(window.__CBP=window.__CBP||[]).push(" עֵצִים הוּא, כָּךְ דַּרְכּוֹ:\",1,0],[2,120,44,13,\"נָטָה קָו. כְּדֶרֶךְ הַנַּגָּרִים, וְעַל פִּי הַקָּו יְתָאֲרֵהוּ בַשֶּׂרֶד, מְיַשֵּׁר אוֹתוֹ בְּמַסּוֹר, שֶׁקּוֹרִין דאלאור״א בלע״ז. יְתָאֲרֵהוּ. יְיַפֵּהוּ:\",2,0],[2,120,44,13,\"יַעֲשֵׂהוּ בַּמַּקְצֻעוֹת. וּמַחְלִיקוֹ בְּרָהִיטְנִי וְאִזְמֵל; מַקְצֻעוֹת תִּרְגֵּם יוֹנָתָן: ״אִיזְמֵלַיָּא״:\",3,0],[2,120,44,13,\"וּבַמְּחוּגָה יְתָאֳרֵהוּ. לְשׁוֹן ״וְתָאַר הַגְּבוּל״ (יהושע טו:ט), אִם בָּא לַעֲשׂוֹת בּוֹ צִיּוּרִים עֲגוּלִים, מְסַבֵּב אוֹתוֹ בַּמְּחוּגָה, קונפ״ש בלע״ז:\",4,0],[2,120,44,13,\"כְּתִפְאֶרֶת אָדָם. הִיא הָאִשָּׁה, שֶׁהִיא תִּפְאֶרֶת בַּעְלָהּ:\",5,0],[2,120,44,14,\"תִּרְזָה וְאַלּוֹן. מִינֵי אִילָנֵי סְרָק:\",1,0],[2,120,44,14,\"וַיְאַמֶּץ לוֹ בַּעֲצֵי יָעַר. עוֹשֶׂה לוֹ חִזּוּקִים, בֵּין לְחִזּוּק בֵּין לְנוֹי, בְּמִינֵי עֵצִים הַמְשֻׁנִּים זֶה מִזֶּה בְּמַרְאֵיהֶן:\",2,0],[2,120,44,14,\"נָטַע אֹרֶן. כְּשֶׁמּוֹצֵא יִחוּר וְנֶטַע הָרָאוּי לְכָךְ, נוֹטְעוֹ לְכָךְ, וְהַגֶּשֶׁם מְגַדְּלוֹ:\",3,0],[2,120,44,14,\"אֹרֶן. לְשׁוֹן ׳נֶטַע יוֹנֵק׳, פלנצו״ן בלע״ז:\",4,0],[2,120,44,15,\"וְהָיָה לְאָדָם לְבָעֵר. וְהָיָה אוֹתוֹ עֵץ מִקְצָתוֹ לְצָרְכֵי אָדָם לְבָעֵר:\",1,0],[2,120,44,15,\"וַיִּקַּח מִן הָעֵצִים. וַיָּחָם גּוּפוֹ לְנֶגְדָּם:\",2,0],[2,120,44,15,\"אַף יַשִּׂיק. מֵהֶם תַּנּוּר וְאוֹפֶה לָחֶם:\",3,0],[2,120,44,15,\"אַף יִפְעַל אֵל. מִן הַנּוֹתָר:\",4,0],[2,120,44,19,\"וְלֹא יָשִׁיב אֶל לִבּוֹ. חֶצְיוֹ שָׂרַפְתִּי בְמוֹ אֵשׁ:\",1,0],[2,120,44,19,\"וְלֹא דַעַת וְלֹא תְבוּנָה בּוֹ לֵאמֹר זֹאת:\",2,0],[2,120,44,19,\"לְבוּל עֵץ. לְרִקְבוֹן עֵץ:\",3,0],[2,120,44,20,\"רֹעֶה אֵפֶר לֵב הוּתַל הִטָּהוּ. לִבּוֹ אֲשֶׁר הוּתַל, הִטָּהוּ לַעֲשׂוֹת לוֹ רוֹעֶה שֶׁל אֵפֶר הַדְּמוּת, שֶׁנִּשְׂרַף חֶצְיוֹ וְנַעֲשָׂה אֵפֶר. הַשּׁוֹטֶה הַזֶּה הָיָה אוֹמֵר שֶׁהוּא לוֹ לְרוֹעֶה וּלְמְפַרְנֵס. דָּבָר אַחֵר: רוֹעֶה אֵפֶר לְשׁוֹן ׳רֵיעוּת׳, עוֹבֵד עֲבוֹדַת אֲחֵרִים וּמְחַבֵּר אֵלָיו עֲבוֹדַת אֲחֵרִים שֶׁהִיא אֵפֶר:\",1,0],[2,120,44,20,\"וְלֹא יַצִּיל. הַנִּתְעֶה אֶת נַפְשׁוֹ לֵאמֹר הֲלוֹא שֶׁקֶר בִּימִינִי, וְיִפָּרֵד מֵעָלָיו:\",2,0],[2,120,44,21,\"לֹא תִנָּשֵׁנִי. לֹא תִּהְיֶה שָׁכוּחַ מִיִּרְאָתִי:\",1,0],[2,120,44,22,\"מָחִיתִי כָעָב פְּשָׁעֶיךָ. בְּמִצְרַיִם וּבַמִּדְבָּר, גַּם עַתָּה שׁוּבָה אֵלַי:\",1,0],[2,120,44,23,\"פִּצְחוּ. לְשׁוֹן פִּתְחוֹן פֶּה:\",1,0],[2,120,44,24,\"וְיֹצֶרְךָ מִבָּטֶן. מֵאָז ״וַיִּתְרוֹצְצוּ הַבָּנִים בְּקִרְבָּהּ״ (בראשית כה:כב) הָיִיתִי לְךָ לְעֶזְרָה וּבְחַרְתִּיךָ:\",1,0],[2,120,44,24,\"נֹטֶה שָׁמַיִם לְבַדִּי:\",2,0],[2,120,44,25,\"מֵפֵר אֹתוֹת בַּדִּים. לְפִי שֶׁאֲנִי נָטִיתִי שָׁמַיִם, לְפִיכָךְ אֲנִי יָכוֹל לְהָפֵר אוֹתָם:\",1,0],[2,120,44,25,\"בַּדִּים. הֵם הַחוֹזִים בַּכּוֹכָבִים עַל יְדֵי אֹתוֹת הַשָּׁמַיִם, וְעַל שֵׁם שֶׁפְּעָמִים הַרְבֵּה שֶׁהֵם מְכַזְּבִים קוֹרִין אוֹתָם ׳בַּדִּים׳, שֶׁאֲנִי מַחֲלִיף הַשָּׂרִים שֶׁלְּמַעְלָה וְטוֹעִין אֵלּוּ הַנִּשְׁאָלִין בָּהֶם. וּלְפִי שֶׁאִצְטַגְנִינֵי בָּבֶל הָיוּ חוֹזִים בַּכּוֹכָבִים, כְּמוֹ שֶׁהוּא אוֹמֵר (ישעיהו מז:יג) ״יַעַמְדוּ נָא וְיוֹשִׁיעוּךְ הוֹבְרֵי שָׁמַיִם״, לְכָךְ הוּא אוֹמֵר שֶׁיָּפֵר אוֹתוֹת בַּדֵּיהֶם, כִּי אֲנִי הוּא שֶׁהֵפַרְתִּי אוֹתוֹת בַּדֵּי מִצְרַיִם:\",2,0],[2,120,44,26,\"מֵקִים דְּבַר עַבְדּוֹ. מֹשֶׁה:\",1,0],[2,120,44,26,\"וַעֲצַת מַלְאָכָיו. מַלְאָךְ אֶחָד אָמַר לְיַעֲקֹב ״יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ״ (בראשית לב:כח), וְקִיַּמְתִּי דְּבָרָיו; אַף כָּאן אֲקַיֵּם עֲצַת נְבִיאַי הָאוֹמֵר עַל יְרוּשָׁלִַם תּוּשָׁב:\",2,0],[2,120,44,27,\"הָאֹמֵר לַצּוּלָה חֳרָבִי. הָאוֹמֵר לְבָבֶל: הִתְיַבְּשִׁי (קהלת רבה יב ח):\",1,0],[2,120,44,27,\"וְנַהֲרֹתַיִךְ אוֹבִישׁ. לְפִי שֶׁהִיא יוֹשֶׁבֶת עַל נְהָרוֹת, מְדַמֶּה הֲרִיגַת אֻכְלוּסֶיהָ לְיֹבֶשׁ נְהָרוֹת:\",2,0],[2,120,44,28,\"רֹעִי. מֶלֶךְ שֶׁלִּי:\",1,0],[2,120,45,1,\"לִמְשִׁיחוֹ. כָּל שֵׁם גְּדֻלָּה קְרוּיָה ׳מְשִׁיחָה׳, כְּמוֹ ״לְךָ נְתַתִּיהָ לְמָשְׁחָה״ (במדבר יח:ח). וְרַבּוֹתֵינוּ אָמְרוּ: לְמֶלֶךְ הַמָּשִׁיחַ אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹבֵל אֲנִי לְךָ עַל כּוֹרֶשׁ, כִּדְאִיתָא בְּמַסֶּכֶת מְגִילָּה (מגילה יב.):\",1,0],[2,120,45,1,\"לְרַד לְפָנָיו גּוֹיִם. לְהַרְקִיעַ וּלְרַדֵּד לְפָנָיו גּוֹיִם, לְרַד – לִשְׁטוֹחַ:\",2,0],[2,120,45,1,\"וּמָתְנֵי מְלָכִים אֲפַתֵּחַ. לְשׁוֹן חַלָּשׁוּת הוּא זֶה וְשֶׁבֶר כֹּחַ, כִּי חֲגוֹרַת מָתְנַיִם הוּא זֵרוּז כֹּחַ, כְּמוֹ ״אֱזָר נָא כְגֶבֶר חֲלָצֶיךָ״ (איוב מ:ז), ״וְאַתָּה תֵאָזֹר מָתְנֶיךָ״ (ירמיהו א:יז). ״וּמְזִיחַ אֲפִיקִים רִפָּה״ (איוב יב:כא) לְשׁוֹן שִׁבְרוֹן כֹּחַ:\",3,0],[2,120,45,1,\"לִפְתֹּחַ לְפָנָיו דַּלְתֵי שַׁעֲרֵי בָּבֶל; שְׁעָרִים הוּא חֲלַל פֶּתַח הַשַּׁעַר, דְּלָתַיִם הֵם הַפּוֹתְחִים וְנוֹעֲלִין בָּהֶן אֶת הַשַּׁעַר:\",4,0],[2,120,45,2,\"וַהֲדוּרִים אֲיַשֵּׁר. תִּרְגֵּם יוֹנָתָן: ״וְשׁוּרַיָּא אֶכְבּוֹשׁ״, כְּמוֹ ״הֲדַר הֲדַרְנָא״ (שבת עז:), עַל שֵׁם שֶׁסּוֹבֶבֶת הַחוֹמָה אֶת הָעִיר. וְיֵשׁ לְפָרֵשׁ הֲדוּרִים: אוֹרְחוֹת מְקֻלְקָלוֹת אֲיַשֵּׁר לְפָנָיו:\",1,0],[2,120,45,3,\"הַקּוֹרֵא בְשִׁמְךָ. עֲדַיִן לֹא נוֹלַדְתָּ, וַאֲנִי קוֹרֵא לְךָ שֵׁם כּוֹרֶשׁ:\",1,0],[2,120,45,4,\"לְמַעַן עַבְדִּי יַעֲקֹב. שֶׁתּוֹצִיאֵהוּ מִגָּלוּת בָּבֶל:\",1,0],[2,120,45,4,\"וְלֹא יְדַעְתָּנִי. לֹא עָשִׂיתָ רְצוֹנִי, כִּי אֲנִי אָמַרְתִּי ״הוּא יִבְנֶה עִירִי״ (ישעיהו מה:יג), וְהוּא כְּשֶׁעָמַד אָמַר ״מִי בָכֶם מִכָּל עַמּוֹ״ (עזרא א:ג), רְשׁוּת נָתַן לָהֶם לֵילֵךְ, וְכָל הַטֹּרַח פָּרַק מֵעַל צַוָּארוֹ:\",2,0],[2,120,45,7,\"יוֹצֵר אוֹר. לַצַּדִּיקִים:\",1,0],[2,120,45,7,\"וּבוֹרֵא חֹשֶׁךְ. לְבָבֶל, וְכֵן עֹשֶׂה שָׁלוֹם וּבוֹרֵא רָע:\",2,0],[2,120,45,8,\"הַרְעִיפוּ שָׁמַיִם וְגוֹ׳. ״צֶדֶק״ הָאָמוּר בַּמִּקְרָא מוּסָב עַל הַנֶּזֶל וְעַל הָרְעִיפָה. הַרְעִיפוּ שָׁמַיִם צֶדֶק וּשְׁחָקִים יִזְּלוּ צֶדֶק, כְּלוֹמַר: מֵאִתִּי יָבֹא הַצֶּדֶק לְהֵיטִיב לָהֶם מִן הַשָּׁמַיִם:\",1,0],[2,120,45,8,\"בְּרָאתִיו. בָּרָאתִי אֶת הַדָּבָר הַזֶּה:\",2,0],[2,120,45,9,\"הוֹי רָב אֶת יֹצְרוֹ. נִתְנַבֵּא יְשַׁעְיָה עַל חֲבַקּוּק, שֶׁעָתִיד לַעֲמוֹד וְלִקְרוֹא תִּגָּר עַל אֹרֶךְ הַצְלָחָתוֹ שֶׁל נְבוּכַדְנֶצַּר: ״עַד אָנָה ה׳ שִׁוַּעְתִּי וְגוֹ׳״ (חבקוק א:ב), ״וְתַעֲשֶׂה אָדָם כִּדְגֵי הַיָּם״ (חבקוק א:יד). וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לִישַׁעְיָה: לָמָּה זֶה בָּא לָרִיב אִתִּי, סָבוּר הוּא שֶׁאֵינִי שָׂם עַל לֵב לְהוֹשִׁיעַ אֶת עַמִּי לְעֵת מְלֹאת אֲשֶׁר ״תִּרְצֶה הָאָרֶץ אֶת שַׁבְּתוֹתֶיהָ״ (ויקרא כו:לד)?\",1,0],[2,120,45,9,\"אֵין יָדַיִם לוֹ. אֵין מָקוֹם לוֹ:\",2,0],[2,120,45,10,\"הוֹי אֹמֵר לְאָב מַה תּוֹלִיד. כָּסָבוּר הוּא לִהְיוֹת מְרַחֵם עַל הַבֵּן יוֹתֵר מֵאָבִיו. דָּבָר אַחֵר: הוֹי בֵּן הָאוֹמֵר לְאָב ״לָמָּה הוֹלַדְתָּ?״ דּוֹמֶה הוּא לָזֶה שֶׁהוּא רָב אֶת יֹצְרוֹ:\",1,0],[2,120,45,11,\"הָאֹתִיּוֹת שְׁאָלוּנִי וגו׳. ה״א נְקוּדָה קָמַץ, לָמַדְתָּ שֶׁאֵינָהּ תְּמִיהָה. וְכֵן פֵּרְשׁוּ: אִם בָּאתֶם לִשְׁאוֹל לִי, אַתֶּם הַנְּבִיאִים, שְׁאָלוּנִי עַל אוֹתוֹת שָׁמַיִם וּמוֹפְתִים אֲשֶׁר אַתֶּם רוֹאִים נוֹלָדִים בָּאָרֶץ, עֲלֵיהֶם הֱיוּ שׁוֹאֲלִים אוֹתִי מַה הֵם, אֲבָל עַל בָּנַי וְעַל פֹּעַל יָדַי יְשָׁרִים, שֶׁבִּשְׁבִילָם יָצַרְתִּי אֶת הַכֹּל, אַתֶּם בָּאִים לְצַוּוֹתִי וְלִקְרֹא לְפָנַי תִּגָּר?\",1,0],[2,120,45,11,\"תְּצַוֻּנִי. תָּמוֹהַּ הוּא, וְכִי עֲלֵיכֶם לְצַוּוֹת עַל בָּנַי? אֲנִי כְּבָר בָּרָאתִי לָהֶם הַיְּשׁוּעָה בְּמַחֲשָׁבָה שֶׁעָלְתָה לְפָנַי. כֵּיצַד? ״אָנֹכִי הַעִירוֹתִיהוּ בְצֶדֶק״ (ישעיהו מה:יג) עַל כּוֹרֶשׁ הוּא אוֹמֵר:\",2,0],[2,120,45,12,\"אָנֹכִי עָשִׂיתִי אֶרֶץ, וּנְתַתִּיהָ לַאֲשֶׁר יָשָׁר בְּעֵינַי:\",1,0],[2,120,45,14,\"יְגִיעַ מִצְרַיִם וְגוֹ׳. הֲרֵי הוֹדַעְתִּי אֶתְכֶם בַּמֶּה אוֹשִׁיעַ אֶת בָּנַי מִיַּד בָּבֶל, כִּי כּוֹרֶשׁ לְכָךְ הֶעִירוֹתִהוּ בְּצִדְקִי. וְעוֹד אֲנִי מוֹדִיעֲכֶם תְּשׁוּעַת סַנְחֵרִיב בִּימֵי חִזְקִיָּהוּ, כַּאֲשֶׁר יָשׁוּב (ישעיהו לו:לו) מֵעַל תִּרְהָקָה מֶלֶךְ כּוּשׁ יָבֹא לִירוּשָׁלַיִם, וְחֶמְדַּת כָּל אוֹצְרוֹת כּוּשׁ וּמִצְרַיִם שֶׁיֵּלְכוּ לַעֲזוֹר אֶת כּוּשׁ בְּיָדוֹ, וְיָבֹא עִם אוֹתוֹ הַשָּׁלָל וְיִפּוֹל בִּירוּשָׁלַיִם, וְחִזְקִיָּהוּ וְעַמּוֹ יָבֹזּוּ אֶת הַכֹּל. כֵּן מְפוֹרָשׁ בְּסֵדֶר עוֹלָם (סדר עולם רבה כג) שֶׁעַל סַנְחֵרִיב נֶאֱמַר:\",1,0],[2,120,45,14,\"אַנְשֵׁי מִדָּה. גּוֹבְהֵי קוֹמָה:\",2,0],[2,120,45,14,\"עָלַיִךְ. יְרוּשָׁלַיִם:\",3,0],[2,120,45,14,\"בַּזִּקִּים יַעֲבֹרוּ. שֶׁהֱבִיאָם שָׁם סַנְחֵרִיב שְׁלוּלִים בְּקוֹלָרִים, וּלְאַחַר מַפַּלְתּוֹ עָמַד חִזְקִיָּהוּ וּפָטַר אֶת כָּל הַשְּׁבוּיִים, וְנִתְגַּיְּרוּ וְהִכִּירוּ מַלְכוּת שָׁמַיִם:\",4,0],[2,120,45,14,\"אַךְ בָּךְ אֵל. יְהוּ מוֹדִים שֶׁאֵין אֱלוֹהַּ אֶלָּא ה׳ לְבַדּוֹ:\",5,0],[2,120,45,15,\"אָכֵן אַתָּה אֵל מִסְתַּתֵּר וְכֵן יֹאמְרוּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא: אָכֵן הֲבִינוֹתָנוּ, כִּי לִגְבּוֹת חוֹבוֹתֵיהֶן שֶׁל עַמְּךָ אַתָּה מִסְתַּתֵּר מִלְּהַרְאוֹת נִצְחוֹנְךָ, כִּבְיָכוֹל אֵין בְּךָ יְכֹלֶת, וּבְהִתְעוֹרֵר רַחֲמֶיךָ אַתָּה אֱלֹהֵי יִשְׂרָאֵל מוֹשִׁיעַ. כָּךְ מְפוֹרָשׁ בַּמְּכִילְתָּא (מכילתא בשלח ויהי א):\",1,0],[2,120,45,16,\"חָרָשֵׁי צִירִים. אֻמָּנֵי צִיּוּרִים שֶׁל פְּסִילִים שֶׁל עֲבוֹדָה זָרָה וּמַזָּלוֹת:\",1,0],[2,120,45,18,\"לֹא תֹהוּ בְרָאָהּ. כִּי לָשֶׁבֶת יְצָרָהּ:\",1,0],[2,120,45,19,\"לֹא בַסֵּתֶר דִּבַּרְתִּי. כְּשֶׁנָּתַתִּי אֶת הַתּוֹרָה, וְלֹא אָמַרְתִּי עַל תֹּהוּ עַל חִנָּם: לְזֶרַע יַעֲקֹב בַּקְּשׁוּנִי, כִּי אִם לְקַבֵּל שָׂכָר גָּדוֹל:\",1,0],[2,120,45,19,\"אֲנִי ה׳ דֹּבֵר צֶדֶק. מֵאַחַר שֶׁפָּתַחְתִּי לָהֶם בִּדְבַר צִדְקִי לְהוֹדִיעָם מַתַּן שְׂכָרָן, אַחַר כֵּן הִגַּדְתִּי לָהֶם מֵישָׁרִים חֻקַּי וְתוֹרָתִי, שֶׁקּוֹדֶם מַתַּן תּוֹרָה נֶאֱמַר לָהֶם (שמות יט:ה) ״וְעַתָּה אִם שָׁמוֹעַ וְגוֹ׳ וִהְיִיתֶם לִי סְגֻלָּה וּמַמְלֶכֶת כֹּהֲנִים וְגוֹ׳״:\",2,0],[2,120,45,20,\"הִתְנַגְּשׁוּ. לְשׁוֹן ׳הַגָּשָׁה׳, וְהַנוּ״ן טְפֵלָה בּוֹ כַּאֲשֶׁר יֹאמַר ׳הִתְנַגְּפוּ׳:\",1,0],[2,120,45,20,\"פְּלִיטֵי הַגּוֹיִם. אֲשֶׁר נִשְׁאֲרוּ מֵחַרְבּוֹ שֶׁל נְבוּכַדְנֶצַּר:\",2,0],[2,120,45,20,\"לֹא יָדְעוּ הַנֹּשְׂאִים אֶת עֵץ פִּסְלָם. לְהָבִין דַּעַת:\",3,0],[2,120,45,21,\"הִשְׁמִיעַ זֹאת מִקֶּדֶם. מִי בִּפְסִילֵיכֶם אֲשֶׁר הִשְׁמִיעַ מִקֶּדֶם לְהָבִיא אֱלֹהֵיכֶם תְּשׁוּעָה, אִישׁ אִישׁ לְעוֹבְדָיו?\",1,0],[2,120,45,21,\"הֲלֹא אֲנִי ה׳ וְאֵין עוֹד. שֶׁאֲנִי מוֹדִיעַ מַה אֲנִי עָתִיד לַעֲשׂוֹת לְעַמִּי, וַאֲקַיֵּם דְּבָרִי:\",2,0],[2,120,45,22,\"פְּנוּ אֵלַי. וְהַנִּיחוּ פְּסִילֵיכֶם, כָּל אַפְסֵי אָרֶץ, וּבְכָךְ תִּוָּשְׁעוּ:\",1,0],[2,120,45,23,\"בִּי נִשְׁבַּעְתִּי. וְיָצָא מִפִּי צְדָקָה לְקַבֵּל כָּל הַשָּׁבִים אֵלַי, דָּבָר דִּבַּרְתִּי וְלֹא יָשׁוּב. וּמַהוּ הַצְּדָקָה אֲשֶׁר יָצְאָת מִפִּי? כִּי לִי תִּכְרַע כָּל בֶּרֶךְ, וַאֲנִי אֲקַבְּלֵם, כְּעִנְיָן שֶׁנֶּאֱמַר ״כִּי אָז אֶהְפֹּךְ אֶל עַמִּים וְגוֹ׳״ (צפניה ג:ט):\",1,0],[2,120,45,24,\"אַךְ בַּה׳ לִי אָמַר. הַמִּקְרָא זֶה מְסֹרָס, וְכֵן פִּתְרוֹנוֹ: אַךְ לִי בַּה׳ אָמַר צְדָקוֹת וָעֹז. אַף עַל פִּי שֶׁכָּל הַגּוֹיִם יִשְׁתַּחֲווּ לְפָנָיו, אַךְ לִי לְבַדִּי, כְּנֶסֶת יִשְׂרָאֵל, בַּה׳ הֻבְטַח לִי צְדָקוֹת וָעֹז, וְלֹא יָבוֹאוּ מַכְחִישֵׁי תּוֹרָה לְחַלֵּל כְּבוֹדִי:\",1,0],[2,120,45,24,\"עָדָיו יָבוֹא וְיֵבֹשׁוּ וגו׳. כָּל הַנֶּחֱרִים בְּהַקָּדוֹשׁ בָּרוּךְ הוּא יָבוֹאוּ עָדָיו לְהִתְחָרֵט עַל מַה שֶּׁעָשׂוּ בְּחַיֵּיהֶם וְיֵבֹשׁוּ:\",2,0],[2,120,45,24,\"הַנֶּחֱרִים. הַמִּתְגָּרִים:\",3,0],[2,120,45,25,\"בַּה׳ יִצְדְּקוּ וְיִתְהַלְלוּ. בְּהַבְטָחַת מִשְׁעַן אַהֲבָתוֹ יִמְצְאוּ צְדָקָה וְיִתְפָּאֲרוּ בְּמָעוֹז:\",1,0],[2,120,45,25,\"וְיִתְהַלְלוּ. פורוונטי״ר בלע״ז:\",2,0],[2,120,46,1,\"כָּרַע בֵּל קֹרֵס נְבוֹ. אֱלָהוּתֵיהֶם שֶׁל בָּבֶל כָּרְעוּ קָרְסוּ, לְשׁוֹן שְׂחוֹק שֶׁל עֲבוֹדָה זָרָה הוּא, כְּמִי שֶׁיֵּשׁ לוֹ חֹלִי מֵעַיִם וְאֵינוֹ מַסְפִּיק לֵישֵׁב עַל מוֹשַׁב בֵּית הַכִּסֵּא עַד שֶׁהוּא נִתְרָז:\",1,0],[2,120,46,1,\"כָּרַע בֵּל קֹרֵס נְבוֹ. אישקרופי״ר בֵּל, קונקיא״ה נְבוֹ. כָּךְ שָׁמַעְתִּי מִשְּׁמוֹ שֶׁל רַבֵּנוּ גֵּרְשׁוֹם מְאוֹר הַגּוֹלָה:\",2,0],[2,120,46,1,\"הָיוּ עֲצַבֵּיהֶם. צַלְמֵי צוּרָתָם שֶׁל בֵּל וּנְבוֹ הָיוּ לַחַיָּה וְלַבְּהֵמָה, נִדְמוּ לִהְיוֹת כְּחַיָּה וְכִבְהֵמָה, שֶׁמְּזַהֲמִין וּמְלַכְלְכִין עַצְמָן בְּרֵעִי שֶׁלָּהֶם:\",3,0],[2,120,46,1,\"נְשֻׂאֹתֵיכֶם עֲמוּסוֹת מַשָּׂא. רְעִי שֶׁבִּמְעֵיהֶם כְּבֵדוֹת הֵם לַעֲמוֹס כְּמַשָּׂא לְאָדָם עָיֵף, לְפִיכָךְ קָרְסוּ כָּרְעוּ יַחְדָּו, הַקְּרִיסָה עִם הַכְּרִיעָה:\",4,0],[2,120,46,2,\"לֹא יָכְלוּ מַלֵּט מַשָּׂא. לְהַפְלִיט הַצּוֹאָה שֶׁבְּמֵעֵיהֶם כִּשְׁאָר הַמּוֹצִיאִין כַּהֹגֶן:\",1,0],[2,120,46,2,\"מַלֵּט. לְשׁוֹן הוֹצָאָה מִמָּקוֹם בָּלוּעַ, וְכֵן (ישעיהו לד:טו) ״שָׁמָּה קִנְּנָה קִפּוֹז וַתְּמַלֵּט״, הוֹצִיאָה בֵּיצָתָהּ, וְכֵן (ישעיהו סו:ז) ״וְהִמְלִיטָה זָכָר״. וְיוֹנָתָן לֹא תִּרְגֵּם כֵּן הַמִּקְרָאוֹת הַלָּלוּ:\",2,0],[2,120,46,3,\"הָעֲמֻסִים מִנִּי בֶטֶן. מֵאָז נוֹלַדְתֶּם בְּבֵית לָבָן הָאֲרַמִּי, עָמַסְתִּי אֶתְכֶם עַל זְרוֹעוֹתַי, כִּי מֵאָז עָמְדוּ עֲלֵיכֶם עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת בְּכָל דּוֹר וָדוֹר, וְלֹא כְּעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁהָיוּ עוֹמְסִים וְנוֹשְׂאִים אֶת אֱלֹהֵיהֶם כְּמוֹ שֶׁאָמוּר לְמַעְלָה, אֲבָל אַתֶּם עֲמוּסִים וּנְשׂוּאִים בִּזְרוֹעוֹתַי:\",1,0],[2,120,46,4,\"וְעַד זִקְנָה. אֲשֶׁר זְקַנְתֶּם וְכָלָה כֹּחֲכֶם, שֶׁאֵין לָכֶם זְכוּת, אֲנִי הוּא בְּרַחֲמַי וּבְמִדַּת טוּבִי לְהוֹשִׁיעֲכֶם וְלַעֲמֹס וְלָשֵׂאת לְמַלֵּט. לְפִי שֶׁאָמַר עַל יִרְאָתָם שֶׁהִיא נִסְבֶּלֶת, וְגַם מַשָּׂאָהּ אֵינָהּ יְכוֹלָה לְמַלֵּט, אָמַר: ״אֲנִי הַסּוֹבֵל אֲחֵרִים וְאֶת מַשָּׂאָם אֲמַלֵּט״:\",1,0],[2,120,46,5,\"וְתַמְשִׁלוּנִי. כְּמוֹ ״וָאֶתְמַשֵּׁל כֶּעָפָר וָאֵפֶר״ (איוב ל:יט), לְשׁוֹן ׳דִּמְיוֹן׳:\",1,0],[2,120,46,5,\"וְנִדְמֶה. וְנִהְיֶה אֲנִי וְהוּא דּוֹמִין זֶה לָזֶה:\",2,0],[2,120,46,6,\"הַזָּלִים זָהָב מִכִּיס. לְשׁוֹן ״יִזְּלוּ מָיִם״ (תהלים קמז:יח):\",1,0],[2,120,46,6,\"בַּקָּנֶה יִשְׁקֹלוּ. הוּא קְנֵה הַמֹּאזְנִים, שֶׁקּוֹרִין פליי״ל בלע״ז:\",2,0],[2,120,46,8,\"זִכְרוּ זֹאת. אֲשֶׁר אֲנִי חָפֵץ לוֹמַר:\",1,0],[2,120,46,8,\"וְהִתְאֹשָׁשׁוּ. וְהִתְחַזְּקוּ, כְּמוֹ ״לַאֲשִׁישֵׁי קִיר חֲרֶשֶׂת״ (ישעיהו טז:ז):\",2,0],[2,120,46,8,\"הָשִׁיבוּ פוֹשְׁעִים עַל לֵב. וּמָה אֲנִי אוֹמֵר לָכֶם לִזְכּוֹר וּלְהָשִׁיב עַל לֵב?\",3,0],[2,120,46,9,\"זִכְרוּ רִאשֹׁנוֹת מֵעוֹלָם. אֲשֶׁר רְאִיתֶם כִּי אָנֹכִי אֵל וְאֵין עוֹד, אָנֹכִי אֱלֹהִים וְאֶפֶס כָּמוֹנִי:\",1,0],[2,120,46,10,\"מַגִּיד מֵרֵאשִׁית אַחֲרִית. גָּלוּת מִצְרַיִם וּגְאֻלָּתָהּ הוֹדַעְתִּי בֵּין הַבְּתָרִים, לִפְנֵי הֱיוֹתָהּ:\",1,0],[2,120,46,11,\"קוֹרֵא מִמִּזְרָח עַיִט. מֵאֶרֶץ אֲרָם, שֶׁהִיא בַּמִּזְרָח, קָרָאתִי לִי אֶת אַבְרָהָם לִהְיוֹת נִמְלָךְ בַּעֲצָתִי. עַיִט – כְּמוֹ ״הֵיתִיב עֵיטָא וְטַעַם״ (דניאל ב:יד), ״אִתְיָעֲטוּ כָּל סָרְכֵי מַלְכוּתָא״ (דניאל ו:ח). וְגַם יֵשׁ לְפוֹתְרוֹ בִּלְשׁוֹן עוֹף: קְרָאתִי לְמַהֵר אַחֲרַי כְּעוֹף הַפּוֹרֵחַ וְנוֹדֵד מִמְּקוֹמוֹ:\",1,0],[2,120,46,11,\"מֶרְחָק. קָרָאתִי לְאִישׁ עֲצָתִי, וְעִמּוֹ יָעַצְתִּי בֵּין הַבְּתָרִים ד׳ גָּלֻיּוֹת, כְּמוֹ שֶׁמְּפוֹרָשׁ בִּבְרֵאשִׁית רַבָּה (בראשית רבה מד יז) ״וְהִנֵּה אֵימָה חֲשֵׁכָה גְדוֹלָה וְגוֹ׳״ (בראשית טו:יב):\",2,0],[2,120,46,11,\"אַף דִּבַּרְתִּי. עִמּוֹ הַגָּלֻיּוֹת וּגְאֻלָּתָן, אַף אֲבִיאֶנָּה:\",3,0],[2,120,46,12,\"אַבִּירֵי לֵב. אֲשֶׁר אִמַּצְתֶּם לְבַבְכֶם וְנִדְבַּקְתֶּם בִּי:\",1,0],[2,120,46,12,\"הָרְחוֹקִים מִצְּדָקָה. אֲשֶׁר אָרְכוּ לָכֶם הַיָּמִים, וְלֹא הֶרְאֵיתִי אֶתְכֶם צִדְקָתִי לִגְאוֹל:\",2,0],[2,120,46,13,\"קֵרַבְתִּי צִדְקָתִי. מֵעַתָּה וְלֹא תִרְחָק:\",1,0],[2,120,47,1,\"אֵין כִּסֵּא. אֵין מַלְכוּת:\",1,0],[2,120,47,1,\"כִּי לֹא תוֹסִיפִי. שֶׁיִּקְרְאוּ לָךְ עוֹד רַכָּה וַעֲנֻגָּה:\",2,0],[2,120,47,2,\"קְחִי רֵחַיִם. הִיא עֲבוֹדָה קָשָׁה, כְּלוֹמַר: הִשְׁתַּעְבְּדִי מֵעַתָּה לְמַלְכֵי מָדַי וּפָרַס. דָּבָר אַחֵר: וְטַחֲנִי קָמַח לְצֵדָה לְדֶרֶךְ גָּלוּתֵךְ:\",1,0],[2,120,47,2,\"גַּלִּי צַמָּתֵךְ. זְרוֹעֵךְ וְשׁוֹקַיִךְ, דָּבָר הַמְצֻמָּת וְקָשׁוּר וּמְכֻסֶּה:\",2,0],[2,120,47,2,\"חֶשְׂפִּי שֹׁבֶל. גַּלִּי הַשְּׁבִילִים מִן הַמַּיִם שֶׁעֲלֵיהֶם, כִּי דֶּרֶךְ שָׁם תֵּצְאִי בַּגּוֹלָה. אוֹ גַּלִּי שׁוֹקֵךְ וְעִבְרִי נְהָרוֹת:\",3,0],[2,120,47,3,\"וְלֹא אֶפְגַּע אָדָם. לֹא אֲבַקֵּשׁ פְּנֵי אָדָם לָקַחַת נִקְמָתִי:\",1,0],[2,120,47,4,\"גֹּאֲלֵנוּ ה׳ צְבָאוֹת שְׁמוֹ. הַנָּבִיא אוֹמֵר: כָּל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לְגָאֳלֵנוּ מִשָּׁם:\",1,0],[2,120,47,6,\"עַל זָקֵן הִכְבַּדְתְּ עֻלֵּךְ. עַל הַזְּקֵנִים, שֶׁלֹּא הָיוּ יְכוֹלִים לִסְבּוֹל טֹרַח, הִכְבַּדְתְּ עֻלֵּךְ:\",1,0],[2,120,47,7,\"וַתֹּאמְרִי בִּלְבָבֵךְ לְעוֹלָם אֶהְיֶה גְבָרֶת, וְאֵין פֻּרְעָנוּת בָּא עָלַי, וְהַדָּבָר הַזֶּה הִשִּׂיאָךְ, עַד לֹא שַׂמְתְּ אֵלֶּה הַמַּכּוֹת שֶׁיָּבוֹאוּ עָלַיִךְ אֶל לִבֵּךְ, וְלֹא זָכַרְתְּ אַחֲרִיתָהּ שֶׁל רָעָתֵךְ שֶׁעָשִׂית:\",1,0],[2,120,47,8,\"עֲדִינָה. תִּרְגֵּם יוֹנָתָן: ״פְּנַקְתָּא״:\",1,0],[2,120,47,8,\"וְאַפְסִי עוֹד. וְ״אֶפֶס מֵאוֹתִי״ (ישעיהו נד:טו) כְּמוֹ ׳אֵין זוּלָתִי׳:\",2,0],[2,120,47,9,\"שְׁתֵּי אֵלֶּה. שֶׁאָמַרְתְּ, שֶׁלֹּא תֵשְׁבִי אַלְמָנָה, וְלֹא תֵדְעִי שְׁכוֹל, תָּבֹאנָה לָךְ פִּתְאוֹם:\",1,0],[2,120,47,9,\"שְׁכוֹל. מִיּוֹשְׁבַיִךְ:\",2,0],[2,120,47,9,\"וְאַלְמֹן. מִמַּלְכֵּךְ; כָּל קְבוּרַת בָּנִים וְגָלוּת בְּנֵי הָאָרֶץ קָרוּי ׳שְׁכוֹל׳:\",3,0],[2,120,47,9,\"כְּתֻמָּם. כֻּלָּם שְׁלֵמִים בִּגְזֵרָתָם, הַשִּׁכּוּל וְהָאַלְמָנוּת:\",4,0],[2,120,47,9,\"חֲבָרַיִךְ. לְשׁוֹן כְּשָׁפִים, כְּמוֹ ״וְחֹבֵר חָבֶר״ (דברים יח:יא):\",5,0],[2,120,47,10,\"חָכְמָתֵךְ וְדַעְתֵּךְ. חָכְמָתֵךְ וְרוֹעַ לְבָבֵךְ הִיא שׁוֹבְבָתֶּךְ, הָפְכוּ לִבֵּךְ לִהְיוֹת שׁוֹבְבָה, אינווייז״א בלע״ז, שִׁבְּבוּךְ מִדֶּרֶךְ שְׁאָר הַבְּרִיּוֹת:\",1,0],[2,120,47,11,\"לֹא תֵדְעִי שַׁחְרָהּ. ״לֹא תֵדְעִין לְמִבְעֵי עֲלַהּ״ (תרגום יונתן), אֶת פְּנֵי מִי תְשַׁחֲרִי לְמַלְּטֵךְ מִמֶּנָּה?\",1,0],[2,120,47,11,\"כַּפְּרָהּ. לְקַנְּחָהּ וּלְהַעֲבִירָהּ, וְזֶהוּ כָּל לְשׁוֹן ׳כַּפָּרָה׳, הוּא לְשׁוֹן קִנּוּחַ וְסִלּוּק:\",2,0],[2,120,47,12,\"עִמְדִי נָא. הִתְחַזְּקִי נָא:\",1,0],[2,120,47,12,\"אוּלַי תַּעֲרוֹצִי. ״מֵאִים תִּכְלִין לְמִיתְקַף״ (תרגום יונתן):\",2,0],[2,120,47,13,\"הֹבְרֵי שָׁמַיִם. יוֹנָתָן תִּרְגֵּם כְּמוֹ צוֹפֵי שָׁמַיִם״ דְּמִסְכַּן לְמַזָּלַת שְׁמַיָּא״, דִּמָּהוּ לְ״בָּרָה כַחַמָּה״ (שיר השירים ו:י) וּלְ״בָּרוּר מִלֵּלוּ״ (איוב לג:ג), וְכֵן חִבְּרוֹ מְנַחֵם עִמָּהֶם, מְבָרְרֵי הֲלִיכַת הַמַּזָּלוֹת, וְכֹה פִּתְרוֹנוֹ: יַעַן אֲשֶׁר לֹא יוּכְלוּן הַקּוֹסְמִים לַעֲמֹד עַל דַּעַת רִגְעֵי הַיּוֹם וְלַיְלָה, עַד בָּרוּר לָהֶם הַשָּׁמַיִם לְטֹהַר. וְגַם מִיכָה אָמַר בִּנְבוּאָה (מיכה ג:ו) ״חָשְׁכָה לָהֶם מִקְּסֹם״, לִמֵּד כִּי בְּיוֹם מַחְשָׁךְ יֵחָתְמוּ הַכּוֹכָבִים וְלֹא יוּכְלוּ לִקְסֹם:\",1,0],[2,120,47,13,\"מוֹדִיעִם לֶחֳדָשִׁים מֵאֲשֶׁר יָבֹאוּ עָלָיִךְ. כִּי בְּהִתְחַדֵּשׁ הַלְּבָנָה רוֹאִים בִּשְׁעַת מוֹלַדְתָּהּ מִקְצָת מִמָּה שֶׁעָתִיד לָבֹא, וְאֵין יוֹדְעִין כָּל הַבֵּרוּר, לְכָךְ נֶאֱמַר ׳מֵאֲשֶׁר׳. וְכֵן הוּא אוֹמֵר בְּמָקוֹם אַחֵר (ישעיהו ח:יט): ״הַמְצַפְצְפִים וְהַמַּהְגִּים״, כְּעוֹפוֹת הַלָּלוּ שֶׁמְּצַפְצְפִין וּמְהַגִּים וְאֵין יוֹדְעִים עַל מָה:\",2,0],[2,120,47,14,\"הִנֵּה הָיוּ חוֹזַיִךְ כְקַשׁ:\",1,0],[2,120,47,14,\"אֵין גַּחֶלֶת לַחְמָם. אֵין שְׁאֵרִית לָהֶם, כְקַשׁ הַזֶּה, שֶׁאֵין בִּדְלִיקָתוֹ גֶּחָלִים לְהִתְחַמֵּם לְאוֹרָם:\",2,0],[2,120,47,15,\"אִישׁ לְעֶבְרוֹ תָּעוּ. אִישׁ לְדַרְכּוֹ, ״אֶל עֵבֶר פָּנָיו״ (יחזקאל א:ט):\",1,0],[2,120,48,1,\"שִׁמְעוּ זֹאת. שְׁנֵי שְׁבָטִים הָעֲתִידִין לָלֶכֶת בַּגּוֹלָה לְבָבֶל:\",1,0],[2,120,48,1,\"בֵּית יַעֲקֹב הַנִּקְרָאִים בְּשֵׁם יִשְׂרָאֵל. הוּא שֵׁבֶט בִּנְיָמִין שֶׁאֵינָם נִקְרָאִים עַל שֵׁבֶט יְהוּדָה, אֶלָּא עַל שֵׁם סְתָם שִׁבְטֵי יִשְׂרָאֵל:\",2,0],[2,120,48,1,\"וּמִמֵּי יְהוּדָה יָצָאוּ. וְשֵׁבֶט יְהוּדָה, שֶׁיָּצְאוּ וְנָזְלוּ מִמֵּי דָּלְיוֹ שֶׁל יְהוּדָה, כְּמָה דְאַתְּ אָמַר ״יִזַּל מַיִם מִדָּלְיָו״ (במדבר כד:ז):\",3,0],[2,120,48,1,\"לֹא בֶאֱמֶת. כְּמוֹ שֶׁאָמַר (ירמיהו ה:ב) ״וְאִם חַי ה׳ יֹאמְרוּ לָכֵן לַשֶּׁקֶר וְגוֹ׳״, כְּלוֹמַר: לֹא הֱיִיתֶם כְּדַי לִגָּאֵל, אֶלָּא עַל כִּי מֵעִיר הַקֹּדֶשׁ נִקְרָאוּ, וְהִיא גָּרְמָה לָהֶם שֶׁלֹּא גָּלוּ עֲשֶׂרֶת הַשְּׁבָטִים בִּימֵי סַנְחֵרִיב בַּחֲלַח וְחָבוֹר (מלכים ב יז:ו), שֶׁאֵין לָהֶם גְּאֻלָה (סנהדרין קי ב):\",4,0],[2,120,48,2,\"וְעַל אֱלֹהֵי יִשְׂרָאֵל נִסְמָכוּ. בִּימֵי חִזְקִיָּהוּ, שֶׁנֶּאֱמַר בּוֹ ״בַּה׳ אֱלֹהֵי יִשְׂרָאֵל בָּטָח״ (מלכים ב יח:ה). הִיא גָּרְמָה לָהֶם שֶׁלֹּא גָּלוּ אֶלָּא בִּימֵי נְבוּכַדְנֶצַּר, שֶׁהִגְלָם לְבָבֶל, וּתְהִי לָהֶם גְּאֻלָּה עַל יְדֵי כּוֹרֶשׁ:\",1,0],[2,120,48,3,\"הָרִאשֹׁנוֹת. שֶׁעָבְרוּ, גְּאֻלַּת מִצְרַיִם וּתְשׁוּעַת חִזְקִיָּהוּ מִיַּד סַנְחֵרִיב:\",1,0],[2,120,48,3,\"מֵאָז הִגַּדְתִּי. מִטֶּרֶם הֱיוֹתָם, וּפִתְאוֹם עֲשִׂיתִים:\",2,0],[2,120,48,3,\"וַתָּבֹאנָה. כְּמוֹ שֶׁהִגַּדְתִּי תְּחִלָּה עַל פִּי נְבִיאַי:\",3,0],[2,120,48,4,\"מִדַּעְתִּי כִּי קָשֶׁה אָתָּה. מֵאֲשֶׁר יָדַעְתִּי אוֹתְךָ כִּי קָשֶׁה אַתָּה, וְאִם יָבֹא הַנֵּס וְלֹא הִגַּדְתִּיו תְּחִלָּה, תֹּאמַר: ״עָצְבִּי עֲשָׂאָם״, וְלֹא מֵאֵת הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם. לְפִיכָךְ אַגִּיד לְךָ מֵאָז בְּטֶרֶם תָּבֹא וְגוֹ׳. מִדַּעְתִּי – מֵ״ם זוֹ מְשַׁמֶּשֶׁת נְתִינַת טַעַם, כְּמוֹ ׳לְפִי שֶׁיָּדַעְתִּי׳. וְדֻגְמָתוֹ: ״כִּי מֵאַהֲבַת ה׳ אֶתְכֶם וּמִשָּׁמְרוֹ אֶת הַשְּׁבוּעָה״ (דברים ז:ח):\",1,0],[2,120,48,6,\"שָׁמַעְתָּ חֲזֵה כֻּלָּהּ. שָׁמַעְתָּ הָרִאשׁוֹנוֹת שֶׁהִגַּדְתִּי, רְאֵה שֶׁבָּאוּ כֻּלָּם:\",1,0],[2,120,48,6,\"וְאַתֶּם הֲלוֹא תַגִּידוּ. וְתָעִידוּנִי אֲשֶׁר לֹא נָפַל דָּבָר:\",2,0],[2,120,48,6,\"הִשְׁמַעְתִּיךָ חֲדָשׁוֹת מֵעַתָּה. עַתָּה אֲנִי חוֹזֵר וּמַשְׁמִיעֲכֶם חֲדָשׁוֹת, שֶׁהֵם חֲדָשׁוֹת לָכֶם, וּלְפָנַי הֵם גְּלוּיוֹת מֵעוֹלָם:\",3,0],[2,120,48,6,\"וּנְצֻרוֹת. וּשְׁמוּרוֹת בְּאוֹצְרוֹתַי, וְאַתָּה לֹא יְדַעְתָּם:\",4,0],[2,120,48,7,\"עַתָּה נִבְרְאוּ וְלֹא מֵאָז הֵם:\",1,0],[2,120,48,7,\"וְלִפְנֵי יוֹם הֱיוֹתָם אֲנִי מַשְׁמִיעֲכֶם:\",2,0],[2,120,48,7,\"וְלֹא שְׁמַעְתָּם. עַד הַיּוֹם. וְלִפְנֵי יוֹם מוּסָב עַל הִשְׁמַעְתִּיךָ הָאָמוּר לְמַעְלָה:\",3,0],[2,120,48,8,\"גַּם לֹא שָׁמַעְתָּ וגו׳. תִּרְגֵּם יוֹנָתָן: ״אַף לָא שְׁמַעְתָּ לְמִילֵי נְבִיָּיא, אַף לָא קַבִּילְתָּא אוּלְפַן אוֹרַיְיתָא, אַף לְפִתְגָמֵי בִּרְכָן וְלָוְוטִין קַיָּמֵי דְּאַקִימִית עִמְכוֹן בְּחוֹרֵב לָא אַרְכִּינְתָּא אוּדְנָךְ״:\",1,0],[2,120,48,8,\"כִּי יָדַעְתִּי בָּגוֹד תִּבְגּוֹד. כְּשֶׁיָּרַדְתִּי לְהַצִּילְךָ מִיַּד מִצְרַיִם, גָּלוּי הָיָה לְפָנַי שֶׁסּוֹפְךָ לִבְגּוֹד, וְאַף עַל פִּי כֵן שָׁמַרְתִּי שְׁבוּעוֹת אָבוֹת. וְזֶהוּ שֶׁנֶּאֱמַר ״רָאֹה רָאִיתִי אֶת עֳנִי עַמִּי״ (שמות ג:ז), שְׁתֵּי רְאִיּוֹת רוֹאֶה אֲנִי שֶׁסּוֹפָן לִבְגּוֹד, וּמִכָּל מָקוֹם רָאִיתִי אֶת עֳנִי עַמִּי. כָּךְ דָּרַשׁ רַבִּי תַּנְחוּמָא:\",2,0],[2,120,48,8,\"וּפֹשֵׁעַ מִבֶּטֶן. מִשֶּׁהָיִיתָ בְּמִצְרַיִם, כְּמוֹ שֶׁמְּפֹרָשׁ (יחזקאל כ:ה-ז) ״וָאִוָּדַע לָהֶם בְּאֶרֶץ מִצְרַיִם וְגוֹ׳ וָאוֹמַר אֲלֵיהֶם וְגוֹ׳״:\",3,0],[2,120,48,9,\"אַאֲרִיךְ אַפִּי. לְשׁוֹן הוֹוֶה הוּא:\",1,0],[2,120,48,9,\"וּתְהִלָּתִי אֶחֱטָם לָךְ. וְזֹאת הִיא תְהִלָּתִי אֲשֶׁר אֶחֱטָם לָךְ, לְשׁוֹן ׳חֹטֶם׳; אֶסְתּוֹם חָטְמִי מִצֵּאת עָשָׁן נְחִירַי וּמִקְּצוֹף עָלֶיךָ, שֶׁהַכּוֹעֵס יוֹצֵא עָשָׁן מִנְּחִירָיו, כְּמָה דְאַתְּ אָמַר ״עָלָה עָשָׁן בְּאַפּוֹ״ (תהילים יח:ט); וְכֵן כָּל ׳חֲרוֹן אַף׳ הוּא לְשׁוֹן חִמּוּם הַחוֹטֶם: ״חָרָה אַפִּי״ (איוב מב:ז), וְכֵן ״וְעַצְמִי חָרָה מִנִּי חֹרֶב״ (איוב ל:ל) – נִחַר חָטְמִי מֵרֹב חִמּוּם:\",2,0],[2,120,48,10,\"וְלֹא בְכָסֶף. וְלֹא עַל יְדֵי אוּר שֶׁל גֵּיהִנֹּם, כְּצוֹרֵף הַכֶּסֶף בָּאוּר:\",1,0],[2,120,48,10,\"בְּחַרְתִּיךָ. בָּחַרְתִּי לְךָ כּוּר עֹנִי, כְּנֶגֶד אוֹר. ׳כּוּר׳ הוּא כְּלִי שֶׁמַּתִּיכִין בּוֹ כֶּסֶף וְזָהָב:\",2,0],[2,120,48,11,\"לְמַעֲנִי. וּלְמַעַן שְׁמִי הַקָּדוֹשׁ:\",1,0],[2,120,48,11,\"כִּי אֵיךְ יֵחָל. אֵיךְ יְחֻלַּל שְׁמִי בְּהַכְרִיתוֹ אֶתְכֶם?\",2,0],[2,120,48,11,\"וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן. שֶׁאוֹיְבַי יֹאמְרוּ יַד גִּלּוּלֵיהֶם רָמָה:\",3,0],[2,120,48,12,\"שְׁמַע אֵלַי יַעֲקֹב. שֵׁם שֶׁקָּרָא לְךָ אָבִיךָ:\",1,0],[2,120,48,12,\"וְיִשְׂרָאֵל מְקֹרָאִי. מֵאִתִּי נִקְרֵאתָ יִשְׂרָאֵל (בראשית לב:כט), וְיוֹנָתָן תִּרְגֵּם: ״וְיִשְׂרָאֵל מְזֻמָּנִי״:\",2,0],[2,120,48,14,\"ה׳ אֲהֵבוֹ. לָזֶה שֶׁיַּעֲשֶׂה חֶפְצוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּבָבֶל:\",1,0],[2,120,48,14,\"וּזְרֹעוֹ יֵרָאֶה בְּאֶרֶץ כַּשְׂדִּים, וְעַל כּוֹרֶשׁ אָמַר כֵּן:\",2,0],[2,120,48,15,\"אֲנִי. גָּאַלְתִּי יִשְׂרָאֵל מִמִּצְרַיִם, וַאֲנִי אֶגְאַל כָּל יִשְׂרָאֵל מִגָּלוּת אַחֲרוֹן וּמֵאַרְבַּע כַּנְפוֹת הָאָרֶץ:\",1,0],[2,120,48,15,\"אַף קְרָאתִיו. לְכוֹרֶשׁ, וְיוֹנָתָן תִּרְגֵּם ה׳ אַהֲבוֹ לְיִשְׂרָאֵל, אַף קְרָאתִיו לְאַבְרָהָם, וּקְרִיאָה זוֹ לְשׁוֹן ׳גִּדּוּל׳ לִהְיוֹת מִקּוֹרְאַי, כְּמוֹ ״אֵלֶּה קְרוּאֵי הָעֵדָה״ (במדבר א:טז):\",2,0],[2,120,48,16,\"מֵעֵת הֱיוֹתָהּ שָׁם אָנִי. ״מֵעִידָּן דְּאִתְפָּרְשׁוּ עַמְמַיָּא מִדַּחַלְתִּי, תַּמָּן אֲנָא קְרִיבְתֵּיהּ לְאַבְרָהָם אֲבוּכוֹן לְפוּלְחָנִי״ (תרגום יונתן):\",1,0],[2,120,48,16,\"וְעַתָּה ה׳ אֱלֹהִים שְׁלָחַנִי וְרוּחוֹ. ״אָמַר נָבִיא: וּכְעַן ה׳ אֱלֹהִים שְׁלָחַנִי וּמֵימְרֵיהּ״. עֵרוּבֵי דְבָרִים – מִי שֶׁאָמַר זֶה לֹא אָמַר זֶה. וּמִדְרַשׁ אַגָּדָה רַבִּי תַּנְחוּמָא (תנחומא יתרו כא) פֵּרֵשׁ: שִׁמְעוּ זֹאת – תּוֹרַת מֹשֶׁה שֶׁנֶּאֱמַר בָּהּ ״זֹאת הַתּוֹרָה״. לֹא מֵרֹאשׁ בַּסֵּתֶר דִּבַּרְתִּי – בְּסִינַי, וְהַנָּבִיא אוֹמֵר: מֵעֵת הֱיוֹתָהּ לְאוֹתוֹ דָבָר שֶׁהוּא אוֹמֵר שָׁם אָנִי. וְלָמַדְנוּ מִכָּאן שֶׁכָּל הַנְּבִיאִים עָמְדוּ בְּסִינַי, וְעַתָּה שְׁלָחַנִי לְהִנָּבֵא אֲלֵיהֶם. וְאַף לָשׁוֹן זֶה יֶשְׁנוֹ עֵרוּבֵי דְבָרִים: לֹא מֵרֹאשׁ בַּסֵּתֶר דִּבַּרְתִּי אָמְרָה שְׁכִינָה, מֵעֵת הֱיוֹתָהּ שָׁם אָנִי אוֹמֵר הַנָּבִיא. וְיֵשׁ לִפְתּוֹר שֶׁלֹּא יְהוּ עֵרוּבֵי דְבָרִים: קִרְבוּ אֵלַי שִׁמְעוּ זֹאת שֶׁאֲנִי מִתְנַבֵּא לָכֶם עַל מַפֶּלֶת בָּבֶל וּגְאֻלַּתְכֶם, לֹא מֵרֹאשׁ בַּסֵּתֶר דִּבַּרְתִּי אוֹתָהּ, מֵעֵת הֱיוֹתָהּ שֶׁגָּזַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַהֲבִיאָהּ שָׁם הָיִיתִי. לוֹמֵד שֶׁמִּשְּׁעַת הַגְּזֵרָה הַקָּדוֹשׁ בָּרוּךְ הוּא מַעֲמִיד הַנָּבִיא שֶׁעָתִיד לְהִנָּבֵא עַל הַדָּבָר בְּסוֹף פַּמַלְיָא שֶׁל מַעְלָה, וְאַף עַל פִּי שֶׁעֲדַיִן אֵינוֹ נוֹצָר:\",2,0],[2,120,48,19,\"כִּמְעֹתָיו. שֶׁל יָם, כְּדָגֵי הַיָּם לָרֹב:\",1,0],[2,120,48,22,\"לָרְשָׁעִים. לִנְבוּכַדְנֶצַּר וְזַרְעוֹ׃\",1,0],[2,120,49,1,\"מִבֶּטֶן קְרָאָנִי. מִשֶּׁאֲנִי בַּבֶּטֶן עָלְתָה לְפָנָיו בְּמַחֲשָׁבָה לִהְיוֹת שְׁמִי יְשַׁעְיָה, לְהִנָּבֵא יְשׁוּעוֹת וְנֶחָמוֹת:\",1,0],[2,120,49,2,\"וַיָּשֶׂם פִּי כְּחֶרֶב חַדָּה. לְהוֹכִיחַ אֶת הָרְשָׁעִים וּלְהִתְנַבְּאוֹת עֲלֵיהֶם פֻּרְעָנוּת:\",1,0],[2,120,49,2,\"בְּצֵל יָדוֹ הֶחְבִּיאָנִי. שֶׁלֹּא יוּכְלוּ לְהָרַע לִי:\",2,0],[2,120,49,2,\"לְחֵץ בָּרוּר. מְמוֹרָט, קלי״ר בלע״ז:\",3,0],[2,120,49,2,\"בְּאַשְׁפָּתוֹ. כְּלִי נַרְתֵּק הַחִצִּים, שֶׁקּוֹרִין קוייכר״א בלע״ז:\",4,0],[2,120,49,4,\"וַאֲנִי אָמַרְתִּי לְרִיק יָגַעְתִּי. כְּשֶׁרָאִיתִי שֶׁאֲנִי מוֹכִיחָם וְאֵינָם שׁוֹמְעִים:\",1,0],[2,120,49,4,\"אָכֵן מִשְׁפָּטִי אֶת ה׳. הוּא יוֹדֵעַ שֶׁאֵינָהּ מֵאִתִּי, אֶלָּא מֵאִתָּם:\",2,0],[2,120,49,5,\"לוֹ יֵאָסֵף. אֵלָיו יָשׁוּב בִּתְשׁוּבָה:\",1,0],[2,120,49,6,\"נָקֵל מִהְיוֹתְךָ וגו׳. מַתָּנָה קְטַנָּה הִיא בְּעֵינַי, שֶׁתְּהֵא לְךָ זֹאת לְבַדָּהּ, שֶׁתְּהֵא לִי עֶבֶד לְהָקִים אֶת יַעֲקֹב וּלְהָשִׁיב אֵלַי נְצוּרֵי יִשְׂרָאֵל, וְהִנְנִי מוֹסִיף לְךָ עוֹד וּנְתַתִּיךָ לְאוֹר גּוֹיִם לְהִנָּבֵא עַל מַפַּלְתָּהּ שֶׁל בָּבֶל, שֶׁהִיא שִׂמְחָה לְכָל הָעוֹלָם:\",1,0],[2,120,49,6,\"וּנְצוּרֵי יִשְׂרָאֵל. כְּמוֹ (משלי ז:י) ״וּנְצֻרַת לֵב״, שֶׁלִּבָּם מֻקָּף יֵצֶר הִרְהוּרֵי עֲבֵירָה כְּעִיר נְצוּרָה מָצוֹר הַצָּרִים עָלֶיהָ:\",2,0],[2,120,49,7,\"לִבְזֹה נֶפֶשׁ. נֶפֶשׁ בְּזוּיָה:\",1,0],[2,120,49,7,\"לִמְתָעֵב גּוֹי. לְמִי שֶׁהַגּוֹי מְתַעֲבוֹ:\",2,0],[2,120,49,7,\"מְלָכִים יִרְאוּ אוֹתוֹ וְקָמוּ:\",3,0],[2,120,49,7,\"אֲשֶׁר נֶאֱמָן. לִשְׁמוֹר הַבְטָחָתוֹ שֶׁהִבְטִיחַ לְאַבְרָהָם עַל הַמַּלְכִיּוֹת, כְּעִנְיָן שֶׁנֶּאֱמַר ״וְהִנֵּה תַנּוּר עָשָׁן וְגוֹ׳״ (בראשית טו:יז):\",4,0],[2,120,49,7,\"קְדוֹשׁ יִשְׂרָאֵל. הוּא וַיִּבְחָרֶךָּ:\",5,0],[2,120,49,8,\"בְּעֵת רָצוֹן. בְּעֵת תְּפִלָּה, שֶׁאַתָּה מִתְרַצֶּה וּמִתְפַּיֵּס לְפָנַי (ברכות ח א):\",1,0],[2,120,49,8,\"וּבְיוֹם יְשׁוּעָה. שֶׁתְּהֵא צָרִיךְ לִישׁוּעָה:\",2,0],[2,120,49,8,\"וְאֶצָּרְךָ. וְאֶשְׁמָרְךָ:\",3,0],[2,120,49,8,\"לִבְרִית עָם. לִהְיוֹת עַם בְּרִית לִי:\",4,0],[2,120,49,8,\"לְהָקִים אֶרֶץ. אֶרֶץ יִשְׂרָאֵל, הַבְּחוּרָה לִי בְּכָל הָאֲרָצוֹת:\",5,0],[2,120,49,9,\"לַאֲסוּרִים צֵאוּ. לְעֵת אֲשֶׁר אוֹמַר לַאֲסוּרֵי גוֹלָה צֵאוּ:\",1,0],[2,120,49,9,\"שְׁפָיִים. תִּרְגֵּם יוֹנָתָן ״נַגְדִּין״, נַחֲלֵי מַיִם:\",2,0],[2,120,49,10,\"שָׁרָב. חוֹם:\",1,0],[2,120,49,11,\"וְשַׂמְתִּי כָל הָרַי לַדָּרֶךְ. כְּלַפֵּי שֶׁאָמַר (ישעיהו לג:ח) עַל יְדֵי חֻרְבָּנָהּ ״שָׁבַת עוֹבֵר אֹרַח״, עַכְשָׁיו יָשׁוּבוּ וְיֵלְכוּ בּוֹ עוֹבְרִים וְשָׁבִים:\",1,0],[2,120,49,11,\"וּמְסִלֹּתַי יְרֻמוּן. כְּלַפֵּי שֶׁאָמַר (ישעיהו לג:ח) ״נָשַׁמּוּ מְסִלּוֹת״, נִתְקַלְקְלוּ מֵאֵין מְתַקֵּן אוֹתָם, עַכְשָׁיו וּמְסִלֹּתַי יְרֻמוּן – יְתַקְּנוּ קִלְקוּל הַדְּרָכִים וְיַגְבִּיהַ אוֹתָם כַּמִשְׁפָּט בְּחִלּוּקֵי אֲבָנִים וְעָפָר:\",2,0],[2,120,49,12,\"מֵאֶרֶץ סִינִים. ״מֵאַרַע דָּרוֹמָא״ (תרגום יונתן):\",1,0],[2,120,49,13,\"כִּי נִחַם ה׳‏ אֶת עַמּוֹ׃\",1,0],[2,120,49,14,\"וַתֹּאמֶר צִיּוֹן. הִיא הָיְתָה סְבוּרָה שֶׁשְּׁכַחְתִּיהָ:\",1,0],[2,120,49,15,\"הֲתִשְׁכַּח אִשָּׁה עוּלָהּ. עוֹלָל שֶׁלָּהּ:\",1,0],[2,120,49,15,\"מֵרַחֵם בֶּן בִּטְנָהּ. מִלְּרַחֵם עַל בֶּן בִּטְנָהּ:\",2,0],[2,120,49,15,\"גַּם אֵלֶּה תִשְׁכַּחְנָה. אֲפִילּוּ אִם אֵלֶּה תִּשְׁכַּחְנָה, אָנֹכִי לֹא אֶשְׁכָּחֵךְ:\",3,0],[2,120,49,16,\"עַל כַּפַּיִם. עַל כַּפַּי רוֹאֶה אֲנִי כְּאִלּוּ אַתְּ חֲקוּקָה עַל כַּפִּי לִרְאוֹתֵךְ וּלְזָכְרֵךְ תָּמִיד. דָּבָר אַחֵר: עַל כַּפַּיִם – מֵעַל עַנְנֵי כָּבוֹד, כְּמוֹ (איוב לו:לב) ״עַל כַּפַּיִם כִּסָּה אוֹר״:\",1,0],[2,120,49,17,\"מִהֲרוּ בָּנָיִךְ. לָשׁוּב:\",1,0],[2,120,49,19,\"תֵּצְרִי מִיּוֹשֵׁב. תְּהִי צָרָה מֵרֹב יוֹשְׁבִים שֶׁיָּבֹאוּ לְתוֹכֵךְ, יְהִי לָהֶם הַמָּקוֹם צַר מִלִּבְנוֹת לָהֶם בָּתִּים:\",1,0],[2,120,49,20,\"בְּנֵי שִׁכֻּלָיִךְ. בָּנִים שֶׁהָיִית שְׁכוּלָה מֵהֶם:\",1,0],[2,120,49,20,\"גְּשָׁה לִּי. הִתְקָרֵב לְצַד אַחֵר בִּשְׁבִילִי וְאֵשֵׁבָה:\",2,0],[2,120,49,21,\"גַּלְמוּדָה. שולד״א בלע״ז:\",1,0],[2,120,49,21,\"וְסוּרָה. מוּסֶרֶת מִכָּל אָדָם, הַכֹּל אוֹמְרִים עָלַי: סוּרוּ מִמֶּנָּה:\",2,0],[2,120,49,22,\"יָדִי… נִסִּי. סִימָן לְהָבִיא גָּלִיּוֹת:\",1,0],[2,120,49,22,\"נִסִּי. פירקא בלע״ז, כמו ״וְכַנֵּס עַל הַגִבְעָה״ (ישעיהו ל:יז), וְהוּא סִימָן קִבּוּץ, וְנוֹתְנִין בְּרֹאשָׁהּ בֶּגֶד:\",2,0],[2,120,49,22,\"בְּחֹצֶן. איישיל״א בלע״ז, וְדוֹמֶה לוֹ בְּעֶזְרָא: ״וגַם (אני) חָצְנִי נָעַרְתִּי״ (נחמיה ה:יג):\",3,0],[2,120,49,24,\"הֲיֻקַּח מִגִּבּוֹר מַלְקוֹחַ. כִּסְבוּרִים אַתֶּם שֶׁאִי אֶפְשָׁר לָקַחַת מֵעֵשָׂיו מַלְקוֹחַ שִׁבְיוֹ שֶׁל יַעֲקֹב הַצַּדִּיק?\",1,0],[2,120,49,25,\"וְאֶת יְרִיבֵךְ. וְעִם מְרִיבַיִךְ אֲנִי אָרִיב:\",1,0],[2,120,49,26,\"וְהַאֲכַלְתִּי אֶת מוֹנַיִךְ. הַבַּבְלִיִּים לְחַיַּת הַשָּׂדֶה אֶת בְּשָׂרָם. מוֹנַיִךְ – לְשׁוֹן ״אַל תּוֹנוּ״ (ויקרא כה:יד), אוֹנָאַת דְּבָרִים, הַמְקַנְתְּרִים אוֹתָךְ בְּגִדּוּפֵיהֶם:\",1,0],[2,120,49,26,\"וְכֶעָסִיס. מֶתֶק יַיִן:\",2,0],[2,120,49,26,\"דָּמָם יִשְׁכָּרוּן. כֵּן יִשְׁכְּרוּ מִדָּמָם אוֹתָם הָרְגִילִים לִשְׁתּוֹת דָּם, וּמִי הֵם אֵלּוּ? עוֹף הַשָּׁמַיִם. כֵּן תִּרְגֵּם יוֹנָתָן:\",3,0],[2,120,50,2,\"מַדּוּעַ בָּאתִי. לְהִתְקָרֵב אֲלֵיכֶם, וְאֵין אִישׁ – מִי מִכֶּם פּוֹנֶה אֵלַי?\",1,0],[2,120,50,3,\"אַלְבִּישׁ שָׁמַיִם. צְבָא הַשָּׁמַיִם, שָׂרֵי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, כְּשֶׁאֲנִי בָּא לִפָּרַע מִן הָאֻמָּה (מכילתא בשלח שירה ב):\",1,0],[2,120,50,4,\"נָתַן לִי לְשׁוֹן לִמּוּדִים. יְשַׁעְיָה הָיָה אוֹמֵר: ה׳ שְׁלָחַנִי וְנָתַן לִי לָשׁוֹן הָרָאוּי לְלַמֵּד, כְּדֵי לָדַעַת לָעוּת אֶת הָעֲיֵפִים וּצְמֵאִים לִשְׁמֹעַ אֶת דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא דָּבָר:\",1,0],[2,120,50,4,\"לָעוּת. מְנַחֵם חִבְּרוֹ בְּמַחֲלוֹקֶת ״עֵת לַעֲשׂוֹת לַה׳״ (תהלים קיט:קכו), לִקְבּוֹעַ לָהֶם עִתִּים:\",2,0],[2,120,50,4,\"יָעִיר לִי אֹזֶן. מְעוֹרֵר אֶת אָזְנִי בְּרוּחַ קָדְשׁוֹ:\",3,0],[2,120,50,4,\"לִשְׁמֹעַ כַּלִּמּוּדִים. בְּמִשְׁפַּט הַלִּמּוּדִים, הָאֱמֶת וְהַנְּכוֹחָה:\",4,0],[2,120,50,5,\"פָּתַח לִי אֹזֶן. וְהִשְׁמִיעַנִי ״אֶת מִי אֶשְׁלַח״ (ישעיהו ו:ח), שָׁלַחְתִּי אֶת עָמוֹס וְהָיוּ קוֹרִין אוֹתוֹ פְּסִילוּס, שָׁלַחְתִּי אֶת מִיכָה וְכוּ׳, כִּדְאִיתָא בִּפְסִיקְתָּא דְּנַחֲמוּ נַחֲמוּ (פסיקתא דרב כהנא טז ד):\",1,0],[2,120,50,5,\"וְאָנֹכִי לֹא מָרִיתִי. מִלֵּילֵךְ בִּשְׁלִיחוּתוֹ, וְלֹא נְסוּגוֹתִי אָחוֹר, אֶלָּא ״וָאוֹמַר הִנְנִי שְׁלָחֵנִי״ (ישעיהו ו:ח):\",2,0],[2,120,50,6,\"גֵּוִי נָתַתִּי לְמַכִּים הוּא אָמַר לִי: ״יְשַׁעְיָה, בָּנַי סַרְבָנִים הֵם, בָּנַי טַרְחָנִים הֵם, עַל מְנָת שֶׁלֹּא תִּכְעוֹס עֲלֵיהֶם״. אָמַרְתִּי לוֹ: ״עַל מְנָת כֵּן״ (פסיקתא דרב כהנא טז ד):\",1,0],[2,120,50,7,\"וַה׳ אֱלֹהִים יַעֲזָר לִי. אִם יָקוּמוּ עָלַי:\",1,0],[2,120,50,8,\"קָרוֹב מַצְדִּיקִי. הַקָּדוֹשׁ בָּרוּךְ הוּא קָרוֹב לִי, לְזַכּוֹתִי בַּדִּין:\",1,0],[2,120,50,9,\"עָשׁ. תּוֹלַעַת הַבְּגָדִים:\",1,0],[2,120,50,10,\"בְּקוֹל עַבְדּוֹ. בְּקוֹל הַנְּבִיאִים:\",1,0],[2,120,50,10,\"אֲשֶׁר הָלַךְ חֲשֵׁכִים. אֲפִלּוּ צָרָה בָּאָה עָלָיו, יִבְטַח בְּשֵׁם ה׳, כִּי הוּא יַצִּילֵהוּ:\",2,0],[2,120,50,11,\"הֵן כֻּלְּכֶם. שֶׁאֵינְכֶם שׁוֹמְעִים בְּקוֹל נְבִיאָיו:\",1,0],[2,120,50,11,\"קֹדְחֵי אֵשׁ. עֶבְרָתוֹ עֲלֵיכֶם:\",2,0],[2,120,50,11,\"מְאַזְּרֵי זִיקוֹת. מַחֲזִיקֵי זִיקוֹת, הֵן גִּצִּין וְגַחֲלֵי אֵשׁ הַנִּזְרָקִין בַּקֶּלַע. וְיֵשׁ לוֹ דֻגְמָא בִּלְשׁוֹן אֲרַמִּי: ״זִיקוּקִין דְּנוּר״ (ברכות נח ב), ״כָּךְ וְכָךְ זִיקָתָא פָּסִיק לָן״ (בבא מציעא צד א):\",3,0],[2,120,50,11,\"לְכוּ בְּאוּר אֶשְׁכֶם. לְפִי דַרְכְּכֶם תִּלְקוּ:\",4,0],[2,120,50,11,\"מִיָּדִי. תְּהֵא גְמוּלְכֶם זֹאת לָכֶם:\",5,0],[2,120,51,1,\"אֶל צוּר חֻצַּבְתֶּם. מִמֶּנּוּ:\",1,0],[2,120,51,1,\"וְאֶל מַקֶּבֶת בּוֹר. שֶׁנּוֹקְבִין וְחוֹצְבִין בָּהּ אֶת הַבּוֹרוֹת, אֲשֶׁר נֻקַּרְתֶּם בָּהּ:\",2,0],[2,120,51,1,\"נֻקַּרְתֶּם. לְשׁוֹן ״נִקְרַת הַצּוּר״ (שמות לג:כב), ״יִקְּרוּהָ עֹרְבֵי נַחַל״ (משלי ל:יז). וּמִי הוּא הַצּוּר? הוּא אַבְרָהָם אֲבִיכֶם, וּמִי הִיא הַמַּקֶּבֶת? הִיא שָׂרָה אֲשֶׁר חוֹלֶלְתְכֶם, אֲשֶׁר יְלַדְתְכֶם, לְשׁוֹן ״כִּי חָלָה גַּם יָלְדָה״ (ישעיהו סו:ח):\",3,0],[2,120,51,2,\"תְּחוֹלֶלְכֶם. אֲשֶׁר תֵּלֵד אֶתְכֶם:\",1,0],[2,120,51,2,\"כִּי אֶחָד קְרָאתִיו. כִּי אֶחָד הָיָה, יְחִידִי בְּאֶרֶץ כְּנַעַן אֲשֶׁר הִגְלֵיתִיו שָׁם מֵאַרְצוֹ וּמִמּוֹלַדְתּוֹ, קְרָאתִיו – רִבִּיתִיו וְגִדַּלְתִּיו, לְשׁוֹן ״קְרִיאֵי הָעֵדָה״ (במדבר א:טז), וּכְשֵׁם שֶׁהוּא הָיָה יָחִיד וְגִדַּלְתִּיו, כֵּן אֲגַדֵּל אֶתְכֶם שֶׁאַתֶּם יְחִידִים לִי:\",2,0],[2,120,51,3,\"וְעַרְבָתָהּ. אַף הוּא לְשׁוֹן ׳מִדְבָּר׳, כְּמוֹ ״בְּאֶרֶץ עֲרָבָה וְשׁוּחָה״ (ירמיהו ב:ו), אֶלָּא שֶׁהָעֲרָבָה כְּבָר הָיָה בָּהּ יִשּׁוּב וְהֻחְרְבָה:\",1,0],[2,120,51,3,\"תּוֹדָה. קוֹל הוֹדָיָה:\",2,0],[2,120,51,4,\"כִּי תוֹרָה מֵאִתִּי תֵצֵא. דִּבְרֵי נְבִיאִים תּוֹרָה הוּא, וְהַמִּשְׁפָּטִים סוֹפָן לִהְיוֹת מַרְגּוֹעַ וּמְנוּחָה לָעַמִּים, אֲשֶׁר אֶהְפּוֹךְ לָהֶם שָׂפָה בְרוּרָה לְעָבְדֵנִי (צפניה ג:ט):\",1,0],[2,120,51,4,\"אַרְגִּיעַ. אָנִיחַ:\",2,0],[2,120,51,5,\"יִשְׁפֹּטוּ. יְיַסְּרוּ, יושטיצ״א בלע״ז:\",1,0],[2,120,51,6,\"שָׁמַיִם כֶּעָשָׁן נִמְלָחוּ. שָׂרֵי צְבָאוֹת הָאֻמּוֹת שֶׁבַּשָּׁמַיִם:\",1,0],[2,120,51,6,\"נִמְלָחוּ. נִתְבַּלּוּ, כְּמוֹ (ירמיהו לח:יב) ״בְּלוֹיֵי הַסְּחָבוֹת וְהַמְּלָחִים״, בֶּגֶד הַנִּשְׁחָת. לָשׁוֹן אַחֵר: נִמְלָחוּ – נִתְבַּלְבְּלוּ, לְשׁוֹן מַלָּחֵי הַיָּם שֶׁמְּבַלְבְּלִין הַמַּיִם בַּמְּשׁוֹטוֹת מַנְהִיגֵי הַסְּפִינָה, וְכֵן ״מְמֻלָּח טָהוֹר קֹדֶשׁ״ (שמות ל:לה):\",2,0],[2,120,51,6,\"וְהָאָרֶץ. שִׁלְטוֹנֵי הָאָרֶץ:\",3,0],[2,120,51,6,\"וְיֹשְׁבֶיהָ. שְׁאָר הָעָם:\",4,0],[2,120,51,6,\"וִישׁוּעָתִי. לְעַמִּי לְעוֹלָם תִּהְיֶה. דָּבָר אַחֵר: שָׁמַיִם וָאָרֶץ מַמָּשׁ, וְכֵן פִּתְרוֹנוֹ: שְׂאוּ עֵינֵיכֶם וְהַבִּיטוּ אֶל הַשָּׁמַיִם וְאֶל הָאָרֶץ וּרְאוּ כַּמָּה הֵם חֲזָקִים וּבְרִיאִים, וְאַף עַל פִּי כֵן יִבְלוּ, וְצִדְקָתִי וִישׁוּעָתִי יִהְיוּ לְעוֹלָם. הֲרֵי שֶׁצִּדְקָתִי בְּרִיאָה וַחֲזָקָה יוֹתֵר מֵהֶם:\",5,0],[2,120,51,8,\"עָשׁ וְסָס. מִינֵי תוֹלָעִים הֵם:\",1,0],[2,120,51,9,\"עוּרִי עוּרִי. תְּפִלַּת הַנָּבִיא הִיא:\",1,0],[2,120,51,9,\"רַהַב. מִצְרַיִם, שֶׁכָּתוּב בָּהּ ״רַהַב הֵם שָׁבֶת״ (ישעיהו ל:ז):\",2,0],[2,120,51,9,\"מְחוֹלֶלֶת. לְשׁוֹן הֶרֶג חָלָל:\",3,0],[2,120,51,9,\"תַּנִּין. פַּרְעֹה:\",4,0],[2,120,51,11,\"וּפְדוּיֵי ה׳ יְשׁוּבוּן. לְשׁוֹן תְּפִלָּה, וּמוּסָב עַל עוּרִי עוּרִי:\",1,0],[2,120,51,12,\"מִי אַתְּ. בַּת צַדִּיקִים כְּמוֹתֵךְ, מְלֵאָה זְכֻיּוֹת, לָמָּה תִּירְאִי מֵאֱנוֹשׁ אֲשֶׁר סוֹפוֹ לָמוּת?\",1,0],[2,120,51,13,\"וַתִּשְׁכַּח ה׳ עֹשֶׂךָ. וְלֹא נִשְׁעַנְתָּ עָלָיו:\",1,0],[2,120,51,13,\"הַמֵּצִיק. מוֹשְׁלֵי אֻמּוֹת הָעוֹלָם הַמְשַׁעְבְּדִים בָּכֶם:\",2,0],[2,120,51,13,\"כַּאֲשֶׁר כּוֹנֵן. נִזְדַּמֵּן:\",3,0],[2,120,51,13,\"וְאַיֵּה חֲמַת הַמֵּצִיק. מָחָר בָּא וְאֵינֶנּוּ:\",4,0],[2,120,51,14,\"מִהַר צֹעֶה לְהִפָּתֵחַ. אֲפִלּוּ נְקָבִין קָשִׁין עָלָיו, וְצָרִיךְ הוּא לְהִפָּתֵחַ בְּהִלּוּךְ הַמֵּעַיִם כְּדֵי שֶׁלֹּא יָמוּת לַשַּׁחַת, וְכֵיוָן שֶׁמִּהַר לְהִפָּתֵחַ צָרִיךְ הוּא לִמְזוֹנוֹת רַבִּים, שֶׁאִם יֶחְסַר לַחְמוֹ אַף הוּא יָמוּת:\",1,0],[2,120,51,14,\"צֹעֶה. לְשׁוֹן דָּבָר הָעוֹמֵד לִהְיוֹת נִירוֹק, כְּמוֹ שֶׁאוֹמֵר בְּמוֹאָב שֶׁדִּמָּהוּ הַנָּבִיא לְיַיִן (ירמיהו מח:יא) ״הַשֹּׁקֵט אֶל שְׁמָרָיו וְלֹא הוּרַק מִכְּלִי אֶל כֶּלִי״, וְנֶאֱמַר שָׁם ״וְשָׁלַחְתִּי לוֹ צֹעִים וְצֵעֻהוּ וְכֵלָיו יָרִיקוּ״. דָּבָר אַחֵר: מִהַר צֹעֶה – אוֹתוֹ הָאוֹיֵב הַמֵּצִיק, שֶׁהוּא עַכְשָׁיו חֲגוּר מָתְנַיִם, חֲלוּץ כֹּחַ, יְמַהֵר לְהִפָּתֵחַ וְלִהְיוֹת חַלָּשׁ:\",2,0],[2,120,51,14,\"צֹעֶה. חוֹגֵר, כְּמוֹ (ישעיהו סג:א) ״צֹעֶה בְּרֹב כֹּחוֹ״:\",3,0],[2,120,51,14,\"וְלֹא יָמוּת. הַמָּסוּר בְּיָדוֹ לַשַּׁחַת, אֲבָל הַלָּשׁוֹן רִאשׁוֹן מִדְּרַשׁ אַגָּדָה הוּא בִּפְסִיקְתָּא רַבָּתִי (פסיקתא רבתי לג:):\",4,0],[2,120,51,15,\"רֹגַע הַיָּם. לְשׁוֹן ״עוֹרִי רָגַע״ (איוב ז:ה), פרונצ״א בלע״ז:\",1,0],[2,120,51,16,\"לִנְטֹעַ שָׁמַיִם. ״לְקַיָּמָא עַמָּא דַּאֲמִיר עֲלֵיהוֹן דְּיִסְגּוֹן כְּכוֹכְבֵי שְׁמַיָּא״ (תרגום יונתן):\",1,0],[2,120,51,16,\"וְלִיסֹד אָרֶץ. ״וּלְשַׁכְלָלָא כְּנִישְׁתָּא דַּאֲמִיר עֲלֵיהוֹן דְּיִסְגּוֹן כְּעַפְרָא דְּאַרְעָא״:\",2,0],[2,120,51,17,\"קֻבַּעַת. תִּרְגֵּם יוֹנָתָן: ״פַּיְלֵי״, וְהוּא שֵׁם כּוֹס. וְלִי נִרְאֶה: קֻבַּעַת – אֵלּוּ הַשְּׁמָרִים הַקְּבוּעִים בְּתַחְתִּית הַכְּלִי, וּמָצִית יוֹרֶה עָלָיו, כְּמוֹ שֶׁנֶּאֱמַר ״שְׁמָרֶיהָ יִמְצוּ״ (תהלים עה:ט):\",1,0],[2,120,51,17,\"הַתַּרְעֵלָה. הוּא מַשְׁקֶה הַמְטַמְטֵם וּמַתִּישׁ כֹּחַ הָאָדָם כְּאָסוּר וְקָשׁוּר וּמְעֻטָּף, כְּמוֹ ״וְהַבְּרוֹשִׁים הָרְעָלוּ״ (נחום ב:ד), ״וְהַשֵּׁרוֹת וְהָרְעָלוֹת״ (ישעיהו ג:יט), שֶׁהוּא לְשׁוֹן ׳עִטּוּף׳, וּבְמַסֶּכֶת שַׁבָּת (שבת סה א) מָדִיּוֹת רְעוּלוֹת – מִין סַרְבָּל נָאֶה לְהִתְעַטֵּף בּוֹ:\",2,0],[2,120,51,17,\"תַּרְעֵלָה. אינטומישמנ״ט בלע״ז:\",3,0],[2,120,51,17,\"מָצִית. אגושטי״ר בלע״ז:\",4,0],[2,120,51,19,\"שְׁתַּיִם הֵנָּה קֹרְאֹתַיִךְ. צָרוֹת כְּפוּלוֹת, שְׁתַּיִם שְׁתַּיִם:\",1,0],[2,120,51,19,\"מִי אֲנַחֲמֵךְ. מִי אָבִיא לָךְ לְנַחֲמֵךְ וְלוֹמַר: אַף אֻמָּה פְּלוֹנִית הִיא לָקְתָה דֻּגְמָתֵךְ?\",2,0],[2,120,51,20,\"עֻלְּפוּ. לְשׁוֹן ׳עֲיֵפוּת׳, כְּמוֹ (עמוס ח:יג) ״תִּתְעַלַּפְנָה הַבְּתוּלוֹת בַּצָּמָא״, פשמי״ר בלע״ז:\",1,0],[2,120,51,20,\"כְּתוֹא מִכְמָר. הֶפְקֵר כְּתוֹא זֶה שֶׁנָּפַל לְמִכְמָר. תּוֹא כְּמוֹ ״וּתְאוֹ וָזָמֶר״ (דברים יד:ה):\",2,0],[2,120,51,21,\"וּשְׁכֻרַת וְלֹא מִיָּיִן. שְׁכֻרַת מִדָּבָר אַחֵר שֶׁלֹּא מִיָּיִן:\",1,0],[2,120,51,22,\"יָרִיב עַמּוֹ. אֲשֶׁר יָדִין דִּין עַמּוֹ:\",1,0],[2,120,51,23,\"מוֹגַיִךְ. מְנִיעֵיךְ וּמְטַלְטְלֵיךְ, כְּמוֹ ״וְהִנֵּה הֶהָמוֹן נָמוֹג״ (שמואל א יד:טז). קרושלי״ר בלע״ז:\",1,0],[2,120,51,23,\"שְׁחִי וְנַעֲבֹרָה. עַל גַּבֵּךְ:\",2,0],[2,120,52,2,\"הִתְנַעֲרִי. אישקור״א בלע״ז, כִּמְנַעֵר אֶת הַטַּלִּית (שבת קמז א):\",1,0],[2,120,52,2,\"קוּמִי. מִן הָאָרֶץ, מִגִּזְרַת ״לָאָרֶץ תֵּשֵׁב״ (ישעיהו ג:כו):\",2,0],[2,120,52,2,\"שְׁבִי. עַל הַכִּסֵּא:\",3,0],[2,120,52,2,\"הִתְפַּתְּחִי. הֱוִי נִתֶּרֶת:\",4,0],[2,120,52,2,\"מוֹסְרֵי. קריגל״ש בלע״ז:\",5,0],[2,120,52,2,\"שְׁבִיָּה. כְּמוֹ ׳שְׁבוּיָה׳:\",6,0],[2,120,52,3,\"חִנָּם נִמְכַּרְתֶּם. עַל עִסְקֵי חִנָּם, הוּא יֵצֶר הָרָע שֶׁאֵינוֹ לָכֶם לְשָׂכָר:\",1,0],[2,120,52,3,\"וְלֹא בְכֶסֶף תִּגָּאֵלוּ. אֶלָּא בִּתְשׁוּבָה (ירושלמי תענית א א):\",2,0],[2,120,52,4,\"מִצְרַיִם יָרַד עַמִּי וגו׳. הֵם הַמִּצְרִיִּים הָיוּ לָהֶם קְצָת חוֹב עֲלֵיהֶם, שֶׁנַּעֲשׂוּ לָהֶם אַכְסַנְיָא וְכִלְכְּלוּם, אֲבָל אַשּׁוּר בְּאֶפֶס וּבְחִנָּם עֲשָׁקוֹ:\",1,0],[2,120,52,5,\"מַה לִּי פֹה. לָמָּה אֲנִי שׁוֹהֵא וּמַשְׁהֵא בָּנַי כָּאן?\",1,0],[2,120,52,5,\"יְהֵילִילוּ. מִתְפָּאֲרִים לֵאמֹר: ״יָדֵינוּ רָמָה״ (דברים לב:כז):\",2,0],[2,120,52,5,\"מְנֹאָץ. מִתְנָאֵץ, וַהֲרֵי זֶה דֻּגְמַת ״וַיִּשְׁמַע אֶת הַקּוֹל מִדַּבֵּר אֵלָיו״ (במדבר ז:פט):\",3,0],[2,120,52,6,\"יֵדַע עַמִּי. כְּשֶׁאֶגְאָלֵם יַכִּירוּ, כִּי שְׁמִי אָדוֹן, שַׁלִּיט וּמוֹשֵׁל, כְּמַשְׁמָעוֹ (חגיגה טו:-טז.):\",1,0],[2,120,52,6,\"לָכֵן בַּיּוֹם. גְּאֻלָּתָם יָבִינוּ כִּי אֲנִי הוּא הַמְדַבֵּר הִנֵּנִי קִיַּמְתִּי:\",2,0],[2,120,52,8,\"צֹפַיִךְ. צוֹפִים שֶׁמַּעֲמִידִין עַל הַחוֹמוֹת וְהַמִּגְדָּלִים לְבַשֵּׂר וְלִרְאוֹת מִי בָּא לָעִיר:\",1,0],[2,120,52,10,\"חָשַׂף. גִּלָּה:\",1,0],[2,120,52,11,\"טָמֵא אַל תִּגָּעוּ. שֶׁקֶץ יִהְיוּ לָכֶם מִלִּגַּע בָּהֶם:\",1,0],[2,120,52,11,\"צְאוּ מִתּוֹכָהּ. מִתּוֹךְ הַגָּלוּת, כָּל נֶחָמוֹת הָאֵלּוּ הָאַחֲרוֹנוֹת אֵינָן אֶלָּא עַל גָּלוּת הָאַחֲרוֹן:\",2,0],[2,120,52,11,\"הִבָּרוּ. הִטַּהֲרוּ:\",3,0],[2,120,52,11,\"נֹשְׂאֵי כְּלֵי ה׳. הַכֹּהֲנִים הַלְוִיִּם, שֶׁהֲיִיתֶם נוֹשְׂאִים כֵּלָיו (שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא) בַּמִּדְבָּר (מִכָּאן לִתְחִיַּת הַמֵּתִים):\",4,0],[2,120,52,12,\"כִּי הוֹלֵךְ לִפְנֵיכֶם. שְׁנֵי דְבָרִים שֶׁבְּסוֹף הַמִּקְרָא הַזֶּה מְיַשְּׁבִין שְׁנֵי דְבָרִים שֶׁבְּרֹאשׁוֹ: כִּי לֹא בְחִפָּזוֹן תֵּצֵאוּ – מָה טַעַם? כִּי הוֹלֵךְ לִפְנֵיכֶם ה׳ לַנְחוֹתְכֶם הַדֶּרֶךְ, וּמִי שֶׁשְּׁלוּחוֹ מַקְדִּים לְפָנָיו לַנְחוֹתוֹ הַדֶּרֶךְ אֵין יְצִיאָתוֹ בְחִפָּזוֹן. וּבִמְנוּסָה לֹא תֵלֵכוּן – לְפִי שֶׁמְּאַסִּפְכֶם אֱלֹהֵי יִשְׂרָאֵל הוֹלֵךְ מֵאַחֲרֵיכֶם לִשְׁמֹר אֶתְכֶם מִכָּל רוֹדֵף, כְּמוֹ ״וְנָסַע דֶּגֶל מַחֲנֵה דָן מְאַסֵּף לְכָל הַמַּחֲנוֹת״ (במדבר י:כה). הַהוֹלֵךְ אַחֲרֵי הַמַּחֲנֶה קָרוּי מְאַסֵּף, לְפִי שֶׁהוּא מַמְתִּין אֶת הַנֶּחֱלָשִׁים וְאֶת הַנִּכְשָׁלִים, וְכֵן הוּא אוֹמֵר בִּיהוֹשֻׁעַ (יהושע ו:יג): ״וְהַמְאַסֵּף הוֹלֵךְ אַחֲרֵי הָאָרוֹן״:\",1,0],[2,120,52,13,\"הִנֵּה יַשְׂכִּיל עַבְדִּי. הִנֵּה בְּאַחֲרִית הַיָּמִים יַצְלִיחַ עַבְדִּי יַעֲקֹב, צַדִּיקִים שֶׁבּוֹ:\",1,0],[2,120,52,14,\"כַּאֲשֶׁר שָׁמְמוּ. כַּאֲשֶׁר תָּמְהוּ עֲלֵיהֶם עַמִּים רַבִּים בִּרְאוֹתָם שִׁפְלוּתָם, וְאָמְרוּ זֶה אֶל זֶה: כַּמָּה מִשְׁחַת מֵאִישׁ מַרְאֵהוּ (שֶׁל יִשְׂרָאֵל), רְאוּ מַה תָּאֳרָם חָשׁוּךְ מִשְּׁאָר בְּנֵי אָדָם, כֵּן כַּאֲשֶׁר אֲנַחְנוּ רוֹאִים בְּעֵינֵינוּ:\",1,0],[2,120,52,15,\"כֵּן יַזֶּה גּוֹיִם רַבִּים. כֵּן עַתָּה גַּם הוּא תִּגְבַּר יָדוֹ וְיַזֶּה אֶת קַרְנוֹת הָעֲוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֲשֶׁר זֵרוּהוּ (זכריה ב:ד):\",1,0],[2,120,52,15,\"יִקְפְּצוּ. יִסְגְּרוּ פִּיהֶם מֵרוֹב תִּמָּהוֹן, כִּי כָבוֹד אֲשֶׁר לֹא סֻפַּר לָהֶם עַל שׁוּם אָדָם רָאוּ בּוֹ:\",2,0],[2,120,52,15,\"הִתְבּוֹנָנוּ. ״אִסְתַּכָּלוּ״:\",3,0],[2,120,53,1,\"מִי הֶאֱמִין לִשְׁמֻעָתֵנוּ. כֵּן יֹאמְרוּ הָעֲוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אִישׁ לְרֵעֵהוּ: אִלּוּ הָיִינוּ שׁוֹמְעִים מִפִּי אֲחֵרִים מַה שֶּׁאָנוּ רוֹאִים, אֵין לְהַאֲמִין:\",1,0],[2,120,53,1,\"וּזְרוֹעַ ה׳. כָּזֹאת בִּגְדֻלָּה וְהוֹד, עַל מִי נִגְלָתָה עַד הֵנָּה?\",2,0],[2,120,53,2,\"וַיַּעַל כַּיּוֹנֵק לְפָנָיו. הָעָם הַזֶּה, לִפְנֵי בָּא לוֹ הַגְּדֻלָּה הַזֹּאת, עַם שָׁפָל הָיָה מְאֹד, וְעָלָה מֵאֵלָיו כְּיוֹנֵק מִיּוֹנֶקֶת הָאִילָנוֹת:\",1,0],[2,120,53,2,\"וְכַשֹּׁרֶשׁ. עָלָה מֵאֶרֶץ צִיָּה:\",2,0],[2,120,53,2,\"לֹא תֹאַר. הָיָה לוֹ מִתְּחִלָּה וְלֹא הָדָר:\",3,0],[2,120,53,2,\"וְנִרְאֵהוּ וְלֹא מַרְאֶה וְנֶחְמְדֵהוּ. וּכְשֶׁרְאִינוּהוּ מִתְּחִלָּה בְּאֵין מַרְאֶה, הֵיאַךְ נֶחְמְדֵהוּ? וְנֶחְמְדֵהוּ תָּמוּהַּ הוּא:\",4,0],[2,120,53,3,\"נִבְזֶה וַחֲדַל אִישִׁים. הָיָה; כֵּן דֶּרֶךְ הַנָּבִיא הַזֶּה: מַזְכִּיר כָּל יִשְׂרָאֵל כְּאִישׁ אֶחָד, ״אַל תִּירָא עַבְדִּי יַעֲקֹב״ (ישעיהו מד:ב), וְאַף כָּאן ״הִנֵּה יַשְׂכִּיל עַבְדִּי״ (ישעיהו נב:יג) בְּבֵית יַעֲקֹב אָמַר; וְ׳יַשְׂכִּיל׳ לְשׁוֹן הַצְלָחָה הוּא, כְּמוֹ ״וַיְהִי דָוִד לְכָל דְּרָכָיו מַשְׂכִּיל״ (שמואל א יח:יד):\",1,0],[2,120,53,3,\"וּכְמַסְתֵּר פָּנִים מִמֶּנּוּ. מֵרֹב בָּשְׁתָּם וְשִׁפְלוּתָם הָיוּ כְּמַסְתִּיר פָּנִים מִמֶּנּוּ, חֲבוּשֵׁי פָּנִים בְּטָמוּן, כְּדֵי שֶׁלֹּא נִרְאֶה אוֹתָם, כְּאָדָם מְנֻגָּע שֶׁמַּסְתִּיר פָּנָיו וְיָרֵא מְהַבִּיט:\",2,0],[2,120,53,4,\"אָכֵן חֳלָיֵנוּ הוּא נָשָׂא. אָכֵן לְשׁוֹן ׳אֲבָל׳ בְּכָל מָקוֹם. אֲבָל עַתָּה אָנוּ רוֹאִים שֶׁלֹּא מֵחֲמַת שִׁפְלוּתוֹ בָּא לוֹ, אֶלָּא מְיֻסָּר הָיָה בְּיִסּוּרִין:\",1,0],[2,120,53,4,\"וַאֲנַחְנוּ חֲשַׁבְנֻהוּ. אָנוּ הָיִינוּ סְבוּרִים שֶׁהוּא שְׂנָאוּי לַמָּקוֹם, וְהוּא לֹא הָיָה כֵּן, אֶלָּא מְחֹלָל הָיָה מִפְּשָׁעֵינוּ וּמְדֻכָּא מֵעֲוֹנוֹתֵינוּ:\",2,0],[2,120,53,5,\"מוּסַר שְׁלוֹמֵנוּ עָלָיו. בָּאוּ עָלָיו יִסּוּרֵי הַשָּׁלוֹם שֶׁהָיָה לָנוּ, שֶׁהוּא הָיָה מְיֻסָּר לִהְיוֹת שָׁלוֹם לְכָל הָעוֹלָם:\",1,0],[2,120,53,6,\"כֻּלָּנוּ כַּצֹּאן תָּעִינוּ. עַתָּה נִגְלָה:\",1,0],[2,120,53,6,\"הִפְגִּיעַ בּוֹ. נֶעְתַּר עַל יָדוֹ וְנִתְרַצָּה עַל עֲוֹן כֻּלָּנוּ, שֶׁלֹּא הֶחְרִיב עוֹלָמוֹ. הִפְגִּיעַ אשפריאי״ר בלע״ז, לְשׁוֹן ׳תְּחִנָּה׳:\",2,0],[2,120,53,7,\"נִגַּשׂ וְהוּא נַעֲנֶה. נִגַּשׂ הִנֵּה בְּנוֹגְשִׂים וְדוֹחֲקִים:\",1,0],[2,120,53,7,\"וְהוּא נַעֲנֶה. בְּאוֹנָאַת דְּבָרִים, שורפרלרי״ן בלע״ז:\",2,0],[2,120,53,7,\"לֹא יִפְתַּח פִּיו. סוֹבֵל הָיָה וְשׁוֹתֵק, כְּמוֹ הַשֶּׂה אֲשֶׁר לַטֶּבַח יוּבָל, וּכְרָחֵל אֲשֶׁר לִפְנֵי גוֹזְזֶיהָ נֶאֱלָמָה:\",3,0],[2,120,53,7,\"לֹא יִפְתַּח פִּיו. מוּסָב עַל שֶׂה לַטֶּבַח יוּבָל:\",4,0],[2,120,53,8,\"מֵעֹצֶר וּמִמִּשְׁפָּט לֻקָּח. הַנָּבִיא מְבַשֵּׂר וְאוֹמֵר, כִּי זֹאת יֹאמְרוּ הָעוֹבְדֵי כּוֹכָבִים וּמָזָלוֹת בְּאַחֲרִית הַיָּמִים, כְּשֶׁיִּרְאוּ כְּשֶׁנִּלְקַח מִן הָעֹצֶר שֶׁהָיָה עָצוּר בְּיָדָם, וּמִמִּשְׁפָּט הַיִּסּוּרִין שֶׁסָּבַל עַד עַתָּה:\",1,0],[2,120,53,8,\"וְאֶת דּוֹרוֹ. שָׁנִים שֶׁעָבְרוּ עָלָיו:\",2,0],[2,120,53,8,\"מִי יְשׂוֹחֵחַ אֶת הַתְּלָאוֹת אֲשֶׁר מְצָאוּהוּ? כִּי נִגְזַר הָיָה מִתְּחִלָּה וְגוֹלֶה מֵאֶרֶץ חַיִּים, הִיא אֶרֶץ יִשְׂרָאֵל, אֲשֶׁר מִפֶּשַׁע עַמִּי בָּא הַנֶּגַע הַזֶּה לַצַּדִּיקִים שֶׁבָּהֶם:\",3,0],[2,120,53,9,\"וַיִּתֵּן אֶת רְשָׁעִים קִבְרוֹ מָסַר אֶת עַצְמוֹ לְהִקָּבֵר כְּכָל אֲשֶׁר יִגְזְרוּ עָלָיו רִשְׁעֵי הָאֻמּוֹת, שֶׁהָיוּ קוֹנְסִין עֲלֵיהֶם הֲרִיגָה וּקְבוּרַת חֲמוֹרִים בִּמְעֵי הַכְּלָבִים:\",1,0],[2,120,53,9,\"אֶת רְשָׁעִים. לְדַעַת הָרְשָׁעִים נִתְרַצָּה לִקָּבֵר, וְלֹא יִכְפּוֹר בֵּאלֹהִים חַיִּים:\",2,0],[2,120,53,9,\"וְאֶת עָשִׁיר בְּמֹתָיו. וּלְדַעַת הַמּוֹשֵׁל מָסַר עַצְמוֹ בְּכָל מִינֵי מָוֶת שֶׁגָּזַר עָלָיו, עַל לֹא רָצָה לְקַבֵּל עָלָיו כְּפִירָה, לַעֲשׂוֹת רָעָה וְלַחְמוֹס חָמָס כְּכָל הַגּוֹיִם אֲשֶׁר הָיָה גָּר בֵּינֵיהֶם:\",3,0],[2,120,53,9,\"וְלֹא מִרְמָה בְּפִיו. לְקַבֵּל עָלָיו עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת:\",4,0],[2,120,53,10,\"וַה׳ חָפֵץ דַּכְּאוֹ הֶחֱלִי. הַקָּדוֹשׁ בָּרוּךְ הוּא חָפֵץ לְדַכְּאוֹ וּלְהַחֲזִירוֹ לְמוּטָב, לְפִיכָךְ הֶחֱלִי אוֹתוֹ:\",1,0],[2,120,53,10,\"אִם תָּשִׂים אָשָׁם נַפְשׁוֹ וְגוֹ׳. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: אֶרְאֶה אִם תְּהֵא נַפְשׁוֹ נוֹתֶנֶת וְנִמְסֶרֶת בִּקְדוּשָׁתִי לַהֲשִׁיבָהּ לִי אָשָׁם עַל כָּל אֲשֶׁר מָעַל, אֶגְמֹל לוֹ גְּמוּלוֹ, וְיִרְאֶה זֶרַע וְגוֹ׳. אָשָׁם זֶה לְשׁוֹן ׳כֹּפֶר׳, שֶׁנּוֹתֵן אָדָם לְמִי שֶׁחָטָא לוֹ, אמינד״א בלע״ז, כְּעִנְיָן שֶׁנֶּאֱמַר בַּפְּלִשְׁתִּים (שמואל א ו:ג): ״אַל תָּשִׁיבוּ אוֹתוֹ רֵיקָם כִּי הָשֵׁב תָּשִׁיבוּ לוֹ אָשָׁם״:\",2,0],[2,120,53,11,\"מֵעֲמַל נַפְשׁוֹ. הָיָה אוֹכֵל וְשָׂבֵעַ, וְלֹא הָיָה גּוֹזֵל וְחוֹמֵס:\",1,0],[2,120,53,11,\"בְּדַעְתּוֹ יַצְדִּיק צַדִּיק. הָיָה שׁוֹפֵט עַבְדִּי מִשְׁפַּט אֱמֶת לְכָל הַבָּאִים לְדִין לְפָנָיו:\",2,0],[2,120,53,11,\"וַעֲוֺנֹתָם. הָיָה סוֹבֵל כְּדֶרֶךְ כָּל הַצַּדִּיקִים, שֶׁנֶּאֱמַר ״אַתָּה וּבָנֶיךָ תִּשְׂאוּ אֶת עֲוֹן הַמִּקְדָּשׁ״ (במדבר יח:א):\",3,0],[2,120,53,12,\"לָכֵן. עַל עֲשׂוֹתוֹ זֹאת אֲחַלֵּק לוֹ נַחֲלָה וְגוֹרָל בָּרַבִּים עִם הָאָבוֹת הָרִאשׁוֹנִים (סוטה יד א):\",1,0],[2,120,53,12,\"הֶעֱרָה לַמָּוֶת נַפְשׁוֹ. לְשׁוֹן ״וַתְּעַר כַּדָּהּ״ (בראשית כד:כ):\",2,0],[2,120,53,12,\"וְאֶת פֹּשְׁעִים נִמְנָה. סָבַל יִסּוּרִין כְּאִלּוּ חָטָא וּפָשַׁע, וְהוּא בִּשְׁבִיל אֲחֵרִים נָשָׂא חֵטְא הָרַבִּים:\",3,0],[2,120,53,12,\"וְלַפֹּשְׁעִים יַפְגִּיעַ. עַל יְדֵי יִסּוּרִין שֶׁבָּאת עַל יָדוֹ טוֹבָה לָעוֹלָם:\",4,0],[2,120,54,1,\"רָנִּי עֲקָרָה. יְרוּשָׁלַיִם, אֲשֶׁר הָיְתָה כְּלֹא יָלָדָה:\",1,0],[2,120,54,1,\"לֹא חָלָה. לְשׁוֹן לֵידָה הוּא, שֶׁהַיּוֹלֶדֶת עַל יְדֵי חִיל וַחֲבָלִים יוֹלֶדֶת:\",2,0],[2,120,54,1,\"מִבְּנֵי בְעוּלָה. בַּת אֱדוֹם:\",3,0],[2,120,54,2,\"יַטּוּ. לְמֵרָחוֹק׃\",1,0],[2,120,54,2,\"מֵיתָרַיִךְ. הֵם חֲבָלִים דַּקִּים הַתְּלוּיִם בְּשׁוּלֵי אֹהָלִים, וְקוֹשְׁרִים בִּיתֵדוֹת, שֶׁקּוֹרִין קביל״ש בלע״ז, וְתוֹקְעִין בָּאָרֶץ:\",2,0],[2,120,54,3,\"תִּפְרֹצִי. תִּגְבְּרוּ:\",1,0],[2,120,54,4,\"עֲלוּמַיִךְ. נְעוּרַיִךְ:\",1,0],[2,120,54,6,\"כִּי תִמָּאֵס. כְּשֶׁתִּמָּאֵס, פְּעָמִים שֶׁכּוֹעֵס עָלֶיהָ מְעַט:\",1,0],[2,120,54,8,\"בְּשֶׁצֶף קֶצֶף. מְנַחֵם פָּתַר: ׳חֳרִי אַף׳, וְדוֹנָשׁ אָמַר: ׳בִּמְעַט קֶצֶף׳, כְּמוֹ בְּרֶגַע קָטֹן עֲזַבְתִּיךְ, וְכֵן תִּרְגֵּם יוֹנָתָן:\",1,0],[2,120,54,8,\"וּבְחֶסֶד עוֹלָם. שֶׁיִּתְקַיֵּם עַד עוֹלָם:\",2,0],[2,120,54,9,\"כִּי מֵי נֹחַ זֹאת לִי. שְׁבוּעָה בְּיָדִי, וְהוֹלֵךְ וּמְפָרֵשׁ דְּבָרוֹ: כַּאֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבֹר מֵי נֹחַ וְגוֹ׳:\",1,0],[2,120,54,10,\"כִּי הֶהָרִים יָמוּשׁוּ. אַף אִם תִּכְלֶה זְכוּת אָבוֹת וְאִמָּהוֹת, חַסְדִּי מֵאִתֵּךְ לֹא יָמוּשׁ (ירושלמי סנהדרין י א):\",1,0],[2,120,54,11,\"סֹעֲרָה. שֶׁלִּבָּהּ סוֹעֵר בְּרוֹבֵי צָרוֹת:\",1,0],[2,120,54,11,\"מַרְבִּיץ בַּפּוּךְ. רוֹצֵף רִצְפָּתֵךְ מֵאַבְנֵי נֹפֶךְ:\",2,0],[2,120,54,12,\"כַּדְכֹד. מִין אֶבֶן טוֹבָה:\",1,0],[2,120,54,12,\"שִׁמְשֹׁתַיִךְ. יוֹנָתָן תִּרְגֵּם ״אַעָךְ״, וּמְנַחֵם חִבְּרוֹ עִם ״יְשַׁמְּשׁוּנֵהּ״ (דניאל ז:י), וְיֵשׁ פּוֹתְרִין לְשׁוֹן ׳שֶׁמֶשׁ׳ – חַלּוֹנוֹת שֶׁחַמָּה זוֹרַחַת בָּהֶן, וְעוֹשִׂין כְּנֶגְדּוֹ מְחִיצָה בְּמִינֵי זְכוּכִית צְבָעִים לְנוֹי, וּמִדְרַשׁ תְּהִלִּים פּוֹתֵר ״שִׁמְשׁוֹתַיִךְ״ וְ״שֶׁמֶשׁ וּמָגֵן״ (תהלים פד:יב) שִׁנֵּי הַחוֹמָה:\",2,0],[2,120,54,12,\"לְאַבְנֵי אֶקְדָּח. יוֹנָתָן תִּרְגֵּם ״לְאַבְנֵי גְמַר״, ׳גּוּמְרִין׳ תַּרְגּוּם ׳גֶּחָלִים׳. פָּתַר ׳אֶקְדָּח׳ לְשׁוֹן ״קֹדְחֵי אֵשׁ״ (ישעיהו נ:יא), וְהֵם מִין אֲבָנִים טוֹבוֹת בּוֹעֲרוֹת כַּלַּפִּידִים, וְהוּא קרבונקל״א לְשׁוֹן ׳גַּחֶלֶת׳. וְיֵשׁ פּוֹתְרִין (בבא בתרא עה א) לְשׁוֹן ׳מַקְדֵּחַ׳, אֲבָנִים גְּדוֹלוֹת שֶׁכָּל חֲלַל הַפֶּתַח קָדוּחַ בְּתוֹכוֹ, וְהַמְּזוּזוֹת וְהַמִּפְתָּן וְהַסַּף כֻּלָּן מִתּוֹךְ הָאֶבֶן הֵם:\",3,0],[2,120,54,12,\"לְאַבְנֵי חֵפֶץ. ״לְאַבְנֵי צְרוּךְ״ (תרגום יונתן):\",4,0],[2,120,54,14,\"רַחֲקִי מֵעֹשֶׁק. כְּמוֹ ״הִתְנַעֲרִי מֵעָפָר״ (ישעיהו נב:ב), תִּרְחֲקִי מִן הָעוֹשְׁקִים אוֹתָךְ:\",1,0],[2,120,54,14,\"(רַחֲקִי מֵעֹשֶׁק. תִּרְחֲקִי מִלַּעֲשׁוֹק בְּנֵי אָדָם כְּדֶרֶךְ שֶׁעוֹשִׂים רְשָׁעִים, שֶׁאוֹסְפִים מָמוֹן מִגָּזֵל, אֲבָל אַתֶּם לֹא תִצְטָרְכוּ לִגְזוֹל, כִּי לֹא תִירְאוּ מִדַּלּוּת וַעֲנִיּוּת, וּמִמְּחִתָּה כִּי לֹא תָבֹא וְלֹא תִקְרַב אֵלָיִךְ. אברבנאל.)\",2,0],[2,120,54,14,\"(בִּצְדָקָה. שֶׁתַּעֲשֶׂה תִּהְיֶה נְכוֹנָה בִּגְאֻלַּת עוֹלָם, וְתִהְיֶה רְחוֹקָה מֵעֹשֶׁק בְּנֵי אָדָם כִּי לֹא תִירָאִי, אֲפִילּוּ פַּחַד וְיִרְאָה לֹא יִהְיֶה לָךְ מֵהֶם, וְתִהְיֶה רְחוֹקָה מִמְּחִתָּה שֶׁלֹּא תִקְרַב אֵלָיִךְ. איל״ה שלוח״ה.)\",3,0],[2,120,54,15,\"הֵן גּוֹר יָגוּר אֶפֶס מֵאוֹתִי. הֵן יָרֵא יִירָא וְיָגוּר מְגוֹרַת רָעוֹת, אוֹתוֹ שֶׁאֵין אֲנִי עִמּוֹ, הוּא שְׂעִיר:\",1,0],[2,120,54,15,\"מִי גָר אִתָּךְ. מִי אֲשֶׁר נֶאֱסַף עָלֶיךָ לְמִלְחָמָה, אוֹ מִי גָר – מִי שֶׁנִּתְגָּרָה בָּךְ. וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ (יבמות כד ב) בְּגֵרִים, לוֹמַר שֶׁאֵין מְקַבְּלִים גֵּרִים לִימוֹת מְשִׁיחֵנוּ. וְאַף בִּפְשׁוּטוֹ שֶׁל מִקְרָא יִתָּכֵן: מִי שֶׁנַּעֲשׂוּ גֵרִים אִתָּךְ בַּעֲנִיּוּתֵךְ, עָלַיִךְ יִפֹּל בְּעֲשִׁירוּתֵךְ, כְּמוֹ ״עַל פְּנֵי כָל אֶחָיו נָפָל״ (בראשית כה:יח):\",2,0],[2,120,54,16,\"הִנֵּה אָנֹכִי. אֲשֶׁר בָּרָאתִי חָרָשׁ הַמְּתַקֵּן כְּלִי, וַאֲנִי אֲשֶׁר בָּרָאתִי מַשְׁחִית הַמְחַבְּלוֹ, כְּלוֹמַר: אֲנִי הוּא שֶׁגֵּרִיתִי בָּךְ אֶת הָאוֹיֵב, אֲנִי הוּא שֶׁהִתְקַנְתִּי לוֹ פֻּרְעָנִיּוֹת:\",1,0],[2,120,54,16,\"וּמוֹצִיא כְלִי לְמַעֲשֵׂהוּ. לְצֹרֶךְ, גּוֹמְרוֹ כָּל צָרְכּוֹ:\",2,0],[2,120,54,17,\"כָּל כְּלִי יוּצַר. כָּל כְּלִי זַיִן אֲשֶׁר יִלְטְשׁוּהוּ וִיחַדְּדוּהוּ בִּשְׁבִילֵךְ לְהִלָּחֵם בָּךְ:\",1,0],[2,120,54,17,\"יוּצַר. לְשׁוֹן ״חַרְבוֹת צוּרִים״ (יהושע ה:ב), ״אַף תָּשִׁיב צוּר חַרְבּוֹ״ (תהלים פט:מד):\",2,0],[2,120,55,1,\"הוֹי כָּל צָמֵא. הוֹי זֶה, לְשׁוֹן קְרִיאָה וְזִמּוּן וְקִבּוּץ הוּא, וְיֵשׁ הַרְבֵּה בַּמִּקְרָא: ״הוֹי הוֹי וְנֻסוּ מֵאֶרֶץ צָפוֹן״ (זכריה ב:י):\",1,0],[2,120,55,1,\"לְכוּ לַמַּיִם. לַתּוֹרָה:\",2,0],[2,120,55,1,\"שִׁבְרוּ. לְשׁוֹן ״לִשְׁבֹּר בָּר״ (בראשית מב:ג), קְנוּ:\",3,0],[2,120,55,1,\"יַיִן וְחָלָב. לֶקַח טוֹב מִיַּיִן וְחָלָב:\",4,0],[2,120,55,2,\"לָמָּה תִשְׁקְלוּ כֶסֶף. לָמָּה תִּגְרְמוּ לָכֶם לִשְׁקוֹל כֶּסֶף לְאוֹיְבֵיכֶם בְּלֹא לֶחֶם? (ויקרא רבה ל א)\",1,0],[2,120,55,3,\"חַסְדֵי דָוִד. שֶׁאֶגְמוֹל לְדָוִד חֲסָדָיו:\",1,0],[2,120,55,4,\"לְאוּמִּים. שַׂר וְגָדוֹל עֲלֵיהֶם, וּמוֹכִיחַ וּמֵעִיד דַּרְכֵיהֶם עַל פְּנֵיהֶם:\",1,0],[2,120,55,5,\"הֵן גּוֹי לֹא תֵדַע תִּקְרָא. לְשִׁמּוּשָׁךְ, אִם אֵלַי תִּשְׁמְעוּ, לְשֵׁם ה׳ הַנִּקְרָא עָלֶיךָ:\",1,0],[2,120,55,6,\"בְּהִמָּצְאוֹ. קֹדֶם גְּזַר דִּין, בְּעוֹד שֶׁהוּא אוֹמֵר לָכֶם ״דִּרְשׁוּנִי״:\",1,0],[2,120,55,8,\"כִּי לֹא מַחְשְׁבוֹתַי מַחְשְׁבוֹתֵיכֶם. אֵין שֶׁלִּי וְשֶׁלָּכֶם שָׁווֹת, לְכָךְ אֲנִי אוֹמֵר לָכֶם יַעֲזֹב רָשָׁע דַּרְכּוֹ, וְיִתְפֹּשׂ אֶת דַּרְכִּי:\",1,0],[2,120,55,8,\"וְאִישׁ אָוֶן מַחְשְׁבֹתָיו, וְיִתְפֹּשׂ אֶת מַחְשְׁבוֹתַי לַעֲשׂוֹת הַטּוֹב בְּעֵינַי. וּמִדְרַשׁ אַגָּדָה (תנחומא בובר וישב יא): כִּי לֹא מַחְשְׁבוֹתַי וְגוֹ׳ אֵין דִּינִי כְּדִינֵי בָּשָׂר וָדָם: אַתֶּם, מִי שֶׁמּוֹדֶה בַּדִּין מִתְחַיֵּב, אֲבָל אֲנִי ״מוֹדֶה וְעוֹזֵב יְרֻחָם״ (משלי כח:יג):\",2,0],[2,120,55,9,\"כִּי גָבְהוּ שָׁמַיִם וגו׳. כְּלוֹמַר, כִּי יֵשׁ הֶבְדֵּל וְחִלּוּק מַעֲלוֹת וְשֶׁבַח בִּדְרָכַי יוֹתֵר מִדַּרְכֵיכֶם וּבְמַחְשְׁבוֹתַי יוֹתֵר מִמַּחְשְׁבוֹתֵיכֶם, כְּגָבוֹהַּ שָׁמַיִם עַל הָאָרֶץ. אַתֶּם נוֹתְנִים לֵב לִמְרוֹד בִּי, וַאֲנִי נוֹתֵן לֵב לְהָשִׁיב אֶתְכֶם:\",1,0],[2,120,55,10,\"כִּי כַּאֲשֶׁר יֵרֵד הַגֶּשֶׁם וְהַשֶּׁלֶג. וְלֹא יָשׁוּב רֵיקָם, אַךְ יֵיטִיב לָעוֹלָם:\",1,0],[2,120,55,11,\"כֵּן יִהְיֶה דְבָרִי אֲשֶׁר יֵצֵא מִפִּי. לְהוֹדִיעֲכֶם עַל יְדֵי הַנְּבִיאִים לֹא יָשׁוּב רֵיקָם, אַךְ יֵיטִיב לָכֶם אִם תִּשְׁמְעוּ לָהֶם:\",1,0],[2,120,55,12,\"כִּי בְשִׂמְחָה תֵצֵאוּ. מִן הַגָּלוּת:\",1,0],[2,120,55,12,\"הֶהָרִים וְהַגְּבָעוֹת יִפְצְחוּ לִפְנֵיכֶם רִנָּה. שֶׁיִּתְּנוּ לָכֶם פִּרְיָם וְצִמְחָם, וְיֵהָנוּ (יְרוֹנְנוּ) יוֹשְׁבֵיהֶם:\",2,0],[2,120,55,13,\"תַּחַת הַנַּעֲצוּץ וְגוֹ׳. רַבּוֹתֵינוּ דָּרְשׁוּ: תַּחַת הָרְשָׁעִים יַעֲלוּ צַדִּיקִים:\",1,0],[2,120,55,13,\"נַעֲצוּץ וְסִרְפַּד – מִינֵי קוֹצִים הֵם, כְּלוֹמַר: הָרְשָׁעִים יֹאבְדוּ וְהַצַּדִּיקִים יִטְּלוּ מֶמְשַׁלְתָּם (מגילה י ב):\",2,0],[2,120,56,2,\"יַעֲשֶׂה זֹּאת. שׁוֹמֵר שַׁבָּת וְגוֹ׳:\",1,0],[2,120,56,3,\"הַבְדֵּל יַבְדִּילַנִי ה׳ מֵעַל עַמּוֹ. לָמָּה אֶתְגַּיֵּר? הֲלֹא הַקָּדוֹשׁ בָּרוּךְ הוּא יַבְדִּילֵנִי מֵעַל עַמּוֹ כְּשֶׁיְשַׁלֵּם שְׂכָרָם:\",1,0],[2,120,56,3,\"וְאַל יֹאמַר הַסָּרִיס. לָמָּה אֵיטִיב דְּרָכַי וּמַעֲלָלַי? הֵן אֲנִי כְּעֵץ יָבֵשׁ, מֵאֵין זִכָּרוֹן:\",2,0],[2,120,56,4,\"וּמַחֲזִיקִים. אוֹחֲזִים:\",1,0],[2,120,56,7,\"לְכָל הָעַמִּים. וְלֹא לְיִשְׂרָאֵל לְבַדָּם, כִּי אַף לַגֵּרִים:\",1,0],[2,120,56,8,\"עוֹד אֲקַבֵּץ עָלָיו. מִן הָאֻמּוֹת שֶׁיִּתְגַּיְּרוּ וְנִלְווּ עֲלֵיהֶם:\",1,0],[2,120,56,8,\"לְנִקְבָּצָיו. נוֹסָפִים עַל קִבּוּצֵי יִשְׂרָאֵל:\",2,0],[2,120,56,9,\"כֹּל חַיְתוֹ שָׂדָי. כָּל גֵּרֵי הָאֻמּוֹת, אֵתָיוּ וְהִתְקָרְבוּ אֵלַי, וְתֹאכְלוּ אֶת כָּל חַיְתוֹ בַּיָּעַר, אֶת גִּבּוֹרֵי הָאֻמּוֹת שֶׁאִמְּצוּ אֶת לִבָּם מִלְּהִתְגַּיֵּר:\",1,0],[2,120,56,9,\"חַיְתוֹ שָׂדָי. חַיַּת הַשָּׂדֶה אֵין כֹּחָהּ רַב כְּחַיַּת הַיַּעַר, חַיַּת הַשָּׂדֶה חֲלָשָׁה וְתַשּׁוּשַׁת כֹּחַ מֵחַיַּת הַיַּעַר, וְעַל שֶׁאָמַר עוֹד אֲקַבֵּץ עָלָיו אָמַר הַמִּקְרָא הַזֶּה:\",2,0],[2,120,56,10,\"צֹפָיו עִוְרִים כֻּלָּם. לְפִי שֶׁאָמַר ״דִּרְשׁוּ ה׳״ (ישעיהו נה:ו) וְכָל הָעִנְיָן, וְהֵם אֵינָם שׁוֹמְעִים, חוֹזֵר וְאוֹמֵר: הִנֵּה הַנְּבִיאִים צוֹעֲקִים לָהֶם וּמַכְרִיזִים עַל הַתְּשׁוּבָה וְתֵיטִיב לָהֶם, וַהֲרֵי פַּרְנָסֵיהֶם כְּעִוְרִים כֻּלָּם, וְאֵינָם רוֹאִין אֶת הַנּוֹלָדוֹת, כְּצוֹפֶה הַמֻּפְקָד לִרְאוֹת אֶת הַחֶרֶב בָּא לְהַזְהִיר אֶת הָעָם, וְהוּא עִוֵּר מִלִּרְאוֹת אֶת הַחֶרֶב בָּאָה וְאִלֵּם מִלְּהַזְהִיר אֶת הָעָם, כַּכֶּלֶב שֶׁמִּנּוּהוּ לִשְׁמֹר הַבַּיִת וְהוּא אִלֵּם מִלִּנְבֹּחַ, כָּךְ פַּרְנָסֵי יִשְׂרָאֵל אֵינָם מַזְהִירִין אוֹתָם לַחֲזוֹר לַמּוּטָב:\",1,0],[2,120,56,10,\"הֹזִים שֹׁכְבִים. פֵּירֵשׁ דּוּנָשׁ: נִרְדָּמִים שׁוֹכְבִין, וְיוֹנָתָן תִּרְגֵּם: ״נַיְימִין שָׁכְבִין״, וְאֵין לוֹ דִּמְיוֹן:\",2,0],[2,120,56,11,\"וְהַכְּלָבִים עַזֵּי נֶפֶשׁ. רוֹצִים לְמַלֹּאות כְּרֵסָם (אינגר״ש בלע״ז):\",1,0],[2,120,56,11,\"וְהֵמָּה רֹעִים. כְּמוֹ שֶׁהַכְּלָבִים לֹא יָדְעוּ שָׂבְעָה, כֵּן הָרֹעִים לֹא יָדְעוּ הָבִין מַה יִּהְיֶה בְּאַחֲרִית הַיָּמִים:\",2,0],[2,120,56,11,\"כֻּלָּם. לְדֶרֶךְ הֲנָיָתָם פָּנוּ אִישׁ לְבִצְעוֹ, לִגְזוֹל אֶת שְׁאָר הָעָם שֶׁהֵם מְמֻנִּים עֲלֵיהֶם:\",3,0],[2,120,56,11,\"מִקָּצֵהוּ. כְּמוֹ ״כָּל הָעָם מִקָּצֶה״ (בראשית יט:ד), מִקְצֵה מִנְיָנָם וְעַד קָצֵהוּ, כֻּלָּם נוֹהֲגִים כֵּן:\",4,0],[2,120,56,12,\"אֵתָיוּ אֶקְחָה יַיִן. כָּךְ הָיוּ אוֹמְרִים זֶה לָזֶה:\",1,0],[2,120,56,12,\"וְהָיָה כָזֶה יוֹם מָחָר. בְּמַאֲכָל וּבְמִשְׁתֶּה:\",2,0],[2,120,57,1,\"הַצַּדִּיק אָבָד. כְּגוֹן יֹאשִׁיָּהוּ:\",1,0],[2,120,57,1,\"וְאֵין אִישׁ שָׂם עַל לֵב. לָמָּה נִסְתַּלֵּק:\",2,0],[2,120,57,1,\"בְּאֵין מֵבִין. אֵין בַּנּוֹתָרִים מֵבִין, מָה רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְסַלְּקוֹ:\",3,0],[2,120,57,1,\"כִּי מִפְּנֵי הָרָעָה הָעֲתִידָה לָבוֹא אֶל הַדּוֹר נֶאֱסַף הַצַּדִּיק:\",4,0],[2,120,57,2,\"יָבֹא שָׁלוֹם. כִּי כֵן אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: יָבֹא הַצַּדִּיק הַזֶּה אֶל אֲבוֹתָיו בְּשָׁלוֹם וְאַל יִרְאֶה בָּרָעָה:\",1,0],[2,120,57,2,\"יָנוּחוּ עַל מִשְׁכְּבוֹתָם. בִּהְיוֹת הָרָעָה, זֶה שֶׁהָיָה הֹלֵךְ נְכֹחוֹ בְּיָשְׁרוֹ, כְּמוֹ ״עֲשׂוֹת נְכֹחָה״ (עמוס ג:י):\",2,0],[2,120,57,3,\"וְאַתֶּם קִרְבוּ הֵנָּה. הַנּוֹתָרִים מִשֶּׁנִּסְתַּלְּקוּ הַצַּדִּיקִים, וּתְקַבְּלוּ פֻּרְעָנוּתֵיכֶם:\",1,0],[2,120,57,3,\"בְּנֵי עֹנְנָה. בְּנֵי כְּשָׁפִים:\",2,0],[2,120,57,3,\"זֶרַע מְנָאֵף. שֶׁהַזָּכָר מְנָאֵף:\",3,0],[2,120,57,3,\"וַתִּזְנֶה. הַנְּקֵבָה:\",4,0],[2,120,57,4,\"עַל מִי תִּתְעַנָּגוּ. מֵאַחַר שֶׁשַּׁבְתֶּם מֵאַחֲרַי, עַל מִי תִּשָּׁעֲנוּ לְהִתְעַנֵּג בְּטוֹבָה? אִלּוּ זְכִיתֶם, אָז תִּתְעַנְּגוּ עַל ה׳, אֲבָל עַכְשָׁיו עַל מִי תִּתְעַנָּגוּ?\",1,0],[2,120,57,4,\"עַל מִי תַּרְחִיבוּ פֶה. כְּשֶׁאַתֶּם מְתַעְתְּעִים וּמַלְעִיבִים בִּנְבִיאָיו:\",2,0],[2,120,57,5,\"הַנֵּחָמִים בָּאֵלִים. הַמִּתְחַמְּמִין בְּשִׁכְבַת זֶרַע תַּחַת אֵלָה וְאַלּוֹן (נידה יג א):\",1,0],[2,120,57,5,\"שׁוֹחֲטֵי הַיְלָדִים. לְקָרְבַּן עֲבוֹדָה זָרָה:\",2,0],[2,120,57,5,\"סְעִפֵי. נִקְרַת הַצּוּרִים, וְכֵן (שופטים טו:יא) ״אֶל סְעִיף סֶלַע״:\",3,0],[2,120,57,6,\"בְּחַלְּקֵי נַחַל. אֲבָנִים אֲשֶׁר בַּנַּחַל:\",1,0],[2,120,57,6,\"חֶלְקֵךְ. בָּהֶם יִרְגְּמוּ אוֹתָךְ:\",2,0],[2,120,57,6,\"הֵם הֵם גּוֹרָלֵךְ. לְהִתְעַצֵּב בָּהֶם. לָמָּה? כִּי גַּם לָהֶם שָׁפַכְתְּ נֶסֶךְ:\",3,0],[2,120,57,6,\"הַעַל אֵלֶּה אֶנָּחֵם. מִלְּהָרַע לָךְ?\",4,0],[2,120,57,7,\"שַׂמְתְּ מִשְׁכָּבֵךְ. מִשְׁכַּב נֵאוּפֵךְ לְעֲבוֹדָה זָרָה עַל הֶהָרִים הָרָמִים:\",1,0],[2,120,57,8,\"וְאַחַר הַדֶּלֶת וְהַמְּזוּזָה שַׂמְתְּ זִכְרוֹנֵךְ. לְמִי שֶׁהוּא מְדַמֶּה אוֹתָהּ לְאִשָּׁה מְנָאֶפֶת, אֲשֶׁר נוֹאֲפֶיהָ צוֹפִים וּמַמְתִּינִים לִפְנֵי פֶּתַח בֵּיתָהּ, וְהִיא לִבָּהּ וְזִכְרוֹנָהּ אֶל הַדֶּלֶת וְהַמְּזוּזָה, אֵיךְ תִּפְתַּח וְתֵצֵא אֲלֵיהֶם:\",1,0],[2,120,57,8,\"כִּי מֵאִתִּי גִּלִּית וַתַּעֲלִי. אֶצְלִי הָיִית שׁוֹכֶבֶת, וְגִלִּית הַכִּסּוּי שֶׁהָיוּ מְכֻסִּים יַחַד, וַתַּעֲלִי מֵאֶצְלִי:\",2,0],[2,120,57,8,\"הִרְחַבְתְּ מִשְׁכָּבֵךְ. לְקַבֵּל בּוֹ נוֹאֲפִים הַרְבֵּה:\",3,0],[2,120,57,8,\"וַתִּכְרָת לָךְ בְּרִית מֵהֶם:\",4,0],[2,120,57,8,\"אָהַבְתְּ מִשְׁכָּבָם. כְּשֶׁחָזִית לָךְ יָד וּמָקוֹם לְהַרְאוֹת לָהֶם אַהֲבָתֵךְ:\",5,0],[2,120,57,8,\"יָד. אייש״י בלע״ז, וְכֵן ״רְאוּ חֶלְקַת יוֹאָב אֶל יָדִי״ (שמואל ב יד:ל):\",6,0],[2,120,57,9,\"וַתָּשֻׁרִי לַמֶּלֶךְ בַּשֶּׁמֶן. וַאֲנִי מִתְּחִלָּה גִּדַּלְתִּיךְ, וְהָיִית מְקַבֶּלֶת פְּנֵי מַלְכֵּךְ בְּכָל מִינֵי תַּפְנוּקִים. וַתָּשֻׁרִי לְשׁוֹן רְאִיַּת פָּנִים, כְּמוֹ ״אֲשׁוּרֶנּוּ וְלֹא קָרוֹב״ (במדבר כד:יז), וְכֵן ״וּתְשׁוּרָה אֵין לְהָבִיא״ (שמואל א ט:ז) דּוֹרוֹן שֶׁל הַקְבָּלַת פָּנִים:\",1,0],[2,120,57,9,\"וַתְּשַׁלְּחִי צִרַיִךְ. שְׁלוּחַיִךְ לְמֵרָחוֹק, לִגְבּוֹת מַס מִמַּלְכֵי הָאֻמּוֹת:\",2,0],[2,120,57,9,\"וַתַּשְׁפִּילִי. אֶת חִזְקֵי הָאֻמּוֹת עַד שְׁאוֹל; כֵּן תִּרְגְּמוֹ יוֹנָתָן:\",3,0],[2,120,57,10,\"בְּרֹב דַּרְכֵּךְ יָגַעַתְּ. נִתְעַסַּקְתְּ בִּצְרָכַיִךְ לְמַלֹּאת תַּאֲוָתֵךְ לְהַרְבּוֹת הוֹנֵךְ:\",1,0],[2,120,57,10,\"לֹא אָמַרְתְּ נוֹאָשׁ. אֶתְיָאֵשׁ מֵאֵלּוּ וְלֹא אָחוּשׁ עוֹד לַעֲסוֹק בָּהֶן, כִּי בַּתּוֹרָה וּבַמִּצְווֹת אֶתֵּן לֵב:\",2,0],[2,120,57,10,\"חַיַּת יָדֵךְ מָצָאת. צֹרֶךְ יָדֵךְ מָצָאת, הִצְלַחְתְּ בְּמַעֲשַׂיִךְ:\",3,0],[2,120,57,10,\"עַל כֵּן לֹא חָלִית. לֹא נֶחֱלָה לִבֵּךְ לִדְאֹג עַל עֲבוֹדָתִי, לַעֲסֹק בַּתּוֹרָה. חַיַּת – לְשׁוֹן עֲרָבִי הוּא: צֹרֶךְ:\",4,0],[2,120,57,11,\"וְאֶת מִי דָּאַגְתְּ. מִמִּי נִתְיָרֵאת?\",1,0],[2,120,57,11,\"כִּי תְכַזֵּבִי. כִּי פָּסַקְתְּ לָךְ מֵעֲבוֹדָתִי וְכָזַבְתְּ בִּי, כְּמוֹ ״לֹא יְכַזְּבוּ מֵימָיו״ (ישעיהו נח:יא), ״כָּל הָאָדָם כֹּזֵב״ (תהלים קטז:יא). פליינצ״א בלע״ז, וְכֵן כָּל לְשׁוֹן ׳כָּזָב׳ – מִי שֶׁבּוֹטְחִין עָלָיו וְהוּא כּוֹזֵב וּבוֹגֵד:\",2,0],[2,120,57,11,\"הֲלֹא אֲנִי מַחְשֶׁה. שֶׁהֶחֱשֵׁיתִי עַל כַּמָּה פְּשָׁעִים שֶׁפָּשַׁעְתְּ בִּי:\",3,0],[2,120,57,12,\"אֲנִי אַגִּיד צִדְקָתֵךְ. אֲנִי תָּמִיד מַגִּיד לָךְ דְּבָרִים, שֶׁאִם תַּעֲשִׂי אוֹתָם תִּצְדְּקִי:\",1,0],[2,120,57,12,\"וְאֶת מַעֲשַׂיִךְ. שֶׁאַתָּה עוֹשֶׂה שֶׁלֹּא בִּרְצוֹנִי, לֹא יוֹעִילוּךְ בְּעֵת רָעָתֵךְ:\",2,0],[2,120,57,13,\"בְּזַעֲקֵךְ יַצִּילוּךְ קִבּוּצַיִךְ. יָקוּמוּ נָא קְבוּצוֹת אֱלִילִים וּפְסִילִים וּמַכְחִישֵׁי תּוֹרָה אֲשֶׁר קִבַּצְתָּ, וְיַצִּילוּךְ בְּזַעֲקֵךְ מִצָּרָתֵךְ. הֲלֹא אֶת כֻּלָּם יִשָּׂא רוּחַ וְלֹא יוּכְלוּ לְהַצִּיל:\",1,0],[2,120,57,14,\"וְאָמַר סֹלּוּ סֹלּוּ. כֹּה אָמַר הַנָּבִיא בִּשְׁמִי לְעַמִּי: כִּבְשׁוּ מְסִלָּה סְלוּלָה, פַּנּוּ יֵצֶר הָרַע מִדַּרְכֵיכֶם (סוכה נב א):\",1,0],[2,120,57,14,\"הָרִימוּ מִכְשׁוֹל. סַלְּקוּ הָאֲבָנִים שֶׁאַתֶּם נִכְשָׁלִים רַגְלֵיכֶם בָּהֶם, הֵם הִרְהוּרֵי רֶשַׁע:\",2,0],[2,120,57,15,\"מָרוֹם וְקָדוֹשׁ אֲנִי שֹׁכֵן, וּמִשָּׁם אֲנִי עִם דַּכָּא וּשְׁפַל רוּחַ, שֶׁאֲנִי מַרְכִּין שְׁכִינָתִי עָלָיו:\",1,0],[2,120,57,15,\"שְׁפָלִים. נִדְכָּאִים, סוֹבְלֵי עֹנִי וָחֳלָיִים:\",2,0],[2,120,57,16,\"כִּי לֹא לְעוֹלָם אָרִיב. אִם אָבִיא יִסּוּרִין עַל הָאָדָם, אֵין תַּחֲרוּתִי עָלָיו לְאֹרֶךְ יָמִים, וְלֹא קִצְפִּי לָנֶצַח:\",1,0],[2,120,57,16,\"כִּי רוּחַ מִלְּפָנַי יַעֲטוֹף. כַּאֲשֶׁר רוּחַ הָאָדָם, שֶׁהוּא מִלְּפָנַי שֶׁנִּתַּן בּוֹ מֵאִתִּי, יַעֲטוֹף יוֹדֶה וְיִכָּנַע עַל מַעֲלוֹ, כְּמוֹ (איכה ב:יט) ״הָעֲטוּפִים בָּרָעָב״, ״בֵּעָטֵף עוֹלֵל״ (שם), וְהַנְּשָׁמוֹת שֶׁאֲנִי עָשִׂיתִי:\",2,0],[2,120,57,16,\"כִּי רוּחַ מִלְּפָנַי. ׳כִּי׳ זֶה מְשַׁמֵּשׁ בִּלְשׁוֹן ׳כַּאֲשֶׁר׳, כְּמוֹ ״כִּי תִרְאֶה״ (שמות כג:ה), ״כִּי תָבוֹא״ (דברים כג:כה). כְּלוֹמַר: כְּשֶׁרוּחוֹ נֶעֱטֶפֶת וְהוּא נִכְנָע, אֲנִי מְבַטֵּל רִיבִי וְקִצְפִּי מֵעָלָיו:\",3,0],[2,120,57,17,\"בַּעֲוֺן בִּצְעוֹ. גְּזֵלָתוֹ:\",1,0],[2,120,57,17,\"קָצַפְתִּי. תְּחִלָּה וְאַכֵּהוּ, הַסְתֵּר פָּנַי תָּמִיד מִצָּרָתוֹ, וְאֶקְצֹף, וְעַל כִּי הוֹלֵךְ שׁוֹבָב בְּדֶרֶךְ לִבּוֹ. וְסָרֵס אֶת הַמִּקְרָא וְכֵן פֵּרוּשׁוֹ: בַּעֲוֺן בִּצְעוֹ וַיֵּלֶךְ שׁוֹבָב בְּדַרְכֵי לִבּוֹ קָצַפְתִּי וְאַכֵּהוּ:\",2,0],[2,120,57,18,\"דְּרָכָיו רָאִיתִי. כְּשֶׁהוּא נִכְנָע מִלְּפָנַי שֶׁבָּאַתְהוּ צָרָה:\",1,0],[2,120,57,18,\"וְאֶרְפָּאֵהוּ וְאַנְחֵהוּ. אוֹלִיכוֹ בְּדֶרֶךְ מַרְפֵּא, אוֹ וְאַנְחֵהוּ לְשׁוֹן הֲנָחָה וּמַרְגּוֹעַ:\",2,0],[2,120,57,18,\"לוֹ וְלַאֲבֵלָיו. לַמִּצְטַעֲרִים עָלָיו:\",3,0],[2,120,57,19,\"בּוֹרֵא נִיב שְׂפָתָיִם. בּוֹרֵא אֲנִי לוֹ נִיב שְׂפָתַיִם חָדָשׁ, כְּלַפֵּי שֶׁבָּאַתְהוּ צָרָה עַד עַתָּה, וְהַכֹּל קָרְאוּ עָלָיו תִּגָּר, יִקְרְאוּ לוֹ: שָׁלוֹם שָׁלוֹם:\",1,0],[2,120,57,19,\"לָרָחוֹק וְלַקָּרוֹב. שְׁנֵיהֶם שָׁוִין: מִי שֶׁנִּתְיַשֵּׁן וְהֻרְגַּל בְּתוֹרָתִי וַעֲבוֹדָתִי מִנְּעוּרָיו, וּמִי שֶׁנִּתְקָרֵב עַתָּה מִקָּרוֹב לָשׁוּב מִדַּרְכּוֹ הָרָעָה (ברכות לד ב). אָמַר ה׳ וּרְפָאתִיו מֵחָלְיוֹ וּמֵחֲטָאָיו:\",2,0],[2,120,57,20,\"וְהָרְשָׁעִים. שֶׁאֵין נוֹתְנִין לֵב לָשׁוּב:\",1,0],[2,120,57,20,\"כַּיָּם נִגְרָשׁ. הַיָּם הַזֶּה גַּלָּיו מִתְגָּאִים לָרוּם לְמַעְלָה וְלָצֵאת חוּץ לִגְבוּל הַחוֹל ״אֲשֶׁר שַׂמְתִּי גְּבוּל לַיָּם״ (ירמיהו ה:כב), וּכְשֶׁמַּגִּיעַ שָׁם הוּא נִשְׁבָּר עַל כָּרְחוֹ, וְכָל זֶה גַּל חֲבֵרוֹ רוֹאֶה וְאֵינוֹ חוֹזֵר בּוֹ. כָּךְ הָרָשָׁע רוֹאֶה אֶת חֲבֵרוֹ לוֹקֶה בְּרִשְׁעוֹ וְאֵינוֹ חוֹזֵר בּוֹ. וּמָה הַיָּם רִפְשׁוֹ וְסִרְיוֹתוֹ עַל פִּיו, כָּךְ הָרְשָׁעִים סִרְיוֹתָם בְּפִיהֶם; כְּגוֹן פַּרְעֹה אָמַר ״מִי ה׳״ (שמות ה:ב), סַנְחֵרִיב אָמַר ״מִי בְּכָל אֱלֹהֵי הָאֲרָצוֹת״ (ישעיהו לו:כ), נְבוּכַדְנֶצַּר אָמַר ״אֶדַּמֶּה לְעֶלְיוֹן״ (ישעיהו יד:יד):\",2,0],[2,120,57,20,\"כַּיָּם נִגְרָשׁ. כְּיָם אֲשֶׁר נִגְרָשׁ, שֶׁגּוֹרֵשׁ כָּל הַיּוֹם רֶפֶשׁ וָטִיט:\",3,0],[2,120,57,21,\"אֵין שָׁלוֹם. כְּלַפֵּי שֶׁאָמַר לַצַּדִּיקִים וּלְבַעֲלֵי תְּשׁוּבָה ״שָׁלוֹם שָׁלוֹם לָרָחוֹק וְגוֹ׳״ (ישעיהו נז:יט), חָזַר וְאָמַר ״אֵין שָׁלוֹם לָרְשָׁעִים״:\",1,0],[2,120,58,1,\"וְהַגֵּד לְעַמִּי פִּשְׁעָם. אֵלּוּ תַּלְמִידֵי חֲכָמִים, שֶׁכָּל שִׁגְגָתָם פֶּשַׁע, שֶׁשִּׁגְגַת תַּלְמוּד עוֹלָה זָדוֹן:\",1,0],[2,120,58,1,\"וּלְבֵית יַעֲקֹב חַטֹּאתָם. אֵלּוּ עַמֵּי הָאָרֶץ, שֶׁאַף זְדוֹנָם שְׁגָגָה (בבא מציעא לג ב):\",2,0],[2,120,58,2,\"וְאוֹתִי יוֹם יוֹם יִדְרֹשׁוּן. כְּעִנְיָן שֶׁנֶּאֱמַר ״וַיְפַתּוּהוּ בְּפִיהֶם״ (תהלים עח:לו):\",1,0],[2,120,58,2,\"וְדַעַת דְּרָכַי יֶחְפָּצוּן. חֲפֵצִים לִשְׁאוֹל הוֹרָאוֹת לַחֲכָמִים, כְּאִלּוּ רוֹצִים לְקַיְּמָם:\",2,0],[2,120,58,2,\"כְּגוֹי אֲשֶׁר צְדָקָה עָשָׂה וגו׳. כָּךְ שׁוֹאֲלִים אוֹתִי תָּמִיד מִשְׁפַּט צֶדֶק, וְאֵין דַּעְתָּם לְקַיְּמָם. וּכְשֶׁהֵן צָמִים וְאֵין נַעֲנִין, אוֹמְרִים: לָמָּה צַמְנוּ וְלֹא רָאִיתָ? וַאֲנִי אוֹמֵר: הֵן בְּיוֹם צוֹמְכֶם תִּמְצְאוּ חֵפֶץ – כָּל חֶפְצֵי צָרְכֵיכֶם אַתֶּם עֲמֵלִים לִמְצוֹא, וְאַף בְּגָזֵל וְחָמָס:\",3,0],[2,120,58,3,\"וְכָל עַצְּבֵיכֶם. בַּעֲלֵי חוֹב שֶׁלָּכֶם, הַנֶּעֱצָבִים עַל יֶדְכֶם, אַתֶּם נוֹגְשִׂים אוֹתָם בְּיוֹם צֹמְכֶם:\",1,0],[2,120,58,4,\"לֹא תָצוּמוּ כַיּוֹם. כְּמִשְׁפַּט הַיּוֹם, לִשְׁבּוֹר לְבַבְכֶם כְּדֵי שֶׁיִּשָּׁמַע קוֹלְכֶם בַּמָּרוֹם:\",1,0],[2,120,58,5,\"הֲלָכֹף. הֵ״א זוֹ תְּמִיהָא, כְּלוֹמַר: שֶׁמָּא לָכֹף כְּאַגְמוֹן רֹאשׁוֹ אֲנִי צָרִיךְ? אַגְמוֹן הוּא כְּמִין מַחַט כָּפוּף, וְצָדִין בּוֹ דָּגִים וְקוֹרִין לוֹ איי״ם בלע״ז:\",1,0],[2,120,58,5,\"הֲלָזֶה תִּקְרָא צוֹם. לְשׁוֹן תְּמִיהָא, לְפִיכָךְ הַהֵ״א נְקוּדָה חֲטַף פַּתַּח:\",2,0],[2,120,58,6,\"חַרְצֻבּוֹת. לְשׁוֹן קִשּׁוּר וְאִסּוּר:\",1,0],[2,120,58,6,\"מוֹטָה. הַטָּיַת מִשְׁפָּט:\",2,0],[2,120,58,6,\"וְכָל מוֹטָה תְּנַתֵּקוּ. תִּרְגֵּם יוֹנָתָן: ״וְכָל דִּין מַסְטֵי תְּסַלְּקוּן״:\",3,0],[2,120,58,7,\"וַעֲנִיִּים מְרוּדִים. נֶאֱנָחִים וְנֶאֱנָקִים עַל צָרָתָם, כְּגוֹן ״עָנְיִי וּמְרוּדִי״ (איכה ג:יט), ״אָרִיד בְּשִׂיחִי״ (תהלים נה:ג):\",1,0],[2,120,58,7,\"וּמִבְּשָׂרְךָ. וּמִקְּרוֹבְךָ:\",2,0],[2,120,58,8,\"יִבָּקַע כַּשַּׁחַר. כְּעַמּוּד הַשַּׁחַר הַבּוֹקֵעַ בֶּעָבִים:\",1,0],[2,120,58,8,\"וַאֲרֻכָתְךָ מְהֵרָה. וּרְפוּאָתְךָ מְהֵרָה, כְּמוֹ ״אַעֲלֶה אֲרֻכָה לָךְ״ (ירמיהו ל:יז):\",2,0],[2,120,58,10,\"וְתָפֵק לָרָעֵב נַפְשֶׁךָ. בְּתַנְחוּמֵי דְּבָרִים טוֹבִים (בבא בתרא ט ב):\",1,0],[2,120,58,11,\"בְּצַחְצָחוֹת. בְּעֵת צִמָּאוֹן וּבַצּוֹרֶת; כָּךְ תִּרְגֵּם יוֹנָתָן:\",1,0],[2,120,58,11,\"יַחֲלִיץ. יְזַיֵּן, כְּמוֹ ״חֲלוּצֵי צָבָא״ (במדבר לא:ה):\",2,0],[2,120,58,12,\"מְשׁוֹבֵב נְתִיבוֹת לָשָׁבֶת. תִּרְגֵּם יוֹנָתָן: ״מְתִיב רַשִׁיעַיָּא לְאוֹרַיְיתָא״:\",1,0],[2,120,58,12,\"מְשׁוֹבֵב. כְּמוֹ ׳מֵשִׁיב׳:\",2,0],[2,120,58,12,\"לָשָׁבֶת. לְיִשּׁוּבוֹ שֶׁל עוֹלָם:\",3,0],[2,120,58,14,\"נַחֲלַת יַעֲקֹב אָבִיךָ. נַחֲלָה בְּלֹא מְצָרִים, כְּמָה שֶׁנֶּאֱמַר ״וּפָרַצְתָּ יָמָּה וָקֵדְמָה וְגוֹ׳״ (בראשית כח:יד). לֹא כְּאַבְרָהָם שֶׁנֶּאֱמַר (בראשית יג:טו) ״הָאָרֶץ אֲשֶׁר אַתָּה רוֹאֶה״. וְיַעֲקֹב שָׁמַר אֶת הַשַּׁבָּת, שֶׁנֶּאֱמַר (בראשית לג:יח) ״וַיִּחַן אֶת פְּנֵי הָעִיר״, שֶׁקָּבַע תְּחוּמִין עִם דִּמְדּוּמֵי חַמָּה. כָּךְ פֵּרֵשׁ רַבִּי שִׁמְשׁוֹן:\",1,0],[2,120,59,1,\"הֵן לֹא קָצְרָה. אֶת אֲשֶׁר לֹא נוֹשַׁעְתֶּם, לֹא מִקֹּצֶר יָדוֹ הוּא:\",1,0],[2,120,59,2,\"הִסְתִּירוּ פָנִים. גָּרְמוּ לָכֶם שֶׁהִסְתִּיר פָּנָיו מִכֶּם:\",1,0],[2,120,59,3,\"נְגֹאֲלוּ. לְשׁוֹן ׳טִנּוּף׳, וְכֵן ״לֶחֶם מְגֹאָל״ (מלאכי א:ז):\",1,0],[2,120,59,5,\"צִפְעוֹנִי. מִין נָחָשׁ רַע:\",1,0],[2,120,59,5,\"בִּקֵּעוּ. אישקלורש״ט בלע״ז, כְּלוֹמַר: מַעֲשִׂים מְכֹעָרִים שֶׁאֵינָם לְטוֹבָתָם עָשׂוּ:\",2,0],[2,120,59,5,\"וְקוּרֵי עַכָּבִישׁ. איריני״ש בלע״ז, וְקוּרֵי – אורטור״ש בלע״ז. קוּרֵי הֵם כְּלֵי הָאוֹרֵג שֶׁהַשְּׁתִי מוּסָךְ בָּהֶן, וּמְנַחֵם חִבְּרוֹ בְּמַחְבֶּרֶת קוֹרוֹת, עַל שֵׁם שֶׁהָעַכָּבִישׁ מֵיסָךְ אֲרִיגוֹתָיו בְּקוֹרוֹת:\",3,0],[2,120,59,5,\"וְהַזּוּרֶה. תִּרְגֵּם יוֹנָתָן: ״מְשַׁחְנָן״, לְשׁוֹן ׳חִמּוּם׳, שֶׁקּוֹרִין בלע״ז קובי״ר; הַמְחַמְּמָן יוֹצֵא מֵהֶן כְּשֶׁהוּא מְבַקֵּעַ הַקְּלִפָּה. וְעִקַּר לְשׁוֹן וְהַזּוּרֶה לְשׁוֹן ׳עִצּוּר׳ הוּא, לְהוֹצִיא הַבָּלוּעַ בְּתוֹכוֹ, כְּמוֹ ״וַיָּזַר אֶת הַגִּזָּה״ (שופטים ו:לח), וְעִצּוּרוֹ שֶׁל זֶה הוּא חִמּוּמוֹ:\",4,0],[2,120,59,5,\"אֶפְעֶה. מִין נָחָשׁ שֶׁהוּא רַע, כָּךְ לֹא יִשְׁתַּלְּמוּ בְּמַעֲשֵׂיהֶם אֶלָּא רָעָה:\",5,0],[2,120,59,8,\"וְאֵין מִשְׁפָּט בְּמַעְגְּלוֹתָם. כְּלוֹמַר, אֵין בְּמַעְגַּל דַּרְכֵיהֶם דָּבָר נִשְׁפָּט בֶּאֱמֶת כְּמִשְׁפָּטוֹ:\",1,0],[2,120,59,8,\"נְתִיבוֹתֵיהֶם עִקְּשׁוּ לָהֶם. הֵם הֶעֱווּ אֶת דַּרְכָּם לְעַצְמָם:\",2,0],[2,120,59,9,\"רָחַק מִשְׁפָּט מִמֶּנּוּ. שֶׁהָיִינוּ צוֹעֲקִים חָמָס מֵאוֹיְבֵינוּ, וְאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹפֵט לִנְקוֹם נְקָמָה:\",1,0],[2,120,59,9,\"וְלֹא תַשִּׂיגֵנוּ צְדָקָה. הַנֶּחָמוֹת הַטּוֹבוֹת שֶׁהִבְטִיחָנוּ אֵין מַשִּׂיגוֹת אוֹתָנוּ לָבוֹא:\",2,0],[2,120,59,9,\"לִנְגֹהוֹת. נְקַוֶּה, וּבָאֲפֵלוֹת נְהַלֵּךְ:\",3,0],[2,120,59,10,\"בָּאַשְׁמַנִּים. מְנַחֵם פָּתַר לְשׁוֹן ׳מַחֲשַׁכִּים׳, וְרֹב הַפּוֹתְרִים מוֹדִים לוֹ. אֲבָל דּוּנַשׁ פָּתַר בּוֹ לְשׁוֹן ׳שׁוּמָן׳, וְהָאָלֶ״ף נוֹסָף בּוֹ, כְּמוֹ אָלֶ״ף שֶׁבְּ״אַחֲוָתִי״ (איוב יג:יז), וְשֶׁבְּ״אַכְזָב״ (ירמיה טו:יח), וְ״דֶרֶךְ הָאֲתָרִים״ (במדבר כא:א). אַף כָּאן בֵּין הָאַשְׁמַנִּים בֵּין הַחַיִּים הַשְּׁמֵנִים אֲנַחְנוּ כַּמֵּתִים. וְיוֹנָתָן תִּרְגֵּם לְשׁוֹן ׳מַסְגֵּר׳: ״אִיתַאֲחַד בְּאַפְנָא כְּמָה דַאֲחִידִין קִבְרַיָּא בְּאַפֵּי מֵיתַיָּא״:\",1,0],[2,120,59,11,\"הָגֹה נֶהְגֶּה. לְשׁוֹן ׳יְלָלָה׳:\",1,0],[2,120,59,13,\"דַּבֶּר עֹשֶׁק. כְּמוֹ ׳לְדַבֵּר עֹשֶׁק׳:\",1,0],[2,120,59,13,\"הֹרוֹ וְהֹגוֹ. לִירוֹת וּלְהוֹצִיא. הֹרוֹ לְשׁוֹן ״יָרָה בַיָּם״ (שמות טו:ד). דָּבָר אַחֵר: הֹרוֹ וְהֹגוֹ – הָרַב וְהַתַּלְמִיד שֵׁם הַמָּקוֹר (סא״א), וְהֹגוֹ כְּמוֹ ״כַּאֲשֶׁר הֹגָה מִן הַמְּסִלָּה״ (שמואל ב כ:יג), ״הָגוֹ סִיגִים מִכָּסֶף״ (משלי כה:ד):\",2,0],[2,120,59,14,\"וְהֻסַּג אָחוֹר מִשְׁפָּט. נִקְמָתֵנוּ מֵאוֹיְבֵינוּ, שֶׁהִיא תְּלוּיָה בְּהַקָּדוֹשׁ בָּרוּךְ הוּא, וְצִדְקָתוֹ עוֹמֶדֶת מֵרָחוֹק. לָמָּה? כִּי כָשְׁלָה אֱמֶת בִּרְחוֹבוֹתֵינוּ, וְכֵיוָן שֶׁהָאֱמֶת כָּשְׁלָה מֵאֶרֶץ, אַף מִשָּׁמַיִם אֵין הַצֶּדֶק וְהַמִּשְׁפָּט בָּאִין:\",1,0],[2,120,59,15,\"מִשְׁתּוֹלֵל. מֻחְזָק שׁוֹטֶה עַל הַבְּרִיּוֹת (סנהדרין צז א), כְּמוֹ ״אֵלְכָה שׁוֹלָל״ (מיכה א:ח), וְהוּא מִגִּזְרַת ״שׁוֹגֵג״, דִּמְתַרְגְּמִינָן ״שָׁלוּ״ (ויקרא ה:לו), וְכֵן ״עַל הַשַּׁל״ (שמואל ב ו:ז):\",1,0],[2,120,59,15,\"וַיֵּרַע בְּעֵינָיו כִּי אֵין מִשְׁפָּט. לְפִיכָךְ הֵבִיא עֲלֵיהֶם הַפֻּרְעָנוּת:\",2,0],[2,120,59,16,\"וַיַּרְא כִּי אֵין אִישׁ. וְעַתָּה בְּהִנָּחֲמוֹ עַל הָרָעָה לְעַמּוֹ, רוֹאֶה כִּי אֵין אִישׁ צַדִּיק לַעֲמוֹד בַּפֶּרֶץ:\",1,0],[2,120,59,16,\"וַיִּשְׁתּוֹמֵם. וַיַּחֲרֵשׁ לִרְאוֹת אִם יֵשׁ מַפְגִּיעַ בַּעֲדָם, וְאֵין מַפְגִּיעַ. וַיִּשְׁתּוֹמֵם לְשׁוֹן אָדָם הָעוֹמֵד וְתוֹהֶה וְשׁוֹתֵק בְּתִמְהוֹנוֹ, וְתָי״ו וַיִּשְׁתּוֹמֵם כְּתָי״ו שֶׁל מִשְׁתּוֹלֵל, וּשְׁנֵיהֶם כָּאן מְשַׁמְּשׁוֹת לְשׁוֹן מִתְפַּעֵל. וְכֵן דֶּרֶךְ הַתֵּיבָה שֶׁיְּסוֹדָהּ הָרִאשׁוֹן שִׁי״ן אוֹ סָמֶ״ךְ, כְּשֶׁהִיא נֶהְפֶּכֶת לִלְשׁוֹן מִתְפַּעֵל, נִתְפַּעֵל וְיִתְפַּעֵל, בָּא הַתָּי״ו בְּאֶמְצַע אוֹתִיּוֹת שֹׁרֶשׁ הַתֵּיבָה. נִמְצָא וַיִּשְׁתּוֹמֵם לְשׁוֹן ״שֹׁמּוּ שָׁמַיִם״ (ירמיהו ב:יב), ״מַשְׁמִים בְּתוֹכָם״ (יחזקאל ג:טו), ״נָשַׁמּוּ אַחֲרֹנִים״ (איוב יח:כ), לְשׁוֹן ׳תִּמָּהוֹן׳:\",2,0],[2,120,59,16,\"וַתּוֹשַׁע לוֹ זְרֹעוֹ. וְיִנָּקֵם מֵאוֹיְבָיו:\",3,0],[2,120,59,16,\"וְצִדְקָתוֹ… סְמָכָתְהוּ. הִיא לְהַשִּׂיאוֹ וּלְאַמֵּץ יָדָיו בְּנִקְמָתוֹ, וְאַף עַל פִּי שֶׁאֵין אֲנַחְנוּ הֲגוּנִים לְהוֹשִׁיעַ:\",4,0],[2,120,59,17,\"קִנְאָה. אינפרימנ״ט בלע״ז, לְקַנְּאוֹת לִשְׁמוֹ הַגָּדוֹל:\",1,0],[2,120,59,18,\"כְּעַל גְּמֻלוֹת. כְּדָת לְהָשִׁיב עַל גְּמֻלוֹת הָאוֹיְבִים:\",1,0],[2,120,59,18,\"כְּעַל יְשַׁלֵּם. כְּדָת לְהָשִׁיב עֲלֵיהֶם יְשַׁלֵּם:\",2,0],[2,120,59,19,\"כִּי יָבֹא כַנָּהָר. צָרָה עַל אוֹיְבָיו:\",1,0],[2,120,59,19,\"נֹסְסָה בוֹ. נִפְלָאוֹת בּוֹ, לְשׁוֹן ׳נֵס׳. דָּבָר אַחֵר: נוֹסְסָה בּוֹ – אוֹכֶלֶת בּוֹ כְּתוֹלַעַת בָּעֵץ, כְּמוֹ (ישעיהו י:יח) ״וְהָיָה כִּמְסוֹס נוֹסֵס״:\",2,0],[2,120,59,20,\"וּבָא לְצִיּוֹן גּוֹאֵל. כָּל זְמַן שֶׁצִּיּוֹן חֲרֵבָה, עֲדַיִין לֹא בָּא הַגּוֹאֵל ספר אחרים אומרים:\",1,0],[2,120,59,21,\"זֹאת בְּרִיתִי אוֹתָם. בְּדָבָר זֶה כָּרַתִּי בְּרִיתִי לָהֶם וַאֲקַיֵּם, כִּי אַף בְּגָלוּתָם לֹא תִּשָּׁכַח תּוֹרָתִי מֵהֶם:\",1,0],[2,120,60,4,\"עַל צַד תֵּאָמַנָה. ״עַל גִּיסְסִין״ (תרגום יונתן), כְּסָלִים שֶׁל מְלָכִים תִּהְיֶינָה אֲמוּנוֹת:\",1,0],[2,120,60,5,\"אָז תִּרְאִי וְנָהַרְתְּ. ״בְּכֵן תֶּחֱזִין וְתִנְהֲרִין״ (תרגום יונתן):\",1,0],[2,120,60,5,\"וּפָחַד וְרָחַב לְבָבֵךְ. וְיִתְמַהּ וְיִרְחַב לִבֵּךְ:\",2,0],[2,120,60,5,\"כִּי יֵהָפֵךְ עָלַיִךְ הֲמוֹן יָם. ״אֲרֵי יִתְחַלֵּף לִיךְ עוּתַר מַעַרְבָא״ (תרגום יונתן):\",3,0],[2,120,60,5,\"חֵיל גּוֹיִם. ״נִכְסֵי דְפָלְחֵי כּוֹכְבַיָּא״:\",4,0],[2,120,60,6,\"שִׁפְעַת. רֹב:\",1,0],[2,120,60,6,\"בִּכְרֵי מִדְיָן. ״הוֹגְנֵי מִדְיָן״ (תרגום יונתן); הֵם גְּמַלִּים בַּחוּרִים, וְכֵן ״בִּכְרָה קַלָּה״ (ירמיה ב:כג):\",2,0],[2,120,60,6,\"וְעֵיפָה. גַּם הֵם מִבְּנֵי מִדְיָן, ״עֵיפָה וָעֵפֶר״ (בראשית כה:ד):\",3,0],[2,120,60,7,\"אֵילֵי נְבָיוֹת. דִּכְרֵי נְבָיוֹת:\",1,0],[2,120,60,9,\"בָּרִאשֹׁנָה. כְּמוֹ ׳כְּבָרִאשׁוֹנָה׳, בִּימֵי שְׁלֹמֹה, כְּעִנְיָן שֶׁנֶּאֱמַר (מלכים א י:כב): ״כִּי אֳנִי תַרְשִׁישׁ לַמֶּלֶךְ בַּיָּם אַחַת לְשָׁלֹשׁ שָׁנִים תָּבֹא אֳנִי תַרְשִׁישׁ וְגוֹ׳״, תַּרְשִׁישׁ שֵׁם הַיָּם:\",1,0],[2,120,60,9,\"לְשֵׁם ה׳ אֱלֹהַיִךְ. שֶׁנִּקְרָא עָלֶיךָ, כִּי יִשְׁמְעוּ שִׁמְעוֹ וְשֵׁם גְּבוּרָתוֹ וְיָבוֹאוּ:\",2,0],[2,120,60,9,\"כִּי פֵאֲרָךְ. נָתַן לָךְ פְּאֵר:\",3,0],[2,120,60,10,\"וּבִרְצוֹנִי. וּבְהַרְצוֹתִי לָךְ, אימונ״א פייזמנ״ט בלע״ז:\",1,0],[2,120,60,11,\"וּפִתְּחוּ שְׁעָרַיִךְ תָּמִיד. לְשׁוֹן ׳פִּתּוּחַ׳, מִמִּשְׁקֹלֶת לָשׁוֹן כָּבֵד, עַל שֵׁם שֶׁפְּתִיחָתָן פְּתִיחַת עוֹלָם, פְּתִיחַת תָּמִיד; כְּמוֹ ׳שִׁבֵּר׳ מִלְּשׁוֹן ׳שְׁבִירָה׳, כָּךְ מִלְּשׁוֹן ׳פְּתִיחָה׳, טי״ש אובירט״ש בלע״ז:\",1,0],[2,120,60,13,\"בְּרוֹשׁ תִּדְהָר וּתְאַשּׁוּר. מִינֵי עֲצֵי יַעַר לְבָנוֹן:\",1,0],[2,120,60,14,\"צִיּוֹן קְדוֹשׁ יִשְׂרָאֵל. ״צִיּוֹן דְּאִתְרְעִי בָהּ קַדִּישָׁא דְיִשְׂרָאֵל״ (תרגום יונתן), צִיּוֹן שֶׁל קְדוֹשׁ יִשְׂרָאֵל:\",1,0],[2,120,60,16,\"וְשֹׁד מְלָכִים. לְשׁוֹן ׳שָׁדַיִם׳, וְתִינָקִי יוֹרֶה עָלָיו:\",1,0],[2,120,60,17,\"תַּחַת הַנְּחֹשֶׁת. שֶׁנָּטְלוּ מִמֵּךְ:\",1,0],[2,120,60,17,\"וְשַׂמְתִּי פְקֻדָּתֵךְ שָׁלוֹם. ״וַאֲשַׁוִּי פַּרְנָסָךְ שְׁלָם וְשָׁלְטוֹנִיךְ בִּזְכוּ״ (תרגום יונתן):\",2,0],[2,120,60,17,\"פְקֻדָּתֵךְ. פְּקִידִים שֶׁלָּךְ, וְרַבּוֹתֵינוּ אָמְרוּ (בבא בתרא ט א): הַפְּקֻדּוֹת שֶׁבָּאוּ עָלֶיךָ בְּגָלוּתֵךְ וְהַנּוֹגְשִׂים שֶׁדְּחָקוּךְ יִהְיוּ לָךְ לְשָׁלוֹם וְלִצְדָקָה:\",3,0],[2,120,60,19,\"לֹא יִהְיֶה לָּךְ עוֹד. לֹא תִצְטָרְכִי לְאוֹר הַשֶּׁמֶשׁ:\",1,0],[2,120,60,20,\"לֹא יֵאָסֵף. לְשׁוֹן ״אָסְפוּ נָגְהָם״ (יואל ב:י), הִכְנִיסוּ אוֹרָם:\",1,0],[2,120,60,21,\"לְהִתְפָּאֵר. שֶׁאֶהְיֶה מִתְפָּאֵר בָּם, פורוונטי״ר בלע״ז:\",1,0],[2,120,60,22,\"בְּעִתָּהּ אֲחִישֶׁנָּה. זָכוּ – אֲחִישֶׁנָּה, לֹא זָכוּ – בְּעִתָּהּ (סנהדרין צח א):\",1,0],[2,120,61,1,\"יַעַן מָשַׁח. אֵין מְשִׁיחָה זוֹ, אֶלָּא לְשׁוֹן שְׂרָרָה וּגְדֻלָּה:\",1,0],[2,120,61,1,\"לִקְרֹא לִשְׁבוּיִם דְּרוֹר. כְּלוֹמַר, לְבַשֵּׂר לָהֶם בְּשׂוֹרַת הַגְּאֻלָּה:\",2,0],[2,120,61,1,\"פְּקַח קוֹחַ. פְּקַח אֶת מַלְקוֹחָם וְשִׁבְיָם וְהַתִּירֵם:\",3,0],[2,120,61,2,\"שְׁנַת רָצוֹן. שְׁנַת פִּיּוּס וְרִצּוּי:\",1,0],[2,120,61,3,\"אֵילֵי הַצֶּדֶק. לְשׁוֹן ׳אִילָנוֹת׳, כְּמוֹ ״מֵאֵילִים אֲשֶׁר חֲמַדְתֶּם״ (ישעיהו א:ט), וּמַטַּע ה׳ יוֹרֶה עָלָיו:\",1,0],[2,120,61,5,\"אִכָּרֵיכֶם. מַנְהִיגֵי הַמַּחֲרֵשָׁה:\",1,0],[2,120,61,6,\"כֹּהֲנֵי ה׳. נְשִׂיאֵי הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,120,61,6,\"חֵיל גּוֹיִם. ״נִכְסֵי פָּלְחֵי כוֹכָבִיָּא״:\",2,0],[2,120,61,6,\"תִּתְיַמָּרוּ. אַתֶּם תִּכָּנְסוּ תַּחְתֵּיהֶם בַּכָּבוֹד שֶׁנָּטְלוּ עַד הֵנָּה:\",3,0],[2,120,61,7,\"תַּחַת בָּשְׁתְּכֶם. שֶׁהָיָה מִשְׁנֶה, אַף הֵם כְלִמָּה יָרֹנּוּ תָּמִיד חֶלְקָם. כְּלוֹמַר: תַּחַת אֲשֶׁר עַד הֵנָּה תָּמִיד עַמִּי הָיוּ רוֹנְנִים כְלִמָּה חֶלְקָם. יֵשׁ רִנָּה שֶׁהוּא אֵבֶל, כְּמוֹ (איכה ב:יט) ״קוּמִי רֹנִּי בַלַּיְלָה״, וּכְמוֹ (מלכים א כב:לו) ״וַתַּעֲבֹר הָרִנָּה״ דְּאַחְאָב:\",1,0],[2,120,61,8,\"כִּי אֲנִי ה׳ אֹהֵב מִשְׁפָּט שֹׂנֵא גָזֵל בְּעוֹלָה. לְכָךְ אֵינוֹ מְקַבֵּל עוֹלוֹת הָעוֹבְדֵי כּוֹכָבִים וּמָזָלוֹת, הַשָּׂרִים וְהַשָּׂרוֹת, שֶׁכֻּלָּן גָּזֵל:\",1,0],[2,120,61,8,\"וְנָתַתִּי פְעֻלָּתָם. שֶׁל יִשְׂרָאֵל שֶׁתְּהֵא בֶּאֱמֶת. אוֹ וְנָתַתִּי פְעֻלָּתָם שֶׁפָּעֲלוּ, שָׂכָר שֶׁסָּבְלוּ גִּדּוּפֵי הָעוֹבְדֵי כּוֹכָבִים וּמָזָלוֹת, הַשָּׂרִים וְהַשָּׂרוֹת עַל כְּבוֹדִי בֶּאֱמֶת:\",2,0],[2,120,61,10,\"כֶּחָתָן. אֲשֶׁר יִלְבַּשׁ לְבוּשֵׁי פְּאֵר כְּכֹהֵן גָּדוֹל:\",1,0],[2,120,61,10,\"וְכַכַּלָּה תַּעְדֶּה כֵלֶיהָ. תַּכְשִׁיטֶיהָ:\",2,0],[2,120,61,11,\"כִּי כָאָרֶץ אֲשֶׁר תּוֹצִיא צִמְחָהּ וְגוֹ׳.\",1,0],[2,120,62,1,\"לְמַעַן צִיּוֹן. אֶעֱשֶׂה וְלֹא אֶחֱשֶׁה עַל מַה שֶּׁעָשׂוּ לָהּ:\",1,0],[2,120,62,1,\"לֹא אֶשְׁקוֹט. לֹא יְהֵא שָׁלוֹם לְפָנַי, עַד יֵצֵא כַנֹּגַהּ צִדְקָהּ:\",2,0],[2,120,62,2,\"יִקֳּבֶנּוּ. יְפָרְשֶׁנּוּ:\",1,0],[2,120,62,4,\"בְּעוּלָה. מְיֻשֶּׁבֶת:\",1,0],[2,120,62,5,\"כִּי יִבְעַל וְגוֹ׳. ״אֲרֵי כְּמָה דְמִתְיַתֵּב עוּלֵם עִם בְּתוּלְתָא, כֵּן יִתְיַיתְבִין בְּגַוֵּיכִי בְּנַיְיכִי״ (תרגום יונתן):\",1,0],[2,120,62,6,\"עַל חוֹמֹתַיִךְ יְרוּשָׁלִַם. רַבּוֹתֵינוּ דְּרָשׁוּהוּ כְּמַשְׁמָעוֹ: מַלְאָכִים הַמַּזְכִּירִים אֶת ה׳ עַל חֻרְבָּנָהּ לִבְנוֹתָהּ. מַאי אָמְרִי? ״אַתָּה תָקוּם תְּרַחֵם צִיּוֹן״ (תהלים קב:יד), ״כִּי בָחַר ה׳ בְּצִיּוֹן״ (תהלים קלב:יג), כִּדְאִיתָא בִּמְסֶכֶת מְנָחוֹת (מנחות פז א). וְיוֹנָתָן תִּרְגֵּם חוֹמוֹתַיִךְ: אָבוֹת הָרִאשׁוֹנִים, הַמְּגִינִים עָלֵינוּ כַּחוֹמָה:\",1,0],[2,120,62,6,\"הִפְקַדְתִּי שֹׁמְרִים. לִכְתּוֹב סֵפֶר זִכְרוֹנוֹת שֶׁלֹּא יִשְׁתַּכַּח זְכוּתָם מִלְּפָנַי:\",2,0],[2,120,62,6,\"לֹא יֶחֱשׁוּ. מִלְּהַזְכִּיר זְכוּתָם לְפָנַי:\",3,0],[2,120,62,6,\"הַמַּזְכִּירִים אֶת ה׳. אֶת זְכוּת הָאָבוֹת:\",4,0],[2,120,62,6,\"אַל דֳּמִי לָכֶם. אַל תַּחֲרִישׁוּ:\",5,0],[2,120,62,9,\"יֹאכְלֻהוּ. מוּסָב עַל דְּגָנֵךְ (ישעיה סב:ח):\",1,0],[2,120,62,9,\"יִשְׁתֻּהוּ. מוּסָב עַל תִּירוֹשֵׁךְ (ישעיהו סב:ח):\",2,0],[2,120,62,10,\"עִבְרוּ עִבְרוּ בַּשְּׁעָרִים. ״אָמַר נְבִיָּיא: עִבְרוּ וְתוּבוּ בְּתַרְעַיָּא, אַפְנוּ לִבָּא דְעַמָּא לְאוֹרַח תַּקְנָא״ (תרגום יונתן):\",1,0],[2,120,62,10,\"סֹלּוּ סֹלּוּ הַמְסִלָּה. כִּבְשׁוּ הַדֶּרֶךְ בטי״ץ לוקמי״ן בלע״ז. סֹלּוּ לְשׁוֹן ׳מְסִלָּה׳ הוּא:\",2,0],[2,120,62,10,\"סַקְּלוּ מֵאֶבֶן. סַקְּלוּ הַמְּסִלָּה וְהַשְׁלִיכוּ אַבְנֵי מִכְשׁוֹל לַצְּדָדִין, סַקְּלוּ. אישפירייר״ן בלע״ז:\",3,0],[2,120,62,10,\"מֵאֶבֶן. מִהְיוֹת שָׁם אֶבֶן, וּכְנֶגֶד יֵצֶר הָרָע הוּא אוֹמֵר (תנחומא בהעלתך י), וְיֵשׁ עוֹד לְפוֹתְרוֹ עַל תִּקּוּן הַדְּרָכִים לְקִבּוּץ הַגָּלִיּוֹת:\",4,0],[2,120,62,10,\"הָרִימוּ נֵס. כְּלוֹנָס, פורק״א בלע״ז. אוֹת הוּא שֶׁיִּקָּבְצוּ אֵלַי, וְיָבִיאוּ לִי אֶת הַגּוֹלִים אֶצְלָם:\",5,0],[2,120,62,11,\"הִנֵּה שְׂכָרוֹ. שֶׁמּוּכָן לָתֵת לַעֲבָדָיו מוּכָן אִתּוֹ:\",1,0],[2,120,62,11,\"וּפְעֻלָּתוֹ. שְׂכַר הַפְּעֻלָּה שֶׁפָּעֲלוּ עִמּוֹ לְפָנָיו, הוּא מוּכָן לָתֵת:\",2,0],[2,120,63,1,\"מִי זֶה בָּא מֵאֱדוֹם. נִתְנַבֵּא הַנָּבִיא עַל שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁעָתִיד לַעֲשׂוֹת נְקָמָה בֶּאֱדוֹם, וְהוּא עַצְמוֹ בִּכְבוֹדוֹ יַהֲרֹג אֶת שַׂר שֶׁלָּהֶם תְּחִלָּה, כְּעִנְיָן שֶׁנֶּאֱמַר (ישעיהו לד:ה) ״כִּי רִוְתָה בַשָּׁמַיִם חַרְבִּי״ וְאַחַר כָּךְ ״עַל אֱדוֹם תֵּרֵד״, וְנִכָּר בְּזַעַם פָּנָיו שֶׁהֲרָגָם הֶרֶג רַב. וְהַנָּבִיא מְדַבֵּר בִּלְשׁוֹן מִלְחֲמוֹת בְּנֵי אָדָם לְבוּשֵׁי בְּגָדִים, וּבְהָרְגָם הֶרֶג הַדָּם נִתָּז עַל בִּגְדֵיהֶם, כִּי כֵּן דֶּרֶךְ הַכְּתוּבִים מְדַבְּרִים בַּשְּׁכִינָה כְּדֶרֶךְ בְּנֵי אָדָם לְשַׂבֵּר אֶת הָאֹזֶן מַה שֶּׁהִיא יְכוֹלָה לִשְׁמוֹעַ, וְכֵן (יחזקאל מג:ב) ״וְקוֹלוֹ כְּקוֹל מַיִם רַבִּים״, דִּמָּה הַנָּבִיא קוֹל חָזָק שֶׁלּוֹ לְקוֹל מַיִם רַבִּים לְשַׂבֵּר אֶת הָאֹזֶן כְּדֶרֶךְ שֶׁאֶפְשָׁר לָהּ לִשְׁמוֹעַ, שֶׁאֵין לְהָבִין וּלְהַאֲזִין בְּרוּחַ גְּבוּרוֹת אֱלֹהֵינוּ לְהַשְׁמִיעָהּ כְּמוֹת שֶׁהִיא:\",1,0],[2,120,63,1,\"מִי זֶה בָּא מֵאֱדוֹם. יִשְׂרָאֵל אוֹמֵר: מִי זֶה וְגוֹ׳, וּבָא חֲמוּץ בְּגָדִים צְבוּעִים בְּדָם, וְכָל דָּבָר שֶׁהוּא מִתְנָאֵץ בְּרֵיחוֹ וּבְמַרְאִיתוֹ נוֹפֵל בּוֹ לְשׁוֹן ׳חִמּוּץ׳:\",2,0],[2,120,63,1,\"מִבָּצְרָה. אָמְרוּ רַבּוֹתֵינוּ (מכות יב.): שְׁתֵּי טָעֻיּוֹת עָתִיד שַׂר שֶׁל שֵׂעִיר לִטְעוֹת, כְּסָבוּר הוּא שֶׁבָּצְרָה הִיא ״בֶּצֶר בַּמִּדְבָּר״ (דברים ד:מג) שֶׁהָיְתָה עִיר מִקְלָט, וְטוֹעֶה, מִשּׁוּם שֶׁאֵין קוֹלֶטֶת אֶלָּא שׁוֹגֵג וְהוּא הָרַג אֶת יִשְׂרָאֵל מֵזִיד. וְעוֹד יֵשׁ מִדְרַשׁ אַגָּדָה (בראשית רבה פג ג), עַל שֶׁהִסְפִּיקָה בָּצְרָה מֶלֶךְ לְשֵׂעִיר בְּמוֹת מַלְכָּהּ הָרִאשׁוֹן ״וַיִּמְלֹךְ תַּחְתָּיו יוֹבָב בֶּן זֶרַח מִבָּצְרָה״ (בראשית לו:לג), וּבָצְרָה מִמּוֹאָב הִיא, כְּעִנְיָן שֶׁנֶּאֱמַר ״עַל קְרִיּוֹת וְעַל בָּצְרָה״ (ירמיהו מח:כד):\",3,0],[2,120,63,1,\"זֶה. (שֶׁהָיָה) הָדוּר בִּלְבוּשׁוֹ וְצֹעֶה וְנֶאֱזָר בְּרֹב כֹּחוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְשִׁיבוֹ: אֲנִי הוּא שֶׁעָלְתָה לְפָנַי לְדַבֵּר בְּצִדְקַת הָאָבוֹת וּבְצִדְקַת דּוֹרוֹ שֶׁל צָרָה, וְצִדְקָתִי גַּם הִיא עִמָּהֶם, וְנִגְלֵיתִי לִהְיוֹת רַב לְהוֹשִׁיעַ. וְהֵם אוֹמְרִים: מַדּוּעַ אָדֹם לִלְבוּשֶׁךָ? מַדּוּעַ בְּגָדֶיךָ אֲדוּמִים?\",4,0],[2,120,63,3,\"וּמֵעַמִּים אֵין אִישׁ אִתִּי. מִתְיַצֵּב לְפָנַי לְהִלָּחֵם:\",1,0],[2,120,63,3,\"וְיֵז נִצְחָם. דָּמָם, שֶׁהוּא תָּקְפּוֹ וְנִצְחוֹנוֹ שֶׁל אָדָם:\",2,0],[2,120,63,3,\"אֶגְאָלְתִּי. כְּמוֹ ״נִגְאֲלוּ בְדָם״ (איכה ד:יד):\",3,0],[2,120,63,5,\"וָאַבִּיט וְאֵין עֹזֵר לְיִשְׂרָאֵל:\",1,0],[2,120,63,5,\"וְאֶשְׁתּוֹמֵם. לְשׁוֹן ׳שְׁתִיקָה׳, וּכְבָר פֵּרַשְׁתִּי לְמַעְלָה ״וַיִּשְׁתּוֹמֵם כִּי אֵין מַפְגִּיעַ״ (ישעיהו נט:טז):\",2,0],[2,120,63,5,\"וַחֲמָתִי הִיא סְמָכָתְנִי. חֲמָתִי שֶׁיֵּשׁ לִי עַל הָאֻמּוֹת, אֲשֶׁר ״אֲנִי קָצַפְתִּי מְעַט״ עַל עַמִּי ״וְהֵמָּה עָזְרוּ לְרָעָה״ (זכריה א:טו), הִיא סְמָכָתְנִי – חִזְּקָה יָדִי וְעוֹרְרָה אֶת לִבִּי לִפָּרַע מֵהֶם, וְאַף עַל פִּי שֶׁאֵין יִשְׂרָאֵל רְאוּיִין וַהֲגוּנִים לִגְאֻלָּה:\",3,0],[2,120,63,6,\"וְאָבוּס. לְשׁוֹן מִתְגּוֹלֵל בְּדָם וְדוֹרֵךְ בָּרַגְלַיִם, כְּמוֹ ״מִתְבּוֹסֶסֶת בְּדָמָיִךְ״ (יחזקאל טז:ו), וּכְמוֹ ״בֹּסְסוּ אֶת חֶלְקָתִי״ (ירמיהו יב:י):\",1,0],[2,120,63,6,\"נִצְחָם. גְּבוּרַת נִצְחוֹנָם:\",2,0],[2,120,63,7,\"חַסְדֵי ה׳ אַזְכִּיר. הַנָּבִיא אָמַר: אַזְכִּיר אֶת יִשְׂרָאֵל אֶת חַסְדֵי ה׳:\",1,0],[2,120,63,7,\"וְרַב טוּב. אַזְכִּיר אֲשֶׁר גָּמַל לְבֵית יִשְׂרָאֵל בְּרַחֲמָיו:\",2,0],[2,120,63,8,\"אַךְ עַמִּי הֵמָּה. אַף עַל פִּי שֶׁגָּלוּי לְפָנַי שֶׁיִּבְגְּדוּ בִּי, מִכָּל מָקוֹם עַמִּי הֵם, וַהֲרֵי הֵם לְפָנַי כְּבָנִים אֲשֶׁר לֹא יְשַׁקֵּרוּ:\",1,0],[2,120,63,9,\"בְּכָל צָרָתָם. שֶׁהֵבִיא עֲלֵיהֶם:\",1,0],[2,120,63,9,\"לֹא צָר. לֹא הֵצֵר לָהֶם כְּפִי מַעַלְלֵיהֶם שֶׁהָיוּ רְאוּיִין לִלְקוֹת, כִּי מַלְאַךְ פָּנָיו הוּא מִיכָאֵל שַׂר הַפָּנִים, מִמְּשַׁמְּשִׁים לְפָנָיו הוֹשִׁיעָם תָּמִיד בִּשְׁלִיחוּתוֹ שֶׁל מָקוֹם:\",2,0],[2,120,63,10,\"וְהֵמָּה מָרוּ. הִקְנִיטוּ, כְּמוֹ ״מַמְרִים הֱיִיתֶם״ (דברים ט:ז):\",1,0],[2,120,63,11,\"וַיִּזְכֹּר יְמֵי עוֹלָם מֹשֶׁה עַמּוֹ. הַנָּבִיא מִתְאוֹנֵן וְאוֹמֵר בְּלָשׁוֹן תְּחִנָּה: הַיּוֹם בַּגּוֹלָה, זוֹכֵר עַמּוֹ אֶת יְמֵי עוֹלָם, אֶת יְמֵי מֹשֶׁה, וּבְצָרָתוֹ הוּא אוֹמֵר: אַיֵּה מֹשֶׁה רוֹעֵנוּ הַמַּעֲלֵנוּ מִיַּם סוּף:\",1,0],[2,120,63,11,\"אֶת רֹעֵי צֹאנוֹ. דִּמְיוֹן רוֹעֶה הַמַּעֲלֶה אֶת צֹאנוֹ, אַיֵּה הוּא אֲשֶׁר שָׂם בְּקֶרֶב יִשְׂרָאֵל אֶת רוּחַ קָדְשׁוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלִמְּדָנוּ חֻקִּים וּמִשְׁפָּטִים:\",2,0],[2,120,63,12,\"מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ. הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מוֹלִיךְ לִימִין מֹשֶׁה אֶת זְרוֹעַ גְּבוּרָתוֹ; בְּכָל עֵת שֶׁהָיָה צָרִיךְ לְעֶזְרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הָיָה זְרוֹעוֹ מוּכָן לִימִינוֹ:\",1,0],[2,120,63,13,\"כַּסּוּס בַּמִּדְבָּר. שֶׁאֵינוֹ נִכְשָׁל, לְפִי שֶׁהִיא אֶרֶץ חֲלָקָה, כֵּן לֹא נִכְשְׁלוּ בַּתְּהוֹם:\",1,0],[2,120,63,14,\"כַּבְּהֵמָה. אֲשֶׁר בַּבִּקְעָה תֵרֵד, וּבִקְעָה הִיא אֶרֶץ חֲלָקָה וְאֵין בָּהּ מִכְשׁוֹל, קנפניי״א בלע״ז:\",1,0],[2,120,63,14,\"תֵרֵד. תִּתְפַּשֵּׁט, כְּמוֹ ״לְרַד לְפָנָיו גּוֹיִם״ (ישעיהו מה:), כֵּן רוּחַ ה׳ תְּנִיחֶנּוּ לַתְּהוֹם, וְעָשָׂה בּוֹ דֶּרֶךְ כְּבוּשָׁה:\",2,0],[2,120,63,14,\"כֵּן נִהַגְתָּ עַמְּךָ. כֵּן הָיָה הַכֹּל כְּמוֹ שֶׁאָמַרְנוּ, נִהַגְתָּ עַמְּךָ:\",3,0],[2,120,63,15,\"אַיֵּה קִנְאָתְךָ. הָרִאשׁוֹנָה:\",1,0],[2,120,63,15,\"הֲמוֹן מֵעֶיךָ. שֶׁהָיוּ רְגִילִים לְהָמוֹת עָלֵינוּ כַּאֲשֶׁר מֵאָז, כְּעִנְיָן שֶׁנֶּאֱמַר (ירמיהו לא:כ) ״עַל כֵּן הָמוּ מֵעַי לוֹ״, וַהֲמוֹן רַחֲמֶיךָ הָרִאשׁוֹנִים אֵלֵינוּ עַתָּה הִתְאַפָּקוּ, נִתְחַסְּנוּ מִהְיוֹת הוֹמִים עָלֵינוּ כַּאֲשֶׁר מֵאָז:\",2,0],[2,120,63,15,\"הִתְאַפָּקוּ. כְּמוֹ ״וַיִּתְאַפַּק וַיֹּאמֶר שִׂימוּ לָחֶם״ (בראשית מג:לא), נִתְאַפַּק, וְלֹא הִכִּירוּ אֶת אֲשֶׁר נִכְמְרוּ רַחֲמָיו אֶל אָחִיו:\",3,0],[2,120,63,16,\"כִּי אַתָּה אָבִינוּ. וְעָלֶיךָ לְהַבִּיט וְלִרְאוֹת בְּצָרוֹתֵינוּ:\",1,0],[2,120,63,16,\"כִּי אַבְרָהָם לֹא יְדָעָנוּ. בְּצָרַת מִצְרָיִם:\",2,0],[2,120,63,16,\"וְיִשְׂרָאֵל לֹא יַכִּירָנוּ בַּמִּדְבָּר, כִּי כְּבָר נִסְתַּלְּקוּ מִן הָעוֹלָם:\",3,0],[2,120,63,16,\"וְאַתָּה ה׳ אָבִינוּ. בְּכֻלָּם נַעֲשֵׂיתָ לָנוּ אָב, וְרַבּוֹתֵינוּ דָּרְשׁוּ בּוֹ כְּמוֹ שֶׁדָּרְשׁוּ בְּמַסֶּכֶת שַׁבָּת (שבת פט ב):\",4,0],[2,120,63,17,\"לָמָּה תַתְעֵנוּ. כִּי בְּיָדְךָ לְהָסִיר יֵצֶר הָרָע, כְּמָה שֶׁנֶּאֱמַר ״כַּחֹמֶר בְּיַד הַיּוֹצֵר וְגוֹ׳״ (ירמיהו יח:ו), וְאוֹמֵר ״וַהֲסִרֹתִי אֶת לֵב הָאֶבֶן וְגוֹ׳״ (יחזקאל לו:כו):\",1,0],[2,120,63,17,\"תַּקְשִׁיחַ. לְשׁוֹן אִמּוּץ לֵב:\",2,0],[2,120,63,18,\"לַמִּצְעָר יָרְשׁוּ עַם קָדְשֶׁךָ. גְּדֻלָּתָם וִירֻשָּׁתָם זְמַן מוּעָט הָיְתָה לָהֶם:\",1,0],[2,120,63,18,\"בּוֹסְסוּ. ״דּוֹשְׁשׁוּ״:\",2,0],[2,120,63,19,\"הָיִינוּ. עַתָּה כְּעַם אֲשֶׁר לֹא בָּחַרְתָּ לִמְשׁוֹל בָּם מֵעוֹלָם, וּכְאִלּוּ לֹא נִקְרָא שִׁמְךָ עֲלֵיהֶם:\",1,0],[2,120,63,19,\"לוּא קָרַעְתָּ שָׁמַיִם. וְיָרַדְתָּ לְהַצִּילֵנוּ עַתָּה, כַּאֲשֶׁר יָרַדְתָּ לְהַצִּיל מִיַּד מִצְרַיִם, אָז מִפָּנֶיךָ הָרִים נָזֹלּוּ בְּרֶתֶת וְזִיעַ:\",2,0],[2,120,64,1,\"כִּקְדֹחַ אֵשׁ. אֶת דָּבָר הַנָּמֵס מִלְּפָנָיו, וְכַאֲשֶׁר הַמַּיִם תִּבְעֶה הָאֵשׁ – כְּשֶׁתִּתֵּן גַּחֶלֶת אוֹ מַתֶּכֶת בַּמַּיִם יַעֲלוּ הַמַּיִם אֲבַעְבּוּעוֹת. כָּל זֶה עָשִׂיתָ בְּמִצְרַיִם, ״וַיְהִי בָרָד וְאֵשׁ מִתְלַקַּחַת בְּתוֹכָהּ״ (שמות ט:כד). אֲבָל יוֹנָתָן תִּרְגֵּם ״כִּקְדוֹחַ אֵשׁ הֲמָסִים״ עַל אֵלִיָּהוּ בְּהַר הַכַּרְמֶל, שֶׁנֶּאֱמַר בּוֹ ״גַּם הַמַּיִם אֲשֶׁר בַּתְּעָלָה לִחֵכָה״ (מלכים א יח:לח):\",1,0],[2,120,64,1,\"לְהוֹדִיעַ שִׁמְךָ לְצָרֶיךָ. כְּעִנְיָן שֶׁנֶּאֱמַר בְּאוֹתָהּ מַכָּה ״וְאוּלָם בַּעֲבוּר זֹאת הֶעֱמַדְתִּיךָ וְגוֹ׳״ (שמות ט:טז), לוּ עָשִׂיתָ עַתָּה כֵּן, אָז מִפָּנֶיךָ גּוֹיִם יִרְגָּזוּ:\",2,0],[2,120,64,2,\"בַּעֲשׂוֹתְךָ. בְּמִצְרַיִם וּבְכָל הָאוֹיְבִים נוֹרָאוֹת, אֲשֶׁר לֹא הָיִינוּ מְקַוִּים שֶׁתַּעֲשֶׂה לָנוּ כָּל אוֹתָן נוֹרָאוֹת, שֶׁלֹּא הָיִינוּ הֲגוּנִים לְכָךְ:\",1,0],[2,120,64,2,\"יָרַדְתָּ. לְהַר סִינַי, אָז מִפָּנֶיךָ הָרִים נָזֹלּוּ. כָּךְ פֵּרֵשׁ דּוֹנַשׁ בֶּן לַבְרַט:\",2,0],[2,120,64,3,\"וּמֵעוֹלָם לֹא שָׁמְעוּ. כְּאוֹתָן נוֹרָאוֹת שֶׁנַּעֲשׂוֹת לְאַחַת מִכָּל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת לְפָנֵי כֵּן, וְגַם עַיִן לֹא רָאָתָה אֱלֹהִים אַחֵר זוּלָתְךָ אֲשֶׁר יַעֲשֶׂה הָאֱלֹהִים לִמְחַכֵּה לוֹ. מַה שֶּׁעָשִׂיתָ אַתָּה לִמְחַכֵּה לְךָ. כָּךְ שָׁמַעְתִּי מֵרַבִּי יוֹסֵי וְהַנָּאַנִי. אֲבָל רַבּוֹתֵינוּ שֶׁאָמְרוּ (ברכות לד א): ״כָּל הַנְּבִיאִים כֻּלָּם לֹא נִתְנַבְּאוּ אֶלָּא לִימוֹת הַמָּשִׁיחַ, אֲבָל לָעוֹלָם הַבָּא עַיִן לֹא רָאָתָה וְגוֹ׳״ – מַשְׁמָעוֹ: עַיִן שׁוּם נָבִיא לֹא רָאָתָה אֶת אֲשֶׁר יַעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לִמְחַכֵּה לוֹ זוּלָתִי עֵינֶיךָ, אַתָּה אֱלֹהִים:\",1,0],[2,120,64,4,\"פָּגַעְתָּ אֶת שָׂשׂ וְעֹשֵׂה צֶדֶק. כְּמוֹ ״וַיִּפְגַּע בּוֹ וַיָּמֹת״ (מלכים א ב:כה), סִלַּקְתָּ מִמֶּנּוּ וְהָרַגְתָּ אֶת הַצַּדִּיקִים שֶׁהָיוּ שָׂשִׂים לַעֲשׂוֹת צֶדֶק, לְדַרְכֵי רַחֲמֶיךָ הָיוּ מַזְכִּירִים אוֹתְךָ בִּתְפִלָּתָם:\",1,0],[2,120,64,4,\"הֵן אַתָּה. כְּשֶׁקָּצַפְתָּ עָלֵינוּ עַל כָּל אֲשֶׁר הָיִינוּ חוֹטְאִים, בָּהֶם מֵעוֹלָם נוֹשַׁעְנוּ בִּתְפִלָּתָם, נוֹשַׁעְנוּ מֵעוֹלָם:\",2,0],[2,120,64,4,\"וְנִוָּשֵׁעַ. לְשׁוֹן הוֹוֶה:\",3,0],[2,120,64,5,\"וַנְּהִי כַטָּמֵא. מֵאַחַר שֶׁנִּסְתַּלְּקוּ הַצַּדִּיקִים מִמֶּנּוּ:\",1,0],[2,120,64,5,\"וּכְבֶגֶד עִדִּים. וְכִלְבוּשׁ מְרֻחָק, כְּבֶגֶד מָאוּס שֶׁהַכֹּל אוֹמְרִים: ״הָסֵר״. עִדִּים תַּרְגּוּם שֶׁל ׳הֲסָרָה׳:\",2,0],[2,120,64,5,\"וַנָּבֶל כֶּעָלֶה. וְנִכְמוֹשׁ כְּעָלֶה, פליישט״ר בלע״ז:\",3,0],[2,120,64,5,\"וַעֲוֺנֵנוּ כָּרוּחַ יִשָּׂאֻנוּ. ״וּבְחוֹבָנָא כְּרוּחָא אִיתְנְטִילְנָא״ (תרגום יונתן):\",4,0],[2,120,64,6,\"מִתְעוֹרֵר. כְּמוֹ מִתְגַּבֵּר עַל יִצְרוֹ:\",1,0],[2,120,64,6,\"וַתְּמוּגֵנוּ. וַתְּנִיעֵנוּ:\",2,0],[2,120,64,11,\"תֶּחֱשֶׁה וּתְעַנֵּנוּ. תַּחֲרִישׁ עַל הֶעָשׂוּי לָנוּ. עַד כָּאן תְּפִלַּת הַנָּבִיא, וּתְחִלָּתָהּ ״חַסְדֵי ה׳ אַזְכִּיר״ (ישעיהו סג:ז):\",1,0],[2,120,65,1,\"נִדְרַשְׁתִּי לְלֹא שָׁאָלוּ. הַקָּדוֹשׁ בָּרוּךְ הוּא מְשִׁיבוֹ: אִי אֶפְשָׁר שֶׁלֹּא לְהִנָּקֵם מֵהֶם, כִּי נִדְרַשְׁתִּי מֵהֶם לְהוֹכִיחָם עַל יְדֵי נְבִיאַי, וְהֵם לֹא הָיוּ שׁוֹאֲלִים:\",1,0],[2,120,65,1,\"אָמַרְתִּי הִנֵּנִי הִנֵּנִי. שׁוּבוּ אֵלַי, וְהִנְנִי מוּכָן לְקַבֵּל:\",2,0],[2,120,65,1,\"אֶל גּוֹי לֹא קֹרָא בִשְׁמִי. אֲשֶׁר לֹא הָיָה חָפֵץ לִהְיוֹת נִקְרָא עַל שְׁמִי:\",3,0],[2,120,65,2,\"פֵּרַשְׂתִּי יָדַי. כְּדֵי לְקַבְּלָם בִּתְשׁוּבָה:\",1,0],[2,120,65,2,\"סוֹרֵר. סָר מִן הַדֶּרֶךְ:\",2,0],[2,120,65,3,\"זֹבְחִים בַּגַּנּוֹת. מַעֲמִידִים עֲבוֹדָה זָרָה בְּגִנּוֹתֵיהֶן, וְשָׁם מְקַטְּרִין בְּשָׂמִים עַל הַלְּבֵנִים:\",1,0],[2,120,65,4,\"הַיֹּשְׁבִים בַּקְּבָרִים. שֶׁתִּשְׁרֶה עֲלֵיהֶם רוּחַ טֻמְאָה שֶׁל שֵׁדִים (סנהדרין סד ב):\",1,0],[2,120,65,4,\"וּבַנְּצוּרִים. הֵם פִּגְרֵי הַמֵּתִים, שֶׁהֵם כִּנְתוּנִים בְּמָצוֹר, שֶׁאֵינָם יְכוֹלִים לָצֵאת:\",2,0],[2,120,65,4,\"וּמְרַק פִּגֻּלִים. רֹטֶב נִתְעָב, כְּמוֹ ״וְאֶת הַמָּרָק שְׁפֹךְ״ (שופטים ו:כ):\",3,0],[2,120,65,5,\"הָאֹמְרִים. אֶל הַצַּדִּיקִים קְרַב אֵלֶיךָ, עֲמוֹד בְּעַצְמְךָ וְאַל תִּגַּשׁ בִּי:\",1,0],[2,120,65,5,\"כִּי קְדַשְׁתִּיךָ. כִּי קָדַשְׁתִּי וְטָהַרְתִּי יוֹתֵר מִמְּךָ; כֵּן תִּרְגֵּם יוֹנָתָן:\",2,0],[2,120,65,5,\"אֵלֶּה. הַתּוֹעֵבָה אֲשֶׁר עָשׂוּ, הִנֵּה לְעָשָׁן חֵמָה בְּאַפִּי:\",3,0],[2,120,65,6,\"הִנֵּה כְתוּבָה. חַטָּאתָם לְפָנַי, כְּבָר נִגְזַר דִּינָם וְנֶחְתַּם:\",1,0],[2,120,65,7,\"עֲוֺנֹתֵיכֶם. שֶׁלָּכֶם וְשֶׁל אֲבוֹתֵיכֶם יַחְדָּיו אֲשַׁלֵּם לָכֶם:\",1,0],[2,120,65,8,\"כַּאֲשֶׁר יִמָּצֵא הַתִּירוֹשׁ בָּאֶשְׁכּוֹל. תִּרְגֵּם יוֹנָתָן: ״כְּמָה דְאִשְׁתְּכַח נֹחַ זַכַּאי בְּדָרָא דְטוֹפָנָא״:\",1,0],[2,120,65,8,\"הַתִּירוֹשׁ. זֶה נֹחַ, שֶׁהָיָה מָתוֹק:\",2,0],[2,120,65,8,\"בָּאֶשְׁכּוֹל. בַּדּוֹר הַמְשֻׁכָּל, וְיֵשׁ לִפְתּוֹר כְּמַשְׁמָעוֹ:\",3,0],[2,120,65,8,\"לְמַעַן עֲבָדַי. לְמַעַן כָּל צַדִּיק וְצַדִּיק הַנִּמְצָא בָּם:\",4,0],[2,120,65,10,\"הַשָּׁרוֹן. שֵׁם מָחוֹז שֶׁהָיָה בְּאֶרֶץ יִשְׂרָאֵל:\",1,0],[2,120,65,10,\"וְעֵמֶק עָכוֹר. כְּמַשְׁמָעוֹ:\",2,0],[2,120,65,11,\"עֹזְבֵי ה׳. רִשְׁעֵי יִשְׂרָאֵל, שֶׁהֶחֱזִיקוּ בַּעֲבוֹדָה זָרָה, וּמֵתוּ בְּרִשְׁעָם:\",1,0],[2,120,65,11,\"הָעֹרְכִים לַגַּד. שֵׁם עֲבוֹדָה זָרָה הָעֲשׂוּיָה עַל שֵׁם הַמַּזָּל, וּבִלְשׁוֹן מִשְׁנָה יֵשׁ (שבת סז ב): ״גָּד גַּדִּי וְסִינוּק לָא״:\",2,0],[2,120,65,11,\"לַמְנִי. לְמִנְיַן חֶשְׁבּוֹן הַכּוֹמְרִים הָיוּ מְמַלְאִים אֲגָנוֹת מֶזֶג יַיִן:\",3,0],[2,120,65,11,\"מִמְסָךְ. יַיִן מָזוּג בְּמַיִם כְּמִשְׁפָּטוֹ, כְּמוֹ ״לַחְקֹר מִמְסָךְ״ (משלי כג:ל), ״מָסְכָה יֵינָהּ״ (משלי ט:ב). וְיֵשׁ פּוֹתְרִים לַמְנִי לַעֲבוֹדָה זָרָה שֶׁמִּנִּיתֶם עֲלֵיכֶם, אֲבָל וּמָנִיתִי אֶתְכֶם שֶׁלֹּא נָקוּד וּמִנִּיתִי דָּגֵשׁ, יוֹרֶה שֶׁהוּא לְשׁוֹן ׳מִנְיָן׳:\",4,0],[2,120,65,13,\"עֲבָדַי. הַצַּדִּיקִים (שֶׁל יִשְׂרָאֵל):\",1,0],[2,120,65,13,\"וְאַתֶּם. הַפּוֹשְׁעִים בִּי:\",2,0],[2,120,65,15,\"שִׁמְכֶם לִשְׁבוּעָה. לוֹקֵחַ מִשִּׁמְכֶם קְלָלָה וּשְׁבוּעָה לְדוֹרוֹת: ״אִם לֹא יִקְרֵנוּ כַּאֲשֶׁר אֵרַע לִפְלוֹנִי״ (ספרי דברים יח):\",1,0],[2,120,65,15,\"וֶהֱמִיתְךָ. מִיתַת עוֹלָם:\",2,0],[2,120,65,15,\"וְלַעֲבָדָיו יִקְרָא שֵׁם אַחֵר. שֵׁם טוֹב וְזֵכֶר לִבְרָכָה:\",3,0],[2,120,65,16,\"אֲשֶׁר הַמִּתְבָּרֵךְ בָּאָרֶץ. כִּי תִהְיֶה יִרְאָתִי עַל כֻּלָּם, ״וּמָלְאָה הָאָרֶץ דֵּעָה״ (ישעיהו יא:ט), וְהַמִּתְהַלֵּל וּמִשְׁתַּבֵּחַ בָּאָרֶץ יִתְבָּרֵךְ בֵּאלֹהֵי אָמֵן, יִתְהַלֵּל שֶׁהוּא עֶבֶד לֵאלֹהֵי אָמֵן, אֱלֹהֵי הָאֱמֶת, שֶׁאִמֵּן וְשָׁמַר הַבְטָחָתוֹ זֹאת:\",1,0],[2,120,65,16,\"כִּי נִשְׁכְּחוּ הַצָּרוֹת. לְכָךְ יִקְרָאוּנִי אֱלֹהֵי אָמֵן:\",2,0],[2,120,65,17,\"שָׁמַיִם חֲדָשִׁים. יִתְחַדְּשׁוּ הַשָּׂרִים שֶׁל מַעְלָה, וְיִהְיוּ שָׂרֵי יִשְׂרָאֵל שָׂרֵי עֶלְיוֹנִים וְשָׂרֵי הָאֻמּוֹת תַּחְתּוֹנִים, וְכֵן בָּאָרֶץ; וְיֵשׁ אוֹמְרִים (פרקי דרבי אליעזר כא) שָׁמַיִם חֲדָשִׁים מַמָּשׁ, וְכֵן עִקָּר, כִּי מִקְרָא מוֹכִיחַ ״כִּי כַּאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְגוֹ׳״ (ישעיהו סו:כב):\",1,0],[2,120,65,20,\"עוּל יָמִים. נַעַר, כְּמוֹ ״עוֹלֵל״ (איכה ב:יא); עוּל יָמִים – קָטָן בְּשָׁנִים:\",1,0],[2,120,65,20,\"בֶּן מֵאָה שָׁנָה יָמוּת. יְהֵא בֶּן עוֹנְשִׁין לְהִתְחַיֵּב מִיתָה בַּעֲבֵירָה שֶׁיֵּשׁ בָּהּ מִיתָה, כָּךְ מְפֹרָשׁ בִּבְרֵאשִׁית רַבָּה (כו ב):\",2,0],[2,120,65,20,\"יְקֻלָּל. בַּעֲבֵרָה שֶׁהִיא צְרִיכָה נִדּוּי:\",3,0],[2,120,65,22,\"כִּימֵי הָעֵץ. תִּרְגֵּם יוֹנָתָן: עֵץ הַחַיִּים:\",1,0],[2,120,65,25,\"יֹאכַל תֶּבֶן. וְלֹא יִצְטָרֵךְ לְהַשְׁחִית בַּבְּהֵמָה:\",1,0],[2,120,65,25,\"וְנָחָשׁ. הֲרֵי עָפָר לַחְמוֹ מָצוּי לוֹ תָּדִיר. וּמִדְרַשׁ אַגָּדָה (בראשית רבה צה א): וְאַרְיֵה כַּבָּקָר יֹאכַל תֶּבֶן – לְפִי שֶׁמָּצִינוּ שֶׁעֵשָׂו נוֹפֵל בְּיַד בְּנֵי יוֹסֵף, שֶׁנֶּאֱמַר ״בֵּית עֵשָׂו לְקַשׁ וּבֵית יוֹסֵף לְהָבָה וְגוֹ׳״ (עובדיה א:יח), אֲבָל בְּיַד בְּנֵי שְׁאָר הַשְּׁבָטִים שֶׁנִּמְשְׁלוּ לְחַיּוֹת לֹא מָצִינוּ. לְכָךְ נֶאֱמַר: וְאַרְיֵה כַּבָּקָר יֹאכַל תֶּבֶן – אוֹתָם הַשְּׁבָטִים שֶׁנִּמְשְׁלוּ כְּאַרְיֵה, כְּגוֹן יְהוּדָה וְדָן, כְּיוֹסֵף שֶׁנִּמְשַׁל כְּשׁוֹר, יֹאכְלוּ אוֹתוֹ שֶׁנִּמְשַׁל כְּתֶבֶן:\",2,0],[2,120,66,1,\"הַשָּׁמַיִם כִּסְאִי. אֵינִי צָרִיךְ לְבֵית הַמִּקְדָּשׁ שֶׁלָּכֶם:\",1,0],[2,120,66,1,\"אֵיזֶה בַיִת. אֲשֶׁר הוּא כְּדַאי לִשְׁכִינָתִי:\",2,0],[2,120,66,2,\"וְאֶת כָּל אֵלֶּה. הַשָּׁמַיִם וְהָאָרֶץ יָדִי עָשָׂתָה, זֹאת אֲשֶׁר צִמְצַמְתִּי שְׁכִינָתִי בְּתוֹכְכֶם בִּהְיוֹתְכֶם נִשְׁמָעִים לִי, לְפִי שֶׁכֵּן דַּרְכִּי לְהַבִּיט אֶל עָנִי וּנְכֵה רוּחַ וְחָרֵד עַל דְּבָרִי. אֲבָל עַתָּה אֵין לִי חֵפֶץ בָּכֶם, שֶׁהֲרֵי שׁוֹחֵט הַשּׁוֹר הִכָּה אֶת בְּעָלָיו וּגְזָלוֹ מִמֶּנּוּ, לְפִיכָךְ זוֹבֵחַ הַשֶּׂה דּוֹמֶה לְפָנַי כְּעוֹרֵף אֶת הַכֶּלֶב, וְהַמַּעֲלֶה אֶת הַמִּנְחָה הֲרֵי הוּא לְפָנַי כְּדַם חֲזִיר, וְהַמַּזְכִּיר לְבוֹנָה מַקְטִיר לְבוֹנָה, כְּמוֹ ״אַזְכָּרָתָהּ״ (ויקרא ה:יב), ״וְהָיְתָה לַלֶּחֶם לְאַזְכָּרָה״ (ויקרא כד:ז):\",1,0],[2,120,66,3,\"מְבָרֵךְ אָוֶן. מְבָרֵךְ אוֹתִי בִּתְשׁוּרַת אֹנֶס, מְבָרֵךְ אָוֶן מַתְשִׁיר אֹנֶס – זֶהוּ פֵּרוּשׁוֹ. וּלְשׁוֹן ׳בְּרָכָה׳ נוֹפֵל בִּתְשׁוּרָה שֶׁהִיא לְהַקְבָּלַת פָּנִים, כְּמוֹ ״קַח נָא אֶת בִּרְכָתִי״ (בראשית לג:יא), ״עֲשׂוּ אִתִּי בְרָכָה וּצְאוּ אֵלַי״ (ישעיהו לו:טז):\",1,0],[2,120,66,3,\"גַּם הֵמָּה בָּחֲרוּ בְדַרְכֵיהֶם. הֵם חֲפֵצִים בַּדְּרָכִים הַלָּלוּ הָרָעִים, וְגַם אֲנִי אֶבְחַר וְאֶחְפּוֹץ בְּתַעֲלֻלֵיהֶם. וְאִם תֹּאמַר מַהוּ גַּם? כֵּן דֶּרֶךְ לְשׁוֹן עִבְרִי לוֹמַר שְׁנֵי גַמִּין זֶה אֵצֶל זֶה, כְּמוֹ ״גַּם בָּחוּר גַּם בְּתוּלָה״ (דברים לב:כה), ״גַּם לִי גַּם לָךְ״ (מלכים א ג:כו), ״גַּם אַהֲבָה גַּם שִׂנְאָה״ (קהלת ט:א), ״וְלֹא יָמוּתוּ גַּם הֵם גַּם אַתֶּם״ (במדבר יח:ג). אַף כָּאן – גַּם הֵם בָּחֲרוּ וְגַם אֲנִי אֶבְחַר:\",2,0],[2,120,66,4,\"בְּתַעֲלֻלֵיהֶם. לִהְיוֹת עוֹלֵל בָּם, לְשׁוֹן ״כִּי הִתְעַלַּלְתְּ בִּי״ (במדבר כב:כט):\",1,0],[2,120,66,4,\"וּמְגוּרֹתָם. מַה שֶּׁהֵם יְרֵאִים:\",2,0],[2,120,66,4,\"יַעַן קָרָאתִי: שִׁמְעוּ וְ״שׁוּבוּ אֵלַי״ (זכריה א:ג):\",3,0],[2,120,66,4,\"וְאֵין עוֹנֶה לֵאמֹר: ״שָׁמַעְתִּי״:\",4,0],[2,120,66,5,\"הַחֲרֵדִים אֶל דְּבָרוֹ. הַצַּדִּיקִים הַמְמַהֲרִים בַּחֲרָדָה לְהִתְקָרֵב אֶל דְּבָרָיו:\",1,0],[2,120,66,5,\"אָמְרוּ אֲחֵיכֶם. פּוֹשְׁעֵי יִשְׂרָאֵל הַנִּזְכָּרִים לְמַעְלָה. דָּבָר אַחֵר: אָמְרוּ אֲחֵיכֶם מְנַדֵּיכֶם. אֲשֶׁר אָמְרוּ לָכֶם ״סוּרוּ טָמֵא״ (איכה ד:טו):\",2,0],[2,120,66,5,\"שֹׂנְאֵיכֶם מְנַדֵּיכֶם. הָאוֹמְרִים ״קְרַב אֵלֶיךָ אַל תִּגַּשׁ בִּי״ (ישעיהו סה:ה). לְמַעַן שְׁמִי יִכְבַּד ה׳. בִּגְדֻלָּתֵנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְכַּבֵּד, שֶׁאָנוּ קְרוֹבִים לוֹ יוֹתֵר מִכֶּם:\",3,0],[2,120,66,5,\"וְנִרְאֶה בְשִׂמְחַתְכֶם וְהֵם יֵבֹשׁוּ. הַנָּבִיא אוֹמֵר: אֲבָל לֹא כֵן הוּא כְּדִבְרֵיהֶם, כִּי בְשִׂמְחַתְכֶם נִרְאֶה וְהֵם יֵבֹשׁוּ. לָמָּה? כִּי קוֹל שָׁאוֹן שֶׁלָּהֶם בָּא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מִמַּה שֶּׁעָשׂוּ בְּעִירוֹ, וְקוֹל יוֹצֵא מֵהֵיכָלוֹ וּמְקַטְרֵג עַל מַחֲרִיבָיו, וְאַחֲרֵי כֵן קוֹל ה׳ מְשַׁלֵּם גְּמוּל לְאֹיְבָיו:\",4,0],[2,120,66,7,\"בְּטֶרֶם תָּחִיל. צִיּוֹן חִיל הַיּוֹלֶדֶת, יָלָדָה אֶת בָּנֶיהָ, כְּלוֹמַר: יִתְקַבְּצוּ בָּנֶיהָ לְתוֹכָהּ, אֲשֶׁר הָיְתָה שׁוֹמֵמָה מֵהֶם וּשְׁכוּלָה, וַהֲרֵי הוּא כְּאִלּוּ יְלָדַתָּן עַכְשָׁיו בְּלֹא חֶבְלֵי יוֹלֵדָה, כִּי כָּל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת יְבִיאוּם לְתוֹכָהּ:\",1,0],[2,120,66,7,\"וְהִמְלִיטָה זָכָר. כָּל יְצִיאַת דָּבָר בָּלוּעַ קָרוּי דהַמְלָטָהד, וְהִמְלִיטָה אישקמוציי״ר בלע״ז:\",2,0],[2,120,66,8,\"הֲיוּחַל אֶרֶץ בְּיוֹם אֶחָד. הֲיָבוֹא חִיל לְיוֹלֶדֶת לֵילֵד מְלֹא אֶרֶץ בָּנִים בְּיוֹם אֶחָד?\",1,0],[2,120,66,9,\"הַאֲנִי אַשְׁבִּיר וְלֹא אוֹלִיד. הַאֲנִי אָבִיא אֶת הָאִשָּׁה עַל הַמַּשְׁבֵּר וְלֹא אֶפְתַּח רַחְמָהּ לְהוֹצִיא עֻבָּרָהּ? כְּלוֹמַר: שֶׁמָּא אַתְחִיל בְּדָבָר וְלֹא אוּכַל לִגְמוֹר? וַהֲלֹא אֲנִי הַמּוֹלִיד אֶת כָּל הַיּוֹלְדוֹת, וְעַכְשָׁיו שֶׁמָּא עָצַרְתִּי? בְּתְמִיהָה:\",1,0],[2,120,66,11,\"מִשֹּׁד. לְשׁוֹן ׳שָׁדַיִם׳:\",1,0],[2,120,66,11,\"תָּמֹצּוּ. שוציי״ר בלע״ז:\",2,0],[2,120,66,11,\"מִזִּיז כְּבוֹדָהּ. מִכָּבוֹד גָּדוֹל הַזָּז וּמְמַשְׁמֵשׁ לָבֹא לָהּ:\",3,0],[2,120,66,11,\"זִיז. אישמובימנ״ט בלע״ז:\",4,0],[2,120,66,12,\"וּכְנַחַל שׁוֹטֵף. אֲנִי נֹטֶה אֵלֶיהָ כְּבוֹד גּוֹיִם:\",1,0],[2,120,66,12,\"עַל צַד. עַל צִדֵּי אוֹמְנֵיכֶם, ״עַל גִּסְסִין״ (תרגום יונתן):\",2,0],[2,120,66,12,\"תְּשָׁעֳשָׁעוּ. תִּהְיוּ מְשֻׁעְשָׁעִין, כְּדֶרֶךְ שֶׁמְּשַׁעְשְׁעִין אֶת הַתִּינוֹק, אישבניי״ר בלע״ז:\",3,0],[2,120,66,14,\"וְנוֹדְעָה יַד ה׳. בַּעֲשׂוֹתוֹ נִקְמוֹתָיו וְנוֹרְאוֹתָיו, יֵדְעוּ עֲבָדָיו אֶת כֹּחַ גְּבוּרַת יָדוֹ:\",1,0],[2,120,66,15,\"בָּאֵשׁ יָבוֹא. בְּחֵמַת אֵשׁ יָבוֹא עַל הָרְשָׁעִים:\",1,0],[2,120,66,15,\"לְהָשִׁיב. לְצָרָיו בְּחֵמָה אֶת אַפּוֹ:\",2,0],[2,120,66,16,\"כִּי בָאֵשׁ שֶׁל גֵּיהִנֹּם ה׳ נִשְׁפָּט עִם צָרָיו, וּלְפִי שֶׁהוּא בַּעַל דִּין וְדַיָּן, נוֹפֵל בּוֹ לְשׁוֹן ׳נִשְׁפָּט׳, שֶׁאַף הוּא טוֹעֵן טַעֲנוֹתָיו לִמְצוֹא עֲוֹנָם וּפִשְׁעָם, וְכֵן ״וְנִשְׁפַּטְתִּי אִתּוֹ״ (יחזקאל לח:כב), ״הִנְנִי נִשְׁפָּט אוֹתָךְ״ (ירמיהו ב:לה), לְשׁוֹן ׳וִכּוּחַ׳ הוּא, דרישניי״ר בלע״ז, וּפְשׁוּטוֹ כִּי בָאֵשׁ ה׳ וְחַרְבּוֹ נִשְׁפָּט כָּל בָּשָׂר וְכֵן רַבִּים מְסֹרָסִים בַּמִּקְרָאוֹת:\",1,0],[2,120,66,17,\"הַמִּתְקַדְּשִׁים. הַמִּזְדַּמְּנִים, ״אֲנִי וְאַתָּה נֵלֵךְ לְיוֹם פְּלוֹנִי לַעֲבוֹד לְעֲבוֹדָה זָרָה פְּלוֹנִית״:\",1,0],[2,120,66,17,\"אֶל הַגַּנּוֹת. שֶׁזּוֹרְעִין שָׁם יָרָק, וְשָׁם הָיוּ מַעֲמִידִין עֲבוֹדָה זָרָה:\",2,0],[2,120,66,17,\"אַחַר אַחַת. כְּמָה שֶׁתִּרְגֵּם יוֹנָתָן: ״סִיעָה בָּתַר סִיעָה״; מִתְקַדְּשִׁים וּמִטַּהֲרִים לַעֲבוֹד, סִיעָה אַחַר שֶׁגָּמְרָה חֲבֶרְתָּהּ אֶת עֲבוֹדָתָהּ:\",3,0],[2,120,66,17,\"בַּתָּוֶךְ. בְּאֶמְצַע הַגִּנָּה, כֵּן הָיָה דַּרְכָּם לְהַעֲמִידָהּ:\",4,0],[2,120,66,18,\"וְאָנֹכִי מַעֲשֵׂיהֶם וּמַחְשְׁבֹתֵיהֶם בָּאָה וגו׳. וְאָנֹכִי מָה לִי לַעֲשׂוֹת? מַעֲשֵׂיהֶם וּמַחְשְׁבוֹתֵיהֶם בָּאָה אֵלַי, וְהִיא תַּזְקִיקֵנִי לְקַבֵּץ אֶת כָּל הַגּוֹיִם וּלְהוֹדִיעַ שֶׁמַּעֲשֵׂיהֶם הֶבֶל, וּמַחְשְׁבוֹתָם שֶׁהֵם חוֹשְׁבִין ״לְמַעַן שְׁמִי יִכְבַּד ה׳״ (ישעיהו סו:ה), יָבִינוּ שֶׁהוּא שֶׁקֶר. וְהֵיכָן הוּא אוֹתוֹ קִבּוּץ? הוּא הָאָסִיף שֶׁנִּבָּא זְכַרְיָה ״וְאָסַפְתִּי אֶת כָּל הַגּוֹיִם אֶל יְרוּשָׁלִָם״ (זכריה יד:ב):\",1,0],[2,120,66,18,\"וְרָאוּ אֶת כְּבוֹדִי. בְּהִלָּחֲמִי בָּהֶם בְּמַכַּת ״הָמֵק בְּשָׂרוֹ וְעֵינָיו וּלְשׁוֹנוֹ״ (זכריה יד:יב):\",2,0],[2,120,66,19,\"וְשַׂמְתִּי בָהֶם אוֹת וְגוֹ׳. פְּלֵיטִים יִנָּצְלוּ מִן הַמִּלְחָמָה וַאֲנִי אַשְׁאִירֵם, כְּדֵי לֵילֵךְ לְבַשֵּׂר לָאִיִּים הָרְחוֹקִים אֶת כְּבוֹדִי אֲשֶׁר רָאוּ בַּמִּלְחָמָה, וְאַף בְּאוֹתָם פְּלֵיטִים אָשִׂים אַחַת מִן הָאוֹתוֹת שֶׁנִּדּוֹנוּ חֲבֵירֵיהֶם בָּהֶם, כְּדֵי לְהוֹדִיעַ לָרְחוֹקִים: בְּמַגֵּפָה זוֹ נִגְּפוּ הַצּוֹבְאִים עַל יְרוּשָׁלַיִם:\",1,0],[2,120,66,20,\"וּבַצַּבִּים. הֵם עֲגָלוֹת מְטֻקָּסוֹת בִּמְחִיצוֹת וְאֹהֶל, וְדוֹמֶה לוֹ ״שֵׁשׁ עֶגְלֹת צָב״ (במדבר ז:ג):\",1,0],[2,120,66,20,\"וּבַכִּרְכָּרוֹת. בְּשִׁיר מְשַׂחֲקִים וּמְכַרְכְּרִים, כְּמוֹ ״וְדָוִד מְכַרְכֵּר״ (שמואל ב ו:יד). טריפי״ר בלע״ז. וּמְנַחֵם פֵּרְשׁוֹ לְשׁוֹן ׳כֶּבֶשׂ׳, כְּמוֹ ״שִׁלְחוּ כַר מֹשֵׁל אֶרֶץ״ (ישעיהו טז:א):\",2,0],[2,120,66,20,\"כַּאֲשֶׁר יָבִיאוּ. מִנְחָה בִּכְלִי טָהוֹר לְרָצוֹן, כֵּן יָבִיאוּ אֶת אֲחֵיכֶם לְמִנְחַת רָצוֹן:\",3,0],[2,120,66,21,\"וְגַם מֵהֶם אֶקַּח לַכֹּהֲנִים לַלְוִיִּם. מִן הָעַמִּים הַמְּבִיאִים אוֹתָם, וּמִן הַמּוּבָאִים אֶקַּח כֹּהֲנִים וּלְוִיִּם, וּלְפָנַי גְּלוּיִים הַכֹּהֲנִים וְהַלְוִיִּם שֶׁבָּהֶם, וְאָבְרוֹר אוֹתָן מִתּוֹכָן, וְיִהְיוּ מְשַׁמְּשִׁין לְפָנַי:\",1,0],[2,120,66,21,\"אָמַר ה׳. וְהֵיכָן אָמַר? ״הַנִּסְתָּרוֹת לַה׳ אֱלֹהֵינוּ״ (דברים כט:כח). כָּךְ מְפֹרָשׁ בְּאַגָּדַת תְּהִלִּים:\",2,0],[2,120,66,24,\"תּוֹלַעְתָּם. רִמָּה הָאוֹכֶלֶת אֶת בְּשָׂרָם:\",1,0],[2,120,66,24,\"וְאִשָּׁם בַּגֵּיהִנֹּם:\",2,0],[2,120,66,24,\"דֵרָאוֹן. לְשׁוֹן ׳בִּזָּיוֹן׳, וְיוֹנָתָן תִּרְגֵּם כְּמִין שְׁתֵּי תֵיבוֹת: דֵּי רְאִיָּה, ״עַד דְּיֵימְרוּן עֲלֵיהוֹן צַדִּיקַיָּא מִיסַת חֲזִינָא״:\",3,0],[2,121,1,1,\"דִּבְרֵי יִרְמְיָהוּ בֶּן חִלְקִיָּהוּ וְגוֹ׳. לֵיתֵי בַּר קַלְקַלְתָּא דְּתַקְנָן עוֹבְדוֹהִי – יִרְמְיָה בָּא מֵרָחָב הַזּוֹנָה (יהושע ב:א), וְלוֹכַח בַּר מְתַקְּנְתָּא דִּמְקַלְקְלָן עוֹבְדוֹהִי – אֵלּוּ יִשְׂרָאֵל שֶׁקִּלְקְלוּ מַעֲשֵׂיהֶן, שֶׁבָּאוּ מִזֶּרַע כָּשֵׁר (פסיקתא רבתי יג,ד):\",1,0],[2,121,1,2,\"אֲשֶׁר הָיָה דְבַר ה׳ אֵלָיו וְגוֹ׳. אֲשֶׁר הִתְחִילָה שְׁכִינָה לִשְׁרוֹת עָלָיו בְּאוֹתוֹ הַזְּמַן:\",1,0],[2,121,1,3,\"וַיְהִי בִּימֵי יְהוֹיָקִים. וַיְהִי נָבִיא כָּל יְמֵי יֹאשִׁיָּהוּ הַנּוֹתָרִים, וִימֵי יְהוֹיָקִים בְּנוֹ וִימֵי צִדְקִיָּהוּ בְּנוֹ, עַד תֹּם עַשְׁתֵּי עֶשְׂרֵה שָׁנָה, הִיא הַשָּׁנָה עַד גְּלוֹת יְרוּשָׁלִַם בַּחֹדֶשׁ הַחֲמִישִׁי:\",1,0],[2,121,1,5,\"בְּטֶרֶם אֶצָּרְךָ בַבֶּטֶן וְגוֹ׳. מִימֵי אָדָם הָרִאשׁוֹן; הֶרְאָהוּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאָדָם דּוֹר וְדוֹר וּנְבִיאָיו (סדר עולם רבה ל):\",1,0],[2,121,1,5,\"אֶצָּרְךָ. לְשׁוֹן צוּרָה:\",2,0],[2,121,1,5,\"יְדַעְתִּיךָ. קְנִיּוֹשְׁטְ״וִי בְּלַעַ״ז, כְּמוֹ ״לֹא נוֹדַעְתִּי לָהֶם״ (שמות ו:ג):\",3,0],[2,121,1,5,\"הִקְדַּשְׁתִּיךָ. זִמַּנְתִּיךָ לְכָךְ:\",4,0],[2,121,1,5,\"נָבִיא לַגּוֹיִם. לְיִשְׂרָאֵל שֶׁהָיוּ נוֹהֲגִים עַצְמָם כַּגּוֹיִם, כָּךְ נִדְרַשׁ בְּסִפְרֵי: ״נָבִיא מִקִּרְבְּךָ וְגוֹ׳ יָקִים לְךָ״ (דברים יח:טו) וְלֹא לְמַכְחִישֵׁי תּוֹרָה. הָא מָה אֲנִי מְקַיֵּם נָבִיא לַגּוֹיִם נְתַתִּיךָ? בְּנוֹהֲגֵי מִנְהַג גּוֹיִם. וְעוֹד יֵשׁ לִפְתּוֹר: נָבִיא לַגּוֹיִם כְּמוֹ ״עַל הַגּוֹיִם״ (ירמיהו י:כה); לְהַשְׁקוֹתָם כּוֹס תַּרְעֵלָה, לְהִנָּבֵא עֲלֵיהֶם פּוּרְעָנוּת, כְּמָה שֶׁנֶּאֱמַר ״קַח אֶת כּוֹס הַיַּיִן הַחֵמָה הַזֹּאת … וְהִשְׁקִיתָה אֹתוֹ אֶת כׇּל הַגּוֹיִם״ (ירמיהו כה:טו). דָּבָר אַחֵר: בְּטֶרֶם תֵּצֵא מֵרֶחֶם הִקְדַּשְׁתִּיךָ, עָלֶיךָ אָמַרְתִּי לְמֹשֶׁה: ״נָבִיא אָקִים לָהֶם כָּמוֹךָ״ (דברים יח:יח). זֶה הוֹכִיחָם וְזֶה הוֹכִיחָם, זֶה נִתְנַבֵּא אַרְבָּעִים שָׁנָה וְזֶה נִתְנַבֵּא אַרְבָּעִים שָׁנָה:\",5,0],[2,121,1,6,\"אֲהָהּ. לְשׁוֹן יְלָל, קוֹנְפְּלֵיינְ״ט בְּלַעַ״ז:\",1,0],[2,121,1,6,\"כִּי נַעַר אָנֹכִי. אֵינִי כְדַאי לְהוֹכִיחָן. מֹשֶׁה הוֹכִיחָן סָמוּךְ לְמִיתָתוֹ (דברים א), כְּבָר נֶחְשַׁב בְּעֵינֵיהֶם בְּכַמָּה נִסִּים שֶׁעָשָׂה לָהֶם: הוֹצִיאָם מִמִּצְרַיִם (שמות יב:לא-מג), וְקָרַע לָהֶם אֶת הַיָּם (שמות יד:טו-לא), הוֹרִיד אֶת הַמָּן, הֵגִיז אֶת הַשְּׂלָיו (במדבר יא), נָתַן לָהֶם אֶת הַתּוֹרָה (שמות לד), הֶעֱלָה אֶת הַבְּאֵר (במדבר כא:טז-יח); אֲנִי, בִּתְחִלַּת שְׁלִיחוּתִי אֲנִי בָּא לְהוֹכִיחָם?!\",2,0],[2,121,1,7,\"עַל כָּל אֲשֶׁר אֶשְׁלָחֲךָ. אֶל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:\",1,0],[2,121,1,7,\"וְאֵת כָּל אֲשֶׁר אֲצַוְּךָ. לְיִשְׂרָאֵל תְּדַבֵּר:\",2,0],[2,121,1,9,\"וַיִּשְׁלַח ה׳ אֶת יָדוֹ. כָּל שְׁלִיחוּת שֶׁהוּא אֵצֶל יָד – לְשׁוֹן הוֹשָׁטָה. לָשׁוֹן אַחֵר: כַּתַּרְגּוּם: ״וְשָׁלַח ה׳ יָת פִּתְגָמֵי נְבִיאוּתֵיהּ״:\",1,0],[2,121,1,10,\"הִפְקַדְתִּיךָ. מִנִּיתִיךָ עַל הַגּוֹיִם:\",1,0],[2,121,1,10,\"לנתוש ולנתוץ. דיספציר בְּלַעַ״ז:\",2,0],[2,121,1,11,\"מַקֵּל שָׁקֵד. מַנְדוֹלִי״ר בְּלַעַ״ז, וְיוֹנָתָן תִּרְגֵּם מַקֵּל שָׁקֵד ״מֶלֶךְ דְּמוֹחִי לְאַבְאָשָׁא״:\",1,0],[2,121,1,12,\"הֵיטַבְתָּ לִרְאוֹת. הַשָּׁקֵד הַזֶּה הוּא מְמַהֵר לְהוֹצִיא פֶרַח קֹדֶם לְכָל הָאִילָנוֹת, אַף אֲנִי מְמַהֵר לַעֲשׂוֹת דְּבָרִי. וּמִדְרַשׁ אַגָּדָה (ירושלמי תענית ד, ה): הַשָּׁקֵד הַזֶּה הוּא מִשְּׁעַת חֲנִיטָתוֹ עַד גְּמַר בִּשּׁוּלוֹ עֶשְׂרִים וְאֶחָד יוֹם, כְּמִנְיַן יָמִים שֶׁבֵּין שִׁבְעָה עָשָׂר בְּתַמּוּז שֶׁבּוֹ הָבְקְעָה הָעִיר, לְתִשְׁעָה בְּאָב שֶׁבּוֹ נִשְׂרַף הַבַּיִת:\",1,0],[2,121,1,13,\"סִיר נָפוּחַ. רוֹתֵחַ בּוֹיִילְנְ״ט בְּלַעַ״ז:\",1,0],[2,121,1,13,\"וּפָנָיו. רְתִיחוֹתָיו, אֵשִׁישׁאוֹנְדִי״שׁ בְּלַעַ״ז:\",2,0],[2,121,1,14,\"מִצָּפוֹן תִּפָּתַח הָרָעָה. בָּבֶל לִצְפוֹנָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל הִיא (גיטין ו.):\",1,0],[2,121,1,16,\"וְדִבַּרְתִּי מִשְׁפָּטַי אוֹתָם. אֶתְוַכַּח עִמָּם, עִם יְהוּדָה וִירוּשָׁלִָם:\",1,0],[2,121,1,17,\"תֶּאְזֹר מָתְנֶיךָ. לְשׁוֹן זֵרוּז, כְּאִישׁ חַיִל:\",1,0],[2,121,1,18,\"לְמַלְכֵי יְהוּדָה. כְּנֶגֶד מַלְכֵי יְהוּדָה:\",1,0],[2,121,1,19,\"וְנִלְחֲמוּ אֵלֶיךָ. ״וִיהוֹן דָּיְנִין וּמְגִיחִין לְקָבְלָךְ לְמִסְתַּר יָת פִּתְגָמֵי נְבוּאָתָךְ״:\",1,0],[2,121,2,2,\"זָכַרְתִּי לָךְ. אִם הֱיִיתֶם שָׁבִים אֵלַי, תַּאֲוָתִי לְרַחֵם עֲלֵיכֶם, כִּי זָכַרְתִּי חֶסֶד נְעוּרַיִךְ וְאַהֲבַת כְּלִילַת חֻפָּתֵךְ, שֶׁהִכְלַלְתִּיךְ לְחֻפָּה; וְלָשׁוֹן הַכְנָסָה הוּא. כְּלוּלֹתָיִךְ נוֹצִי״שׁ בְּלַעַ״ז. וּמַה הוּא חֶסֶד נְעוּרַיִךְ? לֶכְתֵּךְ אַחַר שְׁלוּחַי, מֹשֶׁה וְאַהֲרֹן; מֵאֶרֶץ נוֹשָׁבֶת (שמות טז:לה) יְצָאתֶם לַמִּדְבָּר, וְאֵין צֵדָה לַדֶּרֶךְ, כִּי הֶאֱמַנְתֶּם בִּי (מכילתא בא פסחא יד):\",1,0],[2,121,2,3,\"קֹדֶשׁ יִשְׂרָאֵל. כִּתְרוּמָה:\",1,0],[2,121,2,3,\"רֵאשִׁית תְּבוּאָתֹה. כְּרֵאשִׁית קָצִיר לִפְנֵי הָעֹמֶר, שֶׁאָסוּר בַּאֲכִילָה וְהָאוֹכְלוֹ מִתְחַיֵּב, כֵּן כָּל אֹכְלָיו יֶאְשָׁמוּ. כֵּן תַּרְגֵּם יוֹנָתָן:\",2,0],[2,121,2,6,\"וְלֹא אָמְרוּ אַיֵּה ה׳. כִּי נֵלֵךְ אַחֲרֵי אֱלֹהִים אֲחֵרִים:\",1,0],[2,121,2,6,\"עֲרָבָה. פְּלַנוּרָ״א בְּלַעַ״ז:\",2,0],[2,121,2,6,\"וְשׁוּחָה. נְטוּיָה, אִינְפוּשִׁיאָ״ה בְּלַעַ״ז:\",3,0],[2,121,2,6,\"צִיָּה. דִּישְׁגַאטָ״ה בְּלַעַ״ז:\",4,0],[2,121,2,6,\"וְצַלְמָוֶת. לְשׁוֹן חֹשֶׁךְ:\",5,0],[2,121,2,7,\"אֶל אֶרֶץ הַכַּרְמֶל. ״לְאַרְעָא דְיִשְׂרָאֵל דַּהֲוַת מְנַצְּבָא כְּכַרְמְלָא״ (תרגום יונתן; פסיקתא רבתי טו, א), פֵּירֵשׁ נְטוּעָה כְּיַעַר:\",1,0],[2,121,2,8,\"תּוֹפְשֵׂי הַתּוֹרָה. סַנְהֶדְרִין:\",1,0],[2,121,2,8,\"וְהָרֹעִים. הַמְּלָכִים:\",2,0],[2,121,2,8,\"נִבְּאוּ בַבַּעַל. בְּשֵׁם הַבַּעַל:\",3,0],[2,121,2,9,\"עוֹד אָרִיב. טֶרֶם אָבִיא עֲלֵיכֶם רָעָה, אֶתְוַכַּח עִמָּכֶם עוֹד עַל יְדֵי נְבִיאַי, אַף עַל פִּי שֶׁרַבְתִּי עִמָּכֶם כְּבָר יָמִים רַבִּים:\",1,0],[2,121,2,10,\"אִיֵּי כִתִּיִּים. לְאִיֵּי כִתִּיִּים:\",1,0],[2,121,2,10,\"אִיֵּי. אִישְׁלַ״שׁ בְּלַעַ״ז:\",2,0],[2,121,2,10,\"וְקֵדָר שִׁלְחוּ. וְלִקְדָר שִׁלְחוּ לִרְאוֹת מִנְהָגָם:\",3,0],[2,121,2,10,\"וְהִתְבּוֹנְנוּ מְאֹד. וְשִׂימוּ לֵב לְהִסְתַּכֵּל בַּדָּבָר יָפֶה:\",4,0],[2,121,2,10,\"הֵן. כְּמוֹ אִם, אִם הֵמִיר גּוֹי מֵהֶם אֶת אֱלֹהָיו וְאַף עַל פִּי שֶׁהֵמָּה לֹא אֱלֹהִים, וְעַמִּי הֵמִיר אֶת כְּבוֹדוֹ אֲשֶׁר בּוֹ הָיָה נִכְבָּד. וְכִתִּיִּים וְקֵדָרִיִּים יוֹשְׁבֵי אֹהָלִים וְרוֹעֵי מִקְנֶה, וְנוֹסְעִים וְהוֹלְכִים וּמִטַּלְטְלִין מִמִּרְעֶה לְמִרְעֶה וּמִמִּדְבָּר לְמִדְבָּר, וְנוֹשְׂאִים אֶת אֱלֹהֵיהֶם עִמָּהֶם לְמָקוֹם שֶׁחוֹנִים שָׁם, וַאֲנִי נָשָׂאתִי אֶתְכֶם עַד אֲשֶׁר קָבַעְתִּי אֶתְכֶם, וְהִנַּחְתֶּם אוֹתִי, כָּךְ תִּרְגֵּם יוֹנָתָן. וְרַבּוֹתֵינוּ אָמְרוּ (תענית ה:): כִּתִּיִּים עוֹבְדִים לַמַּיִם, וְקֵדָרִיִּים עוֹבְדִים לָאֵשׁ, וְאַף עַל פִּי שֶׁיּוֹדְעִים שֶׁהַמַּיִם מְכַבִּין אֶת הָאֵשׁ, לֹא הִנִּיחוּ אֶת אֱלֹהֵיהֶם:\",5,0],[2,121,2,11,\"בְּלֹא יוֹעִיל. בַּעֲבוֹדָה זָרָה שֶׁאֵין בָּהּ תּוֹעֶלֶת:\",1,0],[2,121,2,12,\"שֹׁמּוּ שָׁמַיִם. לְשׁוֹן תִּמָּהוֹן, כְּמוֹ הִשְׁתּוֹמְמוּ; וְהוּא לְשׁוֹן צִוּוּי, כְּמוֹ ״אִם כֹּה יֹאמְרוּ אֵלֵינוּ דֹּמּוּ״ (שמואל א יד:ט):\",1,0],[2,121,2,12,\"וְשַׂעֲרוּ. לְשׁוֹן סַעַר:\",2,0],[2,121,2,12,\"חָרְבוּ מְאֹד. כְּאִלּוּ אַתֶּם נֶחֱרָבִים עַל בֵּית הַמִּקְדָּשׁ שֶׁעָתִיד לֵיחָרֵב:\",3,0],[2,121,2,13,\"שְׁתַּיִם רָעוֹת. אִם הֵמִירוּ יִרְאָתָם בְּכַיּוֹצֵא בָּהּ, יֵשׁ כָּאן רָעָה אַחַת; וְעַכְשָׁיו שֶׁאוֹתִי עָזְבוּ, שֶׁאֲנִי מְקוֹר מַיִם חַיִּים, לָלֶכֶת אַחֲרֵי הָעֲבוֹדָה הַזָּרָה, שֶׁהֵם כְּבֹארוֹת שֶׁל מַיִם מְכֻנָּסִין וְנִשְׁבָּרִין וְנִסְדָּקִין, וּמֵימֵיהֶם נִבְלָעִים בִּסְדָקֵיהֶם, הֲרֵי שְׁתַּיִם רָעוֹת:\",1,0],[2,121,2,13,\"לַחְצֹב. לַחְפֹּר:\",2,0],[2,121,2,13,\"אֲשֶׁר לֹא יָכִלוּ. טִינְדְרוֹנְ״ט בְּלַעַ״ז אֶת מֵימֵיהֶם; שֶׁהַמַּיִם מְטַשְׁטְשִׁין אֶת שְׂפָתָם וְכוֹתְלֵיהֶם וְהֵם נוֹפְלִין:\",3,0],[2,121,2,14,\"יְלִיד בַּיִת. בֶּן הָאָמָה:\",1,0],[2,121,2,15,\"יִשְׁאֲגוּ. שׁוֹאֲגִים, לְשׁוֹן הֹוֶה:\",1,0],[2,121,2,15,\"כְּפִירִים. מְלָכִים:\",2,0],[2,121,2,15,\"נִצְּתוּ. נִצְּתוּ בָּאֵשׁ:\",3,0],[2,121,2,16,\"גַּם בְּנֵי נֹף וְתַחְפַּנְחֵס. הֵם מִצְרַיִם שֶׁאַתֶּם בּוֹטְחִים עֲלֵיהֶם לְעֶזְרָה:\",1,0],[2,121,2,16,\"יִרְעוּךְ קָדְקֹד. לְשׁוֹן רְצִיצָה, כְּדִמְתַרְגְּמִינָן ״וְרָצוּץ״ (דברים כח:לג): ״וּרְעִיעַ״:\",2,0],[2,121,2,17,\"הֲלֹא זֹאת תַּעֲשֶׂה לָּךְ. הֲלֹא אֶת הָרָעָה וְאֶת הַפּוּרְעָנוּת הַזֹּאת תִּגְרֹם לָךְ הָאַשְׁמָה וְהֶעָוֹן אֲשֶׁר עָזַבְתְּ אֶת ה׳ אֱלֹהַיִךְ:\",1,0],[2,121,2,17,\"בְּעֵת מוֹלִיכֵךְ בַּדָּרֶךְ. שֶׁהָיָה מְלַמֵּד אוֹתְךָ דֶּרֶךְ הַטּוֹבָה וְהַיְשָׁרָה:\",2,0],[2,121,2,18,\"מַה לָּךְ לְדֶרֶךְ מִצְרַיִם. לָמָּה תַּעַזְבִי אוֹתִי וְתִבְטְחִי עַל מִצְרַיִם?\",1,0],[2,121,2,18,\"לִשְׁתּוֹת מֵי שִׁחוֹר. שֶׁטִּבְּעוּ זְכוֹרֵיכֶם בַּנִּילוּס; שִׁחוֹר הוּא נִילוּס, כְּמָה שֶׁנֶּאֱמַר ״מִן הַשִּׁיחוֹר אֲשֶׁר עַל פְּנֵי מִצְרָיִם״ בְּסֵפֶר יְהוֹשֻׁעַ (יהושע יג:ג):\",2,0],[2,121,2,18,\"וּמַה לָּךְ. לִמְרֹד בִּי לְמַעַן תִּגְלִי לְדֶרֶךְ אַשּׁוּר, לְמֵעֵבֶר נְהַר פְּרָת:\",3,0],[2,121,2,19,\"תְּיַסְּרֵךְ רָעָתֵךְ. סוֹף שֶׁרָעָתֵךְ תָּבִיא עָלֶיךָ יִסּוּרִין:\",1,0],[2,121,2,19,\"וּמְשׁוּבוֹתַיִךְ. לְשׁוֹן ״בָּנִים שׁוֹבָבִים״ (ירמיה ג:יד):\",2,0],[2,121,2,19,\"תּוֹכִיחוּךְ. לְשׁוֹן ״מוּסָר״ (ירמיה ל:יד):\",3,0],[2,121,2,19,\"וְלֹא פַחְדָּתִי. פַּחַד שֶׁלִּי לֹא הָיָה בְּלִבֵּךְ לִירָא אוֹתִי:\",4,0],[2,121,2,20,\"שָׁבַרְתִּי עֻלֵּךְ. הָעוֹל שֶׁל עֵץ נוֹפֵל בּוֹ לְשׁוֹן שְׁבִירָה, וְהַמּוֹסְרוֹת, שֶׁהֵן שֶׁל עוֹר, נוֹפֵל בָּהֶן לְשׁוֹן נְתִיקָה:\",1,0],[2,121,2,20,\"מוֹסְרוֹתַיִךְ. הֵם רְצוּעוֹת שֶׁקּוֹשְׁרִין בָּהֶם הָעוֹל:\",2,0],[2,121,2,20,\"וַתֹּאמְרִי לֹא אֶעֱבוֹר. עַל דְּבָרֶיךָ:\",3,0],[2,121,2,20,\"כִּי עַל כָּל גִּבְעָה. אַךְ אַתָּה לֹא שָׁמַרְתָּ הַבְטָחָתְךָ, וְעַל כָּל גִּבְעָה אַתְּ צֹעָה – לְשׁוֹן מִשְׁכָּב וּמַצָּע. כִּי מְשַׁמֵּשׁ לְשׁוֹן אֶלָּא:\",4,0],[2,121,2,21,\"נְטַעְתִּיךְ שׂוֹרֵק. שׂוֹרֵק הוּא זְמוֹרוֹת גֶּפֶן טוֹב, כְּלוֹמַר בְּנֵי אָבוֹת כְּשֵׁרִים וְצַדִּיקִים. וּמִדְרָשׁוֹ: נְטַעְתִּיךְ שׂוֹרֵק, הוֹסַפְתִּי לְךָ עַל שֶׁבַע מִצְווֹת שֶׁל בְּנֵי נֹחַ שֵׁשׁ מֵאוֹת וָשֵׁשׁ, כְּמִנְיַן שׂוֹרֵ״ק:\",1,0],[2,121,2,21,\"סוּרֵי. דִישְׁטוֹרְלָטוֹ״רְשׁ בְּלַעַ״ז:\",2,0],[2,121,2,21,\"גֶּפֶן נָכְרִיָּה. הַצּוֹמַחַת בַּיְּעָרִים:\",3,0],[2,121,2,22,\"בַּנֶּתֶר. מִין אֲדָמָה שֶׁחָפִין וְשָׁפִין בָּהּ אֶת הַבְּגָדִים:\",1,0],[2,121,2,22,\"בּוֹרִית. נִקָּיוֹן, כְּמוֹ ״וּבַר לֵבָב״ (תהלים כד:ד). וְיֵשׁ לוֹעֲזִים בּוֹרִית – שָׁאבוֹ״ן בְּלַעַז:\",2,0],[2,121,2,22,\"נִכְתָּם עֲוֺנֵךְ. ״הָא כְּרוֹשֶׁם כִּתְמָא דְּלָא דָכֵי, כֵּן סַגִּיאוּ חוֹבֵיךְ קֳדָמַי״ (תרגום יונתן):\",3,0],[2,121,2,22,\"כֶּתֶם. טָאקָ״א בְּלַעַ״ז:\",4,0],[2,121,2,22,\"עֲוֺנֵךְ. עַל עֲוֹן הָעֵגֶל נֶאֱמַר, שֶׁהוּא קַיָּם לְעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר ״וּבְיוֹם פָּקְדִי וּפָקַדְתִּי עֲלֵיהֶם״ (שמות לב:לד) – כָּל פְּקִידוֹת הַבָּאוֹת עַל יִשְׂרָאֵל, יִהְיֶה מִקְצָת עֲוֹן הָעֵגֶל בָּהֶם (סנהדרין קב.):\",5,0],[2,121,2,23,\"רְאִי דַרְכֵּךְ בַּגַּיְא. מָה עָשִׂית מוּל בֵּית פְּעוֹר (דברים ג:כט)! וְעוֹדֵ עַתָּה אַתְּ מַחֲזֶקֶת בְּאוֹתוֹ הַדֶּרֶךְ כִּבְכָרָה קַלָּה הַמְשָׂרֶכֶת דְּרָכֶיהָ:\",1,0],[2,121,2,23,\"בִּכְרָה. גְּמַלָּה נְקֵבָה בְּחוּרָה, שֶׁהִיא אוֹהֶבֶת לָנוּעַ. ״בִּכְרֵי מִדְיָן״ (ישעיהו ס:ו) מְתֻרְגָּם: ״הוֹגְנֵי מִדְיָן״, וְהֵם גְּמַלִּים בְּחוּרִים; כְּמוֹ שֶׁמָּצִינוּ בְּסַנְהֶדְרִין (סנהדרין נב.): נְפִישֵׁי גְּמַלֵּי סָבֵי דְּטָעֲינִי מַשְׁכֵּי דְּהוֹגְנֵי:\",2,0],[2,121,2,23,\"מְשָׂרֶכֶת. מַחֲזֶקֶת בְּדַרְכֵי נְעוּרֶיהָ; לְשׁוֹן מַסְרִיךְ (בבא מציעא ו.), סָרִיךְ (גיטין סח:). וְיֵשׁ לְחַבְּרוֹ עִם ״שְׂרוֹךְ נַעַל״ (בראשית יד:כג) – קוֹשֶׁרֶת דַּרְכֵי נַעֲרוּתָהּ בְּלִבָּהּ:\",3,0],[2,121,2,24,\"פֶּרֶה. שַׁלְוָואטִיקְ״וּ בְּלַעַ״ז, וְיֵשׁ לוֹעֲזִין קוּלִיי״ן בְּלַעַ״ז:\",1,0],[2,121,2,24,\"לִמּוּד מִדְבָּר. הַלָּמוּד לִהְיוֹת בַּמִּדְבָּרוֹת; כֵּן אָהַבְתְּ לָנוּעַ:\",2,0],[2,121,2,24,\"שָׁאֲפָה רוּחַ. פּוֹתַחַת אֶת פִּיהָ וְשׁוֹאֶפֶת רוּחַ, וּלְעוֹלָם הוּא חוֹזֵר לִמְקוֹמוֹ (קהלת א:ו):\",3,0],[2,121,2,24,\"תַּאֲנָתָהּ מִי יְשִׁיבֶנָּה. אוֹתָהּ מִדַּת תַּנִּינִים שֶׁיֵּשׁ בָּהּ, כִּי גַּם הַתַּנִּין שׁוֹאֵף רוּחַ, כְּמָה שֶׁנֶּאֱמַר ״שָׁאֲפוּ רוּחַ כַּתַּנִּים״ (ירמיה יד:ו). מִי יְשִׁיבֶנָּה מֵאוֹתָהּ מִדָּה? כֵּן אַתֶּם, מִי יוּכַל לַהֲשִׁיבְכֶם מִדַּרְכְּכֶם הָרָעָה?\",4,0],[2,121,2,24,\"כָּל מְבַקְשֶׁיהָ לֹא יִיעָפוּ. כִּי עַל חִנָּם יִיעָפוּ, שֶׁלֹּא יוּכְלוּ לְהַשִּׂיגָהּ. וּמַה סוֹפָהּ? בְּחָדְשָׁהּ יִמְצָאוּנְהָ. חֹדֶשׁ אֶחָד יֵשׁ בַּשָּׁנָה שֶׁהִיא יְשֵׁנָה כָּל הַחֹדֶשׁ, וְאָז הִיא נִלְכֶּדֶת; אַף אַתֶּם, חֹדֶשׁ אֶחָד (הוּא אָב) הוּכַן לָכֶם כְּבָר מִימוֹת הַמְרַגְּלִים, שֶׁקָּבְעוּ אֲבוֹתֵיכֶם בְּכִיַּת חִנָּם, בּוֹ תִּלָּכְדוּ (סוטה לה.). תַּאֲנָתָהּ. שׁוֹ״ן דְּגְרוֹנְמִינְ״ט בְּלַעַ״ז. וְכֵן תִּרְגֵּם יוֹנָתָן: ״כִּירוּדָא״. דָּבָר אַחֵר: לְשׁוֹן יְלָלָה, כְּמוֹ ״תַּאֲנִיָּה וַאֲנִיָּה״ (יחזקאל כט:ב). לָשׁוֹן אַחֵר: שַׁאקוֹנְטְרִיאָ״ה בְּלַעַ״ז, כְּמוֹ ״תַּאֲנַת שִׁילֹה״ (יהושע טז:ו):\",5,0],[2,121,2,25,\"מִנְעִי רַגְלֵךְ מִיָּחֵף. זוֹ הִיא מִדָּתֵךְ, כְּפֶרֶא הָאוֹהֶבֶת לָנוּעַ. נְבִיאַי אוֹמְרִים לִיךְ: מִנְעִי עַצְמֵךְ מֵעֲבוֹדָה זָרָה שֶׁלֹּא תֵּלְכִי יָחֵף בַּגּוֹלָה, וּמִנְעִי גְּרוֹנֵךְ מִלָּמוּת בַּצָּמָא; וַתֹּאמְרִי עַל דִּבְרֵי הַנְּבִיאִים נוֹאָשׁ. אֵין מִיחוּשׁ, נוֹאַשְׁתִּי בְּדִבְרֵיכֶם. נוֹאָשׁ נוֹקְלִיי״ר בְּלַעַ״ז:\",1,0],[2,121,2,26,\"כִּי יִמָּצֵא. בִּתְחִלָּה כְּשֶׁהוּא נִמְצָא גַּנָּב, וְהוּא הָיָה מֻחְזָק נֶאֱמָן; כָּךְ תִּרְגֵּם יוֹנָתָן:\",1,0],[2,121,2,27,\"וּבְעֵת רָעָתָם יֹאמְרוּ. אֵלַי קוּמָה וְהוֹשִׁיעֵנוּ. וְכֵן תַּרְגּוּם יוֹנָתָן: ״וּבְעִידָּן דְּבִישְׁתָּא אַתְיָא עֲלֵיהוֹן כַּפְרִין בְּטָעוּתְהוֹן וּמוֹדָן קֳדָמַי וְאָמְרִין רַחֵם עֲלָנָא וּפְרוּקְנָא״:\",1,0],[2,121,2,28,\"מִסְפַּר עָרֶיךָ הָיוּ אֱלֹהֶיךָ. בְּכָל עִיר וָעִיר אֱלוֹהַּ אַחֵר:\",1,0],[2,121,2,29,\"לָמָּה תָרִיבוּ. אֵיךְ תָּבֹאוּ לְהִתְוַכֵּחַ בְּרִיב וְלוֹמַר: לֹא חָטָאנוּ?!\",1,0],[2,121,2,29,\"כֻּלְּכֶם פְּשַׁעְתֶּם בִּי. אַף הַצַּדִּיקִים בְּמַשְׁמָע; הַיְינוּ דְּאָמְרֵי אִינְשֵׁי: בַּהֲדֵי הוּצָא, לָקִיא כַּרְבָּא (בבא קמא צב.):\",2,0],[2,121,2,30,\"לַשָּׁוְא הִכֵּיתִי. עַל חִנָּם, כִּי לֹא הוֹעִיל שֶׁיִּקְחוּ מוּסָר:\",1,0],[2,121,2,30,\"אָכְלָה חַרְבְּכֶם. אֶת נְבִיאֵיכֶם, הֲרַגְתֶּם אֶת זְכַרְיָה (דברי הימים ב כד:כא) וִישַׁעְיָה (יבמות מט:):\",2,0],[2,121,2,31,\"רְאוּ דְבַר ה׳. הוֹצִיא לָהֶם צִנְצֶנֶת הַמָּן, אָמַר לָהֶם: רְאוּ כָּאן מַה דְּבַר ה׳ מוֹעִיל (מכילתא בשלח ויסע ה)! הֲמִדְבָּר הָיִיתִי לְיִשְׂרָאֵל. לְשׁוֹן תֵּימָה הוּא, לְכָךְ נְקוּדה מ״ם רָפִי וְה״א בַּחֲטַף פַּתָּח: כְּלוּם נִדְמֶה לַאֲבוֹתֵיכֶם שֶׁהוּא מִדְבָּר כְּשֶׁהָלְכוּ בּוֹ, שֶׁהוֹרַדְתִּי לָהֶם לֶחֶם זֶה דְּבַר יוֹם בְּיוֹמוֹ (שמות טז:ד)?\",1,0],[2,121,2,31,\"מַאְפֵּלְיָה. לְשׁוֹן חֹשֶׁךְ:\",2,0],[2,121,2,31,\"מַדּוּעַ אָמְרוּ עַמִּי רַדְנוּ. נִבְדַּלְנוּ מִמְּךָ, כְּמוֹ הָרוֹדֶה פַּת מִן הַתַּנּוּר (תרומות י,ג). כָּךְ מִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, במדבר ב). וּמְנַחֵם פֵּרֵשׁ רַדְנוּ לְשׁוֹן יְרִידָה, וְעוֹד פָּנִים אֲחֵרִים:\",3,0],[2,121,2,33,\"תֵּיטִיבִי. תְּקַשְּׁטִי עַצְמֵךְ לִקְרַאת נוֹאֲפַיִךְ, כְּמוֹ ״וַתֵּיטֶב רֹאשָׁהּ״ דְּאִיזֶבֶל, בְּפָרָשַׁת יֵהוּא (מלכים ב ט:ל):\",1,0],[2,121,2,33,\"גַּם אֶת הָרָעוֹת לִמַּדְתְּ. חָזַרְתְּ עַל כָּל רוֹעַ דֶּרֶךְ, לִלְמוֹד אֶת הַמְקֻלְקֶלֶת שֶׁבְּכֻלָּם:\",2,0],[2,121,2,33,\"גַּם. לְשׁוֹן אֲפִילוּ. לָכֵן. לְשׁוֹן שְׁבוּעַת אֱמֶת, אַךְ אֶת הַדֶּרֶךְ הָרָעָה שֶׁבְּכָל הַדְּרָכִים לִמַּדְתְּ לְעַצְמֵךְ:\",3,0],[2,121,2,33,\"לִמַּדְתְּ. הִנְהַגְתְּ:\",4,0],[2,121,2,34,\"בַּמַּחְתֶּרֶת מְצָאתִים. לֹא מָצָאתָ אוֹתָם בַּמַּחְתֶּרֶת כְּשֶׁהָרַגְתָּ אוֹתָם:\",1,0],[2,121,2,34,\"מְצָאתִים. כֹּה יֹאמַר לִנְקֵבָה לְשׁוֹן פָּעַלְתְּ, וְהַרְבֵּה יֵשׁ בְּסֵפֶר (יחזקאל טז:נח) אֶת נְשָׂאתִים:\",2,0],[2,121,2,34,\"כִּי עַל כָּל אֵלֶּה. שֶׁהָיוּ מוֹכִיחִים אוֹתְךָ בַּדְּבָרִים הָאֵלֶּה:\",3,0],[2,121,2,35,\"וַתֹּאמְרִי. בְּלִבֵּךְ׃\",1,0],[2,121,2,35,\"כִּי נִקֵּיתִי. אֲשֶׁר זַכָּאָה אֲנִי נַפְשִׁי:\",2,0],[2,121,2,35,\"נִשְׁפָּט אוֹתָךְ. בָּא עִמָּךְ בְּמִשְׁפָּט:\",3,0],[2,121,2,36,\"תֵּזְלִי. לְשׁוֹן זִלְזוּל:\",1,0],[2,121,2,36,\"לְשַׁנּוֹת אֶת דַּרְכֵּךְ. לַעֲזֹב אוֹתִי וְלִסְמֹךְ עַל מִצְרַיִם לְעֶזְרָה, בִּימֵי יְהוֹיָקִים (מלכים ב כד:ז) וְצִדְקִיָּהוּ (ירמיה לז):\",2,0],[2,121,2,36,\"לְשַׁנּוֹת. לְשׁוֹן שִׁנּוּי:\",3,0],[2,121,2,36,\"כַּאֲשֶׁר בֹּשְׁתְּ מֵאַשּׁוּר. שֶׁסָּמַךְ אָחָז עָלָיו, ״וַיָּצַר לוֹ וְלֹא חִזְּקוֹ״ כְּמָה שֶׁנֶּאֱמַר בְּדִבְרֵי הַיָּמִים (דברי הימים ב כח:כ):\",4,0],[2,121,3,1,\"לֵאמֹר הֵן יְשַׁלַּח וְגוֹ׳. יֵשׁ לִי לוֹמַר, שֶׁאֵין עוֹד אַתְּ רְאוּיָה לִי, כִּי כֵן דֶּרֶךְ הַמְּשַׁלֵּחַ אֶת אִשְׁתּוֹ וְהָלְכָה וְגוֹ׳:\",1,0],[2,121,3,1,\"וְאַתְּ זָנִית רֵעִים רַבִּים. עִם אוֹהֲבִים רַבִּים; וְאַף עַל פִּי כֵן, שׁוּבִי אֵלַי:\",2,0],[2,121,3,1,\"וְשׁוּב אֵלַי. כְּמוֹ ״עֲשׂוֹת״, וְלָשׁוּב אֵלַי אֲנִי עוֹסֵק בָּךְ:\",3,0],[2,121,3,2,\"שְׁפָיִים. יִבְלֵי מַיִם:\",1,0],[2,121,3,2,\"לֹא שֻׁגַּלְתְּ. לְשׁוֹן פִּילֶגֶשׁ:\",2,0],[2,121,3,2,\"יָשַׁבְתְּ לָהֶם. לִהְיוֹת נְכוֹנָה לִקְרָאתָם:\",3,0],[2,121,3,2,\"כַּעֲרָבִי. יוֹשֵׁב אֹהָלִים, שֶׁהוּא תָּמִיד מָצוּי בַּחוּץ, בַּמִּדְבָּרוֹת; וְעַל שֵׁם כָּךְ הוּא קָרוּי עֲרָבִי, שֶׁשּׁוֹכֵן בָּעֲרָבָה:\",4,0],[2,121,3,3,\"וּמַלְקוֹשׁ. כְּמָטָר הַיּוֹרֵד בְּנִיסָן (יואל ב:כג) עַל הַמְּלִילוֹת וְעַל הַקַּשִּׁין. וּמַלְקוֹשׁ טְרַדִיוֹ״א בְּלַעַ״ז:\",1,0],[2,121,3,4,\"הֲלוֹא מֵעַתָּה. הַלְוַאי שַׁבְתְּ מֵרָעָתֵךְ וְקָרָאת לִי אָבִי, וְאִם תַּעֲשִׂי כָּךְ, הֲיִנְטֹר לָךְ אֲדוֹנַיִךְ לְעוֹלָם אֵת אֲשֶׁר חָטָאת לוֹ, אִם יִשְׁמֹר לָנֶצַח? לֹא יִשְׁמֹר!\",1,0],[2,121,3,5,\"הִנֵּה דִבַּרְתְּ. בְּפִיךְ: ״לֹא נָבוֹא עוֹד אֵלֶיךָ״ (ירמיה ב:לא), וְאוֹתָהּ הָרָעָה תַּעֲשִׂי וְלֹא תִתְּנִי לֵב לָשׁוּב:\",1,0],[2,121,3,5,\"וַתּוּכָל. וְנִצַּחְתְּ לִמְרוֹד:\",2,0],[2,121,3,6,\"מְשׁוּבָה. נִצַּחַת (ירמיה ח:ה) וּמוּכַחַת בִּימֵי יֹאשִׁיָּהוּ הַמֶּלֶךְ כְּשֶׁצִּוַּנִי לְהַחֲזִיר עֲשֶׂרֶת הַשְּׁבָטִים (מגלה יד:). הֲרָאִיתָ אֲשֶׁר עָשְׂתָה מְשֻׁבָה יִשְׂרָאֵל ״הַשּׁוֹבֵבָה״ (ירמיה לא:כא), אַנְבּוֹזִייָ״ה בְּלַעַ״ז:\",1,0],[2,121,3,6,\"יִשְׂרָאֵל. עֲשֶׂרֶת הַשְּׁבָטִים:\",2,0],[2,121,3,6,\"הוֹלְכָה הִיא. בְּעוֹדָהּ עַל אַדְמָתָהּ, קוֹדֶם שֶׁגָּלְתָה בִּימֵי חִזְקִיָּהוּ עִם הוֹשֵׁעַ בֶּן אֵלָה (מלכים ב יז):\",3,0],[2,121,3,6,\"הוֹלְכָה. הָיְתָה הוֹלֶכֶת עַל כָּל הַר גָּבֹהַּ:\",4,0],[2,121,3,6,\"וַתִּזְנִי שָׁם. לַעֲבוֹדָה זָרָה. וַתִּזְנִי כְּמוֹ וַתִּזֶן: יוֹ״ד יְתֵרָה:\",5,0],[2,121,3,7,\"וָאֹמַר. עַל יְדֵי נְבִיאַי עָמוֹס וְהוֹשֵׁעַ בֶּן בְּאֵרִי וּשְׁאָר נְבִיאִים: אֵלַי תָּשׁוּב:\",1,0],[2,121,3,7,\"וַתֵּרֶא בָּגוֹדָה אֲחוֹתָהּ יְהוּדָה. כָּל זֶה. בֹּגֵדָה קָשָׁה מִמְּשׁוּבָה: יִשְׂרָאֵל, שֶׁהֵם רִאשׁוֹנִים לְקִלְקוּל וְלֹא רָאוּ פֻּרְעָנוּת לִלְמֹד מִמֶּנּוּ וְלָשׁוּב, קְרוּיִין מְשׁוּבָה; יְהוּדָה, שֶׁרָאוּ שֶׁגָּלוּ אֵלּוּ וְלֹא לָקְחוּ מוּסָר, קְרוּיִין בֹּגֵדָה:\",2,0],[2,121,3,8,\"וָאֵרֶא כִּי עַל כָּל אוֹדוֹת וגו׳. נְקֻדּוֹת טַעֲמֵי מִקְרָא זֶה מְלַמְּדִין עַל פֵּרוּשׁוֹ: יִשְׂרָאֵל נָקוּד זָקֵף, מֻבְדָּל מִשִּׁלַּחְתִּיהָ; שִׁלַּחְתִּיהָ נָקוּד זָקֵף גָּדוֹל לְעַצְמוֹ. וְזֶה פֵּרוּשׁוֹ: וָאֵרֶא נִסְתַּכַּלְתִּי בָּהּ לִיפָּרַע מִמֶּנָּה, וְלָמָּה? כִּי עַל כָּל אוֹדוֹת אֲשֶׁר נִאֲפָה מְשׁוּבָה יִשְׂרָאֵל, וּמָה הָיְתָה נִקְמָתִי? שִׁלַּחְתִּיהָ מֵעַל פָּנַי. וְלֹא יָרְאָה בֹּגֵדָה יְהוּדָה שֶׁרָאֲתָה בְּפוּרְעָנוּת שֶׁל שׁוֹמְרוֹן, לָתֵת לִבָּהּ לָשׁוּב:\",1,0],[2,121,3,9,\"וַתִּנְאַף אֶת הָאֶבֶן. ״וְטָעַת עִם פָּלְחֵי אַבְנַיָּא וְאָעֵיָא״, וְיוֹנָתָן תִּרְגֵּם מִקֹּל זְנוּתָהּ לְשׁוֹן קַלּוּת: ״מִדְּקַלִּילָא בְּעֵינָהָא טָעֲוָותָהָא״:\",1,0],[2,121,3,10,\"וְגַם בְּכָל זֹאת. שֶׁרָאוּ בְּקִלְקוּלַת פֻּרְעָנוּת חֲבֵרֵיהֶם:\",1,0],[2,121,3,10,\"כִּי אִם בְּשֶׁקֶר. דּוֹרוֹ שֶׁל יֹאשִׁיָּה מַרְאִין עַצְמָם שֶׁהֵם צַדִּיקִים, וְהֵם רְשָׁעִים הָיוּ. צָרִים צוּרוֹת שֶׁל עֲבוֹדָה זָרָה עַל דַּלְתוֹתֵיהֶם מִבִּפְנִים, חֶצְיָהּ עַל זוֹ וְחֶצְיָהּ עַל זוֹ, וּכְשֶׁהָיוּ מְבַעֲרֵי עֲבוֹדָה זָרָה בּוֹדְקִים, הָיָה הַדֶּלֶת פָּתוּחַ וְלֹא הָיוּ מַכִּירִין בָּהּ:\",2,0],[2,121,3,11,\"צִדְּקָה נַפְשָׁהּ מְשֻׁבָה יִשְׂרָאֵל. נִקְּתָה וּפָטְרָה עַצְמָהּ מִן הַדִּין, שֶׁלֹּא הָיָה לָהּ מִמִּי לִלְמוֹד:\",1,0],[2,121,3,12,\"הָלוֹךְ וְקָרָאתָ וְגוֹ׳. הָלוֹךְ כְּתַרְגּוּמוֹ: ״אֲזִיל״, לְשׁוֹן צִוּוּי; כָּאן צִוָּהוּ לֵילֵךְ וּלְהַחֲזִיר עֲשֶׂרֶת הַשְּׁבָטִים בִּימֵי יֹאשִׁיָּהוּ (מגלה יד:), כְּמוֹ שֶׁאָמַר לְמַעְלָה (פסוק ו), שֶׁבִּימֵי יֹאשִׁיָּהוּ נֶאֶמְרָה לוֹ נְבוּאָה זוֹ; וְחָזְרוּ מִקְצָת מֵהֶן בִּשְׁמוֹנֶה עֶשְׂרֵה לְיֹאשִׁיָּהוּ (דברי הימים ב לה,יז-יט):\",1,0],[2,121,3,12,\"צָפוֹנָה. אֶל הַמְּקוֹמוֹת שֶׁגָּלוּ שָׁם לְאַשּׁוּר:\",2,0],[2,121,3,12,\"פָּנַי. ״רוּגְזִי״, כֵּן תַּרְגֵּם יוֹנָתָן:\",3,0],[2,121,3,13,\"פָּשָׁעַתְּ. מָרַדְתְּ:\",1,0],[2,121,3,13,\"וַתְּפַזְּרִי אֶת דְּרָכַיִךְ. לְשׁוֹן זְנוּת; פִּסּוּק רַגְלַיִם לְמִשְׁכְּבֵי אִשָּׁה:\",2,0],[2,121,3,14,\"שׁוֹבָבִים. אַנְוִוישִׁי״ר בְּלַעַ״ז, שֶׁשּׁוֹבַבְתֶּם דַּרְכְּכֶם מֵרוֹב כֹּל (דברים כח:מז), שֶׁהֱיִיתֶם בְּשַׁלְוָה וְעֹנֶג, כְּמוֹ שֶׁהוּא אוֹמֵר ״הַפּוֹרְטִים עַל פִּי הַנָּבֶל״ (עמוס ו:ה), ״הַשֹּׁתִים בְּמִזְרְקֵי יַיִן״ (עמוס ו:ו):\",1,0],[2,121,3,14,\"כִּי אָנֹכִי בָּעַלְתִּי בָכֶם. וְנִקְרֵאתֶם בִּשְׁמִי, שֶׁאֲנִי אָדוֹן לָכֶם, וְאֵין כְּבוֹדִי לְהַנִּיחַ אֶתְכֶם בְּיַד אוֹיְבִי:\",2,0],[2,121,3,16,\"לֹא יֹאמְרוּ עוֹד אֲרוֹן. כִּי כָל כְּנִיסַתְכֶם תְּהֵא קְדוֹשָׁה, וְאֶשְׁכּוֹן בָּהּ כְּאִלּוּ הוּא אֲרוֹן:\",1,0],[2,121,3,16,\"יִפְקֹדוּ. כְּמוֹ יִזְכְּרוּ:\",2,0],[2,121,3,16,\"וְלֹא יֵעָשֶׂה עוֹד. מַה שֶּׁנַּעֲשָׂה בּוֹ כְּבָר בְּשִׁילֹה, שֶׁהֱבִיאוּהוּ בַּמִּלְחָמָה עִם פְּלִשְׁתִּים, בִּימֵי עֵלִי (שמואל א ד):\",3,0],[2,121,3,17,\"וְנִקְווּ. וְנִקְבְּצוּ, לְשׁוֹן ״מִקְוֵה מַיִם״ (ויקרא יא:לו):\",1,0],[2,121,3,17,\"שְׁרִירוּת. לְשׁוֹן רְאִיָּה, כְּמוֹ ״אֲשׁוּרֶנּוּ״ (במדבר כד, יז):\",2,0],[2,121,3,18,\"יֵלְכוּ בֵית יְהוּדָה עַל בֵּית יִשְׂרָאֵל. עִמָּם יִתְחַבְּרוּ וְיִתְוַסְּפוּ עֲלֵיהֶם לִהְיוֹת מַמְלָכָה אַחַת:\",1,0],[2,121,3,19,\"וְאָנֹכִי אָמַרְתִּי. בְּלִבִּי, וְלָכֵן הִנְחַלְתִּים לַאֲבוֹתֵיכֶם:\",1,0],[2,121,3,19,\"אֵיךְ אֲשִׁיתֵךְ בַּבָּנִים. אֶת, עֲדָתִי וְאֻמָּתִי, בְּתוֹךְ שְׁאָר בָּנִים, לְפִיכָךְ בֵּרַרְתִּי מָנָה יָפָה וְאֶתֶּן לָךְ אֶרֶץ חֶמְדָּה:\",2,0],[2,121,3,19,\"צְבִי צִבְאוֹת גּוֹיִם. צִבְיוֹן כָּל צִבְאוֹת גּוֹיִם (תנחומא, משפטים יז):\",3,0],[2,121,3,20,\"אָכֵן. אֲבָל אַתֶּם לֹא עֲשִׂיתֶם מַחֲשַׁבְתִּי, כִּי אִם כְּמוֹ אִשָּׁה שֶׁבּוֹגְדָה מֵרֵעָהּ עַל שֶׁאֵינוֹ יָכוֹל לְהַסְפִּיק מְזוֹנוֹתֶיהָ, כֵּן בְּגַדְתֶּם בִּי – הַמַּסְפִּיק לָכֶם כָּל טוֹב; כָּךְ מִדְרַשׁ אַגָּדָה (תנחומא, משפטים יז):\",1,0],[2,121,3,21,\"עַל שְׁפָיִים נִשְׁמָע. קָרוֹב הוּא לְהִשָּׁמַע:\",1,0],[2,121,3,22,\"הִנְנוּ אָתָנוּ לָךְ. הַנָּבִיא מְלַמְּדָם לְהִתְוַדּוֹת וְלוֹמַר כֵּן: הִנְנוּ אָתָנוּ לָךְ, אָכֵן לַשֶּׁקֶר וְגוֹ, וְהַבֹּשֶׁת אָכְלָה וְגוֹ׳ נִשְׁכְּבָה בְבָשְׁתֵּנוּ. כָּל זֶה לְשׁוֹן תְּפִלָּה שֶׁהַנָּבִיא מְלַמְּדָם לוֹמַר:\",1,0],[2,121,3,22,\"אָתָנוּ. בָּאנוּ:\",2,0],[2,121,3,23,\"אָכֵן לַשֶּׁקֶר. שָׁמַרְנוּ מִגְּבָעוֹת וְהָמוֹן הָרִים שֶׁעָבַדְנוּ עֲבוֹדָה זָרָה שָׁם (על פי שמואל א כה:כא):\",1,0],[2,121,3,23,\"אָכֵן. בֶּאֱמֶת:\",2,0],[2,121,3,24,\"וְהַבֹּשֶׁת. עֲבוֹדָה זָרָה שֶׁעָסַקְנוּ בָּהּ; כְּמָה דְאַתְּ אָמֵר ״וַיִּנָּזְרוּ לַבֹּשֶׁת״ (הושע ט:י):\",1,0],[2,121,3,24,\"אָכְלָה אֶת יְגִיעַ אֲבוֹתֵינוּ. בַּעֲוֹן עֲבוֹדָתָהּ הָיָה יְגִיעֵנוּ לָבַז:\",2,0],[2,121,4,1,\"אִם תָּשׁוּב יִשְׂרָאֵל. בִּתְשׁוּבָה זוֹ אֵלַי תָּשׁוּב לִכְבוֹדְךָ וּגְדֻלָּתְךָ הָרִאשׁוֹנָה:\",1,0],[2,121,4,1,\"וְאִם תָּסִיר שִׁקּוּצֶיךָ מִפָּנַי. אָז לֹא תָנוּד – לָצֵאת בַּגּוֹלָה:\",2,0],[2,121,4,2,\"וְנִשְׁבַּעְתָּ חַי ה׳ בֶּאֱמֶת. כְּשֶׁתִּשָּׁבַע בִּשְׁמִי תִּשָּׁבַע בֶּאֱמֶת, וְלֹא כַּאֲשֶׁר עַתָּה, שֶׁכָּתוּב בָּכֶם ״אִם חַי ה׳ יֹאמְרוּ אָכֵן לְשֶׁקֶר יִשָּׁבֵעוּ״ (ירמיה ה:ב):\",1,0],[2,121,4,2,\"וְהִתְבָּרְכוּ בוֹ גוֹיִם. אִם תַּעֲשׂוּ כֵּן, אָז יִתְבָּרְכוּ בְּיִשְׂרָאֵל הַגּוֹיִם; כָּל גּוֹי יֹאמַר לִבְנוֹ: תְּהֵא כִּפְלוֹנִי יִשְׂרָאֵל:\",2,0],[2,121,4,2,\"יִתְהַלָּלוּ. יַגִּידוּ שִׁבְחֲכֶם. דָּבָר אַחֵר: יִתְהַלָּלוּ – מִי שֶׁיּוּכַל לְהִדָּבֵק בְּיִשְׂרָאֵל, יִתְפָּאֵר בַּדָּבָר; פורוונטי״ר בְּלַעַ״ז:\",3,0],[2,121,4,3,\"כִּי כֹה אָמַר ה׳ וגו׳ נִירוּ לָכֶם נִיר. – הֱווּ לְמֵדִין מֵעוֹבְדֵי אֲדָמָה, שֶׁנָּרִים אוֹתָהּ בִּימֵי הַקַּיִץ לְהָמִית שָׁרְשֵׁי הָעֲשָׂבִים, שֶׁלֹּא תְּהֵא מַעֲלָה קוֹצִים בְּעֵת הַזֶּרַע בַּחֹרֶף; אַף אַתֶּם הֵטִיבוּ מַעֲשֵׂיכֶם בְּטֶרֶם תָּבֹא עֲלֵיכֶם הָרָעָה, שֶׁלֹּא תְּהֵא תְּפִלַּתְכֶם נִמְאֶסֶת כְּשֶׁתִּצְעֲקוּ:\",1,0],[2,121,4,3,\"וְאַל תִּזְרְעוּ אֶל קוֹצִים. וְאַל תְּהִי צַעֲקַתְכֶם לְפָנַי מִתּוֹךְ הָרֶשַׁע כִּי אִם מִתּוֹךְ תְּשׁוּבָה, שֶׁלֹּא תִהְיוּ דּוֹמִים לְזוֹרֵעַ בְּלֹא נִיר, וְהִיא נֶהְפֶּכֶת לְקוֹצִים; קַרְדוֹנְ״שׁ בְּלַעַ״ז:\",2,0],[2,121,4,4,\"הִמּוֹלוּ לַה׳. בְּטֶרֶם תֵּצֵא חֲמָתִי כָאֵשׁ; זֶהוּ כְּנִיר לִפְנֵי הַזֶּרַע (ירמיה ג:ג):\",1,0],[2,121,4,5,\"וְאִמְרוּ תִּקְעוּ שׁוֹפָר. הַזְהִירוּ אֶת יוֹשְׁבֵי הָאָרֶץ, שֶׁיִּתְקְעוּ בְּשׁוֹפָר לִבְרוֹחַ:\",1,0],[2,121,4,5,\"מַלְאוּ. לְשׁוֹן אֲסִיפָה, וְהַרְבֵּה יֵשׁ בַּמִּקְרָא: ״אֲשֶׁר יִקָּרֵא עָלָיו מְלֹא רֹעִים״ (ישעיהו לא:ד); ״קָרְאוּ אַחֲרֶיךָ מָלֵא״ (ירמיהו יב:ו); ״יַחַד עָלַי יִתְמַלָּאוּן״ (איוב טז:י):\",2,0],[2,121,4,6,\"שְׂאוּ נֵס. לִבְרוֹחַ לְצִיּוֹן:\",1,0],[2,121,4,6,\"הָעִיזוּ. הֵאָסְפוּ, כְּמוֹ ״שְׁלַח הָעֵז״ (שמות ט:יט):\",2,0],[2,121,4,7,\"עָלָה אַרְיֵה. נְבוּכַדְנֶצַּר (מגלה יא.):\",1,0],[2,121,4,7,\"מִסֻּבְּכוֹ. דֶּרֶךְ אַרְיֵה לֵישֵׁב בְּמַאֲרַב סִבְכֵי הַיַּעַר (ישעיה י:לד); אשפיישי״ש בְּלַעַז:\",2,0],[2,121,4,7,\"תִּצֶּינָה. לְשׁוֹן ״צִיָּה״ (ירמיה ב:ו):\",3,0],[2,121,4,8,\"עַל זֹאת. מַה הוּא זֹאת? כִּי לֹא שָׁב וְגוֹ׳. וְאַף עַל פִּי שֶׁדִּבֵּר לְמַעְלָה בִּנְבוּכַדְנֶצַּר עַל הַחֻרְבָּן, כָּאן חָזַר לְדַבֵּר בְּמִיתַת יֹאשִׁיָּהוּ:\",1,0],[2,121,4,8,\"כִּי לֹא שָׁב חֲרוֹן אַף וְגוֹ׳. וְאַף עַל פִּי שֶׁשָּׁב יֹאשִׁיָּהוּ בְּכָל לֵב, נֶאֱמַר בּוֹ (מלכים ב כג:כו) ״לֹא שָׁב ה׳ מֵחֲרוֹן אַפּוֹ עַל כָּל הַכְּעָסִים אֲשֶׁר הִכְעִיסוֹ מְנַשֶּׁה״:\",2,0],[2,121,4,9,\"וְהָיָה בַּיּוֹם הַהוּא. בְּיוֹמוֹ שֶׁל יֹאשִׁיָּהוּ יִתְמְהוּ: לָמָּה עָלְתָה בּוֹ כָּל כָּךְ? וְהֵם אֵין יוֹדְעִין שֶׁאֵין דּוֹרוֹ חוֹזֵר יָפֶה; כְּשֶׁבָּא לְבַעֵר אֶת עֲבוֹדָה זָרָה מֶה הָיוּ לֵיצָנֵי הַדּוֹר עוֹשִׂין? חוֹקְקִין צוּרַת עֲבוֹדָה זָרָה עַל דַּלְתוֹתֵיהֶן, חֶצְיָהּ בְּדֶלֶת זֶה וְחֶצְיָהּ בְּדֶלֶת זֶה; כְּשֶׁהָיָה פּוֹתְחוֹ לֹא הָיְתָה נִכֶּרֶת, וּכְשֶׁהָלַךְ מִשָּׁם סוֹגְרָהּ וְהִיא מִתְחַבֶּרֶת:\",1,0],[2,121,4,10,\"הַשֵּׁא הִשֵּׁאתָ. אַטִינְטַא״ר בְּלַעַ״ז, לְשׁוֹן ״הַנָּחָשׁ הִשִּׁיאַנִי״ (בראשית ג:יג); שֶׁנְּבִיאֵי הַשֶּׁקֶר נִבָּאִים לָכֶם: שָׁלוֹם יִהְיֶה לָכֶם:\",1,0],[2,121,4,11,\"לָעָם הַזֶּה. עַל הָעָם הַזֶּה, כְּשֶׁיִּגְלוּ כֻּלָּם:\",1,0],[2,121,4,11,\"צַח שְׁפָיִים. מְכַבֵּד וּמְטַאטֵא אַף אֶת שְׂדוֹת יִבְלֵי הַמַּיִם, לְשִׁיתָם מִדְבָּר. לָשׁוֹן אַחֵר: צַח לְשׁוֹן ״צָמָא״, דִּמְתַרְגְּמִינָן: ״צְחוּתָא״:\",2,0],[2,121,4,11,\"דֶּרֶךְ בַּת עַמִּי. אוֹתוֹ רוּחַ בָּא. וְגַם לוֹא לִזְרוֹת מוֹץ מִגֹּרֶן, אהבוניי״ר בְּלַעַז, כְּמוֹ ״וְאֶזְרֵם בְּמִזְרֶה״ (ירמיה טו:ז):\",3,0],[2,121,4,11,\"וְלוֹא לְהָבַר. וְלִנְקוֹת תְּבוּאָה הוּא בָּא, כְּלוֹמַר: לֹא לְטוֹבָה כִּי אִם לְרָעָה, לְהַגְלוֹת אֶת אֲנָשִׁים (וְנָשִׁים) טַף וּבְהֵמָה:\",4,0],[2,121,4,12,\"רוּחַ מָלֵא. מֵאֵלֶּה הַפֻּרְעָנוּת יָבוֹא לִי רוּחַ מָלֵא, רוּחַ שָׁלֵם, שֶׁלֹּא אֶחְזוֹר בּוֹ וְלֹא אֶנָּחֵם. רוּחַ טַלְנ״ט בְּלַעַ״ז:\",1,0],[2,121,4,12,\"מִשְׁפָּטִים. לְשׁוֹן וִכּוּחַ:\",2,0],[2,121,4,13,\"וְכַסּוּפָה. אִיקוֹמָאטְרוֹבִילוֹ בְּלַעַ״ז:\",1,0],[2,121,4,14,\"אוֹנֵךְ. חֲמָסֵךְ:\",1,0],[2,121,4,15,\"כִּי קוֹל מַגִּיד מִדָּן. ״אָרֵי קַל נְבִיָּא מִתְנְבָן עֲלֵיהוֹן דְּגָלוֹן עַל דְּפָלְחוּ לָעֲגָלָה דִּבְדָן וּמְבַשְּׂרָן בְּשׁוֹרָן בַּיְּשָׁן יָתוּן עֲלֵיהוֹן עַל דְּאִשְׁתַּעֲבְדוּ לְצַלְמָא דָּקִים מִיכָה בְּטוּרָא דְּבֵית אֶפְרַיִם״. וְאַף עַל פִּי שֶׁכְּבָר גָּלוּ הָעֲגָלִים מִיְּמוֹת סַנְחֵרִב, עֲדַיִן עֲווֹנָם קַיָּם. גְּדוֹלָה הִיא עֲבֵרָה שֶׁשּׁוֹבֶרֶת לְפָנֶיהָ וּלְאַחֲרֶיהָ: לְפָנֶיהָ מִיְּמוֹת אַבְרָהָם שֶׁנֶּאֱמַר ״וְיִרְדֹּף עַד דָּן״ (בראשית יד:יד), כֵּיוָן שֶׁהִגִּיעַ לְדָן תָּשַׁשׁ כֹּחוֹ שֶׁעֲתִידִין בָּנָיו לַעֲבֹד שָׁם עֲבוֹדָה זָרָה; וּלְאַחֲרֶיהָ בְּחֻרְבַּן הַבַּיִת שֶׁנֶּאֱמַר: כִּי קוֹל מַגִּיד מִדָּן:\",1,0],[2,121,4,15,\"וּמַשְׁמִיעַ אָוֶן. אָוֶן שֶׁבֶר:\",2,0],[2,121,4,16,\"נוֹצְרִים. נוֹתְנֵי מָצוֹר עֲלֵיהֶם:\",1,0],[2,121,4,17,\"שָׂדַי. כְּמוֹ שָׂדֶה:\",1,0],[2,121,4,17,\"אוֹתִי מָרָתָה. הִקְנִיטָה; כְּמוֹ ״מַמְרִים הֱיִיתֶם״ (דברים ט:כד) – מַרְגְּזִין:\",2,0],[2,121,4,18,\"עָשׂוֹ אֵלֶּה. לַעֲשׂוֹת אֵלֶּה לָךְ:\",1,0],[2,121,4,19,\"אוֹחִילָה. לְשׁוֹן חִיל וְרֶתֶת:\",1,0],[2,121,4,19,\"קִירוֹת. אַנְטִינָ״שׁ בְּלַעַ״ז:\",2,0],[2,121,4,19,\"שָׁמַעַתְּ נַפְשִׁי. מֵאֲחוֹרֵי הַפַּרְגּוֹד (חגיגה טו.) בָּאַתְנִי בְּשׂוֹרַת קוֹל מִתְּרוּעַת מִלְחָמָה:\",3,0],[2,121,4,20,\"שֶׁבֶר עַל שֶׁבֶר. חָרְבוֹת יְרוּשָׁלַיִם עַל גָּלוּת יְכָנְיָה:\",1,0],[2,121,4,20,\"רֶגַע יְרִיעוֹתָי. רֶגַע שֻׁדְּדוּ יְרִיעוֹתָי:\",2,0],[2,121,4,21,\"עַד מָתַי אֶרְאֶה. הָאֲסִיפוֹת הָאֵלֶּה הַנּוֹשְׂאִים נֵס, לְהִקָּבֵץ לָבֹא לְהִלָּחֵם:\",1,0],[2,121,4,24,\"הִתְקַלְקָלוּ. נִתְּקוּ וְנִזְרְקוּ מִמְּקוֹמָן; וְעִם ״קַלְקַל בַּחִצִּים״ (יחזקאל כא:כו) חִבְּרוֹ מְנַחֵם:\",1,0],[2,121,4,26,\"וְהִנֵּה הַכַּרְמֶל. אֶרֶץ הַנְּטוּעַ כָּל טוֹב כַּכַּרְמֶל נִהְיָה מִדְבָּר. מִדְרַשׁ אַגָּדָה: רָאִיתִי הֶהָרִים אֵלּוּ הָאָבוֹת, וְכָל הַגְּבָעוֹת אֵלּוּ אִמָּהוֹת (ראש השנה יא.), כְּלוֹמַר זְכוּתָן תַּמָּה, אֵין הָאָדָם, זְכוּת מֹשֶׁה שֶׁנֶּאֱמַר בּוֹ עָנִיו מִכָּל הָאָדָם (במדבר יב,ג), וְהִנֵּה הַכַּרְמֶל אֵלִיָּהוּ:\",1,0],[2,121,4,27,\"וְכָלָה לֹא אֶעֱשֶׂה. בְּיוֹשְׁבֶיהָ, כִּי אוֹתִיר פְּלִיטִים שֶׁיֵּלְכוּ בַּגּוֹלָה:\",1,0],[2,121,4,28,\"תֶּאֱבַל. תֶּחֱרַב:\",1,0],[2,121,4,28,\"זַמּוֹתִי. לְשׁוֹן מַחֲשָׁבָה:\",2,0],[2,121,4,28,\"עַל כִּי דִבַּרְתִּי. הַפּוּרְעָנוּת הַזֶּה, וַאֲקַיְּמֶנָּה:\",3,0],[2,121,4,28,\"וְלֹא אָשׁוּב. וְלֹא אֶנָּחֵם, לַחְשֹׁב מַחְשָׁבוֹת טוֹבוֹת עֲלֵיהֶם:\",4,0],[2,121,4,29,\"וְרוֹמֵה. כְּמוֹ ״רָמָה בַיָּם״ (שמות טו:א):\",1,0],[2,121,4,29,\"בָּאוּ בֶעָבִים. בַּיְּעָרוֹת עָבִים, מְקוֹם סִיכּוּךְ קוֹצִים לְהִטָּמֵן:\",2,0],[2,121,4,29,\"וּבַכֵּפִים עָלוּ. ״סֶלַע״ (ירמיה כג:כט) מְתֻרְגָּם ״בְּכִיפַיָּא״:\",3,0],[2,121,4,30,\"כִּי תִלְבְּשִׁי שָׁנִי. לְהִתְנָאוֹת וְלִמְצֹא רַחֲמִים לִפְנֵי הַשּׁוֹדֵד:\",1,0],[2,121,4,30,\"תִּקְרְעִי בַפּוּךְ. לְשׁוֹן קְרִיעָה, שֶׁהַפּוּךְ נִרְאֶה כְּמַרְחִיב קֶרַע הָעַיִן; כָּךְ שָׁמַעְתִּי. וְגַם מְנַחֵם לֹא חָלַק, בְּמַחְבֶּרֶת קֶרַע:\",2,0],[2,121,4,30,\"פּוּךְ. לְשׁוֹן כָּחוֹל (שבת ח,ג):\",3,0],[2,121,4,30,\"עוֹגְבִים. הַמְּשַׂחֲקִים עִם הַנָּשִׁים בְּצִדֵּי מִינֵי נִיאוּף; כְּמוֹ ״וַתַּעְגְּבָה עַל פִּלַגְשֵׁיהֶם״ (יחזקאל כג:כ):\",4,0],[2,121,4,30,\"נַפְשֵׁךְ יְבַקֵּשׁוּ. מְבַקְּשִׁים לְהָרְגֵךְ:\",5,0],[2,121,4,31,\"כְּמַבְכִּירָה. כְּאִשָּׁה הַמְּבַכֶּרֶת תְּחִלַּת לֵידָתָהּ:\",1,0],[2,121,4,31,\"תִּתְיַפֵּחַ. תְּיַלֵּל וְתִצְעַק גְּנִיחוֹת; קונפליינ״ט בְּלַעַ״ז; כְּמוֹ ״וִיפֵחַ חָמָס״ (תהלים כז:יב) – לְשׁוֹן דִּבּוּר:\",2,0],[2,121,4,31,\"אוֹי נָא לִי. כָּךְ אוֹמֶרֶת:\",3,0],[2,121,5,3,\"ה׳ עֵינֶיךָ הֲלוֹא. הֵם בַּעֲלֵי אֱמוּנָה לְהֵיטִיב, וְלָמָּה בָּגְדוּ אֵלֶּה בָּךְ וְאֵין מְבַקְּשִׁין אֱמוּנָה?\",1,0],[2,121,5,3,\"הִכִּיתָה אוֹתָם. וְלֹא נַעֲשׂוּ חוֹלִים עַל הַמַּכָּה, לָשׂוּם עַל לִבָּם לָשׁוּב מֵרָעָתָם:\",2,0],[2,121,5,3,\"קַחַת. כְּמוֹ לָקַחַת:\",3,0],[2,121,5,4,\"וַאֲנִי אָמַרְתִּי. הַנָּבִיא אוֹמֵר כָּךְ. אַךְ דַּלִּים הֵם מֵחָכְמָה, אֵלּוּ שֶׁאֲנִי מְדַבֵּר עִמָּהֶם:\",1,0],[2,121,5,4,\"נוֹאֲלוּ. לְשׁוֹן ״אֱוִיל״ (ירמיה ד:כב), כְּתַרְגּוּמוֹ: ״אִיטְפַּשׁוּ״:\",2,0],[2,121,5,5,\"אֵלְכָה לִי אֶל הַגְּדוֹלִים. הֵם יִשְׁמְעוּ; אַךְ לֹא הוֹעַלְתִּי, וְגַם הֵמָּה יַחְדָּו שָׁבְרוּ עֹל שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מֵעֲלֵיהֶם:\",1,0],[2,121,5,6,\"אַרְיֵה. מַלְכוּת בָּבֶל:\",1,0],[2,121,5,6,\"זְאֵב. מַלְכוּת מָדַי:\",2,0],[2,121,5,6,\"נָמֵר. מַלְכוּת אַשּׁוּר:\",3,0],[2,121,5,6,\"יִטָּרֵף. בֶּאֱדוֹם (אסתר רבה, פתיחתא ה):\",4,0],[2,121,5,6,\"זְאֵב עֲרָבוֹת. לְשׁוֹן ״עֲרָבָה וְשׁוּחָה״ (ירמיה ב:ו): זְאֵב הַמִּדְבָּר:\",5,0],[2,121,5,6,\"שׁוֹקֵד. מְמַהֵר, וּמְנַחֵם חִבְּרוֹ עִם לְשׁוֹן שְׁמִירָה, כְּמוֹ ״לִשְׁקֹד עַל דַּלְתוֹתַי״ (משלי ח:לד). וְיוֹנָתָן תִּרְגֵּם לְשׁוֹן אֲרִיבָה:\",6,0],[2,121,5,7,\"אֵי לָזֹאת אֶסְלַח לָךְ. בִּתְמִיהָּ: שֶׁמָּא לָזֹאת אֶסְלַח לָךְ?! וּמְנַחֵם פֵּרֵשׁ אֵי כְּמוֹ אַיִן. אֲשֶׁר בָּנַיִךְ עֲזָבוּנִי וָאַשְׂבִּעַ אוֹתָם כָּל טוֹב:\",1,0],[2,121,5,7,\"יִתְגּוֹדָדוּ. יִתְקַבְּצוּ גְדוּדִים:\",2,0],[2,121,5,8,\"סוּסִים מְיֻזָּנִים מַשְׁכִּים הָיוּ. בְּכָל בֹּקֶר הָיוּ. מַשְׁכִּים – לְאוֹר בֹּקֶר בְּהַשְׁכָּמָה:\",1,0],[2,121,5,8,\"יִצְהָלוּ. לָשׁוֹן זֶה נוֹפֵל עַל הַסּוּסִים: ״מִקּוֹל מִצְהֲלוֹת אַבִּירָיו״ (ירמיה ח:טז). לְשׁוֹן צַהֲלָה – אֵישְׁיוּדְמִינְ״ט בְּלַעַ״ז:\",2,0],[2,121,5,10,\"בְשָׁרוֹתֶיהָ. לְשׁוֹן מִישׁוֹר, וּמְנַחֵם חִבְּרוֹ לְשׁוֹן חוֹמָה עִם ״אֲדַלֵּג שׁוּר״ (תהלים יח:ל), אַךְ לֹא יִתָּכְנוּ נְטִישׁוֹתֶיהָ צִי״שׁ בְּלַעַ״ז, שֶׁהֵם שָׁרְשֵׁי כֶּרֶם, לִהְיוֹת נֶחְשָׁבִים עִם הַחוֹמוֹת וְלֹא עִם הַמִּישׁוֹר. וַאֲנִי אוֹמֵר שָׁרוֹתֶיהָ לְשׁוֹן שׁוּרוֹת הַכֶּרֶם. וְיוֹנָתָן תִּרְגֵּם בְּשָׁרוֹתֶיהָ ״בְּקִירוֹהָא״, וּנְטִישׁוֹתֶיהָ ״בְּרָנִיתָהָא״:\",1,0],[2,121,5,12,\"וַיֹּאמְרוּ לֹא הוּא. ״לָא מִן קֳדָמוֹהִי אַתְיָא עֲלָנָא טָבְתָא״ (תרגום יונתן):\",1,0],[2,121,5,13,\"וְהַנְּבִיאִים יִהְיוּ לְרוּחַ. כְּתַרְגּוּמוֹ: ״וְנָבִיֵּי שִׁקְרָא יְהוֹן לְלָמָא״; כְּלוֹמַר: הַנְּבוּאָה שֶׁנִּיבָּאִים לָנוּ נְבִיאֵי שֶׁקֶר בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, דִּבְרֵיהֶם יֵהָפְכוּ לְהֶבֶל, וְהַדִּבֵּר שֶׁל קְדֻשָּׁה, שֶׁהֵם אוֹמְרִים לָנוּ בְּשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵינָן בָּהֶם:\",1,0],[2,121,5,13,\"כֹּה יֵעָשֶׂה לָהֶם. הַנָּבִיא אוֹמֵר לָאוֹמְרִים זֹאת, כֹּה יֵעָשֶׂה לָהֶם, כַּאֲשֶׁר אָמַר ה׳ לִי. וּמָה אָמַר ה׳ לִי? יַעַן דַּבֶּרְכֶם אֶת הַדָּבָר הַזֶּה וְגוֹ׳:\",2,0],[2,121,5,14,\"וַאֲכָלָתַם. וְתֹאכַל אוֹתָם:\",1,0],[2,121,5,15,\"אֵיתָן. תַּקִּיף (מכילתא בשלח ויהי ו):\",1,0],[2,121,5,15,\"גּוֹי מֵעוֹלָם הוּא. מִימֵי קֶדֶם הִתְחִיל לִמְרוֹד בִּי, בְּדוֹר הַפְּלַגָּה בְּאֶרֶץ שִׁנְעָר (בראשית יא:א-ט; פסחים צד.-צד:):\",2,0],[2,121,5,16,\"אַשְׁפָּתוֹ. מְקוֹם נַרְתֵּק הַחִצִּים:\",1,0],[2,121,5,17,\"יְרוֹשֵׁשׁ עָרֵי מִבְצָרֶיךָ וְגוֹ׳. הֲרֵי זֶה מִקְרָא מְסֹרָס: יְרוֹשֵׁשׁ בֶּחָרֶב אֶת עָרֵי מִבְצָרֶיךָ אֲשֶׁר אַתָּה בּוֹטֵחַ בָּהֵנָּה:\",1,0],[2,121,5,17,\"יְרוֹשֵׁשׁ. יְמַסְכֵּן:\",2,0],[2,121,5,17,\"בַּחָרֶב. עַל יְדֵי גְּיָסוֹת, וְכֵן הוּא אוֹמֵר ״וְחֶרֶב לֹא תַעֲבֹר בְּאַרְצְכֶם״ (ויקרא כו:ו):\",3,0],[2,121,5,22,\"הַאוֹתִי לֹא תִירָאוּ. הֲלֹא הַיָּם, שֶׁאֵינוֹ דּוֹאֵג מִפְּנֵי הַפּוּרְעָנוּת וְאֵינוֹ מְצַפֶּה לְקִבּוּל שָׂכָר, יָרֵא מִפָּנַי, וְאֵינוֹ עוֹבֵר הַגְּבוּל אֲשֶׁר שַׂמְתִּי סְבִיבָיו:\",1,0],[2,121,5,22,\"תָּחִילוּ. לְשׁוֹן פַּחַד:\",2,0],[2,121,5,22,\"וַיִּתְגָּעֲשׁוּ. גַּלָּיו, וּמְרוֹמֵם לַעֲבוֹר הַגְּבוּל וְלֹא יוּכָלוּ לַעֲבוֹר:\",3,0],[2,121,5,22,\"וְהָמוּ גַלָּיו. שָׁאוֹן קוֹל גָּדוֹל (ישעיהו יג:ד):\",4,0],[2,121,5,22,\"וְלֹא יַעַבְרֶנְהוּ. הַגַּלִּים לֹא יַעַבְרוּ הַגְּבוּל:\",5,0],[2,121,5,24,\"יוֹרֶה וּמַלְקוֹשׁ. כַּתַּרְגּוּם: ״בְּכִיר וְלָקִישׁ״:\",1,0],[2,121,5,24,\"שְׁבֻעוֹת חֻקּוֹת קָצִיר. שִׁבְעָה שָׁבוּעוֹת, שֶׁחָקַק לָנוּ בָּהֶן שְׁתֵּי חֻקּוֹת קָצִיר: חֹק הָעֹמֶר וְחֹק שְׁתֵּי הַלֶּחֶם (ויקרא רבה כח, ג):\",2,0],[2,121,5,24,\"יִשְׁמָר לָנוּ. שֶׁיְּהֵא הַקָּצִיר בִּזְמַנּוֹ:\",3,0],[2,121,5,25,\"הִטּוּ אֵלֶּה. הִטּוּ הַחֻקּוֹת הָאֵלֶּה מֵעֲלֵיכֶם; שֶׁאֵינָם שׁוֹמְרִים לָכֶם, וְאַתֶּם כָּלִים בָּרָעָב:\",1,0],[2,121,5,26,\"יָשׁוּר. יֶאֱרֹב, וְכֵן ״לְמַעַן שׁוֹרְרָי״ (תהילים ה:ט); לְשׁוֹן ״אֲשׁוּרֶנּוּ וְלֹא קָרוֹב״ (במדבר כד:יז):\",1,0],[2,121,5,26,\"כְּשַׁךְ יְקוּשִׁים. כַּאֲשֶׁר יִשּׁוֹךְ הַיָּקוֹשׁ שֶׁעוֹשִׂין לִלְכּוֹד צְבָיִים בַּיַּעַר, כְּשֶׁרַגְלוֹ בָּא לְתוֹכוֹ, וְהוּא נוֹשְׁכוֹ וּמַחֲזִיקוֹ בְּרַגְלוֹ, וְנִלְכָּד; וְקוֹרִין לוֹ פִּיי״ד בְּלַעַז:\",2,0],[2,121,5,26,\"הִצִּיבוּ מַשְׁחִית. צִינְבִּי״ל בְּלַעַ״ז; כֵּן עוֹשִׂין אוֹרְבִים עַל עִיר אוֹ עַל דֶּרֶךְ:\",3,0],[2,121,5,26,\"הִצִּיבוּ. כְּמוֹ ״מַצַּב פְּלִשְׁתִּים״ (שמואל א יג:כג) (סא״א):\",4,0],[2,121,5,27,\"כִּכְלוּב. הוּא מָקוֹם שֶׁמְּפַטְּמִין בּוֹ עוֹפוֹת; וְכֵן תִּרְגְּמוֹ יוֹנָתָן: ״כְּבֵית פִּיטְמָא״; וּבְלַעַ״ז פְרַנְ״ק:\",1,0],[2,121,5,28,\"עָשְׁתוּ. לְשׁוֹן ״עֶשֶׁת שֵׁן״ (שיר השירים ה:יד), גּוּף עָב; וּבְלַעַז אִישְׁפִּישׁוֹרְ״ט:\",1,0],[2,121,5,28,\"עָבְרוּ דִבְרֵי רָע. אִם בָּאת רָעָה אוֹ עֲבֵירָה לְיָדָם לֹא נָטוּ מִמֶּנָּה, אֶלָּא עָבְרוּ בָהּ וַעֲשָׂאוּהָ:\",2,0],[2,121,5,28,\"לֹא דָנוּ דִּין יָתוֹם. לְמַעַן יַצְלִיחוּ:\",3,0],[2,121,5,30,\"שַׁמָּה. תִּמָּהוֹן:\",1,0],[2,121,5,30,\"וְשַׁעֲרוּרָה. דָּבָר מְגֻנֶּה לַכֹּל. וּמַהוּ דְּבַר הַתִּמָּהוֹן? הַנְּבִיאִים נִבְּאִים שֶׁקֶר וְאוֹמְרִים: הֱווּ גּוֹזְלִין וְאוֹנְסִין, וְהַכֹּהֲנִים שֶׁהֵם שׁוֹפְטֵי הָעָם וְנוֹגְשֵׂיהֶם יִרְדּוּ אֶת הָעָם עַל יְדֵי הַנְּבִיאִים, כְּלוֹמַר: לְאַחֲרֵיהֶם, כְּמוֹ ״וְהַמֶּלֶךְ עוֹבֵר וְכָל הָעָם עוֹבְרִים עַל יָדוֹ״ (שמואל ב טו:יז-כג) (רוֹדֵף) (ס״א דְּדָוִד) אַחֲרָיו, אַף כָּאן עַל יְדֵיהֶם – אַחֲרֵיהֶם, לַעֲשׂוֹת כְּדִבְרֵי הַנְּבִיאִים:\",2,0],[2,121,6,1,\"הָעִזוּ בְּנֵי בִנְיָמִן. לָלֶכֶת לְעָרֵיכֶם, לִשְׁמֹר מִבְצָרֵיכֶם:\",1,0],[2,121,6,1,\"בֵּית הַכֶּרֶם. שֵׁם מָקוֹם הוּא:\",2,0],[2,121,6,1,\"שְׂאוּ מַשְׂאֵת. נֵס, לְהִקָּבֵץ וּלְהִלָּחֵם עַל נַפְשְׁכֶם:\",3,0],[2,121,6,2,\"הַנָּוָה וְהַמְּעֻנָּגָה דָּמִיתִי. הֶחֱרַבְתִּי תִּרְגְּמוֹ יוֹנָתָן; לְשׁוֹן ״וְנָדַמּוּ נְאוֹת הַשָּׁלוֹם״ (ירמיה כה:לז); ״נִדְמְתָה אַשְׁקְלוֹן״ (ירמיה מז:ה):\",1,0],[2,121,6,3,\"רוֹעִים וְעֶדְרֵיהֶם. מָשָׁל הוּא: מְלָכִים וְחֵילוֹתֵיהֶם:\",1,0],[2,121,6,3,\"רָעוּ. אָכְלוּ:\",2,0],[2,121,6,3,\"אֶת יָדוֹ. אֶת מְקוֹמוֹ; סְבִיבָיו:\",3,0],[2,121,6,4,\"קַדְּשׁוּ. זַמְּנוּ:\",1,0],[2,121,6,4,\"אוֹי לָנוּ. לְעֵת פְּנוֹת הַיּוֹם:\",2,0],[2,121,6,4,\"כִּי פָנָה הַיּוֹם. כַּאֲשֶׁר פָּנָה לְעֵת עֶרֶב הִצִּיתוּ הָאוּר בְּבֵית הַמִּקְדָּשׁ (תענית כט.):\",3,0],[2,121,6,6,\"כִּרְתוּ עֵצָה. לֹא מַפִּיק הֵ״א, וְהוּא לְשׁוֹן ׳עֵץ׳, שֶׁאֵין לְשׁוֹן ׳כְּרִיתָה׳ נוֹפֵל עַל הָ״עֵצָה״ (שמואל ב טז:כ). וְעֵצָה הָאָמוּר כָּאן – לְשׁוֹן הַרְבֵּה עֵצִים, כְּמוֹ ״דָּגָה״ (שמות ז:יח) – לְשׁוֹן דָּגִים הַרְבֵּה:\",1,0],[2,121,6,6,\"הָעִיר הָפְקַד. שֶׁבָּאָה פְּקֻדָּתָהּ:\",2,0],[2,121,6,7,\"כְּהָקִיר. לְשׁוֹן מָקוֹר:\",1,0],[2,121,6,7,\"בַּיִר. בְּאֵר:\",2,0],[2,121,6,7,\"כֵּן הֵקֵרָה רָעָתָהּ. כֵּן נוֹבַעַת רָעָתָם; תָּמִיד מוֹסִיפִים וּמְחַדְּשִׁים:\",3,0],[2,121,6,7,\"חֳלִי וּמַכָּה. ״עַל כֵּן אַיְתֵיתִי עֲלָהּ מְרַע וּמְחָא״ (תרגום יונתן):\",4,0],[2,121,6,8,\"הִוָּסְרִי. קַבְּלִי מוּסָר:\",1,0],[2,121,6,8,\"פֶּן תֵּקַע. פֶּן תִּנָּתֵק. הוֹקַע לְשׁוֹן חִבּוּר: ״וְהוֹקַע אוֹתָם״ (במדבר כה:ד), וְיֵשׁ לְשׁוֹן הֲסָרַת הַחִבּוּר, וְהַרְבֵּה תֵּיבוֹת מְשַׁמְּשׁוֹת כֵּן:\",2,0],[2,121,6,9,\"עוֹלֵל. גְּרַפָּאִי״ן בְּלַעַ״ז. לְאַחַר שֶׁבָּצְרוּ הַכֶּרֶם וְנִשְׁאֲרוּ עוֹלֵלוֹת, וְהָעֲנִיִּים בָּאִים וְעוֹלְלִים אוֹתָם, כֵּן יָבוֹזּוּ וְיַחְזְרוּ וְיָבוֹזּוּ:\",1,0],[2,121,6,9,\"הָשֵׁב יָדְךָ. אַתָּה, הַשּׂוֹנֵא, הָשֵׁב יָדְךָ לִשְׁלוֹל שֵׁנִית, כְּבוֹצֵר הַמֵּשִׁיב יָדוֹ עַל סַלְסִלּוֹת – הַמְּסַלְסֵל וּמְחַפֵּשׂ הָעוֹלֵלוֹת. וְכֵן הָיְתָה: מִשֶּׁהִגְלָה אֶת יְהוֹיָקִים וַהֲרָגוֹ וְהִמְלִיךְ אֶת יְכָנְיָה, חָזַר לְסוֹף שְׁלֹשָׁה חֳדָשִׁים וְהִגְלָהוּ, חָזַר לְסוֹף עַשְׁתֵּי עֶשְׂרֵה שָׁנָה וְהִגְלָה אֶת צִדְקִיָּהוּ (מלכים ב כד-כה):\",2,0],[2,121,6,9,\"סַלְסִלּוֹת. רְבִירְקְדוּרְ״שׁ בְּלַעַ״ז, כְּמוֹ ״סַלְסְלֶהָ וּתְרוֹמְמֶךָּ״ (משלי ד:ח) – כָּךְ פֵּרְשׁוֹ דּוּנַשׁ. וּמְנַחֵם פֵּרֵשׁ לְשׁוֹן ״סַל״ (שמות כט:ג); פַּנִירְ״שׁ בְּלַעַ״ז:\",3,0],[2,121,6,10,\"וְאָעִידָה. לְשׁוֹן הַתְרָאָה:\",1,0],[2,121,6,10,\"עֲרֵלָה. אֲטוּמָה, וְכֵן כָּל לְשׁוֹן עֲרֵלָה:\",2,0],[2,121,6,10,\"לְחֶרְפָּה. מְחָרְפִין אוֹתוֹ:\",3,0],[2,121,6,11,\"וְאֶת חֲמַת ה׳ מָלֵאתִי. לִבִּי מָלֵא נְבוּאָה לָבוֹא חֲמַת ה׳ עֲלֵיהֶם:\",1,0],[2,121,6,11,\"הָכִיל. כְּמוֹ ״לְהָכִיל״ (יחזקאל כא:לג), אשופרי״ר בְּלַעַ״ז:\",2,0],[2,121,6,11,\"שְׁפֹךְ עַל עוֹלָל. לִשְׁפֹּךְ עַל הַיּוֹנְקִים:\",3,0],[2,121,6,11,\"בַּחוּץ. בַּשּׁוּק:\",4,0],[2,121,6,11,\"מְלֵא יָמִים. קָרוֹב לַמָּוֶת, וְהוּא יֶתֶר עַל זָקֵן:\",5,0],[2,121,6,12,\"שָׂדוֹת וְנָשִׁים יַחְדָּו. יוּסַבּוּ לַאֲחֵרִים:\",1,0],[2,121,6,13,\"בּוֹצֵעַ בָּצַע. אוֹנֵס מָמוֹן:\",1,0],[2,121,6,14,\"עַל נְקַלָּה. קַל הוּא לִנְבִיאֵי הַשֶּׁקֶר לְהוֹצִיא מִפִּיהֶם וְלוֹמַר שָׁלוֹם יִהְיֶה לָכֶם (ירמיה ד:י), וּבַדָּבָר הַזֶּה מְרַפְּאִין בְּדִבּוּרָם אֶת הַשֶּׁבֶר הֶעָתִיד לָבֹא עֲלֵיהֶן:\",1,0],[2,121,6,15,\"הוֹבִישׁוּ. ״עֲלֵיהוֹן לְמִיבְהַת״ (תרגום יונתן):\",1,0],[2,121,6,15,\"הַכְלִים. כְּמוֹ לְהַכְלִים:\",2,0],[2,121,6,15,\"גַּם בּוֹשׁ לֹא יֵבוֹשׁוּ. אֵינָם מִתְבַּיְּשִׁין מִמַּעֲשֵׂיהֶם הָרָעִים:\",3,0],[2,121,6,16,\"מַרְגּוֹעַ. מְנוּחָה:\",1,0],[2,121,6,17,\"וַהֲקִימֹתִי עֲלֵיכֶם צוֹפִים. הוּא שֶׁמַּעֲמִידִין אֲנָשִׁים עַל הַמִּגְדָּלִים עֵת הַחֵרוּם אִישׁ צוֹפֶה, וְרוֹאֶה: אִם גַּיִס בָּא לָעִיר, תּוֹקֵעַ בַּשּׁוֹפָר וּמַזְהִיר אֶת הָעָם לְהֵחָלֵץ וְלָבֹא עַל הַחוֹמָה; אַף אֲנִי הֶעֱמַדְתִּי נְבִיאִים הַמַּשְׁמִיעִים אֶתְכֶם אֶת הַפֻּרְעָנוּת הַבָּאָה, לְהִזְדָּרֵז וּלְתַקֵּן דַּרְכֵיכֶם שֶׁתְּנַצְּלוּ, וְהוּא כְּשׁוֹפָר תְּקִיעוֹת הַצּוֹפֶה, הַקְשִׁיבוּ לְקוֹל הַשּׁוֹפָר הַזֶּה וְהֵחָלְצוּ:\",1,0],[2,121,6,17,\"וְהַקִימֹתִי. פֵּירוּשׁ: הֶעֱמַדְתִּי לָהֶם כְּבָר; וְכֵן תִּרְגֵּם יוֹנָתָן: ״וַאֲקִימִית״, צוֹפִים גִּיט״שׁ בְּלַעַ״ז:\",2,0],[2,121,6,18,\"אֶת אֲשֶׁר בָּם. אֶת הָרָעָה אֲשֶׁר בְּיָדָם:\",1,0],[2,121,6,19,\"פְּרִי מַחְשְׁבוֹתָם. שְׂכַר מַחְשְׁבוֹתָם:\",1,0],[2,121,6,19,\"וְתוֹרָתִי וַיִּמְאֲסוּ בָהּ. הֲרֵי זֶה דּוּגְמַת ״עָזִּי וְזִמְרָת יָהּ וַיְהִי לִי לִישׁוּעָה״ (שמות טו:ב), שֶׁהָיָה לוֹ לוֹמַר הָיָה לִי לִישׁוּעָה; אַף כָּאן הָיָה לוֹ לוֹמַר וְתוֹרָתִי מָאֲסוּ בָהּ. וְדֶרֶךְ הַמִּקְרָאוֹת לְדַבֵּר כֵּן:\",2,0],[2,121,6,20,\"לָמָּה זֶּה לִי לְבוֹנָה. אֲשֶׁר אַתֶּם מַקְרִיבִים לְפָנַי, אֲשֶׁר מִשְּׁבָא בָּאָה:\",1,0],[2,121,6,20,\"לֹא עָרְבוּ. לֹא נָעֲמוּ:\",2,0],[2,121,6,23,\"יַחֲזִיקוּ. יִקְחוּ, כְּמוֹ ״וַיִּשְׁלַח יָדוֹ וַיַּחֲזֶק בּוֹ״ (שמות ד:ד), וְכֵן ״צָרָה הֶחֱזִיקַתְנוּ״ (ירמיה ו:כד) – אֲחָזַתְנוּ:\",1,0],[2,121,6,25,\"מָגוֹר. יִרְאָה. לָשׁוֹן אַחֵר: לְשׁוֹן אֲסִיפָה, כְּמוֹ ״מְגוּרֵי אֶל חֶרֶב״ (יחזקאל כא:יז); וְכֵן תִּרְגֵּם יוֹנָתָן:\",1,0],[2,121,6,26,\"וְהִתְפַּלְּשִׁי. הִתְגַּלְגְּלִי:\",1,0],[2,121,6,26,\"אֵבֶל יָחִיד. אֵבֶל שֶׁל בֵּן יָחִיד, מִי שֶׁאֵין לוֹ אֶלָּא בֵּן יָחִיד וּמֵת:\",2,0],[2,121,6,26,\"מִסְפַּד תַּמְרוּרִים. לְפִי שֶׁהוּא דָּבוּק נָקוּד מִסְפַּד בְּפַתָּח, וְאֵינוֹ נָקוּד מִסְפֵּד (ירמיה מח:לח) בְּצֵירֵי:\",3,0],[2,121,6,26,\"עָלֵינוּ. כִּבְיָכוֹל, עָלַי וְעָלֶיךָ:\",4,0],[2,121,6,27,\"בָּחוֹן נְתַתִּיךָ. לְיִרְמְיָה נֶאֱמַר: חָזָק נְתַתִּיךָ בְּתוֹכָם. וְתֵדַע וּבָחַנְתָּ אֶת דַּרְכָּם. שֶׁתּוֹכִיחֵם וְהֵם לֹא יִשְׁמְעוּ. בָּחוֹן. לְשׁוֹן חוֹזֶק, כְּמוֹ ״עֹפֶל וָבַחַן״ (ישעיהו לב:יד); ״הֵקִימוּ בְחוּנָיו״ (ישעיהו כג:יג):\",1,0],[2,121,6,28,\"סָרֵי סוֹרְרִים. סָרִים מִן הַדֶּרֶךְ:\",1,0],[2,121,6,28,\"הוֹלְכֵי רָכִיל. בֵּין הַנְּחֹשֶׁת וְהַבַּרְזֶל: מַטִּילֵי אֵיבָה בֵּין שְׁנֵי שָׂרִים שֶׁיֵּשׁ בָּהֶן כֹּחַ לְהִתְגָּרוֹת יַחַד; כָּךְ שָׁמַעְתִּי. וַאֲנִי אוֹמֵר: הוֹלְכֵי רָכִיל הֵם, וַחֲזָקִים כַּנְּחֹשֶׁת וּבַרְזֶל לְהַחֲזִיק כְּזָבֵיהֶם. וְיוֹנָתָן תִּרְגֵּם רָכִיל זֶה לְשׁוֹן נוֹכֵל: ״מְהַלְּכִין בִּנְכִילוּ כְּמָא דְמְעָרֵב נְחָשׁ עִם פַּרְזְלָא״. וְנוֹכֵל הוּא לְשׁוֹן מַחֲשָׁבָה, כְּמוֹ ״וַיִּתְנַכְּלוּ אֹתוֹ לַהֲמִיתוֹ״ (בראשית לז:יח):\",2,0],[2,121,6,29,\"נָחַר מַפּוּחַ. מָשָׁל הוּא: כְּשֶׁצּוֹרְפִים כֶּסֶף נוֹפְחִין בַּמַּפּוּחַ, וְנוֹתְנִין תָּמִיד עוֹפֶרֶת בְּתוֹךְ הַכּוּר וּמוֹעִיל לִצְרוֹף; אֲבָל אַתֶּם, בָּאתִי לִצְרוֹף אֶתְכֶם – הַמַּפּוּחַ נָחַר וְנֶחְרַךְ מִכֹּחַ הָאֵשׁ, וְתַם הָעוֹפֶרֶת כֻּלּוֹ. נָחַר לְשׁוֹן ״חָרָה אַפּוֹ״ (איוב לב:ב) ״וְעַצְמִי חָרָה מִנִּי חֹרֶב״ (איוב ל:ל) אישר״ש בְּלַעַ״ז:\",1,0],[2,121,6,29,\"לַשָּׁוְא. עַל חִנָּם צָרַף הַצּוֹרֵף כִּי לֹא הוֹעִיל:\",2,0],[2,121,6,29,\"וְרָעִים לֹא נִתָּקוּ. מִדַּרְכָּם הָרָעָה; כְּלוֹמַר: יָגְעוּ הַנְּבִיאִים לְהוֹכִיחַ וְלֹא הוֹעִילוּ:\",3,0],[2,121,6,29,\"נִתָּקוּ. פּוֹרְצְטְרַאקִי״ץ בְּלַעַ״ז, (נוסח אחר וְרָעִים כְּמוֹ רְשָׁעִים סא״א):\",4,0],[2,121,6,30,\"כֶּסֶף נִמְאָס. שֶׁאֵינוֹ נִצְרָף בְּשׁוּם יְגִיעָה:\",1,0],[2,121,7,4,\"הֵיכַל ה׳ הֵיכַל ה׳ הֵיכַל ה׳. ״תְּלָת זִמְנִין בְּשַׁתָּא אַתּוּן מִתְחֲזִין קֳדָמוֹהִי״:\",1,0],[2,121,7,9,\"הֲגָנֹב רָצֹחַ וְגוֹ׳. בִּתְמִיהָּ, וְכִי אֵלֶּה תַּעֲשׂוּ וְיוֹעִיל הַהֵיכָל לָכֶם?\",1,0],[2,121,7,11,\"הַמְעָרַת פָּרִיצִים הָיָה. בְּעֵינֵיכֶם הַבַּיִת הַזֶּה? בִּתְמִיהָּ:\",1,0],[2,121,7,11,\"הִנֵּה רָאִיתִי. שֶׁכָּךְ הוּא בְּעֵינֵיכֶם:\",2,0],[2,121,7,14,\"כַּאֲשֶׁר עָשִׂיתִי לְשִׁלוֹ. בִּימֵי עֵלִי (שמואל א ד:יא-יח):\",1,0],[2,121,7,15,\"כַּאֲשֶׁר הִשְׁלַכְתִּי וְגוֹ׳. עֲשֶׂרֶת הַשְּׁבָטִים:\",1,0],[2,121,7,18,\"לַעֲשׂוֹת כַּוָּנִים. דְּפוּס הַכּוֹכָב:\",1,0],[2,121,7,18,\"לִמְלֶכֶת הַשָּׁמַיִם. כּוֹכָב הַגָּדוֹל הָיוּ קוֹרִין מְלֶכֶת הַשָּׁמַיִם, לְשׁוֹן מַלְכָּה; וְכֵן תִּרְגֵּם יוֹנָתָן: ״לְכוֹכֶבֶת שְׁמַיָּא״:\",2,0],[2,121,7,20,\"נִתֶּכֶת. יוֹרֶדֶת וּמַגַּעַת; כְּמוֹ ״וּמָטָר לֹא נִתַּךְ אָרְצָה״ (שמות ט:לג) ״לָא מְטָא״ (תרגום אונקלוס):\",1,0],[2,121,7,21,\"עוֹלוֹתֵיכֶם. שֶׁאַתֶּם מַקְרִיבִים כָּלִיל (ויקרא א:ח-ט), טוֹב לָכֶם שֶׁתּוֹסִיפוּ אוֹתָם עַל שַׁלְמֵיכֶם וְתַקְרִיבוּ אוֹתָם שְׁלָמִים וְתֹאכְלוּ הַבָּשָׂר, שֶׁהֲרֵי אֵינָם מְקֻבָּלוֹת לְפָנַי, וְלָמָּה תַפְסִידוּם?\",1,0],[2,121,7,22,\"בְּיוֹם הוֹצִיאִי אוֹתָם. תְּחִלַּת תְּנַאי לֹא הָיְתָה אֶלָּא ״אִם שָׁמוֹעַ תִּשְׁמְעוּ בְּקוֹלִי וּשְׁמַרְתֶּם אֶת בְּרִיתִי וִהְיִיתֶם לִי סְגֻלָּה״ (שמות יט:ה).\",1,0],[2,121,7,24,\"בִּשְׁרִירוּת לִבָּם. בְּמַרְאֵה לִבָּם; לָשׁוֹן ״אֲשׁוּרֶנּוּ״ (במדבר כד:יז):\",1,0],[2,121,7,25,\"יוֹם הַשְׁכֵּם וְשָׁלוֹחַ. מִדֵּי יוֹם בְּיוֹם הַשְׁכֵּם וְשָׁלוֹחַ:\",1,0],[2,121,7,29,\"גָּזִּי נִזְרֵךְ. תַּלְשִׁי שְׂעָרֵךְ; כְּמוֹ ״וַיָּגָז שַׂלְוִים״ (במדבר יא:לא); ״וַיָּגָז אֶת רֹאשׁוֹ״ (איוב א:כ). לָשׁוֹן אַחֵר: נִזְרֵךְ כִּתְרֵךְ, לְשׁוֹן גְּדֻלָּה; וְכֵן תִּרְגֵּם יוֹנָתָן: ״רַבְרְבִיךְ״, וְכֵן חִבְּרוֹ מְנַחֵם:\",1,0],[2,121,7,29,\"וַיִּטֹּשׁ. וַיַּעֲזֹב:\",2,0],[2,121,7,31,\"בָּמוֹת הַתֹּפֶת. הוּא הַמֹּלֶךְ (מלכים ב כג:י), שֶׁהָיָה שֶׁל נְחֹשֶׁת, וּמַסִּיקִין אוֹתוֹ מִתַּחְתָּיו וְיָדָיו פְּשׁוּטוֹת וְנִסָּקוֹת, וְנוֹתְנִין אֶת הַיֶּלֶד עַל יָדָיו וְהוּא נִכְוֶה וְנוֹהֵם, וְהַכּוֹמְרִים הָיוּ מַקִּישִׁין בְּתוּפִּים שֶׁלֹּא יִשְׁמַע הָאָב קוֹל הַבֵּן וְיִכָּמְרוּ רַחֲמָיו (בראשית מג:ל). תֹּפֶת עַל שֵׁם הַתּוֹף:\",1,0],[2,121,7,31,\"הִנֹּם. עַל שֵׁם נַהֲמַת הַבֵּן (תנחומא בובר, ואתחנן הוספה ב):\",2,0],[2,121,7,31,\"לֹא צִוִּיתִי. בְּמִצְווֹת שֶׁיַּקְרִיבוּ בְּנֵיהֶם לְקָרְבָּן, וְלֹא דִבַּרְתִּי לְאֶחָד מִן הַנְּבִיאִים. וּכְשֶׁדִּבַּרְתִּי לְאַבְרָהָם לִשְׁחוֹט אֶת בְּנוֹ (בראשית כב:ב), לֹא עָלְתָה עַל לִבִּי שֶׁיִּשְׁחוֹט, אֶלָּא לְהוֹדִיעַ צִדְקוֹ:\",3,0],[2,121,7,33,\"וְאֵין מַחֲרִיד. אֶת הָעוֹפוֹת מֵעַל הַפְּגָרִים:\",1,0],[2,121,8,2,\"וּשְׁטָחוּם לַשֶּׁמֶשׁ. וְהַכַּשְׂדִּים יִשְׁכְּנוּ לָצוּר עַל הָעִיר בְּקִבְרֵי הַשָּׂרִים, שֶׁהָיוּ נָאִים כְּפַלָּטִין (סנהדרין צו:):\",1,0],[2,121,8,2,\"לְדֹמֶן. לְזֶבֶל:\",2,0],[2,121,8,3,\"וְנִבְחַר מָוֶת מֵחַיִּים. אַף עַל פִּי שֶׁהֵם רוֹאִים אֶת הַמֵּתִים נְתוּנִין בְּבִזָּיוֹן, צָרַת הַחַיִּים גְּדוֹלָה הֵימֶנָּה, וְיִבְחֲרוּ אֶת הַמָּוֶת:\",1,0],[2,121,8,4,\"הֲיִפְּלוּ וְלֹא יָקוּמוּ. הֲטוֹב לָהֶם שֶׁיַּפִּילוּ אֶת עַצְמָם לִנְפִילָה שֶׁאֵין לָהֶם תְּקוּמָה:\",1,0],[2,121,8,4,\"אִם יָשׁוּב וְלֹא יָשׁוּב. לִכְשֶׁיִּרְצוּ לָשׁוּב מֵרָעָתָם, לֹא יָשׁוּב הַקָּדוֹשׁ בָּרוּךְ הוּא מִגְּזֵרָתוֹ (ספר במדבר מב). דָּבָר אַחֵר: אַף אִם יָשׁוּבוּ בִּתְשׁוּבָה, לֹא תִתְקַיֵּם בְּיָדָם, כִּי יְמַהֲרוּ לָשׁוּב לְרִשְׁעָתָם (ספר במדבר מב); וְכֵן תִּרְגֵּם יוֹנָתָן: ״אִם לְמֵיתַב, גְּלֵי קֳדָמַי דְּלָא יְתוּבוּן״:\",2,0],[2,121,8,5,\"מְשׁוּבָה נִצַּחַת. מְשׁוּבַת עוֹלָם; כְּמוֹ ״נֶצַח״ (ירמיה טו:יח):\",1,0],[2,121,8,5,\"הֶחֱזִיקוּ. אָחֲזוּ:\",2,0],[2,121,8,5,\"בַּתַּרְמִית. בְּמִרְמָה:\",3,0],[2,121,8,6,\"לֹא כֵן. לֹא בַּדִּין, כְּמוֹ ״כֵּן בְּנוֹת צְלָפְחָד״ (במדבר כז:ז):\",1,0],[2,121,8,6,\"כֻּלֹּה שָׁב בִּמְרוּצָתָם. בַּדֶּרֶךְ הָרִאשׁוֹן חוֹטְאִים, וְחוֹזְרִים וְחוֹטְאִים. מְרוּצָתָם – קוֹרְשִׁ״י בְּלַעַ״ז:\",2,0],[2,121,8,6,\"שׁוֹטֵף. אֵישְׁפְּרִידִי״ן בְּלַעַ״ז:\",3,0],[2,121,8,7,\"חֲסִידָה. צִיגוֹנִיאָ״ה בְּלַעַ״ז:\",1,0],[2,121,8,7,\"מוֹעֲדֶיהָ. עֵת עָבְרָם אֶל אִיֵּי הַיָּם מִפְּנֵי הַצִּנָּה, וְעֵת שׁוּבָם:\",2,0],[2,121,8,7,\"שָׁמְרוּ. הִמְתִּינוּ:\",3,0],[2,121,8,7,\"וְתוֹר וְסִיס וְעָגוּר. ״וְשַׁפְנִינָא וְכוּרְכְיָא וּסְנוּנִיתָא״ (תרגום יונתן). כּוּרְכְיָא – גְּרוּאָ״ה בְּלַעַ״ז, סְנוּנִית – אֲרוּנְדִּילָ״א בְּלַעַ״ז:\",4,0],[2,121,8,8,\"אָכֵן הִנֵּה לַשֶּׁקֶר. הִנֵּה חָכְמַתְכֶם לַשֶּׁקֶר בָּכֶם, לְרַפְּאוֹתְכֶם עַל נְקַלָּה:\",1,0],[2,121,8,8,\"עָשָׂה עֵט שֶׁקֶר סוֹפְרִים. נְבִיאֲכֶם:\",2,0],[2,121,8,9,\"הוֹבִישׁוּ חֲכָמִים. כְּמוֹתְכֶם. וּמַהוּ הַבֹּשֶׁת? – הִנֵּה בִדְבַר ה׳ מָאָסוּ וְחָכְמַת מֶה לָהֶם:\",1,0],[2,121,8,11,\"וַיְרַפּוּ. כְּמוֹ ״וַיְרַפְּאוּ״ (ירמיה ו:יד):\",1,0],[2,121,8,12,\"הוֹבִישׁוּ. בֹּשֶׁת וּכְלִימָּה תָּבֹא לָהֶם:\",1,0],[2,121,8,12,\"גַּם בּוֹשׁ לֹא יֵבוֹשׁוּ. אֵינָם מִתְבַּיְּשִׁים בְּמַעֲשֵׂיהֶם הָרָעִים, לָתֵת לֵב לָשׁוּב:\",2,0],[2,121,8,13,\"אָסֹף אֲסִיפֵם. לְשׁוֹן כְּלָיָה, כְּמוֹ ״אָסֹף אָסֵף כֹּל מֵעַל פְּנֵי הָאֲדָמָה״ (צפניה א:ב):\",1,0],[2,121,8,13,\"אֵין עֲנָבִים בַּגֶּפֶן. לֹא יִוָּתֵר דָּבָר:\",2,0],[2,121,8,13,\"וְהֶעָלֶה נָבֵל. לְשׁוֹן כָּמוֹשׁ, פְּלֵיישְׁטִי״שׁ בְּלַעַ״ז; כְּמוֹ ״וּכְנֹבֶלֶת מִתְּאֵנָה״ (ישעיהו לד:ד), ״כָּאֵלָה נוֹבֶלֶת עָלֶיהָ״ (ישעיהו א:ל):\",3,0],[2,121,8,13,\"וָאֶתֵּן לָהֶם יַעַבְרוּם. כָּל זֹאת תִּהְיֶה לָהֶם עַל כִּי נָתַתִּי לָהֶם חֻקִּים וְעָבְרוּ עֲלֵיהֶם:\",4,0],[2,121,8,14,\"וְנִדְּמָה שָׁם. וְנִדּוֹם שָׁם, נֵשֵׁב שָׁם דּוֹמִים וַאֲבֵלִים:\",1,0],[2,121,8,14,\"מֵי רֹאשׁ. ״כָּס דִּלְוָוט בִּישׁ כְּרֵישֵׁי חִיוָן״ (תרגום יונתן); ״רֹאשׁ פְּתָנִים״ (דברים לב:לג) הוּא אֶרֶס שֶׁבְּשִׁנָּיו:\",2,0],[2,121,8,16,\"מִדָּן נִשְׁמַע. ״עַל דְּפַלְחוּ לְעֶגְלָא דִּבְדָן״ (תרגום יונתן; סנהדרין צו.):\",1,0],[2,121,8,16,\"נַחְרַת סוּסָיו. עֲטִישׁוֹת נְחִירָיו:\",2,0],[2,121,8,16,\"מִצְהֲלוֹת אַבִּירָיו. צַהֲלַת מִשְׂחַק סוּסָיו; וּמָצִינוּ בְּמָקוֹם אַחֵר סוּסִים נִקְרָאִים אַבִּירִים: ״מִדַּהֲרוֹת דַּהֲרוֹת אַבִּירָיו״ (שופטים ה:כב), לְשׁוֹן ״סוּס דּוֹהֵר״ (נחום ג:ב). וְיוֹנָתָן תִּרְגֵּם: ״מִקָּל פְּסִיעוֹת גַּבְרוֹהִי״:\",3,0],[2,121,8,17,\"נְחָשִׁים צִפְעֹנִים. לְסוֹף שִׁבְעִים שָׁנָה נַעֲשֶׂה צֶפַע, וְאוֹטֵם אָזְנוֹ שֶׁלֹּא יִשְׁמַע לְקוֹל חֶבֶר הַמְלַחֲשׁוֹ, שֶׁנֶּאֱמַר ״כְּמוֹ פֶתֶן חֵרֵשׁ יַאְטֵם אָזְנוֹ…״ (תהלים נח:ה-ו); הוּא שֶׁנֶּאֱמַר: אֲשֶׁר אֵין לָהֶם לָחַשׁ (ראה שוחר טוב נח:ב):\",1,0],[2,121,8,18,\"מַבְלִיגִיתִי עֲלֵי יָגוֹן. כְּמוֹ הִבְלַגְתִּי, וְשֵׁם דָּבָר הוּא מישאיטינמנ״ץ בְּלַעַ״ז, כְּלוֹמַר אִם אָמַרְתִּי אַבְלִיגָה וְאֶתְאַפֵּק עֲלֵי יָגוֹנִי:\",1,0],[2,121,8,18,\"עָלַי לִבִּי דַוָּי. מִקּוֹל נְבוּאוֹת הַנִּגְלוֹת אֵלַי בְּפֻרְעָנִיּוֹת הַבָּאוֹת:\",2,0],[2,121,8,19,\"הִנֵּה קוֹל שַׁוְעַת בַּת עַמִּי. אֲנִי שׁוֹמֵעַ שֶׁסּוֹפָן לִצְעֹק בְּאֶרֶץ מַרְחַקִּים. וְלָמָּה כָּל זֹאת? הֲלֹא ה׳ בְּצִיּוֹן, וְאִם יָשׁוּבוּ אֵלָיו יִמָּצֵא לָהֶם!\",1,0],[2,121,8,20,\"עָבַר קָצִיר כָּלָה קָיִץ. צִפִּינוּ לְעֶזְרַת מִצְרַיִם וְלֹא בָאָה; אָמַרְנוּ: יַעֲבֹר הַקָּצִיר וְיִהְיוּ פְנוּיִין וְיָבֹאוּ, וְהִנֵּה עָבַר זְמַן הַקָּצִיר בְּאִיָּר, וּזְמַן הַקָּיִץ בְּתַמּוּז, וְלֹא בָאוּ (בבא מציעא קו:):\",1,0],[2,121,8,21,\"קָדַרְתִּי. לְשׁוֹן שַׁחֲרוּת וְאֹפֶל:\",1,0],[2,121,8,21,\"שַׁמָּה. תִּמָּהוֹן:\",2,0],[2,121,8,21,\"הֶחֱזִקָתְנִי. אֲחָזַתְנִי:\",3,0],[2,121,8,22,\"הַצֳּרִי אֵין בְּגִלְעָד. שֶׁהַצֳּרִי בָּא מִשָּׁם, כְּמוֹ שֶׁנֶּאֱמַר ״עֲלִי גִלְעָד וּקְחִי צֳרִי״ (ירמיה מו:יא); כְּלוֹמַר: וְכִי לֹא הָיוּ לָהֶם אֲנָשִׁים צַדִּיקִים מִמִּי לִלְמֹד, וְיֵיטִיבוּ דַרְכֵיהֶם?\",1,0],[2,121,8,22,\"אֲרֻכַת. רְפוּאַת אִינְפְּלַשְׁטְרָ״א בְּלַעַ״ז:\",2,0],[2,121,9,1,\"עֲצֶרֶת בֹּגְדִים. כְּנֵסִיּוֹת בּוֹגְדִים:\",1,0],[2,121,9,2,\"וַיַּדְרְכוּ. לָשׁוֹן זֶה נוֹפֵל בְּהַזְמָנַת הַקֶּשֶׁת לִירוֹת חֵץ; וְקֶשֶׁת הִיא אַרְבַּלִישְׁטְ״א בְּלַעַ״ז, וּבָרַגְלַיִם דּוֹרְכִין אוֹתָהּ, לְכָךְ קוֹרֵא אוֹתָהּ דְּרִיכָה. וְהַנָּבִיא הִמְשִׁיל לְשׁוֹנָם לְקֶשֶׁת שֶׁקֶר, שֶׁדָּרְכוּ לְשׁוֹנָם קֶשֶׁת בְּשֶׁקֶר:\",1,0],[2,121,9,2,\"מֵרָעָה אֶל רָעָה. מֵעֲבֵירָה אֶל עֲבֵירָה:\",2,0],[2,121,9,3,\"עָקוֹב יַעֲקֹב. אָרוֹב יֶאֱרֹב:\",1,0],[2,121,9,4,\"הַעֲוֵה נִלְאוּ. יָגְעוּ וְטָרְחוּ לְעַוֵּת אֶת דַּרְכָּם:\",1,0],[2,121,9,4,\"הַעֲוֵה. כְּמוֹ ״הַכְבֵּד אֶת לִבּוֹ״ (שמות ח:יא): לְהַעֲווֹת:\",2,0],[2,121,9,5,\"שִׁבְתְּךָ בְּתוֹךְ מִרְמָה. כְּשֶׁהֵן יוֹשְׁבִים, חוֹשְׁבִין מַחְשְׁבוֹת מִרְמָה; וּבְמִרְמָה הֶחְלִיפוּ יִרְאָתִי וּמֵאֲנוּ דַעַת אוֹתִי:\",1,0],[2,121,9,5,\"בְּמִרְמָה. בִּשְׁבִיל הַמִּרְמָה:\",2,0],[2,121,9,6,\"הִנְנִי צוֹרְפָם. בְּיִסּוּרִין:\",1,0],[2,121,9,6,\"מִפְּנֵי בַת עַמִּי. ״מִן קֳדָם חוֹבֵי כְּנִישְׁתָּא דְיִשְׂרָאֵל״ (תרגום יונתן):\",2,0],[2,121,9,7,\"חֵץ שָׁחוּט לְשׁוֹנָם. מָשׁוּךְ; כְּמוֹ ״זָהָב שָׁחוּט״ (מלכים א י:טז), וְכֵן ״וְשַׁחֲטָה שִׁטִּים״ (הושע ה:ב) טְרֵיי״ט בְּלַעַ״ז. לִישְׁנָא אַחֲרִינָא: לְשׁוֹן שְׁחִיטָה מַמָּשׁ, טְרַאנְקָא״ט בְּלַעַ״ז; וְכֵן חִבְּרוֹ מְנַחֵם, וְכֵן תִּרְגֵּם יוֹנָתָן: ״כְּגִיר דִּי מַחְרִיף״:\",1,0],[2,121,9,7,\"וּבְקִרְבּוֹ. תִּרְגֵּם יוֹנָתָן: ״וּבְמָעוֹהִי״:\",2,0],[2,121,9,9,\"עַל הֶהָרִים. עַל חֻרְבַּן הֶהָרִים:\",1,0],[2,121,9,9,\"וְעַל נְאוֹת מִדְבָּר. נְוֵה רוֹעִים שֶׁבַּמִּדְבָּרוֹת. נְאוֹת לְשׁוֹן ״נָוֶה״, וְכֵן ״נְאוֹת אֱלֹהִים״ (תהלים פג:יג), וְכֵן ״לְבֵיתְךָ נָאֲוָה קֹדֶשׁ״ (תהלים צג:ה):\",2,0],[2,121,9,9,\"נִצְּתוּ. לְשׁוֹן ״צִיָּה״ (ירמיה ב:ו), וְכֵן ״נִצְּתָה״ (ירמיה ט:יא):\",3,0],[2,121,9,9,\"נָדְדוּ הָלָכוּ. סוֹפָן לֵילֵךְ. חֲמִשִּׁים וּשְׁתַּיִם שָׁנָה לֹא עָבַר אִישׁ בִּיהוּדָה; מִגָּלוּת צִדְקִיָּהוּ עַד פְּקִידַת כּוֹרֶשׁ מֶלֶךְ פָּרַס חֲמִשִּׁים וּשְׁתַּיִם שָׁנָה הָיוּ, וְרֶמֶז לַדָּבָר: עַד בְּהֵמָה. חֶשְׁבּוֹנָהּ בְּגִימַטְרִיָּא חֲמִשִּׁים וּשְׁתַּיִם; וְהַחֶשְׁבּוֹן מְכֻוָּן בְּמַסֶּכֶת מְגִלָּה (ראה יומא נד.):\",4,0],[2,121,9,10,\"לְגַלִּים. ״דְּגוֹרִין״ (תרגום יונתן):\",1,0],[2,121,9,11,\"מִי הָאִישׁ הֶחָכָם. שֶׁיָּבִין זֹאת, וּמִי הַנָּבִיא אֲשֶׁר דִּבֶּר פִּי ה׳ אֵלָיו:\",1,0],[2,121,9,11,\"וְיַגִּידָהּ. וּמִי יַגִּיד עַל מָה אָבְדָה הָאָרֶץ וּבָא כָּל הַפֻּרְעָנוּת הַזֶּה:\",2,0],[2,121,9,14,\"לַעֲנָה. עֵשֶׂב מַר:\",1,0],[2,121,9,14,\"מֵי רֹאשׁ. אֶרֶס נָחָשׁ:\",2,0],[2,121,9,18,\"כִּי הִשְׁלִיכוּ מִשְׁכְּנוֹתֵינוּ. אֶת שׁוֹכְנֵיהֶם. וְיֵשׁ עוֹד לוֹמַר: כִּי הִשְׁלִיכוּ הָאוֹיְבִים אֶת מִשְׁכְּנוֹתֵינוּ לָאָרֶץ:\",1,0],[2,121,9,20,\"לְהַכְרִית עוֹלָל מִחוּץ. מִן הַשּׁוּק; כְּמוֹ ״וְחוּצוֹת תָּשִׂים לְךָ בְדַמֶּשֶׂק״ (מלכים א כ:לד):\",1,0],[2,121,9,22,\"אַל יִתְהַלֵּל חָכָם. אַל תִּתְהַלְּלוּ לוֹמַר: ״חֲכָמִים אֲנַחְנוּ״ (ירמיה ח:ח); הִנֵּה בִּדְבָרַי מְאַסְתֶּם וְחָכְמַת מַה לָכֶם (ירמיה ח:ט); אִם הִשְׂכַּלְתֶּם וִידַעְתֶּם אוֹתִי, אָז תִּתְהַלְּלוּ בְּחָכְמַתְכֶם:\",1,0],[2,121,9,23,\"השכל. כמו ״הַכְבֵּד״ (שמות ח:יא) (אגטליינ״ט בלע״ז):\",1,0],[2,121,9,24,\"עַל כָּל מוּל בְּעָרְלָה. עַל כָּל מוּל שֶׁיֵּשׁ לוֹ עָרְלָה, אֲפִלּוּ עָרְלַת לֵב (בראשית רבה מו, ה):\",1,0],[2,121,9,25,\"עַל מִצְרַיִם וְגוֹ׳. שְׁכֵינֵי אֶרֶץ יִשְׂרָאֵל הָיוּ, וְלָקוּ אַחֲרֶיהָ בְּסָמוּךְ לָהּ, כְּמוֹ שֶׁכָּתוּב בִּיחֶזְקֵאל (יחזקאל כט:ב-יב); וּמְפֹרָשׁ בְּסֵדֶר עוֹלָם (סדר עולם רבה כו):\",1,0],[2,121,9,25,\"קְצוּצֵי פֵאָה. לְשׁוֹן קָצֶה: הַמּוּקְצִין בִּפְאַת מִדְבָּר:\",2,0],[2,121,10,2,\"אֶל דֶּרֶךְ הַגּוֹיִם אַל תִּלְמָדוּ. וְאָז מֵאוֹתוֹת הַשָּׁמַיִם אַל תֵּחָתּוּ – מֵחַמָּה לוֹקָה וּמִמְּאוֹרוֹת לוֹקִין:\",1,0],[2,121,10,3,\"חָרָשׁ. אֻמָּן:\",1,0],[2,121,10,3,\"מַעֲצָד. דּוֹלְדוֹיִירָ״א בְּלַעַ״ז:\",2,0],[2,121,10,4,\"מַסְמְרוֹת. קְלוֹיִ״שׁ בְּלַעַ״ז:\",1,0],[2,121,10,4,\"וּמַקָּבוֹת. קוֹרְנָס, מַרְטִי״ל בְּלַעַ״ז:\",2,0],[2,121,10,4,\"יָפִיק. יִכְרַע בִּרְכָּיו, לְשׁוֹן ״פּוּקָה״ (שמואל א כה:לא) ״וּפִיק בִּרְכַּיִם״ (נחום ב:יא):\",3,0],[2,121,10,5,\"כְּתֹמֶר מִקְשָׁה. מַקִּישׁ אוֹתוֹ בְּקוּרְנָס עַד שֶׁזּוֹקֵף לוֹ קוֹמָה כְּדֶקֶל:\",1,0],[2,121,10,5,\"אַל תִּירְאוּ מֵהֶם. אִם תִּפְרְשׁוּ מֵהֶם, כִּי לֹא יָרֵעוּ לָכֶם:\",2,0],[2,121,10,5,\"וְגַם הֵיטֵיב אֵין אוֹתָם. אִם תַּעַבְדוּם. הֵיטֵיב כְּמוֹ ״לְהֵיטִיב״ (ירמיה לב:מא):\",3,0],[2,121,10,7,\"לְךָ יָאָתָה. לְךָ נָאֶה:\",1,0],[2,121,10,8,\"וּבְאַחַת יִבְעֲרוּ. הַגּוֹיִים. וּמָה הִיא הָאַחַת מוּסַר הֲבָלִים שֶׁל עֵץ שֶׁלָּהֶם וְיִתְיַסְּרוּ עָלָיו. יִבְעֲרוּ לְשׁוֹן שְׁטוּת, וְכֵן וְיִכְסָלוּ:\",1,0],[2,121,10,9,\"מְרֻקָּע. מְרֻדָּד:\",1,0],[2,121,10,10,\"וַה׳ אֱלֹהִים אֱמֶת. לָמָּה? כִּי הוּא אֱלֹהִים חַיִּים וּמֶלֶךְ עוֹלָם, לְכָךְ יָכוֹל לְאַמֵּת דְּבָרָיו. אֲבָל בָּשָׂר וָדָם – אוֹמֵר לַעֲשׂוֹת, וּמֵת אוֹ תָּשַׁשׁ כֹּחוֹ אוֹ יוֹרֵד מִנְּכָסָיו, וְאֵין בְּיָדוֹ לְקַיֵּם (פסיקתא רבתי יד):\",1,0],[2,121,10,11,\"כִּדְנָה תֵאמְרוּן. אִגֶּרֶת הִיא שֶׁשָּׁלַח יִרְמְיָה לִיכָנְיָה וְגָלוּתוֹ בַּגּוֹלָה, לְהָשִׁיב לַכַּשְׂדִּים אֲרָמִית תְּשׁוּבָה, אִם אוֹמְרִין לָהֶם לַעֲבוֹד לַעֲבוֹדָה זָרָה (תנחומא, שופטים יב):\",1,0],[2,121,10,12,\"נָטָה. טינדי״ש בְּלַעַ״ז:\",1,0],[2,121,10,13,\"לְקוֹל תִּתּוֹ. בְּעֵת בֹּא קוֹל שֶׁהוּא נוֹתֵן הֲמוֹן מַיִם בַּשָּׁמַיִם:\",1,0],[2,121,10,13,\"נְשִׂאִים. עֲנָנִים:\",2,0],[2,121,10,13,\"בְּרָקִים. פְלַנְדוֹרִי״שׁ בְּלַעַ״ז:\",3,0],[2,121,10,14,\"נִבְעַר. לְשׁוֹן ״אִישׁ בַּעַר״ (תהילים צב:ז), וְכֵן נִבְעֲרוּ הָרוֹעִים:\",1,0],[2,121,10,14,\"נִסְכּוֹ. לְשׁוֹן ״מַסֵּכָה״ (שמות לב:ד):\",2,0],[2,121,10,15,\"בְּעֵת פְּקֻדָּתָם. כְּשֶׁאֶפְקֹד עֲלֵיהֶם:\",1,0],[2,121,10,17,\"אִסְפִּי מֵאֶרֶץ כִּנְעָתֵךְ. הַחְבִּיאוּ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״כְּנוֹשִׁי מֵאַרְעָא סְחוֹרְתִּיךְ״, כְּמוֹ ״כְּנַעַן בְּיָדוֹ מֹאזְנֵי מִרְמָה״ (הושע יב:ח); וּמְנַחֵם פֵּרֵשׁ כִּנְעָתֵךְ – לְשׁוֹן הַכְנָעָה וְשִׁפְלוּת, וְאִסְפִּי – לְשׁוֹן שְׁחִיָּה: שְׁחִי וְהַשְׁפִּילִי יוֹתֵר מִשִּׁפְלוּת אֶרֶץ אֶת הַכְנָעָתֵךְ, אַתְּ, יְרוּשָׁלַיִם, הַיּוֹשֶׁבֶת עַתָּה בַּמָּצוֹר:\",1,0],[2,121,10,18,\"קוֹלֵעַ. כְּזֶה שֶׁהוּא זוֹרֵק אֶבֶן בַּקֶּלַע:\",1,0],[2,121,10,18,\"לְמַעַן. אֲשֶׁר יִמְצְאוּ שְׂכַר פְּעֻלָּתָם:\",2,0],[2,121,10,19,\"נַחְלָה. לְשׁוֹן חוֹלִי:\",1,0],[2,121,10,19,\"וְאֶשָּׂאֶנּוּ. תִּרְגֵּם יוֹנָתָן: ״וַאֲסוֹבְרַנִיהּ״; אֲשׁוֹפְרִיר״לוֹי בְּלַעַ״ז:\",2,0],[2,121,10,20,\"יְצָאוּנִי. יָצְאוּ מִמֶּנִּי; יְרוּשָׁלַיִם אוֹמֶרֶת כֵּן:\",1,0],[2,121,10,21,\"הָרֹעִים. הַמְּלָכִים:\",1,0],[2,121,10,21,\"לֹא הִשְׂכִּילוּ. לֹא הִצְלִיחוּ בְּמַלְכוּתָם; כְּמוֹ ״בְּכָל אֲשֶׁר יִפְנֶה יַשְׂכִּיל״ (משלי יז:ח, שמואל א יד:מז):\",2,0],[2,121,10,21,\"מַרְעִיתָם. צֹאן מַרְעִיתָם:\",3,0],[2,121,10,23,\"לֹא לָאָדָם דַּרְכּוֹ. כִּי יֵצֶר הָרַע שֶׁבָּרָאתָ בּוֹ מַטֵּהוּ מִן הַדֶּרֶךְ. דָּבָר אַחֵר: יָדַעְתִּי ה׳ כִּי לֹא לָאָדָם דַּרְכּוֹ, אֵין בְּיַד כָּל אָדָם כֹּחַ לְהַצְלִיחַ דַּרְכּוֹ, וְאִם לֹא עַל פִּיךָ, אֵין כֹּחַ בְּיַד אוֹיֵב לְהַחֲרִיב בֵּיתֶךָ:\",1,0],[2,121,10,24,\"אַךְ בְּמִשְׁפָּט. בְּיִסּוּרִין:\",1,0],[2,121,10,24,\"בְּמִשְׁפָּט. יוּשְׁטִיצָ״א בְּלַעַ״ז:\",2,0],[2,121,10,24,\"אַךְ בְּמִשְׁפָּט. תִּרְגֵּם יוֹנָתָן: ״בְּרַם בְּדִין חֲשׁוּךְ״:\",3,0],[2,121,10,24,\"אַל בְּאַפְּךָ. פֶּן תְּהֵא כְלָיָה:\",4,0],[2,121,10,25,\"אָכְלוּ. דְוֹורִירוֹ״נְט בְּלַעַ״ז, וְכֵן וַאֲכָלֻהוּ:\",1,0],[2,121,11,5,\"אָמֵן ה׳. שֶׁיְּהֵא אָרוּר:\",1,0],[2,121,11,7,\"הָעֵד הַעִדֹתִי. לְשׁוֹן הַתְרָאָה:\",1,0],[2,121,11,8,\"וָאָבִיא עֲלֵיהֶם אֶת כָּל דִּבְרֵי הַבְּרִית. הָאָלוֹת הָאֲמוּרוֹת בַּבְּרִית עַל הַדְּבָרִים אֲשֶׁר צִוִּיתִי לַעֲשׂוֹת וְלֹא עָשׂוּ:\",1,0],[2,121,11,12,\"עָרֵי יְהוּדָה. מֵעָרֵי יְהוּדָה:\",1,0],[2,121,11,14,\"רִנָּה וּתְפִלָּה. ״בְּבָעוּ וּבְצָלוּ״ (תרגום יונתן):\",1,0],[2,121,11,15,\"מָה לִידִידִי בְּבֵיתִי. מָה לְעַם סְגֻלָּתִי לָבֹא עוֹד בְּבֵיתִי:\",1,0],[2,121,11,15,\"עֲשׂוֹתָהּ הַמְזִמָּתָה. לַעֲשׂוֹת הִיא מְזִמַּת עֲצַת חֲטָאִים שֶׁלָּהּ:\",2,0],[2,121,11,15,\"הָרַבִּים. שֶׁבָּהֶם:\",3,0],[2,121,11,15,\"וּבְשַׂר קֹדֶשׁ יַעַבְרוּ מֵעָלָיִךְ. אַף הַמִּילָה בִּטְּלוּ מִבְּשָׂרָם, שֶׁעַל יָדָהּ הָיוּ מְקֻדָּשִׁים לִי (מנחות נג:):\",4,0],[2,121,11,15,\"כִּי רָעָתֵכִי אָז תַּעֲלֹזִי. כְּשֶׁאַתֶּם עוֹבְרִים עֲבֵרָה אַתֶּם שְׂמֵחִים:\",5,0],[2,121,11,16,\"לְקוֹל הֲמוּלָּה. לְשׁוֹן שָׁאוֹן עַם רַב שֶׁיָּבֹא עֲלֵיהֶם:\",1,0],[2,121,11,16,\"וְרָעוּ דָּלִיּוֹתָיו. וְרִצְּצוּ אֶת עֲנָפָיו:\",2,0],[2,121,11,18,\"וַה׳ הוֹדִיעַנִי. כָּךְ אָמַר הַנָּבִיא: הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹדִיעַנִי אֶת פּוּרְעָנוּתָם:\",1,0],[2,121,11,19,\"וַאֲנִי כְּכֶבֶשׂ אַלּוּף. אֲשֶׁר יוּבַל לִטְבוֹחַ:\",1,0],[2,121,11,19,\"יוּבַל. לְפִי שֶׁאֲנִי מוֹדִיעָם הָרָעָה, הֵם אוֹמְרִים לְהָרְגֵנִי:\",2,0],[2,121,11,19,\"כְּכֶבֶשׂ אַלּוּף. דּוּנָשׁ וִיהוּדָה בֶּן קוּרִישׁ פֵּתְרוּהוּ: כְּכֶבֶשׂ וּפָר אֲשֶׁר יוּבַל לִטְבוֹחַ. וְאַלּוּף כְּמוֹ ״שְׁגַר אֲלָפֶיךָ״ (דברים כח:ד). וְאַף עַל פִּי שֶׁלֹּא נֶאֱמַר וְאַלּוּף, יֵשׁ לָנוּ כַּיּוֹצֵא בוֹ: ״שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה״ (חבקוק ג:יא); ״כְּסוּס עָגוּר כֵּן אֲצַפְצֵף״ (ישעיהו לח:יד). וּמְנַחֵם פֵּתֵר כֶּבֶשׂ אַלּוּף – כֶּבֶשׂ גָּדוֹל (עיין בתהלים נח בפירוש רש״י); וְיוֹנָתָן מְסַיְּעוֹ, שֶׁתִּרְגֵּם: ״כְּאִימַר בְּחִיר״:\",3,0],[2,121,11,19,\"נַשְׁחִיתָהּ עֵץ בְּלַחְמוֹ. ״נִרְמֵי סְמָא דְּמָוְתָא בְּמִכְלֵיהּ״ (תרגום יונתן):\",4,0],[2,121,11,20,\"אֶרְאֶה נִקְמָתְךָ מֵהֶם. אֶת אַנְשֵׁי עֲנָתוֹת הָיָה מְקַלֵּל:\",1,0],[2,121,11,23,\"אֶל אַנְשֵׁי עֲנָתוֹת. כְּמוֹ עַל אַנְשֵׁי עֲנָתוֹת:\",1,0],[2,121,12,1,\"צַדִּיק אַתָּה ה׳ כִּי אָרִיב אֵלֶיךָ. כְּשֶׁאֶתְוַכֵּחַ עִמְּךָ, יָדַעְתִּי כִּי תִצְדַּק בִּדְבָרֶיךָ, אַךְ חָפֵץ אֲנִי לְדַבֵּר מִשְׁפָּטִים אוֹתָךְ, לְהוֹדִיעֵנִי דַּרְכֶּךָ (שמות לג:יג):\",1,0],[2,121,12,1,\"מַדּוּעַ דֶּרֶךְ רְשָׁעִים צָלֵחָה. שֶׁנָּתַתָּ גְּדֻלָּה לִנְבוּכַדְנֶצַּר הָרָשָׁע וְתַצְלִיחֵהוּ לְהַחֲרִיב בֵּיתֶךָ. דָּבָר אַחֵר: עַל אַנְשֵׁי עֲנָתוֹת הָיָה צוֹעֵק וְקוֹרֵא תִּגָּר (ירמיה יא:כא):\",2,0],[2,121,12,1,\"שָׁלוּ. לְשׁוֹן ״שַׁלְוָה״ (תהלים קכב:ז):\",3,0],[2,121,12,3,\"וְאַתָּה ה׳ יְדַעְתָּנִי. גַּם עַל אַנְשֵׁי עֲנָתוֹת הָעוֹמְדִים עָלַי עָזְרֵנִי, כִּי אַתָּה יְדַעְתָּנִי:\",1,0],[2,121,12,3,\"הַתִּיקֵם כְּצֹאן לְטִבְחָה. נַתְּקֵם מִן הַחַיִּים לָמוּת, דִּישְׁטָאקָאלוּ״שׁ בְּלַעַ״ז, כְּמוֹ ״עַד הַתִּיקְנוּ אוֹתָם מִן הָעִיר״ (יהושע ח:ו):\",2,0],[2,121,12,3,\"וְהַקְדִּישֵׁם. הַזְמִינֵם:\",3,0],[2,121,12,4,\"עַד מָתַי תֶּאֱבַל הָאָרֶץ וְעֵשֶׂב כָּל הַשָּׂדֶה יִיבָשׁ. עַד כָּאן דִּבְרֵי הַנָּבִיא, וְרוּחַ הַקֹּדֶשׁ מְשִׁיבָתוֹ: מֵרָעַת יֹשְׁבֵי בָהּ סָפְתָה בְהֵמוֹת וָעוֹף:\",1,0],[2,121,12,4,\"תֶּאֱבַל. תֶּחֱרַב:\",2,0],[2,121,12,4,\"סָפְתָה. פוֹנִיד״א בְּלַעַ״ז:\",3,0],[2,121,12,4,\"כִּי אָמְרוּ. יוֹשְׁבֵי הָאָרֶץ הַזֹּאת:\",4,0],[2,121,12,4,\"לֹא יִרְאֶה אֶת אַחֲרִיתֵנוּ. אֵין גָּלוּי לְפָנָיו מַה יִהְיֶה בְּסוֹפֵינוּ:\",5,0],[2,121,12,5,\"כִּי אֶת רַגְלִים רַצְתָּה וַיַּלְאוּךָ. קְרוֹבֶיךָ, הַכֹּהֲנִים כְּמוֹתְךָ, וְאַנְשֵׁי עִירְךָ בָּאִים לְהָרְגֶךָ. אֶת רַגְלִים. עִם רַגְלִים, פִּיאוֹנִיד״ש בְּלַעַז:\",1,0],[2,121,12,5,\"וְאֵיךְ תְּתַחֲרֶה אֶת הַסּוּסִים. לָרוּץ אֶת הַסּוּסִים; כְּלוֹמַר: וּמָה קְרוֹבֶיךָ הַכֹּהֲנִים בָּאִים לְהָרְגְךָ, כָּל שֶׁכֵּן שֶׁיָּקוּמוּ לְהוֹרְגְךָ שָׂרֵי יְהוּדָה; וְזֶהוּ קִצְפִּי עֲלֵיהֶם, וְזוֹ הִיא הַצְלָחַת הָאוֹיֵב. וְכֵן תִּרְגֵּם יוֹנָתָן: ״דְּנָא תְּיוּבְתָּא וְגוֹ׳״. וּמִדְרַשׁ רַבּוֹתֵינוּ (סנהדרין צו.): אִם עַל שְׂכַר שָׁלֹשׁ פְּסִיעוֹת שֶׁרָץ נְבוּכַדְנֶצַּר לִכְבוֹדִי בִּימֵי מְרֹדַךְ בַּלְאֲדָן אַתָּה תָּמֵהַּ, שֶׁהִרְבֵּיתִי גְדֻלָּתוֹ כָּל כָּךְ, מָה תִּתְמַהּ עוֹד כְּשֶׁתִּרְאֶה שִׁלּוּם שָׂכָר שֶׁאֲשַׁלֵּם לַצַּדִּיקִים שֶׁרָצוּ לְפָנַי כַּסּוּסִים!\",2,0],[2,121,12,5,\"תְּתַחֲרֶה. אַאֲטִיר״שׁ בְּלַעַ״ז:\",3,0],[2,121,12,5,\"וּבְאֶרֶץ שָׁלוֹם. אֲשֶׁר אַתָּה בּוֹטֵחַ שָׁם הִלְאוּךָ:\",4,0],[2,121,12,5,\"וְאֵיךְ תַּעֲשֶׂה בִּגְאוֹן. שָׂרֵי יְהוּדָה. וּגְאוֹן הַיַּרְדֵּן מָשָׁל הוּא, לְפִי שֶׁהוּא מְקוֹם אֲרָיוֹת וּנְמֵרִים, וְכֵן לִמְּדָנוּ יוֹנָתָן בְּהַרְבֵּה מְקוֹמוֹת; וְכָאן תִּרְגֵּם: ״וְאַכְדֵּין אַתְּ מְדַמֵּי לְקָבֵל חֵיוַת בָּרָא דִּי בְּרוּם יַרְדְּנָא״, וְהִנֵּה ״כְּאַרְיֵה יַעֲלֶה מִגְּאוֹן הַיַּרְדֵּן״ (ירמיה מט:יט; נ:מד) תִּרְגֵּם יוֹנָתָן בִּשְׁתֵּי מְקוֹמוֹת: ״כְּאַרְיֵה דְּסָלִיק מֵרוּם יַרְדְּנָא״:\",5,0],[2,121,12,6,\"קָרְאוּ אַחֲרֶיךָ מָלֵא. קְבוּצַת אֲנָשִׁים:\",1,0],[2,121,12,7,\"יְדִידוּת נַפְשִׁי. עַם סְגֻלָּתִי:\",1,0],[2,121,12,8,\"נָתְנָה עָלַי בְּקוֹלָהּ. עָלְתָה לְפָנַי צַעֲקַת חֲמָסֶיהָ:\",1,0],[2,121,12,9,\"הָעַיִט צָבוּעַ. הַה״א תָּמוּהַּ, לְכָךְ הוּא נָקוּד פַּתָּ״ח: הֲכִי הֵם עוֹף צָבוּעַ, מְגֹאָל בְּדָם, שֶׁשְּׁאָר הָעוֹפוֹת נֶאֱסָפִים עָלָיו? דָּבָר אַחֵר: הָעַיִט צָבוּעַ עוֹף אֶחָד שֶׁהוּא צָבוּעַ וְכָל הָעוֹפוֹת נֶאֱסָפִים עָלָיו לְאוֹכְלוֹ שֶׁשּׂוֹנְאִים אוֹתוֹ:\",1,0],[2,121,12,9,\"הָעַיִט סָבִיב עָלֶיהָ. שֶׁמָּא עוֹף שָׁמַיִם הֵם אֵלּוּ הַחַיָּלוֹת, הַגְּדוּדִים הַקַּלִּים אֲשֶׁר סְבִיבֶיהָ?!\",2,0],[2,121,12,9,\"הֵתָיוּ. בֹּאוּ:\",3,0],[2,121,12,10,\"רוֹעִים רַבִּים. רָאשֵׁי גְיָסוֹת שֶׁל חֵיל נְבוּכַדְנֶצַּר, כְּמוֹ שֶׁנֶּאֱמַר לְמַעְלָה ״אֵלֶיהָ יָבֹאוּ רוֹעִים וְעֶדְרֵיהֶם״ (ירמיה ו:ג):\",1,0],[2,121,12,10,\"בֹּסְסוּ. לְשׁוֹן ״מִרְמָס״ (ישעיה י:ו); וְכֵן ״וְהָיוּ כַגִּבּוֹרִים בּוֹסִים בְּטִיט חוּצוֹת״ (זכריה י:ה):\",2,0],[2,121,12,10,\"חֶלְקַת. קַנְפַנְיָ״א בְּלַעַ״ז:\",3,0],[2,121,12,11,\"אָבְלָה עָלַי. לְפָנַי:\",1,0],[2,121,12,13,\"זָרְעוּ חִטִּים וְקֹצִים קָצָרוּ. הִתְפַּלְלוּ וְלֹא נִתְקַבְּלָה תְּפִלָּתָם. לָמָּה? לְפִי שֶׁלֹּא נָרוּ לָהֶם נִיר תְּשׁוּבָה וּמַעֲשִׂים טוֹבִים, לְכָךְ זָרְעוּ אֶל קוֹצִים (ירמיה ד:ג). סֵפֶר שֶׁנָּקוּד בּוֹ זִרְעוּ, בְּחִירִ״ק הַזַּיִ״ן, שִׁבּוּשׁ הוּא:\",1,0],[2,121,12,13,\"נֶחְלוּ. לְשׁוֹן חוֹלִי, נֶחְלוּ בְּמַכְאוֹבָם וְצָעֲקָתָם לְפָנַי, וְלֹא יוֹעִלוּ:\",2,0],[2,121,12,13,\"מִתְּבוּאֹתֵיכֶם. מִמַּעֲשֵׂיכֶם:\",3,0],[2,121,12,14,\"שְׁכֵנַי הָרָעִים. מִצְרַיִם, עַמּוֹן וּמוֹאָב וְצוֹר וְצִידוֹן, שֶׁהָיוּ שְׁכֵנֵי אֶרֶץ יִשְׂרָאֵל וּמַזִּיקִין אוֹתָם:\",1,0],[2,121,12,15,\"אָשׁוּב וְרִחַמְתִּים. כֻּלָּן לָקוּ סָמוּךְ לְחֻרְבַּן הַבַּיִת, וּבְכֻלָּם נֶאֱמַר ״וְשַׁבְתִּי אֶת שְׁבוּת״ בְּסֵפֶר זֶה (ירמיה כט:יד; ל:ג, יח; לא:כב; לג:ז, יא, כו; מח:מז; מט:ו, לט):\",1,0],[2,121,12,16,\"אִם לָמוֹד יִלְמְדוּ. אִם יַאֲמִינוּ בַּה׳:\",1,0],[2,121,12,16,\"וְנִבְנוּ. לְשׁוֹן בִּנְיָן:\",2,0],[2,121,13,1,\"אֵזוֹר. פּוֹרְצִינְ״ט בְּלַעַ״ז:\",1,0],[2,121,13,1,\"וּבַמַּיִם לֹא תְבִיאֵהוּ. לְכַבְּסוֹ כְּשֶׁיְּהֵא מָלֵא זֵיעָה, כְּדֵי שֶׁיְּמַהֵר לֵירָקֵב:\",2,0],[2,121,13,7,\"לֹא יִצְלַח לַכֹּל. אֵינוֹ רָאוּי לִכְלוּם:\",1,0],[2,121,13,10,\"וִיהִי כָּאֵזוֹר הַזֶּה. גְּאוֹנָם יִהְיֶה כָּאֵזוֹר הַזֶּה הַנִּרְקָב:\",1,0],[2,121,13,12,\"נֵבֶל. כְּלִי חֶרֶס הוּא, וְעָשׂוּי לְהַכְנִיס בּוֹ יָיִן:\",1,0],[2,121,13,14,\"וְנִפַּצְתִּים אִישׁ אֶל אָחִיו. אַכֶּה זֶה עַל זֶה, עַד שֶׁיִּשָּׁבְרוּ חֲתִיכוֹת דַּקּוֹת; כְּמוֹ ״כִּכְלִי יוֹצֵר תְּנַפְּצֵם״ (תהלים ב:ט); ״וְנִפֵּץ אֶת עֹלָלַיִךְ״ (תהלים קלז:ט); וְכֵן כָּל נִפּוּץ שֶׁבַּמִּקְרָא:\",1,0],[2,121,13,14,\"וְהָאָבוֹת וְהַבָּנִים. אֲנַפֵּץ זֶה אֵצֶל זֶה:\",2,0],[2,121,13,16,\"יִתְנַגְּפוּ. יִכָּשְׁלוּ, אצופי״ר בְּלַעַ״ז:\",1,0],[2,121,13,16,\"הָרֵי נָשֶׁף. הָרֵי חֹשֶׁךְ, בְּלֶכְתָּם בַּגּוֹלָה:\",2,0],[2,121,13,16,\"וְשִׁית לַעֲרָפֶל. כְּמוֹ וְלָשִׁית אֶת הָאוֹר לַעֲרָפֶל:\",3,0],[2,121,13,17,\"מִפְּנֵי גֵוָה. מִפְּנֵי גְדוּלָּה שֶׁלָּכֶם שֶׁתִּתְבַּטֵּל. דָּבָר אַחֵר, מִפְּנֵי גַּאֲוָתָהּ שֶׁל מַלְכוּת שָׁמַיִם שֶׁתִּנָּתֵן לֶאֱלִילִים שֶׁל כַּשְׂדִּים (חגיגה ה:):\",1,0],[2,121,13,18,\"לַמֶּלֶךְ וְלַגְּבִירָה. יְהוֹיָכִין וְאִמּוֹ:\",1,0],[2,121,13,18,\"יָרַד מַרְאֲשׁוֹתֵיכֶם. וּושְׁטְרִי קָאיִ״ץ בְּלַעַ״ז, עֲלִיַּתְכֶם; כְּמוֹ שֶׁנֶּאֱמַר ״וַיֵּצֵא אֵלָיו יְהוֹיָכִין הוּא וְאִמּוֹ וַעֲבָדָיו״ (מלכים ב כד:יב), וְכֻלָּם הוֹלִיכָם בַּגּוֹלָה:\",2,0],[2,121,13,19,\"עָרֵי הַנֶּגֶב סֻגְּרוּ. לִפְנֵי הַבָּאִין עֲלֵיהֶם מִן הַצָּפוֹן; עָרֵי אֶרֶץ יִשְׂרָאֵל סְגוּרוֹת מֵאֵימַת נְבוּכַדְנֶצַּר:\",1,0],[2,121,13,19,\"הׇגְלָת שְׁלוֹמִים. לֹא יִלָּחֵם יְהוֹיָכִין, כִּי לְשָׁלוֹם יֵצֵא וְיַגְלֵהוּ (מלכים ב כד:יב). לָשׁוֹן אַחֵר: שְׁלוֹמִים גרדונאמינ״ץ בְּלַעַז, כְּלוֹמַר: תַּשְׁלוּם עֲוֹנָם; וְכֵן תִּרְגֵּם יוֹנָתָן: ״אִיתְקַבְּלוּ תּוֹשְׁלַמַת חוֹבֵיהוֹן״:\",2,0],[2,121,13,20,\"שְׂאוּ עֵינֵיכֶם וּרְאוּ. אֶת הַבָּאִים עֲלֵיכֶם מִצָּפוֹן:\",1,0],[2,121,13,20,\"אַיֵּה הָעֵדֶר נִתַּן לָךְ. אַחַר שֶׁיִּגְלוּ, יֹאמַר לִירוּשָׁלַיִם כֵּן:\",2,0],[2,121,13,21,\"מַה תֹּאמְרִי כִּי יִפְקֹד. הַקָּדוֹשׁ בָּרוּךְ הוּא עָלַיִךְ:\",1,0],[2,121,13,21,\"לִמַּדְתְּ אוֹתָם עָלַיִךְ אַלֻּפִים לְרֹאשׁ. שְׁלַחְתֶּם אֲלֵיהֶם מַלְאָכִים לַכַּשְׂדִּיִּים לְהָבִיא מִשָּׁם אֱלִילִים שֶׁלָּהֶם לְעָבְדָם, כְּמוֹ שֶׁנֶּאֱמַר בִּיחֶזְקֵאל (יחזקאל כג:טז) ״וַתַּעְגְּבָה עֲלֵיהֶם לְמַרְאֵה עֵינֶיהָ וַתִּשְׁלַח מַלְאָכִים אֲלֵיהֶם כַּשְׂדִּימָה״. דָּבָר אַחֵר: לִמַּדְתְּ אוֹתָם עָלַיִךְ אַלֻּפִים – חִזְקִיָּהוּ שֶׁהֶרְאָה לִשְׁלוּחֵי מְרֹדַךְ בַּלְאֲדָן אֶת כָּל בֵּית נְכָאתָה (ישעיהו לט:ב):\",2,0],[2,121,13,22,\"שׁוּלַיִךְ. שִׁפּוּלֵי הַבְּגָדִים, טִי״שׁ אוֹרְלָ״שׁ בְּלַעַ״ז; כְּשֶׁמַּפְשִׁיטִין אֶת הָאִשָּׁה דֶּרֶךְ בִּזָּיוֹן, מְהַפְּכִין חֲלוּקָהּ מִלְּמַטָּה לְמַעְלָה:\",1,0],[2,121,13,22,\"נֶחְמְסוּ עֲקֵבָיִךְ. נִגְזְרוּ דְּרָכַיִךְ. נֶחְמְסוּ כְּמוֹ ״וַיַּחְמֹס כַּגַּן שֻׂכּוֹ״ (איכה ב:ו):\",2,0],[2,121,13,22,\"עֲקֵבָיִךְ. טְרַצִי״שׁ בְּלַעַ״ז; פָּסְקוּ עוֹבְרֵי דְרָכִים:\",3,0],[2,121,13,23,\"כּוּשִׁי. שֵׁם אָדָם שָׁחוֹר, וְקוֹרִין מָאוֹר בְּלַעַ״ז:\",1,0],[2,121,13,23,\"וְנָמֵר. לִיאַפַּרְ״ט בְּלַעַ״ז:\",2,0],[2,121,13,23,\"חֲבַרְבֻּרֹתָיו. הַנָּמֵר מְנֻמָּר הוּא, וְהֵם הַחֲבַרְבֻּרוֹת, טָק״שׁ בְּלַעַ״ז; וְאִי אֶפְשָׁר שֶׁיֵּהָפְכוּ:\",3,0],[2,121,13,23,\"הָרֵעַ. כְּמוֹ ״לְהָרֵעַ״ (תהלים לז:ח):\",4,0],[2,121,13,25,\"מְנָת מִדַּיִךְ. חֵלֶק מִדּוֹתַיִךְ, מִדָּה כְּנֶגֶד מִדָּה:\",1,0],[2,121,13,26,\"חָשַׂפְתִּי שׁוּלַיִךְ. גִּלִּיתִי שִׁפּוּלֵי בְגָדַיִךְ, לְהָפְכָם עַל פָּנָיִךְ:\",1,0],[2,121,13,27,\"מִצְהֲלוֹתַיִךְ. כְּצַהֲלַת סוּסִים נוֹאֲפִים (ירמיה ה:ח):\",1,0],[2,121,13,27,\"אַחֲרֵי מָתַי. תִּטְהֲרִי עֹד:\",2,0],[2,121,14,1,\"דִּבְרֵי הַבַּצָּרוֹת. שֶׁיָּבִיא עֲלֵיהֶם רָעָב. וּמְנַחֵם חִבְּרוֹ לְשׁוֹן מִבְצָר, כְּמוֹ ״וּמִבְצַר מִשְׂגַּב חוֹמוֹתֶיךָ״ (ישעיהו כה:יב):\",1,0],[2,121,14,2,\"וּשְׁעָרֶיהָ. עָרֶיהָ:\",1,0],[2,121,14,2,\"וְצִוְחַת יְרוּשָׁלִַם. צַעֲקַת יְרוּשָׁלַיִם, כְּמוֹ ״מֵרֹאשׁ הָרִים יִצְוָחוּ״ (ישעיה מב:יא):\",2,0],[2,121,14,3,\"עַל גֵּבִים. בּוֹרוֹת שֶׁהַמַּיִם מִתְכַּנְּסִים בָּהֶם:\",1,0],[2,121,14,3,\"שָׁבוּ כְלֵיהֶם רֵיקָם. שֶׁלֹּא יָרַד מָטָר:\",2,0],[2,121,14,3,\"וְחָפוּ. לְשׁוֹן כִּסּוּי:\",3,0],[2,121,14,4,\"אִכָּרִים. בּוֹבִיֵּיר״שׁ בְּלַעַ״ז:\",1,0],[2,121,14,5,\"יָלְדָה וְעָזוֹב. אֶת וְלָדָהּ, לְבַקֵּשׁ לָהּ מִרְעֶה:\",1,0],[2,121,14,6,\"עַל שְׁפָיִים. יִבְלֵי מַיִם, רִיבֵיירְ״שׁ בְּלַעַ״ז:\",1,0],[2,121,14,7,\"עָנוּ בָנוּ. הֵעִידוּ בָּנוּ:\",1,0],[2,121,14,7,\"עֲשֵׂה לְמַעַן שְׁמֶךָ. עֲשֵׂה מַה שֶּׁתַּעֲשֶׂה עִמָּנוּ לְמַעַן שֵׁם גָּדוֹל שֶׁיֵּצֵא לְךָ, שֶׁאַתָּה מוֹשֵׁל בַּכֹּל, וַאֲנַחְנוּ עַמְּךָ וְצֹאן מַרְעִיתֶךָ (תהלים עט:יג), וְלֹא נָאֶה שֶׁתִּתֵּן שֵׁם נִצְחוֹנְךָ לָאֱלִילִים. וּמִדְרַשׁ אַגָּדָה יֵשׁ (ירושלמי תענית ב:ו סה,ד): לְמַעַן שְׁמֶךָ וְכוּ׳:\",2,0],[2,121,14,8,\"מִקְוֵה. תּוֹחֶלֶת:\",1,0],[2,121,14,9,\"נִדְהָם. רַקְרוּ״ץ בְּלַעַ״ז, מוֹשֵׁךְ יָדוֹ מִן הַמִּלְחָמָה; וְיֵשׁ אוֹמְרִים: רַקְרִיאַנְ״ץ בְּלַעַ״ז:\",1,0],[2,121,14,9,\"וְשִׁמְךָ עָלֵינוּ נִקְרָא. לְפִיכָךְ אֵין כְּבוֹדְךָ בְּכָךְ:\",2,0],[2,121,14,9,\"תַּנִּחֵנוּ. פֵּירוּשׁוֹ כְּמוֹ ״תַּעַזְבֵנוּ״ (איכה ה:כ):\",3,0],[2,121,14,10,\"כֵּן אָהֲבוּ לָנוּעַ. כֵּן, כְּמָה שֶׁגָּזַרְתִּי עֲלֵיהֶם גּוֹלָה בְּמִצְרַיִם וּבָבֶל, אָהֲבוּ שָׁם לִהְיוֹת גּוֹלִים, לַעֲבֹד אֱלִילֵיהֶם הָרְחוֹקוֹת:\",1,0],[2,121,14,14,\"וֶאֱלִיל. לְשׁוֹן אַל, דָּבָר שֶׁאֵינוֹ:\",1,0],[2,121,14,17,\"נַחְלָה מְאֹד. לְשׁוֹן ״חֳלִי״ (ירמיה ו:ז):\",1,0],[2,121,14,18,\"סָחֲרוּ. סָבְבוּ לְבַקֵּשׁ הַצָּלָה:\",1,0],[2,121,14,18,\"אֶל אֶרֶץ וְלֹא יָדָעוּ. אֶל אֶרֶץ אַחֶרֶת, וְלֹא הָיוּ יוֹדְעִין בָּהּ עַד הֵנָּה:\",2,0],[2,121,14,19,\"אִם בְּצִיּוֹן גָּעֲלָה נַפְשֶׁךָ. עַל מְנָת שֶׁלֹּא לָשׁוּב עָלֶיהָ? כִּי אִם דַּעְתְּךָ לָשׁוּב, מַדּוּעַ הִכִּיתָ בְּאֵין מַרְפֵּא? (פסיקתא רבתי לא)\",1,0],[2,121,14,21,\"לְמַעַן שִׁמְךָ. שֶׁנִּקְרֵאתָ ״רַחוּם״ (שמות לד:ו):\",1,0],[2,121,14,21,\"כִּסֵּא כְבוֹדֶךָ. בֵּית הַמִּקְדָּשׁ (פסחים ה.), וּמִדְרַשׁ אַגָּדָה (תנחומא, במדבר כב): יִשְׂרָאֵל הַחֲקוּקִים בְּכִסֵּא כְבוֹדֶךָ:\",2,0],[2,121,14,22,\"וְאִם הַשָּׁמַיִם יִתְּנוּ רְבִיבִים. מֵאֲלֵיהֶם, אִם לֹא עַל פִּיךָ? בִּתְמִיהָּ. כָּל תְּמִיהָה הַכְּפוּלָה, הָרִאשׁוֹנָה בְּה״א וְהַשְּׁנִיָּה בְּאִם, כְּגוֹן: ״הַבְּמַחֲנִים אִם בְּמִבְצָרִים״ (במדבר יג:יט); ״הֲטוֹבָה הִיא אִם רָעָה״ (במדבר יג:יט); ״הֲמָאוֹס מָאַסְתָּ אִם בְּצִיּוֹן גָּעֲלָה נַפְשֶׁךָ״ (ירמיהו יד:יט). אַף כָּאן: הֲיֵשׁ בְּהַבְלֵי הַגּוֹיִם… וְאִם הַשָּׁמַיִם:\",1,0],[2,121,15,1,\"מֹשֶׁה וּשְׁמוּאֵל. שְׁנֵיהֶם נִזְקְקוּ לְבַקֵּשׁ רַחֲמִים עַל יִשְׂרָאֵל, וּמִתְּחִלָּה הֶחֱזִירוּם לְמוּטָב, וְאַחַר כָּךְ הִתְפַּלְלוּ עֲלֵיהֶם; וְלֹא עָלָה בְלִבָּם לְהָשִׁיב אַפִּי עַד שֶׁהֶחֱזִירוּם לְמוּטָב. מֹשֶׁה אָמַר: ״שִׂימוּ אִישׁ חַרְבּוֹ וְגוֹ׳״ (שמות לב:כז), ״וַיִּזֶר עַל פְּנֵי הַמַּיִם וְגוֹ׳״ (שמות לב:כ), וְאַחַר כָּךְ ״אֶעֱלֶה אֶל ה׳ אוּלַי אֲכַפְּרָה״ (שמות לב:ל); שְׁמוּאֵל בַּמִּצְפָּה: ״וַיָּסִירוּ בְנֵי יִשְׂרָאֵל אֶת הַבְּעָלִים וְגוֹ׳״ (שמואל א ז:ד), וְאַחַר כָּךְ ״קִבְצוּ אֶת יִשְׂרָאֵל הַמִּצְפָּתָה וְאֶתְפַּלֵּל עֲלֵיכֶם״ (שמואל א ז:ה). אַתָּה אֵינְךָ יָכוֹל לַהֲשִׁיבָם אֵלַי, לְכָךְ אַל תִּתְפַּלֵּל עֲלֵיהֶם (ירמיה ז:טז):\",1,0],[2,121,15,1,\"נַפְשִׁי. רְצוֹנִי:\",2,0],[2,121,15,2,\"אֲשֶׁר לַמָּוֶת וְגוֹ׳. כָּל הַמְאֻחָר בַּפָּסוּק קָשֶׁה מֵחֲבֵירוֹ. חֶרֶב קָשֶׁה מִמָּוֶת, מִיתַת חֶרֶב מְנֻוֶּלֶת וּמִיתָה עַל מִטָּתוֹ אֵינָהּ מְנֻוֶּלֶת, וְכֵן הוּא אוֹמֵר (תהלים קטז:טו) ״יָקָר בְּעֵינֵי ה׳ הַמָּוְתָה לַחֲסִידָיו״. רָעָב קָשֶׁה מֵחֶרֶב, שֶׁזֶּה מִצְטַעֵר וְזֶה אֵינוֹ מִצְטַעֵר, וְכֵן הוּא אוֹמֵר ״טוֹבִים הָיוּ חַלְלֵי חֶרֶב מֵחַלְלֵי רָעָב״ (איכה ד:ט). שְׁבִי כֻּלְּהוּ אִיתַנְהוּ בְּגַוֵּהּ (בבא בתרא ח:):\",1,0],[2,121,15,3,\"וּפָקַדְתִּי. לְשׁוֹן מִנּוּי וּפְקִידוּת:\",1,0],[2,121,15,3,\"לִסְחֹב. לִגְרֹר, וְכֵן ״אִם לֹא יִסְחָבוּם״ (ירמיה מט:כ):\",2,0],[2,121,15,4,\"לְזַעֲוָה. מִגִּזְרַת ״לֹא קָם וְלֹא זָע״ (אסתר ה:ט); וּכְמוֹהוּ גַּאֲוָה מִגִּזְרַת ״גֵּא מְאֹד״ (ישעיה טז:ו):\",1,0],[2,121,15,4,\"לְכָל מַמְלְכוֹת הָאָרֶץ. כָּל הַשּׁוֹמֵעַ רָעָה שֶׁבָּאָה עֲלֵיהֶם, יָזוּעַ:\",2,0],[2,121,15,5,\"יָנוּד. יְקוֹנֵן:\",1,0],[2,121,15,5,\"וּמִי יָסוּר. אֵלֶיךָ, לִנְטוֹת מִדַּרְכּוֹ אֵלַיִךְ, לִשְׁאֹל לָךְ לְשָׁלוֹם:\",2,0],[2,121,15,6,\"נִלְאֵיתִי הִנָּחֵם. כַּמָּה פְּעָמִים חָשַׁבְתִּי לְהַשְׁחִית וְנִחַמְתִּי עַל הָרָעָה; עַתָּה נִלְאֵיתִי הִנָּחֵם. הִנָּחֵם – רְפוֹרְפִינְשְׁ״ר בְּלַעַ״ז:\",1,0],[2,121,15,7,\"בַּמִּזְרֶה. נָפָה שֶׁקּוֹרִין וו״ן בְּלַעַ״ז, כָּזֶה שֶׁהוּא זוֹרֶה שְׂעוֹרִין; שֶׁלֹּא יְהוּ כֻּלָּן גּוֹלִין לְמָקוֹם אֶחָד:\",1,0],[2,121,15,8,\"עָצְמוּ לִי. רַבּוּ לְפָנַי אַלְמְנוֹתָו:\",1,0],[2,121,15,8,\"עַל אֵם. עַל יְרוּשָׁלַיִם שֶׁהָיְתָה עִיר וָאֵם בְּיִשְׂרָאֵל (שמואל ב כ:יט):\",2,0],[2,121,15,8,\"בַּצׇּהֳרָיִם. הַכֹּל יְהֵא גָּלוּי לְפָנָיו, כָּל גִּנְזֵי מַטְמוֹנָם:\",3,0],[2,121,15,8,\"הִפַּלְתִּי עָלֶיהָ פִּתְאֹם עִיר. הִשְׁכַּנְתִּי עֲלֵיהֶם פִּתְאֹם גְּיָסוֹת שֶׁל עִיר וּבֶהָלוֹת רַבּוֹת. וְיֵשׁ פּוֹתְרִים עִיר – לְשׁוֹן שׂוֹנֵא, כְּמוֹ ״וַיְהִי עָרֶיךָ״ (שמואל א כח:טז); ״וּפִשְׁרֵיהּ לְעָרָךְ״ (דניאל ד:טז):\",4,0],[2,121,15,9,\"אֻמְלְלָה יוֹלֶדֶת הַשִּׁבְעָה. שׁוֹמְרוֹן וּכְנֵסִיָּה שֶׁל עֲשֶׂרֶת שְׁבָטִים, שֶׁעָמְדוּ מֵהֶם שֶׁבַע מִשְׁפָּחוֹת (גיטין פח.), כְּבָר אֻמְלְלָה וְגָלְתָה:\",1,0],[2,121,15,9,\"וּשְׁאֵרִיתָם. אֵלּוּ יְהוּדָה וּקְצָת בִּנְיָמִין שֶׁנִּשְׁתַּיְּרוּ בְּיִשְׂרָאֵל, לַחֶרֶב אֶתֵּן. אֵלּוּ הֵן שֶׁבַע מִשְׁפָּחוֹת: יָרָבְעָם בֶּן נְבָט וּבֵיתוֹ, בַּעְשָׁא וּבֵיתוֹ, עָמְרִי וּבֵיתוֹ, יֵהוּא וּבֵיתוֹ, מְנַחֵם וּבֵיתוֹ, פֶּקַח וּבֵיתוֹ, הוֹשֵׁעַ וּבֵיתוֹ:\",2,0],[2,121,15,9,\"נָפְחָה נַפְשָׁהּ. לְשׁוֹן דָּאֲבָה נַפְשָׁהּ, מְתַרְגְּמִינָן ״וְדַאֲבוֹן נֶפֶשׁ״ (דברים כח:סה) ״וּמַפְּחָן נְפָשׁ״:\",3,0],[2,121,15,9,\"בְּעוֹד יוֹמָם. בְּלֹא זְמַנָּם מִהֲרוּ לִיפּוֹל. כָּךְ נִדְרַשׁ בְּמַסֶּכֶת גִּיטִּין (גיטין פח.). וּבְמִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, בובר ויצא יד) דָּרְשׁוּ כְּלַפֵּי יְרוּשָׁלַיִם, וּמוֹנֶה שִׁבְעָה רְשָׁעִים: יְהוֹרָם, יְהוֹאָשׁ, אָחָז, מְנַשֶּׁה, אָמוֹן, יְהוֹיָקִים, צִדְקִיָּהוּ. אַךְ יֵשׁ לִמְנוֹת עוֹד: רְחַבְעָם, אֲבִיָּה, אֲמַצְיָה, אֲחַזְיָה:\",4,0],[2,121,15,9,\"וְחָפֵרָה. לְשׁוֹן בּוֹשֶׁת:\",5,0],[2,121,15,10,\"אוֹי לִי אִמִּי. יִרְמְיָה הָיָה מִתְאוֹנֵן עַל עַצְמוֹ, שֶׁהָיוּ שׂוֹנְאִין אוֹתוֹ בְּנֵי עִירוֹ עַל דִּבְרֵי תוֹכְחוֹתָיו:\",1,0],[2,121,15,10,\"וְאִישׁ מָדוֹן. אִישׁ מְרִיבָה, כְּמוֹ ״לֹא יָדוֹן רוּחִי״ (בראשית ו:ג):\",2,0],[2,121,15,10,\"לֹא נָשִׁיתִי. כְּמוֹ ״לֹא תִהְיֶה לוֹ כְּנֹשֶׁה״ (שמות כב:כד):\",3,0],[2,121,15,10,\"כֻּלֹּה מְקַלְלַוְנִי. אֵינִי רָב עִמָּהֶם עַל עִסְקֵי מָמוֹן שֶׁיֵּשׁ לִי עֲלֵיהֶם וְלֹא לָהֶם עָלַי, וַהֲרֵי כָּל הָעָם מְקַלְלַנִי:\",4,0],[2,121,15,11,\"שֵׁרִיתִיךָ. הִשְׁאַרְתִּיךָ, לְשׁוֹן ״שְׁאֵרִית״ (בראשית מה:ז). וְכֵן פִּתְרוֹ מְנַחֵם. אֲבָל דּוֹנָשׁ פָּתַר אוֹתוֹ לְשׁוֹן הַתָּרָה, וְשֵׁרִיתִיךָ כְּמוֹ ״מְשָׁרֵי קִטְרִין״ (דניאל ה:יב). וּפִתְרוֹן שֵׁרִיתִיךָ כֵּן הוּא, שֶׁנֶּאֱמַר ״הִנֵּה פְתַחְתִּיךָ הַיּוֹם מִן הָאֲזִקִּים״ (ירמיה מ:ד); כְּלוֹמַר: בַּיּוֹם אֲשֶׁר הֵקִים ה׳ אֶת דְּבָרוֹ נֶאֱמַר לוֹ: ״וְעַתָּה הִנֵּה פְתַחְתִּיךָ הַיּוֹם מִן הָאֲזִקִּים אֲשֶׁר עַל יָדֶיךָ, אִם טוֹב בְּעֵינֶיךָ לָבוֹא אִתִּי בָבֶלָה״ (ירמיה מ:ד). וְגַם יִשְׂרָאֵל בִּקְּשׁוּ מִמֶּנּוּ שֶׁיִּתְפַּלֵּל בִּשְׁבִילָם, כַּאֲשֶׁר נֶאֱמַר לוֹ: ״הִתְפַּלֵּל בַּעֲדֵנוּ אֶל ה׳ אֱלֹהֵינוּ… כִּי נִשְׁאַרְנוּ מְעַט מֵהַרְבֵּה״ (ירמיה מב:ב):\",1,0],[2,121,15,11,\"אִם לֹא. לְשׁוֹן שְׁבוּעָה:\",2,0],[2,121,15,11,\"הִפְגַּעְתִּי בְךָ בְּעֵת רָעָה. אֶת הָאוֹיֵב, כְּשֶׁתָּבֹא עֲלֵיהֶם הָרָעָה, יִפְגְּעוּ בְךָ שֶׁתְּבַקֵּשׁ רַחֲמִים עֲלֵיהֶם; כְּגוֹן צִדְקִיָּה, אָמַר לוֹ: ״דְּרָשׁ נָא בַּעֲדֵנוּ אֶת ה׳ וְגוֹ׳״ (ירמיה כא:ב). דָּבָר אַחֵר: נְבוּזַרְאֲדָן יְבַקֵּשׁ מֵאִתְּךָ: ״אִם טוֹב בְּעֵינֶיךָ לָבֹא אִתִּי בָּבֶלָה״ (ירמיה מ:ד):\",3,0],[2,121,15,12,\"הֲיָרֹעַ בַּרְזֶל בַּרְזֶל מִצָּפוֹן. אוֹמֵר אֲנִי: בַּרְזֶל הַבָּא מִצָּפוֹן קָשֶׁה מִשְּׁאָר בַּרְזֶל. וְכֵן פִּתְרוֹנוֹ: הֵם נִמְשְׁלוּ לְבַרְזֶל: ״הוֹלְכֵי רָכִיל נְחֹשֶׁת וּבַרְזֶל״ (ירמיה ו:כח), וּבְיִרְמְיָה נֶאֱמַר: ״נְתַתִּיךָ לְעַמּוּד בַּרְזֶל וּלְחוֹמַת נְחֹשֶׁת״ (ירמיה א:יח) – וְשֶׁלּוֹ חָזָק מִשֶּׁלָּהֶם, כִּי נְבוּכַדְנֶצַּר מִצָּפוֹן יָבֹא כִּדְבָרָיו עֲלֵיהֶם:\",1,0],[2,121,15,12,\"הֲיָרֹעַ. הֲיְרוֹצֵץ בַּרְזֶל שֶׁלָּהֶם אֶת שֶׁלְּךָ? דָּבָר אַחֵר: הֲיְרוֹצֵץ פַּרְעֹה הַבָּא בְּעֶזְרַתְכֶם, שֶׁהוּא קָשֶׁה כְּבַרְזֶל, אֶת נְבוּכַדְנֶצַּר, שֶׁהוּא בַּרְזֶל הַבָּא מִצָּפוֹן וּנְחֹשֶׁת? וְתַרְגּוּם יוֹנָתָן נוֹטֶה לְצַד זֶה:\",2,0],[2,121,15,13,\"חֵילְךָ. לְשׁוֹן מָמוֹן (ראה דברים ח:יז):\",1,0],[2,121,15,13,\"וְאוֹצְרוֹתֶיךָ. לְיִשְׂרָאֵל הוּא אוֹמֵר:\",2,0],[2,121,15,13,\"וּבְכָל חַטֹּאותֶיךָ. וּלְמַעַן כָּל חַטֹּאותֶיךָ תְּהִי זֹאת לָךְ:\",3,0],[2,121,15,13,\"וּבְכָל גְּבוּלֶיךָ. אֲשֶׁר הֶעֱמַדְתָּ אֱלִילִים בְּכֻלָּן:\",4,0],[2,121,15,15,\"אַל לְאֶרֶךְ אַפְּךָ תִּקָּחֵנִי. תַּרְגּוּם יוֹנָתָן: ״לָא תִּתֵּן אַרְכָּא לְעוֹלְבָנִי״ – אַל תִּקַּח אֶת רִיבִי לְהַנִּיחוֹ לְאֹרֶךְ אַפְּךָ, אֶלָּא מַהֵר וְהִנָּקֶם לִי:\",1,0],[2,121,15,15,\"שְׂאֵתִי. כְּמוֹ סָבַלְתִּי:\",2,0],[2,121,15,15,\"עָלֶיךָ. בִּשְׁבִילְךָ:\",3,0],[2,121,15,16,\"נִמְצְאוּ דְבָרֶיךָ וָאֹכְלֵם. לְתַאֲוָה מִתְּחִלָּה, וְהָיוּ לְשָׂשׂוֹן, כִּי דִּמִּיתִי שֶׁיִּשְׁמְעוּ אֵלַי עַתָּה:\",1,0],[2,121,15,17,\"מִפְּנֵי יָדְךָ. מִפְּנֵי נְבוּאָה הַבָּאָה לִי מֵאִתְּךָ:\",1,0],[2,121,15,17,\"יָשַׁבְתִּי. יְחִידִי וּמִשְׁתּוֹמֵם בַּאֲבֵילוּת, כִּי נְבוּאַת זַעַם מִלֵּאתָנִי, בְּחֻרְבַּן בֵּיתֶךָ:\",2,0],[2,121,15,18,\"אֲנוּשָׁה. חוֹלָה; כְּמוֹ ״וַיֵּאָנַשׁ״ (שמואל ב יב:טו) – וַיֶּחֱלֶה; בִּבְנָהּ שֶׁל בַּת שֶׁבַע:\",1,0],[2,121,15,18,\"הָיוֹ תִהְיֶה לִי. אַתָּה הוֹוֶה לִי כְּמוֹ אַכְזָב. כְּאָדָם שֶׁמִּבְטָחוֹ נִפְסָק מִמֶּנּוּ, שֶׁאַתָּה מַנִּיחֵנִי לְהִצְטַעֵר בְּיָדָם. אַכְזָב מָקוֹר פּוֹסֵק, פייליינ״ץ בְּלַעַז:\",2,0],[2,121,15,18,\"מַיִם לֹא נֶאֱמָנוּ. לִסְמֹךְ עֲלֵיהֶם:\",3,0],[2,121,15,19,\"לָכֵן. בַּעֲבוּר שֶׁאֲנִי סוֹבֵל הַצָּרוֹת הָאֵלֶּה:\",1,0],[2,121,15,19,\"כֹּה אָמַר ה׳. לִי:\",2,0],[2,121,15,19,\"אִם תָּשׁוּב. אַתָּה יִשְׂרָאֵל עַל יְדֵי וַאֲשִׁיבְךָ אֲנִי אֵלָיו, אָמַר לִי: לְפָנַי תַּעֲמֹד:\",3,0],[2,121,15,19,\"וְאִם תּוֹצִיא יָקָר מִזּוֹלֵל. אִם תּוֹצִיא אָדָם הָגוּן מֵאָדָם רָשָׁע, שֶׁתַּחֲזִירֶנּוּ לְמוּטָב:\",4,0],[2,121,15,19,\"כְּפִי תִהְיֶה. שֶׁאֲנִי גּוֹזֵר גְּזֵירָה וְאַתָּה מְבַטְּלָהּ (בבא מציעא פה.):\",5,0],[2,121,15,19,\"יָשׁוּבוּ הֵמָּה אֵלֶיךָ וְאַתָּה לֹא תָשׁוּב אֲלֵיהֶם. ״יְתוּבוּן אִינּוּן לְפִתְגָּמָךְ וְאַתְּ לָא תְּתוּב לְמִטְעֵי בַּתְרֵיהוֹן״ (תרגום יונתן):\",6,0],[2,121,16,5,\"בֵּית מַרְזֵחַ. מִשְׁתֶּה; בְּסִפְרֵי בְּפָרָשַׁת בֵּית פְּעוֹר(ספרי פיסקא קלא) רָאִיתִי: חָזְרוּ לַעֲשׂוֹת לָהֶם מַרְזֵיחִין; אֲבָל רַבּוֹתֵינוּ פֵּרְשׁוּ (כתובות סט:) מַרְזֵחַ – אֵבֶל:\",1,0],[2,121,16,5,\"תָּנֹד. תְּקוֹנֵן:\",2,0],[2,121,16,5,\"כִּי אָסַפְתִּי אֶת שְׁלוֹמִי וגו׳. כְּשֶׁהָיָה אַבְרָהָם אֲבִיהֶם עוֹשֶׂה צְדָקָה וּמִשְׁפָּט (בראשית יח:יט), נָתַתִּי לְזַרְעוֹ חֶסֶד וְרַחֲמִים: ״וְשָׁמַר ה׳ אֱלֹהֶיךָ לְךָ וגו׳״ (דברים ז:יב), ״וְנָתַן לְךָ רַחֲמִים״ (דברים יג:יח). הֵם הָפְכוּ לַלַּעֲנָה מִשְׁפָּט וּצְדָקָה לָאָרֶץ הִנִּיחוּ (עמוס ה:ז), אַף אֲנִי חָזַרְתִּי וְאָסַפְתִּי אֵלַי אֶת חַסְדִּי וְאֶת רַחֲמִי:\",3,0],[2,121,16,5,\"אָסַפְתִּי. אטואי״ש בְּלַעַ״ז, כְּמוֹ ״אָסַף אֱלֹהִים אֶת חֶרְפָּתִי״ (בראשית ל:כג):\",4,0],[2,121,16,6,\"וּמֵתוּ גְדוֹלִים וּקְטַנִּים. וְאַחַר שֶׁהַכֹּל מֵתִים, מַה לְּךָ לִסְפּוֹד?\",1,0],[2,121,16,6,\"וְלֹא יִתְגֹּדַד וְלֹא יִקָּרֵחַ לָהֶם. דֶּרֶךְ הָאֲבֵלִים לְהִתְגּוֹדֵד וְלִשְׂרֹט בְּשָׂרָם וְלִקְרוֹחַ קָרְחָה בְּרֹאשָׁם; וּמִכָּל מָקוֹם, לְיִשְׂרָאֵל אָסוּר (ויקרא יט:כח; דברים יד:א), וְלֹא הִזְכִּירוֹ כָּאן אֶלָּא לְדוּגְמַת אֵבֶל:\",2,0],[2,121,16,7,\"וְלֹא יִפְרְסוּ. לְשׁוֹן שְׁבִירָה, כְּמוֹ ״מְנֵא מְנֵא תְּקֵל וּפַרְסִין״ (דניאל ה:כה); שֶׁמַּבְרִין אֶת הָאֲבֵלִים בָּרְחָבָה וּפוֹרְסִין לָהֶם בִּרְכַּת הַמּוֹצִיא. ״כִּי הוּא יְבָרֵךְ הַזֶּבַח״ (שמואל א ט:יג) – תִּרְגֵּם יוֹנָתָן: ״אֲרֵי הוּא פָּרִיס עַל מְזוֹנָא״:\",1,0],[2,121,16,7,\"וְלֹא יַשְׁקוּ אוֹתָם וְגוֹ׳. הֲרֵי טַעַם לָמָּה שֶׁאָמַרְתִּי: אַל תֵּלֵךְ לִסְפּוֹד:\",2,0],[2,121,16,8,\"וּבֵית מִשְׁתֶּה. אֲשֶׁר אָמַרְתִּי לְךָ לְמַעְלָה לֹא תָבוֹא, זֶה הַטַּעַם: הִנְנִי מַשְׁבִּית מִן הַמָּקוֹם הַזֶּה וְגוֹ׳:\",1,0],[2,121,16,13,\"וַעֲבַדְתֶּם שָׁם אֶת אֱלֹהִים אֲחֵרִים. תִּרְגֵּם יוֹנָתָן: ״וְתִפְלְחוּן תַּמָּן לְעַמְמַיָּא פָּלְחֵי טָעֲוָותָא״:\",1,0],[2,121,16,14,\"לָכֵן. לְשׁוֹן שְׁבוּעָה, אַף עַל פִּי שֶׁבְּגַדְתֶּם בִּי, שְׁבוּעָה הִיא בְּיָדִי שֶׁאֶגְאוֹל אֶתְכֶם:\",1,0],[2,121,16,14,\"וְלֹא יֵאָמֵר עוֹד וגו׳. רַבּוֹתֵינוּ דָּרְשׁוּ (ברכות יב:) לֹא שֶׁתֵּעָקֵר יְצִיאַת מִצְרַיִם מִמְּקוֹמָהּ, אֶלָּא גְּאֻלָּה אַחֲרוֹנָה עִקָּר וִיצִיאַת מִצְרַיִם טָפֵל לָהּ:\",2,0],[2,121,16,16,\"וְדִיגוּם. מָה הַדַּיָּג שׁוֹלְהוּ מִתּוֹךְ מְקוֹם גִּדּוּלוֹ, אַף אֵלּוּ יִלְכְּדוּ אוֹתָם בְּתוֹךְ הָעִיר; וּמָה עִסְקוֹ שֶׁל דָּג, מִשֶּׁנִּלְכַּד הוּא מֵת, כָּךְ אָבִיא עֲלֵיהֶם הוֹרְגִים; וְאַחֲרֵי כֵן אֶשְׁלַח צַיָּדִים לַנִּשְׁאָרִים וְלַבּוֹרְחִים מִן הַחֶרֶב עַל הַהָרִים וְהַגְּבָעוֹת, וְצָדוּם – לְהַגְלוֹתָם בַּשֶּׁבִי:\",1,0],[2,121,16,18,\"מִשְׁנֵה עֲוֺנָם. אֶת שֶׁשָּׁנוּ עַל עֲוֹנָם לַעֲשׂוֹת עֲוֹנוֹת אֲבוֹתֵיהֶם; וְיוֹנָתָן תִּרְגֵּם כֵּן: ״וַאֲשִׁלֵּים לְתִנְיָינִין כְּקַדְמָאִין עַל חַד תְּרֵין״:\",1,0],[2,121,16,19,\"ה׳ עֻזִּי וּמָעֻזִּי וּמְנוּסִי. אַנְטִיפוֹיְימַאנְ״ט בְּלַעַ״ז, וּמְנַחֵם חִבְּרוֹ לְשׁוֹן פֶּלֶא, כְּמוֹ ״נָתַתָּ לִּירֵאֶיךָ נֵּס לְהִתְנוֹסֵס״ (תהלים ס:ו), וְכֵן ״ה׳ נִסִּי״ (שמות יז:טו). וְדוֹנָשׁ פָּתַר אוֹתוֹ לְשׁוֹן מָנוֹס מַמָּשׁ:\",1,0],[2,121,16,19,\"אֵלֶיךָ גּוֹיִם יָבֹאוּ. סוֹף הָאֻמּוֹת לָשׁוּב אֵלֶיךָ וּלְעָבְדְּךָ שְׁכֶם אֶחָד (צפניה ג:ט); וְעַמְּךָ, אֵיךְ עָשׂוּ לָהֶם אֱלֹהִים וְהֵמָּה לֹא אֱלֹהִים?!\",2,0],[2,121,16,19,\"מֵאַפְסֵי. כְּמוֹ ״מִקְּצֵה״ (ירמיה יב:יב):\",3,0],[2,121,16,19,\"נָחֲלוּ. לְשׁוֹן נַחֲלָה:\",4,0],[2,121,16,19,\"מוֹעִיל. לְשׁוֹן תּוֹעֶלֶת:\",5,0],[2,121,16,21,\"כִּי שְׁמִי ה׳. כְּמַשְׁמָעוֹ: מוֹשֵׁל וְשַׁלִּיט לְקַיֵּם גְּזֵרָתִי (ויקרא רבה כד, א):\",1,0],[2,121,17,1,\"בְּעֵט בַּרְזֶל. מָשָׁל הוּא, כְּלוֹמַר: חֲקוּקָה בְּשִׁקּוּעַ וְאֵין נוֹחָה לִמְחוֹק. וּמִדְרַשׁ אַגָּדָה בְּעֵט בַּרְזֶל בְּצִפֹּרֶן שָׁמִיר עַל יְדֵי יִרְמְיָה שֶׁנִּקְרָא עַמּוּד בַּרְזֶל, וְעַל יְדֵי יְחֶזְקֵאל שֶׁנֶּאֱמַר לוֹ״ כַּשָּׁמִיר חָזָק מִצּוּר נָתַתִּי מִצְחֶךָ״ (יחזקאל ג:ט):\",1,0],[2,121,17,1,\"חֲרוּשָׁה. חֲקוּקָה, כְּזֶה שֶׁהוּא חוֹרֵשׁ בָּעֹמֶק:\",2,0],[2,121,17,1,\"עַל לוּחַ לִבָּם. שֶׁאֵינָם שׁוֹכְחִין עֲבוֹדָה זָרָה שֶׁלָּהֶם:\",3,0],[2,121,17,2,\"כִּזְכֹּר בְּנֵיהֶם מִזְבְּחוֹתָם. כִּזְכִירַת בְּנֵיהֶם כֵּן הָיְתָה לָהֶם זְכִירַת מִזְבְּחוֹתָם; כְּאָדָם שֶׁיֵּשׁ לוֹ גִּעְגּוּעִין עַל בְּנוֹ (סנהדרין סג:):\",1,0],[2,121,17,2,\"וַאֲשֵׁרֵיהֶם. אֲשֶׁר עַל עֵץ רַעֲנָן. עַל עֵץ – כְּמוֹ אֵצֶל, וְכֵן תִּרְגֵּם יוֹנָתָן: ״תְּחוֹת כָּל אִילָן עֲבוּף״:\",2,0],[2,121,17,3,\"הֲרָרִי בַּשָּׂדֶה. יְרוּשָׁלַיִם הַיּוֹשֶׁבֶת בָּהָר הַמִּישׁוֹר (ירמיה כא:יג), כָּל סְבִיב הָעִיר מִישׁוֹר, שָׂדֶה. וְלָשׁוֹן הֲרָרִי – כְּמוֹ ״עֲרָבִי״ (ישעיה יג:כ), עַל שֵׁם שֶׁיּוֹשֵׁב בָּעֲרָבָה; מוֹנְטִינְיֵיר״שׁ בְּלַעַ״ז, יוֹשְׁבֵי הָהָר (ספרים ארחים יוֹשֶׁבֶת הָהָר):\",1,0],[2,121,17,3,\"חֵילְךָ. כְּמוֹ מָמוֹנְךָ (ראה דברים ח:יז):\",2,0],[2,121,17,3,\"בָּמוֹתֶיךָ בְּחַטָּאת. בָּמוֹתֶיךָ עֲשׂוּיוֹת בְּחֵטְא לְשֵׁם עֲבוֹדָה זָרָה בְּכָל גְּבוּלֶיךָ:\",3,0],[2,121,17,4,\"וְשָׁמַטְתָּה. עַל כָּרְחֲךָ תִּשְׁמַט אַרְצְךָ אֶת אֲשֶׁר לֹא שָׁבְתָה בְּשַׁבְּתוֹתֵיכֶם (ויקרא כו:לה), שֶׁאָמַרְתִּי לָכֶם ״וְשָׁבְתָה הָאָרֶץ״ (ויקרא כה:ב):\",1,0],[2,121,17,4,\"וּבְךָ. אֶנָּקֵם מֵחֲמַת נַחֲלָתְךָ אֲשֶׁר נָתַתִּי לָךְ שֶׁלֹּא עָשִׂיתָ רְצוֹנִי לְהַשְׁמִיטָהּ, דָּבָר אַחֵר: וּבְךָ מִנַּחֲלָתְךָ – וּבְךָ אֶנָּקֵם מִנַּחֲלָתְךָ, שֶׁאַגְלֶה אוֹתְךָ מִמֶּנָּה:\",2,0],[2,121,17,4,\"כִּי אֵשׁ קְדַחְתֶּם בְּאַפִּי. יְקַדְתֶּם בִּנְחִירַי:\",3,0],[2,121,17,5,\"אֲשֶׁר יִבְטַח בָּאָדָם. בַּחֲרִישׁוֹ וּקְצִירוֹ, לוֹמַר: אֶזְרַע בַּשְּׁבִיעִית וְאֹכַל:\",1,0],[2,121,17,5,\"זְרוֹעוֹ. כְּמוֹ עֶזְרוֹ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״רוּחְצָנֵיהּ״:\",2,0],[2,121,17,5,\"וּמִן ה׳ יָסוּר לִבּוֹ. שֶׁהִבְטִיחוֹ: ״וְצִוִּיתִי אֶת בִּרְכָתִי לָכֶם״ (ויקרא כה:כא). כָּךְ שָׁמַעְתִּי:\",3,0],[2,121,17,6,\"כְּעַרְעָר. כְּעֵץ יְחִידִי; לְשׁוֹן ״עֲרִירִי״ (בראשית טו:ב). וְיֵשׁ אוֹמֵר: דְּגַאשְׁטִי״הּ בְּלַעַ״ז. וּמְנַחֵם פֵּירֵשׁ: שֵׁם עֵץ מֵעֲצֵי הַיַּעַר וְעַרְעָר שְׁמוֹ; וְכֵן פֵּירֵשׁ ״כְּעַרְעָר בַּמִּדְבָּר״ (ירמיה מח:ו): עֵץ אֶחָד מֵעֲצֵי הַיַּעַר:\",1,0],[2,121,17,6,\"בָּעֲרָבָה. לְשׁוֹן מִישׁוֹר:\",2,0],[2,121,17,6,\"חֲרֵרִים. יֹבֶשׁ, כְּמוֹ ״חָרָה מִנִּי חֹרֶב״ (איוב ל:ל):\",3,0],[2,121,17,6,\"אֶרֶץ מְלֵחָה. אֶרֶץ שֶׁהִיא מְלֵחָה וְלֹא תְהֵא מְיֻשֶּׁבֶת:\",4,0],[2,121,17,8,\"וְלֹא יִרְאֶה. הָעֵץ כִּי יָבֹא חֹם:\",1,0],[2,121,17,8,\"בַּצֹּרֶת. לְשׁוֹן רָעָב פאמצ״א בְּלַעַ״ז,.לָשׁוֹן אַחֵר: בַּצֹּרֶת לְשׁוֹן מִבְצָר, וְכֵן חִבְּרוֹ מְנַחֵם:\",2,0],[2,121,17,8,\"לֹא יִדְאָג. לֹא יִפְחַד:\",3,0],[2,121,17,9,\"עָקֹב הַלֵּב. מָלֵא תּוֹאֲנָה וַעֲקֻבָּה מִכֹּל רָעָה:\",1,0],[2,121,17,9,\"וְאָנוּשׁ. לְשׁוֹן חֹלִי, וְחָלְיוֹ הוּא זֶה:\",2,0],[2,121,17,9,\"מִי יֵדָעֶנּוּ. הוּא סָבוּר: מִי יֵדָעֶנּוּ. אֲנִי ה׳ חוֹקְרוֹ:\",3,0],[2,121,17,11,\"קוֹרֵא דָגַר. קוּקוּ״וּ גְלוּנְצְנְ״ט בְּלַעַ״ז:\",1,0],[2,121,17,11,\"וְלֹא יָלָד. הַקּוֹרֵא הַזֶּה מוֹשֵׁךְ אַחֲרָיו אֶפְרוֹחִים שֶׁלֹּא יָלָד. דָּגַר. צִפְצוּף שֶׁמְּצַפְצֵף הָעוֹף בְּקוֹלוֹ לִמְשׁוֹךְ אֶפְרוֹחִין אַחֲרָיו, וְאֵלּוּ שֶׁהַקּוֹרֵא דָּגַר לֹא יֵלְכוּ אַחֲרָיו מִשֶּׁיִּגְדְּלוּ שֶׁאֵינָם מִינוֹ, כָּךְ עֹשֶׂה עֹשֶׁר וְלֹא בְמִשְׁפָּט:\",2,0],[2,121,17,11,\"יִהְיֶה נָבָל. ״מִתְקְרֵי רְשִׁיעָא״ (תרגום יונתן):\",3,0],[2,121,17,12,\"כִּסֵּא כָבוֹד וגו׳. לְפִי שֶׁבָּא לוֹמַר כָּל עֹזְבֶיךָ יֵבֹשׁוּ, מַתְחִיל בְּקִלּוּסוֹ שֶׁל מָקוֹם וּמְדַבֵּר לְפָנָיו: אַתָּה, שֶׁכִּסֵּא כָבוֹד וּמָרוֹם מֵרֵאשִׁית בְּרִיאַת עוֹלָם וּמְכֻוָּן כְּנֶגֶד מִקְדָּשֵׁנוּ:\",1,0],[2,121,17,13,\"מִקְוֵה יִשְׂרָאֵל. ה׳ יוֹשֵׁב עָלָיו, לְפִיכָךְ כָּל עֹזְבֶיךָ יֵבֹשׁוּ:\",1,0],[2,121,17,13,\"וְסוּרַי בָּאָרֶץ יִכָּתֵבוּ. אוֹתָם שֶׁסָּרִים מִדְּבָרַי, שֶׁאֵינָם שׁוֹמְעִים שְׁלִיחוּתִי, בְּקִבְרוֹת תַּחְתִּיּוֹת אֶרֶץ יִכָּתֵבוּ:\",2,0],[2,121,17,14,\"כִּי תְהִלָּתִי אָתָּה. בְּךָ אֲנִי מִתְהַלֵּל וּמִתְפָּאֵר לוֹמַר שֶׁאַתָּה מוֹשִׁיעִי:\",1,0],[2,121,17,14,\"תְּהִלָּתִי. וונטנצ״א בְּלַעַ״ז:\",2,0],[2,121,17,15,\"אַיֵּה דְּבַר ה׳. הַפּוּרְעָנִיּוֹת שֶׁאַתָּה מִתְנַבֵּא:\",1,0],[2,121,17,16,\"וַאֲנִי לֹא אַצְתִּי. לֹא מִהַרְתִּי לְזָרֶזְךָ לַהֲבִיאָם, מִהְיוֹת רֹעֶה טוֹב מְחַזֵּר אַחֲרֶיךָ לְבַקֵּשׁ עֲלֵיהֶם רַחֲמִים:\",1,0],[2,121,17,16,\"וְיוֹם אָנוּשׁ. חֹלִי שֶׁל פֻּרְעָנוּת לֹא הִתְאַוֵּיתִי. וְיוֹנָתָן תִּרְגֵּם: ״וַאֲנָא לָא עַנְבִּית עַל מֵימְרָךְ מִלְּהִתְנַבָּאָה עֲלֵיהוֹן לַאֲתָבוּתְהוֹן לְדַחַלְתָּךְ״. וּלְפִי הַתַּרְגּוּם יִהְיֶה אַצְתִּי – לְשׁוֹן עִכּוּב, כְּלוֹמַר: לֹא עִכַּבְתִּי מִלּוֹמַר לָהֶם שְׁלִיחוּתֶיךָ וּלְהָשִׁיבָם אֵלֶיךָ, אִם הָיוּ שׁוֹמְעִים אֵלַי:\",2,0],[2,121,17,16,\"מוֹצָא שְׂפָתַי נֹכַח פָּנֶיךָ הָיָה. לְהָשִׁיב אֶת חֲמָתְךָ מֵהֶם:\",3,0],[2,121,17,17,\"אַל תִּהְיֵה לִי לִמְחִתָּה. אַל יְהִי שְׁלִיחוּתְךָ לִמְחִתָּה:\",1,0],[2,121,17,18,\"יֵבֹשׁוּ רֹדְפַי. אַנְשֵׁי עֲנָתוֹת לְבַדָּם:\",1,0],[2,121,17,23,\"וְלֹא שָׁמְעוּ. אֲבוֹתֵיכֶם לְמַה שֶּׁצִּוִּיתִים:\",1,0],[2,121,17,27,\"וּבֹא. כְּמוֹ וְלָבֹא:\",1,0],[2,121,18,3,\"עַל הָאׇבְנָיִם. ״עַל סַדְנָא״ (תרגום יונתן). פורמ״ש בְּלַעַ״ז:\",1,0],[2,121,18,4,\"אֲשֶׁר הוּא עוֹשֶׂה בַּחֹמֶר. אֲשֶׁר הוּא עוֹשֶׂה מִן הַחֹמֶר נִשְׁחַת בְּיַד הַיּוֹצֵר, בְּעוֹדוֹ לַח; וּמִקְרָא מְסֹרָס הוּא:\",1,0],[2,121,18,8,\"מֵרָעָתוֹ אֲשֶׁר דִּבַּרְתִּי עָלָיו. מֵעֲבֵירוֹת שֶׁבְּיָדוֹ, אֲשֶׁר בִּשְׁבִילוֹ דִּבַּרְתִּי עָלָיו ״לִנְתוֹשׁ וְלִנְתוֹץ״ (ירמיה א:י), אִירְפוֹרְקִ״י בְּלַעַ״ז:\",1,0],[2,121,18,8,\"וְנִחַמְתִּי. וְחָשַׁבְתִּי מַחֲשָׁבָה אַחֶרֶת:\",2,0],[2,121,18,12,\"וְאָמְרוּ נוֹאָשׁ. וְיָדַעְתִּי שֶׁהֵם יֹאמְרוּ לְךָ עַל דְּבָרֶיךָ, שֶׁאֵין חוֹשְׁשִׁין לָהֶם:\",1,0],[2,121,18,13,\"שַׁעֲרֻרִת. דְּבָר גְּנַאי:\",1,0],[2,121,18,14,\"הֲיַעֲזֹב מִצּוּר שָׂדַי שֶׁלֶג לְבָנוֹן. הֲיַעֲזֹב אָדָם הַצָּרִיךְ לִשְׁתּוֹת מַיִם הַנּוֹזְלִים מִצּוּר שֶׁבַּשָּׂדוֹת, הַבָּאִים מִשֶּׁלֶג הַלְּבָנוֹן שֶׁהוּא נָקִי?!\",1,0],[2,121,18,14,\"אִם יִנָּתְשׁוּ מַיִם זָרִים. אוֹ אִם יַעַזְבוּ מַיִם חַיִּים נוֹבְעִים, שֶׁהֵם זָרִים עַד הֵנָּה מִכָּל אָדָם, וְהֵם קָרִים. זָרִים הֵם נוֹבְעִים, וְזֶה יוֹכִיחַ: ״אֲנִי קַרְתִּי וְשָׁתִיתִי מַיִם זָרִים״ (מלכים ב יט:כד). וּמְנַחֵם חִבְּרוֹ זָרִים עִם ״לֹא זֹרוּ וְלֹא חֻבָּשׁוּ״ (ישעיהו א:ו) – לְשׁוֹן מֵימֵי תְרוּפָה. וְנָתַן טַעַם לִדְבָרָיו וְאָמַר, כִּי אִם בִּקֵּשׁ לְדַבֵּר בִּלְשׁוֹן זֶרֶם, הָיָה מַכְפִּיל אֶת הַמֵּ״ם וְהָיָה מוֹסִיף יוֹ״ד מֵ״ם, וְהָיָה אוֹמֵר זְרוּמִים, לְרַבּוֹת הַמַּיִם וְלִהְיוֹתָם זְרָמִים:\",2,0],[2,121,18,14,\"שָׂדַי. כְּמוֹ שָׂדֶה:\",3,0],[2,121,18,14,\"קָרִים. פְּרִיוְודָ״שׁ בְּלַעַ״ז:\",4,0],[2,121,18,14,\"נוֹזְלִים. קוֹרַאנְ״ץ בְּלַעַ״ז. וְעוֹד יֵשׁ לְפָתְרוֹ: אִם יִנָּתְשׁוּ לִהְיוֹת מַיִם זָרִים נִמְאָסִים, הַמַּיִם שֶׁהֵם קָרִים נוֹזְלִים:\",5,0],[2,121,18,14,\"(זָרִים לְלָשׁוֹן רִאשׁוֹן הוּא לְשׁוֹן זֶרֶם; לְלָשׁוֹן שֵׁנִי הוּא לָשׁוֹן זָרוֹת, כְּלוֹמַר מַיִם מְאוּסִים):\",6,0],[2,121,18,15,\"כִּי. כֵּן עָשׂוּ עַמִּי אֲשֶׁר שְׁכֵחֻנִי וְלַשָּׁוְא יְקַטֵּרוּ:\",1,0],[2,121,18,15,\"שְׁבִילֵי עוֹלָם. שְׁבִילִים הַמְתֻקָּנִים אָמְרוּ שֶׁהֵם מִכְשׁוֹל, כְּדֵי לָלֶכֶת דֶּרֶךְ לֹא סְלוּלָה לֹא כְבוּשָׁה:\",2,0],[2,121,18,16,\"שְׁרִיקוֹת. הָעוֹבֵר עַל חֳרָבוֹת שֶׁרָאָה כְּבָר בְּבִנְיָנָם, טוֹבִים, רָגִיל לִשְׁרֹק:\",1,0],[2,121,18,16,\"יִשּׁוֹם. יִתְמַהּ:\",2,0],[2,121,18,17,\"עֹרֶף וְלֹא פָנִים. כְּשֶׁיִּבְרְחוּ מִפְּנֵי הָאוֹיֵב:\",1,0],[2,121,18,17,\"אֶרְאֵם. וְלֹא אוֹשִׁיעֵם:\",2,0],[2,121,18,18,\"וַיֹּאמְרוּ לְכוּ וְגוֹ׳. יִרְמְיָה הָיָה קוֹבֵל עַל אַנְשֵׁי עֲנָתוֹת וְאוֹמֵר שֶׁאוֹמְרִים כֵּן:\",1,0],[2,121,18,18,\"תּוֹרָה מִכֹּהֵן. שֶׁעַל הַכֹּהֲנִים לְהוֹרוֹת תּוֹרָה, שֶׁנֶּאֱמַר ״יוֹרוּ מִשְׁפָּטֶיךָ לְיַעֲקֹב״ (דברים לג:י):\",2,0],[2,121,18,18,\"וְדָבָר מִנָּבִיא. דִּבְרֵי נְבוּאָה:\",3,0],[2,121,18,18,\"וְנַכֵּהוּ בַלָּשׁוֹן. ״וּנְסַהֲדִינֵיהּ סַהֲדוּתָא דְּשִׁקְרָא״ (תרגום יונתן):\",4,0],[2,121,18,21,\"וְהַגִּרֵם. (הוֹרִידֵם עַל יְדֵי חֶרֶב) לְשׁוֹן ״עֵינִי נִגְּרָה״ (איכה ג:מט), ״כַּמַּיִם הַמּוּגָרִים״ (מיכה א:ד):\",1,0],[2,121,18,21,\"עַל יְדֵי חֶרֶב. עַל יְדֵי גְּיָסוֹת:\",2,0],[2,121,18,21,\"וְאַנְשֵׁיהֶם. שֶׁל הָאַלְמָנוֹת, יִהְיוּ הֲרֻגֵי מַלְאַךְ הַמָּוֶת:\",3,0],[2,121,18,22,\"כִּי כָרוּ שׁוּחָה. שֶׁחֲשָׁדוּהוּ מֵאֵשֶׁת אִישׁ, שֶׁנֶּאֱמַר ״כִּי שׁוּחָה עֲמֻקָּה זוֹנָה״ (משלי כג:כז):\",1,0],[2,121,18,23,\"אַל תֶּמְחִי. אַל תְּהִי מְחוּיָה. וּלְפִי שֶׁהוּא לְשׁוֹן נְקֵבָה נָתַן בּוֹ יוֹ״ד, וְאַף הִיא יְתֵרָה, כְּיוֹ״ד שֶׁל ״וַתִּזְנִי בָם״ (יחזקאל טז:יז):\",1,0],[2,121,19,1,\"בַּקְבּוּק. צְלוֹחִית:\",1,0],[2,121,19,1,\"יוֹצֵר חָרֶשׂ. כְּלוֹמַר: שֶׁל יוֹצֵר, שֶׁהוּא שֶׁל חָרֶשׂ:\",2,0],[2,121,19,1,\"וּמִזִּקְנֵי הָעָם. הָלוֹךְ עִמָּךְ; וּמִזִּקְנֵי הָעָם מוּסָב עַל הָלוֹךְ :וּמִזִּקְנֵי הָעָם עִמָּךְ:\",3,0],[2,121,19,2,\"שַׁעַר הַחַרְסִית. שַׁעַר הָאַשְׁפּוֹת (נחמיה ב:יג), שֶׁשָּׁם זוֹרְקִין חֲרָסִים הַנִּשְׁבָּרִים; וְכֵן תִּרְגְּמוֹ יוֹנָתָן: ״תְּרַע קִילְקִלְתָּא״:\",1,0],[2,121,19,3,\"תִּצַּלְנָה. טִינְטִינִי״ר בְּלַעַ״ז; לְשׁוֹן ״מְצִלְתַּיִם״ (נחמיה יב:כז); ״בְּצִלְצְלֵי שָׁמַע״ (תהלים קנ:ה):\",1,0],[2,121,19,4,\"וַיְנַכְּרוּ. עֲשָׂאוּהוּ נָכְרִי לְפָנַי:\",1,0],[2,121,19,7,\"וּבַקּוֹתִי. וְרוֹקַנְתִּי, לְשׁוֹן ״בּוּקָה וּמְבוּקָה״ (נחום ב:יא). וְעַל שֵׁם בַּקְבּוּק שֶׁהוּא מְדַבֵּר בּוֹ, לָקַח לְשׁוֹנוֹ כֵּן:\",1,0],[2,121,19,9,\"וּבְמָצוֹק. לְשׁוֹן צָרָה, כְּמוֹ ״צוּקָה״ (ישעיה ל:ו):\",1,0],[2,121,19,11,\"(אֲשֶׁר לֹא יוּכַל לְהֵרָפֵה. אַהָעָם קָאֵי, אֲבָל הָעִיר אֶעֱשֶׂה כְּתֹפֶת וַאֲטַהֵר לֶעָתִיד):\",1,0],[2,121,19,12,\"הָעִיר הַזֹּאת כְּתֹפֶת. כֻּלָּהּ מְלֵאָה הֲרוּגִים, כְּמוֹ הַתֹּפֶת שֶׁהוֹרְגִין שָׁם אֶת הַיְלָדִים לַמֹּלֶךְ (מלכים ב כג:י):\",1,0],[2,121,20,2,\"הַמַּהְפֶּכֶת. שֵׁם מְקוֹם הָאֲסוּרִים, וְיוֹנָתָן תִּרְגֵּם: ״לְכִיפְתָּא״, אַרְוְלוֹ״ר בְּלַעַ״ז:\",1,0],[2,121,20,3,\"מָגוֹר. יִרְאָה:\",1,0],[2,121,20,3,\"לֹא פַשְׁחוּר קָרָא ה׳ שְׁמֶךָ וגו׳. לֹא נִקְרָא שִׁמְךָ פַּשְׁחוּר אֶלָּא בִּשְׁבִיל דָּבָר זֶה. כְּלוֹמַר פָּשַׁח שָׁחוֹר כְּמוֹ אִילָן שֶׁנִּפְשַׁח (משנה שביעית ד, ו), וְכֵן ״וַיְפַשְּׁחֵנִי״ (איכה ג, יא), וְכֵן אָמַר לוֹ לֹא פַשְׁחוּר קָרָא שְׁמֶךָ שֶׁלְּשׁוֹן פַּשְׁחוּר מַשְׁמַע אָדָם גָּדוֹל וּבֶן חוֹרִין, פָּשׁ חוּר, אֶלָּא לְכָךְ נִקְרָא שִׁמְךָ פַּשְׁחוּר – פָּשַׁח שָׁחוֹר. דָּבָר אַחֵר: פָּשׁ סְחוֹר, רַבִּים סְבִיבוֹתֶיךָ לַהֲרֹג, וְלַלָּשׁוֹן זֶה מָגוֹר הוּא לְשׁוֹן אֲסִיפָה, כְּמוֹ ״מְגוּרֵי אֶל חָרֶב״ (יחזקאל כא:יז):\",2,0],[2,121,20,5,\"חֹסֶן. מָמוֹן:\",1,0],[2,121,20,7,\"פִּתִּיתַנִי. לָלֶכֶת בִּשְׁלִיחוּתְךָ:\",1,0],[2,121,20,7,\"חֲזַקְתַּנִי. הִכְבַּדְתָּ עָלַי יָדְךָ הַחֲזָקָה, לָלֶכֶת עַל כָּרְחִי:\",2,0],[2,121,20,7,\"וַתּוּכָל. וְנִצַּחְתָּ:\",3,0],[2,121,20,7,\"כֻּלֹּה. כָּל הָעָם לֹעֵג לִי:\",4,0],[2,121,20,8,\"מִדֵּי אֲדַבֵּר. בְּכָל עֵת שֶׁאֲדַבֵּר אֲלֵיהֶם, אֲנִי צָרִיךְ לִזְעֹק וּלְהָרִים קוֹל; וְאֵינִי קוֹרֵא אֲלֵיהֶם טוֹבָה כִּי אִם נְבוּאוֹת חָמָס וָשֹׁד:\",1,0],[2,121,20,8,\"כִּי הָיָה דְבַר ה׳ לִי. לְפִיכָךְ דִּבְּרוּ לִי חֶרְפָּה, שֶׁהֵם מְחָרְפִים אוֹתִי:\",2,0],[2,121,20,8,\"וּלְקֶלֶס. וּלְדִבּוּר, כְּמוֹ ״וְקַלָּסָה״ (יחזקאל כב:ד):\",3,0],[2,121,20,9,\"וְאָמַרְתִּי לֹא אֶזְכְּרֶנּוּ. וְאִם אָמַר לִי לִבִּי שֶׁלֹּא לֵילֵךְ בִּשְׁלִיחוּתוֹ עוֹד:\",1,0],[2,121,20,9,\"וְהָיָה בְלִבִּי. הַנְּבוּאָה כְּאֵשׁ בֹּעֶרֶת, וְעַל כָּרְחִי אֲנִי צָרִיךְ לֵילֵךְ:\",2,0],[2,121,20,9,\"עָצוּר בְּעַצְמוֹתָי. וְכָנוּס בְּעַצְמוֹתַי הָאֵשׁ:\",3,0],[2,121,20,9,\"כַּלְכֵּל. לִסְבּוֹל הָאֵשׁ:\",4,0],[2,121,20,10,\"כִּי שָׁמַעְתִּי. אֲנִי אָמַרְתִּי שֶׁלֹּא אֶזְכְּרֶנּוּ לְפִי שֶׁשָּׁמַעְתִּי דִּבַּת רַבִּים, אֵלּוּ שֶׁמִּתְלַחֲשִׁים עָלַי:\",1,0],[2,121,20,10,\"מָגוֹר. לְשׁוֹן אֲסִיפָה, וְכֵן תִּרְגֵּם יוֹנָתָן:\",2,0],[2,121,20,10,\"הַגִּידוּ. עָלָיו עֵדוּת שֶׁקֶר:\",3,0],[2,121,20,10,\"וְנַגִּידֶנּוּ. וְנָעִידֶנּוּ. וּמְנַחֵם פֵּירֵשׁ הַגִּידוּ וְנַגִּידֶנּוּ כְּמוֹ ״לֹא תִתְגּוֹדְדוּ״ (דברים יד:א), וְכֵן חִבֵּר ״לְחֵלֶק יַגִּיד רֵעִים״ (איוב יז:ה) לְשׁוֹן הַשְׁחָתָה, כְּמוֹ ״גֹּדּוּ אִילָנָא״ (דניאל ד:יא). וְדוּנָשׁ פָּתַר אוֹתוֹ לְשׁוֹן הַגָּדָה מַמָּשׁ, וְכֹה פִּתְרוֹנוֹ: הַגִּידוּ עָלָיו דִּבְרֵי שֶׁקֶר וְנַגִּידֶנּוּ לַמֶּלֶךְ. וְיֵשׁ לָנוּ כְּמוֹ נַגִּידֶנּוּ דְּבָרִים רַבִּים בַּמִּקְרָא, אֲשֶׁר לֹא יִכּוֹן פִּתְרוֹנוֹ כִּי אִם עַד אֲשֶׁר יְחַלְּקוּן לִשְׁתֵּי תֵיבוֹת אוֹ לְשָׁלֹשׁ, כְּמוֹ ״וְלֹא יָכְלוּ דַּבְּרוֹ לְשָׁלוֹם״ (בראשית לז:ד); ״בָּנַי יְצָאֻנִי״ (ירמיה י:כ):\",4,0],[2,121,20,10,\"שׁוֹמְרֵי צַלְעִי. מְצַפִּים שִׁבְרִי:\",5,0],[2,121,20,10,\"אוּלַי יְפֻתֶּה. לִשְׁמֹעַ לָנוּ וְלִטְעוֹת אַחֲרֵינוּ:\",6,0],[2,121,20,11,\"כִּי לֹא הִשְׂכִּילוּ. לֹא הִצְלִיחוּ בַּעֲצָתָם:\",1,0],[2,121,20,14,\"אָרוּר הַיּוֹם אֲשֶׁר יֻלַּדְתִּי בּוֹ. פוא״י אינייניר״ט בְּלַעַ״ז, הִיא שְׁעַת הֵרָיוֹן. וְעַל יְדֵי אֹנֶס שִׁמֵּשׁ חִלְקִיָּהוּ אָבִיו מִטָּתוֹ בַּיּוֹם, שֶׁהָיָה בּוֹרֵחַ מִפְּנֵי מְנַשֶּׁה שֶׁהָיָה הוֹרֵג אֶת הַנְּבִיאִים; וְשִׁמֵּשׁ מִטָּתוֹ וּבָרַח (בראשית רבה סד, ה):\",1,0],[2,121,20,15,\"שַׂמֵּחַ. מ״ם דְּגוּשָׁה, שֶׁהוּא לְשׁוֹן תְּשַׂמַּח אֲחֵרִים; שֶׁשִּׂמַּח אֶת אָבִיו בִּבְשׂוֹרָתוֹ:\",1,0],[2,121,20,16,\"כֶּעָרִים אֲשֶׁר הָפַךְ. סְדוֹם וַעֲמוֹרָה (בראשית יט:כד-כה):\",1,0],[2,121,20,16,\"וְלֹא נִחָם. מִשֶּׁגָּזַר עֲלֵיהֶם חוּרְבָּן, לֹא חָשַׁב מַחֲשָׁבָה אַחֶרֶת לְבַטֵּל גְּזֵרָתוֹ (בראשית יח:כ-לב):\",2,0],[2,121,20,17,\"אֲשֶׁר לֹא מוֹתְתַנִי מַלְאַךְ הַמָּוֶת מֵרָחֶם. וַהֲרֵי זֶה מִן הַמִּקְרָאוֹת קִצְרֵי דִּבּוּר:\",1,0],[2,121,20,17,\"הֲרַת עוֹלָם. הֵרָיוֹן שֶׁל עוֹלָמִית:\",2,0],[2,121,20,18,\"עָמָל וְיָגוֹן. חֻרְבַּן בֵּית הַמִּקְדָּשׁ:\",1,0],[2,121,21,4,\"הִנְנִי מֵסֵב אֶת כְּלֵי הַמִּלְחָמָה. יֵשׁ בָּכֶם הַיּוֹדְעִים לְהַשְׁבִּיעַ אֶת הַשָּׂרִים שֶׁל מַעְלָה הַמְמֻנִּים עַל הַפֻּרְעָנִיּוֹת, לְהַצִּיל אִישׁ אִישׁ מִן הָרָעָה שֶׁהוּא מְמֻנֶּה עָלֶיהָ, וּבְכָךְ אַתֶּם בּוֹטְחִים; הִנְנִי מֵסֵב אֶת הַשְּׂרָרָה שֶׁל זֶה לָזֶה, וְלֹא תֵדְעוּ עַל מִי תַּשְׁבִּיעוּ:\",1,0],[2,121,21,4,\"וְאָסַפְתִּי אוֹתָם. כְּלֵי מִלְחָמָה אֶל תּוֹךְ הָעִיר הַזֹּאת, שֶׁאַשְׁחִית אֶתְכֶם בְּדֶבֶר עַל יְדֵי מַלְאַךְ הַמָּוֶת, שֶׁהוּא מִן הַשָּׂרִים הָעֶלְיוֹנִים; וְכֵן מְפֹרָשׁ בָּעִנְיָן: בְּדֶבֶר גָּדוֹל יָמוּתוּ:\",2,0],[2,121,21,9,\"וְהָיְתָה לוֹ נַפְשׁוֹ לְשָׁלָל. כְּאָדָם הַשּׁוֹלֵל שָׁלָל וְחוֹטְפוֹ וְהוֹלֵךְ לוֹ, כֵּן תִּהְיֶה לוֹ נַפְשׁוֹ שְׁלוּלָה מִן הַמִּיתָה, מִן הַהוֹרְגִים:\",1,0],[2,121,21,10,\"פָּנַי. כְּתַרְגּוּמוֹ: ״רוּגְזִי״:\",1,0],[2,121,21,12,\"מִיַּד עוֹשֵׁק. טַעֲמוֹ לְמַטָּה, שֶׁאֵינוֹ שֵׁם דָּבָר אֶלָּא שֵׁם הַגַּזְלָן הָעוֹשֵׁק אֶת אֲחֵרִים:\",1,0],[2,121,21,12,\"וְאֵין מְכַבֶּה. שֶׁלֹּא יִמָּלֵט לָכֶם שָׂרִיד:\",2,0],[2,121,21,13,\"יוֹשֶׁבֶת הָעֵמֶק. יְרוּשָׁלַיִם הִיא בְּתוֹךְ עֵמֶק. דָּבָר אַחֵר: שֶׁהֶעֱמִיק הַקָּדוֹשׁ בָּרוּךְ הוּא עֵצָה עָלֶיךָ לְהַחֲרִיבֶךָ:\",1,0],[2,121,21,13,\"צוּר הַמִּישׁוֹר. הַר שֶׁכָּל סְבִיבָיו מִישׁוֹר:\",2,0],[2,121,21,13,\"מִי יֵחַת עָלֵינוּ. מִי יַחֲנֶה עָלֵינוּ, כְּמוֹ ״כִּי שָׁם אֲרָם נְחִתִּים״ (מלכים ב ו:ט):\",3,0],[2,121,22,3,\"אַל תּוֹנוּ. זוֹ אוֹנָאַת דְּבָרִים (תורת כהנים בהר פרשתא ג, ד):\",1,0],[2,121,22,6,\"גִּלְעָד אַתָּה לִי וגו׳. ״אִלּוּ אַתְּ חֲבִיב קֳדָמַי כְּבֵית מַקְדְּשָׁא דְּרָם בְּרֵישׁ טוּרַיָּא, אִם לֹא אֲשַׁוִּינָךְ מִדְבְּרָא״ (תרגום יונתן):\",1,0],[2,121,22,6,\"גִּלְעָד אַתָּה. הַמִּקְדָּשׁ (מכילתא בשלח עמלק ב), שֶׁמִּמֶּנּוּ צֳרִי וּרְפוּאָה לְכָל הָעוֹלָם (פסיקתא רבתי לג):\",2,0],[2,121,22,7,\"וְקִדַּשְׁתִּי. וְזִמַּנְתִּי:\",1,0],[2,121,22,7,\"וְכָרְתוּ מִבְחַר אֲרָזֶיךָ. לְפִי שֶׁדִּמָּהוּ לַלְּבָנוֹן, נוֹפֵל כָּאן הַלָּשׁוֹן הַזֶּה:\",2,0],[2,121,22,10,\"אַל תִּבְכּוּ לַמֵּת. לִיהוֹיָקִים, שֶׁיָּמוּת לִפְנֵי הַשַּׁעַר כְּשֶׁיִּסְחָבוּהוּ לְהַגְלוֹתוֹ (ירמיה כב:יט):\",1,0],[2,121,22,10,\"בְּכוּ לַהֹלֵךְ. לִיהוֹיָכִין וְלִצִדְקִיָּהוּ. אֱמוֹר מֵעַתָּה: חֲבִיבָה מִיתָתוֹ שֶׁל יְהוֹיָקִים, שֶׁנֶּאֱמַר בּוֹ ״וְנִבְלָתוֹ תִּהְיֶה מֻשְׁלֶכֶת לַחֹרֶב בַּיּוֹם וְלַקֶּרַח בַּלָּיְלָה״ (ירמיה לו:ל), מֵחַיָּיו שֶׁל יְהוֹיָכִין, שֶׁנֶּאֱמַר בּוֹ ״וַאֲרֻחָתוֹ אֲרֻחַת תָּמִיד וְגוֹ׳״ (ירמיה נב:לד):\",2,0],[2,121,22,11,\"אֶל שַׁלּוּם. הוּא צִדְקִיָּהוּ, וְכָךְ נִקְרָא ״וְהָרְבִיעִי שַׁלּוּם״ (דברי הימים א ג:טו). וְקְרָאוֹ רְבִיעִי לַמַּלְכוּת בִּבְנֵי יֹאשִׁיָּהוּ, שֶׁבַּתְּחִלָּה מָלַךְ יְהוֹאָחָז וְאַחַר כָּךְ יְהוֹיָקִים וְאַחֲרָיו יְהוֹיָכִין וְאַחֲרָיו צִדְקִיָּהוּ (מלכים ב כג-כה; הוריות יא:):\",1,0],[2,121,22,11,\"אֲשֶׁר יָצָא. וְאַף עַל פִּי שֶׁלֹּא יָצָא עֲדַיִן, מִתְנַבֵּא עָלָיו כְּאִלּוּ יָצָא:\",2,0],[2,121,22,13,\"הוֹי בּוֹנֶה בֵיתוֹ. עַל יְהוֹיָקִים הוּא אוֹמֵר, שֶׁהוּא הָיָה רָשָׁע. וְסוֹף הָעִנְיָן מוֹכִיחַ: לָכֵן כֹּה אָמַר ה׳ אֶל יְהוֹיָקִים וְגוֹ׳:\",1,0],[2,121,22,14,\"בֵּית מִדּוֹת. בַּיִת גָּדוֹל, כְּמוֹ ״אַנְשֵׁי מִדּוֹת״ (במדבר יג:לב) שֶׁיֵּשׁ בָּהֶן מַה לִמְדֹּד:\",1,0],[2,121,22,14,\"וְקָרַע לוֹ. וְהִרְחִיב לוֹ. אֲחֵרִים הִגִּיהוּ וְקָרַע לוֹ וּפָתַח לוֹ, וְכֵן ״וַתִּקְרְעִי בַּפּוּךְ״ (ירמיה ד:ל), ״קָרַעְתָּ שָׁמַיִם יָרַדְתָּ״ (ישעיהו סג:יט) – כֻּלָּן לְשׁוֹן פְּתִיחָה:\",2,0],[2,121,22,14,\"וְסָפוּן בָּאָרֶז. מְסַכֵּךְ הַגַּג בַּאֲרָזִים:\",3,0],[2,121,22,14,\"וּמָשׁוֹחַ בַּשָּׁשַׁר. ״וּמְצֻיָּר בְּסַמְמָנִים״, תִּרְגֵּם יוֹנָתָן. בַּשָּׁשַׁר צֶבַע הוּא מִמִּין הַצִּיּוּרִים. לָשׁוֹן אַחֵר: וּמָשׁוֹחַ בַּשָּׁשַׁר כְּמוֹ חוּט הַמִּשְׁחָה (כלים יז,יג) אֵיינַאנְ״ט אַנְשִׁינוֹפְלָ״א בְּלַעַז:\",4,0],[2,121,22,15,\"הֲתִמְלֹךְ. הַתַּאֲרִיךְ יָמִים עַל שֶׁאַתָּה מְתַחֲרֶה לְהַכְבִּיד עַל מֶמְשַׁלְתְּךָ לְהוֹדִיעַ שֶׁאַתָּה מֶלֶךְ?!\",1,0],[2,121,22,15,\"אָבִיךָ. יֹאשִׁיָּהוּ, שֶׁהִתְנַהֵג בַּעֲנָוָה, הֲלוֹא אָכַל וְשָׁתָה וְרָאָה טוֹב כָּל יְמֵי חַיָּיו:\",2,0],[2,121,22,17,\"עַל בִּצְעֶךָ. לִגְזֹל מָמוֹן:\",1,0],[2,121,22,17,\"הַמְּרוּצָה. רִצּוּץ דַּלִּים; וְעֹשֶׁק יוֹכִיחַ עָלָיו, כִּי עָשׁוּק וְרָצוּץ תָּמִיד סְמוּכִין בִּלְשׁוֹן מִקְרָא (דברים כח:לג; עמוס ד:א), וְכֵן ״אֶת מִי עָשַׁקְתִּי וְאֶת מִי רַצּוֹתִי״ (שמואל א יב:ג):\",2,0],[2,121,22,18,\"וְהוֹי הֹדֹה. הוֹי עַל תִּפְאַרְתּוֹ:\",1,0],[2,121,22,19,\"קְבוּרַת חֲמוֹר יִקָּבֵר. ״כְּמָה דִמְשַׁגְּרִין יָת נִבְלַת חֲמָרָא כֵּן יְשַׁגְּרוּן יָת נְבִילְתֵיהּ״ (תרגום יונתן). יְשַׁגְּרוּן – יִסְחֲבוּן:\",1,0],[2,121,22,20,\"עֲלִי הַלְּבָנוֹן וּצְעָקִי. ״סַקִי לְבֵית מַקְדְּשָׁא וְצַוְּחִי״ (תרגום יונתן):\",1,0],[2,121,22,20,\"וּבַבָּשָׁן תְּנִי קוֹלֵךְ. עַל הַבָּשָׁן שֶׁיֶּחֱרַב. וְיוֹנָתָן תִּרְגֵּם: ״וּבְתַרְעֵי טוּר בֵּיתָא״; וְאֵינִי יוֹדֵעַ לְפָרֵשׁ הָאֵיךְ נוֹפֵל לְשׁוֹן בָּשָׁן בְּשַׁעֲרֵי הַר הַבַּיִת, אִם לֹא בִּשְׁבִיל הַדְּלָתוֹת שֶׁעוֹשִׂין מֵאַלּוֹנֵי הַבָּשָׁן, וְהוּא שֵׁם מָקוֹם. אוֹ לְשׁוֹן בָּשָׁן – מְקוֹם בִּקְעָה רְחָבָה, כֵּן הֶקֵּף הַר הַבַּיִת מִגְרָשׁ רֶוַח לְבֵית הַמִּקְדָּשׁ:\",2,0],[2,121,22,20,\"וְצַעֲקִי מֵעֲבָרִים. ״וְצַוְּחִי עַל מְגִיזָתָא״ (תרגום יונתן), וְהֵם לְשׁוֹן מָקוֹם:\",3,0],[2,121,22,21,\"בְּשַׁלְוֺתַיִךְ. כְּשֶׁהָיִיתָ בְּשַׁלְוָה:\",1,0],[2,121,22,22,\"כָּל רֹעַיִךְ. כָּל מְלָכַיִךְ:\",1,0],[2,121,22,22,\"תִּרְעֶה רוּחַ. רוּחַ קָדִים תְּרוֹצְצֵם:\",2,0],[2,121,22,23,\"מְקֻנַּנְתְּ בָּאֲרָזִים. שֶׁשַּׂמְתְּ קִנֵּךְ בְּמִגְדְּלוֹת בָּתֵּי אֲרָזִים, לִבְנוֹת בָּתֵּי מִדּוֹת:\",1,0],[2,121,22,23,\"מַה נֵּחַנְתְּ. מַה מָּצָאת חֵן בִּשְׁבִיל גֹּבַהּ מִגְדָּלַיִךְ בְּעֵינֵי שׁוֹדְדַיִךְ, בְּבֹא לָךְ חֲבָלִים שֶׁל לֵידָה. וּמְנַחֵם פָּתַר נֵּחַנְתְּ לְשׁוֹן חֲנִיָּה; אֲבָל דּוּנַשׁ פָּתַר אוֹתוֹ לְשׁוֹן חֵן:\",2,0],[2,121,22,24,\"חוֹתָם עַל יַד יְמִינִי. חָקוּק וְחָתוּם בְּתוֹךְ בְּשַׂר זְרוֹעִי:\",1,0],[2,121,22,24,\"אֶתְּקֶנְךָּ. אֶנְתְּקֶךָ, לְשׁוֹן ״הַתִּיקֵם כַּצֹּאן לְטִבְחָה״ (ירמיה יב:ג); ״עַד הִתִּיקוּנוֹ אוֹתָם״ (יהושע ח:ו); וְהַנּוּ״ן יְתֵרָה בּוֹ. וּמִדְרַשׁ אַגָּדָה (פסיקתא דרב כהנא כד:יא): בִּמְקוֹם שֶׁנִּתַּק – נִתְקַן; שֶׁעָשָׂה תְּשׁוּבָה בְּבָבֶל, וְנִשְׁאַל הַקָּדוֹשׁ בָּרוּךְ הוּא עַל שֶׁנִּשְׁבַּע כִּתְבוּ אֶת הָאִישׁ הַזֶּה עֲרִירִי, וְנוֹלַד לוֹ זְרֻבָּבֶל בְּבָבֶל, וְנֶאֱמַר לוֹ עַל פִּי הַנָּבִיא: ״בַּיּוֹם הַהוּא אֶקָּחֲךָ זְרֻבָּבֶל בֶּן שְׁאַלְתִּיאֵל עַבְדִּי וְשַׂמְתִּיךָ כַּחוֹתָם״ (חגי ב:כג); כְּלַפֵּי שֶׁאָמַר לְאָבִיו: אִם יִהְיֶה חוֹתָם עַל יַד יְמִינִי, אֶנְתְּקֶנּוּ:\",2,0],[2,121,22,26,\"וְהֵטַלְתִּי. לְשׁוֹן הַשְׁלָכָה:\",1,0],[2,121,22,27,\"מְנַשְּׂאִים אֶת נַפְשָׁם. לְשׁוֹן תַּנְחוּמִים; שֶׁנַּפְשָׁם מִתְנַשְּׂאָה לְהִתְנַחֵם וְלוֹמַר: עוֹד נָשׁוּב לְאַרְצֵנוּ:\",1,0],[2,121,22,28,\"הַעֶצֶב נִבְזֶה. תְּמִיהָּ הוּא: שֶׁמָּא צוּרָה נִשְׁבָּר וְנִבְזֶה הָאִישׁ הַזֶּה שֶׁהֻשְׁלַךְ מֵעַל פָּנַי כְּמִי שֶׁאֵין חֵפֶץ בּוֹ?!\",1,0],[2,121,22,28,\"נָפוּץ. נִשְׁבָּר, כְּמוֹ ״כִּכְלִי יוֹצֵר תְּנַפְּצֵם״ (תהלים ב:ט). וַאֲחֵרִים הִגִּיהוּ הַעֶצֶב כְּמוֹ הָעֲצַבִּים, ״מְעַצְּבִין אֶת הַקָּטָן״ בְּמַסֶּכֶת שַׁבָּת (קמז.), כְּלוֹמַר: הַאַתָּה נִבְזֶה וְנָפוּץ בְּעֵינֶיךָ כְּעוֹלֵל קָטָן שֶׁמְּעַצְּבִין אוֹתוֹ? מילויילי״ר בְּלַעַז. אֵין זֶה כְּדַי:\",2,0],[2,121,22,28,\"הוּטְלוּ. הֻשְׁלְכוּ, לְשׁוֹן הַשְׁלָכָה שֶׁאֵין לָהּ תְּקוּמָה, כְּמוֹ ״כִּי יִפֹּל לֹא יוּטָל״ (תהלים לז:כד):\",3,0],[2,121,22,29,\"אֶרֶץ אֶרֶץ אָרֶץ. מֵאַרְצוֹ גָּלָה אֶל אֶרֶץ אַחֶרֶת, וְאַתְּ, אֶרֶץ יִשְׂרָאֵל, שִׁמְעִי דְּבַר ה׳. דָּבָר אַחֵר: אֶרֶץ אֶרֶץ, אֶרֶץ שֶׁהוּא אֶרֶץ שֶׁבָּאֲרָצוֹת, שֶׁהָיְתָה חֲשׁוּבָה שֶׁבְּכֻלָּן. דָּבָר אַחֵר (בבא בתרא לח.): אֶרֶץ יִשְׂרָאֵל שָׁלֹשׁ אֲרָצוֹת הָיוּ בָּהּ: יְהוּדָה וְעֵבֶר הַיַּרְדֵּן וְהַגָּלִיל:\",1,0],[2,121,22,30,\"גֶּבֶר. אֲשֶׁר לֹא יִצְלַח בְּיָמָיו כִּתְבוּהוּ:\",1,0],[2,121,23,1,\"הוֹי רוֹעִים. מַלְכֵי יְהוּדָה:\",1,0],[2,121,23,2,\"לֹא פְקַדְתֶּם אוֹתָם. לֹא נִזְהַרְתֶּם לְשָׁמְרָם:\",1,0],[2,121,23,4,\"וְלֹא יִפָּקֵדוּ. וְלֹא יֶחְסְרוּ, לָשׁוֹן ״וְלֹא נִפְקַד מִמֶּנּוּ אִישׁ״ (במדבר לא:מט):\",1,0],[2,121,23,5,\"וְהִשְׂכִּיל. וְיַצְלִיחַ:\",1,0],[2,121,23,6,\"ה׳ צִדְקֵנוּ. ה׳ מַצְדִּיק אוֹתָנוּ בְּיָמָיו שֶׁל זֶה:\",1,0],[2,121,23,9,\"לַנְּבִיאִים נִשְׁבַּר לִבִּי בְקִרְבִּי. לְדִבְרֵי הַנְּבִיאִים, הָאוֹמְרִים שָׁלוֹם יִהְיֶה לָכֶם, נִשְׁבַּר לִבִּי. רָחֲפוּ – הוֹלְכִים וְנָעִים, כְּכַנְפֵי צִפּוֹר הַמְרַחֵף עַל קִנּוֹ; טְרַנְבְּלִיר״ט בְּלַעַז:\",1,0],[2,121,23,9,\"מִפְּנֵי ה׳. שֶׁאֲנִי שׁוֹמֵעַ מִמֶּנּוּ גְּזֵרָה רָעָה זֹאת:\",2,0],[2,121,23,10,\"מִפְּנֵי אָלָה. שְׁבוּעַת שֶׁקֶר:\",1,0],[2,121,23,10,\"אָבְלָה. חֲרֵבָה:\",2,0],[2,121,23,10,\"מְרוּצָתָם. קוֹרְשָׁ״א בְּלַעַ״ז, וְיוֹנָתָן תִּרְגֵּם לְשׁוֹן רָצוֹן:\",3,0],[2,121,23,10,\"לֹא כֵן. לֹא בַדִּין:\",4,0],[2,121,23,11,\"גַּם נָבִיא גַּם כֹּהֵן. אֲפִילּוּ אֵלּוּ, שֶׁהַכֹּל לְמֵדִין מֵהֶם:\",1,0],[2,121,23,11,\"גַּם בְּבֵיתִי מָצָאתִי רָעָתָם. שֶׁהֶעֱמִידוּ דְּמוּת בַּהֵיכָל:\",2,0],[2,121,23,12,\"כַּחֲלַקְלַקּוֹת. אֶרֶץ חֲלָקָה, שֶׁהָרֶגֶל מַחְלֶקֶת בָּהּ וְהָאָדָם נוֹפֵל:\",1,0],[2,121,23,12,\"כַּחֲלַקְלַקּוֹת בָּאֲפֵלָה. כִּשָּׁלוֹן עַל כִּשָּׁלוֹן: חֲלַקְלַקּוֹת בָּאוֹר יֵשׁ כִּשָּׁלוֹן, אֲפֵלָה בְּלֹא חֲלַקְלַקּוֹת יֵשׁ כִּשָּׁלוֹן:\",2,0],[2,121,23,13,\"וּבִנְבִיאֵי שֹׁמְרוֹן רָאִיתִי תִפְלָה. קֹדֶם שֶׁגָּלוּ:\",1,0],[2,121,23,14,\"וּבִנְבִיאֵי יְרוּשָׁלִַם. אֲנִי רוֹאֶה עַתָּה שַׁעֲרוּרָה, דָּבָר מְגֻנֶּה:\",1,0],[2,121,23,14,\"וְחִזְּקוּ יְדֵי מְרֵעִים. אוֹמְרִים לָרְשָׁעִים: שָׁלוֹם יִהְיֶה לָכֶם:\",2,0],[2,121,23,14,\"לְבִלְתִּי שָׁבוּ. שֶׁלֹּא יָשׁוּבוּ הַמְּרֵעִים אִישׁ מֵרָעָתוֹ:\",3,0],[2,121,23,17,\"וְכֹל הוֹלֵךְ בִּשְׁרִירוּת לִבּוֹ וְגוֹ׳. וּלְכָל הוֹלֵךְ בִּשְׁרִירוּת לִבּוֹ וְגוֹ׳:\",1,0],[2,121,23,18,\"מִי עָמַד בְּסוֹד ה׳. וְיִשְׁמַע אֶת הַנִּגְזָר מִלְּפָנָיו? אוֹתוֹ שֶׁהִקְשִׁיב דְּבַר תּוֹרָתוֹ וְיִשְׁמַע לְמִצְוֹתָיו, וְלֹא הָרְשָׁעִים הָאֵלֶּה! שְׁמִיעָה הָרִאשׁוֹנָה שֶׁבַּמִּקְרָא זֶה – שְׁמִיעָה מַמָּשׁ; שְׁמִיעָה הָאַחֲרוֹנָה – קַבָּלָה:\",1,0],[2,121,23,19,\"מִתְחוֹלֵל. מִשְׁתַּכֵּן, מְחַזֵּר לִשְׁכּוֹן; וְעַל רֹאשׁ רְשָׁעִים יִשְׁכּוֹן:\",1,0],[2,121,23,20,\"מְזִמּוֹת. לְשׁוֹן מַחֲשָׁבָה:\",1,0],[2,121,23,22,\"וְאִם עָמְדוּ בְּסוֹדִי וְיַשְׁמִיעוּ דְבָרַי וגו׳. הָיָה לָהֶם לְהַשְׁמִיעַ דְּבָרַי וְתוֹרָתִי אֶת עַמִּי, וְלֹא לְהַטְעוֹתָם בָּהּ מֵעָלַי:\",1,0],[2,121,23,23,\"הַאֱלֹהֵי מִקָּרֹב. שֶׁאֵינִי רוֹאֶה אֶלָּא בְּסָמוּךְ לִי, וְאֵין בִּי כֹּחַ לִשְׁפּוֹט אֶת הַתַּחְתּוֹנִים שֶׁהֵם רְחוֹקִים מִמֶּנִּי, וְאֵינִי יוֹדֵעַ בְּמַעֲשֵׂיהֶם?!\",1,0],[2,121,23,24,\"אִם יִסָּתֵר אִישׁ. זֶהוּ כֶּפֶל תְּמִיהָה הַאֱלֹהֵי מִקָּרֹב, כְּדֶרֶךְ כָּל תְּמִיהוֹת הַכְּפוּלוֹת:\",1,0],[2,121,23,26,\"עַד מָתַי. יִנָּבְאוּ שֶׁקֶר? וְכִי יֵשׁ בְּלִבָּם שֶׁל הַנְּבִיאִים הַלָּלוּ, הַנִּבְּאִים שָׁקֶר, לְקַיֵּם מַחְשְׁבוֹתָם שֶׁהֵם חוֹשְׁבִים לְהַשְׁכִּיחַ אֶת עַמִּי שְׁמִי וְגוֹ׳?!\",1,0],[2,121,23,26,\"תַּרְמִית. לְשׁוֹן מִרְמָה:\",2,0],[2,121,23,28,\"יְסַפֵּר חֲלוֹם. יְסַפְּרֶנּוּ לְשׁוֹן הֲבַאי כִּשְׁאָר חֲלוֹמוֹת, וְלֹא יְחַזְּקֶנּוּ בְּדִבְרֵי נְבוּאָה:\",1,0],[2,121,23,28,\"מַה לַתֶּבֶן אֶת הַבָּר. מַה עִנְיַן שֶׁקֶר אֵצֶל אֱמֶת?\",2,0],[2,121,23,28,\"אֶת הַבָּר. עִם הַבָּר:\",3,0],[2,121,23,29,\"הֲלֹא כֹה דְבָרִי כָּאֵשׁ. לֹא הָיָה לָהֶם לִטְעוֹת וּלְדַמּוֹת חֲלוֹמוֹת לוֹמַר שֶׁהֵם נְבוּאָה, כִּי דְּבַר נְבוּאָה כְּשֶׁבָּאָה בְּפִי הַנָּבִיא בִּגְבוּרָה הִיא בָאָה בּוֹ כְּאֵשׁ בּוֹעֶרֶת, כָּעִנְיָן שֶׁנֶּאֱמַר ״וַתְּהִי בְלִבִּי כְּאֵשׁ בֹּעֶרֶת״ (ירמיה כ:ט), וְאוֹמֵר ״וְיַד ה׳ עָלַי חֲזָקָה״ (יחזקאל ג:יד):\",1,0],[2,121,23,29,\"וּכְפַטִּישׁ. פִּי״ק בְּלַעַ״ז, וְיֵשׁ אוֹמֵר מַרְטִיי״ל בְּלַעַ״ז:\",2,0],[2,121,23,30,\"מְגַנְּבֵי דְבָרַי אִישׁ מֵאֵת רֵעֵהוּ. אִישׁ מֵאֵת רֵעֵהוּ יֵשׁ לָהֶם מְרַגְּלִים אֵצֶל נְבִיאֵי הָאֱמֶת, וְשׁוֹמְעִין סִגְנוֹן שֶׁלָּהֶם שֶׁהֵם מִתְנַבְּאִים בּוֹ, וְאוֹמְרִין נְבוּאַת שֶׁקֶר בְּאוֹתוֹ לָשׁוֹן, כְּמוֹ שֶׁעָשָׂה חֲנַנְיָה בֶּן עַזּוּר: שָׁמַע אֶת יִרְמְיָה מִתְנַבֵּא בַּשּׁוּק הָעֶלְיוֹן ״הִנְנִי שׁוֹבֵר אֶת קֶשֶׁת עֵילָם״ (ירמיה מט:לה), וְהוּא נִיבָּא בַּשּׁוּק הַתַּחְתּוֹן ״שָׁבַרְתִּי אֶת עוֹל מֶלֶךְ בָּבֶל״ (ירמיה כח:ב), כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ בְּסַנְהֶדְרִין (פט.):\",1,0],[2,121,23,31,\"הַלּוֹקְחִים לְשׁוֹנָם. הַמְּלַמְּדִים לְשׁוֹנָם לוֹמַר שִׁקְרֵיהֶם בְּלָשׁוֹן נְאֻם ה׳, כִּנְבִיאֵי הָאֱמֶת, לְמַעַן יַאֲמִינוּ בָם:\",1,0],[2,121,23,32,\"וּבְפַחֲזוּתָם. לְשׁוֹן תִּמָּהוֹן, אִישְׁטוֹרְדִיזוֹ״ן בְּלַעַ״ז:\",1,0],[2,121,23,33,\"מַה מַשָּׂא ה׳. לְשׁוֹן שְׂחוֹק, לְפִי שֶׁנְּבוּאָתוֹ לָהֶם לְמַשָּׂא:\",1,0],[2,121,23,33,\"וְאָמַרְתָּ אֲלֵיהֶם אֶת מַה מַשָּׂא וְנָטַשְׁתִּי וגו׳. אוֹמְרִים לָכֶם מָה הַמַּשָּׂא, אַתֶּם לְמַשָּׂא לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא אָמַר שֶׁיִּטּוֹשׁ וְיַשְׁלִיךְ אֶתְכֶם מֵעַל זְרוֹעוֹתָיו מִשָּׁמַיִם אֶרֶץ (איכה ב:א), כָּךְ שָׁמַעְתִּי:\",2,0],[2,121,23,33,\"וְנָטַשְׁתִּי. וְעָזַבְתִּי:\",3,0],[2,121,23,36,\"כִּי הַמַּשָּׂא יִהְיֶה לְאִישׁ דְּבָרוֹ. אַף עַל פִּי שֶׁאַתֶּם מְהַפְּכִין אֶת הַמַּשָּׂא לִגְנַאי, מַשָּׂא דְּבַר ה׳ לְאִישׁ דְּבָרוֹ וּלְאִישׁ עֲצָתוֹ הוּא מְגַלֵּהוּ (ישעיהו מ:יג), וְאַתֶּם מְהַפְּכִין אוֹתוֹ לִלְשׁוֹן מַשָּׂאוֹי. זוֹ לֹא שָׁמַעְתִּי כֵּן, וְהִיא עִקָּר; אֲבָל כָּךְ שָׁמַעְתִּי: כִּי הַמַּשָּׂאוֹי יִהְיֶה מַשָּׂאוֹי שֶׁל פֻּרְעָנוּת לְמִי שֶׁאוֹמְרוֹ, הַשּׁוֹאֵל מַה מַּשָּׂא. עִנְיָן אַחֵר: מַשָּׂא ה׳. לְשׁוֹן נְבוּאָה הוּא; וְהָיָה הַנָּבִיא הַשֶּׁקֶר שׁוֹאֵל לַנָּבִיא הָאֱמֶת לֵאמֹר לוֹ אֶת דְּבַר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּלָשׁוֹן שֶׁבָּא הַסִּיגְנוֹן אֵלָיו, וְהַסִּיגְנוֹן לֹא הָיָה מְפָרֵשׁ הַדִּבּוּר כָּל כָּךְ, וְהָיָה נְבִיא הַשֶּׁקֶר מְהַפֵּךְ אֶת הַפֵּרוּשׁ לְצַד אַחֵר, וְהָיָה מְדַבֵּר בְּדוּגְמַת נְבִיא הָאֱמֶת כְּדֵי שֶׁיַּאֲמִינוּ בּוֹ; וְכֵן עָשָׂה חֲנַנְיָה בֶּן עַזּוּר. לָכֵן הוּא אוֹמֵר: אַל תִּשְׁאֲלוּ מַשָּׂא ה׳ – אֶת לְשׁוֹן הַסִּיגְנוֹן, אֶלָּא מַה דִּבֵּר וּמַה עָנָה – אֶת פֵּרוּשׁ הַדָּבָר; שַׁאֲלוּ לַנָּבִיא הָאֱמֶת לֵאמֹר לָהֶם מַה הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר וּלְהֵיכָן נוֹטִין אֶת דְּבָרָיו:\",1,0],[2,121,23,36,\"כִּי הַמַּשָּׂא יִהְיֶה לְאִישׁ דְּבָרוֹ. סִיגְנוֹן סְתָם; הַקָּדוֹשׁ בָּרוּךְ הוּא אֲמָרוֹ סְתָם לְאִישׁ עֲצָתוֹ, שֶׁאֵינוֹ חָשׁוּד לְהוֹפְכוֹ, וְאַתֶּם שׁוֹאֲלִים אוֹתוֹ כְּדֵי לְהוֹפְכוֹ. וַהֲפַכְתֶּם אֶת דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזֶהוּ שֶׁאָמַר לְמַעְלָה מִגַּנְּבֵי דְבָרַי אִישׁ מֵאֵת רֵעֵהוּ, גַּם זֶה לָשׁוֹן מְיֻתָּר:\",2,0],[2,121,23,37,\"כֹּה תֹאמַר אֶל הַנָּבִיא. כְּשֶׁאַתֶּם בָּאִים לִשְׁאֹל דְּבָרַי מֵאֵת הַנָּבִיא:\",1,0],[2,121,23,39,\"וְנָשִׁיתִי. לְשׁוֹן ״גִּיד הַנָּשֶׁה״ (בראשית לב:לג), וְלָשׁוֹן ״נָשְׁתָה גְבוּרָתָם״ (ירמיה נא:ל); קוֹפֵץ וּמְטַלְטֵל מִמָּקוֹם לְמָקוֹם:\",1,0],[2,121,24,1,\"דּוּדָאֵי. קְדֵרוֹת:\",1,0],[2,121,24,1,\"מוּעָדִים. מוּכָנִים:\",2,0],[2,121,24,1,\"הֶחָרָשׁ וְהַמַּסְגֵּר. תַּלְמִידֵי חֲכָמִים שֶׁגָּלוּ עִם יְכָנְיָה (סדר עולם רבה כה), וּכְבָר פֵּירַשְׁתִּיו בְּסֵפֶר מְלָכִים (מלכים ב כד:טז) הֶחָרָשׁ וְהַמַּסְגֵּר לימייטראה ליפורטי״ר בְּלַעַז. לָשׁוֹן אַחֵר: הֶחָרָשׁ וְהַמַּסְגֵּר – הֶחָרָשׁ לְשׁוֹן חֶרֶשׁ, הַמַּסְגֵּר לְשׁוֹן סָגוּר, כְּלוֹמַר: חֲכָמִים גְּדוֹלִים בַּתּוֹרָה, שֶׁכְּשֶׁהָיָה אֶחָד מֵהֶם מְדַבֵּר, הַכֹּל שׁוֹתְקִים. מַסְגֵּר שֶׁהָיוּ סוֹגְרִים וְאֵין פּוֹתֵחַ (ישעיה כב:כב; סנהדרין לח.):\",3,0],[2,121,24,2,\"כִּתְאֵנֵי הַבַּכֻּרוֹת. שֶׁבִּשְּׁלוּ כָּל צָרְכָּן בִּתְחִלַּת בִּכּוּרֵי תְאֵנִים, שֶׁהֵם חֲבִיבוֹת עַל מוֹצְאֵיהֶם בְּרֵאשִׁיתָם (ישעיה כח:ד):\",1,0],[2,121,24,5,\"כֵּן אַכִּיר אֶת גָּלוּת וגו׳. הֲרֵי זֶה מִקְרָא מְסֹרָס: כֵּן אַכִּיר לְטוֹבָה אֶת גָּלוּת יְהוּדָה שֶׁהִגְלֵיתִי כְּבָר, יְכָנְיָה וְגָלוּתוֹ:\",1,0],[2,121,24,6,\"אֶתּוֹשׁ. לְשׁוֹן עֲקִירָה:\",1,0],[2,121,24,9,\"לְזַעֲוָה לְרָעָה לְכָל מַמְלְכוֹת הָאָרֶץ. שֶׁיִּשְׁמְעוּ הָרָעָה הַבָּאָה עֲלֵיהֶם וְיָזוּעוּ:\",1,0],[2,121,24,9,\"וְלִשְׁנִינָה. שֶׁיִּשְׁנְנוּ וִידַבְּרוּ הַכֹּל בְּפֻרְעָנוּתָם:\",2,0],[2,121,25,1,\"בַּשָּׁנָה הָרְבִיעִית. שָׁנָה שֶׁנִּתְחַתֵּם גְּזַר דִּינָם שֶׁיִּגְלוּ וְשֶׁיִּשְׁתּוּ כּוֹס הַחֵמָה, כְּמוֹ שֶׁאָמוּר בָּעִנְיָן: קַח אֶת כּוֹס וְגוֹ׳. וְקוֹדֶם גְּזַר דִּין אָמַר לַנָּבִיא לְהוֹכִיחָם, אוּלַי יָשׁוּבוּ וְלֹא יִתְחַתֵּם גְּזַר דִּינָם:\",1,0],[2,121,25,3,\"שָׁלֹשׁ וְעֶשְׂרִים. יֹאשִׁיָּהוּ מָלַךְ שְׁלֹשִׁים וְאַחַת (מלכים ב כב:א), צֵא מֵהֶם שְׁתֵּים עֶשְׂרֵה שָׁנָה, נִשְׁאֲרוּ תְּשַׁע עֶשְׂרֵה, וְאַרְבַּע שֶׁל בְּנוֹ (ירמיה א:ג), הֲרֵי שָׁלֹשׁ וְעֶשְׂרִים:\",1,0],[2,121,25,3,\"אַשְׁכֵּים וְדַבֵּר. לְשׁוֹן הוֹוֶה: הָיִיתִי מַשְׁכִּים וּמְדַבֵּר תָּמִיד:\",2,0],[2,121,25,10,\"קוֹל רֵחַיִם. סִימָן הוּא לִסְעוּדַת בְּרִית מִילָה, עַל שֵׁם שֶׁטּוֹחֲנִין וְשׁוֹחֲקִין לָהּ סַמְמָנִין לִרְפוּאָה:\",1,0],[2,121,25,10,\"אוֹר נֵר. סִימַן מִשְׁתֶּה. כָּךְ שָׁנִינוּ בְּסַנְהֶדְרִין (סנהדרין לב:):\",2,0],[2,121,25,13,\"אֶת כָּל הַכָּתוּב. עַל בָּבֶל:\",1,0],[2,121,25,13,\"בַּסֵּפֶר הַזֶּה. בְּסוֹפוֹ:\",2,0],[2,121,25,14,\"כִּי עָבְדוּ בָם. כְּמוֹ כִּי יַעַבְדוּ בָם, בִּבְנֵי בָבֶל:\",1,0],[2,121,25,14,\"גַּם הֵמָּה גּוֹיִם רַבִּים. מָדַי וּפָרָס:\",2,0],[2,121,25,15,\"כּוֹס הַיַּיִן הַחֵמָה. נְבוּאַת הַפֻּרְעָנוּת:\",1,0],[2,121,25,15,\"וְהִשְׁקִיתָה אוֹתוֹ. הִנָּבֵא לָהֶם שֶׁלֹּא תָשׁוּב עוֹד בְּשׁוּם תְּשׁוּבָה:\",2,0],[2,121,25,16,\"וְהִתְגֹּעֲשׁוּ. ״וְיִשְׁתַּגְּעוּן״ (תרגום יונתן):\",1,0],[2,121,25,16,\"וְהִתְהוֹלָלוּ. לְשׁוֹן ״הוֹלֵלוּת״ (קהלת י:יג), יִשְׁתַּטּוּ:\",2,0],[2,121,25,18,\"כַּיּוֹם הַזֶּה. כַּאֲשֶׁר הֵם הַיּוֹם; לְאַחַר הַחֻרְבָּן כָּתַב יִרְמְיָה סִפְרוֹ:\",1,0],[2,121,25,20,\"וְאֵת כָּל הָעֶרֶב. ״כָּל סוּמְכְוָתָא״ (תרגום יונתן) אֲשֶׁר עֲרֻבַּת פַּרְעֹה וּמִשְׁעַנְתּוֹ עֲלֵיהֶם לְעֶזְרָה. הָעֶרֶב גרנטיא״ה בְּלַעַ״ז:\",1,0],[2,121,25,22,\"וְאֵת מַלְכֵי הָאִי. כָּל אֵלּוּ שֶׁמָּנָה עַד כָּאן, שְׁכֵינֵי אֶרֶץ יִשְׂרָאֵל הֵם:\",1,0],[2,121,25,23,\"קְצוּצֵי פֵאָה. הַמּוּקְצִים בִּקְצֵה אוֹתָהּ הָרוּחַ:\",1,0],[2,121,25,24,\"מַלְכֵי עֲרָב. עֲרַבְיָא (כתובות סז.):\",1,0],[2,121,25,24,\"וְאֵת כָּל מַלְכֵי הָעֶרֶב. ״סוּמְכְוָותָא״ שֶׁל עַרְבִיִּים:\",2,0],[2,121,25,26,\"שֵׁשַׁךְ. הוּא בָּבֶל בְּא״ת ב״ש (תנחומא, קרח יב):\",1,0],[2,121,25,27,\"וּקְיוּ. כְּאָדָם שֶׁשּׁוֹתֶה יוֹתֵר מִדַּאי, שֶׁמֵּקִיא:\",1,0],[2,121,25,27,\"הַחֶרֶב. הַתִּגָּר שֶׁל הַמִּלְחָמָה:\",2,0],[2,121,25,29,\"מֵחֵל. מַתְחִיל:\",1,0],[2,121,25,30,\"עַל נָוֵהוּ. מִתְאַבֵּל עַל חֻרְבַּן בֵּיתוֹ:\",1,0],[2,121,25,30,\"הֵידָד. לָשׁוֹן הוּא שֶׁצּוֹעֲקִין עוֹשֵׂי מְלָאכָה כְּבֵדָה בְּקוֹל רָם, לְזָרֵז זֶה אֶת זֶה לְהִתְחַזֵּק, וְדוֹרְכֵי גִּתּוֹת רְגִילִין בָּהּ:\",2,0],[2,121,25,30,\"יַעֲנֶה. כָּל לְשׁוֹן עֲנִיָּה צְעָקַת קוֹל רָם הִיא:\",3,0],[2,121,25,31,\"נִשְׁפָּט. מִתְוַכֵּחַ בַּדִּין:\",1,0],[2,121,25,32,\"מִגּוֹי אֶל גּוֹי. שֶׁאֲנִי מְסַכְסְכָן זֶה בָּזֶה:\",1,0],[2,121,25,32,\"מִיַּרְכְּתֵי. כְּתַרְגּוּמוֹ: ״מִסְּיָפֵי״:\",2,0],[2,121,25,34,\"הֵילִילוּ. לְשׁוֹן ״יְלָלָה״ (צפניה א:י):\",1,0],[2,121,25,34,\"וְהִתְפַּלְּשׁוּ. הִתְגַּלְגְּלוּ בֶּעָפָר, וֹוטְרְלִי״ר בְּלַעַ״ז:\",2,0],[2,121,25,34,\"וּתְפוֹצוֹתִיכֶם. הֲרֵי זֶה מִקְרָא קָצָר, כְּלוֹמַר: וּתְפוּצוֹתֵיכֶם תִּקְרַבְנָה לָבֹא:\",3,0],[2,121,25,34,\"כִּכְלִי חֶמְדָּה. כְּלוֹמַר: אִם תֹּאמְרוּ חֲשׁוּבִים אֲנַחְנוּ, הַרְבֵּה יֵשׁ כְּלֵי חֶמְדָּה שֶׁל זְכוּכִית, נוֹפְלִים וּמִשְׁתַּבְּרִים וְאוֹבְדִים:\",4,0],[2,121,25,37,\"וְנָדַמּוּ. לְשׁוֹן חֻרְבָּה, לְשׁוֹן ״הֲדִמָּנוּ״, ״וְנִדְּמָה שָׁם״ (ירמיה ח:יד):\",1,0],[2,121,25,38,\"עָזַב כַּכְּפִיר וְגוֹ׳. ״גָּלָה מַלְכָּא מִכַּרְכֵּיהּ״ (תרגום יונתן), כַּכְּפִיר הָעוֹזֵב אֶת סֻכּוֹ:\",1,0],[2,121,25,38,\"הַיּוֹנָה. מִשְׁתַּכֶּרֶת בְּיַיִן, כֵּן תִּרְגֵּם יוֹנָתָן. דָּבָר אַחֵר: לְשׁוֹן אוֹנָאָה:\",2,0],[2,121,26,1,\"בְּרֵאשִׁית מַמְלְכוּת. פָּרָשָׁה זוֹ תַּחְתּוֹנָה קָדְמָה לָעֶלְיוֹנָה אַרְבַּע שָׁנִים (ירמיה כה:א):\",1,0],[2,121,26,10,\"וַיִּשְׁמְעוּ שָׂרֵי יְהוּדָה. שֶׁתָּפְשׂוּ נְבִיאֵי הַשֶּׁקֶר וְהַכֹּהֲנִים אֶת יִרְמְיָה:\",1,0],[2,121,26,10,\"בְּפֶתַח שַׁעַר ה׳ הֶחָדָשׁ. אֲחֵרִים הִגִּיהוּ: כְּשֶׁגָּלָה יְהוֹיָכִין וְקְצָת כְּלֵי בֵּית אֱלֹהֵינוּ עִמּוֹ, שָׁבְרוּ חֵילוֹ שֶׁל נְבוּכַדְנֶצַּר שַׁעַר הַמִּזְרָחִי, וְחָזַר צִדְקִיָּהוּ וְתִקְּנוֹ וְחִדְּשׁוֹ; לְכָךְ נִקְרָא חָדָשׁ:\",2,0],[2,121,26,18,\"מִיכָה הַמּוֹרַשְׁתִּי. ״דְּמִן מָרֵישָׁא״ (תרגום יונתן):\",1,0],[2,121,26,18,\"עִיִּים. גַּלִּים:\",2,0],[2,121,26,19,\"וַיְחַל. לְשׁוֹן תְּפִלָּה:\",1,0],[2,121,26,19,\"וַאֲנַחְנוּ עֹשִׂים רָעָה גְדוֹלָה. אִם נַהֲרֹג אוֹתוֹ:\",2,0],[2,121,26,20,\"וְגַם אִישׁ הָיָה מִתְנַבֵּא. מִי שֶׁאָמַר זוֹ לֹא אָמַר זוֹ; עַד כָּאן דִּבְרֵי צַדִּיקִים, וְעָמְדוּ רְשָׁעִים שֶׁהָיוּ שָׁם וְאָמְרוּ: גַּם אִישׁ מִתְנַבֵּא וְגוֹ׳, כְּשֵׁם שֶׁאוּרִיָּה נֶהֱרַג, יֵהָרֵג יִרְמְיָה; כָּךְ מְפֹרָשׁ בְּסִפְרֵי (ספרי במדבר פיסקא פח):\",1,0],[2,121,27,1,\"בְּרֵאשִׁית מַמְלֶכֶת יְהוֹיָקִם. שָׁלֹשׁ שָׁנִים לִפְנֵי שֶׁמָּלַךְ נְבוּכַדְנֶצַּר (ירמיה כה:א), נִתְנַבֵּא עָלָיו שֶׁיִּמְלֹךְ:\",1,0],[2,121,27,2,\"מוֹסֵרוֹת. הֵם רְצוּעוֹת הָעוֹל, שֶׁקּוֹרִין קוֹיוּנְגְמְ״שׁ:\",1,0],[2,121,27,3,\"וְשִׁלַּחְתָּם אֶל מֶלֶךְ אֱדוֹם. בִּימֵי צִדְקִיָּהוּ בַּשָּׁנָה הָרְבִיעִית לְמָלְכוֹ (ירמיה כח:א); שֶׁעָשָׂהוּ נְבוּכַדְנֶצַּר שַׁלִּיט עַל חֲמִשָּׁה מְלָכִים:\",1,0],[2,121,27,3,\"מֶלֶךְ אֱדוֹם וּמֶלֶךְ מוֹאָב וּמֶלֶךְ בְּנֵי עַמּוֹן וְגוֹ׳. אֵלּוּ חֲמִשָּׁה מְלָכִים נָתַן נְבוּכַדְנֶצַּר תַּחַת יָדוֹ שֶׁל צִדְקִיָּהוּ (איכה רבה ב, יד). חֲמֵשׁ עֶשְׂרֵה שָׁנָה הָיוּ עַל צַוָּארוֹ, מִשָּׁנָה אַחַת לִיהוֹיָקִים עַד הַשָּׁנָה הָרְבִיעִית לְצִדְקִיָּהוּ, שֶׁשְּׁבָרָם הֵימֶנּוּ חֲנַנְיָה בֶּן עַזּוּר (ירמיה כח:י):\",2,0],[2,121,27,6,\"עַבְדִּי. שֶׁיַּעֲשֶׂה רְצוֹנִי לִפָּרַע מִשּׂוֹנְאַי:\",1,0],[2,121,27,7,\"וְאֶת בְּנוֹ. אֱוִיל מְרֹדַךְ:\",1,0],[2,121,27,7,\"וְאֶת בֶּן בְּנוֹ. בֵּלְשַׁאצַּר:\",2,0],[2,121,27,7,\"עַד בֹּא עֵת אַרְצוֹ. שֶׁיָּבֹאוּ דָּרְיָוֶשׁ הַמָּדִי וְכוֹרֶשׁ וְיַהַרְגוּ אֶת בֵּלְשַׁאצַּר:\",3,0],[2,121,27,12,\"וְאֶל צִדְקִיָּה מֶלֶךְ יְהוּדָה דִּבַּרְתִּי וְגוֹ׳. כָּל זֶה אָמַר יִרְמְיָהוּ אֶל שְׁלוּחֵי הַמְּלָכִים:\",1,0],[2,121,27,16,\"הִנֵּה כְלֵי בֵית ה׳. שֶׁגָּלוּ עִם יְכָנְיָה (להלן כ):\",1,0],[2,121,27,19,\"הַמְּכוֹנוֹת. תִּרְגֵּם יוֹנָתָן: ״בְּסִיסַיָּא״, כְּמוֹ ״אֶת הַכִּיּוֹר וְאֶת כַּנּוֹ״ (שמות לה:טז):\",1,0],[2,121,27,20,\"בַּגְלוֹתוֹ. כְּמוֹ בְּהַגְלוֹתוֹ:\",1,0],[2,121,27,20,\"חֹרֵי. כְּמוֹ ״שָׂרֵי״ (ירמיה כד:א):\",2,0],[2,121,27,22,\"עַד יוֹם פָּקְדִי אוֹתָם. בִּימֵי כּוֹרֶשׁ, כְּמוֹ שֶׁמְפוֹרָשׁ בְּסֵפֶר עֶזְרָא (עזרא א:ז-יא):\",1,0],[2,121,28,1,\"וַיְהִי בַּשָּׁנָה הַהִיא. כְּשֶׁהִגִּיעַ אוֹתוֹ הַזְּמַן שֶׁהִשְׁלִיט נְבוּכַדְנֶצַּר אֶת צִדְקִיָּהוּ עַל חֲמֵשֶׁת מְלָכִים, שֶׁהָיָה יִרְמְיָה אוֹמֵר שְׁלִיחוּתוֹ וּמְשַׁלֵּחַ הַמּוֹסֵרוֹת וְהַמּוֹטוֹת אֶל הַמְּלָכִים בְּיַד מַלְאָכֵיהֶם (ירמיה כז:ב-ג):\",1,0],[2,121,28,1,\"בְּרֵאשִׁית מַמְלֶכֶת צִדְקִיָּה. בִּתְחִלָּה שֶׁהִשְׁלִיטוֹ עַל חֲמֵשֶׁת הַמְּלָכִים, וְאִי אֶפְשָׁר לוֹמַר בִּתְחִלַּת מַלְכוּתוֹ, שֶׁהֲרֵי נֶאֱמַר בַּשָּׁנָה הָרְבִיעִית. אוֹתָהּ שָׁנָה יָרַד לְהַקְבִּיל אֶת פְּנֵי נְבוּכַדְנֶצַּר בְּבָבֶל, וְשָׂרָיָה שַׂר הַמְּנוּחָה עִמּוֹ, וּכְמוֹ שֶׁנֶּאֱמַר בְּסוֹף הַסֵּפֶר (ירמיה נא:נט), וְהִשְׁלִיטוֹ עַל הַמְּלָכִים:\",2,0],[2,121,28,1,\"אָמַר אֵלַי וגו׳. אָמְרוּ רַבּוֹתֵינוּ (סדר עולם רבה כה): מִי הִטְעָה אֶת חֲנַנְיָה? שָׁמַע שֶׁהָיָה יִרְמְיָה מִתְנַבֵּא בַּשּׁוּק הָעֶלְיוֹן: ״הִנְנִי שֹׁבֵר אֶת קֶשֶׁת עֵילָם״ (ירמיה מט:לה), וּנְבוּאָה זוֹ בְּסוֹף הַסֵּפֶר נֶאֶמְרָה, בְּרֵאשִׁית מַמְלֶכֶת צִדְקִיָּה, כְּמוֹ שֶׁמְּפֹרָשׁ שָׁם (ירמיה מט:לד); וּלְפִי שֶׁעֵילָם סְמוּכָה לְבָבֶל, עָמַד הוּא בַּשּׁוּק הַתַּחְתּוֹן וְדָרַשׁ וְדָן קַל וָחֹמֶר: וּמָה עֵילָם, שֶׁלֹּא בָּאָה אֶלָּא לַעֲזֹר אֶת הַכַּשְׂדִּים וְכוּ׳; כְּמָה שֶׁהִיא בְּסַנְהֶדְרִין (פט.):\",3,0],[2,121,28,6,\"יַעֲשֶׂה. פַאצָ״א בְּלַעַ״ז:\",1,0],[2,121,28,6,\"יקם. לְשׁוֹן תְּפִלָּה (של״ש שטי״ן אלו ע״ד והביא״ו לבית הכל״א לא סדר״ן הר״ב המחב״ר) (אָמֵן כֵּן יַעֲשֶׂה וְגוֹ׳. בַּעֲלֵי אַגָּדָה אוֹמְרִים: כָּךְ אָמַר לוֹ הַלְוַאי וְיִתְקַיְּמוּ דְּבָרֶיךָ אֲנִי מִשְׁתַּכֵּר וְאַתָּה נִפְסַד, אֲנִי כֹּהֵן וְאוֹכֵל קָדְשֵׁי שָׁמַיִם אִם יַעֲמֹד הַבַּיִת בְּבִנְיָנוֹ, וְאַתָּה גִּבְעוֹנִי כְּדָכָתִיב כָּאן) אֲשֶׁר מִגִּבְעוֹן, וְתִהְיֶה לִי עֶבֶד חוֹטֵב עֵצִים וְשׁוֹאֵב מַיִם (וּמוֹרֵה צֶדֶק שֶׁלֹּא פֵּרֵשׁ נָקִיט לֵהּ טַעַם רַבּוֹתֵינוּ, שֶׁלָּמְדוּ מִכָּאן: כָּל הַמַּחֲנִיף לָרָשָׁע סוֹף נוֹפֵל בְּיָדוֹ אוֹ בְּיַד בְּנוֹ אוֹ בְּיַד בֶּן בְּנוֹ, שֶׁכֵּן יִרְאִיָּיה בֶּן שֶׁלֶמְיָה בֶּן חֲנַנְיָה תָּפְשׂוּ לְבַסּוֹף וְהֵבִיאוּ לְבֵית הַכֶּלֶא):\",2,0],[2,121,28,7,\"אַךְ שְׁמַע נָא וְגוֹ׳. עַד הַנָּבִיא אֲשֶׁר יִנָּבֵא לְשָׁלוֹם, אָמַר: אֲנִי מִתְנַבֵּא פּוּרְעָנִיּוֹת; אִם לֹא יָבֹא, אֵינִי שַׁקְרָן, הַקָּדוֹשׁ בָּרוּךְ הוּא ״נִחָם עַל הָרָעָה״ (יואל ב:יג), אֲבָל הַנָּבִיא אֲשֶׁר יִנָּבֵא לְשָׁלוֹם, בְּבֹא דְּבַר הַנָּבִיא יִוָּדַע וְגוֹ׳, אֲבָל אִם לֹא יָבֹא דְּבָרוֹ – שַׁקְרָן הוּא, שֶׁנֶּאֱמַר: ״לֹא אִישׁ אֵל וִיכַזֵּב וְגוֹ׳״ (במדבר כג:יט). כָּךְ דָּרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, וירא יג):\",1,0],[2,121,28,14,\"אֶת חַיַּת הַשָּׂדֶה נָתַתִּי לוֹ. שֶׁרָכַב עַל אֲרִי וְקָשַׁר תַּנִּין בְּרֹאשׁוֹ (שבת קמט:):\",1,0],[2,121,28,16,\"הַשָּׁנָה אַתָּה מֵת. וּבַשָּׁנָה הַבָּאָה תִּקָּבֵר:\",1,0],[2,121,28,17,\"בַּשָּׁנָה הַהִיא בַּחֹדֶשׁ הַשְּׁבִיעִי. וַהֲלֹא אֵין חֹדֶשׁ שְׁבִיעִי מִן הַשָּׁנָה? אֶלָּא מֵת עֶרֶב רֹאשׁ הַשָּׁנָה, וְצִוָּה לְבָנָיו שֶׁיִּקְבְּרוּהוּ לְאַחַר רֹאשׁ הַשָּׁנָה וְלֹא קֹדֶם, וְיַעֲלִימוּ אֶת מִיתָתוֹ אוֹתוֹ הַיּוֹם, כְּדֵי לַעֲשׂוֹת נְבוּאַת יִרְמְיָה שֶׁקֶר (ירושלמי סנהדרין יא,ה):\",1,0],[2,121,29,2,\"וְהַגְּבִירָה. אֵם הַמֶּלֶךְ (מלכים א טו:יג):\",1,0],[2,121,29,8,\"יַשִּׁיאוּ. לְשׁוֹן הֲסָתָה, כְּמוֹ ״הַנָּחָשׁ הִשִּׁיאַנִי״ (בראשית ג:יג):\",1,0],[2,121,29,12,\"וּקְרָאתֶם אֹתִי וְהֲלַכְתֶּם. בִּדְרָכַי; וַהֲרֵי זֶה מִקְרָא קָצָר:\",1,0],[2,121,29,16,\"אֶל הַמֶּלֶךְ. צִדְקִיָּהוּ, אֲשֶׁר לֹא גָּלָה:\",1,0],[2,121,29,17,\"כַּתְּאֵנִים הַשֹּׁעָרִים. לְשׁוֹן ״שַׁעֲרוּרִיָּה״ (הושע ו:י):\",1,0],[2,121,29,18,\"וּלְחֶרְפָּה. שֶׁיְּחָרְפוּ אוֹתָם, דִּישְׁטְרוּוִי״ר בְּלַעַ״ז; וְכֵן כָּל חֶרְפָּה שֶׁבַּמִּקְרָא:\",1,0],[2,121,29,22,\"אֲשֶׁר קָלָם. לְשׁוֹן ״קָלוּי בָּאֵשׁ״ (ויקרא ב:יד):\",1,0],[2,121,29,23,\"וַיְנַאֲפוּ אֶת נְשֵׁי רֵעֵיהֶם. כְּמוֹ שֶׁמְּפֹרָשׁ בְּסַנְהֶדְרִין (סנהדרין צג.): כֹּה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: שִׁכְבִי עִם חֲבֵרִי:\",1,0],[2,121,29,23,\"וָעֵד. לְשׁוֹן עֵדוּת:\",2,0],[2,121,29,24,\"הַנֶּחֱלָמִי. שֵׁם מָקוֹם:\",1,0],[2,121,29,26,\"נְתָנְךָ כֹהֵן. אֶל צְפַנְיָה כָּתַב כֵּן (ירמיה כא:א):\",1,0],[2,121,29,26,\"פְּקִידִים. מְמֻנִּים:\",2,0],[2,121,29,26,\"מַהְפֶּכֶת. כִּיפָּה:\",3,0],[2,121,29,26,\"הַצִּינוֹק. סַדָּן, צִיפְ״שׁ בְּלַעַ״ז:\",4,0],[2,121,29,28,\"כִּי עַל כֵּן שָׁלַח. כִּי יֵשׁ לְךָ לִגְעֹר בּוֹ עַל אֲשֶׁר שָׁלַח אֵלֵינוּ בָּבֶל לֵאמֹר אֲרֻכָּה הִיא גָּלוּתְכֶם שָׁם:\",1,0],[2,121,29,28,\"עַל כֵּן. כְּמוֹ עַל אֲשֶׁר:\",2,0],[2,121,30,3,\"כִּי הִנֵּה יָמִים בָּאִים. וְלֹא תֹאמַר לָמָּה אֶכְתְּבֶנּוּ כִּי יֹאבְדוּ כֻּלָּם וְאֵין קוֹרֵא בּוֹ וְאֵין זוֹכְרוֹ עוֹד כִּי הִנֵּה יָמִים בָּאִים וְגוֹ׳:\",1,0],[2,121,30,5,\"קוֹל חֲרָדָה שָׁמָעְנוּ. יֵשׁ פּוֹתְרִין עַל שְׁמוּעַת בָּבֶל שֶׁהָיוּ חֲרֵדִים מִמֶּנָּה אוֹתָם שֶׁגָּלוּ שָׁם, וּמִדְרַשׁ אַגָּדָה עַל מִלְחֶמֶת גּוֹג וּמָגוֹג:\",1,0],[2,121,30,6,\"אִם יוֹלֵד זָכָר. אִם דֶּרֶךְ לִזְכָרִים לָלֶדֶת שֶׁיֹּאחֲזוּם חֲבָלִים כַּיּוֹלֵדָה:\",1,0],[2,121,30,6,\"חֲלָצָיו. כְּמוֹ מָתְנָיו:\",2,0],[2,121,30,7,\"הַיּוֹם הַהוּא. יוֹם הֲרִיגַת בֵּלְשַׁאצַּר וּמַפֶּלֶת בָּבֶל, עִנְיָן אַחֵר יוֹם מַפֶּלֶת גּוֹג:\",1,0],[2,121,30,8,\"אֶשְׁבֹּר עֻלּוֹ. יָסוּר עוֹל הָאֻמּוֹת מֵעַל יִשְׂרָאֵל:\",1,0],[2,121,30,10,\"וְאַתָּה אַל תִּירָא. מִכָּל הָרָעוֹת אֲשֶׁר תִּרְאֶה בָּאָה עַל בָּבֶל אֲשֶׁר אַתָּה בְתוֹכָהּ:\",1,0],[2,121,30,10,\"וְשַׁאֲנַן. כְּמוֹ וְשָׁקַט:\",2,0],[2,121,30,11,\"וְיִסַּרְתִּיךָ לַמִּשְׁפָּט. בְּדִין חָסוּךְ:\",1,0],[2,121,30,11,\"וְנַקֵּה לֹא אֲנַקֶּךָ. לְשׁוֹן טִיאוּט, הַשְׁמֵד:\",2,0],[2,121,30,12,\"אָנוּשׁ לְשִׁבְרֵךְ נַחְלָה. שִׁבְרֵךְ אנפר״ש בְּלַעַ״ז:\",1,0],[2,121,30,13,\"לְמָזוֹר. רְפוּאָה, אֵין אָדָם סָבוּר שֶׁתְּהֵא לָךְ תְּשׁוּעָה:\",1,0],[2,121,30,13,\"תְּעָלָה. רְפוּאָה, לְשׁוֹן הוֹעִיל:\",2,0],[2,121,30,14,\"מוּסַר אַכְזָרִי. יִסּוּרֵי אַכְזָרִיּוּת. הַמּוּסַר אַכְזָרִי הוּא:\",1,0],[2,121,30,16,\"לָכֵן. שְׁבוּעָה:\",1,0],[2,121,30,16,\"שֹׁאסַיִךְ לִמְשִׁסָּה. לְשׁוֹן בִּיזָּה, וְכֵן תִּרְגֵּם יוֹנָתָן: ״וִיהוֹן עָדַיִךְ לַעֲדִי״:\",2,0],[2,121,30,17,\"אֲרֻכָה. רְפוּאָה:\",1,0],[2,121,30,18,\"וְאַרְמוֹן. הַמִּקְדָּשׁ:\",1,0],[2,121,30,19,\"וְהִכְבַּדְתִּים. שֶׁיִּהְיוּ עַם כָּבֵד:\",1,0],[2,121,30,19,\"וְלֹא יִצְעָרוּ. כְּמוֹ יִמְעָטוּ:\",2,0],[2,121,30,21,\"אַדִּירוֹ. שַׂר שֶׁלּוֹ:\",1,0],[2,121,30,21,\"עָרַב אֶת לִבּוֹ. לְשׁוֹן עֵרָבוֹן, פרוויל״א הטינ״א בְּלַעַ״ז:\",2,0],[2,121,30,21,\"לָגֶשֶׁת אֵלַי. לַמִּלְחָמָה, לִמְחוֹת בְּיָדִי:\",3,0],[2,121,30,23,\"מִתְגּוֹרֵר. חוֹנֶה וְדָר, לְשׁוֹן ״אֶרֶץ מְגוּרֵי״ (בראשית לז:א). וְדוּגְמָתוֹ ״וְסַעַר מִתְחוֹלֵל״ (ירמיה כג:יט) הָאָמוּר בַּמִּקְרָא הָאַחֵר, הוּא זֶה, שֶׁשְּׁנֵיהֶם לְשׁוֹן חֲנִיָּה:\",1,0],[2,121,30,23,\"עַל רֹאשׁ רְשָׁעִים. עַל רֹאשׁ הַגּוֹיִים:\",2,0],[2,121,31,2,\"מָצָא חֵן. בְּעֵינֵי דּוֹר הַמִּדְבָּר:\",1,0],[2,121,31,2,\"שְׂרִידֵי חָרֶב. מִצְרַיִם וְהָעֲמָלֵקִי וְהַכְּנַעֲנִי:\",2,0],[2,121,31,2,\"הָלוֹךְ לְהַרְגִּיעוֹ יִשְׂרָאֵל. בְּהוֹלִיכָם לִנְחוֹל אֶרֶץ מַרְגּוֹעָם:\",3,0],[2,121,31,3,\"מֵרָחוֹק. בִּזְכוּת אָבוֹת (בראשית יז:ז):\",1,0],[2,121,31,3,\"נִרְאָה לִי. אֲנִי הַנָּבִיא, וְאָמַר לִי לֵאמֹר לִכְנֶסֶת יִשְׂרָאֵל אַהֲבַת עוֹלָם אֲהַבְתִּיךְ:\",2,0],[2,121,31,4,\"עוֹד אֶבְנֵךְ וְנִבְנֵית. בִּנְיָנִים שְׁנַיִם הָיוּ לָךְ עַל יְדֵי אָדָם, לְכָךְ חָרְבוּ. עוֹד אֶבְנֵךְ אֲנִי בְּעַצְמִי בִּנְיָן שְׁלִישִׁי, וְנִבְנֵית לְעוֹלָם. תַּעְדִּי תִּתְקַשְּׁטִי:\",1,0],[2,121,31,5,\"וְחִלֵּלוּ. בַּשָּׁנָה הָרְבִיעִית יְחַלְּלוּ אֶת פִּרְיָם לִפְדּוֹתוֹ בְּכֶסֶף (ויקרא יט:כד):\",1,0],[2,121,31,6,\"נוֹצְרִים. צוֹפִים בְּרָאשֵׁי מִגְדָּלִים גְּבוֹהִים לְהַכְרִיז קוֹל נִשְׁמָע לְמֵרָחוֹק. לָשׁוֹן אַחֵר: נוֹצְרִים כְּמוֹ ״נֹצֵר חֶסֶד לָאֲלָפִים״ (שמות לד:ז), לְשׁוֹן שְׁמִירָה. כְּלוֹמַר, יֶשׁ יוֹם שֶׁיִּקְרְאוּ אוֹתָם שֶׁשָּׁמְרוּ הַתּוֹרָה וְיֹאמְרוּ קוּמוּ. וְכֵן תִּרְגֵּם יוֹנָתָן: ״אֲרֵי אִית אֲרִיכוּת יוֹמַיָּא וְסַגִּי טוּבָא דְּעָתִיד לְמֵיתֵי לְצַדִּיקַיָּא דְּנַטְרוּ אוֹרַיְתִי מִלְּקַדְמִין״:\",1,0],[2,121,31,7,\"וְצַהֲלוּ בְּרֹאשׁ הַגּוֹיִם. בְּמִגְדָּלוֹת גְּבוֹהִים כְּדֵי שֶׁיִּשְׁמְעוּ לְמֵרָחוֹק:\",1,0],[2,121,31,8,\"בָּם עִוֵּר וּפִסֵּחַ. אֲפִילּוּ הַנִּכְשָׁלִים שֶׁבָּהֶם לֹא אֶמְאַס:\",1,0],[2,121,31,9,\"בִּבְכִי יָבֹאוּ. עַל יְדֵי תְּפִלָּה וּתְשׁוּבָה:\",1,0],[2,121,31,10,\"מְזָרֵה. אֶסְפְּרֵיינְ״שׁ בְּלַעַ״ז:\",1,0],[2,121,31,12,\"וְנָהֲרוּ. יֵאָסְפוּ כְּמוֹ נָהָר:\",1,0],[2,121,31,14,\"דָּשֶׁן. שָׁמֵן:\",1,0],[2,121,31,15,\"קוֹל בְּרָמָה נִשְׁמָע. ״קָלָא בְּרוּם עָלְמָא אִישְׁתְּמַע, קָל בֵּית יִשְׂרָאֵל דְּבָכְיָן עַל יִרְמְיָה נְבִיָּיא כַּד שְׁלַח יָתֵיהּ נְבוּזַרְאֲדָן מֵרָמָתָא״. לָשׁוּב מֵאַחַר הַגּוֹלִים אֶל גְּדַלְיָה בֶּן אֲחִיקָם, כְּמוֹ שֶׁאָמַר בְּסֵפֶר זֶה (ירמיה מ:א):\",1,0],[2,121,31,15,\"רָחֵל מְבַכָּה עַל בָּנֶיהָ. מִדְרַשׁ אַגָּדָה אָמַר שֶׁהָלְכוּ אָבוֹת וְאִמָּהוֹת לְפַיֵּס אֶת הַהַקָּדוֹשׁ בָּרוּךְ הוּא עַל שֶׁהֶעֱמִיד מְנַשֶּׁה דְּמוּת בַּהֵיכָל, וְלֹא נִתְפַּיֵּס. נִכְנְסָה רָחֵל, אָמְרָה לְפָנָיו: רִבּוֹנוֹ שֶׁל עוֹלָם רַחֲמֵי מִי מְרֻבִּים רַחֲמֶיךָ אוֹ רַחֲמֵי בָּשׂר וָדָם, הֱוֵי אוֹמֵר רַחֲמֶיךָ מְרֻבִּים. וַהֲלֹא אֲנִי הִכְנַסְתִּי צָרָתִי בְּתוֹךְ בֵּיתִי, שֶׁכָּל עֲבוֹדָה שֶׁעָבַד יַעֲקֹב אֶת אָבִי לֹא עָבַד אֶלָּא בִּשְׁבִילִי; כְּשֶׁבָּאתִי לִיכָּנֵס לַחֻפָּה הִכְנִיסוּ אֶת אֲחוֹתִי, וְלֹא דַי שֶׁשָּׁתַקְתִּי אֶלָּא שֶׁמָּסַרְתִּי לָהּ סִימָנִי. אַף אַתָּה, אִם הִכְנִיסוּ בָנֶיךָ צָרָתְךָ בְּבֵיתְךָ, שְׁתוֹק לָהֶם. אָמַר לָהּ: יָפֶה לִמַּדְתְּ סַנֵּגוֹרְיָא, יֵשׁ שָׂכָר לִפְעֻלָּתֵךְ וּלְצִדְקָתֵךְ שֶׁמָּסַרְתְּ סִימָנֵךְ לַאֲחוֹתֵךְ:\",2,0],[2,121,31,18,\"מִתְנוֹדֵד. קוֹמְפְּלֵיְינְ״ט בְּלַעַ״ז, לְשׁוֹן ״מִי יָנוּד לָךְ״ (ירמיה טו:ה):\",1,0],[2,121,31,18,\"יִסַּרְתַּנִי. בְּיִסּוּרִין אַתָּה הַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,121,31,18,\"כְּעֵגֶל לֹא לוּמָּד. פוּשָׁאגוּיֵילוֹנִ״י בְּלַעַ״ז, לְשׁוֹן ״מַלְמַד הַבָּקָר״ (שופטים ג:לא). הָיִיתִי בַּתְּחִלָּה, לְכָךְ חָטָאתִי לְךָ:\",3,0],[2,121,31,19,\"נִחַמְתִּי. אֲנִי מִתְחָרֵט עַל תּוֹעֲבוֹתַי:\",1,0],[2,121,31,19,\"הִוָּדְעִי. שֶׁהִתְבּוֹנַנְתִּי בְּעַצְמִי שֶׁמָּעַלְתִּי, אפרינו״יי בְּלַעַ״ז:\",2,0],[2,121,31,19,\"חֶרְפַּת נְעוּרָי. שֶׁיְּכוֹלִים אוֹיְבַי לְחָרְפֵנִי עַל חַטֹּאת נְעוּרָי:\",3,0],[2,121,31,20,\"הֲבֵן יַקִּיר לִי אֶפְרַיִם. הֵן דִּבְרֵי שְׁכִינָה, כְּלוֹמַר הוּא מִתְנוֹדֵד וַאֲנִי לִבִּי נֶהְפַּךְ עָלַי לְרַחֵם, שֶׁמָּא בְּנִי יַקִּירִי הוּא, כְּמוֹ שֶׁאֵין לוֹ אֶלָּא בֵּן אֶחָד שֶׁהוּא עוֹשֶׂה לוֹ כָּל רְצוֹנוֹ. שַׁעֲשׁוּעִים אישבניימני״ץ בְּלַעַ״ז:\",1,0],[2,121,31,20,\"מִדֵּי דַבְּרִי בּוֹ. בְּכָל עֵת שֶׁאֲנִי מְדַבֵּר בּוֹ. וּמִדְרַשׁ וַיִּקְרָא רַבָּה (ויקרא רבה ב,ג): דַּי דִּבּוּרִי שֶׁנָּתַתִּי בּוֹ, שֶׁלִּמַּדְתִּיו תּוֹרָתִי, לְרַחֵם עָלָיו:\",2,0],[2,121,31,21,\"הַצִּיבִי לָךְ צִיֻּנִים. סִימָנִים בְּדַרְכֵי אֲבוֹתַיִךְ הַטּוֹבִים:\",1,0],[2,121,31,21,\"תַּמְרוּרִים. תְּמָרִים קְטַנִּים נְטוּעִים לְסִימָן בַּדֶּרֶךְ. וּפְשׁוּטוֹ שֶׁל מִקְרָא, עֲשִׂי סִימָנִים לָדַעַת הַדֶּרֶךְ שֶׁהָלַכְתְּ בָּהּ מֵאֶרֶץ יִשְׂרָאֵל לְבָבֶל, שֶׁתַּחְזִירִי בְּאוֹתוֹ דֶּרֶךְ. כְּלוֹמַר, כִּי וַדַּאי תָּשׁוּבִי מִשָּׁם:\",2,0],[2,121,31,21,\"דֶּרֶךְ הָלָכְתְּ. הָלַכְתִּי כְּתִיב, וְכָל מָקוֹם שֶׁהָלַכְתְּ הָלַכְתִּי אֲנִי עִמָּךְ. וְיוֹנָתָן תִּרְגֵּם שִׂימִי לָךְ תַּמְרוּרִים ״הִתְפַּלֵּל בְּמָרַר נַפְשֵׁךְ״ (וּמְנַחֵם פֵּרֵשׁ תַּמְרוּרִין עִנְיַן מוֹעֵל, וְכֵן פֵּרֵשׁ ״וְתִימֲרוֹת עָשָׁן״ (יואל ג:ג) סא״א):\",3,0],[2,121,31,22,\"תִּתְחַמָּקִין. תִּסְתְּרִי מִמֶּנִּי, שֶׁאַתְּ בּוֹשָׁה לָשׁוּב אֱלֵי מִפְּנֵי דַּרְכֵּךְ. הִנֵּה חֲדָשָׁה נִבְרֵאת בָּאָרֶץ, שֶׁהַנְּקֵבָה תַּחֲזֹר אַחַר הַזָּכָר לְבַקְּשׁוֹ שֶׁיִּשָּׂאֶנָּה, לְשׁוֹן ״וַאֲסוֹבְבָהּ בָּעִיר אֲבַקְּשָׁהּ וְגוֹ׳״ (שִׁיר הַשִּׁירִים ג:ב); וּמִשּׁוּם רַבִּי יְהוּדָה הַדַּרְשָׁן שָׁמַעְתִּי: נְקֵבָה תְּסוֹבֵב לִהְיוֹת גָּבֶר, אֲנִי נְתַתִּיךְ כְּבַת הַנּוֹטֶלֶת עִשּׂוּר נְכָסִים שִׁבְעָה אֻמּוֹת מִשִּׁבְעִים, סוֹף שֶׁתִּטְּלִי הַכֹּל כְּבֶן זָכָר שֶׁהוּא יוֹרֵשׁ הַכֹּל:\",1,0],[2,121,31,26,\"עַל זֹאת הֱקִיצוֹתִי. כָּךְ אָמַר יִרְמְיָה, כָּל מַה שֶּׁהָיִיתִי יָשֵׁן וְנִרְדָּם בִּנְבוּאַת פֻּרְעָנוּת, בַּנְּבוּאָה הַזֹּאת הֱקִיצוֹתִי מִתַּרְדֵּמָתִי:\",1,0],[2,121,31,26,\"עָרְבָה. נְעֵמָה:\",2,0],[2,121,31,27,\"זֶרַע אָדָם וְזֶרַע בְּהֵמָה. הַטּוֹבִים וְהַסְּכָלִים שֶׁבָּהֶם, אֲנִי אֶזְרָעֵם כֻּלָּם לִהְיוֹת זֶרַע שֶׁלִּי. זֶרַע אָדָם וְזֶרַע בְּהֵמָה תִּרְגֵּם יוֹנָתָן: ״אֲקִימִינוּן כִּבְנֵי אֱנָשָׁא וְאַצְלְחִינוּן כִּבְעִירָא״, שֶׁאֵין עֲוֹנוֹתֶיהָ נִפְקָדִין עָלֶיהָ:\",1,0],[2,121,31,29,\"בֹּסֶר. פְּרִי שֶׁלֹּא נִגְמַר, וְהוּא מַקְהֶה אֶת הַשִּׁנַּיִם:\",1,0],[2,121,31,29,\"וְשִׁנֵּי בָנִים תִּקְהֶינָה. הַבָּנִים יִלְקוּ בַּעֲוֹן אָבוֹת:\",2,0],[2,121,31,35,\"לְאוֹר. אֵיאַקְלַארְזִי״ר בְּלַעַ״ז, וְכֵן תִּרְגֵּם יוֹנָתָן ״לְאַנְהָרָא״:\",1,0],[2,121,31,35,\"רוֹגַע הַיָּם. מְנִידוֹ וּמַרְתִּיחוֹ וְנַעֲשֶׂה קְמָטִים קְמָטִים, כְּמוֹ ״עוֹרִי רָגַע״ (איוב ז:ה):\",2,0],[2,121,31,36,\"יָמֻשׁוּ. כְּמוֹ ״לֹא יָמִישׁ״ (שמות יג:כב):\",1,0],[2,121,31,37,\"אִם יִמַּדּוּ שָׁמַיִם. כַּמָּה גָּבְהָם:\",1,0],[2,121,31,37,\"גַּם אֲנִי אֶמְאַס. בְּיִשְׂרָאֵל, כְּלוֹמַר כְּשֵׁם שֶׁהֵם לֹא יִמַּדּוּ וְלֹא יֵחָקְרוּ, כָּךְ יִשְׂרָאֵל לֹא יִמָּאֲסוּ בְּכָל אֲשֶׁר חָטְאוּ:\",2,0],[2,121,31,40,\"הָעֵמֶק הַפְּגָרִים. עֵמֶק שֶׁנָּפְלוּ שָׁם פִּגְרֵי מַחֲנֵה סַנְחֵרִיב (מלכים ב יט:לה; ישעיה לז:לו):\",1,0],[2,121,31,40,\"וְהַדֶּשֶׁן. מְקוֹם שֶׁפֶךְ הַדֶּשֶׁן שֶׁהָיָה חוּץ לִירוּשָׁלַיִם, יוֹסִיפוּ עַל הָעִיר וְיַכְנִיסוּ כָּל זֶה לְתוֹךְ חוֹמוֹתֶיהָ. וּנְבוּאָה זוֹ עֲתִידָה לָבֹא:\",2,0],[2,121,31,40,\"הַשְּׁדֵמוֹת. קַנְפַנְיָ״א בְּלַעַ״ז:\",3,0],[2,121,32,2,\"צָרִים. לְשׁוֹן ״מָצוֹר״ (דברים כ:יט):\",1,0],[2,121,32,2,\"בַּחֲצַר הַמַּטָּרָה. לְשׁוֹן בֵּית הַמִּשְׁמָר:\",2,0],[2,121,32,5,\"עַד פָּקְדִי אֹתוֹ. פְּקֻדַּת כָּל הָאָדָם הִיא הַמִּיתָה (במדבר טז:כט):\",1,0],[2,121,32,6,\"וַיֹּאמֶר יִרְמְיָהוּ וגו׳. לֹא לְצִדְקִיָּהוּ אָמַר כֵּן, אֶלָּא פֵּירֵשׁ הַכָּתוּב לָמָּה כְּלָאוֹ, וְחוֹזֵר לְדִבּוּרוֹ הָרִאשׁוֹן לְפָרֵשׁ מַה הַדָּבָר אֲשֶׁר הָיָה אֶל יִרְמְיָהוּ:\",1,0],[2,121,32,7,\"בָּא אֵלֶיךָ. עַל פִּי הַדִּבּוּר:\",1,0],[2,121,32,11,\"אֶת סֵפֶר הַמִּקְנָה. שְׁטַר הַמְּכִירָה:\",1,0],[2,121,32,11,\"אֶת הֶחָתוּם וְגוֹ׳. עִם חֲתִימָתוֹ, כְּשֶׁהוּא חָתוּם כְּדָת וְחֹק:\",2,0],[2,121,32,11,\"וְאֶת הַגָּלוּי. שֶׁהוּחְזַק בְּבֵית דִּין עַל פִּי עֵדָיו, וְכָתְבוּ וְחָתְמוּ הַדַּיָּנִין אַשְׁרְתָּא דְדַיָּנֵי, הוּא קִיּוּם הַשְּׁטָרוֹת (כתובות כא:), לַעֲשׂוֹת הַדָּבָר גָּלוּי וּמְפֻרְסָם, פֶּן יָמוּתוּ הָעֵדִים. וְרַבּוֹתֵינוּ פֵּרְשׁוּ לְעִנְיַן גֵּט פָּשׁוּט וּמְקֻשָּׁר בְּבָבָא בַּתְרָא (קס.-קס:):\",3,0],[2,121,32,12,\"לְעֵינֵי חֲנַמְאֵל דּוֹדִי. וְעַד עַכְשָׁו קְרָאוֹ בֶּן דּוֹדִי, שֶׁמָּא שְׁנַיִם הָיוּ, וְאִם אֵין זֹאת לֹא יָדַעְתִּי מַהוּ. וְיֵשׁ נוֹטִים לוֹמַר דּוֹדוֹ וּבֶן דּוֹדוֹ הָיָה חֲנַמְאֵל לְיִרְמְיָה, כְּגוֹן רְאוּבֵן נָשָׂא אֶת בַּת שִׁמְעוֹן אָחִיו וְיָלְדָה לוֹ נְמוּאֵל, וּכְבָר הוֹלִיד שִׁמְעוֹן יָמִין, הֲרֵי יָמִין דּוֹדוֹ לִנְמוּאֵל, שֶׁבֶּן אֲחִי אִמּוֹ הוּא וְגַם בֶּן דּוֹדוֹ, שֶׁהוּא בֶּן שִׁמְעוֹן אֲחִי אָבִיו שֶׁל נְמוּאֵל. וְאֵינָהּ הִיא הַמִּדָּה, שֶׁלֹּא מָצִינוּ בְּכָל הַמִּקְרָא אָח הָאֵם קָרוּי דּוֹד:\",1,0],[2,121,32,14,\"כֹּה אָמַר וְגוֹ׳. אַל תֹּאמַר: לְחִנָּם אֲנִי מַצְנִיעָם, שֶׁהֲרֵי הַכֹּל גּוֹלִים:\",1,0],[2,121,32,15,\"כִּי כֹה אָמַר ה׳. סוֹפָן לִקְנוֹת בָּתִּים:\",1,0],[2,121,32,17,\"לֹא יִפָּלֵא. לֹא יִכָּחֵד; וְיוֹדֵעַ אַתָּה שֶׁסּוֹפֵנוּ לִגְלוֹת, וְלָמָּה אָמַרְתָּ לִי לִקְנוֹת שָׂדֶה?\",1,0],[2,121,32,18,\"וּמְשַׁלֵּם עֲוֺן אָבוֹת אֶל חֵיק. הַדּוֹר הַזֶּה, הַהוֹלְכִים אַחֲרֵי אֲבוֹתֵיהֶם בְּדֶרֶךְ הָרָעָה:\",1,0],[2,121,32,18,\"הַגָּדוֹל הַגִּבּוֹר. וְלֹא אָמַר וְהַנּוֹרָא, אָמַר: עוֹבְדֵי אֱלִילִים מְרַקְּדִין בְּהֵיכָלוֹ, אַיֵּה נוֹרְאוֹתָיו? בְּמַסֶּכֶת יוֹמָא (יומא סט:):\",2,0],[2,121,32,20,\"וּבָאָדָם. בִּשְׁאָר אֲנָשִׁים. דָּבָר אַחֵר: אוֹתוֹת שֶׁהָיוּ שְׁקוּלִין לְיִשְׂרָאֵל וּלְמִצְרַיִם, כֵּיצַד? ״וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ וַיָּאֶר הַלַּיְלָה״ (שמות יד:כ) – אוֹתוֹ מַזָּל שֶׁשִּׁמֵּשׁ חֹשֶׁךְ לְמִצְרַיִם, שִׁמֵּשׁ אוֹר לְיִשְׂרָאֵל; מִדְרַשׁ אַגָּדָה:\",1,0],[2,121,32,23,\"וַתַּקְרֵא אוֹתָם. הִקְרֵיתָ אוֹתָם; לְשׁוֹן ״מִקְרֶה״ (שמואל א ו:ט):\",1,0],[2,121,32,24,\"וַאֲשֶׁר דִּבַּרְתָּ. רָעָה עָלֶיהָ, הָיָה וּבָא:\",1,0],[2,121,32,25,\"וְהָעִיר נִתְּנָה. וְלָמָּה לִי שָׂדֶה?\",1,0],[2,121,32,27,\"הֲמִמֶּנִּי יִפָּלֵא. וְכִי הָעֲתִידוֹת עֲלוּמוֹת מִמֶּנִּי?\",1,0],[2,121,32,31,\"לְמִן הַיּוֹם אֲשֶׁר בָּנוּ אוֹתָהּ. בְּיוֹם שֶׁהוּסַד הַבַּיִת, נָשָׂא שְׁלֹמֹה אֶת בַּת פַּרְעֹה (ויקרא רבה יב, ה):\",1,0],[2,121,32,33,\"וְלַמֵּד אוֹתָם. לְשׁוֹן פָּעוּל, אפרננ״ט בְּלַעַ״ז:\",1,0],[2,121,32,37,\"הִנְנִי מְקַבְּצָם. בְּרַחֲמִים, מִכָּל אֲשֶׁר הִדַּחְתִּים שָׁם בְּאַפִּי:\",1,0],[2,121,33,1,\"עָצוּר. בְּבֵית הַכֶּלֶא:\",1,0],[2,121,33,2,\"כֹּה אָמַר ה׳ עֹשָׂהּ. הָעוֹשֶׂה זֹאת:\",1,0],[2,121,33,3,\"קְרָא אֵלַי וְאֶעֱנֶךָּ. לְהוֹדִיעֲךָ הָעֲתִידוֹת:\",1,0],[2,121,33,3,\"וּבְצוּרוֹת. שְׁמוּרוֹת בְּלִבִּי לַעֲשׂוֹתָם:\",2,0],[2,121,33,4,\"הַנְּתֻצִים אֶל הַסֹּלְלוֹת. לַעֲשׂוֹת מֵהֶם סֹלְלוֹת, תִּלִּים שֶׁצְּבוּרִים לְמַעְלָה, אֲשֶׁר בּוֹנִים בְּנֵי הָעִיר לַעֲלוֹת אֶל הַסֹּלְלוֹת, לְהִלָּחֵם מֵעֲלֵיהֶם אֶל הַכַּשְׂדִּים:\",1,0],[2,121,33,4,\"וְאֶל הֶחָרֶב. ״לְתַקְּפָא שׁוּרָא מִן קֳדָם דְּקָטְלִין בְּחַרְבָּא״ (תרגום יונתן):\",2,0],[2,121,33,5,\"וּלְמַלְּאָם אֶת פִּגְרֵי הָאָדָם. וְאֶת הַבָּתִּים אֲשֶׁר נָתְצוּ עוֹשִׂים קְבָרוֹת לַפְּגָרִים שֶׁנֶּהֱרָגִים בְּתוֹךְ הָעִיר:\",1,0],[2,121,33,5,\"וַאֲשֶׁר הִסְתַּרְתִּי וְגוֹ׳. כֹּה אָמַר ה׳ הִנְנִי מַעֲלֶה לָהּ וְגוֹ׳:\",2,0],[2,121,33,6,\"עֲתֶרֶת שָׁלוֹם. בִּרְכַּת שָׁלוֹם; שֶׁלוּ״ד בְּלַעַ״ז:\",1,0],[2,121,33,12,\"נְוֵה רוֹעִים. מְדוֹר רוֹעִים:\",1,0],[2,121,33,13,\"עוֹד תַּעֲבֹרְנָה הַצֹּאן וגו׳. יֵצְאוּ וְיָבֹאוּ יִשְׂרָאֵל עַל יְדֵי מַנְהִיג הוֹלֵךְ בְּרֹאשָׁם (מיכה ב:יג):\",1,0],[2,121,33,17,\"לֹא יִכָּרֵת. כְּרִיתוּת עוֹלָם, אֶלָּא אִם יִפְסוֹק, סוֹפוֹ לַחֲזוֹר:\",1,0],[2,121,33,18,\"כָּל הַיָּמִים. לֹא יִכָּרֵת לָהֶם זֶרַע הָרָאוּי לְהַעֲלוֹת עוֹלָה וּלְהַקְטִיר מִנְחָה:\",1,0],[2,121,33,20,\"אִם תָּפֵרוּ אֶת בְּרִיתִי הַיּוֹם. אִם תּוּכְלוּ לְהָפֵר אֶת בְּרִיתִי אֲשֶׁר כָּרַתִּי אֶת הַיּוֹם וְאֶת הַלַּיְלָה לִהְיוֹתָם בְּעִתָּם, אֲשֶׁר כָּרַתִּי לְנֹחַ וּבָנָיו ״וְיוֹם וָלַיְלָה לֹא יִשְׁבֹּתוּ״ (בראשית ח:כב):\",1,0],[2,121,33,24,\"שְׁתֵּי הַמִּשְׁפָּחוֹת. הַמַּלְכוּת וְהַכְּהֻנָּה (תנחומא, לך כ):\",1,0],[2,121,33,24,\"וְאֶת עַמִּי יִנְאָצוּן. וּבַדְּבָרִים הָאֵלֶּה הֵם גּוֹרְמִים לְעַמִּי לְנָאֵץ מִהְיוֹת גּוֹי לִי:\",2,0],[2,121,33,24,\"לִפְנֵיהֶם. לִפְנֵי דִּבְרֵיהֶם אֵלֶּה, שֶׁמְּלַמְּדִין אוֹתָןלוֹמַר: לֹא יָשׁוּב הַקָּדוֹשׁ בָּרוּךְ הוּא מֵחֲרוֹנוֹ עוֹד, וְלֹא תוֹעִיל לָכֶם תְּשׁוּבָה:\",3,0],[2,121,33,25,\"אִם לֹא בְרִיתִי וְגוֹ׳. אִי אֶפְשָׁר שֶׁלֹּא יִתְקַיֵּם הַבְּרִית שֶׁכָּרַתִּי לְיוֹם וָלַיְלָה לִהְיוֹת בְּעִתָּם, וְאִי אֶפְשָׁר לְחֻקּוֹת שָׁמַיִם וָאָרֶץ לִיבָּטֵל כְּאִלּוּ לֹא שַׂמְתִּים, ״גַּם זֶרַע יַעֲקֹב וְגוֹ׳״ (ירמיהו לג:כו). וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ (נדרים לב.) לְעִנְיַן בְּרִית הַתּוֹרָה, לִלְמֹד מִכָּאן שֶׁבִּשְׁבִיל הַתּוֹרָה נִבְרְאוּ שָׁמַיִם וָאָרֶץ; אַךְ אֵין הַמִּדְרָשׁ מְיֻשָּׁב עַל סֵדֶר הַמִּקְרָאוֹת:\",1,0],[2,121,34,5,\"בְּשָׁלוֹם תָּמוּת. אָמְרוּ רַבּוֹתֵינוּ (מועד קטן כח:), שֶׁמֵּת נְבוּכַדְנֶצַּר בְּיָמָיו. שֶׁכָּל יְמֵי נְבוּכַדְנֶצַּר לֹא יָצְאוּ אֲסִירָיו מֵאֲסִירֵיהֶם, וּכְשֶׁמֵּת נְבוּכַדְנֶצַּר יָצָא צִדְקִיָּהוּ מִבֵּית הָאֲסוּרִים, וּלְמָחֳרָת מֵת וְקָבְרוּהוּ בְּכָבוֹד:\",1,0],[2,121,34,5,\"וּבְמִשְׂרְפוֹת אֲבוֹתֶיךָ. כָּךְ הָיָה דַּרְכָּם, לִשְׂרֹף עַל הַמְּלָכִים מִטָּתָן וּכְלֵי תַשְׁמִישָׁן (דברי הימים ב טז:יד; עבודה זרה יא.):\",2,0],[2,121,34,8,\"אַחֲרֵי כְּרוֹת הַמֶּלֶךְ. בַּשָּׁנָה הַשְּׁבִיעִית לְמָלְכוֹ. כָּךְ שָׁנִינוּ בְּסֵדֶר עוֹלָם (סדר עולם רבה כו): ״וַיְהִי בַּשָּׁנָה הַשְּׁבִיעִית… בָּאוּ אֲנָשִׁים מִזִּקְנֵי יְהוּדָה לִדְרֹשׁ אֶת ה׳״ (יחזקאל כ:א). אָמְרוּ לִיחֶזְקֵאל: עֶבֶד כֹּהֵן שֶׁמְּכָרוֹ רַבּוֹ, מַהוּ שֶׁיֹּאכַל בִּתְרוּמָה? כְּלוֹמַר, לְפִי שֶׁהָיוּ רוֹצִין לוֹמַר: לֹא נֶעֱנַשׁ עַל הַמִּצְוֹת, עַל שֶׁהֶחֱזִירוּ אֶת הָעֲבָדִים:\",1,0],[2,121,34,17,\"הִנְנִי קֹרֵא לָכֶם דְּרוֹר. מֵאִתִּי, שֶׁאֵינִי אָדוֹן לָכֶם לְהַצִּיל, וְתִהְיוּ הֶפְקֵר אֶל הַחֶרֶב וְאֶל הָרָעָב:\",1,0],[2,121,34,18,\"הָעֵגֶל אֲשֶׁר כָּרְתוּ לִשְׁנַיִם. כְּשֶׁחָזְרוּ וְכָבְשׁוּם, כָּרְתוּ כֻּלָּם בְּרִית לִמְרוֹד בַּמָּקוֹם, וְכָרְתוּ הָעֵגֶל לִשְׁנַיִם וְעָבְרוּ בֵּין בְּתָרָיו, לִמְרוֹד בּוֹ. וְהִיא הָיְתָה בְּרִית חֲזָקָה וּגְמוּרָה, לֵאמֹר: כָּכָה יִבָּתֵר וְיֵחָלֵק הָעוֹבֵר עָלֶיהָ (בראשית טו:ט-יז):\",1,0],[2,121,34,21,\"הָעוֹלִים מֵעֲלֵיכֶם. מִפְּנֵי חֵיל פַּרְעֹה שֶׁיָּצָא מִמִּצְרַיִם, כְּמוֹ שֶׁמְּפֹרָשׁ בְּסֵפֶר זֶה (ירמיה לז:ה):\",1,0],[2,121,34,22,\"הִנְנִי מְצַוֶּה. וְשָׁב חֵיל פַּרְעֹה לְאַרְצוֹ, וְהַכַּשְׂדִּים יָשׁוּבוּ עֲלֵיכֶם (ירמיה לז:ה-ח):\",1,0],[2,121,35,2,\"אֶל בֵּית הָרֵכָבִים. בְּנֵי יוֹנָדָב בֶּן רֵכָב (ירמיה לה:ו), וּמִבְּנֵי יִתְרוֹ הָיוּ (מכילתא יתרו עמלק ב):\",1,0],[2,121,35,4,\"אִישׁ הָאֱלֹהִים. ״נָבִיא דַּה׳״ (תרגום יונתן):\",1,0],[2,121,35,4,\"שׁוֹמֵר הַסַּף. ״אֲמַרְכְּלָא״ (תרגום יונתן), טְרֵשׁוֹרִי״ר בְּלַעַ״ז:\",2,0],[2,121,35,7,\"בָּאֳהָלִים תֵּשְׁבוּ. בַּמִּדְבָּרִיּוֹת. אֲשֶׁר אַתֶּם גָּרִים שָׁם. לֹא הָיָה לָהֶם חֵלֶק בָּאָרֶץ, שֶׁבְּנֵי גֵרִים הָיוּ (ספרי במדבר עח):\",1,0],[2,121,35,11,\"וַיְהִי בַּעֲלוֹת נְבוּכַדְרֶאצַּר. עַל כָּרְחֵנוּ בָּאנוּ הָעִיר, לְכָךְ עַכְשָׁיו אָנוּ יוֹשְׁבִים בַּבָּתִּים:\",1,0],[2,121,36,5,\"עָצוּר. בְּבֵית הַכֶּלֶא:\",1,0],[2,121,36,10,\"פֶּתַח שַׁעַר בֵּית ה׳ הֶחָדָשׁ. הוּא שַׁעַר הַמִּזְרָחִי, כֵּן תִּרְגֵּם יוֹנָתָן:\",1,0],[2,121,36,16,\"הַגֵּיד נַגִּיד לַמֶּלֶךְ. אוּלַי יִשְׁמַע:\",1,0],[2,121,36,20,\"חָצֵרָה. אֶל הֶחָצֵר. כָּל תֵּיבָה שֶׁצְּרִיכָה לָמֶ״ד בִּתְחִלָּתָהּ, הִטִּיל לָהּ הֵ״א בְּסוֹפָהּ (יבמות יג:):\",1,0],[2,121,36,22,\"וְאֶת הָאָח. פֵּרְשׁוּ רַבּוֹתֵינוּ (שבת כ.): עֵצִים; עַל שֵׁם שֶׁנִּדְלָקִים בְּאַחְוָה (כְּלוֹמַר שֶׁנִּדְלָקִים זֶה מִזֶּה כְּאַחִים שֶׁמְּהַנִּים זֶה לָזֶה סא״א). וּלְפִי פְשׁוּטוֹ מַשְׁמַע שֶׁהוּא כְּלִי שֶׁמְּבַעֲרִין עָלָיו אוּר לִפְנֵי הַשָּׂרִים:\",1,0],[2,121,36,23,\"שָׁלֹשׁ דְּלָתוֹת. רַבּוֹתֵינוּ אָמְרוּ (מועד קטן כו.): מְגִלַּת קִינוֹת הָיְתָה, קָרְאוּ לְפָנָיו ״אֵיכָה״, ״בָּכֹה תִבְכֶּה״, ״גָּלְתָה יְהוּדָה״, ״דַּרְכֵי צִיּוֹן אֲבֵלוֹת״ (איכה א:א-ד) – בְּכָל זֶה לֹא חָשׁ, אָמַר: אֲנִי מֶלֶךְ עַל הַנּוֹתָרִים; כֵּיוָן שֶׁקָּרָא ״הָיוּ צָרֶיהָ לְרֹאשׁ״ (איכה א:ה), אָמַר: מֵעַכְשָׁיו אֵינִי מֶלֶךְ; מִיָּד וַיִּקְרָעֶהָ בְּתַעַר הַסֹּפֵר:\",1,0],[2,121,36,23,\"יִקְרָעֶהָ. כְּמוֹ קְרָעָהּ:\",2,0],[2,121,36,25,\"הִפְגִּיעוּ. הִתְחַנְּנוּ:\",1,0],[2,121,36,32,\"דְּבָרִים רַבִּים כָּהֵמָּה. מִתְּחִלָּה הָיוּ שָׁלֹשׁ אַלְפָא בֵּיתִין: ״אֵיכָה יָשְׁבָה״ (איכה א:א), ״אֵיכָה יָעִיב״ (איכה ב:א), ״אֵיכָה יוּעַם״ (איכה ד:א), וְהוֹסִיף עָלֶיהָ ״אֲנִי הַגֶּבֶר״ (איכה ג:א), שֶׁכָּל אוֹת מְשֻׁלֶּשֶׁת בָּהּ (איכה רבה ג:א):\",1,0],[2,121,37,1,\"וַיִּמְלֹךְ מֶלֶךְ. לְפִי שֶׁמֵּעַתָּה בָּא לְסַפֵּר וְלוֹמַר שֶׁנִּתְקַיְּמוּ הַפּוּרְעָנִיּוֹת שֶׁנִּבָּא עַד הֵנָּה, הִתְחִיל לוֹמַר כֵּן: וּבְבֹא עֵת הַפְּקֻדָּה, שֶׁקָּרְבוּ הַיָּמִים לְהִתְקַיֵּם הַדְּבָרִים, וַיִּמְלֹךְ מֶלֶךְ אַחֵר עַל יְהוּדָה תַּחַת כָּנְיָהוּ בֶּן יְהוֹיָקִים וְגוֹ׳:\",1,0],[2,121,37,4,\"וְיִרְמְיָהוּ בָּא וְיֹצֵא בְּתוֹךְ הָעָם. כְּשֶׁמָּלַךְ צִדְקִיָּהוּ, צִוָּה וְהוֹצִיאוּהוּ מִבֵּית הַכֶּלֶא שֶׁכְּלָאוֹ יְהוֹיָקִים. שֶׁצִּדְקִיָּה הָיָה צַדִּיק וְדוֹרוֹ רְשָׁעִים, וִיהוֹיָקִים הָיָה רָשָׁע וְדוֹרוֹ צַדִּיקִים (סנהדרין קג.):\",1,0],[2,121,37,5,\"וְחֵיל פַּרְעֹה יָצָא מִמִּצְרָיִם. לְעֶזְרָה לִיהוּדָה:\",1,0],[2,121,37,7,\"שָׁב לְאַרְצוֹ מִצְרָיִם. בִּסְפִינוֹת הָיוּ בָאִים, וְרָמַז הַקָּדוֹשׁ בָּרוּךְ הוּא לַיָּם, וְהֵצִיף עָלָיו כְּמוֹ נוֹדוֹת וְאוֹבוֹת (כְּלוֹמַר נְפוּחוֹת) דּוֹמוֹת לְעוֹרוֹת בְּנֵי אָדָם. אָמְרוּ זֶה לָזֶה: מַה זֹּאת? אָמְרוּ: אֵלּוּ אֲבוֹתֵינוּ, שֶׁטִּבְּעוּם אֲבוֹתֵיהֶם שֶׁל אֵלּוּ שֶׁאָנוּ הוֹלְכִים לְעֶזְרָתָם בַּיָּם. מִיָּד שָׁבוּ לְאַרְצָם (איכה רבה ד, כ):\",1,0],[2,121,37,12,\"לַחֲלִק מִשָּׁם בְּתוֹךְ הָעָם. ״לְפַלְגָא אַחֲסַנְתָּא דִילֵיהּ בְּגוֹ עַמָּא״ (תרגום יונתן). וּבְעוֹד הַכַּשְׂדִּים צָרִים עָלֶיהָ לֹא הָיָה יוֹצֵא מִמֶּנָּה, שֶׁמִּתְפַּלֵּל עַל הָעִיר שֶׁלֹּא תִלָּכֵד:\",1,0],[2,121,37,13,\"וְשָׁם בַּעַל פְּקִדֻת. מְמֻנֶּה לִשְׁמֹר שֶׁלֹּא יֵצֵא אִישׁ מִן הָעִיר לְהַשְׁלִים אֶל הַכַּשְׂדִּים:\",1,0],[2,121,37,13,\"בֶּן שֶׁלֶמְיָה בֶּן חֲנַנְיָה. הוּא חֲנַנְיָה בֶּן עַזּוּר (ירמיה כח:א). בֶּן בְּנוֹ הָיָה זֶה, וּלְכָךְ יִחֲסוֹ הַכָּתוּב, לְלַמֵּד שֶׁכָּל הַמַּחֲנִיף לָרָשָׁע סוֹף נוֹפֵל בְּיָדוֹ (סוטה מא:) אוֹ בְּיַד בְּנוֹ אוֹ בְּיַד בֶּן בְּנוֹ; וְיִרְמְיָה הֶחֱנִיף לוֹ, שֶׁאָמַר לוֹ: ״אָמֵן יָקֵם ה׳ אֶת דְּבָרֶיךָ״ (ירמיה כח:ו). וּמִדְרַשׁ אַגָּדָה: שֶׁצִּוָּה חֲנַנְיָה אֶת בְּנוֹ: רְאֵה שֶׁאֲנִי מֵת עַל יְדֵי יִרְמְיָה, וְהֶעֱמִידַנִי שַׁקְרָן בִּנְבוּאָתִי; אִם תּוּכַל לְהַכְשִׁילוֹ, הַכְשִׁילֵהוּ. וּבְנוֹ צִוָּה גַּם הוּא לְבָנָיו כָּךְ, וּכְשֶׁהִגִּיעַ שָׁעָה, הִכְשִׁילוֹ:\",2,0],[2,121,37,16,\"וְאֶל הַחֲנֻיּוֹת. תִּרְגֵּם יוֹנָתָן: ״לְגַיו מִן חֲנָוָאתָא״; חֲנֻיּוֹת הָיוּ לִפְנֵי אוֹתוֹ בֵּית הַכֶּלֶא:\",1,0],[2,121,37,21,\"מֵחוּץ הָאֹפִים. מִשּׁוּק נַחְתּוֹמִים, כְּמוֹ ״וְחֻצוֹת תָּשִׂים לְךָ בְדַמֶּשֶׂק״ (מלכים א כ:לד):\",1,0],[2,121,38,2,\"וְהָיְתָה לוֹ נַפְשׁוֹ לְשָׁלָל. וְהָיוּ לוֹ חַיָּיו הַצָּלָה, כְּאִלּוּ שָׁלַל נַפְשׁוֹ; כְּאָדָם הַשּׁוֹלֵל שָׁלָל וּמִשְׂתַּכֵּר, כָּךְ יִשְׂתַּכֵּר זֶה נַפְשׁוֹ:\",1,0],[2,121,38,4,\"עַל כֵּן הוּא מְרַפֵּא. אֶלַאקְנְ״ץ בְּלַעַ״ז, לְשׁוֹן רִפְיוֹן:\",1,0],[2,121,38,5,\"יוּכַל. כְּמוֹ יָכוֹל, עַל אֲשֶׁר הוּא מְרַפֵּא אֶת וְגוֹ׳:\",1,0],[2,121,38,6,\"הַבּוֹר מַלְכִּיָּהוּ. שֶׁל מַלְכִּיָּהוּ:\",1,0],[2,121,38,7,\"עֶבֶד מֶלֶךְ. בָּרוּךְ בֶּן נֵרִיָּה:\",1,0],[2,121,38,7,\"הַכּוּשִׁי. צִדְקִיָּהוּ: מָה כּוּשִׁי מְשֻׁנֶּה בְּעוֹרוֹ, אַף צִדְקִיָּהוּ מְשֻׁנֶּה בְּצִדְקוֹ מִכָּל דּוֹרוֹ (מועד קטן טז:). וְיֵשׁ מִדְרָשׁ דּוֹרֵשׁ הַכּוּשִׁי עַל בָּרוּךְ (ספרי במדבר צט):\",2,0],[2,121,38,7,\"אִישׁ סָרִיס. גֶּבֶר רַב:\",3,0],[2,121,38,9,\"וַיָּמָת תַּחְתָּיו וגו׳. אִלּוּ הִנִּיחוּ אוֹתוֹ בִּמְקוֹמוֹ הָיָה מֵת מֵאֵלָיו בָּרָעָב, וְהֵם הֵרֵעוּ לְקָרֵב מִיתָתוֹ:\",1,0],[2,121,38,10,\"שְׁלֹשִׁים אֲנָשִׁים. מִתּוֹךְ שֶׁכֹּחָן תַּשׁ בָּרָעָב, נִצְרְכוּ כֻּלָּן:\",1,0],[2,121,38,11,\"בְּלוֹיֵי סְחָבוֹת. בְּלוּאֵי בְגָדִים הַנִּסְחָבִים:\",1,0],[2,121,38,12,\"וְהַמְּלָחִים. לְשׁוֹן רִקָּבוֹן, כְּמוֹ ״כֶּעָשָׁן נִמְלָחוּ״ (ישעיה נא:ו):\",1,0],[2,121,38,12,\"תַּחַת אַצִּלוֹת יָדֶיךָ. שֶׁלֹּא יַזִּיקוּךָ הַחֲבָלִים:\",2,0],[2,121,38,12,\"אַצִּילוֹת. אֵיישִׁילָ״שׁ בְּלַעַ״ז:\",3,0],[2,121,38,14,\"מָבוֹא הַשְּׁלִישִׁי. לֹא יָדַעְתִּי הֵיכָן הוּא. וְשֶׁמָּא בְּעֶזְרַת יִשְׂרָאֵל הִיא, לוֹמַר שֶׁהַחֵיל וְעֶזְרַת נָשִׁים לְפָנֶיהָ (משנה סכה ה,ד):\",1,0],[2,121,38,19,\"דּוֹאֵג. יָרֵא:\",1,0],[2,121,38,19,\"פֶּן יִתְּנוּ אוֹתִי. הַכַּשְׂדִּים בְּיַד הַיְּהוּדִים, לוֹמַר: מַלְכְּכֶם יְהִי עַבְדְּכֶם עַל שֶׁקְּדַמְתֶּם לְהַשְׁלִים עִמָּנוּ:\",2,0],[2,121,38,19,\"וְהִתְעַלְּלוּ בִי. הַיְּהוּדִים. אִיגְבְּרוֹנְ״ט בְּלַעַ״ז:\",3,0],[2,121,38,22,\"אַנְשֵׁי שְׁלוֹמֶךָ. נְבִיאֵי הַשֶּׁקֶר, שֶׁאָמְרוּ לְךָ: לֹא תִלָּכֵד:\",1,0],[2,121,38,22,\"בַּבֹּץ. טִיט, לְשׁוֹן ״הֲיִגְאֶה גֹּמֶא בְּלֹא בִצָּה״ (איוב ח:יא):\",2,0],[2,121,38,23,\"וְאֶת הָעִיר הַזֹּאת תִּשְׂרֹף בָּאֵשׁ. הֲרֵי אַתָּה כְּאִלּוּ שׂוֹרְפָהּ בְּיָדַיִם, שֶׁאַתָּה גּוֹרֵם לָהּ:\",1,0],[2,121,39,3,\"וַיָּבֹאוּ כָּל שָׂרֵי מֶלֶךְ בָּבֶל וַיֵּשְׁבוּ בְּשַׁעַר הַתָּוֶךְ וְגוֹ׳. מַגִּיד שֶׁנִּתְקַיְּמָה כָּאן נְבוּאָה עֶלְיוֹנָה: ״וּבָאוּ וְנָתְנוּ אִישׁ כִּסְאוֹ פֶּתַח שַׁעֲרֵי יְרוּשָׁלִַם וְגוֹ׳״ (ירמיה א:טו):\",1,0],[2,121,39,3,\"בְּשַׁעַר הַתָּוֶךְ. ״בְּתַרְעָא מְצִיעָתָא״ (תרגום יונתן); שַׁעַר הָעֲזָרָה, שַׁעַר נִיקָנוֹר הַמִּזְרָחִי, וְהוּא בֵּין שַׁעַר עֶזְרַת נָשִׁים וּבֵין שַׁעַר הַהֵיכָל. וְרַבּוֹתֵינוּ אָמְרוּ שַׁעַר הַתָּוֶךְ שַׁעַר שֶׁמְּחַתְּכִין בּוֹ הֲלָכוֹת, עֲלֵיהֶם הוּא אוֹמֵר ״מְקוֹם הַמִּשְׁפָּט שָׁמָּה הָרֶשַׁע״ (קהלת ג:טז):\",2,0],[2,121,39,4,\"דֶּרֶךְ גַּן הַמֶּלֶךְ. מְעָרָה הָיְתָה לוֹ מִבֵּיתוֹ עַד עַרְבוֹת יְרֵחוֹ, וַיֵּצְאוּ לֵילֵךְ דֶּרֶךְ הַמְּעָרָה (פסיקתא רבתי כו); מָה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, לְקַיֵּם ״וּפָרַשְׂתִּי אֶת רִשְׁתִּי עָלָיו״ (יחזקאל יב:יג)? זִמֵּן צְבִי לִפְנֵי הַכַּשְׂדִּים מְהַלֵּךְ עַל גַּג הַמְּעָרָה חוּץ לָעִיר, וְרָצוּ אַחֲרָיו לְתָפְשׂוֹ וְהוּא רָץ עַד פֶּתַח הַמְּעָרָה, וְרָאוּ אֶת צִדְקִיָּהוּ יוֹצֵא מִן הַמְּעָרָה:\",1,0],[2,121,39,5,\"וַיְדַבֵּר אִתּוֹ מִשְׁפָּטִים. לָמָּה עָבַרְתָּ עַל הַשְּׁבוּעָה?!\",1,0],[2,121,39,6,\"וְאֵת כָּל חוֹרֵי יְהוּדָה. אֵלּוּ הַסַּנְהֶדְרִין, עַל שֶׁהִתִּירוּ לוֹ אֶת שְׁבוּעָתוֹ (תנחומא, ואתחנן א). הַחֵטְא הָיָה בְּעֵינֵי הָאֱלֹהִים שֶׁהִתִּירוּ הַשְּׁבוּעָה:\",1,0],[2,121,39,8,\"וְאֶת בֵּית הָעָם. בָּתֵּי כְנֵסִיּוֹת (שבת לב.):\",1,0],[2,121,39,10,\"כְּרָמִים וִיגֵבִים. שָׂדוֹת לְעָבְדָם. כָּל יְגִיבָה לְשׁוֹן חֲפִירָה, אַפּוֹשִׁי״ץ בְּלַעַ״ז:\",1,0],[2,121,39,13,\"רַבֵּי. כְּמוֹ שָׂרֵי:\",1,0],[2,121,39,14,\"אֶל גְּדַלְיָהוּ בֶן אֲחִיקָם. שֶׁנָּפַל אֶל הַכַּשְׂדִּים עַל פִּי יִרְמְיָה, וּכְשֶׁנִּלְכְּדָה הָעִיר מִנָּהוּ שַׁלִּיט בַּנִּשְׁאָרִים שָׁם:\",1,0],[2,121,39,16,\"וְהָיוּ לְפָנֶיךָ בַּיּוֹם הַהוּא. וְהָיוּ הַדְּבָרִים לְפָנֶיךָ, שֶׁתִּרְאֶה אוֹתָם מִתְקַיְּמִים:\",1,0],[2,121,39,17,\"בְּיַד הָאֲנָשִׁים. בְּיַד הַכַּשְׂדִּים:\",1,0],[2,121,40,1,\"הַדָּבָר אֲשֶׁר הָיָה. מַה שֶׁנֶּאֱמַר בְּסוֹף הָעִנְיָן: ״וַיְהִי מִקֵּץ עֲשֶׂרֶת יָמִים וַיְהִי דְבַר ה׳ וְגוֹ׳״ (ירמיה מב:ז), אֶלָּא שֶׁכָּתַב תְּחִלָּה עַל מָה נֶאֱמַר לוֹ. וּמִדְרַשׁ אַגָּדָה בְּאֵיכָה רַבָּתִי (איכה רבה פתיחתא לד): מַה הָיָה הַדָּבָר? – וְשׁוּבָה אֶל גְּדַלְיָהוּ. אָמַר לוֹ: אוֹ אַתְּ נָחִית עִמְּהוֹן וַאֲנָא מְסוֹבֵר הָכָא, אוֹ אַתְּ סוֹבֵר הָכָא וַאֲנָא נָחִית עִמְּהוֹן; אָמַר: אִין אֲנָא נָחִית עִמְּהוֹן, מָה אֲנָא מְהַנֵּי לְהוֹן? אֶלָּא יֵיחוֹת בָּרְיֵיהוֹן עִמְּהוֹן, דְּסַגִּין הוּא מְהַנֵּי לְהוֹן:\",1,0],[2,121,40,1,\"מִן הָרָמָה. שֶׁהָיָה גּוֹלֶה מֵעַצְמוֹ עִמָּהֶן; הָיָה רוֹאֶה כַּת שְׁלוּלִים בְּקוֹלָרִין, הָיָה מַכְנִיס צַוָּארוֹ בֵּינֵיהֶם, וְכוּ׳; כִּדְאִיתָא בִּפְסִיקְתָּא (פסיקתא דרב כהנא יג, ט) דְּאַפְטַרְתָּא ״דִּבְרֵי יִרְמְיָהוּ״ (ירמיה א:א). שֶׁאִי אֶפְשָׁר לוֹמַר שֶׁנְּתָנוֹ נְבוּזַרְאֲדָן בָּאזִקִּים, שֶׁהֲרֵי צִוָּה נְבוּכַדְנֶצַּר: ״אַל תַּעַשׂ לוֹ מְאוּמָה רָע״ (ירמיה לט:יב):\",2,0],[2,121,40,1,\"בָּאזִקִּים. בְּזִיאוֹ״שׁ בְּלַעַ״ז:\",3,0],[2,121,40,2,\"ה׳ אֱלֹהֶיךָ דִּבֶּר וְגוֹ׳. לָמָּה אַתָּה מִצְטַעֵר עֲלֵיהֶם? וַהֲלֹא אַתָּה נִבֵּאתָ לָהֶם וְלֹא שָׁמְעוּ; כִּדְאִיתָא בַּפְּסִיקְתָּא (פסיקתא דרב כהנא יג, ט):\",1,0],[2,121,40,4,\"פִתַּחְתִּיךָ. לְשׁוֹן ״וַיְפַתַּח הַגְּמַלִּים״ (בראשית כד:לב), וְכַן תִּרְגֵּם יוֹנָתָן: ״וּכְעַן הָא שָׁרִיתָךְ״. וּמְנַחֵם פָּתַר כֻּלָּם לְשׁוֹן פְּתִיחָה מַמָּשׁ:\",1,0],[2,121,40,5,\"וְעוֹדֶנּוּ לֹא יָשׁוּב. בְּכָל זֹאת לֹא הָיָה חָפֵץ לָשׁוּב; אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: וְשֻׁבָה אֶל גְּדַלְיָה, אֲשֶׁר הֻפְקַד עַל הָעֲנִיִּים הַנִּשְׁאָרִים; גַּם הֵם צְרִיכִין לְךָ, כִּשְׁאָר הַגּוֹלִים:\",1,0],[2,121,40,5,\"אֲרוּחָה וּמַשְׂאֵת. ״מַתְּנָן וּנְבִזְבְּזָן״ (תרגום יונתן):\",2,0],[2,121,40,10,\"וְקַיִץ. דְּבֵלָה:\",1,0],[2,121,41,1,\"וְרַבֵּי הַמֶּלֶךְ. וְשָׂרֵי הַמֶּלֶךְ. נִתְקַנְּאוּ בּוֹ שֶׁנָּטַל גְּדֻלָּה:\",1,0],[2,121,41,5,\"לְהָבִיא בֵּית ה׳. כְּשֶׁנָּסְעוּ מִבֵּיתָם לֹא הָיוּ יוֹדְעִים בְּחֻרְבַּן הַבַּיִת, וּבַדֶּרֶךְ שָׁמְעוּ וְקָרְעוּ בִּגְדֵיהֶם וְגִלְּחוּ זְקָנָם (מועד קטן כו.):\",1,0],[2,121,41,5,\"וּמִתְגּוֹדְדִים. לְשׁוֹן שְׂרִיטָה:\",2,0],[2,121,41,9,\"אֲשֶׁר הִכָּה בְּיַד גְּדַלְיָהוּ. מִתּוֹךְ שֶׁהָיָה לוֹ לָחוּשׁ לַעֲצַת יוֹחָנָן בֶּן קָרֵחַ וְלֹא חָשׁ (ירמיה מ:יג-טז), הֶעֱלָה עָלָיו כְּאִלּוּ נֶהֶרְגוּ עַל יָדוֹ (נדה סא.):\",1,0],[2,121,41,12,\"אֶל מַיִם רַבִּים. ״עַל בְּרֵכַת מַיִּין סַגִּיאִין״ (תרגום יונתן):\",1,0],[2,121,41,17,\"בְּגֵרוּת כִּמְהָם. ״בְּגֵרוּת דִּיהַב דָּוִד לְכִמְהָם בַּר בַּרְזִלַּי גִּלְעָדָאָה״ (תרגום יונתן), כְּשֶׁשָּׁב מִמִּלְחֶמֶת אַבְשָׁלוֹם, כְּמוֹ שֶׁנֶּאֱמַר בְּסֵפֶר שְׁמוּאֵל ״אִתִּי יַעֲבֹר כִּמְהָם וְגוֹ׳״ (שמואל ב יט:לט):\",1,0],[2,121,42,14,\"וְקוֹל שׁוֹפָר. שֶׁתּוֹקְעִין הַצּוֹפִים לְהַזְהִיר אֶת הָעָם:\",1,0],[2,121,43,9,\"וּטְמַנְתָּם בַּמֶּלֶט. מ״ם זוֹ יְסוֹד נוֹפֵל הִיא בַּתֵּיבָה, כְּמוֹ מָקוֹם, מַעֲמָד, מַעֲשֶׂה; וִיסוֹדוֹ לָט, כְּמוֹ ״וַיָּלֶט פָּנָיו״ (מלכים א יט:יג): לְאַט אוֹתָהּ בְּתוֹךְ הַטִּיט בַּמַּלְבֵּן. בַּמֶּלֶט אַנְוְלוֹפְמַנְטוֹ בְּלַעַ״ז:\",1,0],[2,121,43,10,\"שַׁפְרִירוֹ. אָהֳלוֹ, וְדֻגְמָתוֹ: ״בְּרוּחוֹ שָׁמַיִם שִׁפְרָה״ (איוב כו:יג):\",1,0],[2,121,43,12,\"וְעָטָה אֶת אֶרֶץ מִצְרַיִם. יִכְרוֹךְ כָּל שְׁלָלָהּ וְיֵצֵא, כַּאֲשֶׁר יִכְרוֹךְ וְיִגְלוֹל הָרֹעֶה אֶת בִּגְדּוֹ וְיַשְׁלִיכוֹ מֵעַל כְּתֵפָיו כְּשֶׁהוּא מוֹלִיךְ צֹאנוֹ לְפָנָיו:\",1,0],[2,121,43,13,\"אֶת מַצְּבוֹת בֵּית שֶׁמֶשׁ. מִזְבְּחוֹת שֶׁעָשׂוּ שָׁם אוֹתָם שֶׁנִּתְגַּיְּרוּ בִּימֵי חִזְקִיָּהוּ, שְׁבוּיֵי סַנְחֵרִיב שֶׁהוֹלִיךְ מִכּוּשׁ וּמִמִּצְרַיִם לִפְנֵי יְרוּשָׁלַיִם בְּיוֹם מַפַּלְתּוֹ; כְּמוֹ שֶׁאָמַר (ישעיהו יט:יח): ״בַּיּוֹם הַהוּא יִהְיוּ חָמֵשׁ עָרִים בְּאֶרֶץ מִצְרַיִם מְדַבְּרוֹת שְׂפַת כְּנַעַן וְנִשְׁבָּעוֹת לַה׳ צְבָאוֹת עִיר הַהֶרֶס יֵאָמֵר לְאַחַת״, וְתִרְגֵּם יוֹנָתָן: ״עִיר קַרְתָּא בֵּית שֶׁמֶשׁ דַּעֲתִידָא לְמֵיחֲרַב יִתְאַמַּר דְּהִיא חֲדָא מִנְּהוֹן״:\",1,0],[2,121,44,10,\"לֹא דֻכְּאוּ. לִבָּם מֵרָעָתָם:\",1,0],[2,121,44,14,\"כִּי אִם פְּלֵטִים. יִרְמְיָה וּבָרוּךְ חָזְרוּ לְשָׁם, שֶׁהִגְלָה נְבוּכַדְנֶאצַּר כְּשֶׁנִּתְּנָה אֶרֶץ מִצְרַיִם בְּיָדוֹ בְּעֶשְׂרִים וְשֶׁבַע לְמָלְכוֹ (יחזקאל כט:יז-כ). כָּךְ שְׁנוּיָה בְּסֵדֶר עוֹלָם (סדר עולם רבה כו):\",1,0],[2,121,44,19,\"הֲמִבַּלְעֲדֵי אֲנָשֵׁינוּ. שֶׁלֹּא מִדַּעְתָּם:\",1,0],[2,121,44,19,\"כַּוָּנִים לְהַעֲצִיבָהּ. דְּפוּסִים כִּדְמוּת עֲצַבִּים (עֲצַבִּים דְּמוּת עַלְמָה כְּמוֹ לְעֵיל כב):\",2,0],[2,121,44,22,\"וְלֹא יוּכַל ה׳ עוֹד לָשֵׂאת. כְּמוֹ וְלֹא יָכוֹל:\",1,0],[2,121,44,30,\"פַּרְעֹה חָפְרַע. ״פַּרְעֹה תְּבִירָא״ (תרגום יונתן); וְחִי״ת זוֹ מְשַׁמֶּשֶׁת בִּמְקוֹם הֵ״א:\",1,0],[2,121,45,3,\"וּמְנוּחָה לֹא מָצָאתִי. לֹא שָׁרְתָה עָלַי שְׁכִינָה לְהִנָּבֵא; כְּמוֹ ״וַתָּנַח עֲלֵיהֶם הָרוּחַ״ (במדבר יא:כו). מָה נִשְׁתַּנֵּיתִי מִתַּלְמִידֵי הַנְּבִיאִים: יְהוֹשֻׁעַ שִׁמֵּשׁ אֶת מֹשֶׁה – נָחָה עָלָיו רוּחַ הַקֹּדֶשׁ; אֱלִישָׁע שִׁמֵּשׁ אֶת אֵלִיָּהוּ – נָחָה עָלָיו רוּחַ הַקֹּדֶשׁ; אֲנִי – מָה נִשְׁתַּנֵּיתִי? (מכילתא בא פסחא א)\",1,0],[2,121,45,4,\"וְאֶת כָּל הָאָרֶץ. הִיא הַנִּדּוֹנֶת בִּנְתִישָׁה וַהֲרִיסָה זוֹ:\",1,0],[2,121,45,5,\"תְּבַקֵּשׁ לְךָ גְדֹלוֹת. נְבוּאוֹת, כְּמוֹ ״סַפְּרָה נָא לִי אֵת כָּל הַגְּדֹלוֹת וְגוֹ׳״ (מלכים ב ח:ד), ״קְרָא אֵלַי וְאַגִּידָה לְךָ גְּדֹלוֹת וְגוֹ׳״ (ירמיה לג:ג). אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אִם אֵין כֶּרֶם אֵין סְיָג, וְאִם אֵין צֹאן אֵין רוֹעֶה; אֵינִי נִגְלֶה עַל הַנְּבִיאִים אֶלָּא בִּזְכוּתָם שֶׁל יִשְׂרָאֵל. כָּךְ שְׁנוּיָה בַּמְּכִילְתָּא בִּתְחִלָּתָהּ (מכילתא בא פסחא א):\",1,0],[2,121,46,3,\"מָגֵן. שֶׁל עוֹר הוּא, וְהוּא שָׁלוּק; וּכְשֶׁיּוֹצֵא לַמִּלְחָמָה מוֹשְׁחוֹ בְּשֶׁמֶן:\",1,0],[2,121,46,3,\"צִנָּה. שֶׁל עֵץ, דְּמוּת תְּרִיסִין שֶׁלָּנוּ:\",2,0],[2,121,46,4,\"מִרְקוּ הָרְמָחִים. כְּמוֹ ״וּמֹרַק וְשֻׁטַּף״ (ויקרא ו:כא); פורביר בְּלַעַ״ז:\",1,0],[2,121,46,5,\"הֵמָּה חַתִּים. מִצְרַיִם:\",1,0],[2,121,46,5,\"וְלֹא הִפְנוּ. עוֹד לַעֲמוֹד בַּמִּלְחָמָה, לֹא הָיָה לָהֶם פְּנַאי:\",2,0],[2,121,46,7,\"כַּיְאֹר יַעֲלֶה. שֶׁהָיָה רָגִיל לְהַעֲלוֹת גְּיָסוֹת סְבִיבָיו כְּמוֹ נָהָר, לִשְׁטֹף סְבִיבָיו:\",1,0],[2,121,46,7,\"יִתְגָּעֲשׁוּ מֵימָיו. ״דְּמִטָּרְפִין מוֹהִי״ (תרגום יונתן):\",2,0],[2,121,46,8,\"כַּיְאוֹר יַעֲלֶה. הָיָה רָגִיל לַעֲלוֹת:\",1,0],[2,121,46,8,\"אוֹבִידָה. כְּמוֹ אֲאַבֵּד:\",2,0],[2,121,46,9,\"וְהִתְהוֹלְלוּ. לְשׁוֹן סִכְלוּת:\",1,0],[2,121,46,10,\"וְרָוְתָה. לְשׁוֹן שֹׂבַע. לָשׁוֹן אַחֵר: לְשׁוֹן שִׁכָּרוֹן, כְּמוֹ ״שֵׁכָר״ (במדבר ו:ג) דִּמְתַרְגְּמִינָן: ״מְרַוֵי״ (תרגום אונקלוס):\",1,0],[2,121,46,10,\"בְּאֶרֶץ צָפוֹן. שֶׁהָלַךְ פַּרְעֹה עַל נְבוּכַדְנֶצַּר בְּכַרְכְּמִישׁ, וְגַם נָפַל וְנֶהֶרְגוּ גִּבּוֹרָיו (ירמיה מו:ב-ו), וְהוּא בָּרַח מִן הַמִּלְחָמָה:\",2,0],[2,121,46,12,\"גִּבּוֹר בְּגִבּוֹר כָּשָׁלוּ. כְּשֶׁהָיוּ בּוֹרְחִים הָיוּ נִכְשָׁלִים וְנִתְקָלִים זֶה בָּזֶה:\",1,0],[2,121,46,13,\"לָבוֹא נְבוּכַדְרֶאצַּר. זוֹ מַכָּה שְׁנִיָּה, שֶׁהֶחֱרִיב נְבוּכַדְנֶצַּר אֶת מִצְרַיִם בִּשְׁנַת עֶשְׂרִים וְשֶׁבַע לְמָלְכוֹ (יחזקאל כט:יז), כְּמוֹ שֶׁשָּׁנִינוּ בְּסֵדֶר עוֹלָם (סדר עולם רבה כו):\",1,0],[2,121,46,14,\"הִתְיַצֵּב וְהָכֵן לָךְ. כְּנֶגֶד הַמִּלְחָמָה, וְהָכֵן וְאַתְקִין:\",1,0],[2,121,46,15,\"נִסְחַף. נִשְׁטְפוּ וְהֶחֱלִיקוּ גִבּוֹרֶיךָ, כְּמוֹ ״מָטָר סֹחֵף״ (משלי כח:ג), נִסְתַּחֲפָה שָׂדֵהוּ בִּלְשׁוֹן מִשְׁנָה (כתבות ז,ח). וּמְנַחֵם חִבְּרוֹ לְשׁוֹן כִּלָּיוֹן, וְכֵן חִבֵּר ״מָטָר סֹחֵף״. וְדוֹנָשׁ פָּתַר ״מָטָר סֹחֵף״ כְּמוֹ מָטָר סוֹעֵף, כְּמוֹ ״מְסָעֵף פֻּארָה בְּמַעֲרָצָה״ (ישעיהו י:לג):\",1,0],[2,121,46,16,\"הִרְבָּה כּוֹשֵׁל. הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֲדָפוֹ, וְהִרְבָּה לוֹ מִכְשׁוֹל:\",1,0],[2,121,46,16,\"גַּם נָפַל. נִתְקַבְּצוּ אִישׁ אֶל רֵעֵהוּ לֵאמֹר נָקוּמָה וְנָשׁוּבָה אֶל עַמֵּנוּ, מִמָּקוֹם שֶׁיָּצָאנוּ מִשָּׁם לְהִלָּחֵם:\",2,0],[2,121,46,16,\"חֶרֶב הַיּוֹנָה. ״חַרְבָּא דְּסָנְאָה דְּהִיא כְּחַמְרָא מְרַוְיָא״ (תרגום יונתן); הַיּוֹנָה לְשׁוֹן יַיִן. לָשׁוֹן אַחֵר: לְשׁוֹן אוֹנָאָה:\",3,0],[2,121,46,17,\"קָרְאוּ שָׁם. בַּמִּלְחָמָה הִכְרִיזוּ מָשָׁל שֶׁל חֶרְפָּה:\",1,0],[2,121,46,17,\"פַּרְעֹה מֶלֶךְ מִצְרַיִם שָׁאוֹן. שֶׁהָיָה מַגְבִּיהַּ קוֹל שָׁאוֹנוֹ תְּשׁוּאוֹת, לְהִתְהַלֵּל בְּחֵילוֹתָיו:\",2,0],[2,121,46,17,\"הֶעֱבִיר הַמּוֹעֵד. שֶׁיִּעֵד הַיּוֹם מִלְחָמָה קָבוּעַ לָצֵאת וּלְהִלָּחֵם וְלֹא יָצָא, וְעָבַר יוֹם זְמַן הַמּוֹעֵד (מועד קטן טז.):\",3,0],[2,121,46,18,\"כִּי כְתָבוֹר בֶּהָרִים. כִּי כַּאֲשֶׁר דְּבַר אֱמֶת הוּא שֶׁתָּבוֹר קָבוּעַ בֶּהָרִים וְהַר הַכַּרְמֶל עַל הַיָּם, כֵּן בֶּאֱמֶת יָבוֹא הַדָּבָר הַזֶּה עַל מִצְרַיִם (מכילתא יתרו בחדש ה):\",1,0],[2,121,46,19,\"כְּלֵי גוֹלָה. אָדָם יוֹצֵא לַדֶּרֶךְ, מְתַקֵּן לוֹ חֵמֶת וּמְקַדָּה שֶׁל חֶרֶס לִשְׁתּוֹת בָּהּ:\",1,0],[2,121,46,19,\"וְנִצְּתָה. לְשׁוֹן ״צִיָּה״ (ישעיה מא:יח):\",2,0],[2,121,46,20,\"עֶגְלָה יְפֵה־פִיָּה. ״מַלְכוּתָא יָאיָיא״ (תרגום יונתן):\",1,0],[2,121,46,20,\"קֶרֶץ. ״עַמְּמִין קְטוּלִין״ (תרגום יונתן); קֶרֶץ לְשׁוֹן חִתּוּךְ, וְכֵן ״מֵחֹמֶר קֹרַצְתִּי״ (איוב לג:ו):\",2,0],[2,121,46,20,\"מִצָּפוֹן. מִבָּבֶל:\",3,0],[2,121,46,21,\"שְׂכִירֶיהָ. שָׂרֶיהָ, כְּמוֹ ״בְּתַעַר הַשְּׂכִירָה״ (ישעיה ז:כ):\",1,0],[2,121,46,21,\"מַרְבֵּק. קוֹפְלָ״א בְּלַעַ״ז:\",2,0],[2,121,46,21,\"הִפְנוּ. פָּנוּ עֹרֶף לְבַקֵּשׁ לָנוּס:\",3,0],[2,121,46,22,\"קוֹלָהּ כַּנָּחָשׁ יֵלֵךְ. הֲרֵי הַנָּחָשׁ בָּא לְלַמֵּד עַל מִצְרַיִם וְנִמְצָא לָמֵד: לָמַדְנוּ מִכָּאן, שֶׁכְּשֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַנָּחָשׁ ״עַל גְּחֹנְךָ תֵלֵךְ״ (בראשית ג:יד), וְקִטֵּעַ אֶת רַגְלָיו וְהָלַךְ קוֹלוֹ בְּסוֹף הָעוֹלָם; כָּךְ שְׁנוּיָה בִּשְׁלֹשִׁים וּשְׁתַּיִם מִדּוֹת דְּרַבִּי אֱלִיעֶזֶר בְּנוֹ שֶׁל רַבִּי יוֹסֵי הַגְּלִילִי (מידה יב):\",1,0],[2,121,46,22,\"כִּי בְחַיִל יֵלֵכוּ. אֵלֶיהָ:\",2,0],[2,121,46,23,\"כָּרְתוּ יַעְרָהּ. כֹּחַ יֵשׁ בָּהֶן לִכְרוֹת כָּל יַעְרָהּ:\",1,0],[2,121,46,23,\"כִּי לֹא יֵחָקֵר. מִסְפַּר צְבָאָם:\",2,0],[2,121,46,25,\"אֶל אָמוֹן. עַל אָמוֹן, עַל הַשַּׂר אָמוֹן. יֵשׁ שֶׁהוּא לְשׁוֹן גְּדֻלָּה, כְּמוֹ ״הֲתֵיטְבִי מִנֹּא אָמוֹן״ (נחום ג:ח):\",1,0],[2,121,46,25,\"מִנֹּא. אֲלֶכְּסַנְדְּרִיָּה רַבְּתָא (פסיקתא רבתי לג), לָאשִׁינְיוֹרִיאָ״ה דְּלִישַׁנְדְּרָ״א בְּלַעַ״ז:\",2,0],[2,121,46,26,\"וְאַחֲרֵי כֵן. מִקֵּץ אַרְבָּעִים שָׁנָה, כְּמוֹ שֶׁאָמַר יְחֶזְקֵאל (יחזקאל כט:יג):\",1,0],[2,121,46,27,\"וְאַתָּה אַל תִּירָא. צַדִּיקִים שֶׁבְּתוֹךְ מִצְרַיִם, שֶׁגָּלוּ שָׁם עַל כָּרְחָם:\",1,0],[2,121,46,28,\"לַמִּשְׁפָּט. ״בְּדִין חָסוּךְ״ (תרגום יונתן), מְעַט מְעַט:\",1,0],[2,121,46,28,\"וְנַקֵּה. לְשׁוֹן טִיאוּט וְהַשְׁמֵד; וְכֵן תִּרְגְּמוֹ יוֹנָתָן לְשׁוֹן כְּלָיָה:\",2,0],[2,121,47,1,\"אֶל פְּלִשְׁתִּים. עַל פְּלִשְׁתִּים:\",1,0],[2,121,47,1,\"בְּטֶרֶם יַכֶּה פַרְעֹה אֶת עַזָּה. כְּשֶׁהָיָה נְבוּכַדְנֶצַּר צָר עַל יְרוּשָׁלַיִם בַּשָּׁנָה הָעֲשִׂירִית לְצִדְקִיָּהוּ, יָצָא חֵיל פַּרְעֹה מִמִּצְרַיִם וַיַּעֲלוּ הַכַּשְׂדִּים מֵעַל יְרוּשָׁלַיִם (ירמיה לז:ה); שָׁמַע פַּרְעֹה, וְשָׁטַף אֶת עַזָּה וְשָׁב לְאַרְצוֹ. בְּסֵדֶר עוֹלָם (פרק כו):\",2,0],[2,121,47,3,\"שַׁעֲטַת. אֵין לוֹ דִּמְיוֹן; וְיוֹנָתָן תִּרְגְּמוֹ: ״מִפְּסוֹעִית״:\",1,0],[2,121,47,3,\"מֵרַעַשׁ לְרִכְבּוֹ. מֵרַעַשׁ אֲשֶׁר לְרִכְבּוֹ:\",2,0],[2,121,47,3,\"גַּלְגִּלָּיו. אוֹפַנֵּי מַרְכְּבוֹתָיו:\",3,0],[2,121,47,3,\"לֹא הִפְנוּ אָבוֹת אֶל בָּנִים. לְהַצִּילָם:\",4,0],[2,121,47,4,\"לְהַכְרִית לְצוֹר וּלְצִידוֹן. פְּלִשְׁתִּים הָיוּ עוֹזְרִים אוֹתָם מֵאוֹיְבֵיהֶם:\",1,0],[2,121,47,4,\"אִי כַפְתּוֹר. אִיזְלָ״שׁ בְּלַעַ״ז:\",2,0],[2,121,47,5,\"נִדְמְתָה. נֶחְרְבָה:\",1,0],[2,121,47,5,\"תִּתְגּוֹדָדִי. תְּשָׂרְטִי בְּאֵבֶל וּבְבֶכִי:\",2,0],[2,121,47,6,\"חֶרֶב לַה׳. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵבִיא לָעוֹלָם:\",1,0],[2,121,47,6,\"הֵרָגְעִי. לְשׁוֹן ״מַרְגּוֹעַ״ (ירמיה ו:טז):\",2,0],[2,121,48,1,\"הַמִּשְׂגָּב. שֵׁם מָקוֹם:\",1,0],[2,121,48,2,\"חֶשְׁבּוֹן. וּמַדְמֵן – שֵׁם מָקוֹם. וּלְפִי שְׁמוֹתָם הוּא מַזְכִּיר פֻּרְעָנוּתָם:\",1,0],[2,121,48,2,\"תִדֹּמִּי. תֶּחֱרָבִי:\",2,0],[2,121,48,4,\"צְעִירֶיהָ. ״שָׁלְטוֹנְהָא״ (תרגום יונתן) הַצְּעִירִים מִן הַמְּלָכִים:\",1,0],[2,121,48,5,\"מַעֲלֵה הַלּוּחִית. שֵׁם מָקוֹם הוּא מַעֲלוֹת הַר:\",1,0],[2,121,48,6,\"כַּעֲרוֹעֵר. מִגְדַּל עֲרוֹעֵר עָשׂוּי בַּמִּדְבָּר, וְאֵין סְבִיבָיו יִשּׁוּב כִּי אִם שׁוֹכְנֵי אֹהָלִים. וּמִגְדָּל הָעוֹמֵד בְּאֵין יִשּׁוּב נִרְאֶה כְּחוּרְבָה; כֵּן תִּרְגֵּם יוֹנָתָן. וּמְנַחֵם פֵּרֵשׁ כַּעֲרוֹעֵר – שֵׁם עֵץ מֵעֲצֵי הַיַּעַר:\",1,0],[2,121,48,9,\"תְּנוּ צִיץ לְמוֹאָב. תְּנוּ כָנָף לְמוֹאָב. כָּל דְּבָר תְּלַאי הַתּוֹלֶה וּבוֹלֵט מִן הָאָדָם וּמִן הַבְּהֵמָה קָרוּי צִיץ, כְּמוֹ ״וְהָיָה לָכֶם לְצִיצִת״ (במדבר טו:לט), ״וַיִּקָּחֵנִי בְּצִיצִת רֹאשִׁי״ (יחזקאל ח:ג):\",1,0],[2,121,48,9,\"כִּי נָצֹא תֵּצֵא. כִּי בִּמְעוֹפָהּ וְחִפָּזוֹן תֵּצְאוּ בַּגּוֹלָה. וְיִהְיֶה נֵצֵא מִגְּזֵרַת נִצָּהּ, כֵּן חָבְרוּ מְנַחֵם, וְכֵן ״כִּי נָצוּ גַּם נָעוּ״ (איכה ד:טו), וְיוֹנָתָן תִּרְגֵּם ״אַעֲדוֹ כִּתְרָא מִמּוֹאָב״, תְּנוּ לַאֲחֵרִים צִיץ הַנֵּזֶר אֲשֶׁר לְמוֹאָב:\",2,0],[2,121,48,10,\"מְלֶאכֶת ה׳. מְלֶאכֶת הַשְׁחָתַת מוֹאָב, שֶׁהִיא שְׁלִיחוּתוֹ שֶׁל מָקוֹם:\",1,0],[2,121,48,11,\"לֹא נָמָר. לֹא נֶחְלַף:\",1,0],[2,121,48,12,\"צוֹעִים. מְרִיקִים, וְכֵן ״מִהַר צֹעֶה לְהִפָּתֵחַ״ (ישעיהו נא:יד) – הוּא הִלּוּךְ הַמֵּעַיִם בְּשִׁלְשׁוּל:\",1,0],[2,121,48,12,\"וְנִבְלֵיהֶם. חֲבִיּוֹתֵיהֶם שֶׁל מוֹאָבִים:\",2,0],[2,121,48,12,\"יְנַפֵּצוּ. יְשַׁבְּרוּ, כְּמוֹ ״אֵיכָה נֶחְשְׁבוּ לְנִבְלֵי חֶרֶשׂ״ (איכה ד:ב); ״כָּל נֵבֶל יִמָּלֵא יָיִן״ (ירמיה יג:יב):\",3,0],[2,121,48,13,\"מִכְּמוֹשׁ. אֲשֶׁר בָּטַח בּוֹ:\",1,0],[2,121,48,13,\"מִבֵּית אֵל. עֵגֶל הַזָּהָב (מלכים א יב:לב):\",2,0],[2,121,48,17,\"נֻדוּ לוֹ. לְשׁוֹן קִינָה, כְּמוֹ ״אַל תָּנֻדוּ לוֹ״ (ירמיה כב:י):\",1,0],[2,121,48,19,\"שַׁאֲלִי נָס וְנִמְלָטָה. שַׁאֲלִי מִן הַנָּסִים וְהַנִּמְלָטִים מִמּוֹאָב מַה נִּהְיָתָה אִם נִמְלַט כְּלוּם מֵהַשְׁחִית:\",1,0],[2,121,48,21,\"וּמִשְׁפָּט בָּא. וּפוּרְעָנוּת בָּא:\",1,0],[2,121,48,26,\"הַשְׁכִּירוּהוּ. הַשְׁקוּהוּ תַּרְעֵלָה (ישעיהו נא:יז) עַד שֶׁיִּשְׁתַּכֵּר:\",1,0],[2,121,48,26,\"גַּם הוּא. כְּמוֹ שֶׁהָיָה שְׂחוֹק לוֹ:\",2,0],[2,121,48,27,\"תִּתְנוֹדָד. הָיִיתָ מֵנִיד בְּרֹאשְׁךָ וּמִתְלוֹצֵץ עַל חֻרְבָּנוֹ. לָשׁוֹן אַחֵר: כִּי מִדֵּי דְבָרֶיךָ בּוֹ – שֶׁהָיִיתָ מִתְרוֹנֵן עַל חָרְבָּנוֹ, אַתָּה תִּתְנוֹדָד – לָצֵאת בַּגּוֹלָה. וְכֵן תִּרְגֵּם יוֹנָתָן: ״עַל דְּאַסְגִּיתוֹן עֲלֵיהוֹן פִּתְגָּמִין בְּכֵן תִּיטַלְטְלוּן״:\",1,0],[2,121,48,28,\"בְּעֶבְרֵי פִי פָחַת. מָקוֹם שֶׁהַמַּיִם כּוֹרִין תַּחַת גִּדּוּדֵי שְׂפַת הַנַּחַל הַגְּבוֹהִים, וּכְשֶׁהַנַּחַל מִתְמַעֵט נִמְצֵאת הַגּוּמָא רֵיקָנִית, וְהַיּוֹנָה מְקַנֶּנֶת בְּאַחַת מֵעֶבְרֵי הַגּוּמָא, וּכְשֶׁנַּחַל רַבָּה שׁוֹטֵף אֶת הַקֵּן וְהִיא נוֹדֶדֶת מִשָּׁם; כָּךְ שָׁמַעְתִּי. וְיוֹנָתָן לֹא תִרְגֵּם כֵּן: ״וְהֲוָה כְּיוֹנָא דְּשַׁבְקָא פּוּם שׁוּבְכָהּ וְנָחֲתָא וְשָׁרְיָא בְּאַרְעִית גּוּבָא״:\",1,0],[2,121,48,30,\"עֶבְרָתוֹ וְלֹא כֵן. שִׂנְאָתוֹ לְיִשְׂרָאֵל לֹא בֶּאֱמֶת וְלֹא בְמִשְׁפָּט:\",1,0],[2,121,48,30,\"בַּדָּיו. גִּבּוֹרָיו:\",2,0],[2,121,48,30,\"לֹא כֵן עָשׂוּ. לֹא כַּגְּמוּל הֵשִׁיבוּ לְזֶרַע אַבְרָהָם, שֶׁנִּלְחַם עִם הַמְּלָכִים וְהִצִּיל אֶת לוֹט אֲבִיהֶם (בראשית יד:יד-טז):\",3,0],[2,121,48,31,\"קִיר חֶרֶשׂ. עִיר מֵאֶרֶץ מוֹאָב:\",1,0],[2,121,48,31,\"יֶהְגֶּה. גּוֹנֵחַ כְּיוֹנִים הוֹגִים:\",2,0],[2,121,48,32,\"מִבְּכִי יַעְזֵר אֶבְכֶּה לָּךְ. כְּשֶׁנֶּאֶמְרָה נְבוּאָה זוֹ כְּבָר חָרְבָה יַעְזֵר, וְהִיא סְמוּכָה לְמוֹאָב:\",1,0],[2,121,48,32,\"אֶבְכֶּה לָּךְ. אֶבְכֶּה בִּשְׁבִילֵךְ דּוּגְמַת אוֹתוֹ בֶּכִי, כִּי גַם אַתְּ תֶּחֱרְבִי כְּמוֹהוּ:\",2,0],[2,121,48,32,\"הַגֶּפֶן שִׂבְמָה. אֶרֶץ כְּרָמִים הָיְתָה:\",3,0],[2,121,48,32,\"נְטִישֹׁתַיִךְ. לְפִי שֶׁדִּמָּה אוֹתָהּ לְגֶפֶן, דִּמָּה אֶת גִּבּוֹרֶיהָ לִנְטִישׁוֹת הַגֶּפֶן:\",4,0],[2,121,48,32,\"עָבְרוּ יָם. הָלְכוּ בַּגּוֹלָה:\",5,0],[2,121,48,32,\"קֵיצֵךְ. לְשׁוֹן ״קַיִץ״ (שמואל ב טז:א) – תְּאֵנִים; וְ״קִצֵּךְ״ (ירמיה נא:יג), שֶׁהִיא לְשׁוֹן קֵץ – אֵין בּוֹ יוֹ״ד וְהַצָּדִ״י דְּגוּשָׁה:\",6,0],[2,121,48,33,\"וְנֶאֶסְפָה. וְכָלְתָה, שֶׁלֹּא תֵרָאֶה:\",1,0],[2,121,48,33,\"לֹא יִדְרֹךְ. עֲנָבִים בְּקוֹל עֲנוֹת הֵידָד, בְּשִׂמְחָה, כַּאֲשֶׁר הָיוּ עוֹשִׂים:\",2,0],[2,121,48,33,\"הֵידָד לֹא הֵידָד. שֶׁהֵידָד יִצְעֲקוּ לֹא יְהִי הֵידָד הָרִאשׁוֹן, כִּי אִם הֵידָד שֶׁל מְנוּסַת חֶרֶב:\",3,0],[2,121,48,34,\"עֶגְלַת שְׁלִשִׁיָּה. מְדִינָה גַּבְרְתָּנִית:\",1,0],[2,121,48,36,\"עַל כֵּן יִתְרַת עָשָׂה. עַל אֲשֶׁר גַּאֲוָה עָשָׂה, לְכָךְ אָבָדוּ:\",1,0],[2,121,48,37,\"גְּדֻדוֹת. שְׂרִיטוֹת:\",1,0],[2,121,48,39,\"אֵיךְ חַתָּה הֵילִילוּ. הֵילִילוּ עָלֶיהָ וְאִמְרוּ אֵיךְ חַתָּה:\",1,0],[2,121,48,40,\"כַּנֶּשֶׁר יִדְאֶה. הָאוֹיֵב אֶל מוֹאָב:\",1,0],[2,121,48,40,\"יִדְאֶה. יָעוּף:\",2,0],[2,121,48,41,\"הַקְּרִיּוֹת. שֵׁם הָעִיר:\",1,0],[2,121,48,43,\"פַּחַד וָפַחַת. אֵלּוּ שְׁנֵי דְבָרִים קָשִׁים זֶה אֵצֶל זֶה, שֶׁהַפַּחַד גּוֹרֵם לוֹ לָנוּס, וְהַפַּחַת מוּכָן לִיפּוֹל בּוֹ:\",1,0],[2,121,48,43,\"פַּחַת. פוֹשָׁ״א בְּלַעַ״ז:\",2,0],[2,121,48,45,\"בְּצֵל חֶשְׁבּוֹן. שֶׁהִיא גְבוֹהָה וְיֵשׁ לָהּ צֵל:\",1,0],[2,121,48,45,\"עָמְדוּ. הַנָּסִים לָנוּחַ בַּצֵּל, אֲשֶׁר לֹא הָיָה בָּהֶן עוֹד כֹּחַ לָנוּס:\",2,0],[2,121,48,45,\"מִבֵּן סִיחוֹן. מֵעִיר סִיחוֹן, כְּמוֹ ״בֶּן רְאוּבֵן״ בִּיהוֹשֻׁעַ (יהושע טו:ו):\",3,0],[2,121,48,45,\"וְקָדְקֹד. אַטְרִיפִירְצְדָ״א בְּלַעַ״ז, וּמְנַחֵם חִבְּרוֹ לְשׁוֹן מָקוֹר, וְיוֹנָתָן תִּרְגֵּם: ״וִיקִירֵי״, לְשׁוֹן יְקָר:\",4,0],[2,121,48,45,\"בְּנֵי שָׁאוֹן. אוֹתָם שֶׁהָיוּ מַגְבִּיהִים קוֹל תִּפְאָרֶת:\",5,0],[2,121,49,1,\"הֲבָנִים אֵין לְיִשְׂרָאֵל. בֵּי״ת רָפָה וְהֵ״א חֲטַף פַּתָּח, שֶׁהוּא לְשׁוֹן תְּמִיהָה:\",1,0],[2,121,49,1,\"מַלְכָּם. עֲבוֹדַת כּוֹכָבִים שֶׁל בְּנֵי עַמּוֹן מַלְכָּם שְׁמָהּ, שֶׁנֶּאֱמַר: ״וּלְמִלְכֹּם תּוֹעֲבַת בְּנֵי עַמּוֹן״ (מלכים ב כג:יג):\",2,0],[2,121,49,3,\"כִּי שֻׁדְּדָה עַי. הַסְּמוּכָה לָהּ, וּמֵאֶרֶץ עַמּוֹן הִיא:\",1,0],[2,121,49,3,\"בְּנוֹת רַבָּה. רַבַּת בְּנֵי עַמּוֹן:\",2,0],[2,121,49,3,\"וְהִתְשׁוֹטַטְנָה בַּגְּדֵרוֹת. תִּרְגְּמוֹ יוֹנָתָן: ״וְאִתְהַמְּמוֹן בְּסִיעָן״ – הִתְגּוֹדְדוּ בַּחֲיָלוֹת; פָּתַר וְהִתְשׁוֹטַטְנָה – לְשׁוֹן חֲיָלוֹת מְשׁוֹטְטִים, וּגְדֵרוֹת – לְשׁוֹן ״גִּדְרוֹת צֹאן״ (במדבר לב:טז) הַמְּלֵאִים עֲדָרִים. וְיֵשׁ לִפְתֹּר: וְהִתְשׁוֹטַטְנָה – וְהִתְעוֹלַלְנָה בְּזֶבֶל גִּדְרוֹת צֹאן, לְשׁוֹן בִּזָּיוֹן; ״וַיִּבֶז עֵשָׂו״ (בראשית כה:לד): ״וְשָׁט עֵשָׂו״ (תרגום אונקלוס):\",3,0],[2,121,49,4,\"תִּתְהַלְלִי. תִּתְפָּאֲרִי, וַונְטִי״ר בְּלַעַ״ז:\",1,0],[2,121,49,4,\"בָּעֲמָקִים. שֶׁאַרְצֵךְ אֶרֶץ עֲמָקִים וְאֵין עֲצִירַת גְּשָׁמִים קָשָׁה לָהּ, שֶׁאֵין חַמָּה שׁוֹלֶטֶת בָּהּ:\",2,0],[2,121,49,4,\"זָב עִמְקֵךְ. מַכַּת רֹב גְּשָׁמִים בָּאָה, עַד שֶׁזָּבוּ הַמַּיִם בָּעֵמֶק וְשָׁטְפוּ שָׁרְשֵׁי הַתְּבוּאָה; כָּךְ פֵּרְשׁוֹ מְנַחֵם:\",3,0],[2,121,49,5,\"אִישׁ לְפָנָיו. כָּל אֲשֶׁר יוּכַל לְמַהֵר וְלָנוּס:\",1,0],[2,121,49,5,\"לַנֹּדֵד. לְשׁוֹן ״נָע וָנָד״ (בראשית ד:יב):\",2,0],[2,121,49,7,\"בְּתֵימָן. אֱדוֹם בִּדְרוֹמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל הִיא, כְּמָה שֶׁנֶּאֱמַר ״וְהָיָה לָכֶם פְּאַת נֶגֶב מִמִּדְבַּר צִן עַל יְדֵי אֱדוֹם״ (במדבר לד:ג):\",1,0],[2,121,49,7,\"מִבָּנִים. מִדּוֹר זֶה:\",2,0],[2,121,49,7,\"נִסְרְחָה. ״אִתְקַלְקְלַת״ (תרגום יונתן):\",3,0],[2,121,49,8,\"הָפְנוּ. הִתְבַּעֲרוּ מִן הַמָּקוֹם הַזֶּה, לְשׁוֹן ״וּפִנּוּ אֶת הַבַּיִת״ (ויקרא יד:לו):\",1,0],[2,121,49,8,\"הֶעְמִיקוּ לָשֶׁבֶת. לְהֵחָבֵא בְּעִמְקֵי מִסְתָּרִים. נֻסוּ הָפְנוּ הֶעְמִיקוּ. כֻּלָּם לְשׁוֹן צִוּוּי הֵם:\",2,0],[2,121,49,9,\"אִם בּוֹצְרִים בָּאוּ לָךְ חָשַׂפְתִּי אֶת וְגוֹ׳ שְׁמוּעָה שָׁמַעְתִּי וְגוֹ׳. כָּל כְּעֵין דּוּגְמָא זוֹ נִבָּא עוֹבַדְיָה עַל אֱדוֹם (עובדיה א:א-ה), וּלְפִי שֶׁסִּיגְנוֹן אֶחָד עוֹלֶה לְכַמָּה נְבִיאִים וְאֵין שְׁנֵי נְבִיאִים מִתְנַבְּאִים בְּסִיגְנוֹן אֶחָד (סנהדרין פט.), בְּמִקְצָת הַדְּבָרִים מִשְׁתַּנִּין:\",1,0],[2,121,49,9,\"לֹא יַשְׁאִירוּ עוֹלֵלוֹת. בִּתְמִיהָּ: וְהַשּׁוֹדְדִים שֶׁבָּאוּ עָלֶיךָ, לֹא הִשְׁאִירוּ לְךָ כְּלוּם!\",2,0],[2,121,49,10,\"חָשַׂפְתִּי. גִּלֵּיתִי, כְּמוֹ ״מַחְשֹׂף הַלָּבָן״ (בראשית ל:לז). וְאַתָּה הִסְגַּרְתָּ שְׂרִידֵי יִשְׂרָאֵל לְמַעַן לֹא יִשָּׁאֵר מֵהֶם אִישׁ; כְּמָה שֶׁנֶּאֱמַר ״אַל תַּסְגֵּר שְׂרִידָיו״ (עובדיה א:יד):\",1,0],[2,121,49,10,\"וְנֶחְבָּה לֹא יוּכָל. וִיבַקֵּשׁ לְהֵחָבֵא וְלֹא יוּכָל:\",2,0],[2,121,49,11,\"עָזְבָה יְתֹמֶיךָ. שֶׁיִּתַּמְתָּ בְּיִשְׂרָאֵל:\",1,0],[2,121,49,12,\"אֲשֶׁר אֵין מִשְׁפָּטָם לִשְׁתּוֹת. שֶׁלֹּא הָיוּ אַחִים לָהֶם, וְאִם הֵרֵעוּ לָהֶם, אֵין לָהֶם מִשְׁפַּט מָוֶת כְּמוֹתְךָ:\",1,0],[2,121,49,13,\"לְחֶרְפָּה וְלִקְלָלָה תִּהְיֶה בָצְרָה. בָּצְרָה מֵעָרֵי מוֹאָב, אֶלָּא מִפְּנֵי הָעִנְיָן שֶׁנֶּאֱמַר ״יוֹבָב בֶּן זֶרַח מִבָּצְרָה״ (בראשית לו:לג), הִיא לוֹקָה עִמּוֹ:\",1,0],[2,121,49,15,\"קָטֹן נְתַתִּיךָ. שֶׁאֵין בָּהֶם מֶלֶךְ בֶּן מֶלֶךְ; לֹא הָיָה דַּרְכָּם בְּרוֹמִי לְהַעֲמִיד מֶלֶךְ בֶּן מֶלֶךְ (עבודה זרה י.):\",1,0],[2,121,49,16,\"תִּפְלַצְתְּךָ. לְשׁוֹן בֶּהָלָה; שֶׁהָיִיתָ מְמַהֵר וְנִבְהָל לְעוֹרֵר שְׂטִימָתְךָ לְאָחִיךָ. וְיֵשׁ לוֹעֲזִין לְשׁוֹן ״פַּלָּצוּת״ (ישעיה כא:ד); וְיֵשׁ לוֹעֲזִין לְשׁוֹן ״מִפְלֶצֶת״ (מלכים א טו:יג):\",1,0],[2,121,49,16,\"הִשִּׁיא אוֹתָךְ. לְהָרַע לָהֶם:\",2,0],[2,121,49,16,\"שׁוֹכְנִי. שׁוֹכֵן:\",3,0],[2,121,49,16,\"תּוֹפְשִׂי. כְּמוֹ ״תּוֹפֵשׂ״ (ירמיה נ:טז), וְהַיּוֹ״ד יְתֵרָה בּוֹ:\",4,0],[2,121,49,19,\"כְּאַרְיֵה יַעֲלֶה מִגְּאוֹן הַיַּרְדֵּן. שֶׁהוּא מְקוֹם אֲרָיוֹת, כְּתַרְגּוּמוֹ שֶׁל יוֹנָתָן, כֵּן יַעֲלֶה הָאוֹיֵב אֶל נְוֵה אֵיתָן:\",1,0],[2,121,49,19,\"אַרְגִּיעָה. אַקְרִיב אֶת הָרֶגַע:\",2,0],[2,121,49,19,\"אֲרִיצֶנּוּ מֵעָלֶיהָ. פִּתְאוֹם וּבְהַצְלָחָה יַחֲרִיבֶנָּה, וְיָשׁוּב לוֹ בְּרֶגַע קָטָן אֶל מְקוֹמוֹ. וַאֲנִי אוֹמֵר: אֲרִיצֶנּוּ מֵעָלֶיהָ מִמַּעַל לָהּ, שֶׁיְּהֵא מִתְגַּבֵּר עָלֶיהָ וְעֶלְיוֹן לָהּ; וְכֵן ״מִמַּעַל לָרָקִיעַ״ (יחזקאל א:כו); וְכֵן ״מִמַּעַל לוֹ״ (ישעיה ו:ב); ״מֵעַל לְמַדָּיו״ (שמואל א יז:לט):\",3,0],[2,121,49,19,\"וּמִי בָחוּר. אוֹתוֹ שֶׁבָּחַרְתִּי לִנְקוֹם נִקְמָתִי עָלֶיהָ אֶפְקֹד:\",4,0],[2,121,49,19,\"וּמִי יֹעִידֶנִּי. לַמִּלְחָמָה, לְהִלָּחֵם אִתִּי:\",5,0],[2,121,49,19,\"רוֹעֶה. מֶלֶךְ:\",6,0],[2,121,49,20,\"אִם לֹא. לְשׁוֹן בֶּאֱמֶת:\",1,0],[2,121,49,20,\"יִסְחָבוּם. יִגְרְרוּם:\",2,0],[2,121,49,20,\"צְעִירֵי הַצֹּאן. בְּזוּיֵי הָאֻמּוֹת. וְרַבּוֹתֵינוּ דָּרְשׁוּ (יומא י.): פָּרַס, שֶׁהוּא הַצָּעִיר בִּבְנֵי יֶפֶת (בראשית י:ב):\",3,0],[2,121,49,20,\"יַשִּׁים. לְשׁוֹן שְׁמָמָה:\",4,0],[2,121,49,23,\"בּוֹשָׁה חֲמָת וְאַרְפָּד. עָרֵי אֲרָם, כִּי שָׁמְעוּ שְׁמֻעָה רָעָה עַל דַּמֶּשֶׂק, שֶׁהִיא רֹאשׁ אֲרָם, כְּמָה שֶׁנֶּאֱמַר ״כִּי רֹאשׁ אֲרָם דַּמֶּשֶׂק״ (ישעיהו ז:ח); לְכָךְ נָמֹגוּ:\",1,0],[2,121,49,23,\"בְּיָם דְּאָגָה. דַּאֲגָתָהּ דּוֹמָה לְדַאֲגַת הַיָּם הַשְׁקֵט לֹא יוּכָל. כָּל דְּאָגָה לְשׁוֹן יִרְאָה הוּא:\",2,0],[2,121,49,24,\"רָפְתָה דַמֶּשֶׂק. רָפוּ יָדֶיהָ מֵהִלָּחֵם:\",1,0],[2,121,49,24,\"וְרֶטֶט. זִיעַ:\",2,0],[2,121,49,25,\"אֵיךְ לֹא עֻזְּבָה. לֹא נִתְמַלֵּאת עָפָר סְבִיב חוֹמָתָהּ לְחַזֵּק הַחוֹמָה, כְּמוֹ ״וַיַּעַזְבוּ אֶת יְרוּשָׁלַיִם עַד הַחוֹמָה״ (נחמיה ג:ח). וְיֵשׁ עוֹד לִפְתֹּר: לָמָּה לֹא נֶעֶזְבָה מִן הָרָעָה הַזֹּאת, שֶׁלֹּא תָבֹא הָרָעָה עָלֶיהָ?\",1,0],[2,121,49,25,\"קִרְיַת מְשׂוֹשִׂי. כָּךְ יִתְאַבֵּל מַלְכָּהּ עָלֶיהָ:\",2,0],[2,121,49,26,\"לָכֵן. לְשׁוֹן שְׁבוּעָה:\",1,0],[2,121,49,26,\"יִדַּמּוּ. יֶחֶרָבוּ, וְאֵינוֹ זָז מִלְּשׁוֹן דְּמָמָה, שֶׁכָּל עִיר חֲרֵבָה אֵין קוֹל נִשְׁמָע בָּהּ:\",2,0],[2,121,49,28,\"קֵדָר. שׁוֹכְנֵי מִדְבָּרוֹת בָּאֳהָלִים הֵם, אֵין חוֹמָה וְאֵין עִיר:\",1,0],[2,121,49,29,\"מָגוֹר. אֵימַאשְׁמְנְ״ט בְּלַעַ״ז. לָשׁוֹן אַחֵר: לְשׁוֹן יִרְאָה:\",1,0],[2,121,49,30,\"כִּי יָעַץ עֲלֵיכֶם וגו׳. וּמָה הִיא הָעֵצָה? קוּמוּ עֲלוּ אֶל גּוֹי שָׁלֵיו:\",1,0],[2,121,49,31,\"בָּדָד יִשְׁכֹּנוּ. בֶּטַח בִּיחִידוּת; אֵין צְרִיכִין לְהִתְאַסֵּף וְלֵישֵׁב בְּרֹב אָדָם, שֶׁאֵין יְרֵאִים שֶׁיָּבֹא אוֹיֵב עֲלֵיהֶם:\",1,0],[2,121,49,32,\"קְצוּצֵי פֵאָה. מוּקְצִים מִקָּצֶה אֶל קָצֶה הָרוּחוֹת:\",1,0],[2,121,49,35,\"אֶת קֶשֶׁת עֵילָם. אֶת תִּקְוַת עֵילָם (ס״א חָזְקַת עֵילָם):\",1,0],[2,121,49,35,\"רֵאשִׁית גְּבוּרָתָם. מֵיטַב גְּבוּרָתָם:\",2,0],[2,121,49,38,\"וְשַׂמְתִּי כִסְאִי. מָצוֹר שֶׁלִּי:\",1,0],[2,121,50,2,\"וּשְׂאוּ נֵס. פּוֹרְקָ״א בְּלַעַ״ז, סִימַן אֲסִיפָה הוּא:\",1,0],[2,121,50,2,\"בֵּל. וּמְרֹדָךְ – שְׁמוֹת עֲבוֹדָה זָרָה שֶׁל בָּבֶל:\",2,0],[2,121,50,3,\"גּוֹי מִצָּפוֹן. מָדַי וּפָרָס:\",1,0],[2,121,50,5,\"דֶּרֶךְ הֵנָּה. דֶּרֶךְ הַמָּקוֹם הַזֶּה, יְרוּשָׁלַיִם, יָסֵבּוּ פְנֵיהֶם, כְּשֶׁתֶּחֱרַב בָּבֶל וְיֵצְאוּ מִתּוֹכָהּ בִּרְשִׁיּוֹן כּוֹרֶשׁ מֶלֶךְ פָּרַס:\",1,0],[2,121,50,6,\"רוֹעֵיהֶם הִתְעוּם. גְּדוֹלֵיהֶם הִתְעוּם מֵעָלַי:\",1,0],[2,121,50,6,\"הָרִים שׁוֹבְבוּם. אֶל הֶהָרִים, אֶל עֲבוֹדַת כּוֹכָבִים שֶׁבֶּהָרִים. שׁוֹבְבוּם אַנְוִויזַאנְ״ץ בְּלַעַ״ז, שׁוֹבְבוּם מַלְכֵיהֶם. וְיוֹנָתָן תִּרְגֵּם הָרִים שׁוֹבְבוּם ״שַׁלְטוֹנִיָּא בְּזוֹנוּן״:\",2,0],[2,121,50,7,\"וּמִקְוֵה אֲבוֹתֵיהֶם. ״וְסִבּוּר אֲבָהָתְהוֹן״ (תרגום יונתן):\",1,0],[2,121,50,8,\"נֻדוּ מִתּוֹךְ בָּבֶל. מֵעַתָּה צְאוּ מִשָּׁם:\",1,0],[2,121,50,8,\"כְּעַתּוּדִים לִפְנֵי צֹאן. דֶּרֶךְ הָעַתּוּדִים לָלֶכֶת לִפְנֵי הָעֵדֶר בְּרֹאשׁ הָעִזִּים:\",2,0],[2,121,50,9,\"וְעָרְכוּ לָהּ. ״וִיסַדְּרוּן עֲלַהּ קְרָב״ (תרגום יונתן):\",1,0],[2,121,50,11,\"שׁוֹסֵי נַחֲלָתִי. בּוֹזְזֵי נַחֲלָתִי:\",1,0],[2,121,50,11,\"כִּי תָפוּשׁוּ. לְשׁוֹן שׁוּמָן:\",2,0],[2,121,50,11,\"כְּעֶגְלָה דָשָׁה. הַדָּשָׁה בַּתְּבוּאָה וְאוֹכֶלֶת תָּמִיד:\",3,0],[2,121,50,12,\"אִמְּכֶם. כְּנֵסִיַּתְכֶם:\",1,0],[2,121,50,12,\"אַחֲרִית. אַתֶּם, הַכַּשְׂדִּים, אִם רֵאשִׁיתְכֶם גָּדוֹל, אַחֲרִיתְכֶם יִהְיוּ מִדְבָּר:\",2,0],[2,121,50,14,\"יְדוּ אֵלֶיהָ. זִרְקוּ לָהּ אֲבָנִים, כְּמוֹ ״וַיַּדּוּ אֶבֶן בִּי״ (איכה ג:נג):\",1,0],[2,121,50,15,\"וְנָתְנָה יָדָהּ. כְּאָדָם שֶׁאֵין בּוֹ כֹּחַ וּמוֹשִׁיט יָד לְכָל מִי שֶׁרוֹאֶה, לְבַקֵּשׁ רַחֲמִים וְעֶזְרָה; וְכֵן ״מִצְרַיִם נָתְנוּ יָד״ (איכה ה:ו) – הוֹשַׁטְנוּ יָד לְמִצְרַיִם לְבַקֵּשׁ מֵהֶם עֶזְרָה:\",1,0],[2,121,50,15,\"אָשְׁיוֹתֶיהָ. חֹזֶק יְסוֹדוֹתֶיהָ, וְכֵן ״וְאֻשַּׁיָּא יְחִיטוּ״ (עזרא ד:יב). וּבִלְשׁוֹן מִשְׁנָה (בבא קמא נ.): כְּגוֹן אֵלּוּ הַחוֹפְרִים לְאוּשִׁין; וְכֵן ״וְהִתְאוֹשָׁשׁוּ״ (ישעיה מו:ח) – וְהִתְחַזְּקוּ:\",2,0],[2,121,50,15,\"כַּאֲשֶׁר עָשְׂתָה. לְעִיר ה׳:\",3,0],[2,121,50,16,\"כִּרְתוּ זוֹרֵעַ. ״שַׁיְצוּ מַלְכָּא מִבָּבֶל וַאֲחִידוּ חַרְבָּא בְּעִידָּן קְטוֹל״ (תרגום יונתן):\",1,0],[2,121,50,17,\"הָרִאשׁוֹן אֲכָלוֹ. שֶׁהִגְלָה עֲשֶׂרֶת הַשְּׁבָטִים:\",1,0],[2,121,50,17,\"עִצְּמוֹ. גֵּרְמוֹ, גִּירֵם עַצְמוֹתָיו, שֶׁגָּמַר הַשְּׁיָרִים: יְהוּדָה וּבִנְיָמִין. עִצְּמוֹ דִּישׁוֹשָׁ״ר בְּלַעַ״ז:\",2,0],[2,121,50,19,\"וְרָעָה הַכַּרְמֶל. לְשׁוֹן ״מִרְעֶה״ (בראשית מז:ד):\",1,0],[2,121,50,21,\"מְרָתַיִם. שֶׁהִמְרַתַּנִי וְהִרְגַּזְתַּנִי:\",1,0],[2,121,50,21,\"פְּקוֹד. שֵׁם מְדִינָה, וְכֵן ״פְּקוֹד וְשׁוֹעַ וְקוֹעַ״ (יחזקאל כג:כג) תִּרְגֵּם יוֹנָתָן שֵׁם מְדִינוֹת:\",2,0],[2,121,50,21,\"וַעֲשֵׂה כְּכֹל אֲשֶׁר צִוִּיתִיךָ. אַתָּה, כּוֹרֶשׁ, בְּיַד יְשַׁעְיָה הַנָּבִיא (ישעיה מה):\",3,0],[2,121,50,23,\"פַּטִּישׁ כָּל הָאָרֶץ. שֶׁהָיָה מְפוֹצֵץ וּמְכַתֵּת אֶת הַכֹּל:\",1,0],[2,121,50,24,\"יָקֹשְׁתִּי לָךְ. לְשׁוֹן ״מוֹקֵשׁ״ (דברים ז:טז):\",1,0],[2,121,50,26,\"בֹּאוּ לָהּ מִקֵּץ. מִסּוֹף הָעִיר הִתְחִילוּ בָהּ, שֶׁלֹּא תֵּדַע וְתִתָּפֵשׂ פִּתְאוֹם:\",1,0],[2,121,50,26,\"פִּתְחוּ מַאֲבֻסֶיהָ. תִּרְגֵּם יוֹנָתָן: ״אִבּוּלָהָא״ – שַׁעֲרֵיהָּ; וְאֵין לוֹ דִּמְיוֹן. וּמְנַחֵם חִבְּרוֹ לְשׁוֹן אֵבוּס:\",2,0],[2,121,50,26,\"סָלּוּהָ. דּוּשׁוּ אוֹתָהּ:\",3,0],[2,121,50,26,\"כְּמוֹ עֲרֵמִים. גְּרָנוֹת:\",4,0],[2,121,50,27,\"כָּל פָּרֶיהָ. שָׂרֶיהָ. כֵּן דֶּרֶךְ הַנְּבִיאִים לְהַמְשִׁיל הַשָּׂרִים לְפָרִים (ישעיה לד:ז), אַבִּירִים (ישעיה לד:ז), וְלַעֲתוּדִים (ישעיה יד:ט):\",1,0],[2,121,50,29,\"הַשְׁמִיעוּ אֶל בָּבֶל רַבִּים. לְשׁוֹן ״וַיַּשְׁמַע שָׁאוּל אֶת הָעָם״ (שמואל א טו:ד): הַזְעִיקוּ לְהֵאָסֵף אֶל בָּבֶל מוֹרִים בְּחִצִּים; כְּמוֹ ״יָסֹבּוּ עָלַי רַבָּיו״ (איוב טז:יג):\",1,0],[2,121,50,30,\"לָכֵן. לְשׁוֹן שְׁבוּעָה:\",1,0],[2,121,50,34,\"הִרְגִּיעַ אֶת הָאָרֶץ. כְּשֶׁתִּפּוֹל בָּבֶל יְהִי מַרְגּוֹעַ וְהַנָּחָה לַכֹּל:\",1,0],[2,121,50,36,\"אֶל הַבַּדִּים. אֶל הַקּוֹסְמִים שֶׁלָּהּ:\",1,0],[2,121,50,36,\"וְנֹאָלוּ. בְּקִסְמֵיהֶם. וְדוֹמֶה לוֹ: ״מֵפֵר אוֹתוֹת בַּדִּים״ (ישעיה מד:כה), וְכֵן תִּרְגְּמוֹ יוֹנָתָן; עַל שֵׁם שֶׁבּוֹדִים וְאוֹמְרִים דִּבְרֵי כָּזָב:\",2,0],[2,121,50,37,\"הָעֶרֶב. ״סוּמְכְוָותָא״ (תרגום יונתן); גְּרַנְטִיאָ״ה בְּלַעַ״ז:\",1,0],[2,121,50,38,\"וּבָאֵימִים יִתְהֹלָלוּ. יִשְׁתַּטּוּ. לָשׁוֹן אַחֵר: פורוונטרונט בְּלַעַ״ז, וְכֵן תִּרְגֵּם יוֹנָתָן: ״מִשְׁתַּבְּחִין״ – בֵּאלֹהֵי הָעֲנָקִים שֶׁהָיוּ לָהֶם:\",1,0],[2,121,50,39,\"צִיִּים אֶת אִיִּים. ״יְעָרְעוּן תַּמְוָן בַּחֲתוּלִין״ (תרגום יונתן), מִינֵי חַיּוֹת הַמְּצוּיִין בְּחוּרְבָּה:\",1,0],[2,121,50,44,\"הִנֵּה כְּאַרְיֵה. אֲשֶׁר יַעֲלֶה מִגְּאוֹן הַיַּרְדֵּן כֵּן יָבֹא הַשּׁוֹדֵד אֶל נְוֵה אֵיתָן. כָּךְ תִּרְגֵּם יוֹנָתָן: ״הָא מֶלֶךְ בְּמַשְׁרִיָּתֵיהּ יִיסַק עֲלֵיהוֹן כְּאַרְיָא דְּסָלִיק מֵרוּם יַרְדְּנָא״; לָמַדְנוּ, שֶׁגְּאוֹן הַיַּרְדֵּן מְקוֹם אֲרָיוֹת הוּא. וְאַף כָּךְ תִּרְגְּמוֹ יוֹנָתָן ״וְאֵיךְ תַּעֲשֶׂה בִּגְאוֹן הַיַּרְדֵּן״ (ירמיה יב:ה): ״לְקָבֵיל חֵיוָא בָּרָא בְּרוּם יַרְדְּנָא״:\",1,0],[2,121,50,44,\"כִּי אַרְגִּיעָה. כְּשֶׁאָבִיא הַשָּׁעָה:\",2,0],[2,121,50,44,\"מֵעָלֶיהָ. מִמַּעַל לָהּ:\",3,0],[2,121,50,44,\"וּמִי יֹעִידֶנִּי. לַמִּלְחָמָה:\",4,0],[2,121,50,45,\"צְעִירֵי הַצֹּאן. פָּרַס, צָעִיר לִבְנֵי יֶפֶת (בראשית י:ב; יומא י.):\",1,0],[2,121,51,1,\"לֵב קָמָי. כַּשְׂדִּים בְּגִימַטְרִיָּא דְּא״ת ב״ש, רוּחַ מַשְׁחִית אֶת רוּחַ מֶלֶךְ פָּרַס וּמָדַי שֶׁהוּא מַשְׁחִית. רוּחַ טַלְנְ״ט בְּלַעַ״ז:\",1,0],[2,121,51,2,\"וְזֵרוּהָ. וְנִפְּצוּהָ:\",1,0],[2,121,51,2,\"וִיבֹקְקוּ. וִירוֹקְנוּ:\",2,0],[2,121,51,3,\"אֶל יִדְרֹךְ הַדּרֵךְ. הֲרֵי זֶה מִקְרָא קָצָר: אֶל אֲשֶׁר אֲנִי אוֹמֵר, שָׁם יִדְרֹךְ הַדּרֵךְ קַשְׁתּוֹ:\",1,0],[2,121,51,3,\"וְאַל יִתְעַל בְּסִרְיוֹנוֹ. אַל יֵרָפֵא:\",2,0],[2,121,51,5,\"כִּי לֹא אַלְמָן. לֹא שְׁכָחוֹ מִלִּנְקוֹם נִקְמָתוֹ:\",1,0],[2,121,51,5,\"כִּי אַרְצָם. שֶׁל כַּשְׂדִּים:\",2,0],[2,121,51,6,\"נֻסוּ. יִשְׂרָאֵל מִתּוֹךְ בָּבֶל:\",1,0],[2,121,51,7,\"כּוֹס זָהָב. הָיְתָה בָּבֶל עַד הֵנָּה בְּיַד ה׳ לְשַׁכֵּר בָּהּ אֶת כָּל הָאָרֶץ יֵין הַחֵימָה (ירושלמי פסחים י:א):\",1,0],[2,121,51,7,\"עַל כֵּן יִתְהוֹלְלוּ גוֹיִם. נִשְׁתַּכְּרוּ וְנִשְׁתַּטּוּ:\",2,0],[2,121,51,9,\"נָגַע אֶל הַשָּׁמַיִם מִשְׁפָּטָהּ. גָּבַהּ פּוּרְעָנוּתָהּ עַד אֶל הַשָּׁמַיִם:\",1,0],[2,121,51,10,\"הוֹצִיא ה׳ אֶת צִדְקוֹתֵינוּ. נִזְכַּרְנוּ לְפָנָיו לִזְכוּת, וּבָאוּ צִדְקוֹת אֲבוֹתֵינוּ לְפָנָיו:\",1,0],[2,121,51,11,\"הָבֵרוּ. לְשׁוֹן נִקָּיוֹן:\",1,0],[2,121,51,11,\"הַשְּׁלָטִים. אַשְׁפּוֹת שֶׁהַחִצִּים נְתוּנִים בָּהֶם:\",2,0],[2,121,51,12,\"גַּם זָמַם ה׳. זֶה יָמִים רַבִּים:\",1,0],[2,121,51,12,\"גַּם עָשָׂה. אֶת מְזִמָּתוֹ. דֶּרֶךְ הַמִּקְרָא לְדַבֵּר שְׁנֵי גַמִּין זֶה אַחַר זֶה, וְעַל יְדֵי הָאַחֲרוֹן בָּא הָרִאשׁוֹן:\",2,0],[2,121,51,13,\"בָּא קִצֵּךְ. קֵץ שֶׁלָּךְ:\",1,0],[2,121,51,13,\"אַמַּת בִּצְעֵךְ. מִדַּת חֲמָסֵךְ. לָשׁוֹן אַחֵר: אַמַּת בִּצְעֵךְ. מִדַּת סוֹפֵךְ; כְּמוֹ ״כִּי יְבַצַּע״ (ישעיה י:יב):\",2,0],[2,121,51,14,\"בְּנַפְשׁוֹ. אִינְשִׁימִישִׁימוֹ״שׁ בְּלַעַ״ז:\",1,0],[2,121,51,14,\"כִּי אִם. לְשׁוֹן בֶּאֱמֶת:\",2,0],[2,121,51,14,\"מִלֵּאתִיךְ אָדָם. אֲמַלִּינָךְ מַשְׁרְיָת עַמְּמִין דְּסַגִּיאִין כְּזַחֲלָא״ (תרגום יונתן):\",3,0],[2,121,51,14,\"וְעָנוּ עָלַיִךְ הֵידָד. ״וִירִימוּן עֲלָךְ בְּקָלְהוֹן״ (תרגום יונתן):\",4,0],[2,121,51,17,\"נִבְעַר כָּל אָדָם. הָעוֹשֶׂה פֶּסֶל לֶאֱלוֹהַּ:\",1,0],[2,121,51,17,\"נִסְכּוֹ. לְשׁוֹן ״מַסֵּכָה״ (שמות לב:ד):\",2,0],[2,121,51,18,\"בְּעֵת פְּקֻדָּתָם. כְּשֶׁיִּפְקֹד הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם וְעַל עוֹבְדֵיהֶם:\",1,0],[2,121,51,19,\"וְשֵׁבֶט נַחֲלָתוֹ. יַעֲקוֹב הַנִּזְכָּר לְמַעְלָה בְּרֹאשׁ הַמִּקְרָא:\",1,0],[2,121,51,20,\"מַפֵּץ אַתָּה לִי. עַד הֵנָּה הֶעֱמַדְתִּיךָ לִי לְמַשְׁחִית וּלְמַפֵּץ אֶת הָאֻמּוֹת שֶׁגָּזַרְתִּי עֲלֵיהֶם גּוֹלָה:\",1,0],[2,121,51,24,\"וְשִׁלַּמְתִּי לְבָבֶל. אַחֲרֵי כָּל זֹאת, שֶׁאֶגְמֹר נִקְמָתִי עַל יָדוֹ בְּעוֹבְדֵי כּוֹכָבִים:\",1,0],[2,121,51,27,\"קַדְּשׁוּ. זַמְּנוּ:\",1,0],[2,121,51,27,\"טִפְסָר. לְשׁוֹן ״חַיִל״ (מלכים א כ:כה) (אוֹ לְשׁוֹן אָדוֹן):\",2,0],[2,121,51,27,\"סָמָר. הִירִיצִי״ר בְּלַעַ״ז, כְּמוֹ ״תְּסַמֵּר שַׂעֲרַת בְּשָׂרִי״ (איוב ד:טו):\",3,0],[2,121,51,29,\"וַתָּחֹל. לְשׁוֹן ״חַלְחָלָה״ (ישעיה כא:ג):\",1,0],[2,121,51,30,\"נָשְׁתָה. קָפְצָה; כְּמוֹ ״גִּיד הַנָּשֶׁה״ (בראשית לב:לג), שֶׁנָּשָׁה מִמְּקוֹמוֹ (חולין צא.):\",1,0],[2,121,51,33,\"כְּגֹרֶן עֵת הִדְרִיכָהּ. הֲרֵי הִיא עַתָּה מְלֵאָה כְּגֹרֶן בְּעֵת שֶׁדָּשׁוּ תְּבוּאָתָהּ, שֶׁהִיא מְלֵאָה חִטִּין:\",1,0],[2,121,51,33,\"עוֹד מְעַט. וְתִתְרוֹקֵן וְתִדְמֶה לְגֹרֶן בְּעֵת תְּחִלַּת הַקָּצִיר, שֶׁהִיא רֵיקָנִית:\",2,0],[2,121,51,35,\"חֲמָסִי וּשְׁאֵרִי. צַעֲקַת חֲמָסִי וּמְזוֹנוֹתַי, אֲשֶׁר אָכְלוּ שְׁאֵרִי:\",1,0],[2,121,51,38,\"נָעֲרוּ. לְשׁוֹן חֲמוֹר נוֹעֵר (ברכות ג.):\",1,0],[2,121,51,39,\"בְּחֻמָּם אָשִׁית אֶת מִשְׁתֵּיהֶם. אֲכַוֵּין שֶׁיְּהוּ מִשְׁתֵּיהֶן בְּעֵת הַחוֹם, כְּדֵי שֶׁיִּשְׁתַּכְּרוּ:\",1,0],[2,121,51,39,\"לְמַעַן יַעֲלֹזוּ וְיָשְׁנוּ. וְיִרְדְּמוּ:\",2,0],[2,121,51,39,\"שְׁנַת עוֹלָם. שֵׁנָה עוֹלָמִית. וְכֵן עָלְתָה בָּם: מִתּוֹךְ מִשְׁתֶּה וְשִׁכְרוּת נֶחְרְבוּ וְנֶהֶרְגוּ, וְנִלְכְּדָה הָעִיר; כְּמוֹ שֶׁנֶּאֱמַר בְּדָנִיֵּאל ״בֵּלְשַׁצַּר אָמַר בִּטְעֵם חַמְרָא וְגוֹ׳״ (דניאל ה:ב), ״אִשְׁתִּיו חַמְרָא וְגוֹ׳״ (דניאל ה:ד), ״בֵּיהּ בְּלֵילְיָא קְטִיל בֵּלְשַׁאצַּר מַלְכָּא וְגוֹ׳״ (דניאל ה:ל), ״וְדָרְיָוֶשׁ מָדָאָה קַבִּיל מַלְכוּתָא״ (דניאל ו:א):\",3,0],[2,121,51,40,\"כְּכָרִים. כְּבָשִׂים, (וְיוֹנָתָן תִּרְגֵּם) ״כְּתוֹרִין״:\",1,0],[2,121,51,41,\"שֵׁשַׁךְ. בָּבֶל בְּגִימַטְרִיָּא דְּא״ת ב״ש (תנחומא, קרח יב):\",1,0],[2,121,51,42,\"עָלָה עַל בָּבֶל הַיָּם. חַיִל גָּדוֹל כְּמוֹ הַיָּם:\",1,0],[2,121,51,44,\"עַל בֵּל. עַל עֲבוֹדַת כּוֹכָבִים שֶׁל בָּבֶל:\",1,0],[2,121,51,44,\"אֶת בִּלְעוֹ. שֶׁהוּשְׁפְּלוּ כָּל יוֹשְׁבֵי הָאָרֶץ תַּחְתָּיו:\",2,0],[2,121,51,44,\"וְלֹא יִנְהֲרוּ. וְלֹא יֵאָסְפוּ; וְכֵן ״וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם״ (ישעיהו ב:ב) – כְּמֵימֵי נְהָרוֹת כֻּלָּם הַהוֹלְכִים אֶל הַיָּם (קהלת א:ז):\",3,0],[2,121,51,46,\"בַּשְּׁמוּעָה הַנִּשְׁמַעַת בָּאָרֶץ. הַשְּׁמוּעָה הַזֹּאת שֶׁל בֵּלְשַׁצַּר שֶׁנֶּהֱרַג:\",1,0],[2,121,51,46,\"וּבָא בַשָּׁנָה הַשְּׁמוּעָה. בְּאוֹתָהּ שָׁנָה עַצְמָהּ תָּבוֹא הַשְּׁמוּעָה שֶׁחָרְבָה בָּבֶל מֵאֵלֶיהָ מִן הַשָּׁמַיִם, שֶׁנֶּאֱמַר ״וְהָיְתָה בָבֶל צְבִי מַמְלָכוֹת תִּפְאֶרֶת גְּאוֹן כַּשְׂדִּים כְּמַהְפֵּכַת אֱלֹהִים אֶת סְדֹם וְאֶת עֲמֹרָה״ (ישעיה יג:יט):\",2,0],[2,121,51,46,\"וְאַחֲרָיו בַּשָּׁנָה. הַשְּׁנִיָּה:\",3,0],[2,121,51,46,\"הַשְּׁמוּעָה. הַטּוֹבָה לָכֶם: ״כֹּה אָמַר כּוֹרֶשׁ מֶלֶךְ פָּרַס״ (עזרא א:ב), ״מִי בָכֶם מִכָּל עַמּוֹ״ (עזרא א:ג):\",4,0],[2,121,51,46,\"וּמֹשֵׁל עַל מֹשֵׁל. דָּרְיָוֶשׁ הַמָּדִי מָלַךְ שָׁנָה אַחַת, וּבַשָּׁנָה הַשְּׁנִיָּה כּוֹרֶשׁ הַפַּרְסִי:\",5,0],[2,121,51,49,\"גַּם בָּבֶל. הָיְתָה לִנְפֹּל בָּהּ חַלְלֵי יִשְׂרָאֵל:\",1,0],[2,121,51,49,\"גַּם לְבָבֶל. יִפְּלוּ חַלְלֵי כָל אַרְצָהּ:\",2,0],[2,121,51,50,\"פְּלֵטִים מֵחֶרֶב. יִשְׂרָאֵל שֶׁגָּלוּ לְתוֹכָהּ, שֶׁפָּלְטוּ מֵחֶרֶב נְבוּזַרְאֲדָן (מלכים ב כה:ח-יב):\",1,0],[2,121,51,51,\"כִּי שָׁמַעְנוּ חֶרְפָּה. שֶׁהָיוּ כַשְׂדִּים אוֹמְרִים וּמְחָרְפִים אוֹתָנוּ לֵאמֹר: יַד אֱלֹהֵינוּ רָמָה, שֶׁהֶחֱרַבְנוּ אֶת בֵּיתוֹ:\",1,0],[2,121,51,52,\"יֶאֱנֹק חָלָל. יִצְעַק חָלָל; כְּשֶׁהוֹרְגִים אֶת הָאָדָם בְּחֵץ אוֹ בְרוֹמַח וְהוּא גּוֹנֵחַ כְּשֶׁמּוֹצִיא הָרוֹמַח, הִיא הָאֲנָקָה:\",1,0],[2,121,51,53,\"וְכִי תְבַצֵּר. לְשׁוֹן מִבְצָר, חוֹזֶק:\",1,0],[2,121,51,53,\"מֵאִתִּי יָבֹאוּ שׁוֹדְדִים לָהּ. מֵאִתִּי, מִן הַשָּׁמַיִם הַגְּבוֹהִים מִמֶּנָּה, יָבֹאוּ לָהּ הַשּׁוֹדְדִים:\",2,0],[2,121,51,55,\"נִתַּן שְׁאוֹן קוֹלָם. נִשְׁמַע קוֹל צַעֲקָתָם:\",1,0],[2,121,51,58,\"תִּתְעַרְעָר. לְשׁוֹן חֲפִירָה, לְשׁוֹן ״עָרוּ עָרוּ עַד הַיְסוֹד״ (תהלים קלז:ז):\",1,0],[2,121,51,58,\"בְּדֵי רִיק. בְּהַרְבֵּה רִיק שֶׁיָּבֹא עֲלֵיהֶם:\",2,0],[2,121,51,59,\"שַׂר מְנוּחָה. ״רַב תִּקְרוֹבְתָּא״ (תרגום יונתן); עַל יָדוֹ הָיוּ רוֹאִים אֶת פְּנֵי הַמֶּלֶךְ הַמְּבִיאִים לוֹ תְּשׁוּרָה:\",1,0],[2,121,52,3,\"כִּי עַל אַף ה׳ הָיְתָה. הִיא גָּרְמָה לוֹ, מֶרֶד צִדְקִיָּהוּ בְּמֶלֶךְ בָּבֶל, שֶׁהוּא תְּחִלַּת הַחֻרְבָּן:\",1,0],[2,121,52,4,\"דָּיֵק. ״כַּרְכּוֹם״ (תרגום יונתן):\",1,0],[2,121,52,7,\"יִבְרְחוּ. כְּמוֹ בָּרְחוּ:\",1,0],[2,121,52,7,\"דֶּרֶךְ שַׁעַר בֵּין הַחֹמֹתַיִם. מְעָרָה הָיְתָה לוֹ מִבֵּיתוֹ עַד עַרְבוֹת יְרִיחוֹ (פסיקתא רבתי כו); וּכְבָר פֵּרַשְׁתִּיהָ בַּסֵּפֶר הַזֶּה (לט:ד):\",2,0],[2,121,52,9,\"רִבְלָתָה. הִיא אַנְטוֹכְיָא (סנהדרין צו:):\",1,0],[2,121,52,9,\"וַיְדַבֵּר אִתּוֹ מִשְׁפָּטִים. עַל שֶׁעָבַר עַל הַשְּׁבוּעָה:\",2,0],[2,121,52,10,\"אֶת כָּל שָׂרֵי יְהוּדָה. סַנְהֶדְרִין, שֶׁאָמַר לָהֶם: אַתֶּם הִתַּרְתֶּם לוֹ אֶת שְׁבוּעָתוֹ (תנחומא, ואתחנן א). וְחֵטְא הָיָה בְּעֵינֵי הָאֱלֹהִים לְהַתִּיר הַשְּׁבוּעָה:\",1,0],[2,121,52,11,\"בֵּית הַפְּקֻדּוֹת. בְּבֵית הָאֲסִירִין:\",1,0],[2,121,52,13,\"בֵּית הַגָּדוֹל. בָּתֵּי כְנֵסִיּוֹת שֶׁמְּגַדְּלִין בָּהֶם תְּפִלָּה, וְיֵשׁ אוֹמְרִים: בָּתֵּי מִדְרָשׁוֹת שֶׁמְּגַדְּלִין בָּהֶם אֶת הַתּוֹרָה. מַחֲלֹקֶת הָאָמוֹרָאִים הִיא (מגילה כז.):\",1,0],[2,121,52,15,\"יֶתֶר הָאָמוֹן. כְּמוֹ ״הֶהָמוֹן״ (שמואל א ד:יד):\",1,0],[2,121,52,16,\"וּלְיֹגְבִים. חוֹפְרִין בָּאָרֶץ. רַבּוֹתֵינוּ אָמְרוּ (שבת כו.): צָדֵי חִלָּזוֹן:\",1,0],[2,121,52,17,\"וְאֶת הַמְּכֹנוֹת. שֶׁל כִּיּוֹרוֹת (מלכים א ז:מג):\",1,0],[2,121,52,18,\"הַמְזַמְּרוֹת. הֵם כְּלֵי זֶמֶר:\",1,0],[2,121,52,19,\"וְאֶת הַסִּפִּים. תִּרְגֵּם יוֹנָתָן: ״קוּלְיָא״, וְלֹא יָדַעְתִּי אִם מִמִּינֵי כְּלֵי זֶמֶר הוּא. וְאוֹמֵר אֲנִי שֶׁהֵן אַגָּנוֹת לְקַבֵּל דָּם, כְּמוֹ ״בַּדָּם אֲשֶׁר בַּסָּף״ (שמות יב:כב). וְיֵשׁ מְפָרְשִׁים הַסִּפִּים – לְשׁוֹן כַּדִּים, לְפִי תַּרְגּוּם שֶׁל יוֹנָתָן, שֶׁתִּרְגֵּם: ״קוּלְיָא״, כִּי כֵן תִּרְגֵּם אוּנְקְלוֹס ״וְכַדָּהּ עַל שִׁכְמָהּ״ (בראשית כד:טו): ״וְקוּלְתָהּ עַל כַּתְפָהָא״; וְלָשׁוֹן זֶה נִרְאֶה שֶׁהַסִּפִּים אֵינָם מִמִּין כְּלֵי זֶמֶר, אֶלָּא הֵם כַּדִּים:\",1,0],[2,121,52,19,\"הַמַּחְתּוֹת. שֶׁחוֹתִין בָּהֶם גֶּחָלִים מֵעַל הַמִּזְבֵּחַ:\",2,0],[2,121,52,19,\"הַמְּנַקִיּוֹת. סְנִיפֵי הַזָּהָב שֶׁבָּהֶם מַעֲמִידִין לֶחֶם הַפָּנִים, כְּמוֹ שֶׁשָּׁנִינוּ בִּמְנָחוֹת (מנחות צז.):\",3,0],[2,121,52,20,\"אֲשֶׁר תַּחַת הַמְּכֹנוֹת. לֹא יָדַעְתִּי הֵיאַךְ, שֶׁהֲרֵי תַּחַת הַיָּם הָיוּ (מלכים א ז:מד); וְדוֹמֶה לִי שֶׁאֵין זֶה אֶלָּא כְּמוֹ אֵצֶל הַמְּכֹנוֹת:\",1,0],[2,121,52,21,\"יְסֻבֶּנּוּ. יַקִּיפֶנּוּ עֹגֶל הֶקֵּפוֹ:\",1,0],[2,121,52,21,\"וְעָבְיוֹ אַרְבַּע אֶצְבָּעוֹת. סְבִיב חֲלָלוֹ:\",2,0],[2,121,52,21,\"נָבוּב. חָלוּל:\",3,0],[2,121,52,22,\"וּשְׂבָכָה וְרִמּוֹנִים עַל הַכּוֹתֶרֶת. עֲשׂוּיָה כִּשְׁתֵּי אֲגָנוֹת, אַחַת כְּדַרְכָּהּ וְאַחַת כְּפוּיָה עַל פִּי הַתַּחְתּוֹנָה, וְהָעֶלְיוֹנָה קְרוּיָה שְׂבָכָה; קוֹיְיפָ״א בְּלַעַ״ז. וְרִמּוֹנִים תְּחוּבִים הָיוּ בְּשַׁרְשְׁרוֹת, וְהַשַּׁרְשְׁרוֹת שְׁנֵי רָאשֶׁיהָ קְשׁוּרִין יַחַד, וּנְתוּנָה עַל הַשְּׂבָכָה, מָקוֹם שֶׁהַשְּׂבָכָה קְצָרָה, וְהִיא יוֹרֶדֶת עַד מְקוֹם דֶּבֶק הַשְּׂבָכָה וְכוֹתֶרֶת, שֶׁהִיא הַבֶּטֶן הָרָחָב שֶׁבַּכּוֹתֶרֶת, וְשָׁם עוֹמֶדֶת; וְהָרִמּוֹנִים מְכַסִּים אֶת מְקוֹם הִדָּבֵק שְׁתֵּי פִּיּוֹת הָאֲגָנוֹת הַמְּדֻבָּקִים יַחַד:\",1,0],[2,121,52,23,\"תִּשְׁעִים וְשִׁשָּׁה רוּחָה. וּבְסוֹף הַמִּקְרָא הוּא אוֹמֵר: כָּל הָרִמּוֹנִים מֵאָה עַל הַשְּׂבָכָה, וּבְסֵפֶר מְלָכִים הוּא אוֹמֵר ״וְהָרִמּוֹנִים מָאתַיִם טוּרִים״ (מלכים א ז:כ) – אַרְבַּע מֵאוֹת לִשְׁתֵּי הַשְּׂבָכוֹת! אֱמוֹר מֵעַתָּה: אַרְבַּע מֵאוֹת הָיוּ לִשְׁתֵּי הַשְּׂבָכוֹת עַל שְׁנֵי הָעַמּוּדִים, שְׁנֵי טוּרִים לְכָל שְׂבָכָה; וְהַטּוּר מֵאָה הוּא, שֶׁאָמַר כָּאן כָּל הָרִמּוֹנִים מֵאָה עַל הַשְּׂבָכָה – לַטּוּר הָאֶחָד, וּמָאתַיִם לִשְׁנֵי הַטּוּרִים, הוּא הָאוֹמֵר שָׁם ״הָרִמּוֹנִים מָאתַיִם טוּרִים סָבִיב״ – מָאתַיִם לִשְׁנֵי טוּרִים סָבִיב לָעַמּוּד הָאֶחָד, וְכֵן לַשֵּׁנִי, הֲרֵי אַרְבַּע מֵאוֹת. וְהָעַמּוּדִים הֶעֱמִידָם שְׁלֹמֹה בָּאוּלָם סָמוּךְ לְכוֹתֶל הַהֵיכָל, וְהַכּוֹתֶל מְכַסֶּה אַרְבַּע רִמּוֹנִים מִכָּל טוּר, שֶׁאֵין נִרְאִים מִבַּחוּץ; הוּא שֶׁאָמוּר כָּאן: וַיִּהְיוּ הָרִמֹּנִים תִּשְׁעִים וְשִׁשָּׁה רוּחָה:\",1,0],[2,121,52,23,\"רוּחָה. כְּמוֹ לָרוּחַ; כָּל תֵּיבָה שֶׁצְּרִיכָה לָמֶ״ד בִּתְחִלָּתָהּ, הִטִּיל לָהּ הֵ״א בְּסוֹפָהּ (יבמות יג:), וּלְכָךְ הַטַּעַם מִלְמַעְלָה תַּחַת הָרֵי״שׁ; כְּלוֹמַר: תִּשְׁעִים וְשִׁשָּׁה מֵהֶם נִרְאִים לְרוּחוֹת הָעַמּוּד. זוֹ לָמַדְתִּי בְּפִרְקֵי שְׁלֹשִׁים וּשְׁתַּיִם מִדּוֹת שֶׁאָמַר רַבִּי אֱלִיעֶזֶר בְּנוֹ שֶׁל רַבִּי יוֹסֵי הַגְּלִילִי (מידה יט):\",2,0],[2,121,52,24,\"כֹּהֵן הַמִּשְׁנֶה. סְגַן הַכֹּהֲנִים, הַמְמֻנֶּה תַּחַת כֹּהֵן גָּדוֹל לְשַׁמֵּשׁ תַּחְתָּיו, אִם יֶאֱרַע בּוֹ פְּסוּל:\",1,0],[2,121,52,24,\"שׁוֹמְרֵי הַסַּף. ״אֲמַרְכְּלִין״ (תרגום יונתן), שֶׁמַּפְתְּחוֹת הָעֲזָרָה מְסוּרוֹת לָהֶן:\",2,0],[2,121,52,25,\"וְשִׁבְעָה אֲנָשִׁים מֵרֹאֵי פְנֵי הַמֶּלֶךְ. וּבְסֵפֶר מְלָכִים (מלכים ב כה:יט) אָמַר ״וַחֲמִשָּׁה אֲנָשִׁים״. הַשְּׁנַיִם חֲשׁוּבִים וְלֹא חֲשׁוּבִים כָּל כָּךְ (שיר השירים רבה ג:יג):\",1,0],[2,121,52,25,\"הַמַּצְבִּא אֶת עַם הָאָרֶץ. יוֹדֵעַ מִנְיָן שֶׁל כָּל עִיר וָעִיר, כַּמָּה אֲנָשִׁים מוֹצִיאָה לַצָּבָא:\",2,0],[2,121,52,28,\"בִּשְׁנַת שֶׁבַע. הִיא גָּלוּת יְכָנְיָה; וּבְסֵפֶר מְלָכִים אָמַר ״בִּשְׁנַת שְׁמוֹנֶה״ (מלכים ב כד:יב), הָא כֵּיצַד? שְׁנַת שְׁמוֹנֶה שֶׁמָּלַךְ נְבוּכַדְנֶצַּר, שְׁנַת שֶׁבַע – שֶׁכִּבֵּשׁ אֶת יְהוֹיָקִים לְעֶבֶד; דְּאָמַר מַר (מגילה יא:): שָׁנָה רִאשׁוֹנָה כִּבֵּשׁ נִינְוֵה, שְׁנִיָּה עָלָה וְכִבֵּשׁ יְהוֹיָקִים:\",1,0],[2,121,52,28,\"יְהוּדִים שְׁלֹשֶׁת אֲלָפִים. וּמִשְּׁאָר שְׁבָטִים שִׁבְעַת אֲלָפִים, הֲרֵי עֲשֶׂרֶת אֲלָפִים. הַכָּתוּב הַזֶּה, שֶׁפֵּירֵשׁ יְהוּדִים שְׁלֹשֶׁת אֲלָפִים, הִכְרִיעַ בֵּין שְׁנֵי מִקְרָאוֹת שֶׁבְּסוֹף סֵפֶר מְלָכִים: פָּסוּק אֶחָד אוֹמֵר ״עֲשֶׂרֶת אֲלָפִים״ (מלכים ב כד:יד) וְאֶחָד אוֹמֵר ״שִׁבְעַת אֲלָפִים״ (מלכים ב כד:טז), בָּא זֶה וּפֵירֵשׁ: יְהוּדִים שְׁלֹשֶׁת אֲלָפִים וּמִשְּׁאָר שְׁבָטִים שִׁבְעַת אֲלָפִים, הֲרֵי עֲשֶׂרֶת אֲלָפִים:\",2,0],[2,121,52,29,\"בִּשְׁנַת שְׁמֹנֶה עֶשְׂרֵה. הִיא גָּלוּת צִדְקִיָּהוּ. וּלְמַעְלָה הוּא אוֹמֵר שְׁנַת תְּשַׁע עֶשְׂרֵה לַמֶּלֶךְ נְבוּכַדְנֶצַּר! – תְּשַׁע עֶשְׂרֵה שֶׁמָּלַךְ, שְׁמֹנֶה עֶשְׂרֵה שֶׁכִּבֵּשׁ אֶת יְהוֹיָקִים (סדר עולם רבה כז):\",1,0],[2,121,52,30,\"בִּשְׁנַת שָׁלֹשׁ וְעֶשְׂרִים. נִתְּנָה צוֹר בְּיָדוֹ, וְשָׁטַף יְהוּדִים שֶׁבִּסְבִיבוֹת עַמּוֹן וּמוֹאָב שְׁבַע מֵאוֹת וְאַרְבָּעִים וַחֲמִשָּׁה; כָּךְ מְפֹרָשׁ בְּסֵדֶר עוֹלָם (סדר עולם רבה כו):\",1,0],[2,121,52,31,\"בְּעֶשְׂרִים וַחֲמִשָּׁה לַחֹדֶשׁ. וּבְמָקוֹם אַחֵר הוּא אוֹמֵר ״בְּעֶשְׂרִים וְשִׁבְעָה לַחֹדֶשׁ״ (מלכים ב כה:כז)! בְּעֶשְׂרִים וַחֲמִשָּׁה לַחֹדֶשׁ מֵת שִׂטְנוֹ נְבוּכַדְנֶאצַּר, וּבְעֶשְׂרִים וְשִׁשָּׁה נִקְבַּר וְהוֹצִיאוֹ אֱוִיל מְרֹדַךְ מִקִּבְרוֹ, וּבְעֶשְׂרִים וְשִׁבְעָה מָלַךְ וְנָשָׂא אֶת רֹאשׁ יְהוֹיָכִין:\",1,0],[2,121,52,31,\"נָשָׂא. נְשָׂאוֹ וְגִדְּלוֹ. לִישְׁנָא אַחֲרִינָא: מְנָאוֹ עִם שְׁאָר הַמְּלָכִים, כְּמוֹ ״שָׂא אֶת רֹאשׁ בְּנֵי יִשְׂרָאֵל״ (במדבר לא:כו; שמות ל:יב):\",2,0],[2,121,52,34,\"וַאֲרֻחָתוֹ. נוֹטֵל פְּרָס מִבֵּית הַמֶּלֶךְ לְכָל צְרָכָיו (תנחומא, מסעי יב):\",1,0],[2,122,1,1,\"אִישׁ הָיָה בְאֶרֶץ עוּץ. פֵּירוּשׁוֹ: בְּאֶרֶץ אֲרָם, כְּמָה דִכְתִיב ״אֶת עוּץ בְּכֹרוֹ״ מִבְּנֵי נָחוֹר (בראשית כב:כא):\",1,0],[2,122,1,1,\"וְהָיָה הָאִישׁ. אַף עַל פִּי שֶׁהוּא לְשׁוֹן עָתִיד, כֵּן דֶּרֶךְ לָשׁוֹן עִבְרִית; וּלְשׁוֹן מְלִיצָתוֹ: וְהוֹוֶה הָאִישׁ הַהוּא גָּדוֹל מִכָּל בְּנֵי קֶדֶם – בְּנֵי אֶרֶץ הַמִּזְרָחִי; שֶׁאֲרָם בְּמִזְרָחוֹ שֶׁל עוֹלָם הוּא, שֶׁנֶּאֱמַר ״מִן אֲרָם יַנְחֵנִי בָלָק מֵהַרְרֵי קֶדֶם״ (במדבר כג:ז). דָּבָר אַחֵר: עוּץ – זֶה אִיּוֹב; בּוּז – זֶה אֱלִיהוּא בֶּן בַּרַכְאֵל הַבּוּזִי; וַהֲרֵי הוּא שֶׁאָמַר אִיּוֹב: ״וּבוּז מִשְׁפָּחוֹת יְחִתֵּנִי״ (איוב לא:לד) – זֶה הוּא מִמִּשְׁפַּחְתִּי שֶׁמִּחְתָּה דְבָרַי; וְהַיְנוּ דְּאָמְרֵי אִינְשֵׁי (סנהדרין לט:): מִינֵּהּ וּבֵהּ אַבָּא לֵיזִיל בֵּהּ נַרְגָּא. דָּבָר אַחֵר: בְּאֶרֶץ עוּץ. בְּאֶרֶץ שֶׁנּוֹטְלִין מִמֶּנּוּ עֵצוֹת רָעוֹת עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנֶּאֱמַר ״מִן הָאָרֶץ הַהִיא יָצָא אַשּׁוּר״ (בראשית י:יא); וּמָה עֵצָה נָטְלוּ? שֶׁהָיוּ אוֹמְרִים: לֹא כָּל הֵימֶנּוּ לִטּוֹל אֶת הָעֶלְיוֹנִים וְלִתֵּן לָנוּ אֶת הַתַּחְתּוֹנִים! אֶלָּא בּוֹאוּ לְאֶרֶץ שִׁנְעָר שֶׁשָּׁם אֱלוֹהוֹת הַרְבֵּה, שֶׁנֶּאֱמַר בָּהּ ״אֶרֶץ פְּסִילִים הִיא״ (ירמיהו נ:לח). ״וְנַעֲשֶׂה מִגְדָּל וְרֹאשׁוֹ בַשָּׁמַיִם וְנַעֲשֶׂה לָּנוּ שֵׁם״ (בראשית יא:ד), וְאֵין שֵׁם הָאָמוּר כָּאן אֶלָּא עֲבוֹדַת כּוֹכָבִים, שֶׁנֶּאֱמַר ״וְשֵׁם אֱלֹהִים אֲחֵרִים לֹא תַזְכִּירוּ״ (שמות כג:יג). מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? יָשַׁב עֲלֵיהֶם בְּדִין וְהֶעֱמִיד עֲלֵיהֶם עֵדִים, שֶׁנֶּאֱמַר ״וַיֵּרֶד ה׳ לִרְאֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל״ (בראשית יא:ה) – וְכִי צָרִיךְ יְרִידָה לִפְנֵי הַמָּקוֹם לִרְאוֹת? וְהַכְּתִיב ״עֵינֵי ה׳ מְשׁוֹטְטוֹת בְּכָל הָאָרֶץ״ (זכריה ד:י)! אֶלָּא לְלַמֵּד הֲלָכָה לְדוֹרוֹת, שֶׁאֵין דָּנִין אֶלָּא עַל פִּי עֵדֵי רְאִיָּה, שֶׁנֶּאֱמַר ״אוֹ רָאָה אוֹ יָדָע״ (ויקרא ה:א):\",2,0],[2,122,1,1,\"וְהָיָה. פְּשׁוּטוֹ כְּמוֹ וַיְהִי, וּמַשְׁמָעוֹ לְעָבָר וּלְהַבָּא:\",3,0],[2,122,1,1,\"תָּם וְיָשָׁר. אֲבָל בִּדְבָרִים שֶׁבֵּין קוֹנוֹ וּבֵינוֹ לֹא הָיָה צַדִּיק? לְכָךְ נֶאֱמַר: וִירֵא אֱלֹהִים וְסָר מֵרָע:\",4,0],[2,122,1,3,\"שִׁבְעַת אַלְפֵי צֹאן. הָרוֹב מָנָה תְּחִלָּה:\",1,0],[2,122,1,3,\"גָּדוֹל מִכָּל בְּנֵי קֶדֶם. מִדּוֹר הַפְּלַגָּה, דִּכְתִיב ״וַיְהִי בְּנָסְעָם מִקֶּדֶם״ (בראשית יא:ב). אֲבָל מֵאַבְרָהָם אֵינוֹ כֵּן, שֶׁהֲרֵי בְּאַבְרָהָם כְּתִיב בּוֹ ׳הַגָּדוֹל׳, שֶׁנֶּאֱמַר ״וְשֵׁם חֶבְרוֹן לְפָנִים קִרְיַת אַרְבַּע הָאָדָם הַגָּדוֹל בָּעֲנָקִים הוּא״ (יהושע יד:טו). הָיָה לוֹ לִכְתֹּב ׳אָדָם גָּדוֹל׳, וְלָמָּה כָּתַב ״הָאָדָם הַגָּדוֹל״? אֶלָּא רֶמֶז שֶׁהוּא אָדָם גָּדוֹל, שֶׁעָמַד בְּעֶשֶׂר נִסְיוֹנוֹת. לְפִיכָךְ כּוֹתְבִין אוֹתוֹ שְׁנֵי הֵהִי״ן. וְאִיּוֹב שֶׁנֶּאֱמַר בּוֹ גָּדוֹל – לֹא עָמַד אֶלָּא בְּאַחַת, שֶׁנֶּאֱמַר ״תָּם וְיָשָׁר וְגוֹ׳״ – מִכָּל אוֹתוֹ הַדּוֹר, שֶׁלֹּא נִתְפַּס עַל אוֹתוֹ עָוֹן (סא״א):\",2,0],[2,122,1,4,\"וְהָלְכוּ בָנָיו וְעָשׂוּ מִשְׁתֶּה בֵּית אִישׁ יוֹמוֹ. בְּבֵית כָּל אֶחָד וְאֶחָד יוֹמוֹ:\",1,0],[2,122,1,4,\"וְשָׁלְחוּ וְקָרְאוּ. כְּמוֹ וְשׁוֹלְחִים וְקוֹרְאִים, שֶׁהָיוּ עוֹשִׂין כֵּן תָּמִיד:\",2,0],[2,122,1,5,\"וַיְהִי כִּי הִקִּיפוּ. כַּאֲשֶׁר כָּלוּ יְמֵי הַמִּשְׁתֶּה, נוֹהֵג הָיָה אִיּוֹב בְּכָל סוֹף שִׁבְעַת הַיָּמִים, שֶׁחָזְרוּ יְמֵי חֲלִילָתָם, הָיָה שׁוֹלֵחַ וּמְקַדְּשָׁם, כְּלוֹמַר: מְזַמְּנָם וְקוֹרְאָם; כְּמוֹ ״הִתְקַדְּשׁוּ לְמָחָר״ (במדבר יא:יח):\",1,0],[2,122,1,5,\"וְהִשְׁכִּים בַּבֹּקֶר וְהֶעֱלָה. מְלִיצָתוֹ, שֶׁהָיָה מַשְׁכִּים וּמַעֲלֶה עוֹלוֹת. לָכֵן כָּתַב בִּלְשׁוֹן עָתִיד, שֶׁהָיָה נוֹהֵג לַעֲשׂוֹת כֵּן תָּמִיד, לְסוֹף כָּל שִׁבְעַת הַיָּמִים:\",2,0],[2,122,1,5,\"מִסְפַּר כֻּלָּם. הַבָּנִים וְהַבָּנוֹת:\",3,0],[2,122,1,5,\"וּבֵרְכוּ. לְשׁוֹן כִּנּוּי כְּלַפֵּי מַעְלָה:\",4,0],[2,122,1,5,\"כָּכָה יַעֲשֶׂה אִיּוֹב. כְּמוֹ הָיָה עוֹשֶׂה מָחָר; כְּשֶׁכָּתַב בְּדָבָר הַהוֹוֶה וְתָדִיר, פְּעָמִים שֶׁכָּתַב בּוֹ לְשׁוֹן עָבָר וּפְעָמִים לְשׁוֹן עָתִיד:\",5,0],[2,122,1,6,\"וַיְהִי הַיּוֹם. אוֹתוֹ יוֹם שֶׁהָיָה רֹאשׁ הַשָּׁנָה (ראש השנה טז.), שֶׁהוּא יוֹם תְּרוּעָה, וְצִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לַשָּׂטָן לְהָבִיא זְכוּת וְחוֹבָה שֶׁל כָּל הַבְּרִיּוֹת. הֲדָא הוּא דִּכְתִיב מִשּׁוּט בָּאָרֶץ:\",1,0],[2,122,1,6,\"וַיָּבֹאוּ בְּנֵי הָאֱלֹהִים לְהִתְיַצֵּב עַל־ה׳. לָרִיב עִמּוֹ, שֶׁאֵין לְהִתְיַצֵּב אֶלָּא עַל־דִּין, שֶׁנֶּאֱמַר: ״נִצָּב לָרִיב ה׳״ (ישעיהו ג:יג):\",2,0],[2,122,1,6,\"וַיָּבֹא גַם הַשָּׂטָן בְּתוֹכָם. לְקַטְרֵג הַבְּרִיּוֹת:\",3,0],[2,122,1,7,\"מֵאַיִן תָּבֹא. דִּבֵּר הַכָּתוּב דֶּרֶךְ אֶרֶץ, שֶׁהַגָּדוֹל מְדַבֵּר תְּחִלָּה וּמַרְשֶׁה הַקָּטָן לַעֲנוֹת:\",1,0],[2,122,1,7,\"מִשּׁוּט בָּאָרֶץ. כַּאֲשֶׁר מְפֹרָשׁ לְמַעְלָה, וּבַהַגָּדָה דְּהַשּׁוּתָּפִין הוּא (בבא בתרא טז.):\",2,0],[2,122,1,7,\"מִשּׁוּט בָּאָרֶץ וּמֵהִתְהַלֵּךְ בָּהּ. כֵּן דַּרְכִּי, לָשׁוּט וְלִרְאוֹת רָעִים וְטוֹבִים; וְשׁוֹטַטְתִּי בְּכָל הָאָרֶץ וְלֹא מָצָאתִי כְּאַבְרָהָם, שֶׁנֶּאֱמַר בּוֹ ״קוּם הִתְהַלֵּךְ בָּאָרֶץ״ (בראשית יג:יז). וְאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (בבא בתרא טז.): שָׂטָן לְשֵׁם שָׁמַיִם נִתְכַּוֵּן, כְּדֵי שֶׁלֹּא יְהֵא נִשְׁכָּח לִפְנֵי אֱלֹהֵינוּ זְכוּתוֹ שֶׁל אַבְרָהָם:\",3,0],[2,122,1,8,\"הֲשַׂמְתָּ לִבְּךָ עַל עַבְדִּי אִיּוֹב. שֶׁתִּרְצֶה לְקַטְרְגוֹ:\",1,0],[2,122,1,8,\"הֲשַׂמְתָּ. לְשׁוֹן תֵּימַהּ הוּא:\",2,0],[2,122,1,8,\"תָּם וְיָשָׁר. שָׁלֵם בְּמַעֲשָׂיו:\",3,0],[2,122,1,9,\"הֶחִנָּם יָרֵא אִיּוֹב. בִּתְמִיהַּ:\",1,0],[2,122,1,10,\"הֲלֹא. אַתָּה שַׂכְתָּ בַּעֲדוֹ לְפִי שֶׁהוּא יוֹדֵעַ שֶׁאַתָּה רָגִיל אֶצְלוֹ לַעֲשׂוֹת לוֹ נִסִּים, וּפָרֶה וְרָבֶה, לְפִיכָךְ עוֹשֶׂה צְדָקוֹת הַלָּלוּ; אֲבָל לֹא נִסִּיתָ אוֹתוֹ:\",1,0],[2,122,1,10,\"שַׂכְתָּ בַעֲדוֹ. הִגַּנְתָּ בַּעֲדוֹ, כִּמְחִיצָּה זוֹ; כְּמוֹ ״הָסֵר מְשׂוּכָתוֹ״ (ישעיהו ה:ה) – מְחִיצָתוֹ. וְכָל ׳בְּעַד׳ הָאָמוּר בִּלְשׁוֹן עִבְרִי אֵינוֹ אֶלָּא לְשׁוֹן ׳כְּנֶגְדּוֹ וּבְפָנָיו׳; כְּמוֹ ״וְכַפֵּר בַּעַדְךָ״ (ויקרא ט:ז) – קַנַּח הֶעָוֹן כְּנֶגְדְּךָ וּבְפָנֶיךָ, לִהְיוֹת הַכַּפָּרָה מָגֵן בַּעַדְךָ; וְכֵן ״ה׳ מָגֵן בַּעֲדִי״ (תהלים ג:ד):\",2,0],[2,122,1,10,\"פָּרַץ בָּאָרֶץ. נִתְחַזְּקוּ, כְּמוֹ ״וְכֵן יִפְרֹץ״ (שמות א:יב), וּמְתַרְגְּמִינָן: ״יִתְקוֹף״. זֶהוּ פְּשׁוּטוֹ. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה אָמְרוּ בַּהַגָּדָה (בבא בתרא טו:; טז.): פָּרַץ גְּדֵרוֹ שֶׁל עוֹלָם, שֶׁהָעִזִּים הוֹרְגִים הַזְּאֵבִים:\",3,0],[2,122,1,11,\"וְאוּלָם. לוּ הָיִיתָ נוֹגֵעַ בְּכָל אֲשֶׁר לוֹ, אִם לֹא עַל פָּנֶיךָ יְבָרְכֶךָּ. מִיָּד; בִּתְמִיהַּ. וְאָז:\",1,0],[2,122,1,12,\"וַיֹּאמֶר ה׳ אֶל הַשָּׂטָן הִנֵּה כָל אֲשֶׁר לוֹ בְּיָדֶךָ. (דָּבָר אַחֵר:) וַיְהִי הַיּוֹם, אוֹתוֹ הַיּוֹם שֶׁחָזְרוּ חֲלִילָה לֶאֱכוֹל בְּבֵית אֲחִיהֶם הַבְּכוֹר:\",1,0],[2,122,1,12,\"בְּנֵי הָאֱלֹהִים. צְבָא הַשָּׁמַיִם הַקְּרוֹבִים לַשְּׁכִינָה, לִהְיוֹת בְּנֵי בֵיתוֹ; וְעַל שֵׁם כָּךְ נִקְרְאוּ בָּנָיו:\",2,0],[2,122,1,12,\"לְהִתְיַצֵּב עַל ה׳. סְבִיבוֹתָיו, כְּמוֹ ״לְכָל הַנִּצָּבִים עָלָיו״ (בראשית מה:א):\",3,0],[2,122,1,14,\"עַל יְדֵיהֶם. כְּמוֹ ״אִישׁ עַל יָדוֹ״ (במדבר ב:יז). וְאֵינוֹ לְשׁוֹן ׳מָקוֹם׳, אֶלָּא עַל שֵׁם שֶׁהוּא מוּכָן וּמְזֻמָּן לְיָדוֹ. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה אָמְרוּ בַּהַגָּדָה (בבא בתרא טו:; טז.) שֶׁהִטְעִימָם הַקָּדוֹשׁ בָּרוּךְ הוּא מֵעֵין עוֹלָם הַבָּא, שֶׁלְּאַחַר חֲרִישַׁת הָאֲתוֹנוֹת הָיוּ זוֹרְעִים עִם הַחֲרִישָׁה וְרוֹעוֹת הָאֲתוֹנוֹת מִיָּד חָזִיז מִן הַתֶּלֶם:\",1,0],[2,122,1,15,\"וַתִּפֹּל שְׁבָא. נִתְנַפְּלָה וְחָנְתָה מַלְכוּת שְׁבָא עֲלֵיהֶם, כְּמוֹ (בראשית כ״ה:י״ח) ״עַל פְּנֵי כָל אֶחָיו נָפָל״:\",1,0],[2,122,1,15,\"וְאֶת־הַנְּעָרִים. מְשָׁרְתֶיךָ, הַשּׁוֹמְרִים אוֹתָם:\",2,0],[2,122,1,15,\"וָאִמָּלְטָה. אֵין מְלִיטָה אֶלָּא לְשׁוֹן הַשְׁמָטָה, שֶׁנִּשְׁמַט מִן הַצָּרָה, (וּבָאתִי לְהַגִּיד לָךְ. וְכֵיוָן שֶׁהִגִּיד, מִיָּד מֵת כן הוא בס״א):\",3,0],[2,122,1,16,\"וּבַנְּעָרִים. בַּמְשָׁרְתִים שׁוֹמְרֵי הַצֹּאן מְדַבֵּר הַכָּתוּב:\",1,0],[2,122,1,17,\"וַיִּפְשְׁטוּ עַל הַגְּמַלִּים. זֶה לְשׁוֹן ״בָּזְזוּ בַּז״ (ישעיה לג:כג) – לְפִי מִנְהָגָם. כָּל זְמַן שֶׁהֵם מְהַלְּכִים, נִדְבָּקִים יַחַד וְהוֹלְכִים בְּמַאֲרָב, שֶׁלֹּא יָבִינוּ בָּהֶם וְיַבְרִיחוּ אֶת הַמִּקְנֶה; וּכְשֶׁמַּגִּיעִים לִמְקוֹם הַמִּקְנֶה, פּוֹשְׁטִים בְּמֶרְחַב הַמִּקְנֶה זֶה לְכָאן וְזֶה לְכָאן, לֶאֱסֹף הַמִּקְנֶה. וְהַמַּלְאָכִים הַלָּלוּ – שְׁלוּחֵי שָׂטָן הָיוּ; וּכְדֵי לְהַקְנִיטוֹ וּלְהַחֲטִיאוֹ בִּשְּׂרוּהוּ תְּחִלָּה בְּהֶפְסֵד מוּעָט, וְאַחַר כָּךְ בְּגָדוֹל הֵימֶנּוּ, וְכֵן כֻּלָּם:\",1,0],[2,122,1,19,\"מֵעֵבֶר הַמִּדְבָּר. מִצַּד שֵׁנִי שֶׁל מִדְבָּר, וְהָיָה הַבַּיִת מִצַּד זֶה; וְזֶהוּ לְשׁוֹן ׳עֵבֶר׳ בַּמִּקְרָא:\",1,0],[2,122,1,19,\"עַל הַנְּעָרִים. בָּנִים, אֲבָל אֵין צָרִיךְ לְהַזְכִּיר הַבָּנוֹת:\",2,0],[2,122,1,19,\"(לְהַגִּיד לָךְ. שֶׁהָיָה לוֹ רְשׁוּת לְהַגִּיד, וְהָיָה מֵת בְּאוֹתוֹ רֶגַע ס״א אינו):\",3,0],[2,122,1,20,\"וַיָּגָז. תָּלַשׁ, כְּמוֹ ״גָּזִּי נִזְרֵךְ״ (ירמיה ז:כט), וּמְתַרְגְּמִינָן: ״תְּלִישָׁה״, וּכְמוֹ ״מִמְּעֵי אִמִּי אַתָּה גוֹזִי״ (תהלים עא:ו) – מוֹשְׁכִי:\",1,0],[2,122,1,21,\"מִבֶּטֶן אִמִּי. הָאֲדָמָה אֲשֶׁר לוּקַחְתִּי מִשָּׁם (בראשית ג:כג), אוֹ אִמִּי מַמָּשׁ:\",1,0],[2,122,1,21,\"וְעָרוֹם אָשׁוּב שָׁמָּה. לֹא בַּבֶּטֶן הוּא מְדַבֵּר. וּמַה שָׁמָּה? אֶל מְקוֹם תְּשׁוּבָתוֹ. וְעַל שֶׁהוּא מוּכָן לְכָךְ, וְלֹא יַחֲלִיף הַחֹק לָשׁוּב כִּי אִם אֶל הֶעָפָר, לְפִיכָךְ לֹא הֻצְרַךְ לְהַזְכִּירוֹ:\",2,0],[2,122,1,22,\"תִּפְלָה. לֹא שׁוּם שֶׁמֶץ וְתִפְלוּת נָתַן עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ (ירמיהו כג:יג) ״וּבִנְבִיאֵי שׁוֹמְרוֹן רָאִיתִי תִפְלָה״:\",1,0],[2,122,1,22,\"וְלֹא נָתַן. לְהַטִּיל תִּפְלָה וְעוֹל אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ ״נָתְנוּ לְדָוִד רְבָבוֹת וְלִי נָתְנוּ הָאֲלָפִים״ (שמואל א יח:ח):\",2,0],[2,122,2,2,\"אֵי מִזֶּה תָּבוֹא. אַיֵּה מָקוֹם שֶׁתּוּכַל לוֹמַר: מִזֶּה אֲנִי בָּא?\",1,0],[2,122,2,3,\"מַחֲזִיק. אוֹחֵז, כְּמוֹ ״וַיִּשְׁלַח יָדוֹ וַיַּחֲזֶק בּוֹ״ (שמות ד:ד), ״מַחֲזִיק בְּאָזְנֵי כֶלֶב״ (משלי כו:יז):\",1,0],[2,122,2,3,\"וַתְּסִיתֵנִי בוֹ. הֲסִיתַנִי לְבָלְעוֹ. כָּל לְשׁוֹן הֲסָתָה אֵינוֹ אֶלָּא לְשׁוֹן הַמְשָׁכָה, שֶׁמַּמְשִׁיךְ אֶת הָאָדָם לַעֲצָתוֹ:\",2,0],[2,122,2,4,\"עוֹר בְּעַד עוֹר. אֵבֶר בִּפְנֵי אֵבֶר. כֵּן דֶּרֶךְ בְּנֵי אָדָם: כְּשֶׁרוֹאֶה הַחֶרֶב בָּאָה עַל רֹאשׁוֹ, מֵגִין בִּזְרוֹעוֹ לְפָנָיו. וְכָל שֶׁכֵּן – כֹּל אֲשֶׁר לָאִישׁ בְּמָמוֹן יִתֵּן:\",1,0],[2,122,2,4,\"בְּעַד נַפְשׁוֹ. בִּפְנֵי נַפְשׁוֹ, לְהָגִין. לְפִי שֶׁזֶּה יוֹדֵעַ בְּנַפְשׁוֹ שֶׁנִּתְחַיֵּב, לְפִיכָךְ אֵינוֹ מִצְטַעֵר עַל מָמוֹנוֹ:\",2,0],[2,122,2,5,\"אוּלָם. אֲבָל:\",1,0],[2,122,2,5,\"אִם לֹא. תִּרְאֶה בּוֹ מִיָּד, שֶׁעַל פָּנֶיךָ יְבָרֲכֶךָּ:\",2,0],[2,122,2,6,\"אַךְ אֶת נַפְשׁוֹ שְׁמֹר. שֶׁלֹּא תֵצֵא. מִכָּאן אָמְרוּ חֲכָמִים (בבא בתרא טז.): קָשֶׁה הָיָה צַעֲרוֹ שֶׁל שָׂטָן יוֹתֵר מִשֶּׁל אִיּוֹב; כְּאוֹמֵר לַחֲבֵירוֹ: שְׁבֹר חָבִית זוֹ וּשְׁמֹר יֵינָהּ:\",1,0],[2,122,2,8,\"לְהִתְגָּרֵד בּוֹ. בְּדָלֶ״ת כָּתוּב, וּלְשׁוֹן מִשְׁנָה הִיא: גּוֹרְדוֹ וּמַעֲמִידוֹ עַל גִּלְדּוֹ (ראש השנה כז:). אֲבָל גּוֹרֵר בְּרֵי״שׁ אֵינוֹ אֶלָּא לְשׁוֹן סְחִיבָה, כְּמוֹ גּוֹרֵר אָדָם מִטָּה וְסַפְסָל (שבת כב.):\",1,0],[2,122,2,9,\"מַחֲזִיק. אוֹחֵז:\",1,0],[2,122,2,9,\"וָמֻת: לְשׁוֹן צִוּוּי, כְּמוֹ ״וּמֻת בָּהָר״ (דברים לב:נ):\",2,0],[2,122,2,10,\"גַּם. לֹא דַי שֶׁבְּרָאָנוּ, אֶלָּא גַּם אֶת הַטּוֹב נְקַבֵּל וְאֶת הָרָע לֹא נְקַבֵּל?! בִּתְמִיהַּ:\",1,0],[2,122,2,10,\"בִּשְׂפָתָיו. אֲבָל בְּלִבּוֹ חָטָא:\",2,0],[2,122,2,11,\"רֵעֵי אִיּוֹב. אוֹהֲבָיו:\",1,0],[2,122,2,11,\"לָנוּד. כְּמוֹ ״מִי יָנוּד לָךְ״ (ישעיהו נא:יט), ״לֹא תָנֻדוּ לוֹ״ (ירמיהו כב:י):\",2,0],[2,122,2,12,\"וְלֹא הִכִּירוּהוּ. כִּי נִשְׁתַּנּוּ פָנָיו מֵחֲמַת הַיִּסּוּרִין:\",1,0],[2,122,2,12,\"הַשָּׁמָיְמָה. כְּלוֹמַר: לְמַעְלָה מֵרָאשֵׁיהֶם (הַרְבֵּה), וְהוּא הָיָה לָהֶם מִנְהַג אֵבֶל:\",2,0],[2,122,2,13,\"לָאָרֶץ. עַל הָאָרֶץ, לְצַעֵר בְּצַעֲרוֹ:\",1,0],[2,122,3,2,\"(מענה איוב) וַיַּעַן. וַיִּצְעַק, שֶׁכָּל עֲנִיָּה הָאֲמוּרָה בַּתּוֹרָה אֵינָהּ אֶלָּא לְשׁוֹן הֲרָמַת קוֹל, וְאָב לְכֻלָּם: ״וְעָנוּ הַלְוִיִּם קוֹל רָם״ (דברים כז:יד):\",1,0],[2,122,3,3,\"אִוָּלֶד בּוֹ. לְשׁוֹן עָתִיד, שֶׁהָיָה אוֹמֵר: הַלְוַאי וְיֹאבַד הַיּוֹם שֶׁהָיִיתִי עָתִיד לְהִוָּלֵד בּוֹ, וְאָז לֹא הָיִיתִי נוֹלָד:\",1,0],[2,122,3,3,\"וְהַלַּיְלָה. אַף הִיא תֹּאבַד:\",2,0],[2,122,3,3,\"אָמַר. שֶׁיֹּאמַר הַמְבַשֵּׂר אֲשֶׁר עָלָיו הַדָּבָר מֻטָּל:\",3,0],[2,122,3,3,\"הוֹרָה גָבֶר. שֶׁעִיבֵּר אָבִי אֶת אִמִּי. בִּנְקֵבָה נוֹהֵג לוֹמַר ׳הוֹרָתָה׳, וּבְזָכָר נוֹהֵג לוֹמַר ׳הוֹרָה אֶת הַנְּקֵבָה׳:\",4,0],[2,122,3,3,\"וְהַלַּיְלָה אָמַר. זֶה אֶחָד מִן הַמְּקוֹמוֹת שֶׁחִסֵּר הַמִּקְרָא אֶת דְּבָרָיו, מִפְּנֵי שֶׁלֹּא הֻצְרַךְ לְפָרֵשׁ מִי הוּא; וּמְלִיצָתוֹ: אָמַר הָאוֹמֵר. (וְדוֹמֶה לוֹ ״הֲיָרֻצוּן בַּסֶּלַע סוּסִים אִם יַחֲרוֹשׁ בַּבְּקָרִים״ (עמוס ו:יב)) – הָיָה לוֹ לוֹמַר: אִם יַחֲרוֹשׁ אָדָם בַּבְּקָרִים. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה אָמְרוּ (נדה טז:): מַלְאָךְ הַמְמֻנֶּה עַל הַהֵרָיוֹן, ׳לַיְלָה׳ שְׁמוֹ:\",5,0],[2,122,3,4,\"הַיּוֹם הַהוּא יְהִי חֹשֶׁךְ. תָּמִיד בְּכָל שָׁנָה, כְּשֶׁיַּגִּיעַ אוֹתוֹ יוֹם:\",1,0],[2,122,3,4,\"אַל יִדְרְשֵׁהוּ אֱלוֹהַּ מִמָּעַל. לְטוֹבָה:\",2,0],[2,122,3,4,\"וְאַל תּוֹפַע עָלָיו נְהָרָה. אוֹרָה, כְּמוֹ ״צֹהַר״ (בראשית ו:טז), וּמְתַרְגְּמִינָן ״נִיהוֹר״ (תרגום אונקלוס):\",3,0],[2,122,3,5,\"יִגְאָלֻהוּ. כְּמוֹ ״לֶחֶם מְגֹאָל״ (מלאכי א:ז), ״בַּמֶּה גֵאַלְנוּךָ״ (מלאכי א:ז), וְהוּא לְשׁוֹן לִכְלוּךְ:\",1,0],[2,122,3,5,\"צַלְמָוֶת. צֵל שֶׁל מָוֶת (חֹשֶׁךְ), שֶׁאֵינוֹ מֵאִיר לְעוֹלָם:\",2,0],[2,122,3,5,\"עֲנָנָה. אֲפֵלָה:\",3,0],[2,122,3,5,\"כְּמְרִירֵי יוֹם. שֵׁדִים הַמּוֹשְׁלִים בַּצָּהֳרַיִם, כְּמוֹ ״קֶטֶב מְרִירִי״ (דברים לב:כד), וְהוּא מוֹשֵׁל בַּצָּהֳרַיִם, שֶׁנֶּאֱמַר ״וּמִקֶּטֶב יָשׁוּד צָהֳרָיִם״ (תהלים צא:ו):\",4,0],[2,122,3,6,\"אַל יִחַדְּ. אַל יִשְׂמַח, כְּמוֹ ״וַיִּחַדְּ יִתְרוֹ״ (שמות יח:ט). פֵּרוּשׁ אַחֵר: אַל יִתְאַחֵד (סא״א):\",1,0],[2,122,3,7,\"גַּלְמוּד. יָחִיד, וְחָסֵר מֵאָדָם וּמִכָּל בְּרִיָּה:\",1,0],[2,122,3,8,\"יִקְּבֻהוּ. יְקַלְלוּהוּ, כְּמוֹ ״קָבָה לִי״ (במדבר כב:יז):\",1,0],[2,122,3,8,\"אוֹרְרֵי יוֹם. הַמְקַלְּלִים אֶת יְמֵיהֶם, לְפִי שֶׁהֵם מְכַוְּנִים לְקַלֵּל קְלָלָה מִתּוֹךְ צַעֲרָם:\",2,0],[2,122,3,8,\"הָעֲתִידִים עוֹרֵר לִוְיָתָן. לִהְיוֹת עֲרִירִים בְּמַחְבַּרְתָּם, לְיַחֵד לִוּוּי שֶׁלָּהֶם מֵחֶבְרַת אִישׁ וְאִשְׁתּוֹ, מֵאֵין בָּנִים. וּבַגְּמָרָא יְרוּשַׁלְמִי רָאִיתִי (מועד קטן א,ה): עוֹרֵר לִוְיָתָן. לְקוֹנֵן עַל לִוּוּי שֶׁלָּהֶם כְּשֶׁיָּמוּת, כְּמוֹ (מועד קטן ח.): לֹא יְעַרְעֵר עַל מֵתוֹ:\",3,0],[2,122,3,9,\"נִשְׁפּוֹ. חֹשֶׁךְ אִישׁוֹנוֹ:\",1,0],[2,122,3,9,\"בְּעַפְעַפֵּי. בְּזָהֳרוּרֵי, כְּמוֹ ״וְעַפְעַפֵּינוּ יִזְּלוּ מָיִם״ (ירמיהו ט:יז):\",2,0],[2,122,3,10,\"כִּי לֹא סָגַר. מִי שֶׁיְּכֹלֶת בְּיָדוֹ לִסְגּוֹר. וְגַם זֶה מִן הַמִּקְרָאוֹת דּוֹמִין לְ״הַלַּיְלָה אָמַר״ (לעיל ג:ג):\",1,0],[2,122,3,10,\"דַּלְתֵי בִטְנִי. שֶׁיָּצָאתִי מִמֶּנּוּ, שֶׁאִם עָשָׂה כֵּן, וַיַּסְתֵּר עָמָל מֵעֵינָי:\",2,0],[2,122,3,11,\"לָמָּה לֹא מֵרֶחֶם אָמוּת. מִיצִיאָתִי מֵרֶחֶם (הָיִיתִי) מוּכָן לָמוּת מִיָּד. וּמְדַבֵּר בִּלְשׁוֹן עָתִיד, כְּאִלּוּ עוֹמֵד עַכְשָׁיו בְּיוֹם יְצִיאַת הָרֶחֶם, וְאוֹמֵר: (לָמָּה) לֹא אָמוּת עַתָּה, וְלָמָּה לֹא מִבֶּטֶן יָצָאתִי וְאֶגְוָע. לָמָּה לֹא הָיְתָה לִי גְּוִיעָה מוּכֶנֶת:\",1,0],[2,122,3,12,\"מַדּוּעַ קִדְּמוּנִי. בִּרְכֵּי אִמִּי קוֹדֶם לְמִיתָה:\",1,0],[2,122,3,12,\"כִּי אִינָק. נִגְזַר עָלַי לִינֹק מֵהֶם. לְפִי שֶׁהוּא מְדַבֵּר בְּיוֹם לֵידָה, הוּא מַזְכִּיר דְּבָרִים שֶׁל אַחֲרָיו בִּלְשׁוֹן עָתִיד:\",2,0],[2,122,3,13,\"שָׁכַבְתִּי. הָיִיתִי שׁוֹכֵב בַּקֶּבֶר:\",1,0],[2,122,3,14,\"הַבּוֹנִים חֳרָבוֹת לָמוֹ. זֶהוּ דֶּרֶךְ לְמַעֲמִידֵי שֵׁם, לִבְנוֹת עָרִים נֶחֱרָבוֹת לְזִכָּרוֹן לָהֶם; כְּמוֹ ״וּבָנוּ מִמְּךָ חָרְבוֹת עוֹלָם וְקֹרֵא לְךָ גֹּדֵר פֶּרֶץ״ (ישעיה נח:יב). כְּלוֹמַר: עִם שָׂרִים וּבַעֲלֵי שֵׁם. אוֹ הַלְוַאי שֶׁלֹּא נוֹדַעְתִּי וְאֶהְיֶה כְּנֵפֶל. וּמַה שֶּׁכָּתַב לֹא אֶהְיֶה כְנֵפֶל טָמוּן – מִפְּנֵי שֶׁעוֹמֵד עַל לָשׁוֹן שֶׁהִתְחִיל לְדַבֵּר, בִּלְשׁוֹן תֵּימַהּ; וּמוּסָב עַל לָמָּה לֹּא, מַדּוּעַ קִדְּמוּנִי בִרְכָּיִם, אוֹ מַדּוּעַ לֹא אֶהְיֶה כְנֵפֶל טָמוּן:\",1,0],[2,122,3,16,\"כְּעוֹלְלִים. תִּינוֹקוֹת. וּלְכָךְ קוֹרֵא אוֹתָם עוֹלְלִים, שֶׁכֻּלָּם שְׂחוֹק וְלִכְלוּךְ; כְּמוֹ ״וְעֹלַלְתִּי בֶעָפָר״ (איוב טז:טו), וּכְמוֹ ״וַיִּתְעַלְּלוּ בָהּ כָּל הַלָּיְלָה״ (שופטים יט:כה):\",1,0],[2,122,3,17,\"חָדְלוּ רֹגֶז. נִמְנָעִים מֵרוּגְזָם, שֶׁהָיוּ נוֹהֲגִים וּרְגִילִים לְהַרְגִּיז בָּאָרֶץ:\",1,0],[2,122,3,17,\"וְשָׁם יָנוּחוּ. וְשָׁם נָחוּ, דָּבָר הַהוֹוֶה כְּתָבוֹ בִּלְשׁוֹן עָתִיד:\",2,0],[2,122,3,19,\"קָטֹן וְגָדוֹל שָׁם. שָׁם נִכָּר מִי חָשׁוּב וּמִי שָׁפָל, וּלְפִי שֶׁאוֹתָהּ גְּדֻלָּה גְּדֻלַּת עוֹלָם הוּא, וְאוֹתוֹ שִׁפְלוּת שִׁפְלוּת עוֹלָם הִיא:\",1,0],[2,122,3,20,\"לָמָּה יִתֵּן. הַנּוֹתֵן, וְהוּא הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,122,3,20,\"לְעָמֵל אוֹר. לְמִי שֶׁגָּדַל בְּעָמָל וְצָרָה, לָמָּה נוֹתֵן לוֹ אוֹר עוֹלָם, וְלֹא הֱמִיתוֹ בְּהִוָּלְדוֹ?\",2,0],[2,122,3,21,\"הַמְחַכִּים לַמָּוֶת. לְמָרֵי נֶפֶשׁ הַתְּאֵבִים וּמִתְאַוִּים לַמָּוֶת, וְקוֹבְלִים לֵאמֹר: אֵינֶנּוּ:\",1,0],[2,122,3,21,\"וַיַּחְפְּרֻהוּ. מְרַגְּלִים אַחֲרָיו:\",2,0],[2,122,3,21,\"מִמַּטְמוֹנִים. יוֹתֵר מִשֶּׁמְּרַגְּלִים אַחַר מַטְמוֹנֵי אוֹצָרוֹת. וְהָיוּ:\",3,0],[2,122,3,22,\"שְׂמֵחִים אֱלֵי גִיל. וְיָשִׂישׂוּ אִם הָיוּ מוֹצְאִים קָבֶר:\",1,0],[2,122,3,22,\"אֱלֵי גִיל. בִּשְׁבִיל הַגִּילָה וְהַשָּׂשׂוֹן שֶׁל מְצִיאַת קָבֶר:\",2,0],[2,122,3,23,\"לְגֶבֶר אֲשֶׁר דַּרְכּוֹ נִסְתָּרָה. כָּל טוֹבוֹת אֲשֶׁר פָּעַל, נִסְתְּרוּ מֵאֵת בַּעַל הַגְּמוּל, וְלֹא הִבִּיט בָּהֶם:\",1,0],[2,122,3,23,\"וַיָּסֶךְ אֱלוֹהַּ בַּעֲדוֹ. עָשָׂה מְחִיצָּה לְפָנָיו, לְסוֹגְרוֹ בְּמַסְגֵּר. כְּמוֹ ״הִנְנִי שָׂךְ אֶת דַּרְכֵּךְ״ (הושע ב:ח):\",2,0],[2,122,3,24,\"תָּבֹא. בָּאָה:\",1,0],[2,122,3,24,\"וַיִּתְּכוּ. לְשׁוֹן ״נִתַּךְ אַרְצָה״ (שמות ט:לג), נִגָּרִים וְיוֹרְדִים כַּמַּיִם. וְיֵשׁ לְפָרֵשׁ ׳נְתִיכָה׳ לְשׁוֹן ׳רִבְּיָה׳:\",2,0],[2,122,3,25,\"פַּחַד פָּחַדְתִּי. כָּל יָמַי עָמַדְתִּי בְּפַחַד עַל זֶה, כְּמוֹ שֶׁאָמַרְנוּ ״וַיְהִי כִּי הִקִּיפוּ וְגוֹ׳״ (איוב א:ה):\",1,0],[2,122,3,25,\"וַאֲשֶׁר יָגֹרְתִּי. הֵן עַתָּה הוּעְתַּד וְנִגְזַר שֶׁיָּבֹא לִי:\",2,0],[2,122,3,26,\"לֹא שָׁלַוְתִּי. מִדְּאָגָה זוֹ, וְהִנֵּה וַיָּבֹא רֹגֶז:\",1,0],[2,122,4,1,\"(מענה אליפז) אֱלִיפַז בֶּן עֵשָׂו הָיָה (בראשית לו:ד), וְעַל יְדֵי שֶׁנִּתְגַּדֵּל בְּחֵיקוֹ שֶׁל יִצְחָק, זָכָה שֶׁתִּשְׁרֶה עָלָיו שְׁכִינָה:\",1,0],[2,122,4,1,\"הַתֵּימָנִי. מֵאֶרֶץ תֵּימָן, מֵאַרְצוֹ שֶׁל עֵשָׂו (בראשית לו:לד) (סא״א):\",2,0],[2,122,4,2,\"הֲנִסָּה. לְשׁוֹן תֵּימַהּ: הֲבַּעֲבוּר שֶׁנִּסָּה דָבָר אֵלֶיךָ תִּלְאֶה? בְּנִסָּיוֹן אֶחָד שֶׁנִּסְּךָ בּוֹרַאֲךָ וּבָא אֵלֶיךָ, אַתָּה נִלְאֶה?! וּמֵעַתָּה, עֲצֹר בְּמִלִּין מִי יוּכַל. מִלְּהַשִׁיבְךָ?\",1,0],[2,122,4,3,\"הִנֵּה יִסַּרְתָּ רַבִּים. שֶׁהִרְבּוּ דְבָרִים, הוֹכַחְתָּם וְיִסַּרְתָּם:\",1,0],[2,122,4,3,\"וְיָדַיִם רָפוֹת. וִיגוּרוֹת מִפּוּרְעָנוּת הַבָּא עֲלֵיהֶם, אַתָּה הָיִיתָ רָגִיל לְחַזְּקָם, וְלוֹמַר: אַל תִּירָא, שֶׁכָּךְ הוּא מִדַּת הַדִּין:\",2,0],[2,122,4,4,\"יְקִימוּן. רְגִילוֹת הֵם מִלֶּיךָ לְהָקִים אֶת הַכּוֹשֵׁל:\",1,0],[2,122,4,6,\"הֲלֹא. עַתָּה סוֹפְךָ מוֹכִיחַ עַל תְּחִלָּתְךָ, שֶׁיִּרְאָתְךָ, שֶׁהָיִיתָ יְרֵא שָׁמַיִם:\",1,0],[2,122,4,6,\"כִּסְלָתֶךָ. הִיא (בבא מציעא נח.) מֵחֲמַת כְּסִילוּת הִיא, וְלֹא מִדַּעַת שְׁלֵימָה. וְכֵן תִּקְוָתְךָ וְתֹם דְּרָכֶיךָ הַכֹּל כְּסִילוּת:\",2,0],[2,122,4,7,\"נִכְחָדוּ. נֶעֶלְמוּ וְנֶאֶבְדוּ, כְּמוֹ ״וַתִּכָּחֵד מִן הָאָרֶץ״ (שמות ט:טו):\",1,0],[2,122,4,8,\"כַּאֲשֶׁר רָאִיתִי. אֲשֶׁר (כֵּן) נִכְחֲדוּ חוֹרְשֵׁי אָוֶן וּמְכִינִים אֶת הָאָוֶן בְּמַחֲשַׁבְתָּם, כְּחוֹרֵשׁ זֶה שֶׁמֵּכִין לִפְנֵי הַזְּרִיעָה, וְאַחֲרֵי כֵן זוֹרְעִים בְּמַעֲשֵׂיהֶם אֶת הֶעָמָל; וְרָאִיתִי, שֶׁהֵם יִקְצְרֻהוּ. כְּלוֹמַר: רָעָתָם שֶׁבָּאָה עֲלֵיהֶם. וְרָאִיתִי, כִּי:\",1,0],[2,122,4,9,\"מִנִּשְׁמַת אֱלוֹהַּ יֹאבֵדוּ. מִנְּשִׁיבַת סַעֲרָתוֹ וְכַעֲסוֹ:\",1,0],[2,122,4,9,\"וּמֵרוּחַ אַפּוֹ יִכְלוּ. כָּלִים תָּמִיד, וְעַל דּוֹר הַמַּבּוּל דִּבֵּר (בראשית ו:יג):\",2,0],[2,122,4,10,\"שַׁאֲגַת אַרְיֵה וְקוֹל שָׁחַל וְגוֹ׳. הָאֲרִי גָּדוֹל, וְהַשַּׁחַל בֵּינוֹנִי, וְהַכְּפִיר קָטָן; כֻּלָּם נִתָּעוּ. כְּלוֹמַר: הַמְּלָכִים וְהַשָּׂרִים וְהָעֲבָדִים. וְכָל שֵׁמוֹת הַלָּלוּ שְׁמוֹת אַרְיֵה הֵם:\",1,0],[2,122,4,11,\"לַיִשׁ אוֹבֵד מִבְּלִי טָרֶף. הַשָּׂרִים אָבְדוּ כְּלַיִשׁ זֶה הָאוֹבֵד מִבְּלִי מָזוֹן, כָּךְ אָבַד כֹּחָם מֵעֲשׂוֹת חָמָס. אוֹבֵד אֵינוֹ לְשׁוֹן אָדָם הָאוֹבֵד דָּבָר מִמֶּנּוּ, אֶלָּא הוּא עַצְמוֹ הוֹלֵךְ לְאִבּוּד, כְּמוֹ ״תָּעִיתִי כְּשֶׂה אֹבֵד״ (תהילים קיט:קעו), וּכְמוֹ ״הָיִיתִי כִּכְלִי אֹבֵד״ (תהילים לא:יג):\",1,0],[2,122,4,11,\"וּבְנֵי לָבִיא יִתְפָּרָדוּ. מְדַבֵּר בְּדוֹר הַפְּלַגָּה, אֲשֶׁר נָפוֹצוּ מִשָּׁם עַל פְּנֵי כָל הָאָרֶץ (בראשית יא:ט):\",2,0],[2,122,4,12,\"וְאֵלַי דָּבָר יְגֻנָּב. חוֹזֵר עַל תּוֹכַחְתּוֹ שֶׁהוֹכִיחוֹ עַד הֵנָּה: מַה תִּזְעַק? זְכָר נָא מִי הוּא נָקִי אָבַד וְגוֹ׳כַּאֲשֶׁר רָאִיתִי וְגוֹ׳, וְעַל אוֹדוֹתֶיךָ אֵלַי דָּבָר נְבוּאָה יְגֻנָּב. מִן הַסִּגְנוֹן, כְּדָבָר גָּנוּב; לְפִי שֶׁאֵין רוּחַ הַקֹּדֶשׁ נִגְלֶה עַל נְבִיאֵי עוֹבְדֵי כּוֹכָבִים בְּפַרְהֶסְיָא. מָשָׁל לְמֶלֶךְ, שֶׁהָיְתָה לוֹ אִשָּׁה וּפִילֶגֶשׁ; כְּשֶׁבָּא אֵצֶל אִשְׁתּוֹ בָּא בְּגָלוּי, וְאֵצֶל פִּילַגְשׁוֹ בָּא בְּסֵתֶר וּבִגְנֵבָה. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לִנְבִיאֵי עוֹבְדֵי כּוֹכָבִים: ״וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ בַּחֲלוֹם הַלָּיְלָה״ (בראשית כ:ג); וְכֵן ״וַיָּבֹא אֱלֹהִים אֶל לָבָן וְגוֹ׳״ (בראשית לא:כד); לְבִלְעָם: ״נֹפֵל וּגְלוּי עֵינָיִם״ (במדבר כד:ד); לֶאֱלִיפַז: בַּחֶזְיוֹנוֹת הַלַּיְלָה. אֲבָל בִּנְבִיאֵי יִשְׂרָאֵל כְּתִיב ״פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ בְּמַרְאֶה וְלֹא בְחִידוֹת״ (במדבר יב:ח). בְּמִדְרַשׁ תַּנְחוּמָא מָצָאתִי מֻגֶּה וְל״שׁ:\",1,0],[2,122,4,12,\"וַתִּקַּח אָזְנִי שֵׁמֶץ מֶנְהוּ. שֶׁמֶץ מִקְצָת רוּחַ הֲבָנָה:\",2,0],[2,122,4,13,\"בִּשְׂעִפִּים. בְּמַחֲשָׁבוֹת:\",1,0],[2,122,4,14,\"פַּחַד קְרָאַנִי. מִן הָרוּחַ שֶׁבָּא אֵלַי. וְרוּחַ הוּא מַלְאָךְ, שֶׁנֶּאֱמַר (תהילים קד:ד) ״עֹשֶׂה מַלְאָכָיו רוּחוֹת״:\",1,0],[2,122,4,15,\"תְּסַמֵּר. הָרוּחַ שַׂעֲרַת בְּשָׂרִי:\",1,0],[2,122,4,15,\"תְּסַמֵּר. הוּא לְשׁוֹן אָדָם שֶׁעָמְדוּ שַׂעֲרוֹתָיו:\",2,0],[2,122,4,16,\"יַעֲמֹד. עוֹמֵד הָיָה בְּפָנַי, וְלֹא הָיִיתִי מַכִּיר מַרְאֵהוּ:\",1,0],[2,122,4,16,\"דְּמָמָה וָקוֹל. קוֹל דָּבָר חֲשַׁאי הָיִיתִי שׁוֹמֵעַ. דָּבָר אַחֵר: דְּמָמָה וָקוֹל אֶשְׁמַע – קוֹל שָׁמַעְתִּי מִדְּמָמָה, אֲבָל דְּמָמָה לֹא שָׁמַעְתִּי. דְּמָמָה – אֵלּוּ הַמַּלְאָכִים שֶׁאוֹמְרִים שִׁירָה, כְּדִמְתַרְגֵּם ״וְאַחַר הָרַעַשׁ קוֹל דְּמָמָה דַקָּה״ (מלכים א יט:יב): ״קָל דִּמְשַׁבְּחִין בַּחֲשַׁאי״. מֹשֶׁה – דְּמָמָה שָׁמַע; מִכָּאן, שֶׁהָרִאשׁוֹנִים נִשְׁתַּמְּשׁוּ בְּקוֹל, וְהָאַחֲרוֹנִים – בְּבַת קוֹל. כְּאָדָם הַמַּכֶּה בְּפַטִּישׁ, וְקוֹל הַהֲבָרָה נִשְׁמַע לְמֵרָחוֹק; כָּךְ הוּא אוֹמֵר:\",2,0],[2,122,4,17,\"הַאֱנוֹשׁ מֵאֱלוֹהַ יִצְדָּק. בִּתְמִיהַּ:\",1,0],[2,122,4,17,\"וְאִם מֵעֹשֵׂהוּ יִטְהַר גָּבֶר. וְאִם יוֹתֵר מֵעוֹשֵׂהוּ יִטְהַר גָּבֶר? וּמָה זֶּה חֲבֵירְךָ יִצְעַק?!\",2,0],[2,122,4,18,\"הֵן בַּעֲבָדָיו. הַצַּדִּיקִים לֹא יַאֲמִין שֶׁלֹּא יֶחֶטְאוּ לוֹ, וּמְסַלְּקָם מִן הָעוֹלָם לִפְנֵי זְמַנָּם:\",1,0],[2,122,4,18,\"תָּהֳלָה. לְשׁוֹן ״הוֹלְלוּת״ (קהלת י:יג):\",2,0],[2,122,4,19,\"אַף. כָּל שֶׁכֵּן:\",1,0],[2,122,4,19,\"שׁוֹכְנֵי בָתֵּי חֹמֶר אֲשֶׁר בֶּעָפָר יְסוֹדָם. קִבְרָם:\",2,0],[2,122,4,19,\"יְדַכְּאוּם לִפְנֵי עָשׁ. מִן הַשָּׁמַיִם מְתִישִׁין אֶת כֹּחָם, עַד שֶׁהֵן שְׁפָלִים וְנִדְכָּאִים לִפְנֵי הָרִמָּה הָאוֹכַלְתָּן בְּמוֹתָן:\",3,0],[2,122,4,20,\"מִבֹּקֶר לָעֶרֶב יֻכַּתּוּ. בְּיוֹם אֶחָד הֵם כְּתוּתִים וְנִדְכָּאִים:\",1,0],[2,122,4,20,\"מִבְּלִי מֵשִׂים. עַל לֵב לָשׁוּב לְקוֹנָם:\",2,0],[2,122,4,20,\"לָנֶצַח יֹאבֵֽדוּ. וְגַם זֶה הוּא מִקְרָא חָסֵר:\",3,0],[2,122,4,21,\"הֲלֹא נִסַּע יִתְרָם בָּם. כְּמוֹ ״יִתְרָה עָשָׂה וְגוֹ׳״ (ישעיהו טו:ז): גַּאֲוָתָם וְחָכְמָתָם תִּתְבַּלַּע בְּגוּפָן (תהלים קז:כז), וְהִנֵּה נוֹסַעַת וְנִסַּחַת, כְּמוֹ ״בַּל יִסַּע יְתֵדוֹתָיו״ (ישעיהו לג:כ):\",1,0],[2,122,5,1,\"קְרָא נָא. עַד כָּאן דִּבֵּר הַנְּבוּאָה, מִכָּאן וָאֵילָךְ חוֹזֵר לְתוֹכַחְתּוֹ: צְעַק הַרְבֵּה, מִי יַעַנְךָ?\",1,0],[2,122,5,1,\"וְאֶל מִי מִקְּדֹשִׁים. הַגּוֹזְרִים זֹאת עָלֶיךָ תִּפְנֶה. לְהִלָּחֵם אִתּוֹ:\",2,0],[2,122,5,2,\"כִּי לֶאֱוִיל וְגוֹ׳. לֶאֱוִיל כְּמוֹתְךָ יַהֲרֹג כַּעֲסוֹ, שֶׁאִלּוּ הָיִיתָ שׁוֹתֵק, שֶׁמָּא תָּשׁוּב מִדַּת הָרַחֲמִים עָלֶיךָ:\",1,0],[2,122,5,2,\"קִנְאָה. הִיא כַּעַס וְחֵמָה, כְּמוֹ ״הֵם קִנְאוּנִי״ (דברים לב:כא):\",2,0],[2,122,5,4,\"יִרְחֲקוּ בָנָיו. זוֹ הִיא קְלָלָה שֶׁקִּלַּלְתִּיו:\",1,0],[2,122,5,4,\"וְיִדַּכְּאוּ. בְּדָגֵשׁ הוּא יְדֻכְּאוּ, וְאִם הוּא נָקוּד רָפֵי מְשַׁמֵּשׁ יְדַכְּאוּ אֲחֵרִים:\",2,0],[2,122,5,5,\"אֲשֶׁר קְצִירוֹ. שֶׁל רָשָׁע:\",1,0],[2,122,5,5,\"רָעֵב יֹאכֵל. כִּי יָמוּת רָשָׁע, יָבוֹאוּ הָרְעֵבִים שֶׁקִּצֵּץ בְּחַיָּיו, וְיִשְׁתַּלְּמוּ גְזֵלוֹתָיו מִנְּכָסָיו:\",2,0],[2,122,5,5,\"וְאֶל מִצִּנִּים יִקָּחֵהוּ. כְּמוֹ ״וְיִקְחוּ אֵלֶיךָ״ (שמות כז:כ), כְּלוֹמַר: לְצֹרֶךְ הֶעָנִי הַנּוֹשָׁע מִצִּנִּים וּכְלֵי זַיִן שֶׁל רָשָׁע זֶה, יִקָּחֵהוּ הַשּׁוֹפֵט הַמְּמֻנֶּה לְכָךְ:\",3,0],[2,122,5,5,\"וְשָׁאַף. וּבָלַע אִישׁ אִישׁ מִן הַצַּמִּים שֶׁגָּזַל בְּחַיָּיו:\",4,0],[2,122,5,5,\"חֵילָם. מָמוֹנָם, שֶׁגָּזַל זֶה בְּחַיָּיו:\",5,0],[2,122,5,6,\"כִּי לֹא יֵצֵא מֵעָפָר. מַכָּה הַבָּאָה עַל הָאָדָם, לֹא לְחִנָּם הוּא, וְלֹא מִן הֶעָפָר תִּצְמַח לוֹ:\",1,0],[2,122,5,6,\"אָוֶן. הוּא לְשׁוֹן שֶׁבֶר:\",2,0],[2,122,5,7,\"כִּי אָדָם לְעָמָל יוּלָּד. כִּי אִי אֶפְשָׁר שֶׁלֹּא יֶחֱטָא וִיקַבֵּל עָמָל בְּחֶטְאוֹ, לְקַבֵּל פּוּרְעָנוּתוֹ. וְאֵינוֹ כִּבְנֵי רֶשֶׁף, שֶׁהֵם מַלְאָכִים וְרוּחוֹת, שֶׁהֵם יַגְבִּיהוּ עוּף, וְאֵינָם מִן הַתַּחְתּוֹנִים (יַגְבִּיהוּ לָעוּף וְלִהְיוֹת מִן הַתַּחְתּוֹנִים (סא״א)), לִשְׁלוֹט בָּם שָׂטָן וְיֵצֶר הָרָע:\",1,0],[2,122,5,7,\"רֶשֶׁף. כְּמוֹ ״רִשְׁפֵּי קֶשֶׁת״ (תהילים עו:ד), כְּשֶׁהַחֵץ מְעוֹפֶפֶת נִקְרָא רִשְׁפֵּי, לְשׁוֹן עוּף (סא״א):\",2,0],[2,122,5,8,\"אוּלָם אֲנִי אֶדְרֹשׁ. אִם הָיוּ בָּאִים עָלַי יִסּוּרִים הַלָּלוּ, הָיִיתִי דּוֹרֵשׁ אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְפִלָּה וּבִתְחִנָּה; וְאִלּוּ הָיִיתִי שָׂם, דִּבְרָתִי בְּבַקָּשָׁה:\",1,0],[2,122,5,10,\"הַנּוֹתֵן מָטָר עַל פְּנֵי אָרֶץ. אֶרֶץ יִשְׂרָאֵל:\",1,0],[2,122,5,10,\"וְשׁוֹלֵחַ מַיִם עַל פְּנֵי חוּצוֹת. עַל יְדֵי שָׁלִיחַ, לִשְׁאָר אֲרָצוֹת:\",2,0],[2,122,5,11,\"לָשׂוּם שְׁפָלִים לְמָרוֹם. הוּא נוֹתֵן אֶת הַמָּטָר, וְהוּא מֵפֵר מַחֲשְׁבוֹת עֲרוּמִים, שֶׁמְּדַמִּין לְהַפְקִיעַ שְׁעָרִים וְלִקְנוֹת שְׂדוֹת הָעֲנִיִּים בִּמְעַט תְּבוּאָה:\",1,0],[2,122,5,11,\"קוֹדְרִים. שֶׁקּוֹמְטִים פָּנִים בָּרָעָב:\",2,0],[2,122,5,12,\"וְלֹא תַעֲשֶׂנָה יְדֵיהֶם תּוּשִׁיָּה. אוֹתָהּ עֵצָה שֶׁדִּמּוּ לַעֲשׂוֹת:\",1,0],[2,122,5,13,\"נִמְהָרָה. כָּל הָעֵצָה הָעֲשׂוּיָה בִּמְהִירוּת הִיא סִכְלוּת:\",1,0],[2,122,5,14,\"יוֹמָם יְפַגְּשׁוּ חֹשֶׁךְ. שֶׁאֵין עֲצָתָם מִתְקַיֶּמֶת וְנַעֲשֵׂית, וְאוֹר חָכְמָתָם נֶהְפַּךְ לְחֹשֶׁךְ:\",1,0],[2,122,5,15,\"וַיּוֹשַׁע. אֶת הַנִּכְשָׁלִים:\",1,0],[2,122,5,15,\"מֵחֶרֶב. וּמֵאֵיזֶה חֶרֶב? מִפִּיהֶם; שֶׁהָיוּ סְבוּרִים לְבוֹלְעָם, וּמִתְאַוִּים לְהַשְׁמִידָם:\",2,0],[2,122,5,15,\"וּמִיַּד חָזָק. יוֹשִׁיעַ אֶבְיוֹן:\",3,0],[2,122,5,16,\"וְעוֹלָתָהּ. הָעֲלִילָה וְהָרִשְׁעָה, כְּמוֹ (תהילים סד:ז) ״יַחְפְּשׂוּ עוֹלוֹת״ – עֲלִילוֹת:\",1,0],[2,122,5,16,\"קָפְצָה. סָגְרָה, כְּמוֹ ״לֹא תִקְפֹּץ״ (דברים טו:ז):\",2,0],[2,122,5,17,\"הִנֵּה אַשְׁרֵי אֱנוֹשׁ וְגוֹ׳. בְּיִסּוּרִין. וּכְשֵׁם שֶׁהוּא (מְרַפֵּא) מַכְאוֹבִים שֶׁל אֵלּוּ, כָּךְ אֲנִי אֶדְרוֹשׁ אֵלָיו עַל יִסּוּרִין אֵלּוּ שֶׁיָּבוֹאוּנִי; וְהָיָה לְךָ לְקַבְּלָם וְלֹא לְמָאֳסָם:\",1,0],[2,122,5,19,\"בְּשֵׁשׁ צָרוֹת. כְּשֶׁיָּבֹאוּ לָעוֹלָם יַצִּילְךָ עַל יְדֵי יִסּוּרִין שֶׁנִּתְיַסַּרְתָּ בָּהֶם, וְגַם בַּשְּׁבִיעִית כְּשֶׁתָּבֹא לֹא יִגַּע בְּךָ. וְעַכְשָׁיו הוּא מוֹנֶה אוֹתָן:\",1,0],[2,122,5,21,\"בְּשׁוֹט לָשׁוֹן. שֶׁל שָׂטָן תֵּחָבֵא אוֹתְךָ. אֵלּוּ הֵן הַשֶּׁבַע צָרוֹת: רָעָב וְחֶרֶב, לָשׁוֹן וְשׁוֹד וְגוֹ׳, וְחַיַּת הָאָרֶץ – הֵם לִיסְטִים:\",1,0],[2,122,5,23,\"אַבְנֵי הַשָּׂדֶה. מִין אָדָם הֵן:\",1,0],[2,122,5,23,\"וְחַיַּת הַשָּׂדֶה. הוּא שֶׁנִּקְרָא גְּרוּשׁ״ה בְּלַעַ״ז, וְזוֹ הִיא חַיַּת הַשָּׂדֶה מַמָּשׁ. וּבִלְשׁוֹן מִשְׁנָה תּוֹרַת כֹּהֲנִים נִקְרָאִים אַדְנֵי הַשָּׂדֶה (כלאים ח,ה):\",2,0],[2,122,5,23,\"הָשְׁלְמָה לָךְ. יִהְיֶה לָהּ שָׁלוֹם עִמָּךְ:\",3,0],[2,122,5,24,\"וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךָ. וְאָז בְּכָל מָקוֹם תִּהְיֶה בָּטוּחַ, כִּי שָׁלוֹם אָהֳלֶךָ:\",1,0],[2,122,5,24,\"וּפָקַדְתָּ נָוְךָ וְלֹא תֶחֱטָא. כְּמוֹ ״אֶל הַשַּׂעֲרָה וְלֹא יַחֲטִא״ (שופטים כ:טז), וְזוֹ הִיא הַשְּׁבִיעִית שֶׁמָּנִינוּ לְמַעְלָה (איוב ה:יט):\",2,0],[2,122,5,26,\"תָּבוֹא בְכֶלַח אֱלֵי קָבֶר. שֶׁתִּנָּצֵל מִן הַדֶּבֶר. וּבְכֶלַח – אֵין סֶמֶךְ בַּמִּקְרָא לְהָבִין מְלִיצָתוֹ. וּלְפִי עִנְיַן הַמְּלִיצָה יִפָּתֵר וְיִלָּמֵד מֵעִנְיָנוֹ, שֶׁהוּא לְשׁוֹן גְּמַר בִּשּׁוּל הַתְּבוּאָה, כְּשֶׁבִּשְּׁלָה כָּל צָרְכָּהּ. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה פֵּרְשׁוּ (מועד קטן כח.) בְּכֶלַח – בְּגִימַטְרִיָּא: שִׁשִּׁים שָׁנָה:\",1,0],[2,122,5,26,\"כַּעֲלוֹת גָּדִישׁ. כַּאֲשֶׁר נִסְתַּלֵּק הַגָּדִישׁ מִן הַקַּרְקַע בְּעִתּוֹ:\",2,0],[2,122,6,1,\"(מענה איוב):\",1,0],[2,122,6,2,\"וְהַוָּתִי. שִׁבְרִי:\",1,0],[2,122,6,2,\"יִשְׂאוּ יָחַד. עִם מִשְׁקָל שֶׁכְּנֶגְדָּם, וַאֲפִלּוּ הֵם חוֹל יַמִּים, יִכְבַּד מִמֶּנּוּ:\",2,0],[2,122,6,3,\"לָעוּ. מְגֻמְגָּמִין, כְּאָדָם שֶׁאֵין בּוֹ כֹּחַ לְהוֹצִיא דָּבָר מִפִּיו כְּתִקּוּנוֹ; וְכֵן ״וְשָׁתוּ וְלָעוּ״ (עובדיה א:טז), שֶׁכֵּן דֶּרֶךְ שִׁכּוֹר לְגַמְגֵּם בִּדְבָרָיו:\",1,0],[2,122,6,4,\"חֲמָתָם. אֶרֶס שֶׁלָּהֶם. דֶּרֶךְ פַּרְסִיִּים לָתֵת אֶרֶס שֶׁל נָחָשׁ בְּחִצֵּיהֶם:\",1,0],[2,122,6,5,\"הֲיִנְהַק פֶּרֶא וְגוֹ׳. כְּלוֹמַר: וְכִי לְחִנָּם אֲנִי צוֹעֵק? וַהֲלֹא בְּהֵמָה שׁוֹטָה אֵינָהּ נוֹהֶקֶת בִּזְמַן שֶׁיֵּשׁ לָהּ דֶּשֶׁא, וְכֵן שׁוֹר לֹא יִגְעֶה אֶלָּא אִם כֵּן אֵין לוֹ בְּלִיל תְּבוּאָה. בְּפֶרֶא נוֹהֵג לְשׁוֹן ׳נְהַק׳, וּבְשׁוֹר – לְשׁוֹן ׳גְּעִיָּה׳:\",1,0],[2,122,6,6,\"הֲיֵאָכֵל תָּפֵל. דָּבָר שֶׁהוּא בְּלִי מֶלַח וְצָרִיךְ לְהַמְלִיחוֹ, וְלֹא נִמְלַח, קָרוּי תָּפֵל בִּלְשׁוֹן מִשְׁנָה (שבת קכח.; חלין קיג.; נדרים נא.):\",1,0],[2,122,6,6,\"אִם יֶשׁ טַעַם בְּרִיר. הַבָּא מֵחֲמַת הַחֲלָמוֹת כְּשֶׁאוֹכֵל דָּבָר חָזָק שֶׁמַּרְבֶּה רִיר וְרוֹק, כְּגוֹן שׁוּם. כְּלוֹמַר: וְכִי סְבוּרִים אַתֶּם שֶׁיִּהְיוּ מִתְקַבְּלוֹת תְּשׁוּבוֹת שֶׁאֵין בָּהֶם מַמָּשׁ? רִיר, כְּמוֹ ״וַיּוֹרֶד רִירוֹ עַל זְקָנוֹ״ (שמואל א כא:יד):\",2,0],[2,122,6,6,\"חַלָּמוּת. כְּמוֹ ״יֶחֶלְמוּ בְנֵיהֶם״ (איוב לט:ד), לְשׁוֹן חוֹזֶק. וְיֵשׁ פּוֹתְרִים לְשׁוֹן חֲלוֹם, וְאֵין נִרְאֶה בְּעֵינַי, מִפְּנֵי דַּגְשׁוּת הַלָּמֶ״ד:\",3,0],[2,122,6,7,\"מֵאֲנָה לִנְגּוֹעַ נַפְשִׁי. כְּלוֹמַר: הַרְבֵּה יֵשׁ לִי לִזְעוֹק, כִּי דְבָרִים שֶׁהָיְתָה נַפְשִׁי מְמָאֶנֶת וְקָצָה לִנְגּוֹעַ בָּהֶן, לְשׁוֹן נְגִיעָה:\",1,0],[2,122,6,7,\"הֵמָּה כִּדְוֵי לַחְמִי. הֵמָּה לִי עַתָּה נְכוֹנִים לְמַשְׁמֵשׁ בָּהֶם כִּמְפוֹת שֻׁלְחָנִי, שֶׁלַּחְמִי נָתוּן בָּהֶם. כִּדְוֵי לְשׁוֹן ״וַיִּכְרֹת אֶת מִדְוֵיהֶם״ (שמואל ב י:ד). כָּךְ שָׁמַעְתִּי מִפִּי רַבִּי מְשֻׁלָּם רוֹפֵא. עִנְיָן אַחֵר: כִּמְפוֹת שֶׁמְּסַנְּנִין בָּהֶן אֶת הַתַּבְשִׁיל וּמַאֲכָל זָב מֵהֶם, דְּוֵי לְשׁוֹן דָּוָה זָבָה (ויקרא טו:לג, יט):\",2,0],[2,122,6,7,\"לַחְמִי. כָּל מַאֲכָל קָרוּי לֶחֶם, כְּמוֹ ״עֲבַד לְחֶם רַב״ (דניאל ה:א), וּכְמוֹ ״נַשְׁחִיתָה עֵץ בְּלַחְמוֹ״ (ירמיהו יא:יט), וְתִרְגֵּם יוֹנָתָן: ״סַמָּא דְמוֹתָא בְּמֵיכְלֵיהּ״. לָשׁוֹן אַחֵר: הֵמָּה כְּמַבָּטֵי מַאֲכָלִי, כְּלוֹמַר: גַּס לִבִּי לְהִסְתַּכֵּל בָּהֶם בְּרִמָּה, כַּאֲשֶׁר אֲנִי מִסְתַּכֵּל בְּמַאֲכָלִי. וּלְשׁוֹן מִשְׁנָה הוּא: ״וּמְסַגּוֹ כִּי דָווּ״, בְּמַסֶּכֶת שַׁבָּת (שבת נג:):\",3,0],[2,122,6,9,\"וְיוֹאֵל. וְיִרְצֶה:\",1,0],[2,122,6,9,\"וִידַכְּאֵנִי. לְשׁוֹן מִיתָה:\",2,0],[2,122,6,9,\"יַתֵּר יָדוֹ. יְגַדֵּל יָדוֹ בְּמַכָּתוֹ, כְּמוֹ ״הִנֵּה יַד ה׳ הוֹיָה״ (שמות ט:ג):\",3,0],[2,122,6,9,\"וִיבַצְּעֵנִי. וִיכַלֵּנִי, כְּמוֹ ״בִּצַּע אֶמְרָתוֹ״ (איכה ב:יז), ״יָדָיו תְּבַצַּעְנָה״ (זכריה ד:ט):\",4,0],[2,122,6,10,\"וּתְהִי עוֹד נֶחָמָתִי. וּתְהִי עוֹד זֹאת לִי לְנֶחָמָה:\",1,0],[2,122,6,10,\"וַאֲסַלְּדָה בְחִילָה וְלֹא יַחְמוֹל. וַאֲבַקֵּשׁ מִמֶּנּוּ סְלִיחָה שֶׁלֹּא יַחְמוֹל מִלְּבַצְּעֵנִי, וַאֲנִי אֵינִי מוֹצֵא לוֹ דִּמְיוֹן בַּמִּקְרָא, זוּלָתִי שֶׁבִּלְשׁוֹן מִשְׁנָה הוּא לְשׁוֹן יָרֵא וְדוֹאֵג (חולין קה:): שֶׁהַיָּד סוֹלֶדֶת בָּהֶן מִלִּכָּווֹת בָּרוֹתְחִין; כְּלוֹמַר: אֶתְחוֹלֵל בִּדְאָגָה וּבְחִילָה בַּקָּשָׁה זוֹ:\",2,0],[2,122,6,10,\"כִּי לֹא כִחַדְתִּי. וְלֹא חָסַרְתִּי אֲמָרָיו מִלְּקַיְּמָן:\",3,0],[2,122,6,11,\"מַה כֹּחִי. חָזָק לִסְבּוֹל:\",1,0],[2,122,6,11,\"כִּי אֲיַחֵל. כִּי אֲמְתִּין עַד יוֹם רְפוּאָה אוֹ עַד יוֹם מִיתָה:\",2,0],[2,122,6,11,\"אֲיַחֵל. כְּמוֹ ״וַיָּחֶל עוֹד״ דְּנֹחַ (בראשית ח:י):\",3,0],[2,122,6,11,\"וּמַה קִּצִּי. וּמָה חָשׁוּב קִצִּי וְחָזָק כִּי אֲיַחֵל, כִּי לֹא אוּכַל לְהַאֲרִיךְ קִצִּי מִלִּסְבּוֹל:\",4,0],[2,122,6,11,\"נַפְשִׁי. הוּא יֵצֶר תַּאֲוַת אָדָם, בְּכַמָּה מְקוֹמוֹת, כְּמוֹ ״אִם יֵשׁ אֶת נַפְשְׁכֶם״ (בראשית כג:ח):\",5,0],[2,122,6,13,\"הַאִם אֵין עֶזְרָתִי בִי. לְשׁוֹן תֵּימָא: הֲגַם זֹאת תָּבֹא עָלַי, שֶׁאֵין עֶזְרָתִי בִּי – אוֹתָם רֵיעִים שֶׁהָיוּ לִי לְעָזְרֵנִי, אֵינָם בְּעֶזְרָתִי?!\",1,0],[2,122,6,13,\"וְתוּשִׁיָּה נִדְּחָה. עֵצָה שֶׁל יוֹעֲצִים נִדְּחָה מִמֶּנִּי, שֶׁקָּמָה עָלַי לְהַקְנִיט וְלִדְחוֹת:\",2,0],[2,122,6,14,\"לַמָּס מֵרֵעֵהוּ חָסֶד. לְמִי שֶׁמּוֹנֵעַ חֶסֶד מֵחֲבֵירוֹ. וְהַלָּמֶ״ד – מְשַׁמֶּשֶׁת, כְּמוֹ ״לָרָב״ (במדבר כו:נד), ״לָצָו״ (ישעיהו כח:י), לָשָׁב. מָס גַּם הוּא לְשׁוֹן פּוֹעֵל, כְּמוֹ בָּא, שָׁב, נָד, גַּם אֵלֶּה לְשׁוֹן עוֹשֶׂה:\",1,0],[2,122,6,14,\"לַמָּס הַחֶסֶד. מְכַלֶּה אוֹתוֹ, כְּמוֹ ״וְחַם הַשֶּׁמֶשׁ וְנָמָס״ (שמות טז:כא):\",2,0],[2,122,6,15,\"אַחַי. בְּנֵי מְלִיצָתִי:\",1,0],[2,122,6,15,\"בָּגְדוּ. בִּי, כְּמוֹ הַנַּחַל הַבּוֹגֵד בְּגִידוֹת כְּמוֹ שֶׁמְּפָרֵשׁ בָּעִנְיָן:\",2,0],[2,122,6,15,\"כַּאֲפִיק נְחָלִים. מוֹצָא נְחָלִים יַעַבְרוּ מִמִּדָּה נְכוֹחָה וְרֵיעוּת. וּמַה הִיא בְּגִידוּתוֹ שֶׁל נַחַל?\",3,0],[2,122,6,16,\"הַקּוֹדְרִים מִנִּי קָרַח. אִם בָּא עֲלֵיהֶם קֶרַח נִקְמָטִים וְנַעֲשִׂים קְרִים (קרשים קרים):\",1,0],[2,122,6,16,\"וְעָלֵימוֹ יִתְעַלֶּם. מִתְכַּסֶּה הַשֶּׁלֶג שֶׁנּוֹפֵל עַל הַקֶּרַח. הֲרֵי בְּגִידָה אַחַת: שֶׁנִּתְכַּסָּה מִן הָעַיִן, וְאֵין הַצָּמֵא מוֹצֵא מַיִם לִשְׁתּוֹת:\",2,0],[2,122,6,17,\"בְּעֵת יְזֹרְבוּ. לְשׁוֹן יְצֹרְבוּ, כְּחוֹם הַשֶּׁמֶשׁ:\",1,0],[2,122,6,17,\"נִצְמָתוּ. רֶטְרִי״שׁ בְּלַעַ״ז, כְּמוֹ ״וְחֹמֶץ צוֹמְתָן״ בִּלְשׁוֹן גְּמָרָא (פסחים מ:). צָדִ״י מִתְחַלֶּפֶת בְּזַיִ״ן, כְּמוֹ צְעָקָה זְעָקָה (בראשית כז:לד; ישעיהו סה:יט):\",2,0],[2,122,6,17,\"יְזֹרְבוּ. לְשׁוֹן ״וְנִצְרְבוּ בָהּ כָּל פָּנִים״ (יחזקאל כא:ג), וּכְמוֹ ״אֵשׁ צָרֶבֶת״ (משלי טז:כז):\",3,0],[2,122,6,17,\"נִדְעֲכוּ. נִקְפְּצוּ מִמְּקוֹמָם:\",4,0],[2,122,6,18,\"יִלָּפְתוּ. יֵאָחֲזוּ אָרְחוֹת דַּרְכָּם, כְּמוֹ ״וַיִּלְפֹּת שִׁמְשׁוֹן״ (שופטים טז:כט), וְכֵן ״וַיֶּחֱרַד הָאִישׁ וַיִּלָּפֵת״ (רות ג:ח) – שֶׁחִבְּקַתּוּ הָאִשָּׁה:\",1,0],[2,122,6,19,\"תֵּימָא. אֶרֶץ יִשְׁמָעֵאל שֶׁהִיא נְמוּכָה, וְהַמַּיִם נִגָּרִים שָׁם:\",1,0],[2,122,6,19,\"קִוּוּ. לְשׁוֹן קַו נָטוּי (ישעיהו לד:יא). דָּבָר אַחֵר: לְשׁוֹן ״יִקָּווּ הַמַּיִם״ (בראשית א:ט):\",2,0],[2,122,6,20,\"בֹּשׁוּ כִּי בָטָח בָּאוּ עָדֶיהָ. יֵבוֹשׁוּ שׁוֹתֶיהָ, כִּי בָטַח כָּל אִישׁ וְאִישׁ לִשְׁתּוֹת מֵהֶם:\",1,0],[2,122,6,21,\"כִּי עַתָּה הֱיִיתֶם לוֹ. הֱיִיתֶם נִמְשָׁלִים לְאוֹתוֹ נַחַל:\",1,0],[2,122,6,21,\"תִּירְאוּ חֲתַת. וּפַחַד הַמַּכָּה, וַתִּירְאוּ לוֹמַר הָאֱמֶת; וּמַחֲנִיפִים אֶת בַּעַל רִיבִי:\",2,0],[2,122,6,22,\"וּמִכֹּחֲכֶם שִׁחֲדוּ בַעֲדִי. וּמִמָּמוֹנְכֶם:\",1,0],[2,122,6,25,\"מַה נִּמְרְצוּ. כְּמוֹ ״קְלָלָה נִמְרֶצֶת״ (מלכים א ב:ח), לְשׁוֹן ״דָּבָר דָּבוּר עַל אָפְנָיו״ (משלי כה:יא). וְכֵן ״נִמְלְצוּ לְחִכִּי״ (תהלים קיט:קג) – כֻּלָּן לְשׁוֹן מְלִיצָה הֵם, וְלָמֶ״ד מִתְחַלֶּפֶת בְּרֵי״שׁ:\",1,0],[2,122,6,25,\"אִמְרֵי יֹשֶׁר. אִם אִמְרֵי יֹשֶׁר הֱיִיתֶם אוֹמְרִים, הָיוּ מְקֻבָּלִים; אֲבָל עַתָּה, מַה יּוֹכִיחַ הוֹכֵחַ מִכֶּם? כָּל תּוֹכָחָה שֶׁבְּאִיּוֹב – בֵּרוּר הַדְּבָרִים הֵם, וּמַעֲמִידִים עַל הָאֱמֶת:\",2,0],[2,122,6,26,\"הֲלְהוֹכַח מִלִּים תַּחְשֹׁבוּ. הֲלְבָרֵר דְּבָרִים תַּחְשֹׁבוּ?\",1,0],[2,122,6,26,\"וּלְרוּחַ. הֵם מְשׁוּלִים:\",2,0],[2,122,6,26,\"אִמְרֵי נוֹאָשׁ. שֶׁאֵין בָּהֶם מַמָּשׁ, כְּמוֹ ״וַתֹּאמְרִי נוֹאָשׁ״ (ירמיה ב:כה) – אֵינִי חוֹשֵׁשׁ לְדִבְרֵי הַנְּבִיאִים:\",3,0],[2,122,6,27,\"תַּפִּילוּ. בְּדִינְכֶם אַתֶּם מַפִּילִים. הַאַף עַל עָנִי כָּמוֹנִי בְּקַו מִשְׁפָּט? וְתִכְרוּ שׁוּחָה עַל רֵיעֲכֶם לְהַפִּילוֹ?\",1,0],[2,122,6,28,\"הוֹאִילוּ. הִתְרַצּוּ לִפְנוֹת אֵלַי וְלִשְׁמֹעַ דְּבָרַי, וְתִרְאוּ אִם עַל פְּנֵיכֶם אֲכַזֵּב:\",1,0],[2,122,6,29,\"שׁוּבוּ נָא. לִבְחוֹן, וְתִבְחֲנוּ, שֶׁלֹּא תְהֵא עוֹד עַוְלָה וְשׁוּבוּ לַחֲקוֹר, וַהֲרֵי צִדְקִי יִמָּצֵא בָהּ:\",1,0],[2,122,6,30,\"אִם חִכִּי לֹא יָבִין הַוּוֹת. לֹא יָבִין כְּשֶׁאֲנִי מְדַבֵּר הַוּוֹת?\",1,0],[2,122,7,1,\"הֲלֹא צָבָא וְגוֹ׳. זֶה הַדָּבָר אֲשֶׁר אָמַרְתִּי לָכֶם הוֹאִילוּ פְּנוּ בִי, כִּי אֵיךְ אַחֲרִישׁ מִלִּזְעוֹק עַל הַוָּתִי? הֲלֹא יְדַעְתֶּם כִּי יֵשׁ צָבָא וּזְמַן לֶאֱנוֹשׁ, כַּמָּה יִחְיֶה:\",1,0],[2,122,7,1,\"וְכִימֵי שָׂכִיר. שֶׁנִּשְׂכַּר לְשָׁנָה, וְיוֹדֵעַ שֶׁיִּכְלוּ יְמֵי שְׂכִירוּתוֹ, כֵּן זֶה יוֹדֵעַ שֶׁיִּכְלוּ שָׁנִים הַקְּצוּבוֹת לוֹ. וַאֲנִי – אוֹתוֹ צָבָא הַנִּתָּן לִי:\",2,0],[2,122,7,2,\"כְּעֶבֶד יִשְׁאַף צֵל. כְּעֶבֶד שֶׁהוּא יָגֵעַ כָּל הַיּוֹם, וְיִשְׁאַף וְיִתְאַוֶּה מָתַי יִהְיֶה צֵל הָעֶרֶב; וּכְשָׂכִיר אֲשֶׁר יְקַוֶּה פָעֳלוֹ לָעֶרֶב, לְפִי שֶׁהָיָה לוֹ כָּל הַיּוֹם לְעָמָל, וְיִתְאַוֶּה לְבִיאַת הַשֶּׁמֶשׁ:\",1,0],[2,122,7,3,\"כֵּן הָנְחַלְתִּי לִי. מִשָּׁמַיִם יַרְחֵי שָׁוְא וְיִסּוּרִין, אוֹתוֹ ״צָבָא הַנִּתָּן לֶאֱנוֹשׁ עֲלֵי אָרֶץ״ (איוב ז:א):\",1,0],[2,122,7,3,\"וְלֵילוֹת עָמָל מִנּוּ לִי. (מִן הַשָּׁמַיִם):\",2,0],[2,122,7,4,\"אִם שָׁכַבְתִּי. בַּלַּיְלָה, צָפִיתִי וְאָמַרְתִּי וְגוֹ׳:\",1,0],[2,122,7,4,\"וּמִדַּד עָרֶב. מָתַי יָאִיר, וְיָבֹא עֵת קִימָה וְעֵת מִידוּד הַנֶּשֶׁף – לְשׁוֹן ״וַתִּדַּד שְׁנָתִי״ (בראשית לא:מ), וְהַמֵּ״ם הוּא עִקָּר נוֹפֵל, כְּמוֹ ״מַאֲמַר״ (אסתר א:טו), ״מִשְׁמָר״ (בראשית מב:יז):\",2,0],[2,122,7,4,\"וְשָׂבַעְתִּי נְדוּדִים. וְאֶשְׂבַּע נְדוּדִים עַל מִטָּתִי בַּיּוֹם עַד נָשֶׁף, לְפִי שֶׁלֹּא הָיִיתִי יָכוֹל לִישֹׁן מִפְּנֵי יִסּוּרִים עַד נֶשֶׁף שֶׁל יוֹם, לְפִי שֶׁלָּבַשׁ בְּשָׂרִי רִמָּה:\",3,0],[2,122,7,5,\"וְגוּשׁ עָפָר. גּוּשַׁת עָפָר, וְהִיא הֶעֶלְתָה חֲלוּדָּה; שֶׁדֶּרֶךְ גּוּשׁ עָפָר לְלַחְלֵחַ וּלְהַעֲלוֹת חֲלוּדָּה:\",1,0],[2,122,7,5,\"רָגַע. נִקְמַט, כְּמוֹ ״רֹגַע הַיָּם״ (ישעיה נא:טו). פֵּרוּשׁ אַחֵר: עוֹרִי רָגַע. לְשׁוֹן נוֹחַ, גַּל אַחַר גַּל, כַּקְּמָטִים הַלָּלוּ:\",2,0],[2,122,7,6,\"יָמַי קַלּוּ. יְמֵי טוֹבָתִי מִהֲרוּ לָלֶכֶת:\",1,0],[2,122,7,6,\"מִנִּי אָרֶג. מִנִּי אֲרִיגָה הַנַּעֲשֵׂית מְהֵרָה, וְכֵן אָמַר חִזְקִיָּה: ״קִפַּדְתִּי כָאֹרֵג חַיַּי״ (ישעיה לח:יב):\",2,0],[2,122,7,6,\"בְּאֶפֶס תִּקְוָה. אֵינִי מְקַוֶּה עוֹד לְטוֹבָה:\",3,0],[2,122,7,7,\"לֹא תָשׁוּב עֵינִי. לְאַחַר מִיתָה. וְכָאן כָּפַר אִיּוֹב בִּתְחִיַּת הַמֵּתִים:\",1,0],[2,122,7,8,\"לֹא תְשׁוּרֵנִי. לֹא יִרְאֵנִי עוֹד עַיִן שֶׁתַּחְפֹּץ לִרְאוֹתִי אַחַר שֶׁאָמוּת:\",1,0],[2,122,7,8,\"עֵינֶיךָ בִּי וְאֵינֶנִּי. לְהַקָּדוֹשׁ בָּרוּךְ הוּא מְדַבֵּר: לָמָּה הֻצְרַכְתָּ לְפַצְּעֵנִי וּלְדַכְּאֵנִי בְּיִסּוּרִים? בִּרְאִיָּה אַחַת, שֶׁתָּשִׂים עֵינֶיךָ עָלַי, וְאֵינֶנִּי בָּעוֹלָם!\",2,0],[2,122,7,11,\"גַּם אֲנִי לֹא אֶחֱשָׂךְ פִּי. הוֹאִיל וְאֵינְךָ חָדֵל מִמֶּנִּי, גַּם אֲנִי לֹא אֶמְנַע דִּבּוּר מִלִּצְעֹק עַל מִדּוֹתֶיךָ:\",1,0],[2,122,7,12,\"הֲיָם אָנִי. שֶׁשַּׂמְתָּ עָלַי חוֹל לְמִשְׁמָר?!\",1,0],[2,122,7,12,\"אִם תַּנִּין. דָּג גָּדוֹל שֶׁחֲבַשְׁתּוֹ בְּנִבְכֵי יָם, כִּי תָשִׂים עָלַי מִשְׁמָר. הַשָּׂטָן הַזֶּה, לְשׁוֹמְרֵנִי, שֶׁלֹּא תֵצֵא נַפְשִׁי?!\",2,0],[2,122,7,13,\"יִשָּׂא בְשִׂיחִי מִשְׁכָּבִי. מִשְׁכַּב הַלַּיְלָה יִסְבֹּל בְּצָרָתִי מְעַט, וְאוּכַל לִמְנֹעַ שִׂיחִי:\",1,0],[2,122,7,15,\"מָוֶת מֵעַצְמוֹתָי. מָוֶת אֲנִי בּוֹחֵר יוֹתֵר מֵאֵיבָרִים הַלָּלוּ שֶׁבִּי:\",1,0],[2,122,7,16,\"מָאַסְתִּי. בְּחַיַּי, כִּי סוֹף סוֹף לֹא לְעוֹלָם אֶחְיֶה:\",1,0],[2,122,7,16,\"חֲדַל מִמֶּנִּי. מִלְּהָרַע לִי, כִּי הֶבֶל וּמְעַט יָמָי:\",2,0],[2,122,7,17,\"כִּי תְגַדְּלֶנּוּ. לָשִׂית אֵלָיו לִבְּךָ, לִפְקֹד מַעֲשָׂיו בְּכָל בֹּקֶר, וְלִבְחֹן לְכָל רֶגַע:\",1,0],[2,122,7,19,\"כַּמָּה. עֵת אָרֹךְ אֲשֶׁר לֹא תִשְׁעֶה מִמֶּנִּי, כְּמוֹ (שמות ה:ט) ״וְאַל יִשְׁעוּ בְּדִבְרֵי שָׁקֶר״, וְכֵן (איוב יד:ו) ״שְׁעֵה מֵעָלַי וַחֲדָל״:\",1,0],[2,122,7,19,\"בִּלְעִי רֻקִּי. כְּדֵי בְּלִיעַת רֻקִּי:\",2,0],[2,122,7,20,\"לְמִפְגָּע לָךְ. כְּפוֹגֵעַ הָאָדָם בְּעֵת חֲמָתוֹ, וּמְעוֹרֵר עָלָיו כָּל מַעֲשֵׂה אֵיבָתוֹ (ס״א חוֹבָתוֹ):\",1,0],[2,122,7,20,\"וָאֶהְיֶה עָלַי לְמַשָּׂא. זֶה אֶחָד מִן תֵּיבוֹת שֶׁכִּינָּה הַכָּתוּב, וְהֵן תִּיקּוּן סוֹפְרִים:\",2,0],[2,122,7,21,\"וּמֶה לֹא תִשָּׂא פִשְׁעִי. וּמָה הַדָּבָר הַזֶּה, שֶׁאֵינְךָ נוֹשֵׂא לְפִשְׁעִי?\",1,0],[2,122,7,21,\"וְשִׁחַרְתַּנִי. תְּבַקְּשֵׁנִי וְלֹא תִמְצָאֵנִי:\",2,0],[2,122,8,2,\"(מענה בלדד): וְרוּחַ כַּבִּיר. רוּחַ דְּבָרִים:\",1,0],[2,122,8,2,\"כַּבִּיר. לְשׁוֹן רוֹב:\",2,0],[2,122,8,3,\"הַאֵל יְעַוֵּת מִשְׁפָּט. הַהֵ״א נָקוּד פַּתָּח, וּמְלִיצָתוֹ לְשׁוֹן תֵּימַהּ:\",1,0],[2,122,8,4,\"וַיְשַׁלְּחֵם בְּיַד פִּשְׁעָם. עַל יְדֵי פִּשְׁעָם, (הַפֶּשַׁע) הוּא נַעֲשָׂה שָׁלִיחַ לְהוֹבִילָם:\",1,0],[2,122,8,5,\"אִם אַתָּה תְשַׁחֵר וְגוֹ׳. יָעִיר עָלֶיךָ אֶת זְכוּתְךָ:\",1,0],[2,122,8,6,\"וְשִׁלַּם נְוַת צִדְקֶךָ. וְיַעֲשֶׂה אֶת נְוַת צִדְקְךָ שָׁלֵם וְתָמִים:\",1,0],[2,122,8,7,\"וְהָיָה רֵאשִׁיתְךָ מִצְעָר. רֵאשִׁיתְךָ שֶׁעָבְרָה מִצְעָר, לְפִי אַחֲרִיתְךָ, שֶׁיִּשְׂגֶּה מְאֹד:\",1,0],[2,122,8,8,\"לְדוֹר רִישׁוֹן. עַל דּוֹר רִאשׁוֹן, כְּמוֹ ״כִּי שְׁאַל נָא לְיָמִים רִאשׁוֹנִים״ (דברים ד:לב):\",1,0],[2,122,8,8,\"וְכוֹנֵן. הָכֵן וְהִזְדַּמֵּן לַעֲמֹד עַל חֶקְרֵי אֲבוֹתָם:\",2,0],[2,122,8,11,\"הֲיִגְאֶה גֹּמֶא. זֹאת יֹאמְרוּ: אֵין הַגֹּמֶא גָּדֵל אֶלָּא בְּעוֹד שֶׁהַבִּצָּה לַחָה בְּמֵימֶיהָ וּבְלִחְלוּחֶיהָ. בִּצָּה מָרִישְׁ״ק בְּלַעַ״ז:\",1,0],[2,122,8,12,\"בְּאִבּוֹ. בְּלִחְלוּחוֹ וּבְפִרְיוֹ:\",1,0],[2,122,8,12,\"לֹא יִקָּטֵף. לֹא יִשָּׁבֵר וְלֹא יִנָּתֵק, כְּמוֹ ״וְקָטַפְתָּ מְלִילֹת״ (דברים כג:כו):\",2,0],[2,122,8,12,\"וְלִפְנֵי כָל חָצִיר יִיבָשׁ. קוֹדֶם כָּל חָצִיר יִיבַשׁ, כְּשֶׁהַמַּיִם כָּלִים וְהַבִּיצָּה חֲרֵבָה:\",3,0],[2,122,8,13,\"כֵּן אָרְחוֹת כָּל שֹׁכְחֵי אֵל. לְהַצְלִיחַ בְּעֵת שֶׁשָּׁעָתוֹ מְשַׂחֶקֶת לוֹ, עַד שֶׁתִּתְמַלֵּא סְאָתוֹ:\",1,0],[2,122,8,13,\"וְתִקְוַת. סוֹפוֹ שֶׁל חָנֵף יֹאבַד:\",2,0],[2,122,8,14,\"אֲשֶׁר יָקוֹט. יִקְצוֹר וְיִכְרוֹת כִּסְלָתוֹ וְהַבְטָחָתוֹ:\",1,0],[2,122,8,14,\"כִּסְלוֹ. הִיא מַחֲשֶׁבֶת מִבְטַחוֹ, כְּמוֹ (איוב לא:כד) ״אִם שַׂמְתִּי זָהָב כִּסְלִי״. יָקוֹט, לְשׁוֹן קָצִיר, כְּמוֹ (יחזקאל טז:מז) ״כִּמְעַט קָט״:\",2,0],[2,122,8,14,\"וּבֵית עַכָּבִישׁ. שֶׁאֵינוֹ קַיָּם, יִהְיֶה מִבְטַחוֹ:\",3,0],[2,122,8,16,\"רָטֹב הוּא. לַח וְחָזָק מַזָּלוֹ טֶרֶם בָּא אֵלָיו עֵת פְּקֻדַּת מַכַּת חוּמוֹ, הַמְיַיבַּשְׁתּוֹ. וּלְפִי שֶׁדִּמָּהוּ בְּגֹמֶא (לעיל ח:יא), מְדַבֵּר לְפִי הָעִנְיָן:\",1,0],[2,122,8,16,\"וְעַל גַּנָּתוֹ יוֹנַקְתּוֹ תֵצֵא. יוֹנַקְתּוֹ שֹׁרֶשׁ הַיּוֹנֵק, אוֹ עָנָף הַיַּלְדָּה הַגָּדֵל בְּשָׁנָה זוֹ, כְּמוֹ ״מֵרֹאשׁ יֹנְקוֹתָיו קָטֹף״ (יחזקאל יז:כב):\",2,0],[2,122,8,17,\"יְסֻבָּכוּ. יִתְאַחֲזוּ בֶּעָנָף וּבְסוֹבֶךְ:\",1,0],[2,122,8,17,\"בֵּית אֲבָנִים. יֶחֱזֶה מָקוֹם אֵיתָן רוֹאֶה וּבוֹנֶה לוֹ לִמְצוּדָה. וּמְנַחֵם פֵּרֵשׁ יֶחֱזֶה לְשׁוֹן גְּבוּל: יִגְבּוֹל אוֹתוֹ, יִבְנֶנּוּ עַד גְּבוּלוֹ, וְכֵן ״מְחוֹז חֶפְצָם״ (תהילים קז:ל), וְכֵן ״מֶחֱזָה אֶל מֶחֱזָה״ (מלכים א ז:ד). כָּל אֵלֶּה לִפְנֵי מַכָּתוֹ:\",2,0],[2,122,8,18,\"וּכְשֶׁיְּבַלְּעֶנּוּ. מִמְּקוֹמוֹ – הַנִּפְרָע מִמֶּנּוּ. וּמִקְרָא חָסֵר הוּא זֶה:\",1,0],[2,122,8,18,\"וְכִחֶשׁ בּוֹ. מְקוֹמוֹ:\",2,0],[2,122,8,18,\"לֹא רְאִיתִיךָ. שֶׁאֵין נִשְׁאָר מִמֶּנּוּ לֹא שֹׁרֶשׁ וְלֹא עָנָף, וַהֲרֵי הוּא כְּלֹא הָיָה. שֶׁאֵין נְפִילָתוֹ כְּמַפֶּלֶת צַדִּיקִים; כִּי הַצַּדִּיק יִפּוֹל וְיָקוּם (משלי כד:טז), וְזֶה יִפּוֹל בְּלֹא תְקוּמָה:\",3,0],[2,122,8,19,\"הֵן הוּא מְשׂוֹשׂ דַּרְכּוֹ. שֶׁל רָשָׁע, שֶׁכָּל מְשׂוֹשׂוֹ וְגַם הַצְלָחָתוֹ, לְלֹא תִּקְוָה תָּשׁוּב:\",1,0],[2,122,8,19,\"וּמֵעָפָר אַחֵר יִצְמָחוּ. בְּנֵי אָדָם שֶׁהָיוּ עַד הֵנָּה שָׁחִים עַד עָפָר, יִצְמָחוּ:\",2,0],[2,122,8,19,\"אַחֵר. אָדָם אַחֵר יִצְמַח לְקַבֵּל גְּדֻלָּתוֹ שֶׁל זֶה, כְּשֵׁם שֶׁמָּצִינוּ ״וְלַחוֹטֵא נָתַן עִנְיָן וְגוֹ׳״ (קהלת ב:כו). עַל כֵּן דַּע עַל עַצְמְךָ: אִם רָשָׁע הָיִיתָ, אֵין תְּקוּמָה לְמַפַּלְתְּךָ, וְאִם תָּם הָיִיתָ וְכוּ׳:\",3,0],[2,122,8,20,\"הֵן אֵל לֹא יִמְאַס תָּם. וְלֹא יַחֲזִיק בְּיַד מְשַׂנְאֶיךָ הַמְּרֵעִים לְךָ, עַד אֲשֶׁר יָשׁוּב לְרַחֵם עָלֶיךָ וִימַלֵּא שְׂחוֹק פִּיךָ:\",1,0],[2,122,9,3,\"(מענה איוב): לָרִיב עִמּוֹ. לְהִתְוַכֵּחַ עִמּוֹ:\",1,0],[2,122,9,4,\"חֲכַם לֵבָב. הוּא לָרִיב:\",1,0],[2,122,9,4,\"וְאַמִּיץ כֹּחַ. לְהִפָּרַע:\",2,0],[2,122,9,4,\"מִי הִקְשָׁה. לִבּוֹ וְהָלַךְ שָׁלֵם?! פַּרְעֹה הִקְשָׁה וְנֶחְסַר (שמות ז:יג, ח:טו, ט:יב), וְכֵן כָּל הַמַּקְשִׁים:\",3,0],[2,122,9,5,\"הַמַּעְתִּיק הָרִים. הַמְּסַלְּקָם, כְּהָפְכוֹ סְדוֹם (בראשית יט:כה):\",1,0],[2,122,9,5,\"וְלֹא יָדָעוּ. עַד שֶׁנֶּהֶפְכוּ:\",2,0],[2,122,9,6,\"הַמַּרְגִּיז אֶרֶץ. בְּהַבִּיטוֹ אֵלֶיהָ וְתִרְעָד (תהלים קד:לב):\",1,0],[2,122,9,7,\"הָאוֹמֵר לַחֶרֶס. לַשֶּׁמֶשׁ: דּוֹם (יהושע י:יב)! וְהוּא שָׁמַר אִמְרַת מֶלֶךְ וְלֹא יִזְרָח:\",1,0],[2,122,9,7,\"וּבְעַד. וּכְנֶגֶד הַכּוֹכָבִים יִסְגֹּר מְחִיצָה, וְלֹא יָאִירוּ:\",2,0],[2,122,9,8,\"נוֹטֶה שָׁמַיִם לְבַדּוֹ. וּמַלְאָכִים נִבְרְאוּ בַּיּוֹם שֵׁנִי, שֶׁלֹּא תֹּאמַר: מִיכָאֵל מָתַח בַּצָּפוֹן, וְגַבְרִיאֵל בַּדָּרוֹם:\",1,0],[2,122,9,8,\"עַל בָּמֳתֵי יָם. עַל גָּבְהֵי יָם. וְעַל מַעֲשֵׂה בְרֵאשִׁית נֶאֱמַר, שֶׁגָּבְהוּ הַמַּיִם הַתַּחְתּוֹנִים לָרוּם לְמַעְלָה, וּדְרָכָם:\",2,0],[2,122,9,9,\"כְּסִיל וְכִימָה. מַזָּלוֹת הֵם:\",1,0],[2,122,9,9,\"וְחַדְרֵי תֵימָן. לְהַכְנִיס שָׁם סוּפָה, כְּמוֹ שֶׁאָמַר ״מִן הַחֶדֶר תָּבוֹא סוּפָה״ (איוב לז:ט):\",2,0],[2,122,9,11,\"הֵן יַעֲבֹר וְגוֹ׳. יָדַעְתִּי כִּי כָּל אֲשֶׁר יַחְפֹּץ יַעֲשֶׂה:\",1,0],[2,122,9,11,\"יַעֲבֹר עָלַי. לְפָנַי, וְלֹא אֶרְאֶנּוּ:\",2,0],[2,122,9,12,\"יַחְתֹּף. יַכֶּה פִּתְאוֹם, כְּמוֹ ״הִיא כְחָתֶף תֶּאֱרֹב״ (משלי כג:כח). לְשׁוֹן ׳פִּתְאוֹם׳ הוּא:\",1,0],[2,122,9,13,\"לֹא יָשִׁיב אַפּוֹ. מִפְּנֵי יִרְאַת (וְצִדְקַת ס״א) אִישׁ:\",1,0],[2,122,9,13,\"תַּחְתָּו שָׁחֲחוּ. צְבָא מָרוֹם שֶׁבָּאוּ לַעֲזוֹר אֶת מִצְרַיִם. מִצְרַיִם נִקְרָא רַהַב, שֶׁנֶּאֱמַר ״לָכֵן קָרָאתִי לָזֹאת רַהַב הֵם שָׁבֶת״ (ישעיהו ל:ז) – עַל שֵׁם גַּאֲוָתָם, אֲשֶׁר אָמְרוּ ״מִי ה׳ וְגוֹ׳״ (שמות ה:ב):\",2,0],[2,122,9,14,\"אַף. כָּל שֶׁכֵּן:\",1,0],[2,122,9,15,\"לֹא אֶעֱנֶה. אִירָא לְהָרִים קוֹל לְפָנָיו:\",1,0],[2,122,9,15,\"לִמְשׁוֹפְטִי. כְּמוֹ לְשׁוֹפְטִי:\",2,0],[2,122,9,16,\"לֹא אַאֲמִין. לֹא אוּכַל לְהַאֲמִין מִיִּרְאָתִי אוֹתוֹ, כִּי אֵיךְ לֹא אִירָאֶנּוּ?\",1,0],[2,122,9,17,\"אֲשֶׁר בִּשְׂעָרָה. נִתְחַלְּפָה צוּרָתִי (ס״א שׁוּרָתִי) לְפָנָיו:\",1,0],[2,122,9,17,\"יְשׁוּפֵנִי. יְכַתְּתֵנִי, וְ״אָכֹת אֹתוֹ טָחוֹן״ (דברים ט:כא) מְתַרְגְּמִינָן ״וְשָׁפֵית יָתֵיהּ״ (תרגום אונקלוס):\",2,0],[2,122,9,17,\"פְּצָעַי. מַכָּה הַמּוֹצִיאָה דָּם וְלֵחָה:\",3,0],[2,122,9,18,\"לֹא יִתְּנֵנִי. אֵינוֹ מַנִּיחֵנִי לְהָשִׁיב רוּחִי אֵלַי:\",1,0],[2,122,9,19,\"אִם לְכֹחַ. אֵיךְ אָרִיב עִמּוֹ? אִם לְכֹחַ הוּא בָּא – אַמִּיץ הִנֵּה הוּא:\",1,0],[2,122,9,19,\"וְאִם לְמִשְׁפָּט. מִי יוּכַל לְהוֹעִידֵנִי לְפָנָיו וּלְהַחֲזִיק דְּבַר מִשְׁפָּטִי?\",2,0],[2,122,9,20,\"הֲלֹא אִם אֶצְדָּק פִּי יַרְשִׁיעֵנִי. כִּי יִסָּתְמוּ דְבָרַי מִיִּרְאָה, וְיַעְקְשֵׁנִי פִּי:\",1,0],[2,122,9,21,\"תָּם אָנִי. יוֹדֵעַ אֲנִי בְּעַצְמִי שֶׁאֲנִי תָּם, וְאַף עַל פִּי כֵן לֹא אֵדַע נַפְשִׁי. בַּמֶּה אֶמְצָא נוֹפֶשׁ:\",1,0],[2,122,9,22,\"אַחַת הִיא. בָּעוֹלָם, וְעָלֶיהָ אָמַרְתִּי שֶׁתָּם וְרָשָׁע הוּא מְכַלֶּה בַּעֲבוּרָהּ; וּמַה הִיא?\",1,0],[2,122,9,23,\"אִם שׁוֹט. לָשׁוֹן שֶׁל שָׂטָן יָמִית פִּתְאוֹם אֶת הַצַּדִּיק:\",1,0],[2,122,9,23,\"לְמַסַּת נְקִיִּים. שֶׁהֵמִית, יִלְעָג:\",2,0],[2,122,9,24,\"בְּיַד רָשָׁע. כְּלַפֵּי שָׂטָן:\",1,0],[2,122,9,24,\"פְּנֵי שׁוֹפְטֶיהָ יְכַסֶּה. מֵהַבְחִין בְּדָבָר אֱמֶת:\",2,0],[2,122,9,24,\"וְאִם לֹא אֵפוֹא. דָּבָר אֱמֶת דָּבָר זֶה, מִי הוּא הַמְכַלֶּה אֶת הַתְּמִימִים?\",3,0],[2,122,9,25,\"וְיָמַי. עִם כִּלְיוֹן שְׁאָר הַתְּמִימִים, קַלּוּ מִנִּי רָץ:\",1,0],[2,122,9,26,\"אֵבֶה. שֵׁם נָהָר שׁוֹטֵף:\",1,0],[2,122,9,26,\"יָטוּשׂ. יִפְרַח:\",2,0],[2,122,9,27,\"שִׂיחִי. דִּבְרֵי צַעֲרִי:\",1,0],[2,122,9,27,\"פָּנַי. חֲמָתִי:\",2,0],[2,122,9,27,\"וְאַבְלִיגָה. אֶתְחַזֵּק, כְּמוֹ ״הַמַּבְלִיג שֹׁד עַל עָז״ (עמוס ה:ט):\",3,0],[2,122,9,28,\"יָגֹרְתִּי כָל עַצְּבוֹתָי. שֶׁלֹּא יַנִּיחוּנִי מִלִּצְעוֹק:\",1,0],[2,122,9,28,\"יָדַעְתִּי כִּי לֹא תְנַקֵּנִי. מֵעֲוֹנִי, מִלְּהִפָּרַע מִמֶּנִּי:\",2,0],[2,122,9,29,\"לָמָּה זֶּה הֶבֶל אִיגָע. לָבוֹא בְּמִשְׁפָּט:\",1,0],[2,122,9,30,\"בְּבוֹר. נִקָּיוֹן:\",1,0],[2,122,9,31,\"בַּשַּׁחַת תִּטְבְּלֵנִי. לִהְיוֹת צָחוֹן וּמְגֹאָל, כְּלוֹמַר: אָז תִּמְצָא לִי עָוֹן רַב:\",1,0],[2,122,9,32,\"בַּמִּשְׁפָּט. בְּדִבְרֵי תוֹכָחוֹת. מִשְׁפָּט מְשַׁמֵּשׁ שָׁלֹשׁ לְשׁוֹנוֹת: תְּחִלָּתוֹ הוֹכָחַת דְּבָרִים, אֶמְצָעִיתוֹ פְּסַק דִּין, וְסוֹפוֹ מִשְׁטַר יִסּוּרִין וְגִבּוּי חוֹב. וּפְעָמִים שֶׁהַמִּקְרָא כּוֹתְבוֹ עַל שֵׁם תְּחִלָּתוֹ, וּפְעָמִים עַל שֵׁם אֶמְצָעִיתוֹ, וּפְעָמִים עַל שֵׁם אַחֲרִיתוֹ:\",1,0],[2,122,9,33,\"מוֹכִיחַ. דְּרַשְׁנִי״ר בְּלַעַ״ז, מַרְאֶה לְכָל אֶחָד חוֹבָתוֹ וּזְכוּתוֹ:\",1,0],[2,122,9,33,\"יָשֵׁת יָדוֹ. מִשְׁטַר אֵימָתוֹ וְנִיגוּשׁוֹ:\",2,0],[2,122,9,33,\"עַל שְׁנֵינוּ. שֶׁלֹּא יְחַזֵּק הֶחָזָק אֶת הָרָפֶה:\",3,0],[2,122,9,35,\"כִּי לֹא כֵן אָנֹכִי. עַל כֵּן שֶׁאָנֹכִי יָרֵא, אֲנִי מֻחְזָק בִּי שֶׁלֹּא אֶתְחַיֵּב בַּדִּין:\",1,0],[2,122,10,1,\"נָקְטָה נַפְשִׁי. נַפְשִׁי מִתְקוֹטֶטֶת עַל שֶׁאֲנִי חַי, וְהוּא לְשׁוֹן ״וּנְקֹטֹתֶם בִּפְנֵיכֶם״ (יחזקאל כ:מג):\",1,0],[2,122,10,1,\"אֶעֶזְבָה עָלַי שִׂיחִי. צָרָתִי, לִזְעוֹק וְלִקְבּוֹל, וְלֹא אוּכַל לְשַׁבְּחוֹ וּלְהַבְלִיגוֹ:\",2,0],[2,122,10,3,\"הֲטוֹב. בִּתְמִיהַּ, כִּי תַעֲשֹׁק וְתִגְזֹל מִן הַצַּדִּיק אֶת צִדְקוֹ, וְעַל עֲצַת רְשָׁעִים וּמַקְנִיטִים הוֹפָעְתָּ זִיוְךָ, לְהַרְאוֹת לָהֶם פָּנִים שׂוֹחֲקוֹת?\",1,0],[2,122,10,5,\"הֲכִימֵי אֱנוֹשׁ יָמֶיךָ. לְהִתְגָּרוֹת בּוֹ וְלִרְדֹּף?\",1,0],[2,122,10,7,\"עַל דַּעְתְּךָ. יוֹדֵעַ אַתָּה:\",1,0],[2,122,10,8,\"עִצְּבוּנִי. עֲשָׂאוּנִי, עֶצֶב דְּפוּס כְּמוֹ אֵין מְעַצְּבִין אֶת הַקָּטָן (שבת קמו:). וְעַתָּה חֵילוֹתֶיךָ יַחַד סָבִיב:\",1,0],[2,122,10,8,\"וַתְּבַלְּעֵנִי. הֵם הַתּוֹלָעִים:\",2,0],[2,122,10,9,\"תְּשִׁיבֵנִי. לְבַסּוֹף:\",1,0],[2,122,10,10,\"כֶּחָלָב תַּתִּיכֵנִי. כְּטִפַּת תּוֹלְדוֹתַי:\",1,0],[2,122,10,12,\"וּפְקֻדָּתְךָ. פְּקֻדַּת מִשְׁמַרְתְּךָ, שֶׁמִּנִּיתָ לִי שׁוֹמְרִים:\",1,0],[2,122,10,12,\"שָׁמְרָה רוּחִי. בְּבֶטֶן אִמִּי, וְאַחַר כָּךְ:\",2,0],[2,122,10,13,\"וְאֵלֶּה צָפַנְתָּ בִלְבָבֶךָ. לְבַלְּעֵנִי, כְּאִלּוּ אֵין (אַתָּה) זוֹכְרָם:\",1,0],[2,122,10,13,\"יָדַעְתִּי כִּי זֹאת עִמָּךְ. הַכֹּל כַּמְפֹרָשׁ, וְלֹא שָׁכַחְתָּ:\",2,0],[2,122,10,14,\"אִם חָטָאתִי וּשְׁמַרְתָּנִי. נָתַתָּ עֵינֶיךָ בִּי מִלְּהַעְלִים וְלַעֲבוֹר עַל מִדּוֹתֶיךָ. (וּמֵעַתָּה) וּמֵעֲוֺנִי אֵין אַתָּה מְנַקֵּנִי, אֶלָּא עַל הַכֹּל אַתָּה פּוֹרֵעַ:\",1,0],[2,122,10,15,\"שְׂבַע קָלוֹן. אֲנִי:\",1,0],[2,122,10,15,\"וּרְאֵה עָנְיִי. אֵין זֶה צִוּוּי, אֶלָּא שֵׁם דָּבָר: רְאֵה עָנְיִי. בֶּדְנַ״ץ בְּלַעַ״ז; שֶׁכָּל שָׁעָה אֲנִי רוֹאֵהוּ. כְּמוֹ שֶׁאַתָּה אוֹמֵר ״וּשְׂבַע יָמִים״ (איוב מב:יז) – כְּמוֹ וְשָׂבֵעַ יָמִים, כֵּן תֹּאמַר וּרְאֵה – כְּמוֹ ׳וְרוֹאֶה עָנְיִי׳:\",2,0],[2,122,10,16,\"וְיִגְאֶה כַּשַּׁחַל תְּצוּדֵנִי. וְיִגְדַּל בְּעֵינֶיךָ לִהְיוֹת לְךָ לְמַשָּׂא וּלְפַח נֶפֶשׁ, אֶת אֲשֶׁר כַּשַּׁחַל תְּצוּדֵנִי אֲשֶׁר תִּפְרֹשׂ לִי מְצוּדָה, כְּאִלּוּ אֲנִי גִּבּוֹר כַּשַּׁחַל:\",1,0],[2,122,10,16,\"וְתָשֹׁב. מִיּוֹם אֶל יוֹם:\",2,0],[2,122,10,16,\"תִּתְפַּלָּא בִי. לְדַקְדֵּק וּלְהַפְלִיא בַּמִּשְׁפָּט, לְשׁוֹן ״כִּי יַפְלִא״ (במדבר ו:ב):\",3,0],[2,122,10,17,\"עֵדֶיךָ. לְהָעִיד עַל חֲלִיפַת הֶחֳלָאִים וּמַכְאוֹבִים:\",1,0],[2,122,10,17,\"וְצָבָא עִמִּי. זְמַנִּים קְצוּבִים לְיִסּוּרַי; אֵלּוּ מְשַׁמְּשִׁים (צבא א׳), וְחוֹזְרִים וּמִתְחַלְּפִים שִׁנּוּיִים מְשֻׁנִּים מֵאֵלֶּה, וּמְשַׁמְּשִׁין זְמַן אַחֵר:\",2,0],[2,122,10,18,\"אֶגְוַע וְעַיִן לֹא תִרְאֵנִי. הַלְוַאי אֶגְוַע מֵרֶחֶם:\",1,0],[2,122,10,19,\"אוּבָל. הַלְוַאי הָיִיתִי מוּבָל:\",1,0],[2,122,10,20,\"וְשִׁית מִמֶּנִּי. תָּשִׁית עַצְמְךָ מִמֶּנִּי וּמֵעָלַי, כְּמוֹ ״קְרַב אֵלֶיךָ״ (ישעיה סה:ה) – קְרַב לְעַצְמְךָ וּרְחַק מִמֶּנִּי:\",1,0],[2,122,10,21,\"בְּטֶרֶם אֵלֵךְ. בְּעוֹדֶנִּי חַי וְלֹא הִגִּיעַ עֵת מוֹתִי, הַנַּח לִי וְאַרְגִּיעַ:\",1,0],[2,122,10,22,\"עֵיפָתָה. שֵׁם דָּבָר, חֲשֵׁיכָה, כְּמוֹ ״שַׁחַר וְעֵיפָה״ (עמוס ד:יג):\",1,0],[2,122,10,22,\"צַלְמָוֶת. הִיא וְלֹא סְדָרִים בָּהּ (שֶׁאֵין שָׁם סִדְרֵי אָדָם כְּלוֹמַר מִנְהָגִים שֶׁאֵין שָׁם יִשּׁוּב וְאוֹר שֶׁלָּהּ כְּמוֹ אֹפֶל הוּא):\",2,0],[2,122,10,22,\"וַתֹּפַע כְּמוֹ אֹפֶל. מָקוֹם מוּפָע שֶׁבָּהּ, כְּמוֹ אֹפֶל הוּא:\",3,0],[2,122,11,2,\"(מענה צופר:) לֹא יֵעָנֶה. מֵאֲחֵרִים, מִפְּנֵי רֹב דְּבָרָיו:\",1,0],[2,122,11,3,\"בַּדֶּיךָ. שֶׁאַתָּה בּוֹדֶה מִלִּבְּךָ:\",1,0],[2,122,11,3,\"מְתִים יַחֲרִישׁוּ. בְּנֵי אָדָם:\",2,0],[2,122,11,4,\"וַתֹּאמֶר. לְהַקָּדוֹשׁ בָּרוּךְ הוּא: זַךְ לִקְחִי וּבַר הָיִיתִי בְעֵינֶיךָ:\",1,0],[2,122,11,6,\"תַּעֲלוּמוֹת חָכְמָה. וְתֵדַע, כִּי כִפְלַיִם לְתוּשִׁיָּה יֵשׁ לַתּוֹרָה, שֶׁלֹּא קִיַּמְתָּ:\",1,0],[2,122,11,6,\"כִּי יַשֶּׁה. כְּמוֹ ״כִּי תַשֶּׁה בְרֵעֲךָ״ (דברים כד:י), (כְּלוֹמַר) הַרְבֵּה יֵשׁ לוֹ עוֹד חוֹב עָלֶיךָ בְּדִבְרֵי עֲוֹנֶיךָ:\",2,0],[2,122,11,7,\"הַחֵקֶר אֱלוֹהַּ תִּמְצָא. שֶׁאַתָּה סָבוּר שֶׁקִּיַּמְתָּ הַכֹּל?\",1,0],[2,122,11,8,\"גָּבְהֵי שָׁמַיִם. דָּבָר שֶׁהוּא גָּבוֹהַּ כְּגָבְהֵי שָׁמַיִם, מַה תִּפְעָל עַתָּה? וַעֲמֻקָּה הִיא הַחָכְמָה מִשְּׁאוֹל:\",1,0],[2,122,11,9,\"מִדָּה. מִדּוּד שֶׁלָּהּ (ס״א מִדָּה שֶׁלָּהּ), וְכָאן הִזְכִּיר מִדּוּד בְּלָשׁוֹן זָכָר (שֶׁלֹּא אָמַר מִדָּתָהּ):\",1,0],[2,122,11,10,\"אִם יַחֲלֹף וְיַסְגִּיר. בְּיִסּוּרִין אֶת מִי שֶׁיִּרְצֶה:\",1,0],[2,122,11,10,\"וְיַקְהִיל. כָּל פַּמַלְיָאוֹת שֶׁלּוֹ, לְוַכֵּחַ עַל שֶׁהִסְגִּיר:\",2,0],[2,122,11,10,\"וּמִי. בָּהֶן יְשִׁיבֶנּוּ בִּדְבָרִים, לִמְצֹא עָוֶל בְּפָעֳלוֹ? וְאִם מִפְּנֵי שֶׁהַנִּדּוֹן שָׁלֵו וְשָׁקֵט יָמִים רַבִּים, כֵּן דַּרְכּוֹ:\",3,0],[2,122,11,11,\"כִּי הוּא יָדַע מְתֵי שָׁוְא וַיַּרְא אָוֶן וְלֹא יִתְבּוֹנָן. שֶׁהֵם עוֹשִׂים יָמִים וְשָׁנִים, וְדוֹמֶה כְּמִי שֶׁלֹּא יִתְבּוֹנֵן (יִתְבּוֹנְנוּ), כִּי מַאֲרִיךְ אַפּוֹ:\",1,0],[2,122,11,12,\"וְאִישׁ נָבוּב. חָלוּל, בְּלֹא לֵב, אֲשֶׁר לֹא הֵבִין דַּרְכּוֹ:\",1,0],[2,122,11,12,\"יִלָּבֵב. יִקְנֶה לוֹ לֵב, לָשׁוּב לְבוֹרְאוֹ וּלְפַשְׁפֵּשׁ בְּמַעֲשָׂיו. אוֹ אָדָם אֲשֶׁר הָיָה כְּעַיִר פֶּרֶא ״לִמֻּד מִדְבָּר״ (ירמיה ב:כד), קַל בְּלֹא דַעַת:\",2,0],[2,122,11,12,\"אָדָם יִוָּלֵד. יְלַמֵּד עַצְמוֹ לִהְיוֹת אָדָם חָדָשׁ, כְּסֵדֶר בְּנֵי אָדָם, וִיכַוֵּן דַּרְכּוֹ:\",3,0],[2,122,11,13,\"אִם אַתָּה. הָיִיתָ מְכַוֵּן לִבְּךָ אַחַר יִסּוּרִין:\",1,0],[2,122,11,13,\"וּפָרַשְׂתָּ אֵלָיו כַּפֶּיךָ. בִּתְחִנָּה:\",2,0],[2,122,11,14,\"וְתַרְחֵק אָוֶן מִיָּדְךָ, וְאַל תַּשְׁכֵּן בְּאֹהָלֶיךָ עַוְלָה:\",1,0],[2,122,11,15,\"כִּי אָז. אִם אַתָּה הָיִיתָ בָּטוּחַ שֶׁתִּשָּׂא פָנֶיךָ מִמּוּם שֶׁתִּגְרֹם לְעַצְמְךָ לָשֵׂאת פָנֶיךָ מִכָּל מוּם (מִתּוֹךְ כָּךְ):\",1,0],[2,122,11,15,\"וְהָיִיתָ מֻצָּק. חָזָק, כְּמוֹ ״מְצוּקֵי אֶרֶץ״ (שמואל א ב:ח):\",2,0],[2,122,11,16,\"עָמָל תִּשְׁכָּח. וְכָל עָמָל הָיִיתָ שׁוֹכֵחַ:\",1,0],[2,122,11,16,\"וּכְּמַיִם עָבְרוּ. וְחָלְפוּ, כֵּן יִהְיֶה לְךָ כָּל זִכְרוֹן עָמָל:\",2,0],[2,122,11,17,\"וּמִצָּהֳרַיִם יָקוּם חָלֶד. יוֹתֵר מֵאוֹר צָהֳרַיִם יָקוּם לְךָ חֶלֶד – מַזָּל וּזְמַן, כְּמוֹ ״וְחֶלְדִּי כְאַיִן נֶגְדֶּךָ״ (תהילים לט:ו). דָּבָר אַחֵר: יָקוּם חָלֶד כְּמוֹ יָקוּם אוֹר חֲלוּדָה שֶׁלְּךָ, כְּלוֹמַר: שֶׁיִּהְיֶה מְקוֹם אֲפֵלָה מֵאִיר יוֹתֵר מֵאוֹר צָהֳרַיִם. זוֹ שָׁמַעְתִּי, אֲבָל הָרִאשׁוֹן לֹא נִרְאֶה (סא״א):\",1,0],[2,122,11,17,\"תָּעֻפָה. אֲפֵלָה שֶׁלְּךָ כַּבֹּקֶר תִּהְיֶה. עִנְיָן אַחֵר: תָּעֻפָה לְשׁוֹן ״עַפְעַפֵּי שַׁחַר״ (איוב ג:ט), שֶׁאִם הוּא לְשׁוֹן אֹפֶל, הָיָה לוֹ לוֹמַר: ׳תְּעוּפָה׳, נָקוּד בִּשְׁוָ״א, כְּמוֹ ״תְּנוּפָה״ (שמות כט:כד), ״תְּקוּמָה״ (ויקרא כו:לז), ״תְּרוּמָה״ (שמות כה:ב), ״תְּנוּמָה״ (תהלים קלב:ד):\",2,0],[2,122,11,20,\"וְעֵינֵי רְשָׁעִים. שׂוֹנְאֶיךָ:\",1,0],[2,122,11,20,\"תִּכְלֶינָה. בִּפְנוֹתָם בְּרָעָתְךָ לִרְאוֹת, וְלֹא יַשִּׂיגוּ (תַּאֲוָתָם). וְכָל ׳כִּלְיוֹן עֵינַיִם׳ שֶׁבִּלְשׁוֹן קֹדֶשׁ, זֶהוּ הַמְּצַפֶּה לִרְאוֹת וְאֵינוֹ מַשִּׂיג, וּכְמוֹ ״וְעֵינֶיךָ רֹאוֹת וְכָלוֹת אֲלֵיהֶם וְגוֹ׳״ (דברים כח:לב):\",2,0],[2,122,11,20,\"וּמָנוֹס. הוּא מִבְטָח:\",3,0],[2,122,11,20,\"וְתִקְוָתָם. מַה שֶּׁהֵם מְקַוִּים לִרְאוֹת בְּךָ, לְמַפַּח נֶפֶשׁ יִהְיֶה לָהֶם:\",4,0],[2,122,12,2,\"(מענה איוב:) תָּמוּת חָכְמָה. כְּשֶׁתָּמוּתוּ, תָּמוּת עִמָּכֶם כָּל חָכְמָה, כִּי כָל חָכְמָה בָּכֶם. אֲבָל:\",1,0],[2,122,12,3,\"גַּם לִי לֵבָב כְּמוֹכֶם. וְאֶת מִי אֵין כְּמוֹ אֵלֶּה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שַׁלִּיט לַעֲשׂוֹת רְצוֹנוֹ וּלְהַאֲרִיךְ שַׁלְוַת רְשָׁעִים? אֵינְכֶם אֶלָּא כִּמְשַׂחֲקִים בִּי, וַאֲנִי הוּא (הַהוֹוֶה) שְׂחוֹק לְרֵעֵהוּ:\",1,0],[2,122,12,4,\"אֶהְיֶה קוֹרֵא לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וַיַּעֲנֵהוּ מִצַּעַר הַקְנָטַתְכֶם. וּמָה יַעֲנֵהוּ? לָתֵת לוֹ שְׂחוֹק לְצַדִּיק וְתָמִים. שָׁלֵם:\",1,0],[2,122,12,4,\"שְׂחוֹק צַדִּיק תָּמִים. הִיא הָעֲנִיָּה אֲשֶׁר יַעֲנֵהוּ. יָדַעְתִּי אֲנִי כַּאֲשֶׁר אֲמַרְתֶּם, כִּי:\",2,0],[2,122,12,5,\"לַפִּיד בּוּז. אֵשׁ שֶׁל גֵּיהִנֹּם עוֹמֵד לְמִי שֶׁשַּׁאֲנָן בְּעַשְׁתּוּתוֹ, לוֹמַר: ״שָׁלוֹם יִהְיֶה לִי״ (דברים כט:יח):\",1,0],[2,122,12,5,\"נָכוֹן. מְזֻמָּן הוּא הָעַשְׁתּוֹת שַׁאֲנָן, לִהְיוֹת בְּמוֹעֲדֵי רֶגֶל – שֶׁרַגְלָם מוֹעֶדֶת:\",2,0],[2,122,12,6,\"יִשְׁלָיוּ. יָדַעְתִּי אֲנִי, כִּי יְמֵי יִשְׁלָיוּ אֹהָלִים לִבְנֵי קֵדָר הַשּׁוֹכְנִים בָּאֹהָלִים הַמִּדְבָּרָה, וְהֵם שׁוֹדְדִים, שֶׁנֶּאֱמַר ״פֶּרֶא אָדָם יָדוֹ בַכֹּל״ (בראשית טז:יב):\",1,0],[2,122,12,6,\"וּבַטֻּחוֹת. שְׁלֵמוּת יֵשׁ לְמַרְגִּיזֵי אֵל, לְכָל אֲשֶׁר הֵבִיא לוֹ הַצּוּר הַשָּׁלוֹם בְּיָדוֹ, אִם טוֹב וְאִם רַע:\",2,0],[2,122,12,11,\"הֲלֹא אֹזֶן מִלִּין תִּבְחָן. וְלָמָּה לֹא יָדְעוּ זֹאת הַשּׁוֹמְעִים פָּעֳלוֹ, כַּאֲשֶׁר הַחֵךְ יִטְעַם לֶאֱכֹל?\",1,0],[2,122,12,12,\"בִּישִׁישִׁים חָכְמָה וְגוֹ׳. לָדַעַת כִּי עִמּוֹ חָכְמָה וְגוֹ׳:\",1,0],[2,122,12,15,\"וִישַׁלְּחֵם וְיַהַפְכוּ אָרֶץ. בִּשְׁלִיחוּתוֹ, כַּאֲשֶׁר עָשָׂה לְדוֹר אֱנוֹשׁ, שֶׁהֵצִיף שְׁלִישׁוֹ שֶׁל עוֹלָם (מכילתא דרבי ישמעאל יתרו ו):\",1,0],[2,122,12,16,\"לוֹ שׁוֹגֵג. הָאָדָם הַשּׁוֹגֵג:\",1,0],[2,122,12,16,\"וּמַשְׁגֶּה. שָׂטָן הַמַּשְׁגֵּהוּ:\",2,0],[2,122,12,17,\"שׁוֹלָל. שֵׁם דָּבָר הוּא שְׁטוּת, מוֹלִיכָם בִּשְׁטוּת כְּשֶׁהוּא רוֹצֶה לְעַרְבֵּב וּלְבַלֵּעַ חָכְמָתָם, כְּמוֹ ״וְסָר מֵרָע מִשְׁתּוֹלֵל״ (ישעיהו נט:טו), ״אֶשְׁתּוֹלְלוּ אַבִּירֵי לֵב״ (תהלים עו:ו). וְתָ״ו אֲשֶׁר בְּ״מִשְׁתּוֹלֵל״ וְ״אֶשְׁתּוֹלְלוּ״ – כֵּן דֶּרֶךְ לְשׁוֹן עִבְרִית בְּתֵיבָה שֶׁיְּסוֹדָהּ שִׁי״ן אוֹ סָמֶ״ךְ, וְהוּא בָּא לְדַבֵּר בִּלְשׁוֹן נַעֲשָׂה וְנִפְעַל אוֹ מִתְפַּעֵל, נוֹתֵן תָּ״ו אַחַר אוֹת רִאשׁוֹנָה שֶׁל יְסוֹד, כְּמוֹ ״וְיִשְׁתַּכְּחוּ בָעִיר״ (קהלת ח:י), ״וְיִשְׁתַּמֵּר חֻקּוֹת עָמְרִי״ (מיכה ו:טז), ״מִסְתּוֹלֵל בְּעַמִּי״ (שמות ט:יז), ״וְיִסְתַּבֵּל הֶחָגָב״ (קהלת יב:ה):\",1,0],[2,122,12,17,\"יְהוֹלֵל. יְשׁוּטֶה, לְשׁוֹן ״הוֹלְלוּת וְסִכְלוּת״ (קהלת ב:יב):\",2,0],[2,122,12,18,\"מוּסַר מְלָכִים פִּתֵּחַ. לְהָסִיר מוּסַר סִבְלָם מֵעַל אֲחֵרִים, וּמַעֲבִירָם מִמְּלוּכָה:\",1,0],[2,122,12,18,\"וַיֶּאְסֹר אֵזוֹר בְּמָתְנֵיהֶם. בִּתְחִלָּתָם, כְּשֶׁהוּא חָפֵץ בָּהֶם, חוֹגֵר חֲלָצֵיהֶם וּמְזָרְזָם כֹּחַ לַמְּלוּכָה:\",2,0],[2,122,12,19,\"כֹּהֲנִים. שָׂרִים, כְּמוֹ ״כֹּהֵן מִדְיָן״ (שמות ג:א), ״כֹּהֵן אוֹן״ (בראשית מא:מה):\",1,0],[2,122,12,20,\"לְנֶאֱמָנִים. אַף לְנֶאֱמָנִים, כִּי פְּעָמִים שְׂפָתָיו נִבְלָלִים לְדַבֵּר סָרָה, כְּגוֹן אַבְרָהָם: ״וְהֶאֱמִין בַּה׳״ (בראשית טו:ו), וְסוֹף נִכְשַׁל: ״בַּמָּה אֵדַע״ (בראשית טו:ח):\",1,0],[2,122,12,21,\"וּמְזִיחַ אֲפִיקִים רִפָּה. וַחֲגוֹר הַחֲזָקִים מְרַפֶּה, וּמְפַתֵּחַ חֲגוֹרָם לְהָתִישׁ כֹּחָם, כְּמוֹ (תהלים קט:יט) ״וּלְמֵזַח תָּמִיד יַחְגְּרֶהָ״:\",1,0],[2,122,12,21,\"אֲפִיקִים. חֲזָקִים, כְּמוֹ ״אֲפִיקֵי נְחוּשָׁה״ (איוב מ:יח); ״אֲפִיקֵי מָגִנִּים״ (איוב מא:ז):\",2,0],[2,122,12,23,\"מַשְׂגִּיא לַגּוֹיִם וַיְאַבְּדֵם. יֵשׁ אוֹמְרִים: כַּאֲשֶׁר עָשָׂה לְמִצְרַיִם, בְּהַשִּׂיגָם אֶת יִשְׂרָאֵל ״לִפְנֵי בַּעַל צְפוֹן״ (שמות יד:ט), שָׁגוּ וְאָמְרוּ: תֵּדְעוּ, שֶׁהִסְכִּים עִמָּנוּ לְטַבְּעָם בַּיָּם, כַּאֲשֶׁר גָּזַרְנוּ ״כָּל הַבֵּן הַיִּלּוֹד הַיְאֹרָה תַּשְׁלִיכֻהוּ״ (שמות א:כב); וְקָשָׁה יִרְאָתוֹ שֶׁל בַּעַל צְפוֹן, שֶׁלֹּא נַעֲשׂוּ בּוֹ שְׁפָטִים כְּכָל אֱלֹהֵי מִצְרַיִם. וְגָרַם הַמָּקוֹם לְהַשְׁגּוֹתָם, כְּדֵי לְטַבְּעָם. וְזֶה הַלָּשׁוֹן אֵינוֹ עִקָּר; דְּאִם כֵּן הָיָה לוֹ לוֹמַר בְּצַד יָמִין ׳מַשְׁגִּיא׳, כְּמוֹ ״שׁוֹגֶה״ (משלי כ:א). אֲבָל זֶה עִקָּר ׳מַגְדִּיל׳, לְשׁוֹן ״שַׂגִּיא כֹחַ״ (איוב לז:כג): מַשְׂגִּיא אֶת הַגּוֹיִם וּמַצְלִיחָם, וְלִבָּם מִתְגָּאֶה בְּהַצְלָחָתָם, וְהוּא הָיָה אָבְדָן שֶׁלָּהֶן – מַה שֶּׁהִצְלִיחוּ:\",1,0],[2,122,12,23,\"שׁוֹטֵחַ. מַרְבֶּה אוֹתָם, לְהַשְׁטִיחַ בָּאָרֶץ וּלְכַסּוֹתָם:\",2,0],[2,122,12,24,\"בְּתֹהוּ לֹא דָרֶךְ. בְּתֹהוּ שֶׁאֵינוֹ דֶרֶךְ:\",1,0],[2,122,13,3,\"אוּלָם אֲנִי. אֵינִי מְבַקֵּשׁ אֶלָּא לְדַבֵּר אֵלָיו, וּלְהִתְוַכֵּחַ עִמּוֹ אֶחְפָּץ:\",1,0],[2,122,13,4,\"טוֹפְלֵי שָׁקֶר. מְחַבְּרֵי דִּבְרֵי שֶׁקֶר:\",1,0],[2,122,13,4,\"רוֹפְאֵי אֱלִיל כֻּלְּכֶם. כָּל אֱלִיל שֶׁבַּמִּקְרָא לְשׁוֹן אַל. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (חולין קכא.): זֶה גִּיד הַצַּוָּאר, שֶׁאֵין לוֹ רְפוּאָה, וּשְׁמוֹ אֱלָל:\",2,0],[2,122,13,6,\"וְרִיבוֹת. הוֹכָחוֹת:\",1,0],[2,122,13,7,\"הֲלָאֵל תְּדַבְּרוּ עַוְלָה. אַחֲרֵי אֲשֶׁר תַּחַת אֵל בָּאתֶם לָרִיב, לֹא טוֹב שֶׁתְּדַבְּרוּ עַוְלָה:\",1,0],[2,122,13,7,\"וְלוֹ תְּדַבְּרוּ רְמִיָּה. בַּעֲבוּרוֹ תְּדַבְּרוּ רְמִיָּה, כְּמוֹ ״הֵן אֲנִי כְפִיךָ לָאֵל״ (איוב לג:ו), וּכְמוֹ ״אֶל הָאָרֶץ אֲשֶׁר דִּבֶּר לָהֶם״ (דברים ט:כח) – לְצָרְכָם, וּכְמוֹ ״יִלָּחֵם לָכֶם״ (שמות יד:יד); ״הַאַתֶּם תְּרִיבוּן לַבַּעַל״ (שופטים ו:לא). הֻקְשָׁה בְּעֵינַי לְדַמּוֹתוֹ כָּאן, וְהוּא דֻּגְמַת ״בְּיַד מֹשֶׁה לוֹ״ – עַל קֹרַח (במדבר יז:ה):\",2,0],[2,122,13,8,\"הֲפָנָיו תִּשָּׂאוּן. וְכִי לְהַחֲנִיף לוֹ בִּשְׂאֵת פָּנִים בָּאתֶם?\",1,0],[2,122,13,8,\"אִם לָאֵל. בִּשְׁבִילוֹ תִּתְוַוּכְחוּן עַל רְמִיָּה?\",2,0],[2,122,13,9,\"הֲטוֹב כִּי יַחְקֹר אֶתְכֶם. וְתִמָּצְאוּ שְׁקָרִים?\",1,0],[2,122,13,9,\"אִם כְּהָתֵל בֶּאֱנוֹשׁ תְּהָתֵלּוּ בוֹ. לוֹמַר: לִכְבוֹדְךָ עָשִׂינוּ עַצְמֵינוּ שְׁקָרִים?\",2,0],[2,122,13,10,\"הוֹכֵחַ יוֹכִיחַ אֶתְכֶם. הֲלֹא יוֹדִיעַ לָכֶם דִּבַּתְכֶם?\",1,0],[2,122,13,10,\"אִם בַּסֵּתֶר. וְכִי בַּסֵּתֶר שֶׁתַּעַמְדוּ לְפָנָיו בַּדִּין, פָּנִים תִּשָּׂאוּ לוֹ, לוֹמַר: שָׁם נָשָׂאנוּ פָנֶיךָ?!\",2,0],[2,122,13,11,\"הֲלֹא שְׂאֵתוֹ. גָּבְהוֹ וְאֵימָתוֹ תְּבַעֵת אֶתְכֶם. וְיֵשׁ אוֹמְרִים: שְׂאֵתוֹ שְׂרֵפַת אֵשׁוֹ, כְּמוֹ ״וַיִּשָּׂאֵם דָּוִד וַאֲנָשָׁיו״ (שמואל ב ה:כא), וּכְמוֹ ״מַשְׂאַת הָעִיר״ (שופטים כ:לח):\",1,0],[2,122,13,12,\"זִכְרֹנֵיכֶם. נִמְשַׁל מִשְׁלֵי אֵפֶר זִכְרֹנֵיכֶם נִמְשַׁל לְאֵפֶר, אַתֶּם סְבוּרִים לְהִתְמַשֵּׁל לְאַבְרָהָם שֶׁאָמַר ״אָנֹכִי עָפָר וָאֵפֶר״ (בראשית יח:כז):\",1,0],[2,122,13,12,\"לְגַבֵּי חֹמֶר. שָׁוֶה לֶעָפָר יְהִי גַבֵּיכֶם אֶצְלוֹ. גַּבֵּיכֶם. גֹּבַהּ שֶׁלָּכֶם, כְּמוֹ ״וַתִּבְנִי לָךְ גָּב״ (יחזקאל טז:כד):\",2,0],[2,122,13,13,\"וְיַעֲבֹר עָלַי מָה. מַה שֶּׁיַּעֲבֹר עָלַי בַּעֲוֹן צַעֲקָתִי יַעֲבֹר עָלַי, וְאַל תָּחוּשׁוּ עַל מָה אֲנִי צָרִיךְ לָשֵׂאת וְלֶאֱחֹז:\",1,0],[2,122,13,14,\"בְּשָׂרִי בְשִׁנָּי. לְיַסְּרֵנִי וּלְכוֹפֵנִי אֶל הַשְּׁתִיקָה:\",1,0],[2,122,13,14,\"וְנַפְשִׁי אָשִׂים בְּכַפִּי. לְהַגִּישׁ נַפְשִׁי לַמָּוֶת בְּיִסּוּרֵי שְׁתִיקָה:\",2,0],[2,122,13,15,\"הֵן יִקְטְלֵנִי. הֲלֹא אִם יִקְטְלֵנִי, אֵינִי נִפְרָד מִמֶּנּוּ, וְתָמִיד לוֹ אֲיַיחֵל; עַל כֵּן אֵין מֶרֶד וָפֶשַׁע בִּדְבָרַי:\",1,0],[2,122,13,15,\"אַךְ דְּרָכַי. וּמִדּוֹתַי שֶׁנָּהַגְתִּי בָּהֶם:\",2,0],[2,122,13,15,\"אֶל פָּנָיו אוֹכִיחַ. לָדַעַת מַה יַּפְשִׁיעֵנִי:\",3,0],[2,122,13,16,\"גַּם הוּא. וְכַאֲשֶׁר אֲנִי שָׁלֵם עִמּוֹ, כֵּן הוּא גַּם הוּא לִי לִישׁוּעָה. וְלֹא תִמְצְאוּ אַתֶּם חֵן בְּעֵינָיו:\",1,0],[2,122,13,16,\"כִּי לֹא לְפָנָיו חָנֵף יָבוֹא. וְזֶה שֶׁנֶּאֱמַר לָהֶם: ״כִּי לֹא דִבַּרְתֶּם אֵלַי נְכוֹנָה״ (איוב מב:ז):\",2,0],[2,122,13,18,\"עָרַכְתִּי מִשְׁפָּט. הוֹכָחַת דְּבָרִים; סִדַּרְתִּי טַעֲנוֹתַי בְּלִבִּי, מַה לְהָשִׁיב:\",1,0],[2,122,13,19,\"אַחֲרִישׁ וְאֶגְוָע. אִם לֹא אָרִיב, אַחֲרִישׁ וְאֶגְוָע:\",1,0],[2,122,13,20,\"אַךְ שְׁתַּיִם אַל תַּעַשׂ עִמָּדִי. דִּין שֶׁל מַעְלָה וְדִין שֶׁל מַטָּה. וְאִם בְּאַחַת תָּבוֹא לְמִשְׁפָּט, אָז מִפָּנֶיךָ לֹא אֶסָּתֵר. אִם בְּדִין שֶׁל מַעְלָה, אֲנִי אוֹמֵר: חָטָאתִי, ״מְכַסֶּה פְשָׁעָיו לֹא יַצְלִיחַ וְגוֹ׳״ (משלי כח:יג); וְאִם בְּדִין שֶׁל מַטָּה, אַף אָנֹכִי לֹא אוֹדֶה: כִּסּוּי חֲטָאָה לָשׁוֹן שֶׁקֶר (תהלים לב:א; קט:ב) (סא״א):\",1,0],[2,122,13,21,\"כַּפְּךָ מֵעָלַי הַרְחַק. כְּפִיָּתְךָ, כְּמוֹ שֶׁהֵשִׁיבוֹ אֱלִיהוּא ״וְאַכְפִּי עָלֶיךָ לֹא יִכְבָּד״ (איוב לג:ז). וְיֵשׁ פּוֹתְרִים כַּפְּךָ – כְּלוֹמַר: יָדְךָ, וְקָשֶׁה לִי לְאוֹמְרוֹ, כִּי לֹא מָצִינוּ ׳כַּף׳ לְרָעָה, כִּי אִם לְהָגֵן, כְּמוֹ ״וְשַׂכֹּתִי כַפִּי״ (שמות לג:כב):\",1,0],[2,122,13,24,\"פָּנֶיךָ תַסְתִּיר. לִרְאוֹת אֶת דַּרְכֵי יָשְׁרִי:\",1,0],[2,122,13,25,\"תַּעֲרוֹץ. תְּפַחִיד:\",1,0],[2,122,13,26,\"מְרוֹרוֹת. סַרְבָנִיּוֹת אֲשֶׁר מָרִיתִי פִּיךָ אַתָּה כּוֹתֵב, וְלֹא הַטּוֹבוֹת שֶׁפָּעַלְתִּי:\",1,0],[2,122,13,27,\"בַּסַּד. בִּלְשׁוֹן אֲרַמִּי ״סַדְנָא בְּסַדְנֵיהּ יָתִיב״ (פסחים כח.) – עֵץ גָּדוֹל שֶׁנּוֹתְנִין בּוֹ רַגְלֵי הָאֲסוּרִים, וּבִלְשׁוֹן יְוָנִי ״אַשְׁתּוֹ״ק״:\",1,0],[2,122,13,27,\"תִּתְחַקֶּה. אַתָּה עַצְמְךָ מִתְחַקֶּה עַל פְּסִיעוֹתַי: כֵּן פָּסַע זֶה, וְכֹה פָּעַל. וּכְמוֹ ״מֵחֵיק הָאָרֶץ״ (יחזקאל מג:יד); ״וְחֵיק הָאַמָּה״ (יחזקאל מג:יג). זֶה הַיְסוֹד אפיקיו״ל בְּלַעַ״ז; ״הֵן עַל כַּפַּיִם חַקֹּתִיךְ״ (ישעיהו מט:טז):\",2,0],[2,122,13,28,\"וְהוּא כְּרָקָב יִבְלֶה. הַגּוּף הַזֶּה אֲשֶׁר תִּרְדֹּף, יֵרָקֵב וְיִבְלֶה, וְאֵין כְּבוֹדְךָ בִּרְדִיפָתְךָ:\",1,0],[2,122,14,3,\"אַף עַל זֶה. הַהֶבֶל וְהַנִּרְקָב:\",1,0],[2,122,14,3,\"פָּקַחְתָּ עֵינֶיךָ. לְדַקְדֵּק בַּחֲטָאָיו:\",2,0],[2,122,14,3,\"וְאוֹתִי. אַתָּה מֵבִיא בְמִשְׁפָּט עַל עֲווֹנוֹתַי:\",3,0],[2,122,14,4,\"מִי יִתֵּן טָהוֹר. מִדְּבַר טִפָּה סְרוּחָה וְשִׁכְבַת זֶרַע שֶׁהוּא טָמֵא. לֹא אֶחָד בָּהֶם טָהוֹר, שֶׁלֹּא יֶחֱטָא:\",1,0],[2,122,14,5,\"אִם חֲרוּצִים יָמָיו. אִם גְּמוּל זֶה הוּא מִשְׁתַּלֵּם, שֶׁחֲרוּצִים וּקְצוּבִים לְיוֹם קָבוּעַ וּמְיֻעָד לְמִיתָה:\",1,0],[2,122,14,5,\"וּמִסְפַּר חֳדָשָׁיו אִתָּךְ. קְצוּבִים, וְחֹק זֶה עָשִׂיתָ לוֹ וְלֹא יִתְקַיֵּם עוֹד יוֹתֵר בָּעוֹלָם – דַּי לְךָ בַּתַּשְׁלוּמִין הַלָּלוּ:\",2,0],[2,122,14,6,\"שְׁעֵה מֵעָלָיו. בְּאוֹתוֹ מִעוּט חָרַץ הַיָּמִים, וְיֶחְדַּל לוֹ מִמַּכְאוֹב, עַד יִרְצֶה בְּזִקְנוּתוֹ וְתַשּׁוּת כֹּחוֹ אֶת יוֹם מוֹתוֹ כְּשָׂכִיר הָרוֹצֶה לְהַשְׁלָמַת עֲבוֹדַת יוֹמוֹ. כִּי עֲבִירָתוֹ מִן הָעוֹלָם חֲלוּטָה וְנִצְמֶתֶת מִשְּׁאָר כָּל הָעוֹבְרִים:\",1,0],[2,122,14,7,\"כִּי יֵשׁ לָעֵץ תִּקְוָה. שֶׁיַּחֲלֹף:\",1,0],[2,122,14,7,\"וְיֹנַקְתּוֹ. אֲשֶׁר מִגִּזְעוֹ לֹא תֶחְדָּל מִהְיוֹת עָנָף:\",2,0],[2,122,14,9,\"וְעָשָׂה קָצִיר. הִיא יוֹנֶקֶת, כְּמוֹ ״תְּשַׁלַּח קְצִירֶיהָ עַד יָם״ (תהילים פ:יב):\",1,0],[2,122,14,9,\"נָטַע. שֵׁם דָּבָר הוּא, וְטַעַם הֲבָרָתוֹ לְמַעְלָה בַּנּוּ״ן, וְנִנְקַד כֻּלּוֹ קָמַץ מִפְּנֵי שֶׁהוּא סוֹף פָּסוּק. אַף מִגִּזְרַת ״נָטַע״ (ישעיה מד:יד) הוּא:\",2,0],[2,122,14,11,\"אָזְלוּ מַיִם מִנִּי יָם. מִמָּקוֹם שֶׁנָּהָר בָּא וְיוֹצֵא מִמְּקוֹרוֹ, הַבָּא מֵאֵלָיו מִן הַיָּם:\",1,0],[2,122,14,11,\"וְהַנָּהָר. הַבָּא מִשָּׁם יֶחֱרַב וְיִיבַשׁ לְעוֹלָם, כֵּן אִישׁ שָׁכַב וְלֹא יָקוּם:\",2,0],[2,122,14,14,\"כָּל־יְמֵי צְבָאִי אֲיַחֵל. לִתְחִיָּה:\",1,0],[2,122,14,15,\"תִּקְרָא. תְּחִנָּה הִיא: קְרָא אֵלַי וְאָנֹכִי אֶעֱנֶךָּ לְהוֹכִיחַ דְּבָרַי:\",1,0],[2,122,14,15,\"תִּכְסֹף. תַּחְמֹד:\",2,0],[2,122,14,16,\"כִּי עַתָּה. אַתָּה מֵרֵיעַ לִי:\",1,0],[2,122,14,16,\"צְעָדַי. אַתָּה סוֹפֵר:\",2,0],[2,122,14,16,\"לֹא תִשְׁמוֹר. אֵינְךָ מַמְתִּין עַל חַטָּאתִי מִלְּהִפָּרַע, כְּמוֹ ״וְאָבִיו שָׁמַר אֶת הַדָּבָר״ (בראשית לז:יא) – הִמְתִּין שֶׁתִּתְקַיֵּם. וּבִלְשׁוֹן מִשְׁנָה (סנהדרין סג:): לֹא יֹאמַר אָדָם לַחֲבֵרוֹ שְׁמוֹר לִי בְּצַד עֲבוֹדַת כּוֹכָבִים פְּלוֹנִית – לְשׁוֹן ״הַמְתֵּן״:\",3,0],[2,122,14,17,\"חָתוּם בִּצְרוֹר. חָתוּם וּמְשֻׁמָּר בִּצְרוֹר בֶּגֶד, כְּכֶסֶף וּמַרְגָּלִיּוֹת, שֶׁלֹּא תֹּאבַד:\",1,0],[2,122,14,17,\"וַתִּטְפֹּל עַל עֲוֺנִי. נִתְחַבַּרְתָּ עַל עֲוֺנִי:\",2,0],[2,122,14,18,\"וְאוּלָם הַר נוֹפֵל. הַר הַנּוֹפֵל גָּבְהוֹ יִבּוֹל וְיֵעָשֶׂה עָפָר, וּתְהֵא לוֹ תִּקְוָה לֵיהָנוֹת מִמֶּנּוּ. וְצוּר אֲשֶׁר נֶעְתַּק מִמְּקוֹמוֹ גַּם הוּא, יִבּוֹל לְשׁוֹן תְּבוּאָה. אוֹ:\",1,0],[2,122,14,19,\"אֲבָנִים. אֲשֶׁר שָׁחֲקוּ מַיִם בְּעָבְרָם עֲלֵיהֶם תָּמִיד:\",1,0],[2,122,14,19,\"תִּשְׁטֹף. הִשְׁטִיפוּ סְפִיחֶיהָ שֶׁל אֶבֶן לֵיהָפֵךְ לְעָפָר וְלִצְמֹחַ בּוֹ דָּבָר, כַּאֲשֶׁר יִצְמַח סְפִיחַ הַקָּצִיר שֶׁעָבַר – כֵּן יִתְהַפֵּךְ עָפָר זֶה סְפִיחֶיהָ לְאֶבֶן:\",2,0],[2,122,14,19,\"וְתִקְוַת אֱנוֹשׁ. אֵינָהּ כֵּן, אֲשֶׁר מִשֶּׁיָּמוּת – אָבְדָה סֶלָה:\",3,0],[2,122,14,20,\"תִּתְקְפֵהוּ. תֶּחֱזַק מִמֶּנּוּ וְתֶאֱנְסֵהוּ בְּתָקְפְּךָ, וַיַּהֲלֹךְ מִן הָעוֹלָם:\",1,0],[2,122,14,21,\"יִכְבְּדוּ. יִהְיוּ כְבֵדִים בְּכֶסֶף וּבְזָהָב, וְהוּא לֹא יֵדָע:\",1,0],[2,122,14,21,\"וְיִצְעֲרוּ. וְיִמְעֲטוּ מִכָּל טוֹב, וְהוּא לֹא יָבִין:\",2,0],[2,122,14,22,\"אַךְ בְּשָׂרוֹ עָלָיו יִכְאָב. קָשָׁה רִמָּה לַמֵּת כְּמַחַט בַּבָּשָׂר הֶחָי (שבת יג:):\",1,0],[2,122,15,2,\"(מענה אליפז): הֶחָכָם יַעֲנֶה דַעַת רוּחַ. תָּמוּהַּ הוּא, וְכִי מִי שֶׁהוּא חָכָם יַעֲנֶה וְיָרִים קוֹל בְּדַעַת שֶׁל רוּחַ וְהֶבֶל?\",1,0],[2,122,15,3,\"הוֹכֵחַ בְּדָבָר לֹא יִסְכּוֹן. לְהִתְוַכֵּחַ בְּדָבָר שֶׁלֹּא תְּהֵא לוֹ מֵהֶן הֲנָאָה, כְּמוֹ ״וַתְּהִי לוֹ סֹכֶנֶת״ (מלכים א א:ב), וּכְמוֹ ״יִסָּכֵן בָּם״ (קהלת י:ט) – יֵהָנֶה בָּם:\",1,0],[2,122,15,4,\"אַף אַתָּה. כָּל שֶׁכֵּן אַתָּה, שֶׁחָכָם מְאֹד, אַתָּה תָּפֵר יִרְאָה בְּמַרְבִּית דְּבָרֶיךָ:\",1,0],[2,122,15,4,\"וְתִגְרַע שִׂיחָה. כְּמוֹ ״כִּי יְגָרַע נִטְפֵי מָיִם״ (איוב לו:כז), וּכְמוֹ ״וְתִגְרַע אֵלֶיךָ חָכְמָה״ (איוב טו:ח):\",2,0],[2,122,15,5,\"כִּי יְאַלֵּף עֲוֺנְךָ. יִצְרְךָ הָרָע אֶת פִּיךָ לְדַבֵּר כַּדְּבָרִים הָאֵלֶּה, וְהָיָה לְךָ לִבְחֹר לְשׁוֹן עֲרוּמִים:\",1,0],[2,122,15,6,\"יַרְשִׁיעֲךָ פִיךָ וְלֹא אָנִי. כְּלוֹמַר: הֲשִׁיבֵנִי עַל שְׁאֵלָתִי, וְנִמְצָא פִיךָ הִרְשִׁיעֲךָ; כִּי טוֹב לִי שֶׁיַּרְשִׁיעֲךָ פִיךָ וְלֹא אָנִי. וְזוֹ הִיא שְׁאֵלָתִי:\",1,0],[2,122,15,7,\"הֲרִאשׁוֹן אָדָם תִּוָּלֵד. הֲבְטֶרֶם אָדָם תִּוָּלֵד? הֵ״א הַזֹּאת מְשַׁמֶּשֶׁת לְשׁוֹן תֵּימַהּ, לְפִיכָךְ נְקוּדָה בַּחֲטַף פַּתָּח. וּמְלִיצָתוֹ: הֲרִאשׁוֹן לְאָדָם הַנּוֹצָר מֵאֲדָמָה נוֹלַדְתָּ, שֶׁיָּדַעְתָּ לְקַיֵּם כָּל חָכְמַת מִצְווֹת הַבּוֹרֵא?!\",1,0],[2,122,15,8,\"וְתִגְרַע. וְתַרְבֶּה מִלְמַעְלָה לְמַטָּה לָרֶדֶת עָלֶיךָ:\",1,0],[2,122,15,10,\"כַּבִּיר. מְרֻבֶּה יָמִים מֵאָבִיךָ:\",1,0],[2,122,15,11,\"הַמְעַט מִמְּךָ תַּנְחוּמוֹת אֵל. אֲשֶׁר הֵיטִיב לְךָ הַצּוּר עַד עַתָּה יָמִים רַבִּים, וּדְבָרוֹ הַטּוֹב אֲשֶׁר לָאַט עִמָּךְ בְּלַאט וְנַחַת דִּשְּׁנוֹ:\",1,0],[2,122,15,11,\"לָאַט. הַנָּעִים. וּלְשׁוֹן פָּעַל הוּא, וְלֹא שֵׁם דָּבָר; וְלָכֵן הוּא נָקוּד חֶצְיוֹ קָמַץ וְחֶצְיוֹ פַּתַּח:\",2,0],[2,122,15,12,\"יִקָּחֲךָ. יְלַמֶּדְךָ, כְּמוֹ ״יַעֲרֹף כַּמָּטָר לִקְחִי״ (דברים לב:ב):\",1,0],[2,122,15,12,\"יִרְזְמוּן. כְּמוֹ יִרְמְזוּן, כְּמוֹ שִׂמְלָה שַׂלְמָה (שמות כב:ח, כו):\",2,0],[2,122,15,14,\"מָה אֱנוֹשׁ כִּי יִזְכֶּה. מַה כֹּחוֹ, שֶׁיּוּכַל לִהְיוֹת זַכַּאי נֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,122,15,15,\"וְשָׁמַיִם. צְבָא הַשָּׁמַיִם:\",1,0],[2,122,15,15,\"זַכּוּ. יִצְהָרוּ. כָּל לְשׁוֹן זַךְ הוּא צֹהַר:\",2,0],[2,122,15,16,\"אַף. כָּל שֶׁכֵּן:\",1,0],[2,122,15,16,\"וְנֶאֱלָח. נִתְעָב וּמְעֹרְבָּב, וְכֵן ״כֻּלּוֹ סָג יַחְדָּו נֶאֱלָחוּ״ (תהילים נג:ד):\",2,0],[2,122,15,18,\"אֲשֶׁר חֲכָמִים יַגִּידוּ. וְיִתְוַדּוּ פִּשְׁעָם וְלֹא כִחֲדוּ עֲוֹנָם מֵאֲבוֹתָם. זֶהוּ אֲשֶׁר רָאִיתִי, וְהִנְנִי אֲסַפֵּר לְךָ. וְהֵיכָן רָאִיתִי? יְהוּדָה הוֹדָה וְלֹא בוֹשׁ בְּמַעֲשֵׂה תָמָר (בראשית לח), רְאוּבֵן הוֹדָה וְלֹא בוֹשׁ בְּמַעֲשֵׂה בִּלְהָה (בראשית לה:כב). וּמֶה הָיָה שְׂכָרָם?\",1,0],[2,122,15,19,\"לָהֶם לְבַדָּם נִתְּנָה הָאָרֶץ. בִּשְׂכַר זֶה זָכָה יְהוּדָה לְמַלְכוּת נֶצַח, וְנָטְלוּ שְׁנֵיהֶם מִן הַנַּחֲלָה חֶלְקָם, וְלֹא גֹרְשׁוּ מִן נַחֲלָתָם בַּעֲוֹנָם, מֵאַחַר שֶׁהוֹדוּ:\",1,0],[2,122,15,19,\"וְלֹא עָבַר זָר בְּתוֹכָם. כְּשֶׁבָּא מֹשֶׁה לְבָרְכָם שֶׁנֶּאֱמַר (דברים לג:ו-ז) ״יְחִי רְאוּבֵן וְאַל יָמֹת וְזֹאת לִיהוּדָה״. דָּבָר אַחֵר וְלֹא עָבַר זָר בְּתוֹכָם בְּנַחֲלָה שֶׁל עָתִיד לָבֹא הַחֲלוּקָה בְּסֵפֶר (יחזקאל מח):\",2,0],[2,122,15,20,\"כָּל יְמֵי. הָרָשָׁע שֶׁאֵינוֹ שָׁב מֵחֶטְאוֹ וְאֵינוֹ מוֹדֶה פְּשָׁעָיו כָּל יָמָיו:\",1,0],[2,122,15,20,\"הוּא מִתְחוֹלֵל. וּמִתְאוֹנֵן עַל הַבְטָחָתוֹ, שֶׁיְּשַׁלֵּם רָעָתוֹ אֲשֶׁר פָּעַל. כָּל מִסְפַּר שָׁנִים אֲשֶׁר נִצְפְּנוּ לֶעָרִיץ. הוּא מִתְחוֹלֵל:\",2,0],[2,122,15,20,\"מִתְחוֹלֵל. לְשׁוֹן אֲנִינוּת, וְלֹא שָׁמַעְתִּי:\",3,0],[2,122,15,21,\"קוֹל פְּחָדִים בְּאָזְנָיו. לֵאמֹר: הִגִּיעַ עֵת תַּשְׁלוּמֵי:\",1,0],[2,122,15,21,\"בַּשָּׁלוֹם. וּכְשֶׁהוּא שָׁרוּי בְּשָׁלוֹם, אָז הַשּׁוֹדֵד יְבוֹאֶנּוּ:\",2,0],[2,122,15,22,\"וְצָפוּי הוּא אֱלֵי חָרֶב. וְעָתִיד הוּא אֱלֵי חֶרֶב וְעֹנִי, לָנוּד לַלֶּחֶם אַיֵּה יִמְצָאֶנּוּ:\",1,0],[2,122,15,23,\"נוֹדֵד הוּא. כְּלוֹמַר: מֻבְטָח הוּא לָנוּד:\",1,0],[2,122,15,23,\"יָדַע. לוֹ בֶּאֱמֶת:\",2,0],[2,122,15,23,\"כִּי נָכוֹן. וּמְזֻמָּן לָבוֹא בְּיָדוֹ כְּלוֹמַר: אֵלָיו וְעִמּוֹ יוֹם חֹשֶׁךְ. כְּמוֹ ״מִן הַבָּא בְיָדוֹ״ (בראשית לב:יד):\",3,0],[2,122,15,24,\"תִּתְקְפֵהוּ. תֶּחֱזַק הַמְּצוּקָה מִמֶּנּוּ וְתֶאֱנְסֵהוּ:\",1,0],[2,122,15,24,\"כְּמֶלֶךְ עָתִיד לַכִּידוֹר. לֹא מָצָאתִי דִּמְיוֹנוֹ. וְיֵשׁ לְפוֹתְרוֹ בָּאוֹתִיּוֹת הַמִּתְחַלְּפוֹת רֵי״שׁ בְּדָלֵי״ת כְּמוֹ אַשְׁכְּנַז וְרִיפַת שֶׁבַּתּוֹרָה (בראשית י:ג) – אַשְׁכְּנַז וְדִיפַת (דברי הימים א א:ו); וְכֵן כִּתִּים וְדוֹדָנִים (בראשית י:ד). אַף כָּאן לַכִּידוֹר – כְּמוֹ לַכִּידוֹד, כְּאוֹתוֹ הַמֶּלֶךְ שֶׁהוּא עָתִיד לִיקוֹד בָּאֵשׁ שֶׁל גֵּיהִנֹּם; וְהוּא סַנְחֵרִיב, שֶׁנִּתְנַבֵּא הַנָּבִיא עָלָיו ״כִּי עָרוּךְ מֵאֶתְמוּל תָּפְתֶּה גַּם הִיא לַמֶּלֶךְ הוּכָן״ (ישעיהו ל:לג) – לִשְׂרֹף חֵילָיו יְקַד יְקוֹד (ישעיהו י:טז); וְדוֹמֶה לוֹ ״כִּידוּדֵי אֵשׁ יִתְמַלָּטוּ״ (איוב מא:יא) – אִם (ס״א אֵשׁ) ״לַפִּידִים״ (איוב מא:יא), אִם לֶהָבוֹת (איוב מא:יג):\",2,0],[2,122,15,26,\"יָרוּץ אֵלָיו. הָיָה רָץ אֶל הַבּוֹרֵא בְּגֹבַהּ וּזְקִיפַת צַוָּאר לְהַכְעִיסוֹ:\",1,0],[2,122,15,26,\"בַּעֲבִי גַּבֵּי מָגִנָּיו. בְּחָזְקַת כֹּחוֹ, גַּבֵּי לְשׁוֹן גּוֹבַהּ, כְּמוֹ ״וַתִּבְנִי לָךְ גָּב״ (יחזקאל טז:כד):\",2,0],[2,122,15,27,\"פִּימָה עֲלֵי כָסֶל. עָשָׂה פֶה עַל חֲלָצַיִם, שֶׁחֶלְבּוֹ וְעֹבִי שׁוּמָנוֹ כָּפוּל עַל כְּסָלָיו, וְנִרְאִין כְּמִין פֶּה:\",1,0],[2,122,15,27,\"פִּימָה. מִגִּזְרַת ״וְהָיְתָה הַפְּצִירָה פִים״ (שמואל א יג:כא), זוֹ הִיא לִימָ״א שֶׁל נַפָּחִים, שֶׁיֵּשׁ לוֹ פִּיּוֹת הַרְבֵּה, וְנִקְרֵאת הֶפְצֵר פִּיּוֹת:\",2,0],[2,122,15,28,\"וַיִּשְׁכּוֹן עָרִים נִכְחָדוֹת. כֵּן דֶּרֶךְ בַּעֲלֵי גַּאֲוָה: בּוֹנִים חֳרָבוֹת לְשֵׁם:\",1,0],[2,122,15,29,\"וְלֹא יָקוּם חֵילוֹ. לֹא יִתְקַיֵּם לְיָמִים רַבִּים:\",1,0],[2,122,15,29,\"וְלֹא יִטֶּה. לֹא יִנְטֶה מְלִיצָתוֹ; כְּמוֹ ״וַיִּטּוּ אַחֲרֵי הַבָּצַע״ (שמואל א ח:ג), שֶׁפֵּירוּשׁוֹ: ׳וַיִּנְטוּ׳ הֵם עַצְמָם; אַף כָּאן לֹא יִנְטֶה מִן הַשָּׁמַיִם לָאָרֶץ. מִנְלָם. מַתַּת תַּאֲוָתָם וְזִמּוּן מַחֲשַׁבְתָּם, וְהוּא כִּשְׁתֵּי תֵיבוֹת: מִן לָהֶם:\",2,0],[2,122,15,29,\"מִן. הֲכָנָתָם, כְּמוֹ ״וַיְמַן לָהֶם הַמֶּלֶךְ״ (דניאל א:ה). וְדוֹמֶה לוֹ ״הַפְּצִירָה פִים״ בִּשְׁתֵּי תֵיבוֹת (שמואל א יג:כא), וְכֵן ״אֶרְאֶלָּם״ (ישעיה לג:ז) – תַּרְגּוּם יוֹנָתָן: ״אִתְגְּלִי לְהוֹן״. זֶה נִרְאֶה בְּעֵינַי, וּמְנַחֵם מְסַיְּעֵנִי. דָּבָר אַחֵר: מִנְלָם. לְשׁוֹן ״כַּנְּלֹתְךָ לִבְגֹּד״ (ישעיה לג:א), וְהַנּוּ״ן שֶׁבּוֹ יְסוֹד נוֹפֵל. לְשׁוֹן תַּכְלִית: לֹא יִטֶּה לָאָרֶץ. לִהְיוֹת בְּטֵלָה, גְּזֵרַת חָרוּץ:\",3,0],[2,122,15,30,\"וְיָסוּר. מִן הָעוֹלָם:\",1,0],[2,122,15,30,\"בְּרוּחַ פִּיו. שֶׁל שַׁלִּיט בָּעוֹלָם, וְזֶה מִקְרָא חָסֵר. וְיֵשׁ פּוֹתְרִים: בִּשְׁבִיל רוּחַ פִּיו – שֶׁהֵרַע לְדַבֵּר סָרָה:\",2,0],[2,122,15,31,\"אַל יַאֲמֵן. אוֹתוֹ אֲשֶׁר בְּשָׁוְא נִתְעָה, כִּי שָׁוְא יִהְיֶה תְמוּרָתוֹ וִיגִיעוֹ, כְּמוֹ ״וְעַל הַתְּמוּרָה״ (רות ד:ז):\",1,0],[2,122,15,32,\"בְּלֹא יוֹמוֹ. תַּעֲמֹד תְּמוּרָתוֹ עַל מְלִיאָתָהּ מִלִּגְדֹּל וּמִלְּהַצְלִיחַ עוֹד, כְּמוֹ ״וַיִּמָּלְאוּ לוֹ אַרְבָּעִים יוֹם״ (בראשית נ:ג). פֵּירוּשׁוֹ: ״וְאַשְׁלִימוּ״ (תרגום אונקלוס):\",1,0],[2,122,15,32,\"וְכִפָּתוֹ. כְּפִיַּת עֲנָפָיו, כָּל עַנְפֵי אִילָן דּוֹמִין לְכִפָּה:\",2,0],[2,122,15,35,\"הָרֹה עָמָל וְיָלֹד אָוֶן. עָשָׂה רָעָה, וְיִשְׁתַּלְּמוּ שְׂכַר הַלֵּידָה לְפִי הַהֵרָיוֹן:\",1,0],[2,122,15,35,\"תָּכִין. תַּזְמִין:\",2,0],[2,122,15,35,\"מִרְמָה. לְמִרְמָה תֵּהָפֵךְ לָהֶם תַּאֲוָתָם:\",3,0],[2,122,16,3,\"(מענה איוב): יַמְרִיצְךָ. יְשַׁעֶרְךָ פִּיךָ לַחֲשֹׁב דְּבָרִים נִמְרָצִים עַל אוֹפְנֵיהֶם:\",1,0],[2,122,16,4,\"כָּכֶם אֲדַבֵּרָה. כָּכֶם אֲנִי יוֹדֵעַ לְקַנְתֵּר:\",1,0],[2,122,16,4,\"לוּ יֵשׁ נַפְשְׁכֶם. בְּיִסּוּרִין תַּחַת נַפְשִׁי, גַּם אֲנִי הָיִיתִי מְחַבֵּר עֲלֵיכֶם בְּמִלִּין וּמֵנִיעַ עֲלֵיכֶם רֹאשִׁי בְּצַעֲקַתְכֶם, וּמְאַמֵּץ אֶתְכֶם בְּמוֹ פִי לֵאמֹר: הַחֲרִישׁוּ, הִתְאַמְּצוּ וְעִמְדוּ בְּיִסּוּרֵיכֶם, כַּאֲשֶׁר אַתֶּם תֹּאמְרוּ אֵלַי:\",2,0],[2,122,16,5,\"וְנִיד שְׂפָתַי. שֶׁאֲנִי נָד וְקוֹבֵל עַתָּה וְצוֹעֵק, אָז יַחְשׂוֹךְ וְלֹא אֶזְעוֹק וְלֹא אָנוּד עוֹד, אֲבָל עַתָּה:\",1,0],[2,122,16,6,\"אִם אֲדַבְּרָה וְגוֹ׳:\",1,0],[2,122,16,7,\"הֲשִׁמּוֹתָ. לְשׁוֹן שְׁתִיקָה, כְּמוֹ ״אֶשְׁתּוֹמֵם״ (ישעיהו סג:ה), וּכְמוֹ ״שֹׁמּוּ שָׁמַיִם״ (ירמיהו ב:יב) – שָׁתְקוּ וְהִתְמָהוּ:\",1,0],[2,122,16,8,\"וַתִּקְמְטֵנִי לְעֵד הָיָה. הִקְמַטְתַּנִי וְהִקְדַּרְתַּנִי בִּשְׁבִיל עֵד, שֶׁהָיָה לְעֵד עַל עֲוֹנִי לְהַשְׂטִינֵנִי:\",1,0],[2,122,16,9,\"צָרִי. הַשָּׂטָן הוּא הַצָּר:\",1,0],[2,122,16,9,\"יִלְטוֹשׁ. יְחַדֵּד, כְּמוֹ ״לוֹטֵשׁ כָּל חֹרֵשׁ וְגוֹמֵר״ (בראשית ד:כב):\",2,0],[2,122,16,10,\"פָּעֲרוּ עָלַי בְּפִיהֶם. פָּתְחוּ, כְּמוֹ ״וּפָעֲרָה פִיהָ״ (ישעיה ה:יד):\",1,0],[2,122,16,10,\"יִתְמַלָּאוּן. יִתְאַסְּפוּן, וְהַרְבֵּה לוֹ דּוֹמִין בַּמִּקְרָא: ״קָרְאוּ אַחֲרֶיךָ מָלֵא״ (ירמיה יב:ו), ״אֲשֶׁר יִקָּרֵא עָלָיו מְלֹא רֹעִים״ (ישעיה לא:ד). וְאֵינוֹ מִשְׁתַּנֶּה מִלְּשׁוֹנוֹ, כִּי כָל ׳מִלּוּי׳ – ׳נֶאֱסָף׳ הוּא:\",2,0],[2,122,16,11,\"יַסְגִּירֵנִי אֵל אֶל עֲוִיל. הִסְגִּירַנִי הַקָּדוֹשׁ בָּרוּךְ הוּא אֶל אֱוִיל לֵץ עוֹלֵל, לָלוּץ בִּי:\",1,0],[2,122,16,11,\"וְעַל יְדֵי רְשָׁעִים יִרְטֵנִי. רְטִיַּת תַּנְחוּמָיו וּרְפוּאָתִי מָסַר לָרְשָׁעִים, שֶׁאֵינָן אֶלָּא מַקְנִיטִים. דָּבָר אַחֵר: יִרְטֵנִי כְּמוֹ יְרַצֵּנִי, לְשׁוֹן רִצּוּי וְתַנְחוּמִים:\",2,0],[2,122,16,12,\"וַיְפַרְפְּרֵנִי. אוֹתוֹ עֲוִיל, לְשׁוֹן פֵּרוּרִין:\",1,0],[2,122,16,12,\"וַיְפַצְפְּצֵנִי. לְשׁוֹן נִשְׁבָּר לִשְׁבָרִים הַרְבֵּה בַּחֲבָטָה רַבָּה, כְּמוֹ ״וְנִפַּצְתִּים אִישׁ אֶל אָחִיו״ (ירמיה יג:יד), ״וְנִפֵּץ עֹלָלַיִךְ אֶל הַסָּלַע״ (תהלים קלז:ט):\",2,0],[2,122,16,13,\"רַבָּיו. מוֹרֶה חִצָּיו, כְּמוֹ ״רֹבֶה קֶשֶׁת״ (בראשית כא:כ):\",1,0],[2,122,16,13,\"מְרֵרָתִי. מָרָה שֶׁלִּי:\",2,0],[2,122,16,15,\"גִּלְדִּי. מַכָּה יְבֵשָׁה וְהַעֲלָאַת גֶּלֶד, וּלְשׁוֹן מִשְׁנָה (ראש השנה כז:): וְהֶעֱמִידוֹ עַל גִּלְדּוֹ:\",1,0],[2,122,16,15,\"וְעוֹלַלְתִּי. וְלִכְלַכְתִּי וְגִנִּיתִי, כְּמוֹ ״וַיִּתְעַלְּלוּ בָהּ״ (שופטים יט:כה) – לְשׁוֹן בִּזָּיוֹן וּגְנַאי, וּכְמוֹ ״עוֹלְלָה לְנַפְשִׁי״ (איכה ג:נא):\",2,0],[2,122,16,15,\"קַרְנִי. זִיוִי, לָשׁוֹן ״וְקַרְנַיִם מִיָּדוֹ לוֹ״ (חבקוק ג:ד):\",3,0],[2,122,16,16,\"חֳמַרְמְרוּ. נִקְמְטוּ, כְּמוֹ ״נֶחְמְרוּ בְּנֵי מֵעֶיהָ״ בִּלְשׁוֹן מִשְׁנָה (חולין נו:); וְכֵן ״מֵעַי חֳמַרְמָרוּ״ (איכה א:כ):\",1,0],[2,122,16,16,\"צַלְמָוֶת. שֶׁחָשְׁכוּ מֵחֲמַת בֶּכִי וְדֶמְעָה:\",2,0],[2,122,16,17,\"וּתְפִלָּתִי זַכָּה. לֹא קִלַּלְתִּי חֲבֵרִי, וְלֹא פִלַּלְתִּי לוֹ רָעָה:\",1,0],[2,122,16,18,\"וְאַל יְהִי מָקוֹם. בָּאָרֶץ לְהַבְלִיעַ בּוֹ צַעֲקָתִי, כִּי לַשָּׁמַיִם תַּעֲלֶה:\",1,0],[2,122,16,19,\"הִנֵּה בַשָּׁמַיִם עֵדִי. יוֹצְרִי הַיּוֹדֵעַ דְּרָכִי:\",1,0],[2,122,16,20,\"דָּלְפָה. דּוֹמַעַת וְזוֹלֶפֶת דִּמְעָה, לְשׁוֹן דִּלּוּף:\",1,0],[2,122,16,21,\"וְיוֹכַח לְגֶבֶר. וְהַלְוַאי יַעֲשֶׂה לִי זֹאת, שֶׁיִּתֵּן לִי מָקוֹם לְהִתְוַכֵּחַ גֶּבֶר עִם אֱלוֹהַּ, לְהַשְׁווֹת שְׁנֵי הָרִיבִים: רִיב גֶּבֶר עִם קוֹנוֹ וְרִיב בֵּין אָדָם לְרֵעֵהוּ:\",1,0],[2,122,16,22,\"כִּי שְׁנוֹת וְגוֹ׳. הַקְּצוּבִים מִסְפָּר לִימֵי חַיַּי:\",1,0],[2,122,16,22,\"יֶאֱתָיוּ. יַגִּיעוּ, וְאָז אֹרַח לֹא אָשׁוּב אֶהֱלֹךְ:\",2,0],[2,122,17,1,\"נִזְעָכוּ. נִקְפְּצוּ, כְּמוֹ ״נִדְעָכוּ״ (איוב ו:יז):\",1,0],[2,122,17,1,\"קְבָרִים לִי. מוּכָן אֲנִי לַקֶּבֶר:\",2,0],[2,122,17,2,\"אִם לֹא. אִם לֹא זֹאת בָּאַתְנִי, שֶׁבְּנֵי אָדָם הַתּוּלִים נוֹעֲדוּ עִמִּי בְּתַנְחוּמַי, לְהָתֵל בִּי:\",1,0],[2,122,17,2,\"וּבְהַמְּרוֹתָם. כְּמוֹ ״וַיַּמְרוּ בִי״ (יחזקאל כ:ח), ״מַמְרִים הֱיִיתֶם״ (דברים ט:ז) – לְשׁוֹן בְּהַקְנָטַתְכֶם:\",2,0],[2,122,17,2,\"תָּלַן עֵינִי. עֵינִי וְלִבִּי וּמַחֲשַׁבְתִּי לָנוּחַ בָּהֶן:\",3,0],[2,122,17,3,\"שִׂימָה נָּא. הַבּוֹרֵא:\",1,0],[2,122,17,3,\"עָרְבֵנִי. בְּתֵקַע כַּף, לְהִתְוַכֵּחַ יַחַד. כְּמוֹ מִי הוּא מֵאֵלֶּה לְיָדִי יִתָּקֵעַ וְיִיטַב לוֹ:\",2,0],[2,122,17,4,\"כִּי לִבָּם צָפַנְתָּ מִשָּׂכֶל. וְעַל כֵּן לֹא תְרוֹמֵם תִּפְאַרְתְּךָ עַל יְדֵיהֶם:\",1,0],[2,122,17,5,\"לְחֵלֶק יַגִּיד. לַחֲלַקְלַקּוּת יַגִּיד כָּל אֶחָד מֵהֶם אֶת רֵעוֹ, וְזֹאת תָּבֹא לָהֶם: עֵינֵי בָנָיו תִּכְלֶינָה:\",1,0],[2,122,17,6,\"וְתֹפֶת. כְּמוֹ ״תֹּף״ (ישעיהו ה:יב):\",1,0],[2,122,17,6,\"לְפָנִים. שֶׁל בְּרִיּוֹת אֲנִי:\",2,0],[2,122,17,7,\"וִיצוּרַי. אֵיבָרִים שֶׁאֲנִי נוֹצָר בָּהֶם:\",1,0],[2,122,17,8,\"יָשֹׁמּוּ. יִתְמְהוּ:\",1,0],[2,122,17,8,\"וְנָקִי. אִם יֵשׁ צַדִּיק שׁוֹמֵעַ בְּהַתּוּלוֹת הַחֲנֵפִים הָאֵלֶּה:\",2,0],[2,122,17,8,\"יִתְעוֹרָר. לָרִיב בָּכֶם:\",3,0],[2,122,17,9,\"וְיֹאחֵז. כָּל צַדִּיק דַּרְכּוֹ לַעֲמֹד כְּנֶגֶד כַּת חֲנֵפִים:\",1,0],[2,122,17,10,\"וְאוּלָם כֻּלָּם. אֲנִי אוֹמֵר לָכֶם תָּשׁוּבוּ נָא וּבֹאוּ נָא:\",1,0],[2,122,17,10,\"וְלֹא אֶמְצָא בָכֶם חָכָם. בְּמַה שֶּׁאַתֶּם מַלְעִיגִים עַל קַבָּלָתִי:\",2,0],[2,122,17,11,\"יָמַי וְגוֹ׳. הִנֵּה יְמֵי טוֹבָתִי שֶׁהֻרְגַּלְתִּי בָּהֶם, עָבְרוּ:\",1,0],[2,122,17,11,\"זִמּוֹתַי. שֶׁזָּמוֹתִי לְהַאֲרִיךְ בְּטוֹבָה:\",2,0],[2,122,17,11,\"נִתְּקוּ מוֹרָשֵׁי לְבָבִי. מַחֲשָׁבוֹת שֶׁלִּבִּי מוֹרִישַׁנִי, שֶׁהָיָה לִבִּי אוֹמֵר לִי לִירַשׁ טוֹבָה לְפִי דַרְכִּי:\",3,0],[2,122,17,12,\"לַיְלָה לְיוֹם יָשִׂימוּ. הַתּוֹלִים אֵלֶּה הוֹפְכִים לִי לַיְלָה לְיוֹם, כִּי מִצָּרַת הַתּוֹלִים לֹא אִישַׁן בַּלַּיְלָה:\",1,0],[2,122,17,12,\"אוֹר קָרוֹב. וְקָצַר לִי, מִפְּנֵי צָרוֹת חֹשֶׁךְ לַיְלָה. אוֹר קָרוֹב – כַּאֲשֶׁר יָבֹא הַשֶּׁמֶשׁ נִרְאֶה לִי שֶׁעַתָּה מִקָּרוֹב הֵאִיר הַיּוֹם, וְנִקְצַר וְחָלַף לוֹ; כְּמוֹ ״הָעִיר הַזֹּאת קְרֹבָה״ (בראשית יט:כ) – נִתְיַשְּׁבָה מִקָּרוֹב מֵחָדָשׁ; וּכְמוֹ ״כִּי רִנְנַת רְשָׁעִים מִקָּרֹב״ (איוב כ:ה), וּכְמוֹ ״חֲדָשִׁים מִקָּרֹב בָּאוּ״ (דברים לב:יז):\",2,0],[2,122,17,13,\"אִם אֲקַוֶּה שְׁאוֹל. כְּמוֹ ״אִם חֲרוּצִים יָמָיו״ (איוב יד:ה), כְּלוֹמַר: מֵאַחַר שֶׁאֲנִי מְקַוֶּה שְׁאוֹל בֵּיתִי:\",1,0],[2,122,17,13,\"וּבַּחֹשֶׁךְ רִפַּדְתִּי. שִׁטַּחְתִּי יְצוּעָי בַּקֶּבֶר:\",2,0],[2,122,17,14,\"לַשַּׁחַת קָרָאתִי אָבִי אָתָּה. לְהִתְלוֹנֵן בּוֹ יָמִים רַבִּים, כְּאִלּוּ הוּא אָבִי, מֵאַחַר שֶׁתִּקְוָתִי זֹאת הִיא:\",1,0],[2,122,17,15,\"וְאַיֵּה אֵפוֹ תִקְוָתִי. וְאַתְּ, לָמָּה נִמְשַׁכְתְּ? וּמִי יְשׁוּרֶנָּה לְהָרִיצָהּ עָדַי?\",1,0],[2,122,17,16,\"בַּדֵּי שְׁאוֹל תֵּרַדְנָה. אוֹתָם אֵבָרִים שֶׁסּוֹפָן לֵירֵד שְׁאוֹל, שֶׁתְּהֵא יַחַד עַל עָפָר נָחַת:\",1,0],[2,122,17,16,\"נָחַת. מְלוֹנָן, לְשׁוֹן ״וַתָּנַח עֲלֵיהֶם הָרוּחַ״ (במדבר יא:כו):\",2,0],[2,122,18,2,\"(מענה בלדד):קִנְצֵי. סוֹף:\",1,0],[2,122,18,2,\"תָּבִינוּ. תִּשְׁתְּקוּ לְהָבִין וְלִשְׁמֹעַ אֶת אֲשֶׁר נְדַבֵּר:\",2,0],[2,122,18,3,\"נִטְמִינוּ בְעֵינֵיכֶם. נֶחְשַׁבְנוּ בְעֵינֵיכֶם טְמוּנִין. וְאֵין יְסוֹד בַּתֵּיבָה זוֹ זוּלָתִי טי״ת מ״ם, כְּמוֹ ״טְמוֹנִין פְּלִשְׁתָּאֵי״, תַּרְגּוּם שֶׁל ״סִתְּמוּם פְּלִשְׁתִּים״ (בראשית כו:טו). יֵשׁ מְפָרְשִׁים לְשׁוֹן טְמִינָה, וְטָעוּת הוּא בְּיָדָם, שֶׁאִם כֵּן צְרִיכָה הַתֵּיבָה שְׁנֵי נוּנִי״ן, אֶחָד בַּיְּסוֹד וְאֶחָד בְּשִׁמּוּשׁ שֶׁל רַבִּים:\",1,0],[2,122,18,4,\"טוֹרֵף נַפְשׁוֹ. חוֹזֵר עַל אִיּוֹב. לְךָ אֲנִי אוֹמֵר, הַטּוֹרֵף וּמְחַבֵּל נַפְשׁוֹ בְּאַפּוֹ וּבְכַעֲסוֹ:\",1,0],[2,122,18,4,\"הֲלְמַעַנְךָ. הַלְמַעַן צִדְקָתְךָ תֵּעָזֵב הָאָרֶץ מִמִּשְׁפַּט מִדָּתָהּ?\",2,0],[2,122,18,4,\"וְיֶעְתַּק צוּר. הַיּוֹצֵר (מִמְּקוֹמוֹ) מִדַּעְתּוֹ וּמִמִּדָּתוֹ:\",3,0],[2,122,18,5,\"גַּם. עַתָּה, לְפִי צַעֲקָתְךָ, זֹאת תִּנְהַג לְדוֹרוֹת:\",1,0],[2,122,18,5,\"אוֹר רְשָׁעִים יִדְעָךְ. יִקְפֹּץ מִמְּקוֹמוֹ. שְׁבִיב. אֶשְׁטַנְצִיל״אָ:\",2,0],[2,122,18,7,\"יֵצְרוּ. יִהְיוּ קְצָרִים צַעֲדֵי כֹּחוֹ:\",1,0],[2,122,18,7,\"וְתַשְׁלִיכֵהוּ. מֵעָלָיו עֲצָתוֹ שֶׁיָּעַץ, אֲשֶׁר לֹא יִתְקַיֵּם:\",2,0],[2,122,18,8,\"כִּי וְגוֹ׳. סוֹפוֹ אֲשֶׁר שֻׁלַּח בְּרֶשֶׁת רַגְלָיו, (שֻׁלְּחוּ) לִצְעוֹד עַל הָרֶשֶׁת וְלִיתָּפֵשׂ:\",1,0],[2,122,18,8,\"וְעַל שְׂבָכָה יִתְהַלָּךְ. הִיא רֶשֶׁת; כָּל שְׂבָכָה עֲשׂוּיָה כְּמוֹ רֶשֶׁת, וְהוּא קֵייפָ״א שֶׁבְּרָאשֵׁי הַנָּשִׁים:\",2,0],[2,122,18,9,\"יֹאחֵז. יֹאחֲזֶנּוּ בְּעָקֵב פַּח:\",1,0],[2,122,18,10,\"טָמוּן בָּאָרֶץ. תַּחַת רַגְלָיו:\",1,0],[2,122,18,10,\"חַבְלוֹ. חֶבֶל מְצוּדָתוֹ אֲשֶׁר יִלָּכֵד בָּהּ:\",2,0],[2,122,18,10,\"וּמַלְכֻּדְתּוֹ. טָמוּן עֲלֵי נְתִיבוֹ, כְּשֵׁם שֶׁטּוֹמְנִין חֶבֶל מַלְכֹּדֶת לָעוֹפוֹת:\",3,0],[2,122,18,11,\"בַּלָּהוֹת. שֵׁדִים:\",1,0],[2,122,18,11,\"וֶהֱפִיצֻהוּ לְרַגְלָיו. (יִנְפְּצֵהוּ) יַחְבְּטוּהוּ עַל הָאָרֶץ:\",2,0],[2,122,18,12,\"אוֹנוֹ. בְּנוֹ (בראשית מט:ג):\",1,0],[2,122,18,12,\"לְצַלְעוֹ. אִשְׁתּוֹ (בראשית ב:כא):\",2,0],[2,122,18,13,\"יֹאכַל בַּדֵּי עוֹרוֹ. וְיֹאכַל כָּל שְׁאָר בַּדָּיו – בָּנָיו וּבְנוֹתָיו:\",1,0],[2,122,18,13,\"בְּכוֹר מָוֶת. שַׂר הַמָּוֶת, כְּמוֹ ״אָנִי בְּכוֹר אֶתְּנֵהוּ״ (תהלים פט:כח):\",2,0],[2,122,18,14,\"יִנָּתֵק מֵאָהֳלוֹ. מֵאִשְׁתּוֹ:\",1,0],[2,122,18,14,\"מִבְטַחוֹ. שֶׁהִיא בְּטוּחָה בּוֹ, (מִבְטַחוֹ) מִבְטַחַת שֶׁלּוֹ, שֶׁהִיא בּוֹטַחַת עָלָיו:\",2,0],[2,122,18,14,\"וְתַצְעִידֵהוּ. וְהִיא תַּצְעִידֵהוּ וְתִשְׁלָחֵהוּ (מֵעָלֶיהָ) לַקֶּבֶר לְמֶלֶךְ הַשֵּׁדִים:\",3,0],[2,122,18,15,\"תִּשְׁכּוֹן בְּאָהֳלוֹ אַלְמָנָה:\",1,0],[2,122,18,15,\"מִבְּלִי לוֹ. (שֶׁלֹּא תְּהֵא שֶׁלּוֹ) שֶׁהֲרֵי מֵת, וְסוֹף יְזֹרֶה עַל נָוֵהוּ גָּפְרִית:\",2,0],[2,122,18,18,\"יֶהְדְּפֻהוּ. מִן הַשָּׁמַיִם:\",1,0],[2,122,18,19,\"נֶכֶד. בֶּן הַבֵּן:\",1,0],[2,122,18,20,\"נָשַׁמּוּ אַחֲרוֹנִים. תָּמְהוּ בְּשָׁמְעָם עַל אֵיד אֲשֶׁר בָּא לוֹ:\",1,0],[2,122,18,20,\"שָׂעַר. לֹא יִתָּכֵן לִהְיוֹת מִגִּזְרַת שֵׂעָר, שֶׁאֵין טַעַם שֵׂעָר בְּשִׁי״ן אֶלָּא בְּעַיִן, וְאֵינוֹ נֶהְפָּךְ לְקָמַץ בְּאַתְנַחְתָּא וְסוֹף פָּסוּק. לֹא שָׁמַעְתִּי:\",2,0],[2,122,18,21,\"אֵלֶּה מִשְׁכְּנוֹת עַוָּל. זֶה אַחֲרִיתָם:\",1,0],[2,122,19,2,\"(מענה איוב): תּוֹגְיוּן. לְשׁוֹן ״תּוּגָה״ (משלי יד:יג):\",1,0],[2,122,19,3,\"עֶשֶׂר פְּעָמִים. עֶשֶׂר פָּרָשִׁיּוֹת יֵשׁ עַד כָּאן:\",1,0],[2,122,19,3,\"תַּהְכְּרוּ לִי. תִּתְנַכְּרוּ לִי:\",2,0],[2,122,19,4,\"אִתִּי תָּלִין. אֲנִי הוּא הַלּוֹקֵחַ מַכּוֹת עַל מְשׁוּגָתִי:\",1,0],[2,122,19,5,\"אִם אָמְנָם. אַתֶּם נוֹסָפִים עָלַי לְצָרָתִי, וְתוֹכִיחוּ עָלַי חֶרְפָּתִי מַרְאִים וּמוֹכִיחִים חֶרְפָּתִי עַל פָּנַי:\",1,0],[2,122,19,7,\"אֶצְעַק. עַל חָמָס וְלֹא אֵעָנֶה:\",1,0],[2,122,19,10,\"וַיַּסַּע. לְשׁוֹן עֲקִירָה:\",1,0],[2,122,19,12,\"וַיָּסֹלּוּ. לְשׁוֹן ״מְסִלָּה״ (ישעיה יא:טז):\",1,0],[2,122,19,13,\"אַךְ זָרוּ. לְשׁוֹן ״אַכְזָר״ (איוב ל:כא):\",1,0],[2,122,19,17,\"לִבְנֵי בִטְנִי. לְאוֹתָם שֶׁגִּדַּלְתִּי בְּבֵיתִי, כְּאִלּוּ הֵם בָּנַי:\",1,0],[2,122,19,18,\"עֲוִילִים מָאֲסוּ בִי. נִבְזֶה אֲנִי בְּעֵינֵי נְעָרִים, וְכָל שֶׁכֵּן בְּעֵינֵי שָׂרִים:\",1,0],[2,122,19,20,\"דָּבְקָה עַצְמִי. שֶׁאֲנִי כָּחוּשׁ מֵעֹבִי בְּשָׂרִי:\",1,0],[2,122,19,20,\"בְּעוֹר שִׁנָּי. כָּל בְּשָׂרִי הָיָה לָקוּי בִּשְׁחִין וּבְתוֹלָעִים, חוּץ מֵחֲנִיכֵי שִׁנָּיו:\",2,0],[2,122,19,24,\"בְּעֵט בַּרְזֶל. יֵחָצְבוּן בַּצּוּר, וְאַחַר כָּךְ מַעֲבִירִין אֶת הָעוֹפֶרֶת עֲלֵיהֶם, לָתֵת לָאוֹתִיּוֹת מַרְאֵה שַׁחֲרוּרִית, לְהַכִּירָם; וְכֵן דֶּרֶךְ חוֹקֵק אֶבֶן. וְלֹא יִתָּכֵן לְפָרֵשׁ עֵט שֶׁל עוֹפֶרֶת, שֶׁהֲרֵי רַךְ הוּא אֵצֶל הָאֶבֶן:\",1,0],[2,122,19,25,\"וַאֲנִי יָדַעְתִּי גֹּאֲלִי חָי. וָא״ו זֶה חוֹזֵר לְמַעְלָה: אַתֶּם תִּרְדְּפוּנִי, וַאֲנִי יָדַעְתִּי גּוֹאֲלִי חַי – לִיפָּרַע, וְהוּא יִתְקַיֵּם וְיַעֲמֹד:\",1,0],[2,122,19,25,\"וְאַחֲרוֹן עַל עָפָר יָקוּם. לְאַחַר שֶׁיִּכְלוּ כָּל שׁוֹכְנֵי עָפָר, הוּא אַחֲרוֹן יַעֲמֹד:\",2,0],[2,122,19,25,\"יָקוּם. יִתְקַיֵּם:\",3,0],[2,122,19,26,\"וְאַחַר עוֹרִי נִקְּפוּ זֹאת. וְהֵם אֵינָם נוֹתְנִים לֵב לְגוֹאֲלִי, אֶלָּא אַחַר מַכַּת עוֹרִי נִקְּפוּ וְנִקְּרוּ הַקְּנִיטָה וְהָרְדִיפָה הַזֹּאת שֶׁאָמַרְתִּי, שֶׁהִיא לִי כְּנוֹקֵף וְחוֹתֵךְ בְּעוֹרִי. כְּמוֹ ״וְנִקַּף סִבְכֵי הַיַּעַר״ (ישעיהו י:לד):\",1,0],[2,122,19,26,\"וּמִבְּשָׂרִי. אֲנִי רוֹאֶה מִשְׁפָּטִים:\",2,0],[2,122,19,26,\"אֱלוֹהַּ. לְשׁוֹן מִשְׁפָּט וְיִסּוּרִין:\",3,0],[2,122,19,28,\"כִּי תֹאמְרוּ מַה נִּרְדָּף לוֹ. כְּמוֹ ״כִּי תֹאמַר בִּלְבָבְךָ״ (דברים ז:יז), שֶׁהוּא מְשַׁמֵּשׁ לְשׁוֹן דִּילְמָא. כְּלוֹמַר: וְשֶׁתִּהְיוּ נוֹתְנִים לִבְּכֶם לַחְמֹל, וְלוֹמַר: לָמָּה נִרְדְּפֶנּוּ?\",1,0],[2,122,19,28,\"וְשֹׁרֶשׁ דָּבָר. הַנִּמְצָא בּוֹ מַה הִיא? לְעוֹלָם לֹא תַעֲלֶה בִלְבַבְכֶם הַטּוֹבָה הַזֹּאת! שֹׁרֶשׁ דָּבָר עַל מָה הוּא עוֹמֵד?\",2,0],[2,122,19,29,\"כִּי חֵמָה. שֶׁאַתֶּם מַגְדִּילִים עָוֹן הַמֵּבִיא לִידֵי חֶרֶב:\",1,0],[2,122,19,29,\"לְמַעַן תֵּדְעוּן. וְתָבִינוּ סוֹד הַפּוּרְעָנוּת הַבָּא עַל הָרְשָׁעִים. וְיֵשׁ אֵם לַמָּסֹרֶת: שַׁדִּין כְּתִיב – כְּמוֹ שֶׁיֵּשׁ דִּין בָּעוֹלָם, כְּמוֹ ״שַׁקַּמְתִּי דְּבוֹרָה״ (שופטים ה:ז). כֵּן רָאִיתִי בְּתַנְחוּמָא (תנחומא, משפטים ג):\",2,0],[2,122,20,2,\"(מענה צופר):שְׂעִפַּי יְשִׁיבוּנִי. מַחְשְׁבוֹתַי יְשִׁיבוּנִי מַעֲנֶה לְפִי, וּבַעֲבוּר שֶׁאֲנִי חָשׁ וְשׁוֹתֵק וְשַׂמְתִּי בִי שְׁתִיקוֹתַי יְשִׁיבוּנִי סְעִיפַי לַעֲנוֹת. אֲנִי שׁוֹמֵעַ מִמְּךָ יִסּוּרֵי כְלִמָּתִי, שֶׁאַתָּה תַכְלִימֵנִי, וְעַל כֵּן דְּבַר רוּחַ יַעֲנֵנִי מִבִּינָתִי לַהֲשִׁיבְךָ:\",1,0],[2,122,20,2,\"חוּשִׁי. שְׁתִיקוּתִי, כְּמוֹ ״עֵת לַחֲשׁוֹת״ (קהלת ג:ז):\",2,0],[2,122,20,4,\"הֲזֹאת. תֵּימַהּ: הֲיוֹדֵעַ אַתָּה מִדָּה הַמְהַלֶּכֶת עַל פְּנֵי כָּל הַדּוֹרוֹת מִנִּי עַד?\",1,0],[2,122,20,5,\"כִּי רִנְנַת רְשָׁעִים. כָּל יְמֵי הֱיוֹתָהּ, מִקָּרוֹב בָּאָה וְלֹא לְאֹרֶךְ יָמִים עוֹמֶדֶת:\",1,0],[2,122,20,5,\"וְשִׂמְחַת חָנֵף עֲדֵי רָגַע. בִּזְמַן מוּעָט תִּכְלֶה:\",2,0],[2,122,20,6,\"שִׂיאוֹ. גָּבְהוֹ:\",1,0],[2,122,20,7,\"כְּגֶלְלוֹ. גָּלָל שֶׁל רְעִי:\",1,0],[2,122,20,8,\"וְלֹא יִמְצָאוּהוּ. יוֹדְעָיו:\",1,0],[2,122,20,9,\"שְׁזָפַתּוּ. רָאֲתָהוּ:\",1,0],[2,122,20,10,\"בָּנָיו יְרַצּוּ דַלִּים. עַל אַנְשֵׁי סְדוֹם נֶאֱמַר מַעֲנֶה זוֹ, שֶׁהָיוּ גַּזְלָנִים וְאַכְזָרִים עַל עֲנִיִּים:\",1,0],[2,122,20,10,\"וְיָדָיו תָּשֵׁבְנָה. חֲמַס כַּפָּיו:\",2,0],[2,122,20,10,\"אוֹנוֹ. כֹּחַ אָנְסוֹ:\",3,0],[2,122,20,11,\"עַצְמוֹתָיו מָלְאוּ עֲלוּמָיו. כֹּחַ נַעֲרוּתָיו:\",1,0],[2,122,20,11,\"וְעִמּוֹ עַל עָפָר תִּשְׁכָּב. כִּי יָמוּת פִּתְאוֹם עִם כֹּחוֹ:\",2,0],[2,122,20,12,\"אִם תַּמְתִּיק. כָּךְ וֶסְתּוֹ שֶׁל רָשָׁע: אִם תַּמְתִּיק בְּפִיו רָעָה וְאֵינוֹ רוֹאֶה לָהּ עַתָּה שָׁעָה שֶׁתָּחוּל, יַכְחִידֶנָּה תַּחַת לְשׁוֹנוֹ, עַד בֹּא הָעֵת שֶׁתַּצְלִיחַ:\",1,0],[2,122,20,14,\"לַחְמוֹ בְּמֵעָיו. בְּיוֹם אֵידוֹ נֶהְפַּךְ לִמְרוֹרוֹת פְּתָנִים:\",1,0],[2,122,20,15,\"חַיִל. מָמוֹן:\",1,0],[2,122,20,16,\"אֶפְעֶה. נָחָשׁ שָׂרָף:\",1,0],[2,122,20,17,\"בִּפְלַגּוֹת נַהֲרֵי נַחֲלֵי. גַּן עֵדֶן הַמְּתוּקִין כִּדְבַשׁ וְחֶמְאָה:\",1,0],[2,122,20,18,\"מֵשִׁיב יָגָע. הַגֶּזֶל שֶׁגָּזַל:\",1,0],[2,122,20,18,\"כְּחֵיל תְּמוּרָתוֹ. כַּאֲשֶׁר תִּהְיֶה תְּמוּרָתוֹ לְ״חֵיל״, נְכָסִים גְּדוֹלִים, אָז יְבִיאֵהוּ חִסָּרוֹן:\",2,0],[2,122,20,18,\"וְלֹא יַעֲלֹס. בּוֹ, וְכֵן ״יַעֲלֹז״ (תהלים צו:יב) וְכֵן ״יַעֲלֹץ״ (דברי הימים א טז:לב) שְׁלָשְׁתָּן מִתְחַלְּפוֹת:\",3,0],[2,122,20,19,\"כִּי רִצַּץ עָזַב דַּלִּים. לְאַחַר שֶׁרִצַּץ אֶת דַּלִּים, עָזַב הַדַּלִּים וְנִטְרַד מִן הָעוֹלָם וְהָלַךְ לוֹ, וְהֵם חוֹזְרִים וְגוֹבִים מִמֶּנּוּ גְּזֵלוֹתָיו:\",1,0],[2,122,20,19,\"כִּי רִצַּץ. כְּשֶׁרִצַּץ; כְּמוֹ ״כִּי יִהְיֶה לָהֶם דָּבָר בָּא אֵלַי״ (שמות יח:טז) – כְּשֶׁיִּהְיֶה לָהֶם:\",2,0],[2,122,20,20,\"כִּי לֹא יָדַע. אֶת בִּטְנוֹ מֵעוֹלָם שָׁלֵיו, בִּטְנוֹ אוֹמֵר לוֹ תָּמִיד: גְּזוֹל וְהָבֵא לְמַלְּאֵנִי! וְעַל כֵּן בַּחֲמוּדוֹ. בִּבְשַׂר יוֹפִי חֶמְדָּתוֹ:\",1,0],[2,122,20,20,\"לֹא יְמַלֵּט. כִּי יְהֵא פּוֹחֵת וְהוֹלֵךְ, וְדוֹמֶה לוֹ ״וַתֶּמֶס כָּעָשׁ חֲמוּדוֹ״ (תהילים לט:יב):\",2,0],[2,122,20,21,\"אֵין שָׂרִיד לְאָכְלוֹ. לֹא שִׁיֵּר מִמַּאֲכָלוֹ לְחַלֵּק לַעֲנִיִּים:\",1,0],[2,122,20,21,\"עַל כֵּן לֹא יָחִיל טוּבוֹ. לֹא יַצְלִיחַ, כְּמוֹ ״יָחִילוּ דְרָכָיו״ (תהלים י:ה). וּבְאַנְשֵׁי סְדוֹם מְדַבֵּר, שֶׁהָיָה עֵינֵיהֶם צָרָה בָּאוֹרְחִים, כִּי כֵּן הֵעִיד עַל סְדוֹם ״גָּאוֹן שִׂבְעַת לֶחֶם וְגוֹ׳ וְיַד עָנִי וְאֶבְיוֹן לֹא הֶחֱזִיקָה״ (יחזקאל טז:מט). וְרַבּוֹתֵינוּ פֵּרְשׁוּ (סנהדרין צב.): אֵין שָׂרִיד לְאָכְלוֹ. לֹא הִשְׁרָה תַּלְמִידֵי חֲכָמִים עַל שֻׁלְחָנוֹ, כְּמוֹ ״וּבַשְּׂרִידִים אֲשֶׁר ה׳ קוֹרֵא״ (יואל ג:ה):\",2,0],[2,122,20,22,\"בִּמְלֹאות שִׂפְקוֹ. בְּהִתְמַלְּאוֹת תַּאֲוַת לִבּוֹ דַּי, אָז יֵצֶר לוֹ. תָּבֹא עָלָיו צָרָה:\",1,0],[2,122,20,22,\"סִפְקוֹ. לְשׁוֹן דֵּי, כְּדִמְתַרְגְּמִינָן: ״כַּד סְפִיקוּ גַמְלַיָּא״ (אונקלוס בראשית כד:כב), ״וּמָצָא לָהֶם״ (במדבר יא:כב): ״הֲיִסְפְּקוּן״ (תרגום אונקלוס):\",2,0],[2,122,20,22,\"כָּל־יַד עָמֵל תְּבוֹאֶנּוּ. תֶּחֱזַק עָלָיו וְתָצַר יַד עֲנִיִּים:\",3,0],[2,122,20,23,\"יְהִי לְמַלֵּא בִטְנוֹ יְשַׁלַּח בּוֹ חֲרוֹן אַפּוֹ. שְׁלִיחוּת חֲרוֹן אַפּוֹ יְהִי לְמַלֵּא בִטְנוֹ. וְאֵין זֶה לְשׁוֹן קְלָלָה אֶלָּא לְשׁוֹן נְבוּאָה וְעָתִיד:\",1,0],[2,122,20,23,\"וְיַמְטֵר עָלֵימוֹ. הַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,122,20,23,\"בִּלְחוּמוֹ. בְּזַעַף מִלְחַמְתּוֹ פַּחִים אֵשׁ וְגָפְרִית (תהלים יא:ו), כְּעִנְיָן שֶׁנֶּאֱמַר: ״וַה׳ הִמְטִיר עַל סְדֹם וְגוֹ׳״ (בראשית יט:כד):\",3,0],[2,122,20,24,\"תַּחְלְפֵהוּ. חִצִּים שֶׁתִּזְרוֹק הַקֶּשֶׁת יַחְלְפוּ אֶת גּוּפוֹ לַעֲבוֹר מֵעֵבֶר אֶל עֵבֶר. לָשׁוֹן אַחֵר: תַּחְלְפֵהוּ, כְּמוֹ תַּחֲלִיפֵהוּ (תְּקַדְּמֵהוּ) קֶשֶׁת נְחוּשָׁה:\",1,0],[2,122,20,25,\"שָׁלַף. הַשּׁוֹלֵף עָלָיו אֶת הַנֶּשֶׁק:\",1,0],[2,122,20,25,\"וַיֵּצֵא. הַנֶּשֶׁק:\",2,0],[2,122,20,25,\"מִגֵּוָה. מִתּוֹךְ תַּעְרָהּ:\",3,0],[2,122,20,25,\"וּבָרָק. פְּלַנְדוֹרְ״שׁ בְּלַעַ״ז, כְּמוֹ ״וּלְמַעַן הֱיוֹת לָהּ בָּרָק״ (יחזקאל כא:טו) – פוֹרְבִּי״ר:\",4,0],[2,122,20,25,\"מִמְּרוֹרָתוֹ יַהֲלֹךְ. מִמְּרוֹרָתוֹ שֶׁל נֶשֶׁק יַהֲלֹךְ, וּמִשָּׁם יִהְיוּ אֵמִים וָפַחַד עַל הָרָשָׁע:\",5,0],[2,122,20,26,\"לִצְפּוּנָיו. לְצֹרֶךְ מַצְפּוּנֵי גְנוּזִים הַצְּפוּנִים לוֹ:\",1,0],[2,122,20,26,\"אֵשׁ לֹא נֻפָּח. אֵשׁ שֶׁל גֵּיהִנֹּם:\",2,0],[2,122,20,26,\"יֵרַע שָׂרִיד בְּאָהֳלוֹ. תָּבֹא רָעָה לַשָּׂרִיד שֶׁיִּשָּׁאֵר בְּאָהֳלוֹ. כָּל הַפָּרָשָׁה כֻּלָּהּ בְּאַנְשֵׁי סְדוֹם (בראשית יט:א-כט):\",3,0],[2,122,20,26,\"יֵרַע שָׂרִיד בְּאָהֳלוֹ. אֲפִלּוּ לוֹט הַנִּמְלָט מֵהֶם בָּאָה רָעָה לְאָהֳלוֹ; זוֹ אִשְׁתּוֹ, שֶׁהָיְתָה נְצִיב מֶלַח (בראשית יט:כו). כֵּן מָצָאתִי בְּמִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, וירא ז):\",4,0],[2,122,20,27,\"מִתְקוֹמָמָה. לְשׁוֹן אוֹיֵב הַקָּם כְּנֶגְדּוֹ:\",1,0],[2,122,20,28,\"יִגֶל. לְשׁוֹן גָּלוּת:\",1,0],[2,122,20,28,\"נִגָּרוֹת. יִהְיוּ אוֹצְרוֹתָיו נְתוּנוֹת לִמְשִׁיסָה וּלְבַז, כְּמוֹ ״כַּמַּיִם הַמֻּגָּרִים אָרְצָה״ (מיכה א:ד):\",2,0],[2,122,20,29,\"אִמְרוֹ מֵאֵל. הָאָמוּר עָלָיו מִלִּפְנֵי הַמָּקוֹם. אִמְרוֹ לְשׁוֹן זָכָר, מִגִּזְרַת ״אֲמָרַי הַאֲזִינָה״ (תהלים ה:ב); ״אִמְרָתוֹ״ (תהלים קמז:טו) – לְשׁוֹן נְקֵבָה, מִגִּזְרַת ״אֲמָרוֹת טְהוֹרוֹת״ (תהלים יב:ז):\",1,0],[2,122,21,2,\"(מענה איוב): וּתְהִי זֹאת תַּנְחוּמוֹתֵיכֶם. אֶת אֲשֶׁר תַּחֲרִישׁוּ וְתִשְׁמְעוּ אֵלַי, זֹאת תְּהִי לִי תַּנְחוּם מֵאִתְּכֶם:\",1,0],[2,122,21,3,\"שָׂאוּנִי. סִבְלוּנִי:\",1,0],[2,122,21,4,\"הֶאָנֹכִי לְאָדָם שִׂיחִי. לָמָּה תַּעַמְדוּ עַל צַעֲקָתִי? וְכִי אֲנִי לְאָדָם כָּמוֹנִי מֵשִׂיחַ, שֶׁיִּשְׁמַע קוֹלִי? וְאִם מַדּוּעַ לֹא תִקְצַר רוּחִי, לִצְעוֹק מִצָּרָה לִי?\",1,0],[2,122,21,5,\"פְּנוּ אֵלַי. לִשְׁמֹעַ:\",1,0],[2,122,21,5,\"וְהָשַׁמּוּ. הִתְּמְהוּ לִדְבָרַי:\",2,0],[2,122,21,5,\"וְשִׂימוּ יָד עַל פֶּה. שֶׁלֹּא תֵדְעוּ לְהָשִׁיב:\",3,0],[2,122,21,6,\"וְאִם זָכַרְתִּי. דָּבָר שֶׁאֲנִי רוֹצֶה לוֹמַר מַדּוּעַ רְשָׁעִים יִחְיוּ?!\",1,0],[2,122,21,6,\"וְנִבְהָלְתִּי. שֶׁאֲנִי רוֹאֶה רִשְׁעֵי דּוֹר הַמַּבּוּל עָתְקוּ גַּם גָּבְרוּ חַיִל (בראשית ו:א-ד):\",2,0],[2,122,21,9,\"שָׁלוֹם מִפָּחַד. שֶׁלֹּא הָיוּ מַזִּיקִין שׁוֹלְטִין בָּהֶן:\",1,0],[2,122,21,10,\"שׁוֹרוֹ עִבַּר. אֶת הַנְּקֵבָה:\",1,0],[2,122,21,10,\"וְלֹא יַגְעִל. לֹא יוֹרֶה בָּהּ זֶרַע פְּסֹלֶת, שֶׁיְּהֵא חוֹזֵר וְנִפְלָט מִגּוּפָהּ בְּלֹא הֵרָיוֹן. כָּל לְשׁוֹן הַגְעָלָה – פְּלִיטָה הוּא; וְכֵן בִּלְשׁוֹן מִשְׁנָה: מַגְעִילָן בְּרוֹתְחִין (עבודה זרה עה.); וְכֵן ״כִּי שָׁם נִגְעַל מָגֵן גִּבּוֹרִים״ (שמואל ב א:כא) – נִפְלַט מְשִׁיחָתוֹ, וְהָיָה כְּאִלּוּ לֹא נִמְשַׁח בְּשֶׁמֶן; שֶׁהָיוּ רְגִילִין לִמְשֹׁחַ מָגִנֵּי עוֹר, כְּדֵי שֶׁיְּהֵא חָלָק וּמַחֲלִיק אֶת הָרֹמַח וְהַחֲנִית הַמַּכֶּה בּוֹ; וְהוּא כְּמוֹ ״שָׂרִים מָשְׁחוּ מָגֵן״ (ישעיה כא:ה):\",2,0],[2,122,21,10,\"תְּפַלֵּט פָּרָתוֹ. בָּעֵת תֵּלֵד אֶת וְלָדָהּ:\",3,0],[2,122,21,10,\"וְלֹא תְשַׁכֵּל. בְּלֹא עֵת:\",4,0],[2,122,21,11,\"יְשַׁלְּחוּ כַצֹּאן עֲוִילֵיהֶם וְגוֹ׳. בְּעֵת לֵידָתוֹ, הָיָה הוֹלֵךְ וּמְרַקֵּד מִיָּד; וְאִם פּוֹגֵעַ בְּמַזִּיק, נִלְחָם בּוֹ. וְהָיְתָה אוֹמֶרֶת לוֹ אִמּוֹ: הָבֵא לִי מִסְפָּרַיִם, וַאֲחַתּוֹךְ שָׁרְךָ! (הגדת בראשית) לֵךְ וְהַדְלֵיק לִי אֶת הַנֵּר! (בראשית רבה לו:א):\",1,0],[2,122,21,12,\"יִשְׂאוּ. הָיוּ נוֹשְׂאִין קוֹל בְּשִׁיר בְּתֹף וְכִנּוֹר. עוּגָב אֵינוֹ אֶלָּא לְשׁוֹן שְׂחוֹק, עַל שֵׁם הָעֲגָבוֹת; אשביימנ״ט בְּלַעַ״ז. כָּךְ שָׁמַעְתִּי:\",1,0],[2,122,21,13,\"וּבְרֶגַע שְׁאוֹל יֵחָתּוּ. כְּשֶׁמַּגִּיעַ יוֹם מוֹתוֹ, הָיָה מֵת לְפִי שָׁעָה, בְּנַחַת בְּלֹא יִסּוּרִין:\",1,0],[2,122,21,13,\"יֵחָתּוּ. יֵרְדוּ, וּבְתַרְגּוּם: ״נְחִיתוּ״:\",2,0],[2,122,21,15,\"וּמַה נּוֹעִיל. מַה הֲנָאָה יֵשׁ לָנוּ כִּי נִפְגַּע בּוֹ? אֵין אָנוּ צְרִיכִין לוֹ אֲפִלּוּ לְטִפַּת גְּשָׁמִים, כִּי ״אֵד יַעֲלֶה מִן הָאָרֶץ״ (בראשית ב:ו):\",1,0],[2,122,21,16,\"הֵן לֹא בְיָדָם טוּבָם. בִּתְמִיהַּ: וְכִי אֵין כָּל טוּבָם בְּיָדָם?\",1,0],[2,122,21,16,\"וַעֲצַת רְשָׁעִים רָחֲקָה מֶנִּי. אִיּוֹב הָיָה מְשַׁבֵּחַ בְּעַצְמוֹ, שֶׁרָאָה אוֹתָם וְלֹא נִמְנָה עִמָּהֶם:\",2,0],[2,122,21,17,\"כַּמָּה נֵר רְשָׁעִים יִדְעָךְ. לְמַעְלָה הוּא חוֹזֵר לָמָּה רְשָׁעִים יִחְיוּ, כַּמָּה תַּאֲרִיךְ זְמַן זֶה? וְחָזַר וּמְקַלְלָם: נֵר רְשָׁעִים יִדְעָךְ וְגוֹ׳:\",1,0],[2,122,21,17,\"חֲבָלִים. גּוֹרָל הָרָאוּי לָהֶם:\",2,0],[2,122,21,19,\"אֱלוֹהַּ יִצְפֹּן לְבָנָיו אוֹנוֹ. בִּתְמִיהַּ: וְכִי מִדָּה הִיא? שֶׁכֵּן זֶה הִרְשִׁיעַ כָּל יָמָיו, וִיהֵא בְּשָׁלוֹם וְיָמוּת בְּשָׁלוֹם, וְאוֹנוֹ – וְרִשְׁעוֹ יִצְפֹּן הַקָּדוֹשׁ בָּרוּךְ הוּא לְבָנָיו, לִלְקוֹת לָהֶם?!\",1,0],[2,122,21,19,\"יְשַׁלֵּם אֵלָיו וְיֵדָע. שֶׁבַח הוּא לְהַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁיְּשַׁלֵּם לָרָשָׁע עַצְמוֹ גְּמוּלוֹ, וְיָבִין שֶׁהִרְשִׁיעַ לַעֲשׂוֹת:\",2,0],[2,122,21,20,\"יִרְאוּ עֵינָיו כִּידוֹ. שִׁבְרוֹ, וְאֵינִי יָכוֹל לִמְצוֹא לוֹ דִּמְיוֹן בַּתּוֹרָה, כִּי אִם לְפִי עִנְיַן הַפָּסוּק נִרְאֶה שֶׁבֶר, וְכֵן הָרַב לֹא מָצָא לוֹ דִּמְיוֹן. (כִּידוֹ. לְשׁוֹן אֵידוֹ, אָלֶ״ף מִתְחַלֵּף בְּכָ״ף):\",1,0],[2,122,21,21,\"כִּי מַה חֶפְצוֹ בְּבֵיתוֹ אַחֲרָיו וּמִסְפַּר חֳדָשָׁיו חֻצָּצוּ. כִּי מַה הוּא חוֹשֵׁשׁ, שקלירי״ר בְּלַעַ״ז, וְחָפֵץ בְּבֵיתוֹ לְאַחַר מוֹתוֹ, לִדְאֹג בְּחַיָּיו בְּפֻרְעָנוּת הָעֲתִידָה לָבֹא עֲלֵיהֶם, אַחֲרֵי שֶׁמִּסְפַּר חֳדָשָׁיו נִקְבְּצוּ וְיִכְלוּ לִפְנֵי הָרָעָה שֶׁהִבְטִיחָם הַמָּקוֹם ״וְהָיוּ יָמָיו מֵאָה וְעֶשְׂרִים שָׁנָה: (בראשית ו:ג)? זֹאת הִיא שֶׁאָמַרְתִּי לָכֶם: ״פְּנוּ אֵלַי וְהָשַׁמּוּ״ (איוב כא:ה):\",1,0],[2,122,21,22,\"הֲלָאֵל יְלַמֶּד דָּעַת. הֲיֵשׁ אֶחָד מִכֶּם אֲשֶׁר הוּא תַּחַת הָאֵל, שֶׁיְּלַמֵּד דַּעַת, מַה הִיא הַמִּדָּה הַזֹּאת?\",1,0],[2,122,21,22,\"וְהוּא רָמִים יִשְׁפּוֹט. כְּגוֹן אֲנִי וְהַצַּדִּיקִים וְהַחֲשׁוּבִים הוּא מְיַסֵּר וְדָן וְנִפְרָע מֵהֶם, כְּמוֹ ״וְלֹא יִפְנֶה דֶּרֶךְ כְּרָמִים״ (איוב כד:יח) הָאָמוּר בְּנֹחַ וּבִמְתוּשֶׁלַח בְּאַגָּדַת חֵלֶק (סנהדרין קח.-קח:). לָשׁוֹן אַחֵר: הַלְאֵל יְלַמֶּד דָּעַת, כְּלוֹמַר: הַאֲנִי צָרִיךְ לְלַמְּדוֹ דַּעַת לִשְׁפּוֹט אֱמֶת? הוּא עַצְמוֹ יוֹדֵעַ שֶׁכֵּן! אֲבָל הוּא יִשְׁפּוֹט דִּינִים רָמִים בְּגָבְהוֹ וּבְגָדְלוֹ, וְאֵינוֹ חָשׁ לְדַקְדֵּק. זֶה שָׁמַעְתִּי, וְלֹא הָרִאשׁוֹן:\",2,0],[2,122,21,23,\"זֶה. הָרָשָׁע:\",1,0],[2,122,21,23,\"יָמוּת. נֶעֱנַשׁ בְּעֶצֶם תֻּמּוֹ, בְּמַרְאֵה שְׁלֵימוּתוֹ, לֹא חָסֵר:\",2,0],[2,122,21,23,\"שַׁלְאֲנַן. כְּמוֹ ״שַׁאֲנָן״ (ירמיהו מח:יא):\",3,0],[2,122,21,24,\"עֲטִינָיו מָלְאוּ חָלָב. לְשׁוֹן מִשְׁנָה הוּא (מנחות פו.): ״עוֹטְנוֹ בְּבֵית הַבַּד״ – צוֹבְרִים הַזֵּיתִים יַחַד וְשׁוּמָנָן מִתְעַגֵּל וּמִתְאַסֵּף לְתוֹכוֹ, כְּדֵי שֶׁיְּהֵא מוּכָן כְּשֶׁעוֹצְרוֹ בְּבֵית הַבַּד; וְאוֹתוֹ כְּלִי שֶׁצּוֹבְרִין אוֹתוֹ כְּדֵי לְהֵאָסֵף שַׁמְנוֹ לְתוֹכוֹ, נִקְרָא ״מַעֲטָן״. אַף כָּאן: חֶלְבּוֹ וְלַחְלוּחוֹ וְשׁוּמָנוֹ נִקְרָא עֲטִינָיו:\",1,0],[2,122,21,25,\"וְזֶה יָמוּת בְּנֶפֶשׁ מָרָה. הָרָמִים וְהַקְּדוֹשִׁים אֵלָיו, יִפְרַע מִיָּד מֵהֶם:\",1,0],[2,122,21,26,\"יַחַד עַל עָפָר יִשְׁכָּבוּ. וּלְאַחַר מוֹתָן אֵין נִכָּר לַבְּרִיּוֹת, מִי הָרַע מִי הַטּוֹב, כִּי כָזֶה כֵּן זֶה יַחַד עַל עָפָר יִשְׁכָּבוּ:\",1,0],[2,122,21,27,\"הֵן יָדַעְתִּי מַחְשְׁבוֹתֵיכֶם. וְהַמְּזִמּוֹת אֲשֶׁר עָלַי תַּחְמֹסוּ – תָּרֵיעוּ לַחְשֹׁב חָמָס:\",1,0],[2,122,21,28,\"כִּי תֹאמְרוּ וְגוֹ׳. בִּשְׁבִיל הָרָעָה אֲשֶׁר בָּאַתְנִי אַתֶּם אוֹמְרִים: רְאוּ, אַיֵּה בֵיתוֹ שֶׁל זֶה, שֶׁהָיָה נָדִיב, וְאַיֵּה אֹהֶל וּמִשְׁכְּנוֹת שְׁאָר רְשָׁעִים? כְּלוֹמַר: כָּמוֹהוּ כָּמוֹהֶם, בְּרִשְׁעוֹ אָבַד בֵּיתוֹ (וְלָמָּה אַתֶּם בּוֹטְחִים בְּשַׁלְוַתְכֶם):\",1,0],[2,122,21,29,\"הֲלֹא שְׁאֶלְתֶּם וְגוֹ׳. כָּל זֶה אַתֶּם מוֹשְׁלִים עָלַי מְשָׁלוֹת:\",1,0],[2,122,21,29,\"וְאֹתֹתָם. אֲשֶׁר הוֹדִיעוּ אֶתְכֶם, לֹא תְנַכְּרוּם מִשּׂוּם עַל לֵב, כְּמוֹ ״וַיִּתְנַכֵּר אֲלֵיהֶם״ (בראשית מב:ז):\",2,0],[2,122,21,30,\"כִּי לְיוֹם. אָמְרוּ לָכֶם, אֲשֶׁר לְיוֹם אֵיד יֵחָשֶׂךְ רָע, הָרָשָׁע מוֹנֵעַ וְנֶחְשָׂךְ מֵרָעָה, וְשָׁמוּר לְיוֹם הַקָּבוּעַ לְאֵידוֹ. כְּמוֹ ״אֲשֶׁר חָשַׂכְתִּי לְעֵת צָר״ (איוב לח:כג) – הִצְנַעְתִּים וַחֲשַׂכְתִּים לְהוֹדִיעָם עַד יוֹם קְרָב וּמִלְחָמָה:\",1,0],[2,122,21,31,\"מִי יַגִּיד עַל פָּנָיו דַּרְכּוֹ. מִי הוּא הַמֶּלֶךְ הַגָּדוֹל אֲשֶׁר יַגִּיד עַל פָּנָיו דַּרְכּוֹ? וְלֹא יִרְאוּ מִמֶּנּוּ, כַּמָּה הוּא נִשְׂגָּב זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁעָשָׂה!\",1,0],[2,122,21,31,\"וּמִי יְשַׁלֶּם לוֹ. וּגְמוּל רִשְׁעוֹ מִי יְשַׁלֶּם לוֹ?\",2,0],[2,122,21,32,\"וְהוּא לִקְבָרוֹת יוּבָל. סוֹפוֹ יוּבַל לַקֶּבֶר:\",1,0],[2,122,21,32,\"וְעַל גָּדִישׁ יִשְׁקוֹד. כְּשֶׁהוּא נִקְבָּר בַּשָּׂדוֹת אֵצֶל הַגְּדִישִׁים. (וְעַל גָּדִישׁ יִשְׁקוֹד. יָדוּנוּ אוֹתוֹ עַל שֶׁלֹּא קִיֵּם הַמִּצְווֹת הַשַּׁיָּכִים בַּשָּׂדֶה, לֶקֶט שִׁכְחָה וּפֵאָה, וּשְׁאָר מִצְווֹת הַנּוֹהֲגִים בָּעֹמֶר וּבַגָּדִישׁ; וְלָכֵן שָׁקְדוּ וִימַהֲרוּ עָלָיו הַפֻּרְעָנוּת הג״ה מר״ע):\",2,0],[2,122,21,33,\"רִגְבֵי. בְּלַשְׁטְ״ז בְּלַעַ״ז:\",1,0],[2,122,21,33,\"וּלְפָנָיו אֵין מִסְפָּר. לַנִּמְשָׁכִים לְאוֹתוֹ דֶּרֶךְ. כָּל אֵלֶּה מְזִמּוֹת תַּחְמְסוּ עָלַי (איוב כא:כז):\",2,0],[2,122,21,34,\"וְאֵיךְ תְּנַחֲמוּנִי הָבֶל. מֵאַחַר שֶׁתְּשׁוּבוֹתֵיכֶם נִשְׁאַר מָעַל, נִשְׁכְּחָה וְאָבְדָה מִכֶּם תְּשׁוּבוֹת הַחָכְמָה; וּתְשׁוּבוֹתֵיכֶם לֹא נִשְׁאֲרָה בְּיֶדְכֶם אֶלָּא תְּשׁוּבַת מָעַל. מָעַל. שֵׁם דָּבָר הוּא, לְכָךְ נִנְקַד כֻּלּוֹ קָמַץ, וְטַעֲמוֹ מִלְּעֵיל. כָּךְ שָׁמַעְתִּי:\",1,0],[2,122,22,2,\"(מענה אליפז):הַלְאֵל יִסְכָּן גָּבֶר. הַלְצֹרֶךְ וּלְהַנָּאַת הַיּוֹצֵר יוֹעִיל גֶּבֶר וְיֵהָנֶה, כַּאֲשֶׁר יְלַמֵּד דַּעַת אֶל הַבְּרִיּוֹת, וְחָכְמָה? יִסְכָּן הָרִאשׁוֹן – לְשׁוֹן הֲנָיָה, כְּמוֹ ״וַתְּהִי לוֹ סֹכֶנֶת״ (מלכים א א:ב); וְהַשֵּׁנִי – לְשׁוֹן לִמּוּד, כְּמוֹ ״הַהַסְכֵּן הִסְכַּנְתִּי״ (במדבר כב:ל). וְגַם הָרִאשׁוֹן יִתָּכֵן לִהְיוֹת נִפְתָּר לְשׁוֹן לִמּוּד: הַלְטוֹבַת הַיּוֹצֵר וּלְצָרְכּוֹ יִלְמַד גֶּבֶר כַּאֲשֶׁר יִלְמַד הַשְׂכֵּל?\",1,0],[2,122,22,3,\"הַחֵפֶץ לְשַׁדַּי. כְּמוֹ ״כִּי מַה חֶפְצוֹ בְּבֵיתוֹ אַחֲרָיו״ (איוב כא:כא)? הַהֲנָאָה וַחֲשָׁשׁ לוֹ, אִם תַּצְדִּיק מַעֲשֶׂיךָ בְּהִתְוַכֵּחַ לְפָנָיו, שֶׁיָּבֹא עִמְּךָ לְהִתְוַכֵּחַ בִּדְבָרֶיךָ?\",1,0],[2,122,22,3,\"וְאִם בֶּצַע. מָמוֹן לוֹ, אִם תַּתֵּם דְּרָכֶיךָ?\",2,0],[2,122,22,4,\"הֲמִיִּרְאָתְךָ יוֹכִיחֶךָ. אוֹ אִם מִיִּרְאָה שֶׁיִּירָא מִפָּנֶיךָ יָבֹא וְיִתְוַכַּח עִמְּךָ?\",1,0],[2,122,22,5,\"הֲלֹא. יוֹדֵעַ הוּא כִּי רָעָתְךָ רַבָּה:\",1,0],[2,122,22,8,\"וְאִישׁ זְרוֹעַ לוֹ הָאָרֶץ. בִּתְמִיהַּ וְכִי מֵחֲמַת שֶׁהָיִיתָ גָּדוֹל תִּירַשׁ אֶת הָאָרֶץ? כְּלוּם הוּא רָאוּי לְהִתְקַיֵּם?\",1,0],[2,122,22,8,\"יֵשֶׁב בָּהּ. יַאֲרִיךְ בָּהּ, כְּמוֹ ״וַתֵּשְׁבוּ בְקָדֵשׁ״ (דברים א:מו):\",2,0],[2,122,22,11,\"אוֹ חֹשֶׁךְ לֹא תִרְאֶה. כְּלוֹמַר: לֹא תִתֵּן עֵינֶיךָ וּבִטְחוֹנְךָ בַּכֹּחַ, לֵאמֹר:\",1,0],[2,122,22,12,\"הֲלֹא אֱלוֹהַּ גֹּבַהּ שָׁמָיִם. וְלֹא יַשְׁפִּיל לִרְאוֹת:\",1,0],[2,122,22,12,\"וּרְאֵה רֹאשׁ כּוֹכָבִים כִּי רָמּוּ. כְּמוֹ ״וּרְאֵה עָנְיִי״ שֶׁבְּסוֹף מַעֲנֶה הַחֲמִישִׁי (איוב י:טו), כְּלוֹמַר: וְנוֹתֵן אַתָּה עַיִן בְּרֹאשׁ כּוֹכָבִים כִּי רָמּוּ. וּבִשְׁבִיל כָּךְ אָמַרְתָּ:\",2,0],[2,122,22,13,\"מַה יָּדַע אֵל. בְּמַעֲשֵׂה הַחֹשֶׁךְ?\",1,0],[2,122,22,13,\"הֲבְעַד עֲרָפֶל יִשְׁפּוֹט. הַכְּנֶגֶד הַחֹשֶׁךְ הַזֶּה יִרְאֶה וְיִשְׁפּוֹט? הִנֵּה:\",2,0],[2,122,22,14,\"עָבִים סֵתֶר. לְפָנָיו וְלֹא יוּכַל לִרְאוֹת:\",1,0],[2,122,22,14,\"וְחוּג שָׁמַיִם יִתְהַלָּךְ. וְלֹא יֵדַע אֶת אֲשֶׁר בָּאָרֶץ:\",2,0],[2,122,22,14,\"חוּג. עוֹגֶל מְחוּגַת שָׁמַיִם, כְּמוֹ ״וּבַמְּחוּגָה יְתָאֳרֵהוּ״ (ישעיהו מד:יג). קוֹמְפָּ״שׁ בְּלַעַ״ז:\",3,0],[2,122,22,15,\"הָאֹרַח עוֹלָם. הַדֶּרֶךְ הָרִאשׁוֹנִים אֲשֶׁר מֵאָז:\",1,0],[2,122,22,15,\"תִּשְׁמֹר. שָׁמַרְתָּ בְּלִבְּךָ, לִזְכּוֹר מַה נִּהְיְיתָה בָּהֶם?\",2,0],[2,122,22,16,\"קֻמְּטוּ וְלֹא עֵת. נִגְזְרוּ בְּלֹא עִתָּם:\",1,0],[2,122,22,16,\"נָהָר וְגוֹ׳. וְנָהָר שֶׁל מַבּוּל אוֹ גָּפְרִית וָאֵשׁ שֶׁל סְדוֹם (בראשית יט:כד), הוּצַק בִּיסוֹדָם:\",2,0],[2,122,22,20,\"אִם לֹא נִכְחַד קִימָנוּ. הֲתִשְׁמֹר וְרָאִיתָ אִם לֹא נִכְחַד יְקוּמָם?\",1,0],[2,122,22,20,\"קִימָנוּ. כְּמוֹ קוֹמָתוֹ שֶׁל אוֹתוֹ הַדּוֹר, כְּמוֹ ״בֵּית אֵל יִמְצָאֶנּוּ וְשָׁם יְדַבֵּר עִמָּנוּ״ (הושע יב:ה) – כְּמוֹ ׳עִמּוֹ׳:\",2,0],[2,122,22,20,\"וְיִתְרָם. גַּאֲוָתָם:\",3,0],[2,122,22,20,\"אָכְלָה אֵשׁ. בְּרוֹתְחִין נִדּוֹנוּ. רַבִּי תַּנְחוּמָא דָּרַשׁ (תנחומא, נח י), שֶׁהָיוּ בַּעֲלֵי קוֹמָה, וְלֹא מֵתוּ בַּתְּהוֹמוֹת, וּבָאוּ עֲלֵיהֶם רוֹתְחִין מִלְמַעְלָה; וְזֶה יִתְרָם – קִימָה יְתֵרָה שֶׁלָּהֶם, כָּךְ שָׁמַעְתִּי:\",4,0],[2,122,22,21,\"הַסְכֶּן. לְמוֹד לִהְיוֹת עִמּוֹ שָׁלֵם:\",1,0],[2,122,22,21,\"וּשְׁלָם. וְתִהְיֶה שָׁלֵם וְלֹא תֶחְסַר בָּהֶם בַּדְּבָרִים הָאֵלֶּה:\",2,0],[2,122,22,21,\"תְּבוֹאַתְךָ טוֹבָה. תְּבוֹאֲךָ טוֹבָה:\",3,0],[2,122,22,24,\"וְשִׁית עַל עָפָר בָּצֶר. עַל אֲשֶׁר תָּשׁוּב אֵלָיו, תָּשִׁית עַל הָאָרֶץ חֹסֶן וּמִבְצָרִים:\",1,0],[2,122,22,24,\"וּבְצוּר נְחָלִים. הַסְּלָעִים גְּבוֹהִים שֶׁבַּנְּחָלִים עֲמוּקִים יִהְיֶה לְךָ אֹסֶף צְבִירַת אוֹפִיר – הִיא סְגֻלַּת מְלָכִים, שֶׁהָיוּ מְסַגְּלִים וְאוֹצְרִים זָהָב הַבָּא מֵאוֹפִיר:\",2,0],[2,122,22,25,\"וְהָיָה שַׁדַּי בְּצָרֶיךָ. אִם שַׁדַּי זֶה קֹדֶשׁ תָּמַהְתִּי עַל פִּתְרוֹנוֹ, שֶׁמַּשְׁמָעוֹ קְלָלָה שֶׁיִּמָּנֶה עִם אוֹיְבָיו כְּמוֹ ״וְאַתְּ הָיִית בְּעֹכְרָי״ (שופטים יא:לה) עִם עוֹכְרָי. וְעַל יְדֵי צֹרֶךְ נְדוּנֶנּוּ מִן הַמִּקְרָאוֹת חֲסֵרִים (כְּמוֹ וְהָיָה שַׁדַּי שׁוֹפֵט בְּצָרִיךְ, וְאִם נוּכַל לְאָמְרוֹ חוֹל לְשׁוֹן דַּיָּן וְחֹסֶן זֶה פִּתְרוֹנוֹ) וְהָיָה חֹסֶן מִבְצָרֶיךָ כְּמוֹ וְשִׁית עַל עָפָר בָּצֶר כְּלוֹמַר הוֹן עָתֵק תִּהְיֶה נִבְצָר. וּלְפִי הָעִנְיָן כֵּן פִּתְרוֹנוֹ שֶׁהֲרֵי סוֹפוֹ מוֹכִיחוֹ וְכֶסֶף תּוֹעָפוֹת לָךְ לְשׁוֹן חֹסֶן כְּמוֹ ״וְתוֹעֲפֹת רְאֵם לוֹ״ (במדבר כג:כב):\",1,0],[2,122,22,26,\"וְתִשָּׂא אֶל אֱלוֹהַּ פָּנֶיךָ. לֹא תָבֹא לְהָרִים פָּנֶיךָ אֶלָּא לִשְׁאוֹל צְרָכֶיךָ הֵימֶנּוּ:\",1,0],[2,122,22,27,\"וּנְדָרֶיךָ תְשַׁלֵּם. מֻבְטָח אַתָּה, שֶׁיֵּרָצוּ קָרְבְּנוֹת תַּשְׁלוּמֵי נְדָרֶיךָ:\",1,0],[2,122,22,28,\"וְיָקָם לָךְ. כְּמוֹ וְיָקוּם לָךְ:\",1,0],[2,122,22,29,\"כִּי הִשְׁפִּילוּ וַתֹּאמֶר גֵּוָה. וְאִם רוֹאֲךָ דּוֹרֵךְ שָׁפָל, תֹּאמַר בְּהַבְטָחָה לְהַגְבִּיהוֹ, וְיִגְבַּהּ:\",1,0],[2,122,22,29,\"וְשַׁח עֵינַיִם. בַּצָּרָה הַבָּאָה (אֵלָיו) בַּעֲוֹנוֹ:\",2,0],[2,122,22,29,\"יוֹשִׁעַ. אוֹתוֹ אֱלוֹהַּ בְּיָדְךָ וּבִתְפִלָּתְךָ:\",3,0],[2,122,22,30,\"יְמַלֵּט אִי נָקִי. אֵין נָקִי, כְּמוֹ ״אִי כָבוֹד״ (שמואל א ד:כא) – אֵין כָּבוֹד, וְכֵן ״וּלְרוֹזְנִים אֵי שֵׁכָר״ (משלי לא:ד) – אֵין שֵׁכָר, אֵין נָאֶה לָהֶם שִׁכְרוּת. שְׁלָשְׁתָּן חִבְּרָם מְנַחֵם בְּמַחֲלֹקֶת אַחַת. וְאַף עַל פִּי שֶׁהֵן שְׁתֵּי תֵיבוֹת, מְפָרְשִׁין כֵּן: וְנִמְלַט אֶת אִי נָקִי בְּבֹר כַּפֶּיךָ, וְכֵן שָׁמַעְתִּי. לָשׁוֹן אַחֵר שָׁמַעְתִּי, שֶׁהָיוּ אוֹמְרִים מִפִּי רַבִּי יַעֲקֹב, שֶׁהוּא לְשׁוֹן אָדָם הַשָּׁרוּי בְּצַעַר וּבַאֲנָקָה, וְהַיּוֹ״ד יְתֵרָה בַּתֵּיבָה, כְּמוֹ ״הַיֹּשְׁבִי בַשָּׁמָיִם״ (תהלים קכג:א). אֲבָל לֹא שָׁמַעְתִּי מִפִּי הָרַב:\",1,0],[2,122,23,2,\"(מענה איוב): גַּם הַיּוֹם. אַחַר כָּל תַּנְחוּמִין הַלָּלוּ:\",1,0],[2,122,23,2,\"מְרִי שִׂיחִי. בִּמְקוֹמוֹ עוֹמֵד, כִּי אֵין תַּנְחוּם בְּדִבְרֵיכֶם:\",2,0],[2,122,23,2,\"יָדִי כָּבְדָה. מַכַּת נִגְעִי תַּקִּיפָה יוֹתֵר מֵאַנְחָתִי; שֶׁאֵינִי קוֹבֵל וְצוֹעֵק לְפִי מַכָּתִי:\",3,0],[2,122,23,3,\"וְאֶמְצָאֵהוּ. לְשׁוֹפְטִי:\",1,0],[2,122,23,3,\"תְּכוּנָתוֹ. מְכוֹן כִּסְאוֹ:\",2,0],[2,122,23,4,\"מִשְׁפָּט. הוֹכָחַת דְּבָרִים:\",1,0],[2,122,23,5,\"(אֵדְעָה מִלִּים יַעֲנֵנִי. וְגַם אִם יִסְתֹּם אוֹתִי מִלְּדַבֵּר לְפָנָיו, שֶׁמָּא יְדַבֵּר הוּא עִמִּי, וְאֵדְעָה מִלִּים יַעֲנֵנִי רַבִּי תַּנְחוּמָא (תנחומא, בראשית יג)):\",1,0],[2,122,23,6,\"הַבְּרָב כֹּחַ. דְּבָרִים וְתוֹכָחוֹת שֶׁל חֲטָאָיו יָרִיב עִמָּדִי:\",1,0],[2,122,23,6,\"לֹא אַךְ. מַכָּה וּכְפִיָּה. לֹא יָשִׂים בִּי אָכְפּוֹ וְאֵימָתוֹ. (וְעוֹד יִפָּתֵר:) לֹא אַךְ הוּא יָשִׂים בִּי, כִּי לֹא יָשִׂים בִּי אַךְ הָרִיב שֶׁל תּוֹכַחַת פְּשָׁעַי, וְלֹא תְשׂוּמוֹת עֲלִילוֹת:\",2,0],[2,122,23,7,\"שָׁם. בִּמְקוֹם רִיבֵנוּ:\",1,0],[2,122,23,7,\"יָשָׁר. כֹּשֶׁר מִפְעֲלוֹתַי יְהֵא נוֹכָח וְנִגְלֶה וְנִרְאֶה עִמּוֹ, לְפָנָיו:\",2,0],[2,122,23,7,\"נוֹכָח. מוּכָח, וְשָׁם אֲפַלְּטָה לָנֶצַח – כִּי לֹא יִמְצָא בִי עָוֹן:\",3,0],[2,122,23,8,\"הֵן קֶדֶם. לְמַעְלָה הוּא חוֹזֵר, לְמִי יִתֵּן יָדַעְתִּי וְגוֹ׳:\",1,0],[2,122,23,8,\"קֶדֶם. מִזְרָח, שֶׁנֶּאֱמַר ״קֵדְמָה מִזְרָחָה״ (שמות כז:יג):\",2,0],[2,122,23,8,\"אָחוֹר. מַעֲרָב. הוֹאִיל וְהַמִּזְרָח – קִדְמַת עוֹלָם, נִמְצָא הַמַּעֲרָב – אֲחוֹרָיו שֶׁל עוֹלָם:\",3,0],[2,122,23,9,\"שְׂמֹאל. צָפוֹן:\",1,0],[2,122,23,9,\"בַּעֲשׂוֹתוֹ. כְּשֶׁבְּרָאוֹ, לֹא עָשָׂה מְקוֹם כִּסְאוֹ שָׁם שֶׁאֶרְאֶנּוּ שָׁם:\",2,0],[2,122,23,9,\"אָחַז. תַּרְגּוּם שֶׁל ״אֶרְאֶה״ (בראשית כא:טז). וְתֵדַע, שֶׁהַטַּעַם תַּחַת הָאָלֶ״ף; וְאִם לְשׁוֹן אֲחִיזָה הוּא, הָיָה טַעֲמוֹ מִלְּרַע, תַּחַת הַחֵי״ת:\",3,0],[2,122,23,9,\"יַעְטֹף יָמִין. כִּסָּה פְּנֵי הַדָּרוֹם בְּפָנָיו, לְמַעַן לֹא אֶרְאֶנּוּ:\",4,0],[2,122,23,10,\"כִּי יָדַע דֶּרֶךְ וְגוֹ׳. אֲשֶׁר עִמָּדִי מַהוּ, לְפִיכָךְ אֵינוֹ בָּא לָרִיב עִמָּדִי:\",1,0],[2,122,23,10,\"בְּחָנַנִי וְגוֹ׳. אֲשֶׁר כַּזָּהָב אֵצֵא אִם יָרִיב עִמָּדִי:\",2,0],[2,122,23,11,\"בְּאֲשׁוּרוֹ. בְּמַעְגָּלוֹ, כְּמוֹ ״אִם תִּטֶּה אֲשׁוּרִי״ (איוב לא:ז), ״כּוֹנֵן אֲשׁוּרָיו״ (תהלים מ:ג):\",1,0],[2,122,23,11,\"וְלֹא אָט. אֵינִי רָגִיל לִנְטוֹת:\",2,0],[2,122,23,12,\"מֵחֻקִּי צָפַנְתִּי אִמְרֵי פִיו. יוֹתֵר מֵחֻקֵּי מְזוֹנוֹתַי הָיִיתִי זָרִיז לִצְפֹּן אִמְרֵי פִיו, כְּמוֹ ״לֶחֶם חֻקִּי״ (משלי ל:ח) – מְזוֹנוֹתַי:\",1,0],[2,122,23,13,\"וְהוּא. לְפִי שֶׁהוּא יָחִיד בָּעוֹלָם, וְיוֹדֵעַ דַּעְתָּן וּמַחֲשַׁבְתָּן שֶׁל בְּרִיּוֹת וּמַה יֵּשׁ לָהֶם לְדַבֵּר לְפָנָיו, לְפִיכָךְ תְּשׁוּבוֹת מוּכָנוֹת לְפָנָיו:\",1,0],[2,122,23,13,\"וּמִי יְשִׁיבֶנּוּ. לְפִיכָךְ נַפְשׁוֹ אִוְּתָה וַיָּעַשׂ:\",2,0],[2,122,23,14,\"כִּי יַשְׁלִים חֻקִּי. יָדַעְתִּי כִּי לֹא יָשִׁיב יָדוֹ עַד אֲשֶׁר יַשְׁלִים חֹק גְּזֵרוֹתָיו – פֻּרְעָנִיּוֹת אֲשֶׁר גָּזַר עָלַי:\",1,0],[2,122,23,14,\"וְכָהֵנָּה רַבּוֹת עִמּוֹ. כִּי כָהֵנָּה רַבּוֹת עָשָׂה:\",2,0],[2,122,23,15,\"עַל כֵּן. שֶׁאֵינוֹ גּוֹמֵל לָאָדָם כְּפִי דְרָכָיו:\",1,0],[2,122,23,15,\"מִפָּנָיו אֶבָּהֵל. וּכְשֶׁאֶתְבּוֹנֵן בִּדְרָכָיו, אֶפְחַד מִמֶּנּוּ:\",2,0],[2,122,23,17,\"כִּי לֹא נִצְמַתִּי מִפְּנֵי חֹשֶׁךְ. בָּזֹאת אֲנִי נִבְהָל, כִּי לֹא נִצְמַתִּי לַחֲלוּטִין וּצְמִיתוּת קֶבֶר מִפְּנֵי הַחֹשֶׁךְ הַזֶּה הַבָּא עָלַי; וְכֵן לֹא כִסָּה מִפָּנַי אֶת הָאֹפֶל הַזֶּה עַד מוֹתִי:\",1,0],[2,122,23,17,\"וּמִפָּנַי כִּסָּה אֹפֶל. עַל כִּי לֹא שֶׁבְּרֹאשׁ הַפָּסוּק, חוֹזֵר:\",2,0],[2,122,24,1,\"מַדּוּעַ מִשַּׁדַּי לֹא נִצְפְּנוּ עִתִּים. קַבָּלָה הוּא זֶה: לָמָּה לֹא נִצְפְּנוּ עִתֵּי יְמֵי הָאָדָם מִן הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁלֹּא יֵדַע יוֹם מוֹת הָאָדָם? שֶׁמָּא לֹא יְמַהֵר פֻּרְעָנוּת, וִיקַדְּמֶנּוּ יוֹם הַמִּיתָה:\",1,0],[2,122,24,1,\"וְיוֹדְעָיו לֹא חָזוּ יָמָיו. מִיּוֹם הָאָדָם, כְּמוֹ ״חֹדֶשׁ יָמִים״ (בראשית כט:יד). (ומְתַּרְגְּמִינָן ״עִדַן בְּעִדַן״ (סא״א)). דָּבָר אַחֵר: מַדּוּעַ יוֹדְעָיו וְאוֹהֲבָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינָן יְכוֹלִין לִרְאוֹת סוֹף דְּרָכָיו וּמִדּוֹתָיו?\",2,0],[2,122,24,1,\"יָמָיו. זוֹ הִיא דֶּרֶךְ שֶׁנָּהַג בְּיָמָיו, כְּמוֹ ״לֹא יֶחֱרַף לְבָבִי מִיָּמָי״ (איוב כז:ו). וּמָה הֵן הַמִּדּוֹת הַתְּמוּהוֹת?\",3,0],[2,122,24,2,\"גְּבוּלוֹת יַשִּׂיגוּ. אוֹתָן שֶׁדַּרְכָּן לְהַסִּיג גְּבוּלוֹת, שֶׁהֵן קוֹנִין שָׂדוֹת כְּנֶגֶד שָׂדוֹת אֲחֵרִים, וּבַלַּיְלָה הֵם מַרְבִּים גְּבוּלֵיהֶם, שֶׁהָיוּ עוֹשִׂים גְּדֵרֵיהֶם בַּלַּיְלָה בְּתוֹךְ תְּחוּם שְׁכֵינֵיהֶם. (וְזֶהוּ מַשִּׂיג דִּמְתַּרְגְּמִינָן ״מִשְׁגֶּה״ שֶׁהָיוּ מַשְׁגִּים הַגְּבוּל סא״א):\",1,0],[2,122,24,2,\"עֵדֶר גָּזְלוּ וַיִּרְעוּ. לְעַצְמָן:\",2,0],[2,122,24,3,\"חֲמוֹר יְתוֹמִים יִנְהָגוּ. וְעוֹשִׂין כָּל רָעוֹת הָאֲמוּרוֹת בָּעִנְיָן. סוֹף דָּבָר: וֵאלוֹהַּ לֹא יָשִׂים תִּפְלָה – לְהוֹדִיעָם עֲוֹנָם וּלְהַמְצִיאָם גְּמוּלָם:\",1,0],[2,122,24,4,\"יַחַד חֻבְּאוּ. עֲנִיֵּי אֶרֶץ מִפְּנֵי שֶׁיְּרֵאִים מֵהֶם:\",1,0],[2,122,24,5,\"הֵן פְּרָאִים. הַפְּרָאִים שֶׁהֵם לִמּוּדֵי מִדְבָּר (ירמיהו ב:כד), לֶאֱרֹב אֶת הָעוֹבְרִים:\",1,0],[2,122,24,5,\"יָצְאוּ בְּפָעֳלָם. יָצְאוּ לִמְלַאכְתָּן, וּמַה הִיא הַפְּעֻלָּה? מְשַׁחֲרֵי לַטָּרֶף. מְבַקְּשִׁים לִטְרוֹף:\",2,0],[2,122,24,5,\"עֲרָבָה לוֹ לֶחֶם לַנְּעָרִים. לִמְשָׁרְתָיו וּנְעָרָיו שֶׁל רָשָׁע, הָעֲרָבָה וְהַמִּדְבָּר הָוֶה לוֹ לֶחֶם לְצָרְכָּם, שֶׁמִּשָּׁם הוּא חוֹטֵף וְאוֹכֵל וְגוֹזֵל מַה שֶּׁהֵם אוֹכְלִים:\",3,0],[2,122,24,5,\"לַנְּעָרִים. הֵם הַהוֹלְכִים אִתּוֹ לִגְזוֹל, כְּמוֹ ״רַק אֲשֶׁר אָכְלוּ הַנְּעָרִים״ (בראשית יד:כד):\",4,0],[2,122,24,6,\"בַּשָּׂדֶה. שֶׁל אֲחֵרִים:\",1,0],[2,122,24,6,\"בְּלִילוֹ. יְבוּלוֹ:\",2,0],[2,122,24,6,\"יִקְצוֹרוּ. לִגְזוֹל:\",3,0],[2,122,24,6,\"וְכֶרֶם רָשָׁע יְלַקֵּשׁוּ. וּכְרָמִים שֶׁל אֲחֵרִים הָרְשָׁעִים הָאֵלּוּ נוֹטְלִים פִּרְיָם, יְלַקֵּשׁוּ אשפריימנ״ט נוֹטְלִים לֶקֶשׁ שֶׁלָּהֶם, לֶקֶשׁ לְשׁוֹן צֶמַח פְּרִי כְּמוֹ ״בִּתְחִלַּת עֲלוֹת הַלֶּקֶשׁ״ (עמוס ז:א) תִּרְגֵּם יוֹנָתָן צִימוּחַ וְכֵן יָסַד רַבִּי אֶלְעָזָר (בהושענא אדמה מארר) לֶקֶשׁ מֵאַרְבֶּה. (דָּבָר אַחֵר וְכֶרֶם רָשָׁע יְלַקֵּשׁוּ, יְלַקְּשׁוּ אוֹתָהּ מֵהַשְּׁחִיתָהּ, כִּי אֶת שֶׁל הָעֲנִיִּים וִיתוֹמִים הֵם אוֹכְלִים. יְלַקֵּשׁוּ כְּמוֹ ״וּפִיהֶם פָּעֲרוּ לְמַלְקוֹשׁ״ (איוב כט:כג) זְמַן אָרוֹךְ וּכְמוֹ ״לְקִישָׁיָּא לְלָבָן״ (אונקלוס בראשית ל:מב)):\",4,0],[2,122,24,7,\"עָרוֹם יָלִינוּ. הֵם מְלִינִים אֶת הָעֲנִיִּים:\",1,0],[2,122,24,7,\"מִבְּלִי לְבוּשׁ. שֶׁנָּטְלוּ כְּסוּיִן:\",2,0],[2,122,24,8,\"מִזֶּרֶם. הַיּוֹרֵד מִן הֶהָרִים יִרְטָבוּ וְיִתְלַחְלְחוּ אוֹתָן הָעֲרוּמִים, לְפִי שֶׁמִבְּלִי כִסּוּי אֵין מַחְסֶה לְהֵחָסוֹת בּוֹ:\",1,0],[2,122,24,8,\"חִבְּקוּ צוּר. נֶחְבָּאִים בִּנְקִיקֵי הַסְּלָעִים, וְגַם שָׁם הַזֶּרֶם יוֹרֵד וּמְקַלֵּחַ עֲלֵיהֶם וְרוֹטְבָם. רָטוֹב – תַּרְגּוּם שֶׁל ״לַח״ (בראשית ל:לז); וְכָל מִי שֶׁאֵינוֹ מְנֻגָּב קָרוּי ׳לַח׳:\",2,0],[2,122,24,8,\"יִרְטָבוּ. מוֹיִישְׁטָ״א בְּלַעַ״ז:\",3,0],[2,122,24,9,\"מִשֹּׁד יָתוֹם. יְנִיקַת הַיָּתוֹם, מְקוֹם מוֹצָא מַאֲכָלוֹ וּמְזוֹנוֹתָיו. כְּמוֹ ״וְשֹׁד מְלָכִים תִּינָקִי״ (ישעיהו ס:טז):\",1,0],[2,122,24,9,\"יַחְבֹּלוּ. לְשׁוֹן ״אִם חָבֹל תַּחְבֹּל״ (שמות כב:כה), וּכְמוֹ ״חֲבֹל לֹא יַחֲבֹל״ (יחזקאל יח:טז):\",2,0],[2,122,24,10,\"הָלְכוּ. הֵם הִלְּכוּהוּ בְּלִי לְבוּשׁ:\",1,0],[2,122,24,10,\"וּרְעֵבִים נָשְׂאוּ עֹמֶר. וּמֵרְעֵבִים נָטְלוּ הָעֳמָרִים שֶׁל לֶקֶט. וְעוֹד יִפָּתֵר וּרְעֵבִים – אוֹתָם שֶׁהָיוּ נוֹשְׂאִים עֹמֶר, לְפִי שֶׁאֵלּוּ גּוֹזְלִים אוֹתָם מֵהֶם, וְהָיוּ נִשְׁאָרִים רְעֵבִים:\",2,0],[2,122,24,11,\"בֵּין שׁוּרוֹתָם יַצְהִירוּ. וְיַעֲשׂוּ שֶׁמֶן, בַּעֲלֵי זֵיתִים:\",1,0],[2,122,24,11,\"וְיְקָבִים דָּרְכוּ. בַּעֲלֵי כְּרָמִים:\",2,0],[2,122,24,11,\"וַיִּצְמָאוּ. לְאַחַר זְמַן; לְפִי שֶׁאֵלּוּ הָרְשָׁעִים גּוֹזְלִים אוֹתָם מֵהֶם:\",3,0],[2,122,24,11,\"בֵּין שׁוּרוֹתָם. כִּמְדֻמֶּה לִי שֶׁעוֹשִׂין הַזֵּיתִים שׁוּרוֹת שׁוּרוֹת בְּבֵית הַבַּד, וְהַיִּצְהָר זָב בֵּינֵיהֶם:\",4,0],[2,122,24,12,\"מֵעִיר מְתִים יִנְאָקוּ. מְתֵיהָ וְטוֹבֵיהָ שֶׁל עִיר יִנָּאֲקוּ מֵחֲמַת אוֹתָן הָאוֹנְסִין:\",1,0],[2,122,24,12,\"לֹא יָשִׂים תִּפְלָה. לְהַקְפִּיד עֲלֵיהֶם וְלִיקַּח נְקָמָה:\",2,0],[2,122,24,13,\"הֵמָּה. הָרְשָׁעִים הָאֵלֶּה, הֵם דּוֹר הַמַּבּוּל שֶׁמָּרְדוּ בָּאוֹר, בִּשְׁבִיל הַמָּטָר שֶׁהָיָה עוֹלֶה מִן הָאָרֶץ (בראשית ב:ו), וְלֹא הָיוּ צְרִיכִים לִכְלוּם:\",1,0],[2,122,24,14,\"לָאוֹר יָקוּם. אִם הָיוּ עוֹמְדִים בַּיּוֹם, הָיוּ הוֹרְגִים עוֹבְרֵי דְרָכִים:\",1,0],[2,122,24,14,\"וּבַלַּיְלָה יְהִי כַגַּנָּב. לַחְתּוֹר בָּתִּים:\",2,0],[2,122,24,15,\"וְעֵין נוֹאֵף. וְהַנּוֹאֵף שֶׁבָּהֶם הָיָה שׁוֹמֵר וּמַמְתִּין עַד נֶשֶׁף, לֵאמֹר וְגוֹ׳:\",1,0],[2,122,24,15,\"וְסֵתֶר. וּבַסֵּתֶר יָשִׂים פָּנָיו לַעֲבוֹר עֲבֵירָה, שֶׁעַל כָּל אֵלֶּה הָיוּ חֲשׁוּדִין דּוֹר הַמַּבּוּל: עַל הַגֶּזֶל, שֶׁנֶּאֱמַר ״וַתִּמָּלֵא הָאָרֶץ חָמָס״ (בראשית ו:יא), וְעַל הָעֲרָיוֹת, שֶׁנֶּאֱמַר ״כִּי הִשְׁחִית כָּל בָּשָׂר״ (בראשית ו:יב):\",2,0],[2,122,24,16,\"יוֹמָם חִתְּמוּ לָמוֹ. אוֹתָם שֶׁהָיוּ חַלָּשִׁים מֵהֶם מֵעֲשׂוֹת לִסְטִיּוּת בַּיּוֹם, הָיוּ חוֹתְרִים בַּבָּתִּים בַּלַּיְלָה, וּבַיּוֹם הָיוּ חֲתוּמִים וּמְסֻגָּרִים בְּבָתֵּיהֶם:\",1,0],[2,122,24,16,\"לֹא יָדְעוּ אוֹר. לֹא הָיוּ מַכִּירִין אֶת הָאוֹר, וְלֹא הָיָה עֵת מַהֲלָכָם:\",2,0],[2,122,24,17,\"כִּי יַחְדָּו בֹּקֶר לָמוֹ צַלְמָוֶת. שֶׁבַּיּוֹם הָיוּ נִסְגָּרִים, וּבַלַּיְלָה הָיוּ הוֹלְכִים לְמַחְתַּרְתָּם, וְלֹא הָיוּ יְרֵאִים מִן הַמַּזִּיקִים כְּלָל:\",1,0],[2,122,24,17,\"כִּי יַכִּיר בַּלְהוֹת צַלְמָוֶת. מַכִּיר הָיָה כָּל אֶחָד שֵׁדִים הַמַּבְהִילִים, וְלֹא הָיָה יָרֵא מֵהֶם. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (סנהדרין קט.): יוֹמָם חָתְמוּ לָמוֹ – בַּיּוֹם הָיוּ עוֹשִׂים סִימָנִים, הֵיכָן מַרְתֵּפוֹ שֶׁל בַּיִת וְהֵיכָן גְּנָזָיו שֶׁל עָשִׁיר; שֶׁהָיוּ מַפְקִידִין אֲפַרְסְמוֹן אֵצֶל בַּעֲלֵי בָתִּים עֲשִׁירִים, וְיוֹדְעִים הֵם שֶׁיַּנִּיחֶנּוּ בְּבֵית גְּנָזָיו, וּבַלַּיְלָה מְרִיחִין וְהוֹלְכִים שָׁם וְחוֹתְרִים שָׁם:\",2,0],[2,122,24,18,\"קַל הוּא עַל פְּנֵי מַיִם. כְּשֶׁהָיוּ הַצַּדִּיקִים נֹחַ וּמְתוּשֶׁלַח מוֹכִיחִים אוֹתָם, וְאוֹמְרִים לָהֶם שֶׁעָתִיד הַמַּבּוּל לָבֹא עֲלֵיהֶם, הָיוּ אוֹמְרִים: קַלִּים אָנוּ לָשׁוּט עַל הַמַּיִם, וְיֵשׁ לָנוּ גֹּמֶא וּדְבָרִים קַלִּים, לַעֲשׂוֹת מֵהֶם אֳנִיּוֹת וְלָשׁוּט:\",1,0],[2,122,24,18,\"תְּקֻלַּל חֶלְקָתָם בָּאָרֶץ לֹא יִפְנֶה דֶּרֶךְ כְּרָמִים. הָיוּ מְקַלְּלִים אֶת חֶלְקָם בָּאָרֶץ לֵאמֹר לֹא יִפְנֶה דֶּרֶךְ הַטּוֹב בְּדַרְכֵי הַצַּדִּיקִים הָרָמִים וְשׁוֹכְנִים בְּרוּמוֹ שֶׁל עוֹלָם. לָשׁוֹן אַחֵר כְּרָמִים הֵם הַצַּדִּיקִים וּפַרְנְסֵי הַדּוֹר, כְּמוֹ ״וְנָתַתִּי לָהּ אֶת כְּרָמֶיהָ מִשָּׁם״ (הושע ב:יז) תִּרְגֵּם יוֹנָתָן ״יַת פַּרְנָסָהָא״, הָיוּ מְקַלְּלִים אֶת חֶלְקָם בָּאָרֶץ לֵאמֹר לֹא יִפְנוּ דֶּרֶךְ הַטּוֹב נִשְׁבָּעִים שֶׁלֹּא יִפְנוּ אֶת דַּרְכָּם. לָשׁוֹן אַחֵר תְּקֻלַּל חֶלְקָתָם מִתְקַלְקֶלֶת הָיְתָה חֶלְקָתָם שֶׁהָיוּ מַשְׁחִיתִים זַרְעָם לְבַטָּלָה, כְּמוֹ ״כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ״ (בראשית ו:יב), תְּקֻלַּל לְשׁוֹן קִלְקוּל, כְּמוֹ ״בַּעֲוֹן אֲשֶׁר יָדַע כִּי מְקַלְלִים לָהֶם בָּנָיו״ (שמואל א ג:יג). לָשׁוֹן אַחֵר תְּקֻלַּל חֶלְקָתָם הַדּוֹרוֹת שֶׁאַחֲרֵיהֶם מְקַלְּלִים בָּהֶם מִי שֶׁפָּרַע מִדּוֹר הַמַּבּוּל, כָּךְ שָׁמַעְתִּי. לָשׁוֹן אַחֵר תְּקֻלַּל חֶלְקָתָם לֹא יִפְנֶה דֶּרֶךְ כְּרָמִים, לֹא הָיוּ מְקַבְּלִים תּוֹכָחָה מִן הַטּוֹבִים. לָשׁוֹן אַחֵר הָיוּ קַלִּים לָשׁוּט בִּסְפִינוֹת לַהֲרֹג וְלַחְמֹס מָמוֹן וְדֶרֶךְ יִשּׁוּב בְּנֵי אָדָם וּנְטִיעַת כְּרָמִים אֵין חוֹשֵׁשׁ לֵילֵךְ:\",2,0],[2,122,24,19,\"צִיָּה גַם חֹם יִגְזְלוּ. מִפְּנֵי רָעָתָם גָּרְמוּ לָהֶם שָׁנָה אַחַת לְהִשְׁתַּנּוֹת עוֹלָם מִשִּׁשָּׁה סְדָרָיו: ״זֶרַע וְקָצִיר וְקֹר וָחֹם וְקַיִץ וָחֹרֶף״ (בראשית ח:כב):\",1,0],[2,122,24,19,\"מִימֵי שֶׁלֶג. כְּמוֹ ׳וּמִימֵי שֶׁלֶג׳, גַּם אוֹתָם גָּזְלוּ מִן הָעוֹלָם, לְפִי שֶׁשְּׁאוֹל חָטָאוּ. יֵשׁ תֵּיבוֹת חֲסֵרוֹת וָוִי״ן, כְּמוֹ ״וַאֲנִי כְּכֶבֶשׂ אַלּוּף״ (ירמיהו יא:יט), וְהוּא נִפְתָּר ׳כְּכֶבֶשׂ וְאַלּוּף׳. עוֹד הַרְבֵּה בְּמַחְבֶּרֶת מְנַחֵם בֶּן סָרוּק:\",2,0],[2,122,24,20,\"יִשְׁכָּחֵהוּ רֶחֶם. אִמּוֹ. דָּרַשׁ רַבִּי תַּנְחוּם (תנחומא, נח ז), שֶׁהָיוּ דּוֹר הַמַּבּוּל נוֹטְלִים אֶת בְּנֵיהֶם וְנוֹתְנִים אוֹתָם תַּחְתֵּיהֶם, לִסְתֹּם אֲרֻבּוֹת הַתְּהוֹם; וַאֲפִלּוּ אִמּוֹ לֹא הָיְתָה מְרַחֶמֶת עָלָיו:\",1,0],[2,122,24,20,\"מְתָקוֹ רִמָּה. לָמוּת וְלֶאֱכוֹל רִמָּה בְּשָׂרָם:\",2,0],[2,122,24,20,\"עוֹד לֹא יִזָּכֵר. בְּשָׁנָה אַחַת נֶעֶקְרוּ. וְעַל אַרְכָּא שֶׁנִּיתַּן לָהֶם מִתְּחִילָּה, הָיָה אִיּוֹב קוֹבֵל; שֶׁהַרְבֵּה מֵתוּ וְלֹא רָאוּ בְּפוּרְעָנוּת זֶה:\",3,0],[2,122,24,21,\"רוֹעֶה עֲקָרָה לֹא תֵלֵד. כָּךְ הָיָה מִנְהָגָם: נוֹשֵׂא שְׁתֵּי נָשִׁים, אַחַת לְתַשְׁמִישׁ וְאַחַת לְבָנִים. זוֹ שֶׁעוֹמֶדֶת לְתַשְׁמִישׁ, מַשְׁקֶה כּוֹס עִקָּרִין כְּדֵי שֶׁלֹּא תֵלֵד עוֹלָמִית, וּמַאֲכִילָהּ תַּפְנוּקִים וּמַרְחִיצָהּ וּמְקַשְּׁטָהּ, כְּדֵי שֶׁתְּהֵא נָאָה. וְזוֹ הָעוֹמֶדֶת לְבָנִים, מַלְבִּישָׁהּ בִּגְדֵי אַלְמָנוֹת וּמַרְעִיבָהּ. וְזֶהוּ שֶׁאוֹמֵר: הָעֲקָרָה שֶׁלֹּא תֵלֵד הָיָה רוֹעֶה וּמֵטִיב, וְאֶת הָאַלְמָנָה שֶׁעוֹמֶדֶת לְבָנִים לֹא יְיֵטִיב:\",1,0],[2,122,24,22,\"וּמָשַׁךְ. הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָן אַבִּירִים בְּכֹחוֹ לְפוּרְעָנוּת וּלְמִחְיָה, מִתּוֹךְ אַרְכָּא שֶׁהֶאֱרִיךְ לָהֶם:\",1,0],[2,122,24,22,\"יָקוּם. יוֹם אֶחָד:\",2,0],[2,122,24,22,\"וְלֹא יַאֲמִין בַּחַיִּין. כְּמוֹ בַּחַיִּים: ״בַּיּוֹם הַזֶּה נִבְקְעוּ כָּל וְגוֹ׳״ (בראשית ז:יא):\",3,0],[2,122,24,23,\"יִתֶּן לוֹ לָבֶטַח. עַד יוֹם אֵידָם, וְנִשְׁעָנוּ:\",1,0],[2,122,24,24,\"רוֹמּוּ מְעַט. נִסְתַּלְּקוּ מִן הָעוֹלָם כִּמְעַט רֶגַע:\",1,0],[2,122,24,24,\"וְהֻמְּכוּ. נִדְכְּאוּ וְנִתְמַסְכְּנוּ:\",2,0],[2,122,24,24,\"כְּכֹל יִקָּפְצוּן. כִּשְׁאָר כָּל הַנִּקְפָּצִים וְנִמְלָטִים בְּעֵת קָצִיר וּבָצִיר וּמָסִיק, שֶׁנִּקְפָּצִים יַחַד, כֵּן תַּמּוּ כְרֶגַע:\",3,0],[2,122,24,25,\"וְאִם לֹא אֵפוֹ. כַּאֲשֶׁר אָמַרְתִּי, יָבֹא אֶחָד מִכֶּם וְיַכְזִיבֵנִי:\",1,0],[2,122,24,25,\"וְיָשֵׂם לְאַל מִלָּתִי. שֶׁאֲנִי מְהַרְהֵר אַחֲרָיו לָדַעַת מִדּוֹתָיו, שֶׁמַּאֲרִיךְ אַף לָרְשָׁעִים. וְאֶת אוֹהֲבָיו, כְּמוֹנִי הוּא מְיַסֵּר וְאֵינוֹ מְמִיתָן; כְּמוֹ שֶׁקּוֹבֵל ״כִּי לֹא נִצְמַתִּי מִפְּנֵי חֹשֶׁךְ״ (איוב כג:יז). וְאֵלּוּ שֶׁ״גְּבוּלוֹת יַשִּׂיגוּ״ (איוב כד:ב), וְכָל אֵלֶּה עָשׂוּ, לֹא הֻכּוּ בְּיִסּוּרִין:\",2,0],[2,122,25,2,\"(מענה בלדד): הַמְשֵׁל וָפַחַד עִמּוֹ. כְּלַפֵּי שֶׁאָמַר אִיּוֹב ״אֶעֶרְכָה לְפָנָיו מִשְׁפָּט״ (איוב כג:ד), אָמַר לוֹ: הַמְשֵׁל וָפַחַד עִמּוֹ, הַמְשֵׁל זֶה מִיכָאֵל, וָפַחַד זֶה גַּבְרִיאֵל. כְּלוּם אַתָּה יָכוֹל לְהָשִׁיב אֶת אֶחָד מֵהֶם?\",1,0],[2,122,25,2,\"עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. כְּשֶׁהַמַּזָּלוֹת עוֹלִים, כָּל אֶחָד סוֹבֵר: אֲנִי עוֹלֶה רִאשׁוֹן; לְפִי שֶׁאֵינוֹ רוֹאֶה מַה שֶּׁלְּפָנָיו, לְפִיכָךְ אֵינוֹ מִתְקַנֵּא. כָּךְ שָׁמַעְתִּי (תנחומא בובר, איוב). לָשׁוֹן אַחֵר: עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. אֵשׁ וּמַיִם בְּלוּלִין, וְאֵין מַיִם מְכַבִּין אֶת הָאֵשׁ. כָּךְ שָׁמַעְתִּי:\",2,0],[2,122,25,4,\"וּמַה יִּצְדַּק וְגוֹ׳. יְלוּד אִשָּׁה שֶׁאָמַרְתָּ: ״בְּחָנֵנִי כַּזָּהָב אֵצֵא״ (איוב כג:י):\",1,0],[2,122,25,5,\"עַד יָרֵחַ. כְּמוֹ ״וְלֹא עָדָה עָלָיו שָׁחַל״ (איוב כח:ח):\",1,0],[2,122,25,5,\"וְלֹא יַאֲהִיל. כְּמוֹ ״לֹא יָהֵלּוּ אוֹרָם״ (ישעיהו יג:י), וְאָלֶ״ף זוֹ בָּאָה כְּמוֹ ״וְלַאֲדִיב אֶת נַפְשֶׁךָ״ (שמואל א ב:לג) – אָלֶ״ף יְתֵרָה. לָשׁוֹן אַחֵר: לֹא יַאֲהִיל – לֹא יִהְיֶה לוֹ צֵל, כְּשֶׁאֵינוֹ מֵאִיר אֵין לוֹ צֵל. וְהָרִאשׁוֹן נִרְאֶה, וּשְׁנֵיהֶם שָׁמַעְתִּי:\",2,0],[2,122,26,4,\"(מענה איוב): וְנִשְׁמַת מִי יָצְאָה מִמֶּךָּ. מִי שָׂם בְּךָ הָרוּחַ הַזֶּה שֶׁיָּצָא מִפִּיךָ? מִי לֹא יָדַע זֹאת?\",1,0],[2,122,26,5,\"הָרְפָאִים. גֵּיהִנֹּם הַמְּרַפֶּה אֶת הַבְּרִיּוֹת:\",1,0],[2,122,26,5,\"יְחוֹלָלוּ. שִׁבְעָה חֲלָלִים שֶׁלּוֹ:\",2,0],[2,122,26,5,\"מִתַּחַת מַיִם וְשֹׁכְנֵיהֶם: בְּעִמְקֵי עֲמָקִים, וְגַם הוּא:\",3,0],[2,122,26,6,\"עָרוֹם שְׁאוֹל נֶגְדּוֹ. לָדַעַת וְלִרְאוֹת אֶת כָּל מַה שֶּׁבְּתוֹכוֹ:\",1,0],[2,122,26,7,\"עַל בְּלִימָה. אֵין כְּלוּם בַּיְּסוֹד, כִּי הֵם עוֹמְדִים בָּאֲוִיר עַל חֹזֶק זְרוֹעוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְדוּנַשׁ פֵּרֵשׁ בְּלִימָה – מִישׁוֹר; כְּמוֹ ״בְּמֶתֶג וָרֶסֶן עֶדְיוֹ לִבְלוֹם״ (תהלים לב:ט). (כָּךְ רָאִיתִי סא״א.)\",1,0],[2,122,26,8,\"וְלֹא נִבְקַע עָנָן. מֵעוֹלָם, שֶׁיִּפְּלוּ מֵימָיו בְּיַחַד:\",1,0],[2,122,26,8,\"תַּחְתָּם. תַּחַת הַמַּיִם:\",2,0],[2,122,26,9,\"מְאַחֵז. בִּמְחִיצוֹת פְּנֵי כִסֵּא הַכָּבוֹד כֻּלּוֹ, כְּגוֹן ״יָשֶׁת חֹשֶׁךְ סִתְרוֹ״ (תהלים יח:יב):\",1,0],[2,122,26,9,\"וּפַּרְשֵׁז. עַל הַכִּסֵּא עֲנָנוֹ, כְּמוֹ וּדְמוּת עַל רָאשֵׁי הַחַיּוֹת רָקִיעַ (יחזקאל א:כב):\",2,0],[2,122,26,10,\"חוֹק חָג. קוֹמְפָּ״שׁ בְּלַעַ״ז, לְשׁוֹן ״וּבַמְּחוּגָה יְתָאֲרֵהוּ״ (ישעיהו מד:יג). סִבְּבוֹ בְּחוֹל, לִהְיוֹת לוֹ (הַחוֹל) חֹק – גְּבוּל עוֹלָם. וְלֹא יַעֲבֹר הַיָּם אוֹתוֹ חוּג, עַד שֶׁיִּכְלֶה אוֹר וְחֹשֶׁךְ:\",1,0],[2,122,26,11,\"יְרוֹפָפוּ. כְּשֶׁבְּרָאָם וְהִקְרִישָׁם הָיוּ רוֹפְפִים, וְגָעַר בָּהֶם וְעָמְדוּ בְּיֹבֶשׁ וּבְחֹזֶק:\",1,0],[2,122,26,11,\"וְיִתְמְהוּ. תּוֹהֶה וְעוֹלֶה (ס״א: כְּאָדָם תּוֹהֶה וְעוֹמֵד) בְּמָקוֹם אֶחָד:\",2,0],[2,122,26,12,\"רָגַע הַיָּם. כְּמוֹ ״עוֹרִי רָגַע״ (איוב ז:ה), נִקְמַט; קְמָטִים קְמָטִים נַעֲשׂוּ, (כָּךְ כְּשֶׁאָמַר ״יִקָּווּ הַמַּיִם״ נֶאֶסְפוּ מִפְּשִׁיטָתָן וְנִקְמְטוּ קְמָטִים קְמָטִים) עַד שֶׁנִּקְווּ לְמָקוֹם אֶחָד הַמּוּכָן לָהֶם (בראשית א:ט):\",1,0],[2,122,26,12,\"מָחַץ רָהַב. מִצְרַיִם קְרוּיִין רְהָבִים (ישעיהו ל:ז):\",2,0],[2,122,26,13,\"בְּרוּחוֹ שָׁמַיִם שִׁפְרָה. בִּדְבָרָיו וּבְרוּחַ פִּיו אִיהֵל, כְּמוֹ ״וְנָטָה אֹהֶל שַׁפְרִירוֹ״ (ירמיה מג:י):\",1,0],[2,122,26,13,\"חוֹלְלָה יָדוֹ. אֶת פַּרְעֹה הַנִּקְרָא ״נָחָשׁ בָּרִיחַ״ (ישעיהו כז:א). לְשׁוֹן חִיל וְצָרָה. וְכֵן בְּמָקוֹם אַחֵר ״הֲלֹא זֹאת הִיא הַמַּחְצֶבֶת רַהַב מְחוֹלֶלֶת תַּנִּין״ (ישעיהו נא:ט). לָשׁוֹן אַחֵר: יִסְּדָה יָדוֹ אֶת לִוְיָתָן, כְּמוֹ ״גְּבָעוֹת חוֹלָלְתִּי״ (משלי ח:כה):\",2,0],[2,122,26,14,\"קְצוֹת דְּרָכָיו. קַלּוֹת וּמוּעָטוֹת, לְפִי שְׁאָר גְּדוֹלוֹת שֶׁבּוֹ:\",1,0],[2,122,26,14,\"וּמַה שֵּׁמֶץ דָּבָר נִשְׁמַע בּוֹ. מָה רֶמֶז דָּבָר אָדָם יָכוֹל לְהָבִין מִפְּעֻלּוֹתָיו. דָּבָר אַחֵר: שֵׁמֶץ כְּמוֹ ״לְשִׁמְצָה״ (שמות לב:כה), לִגְנוּת:\",2,0],[2,122,27,1,\"וַיֹּסֶף. עָמְדוּ רֵיעָיו מֵעֲנוֹת, כַּאֲשֶׁר הוֹכִיחָם אֱלִיהוּא ״כִּי עָמְדוּ וְלֹא עָנוּ עוֹד״ (איוב לב:טז):\",1,0],[2,122,27,2,\"חַי אֵל. שְׁבוּעָה הִיא, כִּי בֶּאֱמֶת הֵסִיר אֶת מִשְׁפָּטִי. וּמִכָּאן דָּרַשׁ רַבִּי יְהוֹשֻׁעַ (סוטה כז:), שֶׁמֵּאַהֲבָה עָבַד אִיּוֹב אֶת הַמָּקוֹם: אֵין אָדָם נוֹדֵר בְּחַיֵּי הַמֶּלֶךְ אֶלָּא אִם כֵּן אוֹהֵב אֶת הַמֶּלֶךְ:\",1,0],[2,122,27,5,\"אִם אַצְדִּיק אֶתְכֶם. אִם אוֹמַר: הַדִּין עִמָּכֶם לְחַיְּבֵנִי:\",1,0],[2,122,27,5,\"לֹא אָסִיר תֻּמָּתִי. לֹא אוֹדֶה לְדִבְרֵיכֶם, לוֹמַר שֶׁאֵינִי תָּם:\",2,0],[2,122,27,6,\"בְּצִדְקָתִי הֶחֱזַקְתִּי. לוֹמַר שֶׁאֲנִי צַדִּיק:\",1,0],[2,122,27,6,\"לֹא יֶחֱרַף לְבָבִי. אוֹתִי מִיָּמַי – מִכָּל דֶּרֶךְ וּמִדָּה שֶׁנָּהַגְתִּי בְּיָמַי, וְעַל כָּרְחוֹ יְהִי כְּרָשָׁע אוֹיְבִי:\",2,0],[2,122,27,8,\"כִּי מַה תִּקְוַת חָנֵף. כִּי לָמָּה אֶהְיֶה רָשָׁע וְגַזְלָן? מַה סוֹפוֹ שֶׁל רָשָׁע הַגּוֹזֵל מָמוֹן?\",1,0],[2,122,27,8,\"כִּי יֵשֶׁל. כִּי יַשְׁלִיךְ הַמָּקוֹם אֶת נַפְשׁוֹ מֵעָלָיו, לְשׁוֹן ״שַׁל נַעַלְךָ״ (שמות ג:ה) ״וְנָשַׁל הַבַּרְזֶל״ (דברים יט:ה):\",2,0],[2,122,27,10,\"אִם עַל שַׁדַּי יִתְעַנָּג. כֶּפֶל הַתְּמִיהָה הִיא, כְּכָל הַתְּמִיהוֹת הַכְּפוּלוֹת; שֶׁכֵּן דֶּרֶךְ הָרִאשׁוֹנָה בְּה״א וְהַשְּׁנִיָּה בְּאִם, כְּמוֹ ״הֲיְרֻצוּן בַּסֶּלַע סוּסִים אִם יַחֲרוֹשׁ בַּבְּקָרִים״ (עמוס ו:יב), ״הֲיֵשׁ בִּלְשׁוֹנִי עַוְלָה וְאִם חִכִּי לֹא יָבִין הַוּוֹת״ (איוב ו:ל). אַף כָּאן: הַצַּעֲקָתוֹ יִשְׁמַע אֵל אִם עַל שַׁדַּי יִתְעַנָּג?! שֶׁמָּא, אוֹ מִי שֶׁהוּא רָשָׁע חָנֵף, יָכוֹל הוּא לְהִתְעַנֵּג וְלִסְמֹךְ עַל יְשׁוּעַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלִקְרֹא אֵלָיו בְּעֵת צָרָתוֹ?! בִּתְמִיהָה:\",1,0],[2,122,27,11,\"אוֹרֶה אֶתְכֶם. מָה הַמִּדָּה שֶׁבְּיַד אֵל, וְדֶרֶךְ אֲשֶׁר עִם שַׁדַּי לֹא אֲכַחֵד. כְּמוֹ ״כִּי יָדַע דֶּרֶךְ עִמָּדִי״ (איוב כג:י):\",1,0],[2,122,27,12,\"כֻּלְּכֶם חֲזִיתֶם. שֶׁזֶּה חֵלֶק אָדָם רָשָׁע:\",1,0],[2,122,27,12,\"וְלָמָּה זֶּה הֶבֶל תֶּהְבָּלוּ. לִהְיוֹת רְשָׁעִים וַחֲנֵפִים:\",2,0],[2,122,27,14,\"אִם יִרְבּוּ בָנָיו לְמוֹ חָרֶב. יִרְבּוּ וְיָמוּתוּ בְּיִסּוּרִים וְתַחֲלוּאִים, עַד כִּי יִשְׂמְחוּ אַלְמְנוֹתָיו בְּמִיתָתָן, וְלֹא תִבְכֶּינָה:\",1,0],[2,122,27,17,\"(וְכֶסֶף נָקִי. כַּסְפּוֹ שֶׁל רָשָׁע לְנָקִי יְחַלְּקֶנּוּ הַקָּדוֹשׁ בָּרוּךְ הוּא):\",1,0],[2,122,27,18,\"בָּנָה כְעָשׁ. כְּתוֹלַע הַבּוֹנֶה חוֹר שֶׁאֵינוֹ מִתְקַיֵּם, וּכְסֻכָּה שֶׁעָשָׂה נוֹצֵר הַתְּאֵנָה (משלי כז:יח) וְהַכֶּרֶם, שֶׁאֵינָהּ שֶׁל קַיָּמָא. (עִנְיָן אַחֵר: נוֹצֵר הַכֶּרֶם – שֶׁאֵינוֹ שׁוֹמְרָהּ בְּכָל עֵת. זֶה שָׁמַעְתִּי (סא״א).)\",1,0],[2,122,27,19,\"עָשִׁיר יִשְׁכַּב. יָמוּת בְּעָשְׁרוֹ, וּפְעָמִים שֶׁלֹּא יֵאָסֵף לִקְבוּרָה:\",1,0],[2,122,27,20,\"בַּלָּהוֹת. שֵׁדִים:\",1,0],[2,122,27,20,\"גְּנָבַתּוּ סוּפָה. וְתַשְׁלִיכֵהוּ לִדְרָאוֹנִים:\",2,0],[2,122,27,22,\"וְיַשְׁלֵךְ עָלָיו. הַמַּשְׁלִיךְ עָלָיו רָעָה, וְלֹא יַחְמֹל:\",1,0],[2,122,27,22,\"מִיָּדוֹ. שֶׁל רָשָׁע וּמִכֹּחוֹ וּמִמְּקוֹמוֹ:\",2,0],[2,122,27,22,\"בָּרוֹחַ יִבְרָח. בֶּן עֲצָתוֹ שֶׁהָיָה מְסַיְּעוֹ בַּתְּחִלָּה, יִבְרַח מֵעֲזוֹר יָדוֹ בִּשְׁעַת כִּשְׁלוֹנוֹ. כְּמוֹ שֶׁעָשָׂה חַרְבוֹנָה לְהָמָן (מגילה טז.):\",3,0],[2,122,27,23,\"יִשְׂפֹּק עָלֵימוֹ כַפֵּימוֹ. הַיּוֹדְעִים (אוֹתוֹ) לְפָנִים, וְעַתָּה רוֹאִים בְּשִׁבְרוֹ:\",1,0],[2,122,28,1,\"כִּי יֵשׁ לַכֶּסֶף מוֹצָא. גַּם זֶה טַעַם אַחֵר לִדְבָרוֹ הָרִאשׁוֹן, שֶׁאָמַר ״בְּצִדְקָתִי הֶחֱזַקְתִּי״ (איוב כז:ו): כִּי לָמָּה אֶהְיֶה רָשָׁע, אִם בִּשְׁבִיל כֶּסֶף וְזָהָב – לַכֹּל יֵשׁ מוֹצָא וְסוֹף, אֲבָל הַחָכְמָה מֵאַיִן תָּבוֹא – זֶה סוֹף הַפָּרָשָׁה – הִיא יְקָרָה מִכֹּל. עַל כֵּן כָּל יָמַי נָתַתִּי לִבִּי עָלֶיהָ לִלְמֹד:\",1,0],[2,122,28,1,\"וּמָקוֹם. יֵשׁ לַזָּהָב, שֶׁמִּשָּׁם יָזוֹקּוּ וְיַתִּיכוּ אוֹתוֹ:\",2,0],[2,122,28,2,\"וְאֶבֶן יָצוּק נְחוּשָׁה. מִן הָהָר יָצַק הָאוּמָּן אֶת הַנְּחוּשָׁה; הֲרֵי תְּחִלָּה וָסוֹף יֵשׁ לְכָל דָּבָר, שֶׁכָּל הָעוֹלָם יִכְלֶה, וְכָל אֲשֶׁר בּוֹ:\",1,0],[2,122,28,3,\"קֵץ שָׂם. הַמָּקוֹם מָתַי תִּהְיֶה הַחֹשֶׁךְ, שֶׁהַשָּׁמַיִם נִמְלָחוּ וְהָאָרֶץ תִּבְלֶה (ישעיהו נא:ו), וּלְכָל תַּכְלִית דָּבָר – הוּא חוֹקֵר לוֹ:\",1,0],[2,122,28,3,\"אֶבֶן. אֲשֶׁר מִשָּׁם יָצָא לוֹ חֹשֶׁךְ וְצַלְמָוֶת. אֶבֶן מְקוֹם מוֹצָא פּוּרְעָנוּת. לָכֵן נִקְרָא אֶבֶן בִּמְקוֹם פּוּרְעָנוּת, כְּאָדָם הַנּוֹגֵף אֶת רַגְלָיו בָּאֶבֶן, שֶׁיֵּשׁ לוֹ צַעַר. כָּךְ שָׁמַעְתִּי. כְּמוֹ ״קַו תֹּהוּ וְאַבְנֵי בֹהוּ״ (ישעיהו לד:יא), ״דְּמִן טוּרָא אִתְגְּזֶרֶת אֶבֶן וְגוֹמֵר״ (דניאל ב:מה):\",2,0],[2,122,28,4,\"פָּרַץ נַחַל. עַל סְדוֹם וַעֲמוֹרָה נַחֲלֵי אֵשׁ וְגָפְרִית (בראשית יט:כד):\",1,0],[2,122,28,4,\"מֵעִם גָּר. מִמָּקוֹם שֶׁהוּא נוֹבֵעַ וְנוֹגֵר:\",2,0],[2,122,28,4,\"הַנִּשְׁכָּחִים מִנִּי רָגֶל. אֵלּוּ אַנְשֵׁי סְדוֹם, שֶׁשִּׁכְּחוּ תּוֹרַת רַגְלֵי אוֹרְחִים מֵאַרְצָם. שֶׁהָיוּ מַשְׁכִּיבִים הָאוֹרֵחַ בְּמִטָּה; אִם הָיָה אָרוֹךְ יוֹתֵר, מְקַטְּעִין רַגְלָיו, וְאִם הָיָה קָצָר, מַאֲרִיכִין אוֹתוֹ. כָּךְ מְפֹרָשׁ בָּאַגָּדָה (סנהדרין קט:):\",3,0],[2,122,28,4,\"דַּלּוּ. עַל יְדֵי פְּרִיצַת נַחַל זֶה, וּמֵאֱנוֹשׁ נָעוּ:\",4,0],[2,122,28,5,\"אֶרֶץ. אֲשֶׁר מִמֶּנָּה יֵצֵא לֶחֶם נֶהְפַּךְ מְקוֹמָהּ כְּמוֹ אֵשׁ:\",1,0],[2,122,28,6,\"מְקוֹם סַפִּיר. הָיוּ אֲבָנֶיהָ:\",1,0],[2,122,28,7,\"לֹא יְדָעוֹ עָיִט. לֹא עָבַר עֲלֵיהֶן חַיִל שֶׁל לִיסְטִין:\",1,0],[2,122,28,7,\"וְלֹא שְׁזָפַתּוּ עֵין אַיָּה. לְפִי שֶׁהִיא רוֹאָה יוֹתֵר מִשְּׁאָר עוֹפוֹת, וּלְכָךְ נִקְרְאָה רָאָה (דברים יד:יג), שֶׁהִיא עוֹמֶדֶת בְּבָבֶל וְרוֹאָה נְבֵלוֹת בְּאֶרֶץ יִשְׂרָאֵל. כָּךְ מְפֹרָשׁ בְּאַגָּדַת (חולין סג.). כְּלוֹמַר: לֹא חֲפָרוּהָ מְרַגְּלִים:\",2,0],[2,122,28,8,\"לֹא עָדָה עָלָיו. עָבַר, כְּדִמְתַרְגְּמִינָן ״אֲשֶׁר עָבַר בֵּין הַבְּתָרִים״ (בראשית טו:יז): ״דַּעֲדָא״ (תרגום אונקלוס):\",1,0],[2,122,28,8,\"שַׁחַץ וְשָׁחַל. מִשִּׁבְעָה שֵׁמוֹת הָאַרְיֵה הֵם (סנהדרין צה.). שִׁשָּׁה שֵׁמוֹת יֵשׁ לָאַרְיֵה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מָה עָשָׂה:\",2,0],[2,122,28,9,\"בַּחַלָּמִישׁ שָׁלַח יָדוֹ. וְהָפַךְ שָׁרְשֵׁי הֶהָרִים מִלְמַעְלָה לְמַטָּה:\",1,0],[2,122,28,10,\"בַּצּוּרוֹת יְאֹרִים בִּקֵּעַ. חוֹזֵר לִתְחִלַּת עִנְיָנוֹ שֶׁאָמַר כִּי לְכָל דָּבָר יֵשׁ מוֹצָא, וּבַצּוּרוֹת בִּקֵּעַ לְמוֹצָא הַיְאוֹרִים וְכֵן כָּל יְקָר רָאֲתָה עֵינוֹ. מֵהֵיכָן יָצָא לַבְּרִיּוֹת (כְּמוֹ שֶׁעָשָׂה לְיִשְׂרָאֵל ״הִכָּה צוּר וַיָּזוּבוּ מַיִם״ (תהלים עח:כ)):\",1,0],[2,122,28,11,\"מִבְּכִי נְהָרוֹת חִבֵּשׁ. בִּבְרִיאַת הָעוֹלָם, כְּשֶׁבָּכוּ מַיִם הַתַּחְתּוֹנִים. בְּכִי כְּמוֹ ״נִבְכֵי יָם״ (איוב לח:טז):\",1,0],[2,122,28,11,\"חִבֵּשׁ. כְּמוֹ ״וַיַּחֲבֹשׁ אֶת־חֲמֹרוֹ״ (בראשית כב:ג). כָּךְ שָׁמַעְתִּי. [ס״א: מִבְּכִי וְגוֹ׳. מִפְּנֵי בְּכִיָּתָן שֶׁל יִשְׂרָאֵל, שֶׁהָיוּ בוֹכִין ״לֵאמֹר מַה נִּשְׁתֶּה״ (שמות טו:כד), חָבַשׁ וְתִקֵּן לָהֶם נַהֲרֵי מַיִם מִן הַסֶּלַע; ״וַיַּחֲבֹשׁ לָהֶם״ (ויקרא ח:יג) – מְתַרְגֵּם: ״וְאַתְקֵין״ (תרגום אונקלוס).]\",2,0],[2,122,28,11,\"וְתַעֲלֻמָהּ יוֹצִיא אוֹר. חַלּוֹן יֵשׁ בָּרָקִיעַ וּשְׁמוֹ תַּעֲלוּמָה, מִשָּׁם תּוֹלְדוֹת הַשֶּׁמֶשׁ לִתְקוּפָתוֹ (פרקי רבי אליעזר ו). כְּלוֹמַר: לְכָל דָּבָר יֵשׁ מוֹצָא וְסוֹף, רַק לַחָכְמָה – לֹא מוֹצָא לָהּ, אֶלָּא מִפִּיו, וְלֹא סוֹף עוֹלָמוֹת:\",3,0],[2,122,28,12,\"וְהַחָכְמָה. הַתּוֹרָה:\",1,0],[2,122,28,13,\"וְלֹא תִמָּצֵא בְּאֶרֶץ הַחַיִּים. בְּמִי שֶׁמְּחַיֶּה, אֶלָּא בְּמִי שֶׁמֵּמִית עַצְמוֹ עָלֶיהָ בִּיגִיעָה וּבְרָעָבוֹן:\",1,0],[2,122,28,14,\"תְּהוֹם אָמַר לֹא בִי הִיא. אִם תִּשְׁאָלֶנָּה לְיוֹרְדֵי תְהוֹם הָעוֹסְקִים בְּמוֹצָא מַרְגָּלִיּוֹת וּבְמוֹצָא זָהָב וָכֶסֶף מִמְּקוֹם תְּהוֹמוֹת הָאָרֶץ, יֹאמְרוּ לְךָ: לֹא בִי הִיא. אֵינִי בָּקִי בְּהוֹרָאָה (שבת פט.. עיין שם היטב וצריך עיון):\",1,0],[2,122,28,14,\"וְיָם אָמַר. וְיוֹרְדֵי הַיָּם לִסְחוֹרָה יֹאמְרוּ לְךָ לֹא עִמָּדִי חָכְמָה. לָמָּה? לְפִי שֶׁאֵינָם יְכוֹלִים לִקְנוֹתָהּ כִּשְׁאָר פְּרַקְמַטְיָא, לָתֵת מֵעָשְׁרָם בְּדָמֶיהָ. וּבָאַגָּדָה הוּא אוֹמֵר (שבת פט.), שֶׁבִּשְׁעַת מַתַּן תּוֹרָה בָּא הַשָּׂטָן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר לוֹ: הֵיכָן תּוֹרָה? אָמַר לוֹ: אֵצֶל בֶּן עַמְרָם. בָּא לוֹ אֵצֶל מֹשֶׁה, אָמַר לוֹ: הֵיכָן תּוֹרָה? אֵצֶל יָם. בָּא לוֹ אֵצֶל יָם, אָמַר לוֹ: הֵיכָן תּוֹרָה? לֹא בִי הִיא; לֵךְ אֵצֶל בֶּן עַמְרָם. בָּא לוֹ אֵצֶל בֶּן עַמְרָם, אָמַר לוֹ: הֵיכָן תּוֹרָה? אֵצֶל תְּהוֹם. בָּא לוֹ אֵצֶל תְּהוֹם, אָמַר לוֹ: הֵיכָן תּוֹרָה? אָמַר לוֹ: אֵין עִמָּדִי; לֵךְ אֵצֶל בֶּן עַמְרָם. בָּא לוֹ אֵצֶל בֶּן עַמְרָם, אָמַר לוֹ: הֵיכָן תּוֹרָה? אֵצֶל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְזֶהוּ שֶׁאָמַר: תְּהוֹם אָמַר לֹא בִי הִיא וְיָם אָמַר אֵין עִמָּדִי:\",2,0],[2,122,28,15,\"לֹא יֻתַּן סְגוֹר. ״זָהָב סָגוּר״ (מלכים א ו:כ) זֶהוּ זָהָב טוֹב, שֶׁבְּשָׁעָה שֶׁנִּפְתָּח, כָּל חֲנֻיּוֹת שֶׁל זָהָב נִסְגָּרוֹת:\",1,0],[2,122,28,16,\"לֹא תְסֻלֶּה. לֹא תִשְׁתַּבַּח, לְשׁוֹן ״סֹלּוּ לָרֹכֵב בָּעֲרָבוֹת״ (תהלים סח:ה). הַמְשַׁבְּחָהּ לוֹמַר: חֲשׁוּבָה הִיא כְּכֶתֶם אוֹפִיר וּכְשֹׁהַם יָקָר – לֹא שֶׁבַח הוּא לָהּ, וְכֵן ״הַמְסֻלָּאִים בַּפָּז״ (איכה ד:ב):\",1,0],[2,122,28,17,\"זָהָב. טָהוֹר, מַנְהִיר כְּמַרְגָּלִית:\",1,0],[2,122,28,17,\"וּתְמוּרָתָהּ וְגוֹ׳. וּתְמוּרָתָהּ לֹא בִּכְלִי פָז:\",2,0],[2,122,28,18,\"רָאמוֹת וְגָבִישׁ. שֵׁמוֹת אֲבָנִים טוֹבוֹת שֶׁבַּיָּם הֵם:\",1,0],[2,122,28,18,\"לֹא יִזָּכֵר. אֶצְלָהּ:\",2,0],[2,122,28,19,\"פִּטְדַת כּוּשׁ. אֶבֶן טוֹבָה הִיא, כְּמוֹ ״אֹדֶם פִּטְדָה״ (שמות כח:יז). כֶּתֶם הִיא קְבוּצַת עֲדִי לְתַכְשִׁיטֵי נָשִׁים, וְנִקְרֵאת הַקְּבוּצָה כֶּתֶם בִּלְשׁוֹן עִבְרִי, וּבִלְשׁוֹן עֲרָבִי אַלְחַלוּ, וְהוּא ״נֶזֶם זָהָב וַחֲלִי כָתֶם״ (משלי כה:יב). וְכֵן ״וַתַּעַד נִזְמָהּ וְחֶלְיָתָהּ״ (הושע ב:טו). וְיֵשׁ פּוֹתְרִים כֶּתֶם – כֶּתֶר, וְלֹא נָכוֹן. כִּי לֹא מָצִינוּ פְּעֻלָּה בְּלָשׁוֹן זֶה, כַּאֲשֶׁר מָצִינוּ בִּלְשׁוֹן כֶּתֶר: מַכְתִּיר, כּוֹתָרוֹת:\",1,0],[2,122,28,21,\"וּמֵעוֹף הַשָּׁמַיִם. מַלְאָכִים הַמְעוֹפְפִים:\",1,0],[2,122,28,22,\"אֲבַדּוֹן וָמָוֶת אָמְרוּ. הַמְּאַבְּדִין וּמְמִיתִין עַצְמָן עָלֶיהָ אָמְרוּ: בְּאָזְנֵינוּ שָׁמַעְנוּ שִׁמְעָהּ, שֶׁהַמִּיגֵּעַ בָּהּ, מִתְקַיֶּמֶת בּוֹ. וְיֵשׁ אוֹמְרִים, כַּאֲשֶׁר בָּאַגָּדָה אֲשֶׁר פֵּרַשְׁתִּי לְמַעְלָה, שֶׁבָּא הַשָּׂטָן לִפְנֵי הַמָּקוֹם, אָמַר לוֹ: הֵיכָן תּוֹרָה? אָמַר לוֹ וְכוּ׳. וְהַיְינוּ דִּכְתִיב: אֲבַדּוֹן וָמָוֶת אָמְרוּ בְּאָזְנֵינוּ שָׁמַעְנוּ שִׁמְעָהּ. כְּשֶׁנִּתְּנָה לְיִשְׂרָאֵל. אֲבָל:\",1,0],[2,122,28,23,\"אֱלֹהִים הֵבִין דַּרְכָּהּ וְהוּא יָדַע אֶת מְקוֹמָהּ. שֶׁיּוֹדֵעַ הוּא הֵיכָן שׁוֹרָה. וְגַם יְשַׁבְּחוּהָ וְיֹאמְרוּ לָהּ, כִּי אֱלֹהִים הֵבִין דַּרְכָּהּ. נִסְתַּכֵּל בָּהּ וּבָרָא אֶת הָעוֹלָם, בְּאוֹתִיּוֹתֶיהָ כְּסִדְרָם וּמִשְׁקָלָן יָצַר כָּל הַיְּצוּרִים; כַּאֲשֶׁר כָּתוּב בְּסוֹד סֵפֶר יְצִירָה:\",1,0],[2,122,28,24,\"כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט. בָּהּ הֵיאַךְ יִבְנֵם וְיִבְרָאֵם, וְתַחַת כָּל הַשָּׁמַיִם צָרְכֵי בְּרִיָּתָן רָאָה בָּהּ:\",1,0],[2,122,28,25,\"לַעֲשׂוֹת וְגוֹ׳. בָּהּ מִשְׁקָל לָרוּחַ, לְכָל אֶרֶץ לְפִי כֹּחָהּ. וְכֵן הַמַּיִם לְפִי הַמִּדָּה, לְפִי מַה שֶּׁהָיְתָה אֶרֶץ צְרִיכָה לְהַשְׁקוֹתָהּ. יֵשׁ אֶרֶץ נְגוּבָה, וּצְרִיכָה הַרְבֵּה גְּשָׁמִים, וְיֵשׁ אֶרֶץ שֶׁאֵינָהּ צְרִיכָה כָּל כָּךְ:\",1,0],[2,122,28,26,\"חֹק. גְּזֵרָה קְצוּבָה לְפִי כָּל אֲרָצוֹת, וּמַעְיָן וּפֶלֶג לְהַשְׁקוֹת כָּל אֶרֶץ וָאֶרֶץ. וּבַעֲשׂוֹתוֹ דֶּרֶךְ לְכָל הַחֲזִיזִים, שֶׁלֹּא יֵצְאוּ שְׁנֵי קוֹלוֹת דֶּרֶךְ נֶקֶב אֶחָד, פֶּן יַחֲרִיב אֶת הָעוֹלָם:\",1,0],[2,122,28,27,\"אָז רָאָה. רָאָה אוֹתָהּ, נִסְתַּכֵּל בָּהּ, וּבַעֲצָתָהּ יַעֲשֶׂה הַכֹּל:\",1,0],[2,122,28,27,\"וַיְסַפְּרָהּ. סִפֵּר אוֹתִיּוֹתֶיהָ: כְּפוּלוֹת וּפְשׁוּטוֹת; רִאשׁוֹנָה וְאֶמְצָעִית וְאַחֲרוֹנִית – הִיא ׳אֱמֶת׳, חוֹתָמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא; וְכֵן בִּשְׁאָר סְדָרִים בָּרָא כָּל דָּבָר וְדָבָר בָּאוֹתִיּוֹת הַלָּלוּ. וְהַכֹּל מְפֹרָשׁ בְּסוֹד סֵפֶר ׳יְצִירָה׳:\",2,0],[2,122,28,27,\"הֱכִינָהּ. זִמְּנָהּ לִיצִירָה:\",3,0],[2,122,28,28,\"הֵן יִרְאַת אֲדֹנָי הִיא חָכְמָה. זוֹ צְרִיכָה לָזוֹ, וְאֵין חָכְמָה יָפָה בְּלֹא יִרְאָה:\",1,0],[2,122,29,2,\"(מענה איוב):מִי יִתְּנֵנִי כְיַרְחֵי קֶדֶם. כְּיָמִים קַדְמוֹנִים, שֶׁהָיִיתִי בִּגְדֻלָּתִי:\",1,0],[2,122,29,3,\"בְּהִלּוֹ נֵרוֹ. לְשׁוֹן אוֹר וְשִׂמְחָה:\",1,0],[2,122,29,3,\"לְאוֹרוֹ. הָיִיתִי הוֹלֵךְ; בְּכָל חֹשֶׁךְ וְצָרָה שֶׁהָיְתָה בָּאָה לָעוֹלָם, לִי הָיָה אוֹר:\",2,0],[2,122,29,4,\"בִּימֵי חָרְפִּי. בִּימֵי קַדְמוּתִי, לָשׁוֹן אֲרַמִּי הוּא: ״חַרְפֵּי וְאַפְּלֵי״ (נידה סה:):\",1,0],[2,122,29,4,\"בְּסוֹד אֱלוֹהַּ עֲלֵי אָהֳלִי. כְּשֶׁהָיוּ כְּשֵׁרֵי הַדּוֹר בָּאִים לְאָהֳלִי לְהִוָּסֵד בְּדִבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּתּוֹרָה וּבְ׳גֶדֶר סְיָג לְשָׁעָה׳:\",2,0],[2,122,29,5,\"נְעָרָי. מְשָׁרְתַי:\",1,0],[2,122,29,6,\"הֲלִיכַי. רַגְלַי:\",1,0],[2,122,29,6,\"בְּחֵמָה. כְּמוֹ בְּחֶמְאָה:\",2,0],[2,122,29,6,\"וְצוּר יָצוּק עִמָּדִי פַּלְגֵי שָׁמֶן. כְּלוֹמַר: נַחַת רוּחַ וְכָל תַּאֲוַת לֵב, הַנּוֹחִים כְּנַחֲלֵי שֶׁמֶן:\",3,0],[2,122,29,6,\"יָצוּק. כְּמוֹ ״וְיָצַקְתָּ״ (שמות כה:יב):\",4,0],[2,122,29,7,\"קָרֶת. תִּקְרָה גְּבוֹהָה מוּכֶנֶת כְּכִסֵּא, לָשֶׁבֶת לְזִקְנֵי הָעִיר:\",1,0],[2,122,29,7,\"בָּרְחוֹב וְגוֹ׳. וְכַאֲשֶׁר בָּרְחוֹב הָיִיתִי מֵכִין מוֹשָׁבִי:\",2,0],[2,122,29,8,\"הָיוּ נְעָרִים רוֹאִים אוֹתִי וְנֶחְבָּאִים, וִישִׁישִׁים עָמְדוּ מִפָּנַי:\",1,0],[2,122,29,9,\"שָׂרִים עָצְרוּ בְמִלִּים. וּמְצַפִּים שֶׁאֶפְתַּח אֲנִי תְּחִלָּה:\",1,0],[2,122,29,11,\"כִּי אֹזֶן. אֲשֶׁר שָׁמְעָה מִלָּתִי וַתְּאַשְּׁרֵנִי:\",1,0],[2,122,29,11,\"וְעַיִן רָאֲתָה. בְּכָל מָקוֹם בְּגָדְלִי וְכֹשֶׁר מִדָּתִי:\",2,0],[2,122,29,13,\"בִּרְכַּת אוֹבֵד. אָדָם מֵת בַּעֲוֹנוֹ וְנִטְרַד:\",1,0],[2,122,29,13,\"עָלַי תָּבֹא. כִּי הָיִיתִי זָן אֶת בָּנָיו וְאֶת אִשְׁתּוֹ. וְרַבּוֹתֵינוּ אָמְרוּ (בבא בתרא טז.), שֶׁהָיָה גּוֹזֵל שְׂדֵה יְתוֹמִים וּמַשְׁבִּיחָהּ וּמַחֲזִירָהּ לָהֶם. וּפְשָׁטֵיהּ דִּקְרָא אֵינוֹ נִרְאֶה כָּךְ, שֶׁאֵין קָרוּי אוֹבֵד – אֶלָּא דָּבָר שֶׁהוּא עַצְמוֹ אוֹבֵד; כְּמוֹ ״כִּכְלִי אֹבֵד״ (תהלים לא:יג), וְכֵן ״תָּעִיתִי כְּשֶׂה אֹבֵד״ (תהלים קיט:קעו); ״צֹאן אֹבְדוֹת״ (ירמיה נ:ו):\",2,0],[2,122,29,13,\"וְלֵב אַלְמָנָה אַרְנִין. שֶׁהָיָה מַטִּיל שְׁמוֹ עַל אַלְמָנוֹת, לֵאמֹר: קְרוֹבָתִי הִיא; אוֹ: אֲנִי אַשִּׂיאֶנָּה! כְּדֵי שֶׁיִּקְפְּצוּ עָלֶיהָ תּוֹבְעִים:\",3,0],[2,122,29,14,\"צֶדֶק לָבַשְׁתִּי וַיִּלְבָּשֵׁנִי. רָדַפְתִּי אַחֲרֵי הַצֶּדֶק וְהוּא נִמְצָא לִי כִּמְעִיל וְצָנִיף, שֶׁהֵם תַּכְשִׁיטִים נָאִים; כֵּן הָיָה מִשְׁפָּטִי נָאֶה וְטָהוֹר:\",1,0],[2,122,29,18,\"וָאֹמַר עִם קִנִּי אֶגְוָע. בִּשְׁבִיל כֹּשֶׁר מִדָּתִי, הָיִיתִי אוֹמֵר בְּלִבִּי: כְּשֶׁאָמוּת יִהְיֶה קִנִּי וּבֵיתִי נָכוֹן עִמִּי:\",1,0],[2,122,29,18,\"וְכַחוֹל אַרְבֶּה יָמִים. עוֹף וּשְׁמוֹ חוֹל. וְלֹא נִקְנְסָה עָלָיו מִיתָה, שֶׁלֹּא טָעַם מֵעֵץ הַדַּעַת; וּלְבַסּוֹף אֶלֶף שָׁנָה מִתְחַדֵּשׁ וְחוֹזֵר לְנַעֲרוּתוֹ:\",2,0],[2,122,29,19,\"שָׁרְשִׁי פָתוּחַ וְגוֹ׳. כָּל זֶה הָיִיתִי אוֹמֵר בְּלִבִּי, שֶׁלֹּא יִיבַשׁ שָׁרְשִׁי וְלֹא יָמוּת קְצִירִי; כְּמוֹ ״וְעָשָׂה קָצִיר״ (איוב יד:ט) – וְהֵן יוֹנְקוֹת עֲנָפִים רַכִּים שֶׁל אִילָן. וְאָמַרְתִּי:\",1,0],[2,122,29,20,\"שֶׁכְּבוֹדִי. יִתְחַדֵּשׁ עִמָּדִי תָּמִיד:\",1,0],[2,122,29,20,\"וְקַשְׁתִּי. וְאֵיתָנִי תַּחֲלִיף תָּמִיד לְטוֹבָה:\",2,0],[2,122,29,21,\"לִי שָׁמְעוּ וְיִחֵלּוּ. הַשּׁוֹמְעִים דְּבָרַי הָיוּ מְיַחֲלִים שֶׁיִּתְקַיְּמוּ, וְהָיוּ מִתְקַיְּמוֹת. כִּי מָסֹרֶת חָכְמָה הָיָה בְּיָדִי:\",1,0],[2,122,29,22,\"תִּטֹּף מִלָּתִי. לְשׁוֹן נְבוּאָה, וְכֵן ״לֹא תַטִּיף עַל בֵּית יִשְׂחָק״ (עמוס ז:טז). כְּלוֹמַר: כִּנְבוּאָה הָיָה דְבָרִי:\",1,0],[2,122,29,23,\"לְמַלְקוֹשׁ. לִזְמַן אָרוֹךְ הָיוּ מְדַבְּרִים, כִּי רוֹב שְׁעוֹתֵיהֶם שְׁתִיקָה, שֶׁהָיוּ תְּאֵבִים לִשְׁמוֹעַ דְּבָרַי:\",1,0],[2,122,29,24,\"לֹא יַאֲמִינוּ. שֶׁאֲנִי מְשַׂחֵק עִמָּהֶם, מִפְּנֵי חֲשִׁיבוּתִי:\",1,0],[2,122,29,24,\"וְאוֹר פָּנַי לֹא יַפִּילוּן. הָיוּ יְרֵאִים לְהִתְקָרֵב אֵלַי וּלְהָגִיס לִבָּם בִּי:\",2,0],[2,122,29,25,\"אֶבְחַר דַּרְכָּם. כָּל דַּרְכֵיהֶם וַעֲצָתָם אֲנִי הָיִיתִי בּוֹחֵר לָהֶם, שֶׁהָיוּ שׁוֹאֲלִים לִי: אֵיזֶה דֶּרֶךְ נֵלֵךְ? וּמַה נַּעֲשֶׂה?\",1,0],[2,122,29,25,\"וְאֵשֵׁב רֹאשׁ. אִם הָיוּ מְסֻבִּים, אֲנִי הָיִיתִי מֵסֵב בְּרֹאשׁ הַמְּסֻבִּים:\",2,0],[2,122,30,2,\"גַּם כֹּחַ יְדֵיהֶם לָמָּה. הָיָה לִי בְּאוֹתָן הַיָּמִים רְשָׁעִים הָיוּ, וְלֹא תּוֹעֶלֶת בָּהֶם; כִּי פֻּרְעָנוּת בָּא עַל יָדָם:\",1,0],[2,122,30,2,\"עָלֵימוֹ אָבַד כָּלַח. זִקְנָה:\",2,0],[2,122,30,3,\"בְּחֶסֶר וּבְכָפָן. הָיוּ גַּלְמוּד:\",1,0],[2,122,30,3,\"הָעוֹרְקִים צִיָּה. שֶׁמַּבְרִיחִין אוֹתָן בְּיָמָיו מִקֶּרֶב בְּנֵי אָדָם, לֵילֵךְ בַּחֹשֶׁךְ:\",2,0],[2,122,30,3,\"אֶמֶשׁ שׁוֹאָה וּמְשׁוֹאָה. בְּרוּאִינָ״א בְּלַעַ״ז:\",3,0],[2,122,30,4,\"הַקּוֹטְפִים מַלּוּחַ עֲלֵי שִׂיחַ. בִּהְיוֹתָם בַּמִּדְבָּרוֹת הָיוּ קוֹטְפִים לָהֶם מְלוּחִים עַל אִילָנוֹת הַיְּעָרִים וְאוֹכְלִים. מַלּוּחַ שֵׁם עֵשֶׂב הוּא, וּבִלְשׁוֹן אֲרַמִּי נִקְרָא קָקוּלִין (ירושלמי פאה ד), וּבִלְשׁוֹן מִשְׁנָה מְלוּחִים, מַצוֹ״שׁ בְּלַעַ״ז, כְּאוֹתָהּ שֶׁשָּׁנִינוּ (קדושין סו.): הֶעֱלוּ מְלוּחִים עַל שֻׁלְחָנוֹת שֶׁל זָהָב:\",1,0],[2,122,30,4,\"שִׂיחַ. אִילָן, כְּמוֹ ״אַחַד הַשִּׂיחִים״ (בראשית כא:טו):\",2,0],[2,122,30,5,\"מִן גֵּו. מִן קֶרֶב עִיר הָיוּ נִגְרָשִׁין:\",1,0],[2,122,30,6,\"בַּעֲרוּץ נְחָלִים. יֵשׁ אֶרֶץ מְלוּחָה, מִתְבַּקַּעַת, שֶׁשָּׁם הָיוּ שׁוֹכְבִים בְּחוֹרֵי הֶעָפָר וְחוֹרֵי נְקִיקֵי הַסְּלָעִים:\",1,0],[2,122,30,6,\"וְכֵפִים. תַּרְגּוּם שֶׁל ״סְלָעִים״ (מלכים א יט:יא). דָּבָר אַחֵר: בַּעֲרוּץ נְחָלִים. הוּא הַנְּקִיק שֶׁעוֹשֶׂה הַנַּחַל סְבִיבוֹתָיו:\",2,0],[2,122,30,7,\"חָרוּל יְסֻפָּחוּ. אוֹרְשִׁיאַ״שׁ בְּלַעַ״ז. הָיוּ נֶאֱסָפִים, כְּמוֹ ״וְנִסְפְּחוּ עַל בֵּית יַעֲקֹב״ (ישעיהו יד:א):\",1,0],[2,122,30,8,\"נִכְאוּ. בְּיָמַי מִן הָאָרֶץ, שֶׁהָיִיתִי מַשְׁפִּילָם; לְשׁוֹן ״נְכֵה רוּחַ״ (ישעיה סו:ב):\",1,0],[2,122,30,11,\"כִּי יִתְרִי פִּתַּח. יֶתֶר קַשְׁתִּי פִּתַּח (כְּמוֹ שֶׁאָמַרְתִּי לְמַעְלָה וְקַשְׁתִּי תַּחְלִיף), כְּלוֹמַר: כֹּחִי הֵתִישׁ מִי שֶׁבְּיָדוֹ לַעֲשׂוֹת:\",1,0],[2,122,30,11,\"וְרֶסֶן מִפָּנַי שִׁלֵּחוּ. רִסְנִי שֶׁהָיוּ מְרֻסָּנִים בּוֹ, שִׁלְּחוּהוּ מִפָּנַי, כִּי אֵינָם יְרֵאִים מֵעַתָּה מִמֶּנִּי:\",2,0],[2,122,30,12,\"עַל יָמִין. עַל יְמִינִי עוֹמְדִים פִּרְחָחִים קְטַנִּים, כִּשְׁאָר הֶדְיוֹטִים; שֶׁאֵינִי חָשׁוּב בְּעֵינֵיהֶם לְהִכָּנַע מִפָּנַי:\",1,0],[2,122,30,12,\"רַגְלַי שִׁלֵּחוּ. אִם הַמָּקוֹם צַר לָהֶם, דּוֹחֲפִים אוֹתִי הָלְאָה:\",2,0],[2,122,30,12,\"וַיָּסֹלּוּ עָלַי אָרְחוֹת אֵידָם. כָּל דֶּרֶךְ נְבָלָה שֶׁיֵּשׁ לָהֶם לַעֲשׂוֹת, עוֹשִׂים מְסִלָּתָן לְפָנַי וְאֶצְלִי, וְלֹא יִירָאוּ:\",3,0],[2,122,30,13,\"נָתְסוּ נְתִיבָתִי. הַטּוֹבָה וְאֵין חוֹשְׁשִׁין לָהּ, נָתְסוּ כְּמוֹ ״נָתְצוּ״ (מלכים ב כה:י) וְסָמֶ״ךְ מִתְחַלֶּפֶת בְּצָדִ״י:\",1,0],[2,122,30,13,\"לְהַוָּתִי יוֹעִילוּ. לְהַקְנִיטֵנִי מוֹסִיפִין:\",2,0],[2,122,30,14,\"כְּפֶרֶץ רָחָב. שֶׁבַּגָּדֵר שֶׁהַכֹּל בָּאִים וְעוֹבְרִים שָׁם, כֵּן יֶאֱתָיוּ יַחַד עָלַי לְהַכְלִימֵנִי:\",1,0],[2,122,30,14,\"תַּחַת שׁוֹאָה הִתְגַּלְגָּלוּ. כְּלוֹמַר: מִתְגַּלְגְּלִים וּבָאִין בְּסֵתֶר, עַד שֶׁמַּגִּיעִין אֶצְלִי לְהַקְנִיטֵנִי, כְּדֵי שֶׁלֹּא אֶשָּׁמֵט מֵהֶם:\",2,0],[2,122,30,15,\"הָהְפַּךְ עָלַי. נֶהְפַּךְ עָלַי:\",1,0],[2,122,30,15,\"בַּלָּהוֹת. שֵׁדִים:\",2,0],[2,122,30,15,\"תִּרְדֹּף כָּרוּחַ. רָעָה:\",3,0],[2,122,30,15,\"אֶת נְדִיבָתִי. רוּחַ נְדִיבָה שֶׁהָיָה שׁוֹרָה עָלַי מִתְּחִלָּה:\",4,0],[2,122,30,16,\"וְעַתָּה. אֶל הַצָּרָה הַזֹּאת תִּשְׁתַּפֵּךְ נַפְשִׁי, כְּאָדָם שֶׁתִּתְפַּעֵם רוּחוֹ; כִּי יֹאחֲזוּנִי, וְכוֹפִין אוֹתִי לְהִשְׁתַּפֵּל נַפְשִׁי:\",1,0],[2,122,30,16,\"יְמֵי עֹנִי. שֶׁאֲנִי בָּהֶם:\",2,0],[2,122,30,17,\"נִקַּר. כְּמוֹ ״הַעֵינֵי הָאֲנָשִׁים הָהֵם תְּנַקֵּר״ (במדבר טז:יד). נִקַּר. פוֹרִיי״ר בְּלַעַ״ז; הַתּוֹלָעִים מְנַקְּרִין בְּשָׂרִי מֵעַל עַצְמִי:\",1,0],[2,122,30,17,\"וְעֹרְקַי. גִּידַי, אֵין לָהֶם מְנוּחָה. ׳גִּיד׳ בִּלְשׁוֹן עֲרָבִי ׳עוֹרֶק׳; כָּךְ פֵּירֵשׁ דּוּנַשׁ. לָשׁוֹן אַחֵר: עֹרְקַי. רוֹדְפַי, הַמַּבְרִיחִין אוֹתִי:\",2,0],[2,122,30,18,\"יִתְחַפֵּשׂ לְבוּשִׁי. מִשְׁתַּנֶּה לְבוּשִׁי, גֶּלֶד אַחַר גֶּלֶד; כְּשֶׁאָדָם פּוֹשֵׁט אֶת בְּגָדָיו וְלוֹבֵשׁ בְּגָדִים אֲחֵרִים, מְשֻׁנִּים מֵרִאשׁוֹנִים, קוֹרֵא אוֹתָם ׳בִּגְדֵי חֹפֶשׂ׳; כְּמוֹ ״הִתְחַפֵּשׂ וָבֹא בַמִּלְחָמָה״ (מלכים א כב:ל), וּמְתֻרְגָּם: ״אִשְׁתַּנִּי״ (תרגום יונתן):\",1,0],[2,122,30,18,\"כְּפִי כֻתָּנְתִּי יַאַזְרֵנִי. שֶׁאוֹזֵר וּמַעֲנִיק צַוָּארִי, כֵּן יַאַזְרֵנִי אוֹתִי לְבוּשִׁי כָּל סְבִיבִי:\",2,0],[2,122,30,19,\"הוֹרָנִי לַחֹמֶר. הוֹרָנִי יְלַמְּדֵנִי הַשְּׁחִין הַזֶּה לֵישֵׁב כְּמוֹ בַחֹמֶר, כְּמוֹ שֶׁאָמַרְנוּ ״וְהוּא יוֹשֵׁב בְּתוֹךְ הָאֵפֶר״ (איוב ב:ח). דָּבָר אַחֵר: הוֹרָנִי לַחֹמֶר פֵּירוּשׁוֹ: הִשְׁלִיכַנִי, לְשׁוֹן ״יָרָה בַיָּם״ (שמות טו:ד):\",1,0],[2,122,30,19,\"וָאֶתְמַשֵּׁל. נִדְמֵיתִי. וּבְמִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא בובר, וישלח ח): אָמַר רַבִּי בֶּרֶכְיָה: סָרֵס אֶת הַמִּקְרָא: אֲנִי נִמְשַׁלְתִּי לְאַבְרָהָם בְּצִדְקָתִי שֶׁקָּרָא עַצְמוֹ ״עָפָר וָאֵפֶר״ (בראשית יח:כז), וְהוּא דָּנַנִּי כְּרִשְׁעֵי דּוֹר הַפְּלַגָּה (שֶׁמָּרְדוּ בּוֹ בְּבִנְיַן הַמִּגְדָּל) שֶׁכָּתוּב בָּהֶם ״וְהַחֵמָר הָיָה לָהֶם לַחֹמֶר״ (בראשית יא:ג):\",2,0],[2,122,30,20,\"עָמַדְתִּי. לִרְאוֹת, לִשְׁתּוֹק וּלְהָבִין; כְּמוֹ ״וּבְפִתְחוֹ עָמְדוּ כָל הָעָם״ (נחמיה ח:ה), וְ״לֹא עָנוּ עוֹד״ (איוב לב:טו):\",1,0],[2,122,30,20,\"וַתִּתְבֹּנֶן בִּי. מְחַשֵּׁב עָלַי לִשְׁנוֹת אֶת נְגָעַי:\",2,0],[2,122,30,22,\"תִּשָּׂאֵנִי אֶל רוּחַ. שֵׁדִים:\",1,0],[2,122,30,22,\"תַּרְכִּיבֵנִי וּתְמֹגְגֵנִי תּוּשִׁיָּה. חַלָּשׁוּת וְתַשּׁוּת כֹּחַ הָיָה מְמוֹגְגֵנִי:\",2,0],[2,122,30,22,\"וּתְמוֹגְגֵנִי תּוּשִׁיָּה. לְשׁוֹן נְקֵבָה, וְעַל תּוּשִׁיָּה עוֹמֵד. וְאֵין תָּי״ו זוֹ כְּתָי״ו שֶׁל תִּשָּׂאֵנִי:\",3,0],[2,122,30,23,\"כִּי יָדַעְתִּי. כִּי יוֹדֵעַ הָיִיתִי אֲשֶׁר לַמָּוֶת תְּשִׁיבֵנִי, מָקוֹם שֶׁהוּא מוֹעֵד לְכָל חָי. בַּקֶּבֶר:\",1,0],[2,122,30,24,\"אַךְ לֹא בְעִי. וּבַהַשְׁחָתָה הָיָה רָגִיל הַשּׁוֹפֵט לִשְׁלֹחַ יָד, כְּמוֹ ״לְעִי הַשָּׂדֶה״ (מיכה א:ו):\",1,0],[2,122,30,24,\"אִם בְּפִידוֹ. אִם הָיָה שׁוֹלֵחַ פִּיד, שֶׁהוּא שֶׁבֶר, עַל בְּרִיּוֹתָיו:\",2,0],[2,122,30,24,\"לָהֶן שׁוּעַ. הָיָה מְשַׁעֲשְׁעָן תַּנְחוּמִין בְּמִקְצָת. וְכֵן פֵּרְשׁוּ רַבּוֹתֵינוּ (ילקוט שמעוני איוב תתקיח): אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מַכֶּה אוּמָּה וּמוֹשִׁיבָהּ צָדוּ, אֶלָּא מֵבִיא פִּיד לָזוֹ וּמְשַׁעֲשְׁעָהּ בַּחֲבֶרְתָּהּ שֶׁלָּקְתָה כְּבָר, וּמִתְנַחֶמֶת בָּהּ. הֵבִיא פִּיד לְאַשּׁוּר וְשִׁעֲשֵׁעַ בְּמִצְרַיִם, שֶׁנֶּאֱמַר ״הֲתֵיטְבִי מִנֹּא אָמוֹן״ (נחום ג:ח); הֵבִיא פִּיד לְמִצְרַיִם וְשִׁעֲשֵׁעַ בְּאַשּׁוּר, שֶׁנֶּאֱמַר ״הִנֵּה אַשּׁוּר… בַּלְּבָנוֹן״ (יחזקאל לא:ג). וְעוֹד יִפָּתֵר לָהֶן שׁוּעַ. תְּפִלָּה וּתְחִנָּה מוֹעֶלֶת בָּהֶם:\",3,0],[2,122,30,25,\"אִם לֹא בָכִיתִי לִקְשֵׁה יוֹם. יוֹדֵעַ וּמַכִּיר, אִם לֹא הָיִיתִי רַחֲמָנִי וּבוֹכֶה עַל עֲנִיִּים קְשֵׁי יוֹם, וְעָגְמָה נַפְשִׁי לָאֶבְיוֹנִים. כִּי עַל כָּל אֵלֶּה בָּאַתְנִי זֹאת:\",1,0],[2,122,30,26,\"כִּי טוֹב קִוִּיתִי וְגוֹ׳. כְּלוֹמַר: כִּי הַגְּמוּל הַזֶּה רָאוּי לִי:\",1,0],[2,122,30,27,\"וְלֹא דָמּוּ. אֵין יְכוֹלִין לִדּוֹם וּלְהַחֲרִישׁ:\",1,0],[2,122,30,28,\"בְּלֹא חַמָּה. לֹא שְׁזָפַתְנִי הַשֶּׁמֶשׁ, וְהִנְנִי קוֹדֵר:\",1,0],[2,122,30,29,\"אָח הָיִיתִי לְתַנִּים וְגוֹ׳. תַּנִּים וּבְנוֹת יַעֲנָה עֲסוּקִים בִּבְכִי כָּל יְמֵיהֶם:\",1,0],[2,122,30,30,\"חָרָה. לְשׁוֹן דָּבָר הַנִּחְרָה וּמִתְיַיבֵּשׁ מִפְּנֵי חוֹם הָאֵשׁ, כְּמוֹ ״נָחַר מַפֻּחַ״ (ירמיהו ו:כט), ״וְתוֹכוֹ נִחָר״ (יחזקאל טו:ד):\",1,0],[2,122,31,1,\"בְּרִית כָּרַתִּי לְעֵינָי. שֶׁלֹּא לְהִסְתַּכֵּל בְּאֵשֶׁת אִישׁ:\",1,0],[2,122,31,1,\"וּמָה אֶתְבּוֹנֵן עַל בְּתוּלָה. מָה לִּי לְהִתְבּוֹנֵן בָּהּ? כָּךְ הָיְתָה חֲסִידוּתִי, שֶׁלֹּא לָתֵת עַיִן אֲפִלּוּ בִּפְנוּיָה; שֶׁמָּא לְאַחַר יָמִים תִּנָּשֵׂא, וְנִמְצֵאתִי כָּרוּךְ אַחֲרֶיהָ. כָּךְ מְפֹרָשׁ בְּאָבוֹת דְּרַבִּי נָתָן (אבות דרבי נתן):\",2,0],[2,122,31,2,\"וּמֶה חֵלֶק וְגוֹ׳. שֶׁגְּמָלַנִי כָּךְ?\",1,0],[2,122,31,3,\"הֲלֹא אֵיד לְעַוָּל. לוֹ רָאוּי, וְלֹא לִי:\",1,0],[2,122,31,3,\"וְנֵכֶר. דּוּגְמַת ״וְאַל תֵּרֶא בְיוֹם אָחִיךָ בְּיוֹם נָכְרוֹ״ (עובדיה א:יב):\",2,0],[2,122,31,4,\"וְכָל צְעָדַי יִסְפּוֹר. וְרוֹאֶה אִם הָלַכְתִּי עִם שָׁוְא:\",1,0],[2,122,31,5,\"וַתַּחַשׁ. וַתְּמַהֵר, כְּמוֹ ״אֲחִישֶׁנָּה״ (ישעיה ס:כב); ״כִּי גָז חִישׁ״ (תהלים צ:י):\",1,0],[2,122,31,7,\"מָאוּם. הוּא מוּם, דְּבַר שֶׁמֶץ. וְאָלֶ״ף זוֹ כְּתוּבָה וְלֹא קְרִיָא בַּמָּסֹרֶת הַגְּדוֹלָה, וְהוּא מִגִּזְרַת לֹא תֹאסִפוּן (שמות ה:ז). אִם זוֹ עָשִׂיתִי, הָיִיתִי רָאוּי לָבֹא עָלַי קְלָלָה זוֹ:\",1,0],[2,122,31,8,\"אֶזְרְעָה וְאַחֵר יֹאכֵל וְצֶאֱצָאַי יְשֹׁרָשׁוּ. יֵעָקְרוּ הַשָּׁרָשִׁין:\",1,0],[2,122,31,9,\"וְעַל פֶּתַח רֵעִי אָרָבְתִּי. לְאִשְׁתּוֹ – יָשִׁיב לִי גְּמוּלִי:\",1,0],[2,122,31,10,\"תִּטְחַן לְאַחֵר אִשְׁתִּי. רַבּוֹתֵינוּ פֵּרְשׁוּהוּ (במדבר רבה ט:כד) לְשׁוֹן תַּשְׁמִישׁ, כְּמוֹ ״וַיְהִי טוֹחֵן בְּבֵית הָאֲסוּרִין״ (שופטים טז:כא):\",1,0],[2,122,31,11,\"כִּי הִיא זִמָּה. וְיָרֵא הָיִיתִי אִם עָשִׂיתִי, שֶׁהוּא עָוֺן פְּלִילִי, עָוֹן שֶׁמִּשְׁפַּט יִסּוּרִין רְאוּיִין לָבֹא עַל יָדוֹ:\",1,0],[2,122,31,12,\"וּבְכָל תְּבוּאָתִי תְשָׁרֵשׁ. הָאֵשׁ הַזֹּאת, לָכֵן נִמְנַעְתִּי מֵעֲשׂוֹת. כְּשֶׁהוּא מְדַבֵּר בִּלְשׁוֹן עִקּוּר, אוֹמֵר תְּשָׁרֵשׁ; וּבִלְשׁוֹן שֹׁרֶשׁ אוֹמֵר ״תַּשְׁרֵשׁ״ (תהלים פ:י). וְכֵן ״יְשֹׁרָשׁוּ״ (איוב לא:ח) – לְשׁוֹן עִקּוּר; ״יַשְׁרֵשׁ״ (ישעיהו כז:ו) – לְשׁוֹן שֹׁרֶשׁ:\",1,0],[2,122,31,14,\"וּמָה אֶעֱשֶׂה וְגוֹ׳. זֹאת נָתַתִּי אֶל לִבִּי, וְכִי יִפְקֹד אֶת דְּרָכַי, מָה אֲשִׁיבֶנּוּ?\",1,0],[2,122,31,15,\"וַיְכֻנֶנּוּ בָרֶחֶם. אֲנִי בְּבֶטֶן אִמִּי, וְהוּא בְּבֶטֶן אִמּוֹ, הֱכִינָנוּ יוֹצֵר אֶחָד:\",1,0],[2,122,31,16,\"אֲכַלֶּה. שֶׁלֹּא מִלֵּאתִי תַּאֲוָתָהּ, שֶׁהוּא כִּלְיוֹן עֵינַיִם. הַמִּתְאַוֶּה וְאֵינוֹ מַגִּיעַ, קָרוּי ״כִּלְיוֹן עֵינַיִם״ (דברים כח:סה):\",1,0],[2,122,31,18,\"כִּי מִנְּעוּרַי גְּדֵלַנִי. הַכִּשָּׁרוֹן הַזֶּה כְּאָב הַמְגַדְּלֵנִי וְהַמְלַמְּדֵנִי, כֵּן לִמְּדַנִי יֹשֶׁר לִבִּי מִנְּעוּרַי:\",1,0],[2,122,31,18,\"וּמִבֶּטֶן אִמִּי אַנְחֶנָּה. לְמִדָּה זוֹ:\",2,0],[2,122,31,22,\"מִשִּׁכְמָה. הוּא רֹחַב הַכָּתֵף:\",1,0],[2,122,31,22,\"מִקָּנָה. הוּא עֶצֶם הָעֶלְיוֹן, הֶעָגֹל כְּקָנֶה; וְעַל שֶׁהוּא עָגֹל כְּקָנֶה, קוֹרֵא אוֹתוֹ כֵּן:\",2,0],[2,122,31,23,\"כִּי פַחַד אֵלַי וְגוֹ׳. פַּחַד הָיָה בְּעֵינַי אֵידוֹ, שֶׁהוּא מֵבִיא עַל הָרְשָׁעִים; לָכֵן חָדַלְתִּי מֵעֲשׂוֹת:\",1,0],[2,122,31,23,\"וּמִשְּׂאֵתוֹ. וּמִכְּבוֹדוֹ:\",2,0],[2,122,31,24,\"כִּסְלִי. כְּמוֹ ״אֲשֶׁר יָקוֹט כִּסְלוֹ״ (איוב ח:יד) – תִּקְוָתִי וּמַחֲשַׁבְתִּי. וְעַל יְדֵי שֶׁכְּלָיוֹת עַל הַכְּסָלִים הֵם (ויקרא ג:ד), וְהַכְּלָיוֹת יוֹעֲצוֹת (תהלים טז:ז), נִקְרֵאת הַמַּחֲשָׁבָה ׳כֶּסֶל׳:\",1,0],[2,122,31,24,\"וְלַכֶּתֶם. קְבוּצוֹת זָהָב וְאוֹצָרוֹת:\",2,0],[2,122,31,24,\"אָמַרְתִּי מִבְטַחִי. לְהִתְחַזֵּק בָּהֶם עַל הָעֲנִיִּים:\",3,0],[2,122,31,25,\"אִם אֶשְׂמַח כִּי רַב חֵילִי. לֹא הָיִיתִי נוֹהֵג שִׂמְחָה בִּפְנֵי הָעֲנִיִּים בְּעָשְׁרִי, שֶׁלֹּא לְהַקְנִיאָם בִּי:\",1,0],[2,122,31,26,\"אִם אֶרְאֶה אוֹר כִּי יָהֵל. חַמָּה בִּתְקוּפַת גְּבוּרָתָהּ וְהִילָּה:\",1,0],[2,122,31,26,\"וְיָרֵחַ יָקָר הוֹלֵךְ. מַגִּיהַּ וְהוֹלֵךְ, כְּמוֹ ״אוֹר יְקָרוֹת״ (זכריה יד:ו), ״כִּיקַר כָּרִים״ (תהלים לז:כ):\",2,0],[2,122,31,27,\"וַיִּפְתְּ בַּסֵּתֶר לִבִּי. לַשֶּׁמֶשׁ וְלַיָּרֵחַ לֵאמֹר: אֱלוֹהוּת הֵם, כִּקְצָת עוֹבְדֵי כוֹכָבִים הַנִּדָּחִים (וְעוֹבְדִים) לְכָל צְבָא הַשָּׁמַיִם:\",1,0],[2,122,31,30,\"וְלֹא נָתַתִּי לַחֲטֹא חִכִּי. לְהַקְנִיט שׂוֹנְאִי וְלִתְבֹּעוֹ מָמוֹן שֶׁאֵין לִי עָלָיו, כְּדֵי לְהַשְׁבִּיעוֹ, וְלִשְׁאֹל בְּאָלָה נַפְשׁוֹ שֶׁל שׂוֹנְאִי:\",1,0],[2,122,31,31,\"לֹא נִשְׂבָּע. מִתּוֹךְ שִׂנְאָה שֶׁהָיוּ שׂוֹנְאִים אוֹתִי, עַל שֶׁהָיִיתִי מַטְרִיחָם בְּהַכְנָסַת אוֹרְחִים:\",1,0],[2,122,31,32,\"לָאֹרַח. לֹא הָיוּ דַּלְתוֹת בֵּיתִי פְּנִימִיִּים וּמוּקָּפִין בֵּית שַׁעַר מִבַּחוּץ, אוֹ מוּסָּבִין בְּקַרְנֵי זָוִית, לְהַשְׁבִּית אֶת הָאוֹרְחִים מִלָּבוֹא, אֶלָּא פְּתוּחִין לְאֵם דֶּרֶךְ, לָבוֹא כָּל הַבָּא:\",1,0],[2,122,31,33,\"בְּחֻבִּי. בְּמַחֲבוֹאִי:\",1,0],[2,122,31,34,\"כִּי אֶעֱרוֹץ. מִתְּחִלָּה הָיִיתִי מַכְנִיעַ הָמוֹן רַבָּה שֶׁל רְשָׁעִים, וְעַתָּה אַף בֵּין כַּשְׂדִּיִים, ״זֶה הָעָם לֹא הָיָה״ (ישעיהו כג:יג):\",1,0],[2,122,31,34,\"יְחִתֵּנִי. יְיָרְאֵנִי:\",2,0],[2,122,31,35,\"הֵן תָּוִי שַׁדַּי יַעֲנֵנִי. וּלְוַאי שֶׁיָּעִיד עָלַי הַמָּקוֹם בַּדִּין, כְּמוֹ שֶׁאָמַר עָלַי: ״כִּי אֵין כָּמוֹהוּ בָּאָרֶץ… תָּם וְיָשָׁר וִירֵא אֱלֹהִים״ (איוב א:ח). גַּם מֹשֶׁה שֶׁכָּתַב סִפְרוֹ וְסִפְרִי יָעִיד עָלַי. כֵּן הָיָה אִיּוֹב אוֹמֵר: תְּנָה לְתַוּוֹת אוֹתִי וְאֶת כּוֹשְׁרִי:\",1,0],[2,122,31,35,\"שַׁדַּי יַעֲנֵנִי. לְבַקָּשָׁה זֹאת:\",2,0],[2,122,31,35,\"וְסֵפֶר כָּתַב אִישׁ רִיבִי. יִכְתֹּב גַּם הוּא סִפְרוֹ, לְהִתְוַכֵּחַ עִמִּי:\",3,0],[2,122,31,36,\"אֶשָּׂאֶנּוּ. לִכְתּוֹב אֶת סְפָרִי:\",1,0],[2,122,31,36,\"אֶעֶנְדֶנּוּ. אֶקְשְׁרֶנּוּ לְסֵפֶר עֲטָרוֹת לִי:\",2,0],[2,122,31,37,\"מִסְפַּר צְעָדַי אַגִּידֶנּוּ. לְאוֹתוֹ הָאִישׁ:\",1,0],[2,122,31,38,\"אִם עָלַי אַדְמָתִי תִזְעָק. עַל לֶקֶט שִׁכְחָה וּפֵאָה וּמַעַשְׂרוֹת, שֶׁלֹּא הוֹצֵאתִי מַעַשְׂרוֹת כָּרָאוּי:\",1,0],[2,122,31,38,\"וְיַחַד תְּלָמֶיהָ יִבְכָּיוּן. שֶׁחָרַשְׁתִּי בְּשׁוֹר וּבַחֲמוֹר יַחְדָּיו (דברים כב:י):\",2,0],[2,122,31,39,\"בְּלִי כָסֶף. לִשְׂכֹּר שְׂכִירִים וּלְעָשְׁקָם. דָּבָר אַחֵר: זֶה מַעֲשֵׂר שֵׁנִי, דִּכְתִיב ״וְצַרְתָּ הַכֶּסֶף בְּיָדְךָ״ (דברים יד:כה):\",1,0],[2,122,31,39,\"וְנֶפֶשׁ בְּעָלֶיהָ. אָרִיס הָעוֹבֵד בָּהּ:\",2,0],[2,122,31,40,\"בָּאְשָׁה. (דָּבָר מַבְאִישׁ) כְּמוֹ ״בְּאוּשִׁים״ (ישעיה ה:ב). וְאִם לֹא עָשִׂיתִי כֵּן תַּחַת חִטָּה יֵצֵא חוֹחַ. תָּנָא רַבִּי אוֹשַׁעְיָא: לִמֶּדְתְךָ תּוֹרָה דֶּרֶךְ אֶרֶץ: שָׂדֶה שֶׁמַּעֲלָה חוֹחִים, יָפֶה לְזוֹרְעָהּ חִטִּים, שֶׁמַּעֲלָה בְּאוּשִׁים יָפֶה לְזוֹרְעָהּ שְׂעוֹרִים. כָּךְ הוּא בַּיַּלְקוּט (ילקוט שמעוני איוב תתקיח). וּמַה טַּעַם? תַּחַת חִטָּה יֵצֵא חוֹחַ:\",1,0],[2,122,31,40,\"תַּמּוּ וְגוֹ׳. עַד כָּאן הוּא חוֹזֵר וּמִתְנַבֵּא כַּמָּה נְבוּאוֹת, וְאַתְּ אוֹמֵר תַּמּוּ דִּבְרֵי אִיּוֹב? אֶלָּא כָּךְ אוֹמֵר אִיּוֹב: אִם לֹא עָשִׂיתִי כֵן, יִתַּמּוּ דִּבְרֵי אִיּוֹב, וְאַל יְהִי פִּתְחוֹן פֶּה לוֹמַר לְפָנֶיךָ ״בִּעַרְתִּי הַקֹּדֶשׁ״ (דברים כו:יג). כָּךְ רָאִיתִי בַּפְּסִיקְתָּא בְּפָרָשַׁת ׳עַשֵּׂר תְּעַשֵּׂר׳ (דברים יד:כב) מְפֹרָשׁ כֵּן, מִן הַפְּסוּקִים הָאֵלּוּ:\",2,0],[2,122,32,2,\"(מענה אליהוא:) מִמִּשְׁפַּחַת רָם. אַבְרָהָם, שֶׁנֶּאֱמַר ״הָאָדָם הַגָּדוֹל בָּעֲנָקִים״ (יהושע יד:טו) – זֶה אַבְרָהָם:\",1,0],[2,122,32,2,\"מֵאֱלֹהִים. יוֹתֵר מִן הַמָּקוֹם:\",2,0],[2,122,32,3,\"וַיַּרְשִׁיעוּ אֶת אִיּוֹב. זֶה אֶחָד מִן הַמִּקְרָאוֹת שֶׁתִּקְּנוּ סוֹפְרִים אֶת לְשׁוֹן הַכָּתוּב: ״וַיַּרְשִׁיעוּ כְּלַפֵּי הַמָּקוֹם בִּשְׁתִיקוֹתָם״ הָיָה לוֹ לִכְתֹּב, אֶלָּא שֶׁכִּנָּה הַכָּתוּב. וְכֵן ״וַיָּמִירוּ אֶת כְּבוֹדָם בְּתַבְנִית שׁוֹר״ (תהלים קו:כ) – ״כְּבוֹדִי״ הָיָה לוֹ לִכְתֹּב, אֶלָּא שֶׁכִּנָּה הַכָּתוּב. וְכֵן ״וְאַל אֶרְאֶה בְּרָעָתִי״ (במדבר יא:טו) – ״בְּרָעָתָם״ הָיָה לוֹ לִכְתֹּב, אֶלָּא שֶׁכִּנָּה הַכָּתוּב. וְכֵן הַרְבֵּה מְקוֹמוֹת (ספרי במדבר פד) וּבַמָּסֹרֶת הַגְּדוֹלָה:\",1,0],[2,122,32,4,\"חִכָּה. הִמְתִּין:\",1,0],[2,122,32,4,\"כִּי זְקֵנִים הֵמָּה מִמֶּנּוּ לְיָמִים. הָאֲחֵרִים, לָכֵן חָדַל לוֹ עַד שֶׁשָּׁתְקוּ הֵם:\",2,0],[2,122,32,6,\"זָחַלְתִּי. יָרֵאתִי:\",1,0],[2,122,32,8,\"אָכֵן רוּחַ הִיא בֶאֱנוֹשׁ. הַחָכְמָה, וְלֹא עַל יְדֵי יָמִים וְזִקְנָה, אֶלָּא רוּחַ הַמָּקוֹם הוּא:\",1,0],[2,122,32,12,\"וְעָדֵיכֶם אֶתְבּוֹנָן. הִתְבּוֹנַנְתִּי בָּכֶם וְרָאִיתִי, כִּי אֵין מוֹכִיחַ לְאִיּוֹב:\",1,0],[2,122,32,13,\"פֶּן תֹּאמְרוּ מָצָאנוּ חָכְמָה. בִּשְׁתִיקוּתֵינוּ, שֶׁלֹּא לְהַקְנִיטוֹ עוֹד, כִּי אֵל יִדְּפֶנּוּ וְלֹא אִישׁ. לֹא הָיָה לָכֶם לְמַעֵט כְּבוֹד הַמָּקוֹם בְּכָךְ:\",1,0],[2,122,32,14,\"וְלֹא עָרַךְ אֵלַי מִלִּין. קַבָּלָה הִיא, אוֹ שֶׁלֹּא עָרַךְ אֵלַי מִלִּין:\",1,0],[2,122,32,14,\"וּבְאִמְרֵיכֶם לֹא אֲשִׁיבֶנּוּ. לֹא בְּאוֹתָן אֲמָרִים שֶׁהֲשִׁיבוֹתֶם לוֹ, הָיִיתִי מְשִׁיבוֹ:\",2,0],[2,122,32,15,\"הֶעְתִּיקוּ. סָרוּ מֵהֶן מִלִּין:\",1,0],[2,122,32,19,\"הִנֵּה בִטְנִי. מָלֵא רוּחַ, דְּבָרִים לְהָשִׁיב בְּתַאֲוָה:\",1,0],[2,122,32,19,\"כְּיַיִן לֹא יִפָּתֵחַ. כְּיַיִן חָדָשׁ שֶׁאֵינוֹ נִפְתָּח, וְהוּא נוֹפֵחַ, וְאַף בְּתוֹךְ אוֹבוֹת חֲדָשִׁים, וּמְבַקְּעָם:\",2,0],[2,122,32,19,\"אוֹבוֹת. נוֹדוֹת עֲשׂוּיִין כְּקוֹמַת אָדָם, גְּבוֹהִים:\",3,0],[2,122,32,21,\"לֹא אֲכַנֶּה. לֹא אֲשַׁנֶּה דְבָרַי לְהַחֲלִיפוֹ לִכְבוֹדוֹ, כְּמוֹ שֶׁאָמַרְתִּי לְמַעְלָה ״וַיַּרְשִׁיעוּ אֶת אִיּוֹב״ (איוב לב:ג) – זֶהוּ ׳כִּנּוּי׳, שֶׁמְּשַׁנֶּה אֶת הַדִּבּוּר בִּשְׁבִיל כְּבוֹדוֹ. וְאַף זֹאת לֹא אֶעֱשֶׂה, כִּי בְּפֶה מָלֵא אוֹכִיחֶנּוּ:\",1,0],[2,122,32,22,\"כִּמְעַט יִשָּׂאֵנִי. יְסַלְּקֵנִי מִן הָעוֹלָם. וְיֵשׁ פּוֹתְרִים יִשָּׂאֵנִי כְּמוֹ ״וַתִּשָּׂא הָאָרֶץ מִפָּנָיו״ (נחום א:ה):\",1,0],[2,122,33,4,\"רוּחַ אֵל עָשָׂתְנִי. וְאֵינִי חָזָק יוֹתֵר מִמְּךָ:\",1,0],[2,122,33,6,\"הֵן אֲנִי כְפִיךָ לָאֵל. כְּמוֹ שֶׁשָּׁאַל פִּיךָ לְהִתְוַכֵּחַ לְמִי שֶׁלֹּא יְבַעֲתֶךָ (איוב יג:כא), הֵן אֲנִי בִּמְקוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּבִשְׁבִילוֹ, לְדַבֵּר דְּבָרָיו:\",1,0],[2,122,33,7,\"וְאַכְפִּי. כְּפִיָּתִי, כְּמוֹ ״אָכַף עָלָיו פִּיהוּ״ (משלי טז:כו):\",1,0],[2,122,33,9,\"חַף. טָהוֹר וּמְשֻׁפְשָׁף, כְּמוֹ (ביצה לה:) ״נָזִיר לֹא יָחוֹף רֹאשׁוֹ״, וּכְמוֹ (שבת נ.) ״בַּכֹּל חָפִין אֶת הַכֵּלִים״:\",1,0],[2,122,33,10,\"תְּנוּאוֹת. עֲלִילוֹת, לְשׁוֹן ״תּוֹאֲנָה״ (שופטים יד:ד) – לָשׁוּב מִן הַמָּקוֹם:\",1,0],[2,122,33,12,\"כִּי יִרְבֶּה אֱלוֹהַּ מֵאֱנוֹשׁ. אֵין הַמָּקוֹם צָרִיךְ כָּל כָּךְ לְדַקְדֵּק אַחַר הָאָדָם, כִּי הַרְבֵּה יֵשׁ לְהַקָּדוֹשׁ בָּרוּךְ הוּא צְדָקוֹת יוֹתֵר מֵאֱנוֹשׁ:\",1,0],[2,122,33,16,\"אָז יִגְלֶה אֹזֶן אֲנָשִׁים. כְּמוֹ שֶׁעָשָׂה לַאֲבִימֶלֶךְ בַּחֲלוֹם הַלַּיְלָה (בראשית כ:ג):\",1,0],[2,122,33,16,\"וּבְמוֹסָרָם יַחְתֹּם. חוֹתְמָן וְאוֹסְרָן בְּיִסּוּרִין עַל עֲוֹנָם:\",2,0],[2,122,33,17,\"לְהָסִיר אָדָם. בְּחָלְיוֹ:\",1,0],[2,122,33,17,\"מַעֲשֶׂה. שֶׁהָיָה בְדַעְתּוֹ לַעֲשׂוֹת:\",2,0],[2,122,33,17,\"וְגֵוָה מִגֶּבֶר יְכַסֶּה. בְּיִסּוּרָיו, לְמַעַן הַכְנִיעוֹ וּלְהַשְׁפִּילוֹ לָשׁוּב, כְּדֵי שֶׁיֶּחְשַׂךְ נַפְשׁוֹ מִמִּיתָה גְּמוּרָה:\",3,0],[2,122,33,17,\"גֵּוָה. כְּמוֹ גַּאֲוָה:\",4,0],[2,122,33,18,\"וְחַיָּתוֹ מֵעֲבֹר בַּשָּׁלַח. בְּשִׁלְחוֹ וְחַרְבּוֹ שֶׁל מַלְאַךְ הַמָּוֶת, כְּלוֹמַר: לְטוֹבָתְךָ הֵבִיא עָלֶיךָ יִסּוּרִין:\",1,0],[2,122,33,18,\"שֶׁלַח. כְּלִי זַיִן, וְכֵן ״יָדוֹ אַחַת מַחֲזֶקֶת הַשֶּׁלַח״ (נחמיה ד:יא):\",2,0],[2,122,33,19,\"וְהוּכַח. לְשׁוֹן תּוֹכָחָה, שֶׁיָּשׁוּב מֵעֲוֹנוֹ:\",1,0],[2,122,33,19,\"וְרוֹב עֲצָמָיו. שֶׁהוּא אֵיתָן, מוֹכִיחָן בְּמַכְאוֹב:\",2,0],[2,122,33,20,\"וְזִהֲמַתּוּ חַיָּתוֹ לָחֶם. מְמַאֶסֶת נַפְשׁוֹ וְחַיָּתוֹ שֶׁל חוֹלֶה כָּל מַאֲכָל:\",1,0],[2,122,33,20,\"וְנַפְשׁוֹ. מְזַהֶמֶת כָּל מַאֲכַל תַּאֲוָה:\",2,0],[2,122,33,21,\"יִכֶל בְּשָׂרוֹ מֵרֹאִי. יֶחְשַׁךְ בְּשָׂרוֹ מִמַּרְאֶה, כְּמוֹ ״כָּלוּ בַדְּמָעוֹת עֵינַי״ (איכה ב:יא), ״מְכַלּוֹת עֵינַיִם״ (ויקרא כו:טז):\",1,0],[2,122,33,21,\"וְשֻׁפּוּ עַצְמוֹתָיו. מִתְנַתְּקִין מִמְּקוֹמוֹ, וְשֻׁפּוּ כְּמוֹ דְּשָׁף מִדּוּכְתֵּיהּ (חולין מב:):\",2,0],[2,122,33,21,\"לֹא רֻאּוּ. אֵין לָהֶם מַרְאֶה וְתֹאַר:\",3,0],[2,122,33,23,\"אֶחָד מִנִּי אָלֶף. בְּמַגִּידֵי פִּשְׁעוֹ, וְהוּא יָלִיץ יָשְׁרוֹ:\",1,0],[2,122,33,24,\"וַיְחֻנֶּנּוּ. הַמָּקוֹם:\",1,0],[2,122,33,24,\"פְּדָעֵהוּ. כְּמוֹ פְּדָאֵהוּ, אָלֶ״ף מִתְחַלֶּפֶת בְּעַיִ״ן. וְהָעִנְיָן מוֹכִיחַ: מָצָאתִי כֹפֶר, וְהוּא ״פִּדְיוֹן״ (שמות כא:ל):\",2,0],[2,122,33,25,\"רֻטְפַשׁ בְּשָׂרוֹ. רוֹטְפַשׁ אֶשְׁקוֹשָׁ״א בְּלַעַ״ז:\",1,0],[2,122,33,25,\"מִנֹּעַר. נִתְעוֹרֵר בְּשָׂרוֹ מִן הַנּוֹעַר, שֶׁהוּא מְנוֹעָר וּמְשֻׁנָּק בְּיִסּוּרֵי חָלְיוֹ. וְאֵין לַתֵּיבָה זוֹ דִּמְיוֹן בַּמִּקְרָא, וּלְפִי הָעִנְיָנִים הֻצְרַכְנוּ לְפָרְשׁוֹ כְּמַשְׁמָעוּת הָעִנְיָן. וְהַפּוֹתְרוֹ בִּלְשׁוֹן ׳רֶפֶשׁ׳, וְאוֹמֵר הַטֵּי״ת נִתּוֹסְפָה בּוֹ, כְּמוֹ ״נִצְטַדָּק״ (בראשית מד:טז) – טוֹעֶה הוּא מְאֹד. כִּי אֵין טֵי״ת מִתּוֹסֶפֶת בַּתֵּיבָה, כִּי אִם בִּלְשׁוֹן ׳מִתְפַּעֵל׳ אוֹ ׳נִתְפַּעֵל׳, וּבַתֵּיבָה שֶׁיְּסוֹדָהּ צַדִּ״י; וְלֹא בִּשְׁאָר תֵּיבוֹת. כְּמוֹ ״צֶדֶק״ (איוב ח:ג) וְ״נִצְטַדָּק״ (בראשית מד:טז); וּכְמוֹ ״צָרוּעַ״ (ויקרא יג:מד) – ׳נִצְטָרַע׳; ״צִיר נֶאֱמָן״ (משלי כה:יג) – ״וַיֵּלְכוּ וַיִּצְטַיָּרוּ״ (יהושע ט:ד); ״צֵדָה״ – ״הִצְטַיַּדְנוּ״ (יהושע ט:יב):\",2,0],[2,122,33,25,\"יָשׁוּב. בְּכֹחוֹ וּבִרְפוּאָה לִימֵי בַּחֲרוּתוֹ:\",3,0],[2,122,33,26,\"בִּתְרוּעָה. בִּתְפִלָּה:\",1,0],[2,122,33,27,\"יָשֹׁר עַל אֲנָשִׁים. יַעֲשֶׂה שׁוּרוֹת שֶׁל אֲנָשִׁים כְּשֶׁנִּצּוֹל מֵחָלְיוֹ, וְיִתְוַדֶּה לְיוֹצְרוֹ:\",1,0],[2,122,33,27,\"וְלֹא שָׁוָה לִי. לֹא נִהְיָה לִי שָׂכָר בִּדְבָרָיו:\",2,0],[2,122,33,29,\"פַּעֲמַיִם שָׁלוֹשׁ. מְיַסְּרוֹ עַל עֲוֹנוֹתָיו בְּחָלְיוֹ, שֶׁלֹּא לְהַשְׁחִיתוֹ; וְאִם יוֹתֵר יַכְעִיס לְפָנָיו, יִדְאַג מִן גֵּיהִנֹּם וּמִן הַמִּיתָה; שֶׁנֶּאֱמַר ״וְעַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ״ (עמוס א:ג):\",1,0],[2,122,34,3,\"(מענה אליהו): כִּי אֹזֶן מִלִּין תִּבְחָן. כַּאֲשֶׁר הַחֵיךְ יִטְעַם הָאֹכֶל:\",1,0],[2,122,34,5,\"מִשְׁפָּטִי. הוֹכָחַת דְּבָרִים:\",1,0],[2,122,34,6,\"אֲכַזֵּב. אֲכַזִּיב שׁוֹפְטִי, שֶׁלֹּא דָנַנִּי אֱמֶת:\",1,0],[2,122,34,6,\"אָנוּשׁ. חוֹלֶה מַכָּתִי, כְּמוֹ ״וַיֵּאָנַשׁ״ (שמואל ב יב:טו):\",2,0],[2,122,34,6,\"חִצִּי. נִגְעִי:\",3,0],[2,122,34,9,\"לֹא יִסְכָּן גָּבֶר. לֹא יֵהָנֶה אָדָם, אִם מַתְמִים דְּרָכָיו:\",1,0],[2,122,34,13,\"מִי פָקַד עָלָיו אָרְצָה. מִי מוֹשֵׁל בּוֹ, לֵאמֹר: לָמָּה כֵּן עָשִׂיתָ וְלֹא צִוִּיתִיךָ כֵּן? כִּי מִי צִוָּהוּ בְּמֶמְשַׁלְתּוֹ, וְלָמָּה יִמְצָא תּוֹאֲנוֹת לַבְּרִיּוֹת? אֵינוֹ צָרִיךְ לְהָשִׁיב דָּבָר לְמוֹשֵׁל בּוֹ, לֵאמֹר: בִּשְׁבִיל זֹאת הֲרֵעוֹתִי לוֹ:\",1,0],[2,122,34,14,\"אִם יָשִׂים אֵלָיו לִבּוֹ. עַל אָדָם, לְהַשְׁחִיתוֹ, לָמָּה יָבֹא בַּעֲלִילָה עָלָיו? הֲרֵי מִיָּד יֶאֱסֹף אֵלָיו רוּחוֹ וְנִשְׁמָתוֹ. רוּחַ וּנְשָׁמָה שֶׁלּוֹ שֶׁהִיא נְפוּחָה בּוֹ, וְאֵין מוֹחֶה בְּיָדוֹ, וְיִגְוַע כָּל בָּשָׂר יָחַד:\",1,0],[2,122,34,16,\"וְאִם בִּינָה. וְאִם אַתָּה רוֹצֶה הָבִין, שִׁמְעָה זֹאת. בִּינָה זוֹ אֵינָהּ שֵׁם דָּבָר, אֶלָּא לְשׁוֹן צִוּוּי, כְּמוֹ ״בִּינָה הֲגִיגִי״ (תהלים ה:ב). לְפִיכָךְ שְׁתַּיִם אֵלּוּ טַעֲמָן לְמַעְלָה, בַּבֵּי״ת, וְכָל שְׁאָר בִּינָה טַעֲמָן לְמַטָּה, בַּנּוּ״ן:\",1,0],[2,122,34,17,\"הַאַף שׂוֹנֵא מִשְׁפָּט. מִשְׁפָּטוֹ שֶׁל שׁוֹפֵט צֶדֶק יַחֲבוֹשׁ הַמָּקוֹם? וְאִם תֹּאמַר: אֵינוֹ מִשְׁפָּט, כִּי לֹא כַדִּין עָשָׂה, אֶפְשָׁר זֹאת מִי שֶׁהוּא צַדִּיק מְאֹד תַּרְשִׁיעַ?\",1,0],[2,122,34,17,\"כַּבִּיר. לְשׁוֹן מְאֹד:\",2,0],[2,122,34,18,\"הַאֲמֹר לְמֶלֶךְ בְּלִיָּעַל. וְכִי הָגוּן וְרָאוּי לֹאמַר לְמֶלֶךְ: בְּלִיָּעַל, וְלֹאמַר רָשָׁע אֶל נְדִיבִים?!\",1,0],[2,122,34,19,\"אֲשֶׁר לֹא נָשָׂא פְּנֵי שָׂרִים. כְּלוֹמַר: לְמֶלֶךְ עוֹלָם, אֲשֶׁר אֵין מַשּׂוֹא פָנִים לְפָנָיו:\",1,0],[2,122,34,19,\"שׁוֹעַ. שַׂר, כְּמוֹ ״וְלַכִּילַי לֹא יֵאָמֵר שׁוֹעַ״ (ישעיהו לב:ה):\",2,0],[2,122,34,20,\"רֶגַע יָמוּתוּ. כְּשֶׁיִּרְצֶה:\",1,0],[2,122,34,20,\"וַחֲצוֹת לָיְלָה. כְּמוֹ שֶׁעָשָׂה לְמִצְרַיִם (שמות יא:ד-ח):\",2,0],[2,122,34,20,\"יְגֹעֲשׁוּ עָם. כְּלוֹמַר: בְּרֶגַע יַעַבְרוּ:\",3,0],[2,122,34,20,\"וְיָסִירוּ אַבִּיר. כֹּחַ שֶׁלָּהֶם:\",4,0],[2,122,34,20,\"לֹא בְיָד. לֹא יִשְׁנוּ בְיָדָם וְאֵין לָהֶם כֹּחַ:\",5,0],[2,122,34,23,\"כִּי לֹא עַל אִישׁ יָשִׂים עוֹד. כְּלוֹמַר: אָמַרְתָּ: ״לֹא אַךְ יָשִׂים בִּי״ (איוב כג:ו), רַק חֲטָאַי לְבַדִּי; וַאֲנִי מְשִׁיבְךָ: לֹא יָשִׂים הַקָּדוֹשׁ בָּרוּךְ הוּא עַל בְּרִיּוֹתָיו עֲלִילוֹת תּוֹסֶפֶת עַל פִּשְׁעָם. עוֹד לְשׁוֹן תּוֹסֶפֶת:\",1,0],[2,122,34,23,\"לָהֲלֹךְ אֶל אֵל בַּמִּשְׁפָּט. כְּשֶׁהוּא בָּא עַל בְּרִיּוֹתָיו לְהִתְוַכֵּחַ עִמָּהֶם:\",2,0],[2,122,34,24,\"יָרֹעַ. יְרוֹצֵץ, כְּמוֹ ״רֹעַ הִתְרוֹעֲעָה״ (ישעיה כד:יט):\",1,0],[2,122,34,24,\"וַיַּעֲמֵד אֲחֵרִים. בִּמְקוֹמָם:\",2,0],[2,122,34,25,\"לָכֵן יַכִּיר מַעְבָּדֵיהֶם. לְפִי שֶׁהוּא מַכִּיר מַעְבָּדֵיהֶם הַטּוֹב וְהָרַע, וְאֵין צֹרֶךְ לוֹ לְהִתְוַכֵּחַ:\",1,0],[2,122,34,25,\"וְהָפַךְ לַיְלָה. עֵת חֹשֶׁךְ וְצָרָה לָהֶם, וְיִדַּכָּאוּ:\",2,0],[2,122,34,26,\"תַּחַת רְשָׁעִים. בִּמְקוֹמָם:\",1,0],[2,122,34,26,\"סְפָקָם. לְאַנְשֵׁי סְדוֹם (בראשית יט:א-כט):\",2,0],[2,122,34,26,\"בִּמְקוֹם רוֹאִים. לְעֵין כֹּל:\",3,0],[2,122,34,27,\"אֲשֶׁר עַל כֵּן סָרוּ מֵאַחֲרָיו. כְּמוֹ ״עַל כֵּן יָדַעְתָּ חֲנֹתֵנוּ בַּמִּדְבָּר״ (במדבר י:לא). כְּמוֹ: מִפְּנֵי אֲשֶׁר סָרוּ מֵאַחֲרָיו וְהֵבִיאוּ לְפָנָיו וְעָלָיו צַעֲקַת דַּלִּים:\",1,0],[2,122,34,29,\"וְהוּא יַשְׁקִיט. מַשְׁקִיט אֶת הַדַּלִּים מֵאוֹתָן הָעוֹשְׁקִים, וּמִי יַרְשִׁיעַ עוֹד? וּבְעוֹד שֶׁהִסְתִּיר פָּנִים, מִי יְשׁוּרֶנּוּ?\",1,0],[2,122,34,29,\"וְעַל גּוֹי וְעַל אָדָם יָחַד. כִּיחִידִים כִּמְרֻבִּים שָׁוֶה לְפָנָיו, לְהַשְׁקִיט וּלְהַסְתִּיר פָּנִים:\",2,0],[2,122,34,30,\"מִמְּלֹךְ אָדָם חָנֵף מִמֹּקְשֵׁי עָם. עַל דַּלִּים שֶׁמָּלַךְ:\",1,0],[2,122,34,30,\"מִמּוֹקְשֵׁי עָם. עָוֹן, וְלֵאלוֹהַּ כָּזֶה לֹא הָיָה לְךָ לוֹמַר ״בְּלִיַּעַל״ וְ״רָשָׁע״ (איוב לד:יח):\",2,0],[2,122,34,31,\"כִּי אֶל אֵל הֶאָמַר. לְהֵאָמֵר אֵלָיו. נָכוֹן וְרָאוּי מֵאֵת כָּל סוֹבְלֵי יִסּוּרִים לְהֵאָמֵר: נָשָׂאתִי, וּמְקַבֵּל וְסוֹבֵל אֲנִי מִשְׁפָּטֶיךָ, וְלֹא אֶחְבֹּל בְּעַצְמִי. וְעוֹד צָרִיךְ הַנִּדּוֹן לוֹמַר:\",1,0],[2,122,34,32,\"בִּלְעֲדֵי אֶחֱזֶה. לְבַד מַה שֶּׁאֲנִי יוֹדֵעַ לִרְאוֹת וּלְהָבִין בִּדְבָרֶיךָ, אַתָּה הוֹרֵנִי, וְאִם אָוֶן פָּעַלְתִּי, לֹא אוֹסִיף:\",1,0],[2,122,34,33,\"הַמֵעִמְּךָ יְשַׁלְּמֶנָּהּ כִּי מָאַסְתָּ וְגוֹ׳. כָּךְ אָמַר אֱלִיהוּ לְאִיּוֹב: הַמֵעִמְּךָ הָיָה לוֹ לְהַקָּדוֹשׁ בָּרוּךְ הוּא לְהִמָּלֵךְ בְּפֵרָעוֹן תַּשְׁלוּמִין מִמְּךָ?\",1,0],[2,122,34,33,\"כִּי מָאַסְתָּ. לֵאמֹר: ״מָאַסְתִּי לֹא לְעוֹלָם אֶחְיֶה״ (איוב ז:טז), ״יַתֵּר יָדוֹ וִיבַצְּעֵנִי״ (איוב ו:ט)?! סָבוּר אַתָּה שֶׁיִּגְבֶּה מִמְּךָ לְפִי דַעְתְּךָ וּרְצוֹנְךָ, וְאַתָּה תִבְחַר הַתַּשְׁלוּמִין, וְלֹא אֲנִי? בִּמְקוֹם הַקָּדוֹשׁ בָּרוּךְ הוּא דִּבֵּר אֱלִיהוּ, בִּתְמִיהַּ:\",2,0],[2,122,34,34,\"אַנְשֵׁי לֵבָב יֹאמְרוּ לִי. כִּי אִיּוֹב לֹא בְדַעַת יְדַבֵּר:\",1,0],[2,122,34,36,\"אָבִי יִבָּחֵן. אָבִי. אַתָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אָב לַכֹּל, הַלְוַאי יִבָּחֵן אִיּוֹב עַד נֶצַח, לְמַעַן תִּהְיֶה תְּשׁוּבָה לְאַנְשֵׁי אָוֶן. וְאַף לִבְנֵי אָדָם דִּבֵּר הַכָּתוּב כֵּן, כְּמוֹ ״אָבִי דָּבָר גָּדוֹל וְגוֹ׳״ (מלכים ב ה:יג). (דָּבָר אַחֵר: אָבִי. כְּמוֹ ״וְתָפֵר הָאֲבִיּוֹנָה״ (קהלת יב:ה), לְשׁוֹן רָצוֹן. כָּךְ חִבְּרוֹ מְנַחֵם. וְכֵן פִּתְרוֹנוֹ: אָבִי יִבָּחֵן אִיּוֹב עַד נֶצַח. רְצוֹנִי וּמְאַוְּיִי שֶׁיִּבָּחֵן אִיּוֹב עַד נֶצַח סא״א).\",1,0],[2,122,34,37,\"יִסְפּוֹק. לְשׁוֹן רוֹב דְּבָרִים וַהֲרָמַת קוֹל:\",1,0],[2,122,34,37,\"בֵּינֵינוּ יִסְפּוֹק. הוּא אוֹמֵר: מַה לָּנוּ וּלְדִבְרֵי אִיּוֹב? ״אַף אָמְנָם שָׁגִיתִי אִתִּי תָּלִין״ (איוב יט:ד)! וְאֵינוֹ יוֹדֵעַ שֶׁאָנוּ נֶעֱנָשִׁים, וּמַסְפִּיק לָנוּ עֲוֹנוֹת, עַל שֶׁאָנוּ שׁוֹמְעִים. כָּךְ מְפֹרָשׁ בְּוַיִּקְרָא רַבָּה (ויקרא רבה ד:ו):\",2,0],[2,122,35,2,\"(מענה אליהוא): הֲזֹאת חָשַׁבְתָּ לְמִשְׁפָּט. שֶׁהוּא מִשְׁפַּט הַבְּרִיּוֹת כְּנֶגֶד יוֹצְרָם, אֲשֶׁר אָמַרְתָּ צִדְקִי מִשֶּׁל הַבּוֹרֵא:\",1,0],[2,122,35,3,\"כִּי תֹאמַר מַה יִּסְכָּן לָךְ. דַּרְכֵי יֹשֶׁר:\",1,0],[2,122,35,3,\"מָה אוֹעִיל. בְּצִדְקָתִי יוֹתֵר מֵחַטָּאתִי:\",2,0],[2,122,35,4,\"וְאֶת רֵעֶיךָ עִמָּךְ. שֶׁשָּׁתְקוּ עַל דְּבָרֶיךָ:\",1,0],[2,122,35,5,\"הַבֵּט שָׁמַיִם. וְאַחֲרֵי שֶׁהוּא גָּבוֹהַּ וְאַתָּה נָמוּךְ, וְאֵין לוֹ תּוֹעֶלֶת בְּרִשְׁעֲךָ וְצִדְקְךָ, לָמָּה תִּתְפָּאֵר אֵלָיו בְּצִדְקְךָ?\",1,0],[2,122,35,8,\"לְאִישׁ. אֲשֶׁר כָּמוֹךָ יוּכַל וְיוֹעִיל רִשְׁעֲךָ וְצִדְקָתֶךָ, רְאֵה רְשָׁעִים רַבִּים אֲשֶׁר:\",1,0],[2,122,35,9,\"מֵרֹב עֲשׁוּקִים. שֶׁהֵם עוֹשְׁקִים, יַזְעִיקוּ אֶת הַבְּרִיּוֹת לְפָנָיו, וִישַׁוְּעוּ עֲנִיִּים מִזְּרוֹעַ רַבִּים הָעוֹשְׁקִים אוֹתָם:\",1,0],[2,122,35,10,\"וְלֹא אָמַר. הָרָשָׁע:\",1,0],[2,122,35,10,\"אַיֵּה אֱלוֹהַּ עֹשָׂי. לִירָא מִפָּנָיו:\",2,0],[2,122,35,10,\"נוֹתֵן זְמִירוֹת. כְּמוֹ ״כַּרְמְךָ לֹא תִזְמֹר״ (ויקרא כה:ד), שֶׁמַּכְרִית אֶת הָרְשָׁעִים בַּלַּיְלָה. כְּגוֹן אַמְרָפֶל וַחֲבֵירָיו (בראשית יד:טו), וּמִצְרַיִם (שמות יב:כט), וְסַנְחֵרִיב (מלכים ב יט:לה):\",3,0],[2,122,35,11,\"מַלְּפֵנוּ. מְלַמְּדֵנוּ חָכְמָה יוֹתֵר מִבְּהֵמוֹת, כְּלוֹמַר: חֲשָׁבָנוּ וְגִדְּלָנוּ מִבַּהֲמוֹת וּמֵעוֹף:\",1,0],[2,122,35,12,\"שָׁם יִצְעֲקוּ. וּרְאֵה, אֲשֶׁר שָׁם צוֹעֲקִים הָעֲנִיִּים מִפְּנֵי גְּאוֹן הָעוֹשְׁקִים אוֹתָם, וְהוּא אֵינוֹ עוֹנֶה.\",1,0],[2,122,35,13,\"אַךְ שָׁוְא לֹא יִשְׁמַע. מִיָּד:\",1,0],[2,122,35,13,\"וְשַׁדַּי לֹא יְשׁוּרֶנָּה. לְהִנָּקֵם מִיָּד, אֶלָּא מַאֲרִיךְ אַפּוֹ:\",2,0],[2,122,35,14,\"אַף כִּי תֹאמַר. כָּל שֶׁכֵּן אַתָּה, שֶׁאֵין צַעֲקָתְךָ בָּאָה כִּי אִם עַל יָדוֹ, וְאַתָּה תֹּאמַר וְתִזְעַק עַל אֲשֶׁר לֹא תְשׁוּרֶנּוּ לְהִתְוַכֵּחַ עִמּוֹ; כְּלוֹמַר: אוֹתָם הַקּוֹבְלִים וְצוֹעֲקִים אֵינוֹ מְמַהֵר לַעֲנוֹתָם, וְאַתָּה תִּצְעַק שֶׁלֹּא תְשׁוּרֶנּוּ?\",1,0],[2,122,35,14,\"דִּין לְפָנָיו. (דְּבָרְךָ סס״א) בְּכָל מָקוֹם שֶׁהוּא:\",2,0],[2,122,35,14,\"וּתְחוֹלֵל. וְקַוֵּה לְתַנְחוּמִין:\",3,0],[2,122,35,15,\"וְעַתָּה. דַּע לְךָ, כִּי אַיִן הִיא פְּקִידַת (אַפּוֹ) זֹאת עָלֶיךָ; אֵינָהּ כְּלוּם לְפִי רוֹב עֲווֹנוֹתֶיךָ:\",1,0],[2,122,35,15,\"וְלֹא יָדַע בַּפַּשׁ מְאֹד. בְּרוֹב חֲטָאֲךָ הִתְנַהֵג הַבּוֹרֵא כְּאִלּוּ לֹא יְדָעָם:\",2,0],[2,122,35,15,\"בַּפַּשׁ. לְשׁוֹן רוֹב, כְּמוֹ ״וּפִשְׁתֶּם״ (מלאכי ג:כ), וּכְמוֹ ״כִּי תָפוּשׁוּ וְגוֹ׳״ (ירמיה נ:יא); ״כִּי פָשָׂה הַנֶּגַע״ (ויקרא יג:נא):\",3,0],[2,122,35,16,\"יַכְבִּיר. לְשׁוֹן מְאֹד:\",1,0],[2,122,36,1,\"וַיֹּסֶף אֱלִיהוּא. רָאִיתִי בְּטַעֲמֵי רַבִּי מֹשֶׁה הַדַּרְשָׁן, שֶׁלְּפִיכָךְ אָמַר שְׁלֹשָׁה מַעֲנוֹת, כְּנֶגֶד שְׁלֹשֶׁת רֵיעֵי אִיּוֹב. וְזֶה רְבִיעִי, לְפִיכָךְ נִקְרָא תּוֹסֶפֶת:\",1,0],[2,122,36,2,\"כַּתַּר לִי זְעֵיר וַאֲחַוֶּךָּ. כֻּלּוֹ לְשׁוֹן אֲרַמִּי הוּא: הוֹחֵל לִי מְעַט וַאֲגִידְךָ. כַּתַּר לְשׁוֹן הוֹחֵל, כַּאֲשֶׁר תִּרְגֵּם יוֹנָתָן ״וּלְתוֹרָתוֹ אִיִּים יְיַחֵלוּ״ (ישעיהו מב:ד): ״יְכַתְּרוּן״:\",1,0],[2,122,36,2,\"לֶאֱלוֹהַּ. לַבָּאִים בִּמְקוֹמוֹ:\",2,0],[2,122,36,4,\"תְּמִים דֵּעוֹת עִמָּךְ. הִנֵּה אַתְחִיל עַתָּה לְדַבֵּר עִמָּךְ, שֶׁאַתָּה סָבוּר שֶׁדַּעְתְּךָ שְׁלֵמָה:\",1,0],[2,122,36,5,\"הֵן אֵל כַּבִּיר. בְּחָכְמָה וּבְרַחֲמִים:\",1,0],[2,122,36,5,\"וְלֹא יִמְאָס. עָנִי:\",2,0],[2,122,36,5,\"כַּבִּיר כֹּחַ לֵב. הוּא לְהִתְנַקֵּם, לְפִיכָךְ לֹא יְחַיֶּה רָשָׁע:\",3,0],[2,122,36,7,\"לֹא יִגְרַע מִצַּדִּיק עֵינָיו. עַד אֲשֶׁר עִם מְלָכִים יוֹשִׁיבֵם:\",1,0],[2,122,36,8,\"וְאִם אֲסוּרִים. וְאִם תִּרְאֶה צַדִּיקִים שֶׁיִּהְיוּ אֲסוּרִים בַּזִּיקִים שֶׁל יִסּוּרִין וָחֳלָיִים, אוֹ יִלָּכְדוּ בְּחַבְלֵי עֹנִי. בִּלְשׁוֹן גּוֹרָל וּמֵיתָרִים נִקְרָא חַבְלֵי, וּבִלְשׁוֹן דְּאָגָה נִקְרָא ״חֶבְלֵי יוֹלֵדָה״ (הושע יג:יג). בְּחַבְלֵי עֹנִי. קוֹדְרֵ״שׁ בְּלַעַ״ז. אֵינוֹ אֶלָּא שֶׁחָטְאוּ לְפָנָיו, וּבָא לִיפָּרַע מֵהֶם לְטוֹבָתָם, לְנַקּוֹתָם, וּלְהַזְהִירָם לָשׁוּב אֵלָיו:\",1,0],[2,122,36,9,\"וַיַּגֵּד לָהֶם פָּעֳלָם. בַּיִּסּוּרִין הַלָּלוּ מוֹדִיעָם שֶׁחָטְאוּ לְפָנָיו. וְכָל דִּבְרֵי אֱלִיהוּא תַּנְחוּמִין שְׁלֵמִים הָיוּ, וְלֹא קִנְתּוּרִין; כְּלוֹמַר: אַל תִּדְאַג עַל יִסּוּרִין, אִם צָדַקְתָּ, כִּי לְטוֹבָה הֵן לְךָ:\",1,0],[2,122,36,10,\"וַיֹּאמֶר. כִּי בְּיִסּוּרִין יְשׁוּבוּן מֵאָוֶן:\",1,0],[2,122,36,11,\"אִם יִשְׁמְעוּ. וְיַעַבְדוּהוּ:\",1,0],[2,122,36,13,\"וְחַנְפֵי לֵב. שֶׁהֵם רְשָׁעִים, הֵם יָשִׂימוּ אָף – בְּבֹא יִסּוּרִין עֲלֵיהֶם, מְחָרְפִים וּמְגַדְּפִים:\",1,0],[2,122,36,13,\"וְלֹא יְשַׁוְּעוּ. לְפָנָיו בִּתְחִנָּה:\",2,0],[2,122,36,13,\"כִּי אֲסָרָם. כְּשֶׁהוּא אוֹסְרָן בְּיִסּוּרִין, לְפִיכָךְ לֹא יִרְפָּאֵם:\",3,0],[2,122,36,14,\"תָּמֹת בַּנֹּעַר. וּבְשִׁנּוּק שֶׁעֲלֵיהֶם נַפְשָׁם:\",1,0],[2,122,36,15,\"יְחַלֵּץ עָנִי. אֶת הֶעָנִי, הַשָּׂם עַצְמוֹ רָשׁ בִּדְבַר תַּחֲנוּנִים, יְחַלֵּץ מִגֵּיהִנֹּם בִּשְׁבִיל עָנְיוֹ שֶׁהֵבִיא עָלָיו:\",1,0],[2,122,36,15,\"וְיִגֶל בַּלַּחַץ אָזְנָם. בַּלַּחַץ שֶׁהֵבִיא עָלָיו, מְגַלֶּה אֶת אָזְנוֹ, לֵאמֹר: שׁוּב אֵלַי!\",2,0],[2,122,36,16,\"וְאַף. זֹאת עוֹד גְּדוֹלָה עָשָׂה לְךָ בְּיִסּוּרִין הַלָּלוּ: הֲסִיתְךָ וְהִדִּיחֲךָ מִגֵּיהִנֹּם, שֶׁפִּיהָ צַר וְתַחְתֶּיהָ רָחָב:\",1,0],[2,122,36,16,\"לֹא מוּצָק. כְּדֵי שֶׁיְּהֵא עֲשָׁנָהּ צָבוּר לְתוֹכָהּ. וְלֹא עוֹד, אֶלָּא שֶׁתִּזְכֶּה לָעוֹלָם הַבָּא, וְנַחַת שֻׁלְחָנְךָ מָלֵא דָשֶׁן:\",2,0],[2,122,36,17,\"וְדִין רָשָׁע מָלֵאתָ. וְאִם נִתְמַלֵּאתָ בְּיִסּוּרֵי הָרְשָׁעִים, הַדִּין וְהַמִּשְׁפָּט הֵם הַיִּסּוּרִין; הֵם יִתְמֹכוּ לְךָ לֶעָתִיד מִגֵּיהִנֹּם, וְיֵשׁ לְךָ לְקַבְּלָם בְּאַהֲבָה:\",1,0],[2,122,36,18,\"כִּי חֵמָה. גְּדוֹלָה תִּהְיֶה:\",1,0],[2,122,36,18,\"פֶּן יְסִיתְךָ. יִצְרְךָ לְדַבֵּר דְּבָרִים:\",2,0],[2,122,36,18,\"בְּשָׂפֶק. בְּשָׂפֶק זֶה אֲשֶׁר תִּשְׂפֹּק, וְתֶרֶב אֲמָרֶיךָ לָאֵל. וּמֵאַחַר שֶׁתַּעֲלֶה הַחֵמָה, רָב מָמוֹן אַל יַטֶּךָּ מִמֶּנָּה:\",3,0],[2,122,36,19,\"הֲיַעֲרֹךְ שׁוּעֲךָ לֹא בְצָר. וְכִי בָּאתָה לַעֲרֹךְ צְעָקָה, שֶׁלֹּא תְּבוֹאֲךָ שׁוּם צָרָה וְשׁוּם מַאֲמַצֵּי כֹחַ לְאוֹנְסְךָ, אִם כֵּן בַּמֶּה יִגְבֶּה אֶת חוֹבוֹ?\",1,0],[2,122,36,20,\"אַל תִּשְׁאַף הַלָּיְלָה. כְּלוֹמַר: וְאֵין לְךָ לִבְחֹר בְּיִסּוּרִים אֲחֵרִים; אַל תִּשְׁאַף וְתִתְאַוֶּה הַלַּיְלָה שֶׁבָּא לְאַמְרָפֶל, לְמִצְרַיִם וּלְסַנְחֵרִיב, לְסַלֵּק עַמִּים מִן הָעוֹלָם, כְּשֶׁהֵם תַּחְתָּם – בִּמְקוֹמָם, בְּשַׁלְוָה; כִּי הֵם אָבְדוּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא:\",1,0],[2,122,36,20,\"לַעֲלוֹת. כְּמוֹ ״אַל תַּעֲלֵנִי בַּחֲצִי יָמָי״ (תהילים קב:כה), ״כַּעֲלוֹת גָּדִישׁ בְּעִתּוֹ״ (איוב ה:כו):\",2,0],[2,122,36,21,\"הִשָּׁמֶר אַל תֵּפֶן אֶל אָוֶן. לָדוּן וְלוֹמַר: הָיָה לוֹ לְשָׁפְטֵנִי בְּיִסּוּרֵי עֲנִיּוּת:\",1,0],[2,122,36,21,\"כִּי עַל זֶה בָּחַרְתָּ מֵעֹנִי. כִּי עַל הַיִּסּוּרִין הַלָּלוּ יֵשׁ לִבְחֹר יוֹתֵר מֵעֲנִיּוּת אָדָם שֶׁנָּהֲגוּ בּוֹ כָּבוֹד, וְלָמוּד בְּעֹשֶׁר כָּל יָמָיו, וְיַעֲמֹד עַל הַמֶּקַח וְאֵין לוֹ דָּמִים, וּבוֹשׁ וְשָׁב לְבֵיתוֹ בְּפַחֵי נֶפֶשׁ. וְאִם תֹּאמַר: אִיּוֹב עָנִי הָיָה עִם הַיִּסּוּרִין? לֹא מָצִינוּ שֶׁאִבֵּד, אֶלָּא בְּהֵמוֹתָיו, אֲבָל לֹא כֶּסֶף וְזָהָב. וַאֲפִלּוּ אִבֵּד בְּהֵמוֹתָיו עִם כֶּסֶף וְזָהָב, טוֹב לוֹ לִהְיוֹת עָנִי וְחוֹלֶה, מִהְיוֹת תָּמִים וְהוֹלֵךְ בַּשְּׁוָקִים וְאֵין בְּיָדוֹ כְּלוּם. וְכֵן מְפֹרָשׁ בְּמִדְרַשׁ רַבִּי תַּנְחוּמָא מִן הַמִּקְרָא הַזֶּה (תנחומא, משפטים יא), כִּי נוֹחִין הָיוּ יִסּוּרֵי אִיּוֹב מִיִּסּוּרֵי עֲנִיּוּת. וְכֵן בְּאַגָּדוֹת הַגְּמָרָא (בבא בתרא קטז.):\",2,0],[2,122,36,22,\"הֵן אֵל יַשְׂגִּיב בְּכֹחוֹ. מִתּוֹךְ שֶׁכֹּחוֹ גָּדוֹל וְאֵין לְהִנָּצֵל מִפָּנָיו, לְפִיכָךְ אֵין כָּמוֹהוּ מוֹרֶה. כְּשֶׁמּוֹרֶה לַחוֹטֵא לָשׁוּב אֵלָיו, מַתְרֶה קוֹדֶם מַכָּה, לְפִי שֶׁהוּא יוֹדֵעַ שֶׁאֵין יָכוֹל לְהִשָּׁמֵר מִמַּכָּתוֹ; כְּמוֹ שֶׁהָיָה מַתְרֶה בְּפַרְעֹה עַל כָּל מַכָּה וּמַכָּה: ״הִנְנִי מַמְטִיר כָּעֵת מָחָר בָּרָד״ (שמות ט:יח), וְ״הִנְנִי מֵבִיא מָחָר אַרְבֶּה״ (שמות י:ד); וְכֵן כֻּלָּם. וּבָשָׂר וָדָם, כְּשֶׁרוֹצֶה לְהִנָּקֵם מֵאוֹיְבָיו, בָּא עָלָיו פִּתְאוֹם; שֶׁאִם יַתְרֶה בּוֹ, יַחֲזֹר וְיִנָּצֵל מִמֶּנּוּ:\",1,0],[2,122,36,23,\"מִי פָקַד עָלָיו דַּרְכּוֹ. יְצַוֶּה עָלָיו מֵעוֹלָם: אֶת הַדֶּרֶךְ הַזֶּה תֵּלֵךְ:\",1,0],[2,122,36,24,\"זְכֹר. דְּרָכָיו, וּבְהַזְכִּירְךָ תַּשְׂגִּיא מֵאֵלֶיךָ שֶׁבַח פֹּעַל מִדּוֹתָיו:\",1,0],[2,122,36,24,\"אֲשֶׁר שֹׁרְרוּ אֲנָשִׁים. אֲשֶׁר רָאוּ אֲנָשִׁים, כְּמוֹ ״אֲשׁוּרֶנּוּ וְלֹא קָרוֹב״ (במדבר כד:יז):\",2,0],[2,122,36,25,\"חָזוּ בוֹ. בְּפָעֳלוֹ:\",1,0],[2,122,36,25,\"מֵרָחוֹק. מִיְּצִירַת עוֹלָם עַד עַכְשָׁיו:\",2,0],[2,122,36,26,\"מִסְפַּר שָׁנָיו וְלֹא חֵקֶר. לְפִיכָךְ צָרִיךְ לֶאֱנוֹשׁ לְהַבִּיט מֵרָחוֹק, לִשְׁאוֹל מַה שֶּׁאֵרַע בָּרִאשׁוֹנִים, וְיִלְמַד מֵהֶם:\",1,0],[2,122,36,27,\"כִּי יְגָרַע. כִּי יַרְבֶּה, כְּמוֹ ״וְתִגְרַע שִׂיחָה״ (איוב טו:ד). וְיֵשׁ פּוֹתְרִים: יִגְרָעֵם מִן הַשָּׁמַיִם, לְהוֹרִידָם אָרֶץ:\",1,0],[2,122,36,27,\"וְיָזֹקּוּ. הָרְקִיעִים אֶת הַמָּטָר:\",2,0],[2,122,36,27,\"לְאֵדוֹ. לַעֲנָנוֹ:\",3,0],[2,122,36,29,\"אַף אִם יָבִין. אוֹ אִם יָבִין אָדָם מַה יֵּשׁ בְּמִפְרְשֵׂי עָב, בִּתְמִיהַּ:\",1,0],[2,122,36,29,\"תְּשֻׁאוֹת. לְשׁוֹן עֲרָפֶל סֻכָּתוֹ:\",2,0],[2,122,36,30,\"הֵן פָּרַשׂ. עַל הֶעָב אֶת אוֹרוֹ, וְשָׁרְשֵׁי הַיָּם כִּסָּה בּוֹ:\",1,0],[2,122,36,31,\"כִּי בָם. בֶּעָבִים יָדִין עַמִּים – יְיַסְּרֵם בַּעֲצִירַת גְּשָׁמִים, בָּרָעָב וְכָל מַכָּה. חָטְאוּ דּוֹר הַמַּבּוּל – ״וַאֲרֻבֹּת הַשָּׁמַיִם נִפְתָּחוּ״ (בראשית ז:יא), אַנְשֵׁי סְדוֹם – ״גָּפְרִית וָמֶלַח שְׂרֵפָה כָל אַרְצָהּ״ (דברים כט:כב), סִיסְרָא – ״מִן הַשָּׁמַיִם נִלְחֲמוּ עִם סִיסְרָא״ (שופטים ה:כ):\",1,0],[2,122,36,31,\"יִתֶּן אֹכֶל לְמַכְבִּיר. מִשָּׁם בָּאִים מְזוֹנוֹת: ״הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם״ (שמות טז:ד). מָשָׁל לְנַחְתּוֹם הָעוֹמֵד לִפְנֵי הַכִּבְשָׁן – נִכְנַס שׂוֹנְאוֹ, חוֹתֶה גֶּחָלִים וְזוֹרֵק בּוֹ; נִכְנַס אוֹהֲבוֹ, מוֹצִיא פַּת חַמָּה וְנוֹתֵן לוֹ:\",2,0],[2,122,36,31,\"לְמַכְבִּיר. לְמִי שֶׁטְּפָלָיו מְרֻבִּים וְכַבִּירִים, וְצָרִיךְ לִמְזוֹנוֹת:\",3,0],[2,122,36,32,\"עַל כַּפַּיִם. עַל הֶעָנָנִים, וְכֵן ״נִשָּׂא לְבָבֵנוּ אֶל כַּפָּיִם״ (איכה ג:מא), עַל שֵׁם ״עָב קְטַנָּה כְּכַף אִישׁ״ (מלכים א יח:מד). וְרַבּוֹתֵינוּ אָמְרוּ (תענית ז:): עַל חָמָס וְעָוֹן כַּפַּיִם כִּסָּה אוֹר, הַמָּטָר נֶעֱצָר:\",1,0],[2,122,36,32,\"וַיְצַו עָלֶיהָ. לָבוֹא עַל יְדֵי מַפְגִּיעַ בִּתְפִלָּה, אוֹהֲבוֹ שֶׁל דּוֹר וְגָדוֹל וְחָכָם שֶׁבּוֹ, יַגִּיד עָלָיו לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא צָרַת הַדּוֹר וּצְרָכָיו:\",2,0],[2,122,36,33,\"יַגִּיד עָלָיו רֵעוֹ. יִדְרֹשׁ לָהֶם לִבְדֹּק לָהֶם בְּמַעֲשֵׂיהֶם וְלָשׁוּב אֵלָיו:\",1,0],[2,122,36,33,\"מִקְנֶה. וְזֶהוּ קִנְיָן שֶׁנִּקְנִין בּוֹ הַגְּשָׁמִים:\",2,0],[2,122,36,33,\"אַף עַל עוֹלֶה. גַּם לְמַעְלָה לְמַעְלָה, כְּמוֹ ״יָשׁוּבוּ אֶל עָל״ (הושע ז:טז), אוֹ ״הֻקַם עָל״ (שמואל ב כג:א). וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ (תענית ח.): קִנְיַן אַף וְחֵמָה עַל הַמֵּגִיס דַּעְתּוֹ. אֲבָל הַנִּקּוּד, שֶׁנִּקַּד מִקְנֶה – פַּתָּח, מוֹכִיחַ, שֶׁהוּא אֵינוֹ דָבוּק לְאַף; שֶׁאִלּוּ הָיָה דָבוּק, הָיָה נָקוּד קָמַץ, וְלֹא הָיָה בּוֹ פִּסּוּק הַטַּעַם, שֶׁהוּא נִטְעָם בִּ׳רְבִיעִי׳:\",3,0],[2,122,37,1,\"וְיִתַּר. וְיִקְפֹּץ, כְּמוֹ ״לְנַתֵּר בָּהֶם עַל הָאָרֶץ״ (ויקרא יא:כא). וְזוֹ הִיא שֶׁלִּבּוֹ תּוֹהֶה:\",1,0],[2,122,37,2,\"שִׁמְעוּ שָׁמוֹעַ בְּרֹגֶז קוֹלוֹ. הָרְעָמִים שֶׁהוּא מַרְעִים בָּרָקִיעַ, כְּהֶגֶה הַיּוֹצֵא מִפִּיו:\",1,0],[2,122,37,3,\"תַּחַת כָּל הַשָּׁמַיִם יִשְׁרֵהוּ. רְאִיתִיו, כְּמוֹ ״אֲשׁוּרֶנּוּ״ (במדבר כד:יז). וְהֵם אוֹתָם אוֹרוֹת שֶׁהַבְּרָקִים מְאִירִים:\",1,0],[2,122,37,4,\"אַחֲרָיו. שֶׁל אוֹתוֹ אוֹר, יִשְׁאַג הָרַעַם וּמַרְעִים בְּקוֹל גְּאוֹנוֹ, וְהֵם בְּרָקִים וּרְעָמִים הַמְּבִיאִים אֶת הַמָּטָר:\",1,0],[2,122,37,4,\"וְלֹא יְעַקְּבֵם. הַמָּקוֹם:\",2,0],[2,122,37,4,\"כִּי יִשָּׁמַע. לְפָנָיו קוֹלוֹ שֶׁל מַפְגִּיעַ (איוב לו:לב):\",3,0],[2,122,37,4,\"יְעַקְּבֵם. יַכְרִיתֵם, וּלְשׁוֹן מִשְׁנָה שָׁנִינוּ (סוטה טז.): בְּשָׁלֹשׁ מְקוֹמוֹת הֲלָכָה עוֹקֶבֶת מִקְרָא:\",4,0],[2,122,37,6,\"כִּי לַשֶּׁלֶג יֹאמַר. עַל יְדֵי הַקּוֹלוֹת הַלָּלוּ:\",1,0],[2,122,37,6,\"הֱוֵא אָרֶץ וְגֶשֶׁם מָטָר וְגֶשֶׁם מִטְרוֹת עֻזּוֹ. כְּלוֹמַר מֵאַרְבַּע רוּחוֹת יָבֹא:\",2,0],[2,122,37,7,\"בְּיַד כָּל אָדָם יַחְתּוֹם. כְּשֶׁאָדָם חוֹטֵא לְפָנָיו, הָאָדָם עַצְמוֹ חוֹתֵם כְּתַב יָדוֹ בְּיוֹם מוֹתוֹ עַל עֲבֵירוֹת שֶׁעָבַר, הַכְּתוּבוֹת לְפָנָיו:\",1,0],[2,122,37,7,\"לָדַעַת כָּל אַנְשֵׁי מַעֲשֵׂהוּ. לְהוֹדִיעַ עַל מָה הוּא נִידּוֹן:\",2,0],[2,122,37,8,\"וַתָּבֹא חַיָּה בְמוֹ אָרֶב. כְּלוֹמַר: וְעוֹד שְׁלוּחִים הַרְבֵּה יֵשׁ לַמָּקוֹם לִיפָּרַע פּוּרְעָנוּתָיו, שִׁלּוּחַ חַיּוֹת רָעוֹת וְסוּפָה וְקָרָה:\",1,0],[2,122,37,9,\"וּמִמְּזָרִים. אוֹצָר יֵשׁ וּשְׁמוֹ מְזָרִים:\",1,0],[2,122,37,10,\"מִנִּשְׁמַת. מֵרוּחוֹ:\",1,0],[2,122,37,10,\"וְרֹחַב מַיִם בְּמוּצָק. בִּיצִיקָה לְפֻרְעָנוּת:\",2,0],[2,122,37,11,\"אַף בְּרִי. שֵׁם מַלְאָךְ הַמְמֻנֶּה עַל הָעֲנָנִים, וְהוּא יָפִיץ עֲנַן מְטָרוֹ שֶׁל הַמָּקוֹם:\",1,0],[2,122,37,11,\"עֲנַן אוֹרוֹ. עֲנַן מְטָרוֹ:\",2,0],[2,122,37,12,\"וְהוּא. הַמְּמֻנֶּה:\",1,0],[2,122,37,12,\"מְסִבּוֹת מִתְהַפֵּךְ בְּתַחְבּוּלוֹתָיו. שֶׁל מָקוֹם:\",2,0],[2,122,37,12,\"לְפָעֳלָם. שֶׁל גְּשָׁמִים. לְפֹעַל הַמּוּטָּל עֲלֵיהֶם לַעֲשׂוֹת, אִם טוֹב וְאִם רַע, מִתְהַפֵּךְ בִּמְסִבּוֹת הַרְבֵּה. כְּאוֹתוֹ שֶׁשָּׁנִינוּ (ראש השנה יז:): הֲרֵי שֶׁהָיוּ יִשְׂרָאֵל צַדִּיקִים גְּמוּרִים בְּרֹאשׁ הַשָּׁנָה, וּפָסְקוּ לָהֶם גְּשָׁמִים; לְסוֹף סָרְחוּ – לִפְחוֹת מֵהֶם אִי אֶפְשָׁר, שֶׁכְּבָר נִגְזְרָה גְּזֵרָה; אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹרִידָם שֶׁלֹּא בִזְמַנָּם, וְעַל אֶרֶץ שֶׁאֵינָהּ צְרִיכָה לָהֶם. וְעִתִּים לְטוֹבָה; כֵּיצַד? וְכוּ׳:\",3,0],[2,122,37,12,\"כָּל אֲשֶׁר יְצַוֵּם. לְאוֹתָן גְּשָׁמִים לַעֲשׂוֹת לָאָרֶץ. דָּבָר אַחֵר: וְהוּא מְסִבּוֹת מִתְהַפֵּךְ בְּתַחְבּוּלוֹתָיו. מַקִּיף עֲנָנִים וְרוּחוֹת סְבִיבוֹת הֶהָרִים, שֶׁיִּהְיוּ שׁוֹתִים מִכָּל רוּחוֹתֵיהֶם. בְּאַגָּדַת ׳וְהָיָה עֵקֶב׳ (ספרי דברים לט):\",4,0],[2,122,37,13,\"אִם לְשֵׁבֶט. אִם לְפוּרְעָנוּת בְּנֵי אָדָם, מוֹרִידָם בֶּהָרִים וּגְבָעוֹת, שֶׁאֵין מְקוֹם זְרִיעָה:\",1,0],[2,122,37,13,\"אִם לְאַרְצוֹ. לְהוֹרִידָם כַּאֲשֶׁר נִגְזַר בִּתְחִלַּת דִּין, לֹא לְשֵׁבֶט וְלֹא לִפְנִים מִן הַשּׁוּרָה, אֶלָּא בְּבֵינוֹנִית:\",2,0],[2,122,37,13,\"אִם לְחֶסֶד. שֶׁנַּעֲשׂוּ הַדּוֹר עַכְשָׁיו יוֹתֵר צַדִּיקִים מִשֶּׁהָיוּ בְּרֹאשׁ הַשָּׁנָה, וְאוֹתָן גְּשָׁמִים שֶׁנִּגְזְרוּ בְּבֵינוֹנִית, מִתְהַפֵּךְ בְּתַחְבּוּלוֹת מְסִבּוֹתֵיהֶם, לֵירֵד בְּחֶסֶד בִּזְמַנָּם, וְעַל הָאָרֶץ הַצְּרִיכָה לָהֶם; שֶׁלֹּא תֵּרֵד הַטִּפָּה מֵהֶם לְאִבּוּד:\",3,0],[2,122,37,13,\"יַמְצִיאֵהוּ. לַמָּטָר, לְאַחַת מִן הַמִּדּוֹת הַלָּלוּ:\",4,0],[2,122,37,15,\"בְּשׂוּם אֱלוֹהַּ. חֹק בְּרִית עֲלֵיהֶם, הֵיאַךְ תְּלוּיִים בְּמַאֲמָר:\",1,0],[2,122,37,16,\"מִפְלְשֵׂי עָב. גִּילּוּי עָב, לְשׁוֹן מָבוֹי מְפוּלָּשׁ. כְּלוֹמַר: לְאָרְכָּן וּלְרָחְבָּן שֶׁל עָבִים:\",1,0],[2,122,37,16,\"הֲתֵדַע. עֲלֵיהֶם מִפְלְאוֹת תְּמִים דֵּעִים:\",2,0],[2,122,37,17,\"אֲשֶׁר בְּגָדֶיךָ חַמִּים. בַּמֶּה בְּגָדֶיךָ חַמִּים? בְּהַשְׁקִיטִי אֶרֶץ מֵרוּחַ דְּרוֹמִית, שֶׁאֵינָהּ הוֹרֶגֶת אֶת הָעוֹלָם בְּקָרָה; שֶׁרוּחַ מִזְרָחִית מְחַמֶּמֶת, שֶׁנֶּאֱמַר ״רוּחַ קָדִים חֲרִישִׁית״ (יונה ד:ח) – שֶׁמַּשְׁתֶּקֶת כָּל הָרוּחוֹת מִפָּנֶיהָ:\",1,0],[2,122,37,18,\"חֲזָקִים. הָרְקִיעִים:\",1,0],[2,122,37,18,\"כִּרְאִי מוּצָק. כִּרְאִי שֶׁהַנָּשִׁים רוֹאוֹת בּוֹ, (מוּצָק טְרִישְׁטְיֵי״ר וְהוּא חָזָק בְּיוֹתֵר):\",2,0],[2,122,37,19,\"הוֹדִיעֵנוּ מַה נֹּאמַר לוֹ. לְהַקָּדוֹשׁ בָּרוּךְ הוּא, בְּרִיבֵנוּ עִמּוֹ. לֹא נוּכַל לַעֲרֹךְ אֵלָיו מִפְּנֵי חֹשֶׁךְ. אֲשֶׁר סִתְרוֹ וּסְבִיבוֹתָיו (תהלים יח:יב):\",1,0],[2,122,37,20,\"הֲיְסֻפַּר לוֹ כִּי אֲדַבֵּר. וְכִי כְּמִדַּת הַבְּרִיּוֹת הוּא, שֶׁצָּרִיךְ שֶׁיְּסַפְּרוּ אֵלָיו דְּבָרִים הַיּוֹצְאִים מִפִּינוּ?\",1,0],[2,122,37,20,\"אִם אָמַר אִישׁ. אוֹמֵר מִפִּיו:\",2,0],[2,122,37,20,\"כִּי יְבֻלָּע. יְגֻלֶּה אֵלָיו מִיָּד, כְּמוֹ ״פֶּן יְבֻלַּע לַמֶּלֶךְ״ (שמואל ב יז:טז) יִגָּלֶה. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (מגילה יח.) הַיְסֻפַּר כָּל שִׁבְחוֹ לוֹ כִּי אֲדַבֵּר. כִּי נְדַבֵּר בּוֹ וּבִגְבוּרָתוֹ, אִם אָמַר אִישׁ, לְסַפְּרָם כֻּלָּם כִּי יְבֻלָּע. מִמְּקוֹמוֹ:\",3,0],[2,122,37,21,\"וְעַתָּה לֹא רָאוּ אוֹר. בְּסוֹף דְּבָרָיו אֶל אֱלִיהוּא חָזַר לְקַנְתֵּר אוֹתָן שְׁלֹשֶׁת רֵיעֵי אִיּוֹב עַל לֹא מָצְאוּ מַעֲנֶה (איוב לב:א-ג), וְאָמַר: וְעַתָּה, שְׁלֹשֶׁת רֵיעֶיךָ אֵלֶּה, שֶׁהָיָה לָהֶם לַהֲשִׁיבְךָ כָּל דְּבָרִים אֵלּוּ שֶׁאָמַרְתִּי לְךָ, לֹא רָאוּ אוֹר. נַעֲשׂוּ הֵמָּה כִּנְפָלִים אֲשֶׁר לֹא רָאוּ חָכְמָה (איוב ג:טז):\",1,0],[2,122,37,21,\"בָּהִיר הוּא בַּשְּׁחָקִים. דּוֹמֶה לַבְּהִירִים הַנִּרְאִים בַּשְּׁחָקִים, לְהוֹרִיד גֶּשֶׁם:\",2,0],[2,122,37,21,\"וְרוּחַ עָבְרָה. וְרוּחַ בָּא וּמְטַהֲרָתָן וּמַעֲבִירָתָן, וְאֵין מָטָר יוֹרֵד. כָּךְ הוּא דֻּגְמָא שֶׁלָּהֶם: הִתְחִילוּ לַהֲשִׁיבְךָ, וְסוֹף עָמְדוּ וְלֹא עָנוּ (איוב לב:טז):\",3,0],[2,122,37,22,\"מִצָּפוֹן זָהָב יֶאֱתֶה. הֲרֵי הוּא כְּחוֹזֵר עַל הָרִאשׁוֹנוֹת. דָּבָר אַחֵר: מִדְרַשׁ חֲכָמִים (תענית ז:): כְּשֶׁהָרָקִיעַ מָלֵא בֶּהָרוֹת עֲנָנִים עֲנָנִים לְהוֹרִיד גֶּשֶׁם, רוּחַ עָבְרָה וַתְּטַהֲרֵם, וְאֵין גֶּשֶׁם יוֹרֵד. זֶה מִדְרַשׁ חֲכָמִים, וְאֵינָהּ מִתְיַשֶּׁבֶת עַל סֵדֶר הַמִּקְרָאוֹת:\",1,0],[2,122,37,22,\"מִצָּפוֹן זָהָב יֶאֱתֶה. מְנַשֵּׁב רוּחַ צְפוֹנִית וּמַעֲבִיר הַגֶּשֶׁם, וְהַחַמָּה זוֹרַחַת; כְּמוֹ ״הַמְּרִיקִים מֵעֲלֵיהֶם הַזָּהָב״ (זכריה ד:יב):\",2,0],[2,122,37,22,\"עַל אֱלוֹהַּ. מִלְּפָנָיו:\",3,0],[2,122,37,22,\"מִצָּפוֹן זָהָב יֶאֱתֶה. נִצְפַּן הַזָּהָב הַטּוֹב לְאוֹתָן שֶׁיֵּאָתִיּוּ אֶת עַצְמָן לְמִצְווֹת הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמַאֲמִינִים בֵּאלוֹהַּ הַנּוֹרָא מְאֹד:\",4,0],[2,122,37,23,\"שַׁדַּי לֹא מְצָאנוּהוּ שַׂגִּיא כֹחַ. לְעוֹרֵר מִשְׁפָּטָיו עַל הַבְּרִיּוֹת בְּגֹדֶל כֹּחוֹ, כִּי אִם בְּרַחֲמִים. וְכַפָּרַת הַבְּרִיּוֹת שָׂם בְּדָבָר מוּעָט לְפִי הַיְּכֹלֶת: קֹמֶץ מִנְחָה, מַחֲצִית הַשֶּׁקֶל, תּוֹרִים וּבְנֵי יוֹנָה, בָּקָר וְצֹאן; וְלֹא טָרַח לְבַקֵּשׁ רְאֵם וְיַחְמוּר:\",1,0],[2,122,37,23,\"וּמִשְׁפָּט. יִסּוּרִין:\",2,0],[2,122,37,23,\"לֹא יְעַנֶּה. הַבְּרִיּוֹת יוֹתֵר מִדַּאי, וְכֵן לֹא יְעַנֶּה הַצַּדִּיק יוֹתֵר מִדַּאי בְּמַה שֶׁאִי אֶפְשָׁר, כִּי אִם ״אִישׁ כְּמַתְּנַת יָדוֹ״ (דברים טז:יז):\",3,0],[2,122,37,24,\"לָכֵן יְרֵאוּהוּ אֲנָשִׁים. מִלְּהִתְוַכֵּחַ אֵלָיו, (כִּי) לֹא יִרְאֶה כָּל חַכְמֵי לֵב. הַמִּתְחַכְּמִים אֵלָיו, כִּי אֵין חָכְמָתָם בְּעֵינָיו כְּלוּם. וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ עַל אִיּוֹב (ראש השנה יז.), שֶׁאָמַר לוֹ אֱלִיהוּא: לְפִי שֶׁהָיִיתָ מֵטִיל אֵימָה יְתֵרָה עַל דּוֹרְךָ חִנָּם, לְפִיכָךְ לֹא זָכִיתָ לְהִתְקַיֵּם לְךָ בָּנִים חַכְמֵי לֵב:\",1,0],[2,122,38,1,\"(מענה מן הסערה): מִן הַסְּעָרָה: מְנֵה שְׂעָרוֹת שֶׁלְּךָ, וַאֲשִׁיבְךָ דְּבָרִים כְּנֶגְדָּן. מִן הַסְּעָרָה שֶׁחֵרַפְתַּנִי ״אֲשֶׁר בַּסְּעָרָה יְשׁוּפֵנִי״ (איוב ט:יז) – מִמֶּנָּה אָשִׁיב לְךָ, כַּאֲשֶׁר תִּשְׁמַע בְּסוֹף הָעִנְיָן: ״מִי פִלַּג לַשֶּׁטֶף תְּעָלָה״ (איוב לח:כה) – גּוּמָא לְכָל שֵׂעָר. דָּבָר אַחֵר: בַּסְּעָרָה הִכָּהוּ, בַּסְּעָרָה רִפְּאָהוּ. כִּדְמְפָרֵשׁ בְּסִפְרֵי (ילקוט שמעוני תורה רלה):\",1,0],[2,122,38,2,\"מַחְשִׁיךְ עֵצָה. עֵצָה חֲשֵׁכָה וּסְכָלָה. דָּבָר אַחֵר: מִי זֶה מַחְשִׁיךְ עֵצָה… בְּלִי דָעַת. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מִי זֶה הוּא מַחְשִׁיךְ עֵצָה – מְקַלְקֵל בְּמִלִּים וּבְרֹב דְּבָרִים? שֶׁכָּתַבְתִּי ״אִישׁ תָּם וְיָשָׁר״ בִּתְחִלַּת הַסֵּפֶר (איוב א:א), כְּדֵי לָחוּל שְׁמִי עָלָיו; וְהוּא בָּא וְהֶחְשִׁיךְ וְקִלְקֵל מַה שֶּׁיָּעַצְתִּי בְּרֹב דְּבָרָיו! וְאִיּוֹב עָנָהוּ: ״מִי זֶה מַעְלִים עֵצָה״ (איוב מב:ג) – אִלּוּ הָיִיתִי יוֹדֵעַ עֲצָתְךָ, לֹא הָיִיתִי מַרְבֶּה בִדְבָרִים. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֱשִׁיבוֹ: וַהֲלֹא אַבְרָהָם לֹא הָיָה יוֹדֵעַ, וְעָמַד בְּעֶשֶׂר! כָּךְ מָצָאתִי:\",1,0],[2,122,38,3,\"אֱזָר נָא כְגֶבֶר חֲלָצֶיךָ. רֶמֶז לוֹ שֶׁיִּתְעוֹרֵר מִן חָלְיוֹ וְיִסּוּרָיו:\",1,0],[2,122,38,4,\"אֵיפֹה. אֵי פֹּה:\",1,0],[2,122,38,5,\"מְמַדֶּיהָ. מִדּוֹתֶיהָ:\",1,0],[2,122,38,6,\"יָרָה אֶבֶן פִּנָּתָהּ. בְּאֶמְצַע הַיָּם, וּמִשָּׁם נִשְׁתַּת כָּל הָעוֹלָם:\",1,0],[2,122,38,7,\"בְּרָן יַחַד. מִתְּחִלָּה כּוֹכְבֵי אוֹר:\",1,0],[2,122,38,8,\"בִּדְלָתַיִם יָם. חוֹל גְּבוּל לוֹ:\",1,0],[2,122,38,8,\"בְּגִיחוֹ. בְּהַמְשָׁכָתוֹ יוֹצֵא מִן הַתְּהוֹם, כְּמוֹ ״גֹּחִי מִבָּטֶן״ (תהלים כב:י) – מוֹשְׁכִי:\",2,0],[2,122,38,9,\"בְּשׂוּמִי עָנָן. סְבִיבוֹת יָם אוֹקְיָינוֹס, שֶׁהוּא הֶיקֵּף הָעוֹלָם; וַעֲנָנִים סוֹבְבִים לוֹ כִּלְבוּשׁ:\",1,0],[2,122,38,9,\"חֲתֻלָּתוֹ. תַּכְרִיכוֹ, כְּמוֹ ״וְהָחְתֵּל לֹא חֻתָּלְתְּ״ (יחזקאל טז:ד):\",2,0],[2,122,38,10,\"וָאֶשְׁבֹּר. עָשִׂיתִי לוֹ שְׁבָרִים סָבִיב, לְעַכְּבוֹ בְּתוֹכָם. וְהֵם לוֹ חֹק אֲשֶׁר לֹא יַעַבְרֵם (ירמיה ה:כב), כְּמוֹ ״וַיִּרְדְּפוּם לִפְנֵי הַשַּׁעַר עַד הַשְּׁבָרִים״ (יהושע ז:ה) – וְהֵם תְּעָלוֹת סָבִיב לָעִיר:\",1,0],[2,122,38,12,\"הֲמִיָּמֶיךָ. מִיּוֹם שֶׁנּוֹלַדְתָּ:\",1,0],[2,122,38,13,\"לֶאֱחֹז בְּכַנְפוֹת הָאָרֶץ. וְעוֹד הֲמִיָּמֶיךָ צִוִּיתָ לֶאֱחֹז בְּכַנְפֵי הָאָרֶץ כְּאָדָם שֶׁאוֹחֵז בְּכַנְפֵי הַטַּלִּית וּמְנַעֲרָהּ? כֵּן אֲנִי עָתִיד לֶאֱחֹז בְּכַנְפוֹתֶיהָ וּלְנַעֵר אֶת הָרְשָׁעִים. וְכֵן הוּא אוֹמֵר ״וַה׳ יַטֶּה אֶת יָדוֹ וְכָשַׁל עוֹזֵר״ (ישעיהו לא:ג) כְּאָדָם הָאוֹחֵז בְּיָדוֹ דָּבָר, וּמַטֶּה יָדוֹ, וְהוּא נוֹפֵל:\",1,0],[2,122,38,14,\"תִּתְהַפֵּךְ. בְּצִיּוּרִין:\",1,0],[2,122,38,14,\"כְּחֹמֶר חוֹתָם. מִטֶּבַע צוּרַת הָאָדָם בְּמוֹתָן, וּבִתְחִיַּת הַמֵּתִים יִחְיוּ וְיַעַמְדוּ בִּלְבוּשֵׁיהֶם:\",2,0],[2,122,38,15,\"וְיִמָּנַע. אָז מֵרְשָׁעִים אוֹרָם. וְכֵן הוּא אוֹמֵר: וּזְרוֹעַ רָמָה תִּשָּׁבֵר:\",1,0],[2,122,38,16,\"נִבְכֵי יָם. מַסְגְּרֵי יָם, כְּמוֹ ״נְבֻכִים הֵם בָּאָרֶץ״ (שמות יד:ג):\",1,0],[2,122,38,17,\"שַׁעֲרֵי מָוֶת. זֶה גֵּיהִנֹּם:\",1,0],[2,122,38,21,\"יָדַעְתָּ. כָּל זֹאת:\",1,0],[2,122,38,21,\"כִּי אָז תִּוָּלֵד. כְּשֶׁבְּרָאתִים:\",2,0],[2,122,38,23,\"אֲשֶׁר חָשַׂכְתִּי. הִמְנַעְתִּי:\",1,0],[2,122,38,23,\"לְעֶת צָר. לַחֲמֵשֶׁת מְלָכִים בְּגִבְעוֹן (יהושע י:טז-כז):\",2,0],[2,122,38,23,\"לְיוֹם קְרָב. מִלְחֶמֶת גּוֹג וּמָגוֹג (יחזקאל לח-לט):\",3,0],[2,122,38,24,\"יֵחָלֶק אוֹר. תִּימוֹר שֶׁל חַמָּה מַפְצִיעַ לְכָאן וּלְכָאן כְּקַרְנֵי אַיָּל:\",1,0],[2,122,38,24,\"קָדִים. שֶׁמֶשׁ הַמִּזְרָח:\",2,0],[2,122,38,25,\"מִי פִלַּג לַשֶּׁטֶף תְּעָלָה. בַּעֲרַבְיָא קוֹרִין לְשַׂעֲרָה שִׁיטְפָא: כָּל שֵׂעָר וְשֵׂעָר שֶׁבָּרֹאשׁ פִּלַּגְתִּי לוֹ תְּעָלָה, גּוּמָא, לִינֹק מִמֶּנָּה; שֶׁאִלּוּ שְׁנַיִם יוֹנְקוֹת מִגּוּמָא אַחַת, מַחְשִׁיכוֹת מְאוֹר עֵינָיו שֶׁל אָדָם. וְהֵם לֹא נִתְחַלְּפוּ לִי, בֵּין אִיּוֹב לְאוֹיֵב נִתְחַלֵּף לִי?! וְזֶהוּ ״מִן הַסְּעָרָה״ (איוב לח:א). דָּבָר אַחֵר: לַשֶּׁטֶף. טִפַּת גֶּשֶׁם שׁוֹטֵף: פִּלַּגְתִּי לְכָל טִפָּה גּוּמָא בֶּעָבִים; שֶׁאִלּוּ יוֹרְדוֹת שְׁתֵּי טִפּוֹת מִגּוּמָא אַחַת, מְטַשְׁטְשׁוֹת אֶת הָאָרֶץ, וְנַעֲשֵׂית טִיט:\",1,0],[2,122,38,25,\"וְדֶרֶךְ לַחֲזִיז קוֹלוֹת. מִי פִלַּג? כָּל קוֹל וָקוֹל יֵשׁ לוֹ שְׁבִיל, וְאִם שְׁנַיִם הוֹלְכִים בִּשְׁבִיל אֶחָד, אֵין הַבְּרִיּוֹת סוֹבְלוֹת אֶת הַקּוֹל:\",2,0],[2,122,38,27,\"שׁוֹאָה. אֶרֶץ שֶׁהִיא חֲשֵׁכָה בְּרָעָב:\",1,0],[2,122,38,28,\"אֶגְלֵי טָל. גַּלֵּי טָל, וְהָאָלֶ״ף יְתֵרָה; כְּמוֹ ״וַאֲחַוֶּה דַעְתִּי בְאָזְנֵיכֶם״ (איוב יג:יז) – אָלֶ״ף יְתֵרָה בְּרֹאשׁ הַתֵּיבָה, לִהְיוֹתוֹ שֵׁם דָּבָר; וְכֵן ״אַבְחַת חֶרֶב״ (יחזקאל כא:כ) – כְּמוֹ נִבּוּחַ חֶרֶב, צַעֲקַת חֶרֶב. לָשׁוֹן אַחֵר: אֶגְלֵי. כְּמוֹ אַגְנֵי טָל, כְּמִין אֲגָנוֹת – פְּלָגִים, שֶׁהַטַּל נָתוּן בָּהֶם. לָמֶ״ד מִתְחַלֵּף בְּנוּ״ן; וְכֵן בְּסֵפֶר נְחֶמְיָה: ״נִשְׁכָּה״ (נחמיה יג:ז) כְּמוֹ ״לִשְׁכָּה״ (נחמיה יג:ה):\",1,0],[2,122,38,29,\"כְּפוֹר. גְּרִיסָ״א:\",1,0],[2,122,38,30,\"כָּאֶבֶן מַיִם יִתְחַבָּאוּ. עַל יְדֵי הַקֶּרַח שֶׁמַּגְלִיד טִפָּה שֶׁעַל פְּנֵיהֶם:\",1,0],[2,122,38,30,\"וּפְנֵי תְהוֹם יִתְלַכָּדוּ. בּוֹ, וְיִתְאַחֲזוּ כְּאֶחָד:\",2,0],[2,122,38,31,\"מַעֲדַנּוֹת כִּימָה. קִשּׁוּר כִּימָה, שֶׁלֹּא תֵצֵא כָּל קוֹרוֹתָיו, וְיַחֲרִיב אֶת הָעוֹלָם בְּצִנָּה:\",1,0],[2,122,38,31,\"אוֹ מוֹשְׁכוֹת כְּסִיל תְּפַתֵּחַ. לְהוֹצִיא חַמָּה, לְהָפִיג צִנָּתָהּ שֶׁל כִּימָה:\",2,0],[2,122,38,32,\"מַזָּרוֹת. כָּל שְׁאָר מַזָּלוֹת:\",1,0],[2,122,38,32,\"וְעַיִשׁ. כּוֹכָב גָּדוֹל שֶׁבַּכִּימָה, וְהַרְבֵּה כּוֹכָבִים קְבוּעִים בּוֹ; וְנָטַל שְׁנֵי כוֹכָבִים מִמֶּנָּה, לִפְתֹּחַ אֲרֻבּוֹת הַמַּבּוּל, וְנִבְקְעוּ בְּמַזַּל טָלֶה; וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲזִירָם לָהּ (תנחומא):\",2,0],[2,122,38,33,\"מִשְׁטָרוֹ. שְׁטִירַת הַמַּזָּלוֹת הַמְּמֻנִּים לְהָבִיא עַל הָאָרֶץ ״קֹר וָחֹם קַיִץ וָחֹרֶף״ (בראשית ח:כב):\",1,0],[2,122,38,34,\"הֲתָרִים לָעָב קוֹלֶךָ. לְצַוּוֹת עָלָיו לְהִתְקַשֵּׁר בְּחֶשְׁכַת מַיִם לִהְיוֹת שִׁפְעַת מַיִם מְתְכַסֶּךָ, וְהוּא קַדְרוּת הֶעָבִים, כְּמוֹ ״אוֹ חֹשֶׁךְ לֹא תִרְאֶה״ (איוב כב:יא). אוֹ שִׁפְעַת מַיִם. עַל פִּיךָ יְכַסֶּךָּ מִן הַשָּׁמַיִם:\",1,0],[2,122,38,35,\"וְיֹאמְרוּ לְךָ. בַּמָּקוֹם שֶׁנִּשְׁתַּלְּחוּ שָׁם הִנֵּנוּ, עָשִׂינוּ שְׁלִיחוּתְךָ! שֶׁאֵין צְרִיכִין לַחֲזֹר לִמְקוֹמָן, וּלְהָשִׁיב שׁלוּחָן, שֶׁהַשְּׁכִינָה בְּכָל מָקוֹם:\",1,0],[2,122,38,36,\"בַּטֻּחוֹת. אֵלּוּ הַכְּלָיוֹת:\",1,0],[2,122,38,36,\"לַשֶּׂכְוִי. זֶה תַּרְנְגוֹל; לְשׁוֹן חֲכָמִים (ראש השנה כו.). וְיֵשׁ אוֹמְרִים: זֶה הַלֵּב, שֶׁהוּא שׂוֹכֶה וְצוֹפֶה וּמְחַשֵּׁב אֶת הַנּוֹלָדוֹת:\",2,0],[2,122,38,37,\"יְסַפֵּר. יְדַבֵּר וְיַזְהִיר תַּפְקִידָם:\",1,0],[2,122,38,37,\"וְנִבְלֵי. עֲשׂוּיִין כְּנוֹדוֹת, וְהַגְּשָׁמִים כְּנוּסִים בּוֹ שָׁם, כְּמוֹ נֵבֶל יָיִן (שמואל א י:ג):\",2,0],[2,122,38,38,\"בְּצֶקֶת עָפָר. בְּיוֹם שֶׁיָּצַקְתִּי עָפָר:\",1,0],[2,122,38,38,\"לַמּוּצָק. לַיְּסוֹד עוֹלָם בְּאֶמְצָעִיתוֹ:\",2,0],[2,122,38,38,\"וּרְגָבִים יְדֻבָּקוּ. סְבִיבוֹתָיו לַצְּדָדִין, עַד כִּי נִתְמַלֵּא אָרְכּוֹ וְרָחְבּוֹ:\",3,0],[2,122,38,40,\"יָשׁוֹחוּ. עוֹמְדִים צְפוּפִים:\",1,0],[2,122,38,40,\"לְמוֹ אָרֶב. לֶאֱרוֹב. כֵּן דֶּרֶךְ הָאוֹרְבִים, לָשׁוּחַ וְלָכוֹף עַצְמָן, כְּדֵי שֶׁלֹּא יַכִּירוּ בָּהֶם:\",2,0],[2,122,38,41,\"יִתְעוּ לִבְלִי אֹכֶל. שֶׁאֲבִיהֶם שׂוֹנְאָם. הַקָּדוֹשׁ בָּרוּךְ הוּא מְזַמֵּן לָהֶם יַתּוּשִׁין, נִבְרָאִים מִצּוֹאָתָן, וְנִכְנָסִין לְתוֹךְ פִּיהֶם:\",1,0],[2,122,39,1,\"יַעֲלֵי סָלַע. אֶשְׁטַנְבּוֹ״ק, וְשׂוֹנְאָה אֶת וְלָדָהּ; וְעוֹלָה לְרֹאשׁ סֶלַע גָּבוֹהַּ כְּשֶׁכּוֹרַעַת לֵילֵד, כְּדֵי שֶׁיִּפּוֹל לָאָרֶץ וְיָמוּת. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְזַמֵּן לוֹ נֶשֶׁר וּמְקַבְּלוֹ בִּכְנָפָיו:\",1,0],[2,122,39,1,\"חוֹלֵל אַיָּלוֹת תִּשְׁמֹר. לְשׁוֹן ״חִיל יוֹלֵדָה״ (ירמיהו ו:כד). הָאַיָּלָה – רַחְמָהּ צַר, וְאֵין הַוָּלָד יָכוֹל לָצֵאת; וּבִשְׁעַת לֵידָתָהּ אֲנִי מְזַמֵּן לָהּ דְּרָקוֹן, וּמַכִּישָׁהּ בְּרַחְמָהּ, וְנִפְתָּח. וְאִם מַקְדִּים וּמְאַחֵר רֶגַע, מִיָּד מֵתָה. וּבֵין אוֹתָם רְגָעִים אֵינִי מַחֲלִיף, וּבֵין ׳אִיּוֹב׳ לְ׳אוֹיֵב׳ נִתְחַלֵּף לִי?!\",2,0],[2,122,39,3,\"תְּפַלַּחְנָה. מִתְבַּקֵּעַ רֶחֶם שֶׁלָּהֶם, וּמוֹצִיא הַוְּלָדוֹת, וְחֶבְלֵי לֵידָה שֶׁלָּהֶם:\",1,0],[2,122,39,3,\"תְּשַׁלַּחְנָה. מֵעֲלֵיהֶם בְּלִדְתָּן, לְרֶגַע שֶׁאֲנִי מַזְמִין לָהֶם:\",2,0],[2,122,39,4,\"יַחְלְמוּ. יֶחֱזְקוּ:\",1,0],[2,122,39,4,\"וְלֹא שָׁבוּ לָמוֹ. מִשֶּׁיִּרְבּוּ קְצָת, יִגְדְּלוּ בַּבָּר, בַּזְּרָעִים וּבַדְּשָׁאִים, וְאֵינָם צְרִיכִים לְגִדּוּל אֲבִיהֶם וְאִמָּם:\",2,0],[2,122,39,5,\"חָפְשִׁי. שֶׁאֵין אָדָם יָכוֹל לְגַדֵּל פֶּרֶא, לְלַמְּדוֹ עֲבוֹדַת בְּהֵמוֹת:\",1,0],[2,122,39,5,\"עָרוֹד. חֲמוֹר הַבָּר:\",2,0],[2,122,39,5,\"מִי פִתֵּחַ. מוֹסְרוֹתָיו, שֶׁאֵין עָלָיו עֹל אָדָם:\",3,0],[2,122,39,8,\"יְתוּר הָרִים מִרְעֵהוּ. הוּא עַצְמוֹ תָּר לוֹ מְקוֹם מִרְעֶה:\",1,0],[2,122,39,9,\"רֵים. כְּמוֹ ״רְאֵם״ (במדבר כג:כב):\",1,0],[2,122,39,9,\"עָבְדֶּךָ. לְעָבְדְּךָ:\",2,0],[2,122,39,10,\"בְּתֶלֶם עֲבֹתוֹ. (אוֹ קָשַׁרְתָּ רְאֵם בַּעֲבוּר תֶּלֶם שֶׁל שׁוֹרְךָ?) עֲבֹת. חֶבֶל שֶׁקּוֹשְׁרִין (שְׁוָורִים) לְתַלְמֵי הַמַּחֲרֵשָׁה:\",1,0],[2,122,39,10,\"יְשַׂדֵּד. יְתַקֵּן הַשָּׂדֶה:\",2,0],[2,122,39,11,\"הֲתִבְטַח בּוֹ. לֶאֱסֹף תְּבוּאָתְךָ, בִּשְׁבִיל שֶׁכֹּחוֹ רַב, וְיָכוֹל לִסְבֹּל הַרְבֵּה?\",1,0],[2,122,39,11,\"וְתַעֲזֹב אֵלָיו יְגִיעֶךָ. לֶאֱסֹף אֶל הַבַּיִת:\",2,0],[2,122,39,13,\"כְּנַף רְנָנִים נֶעֱלָסָה. כֵּן שֵׁם עוֹף גָּדוֹל רְנָנִים, וּלְשׁוֹן מִשְׁנָה קָרוּי בַּר יוֹכְנִי (בכורות נז:):\",1,0],[2,122,39,13,\"אֶבְרָה. כָּל עוֹף קָרוּי אֶבְרָה, עַל שֵׁם שֶׁפּוֹרֵחַ. כְּלוֹמַר: אוֹ עוֹף שֶׁשְּׁמוֹ חֲסִידָה, וְעוֹף שֶׁשְּׁמוֹ נֹצָה. רְאֵה מָה מִנְהָגָהּ:\",2,0],[2,122,39,14,\"תַּעֲזֹב לָאָרֶץ בֵּיצֶיהָ. וְהוֹלֶכֶת וּמִתְחַמֶּמֶת לְמֵרָחוֹק עַל עָפָר:\",1,0],[2,122,39,15,\"וַתִּשְׁכַּח כִּי רֶגֶל תְּזוּרֶהָ. לְבֵיצָתָהּ תְּבַקְּעֶנָּה:\",1,0],[2,122,39,16,\"הִקְשִׁיחַ. הִקְשָׁה בָּנֶיהָ מִלִּבָּהּ, כְּאִלּוּ אֵינָם שֶׁלָּהּ:\",1,0],[2,122,39,16,\"לְרִיק יְגִיעָהּ. וְאֵינָהּ יְרֵאָה שֶׁתְּאַבְּדֵם:\",2,0],[2,122,39,18,\"כָּעֵת בַּמָּרוֹם תַּמְרִיא. כָּל לְשׁוֹן הַמְרָאָה כְּאָדָם שֶׁזּוֹנֶה לִבּוֹ לָצֵאת מִמִּדָּתוֹ וּמִגִּדּוּלוֹ וּמֵאַרְצוֹ, לְשׁוֹטֵט לוֹ בָּאֲרָצוֹת, וּלְנַסּוֹת לוֹ מִדּוֹת אֲחֵרוֹת. וְכֵן ״בֵּן סוֹרֵר וּמוֹרֶה״ (דברים כא:יח). וּבִלְשׁוֹן גְּמָרָא: אִימְרָאִי כַּלְּתֵיהּ דְּרַב זְבִיד, אִימְרָאִי וְנָפְקָא (כתובות סג: ושם איתא אימרדא ועיין ברש״י בחולין נח ומציעא עו ד״ה ואימרו):\",1,0],[2,122,39,19,\"רַעְמָה. לְשׁוֹן רַעַם וּבְעָתָה, כְּמוֹ ״רָעֲמוּ פָנִים״ (יחזקאל כז:לה):\",1,0],[2,122,39,20,\"כָּאַרְבֶּה. מְדַלֵּג וּמְקַפֵּץ כָּאַרְבֶּה וּמַרְעִישׁ סְבִיבָיו:\",1,0],[2,122,39,20,\"נַחְרוֹ. כְּשֶׁהוּא נוֹפֵחַ בִּנְחִירָיו בְּקוֹל אֵימָה הוּא:\",2,0],[2,122,39,21,\"יַחְפְּרוּ בָעֵמֶק. כְּמוֹ ״וְיַחְפְּרוּ לָנוּ אֶת הָאָרֶץ״ (דברים א:כב), שֶׁדֶּרֶךְ הַפָּרָשִׁים אוֹרְבִים בָּעֲמָקִים וּבַנְּחָלִים:\",1,0],[2,122,39,21,\"וְיָשִׂישׂ בְּכֹחַ. וְהַסּוּס שָׂמֵחַ וְיוֹצֵא לִקְרַאת נָשֶׁק:\",2,0],[2,122,39,22,\"וְלֹא יֵחָת. וְלֹא יִירָא:\",1,0],[2,122,39,23,\"תִּרְנֶה אַשְׁפָּה. מְלֵאָה חִצִּים, וּמְקַשְׁקְשׁוֹת זוֹ בְּזוֹ וְנִשְׁמַע קוֹלָם:\",1,0],[2,122,39,23,\"לַהַב חֲנִית. כְּלִי שֶׁל בַּרְזֶל (וַחֲנִית שֶׁל בַּרְזֶל) קָרוּי לַהַב, כְּמוֹ ״וַיָּבֹא גַם הַנִּצָּב אַחַר הַלַּהַב״ (שופטים ג:כב):\",2,0],[2,122,39,24,\"יְגַמֶּא אָרֶץ. עוֹשֶׂה גֻּמּוֹת בְּרַגְלָיו. עִנְיָן אַחֵר: יְגַמֶּא כְּמוֹ ״הַגְמִיאִינִי נָא״ (בראשית כד:יז):\",1,0],[2,122,39,24,\"וְלֹא יַאֲמִין. מֵרוֹב שִׂמְחָה, שֶׁהוּא מִתְאַוֶּה לַמִּלְחָמָה:\",2,0],[2,122,39,24,\"כִּי קוֹל שׁוֹפָר. שֶׁל מִלְחָמָה:\",3,0],[2,122,39,25,\"בְּדֵי שׁוֹפָר. לְשׁוֹן ״דֵּי הָשִׁיב לוֹ״ (ויקרא כה:כח) – בְּהַרְבֵּה שׁוֹפָר:\",1,0],[2,122,39,25,\"יֹאמַר הֶאָח. לָשׁוֹן שֶׁאוֹמְרִים (הָעוֹבְרִים) כְּשֶׁהֵן שְׂמֵחִין, כְּמוֹ שֶׁאוֹמְרִים ״אֲהָהּ״ (יהושע ז:ז) מֵחֲמַת צַעַר:\",2,0],[2,122,39,26,\"יַאֲבֶר נֵץ. יִגְדַּל הַנֵּץ כָּנָף. וּמַלְאָךְ הוּא דּוֹמֶה לִדְמוּת נֵץ, וּמַעֲמִיד קֹשִׁי הָרוּחַ דְּרוֹמִית בִּפְרִישׂוּת כְּנָפָיו, שֶׁלֹּא תַּחֲרִיב אֶת הָעוֹלָם:\",1,0],[2,122,39,27,\"אִם עַל פִּיךָ יַגְבִּיהַּ נָשֶׁר. הַשְּׁכִינָה, שֶׁנֶּאֱמַר: ״כְּנֶשֶׁר יָעִיר קִנּוֹ״ (דברים לב:יא) – הָיָה מְסַלֵּק פָּמַלְיָא שֶׁלּוֹ, שֶׁלֹּא יַזִּיקוּ לְאַהֲרֹן בְּבוֹאוֹ אֶל הַקֹּדֶשׁ בְּיוֹם הַכִּפּוּרִים:\",1,0],[2,122,39,28,\"סֶלַע יִשְׁכֹּן וְיִתְלוֹנָן. בָּטוּחַ הָיָה אַהֲרֹן בְּמַחְתַּת הַקְּטֹרֶת, כְּשֶׁנְּתָנָהּ עַל אֶבֶן שְׁתִיָּה (יומא נג:):\",1,0],[2,122,39,29,\"מִשָּׁם חָפַר אֹכֶל. מִתְפַּלֵּל עַל צָרְכֵי כָּל הַשָּׁנָה. וְאַחַר כָּל הַכָּבוֹד הַזֶּה רָאָה בְּמִיתַת שְׁנֵי אֶפְרוֹחָיו נָדָב וַאֲבִיהוּא, שֶׁמֵּתוּ לְהִתְקַדֵּשׁ שְׁמִי בָּהֶם (ויקרא י:א-ב), שֶׁנָּפְלָה אֵימָתִי עַל הַשְּׁאָר:\",1,0],[2,122,39,30,\"יְעַלְעוּ. וְאֵינָן אֶלָּא כְּפִי מִדַּת בָּלְעוֹ דָּם וּמַיִם, וְנִרְאֶה כְּבוֹלֵעַ הַרְבֵּה, כְּאוֹמֵר ״עַל עַל״. וְכֵן בִּלְשׁוֹן חֲכָמִים בְּהַשְׁקָאַת סוֹטָה (סוטה כ.): מְעַרְעֲרִין אוֹתָהּ וּמַשְׁקִין אוֹתָהּ עַל כָּרְחָהּ. וְכֵן ״זַעֲקַת שֶׁבֶר יְעֹעֵרוּ״ (ישעיהו טו:ה) – לְשׁוֹן קְרִיאַת גָּרוֹן דּוֹמֶה לְכָךְ. וּלְפִי הַדֶּרֶךְ דִּבֵּר הַנָּבִיא:\",1,0],[2,122,39,30,\"וּבַאֲשֶׁר חֲלָלִים שָׁם הוּא. לֶאֱכוֹל. וְרַבּוֹתֵינוּ דִּמּוּ כָּל עִנְיָן זֶה בְּאַהֲרֹן, בִּפְסִיקְתָּא דְּ׳אַחֲרֵי מוֹת׳ (פסיקתא רבתי):\",2,0],[2,122,40,2,\"(מענה ה׳):הֲרֹב עִם שַׁדַּי יִסּוֹר. הַאִם שַׁדַּי – אָדָם יִשְׂתָּרֵר?\",1,0],[2,122,40,2,\"מוֹכִיחַ אֱלוֹהַּ יַעֲנֶנָּה. הַבָּא לְהִתְוַכֵּחַ, יַעֲנֶה דְּבָרָיו?\",2,0],[2,122,40,5,\"(מענה איוב): אַחַת דִּבַּרְתִּי. כְּלוֹמַר: מְעַט אָמַרְתִּי וְלֹא אוֹסִיף עוֹד. וְיֵשׁ פּוֹתְרִים: אַחַת דִּבַּרְתִּי, אֲשֶׁר אָמַרְתִּי (איוב ט:כב) ״תָּם וְרָשָׁע הוּא מְכַלֶּה״, לֹא אֶעֱנֶה עוֹד:\",1,0],[2,122,40,5,\"וּשְׁתַּיִם. שֶׁאָמַרְתִּי: ״אַל תַּעַשׂ עִמָּדִי״ (איוב יג:כ), לֹא אוֹסִיף:\",2,0],[2,122,40,8,\"(מענה ה׳ מן הסערה): הַאַף תָּפֵר מִשְׁפָּטִי. הַאַף תּוֹכִיחַ שֶׁדְּבָרֶיךָ לְהָפֵר מִשְׁפָּטִי, וּלְהַרְאוֹת שֶׁהוּא מְעֻקָּל?\",1,0],[2,122,40,10,\"עֲדֵה. לְשׁוֹן עֲדִי וְתַכְשִׁיט:\",1,0],[2,122,40,12,\"וְהָדוֹךְ. לְשׁוֹן ״דָּכוּ בַמְּדוֹכָה״ (במדבר יא:ח):\",1,0],[2,122,40,15,\"בְּהֵמוֹת. מוּכָן לֶעָתִיד:\",1,0],[2,122,40,16,\"כֹּחוֹ בְמָתְנָיו. בֵּיצָיו מְעוּכִים וְנִסְתָּרִים, וְלֹא נִתְּקוּ לְגַמְרֵי:\",1,0],[2,122,40,16,\"בִּשְׁרִירֵי. כְּמוֹ ״שָׁרְרֵךְ״ (שיר השירים ז:ג):\",2,0],[2,122,40,17,\"יַחְפֹּץ. כְּמוֹ יַחְפֹּז (להלך כג) – מִתְקַשֶּׁה. וְכֵן בִּלְשׁוֹן חֲכָמִים ׳דַּחֲפִיזָא כִּי אוּפְתָּא׳ (חולין מז:) – קָשֶׁה כָּעֵץ:\",1,0],[2,122,40,17,\"פַּחֲדָיו. בֵּיצָיו:\",2,0],[2,122,40,17,\"יְשֹׂרָגוּ. גְּדִילִים כְּמוֹ ״וַיִּשְׂתָּרְגוּ״ (איכה א:יד), אוֹ שְׂרִיגֵי מִטָּה בִּלְשׁוֹן מִשְׁנָה (כלים כד:ח), וְהוּא לְשׁוֹן גָּדִיל:\",3,0],[2,122,40,18,\"אֲפִיקֵי. חוֹזֶק:\",1,0],[2,122,40,18,\"גְּרָמָיו. עֲצָמָיו:\",2,0],[2,122,40,18,\"כְּמַטִּיל. כְּמַשָּׂאוֹי שֶׁל בַּרְזֶל:\",3,0],[2,122,40,19,\"רֵאשִׁית דַּרְכֵי אֵל. מִבְּרֵאשִׁית נִבְרָא רֹאשׁ לַבְּהֵמוֹת:\",1,0],[2,122,40,19,\"הָעֹשׂוֹ. הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַצְמוֹ יִשְׁחֲטֶנּוּ:\",2,0],[2,122,40,20,\"כִּי בוּל הָרִים יִשְׂאוּ לוֹ. וּבְסֵפֶר תְּהִלִּים כָּתוּב ״בְּהֵמוֹת בְּהַרְרֵי אָלֶף״ (תהלים נ:י), אֶלֶף הָרִים נָשְׂאוּ לוֹ יְבוּל וּבְכָל יוֹם רוֹעֶה אֶת כֻּלָּם. (עד כאן יסד רש״י מכאן ואילך אינו לשון רש״י):\",1,0],[2,122,40,21,\"צֶאֱלִים. צֵל אִילָנוֹת:\",1,0],[2,122,40,22,\"יְסֻכֻּהוּ צֶאֱלִים צִלְלוֹ. אוֹתוֹ צֵל שֶׁל סֵתֶר קָנֶה וּבִצָּה מְסֻבָּךְ וּמְסֻכָּךְ בְּאִילָנוֹת הַרְבֵּה:\",1,0],[2,122,40,23,\"הֵן יַעֲשֹׁק נָהָר וְלֹא יַחְפּוֹז. פְּרָת, שֶׁמֵּימָיו פָּרִים וְרָבִים, וְהוּא נָהָר גָּדוֹל – עוֹשְׁקוֹ וְגוֹזְלוֹ מִן הַבְּרִיּוֹת בִּשְׁתוֹתוֹ:\",1,0],[2,122,40,23,\"וְלֹא יַחְפּוֹז. לֹא מִתְקַשֶּׁה בִּטְנוֹ עַל שְׁתִיָּתוֹ, כְּמוֹ יַחְפֹּץ זְנָבוֹ:\",2,0],[2,122,40,23,\"יִבְטַח כִּי יָגִיחַ יַרְדֵּן. בָּטוּחַ הוּא לִמְשֹׁךְ כָּל הַיַּרְדֵּן לְפִיהוּ, אִלּוּ הָיָה שׁוֹתֶה שָׁם. כְּמוֹ ״גֹּחִי מִבָּטֶן״ (תהלים כב:י):\",3,0],[2,122,40,24,\"בְּעֵינָיו יִקָּחֶנּוּ. הַמָּקוֹם יִקָּחֶנּוּ בְּהַבִּיטוֹ בּוֹ, וְנִרְעָד מֵאֵימָתוֹ:\",1,0],[2,122,40,24,\"בְּמוֹקְשִׁים. כְּלֵי אוּמָּנוּת שֶׁל צַיָּדִים, שֶׁשּׁוֹלִים בָּהֶם דָּגִים:\",2,0],[2,122,40,25,\"תִּמְשֹׁךְ לִוְיָתָן וְגוֹ׳. כַּאֲשֶׁר תִּמְשְׁכֶנּוּ בְּחַכָּה וְתָשִׂים אַגְמוֹן בְּאַפּוֹ, הֲיְדַבֵּר אֵלֶיךָ תַּחֲנוּנִים? כְּלוֹמַר: לֹא תוּכַל (לְהִתְקָרֵב אֵלָיו) בִּכְלִי מְצוּדָה:\",1,0],[2,122,40,25,\"תַּשְׁקִיעַ לְשׁוֹנוֹ. תַּשְׁקִיעַ חֶבֶל בִּלְשׁוֹנוֹ, לְהוֹצִיאוֹ מִמְּקוֹמוֹ:\",2,0],[2,122,40,26,\"אַגְמוֹן. הוּא כָּפוּף, כְּמוֹ ״כִּפָּה וְאַגְמוֹן״ (ישעיה ט:יג); וְעָשׂוּי שֶׁל בַּרְזֶל, לָצוּד בּוֹ דָּגִים:\",1,0],[2,122,40,26,\"הֲתָשִׂים. אִם תָּשִׂים אַגְמוֹן בְּאַפּוֹ לְהוֹצִיאוֹ מִן הַיָּם?\",2,0],[2,122,40,26,\"וּבְחוֹחַ. כְּלִי שֶׁל צַיָּדֵי דָּגִים:\",3,0],[2,122,40,26,\"תִּקּוֹב. כְּמוֹ תִּנְקֹב:\",4,0],[2,122,40,27,\"הֲיַרְבֶּה אֵלֶיךָ תַּחֲנוּנִים. אִם יַרְבֶּה לְךָ תַּחֲנוּנִים וִיבַקֵּשׁ עַל נַפְשׁוֹ, שֶׁתַּנִּיחֵהוּ?\",1,0],[2,122,40,27,\"אִם יְדַבֵּר. כֶּפֶל מִלָּה:\",2,0],[2,122,40,27,\"רַכּוֹת. דְּבָרִים שֶׁל תַּחֲנוּנִים:\",3,0],[2,122,40,28,\"הֲיִכְרוֹת בְּרִית עִמָּךְ. אִם יִכְרוֹת בְּרִית לְעָבְדְךָ, שֶׁתִּקָּחֶנּוּ לִהְיוֹת לְךָ עֶבֶד עוֹלָם?\",1,0],[2,122,40,29,\"הַתְשַׂחֶק. אִם תְּשַׂחֵק וּתְטַיֵּל בּוֹ, כְּאִלּוּ הוּא צִפּוֹר קָטָן?\",1,0],[2,122,40,29,\"וְאִם תִּקְשְׁרֶנּוּ לְצַוָּארֵי (ס״א לְצֹרֶךְ) נְעָרֶיךָ הַקְּטַנִּים, שֶׁיְּטַיְּלוּ בּוֹ; כְּצִפֳּרִים קְטַנִּים שֶׁנּוֹתְנִין לְתִינוֹקוֹת, לְטַיֵּל וּלְפַיְּסוֹ:\",2,0],[2,122,40,30,\"יִכְרוּ עָלָיו חַבָּרִים. אִם יִכְרוּ וְיַחְכְּמוּ עָלָיו חֲבֵרִים וּמְכַשְּׁפִים, לָצוּד אוֹתוֹ לְהוֹצִיאוֹ מִן הַיָּם עַל יְדֵי מְכַשְּׁפוֹת, שֶׁיֶּחֱצוּהוּ וִיחַלְּקוּהוּ בֵּין תַּגָּרִים; כְּעִנְיָן שֶׁעוֹשִׂים צַיָּדֵי הַיָּם, שֶׁצָּדִין דָּגִים גְּדוֹלִים בְּחָכְמָתָם, וּבָאִים הַתַּגָּרִים וְקוֹנִים מֵהֶם:\",1,0],[2,122,40,30,\"יִכְרוּ. לְשׁוֹן ״כּוֹרֶה שׁוּחָה״ (ירמיה יח:כב):\",2,0],[2,122,40,30,\"חַבָּרִים. לְשׁוֹן ״וְחֹבֵר חָבֶר״ (דברים יח:יא):\",3,0],[2,122,40,30,\"כְּנַעֲנִים. תַּגָּרִים:\",4,0],[2,122,40,31,\"הֲתְמַלֵּא. אִם תְּמַלֵּא תַּאֲוָתְךָ, וְתַעֲשֶׂה סֻכּוֹת מֵעוֹרוֹ:\",1,0],[2,122,40,31,\"וּבְצִלְצַל דָּגִים רֹאשׁוֹ. וְאִם תַּעֲשֶׂה מֵרֹאשׁוֹ צִלְצַל דָּגִים? כֶּפֶל לָשׁוֹן:\",2,0],[2,122,40,31,\"צִלְצַל. סֻכַּת דָּגִים. וְלַסֻּכָּה עֲשׂוּיָה מֵרֹאשׁוֹ קוֹרֵא אוֹתָהּ צִלְצַל דָּגִים, לְפִי שֶׁעֲשׂוּיָה מִמֶּנּוּ:\",3,0],[2,122,40,31,\"צִלְצַל. אַמְבּוֹרִיץ בְּלַעַ״ז, לְשׁוֹן צֵל הוּא, וְהוּא מִתֵּיבוֹת כְּפוּלוֹת, כְּמוֹ ״יְרַקְרַק אֲדַמְדַּם״ (ויקרא יג:מט), ״פְּתַלְתֹּל״ (דברים לב:ה), ״קַעֲקַע״ (ויקרא יט:כח):\",4,0],[2,122,40,32,\"שִׂים עָלָיו כַּפֶּךָ. הִתְגַּבֵּר לַעֲרֹךְ לְפָנָיו, שֶׁתָּשִׂים עָלָיו כַּפֶּיךָ לְהַכּוֹתוֹ:\",1,0],[2,122,40,32,\"זְכֹר מִלְחָמָה אַל תּוֹסַף. וְאַל תּוֹסִיף זְכֹר גְּבוּרָתְךָ, לְהִלָּחֵם בּוֹ בַּמִּלְחָמָה:\",2,0],[2,122,40,32,\"אַל תּוֹסַף. מִן יָסַף, כְּמוֹ ״וְלֹא יָסַף עוֹד לְדַעְתָּהּ״ (בראשית לח:כו); וּבְלַעַ״ז רֶקְרֵייטְרַ״שׁ. אַל תּוֹסַף. סָמֶ״ךְ נִפְתַּחַת, מִפְּנֵי סוֹף פָּסוּק; כְּמוֹ ״אַל תּוֹתַר״ (בראשית מט:ד); ״וַתֹּתַר״ (רות ב:יד); וְכֵן הַרְבֵּה כָּמוֹהוּ:\",3,0],[2,122,41,1,\"הֵן תּוֹחַלְתּוֹ נִכְזָבָה. הֵן אִם תּוֹחַלְתּוֹ נִכְזָבָה, שֶׁלֹּא יְהֵא בּוֹ כֹּחַ לְהִלָּחֵם וְלָזוּז מִמְּקוֹמוֹ:\",1,0],[2,122,41,1,\"הֲגַם אֶל מַרְאָיו יֻטָּל. אִם גַּם אֶל מַרְאִית פָּנָיו יֻטַּל וְיֻשְׁלַךְ אָדָם, לַעֲמֹד לְפָנָיו לְהִסְתַּכֵּל בּוֹ, מִפְּנֵי אֵימָתוֹ:\",2,0],[2,122,41,2,\"לֹא אַכְזָר כִּי יְעוּרֶנּוּ. אֵין אַכְזָר גִּבּוֹר וְעָרִיץ, אֲשֶׁר יְעִירֶנּוּ מִשְּׁנָתוֹ, וִיעוֹרְרֶנּוּ מִמְּקוֹמוֹ לַהֲקִימוֹ:\",1,0],[2,122,41,2,\"וּמִי הוּא וְגוֹ׳. אֲשֶׁר יִתְיַצֵּב וְיַעֲמֹד לְפָנַי, אֲשֶׁר אֲנִי עוֹשֶׂה אֶת כָּל אֵלֶּה:\",2,0],[2,122,41,3,\"מִי הִקְדִּימַנִי. וּמִי הוּא אֲשֶׁר הִקְדִּים פָּנַי בְּהַקְבָּלָתוֹ, לְעָבְדֵנִי וְלִשְׁמֹר מִצְוֹתַי, וַאֲשַׁלֵּם לוֹ שְׂכָרוֹ?\",1,0],[2,122,41,3,\"תַּחַת כָּל הַשָּׁמַיִם לִי הוּא. כָּל אֲשֶׁר בַּשָּׁמַיִם לִי הוּא, וּבְיָדִי לִפְרֹעַ לוֹ שְׂכָרוֹ וּפְעֻלָּתוֹ וּמַעֲבָדוֹ:\",2,0],[2,122,41,4,\"לֹא אַחֲרִישׁ בַּדָּיו. לֹא אַחֲרִישׁ עַל בָּנָיו שֶׁל צַדִּיק, שֶׁהָלַךְ לְפָנַי בְּתָמִים, וּלְבָנָיו יִשְׁתַּלְּמוּ שְׂכַר טוֹב אֲבִיהֶם, וְיִמְצְאוּ טוֹבָה בִּזְכוּתוֹ:\",1,0],[2,122,41,4,\"וּדְבַר גְּבוּרוֹת וְחִין עֶרְכּוֹ. וּדְבַר גְּבוּרוֹתָיו אֲשֶׁר נִתְגַּבֵּר לַעֲשׂוֹת הַטּוֹב וְהַיָּשָׁר, וּתְחִנַּת סִדּוּרוֹ שֶׁל צַדִּיק אֲשַׁלֵּם שְׂכָרוֹ גַּם לְבָנָיו אַחֲרָיו:\",2,0],[2,122,41,4,\"בַּדָּיו. עֲנָפָיו, וְהֵם בָּנָיו, כְּמוֹ ״וַתַּעַשׂ בַּדִּים וַתִּשְׁלַח פֹּארוֹת״ (יחזקאל יז:ו):\",3,0],[2,122,41,5,\"מִי גִלָּה פְּנֵי לְבוּשׁוֹ. חוֹזֵר עַל הָרִאשׁוֹנוֹת, לְדַבֵּר עַל לִוְיָתָן. מִי יוּכַל לְגַלּוֹת קַשְׂקַשּׂוֹת שֶׁהֵן בְּכֶפֶל רִסְנוֹ, בְּכֶפֶל שְׂפָתָיו כְּשֶׁהֵן פְּתוּחוֹת מִי הוּא אֲשֶׁר יִכָּנֵס שָׁם. בְּכֶפֶל הֵן הַשְּׂפָתַיִם, שֶׁהֵן כְּפוּלוֹת: אַחַת לְמַעְלָה וְאַחַת לְמַטָּה, שֶׁאֵין בְּרִיָּה רַשָּׁאָה לִיכָּנֵס שָׁם מִפְּנֵי אֵימָתוֹ:\",1,0],[2,122,41,6,\"דַּלְתֵי פָנָיו. הֵן הַשְּׂפָתַיִם; כְּשֶׁהוּא סוֹגֵר פִּיו, מִי יוּכַל לְפָתְחָן?\",1,0],[2,122,41,6,\"סְבִיבוֹת שִׁנָּיו אֵימָה. אֲשֶׁר מִפְּנֵי פַּחְדּוֹ וְאֵימָתוֹ אֵין בְּרִיָּה יְכוֹלָה לְהִתְקָרֵב לְשִׁנָּיו:\",2,0],[2,122,41,7,\"גַּאֲוָה אֲפִיקֵי מָגִנִּים. גַּאֲוָה גְּדוֹלָה יֵשׁ לוֹ בְּחֹזֶק מָגִנָּיו, הֵן קַשְׂקַשִּׂים שֶׁעָלָיו, הַמְּגִנִּין עָלָיו כְּמָגֵן:\",1,0],[2,122,41,7,\"סָגוּר. הוּא חוֹתַם שִׁרְיוֹנוֹ, שֶׁהוּא צַר וְסָגוּר וְעָצוּם; שֶׁכָּל קַשְׂקֶשֶׂת וְקַשְׂקֶשֶׂת דְּבוּקָה בּוֹ וַאֲדוּקָה לַחֲבֶרְתָּהּ, שֶׁאֵין בְּרִיָּה יְכוֹלָה לְהַכּוֹתוֹ בֵּין הַדְּבָקִים (מלכים א כב:לד). וְזֶהוּ שֶׁנֶּאֱמַר: אֶחָד בְּאֶחָד יִגַּשׁוּ. שֶׁכֻּלָּן מֻגָּשׁוֹת וּתְכוּפוֹת זוֹ לָזוֹ:\",2,0],[2,122,41,9,\"יִתְלַכְּדוּ וְלֹא יִתְפָּרָדוּ. עֲדַיִן כּוֹפֵל לְשׁוֹנוֹ, שֶׁנִּלְכָּדוֹת וְנֶאֱחָדוֹת כָּל אַחַת וְאַחַת בַּחֲבֶרְתָּהּ, שֶׁלֹּא תִּהְיֶינָה מִתְפָּרְדוֹת זוֹ מִזּוֹ:\",1,0],[2,122,41,10,\"עֲטִישֹׁתָיו תָּהֶל אוֹר. בְּכָל עֲטִישָׁה וַעֲטִישָׁה שֶׁהוּא מִתְעַטֵּשׁ, יָהֶל וְתִזְרַח אוֹר:\",1,0],[2,122,41,10,\"תָּהֶל. כְּמוֹ ״בְּהִלּוֹ נֵרוֹ״ (איוב כט:ג):\",2,0],[2,122,41,10,\"וְעֵינָיו כְּעַפְעַפֵּי שָׁחַר. עֵינָיו זוֹרְחוֹת וּמְאִירוֹת כְּדִמְדּוּמֵי חַמָּה, כְּמוֹ לְעֵת בֹּקֶר שֶׁהַשֶּׁמֶשׁ מִתְאַדֶּמֶת:\",3,0],[2,122,41,11,\"מִפִּיו. מִלַּהֶבֶת הַיּוֹצֵאת מִמֶּנּוּ:\",1,0],[2,122,41,11,\"מִפִּיו לַפִּידִים יַהֲלֹכוּ. לַפִּידִים יוֹצְאוֹת מִפִּיו:\",2,0],[2,122,41,11,\"כִּידוֹדֵי אֵשׁ. כְּמוֹ לַפִּידִים:\",3,0],[2,122,41,11,\"יִתְמַלָּטוּ. פִּתְרוֹנוֹ לְפִי עִנְיָנוֹ שוינ״ט אישקמוצי״ר בְּלַעַ״ז:\",4,0],[2,122,41,12,\"מִנְּחִירָיו יֵצֵא עָשָׁן. כְּסִיר נָפוּחַ עַל הָאֵשׁ, שֶׁמַּעֲלֶה עָשָׁן:\",1,0],[2,122,41,12,\"וְאַגְמוֹן. פִּתְרוֹנוֹ לְפִי עִנְיָנוֹ, לְשׁוֹן כְּלִי חֶרֶשׂ הוּא, כְּמוֹ דּוּד נָפוּחַ; כְּעִנְיָן שֶׁנֶּאֱמַר ״סִיר נָפוּחַ אֲנִי רֹאֶה״ (ירמיהו א:יג):\",2,0],[2,122,41,13,\"נַפְשׁוֹ גֶּחָלִים תְּלַהֵט. גֶּחָלִים בּוֹעֲרוֹת וְלוֹהֲטוֹת, וְלַהֲבוֹת דּוֹלְקוֹת יוֹצְאוֹת מִפִּיו:\",1,0],[2,122,41,14,\"בְּצַוָּארוֹ יָלִין עֹז. גְּבוּרָה:\",1,0],[2,122,41,14,\"וּלְפָנָיו תָּדוּץ דְּאָבָה. שֶׁאֵין דַּאֲבוֹן וְעִצָּבוֹן לְפָנָיו, שֶׁאֵינוֹ מִתְיָרֵא מִשּׁוּם בְּרִיָּה. תָּדוּץ לְשׁוֹן דִּיצָה וְשִׂמְחָה:\",2,0],[2,122,41,15,\"מַפְּלֵי בְשָׂרוֹ דָבֵקוּ. נִדְבָּקוֹת וּתְכוּפוֹת זוֹ בָּזוֹ, שֶׁהַדָּגִים הֵן נַעֲשִׂין חֲתִיכוֹת חֲתִיכוֹת בִּבְשָׂרוֹ, וּמְדֻבָּקוֹת זוֹ בָּזוֹ. וּבְדָג גָּדוֹל כְּשֶׁהוּא מְבֻשָּׁל, נִרְאוֹת חֲתִיכוֹת כְּשֶׁהֵן שׁוֹכְבוֹת זוֹ עַל זוֹ וְזוֹ אֵצֶל זוֹ. וְכֵן הוֹלֵךְ סִדּוּר הַמִּלָּה: תְּחִלָּה דִּבֵּר בְּקַשְׂקַשּׂוֹתָיו שֶׁל לִוְיָתָן וְאַחַר כֵּן בַּחֲתִיכוֹת בְּשָׂרוֹ וְחֹזֶק לִבּוֹ:\",1,0],[2,122,41,15,\"מַפְּלֵי. לְשׁוֹן כְּפִילוּת חֲתִיכוֹת. וְיֵשׁ לוֹמַר כְּמוֹ פְּלָאֵי פְּלוּיֵי שֶׁבִּלְשׁוֹן גְּמָרָא (נדה כא:) לְשׁוֹן בִּקּוּעַ בִּקּוּעֵי חֲתִיכוֹתָיו:\",2,0],[2,122,41,15,\"דָבֵקוּ. בֵּי״ת קְמוּצָה בְּקָמַץ קָטָן, כְּמוֹ ״וּלְשׁוֹנָם לְחִכָּם דָּבֵקָה״ (איוב כט:י), וְכֵן הַרְבֵּה בְּאֶתְנַחְתָּא וְסוֹף פָּסוּק:\",3,0],[2,122,41,15,\"יָצוּק עָלָיו. כָּל מַפָּל וּמַפָּל יָצוּק זֶה עַל זֶה אֲשֶׁר לֹא יִמּוֹט וְלֹא יִתְפָּרֵד זֶה מֵעַל זֶה. יָצוּק לְשׁוֹן ״מוּצָק״ (איוב לז:יח), וְהוּא לְשׁוֹן עָשׂוּי, כְּמוֹ יָרוּד מִן יָרַד, יָצוּק מִן יָצַק, ״יָדוּעַ״ (ישעיה נג:ג) מִן יָדַע:\",4,0],[2,122,41,16,\"לִבּוֹ יָצוּק כְּמוֹ אָבֶן. לִבּוֹ בְּקִרְבּוֹ חָזָק וּמְיֻסָּד כְּאֶבֶן הַקְּבוּעָה וּנְתוּנָה בִּיסוֹד הַבִּנְיָן בְּחֹזֶק:\",1,0],[2,122,41,16,\"יָצוּק כְּפֶלַח תַּחְתִּית. כּוֹפֵל מִלָּתוֹ, שֶׁמְּיֻסָּד לִבּוֹ וְקָבוּעַ כְּפֶלַח שֶׁל רֵחַיִם, שֶׁנָּתוּן בְּתַחְתִּיתוֹ שֶׁל פֶּלַח רֶכֶב. שֶׁפֶּלַח רֶכֶב שֶׁלְּמַעְלָה – הוּא סוֹבֵב וּמִתְגַּלְגֵּל וְטוֹחֵן, וְשֶׁל מַטָּה – אֵינוֹ זָז מִמְּקוֹמוֹ כִּי קָבוּעַ הוּא בִּמְקוֹמוֹ, אֲשֶׁר לֹא יִמּוֹט (ישעיהו מ:כ). הוּא נִקְרָא ׳פֶּלַח׳, שֶׁנֶּאֱמַר ״וַתַּשְׁלֵךְ אִשָּׁה אַחַת פֶּלַח רֶכֶב עַל רֹאשׁ אֲבִימֶלֶךְ״ (שופטים ט:נג), וְאֶת שֶׁלְּמַטָּה קָרוּי פֶּלַח תַּחְתִּית:\",2,0],[2,122,41,17,\"מִשֵּׂתוֹ יָגוּרוּ אֵלִים. מִפַּחְדּוֹ מִתְיָרְאִים גִּבּוֹרִים וַחֲזָקִים, בֵּין דָּגִים בֵּין שְׁאָר בְּרִיּוֹת:\",1,0],[2,122,41,17,\"מִשְּׁבָרִים יִתְחַטָּאוּ. גַּלֵּי הַיָּם, שֶׁקְּרוּיִין מִשְׁבָּרִים, הֵן חֲסֵרִין לְפָנָיו; שֶׁהוּא שׁוֹבְרָן בִּפְרִיחָתוֹ, כַּאֲשֶׁר הוּא פּוֹרֵחַ וְצָף בְּגַלֵּי הַיָּם:\",2,0],[2,122,41,17,\"יִתְחַטָּאוּ. לְשׁוֹן חִסָּרוֹן, כְּמוֹ ״וְהָיִיתִי אֲנִי וּבְנִי שְׁלֹמֹה חַטָּאִים״ (מלכים א א:כא):\",3,0],[2,122,41,18,\"מַשִּׂיגֵהוּ חֶרֶב בְּלִי תָקוּם. גִּבּוֹר הַמַּשִּׂיגֵהוּ לְהִלָּחֵם בְּחֶרֶב – לֹא יִתְקַיֵּם חַרְבּוֹ, כִּי הוּא יִשְׁבְּרֶנָּה:\",1,0],[2,122,41,18,\"חֲנִית מַסָּע וְשִׁרְיָה. וְכֵן כָּל כְּלֵי מִלְחָמָה הַלָּלוּ שֶׁבְּיַד הַמַּשִּׂיג, לֹא יִתְקַיְּמוּ וְלֹא יַעַמְדוּ לְפָנָיו שֶׁל לִוְיָתָן. מַסָּע. יֵשׁ לוֹמַר שֶׁהוּא אֶחָד מִכְּלֵי מִלְחָמָה, כְּמוֹ חֶרֶב וַחֲנִית וְשִׁרְיָה. וְיֵשׁ לוֹמַר מַסָּע דּוּגְמַת ״אֶבֶן שְׁלֵמָה מַסָּע וְגוֹ׳״ (מלכים א ו:ז). וְזֶהוּ פִּתְרוֹנוֹ: חֲנִית מַסָּע שֶׁהוּא גָּדוֹל וְאֵינוֹ נוֹחַ לְטַלְטֵל כָּל כָּךְ, מִפְּנֵי שֶׁהוּא גָּדוֹל וְחָזָק מְאֹד; כְּעִנְיָן שֶׁנֶּאֱמַר בְּגָלְיַת הַפְּלִשְׁתִּי ״וְחֵץ חֲנִיתוֹ כִּמְנוֹר אֹרְגִים וְלַהֶבֶת חֲנִיתוֹ שֵׁשׁ מֵאוֹת וְגוֹ׳״ (שמואל א יז:ז):\",2,0],[2,122,41,18,\"וְשִׁרְיָה. שִׁרְיוֹן:\",3,0],[2,122,41,19,\"יַחְשֹׁב לְתֶבֶן בַּרְזֶל. כְּלֵי זַיִן שֶׁל בַּרְזֶל חֲשׁוּבִים לְפָנָיו כְּתֶבֶן, וּכְלֵי זַיִן שֶׁל נְחֹשֶׁת הֵם לְפָנָיו כִּרְקֵבוּת עֵץ.\",1,0],[2,122,41,20,\"לֹא יַבְרִיחֶנּוּ בֶן קָשֶׁת. לֹא יִבְרַח מִפְּנֵי בַּעַל קֶשֶׁת וְחִצִּים, וְאַבְנֵי בַּלִּיסְטְרָאוֹת הֲרֵי הֵן לְפָנָיו כְּקַשׁ:\",1,0],[2,122,41,21,\"תּוֹתָח. הוּא כְּלִי זַיִן, וּפִתְרוֹנוֹ לְפִי עִנְיָנוֹ:\",1,0],[2,122,41,21,\"וְיִשְׂחַק לְרַעַשׁ כִּידוֹן. לְרַעַשׁ מְהוּמַת בַּעֲלֵי מִלְחָמוֹת נוֹטְלֵי כִּידוֹן, הוּא מְשַׂחֵק וּמְטַיֵּל; שֶׁאֵינוֹ מִתְיָרֵא מִפְּנֵיהֶם:\",2,0],[2,122,41,22,\"תַּחְתָּיו חַדּוּדֵי חָרֶשׂ. בִּמְקוֹם חֲנִיָּתוֹ יֵשׁ זָהֳרוּרֵי שֶׁמֶשׁ, כִּי סְנַפִּירִים שֶׁלּוֹ, אֲשֶׁר תַּחְתָּיו – בְּבִטְנוֹ, מְאִירוֹת וּמַזְרִיחוֹת כַּשֶּׁמֶשׁ:\",1,0],[2,122,41,22,\"חַדּוּדֵי. כְּמוֹ ״חֶרֶב חַדָּה״ (יחזקאל ה:א), שֶׁהִיא שְׁנוּנָה, צַחָה וּמְלֻבָּנָה; וְעַל שֵׁם כָּךְ קוֹרֵא לְזַהֲרוּרֵי – חַדּוּדֵי:\",2,0],[2,122,41,22,\"חָרֶשׂ. שֶׁמֶשׁ, כְּמוֹ ״הָאוֹמֵר לַחֶרֶס לֹא יִזְרָח וְגוֹ׳״ (איוב ט:ז), ״בְּטֶרֶם תָּבֹא הַחַרְסָה״ (שופטים יד:יח):\",3,0],[2,122,41,22,\"יִרְפַּד חָרוּץ עֲלֵי טִיט. מִלָּה כְּפוּלָה, יִרְפַּד חָרוּץ מוּסָב עַל חִדּוּדֵי חֶרֶס, עֲלֵי טִיט מוּסָב עַל תַּחְתִּיתוֹ, בִּמְקוֹם שֶׁהוּא שָׂם עַל הַחוֹל, זֶה טִיט רִפּוּדוֹ מַזְרִיחַ כְּזָהָב חָרוּץ, כְּעִנְיָן שֶׁנֶּאֱמַר ״רְפִידָתוֹ זָהָב״ (שיר השירים ג:י), חָרוּץ מִין זָהָב, כְּעִנְיָן שֶׁנֶּאֱמַר ״מֵחָרוּץ תְּבוּאָתָהּ״ (משלי ג:יד), ״טוֹב פִּרְיָהּ מֵחָרוּץ וּמִפָּז״ (משלי ח:יט). יִרְפַּד לְשׁוֹן מַצָּע וּמִשְׁכָּב כְּמוֹ ״רְפִידָתוֹ זָהָב״ (שיר ג:י):\",4,0],[2,122,41,23,\"יַרְתִּיחַ כַּסִּיר מְצוּלָה. כְּסִיר קָטָן נָפוּחַ, שֶׁמַּעֲלֶה מְהֵרָה רְתִיחוֹת תְּכוּפוֹת וּרְצוּפוֹת, כֵּן הוּא מַרְתִּיחַ אֶת הַמְּצוּלָה שֶׁהִיא גְּדוֹלָה וַעֲמֻקָּה:\",1,0],[2,122,41,23,\"יָם יָשִׂים כַּמֶּרְקָחָה. כְּמִרְקַחַת רִקּוּחַ בְּשָׂמִים, שֶׁהִיא מְעוֹרָה וּמְעֹרֶבֶת, כְּמוֹ כֵן יָשִׂים וִיעָרֵב אֶת הַיָּם כְּשֶׁהוּא זָז מִמְּקוֹמוֹ:\",2,0],[2,122,41,24,\"אַחֲרָיו יָאִיר נָתִיב. כְּשֶׁהוּא פּוֹרֵחַ וְשָׁט בַּיָּם, אַחֲרָיו מֵאִיר נָתִיב הַתְּהוֹם; שֶׁלְּפִי שָׁעָה שֶׁהוּא פּוֹרֵחַ, וְאֵין שָׁם מַיִם מֵחֲמַת מְרוּצַת פְּרִיחָתוֹ:\",1,0],[2,122,41,24,\"יַחְשֹׁב תְּהוֹם לְשֵׂיבָה. תְּהוֹם חָשׁוּב לְפָנָיו בְּחַלָּשׁוּת וְתַשּׁוּת:\",2,0],[2,122,41,24,\"לְשֵׂיבָה. לְחַלְשׁוּת שֶׁל זִקְנָה וְשֵׂיבָה:\",3,0],[2,122,41,25,\"אֵין עַל עָפָר מָשְׁלוֹ. מֵ״ם חֲטַף קָמַץ, וּפִתְרוֹנוֹ: מֶמְשַׁלְתּוֹ – שֶׁאֵין בְּרִיָּה מוֹשֶׁלֶת עָלָיו. וְהוּא שֵׁם דָּבָר: מוֹשֵׁל וְשִׁלְטוֹן, וְעַל כֵּן הַמֵּ״ם מְנֻקֶּדֶת בַּחֲטַף קָמַץ:\",1,0],[2,122,41,25,\"הֶעָשׂוּ. כְּמוֹ ״הֶעָשׂוּי״ (שמות ג:טז), וְלֹא יָדַעְתִּי לוֹ רֵיעַ. וּפִתְרוֹנוֹ: הֶעָשׂוּי בְּלִי פַּחַד וּמְחִתָּה, שֶׁאֵינוֹ מִתְיָרֵא מִן הַבְּרִיּוֹת; כְּמוֹ שֶׁנֶּאֱמַר בַּסּוּס ״יִשְׂחַק לְפַחַד וְלֹא יֵחָת״ (איוב לט:כב):\",2,0],[2,122,41,26,\"אֵת כָּל גָּבֹהַּ יִרְאֶה. כָּל הַגְּבוֹהִים שֶׁבָּעוֹלָם הוּא רוֹאֶה תַּחְתָּיו, וְכֵן הוּא מִנְהַג הָעוֹלָם, אֲשֶׁר אוֹתוֹ הָעוֹמֵד לְמַעְלָה רוֹאֶה אֶת הַתַּחְתּוֹן יוֹתֵר מִמַּה שֶּׁרוֹאֶה הַתַּחְתּוֹן, וְאֵין לַתַּחְתּוֹן גְּבוּרָה וְנִצָּחוֹן נֶגֶד הָעֶלְיוֹן. וְלִוְיָתָן זֶה רוֹאֶה אֶת כָּל הַגִּבּוֹרִים, לוֹמַר שֶׁאֵין לָהֶם גְּבוּרָה כְּנֶגְדּוֹ:\",1,0],[2,122,41,26,\"הוּא מֶלֶךְ עַל כָּל בְּנֵי שָׁחַץ. מִלָּה כְּפוּלָה: עַל כָּל גַּאֲוָה יִרְאֶה, וְהוּא מֶלֶךְ עַל כָּל בְּנֵי שָׁחַץ – בְּנֵי גַּסּוּת הָרוּחַ שֶׁבָּרָאתִי בְּעוֹלָמִי, שֶׁאֵין לָהֶם כְּנֶגְדּוֹ מֶמְשָׁלָה וּשְׂרָרָה. וְהָאֵיךְ נְשָׂאֲךָ לִבְּךָ לָשֵׂאת רֹאשׁ לְפָנַי, לְהִתְוַכֵּחַ נֶגְדִּי – כִּי הִנְנִי עוֹשֶׂה אֶת כָּל הַנִּפְלָאוֹת הָאֵלֶּה?!\",2,0],[2,122,42,2,\"(מענה איוב): יָדַעְתִּי כִּי כֹל תּוּכָל. כִּי הַכֹּל תּוּכַל לַעֲשׂוֹת, כַּאֲשֶׁר יָשָׁר בְּעֵינֶיךָ:\",1,0],[2,122,42,2,\"וְלֹא יִבָּצֵר מִמְּךָ מְזִמָּה. כּוֹפֵל מִלָּתוֹ: שֶׁאֵין מְזִמָּה וּמַחֲשָׁבָה נִבְצֶרֶת וְנִסְתֶּרֶת מִמְּךָ, אֲשֶׁר כָּל מַחֲשְׁבוֹתֶיךָ תּוּכַל לִגְמֹר וּלְמַלְּאוֹת; כִּי בְיָדְךָ כֹּחַ וּגְבוּרָה וּבְיָדְךָ לַעֲשׂוֹת כָּל הַטּוֹב בְּעֵינֶיךָ (דברי הימים א כט:יב). וּמִקְרָא זֶה דּוּגְמַת ״וְעַתָּה לֹא יִבָּצֵר מֵהֶם כֹּל אֲשֶׁר יָזְמוּ לַעֲשׂוֹת״ (בראשית יא:ו):\",2,0],[2,122,42,3,\"מִי זֶה מַעְלִים. אֲשֶׁר הֶעֱלִים וְכִסָּה עֲצָתוֹ וְנִפְלְאוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בִּבְלִי דַעַת? יָדַעְתִּי כִּי הַכֹּל בְּיָדְךָ לַעֲשׂוֹת, וְעַל כֵּן הִגַּדְתִּי קְצָת מִגְּבוּרוֹתָיו כַּאֲשֶׁר הָיוּ עִם לְבָבִי, כַּאֲשֶׁר יָדַעְתִּי:\",1,0],[2,122,42,3,\"וְלֹא אָבִין. אֲבָל לֹא הֵבַנְתִּי כָּל כָּךְ, כַּאֲשֶׁר הוֹדַעְתַּנִי; כִּי כַּמָּה נִפְלָאוֹת נִסְתָּרוֹת וְנֶעֱלָמוֹת מִמֶּנִּי, אֲשֶׁר אֵינֶנִּי יוֹדֵעַ:\",2,0],[2,122,42,5,\"לְשֵׁמַע אֹזֶן שְׁמַעְתִּיךָ. כַּמָּה וְכַמָּה פְּעָמִים שָׁמַעְתִּי שִׁמְעֲךָ, וְעַתָּה עֵינִי רָאֲתָה אֶת שְׁכִינָתְךָ:\",1,0],[2,122,42,6,\"עַל כֵּן. אֲשֶׁר זָכִיתִי לַחֲזוֹת שְׁכִינָתְךָ, מוֹאֵס אֲנִי בְּחַיַּי; וְאֶהְיֶה מִתְנַחֵם, אִלּוּ הָיִיתִי שׁוֹכֵן בַּקֶּבֶר, לָשׁוּב לְעָפָר וָאֵפֶר אֲשֶׁר לֻקַּחְתִּי מִשָּׁם:\",1,0],[2,122,42,7,\"וּבִשְׁנֵי רֵעֶיךָ. בִּלְדַּד הַשּׁוּחִי וְצוֹפַר הַנַּעֲמָתִי:\",1,0],[2,122,42,7,\"כִּי לֹא דִבַּרְתֶּם. שֶׁהֲרֵי לֹא דִבַּרְתֶּם אֵלַי טַעֲנָה נְכוֹנָה כְּעַבְדִּי אִיּוֹב; שֶׁהֲרֵי הוּא לֹא פָּשַׁע בִּי, כִּי אִם עַל אֲשֶׁר אָמַר ״תָּם וְרָשָׁע הוּא מְכַלֶּה״ (איוב ט:כב), וְעַל יְדֵי הַשָּׂטָן הַמְקַטְרֵג אֶת הָעוֹלָם, שֶׁנֶּאֱמַר ״אִם שׁוֹט יָמִית פִּתְאוֹם וְגוֹ׳״ (איוב ט:כג). וְאִם הוֹסִיף לְדַבֵּר – מִפְּנֵי קֹשִׁי יִסּוּרִין אֲשֶׁר כָּבְדוּ וְחָזְקוּ עָלָיו דִּבֵּר. אֲבָל אַתֶּם פְּשַׁעְתֶּם, עַל אֲשֶׁר הִרְשַׁעְתֶּם אוֹתוֹ, לֵאמֹר ״הֲלֹא יִרְאָתְךָ כִּסְלָתֶךָ״ (איוב ד:ו), וְהֶחֱזַקְתֶּם אוֹתוֹ בְּחֶזְקַת רָשָׁע. וּלְבַסּוֹף הֱיִיתֶם מְשֻׁתָּקִים וּמְנֻצָּחִים לְפָנָיו; וְהָיָה לָכֶם לְנַחֲמוֹ, כַּאֲשֶׁר עָשָׂה אֱלִיהוּא. וְלֹא דַי לְאִיּוֹב בְּצָרָתוֹ וְיִסּוּרָיו, כִּי גַם הוֹסַפְתֶּם עַל חַטֹּאתֵיכֶם פֶּשַׁע לְהַקְנִיטוֹ:\",2,0],[2,122,42,8,\"וְהַעֲלִיתֶם עוֹלָה בַּעַדְכֶם. לְמַעַן שֶׁתִּתְרַצּוּ וְתִתְפַּיְּסוּ לְפָנַי, וּבִלְבַד אֲשֶׁר עַבְדִּי אִיּוֹב יִתְפַּלֵּל עֲלֵיכֶם אֲשֶׁר אֶסְלַח לְחַטֹּאתֵיכֶם, וְלִפְשָׁעֵיכֶם לֹא אֶזְכֹּר עוֹד:\",1,0],[2,122,42,8,\"כִּי אִם פָּנָיו אֶשָּׂא. שֶׁהֲרֵי פָנָיו אֶשָּׂא לְקַבֵּל תְּפִלָּתוֹ. הֲרֵי אִם כְּמוֹ אֲשֶׁר, וְכֵן ״עַד אִם כִּלּוּ לִשְׁתּוֹת״ (בראשית כד:יט), ״אִם כֹּפֶר יוּשַׁת עָלָיו״ (שמות כא:ל), וְכֵן הַרְבֵּה:\",2,0],[2,122,42,8,\"כִּי לֹא. שֶׁהֲרֵי לֹא:\",3,0],[2,122,42,9,\"וַיִּשָּׂא ה׳ אֶת פְּנֵי אִיּוֹב. וַיִּשָּׂא כְּמוֹ ״נָשָׂאתִי פָנֶיךָ גַּם לַדָּבָר הַזֶּה״ (בראשית יט:כא), שֶׁקִּבֵּל תְּפִלָּתוֹ וְהִסְבִּיר לוֹ פָּנִים:\",1,0],[2,122,42,10,\"שָׁב אֶת שְׁבוּת אִיּוֹב בְּהִתְפַּלְלוֹ. שָׁב נוֹפֵל לוֹמַר בְּעִנְיָן זֶה, וַהֲרֵי הוּא כְּאִלּוּ כְּתִיב וְהֵשִׁיב אֶת שְׁבוּת אִיּוֹב:\",1,0],[2,122,42,10,\"בְּהִתְפַּלְלוֹ בְּעַד רֵעֵהוּ. בִּזְכוּת שֶׁהִתְפַּלֵּל עַל כָּל רֵיעַ וְרֵיעַ שֶׁלּוֹ:\",2,0],[2,122,42,10,\"לְמִשְׁנֶה. עַל אֶחָד שְׁנַיִם (נראה דקאי גם על מה שכתב למעלה שהיה לו לומר להשיב מהר״ז), וְלֹא דִקְדֵּק הַמִּקְרָא בְּמִלָּתוֹ:\",3,0],[2,122,42,11,\"לְפָנִים. כָּל אֲשֶׁר הָיוּ אוֹהֲבָיו וּמַכִּירָיו בְּטֶרֶם הִגִּיעוּ אֵלָיו הַיִּסּוּרִים:\",1,0],[2,122,42,11,\"וַיָּנֻדוּ לוֹ. לְשׁוֹן קוֹנְפְּלֵיְינְטָ״א בְּלַעַ״ז:\",2,0],[2,122,42,11,\"קְשִׂיטָה. מָעָה:\",3,0],[2,122,42,11,\"וְאִישׁ. וְכָל אֶחָד וְאֶחָד (רוצה לומר שלא תאמר שהכונה שיש שנתנו לו קשיטה ויש שנתן לו נזם לכך כתב רש״י ואיש פירושו כל אחד ואחד מהר״ז):\",4,0],[2,122,42,12,\"מֵרֵאשִׁיתוֹ. יוֹתֵר מֵרֵאשִׁית עָשְׁרוֹ:\",1,0],[2,122,42,13,\"שִׁבְעָנָה. הֵם פַּעֲמַיִם שֶׁבַע, שְׁתֵּי שְׁבִיעִיּוֹת; כְּמוֹ ״שְׁבֻעַיִם״ (ויקרא יב:ה), שֶׁהֵם שְׁתֵּי שָׁבוּעוֹת:\",1,0],[2,122,42,14,\"וַיִּקְרָא שֵׁם הָאַחַת יְמִימָה. עַל שֵׁם יָפְיָתָן נִקְרְאוּ שְׁמוֹתֵיהֶן:\",1,0],[2,122,42,14,\"יְמִימָה. צַחָה וּמְלֻבָּנָה כַּיּוֹם:\",2,0],[2,122,42,14,\"קְצִיעָה. רֵיחָהּ נוֹדֵף עָרֵב וּמְבֻשָּׂם, כִּקְצִיעָה שֶׁל בֹּשֶׂם:\",3,0],[2,122,42,14,\"קֶרֶן הַפּוּךְ. עַל שֵׁם הַקֶּרֶן שֶׁנּוֹתְנִין בּוֹ כְּחוֹל וּבוֹרִית, שֶׁנֶּאֱמַר ״וְתִקְרְעִי בַפּוּךְ עֵינַיִךְ״ (ירמיהו ד:ל):\",4,0],[2,122,42,15,\"וְלֹא נִמְצָא נָשִׁים יָפוֹת כִּבְנוֹת אִיּוֹב וְגוֹ׳. וְלֹא נִמְצָא מַעֲשֶׂה שֶׁל נָשִׁים יָפוֹת, כְּמַעֲשֵׂה יֹפִי שֶׁל בְּנוֹת אִיּוֹב; וּמִקְרָא זֶה דּוּגְמַת ״וַיְהִי אֲנָשִׁים אֲשֶׁר הָיוּ טְמֵאִים״ (במדבר ט:ו); וְכֵן הַרְבֵּה:\",1,0],[2,122,42,15,\"וַיִּתֵּן לָהֶם אֲבִיהֶם נַחֲלָה בְּתוֹךְ אֲחֵיהֶם. מִתּוֹךְ חֲשִׁיבוּתָן וְיָפְיָן, נָתַן לָהֶם נַחֲלָה עִם הָאַחִים:\",2,0],[2,122,42,17,\"וּשְׂבַע יָמִים. מִן שָׂבֵעַ יֹאמַר שְׂבַע בִּדְבֵקוּת:\",1,0],[2,123,1,1,\"אֶל יוֹאֵל בֶּן פְּתוּאֵל. בֶּן שְׁמוּאֵל הַנָּבִיא, שֶׁפִּתָּה לָאֵל בִּתְפִלָּתוֹ, יֵשׁ אוֹמְרִים שֶׁנְּבוּאָה זוֹ נֶאֶמְרָה בְּאוֹתָן שֶׁבַע שָׁנִים שֶׁאָמַר אֱלִישָׁע (מלכים ב ח:א) ״כִּי קָרָא ה׳ לָרָעָב וְגוֹ׳״ וּבִימֵי יְהוֹרָם בֶּן אַחְאָב הָיוּ. וּבַהֲלָכוֹת גְּדוֹלוֹת נִמְצָא יוֹאֵל וְנָחוּם וַחֲבַקּוּק הָיוּ בִּימֵי מְנַשֶּׁה:\",1,0],[2,123,1,2,\"הֲהָיְתָה זֹּאת. הָאֲמוּרָה לְמַטָּה:\",1,0],[2,123,1,4,\"יֶתֶר הַגָּזָם וְגוֹ׳. גָּזָם אַרְבֶּה יֶלֶק חָסִיל מִינֵי גּוֹבַאי הֵם וְנִתְנַבֵּא עֲלֵיהֶם שֶׁיָּבֹאוּ וּבָאוּ בְּאוֹתָן הַיָּמִים וְכִלּוּ כָּל פְּרִי הָעֵץ וִירַק הַשָּׂדֶה:\",1,0],[2,123,1,5,\"עָסִיס. יַיִן הַטּוֹב:\",1,0],[2,123,1,6,\"גּוֹי עָלָה עַל אַרְצִי. הַגּוֹבַאי הַזֶּה כִּנָּהוּ כְּצָבָא גּוֹי:\",1,0],[2,123,1,6,\"וּמְתַלְּעוֹת. הֵן הַשִּׁנַּיִם הַגַּסִּין שֶׁלּוֹעֵס בָּהֶן:\",2,0],[2,123,1,7,\"לִקְצָפָה. לְמַפַּח נֶפֶשׁ:\",1,0],[2,123,1,7,\"חָשֹׂף חֲשָׂפָהּ וְהִשְׁלִיךְ. קִלּוּף קְלִפּוֹת הָעֵץ וְהִשְׁלִיכוֹ עַד הִלְבִּינוּ זְמוֹרוֹת הַגֶּפֶן:\",2,0],[2,123,1,8,\"אֱלִי. ׳קִינָה׳ מְתַרְגְּמִינָן ׳אִילְיָא׳:\",1,0],[2,123,1,9,\"הָכְרַת. כְּמוֹ ׳נִכְרַת׳, הֵ״א הַנְּקוּדָה בְּחָטַף קָמַץ עוֹמֶדֶת בִּמְקוֹם נוּ״ן כְּמוֹ ״וְחַיַּת הַשָּׂדֶה הָשְׁלְמָה לָךְ״ (איוב ה:כג):\",1,0],[2,123,1,11,\"הוֹבִישׁוּ. הִכָּלְמוּ:\",1,0],[2,123,1,11,\"אִכָּרִים. מַנְהִיגֵי הַמַּחֲרֵשָׁה:\",2,0],[2,123,1,11,\"עַל חִטָּה וְעַל שְׂעוֹרָה. מוּסָב עַל אִכָּרִים, וְעַל הַכּוֹרְמִים אָמַר:\",3,0],[2,123,1,12,\"הַגֶּפֶן הוֹבִישָׁה וְהַתְּאֵנָה אֻמְלָלָה. נִכְרְתָה פָּסַק פִּרְיָהּ:\",1,0],[2,123,1,12,\"הוֹבִישׁ. כְּמוֹ ׳יָבֵשׁ׳:\",2,0],[2,123,1,14,\"קַדְּשׁוּ צוֹם. הַזְמִינוּ צוֹם:\",1,0],[2,123,1,14,\"עֲצָרָה. אֲסִיפָה:\",2,0],[2,123,1,15,\"אֲהָהּ. לְשׁוֹן גְּנִיחַת יְלָלָה:\",1,0],[2,123,1,15,\"וּכְשׁוֹד. וּכְבִזַּת שׁוֹדְדִים:\",2,0],[2,123,1,15,\"יָבוֹא. מֵאֵת הַמָּקוֹם:\",3,0],[2,123,1,16,\"נֶגֶד עֵינֵינוּ. אָנוּ רוֹאִים:\",1,0],[2,123,1,17,\"עָבְשׁוּ. הֶעֱלוּ חֲלוּדָה וְעִפּוּשׁ בְּלַעַ״ז מוי״ישיר:\",1,0],[2,123,1,17,\"פְּרֻדּוֹת. תִּרְגֵּם יוֹנָתָן ״גַּרְבֵּי חַמְרָא״:\",2,0],[2,123,1,17,\"מֶגְרְפֹתֵיהֶם. תַּרְגּוּם יוֹנָתָן ״מְגוּפָתְהוֹן״ מְגוּפַת כִּסּוּי הֶחָבִיּוֹת:\",3,0],[2,123,1,17,\"נָשַׁמּוּ אוֹצָרוֹת. שֶׁל יַיִן וְשֶׁל שֶׁמֶן:\",4,0],[2,123,1,17,\"מַמְּגֻרוֹת. מְגוּרוֹת שֶׁל חִטִּין:\",5,0],[2,123,1,18,\"נָבֹכוּ. נִתְעַרְבְּלוּ וְנִסְגְּרוּ וְתָעוּ בַּיְּעָרִים וּבַמִּדְבָּרוֹת:\",1,0],[2,123,1,18,\"נֶאְשָׁמוּ. נִתְקַלְקְלוּ בְּאַשְׁמָתָן:\",2,0],[2,123,1,19,\"נְאוֹת מִדְבָּר. לְשׁוֹן ׳נָוֶה׳:\",1,0],[2,123,1,20,\"תַּעֲרוֹג. תִּצְעַק כַּאֲשֶׁר פָּתַר דּוּנַשׁ עָרַג לְאַיָּלִים נָהַם לִשְׁחָלִים וְגָעָה לַעֲגָלִים וְצָהַל לְסוּסִים צִפְצוּף לְעוֹפוֹת וְנָבַח לִכְלָבִים:\",1,0],[2,123,2,1,\"תִּקְעוּ שׁוֹפָר. לְהַשְׁמִיעָם שֶׁיָּשׁוּבוּ בִּתְשׁוּבָה בְּטֶרֶם תְּבוֹאתָם הָרָעָה הַזֹּאת:\",1,0],[2,123,2,1,\"יוֹם ה׳. מַה שֶׁאָמַרְנוּ לְמַעְלָה:\",2,0],[2,123,2,2,\"כְּשַׁחַר פָּרֻשׂ עַל הֶהָרִים. הָאַרְבֶּה וְהַגָּזָם נִפְרָשִׂים עַל הֶהָרִים כְּשַׁחַר הַנִּפְרָשׂ בְּכָל הָעוֹלָם:\",1,0],[2,123,2,2,\"כָּמֹהוּ לֹא נִהְיָה מִן הָעוֹלָם. לָבוֹא כָּל הַמִּינִים הַלָּלוּ זֶה אַחַר זֶה, אֲבָל מִין אַרְבֶּה לְבַדּוֹ לֹא הָיָה כְּמוֹ אוֹתוֹ שֶׁל מִצְרַיִם שֶׁנֶּאֱמַר ״וְאַחֲרָיו לֹא יִהְיֶה כֵּן״ (שמות י:יד):\",2,0],[2,123,2,3,\"לְפָנָיו אָכְלָה אֵשׁ. מַשְׁחִיתִים אֶת הַכֹּל כְּאִלּוּ אֵשׁ אוֹכֶלֶת לִפְנֵיהֶם וְלֶהָבָה מְלַהֶטֶת אַחֲרֵיהֶם:\",1,0],[2,123,2,3,\"כְּגַן עֵדֶן. הָיְתָה הָאָרֶץ לִפְנֵי בּוֹאוֹ וְאַחַר שֶׁיֵּלֵךְ הִנִּיחַ אֶת הָאָרֶץ כְּמִדְבַּר שְׁמָמָה:\",2,0],[2,123,2,4,\"כְּמַרְאֵה סוּסִים מַרְאֵהוּ. בִּמְרוּצָתוֹ:\",1,0],[2,123,2,5,\"כְּקוֹל לַהַב. הָאוֹכֶלֶת קַשׁ מַשְׁמַעַת קוֹל:\",1,0],[2,123,2,5,\"עֱרוּךְ מִלְחָמָה. לְפִי שֶׁהוּא דָבוּק נָקוּד חֲטַף סְגוֹל:\",2,0],[2,123,2,6,\"קִבְּצוּ פָּארוּר. שַׁחֲרוּת כַּקְּדֵרָה כְּמָה דְאַתְּ אָמַר ״וּבִשְּׁלוּ בַפָּרוּר״ (במדבר יא:ח). וְאָלֶף הַכְּתוּבָה יְתֵרָה הִיא וְאֵינָהּ נִקְרֵאת:\",1,0],[2,123,2,7,\"וְלֹא יְעַבְּטוּן. אֵין לוֹ דִמְיוֹן וּפִתְרוֹנוֹ לְפִי עִנְיָנוֹ לֹא יְעַקְּלוּן:\",1,0],[2,123,2,8,\"וּבְעַד הַשֶּׁלַח. כְּמוֹ בְּעַד הַחַלּוֹנִים עַל פְּנֵי כְּלֵי זַיִן יִפְּלוּ וְיַחֲנוּ:\",1,0],[2,123,2,8,\"וְלֹא יִבְצָעוּ. וְלֹא יְקַבְּלוּן מָמוֹן. וְיוֹנָתָן פָּתַר בּוֹ לְשׁוֹן ׳שְׁלִיחוּת׳ בִּשְׁבִיל שְׁלִיחוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מַפִּילִין עַצְמָן וּבֶצַע כֶּסֶף לֹא לָקָחוּ:\",2,0],[2,123,2,9,\"בָּעִיר יָשֹׁקּוּ. לְשׁוֹן הַשְׁמָעַת קוֹל כְּמוֹ ״כְּמַשַּׁק גֵּבִים״ (ישעיהו לג:ד) ״דֹּב שׁוֹקֵק״ (משלי כח) ״מִמְשַׁק חָרוּל״ (צפניה ב:ט). וְיוֹנָתָן תִּרְגֵּם לְשׁוֹן ׳נֶשֶׁק׳ ״מִזְדַּיְּנִין״:\",1,0],[2,123,2,10,\"רָעֲשׁוּ שָׁמָיִם. בִּשְׁבִיל פֻּרְעָנוּת הַבָּאָה עַל יִשְׂרָאֵל רוֹגְזִים וְרוֹעֲשִׁים:\",1,0],[2,123,2,10,\"אָסְפוּ נָגְהָם. הִכְנִיסוּ אוֹרָן:\",2,0],[2,123,2,11,\"וַה׳ נָתַן. עֲלֵיהֶם קוֹלוֹ בְּמַאֲמַר נְבִיאָיו לִפְנֵי שָׁלְחוֹ בָּהֶם אֶת חֵילוֹ זֶה:\",1,0],[2,123,2,11,\"כִּי רַב מְאֹד מַחֲנֵהוּ. אֲשֶׁר יִשְׁלַח בָּכֶם אִם לֹא תֵּטִיבוּן:\",2,0],[2,123,2,13,\"וְאַל בִּגְדֵיכֶם. כִּי אֵינִי חָשׁ לִקְרִיעַת בִּגְדֵיכֶם. דָּבָר אַחֵר קִרְעוּ לְבַבְכֶם וְאַל תִּצְטָרְכוּ לִקְרֹעַ בִּגְדֵיכֶם מֵחֲמַת אֵבֶל:\",1,0],[2,123,2,13,\"וְנִחָם עַל הָרָעָה. נֶהְפַּךְ לְמַחֲשָׁבָה אַחֶרֶת:\",2,0],[2,123,2,14,\"מִי יוֹדֵעַ. שֶׁיֵּשׁ בּוֹ עָוֹן יָשׁוּב וְנִחָם:\",1,0],[2,123,2,14,\"וְהִשְׁאִיר. הֶחָסִיל וְהַגָּזָם אַחֲרָיו בְּרָכָה עַל יְדֵי הַתְּשׁוּבָה תָּבֹא בְּרָכָה בַּפֵּרוֹת:\",2,0],[2,123,2,16,\"קִבְצוּ זְקֵנִים. מִמִּשְׁקְלוֹת ״שְׁלַח קְבֹץ אֵלַי״ (מלכים א יח:יט) לְשׁוֹן רָפֵי וְקַל:\",1,0],[2,123,2,17,\"לְחֶרְפָּה. לְגִדּוּפִין:\",1,0],[2,123,2,17,\"לִמְשָׁל בָּם גּוֹיִם. לְשׁוֹן מָשָׁל וּשְׁנִינָה:\",2,0],[2,123,2,18,\"וַיְקַנֵּא ה׳ לְאַרְצוֹ. לְשׁוֹן ״הַמְקַנֵּא אַתָּה לִי״ (במדבר יא:כט) נִכְנְסָה בְּלִבּוֹ צָרָתָהּ וְנִלְחַם בְּמִלְחַמְתָּהּ וְנִתְעַסֵּק בְּצָרְכֶיהָ. וְרַבּוֹתֵינוּ פֵּרְשׁוּ לְשׁוֹן ׳הַתְרָאָה׳, הִתְרָה בַּגּוֹבַאי עַל עִסְקֵי אַרְצוֹ:\",1,0],[2,123,2,19,\"חֶרְפָּה. גִּדּוּף שֶׁיִּקְרְאוּ אֶתְכֶם חַסְרֵי לֶחֶם:\",1,0],[2,123,2,20,\"וְאֶת הַצְּפוֹנִי. יֵשׁ לְפוֹתְרוֹ עַל חֵיל הָאַרְבֶּה וְעָלָיו נוֹפֵל לְשׁוֹן הִדַּחְתִּיו אֶל אֶרֶץ צִיָּה וּשְׁמָמָה. דָּבָר אַחֵר הָעָם הַבָּא מִצָּפוֹן מַלְכֵי אַשּׁוּר וְרַבּוֹתֵינוּ אוֹמְרִים זֶה יֵצֶר הָרָע שֶׁצָּפוּן בִּלְבָבוֹ שֶׁל אָדָם:\",1,0],[2,123,2,20,\"הַקַּדְמוֹנִי. הַמִּזְרָחִי. וְרַבּוֹתֵינוּ שֶׁפֵּרְשׁוּ בְּיֵצֶר הָרָע דָּרְשׁוּ שְׁנֵי הַיָּמִים הַלָּלוּ בְּמִקְדָּשׁ רִאשׁוֹן וּבְמִקְדָּשׁ שֵׁנִי וְכֵן פֵּרְשׁוּהוּ עַל אֲשֶׁר שָׂם פָּנָיו בְּמִקְדָּשׁ רִאשׁוֹן וְשֵׁנִי וְהֶחֱרִיבָם. וּלְפִי הַתַּרְגּוּם שֶׁפֵּרְשׁוּ עַל חֵיל מֶלֶךְ אַשּׁוּר צָרִיךְ לוֹמַר פָּנָיו (אֶל) הַיָּם הַקַּדְמוֹנִי מִקְצָת חֵילוֹ אֶשְׁלַח לְמִזְרָח וּמִקְצָתוֹ לְמַעֲרָב:\",2,0],[2,123,2,20,\"צַחֲנָתוֹ. בָּאְשׁוֹ יוֹרֶה עָלָיו שֶׁהוּא לְשׁוֹן זֹהַם וְטִנּוּף:\",3,0],[2,123,2,20,\"כִּי הִגְדִּיל לַעֲשׂוֹת. רָאָה שֶׁפָּשַׁט יָדוֹ בַּגְּדוֹלִים:\",4,0],[2,123,2,21,\"אַל תִּירְאִי אֲדָמָה. אֶרֶץ יִשְׂרָאֵל אִם תָּשׁוּבִי בִּתְשׁוּבָה:\",1,0],[2,123,2,23,\"אֶת הַמּוֹרֶה. אֶת נְבִיאֵיכֶם הַמּוֹרִים אֶתְכֶם לָשׁוּב אֵלַי כְּדֵי לְצַדֵּק אֶתְכֶם:\",1,0],[2,123,2,23,\"מוֹרֶה וּמַלְקוֹשׁ. כְּמוֹ ״יוֹרֶה וּמַלְקוֹשׁ״ (דברים יא:יד):\",2,0],[2,123,2,23,\"בָּרִאשׁוֹן. בְּנִיסָן וְאַף עַל פִּי שֶׁהַיּוֹרֶה הִיא רְבִיעָה רִאשׁוֹנָה הַיּוֹרֶדֶת עַל הַזֶּרַע וְהוּא בְּמַרְחֶשְׁוָן, אוֹתָהּ שָׁנָה בְּנִיסָן זָרְעוּ כְּמוֹ שֶׁמְּפֹרָשׁ בְּמַסֶּכֶת תַּעֲנִית שֶׁגָּדְלָה הַתְּבוּאָה בְּאַחַד עָשָׂר יוֹם:\",3,0],[2,123,2,24,\"וְהֵשִׁיקוּ. לְשׁוֹן הַשְׁמָעַת קוֹל כְּשֶׁהַקִּלּוּחַ יוֹרֵד מִן הַגַּת אֶל תּוֹךְ הַיֶּקֶב וְהוּא הַבּוֹר שֶׁלִּפְנֵי הַגַּת:\",1,0],[2,123,3,1,\"וְהָיָה אַחֲרֵי כֵן. לֶעָתִיד לָבֹא:\",1,0],[2,123,3,1,\"עַל כָּל בָּשָׂר. עַל מִי שֶׁנַּעֲשָׂה לִבּוֹ רַךְ כַּבָּשָׂר דֻּגְמַת ״וְנָתַתִּי לָכֶם לֵב בָּשָׂר״ (יחזקאל לו:כו):\",2,0],[2,123,3,3,\"וְתִמְרוֹת עָשָׁן. זְקִיפוּת מַעֲלֵה עָשָׁן בְּגֹבַהּ:\",1,0],[2,123,3,4,\"יֵהָפֵךְ לְחֹשֶׁךְ. לְבַיֵּשׁ אֶת הַמִּשְׁתַּחֲוִים לַחַמָּה:\",1,0],[2,123,3,5,\"וְהָיָה כָּל אֲשֶׁר יִקְרָא וְגוֹ׳ כַּאֲשֶׁר אָמַר. וְהֵיכָן אָמַר ״וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה׳ נִקְרָא עָלֶיךָ״ (דברים כח:י):\",1,0],[2,123,3,5,\"וּבַשְּׂרִידִים. בַּשְּׁאֵרִית אֲשֶׁר יוֹתִיר:\",2,0],[2,123,3,5,\"אֲשֶׁר ה׳ קוֹרֵא. לְשׁוֹן קְרוּאִים לִסְעוּדָה אוֹ לַעֲבוֹדַת הַמֶּלֶךְ לְשׁוֹן ׳הַזְמָנָה׳:\",3,0],[2,123,4,2,\"אֶל עֵמֶק יְהוֹשָׁפָט. אֵרֵד עִמָּם בְּעֹמֶק הַדִּין, יְהוֹשָׁפָט מִשְׁפָּטִי יָהּ:\",1,0],[2,123,4,3,\"יַדּוּ גוֹרָל. כְּמוֹ ״וַיַּדּוּ אֶבֶן בִּי״ (איכה ג:נג):\",1,0],[2,123,4,4,\"הַגְּמוּל אַתֶּם מְשַׁלְּמִים. זֶהוּ הַגְּמוּל שֶׁנָּתַן שְׁלֹמֹה לְחִירָם מֶלֶךְ צוֹר עֶשְׂרִים עִיר (מלכים א ט):\",1,0],[2,123,4,4,\"קַל מְהֵרָה. לְשׁוֹן ׳זְרִיזוּת׳:\",2,0],[2,123,4,8,\"לִשְׁבָאיִם וְגוֹ׳. לִבְנֵי שְׁבָא:\",1,0],[2,123,4,8,\"כִּי ה׳ דִּבֵּר. וְהֵיכָן דִּבֵּר ״עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו״ (בראשית ט:כה) כֵּן מְפֹרָשׁ בִּמְכִילְתִּין:\",2,0],[2,123,4,9,\"קַדְּשׁוּ מִלְחָמָה. אִם תּוּכְלוּן אַתֶּם לְהִלָּחֵם כְּנֶגְדִּי:\",1,0],[2,123,4,10,\"אִתֵּיכֶם. קלטר״ש בְּלַעַ״ז:\",1,0],[2,123,4,10,\"וּמַזְמְרוֹתֵיכֶם. שרפש״א בְּלַעַ״ז:\",2,0],[2,123,4,11,\"עוּשׁוּ. כְּמוֹ ׳חוּשׁוּ׳ כָּךְ חִבְּרוֹ מְנַחֵם. וְיוֹנָתָן תִּרְגֵּם ״יִתְכַּנְּשׁוּן״, וְאוֹמֵר אֲנִי שֶׁהוּא לְשׁוֹן ׳עֶשֶׁת בַּרְזֶל׳ הַמְכֻנָּס יַחַד מש״א בְּלַעַ״ז וְאֵין תָּי״ו בּוֹ יְסוֹד:\",1,0],[2,123,4,11,\"שָׁמָּה הִנְחַת ה׳ גִּבּוֹרֶיךָ. שָׁם בִּקְבוּצַת עֵמֶק יְהוֹשָׁפָט יִשְׁבּוֹר גְּבוּרַתְכֶם כֵּן תִּרְגֵּם יוֹנָתָן. וְאֵינִי יוֹדֵעַ אִם לְשׁוֹן אֲרָמִי הוֹרָדָה אוֹ לְשׁוֹן חֲתַת וְהַנּוּ״ן בּוֹ נוֹפֵל כְּמוֹ (דניאל ב:כה) ״הַנְעֵל לְדָנִיֵּאל קֳדָם מַלְכָּא״, שֶׁאֵין בּוֹ אוֹת שֹׁרֶשׁ אֶלָּא עַל:\",2,0],[2,123,4,13,\"שִׁלְחוּ מַגָּל וְגוֹ׳. שִׁלְחוּ חֲרָבוֹת אוֹתָם הַהוֹלְכִים בִּשְׁלִיחוּתִי לְחַבֵּל אֶת אוֹיְבֵי ה׳:\",1,0],[2,123,4,13,\"כִּי בָשַׁל קָצִיר. כְּלוֹמַר כִּי הִגִּיעַ עִתָּם וְדִמָּה הַדָּבָר לְקָצִיר שֶׁקּוֹצְרִים אוֹתוֹ בְּמַגָּלוֹת כְּשֶׁגָּמַר בִּשּׁוּלוֹ:\",2,0],[2,123,4,13,\"בֹּאוּ רְדוּ כִּי מָלְאָה גַת. מִן הָעֲנָבִים בֹּאוּ וְדִרְכוּ אוֹתָם כְּלוֹמַר נִתְמַלָּא סְאַת עֲוֹנָם. רְדוּ לְשׁוֹן כְּבִישָׁה וְרִדּוּי כְּמוֹ ״וּרְדוּ בִדְגַת הַיָּם״ (בראשית א:כח):\",3,0],[2,123,4,13,\"הֵשִׁיקוּ הַיְקָבִים. קוֹל קִלּוּחַ הַיְקָבִים הַיּוֹרֵד תּוֹךְ הַבּוֹר שֶׁלִּפְנֵי הַגִּתּוֹת נִשְׁמָע:\",4,0],[2,123,4,14,\"בְּעֵמֶק הֶחָרוּץ. שֶׁשָּׁם חָרוּץ שֶׁהַמִּשְׁפָּט אֱמֶת וְכֵן תִּרְגֵּם יוֹנָתָן ״מֵישַׁר פִּלּוּג דִּינָא״:\",1,0],[2,123,4,15,\"אָסְפוּ נָגְהָם. הִכְנִיסוּ אוֹרָם:\",1,0],[2,123,4,16,\"מִצִּיּוֹן יִשְׁאָג. מִמַּה שֶּׁעָשׂוּ לְצִיּוֹן:\",1,0],[2,123,4,16,\"וְרָעֲשׁוּ שָׁמַיִם וָאָרֶץ. יִפָּרַע מִשָּׂרִים שֶׁל מַעְלָה (שָׂרֵי הַכַּשְׂדִּים) וְאַחַר כָּךְ מִן (הַכַּשְׂדִּים):\",2,0],[2,123,4,16,\"מַחֲסֶה. לְשׁוֹן ׳כִּסּוּי׳, וּבְלַעַ״ז אבריאיי״ל:\",3,0],[2,123,4,18,\"אֲפִיקֵי. מְקוֹם מוֹצָא מַיִם:\",1,0],[2,123,4,18,\"וְהִשְׁקָה אֶת נַחַל הַשִּׁטִּים. כְּמַשְׁמָעוֹ ״וּמַשְׁקֵי יָת מֵישַׁר שִׁטִּים״. וּמִדְרָשׁוֹ יְכַפֵּר עַל עֲוֹן פְּעוֹר (עיין זכריה יד):\",2,0],[2,123,4,19,\"מִצְרַיִם וְגוֹ׳. סְמָכָן זֶה לָזֶה לְפֻרְעָנִיּוֹת אַתָּה מוֹצֵא שֶׁאִלּוּלֵי מִצְרַיִם לֹא הָיְתָה אֱדוֹם שֶׁנֶּאֱמַר (מלכים א יא:טז) ״כִּי שֵׁשֶׁת חֳדָשִׁים יָשַׁב יוֹאָב עַד הַכְרִית כָּל זָכָר בֶּאֱדוֹם״ וּכְתִיב (שם יז-כא) ״וַיִּבְרַח אֲדַד הוּא וַאֲנָשִׁים אֲדוֹמִיִּים וַיִּמְצָא הֲדַד חֵן בְּעֵינֵי פַרְעֹה וְגוֹמֵר וַהֲדַד שָׁמַע כִּי שָׁכַב דָּוִד עִם אֲבוֹתָיו וְגוֹמֵר״ וּבָאַחֲרוֹנָה ״וַיְהִי לְשָׂטָן לִשְׁלֹמֹה״ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֲנִי אֲכַלֶּה זוֹ וָזוֹ:\",1,0],[2,123,4,19,\"מֵחֲמַס בְּנֵי יְהוּדָה. בִּשְׁבִיל חָמָס שֶׁעָשׂוּ עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת לִבְנֵי יְהוּדָה אֲשֶׁר שָׁפְכוּ אֶת דָּמָם:\",2,0],[2,123,4,21,\"וְנִקֵּיתִי דָּמָם לֹא נִקֵּיתִי. וְאַף אִם אֲנַקֶּה אוֹתָם מִשְּׁאָר עֲבֵירוֹת שֶׁבְּיָדָם וּמֵרָעוֹת שֶׁעָשׂוּ לִי, דָּמָם שֶׁל בְּנֵי יְהוּדָה לֹא אֲנַקֶּה מֵהֶם. אֵימָתַי תִּהְיֶה זֹאת, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹכֵן בְּצִיּוֹן:\",1,0],[2,124,1,2,\"וּקְרָא עָלֶיהָ. אֶת קְרִיאָתִי:\",1,0],[2,124,1,3,\"לִבְרֹחַ תַּרְשִׁישָׁה. יָם שֶׁשְּׁמוֹ תַּרְשִׁישׁ, וְהוּא בְּחוּצָה לָאָרֶץ. אָמַר: אֶבְרַח לִי הַיָּם, שֶׁאֵין הַשְּׁכִינָה שׁוֹרָה בְּחוּץ לָאָרֶץ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: חַיֶּיךָ, יֵשׁ לִי שְׁלוּחִים כְּיוֹצֵא בְּךָ לִשְׁלוֹחַ אַחֲרֶיךָ וּלְהָבִיאֲךָ מִשָּׁם. מָשָׁל לְעֶבֶד כֹּהֵן שֶׁבָּרַח מִן רַבּוֹ וְנִכְנַס לְבֵית הַקְּבָרוֹת. אָמַר לוֹ רַבּוֹ: יֵשׁ לִי עֲבָדִים כַּיוֹצֵא בְּךָ לִשְׁלוֹחַ אַחֲרֶיךָ וּלְהָבִיאֲךָ מִשָּׁם. וּמָה רָאָה יוֹנָה שֶׁלֹּא רָצָה לֵילֵךְ אֶל נִינְוֵה? אָמַר: הָעַכּוּ״ם קְרוֹבֵי תְשׁוּבָה הֵם, אִם אוֹמַר לָהֶם וְיַעֲשׂוּ תְשׁוּבָה נִמְצֵאתִי מְחַיֵּב אֶת יִשְׂרָאֵל שֶׁאֵין שׁוֹמְעִים לְדִבְרֵי הַנְּבִיאִים:\",1,0],[2,124,1,3,\"וַיִּתֵּן שְׂכָרָהּ. הִקְדִּים לָתֵת שְׂכָרָהּ, וְאֵין דֶּרֶךְ יוֹרְדֵי הַיָּם לָתֵת שְׂכַר הַסְּפִינָה עַד שְׁעַת הַיְּצִיאָה, וְהוּא הִקְדִּים. וְלֹא עוֹד אֶלָּא שֶׁנָּתַן שְׂכַר כֻּלָּהּ:\",2,0],[2,124,1,4,\"חִשְּׁבָה לְהִשָּׁבֵר. נִדְמֵית כְּאִלּוּ הִיא נִשְׁבֶּרֶת:\",1,0],[2,124,1,5,\"הַמַּלָּחִים. בְּנֵי אָדָם הַמַּנְהִיגִים אֶת הַסְּפִינָה:\",1,0],[2,124,1,5,\"אִישׁ אֶל אֱלֹהָיו. מִן שִׁבְעִים אוּמּוֹת שֶׁל עַכּוּ״ם הָיוּ שָׁם:\",2,0],[2,124,1,6,\"רַב הַחֹבֵל. שַׂר הַמַּלָּחִים, שֶׁאַף הֵם נִקְרָאִים חוֹבְלֵי הַיָּם, וּבְלַעַ״ז גובירניי״ל:\",1,0],[2,124,1,6,\"מַה לְּךָ נִרְדָּם. מַה לְּךָ לִהְיוֹת נִרְדָּם? אֵין עַתָּה עֵת רְדֹם:\",2,0],[2,124,1,6,\"יִתְעַשֵּׁת. לְשׁוֹן מַחֲשָׁבָה, וְכֵן ״עֶשְׁתֹּנֹתָיו״ (תהלים קמ״ו:ד), ״וּמַלְכָּא עֲשִׁית״ (דניאל ו:ד):\",3,0],[2,124,1,7,\"לְכוּ וְנַפִּילָה גוֹרָלוֹת. רוֹאִים הָיוּ שְׁאָר סְפִינוֹת הוֹלְכוֹת בַּיָּם בְּשָׁלוֹם וְשֶׁלָּהֶם מִשְׁתַּבֶּרֶת. אָמְרוּ: בִּשְׁבִיל אֶחָד מִמֶּנּוּ הוּא. כֵּן מָצִינוּ בְּפִרְקֵי דְרַבִּי אֱלִיעֶזֶר:\",1,0],[2,124,1,7,\"בְּשֶׁלְּמִי. בְּמַעֲשָׂיו שֶׁל מִי מִמֶּנּוּ:\",2,0],[2,124,1,8,\"הַגִּידָה נָּא לָנוּ בַּאֲשֶׁר לְמִי. לְמִי חָטָאתָ אֲשֶׁר בִּשְׁבִיל כֵּן הָרָעָה הַזֹּאת לָנוּ:\",1,0],[2,124,1,8,\"מַה מְּלַאכְתְּךָ. שֶׁמָּא פָּשַׁעְתָּ בְּאוּמָּנוּתְךָ:\",2,0],[2,124,1,8,\"וּמֵאַיִן תָּבֹא. שֶׁמָּא עַל אַנְשֵׁי אוֹתוֹ מָקוֹם נִגְזְרָה גְזֵרָה אֲפִילּוּ אֵין אַתָּה בָהּ:\",3,0],[2,124,1,8,\"וְאֵי מִזֶּה עַם אָתָּה. שֶׁמָּא עַמְּךָ חָטְאוּ:\",4,0],[2,124,1,10,\"מַה זֹּאת עָשִׂיתָ. לָמָּה עָשִׂיתָ כֵּן לִבְרֹחַ מִן מוֹשֵׁל כָּזֶה:\",1,0],[2,124,1,13,\"וַיַּחְתְּרוּ הָאֲנָשִׁים. יָגְעוּ וְעָסְקוּ כְּחוֹתֵר בַּמַּחְתֶּרֶת:\",1,0],[2,124,1,14,\"בְּנֶפֶשׁ הָאִישׁ הַזֶּה. בֶּעָוֹן שֶׁנִּשְׁלַח יָד בְּנַפְשׁוֹ:\",1,0],[2,124,1,16,\"וַיִּדְּרוּ נְדָרִים. שֶׁיִּתְגַּיְּרוּ:\",1,0],[2,124,2,1,\"דָּג גָּדוֹל. זָכָר הָיָה וְהָיָה עוֹמֵד בְּרֶוַח וְלֹא נָתַן לֵב לְהִתְפַּלֵּל. רָמַז הַקָּדוֹשׁ בָּרוּךְ הוּא לַדָּג וְהֵקִיאוֹ לְתוֹךְ פִּיהָ שֶׁל נְקֵבָה שֶׁהָיְתָה מְלֵאָה עוּבָּרִים, וְהָיָה שָׁם בְּדוֹחַק וַיִּתְפַּלֵּל שָׁם, שֶׁנֶּאֱמַר ״מִמְּעֵי הַדָּגָה״. (וַיְמַן ה׳. אוֹתָן ט״ז יָמִים שֶׁחָסְרוּ יִשְׂרָאֵל מִן הַמָּן, שֶׁלֹּא אָכְלוּ מ׳ שָׁנִים שְׁלֵימוֹת הַמָּן. זֶה לָקַח הַקָּבָּ״ה וּפִרְנֵס אֶת הַדָּג שֶׁלֹּא יְעוּכַּל יוֹנָה בְּמֵעָיו, וְגַם יוֹנָה אָכַל בְּתוֹכוֹ מִזֶּה הַמָּן. לָכֵן נֶאֱמַר וַיְמַן – אוֹתִיּוֹת י״ו מ״ן. וְכֵן וַיְמַ״ן קִיקָיוֹן שֶׁהָיָה אוֹכֵל ד׳ עוֹמְרִים, לָכֵן נֶאֱמַר ד׳ פְּעָמִים וַיְמַן. וּבְלָשׁוֹן יָוָן נִקְרָא מָן קִיקָא, וְעַל זֶה נֶאֱמַר קִי״ק יוֹ״ן. סוד מישרים):\",1,0],[2,124,2,2,\"(ה׳ אלהיו שִׁתֵּף דִּין וְרַחֲמִים, זְכוּת אַבְרָהָם וְיִצְחָק. ממעי הדגה זֶה יַעֲקֹב. סוד מישרים):\",1,0],[2,124,2,3,\"מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי. מִבֶּטֶן הַדָּג שֶׁהוּא כִּשְׁאוֹל לִי:\",1,0],[2,124,2,4,\"כָּל מִשְׁבָּרֶיךָ וְגַלֶּיךָ. כָּל נַחְשׁוּלוֹהִי דְיַמָּא, עַל שֵׁם שֶׁהַנַּחְשׁוֹל מְשַׁבֵּר וּמְפָרֵק אֶת הַיָּם:\",1,0],[2,124,2,5,\"וַאֲנִי אָמַרְתִּי. כְּשֶׁהִשְׁלִיכוּנִי אֶל הַיָּם: הִנְנִי מֵת וְנִגְרַשְׁתִּי מִנֶּגֶד עֵינֶיךָ:\",1,0],[2,124,2,5,\"אַךְ. רָאִיתִי שֶׁקִּיַּמְתַּנִי כָּל אֵלּוּ הַיָּמִים, יָדַעְתִּי כִּי אוֹסִיף לְהַבִּיט אֶל הֵיכַל קָדְשֶׁךָ:\",2,0],[2,124,2,6,\"סוּף חָבוּשׁ לְרֹאשִׁי. יַמָּא דְסוּף תָּלֵי לְעֵיל מִן רֵישִׁי, שֶׁהֶרְאָהוּ הַקָּדוֹשׁ בָּרוּךְ הוּא יַם סוּף וְאֵיךְ עָבְרוּ יִשְׂרָאֵל בְּתוֹכוֹ, שֶׁהָיוּ שְׁתֵּי עֵינֵי הַדָּגָה כְּמִין שְׁתֵּי חַלּוֹנוֹת וּמִסְתַּכֵּל וְרוֹאֶה כָּל מַה שֶּׁבַּיָּם:\",1,0],[2,124,2,7,\"לְקִצְבֵי הָרִים יָרַדְתִּי. לְסוֹף מִדַּת הֶהָרִים הַקְּבוּעִים עַל הַתְּהוֹם יָרַדְתִּי:\",1,0],[2,124,2,7,\"״אֲנִי אָמַרְתִּי״ הָאָרֶץ בְּרִיחֶיהָ בַעֲדִי. כְּנֶגְדִּי לְמַעְלָה מִמֶּנִּי סָגוּר וְלֹא אֵצֵא לְעוֹלָם. בַּעֲדִי כְּמוֹ ״וְסָגַרְתְּ הַדֶּלֶת בַּעֲדֵךְ״ (מלכים ב ד:ד), וְכֵן כָּל בְּעַד שֶׁבַּמִּקְרָא ״עוֹר בְּעַד עוֹר״ (איוב ב:ד) – אֵבֶר כְּנֶגֶד אֵבֶר:\",2,0],[2,124,2,7,\"לְעוֹלָם. מוּסָב עַל מַה שֶּׁאָמַר לְמַעְלָה: וַאֲנִי אָמַרְתִּי נִגְרַשְׁתִּי, וַאֲנִי אָמַרְתִּי הָאָרֶץ בְּרִיחֶיהָ סְגוּרִים בַּעֲדִי לְעוֹלָם:\",3,0],[2,124,2,7,\"וַתַּעַל מִשַּׁחַת חַיַּי. אֲבָל כְּבָר רָאִיתִי כָּאן גֵּיהִנֹּם וּמִשָּׁם הֶעֱלִיתָנִי, וְהִנְנִי עַתָּה כְּנֶגֶד תַּחַת הַהֵיכָל שֶׁבִּירוּשָׁלַיִם, כְּעִנְיָן שֶׁנֶּאֱמַר: ״אַךְ אוֹסִיף לְהַבִּיט אֶל הֵיכַל קָדְשֶׁךָ״, ״וַתָּבֹא אֵלֶיךָ תְפִלָּתִי אֶל הֵיכַל קָדְשֶׁךָ״:\",4,0],[2,124,2,8,\"בְּהִתְעַטֵּף. בְּאִשְׁתַּלְהָיוּת, וְכֵן ״בְּהִתְעַטֵּף נַפְשָׁם״, וְכֵן ״בַּעֲטֹף עוֹלֵל״ (איכה ב:יא):\",1,0],[2,124,2,9,\"מְשַׁמְּרִים הַבְלֵי שָׁוְא. אוֹתָן שֶׁעוֹבְדִים לְעַכּוּ״ם:\",1,0],[2,124,2,9,\"חַסְדָּם יַעֲזֹבוּ. יִרְאַת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁכָּל חַסְדָּם וְטוֹבָתָם מֵאִתּוֹ יַעֲזֹבוּ, אֲבָל אֲנִי אֵינִי כֵן אֶלָּא בְּקוֹל תּוֹדָה אֶזְבְּחָה לָּךְ. כָּךְ תִּרְגֵּם יוֹנָתָן. וּפִרְקֵי דְרַבִּי אֱלִיעֶזֶר דָּרְשׁוּ כְּלַפֵּי הַמַּלָּחִים שֶׁעָזְבוּ חַסְדָּם שֶׁהָיוּ מְטִיבִים לְעַכּוּ״ם וְנִתְגַּיְּרוּ:\",2,0],[2,124,2,10,\"יְשׁוּעָתָה לַה׳. נִדְרֵי שְׁלָמִים וְתוֹדָה אֲשַׁלֵּם לְשֵׁם יְשׁוּעוֹת אֲשֶׁר לַה׳. יְשׁוּעָתָה כְּמוֹ לִישׁוּעָתָה, וְכֵן ״קוּמָה עֶזְרָתָה לָּנוּ״ (תהלים מד:כז) – לְעֶזְרָה שֶׁלָּנוּ:\",1,0],[2,124,3,4,\"נֶהְפָּכֶת. נֶחֱרֶבֶת. (וְלֹא אָמַר נֶחֱרֶבֶת כִּי נֶהְפָּכֶת מְשַׁמֵּשׁ שְׁתֵּי לְשׁוֹנוֹת, רַע וְטוֹב: אִם לֹא יַעֲשׂוּ תְשׁוּבָה – נֶחֱרֶבֶת, וְאִם יַעֲשׂוּ תְשׁוּבָה – אָז נֶהְפָּכֶת. עַל אַנְשֵׁי נִינְוֵה קָאֵי שֶׁיַּהַפְכוּ מֵרָעָה לְטוֹבָה וְיַעֲשׂוּ תְשׁוּבָה. הג״ה דר״ע):\",1,0],[2,124,3,6,\"אַדַּרְתּוֹ. לְבוּשׁ יְקָרֵיהּ:\",1,0],[2,124,3,7,\"וַיַּזְעֵק. צִוָּה וְהִכְרִיז:\",1,0],[2,124,3,7,\"מִטַּעַם הַמֶּלֶךְ וּגְדוֹלָיו. מֵעֲצַת הַמֶּלֶךְ וּגְדוֹלָיו צִוּוּ לְהַכְרִיז:\",2,0],[2,124,3,8,\"וְיִקְרְאוּ אֶל אֱלֹהִים בְּחָזְקָה. אָסְרוּ אִמָּהוֹת לְבַד וְהַוְּלָדוֹת לְבַד. אָמְרוּ לְפָנָיו: רִבּוֹנוֹ שֶׁל עוֹלָם, אִם אֵין אַתָּה מְרַחֵם עָלֵינוּ אֵין אָנוּ מְרַחֲמִים עַל אֵלּוּ:\",1,0],[2,124,3,9,\"מִי יוֹדֵעַ. עֲבֵירוֹת שֶׁבְּיָדוֹ יָשׁוּב:\",1,0],[2,124,3,10,\"וַיִּנָּחֶם הָאֱלֹהִים. נִתְעַשֵּׁת עַל הָרָעָה לָשׁוּב מִמֶּנָּה:\",1,0],[2,124,4,1,\"וַיֵּרַע אֶל יוֹנָה. אָמַר: עַכְשָׁיו יֹאמְרוּ הָעַכּוּ״ם שֶׁאֲנִי נְבִיא הַשֶּׁקֶר:\",1,0],[2,124,4,2,\"הֲלֹא זֶה דְבָרִי. יוֹדֵעַ אֲנִי שֶׁאִם יַחְזְרוּ בִּתְשׁוּבָה לֹא תַּחֲרִיבֵם וְאֶהְיֶה שַׁקְרָן בְּעֵינֵיהֶם:\",1,0],[2,124,4,6,\"וַיְמַן. לְשׁוֹן הַזְמָנָה:\",1,0],[2,124,4,6,\"לְהַצִּיל לוֹ מֵרָעָתוֹ. מֵחוֹם הַשֶּׁמֶשׁ:\",2,0],[2,124,4,6,\"קִיקָיוֹן. עֵשֶׂב הַגָּדֵל לְמַעְלָה בַּעֲנָפִים רַבִּים וּמֵצִיל, וְכָךְ שְׁמוֹ:\",3,0],[2,124,4,7,\"וַתַּךְ. הַתּוֹלַעַת אֶת הַקִּיקָיוֹן. בִּמְקוֹם שֶׁיֹּאמַר לְזָכָר וַיַּךְ, יֹאמַר לְשׁוֹן נְקֵבָה וַתַּךְ:\",1,0],[2,124,4,8,\"חֲרִישִׁית. אָמְרוּ רַבּוֹתֵינוּ: בְּשָׁעָה שֶׁמְּנַשֶּׁבֶת מַשְׁתֶּקֶת כָּל הָרוּחוֹת מִפָּנֶיהָ וְהִיא חַמָּה מְאֹד. וְכֵן תִּרְגֵּם יוֹנָתָן: שְׁתִיקָא:\",1,0],[2,124,4,8,\"וַיִּתְעַלָּף. פשמיי״ר בְּלַעַ״ז:\",2,0],[2,124,4,10,\"לֹא עָמַלְתָּ בּוֹ. בַּחֲרִישָׁה וּזְרִיעָה וְהַשְׁקָאַת מַיִם:\",1,0],[2,124,4,10,\"שֶׁבִּן לַיְלָה. כְּמוֹ בֶּן לַיְלָה, לֹא גָדַל אֶלָּא לַיְלָה אֶחָד:\",2,0],[2,124,4,11,\"אֲשֶׁר לֹא יָדַע וגו׳. קְטַנִּים:\",1,0],[2,124,4,11,\"וּבְהֵמָה רַבָּה. בְּנֵי אָדָם גְּדוֹלִים וְדַעְתָּן כִּבְהֵמָה, שֶׁאֵינָם מַכִּירִים מִי בְּרָאָם:\",2,0],[2,125,1,1,\"וַיְהִי אַחֲרֵי מוֹת משֶׁה מְחוּבָּר עַל סֵדֶר הַתּוֹרָה הַמְסַיֶּימֶת בִּפְטִירַת משֶׁה, וְזֶה מְחוּבָּר לָהּ.\",1,0],[2,125,1,2,\"משֶׁה עַבְדִּי מֵת וְאִילּוּ הָיָה קַיָּים, בּוֹ הָיִיתִי חָפֵץ. וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ (תמורה טז א) עַל שְׁלשֶׁת אֲלָפִים הֲלָכוֹת שֶׁנִּשְׁתַּכְּחוּ בִּימֵי אֶבְלוֹ שֶׁל משֶׁה. בָּא יְהוֹשֻׁעַ וְשָׁאַל, אָמַר לוֹ הַקָּבָּ\\\"ה: משֶׁה עַבְדִּי מֵת וְהַתּוֹרָה עַל שְׁמוֹ נִקְרֵאת, לוֹמַר לְךָ אִי אֶפְשָׁר, צֵא וְטוֹרְדָן בְּמִלְחָמָה.\",1,0],[2,125,1,3,\"כָּל מָקוֹם אֲשֶׁר תִּדְרֹךְ כַּיּוֹצֵא בּוֹ נֶאֱמַר לְמשֶׁה, וְשָׁנִינוּ בְּסִפְרֵי (פר' עקב): אִם לְלַמֵּד עַל תְּחוּמֵי אֶרֶץ יִשְׂרָאֵל, הֲרֵי הוּא אוֹמֵר: מֵהַמִּדְבָּר וְהַלְּבָנוֹן הַזֶּה, אִם כֵּן לָמָּה נֶאֱמַר: כָּל מָקוֹם אֲשֶׁר תִּדְרֹךְ כַּף אַף חוּצָה לָאָרֶץ, מִשֶּׁתִּכְבְּשׁוּ אֶת הָאָרֶץ, כָּל מַה שֶּׁתִּכְבְּשׁוּ מִחוּצָה לָאָרֶץ יִהְיֶה קָדוֹשׁ וְיִהְיֶה שֶׁלָּכֶם.\",1,0],[2,125,1,4,\"מֵהַמִּדְבָּר וְהַלְּבָנוֹן הַזֶּה הוּא מִדְבַּר קָדֵשׁ, מִדְבַּר צִין שֶׁעַל יְדֵי אֱדוֹם, שֶׁהָיָה בְּמִקְצוֹעַ דְּרוֹמִית מִזְרָחִית וְדֶרֶךְ שָׁם נִכְנְסוּ לָאָרֶץ, שֶׁנֶּאֱמַר (במדבר כ טז): וְהִנֵּה אֲנַחְנוּ בְקָדֵשׁ וְגוֹמֵר, וּמִנַּיִין שֶׁהָיָה בִּדְּרוֹמִית מִזְרָחִית, שֶׁנֶּאֱמַר (שם לד ג): וְהָיָה לָכֶם פְּאַת נֶגֶב מִמִּדְבַּר צִין עַל יְדֵי אֱדוֹם.\",1,0],[2,125,1,4,\"וְעַד הַנָּהָר הַגָּדוֹל נְהַר פְּרָת זֶה רָחְבָּהּ מִדָּרוֹם לְצָפוֹן.\",2,0],[2,125,1,4,\"כָּל אֶרֶץ הַחִתִּים בַּכְּלָל הַזֶּה.\",3,0],[2,125,1,4,\"וְעַד הַיָּם הַגָּדוֹל מְבוֹא הַשָּׁמֶשׁ לְאָרְכָּהּ, מִן הַמִּזְרָח לַמַּעֲרָב.\",4,0],[2,125,1,6,\"חֲזַק וֶאֱמָץ בְּדֶרֶךְ אֶרֶץ, כְּמָה שֶׁהוּא אוֹמֵר: כִּי אַתָּה תַּנְחִיל.\",1,0],[2,125,1,7,\"רַק חֲזַק וֶאֱמַץ מְאֹד בְּתּוֹרָה, כְּמוֹ שֶׁהוּא אוֹמֵר: לִשְׁמֹר וְלַעֲשׂוֹת כְּכָל הַתּוֹרָה.\",1,0],[2,125,1,7,\"תַּשְׂכִּיל תַּצְלִיחַ.\",2,0],[2,125,1,8,\"סֵפֶר הַתּוֹרָה הַזֶּה סֵפֶר מִשְׁנֵה תּוֹרָה הָיָה לְפָנָיו.\",1,0],[2,125,1,8,\"וְהָגִיתָ בּוֹ וְהִתְבּוֹנַנְתָּ בּוֹ, כָּל הִגָּיוֹן שֶׁבַּתּוֹרָה בַּלֵּב, כְּמָה דְּאַתְּ אָמַר (תהלים יט טו): וְהֶגְיוֹן לִבִּי לְפָנֶיךָ, (ישעיהו לג יח): לִבְּךָ יֶהְגֶּה אֵימָה.\",2,0],[2,125,1,9,\"הֲלוֹא צִוִּיתִיךָ חֲזַק וֶאֱמָץ בְּמִלְחָמָה, כְּמוֹ שֶׁנֶּאֱמַר: אַל תַּעֲרֹץ וְאַל תֵּחָת. וְהֵיכָן צִוָּהוּ בִּימֵי משֶׁה, שֶׁנֶּאֱמַר (דברים לא כג): וַיְצַו אֶת יְהוֹשֻׁעַ בִּן־נוּן וְגוֹ'.\",1,0],[2,125,1,10,\"וַיְצַו יְהוֹשֻׁעַ בְּיּוֹם שֶׁתַּמּוּ יְמֵי בְּכִי אֵבֶל משֶׁה.\",1,0],[2,125,1,11,\"הָכִינוּ לָכֶם צֵדָה כָּל דָּבָר הַצָּרִיךְ לַדֶּרֶךְ וּכְלֵי זֵינָם לַמִּלְחָמָה אָמַר לָהֶם לְתַקֵּן, שֶׁאִם אַתָּה אוֹמֵר בְּמַאֲכָל וּבְמִשְׁתֶּה, הֲרֵי הָיוּ מִסְתַּפְּקִים בַּמָּן שֶׁבִּכְלֵיהֶם עַד ט\\\"ז בְּנִיסָן, וְכֵן הוּא אוֹמֵר (לקמן ה יב): וַיִּשְׁבֹּת הַמָּן מִמָּחֳרָת (מִפִּי רַבִּי).\",1,0],[2,125,1,11,\"בְּעוֹד שְׁלשֶׁת יָמִים בְּסוֹף שְׁלשֶׁת יָמִים, בְּעוֹד שֶׁתִּהְיוּ כָּאן שְׁלשֶׁת יָמִים וְאַחַר תַּעֲבֹרוּ.\",2,0],[2,125,1,14,\"כָּל גִּבּוֹרֵי הַחַיִל שֶׁבָּכֶם יַעַבְרוּ חֲלוּצִים.\",1,0],[2,125,1,15,\"מִזְרַח הַשָּׁמֶשׁ עֵבֶר מִזְרָחִי שֶׁל יַרְדֵּן.\",1,0],[2,125,1,18,\"יַמְרֶה יַקְנִיט אֶת דְּבָרֶיךָ.\",1,0],[2,125,2,1,\"וַיִּשְׁלַח יְהוֹשֻׁעַ וְגוֹ' עַל כָּרְחִי אֲנִי צָרִיךְ לוֹמַר שֶׁבְּתוֹךְ יְמֵי אֵבֶל משֶׁה שְׁלָחָם, שֶׁהֲרֵי לְסוֹף ג' יָמִים שֶׁתַּמּוּ יְמֵי אֵבֶל משֶׁה עָבְרוּ אֶת הַיַּרְדֵּן, שֶׁמִּשָּׁם אָנוּ לְמֵדִים שֶׁמֵּת משֶׁה בְּז' אֲדָר כְּשֶׁאַתָּה מוֹנֶה ל\\\"ג לְמַפְרֵעַ מִיּוֹם שֶׁעָלוּ מִן הַיַּרְדֵּן בֶּעָשׂוֹר לַחֹדֶשׁ הָרִאשׁוֹן, וְעַל כָּרְחָךְ מִשֶּׁנִּשְׁתַּלְּחוּ הַמְרַגְּלִים לֹא עָבְרוּ אֶת הַיַּרְדֵּן עַד יוֹם הַחֲמִישִׁי, שֶׁנֶּאֱמַר: וַיֵּשְׁבוּ שָׁם שְׁלשֶׁת יָמִים עַד־שָׁבוּ הָרוֹדְפִים בּוֹ בַּלַּיְלָה, וַיַּעַבְרוּ וַיָּבֹאוּ אֶל יְהוֹשֻׁעַ בִּן־נוּן... וַיַּשְׁכֵּם יְהוֹשֻׁעַ בַּבֹּקֶר וַיִּסְעוּ מֵהַשִּׁטִּים הֲרֵי יוֹם ד', וַיָּלִינוּ שָׁם טֶרֶם יַעֲבֹרוּ נִמְצָא שֶׁלֹּא עָבְרוּ עַד יוֹם ה'.\",1,0],[2,125,2,1,\"חֶרֶשׁ בְּרָז, כָּךְ תִּירְגֵּם יוֹנָתָן, אָמַר לָהֶם: עֲשׂוּ עַצְמְכֶם כְּחֵרְשִׁים, כְּדֵי שֶׁלֹּא יַסְתִּירוּ דִּבְרֵיהֶם מִפְּנֵיכֶם. דָּבָר אַחֵר: חֶרֶשׁ חֶרֶס, הַטְעִינוּ עַצְמְכֶם קְדֵרוֹת כְּדֵי שֶׁתִּהְיוּ נִרְאִין כְּקַדָּרִין.\",2,0],[2,125,2,1,\"רְאוּ אֶת הָאָרֶץ וְאֶת יְרִיחוֹ וַהֲלֹא יְרִיחוֹ בִּכְלָל הָיְתָה וְלָמָּה יָצָאת, אֶלָּא שֶׁהָיְתָה קָשָׁה כְּנֶגֶד כּוּלָּם, לְפִי שֶׁהָיְתָה יוֹשֶׁבֶת עַל הַסְּפָר. וְכַיּוֹצֵא בּוֹ (שמואל ב ב ל): וַיִּפָּקְדוּ מֵעַבְדֵי דָּוִד תִּשְׁעָה־עָשָׂר אִישׁ וַעֲשָׂהאֵל, וַהֲלֹא עֲשָׂהאֵל בִּכְלָל הָיָה וְלָמָּה יָצָא, אֶלָּא שֶׁהָיָה קָשֶׁה כְּנֶגֶד כּוּלָּם, כַּיּוֹצֵא בּוֹ (מלכים א יא א): וְהַמֶּלֶךְ שְׁלֹמֹה אָהַב נָשִׁים נָכְרִיּוֹת רַבּוֹת וְאֶת בַּת פַּרְעֹה, וַהֲלֹא בַּת פַּרְעֹה בִּכְלָל הָיְתָה וְלָמָּה יָצָאת, אֶלָּא שֶׁהָיָה מְחַבְּבָהּ כְּנֶגֶד כּוּלָּם, וּכְלַפֵּי חֵטְא שֶׁהֶחֱטִיאָה אוֹתוֹ יוֹתֵר מִכּוּלָּן, כָּךְ שְׁנוּיָיה בְּסִפְרֵי (עקב נב).\",3,0],[2,125,2,1,\"אִשָּׁה זוֹנָה תִּירְגֵּם יְהוֹנָתָן: פּוּנְדְּקִיתָא, מוֹכֶרֶת מִינֵי מְזוֹנוֹת.\",4,0],[2,125,2,2,\"לַחְפֹּר לְרַגֵּל, כְּמוֹ (איוב לט כט): מִשָּׁם חָפַר אֹכֶל.\",1,0],[2,125,2,4,\"וַתִּצְפְּנוֹ יֵשׁ מִקְרָאוֹת מְדַבְּרִים עַל הָרַבִּים כְּיָחִיד, לְפִי שֶׁמִּיהֲרָה בְּהַטְמָנָתָם וּבְמָקוֹם צַר, כְּאִילּוּ הָיָה יְחִידִי, וּמִדְרַשׁ אַגָּדַת תַּנְחוּמָא יֵשׁ (שלח א): פִּנְחָס וְכָלֵב הָיוּ, וּפִנְחָס עָמַד לִפְנֵיהֶם וְלֹא רָאוּהוּ לְפִי שֶׁהָיָה כְּמַלְאָךְ. דָּבָר אַחֵר: וַתִּצְפְּנוֹ כָּל אֶחָד וְאֶחָד בִּפְנֵי עַצְמוֹ, וְדוּגְמָתוֹ מָצִינוּ (משלי כז ט): שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב, וְלֹא אָמַר יְשַׂמְּחוּ לֵב.\",1,0],[2,125,2,6,\"בְּפִשְׁתֵּי הָעֵץ פִּשְׁתִּים בְּגִבְעוֹלֵיהֶן.\",1,0],[2,125,2,7,\"עַל הַמַּעְבְּרוֹת מְקוֹם מַעֲבַר הַמַּיִם, שֶׁהָיוּ סְבוּרִים שֶׁחָזְרוּ לַאֲחוֹרֵיהֶם אֶל עַרְבוֹת מוֹאָב, וְהַיַּרְדֵּן מַפְסִיק בֵּינְתַיִם.\",1,0],[2,125,2,7,\"וְהַשַּׁעַר סָגָרוּ הַשּׁוֹעֲרִים.\",2,0],[2,125,2,11,\"וְלֹא קָמָה עוֹד רוּחַ בְּאִישׁ אֲפִילּוּ לִּשְׁכַּב עִם אִשָּׁה, אָמְרוּ: אֵין לְךָ כָּל שַׂר וְנָגִיד שֶׁלֹּא בָּא אֶל רָחָב הַזּוֹנָה, וּבַת עֶשֶׂר שָׁנִים הָיְתָה כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, וְזִנְּתָה כָּל אַרְבָּעִים שָׁנָה (זבחים קטז ב).\",1,0],[2,125,2,12,\"אוֹת אֱמֶת שֶׁתַּעֲשׂוּ כְּשֶׁתָּבֹאוּ וַתִּכְבְּשׁוּ אֶת הָעִיר, שֶׁתַּכִּירוּ הָאוֹת וְתַחְיוּנִי.\",1,0],[2,125,2,15,\"וַתּוֹרִדֵם בַּחֶבֶל בְּעַד הַחַלּוֹן בְּאוֹתוֹ חֶבֶל וְחַלּוֹן הָיוּ הַנּוֹאֲפִים עוֹלִין אֵלֶיהָ. אָמְרָה: רִבּוֹנוֹ שֶׁל עוֹלָם, בְּאֵלּוּ חָטָאתִי בְּאֵלּוּ תִּמְחוֹל לִי.\",1,0],[2,125,2,16,\"עַד שׁוֹב הָרֹדְפִים רָאֲתָה בְּרוּחַ הַקֹּדֶשׁ שֶׁיָּשׁוּבוּ לְסוֹף שְׁלשֶׁת יָמִים.\",1,0],[2,125,2,17,\"נְקִיִּים אֲנַחְנוּ הֲרֵי אָנוּ תּוֹלִין הַדָּבָר בָּךְ לַעֲשׂוֹת הָאוֹת הַזֶּה.\",1,0],[2,125,2,18,\"אֶת תִּקְוַת לְשׁוֹן קַו וְחֶבֶל.\",1,0],[2,125,2,19,\"דָּמוֹ בְרֹאשׁוֹ עֲוֹן הֲרִיגָתוֹ עַל רֹאשׁוֹ תְּהֵא, כִּי הוּא יִגְרוֹם מִיתָתוֹ.\",1,0],[2,125,2,19,\"דָּמוֹ בְרֹאשֵׁנוּ עֲוֹן הֲרִיגָתוֹ תְּהֵא עָלֵינוּ.\",2,0],[2,125,2,23,\"וַיַּעַבְרוּ אֶת הַיַּרְדֵּן.\",1,0],[2,125,3,3,\"וַהֲלַכְתֶּם אַחֲרָיו. נִשְׁתַּנָּה הַמַּסָּע הַזֶּה מִשְּׁאָר מַסָּעוֹת, שֶׁכָּל זְמָן שֶׁמֹּשֶׁה הָיָה קַיָּים הָיָה עַמּוּד הֶעָנָן נוֹסֵעַ תְּחִלָּה, וּמַרְאֶה לָהֶם הַדֶּרֶךְ וְהָאָרוֹן נוֹסֵעַ אַחַר ב' דְּגָלִים, עַכְשָׁיו הָאָרוֹן נוֹסֵעַ תְּחִלָּה.\",1,0],[2,125,3,3,\"וְהַכֹּהֲנִים הַלְוִיִּם לְפִי שֶׁיָּצְאוּ כּוּלָּם מִלֵּוִי (אֲבִי) אֲבִי עַמְרָם נִקְרְאוּ לְוִיּם, כְּמוֹ שֶׁפֵּרְשׁוּ רַבּוֹתֵינוּ בִּבְרֵאשִׁית רַבָּה: בְּמ\\\"ח מְקוֹמוֹת נִקְרְאוּ הַכֹּהֲנִים לְוִיּם. וְזֶה טַעְמוֹ שֶׁל דָּבָר (מפּי רבּי).\",2,0],[2,125,3,4,\"אַךְ רָחוֹק יִהְיֶה כְּבוֹדוֹ שֶׁל מָקוֹם הוּא.\",1,0],[2,125,3,4,\"וּבֵינָיו כְּמוֹ וּבֵינוֹ, וְדוֹמֶה לוֹ (תהלים קמט ב): יִשְׂמַח יִשְׂרָאֵל בְּעוֹשָׂיו. דָּבָר אַחֵר: ב' אֲרוֹנוֹת הָיוּ, שֶׁל שְׁכִינָה וְשֶׁל יוֹסֵף מְהַלְּכִין יַחַד.\",2,0],[2,125,3,4,\"כְּאַלְפַּיִם אַמָּה כְּדֵי שֶׁתִּהְיוּ יְכוֹלִין לֵילֵךְ וּלְהִתְפַּלֵּל לְפָנָיו בְּשַׁבָּת, כָּךְ מְפוֹרָשׁ בְּמִדְרַשׁ תַּנְחוּמָא, לְפִי שֶׁיָּדַע שֶׁעֲתִידִין לִהְיוֹת צָרִים לִפְנֵי יְרִיחוֹ בַּשַּׁבָּת.\",3,0],[2,125,3,4,\"לְמַעַן אֲשֶׁר תֵּדְעוּ מוּסָב עַל: וַהֲלַכְתֶּם אַחֲרָיו.\",4,0],[2,125,3,4,\"כִּי לֹא עֲבַרְתֶּם בַּדֶּרֶךְ לֹא הֲלַכְתֶּם בְּעִנְיָן זֶה עַד הֵנָּה.\",5,0],[2,125,3,5,\"וַיֹּאמֶר יְהוֹשֻׁעַ בַּיּוֹם הַשְּׁלִישִׁי, וְיוֹם ל' שֶׁל אֵבֶל הָיָה רִאשׁוֹן לְג' הַיָּמִים.\",1,0],[2,125,3,5,\"הִתְקַדָּשׁוּ הִזְדַּמְּנוּ.\",2,0],[2,125,3,5,\"כִּי מָחָר בְּעָבְרְכֶם אֶת הַיַּרְדֵּן.\",3,0],[2,125,3,5,\"נִפְלָאוֹת תִּירְגֵּם יוֹנָתָן: פְּרִישָׁן.\",4,0],[2,125,3,6,\"וַיֹּאמֶר יְהוֹשֻׁעַ אֶל הַכֹּהֲנִים בְּיוֹם הַמָּחֳרָת.\",1,0],[2,125,3,6,\"שְׂאוּ אֶת אֲרוֹן הַבְּרִית עַד עַכְשָׁיו נָשְׂאוּ הַלְוִיִּם, וְהַיּוֹם הַכֹּהֲנִים.\",2,0],[2,125,3,8,\"כְּבֹאֲכֶם עַד קְצֵה מֵי הַיַּרְדֵּן כְּשֶׁתִּכַּנְסוּ לִפְנִים מִשְּׂפָתוֹ.\",1,0],[2,125,3,8,\"בַּיַּרְדֵּן תַּעֲמֹדוּ עַד אֲשֶׁר יַעַבְרוּ כָּל הָעָם אֶל הָעֵבֶר הַשֵּׁנִי.\",2,0],[2,125,3,9,\"גְּשׁוּ הֵנָּה צִמְצֵם אֶת כּוּלָּם בֵּין שְׁנֵי בַּדֵּי אָרוֹן, זֶה אֶחָד מִן הַמְּקוֹמוֹת שֶׁהֶחֱזִיק מוּעָט אֶת הַמְרוּבֶּה.\",1,0],[2,125,3,10,\"בְּזֹאת תֵּדְעוּן בְּמַה שֶּׁאַתֶּם רוֹאִים שֶׁכֻּלְּכֶם מְצוּמְצָמִין כָּאן.\",1,0],[2,125,3,11,\"הַבְּרִית אֲדוֹן כָּל הָאָרֶץ בְּרִית שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא אֲדוֹן כָּל הָאָרֶץ. וְאַל תִּתְמַהּ עַל הַהֵ\\\"א שֶׁל הַבְּרִית, שֶׁהַרְבֵּה מִקְרָאוֹת מְדַבְּרִים כָּךְ, כְּמוֹ: (מלכים ב טז יז) הַמִּסְגְּרוֹת הַמְּכוֹנֹת: (ירמיהו לא לט) הָעֵמֶק הַפְּגָרִים.\",1,0],[2,125,3,11,\"עֹבֵר לִפְנֵיכֶם מַקְדִּים לִפְנֵיכֶם לִיכָּנֵס לְתוֹךְ הַיַּרְדֵּן.\",2,0],[2,125,3,12,\"קְחוּ לָכֶם שְׁנֵי עָשָׂר אִישׁ הָכִינוּ אוֹתָם לִהְיוֹת נְכוֹנִים לְמַה שֶּׁאֲצַוֶּה אוֹתָם כְּשֶׁתַּעַבְרוּ אֶת הַיַּרְדֵּן.\",1,0],[2,125,3,13,\"הַמַּיִם הַיֹּרְדִים מִלְמָעְלָה לְמַטָּה, כְּדֶרֶךְ כָּל הַנְּהָרוֹת הַמּוֹשְׁכִים.\",1,0],[2,125,3,13,\"וְיַעַמְדוּ נֵד אֶחָד כְּשֶׁיֵּרְדוּ הַמַּיִם עַד מָקוֹם שֶׁנִּכְרְתוּ שָׁם וְאֵינָם יוֹרְדִים מִשָּׁם וּלְמַטָּה, אֶלָּא הֵם מִתְקַבְּצִים וְנִגְדָּשִׁין וְעוֹלִין לְמַעְלָה, כִּיפִּין עַל גַּבֵּי כִּיפִּין.\",2,0],[2,125,3,13,\"נֵד כְּמוֹ (תהלים לג ז): כּוֹנֵס כַּנֵּד: (ישעיהו יז יא), נֵד קָצִיר, לְשׁוֹן גּוֹבַהּ, וְכֵן חִבְּרָם מְנַחֵם.\",3,0],[2,125,3,15,\"גְּדוֹתָיו לְשׁוֹן שָׂפָה גְּבֹהָה.\",1,0],[2,125,3,15,\"כָּל יְמֵי קָצִיר שֶׁיְּמֵי נִיסָן יְמֵי קָצִיר הֵם.\",2,0],[2,125,3,16,\"הַרְחֵק מְאֹד מִמָּקוֹם שֶׁעָמְדוּ שָׁם נִפְסְקוּ.\",1,0],[2,125,3,16,\"מֵאָדָם הָעִיר כָּךְ שְׁמָהּ.\",2,0],[2,125,3,16,\"וְהַיֹּרְדִים אוֹתָם שֶׁהָיוּ יוֹרְדִים מִשָּׁם וּלְמַטָּה תְּחִלָּה.\",3,0],[2,125,3,16,\"תַּמּוּ נִכְרָתוּ עָבְרוּ כְּדֶרֶךְ הֲלִיכָתָן כְּכָל הַנְּחָלִים הַהוֹלְכִים אֶל הַיָּם עַד אֲשֶׁר תַּמּוּ.\",4,0],[2,125,3,17,\"וַיַּעַמְדוּ הַכֹּהֲנִים אֵצֶל שְׂפַת הַיַּרְדֵּן.\",1,0],[2,125,3,17,\"בְּתוֹךְ הַיַּרְדֵּן וְכָל זְמָן שֶׁעָמְדוּ לֹא יָרְדוּ הַמַּיִם הָעֶלְיוֹנִים לְמַטָּה, וּבְתוֹךְ כָּךְ כָּל הָעָם עוֹבְרִים בְּחָרָבָה.\",2,0],[2,125,3,17,\"הָכֵן מְכוּוָּנִים וְנִצָּבִים זֶה כְּנֶגֶד זֶה.\",3,0],[2,125,4,2,\"שְׁנֵים עָשָׂר אֲנָשִׁים הֵם שֶׁנִּזְכָּרִים לְמַעְלָה לִהְיוֹת נְכוֹנִים.\",1,0],[2,125,4,3,\"וְהַעֲבַרְתֶּם אוֹתָם עִמָּכֶם כְּמִצְוַת משֶׁה (דברים כז ד) לִבְנוֹת לָהֶם מִזְבֵּחַ בְּהַר עֵיבָל וְלִכְתּוֹב עֲלֵיהֶם אֶת דִּבְרֵי הַתּוֹרָה, וּבוֹ בַּיּוֹם בָּאוּ אֶל הַר עֵיבָל וּבָנוּ בָּהֶם אֶת הַמִּזְבֵּחַ וְהֶעֱלוּ עוֹלוֹת וּשְׁלָמִים, וְאָכְלוּ וְשָׁתוּ, וְקִפְּלוּ אוֹתָם וּבָאוּ וְלָנוּ בַּגִּלְגָּל.\",1,0],[2,125,4,5,\"עִבְרוּ לִפְנֵי אֲרוֹן וְגוֹ' הִכָּנְסוּ עַתָּה בַּיַּרְדֵּן וְעִבְרוּ עַד לִפְנֵי הַכֹּהֲנִים.\",1,0],[2,125,4,7,\"וְהָיוּ הָאֲבָנִים הָאֵלֶּה בַּגִּלְגָּל לְזִכְרוֹן זֶה.\",1,0],[2,125,4,9,\"וּשְׁתֵּים עֶשְׂרֵה אֲבָנִים אֲחֵרוֹת הֵקִים יְהוֹשֻׁעַ בְּתוֹךְ הַיַּרְדֵּן.\",1,0],[2,125,4,10,\"עַד תֹּם כָּל־הַדָּבָר כְּמוֹ שֶׁשָּׁנִינוּ בְּמַסֶּכֶת סוֹטָה (לד א): עוֹדָם בַּיַּרְדֵּן, אָמַר לָהֶם יְהוֹשֻׁעַ: דְּעוּ לָמָּה אַתֶּם עוֹבְרִים אֶת הַיַּרְדֵּן, עַל מְנָת שֶׁתּוֹרִישׁוּ אֶת כָּל יוֹשְׁבֵי הָאָרֶץ וְכוּ'.\",1,0],[2,125,4,11,\"וַיְהִי כַּאֲשֶׁר תַּם כָּל הָעָם לַעֲבוֹר וַיַּעֲבֹר אֲרוֹן וְגוֹ' לֹא כְּדֶרֶךְ שֶׁעָבְרוּ הָאֲחֵרִים, אֶלָּא כְּמוֹ שֶׁמְּפוֹרָשׁ לְמַטָּה בָּעִנְיָן (להלן פסוק יח): נִתְּקוּ כַּפּוֹת רַגְלֵי הַכֹּהֲנִים לַאֲחוֹרֵיהֶם אֶל הֶחָרָבָה עַל הַשָּׂפָה שֶׁנִּכְנְסוּ בָּהּ, שֶׁהָיוּ עוֹמְדִים אֶצְלָהּ, וְחָזְרוּ הַמַּיִם לַאֲחוֹרֵיהֶם לֵילֵךְ כִּתְמוֹל שִׁלְשׁוֹם; נִמְצָא, אֲרוֹן וְנוֹשְׂאָיו מִצַּד זֶה וְכָל יִשְׂרָאֵל מִצַּד זֶה, נָשָׂא הָאֲרוֹן אֶת נוֹשְׂאָיו וְעָבַר.\",1,0],[2,125,4,11,\"לִפְנֵי הָעָם לְעֵינֵי הָעָם.\",2,0],[2,125,4,16,\"צַוֵּה אֶת הַכֹּהֲנִים כָּאן פֵּירַשׁ הַכָּתוּב אֶת הָאָמוּר לְמַעְלָה, הֵיאָךְ עָבַר אֲרוֹן ה' וְהַכֹּהֲנִים לִפְנֵי הָעָם וְגוֹ'.\",1,0],[2,125,4,16,\"וְיַעֲלוּ מִן הַיַּרְדֵּן 'וְיַעַבְרוּ' אֵין כְּתִיב כָּאן, אֶלָּא 'וְיַעֲלוּ', לָמַדְנוּ שֶׁעַל הַשָּׂפָה שֶׁהָיוּ עוֹמְדִין אֶצְלָהּ עָלוּ, וְאִי אֶפְשָׁר לוֹמַר שֶׁהָיוּ עוֹמְדִין אֵצֶל שְׂפַת הַיַּרְדֵּן שֶׁבַּמַּעֲרָב, שֶׁהֲרֵי נֶאֱמַר לְמַעְלָה (ג טו) נִטְבְּלוּ רַגְלֵי הַכֹּהֲנִים בִּקְצֵה הַמַּיִם, וְשָׁם נֶאֱמַר וַיַּעַמְדוּ הַכֹּהֲנִים וְכָל יִשְׂרָאֵל עוֹבְרִים.\",2,0],[2,125,4,18,\"נִתְּקוּ כַּפּוֹת רַגְלֵי הַכֹּהֲנִים מִן הַמַּיִם אֶל הֶחָרָבָה שֶׁאֶצְלָם, וַיָּשׁוּבוּ הַמַּיִם לִמְקוֹמָם; נִמְצָא, אֲרוֹן מִצַּד זֶה וְיִשְׂרָאֵל מִצַּד זֶה, נָשָׂא אֲרוֹן אֶת נוֹשְׂאָיו וְעָבַר. וְעַל דָּבָר זֶה נֶעֱנַשׁ עוּזָּא (שמואל ב ו ז) כְּשֶׁאָחַז בָּאָרוֹן, נוֹשְׂאָיו נָשָׂא, עַצְמוֹ לֹא כָּל שֶׁכֵּן.\",1,0],[2,125,4,20,\"הֵקִים יְהוֹשֻׁעַ בַּגִּלְגָּל הוּא הַמָּלוֹן אֲשֶׁר לָנוּ בּוֹ הַלַּיְלָה.\",1,0],[2,125,5,1,\"אֲשֶׁר בְּעֵבֶר הַיַּרְדֵּן יָמָּה לְצַד שֶׁעָבְרוּ בְּנֵי יִשְׂרָאֵל, הוּא צַד שֶׁל מַעֲרָבִי, וְעַד עַכְשָׁיו הָיוּ בְּעֵבֶר מִזְרָחִי.\",1,0],[2,125,5,2,\"חַרְבוֹת צֻרִים כְּתַּרְגּוּמוֹ: אִזְמְלָוָן חֲרִיפִין, וְכֵן (תהלים פט מד): אַף תָּשִׁיב צוּר חַרְבּוֹ, כְּשֶׁהַחֲרִיפוּת נֶהְפָּךְ לַצְּדָדִין וְאֵינוֹ חוֹתֵךְ יָפֶה, וְכֵן (ישעיהו נד יז): כָּל כְּלִי יוּצַר עָלַיִךְ.\",1,0],[2,125,5,2,\"שֵׁנִית שֶׁמָּלוּ כְּבָר בְּלֵיל יְצִיאָתָם מִמִּצְרַיִם קָהָל גָּדוֹל יַחַד, וְזוֹ פַּעַם שֵׁנִית, שֶׁכָּל הָאַרְבָּעִים שָׁנָה שֶׁהָיוּ בַּמִּדְבָּר לֹא נָשְׁבָה לָהֶם רוּחַ צְפוֹנִית וְלֹא הָיָה לָהֶם יוֹם נוֹחַ לָמוּל, כְּמוֹ שֶׁשָּׁנִינוּ בִּיבָמוֹת (עא ב). וְרַבּוֹתֵינוּ אָמְרוּ (שם): שֵׁנִית זוֹ פְּרִיעַת מִילָה שֶׁלֹּא נִתְּנָה לְאַבְרָהָם אָבִינוּ.\",2,0],[2,125,5,3,\"גִּבְעַת הָעֲרָלוֹת עַל שֵׁם הַמְּאוֹרָע נִקְרָא, שֶׁנַּעֲשָׂה כְּמִין גִּבְעָה.\",1,0],[2,125,5,4,\"וְזֶה הַדָּבָר עַל יְדֵי דִּבּוּר מָל אוֹתָם, אָמַר לָהֶם: סְבוּרִים אַתֶּם לִירַשׁ אֶת הָאָרֶץ עֲרֵלִים, לֹא כָּךְ נֶאֱמַר לְאַבְרָהָם (בראשית יז ט): וְאַתָּה אֶת־בְּרִיתִי תִשְׁמֹר וְגוֹמֵר (שם שם ח), וְנָתַתִּי לְךָ וּלְזַרְעֲךָ אַחֲרֶיךָ אֵת אֶרֶץ מְגֻרֶיךָ.\",1,0],[2,125,5,4,\"כָּל הָעָם הַיּוֹצֵא לֹא הָיָה אֶחָד מֵהֶם כָּאן, שֶׁכֻּלָּם מֵתוּ, וְהֵם הָיוּ מוּלִים, שֶׁנֶּאֱמַר: כִּי מֻלִים הָיוּ.\",2,0],[2,125,5,5,\"לֹא מָלוּ כְּמוֹ שֶׁפֵּירַשְׁתִּי, שֶׁלֹּא נָשְׁבָה רוּחַ צְפוֹנִית, וְהֵם שֶׁמָּלוּ עַכְשָׁיו.\",1,0],[2,125,5,7,\"וְאֶת בְּנֵיהֶם הֵקִים תַּחְתָּם וְאֶת בְּנֵיהֶם שֶׁהֵקִים תַּחְתֵּיהֶם, הֵם הַיִּלּוֹדִים בַּמִּדְבָּר, אוֹתָם מָל יְהוֹשֻׁעַ.\",1,0],[2,125,5,8,\"וַיֵּשְׁבוּ תַּחְתָּם (תַּרְגּוּם:) בַּאֲתַרְהוֹן, וְלֹא צָרוּ עַל הָעִיר.\",1,0],[2,125,5,8,\"עַד חֲיוֹתָם מִן הַמַּכָּה.\",2,0],[2,125,5,9,\"גַּלּוֹתִי הֲסִירוֹתִי אֶת חֶרְפַּת מִצְרַיִם, שֶׁהָיוּ אוֹמְרִים: רְאוּ כִּי רָעָה נֶגֶד פְּנֵיכֶם, כּוֹכָב אֶחָד יֵשׁ שֶׁשְּׁמוֹ 'רָעָה' וְהוּא סִימָן שֶׁל דָּם, רוֹאִין אָנוּ אוֹתוֹ עֲלֵיכֶם בַּמִּדְבָּר, וְהוּא שֶׁאָמַר משֶׁה בַּמִּדְבָּר (שמות לב יב): לָמָּה יֹאמְרוּ מִצְרַיִם לֵאמֹר בְּרָעָה הוֹצִיאָם, וְהֵם אֵינָם יוֹדְעִים שֶׁהוּא דַּם מִילָה, וּכְשֶׁמָּלוּ בִּימֵי יְהוֹשֻׁעַ וּבָא אוֹתוֹ הַדָּם הוּסְרָה אוֹתָהּ הַחֶרְפָּה שֶׁעֲדַיִין עֵרֶב רַב שֶׁעָלוּ עִמָּהֶם הָיוּ מוֹנִים לָהֶם, כָּךְ דָרַשׁ רַבִּי משֶׁה הַדַּרְשָׁן.\",1,0],[2,125,5,9,\"גַּלּוֹתִי הֲסִירוֹתִי, כְּמוֹ: (תהלים קיט כב), גַּל מֵעָלַי חֶרְפָּה: (בראשית כט י), וַיָּגֶל אֶת הָאֶבֶן.\",2,0],[2,125,5,11,\"מִמָּחֳרַת הַפֶּסַח יוֹם הֲנָפַת הָעוֹמֶר, שֶׁהִקְרִיבוּ עוֹמֶר תְּחִלָּה וּמִז' בַּאֲדָר שֶׁמֵּת משֶׁה, שֶׁפָּסַק הַמָּן, הָיוּ מִסְתַפְּקִין עַד עַכְשָׁיו מִמָּן שֶׁבִּכְלֵיהֶם שֶׁלָּקְטוּ בְּשִׁבְעָה בַּאֲדָר, שֶׁנֶּאֱמַר (שמות טז לה): אֶת הַמָּן אָכְלוּ אַרְבָּעִים שָׁנָה, וַהֲלֹא מ' שָׁנָה חָסֵר שְׁלשִׁים יוֹם, שֶׁהֲרֵי תְּחִלַּת יְרִידַת הַמָּן בְּט\\\"ו בְּאִיָיר, אֱמוֹר מֵעַתָּה, בַּחֲרָרָה שֶׁהוֹצִיאוּ יִשְׂרָאֵל מִמִּצְרַיִם טָעֲמוּ טַעַם מָן.\",1,0],[2,125,5,12,\"וְלֹא הָיָה עוֹד לִבְנֵי יִשְׂרָאֵל מָן לְפִיכָךְ: וַיֹּאכְלוּ מֵעֲבוּר הָאָרֶץ, אִם הָיָה לָהֶם מָן לֹא הָיוּ אוֹכְלִים מִן הַתְּבוּאָה, שֶׁהַמָּן הָיָה נוֹחַ לָהֶם, מָשָׁל אוֹמֵר לַתִּינוֹק: מִפְּנֵי מָה אַתָּה אוֹכֵל פַּת שְׂעוֹרִין, לְפִי שֶׁאֵין לִי פַּת חִטִּין, לְכָךְ נֶאֱמַר: וְלֹא הָיָה עוֹד וְגוֹ'.\",1,0],[2,125,5,13,\"בִּהְיוֹת יְהוֹשֻׁעַ בִּירִיחוֹ מִכָּאן לְעִיבּוּרָהּ שֶׁל עִיר שֶׁהִיא מִן הָעִיר, שֶׁאִי אֶפְשָׁר לוֹמַר בְּתוֹךְ יְרִיחוֹ.\",1,0],[2,125,5,13,\"הֲלָנוּ אַתָּה (תַּרְגּוּם:) הַלְמִסְעַדְנָא אֲתֵיתָא.\",2,0],[2,125,5,14,\"עַתָּה בָאתִי לְעֶזְרָתְךָ, שֶׁאֵין אָדָם יָכוֹל לְהִלָּחֵם עָלֶיהָ וּלְתוֹפְשָׂהּ לְהַפִּיל הַחוֹמָה, אֲבָל בִּימֵי משֶׁה רַבָּךְ בָּאתִי וְלֹא חָפֵץ בִּי, שֶׁנֶּאֱמַר (שמות לג טו): אִם אֵין פָּנֶיךָ הֹלְכִים וְגוֹ'.\",1,0],[2,125,5,15,\"שַׂר צְבָא ה' יִשְׂרָאֵל שֶׁהוּא צָבָא לַה', וּמִיכָאֵל הָיָה, שֶׁנֶּאֱמַר (דניאל י כא): מִיכָאֵל שַׂרְכֶם.\",1,0],[2,125,6,1,\"סֹגֶרֶת וּמְסֻגֶּרֶת כְּתַּרְגּוּמוֹ: אֲחִידָא בְּדָשִׁין דְּפַרְזְלָא, וּמִתַּקְּפָא בְּעִבָּרִין דִּנְחָשׁ.\",1,0],[2,125,6,4,\"הַיּוֹבְלִים אֵילִים.\",1,0],[2,125,6,5,\"בִּמְשֹׁךְ בִּתְקִיעָה אַחֲרוֹנָה, בְּהַאֲרִיךְ הַתּוֹקֵעַ אֶת הַקּוֹל.\",1,0],[2,125,6,5,\"תַּחְתֶּיהָ בִּמְקוֹמָהּ.\",2,0],[2,125,6,9,\"וְהֶחָלוּץ בְּנֵי רְאוּבֵן וּבְנֵי גָד הָיוּ עוֹבְרִים לִפְנֵיהֶם, לְפִי שֶׁהָיוּ בְּנֵי גָד גִּבּוֹרִים וּמַכִּים בִּזְרוֹעַ חֲזָקָה, כְּמוֹ שֶׁנֶּאֱמַר (דברים לג כ): וְטָרַף זְרוֹעַ אַף קָדְקֹד.\",1,0],[2,125,6,13,\"וְהַמְאַסֵּף שֵׁבֶט דָּן הַנּוֹסֵעַ אַחֲרוֹן, וְהוּא מְאַסֵּף אֶת כָּל הַמִּתְעַכְּבִים הָאַחֲרוֹנִים.\",1,0],[2,125,6,15,\"בַּיּוֹם הַשְּׁבִיעִי שַׁבָּת הָיָה.\",1,0],[2,125,6,17,\"וְהָיְתָה הָעִיר חֵרֶם הֶקְדֵּשׁ, כִּי הַיּוֹם שַׁבַּת קֹדֶשׁ, וְרָאוּי לִהְיוֹת קֹדֶשׁ שָׁלָל הַנִּשְׁלָל בּוֹ.\",1,0],[2,125,6,18,\"וַעֲכַרְתֶּם לְשׁוֹן מַיִם עֲכוּרִים.\",1,0],[2,125,6,23,\"וַיָּבֹאוּ הַנְּעָרִים הַמְרַגְּלִים כָּאן הָיוּ צְרִיכִים זֵירוּז וְנַעֲשׂוּ כִּנְעָרִים זְרִיזִים, וּבַלַּיְלָה הָרִאשׁוֹן הָיוּ כְּמַלְאָכִים שֶׁשָּׁמְרוּ עַצְמָן מִן הָעֲבֵירָה עִם רָחָב הַזּוֹנָה, לְכָךְ נִקְרְאוּ שָׁם מַלְאָכִים, וּלְכָךְ נִקְרְאוּ: אֲנָשִׁים, מַלְאָכִים, נְעָרִים.\",1,0],[2,125,6,26,\"בִּבְכֹרוֹ יְיַסְּדֶנָּה וּבִצְעִירוֹ בִּתְחִלַּת יְסוֹד שֶׁיִּבְנֶה בָּהּ יָמוּת בְּנוֹ הַבְּכוֹר, וְיִקְבְּרֶנוּ וְיֵלֵךְ עַד שֶׁיָּמוּת הַצָּעִיר בִּגְמַר הַמְּלָאכָה, הִיא הַצָּבַת הַדְּלָתוֹת.\",1,0],[2,125,7,2,\"עִם בֵּית אָוֶן אֵצֶל בֵּית אָוֶן.\",1,0],[2,125,7,2,\"מִקֶּדֶם לְבֵית אֵל מִמִּזְרַח לְבֵית אֵל.\",2,0],[2,125,7,5,\"עַד הַשְּׁבָרִים (תַּרְגּוּם:) עַד דְּתַבְרוּנוֹן.\",1,0],[2,125,7,7,\"וְלוּ הוֹאַלְנוּ הַלְוַאי נִמְלַכְנוּ לָשֶׁבֶת בְּעֵבֶר הַיַּרְדֵּן מִזְרָחָה, בְּאֶרֶץ סִיחוֹן וְעוֹג שֶׁנִכְבְּשָׁה כְּבָר.\",1,0],[2,125,7,9,\"וּמַה תַּעֲשֶׂה לְשִׁמְךָ הַמְשׁוּתָּף בִּשְׁמֵנוּ, זֶהוּ מִדְרָשׁוֹ. וּפְשׁוּטוֹ וּמַה תַּעֲשֶׂה לְשֵׁם גְּבוּרָתְךָ שֶׁיָּצָא כְּבָר, וְעַתָּה יֹאמְרוּ תָּשַׁשׁ כֹּחוֹ.\",1,0],[2,125,7,10,\"קֻם לָךְ קָם לָךְ כְּתִיב, עָמַד לְךָ מַה שֶּׁהִתְפַּלַּלְתָּ לְפָנַי וְהִזְכַּרְתָּ. דָּבָר אַחֵר: עָמַדְתָּ לְךָ בַּמַּחֲנֶה וְלֹא יָצָאתָ עִמָּהֶם, וַאֲנִי אָמַרְתִּי: (במדבר כז יז), אֲשֶׁר יוֹצִיאֵם וַאֲשֶׁר יְבִיאֵם, (דברים לא כג): כִּי אַתָּה תָּבִיא אֶת בְּנֵי יִשְׂרָאֵל... וְאָנֹכִי אֶהְיֶה עִמְּךָ: (שם ג כח), כִּי הוּא יַעֲבֹר לִפְנֵי הָעָם הַזֶּה וְהוּא יַנְחִיל אוֹתָם אִם תֵּלֵךְ אַתָּה לִפְנֵיהֶם יַצְלִיחוּ, וְאִם לָאו לֹא יַצְלִיחוּ. דָּבָר אַחֵר: קֻם לָךְ בִּשְׁבִילְךָ זֹאת לָהֶם, לֹא אָמַרְתִּי לְךָ לְהַקְדִּישׁ שְׁלַל הָעִיר.\",1,0],[2,125,7,14,\"לַבָּתִּים יֵשׁ בְּמִשְׁפָּחָה אַחַת הַרְבֵּה בָּתֵּי אָבוֹת.\",1,0],[2,125,7,14,\"לַגְּבָרִים לְרָאשֵׁי גּוּלְגּוֹלֶת, כָּל אַנְשֵׁי הַבַּיִת יָבֹאוּ לַגּוֹרָל.\",2,0],[2,125,7,15,\"(תוספת) יִשָּׂרֵף בָּאֵשׁ הָאֹהֶל וְהַמִּטַּלְטְלִין.\",1,0],[2,125,7,15,\"אֹתוֹ וְאֶת כָּל אֲשֶׁר לוֹ כַּדִּין הַמְפוֹרָשׁ לְּמַטָּה (להלן פסוק כה): אוֹתוֹ וְהַבְּהֵמָה בִּסְקִילָה, וְהַזָּקֵף שֶׁהוּא עַל 'בָּאֵשׁ' מוֹכִיחַ שֶׁהוּא נִפְרָד 'מֵאוֹתוֹ', שֶׁכֵּן מָצִינוּ מִקְרָאוֹת שֶׁהַטַּעַם מְחַלְּקָן, כְּמוֹ (דברים יא ל): אַחֲרֵי דֶּרֶךְ מְבוֹא הַשֶּׁמֶשׁ, שֶׁ'אַחֲרֵי' מוּפְלָג 'מִדֶּרֶךְ' עַל יְדֵי הַטַּעַם, וְכֵן פִּתְרוֹנוֹ: הַנִּלְכָּד בַּחֵרֶם יִשָּׂרֵף בָּאֵשׁ, הָרָאוּי לִישָּׂרֵף כְּמוֹ שֶׁמְּפֹרָשׁ לְּמַטָּה.\",2,0],[2,125,7,15,\"אֹתוֹ וְאֶת כָּל אֲשֶׁר לוֹ כַּדִּין הָאָמוּר לְּמַטָּה, וְזֶה מִקְרָא קָצָר, וְדוֹמֶה לוֹ (שמואל ב ה ח): כָּל מַכֵּה יְבֻסִי וְיִגַּע בַּצִּנּוֹר, לֹא פֵּירַשׁ מַה יִּהְיֶה לוֹ. וּבְדִבְרֵי הַיָּמִים (א יא ו) פֵּירַשׁ: יִהְיֶה לְרֹאשׁ, אַף כָּאן לֹא פֵּירַשׁ מַה יִּהְיֶה בְּ'אוֹתוֹ וְכָל אֲשֶׁר לוֹ' וּלְמַטָּה פֵּירַשׁ.\",3,0],[2,125,7,16,\"וַיַּקְרֵב אֶת יִשְׂרָאֵל לִפְנֵי הַחֹשֶׁן, מָקוֹם שֶׁהַשְּׁבָטִים כְּתוּבִים, וּמָסַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא סִימָן, שֶׁהַשֵּׁבֶט שֶׁחָטָא אַבְנוֹ כָּהָה, וְכָהֲתָה אַבְנוֹ שֶׁל יְהוּדָה.\",1,0],[2,125,7,17,\"וַיַּקְרֵב אֶת מִשְׁפַּחַת יְהוּדָה לְגוֹרָל אֶחָד קֵרַב רָאשֵׁי הַמִּשְׁפָּחוֹת, אָדָם אֶחָד מִכָּל הַמִּשְׁפָּחָה וְהִטִּילוּ גּוֹרָל עַל מִי יִפּוֹל, וְאַחַר כָּךְ עַל כָּל בָּתֵּי אָבוֹת שֶׁל אוֹתָהּ מִשְׁפָּחָה, וּבָא אָדָם אֶחָד מִכָּל בֵּית אָב לְגוֹרָל, וְאַחַר כֵּן בָּאוּ כָּל אַנְשֵׁי אוֹתוֹ הַבַּיִת.\",1,0],[2,125,7,19,\"שִׂים־נָא כָבוֹד הִתְחִיל לְהוֹצִיא לַעַז עַל הַגּוֹרָל, אָמַר לוֹ: בְּגוֹרָל אַתָּה בָּא עָלַי, אַתָּה וְאֶלְעָזָר הַכֹּהֵן גְּדוֹלֵי הַדּוֹר אַתֶּם; הַטֵּל הַגּוֹרָל עַל שְׁנֵיכֶם, וְיִפּוֹל עַל הָאֶחָד. אָמַר לוֹ: שִׂים־נָא כָבוֹד, בְּבַקָּשָׁה מִמְּךָ, אַל תּוֹצִיא לַעַז עַל הַגּוֹרָלוֹת שֶׁבּוֹ עֲתִידָה הָאָרֶץ לֵיחָלֵק.\",1,0],[2,125,7,20,\"וַיַּעַן עָכָן רָאָה בְּנֵי יְהוּדָה נֶאֱסָפִים לְמִלְחָמָה, אָמַר: מוּטָב שֶׁאָמוּת אֲנִי לְבַדִּי וְאַל יֵהָרְגוּ כַּמָּה אֲלָפִים מִיִּשְׂרָאֵל.\",1,0],[2,125,7,20,\"וְכָזֹאת וְכָזֹאת עָשִׂיתִי גַּם בַּחֲרָמִים אֲחֵרִים בִּימֵי משֶׁה, שֶׁנֶּאֱמַר (במדבר כא ב): וְהַחֲרַמְתִּי אֶת עָרֵיהֶם.\",2,0],[2,125,7,21,\"וָאֵרֶא בַשָּׁלָל הִתְבּוֹנַנְתִּי בְּמַה שֶּׁכָּתוּב בַּתּוֹרָה (דברים כ יד): וְאָכַלְתָּ [אֶת־שְׁלַל] וְגוֹ'.\",1,0],[2,125,7,21,\"אַדֶּרֶת שִׁנְעָר תַּרְגּוּמוֹ: אִיצְטְלָא (דְּמֵילָתָא) בַּבְלִי, שֶׁכָּל מֶלֶךְ שֶׁלֹּא קָנָה לוֹ פַּלְטֵרִין בְּאֶרֶץ יִשְׂרָאֵל, לֹא נִתְקָרְרָה דַּעְתּוֹ בְּמַלְכוּתוֹ, שֶׁנֶּאֱמַר (ירמיהו ג יט): וְאֶתֵּן־לָךְ אֶרֶץ חֶמְדָּה נַחֲלַת צְבִי צִבְאוֹת גּוֹיִם, וְהָיָה לְמֶלֶךְ בָּבֶל פַּלְטֵרִין בִּירִיחוֹ, וּכְשֶׁהָיָה בָּא לְכָאן לוֹבֵשׁ אוֹתָם.\",2,0],[2,125,7,22,\"וַיָּרֻצוּ הָאֹהֱלָה שֶׁלֹּא יַקְדִּימוּ שֵׁבֶט יְהוּדָה וְיִטְּלוּהָ מִשָּׁם לְהַכְחִישׁ אֶת הַגּוֹרָל.\",1,0],[2,125,7,23,\"וַיַּצִּקֻם (תַּרְגּוּם:) וְאַתִּיכוּנוּן, וְרַבּוֹתֵינוּ אָמְרוּ (סנהדרין מד א): בָּא וַחֲבָטָן לִפְנֵי הַמָּקוֹם, אָמַר לְפָנָיו: רִבּוֹנוֹ שֶׁל עוֹלָם, עַל אֵלּוּ יִפְּלוּ רוּבָּן שֶׁל סַנְהֶדְרִין.\",1,0],[2,125,7,24,\"וְאֶת בָּנָיו וְגוֹ' וְכָל יִשְׂרָאֵל לִרְאוֹת בְּרִדּוּיוֹ וְיִוַּסְּרוּ מִלַּעֲשׂוֹת כָּמוֹהוּ.\",1,0],[2,125,7,24,\"וְאֶת שׁוֹרוֹ וְאֶת חֲמֹרוֹ לְאַבְּדָם, כְּמָה שֶׁנֶּאֱמַר (לעיל פסוק טו): וְהָיָה הַנִּלְכָּד בַּחֵרֶם יִשָּׂרֵף בָּאֵשׁ אֹתוֹ וְכָל אֲשֶׁר לוֹ.\",2,0],[2,125,7,25,\"וַיִּרְגְּמוּ אֹתוֹ... אֶבֶן שֶׁחִלֵּל אֶת הַשַּׁבָּת.\",1,0],[2,125,7,25,\"וַיִּשְׂרְפוּ אֹתָם הָאֹהֶל וְהַמִּטַּלְטְלִין.\",2,0],[2,125,7,25,\"וַיִּסְקְלוּ אֹתָם הַשּׁוֹר וְהַבְּהֵמָה.\",3,0],[2,125,8,2,\"תָּבֹזּוּ לָכֶם וְאַל תַּחֲרִימוּ הַשָּׁלָל עוֹד.\",1,0],[2,125,8,6,\"הַתִּיקֵנוּ אוֹתָם לְשׁוֹן תִּיק, שֶׁנּוֹצִיאֵם מִתִּיק הָעִיר, דישפורי\\\"ר בְּלַעַז (לְהוֹצִיא, לִשְׁלוֹף). וְיֵשׁ לְפוֹתְרוֹ לְשׁוֹן נְתִיקָה, כְּמוֹ (ירמיהו יב ג): הַתִּיקֵם כְּצֹאן לְטִבְחָה.\",1,0],[2,125,8,7,\"וְהוֹרַשְׁתֶּם (תַּרְגּוּם:) וּתְתָרְכוּן.\",1,0],[2,125,8,9,\"מִיָּם לָעַי שֶׁהָעַי מִקֶּדֶם לְבֵית אֵל, וּבֵית אֵל מִיָּם לָעַי.\",1,0],[2,125,8,9,\"וַיָּלֶן יְהוֹשֻׁעַ בְּתוֹךְ הָעָם לִהְיוֹת נָכוֹן בְּהַשְׁכָּמַת הַבֹּקֶר.\",2,0],[2,125,8,10,\"וַיַּעַל הוּא כְּמוֹ שֶׁאָמַר לוֹ הַמָּקוֹם, אִם הוּא עוֹבֵר לִפְנֵיהֶם עוֹבְרִין, וְאִם לָאו אֵין עוֹבְרִין.\",1,0],[2,125,8,12,\"וַיִּקַּח כַּחֲמֵשֶׁת אֲלָפִים אִישׁ אוֹרֵב אַחַר אוֹרֵב, אֶחָד קָרוֹב לָעִיר מֵחֲבֵירוֹ.\",1,0],[2,125,8,13,\"וַיָּשִׂימוּ הָעָם שִׂימָה זוֹ לְשׁוֹן הַזְמָנָה, סָמוּךְ לַחוֹמָה לְהִלָּחֵם, כְּמוֹ שֶׁנֶּאֱמַר בְּבֶן הֲדַד (מלכים א כ ל): שִׂימוּ עַל הָעִיר, וַיָּשִׂימוּ.\",1,0],[2,125,8,13,\"וְאֶת עֲקֵבוֹ וְאֶת אָרְבּוֹ, כְּמוֹ (בראשית כז לו): וַיַּעְקְבֵנִי.\",2,0],[2,125,8,13,\"וַיֵּלֶךְ יְהוֹשֻׁעַ בַּלַּיְלָה הַהוּא בְּתוֹךְ הָעֵמֶק אָמְרוּ רַבּוֹתֵינוּ (סנהדרין מד ב) שֶׁלָּן בְּעוֹמְקָהּ שֶׁל הֲלָכָה.\",3,0],[2,125,8,14,\"לַמּוֹעֵד לִזְמַן הַיּוֹם, שֶׁנּוֹעֲצוּ יַחַד מֵאֶתְמוֹל בְּאוֹתוֹ שָׁעָה נֵצֵא, שֶׁהָיוּ מְנַחֲשִׁים וּמְעוֹנְנִים.\",1,0],[2,125,8,15,\"וַיִּנָּגְעוּ לְשׁוֹן נֶגַע (כְּתַרְגּוּמוֹ:) וְאִתְּבַרוּ, הֶרְאוּ עַצְמָן כְּאִלּוּ הֵם נִגָּפִים לִפְנֵיהֶם.\",1,0],[2,125,8,18,\"נְטֵה בַּכִּידוֹן הוּא הָיָה סִימָן לָאוֹרֵב לָצֵאת מִן הַמַּאֲרָב, בִּרְאוֹתוֹ הַכִּידוֹן נָטוּי עַל הָעִיר. כִּידוֹן שפיד\\\"ו בְּלַעַז (רוֹמַח, חַנִית).\",1,0],[2,125,8,20,\"יָדַיִם כֹּחַ.\",1,0],[2,125,8,20,\"וְהָעָם הַנָּס הַמִּדְבָּר יִשְׂרָאֵל שֶׁנָּסוּ אֶל הַמִּדְבָּר כְּמוֹ שֶׁאָמַר לְמַעְלָה, נֶהְפַּךְ לְהִלָּחֵם אֶל הָרוֹדֵף.\",2,0],[2,125,8,22,\"וְאֵלֶּה יָצְאוּ מִן הָעִיר הָאוֹרֵב שֶׁהִצִּית אֶת הָעִיר.\",1,0],[2,125,8,30,\"אָז יִבְנֶה וְגוֹ' פָּרָשָׁה זוֹ כְּתוּבָה מוּקְדָּם וּמְאוּחָר, שֶׁמִּיּוֹם שֶׁעָבְרוּ אֶת הַיַּרְדֵּן עָשָׂה כֵּן.\",1,0],[2,125,8,32,\"וַיִּכְתָּב־שָׁם עַל הָאֲבָנִים הֵן הֵנָּה הָאֲבָנִים הָאֲמוּרִים לְמַעְלָה, לְאַחַר מַעֲשֶׂה זֶה קִפְּלוּ (קלפו) הַסִּיד מֵעֲלֵיהֶם וֶהֱבִיאוּם הַגִּלְגָּל.\",1,0],[2,125,8,33,\"לְבָרֵךְ אֶת הָעָם יִשְׂרָאֵל בָּרִאשׁוֹנָה לְהַקְדִּים בְּרָכוֹת לִקְלָלוֹת: בָּרוּךְ הָאִישׁ אֲשֶׁר לֹא יַעֲשֶׂה פֶסֶל וּמַסֵּכָה.\",1,0],[2,125,9,4,\"וַיַּעֲשׂוּ גַּם הֵמָּה בְּעָרְמָה כְּמוֹ שֶׁעָשׂוּ בְּנֵי יַעֲקֹב בְּעָרְמָה (בראשית לד) וּבַחֲמוֹר אֲבִי שְׁכֶם שֶׁהָיָה חִוִּי, וְיוֹשְׁבֵי גִּבְעוֹן מִן הַחִוִּי הָיוּ, כְּמוֹ שֶׁאָמוּר בָּעִנְיָן.\",1,0],[2,125,9,4,\"וַיִּצְטַיָּרוּ עָשׂוּ עַצְמָם כְּהוֹלְכִים בִּשְׁלִיחוּת, לְשׁוֹן (ירמיהו מט יד): וְצִיר בַּגּוֹיִם שֻׁלַּח, וְכָל תֵּיבָה שֶׁתְּחִלַּת יְסוֹדָהּ צָדִ\\\"י, כְּשֶׁהִיא מִתְפַּעֶלֶת ל' מִתְפַּעֵל, אוֹ נִתְפַּעֵל, בָּאָה טֵי\\\"ת בְּתוֹכָהּ וְחוֹלֶקֶת אֶת אוֹתִיוֹת שָׁרְשֵׁי הַתֵּיבָה, כְּמוֹ (בראשית מד טז): מַה נִּצְטַדָּק, מִגִּזְרַת צֶדֶק, שֶׁאוֹמֵר נִּצְטַדַּק, וְכֵן (דניאל ד ל): גִּשְׁמֵהּ יִצְטַבַּע, מִגִּזְרַת צֶבַע.\",2,0],[2,125,9,4,\"שַׂקִּים בָּלִים שֶׁיִּהְיוּ נִרְאִים כְּבָאִים מֵאֶרֶץ רְחוֹקָה.\",3,0],[2,125,9,4,\"וּמְצֹרָרִים לְשׁוֹן מְבוּקָּעִים, לְשׁוֹן אֲרַמִּי: צִירְיָא דְּחִיטֵּי דְּמָצְרִי זִיקֵי.\",4,0],[2,125,9,5,\"נִקֻּדִים ארשי\\\"ץ בְּלַעַז (שְׂרוּפִים כֶּעֵין צְנִימִים), לְשׁוֹן מוֹקֵד, וְכֵן תִּרְגְּמוֹ יוֹנָתָן: כִּסְנִין.\",1,0],[2,125,9,7,\"אוּלַי בְּקִרְבִּי אַתָּה יוֹשֵׁב שֶׁמָּא מִיּוֹשְׁבֵי הָאָרֶץ אַתֶּם.\",1,0],[2,125,9,12,\"הִצְטַיַּדְנוּ לְשׁוֹן צֵדָה, כְּשֶׁהוֹצֵאנוּהוּ לְצֵדָה לַדֶּרֶךְ.\",1,0],[2,125,9,14,\"וַיִּקְחוּ הָאֲנָשִׁים מִצֵּידָם קִבְּלוּ דִּבְרֵיהֶם, שֶׁצָּדוּם בְּפִיהֶם, לְשׁוֹן (שמות כא יג): וַאֲשֶׁר לֹא צָדָה.\",1,0],[2,125,10,12,\"אָז יְדַבֵּר אָמַר שִׁירָה תַּחַת הַשֶּׁמֶשׁ, לְפִי שֶׁאָמַר לַשֶּׁמֶשׁ דּוֹם, דּוֹם מִלּוֹמַר שִׁירָה, וְכָל זְמַן שֶׁהוּא דּוֹמֵם, עוֹמֵד וְאֵינוֹ מְהַלֵּךְ, שֶׁבְּכָל עֵת הִילּוּכוֹ הוּא אוֹמֵר שִׁירָה. וּפְשׁוּטוֹ שֶׁל מִקְרָא: דּוֹם לְשׁוֹן הַמְתָּנָה, כְּמוֹ (שמואל א יד ט): אִם כֹּה יֹאמְרוּ אֵלֵינוּ דֹּמּוּ, וְכֵן (תהלים לז ז): דֹּם לַה'.\",1,0],[2,125,10,12,\"וְיָרֵחַ בְּעֵמֶק אַיָּלוֹן אוֹתוֹ פַּעַם הָיָה הַיָּרֵחַ עוֹמֵד כְּנֶגֶד עֵמֶק אַיָּלוֹן, וְהוּא רָחוֹק מִגִּבְעוֹן, שֶׁהֲרֵי גִּבְעוֹן בִּגְבוּל בִּנְיָמִין וְאַיָּלוֹן בִּגְבוּל דָּן.\",2,0],[2,125,10,13,\"הֲלֹא הִיא כְתוּבָה דָּבָר זֶה נִכְתַּב בַּתּוֹרָה, שֶׁאָמַר לוֹ יַעֲקֹב לְיוֹסֵף (בראשית מח יט): וְזַרְעוֹ (שֶׁל אֶפְרַיִם) יִהְיֶה מְלֹא הַגוֹיִם, אֵימָתַי, בְּיוֹם שֶׁעָמְדָה חַמָּה לִיהוֹשֻׁעַ, נִתְמַלֵּא כָּל הָעוֹלָם שִׁמְעוֹ שֶׁל יְהוֹשֻׁעַ, וַיַּעֲמֹד הַשֶּׁמֶשׁ בַּחֲצִי הַשָּׁמַיִם וְלֹא אָץ לָבֹא כְּיוֹם תָּמִים.\",1,0],[2,125,10,18,\"גֹּלּוּ גַּלְגְּלוּ אֲבָנִים אֶל פִּי הַמְּעָרָה.\",1,0],[2,125,10,21,\"לֹא חָרַץ לִבְנֵי יִשְׂרָאֵל הֲרֵי זֶה מִקְרָא קָצָר, לֹא חָרַץ הַחוֹרֵץ לְאִישׁ מִבְּנֵי יִשְׂרָאֵל אֶת לְשׁוֹנוֹ.\",1,0],[2,125,10,21,\"חָרַץ לְשׁוֹן דִּבּוּר הַלָּשׁוֹן, וְכֵן (שמות יא ז): לֹא יֶחֱרַץ כֶּלֶב לְשׁוֹנוֹ, וְכֵן (שמואל ב ה כד): אָז תֶּחֱרָץ, דְּדָוִד תִּקְרָא, תִּצְעַק קוֹל תְּשׁוּאוֹת הַמִּלְחָמָה.\",2,0],[2,125,10,40,\"וְהָאֲשֵׁדוֹת מָקוֹם שֶׁמֵּי הַגְּבָעוֹת שׁוֹפְכִים.\",1,0],[2,125,10,41,\"מִקָּדֵשׁ בַּרְנֵע וְעַד עַזָּה מִצַּד דְּרוֹמִית שֶׁל אֶרֶץ יִשְׂרָאֵל הוּא, מִן הַמִּזְרָח לַמַּעֲרָב, וְלֹא הִסְפִּיק לִכְבּוֹשׁ כָּל הַמֶּצֶר וְנִשְׁאַר מֵעַזָּה עַד הַיָּם, הוּא שֶׁאָמַר לְּמַטָּה: זֹאת הָאָרֶץ הַנִּשְׁאֶרֶת הָעַזָּתִי וְהָאַשְׁדּוֹדִי וְגוֹ'.\",1,0],[2,125,11,2,\"נֶגֶב כִּנְרוֹת דְּרוֹם גִּינוֹסָר.\",1,0],[2,125,11,2,\"וּבְנָפוֹת דּוֹר פִּלְכֵי דּוֹר, קונטדו\\\"ש בְּלַעַז (חֶלְקֵי אָרֶץ, מְחוֹזוֹת).\",2,0],[2,125,11,2,\"מִיָּם מַעֲרָבָה.\",3,0],[2,125,11,8,\"מִשְׂרְפוֹת מַיִם תִּרְגֵּם יוֹנָתָן: חֲרִיצֵי יַמָּא, שֶׁעוֹשִׂין חֲרִיצִין וּמֵי הַיָּם יוֹצְאִין לְתוֹכָן, וְנִשְׂרָפִין מֵחוֹם הַשֶּׁמֶשׁ וְנַעֲשִׂים מֶלַח.\",1,0],[2,125,11,13,\"הָעֹמְדוֹת עַל תִּלָּם שֶׁלֹּא נֶהֱרְסָה חוֹמָתָם כְּמוֹ יְרִיחוֹ שֶׁנָּפְלָה חוֹמָתָהּ, וְכֵן הָעַי שֶׁנֶּאֱמַר בָּהּ (לעיל ח כח): וַיְשִׂימֶהָ תֵּל עוֹלָם שְׁמָמָה.\",1,0],[2,125,11,13,\"זוּלָתִי אֶת־חָצוֹר לְבַדָּהּ בַּמָּסוֹרֶת שְׂרָפָה משֶׁה צִוָּה לוֹ וּמָסַר לוֹ כֵּן. (בראשית רבה וישלח):\",2,0],[2,125,11,17,\"הָהָר הֶחָלָק (תַּרְגּוּם:) טוּרָא שְׁעִיעַ, מַחֲלִיק, הָהָר הֶחָלָק עַד בַּעַל גָּד בַּמֶּצֶר הַמִּזְרָחִי, וְלֹא הִסְפִּיק לִכְבּוֹשׁ בְּחַיָּיו אֶת כָּל הַמֶּצֶר עַד הַצָּפוֹן.\",1,0],[2,125,11,17,\"בַּעַל גָּד מֵישַׁר גָּד.\",2,0],[2,125,11,18,\"יָמִים רַבִּים עָשָׂה יְהוֹשֻׁעַ בִּגְנוּתוֹ סִפֵּר הַכָּתוּב, שֶׁהָיָה מִתְכַּוֵּון לִדְחוֹת אֶת כִּבּוּשׁ הָאָרֶץ כְּדֵי לְהַאֲרִיךְ יָמָיו, לְפִי שֶׁנֶּאֱמַר (לעיל א י): וְאַתָּה תַּנְחִלֶנָּה אוֹתָם, בְּמִדְרַשׁ תַּנְחוּמָא.\",1,0],[2,125,12,1,\"אֲשֶׁר הִכּוּ בְּנֵי יִשְׂרָאֵל בִּימֵי משֶׁה.\",1,0],[2,125,12,2,\"וְעַד יַבֹּק הַנַּחַל שֶׁשָּׁם גְּבוּל אֶרֶץ בְּנֵי עַמּוֹן, סוֹף מֶצֶר אֶרֶץ בְּנֵי עַמּוֹן, וּמִשָּׁם וָהָלְאָה הָיוּ בְּנֵי עַמּוֹן מוֹשְׁלִים.\",1,0],[2,125,12,5,\"וַחֲצִי הַגִּלְעָד גְּבוּל סִיחוֹן שָׁם הָיָה מֶצֶר מֶמְשֶׁלֶת סִיחוֹן, כְּשֶׁאָמַרְנוּ לְמַעְלָה, שֶׁחֲצִי הַגִּלְעָד הָיָה שֶׁלּוֹ, וְזֶה חֲצִי הַשֵּׁנִי שֶׁל עוֹג.\",1,0],[2,125,12,23,\"לְנָפַת דּוֹר (תַּרְגּוּם:) לְפַּלְכֵי דּוֹר.\",1,0],[2,125,13,1,\"וְהָאָרֶץ נִשְׁאֲרָה הַרְבֵּה מְאֹד מִמַּה שֶּׁאָמַרְתִּי לְאַבְרָהָם נִשְׁאֲרָה לְרִשְׁתָּהּ, שֶׁלֹּא נִכְבְּשָׁה.\",1,0],[2,125,13,2,\"גְּלִילוֹת מרקא\\\"ש בְּלַעַז (אֵזוֹרֵי הַגְבוּל, הַסְפַר).\",1,0],[2,125,13,3,\"מִן הַשִּׁיחוֹר הוּא נִילוּס, הוּא נַחַל מִצְרַיִם, הוּא סָמוּךְ לִתְחוּם מִקְצוֹעַ דְּרוֹמִית מַעֲרָבִית שֶׁל אֶרֶץ יִשְׂרָאֵל, כְּמוֹ שֶׁאָמַר בְּ'אֵלֶּה מַסְעֵי' (במדבר לד ה), וְלָמַדְנוּ כָּאן שֶׁלֹּא כָּבַשׁ יְהוֹשֻׁעַ בְּחַיָּיו כָּל מֶצֶר הַדְּרוֹמִי אֶלָּא מִמִּדְבַּר צִין, הוּא הָהָר הֶחָלָק הָעוֹלֶה שֵׂעִירָה עַד הַנִּילוּס, הוּא תְּחוּם עַזָּה הָאָמוּר לְמַעְלָה, מִקָּדֵשׁ בַּרְנֵע עַד עַזָּה.\",1,0],[2,125,13,3,\"וְעַד גְּבוּל עֶקְרוֹן צָפוֹנָה הָעֶקְרוֹנִי יוֹשֵׁב עַל הַיָּם וּמִתְפַּשֵּׁט לְצַד הַצָּפוֹן יוֹתֵר מִן הָאֲחֵרִים.\",2,0],[2,125,13,3,\"לַכְּנַעֲנִי תֵּחָשֵׁב מֵאֶרֶץ הַכְּנַעֲנִי שֶׁנָּתַתִּי לְאַבְרָהָם הוּא.\",3,0],[2,125,13,3,\"חֲמֵשֶׁת סַרְנֵי פְּלִשְׁתִּים וְגוֹ' הִיא סוֹף גְּמַר הַמֶּצֶר עַד הַיָּם הַגָּדוֹל שֶׁבַּמַּעֲרָב.\",4,0],[2,125,13,3,\"הָעַזָּתִי וְהָאַשְׁדּוֹדִי הָאֶשְׁקְלוֹנִי וְגוֹ' שִׁשָּׁה סְרָנִים הוּא מוֹנֶה, וּמִתְּחִלָתָן קְרָאָן 'חֲמֵשֶׁת'. אָמַר רַבִּי יוֹנָתָן (חולין ס ב), אִידוֹנְרִיקֵי שֶׁלָּהֶם חַמִשָּׁה; הַחֲשׁוּבִים חֲמִשָּׁה הָיוּ, שֶׁהָעַוִּים אֵינוֹ מוֹנֶה מִן הַסְּרָנִים הַחֲשׁוּבִים. וְעוֹד יֵשׁ לְפָרֵשׁ, חֲמֵשֶׁת סַרְנֵי פְּלִשְׁתִּים: הָעַזָּתִי, וְהָאַשְׁדּוֹדִי, הָאֶשְׁקְלוֹנִי, הַגִּתִּי וְהָעֶקְרוֹנִי הֵם חֲמִשָּׁה, וְעוֹד נִשְׁאַר לִכְבּוֹשׁ אֶרֶץ הָעַוִּים שֶׁאֵינָם מִן הַפְּלִשְׁתִּים.\",5,0],[2,125,13,4,\"מִתֵּימָן כָּל אֶרֶץ הַכְּנַעֲנִי פָּסוּק רִאשׁוֹן מָנָה מִצַּד הַדְּרוֹמִי מִן הַמִּזְרָח לַמַּעֲרָב, וְזֶה מוֹנֶה אֶת רוֹחַב אוֹתוֹ הַמִּקְצוֹעַ הַנּוֹתָר לִיכָּבֵשׁ, כַּמָּה הוּא מִן הַדָּרוֹם לַצָּפוֹן.\",1,0],[2,125,13,4,\"מִתֵּימָן כָּל אֶרֶץ הַכְּנַעֲנִי מִתֵּימָן זוֹ מְעָרָה לַצִּידוֹנִים, עַד אֲפֵקָה עַד הָאֱמוֹרִי.\",2,0],[2,125,13,5,\"וְהָאָרֶץ הַגִּבְלִי וְכָל הַלְּבָנוֹן מִזְרַח הַשֶּׁמֶשׁ וּבַמֶּצֶר מִזְרָחִי נִשְׁאָר לִכְבּוֹשׁ בְּמִקְצוֹעַ הַצָּפוֹן כָּל הַלְּבָנוֹן, מִבַּעַל גָּד עַד סוֹף הַמֶּצֶר, וּבָרוֹחַב מִן הַמִּזְרָח לַמַּעֲרָב עַד לְבוֹא חֲמָת, זֶהוּ כָּל מֶצֶר הַצְּפוֹנִי שֶׁלְּבוֹא חֲמָת בְּמִקְצוֹעַ צְפוֹנִית מַעֲרָבִית בְּ'אֵלֶּה מַסְעֵי' (במדבר לד ח).\",1,0],[2,125,13,6,\"אָנֹכִי אוֹרִישֵׁם אַחֲרֵי מוֹתְךָ.\",1,0],[2,125,13,6,\"הַפִּלֶהָ לְיִשְׂרָאֵל בְּנַחֲלָה וְיִכְבּוֹשׁ לְאַחַר זְמָן כָּל שֵׁבֶט וְשֵׁבֶט מַה שֶּׁנָּפַל בְּגוֹרָלוֹ.\",2,0],[2,125,13,8,\"עִמּוֹ הָראוּבֵנִי וְהַגָּדִי עִם חֲצִי הָרִאשׁוֹן שֶׁל מְנַשֶּׁה, הָראוּבֵנִי וְהַגָּדִי לָקְחוּ נַחֲלָתָם.\",1,0],[2,125,13,9,\"מֵעֲרוֹעֵר אֲשֶׁר עַל שְׂפַת וְגוֹ' מוֹנֶה וְהוֹלֵךְ כָּל אֶרֶץ עֵבֶר הַיַּרְדֵּן, וְאַחַר כָּךְ מְפָרֵשׁ גְּבוּל כָּל שֵׁבֶט וְשֵׁבֶט וְיִתֵּן משֶׁה לְמַטֶּה פְּלוֹנִי וּפְלוֹנִי.\",1,0],[2,125,13,12,\"מִיֶּתֶר הָרְפָאִים שֶׁהָרַג כְּדָרְלָעֹמֶר וְהַמְּלָכִים אֲשֶׁר אִתּוֹ, כְּמָה שֶׁנֶּאֱמַר (בראשית יד ה): וַיַּכּוּ אֶת רְפָאִים בְּעַשְׁתְּרוֹת קַרְנַיִם.\",1,0],[2,125,13,19,\"בְּהַר הָעֵמֶק (תַּרְגּוּם:) בְּטוּרָא דְמֵישָׁרָא.\",1,0],[2,125,13,25,\"וַחֲצִי אֶרֶץ בְּנֵי עַמּוֹן חֲצִי מַה שֶּׁכָּבְשׁוּ מֵאֶרֶץ בְּנֵי עַמּוֹן וּמִסִּיחוֹן.\",1,0],[2,125,13,27,\"הַיַּרְדֵּן וּגְבֻל יַרְדְּנָא וּתְחוּמֶיהָ הֶעָרִים עַל שְׂפָתוֹ.\",1,0],[2,125,13,28,\"הֶעָרִים וְחַצְרֵיהֶם הֶעָרִים הַמּוּקָּפוֹת חוֹמָה.\",1,0],[2,125,13,28,\"וְחַצְרֵיהֶם עָרֵי הַפְּרָזִי בְּלֹא חוֹמָה.\",2,0],[2,125,14,1,\"אֲשֶׁר נָחֲלוּ אוֹתָם אֲשֶׁר הִנְחִילוּ אוֹתָם.\",1,0],[2,125,14,4,\"כִּי הָיוּ בְּנֵי יוֹסֵף שְׁנֵי מַטּוֹת תַּחַת שֵׁבֶט לֵוִי.\",1,0],[2,125,14,7,\"כַּאֲשֶׁר עִם לְבָבִי וְלֹא כַּאֲשֶׁר עִם פִּי, שֶׁהַמְרַגְּלִים הָיוּ בְּעֵצָה אַחַת, וְיָּרֵא כָּלֵב לוֹמַר לָהֶם שֶׁלֹּא יֹאמַר כְּמוֹתָם, וּכְשֶׁבָּא הִכְחִישָׁם, וְזֶהוּ שֶׁנֶּאֱמַר שָׁם (במדבר יד כד): עֵקֶב הָיְתָה רוּחַ אַחֶרֶת עִמּוֹ, שֶׁהָיָה אוֹמֵר לָהֶם אֶחָד בַּפֶּה וְאֶחָד בַּלֵּב.\",1,0],[2,125,14,10,\"זֶה אַרְבָּעִים וְחָמֵשׁ שָׁנָה לָמַדְנוּ שֶׁשָּׁהוּ בְּכִיבּוּשׁ הָאָרֶץ שֶׁבַע שָׁנִים, שֶׁהֲרֵי בַּשָּׁנָה הַשֵּׁנִית שָׁלַח משֶׁה הַמְרַגְּלִים, נִשְׁאֲרוּ שְׁלשִׁים וּשְׁמֹנֶה שֶׁהָלְכוּ בַּמִּדְבָּר וְשֶׁבַע שֶׁכָּבְשׁוּ, הֲרֵי אַרְבָּעִים וְחָמֵשׁ.\",1,0],[2,125,14,15,\"הָאָדָם הַגָּדוֹל בָּעֲנָקִים הוּא אֲבִיהֶם שֶׁל אֲחִימָן שֵׁשַׁי וְתַלְמַי, אַרְבַּע הָיָה שְׁמוֹ. דָּבָר אַחֵר: עַל שֵׁם הָאָב וּשְׁלשָׁה בָּנִים, שֶׁכֵּן קוֹרֵא אוֹתָם (שם יג כב): יְלִידֵי הָעֲנָק.\",1,0],[2,125,14,15,\"וְהָאָרֶץ שָׁקְטָה מִמִּלְחָמָה מוּסָב לָעִנְיָן הָרִאשׁוֹן, לְאַחַר שֶׁבַע שֶׁכָּבְשׁוּ סְבִיבוֹתֵיהֶם, נִכְנְעוּ הָאֱמוֹרִיִים וְלֹא נֶאֶסְפוּ עוֹד לְמִלְחָמָה עֲלֵיהֶם, לְכָךְ הִתְחִילוּ לַעֲסוֹק בְּחִילּוּק הָאָרֶץ. וּמִדְרַשׁ אַגָּדָה: הָאָדָם הַגָּדוֹל בָּעֲנָקִים הוּא אַבְרָהָם אָבִינוּ, הוּא שֶׁגָּרַם לָהֶם שֶׁהָאָרֶץ שָׁקְטָה מִמִּלְחָמָה אַרְבָּעִים שָׁנָה שֶׁנִּתְעַכְּבוּ בַּמִּדְבָּר, בְּשָׂכָר שֶׁכִּבְּדוּ אֶת הַזָּקֵן בְּקִרְיַת אַרְבַּע, שֶׁאָמְרוּ לוֹ (בראשית כג ו): נְשִׂיא אֱלֹהִים אַתָּה בְּתוֹכֵנוּ.\",2,0],[2,125,15,1,\"אֶל גְּבוּל אֱדוֹם סָמוּךְ לְמֶצֶר אֱדוֹם.\",1,0],[2,125,15,1,\"נֶגְבָּה בִּתְחוּם מֶצֶר דְּרוֹמִי שֶׁל אֶרֶץ יִשְׂרָאֵל.\",2,0],[2,125,15,1,\"מִקְצֵה תֵימָן בְּסוֹף כָּל הַמֶּצֶר.\",3,0],[2,125,15,2,\"וַיְהִי לָהֶם גְּבוּל מֶצֶר דְּרוֹמִי שֶׁל יְהוּדָה.\",1,0],[2,125,15,2,\"מִקְצֵה יַם הַמֶּלַח הוּא מִקְצוֹעַ דְּרוֹמִית מִזְרָחִית שֶׁל אֶרֶץ יִשְׂרָאֵל בְּ'אֵלֶּה מַסְעֵי' (במדבר לד ג).\",2,0],[2,125,15,2,\"מִן הַלָּשֹׁן שֶׁל יָם.\",3,0],[2,125,15,3,\"וְיָצָא אֶל מִנֶּגֶב לְמַעֲלֵה עַקְרַבִּים וְאֵינוֹ אוֹמֵר 'וְיָצָא וְנָסַב וְתָאַר', אֶלָּא בְּמָקוֹם שֶׁחוּט שֶׁל גְּבוּל בּוֹלֵט אֶל הַחוּץ, אוֹ כּוֹנֵס לְצַד פְּנִים שֶׁאֵינוֹ הוֹלֵךְ מְכֻוָּון, וְכָאן הוּא בּוֹלֵט אֶל הַחוּץ וּבָא מִנֶּגֶב לְמַעֲלֵה עַקְרַבִּים בַּדָּרוֹם שֶׁל מַעֲלֵה עַקְרַבִּים, נִמְצָא שֶׁמַּעֲלֵה עַקְרַבִּים לִפְנִים מִן הַחוּט, וְעָבַר וּבָא לוֹ אֶל הַמַּעֲרָב.\",1,0],[2,125,15,3,\"צִנָה לְצִן, וְכָל תֵּיבָה שֶׁצְּרִיכָה לַמֶ\\\"ד בִּתְחִלָּתָהּ הִטִּיל לָהּ הֵ\\\"א בְּסוֹפָהּ.\",2,0],[2,125,15,3,\"וְעָלָה כָּל מַה שֶּׁהוּא עוֹלֶה מִן הַמִּזְרָח, לְצַד יְרוּשָׁלַיִם הוּא עוֹלֶה, וּמִיְּרוּשָׁלַיִם וָהָלְאָה הוּא יוֹרֵד. כָּאן לָמַדְנוּ שֶׁיְּרוּשָׁלַיִם גְּבוֹהָה מִכָּל אֶרֶץ יִשְׂרָאֵל. וִירוּשָׁלַיִם אֵינָהּ נִזְכֶּרֶת בְּמֶצֶר זֶה, שֶׁבְּמֶצֶר צְפוֹנִית שֶׁל יְהוּדָה הָיְתָה, כְּמוֹ שֶׁאָמוּר בָּעִנְיָן.\",3,0],[2,125,15,3,\"וְעָלָה מִנֶּגֶב לְקָדֵשׁ בַּרְנֵעַ הַחוּט הוֹלֵךְ לִדְרוֹמָהּ שֶׁל קָדֵשׁ בַּרְנֵעַ, נִמְצֵאת קָדֵשׁ לִפְנִים מִן הַחוּט.\",4,0],[2,125,15,3,\"וְעָבַר חֶצְרוֹן לְצַד הַמַּעֲרָב הוּא מוֹנֶה וְהוֹלֵךְ, עַד: וְהָיוּ תֹּצְאֹתָיו הַיָּמָּה.\",5,0],[2,125,15,4,\"תֹּצְאוֹת סוֹפוֹ שֶׁל מֶצֶר אֶל הַיָּם הַגָּדוֹל, שֶׁהוּא מֶצֶר מַעֲרָבִי לְכָל אֶרֶץ יִשְׂרָאֵל. נִמְצָא גְּבוּל יְהוּדָה מַחֲזִיק כָּל אָרְכָּהּ שֶׁל אֶרֶץ יִשְׂרָאֵל מִן הַמִּזְרָח לַמַּעֲרָב, וְעוֹמֵד בִּדְרוֹמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל.\",1,0],[2,125,15,5,\"וּגְבוּל קֵדְמָה חוּט הַמָּתוּחַ לְמֶצֶר מִזְרָחִי שֶׁל יְהוּדָה.\",1,0],[2,125,15,5,\"יַם הַמֶּלַח שֶׁהוּא מִקְצוֹעַ דְּרוֹמִית מִזְרָחִית לָאָרֶץ בְּ'אֵלֶּה מַסְעֵי' (במדבר שם).\",2,0],[2,125,15,5,\"עַד קְצֵה הַיַּרְדֵּן רָחְבּוֹ שֶׁל גְּבוּל יְהוּדָה אֵינוֹ אֶלָּא כְּנֶגֶד יָם הַמֶּלַח, עַד מָקוֹם שֶׁהַיַּרְדֵּן נוֹפֵל בְּיַם הַמֶּלַח, שֶׁהַיַּרְדֵּן אַף הוּא בְּמֶצֶר מִזְרָח שֶׁל אֶרֶץ כְּנָעַן, כְּמוֹ שֶׁנֶּאֱמַר בְּ'אֵלֶּה מַסְעֵי' בְּמֶצֶר מִזְרָחִי (שם לד יב): וְיָרַד הַגְּבוּל הַיַּרְדֵּנָה וְהָיוּ תּוֹצְאֹתָיו יָם הַמֶּלַח, שֶׁהוּא בְּמִקְצוֹעַ.\",3,0],[2,125,15,5,\"וּגְבוּל לִפְאַת צָפוֹנָה חוּט מֶצֶר הַמָּתוּחַ לְמֶצֶר צָפוֹן מִן הַמִּזְרָח לַמַּעֲרָב, מִלְּשׁוֹן יַם הַמֶּלַח מִמָּקוֹם שֶׁהַיַּרְדֵּן נוֹפֵל בּוֹ, שֶׁאָמַרְנוּ שֶׁשָּׁם כָּלָה רוֹחַב גְּבוּל מֶצֶר הַמִּזְרָחִי וְעָלָה לְצַד הַמַּעֲרָב בֵּית חָגְלָה, וְעָבַר הַחוּט מִצָּפוֹן לְבֵית הָעֲרָבָה, נִמְצָא בֵּית הָעֲרָבָה בְּתוֹךְ גְּבוּל יְהוּדָה לִפְנִים מִן הַחוּט.\",4,0],[2,125,15,6,\"וְעָלָה הַגְּבוּל אֶבֶן בֹּהַן כָּל מַה שֶּׁהוֹלֵךְ עַד יְרוּשָׁלַיִם הוּא עוֹלֶה.\",1,0],[2,125,15,7,\"וְעָלָה הַגְּבוּל דְּבִרָה מֵעֵמֶק עָכוֹר שֶׁהָיָה עֵמֶק עָכוֹר בֵּין אֶבֶן בֹּהַן לַדְּבִיר.\",1,0],[2,125,15,7,\"וְצָפוֹנָה פֹּנֶה אֶל הַגִּלְגָּל וּכְשֶׁמַּגִּיעַ כְּנֶגֶד הַגִּלְגָּל, מַרְחִיב הַגְּבוּל וְיוֹצֵא חוּט הַמֶּצֶר לְצַד הַצָּפוֹן אֶל הַגִּלְגָּל, אֲשֶׁר הוּא נוֹכַח מַעֲלֵה אֲדֻמִּים אֲשֶׁר הַמַּעֲלֶה בִּדְרוֹם הַנַּחַל, נִמְצָא הַנַּחַל חוּץ מִן הַחוּט שֶׁלֹּא בִּגְבוּל יְהוּדָה.\",2,0],[2,125,15,7,\"מִנֶּגֶב לַנַּחַל עֵמֶק וּמִדְרוֹן הָיָה בְּלֹא מַיִם.\",3,0],[2,125,15,7,\"אֶל עֵין רֹגֵל מַעְיַן הַכּוֹבְסִים, תִּרְגֵּם יוֹנָתָן: עֵין קַצְרָא, וְקוֹרֵא אֶת הַכּוֹבֵס רוֹגֵל, עַל שֵׁם שֶׁבּוֹעֵט אֶת בִּגְדֵי הַצֶּמֶר בְּרַגְלָיו, פולוש בְּלַעַ\\\"ז (דוֹרֵךְ־בְרַגְלָיו).\",4,0],[2,125,15,8,\"וְעָלָה וְגו' גֵּי בֶן הִנֹּם עוֹדֶנּוּ עוֹלֶה מְעַט עַד עֵין עֵיטָם וּמִשָּׁם וָהָלְאָה הוּא יוֹרֵד, וְזֶהוּ שֶׁאָמְרוּ רַבּוֹתֵינוּ ז\\\"ל בִּשְׁחִיטַת קָדָשִׁים (זבחים נד ב): סָבוּר לְמִבְנָיְיהוּ בְּעֵין עֵיטָם שֶׁהוּא גָּבוֹהַּ מִירוּשָׁלַיִם מְעַט.\",1,0],[2,125,15,8,\"אֶל כֶּתֶף הַיְבוּסִי מִנֶּגֶב נִמְצֵאת יְרוּשָׁלַיִם חוּץ מִן הַחוּט וְאֵינָהּ בִּגְבוּל יְהוּדָה אֶלָּא בִּגְבוּל בִּנְיָמִין שֶׁהוּא בִּצְפוֹנוֹ שֶׁל יְהוּדָה.\",2,0],[2,125,15,9,\"וְתָאַר לְשׁוֹן וְנָסַב בְּעוֹגֶל, כְּמוֹ (ישעיהו מד יג): וּבַמְּחוּגָה יְתָאֳרֵהוּ, וְיוֹנָתָן תִּירְגֵּם אֶת כֻּלָּם 'וְיִסְחֹר'.\",1,0],[2,125,15,9,\"וְיָצָא אֶל עָרֵי הַר עֶפְרוֹן הַחוּט יוֹצֵא לְצַד הַצָּפוֹן, וְהַגְּבוּל הִרְחִיב עַד עָרֵי הַר עֶפְרוֹן.\",2,0],[2,125,15,9,\"וְתָאַר הַגְּבוּל בַּעֲלָה אֵין זֶה לְצַד הַמַּעֲרָב, אֶלָּא הַבְּלִיטָה לְצַד צָפוֹן.\",3,0],[2,125,15,10,\"וְנָסַב הַגְּבוּל מִבַּעֲלָה יָמָּה עַכְשָׁיו חוֹזֵר לְמִנְיָנוֹ הָרִאשׁוֹן, מִן הַמִּזְרָח לַמַּעֲרָב.\",1,0],[2,125,15,10,\"אֶל כֶּתֶף הַר יְעָרִים מִצָּפוֹנָה שֶׁהָיָה הַחוּט בִּצְפוֹנָהּ שֶׁל הַר יְעָרִים, נִמְצָא הַר יְעָרִים בְּתוֹךְ גְּבוּל יְהוּדָה לִפְנִים מִן הַחוּט.\",2,0],[2,125,15,11,\"וְהָיוּ תֹּצְאוֹת הַגְּבוּל סוֹף הַמֶּצֶר.\",1,0],[2,125,15,11,\"יָמָּה אֶל יָם הַגָּדוֹל שֶׁהוּא מִצַּד מַעֲרָבִי.\",2,0],[2,125,15,13,\"אֶל פִּי ה' לִיהוֹשֻׁעַ כְּמָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לִיהוֹשֻׁעַ.\",1,0],[2,125,15,14,\"וַיֹרֶשׁ מִשָּׁם כָּלֵב לְאַחַר מִיתַת יְהוֹשֻׁעַ, כִּי עֲדַיִין בִּימֵי יְהוֹשֻׁעַ לֹא נִלְכְּדָה חֶבְרוֹן, כְּמָה שֶׁנֶּאֱמַר בְּסֵפֶר שׁוֹפְטִים (א כ), וְלֹא נִכְתְּבָה כָּאן אֶלָּא מִפְּנֵי הַחֲלֻקָּה.\",1,0],[2,125,15,15,\"קִרְיַת סֵפֶר רַבּוֹתֵינוּ אָמְרוּ (תמורה טז א): אֵלּוּ הֲלָכוֹת שֶׁנִּשְׁתַּכְּחוּ בִּימֵי אֶבְלוֹ שֶׁל משֶׁה שֶׁהֶחֱזִיר עָתְנִיאֵל בֵּן קְנַז מִפִּלְפּוּלוֹ.\",1,0],[2,125,15,17,\"אֲחִי כָלֵב מֵאִמּוֹ.\",1,0],[2,125,15,18,\"וַתִּצְנַח (תַּרְגּוּם:) וְאִתְרְכִינַת, הִטְּתָה עַצְמָהּ לִיפּוֹל בְּרַגְלָיו.\",1,0],[2,125,15,19,\"תְּנָה לִי בְרָכָה פַּרְנָסָה.\",1,0],[2,125,15,19,\"אֶרֶץ הַנֶּגֶב חֲרֵבָה, כְּמוֹ (בראשית ח יג): חָרְבוּ פְּנֵי הָאֲדָמָה, וּמְתַרְגֵּם: נְגִיבוּ, שייקא בְּלַעַ\\\"ז (יְבֵשָׁה), בַּיִת מְנֻגָּב מִכָּל טוּב, אָדָם שֶׁאֵין בּוֹ אֶלָּא תּוֹרָה.\",2,0],[2,125,15,19,\"נְתַתָּנִי נָתַתָּ לִי, כְּמוֹ (שם לז ד): דַּבְּרוֹ לְשָׁלוֹם—דַּבֵּר אֵלָיו; (ירמיהו י כ): בָּנַי יְצָאֻנִי—יָצְאוּ מִמֶּנִּי; (מלכים א יט כא): בִשְּׁלָם־בִּשֵּׁל לָהֶם.\",3,0],[2,125,15,19,\"גֻּלּוֹת מַעְיָנוֹת.\",4,0],[2,125,15,21,\"וַיִּהְיוּ הֶעָרִים מִקְצֵה לְמַטֵּה בְּנֵי יְהוּדָה בִּגְבוּל מַטֵּה יְהוּדָה, הוּא שֶׁאָמְרוּ רַבּוֹתֵינוּ (גיטין ז א): לֹא מָנָה יְהוֹשֻׁעַ אֶלָּא עֲיָירוֹת הָעוֹמְדוֹת עַל הַגְּבוּלִים.\",1,0],[2,125,15,32,\"כָּל עָרִים עֶשְׂרִים וָתֵשַׁע וּבִפְרָטָן אַתָּה מוֹצֵא שְׁלשִׁים וּשְׁמוֹנֶה, אֶלָּא אֵלֶּה הַיְּתֵרוֹת נָטְלוּ בְּנֵי שִׁמְעוֹן מֵחֶבֶל בְּנֵי יְהוּדָה, וְנִזְכָּרוֹת הֵם בְּנַחֲלַת שִׁמְעוֹן: בְּאֵר שֶׁבַע, וּמוֹלָדָה, חֲצַר שׁוּעָל, וָעָצֶם, וְאֶלְתּוֹלַד, וְחָרְמָה, וְצִקְלַג, וְעַיִן וְרִמּוֹן הֲרֵי תֵּשַׁע הַיְּתֵרוֹת הַמְּנוּיוֹת כָּאן.\",1,0],[2,125,15,36,\"עָרִים אַרְבַּע עֶשְׂרֵה וּבִפְרָטָן חֲמֵשׁ עֶשְׂרֵה; אוֹמֵר אֲנִי, תַּפּוּחַ וְהָעֵינָם אֶחָד הוּא, וְזֶה פֵּירוּשׁוֹ: תַּפּוּחַ וְהָעַיִן שֶׁלּוֹ, הוּא עֵין תַּפּוּחַ הָאָמוּר בְּנַחֲלַת מְנַשֶּׁה: אֶל יוֹשְׁבֵי עֵין תַּפּוּחַ.\",1,0],[2,125,15,47,\"וְהַיָּם הַגָּדוֹל וּגְבוּל נִסִּין שֶׁבַּיָּם שֶׁקּוֹרִין אישלי\\\"ש בְּלַעַ\\\"ז (אִיֵי הַיָם).\",1,0],[2,125,15,63,\"לֹא יָכְלוּ בְּנֵי יְהוּדָה לְהוֹרִישָׁם שָׁנִינוּ בְּסִפְרֵי: רַבִּי יְהוֹשֻׁעַ בֶּן קָרְחָה אוֹמֵר: יְכוֹלִין הָיוּ, אֶלָּא שֶׁלֹּא הָיוּ רַשָּׁאִין מֵחֲמַת הַשְּׁבוּעָה שֶׁנִּשְׁבַּע אַבְרָהָם לַאֲבִימֶלֶךְ, וִיבוּסִי זֶה לֹא עַל שֵׁם הָאוּמָּה הָיָה, אֶלָּא מִגְדַּל דָּוִד שֶׁהָיָה בִּירוּשָׁלַיִם וּשְׁמוֹ יְבוּס, וּבְנֵי אוֹתוֹ מָחוֹז מִפְּלִשְׁתִּים הָיוּ, וּכְשֶׁכָּבְשׁוּ בְּנֵי יְהוּדָה אֶת יְרוּשָׁלַיִם לֹא הוֹרִישׁוּ אֶת בְּנֵי אוֹתוֹ מָחוֹז.\",1,0],[2,125,16,1,\"וַיֵּצֵא הַגּוֹרָל לִבְנֵי יוֹסֵף בְּמֶצֶר צְפוֹנִי שֶׁל גְּמַר כִּיבּוּשׁוֹ שֶׁל יְהוֹשֻׁעַ נָפַל לָהֶם הַגּוֹרָל, כְּמוֹ שֶׁכָּתוּב לְּמַטָּה: וּבְנֵי יוֹסֵף יַעַמְדוּ עַל גְּבוּלָם מִצָּפוֹן, וְהַרְבֵּה מִן הָאָרֶץ הָיָה בֵּין בְּנֵי יְהוּדָה וּבֵין בְּנֵי יוֹסֵף, שֶׁנָּטְלוּ שְׁאָר הַשְּׁבָטִים אַחֲרֵיהֶם (רָצָה לוֹמַר, בֵּינֵיהֶם), כְּמוֹ שֶׁמָּצִינוּ בְּשֵׁבֶט בִּנְיָמִין (לקמן יח יא): וַיֵּצֵא גְּבוּל גּוֹרָלָם בֵּין בְּנֵי יְהוּדָה וּבֵין בְּנֵי יוֹסֵף.\",1,0],[2,125,16,1,\"מִיַּרְדֵּן יְרִיחוֹ לְמֵי יְרִיחוֹ מִזְרָחָה הִתְחִיל הַגְּבוּל לַמִּזְרָח.\",2,0],[2,125,16,1,\"הַמִּדְבָּר עוֹלֶה מִירִיחוֹ אֶל הַמִּדְבָּר עוֹלֶה הַגְּבוּל מִירִיחוֹ וּבָא לוֹ לְצַד מַעֲרָב לְבֵית אֵל.\",3,0],[2,125,16,5,\"מִזְרָחָה עַטְרוֹת אַדָּר לְמִזְרָח מַתְחִיל מֵעַטְרוֹת אַדָּר, וּמִשָּׁם רוֹחַב תְּחוּמוֹ עַד בֵּית חוֹרוֹן הֲרֵי רָחְבּוֹ.\",1,0],[2,125,16,6,\"וְיָצָא הַגְּבוּל הַיָּמָּה אָרְכּוֹ הָיְתָה לְצַד הַמַּעֲרָב אֶל הַמִּכְמְתָת, מִצָּפוֹן שֶׁל הַמִּכְמְתָת הוֹלֵךְ הַחוּט.\",1,0],[2,125,16,6,\"וְנָסַב הַגְּבוּל מִתְפַּשֵּׁט רוֹחַב הַתְּחוּם לְצַד צָפוֹן, וְהַחוּט יוֹצֵא בִּבְלִיטָתוֹ בְּמִזְרָחָהּ שֶׁל תַּאֲנַת שִׁילֹה.\",2,0],[2,125,16,6,\"וְעָבַר אוֹתוֹ וְעָבַר הַגְּבוּל אֶת תַּאֲנַת שִׁילֹה, וְעָבַר הַחוּט מִמִּזְרָח שֶׁל יָנוֹחַ כָּל זֶה בְּלִיטַת הָרוֹחַב, עַד 'וְיָצָא הַיַּרְדֵּן', וְשָׁם עִיר וּשְׁמָהּ תַּפּוּחַ, וּמִשָּׁם יִסּוֹב הַחוּט לְמִדַּת אוֹרֶךְ הַגְּבוּל יָמָּה לְנַחַל קָנָה.\",3,0],[2,125,16,9,\"וְהֶעָרִים הַמִּבְדָּלוֹת וְגַם זֶה עוֹד מִנַּחֲלַת אֶפְרַיִם, עָרִים הָיוּ לָהֶם מוּבְדָּלוֹת מִתְּחוּמוֹ וּמֻבְלָעוֹת בְּתוֹךְ נַחֲלַת בְּנֵי מְנַשֶּׁה.\",1,0],[2,125,17,1,\"לְמָכִיר בְּכוֹר מְנַשֶּׁה לְפִיכָךְ נָטַל תְּחִלָּה בִּימֵי משֶׁה בְּעֵבֶר הַיַּרְדֵּן, וַיְהִי לוֹ הַגִּלְעָד וְהַבָּשָׁן.\",1,0],[2,125,17,5,\"וַיִּפְּלוּ חֶבְלֵי מְנַשֶּׁה עֲשָׂרָה שִׁשָּׁה לְשִׁשָּׁה בָּתֵּי אָבוֹת הַמְּנוּיִים לְמַעְלָה, וְאַרְבַּע לִבְנוֹת צְלָפְחָד, לֹא שֶׁתְּהֵא כָּל אַחַת בֵּית אָב לְעַצְמָהּ אֶלָּא שֶׁנָּטְלוּ אַרְבָּעָה חֲלָקִים, חֵלֶק שֶׁל אֲבִיהֶם שֶׁהָיָה מִיּוֹצְאֵי מִצְרַיִם, וּלְפִי מִנְיַן הַיּוֹצְאִים מִמִּצְרַיִם נִתְחַלְּקָה הָאָרֶץ וְחִלְּקוּ עִם אֶחָיו בְּנִכְסֵי חֵפֶר אָבִיו, שֶׁהָיָה גַּם הוּא מִיּוֹצְאֵי מִצְרַיִם וְשֶׁהָיָה בְּכוֹר וְנָטַל שְׁנֵי חֲלָקִים, וְעוֹד הָיָה לָהֶם חֵלֶק אֲחִי אֲבִיהֶם שֶׁמֵּת בַּמִּדְבָּר בְּלֹא בָּנִים, וְנָטְלוּ נַחֲלָה בְּחֶלְקוֹ, כָּךְ אָמְרוּ רַבּוֹתֵינוּ בְּבָּבָא בַּתְרָא (קיח א), וְלֹא הוּזְקַק הַכָּתוּב לְהַשְׁמִיעֵנוּ מִנְיַן חֶלְקֵי הַבָּנוֹת, אֶלָּא לְלַמֵּד שֶׁנָּטְלוּ חֵלֶק בְּכוֹרָה וּלְהוֹדִיעַ שֶׁאֶרֶץ יִשְׂרָאֵל חֵלֶק יְרֻשָּׁה לָהֶם מֻחְזֶקֶת מֵאֲבוֹתֵיהֶם, שֶׁאִילּוּלֵי כֵּן אֵין הַבְּכוֹר נוֹטֵל בָּרָאוּי כְּבַמּוּחְזָק.\",1,0],[2,125,17,6,\"וְאֶרֶץ הַגִּלְעָד שֶׁבְּעֵבֶר הַיַּרְדֵּן הָיְתָה לִבְנֵי מְנַשֶּׁה הַנּוֹתָרִים.\",1,0],[2,125,17,8,\"אֶרֶץ תַּפּוּחַ הַכְּפָרִים וְהַחֲצֵרִים, וְתַפּוּחַ עַצְמָהּ הָעִיר הָיְתָה לִבְנֵי אֶפְרַיִם.\",1,0],[2,125,17,8,\"אֶל גְּבוּל מְנַשֶּׁה עַל מֶצֶר מְנַשֶּׁה לְסוֹף גְּבוּלוֹ.\",2,0],[2,125,17,9,\"עָרִים הָאֵלֶּה מִתַּפּוּחַ עַד נַחַל קָנָה לְאֶפְרַיִם הָיוּ בְּתוֹךְ עָרֵי מְנַשֶּׁה.\",1,0],[2,125,17,10,\"נֶגְבָּה לְאֶפְרַיִם אֶפְרַיִם נָטַל חֶלְקוֹ מִדָּרוֹם לְצַד הָאָרֶץ שֶׁבֵּין בְּנֵי יְהוּדָה לִשְׁאָר הַשְּׁבָטִים.\",1,0],[2,125,17,10,\"וְצָפוֹנָה לִמְנַשֶּׁה מְנַשֶּׁה נָטַל לְצַד צָפוֹן.\",2,0],[2,125,17,11,\"שְׁלשֶׁת הַנָּפֶת (תַּרְגּוּם:) תְּלָתָא פְּלָכִין, וּ'שְׁלשֶׁת הַנָּפֶת' הַנִּזְכָּרִים כָּאן שֶׁל דֹּאר וְשֶׁל עֵין דּוֹר הָיוּ, כְּמוֹ שֶׁאָמוּר לְמַעְלָה בְּסֵפֶר זֶה (יב כג): מֶלֶךְ דּוֹר לְנָפַת דּוֹר, וּבְפָסוּק אַחֵר אוֹמֵר (לעיל יא ב): לְנָפֶת דֹּאר מִיָּם, וְכָאן כָּךְ הוּא אוֹמֵר: וְאֶת יוֹשְׁבֵי דֹּאר וּבְנוֹתֶיהָ שְׁלשֶׁת הַנָּפֶת שֶׁהָיוּ לָהּ.\",1,0],[2,125,17,12,\"וַיּוֹאֶל וַיֹּאבֶה.\",1,0],[2,125,17,14,\"וַיְדַבְּרוּ בְּנֵי יוֹסֵף שֵׁבֶט מְנַשֶּׁה.\",1,0],[2,125,17,14,\"עַד אֲשֶׁר־עַד־כֹּה בֵּרְכַנִי ה' עַד אֲשֶׁר רָאִיתָ שֶׁנִּתְרַבָּה מִנְיָנוֹ מִמִּנְיָן רִאשׁוֹן לְמִנְיָן שֵׁנִי עֶשְׂרִים אֶלֶף וַחֲמֵשׁ מֵאוֹת כְּמִנְיַן 'כֹּה' בְּגִימְטַרְיָה, בְּמִנְיָן רִאשׁוֹן אַתָּה מוֹצֵא בִּמְנַשֶּׁה בְּסֵפֶר בְּמִדְבָּר (א לה): שְׁנַיִם וּשְׁלשִׁים אֶלֶף וּמָאתַיִם, וּבְפִינְחָס (שם כו לד): שְׁנַיִם וַחֲמִשִּׁים אֶלֶף וּשְׂבַע מֵאוֹת. דָּבָר אַחֵר: עַד אֲשֶׁר עַד כֹּה בְּרָכָה נֶאֶמְרָה לְאַבְרָהָם (בראשית טו ה): כֹּה יִהְיֶה זַרְעֲךָ, נִתְקַיְּימָה בִּי, וּלְפִי פְּשׁוּטוֹ: עַד אֲשֶׁר עַד כֹּה עַד אֲשֶׁר כָּךְ, כַּאֲשֶׁר אַתָּה רוֹאֶה.\",2,0],[2,125,17,15,\"אִם עַם רַב אַתָּה יֵשׁ בְּךָ כֹּחַ לִכְרוֹת יְעָרוֹת וּלְפַנּוֹתָהּ, כְּעֵין שֶׁקּוֹרִין אישרטי\\\"ר בְּלַעַז וְשָׁם תִּבְנֶה עָרִים.\",1,0],[2,125,17,15,\"וּבֵרֵאתָ לְשׁוֹן כְּרִיתָה, כְּמוֹ (יחזקאל כג מז): וּבָרֵא אוֹתְהֶן בְּחַרְבוֹתָם, אישרטרא\\\"ש בְּלַעַז.\",2,0],[2,125,17,15,\"אָץ דָּחוּק.\",3,0],[2,125,17,16,\"לֹא יִמָּצֵא לָנוּ הָהָר כִּי אָץ הוּא לָנוּ כַּאֲשֶׁר אָמַרְתָּ.\",1,0],[2,125,17,16,\"לֹא יִמָּצֵא לֹא יַסְפִּיק.\",2,0],[2,125,17,16,\"וְרֶכֶב בַּרְזֶל וּמַה שֶּׁאַתָּה אוֹמֵר לַעֲלוֹת הַיַּעְרָה וְלִכְבּוֹשׁ בְּאֶרֶץ הַפְּרִיזִּי וְהָרְפָאִים, עַם חָזָק הוּא אוֹתוֹ כְּנַעֲנִי וְרֶכֶב בַּרְזֶל לוֹ, וְאַל תִּתְמַהּ אִם קְרָאוֹ לַפְּרִיזִי וּרְפָאִים כְּנַעֲנִי, כִּי כֻּלַּם בְּנֵי כְּנַעַן הָיוּ.\",3,0],[2,125,17,18,\"כִּי הַר יִהְיֶה־לָּךְ אוֹתוֹ שֶׁאָמַרְתִּי לְךָ עֲלֵה לְךָ הַיַּעֲרָה.\",1,0],[2,125,17,18,\"כִּי יַעַר הוּא וּבֵרֵאתוֹ כִּי יַעַר הוּא וְאֵינוֹ רָאוּי אֶלָּא לְעַם רַב וִיבָרְאוּהוּ וִיפַנּוּהוּ.\",2,0],[2,125,17,18,\"וּבֵרֵאתוֹ אַתָּה שֶׁאַתָּה עַם רַב.\",3,0],[2,125,17,18,\"וְהָיָה לְךָ תֹּצְאֹתָיו כִּי תוֹרִיש אֶת הַכְּנַעֲנִי עַל יְדֵי שֶׁאַתָּה עַם רַב.\",4,0],[2,125,17,18,\"כִּי רֶכֶב בַּרְזֶל לוֹ וְאֵין אֶחָד מִשְּׁאָר הַשְּׁבָטִים כְּדַאי לְהִלָּחֵם בּוֹ.\",5,0],[2,125,17,18,\"כִּי חָזָק הוּא וְאַתָּה יֵשׁ בְּךָ הַיְכוֹלֶת וְתּוֹרִישֶׁנּוּ, וְרַבּוֹתֵינוּ פֵּירְשׁוּ (בבא בתרא קיח א): עֲלֵה לְךָ הַיַּעְרָה, הַחְבִּיאוּ עַצְמְכֶם בַּיְעָרוֹת שֶׁלֹּא תִּשְׁלוֹט בָּכֶם עַיִן הָרָע.\",6,0],[2,125,18,1,\"וַיַשְׁכִּינוּ שָׁם אֶת־אֹהֶל מוֹעֵד שֶׁעָשׂוּ בַּמִּדְבָּר, וְלֹא הָיָה שָׁם תִּקְרָה, אֶלָּא בַּיִת שֶׁל אֲבָנִים מִלְּמַטָּן וִירִיעוֹת מִלְמַעְלָן, כָּךְ שָׁנִינוּ בִּשְׁחִיטַת קָדָשִׁים (זבחים כד ב).\",1,0],[2,125,18,1,\"וְהָאָרֶץ נִכְבְּשָׁה לִפְנֵיהֶם מִשֶּׁנִּקְבַּע הַמִּשְׁכָּן, הָיְתָה הָאָרֶץ נוֹחָה לִיכָּבֵשׁ לִפְנֵיהֶם.\",2,0],[2,125,18,2,\"שִׁבְעָה שְׁבָטִים שֶׁכְּבָר קִבְּלוּ נַחֲלָתָן רְאוּבֵן וְגָד וַחֲצִי שֵׁבֶט מְנַשֶּׁה בִּימֵי משֶׁה בְּעֵבֶר הַיַּרְדֵּן, וּבְאֶרֶץ כְּנַעַן כְּבָר נָפַל גּוֹרָל לִיהוּדָה וּלְאֶפְרַיִם וְלַחֲצִי שֵׁבֶט מְנַשֶּׁה, הֲרֵי חֲמִשָּׁה שְׁבָטִים.\",1,0],[2,125,18,3,\"מִתְרַפִּים מִתְרַשְּׁלִין.\",1,0],[2,125,18,4,\"לַשָּׁבֶט לְכָל שֵׁבֶט מִן הַשִּׁבְעָה.\",1,0],[2,125,18,4,\"לְפִי נַחֲלָתָם לְשִׁבְעָה חֲלָקִים וְלֹא בְּשָׁוֶה, אֶלָּא לְפִי הַשְּׁבָטִים הָרְאוּיִין לְחֶלְקָם, לָרַב לְפִי רֻבּוֹ וְלַמְּעַט לְפִי מִיעוּטוֹ, כְּמָה שֶׁנֶּאֱמַר (במדבר כו נד): לָרַב תַּרְבֶּה נַחֲלָתוֹ וְלַמְּעַט תַּמְעִיט נַחֲלָתוֹ וְגוֹמֵר.\",2,0],[2,125,18,5,\"וְהִתְחַלְּקוּ אֹתָהּ לְשִׁבְעָה חֲלָקִים אוֹתָהּ שֶׁנִכְבְּשָׁה כְּבָר וְהָעֲתִידָה לִיכָּבֵשׁ.\",1,0],[2,125,18,5,\"יְהוּדָה יַעֲמֹד עַל גְּבוּלוֹ מִנֶּגֶב אֶרֶץ יִשְׂרָאֵל שֶׁשָּׁם נָפַל לוֹ גּוֹרָל כָּל הַמֶּצֶר הַדְּרוֹמִי.\",2,0],[2,125,18,5,\"וּבֵית יוֹסֵף וְגוֹ' מִצָּפוֹן צְפוֹנִי לְמַה שֶּׁנִּכְבַּשׁ כְּבָר, וְעוֹד יֵשׁ הַרְבֵּה לִכְבּוֹשׁ צַד הַמֶּצֶר מִבַּעַל גַּד עַד לְבוֹא חֲמָת, שֶׁהוּא אֵצֶל הֹר הָהָר בְּמֶצֶר צְפוֹנִי, וְהַשִּׁבְעָה שְׁבָטִים יְחַלְּקוּ אוֹתָהּ שֶׁבֵּין יְהוּדָה לְיוֹסֵף, וְאוֹתָהּ הָעוֹמֶדֶת לִיכָּבֵשׁ.\",3,0],[2,125,18,6,\"וְיָרִיתִי וְהִשְׁלַכְתִּי, כְּמוֹ (שמות טו ד): יָרָה בַיָּם.\",1,0],[2,125,18,12,\"וַיְהִי לָהֶם הַגְּבוּל לִפְאַת צָפוֹנָה וַיְהִי מֶצֶר גְּבוּל הַצְּפוֹנִי שֶׁלָּהֶם מִן הַיַּרְדֵּן, שֶׁבַּמִּזְרָח מַתְחִיל הַמֶּצֶר, וְעָלָה אֶל כֶּתֶף יְרִיחוֹ מִצָּפוֹן, וְעָלָה מִשָּׁם אֶל הַמַּעֲרָב אֶל עֵבֶר יְרִיחוֹ, וּמוֹשֵׁךְ הַחוּט בִּצְפוֹנָהּ שֶׁל יְרִיחוֹ, נִמְצֵאת יְרִיחוֹ לִפְנִים מִן הַחוּט בְּחֵלֶק בִּנְיָמִין.\",1,0],[2,125,18,12,\"מִדְבָּרָהּ בֵּית אָוֶן לַמִּדְבַּר שֶׁל בֵּית אָוֶן.\",2,0],[2,125,18,13,\"וְעָבַר מִשָּׁם לְצַד הַמַּעֲרָב.\",1,0],[2,125,18,13,\"לוּזָה אֶל כֶּתֶף לוּזָה נֶגְבָּה הִיא בֵּית אֵל שֶׁקְּרָאָהּ יַעֲקֹב (בראשית כח יט), וְלֹא זוֹ הִיא בֵּית אֵל שֶׁאֵצֶל הָעַי, שֶׁהֲרֵי אוֹמֵר בִּגְבוּל יוֹסֵף (לעיל טז ב): וְיָצָא מִבֵּית אֵל לוּזָה, לָמַדְנוּ שֶׁשְּׁנַיִם הָיוּ, וְלוּז לֹא בְּחֵלֶק בִּנְיָמִין הָיְתָה, שֶׁהֲרֵי חוּט הַמֶּצֶר מִלּוּז וְלִפְנִים הוּא, כְּמוֹ שֶׁהוּא אוֹמֵר (פסוק יג): אֶל כֶּתֶף לוּזָה נֶגְבָּה, הַחוּט הוֹלֵךְ בִּדְרוֹמָהּ שֶׁל לוּז, נִמְצֵאת לוּז מִן הַחוּט וְלַחוּץ, בְּנַחֲלַת בְּנֵי יוֹסֵף, וּבֵית אֵל הָיְתָה בְּחֵלֶק בִּנְיָמִין, כְּמוֹ שֶׁכָּתוּב לְמַטָּה בָּעִנְיָן (להלן פסוק כב).\",2,0],[2,125,18,14,\"וְתָאַר הַגְּבוּל וְנָסַב לִפְאַת יָם נֶגְבָּה בְּעַטְרוֹת אַדָּר כָּלָה אוֹרֶךְ הַצְּפוֹנִי מִן הַמִּזְרָח לַמַּעֲרָב, וּמִשָּׁם נָסַב הַחוּט לִגְבוּל הַמַּעֲרָב שֶׁל בִּנְיָמִין לֵילֵךְ נֶגְבָּה מִן הַצָּפוֹן לַדָּרוֹם, חוּט הַמַּעֲרָבִית מִן הָהָר אֲשֶׁר עַל פְּנֵי בֵּית חוֹרוֹן נֶגְבָּה מִן הָהָר אֲשֶׁר בִּדְרוֹמָהּ שֶׁל בֵּית חוֹרוֹן, מִשָּׁם הָיָה מַתְחִיל מִקְצוֹעַ מַעֲרָבִית צְפוֹנִית שֶׁל בִּנְיָמִין וּבָא לוֹ הַחוּט מִצָּפוֹן לְדָרוֹם.\",1,0],[2,125,18,14,\"וְהָיוּ תֹצְאֹתָיו מִקְצוֹעַ מַעֲרָבִית דְּרוֹמִית שֶׁלּוֹ אֶל קִרְיַת יְעָרִים שֶׁל יְהוּדָה, נִמְצָא רוֹחַב גְּבוּל בִּנְיָמִין נוֹטֵל כָּל רוֹחַב הָאָרֶץ שֶׁבֵּין יְהוּדָה לְאֶפְרַיִם, גְּבוּל דְּרוֹמִי שֶׁלּוֹ עִם גְּבוּל צְפוֹנִי שֶׁל יְהוּדָה, וְשָׁם הָיְתָה יְרוּשָׁלַיִם כְּמוֹ שֶׁאָמוּר לְמַטָּה בָּעִנְיָן, לְפִיכָךְ הָיָה לִשְׁנֵי הַשְּׁבָטִים חֵלֶק בָּהּ, וּגְבוּל צְפוֹנִי שֶׁל בִּנְיָמִין וּדְרוֹמִי שֶׁל אֶפְרַיִם נוֹגְעִין זֶה בָּזֶה, וְשָׁם הָיְתָה שִׁילֹה בְּחֵלֶק אֶפְרַיִם, כְּמָה שֶׁנֶּאֱמַר (תהלים עח ס סז): וַיִּטֹּשׁ מִשְׁכַּן שִׁילֹה וְגוֹמֵר וַיִּמְאַס בְּאֹהֶל יוֹסֵף וּבְשֵׁבֶט אֶפְרַיִם לֹא בָחָר, וְאַף לְבִנְיָמִין הָיָה בּוֹ חֵלֶק, וְכֵן שָׁנִינוּ בִּשְׁחִיטַת קָדָשִׁים (זבחים כד ב): בְּג' מְקוֹמוֹת שָׁרְתָה לָהֶם שְׁכִינָה לְיִשְׂרָאֵל, בְּשִׁילֹה וְנוֹב וּבֵית הָעוֹלָמִים, וּבְכֻלָּן לֹא שָׁרְתָה אֶלָּא בְּחֶלְקוֹ שֶׁל בִּנְיָמִין.\",2,0],[2,125,18,14,\"זֹאת פְּאַת יָם רוּחַ מַעֲרָבִי מֵעַטְרוֹת אַדָּר עַד קִרְיַת יְעָרִים.\",3,0],[2,125,18,15,\"וּפְאַת נֶגְבָּה מִצַּד דְּרוֹמִי לְבִנְיָמִין וְהוּא צְפוֹנִי שֶׁל יְהוּדָה, וְכָל הַתְּחוּמִין הַמְּנוּיִין כָּאן נִמְנוּ בִּצְפוֹנָהּ שֶׁל יְהוּדָה, וְכָל מָקוֹם שֶׁכָּתוּב כָּאן 'וְיָרַד', כָּתוּב בִּיהוּדָה 'וְעָלָה', לְפִי שֶׁכָּאן הוּא מוֹנֶה מִן הַמַּעֲרָב לַמִּזְרָח, וְשָׁם מוֹנֶה מִן הַמִּזְרָח לַמַּעֲרָב.\",1,0],[2,125,18,15,\"וְיָצָא הַגְּבוּל יָמָּה אֶל יָם אֶחָד וְלֹא יָדַעְתִּי אֵיזֶה יָם הוּא.\",2,0],[2,125,18,19,\"אֶל לְשׁוֹן יַם הַמֶּלַח צָפוֹנָה בִּצְפוֹנוֹ שֶׁל לָשׁוֹן, נִמְצָא כָּל הַלָּשׁוֹן בְּחֶלְקוֹ שֶׁל יְהוּדָה.\",1,0],[2,125,18,19,\"אֶל קְצֵה הַיַּרְדֵּן מָקוֹם שֶׁהַיַּרְדֵּן נוֹפֵל בְּיַם הַמֶּלַח, וְהוּא נִמְנֶה מִקְצוֹעַ מִזְרָחִית צְפוֹנִית לִיהוּדָה, וְכָאן הוּא מוֹנֶה מִקְצוֹעַ דְּרוֹמִית מִזְרָחִית לְבִנְיָמִין.\",2,0],[2,125,18,20,\"וְהַיַּרְדֵּן יִגְבֹּל־אֹתוֹ לִפְאַת קֵדְמָה הַיַּרְדֵּן הָיָה לוֹ לְבִנְיָמִין מֶצֶר מִזְרָחִי, שֶׁהַיַּרְדֵּן הוֹלֵךְ עַל פְּנֵי רוֹחַב כָּל גְּבוּלוֹ לְמִזְרָח.\",1,0],[2,125,18,28,\"וְצֵלַע הָאֶלֶף וְהַיְבוּסִי הִיא יְרוּשָׁלַיִם כָּל אַחַת עִיר לְעַצְמָהּ, וְכֵן גִּבְעַת, קִרְיַת, חָמֵשׁ עָרִים בְּפָסוּק זֶה.\",1,0],[2,125,19,1,\"וַיֵּצֵא הַגּוֹרָל הַשֵּׁנִי שֵׁנִי לְבִנְיָמִין, שֶׁגּוֹרָל בִּנְיָמִין הָיָה רִאשׁוֹן לְשִׁבְעָה הַשְּׁבָטִים שֶׁאָמַר יְהוֹשֻׁעַ לִשְׁלוּחָיו וְהִתְחַלְּקוּ אוֹתָהּ לְשִׁבְעָה חֲלָקִים, שֶׁכְּבָר נָטְלוּ יְהוּדָה וְיוֹסֵף, כְּמוֹ שֶׁנֶּאֱמַר שָׁם (לעיל יח ה): יְהוּדָה יַעֲמֹד עַל גְּבוּלוֹ מִנֶּגֶב וְגוֹ', מִכָּאן וְאֵילָךְ מוֹנֶה וְהוֹלֵךְ ז' גּוֹרָלוֹת.\",1,0],[2,125,19,9,\"רַב מֵהֶם מִן הָרָאוּי לָהֶם.\",1,0],[2,125,19,12,\"כִּסְלוֹת תָּבוֹר אוֹמֵר אֲנִי שֶׁהוּא לְשׁוֹן כְּסָלִים, פלנק\\\"ש בְּלַעַז (צַלְעוֹת הַבְּהֵמָה), [כּמוֹ וַיִקְרָא ג'ד'] לֹא בְּגוֹבְהוֹ וְלֹא בְּשִׁפּוּלוֹ אֶלָּא בְּשִׁפּוּעוֹ וְסָמוּךְ לְאֶמְצָעוֹ קָרוֹב לְצַד אֲחוֹרַיִם, וּמִלְּצַד פָּנָיו, כְּדֶרֶךְ שֶׁהַכְּסָלִים עוֹמְדוֹת בַּבְּהֵמָה, וּבְמָקוֹם שֶׁהוּא אוֹמֵר (להלן פסוק לד) אָזְנוֹת תָּבוֹר, סָמוּךְ לְרֹאשׁוֹ הוּא, בִּמְקוֹם הָאָזְנַיִם.\",1,0],[2,125,19,13,\"קֵדְמָה מִזְרָחָה גִּתָּה חֵפֶר מִמִּזְרָח לְגַת הַחֵפֶר, שֵׁם עִירוֹ שֶׁל יוֹנָה בֶּן אֲמִתַּי (מלכים ב יד כה).\",1,0],[2,125,19,13,\"עִתָּה קָצִין שֵׁם הָעִיר עִתָּה קָצִין.\",2,0],[2,125,19,13,\"הַמְּתֹאָר הַנֵּעָה הַמּוּסָב עַל נֵעָה, כְּלוֹמַר מִשָּׁם תָּאַר הַגְּבוּל לְנֵעָה, וְכֵן תִּרְגֵּם יוֹנָתָן: וְנָפֵיק לְרִמּוֹן וּמִתַּמָּן מִסְתְּחָר לְנֵעָה.\",3,0],[2,125,19,29,\"מִבְצַר צֹר (תַּרְגּוּם:) קִרְוִין כְּרִיכָן קִרְוֵי תּוּקְפָא.\",1,0],[2,125,19,29,\"צֹר לְשׁוֹן צוּר.\",2,0],[2,125,19,29,\"מֵחֶבֶל אַכְזִיבָה (תַּרְגּוּם:) מֵעֲדַב אַכְזִיבָה, מִגּוֹרָל כְּזִיב.\",3,0],[2,125,19,35,\"וְעָרֵי מִבְצָר הָיוּ לְנַפְתָּלִי הַצִּדִּים צֵר.\",1,0],[2,125,19,41,\"צָרְעָה וְאֶשְׁתָּאוֹל מִשֶּׁל יְהוּדָה הָיָה (לעיל טו לג), וְנָפַל גּוֹרָל בְּנֵי דָּן סָמוּךְ לָהֶם.\",1,0],[2,125,19,47,\"וַיֵּצֵא גְּבוּל בְּנֵי־דָן־מֵהֶם כָּאן נָטְלוּ קְצָת וְעוֹד נָפַל לָהֶם גּוֹרָל בְּמָקוֹם אַחֵר רָחוֹק מִגְּבוּלָם, וּשְׁאָר שְׁבָטִים מַפְסִיקִין בֵּינְתַיִם.\",1,0],[2,125,19,47,\"וַיִּלָּחֲמוּ עִם לֶשֶׁם לְאַחַר זְמַן בִּימֵי עָתְנִיאֵל בֶּן קְנַז, וּבִימֵי פֶּסֶל מִיכָה, כְּמָה שֶׁנֶּאֱמַר בְּסֵפֶר שׁוֹפְטִים (יח ב).\",2,0],[2,125,19,47,\"לֶשֶׁם הִיא לַיִשׁ הָאֲמוּרָה בְּסֵפֶר שׁוֹפְטִים (יח יד).\",3,0],[2,125,19,51,\"אֲשֶׁר נִחֲלוּ הִנְחִילוּ.\",1,0],[2,125,20,6,\"עַד עָמְדוֹ וְגוֹ' לַמִּשְׁפָּט אִם יִפָּטֵר מִגָּלוּת יִפָּטֵר, וְאִם יִתְחַיֵּיב גָּלוּת יַחֲזוֹר לְעִיר מִקְלָטוֹ (במדבר לה נה): וְיֵשֵׁב שָׁם עַד מוֹת הַכֹּהֵן הַגָּדוֹל.\",1,0],[2,125,20,8,\"וּמֵעֵבֶר לְיַרְדֵּן יְרִיחוֹ מִזְרָחָה נָתְנוּ בִּימֵי משֶׁה, שֶׁנֶּאֱמַר (דברים ד מג): אֶת בֶּצֶר בַּמִּדְבָּר וְגוֹ'.\",1,0],[2,125,20,9,\"הַמּוּעָדָה הַהַזְמָנָה הַיְעוּדוֹת לְכָךְ.\",1,0],[2,125,21,5,\"וְלִבְנֵי קְהָת הַנּוֹתָרִים הֵם בְּנֵי משֶׁה וּבְנֵי יִצְהָר וְחֶבְרוֹן וְעֻזִּיאֵל.\",1,0],[2,125,21,5,\"מִמִּשְׁפַּחַת מַטֵּה אֶפְרַיִם מִנַּחֲלַת שֵׁבֶט בְּנֵי אֶפְרַיִם נָפְלוּ לָהֶם אֵלֶּה הֶעָרִים, שֶׁבְּכָל שֵׁבֶט וְשֵׁבֶט נָטְלוּ, כְּמָה שֶׁנֶּאֱמַר (במדבר לה ח): מֵאֵת הָרַב תַּרְבּוּ וּמֵאֵת הַמְּעַט תַּמְעִיטוּ אִישׁ כְּפִי נַחֲלָתוֹ אֲשֶׁר יִנְחָלוּ יִתֵּן מֵעָרָיו לַלְוִיִּם.\",2,0],[2,125,21,9,\"אֲשֶׁר יִקְרָא אֶתְהֶן בְּשֵׁם לְפִי שֶׁלֹּא הִזְכִּיר לְמַעְלָה אֶת שְׁמוֹת הֶעָרִים שֶׁנִּתְּנוּ לָהֶם, וּלְמַטָּה הוּא מְפָרֵשׁ אֶת שְׁמוֹתָם, לְכָךְ אָמַר: אֲשֶׁר יִקְרָא אֶתְהֶן בְּשֵׁם.\",1,0],[2,125,21,18,\"וְאֶת עַלְמוֹן וּבְדִבְרֵי הַיָּמִים (דברי הימים א ו מה): וְאֶת עָלֶמֶת, הִיא בַּחוּרִים, שֶׁיּוֹנָתָן (שמואל ב ג טז) מְתַרְגֵּם אוֹתָהּ: עֲלָמוֹת.\",1,0],[2,125,21,18,\"אֶת מִגְרָשֶׁיהָ סְבִיבוֹתֶיהָ אַלְפַּיִם אַמָּה לְכָל רוּחַ.\",2,0],[2,125,22,7,\"וְגַם כִּי שִׁלְּחָם יְהוֹשֻׁעַ לַחֲצִי שֵׁבֶט הַמְנַשֶּׁה, כַּאֲשֶׁר שָׁלַח אֶת בְּנֵי רְאוּבֵן וְגָד.\",1,0],[2,125,22,8,\"עִם אֲחֵיכֶם בְּנֵי רְאוּבֵן וּבְנֵי גָּד, וְיֵשׁ פּוֹתְרִין: עִם אֲחֵיכֶם שֶׁנִּשְׁאֲרוּ לִשְׁמוֹר אֶת הֶעָרִים עִם הַנָּשִׁים וְהַטַּף, וְלֹא עָבְרוּ אֶת הַיַּרְדֵּן עִם הַחֲלוּצִים, גַּם הֵם נָטְלוּ חֵלֶק בַּבִּזָּה.\",1,0],[2,125,22,12,\"לַעֲלוֹת עֲלֵיהֶם לַצָּבָא לְפִי שֶׁנֶּאֶסְרוּ הַבָּמוֹת מִשֶּׁנִּקְבַּע הַמִּשְׁכָּן בְּשִׁילֹה.\",1,0],[2,125,22,19,\"אִם טְמֵאָה אֶרֶץ אֲחֻזַּתְכֶם שֶׁלֹּא בָּחַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁרוֹת בָּהּ שְׁכִינָתוֹ.\",1,0],[2,125,22,19,\"וְאֹתָנוּ אַל תִּמְרֹדוּ כְּמוֹ: וּבָנוּ אַל תִּמְרוֹדוּ.\",2,0],[2,125,22,22,\"אֵל אֱלֹהִים ה' אֵל כָּל הָאֱלֹהִים הוּא ה' הַיּוֹדֵעַ כִּי לֹא בְּמֶרֶד וְגוֹמֵר, וּכְשֶׁכָּפַל לוֹמַר שְׁתֵּי פְּעָמִים אֱלֹהִים, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.\",1,0],[2,125,22,22,\"אַל תּוֹשִיעֵנוּ כְּלַפֵּי שְׁכִינָה אָמְרוּ.\",2,0],[2,125,22,23,\"הוּא יְבַקֵּשׁ יִפָּרַע מִמֶּנּוּ.\",1,0],[2,125,22,24,\"מִדְּאָגָה מִדָּבָר מֵחֲמַת דַּאֲגַת יִרְאַת דְּבַר חֶרְפָּה עָשִׂינוּ, כְּמָה שֶׁמְּפֹרָשׁ פֶּן יֹאמְרוּ בְּנֵיכֶם מָחָר לְחָרֵף אֶת בָּנֵינוּ, כְּשֶׁיֵּלְכוּ לְהַקְרִיב בְּמִשְכַּן שִׁילֹה, שֶׁמָּא יֹאמְרוּ מַה לָּכֶם וְלַה', וַהֲלֹא גְּבוּל נָתַן בֵּינֵינוּ וּבֵינֵיכֶם אֶת הַיַּרְדֵּן, זוֹ דָּאַגְנוּ וְעָשִׂינוּ. כָּל 'דְּאָגָה' שֶׁבַּמִּקְרָא לְשׁוֹן יִרְאָה הוּא, כְּמוֹ (ירמיהו לח יט): אֲנִי דּוֹאֵג אֶת הַיְּהוּדִים, דְּצִדְקִיָּהוּ.\",1,0],[2,125,22,27,\"כִּי עֵד הוּא שֶׁלֹּא סִילַּקְנוּ עַצְמֵנוּ מִתּוֹרַת מִזְבֵּחַ.\",1,0],[2,125,22,33,\"וַיְבָרְכוּ אֱלֹהִים (תַּרְגּוּם:) וְאוֹדִיאוּ קֳדָם ה' בְּנֵי יִשְׂרָאֵל.\",1,0],[2,125,22,34,\"וַיִּקְרְאוּ בְּנֵי רְאוּבֵן וּבְנֵי גָד לַמִּזְבֵּחַ כִּי עֵד הוּא הֲרֵי זֶה מִן הַמִּקְרָאוֹת הַקְּצָרִים, וְצָרִיךְ לְהוֹסִיף בּוֹ תֵּיבָה אַחַת: וַיִּקְרְאוּ בְּנֵי רְאוּבֵן וּבְנֵי גָד לַמִּזְבֵּחַ עֵד.\",1,0],[2,125,23,4,\"רְאוּ הִפַּלְתִּי לָכֶם בְּגוֹרָל לְנַחֲלָה.\",1,0],[2,125,23,4,\"הַנִּשְׁאָרִים לִיכָּבֵשׁ.\",2,0],[2,125,23,13,\"וּלְשׁוֹטֵט בְּצִדֵּיכֶם יְשׁוֹטְטוּ לָבוֹז וְלִשְׁלוֹל סְבִיבוֹתֵיכֶם.\",1,0],[2,125,23,13,\"וְלִצְנִנִים לְשׁוֹן מַחֲנוֹת, וְכֵן (יחזקאל כג כד): וּבָאוּ עָלַיִךְ הֹצֶן, כְּצִנָּה זוֹ הַמַּקֶּפֶת אֶת הָאָדָם מִשָּׁלשׁ רוּחוֹת, כְּמָה שֶׁנֶּאֱמַר (תהלים ה יג): כַּצִּנָּה רָצוֹן תַּעְטְרֶנּוּ תְּסוֹבְבֶנוּ, כְּמוֹ (שמואל א כג כו): וְשָׁאוּל וַאֲנָשָׁיו עֹטְרִים אֶל דָּוִד וְאֶל אֲנָשָׁיו, עֹטְרִים סוֹבְבִים.\",2,0],[2,125,24,3,\"וָאַרְבֶּה אֶת זַרְעוֹ חֲסַר הֵ\\\"א, כַּמָּה מְרִיבוֹת וְנִסְיוֹנוֹת עָשִׂיתִי עִמּוֹ, עַד שֶׁלֹּא נָתַתִּי לוֹ זֶרַע.\",1,0],[2,125,24,7,\"וַיָּבֵא עָלָיו אֶת הַיָּם עַל כָּל יָחִיד וְיָחִיד שֶׁבָּהֶם, שֶׁאִם הָיָה הַיָּחִיד בּוֹרֵחַ שֶׁלֹּא לִיכָּנֵס בַּיָּם, גַּל שֶׁל יָם רוֹדֵף אַחֲרָיו וְקוֹלְטוֹ.\",1,0],[2,125,24,11,\"וַיִּלָּחֲמוּ בָכֶם בַּעֲלֵי יְרִיחוֹ הָאֱמוֹרִי וְהַפְּרִזִּי וְגוֹמֵר כָּל שִׁבְעָה הָעוֹבְדֵי כּוֹכָבִים נִזְכָּרִין כָּאן, לְפִי שֶׁיְּרִיחוֹ עוֹמֶדֶת עַל הַסְּפָר, וְהָיְתָה נִגְרָהּ וּמַנְעוּלָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל נִקְבְּצוּ לְתוֹכָהּ מִכָּל שִׁבְעָה הָאוּמּוֹת גִּבּוֹרֵי הֶחָיִל.\",1,0],[2,125,24,19,\"אֱלֹהִים קְדוֹשִׁים בְּרוֹב מְקוֹמוֹת נִקְרָא כָּל לְשׁוֹן רַבָּנוּת לְשׁוֹן רַבִּים, כְּמוֹ (בראשית מב ל): אֲדֹנֵי הָאָרֶץ, (שם לט כ): אֲדֹנֵי יוֹסֵף, (שמות כב יד) : אִם בְּעָלָיו עִמּוֹ, (שמואל ב כ כג): אֲשֶׁר הָלְכוּ אֱלֹהִים לִפְדּוֹת, לְפִי שֶׁהַשֵּׁם הַזֶּה שֵׁם שְׂרָרָה הוּא.\",1,0],[2,125,24,22,\"עֵדִים אַתֶּם בָּכֶם רָאָה יְהוֹשֻׁעַ שֶׁעֲתִידִין לְעַרְעֵר בִּימֵי יְחֶזְקֵאל וְלוֹמַר (יחזקאל כ לב): נִהְיֶה כַגּוֹיִם, לְפִיכָךְ הִכְבִּיד עֲלֵיהֶם עַכְשָׁיו, וּלְכָךְ הוּשַׁב לָהֶם בִּימֵי יְחֶזְקֵאל (שם פסוקים לב לג): וְהָעֹלָה עַל רוּחֲכֶם הָיֹה לֹא תִהְיֶה וְגוֹמֵר, חַי אֲנִי אִם לֹא בְיַד חֲזָקָה וְגוֹמֵר, כְּבָר קִבַּלְתֶּם עֲלֵיכֶם בִּימֵי יְהוֹשֻׁעַ, וְלֹא תֹּאמְרוּ מַה שֶּׁקִּבַּלְנוּ עָלֵינוּ בִּימֵי משֶׁה כְּדֵי לִיכָּנֵס לָאָרֶץ עָשִׂינוּ, הֲרֵי בִּימֵי יְהוֹשֻׁעַ כְּבָר נִכְנַסְתֶּם וְקִבַּלְתֶּם.\",1,0],[2,125,24,25,\"וַיָּשֶׂם לוֹ חֹק וּמִשְׁפָּט בִּשְׁכֶם סִידֵּר לָהֶם שָׁם הַחֻקִּים שֶׁבַּתּוֹרָה וְקִבְּלוּ עֲלֵיהֶם.\",1,0],[2,125,24,26,\"וַיִּכְתֹּב יְהוֹשֻׁעַ וְגוֹמֵר תַּרְגּוּם יוֹנָתָן: וְכָתַב יְהוֹשֻׁעַ יַת פִּתְגָּמַיָּא הָאִלֵּין וְאַצְנְעִינוּן בְּסֵפֶר אוֹרָיְיתָא דַה', וּבְמַסֶּכֶת מַכּוֹת (יא א) נֶחְלְקוּ אֲמוֹרָאִים: חַד אָמַר אֵלּוּ שְׁמוֹנָה פְּסוּקִים (דברים לד ה-יב) מִן 'וַיָּמֹת משֶׁה' עַד 'לְעֵינֵי כָּל יִשְׂרָאֵל', שֶׁהֲרֵי סֵפֶר תּוֹרָה חָסֵר וְהִשְׁלִימוֹ, וְחַד אָמַר פָּרָשָׁה זוֹ שֶׁל עָרֵי מִקְלָט כָּתַב בְּסִפְרוֹ כְּמוֹ שֶׁהָיוּ כְּתוּבִים בְּסֵפֶר הַתּוֹרָה.\",1,0],[2,125,24,26,\"תַּחַת הָאַלָּה (תַּרְגּוּם:) תְּחוֹת אַלְּתָא, הִיא מְזוּזוֹת הַפֶּתַח, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ו לא): הָאַיִל מְזוּזוֹת חֲמִשִׁית, וּמִדָּה אַחַת לָאֵלִים, וְיֵשׁ אוֹמְרִים זוֹ הָאֵלָה אֲשֶׁר עִם שְׁכֶם, שֶׁכָּתוּב בְּיַעֲקֹב (בראשית לה ד): וַיִּטְמֹן אֹתָם יַעֲקֹב תַּחַת הָאֵלָה.\",2,0],[2,125,24,26,\"אֲשֶׁר בְּמִקְדַּשׁ ה' כְּלַפֵּי שֶׁהֵבִיאוּ שָׁם אֶת הָאֲרוֹן, כְּמָה שֶׁנֶּאֱמַר לְמַעְלָה (פסוק א): וַיִּתְיַצְּבוּ לִפְנֵי הָאֱלֹהִים.\",3,0],[2,125,24,27,\"הָאֶבֶן הַזֹּאת תִּהְיֶה בָּנוּ לְעֵדָה וגו' (תַּרְגּוּם:) הָא אַבְנָא הָדָא תְּהֵי לָנָא כִּתְרֵין לוּחֵי אֶבֶן דִּקְיָימָה אֲרֵי יָתָהּ עֲבַדְנָא לְסַהֲדוּ אֲרֵי פִּתְגָּמַיָּא דִּכְתִיבִין עֲלָהּ מֵעֵין כָּל פִּתְגָמַיָא דַּה' דְּמַלֵיל עִמָּנָא. וְגַם יֵשׁ לְפוֹתְרוֹ כְּמַשְׁמָעוֹ, כִּי הִיא שָׁמְעָה אֶת הַדְּבָרִים אֲשֶׁר דִּבַּרְתִּי לָכֶם בִּשְׁלִיחוּתוֹ שֶׁל מָקוֹם.\",1,0],[2,125,24,30,\"בְּתִמְנַת סֶרַח כָּךְ שְׁמָהּ, וּבְמָקוֹם אַחֵר (שופטים ב ט) הוּא קוֹרֵא אוֹתָהּ 'תִּמְנַת חֵרֶס', עַל שֵׁם שֶׁהֶעֱמִידוּ תְּמוּנַת הַחַמָּה עַל קִבְרוֹ (של יהושע), לוֹמַר זֶה הוּא שֶׁהֶעֱמִיד הַחַמָּה, וְכָל הָעוֹבֵר עָלֶיהָ אוֹמֵר חֲבָל עַל זֶה שֶׁעָשָׂה דָּבָר גָּדוֹל כָּזֶה וָמֵת. וְיֵשׁ אוֹמְרִים, תִּמְנַת חֵרֶס שְׁמָהּ, וְלָמָּה נִקְרָא שְׁמָהּ תִּמְנַת סֶרַח, עַל שֵׁם שֶׁפֵּירוֹתֶיהָ מַסְרִיחִין מֵרוֹב שֻׁמָּנַן.\",1,0],[2,125,24,30,\"לְהַר גָּעַשׁ מְלַמֵּד שֶׁרָעַשׁ עֲלֵיהֶם הָהָר לְהוֹרְגָם לְפִי שֶׁלֹּא הִסְפִּידוּהוּ כָּרָאוּי.\",2,0],[2,125,24,31,\"הֶאֱרִיכוּ יָמִים יָמִים הֶאֱרִיכוּ, שָׁנִים לֹא הֶאֱרִיכוּ, שֶׁנֶּעֶנְשׁוּ.\",1,0],[2,125,24,32,\"קָבְרוּ בִּשְׁכֶם מִשְּׁכֶם גְּנָבוּהוּ, לִשְׁכֶם הֶחֱזִירוּהוּ.\",1,0],[2,125,24,33,\"בְּגִבְעַת פִּינְחָס בְּנוֹ מֵהֵיכָן הָיָה לוֹ לְפִינְחָס חֵלֶק בָּאָרֶץ, שֶׁיָּרַשׁ מֵאִשְׁתּוֹ.\",1,0],[2,126,1,1,\"מִי יַעֲלֶה לָּנוּ אֶל הַכְּנַעֲנִי. עַל מְקוֹמוֹת שֶׁהִפַּלְנוּ בְּגוֹרָל וַעֲדַיִן לֹא נִכְבְּשׁוּ:\",1,0],[2,126,1,2,\"יְהוּדָה יַעֲלֶה. שֵׁבֶט יְהוּדָה יַעֲלֶה תְּחִלָּה לִכְבֹּשׁ אֶת גּוֹרָלוֹ:\",1,0],[2,126,1,3,\"לְשִׁמְעוֹן אָחִיו. לְשֵׁבֶט שִׁמְעוֹן:\",1,0],[2,126,1,3,\"עֲלֵה אִתִּי. וְעָזְרֵנִי לִכְבּוֹשׁ אֶת מַה שֶׁנָּפַל בְּגוֹרָלִי וְיֵשׁ פּוֹתְרִין: יְהוּדָה יַעֲלֶה, הוּא עָתְנִיאֵל, הוּא יַעְבֵּץ, שֶׁאָנוּ אוֹמְרִים בְּמַסֶּכֶת תְּמוּרָה (טז א): מַה שְּׁמוֹ, יְהוּדָה אֲחִי שִׁמְעוֹן שְׁמוֹ, וּלְשִׁמְעוֹן אָחִיו אָמַר שֶׁיֵּלֵךְ אִתּוֹ:\",2,0],[2,126,1,4,\"בְּבֶזֶק. שֵׁם מָקוֹם:\",1,0],[2,126,1,7,\"שִׁבְעִים מְלָכִים וְגוֹ׳. מִכָּאן אַתָּה לָמֵד מַה גְּדוּלָּתָן וְעָשְׁרָן שֶׁל מַלְכֵי כְּנַעַן, שֶׁהֲרֵי אֲדֹנִי בֶזֶק לֹא הָיָה כְּדַאי לִמְנוֹת (יהושע יב) עִם מַלְכֵי כְּנַעַן בְּשֵׁם ׳מֶלֶךְ׳, וְכָתוּב בּוֹ כֵּן:\",1,0],[2,126,1,7,\"וַיְבִיאֻהוּ יְרוּשָׁלִַם. שֶׁהָלְכוּ מִשָּׁם לְהִלָּחֵם עַל יְרוּשָׁלַיִם:\",2,0],[2,126,1,8,\"שִׁלְּחוּ בָאֵשׁ. שִׁלְּחוּ אֵשׁ בְּכֻלָּהּ:\",1,0],[2,126,1,13,\"אֲחִי כָלֵב. מֵאִמּוֹ:\",1,0],[2,126,1,14,\"וַתְּסִיתֵהוּ. (תרגום:) וְאַמְלָכְתֵּיהּ, לְשׁוֹן נִמְלָךְ, שֶׁמְּיַעֲצִין הָאָדָם וּמַשִּׂיאִין לִבּוֹ לְדָבָר אַחֵר, נִרְאֶה לִי:\",1,0],[2,126,1,14,\"וַתִּצְנַח. (תרגום:) וְאִתְרְכִינַת, לִיפּוֹל לְרַגְלֵי אָבִיהָ:\",2,0],[2,126,1,15,\"אֶרֶץ הַנֶּגֶב. אָדָם שֶׁבֵּיתוֹ מְנֻגָּב מִכָּל טוּב, שֶׁאֵין בּוֹ אֶלָּא תּוֹרָה:\",1,0],[2,126,1,15,\"גֻּלֹּת מָיִם. שְׂדֵה בֵּית הַבַּעַל, (תרגום:) אֲתַר בֵּית שָׁקְיָא דְמַיָּא:\",2,0],[2,126,1,16,\"מֵעִיר הַתְּמָרִים. הִיא יְרִיחוֹ, שֶׁנִּתַּן לָהֶם דּוּשְׁנָהּ שֶׁל יְרִיחוֹ לְאָכְלָהּ עַד שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ, וּמִי שֶׁיִּבְנֶה בֵּית הַבְּחִירָה בְּחֶלְקוֹ יִטְּלֶנָּה, כְּדֵי שֶׁיְּהֵא לְכָל יִשְׂרָאֵל חֵלֶק בְּבֵית הַבְּחִירָה, וּנְתָנוּהָ לִבְנֵי יִתְרוֹ אַרְבַּע מֵאוֹת אַרְבָּעִים שָׁנָה, וְהַתַּלְמִידִים שֶׁבָּהֶם הִנִּיחוּהָ וְהָלְכוּ אֵצֶל עָתְנִיאֵל בֶּן קְנַז הוּא יַעְבֵּץ בְּמִדְבַּר יְהוּדָה אֲשֶׁר בְּנֶגֶב עֲרָד לִלְמוֹד תּוֹרָה:\",1,0],[2,126,1,16,\"וַיֵּשֶׁב אֶת הָעָם. עִם הַתַּלְמִידִים הַיּוֹשְׁבִים לְפָנָיו הוּא בִּקֵּשׁ מֵאֵת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּזְמִין לוֹ תַּלְמִידִים הֲגוּנִים, שֶׁנֶּאֱמַר (דברי הימים א ד:י) וַיִּקְרָא יַעְבֵּץ לֵאלֹהִים וְגוֹ׳, וְזִמֵּן לוֹ הַחֲסִידִים הַלָּלוּ:\",2,0],[2,126,1,19,\"כִּי לֹא לְהוֹרִישׁ. תִּרְגֵּם יוֹנָתָן: בָּתַר כֵּן דְּחָבוּ, לָא יְכִילוּ לְתָרְכָא יָת יָתְבֵי מֵישְׁרָא:\",1,0],[2,126,1,21,\"וְאֶת הַיְבוּסִי יֹשֵׁב יְרוּשָׁלִַם. מָחוֹז הָיָה בִּירוּשָׁלַיִם שֶׁשְּׁמוֹ יְבוּסִי (פרקי דרבי אליעזר לו), וּמִבְּנֵי אֲבִימֶלֶךְ הָיוּ, וְלֹא הוֹרִישָׁם מִפְּנֵי הַשְּׁבוּעָה (בראשית כא:כג-כד) עַד שֶׁבָּא דָוִד (שמואל ב ה:ו-ז), לְפִי שֶׁעֲדַיִן הָיָה נֶכְדּוֹ קַיָּם, וְהוּא נִשְׁבַּע לוֹ וּלְנִינוֹ וּלְנֶכְדּוֹ:\",1,0],[2,126,1,22,\"בֵּית אֵל. שֶׁנָּפַל בְּגוֹרָלָם (יהושע טז:א), וְאַף עַל פִּי שֶׁפֶּסֶל מִיכָה עִמָּהֶם, שֶׁהֲרֵי מִיכָה מִשֵּׁבֶט אֶפְרַיִם (שופטים יז:א), נֶאֱמַר כָּאן ׳וַה׳ עִמָּם׳, הוּא שֶׁאָמַר דָּנִיֵּאל (דניאל ט:ז): לְךָ ה׳ הַצְּדָקָה וְלָנוּ בֹּשֶׁת הַפָּנִים:\",1,0],[2,126,1,23,\"וַיָּתִירוּ. עַל יְדֵי אֲחֵרִים, (תרגום:) וּשְׁלָחוּ מְאַלְּלִין, וְיָתוּרוּ אֶת אֶרֶץ (במדבר יג:ב) נֶאֱמַר בַּמְרַגְּלִים עַצְמָן, וְאֵלּוּ שֶׁשָּׁלְחוּ מְרַגְּלִים נֶאֱמַר בָּהֶם וַיָּתִירוּ:\",1,0],[2,126,1,24,\"אֶת מְבוֹא הָעִיר. שֶׁהָיוּ נִכְנָסִים לָהּ דֶּרֶךְ הַמְּעָרָה, וְלוּז אֶחָד עוֹמֵד עַל פִּי הַמְּעָרָה וְנִכְנָסִים דֶּרֶךְ הַלּוּז לַמְּעָרָה:\",1,0],[2,126,1,25,\"וַיַּרְאֵם. בְּאֶצְבָּעוֹ:\",1,0],[2,126,1,26,\"לוּז. שֶׁגָּדְלוּ בּוֹ אֱגוֹזִים דַּקִּים, קולדר״א בְּלַעַ״ז:\",1,0],[2,126,1,26,\"הוּא שְׁמָהּ עַד הַיּוֹם. לֹא בִּלְבְּלָה סַנְחֵרִיב, וְלֹא הֶחֱרִיבָהּ נְבוּכַדְנֶצַּר:\",2,0],[2,126,1,27,\"וְלֹא הוֹרִישׁ מְנַשֶּׁה. סִפֵּר הַכָּתוּב בִּגְנוּתוֹ, שֶׁהִתְחִילוּ לִמְעוֹל בְּהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁצִּוָּה אוֹתָם (במדבר לג:נב): וְהוֹרַשְׁתֶּם אֶת כָּל יוֹשְׁבֵי הָאָרֶץ וְגוֹ׳:\",1,0],[2,126,2,1,\"וַיַּעַל מַלְאַךְ ה׳. שָׁנִינוּ בְּ׳סֵדֶר עוֹלָם׳ (פרק יט): זֶה הָיָה פִּנְחָס:\",1,0],[2,126,2,1,\"אֶל הַבֹּכִים. שֵׁם הַמָּקוֹם:\",2,0],[2,126,2,1,\"אַעֲלֶה אֶתְכֶם. כָּךְ הָיָה דַעְתִּי מִתְּחִלָּה לְהַעֲלוֹתְכֶם מִמִּצְרַיִם, וְכֵן עָשִׂיתִי עַל מְנָת לְהוֹרִישׁ אֶת אוֹיְבַי:\",3,0],[2,126,2,3,\"וְגַם אָמַרְתִּי. עַתָּה אָמַרְתִּי בְּאַפִּי:\",1,0],[2,126,2,3,\"לְצִדִּים. לִמְצַדְּדִים בְּצִדְּכֶם בִּגְדוּדִים וְגַיָּסוֹת לִשְׁלֹל וְלָבוֹז:\",2,0],[2,126,2,6,\"וַיְשַׁלַּח יְהוֹשֻׁעַ וְגוֹ׳. זֶה הַמַּעֲשֶׂה הָיָה מֻקְדָּם, אֶלָּא לְפִי שֶׁבָּא לוֹמַר (פסוק יא): וַיַּעֲשׂוּ הָרַע, הִתְחִיל לוֹמַר כֵּן: יְהוֹשֻׁעַ כְּשֶׁמֵּת, וְקִבְּלוּ לְפָנָיו לַעֲבֹד ה׳, שְׁלָחָם אִישׁ לְנַחֲלָתוֹ, וְהֵם עָבְדוּ אֶת ה׳ כָּל יָמָיו וְכָל יְמֵי הַזְּקֵנִים, וְאַחַר כָּךְ: וַיַּעֲשׂוּ בְּנֵי יִשְׂרָאֵל הָרַע:\",1,0],[2,126,2,7,\"אֲשֶׁר הֶאֱרִיכוּ יָמִים וְגוֹ׳. יָמִים הֶאֱרִיכוּ, שָׁנִים לֹא הֶאֱרִיכוּ, לְפִי שֶׁנִּתְעַצְּלוּ בְּהֶסְפֵּדוֹ, הוּא שֶׁנֶּאֱמַר (פסוק ט): הַר גָּעַשׁ, שֶׁרָעַשׁ עֲלֵיהֶם הָהָר לְהָרְגָן:\",1,0],[2,126,2,9,\"בְּתִמְנַת חֶרֶס. עַל שֵׁם שֶׁהֶעֱמִידוּ תְּמוּנַת חֶרֶס עַל קִבְרוֹ, כְּלוֹמַר חֲבָל עַל אָדָם שֶׁהֶעֱמִיד הַחַמָּה וּמוּטָל בְּקֶבֶר:\",1,0],[2,126,2,15,\"בְּכָל אֲשֶׁר יָצְאוּ יַד ה׳ הָיְתָה בָּם לְרָעָה. עַל אֲבִימֶלֶךְ וּמַחְלוֹן וְכִלְיוֹן נֶאֱמַר בְּ׳סֵדֶר עוֹלָם׳ (פרק יב):\",1,0],[2,126,2,16,\"וַיָּקֶם ה׳ שֹׁפְטִים. תָּמִיד מִדּוֹר אֶל דּוֹר, כְּמוֹ שֶׁהוּא מוֹנֶה וְהוֹלֵךְ בַּסֵּפֶר הַזֶּה, שׁוֹפֵט אַחַר שׁוֹפֵט:\",1,0],[2,126,2,18,\"וְכִי הֵקִים. לְשׁוֹן הֹוֶה, וְכַאֲשֶׁר הָיָה מֵקִים לָהֶם שׁוֹפְטִים, וְהָיָה ה׳ עִם הַשּׁוֹפֵט וְגוֹ׳:\",1,0],[2,126,2,18,\"כִּי יִנָּחֵם. שֶׁהָיָה מִתְנַחֵם לָהֶם עַל הָרָעָה, כֵּן תִּרְגֵּם יוֹנָתָן:\",2,0],[2,126,2,18,\"מִנַּאֲקָתָם. מִפְּנֵי נַאֲקָתָם, הָעוֹלָה לְפָנָיו מִפְּנֵי אוֹיְבֵיהֶם:\",3,0],[2,126,2,19,\"לֹא הִפִּילוּ. לֹא הִנִּיחוּ דָבָר לִהְיוֹת נוֹכָחִים עַל כָּל הַבָּא עֲלֵיהֶם:\",1,0],[2,126,2,22,\"הֲשֹׁמְרִים הֵם. ה״א חֲטַף פַּתַּח הוּא נָקוּד, לְפִי שֶׁהוּא לְשׁוֹן שְׁאֵלָה וְנִסָּיוֹן:\",1,0],[2,126,3,1,\"לְנַסּוֹת בָּם אֶת יִשְׂרָאֵל. אֶת דּוֹר הָאַחֵר אֲשֶׁר לֹא יָדְעוּ אֶת נִסֵּי מִלְחֲמוֹת כְּנַעַן וְלֹא רָאוּ אֶת הַמַּעֲשֶׂה הַגָּדוֹל, וְהִמְרוּ וּמָעֲלוּ בַמָּקוֹם:\",1,0],[2,126,3,2,\"רַק לְמַעַן דַּעַת. רַק לְדָבָר הַזֶּה לְבַדּוֹ הִנִּיחָם, לְמַעַן דַּעַת וּלְהִתְבּוֹנֵן דּוֹרוֹת בְּנֵי יִשְׂרָאֵל הַבָּאִים מַה הַחֵטְא גּוֹרֵם, כִּי עַתָּה הֵם זְקוּקִים לְלַמְּדָם מִלְחָמָה:\",1,0],[2,126,3,2,\"רַק אֲשֶׁר לְפָנִים. שֶׁהָיוּ עוֹמְדִים לְשָׁרֵת אֶת ה׳:\",2,0],[2,126,3,2,\"לֹא יְדָעוּם. לְמִלְחָמוֹת הַלָּלוּ וְטַכְסִיסֵיהֶם, וְלֹא נִצְרְכוּ לָהֶם:\",3,0],[2,126,3,3,\"חֲמֵשֶׁת סַרְנֵי פְלִשְׁתִּים. הֵם הַגּוֹיִם אֲשֶׁר הִנִּיחַ לְנַסּוֹת:\",1,0],[2,126,3,10,\"וַתְּהִי עָלָיו רוּחַ ה׳. דָּרַשׁ רַבִּי תַּנְחוּמָא (מדרש תנחומא שמות כ) נִסְתַּכֵּל בָּהֶם, שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה בְּמִצְרַיִם (שמות ג:ז) רָאֹה רָאִיתִי אֶת עֳנִי עַמִּי, מַה הֵן שְׁתֵּי רְאִיּוֹת הַלָּלוּ, אָמַר לוֹ: רוֹאֶה אֲנִי שֶׁעֲתִידִין לִטְעוֹת בָּעֵגֶל, וְאַף עַל פִּי כֵן ׳רָאִיתִי אֶת עֳנִי עַמִּי׳. זוֹ דָּרַשׁ עָתְנִיאֵל, אָמַר: בֵּין זַכִּים בֵּין חַיָּבִים, עָלָיו לְהוֹשִׁיעָם:\",1,0],[2,126,3,13,\"אֶת עִיר הַתְּמָרִים. יְרִיחוֹ:\",1,0],[2,126,3,15,\"אִטֵּר יַד יְמִינוֹ. תִּרְגֵּם יְהוֹנָתָן: גְּבַר גְּמִיד יַד יְמִינֵיהּ, וְכָל גְּמִיד לְשׁוֹן אֲרָמִי הוּא, דָּבָר כָּווּץ מֵחֲמַת חֹלִי, ריטרי״ט בְּלַעַ״ז; לֹא הָיָה שׁוֹלֵט בְּיַד יְמִינוֹ. וּבִלְשׁוֹן עִבְרִי: אִטֵּר, אָטוּם, כְּמוֹ (תהלים סט:טז) וְאַל תֶּאְטַר עָלַי בְּאֵר פִּיהָ, אָטוּם בְּיַד יְמִינוֹ, שֶׁלֹּא הָיָה שׁוֹלֵט בָּהּ:\",1,0],[2,126,3,16,\"גֹּמֶד אָרְכָּהּ. אַמָּה גְּדוּמָה, וּבִלְשׁוֹן אַשְׁכְּנַז: דוימ״ן לאנ״ג, וּבִלְשׁוֹן לַעַז: גשקור״ט:\",1,0],[2,126,3,16,\"עַל יֶרֶךְ יְמִינוֹ. לְפִי שֶׁבִּשְׂמֹאלוֹ שׁוֹלֵט, יֹאחֲזֶנָּה בִּשְׂמֹאלוֹ:\",2,0],[2,126,3,17,\"אִישׁ בָּרִיא. (תרגום:) פָּטִים:\",1,0],[2,126,3,18,\"וַיְשַׁלַּח אֶת הָעָם. חָזַר לַאֲחוֹרָיו וְלִוָּה אֶת חֲבוּרַת יִשְׂרָאֵל אֲשֶׁר בָּאוּ עִמּוֹ לָשֵׂאת אֶת הַמִּנְחָה, וְלִוָּה אוֹתָם עַד הַגִּלְגָּל:\",1,0],[2,126,3,19,\"וְהוּא שָׁב. יְחִידִי:\",1,0],[2,126,3,19,\"מִן הַפְּסִילִים. מָקוֹם שֶׁפּוֹסְלִים שָׁם אֲבָנִים מִן הָהָר, וְכֵן תִּרְגֵּם יוֹנָתָן: מִן מַחְצְבַיָּא, וּבָא אֶל עֶגְלוֹן וַיֹּאמֶר לוֹ:\",2,0],[2,126,3,19,\"וַיֹּאמֶר הָס. אָמַר עֶגְלוֹן: שִׁתְקוּ אֶת הַכֹּל מֵעָלַי, וְיוֹנָתָן תִּרְגֵּם הָס: סְלִיק, הוֹצִיא כָּל אִישׁ, וְאַף עַל פִּי כֵן ׳הָס׳, לְשׁוֹן שְׁתוֹק:\",3,0],[2,126,3,20,\"בַּעֲלִיַּת הַמְּקֵרָה. (תרגום:) בַּעֲלִיַּת בֵּית קַיְטָא, שֶׁהָיְתָה לָאֲוִיר וְצוֹנֶנֶת:\",1,0],[2,126,3,20,\"דְּבַר אֱלֹהִים לִי אֵלֶיךָ. וְצָרִיךְ אַתָּה לַעֲמוֹד:\",2,0],[2,126,3,20,\"וַיָּקָם מֵעַל הַכִּסֵּא. לְכָךְ זָכָה וְיָצְאָה מִמֶּנּוּ רוּת:\",3,0],[2,126,3,22,\"הַנִּצָּב. הוּא הַבַּרְזֶל שֶׁהַשָּׁנוּן תָּחוּב לְתוֹכוֹ, שֶׁקּוֹרִין הול״ט בְּלַעַ״ז, הוּא הַמַּעֲמִיד הַחֶרֶב עַל פִּי תַּעְרָהּ:\",1,0],[2,126,3,22,\"הַלַּהַב. הוּא הַשָּׁנוּן שֶׁקּוֹרִין ברונ״ט בְּלַעַ״ז, וּבְלַעַ״ז למ״א:\",2,0],[2,126,3,22,\"וַיִּסְגֹּר הַחֵלֶב. שֻׁמָּנוֹ, שֶׁהָיָה שָׁמֵן מְאֹד, וְכִסָּה אֶת כָּל אֹרֶךְ הַחֶרֶב:\",3,0],[2,126,3,22,\"וַיֵּצֵא הַפַּרְשְׁדֹּנָה. תִּרְגֵּם יוֹנָתָן: וּנְפַק אוּכְלֵיהּ שְׁפִיךְ, עֲשָׂאָן כִּשְׁתֵּי תֵבוֹת וְשִׁי״ן מְשַׁמֶּשֶׁת לִשְׁתֵּיהֶן, וַיֵּצֵא הַפֶּרֶשׁ, שְׁדוֹנָה, בִּשְׁפִיכָה. שָׁפַךְ, ׳שְׁדָא׳ כְּתַרְגּוּמוֹ:\",4,0],[2,126,3,23,\"וַיֵּצֵא אֵהוּד הַמִּסְדְּרוֹנָה. מִן הָעֲלִיָּה אֶל הַמִּסְדְּרוֹנָה, תִּרְגֵּם יוֹנָתָן: לְאַכְסַדְרָא:\",1,0],[2,126,3,23,\"וְנָעָל. בְּמַפְתֵּחַ:\",2,0],[2,126,3,24,\"וְהוּא יָצָא. אֵהוּד יָצָא, וְעַבְדָיו שֶׁל עֶגְלוֹן בָּאוּ:\",1,0],[2,126,3,24,\"מֵסִיךְ רַגְלָיו. (תרגום:) עָבֵיד צוֹרְכֵיהּ, הֵם נְקָבִים הַגְּדוֹלִים:\",2,0],[2,126,3,25,\"עַד בּוֹשׁ. עַד עִכּוּב, כְּלוֹמַר זְמַן אָרוֹךְ:\",1,0],[2,126,3,26,\"נִמְלַט. בָּרַח, אישקימוציי״ר בְּלַעַ״ז:\",1,0],[2,126,3,26,\"עַד הִתְמַהְמְהָם. כְּמוֹ (שיר השירים א:יב) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ, (שם ב:ז) אֶת הָאַהֲבָה עַד שֶׁתֶּחְפָּץ, בְּעוֹד שֶׁשְּׁנֵינוּ חֲפֵצִים בָּהּ:\",2,0],[2,126,3,26,\"הַשְּׂעִירָתָה. יַעַר דַּק וְעָב, שֶׁקּוֹרִין ברוצ״ש בְּלַעַ״ז, וְטוֹב הוּא לְהֵחָבֵא וְהַרְבֵּה יֵשׁ בְּסֵדֶר זְרָעִים שֶׁעַנְפֵי אִילָנוֹת דַּקִּים קְרוּיִין שֵׂעָר (כלאים ד:ט) הוֹפֵךְ אֶת הַשֵּׂעָר, (פאה ב:ג) וְאִם הָיָה הַשֵּׂעָר כּוֹתֵשׁ:\",3,0],[2,126,3,27,\"וַיְהִי בְּבוֹאוֹ. שֶׁעָבַר אֶת הַיַּרְדֵּן וּבָא לִמְקוֹמוֹ בְּאֶרֶץ כְּנָעַן:\",1,0],[2,126,3,27,\"בְּהַר אֶפְרָיִם. שֶׁהָיָה בְּאֶרֶץ כְּנַעַן בְּעֵבֶר הַיַּרְדֵּן הַמַּעֲרָבִי, וְאֶרֶץ מוֹאָב הָיְתָה בְּעֵבֶר הַיַּרְדֵּן בְּמִזְרָחוֹ, מִתּוֹךְ שֶׁשָּׁלְטוּ בְּיִשְׂרָאֵל וְעָבְרוּ אֶת הַיַּרְדֵּן, יָרְשׁוּ אֶת יְרִיחוֹ, כְּמוֹ שֶׁכָּתוּב לְמַעְלָה (פסוק יג) וְנָתְנוּ אֶת סַרְנֵיהֶם וּשְׁלִיטֵיהֶם עַל יִשְׂרָאֵל:\",2,0],[2,126,3,28,\"רִדְפוּ. לַהֲרֹג אֶת כָּל מוֹאָב שֶׁבְּעֵבֶר הַיַּרְדֵּן שֶׁלָּנוּ:\",1,0],[2,126,3,28,\"וַיִּלְכְּדוּ אֶת מַעְבְּרוֹת הַיַּרְדֵּן. שֶׁלֹּא יַעַבְרוּ מוֹאָב לָנוּס וְלָשׁוּב אֶל אַרְצָם:\",2,0],[2,126,3,29,\"כָּל שָׁמֵן. (תרגום:) כָּל גְּבַר אֵימְתָן:\",1,0],[2,126,3,31,\"מַלְמַד. הוּא דָּרְבָן, מַרְדֵּעַ, אגויילו״ן בְּלַעַ״ז:\",1,0],[2,126,4,2,\"בַּחֲרֹשֶׁת הַגּוֹיִם. שֵׁם עִיר, עַל שֵׁם שֶׁהָיְתָה חֲזָקָה וְשׁוֹלֶטֶת:\",1,0],[2,126,4,3,\"לָחַץ אֶת בְּנֵי יִשְׂרָאֵל בְּחָזְקָה. דָּרַשׁ רַבִּי תַּנְחוּמָא (צו ב): בְּגִדּוּפִין, וְכֵן הוּא אוֹמֵר (מלאכי ג:יג): חָזְקוּ עָלַי דִּבְרֵיכֶם:\",1,0],[2,126,4,4,\"אֵשֶׁת לַפִּידוֹת. שֶׁהָיְתָה עוֹשָׂה פְּתִילוֹת לַמִּקְדָּשׁ:\",1,0],[2,126,4,5,\"תַּחַת תֹּמֶר. תְּמָרִים הָיוּ לָהּ בִּירִיחוֹ:\",1,0],[2,126,4,5,\"בֵּין הָרָמָה וּבֵין בֵּית אֵל בְּהַר אֶפְרָיִם. לְפִי תַּרְגּוּמוֹ שֶׁל יוֹנָתָן יֵשׁ לִלְמֹד שֶׁאֵין מִקְרָא זֶה כְּמַשְׁמָעוֹ, וְאֵין אֵלּוּ סִימָנֵי מְקוֹם יְשִׁיבָתָהּ, אֶלָּא לָמַדְנוּ שֶׁאִשָּׁה עֲשִׁירָה הָיְתָה וּמִן הַמְּקוֹמוֹת הָאֵלּוּ הָיְתָה פַּרְנָסָתָהּ, וְהִיא יוֹשֶׁבֶת בְּעִירָהּ, עֲטָרוֹת שְׁמָהּ:\",2,0],[2,126,4,5,\"תַּחַת תֹּמֶר. תְּמָרִים הָיוּ לָהּ בִּירִיחוֹ, וּכְרָמִים בָּרָמָה, וְזֵיתִים בְּבִקְעַת בֵּית אֵל, שֶׁהוּא מְקוֹם שָׁמֵן, וְעָפָר חִוָּר בְּהַר אֶפְרַיִם, (תרגום:) ׳בְּטוּר מַלְכָּא׳, אוֹמֵר אֲנִי שֶׁמּוֹכְרִין אוֹתָהּ לְיוֹצְרֵי חֶרֶשׂ. וְיֵשׁ פּוֹתְרִין: ׳עָפָר חִוָּר׳, שְׂדֵה זֶרַע, כְּמוֹ (משנה שביעית ב:א): שְׂדֵה הַלָּבָן:\",3,0],[2,126,4,6,\"הֲלֹא צִוָּה. בְּיַד מֹשֶׁה (דברים כ:יז): כִּי הַחֲרֵם תַּחֲרִימֵם, כָּךְ שְׁנוּיָה בִּמְכִילְתָא (בא יב):\",1,0],[2,126,4,10,\"וַיַּעַל בְּרַגְלָיו. עִמּוֹ:\",1,0],[2,126,4,11,\"אֵלוֹן בְּצַעֲנַנִּים. (תרגום:) מֵישַׁר אַגְנַיָּא, מְקוֹם מֵישַׁר שֶׁל בְּצָעִים, מריש״ק בְּלַעַ״ז וְהוּא אַגְנַיָּא גֵּבִים, כְּמִין גּוּמוֹת שֶׁהַמַּיִם נִקְבָּצִים שָׁם, ׳אַגְנֵי דְּאַרְעָא מִקְרוֹן׳ (קידושין סא א):\",1,0],[2,126,4,13,\"מֵחֲרֹשֶׁת הַגּוֹיִם אֶל נַחַל קִישׁוֹן. הִזְעִיקָם שֶׁיֵּלְכוּ אֶל נַחַל קִישׁוֹן מֵחֲרֹשֶׁת הַגּוֹיִם שֶׁהוּא יוֹשֵׁב שָׁם:\",1,0],[2,126,4,18,\"בַּשְּׂמִיכָה. תִּרְגֵּם יוֹנָתָן: בְּגוֹנְכָא, וּפֵרַשׁ רַב הַאי (שבת נא א): גּוֹנְכָא - גְּלוּפְקְרִין, קוט״א בְּלַעַ״ז:\",1,0],[2,126,4,19,\"נֹאד הֶחָלָב. שֶׁהֶחָלָב מַכְבִּיד אֶת הַגּוּף לִהְיוֹת נִרְדָּם:\",1,0],[2,126,4,20,\"עֲמֹד פֶּתַח הָאֹהֶל. זָרְזִי עַצְמֵךְ כְּזָכָר. וְיֵשׁ פּוֹתְרִים: ׳עֲמֹד׳, כְּמוֹ לַעֲמֹד:\",1,0],[2,126,4,21,\"יְתַד הָאֹהֶל. קבילי״ל בְּלַעַ״ז, שֶׁתּוֹקְעִין בָּאָרֶץ עִם שִׁפּוּלֵי הָאֹהֶל לְפוֹשְׁטוֹ:\",1,0],[2,126,4,21,\"הַמַּקֶּבֶת. (תרגום:) אַרְזַפְתָּא, מרטי״ל בְּלַעַ״ז:\",2,0],[2,126,4,21,\"בַּלָּאט. (תרגום:) בְּרָז, חֶרֶשׁ:\",3,0],[2,126,4,21,\"וַתִּצְנַח בָּאָרֶץ. (תרגום:) וּנְעָצַת בְּאַרְעָא:\",4,0],[2,126,4,22,\"בְּרַקָּתוֹ. (תרגום:) בְּצִידְעֵיהּ, ניל״ה טימפי״ה בְּלַעַ״ז, וּתְחָבָהּ בְּרַקָּתוֹ וּבָאָרֶץ:\",1,0],[2,126,5,2,\"בִּפְרֹעַ פְּרָעוֹת בְּיִשְׂרָאֵל בְּהִתְנַדֵּב עָם. כְּשֶׁבָּאוּ פְּרָצוֹת עַל יִשְׂרָאֵל שֶׁפָּרְצוּ בָּהֶם אוֹיְבֵיהֶם עַל עָזְבָם אֶת ה׳, וְהִתְנַדֵּב הָעָם לָשׁוּב בִּתְשׁוּבָה, מֵעַתָּה בָּרְכוּ אֶת ה׳ עַל הַתְּשׁוּעוֹת שֶׁעָשָׂה:\",1,0],[2,126,5,3,\"אָנֹכִי אָנֹכִי. כָּפוּל, שָׁמַעְתִּי מִדְרַשׁ אַגָּדָה (ילקוט שמעוני ב מז) לֹא קִפֵּחַ הַקָּדוֹשׁ בָּרוּךְ הוּא שְׂכַר תָּבוֹר וְכַרְמֶל, שֶׁבָּאוּ לְמַתַּן תּוֹרָה לָתֵת עֲלֵיהֶם אֶת הַתּוֹרָה וְחָזְרוּ בְּבֹשֶׁת הַפָּנִים, אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, סוֹף שֶׁאֲנִי פּוֹרֵעַ לָכֶם כִּפְלַיִם, נֶאֱמַר בְּסִינַי (שמות כ:ב) אָנֹכִי ה׳ אֱלֹהֶיךָ, בְּתָבוֹר יֵאָמַר: אָנֹכִי אָנֹכִי. נֶאֱמַר בְּסִינַי (שם) אָנֹכִי ה׳ אֱלֹהֶיךָ, בְּכַרְמֶל יֵאָמַר, כָּפוּל (מלכים א יח:לט) ה׳ הוּא הָאֱלֹהִים, ה׳ הוּא הָאֱלֹהִים, בִּימֵי אֵלִיָּהוּ:\",1,0],[2,126,5,4,\"ה׳ בְּצֵאתְךָ מִשֵּׂעִיר. זֶה מַתַּן תּוֹרָה, כְּמָה שֶׁנֶּאֱמַר (דברים לג:ב) וְזָרַח מִשֵּׂעִיר לָמוֹ, וּמַה עִנְיָנָהּ לְכָאן, כָּךְ אָמְרָה דְּבוֹרָה: קָשָׁה הִיא הַתּוֹרָה לִפְרֹשׁ מִמֶּנָּה וְטוֹבָה הִיא לִדְבַּק בָּהּ, שֶׁהֲרֵי בְּמוֹרָא וּבִגְבוּרָה נִתְּנָה, וּלְכָךְ נִמְסְרוּ יִשְׂרָאֵל בְּיַד אוֹיְבֵיהֶם עַל פְּרִישָׁתָם הֵימֶנָּה וּכְשֶׁהִתְנַדְּבוּ לַעֲסוֹק בָּהּ נוֹשְׁעוּ, כָּל זֶה יֵשׁ לִלְמֹד מִתַּרְגּוּמוֹ שֶׁל יוֹנָתָן:\",1,0],[2,126,5,4,\"נָטְפוּ. הֵזִילוּ טַל תְּחִיָּה:\",2,0],[2,126,5,5,\"הָרִים נָזְלוּ. כְּמַיִם נוֹזְלִים נָמוֹגוּ:\",1,0],[2,126,5,5,\"זֶה סִינַי. כְּבָר מְפֹרָשׁ (שמות יט:כ) מַה נִרְאָה בּוֹ: עָשַׁן כֻּלּוֹ, וְקוֹל, וְלַפִּידִים וְאֵשׁ:\",2,0],[2,126,5,5,\"מִפְּנֵי ה׳. וַהֲרֵי זֶה מִקְרָא קָצָר ׳זֶה סִינַי׳, מַה אֵרַע בּוֹ, מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה׳:\",3,0],[2,126,5,6,\"בִּימֵי שַׁמְגַּר בֶּן עֲנָת בִּימֵי יָעֵל. מְלַמֵּד שֶׁאַף יָעֵל שָׁפְטָה אֶת יִשְׂרָאֵל בְּיָמֶיהָ:\",1,0],[2,126,5,6,\"חָדְלוּ אֳרָחוֹת. הָיוּ יְרֵאִים יִשְׂרָאֵל לָצֵאת לְדַרְכָּם מִפְּנֵי הָאוֹיְבִים וְהָיוּ הוֹלְכִים דֶּרֶךְ עֲקַלָּתוֹן בְּהֵחָבֵא:\",2,0],[2,126,5,7,\"חָדְלוּ פְרָזוֹן. עָרֵי הַפְּרָזִי שֶׁאֵין לָהֶם חוֹמָה חָדְלוּ מִהְיוֹת יוֹשְׁבִים בָּהֶם מִפְּנֵי אוֹיְבֵיהֶם, וְנֶאֶסְפוּ אֶל עָרֵי הַמִּבְצָר:\",1,0],[2,126,5,7,\"עַד שַׁקַּמְתִּי. כְּמוֹ שֶׁקַּמְתִּי, וְכֵן (שופטים ו:יז) שָׁאַתָּה מְדַבֵּר עִמִּי:\",2,0],[2,126,5,8,\"יִבְחַר אֱלֹהִים חֲדָשִׁים אָז לָחֶם שְׁעָרִים. כְּשֶׁבָּחַר לוֹ יִשְׂרָאֵל אֱלֹהִים חֲדָשִׁים, אָז הֻזְקְקוּ לְמִלְחָמָה בְּשַׁעֲרֵיהֶם, רְאוּ עַתָּה בְּהִתְנַדְּבָם, אִם יֵרָאֶה בְּיִשְׂרָאֵל מָגֵן וָרֹמַח, שֶׁצָּרִיךְ לְהִלָּחֵם בְּאַרְבָּעִים אֶלֶף רָאשֵׁי גְיָסוֹת שֶׁהֵבִיא הַגּוֹי עֲלֵיהֶם, וְכֻלָּם הֲמָמָם הַמָּקוֹם בְּמִלְחֶמֶת הַכּוֹכָבִים (פסוק כא) וְנַחַל קִישׁוֹן גְּרָפָם:\",1,0],[2,126,5,8,\"שְׁעָרִים. כְּמוֹ (דברים יז:ב) כִּי יִמָּצֵא בְקִרְבְּךָ בְּאַחַד שְׁעָרֶיךָ, עֲיָירוֹת:\",2,0],[2,126,5,9,\"לִבִּי. אֲנִי דְּבוֹרָה לְחוֹקְקֵי יִשְׂרָאֵל, לֶאֱהֹב אֶת חַכְמֵי יִשְׂרָאֵל שֶׁהִתְנַדְּבוּ בָּעָם, לֵאמֹר: בָּרְכוּ אֶת ה׳ וְשׁוּבוּ אֵלָיו:\",1,0],[2,126,5,10,\"רֹכְבֵי אֲתֹנוֹת צְחֹרוֹת. הַסּוֹחֲרִים וְהַשָּׂרִים שֶׁיִּרְכְּבוּ מֵעַתָּה עַל אֲתוֹנוֹת לְבָנוֹת הַחֲשׁוּבוֹת, מִבְּלִי יִרְאָה וְדַאֲגַת אוֹיְבֵיהֶם, וְאוֹתָן שֶׁיּוֹשְׁבִין עַל מִדִּין, לְשׁוֹן דַּיָּנִים, שֶׁהָיוּ יְרֵאִים לַעֲשׂוֹת מִשְׁפָּט בְּפַרְהֶסְיָא, וְכֵן תִּרְגֵּם יוֹנָתָן: דַּהֲווֹ מִתְחַבְּרִין לְמֵיתַב עַל דִּינָא, וְאוֹתָן שֶׁהוֹלְכִין רַגְלִי עַל דֶּרֶךְ, שִׂיחוּ וְסַפְּרוּ אֶת הַתְּשׁוּעָה הַזֹּאת, אֲשֶׁר מִקּוֹל הַמְחַצְּצִים אֶתְכֶם, אוֹרְבִים, לִסְטִים וּמוֹכְסִין, הַיּוֹשְׁבִין גְּדוּדִים בְּמַעֲרָכוֹת לֶאֱרֹב בְּעָבְרֵי הַמַּיִם, שָׁם יִתְּנוּ עַתָּה רוֹכְבֵי הָאֲתוֹנוֹת וְהוֹלְכֵי עַל דֶּרֶךְ אֶת צִדְקוֹת ה׳, וּמַה הֵן הַצְּדָקוֹת (פסוק יא) צִדְקוֹת פִּרְזוֹנוֹ בְּיִשְׂרָאֵל שֶׁהִשְׁקִיט אֶת יִשְׂרָאֵל, לִשְׁכּוֹן פְּרָזוֹן וְלָצֵאת מְפֻזָּרִים בִּיחִידִי, שֶׁלֹּא בַּאֲסִיפַת עָם:\",1,0],[2,126,5,11,\"מְחַצְצִים. פָּתַר מְנַחֵם: עוֹרְכֵי מִלְחָמָה וְסוֹדְרֵי קְרָב, וְחִבְּרוֹ עִם (משלי ל:כז) מֶלֶךְ אֵין לָאַרְבֶּה וַיֵּצֵא חֹצֵץ כֻּלּוֹ, לְשׁוֹן גְּדוּדִים. דָּבָר אַחֵר:\",1,0],[2,126,5,11,\"מִקּוֹל מְחַצְצִים בֵּין מַשְׁאַבִּים. כְּשֶׁהֱיִיתֶם הוֹלְכִים בֵּין מַשְׁאַבִּים לִשְׁאֹב מַיִם, הֱיִיתֶם יְרֵאִים מִקּוֹל אֲבָנִים, חַלּוּקֵי הַנַּחַל, קיזל״ש בְּלַעַ״ז, שֶׁהָעוֹבֵר עֲלֵיהֶם נִשְׁמָע קוֹלָם, וֶהֱיִיתֶם יְרֵאִים שֶׁלֹּא יַרְגִּישׁוּ בָכֶם אוֹיְבֵיכֶם, מֵעַכְשָׁיו אֵין לָחוּשׁ עַל זֹאת, וּמִשּׁוּם הָכִי מִצְוָה עֲלֵיכֶם לִיתֵּן הוֹדָיָה לִשְׁמוֹ:\",2,0],[2,126,5,11,\"מְחַצְצִים. לְשׁוֹן אַבְנֵי חִלּוּקֵי הַנַּחַל, כְּמוֹ (איכה ג:טז): ״וַיַּגְרֵס בֶּחָצָץ״:\",3,0],[2,126,5,11,\"אָז יָרְדוּ לַשְּׁעָרִים. חָזְרוּ לְעָרֵי מוֹשְׁבוֹתָם שֶׁבָּרְחוּ מֵהֶם לֵיאָסֵף אֶל עָרֵי הַמִּבְצָר:\",4,0],[2,126,5,12,\"עוּרִי עוּרִי דְּבוֹרָה. לְשׁוֹן שֶׁבַח כִּפְשׁוּטוֹ, הִתְגַּבְּרִי בְּשִׁירָתֵךְ וְרַבּוֹתֵינוּ אָמְרוּ (פסחים סו:) מִפְּנֵי שֶׁנִּתְהַלְּלָה וְאָמְרָה (פסוק ז) עַד שַׁקַּמְתִּי דְּבוֹרָה, נִסְתַּלְּקָה הֵימֶנָּה רוּחַ הַקֹּדֶשׁ:\",1,0],[2,126,5,13,\"אָז יָרַד שָׂרִיד לְאַדִּירִים. יָרַד - יִרְדֶּה, כְּמוֹ (ישעיהו מה:א) לְרַד לְפָנָיו גוֹיִם, שְׂרִידֵי יִשְׂרָאֵל רָדוּ בְּאַדִּירֵי הַגּוֹיִם:\",1,0],[2,126,5,13,\"ה׳ יְרַד לִי בַּגִּבּוֹרִים. יִרְדֶּה לִי אֶת גִּבּוֹרֵי הַגּוֹיִם:\",2,0],[2,126,5,14,\"מִנִּי אֶפְרַיִם. מִן אֶפְרַיִם יָצָא שׁוֹרֶשׁ יְהוֹשֻׁעַ בֶּן נוּן, לִרְדּוֹת בַּעֲמָלֵק לַחֲלֹשׁ אוֹתוֹ לְפִי חֶרֶב, וּמְחֻבָּר מִקְרָא זֶה לְעֶלְיוֹן, לְפָרֵשׁ: ה׳ יְרַד לִי בַּגִּבּוֹרִים, אֶת יְהוֹשֻׁעַ הֵקִים לְרַד בַּעֲמָלֵק:\",1,0],[2,126,5,14,\"אַחֲרֶיךָ. יָקוּם מִשֵּׁבֶט בִּנְיָמִין שָׁאוּל בֶּן קִישׁ שֶׁיִּגְרְמֶנּוּ וִיעַמֵּם אוֹתוֹ כְּגֶחָלִים עוֹמְמוֹת וְיֵשׁ לִפְתּוֹר: ״בַּעֲמָמֶיךָ״, בְּחַיִל שֶׁל מָאתַיִם אֶלֶף רַגְלִי שֶׁבָּא שָׁאוּל עֲלֵיהֶם:\",2,0],[2,126,5,14,\"מִנִּי מָכִיר יָרְדוּ מְחֹקְקִים. שָׂרִים גְּדוֹלִים שֶׁכָּבְשׁוּ אֶת הָאֱמוֹרִי, אֲשֶׁר כָּבְשׁוּ (דברים ג:ד) שִׁשִּׁים עִיר כָּל חֶבֶל אַרְגּוֹב שֶׁכָּבַשׁ יָאִיר:\",3,0],[2,126,5,15,\"וְשָׂרַי בְּיִשָּׂשכָר. שָׂרִים שֶׁבְּיִשָּׂשכָר, הֵם סַנְהֶדְרָאוֹת עוֹסְקִין בַּתּוֹרָה, (דברי הימים א יב:לג) יוֹדְעֵי בִינָה לָעִתִּים, הֵם תָּמִיד עִם דְּבוֹרָה לְלַמֵּד בְּיִשְׂרָאֵל חֹק וּמִשְׁפָּט:\",1,0],[2,126,5,15,\"וְשָׂרַי בְּיִשָּׂשכָר. יוּ״ד זוֹ טְפֵלָה הִיא וְאֵינָהּ מְשַׁמֶּשֶׁת כְּלוּם, וַהֲרֵי הִיא כְּיוּ״ד (תהלים ח:ח) בַּהֲמוֹת שָׂדַי, (ירמיהו כב:יד) וְקָרַע לוֹ חַלּוֹנָי:\",2,0],[2,126,5,15,\"וְיִשָּׂשכָר כֵּן בָּרָק. וּשְׁאָר הָעָם שֶׁל יִשָּׂשכָר, כֵּן הֵם עִם בָּרָק לְכָל אֲשֶׁר יְצַוֶּה:\",3,0],[2,126,5,15,\"בָּעֵמֶק שֻׁלַּח בְּרַגְלָיו. שְׁלָחָם בְּכָל שְׁלִיחוּתוֹ, וְלֶאֱסוֹף אֶת הָעָם וּלְכָל צָרְכֵי הַמִּלְחָמָה:\",4,0],[2,126,5,15,\"בִּפְלַגּוֹת רְאוּבֵן. אֲבָל בְּחִלּוּקֵי לִבּוֹ שֶׁל רְאוּבֵן רַבּוּ חִקְקֵי לֵב. (תרגום:) נִכְלֵי לִיבָּא, עָרְמוּמִית, וּמָה הִיא עָרְמוּמִיתוֹ, יָשַׁב לוֹ בֵּין מִשְׁפְּתֵי הַמִּלְחָמָה לִשְׁמוֹעַ מִי נוֹצֵחַ וְיִהְיֶה עִמּוֹ:\",5,0],[2,126,5,16,\"שְׁרִיקוֹת עֲדָרִים. לִשְׁמוֹעַ קוֹל עֶדְרֵי הַמִּלְחָמָה, לְמִי קוֹל עֲנוֹת גְּבוּרָה וּלְמִי קוֹל עֲנוֹת חֲלוּשָׁה:\",1,0],[2,126,5,17,\"בְּעֵבֶר הַיַּרְדֵּן שָׁכֵן. וְלֹא בָא אֶל הַמִּלְחָמָה, וְכֵן דָּן הִכְנִיס מָמוֹנוֹ בִּסְפִינוֹת לַעֲמוֹד וְלִבְרוֹחַ:\",1,0],[2,126,5,17,\"וְעַל מִפְרָצָיו. לִשְׁמוֹר פִּרְצוֹת אַרְצוֹ:\",2,0],[2,126,5,18,\"זְבֻלוּן עַם חֵרֵף וְגוֹ׳. בִּזָּה נַפְשׁוֹ וְהִפְקִיר עַצְמוֹ לָמוּת בַּמִּלְחָמָה עִם בָּרָק, וְכֵן נַפְתָּלִי עַל מְרוֹמֵי שָׂדֶה עַל הַר תָּבוֹר:\",1,0],[2,126,5,19,\"בְּתַעְנַךְ עַל מֵי מְגִדּוֹ. תִּרְגֵּם יוֹנָתָן: בְּתַעֲנַךְ הֲווֹ שָׁרָן וּמָטָן עַל מֵי מְגִדּוֹ, רֹאשׁ הַמַּחֲנֶה בְּתַעֲנַךְ וּמַגִּיעַ עַד מֵי מְגִדּוֹ:\",1,0],[2,126,5,19,\"בֶּצַע כֶּסֶף לֹא לָקָחוּ. חִנָּם בָּאוּ לְעֶזְרַת סִיסְרָא, לֹא בִּקְשׁוּ מִמֶּנּוּ שָׂכָר:\",2,0],[2,126,5,20,\"מִן שָׁמַיִם נִלְחָמוּ. וְאַף הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח בָּם צְבָאָיו שֶׁאֵינָם רוֹצִים שׁוּם שָׂכָר:\",1,0],[2,126,5,20,\"מִמְּסִלּוֹתָם. רֹאשׁ הַכּוֹכָב בַּשָּׁמַיִם וְסוֹפוֹ בָּאָרֶץ, מִכָּאן אָמְרוּ (תנחומא בראשית ה) עָבְיוֹ שֶׁל רָקִיעַ כַּאֲוִיר שֶׁבֵּין שָׁמַיִם לָאָרֶץ, שֶׁהַכּוֹכָב תָּקוּעַ בָּרָקִיעַ כְּמִין נֶגֶר בְּדֶלֶת, מִדַּת אָרְכּוֹ כְּעָבְיוֹ שֶׁל רָקִיעַ, וּמִן הַמִּקְרָא שֶׁמֵּעִיד ׳מִמְּסִלּוֹתָם נִלְחָמוּ׳, אָנוּ שׁוֹמְעִין שֶׁעָבְיוֹ שֶׁל רָקִיעַ כְּגוֹבַהּ שָׁמַיִם מִן הָאָרֶץ:\",2,0],[2,126,5,21,\"גְּרָפָם. טֵאטֵם מִן הָעוֹלָם, כְּמַגְרֵפָה זוֹ שֶׁגּוֹרֶפֶת אֶת הָאֵפֶר מִן הַכִּירָה:\",1,0],[2,126,5,21,\"נַחַל קְדוּמִים. שֶׁנַּעֲשָׂה עָרֵב לַיָּם עַל זֶה מִימוֹת מִצְרַיִם, כִּדְאִיתָא בִּפְסָחִים (קיח:):\",2,0],[2,126,5,21,\"תִּדְרְכִי נַפְשִׁי. בָּרַגְלַיִם אֶת עֹז גִּבּוֹרֵי כְנָעַן:\",3,0],[2,126,5,22,\"הָלְמוּ עִקְּבֵי סוּס. נִשְׁתַּלְּפוּ טַלְפֵי סוּסֵיהֶם, שֶׁהָיָה חֹם הַכּוֹכָב מַרְתִּיחַ אֶת הַטִּיט וְהַצִּפּוֹרֶן נִשְׁמְטָה, כְּמוֹ שֶׁמּוֹלְגִין אֶת הָרַגְלַיִם בְּרוֹתְחִין וְהַטְּלָפִים נִשְׁמָטִים, מִתּוֹךְ שֶׁנִּשְׁתַּלְּפוּ נֶהֶלְמוּ הָרַגְלַיִם:\",1,0],[2,126,5,22,\"מִדַּהֲרוֹת דַּהֲרוֹת אַבִּירָיו. שֶׁהָיוּ מַרְקִידִים אֶת סוּסֵיהֶם בַּמִּלְחָמָה, כְּמוֹ (נחום ג:ב) וְסוּס דֹּהֵר, הוּא לְשׁוֹן הַרְקָדַת הַסּוּס:\",2,0],[2,126,5,23,\"אוֹרוּ מֵרוֹז. אָמְרֵי לַהּ כּוֹכְבָא הֲוָה, וְאָמְרֵי לַהּ גַּבְרָא חֲשִׁיבָא הֲוָה (מועד קטן טז.), וְהָיָה סָמוּךְ לִמְקוֹם הַמִּלְחָמָה וְלֹא בָא:\",1,0],[2,126,5,23,\"אָמַר מַלְאַךְ ה׳. אָמַר בָּרָק בִּשְׁלִיחוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,126,5,23,\"יוֹשְׁבֶיהָ. הַיּוֹשְׁבִים בְּאַרְבַּע אַמּוֹת שֶׁלּוֹ (שם) בְּאַרְבַּע מְאָה שִׁיפּוּרֵי שַׁמְּתֵיהּ בָּרָק לְמֵרוֹז:\",3,0],[2,126,5,23,\"לְעֶזְרַת ה׳. כִּבְיָכוֹל, שֶׁמִּי שֶׁהוּא עוֹזֵר אֶת יִשְׂרָאֵל, כְּעוֹזֵר אֶת הַשְּׁכִינָה:\",4,0],[2,126,5,24,\"מִנָּשִׁים בָּאֹהֶל. שָׂרָה, שֶׁנֶּאֱמַר בָּהּ (בראשית יח:ט) הִנֵּה בָאֹהֶל. רִבְקָה שֶׁנֶּאֱמַר בָּהּ (בראשית כד:סז) וַיְבִיאֶהָ יִצְחָק הָאֹהֱלָה. רָחֵל וְלֵאָה, שֶׁנֶּאֱמַר בָּהֶן (בראשית לא:לג) וַיֵּצֵא מֵאֹהֶל לֵאָה וְגוֹ׳:\",1,0],[2,126,5,24,\"מִנָּשִׁים בָּאֹהֶל תְּבֹרָךְ. יָעֵל לָמָּה - הֵן יָלְדוּ וְגִדְּלוּ, וְאִם לֹא יָעֵל הֲרֵי הָרָשָׁע הַזֶּה בָּא וּמְאַבְּדָן, כָּךְ הוּא בִּבְרֵאשִׁית רַבָּה (מח:טו). דָּבָר אַחֵר, אַף יָעֵל הָיְתָה יוֹשֶׁבֶת אֹהָלִים, לְפִיכָךְ הִזְכִּיר אוֹתָהּ בְּבִרְכַּת אֹהָלִים:\",2,0],[2,126,5,25,\"חָלָב נָתָנָה. לָדַעַת אִם לִבּוֹ עָלָיו שֶׁיָּבִין בֵּין טַעַם מַיִם לְטַעַם חָלָב, כֵּן תִּרְגֵּם יוֹנָתָן:\",1,0],[2,126,5,25,\"בְּסֵפֶל אַדִּירִים. בְּסֵפֶל שֶׁשּׁוֹתִין בּוֹ מַיִם, שֶׁהַמַּיִם נִקְרְאוּ ׳אַדִּירִים׳, שֶׁנֶּאֱמַר (שמות טו:י): בְּמַיִם אַדִּירִים:\",2,0],[2,126,5,26,\"לְהַלְמוּת עֲמֵלִים. סִיסְרָא, שֶׁהָיָה עָמֵל וְיָגֵעַ:\",1,0],[2,126,5,26,\"מָחֲקָה. לְשׁוֹן חִיקּוּי:\",2,0],[2,126,5,26,\"וּמָחֲצָה. לְשׁוֹן מַחַץ:\",3,0],[2,126,5,26,\"וְחָלְפָה. יוֹצֵא מִצַּד אַחֵר:\",4,0],[2,126,5,28,\"וַתְּיַבֵּב. לְשׁוֹן דִּבּוּר, כְּמוֹ (ישעיהו נז:יט) נִיב שְׂפָתַיִם וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ (ראש השנה לג:) לְשׁוֹן גְּנִיחָה, כִּתְרוּעָה, דִּמְתַרְגְּמִינָן ׳יְבָבָא׳ (ויקרא כג:כד). וַאֲנִי אוֹמֵר: לְשׁוֹן רְאִיָּה, כְּמוֹ (זכריה ב:ב) בָּבַת עֵינִי, וְכֵן חִבְּרוֹ מְנַחֵם:\",1,0],[2,126,5,28,\"אֶשְׁנָב. חַלּוֹן:\",2,0],[2,126,5,29,\"חַכְמוֹת שָׂרוֹתֶיהָ תַּעֲנֶינָה. הַחֲכָמוֹת שֶׁבְּשָׂרוֹתֶיהָ, לְכָךְ נָקוּד חֵי״ת פַּתַּ״ח, חָכְמוֹת שֶׁהוּא שֵׁם דָּבָר נָקוּד חֲטַ״ף קָמַ״ץ, כְּמוֹ (משלי יד:א) רָאמוֹת לֶאֱוִיל חָכְמוֹת, וְזֶה נָקוּד חַכְמוֹת, וְכֵן (שם יד:א) חַכְמוֹת נָשִׁים בָּנְתָה בֵיתָהּ, חַכְמוֹת שֶׁבַּנָּשִׁים:\",1,0],[2,126,5,29,\"תַּעֲנֶינָּה. דַּגְשׁוּת שֶׁל נוּ״ן מְשַׁמֶּשֶׁת בִּמְקוֹם נוּ״ן שְׁלִישִׁית, וּפִתְרוֹנוֹ תַּעֲנֶינָּה אוֹתָהּ, דַּגְשׁוּת נוּ״ן מְשַׁמֶּשֶׁת בִּמְקוֹם ׳אוֹתָהּ׳, כְּמוֹ (ויקרא ו:יד) מֻרְבֶּכֶת תְּבִיאֶנָּה:\",2,0],[2,126,5,29,\"אַף הִיא תָּשִׁיב אֲמָרֶיהָ. תַּנְחוּמִין לְעַצְמָהּ: מָה אֲנִי מִתְמַהּ תְּמִיהָ עַל עִכּוּב בְּנִי:\",3,0],[2,126,5,30,\"הֲלֹא יִמְצְאוּ יְחַלְּקוּ שָׁלָל. וְהוּא מְעַכְּבָן:\",1,0],[2,126,5,30,\"רַחֲמָתַיִם לְרֹאשׁ גֶּבֶר. מְעַנִּים נָשִׁים יָפוֹת בְּיִשְׂרָאֵל, וְכָל אִישׁ מֵהֶם יֵשׁ לוֹ בְּמִטָּתוֹ שְׁתַּיִם וְשָׁלֹשׁ נָשִׁים:\",2,0],[2,126,5,31,\"כֵּן יֹאבְדוּ. דְּבוֹרָה אָמְרָה: תַּנְחוּמִין שֶׁל הֶבֶל הֵן לָהּ, כֵּן יֹאבְדוּ כָל אוֹיְבֶיךָ ה׳, כַּאֲשֶׁר אָבַד הוּא:\",1,0],[2,126,5,31,\"וְאֹהֲבָיו כְּצֵאת הַשֶּׁמֶשׁ בִּגְבוּרָתוֹ. לֶעָתִיד לָבֹא, (ישעיהו ל:כו) שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים, שֶׁהִיא עַל אַחַת שְׁלֹשׁ מֵאוֹת וְאַרְבָּעִים וְשָׁלֹשׁ כְּמִסְפַּר אַרְבָּעִים וְתֵשַׁע שְׁבִיעִיּוֹת:\",2,0],[2,126,5,31,\"וַתִּשְׁקֹט הָאָרֶץ. אֵין זֶה מִדִּבְרֵי דְבוֹרָה אֶלָּא מִדִּבְרֵי כּוֹתֵב הַסֵּפֶר:\",3,0],[2,126,6,1,\"וַיַּעֲשׂוּ הָרַע. עַד כָּאן נֶאֱמַר ׳וַיּוֹסִיפוּ׳, שֶׁהָיָה נִצְבָּר חֵטְא עַל חֵטְא, אֲבָל בְּשִׁירָה זוֹ נִמְחַל לָהֶם כָּל אֲשֶׁר עָשׂוּ, וְעַכְשָׁיו מַתְחִילִין לַחֲטוֹא, כָּךְ נִדְרַשׁ בְּאַגָּדַת תְּהִלִּים (מדרש תהלים יח ו):\",1,0],[2,126,6,2,\"הַמִּנְהָרוֹת. (תרגום:) מַטְמוֹרִיתָא, וּבִלְשׁוֹן לַעַ״ז: וודו״ש, וְעַל שֵׁם שֶׁעוֹשִׂין בָּהֶם מָאוֹר קָטָן בְּמָקוֹם שֶׁאֵין נִיכָּר קוֹרְאָן מִנְהָרוֹת, לויישיט״ש בְּלַעַ״ז:\",1,0],[2,126,6,2,\"מְעָרוֹת. גרוטי״ה בְּלַעַ״ז:\",2,0],[2,126,6,2,\"מְצָדוֹת. פליישדי״ץ בְּלַעַ״ז, שֶׁעוֹשִׂים בַּיְּעָרִים עַל יְדֵי הַפָּלַת הָאִילָנוֹת סָבִיב סָבִיב:\",3,0],[2,126,6,5,\"הֵם וּמִקְנֵיהֶם. לִרְעוֹת אֶת הַתְּבוּאָה:\",1,0],[2,126,6,8,\"אִישׁ נָבִיא. זֶה הַנָּבִיא הוּא פִּנְחָס, בְּ״סֵדֶר עוֹלָם״ (פרק ב):\",1,0],[2,126,6,11,\"אֲבִי הָעֶזְרִי. מִבְּנֵי אֲבִיעֶזֶר בֶּן גִּלְעָד בֶּן מְנַשֶּׁה:\",1,0],[2,126,6,11,\"וְגִדְעוֹן בְּנוֹ. אָבִיו הָיָה חוֹבְטָן וְהוּא כוֹבְרָן, אָמַר לוֹ: אַבָּא, זָקֵן אַתָּה וְאִם יָבֹאוּ הַמִּדְיָנִים לֹא תוּכַל לָנוּס, לֵךְ אַתָּה וַאֲנִי אֶחְבֹּט:\",2,0],[2,126,6,11,\"בַּגַּת. בְּקוֹרוֹת בֵּית הַבַּד:\",3,0],[2,126,6,12,\"ה׳ עִמְּךָ גִּבּוֹר הֶחָיִל. שֶׁנָּתַן לְךָ כֹּחַ כָּזֶה:\",1,0],[2,126,6,13,\"וְיֵשׁ ה׳ עִמָּנוּ. וְאִם יֵשׁ ה׳ עִמָּנוּ, לָמָּה מְצָאַתְנוּ וְגוֹ׳:\",1,0],[2,126,6,13,\"אֲשֶׁר סִפְּרוּ לָנוּ אֲבוֹתֵינוּ. פֶּסַח הָיָה, אָמַר לוֹ: אֶמֶשׁ הִקְרַנִי אַבָּא אֶת הַהַלֵּל, וּשְׁמַעְתִּיו שֶׁהָיָה אוֹמֵר (תהלים קיד:א): בְּצֵאת יִשְׂרָאֵל מִמִּצְרַיִם, ׳וְעַתָּה נְטָשָׁנוּ׳, אִם צַדִּיקִים הָיוּ אֲבוֹתֵינוּ, יַעֲשֶׂה לָנוּ בִּזְכוּתָם, וְאִם רְשָׁעִים הָיוּ, כְּשֵׁם שֶׁעָשָׂה לָהֶם נִפְלְאוֹתָיו חִנָּם כֵּן יַעֲשֶׂה לָנוּ, וְאַיֵּה כָל נִפְלְאוֹתָיו:\",2,0],[2,126,6,14,\"וַיִּפֶן אֵלָיו. הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַצְמוֹ:\",1,0],[2,126,6,14,\"בְּכֹחֲךָ זֶה. בְּכֹחַ הַזְּכוּת הַזֶּה שֶׁלִּמַּדְתָּ סָנֵגוֹרְיָא עַל בָּנַי, כָּךְ דָּרַשׁ רַבִּי תַּנְחוּמָא (מדרש תנחומא שופטים ד):\",2,0],[2,126,6,15,\"הִנֵּה אַלְפִּי. הָאֶלֶף שֶׁאֲנִי נִמְנֶה בּוֹ לִהְיוֹת תַּחַת שַׂר הָאֶלֶף, הוּא הָאֶלֶף הַדַּל בְּכָל אַלְפֵי מְנַשֶּׁה:\",1,0],[2,126,6,17,\"שָׁאַתָּה. כְּמוֹ שֶׁאַתָּה:\",1,0],[2,126,6,19,\"קֶמַח מַצּוֹת. לָמַדְנוּ שֶׁפֶּסַח הָיָה, יוֹם תְּנוּפַת הָעוֹמֶר, לְכָךְ נֶאֱמַר (לקמן ז:יג) וְהִנֵּה צְלִיל לֶחֶם שְׂעוֹרִים מִתְהַפֵּךְ וְגוֹ׳:\",1,0],[2,126,6,19,\"וְהַמָּרַק. וְהָרוֹטֶב:\",2,0],[2,126,6,22,\"אֲהָהּ. לְשׁוֹן דְּאָגָה, כְּלוֹמַר מַה תְּהֵא עָלַי:\",1,0],[2,126,6,22,\"כִּי עַל כֵּן רָאִיתִי. כִּי עַל אֲשֶׁר רָאִיתִי מַלְאַךְ ה׳, לְכָךְ אֲנִי דּוֹאֵג וְצוֹעֵק ׳אֲהָהּ׳:\",2,0],[2,126,6,24,\"וַיִּקְרָא לוֹ. גִּדְעוֹן לַמִּזְבֵּחַ:\",1,0],[2,126,6,24,\"ה׳ שָׁלוֹם. ה׳ הוּא שְׁלוֹמֵנוּ:\",2,0],[2,126,6,25,\"פַּר הַשּׁוֹר. פַּר הַבָּחוּר, שֶׁהַשּׁוֹר בֶּן יוֹמוֹ קָרוּי שׁוֹר:\",1,0],[2,126,6,25,\"וּפַר הַשֵּׁנִי. (תרגום:) וְתוֹרָא תִּנְיָנָא:\",2,0],[2,126,6,25,\"שֶׁבַע שָׁנִים. (תרגום:) דְּאִיתְפַּטַּם שֶׁבַע שְׁנִין לַעֲבוֹדָה זָרָה. שְׁמוֹנָה דְבָרִים הוּתְרוּ אוֹתוֹ הַלַּיְלָה: מוּקְצֶה, אֲשֵׁרָה, וְלַיְלָה, וּבָמָה וְכוּ׳, כִּדְאִיתָא בִּתְמוּרָה (כח ב):\",3,0],[2,126,6,26,\"רֹאשׁ הַמָּעוֹז. רֹאשׁ הַסֶּלַע:\",1,0],[2,126,6,31,\"הַאַתֶּם תְּרִיבוּן לַבַּעַל. בִּשְׁבִיל הַבַּעַל:\",1,0],[2,126,6,31,\"תּוֹשִׁיעוּן אוֹתוֹ. תִּנְקְמוּ נִקְמָתוֹ, וְכֵן (שמואל א כה:לג): וְהֹשֵׁעַ יָדִי לִי, דְּדָוִד בְּנָבָל:\",2,0],[2,126,6,31,\"אֲשֶׁר יָרִיב לוֹ. בִּשְׁבִילוֹ:\",3,0],[2,126,6,31,\"עַד הַבֹּקֶר. עַד הַבֹּקֶר הַמְתִּינוּ:\",4,0],[2,126,6,31,\"אִם אֱלֹהִים הוּא. יָרִיב הוּא לְעַצְמוֹ רִיבוֹ וְנִקְמָתוֹ, וּכְדֵי לִדְחוֹתָם עַד שֶׁיִּבְרַח גִּדְעוֹן הָיָה אוֹמֵר כֵּן:\",5,0],[2,126,6,32,\"יָרֶב בּוֹ. בְּגִדְעוֹן. אֵצֶל רִיב נוֹפֵל עִם, אוֹ אֶת, אוֹ בּוֹ, כְּמוֹ (בראשית לא:לו): וַיָּרֶב בְּלָבָן, אֲבָל ׳לוֹ׳ אֵינוֹ נוֹפֵל עַל הַלָּשׁוֹן, וְכָל ׳לוֹ׳ הַכְּתוּבִים כָּאן ׳בִּשְׁבִיל׳ הֵם:\",1,0],[2,126,6,34,\"רוּחַ ה׳. רוּחַ גְּבוּרָה:\",1,0],[2,126,6,34,\"וַיִּזָּעֵק אֲבִיעֶזֶר. כָּל הַמִּשְׁפָּחָה:\",2,0],[2,126,6,38,\"וַיְהִי כֵן. שֶׁהָיָה טַל עַל הַגִּזָּה לְבַדָּהּ יוֹתֵר מִבִּשְׁאָר מְקוֹמוֹת, כְּמוֹ שֶׁהוּא אוֹמֵר (פסוק לז): מְלֹא הַסֵּפֶל מַיִם, אֲבָל ׳עַל כָּל הָאָרֶץ חֹרֶב׳ לֹא נִתְקַיֵּם, שֶׁהַבְּרִית כְּרוּתָה לַטַּל שֶׁאֵינוֹ נֶעְצָר (תענית ג א):\",1,0],[2,126,6,38,\"וַיָּזַר. לְשׁוֹן מְכַבֵּשׁ, וְכֵן (ישעיהו א:ו): לֹא זֹרוּ וְלֹא חֻבָּשׁוּ, לֹא נֶחְבְּשׁוּ לְהוֹצִיא הַלֵּחָה:\",2,0],[2,126,7,1,\"מִגִּבְעַת הַמּוֹרֶה בָּעֵמֶק. (תרגום:) דְּמִסְתַּכְּיָא לְמֵישְׁרָא. הַמּוֹרֶה, לְשׁוֹן הוֹרָאָה וּרְאִיָּה, כְּמוֹ (משלי ו:יג) מוֹרֶה בְּאֶצְבְּעוֹתָיו, שֶׁמִּשָּׁם צוֹפִים וְרוֹמְזִים בָּעֵמֶק:\",1,0],[2,126,7,2,\"יִתְפָּאֵר. וונטי״ר בְּלַעַ״ז:\",1,0],[2,126,7,3,\"וַיִּצְפֹּר. בַּבֹּקֶר, לְשׁוֹן אֲרָמִי: צַפְרָא:\",1,0],[2,126,7,5,\"כֹּל אֲשֶׁר יָלֹק בִּלְשׁוֹנוֹ וְגוֹ׳ וְכֹל אֲשֶׁר יִכְרַע עַל בִּרְכָּיו לִשְׁתּוֹת. תַּצִּיג אוֹתוֹ לְבַד חוּץ מִסִּיעָתְךָ, כִּי הֵם לֹא יֵלְכוּ עִמְּךָ, שֶׁכָּךְ הֵם לְמוּדִים לִכְרוֹעַ לִפְנֵי עֲבוֹדַת גִּלּוּלִים:\",1,0],[2,126,7,6,\"הַמְלַקְקִים בְּיָדָם. אֵין זֶה דֶּרֶךְ כְּרִיעָה כְּלוֹקֵק בִּלְשׁוֹנוֹ:\",1,0],[2,126,7,12,\"נֹפְלִים בָּעֵמֶק. שׁוֹכְנִים בָּעֵמֶק:\",1,0],[2,126,7,13,\"צְלִיל. צָלוּל כְּתִיב, שֶׁהָיָה הַדּוֹר צָלוּל מִן הַצַּדִּיקִים:\",1,0],[2,126,7,13,\"צְלִיל לֶחֶם שְׂעֹרִים. (תרגום:) חֲרַר דְּלֶחֶם שְׂעוֹרִים, חֲרָרָה שֶׁאוֹפִין עַל הַגֶּחָלִים:\",2,0],[2,126,7,13,\"לֶחֶם שְׂעֹרִים. הוּא זְכוּת הָעוֹמֶר הַקָּרֵב בְּפֶסַח:\",3,0],[2,126,7,13,\"וַיַּכֵּהוּ וַיִּפֹּל. הָאֹהֶל: וַיַּהַפְכֵהוּ. הָאֹהֶל מִלְּמַטָּה לְמַעְלָה, וְנָפַל הָאֹהֶל:\",4,0],[2,126,7,15,\"אֶת מִסְפַּר הַחֲלוֹם. אֶת סִפּוּר הַחֲלוֹם, (תרגום:) יַת שׁוּעִית חֶלְמָא וְיַת פִּשְׁרֵיהּ:\",1,0],[2,126,7,15,\"וְאֶת שִׁבְרוֹ. וְאֶת מִמְכָּרוֹ, כְּלוֹמַר: וְאֶת פִּתְרוֹנוֹ:\",2,0],[2,126,7,16,\"שׁוֹפָרוֹת וְלַפִּידִים. לְהַזְכִּיר זְכוּת מַתַּן תּוֹרָה וּפְשׁוּטוֹ: לַיְלָה הָיָה, כְּמוֹ שֶׁכָּתוּב (פסוק ט) וְהָיָה חֹשֶׁךְ, לְפִיכָךְ נָשְׂאוּ שָׁם לַפִּידִים לְהָאִיר לָהֶם וּנְתָנוּם בַּכַּדִּים כְּדֵי שֶׁלֹּא יָבִינוּ בַּלַּפִּידִים:\",1,0],[2,126,7,17,\"מִמֶּנִּי תִרְאוּ. אֶת אֲשֶׁר אֲנִי עוֹשֶׂה, רְאוּ וַעֲשׂוּ כֵן:\",1,0],[2,126,7,18,\"אָנֹכִי וְכָל אֲשֶׁר אִתִּי. אֶחָד מִן הָרָאשִׁים, וּמֵאָה אִישׁ הָיָה עִמּוֹ (פסוק יט):\",1,0],[2,126,7,18,\"לַה׳ וּלְגִדְעוֹן. (תרגום:) חַרְבָּא דִּמְקַטְּלָא מִן קֳדָם ה׳ וְנִצְחָנָא עַל יְדֵי גִדְעוֹן:\",2,0],[2,126,7,19,\"הָקֵם הֵקִימוּ. כְּבָר בְּנֵי הַחַיִל אֶת הַשּׁוֹמְרִים שֶׁהָיְתָה מִשְׁמַרְתָּם בָּאַשְׁמֹרֶת הַתִּיכוֹנָה, שֶׁכֵּן דֶּרֶךְ בְּנֵי גְיָיסוֹת לְהַעֲמִיד שׁוֹמְרִים, אֵלּוּ יִשְׁמְרוּ שְׁלִישׁ הַלַּיְלָה הָרִאשׁוֹן וְאֵלּוּ שְׁלִישׁ הַשֵּׁנִי, וְאֵלּוּ שְׁלִישׁ הָאַחֲרוֹן:\",1,0],[2,126,7,19,\"וְנָפוֹץ הַכַּדִּים. וְלִשְׁבּוֹר הַכַּדִּים אֲשֶׁר בְּיָדָם:\",2,0],[2,126,7,21,\"וַיָּרִיעוּ. תְּרוּעַת מַסָּע וְנִיסָה:\",1,0],[2,126,7,24,\"וְלִכְדוּ לָהֶם אֶת הַמַּיִם. הַמַּפְסִיקִין בֵּין אֲרָם לְאֶרֶץ כְּנָעַן:\",1,0],[2,126,7,24,\"וְאֶת הַיַּרְדֵּן. שֶׁגַּם הוּא הָיָה מַפְסִיק:\",2,0],[2,126,7,25,\"הֵבִיאוּ אֶל גִּדְעוֹן מֵעֵבֶר לַיַּרְדֵּן. בַּבֹּקֶר, כְּשֶׁעָבַר גִּדְעוֹן אֶת הַיַּרְדֵּן לִרְדֹּף אַחַר זֶבַח וְצַלְמֻנָּע:\",1,0],[2,126,8,2,\"מַה עָשִׂיתִי עַתָּה כָּכֶם. מַה חָשׁוּב מַה שֶּׁעָשִׂיתִי בִּתְחִלָּתוֹ, כְּמַה שֶּׁעֲשִׂיתֶם אַתֶּם בַּסּוֹף:\",1,0],[2,126,8,2,\"הֲלֹא טוֹב עֹלְלוֹת. שֶׁבָּאוּ לְיֶדְכֶם בַּסּוֹף מִתְּחִלַּת הַבָּצִיר שֶׁבָּצַרְנוּ אֲנִי וּמִשְׁפַּחְתִּי, שֶׁהֲרֵי בְּיֶדְכֶם נָתַן ה׳ אֶת הַמְּלָכִים:\",2,0],[2,126,8,3,\"וּמַה יָּכֹלְתִּי. לַעֲשׂוֹת שֶׁיְּהֵא חָשׁוּב כְּמַעֲשֵׂה שֶׁלָּכֶם:\",1,0],[2,126,8,4,\"עֹבֵר הוּא וּשְׁלֹשׁ מֵאוֹת הָאִישׁ. עוֹבְרִים אֶת הַיַּרְדֵּן אַחֲרֵי זֶבַח וְצַלְמֻנָּע שֶׁעָבְרוּ אֶת הַיַּרְדֵּן תְּחִלָּה, וְהָיוּ מַשְׁחִיתִים מֵעֵבֶר לַיַּרְדֵּן אֶת אֶרֶץ רְאוּבֵן וְגָד וּמְנַשֶּׁה, וְעָבַר שָׁם כְּדֵי לִנְקֹם אַף בָּהֶם:\",1,0],[2,126,8,5,\"לְאַנְשֵׁי סֻכּוֹת. יִשְׂרָאֵל הָיוּ:\",1,0],[2,126,8,6,\"הֲכַף זֶבַח וְצַלְמֻנָּע בְּיָדֶךָ. שֶׁאַתָּה מִתְפָּאֵר שֶׁהִצַּלְתָּנוּ מִיַּד מִדְיָן:\",1,0],[2,126,8,7,\"הַבַּרְקֳנִים. רונצי״ש בְּלַעַ״ז:\",1,0],[2,126,8,10,\"בַּקַּרְקֹר. שֵׁם מָקוֹם:\",1,0],[2,126,8,11,\"דֶּרֶךְ הַשְּׁכוּנֵי בָאֳהָלִים. דֶּרֶךְ אֶרֶץ קֵדָר וַעֲרָב הַשּׁוֹכְנִים בַּמִּדְבָּר בְּאָהֳלֵיהֶם, שֶׁרוֹעִים מִקְנֶה תָּמִיד וְאֵין דָּרִים בְּבָתִּים:\",1,0],[2,126,8,11,\"מִקֶּדֶם לְנֹבַח וְיׇגְבְּהָה. שֶׁהֵם עָרֵי יִשְׂרָאֵל, וְלֹא רָצָה לֵילֵךְ שָׁם אֶלָּא דֶּרֶךְ עֲקַלָּתוֹן, כְּדֵי שֶׁלֹּא יַרְגִּישׁוּ בָהֶם, וִיהוּמַּם פִּתְאוֹם:\",2,0],[2,126,8,13,\"מִלְמַעֲלֵה הֶחָרֶס. עַד שֶׁלֹּא שָׁקְעָה הַשֶּׁמֶשׁ, בְּעוֹד הַחַמָּה נִרְאֵית גָּבוֹהַּ:\",1,0],[2,126,8,16,\"וַיֹּדַע בָּהֶם. (תרגום:) וּתְבַר בְּהוֹן:\",1,0],[2,126,8,18,\"אֶחָד כְּתֹאַר בְּנֵי הַמֶּלֶךְ. יוֹנָתָן תִּרְגֵּם: אֶחָד הָיָה בָהֶם שֶׁתּוֹאֲרוֹ כְּתוֹאַר בְּנֵי הַמֶּלֶךְ. וְיֵשׁ לְפוֹתְרוֹ: כָּמוֹךָ כָּמוֹהֶם, תּוֹאַר אֶחָד לָכֶם, כִּי כְתוֹאַר בְּנֵי מְלָכִים הָיוּ:\",1,0],[2,126,8,20,\"וְלֹא שָׁלַף הַנַּעַר חַרְבּוֹ. לְהָרְגָם, שֶׁהָיָה יָרֵא מֵהֶם:\",1,0],[2,126,8,21,\"הַשַּׂהֲרֹנִים. לוינ״ש בְּלַעַ״ז, שֶׁל זָהָב:\",1,0],[2,126,8,26,\"הַשַּׂהֲרֹנִים וְהַנְּטִיפוֹת. (תרגום:) עִנְקְיָא וּכְלִילָא:\",1,0],[2,126,8,27,\"וַיַּעַשׂ אוֹתוֹ גִדְעוֹן לְאֵפוֹד. לִהְיוֹת לְזִכָּרוֹן עַל תְּשׁוּעָה גְדוֹלָה, לִרְאוֹת כַּמָּה הָיָה חֵילָם כָּבֵד שֶׁבְּנִזְמֵי חֲשׁוּבֵיהֶם הָיָה כָּל הַזָּהָב הַזֶּה:\",1,0],[2,126,8,27,\"וַיִּזְנוּ כָל יִשְׂרָאֵל אַחֲרָיו. לְאַחַר מִיתַת גִּדְעוֹן:\",2,0],[2,126,8,33,\"בַּעַל בְּרִית. כָּךְ שְׁמוֹ:\",1,0],[2,126,8,35,\"וְלֹא עָשׂוּ חֶסֶד וְגוֹ׳. שֶׁהָרְגוּ אֶת בָּנָיו, כְּמוֹ שֶׁכָּתוּב בָּעִנְיָן (שופטים ט:ה):\",1,0],[2,126,9,4,\"וּפֹחֲזִים. בְּהוּלִים בְּמַעֲשֵׂיהֶם לַעֲשׂוֹת בְּלֹא תְבוּנָה:\",1,0],[2,126,9,6,\"עִם אֵלוֹן מֻצָּב. (תרגום:) מֵישַׁר קָמְתָא - מִישׁוֹר שֶׁהָיוּ בּוֹ מַצֵּבוֹת:\",1,0],[2,126,9,8,\"הָלוֹךְ הָלְכוּ הָעֵצִים. מָשָׁל הוּא:\",1,0],[2,126,9,8,\"לַזַּיִת. עָתְנִיאֵל בֶּן קְנַז (שופטים א:יג), הַבָּא מִשֵּׁבֶט יְהוּדָה שֶׁנִּקְרָא זַיִת, שֶׁנֶּאֱמַר (ירמיהו יא:טז): זַיִת רַעֲנָן יְפֵה פְרִי תֹאַר וְגוֹ׳:\",2,0],[2,126,9,9,\"דִּשְׁנִי. לְשׁוֹן שׁוּמָן:\",1,0],[2,126,9,10,\"לַתְּאֵנָה. דְּבוֹרָה:\",1,0],[2,126,9,11,\"אֶת מָתְקִי. דְּבַשׁ דְּבוֹרִים:\",1,0],[2,126,9,12,\"לַגָּפֶן. גִּדְעוֹן, שֶׁהוּא מִזֶּרַע יוֹסֵף (שופטים ו:יא), שֶׁנֶּאֱמַר בּוֹ (בראשית מט:כב) בֵּן פֹּרָת, (ותרגם שם אונקלוס:) כְּגוּפָן דִּנְצִיב וְכוּ׳:\",1,0],[2,126,9,13,\"הַמְשַׂמֵּחַ אֱלֹהִים. שֶׁאֵין אוֹמְרִים הַלְוִיִּם שִׁיר שֶׁל הַקָּרְבָּן אֶלָּא עַל הַנְּסָכִים:\",1,0],[2,126,9,14,\"אֶל הָאָטָד. ספינ״ה בְּלַעַ״ז:\",1,0],[2,126,9,15,\"אִם בֶּאֱמֶת. שֶׁאֲנִי הָגוּן לַמַּלְכוּת:\",1,0],[2,126,9,22,\"וַיָּשַׂר. עַל כָּרְחָם נָהַג רַבָּנוּת וּבְגַאֲוָה:\",1,0],[2,126,9,23,\"רוּחַ רָעָה. שִׂנְאָה, שלנ״ש מלטלינ״ט בְּלַעַ״ז:\",1,0],[2,126,9,26,\"גַּעַל בֶּן עֶבֶד. מֵאוּמָּה אַחֶרֶת הָיָה:\",1,0],[2,126,9,27,\"וַיַּעֲשׂוּ הִלּוּלִים. (תרגום:) וַעֲבַדוּ חַנְגִין:\",1,0],[2,126,9,28,\"מִי אֲבִימֶלֶךְ וּמִי שְׁכֶם. מִי אֲבִימֶלֶךְ לִהְיוֹת שַׂר עַל שְׁכֶם וּמִי שְׁכֶם לִהְיוֹת עֲבָדִים לַאֲבִימֶלֶךְ, הֲלֹא בֶּן יְרֻבַּעַל הָיָה אֲבִימֶלֶךְ מִן עָפְרַת אֲבִי הָעֶזְרִי (לעיל ו:יא):\",1,0],[2,126,9,28,\"וּזְבֻל פְּקִידוֹ. וְזֶה פְּקִיד הָעִיר שֶׁשְּׁמוֹ ׳זְבוּל׳, פְּקִידוֹ שֶׁל אֲבִימֶלֶךְ הוּא, וַאֲדוֹנָיו אֵין לוֹ מִשְׁפַּט מְלוּכָה בָּעִיר וְאַף פְּקִידוֹ אֵינוֹ כְּלוּם:\",2,0],[2,126,9,28,\"עִבְדוּ אֶת אַנְשֵׁי חֲמוֹר. אִם בָּאתֶם לִקְנוֹת לָכֶם אֲדוֹנִים, בֹּאוּ וְעִבְדוּ אֶת אַנְשֵׁי חֲמוֹר, שֶׁהָיָה נְשִׂיא הָאָרֶץ מִקֶּדֶם (בראשית לד:ב):\",3,0],[2,126,9,28,\"וּמַדּוּעַ נַעַבְדֶנּוּ. לַאֲבִימֶלֶךְ:\",4,0],[2,126,9,29,\"וַיֹּאמֶר לַאֲבִימֶלֶךְ. וַיֹּאמֶר גַּעַל בִּפְנֵי זְבוּל, הוֹדִיעַ לַאֲבִימֶלֶךְ:\",1,0],[2,126,9,29,\"רַבֶּה צְבָאֲךָ וָצֵאָה. מִן הַמָּקוֹם שֶׁאַתָּה שָׁם, וְנִרְאֶה אֶת גְּדֻלָּתְךָ:\",2,0],[2,126,9,31,\"בְּתָרְמָה. כְּמוֹ בְּמִרְמָה, בְּתַרְמִית, כְּלוֹמַר: בַּלָּט וּבַסֵּתֶר:\",1,0],[2,126,9,34,\"אַרְבָּעָה רָאשִׁים. אַרְבָּעָה כִּתּוֹת:\",1,0],[2,126,9,37,\"מֵעִם טַבּוּר הָאָרֶץ. (תרגום:) מִן תּוּקְפָא דְאַרְעָא, מֵהַר הַגָּבוֹהַּ שֶׁבְּכֻלָּם:\",1,0],[2,126,9,37,\"אֵלוֹן מְעוֹנְנִים (תרגום:) מֵישַׁר מְעוֹנְנִים:\",2,0],[2,126,9,42,\"וַיֵּצֵא הָעָם הַשָּׂדֶה. אַנְשֵׁי שְׁכֶם:\",1,0],[2,126,9,42,\"וַיַּגִּידוּ. הַמַּגִּידִים לַאֲבִימֶלֶךְ, שֶׁיָּצְאוּ בְּנֵי הָעִיר אֶל הַשָּׂדֶה לַעֲשׂוֹת חֶפְצֵיהֶם:\",2,0],[2,126,9,44,\"פֶּתַח שַׁעַר הָעִיר. שֶׁלֹּא יוּכְלוּ לִיכָּנֵס:\",1,0],[2,126,9,46,\"צְרִיחַ. יַעַר שֶׁכָּפוּ אִילָנוֹת וּפְסָגִים סָבִיב סָבִיב, וְקוֹרִין אוֹתוֹ פלייש״ר בְּלַעַ״ז:\",1,0],[2,126,9,46,\"בֵּית אֵל בְּרִית. אוֹתוֹ צְרִיחַ הָיָה שֶׁל בַּעַל בְּרִית, שֵׁם שֶׁל עֲבוֹדָה זָרָה שֶׁלָּהֶם, וְצַלְמוֹן (פסוק מח), יַעַר הָיָה שָׁם וְיֵשׁ פּוֹתְרִין: צְרִיחַ, וודו״י בְּלַעַ״ז שֶׁעוֹשִׂין בַּקַּרְקַע:\",2,0],[2,126,9,48,\"שׂוֹכַת עֵצִים. עֲנַף עֵצִים:\",1,0],[2,126,9,53,\"פֶּלַח רֶכֶב. חֲתִיכַת אֶבֶן שֶׁל רֵחַיִם הָעֶלְיוֹנָה הַקְּרוּיָה רֶכֶב:\",1,0],[2,126,9,53,\"וַתָּרִץ. וַתְּרוֹצֵץ:\",2,0],[2,126,9,54,\"פֶּן יֹאמְרוּ לִי. פֶּן יֹאמְרוּ עָלַי:\",1,0],[2,126,10,1,\"בֶּן דּוֹדוֹ. כָּךְ שְׁמוֹ:\",1,0],[2,126,10,4,\"עֲיָרִים. (תרגום:) עוּלִין, סוּסִים בְּחוּרִים:\",1,0],[2,126,10,4,\"וּשְׁלֹשִׁים עֲיָרִים לָהֶם. וּשְׁלֹשִׁים עָרִים בְּלֹא חוֹמָה לָהֶם, לְכָךְ נִקְרְאוּ עֲיָרִים, לְשׁוֹן עֲיָירוֹת:\",2,0],[2,126,10,6,\"אֶת הַבְּעָלִים וְגוֹ׳. שֶׁבַע עֲבוֹדוֹת זָרוֹת נִמְנוּ כָּאן:\",1,0],[2,126,10,6,\"וַיַּעַזְבוּ אֶת ה׳ וְלֹא עֲבָדוּהוּ. אֲפִילוּ בְּשׁוּתָּפוּת עִם אֵלּוּ:\",2,0],[2,126,10,8,\"בַּשָּׁנָה הַהִיא. כְּשֶׁמֵּת יָאִיר:\",1,0],[2,126,10,8,\"אֲשֶׁר בְּעֵבֶר הַיַּרְדֵּן. אֶרֶץ רְאוּבֵן וְגָד וַחֲצִי הַמְּנַשֶּׁה, שֶׁהָיוּ שְׁכֵנֵיהֶם:\",2,0],[2,126,10,11,\"הֲלֹא מִמִּצְרַיִם. שֶׁבַע תְּשׁוּעוֹת יֵשׁ כָּאן, כְּנֶגֶד שֶׁבַע עֲבוֹדוֹת זָרוֹת שֶׁהָיוּ עוֹבְדִים:\",1,0],[2,126,10,12,\"וּמָעוֹן. שֵׁם אוּמָּה:\",1,0],[2,126,10,16,\"וַתִּקְצַר נַפְשׁוֹ בַּעֲמַל. כִּבְיָכוֹל לֹא הָיָה רַחֲבַת מָקוֹם לִסְבּוֹל וְלִכָּנֵס שָׁם צָרָה שֶׁהָיָה לוֹ בַּעֲמַל יִשְׂרָאֵל:\",1,0],[2,126,10,17,\"וַיִּצָּעֲקוּ. נֶאֶסְפוּ עַל יְדֵי כָּרוּז:\",1,0],[2,126,11,4,\"וַיִּלָּחֲמוּ בְנֵי עַמּוֹן. הִיא הָאֲמוּרָה לְמַעְלָה (י:ט):\",1,0],[2,126,11,11,\"אֶת כָּל דְּבָרָיו. הַתְּנַאי שֶׁבֵּינֵיהֶם:\",1,0],[2,126,11,11,\"לִפְנֵי ה׳ בַּמִּצְפָּה. לְמָקוֹם שֶׁנֶּאֶסְפוּ כֻּלָּם, שֶׁהַשְּׁכִינָה שׁוֹרָה עַל רוֹב צִבּוּר:\",2,0],[2,126,11,16,\"עַד יַם סוּף. בִּדְרוֹמָהּ שֶׁל אֶרֶץ אֱדוֹם, וְאֶרֶץ אֱדוֹם בִּדְרוֹמָהּ שֶׁל אֶרֶץ כְּנַעַן:\",1,0],[2,126,11,17,\"אֶעְבְּרָה נָּא בְאַרְצֶךָ. מִדָּרוֹם לְצָפוֹן, לִיכָּנֵס לְאֶרֶץ כְּנַעַן:\",1,0],[2,126,11,17,\"וְגַם אֶל מֶלֶךְ מוֹאָב. שֶׁהָיְתָה אַרְצוֹ בְּסוֹף אֶרֶץ אֱדוֹם, בְּמִזְרָחָהּ שֶׁל אֱדוֹם וּבִדְרוֹמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל:\",2,0],[2,126,11,17,\"וְלֹא אָבָה. מֹשֶׁה רְמָזָהּ בַּתּוֹרָה (דברים ב:כט): כַּאֲשֶׁר עָשׂוּ לִי בְּנֵי עֵשָׂו הַיּוֹשְׁבִים בְּשֵׂעִיר וְהַמּוֹאָבִים הַיּוֹשְׁבִים בְּעָר, כְּשֵׁם שֶׁאֱדוֹם לֹא נְתָנוּם לַעֲבֹר, כָּךְ מוֹאָב לֹא נְתָנוּם לַעֲבֹר:\",3,0],[2,126,11,18,\"וַיֵּלֶךְ בַּמִּדְבָּר. מִן הַמַּעֲרָב לַמִּזְרָח, בְּמֵיצַר דְּרוֹמִי שֶׁל אֱדוֹם וּמוֹאָב:\",1,0],[2,126,11,18,\"וַיָּסָב אֶת אֶרֶץ אֱדוֹם. כָּל דְּרוֹמָהּ:\",2,0],[2,126,11,18,\"וְאֶת אֶרֶץ מוֹאָב. כָּל דְּרוֹמָהּ, וּכְשֶׁהִגִּיעַ לְמִקְצוֹעַ דְּרוֹמִית מִזְרָחִית, פָּנָה אֶל הַצָּפוֹן לִסְבּוֹב אֶת מֵיצַר הַמִּזְרָחִי:\",3,0],[2,126,11,18,\"וַיָּבֹא מִמִּזְרַח שֶׁמֶשׁ לְאֶרֶץ מוֹאָב וַיַּחֲנוּן בְּעֵבֶר אַרְנוֹן. לְסוֹף מִזְרָחָהּ שֶׁל אֶרֶץ מוֹאָב, וְשָׁם הִתְחִילָה אֶרֶץ סִיחוֹן וְעוֹג, וְכָבְשׁוּ עֵבֶר הַיַּרְדֵּן בְּמִזְרַח אֶרֶץ כְּנַעַן וְעָבְרוּ הַיַּרְדֵּן, וְנִכְנְסוּ לָהּ לְאֶרֶץ כְּנַעַן דֶּרֶךְ הַמִּזְרָח:\",4,0],[2,126,11,22,\"וַיִּירְשׁוּ וְגוֹ׳ מֵאַרְנוֹן וְעַד הַיַּבֹּק. שֶׁאַתָּה אוֹמֵר שֶׁהוּא שֶׁלְּךָ (פסוק יג), הֵם מִסִּיחוֹן לָקְחוּ:\",1,0],[2,126,11,22,\"וּמִן הַמִּדְבָּר וְעַד הַיַּרְדֵּן. מִדְבָּרוֹת הָיוּ שָׁם לִפְנֵי הַיַּרְדֵּן:\",2,0],[2,126,11,26,\"עַל יְדֵי אַרְנוֹן. אֵצֶל אַרְנוֹן, שֶׁהָיוּ מִמּוֹאָב, וְיָדְעוּ שֶׁלֹּא הָיָה לָהֶם לַעֲבֹר עֲלֵיהֶם, שֶׁהֲרֵי מִסִּיחוֹן כְּבָשׁוּם (במדבר כא:כד), שֶׁלְּקָחָם מִמֶּלֶךְ מוֹאָב (שם שם כו):\",1,0],[2,126,11,26,\"שְׁלֹשׁ מֵאוֹת שָׁנָה. מִשֶּׁכָּבְשׁוּ אֶת הָאָרֶץ בִּימֵי יְהוֹשֻׁעַ עַד יִפְתָּח מִכָּאן יֵשׁ לִלְמוֹד שְׁנוֹת הַשּׁוֹפְטִים הַנִּזְכָּרִים עַד הֵנָּה, אִם שְׁנֵי הַשִּׁעְבּוּד שֶׁל כָּל אוּמָּה נִמְנִים בְּתוֹךְ יְמֵי הַשּׁוֹפֵט אִם לָאו. שָׁנִינוּ בְּסֵדֶר עוֹלָם (פרק יב): יְהוֹשֻׁעַ פִּרְנֵס אֶת יִשְׂרָאֵל עֶשְׂרִים וּשְׁמוֹנֶה שָׁנָה, וְאֵין לוֹ מִקְרָא מִמִּי לִלְמוֹד. עָתְנִיאֵל (לעיל ג:יא), אַרְבָּעִים שָׁנָה, וּשְׁנֵי שִׁעְבּוּד שֶׁל כּוּשַׁן רִשְׁעָתַיִם (שם שם ח) בִּכְלָלָם. אַחֲרָיו אֵהוּד (שם שם ל), שְׁמוֹנִים שָׁנָה, שְׁמוֹנֶה עֶשְׂרֵה שָׁנִים שִׁעְבּוּד שֶׁל עֶגְלוֹן (שם שם יד) בְּתוֹכָם, הֲרֵי מֵאָה אַרְבָּעִים וּשְׁמוֹנֶה שָׁנָה. דְּבוֹרָה (שם ה:לא) אַרְבָּעִים שָׁנָה, וּשְׁנֵי שִׁעְבּוּד יָבִין (שם ד:ג) בְּתוֹכָם, הֲרֵי מֵאָה שְׁמוֹנִים וּשְׁמוֹנֶה. אַחֲרָיו, שֶׁבַע שָׁנִים שֶׁל שִׁעְבּוּד מִדְיָן (שם ו:א), וְאַרְבָּעִים שֶׁל גִּדְעוֹן (שם ח:כח), וְשָׁלֹשׁ שֶׁל אֲבִימֶלֶךְ (שם ט:כב), הֲרֵי מָאתַיִם שְׁלֹשִׁים וּשְׁמוֹנֶה שָׁנִים. אַחֲרָיו, עֶשְׂרִים וְשָׁלֹשׁ שֶׁל תּוֹלָע (שם י:ב), וְעֶשְׂרִים וּשְׁתַּיִם שֶׁל יָאִיר (שם י:ג), אֶלָּא שֶׁעָלְתָה שָׁנָה אַחַת לִשְׁנֵיהֶם, וּשְׁמוֹנֶה עֶשְׂרֵה שֶׁל בְּנֵי עַמּוֹן (שם שם ח) עַד שֶׁלֹּא בָּא יִפְתָּח, הֲרֵי שְׁלֹשׁ מֵאוֹת:\",2,0],[2,126,11,29,\"עָבַר בְּנֵי עַמּוֹן. אֶל בְּנֵי עַמּוֹן:\",1,0],[2,126,11,33,\"אָבֵל כְּרָמִים. (תרגום:) מֵישַׁר כַּרְמַיָּא:\",1,0],[2,126,11,35,\"הַכְרֵעַ הִכְרַעְתִּנִי. לְשׁוֹן נְקֵבָה, וְדוֹמֶה לוֹ (שיר השירים ד:ט): לִבַּבְתִּנִי אֲחוֹתִי כַלָּה:\",1,0],[2,126,11,35,\"הָיִית בְּעֹכְרָי. כָּל דָּמִי נֶעְכָּר, קִפַּחְתְּ אֶת רַגְלִי:\",2,0],[2,126,11,37,\"וְיָרַדְתִּי עַל הֶהָרִים. לְשׁוֹן יְלָלָה הוּא, וְדוּגְמָתוֹ (ישעיהו טו:ג): עַל גַּגּוֹתֶיהָ וּבִרְחוֹבוֹתֶיהָ כֻּלֹּה יְיֵלִיל יָרַד בִּבְכִי, הַמִּתְעַצֵּב בִּבְכִי עַד שֶׁגּוּפוֹ מִשְׁתַּבֵּר. וּבְמִדְרַשׁ אַגָּדָה דּוֹרֵשׁ רַבִּי תַּנְחוּמָא (בחוקותי ה): עַל הֶהָרִים. לִפְנֵי סַנְהֶדְרִין, שֶׁמָּא יִמְצְאוּ פֶּתַח לְנִדְרְךָ:\",1,0],[2,126,11,38,\"וַתֵּבְךְּ עַל בְּתוּלֶיהָ. מִדְּלָא כְתִיב עַל בְּתוּלוֹתֶיהָ, מַשְׁמַע בְּתוּלִים מַמָּשׁ:\",1,0],[2,126,11,39,\"וַתְּהִי חֹק. גָּזְרוּ שֶׁלֹּא יַעֲשֶׂה אָדָם עוֹד כֵּן, שֶׁאִלּוּ הָלַךְ אֵצֶל פִּנְחָס, אוֹ הוּא בָּא אֶצְלוֹ, הָיָה מַתִּיר לוֹ נִדְרוֹ, עָמְדוּ בִּגְדֻלָּתָן, וּמִבֵּין שְׁנֵיהֶם אָבְדָה, וְנִפְרַע מֵהֶם, פִּנְחָס נִסְתַּלְּקָה שְׁכִינָה הֵימֶנּוּ, שֶׁנֶּאֱמַר בְּדִבְרֵי הַיָּמִים (א ט:כ): לְפָנִים ה׳ עִמּוֹ, לָמַדְנוּ שֶׁבְּסוֹפוֹ אֵינוֹ עִמּוֹ, וְיִפְתָּח הוּכָּה בִּשְׁחִין וְנִפּוּל אֵבָרִים, שֶׁנֶּאֱמַר (לקמן יב:ז): וַיִּקָּבֵר בְּעָרֵי גִלְעָד. וְיֵשׁ עוֹד לִפְתֹּר: וַתְּהִי חֹק בְּיִשְׂרָאֵל. מְחֻבָּר לְמִקְרָא שֶׁלְּאַחֲרָיו:\",1,0],[2,126,11,40,\"מִיָּמִים יָמִימָה תֵּלַכְנָה וְגוֹ׳. הַדָּבָר הַזֶּה קָבְעוּ עֲלֵיהֶם לְחֹק:\",1,0],[2,126,11,40,\"לְתַנּוֹת. לְקוֹנֵן:\",2,0],[2,126,12,1,\"וַיַּעֲבֹר צָפוֹנָה. וַיַּעֲבֹר אֶת הַיַּרְדֵּן, וְהָלְכוּ לִצְפוֹן עֵבֶר הַיַּרְדֵּן, אֶל הַגִּלְעָד:\",1,0],[2,126,12,4,\"כִּי אָמְרוּ פְּלִיטֵי אֶפְרַיִם אַתֶּם גִּלְעָד. פְּחוּתִים שֶׁבְּאֶפְרַיִם הָיוּ מְבַזִּים אֶת הַגִּלְעָד, וְאוֹמְרִים לָהֶם: מָה אַתֶּם גִּלְעָד חֲשׁוּבִים בְּתוֹךְ אֶפְרַיִם וּבְתוֹךְ מְנַשֶּׁה, כֵּן תִּרְגֵּם יוֹנָתָן:\",1,0],[2,126,12,5,\"וַיִּלְכֹּד גִּלְעָד אֶת מַעְבְּרוֹת וְגוֹ׳. הָיוּ שׁוֹמְרִים בִּמְקוֹם הַמַּעְבָּרוֹת:\",1,0],[2,126,12,6,\"אֱמָר נָא שִׁבֹּלֶת. שִׁבֹּלֶת הַנָּהָר הַזֶּה אֶעֱבֹר:\",1,0],[2,126,12,6,\"וְלֹא יָכִין לְדַבֵּר כֵּן. שֶׁהָיוּ מְגַמְגְּמִים בִּלְשׁוֹנָם:\",2,0],[2,126,12,8,\"אִבְצָן. זֶה בֹּעַז:\",1,0],[2,126,13,4,\"יַיִן וְשֵׁכָר. (תרגום:) חַמַר חֲדַת וְעַתִּיק:\",1,0],[2,126,13,5,\"וּמוֹרָה. תַּעַר, עַל שֵׁם שֶׁמּוֹרֶה וּמַשְׁלִיךְ אֶת הַשֵּׂעָר:\",1,0],[2,126,13,7,\"וְאַל תֹּאכְלִי כָּל טֻמְאָה. דְּבָרִים הָאֲסוּרִים לְנָזִיר:\",1,0],[2,126,13,8,\"לַנַּעַר הַיּוּלָד. הֶעָתִיד לְהִוָּלֵד:\",1,0],[2,126,13,11,\"אַחֲרֵי אִשְׁתּוֹ. אַחַר עֲצָתָהּ:\",1,0],[2,126,13,12,\"מַה יִּהְיֶה מִשְׁפַּט הַנַּעַר וּמַעֲשֵׂהוּ. (תרגום:) מָה חֲזִי לְמֶעֱבַד לְעוּלֵימָא וּמָה נַעֲבִיד לֵיהּ:\",1,0],[2,126,13,15,\"נַעְצְרָה נָּא אוֹתָךְ. נֶאֱסֹף אוֹתְךָ אֶל הַבַּיִת:\",1,0],[2,126,13,17,\"כִּי יָבֹא דְבָרְךָ. אִם יָבֹא לָנוּ שְׁלִיחוּת דָּבָר מֵאִתְּךָ, מִשֶּׁנֵּדַע וְנַכִּיר אֶת שְׁמֶךָ:\",1,0],[2,126,13,17,\"וְכִבַּדְנוּךָ. וְנַעֲשֶׂה מַה שֶּׁתִּשְׁלַח לָנוּ:\",2,0],[2,126,13,18,\"וְהוּא פֶלִאי. מְכֻסֶּה, תָּמִיד הוּא מִשְׁתַּנֶּה וְאֵין יָדוּעַ לְמָה מִשְׁתַּנֶּה הַיּוֹם (ספרי נשא מב):\",1,0],[2,126,13,23,\"וְכָעֵת. הַזֹּאת:\",1,0],[2,126,13,23,\"לֹא הִשְׁמִיעָנוּ כָּזֹאת. לֹא הָיָה מַשְׁמִיעֵנוּ בְּשׂוֹרָה זוֹ אִם רְאוּיִים אָנוּ לָמוּת:\",2,0],[2,126,13,25,\"לְפַעֲמוֹ. לָבֹא בְּקִרְבּוֹ לִפְעָמִים:\",1,0],[2,126,14,4,\"כִּי תֹאֲנָה הוּא מְבַקֵּשׁ. עֲלִילָה לְהִתְגָּרוֹת בָּם:\",1,0],[2,126,14,7,\"וַיְדַבֵּר לָאִשָּׁה. עַל הָאִשָּׁה, דִּבֵּר לִקְרוֹבֶיהָ, כֵּן תִּרְגֵּם יוֹנָתָן:\",1,0],[2,126,14,8,\"עֲדַת דְּבוֹרִים. (תרגום:) קִינָא דְדַבְרַיָּתָא, כְּנִיסַת דְּבוֹרִים:\",1,0],[2,126,14,9,\"וַיִּרְדֵּהוּ. לְשׁוֹן הַבְדָּלַת דִּבּוּק שֶׁל כָּל דָּבָר הַנִּדְבָּק, וְכֵן לְעִנְיַן פַּת הַנִּדְבֶּקֶת בַּתַּנּוּר, נִקְרֵאת הַבְדָּלָתוֹ רְדִיָּה, (שבת קיז ב): הָרוֹדֶה פַּת מִן הַתַּנּוּר, (בבא מציעא סד א): הָרוֹדֶה אֶת כַּוַּרְתּוֹ, עַל שֵׁם שֶׁהַדְּבַשׁ עָשׂוּי עַל יְדֵי חַלּוֹת שֶׁעוֹשֶׂה מְדֻבָּק בְּדָפְנֵי הַכְּלִי בְּכָל צְדָדִין מִדּוֹפֶן אֶל דּוֹפֶן, כְּמִדַּת עוֹגֶל הַכְּלִי, וְכֵן תִּרְגֵּם יוֹנָתָן: וַיִּרְדֵּהוּ, וּנְסַחְיֵהּ:\",1,0],[2,126,14,10,\"וַיֵּרֶד אָבִיהוּ אֶל הָאִשָּׁה. (תרגום:) עַל עִסְקֵי אִתְּתָא:\",1,0],[2,126,14,11,\"מֵרֵעִים. חֲבֵרִים לְשׁוֹשְׁבִינוּת:\",1,0],[2,126,14,15,\"וַיְהִי בַּיּוֹם הַשְּׁבִיעִי. לִימוֹת הַשַּׁבָּת, וְלֹא שְׁבִיעִי לַמִּשְׁתֶּה, וְהוּא רְבִיעִי לִימֵי הַמִּשְׁתֶּה:\",1,0],[2,126,14,15,\"הַלְיָרְשֵׁנוּ קְרָאתֶם לָנוּ הֲלֹא. תִּרְגֵּם יוֹנָתָן: הַלְמִסְכְּנוּתָנָא קְרִיתוֹן יָתָנָא הָלְכָא:\",2,0],[2,126,14,17,\"שִׁבְעַת הַיָּמִים. הַנּוֹתָרִים מִשִּׁבְעַת הַיָּמִים, מֵרְבִיעִי וְאֵילָךְ:\",1,0],[2,126,14,18,\"בְּטֶרֶם יָבֹא הַחַרְסָה. לִפְנֵי שְׁקִיעַת הַחַמָּה, שֶׁעֲדַיִן הָיָה לָהֶם שֵׁהוּת עַד הָעֶרֶב:\",1,0],[2,126,14,18,\"חֲרַשְׁתֶּם בְּעֶגְלָתִי. מָשָׁל הוּא (תרגום:) אִילּוּלְפוֹן בְּדַקְתּוּן בְּאִתְּתִי:\",2,0],[2,126,14,19,\"רוּחַ ה׳. (תרגום:) רוּחַ גְּבוּרָה מִן קֳדָם ה׳:\",1,0],[2,126,14,19,\"חֲלִיצוֹתָם. מַלְבּוּשִׁים שֶׁחָלַץ מֵעֲלֵיהֶן:\",2,0],[2,126,14,20,\"לְמֵרֵעֵהוּ. לְאֶחָד מִשּׁוֹשְׁבִינָיו נְתָנָהּ:\",1,0],[2,126,15,3,\"נִקֵּיתִי הַפַּעַם. בְּדִין אֶעֱשֶׂה לָהֶם הָרָעָה:\",1,0],[2,126,15,4,\"וַיֶּפֶן. אֶת הַזְּנָבוֹת זָנָב אֶל זָנָב. וַיִּפֶן, מַשְׁמַע הוּא עַצְמוֹ פָּנָה (שמות לב טו); וַיֶּפֶן, מַשְׁמַע הִפְנָה אֶת אֲחֵרִים, וְכֵן שִׁמּוּשׁ כָּל תֵּיבָה שֶׁפֹּעַל שֶׁלָּהּ בְּה״א; (שמות א כ): וַיִּרֶב הָעָם; (איכה ב ה): וַיֶּרֶב בְּבַת יְהוּדָה תַּאֲנִיָּה; (מלכים ב כה כא): וַיִּגֶל יְהוּדָה מֵעַל אַדְמָתוֹ, גָּלָה; (שם ב: יח יא): וַיֶּגֶל מֶלֶךְ אַשּׁוּר אֶת יִשְׂרָאֵל אַשּׁוּרָה, הִגְלָה:\",1,0],[2,126,15,6,\"חֲתַן הַתִּמְנִי. חֲתַן הַפְּלִשְׁתִּי אֲשֶׁר בְּתִמְנָה (לעיל יד א):\",1,0],[2,126,15,7,\"אִם תַּעֲשׂוּן כָּזֹאת. וְשֶׁמָּא רְגִילִין אַתֶּם בְּכָךְ, לָתֵת אִשְׁתּוֹ שֶׁל זֶה לָזֶה:\",1,0],[2,126,15,8,\"שׁוֹק עַל יָרֵךְ. (תרגום:) פָּרְשִׁין עִם רַגְלָאִין, רוֹכֵב סוּס אֵינוֹ נִשְׁעָן עַל יְרֵכוֹ כִּי אִם עַל שׁוֹקוֹ, רֶגֶל אֶחָד נָתוּן בַּבַּרְזֶל הַתָּלוּי בַּמֶּרְכֶּבֶת:\",1,0],[2,126,15,8,\"בִּסְעִיף. בְּנִקְרַת סֶלַע עֵיטָם, וַחֲבֵרוֹ (ישעיהו נז:ה): סְעִיפֵי הַסְּלָעִים, (שם י:לג): מְסָעֵף פֹּארָה:\",2,0],[2,126,15,9,\"וַיִּנָּטְשׁוּ. וַיִּתְפַּזְּרוּ:\",1,0],[2,126,15,9,\"בַּלֶּחִי. שֵׁם מָקוֹם:\",2,0],[2,126,15,10,\"לָמָה עֲלִיתֶם עָלֵינוּ. הֲלֹא עֲבָדִים אֲנַחְנוּ לָכֶם:\",1,0],[2,126,15,10,\"לֶאֱסוֹר אֶת שִׁמְשׁוֹן. שֶׁתַּאַסְרוּהוּ וְתַסְגִּירוּהוּ לָנוּ:\",2,0],[2,126,15,13,\"לֹא כִּי אָסוֹר נֶאֱסָרְךָ. לֹא נַהֲרוֹג אוֹתְךָ, כִּי אִם אָסוֹר נֶאֱסָרְךָ:\",1,0],[2,126,15,14,\"רוּחַ ה׳. (תרגום:) רוּחַ גְּבוּרָה מִן קֳדָם ה׳:\",1,0],[2,126,15,14,\"אֱסוּרָיו. קִשּׁוּרָיו:\",2,0],[2,126,15,15,\"טְרִיָּה. לַחָה, וְרָאִיתִי בְּסֵפֶר רְפוּאוֹת שֶׁקּוֹרֵא לַלֵּחָה שֶׁיּוֹצֵא מִן הַמַּכָּה: ׳טְרִיָּה׳:\",1,0],[2,126,15,16,\"חֲמוֹר חֲמֹרָתָיִם. בִּלְחִי הַחֲמוֹר לִצְבּוֹר צְבָרִים רַבִּים, (תרגום:) בְּלוּעָא דִחמָרָא רְמֵיתִנוּן דְּגוֹרִין:\",1,0],[2,126,15,19,\"אֶת הַמַּכְתֵּשׁ. גּוּמָּא שֶׁהַשֵּׁן יוֹשֶׁבֶת בָּהּ, עֲשׂוּיָה כְּעֵין מַכְתֶּשֶׁת:\",1,0],[2,126,15,19,\"עֵין הַקּוֹרֵא. מַעְיָן שֶׁבָּא עַל יְדֵי זַעֲקַת הַקּוֹרֵא אֶל ה׳:\",2,0],[2,126,16,2,\"לַעַזָּתִים לֵאמֹר. לְאַנְשֵׁי עַזָּה נֶאֱמַר:\",1,0],[2,126,16,2,\"וַיִּתְחָרְשׁוּ. נָהֲגוּ עַצְמָן בִּשְׁתִיקָה:\",2,0],[2,126,16,3,\"וַיִּסָּעֵם. וַיַּעַקְרֵם מִמְּקוֹמָם:\",1,0],[2,126,16,7,\"יְתָרִים. חֲבָלִים דַּקִּים:\",1,0],[2,126,16,9,\"וְלֹא נוֹדַע כֹּחוֹ. לֹא הוּצְרַךְ לְהִתְחַזֵּק בְּנַתְּקוֹ אוֹתָם:\",1,0],[2,126,16,11,\"בַּעֲבוֹתִים. חֲבָלִים גַּסִּים:\",1,0],[2,126,16,13,\"מַחְלְפוֹת. קְוֻצּוֹת, פלוני״ש בְּלַעַ״ז:\",1,0],[2,126,16,13,\"עִם הַמַּסָּכֶת. עֵץ שֶׁהַגַּרְדִּי מֵיסֵךְ בּוֹ אֶת הַשְּׁתִי, וְשֵׁם הָעֵץ אנשובל״א מַסֶּכֶת, אורטר״א בְּלַעַ״ז:\",2,0],[2,126,16,16,\"וַתְּאַלְצֵהוּ. דְּחָקַתּוֹ, וְאֵין לוֹ דִּמְיוֹן:\",1,0],[2,126,16,18,\"וַתֵּרֶא דְלִילָה כִּי הִגִּיד לָהּ. נִכָּרִין דִּבְרֵי אֱמֶת:\",1,0],[2,126,16,19,\"וַתִּקְרָא לָאִישׁ. לִשְׁלוּחָן שֶׁל סְרָנִים:\",1,0],[2,126,16,21,\"וַיּוֹרִידוּ אוֹתוֹ עַזָּתָה. מְקוֹם תְּחִלַּת קִלְקוּלוֹ:\",1,0],[2,126,16,21,\"וַיְהִי טוֹחֵן. בָּרֵחַיִם, מְלָאכָה כְּבֵדָה וְרַבּוֹתֵינוּ (סוטה י א) פֵּרְשׁוּ מַה שֶּׁפֵּרְשׁוּ:\",2,0],[2,126,16,25,\"בֵּין הָעַמּוּדִים. אֲשֶׁר הַבַּיִת נָכוֹן עֲלֵיהֶם:\",1,0],[2,126,16,26,\"וַהֲמִישֵׁנִי. פאלפא״ר בְּלַעַ״ז, כְּמוֹ (בראשית כז:יב): ״אוּלַי יְמֻשֵּׁנִי״:\",1,0],[2,126,16,28,\"זָכְרֵנִי נָא. זְכֹר עֶשְׂרִים שָׁנָה שֶׁשָּׁפַטְתִּי אֶת יִשְׂרָאֵל, וְלֹא אָמַרְתִּי לְאֶחָד מֵהֶם הַעֲבֵר לִי מַקֵּל זֶה מִמָּקוֹם לְמָקוֹם:\",1,0],[2,126,16,28,\"נְקַם אַחַת מִשְּׁתֵי עֵינַי. וּשְׂכַר עַיִן הַשֵּׁנִית הַנַּח לִי לָעוֹלָם הַבָּא, וְכָאן פְּרַע לִי שְׂכַר אַחַת מֵהֶן:\",2,0],[2,126,16,29,\"וַיִּלְפֹּת. וַיֹּאחַז, אינברצ״א בְּלַעַ״ז, כְּמוֹ (רות ג:ח): ״וַיֶּחֱרַד הָאִישׁ וַיִּלָּפֵת״, נֶאֱחַז בִּזְרוֹעוֹת הָאִשָּׁה:\",1,0],[2,126,17,1,\"וַיְהִי אִישׁ מֵהַר אֶפְרָיִם. אַף עַל פִּי שֶׁנִּכְתְּבוּ שְׁתֵּי פָּרָשִׁיּוֹת הַלָּלוּ בְּסוֹף הַסֵּפֶר, שֶׁל מִיכָה וְשֶׁל פִּלֶגֶשׁ בַּגִּבְעָה, בִּתְחִלַּת הַשּׁוֹפְטִים הָיָה, בִּימֵי עָתְנִיאֵל בֶּן קְנַז, שֶׁנֶּאֱמַר (שופטים יח:לא): ״וַיָּשִׂימוּ לָהֶם אֶת פֶּסֶל מִיכָה וְגוֹ׳ כָּל יְמֵי הֱיוֹת בֵּית אֱלֹהִים בְּשִׁילֹה״, לָמַדְנוּ שֶׁכָּל יְמֵי שִׁילֹה הָיָה דְּמוּת שֶׁל מִיכָה, וּבְפִלֶגֶשׁ בַּגִּבְעָה נֶאֱמַר עַל יְבוּס שֶׁבִּירוּשָׁלַיִם (שופטים יט:יב): ״לֹא נָסוּר אֶל עִיר נָכְרִי״, לָמַדְנוּ שֶׁעֲדַיִן לֹא כָּבְשׁוּ אֶת יְרוּשָׁלַיִם:\",1,0],[2,126,17,2,\"אֲשֶׁר לֻקַּח לָךְ. אֲשֶׁר נִגְנַב מִמֵּךְ, וְיֵשׁ לוֹ דוֹמֶה (שמואל א כא:ו): ״כִּי אִשָּׁה עֲצוּרָה לָנוּ״, עֲצוּרָה מִמֶּנּוּ:\",1,0],[2,126,17,2,\"וְאַתְּ אָלִית. קִלְלַת כָּל מִי שֶׁגְּנָבוֹ, וְגַם אָמַרְתְּ הַקְּלָלָה בְּאָזְנַי:\",2,0],[2,126,17,2,\"הִנֵּה הַכֶּסֶף. אֲנִי מוֹדֶה לָךְ עָלָיו שֶׁהוּא בְּיָדִי שֶׁאֲנִי לְקַחְתִּיו:\",3,0],[2,126,17,3,\"וַיָּשֶׁב אֶת אֶלֶף וּמֵאָה הַכֶּסֶף לְאִמּוֹ. אָמַר לְהַחֲזִירוֹ לָהּ, וּבַמָּקוֹם שֶׁהוּא שָׁם הֲרֵי הוּא בִּרְשׁוּתֵךְ:\",1,0],[2,126,17,3,\"הַקְדֵּשׁ הִקְדַּשְׁתִּי אֶת הַכֶּסֶף מִיָּדִי לִבְנִי. קִבַּלְתִּי עָלַי לְמָסְרוֹ מִיָּדִי לְיָדְךָ לְשֵׁם דְּמוּת וּמַסֵּכָה, תְּנֵהוּ לִי עַתָּה וּמִיָּדִי אֲנִי אֲשִׁיבֶנּוּ אֵלֶיךָ יֵשׁ אוֹמְרִים שֶׁהָאִשָּׁה הַזֹּאת הִיא דְּלִילָה, לְפִי שֶׁכָּתוּב (לעיל טז:ה): ״אֶלֶף וּמֵאָה כֶּסֶף״, וְטָעוּת הוּא בְּיָדָם, שֶׁהַרְבֵּה שָׁנִים קָדַם מִיכָה לְשִׁמְשׁוֹן, אַךְ הַפָּרָשִׁיּוֹת נִסְמְכוּ עַל הַכֶּסֶף הָרָע שֶׁשָּׁוֶה כָּאן וְכָאן, וְכֶסֶף שֶׁל פּוּרְעָנוּת הָיוּ שְׁנֵיהֶם:\",2,0],[2,126,17,5,\"בֵּית אֱלֹהִים. בֵּית עֲבוֹדָה זָרָה, וְכֵן כָּל ׳אֱלֹהִים׳ הָאֲמוּרִים בְּפָרָשָׁה זוֹ חוֹל, חוּץ מִזֶּה (שופטים יח:לא): ״כָּל יְמֵי הֱיוֹת בֵּית הָאֱלֹהִים בְּשִׁילֹה״ (שבועות לה ב):\",1,0],[2,126,17,5,\"וַיְמַלֵּא אֶת יַד אַחַד. חֲנָכוֹ לַעֲבוֹדַת הַדְּמוּת לִהְיוֹת כֹּהֵן לְפָנָיו, כָּל חִנּוּךְ דָּבָר שֶׁאָדָם נִכְנָס בּוֹ לְשֵׁם גְּדֻלָּה קָרוּי מִלּוּי יָדַיִם, רישוושטי״ר בְּלַעַ״ז; וּכְשֶׁנּוֹתְנִין פְּקִידוּת לְאָדָם, קוֹרִין לְמַתָּן רישוישטי״ר בְּלַעַ״ז:\",2,0],[2,126,17,7,\"מִמִּשְׁפַּחַת יְהוּדָה. וְהוּא לֵוִי מִן הָאֵם וְרַבּוֹתֵינוּ אָמְרוּ (בבא בתרא קט ב): לְפִי שֶׁעָשָׂה מַעֲשֵׂה מְנַשֶּׁה שֶׁבָּא מִיהוּדָה, קְרָאוֹ מִמִּשְׁפַּחַת יְהוּדָה, וְהוּא לֵוִי בֶּן גֵּרְשׁוֹם בֶּן מֹשֶׁה רַבֵּינוּ הָיָה, כְּמוֹ שֶׁמְּפֹרָשׁ בָּעִנְיָן (שופטים יח:ל): ״וִיהוֹנָתָן בֶּן גֵּרְשׁוֹם וְגוֹ׳״:\",1,0],[2,126,17,8,\"לַעֲשׂוֹת דַּרְכּוֹ. דֶּרֶךְ הֲלִיכָתוֹ:\",1,0],[2,126,17,9,\"בַּאֲשֶׁר אֶמְצָא. פַּרְנָסָתִי לְהִשְׂתַּכֵּר:\",1,0],[2,126,17,10,\"לַיָּמִים. לְסוֹף שָׁנָה:\",1,0],[2,126,17,10,\"וְעֵרֶךְ בְּגָדִים. זוּג חֲלִיפַת בְּגָדִים שֶׁהֵם עֵרֶךְ וְסֵדֶר לְכָל בְּנֵי אָדָם כְּפִי הָרָאוּי לָהֶם לְשָׁנָה:\",2,0],[2,126,17,10,\"וְעֵרֶךְ בְּגָדִים. אפרליימנ״ט בְּלַעַ״ז:\",3,0],[2,126,17,10,\"וּמִחְיָתֶךָ. וּמְזוֹנוֹתֶיךָ:\",4,0],[2,126,17,10,\"וַיֵּלֶךְ הַלֵּוִי. אַחַר עֲצָתוֹ:\",5,0],[2,126,18,1,\"כִּי לֹא נָפְלָה לוֹ. יְרֻשָּׁה כְּפִי הָרָאוּי לָהֶם בְּאֶרֶץ מְכֻבֶּשֶׁת, כְּמוֹ שֶׁנֶּאֱמַר בִּיהוֹשֻׁעַ (יהושע יט:מז): ״וַיֵּצֵא גְבוּל בְּנֵי דָן מֵהֶם״, וְאַף מִכָּאן יֵשׁ לִלְמֹד שֶׁהָיָה מַעֲשֶׂה זֶה בִּתְחִלַּת הַשּׁוֹפְטִים מִיָּד:\",1,0],[2,126,18,3,\"מִי הֱבִיאֲךָ הֲלֹם. יֵשׁ כָּאן תְּמִיהוֹת הַרְבֵּה, (בבא בתרא קי:) לֹא מִזַּרְעוֹ שֶׁל מֹשֶׁה רַבֵּינוּ אַתָּה, שֶׁנֶּאֱמַר בּוֹ (שמות ג:ה): ״אַל תִּקְרַב הֲלֹם״, (שם ד:יא): ״מִי שָׂם פֶּה לָאָדָם״, (שם ד:ב): ״מַה זֶּה בְיָדֶךָ״:\",1,0],[2,126,18,5,\"שְׁאַל נָא בֵאלֹהִים. בַּתְּרָפִים שֶׁמְּדַבְּרִים עַל יְדֵי מְכַשְּׁפוֹת:\",1,0],[2,126,18,6,\"נֹכַח ה׳ דַּרְכְּכֶם. נֹכַח הַקָּדוֹשׁ בָּרוּךְ הוּא גָּלוּי, כִּי זֶה אֵין בּוֹ מַמָּשׁ:\",1,0],[2,126,18,7,\"וְאֵין מַכְלִים דָּבָר. אֵין אֶחָד מֵהֶם צָרִיךְ לַחֲבֵרוֹ שֶׁיַּחֲזִירֶנּוּ רֵיקָם וְיַכְלִימֶנּוּ, כְּמוֹ שֶׁנֶּאֱמַר בְּסוֹף הָעִנְיָן (פסוק י): ״אֵין מַחְסוֹר כָּל דָּבָר״, כָּךְ שָׁמַעְתִּי:\",1,0],[2,126,18,7,\"יוֹרֵשׁ עֶצֶר. יוֹרְשִׁים מוּעָטִים, שֶׁאִם יַהַרְגוּ אֶת אֵלּוּ, אֵין עוֹד עוֹרְרִין נִלְחָמִים עִם הַמַּחֲזִיקִים בַּנַּחֲלָה:\",2,0],[2,126,18,7,\"וּרְחוֹקִים הֵמָּה. מֵעֶזְרַת צִידוֹנִים:\",3,0],[2,126,18,7,\"וְדָבָר אֵין לָהֶם עִם אָדָם. שׁוּם בְּרִית כְּרוּתָה שֶׁיָּבֹאוּ לְעֶזְרָתָם לְעֵת הַצֹּרֶךְ:\",4,0],[2,126,18,8,\"מָה אַתֶּם. כְּלוֹמַר מָה אַתֶּם מְשִׁיבִים דָּבָר, מַה מְּצָאתֶם בַּמָּקוֹם שֶׁנָּפַל לָנוּ גוֹרָלֵנוּ, מָה הָעָם, הֶחָזָק הוּא הֲרָפֶה:\",1,0],[2,126,18,9,\"וְאַתֶּם מַחְשִׁים. מִתְעַצְּלִים:\",1,0],[2,126,18,21,\"וְאֶת הַכְּבוּדָּה. מַשָּׂאוֹת, כָּל דָּבָר שֶׁהוּא כָּבֵד בַּהֲלִיכָתוֹ שֶׁאֵינוֹ יָכוֹל לָרוּץ אִם יִרְדְּפוּ בְּנֵי הַמָּקוֹם אַחֲרֵיהֶם:\",1,0],[2,126,18,21,\"הַכְּבוּדָּה. פיזנטו״מא בְּלַעַ״ז:\",2,0],[2,126,18,23,\"וַיַּסֵּבּוּ פְּנֵיהֶם. בְּנֵי דָן אֶל הַקּוֹרְאִים אֲלֵיהֶם:\",1,0],[2,126,18,24,\"וּמַה לִּי עוֹד. וּמַה נִּשְׁאַר לִי עוֹד:\",1,0],[2,126,18,25,\"אֲנָשִׁים מָרֵי נֶפֶשׁ. כַּעֲסָנִים שֶׁיֵּשׁ בְּסִיעָתֵנוּ:\",1,0],[2,126,18,27,\"לַיִשׁ. שֵׁם הָעִיר, וּבְסֵפֶר יְהוֹשֻׁעַ (יהושע יט:מז) קוֹרֵא שְׁמָהּ ׳לֶשֶׁם׳, עַל שֵׁם שֶׁמָּצְאוּ שָׁם אֶבֶן טוֹבָה שֶׁשְּׁמָהּ ׳לֶשֶׁם׳, וְהִיא הָיְתָה עַל הַחֹשֶׁן לְשֵׁבֶט דָּן, שְׁמוֹ כָּתוּב עַל ׳לֶשֶׁם׳, וְיָדְעוּ שֶׁבֶּאֱמֶת הִיא נַחֲלָתָם:\",1,0],[2,126,18,30,\"בֶּן מְנַשֶּׁה. מִפְּנֵי כְּבוֹדוֹ שֶׁל מֹשֶׁה כָּתוּב נוּ״ן לְשַׁנּוֹת אֶת הַשֵּׁם, וְנִכְתַּב תְּלוּיָה לוֹמַר שֶׁלֹּא הָיָה מְנַשֶּׁה אֶלָּא מֹשֶׁה:\",1,0],[2,126,18,30,\"עַד יוֹם גְּלוֹת הָאָרֶץ. בִּימֵי סַנְחֵרִיב בְּגָלוּת רִאשׁוֹנָה:\",2,0],[2,126,19,2,\"וַתִּזְנֶה עָלָיו פִּילַגְשׁוֹ. זָנְתָה מִבֵּיתוֹ אֶל הַחוּץ כָּל לְשׁוֹן זְנוּת אֵינוֹ אֶלָּא לְשׁוֹן ׳יוֹצֵאת׳ (תרגום אונקלוס בראשית לד:לא): נַפְקַת בָּרָא, יוֹצֵאת מִבַּעְלָהּ לֶאֱהוֹב אֶת אֲחֵרִים:\",1,0],[2,126,19,6,\"הוֹאֶל נָא וְלִין. הַלַּיְלָה:\",1,0],[2,126,19,9,\"רָפָה. הַשֶּׁמֶשׁ מִגְּבוּרָתוֹ וְנָטָה לַעֲרוֹב:\",1,0],[2,126,19,9,\"הִנֵּה חֲנוֹת הַיּוֹם. עֵת שֶׁכָּל הוֹלְכֵי דְרָכִים נוֹטִים לַחֲנוֹת בַּבַּיִת:\",2,0],[2,126,19,12,\"עַד גִּבְעָה. גִּבְעַת בִּנְיָמִן:\",1,0],[2,126,19,13,\"וְלַנּוּ. כְּמוֹ וְלַנְנוּ, דַּגְשׁוּת הַנּוּ״ן בִּמְקוֹם נוּ״ן שְׁנִיָּה:\",1,0],[2,126,19,18,\"וְאֶת בֵּית ה׳. לְשִׁילֹה אֲנִי הוֹלֵךְ:\",1,0],[2,126,19,21,\"וַיָּבָל לַחֲמוֹרִים. וַיִּתֵּן יְבוּל לַחֲמוֹרִים, ׳וַיָּבָל׳ אפרוונד״ר בְּלַעַ״ז:\",1,0],[2,126,19,22,\"וְנֵדָעֶנּוּ. מִשְׁכַּב זָכוּר:\",1,0],[2,126,19,28,\"וְאֵין עוֹנֶה. כִּי מֵתָה:\",1,0],[2,126,20,2,\"פִּנּוֹת כָּל הָעָם. (תרגום:) רֵישֵׁי כָּל עַמָּא:\",1,0],[2,126,20,5,\"דִּמּוּ לַהֲרֹג. כִּוְּנוּ לַהֲרֹג, אנישמינט״ו בְּלַעַ״ז:\",1,0],[2,126,20,10,\"לַעֲשׂוֹת לְבוֹאָם. לְבִיאָתָם זוֹ לְגִבְעַת בִּנְיָמִין ׳כְּכָל הַנְּבָלָה׳ וְגוֹ׳:\",1,0],[2,126,20,11,\"חֲבֵרִים. שָׁוִים בְּעֵצָה אַחַת:\",1,0],[2,126,20,12,\"בְּכָל שִׁבְטֵי בִנְיָמִן. עֲשָׂרָה שְׁבָטִים נֶחְשְׁבוּ עֲשָׂרָה מִשְׁפְּחוֹתָיו, שֶׁיִּהְיוּ מֵרָחֵל שְׁנֵים עָשָׂר שְׁבָטִים:\",1,0],[2,126,20,16,\"אִטֵּר יַד יְמִינוֹ. גְּמוּדֵי יַד יְמִינָם, לֹא הָיוּ שׁוֹלְטִים בָּהּ כְּאִלּוּ הָיְתָה אֲטוּמָה, כְּמוֹ (תהלים סט:טז): ״אַל תֶּאְטַר עָלַי בְּאֵר פִּיהָ״:\",1,0],[2,126,20,16,\"כָּל זֶה. שְׁבַע מֵאוֹת אִישׁ הַלָּלוּ:\",2,0],[2,126,20,16,\"אֶל הַשַּׂעֲרָה. לְחוּט הַשֵּׂעָר:\",3,0],[2,126,20,16,\"וְלֹא יַחֲטִא. לֹא יִשְׁגֶּה:\",4,0],[2,126,20,18,\"יְהוּדָה בַתְּחִלָּה. אֲבָל לֹא בָחֲנוּ לִשְׁאוֹל אִם לְנַצֵּחַ אִם לִינָּצֵחַ, וּבָאַחֲרוֹנָה שֶׁבָּחֲנוּ, אָמַר (פסוק כח): ״עֲלוּ כִּי מָחָר אֶתְּנֶנּוּ בְיָדֶךָ״, הִשְׁכִּימוּ וְהִשְׁלִימוּ דִּבְרֵיהֶם:\",1,0],[2,126,20,21,\"וַיַּשְׁחִיתוּ. נֶעֶנְשׁוּ עַל שֶׁלֹּא קִנְּאוּ כְּמוֹ כֵן בְּמַעֲשֵׂה דְּמוּת מִיכָה שֶׁהָיָה כְּבָר:\",1,0],[2,126,20,33,\"בְּבַעַל תָּמָר. בְּמֵישַׁר יְרִיחוֹ:\",1,0],[2,126,20,33,\"מֵגִיחַ. נִמְשָׁךְ, כְּמוֹ (איוב מ:כג): ״יָגִיחַ יַרְדֵּן אֶל פִּיהוּ״; (תהלים כב:י): ״גֹחִי מִבָּטֶן״:\",2,0],[2,126,20,33,\"מִמַּעֲרֵה גָבַע. מִמָּקוֹם צַר, עֶרְוָתָהּ וְגִלּוּיָהּ שֶׁל גִּבְעַת בִּנְיָמִין, מְקוֹם תּוֹרְפָה שֶׁלָּהּ שֶׁהִיא נוֹחָה לִיכָּבֵשׁ מִשָּׁם, כְּמוֹ (בראשית מב:ט): ״לִרְאוֹת אֶת עֶרְוַת הָאָרֶץ בָּאתֶם״:\",3,0],[2,126,20,36,\"וַיִּתְּנוּ אִישׁ יִשְׂרָאֵל. אֲשֶׁר בַּשָּׂדֶה, מָקוֹם לְבִנְיָמִן לִבְרֹחַ אֶל הַגִּבְעָה, כִּי סָמְכוּ יִשְׂרָאֵל עַל הָאוֹרֵב שֶׁיֵּצְאוּ לִקְרָאתָם:\",1,0],[2,126,20,37,\"וַיִּמְשֹׁךְ הָאוֹרֵב. מָשַׁךְ בַּשּׁוֹפָר; דָּבָר אַחֵר: מָשַׁךְ בַּשּׁוֹפָר הָעָם אֲשֶׁר אִתּוֹ, אֶל הָעִיר:\",1,0],[2,126,20,38,\"וְהַמּוֹעֵד הָיָה. מִתְּחִלָּה הָיָה אוֹת בֵּין יִשְׂרָאֵל וּבֵין הָאוֹרֵב, לִהְיוֹת הָאוֹרֵב מַרְבֶּה לְהַעֲלוֹת עֲשַׁן הָעִיר, וְיָבִינוּ יִשְׂרָאֵל אֲשֶׁר לָכַד הָאוֹרֵב אֶת הַגִּבְעָה:\",1,0],[2,126,20,38,\"מַשְׂאַת הֶעָשָׁן. גֹּבַהּ הֶעָשָׁן:\",2,0],[2,126,20,39,\"וַיַּהֲפֹךְ אִישׁ יִשְׂרָאֵל. עַכְשָׁיו חוֹזֵר לִתְחִלַּת הַדְּבָרִים וְשׁוֹנֶה וּמְפָרֵשׁ, עֶשְׂרִים וַחֲמִשָּׁה אֶלֶף שֶׁכָּתַבְנוּ לְמַעְלָה (פסוק לה), כֵּיצַד נָפְלוּ וְהֵיכָן נָפְלוּ:\",1,0],[2,126,20,42,\"וַאֲשֶׁר מֵהֶעָרִים. הָאוֹרֵב שֶׁנִּכְנַס בָּעִיר, מַשְׁחִיתִים אוֹתוֹ בְּתוֹךְ הַשֵּׁבֶט, בְּתוֹךְ הָעִיר:\",1,0],[2,126,20,43,\"כִּתְּרוּ אֶת בִּנְיָמִן. הִקִּיפוּ אֶת בִּנְיָמִן כְּכֶתֶר הַמַּקִּיף אֶת הָרֹאשׁ, וְכֵן (תהלים כב:יג): ״אַבִּירֵי בָשָׁן כִּתְּרוּנִי״, וְכֵן (חבקוק א:ד): ״כִּי רָשָׁע מַכְתִּיר אֶת הַצַּדִּיק״, וְכֵן גַּם בִּלְשׁוֹן עֲטָרָה נִקְרֵאת הַקָּפָה (שמואל א כג:כו): ״וְשָׁאוּל וַאֲנָשָׁיו עֹטְרִים אֶל דָּוִד וְאֶל אֲנָשָׁיו לְתָפְשָׂם״:\",1,0],[2,126,20,43,\"הִרְדִיפֻהוּ. קוֹרְאִים אַחֲרָיו רְדִיפָה, צוֹעֲקִים זֶה לָזֶה לִרְדֹּף:\",2,0],[2,126,20,43,\"מְנוּחָה הִדְרִיכֻהוּ. אֵצֶל הֶעָרִים שֶׁהֵם נוֹחִים בָּהֶם, שָׁם הִדְבִּיקוּהוּ:\",3,0],[2,126,20,43,\"הִדְרִיכֻהוּ. הִשִּׂיגוּהוּ, וְיֵשׁ דֻּגְמָתוֹ בִּלְשׁוֹן גְּמָרָא (כתובות ס ב): רְהַט בַּתְרֵיהּ פַּרְסָא בְּחָלָא וְלֹא אַדְרְכֵיהּ:\",4,0],[2,126,20,43,\"עַד נֹכַח הַגִּבְעָה. מִמִּזְרָחָהּ שֶׁל גִּבְעָה:\",5,0],[2,126,20,44,\"וַיִּפְּלוּ מִבִּנְיָמִן שְׁמוֹנָה עָשָׂר אֶלֶף. בַּשָּׂדֶה בְּתוֹךְ הַמִּלְחָמָה:\",1,0],[2,126,20,45,\"וַיְעֹלְלֻהוּ. הֲרִיגָה אַחַר הֲרִיגָה, כְּעוֹלְלוֹת שֶׁאַחַר הַבָּצִיר:\",1,0],[2,126,20,45,\"חֲמֵשֶׁת אֲלָפִים אִישׁ. הֲרֵי עֶשְׂרִים וּשְׁלֹשָׁה אֶלֶף:\",2,0],[2,126,20,45,\"עַד גִּדְעֹם. שֵׁם מָקוֹם:\",3,0],[2,126,20,45,\"וַיַּכּוּ מִמֶּנּוּ אַלְפַּיִם אִישׁ. הֲרֵי עֶשְׂרִים וַחֲמִשָּׁה אֶלֶף הָאָמוּר לְמַעְלָה (פסוק לה), וְהַמֵּאָה הַכְּתוּבִים לְמַעְלָה (שם), לֹא פֵּרַשׁ הֵיכָן נָפְלוּ:\",4,0],[2,126,20,48,\"שָׁבוּ אֶל בְּנֵי בִנְיָמִן. בְּכָל הֶעָרִים:\",1,0],[2,126,20,48,\"מֵעִיר מְתֹם. הֵתַמּוּ כָּל יוֹשְׁבֵי הֶעָרִים:\",2,0],[2,126,20,48,\"וְעַד בְּהֵמָה. וַאֲנָשִׁים בִּכְלַל ׳מְתוֹם׳ הָיוּ, שֶׁ׳מְּתוֹם׳ לְשׁוֹן כְּלָיָה הוּא וְיֵשׁ לִתְמֹהַּ עַל אֶלֶף הֵיכָן הֵם, שֶׁהֲרֵי עֶשְׂרִים וְשִׁשָּׁה אֶלֶף הִתְפַּקְּדוּ מִן הֶעָרִים, וּמִן הַגִּבְעָה שֵׁשׁ מֵאוֹת, וְכָאן מָנָה בַּנּוֹפְלִים עֶשְׂרִים וַחֲמִשָּׁה אֶלֶף וּמֵאָה אִישׁ, וְשֵׁשׁ מֵאוֹת נִמְלְטוּ אֶל סֶלַע הָרִמּוֹן, וְהָאֶלֶף בָּרְחוּ אֶל הֶעָרִים וְנָפְלוּ לְמָחֳרָת כְּשֶׁשָּׁבוּ בְּנֵי יִשְׂרָאֵל אֶל עָרֵי בִנְיָמִן לְהַחֲרִים הַנָּשִׁים וְהַטַּף:\",3,0],[2,126,21,3,\"לְהִפָּקֵד. לְהִגָּרַע:\",1,0],[2,126,21,6,\"וַיִּנָּחֲמוּ. שָׁבוּ לַחֲשֹׁב עֲלֵיהֶם מַחְשֶׁבֶת פְּלֵיטָה:\",1,0],[2,126,21,12,\"אַרְבַּע מֵאוֹת. נַעֲרָה בְתוּלָה הוֹשִׁיבוּם עַל פִּי חָבִיּוֹת שֶׁל יַיִן, בְּעוּלָה רֵיחָהּ נוֹדֵף, בְּתוּלָה אֵין רֵיחָהּ נוֹדֵף:\",1,0],[2,126,21,14,\"וְלֹא מָצְאוּ לָהֶם. לֹא סִפְּקוּ לָהֶם:\",1,0],[2,126,21,17,\"יְרֻשַּׁת פְּלֵיטָה. נַחֲלַת הַשֵּׁבֶט נִשְׁאֲרָה רֵיקָנִית, הָבוּ עֵצָה שֶׁיּוֹלִידוּ בָנִים וְיַחֲזִיקוּ בְּנַחֲלָתָם הַפְּלֵיטָה הַנִּשְׁאֶרֶת, וְלֹא יִמָּחֶה שֵׁבֶט מִיִּשְׂרָאֵל:\",1,0],[2,126,21,19,\"מִזְרְחָה הַשֶּׁמֶשׁ לַמְסִלָּה. בְּמִזְרָחָהּ שֶׁל מְסִלָּה, שִׁילֹה בִּצְפוֹנָהּ שֶׁל בֵּית אֵל וּבִדְרוֹמָהּ שֶׁל לְבוֹנָה, וּבְמִזְרָחָהּ שֶׁל מְסִלָּה הָעוֹלָה מִבֵּית אֵל שְׁכֶמָה:\",1,0],[2,126,21,22,\"לָרִיב אֵלֵינוּ. לָלֶכֶת אֵלֵינוּ בַּמִּלְחָמָה:\",1,0],[2,126,21,22,\"וְאָמַרְנוּ אֲלֵיהֶם חָנּוּנוּ אוֹתָם. רִחַמְנוּ עֲלֵיהֶם כִּי אֵינָם יוֹדְעִים מַה לַּעֲשׂוֹת, ׳כִּי לֹא לָקַחְנוּ אִישׁ אִשְׁתּוֹ בַּמִּלְחָמָה׳ שֶׁל יָבֵשׁ גִּלְעָד אֶלָּא לְאַרְבַּע מֵאוֹת אִישׁ מֵהֶם, וְאִם עַל הַשְּׁבוּעָה אַתֶּם מַקְפִּידִים, לֹא עָוֹן לָכֶם בַּדָּבָר ׳כִּי לֹא אַתֶּם נְתַתֶּם לָהֶם׳ אֶת בְּנוֹתֵיכֶם שֶׁתְּהֵא לָכֶם אַשְׁמָה בַּדָּבָר וְשָׁלוֹם לָכֶם אַל תִּירָאוּ:\",2,0],[2,127,1,1,\"אֵיכָה יָשְׁבָה בָדָד. יִרְמְיָה כָתַב סֵפֶר קִינוֹת, הִיא הַמְּגִלָּה אֲשֶׁר שָׂרַף יְהוֹיָקִים עַל הָאֵשׁ אֲשֶׁר עַל הָאָח, וְהָיוּ בָהּ שָׁלשׁ אָלֶ\\\"ף בֵּיתוֹ\\\"ת: \\\"אֵיכָה יָשְׁבָה\\\", \\\"אֵיכָה יָעִיב\\\", \\\"אֵיכָה יוּעַם\\\". שׁוּב הוֹסִיף עָלָיו \\\"אֲנִי הַגֶּבֶר\\\" שֶׁהוּא שָׁלשׁ אָלֶ\\\"ף בֵּיתוֹ\\\"ת, שֶׁנֶּאֱמַר, \\\"וְעוֹד נוֹסַף עֲלֵיהֶם דְבָרִים רַבִּים כָּהֵמָּה\\\", שָׁלשׁ כְּנֶגֶד שָׁלשׁ:\",1,0],[2,127,1,1,\"בָדָד. גַּלְמוּד מִיּוֹשְׁבֶיהָ:\",2,0],[2,127,1,1,\"רַבָּתִי עָם. יוּ\\\"ד יְתֵרָה, כְּמוֹ \\\"רַבַּת עָם\\\", שֶׁהָיְתָה עַמָּהּ רַב. יֵשׁ מִדְרְשֵׁי אַגָּדָה הַרְבֵּה, וַאֲנִי בָאתִי לְפָרֵשׁ לְשׁוֹן הַמִּקְרָא כְּמַשְׁמָעוֹ:\",3,0],[2,127,1,1,\"הָיְתָה כְּאַלְמָנָה. וְלֹא אַלְמָנָה מַמָּשׁ, אֶלָּא כְאִשָּׁה שֶׁהָלַךְ בַּעְלָהּ לִמְדִינַת הַיָּם וְדַעְתּוֹ לַחֲזוֹר אֶצְלָהּ:\",4,0],[2,127,1,2,\"בָּכוֹ תִבְכֶּה. שְׁתֵּי בְכִיּוֹת עַל שְׁתֵּי חֻרְבָּנִין:\",1,0],[2,127,1,2,\"בַּלַּיְלָה. שֶׁהַמִּקְדָּשׁ נִשְׂרַף בַּלַּיְלָה, דְּאָמַר מַר \\\"לְעֵת עֶרֶב הִצִּיתוּ בוֹ אֶת הָאוּר\\\". דָּבָר אַחֵר: \\\"בַּלַיְלָה\\\", לַיְלָה שֶׁל בְּכִיַּת מְרַגְּלִים בְּתִשְׁעָה בְאָב גָּרְמָה לָהֶם. דָּבָר אַחֵר: \\\"בַּלַּיְלָה\\\", שֶׁכָּל הַבּוֹכֶה בַלַּיְלָה, הַשּׁוֹמֵעַ קוֹלוֹ בּוֹכֶה עִמּוֹ:\",2,0],[2,127,1,2,\"וְדִמְעָתָהּ עַל לֶחֱיָהּ. מִתּוֹךְ שֶׁהִיא בוֹכָה תָמִיד:\",3,0],[2,127,1,2,\"כָּל רֵעֶיהָ. אוֹהֲבֶיהָ:\",4,0],[2,127,1,3,\"גָּלְתָה יְהוּדָה. מֵאַרְצָהּ:\",1,0],[2,127,1,3,\"מֵעֹנִי. מֵחֲמַת עֹנִי:\",2,0],[2,127,1,3,\"וּמֵרֹב עֲבֹדָה. שֶׁהִכְבִּידוּ עָלֶיהָ כַשְׂדִּים:\",3,0],[2,127,1,3,\"הִיא יָשְׁבָה בַגּוֹיִם. וּבַמָּקוֹם שֶׁגָּלְתָה וְיָשְׁבָה שָׁם, לֹא מָצְאָה מָנוֹחַ:\",4,0],[2,127,1,3,\"בֵּין הַמְּצָרִים. שֶׁיֵּשׁ גֹּבַהּ מִכַּאן וּמִכַּאן וְאֵין מָקוֹם לָנוּס:\",5,0],[2,127,1,3,\"הַמְּצָרִים. גְּבוּלִים שֶׁל שָׂדֶה וָכָרֶם. וּמִדְרַשׁ אַגָּדָה, בֵּין שִׁבְעָה עָשָׂר בְּתַמּוּז לְתִשְׁעָה בְאָב:\",6,0],[2,127,1,4,\"בָּאֵי מוֹעֵד. עוֹלֵי רְגָלִים:\",1,0],[2,127,1,4,\"נוּגוֹת. לְשׁוֹן יָגוֹן וְאֵין שֹׁרֶשׁ בַּתֵּבָה אֶלָּא הַגִּימֶ\\\"ל לְבַדָּהּ:\",2,0],[2,127,1,5,\"שָׁלוּ. יוֹשְׁבִים בְּשַׁלְוָה:\",1,0],[2,127,1,5,\"הוֹגָהּ. הִדְאִיבָהּ, וְהוּא לְשׁוֹן יָגוֹן:\",2,0],[2,127,1,6,\"כְּאַיָּלִים לֹא מָצְאוּ מִרְעֶה. כְּאַיָּלִים אֲשֶׁר לֹא מָצְאוּ מִרְעֶה, שֶׁאֵין לָהֶם כֹּחַ לִבְרֹחַ, שֶׁהֻחְלַשׁ כֹּחָם בְּרָעָב:\",1,0],[2,127,1,6,\"לִפְנֵי רוֹדֶף. כָּל \\\"רֹדֵף\\\" שֶׁבַּמִּקְרָא חָסֵר, וְזֶה מָלֵא, שֶׁנִּרְדְּפוּ רְדִיפָה שְׁלֵמָה עַל כֵּן יָסַד הַפַּיָּט, \\\"מָלֵא רֻדַּפְתִּי וְחָסְרָה שְׁנַת גְּאוּלַי\\\". \\\"שְׁנַת גְּאֻלַי בָּאָה\\\" חָסֵר כְּתִיב:\",2,0],[2,127,1,7,\"זָכְרָה יְרוּשָׁלַםִ. בְּגָלוּתָהּ:\",1,0],[2,127,1,7,\"יְמֵי עָנְיָהּ. יְמֵי חֻרְבָּנָה שֶׁהֱבִיאָהּ לִידֵי עֹנִי:\",2,0],[2,127,1,7,\"וּמְרוּדֶיהָ. הִיא לְשׁוֹן צַעַר, כְּמוֹ \\\"וְיָרַדְתִּי עַל הֶהָרִים\\\", \\\"אָרִיד בְּשִׂיחִי וְאָהִימָה\\\":\",3,0],[2,127,1,7,\"כֹּל מַחֲמֻדֶיהָ. וְזָכְרָה כָל טוּב מַחֲמֻדֶיהָ שֶׁמִּימֵי קֶדֶם:\",4,0],[2,127,1,7,\"שָׂחֲקוּ עַל מִשְׁבַּתֶּהָ. שָׂמְחוּ עַל שְׁבִיתַת מְשׂוֹשָׂהּ, חַגָּהּ, חָדְשָׁהּ וְשַׁבַּתָּהּ וּמִדְרַשׁ אַגָּדָה דוֹרְשׁוֹ בְלָשׁוֹן אַחֵר, שֶׁהָיוּ שׁוֹבְתִין בַּגּוֹלָה בְשַׁבָּתוֹת וְיָמִים טוֹבִים וְשׁוֹמְטִים בִשְׁבִיעִית, וְהָיוּ הָעַכּוּ\\\"ם מְשַׂחֲקִים עֲלֵיהֶם וְאוֹמְרִים \\\"שׁוֹטִים, בְּאַרְצְכֶם לֹא שְׁמַטְתֶּם, וְעַכְשָׁיו בַּגּוֹלָה תִשְׁמְטוּ? בְּאַרְצְכֶם לֹא שְׁמַרְתֶּם, וְעַכְשָׁיו בַּגּוֹלָה תִשְׁמְרוּן?\\\":\",5,0],[2,127,1,8,\"לְנִידָה. לְגוֹלָה, לְשׁוֹן \\\"נָע וָנָד\\\", אישמוב\\\"ר בְּלַעַ\\\"ז:\",1,0],[2,127,1,8,\"עֶרְוָתָהּ. קְלוֹנָהּ:\",2,0],[2,127,1,8,\"נֶאֶנְחָה. לְשׁוֹן נִפְעֲלָה, שושפיר\\\"ר בְּלַעַ\\\"ז. \\\"שָׁמְעוּ כִּי נֶאֱנָחָה אָנִי\\\" הוּא שֵׁם דָּבָר, שושפוריר\\\"א בְּלַעַ\\\"ז:\",3,0],[2,127,1,9,\"טֻמְאָתָהּ בְּשׁוּלֶיהָ. לְשׁוֹן גְּנַאי הוּא. דַּם נִדּוֹתָהּ נִכָּר בְּשׁוּלֵי בְגָדֶיהָ. כְּלוֹמַר, חַטּאוֹתֶיהָ גְלוּיִין. הַרְבֵּה עֲשָׂאָתַן בְּגָלוּי:\",1,0],[2,127,1,9,\"לֹא זָכְרָה אַחֲרִיתָהּ. כְּשֶׁהָיוּ חוֹטְאִין, לֹא נָתְנוּ לֵב מַה תִּהְיֶה אַחֲרִיתָן, לְפִיכָךְ, \\\"וַתֵּרֶד פְּלָאִים\\\". יְרִידָתָהּ נִפְלֵאת פְּלָאִים הַרְבֵּה, שֶׁהַכֹּל מַפְלִיאִים שֶׁאֵירַע לָהּ מַה שֶׁלֹּא אֵירַע לְכָל עִיר:\",2,0],[2,127,1,10,\"יָדוֹ פָּרַשׂ צָר. עַמּוֹן וּמוֹאָב:\",1,0],[2,127,1,10,\"עַל כָּל מַחֲמַדֶּיהָ. סִפְרֵי תוֹרוֹת, שֶׁנֶּאֱמַר בָּהֶם \\\"הַנֶּחֱמָדִים מִזָּהָב\\\". הַכֹּל נִפְנוּ לָבוֹז כֶּסֶף וְזָהָב, וְהֵם נִפְנִים עַל סִפְרֵי תוֹרוֹת כְּדֵי לְשָׂרְפָם, לְפִי שֶׁכָּתוּב בָּהֶם \\\"לֹא יָבֹא עַמּוֹנִי וְגוֹ'\\\": אֲשֶׁר צִוִּיתָה\",2,0],[2,127,1,10,\"לֹא יָבֹאוּ בַקָּהָל לָךְ. אֵלּוּ עַמּוֹן וּמוֹאָב:\",3,0],[2,127,1,12,\"לוֹא אֲלֵיכֶם. לֹא תְהֵא כַצָּרָה הַזֹּאת עוֹד לְכָל עוֹבְרֵי עַל דָּת. אָמְרוּ חֲכָמִים, מִכַּאן לְקוּבְלָנָא מִן הַתּוֹרָה. רְאוּ מֶה עָשָׂה לִי. \\\"הַבִּיטוּ וּרְאוּ וְגוֹ'\\\":\",1,0],[2,127,1,12,\"אֲשֶׁר עוֹלַל לִי. אֲשֶׁר נַעֲשָׂה לִי:\",2,0],[2,127,1,12,\"אֲשֶׁר הוֹגָה ה'. אוֹתִי בְּיוֹם חֲרוֹן אַפּוֹ. גַּם זֶה לְשׁוֹן יָגוֹן:\",3,0],[2,127,1,13,\"וַיִּרְדֶּנָּה. וַיִּרֶד אוֹתָהּ, וַיְשַׁבֵּר אוֹתָהּ עַל יְדֵי רִדּוּי וְיִסּוּרִין, לָכֵן הַנּוּ\\\"ן דְּגוּשָׁה, לְפָתְרוֹ בְּלָשׁוֹן יְחִידִית, כְּמוֹ יַעֲשֶׂנָּה, יְכַרְסְמֶנָּה, יִרְעֶנָּה, שֶׁהָעֶצֶם לְשׁוֹן נְקֵבָה, כְּמָה דְאַתְּ אָמַר \\\"הָעֲצָמוֹת הַיְבֵשׁוֹת\\\". שִׁבֵּר כָּל אַחַת וְאֶחָת. דָּבָר אַחֵר: \\\"וַיִּרְדֶּנָּה\\\" כְּמוֹ \\\"וַיִּרְדֵּהוּ אֶל כַּפָּיו\\\". הֵרִיק אֶת הַמּוֹחַ, גּוֹרֵר וְרוֹדֶה הַמּוֹחַ מִתּוֹכוֹ:\",1,0],[2,127,1,14,\"נִשְׂקַד עֹל פְּשָׁעַי בְּיָדוֹ. אֵין לְתֵבָה זוּ דִמְיוֹן בַּמִּקְרָא וּבְלָשׁוֹן אֲרַמִּי שֶׁל פְּסִיקְתָּא קוֹרִין לְדָרְבָן מַסְקָדָא, מַלְמַד הַבָּקָר. וְאוֹמֵר אֲנִי, \\\"נִשְׂקַד\\\" פיינטרינ\\\"ט בְּלַעַ\\\"ז. נְקֻדִּים, מְנֻמָּרִים וּמְסֻמָּנִים הָיוּ פְשָׁעַי בְּיָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְזִכָּרוֹן. לֹא נִשְׁכַּח מִנְיָנָם וְתַשְׁלוּמֵיהֶם:\",1,0],[2,127,1,14,\"יִשְׂתָּרְגוּ. נַעֲשׂוּ קְלִיעוֹת קְלִיעוֹת וְעָלוּ עַל צַוָּארִי, לְשׁוֹן מִשְׁנָה, אֵין מְסָרְגִין אֶת הַמִּטּוֹת:\",2,0],[2,127,1,15,\"סִלָּה. רָמַס וְרָפַס, לְשׁוֹן \\\"סֹלּוּ סֹלּוּ הַמְסִלָּה\\\":\",1,0],[2,127,1,15,\"קָרָא עָלַי מוֹעֵד. יְעִידַת גְיָסוֹת לָבֹא עָלָי. וְרַבּוֹתֵינוּ דָרְשׁוּ מַה שֶׁדָּרְשׁוּ. תַּמּוּז דְּהַהִיא שַׁתָּא מְלוּיֵי מַלְיוּהָ, שֶׁל שָׁנָה שְׁנִיָּה לְצֵאתָם מִמִּצְרָיִם. לְכַךְ, אֵירַע חֲזָרָתָן שֶׁל מְרַגְּלִים לֵיל תִּשְׁעָה בְאָב, שֶׁעָלֶיהָ הֻקְבְּעָה בְכִיָּתָן לְדוֹרוֹת:\",2,0],[2,127,1,15,\"גַּת דָּרַךְ. לְשׁוֹן הֲרֵגָה, כְּמוֹ \\\"פּוּרָה דָרַכְתִּי לְבַדִּי\\\". כְּדוֹרֵךְ עֲנָבִים לְהוֹצִיא יֵינָם, כַּךְ רָמַס הַנָּשִׁים לְהוֹצִיא דָמָם:\",3,0],[2,127,1,16,\"עֵינִי עֵינִי. כְּלוֹמַר, תָּמִיד עֵינִי יוֹרְדָה מַיִם. כֵּפֶל הַלָּשׁוֹן מְלַמֵּד שֶׁאֵין הַפוּגוֹת:\",1,0],[2,127,1,17,\"פֵּרְשָׂה צִיּוֹן בְּיָדֶיהָ. כְּמוֹ \\\"וּפֵרַשׂ יָדָיו בְּקִרְבּוֹ\\\", כְּאָדָם הַמּוֹלִיךְ יָדָיו, מוֹלִיכָם וּמְבִיאָם וּמִצְטַעֵר בָּהֶם. דָּבָר אַחֵר: \\\"פֵּרְשָׂה צִיּוֹן\\\" לְשׁוֹן שְׁבִירָה, כְּמוֹ \\\"פּוֹרֵשׂ אֵין לָהֶם\\\", \\\"וְלֹא יִפְרְסוּ לָהֶם עַל אָבֵל, לְנַחֲמוֹ עַל מֵת\\\": כַּךְ חִבְּרוֹ מְנַחֵם. וּבִלְשׁוֹן מִשְׁנָה, \\\"פְּרוּסָה קַיֶּמֶת\\\". וּמַשְׁמָעוֹ, כָּאָדָם הַמִּצְטַעֵר שֶׁחוֹבֵק אֶת יָדָיו וּמְשַׁבְּרָם. תּוֹסֶפֶת מָצָאתִי: צִוָּה ה' לְיַעֲקֹב\",1,0],[2,127,1,17,\"סְבִיבָיו צָרָיו. צִוָּה עַל יַעֲקֹב שֶׁיִּהְיוּ צָרָיו סְבִיבָיו. אַף כְּשֶׁגָּלוּ לְבָבֶל וּלְאַשּׁוּר, הֶגְלָה סַנְחֵרִיב אֶת אוֹיְבֵיהֶם, עַמּוֹן וּמוֹאָב, וְהוֹשִׁיבָם אֶצְלֵיהֶם, וְהֵם מְקַנְתְּרִים אוֹתָם, כְּמוֹ שֶׁאָמְרוּ בְּמַסֶּכֶת קִדּוּשִׁין: הוּמַנְיָא אִיכָּא בְּבָבֶל, כֻּלָּהּ דְּעַמּוֹנָאֵי:\",2,0],[2,127,1,17,\"לְנִדָּה. לְרִחוּק, לָבוּז:\",3,0],[2,127,1,19,\"קָרָאתִי לַמְּאַהֲבַי. לְאוֹתָם שֶׁמַּרְאִים עַצְמָם כְּאוֹהֲבִים:\",1,0],[2,127,1,19,\"הֵמָּה רִמּוּנִי. כְּגוֹן בְּנֵי יִשְׁמָעֵאל שֶׁהָיוּ יוֹצְאִים לִקְרַאת הַגוֹלִים כְּשֶׁהָיוּ הַשַׁבָּאִים מוֹלִיכִים אוֹתָם דֶּרֶךְ עֲלֵיהֶם וּמַרְאִים אֶת עַצְמָם כְּאִלּוּ מְרַחֲמִים עֲלֵיהֶם, וְהָיוּ מוֹצִיאִים לָהֶם מִינֵי מְלוּחִים וְנוֹדוֹת נְפוּחִים כִּסְבוּרִים שֶׁהוּא יַיִן, וְאוֹכְלִים וּצְמֵאִים וְרוֹצִים לִשְׁתּוֹת, וּכְשֶׁמַּתִּיר הַנּוֹד בְּשִׁנָּיו, הָיְתָה הָרוּחַ נִכְנֶסֶת בְּמֵעָיו וְהוּא מֵת. וְהוּא שֶׁאָמַר הַכָּתוּב \\\"בַּיַּעַר בַּעְרַב תָּלִינוּ וְגוֹ'\\\", \\\"לִקְרַאת צָמֵא הֵתָיוּ מָיִם ישְׁבֵי אֶרֶץ תֵּימָא בְּלַחְמוֹ קִדְּמוּ נוֹדֵד\\\":\",2,0],[2,127,1,19,\"וְיָשִׁיבוּ אֶת נַפְשָׁם. כְּדֵי שֶׁיָּשִׁיבוּ אֶת נַפְשָׁם:\",3,0],[2,127,1,20,\"חֳמַרְמְרוּ. כֻּוְּצוּ, וְיֵשׁ כָּזֶה בִלְשׁוֹן מִשְׁנָה: נָפְלָה לְאוּר, וְנֶחְמְרוּ בְנֵי מֵעֶיהָ:\",1,0],[2,127,1,20,\"בַּבַּיִת כַּמָּוֶת. בְּתוֹךְ הַבַּיִת הָיְתָה אֵימַת שֵׁדִים וּמַזִּיקִים וּמַלְאֲכֵי מָוֶת, וּמִחוּץ חֶרֶב הָאוֹיֵב מְשַׁכָּלֶת:\",2,0],[2,127,1,21,\"כִּי אַתָּה עָשִׂיתָ. אַתָּה גָרַמְתָּ לִי שֶׁהֵם שׂוֹנְאִים אוֹתִי, שֶׁהִבְדַּלְתַּנִי מִמַּאֲכָלָם וּמִמִּשְׁתֵּיהֶם וּמֵהִתְחַתֵּן בָּם. אִם נִתְחַתַּנְתִּי בָהֶם, הָיוּ מְרַחֲמִים עָלַי וְעַל בְּנֵי בְנוֹתֵיהֶם:\",1,0],[2,127,1,21,\"הֵבֵאתָ יוֹם קָרָאתָ. הַלְוַאי וְהֵבֵאתָ עֲלֵיהֶם יוֹם הַמּוֹעֵד שֶׁקָּרָאתָ עָלָי:\",2,0],[2,127,1,21,\"וְיִהְיוּ כָמֹנִי. בְרָעָה:\",3,0],[2,127,1,22,\"תָּבֹא כָל רָעָתָם לְפָנֶיךָ. יִזָּכְרוּ וְיִפָּקְדוּ עֲוֹנוֹתָם לְפָנֶיךָ:\",1,0],[2,127,1,22,\"וְעוֹלֵל לָמוֹ. וּפְעוֹל לָמוֹ, כְּמוֹ \\\"גַּם בְּמַעֲלָלָיו יִתְנַכֶּר\\\", \\\"וְכִפְרִי מַעֲלָלָיו\\\":\",2,0],[2,127,2,1,\"אֵיכָה יָעִיב. יַאֲפִיל, כְּמָה דְאַתְּ אָמַר \\\"וְהַשָּׁמַיִם הִתְקַדְּרוּ עָבִים\\\":\",1,0],[2,127,2,1,\"מִשָּׁמַיִם אֶרֶץ. לְאַחַר שֶׁהִגְבִּיהָם עַד לַשָּׁמַיִם, הִשְׁלִיכָם לָאָרֶץ בְּבַת אַחַת וְלֹא מְעַט מְעַט; מִאִיגְרָא רָמָא לְבֵירָא עֲמִיקְתָּא:\",2,0],[2,127,2,1,\"הֲדֹם רַגְלָיו. שְׁרַפְרַף מַרְגְּלוֹתָיו, וְזֶה בֵית הַמִּקְדָּשׁ:\",3,0],[2,127,2,2,\"נְאוֹת יַעֲקֹב. בָּתֵּי יַעֲקֹב, לְשׁוֹן נָוֶה:\",1,0],[2,127,2,2,\"הִגִּיעַ לָאָרֶץ. הִשְׁפִּילָם לָאָרֶץ:\",2,0],[2,127,2,2,\"חִלֵּל מַמְלָכָה וְשָׂרֶיהָ. אֵלּוּ יִשְׂרָאֵל שֶׁהָיוּ קְרוּיִם \\\"מַמְלֶכֶת כֹּהֲנִים\\\":\",3,0],[2,127,2,2,\"וְשָׂרֶיהָ. מִדְרַשׁ אַגָּדָה יֵשׁ: אֵלּוּ שָׂרִים שֶׁל מַעְלָה שֶׁהֶחֱלִיפָם. הַמְמֻנֶּה עַל הָאוּר מִנָּה עַל הַמַּיִם, וְהֶחֱלִיף כָּל הַמְמֻנִּים, לְפִי שָׁהָיוּ בְרִשְׁעֵי יִשְׂרָאֵל בַּעֲלֵי שֵׁם הַמְפֹרָשׁ וּבוֹטְחִים הֵם שֶׁיַּשְׁבִּיעוּ אֶת שָׂרֵי מַעְלָה לְהַצִּילָם מֵאֵשׁ וּמִמַּיִם וּמֵחֶרֶב, וְעַכְשָׁיו, כְּשֶׁהָיָה מַשְׁבִּיעַ אֶת שַׂר הָאֵשׁ בִּשְׁמוֹ, וְהוּא מֵשִׁיב: \\\"אֵין מֶמְשָׁלָה זוּ בְיָדִי\\\". וְכֵן כֻּלָּם:\",4,0],[2,127,2,3,\"הֵשִׁיב אָחוֹר יְמִינוֹ. הֵשִׁיב עַצְמוֹ כְּמֵשִׁיב אָחוֹר יְמִינוֹ מִלְּהִלָּחֵם בְּעַד בָּנָיו:\",1,0],[2,127,2,4,\"דָּרַךְ קַשְׁתּוֹ. לְפִי שֶׁכַּךְ דֶּרֶךְ דּוֹרְכֵי קֶשֶׁת שֶׁהֵם חֲזָקִים, לָשׂוּם רַגְלוֹ עֲלֵיהֶם כְּשֶׁהוּא כוֹפְפָם, לְכַךְ נִכְתַּב בִּלְשׁוֹן דְּרִיכָה:\",1,0],[2,127,2,4,\"שָׁפַךְ כָּאֵשׁ חֲמָתוֹ. כַּךְ חִבּוּר הַמִּלּוֹת, שָׁפַךְ חֲמָתוֹ שֶׁהִיא כָאֵשׁ. כִּי לֹא מָצִינוּ שְׁפִיכָה שֶׁל אֵשׁ אֶלָּא אֵצֶל חֵמָה, כְּדִכְתִיב \\\"שְׁפֹךְ חֲמָתְךָ אֶל הַגּוֹיִם\\\":\",2,0],[2,127,2,5,\"וַיֶּרֶב בְּבַת יְהוּדָה. הִרְבָּה בִכְנֶסֶת יְהוּדָה:\",1,0],[2,127,2,5,\"תַּאֲנִיָּה וַאֲנִיָּה. צַעַר וִילָלָה:\",2,0],[2,127,2,5,\"וַיֶּרֶב. נָקוּד יוּ\\\"ד פַּתָּ\\\"ח קָטָן שֶׁהוּא לְשׁוֹן הִרְבָּה אֶת אֲחֵרִים. \\\"וַיִּרֶב הָעָם וַיַּעַצְמוּ מְאֹד\\\" נָקוּד חִירִ\\\"ק שֶׁהוּא לְשׁוֹן רָבָה הוּא אֶת עַצְמוֹ. וְכֵן כָּל תֵּיבָה שֶׁפָּעַל שֶׁלָּהּ בְּהֵ\\\"א, כְּגוֹן, פָּנָה, זָנָה, בָּכָה, כֵּן דַּרְכָּהּ לְשַׁמֵּשׁ כְּשֶׁהוּא מְחַסֵּר מִמֶּנָּה הֵ\\\"א, כְּשֶׁהוּא מְדַבֵּר עַל עַצְמוֹ נָקוּד חִירִ\\\"ק, כְּגוֹן, \\\"וַיִּפֶן פַּרְעֹה\\\". וּכְשֶׁהוּא מְדַבֵּר עַל אֲחֵרִים, נָקוּד פַּתָּ\\\"ח קָטָן, כְּגוֹן, \\\"וַיֶּפֶן זָנָב אֶל זָנָב\\\", \\\"וַיִּגֶל יְהוּדָה מֵעַל אַדְמָתוֹ\\\", \\\"וַיֶּגֶל מֶלֶךְ בָּבֶל אֶת יִשְׂרָאֵל אַשׁוּרָה\\\":\",3,0],[2,127,2,6,\"וַיַּחְמֹס. לְשׁוֹן כְּרִיתָה, וְכֵן: \\\"יַחְמֹס כַּגֶּפֶן\\\", נֶחְמְסוּ עֲקֵבָיִךְ:\",1,0],[2,127,2,6,\"כַּגַּן. כְּמוֹ שֶׁגּוֹזְזִין יַרְקוֹת הַגִּנָּה:\",2,0],[2,127,2,6,\"שֻׂכּוֹ. מְעוֹנָתוֹ. \\\"שִׁכּוֹ\\\" כְּתִיב, שֶׁשִׁכֵּךְ חֲמָתוֹ עַל בָּנָיו בְּחֻרְבַּן בֵּיתוֹ. כַּךְ נִדְרָשׁ בְּמִדְרַשׁ קִינוֹת:\",3,0],[2,127,2,6,\"שִׁחֵת מוֹעֲדוֹ. בֵּית קָדְשֵׁי הַקֳּדָשִׁים, שֶׁשָּׁם הָיָה נוֹעָד לְבָנָיו, שֶׁנֶּאֱמַר \\\"וְנוֹעַדְתִּי לְךָ שָׁם\\\":\",4,0],[2,127,2,6,\"מֶלֶךְ וְכֹהֵן. צִדְקִיָּהוּ הַמֶּלֶךְ וּשְׂרָיָהוּ כֹּהֵן גָּדוֹל:\",5,0],[2,127,2,7,\"נִאֵר. בִּטֵּל. וְכֵן \\\"נֵאַרְתָּה בְּרִית עַבְדֶּךָ\\\":\",1,0],[2,127,2,7,\"כְּיוֹם מוֹעֵד. שֶׁהָיוּ שְׂמֵחִים וּמְשׁוֹרְרִים בְּתוֹכוֹ בְקוֹל רָם, כֵּן נָתְנוּ הָאוֹיְבִים בְּחֻרְבָּנוֹ קוֹל שִׂמְחָה:\",2,0],[2,127,2,8,\"חָשַׁב ה' לְהַשְׁחִית. זֶה יָמִים רַבִּים שֶׁעָלְתָה עַל דַּעְתּוֹ כַךְ, שֶׁנֶּאֱמַר \\\"כִּי עַל אַפִּי וְעַל חֲמָתִי הָיְתָה לִי הָעִיר הַזֹּאת לַהֲסִירָהּ מֵעַל פָּנָי\\\":\",1,0],[2,127,2,8,\"נָטָה קָו. שֶׁל מִשְׁפָּט לִפָּרַע עַל עֲוֹנֵינוּ:\",2,0],[2,127,2,8,\"מִבַּלֵּעַ. מֵהַשְׁחִית:\",3,0],[2,127,2,8,\"חֵל וְחוֹמָה. שׁוּרָא וּבַר שׁוּרָא, חוֹמָה נְמוּכָה שֶׁכְּנֶגֶד חוֹמָה גְבוֹהָה:\",4,0],[2,127,2,9,\"טָבְעוּ בָאָרֶץ שְׁעָרֶיהָ. מִדְרַשׁ אַגָּדָה: לְפִי שֶׁחָלְקוּ כָבוֹד לָאָרוֹן, שֶׁנֶּאֱמַר \\\"שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם\\\". לְפִיכָךְ לֹא שָׁלְטָה בָהֶם בִּרְיָה וְטָבְעוּ בָאָרֶץ. וְרַבּוֹתֵינוּ אָמְרוּ, מַעֲשֵׂי יְדֵי דָוִד הָיוּ, לְפִיכָךְ לֹא שָׁלְטוּ בָהֶם אוֹיְבִים:\",1,0],[2,127,2,9,\"אֵין תּוֹרָה. אֵין בָּהֶם מוֹרֵה הוֹרָאָה:\",2,0],[2,127,2,10,\"יֵשְׁבוּ לָאָרֶץ וְגוֹ'. כְּמַשְׁמָעוֹ, וּמִדְרַשׁ אַגָּדָה: נְבוּכַדְנֶצַּר הוֹשִׁיבָם לָאָרֶץ. כְּשֶׁמָּרַד בּוֹ צִדְקִיָּהוּ וְעָבַר עַל שְׁבוּעָתוֹ, בָּא וְיָשַׁב לוֹ בְדָּפְנָה שֶׁל אַנְטוּכְיָא וְשָׁלַח בִּשְׁבִיל סַנְהֶדְרִין, וּבָאוּ לִקְרָאתוֹ, וְרָאָה אוֹתָם אֲנָשִׁים שֶׁל צוּרָה, וְהוֹשִׁיב אוֹתָם בְּקַתֵּדְרָאוֹת שֶׁל זָהָב. אָמַר לָהֶם: \\\"סַדְּרוּ לִי תוֹרַתְכֶם פָּרָשָׁה וּפָרָשָׁה וְתַרְגְּמוּהָ לִי\\\". כֵּיוָן שׁהִגִּיעוּ לְפָרָשַׁת נְדָרִים, אָמַר לָהֶם, \\\"אִם הוּא רוֹצֶה לַחֲזוֹר, יָכוֹל הוּא לַחֲזוֹר?\\\" אָמְרוּ לוֹ, \\\"יֵלֵךְ אֵצֶל חָכָם וְיַתִּיר לוֹ\\\". אָמַר לָהֶם, \\\"אִם כֵּן, אַתֶּם הִתַּרְתֶּם לְצִדְקִיָּהוּ אֶת שְׁבוּעָתוֹ\\\". צִוָּה וּשְׁמָטוּם וְהוֹשִׁיבָם לָאָרֶץ, וְקָשְׁרוּ שַׂעְרוֹת רֹאשָׁם בְּזַנְבוֹת הַסּוּסִים וּגְרָרוּם:\",1,0],[2,127,2,11,\"חֳמַרְמְרוּ. רגיזליר\\\"ט בְּלַעַ\\\"ז דֶּרֶךְ בְּנֵי מֵעַיִם, כְּשֶׁמַּשְׁלִיכָם אָדָם לָאוּר, הֵם כּוֹוְצִים וּמִתְחֲמַרְמְרִים:\",1,0],[2,127,2,11,\"בֵּעָטֵף. פשמי\\\"ר:\",2,0],[2,127,2,13,\"מָה אֲעִידֵךְ מָה אֲדַמֶּה לָּךְ. לוֹמַר לָךְ: \\\"מַה תִּתְמְהִי עַל שִׁבְרֵךְ? הֲלֹא אַף לְאֻמָּה פְלוֹנִית אֵרַע כְּמוֹתֵךְ\\\"?\",1,0],[2,127,2,13,\"מָה אַשְׁוֶה לָּךְ וַאֲנַחֲמֵךְ. כְּשֶׁבָּאָה צָרָה עַל אָדָם, אוֹמְרִים לוֹ: \\\"אַף לִפְלוֹנִי עָלְתָה כָךְ\\\". תַּנְחוּמִים הֵם לוֹ:\",2,0],[2,127,2,14,\"שָׁוְא וְתָפֵל. דְּבָרִים שֶׁאֵין בָּהֶם טַעַם. וּבִלְשׁוֹן לַעַ\\\"ז אפלשטרימנ\\\"ט:\",1,0],[2,127,2,14,\"וְלֹא גִלּוּ עַל עֲוֹנֵךְ. לְהוֹכִיחַ דַּרְכֵּךְ עַל פָּנָיִךְ:\",2,0],[2,127,2,14,\"לְהָשִׁיב שְׁבוּתֵךְ. לְיַשֵׁר מְשׁוּבוֹתַיִךְ, לְשׁוֹן \\\"שׁוֹבְבָה\\\", \\\"שׁוֹבָבִים\\\", \\\"וַיֵּלֶךְ שׁוֹבָב\\\".\",3,0],[2,127,2,14,\"וּמַדּוּחִים. הִדִּיחוּךְ מֵעָלָי:\",4,0],[2,127,2,15,\"שָׁרְקוּ. נוֹפֵחַ בְּפִיו, שיבלי\\\"ר בְּלַעַ\\\"ז, וְדֶרֶךְ אָדָם לַעֲשׂוֹת כֵּן הָרוֹאֶה דָבָר חָשׁוּב שֶׁחָרַב וְכָלָה:\",1,0],[2,127,2,15,\"כְּלִילַת יֹפִי. כָּל הַיּוֹפִי הָיָה שֶׁלָּהּ:\",2,0],[2,127,2,16,\"פָּצוּ עָלַיִךְ פִּיהֶם. מִפְּנֵי מָה הִקְדִּים פֵּ\\\"א לְעַיִ\\\"ן? מִפְּנֵי שֶׁהָיוּ אוֹמְרִים בְּפִיהֶם מַה שֶׁלֹּא רָאוּ בְּעֵינֵיהֶם:\",1,0],[2,127,2,17,\"בִּצַּע אֶמְרָתוֹ. כִּלָּה גְזֵרָתוֹ, כְּמוֹ \\\"יַתֵּר יָדוֹ וִיבַצְּעֵנִי\\\":\",1,0],[2,127,2,17,\"אֲשֶׁר צִוָּה מִימֵי קֶדֶם. מַה שֶׁכָּתוּב בַּתּוֹרָה \\\"וְיָסַפְתִּי לְיַסְּרָה אֶתְכֶם שֶׁבַע\\\":\",2,0],[2,127,2,18,\"פוּגַת. הָעֲבָרָה, טרישאלמינ\\\"ט, כְּמוֹ \\\"וַיָּפָג לִבּוֹ\\\".\",1,0],[2,127,2,18,\"בַּת עֵינֵךְ. שָׁחוֹר שֶׁל עַיִן שֶׁקּוֹרִין פרוניל\\\"ט:\",2,0],[2,127,2,19,\"אַשְׁמֻרוֹת. שְׁנֵי חֶלְקֵי הַלַּיְלָה, שֶׁהַלַּיְלָה נֶחֱלֶקֶת לִשְׁלשָׁה חֲלָקִים, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ בְמַסֶּכֶת בְּרָכוֹת:\",1,0],[2,127,2,19,\"הָעֲטוּפִים. אשפומי\\\"ן בְּלַעַ\\\"ז:\",2,0],[2,127,2,20,\"עֹלְלֵי טִפֻּחִים. יְלָדִים רַכִּים שֶׁעוֹדָן גְּדֵלִים בְּטִפּוּחֵי אִמּוֹתָם. וְרַבּוֹתֵינוּ דָרְשׁוּ עַל דּוֹאֵג בֶּן יוֹסֵף שֶׁהָיְתָה אִמּוֹ מוֹדַדְתּוֹ בִטְפָחִים בְּכָל יוֹם וָיוֹם לָתֵת זָהָב לְבֵית הַמִּקְדָּשׁ לְפִי מַה שֶׁהָיָה גָדֵל, וּלְבַסּוֹף אֲכָלַתּוּ:\",1,0],[2,127,2,20,\"אִם יֵהָרֵג בְּמִקְדַּשׁ ה' כֹּהֵן וְנָבִיא. רוּחַ הַקֹּדֶשׁ מְשִׁיבָתָם \\\"וְכִי נָאֶה לָכֶם שֶׁהֲרַגְתֶּם אֶת זְכַרְיָה בֶּן יְהוֹיָדָע\\\", כְּמוֹ שֶׁכָּתוּב בְּדִבְרֵי הַיָּמִים, שֶׁהוֹכִיחָם כְּשֶׁבָּאוּ לְהִשְׁתַּחֲוֹת לְיוֹאָשׁ וַעֲשָׂאוּהוּ עֲבוֹדַת אֱלִילִים \\\"וְרוּחַ לָבְשָׁה אֶת זְכַרְיָה בֶן יְהוֹיָדָע\\\". וְהָיָה כֹהֵן וְנָבִיא, וַהֲרָגוּהוּ בָעֲזָרָה:\",2,0],[2,127,2,22,\"תִּקְרָא כְיוֹם מוֹעֵד. כְּמוֹ \\\"קָרָאתָ\\\". וּלְשׁוֹן הֹוֶה הוּא:\",1,0],[2,127,2,22,\"מְגוּרַי. שְׁכֻנַי הָרָעִים לְהֵאָסֵף עָלַי לְהַשְׁחִית:\",2,0],[2,127,2,22,\"אֲשֶׁר טִפַּחְתִּי וְרִבִּיתִי אוֹיְבִי כִלָּם. הַיְלָדִים אֲשֶׁר טִפַּחְתִּי וְגִדַּלְתִּי אוֹתָם בָּא הָאוֹיֵב וְכִלָּה אוֹתָם:\",3,0],[2,127,3,1,\"אֲנִי הַגֶּבֶר רָאָה עֳנִי. הָיָה מִתְאוֹנֵן יִרְמְיָה לוֹמַר: \\\"אֲנִי הַגֶּבֶר רָאָה עֳנִי\\\", אֲשֶׁר רָאָה עֹנִי מִכָּל הַנְּבִיאִים שֶׁנִּתְנַבְּאוּ עַל חֻרְבַּן הַבַּיִת, שֶׁבִּימֵיהֶם לֹא נֶחֱרַב הַבַּיִת, כִּי אִם בְּיָמָי:\",1,0],[2,127,3,1,\"בְּשֵׁבֶט עֶבְרָתוֹ. שֶׁל רוֹדֶה וּמַכֶּה, הוּא הַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,127,3,3,\"אַךְ בִּי יָשֻׁב. אֲנִי לְבַדִּי לוֹקֶה תָמִיד, כִּי כָל תְּשׁוּבוֹת מַכּוֹתָיו עָלָי:\",1,0],[2,127,3,4,\"בִּלָּה בְשָׂרִי. כְּמוֹ \\\"לְבוּל עֵץ\\\". דָּבָר אַחֵר: \\\"בִּלָּה בְשָׂרִי וְעוֹרִי\\\". כְּמוֹ \\\"וְהָאָרֶץ כַּבֶּגֶד תִּבְלֶה\\\". כְּלוֹמַר, שָׁכְבוּ לָאָרֶץ חוּצוֹת נַעַר וְזָקֵן, וְלֹא הָיָה לָהֶם כַּר וְכֶסֶת וּבִלָּה בְשָׂרָם כְּשֶׁהֵם גּוֹלִים:\",1,0],[2,127,3,5,\"וַיַּקַּף. הִקִּיפַנִי:\",1,0],[2,127,3,5,\"רֹאשׁ וּתְלָאָה. כְּמוֹ \\\"רֹאשׁ וְלַעֲנָה\\\". וּמִדְרַשׁ אַגָּדָה: רֹאשׁ זֶה נְבוּכַדְנֶצַּר בְּגָלוּת יְהוֹיָכִין. וּתְלָאָה, נְבוּזַרְאֲדָן שֶׁגָּמַר הַמַּכָּה בִימֵי צִדְקִיָּהוּ וְהֶלְאַנִי:\",2,0],[2,127,3,7,\"גָּדַר בַּעֲדִי. עָשָׂה חוֹמָה לְנֶגְדִּי לִהְיוֹת כָּלוּא:\",1,0],[2,127,3,7,\"וְלֹא אֵצֵא. הוֹשִׁיב סְבִיבוֹתַי מַחֲנוֹת וּגְיָסוֹת שֶׁל אוֹרְבִים:\",2,0],[2,127,3,7,\"הִכְבִּיד נְחָשְׁתִּי. עָשָׂה לְרַגְלַי נְחֻשְׁתַּיִם כְּבֵדִים שֶׁלֹא אוּכַל לֵילֵךְ, פיריי\\\"שׁ בְּלַעַ\\\"ז:\",3,0],[2,127,3,8,\"שָׂתַם תְּפִלָּתִי. סָתַם חַלֹּנוֹת הָרָקִיעַ בְּפָנֶיהָ:\",1,0],[2,127,3,9,\"נְתִיבוֹתַי עִוָּה. אִם בָּאתִי לָצֵאת, אֵינִי יוֹצְאָה בַדְּרָכִים הַסְּלוּלִים, בְּדֶרֶךְ יְשָׁרָה, מִפְּנֵי הָאוֹיְבִים, וְאֵצֵא דֶרֶךְ עֲקַלָּתוֹן:\",1,0],[2,127,3,10,\"דֹּב אֹרֵב הוּא לִי. הַקָּדוֹשׁ בָּרוּךְ הוּא נֶהְפַּךְ לִי לְדֹב אוֹרֵב:\",1,0],[2,127,3,11,\"דְּרָכַי סוֹרֵר. לְשׁוֹן סִירִים, קוֹצִים. סוֹרֵר, קוֹוֵץ אוֹתָם, מְפַזֵּר קוֹצִים בִּדְרָכָי:\",1,0],[2,127,3,11,\"וַיְפַשְּׁחֵנִי. לְשׁוֹן פִּסּוּק הָרַגְלַיִם שֶׁהָעוֹבֵר עַל הַדְּרָכִים שֶׁאֵין מֻפְנִים צָרִיךְ לְהַרְחִיב צְעָדָיו. וְיֵשׁ דֻּגְמָא בִלְשׁוֹן גְּמָרָא, \\\"הַאי מַאן דְּפָשַׁח דִּיקְלָא:\",2,0],[2,127,3,12,\"וַיַּצִּיבֵנִי כַּמַּטָּרָא. הֶעֱמִידַנִי כְנֶגֶד חִצִּיו לִירוֹת בִּי כְּמַטָּרָא, אשנייל\\\"א בְּלַעַ\\\"ז:\",1,0],[2,127,3,13,\"בְּנֵי אַשְׁפָּתוֹ. חִצִּים שֶׁנּוֹתְנִין בְּתוֹךְ אַשְׁפָּה שֶׁקּוֹרִין קויכר\\\"א:\",1,0],[2,127,3,16,\"וַיַּגְרֵס. וַיְשַׁבֵּר, וְדֻגְמָתוֹ \\\"גָּרְסָה נַפְשִׁי\\\". וְכֵן, \\\"גֶּרֶשׂ כַּרְמֶל\\\":\",1,0],[2,127,3,16,\"בֶּחָצָץ. אֲבָנִים דַּקִּים שֶׁבְּתוֹךְ הֶעָפָר, שֶׁהָיוּ הַגּוֹלִים לָשִׁין עִסָּתָן בְּתוֹךְ הַגּוּמוֹת שֶׁחוֹפְרִים בַּקַּרְקַע, וְהֶחָצָץ נִכְנָס לְתוֹכָהּ, כְּמוֹ שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לִיחֶזְקֵאל \\\"עֲשֵׂה לְךָ כְּלֵי גוֹלָה\\\" לִשְׁתּוֹת בּוֹ וְלָלוּשׁ בְּתוֹכוֹ חֲרָרָה קְטַנָּה, כְּדֵי שֶׁיִּלְמְדוּ הֵם וְיַעֲשׂוּ כֵן, כָּעִנְיָן שֶׁנֶּאֱמַר \\\"וְהָיָה יְחֶזְקֵאל לָכֶם לְמוֹפֵת\\\". וְהֵם הָיוּ מְשַׂחֲקִים עָלָיו וְלֹא עָשׂוּ כֵן. לְסוֹף נִשְׁתַּבְּרוּ שִׁנֵּיהֶם:\",2,0],[2,127,3,16,\"הִכְפִּישַׁנִי. כָּפָה אוֹתִי בָאֵפֶר כִּכְלִי הַכָּפוּי עַל פִּיו, ארנטי\\\"ר בְּלַעַ\\\"ז, וְיֵשׁ דּוֹמֶה בַמִּשְׁנָה, \\\"פִּישׁוֹן הַגָּמָּל בַּמִּדָּה הַכְּפוּשָׁה מָדַד\\\":\",3,0],[2,127,3,18,\"וָאֹמַר אָבַד נִצְחִי. אָמַרְתִּי בְלִבִּי בְּרֹב צָרוֹתַי, \\\"אָבַד עוֹלָמִי וְסִבְרִי\\\":\",1,0],[2,127,3,19,\"וּמְרוּדִי. אקימפלויינ\\\"ט בְּלַעַ\\\"ז:\",1,0],[2,127,3,20,\"זָכוֹר תִּזְכּוֹר. נַפְשִׁי אֶת עָנְיִי וּמְרוּדִי וְתָשׁוֹחַ עָלַי. כַּךְ הוּא פְשׁוּטוֹ לְפִי עִנְיַן שִׁיטַת הַמִּקְרָא. וּמִדְרַשׁ אַגָּדָה: \\\"זָכוֹר תִּזְכּוֹר\\\", יָדַעְתִּי שֶׁסּוֹפְךָ לִזְכּוֹר אֶת הֶעָשׂוּי לִי, אֲבָל תָּשׁוֹחַ עָלַי נַפְשִׁי לְהַמְתִּין עַד זְמַן הַזְּכִירָה, וּמִכַּאן יִסַּד הַפַּיָּט, \\\"בְּזֹאת יָדַעְתִּי כִּי יֵשׁ לְךָ לִזְכּוֹר, אֲבָל תָּשׁוֹחַ עָלַי נַפְשִׁי עַד שֶׁתִּזְכּוֹר\\\":\",1,0],[2,127,3,21,\"זֹאת אָשִׁיב אֶל לִבִּי. אַחַר שֶׁאָמַר לִי לִבִּי, \\\"אָבְדָה תוֹחַלְתִּי מֵה'\\\", אָשִׁיב זֹאת אֶל לִבִּי וְאוֹחִיל עוֹד. וּמָה הוּא זֹאת שֶׁאָשִׁיב אֶל לִבִּי?\",1,0],[2,127,3,22,\"חַסְדֵי ה' כִּי לֹא תָמְנוּ. וְכָל הָעִנְיָן עַד \\\"מַה יִתְאוֹנֵן וְגוֹ'\\\":\",1,0],[2,127,3,22,\"כִּי לֹא תָמְנוּ. כְּמוֹ כִּי לֹא תַמּוּ. וְיֵשׁ מְפָרְשִׁים \\\"כִּי לֹא תָמְנוּ\\\" כְּמוֹ \\\"הַאִם תַּמְנוּ לִגְוֹעַ\\\". חַסְדֵי ה' הֵם אֲשֶׁר לֹא תָמְנוּ וְלֹא כָלִינוּ בַעֲוֹנֵינוּ:\",2,0],[2,127,3,23,\"חֲדָשִׁים לַבְּקָרִים. מִתְחַדְּשִׁים הֵם חֲסָדֶיךָ מִיּוֹם אֶל יוֹם:\",1,0],[2,127,3,23,\"רַבָּה אֱמוּנָתֶךָ. גְּדוֹלָה הִיא הַבְטָחָתְךָ, וְדָבָר גָּדוֹל הוּא לְהַאֲמִין בְּךָ שֶׁתְּקַיֵּם וְתִשְׁמֹר מַה שֶּׁהִבְטַחְתָּ לָּנוּ:\",2,0],[2,127,3,24,\"חֶלְקִי ה' אָמְרָה נַפְשִׁי. ה' מְנָת חֶלְקִי, וְדִין הוּא שֶׁאוֹחִיל לוֹ:\",1,0],[2,127,3,26,\"טוֹב וְיָחִיל וְדוּמָם. וָי\\\"ו שֶׁל \\\"וְיָחִיל\\\" יְתֵרָה, כְּמוֹ וָי\\\"ו שֶׁל \\\"וְאַיָּה וַעֲנָה\\\". טוֹב שֶׁיָּחִיל אָדָם וְיִדֹּם וִיצַפֶּה לִתְשׁוּעַת ה':\",1,0],[2,127,3,28,\"יֵשֵׁב בָּדָד. מִי שֶׁאֵרַע לוֹ אֵבֶל וְצָרָה, יֵשֵׁב גַּלְמוּד וִיצַפֶּה לְטוֹבָה:\",1,0],[2,127,3,28,\"וְיִדֹּם. לְשׁוֹן הַמְתָּנָה, כְּמוֹ \\\"אִם כֹּה יֹאמְרוּ אֵלֵינוּ דֹּמוּ\\\" דִיהוֹנָתָן.\",2,0],[2,127,3,28,\"כִּי נָטַל עָלָיו. כִּי בַעַל הַגְּזֵרוֹת נָשָׂא עָלָיו הַגְּזֵרָה זוּ:\",3,0],[2,127,3,31,\"כִּי לֹא יִזְנַח לְעוֹלָם אֲדֹנָי. לָכֵן טוֹב לִדֹּם:\",1,0],[2,127,3,32,\"כִּי אִם הוֹגָה. אִם הָאָדָם מֵבִיא עָלָיו יָגוֹן בִּשְׁבִיל עֲוֹנוֹ, וְאַחַר כַּךְ, וְרִחַם כְּרֹב חֲסָדָיו.\",1,0],[2,127,3,32,\"הוֹגָה וַיַּגֶּה. לְשׁוֹן תּוּגָה הֵם:\",2,0],[2,127,3,33,\"כִּי לֹא עִנָּה מִלִּבּוֹ. וַיַּגֶּה בְּנֵי אִישׁ. מִלִּבּוֹ וּמֵרְצוֹנוֹ, כִּי הֶעָוֹן גּוֹרֵם:\",1,0],[2,127,3,34,\"לְדַכֵּא תַּחַת רַגְלָיו. מוּסָב עַל \\\"כִּי לֹא עִנָּה מִלִּבּוֹ\\\" לִהְיוֹת מְדַכֵּא תַּחַת רַגְלָיו וְגוֹ'. וְלֹא לְהַטּוֹת מִשְׁפַּט גָּבֶר וְגוֹ'. וְלֹא לְעַוֵּת אָדָם בְּרִיבוֹ, כָּל אֵלֶה ה' לֹא רָאָה. לֹא נִרְאָה לוֹ, וְלֹא עָלְתָה לְפָנָיו בְּמַחֲשַׁבְתּוֹ לַעֲשׂוֹת כֵּן:\",1,0],[2,127,3,36,\"לֹא רָאָה. לֹא הֻכְשַׁר בְּעֵינָיו שֶׁיְּעַוְּתוּ בֵית דִּין שֶׁל מַעְלָה אָדָם בְּרִיבוֹ, כְּמוֹ \\\"מָה רָאִיתָ כִּי עָשִׂיתָ וְגוֹ'\\\":\",1,0],[2,127,3,37,\"מִי זֶה אָמַר וַתֶּהִי, וְגוֹ':\",1,0],[2,127,3,38,\"מִפִּי עֶלְיוֹן וְגוֹ'. וְאִם בָּאתִי לוֹמַר: \\\"לֹא מִיָּדוֹ בָאָה אֵלַי הָרָעָה הַזֹּאת, מִקְרֶה הִיא שֶׁהָיָה לִי\\\", אֵין זֹאת, כִּי אִם בֵּין רָעוֹת וּבֵין טוֹבוֹת, מִי זֹאת אָמַר וַתֶּהִי, אִם ה' לֹא צִוָּה, וּמִפִּיו לֹא תֵצֵא הֵן רָעָה הֵן טוֹבָה, אֲבָל מַה יֵּשׁ לְהִתְאוֹנֵן אָדָם חָי? \\\"גֶּבֶר עַל חֲטָאָיו\\\". כָּל אִישׁ וְאִישׁ יִתְאוֹנֵן עַל חֲטָאָיו, כִּי הֵם הַמְּבִיאִים עָלָיו הָרָעָה. (\\\"מִפִּי עֶלְיוֹן לֹא תֵצֵא\\\". אָמַר רַבִּי יוֹחָנָן: מִיּוֹם שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא \\\"רְאֵה נָתַתִּי לְפָנֶיךָ הַיּוֹם אֶת הַחַיִּים וְאֶת הַטּוֹב וְגוֹ'\\\", לֹא יָצָא רָעָה וְטוֹבָה מִפִּיו, אֶלָּא הָרָעָה בָאָה מֵאֵלֶיהָ לְעוֹשֶׂה רַע וְהַטּוֹב לְעוֹשֶׂה טוֹב.) לְפִיכָךְ, \\\"מַה יִּתְאוֹנֵן\\\"? לָמָּה יִתְרַעֵם הָאָדָם אִם לֹא עַל חֲטָאָיו:\",1,0],[2,127,3,41,\"נִשָּׂא לְבָבֵנוּ אֶל כַּפָּיִם. כְּשֶׁאָנוּ נוֹשְׂאִים אֶת כַּפֵּינוּ אֶל הַשָּׁמַיִם, נִשָּׂא אַף לְבָבֵנוּ עִמָּהֶם לָשׁוּב, לְהָשִׁיב לְבָבֵנוּ לִפְנֵי הַמָּקוֹם בָּרוּךְ הוּא. דָּבָר אַחֵר: \\\"אֶל כַּפָּיִם\\\" אֶל הָעֲנָנִים, אֶל שָׁמַיִם, כְּמָה דְאַתְּ אָמַר \\\"וְהִנֵּה עָב קְטַנָּה כְּכַף אִישׁ עֹלָה\\\", וְכֵן \\\"עַל כַּפַּיִם כִּסָּה אוֹר\\\". וּמִדְרַשׁ רַבּוֹתֵינוּ: נִשָּׂא לְבָבֵנוּ בֶאֱמֶת לְהַקָּדוֹשׁ בָּרוּךְ הוּא כָּאָדָם הָרוֹחֵץ בְּנִקָּיוֹן כַּפָּיו, שֶׁמַּשְׁלִיךְ מִיָּדָיו כָּל טִנּוּף, כִּי מוֹדֶה וְעוֹזֵב יְרֻחָם, וְהַמּוֹדֶה וְאֵינוֹ עוֹזֵב, כְּטוֹבֵל וְשֶׁרֶץ בְּיָדוֹ:\",1,0],[2,127,3,42,\"נַחְנוּ פָשַׁעְנוּ וּמָרִינוּ. זֶה דַרְכֵּנוּ עַל יְדֵי יֵצֶר הָרָע:\",1,0],[2,127,3,42,\"אַתָּה לֹא סָלָחְתָּ. וּלְךָ הָיָה נָאֶה הַסְּלִיחָה, כִּי כֵן דַּרְכֶּךָ:\",2,0],[2,127,3,43,\"סַכּוֹתָה בָאַף. חָצַצְתָּ אֶת הָאַף לִהְיוֹת מְחִיצָה בֵינְךָ וּבֵינֵינוּ, וַתִּרְדְּפֵנוּ בוֹ:\",1,0],[2,127,3,45,\"סְחִי וּמָאוֹס. הוּא נִיעַ בִּלְשׁוֹן מִשְׁנָה: \\\"כִּיחוֹ וְנִיעוֹ\\\", שֶׁנִּסָּח מִתּוֹךְ הָרֵיאָה וְיוֹצֵא דֶרֶךְ הַגָּרוֹן:\",1,0],[2,127,3,45,\"תְּשִׂימֵנוּ. לְשׁוֹן הֹוֶה הוּא:\",2,0],[2,127,3,47,\"פַּחַד וָפַחַת. כְּשֶׁנַּסְנוּ מִפְּנֵי הַפַּחַד, נָפַלְנוּ אֶל הַפַּחַת, שׁוּחָה:\",1,0],[2,127,3,47,\"הַשֵּׁאת. לְשׁוֹן שְׁאִיָּה, כְּמוֹ הַשֵּׁאת:\",2,0],[2,127,3,49,\"מֵאֵין הֲפֻגוֹת. מֵאֵין חֲלִיפִין וְהַעֲבָרָה:\",1,0],[2,127,3,51,\"עֵינִי עוֹלְלָה לְנַפְשִׁי מִכֹּל בְּנוֹת עִירִי. יִרְמְיָה מִמִּשְׁפַּחַת כֹּהֲנִים הָיָה, וְאָמַר: \\\"עֵינִי\\\" בְּדִמְעָה \\\"עוֹלְלָה\\\" וְנִוְּלָה פָנַי עֲלֵי נַפְשִׁי \\\"מִכֹּל בְּנוֹת עִירִי\\\".\",1,0],[2,127,3,51,\"עוֹלְלָה. לְשׁוֹן נִוּוּל, כְּמוֹ \\\"וְעֹלַלְתִּי בֶעָפָר קַרְנִי\\\":\",2,0],[2,127,3,51,\"מִכֹּל בְּנוֹת עִירִי. מִשְׁפַּחְתִּי יֵשׁ לָהּ לִבְכּוֹת מִכֹּל מִשְׁפְּחוֹת הָעִיר, שֶׁהָיְתָה נִבְחֶרֶת לִקְדֻשָּׁה וְלַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל יִשְׂרָאֵל:\",3,0],[2,127,3,53,\"צָמְתוּ בַבּוֹר חַיָּי. בְּבֵית הַכֶּלֶא.\",1,0],[2,127,3,53,\"צָמְתוּ. אָסְרוּ, כְּמוֹ: \\\"צוֹמֶת הַגִּידִין\\\" \\\"מִבַּעַד לְצַמָּתֵךְ\\\" אירייסו\\\"ר:\",2,0],[2,127,3,53,\"וַיַּדּוּ אֶבֶן בִּי. עַל פִּי הַבְּאֵר. כַּךְ עָשׂוּ לְדָנִיֵּאל, וְיִרְמְיָה רָאָה בְרוּחַ הַקֹּדֶשׁ:\",3,0],[2,127,3,53,\"צָמְתוּ בַבּוֹר חַיָּי. וְאַף עַל פִּי שֶׁצָּמְתוּ בַבּוֹר חַיָּי, שֶׁאֵינִי יָכוֹל לַעֲלוֹת מִתּוֹכוֹ, לֹא שָׁתוּ לִבָּם גַּם לָזֹאת עַד שֶׁיַּדוּ אֶבֶן בִּי:\",4,0],[2,127,3,54,\"צָפוּ מַיִם וְגוֹ'. שֶׁבִּזְמַן שֶׁבָּא אָדָם בְּמַיִם עַד מָתְנָיו, עֲדַיִן יֵשׁ תִּקְוָה, אֲבָל אִם צָפוּ הַמַּיִם עַל רֹאשׁוֹ, אָז אוֹמֵר \\\"אָבְדָה תִקְוָתִי\\\". אֲבָל אֲנִי אֵינִי עוֹשֶׂה כֵן, אֶלָּא \\\"קָרָאתִי וְגוֹ'\\\":\",1,0],[2,127,3,54,\"צָפוּ מַיִם. עַכּוּ\\\"ם:\",2,0],[2,127,3,57,\"קָרַבְתָּ בְּיוֹם אֶקְרָאֶךָ. כַּךְ הָיִיתָ רָגִיל בַּיָּמִים הָרִאשׁוֹנִים, לִקְרַב אֵלַי בְּיוֹם קָרְאִי:\",1,0],[2,127,3,58,\"רַבְתָּ ה' רִיבֵי נַפְשִׁי. בַּיָּמִים שֶׁעָבְרוּ:\",1,0],[2,127,3,59,\"רָאִיתָה ה' עַוָּתָתִי. בַּצָּרָה הַזֹּאת שֶׁעִוְּתוּ בִי אוֹיְבַי:\",1,0],[2,127,3,59,\"שָׁפְטָה מִשְׁפָּטִי. כַּאֲשֶׁר עָשִׂיתָ כְבָר:\",2,0],[2,127,3,65,\"מְגִנַּת לֵב. שֶׁבֶר לֵב, כְּמָה דְאַתְּ אָמַר \\\"אֲמַגֶּנְךָ יִשְׂרָאֵל\\\", אֲשֶׁר מִגֵּן צָרֶיךָ בְּיָדֶךָ. דָּבָר אַחֵר: \\\"מְגִנַּת לֵב\\\". אוֹטֶם הַלֵּב, צָרָה וַאֲנָחָה, אֲשֶׁר הִיא כְמָגֵן כְּנֶגֶד לִבָּם. וְהַמְפָרְשׁוֹ בִלְשׁוֹן תּוּגָה וְיָגוֹן טוֹעֶה, שֶׁאֵין נוּ\\\"ן נוֹפֶלֶת בּוֹ, שֶׁהַנּוּ\\\"ן בְּיָגוֹן אֵינָהּ שֹׁרֶשׁ אֶלָּא כְגוֹן נוּ\\\"ן שֶׁל \\\"הָמוֹן\\\" מִגִּזְרַת \\\"הָמוּ גוֹיִם\\\" וּכְגוֹן נוּ\\\"ן שֶׁל \\\"קָלוֹן\\\" מִגִּזְרַת \\\"נִקְלֶה\\\", וּכְנוּ\\\"ן שֶׁל \\\"צִיּוֹן\\\" מִגִּזְרַת \\\"צִיָּה\\\", וְכֵן נוּ\\\"ן שֶׁל \\\"שִׁבְרוֹן\\\" מִגִּזְרַת \\\"שֶׁבֶר\\\", (וּכְגוֹן נוּ\\\"ן שֶׁל \\\"שִׁמָּמוֹן\\\", \\\"שִׁגָּעוֹן\\\" נִרְאֶה לִי שֶׁכֵּן צָרִיךְ לִקְרוֹא וְקַל לְהָבִין):\",1,0],[2,127,3,65,\"תַּאֲלָתְךָ. לְשׁוֹן \\\"נוֹאֲלוּ שָׂרֵי צֹעַן\\\":\",2,0],[2,127,4,1,\"אֵיכָה יוּעַם זָהָב. קִינָה זוּ נֶאֶמְרָה עַל יֹאשִׁיָּהוּ, כְּמוֹ שֶׁנֶּאֱמַר בְּדִבְרֵי הַיָּמִים \\\"וְהִנָּם כְּתוּבִים עַל הַקִּינוֹת\\\". וְעִמָּהּ חִבֵּר בְּתוֹךְ הַקִּינָה אֶת שְׁאָר בְּנֵי צִיּוֹן:\",1,0],[2,127,4,1,\"יוּעַם. יִכְהֶה, כְּמוֹ דְאַתְּ מְתַּרְגֵּם \\\"כֵּהָה\\\" עַמְיָא.\",2,0],[2,127,4,1,\"זָהָב. מַרְאִית פָּנִים הַמַּצְהִיב כְּזָהָב:\",3,0],[2,127,4,1,\"יִשְׁנֶא. יִשְׁתַּנֶּה מִמַּרְאִיתוֹ:\",4,0],[2,127,4,1,\"הַכֶּתֶם. קְבוּצַת כְּלֵי נוֹי הַזָּהָב שֶׁהֵם לַעֲדִי, קָרוּי כֶּתֶם:\",5,0],[2,127,4,1,\"אַבְנֵי קֹדֶשׁ. בָּנִים הַמְאִירִים כַּאֲבָנִים טוֹבוֹת וּמִדְרַשׁ אַגָּדָה: כָּל רְבִיעִית דָּם שֶׁיָּצָא מִיֹּאשִׁיָּהוּ בְּכָל חֵץ וְחֵץ שֶׁנָּעֲצוּ בוֹ הָיָה יִרְמְיָה קוֹבְרָהּ בִּמְקוֹמָהּ, וְעָלֶיהָ הוּא קוֹרֵא: \\\"תִּשְׁתַּפֵּכְנָה אַבְנֵי קֹדֶשׁ\\\":\",6,0],[2,127,4,2,\"הַמְסֻלָּאִים בַּפָּז. הַמְהֻלָּלִים וְהַנֶּעֱרָכִים כְּפָז. הָרוֹאֶה אוֹתָם אוֹמֵר: \\\"רְאוּ תָאֳרָם שֶׁל אֵלּוּ כְּמַרְאִית פָּז\\\". וְכֵן \\\"לֹא תְסֻלֶּה בְּכֶתֶם אוֹפִיר\\\", \\\"בְּכֶתֶם טָהוֹר לֹא תְסֻלֶּה\\\" \\\"סֹלּוּ לָרֹכֵב בָּעֲרָבוֹת\\\", לְשׁוֹן הִלּוּל וְעֵרֶךְ הֵן:\",1,0],[2,127,4,2,\"לְנִבְלֵי חֶרֶשׂ. כַּדֵּי חֶרֶשׂ שֶׁנּוֹתְנִים בָּהֶם יַיִן, כְּגוֹן נִבְלֵי יַיִן \\\"וְנִבְלֵיהֶם יְנַפֵּצוּ\\\":\",2,0],[2,127,4,3,\"גַּם תַּנִּין. אַף עַל פִּי שֶׁאַכְזָרִי הוּא, חָלְצוּ שַׁד. כְּשֶׁרוֹאֶה אֶת בְּנוֹ בָּא מֵרָחוֹק רָעֵב, חוֹלֵץ שָׁדָיו מִתּוֹךְ נַרְתִּיקוֹ, שֶׁיֵשׁ לוֹ כִסּוּי עַל דַּדָּיו וּמוֹצִיאוֹ מִתּוֹכוֹ, כְּדֵי שֶׁלֹּא יִרְאֵהוּ בְנוֹ מְכֻסֶּה וַיַחֲזוֹר לַאֲחוֹרָיו, וְהֵינִיקוּ גּוּרֵיהֶן:\",1,0],[2,127,4,3,\"בַּת עַמִּי לְאַכְזָר. רוֹאִים אֶת בְּנֵיהֶם צוֹעֲקִים לְלֶחֶם, וְאֵין פּוֹרֵשׂ לָהֶם, שֶׁחַיֵּיהֶם קוֹדְמִים לָהֶם לְחַיֵּי בְנֵיהֶם מֵחֲמַת הָרָעָב:\",2,0],[2,127,4,5,\"הָאֱמֻנִים עֲלֵי תוֹלָע. עַל בִּגְדֵי צִבְעוֹנִין:\",1,0],[2,127,4,5,\"הָאֱמֻנִים. לְשׁוֹן \\\"וַיְהִי אֹמֵן אֶת הֲדַסָּה\\\":\",2,0],[2,127,4,5,\"אַשְׁפַּתּוֹת. אַשְׁפּוֹת שֶׁל זֶבֶל. שׁוֹכְבִים עַל הָאַשְׁפּוֹת בַּחוּץ:\",3,0],[2,127,4,6,\"וַיִּגְדַּל עֲוֹן וְגוֹ'. פֻּרְעֲנוּתָם מוֹכִיחַ עֲלֵיהֶם שֶׁגָּדוֹל עֲוֹנָם מִשֶּׁל סְדוֹם:\",1,0],[2,127,4,6,\"הַהֲפוּכָה כְמוֹ רָגַע. שֶׁהֲרֵי סְדוֹם לֹא נִמְשְׁכָה צָרָתָם. כְּרֶגַע אֶחָד נֶהֶפְכָה:\",2,0],[2,127,4,6,\"וְלֹא חָלוּ בָהּ יָדָיִם. יְדֵי הָאוֹיֵב, כִּי עַל יְדֵי הַמַּלְאָכִים נֶהֶפְכָה. וְיֵשׁ מִדְרְשֵׁי אַגָּדָה, וְאֵינוֹ מְיֻשָּׁב עַל סֵדֶר הַמִּקְרָאוֹת:\",3,0],[2,127,4,7,\"זַכּוּ נְזִירֶיהָ. שָׂרֶיהָ, כְּמוֹ נֵזֶר וְכֶתֶר. וַאֲנִי אוֹמֵר, נְזִירֶיהָ מַמָּשׁ, שֶׁהָיוּ מְגֻדְּלֵי שֵׂעָר וְנָאִים בְּיוֹתֵר, וּמוּסָב עַל \\\"בַּת עַמִּי\\\":\",1,0],[2,127,4,7,\"אָדְמוּ עֶצֶם מִפְּנִינִים. אוֹתָם שֶׁהָיוּ מַרְאֵיהֶם אָדוֹם מִפְּנִינִים וְגִזְרָתָם כְּמוֹ סַפִּיר, חָשַׁךְ תָּאֳרָם מִפֶּחָמִים:\",2,0],[2,127,4,8,\"מִשְּׁחוֹר. הוּא פֶחָם:\",1,0],[2,127,4,8,\"עֶצֶם. לְשׁוֹן מַרְאֶה, כְּמוֹ \\\"וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר\\\", קול\\\"ר בְּלַעַ\\\"ז:\",2,0],[2,127,4,8,\"צָפַד. נִקְמַט וְנִתְחַבֵּר, וְאֵין לוֹ דִמְיוֹן:\",3,0],[2,127,4,9,\"שֶׁהֵם יָזֻבוּ מְדֻקָּרִים וְגוֹ'. חַלְלֵי הָרָעָב הָיוּ נְפוּחִים מֵרֵיחַ תְּנוּבוֹת הַשָּׂדֶה, שֶׁהָיוּ הָאוֹיְבִים צוֹלִים בָּשָּׂר עַל הָעֲשָׂבִים חוּץ לַחוֹמָה, וְהָרֵיחַ נִכְנָס בְּתוֹךְ נְפוּחֵי הָרָעָב וּכְרֵסָן נִבְקַעַת, וּפִרְשָׁם זָב, וַהֲרֵי זֶה מִיתַת נִוּוּל יוֹתֵר מֵהֲרוּגֵי חָרֶב:\",1,0],[2,127,4,9,\"מְדֻקָּרִים. מְבֻקָּעִים. בֵּין נְפִיחַת רָעָב בֵּין בִּקּוּעַ חֶרֶב קָרוּי דְּקִירָה:\",2,0],[2,127,4,9,\"מִתְּנוּבֹת שָׂדָי. מִשָׁרָשִׁים וַעֲשָׂבִים שֶׁמְּלַקְּטִים וְאוֹכְלִים, רַב פִּרְשָׁם וּמִאוּסָם:\",3,0],[2,127,4,10,\"לְבָרוֹת. לְמַאֲכָל, כְּמוֹ \\\"וְלֹא בָרָה אִתָּם לָחֶם\\\", \\\"לְהַבְרוֹת אֶת דָּוִד\\\":\",1,0],[2,127,4,11,\"כִּלָּה ה' אֶת חֲמָתוֹ. אֲשֶׁר בָּעֲרָה בוֹ כַּמָּה שָׁנִים, עַתָּה כִלָּה אוֹתָהּ בְּהִנָּקְמוֹ מֵהֶם:\",1,0],[2,127,4,13,\"מֵחַטֹּאת נְבִיאֶיהָ. שֶׁל שֶׁקֶר, הָיְתָה לָהּ הָרָעָה הַזֹּאת:\",1,0],[2,127,4,14,\"נָעוּ עִוְרִים בַּחוּצוֹת. כְּשֶׁהָיוּ הָעִוְרִים הוֹלְכִים בַּשּׁוּק, הָיוּ נָעִים, וְרַגְלֵיהֶם נִשְׁמָטִים בְּדַם הַהֲרוּגִים שֶׁהָיוּ הָרְשָׁעִים הוֹרְגִים בְּתוֹכָהּ:\",1,0],[2,127,4,14,\"נְגֹאֲלוּ בַּדָּם. נִתְלַכְלְכוּ בַּדָּם, עַד אֲשֶׁר לֹא יָכְלוּ הַקְּרוֹבִים אֲלֵיהֶם לִגַּע בִּלְבוּשֵׁיהֶם, וְהָיוּ קוֹרְאִים אֲלֵיהֶם:\",2,0],[2,127,4,15,\"סוּרוּ. מֵעָלֵינוּ, אַתֶּם הַטְּמֵאִים הַמְלֻכְלָכִים בַּדָּם:\",1,0],[2,127,4,15,\"כִּי נָצוּ. לְשׁוֹן סִרְחוֹן וְלִכְלוּךְ, כְּמוֹ \\\"מֻרְאָתוֹ בְּנֹצָתָהּ\\\", דִּמְתַרְגְּמִינָן \\\"בְּאוּכְלֵיהּ\\\". כַּךְ חִבְּרוֹ מְנַחֵם:\",2,0],[2,127,4,15,\"גַּם נָעוּ. נִשְׁמְטוּ בַדָּם:\",3,0],[2,127,4,16,\"פְּנֵי ה' חִלְּקָם. פָּנִים שֶׁל זַעַם מֵאֵת הַקָּדוֹשׁ בָּרוּךְ הוּא חִלְּקָם וְהִפְרִידָם בָּעַכּוּ\\\"ם לְמַעַן אֲשֶׁר פְּנֵי הַכֹּהֲנִים לֹא נָשָׂאוּ, בִּהְיוֹתָם בְּשַׁלְוָתָם:\",1,0],[2,127,4,17,\"עוֹדֵינוּ תִּכְלֶינָה עֵינֵינוּ אֶל עֶזְרָתֵנוּ הָבֶל. כְּשֶׁבָּאָה עָלֵינוּ הָרָעָה, עֲדַיִן הָיוּ עֵינֵינוּ צוֹפוֹת אֶל חֵיל פַּרְעֹה, שֶׁנֶּאֱמַר בָּהֶם \\\"וּמִצְרַיִם הֶבֶל וָרִיֹק יַעְזֹרוּ\\\", שֶׁהָיוּ מַבְטִיחִים אוֹתָנוּ לְעֶזְרָה וְלֹא בָאוּ, כְּמוֹ שֶׁנֶּאֱמַר בָּהֶם \\\"הִנֵּה חֵיל פַּרְעֹה הַיֹּצֵא לָכֶם לְעֶזְרָה שָׁב לְאַרְצוֹ מִצְרָיִם\\\". מָצִינוּ בְמִדְרַשׁ קִינוֹת שֶׁהָיוּ בָאִים בִּסְפִינוֹת. רָמַז הַקָּדוֹשׁ בָּרוּךְ הוּא לַיָּם וְהֵצִיף לִפְנֵיהֶם נוֹדוֹת נְפוּחִים כְּמִין מֵעֵי אָדָם נִנְעָרִים בַּמָּיִם. אָמְרוּ זֶה לָזֶה, \\\"הַנּוֹדוֹת הַלָּלוּ הֵם אֲבוֹתֵינוּ אַנְשֵׁי מִצְרַיִם שֶׁטֻּבְּעוּ בַיָּם מֵחֲמַת הַיְּהוּדִים הַלָּלוּ, וַאֲנַחְנוּ יוֹצְאִים לְעֶזְרָתָם?\\\" עָמְדוּ וְחָזְרוּ לַאֲחוֹרֵיהֶם:\",1,0],[2,127,4,17,\"צִפִּינוּ. חִכִּינוּ:\",2,0],[2,127,4,18,\"צָדוּ צְעָדֵינוּ. אוֹיְבֵינוּ אָרְבוּ אֶת צְעָדֵינוּ מִלֶּכֶת בִּרְחוֹבוֹתֵינוּ, כְּמוֹ \\\"וַאֲשֶׁר לֹא צָדָה\\\", \\\"וְאַתָּה צֹדֶה אֶת נַפְשִׁי\\\":\",1,0],[2,127,4,20,\"מְשִׁיחַ ה'. הוּא יֹאשִׁיָּהוּ, כְּמוֹ שֶׁנֶּאֱמַר בְּדִבְרֵי הַיָּמִים \\\"וַיְקוֹנֵן יִרְמְיָהוּ עַל יֹאשִׁיָּהוּ\\\":\",1,0],[2,127,4,20,\"בִּשְׁחִיתוֹתָם. בַּגּוּמוֹת שֶׁחָפְרוּ:\",2,0],[2,127,4,21,\"שִׂישִׂי וְשִׂמְחִי בַּת אֱדוֹם. נִתְנַבֵּא יִרְמְיָהוּ עַל חֻרְבַּן בַּיִת שֵׁנִי, שֶׁיַּחֲרִיבוּהוּ רוֹמִיִּים:\",1,0],[2,127,4,21,\"שִׂישִׂי וְשִׂמְחִי. לְפִי שָׁעָה, אֲבָל סוֹפֵךְ שֶׁגַּם עָלַיִךְ תַּעֲבָר כּוֹס הַפֻּרְעָנוּת וְתִשְׁכְּרִי מִמֶּנּוּ:\",2,0],[2,127,4,21,\"וְתִתְעָרִי. וְתָקִיאִי, כְּמוֹ \\\"וַתְּעַר כַּדָּהּ\\\":\",3,0],[2,127,4,22,\"תַּם עֲו‍ֹנֵךְ בַּת צִיּוֹן. לָקִית עַל כָּל חַטֹּאתָיִךְ:\",1,0],[2,127,4,22,\"לֹא יוֹסִיף לְהַגְלוֹתֵךְ. מִגָּלוּת אֱדוֹם וּלְהַלָּן עוֹד:\",2,0],[2,127,5,4,\"מֵימֵינוּ בְּכֶסֶף שָׁתִינוּ. שֶׁהָיִינוּ יְרֵאִים לִשְׁאוֹב מַיִם מִן הַנָּהָר מִפְּנֵי הָאוֹיְבִים, וְהָיִינוּ קוֹנִים מֵהֶם בְּכֶסֶף:\",1,0],[2,127,5,5,\"עַל צַוָּארֵנוּ נִרְדָּפְנוּ. מֵעוֹל עֲבוֹדָה קָשָׁה:\",1,0],[2,127,5,5,\"יָגַעְנוּ. לֶאֱסוֹף מָמוֹן וּנְכָסִים:\",2,0],[2,127,5,5,\"וְלֹא הוּנַח לָנוּ. יְגִיעֵנוּ בְּיָדֵינוּ, כִּי הָאוֹיְבִים הָיוּ גוֹבִים וְחוֹטְפִים הַכֹּל בְּמִסִּים וְגֻלְגָּלִיּוֹת וְאַרְנוּנִיּוֹת:\",3,0],[2,127,5,6,\"מִצְרַיִם נָתַנּוּ יָד. דֶּרֶךְ אָדָם הַנּוֹפֵל וְרוֹצֶה לַעֲמוֹד, מוֹשִׁיט יָד לְמִי שֶׁאֶצְלוֹ לַעֲזוֹר לוֹ, וְאַף כַּאן, לְמִצְרַיִם הוֹשַׁטְנוּ יָד שֶׁיַּעְזְרוּנוּ:\",1,0],[2,127,5,6,\"אַשּׁוּר. שֶׁיַּשְׂבְּעוּנוּ בְלַחְמָם:\",2,0],[2,127,5,6,\"נָתַנּוּ. כְּמוֹ \\\"נָתַנְנוּ\\\". דַּגְשׁוּת הַנּוּ\\\"ן מְשַׁמֶּשֶׁת בִּמְקוֹם נוּ\\\"ן שְׁנִיָּה, וְכֵן, \\\"כִּי מִמְּךָ הַכֹּל וּמִיָּדְךָ נָתַנּוּ לָךְ\\\". וְכֵן, \\\"וְנָתַנּוּ אֶת בְּנֹתֵינוּ לָכֶם\\\":\",3,0],[2,127,5,9,\"בְּנַפְשֵׁנוּ נָבִיא לַחְמֵנוּ. בְּסַכָּנַת נַפְשֵׁנוּ. הָיִינוּ מְסֻּכָּנִים, כְּשֶׁהָיִינוּ מְבִיאִים מְזוֹנוֹתֵינוּ מִן הַשָּׂדֶה, מִפְּנֵי חֶרֶב הַמִּדְבָּר:\",1,0],[2,127,5,10,\"נִכְמָרוּ. נִתְחַמְּמוּ, וְכֵן, \\\"כִּי נִכְמְרוּ רַחֲמָיו\\\". וּבִלְשׁוֹן גְּמָרָא יֵשׁ הַרְבֵּה: \\\"עַל הַכּוֹמֶר שֶׁל עֲנָבִים\\\". \\\"מִכְמָר בְּישְׂרָאֵל\\\":\",1,0],[2,127,5,10,\"זַלְעֲפוֹת רָעָב. כְּמוֹ \\\"וְרוּחַ זִלְעָפוֹת\\\", לְשׁוֹן שְׂרֵפָה:\",2,0],[2,127,5,13,\"טְחוֹן נָשָׂאוּ. כְּשֶׁהָיוּ הָאוֹיְבִים מוֹלִיכִין אוֹתָם בְּקוֹלָרִין, הָיוּ נוֹתְנִים עַל כְּתֵפֵיהֶם רֵחַיִם וּמַשָׂאוֹת כְּדֵי לְיַגְּעָם. וְכֵן, \\\"בָּעֵץ כָּשָׁלוּ\\\", כָּשַׁל כֹּחָם. וּלְשׁוֹן כִּשְׁלוֹן נוֹפֵל בְּתַשּׁוּת כֹּחַ, כְּמוֹ שֶׁנֶּאֱמַר בְּעֶזְרָא \\\"וַיֹּאמֶר יְהוּדָה כָּשַׁל כֹּחַ הַסַּבָּל\\\". וְכֵן \\\"הִכְשִׁיל כֹּחִי\\\":\",1,0],[2,127,5,17,\"עַל זֶה הָיָה דָוֶה לִבֵּנוּ וְגוֹ'. עַל הַמְפֹרָשׁ בַּמִּקְרָא שֶׁל אַחֲרָיו: \\\"עַל הַר צִיּוֹן שֶׁשָּׁמֵם\\\". וְ\\\"שׁוּעָלִים הִלְּכוּ בוֹ\\\":\",1,0],[2,127,5,19,\"אַתָּה ה'. יָדַעְנוּ כִּי לְעוֹלָם תֵּשֵׁב וְהוֹאִיל וְכֵן הוּא:\",1,0],[2,127,5,20,\"לָמָּה לָנֶצַח תִּשְׁכָּחֵנוּ. הֲלֹא נִשְׁבַּעְתָּ לָנוּ בְּךָ כְּשֵׁם שֶׁאַתָּה קַיָּם כַּךְ שְׁבוּעָתְךָ קַיֶּמֶת:\",1,0],[2,127,5,22,\"כִּי אִם מָאֹס מְאַסְתָּנוּ. בִּשְׁבִיל שֶׁחָטָאנוּ לֹא הָיָה לְךָ לְהַרְבּוֹת קֶצֶף עַד מְאֹד כַּאֲשֶׁר קָצַפְתָּ:\",1,0],[2,127,5,22,\"הֲשִׁיבֵנוּ ה'. מִפְּנֵי שֶׁמְּסַיֵּם בְּדִבְרֵי תוֹכֵחָה הֻצְרַךְ לִכְפֹּל מִקְרָא שֶׁלְּפָנָיו פַּעַם אַחֶרֶת, וְכֵן יְשַׁעְיָה וּתְרֵי עָשָׂר וְקֹהֶלֶת:\",2,0],[2,128,1,1,\"ויקרא אל משה. לְכָל דִּבְּרוֹת וּלְכָל אֲמִירוֹת וּלְכָל צִוּוּיִים קָדְמָה קְרִיאָה, לְשׁוֹן חִבָּה, לָשׁוֹן שֶׁמַּלְאֲכֵי הַשָּׁרֵת מִשְׁתַּמְּשִׁין בּוֹ, שֶׁנֶּאֱמַר וְקָרָא זֶה אֶל זֶה (ישעיהו ו'), אֲבָל לִנְבִיאֵי אֻמּוֹת הָעוֹלָם נִגְלָה עֲלֵיהֶן בִּלְשׁוֹן עֲרָאִי וְטֻמְאָה, שֶׁנֶּאֱמַר וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם (במדבר כ\\\"ג):\",1,0],[2,128,1,1,\"ויקרא אל משה. הַקּוֹל הוֹלֵךְ וּמַגִּיעַ לְאָזְנָיו וְכָל יִשְֹרָאֵל לֹא שׁוֹמְעִין; יָכוֹל אַף לְהַפְסָקוֹת הָיְתָה קְרִיאָה, תַּ\\\"ל וַיְדַבֵּר — לְדִבּוּר הָיְתָה קְרִיאָה וְלֹא לְהַפְסָקוֹת, וּמֶה הָיוּ הַפְסָקוֹת מְשַׁמְּשׁוֹת? לִתֵּן רֶוַח לְמֹשֶׁה לְהִתְבּוֹנֵן בֵּין פָּרָשָׁה לְפָרָשָׁה וּבֵין עִנְיָן לְעִנְיָן; קַ\\\"וָ לְהֶדְיוֹט הַלּוֹמֵד מִן הַהֶדְיוֹט:\",2,0],[2,128,1,1,\"אליו. לְמַעֵט אֶת אַהֲרֹן; רַ' יְהוּדָה אוֹמֵר י\\\"ג דִּבְּרוֹת נֶאֶמְרוּ בַּתּוֹרָה לְמֹשֶׁה וּלְאַהֲרֹן וּכְנֶגְדָּן נֶאֶמְרוּ י\\\"ג מִעוּטִין, לְלַמֶּדְךָ שֶׁלֹּא לְאַהֲרֹן נֶאֶמְרוּ אֶלָּא לְמֹשֶׁה שֶׁיֹּאמַר לְאַהֲרֹן, וְאֵלּוּ הֵן י\\\"ג מִעוּטִין: לְדַבֵּר אִתּוֹ, מִדַּבֵּר אֵלָיו, וַיְדַבֵּר אֵלָיו (במדבר ז'), וְנוֹעַדְתִּי לְךָ (שמות כ\\\"ה) — כֻּלָּן בְּתוֹרַת כֹּהֲנִים. יָכוֹל יִשְׁמְעוּ אֶת קוֹל הַדִּבּוּר תַּ\\\"לֹ קוֹל לוֹ, קוֹל אֵלָיו, מֹשֶׁה שׁוֹמֵעַ וְכָל יִשְֹרָאֵל לֹא שָׁמְעוּ:\",3,0],[2,128,1,1,\"מאהל מועד. מְלַמֵּד שֶׁהָיָה הַקּוֹל נִפְסָק וְלֹא הָיָה יוֹצֵא חוּץ לָאֹהֶל; יָכוֹל מִפְּנֵי שֶׁהַקּוֹל נָמוּךְ, תַּ\\\"ל אֶת הַקּוֹל, מַהוּ הַקּוֹל? הוּא הַקּוֹל הַמְפֹרָשׁ בִּתְהִלִּים קוֹל ה' בַּכֹּחַ קוֹל ה' בֶּהָדָר קוֹל ה' שֹׁבֵר אֲרָזִים (תהילים כ\\\"ט), אִם כֵּן לָמָּה נֶאֱמַר מֵאֹהֶל מוֹעֵד? מְלַמֵּד שֶׁהָיָה הַקּוֹל נִפְסָק. כַּיּוֹצֵא בּוֹ וְקוֹל כַּנְפֵי הַכְּרוּבִים נִשְׁמַע עַד הֶחָצֵר הַחִיצֹנָה (יחזקאל י'), יָכוֹל שֶׁהַקּוֹל נָמוּךְ תַּ\\\"ל כְּקוֹל אֵל שַׁדַּי בְּדַבְּרוֹ, אִם כֵּן לָמָּה נֶאֱמַר עַד הֶחָצֵר הַחִיצֹנָה? שֶׁכֵּוָּן שֶׁמַּגִּיעַ שָׁם הָיָה נִפְסָק:\",4,0],[2,128,1,1,\"מאהל מועד לאמר. יָכוֹל מִכָּל הַבַּיִת, תַּ\\\"ל מֵעַל הַכַּפֹּרֶת, יָכוֹל מֵעַל הַכַּפֹּרֶת כֻּלָּהּ, תַּ\\\"ל מִבֵּין שְׁנֵי הַכְּרֻבִים:\",5,0],[2,128,1,1,\"לאמר. צֵא וֶאֱמֹר לָהֶם דִּבְרֵי כִּבּוּשִׁין — בִּשְׁבִילְכֶם הוּא נִדְבָּר עִמִּי; שֶׁכֵּן מָצִינוּ שֶׁכָּל ל\\\"ח שָׁנָה שֶׁהָיוּ יִשְֹרָאֵל בַּמִּדְבָּר כִּמְנֻדִּים, מִן הַמְרַגְּלִים וָאֵילַךְ, לֹא נִתְיַחֵד הַדִּבּוּר עִם מֹשֶׁה, שֶׁנֶּאֱמַר וַיְהִי כַאֲשֶׁר תַּמּוּ כָּל אַנְשֵׁי הַמִּלְחָמָה לָמוּת … וַיְדַבֵּר ה' אֵלַי לֵאמֹר (דברים ב'), אֵלַי הָיָה הַדִּבּוּר. דָּ\\\"אַ צֵא וֶאֱמֹר לָהֶן דְּבָרַי וַהֲשִׁיבֵנִי אִם יְקַבְּלוּם, כְּמָה שֶׁנֶּאֱמַר וַיָּשֶׁב מֹשֶׁה אֶת דִּבְרֵי הָעָם וְגוֹ' (שמות י\\\"ט):\",6,0],[2,128,1,2,\"אדם כי יקריב מכם. כְּשֶׁיַּקְרִיב; בְּקָרְבְּנוֹת נְדָבָה דִּבֵּר הָעִנְיָן:\",1,0],[2,128,1,2,\"אדם. לָמָּה נֶאֱמַר? מָה אָדָם הָרִאשׁוֹן לֹא הִקְרִיב מִן הַגָּזֵל — שֶׁהַכֹּל הָיָה שֶׁלּוֹ — אַף אַתֶּם לֹא תַּקְרִיבוּ מִן הַגָּזֵל (ויקרא רבה):\",2,0],[2,128,1,2,\"הבהמה. יָכוֹל אַף חַיָּה בִּכְלָל, תַּ\\\"לֹ בָּקָר וָצֹאן:\",3,0],[2,128,1,2,\"מן הבהמה. וְלֹא כֻּלָּהּ — לְהוֹצִיא אֶת הָרוֹבֵעַ וְאֶת הַנִּרְבָּע:\",4,0],[2,128,1,2,\"מן הבקר. לְהוֹצִיא אֶת הַנֶּעֱבָד:\",5,0],[2,128,1,2,\"מן הצאן. לְהוֹצִיא אֶת הַמֻּקְצָה:\",6,0],[2,128,1,2,\"ומן הצאן. לְהוֹצִיא אֶת הַנּוֹגֵחַ שֶׁהֵמִית; כְּשֶׁהוּא אוֹמֵר לְמַטָּה מִן הָעִנְיָן מִן הַבָּקָר — שֶׁאֵין תַּ\\\"ל — לְהוֹצִיא אֶת הַטְּרֵפָה (ספרא):\",7,0],[2,128,1,2,\"תקריבו. מְלַמֵּד שֶׁשְּׁנַיִם מִתְנַדְּבִים עוֹלָה בְּשֻׁתָּפוּת:\",8,0],[2,128,1,2,\"קרבנכם. מְלַמֵּד שֶׁהִיא בָּאָה נִדְבַת צִבּוּר, הִיא עוֹלַת קַיִץ הַמִּזְבֵּחַ, הַבָּאָה מִן הַמּוֹתָרוֹת (שבועות י\\\"ב):\",9,0],[2,128,1,3,\"זכר. וְלֹא נְקֵבָה; כְּשֶׁהוּא אוֹמֵר זָכָר לְמַטָּה — שֶׁאֵין תַּ\\\"לֹ — זָכָר וְלֹא טֻמְטוּם וְאַנְדְּרוֹגִינוֹס:\",1,0],[2,128,1,3,\"תמים. בְּלֹא מוּם:\",2,0],[2,128,1,3,\"אל פתח אהל מועד. מְטַפֵּל בַּהֲבָאָתוֹ עַד הָעֲזָרָה; מַהוּ אוֹמֵר יַקְרִיב יַקְרִיב? אֲפִלּוּ נִתְעָרְבָה עוֹלַת רְאוּבֵן בְּעוֹלַת שִׁמְעוֹן יַקְרִיב כָּל אֶחָד לְשֵׁם מִי שֶׁהוּא, וְכֵן עוֹלָה בְּחֻלִּין, יִמָּכְרוּ הַחֻלִּין לְצָרְכֵי עוֹלוֹת, וַהֲרֵי הֵן כֻּלָּן עוֹלוֹת, וְתִקְרַב כָּל אֶחָד לְשֵׁם מִי שֶׁהוּא; יָכוֹל אֲפִלּוּ נִתְעָרְבָה בִּפְסוּלִין אוֹ בְּשֶׁאֵינוֹ מִינוֹ, תַּלְמוּד לוֹמַר \\\"יַקְרִיבֶנּוּ\\\" (ספרא):\",3,0],[2,128,1,3,\"יקריב אתו. מְלַמֵּד שֶׁכּוֹפִין אוֹתוֹ, יָכוֹל בְּעַל כָּרְחוֹ, תַּלְמוּד לוֹמַר \\\"לִרְצוֹנוֹ\\\", הָא כֵּיצַד? כּוֹפִין אוֹתוֹ עַד שֶׁיֹּאמַר רוֹצֶה אֲנִי (שם):\",4,0],[2,128,1,3,\"לפני ה' וסמך. אֵין סְמִיכָה בְּבָמָה (שם):\",5,0],[2,128,1,4,\"על ראש העלה. לְהָבִיא עוֹלַת חוֹבָה לִסְמִיכָה וּלְהָבִיא עוֹלַת הַצֹּאן (שם):\",1,0],[2,128,1,4,\"העלה. פְּרָט לְעוֹלַת הָעוֹף (שם):\",2,0],[2,128,1,4,\"ונרצה לו. עַל מָה הוּא מְרַצֶּה לוֹ? אִם תֹּאמַר עַל כָּרֵתוֹת וּמִיתוֹת בֵּית דִּין אוֹ מִיתָה בִּידֵי שָׁמַיִם אוֹ מַלְקוּת, הֲרֵי עָנְשָׁן אָמוּר, הָא אֵינוֹ מְרַצֶּה אֶלָּא עַל עֲשֵֹה וְעַל לָאו שֶׁנִּתַּק לַעֲשֵֹה (שם):\",3,0],[2,128,1,5,\"ושחט והקריבו, הכהנים. מִקַּבָּלָה וָאֵילַךְ מִצְוַת כְּהֻנָּה — לִמֵּד עַל הַשְּׁחִיטָה שֶׁכְּשֵׁרָה בְּזָר (שם):\",1,0],[2,128,1,5,\"לפני ה'. בַּעֲזָרָה:\",2,0],[2,128,1,5,\"והקריבו. זוֹ קַבָּלָה, שֶׁהִיא הָרִאשׁוֹנָה, וּמַשְׁמָעָהּ לְשׁוֹן הוֹלָכָה, לָמַדְנוּ שְׁתֵּיהֶן:\",3,0],[2,128,1,5,\"בני אהרן. יָכוֹל חֲלָלִים, תַּ\\\"ל הַכֹּהֲנִים:\",4,0],[2,128,1,5,\"את הדם וזרקו את הדם. מַה תַּ\\\"ל דָּם דָּם שְׁנֵי פְּעָמִים? לְהָבִיא אֶת שֶׁנִּתְעָרֵב בְּמִינוֹ אוֹ בְּשֶׁאֵינוֹ מִינוֹ, יָכוֹל אַף בִּפְסוּלִים אוֹ בְּחַטָּאוֹת הַפְּנִימִיּוֹת אוֹ בְּחַטָּאוֹת הַחִיצוֹנִיּוֹת, שֶׁאֵלּוּ לְמַעְלָה וְהִיא לְמַטָּה, תַּ\\\"ל בְּמָקוֹם אַחֵר דָּמוֹ (זבחים פ\\\"א):\",5,0],[2,128,1,5,\"וזרקו. עוֹמֵד לְמַטָּה וְזוֹרֵק מִן הַכְּלִי לְכֹתֶל הַמִּזְבֵּחַ לְמַטָּה מִחוּט הַסִּקְרָא כְּנֶגֶד הַזָּוִיּוֹת, לְכָךְ נֶאֱמַר סָבִיב — שֶׁיְּהֵא הַדָּם נָתוּן בְּאַרְבַּע רוּחוֹת הַמִּזְבֵּחַ; אוֹ יָכוֹל יַקִּיפֶנּוּ כְּחוּט, תַּ\\\"ל וְזָרְקוּ וְאִי אֶפְשַׁר לְהַקִּיף בִּזְרִיקָה, אִי וְזָרְקוּ יָכוֹל בִּזְרִיקָה אַחַת, תַּ\\\"ל סָבִיב, הָא כֵּיצַד? נוֹתֵן שְׁתֵּי מַתָּנוֹת שֶׁהֵן אַרְבַּע (ספרא):\",6,0],[2,128,1,5,\"אשר פתח אהל מועד. וְלֹא בִּזְמַן שֶׁהוּא מְפֹרָק (שם):\",7,0],[2,128,1,6,\"והפשיט וגו'. מַה תַּלְמוּד לוֹמַר הָעוֹלָה? לְרַבּוֹת אֶת כָּל הָעוֹלוֹת לְהֶפְשֵׁט וְנִתּוּחַ:\",1,0],[2,128,1,6,\"אתה לנתחיה. וְלֹא נְתָחֶיהָ לִנְתָחִים (ספרא):\",2,0],[2,128,1,7,\"ונתנו … אש. אַעַ\\\"פִּי שֶׁהָאֵשׁ יוֹרֶדֶת מִן הַשָּׁמַיִם מִצְוָה לְהָבִיא מִן הַהֶדְיוֹט (שם):\",1,0],[2,128,1,7,\"בני אהרן הכהן. כְּשֶׁהוּא בְּכִהוּנוֹ, הָא אִם עָבַד בְּבִגְדֵי כֹּהֵן הֶדְיוֹט עֲבוֹדָתוֹ פְּסוּלָה:\",2,0],[2,128,1,8,\"בני אהרן הכהנים. כְּשֶׁהֵם בְּכִהוּנָם, הָא כֹּהֵן הֶדְיוֹט שֶׁעָבַד בִּשְׁמוֹנָה בְּגָדִים עֲבוֹדָתוֹ פְּסוּלָה (זבחים י\\\"ח):\",1,0],[2,128,1,8,\"את הנתחים את הראש. לְפִי שֶׁאֵין הָרֹאשׁ בִּכְלַל הֶפְשֵׁט, שֶׁכְּבָר הֻתַּז בִּשְׁחִיטָה, לְפִיכָךְ הֻצְרַךְ לִמְנוֹתוֹ לְעַצְמוֹ (חולין כ\\\"ז):\",2,0],[2,128,1,8,\"ואת הפדר. לָמָּה נֶאֱמַר? לְלַמֶּדְךָ שֶׁמַּעֲלֵהוּ עִם הָרֹאשׁ וּמְכַסֶּה בּוֹ אֶת בֵּית הַשְּׁחִיטָה, וְזֶהוּ דֶּרֶךְ כָּבוֹד שֶׁל מַעְלָה (שם):\",3,0],[2,128,1,8,\"אשר על המזבח. שֶׁלֹּא יִהְיוּ הַגְּזִירִין יוֹצְאִין חוּץ לַמַּעֲרָכָה (ספרא):\",4,0],[2,128,1,9,\"עלה. לְשֵׁם עוֹלָה יַקְטִירֶנּוּ:\",1,0],[2,128,1,9,\"אשה. כְּשֶׁיִּשְׁחֲטֶנּוּ יְהֵי שׁוֹחֲטוֹ לְשֵׁם הָאֵשׁ; וְכָל אִשֶּׁה לְשׁוֹן אֵשׁ, פוש\\\"ייר בְּלַעַז:\",2,0],[2,128,1,9,\"ניחוח. נַחַת רוּחַ לְפָנַי, שֶׁאָמַרְתִּי וְנַעֲשָֹה רְצוֹנִי (שם):\",3,0],[2,128,1,10,\"ואם מן הצאן. וי\\\"ו מוֹסִיף עַל עִנְיָן רִאשׁוֹן, וְלָמָּה הֻפְסַק? לִתֵּן רֶוַח לְמֹשֶׁה לְהִתְבּוֹנֵן בֵּין פָּרָשָׁה לְפָרָשָׁה (שם):\",1,0],[2,128,1,10,\"מן הצאן, מן הכשבים, מן העזים. הֲרֵי אֵלּוּ ג' מִעוּטִין — פְּרָט לְזָקֵן וּלְחוֹלֶה וְלִמְזֹהָם (שם):\",2,0],[2,128,1,11,\"על ירך המזבח. עַל צַד הַמִּזְבֵּחַ:\",1,0],[2,128,1,11,\"צפנה לפני ה'. וְאֵין צָפוֹן בְּבָמָה (שם):\",2,0],[2,128,1,14,\"מן העוף. וְלֹא כָּל הָעוֹף; לְפִי שֶׁנֶּאֱמַר תָּמִים זָכָר בַּבָּקָר בַּכְּשָׂבִים וּבָעִזִּים — תַּמּוּת וְזַכְרוּת בִּבְהֵמָה וְאֵין תַּמּוּת וְזַכְרוּת בְּעוֹפוֹת — יָכוֹל אַף מְחֻסַּר אֵבֶר, תַּ\\\"ל מִן הָעוֹף (שם):\",1,0],[2,128,1,14,\"תרים. גְּדוֹלִים וְלֹא קְטַנִּים:\",2,0],[2,128,1,14,\"בני יונה. קְטַנִּים וְלֹא גְּדוֹלִים:\",3,0],[2,128,1,14,\"מן התרים או מן בני היונה. פְּרָט לִתְחִלַּת הַצִּהוּב שֶׁבָּזֶה וְשֶׁבָּזֶה שֶׁהוּא פָּסוּל, שֶׁגָּדוֹל הוּא אֵצֶל בְּנֵי יוֹנָה וְקָטָן אֵצֶל תּוֹרִים (חולין כ\\\"ב):\",4,0],[2,128,1,15,\"והקריבו. אֲפִלּוּ פְּרֵדָה אַחַת יָבִיא (ספרא):\",1,0],[2,128,1,15,\"הכהן, ומלק. אֵין מְלִיקָה בִּכְלִי אֶלָּא בְּעַצְמוֹ שֶׁל כֹּהֵן, קוֹצֵץ בְּצִפָּרְנוֹ מִמּוּל הָעֹרֶף וְחוֹתֵךְ מַפְרַקְתּוֹ עַד שֶׁמַּגִּיעַ לַסִּימָנִין וְקוֹצְצָן (שם):\",2,0],[2,128,1,15,\"ונמצה דמו. לְשׁוֹן מִיץ אַפַּיִם (משלי ל'), כִּי אָפֵס הַמֵּץ (ישעיהו ט\\\"ז), כּוֹבֵשׁ בֵּית הַשְּׁחִיטָה עַל קִיר הַמִּזְבֵּחַ וְהַדָּם מִתְמַצֶּה וְיוֹרֵד (זבחים ס\\\"ה):\",3,0],[2,128,1,15,\"ומלק, והקטיר, ונמצה. אֶ\\\"לֹ כֵּן מֵאַחַר שֶׁהוּא מַקְטִיר הוּא מוֹצֶה? אֶלָּא מַה הַקְטָרָה הָרֹאשׁ בְּעַצְמוֹ וְהַגּוּף בְּעַצְמוֹ, אַף מְלִיקָה כֵּן. וּפְשׁוּטוֹ שֶׁל מִקְרָא מְסֹרָס הוּא — וּמָלַק וְהִקְטִיר, וְקֹדֶם הַקְטָרָה וְנִמְצָה דָמוֹ כְּבָר:\",4,0],[2,128,1,16,\"מראתו. מְקוֹם הָרְעִי, זֶה הַזֶּפֶק (ספרא):\",1,0],[2,128,1,16,\"בנצתה. עִם בְּנֵי מֵעֶיהָ, וְנוֹצָה לְשׁוֹן דָּבָר הַמָּאוּס, כְּמוֹ כִּי נָצוּ גַּם נָעוּ (איכה ד'), וְזֶהוּ שֶׁתִּרְגֵּם אֻנְקְלוֹס בְּאוּכְלֵיהּ; וְזֶהוּ מִדְרָשׁוֹ שֶׁל אַבָּא יוֹסֵי בֶּן חָנָן שֶׁאָמַר נוֹטֵל אֶת הַקֻּרְקְבָן עִמָּהּ; וְרַבּוֹתֵינוּ זִ\\\"לִ אָמְרוּ קוֹדֵר סְבִיב הַזֶּפֶק בְּסַכִּין כְּעֵין אֲרֻבָּה וְנוֹטְלוֹ עִם הַנּוֹצָה שֶׁעַל הָעוֹר (ספרא); בְּעוֹלַת בְּהֵמָה שֶׁאֵינָהּ אוֹכֶלֶת אֶלָּא בְּאֵבוּס בְּעָלֶיהָ, נֶאֱמַר וְהַקֶּרֶב וְהַכְּרָעַיִם יִרְחַץ בַּמָּיִם וְהִקְטִיר, וּבָעוֹף שֶׁנָּזוֹן מִן הַגָּזֵל, נֶאֱמַר וְהִשְלִיךְ אֶת הַמֵּעַיִם, שֶׁאָכַל מִן הַגָּזֵל (ויקרא רבה ג'):\",2,0],[2,128,1,16,\"אצל המזבח קדמה. בְּמִזְרָחוֹ שֶׁל כֶּבֶשׁ (ספרא):\",3,0],[2,128,1,16,\"אל מקום הדשן. מָקוֹם שֶׁנּוֹתְנִין שָׁם תְּרוּמַת הַדֶּשֶׁן בְּכָל בֹּקֶר וְדִשּׁוּן מִזְבֵּחַ הַפְּנִימִי וְהַמְּנוֹרָה, וְכֻלָּם נִבְלָעִים שָׁם בִּמְקוֹמָן:\",4,0],[2,128,1,17,\"ושסע. אֵין שִׁסּוּעַ אֶלָּא בַּיָּד, וְכֵן הוּא אוֹמֵר בְּשִׁמְשׁוֹן וַיְשַׁסְּעֵהוּ כְּשַׁסַּע הַגְּדִי וְגוֹ' (שופטים י\\\"ד):\",1,0],[2,128,1,17,\"בכנפיו. עִם כְּנָפָיו — אֵינוֹ צָרִיךְ לִמְרֹט כַּנְפֵי נוֹצָתוֹ:\",2,0],[2,128,1,17,\"בכנפיו. נוֹצָה מַמָּשׁ; וַהֲלֹא אֵין לְךָ הֶדְיוֹט שֶׁמֵּרִיחַ רֵיחַ כְּנָפַיִם נִשְֹרָפִים וְאֵין נַפְשׁוֹ קָצָה עָלָיו, וְלָמָּה אָמַר הַכָּתוּב יַקְרִיב? כְּדֵי שֶׁיְּהֵא הַמִּזְבֵּחַ שָֹבֵעַ וּמְהֻדָּר בְּקָרְבָּנוֹ שֶׁל עָנִי (ויק\\\"ר ג'):\",3,0],[2,128,1,17,\"לא יבדיל. אֵינוֹ מְפָרְקוֹ לְגַמְרֵי, לִשְׁתֵּי חֲתִיכוֹת, אֶלָּא קוֹרְעוֹ מִגַּבּוֹ; נֶאֱמַר בָּעוֹף רֵיחַ נִיחוֹחַ וְנֶאֱמַר בַּבְּהֵמָה רֵיחַ נִיחוֹחַ, לוֹמַר לְךָ אֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט וּבִלְבַד שֶׁיְּכַוֵּן אֶת לִבּוֹ לַשָּׁמַיִם (ספרא):\",4,0],[2,128,2,1,\"ונפש כי תקריב. לֹא נֶאֱמַר נֶפֶשׁ בְּכָל קָרְבְּנוֹת נְדָבָה אֶלָּא בַּמִּנְחָה, מִי דַּרְכּוֹ לְהִתְנַדֵּב מִנְחָה? עָנִי. אָמַר הַקָּבָּ\\\"ה, מַעֲלֶה אֲנִי עָלָיו כְּאִלּוּ הִקְרִיב נַפְשׁוֹ (מנחות ק\\\"ד):\",1,0],[2,128,2,1,\"סלת יהיה קרבנו. הָאוֹמֵר הֲרֵי עָלַי מִנְחָה סְתָם, מֵבִיא מִנְחַת סֹלֶת, שֶׁהִיא הָרִאשׁוֹנָה שֶׁבַּמְּנָחוֹת וְנִקְמֶצֶת כְּשֶׁהִיא סֹלֶת, כְּמוֹ שֶׁמְּפֹרָשׁ בָּעִנְיָן; לְפִי שֶׁנֶּאֶמְרוּ כָּאן חֲמִשָּׁה מִינֵי מְנָחוֹת, וְכֻלָּן בָּאוֹת אֲפוּיוֹת קֹדֶם קְמִיצָה חוּץ מִזּוֹ, לְכָךְ קְרוּיָה מִנְחַת סֹלֶת:\",2,0],[2,128,2,1,\"סלת. אֵין סֹלֶת אֶלָּא מִן הַחִטִּין, שֶׁנֶּאֱמַר סֹלֶת חִטִּים (שמות כ\\\"ט), וְאֵין מִנְחָה פְּחוּתָה מֵעִשָּׂרוֹן, שֶׁנֶּאֱמַר וְעִשָּׂרוֹן סֹלֶת … לְמִנְחָה (ויקרא י\\\"ד) — עִשָּׂרוֹן לְכָל מִנְחָה:\",3,0],[2,128,2,1,\"ויצק עליה שמן. עַל כֻּלָּהּ:\",4,0],[2,128,2,1,\"ונתן עליה לבנה. עַל מִקְצָתָהּ — מַנִּיחַ קֹמֶץ לְבוֹנָה עָלֶיהָ לְצַד אֶחָד. וּמָה רָאִיתָ לוֹמַר כֵּן? שֶׁאֵין רִבּוּי אַחַר רִבּוּי בַּתּוֹרָה אֶלָּא לְמַעֵט; דָּ\\\"אַ: שֶׁמֶן עַל כֻּלָּהּ, מִפְּנֵי שֶׁהוּא נִבְלָל עִמָּהּ וְנִקְמָץ עִמָּהּ, כְּמוֹ שֶׁנֶּאֱמַר מִסָּלְתָּהּ וּמִשַּׁמְנָהּ, וּלְבוֹנָה עַל מִקְצָתָהּ, שֶׁאֵינָהּ נִבְלֶלֶת עִמָּהּ וְלֹא נִקְמֶצֶת עִמָּהּ, שֶׁנֶּאֱמַר עַל כָּל לְבֹנָתָהּ, שֶׁלְּאַחַר שֶׁקָּמַץ מְלַקֵּט אֶת הַלְּבוֹנָה כֻּלָּהּ מֵעָלֶיהָ וּמַקְטִירָהּ (ספרא):\",5,0],[2,128,2,1,\"ויצק, ונתן, והביאה. מְלַמֵּד שֶׁיְּצִיקָה וּבְלִילָה כְּשֵׁרִים בְּזָר (שם):\",6,0],[2,128,2,2,\"הכהנים וקמץ. מִקְּמִיצָה וָאֵילָךְ מִצְוַת כְּהֻנָּה (שם):\",1,0],[2,128,2,2,\"וקמץ משם. מִמָּקוֹם שֶׁרַגְלֵי הַזָּר עוֹמְדוֹת; לְלַמֶּדְךָ שֶׁהַקְּמִיצָה כְּשֵׁרָה בְּכָל מָקוֹם בָּעֲזָרָה, אַף בְּי\\\"א אַמָּה שֶׁל מְקוֹם דְּרִיסַת רַגְלֵי יִשְֹרָאֵל (יומא ט\\\"ז):\",2,0],[2,128,2,2,\"מלא קמצו. יָכוֹל מְבֹרָץ — מְבַצְבֵּץ וְיוֹצֵא לְכָל צַד, תַּ\\\"לֹ בְּמָקוֹם אַחֵר וְהֵרִים מִמֶּנּוּ בְּקֻמְצוֹ (ויקרא ו') — לֹא יְהֵא כָּשֵׁר אֶלָּא מַה שֶּׁבְּתוֹךְ הַקֹּמֶץ, אִי בְּקֻמְצוֹ יָכוֹל חָסֵר, תַּ\\\"לֹ מְלֹא, הָא כֵּיצַד? חוֹפֶה שְׁלוֹשׁ אֶצְבְּעוֹתָיו עַל פַּס יָדוֹ, וְזֶהוּ קֹמֶץ בְּמַשְׁמַע לָשׁוֹן הָעִבְרִית (מנחות י\\\"א):\",3,0],[2,128,2,2,\"על כל לבנתה. לְבַד כָּל הַלְּבוֹנָה יְהֵא הַקֹּמֶץ מָלֵא:\",4,0],[2,128,2,2,\"לבנתה והקטיר. אַף הַלְּבוֹנָה בְּהַקְטָרָה:\",5,0],[2,128,2,2,\"מלא קמצו מסלתה ומשמנה. הָא אִם קָמַץ וְעָלָה בְּיָדוֹ גַּרְגֵּר מֶלַח אוֹ קֹרֶט לְבוֹנָה פְּסוּלָה (שם ו'):\",6,0],[2,128,2,2,\"אזכרתה. הַקֹּמֶץ הָעוֹלֶה לְגָבוֹהַּ הוּא זִכְרוֹן הַמִּנְחָה — שֶׁבּוֹ נִזְכָּר בְּעָלֶיהָ לְטוֹבָה וּלְנַחַת רוּחַ:\",7,0],[2,128,2,3,\"לאהרן ולבניו. כֹּהֵן גָּדוֹל נוֹטֵל חֵלֶק בָּרֹאשׁ שֶׁלֹּא בְּמַחֲלֹקֶת וְהַהֶדְיוֹט בְּמַחֲלֹקֶת (ספרא):\",1,0],[2,128,2,3,\"קדש קדשים. הִיא לָהֶם:\",2,0],[2,128,2,3,\"מאשי ה'. אֵין לָהֶם חֵלֶק בָּהּ אֶלָּא לְאַחַר מַתְּנוֹת הָאִשִּׁים (שם):\",3,0],[2,128,2,4,\"וכי תקריב וגו'. שֶׁאָמַר הֲרֵי עָלַי מִנְחַת מַאֲפֵה תַּנּוּר; וְלִמֵּד הַכָּתוּב שֶׁיָּבִיא אוֹ חַלּוֹת אוֹ רְקִיקִין, הַחַלּוֹת בְּלוּלוֹת וְהָרְקִיקִין מְשׁוּחִין; וְנֶחְלְקוּ רַבּוֹתֵינוּ בִּמְשִׁיחָתָן, יֵשׁ אוֹמְרִים מוֹשְׁחָן וְחוֹזֵר וּמוֹשְׁחָן עַד שֶׁכָּלֶה כָּל הַשֶּׁמֶן שֶׁבַּלֹּג — שֶׁכָּל הַמְּנָחוֹת טְעוּנוֹת לֹג שֶׁמֶן — וְיֵשׁ אוֹמְרִים מוֹשְׁחָן כְּמִין \\\"כִי\\\" וּשְׁאָר הַשֶּׁמֶן נֶאֱכָל בִּפְנֵי עַצְמוֹ לַכֹּהֲנִים (מנחות ע\\\"ה); מַה תַּ\\\"ל בַּשֶּׁמֶן בַּשֶּׁמֶן שְׁנֵי פְּעָמִים? לְהַכְשִׁיר שֶׁמֶן שֵׁנִי וּשְׁלִישִׁי הַיּוֹצֵא מִן הַזֵּיתִים, וְאֵין צָרִיךְ שֶׁמֶן רִאשׁוֹן אֶלָּא לַמְּנוֹרָה שֶׁנֶּאֱמַר בּוֹ זָךְ (שמות כ\\\"ז), וְשָׁנִינוּ בִּמְנָחוֹת כָּל הַמְּנָחוֹת הָאֲפוּיוֹת לִפְנֵי קְמִיצָתָן וְנִקְמָצוֹת עַל יְדֵי פְּתִיתָה, כֻּלָּן בָּאוֹת עֶשֶֹר עֶשֶֹר חַלּוֹת, וְהָאָמוּר בָּה רְקִיקִין בָּאָה עֲשָׂרָה רְקִיקִין (מנחות ע\\\"ו):\",1,0],[2,128,2,5,\"ואם מנחה על המחבת. שֶׁאָמַר הֲרֵי עָלַי מִנְחַת מַחֲבַת; וּכְלִי הוּא שֶׁהָיָה בַּמִּקְדָּשׁ, שֶׁאוֹפִין בּוֹ מִנְחָה זוֹ עַל הָאוּר בְּשֶׁמֶן, וְהַכְּלִי אֵינוֹ עָמֹק אֶלָּא צָף, וּמַעֲשֵׂי הַמִּנְחָה שֶׁבְּתוֹכוֹ קָשִׁין, שֶׁמִּתּוֹךְ שֶׁהִיא צָפָה, הָאוּר שׂוֹרֵף אֶת הַשֶּׁמֶן. וְכֻלָּן טְעוּנוֹת שָׁלוֹשׁ מַתְּנוֹת שֶׁמֶן — יְצִיקָה וּבְלִילָה וּמַתַּן שֶׁמֶן בִּכְלִי קֹדֶם לַעֲשִֹיָּתָן (שם ע\\\"ד):\",1,0],[2,128,2,5,\"סלת בלולה בשמן. מְלַמֵּד שֶׁבּוֹלְלָן בְּעוֹדָן סֹלֶת (מנחות ע\\\"ד):\",2,0],[2,128,2,6,\"פתות אתה פתים. לְרַבּוֹת כָּל הַמְּנָחוֹת הַנֶּאֱפוֹת קֹדֶם קְמִיצָה לִפְתִיתָה (שם ע\\\"ה):\",1,0],[2,128,2,6,\"ויצקת עליה שמן מנחה הוא. לְרַבּוֹת כָּל הַמְּנָחוֹת לִיצִיקָה; יָכוֹל אַף מִנְחָה מַאֲפֵה תַּנּוּר כֵּן, תַּ\\\"ל עָלֶיהָ; אוֹצִיא אֶת הַחַלּוֹת וְלֹא אוֹצִיא אֶת הָרְקִיקִין, תַּ\\\"ל הִוא (שם):\",2,0],[2,128,2,7,\"מרחשת. כְּלִי הוּא שֶׁהָיָה בַּמִּקְדָּשׁ, עָמֹק, וּמִתּוֹךְ שֶׁהִיא עֲמֻקָּה, שַׁמְנָהּ צָבוּר וְאֵין הָאוּר שׂוֹרְפוֹ, לְפִיכָךְ מַעֲשֵׂי מִנְחָה הָעֲשׂוּיִין לְתוֹכָהּ רוֹחֲשִׁין; כָּל דָּבָר רַךְ עַל יְדֵי מַשְׁקֶה נִרְאֶה כְּרוֹחֵשׁ וּמְנַעֲנֵעַ (ספרא):\",1,0],[2,128,2,8,\"אשר יעשה מאלה. מֵאֶחָד מִן הַמִּינִים הַלָּלוּ:\",1,0],[2,128,2,8,\"והקריבה. בְּעָלֶיהָ אל הכהן:\",2,0],[2,128,2,8,\"והגישה. הַכֹּהֵן:\",3,0],[2,128,2,8,\"והגישה אל המזבח. מַגִּישָׁהּ לְקֶרֶן דְּרוֹמִית מַעֲרָבִית שֶׁל מִזְבֵּחַ (זבחים ס\\\"ג):\",4,0],[2,128,2,9,\"את אזכרתה. הִיא הַקֹּמֶץ:\",1,0],[2,128,2,11,\"וכל דבש. כָּל מְתִיקַת פְּרִי קְרוּיָה דְּבַשׁ:\",1,0],[2,128,2,12,\"קרבן ראשית תקריבו אתם. מַה יֵּשׁ לְךָ לְהָבִיא מִן הַשְּׂאוֹר וּמִן הַדְּבַשׁ? קָרְבַּן רֵאשִׁית — שְׁתֵּי הַלֶּחֶם שֶׁל עֲצֶרֶת הַבָּאִים מִן הַשְּׂאוֹר, שֶׁנֶּאֱמַר חָמֵץ תֵּאָפֶינָה (ויקרא כ\\\"ג), וּבִכּוּרִים מִן הַדְּבַשׁ, כְּמוֹ בִּכּוּרֵי תְּאֵנִים וּתְמָרִים (מנחות נ\\\"ח):\",1,0],[2,128,2,13,\"מלח ברית. שֶׁהַבְּרִית כְּרוּתָה לַמֶּלַח מִשֵּׁשֶׁת יְמֵי בְּרֵאשִׁית, שֶׁהֻבְטְחוּ הַמַּיִם הַתַּחְתּוֹנִים לִקָּרֵב בַּמִּזְבֵּחַ בַּמֶּלַח וְנִסּוּךְ הַמַּיִם בֶּחָג:\",1,0],[2,128,2,13,\"על כל קרבנך. עַל עוֹלַת בְּהֵמָה וָעוֹף וְאֵמוּרֵי כָּל הַקָּדָשִׁים כֻּלָּן (מנחות כ'):\",2,0],[2,128,2,14,\"ואם תקריב. הֲרֵי אִם מְשַׁמֵּשׁ בִּלְשׁוֹן כִּי, שֶׁהֲרֵי אֵין זֶה רְשׁוּת, שֶׁהֲרֵי בְּמִנְחַת הָעֹמֶר הַכָּתוּב מְדַבֵּר שֶׁהִיא חוֹבָה, וְכֵן וְאִם יִהְיֶה הַיֹּבֵל וְגוֹ' (במדבר ל\\\"ו):\",1,0],[2,128,2,14,\"מנחת בכורים. בְּמִנְחַת הָעֹמֶר הַכָּתוּב מְדַבֵּר שֶׁהִיא בָּאָה אָבִיב — בִּשְׁעַת בִּשּׁוּל הַתְּבוּאָה, וּמִן הַשְּׂעוֹרִים הִיא בָּאָה, נֶאֱמַר כָּאן אָבִיב וְנֶאֱמַר לְהַלָּן (שמות ט'), הַשְּׂעֹרָה אָבִיב:\",2,0],[2,128,2,14,\"קלוי באש. שֶׁמְּיַבְּשִׁין אוֹתָהּ עַל הָאוּר בְּאַבּוּב שֶׁל קַלָּאִים, שֶׁאִלּוּלֵי כֵן אֵינָהּ נִטְחֶנֶת בָּרֵחַיִם, לְפִי שֶׁהִיא לַחָה:\",3,0],[2,128,2,14,\"גרש כרמל. גְּרוּסָה בְּעוֹדָהּ לַחָה:\",4,0],[2,128,2,14,\"גרש. גֶּרֶשׂ לְשׁוֹן שְׁבִירָה וּטְחִינָה, גּוֹרְסָהּ בְּרֵחַיִם שֶׁל גָּרוֹסוֹת, כְּמוֹ וַיַּגְרֵס בֶּחָצָץ (איכה ג'), וְכֵן גָּרְסָה נַפְשִׁי (תהילים קי\\\"ט):\",5,0],[2,128,2,14,\"כרמל. בְּעוֹד הַכַּר מָלֵא, שֶׁהַתְּבוּאָה לַחָה וּמְלֵאָה בְּקַשִּׁין שֶׁלָּהּ, וְעַל כֵּן נִקְרָאִים הַמְּלִילוֹת כַּרְמֶל, וְכֵן כַּרְמֶל בְּצִקְלוֹנוֹ (מלכים ב ד'):\",6,0],[2,128,3,1,\"שלמים. שֶׁמְּטִילִים שָׁלוֹם בָּעוֹלָם; דָּ\\\"אַ: שְׁלָמִים שֶׁיֵּשׁ בָּהֶם שָׁלוֹם לַמִּזְבֵּחַ וְלַכֹּהֲנִים וְלַבְּעָלִים (ספרא):\",1,0],[2,128,3,3,\"ואת כל החלב וגו'. לְהָבִיא חֵלֶב שֶׁעַל הַקֵּבָה דִּבְרֵי רַבִּי יִשְׁמָעֵאל, רַבִּי עֲקִיבָא אוֹמֵר לְהָבִיא חֵלֶב שֶׁעַל הַדַּקִּין (שם):\",1,0],[2,128,3,4,\"הכסלים. פלנק\\\"ש בְּלַעַז; שֶׁהַחֵלֶב שֶׁעַל הַכְּלָיוֹת כְּשֶׁהַבְּהֵמָה חַיָּה הוּא בְּגֹבַהּ הַכְּסָלִים מִלְּמַטָּה, וְזֶה הַחֵלֶב שֶׁתַּחַת הַמָּתְנַיִם — שֶׁקּוֹרִין בְּלַעַז לונבי\\\"לוש — לֹבֶן הַנִּרְאֶה לְמַעְלָה בְּגֹבַהּ הַכְּסָלִים, וּבְתַחְתִּיתוֹ הַבָּשָֹר חוֹפֵהוּ:\",1,0],[2,128,3,4,\"היתרת. הוּא דֹּפֶן הַמָּסָךְ שֶׁקּוֹרִין איברי\\\"ש, וּבְלָשׁוֹן אֲרַמִּי חִצְרָא דְּכַבְדָּא:\",2,0],[2,128,3,4,\"על הכבד. שֶׁיִּטֹּל מִן הַכָּבֵד עִמָּהּ מְעַט, וּבְמָקוֹם אַחֵר הוּא אוֹמֵר וְאֶת הַיֹּתֶרֶת מִן הַכָּבֵד (ויקרא ט'):\",3,0],[2,128,3,4,\"על הכבד על הכליות. לְבַד מִן הַכָּבֵד וּלְבַד מִן הַכְּלָיוֹת יְסִירֶנָּה לְזוֹ:\",4,0],[2,128,3,5,\"על העלה. מִלְּבַד הָעוֹלָה; לִמְּדָנוּ שֶׁתִּקְדֹּם עוֹלַת תָּמִיד לְכָל קָרְבָּן עַל הַמַּעֲרָכָה (זבחים פ\\\"ט):\",1,0],[2,128,3,7,\"אם כשב. לְפִי שֶׁיֵּשׁ בְּאֵמוּרֵי הַכֶּשֶׂב מַה שֶּׁאֵין בְּאֵמוּרֵי הָעֵז, שֶׁהַכֶּשֶׂב אַלְיָתוֹ קְרֵבָה, לְכָךְ נֶחְלְקוּ לִשְׁתֵּי פָּרָשִׁיּוֹת (ספרא):\",1,0],[2,128,3,8,\"וזרקו. שְׁתֵּי מַתָּנוֹת שֶׁהֵן אַרְבַּע; וְעַל יְדֵי הַכְּלִי הוּא זוֹרֵק, וְאֵינוֹ נוֹתֵן בָּאֶצְבַּע אֶלָּא חַטָּאת (זבחים נ\\\"ה):\",1,0],[2,128,3,9,\"חלבו. הַמֻּבְחָר שֶׁבּוֹ, וּמַהוּ? זֶה הָאַלְיָה תְּמִימָה:\",1,0],[2,128,3,9,\"לעמת העצה. לְמַעְלָה מִן הַכְּלָיוֹת הַיּוֹעֲצוֹת:\",2,0],[2,128,3,11,\"לחם אשה לה'. לַחְמוֹ שֶׁל אֵשׁ לְשֵׁם גָּבוֹהַּ:\",1,0],[2,128,3,11,\"לחם. לְשׁוֹן מַאֲכָל, וְכֵן נַשְׁחִיתָה עֵץ בְּלַחְמוֹ (ירמיהו י\\\"א), עֲבַד לְחֶם רַב (דניאל ה'), לִשְֹחוֹק עֹשִֹׁים לֶחֶם (קהלת י'):\",2,0],[2,128,3,17,\"חקת עולם. יָפֶה מְפֹרָשׁ בְּתוֹרַת כֹּהֲנִים כָּל הַפָּסוּק הַזֶּה:\",1,0],[2,128,4,2,\"מכל מצות ה'. פֵּרְשׁוּ רַבּוֹתֵינוּ אֵין חַטָּאת בָּאָה אֶלָּא עַל דָּבָר שֶׁזְּדוֹנוֹ לָאו וְכָרֵת (ספרא):\",1,0],[2,128,4,2,\"מאחת מהנה. מִמִּקְּצָת אַחַת מֵהֶן, כְּגוֹן הַכּוֹתֵב בְּשַׁבָּת שם מִשִּׁמְעוֹן, נח מִנָּחוֹר, דן מִדָּנִיֵּאל (שם):\",2,0],[2,128,4,3,\"אם הכהן המשיח יחטא לאשמת העם. מִדְרָשׁוֹ: אֵינוֹ חַיָּב אֶלָּא בְּהֶעְלֵם דָּבָר עִם שִׁגְגַת מַעֲשֶֹה, כְּמוֹ שֶׁנֶּאֱמַר לְאַשְׁמַת הָעָם וְנֶעְלַם דָּבָר מֵעֵינֵי הַקָּהָל וְעָשׂוּ (שם); וּפְשׁוּטוֹ לְפִי אַגָּדָה: כְּשֶׁכֹּהֵן גָּדוֹל חוֹטֵא, אַשְׁמַת הָעָם הוּא זֶה, שֶׁהֵן תְּלוּיִין בּוֹ לְכַפֵּר עֲלֵיהֶם וּלְהִתְפַּלֵּל בַּעֲדָם, וְנַעֲשֶׂה מְקֻלְקָל:\",1,0],[2,128,4,3,\"פר. יָכוֹל זָקֵן, תַּלְמוּד לוֹמַר בֶּן, אִי בֶּן יָכוֹל קָטָן, תַּלְמוּד לוֹמַר פַּר, הָא כֵּיצַד? זֶה פַּר בֶּן שָׁלוֹשׁ (שם):\",2,0],[2,128,4,5,\"אל אהל מועד. לַמִּשְׁכָּן, וּבְבֵית עוֹלָמִים לַהֵיכָל:\",1,0],[2,128,4,6,\"את פני פרכת הקדש. כְּנֶגֶד מְקוֹם קְדֻשָּׁתָהּ — מְכֻוָּן כְּנֶגֶד בֵּין הַבַּדִּים, וְלֹא הָיוּ נוֹגְעִים דָּמִים בַּפָּרֹכֶת, וְאִם נָגְעוּ נָגְעוּ:\",1,0],[2,128,4,7,\"ואת כל דם. שְׁיָרֵי הַדָּם (זבחים כ\\\"ה):\",1,0],[2,128,4,8,\"ואת כל חלב פר. חֶלְבּוֹ הָיָה לוֹ לוֹמַר, מַה תַּלְמוּד לוֹמַר פַּר? לְרַבּוֹת פַּר שֶׁל יוֹם הַכִּפּוּרִים לִכְלָיוֹת וְלַחֲלָבִים וְיוֹתֶרֶת (ספרא):\",1,0],[2,128,4,8,\"החטאת. לְהָבִיא שְֹעִירֵי עֲ\\\"זָ לִכְלָיוֹת וְלַחֲלָבִים וּלְיוֹתֶרֶת (שם):\",2,0],[2,128,4,8,\"ירים ממנו. מִן הַמְחֻבָּר — שֶׁלֹּא יְנַתְּחֶנּוּ קֹדֶם הֲסָרַת חֶלְבּוֹ, תּוֹרַת כֹּהֲנִים:\",3,0],[2,128,4,10,\"כאשר יורם. מֵאוֹתָן אֵמוּרִין הַמְפֹרָשִׁין בְּשׁוֹר זֶבַח הַשְּׁלָמִים; וְכִי מַה פֵּרֵשׁ בְּזֶבַח הַשְּׁלָמִים שֶׁלֹא פֵּרֵשׁ כָּאן? אֶלָּא לְהַקִּישׁוֹ לִשְׁלָמִים, מַה שְּׁלָמִים לִשְׁמָן אַף זֶה לִשְׁמוֹ, וּמָה שְׁלָמִים שָׁלוֹם לָעוֹלָם, אַף זֶה שָׁלוֹם לָעוֹלָם; וּבִשְׁחִיטַת קֳדָשִׁים מַצְרִיכוֹ לִלְמֹד הֵימֶנּוּ שֶׁאֵין לְמֵדִין לָמֵד מִן הַלָּמֵד בָּקֳדָשִׁים, בְּפֶרֶק אֵיזֶהוּ מְקוֹמָן (זבחים מ\\\"ט):\",1,0],[2,128,4,10,\"על הכבד על הכליות. על ראשו ועל כרעיו. כֻּלָּן לְשׁוֹן תּוֹסֶפֶת הֵן, כְּמוֹ מִלְּבַד:\",2,0],[2,128,4,12,\"אל מקום טהור. לְפִי שֶׁיֵּשׁ מִחוּץ לָעִיר מָקוֹם מוּכָן לְטֻמְאָה — לְהַשְׁלִיךְ אֲבָנִים מְנֻגָּעוֹת וּלְבֵית הַקְּבָרוֹת — הֻצְרַךְ לוֹמַר מִחוּץ לַמַּחֲנֶה זֶה — שֶׁהוּא חוּץ לָעִיר — שֶׁיְּהֵא הַמָּקוֹם טָהוֹר:\",1,0],[2,128,4,12,\"מחוץ למחנה. חוּץ לְשָׁלוֹשׁ מַחֲנוֹת; וּבֵית עוֹלָמִים חוּץ לָעִיר, כְּמוֹ שֶׁפֵּרְשׁוּהוּ רַבּוֹתֵינוּ בְּמַסֶּכֶת יוֹמָא (דף ס\\\"ח) וּבְסַנְהֶדְרִין (דף מ\\\"ב):\",2,0],[2,128,4,12,\"אל שפך הדשן. מָקוֹם שֶׁשּׁוֹפְכִין בּוֹ הַדֶּשֶׁן הַמְסֻלָּק מִן הַמִּזְבֵּחַ, כְּמוֹ שֶׁנֶּאֱמַר וְהוֹצִיא אֶת הַדֶּשֶׁן אֶל מִחוּץ לַמַּחֲנֶה (ויקרא ו'):\",3,0],[2,128,4,12,\"על שפך הדשן ישרף. שֶׁאֵין תַּלְמוּד לוֹמַר, אֶלָּא לְלַמֵּד שֶׁאֲפִלּוּ אֵין שָׁם דֶּשֶׁן (ספרא):\",4,0],[2,128,4,13,\"עדת ישראל. אֵלּוּ סַנְהֶדְרִין (שם):\",1,0],[2,128,4,13,\"ונעלם דבר. טָעוּ לְהוֹרוֹת בְּאַחַת מִכָּל כָּרֵתוֹת שֶׁבַּתּוֹרָה שֶׁהוּא מֻתָּר (הוריות ח'):\",2,0],[2,128,4,13,\"הקהל ועשו. שֶׁעָשׂוּ צִבּוּר עַל פִּיהֶם:\",3,0],[2,128,4,17,\"את פני הפרכת. וּלְמַעְלָה הוּא אוֹמֵר אֶת פְּנֵי פָּרֹכֶת הַקֹּדֶשׁ מָשָׁל לְמֶלֶךְ שֶׁסָּרְחָה עָלָיו מְדִינָה, אִם מִעוּטָהּ סָרְחָה, פָּמַלְיָא שֶׁלּוֹ מִתְקַיֶּמֶת וְאִם כֻּלָּהּ סָרְחָה, אֵין פָּמַלְיָא שֶׁלּוֹ מִתְקַיֶּמֶת, אַף כָּאן, כְּשֶׁחָטָא כֹּהֵן מָשִׁיחַ עֲדַיִן שֵׁם קְדֻשַּׁת הַמָּקוֹם עַל הַמִּקְדָּשׁ, מִשֶּׁחָטְאוּ כֻּלָּם, חַס וְשָׁלוֹם נִסְתַּלְּקָה הַקְּדֻשָּׁה (זבחים מ\\\"א):\",1,0],[2,128,4,18,\"יסוד מזבח העלה אשר פתח אהל מועד. זֶה יְסוֹד מַעֲרָבִי שֶׁהוּא כְּנֶגֶד הַפֶּתַח (שם נ\\\"א):\",1,0],[2,128,4,19,\"ואת כל חלבו ירים. אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ כָּאן יוֹתֶרֶת וּשְׁתֵּי כְּלָיוֹת, לְמֵדִין הֵם מִוְּעָשָׂה לַפָּר כַּאֲשֶׁר עָשָׂה וְגוֹ' וּמִפְּנֵי מָה לֹא נִתְפָּרְשׁוּ בּוֹ? תָּנָא דְּבֵי רַבִּי יִשְׁמָעֵאל מָשָׁל לְמֶלֶךְ שֶׁזָּעַם עַל אוֹהֲבוֹ וּמִעֵט בְּסִרְחוֹנוֹ מִפְּנֵי חִבָּתוֹ (שם מ\\\"א):\",1,0],[2,128,4,20,\"ועשה לפר זֶה כאשר עשה לפר החטאת. כְּמוֹ שֶׁמְּפֹרָשׁ בְּפַר כֹּהֵן מָשִׁיחַ — לְהָבִיא יוֹתֶרֶת וּשְׁתֵּי כְּלָיוֹת שֶׁפֵּרֵשׁ שָׁם, מַה שֶּׁלֹא פֵּרֵשׁ כָּאן, וְלִכְפֹּל בְּמִצְוַת הָעֲבוֹדוֹת, לְלַמֵּד שֶׁאִם חִסֵּר אַחַת מִכָּל הַמַּתָּנוֹת פָּסוּל; לְפִי שֶׁמָּצִינוּ בַּנִּתָּנִין עַל הַמִּזְבֵּחַ הַחִיצוֹן שֶׁנְּתָנָן בְּמַתָּנָה אַחַת כִּפֵּר, הֻצְרַךְ לוֹמַר כָּאן שֶׁמַּתָּנָה אַחַת מֵהֶן מְעַכֶּבֶת (שם ל\\\"ט):\",1,0],[2,128,4,22,\"אשר נשיא יחטא. לְשׁוֹן אַשְׁרֵי — אַשְׁרֵי הַדּוֹר שֶׁהַנָּשִׂיא שֶׁלּוֹ נוֹתֵן לֵב לְהָבִיא כַּפָּרָה עַל שִׁגְגָתוֹ, קַל וָחֹמֶר שֶׁמִּתְחָרֵט עַל זְדוֹנוֹתָיו (ספרא):\",1,0],[2,128,4,23,\"או הודע. כְּמוֹ אִם הוֹדַע הַדָּבָר; הַרְבֵּה אוֹ יֵשׁ שֶׁמְּשַׁמְּשִׁין בִּלְשׁוֹן אִם, וְאִם בִּמְקוֹם אוֹ, וְכֵן אוֹ נוֹדַע כִּי שׁוֹר נַגָּח הוּא (שמות כ\\\"א):\",1,0],[2,128,4,23,\"הודע אליו. כְּשֶׁחָטָא הָיָה סָבוּר שֶׁהוּא הֶתֵּר, וּלְאַחַר מִכָּאן נוֹדַע לוֹ שֶׁאִסּוּר הָיָה:\",2,0],[2,128,4,24,\"במקום אשר ישחט את העלה. בַּצָּפוֹן שֶׁהוּא מְפֹרָשׁ בָּעוֹלָה:\",1,0],[2,128,4,24,\"חטאת הוא. לִשְׁמוֹ כָּשֵׁר, שֶׁלֹּא לִשְׁמוֹ פָּסוּל (ספרא):\",2,0],[2,128,4,25,\"ואת דמו. שְׁיָרֵי הַדָּם:\",1,0],[2,128,4,26,\"כחלב זבח השלמים. כְּאוֹתָן אֵמוּרִין הַמְפֹרָשִׁים בְּעֵז הָאָמוּר אֵצֶל שְׁלָמִים:\",1,0],[2,128,4,31,\"כאשר הוסר חלב מעל זבח השלמים. כְּאֵמוּרֵי עֵז הָאֲמוּרִים בַּשְּׁלָמִים:\",1,0],[2,128,4,33,\"ושחט אתה לחטאת. שֶׁתְּהֵא שְׁחִיטָתָהּ לְשֵׁם חַטָּאת (זבחים ז'):\",1,0],[2,128,4,35,\"כאשר יוסר חלב הכשב. שֶׁנִּתְרַבּוּ אֵמוּרָיו בָּאַלְיָה, אַף חַטָּאת כְּשֶׁהִיא בָּאָה כִּבְשָׂה טְעוּנָה אַלְיָה עִם הָאֵמוּרִין:\",1,0],[2,128,4,35,\"על אשי ה'. עַל מְדוּרוֹת הָאֵשׁ הָעֲשׂוּיוֹת לַשֵּׁם, פוא\\\"ייליש בְּלַעַז:\",2,0],[2,128,5,1,\"ושמעה קול אלה. בְּדָבָר שֶׁהוּא עֵד בּוֹ — שֶׁהִשְׁבִּיעוּהוּ שְׁבוּעָה, שֶׁאִם יוֹדֵעַ לוֹ בְּעֵדוּת, שֶׁיָּעִיד לוֹ (ספרא):\",1,0],[2,128,5,2,\"או נפש אשר תגע וגו'. וּלְאַחַר הַטֻּמְאָה הַזּוֹ יֹאכַל קָדָשִׁים אוֹ יִכָּנֵס לַמִּקְדָּשׁ, שֶׁהוּא דָּבָר שֶׁזְּדוֹנוֹ כָּרֵת; בְּמַסֶּכֶת שְׁבוּעוֹת (דף י\\\"ד) נִדְרַשׁ כֵּן:\",1,0],[2,128,5,2,\"ונעלם ממנו. הַטֻּמְאָה:\",2,0],[2,128,5,2,\"ואשם. בַּאֲכִילַת קֹדֶשׁ אוֹ בְּבִיאַת מִקְדָּשׁ:\",3,0],[2,128,5,3,\"בטמאת אדם. זוֹ טֻמְאַת מֵת:\",1,0],[2,128,5,3,\"לכל טמאתו. לְרַבּוֹת טֻמְאַת מַגַּע זָבִין וְזָבוֹת:\",2,0],[2,128,5,3,\"אשר יטמא. לְרַבּוֹת הַנּוֹגֵעַ בְּבוֹעֵל נִדָּה:\",3,0],[2,128,5,3,\"בה. לְרַבּוֹת בּוֹלֵעַ נִבְלַת עוֹף טָהוֹר (ספרא):\",4,0],[2,128,5,3,\"ונעלם. וְלֹא יָדַע שֶׁשָּׁכַח הַטֻּמְאָה:\",5,0],[2,128,5,3,\"ואשם. בַּאֲכִילַת קֹדֶשׁ אוֹ בְּבִיאַת מִקְדָּשׁ:\",6,0],[2,128,5,4,\"בשפתים. וְלֹא בַּלֵּב (שם):\",1,0],[2,128,5,4,\"להרע. לְעַצְמוֹ:\",2,0],[2,128,5,4,\"או להיטיב. לְעַצְמוֹ, כְּגוֹן אֹכַל וְלֹא אֹכַל, אִישַׁן וְלֹא אִישַׁן (שבועות כ\\\"ז):\",3,0],[2,128,5,4,\"לכל אשר יבטא. לְרַבּוֹת לְשֶׁעָבַר:\",4,0],[2,128,5,4,\"ונעלם ממנו. וְעָבַר עַל שְׁבוּעָתוֹ, כָּל אֵלֶּה בְּקָרְבָּן עוֹלֶה וְיוֹרֵד, כַּמְּפֹרָשׁ כָּאן, אֲבָל שְׁבוּעָה שֶׁיֵּשׁ בָּהּ כְּפִירַת מָמוֹן אֵינָהּ בְּקָרְבָּן זוֹ אֶלָּא בְּאָשָׁם:\",5,0],[2,128,5,8,\"והקריב את אשר לחטאת ראשונה. חַטָּאת קוֹדֶמֶת לָעוֹלָה (ספרא); לְמָה הַדָּבָר דּוֹמֶה? לִפְרַקְלִיט שֶׁנִּכְנָס לְרַצּוֹת, רִצָּה פְּרַקְלִיט, נִכְנָס דּוֹרוֹן אַחֲרָיו (זבחים ז'):\",1,0],[2,128,5,8,\"ולא יבדיל. אֵינוֹ מוֹלֵק אֶלָּא סִימָן אֶחָד (חולין כ\\\"א):\",2,0],[2,128,5,8,\"ערף. הוּא גֹּבַהּ הָרֹאשׁ הַמַּשְׁפִּיעַ לְצַד הַצַּוָּאר:\",3,0],[2,128,5,8,\"ממול ערפו. מוּל הָרוֹאֶה אֶת הָעֹרֶף, וְהוּא אֹרֶךְ כָּל אֲחוֹרֵי הַצַּוָּאר (שם י\\\"ט):\",4,0],[2,128,5,9,\"והזה מדם החטאת. בָּעוֹלָה לֹא הִטְעִין אֶלָּא מִצּוּי, וּבַחַטָּאת הַזָּאָה וּמִצּוּי, אוֹחֵז בָּעֹרֶף וּמַתִּיז, וְהַדָּם נִתָּז וְהוֹלֵךְ לַמִּזְבֵּחַ:\",1,0],[2,128,5,9,\"חטאת הוא. לִשְׁמָהּ כְּשֵׁרָה, שֶׁלֹא לִשְׁמָהּ פְּסוּלָה (ספרא):\",2,0],[2,128,5,10,\"כמשפט. כַּדָּת הָאָמוּר בְּעוֹלַת הָעוֹף שֶׁל נְדָבָה בְּרֹאשׁ הַפָּרָשָׁה:\",1,0],[2,128,5,11,\"כי חטאת הוא. וְאֵין בַּדִּין שֶׁיְּהֵא קָרְבָּנוֹ מְהֻדָּר (מנחות ו'):\",1,0],[2,128,5,12,\"חטאת הוא. נִקְמְצָה וְנִקְטְרָה לִשְׁמָהּ כְּשֵׁרָה, שֶׁלֹּא לִשְׁמָהּ פְּסוּלָה:\",1,0],[2,128,5,13,\"על חטאתו אשר חטא. כָּאן שִׁנָּה הַכָּתוּב, שֶׁהֲרֵי בַּעֲשִׁירוּת וּבְדַלּוּת נֶאֱמַר מֵחַטָּאתוֹ, וְכָאן בְּדַלֵּי דַּלּוּת נֶאֱמַר עַל חַטָּאתוֹ, דִּקְדְּקוּ רַבּוֹתֵינוּ מִכָּאן, שֶׁאִם חָטָא כְּשֶׁהוּא עָשִׁיר וְהִפְרִישׁ מָעוֹת לְכִשְׂבָּה אוֹ שְׂעִירָה וְהֶעֱנִי, יָבִיא מִמִּקְצָתָן שְׁתֵּי תּוֹרִים, הִפְרִישׁ מָעוֹת לִשְׁתֵּי תּוֹרִים וְהֶעֱנִי, יָבִיא מִמִּקְצָתָן עֲשִׂירִית הָאֵפָה, הִפְרִישׁ מָעוֹת לַעֲשִׂירִית הָאֵפָה וְהֶעֱשִׁיר, יוֹסִיף עֲלֵיהֶן וְיָבִיא קָרְבַּן עָשִׁיר, לְכָךְ נֶאֱמַר כָּאן עַל חַטָּאתוֹ:\",1,0],[2,128,5,13,\"מאחת מאלה. מֵאַחַת מִשָּׁלוֹשׁ כַּפָּרוֹת הָאֲמוּרוֹת בָּעִנְיָן — אוֹ בַּעֲשִׁירוּת אוֹ בְּדַלּוּת אוֹ בְּדַלֵּי דַּלּוּת; וּמָה תַּלְמוּד לוֹמַר? שֶׁיָּכוֹל הַחֲמוּרִים שֶׁבָּהֶם יִהְיוּ בְּכִשְׂבָּה אוֹ שְׂעִירָה, וְהַקַּלִּין יִהְיוּ בְּעוֹף, וְהַקַּלִּין שֶׁבַּקַּלִין יִהְיוּ בַּעֲשִׂירִית הָאֵפָה, תַּלְמוּד לוֹמַר מֵאַחַת מֵאֵלֶּה, לְהַשְׁווֹת קַלִּין לַחֲמוּרִין לְכִשְׂבָּה וּשְׂעִירָה אִם הִשִּׂיגָה יָדוֹ, וְאֶת הַחֲמוּרִין לַקַּלִּין לַעֲשִׂירִית הָאֵפָה בְּדַלֵּי דַּלּוּת (ספרא):\",2,0],[2,128,5,13,\"והיתה לכהן כמנחה. לְלַמֵּד עַל מִנְחַת חוֹטֵא שֶׁיִּהְיוּ שְׁיָרֶיהָ נֶאֱכָלִין, זֶהוּ לְפִי פְּשׁוּטוֹ; וְרַבּוֹתֵינוּ דָּרְשׁוּ: \\\"וְהָיְתָה לַכֹּהֵן\\\" — וְאִם חוֹטֵא זֶה כֹּהֵן הוּא, תְּהֵא כִּשְׁאָר מִנְחַת נִדְבַת כֹּהֵן, שֶׁהִיא בְּכָלִיל תִּהְיֶה לֹא תֵאָכֵל (ספרא):\",3,0],[2,128,5,15,\"כי תמעל מעל. אֵין מְעִילָה בְּכָל מָקוֹם אֶלָּא שִׁנּוּי, וְכֵן הוּא אוֹמֵר וַיִּמְעֲלוּ בֵאלֹהֵי אֲבֹתֵיהֶם וַיִּזְנוּ אַחֲרֵי אֱלֹהֵי עַמֵּי הָאָרֶץ (דהי\\\"א ה'), וְכֵן הוּא אוֹמֵר בְּסוֹטָה וּמָעֲלָה בוֹ מָעַל (במדבר ה'):\",1,0],[2,128,5,15,\"וחטאה בשגגה מקדשי ה'. שֶׁנֶּהֱנָה מִן הַהֶקְדֵּשׁ; וְהֵיכָן הֻזְהַר? נֶאֱמַר כָּאן חֵטְא, וְנֶאֱמַר לְהַלָּן חֵטְא בִּתְרוּמָה, וְלֹא יִשְֹאוּ עָלָיו חֵטְא (ויקרא כ\\\"ב), מַה לְּהַלָּן הִזְהִיר, אַף כָּאן הִזְהִיר; אִי מַה לְּהַלָּן לֹא הִזְהִיר אֶלָּא עַל הָאוֹכֵל, אַף כָּאן לֹא הִזְהִיר אֶלָּא עַל הָאוֹכֵל, תַּ\\\"לֹ תִמְעֹל מַעַל — רִבָּה (ספרא):\",2,0],[2,128,5,15,\"מקדשי ה'. הַמְיֻחָדִים לַשֵּׁם, יָצְאוּ קָדָשִׁים קַלִּים (שם):\",3,0],[2,128,5,15,\"איל. לְשׁוֹן קָשֶׁה, כְּמוֹ וְאֶת אֵילֵי הָאָרֶץ לָקָח (יחזקאל י\\\"ז), אַף כָּאן קָשֶׁה — בֶּן שְׁתֵּי שָׁנִים (ספרא):\",4,0],[2,128,5,15,\"בערכך כסף שקלים. שֶׁיְּהֵא שָׁוֶה שְׁתֵּי סְלָעִים:\",5,0],[2,128,5,16,\"ואת אשר חטא מן הקדש ישלם. קֶרֶן וְחֹמֶשׁ לַהֶקְדֵּשׁ:\",1,0],[2,128,5,17,\"ולא ידע ואשם, והביא. הָעִנְיָן הַזֶּה מְדַבֵּר בְּמִי שֶׁבָּא סְפֵק כָּרֵת לְיָדוֹ וְלֹא יָדַע אִם עָבַר עָלָיו אִם לָאו, כְּגוֹן חֵלֶב וְשֻׁמָּן לְפָנָיו, וּכְסָבוּר שְׁתֵּיהֶן הֶתֵּר וְאָכַל אֶת הָאֶחָד, אָמְרוּ לוֹ אַחַת שֶׁל חֵלֶב הָיְתָה, וְלֹא יָדַע אִם זוֹ שֶׁל חֵלֶב אָכַל, הֲרֵי זֶה מֵבִיא אָשָׁם תָּלוּי, וּמֵגֵן עָלָיו כָּל זְמַן שֶׁלֹּא נוֹדַע לוֹ שֶׁוַּדַּאי חָטָא, וְאִם נוֹדַע לוֹ לְאַחַר זְמַן, יָבִיא חַטָּאת (כריתות כ\\\"ב):\",1,0],[2,128,5,17,\"ולא ידע ואשם ונשא עונו. רַבִּי יוֹסֵי הַגְּלִילִי אוֹמֵר, הֲרֵי הַכָּתוּב עָנַשׁ אֶת מִי שֶׁלֹּא יָדַע, עַל אַחַת כַּמָּה וְכַמָּה שֶׁיַּעֲנִישׁ אֶת מִי שֶׁיָּדַע, רַבִּי יוֹסֵי אוֹמֵר, אִם נַפְשְׁךָ לֵידַע מַתַּן שְֹכָרָן שֶׁל צַדִּיקִים, צֵא וּלְמַד מֵאָדָם הָרִאשׁוֹן שֶׁלֹּא נִצְטַוָּה אֶלָּא עַל מִצְוַת לֹא תַעֲשֶׂה וְעָבַר עָלֶיהָ, רְאֵה כַּמָּה מִיתוֹת נִקְנְסוּ עָלָיו וּלְדוֹרוֹתָיו. וְכִי אֵיזוֹ מִדָּה מְרֻבָּה שֶׁל טוֹבָה אוֹ שֶׁל פֻּרְעָנוּת? הֱוֵי אוֹמֵר מִדָּה טוֹבָה, אִם מִדַּת פֻּרְעָנוּת מְעוּטָה, רְאֵה כַּמָּה מִיתוֹת נִקְנְסוּ לוֹ וּלְדוֹרוֹתָיו, מִדָּה טוֹבָה הַמְרֻבָּה הַיּוֹשֵׁב לוֹ מִן הַפִּגּוּלִין וְהַנּוֹתָרוֹת וְהַמִּתְעַנֶּה בְּיוֹם הַכִּפּוּרִים — עַאַכַּ\\\"וְ שֶׁיִּזְכֶּה לוֹ וּלְדוֹרוֹתָיו וּלְדוֹרוֹת דּוֹרוֹתָיו עַד סוֹף כָּל הַדּוֹרוֹת; רַבִּי עֲקִיבָא אוֹמֵר, הֲרֵי הוּא אוֹמֵר עַל פִּי שְׁנַיִם עֵדִים אוֹ שְׁלֹשָׁה וְגוֹ' (דברים י\\\"ז), אִם מִתְקַיֶּמֶת הָעֵדוּת בִּשְׁנַיִם, לָמָּה פֵּרֵט לְךָ הַכָּתוּב ג'? אֶלָּא לְהָבִיא שְׁלִישִׁי לְהַחֲמִיר עָלָיו וְלַעֲשׂוֹת דִּינוֹ כַּיּוֹצֵא בָּאֵלּוּ לְעִנְיַן עֹנֶשׁ בַּהֲזָמָה; אִם כָּךְ עָנַשׁ הַכָּתוּב לַנִּטְפָּל לְעוֹבְרֵי עֲבֵרָה כְּעוֹבְרֵי עֲבֵרָה, עַל אַחַת כַּמָּה וְכַמָּה שֶׁיְּשַׁלֵּם שָֹכָר טוֹב לַנִּטְפָּל לְעוֹשֵׂי מִצְוָה כְּעוֹשֵׂי מִצְוָה (סנהדרין ט'); רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה אוֹמֵר, כִּי תִקְצֹר קְצִירְךָ בְשָׂדֶךָ וְשָׁכַחְתָּ עֹמֶר בַּשָּׂדֶה הֲרֵי הוּא אוֹמֵר לְמַעַן יְבָרֶכְךָ וְגוֹ' (דברים כ\\\"ד) — קָבַע הַכָּתוּב בְּרָכָה לְמִי שֶׁבָּאת עַל יָדוֹ מִצְוָה בְּלֹא יָדַע — אֱמֹר מֵעַתָּה, הָיְתָה סֶלַע צְרוּרָה בִּכְנָפָיו וְנָפְלָה הֵימֶנּוּ וּמְצָאָהּ הֶעָנִי וְנִתְפַּרְנֵס בָּהּ, הֲרֵי הַקָּבָּ\\\"ה קוֹבֵעַ לוֹ בְּרָכָה (ספרא):\",2,0],[2,128,5,18,\"בערכך לאשם. בָּעֵרֶךְ הָאָמוּר לְמַעְלָה:\",1,0],[2,128,5,18,\"אשר שגג והוא לא ידע. הָא אִם יָדַע לְאַחַר זְמַן, לֹא נִתְכַּפֵּר לוֹ בְּאָשָׁם זֶה עַד שֶׁיָּבִיא חַטָּאת, הָא לְמָה זֶה דּוֹמֶה? לְעֶגְלָה עֲרוּפָה שֶׁנִּתְעָרְפָה וְאַחַר כָּךְ נִמְצָא הַהוֹרֵג, הֲרֵי זֶה יֵהָרֵג (שם):\",2,0],[2,128,5,19,\"אשם הוא אשם אשם. הָרִאשׁוֹן כֻּלּוֹ קָמוּץ, שֶׁהוּא שֵׁם דָּבָר, וְהָאַחֲרוֹן חֶצְיוֹ קָמָץ וְחֶצְיוֹ פַּתָּח שֶׁהוּא לְשׁוֹן פָּעַל; וְאִם תֹּאמַר מִקְרָא שֶׁלֹּא לְצֹרֶךְ הוּא, כְּבָר דָּרוּשׁ הוּא בְּתוֹרַת כֹּהֲנִים, אשם אשם — לְהָבִיא אֲשַׁם שִׁפְחָה חֲרוּפָה שֶׁיְּהֵא אַיִל בֶּן שְׁתֵּי סְלָעִים, יָכוֹל שֶׁאֲנִי מְרַבֶּה אֲשַׁם נָזִיר וַאֲשַׁם מְצֹרָע, תַּלְמוּד לוֹמַר הוּא (שם):\",1,0],[2,128,5,21,\"נפש כי תחטא. אָמַר רַבִּי עֲקִיבָא, מַה תַּ\\\"ל וּמָעֲלָה מַעַל בַּה'? לְפִי שֶׁכָּל הַמַּלְוֶה וְהַלֹּוֶה וְהַנּוֹשֵֹׁא וְהַנּוֹתֵן אֵינוֹ עוֹשֶׂה אֶלָּא בְּעֵדִים וּבִשְׁטָר, לְפִיכָךְ בִּזְמַן שֶׁהוּא מְכַחֵשׁ, מְכַחֵשׁ בָּעֵדִים וּבַשְּׁטָר, אֲבָל הַמַּפְקִיד אֵצֶל חֲבֵרוֹ אֵינוֹ רוֹצֶה שֶׁתֵּדַע בּוֹ נְשָׁמָה אֶלָּא שְׁלִישִׁי שֶׁבֵּינֵיהֶם, לְפִיכָךְ כְּשֶׁהוּא מְכַחֵשׁ מְכַחֵשׁ בַּשְּׁלִישִׁי שֶׁבֵּינֵיהֶם (שם):\",1,0],[2,128,5,21,\"בתשומת יד. שֶׁשָּׂם בְּיָדוֹ מָמוֹן לְהִתְעַסֵּק אוֹ בְּמִלְוֶה:\",2,0],[2,128,5,21,\"או בגזל. שֶׁגָּזַל מִיָּדוֹ כְּלוּם:\",3,0],[2,128,5,21,\"או עשק. הוּא שְֹכַר שָֹכִיר (שם):\",4,0],[2,128,5,22,\"וכחש בה. שֶׁכָּפַר על אחת מכל אֵלֶּה אשר יעשה האדם לחטא וּלְהִשָּׁבַע עַל שֶׁקֶר לִכְפִירַת מָמוֹן:\",1,0],[2,128,5,23,\"כי יחטא ואשם. כְּשֶׁיַּכִּיר בְּעַצְמוֹ לָשׁוּב בִּתְשׁוּבָה, וּבְדַעְתּוֹ לְהִתְוַדּוֹת כִּי חָטָא וְאָשֵׁם:\",1,0],[2,128,5,24,\"בראשו. הוּא הַקֶּרֶן, רֹאשׁ הַמָּמוֹן:\",1,0],[2,128,5,24,\"וחמשתיו. רִבְּתָה הַתּוֹרָה חֲמִישִׁיּוֹת הַרְבֵּה לְקֶרֶן אַחַת, שֶׁאִם כָּפַר בַּחֹמֶשׁ וְנִשְׁבַּע וְהוֹדָה, חוֹזֵר וּמֵבִיא חֹמֶשׁ עַל אוֹתוֹ חֹמֶשׁ, וְכֵן מוֹסִיף וְהוֹלֵךְ עַד שֶׁיִּתְמַעֵט הַקֶּרֶן הַנִּשְׁבָּע לוֹ פָּחוֹת מִשָּׁוֶה פְּרוּטָה (בבא קמא ק\\\"ג):\",2,0],[2,128,5,24,\"לאשר הוא לו. לְמִי שֶׁהַמָּמוֹן שֶׁלּוֹ (שם):\",3,0],[2,128,6,2,\"צו את אהרן. אֵין צַו אֶלָּא לְשׁוֹן זֵרוּז מִיָּד וּלְדוֹרוֹת; אָמַר רַבִּי שִׁמְעוֹן, בְּיוֹתֵר צָרִיךְ הַכָּתוּב לְזָרֵז בְּמָקוֹם שֶׁיֵּשׁ בּוֹ חֶסְרוֹן כִּיס (ספרא):\",1,0],[2,128,6,2,\"זאת תורת העלה וגו'. הֲרֵי הָעִנְיָן הַזֶּה בָּא לְלַמֵּד עַל הֶקְטֵר חֲלָבִים וְאֵבָרִים שֶׁיְּהֵא כָּשֵׁר כָּל הַלַּיְלָה, וּלְלַמֵּד עַל הַפְּסוּלִין אֵי זֶה אִם עָלָה יֵרֵד, וְאֵי זֶה אִם עָלָה לֹא יֵרֵד, שֶׁכָּל תּוֹרָה לְרַבּוֹת הוּא בָּא, לוֹמַר — תּוֹרָה אַחַת לְכָל הָעוֹלִים, וַאֲפִלוּ פְּסוּלִין, שֶׁאִם עָלוּ לֹא יֵרְדוּ (שם):\",2,0],[2,128,6,2,\"הוא העלה. לְמַעֵט אֶת הָרוֹבֵעַ וְאֶת הַנִּרְבָּע וְכַיּוֹצֵא בָּהֶן, שֶׁלֹּא הָיָה פְּסוּלָן בַּקֹּדֶשׁ, שֶׁנִּפְסְלוּ קֹדֶם שֶׁבָּאוּ לָעֲזָרָה (שם ח):\",3,0],[2,128,6,3,\"מדו בד. הִיא הַכֻּתֹּנֶת, וּמָה תַּ\\\"ל מִדּוֹ? שֶׁתְּהֵא כְּמִדָּתוֹ (שם):\",1,0],[2,128,6,3,\"על בשרו. שֶׁלֹּא יְהֵא דָּבָר חוֹצֵץ בֵּינְתַיִם (זבחים י\\\"ט):\",2,0],[2,128,6,3,\"והרים את הדשן. הָיָה חוֹתֶה מְלֹא מַחְתָּה מִן הַמְאֻכָּלוֹת הַפְּנִימִיּוֹת וְנוֹתְנָן בְּמִזְרָחוֹ שֶׁל כֶּבֶשׁ (תמיד כ\\\"ח):\",3,0],[2,128,6,3,\"הדשן אשר תאכל האש את העלה. וַעֲשָׂאַתָּה דֶּשֶׁן, מֵאוֹתוֹ דֶּשֶׁן יָרִים תְּרוּמָה ושמו אצל המזבח:\",4,0],[2,128,6,3,\"[על המזבח. מָצָא אֵבָרִים שֶׁעֲדַיִן לֹא נִתְאַכְּלוּ, מַחֲזִירָן עַל מִזְבֵּחַ לְאַחַר שֶׁחָתָה גֶּחָלִים אֵילָךְ וָאֵילָךְ וְנָטַל מִן הַפְּנִימִיּוֹת, שֶׁנֶּאֱמַר אֶת הָעֹלָה עַל הַמִּזְבֵּחַ]:\",5,0],[2,128,6,4,\"ופשט את בגדיו. אֵין זוֹ חוֹבָה אֶלָּא דֶּרֶךְ אֶרֶץ, שֶׁלֹּא יְלַכְלֵךְ בְּהוֹצָאַת הַדֶּשֶׁן בְּגָדִים שֶׁהוּא מְשַׁמֵּשׁ בָּהֶן תָּמִיד — בְּגָדִים שֶׁבִּשֵּׁל בָּהֶן קְדֵרָה לְרַבּוֹ, אַל יִמְזֹג בָּהֶן כּוֹס לְרַבּוֹ, לְכָךְ וְלָבַשׁ בְּגָדִים אֲחֵרִים פְּחוּתִין מֵהֶם (ספרא):\",1,0],[2,128,6,4,\"והוציא את הדשן. הַצָּבוּר בַּתַּפּוּחַ, כְּשֶׁהוּא הַרְבֵּה וְאֵין מָקוֹם לַמַּעֲרָכָה, מוֹצִיאוֹ מִשָּׁם; וְאֵין זֶה חוֹבָה לְכָל יוֹם, אֲבָל הַתְּרוּמָה חוֹבָה בְּכָל יוֹם (תמיד כ\\\"ח):\",2,0],[2,128,6,5,\"והאש על המזבח תוקד בו. רִבָּה כָּאן יְקִידוֹת הַרְבֵּה — על מוקדה, ואש המזבח תוקד בו, והאש על המזבח תוקד בו, אש תמיד תוקד על המזבח, כֻּלָּן נִדְרְשׁוּ בְּמַסֶּכֶת יוֹמָא (דף מ\\\"ה), שֶׁנֶּחְלְקוּ רַבּוֹתֵינוּ בְּמִנְיַן הַמַּעֲרָכוֹת שֶׁהָיוּ שָׁם:\",1,0],[2,128,6,5,\"וערך עליה העלה. עוֹלַת תָּמִיד הִיא תִּקְדֹּם (מנחות מ\\\"ט):\",2,0],[2,128,6,5,\"חלבי השלמים. אִם יָבִיאוּ שָׁם שְׁלָמִים, וְרַבּוֹתֵינוּ לָמְדוּ מִכָּאן \\\"עָלֶיהָ\\\" — עַל עוֹלַת הַבֹּקֶר הַשְׁלֵם כָּל הַקָּרְבָּנוֹת כֻּלָּם, מִכָּאן שֶׁלֹּא יְהֵא דָּבָר מְאֻחָר לְתָמִיד שֶׁל בֵּין הָעַרְבָּיִם (ספרא):\",3,0],[2,128,6,6,\"אש תמיד. אֵשׁ שֶׁנֶּאֱמַר בּוֹ תָּמִיד, הִיא שֶׁמַּדְלִיקִין בָּהּ אֶת הַנֵּרוֹת שֶׁנֶּאֱמַר בָּה לְהַעֲלֹת נֵר תָּמִיד (שמות כ\\\"ז), אַף הִיא מֵעַל מִזְבֵּחַ הַחִיצוֹן תּוּקַד (יומא מ\\\"ה):\",1,0],[2,128,6,6,\"לא תכבה. הַמְכַבֶּה אֵשׁ עַל הַמִּזְבֵּחַ עוֹבֵר בִּשְׁנֵי לָאוִין:\",2,0],[2,128,6,7,\"וזאת תורת המנחה. תּוֹרָה אַחַת לְכֻלָּן — לְהַטְעִינָן שֶׁמֶן וּלְבוֹנָה הָאֲמוּרִין בָּעִנְיָן, שֶׁיָּכוֹל אֵין לִי טְעוּנוֹת שֶׁמֶן וּלְבוֹנָה אֶלָּא מִנְחַת יִשְֹרָאֵל שֶׁהִיא נִקְמֶצֶת, מִנְחַת כֹּהֲנִים שֶׁהִיא כָּלִיל מִנַּיִן? תַּ\\\"ל תּוֹרַת (ספרא):\",1,0],[2,128,6,7,\"הקרב אתה. הִיא הַגָּשָׁה בְּקֶרֶן דְּרוֹמִית מַעֲרָבִית (שם):\",2,0],[2,128,6,7,\"לפני ה'. הוּא מַעֲרָב שֶׁהוּא לְצַד אֹהֶל מוֹעֵד:\",3,0],[2,128,6,7,\"אל פני המזבח. הוּא הַדָּרוֹם, שֶׁהוּא פָּנָיו שֶׁל מִזְבֵּחַ, שֶׁהַכֶּבֶשׁ נָתוּן לְאוֹתוֹ הָרוּחַ (סוטה י\\\"ד):\",4,0],[2,128,6,8,\"והרים ממנו. מִן הַמְחֻבָּר — שֶׁיְּהֵא עִשָּׂרוֹן שָׁלֵם בְּבַת אַחַת בִּשְׁעַת קְמִיצָה (ספרא):\",1,0],[2,128,6,8,\"בקמצו. שֶׁלֹּא יַעֲשֶֹה מִדָּה לַקֹּמֶץ (שם):\",2,0],[2,128,6,8,\"מסלת המנחה ומשמנה. מִכָּאן שֶׁקּוֹמֵץ מִמָּקוֹם שֶׁנִּתְרַבָּה שַׁמְנָהּ (סוטה י\\\"ד):\",3,0],[2,128,6,8,\"המנחה. שֶׁלֹּא תְּהֵא מְעֹרֶבֶת בְּאַחֶרֶת (ספרא):\",4,0],[2,128,6,8,\"ואת כל הלבנה אשר על המנחה והקטיר. מְלַקֵּט אֶת לְבוֹנָתָהּ לְאַחַר קְמִיצָה וּמַקְטִירוֹ; וּלְפִי שֶׁלֹּא פֵּרֵשׁ כֵּן אֶלָּא בְּאַחַת מִן הַמְּנָחוֹת בְּוַיִּקְרָא, הֻצְרַךְ לִשְׁנוֹת פָּרָשָׁה זוֹ, לִכְלֹל כָּל הַמְּנָחוֹת כְּמִשְׁפָּטָן:\",5,0],[2,128,6,9,\"במקום קדש. וְאֵיזֶהוּ? בַּחֲצַר אֹהֶל מוֹעֵד:\",1,0],[2,128,6,10,\"לא תאפה חמץ חלקם. אַף הַשְּׁיָרִים אֲסוּרִים בְּחָמֵץ (מנחות נ\\\"ה):\",1,0],[2,128,6,10,\"כחטאת וכאשם. מִנְחַת חוֹטֵא הֲרֵי הִיא כְּחַטָּאת, לְפִיכָךְ קְמָצָהּ שֶׁלֹא לִשְׁמָהּ פְּסוּלָה, מִנְחַת נְדָבָה הֲרֵי הִיא כְּאָשָׁם, לְפִיכָךְ קְמָצָהּ שֶׁלֹּא לִשְׁמָהּ כְּשֵׁרָה (ספרא):\",2,0],[2,128,6,11,\"כל זכר. אֲפִלּוּ בַּעַל מוּם; לָמָּה נֶאֱמַר? אִם לַאֲכִילָה הֲרֵי כְּבָר אָמוּר, לֶחֶם אֱלֹהָיו מִקָּדְשֵׁי הַקֳּדָשִׁים וְגוֹ' (ויקרא כ\\\"א), אֶלָּא לְרַבּוֹת בַּעֲלֵי מוּמִין לְמַחֲלֹקֶת (ספרא):\",1,0],[2,128,6,11,\"כל אשר יגע וגו'. קָדָשִׁים קַלִּים אוֹ חֻלִּין שֶׁיִּגְּעוּ בָּהּ וְיִבְלְעוּ מִמֶּנָּה:\",2,0],[2,128,6,11,\"יקדש. לִהְיוֹת כָּמוֹהָ, שֶׁאִם פְּסוּלָה יִפָּסְלוּ, וְאִם כְּשֵׁרָה יֵאָכְלוּ כְּחֹמֶר הַמִּנְחָה (שם):\",3,0],[2,128,6,13,\"זה קרבן אהרן ובניו. אַף הַהֶדְיוֹטוֹת מַקְרִיבִין עֲשִׂירִית הָאֵפָה בַּיּוֹם שֶׁהֵן מִתְחַנְּכִין לָעֲבוֹדָה, אֲבָל כֹּהֵן גָּדוֹל בְּכָל יוֹם, שֶׁנֶּאֱמַר מִנְחָה תָּמִיד וְגוֹ' וְהַכֹּהֵן הַמָּשִׁיחַ תַּחְתָּיו מִבָּנָיו וְגוֹ' חָק עוֹלָם:\",1,0],[2,128,6,14,\"מרבכת. חֲלוּטָה בְּרוֹתְחִין כָּל צָרְכָּהּ (שם):\",1,0],[2,128,6,14,\"תפיני. אֲפוּיָה אֲפִיּוֹת הַרְבֵּה — אַחַר חֲלִיטָתָהּ אוֹפָהּ בַּתַּנּוּר וְחוֹזֵר וּמְטַגְּנָהּ בַּמַּחֲבַת (מנחות נ'):\",2,0],[2,128,6,14,\"מנחת פתים. מְלַמֵּד שֶׁטְּעוּנָה פְּתִיתָה:\",3,0],[2,128,6,15,\"המשיח תחתיו מבניו. הַמָּשִׁיחַ מִבָּנָיו תַּחְתָּיו:\",1,0],[2,128,6,15,\"כליל תקטר. אֵין נִקְמֶצֶת לִהְיוֹת שְׁיָרֶיהָ נֶאֱכָלִין אֶלָּא כֻּלָּהּ כָּלִיל, וְכֵן כָּל מִנְחַת כֹּהֵן שֶׁל נְדָבָה כָּלִיל תִּהְיֶה:\",2,0],[2,128,6,16,\"כליל. כֻּלָּהּ שָׁוָה לְגָבוֹהַּ:\",1,0],[2,128,6,19,\"המחטא אתה. הָעוֹבֵד עֲבוֹדוֹתֶיהָ — שֶׁהִיא נַעֲשֵׂית חַטָּאת עַל יָדוֹ:\",1,0],[2,128,6,19,\"המחטא אתה יאכלנה. הָרָאוּי לַעֲבוֹדָה; יָצָא טָמֵא בִּשְׁעַת זְרִיקַת דָּמִים, שֶׁאֵינוֹ חוֹלֵק בַּבָּשָׂר; וְאִי אֶפְשָׁר לוֹמַר שֶׁאוֹסֵר שְׁאָר כֹּהֲנִים בַּאֲכִילָתָהּ חוּץ מִן הַזּוֹרֵק דָּמָהּ, שֶׁהֲרֵי נֶאֱמַר לְמַטָּה כָּל זָכָר בַּכֹּהֲנִים יֹאכַל אֹתָהּ (זבחים צ\\\"ט):\",2,0],[2,128,6,20,\"כל אשר יגע בבשרה. כָּל דְּבַר אֹכֶל אֲשֶׁר יִגַּע וְיִבְלַע מִמֶּנָּה:\",1,0],[2,128,6,20,\"יקדש. לִהְיוֹת כָּמוֹהָ — אִם פְּסוּלָה תִּפָּסֵל, וְאִם הִיא כְּשֵׁרָה, תֵּאָכֵל כַּחֹמֶר שֶׁבָּהּ:\",2,0],[2,128,6,20,\"ואשר יזה מדמה על הבגד. וְאִם הֻזָּה מִדָּמָהּ עַל הַבֶּגֶד, אוֹתוֹ מְקוֹם הַדָּם שֶׁבַּבֶּגֶד אֲשֶׁר יִזֶּה עָלֶיה, תְּכַבֵּס בְּתוֹךְ הָעֲזָרָה:\",3,0],[2,128,6,20,\"אשר יזה. יְהֵא נִזֶּה, כְּמוֹ וְלֹא יִטֶּה לָאָרֶץ מִנְלָם (איוב ט\\\"ו) — יְהֵא נָטוּי:\",4,0],[2,128,6,21,\"ישבר. לְפִי שֶׁהַבְּלִיעָה שֶׁנִּבְלַעַת בּוֹ נַעֲשֶׂה נוֹתָר, וְהוּא הַדִּין לְכָל הַקֳּדָשִׁים:\",1,0],[2,128,6,21,\"ומרק. לְשׁוֹן תַּמְרוּקֵי הַנָּשִׁים (אסתר ב'), אשקור\\\"מנט בְּלַעַז:\",2,0],[2,128,6,21,\"ומרק ושטף. לִפְלֹט אֶת בְּלִיעָתוֹ, אֲבָל כְּלִי חֶרֶס לִמֶּדְךָ הַכָּתוּב כָּאן שֶׁאֵינוֹ יוֹצֵא מִידֵי דָּפְיוֹ לְעוֹלָם (עבודה זרה ל\\\"ד):\",3,0],[2,128,6,22,\"כל זכר בכהנים יאכל אתה. הָא לָמַדְתָּ שֶׁהַמְחַטֵּא אוֹתָהּ הָאָמוּר לְמַעְלָה לֹא לְהוֹצִיא שְׁאָר הַכֹּהֲנִים, אֶלָּא לְהוֹצִיא אֶת שֶׁאֵינוֹ רָאוּי לְחִטּוּי:\",1,0],[2,128,6,23,\"וכל חטאת וגו'. שֶׁאִם הִכְנִיס מִדַּם חַטָּאת הַחִיצוֹנָה לִפְנִים פְּסוּלָה:\",1,0],[2,128,6,23,\"וכל. לְרַבּוֹת שְׁאָר קָדָשִׁים (ספרא):\",2,0],[2,128,7,1,\"קדש קדשים הוא. הוּא קָרֵב וְאֵין תְּמוּרָתוֹ קְרֵבָה (ספרא):\",1,0],[2,128,7,2,\"ישחטו. רִבָּה לָנוּ שְׁחִיטוֹת הַרְבֵּה; לְפִי שֶׁמָּצִינוּ אָשָׁם בְּצִבּוּר, נֶאֱמַר \\\"יִשְׁחֲטוּ\\\" — רַבִּים, וּתְלָאוֹ בְּעוֹלָה, לְהָבִיא עוֹלַת צִבּוּר לַצָּפוֹן:\",1,0],[2,128,7,3,\"ואת כל חלבו וגו'. עַד כָּאן לֹא נִתְפָּרְשׁוּ אֵמוּרִין בָּאָשָׁם, לְכָךְ הֻצְרַךְ לְפָרְשָׁם כָּאן, אֲבָל חַטָּאת כְּבָר נִתְפָּרֵשׁ בָּהּ בְּפָרָשַׁת וַיִּקְרָא:\",1,0],[2,128,7,3,\"את האליה. לְפִי שֶׁאָשָׁם אֵינוֹ בָּא אֶלָּא אַיִל אוֹ כֶּבֶשׂ, וְאַיִל וְכֶבֶשׂ נִתְרַבּוּ בְּאַלְיָה:\",2,0],[2,128,7,5,\"אשם הוא. עַד שֶׁיִּנָּתֵק שְׁמוֹ מִמֶּנּוּ, לִמֵּד עַל אָשָׁם שֶׁמֵּתוּ בְּעָלָיו אוֹ שֶׁנִּתְכַּפְּרוּ בְּעָלָיו, אַעַ\\\"פִּי שֶׁעוֹמֵד לִהְיוֹת דָּמָיו עוֹלֶה לְקַיִץ הַמִּזְבֵּחַ, אִם שְׁחָטוֹ סְתָם, אֵינוֹ כָּשֵׁר לְעוֹלָה קֹדֶם שֶׁנִּתַּק לִרְעִיָּה; וְאֵינוֹ בָּא לְלַמֵּד עַל הָאָשָׁם שֶׁיְּהֵא פָּסוּל שֶׁלֹּא לִשְׁמוֹ — כְּמוֹ שֶׁדָּרְשׁוּ הוּא הַכָּתוּב בַּחַטָּאת — לְפִי שֶׁאָשָׁם לֹא נֶאֱמַר בּוֹ אָשָׁם הוּא אֶלָּא לְאַחַר הַקְטָרַת אֵמוּרִין, וְהוּא עַצְמוֹ שֶׁלֹּא הֻקְטְרוּ אֵמוּרָיו כָּשֵׁר (זבחים ה'):\",1,0],[2,128,7,6,\"קדש קדשים הוא. בְּתוֹרַת כֹּהֲנִים הוּא נִדְרָשׁ:\",1,0],[2,128,7,7,\"תורה אחת להם. בְּדָבָר זֶה:\",1,0],[2,128,7,7,\"הכהן אשר יכפר בו. הָרָאוּי לְכַפָּרָה חוֹלֵק בּוֹ, פְּרָט לִטְבוּל יוֹם וּמְחֻסַּר כִּפּוּרִים וְאוֹנֵן (ספרא):\",2,0],[2,128,7,8,\"עור העלה אשר הקריב לכהן לו יהיה. פְּרָט לִטְבוּל יוֹם וּמְחֻסַּר כִּפּוּרִים וְאוֹנֵן שֶׁאֵין חוֹלְקִים בָּעוֹרוֹת (שם):\",1,0],[2,128,7,9,\"לכהן המקריב אתה וגו'. יָכוֹל לוֹ לְבַדּוֹ, תַּ\\\"ל לכל בני אהרן תהיה, יָכוֹל לְכֻלָּן, תַּ\\\"ל לכהן המקריב, הָא כֵּיצַד? לְבֵית אָב שֶׁל יוֹם שֶׁמַּקְרִיבִין אוֹתָהּ (שם):\",1,0],[2,128,7,10,\"בלולה בשמן. זוֹ מִנְחַת נְדָבָה:\",1,0],[2,128,7,10,\"וחרבה. זוֹ מִנְחַת חוֹטֵא וּמִנְחַת קְנָאוֹת שֶׁאֵין בָּהֶן שֶׁמֶן:\",2,0],[2,128,7,12,\"אם על תודה יקריבנו. אִם עַל דְּבַר הוֹדָאָה עַל נֵס שֶׁנַּעֲשָׂה לוֹ, כְּגוֹן יוֹרְדֵי הַיָּם וְהוֹלְכֵי מִדְבָּרוֹת וַחֲבוּשֵׁי בֵּית הָאֲסוּרִים וְחוֹלֶה שֶׁנִּתְרַפֵּא — שֶׁהֵן צְרִיכִין לְהוֹדוֹת, שֶׁכָּתוּב בָּהֶן יוֹדוּ לַה' חַסְדּוֹ וְנִפְלְאוֹתָיו לִבְנֵי אָדָם וְיִזְבְּחוּ זִבְחֵי תוֹדָה (תהילים ק\\\"ז) — אִם עַל אַחַת מֵאֵלֶּה נָדַר שְׁלָמִים הַלָּלוּ, שַׁלְמֵי תּוֹדָה הֵן, וּטְעוּנוֹת לֶחֶם הָאָמוּר בָּעִנְיָן, וְאֵין נֶאֱכָלִין אֶלָּא לְיוֹם וְלַיְלָה, כְּמוֹ שֶׁמְּפֹרָשׁ כָּאן:\",1,0],[2,128,7,12,\"והקריב על זבח התודה. אַרְבָּעָה מִינֵי לֶחֶם — חַלּוֹת וּרְקִיקִין וּרְבוּכָה, שְׁלוֹשָׁה מִינֵי מַצָּה, וּכְתִיב עַל חַלֹּת לֶחֶם חָמֵץ וְגוֹ'; וְכָל מִין וָמִין עֶשֶׂר חַלּוֹת, כָּךְ מְפֹרָשׁ בִּמְנָחוֹת, וְשִׁעוּרָן חָמֵשׁ סְאִין יְרוּשַׁלְמִיּוֹת, שֶׁהֵן ו' מִדְבָּרִיּוֹת, כ' עִשָּׂרוֹן (מנחות ע\\\"ו):\",2,0],[2,128,7,12,\"מרבכת. לֶחֶם חָלוּט בְּרוֹתְחִין כָּל צָרְכּוֹ:\",3,0],[2,128,7,13,\"יקריב קרבנו על זבח. מַגִּיד שֶׁאֵין הַלֶּחֶם קָדוֹשׁ קְדֻשַּׁת הַגּוּף — לִפָּסֵל בְּיוֹצֵא וּטְבוּל יוֹם וּמִלָּצֵאת לְחֻלִּין בְּפִדְיוֹן — עַד שֶׁיִּשָּׁחֵט הַזֶּבַח (ספרא):\",1,0],[2,128,7,14,\"אחד מכל קרבן. לֶחֶם אֶחָד מִכָּל מִין וָמִין יִטֹּל תְּרוּמָה לַכֹּהֵן הָעוֹבֵד עֲבוֹדָתוֹ, וְהַשְּׁאָר נֶאֱכָל לַבְּעָלִים (מנחות ע\\\"ז); וּבָשָׂר לַבְּעָלִים חוּץ מֵחָזֶה וְשׁוֹק שֶׁבָּהּ, כְּמוֹ שֶׁמְּפֹרָשׁ לְמַטָּה תְּנוּפַת חָזֶה וְשׁוֹק בִּשְׁלָמִים, וְהַתּוֹדָה קְרוּיָה שְׁלָמִים:\",1,0],[2,128,7,15,\"ובשר זבח תודת שלמיו. יֵשׁ כָּאן רִבּוּיִין הַרְבֵּה, לְרַבּוֹת חַטָּאת וְאָשָׁם וְאֵיל נָזִיר וַחֲגִיגַת אַרְבָּעָה עָשָׂר שֶׁיִּהְיוּ נֶאֱכָלִין לְיוֹם וְלַיְלָה (ספרא):\",1,0],[2,128,7,15,\"ביום קרבנו יאכל. וְכִזְמַן בְּשָׂרָהּ זְמַן לַחְמָהּ:\",2,0],[2,128,7,15,\"לא יניח ממנו עד בקר. אֲבָל אוֹכֵל הוּא כָּל הַלַּיְלָה, אִם כֵּן לָמָּה אָמְרוּ עַד חֲצוֹת? כְּדֵי לְהַרְחִיק אָדָם מִן הָעֲבֵרָה (שם):\",3,0],[2,128,7,16,\"ואם נדר או נדבה. שֶׁלֹּא הֱבִיאָהּ עַל הוֹדָאָה שֶׁל נֵס, אֵינָהּ טְעוּנָה לֶחֶם, וְנֶאֱכֶלֶת לִשְׁנֵי יָמִים כְּמוֹ שֶׁמְּפֹרָשׁ בָּעִנְיָן:\",1,0],[2,128,7,16,\"וממחרת והנותר ממנו בָּרִאשׁוֹן יאכל. וי\\\"ו זוֹ יְתֵרָה הִיא, וְיֵשׁ כָּמוֹהָ הַרְבֵּה בַּמִּקְרָא, כְּגוֹן וְאֵלֶה בְנֵי צִבְעוֹן וְאַיָּה וַעֲנָה (בראשית ל\\\"ו), תֵּת וְקֹדֶשׁ וְצָבָא מִרְמָס (דניאל ח'):\",2,0],[2,128,7,18,\"ואם האכל יאכל וגו'. בִּמְחַשֵּׁב בַּשְּׁחִיטָה לְאָכְלוֹ בַּשְּׁלִישִׁי הַכָּתוּב מְדַבֵּר; יָכוֹל אִם אָכַל מִמֶּנּוּ בַּשְּׁלִישִׁי יִפָּסֵל לְמַפְרֵעַ, תַּלְמוּד לוֹמַר הַמַּקְרִיב אֹתוֹ לֹא יֵחָשֵׁב — בִּשְׁעַת הַקְרָבָה הוּא נִפְסָל וְאֵינוֹ נִפְסָל בַּשְּׁלִישִׁי; וְכֵן פֵּרוּשׁוֹ: בִּשְׁעַת הַקְרָבָתוֹ לֹא תַּעֲלֶה זֹאת בְּמַחֲשָׁבָה, וְאִם חִשֵּׁב פִּגּוּל יִהְיֶה (זבחים כ\\\"ט):\",1,0],[2,128,7,18,\"והנפש האכלת ממנו. אֲפִלּוּ בְּתוֹךְ הַזְּמַן עונה תשא:\",2,0],[2,128,7,19,\"והבשר. שֶׁל קֹדֶשׁ שְׁלָמִים אשר יגע בכל טמא לא יאכל:\",1,0],[2,128,7,19,\"והבשר. לְרַבּוֹת אֵבֶר שֶׁיָּצָא מִקְצָתוֹ — שֶׁהַפְּנִימִי מֻתָּר (ספרא):\",2,0],[2,128,7,19,\"כל טהור יאכל בשר. מַה תַּ\\\"ל? לְפִי שֶׁנֶּאֱמַר וְדַם זְבָחֶיךָ יִשָּׁפֵךְ וְגוֹ' וְהַבָּשָֹר תֹּאכֵל (דברים י\\\"ב), יָכוֹל לֹא יֹאכְלוּ שְׁלָמִים אֶלָּא הַבְּעָלִים, לְכָךְ נֶאֱמַר כָּל טָהוֹר יֹאכַל בָּשָֹר (ספרא):\",3,0],[2,128,7,19,\"(והבשר כל טהור יאכל בשר. כְּלוֹמַר, כָּל מַה שֶּׁאָסַרְתִּי לְךָ בְּחַטָּאת וְאָשָׁם, שֶׁאִם יָצְאוּ חוּץ לַקְּלָעִים אֲסוּרִין — כְּמוֹ שֶׁכָּתוּב בַּחֲצַר אֹהֶל מוֹעֵד יֹאכְלוּהָ (ויקרא ו') — בְּבָשָׂר זֶה אֲנִי אוֹמֵר לְךָ כָּל טָהוֹר יֹאכַל בָּשָׂר אֲפִלּוּ בְּכָל הָעִיר):\",4,0],[2,128,7,20,\"וטמאתו עליו. בְּטֻמְאַת הַגּוּף הַכָּתוּב מְדַבֵּר, אֲבָל טָהוֹר שֶׁאָכַל אֶת הַטָּמֵא אֵינוֹ עָנוּשׁ כָּרֵת אֶלָּא אַזְהָרַת והבשר אשר יגע בכל טמא וגו'; וְאַזְהָרַת טָמֵא שֶׁאָכַל אֶת הַטָּהוֹר אֵינָהּ מְפֹרֶשֶׁת בַּתּוֹרָה, אֶלָּא חֲכָמִים לְמָדוּהָ בִּגְזֵרָה שָׁוָה; שָׁלוֹשׁ כָּרֵתוֹת אֲמוּרוֹת בְּאוֹכְלֵי קָדָשִׁים בְּטֻמְאַת הַגּוּף, וּדְרָשׁוּם רַבּוֹתֵינוּ בִּשְׁבוּעוֹת אַחַת לִכְלָל, וְאַחַת לִפְרָט, וְאַחַת לְלַמֵּד עַל קָרְבָּן עוֹלֶה וְיוֹרֵד שֶׁלֹּא נֶאֱמַר אֶלָּא עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו:\",1,0],[2,128,7,24,\"יעשה לכל מלאכה. בָּא וְלִמֵּד עַל הַחֵלֶב שֶׁאֵינוֹ מְטַמֵּא טֻמְאַת נְבֵלוֹת:\",1,0],[2,128,7,24,\"ואכל לא תאכלהו. אָמְרָה תּוֹרָה, יָבֹא אִסּוּר נְבֵלָה וּטְרֵפָה וְיָחוּל עַל אִסּוּר חֵלֶב, שֶׁאִם אֲכָלוֹ יִתְחַיֵּב אַף עַל לָאו שֶׁל נְבֵלָה, וְלֹא תֹּאמַר אֵין אִסּוּר חָל עַל אִסּוּר (זבחים ע'):\",2,0],[2,128,7,26,\"בכל מושבתיכם. לְפִי שֶׁהִיא חוֹבַת הַגּוּף וְאֵינָהּ חוֹבַת קַרְקַע נוֹהֶגֶת בְּכָל מוֹשָׁבוֹת, וּבְמַסֶּכֶת קִדּוּשִׁין בְּפֶרֶק א' מְפֹרָשׁ לָמָּה הֻצְרַךְ לוֹמַר:\",1,0],[2,128,7,26,\"לעוף ולבהמה. פְּרָט לְדַם דָּגִים וַחֲגָבִים (כריתות כ'):\",2,0],[2,128,7,30,\"ידיו תביאינה וגו'. שֶׁתְּהֵא יַד הַבְּעָלִים מִלְּמַעְלָה, וְהַחֵלֶב וְהֶחָזוֹת נְתוּנִין בָּהּ, וְיַד כֹּהֵן מִלְּמַטָּה וּמְנִיפָן (מנחות ס\\\"א):\",1,0],[2,128,7,30,\"את אשי ה'. וּמָה הֵן הָאִשִּׁים?\",2,0],[2,128,7,30,\"את החלב על החזה יביאנו. כְּשֶׁמְּבִיאוֹ מִבֵּית הַמִּטְבָּחַיִם נוֹתֵן חֵלֶב עַל הֶחָזֶה, וּכְשֶׁנּוֹתְנוֹ לְיַד הַכֹּהֵן הַמֵּנִיף נִמְצָא הֶחָזֶה לְמַעְלָה וְהַחֵלֶב לְמַטָּה, וְזֶהוּ הָאָמוּר בְּמָקוֹם אַחֵר שׁוֹק הַתְּרוּמָה וַחֲזֵה הַתְּנוּפָה עַל אִשֵּׁי הַחֲלָבִים יָבִיאוּ לְהָנִיף וְגוֹ' (ויקרא י'), וּלְאַחַר הַתְּנוּפָה נוֹתְנוֹ לַכֹּהֵן הַמַּקְטִיר, וְנִמְצָא הֶחָזֶה לְמַטָּה, וְזֶהוּ שֶׁנֶּאֱמַר וַיָּשִֹימוּ אֶת הַחֲלָבִים עַל הֶחָזוֹת וַיַּקְטֵר הַחֲלָבִים הַמִּזְבֵּחָה (שם ט'), לִמְּדָנוּ שֶׁשְּׁלוֹשָׁה כֹּהֲנִים זְקוּקִין לָהּ, כָּךְ מְפֹרָשׁ בִּמְנָחוֹת:\",3,0],[2,128,7,30,\"את החלב על החזה יביאנו. וְאֶת הֶחָזֶה לָמָּה מֵבִיא? לְהָנִיף אוֹתוֹ הוּא מְבִיאוֹ וְלֹא שֶׁיְּהֵא הוּא מֵהָאִשִּׁים: לְפִי שֶׁנֶּאֱמַר את אשי ה' את החלב על החזה יָכוֹל שֶׁיְּהֵא אַף הֶחָזֶה לָאִשִּׁים, לְכָךְ נֶאֱמַר את החזה להניף וגו':\",4,0],[2,128,7,31,\"והקטיר הכהן את החלב. וְאַחַ\\\"כַּ והיה החזה לאהרן, לִמְּדָנוּ שֶׁאֵין הַבָּשָׂר נֶאֱכָל בְּעוֹד שֶׁהָאֵמוּרִים לְמַטָּה מִן הַמִּזְבֵּחַ (ספרא):\",1,0],[2,128,7,32,\"שוק. מִן הַפֶּרֶק שֶׁל אַרְכֻּבָּה הַנִּמְכֶּרֶת עִם הָרֹאשׁ עַד הַפֶּרֶק הָאֶמְצָעִי שֶׁהוּא סֹבֶךְ שֶׁל רֶגֶל (חולין קל\\\"ד):\",1,0],[2,128,7,33,\"המקריב את דם השלמים וגו'. מִי שֶׁהוּא רָאוּי לִזְרִיקָתוֹ וּלְהַקְטִיר חֲלָבָיו, יָצָא טָמֵא בִּשְׁעַת זְרִיקַת דָּמִים אוֹ בִּשְׁעַת הֶקְטֵר חֲלָבִים שֶׁאֵינוֹ חוֹלֵק בַּבָּשָׂר (ספרא):\",1,0],[2,128,7,34,\"תנופה, תרומה. מוֹלִיךְ וּמֵבִיא מַעֲלֶה וּמוֹרִיד (מנחות ס\\\"ב):\",1,0],[2,128,7,37,\"ולמלואים. לְיוֹם חִנּוּךְ הַכְּהֻנָּה:\",1,0],[2,128,8,2,\"קח את אהרן. פָּרָשָׁה זוֹ נֶאֶמְרָה שִׁבְעַת יָמִים קֹדֶם הֲקָמַת הַמִּשְׁכָּן, שֶׁאֵין מֻקְדָּם וּמְאֻחָר בַּתּוֹרָה:\",1,0],[2,128,8,2,\"קח את אהרן. קָחֶנּוּ בִדְבָרִים וּמָשְׁכֵהוּ:\",2,0],[2,128,8,2,\"ואת פר החטאת וגו'. אֵלּוּ הָאֲמוּרִים בְּעִנְיַן צַוָּאַת הַמִּלּוּאִים בִּוְאַתָּה תְּצַוֶּה, וְעַכְשָׁיו בְּיוֹם רִאשׁוֹן לַמִּלּוּאִים חָזַר וְזֵרְזוֹ בִשְׁעַת מַעֲשֶֹה:\",3,0],[2,128,8,3,\"הקהל אל פתח אהל מועד. זֶה אֶחָד מִן הַמְּקוֹמוֹת שֶׁהֶחֱזִיק מֻעָט אֶת הַמְרֻבֶּה (ויקרא רבה י'):\",1,0],[2,128,8,5,\"זה הדבר. דְּבָרִים שֶׁתִּרְאוּ שֶׁאֲנִי עוֹשֶׂה לִפְנֵיכֶם, צִוַּנִי הַקָּבָּ\\\"ה לַעֲשׂוֹת, וְאַל תֹּאמְרוּ לִכְבוֹדִי וְלִכְבוֹד אָחִי אֲנִי עוֹשֶֹׁה; כָּל הָעִנְיָן הַזֶּה פֵּרַשְׁתִּי בְּ\\\"וְאַתָּה תְּצַוֶּה\\\":\",1,0],[2,128,8,8,\"את האורים. כְּתָב שֶׁל שֵׁם הַמְפֹרָשׁ:\",1,0],[2,128,8,9,\"וישם על המצנפת. פְּתִילֵי תְכֵלֶת הַקְּבוּעִים בַּצִּיץ נָתַן עַל הַמִּצְנֶפֶת, נִמְצָא הַצִּיץ תָּלוּי בַּמִּצְנֶפֶת:\",1,0],[2,128,8,11,\"ויז ממנו על המזבח. לֹא יָדַעְתִּי הֵיכָן נִצְטַוָּה בַּהַזָּאוֹת הַלָּלוּ:\",1,0],[2,128,8,12,\"ויצק, וימשח. בַּתְּחִלָּה יוֹצֵק עַל רֹאשׁוֹ וְאַחַר כָּךְ נוֹתֵן בֵּין רִיסֵי עֵינָיו וּמוֹשֵׁךְ בְּאֶצְבָּעוֹ מִזֶּה לָזֶה (הוריות י\\\"ב):\",1,0],[2,128,8,13,\"ויחבש. לְשׁוֹן קְשִׁירָה:\",1,0],[2,128,8,15,\"ויחטא את המזבח. חִטְּאוֹ וְטִהֲרוֹ מִזָּרוּת לִכָּנֵס לִקְדֻשָּׁה:\",1,0],[2,128,8,15,\"ויקדשהו. בַּעֲבוֹדָה זוֹ:\",2,0],[2,128,8,15,\"לכפר עליו. מֵעַתָּה כָּל הַכַּפָּרוֹת:\",3,0],[2,128,8,16,\"הכבד. לְבַד הַכָּבֵד, שֶׁהָיָה נוֹטֵל מְעַט מִן הַכָּבֵד עִמָּהּ:\",1,0],[2,128,8,22,\"איל המלאים. אֵיל הַשְּׁלָמִים, שֶׁמִּלּוּאִים לְשׁוֹן שְׁלָמִים, שֶׁמְּמַלְּאִין וּמַשְׁלִימִין אֶת הַכֹּהֲנִים בִּכְהֻנָּתָם:\",1,0],[2,128,8,26,\"וחלת לחם שמן. הִיא רְבוּכָה שֶׁהָיָה מַרְבֶּה בָּהּ שֶׁמֶן כְּנֶגֶד הַחַלּוֹת וְהָרְקִיקִין, כָּךְ מְפֹרָשׁ בִּמְנָחוֹת (דף פ\\\"ט):\",1,0],[2,128,8,28,\"ויקטר המזבחה. מֹשֶׁה שִׁמֵּשׁ כָּל שִׁבְעַת יְמֵי הַמִּלּוּאִים בְּחָלוּק לָבָן (עבודה זרה ל\\\"ד):\",1,0],[2,128,8,28,\"על העלה. אַחַר הָעוֹלָה, וְלֹא מָצִינוּ שׁוֹק שֶׁל שְׁלָמִים קָרֵב בְּכָל מָקוֹם חוּץ מִזֶּה:\",2,0],[2,128,8,34,\"צוה ה' לעשת. כָּל שִׁבְעַת הַיָּמִים; וְרַבּוֹתֵינוּ דָרְשׁוּ, לעשת — זֶה מַעֲשֵׂה פָרָה, לכפר — זֶה מַעֲשֵׂה יוֹם הַכִּפּוּרִים, וּלְלַמֵּד שֶׁכֹּהֵן גָּדוֹל טָעוּן פְּרִישָׁה קֹדֶם יוֹם הַכִּפּוּרִים שִׁבְעַת יָמִים, וְכֵן הַכֹּהֵן הַשּׂוֹרֵף אֶת הַפָּרָה (ספרא):\",1,0],[2,128,8,35,\"ולא תמותו. הָא אִם לֹא תַעֲשׂוּ כֵן הֲרֵי אַתֶּם חַיָּבִים מִיתָה:\",1,0],[2,128,8,36,\"ויעש אהרן ובניו. לְהַגִּיד שִׁבְחָן, שֶׁלֹא הִטּוּ יָמִין וּשְֹמֹאל:\",1,0],[2,128,9,1,\"ויהי ביום השמיני. לַמִּלּוּאִים; הוּא רֹאשׁ חֹדֶשׁ נִיסָן שֶׁהוּקַם הַמִּשְׁכָּן בּוֹ בַיּוֹם וְנָטַל עֶשֶׂר עֲטָרוֹת הַשְּׁנוּיוֹת בְּסֵדֶר עוֹלָם:\",1,0],[2,128,9,1,\"ולזקני ישראל. לְהַשְׁמִיעָם שֶׁעַל פִּי הַדִּבּוּר אַהֲרֹן נִכְנָס וּמְשַׁמֵּשׁ בִּכְהֻנָּה גְדוֹלָה וְלֹא יֹאמְרוּ מֵאֵלָיו נִכְנָס (תנחומא):\",2,0],[2,128,9,2,\"קח לך עגל. לְהוֹדִיעַ שֶׁכִּפֵּר לוֹ הַקָּבָּ\\\"ה עַל יְדֵי עֵגֶל זֶה עַל מַעֲשֵׂה הָעֵגֶל שֶׁעָשָֹה (שם):\",1,0],[2,128,9,4,\"כי היום ה' נראה אליכם. לְהַשְׁרוֹת שְׁכִינָתוֹ בְמַעֲשֵׂה יְדֵיכֶם, לְכָךְ קָרְבָּנוֹת הַלָּלוּ בָּאִין חוֹבָה לְיוֹם זֶה:\",1,0],[2,128,9,7,\"קרב אל המזבח. שֶׁהָיָה אַהֲרֹן בּוֹשׁ וְיָרֵא לָגֶשֶׁת, אָמַר לוֹ מֹשֶׁה, לָמָּה אַתָּה בוֹשׁ? לְכָךְ נִבְחַרְתָּ (ספרא):\",1,0],[2,128,9,7,\"את חטאתך. עֵגֶל בֶּן בָּקָר:\",2,0],[2,128,9,7,\"ואת עלתך. הָאָיִל:\",3,0],[2,128,9,7,\"קרבן העם. שְׂעִיר עִזִּים וְעֵגֶל וְכֶבֶשׂ; כָּל מָקוֹם שֶׁנֶּאֱמַר \\\"עֵגֶל\\\" בֶּן שָׁנָה הוּא וּמִכָּאן אַתָּה לָמֵד (שם):\",4,0],[2,128,9,11,\"ואת הבשר ואת העור וגו'. לֹא מָצִינוּ חַטָּאת חִיצוֹנָה נִשְֹרֶפֶת אֶלָּא זוֹ וְשֶׁל מִלּוּאִים, וְכֻלָּן עַל פִּי הַדִּבּוּר:\",1,0],[2,128,9,12,\"וימצאו. לְשׁוֹן הוֹשָׁטָה וְהַזְמָנָה:\",1,0],[2,128,9,15,\"ויחטאהו. עָשָׂהוּ כְּמִשְׁפַּט חַטָּאת:\",1,0],[2,128,9,15,\"כראשון. כָּעֵגֶל שֶׁלּוֹ:\",2,0],[2,128,9,16,\"ויעשה כמשפט. הַמְפֹרָשׁ בְּעוֹלַת נְדָבָה בְּוַיִּקְרָא:\",1,0],[2,128,9,17,\"וימלא כפו. הִיא קְמִיצָה (שם):\",1,0],[2,128,9,17,\"מלבד עלת הבקר. כָּל אֵלֶּה עָשָֹה אַחַר עוֹלַת הַתָּמִיד:\",2,0],[2,128,9,19,\"והמכסה. חֵלֶב הַמְכַסֶּה אֶת הַקֶּרֶב:\",1,0],[2,128,9,20,\"וישימו את החלבים על החזות. לְאַחַר הַתְּנוּפָה נְתָנָן כֹּהֵן הַמֵּנִיף לְכֹהֵן אַחֵר לְהַקְטִירָם, נִמְצְאוּ הָעֶלְיוֹנִים לְמַטָּה (מנחות ס\\\"ב):\",1,0],[2,128,9,22,\"ויברכם. בִּרְכַּת כֹּהֲנִים — יְבָרֶכְךָ, יָאֵר, יִשָּׂא (סוטה ל\\\"ח):\",1,0],[2,128,9,22,\"וירד. מֵעַל הַמִּזְבֵּחַ:\",2,0],[2,128,9,23,\"ויבא משה ואהרן וגו'. לָמָּה נִכְנְסוּ? מָצָאתִי בְּפָרָשַׁת מִלּוּאִים, בְּבָרַיְתָא הַנּוֹסֶפֶת עַל תּוֹרַת כֹּהֲנִים שֶׁלָּנוּ, לָמָּה נִכְנַס מֹשֶׁה עִם אַהֲרֹן? לְלַמְּדוֹ עַל מַעֲשֵׂה הַקְּטֹרֶת, אוֹ לֹא נִכְנַס אֶלָּא לְדָבָר אַחֵר? הֲרֵינִי דָן, יְרִידָה וּבִיאָה טְעוּנָה בְרָכָה, מַה יְּרִידָה מֵעֵין עֲבוֹדָה אַף בִּיאָה מֵעֵין עֲבוֹדָה, הָא לָמַדְתָּ לָמָּה נִכְנַס מֹשֶׁה עִם אַהֲרֹן לְלַמְּדוֹ עַל מַעֲשֵׂה הַקְּטֹרֶת; דָּ\\\"אַ כֵּיוָן שֶׁרָאָה אַהֲרֹן שֶׁקָּרְבוּ כָּל הַקָּרְבָּנוֹת וְנַעֲשׂוּ כָל הַמַּעֲשִׂים וְלֹא יָרְדָה שְׁכִינָה לְיִשְׂרָאֵל, הָיָה מִצְטַעֵר וְאוֹמֵר, יוֹדֵעַ אֲנִי שֶׁכָּעַס הַקָּבָּ\\\"ה עָלַי וּבִשְׁבִילִי לֹא יָרְדָה שְׁכִינָה לְיִשְׂרָאֵל, אָמַר לוֹ לְמֹשֶׁה, מֹשֶׁה אָחִי, כָּךְ עָשִֹיתָ לִי שֶׁנִּכְנַסְתִּי וְנִתְבַּיַּשְׁתִּי? מִיַּד נִכְנַס מֹשֶׁה עִמּוֹ וּבִקְּשׁוּ רַחֲמִים וְיָרְדָה שְׁכִינָה לְיִשְׂרָאֵל (ספרא):\",1,0],[2,128,9,23,\"ויצאו ויברכו את העם. אָמְרוּ וִיהִי נֹעַם ה' אֱלֹהֵינוּ עָלֵינוּ, יְהִי רָצוֹן שֶׁתִּשְׁרֶה שְׁכִינָה בְמַעֲשֵׂה יְדֵיכֶם; לְפִי שֶׁכָּל שִׁבְעַת יְמֵי הַמִּלּוּאִים שֶׁהֶעֱמִידוֹ מֹשֶׁה לַמִּשְׁכָּן וְשִׁמֵּשׁ בּוֹ וּפֵרְקוֹ בְכָל יוֹם לֹא שָׁרְתָה בוֹ שְׁכִינָה, וְהָיוּ יִשְׂרָאֵל נִכְלָמִים וְאוֹמְרִים לְמֹשֶׁה, מֹשֶׁה רַבֵּנוּ, כָּל הַטֹּרַח שֶׁטָּרַחְנוּ שֶׁתִּשְׁרֶה שְׁכִינָה בֵינֵינוּ וְנֵדַע שֶׁנִּתְכַּפֵּר לָנוּ עֲוֹן הָעֵגֶל, לְכָךְ אָמַר לָהֶם זֶה הַדָּבָר אֲשֶׁר צִוָּה ה' תַּעֲשׂוּ וְיֵרָא אֲלֵיכֶם כְּבוֹד ה' — אַהֲרֹן אָחִי כְּדַאי וְחָשׁוּב מִמֶּנִּי, שֶׁעַל יְדֵי קָרְבְּנוֹתָיו וַעֲבוֹדָתוֹ תִשְׁרֶה שְׁכִינָה בָכֶם וְתֵדְעוּ שֶׁהַמָּקוֹם בָּחַר בּוֹ:\",2,0],[2,128,9,24,\"וירנו. כְּתַרְגּוּמוֹ:\",1,0],[2,128,10,2,\"ותצא אש. רַ' אֱלִיעֶזֶר אוֹמֵר לֹא מֵתוּ בְנֵי אַהֲרֹן אֶלָּא עַל יְדֵי שֶׁהוֹרוּ הֲלָכָה בִּפְנֵי מֹשֶׁה רַבָּן, רַבִּי יִשְׁמָעֵאל אוֹמֵר שְׁתוּיֵי יַיִן נִכְנְסוּ לַמִּקְדָּשׁ, תֵּדַע, שֶׁאַחַר מִיתָתָן הִזְהִיר הַנּוֹתָרִים שֶׁלֹּא יִכָּנְסוּ שְׁתוּיֵי יַיִן לַמִּקְדָּשׁ, מָשָׁל לְמֶלֶךְ שֶׁהָיָה לוֹ בֶן בַּיִת וְכוּ', כִּדְאִיתָא בְּוַיִּקְרָא רַבָּה:\",1,0],[2,128,10,3,\"הוא אשר דבר וגו'. הֵיכָן דִּבֵּר? וְנֹעַדְתִּי שָׁמָּה לִבְנֵי יִשְֹרָאֵל וְנִקְדַּשׁ בִּכְבֹדִי (שמות כ\\\"ט), אַל תִּקְרֵי בִּכְבֹדִי אֶלָּא בִּמְכֻבָּדַי; אָמַר לוֹ מֹשֶׁה לְאַהֲרֹן, אַהֲרֹן אָחִי, יוֹדֵעַ הָיִיתִי שֶׁיִּתְקַדֵּשׁ הַבַּיִת בִּמְיֻדָּעָיו שֶׁל מָקוֹם, וְהָיִיתִי סָבוּר אוֹ בִי אוֹ בְךָ, עַכְשָׁיו רוֹאֶה אֲנִי שֶׁהֵם גְּדוֹלִים מִמֶּנִּי וּמִמְּךָ (ספרא):\",1,0],[2,128,10,3,\"וידם אהרן. קִבֵּל שָׂכָר עַל שְׁתִיקָתוֹ, וּמַה שָּׂכָר קִבֵּל? שֶׁנִּתְיַחֵד עִמּוֹ הַדִּבּוּר — שֶׁנֶּאֶמְרָה לוֹ לְבַדּוֹ פָּרָשַׁת שְׁתוּיֵי יַיִן (ויקרא רבה י\\\"ב):\",2,0],[2,128,10,3,\"בקרבי. בִּבְחִירַי:\",3,0],[2,128,10,3,\"ועל פני כל העם אכבד. כְּשֶׁהַקָּבָּ\\\"ה עוֹשֶׂה דִין בַּצַּדִּיקִים מִתְיָרֵא וּמִתְעַלֶּה וּמִתְקַלֵּס, אִם כֵּן בְּאֵלּוּ, כָּל שֶׁכֵּן בָּרְשָׁעִים; וְכֵן הוּא אוֹמֵר נוֹרָא אֱלֹהִים מִמִּקְדָּשֶׁיךָ (תהלים ס\\\"ח), אַל תִּקְרֵי מִמִּקְדָּשֶׁיךָ אֶלָּא מִמְּקֻדָּשֶׁיךָ:\",4,0],[2,128,10,4,\"דד אהרן. עֻזִּיאֵל אֲחִי עַמְרָם הָיָה שֶׁנֶּאֱמַר וּבְנֵי קְהָת וְגוֹ' (שמות ו'):\",1,0],[2,128,10,4,\"שאו את אחיכם וגו'. כְּאָדָם הָאוֹמֵר לַחֲבֵרוֹ, הַעֲבֵר אֶת הַמֵּת מִלִּפְנֵי הַכַּלָּה שֶׁלֹּא לְעַרְבֵּב אֶת הַשִּׂמְחָה:\",2,0],[2,128,10,5,\"בכתנתם. שֶׁל מֵתִים; מְלַמֵּד שֶׁלֹּא נִשְׂרְפוּ בִגְדֵיהֶם אֶלָּא נִשְׁמָתָם, כְּמִין שְׁנֵי חוּטִין שֶׁל אֵשׁ נִכְנְסוּ לְתוֹךְ חָטְמֵיהֶם (ספרא):\",1,0],[2,128,10,6,\"אל תפרעו. אַל תְּגַדְּלוּ שֵׂעָר, מִכָּאן שֶׁאָבֵל אָסוּר בְּתִסְפֹּרֶת, אֲבָל אַתֶּם אַל תְּעַרְבְּבוּ שִׂמְחָתוֹ שֶׁל מָקוֹם (מועד קטן י\\\"ד):\",1,0],[2,128,10,6,\"ולא תמתו. הָא אִם תַּעֲשׂוּ תָּמוּתוּ (ספרא):\",2,0],[2,128,10,6,\"ואחיכם כל בית ישראל. מִכָּאן שֶׁצָּרָתָן שֶׁל תַּלְמִידֵי חֲכָמִים מֻטֶּלֶת עַל הַכֹּל לְהִתְאַבֵּל בָּהּ (מועד קטן כ\\\"ח):\",3,0],[2,128,10,9,\"יין ושכר. יַיִן דֶּרֶךְ שִׁכְרוּתוֹ (ספרא):\",1,0],[2,128,10,9,\"בבאכם אל אהל מועד. אֵין לִי אֶלָּא בְּבֹאֲכֶם לַהֵיכָל, בְּגִשְׁתָּם לַמִּזְבֵּחַ מִנַּיִן? נֶאֱמַר כָּאן בִּיאַת אֹהֶל מוֹעֵד וְנֶאֱמַר בְּקִדּוּשׁ יָדַיִם וְרַגְלַיִם בִּיאַת אֹהֶל מוֹעֵד, מַה לְּהַלָּן עָשָׂה גִישַׁת מִזְבֵּחַ כְּבִיאַת אֹהֶל מוֹעֵד, אַף כָּאן עָשָׂה גִישַׁת מִזְבֵּחַ כְּבִיאַת אֹהֶל מוֹעֵד (שם):\",2,0],[2,128,10,10,\"ולהבדיל. כְּדֵי שֶׁתַּבְדִּילוּ בֵּין עֲבוֹדָה קְדוֹשָׁה לִמְחֻלֶּלֶת, הָא לָמַדְתָּ שֶׁאִם עָבַד עֲבוֹדָתוֹ פְסוּלָה (שם):\",1,0],[2,128,10,11,\"ולהורת. לִמֵּד שֶׁאָסוּר שִׁכּוֹר בְּהוֹרָאָה, יָכוֹל יְהֵא חַיָּב מִיתָה, תַּ\\\"ל אַתָּה וּבָנֶיךָ אִתָּךְ, וְלֹא תָמֻתוּ, כֹּהֲנִים בַּעֲבוֹדָתָם בְּמִיתָה, וְאֵין חֲכָמִים בְּהוֹרָאָתָן בְּמִיתָה (שם):\",1,0],[2,128,10,12,\"הנותרים. מִן הַמִּיתָה, מְלַמֵּד שֶׁאַף עֲלֵיהֶן נִקְנְסָה מִיתָה עַל עֲוֹן הָעֵגֶל, הוּא שֶׁנֶּאֱמַר (דברים ט'), וּבְאַהֲרֹן הִתְאַנַּף ה' מְאֹד לְהַשְׁמִידוֹ, וְאֵין הַשְׁמָדָה אֶלָּא כִלּוּי בָּנִים, שֶׁנֶּאֱמַר (עמוס ב'), וָאַשְׁמִיד פִּרְיוֹ מִמַּעַל, וּתְפִלָּתוֹ שֶׁל מֹשֶׁה בִּטְּלָה מֶחֱצָה, שֶׁנֶּאֱמַר (דברים ט'), וָאֶתְפַּלֵּל גַּם בְּעַד אַהֲרֹן בָּעֵת הַהִיא:\",1,0],[2,128,10,12,\"קחו את המנחה. אַף עַל פִּי שֶׁאַתֶּם אוֹנְנִין וְקָדָשִׁים אֲסוּרִים לְאוֹנֵן:\",2,0],[2,128,10,12,\"את המנחה. זוֹ מִנְחַת שְׁמִינִי וּמִנְחַת נַחְשׁוֹן (ספרא):\",3,0],[2,128,10,12,\"ואכלוה מצות. מַה תַּ\\\"ל? לְפִי שֶׁהִיא מִנְחַת צִבּוּר וּמִנְחַת שָׁעָה וְאֵין כַּיּוֹצֵא בָהּ לְדּוֹרוֹת, הֻצְרַךְ לְפָרֵשׁ בָּהּ דִּין שְׁאָר מְנָחוֹת (שם):\",4,0],[2,128,10,13,\"וחק בניך. אֵין לַבָּנוֹת חֹק בַּקֳּדָשִׁים (שם):\",1,0],[2,128,10,13,\"כי כן צויתי. בַּאֲנִינוּת יֹאכְלוּהָ (שם; זבחים ק\\\"א):\",2,0],[2,128,10,14,\"ואת חזה התנופה. שֶׁל שַׁלְמֵי צִבּוּר.\",1,0],[2,128,10,14,\"תאכלו במקום טהור. וְכִי אֶת הָרִאשׁוֹנִים אָכְלוּ בְּמָקוֹם טָמֵא? אֶלָּא הָרִאשׁוֹנִים שֶׁהֵם קָדְשֵׁי קֳדָשִׁים הֻזְקְקָה אֲכִילָתָם בְּמָקוֹם קָדוֹשׁ, אֲבָל אֵלּוּ אֵין צְרִיכִים תּוֹךְ הַקְּלָעִים אֲבָל צְרִיכִים הֵם לֵאָכֵל תּוֹךְ מַחֲנֵה יִשְׂרָאֵל שֶׁהוּא טָהוֹר מִלִּכָּנֵס שָׁם מְצֹרָעִים; מִכָּאן שֶׁקָּדָשִׁים קַלִּים נֶאֱכָלִין בְּכָל הָעִיר (שם נ\\\"ה):\",2,0],[2,128,10,14,\"אתה ובניך ובנתיך. אַתָּה וּבָנֶיךָ בְּחֵלֶק אֲבָל בְּנוֹתֶיךָ לֹא בְחֵלֶק, אֶלָּא אִם תִּתְּנוּ לָהֶם מַתָּנוֹת רַשָּׁאוֹת הֵן לֶאֱכֹל בְּחָזֶה וְשׁוֹק, אוֹ אֵינוֹ אֶלָּא אַף הַבָּנוֹת בְּחֵלֶק? תַּלְמוּד לוֹמַר כִּי חָקְךָ וְחָק בָּנֶיךָ נִתְּנוּ — חֹק לַבָּנִים וְאֵין חֹק לַבָּנוֹת (ספרא):\",3,0],[2,128,10,15,\"שוק התרומה וחזה התנופה. לשון אשר הונף ואשר הורם. תנופה מוליך ומביא תרומה מעלה ומוריד. ולמה חלקן הכתוב תרומה בשוק ותנופה בחזה. לא ידענו. ששניהם בהרמה והנפה:\",1,0],[2,128,10,15,\"על אשי החלבים. מִכָּאן שֶׁהַחֲלָבִים לְמַטָּה בִּשְׁעַת תְּנוּפָה, וְיִשּׁוּב הַמִּקְרָאוֹת שֶׁלֹּא יַכְחִישׁוּ זֶה אֶת זֶה כְּבָר פֵּרַשְׁתִּי אֶת שְׁלָשְׁתָּן בְּצַו אֶת אַהֲרֹן:\",2,0],[2,128,10,16,\"שעיר החטאת. שְׂעִיר מוּסְפֵי רֹאשׁ חֹדֶשׁ; וּשְׁלֹשָׁה שְׂעִירֵי חַטָּאוֹת קָרְבוּ בוֹ בַיּוֹם, שְׂעִיר עִזִּים וּשְׂעִיר נַחְשׁוֹן וּשְׂעִיר רֹאשׁ חֹדֶשׁ, וּמִכֻּלָּן לֹא נִשְׂרַף אֶלָּא זֶה; וְנֶחְלְקוּ בַדָּבָר חַכְמֵי יִשְֹרָאֵל, יֵשׁ אוֹמְרִים מִפְּנֵי הַטֻּמְאָה שֶׁנָּגְעָה בוֹ נִשְׂרַף, וְיֵשׁ אוֹמְרִים מִפְּנֵי אֲנִינוּת נִשְׂרַף, לְפִי שֶׁהוּא קָדְשֵׁי דוֹרוֹת, אֲבָל בְּקָדְשֵׁי שָׁעָה סָמְכוּ עַל מֹשֶׁה שֶׁאָמַר לָהֶם בַּמִּנְחָה וְאִכְלוּהָ מַצּוֹת (ספרא; זבחים ק\\\"א):\",1,0],[2,128,10,16,\"דרש דרש. שְׁתֵּי דְרִישׁוֹת: מִפְּנֵי מָה נִשְׂרַף זֶה? וּמִפְּנֵי מָה נֶאֶכְלוּ אֵלּוּ? כָּךְ הִיא בְּתוֹרַת כֹּהֲנִים:\",2,0],[2,128,10,16,\"על אלעזר ועל איתמר. בִּשְׁבִיל כְּבוֹדוֹ שֶׁל אַהֲרֹן הָפַךְ פָּנָיו כְּנֶגֶד הַבָּנִים וְכָעַס (ספרא):\",3,0],[2,128,10,16,\"לאמר. אָמַר לָהֶם הֲשִׁיבוּנִי עַל דְּבָרַי (שם):\",4,0],[2,128,10,17,\"מדוע לא אכלתם את החטאת במקום הקדש. וְכִי חוּץ לַקֹּדֶשׁ אֲכָלוּהָ, וַהֲלֹא שְׂרָפוּהָ, וּמַה הוּא אוֹמֵר בִּמְקוֹם הַקֹּדֶשׁ, אֶלָּא אָמַר לָהֶם שֶׁמָּא חוּץ לַקְּלָעִים יָצְאָה וְנִפְסְלָה:\",1,0],[2,128,10,17,\"כי קדש קדשים הוא. וְנִפְסֶלֶת בְּיוֹצֵא, וְהֵם אָמְרוּ לוֹ לָאו. אָמַר לָהֶם הוֹאִיל וּבִמְקוֹם הַקֹּדֶשׁ הָיְתָה, מַדּוּעַ לֹא אֲכַלְתֶּם אוֹתָהּ:\",2,0],[2,128,10,17,\"ואתה נתן לכם לשאת וגו'. שֶׁהַכֹּהֲנִים אוֹכְלִים וּבְעָלִים מִתְכַּפְּרִים:\",3,0],[2,128,10,17,\"לשאת את עון העדה. מִכָּאן לָמַדְנוּ שֶׁשְּׂעִיר רֹאשׁ חֹדֶשׁ הָיָה, שֶׁהוּא מְכַפֵּר עַל עֲוֹן טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו, שֶׁחַטַּאת שְׁמִינִי וְחַטַּאת נַחְשׁוֹן לֹא לְכַפָּרָה בָּאוּ:\",4,0],[2,128,10,18,\"הן לא הובא וגו'. שֶׁאִלּוּ הוּבָא, הָיָה לָכֶם לְשָֹרְפָהּ, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא ו'), וְכָל חַטָּאת אֲשֶׁר יוּבָא מִדָּמָהּ וְגוֹ' (פסחים פ\\\"ב):\",1,0],[2,128,10,18,\"אכל תאכלו אתה. הָיָה לָכֶם לְאָכְלָהּ אַף עַל פִּי שֶׁאַתֶּם אוֹנְנִים:\",2,0],[2,128,10,18,\"כאשר צויתי. לָכֶם בַּמִּנְחָה:\",3,0],[2,128,10,19,\"וידבר אהרן. אֵין לְשׁוֹן דִּבּוּר אֶלָּא לְשׁוֹן עַז, שֶׁנֶּאֱמַר וַיְדַבֵּר הָעָם וְגוֹ' (במדבר כ\\\"א), אֶפְשָׁר מֹשֶׁה קָצַף עַל אֶלְעָזָר וְעַל אִיתָמָר וְאַהֲרֹן מְדַבֵּר? הָא יָדַעְתָּ שֶׁלֹּא הָיְתָה אֶלָּא מִדֶּרֶךְ כָּבוֹד; אָמְרוּ: אֵינוֹ בַדִּין שֶׁיְּהֵא אָבִינוּ יוֹשֵׁב וְאָנוּ מְדַבְּרִים לְפָנָיו, וְאֵינוֹ בַדִּין שֶׁיְּהֵא תַלְמִיד מֵשִׁיב אֶת רַבּוֹ; יָכוֹל מִפְּנֵי שֶׁלֹּא הָיָה בְאֶלְעָזָר לְהָשִׁיב? תַּ\\\"ל וַיֹּאמֶר אֶלְעָזָר הַכֹּהֵן אֶל אַנְשֵׁי הַצָּבָא וְגוֹמֵר (שם ל\\\"א), הֲרֵי כְּשֶׁרָצָה, דִּבֵּר לִפְנֵי מֹשֶׁה וְלִפְנֵי הַנְּשִֹיאִים, זוֹ מָצָאתִי בְּסִפְרֵי שֶׁל פָּנִים שֵׁנִי:\",1,0],[2,128,10,19,\"הן היום הקריבו. מַהוּ אוֹמֵר? אֶלָּא אָמַר לוֹ מֹשֶׁה: שֶׁמָּא זְרַקְתֶּם דָּמָהּ אוֹנְנִין, שֶׁאוֹנֵן שֶׁעָבַד חִלֵּל? אָמַר לוֹ אַהֲרֹן וְכִי הֵם הִקְרִיבוּ שֶׁהֵם הֶדְיוֹטוֹת? אֲנִי הִקְרַבְתִּי שֶׁאֲנִי כֹהֵן גָּדוֹל וּמַקְרִיב אוֹנֵן (זבחים ק\\\"א):\",2,0],[2,128,10,19,\"ותקראנה אתי כאלה. אֲפִלוּ לֹא הָיוּ הַמֵּתִים בָּנַי, אֶלָּא שְׁאָר קְרוֹבִים שֶׁאֲנִי חַיָּב לִהְיוֹת אוֹנֵן עֲלֵיהֶם כְּאֵלּוּ, כְּגוֹן כָּל הָאֲמוּרִים בְּפָרָשַׁת כֹּהֲנִים שֶׁהַכֹּהֵן מִטַּמֵּא לָהֶם (ספרא).\",3,0],[2,128,10,19,\"ואכלתי חטאת. וְאִם אָכַלְתִּי הייטב וגו':\",4,0],[2,128,10,19,\"היום. אֲבָל אֲנִינוּת לַיְלָה מֻתָּר, שֶׁאֵין אוֹנֵן אֶלָּא יוֹם קְבוּרָה (ספרא; זבחים ק'):\",5,0],[2,128,10,19,\"הייטב בעיני ה'. אִם שָׁמַעְתָּ בְּקָדְשֵׁי שָׁעָה אֵין לְךָ לְהָקֵל בְּקָדְשֵׁי דוֹרוֹת:\",6,0],[2,128,10,20,\"וייטב בעיניו. הוֹדָה וְלֹא בוֹשׁ לוֹמַר לֹא שָׁמַעְתִּי (זבחים ק\\\"א):\",1,0],[2,128,11,1,\"אל משה ואל אהרן. לְמֹשֶׁה אָמַר שֶׁיֹּאמַר לְאַהֲרֹן:\",1,0],[2,128,11,1,\"לאמר אלהם. אָמַר שֶׁיֹּאמַר לְאֶלְעָזָר וּלְאִיתָמָר; אוֹ אֵינוֹ אֶלָּא לֵאמֹר לְיִשְֹרָאֵל? כְּשֶׁהוּא אוֹמֵר דַּבְּרוּ אֶל בְּנֵי יִשְֹרָאֵל הֲרֵי דִּבּוּר אָמוּר לְיִשְֹרָאֵל, הָא מָה אֲנִי מְקַיֵּם לֵאמֹר אֲלֵהֶם? לַבָּנִים — לְאֶלְעָזָר וּלְאִיתָמָר (ספרא):\",2,0],[2,128,11,2,\"דברו אל בני ישראל. אֶת כֻּלָּם הִשְׁוָה לִהְיוֹת שְׁלוּחִים בְּדִבּוּר זֶה, לְפִי שֶׁהֻשְׁווּ בַּדְּמִימָה וְקִבְּלוּ עֲלֵיהֶם גְּזֵרַת הַמָּקוֹם מֵאַהֲבָה:\",1,0],[2,128,11,2,\"זאת החיה. לְשׁוֹן חַיִּים, לְפִי שֶׁיִּשְֹרָאֵל דְּבוּקִים בַּמָּקוֹם וּרְאוּיִין לִהְיוֹת חַיִּים, לְפִיכָךְ הִבְדִּילָם מִן הַטֻּמְאָה וְגָזַר עֲלֵיהֶם מִצְוֹת, וְלָאֻמּוֹת לֹא אָסַר כְּלוּם, מָשָׁל לְרוֹפֵא שֶׁנִּכְנַס לְבַקֵּר אֶת הַחוֹלֶה כּוּ' כִּדְאִיתָא בְּמִדְרַשׁ רַבִּי תַנְחוּמָא:\",2,0],[2,128,11,2,\"זאת החיה. מְלַמֵּד שֶׁהָיָה מֹשֶׁה אוֹחֵז בַּחַיָּה וּמַרְאֶה אוֹתָהּ לְיִשְֹרָאֵל זֹאת תֹּאכְלוּ וְזֹאת לֹא תֹאכְלוּ (חולין מ\\\"ב), אֶת זֶה תֹּאכְלוּ וְגוֹ' (פסוק ט'), אַף בְּשִׁרְצֵי הַמַּיִם אָחַז מִכָּל מִין וָמִין וְהֶרְאָה לָהֶם, וְכֵן בָּעוֹף וְאֶת אֵלֶּה תְּשַׁקְּצוּ מִן הָעוֹף (פסוק י\\\"ג), וְכֵן בַּשְּׁרָצִים וְזֶה לָכֶם הַטָּמֵא (פסוק כ\\\"ט):\",3,0],[2,128,11,2,\"זאת החיה … מכל הבהמה. מְלַמֵּד שֶׁהַבְּהֵמָה בִּכְלַל חַיָּה (ספרא; חולין ע'):\",4,0],[2,128,11,3,\"מפרסת. כְּתַרְגּוּמוֹ סְדִיקָא:\",1,0],[2,128,11,3,\"פרסה. פלנט\\\"א בְּלַעַז:\",2,0],[2,128,11,3,\"ושסעת שסע. שֶׁמֻּבְדֶּלֶת מִלְּמַעְלָה וּמִלְּמַטָּה בִּשְׁתֵּי צִפָּרְנִַין, כְּתַרְגּוּמוֹ וּמַטִּלְּפָן טִלְפִין, שֶׁיֵּשׁ שֶׁפַּרְסוֹתָיו סְדוּקוֹת מִלְּמַעְלָה וְאֵין שְׁסוּעוֹת וּמֻבְדָּלוֹת לְגַמְרֵי, שֶׁמִּלְּמַטָּה מְחֻבָּרוֹת:\",3,0],[2,128,11,3,\"מעלת גרה. מַעֲלָה וּמְקִיאָה הָאֹכֶל מִמֵּעֶיהָ וּמַחֲזֶרֶת אוֹתוֹ לְתוֹךְ פִּיהָ לְכָתְשׁוֹ וּלְטָחֳנוֹ הָדֵק:\",4,0],[2,128,11,3,\"גרה. כָּךְ שְׁמוֹ; וְיִתָּכֵן לִהְיוֹת מִגִּזְרַת מַיִם הַנִּגָּרִים (שמואל ב י\\\"ד), שֶׁהוּא נִגְרָר אַחַר הַפֶּה; וְתַרְגּוּמוֹ פִשְׁרָא, שֶׁעַל יְדֵי הַגֵּרָה הָאֹכֶל נִפְשָׁר וְנִמּוֹחַ:\",5,0],[2,128,11,3,\"בבהמה. תֵּיבָה יְתֵרָה הִיא לִדְרָשָׁה — לְהַתִּיר אֶת הַשְּׁלִיל הַנִּמְצָא בִמְעֵי אִמּוֹ (ספרא; חולין ס\\\"ט):\",6,0],[2,128,11,3,\"אתה תאכלו. וְלֹא בְהֵמָה טְמֵאָה, וַהֲלֹא בְאַזְהָרָה הִיא? אֶלָּא לַעֲבֹר עָלֶיהָ בַּעֲשֵׂה וְלֹא תַעֲשֶׂה (ספרא; זבחים ל\\\"ד):\",7,0],[2,128,11,8,\"מבשרם לא תאכלו. אֵין לִי אֶלָּא אֵלּוּ, שְׁאָר בְּהֵמָה טְמֵאָה שֶׁאֵין לָהּ שׁוּם סִימָן טָהֳרָה מִנַּיִן? אָמַרְתָּ קַל וָחֹמֶר, וּמָה אֵלּוּ שֶׁיֵּשׁ בָּהֶן קְצָת סִימָנֵי טָהֳרָה אֲסוּרוֹת וְכוּ' (ספרא):\",1,0],[2,128,11,8,\"מבשרם. עַל בְּשָׂרָם בְּאַזְהָרָה וְלֹא עַל עֲצָמוֹת וְגִידִין וְקַרְנַיִם וּטְלָפַיִם (שם):\",2,0],[2,128,11,8,\"ובנבלתם לא תגעו. יָכוֹל יְהוּ יִשְׂרָאֵל מֻזְהָרִים עַל מַגַּע נְבֵלָה, תַּ\\\"ל אֱמֹר אֶל הַכֹּהֲנִים וְגוֹ' — כֹּהֲנִים מֻזְהָרִין וְאֵין יִשְׂרָאֵל מֻזְהָרִין — קַל וָחֹמֶר מֵעַתָּה: וּמַה טֻּמְאַת מֵת חֲמוּרָה לֹא הִזְהִיר בָּהּ אֶלָּא כֹּהֲנִים, טֻמְאַת נְבֵלָה קַלָּה לֹא כָל שֶׁכֵּן, וּמַה תַּלְמוּד לוֹמַר לֹא תִגָּעוּ? בָּרֶגֶל (שם; ראש השנה ט\\\"ז):\",3,0],[2,128,11,9,\"סנפיר. אֵלּוּ שֶׁשָּׁט בָּהֶם (חולין נ\\\"ט):\",1,0],[2,128,11,9,\"קשקשת. אֵלּוּ קְלִפִּין הַקְּבוּעִים בּוֹ (כְּמוֹ שֶׁנֶּאֱמַר (שמואל א י\\\"ז), וְשִׁרְיוֹן קַשְׂקַשִּׂים הוּא לָבוּשׁ):\",2,0],[2,128,11,10,\"שרץ. בְּכָל מָקוֹם מַשְׁמָעוֹ דָּבָר נָמוּךְ שֶׁרוֹחֵשׁ וְנָד עַל הָאָרֶץ:\",1,0],[2,128,11,11,\"ושקץ יהיו. לֶאֱסֹר אֶת עֵרוּבֵיהֶן אִם יֵשׁ בָּהֶם בְּנוֹתֵן טַעַם (ספרא):\",1,0],[2,128,11,11,\"מבשרם. אֵינוֹ מוּזְהָר עַל הַסְּנַפִּירִים וְעַל הָעֲצָמוֹת (שם):\",2,0],[2,128,11,11,\"ואת נבלתם תשקצו. לְרַבּוֹת יַבְחוּשִׁין שֶׁסִּנְּנָן; יַבְחוּשִׁין מושיירונ\\\"ש בלע\\\"ז (חולין ס\\\"ז):\",3,0],[2,128,11,12,\"כל אשר אין לו וגו'. מַה תַּ\\\"ל? שֶׁיָּכוֹל אֵין לִי שֶׁיְּהֵא מֻתָּר אֶלָּא הַמַּעֲלֶה סִימָנִין שֶׁלּוֹ לַיַּבָּשָׁה, הִשִּׁירָן בַּמַּיִם מִנַּיִן? תַּ\\\"ל כֹּל אֲשֶׁר אֵין לוֹ סְנַפִּיר וְקַשְׂקֶשֶׂת בַּמַּיִם, הָא אִם הָיוּ לוֹ בַּמַּיִם אַף עַל פִּי שֶׁהִשִּׁירָן בַּעֲלִיָּתוֹ מֻתָּר (ספרא):\",1,0],[2,128,11,13,\"לא יאכלו. לְחַיֵּב אֶת הַמַּאֲכִילָן לִקְטַנִּים, שֶׁכָּךְ מַשְׁמָעוֹ לֹא יְהוּ נֶאֱכָלִין עַל יָדְךָ, אוֹ אֵינוֹ אֶלָּא לְאָסְרָן בַּהֲנָאָה? תַּ\\\"ל לֹא תֹאכְלוּם — בַּאֲכִילָה אֲסוּרִין בַּהֲנָאָה מֻתָּרִין; כָּל עוֹף שֶׁנֶּאֱמַר בּוֹ לְמִינָהּ, לְמִינוֹ, לְמִינֵהוּ, יֵשׁ בְּאוֹתוֹ הַמִּין שֶאֵין דּוֹמִין זֶה לָזֶה לֹא בְמַרְאֵיהֶם וְלֹא בִשְׁמוֹתָם וְכֻלָּן מִין אֶחָד:\",1,0],[2,128,11,16,\"הנץ. אשפר\\\"ויר:\",1,0],[2,128,11,17,\"שלך. פֵּרְשׁוּ רַבּוֹתֵינוּ זֶה הַשּׁוֹלֶה דָגִים מִן הַיָּם, וְזֶה שֶׁתִּרְגֵּם אֻנְקְלוֹס וְשָׁלֵי נוּנָא (חולין ס\\\"ג):\",1,0],[2,128,11,17,\"כוס וינשוף. הֵם צואי\\\"טש הַצּוֹעֲקִים בַּלַּיְלָה, וְיֵשׁ לָהֶם לְסָתוֹת כְּאָדָם, וְעוֹד אַחֵר דּוֹמֶה לוֹ שֶׁקּוֹרִין יי\\\"בו:\",2,0],[2,128,11,18,\"תנשמת. הִיא קלב\\\"א ש\\\"וריץ, וְדוֹמָה לְעַכְבָּר הַפּוֹרַחַת בַּלַּיְלָה, וְתִנְשֶׁמֶת הָאֲמוּרָה בַּשְּׁרָצִים הִיא דוֹמָה לָהּ וְאֵין לָהּ עֵינַיִם, וְקוֹרִין לָהּ טלפ\\\"א:\",1,0],[2,128,11,19,\"החסידה. זוֹ דַיָּה לְבָנָה, ציגוני\\\"א, וְלָמָּה נִקְרָא שְׁמָהּ חֲסִידָה? שֶׁעוֹשָֹׁה חֲסִידוּת עִם חַבְרוֹתֶיהָ בִּמְזוֹנוֹת (שם):\",1,0],[2,128,11,19,\"האנפה. הִיא דַיָּה רַגְזָנִית, וְנִרְאֶה לִי שֶׁקּוֹרִין אוֹתוֹ הי\\\"רון:\",2,0],[2,128,11,19,\"הדוכיפת. תַּרְנְגוֹל הַבָּר, וְכַרְבָּלְתּוֹ כְפוּלָה, וּבְלַעַז הרופ\\\"א, וְלָמָּה נִקְרָא שְׁמוֹ דּוּכִיפַת? שֶׁ\\\"הוֹדוֹ כָפוּת\\\" וְזוֹ הִיא כַּרְבָּלְתוֹ, וְנַגַּר טוּרָא נִקְרָא עַל שֵׁם מַעֲשָׂיו, כְּמוֹ שֶׁפֵּרְשׁוּ רַבּוֹתֵינוּ בְּמַסֶּכֶת גִּטִּין בְּפֶרֶק מִי שֶׁאֲחָזוֹ (גיטין דף ס\\\"ח):\",3,0],[2,128,11,20,\"שרץ העוף. הֵם הַדַּקִּים הַנְּמוּכִים הָרוֹחֲשִׁין עַל הָאָרֶץ, כְּגוֹן זְבוּבִים וּצְרָעִין וְיַתּוּשִׁין וַחֲגָבִים:\",1,0],[2,128,11,21,\"על ארבע. עַל אַרְבַּע רַגְלָיִם:\",1,0],[2,128,11,21,\"ממעל לרגליו. סָמוּךְ לְצַוָּארוֹ יֵשׁ לוֹ כְּמִין שְׁתֵּי רַגְלַיִם לְבַד אַרְבַּע רַגְלָיו, וּכְשֶׁרוֹצֶה לָעוּף וְלִקְפֹּץ מִן הָאָרֶץ מִתְחַזֵּק בְּאוֹתָן שְׁנֵי כְרָעַיִם וּפוֹרֵחַ, וְיֵשׁ הַרְבֵּה — כְּאוֹתָן שֶׁקּוֹרִין לנגו\\\"שטא — אֲבָל אֵין אָנוּ בְקִיאִין בָּהֶן, שֶׁאַרְבָּעָה סִימָנֵי טָהֳרָה נֶאֶמְרוּ בָהֶם אַרְבַּע רַגְלַיִם וְאַרְבַּע כְּנָפַיִם וְקַרְסוּלִין — אֵלּוּ כְרָעַיִם הַכְּתוּבִים כָּאן — וּכְנָפָיו חוֹפִין אֶת רֻבּוֹ, וְכָל סִימָנִין הַלָּלוּ מְצוּיִים בְּאוֹתָן שֶׁבֵּינוֹתֵינוּ, אֲבָל יֵשׁ שֶׁרֹאשָׁן אָרֹךְ וְיֵשׁ שֶׁאֵין לָהֶם זָנָב, וְצָרִיךְ שֶׁיְּהֵא שְׁמוֹ חָגָב, וּבָזֶה אֵין אָנוּ יוֹדְעִים לְהַבְדִּיל בֵּינֵיהֶן:\",2,0],[2,128,11,23,\"וכל שרץ העוף וגו'. בָּא וְלִמֵּד שֶׁאִם יֵשׁ לוֹ חָמֵשׁ טָהוֹר (ספרא):\",1,0],[2,128,11,24,\"ולאלה. הָעֲתִידִין לֵאָמֵר בָּעִנְיָן לְמַטָּה.\",1,0],[2,128,11,24,\"תטמאו. כְּלוֹמַר בִּנְגִיעָתָם יֵשׁ טֻמְאָה:\",2,0],[2,128,11,25,\"וכל הנשא מנבלתם. כָּל מָקוֹם שֶׁנֶּאֶמְרָה טֻמְאַת מַשָּׂא, חֲמוּרָה מִטֻּמְאַת מַגָּע, שֶׁהִיא טְעוּנָה כִבּוּס בְּגָדִים (ספרא):\",1,0],[2,128,11,26,\"מפרסת פרסה ושסע איננה שסעת. כְּגוֹן גָּמָל, שֶׁפַּרְסָתוֹ סְדוּקָה לְמַעְלָה אֲבָל לְמַטָּה הִיא מְחֻבֶּרֶת, כָּאן לִמֶּדְךָ שֶׁנִּבְלַת בְּהֵמָה טְמֵאָה מְטַמְּאָה, וּבָעִנְיָן שֶׁבְּסוֹף הַפָּרָשָׁה פֵּרֵשׁ עַל בְּהֵמָה טְהוֹרָה:\",1,0],[2,128,11,27,\"על כפיו. כְּגוֹן כֶּלֶב וְדֹב וְחָתוּל:\",1,0],[2,128,11,27,\"טמאים הם לכם. לְמַגָּע:\",2,0],[2,128,11,29,\"וזה לכם הטמא. כָּל טֻמְאוֹת הַלָּלוּ אֵינָן לְאִסּוּר אֲכִילָה אֶלָּא לְטֻמְאָה מַמָּשׁ — לִהְיוֹת טָמֵא בְּמַגָּעָן, וְנֶאֱסַר לֶאֱכֹל תְּרוּמָה וְקָדָשִׁים וְלִכָּנֵס בַּמִּקְדָּשׁ:\",1,0],[2,128,11,29,\"החלד. מוש\\\"טילא:\",2,0],[2,128,11,29,\"והצב. פויי\\\"ט שֶׁדּוֹמֶה לִצְפַרְדֵּעַ:\",3,0],[2,128,11,30,\"אנקה. הרי\\\"ון:\",1,0],[2,128,11,30,\"הלטאה. לישרד\\\"ה:\",2,0],[2,128,11,30,\"חמט. לימצ\\\"א:\",3,0],[2,128,11,30,\"תנשמת. טל\\\"פא:\",4,0],[2,128,11,32,\"במים יובא. וְאַף לְאַחַר טְבִילָתוֹ טָמֵא הוּא לִתְרוּמָה:\",1,0],[2,128,11,32,\"עד הערב. וְאַחַ\\\"כַּ וטהר בְּהַעֲרֵב הַשֶּׁמֶשׁ:\",2,0],[2,128,11,33,\"אל תוכו. אֵין כְּלִי חֶרֶס מִטַּמֵּא אֶלָּא מֵאֲוִירוֹ (חולין כ\\\"ד):\",1,0],[2,128,11,33,\"כל אשר בתוכו יטמא. הַכְּלִי חוֹזֵר וּמְטַמֵּא מַה שֶּׁבַּאֲוִירוֹ:\",2,0],[2,128,11,33,\"ואתו תשברו. לִמֵּד שֶׁאֵין לוֹ טָהֳרָה בַּמִּקְוֶה:\",3,0],[2,128,11,34,\"מכל האכל אשר יאכל. מוּסָב עַל מִקְרָא הָעֶלְיוֹן: \\\"כל אשר בתוכו יטמא מִכָּל הָאֹכֶל אֲשֶׁר יֵאָכֵל\\\" אֲשֶׁר בָּאוּ עָלָיו מַיִם וְהוּא בְּתוֹךְ כְּלִי חֶרֶס הַטָּמֵא יִטְמָא (וְכֵן כָּל מַשְׁקֶה אֲשֶׁר יִשָּׁתֶה בְּכָל כְּלִי וְהוּא בְּתוֹךְ כְּלִי חֶרֶס הַטָּמֵא יִטְמָא). לָמַדְנוּ מִכָּאן דְּבָרִים הַרְבֵּה, לָמַדְנוּ שֶׁאֵין אֹכֶל מֻכְשָׁר וּמְתֻקָּן לְקַבֵּל טֻמְאָה עַד שֶׁיָּבֹאוּ עָלָיו מַיִם פַּעַם אַחַת, וּמִשֶּׁבָּאוּ עָלָיו מַיִם פַּעַם אַחַת מְקַבֵּל טֻמְאָה לְעוֹלָם וַאֲפִלוּ נָגוּב, וְהַיַּיִן וְהַשֶּׁמֶן וְכָל הַנִּקְרָא מַשְׁקֶה מַכְשִׁיר זְרָעִים לְטֻמְאָה כַּמַּיִם, שֶׁכָּךְ יֵשׁ לִדְרֹשׁ הַמִּקְרָא: אֲשֶׁר יָבֹא עָלָיו מַיִם אוֹ כָל מַשְׁקֶה אֲשֶׁר יִשָּׁתֶה בְּכָל כְּלִי, יִטְמָא הָאֹכֶל, וְעוֹד לָמְדוּ רַבּוֹתֵינוּ מִכָּאן שֶׁאֵין וְלַד הַטֻּמְאָה מְטַמֵּא כֵלִים שֶׁכָּךְ שָׁנִינוּ (פסחים פ'), יָכוֹל יְהוּ כָל הַכֵּלִים מִטַּמְּאִין מֵאֲוִיר כְּלִי חֶרֶס תַּ\\\"ל כֹּל אֲשֶׁר בְּתוֹכוֹ יִטְמָא מִכָּל הָאֹכֶל — אֹכֶל (וּמַשְׁקֶה) מִטַּמֵּא מֵאֲוִיר כְּלִי חֶרֶס וְאֵין כָּל הַכֵּלִים מִטַּמְּאִין מֵאֲוִיר כְּלִי חֶרֶס — לְפִי שֶׁהַשֶּׁרֶץ אַב הַטֻּמְאָה וְהַכְּלִי שֶׁנִּטְמָא מִמֶּנּוּ וְלַד הַטֻּמְאָה, לְפִיכָךְ אֵינוֹ חוֹזֵר וּמְטַמֵּא כֵלִים שֶׁבְּתוֹכוֹ, וְלָמַדְנוּ עוֹד שֶׁהַשֶּׁרֶץ שֶׁנָּפַל לַאֲוִיר הַתַּנּוּר וְהַפַּת בְּתוֹכוֹ וְלֹא נָגַע הַשֶּׁרֶץ בַּפַּת, הַתַּנּוּר רִאשׁוֹן וְהַפַּת שְׁנִיָּה, וְלֹא נֹאמַר רוֹאִין אֶת הַתַּנּוּר כְּאִלּוּ מָלֵא טֻמְאָה וּתְהֵא הַפַּת תְּחִלָּה, שֶׁאִם אַתָּה אוֹמֵר כֵּן, לֹא נִתְמַעֲטוּ כָל הַכֵּלִים מִלִּטַּמֵּא מֵאֲוִיר כְּלִי חֶרֶס, שֶׁהֲרֵי טֻמְאָה עַצְמָהּ נָגְעָה בָּהֶן מִגַּבָּן, וְלָמַדְנוּ עוֹד עַל בִּיאַת מַיִם שֶׁאֵינָהּ מַכְשֶׁרֶת זְרָעִים אֶלָּא אִם כֵּן נָפְלוּ עֲלֵיהֶן מִשֶּׁנִּתְלְשׁוּ, שֶׁאִם אַתָּה אוֹמֵר מְקַבְּלִין הֶכְשֵׁר בִּמְחֻבָּר, אֵין לְךָ שֶׁלֹּא בָאוּ עָלָיו מַיִם, וּמַהוּ אוֹמֵר אֲשֶׁר יָבֹא עָלָיו מַיִם? וְלָמַדְנוּ עוֹד שֶׁאֵין אֹכֶל מְטַמֵּא אֲחֵרִים אֶלָּא אִם כֵּן יֵשׁ בּוֹ כַּבֵּיצָה, שֶׁנֶּאֱמַר אֲשֶׁר \\\"יֵאָכֵל\\\" — אֹכֶל הַנֶּאֱכָל בְּבַת אֶחָת, וְשִׁעֲרוּ חֲכָמִים אֵין בֵּית הַבְּלִיעָה מַחֲזִיק יוֹתֵר מִבֵּיצַת תַּרְנְגֹלֶת (ספרא; יומא פ'):\",1,0],[2,128,11,35,\"תנור וכירים. כֵּלִים הַמִּטַּלְטְלִין הֵם, וְהֵן שֶׁל חֶרֶס וְיֵשׁ לָהֶן תָּוֶךְ, וְשׁוֹפֵת עַל נֶקֶב הֶחָלָל אֶת הַקְּדֵרָה, וּשְׁנֵיהֶם פִּיהֶם לְמַעְלָה:\",1,0],[2,128,11,35,\"יתץ. שֶׁאֵין לִכְלֵי חֶרֶס טָהֳרָה בִּטְבִילָה:\",2,0],[2,128,11,35,\"וטמאים יהיו לכם. שֶׁלֹּא תֹאמַר מְצֻוֶּה אֲנִי לְנָתְצָם, תַּלְמוּד לוֹמַר וּטְמֵאִים יִהְיוּ לָכֶם — אִם רָצָה לְקַיְּמָן בְּטֻמְאָתָן רַשַּׁאי:\",3,0],[2,128,11,36,\"אך מעין ובור מקוה מים. הַמְחֻבָּרִים לַקַּרְקַע אֵין מְקַבְּלִין טֻמְאָה, וְעוֹד יֵשׁ לְךָ לִלְמֹד, יהיה טהור — הַטּוֹבֵל בָּהֶם מִטֻּמְאָתוֹ:\",1,0],[2,128,11,36,\"ונגע בנבלתם יטמא. אֲפִלּוּ הוּא בְּתוֹךְ מַעְיָן וּבוֹר וְנוֹגֵעַ בְּטֻמְאָתָם יִטְמָא; שֶׁלֹּא תֹאמַר קַל וָחֹמֶר: אִם מְטַהֵר אֶת הַטְּמֵאִים מִטֻּמְאָתָם קַל וָחֹמֶר שֶׁיַּצִּיל אֶת הַטָּהוֹר מִלִּטַּמֵּא לְכָךְ נֶאֱמַר וְנֹגֵעַ בְּנִבְלָתָם יִטְמָא (נדרים ע\\\"ה):\",2,0],[2,128,11,37,\"זרע זרוע. זְרִיעָה שֶׁל מִינֵי זֵרְעוֹנִין; זֵרוּעַ שֵׁם דָּבָר הוּא, כְּמוֹ וְיִתְּנוּ לָנוּ מִן הַזֵּרֹעִים (דניאל א'):\",1,0],[2,128,11,37,\"טהור הוא. לִמֶּדְךָ הַכָּתוּב שֶׁלֹּא הֻכְשַׁר וְנִתְקַן לִקָּרוֹת אֹכֶל לְקַבֵּל טֻמְאָה עַד שֶׁיָּבֹאוּ עָלָיו מָיִם:\",2,0],[2,128,11,38,\"וכי יתן מים על זרע. לְאַחַר שֶׁנִּתְלַשׁ, שֶׁאִם תֹּאמַר יֵשׁ הֶכְשֵׁר בִּמְחֻבָּר, אֵין לְךָ זֶרַע שֶׁלֹּא הֻכְשָׁר (חולין קי\\\"ח):\",1,0],[2,128,11,38,\"מים על זרע. בֵּין מַיִם בֵּין שְׁאָר מַשְׁקִין, בֵּין הֵם עַל הַזֶּרַע בֵּין זֶרַע נוֹפֵל לְתוֹכָן, הַכֹּל נִדְרָשׁ בְּתוֹרַת כֹּהֲנִים:\",2,0],[2,128,11,38,\"ונפל מנבלתם עליו. אַף מִשֶּׁנֻּגַּב מִן הַמַּיִם, שֶׁלֹּא הִקְפִּידָה תוֹרָה אֶלָּא לִהְיוֹת עָלָיו שֵׁם אֹכֶל, וּמִשֶּׁיָּרַד לוֹ הֶכְשֵׁר קַבָּלַת טֻמְאָה פַּעַם אַחַת, שׁוּב אֵינוֹ נֶעֱקָר הֵימֶנּוּ:\",3,0],[2,128,11,39,\"בנבלתה. וְלֹא בָעֲצָמוֹת וְגִידִין וְלֹא בַקַּרְנַיִם וּטְלָפַיִם וְלֹא בָעוֹר (ספרא):\",1,0],[2,128,11,40,\"והנשא את נבלתה. חֲמוּרָה טֻמְאַת מַשָּׂא מִטֻּמְאַת מַגָּע, שֶׁהַנּוֹשֵׂא מְטַמֵּא בְגָדִים, וְהַנּוֹגֵעַ אֵין בְּגָדָיו טְמֵאִין, שֶׁלֹּא נֶאֱמַר בּוֹ יְכַבֵּס בְּגָדָיו:\",1,0],[2,128,11,40,\"והאכל מנבלתה. יָכוֹל תְּטַמְּאֶנּוּ אֲכִילָתוֹ? כְּשֶׁהוּא אוֹמֵר בְּנִבְלַת עוֹף טָהוֹר (ויקרא כ\\\"ב) \\\"נְבֵלָה וּטְרֵפָה לֹא יֹאכַל לְטָמְאָה בָהּ\\\", בָהּ — אוֹתָהּ מְטַמָּא בְגָדִים בַּאֲכִילָתָהּ וְאֵין נִבְלַת בְּהֵמָה מְטַמָּא בְגָדִים בַּאֲכִילָתָהּ בְּלֹא מַשָּׂא, כְּגוֹן אִם תְּחָבָהּ לוֹ חֲבֵרוֹ בְּבֵית הַבְּלִיעָה, אִם כֵּן מַה תַּ\\\"ל הָאֹכֵל? לִתֵּן שִׁעוּר לַנּוֹשֵׂא וְלַנּוֹגֵעַ כְּדֵי אֲכִילָה, וְהוּא כַּזַּיִת (ספרא; נדה מ\\\"ב):\",2,0],[2,128,11,40,\"וטמא עד הערב. אַף עַל פִּי שֶׁטָּבַל צָרִיךְ הַעֲרֵב שֶׁמֶשׁ:\",3,0],[2,128,11,41,\"השרץ על הארץ. לְהוֹצִיא אֶת הַיַּתּוּשִׁין שֶׁבַּכְּלִיסִין וְשֶׁבַּפּוֹלִין, וְאֶת הַזִּיזִין שֶׁבָּעֲדָשִׁים, שֶׁהֲרֵי לֹא שָׁרְצוּ עַל הָאָרֶץ אֶלָּא בְּתוֹךְ הָאֹכֶל, אֲבָל מִשֶּׁיָּצְאוּ לָאֲוִיר וְשָׁרְצוּ הֲרֵי נֶאֱסְרוּ (ספרא; חולין ס\\\"ז):\",1,0],[2,128,11,41,\"לא יאכל. לְחַיֵּב עַל הַמַּאֲכִיל כָּאוֹכֵל; וְאֵין קָרוּי שֶׁרֶץ אֶלָּא דָּבָר נָמוּךְ, קְצַר רַגְלַיִם, שֶׁאֵינוֹ נִרְאֶה אֶלָּא כְּרוֹחֵשׁ וְנָד:\",2,0],[2,128,11,42,\"הולך על גחון. זֶה נָחָשׁ, וּלְשׁוֹן גָּחוֹן שְׁחִיָּה, שֶׁהוֹלֵךְ שָׁח וְנוֹפֵל עַל מֵעָיו:\",1,0],[2,128,11,42,\"כל הולך. לְהָבִיא הַשִּׁלְשׁוּלִין וְאֶת הַדּוֹמֶה לַדּוֹמֶה:\",2,0],[2,128,11,42,\"הולך על ארבע. זֶה עַקְרָב:\",3,0],[2,128,11,42,\"כל. לְהָבִיא אֶת הַחִפּוּשִׁית, אשקר\\\"בוט בְּלַעַז, וְאֶת הַדּוֹמֶה לַדּוֹמֶה:\",4,0],[2,128,11,42,\"מרבה רגלים. זֶה נַדָּל, שֶׁרֶץ שֶׁיֵּשׁ לוֹ רַגְלַיִם מֵרֹאשׁוֹ וְעַד זְנָבוֹ לְכָאן וּלְכָאן, וְקוֹרִין צינטפי\\\"דש (ספרא):\",5,0],[2,128,11,43,\"אל תשקצו. בַּאֲכִילָתָן, שֶׁהֲרֵי כְּתִיב נַפְשֹׁתֵיכֶם וְאֵין שִׁקּוּץ נֶפֶשׁ בְּמַגָּע, וְכֵן וְלֹא תְטַמְּאוּ בַּאֲכִילָתָם:\",1,0],[2,128,11,43,\"ונטמתם בם. אִם אַתֶּם מִטַּמְּאִין בָּהֶם בָּאָרֶץ, אַף אֲנִי מְטַמֵּא אֶתְכֶם בָּעוֹלָם הַבָּא וּבִישִׁיבַת מַעְלָה (יומא ל\\\"ט):\",2,0],[2,128,11,44,\"כי אני ה' אלהיכם. כְּשֵׁם שֶׁאֲנִי קָדוֹשׁ שֶׁאֲנִי ה' אֱלֹהֵיכֶם, כָּךְ וְהִתְקַדִּשְׁתֶּם — קַדְּשׁוּ עַצְמְכֶם לְמַטָּה:\",1,0],[2,128,11,44,\"והייתם קדשים. לְפִי שֶׁאֲנִי אֲקַדֵּשׁ אֶתְכֶם לְמַעְלָה וּבָעוֹלָם הַבָּא:\",2,0],[2,128,11,44,\"ולא תטמאו וגו'. לַעֲבֹר עֲלֵיהֶם בְּלָאוִין הַרְבֵּה, וְכָל לָאו מַלְקוּת, וְזֶהוּ שֶׁאָמְרוּ בַּתַּלְמוּד (מכות ט\\\"ז:), אָכַל פּוּטִיתָא לוֹקֶה אַרְבַּע, נְמָלָה לוֹקֶה חָמֵשׁ, צִרְעָה לוֹקֶה שֵׁשׁ:\",3,0],[2,128,11,45,\"כי אני ה' המעלה אתכם. עַל מְנָת שֶׁתְּקַבְּלוּ מִצְוֹתַי הֶעֱלֵיתִי אֶתְכֶם; דָּבָר אַחֵר, כִּי אֲנִי ה' הַמַּעֲלֶה אֶתְכֶם: בְּכֻלָּן כְּתִיב \\\"הוֹצֵאתִי\\\" וְכָאן כְּתִיב \\\"הַמַּעֲלֶה\\\", תָּנָא דְבֵי רַ' יִשְׁמָעֵאל אִלְּמָלֵי לֹא הֶעֱלֵיתִי אֶת יִשְֹרָאֵל מִמִּצְרַיִם אֶלָּא בִּשְׁבִיל שֶׁאֵין מִטַּמְּאִין בִּשְׁרָצִים כִּשְׁאָר אֻמּוֹת דַּיָּם, וּמַעַלְיוּתָא הִיא גַּבַּיְהוּ, זֶהוּ לְשׁוֹן מַעֲלָה:\",1,0],[2,128,11,47,\"להבדיל. לֹא בִּלְבַד הַשּׁוֹנֶה, אֶלָּא שֶׁתְּהֵא יוֹדֵעַ וּמַכִּיר וּבָקִי בָּהֶן (ספרא):\",1,0],[2,128,11,47,\"בין הטמא ובין הטהר. צָרִיךְ לוֹמַר בֵּין חֲמוֹר לְפָרָה, וַהֲלֹא כְבָר מְפֹרָשִׁים הֵם? אֶלָּא בֵּין טְמֵאָה לְךָ לִטְהוֹרָה לְךָ — בֵּין נִשְׁחַט חֶצְיוֹ שֶׁל קָנֶה לְנִשְׁחַט רֻבּוֹ:\",2,0],[2,128,11,47,\"ובין החיה הנאכלת. צָרִיךְ לוֹמַר בֵּין צְבִי לְעָרוֹד וַהֲלֹא כְבָר מְפֹרָשִׁים הֵם? אֶלָּא בֵּין שֶׁנּוֹלְדוּ בָהּ סִימָנֵי טְרֵפָה כְּשֵׁרָה לְנוֹלְדוּ בָהּ סִימָנֵי טְרֵפָה פְּסוּלָה (ספרא):\",3,0],[2,128,12,2,\"אשה כי תזריע. אָ\\\"רַ שִׂמְלַאי: כְּשֵׁם שֶׁיְּצִירָתוֹ שֶׁל אָדָם אַחַר כָּל בְּהֵמָה חַיָּה וָעוֹף בְּמַעֲשֵׂה בְרֵאשִׁית, כָּךְ תּוֹרָתוֹ נִתְפָּרְשָׁה אַחַר תּוֹרַת בְּהֵמָה חַיָּה וָעוֹף (ויקרא רבה יד):\",1,0],[2,128,12,2,\"כי תזריע. לְרַבּוֹת שֶׁאֲפִלּוּ יְלָדַתּוּ מָחוּי — שֶׁנִּמְחָה וְנַעֲשָׂה כְּעֵין זֶרַע — אִמּוֹ טְמֵאָה לֵידָה (נדה כ\\\"ז):\",2,0],[2,128,12,2,\"כימי נדת דותה תטמא. כְּסֵדֶר כָּל טֻמְאָה הָאֲמוּרָה בְנִדָּה מִטַּמְּאָה בְטֻמְאַת לֵידָה, וַאֲפִלוּ נִפְתַּח הַקֶּבֶר בְּלֹא דָם (שם כ\\\"א):\",3,0],[2,128,12,2,\"דותה. לְשׁוֹן דָּבָר הַזָּב מִגּוּפָהּ; לָשׁוֹן אַחֵר לְשׁוֹן מַדְוֶה וְחֹלִי, שֶׁאֵין אִשָּׁה רוֹאָה דָם שֶׁלֹּא תֶחֱלֶה וְרֹאשָׁהּ וְאֵבָרֶיהָ כְבֵדִין עָלֶיהָ (שם ט'):\",4,0],[2,128,12,4,\"תשב. אֵין תֵּשֵׁב אֶלָּא לְשׁוֹן עַכָּבָה, כְּמוֹ וַתֵּשְׁבוּ בְקָדֵשׁ (דברים א'), וַיֵּשֶׁב בְּאֵלֹנֵי מַמְרֵא (בראשית י\\\"ג):\",1,0],[2,128,12,4,\"בדמי טהרה. אַעַ\\\"פִּי שֶׁרוֹאָה טְהוֹרָה:\",2,0],[2,128,12,4,\"בדמי טהרה. לֹא מַפִּיק הֵ\\\"א, וְהוּא שֵׁם דָּבָר כְּמוֹ טֹהַר:\",3,0],[2,128,12,4,\"ימי טהרה. מַפִּיק הֵ\\\"א — יְמֵי טֹהַר שֶׁלָּהּ:\",4,0],[2,128,12,4,\"בכל קדש. לְרַבּוֹת אֶת הַתְּרוּמָה, לְפִי שֶׁזּוֹ טְבוּלַת יוֹם אָרֹךְ, שֶׁטָּבְלָה לְסוֹף שִׁבְעָה וְאֵין שִׁמְשָׁהּ מַעֲרִיב לְטַהֲרָהּ עַד שְׁקִיעַת הַחַמָּה שֶׁל יוֹם אַרְבָּעִים שֶׁלְּמָחָר תָּבִיא אֶת כַּפָּרַת טָהֳרָתָהּ:\",5,0],[2,128,12,4,\"לא תגע. אַזְהָרָה לָאוֹכֵל וְכוֹ' כְּמוֹ שֶׁשְּׁנוּיָה בִיבָמוֹת (דף ע\\\"ה):\",6,0],[2,128,12,7,\"והקריבו. לִמֶּדְךָ שֶׁאֵין מְעַכְּבָהּ לֶאֱכֹל בְּקָדָשִׁים אֶלָּא אֶחָד מֵהֶם, וְאֵי זֶה הוּא? זֶה חַטָּאת, שֶׁנֶּאֱמַר וְכִפֶּר עָלֶיהָ הַכֹּהֵן וְטָהֵרָה, מִי שֶׁהוּא בָא לְכַפֵּר, בּוֹ הַטָּהֳרָה תְלוּיָה:\",1,0],[2,128,12,7,\"וטהרה. מִכְּלָל שֶׁעַד כָּאן קְרוּיָה טְמֵאָה:\",2,0],[2,128,12,8,\"אחד לעלה ואחד לחטאת. לֹא הִקְדִּימָהּ הַכָּתוּב אֶלָּא לְמִקְרָאָהּ, אֲבָל לְהַקְרָבָה חַטָּאת קוֹדֵם לָעוֹלָה, כָּךְ שָׁנִינוּ בִּזְבָחִים בְּפֶרֶק כָּל הַתָּדִיר (זבחים צ ע\\\"א):\",1,0],[2,128,13,2,\"שאת או ספחת וגו'. שְׁמוֹת נְגָעִים הֵם וּלְבָנוֹת זוֹ מִזּוֹ:\",1,0],[2,128,13,2,\"בהרת. חֲבַרְבּוּרוֹת, טיי\\\"א בְּלַעַז, וְכֵן בָּהִיר הוּא בַּשְּׁחָקִים (איוב ל\\\"ז):\",2,0],[2,128,13,2,\"אל אהרן וגו'. גְּזֵרַת הַכָּתוּב הִיא שֶׁאֵין טֻמְאַת נְגָעִים וְטָהֳרָתָן אֶלָּא עַל פִּי כֹהֵן (ספרא):\",3,0],[2,128,13,3,\"הפך לבן. מִתְּחִלָּה שָׁחֹר וְהָפַךְ לְלָבָן בְּתוֹךְ הַנֶּגַע; וּמִעוּט שֵׂעָר שְׁנַיִם:\",1,0],[2,128,13,3,\"עמק מעור בשרו. כָּל מַרְאֵה לָבָן עָמֹק הוּא, כְּמַרְאֵה חַמָּה עֲמֻקָּה מִן הַצֵּל:\",2,0],[2,128,13,3,\"וטמא אתו. יֹאמַר לוֹ טָמֵא אַתָּה, שֶׁשֵּׂעָר לָבָן סִימָן טֻמְאָה הוּא גְּזֵרַת הַכָּתוּב:\",3,0],[2,128,13,4,\"ועמק אין מראה. לֹא יָדַעְתִּי פֵרוּשׁוֹ:\",1,0],[2,128,13,4,\"והסגיר. יַסְגִּירֶנּוּ בְּבַיִת אֶחָד וְלֹא יִרְאֶה עַד סוֹף הַשָּׁבוּעַ וְיוֹכִיחוּ סִימָנִים עָלָיו:\",2,0],[2,128,13,5,\"בעניו. בְּמַרְאֵהוּ וּבְשִׁעוּרוֹ הָרִאשׁוֹן:\",1,0],[2,128,13,5,\"והסגירו … שנית. הָא אִם פָּשָׂה בְּשָׁבוּעַ רִאשׁוֹן, טָמֵא מֻחְלָט:\",2,0],[2,128,13,6,\"כהה. הָכְהָה מִמַּרְאִיתוֹ, הָא אִם עָמַד בְּמַרְאִיתוֹ אוֹ פָשָׂה טָמֵא:\",1,0],[2,128,13,6,\"מספחת. שֵׁם נֶגַע טָהוֹר:\",2,0],[2,128,13,6,\"וכבס בגדיו וטהר. הוֹאִיל וְנִזְקַק לְהִסָּגֵר נִקְרָא טָמֵא וְצָרִיךְ טְבִילָה:\",3,0],[2,128,13,8,\"וטמאו הכהן. וּמִשֶּׁטִּמְּאוֹ הֲרֵי הוּא מֻחְלָט, וְזָקוּק לְצִפֳּרִים וּלְתִגְלַחַת וּלְקָרְבָּן הָאָמוּר בְּפָרָשַׁת זֹאת תִּהְיֶה:\",1,0],[2,128,13,8,\"צרעת הוא. הַמִּסְפַּחַת הַזֹּאת:\",2,0],[2,128,13,8,\"צרעת. לְשׁוֹן נְקֵבָה. נגע. לְשׁוֹן זָכָר:\",3,0],[2,128,13,10,\"ומחית. שינמי\\\"נט בְּלַעַז, שֶׁנֶּהְפַּךְ מִקְצַת הַלֹּבֶן שֶׁבְּתוֹךְ הַשְּׂאֵת לְמַרְאֵה בָשָׂר, אַף הִיא סִימָן טֻמְאָה — שֵׂעָר לָבָן בְּלֹא מִחְיָה וּמִחְיָה בְּלֹא שֵׂעָר לָבָן — וְאַף עַל פִּי שֶׁלֹּא נֶאֶמְרָה מִחְיָה אֶלָּא בַּשְּׂאֵת, אַף בְּכָל הַמַּרְאוֹת וְתוֹלְדוֹתֵיהֶן הוּא סִימָן טֻמְאָה:\",1,0],[2,128,13,11,\"צרעת נושנת הוא. מַכָּה יְשָׁנָה הִיא תַּחַת הַמִּחְיָה, וְחַבּוּרָה זוֹ נִרְאֵית בְּרִיאָה לְמַעְלָה וְתַחְתֶּיהָ מְלֵאָה לֵחָה — שֶׁלֹּא תֹאמַר הוֹאִיל וְעָלְתָה מִחְיָה אֲטַהֲרֶנָּה:\",1,0],[2,128,13,12,\"מראשו. שֶׁל אָדָם ועד רגליו:\",1,0],[2,128,13,12,\"לכל מראה עיני הכהן. פְּרָט לְכֹהֵן שֶׁחָשַׁךְ מְאוֹרוֹ (ספרא):\",2,0],[2,128,13,14,\"וביום הראות בו בשר חי. אִם צָמְחָה בוֹ מִחְיָה הֲרֵי כְבָר פֵּרֵשׁ שֶׁהַמִּחְיָה סִימָן טֻמְאָה? אֶלָּא הֲרֵי שֶׁהָיָה הַנֶּגַע בְּאֶחָד מֵעֶשְׂרִים וְאַרְבָּעָה רָאשֵׁי אֵבָרִים שֶׁאֵין מִטַּמְּאִין מִשּׁוּם מִחְיָה — לְפִי שֶׁאֵין נִרְאֶה הַנֶּגַע כֻּלּוֹ כְאֶחָד, שֶׁשּׁוֹפְעִין אֵילָךְ וָאֵילָךְ (נגעים פ\\\"ו; קידושין כ\\\"ה) — וְחָזַר רֹאשׁ הָאֵבֶר וְנִתְגַּלָּה שִׁפּוּעוֹ עַל יְדֵי שֻׁמָּן, כְּגוֹן שֶׁהִבְרִיא וְנַעֲשָֹה רָחָב וְנִרְאֵית בּוֹ הַמִּחְיָה, לִמְּדָנוּ הַכָּתוּב שֶׁתְּטַמֵּא (ספרא):\",1,0],[2,128,13,14,\"וביום. מַה תַּ\\\"ל? לְלַמֵּד יֵשׁ יוֹם שֶׁאַתָּה רוֹאֶה בוֹ וְיֵשׁ יוֹם שֶׁאֵין אַתָּה רוֹאֶה בוֹ, מִכָּאן אָמְרוּ: חָתָן נוֹתְנִין לוֹ כָּל שִׁבְעַת יְמֵי הַמִּשְׁתֶּה, לוֹ וְלִכְסוּתוֹ וּלְבֵיתוֹ, וְכֵן בָּרֶגֶל נוֹתְנִין לוֹ כָּל יְמֵי הָרֶגֶל (נגעים פ\\\"ג, מועד קטן ז'):\",2,0],[2,128,13,15,\"צרעת הוא. הַבָּשָׂר הַהוּא: בָּשָׂר לְשׁוֹן זָכָר:\",1,0],[2,128,13,18,\"שחין. לְשׁוֹן חִמּוּם, שֶׁנִּתְחַמֵּם הַבָּשָֹר בְּלִקּוּי הַבָּא לוֹ מֵחֲמַת מַכָּה שֶׁלֹּא מֵחֲמַת הָאוּר (חולין ח'):\",1,0],[2,128,13,18,\"ונרפא. הַשְּׁחִין הֶעֱלָה אֲרוּכָה וּבִמְקוֹמוֹ הֶעֱלָה נֶגַע אַחֵר:\",2,0],[2,128,13,19,\"או בהרת לבנה אדמדמת. שֶׁאֵין הַנֶּגַע לָבָן חָלָק, אֶלָּא פָּתוּךְ וּמְעֹרָב בִּשְׁתֵּי מַרְאוֹת — לֹבֶן וְאֹדֶם:\",1,0],[2,128,13,20,\"מראה שפל. וְאֵין מַמָּשָׁהּ שָׁפָל, אֶלָּא מִתּוֹךְ לַבְנוּנִיתוֹ הוּא נִרְאֶה שָׁפָל וְעָמֹק, כְּמַרְאֵה חַמָּה עֲמֻקָּה מִן הַצֵּל:\",1,0],[2,128,13,22,\"נגע הוא. הַשְּׂאֵת הַזֹּאת אוֹ הַבַּהֶרֶת:\",1,0],[2,128,13,23,\"תחתיה. בִּמְקוֹמָהּ:\",1,0],[2,128,13,23,\"צרבת השחין. כְּתַרְגּוּמוֹ רֹשֶׁם שִׁחֲנָא; — אֵינוֹ אֶלָּא רֹשֶׁם הַחִמּוּם הַנִּכָּר בַּבָּשָֹר; כָּל צָרֶבֶת לְשׁוֹן רְגִיעַת עוֹר הַנִּרְגָּע מֵחֲמַת חִמּוּם, כְּמוֹ וְנִצְרְבוּ בָהּ כָּל פָּנִים (יחזקאל כ\\\"א), רייטרו\\\"ר בְּלַעַז:\",2,0],[2,128,13,23,\"צרבת. רייטרי\\\"שמנט בְּלַעַז:\",3,0],[2,128,13,24,\"מחית המכוה. שנימני\\\"ט; כְּשֶׁחָיְתָה הַמִּכְוָה הָפְכָה לְבַהֶרֶת פְּתוּכָה אוֹ לְבָנָה חֲלָקָה; וְסִימָנֵי מִכְוָה וְסִימָנֵי שְׁחִין שָׁוִים הֵם, וְלָמָּה חִלְּקָן הַכָּתוּב? לוֹמַר שֶׁאֵין מִצְטָרְפִין זֶה עִם זֶה — נוֹלַד חֲצִי גְרִיס בַּשְּׁחִין וַחֲצִי גְרִיס בַּמִּכְוָה, לֹא יִדּוֹנוּ כִגְרִיס (חולין ח'):\",1,0],[2,128,13,29,\"בראש או בזקן. בָּא הַכָּתוּב לְחַלֵּק בֵּין נֶגַע שֶׁבִּמְקוֹם שֵׂעָר לְנֶגַע שֶׁבִּמְקוֹם בָּשָׂר, שֶׁזֶּה סִימָנוֹ בְּשֵׂעָר לָבָן וְזֶה סִימָנוֹ בְּשֵׂעָר צָהֹב:\",1,0],[2,128,13,30,\"ובו שער צהב. שֶׁנֶּהְפַּךְ שֵׂעָר שָׁחֹר שֶׁבּוֹ לְצָהֹב:\",1,0],[2,128,13,30,\"נתק הוא. כָּךְ שְׁמוֹ שֶׁל נֶגַע שֶׁבִּמְקוֹם שֵׂעָר:\",2,0],[2,128,13,31,\"ושער שחר אין בו. הָא אִם הָיָה בוֹ שֵׂעָר שָׁחֹר טָהוֹר וְאֵין צָרִיךְ לְהֶסְגֵּר, שֶׁהַשֵּׂעָר שָׁחֹר סִימָן טָהֳרָה הוּא בִנְתָקִים, כְּמוֹ שֶׁנֶּאֱמַר (פסוק ל\\\"ז), וְשֵׂעָר שָׁחֹר צָמַח בּוֹ וְגוֹ':\",1,0],[2,128,13,32,\"והנה לא פשה וגו'. הָא אִם פָּשָׂה אוֹ הָיָה בוֹ שֵׂעָר צָהֹב טָמֵא:\",1,0],[2,128,13,33,\"והתגלח. סְבִיבוֹת הַנֶּתֶק,\",1,0],[2,128,13,33,\"ואת הנתק לא יגלח. מַנִּיחַ שְׁתֵּי שְׂעָרוֹת סָמוּךְ לוֹ סָבִיב, כְּדֵי שֶׁיְּהֵא נִכָּר אִם פָּשָׂה, שֶׁאִם יִפְשֶׂה יַעֲבֹר הַשְּׂעָרוֹת וְיֵצֵא לִמְקוֹם הַגִּלּוּחַ (נגעים פ\\\"י, ספרא):\",2,0],[2,128,13,35,\"אחרי טהרתו. אֵין לִי אֶלָּא פוֹשֶׂה לְאַחַר הַפְּטוֹר, מִנַּיִן אַף בְּסוֹף שָׁבוּעַ רִאשׁוֹן וּבְסוֹף שָׁבוּעַ שֵׁנִי? תַּלְמוּד לוֹמַר פָּשֹׂה יִפְשֶׂה (ספרא):\",1,0],[2,128,13,37,\"ושער שחר. מִנַּיִן אַף הַיָּרֹק וְהָאָדֹם, שֶׁאֵינוֹ צָהֹב? תַּלְמוּד לוֹמַר \\\"וְשֵׂעָר\\\"; וּלְשׁוֹן צָהֹב דּוֹמֶה לְתַבְנִית הַזָּהָב — צָהֹב כְּמוֹ זָהֹב, אור\\\"פלא בְּלַעַז:\",1,0],[2,128,13,37,\"טהור הוא וטהרו הכהן. הָא טָמֵא שֶׁטִּהֲרוֹ הַכֹּהֵן לֹא טָהוֹר:\",2,0],[2,128,13,38,\"בהרת. חֲבַרְבּוּרוֹת:\",1,0],[2,128,13,39,\"כהות לבנת. שֶׁאֵין לֹבֶן שֶׁלָּהֶן עַז אֶלָּא כּוֹהֶה:\",1,0],[2,128,13,39,\"בהק. כְּמוֹ לֹבֶן הַנִּרְאֶה בִּבְשַׂר אָדָם אָדֹם, שֶׁקּוֹרִין רוש\\\"ו, בֵּין חֲבַרְבּוּרוֹת אַדְמִימוּתוֹ, קָרוּי בֹּהַק, כְּאִישׁ עַדְשָׁן שֶׁבֵּין עֲדָשָׁה לַעֲדָשָׁה מַבְהִיק הַבָּשָֹר בְּלֹבֶן צַח:\",2,0],[2,128,13,40,\"קרח הוא טהור הוא. טָהוֹר מִטֻּמְאַת נְתָקִין, שֶׁאֵינוֹ נִדּוֹן בְּסִימָנֵי רֹאשׁ וְזָקָן שֶׁהֵם מְקוֹם שֵׂעָר, אֶלָּא בְסִימָנֵי נֶגַע עוֹר בָּשָׂר — (בְּשֵֹעָר לָבָן) וּמִחְיָה וּפִשְׂיוֹן (נגעים פ\\\"י):\",1,0],[2,128,13,41,\"ואם מפאת פניו. מִשִּׁפּוּעַ קָדְקֹד כְּלַפֵּי פָנָיו קָרוּי גַּבַּחַת — וְאַף הַצְּדָעִין שֶׁמִּכָּאן וּמִכָּאן בִּכְלָל — וּמִשִּׁפּוּעַ קָדְקֹד כְּלַפֵּי אֲחוֹרָיו קָרוּי קָרַחַת:\",1,0],[2,128,13,42,\"נגע לבן אדמדם. פָּתוּךְ; מִנַּיִן שְׁאָר הַמַּרְאוֹת? תַּלְמוּד לוֹמַר נֶגַע:\",1,0],[2,128,13,43,\"כמראה צרעת עור בשר. כְּמַרְאֵה הַצָּרַעַת הָאָמוּר בְּפָרָשַׁת \\\"עוֹר בָּשָׂר\\\" — אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ, וּמָה אָמוּר בּוֹ? שֶׁמְּטַמֵּא בְאַרְבַּע מַרְאוֹת, וְנִדּוֹן בִּשְׁנֵי שָׁבוּעוֹת; וְלֹא כְמַרְאֵה צָרַעַת הָאָמוּר בִּשְׁחִין וּמִכְוָה שֶׁהוּא נִדּוֹן בְּשָׁבוּעַ אֶחָד, וְלֹא כְמַרְאֵה נְתָקִין שֶׁל מְקוֹם שֵׂעָר, שֶׁאֵין מְטַמְּאִין בְּאַרְבַּע מַרְאוֹת — שְׂאֵת וְתוֹלַדְתָּהּ, בַּהֶרֶת וְתוֹלַדְתָּהּ:\",1,0],[2,128,13,44,\"בראשו נגעו. אֵין לִי אֶלָּא נְתָקִין, מִנַּיִן לְרַבּוֹת שְׁאָר הַמְנֻגָּעִים? תַּ\\\"ל \\\"טַמֵּא יְטַמְּאֶנּוּ\\\", לְרַבּוֹת אֶת כֻּלָּן — עַל כֻּלָּן הוּא אוֹמֵר בְּגָדָיו יִהְיוּ פְרֻמִים וְגוֹ':\",1,0],[2,128,13,45,\"פרמים. קְרוּעִים:\",1,0],[2,128,13,45,\"פרוע. מְגֻדַּל שֵׂעָר:\",2,0],[2,128,13,45,\"ועל שפם יעטה. כְּאָבֵל:\",3,0],[2,128,13,45,\"שפם. שְׂעַר הַשְּׂפָתַיִם, גרנו\\\"ן בְּלַעַז:\",4,0],[2,128,13,45,\"וטמא טמא יקרא. מַשְׁמִיעַ שֶׁהוּא טָמֵא וְיִפְרְשׁוּ מִמֶּנּוּ (ספרא, מועד קטן ה'):\",5,0],[2,128,13,46,\"בדד ישב. שֶׁלֹּא יִהְיוּ טְמֵאִים יוֹשְׁבִין עִמּוֹ; וְאָמְרוּ רַבּוֹתֵינוּ מַה נִּשְׁתַּנָּה מִשְּׁאָר טְמֵאִים לֵישֵׁב בָּדָד? הוֹאִיל וְהוּא הִבְדִּיל בְּלָשׁוֹן הָרָע בֵּין אִישׁ לְאִשְׁתּוֹ וּבֵין אִישׁ לְרֵעֵהוּ, אַף הוּא יִבָּדֵל (ערכין ט\\\"ז):\",1,0],[2,128,13,46,\"מחוץ למחנה. חוּץ לְשָׁלוֹשׁ מַחֲנוֹת:\",2,0],[2,128,13,48,\"לפשתים ולצמר. שֶׁל פִּשְׁתִּים אוֹ שֶׁל צֶמֶר:\",1,0],[2,128,13,48,\"או בעור. זֶה עוֹר שֶׁלֹא נַעֲשָׂה בוֹ מְלָאכָה:\",2,0],[2,128,13,48,\"או בכל מלאכת עור. זֶה עוֹר שֶׁנַּעֲשָׂה בוֹ מְלָאכָה:\",3,0],[2,128,13,49,\"ירקרק. יָרֹק שֶׁבַּיְרֻקִּין:\",1,0],[2,128,13,49,\"אדמדם. אָדֹם שֶׁבָּאֲדֻמִּים:\",2,0],[2,128,13,51,\"צרעת ממארת. לְשׁוֹן סִלּוֹן מַמְאִיר (יחזקאל כ\\\"ח), פויי\\\"נט בְּלַעַז; וּמִדְרָשׁוֹ: תֵּן בּוֹ מְאֵרָה שֶׁלֹא תֵהָנֶה הֵימֶנּוּ (ספרא):\",1,0],[2,128,13,52,\"בצמר או בפשתים. שֶׁל צֶמֶר אוֹ שֶׁל פִּשְׁתִּים, זֶהוּ פְשׁוּטוֹ; וּמִדְרָשׁוֹ: יָכוֹל יָבִיא גִּזֵּי צֶמֶר וַאֲנִיצֵי פִשְׁתָּן וְיִשְׂרְפֵם עִמּוֹ? תַּ\\\"ל \\\"הוּא\\\" באש תשרף — אֵינָהּ צְרִיכָה דָבָר אַחֵר עִמָּהּ, אִם כֵּן מַה תַּ\\\"ל \\\"בַּצֶּמֶר אוֹ בַפִּשְׁתִּים\\\"? לְהוֹצִיא אֶת הָאֻמְרִיּוֹת שֶׁבּוֹ שֶׁהֵן מִמִּין אַחֵר; אֻמְרִיּוֹת לְשׁוֹן שָׂפָה, כְּמוֹ אִימְרָא (ספרא):\",1,0],[2,128,13,54,\"את אשר בו הנגע. יָכוֹל מְקוֹם הַנֶּגַע בִּלְבַד, תַּ\\\"ל \\\"אֵת אֲשֶׁר בּוֹ הַנָּגַע\\\", יָכוֹל כָּל הַבֶּגֶד כֻּלּוֹ טָעוּן כִּבּוּס, תַּ\\\"ל \\\"הַנָּגַע\\\", הָא כֵיצַד? יְכַבֵּס מִן הַבֶּגֶד עִמּוֹ:\",1,0],[2,128,13,55,\"אחרי הכבס. לְשׁוֹן הֵעָשׂוֹת:\",1,0],[2,128,13,55,\"לא הפך הנגע את עינו. לֹא הָכְהָה מִמַּרְאִיתוֹ:\",2,0],[2,128,13,55,\"והנגע לא פשה. שָׁמַעְנוּ שֶׁאִם לֹא הָפַךְ וְלֹא פָשָׂה טָמֵא — וְאֵין צָרִיךְ לוֹמַר לֹא הָפַךְ וּפָשָׂה — הָפַךְ וְלֹא פָשָׂה אֵינִי יוֹדֵעַ מַה יֵּעָשֶׂה לוֹ, תַּ\\\"ל \\\"וְהִסְגִּיר אֶת הַנֶּגַע\\\" — מִכָּל מָקוֹם, דִּבְרֵי רַ' יְהוּדָה, וַחֲכָמִים אוֹמְרִים וְכוּ', כִּדְאִיתָא בְת\\\"כֹּ, וּרְמַזְתִּיהָ כָּאן לְיַשֵּׁב הַמִּקְרָא עַל אָפְנָיו:\",3,0],[2,128,13,55,\"פחתת הוא. לְשׁוֹן גֻּמָּא, כְּמוֹ בְּאַחַת הַפְּחָתִים (שמואל ב י\\\"ז), כְּלוֹמַר שְׁפֵלָה הִיא — נֶגַע שֶׁמַּרְאָיו שׁוֹקְעִין (ספרא):\",4,0],[2,128,13,55,\"בקרחתו או בגבחתו. כְּתַרְגּוּמוֹ בִּשְׁחִיקוּתֵהּ אוֹ בְחַדָּתוּתֵהּ:\",5,0],[2,128,13,55,\"קרחתו. שְׁחָקִים, יְשָׁנִים; וּמִפְּנֵי הַמִּדְרָשׁ שֶׁהֻצְרַךְ לִגְזֵרָה שָׁוָה — מִנַּיִן לִפְרִיחָה בַבְּגָדִים שֶׁהִיא טְהוֹרָה? נֶאֶמְרָה קָרַחַת וְגַבַּחַת בָּאָדָם, וְנֶאֶמְרָה קָרַחַת וְגַבַּחַת בַּבְּגָדִים, מַה לְּהַלָּן פָּרַח בְּכֻלּוֹ טָהוֹר אַף כָּאן פָּרַח בְּכֻלּוֹ טָהוֹר — לְכָךְ אָחַז הַכָּתוּב לְשׁוֹן קָרַחַת וְגַבַּחַת; וּלְעִנְיַן פֵּרוּשׁוֹ וְתַרְגּוּמוֹ זֶהוּ מַשְׁמָעוֹ: קָרַחַת לְשׁוֹן יְשָׁנִים וְגַבַּחַת לְשׁוֹן חֲדָשִׁים — כְּאִלּוּ נִכְתַּב בְּאַחֲרִיתוֹ אוֹ בְקַדְמוּתוֹ — שֶׁהַקָּרַחַת לְשׁוֹן אֲחוֹרַיִם וְגַּבַּחַת לְשׁוֹן פָּנִים, כְּמוֹ שֶׁכָּתוּב וְאִם מִפְּאַת פָּנָיו וְגוֹ', וְהַקָּרַחַת כָּל שֶׁשּׁוֹפֵעַ וְיוֹרֵד מִן הַקָּדְקֹד וּלְאַחֲרָיו, כָּךְ מְפֹרָשׁ בְּתֹ\\\"כֹּ:\",6,0],[2,128,13,56,\"וקרע אתו. יִקְרַע מְקוֹם הַנֶּגַע מִן הַבֶּגֶד וְיִשְׂרְפֶנּוּ:\",1,0],[2,128,13,57,\"פרחת הוא. דָּבָר הַחוֹזֵר וְצוֹמֵחַ:\",1,0],[2,128,13,57,\"באש תשרפנו. אֶת כָּל הַבֶּגֶד:\",2,0],[2,128,13,58,\"וסר מהם הנגע. אִם כְּשֶׁכִּבְּסוּהוּ בַתְּחִלָּה עַל פִּי כֹהֵן סָר מִמֶּנּוּ הַנֶּגַע לְגַמְרֵי.\",1,0],[2,128,13,58,\"וכבס שנית. לְשׁוֹן טְבִילָה; תַּרְגּוּם שֶׁל כִּבּוּסִין שֶׁבְּפָרָשָׁה זוֹ לְשׁוֹן לִבּוּן, \\\"וְיִתְחַוַּר\\\", חוּץ מִזֶּה, שֶׁאֵינוֹ לְלִבּוּן אֶלָּא לִטְבֹּל, לְכָךְ תַּרְגּוּמוֹ \\\"וְיִצְטַבַּע\\\", וְכֵן כָּל כִּבּוּסֵי בְגָדִים שֶׁהֵן לִטְבִילָה מְתֻרְגָּמִין וְיִצְטַבַּע:\",2,0],[2,128,14,2,\"זאת תהיה תורת וגו'. מְלַמֵּד שֶׁאֵין מְטַהֲרִין אוֹתוֹ בַּלַּיְלָה (ספרא):\",1,0],[2,128,14,3,\"אל מחוץ למחנה. חוּץ לִשְׁלוֹשָׁה מַחֲנוֹת שֶׁנִּשְׁתַּלַח שָׁם בִּימֵי חֲלוּטוֹ:\",1,0],[2,128,14,4,\"חיות. פְּרָט לִטְרֵפוֹת:\",1,0],[2,128,14,4,\"טהרות. פְּרָט לְעוֹף טָמֵא, לְפִי שֶׁהַנְּגָעִים בָּאִין עַל לָשׁוֹן הָרַע שֶׁהוּא מַעֲשֵׂה פִטְפּוּטֵי דְבָרִים, לְפִיכָךְ הֻזְקְקוּ לְטָהֳרָתוֹ צִפֳּרִים שֶׁמְּפַטְפְּטִין תָּמִיד בְּצִפְצוּף קוֹל (ערכין ט\\\"ז):\",2,0],[2,128,14,4,\"ועץ ארז. לְפִי שֶׁהַנְּגָעִים בָּאִין עַל גַּסּוּת הָרוּחַ (שם):\",3,0],[2,128,14,4,\"ושני תולעת ואזב. מַה תַּקָּנָתוֹ וְיִתְרַפֵּא? יַשְׁפִּיל עַצְמוֹ מִגַּאֲוָתוֹ כְּתוֹלַעַת וּכְאֵזוֹב:\",4,0],[2,128,14,4,\"עץ ארז. מַקֵּל שֶׁל אֶרֶז:\",5,0],[2,128,14,4,\"שני תולעת. לָשׁוֹן שֶׁל צֶמֶר צָבוּעַ זְהוֹרִית:\",6,0],[2,128,14,5,\"על מים חיים. נוֹתֵן אוֹתָם תְּחִלָּה בִּכְלִי, כְּדֵי שֶׁיְּהֵא דַם צִפּוֹר נִכָּר בָּהֶם, וְכַמָּה הֵם? רְבִיעִית (סוטה ט\\\"ז):\",1,0],[2,128,14,6,\"את הצפר החיה יקח אתה. מְלַמֵּד שֶׁאֵינוֹ אוֹגְדָהּ עִמָּהֶם, אֶלָּא מַפְרִישָׁהּ לְעַצְמָהּ, אֲבָל הָעֵץ וְהָאֵזוֹב כְּרוּכִין יַחַד בִּלְשׁוֹן הַזְּהוֹרִית, כָּעִנְיָן שֶׁנֶּאֱמַר וְאֶת עֵץ הָאֶרֶז וְאֶת שְׁנִי הַתּוֹלַעַת וְאֶת הָאֵזֹב — קִיחָה אַחַת לִשְׁלָשְׁתָּן; יָכוֹל כְּשֵׁם שֶׁאֵינָהּ בִּכְלַל אֲגֻדָּה, כָּךְ לֹא תְהֵא בִכְלַל טְבִילָה, תַּ\\\"ל וְטָבַל אוֹתָם וְאֵת הַצִּפֹּר הַחַיָּה — הֶחֱזִיר אֶת הַצִּפּוֹר לִכְלַל טְבִילָה (ספרא):\",1,0],[2,128,14,8,\"וישב מחוץ לאהלו. מְלַמֵּד שֶׁאָסוּר בְּתַשְׁמִישׁ הַמִּטָּה (שם):\",1,0],[2,128,14,9,\"את כל שערו וגו'. כְּלָל וּפְרָט וּכְלָל, לְהָבִיא כָּל מְקוֹם כִּנּוּס שֵׂעָר וְנִרְאֶה (סוטה ט\\\"ז):\",1,0],[2,128,14,10,\"וכבשה אחת. לְחַטָּאת:\",1,0],[2,128,14,10,\"ושלשה עשרנים. לְנִסְכֵּי שְׁלוֹשָׁה כְבָשִֹים הַלָּלוּ, שֶׁחַטָּאתוֹ וַאֲשָׁמוֹ שֶׁל מְצֹרָע טְעוּנִין נְסָכִים (מנחות צ\\\"א):\",2,0],[2,128,14,10,\"ולג אחד שמן. לְהַזּוֹת עָלָיו שֶׁבַע, וְלִתֵּן מִמֶּנּוּ עַל תְּנוּךְ אָזְנוֹ וּמַתַּן בְּהוֹנוֹת:\",3,0],[2,128,14,11,\"לפני ה'. בְּשַׁעַר נִקָּנוֹר, וְלֹא בָעֲזָרָה עַצְמָהּ, לְפִי שֶׁהוּא מְחֻסָּר כִּפּוּרִים (כלים פ\\\"א):\",1,0],[2,128,14,12,\"והקריב אתו לאשם. יַקְרִיבֶנּוּ לְתוֹךְ הָעֲזָרָה לְשֵׁם אָשָׁם לְהָנִיף, שֶׁהוּא טָעוּן תְּנוּפָה חָי (מנחות ס\\\"ב):\",1,0],[2,128,14,12,\"והניף אתם. אֶת הָאָשָׁם וְאֶת הַלֹּג (שם ס\\\"א):\",2,0],[2,128,14,13,\"במקום אשר ישחט וגו'. עַל יֶרֶךְ הַמִּזְבֵּחַ בַּצָּפוֹן, וּמַה תַּלְמוּד לוֹמַר? וַהֲלֹא כְבָר נֶאֱמַר בְּתוֹרַת אָשָׁם בְפָרָשַׁת צַו אֶת אַהֲרֹן שֶׁהָאָשָׁם טָעוּן שְׁחִיטָה בַצָּפוֹן? לְפִי שֶׁיָּצָא זֶה מִכְּלַל אֲשָׁמוֹת לִדּוֹן בְּהַעֲמָדָה, יָכוֹל תְּהֵא שְׁחִיטָתוֹ בִּמְקוֹם הַעֲמָדָתוֹ, לְכָךְ נֶאֱמַר \\\"וְשָׁחַט … בִּמְקוֹם אֲשֶׁר יִשְׁחַט וְגוֹ'\\\" (ספרא):\",1,0],[2,128,14,13,\"כי כחטאת. כִּי כְּכָל הַחַטָּאוֹת האשם הַזֶּה הוא לכהן — בְּכָל עֲבוֹדוֹת הַתְּלוּיוֹת בַּכֹּהֵן הֻשְׁוָה אָשָׁם זֶה לְחַטָּאת. שֶׁלֹּא תֹאמַר הוֹאִיל וְיָצָא דָמוֹ מִכְּלַל שְׁאָר אֲשָׁמוֹת לִנָּתֵן עַל תְּנוּךְ וּבְהוֹנוֹת, לֹא יְהֵא טָעוּן מַתַּן דָּמִים וְאֵמוּרִים לְגַבֵּי מִזְבֵּחַ, לְכָךְ נֶאֱמַר כִּי כַּחַטָּאת הָאָשָׁם הוּא לַכֹּהֵן יָכוֹל יְהֵא דָמוֹ נִתָּן לְמַעְלָה כַּחַטָּאת, תַּלְמוּד לוֹמַר וְכוּ' בְּתוֹרַת כֹּהֲנִים:\",2,0],[2,128,14,14,\"תנוך. גָּדֵר אֶמְצָעִי שֶׁבָּאֹזֶן, וּלְשׁוֹן תְּנוּךְ לֹא נוֹדַע לִי, וְהַפּוֹתְרִים קוֹרִים לוֹ טנד\\\"רום:\",1,0],[2,128,14,14,\"בהן. גּוּדָל:\",2,0],[2,128,14,16,\"לפני ה'. כְּנֶגֶד בֵּית קָדְשֵׁי הַקֳּדָשִׁים (ספרא):\",1,0],[2,128,14,20,\"ואת המנחה. מִנְחַת נְסָכִים שֶׁל בְּהֵמָה:\",1,0],[2,128,14,21,\"ועשרון סלת אחד. לְכֶבֶשׂ זֶה שֶׁהוּא אֶחָד, יָבִיא עִשָּׂרוֹן אֶחָד לִנְסָכָיו:\",1,0],[2,128,14,21,\"ולג שמן. לָתֵת מִמֶּנּוּ עַל הַבְּהוֹנוֹת; וְשֶׁמֶן שֶׁל נִסְכֵּי הַמִּנְחָה לֹא הֻזְקַק הַכָּתוּב לְפָרֵשׁ:\",2,0],[2,128,14,23,\"ביום השמיני לטהרתו. שְׁמִינִי לְצִפֳּרִים וּלְהַזָּאַת עֵץ אֶרֶז וְאֵזוֹב וּשְׁנִי תּוֹלַעַת:\",1,0],[2,128,14,28,\"על מקום דם האשם. אֲפִלּוּ נִתְקַנַּח הַדָּם; לִמֵּד, שֶׁאֵין הַדָּם גּוֹרֵם אֶלָּא הַמָּקוֹם גּוֹרֵם (ספרא):\",1,0],[2,128,14,34,\"ונתתי נגע צרעת. בְּשׂוֹרָה הִיא לָהֶם שֶׁהַנְּגָעִים בָּאִים עֲלֵיהֶם; לְפִי שֶׁהִטְמִינוּ אֱמוֹרִיִּים מַטְמוֹנִיּוֹת שֶׁל זָהָב בְּקִירוֹת בָּתֵּיהֶם כָּל אַרְבָּעִים שָׁנָה שֶׁהָיוּ יִשְֹרָאֵל בַּמִּדְבָּר, וְעַל יְדֵי הַנֶּגַע נוֹתֵץ הַבַּיִת וּמוֹצְאָן (ויקרא רבה י\\\"ז):\",1,0],[2,128,14,35,\"כנגע נראה לי בבית. שֶׁאֲפִלּוּ הוּא חָכָם וְיוֹדֵעַ שֶׁהוּא נֶגַע וַדַּאי, לֹא יִפְסֹק דָּבָר בָּרוּר לוֹמַר \\\"נֶגַע נִרְאָה לִי\\\", אֶלָּא \\\"כְּנֶגַע נִרְאָה לִי\\\":\",1,0],[2,128,14,36,\"בטרם יבא הכהן וגו'. שֶׁכָּל זְמַן שֶׁאֵין כֹּהֵן נִזְקָק לוֹ, אֵין שָׁם תּוֹרַת טֻמְאָה:\",1,0],[2,128,14,36,\"ולא יטמא כל אשר בבית. שֶׁאִם לֹא יְפַנֵּהוּ, וְיָבֹא הַכֹּהֵן וְיִרְאֶה הַנֶּגַע נִזְקָק לְהֶסְגֵּר וְכָל מַה שֶּׁבְּתוֹכוֹ יִטְמָא; וְעַל מָה חָסָה תוֹרָה? אִם עַל כְּלֵי שֶׁטֶף, יַטְבִּילֵם וְיִטְהֲרוּ, וְאִם עַל אֳכָלִין וּמַשְׁקִין, יֹאכְלֵם בִּימֵי טֻמְאָתוֹ, הָא לֹא חָסָה תוֹרָה אֶלָּא עַל כְּלֵי חֶרֶס, שֶׁאֵין לָהֶם טָהֳרָה בַּמִּקְוֶה (ספרא):\",2,0],[2,128,14,37,\"שקערורת. שׁוֹקְעוֹת בְּמַרְאֵיהֶן (שם):\",1,0],[2,128,14,40,\"וחלצו את האבנים. כְּתַרְגּוּמוֹ: וִיִשְׁלְפוּן — יִטְּלֵם מִשָּׁם, כְּמוֹ וְחָלְצָה נַעֲלוֹ (דברים כ\\\"ה) — לְשׁוֹן הֲסָרָה:\",1,0],[2,128,14,40,\"אל מקום טמא. מָקוֹם שֶׁאֵין טְהָרוֹת מִשְׁתַּמְּשׁוֹת שָׁם, לִמֶּדְךָ הַכָּתוּב שֶׁהָאֲבָנִים הַלָּלוּ מְטַמְּאוֹת מְקוֹמָן בְּעוֹדָן בּוֹ (ספרא):\",2,0],[2,128,14,41,\"יקצע. רדויי\\\"ר בְּלַעַז, וּבִלְשׁוֹן מִשְׁנָה יֵשׁ הַרְבֶּה:\",1,0],[2,128,14,41,\"מבית. מִבִּפְנִים:\",2,0],[2,128,14,41,\"סביב. סְבִיבוֹת הַנֶּגַע; בְּתֹ\\\"כֹּ נִדְרַשׁ כֵּן — שֶׁיִּקְלֹף הַטִּיחַ שֶׁסְּבִיב אַבְנֵי הַנֶּגַע:\",3,0],[2,128,14,41,\"הקצו. לְשׁוֹן קָצֶה — אֲשֶׁר קִצְּעוּ בִקְצוֹת הַנֶּגַע סָבִיב:\",4,0],[2,128,14,43,\"הקצות. לְשׁוֹן הֵעָשׂוֹת, וְכֵן הִטּוֹחַ, אֲבָל חִלֵּץ אֶת הָאֲבָנִים מוּסָב הַלָּשׁוֹן אֶל הָאָדָם שֶׁחִלְּצָן, וְהוּא מִשְׁקַל לְשׁוֹן כָּבֵד, כְּמוֹ כִּפֵּר, דִּבֵּר:\",1,0],[2,128,14,43,\"ואם ישוב הנגע וגו'. יָכוֹל חָזַר בּוֹ בַיּוֹם יְהֵא טָמֵא, תַּ\\\"ל \\\"וְשָׁב הַכֹּהֵן\\\" \\\"וְאִם יָשׁוּב\\\", מַה שִּׁיבָה הָאָמוּר לְהַלָּן לְסוֹף שָׁבוּעַ, אַף שִׁיבָה הָאֲמוּרָה כָּאן בְּסוֹף שָׁבוּעַ (ספרא):\",2,0],[2,128,14,44,\"ובא הכהן וראה והנה פשה. יָכוֹל לֹא יְהֵא הַחוֹזֵר טָמֵא אֶלָּא אִם כֵּן פָּשָׂה, נֶאֱמַר צָרַעַת מַמְאֶרֶת בַּבָּתִּים, וְנֶאֱמַר צָרַעַת מַמְאֶרֶת בַּבגדים, מַה לְּהַלָּן טִמֵּא אֶת הַחוֹזֵר אַעַ\\\"פִּ שֶׁאֵינוֹ פוֹשֶׂה, אַף כָּאן טִמֵּא אֶת הַחוֹזֵר אַעַ\\\"פִּ שֶׁאֵינוֹ פוֹשֶׂה, אִם כֵּן מַה תַּ\\\"ל וְהִנֵּה פָשָׂה? אֵין כָּאן מְקוֹמוֹ שֶׁל מִקְרָא זֶה, אֶלָּא \\\"וְנָתַץ אֶת הַבַּיִת\\\" הָיָה לוֹ לִכְתֹּב אַחַר \\\"וְאִם יָשׁוּב הַנֶּגַע\\\"; \\\"וְרָאָה וְהִנֵּה פָּשָׂה\\\" הָא לֹא בָא לְלַמֵּד אֶלָּא עַל נֶגַע הָעוֹמֵד בְּעֵינָיו בְּשָׁבוּעַ רִאשׁוֹן, וּבָא בְסוֹף שָׁבוּעַ שֵׁנִי וּמְצָאוֹ שֶׁפָּשָׂה — שֶׁלֹּא פֵּרֵשׁ בּוֹ הַכָּתוּב לְמַעְלָה כְלוּם בְּעוֹמֵד בְּעֵינָיו בְּשָׁבוּעַ רִאשׁוֹן — וְלִמֶּדְךָ כָּאן בְּפִשְׂיוֹן זֶה, שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בְּעוֹמֵד בָּרִאשׁוֹן וּפָשָׂה בַשֵּׁנִי; וּמַה יַּעֲשֶׂה לּוֹ? יָכוֹל יִתְּצֶנּוּ, כְּמוֹ שֶׁסָּמַךְ לוֹ \\\"וְנָתַץ אֶת הַבַּיִת\\\", תַּ\\\"ל וְשָׁב הַכֹּהֵן, וּבָא הַכֹּהֵן, נִלְמַד בִּיאָה מִשִּׁיבָה, מַה שִּׁיבָה חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ, אַף בִּיאָה חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ, וְאִם חוֹזֵר נוֹתֵץ, לֹא חָזַר טָהוֹר. וּמִנַּיִן שֶׁאִם עָמַד בָּזֶה וּבָזֶה חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ? תַּלְמוּד לוֹמַר וְאִם בֹּא יָבֹא, בַּמֶּה הַכָּתוּב מְדַבֵּר? אִם בְּפוֹשֶׂה בָּרִאשׁוֹן, הֲרֵי כְבָר אָמוּר, אִם בְּפוֹשֶׂה בַשֵּׁנִי, הֲרֵי כְבָר אָמוּר, הָא אֵינוֹ אוֹמֵר וְאִם בֹּא יָבֹא אֶלָּא אֶת שֶׁבָּא בְסוֹף שָׁבוּעַ רִאשׁוֹן וּבָא בְסוֹף שָׁבוּעַ שֵׁנִי וְרָאָה וְהִנֵּה לֹא פָשָׂה; זֶה הָעוֹמֵד מַה יַּעֲשֶׂה לוֹ? יָכוֹל יִפָּטֵר וְיֵלֵךְ, כְּמוֹ שֶׁכָּתוּב כָּאן וְטִהַר אֶת הַבַּיִת? תַּ\\\"ל כִּי נִרְפָּא הַנָּגַע — לֹא טִהַרְתִּי אֶלָּא הָרָפוּי, מַה יַּעֲשֶׂה לוֹ? בִּיאָה אֲמוּרָה לְמַעְלָה וּבִיאָה אֲמוּרָה לְמַטָּה, מַה בָּעֶלְיוֹנָה חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ — דְּגָמַר לָהּ זֶהוּ שִׁיבָה זֶהוּ בִיאָה — אַף בַּתַּחְתּוֹנָה כֵן וְכוּ', כִּדְאִיתָא בְתוֹרַת כֹּהֲנִים. גְּמָרוֹ שֶׁל דָּבָר אֵין נְתִיצָה אֶלָּא בְּנֶגַע הַחוֹזֵר אַחַר חֲלִיצָה וְקִצּוּעַ וְטִיחָה, וְאֵין הַחוֹזֵר צָרִיךְ פִּשְׂיוֹן. וְסֵדֶר הַמִּקְרָאוֹת כָּךְ הוּא: וְאִם יָשׁוּב, וְנָתַץ, וְהַבָּא אֶל הַבַּיִת, וְהָאוֹכֵל בַּבַּיִת, וּבָא הַכֹּהֵן וְרָאָה וְהִנֵּה פָשָׂה, וְדִבֵּר הַכָּתוּב בָּעוֹמֵד בָּרִאשׁוֹן שֶׁנּוֹתֵן לוֹ שָׁבוּעַ שֵׁנִי לְהֶסְגֵּרוֹ, וּבְסוֹף שָׁבוּעַ שֵׁנִי לְהֶסְגֵּרוֹ בָּא וְרָאָהוּ שֶׁפָּשָׂה, וּמַה יַּעֲשֶֹה לוֹ? חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ, חָזַר, נוֹתֵץ, לֹא חָזַר, טָעוּן צִפֳּרִים; שֶׁאֵין בַּנְּגָעִים יוֹתֵר מִשְּׁלוֹשָׁה שָׁבוּעוֹת (עי' ספרא).\",1,0],[2,128,14,46,\"כל ימי הסגיר אתו. וְלֹא יָמִים שֶׁקָּלַף אֶת נִגְעוֹ; יָכוֹל שֶׁאֲנִי מוֹצִיא הַמֻּחְלָט שֶׁקָּלַף אֶת נִגְעוֹ, תַּ\\\"ל כָּל יְמֵי:\",1,0],[2,128,14,46,\"יטמא עד הערב. מְלַמֵּד שֶׁאֵין מְטַמֵּא בְגָדִים; יָכוֹל אֲפִלוּ שָׁהָה בִכְדֵי אֲכִילַת פְּרָס, תַּ\\\"ל וְהָאוֹכֵל בַּבַּיִת יְכַבֵּס אֶת בְּגָדָיו, אֵין לִי אֶלָּא אוֹכֵל, שׁוֹכֵב מִנַּיִן? תַּ\\\"ל וְהַשּׁוֹכֵב, אֵין לִי אֶלָּא אוֹכֵל וְשׁוֹכֵב, לֹא אוֹכֵל וְלֹא שׁוֹכֵב מִנַּיִן? תַּ\\\"ל יכבס יכבס רִבָּה; אִם כֵּן לָמָּה נֶאֱמַר אוֹכֵל וְשׁוֹכֵב? לִתֵּן שִׁעוּר לַשּׁוֹכֵב כְּדֵי אֲכִילַת פְּרָס (שם):\",2,0],[2,128,14,48,\"ואם בא יבא. לְסוֹף שָׁבוּעַ שֵׁנִי:\",1,0],[2,128,14,48,\"וראה והנה לא פשה. מִקְרָא זֶה בָּא לְלַמֵּד בָּעוֹמֵד בְּעֵינָיו בָּרִאשׁוֹן וּבַשֵּׁנִי וּמַה יַּעֲשֶׂה לוֹ, יָכוֹל יְטַהֲרֶנּוּ, כְּמַשְׁמָעוֹ שֶׁל מִקְרָא \\\"וְטִהַר הַכֹּהֵן אֶת הַבַּיִת\\\", תַּ\\\"ל כִּי נִרְפָּא הַנָּגַע — לֹא טִהַרְתִּי אֶלָּא אֶת הָרָפוּי; וְאֵין רָפוּי אֶלָּא הַבַּיִת שֶׁהֻקְצָה וְהוּטַח וְלֹא חָזַר הַנֶּגַע — אֲבָל זֶה טָעוּן חֲלִיצָה וְקִצּוּי וְטִיחָה וְשָׁבוּעַ שְׁלִישִׁי; וְכֵן הַמִּקְרָא נִדְרָשׁ: וְאִם בֹּא יָבֹא בַשֵּׁנִי, וְרָאָה וְהִנֵּה לֹא פָשָׂה, יְטִיחֶנּוּ — וְאֵין טִיחָה בְּלֹא חִלּוּץ וְקִצּוּי — וְאַחֲרֵי הִטּוֹחַ אֶת הַבַּיִת וְטִהַר הַכֹּהֵן אֶת הַבַּיִת, אִם לֹא חָזַר לְסוֹף הַשָּׁבוּעַ, כִּי נִרְפָּא הַנָּגַע, וְאִם חָזַר, כְּבָר פֵּרֵשׁ עַל הַחוֹזֵר שֶׁטָּעוּן נְתִיצָה:\",2,0],[2,128,14,57,\"להורת ביום הטמא. אֵיזֶה יוֹם מְטַהֲרוֹ וְאֵיזֶה יוֹם מְטַמְּאוֹ (עי' ספרא):\",1,0],[2,128,15,2,\"כי יהיה זב. יָכוֹל זָב מִכָּל מָקוֹם יְהֵא טָמֵא, תַּ\\\"ל מִבְּשָׂרוֹ, — וְלֹא כָל בְּשָׂרוֹ. אַחַר שֶׁחִלֵּק הַכָּתוּב בֵּין בָּשָׂר לְבָשָׂר זָכִיתִי לָדִין, טִמֵּא בְזָב וְטִמֵּא בְזָבָה, מַה זָּבָה מִמָּקוֹם שֶׁהִיא מִטַּמְּאָה טֻמְאָה קַלָּה — \\\"נִדָּה\\\" — מִטַּמְּאָה טֻמְאָה חֲמוּרָה — \\\"זִיבָה\\\" — אַף הַזָּב מִמָּקוֹם שֶׁמִּטַּמֵּא טֻמְאָה קַלָּה — \\\"קֶרִי\\\" — מִטַּמֵּא טֻמְאָה חֲמוּרָה — \\\"זִיבָה\\\" (שם):\",1,0],[2,128,15,2,\"זובו טמא. לִמֵּד עַל הַטִּפָּה שֶׁהִיא מְטַמְּאָה; זוֹב דּוֹמֶה לְמֵי בָצֵק שֶׁל שְׂעוֹרִין, וְדָחוּי, וְדּוֹמֶה לְלֹבֶן בֵּיצָה הַמּוּזֶרֶת, שִׁכְבַת זֶרַע קָשׁוּר, כְּלֹבֶן בֵּיצָה שֶׁאֵינָהּ מוּזֶרֶת:\",2,0],[2,128,15,3,\"רר. לְשׁוֹן רִיר — שֶׁזָּב בְּשָׂרוֹ אֶת זוֹבוֹ כְּמוֹ רִיר, שֶׁיּוֹצֵא צָלוּל:\",1,0],[2,128,15,3,\"או החתים. שֶׁיּוֹצֵא עָב, וְסוֹתֵם אֶת פִּי הָאַמָּה, וְנִסְתָּם בְּשָׂרוֹ מִטִּפַּת זוֹבוֹ, זֶהוּ פְּשׁוּטוֹ; וּמִדְרָשׁוֹ: מָנָה הַכָּתוּב הָרִאשׁוֹן רְאִיּוֹת שְׁתַּיִם וּקְרָאוֹ טָמֵא, שֶׁנֶּאֱמַר זָב מִבְּשָׂרוֹ זוֹבוֹ טָמֵא הוּא, וּמָנָה הַכָּתוּב הַשֵּׁנִי רְאִיּוֹת שָׁלֹשׁ וּקְרָאוֹ טָמֵא, שֶׁנֶּאֱמַר טֻמְאָתוֹ בְּזוֹבוֹ רָר בְּשָׂרוֹ אֶת זוֹבוֹ אוֹ הֶחְתִּים בְּשָׂרוֹ מִזּוֹבוֹ טֻמְאָתוֹ הִוא, הָא כֵיצַד? שְׁתַּיִם לְטֻמְאָה, וְהַשְּׁלִישִׁית מַזְקִיקַתּוּ לְקָרְבָּן (נדה מ\\\"ג: מגילה ח.):\",2,0],[2,128,15,4,\"כל המשכב. הָרָאוּי לְמִשְׁכָּב; יָכוֹל אֲפִלּוּ מְיֻחָד לִמְלָאכָה אַחֶרֶת, תַּ\\\"ל אֲשֶׁר יִשְׁכַּב — אֲשֶׁר שָׁכַב לֹא נֶאֱמַר אֶלָּא אֲשֶׁר יִשְׁכַּב — הַמְיֻחָד תָּמִיד לְכָךְ, יָצָא זֶה שֶׁאוֹמְרִין לוֹ \\\"עֲמֹד וְנַעֲשֶׂה מְלַאכְתֵּנוּ\\\":\",1,0],[2,128,15,4,\"אשר ישב. יָשַׁב לֹא נֶאֱמַר אֶלָּא אֲשֶׁר יֵשֵׁב עָלָיו, בַּמְיֻחָד תָּמִיד לְכָךְ (שבת נ\\\"ט):\",2,0],[2,128,15,5,\"ואיש אשר יגע במשכבו. לִמֵּד עַל הַמִּשְׁכָּב שֶׁחָמוּר מִן הַמַּגָּע, שֶׁזֶּה נַעֲשֶׂה אַב הַטֻּמְאָה לְטַמֵּא אָדָם לְטַמֵּא בְגָדִים, וְהַמַּגָּע שֶׁאֵינוֹ מִשְׁכָּב אֵינוֹ אֶלָּא וְלַד הַטֻּמְאָה, וְאֵינוֹ מְטַמֵּא אֶלָּא אֳכָלִין וּמַשְׁקִין (עי' ספרא):\",1,0],[2,128,15,6,\"והישב על הכלי. אֲפִלּוּ לֹא נָגַע — אֲפִלוּ עֲשָֹרָה כֵלִים זֶה עַל זֶה — כֻּלָּן מְטַמְּאִין מִשּׁוּם מוֹשָׁב, וְכֵן בְּמִשְׁכָּב:\",1,0],[2,128,15,8,\"וכי ירק הזב בטהור. וְנָגַע בּוֹ אוֹ נְשָׂאוֹ, שֶׁהָרֹק מְטַמֵּא בְמַשָּׂא (עי' נדה נ\\\"ה):\",1,0],[2,128,15,9,\"וכל המרכב. אַעַ\\\"פִּ שֶׁלֹּא יָשַׁב עָלָיו, כְּגוֹן הַתְּפוּס שֶׁל סְרָגָא, שֶׁקּוֹרִין ארצו\\\"ן, טָמֵא מִשּׁוּם מֶרְכָּב, וְהָאֻכָּף שֶׁקּוֹרִין סל\\\"ויש טָמֵא טֻמְאַת מוֹשָׁב (עירובין כ\\\"ז):\",1,0],[2,128,15,10,\"וכל הנגע בכל אשר יהיה תחתיו. שֶׁל זָב; בָּא וְלִמֵּד עַל הַמֶּרְכָּב שֶׁיְּהֵא הַנּוֹגֵעַ בּוֹ טָמֵא וְאֵין טָעוּן כִּבּוּס בְּגָדִים, וְהוּא חֹמֶר בַּמִּשְׁכָּב מִבַּמֶּרְכָּב:\",1,0],[2,128,15,10,\"והנושא אותם. אֶת כָּל הָאָמוּר בְּעִנְיַן הַזָּב — זוֹבוֹ וְרֻקּוֹ וְשִׁכְבַת זַרְעוֹ וּמֵימֵי רַגְלָיו וְהַמִּשְׁכָּב וְהַמֶּרְכָּב — מַשָּׂאָן מְטַמֵּא אָדָם לְטַמֵּא בְגָדִים (עי' ספרא):\",2,0],[2,128,15,11,\"וידיו לא שטף במים. בְּעוֹד שֶׁלֹּא טָבַל מִטֻּמְאָתוֹ, וַאֲפִלּוּ פָסַק מִזּוֹבוֹ וְסָפַר שִׁבְעָה וּמְחֻסָּר טְבִילָה, מְטַמֵּא בְכָל טֻמְאוֹתָיו, וְזֶה שֶׁהוֹצִיא הַכָּתוּב טְבִילַת גוּפוֹ שֶׁל זָב בִּלְשׁוֹן שְׁטִיפַת יָדַיִם, לְלַמֶּדְךָ שֶׁאֵין בֵּית הַסְּתָרִים טָעוּן בִּיאַת מַיִם, אֶלָּא אֵבֶר הַגָּלוּי כְּמוֹ הַיָּדַיִם (ספרא):\",1,0],[2,128,15,12,\"וכלי חרש אשר יגע בו הזב. יָכוֹל אֲפִלּוּ נָגַע בּוֹ מֵאֲחוֹרָיו וְכוּ', כִּדְאִיתָא בְתוֹרַת כֹּהֲנִים עַד \\\"מַגָּעוֹ שֶׁהוּא כְכֻלּוֹ הֱוֵי אוֹמֵר זֶה הֶסֵּטוֹ\\\":\",1,0],[2,128,15,13,\"וכי יטהר. כְּשֶׁיִּפְסֹק (שם):\",1,0],[2,128,15,13,\"שבעת ימים לטהרתו. שִׁבְעַת יָמִים טְהוֹרִים מִטֻּמְאַת זִיבָה, שֶׁלֹּא יִרְאֶה זוֹב, וְכֻלָּן רְצוּפִין (ספרא):\",2,0],[2,128,15,18,\"ורחצו במים. גְּזֵרַת מֶלֶךְ הִיא שֶׁתִּטְמָא הָאִשָּׁה בְּבִיאָה; וְאֵין הַטַּעַם מִשּׁוּם נוֹגֵעַ בְּשִׁכְבַת זֶרַע, שֶׁהֲרֵי מַגַּע בֵּית הַסְּתָרִים הוּא (נדה מ\\\"א:):\",1,0],[2,128,15,19,\"כי תהיה זבה. יָכוֹל מֵאֶחָד מִכָּל אֵבָרֶיהָ, תַּ\\\"ל וְהִיא גִּלְּתָה אֶת מְקוֹר דָּמֶיהָ — אֵין דָּם מְטַמֵּא אֶלָּא הַבָּא מִן הַמָּקוֹר:\",1,0],[2,128,15,19,\"דם יהיה זבה בבשרה. אֵין זוֹבָהּ קָרוּי זוֹב לְטַמֵּא אֶלָּא אִם כֵּן הוּא אָדֹם (שם י\\\"ט):\",2,0],[2,128,15,19,\"בנדתה. כְּמוֹ וּמִתֵּבֵל יְנִדֻּהוּ (איוב י\\\"ח) — שֶׁהִיא מְנֻדָּה מִמַּגַּע כָּל אָדָם:\",3,0],[2,128,15,19,\"תהיה בנדתה. אֲפִלּוּ לֹא רָאֲתָה אֶלָּא רְאִיָּה רִאשׁוֹנָה (ספרא):\",4,0],[2,128,15,23,\"ואם על המשכב הוא. הַשּׁוֹכֵב אוֹ הַיּוֹשֵׁב עַל מִשְׁכָּבָהּ אוֹ עַל מוֹשָׁבָהּ אֲפִלּוּ לֹא נָגַע בָּהּ, אַף הוּא בְּדַת טֻמְאָה הָאֲמוּרָה בַּמִקְרָא הָעֶלְיוֹן, שֶׁטָּעוּן כִּבּוּס בְּגָדִים:\",1,0],[2,128,15,23,\"על הכלי. לְרַבּוֹת אֶת הַמֶּרְכָּב:\",2,0],[2,128,15,23,\"בנגעו בו. אֵינוֹ מְדַבֵּר אֶלָּא עַל הַמֶּרְכָּב שֶׁנִּתְרַבָּה מֵ\\\"עַל הַכְּלִי\\\":\",3,0],[2,128,15,23,\"בנגעו בו יטמא. וְאֵינוֹ טָעוּן כִּבּוּס בְּגָדִים, שֶׁהַמֶּרְכָּב אֵין מַגָּעוֹ מְטַמֵּא אָדָם לְטַמֵּא בְגָדִים (כלים פכ\\\"ג):\",4,0],[2,128,15,24,\"ותהי נדתה עליו. יָכוֹל יַעֲלֶה לְרַגְלָהּ — שֶׁאִם בָּא עָלֶיהָ בַחֲמִישִׁי לְנִדָּתָהּ לֹא יִטְמָא אֶלָּא שְׁלוֹשָׁה יָמִים כְּמוֹתָהּ — תַּ\\\"ל וְטָמֵא שִׁבְעַת יָמִים, וּמַה תַּ\\\"ל וּתְהִי נִדָּתָהּ עָלָיו? מַה הִיא מְטַמְּאָה אָדָם וּכְלֵי חֶרֶס, אַף הוּא מְטַמֵּא אָדָם וּכְלֵי חֶרֶס (ספרא; נדה ל\\\"ג):\",1,0],[2,128,15,25,\"ימים רבים. שְׁלֹשָׁה יָמִים (ספרא):\",1,0],[2,128,15,25,\"בלא עת נדתה. אַחַר שֶׁיָּצְאוּ שִׁבְעַת יְמֵי נִדָּתָהּ:\",2,0],[2,128,15,25,\"או כי תזוב. אֶת שְׁלֹשֶׁת הַיָּמִים הַלָּלוּ:\",3,0],[2,128,15,25,\"על נדתה. מֻפְלָג מִנִּדָּתָהּ יוֹם אֶחָד, זוֹ הִיא זָבָה, וּמִשְׁפָּטָהּ חָרוּץ בְּפָרָשָׁה זוֹ, וְלֹא כְּדַת הַנִּדָּה, שֶׁזּוֹ טְעוּנָה סְפִירַת שִׁבְעָה נְקִיִּים וְקָרְבָּן, וְהַנִּדָּה אֵינָהּ טְעוּנָה סְפִירַת נְקִיִּים, אֶלָּא שִׁבְעַת יָמִים תִּהְיֶה בְנִדָּתָהּ בֵּין רוֹאָה בֵּין שֶׁאֵינָהּ רוֹאָה. וְדָרְשׁוּ בְּפָרָשָׁה זוֹ י\\\"א יוֹם בֵּין סוֹף נִדָּה לִתְחִלַּת נִדָּה, שֶׁכָּל שְׁלֹשֶׁת רְצוּפִין שֶׁתִּרְאֶה בְאַחַד עָשָׂר יוֹם הַלָּלוּ תְּהֵא זָבָה:\",4,0],[2,128,15,31,\"והזרתם. אֵין נְזִירָה אֶלָּא פְרִישָׁה וְכֵן נָזֹרוּ אָחוֹר (ישעיהו א'), וְכֵן נְזִיר אֶחָיו (בראשית מ\\\"ט):\",1,0],[2,128,15,31,\"ולא ימתו בטמאתם. הֲרֵי הִכָּרֵת שֶׁל מְטַמֵּא מִקְדָּשׁ קָרוּי מִיתָה:\",2,0],[2,128,15,32,\"זאת תורת הזב. בַּעַל רְאִיָּה אַחַת, וּמַהוּ תוֹרָתוֹ?\",1,0],[2,128,15,32,\"ואשר תצא ממנו שכבת זרע — הֲרֵי הוּא כְּבַעַל קֶרִי, טָמֵא טֻמְאַת עֶרֶב:\",2,0],[2,128,15,33,\"והזב את זובו. בַּעַל שְׁתֵּי רְאִיּוֹת, וּבַעַל שָׁלוֹשׁ רְאִיּוֹת, שֶׁתּוֹרָתָן מְפֹרֶשֶׁת לְמַעְלָה:\",1,0],[2,128,16,1,\"וידבר ה' אל משה אחרי מות שני בני אהרן וגו'. מַה תַּ\\\"ל? הָיָה רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה מוֹשְׁלוֹ מָשָׁל לְחוֹלֶה שֶׁנִּכְנָס אֶצְלוֹ רוֹפֵא, אָמַר לוֹ אַל תֹּאכַל צוֹנֵן וְאַל תִּשְׁכַּב בְּטַחַב; בָּא אַחֵר וְאָמַר לוֹ אַל תֹּאכַל צוֹנֵן וְאַל תִּשְׁכַּב בְּטַחַב שֶׁלֹּא תָמוּת כְּדֶרֶךְ שֶׁמֵּת פְּלוֹנִי, זֶה זֵרְזוֹ יוֹתֵר מִן הָרִאשׁוֹן, לְכָךְ נֶאֱמַר אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן:\",1,0],[2,128,16,2,\"ויאמר ה' אל משה דבר אל אהרן אחיך ואל יבא. שֶׁלֹּא יָמוּת כְּדֶרֶךְ שֶׁמֵּתוּ בָנָיו:\",1,0],[2,128,16,2,\"ולא ימות. שֶׁאִם בָּא הוּא מֵת (ספרא):\",2,0],[2,128,16,2,\"כי בענן אראה. כִּי תָמִיד אֲנִי נִרְאֶה שָׁם עִם עַמּוּד עֲנָנִי, וּלְפִי שֶׁגִּלּוּי שְׁכִינָתִי שָׁם, יִזָּהֵר שֶׁלֹּא יַרְגִּיל לָבֹא, זֶהוּ פְשׁוּטוֹ; וּמִדְרָשׁוֹ: לֹא יָבֹא כִּי אִם בַּעֲנַן הַקְּטֹרֶת בְּיוֹם הַכִּפּוּרִים (יומא נ\\\"ג):\",3,0],[2,128,16,3,\"בזאת. גִּימַטְרִיָּא שֶׁלּוֹ אַרְבַּע מֵאוֹת וְעֶשֶׂר, רֶמֶז לְבַיִת רִאשׁוֹן (ויקרא רבה כ\\\"א):\",1,0],[2,128,16,3,\"בזאת יבא אהרן וגומר. וְאַף זוֹ לֹא בְכָל עֵת, כִּי אִם בְּיוֹם הַכִּפּוּרִים, כְּמוֹ שֶׁמְּפֹרָשׁ בְּסוֹף הַפָּרָשָׁה \\\"בַּחֹדֶשׁ הַשְּׁבִיעִי בֶּעָשׂוֹר לַחֹדֶשׁ\\\" (שם):\",2,0],[2,128,16,4,\"כתנת בד וגו'. מַגִּיד שֶׁאֵינוֹ מְשַׁמֵּשׁ לִפְנִים בִּשְׁמוֹנָה בְגָדִים שֶׁהוּא מְשַׁמֵּשׁ בָּהֶן בַּחוּץ, שֶׁיֵּשׁ בָּהֶם זָהָב, לְפִי שֶׁאֵין קָטֵגוֹר נַעֲשֶׂה סָנֵגוֹר, אֶלָּא בְּאַרְבָּעָה כְּכֹהֵן הֶדְיוֹט — וְכֻלָּן שֶׁל בּוּץ (ראש השנה כ\\\"ו):\",1,0],[2,128,16,4,\"קדש ילבש. שֶׁיִּהְיוּ מִשֶּׁל הֶקְדֵּשׁ (ספרא):\",2,0],[2,128,16,4,\"יצנף. כְּתַרְגּוּמוֹ, יָחֵת בְּרֵישֵׁיהּ — יַנִּיחַ בְּרֹאשׁוֹ, כְּמוֹ וַתַּנַּח בִּגְדוֹ (בראשית ל\\\"ט) — וַאֲחִתְּתֵהּ:\",3,0],[2,128,16,4,\"ורחץ במים. אוֹתוֹ הַיּוֹם טָעוּן טְבִילָה בְּכָל חֲלִיפוֹתָיו; וְחָמֵשׁ פְּעָמִים הָיָה מַחֲלִיף מֵעֲבוֹדַת פְּנִים לַעֲבוֹדַת חוּץ, וּמִחוּץ לִפְנִים, וּמְשַׁנֶּה מִבִּגְדֵי זָהָב לְבִגְדֵי לָבָן וּמִבִּגְדֵי לָבָן לְבִגְדֵי זָהָב, וּבְכָל חֲלִיפָה טָעוּן טְבִילָה וּשְׁנֵי קִדּוּשֵׁי יָדַיִם וְרַגְלַיִם מִן הַכִּיּוֹר (יומא ל\\\"א):\",4,0],[2,128,16,6,\"את פר החטאת אשר לו. הָאָמוּר לְמַעְלָה, וְלִמֶּדְךָ כָּאן שֶׁמִּשֶּׁלּוֹ הוּא בָא וְלֹא מִשֶּׁל צִבּוּר (שם ג'):\",1,0],[2,128,16,6,\"וכפר בעדו ובעד ביתו. מִתְוַדֶּה עָלָיו עֲוֹנוֹתָיו וַעֲוֹנוֹת בֵּיתוֹ (שם ל\\\"ו):\",2,0],[2,128,16,8,\"ונתן אהרן על שני השעירם גרלות. מַעֲמִיד אֶחָד לְיָמִין וְאֶחָד לִשְׂמֹאל, וְנוֹתֵן שְׁתֵּי יָדָיו בַּקַּלְפִּי, וְנוֹטֵל גּוֹרָל בְּיָמִין וַחֲבֵרוֹ בִּשְׂמֹאל וְנוֹתֵן עֲלֵיהֶם, אֶת שֶׁכָּתוּב בּוֹ \\\"לַשֵּׁם\\\" הוּא לַשֵּׁם, וְאֶת שֶׁכָּתוּב בּוֹ \\\"לַעֲזָאזֵל\\\" מִשְׁתַּלֵּחַ לַעֲזָאזֵל (יומא ל\\\"ט):\",1,0],[2,128,16,8,\"עזאזל. הוּא הַר עַז וְקָשֶׁה, צוּק גָּבוֹהַּ, שֶׁנֶּאֱמַר אֶרֶץ גְזֵרָה — חֲתוּכָה:\",2,0],[2,128,16,9,\"ועשהו חטאת. כְּשֶׁמַּנִיחַ הַגּוֹרָל עָלָיו קוֹרֵא לוֹ שֵׁם וְאוֹמֵר \\\"לַה' חַטָּאת\\\":\",1,0],[2,128,16,10,\"יעמד חי. כְּמוֹ יֻעֲמַד חַי — עַל יְדֵי אֲחֵרִים, וְתַרְגּוּמוֹ יִתָּקַם כַּד חַי; מַה תַּ\\\"ל? לְפִי שֶׁנֶּאֱמַר לְשַׁלֵּחַ אֹתוֹ לַעֲזָאזֵל וְאֵינִי יוֹדֵעַ שִׁלּוּחוֹ אִם לְמִיתָה אִם לְחַיִּים, לְכָךְ נֶאֱמַר יָעֳמַד חַי, עֲמִידָתוֹ חַי עַד שֶׁיִּשְׁתַּלֵּחַ, מִכָּאן שֶׁשִּׁלּוּחוֹ לְמִיתָה (ספרא):\",1,0],[2,128,16,10,\"לכפר עליו. שֶׁיִּתְוַדֶּה עָלָיו, כְּדִכְתִיב \\\"וְהִתְוַדָּה עָלָיו\\\" וְגוֹ':\",2,0],[2,128,16,11,\"וכפר בעדו וגו'. וִדּוּי שֵׁנִי, עָלָיו וְעַל אֶחָיו הַכֹּהֲנִים, שֶׁהֵם כֻּלָּם קְרוּיִים בֵּיתוֹ, שֶׁנֶּאֱמַר \\\"בֵּית אַהֲרֹן בָּרֲכוּ אֶת ה'\\\" וְגוֹ' (תהילים קל\\\"ה), מִכָּאן שֶׁהַכֹּהֲנִים מִתְכַּפְּרִין בּוֹ, וְכָל כַּפָּרָתָן אֵינָהּ אֶלָּא עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו, כְּמוֹ שֶׁנֶּאֱמַר (פסוק ט\\\"ז), \\\"וְכִפֶּר עַל הַקֹּדֶשׁ מִטֻּמְאֹת\\\" וְגוֹ' (ספרא; שבועות ז'):\",1,0],[2,128,16,12,\"מעל המזבח. הַחִיצוֹן:\",1,0],[2,128,16,12,\"מלפני ה'. מִצַּד שֶׁלִּפְנֵי הַפֶּתַח, וְהוּא צַד מַעֲרָבִי:\",2,0],[2,128,16,12,\"דקה. מַה תַּ\\\"ל דַּקָּה? וַהֲלֹא כָל הַקְּטֹרֶת דַּקָּה הִיא, שֶׁנֶּאֱמַר וְשָׁחַקְתָּ מִמֶּנָּה הָדֵק (שמות ל\\\"ו), אֶלָּא שֶׁתְּהֵא דַּקָּה מִן הַדַּקָּה, שֶׁבְּעֶרֶב יֹהַ\\\"כִּ הָיָה מַחֲזִירָהּ לַמַּכְתֶּשֶׁת (כריתות ו'):\",3,0],[2,128,16,13,\"על האש. שֶׁבְּתוֹךְ הַמַּחְתָּה:\",1,0],[2,128,16,13,\"ולא ימות. הָא אִם לֹא עֲשָֹאָהּ כְּתִקְנָהּ חַיָּב מִיתָה (ספרא):\",2,0],[2,128,16,14,\"והזה באצבעו. הַזָּאָה אַחַת בְּמַשְׁמָע:\",1,0],[2,128,16,14,\"ולפני הכפרת יזה שבע. הֲרֵי אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה (שם):\",2,0],[2,128,16,15,\"אשר לעם. מַה שֶּׁהַפָּר מְכַפֵּר עַל הַכֹּהֲנִים מְכַפֵּר הַשָּׂעִיר עַל יִשְׂרָאֵל, וְהוּא הַשָּׂעִיר שֶׁעָלָה עָלָיו הַגּוֹרָל לַשֵּׁם (שבועות ב'):\",1,0],[2,128,16,15,\"כאשר עשה לדם הפר. אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה:\",2,0],[2,128,16,16,\"מטמאת בני ישראל. עַל הַנִּכְנָסִין לַמִּקְדָּשׁ בְּטֻמְאָה וְלֹא נוֹדַע לָהֶם בַּסּוֹף, שֶׁנֶּאֱמַר לכל חטאתם, וְחַטָּאת הִיא שׁוֹגֵג.\",1,0],[2,128,16,16,\"ומפשעיהם. אַף הַנִּכְנָסִין מֵזִיד בְּטֻמְאָה (שם ז'):\",2,0],[2,128,16,16,\"וכן יעשה לאהל מועד. כְּשֵׁם שֶׁהִזָּה מִשְּׁנֵיהֶם בִּפְנִים אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה, כָּךְ מַזֶּה עַל הַפָּרֹכֶת מִבַּחוּץ מִשְּׁנֵיהֶם אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה (ספרא; יומא נ\\\"ו):\",3,0],[2,128,16,16,\"השכן אתם בתוך טמאתם. אַעַ\\\"פִּי שֶׁהֵם טְמֵאִים שְׁכִינָה בֵינֵיהֶם (שם):\",4,0],[2,128,16,18,\"אל המזבח אשר לפני ה'. זֶה מִזְבַּח הַזָּהָב שֶׁהוּא לִפְנֵי ה' — בַּהֵיכָל, וּמַה תַּ\\\"ל וְיָצָא? לְפִי שֶׁהִזָּה הַהַזָּאוֹת עַל הַפָּרֹכֶת וְעָמַד מִן הַמִּזְבֵּחַ וְלִפְנִים וְהִזָּה, וּבְמַתְּנוֹת הַמִּזְבֵּחַ הִזְקִיקוֹ לָצֵאת מִן הַמִּזְבֵּחַ וְלַחוּץ וְיַתְחִיל מִקֶּרֶן מִזְרָחִית צְפוֹנִית (יומא נ\\\"ח):\",1,0],[2,128,16,18,\"וכפר עליו. מַה הִיא כַפָּרָתוֹ? ולקח מדם הפר ומדם השעיר מְעֹרָבִין זֶה לְתוֹךְ זֶה (שם נ\\\"ז):\",2,0],[2,128,16,19,\"והזה עליו מן הדם. אַחַר שֶׁנָּתַן מַתָּנוֹת בְּאֶצְבָּעוֹ עַל קַרְנוֹתָיו מַזֶּה שֶׁבַע הַזָּאוֹת עַל גַּגּוֹ:\",1,0],[2,128,16,19,\"וטהרו. מִמַּה שֶּׁעָבָר:\",2,0],[2,128,16,19,\"וקדשו. לֶעָתִיד לָבֹא (ספרא):\",3,0],[2,128,16,21,\"איש עתי. הַמּוּכָן לְכָךְ מִיּוֹם אֶתְמוֹל:\",1,0],[2,128,16,23,\"ובא אהרן אל אהל מועד. אָמְרוּ רַבּוֹתֵינוּ שֶׁאֵין זֶה מְקוֹמוֹ שֶׁל מִקְרָא זֶה וְנָתְנוּ טַעַם לְדִבְרֵיהֶם בְּמַסֶּכֶת יוֹמָא (דף ל\\\"ב), וְאָמְרוּ: כָּל הַפָּרָשָׁה כֻּלָּהּ נֶאֶמְרָה עַל הַסֵּדֶר חוּץ מִבִּיאָה זוֹ שֶׁהִיא אַחַר עֲשִֹיַּת עוֹלָתוֹ וְעוֹלַת הָעָם, וְהַקְטָרַת אֵמוּרֵי פַּר וְשָֹעִיר, שֶׁנַּעֲשִֹים בַּחוּץ בְּבִגְדֵי זָהָב, וְטוֹבֵל וּמְקַדֵּשׁ וּפוֹשְׁטָן וְלוֹבֵשׁ בִּגְדֵי לָבָן, ובא אל אהל מועד לְהוֹצִיא אֶת הַכַּף וְאֶת הַמַּחְתָּה שֶׁהִקְטִיר בָּהּ הַקְּטֹרֶת לִפְנַי וְלִפְנִים:\",1,0],[2,128,16,23,\"ופשט את בגדי הבד. אַחַר שֶׁהוֹצִיאָהּ, וְלוֹבֵשׁ בִּגְדֵי זָהָב לְתָמִיד שֶׁל בֵּין הָעַרְבַּיִם; וְזֶהוּ סֵדֶר הָעֲבוֹדוֹת: תָּמִיד שֶׁל שַׁחַר בְּבִגְדֵי זָהָב, וַעֲבוֹדַת פַּר וְשָׂעִיר הַפְּנִימִיִּים וּקְטֹרֶת שֶׁל מַחְתָּה בְּבִגְדֵי לָבָן, וְאֵילוֹ וְאֵיל הָעָם וּמִקְצַת הַמּוּסָפִין בְּבִגְדֵי זָהָב, וְהוֹצָאַת כַּף וּמַחְתָּה בְּבִגְדֵי לָבָן, וּשְׁיָרֵי הַמּוּסָפִין וְתָמִיד שֶׁל בֵּין הָעַרְבַּיִם וּקְטֹרֶת הַהֵיכָל שֶׁעַל מִזְבֵּחַ הַפְּנִימִי בְּבִגְדֵי זָהָב; וְסֵדֶר הַמִּקְרָאוֹת לְפִי הָעֲבוֹדוֹת כָּךְ הוּא: וְשִׁלַּח אֶת הַשָּׂעִיר בַּמִּדְבָּר, וְרָחַץ אֶת בְּשָׂרוֹ בַמַּיִם וְגוֹ', וְיָצָא וְעָשָׂה אֶת עֹלָתוֹ וְגוֹ', וְאֵת חֵלֶב הַחַטָּאת וְגוֹ', וְכָל הַפָּרָשָׁה עַד וְאַחֲרֵי כֵן יָבוֹא אֶל הַמַּחֲנֶה — וְאַחַר כָּךְ וּבָא אַהֲרֹן:\",2,0],[2,128,16,23,\"והניחם שם. מְלַמֵּד שֶׁטְּעוּנִין גְּנִיזָה וְלֹא יִשְׁתַּמֵּשׁ בְּאוֹתָן ד' בְגָדִים לְיוֹם הַכִּפּוּרִים אַחֵר (יומא י\\\"ב):\",3,0],[2,128,16,24,\"ורחץ את בשרו וגו'. לְמַעְלָה לָמַדְנוּ מִ\\\"וְרָחַץ אֶת בְּשָֹרוֹ וּלְבֵשָׁם\\\" שֶׁכְּשֶׁהוּא מְשַׁנֶּה מִבִּגְדֵי זָהָב לְבִגְדֵי לָבָן טָעוּן טְבִילָה, — שֶׁבְּאוֹתָהּ טְבִילָה פָשַׁט בִּגְדֵי זָהָב שֶׁעָבַד בָּהֶן עֲבוֹדַת תָּמִיד שֶׁל שַׁחַר וְלוֹבֵשׁ בִּגְדֵי לָבָן לַעֲבוֹדַת הַיּוֹם, — וְכָאן לָמַדְנוּ שֶׁכְּשֶׁהוּא מְשַׁנֶּה מִבִּגְדֵי לָבָן לְבִגְדֵי זָהָב טָעוּן טְבִילָה (שם ל\\\"ב):\",1,0],[2,128,16,24,\"במקום קדוש. הַמְקֻדָּשׁ בִּקְדֻשַּׁת עֲזָרָה; וְהִיא הָיְתָה בְגַג בֵּית הַפַּרְוָה, וְכֵן אַרְבַּע טְבִילוֹת הַבָּאוֹת חוֹבָה לַיּוֹם, אֲבָל הָרִאשׁוֹנָה הָיְתָה בַחֹל (שם י\\\"ט):\",2,0],[2,128,16,24,\"ולבש את בגדיו. שְׁמוֹנָה בְגָדִים שֶׁהוּא עוֹבֵד בָּהֶן כָּל יְמוֹת הַשָּׁנָה:\",3,0],[2,128,16,24,\"ויצא. מִן הַהֵיכָל אֶל הֶחָצֵר שֶׁמִּזְבַּח הָעוֹלָה שָׁם:\",4,0],[2,128,16,24,\"ועשה את עלתו. אַיִל לְעוֹלָה הָאָמוּר לְמַעְלָה:\",5,0],[2,128,16,24,\"ואת עלת העם. וְאַיִל אֶחָד לְעוֹלָה הָאָמוּר לְמַעְלָה \\\"וּמֵאֵת עַדַת בְּנֵי יִשְֹרָאֵל\\\" וְגוֹ':\",6,0],[2,128,16,25,\"ואת חלב החטאת. אֵמוּרֵי פַּר וְשָׂעִיר:\",1,0],[2,128,16,25,\"יקטיר המזבחה. עַל מִזְבֵּחַ הַחִיצוֹן, דְּאִלּוּ בַּפְּנִימִי כְתִיב לֹא תַעֲלוּ עָלָיו קְטֹרֶת זָרָה וְעֹלָה וּמִנְחָה (שמות ל'):\",2,0],[2,128,16,27,\"אשר הובא את דמם. לַהֵיכָל וְלִפְנַי וְלִפְנִים:\",1,0],[2,128,16,32,\"וכפר הכהן אשר ימשח וגו'. כַּפָּרָה זוֹ שֶׁל יוֹם הַכִּפּוּרִים אֵינָהּ כְּשֵׁרָה אֶלָּא בְּכֹהֵן גָּדוֹל (יומא ע\\\"ג); לְפִי שֶׁנֶּאֶמְרָה כָל הַפָּרָשָׁה בְּאַהֲרֹן, הֻצְרַךְ לוֹמַר בְּכֹהֵן גָּדוֹל הַבָּא אַחֲרָיו שֶׁיְּהֵא כָמוֹהוּ:\",1,0],[2,128,16,32,\"ואשר ימלא את ידו. אֵין לִי אֶלָּא הַמָּשׁוּחַ בְּשֶׁמֶן הַמִּשְׁחָה, מְרֻבֵּה בְגָדִים מִנַּיִן? תַּ\\\"ל וַאֲשֶׁר יְמַלֵּא אֶת יָדוֹ וְגוֹמֵר; וְהֵם כָּל הַכֹּהֲנִים גְּדוֹלִים שֶׁעָמְדוּ מִיֹּאשִׁיָּהוּ וָאֵילָךְ, שֶׁבְּיָמָיו נִגְנְזָה צְלוֹחִית שֶׁל שֶׁמֶן הַמִּשְׁחָה (הוריות י\\\"ב):\",2,0],[2,128,16,32,\"לכהן תחת אביו. לְלַמֵּד שֶׁאִם בְּנוֹ מְמַלֵּא אֶת מְקוֹמוֹ, הוּא קוֹדֵם לְכָל אָדָם (ספרא):\",3,0],[2,128,16,34,\"ויעש כאשר צוה וגו'. כְּשֶׁהִגִּיעַ יוֹם הַכִּפּוּרִים עָשָֹה כַּסֵּדֶר הַזֶּה; וּלְהַגִּיד שִׁבְחוֹ שֶׁל אַהֲרֹן, שֶׁלֹּא הָיָה לוֹבְשָׁן לִגְדֻלָּתוֹ אֶלָּא כִּמְקַיֵּם גְּזֵרַת הַמֶּלֶךְ (שם):\",1,0],[2,128,17,3,\"אשר ישחט שור או כשב. בַּמֻּקְדָּשִׁין הַכָּתוּב מְדַבֵּר, שֶׁנֶּאֱמַר \\\"לְהַקְרִיב קָרְבָּן\\\" (זבחים ק\\\"ז):\",1,0],[2,128,17,3,\"במחנה. חוּץ לָעֲזָרָה:\",2,0],[2,128,17,4,\"דם יחשב. כְּשׁוֹפֵךְ דַּם הָאָדָם שֶׁמִּתְחַיֵּב בְּנַפְשׁוֹ:\",1,0],[2,128,17,4,\"דם שפך. לְרַבּוֹת אֶת הַזּוֹרֵק דָּמִים בַּחוּץ (שם):\",2,0],[2,128,17,5,\"אשר הם זבחים. אֲשֶׁר הֵם רְגִילִים לִזְבֹּחַ:\",1,0],[2,128,17,7,\"לשעירם. לַשֵּׁדִים, כְּמוֹ וּשְֹעִירִים יְרַקְּדוּ שָׁם (ישעיהו י\\\"ג):\",1,0],[2,128,17,8,\"אשר יעלה עלה. לְחַיֵּב עַל הַמַּקְטִיר אֵבָרִים בַּחוּץ כְּשׁוֹחֵט בַּחוּץ, שֶׁאִם שָׁחַט אֶחָד וְהֶעֱלָה חֲבֵרוֹ שְׁנֵיהֶם חַיָּבִין (זבחים ק\\\"ו):\",1,0],[2,128,17,9,\"ונכרת. זַרְעוֹ נִכְרָת וְיָמָיו נִכְרָתִין:\",1,0],[2,128,17,10,\"כל דם. לְפִי שֶׁנֶּאֱמַר \\\"בַּנֶּפֶשׁ יְכַפֵּר\\\", יָכוֹל לֹא יְהֵא חַיָּב אֶלָּא עַל דַּם הַמֻּקְדָּשִׁים, תַּ\\\"ל \\\"כָּל דָּם\\\":\",1,0],[2,128,17,10,\"ונתתי פני. פְּנַאי שֶׁלִּי — פּוֹנֶה אֲנִי מִכָּל עֲסָקַי וְעוֹסֵק בּוֹ (ספרא):\",2,0],[2,128,17,11,\"כי נפש הבשר. שֶׁל כָּל בְּרִיָּה בַּדָּם הִיא תְלוּיָה, וּלְפִיכָךְ נְתַתִּיו (עַל הַמִּזְבֵּחַ) לְכַפֵּר עַל נֶפֶשׁ הָאָדָם — תָּבֹא נֶפֶשׁ וּתְכַפֵּר עַל הַנֶּפֶשׁ:\",1,0],[2,128,17,12,\"כל נפש מכם. לְהַזְהִיר גְּדוֹלִים עַל הַקְּטַנִּים:\",1,0],[2,128,17,13,\"אשר יצוד. אֵין לִי אֶלָּא צַיִד, אֲוָזִין וְתַרְנְגוֹלִין מִנַּיִן? תַּ\\\"ל \\\"צֵיד\\\" מִכָּל מָקוֹם; אִם כֵּן לָמָּה נֶאֱמַר \\\"אֲשֶׁר יָצוּד\\\"? שֶׁלֹּא יֹאכַל בָּשָׂר אֶלָּא בַּהַזְמָנָה הַזֹּאת (חולין פ\\\"ד):\",1,0],[2,128,17,13,\"אשר יאכל. פְּרָט לִטְמֵאִים (שם פ\\\"ה):\",2,0],[2,128,17,14,\"דמו בנפשו הוא. דָּמוֹ הוּא לוֹ בִּמְקוֹם הַנֶּפֶשׁ, שֶׁהַנֶּפֶשׁ תְּלוּיָה בוֹ:\",1,0],[2,128,17,14,\"כי נפש כל בשר דמו הוא. הַנֶּפֶשׁ הִיא הַדָּם. דָּם וּבָשָׂר לְשׁוֹן זָכָר, נֶפֶשׁ לְשׁוֹן נְקֵבָה:\",2,0],[2,128,17,15,\"אשר תאכל נבלה וטרפה. בְּנִבְלַת עוֹף טָהוֹר דִּבֵּר הַכָּתוּב, שֶׁאֵין לָהּ טֻמְאָה אֶלָּא בְשָׁעָה שֶׁנִּבְלַעַת בְּבֵית הַבְּלִיעָה, וְלִמֶּדְךָ כָּאן שֶׁמְּטַמְּאָה בַאֲכִילָתָהּ (וְאֵינָהּ מְטַמְּאָה בְמַגָּע); וּטְרֵפָה הָאֲמוּרָה כָּאן לֹא נִכְתַּב אֶלָּא לִדְרֹשׁ, וְכֵן שָׁנִינוּ: יָכוֹל תְּהֵא נִבְלַת עוֹף טָמֵא מְטַמְּאָה בְּבֵית הַבְּלִיעָה, תַּ\\\"ל טְרֵפָה — מִי שֶׁיֵּשׁ בְּמִינוֹ טְרֵפָה, יָצָא עוֹף טָמֵא שֶׁאֵין בְּמִינוֹ טְרֵפָה (ספרא; זבחים ע'):\",1,0],[2,128,17,16,\"ונשא עונו. אִם יֹאכַל קֹדֶשׁ אוֹ יִכָּנֵס לַמִּקְדָּשׁ חַיָּב עַל טֻמְאָה זוֹ כְּכָל שְׁאָר טֻמְאוֹת (ספרא):\",1,0],[2,128,17,16,\"ובשרו לא ירחץ ונשא עונו. עַל רְחִיצַת גּוּפוֹ עָנוּשׁ כָּרֵת וְעַל כִּבּוּס בְּגָדִים בְּמַלְקוּת (שם):\",2,0],[2,128,18,2,\"אני ה' אלהיכם. אֲנִי הוּא שֶׁאָמַרְתִּי בְסִינַי אָנֹכִי ה' אֱלֹהֶיךָ וְקִבַּלְתֶּם עֲלֵיכֶם מַלְכוּתִי, מֵעַתָּה קַבְּלוּ גְזֵרוֹתָי; רַבִּי אוֹמֵר גָּלוּי וְיָדוּעַ לְפָנָיו שֶׁסּוֹפָן לִנָּתֵק בַּעֲרָיוֹת בִּימֵי עֶזְרָא, לְפִיכָךְ בָּא עֲלֵיהֶם בִּגְזֵרָה אני ה' אלהיכם — דְּעוּ מִי גוֹזֵר עֲלֵיכֶם, דַּיָּן לִפָּרַע וְנֶאֱמָן לְשַׁלֵּם שָׂכָר (עי' ספרא):\",1,0],[2,128,18,3,\"כמעשה ארץ מצרים. מַגִּיד שֶׁמַּעֲשֵׂיהֶם שֶׁל מִצְרִיִּים וְשֶׁל כְּנַעֲנִיִּים מְקֻלְקָלִים מִכָּל הָאֻמּוֹת, וְאוֹתוֹ מָקוֹם שֶׁיָּשְׁבוּ בוֹ יִשְׂרָאֵל מְקֻלְקָל מִן הַכֹּל:\",1,0],[2,128,18,3,\"אשר אני מביא אתכם שמה. מַגִּיד שֶׁאוֹתָן עֲמָמִין שֶׁכִּבְּשׁוּ יִשְֹרָאֵל מְקֻלְקָלִים מִכֻּלָּם (שם):\",2,0],[2,128,18,3,\"ובחקתיהם לא תלכו. מַה הִנִּיחַ הַכָּתוּב שֶׁלֹּא אָמַר? אֶלָּא אֵלּוּ נִימוֹסוֹת שֶׁלָּהֶן — דְּבָרִים הַחֲקוּקִין לָהֶם — כְּגוֹן טַרְטִיָּאוֹת וְאִצְטַדִיָּאוֹת, רַבִּי מֵאִיר אוֹמֵר, אֵלּוּ דַּרְכֵי הָאֱמוֹרִי שֶׁמָּנוּ חֲכָמִים (שם):\",3,0],[2,128,18,4,\"את משפטי תעשו. אֵלּוּ דְּבָרִים הָאֲמוּרִים בַּתּוֹרָה בְּמִשְׁפָּט, שֶׁאִלּוּ לֹא נֶאֶמְרוּ הָיוּ כְדַאי לְאָמְרָן:\",1,0],[2,128,18,4,\"ואת חקתי תשמרו. דְּבָרִים שֶׁהֵן גְּזֵרַת הַמֶּלֶךְ, שֶׁיֵּצֶר הָרַע מֵשִׁיב עֲלֵיהֶם לָמָּה לָנוּ לְשָׁמְרָן? וְאֻמּוֹת הָעוֹלָם מְשִׁיבִין עֲלֵיהֶם, כְּגוֹן אֲכִילַת חֲזִיר וּלְבִישַׁת שַׁעַטְנֵז וְטָהֳרַת מֵי חַטָּאת, לְכָךְ נֶאֱמַר אני ה', גָּזַרְתִּי עֲלֵיכֶם, אֵי אַתָּה רַשַּׁאי לִפָּטֵר (יומא ס\\\"ז):\",2,0],[2,128,18,4,\"ללכת בהם. אַל תִּפָּטֵר מִתּוֹכָם, שֶׁלֹּא תֹאמַר לָמַדְתִּי חָכְמַת יִשְׂרָאֵל אֵלֵךְ וְאֶלְמַד חָכְמַת הָאֻמּוֹת (ספרא):\",3,0],[2,128,18,5,\"ושמרתם את חקתי וגו'. לְרַבּוֹת שְׁאָר דִּקְדּוּקֵי הַפָּרָשָׁה, שֶׁלֹּא פֵּרֵט הַכָּתוּב בָּהֶם; דָּבָר אַחֵר לִתֵּן שְׁמִירָה וַעֲשִׂיָּה לַחֻקִּים וּשְׁמִירָה וַעֲשִׂיָּה לַמִּשְׁפָּטִים, לְפִי שֶׁלֹּא נָתַן אֶלָּא עֲשִׂיָּה לַמִּשְׁפָּטִים וּשְׁמִירָה לַחֻקִּים (ספרא):\",1,0],[2,128,18,5,\"וחי בהם. לָעוֹלָם הַבָּא, שֶׁאִם תֹּאמַר בָּעוֹלָם הַזֶּה וַהֲלֹא סוֹפוֹ הוּא מֵת (שם):\",2,0],[2,128,18,5,\"אני ה'. נֶאֱמָן לְשַׁלֵּם שָׂכָר (שם):\",3,0],[2,128,18,6,\"לא תקרבו. לְהַזְהִיר הַנְּקֵבָה כַּזָּכָר, לְכָךְ נֶאֱמַר לְשׁוֹן רַבִּים:\",1,0],[2,128,18,6,\"אני ה'. נֶאֱמָן לְשַׁלֵּם שָׂכָר:\",2,0],[2,128,18,7,\"ערות אביך. זוֹ אֵשֶׁת אָבִיךָ, אוֹ אֵינוֹ אֶלָּא כְמַשְׁמָעוֹ? נֶאֱמַר כָּאן עֶרְוַת אָבִיךָ וְנֶאֱמַר לְהַלָּן עֶרְוַת אָבִיו גִּלָּה, מַה לְּהַלָּן אֵשֶׁת אָבִיו אַף כָּאן אֵשֶׁת אָבִיו (סנהדרין נ\\\"ד):\",1,0],[2,128,18,7,\"וערות אמך. לְהָבִיא אִמּוֹ שֶׁאֵינָהּ אֵשֶׁת אָבִיו (שם):\",2,0],[2,128,18,8,\"ערות אשת אביך. לְרַבּוֹת אַחַר מִיתָה (שם):\",1,0],[2,128,18,9,\"בת אביך. אַף בַּת אֲנוּסָה בְמַשְׁמָע:\",1,0],[2,128,18,9,\"מולדת בית או מולדת חוץ. בֵּין שֶׁאוֹמְרִים לוֹ לְאָבִיךָ קַיֵּם אֶת אִמָּהּ, וּבֵין שֶׁאוֹמְרִים לוֹ הוֹצֵא אֶת אִמָּהּ, כְּגוֹן מַמְזֶרֶת אוֹ נְתִינָה (יבמות כ\\\"ג):\",2,0],[2,128,18,10,\"ערות בת בנך וגו'. בְּבִתּוֹ מֵאֲנוּסָתוֹ הַכָּתוּב מְדַבֵּר, וּבִתּוֹ וּבַת בִּתּוֹ מֵאִשְׁתּוֹ אָנוּ לְמֵדִין מֵ\\\"עֶרְוַת אִשָּׁה וּבִתָּהּ\\\", שֶׁנֶּאֱמַר בָּהֶן \\\"לֹא תְגַלֵּה\\\", בֵּין שֶׁהִיא מִמֶּנּוּ וּבֵין שֶׁהִיא מֵאִישׁ אַחֵר (שם כב):\",1,0],[2,128,18,10,\"ערות בת בנך. קַל וָחֹמֶר לְבִתְּךָ, אֶלָּא לְפִי שֶׁאֵין מַזְהִירִין מִן הַדִּין, לְמָדוּהָ מִגְּזֵרָה שָׁוָה בְּמַסֶּכֶת יְבָמוֹת (דף ג'):\",2,0],[2,128,18,11,\"ערות בת אשת אביך. לִמֵּד שֶׁאֵינוֹ חַיָּב עַל אֲחוֹתוֹ מִשִּׁפְחָה וְנָכְרִית, לְכָךְ נֶאֱמַר \\\"בַּת אֵשֶׁת אָבִיךָ\\\" — בִּרְאוּיָה לְקִדּוּשִׁין (שם כ\\\"ג):\",1,0],[2,128,18,14,\"ערות אחי אביך לא תגלה. וּמַה הִיא עֶרְוָתוֹ? אל אשתו לא תקרב:\",1,0],[2,128,18,15,\"אשת בנך. לֹא אָמַרְתִּי אֶלָּא בְּשֶׁיֵּשׁ לְבִנְךָ אִישׁוּת בָּהּ, פְּרָט לַאֲנוּסָה וְשִׁפְחָה וְנָכְרִית (עי' ספרא):\",1,0],[2,128,18,17,\"ערות אשה ובתה. לֹא אָסַר הַכָּתוּב אֶלָּא עַל יְדֵי נִשּׂוּאֵי הָרִאשׁוֹנָה, לְכָךְ נֶאֱמַר לֹא \\\"תִקַּח\\\" — לְשׁוֹן קִיחָה, וְכֵן לְעִנְיַן הָעֹנֶשׁ, אֲשֶׁר \\\"יִקַּח\\\" אֶת אִשָּׁה וְאֶת אִמָּה — לְשׁוֹן קִיחָה, אֲבָל אָנַס אִשָּׁה מֻתָּר לִשָּׂא בִּתָּהּ (יבמות צ\\\"ז):\",1,0],[2,128,18,17,\"שארה הנה. קְרוֹבוֹת זוֹ לָזוֹ:\",2,0],[2,128,18,17,\"זמה. עֵצָה, כְּתַרְגּוּמוֹ עֲצַת חֶטְאִין, שֶׁיִּצְרְךָ יוֹעֶצְךָ לַחֲטֹא:\",3,0],[2,128,18,18,\"אל אחתה. שְׁתֵּיהֶן כְּאַחַת (קידושין נ'):\",1,0],[2,128,18,18,\"לצרר. לְשׁוֹן צָרָה — לַעֲשׂוֹת אֶת זוֹ צָרָה לָזוֹ:\",2,0],[2,128,18,18,\"בחייה. לִמֶּדְךָ שֶׁאִם גֵרְשָׁהּ לֹא יִשָּׂא אֶת אֲחוֹתָהּ כָּל זְמַן שֶׁהִיא בַחַיִּים (יבמות ח'):\",3,0],[2,128,18,21,\"למלך. עֲ\\\"זָ הִיא שֶׁשְּׁמָהּ מֹלֶךְ, וְזוֹ הִיא עֲבוֹדָתָהּ, שֶׁמּוֹסֵר בְּנוֹ לַכּוֹמְרִים וְעוֹשִׂין שְׁתֵּי מְדוּרוֹת גְּדוֹלוֹת וּמַעֲבִירִין אֶת הַבֵּן בְּרַגְלָיו בֵּין שְׁתֵּי מְדוּרוֹת הָאֵשׁ (סנהדרין ס\\\"ד):\",1,0],[2,128,18,21,\"לא תתן. זוֹ הִיא מְסִירָתוֹ לַכּוֹמְרִים:\",2,0],[2,128,18,21,\"להעביר למלך. זוֹ הַעֲבָרַת הָאֵשׁ:\",3,0],[2,128,18,23,\"תבל הוא. לְשׁוֹן קָדֵשׁ וְעֶרְוָה וְנִאוּף, וְכֵן וְאַפִּי עַל תַּבְלִיתָם (ישעיהו י'); דָּבָר אַחֵר תֶּבֶל הוּא לְשׁוֹן בְּלִילָה וְעִרְבּוּב זֶרַע אָדָם וְזֶרַע בְּהֵמָה:\",1,0],[2,128,18,28,\"ולא תקיא הארץ אתכם. מָשָׁל לְבֶן מֶלֶךְ שֶׁהֶאֱכִילוּהוּ דָּבָר מָאוּס, שֶׁאֵין עוֹמֵד בְּמֵעָיו אֶלָּא מְקִיאוֹ, כָּךְ אֶרֶץ יִשְׂרָאֵל אֵינָהּ מְקַיֶּמֶת עוֹבְרֵי עֲבֵרָה (ספרא סוף קדושים), וְתַרְגּוּמוֹ וְלָא תְרוֹקֵן, לְשׁוֹן רִקּוּן — מְרִיקָה עַצְמָהּ מֵהֶם:\",1,0],[2,128,18,29,\"הנפשות העשת. הַזָּכָר וְהַנְּקֵבָה בְמַשְׁמָע (ספרא):\",1,0],[2,128,18,30,\"ושמרתם את משמרתי. לְהַזְהִיר בֵּית דִּין עַל כָּךְ (שם):\",1,0],[2,128,18,30,\"ולא תטמאו בהם אני ה' אלהיכם. הָא אִם תִּטַּמְּאוּ אֵינִי אֱלֹהֵיכֶם, וְאַתֶּם נִפְסָלִים מֵאַחֲרַי, וּמַה הֲנָאָה יֵשׁ לִי בָּכֶם וְאַתֶּם מִתְחַיְּבִים כְּלָיָה? לְכָךְ נֶאֱמַר אֲנִי ה' אֱלֹהֵיכֶם (שם):\",2,0],[2,128,19,2,\"דבר אל כל עדת בני ישראל. מְלַמֵּד שֶׁנֶּאֶמְרָה פָרָשָׁה זוֹ בְּהַקְהֵל מִפְּנֵי שֶׁרֹב גּוּפֵי תוֹרָה תְלוּיִּין בָּהּ (ספרא):\",1,0],[2,128,19,2,\"קדשים תהיו. הֱווּ פְרוּשִׁים מִן הָעֲרָיוֹת וּמִן הָעֲבֵרָה, שֶׁכָּל מָקוֹם שֶׁאַתָּה מוֹצֵא גֶדֶר עֶרְוָה אַתָּה מוֹצֵא קְדֻשָּׁה, אִשָּׁה זֹנָה וַחֲלָלָה וְגוֹ' אֲנִי ה' מְקַדִּשְׁכֶם (ויקרא כ\\\"א), וְלֹא יְחַלֵּל זַרְעוֹ, אֲנִי ה' מְקַדְּשׁוֹ (שם), קְדֹשִׁים יִהְיוּ, אִשָּׁה זֹנָה וַחֲלָלָה (שם):\",2,0],[2,128,19,3,\"איש אמו ואביו תיראו. כָּל אֶחָד מִכֶּם תִּירְאוּ אָבִיו וְאִמּוֹ, זֶהוּ פְשׁוּטוֹ; וּמִדְרָשׁוֹ: אֵין לִי אֶלָּא אִישׁ, אִשָּׁה מִנַּיִן? כְּשֶׁהוּא אוֹמֵר תִּירָאוּ הֲרֵי כָאן שְׁנַיִם, אִם כֵּן לָמָּה נֶאֱמַר אִישׁ? שֶׁהָאִישׁ סֵפֶק בְּיָדוֹ לַעֲשׂוֹת אֲבָל אִשָּׁה רְשׁוּת אֲחֵרִים עָלֶיהָ (ספרא; קידושין ל'):\",1,0],[2,128,19,3,\"אמו ואביו תיראו. כָּאן הִקְדִּים אֵם לָאָב, לְפִי שֶׁגָּלוּי לְפָנָיו שֶׁהַבֵּן יָרֵא אֶת אָבִיו יוֹתֵר מֵאִמּוֹ, וּבַכָּבוֹד הִקְדִּים אָב לָאֵם, לְפִי שֶׁגָּלוּי לְפָנָיו שֶׁהַבֵּן מְכַבֵּד אֶת אִמּוֹ יוֹתֵר מֵאָבִיו, מִפְּנֵי שֶׁמְּשַׁדַּלְתּוֹ בִדְבָרִים (שם):\",2,0],[2,128,19,3,\"ואת שבתתי תשמרו. סָמַךְ שַׁבָּת לְמוֹרָא אָב, לוֹמַר אַף עַל פִּי שֶׁהִזְהַרְתִּיךָ עַל מוֹרָא אָב, אִם יֹאמַר לְךָ חַלֵּל אֶת הַשַּׁבָּת, אַל תִּשְׁמַע לוֹ, וְכֵן בִּשְׁאָר כָּל הַמִּצְווֹת (בבא מציעא ל\\\"ב):\",3,0],[2,128,19,3,\"אני ה' אלהיכם. אַתָּה וְאָבִיךָ חַיָּבִים בִּכְבוֹדִי, לְפִיכָךְ לֹא תִשְׁמַע לוֹ לְבַטֵּל אֶת דְּבָרַי. אֵיזֶהוּ מוֹרָא? לֹא יֵשֵׁב בִּמְקוֹמוֹ וְלֹא יְדַבֵּר בִּמְקוֹמוֹ וְלֹא יִסְתֹּר אֶת דְּבָרָיו, וְאֵיזֶהוּ כָבוֹד? מַאֲכִיל וּמַשְׁקֶה, מַלְבִּישׁ וּמַנְעִיל, מַכְנִיס וּמוֹצִיא (קידושין ל\\\"א):\",4,0],[2,128,19,4,\"אל תפנו אל האלילם. לְעָבְדָם; אֱלִילִים לְשׁוֹן אַל — כְּלֹא הוּא חָשׁוּב:\",1,0],[2,128,19,4,\"ואלהי מסכה. תְּחִלָּתָן אֱלִילִים הֵם, וְאִם אַתָּה פוֹנֶה אַחֲרֵיהֶם סוֹפְךָ עוֹשֶׂה אוֹתָם אֱלוֹהוֹת (ספרא):\",2,0],[2,128,19,4,\"לא תעשו לכם. לֹא תַעֲשׂוּ לַאֲחֵרִים וְלֹא אֲחֵרִים לָכֶם; וְאִם תֹּאמַר לֹא תַעֲשׂוּ לְעַצְמְכֶם אֲבָל אֲחֵרִים עוֹשִׂין לָכֶם, הֲרֵי כְבָר נֶאֱמַר לֹא יִהְיֶה לְךָ (שמות כ') — לֹא שֶׁלְּךָ וְלֹא שֶׁל אֲחֵרִים:\",3,0],[2,128,19,5,\"וכי תזבחו וגו'. לֹא נֶאֶמְרָה פָרָשָׁה זוֹ אֶלָּא לְלַמֵּד, שֶׁלֹּא תְהֵא זְבִיחָתָן אֶלָּא עַל מְנָת לֵאָכֵל בְּתוֹךְ הַזְּמַן הַזֶּה, שֶׁאִם לִקְבֹּעַ לָהֶם זְמַן אֲכִילָה, הֲרֵי כְבָר נֶאֱמַר (ויקרא ז') וְאִם נֶדֶר אוֹ נְדָבָה זֶבַח קָרְבָּנוֹ וְגוֹ' (ספרא):\",1,0],[2,128,19,5,\"לרצנכם תזבחהו. תְּחִלַּת זְבִיחָתוֹ תְּהֵא עַל מְנָת נַחַת רוּחַ — שֶׁיְּהֵא לָכֶם לְרָצוֹן, שֶׁאִם תְּחַשְּׁבוּ עָלָיו מַחֲשֶׁבֶת פְּסוּל לֹא יֵרָצֶה עֲלֵיכֶם לְפָנַי:\",2,0],[2,128,19,5,\"לרצנכם. אפיי\\\"צימנטו, זֶהוּ לְפִי פְשׁוּטוֹ; וְרַבּוֹתֵינוּ לָמְדוּ מִכָּאן לַמִּתְעַסֵּק בַּקֳּדָשִׁים שֶׁפָּסוּל, שֶׁצָּרִיךְ שֶׁיִּתְכַּוֵּן לִשְׁחֹט (זבחים מ\\\"ז; חולין י\\\"ג):\",3,0],[2,128,19,6,\"ביום זבחכם יאכל. כְּשֶׁתִּזְבְּחוּהוּ תִּשְׁחֲטוּהוּ עַל מְנָת זְמַן זֶה שֶׁקָּבַעְתִּי לָכֶם כְּבָר:\",1,0],[2,128,19,7,\"ואם האכל יאכל וגו'. אִם אֵינוֹ עִנְיָן לְחוּץ לִזְמַנּוֹ, שֶׁהֲרֵי כְבָר נֶאֱמַר וְאִם הֵאָכֹל יֵאָכֵל מִבְּשַׂר זֶבַח שְׁלָמָיו וְגוֹ' (ויקרא ז'), תְּנֵהוּ עִנְיָן לְחוּץ לִמְקוֹמוֹ; יָכוֹל יִהְיוּ חַיָּבִין כָּרֵת עַל אֲכִילָתוֹ, תַּ\\\"לֹ וְהַנֶּפֶשׁ הָאֹכֶלֶת מִמֶּנּוּ עֲוֹנָהּ תִּשָּׂא, \\\"מִמֶּנּוּ\\\" וְלֹא מֵחֲבֵרוֹ, יָצָא הַנִּשְׁחָט בְּמַחֲשֶׁבֶת חוּץ לִמְקוֹמוֹ (זבחים כ\\\"ח):\",1,0],[2,128,19,7,\"פגול. מְתֹעָב, כְּמוֹ וּמְרַק פִּגֻּלִים כְּלֵיהֶם (ישעיהו ס\\\"ה):\",2,0],[2,128,19,8,\"ואכליו עונו ישא. בְּנוֹתָר גָּמוּר הַכָּתוּב מְדַבֵּר, וְאֵינוֹ עָנוּשׁ כָּרֵת עַל הַנִּשְׁחָט חוּץ לִמְקוֹמוֹ, שֶׁכְּבָר מִעֲטוֹ הַכָּתוּב, וְזֶה בְּנוֹתָר גָּמוּר מְדַבֵּר, וּבְמַסֶּכֶת כָּרֵתוֹת (דף ה'), לְמָדוּהוּ מִגְּזֵרָה שָׁוָה:\",1,0],[2,128,19,9,\"לא תכלה פאת שדך. שֶׁיַּנִּיחַ פֵּאָה בְסוֹף שָׂדֵהוּ (עי' ספרא):\",1,0],[2,128,19,9,\"ולקט קצירך. שִׁבֳּלִים הַנּוֹשְׁרִים בִּשְׁעַת קְצִירָה, אַחַת אוֹ שְׁתַּיִם, אֲבָל שָׁלוֹשׁ אֵינָן לֶקֶט (פאה פ\\\"ו):\",2,0],[2,128,19,10,\"לא תעולל. לֹא תִטֹּל עוֹלֵלוֹת שֶׁבָּהּ, וְהֵן נִכָּרוֹת; אֵיזֶהוּ עוֹלֵלוֹת? כֹּל שֶׁאֵין לוֹ לֹא כָתֵף וְלֹא נָטֵף (ספרא):\",1,0],[2,128,19,10,\"ופרט כרמך. גַּרְגְּרֵי עֲנָבִים הַנּוֹשְׁרִים בִּשְׁעַת בְּצִירָה:\",2,0],[2,128,19,10,\"אני ה' אלהיכם. דַּיָּן לִפָּרַע; וְאֵינִי גוֹבֶה מִכֶּם אֶלָּא נְפָשׁוֹת, שֶׁנֶּאֱמַר אַל תִּגְזָל דָּל וְגוֹ' כִּי ה' יָרִיב רִיבָם וְגוֹ' (משלי כ\\\"ב):\",3,0],[2,128,19,11,\"לא תגנבו. אַזְהָרָה לְגוֹנֵב מָמוֹן, אֲבָל לֹא תִגְנֹב שֶׁבַּעֲשֶׂרֶת הַדִּבְּרוֹת אַזְהָרָה לְגוֹנֵב נְפָשׁוֹת, דָּבָר הַלָּמֵד מֵעִנְיָנוֹ — דָּבָר שֶׁחַיָּבִין עָלָיו מִיתַת בֵּית דִּין:\",1,0],[2,128,19,11,\"ולא תכחשו. לְפִי שֶׁנֶּאֱמַר (ויקרא ה'), וְכִחֶשׁ בָּהּ מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ, לָמַדְנוּ עֹנֶשׁ, אַזְהָרָה מִנַּיִן? תַּ\\\"לֹ וְלֹא תְכַחֲשׁוּ:\",2,0],[2,128,19,11,\"ולא תשקרו. לְפִי שֶׁנֶּאֱמַר (שם), וְנִשְׁבַּע עַל שָׁקֶר יְשַׁלֵּם קֶרֶן וְחֹמֶשׁ, לָמַדְנוּ עֹנֶשׁ, אַזְהָרָה מִנַּיִן? תַּ\\\"ל וְלֹא תְשַׁקְּרוּ:\",3,0],[2,128,19,11,\"לא תגנבו ולא תכחשו ולא תשקרו ולא תשבעו. אִם גָּנַבְתָּ סוֹפְךָ לְכַחֵשׁ, סוֹפְךָ לְשַׁקֵּר, סוֹפְךָ לִשָּׁבַע לַשֶּׁקֶר:\",4,0],[2,128,19,12,\"ולא תשבעו בשמי. לָמָּה נֶאֱמַר? לְפִי שֶׁנֶּאֱמַר לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךָ לַשָּׁוְא (שמות כ'), יָכוֹל לֹא יְהֵא חַיָּב אֶלָּא עַל שֵׁם הַמְיֻחָד, מִנַּיִן לְרַבּוֹת כָּל הַכִּנּוּיִין? תַּ\\\"ל וְלֹא תִשָּׁבְעוּ בִשְׁמִי לַשָּׁקֶר — כָּל שֵׁם שֶׁיֵּשׁ לִי (ספרא):\",1,0],[2,128,19,13,\"לא תעשק. זֶה הַכּוֹבֵשׁ שְׂכַר שָׂכִיר (בבא מציעא ס\\\"א):\",1,0],[2,128,19,13,\"לא תלין. לְשׁוֹן נְקֵבָה, מוּסָב עַל הַפְּעוּלָה:\",2,0],[2,128,19,13,\"עד בקר. בִּשְׂכִיר יוֹם הַכָּתוּב מְדַבֵּר, שֶׁיְּצִיאָתוֹ מִשֶּׁשָּׁקְעָה חַמָּה, לְפִיכָךְ זְמַן גִּבּוּי שְׂכָרוֹ כָּל הַלָּיְלָה, וּבְמָקוֹם אַחֵר הוּא אוֹמֵר וְלֹא תָבוֹא עָלָיו הַשֶּׁמֶשׁ (דברים כ\\\"ד), מְדַבֵּר בִּשְֹכִיר לַיְלָה, שֶׁהַשְׁלָמַת פְּעֻלָּתוֹ מִשֶּׁיַּעֲלֶה עַמּוּד הַשַּׁחַר, לְפִיכָךְ זְמַן גִּבּוּי שְׂכָרוֹ כָּל הַיּוֹם, לְפִי שֶׁנָּתְנָה תוֹרָה זְמַן לְבַעַל הַבַּיִת עוֹנָה לְבַקֵּשׁ מָעוֹת (בבא מציעא ק\\\"י):\",3,0],[2,128,19,14,\"לא תקלל חרש. אֵין לִי אֶלָּא חֵרֵשׁ, מִנַּיִן לְרַבּוֹת כָּל אָדָם? תַּ\\\"ל בְּעַמְּךָ לֹא תָאֹר (שמות כ\\\"ב), אִם כֵּן לָמָּה נֶאֱמַר חֵרֵשׁ? מַה חֵרֵשׁ מְיֻחָד שֶׁהוּא בַחַיִּים, אַף כָּל שֶׁהוּא בַחַיִּים, יָצָא הַמֵּת שֶׁאֵינוֹ בַחַיִּים (ספרא):\",1,0],[2,128,19,14,\"ולפני עור לא תתן מכשול. לִפְנֵי הַסּוּמָא בְדָבָר לֹא תִתֵּן עֵצָה שֶׁאֵינָהּ הוֹגֶנֶת לוֹ, אַל תֹּאמַר מְכֹר שָׂדְךָ וְקַח לְךָ חֲמוֹר, וְאַתָּה עוֹקֵף עָלָיו וְנוֹטְלָהּ הֵימֶנּוּ (שם):\",2,0],[2,128,19,14,\"ויראת מאלהיך. לְפִי שֶׁהַדָּבָר הַזֶּה אֵינוֹ מָסוּר לַבְּרִיּוֹת לֵידַע אִם דַּעְתּוֹ שֶׁל זֶה לְטוֹבָה אוֹ לְרָעָה, וְיָכוֹל לְהִשָּׁמֵט וְלוֹמַר לְטוֹבָה נִתְכַּוַּנְתִּי, לְפִיכָךְ נֶאֱמַר בּוֹ וְיָרֵאתָ מֵּאֱלֹהֶיךָ הַמַּכִּיר מַחְשְׁבוֹתֶיךָ; וְכֵן כָּל דָּבָר הַמָּסוּר לְלִבּוֹ שֶׁל אָדָם הָעוֹשֵׂהוּ וְאֵין שְׁאָר הַבְּרִיּוֹת מַכִּירוֹת בּוֹ, נֶאֱמַר בּוֹ וְיָרֵאתָ מֵּאֱלֹהֶיךָ:\",3,0],[2,128,19,15,\"לא תעשו עול במשפט. מְלַמֵּד שֶׁהַדַּיָּן הַמְקַלְקֵּל אֶת הַדִּין קָרוּי עַוָּל, שָׂנוּי וּמְשֻׁקָּץ, חֵרֶם וְתוֹעֵבָה, שֶׁהָעָוֶל קָרוּי תּוֹעֵבָה, שֶׁנֶּאֱמַר כִּי תוֹעֲבַת ה' וְגוֹ' כֹּל עֹשֵׂה עָוֶל (דברים כ\\\"ה), וְהַתּוֹעֵבָה קְרוּיָה חֵרֶם וְשֶׁקֶץ שֶׁנֶּאֱמַר וְלֹא תָבִיא תוֹעֵבָה אֶל בֵּיתֶךָ וְהָיִיתָ חֵרֶם כָּמֹהוּ שַׁקֵּץ תְּשַׁקְּצֶנּוּ וְגוֹ' (שם ז'):\",1,0],[2,128,19,15,\"לא תשא פני דל. שֶׁלֹּא תֹאמַר עָנִי הוּא זֶה, וְהֶעָשִׁיר חַיָּב לְפַרְנְסוֹ, אֲזַכֶּנּוּ בַדִּין וְנִמְצָא מִתְפַּרְנֵס בִּנְקִיּוּת (ספרא):\",2,0],[2,128,19,15,\"ולא תהדר פני גדול. שֶׁלֹּא תֹאמַר עָשִׁיר הוּא זֶה, בֶּן גְּדוֹלִים הוּא זֶה, הֵיאַךְ אֲבַיְּשֶׁנּוּ וְאֶרְאֶה בְּבָשְׁתּוֹ? עֹנֶשׁ יֵשׁ בַּדָּבָר לְכָךְ נֶאֱמַר וְלֹא תֶהְדַּר פְּנֵי גָדוֹל:\",3,0],[2,128,19,15,\"בצדק תשפט עמיתך. כְּמַשְׁמָעוֹ; דָּ\\\"אַ: הֱוֵי דָן אֶת חֲבֵרְךָ לְכַף זְכוּת (שבועות ל'):\",4,0],[2,128,19,16,\"לא תלך רכיל. אֲנִי אוֹמֵר עַל שֵׁם שֶׁכָּל מְשַׁלְּחֵי מְדָנִים וּמְסַפְּרֵי לָשׁוֹן הָרַע הוֹלְכִים בְּבָתֵּי רֵעֵיהֶם לְרַגֵּל מַה יִּרְאוּ רָע, אוֹ מַה יִּשְׁמְעוּ רָע, לְסַפֵּר בַּשּׁוּק, נִקְרָאִים הוֹלְכֵי רָכִיל — הוֹלְכֵי רְגִילָה, אשפיי\\\"מנט בְּלַעַז. וּרְאָיָה לִדְבָרַי, שֶׁלֹּא מָצִינוּ רְכִילוּת שֶׁאֵין כָּתוּב בִּלְשׁוֹן הֲלִיכָה, לֹא תֵלֵךְ רָכִיל, הֹלְכֵי רָכִיל נְחֹשֶׁת וּבַרְזֶל (ירמיהו ו'), וּשְׁאָר לָשׁוֹן הָרַע אֵין כָּתוּב בּוֹ הֲלִיכָה, מְלָשְׁנִי בַסֵּתֶר רֵעֵהוּ (תהילים ק\\\"א), לָשׁוֹן רְמִיָּה (שם ק\\\"כ), לָשׁוֹן מְדַבֶּרֶת גְּדֹלוֹת (שם י\\\"ב); לְכָךְ אֲנִי אוֹמֵר שֶׁהַלָּשׁוֹן הוֹלֵךְ וּמְרַגֵּל, שֶׁהַכַּ\\\"ף נֶחֱלֶפֶת בְּגִימֶ\\\"ל, שֶׁכָּל הָאוֹתִיּוֹת שֶׁמּוֹצָאֵיהֶם מִמָּקוֹם אֶחָד מִתְחַלְּפוֹת זוֹ בָזוֹ, בֵּי\\\"ת בְּפֵ\\\"א וְגִימֶ\\\"ל בְּכַ\\\"ף וְקוֹ\\\"ף, וְנוּ\\\"ן בְּלָמֶ\\\"ד, וְזַיִ\\\"ן בְּצָדִ\\\"י, וְכֵן וַיְרַגֵּל בְּעַבְדְּךָ (שמואל ב י\\\"ט) — רִגֵּל בְּמִרְמָה לֵאמֹר עָלַי רָעָה, וְכֵן לֹא רָגַל עַל לְשֹׁנוֹ (תהילים ט\\\"ו), וְכֵן רוֹכֵל — הַסּוֹחֵר וּמְרַגֵּל אַחַר כָּל סְחוֹרָה, וְכֵן הַמּוֹכֵר בְּשָׂמִים לְהִתְקַשֵּׁט בָּהֶם הַנָּשִׁים, עַל שֵׁם שֶׁמְּחַזֵּר תָּמִיד בָּעֲיָרוֹת, נִקְרָא רוֹכֵל לְשׁוֹן רוֹגֵל; לָא תֵיכוּל קוּרְצִין כְּמוֹ וַאֲכַלוּ קַרְצֵיהוֹן דִּי יְהוּדָיֵא (דניאל ג׳:ח׳), אָכַל בֵּיהּ קוּרְצָא בֵּי מַלְכָּא (ברכות נ\\\"ח:); נִרְאֶה בְעֵינַי שֶׁהָיָה מִשְׁפָּטָם לֶאֱכֹל בְּבֵית הַמְקַבֵּל דִּבְרֵיהֶם שׁוּם הַלְעָטָה, וְהוּא גְמַר חִזּוּק שֶׁדְּבָרָיו מְקֻיָּמִים וְיַעֲמִידֵם עַל הָאֱמֶת, וְאוֹתָהּ הַלְעָטָה נִקְרֵאת אֲכִילַת קוּרְצִין, לְשׁוֹן קוֹרֵץ בְּעֵינָיו (משלי ו'), שֶׁכֵּן דֶּרֶךְ כָּל הוֹלְכֵי רָכִיל לִקְרֹץ בְּעֵינֵיהֶם וְלִרְמֹז דִּבְרֵי רְכִילוּתָן, שֶׁלֹּא יָבִינוּ שְׁאָר הַשּׁוֹמְעִים:\",1,0],[2,128,19,16,\"לא תעמד על דם רעך. לִרְאוֹת בְּמִיתָתוֹ וְאַתָּה יָכוֹל לְהַצִּילוֹ, כְּגוֹן טוֹבֵעַ בַּנָּהָר וְחַיָּה אוֹ לִיסְטִים בָּאִים עָלָיו (סנהדרין ע\\\"ג):\",2,0],[2,128,19,16,\"אני ה'. נֶאֱמָן לְשַׁלֵּם שָׂכָר, וְנֶאֱמָן לִפָּרַע:\",3,0],[2,128,19,17,\"ולא תשא עליו חטא. לֹא תַלְבִּין אֶת פָּנָיו בָּרַבִּים (עי' ספרא):\",1,0],[2,128,19,18,\"לא תקם. אָמַר לוֹ הַשְׁאִילֵנִי מַגָּלְךָ, אָמַר לוֹ לָאו, לְמָחָר אָמַר לוֹ הַשְׁאִילֵנִי קַרְדֻּמְּךָ, אָמַר לוֹ אֵינִי מַשְׁאִילְךָ כְּדֶרֶךְ שֶׁלֹּא הִשְׁאַלְתַּנִי, זוֹ הִיא נְקִימָה; וְאֵיזוֹ הִיא נְטִירָה? אָמַר לוֹ הַשְׁאִילֵנִי אֶת קַרְדֻּמְּךָ, אָמַר לוֹ לָאו, לְמָחָר אָמַר לוֹ הַשְׁאִילֵנִי מַגָּלְךָ, אָמַר לוֹ הֵא לְךָ, אֵינִי כְמוֹתְךָ שֶׁלֹּא הִשְׁאַלְתַּנִי, זוֹ הִיא נְטִירָה, שֶׁנּוֹטֵר הָאֵיבָה בְּלִבּוֹ, אַעַ\\\"פִּי שֶׁאֵינוֹ נוֹקֵם (ספרא; יומא כ\\\"ג):\",1,0],[2,128,19,18,\"ואהבת לרעך כמוך. אָמַר רַבִּי עֲקִיבָא זֶה כְּלָל גָּדוֹל בַּתּוֹרָה (ספרא):\",2,0],[2,128,19,19,\"את חקתי תשמרו. וְאֵלּוּ הֵן: בְּהֶמְתְּךָ לֹא תַרְבִּיעַ כִּלְאַיִם וְגוֹ'; חֻקִּים — אֵלּוּ גְזֵרַת מֶלֶךְ שֶׁאֵין טַעַם לַדָּבָר:\",1,0],[2,128,19,19,\"ובגד כלאים. לָמָּה נֶאֱמַר? לְפִי שֶׁנֶּאֱמַר \\\"לֹא תִלְבַּשׁ שַׁעַטְנֵז צֶמֶר וּפִשְׁתִּים יַחְדָּו\\\" (דברים כ\\\"ב), יָכוֹל לֹא יִלְבַּשׁ גִּזֵּי צֶמֶר וַאֲנִיצֵי פִשְׁתָּן, תַּ\\\"ל \\\"בֶּגֶד\\\", מִנַּיִן לְרַבּוֹת הַלְּבָדִים? תַּ\\\"לֹ \\\"שַׁעַטְנֵז\\\" — דָּבָר שֶׁהוּא שׁוּעַ טָווּי וְנוּז. וְאוֹמֵר אֲנִי נוּז לְשׁוֹן דָּבָר הַנִּמְלָל וְשָׁזוּר זֶה עִם זֶה לְחַבְּרוֹ, טישט\\\"יר בְּלַעַז, כְּמוֹ \\\"חַזְיָין לִנְזָאֵי דְאִית בְּהוֹן\\\" (מועד קטן י\\\"ב), שֶׁאָנוּ מְפָרְשִׁין לְשׁוֹן כִּמּוּשׁ, פליש\\\"טרא, וּלְשׁוֹן שַׁעַטְנֵז פֵּרֵשׁ מְנַחֵם מַחְבֶּרֶת צֶמֶר וּפִשְׁתִּים:\",2,0],[2,128,19,20,\"נחרפת לאיש. מְיֻעֶדֶת וּמְיֻחֶדֶת לְאִישׁ, וְאֵינִי יוֹדֵעַ לוֹ דִמְיוֹן בַּמִּקְרָא; וּבְשִׁפְחָה כְנַעֲנִית חֶצְיָהּ שִׁפְחָה וְחֶצְיָהּ בַּת חֹרִין הַמְאֹרֶסֶת לְעֶבֶד עִבְרִי שֶׁמֻּתָּר בְּשִׁפְחָה הַכָּתוּב מְדַבֵּר:\",1,0],[2,128,19,20,\"והפדה לא נפדתה. פְּדוּיָה וְאֵינָהּ פְּדוּיָה, וּסְתָם פִּדְיוֹן בְּכֶסֶף:\",2,0],[2,128,19,20,\"או חפשה. בִּשְׁטָר (ספרא):\",3,0],[2,128,19,20,\"בקרת תהיה. הִיא לוֹקָה וְלֹא הוּא, יֵשׁ עַל בֵּית דִּין לְבַקֵּר אֶת הַדָּבָר שֶׁלֹּא לְחַיְּבָהּ מִיתָה כי לא חפשה וְאֵין קִדּוּשֶׁיהָ קִדּוּשִׁין גְּמוּרִין: וְרַבּוֹתֵינוּ לָמְדוּ מִכָּאן (מכות כ\\\"ב), שֶׁמִּי שֶׁהוּא בְמַלְקוּת תְּהֵא בִקְרִיאָה — שֶׁהַדַּיָּנִים הַמַּלְקִין קוֹרִין עַל הַלּוֹקֶה \\\"אִם לֹא תִשְׁמֹר לַעֲשׂוֹת וְגוֹ' וְהִפְלָא ה' אֶת מַכֹּתְךָ וְגוֹ'\\\" (דברים כ\\\"ח):\",4,0],[2,128,19,20,\"כי לא חפשה. לְפִיכָךְ אֵין חַיָּב עָלֶיהָ מִיתָה, שֶׁאֵין קִדּוּשֶׁיהָ קִדּוּשִׁין, הָא אִם חֻפְּשָׁה קִדּוּשֶׁיהָ קִדּוּשִׁין וְחַיָּב מִיתָה (ספרא):\",5,0],[2,128,19,22,\"ונסלח לו מחטאתו אשר חטא. לְרַבּוֹת אֶת הַמֵּזִיד כַּשּׁוֹגֵג (ספרא):\",1,0],[2,128,19,23,\"וערלתם ערלתו. וַאֲטַמְתֶּם אֲטִימָתוֹ — יְהֵא אָטוּם וְנִסְתָּם מִלֵּהָנוֹת מִמֶּנּוּ:\",1,0],[2,128,19,23,\"שלש שנים יהיה לכם ערלים. מֵאֵימָתַי מוֹנֶה לוֹ? מִשְּׁעַת נְטִיעָתוֹ; יָכוֹל אִם הִצְנִיעוֹ, לְאַחַר שָׁלוֹשׁ שָׁנִים יְהֵא מֻתָּר, תַּ\\\"ל יִהְיֶה — בַּהֲוָיָתוֹ יְהֵא (ספרא):\",2,0],[2,128,19,24,\"יהיה כל פריו קדש. כְּמַעֲשֵׂר שֵׁנִי שֶׁכָּתוּב בּוֹ וְכָל מַעְשַׂר הָאָרֶץ וְגוֹ' קֹדֶשׁ לַה' (ויקרא כ\\\"ז), מַה מַּעֲשֵׂר שֵׁנִי אֵינוֹ נֶאֱכָל חוּץ לְחוֹמוֹת יְרוּשָׁלַיִם אֶלָּא בְּפִדְיוֹן, אַף זֶה כֵּן, וְדָבָר זֶה הלולים לה' הוּא, שֶׁנּוֹשְׂאוֹ שָׁם לְשַׁבֵּחַ וּלְהַלֵּל לַשָּׁמַיִם (עי' ברכות ל\\\"ה):\",1,0],[2,128,19,25,\"להוסיף לכם תבואתו. הַמִּצְוָה הַזֹּאת שֶׁתִּשְׁמְרוּ, תִּהְיֶה לְהוֹסִיף לָכֶם תְּבוּאָתוֹ, שֶׁבִּשְׂכָרָהּ אֲנִי מְבָרֵךְ לָכֶם פֵּרוֹת הַנְּטִיעָה; הָיָה רַבִּי עֲקִיבָא אוֹמֵר דִּבְּרָה תוֹרָה כְּנֶגֶד יֵצֶר הָרָע, שֶׁלֹּא יֹאמַר אָדָם הֲרֵי אַרְבַּע שָׁנִים אֲנִי מִצְטַעֵר בּוֹ חִנָּם לְפִיכָךְ נֶאֱמַר לְהוֹסִיף לָכֶם תְּבוּאָתוֹ (ספרא):\",1,0],[2,128,19,25,\"אני ה'. אֲנִי ה' הַמַּבְטִיחַ עַל כָּךְ וְנֶאֱמָן לִשְׁמֹר הַבְטָחָתִי:\",2,0],[2,128,19,26,\"לא תאכלו על הדם. לְהַרְבֵּה פָנִים נִדְרָשׁ בְּסַנְהֶדְרִין (דף ס\\\"ג): אַזְהָרָה שֶׁלֹּא יֹאכַל מִבְּשַֹר קָדָשִׁים לִפְנֵי זְרִיקַת דָּמִים, וְאַזְהָרָה לָאוֹכֵל מִבֶּהֱמַת חֻלִּין טֶרֶם שֶׁתֵּצֵא נַפְשָׁהּ, וְעוֹד הַרְבֵּה:\",1,0],[2,128,19,26,\"לא תנחשו. כְּגוֹן אֵלּוּ הַמְנַחֲשִׁין בְּחֻלְדָּה וּבְעוֹפוֹת, פִּתּוֹ נָפְלָה מִפִּיו, צְבִי הִפְסִיקוֹ בַדֶּרֶךְ (ספרא):\",2,0],[2,128,19,26,\"ולא תעוננו. לְשׁוֹן עוֹנוֹת וְשָׁעוֹת, שֶׁאוֹמֵר יוֹם פְּלוֹנִי יָפֶה לְהַתְחִיל מְלָאכָה, שָׁעָה פְלוֹנִית קָשָׁה לָצֵאת (סנהדרין ס\\\"ה):\",3,0],[2,128,19,27,\"לא תקפו פאת ראשכם. זֶה הַמַּשְׁוֶה צְדָעָיו לַאֲחוֹרֵי אָזְנוֹ וּלְפַדַּחְתּוֹ, וְנִמְצָא הֶקֵּף רֹאשׁוֹ עָגֹל סָבִיב, שֶׁעַל אֲחוֹרֵי אָזְנָיו עִקְּרֵי שְׂעָרוֹ לְמַעְלָה מִצְּדָעָיו הַרְבֵּה:\",1,0],[2,128,19,27,\"פאת זקנך. סוֹף הַזָּקָן וּגְבוּלָיו (מכות כ'), וְהֵן חָמֵשׁ — שְׁתַּיִם בְּכָל לֶחִי וָלֶחִי, לְמַעְלָה אֵצֶל הָרֹאשׁ שֶׁהוּא רָחָב, וְיֵשׁ בּוֹ שְׁתֵּי פֵאוֹת, וְאַחַת לְמַטָּה בְּסַנְטֵרוֹ — מְקוֹם חִבּוּר שְׁנֵי הַלְּחָיַיִם יַחַד (שבועות נ'):\",2,0],[2,128,19,28,\"ושרט לנפש. כֵּן דַּרְכָּן שֶׁל אֱמוֹרִיִּים לִהְיוֹת מְשָׂרְטִין בְּשָֹרָם כְּשֶׁמֵּת לָהֶם מֵת:\",1,0],[2,128,19,28,\"וכתבת קעקע. כְּתָב מְחֻקֶּה וְשָׁקוּעַ שֶׁאֵינוֹ נִמְחָק לְעוֹלָם שֶׁמְּקַעְקְעוֹ בְּמַחַט וְהוּא מַשְׁחִיר לְעוֹלָם:\",2,0],[2,128,19,28,\"קעקע. לְשׁוֹן וְהוֹקַע אוֹתָם (במדבר כ\\\"ה), וְהוֹקַעְנוּם (שמואל ב כ\\\"א), תּוֹחֲבִין עֵץ בָּאָרֶץ וְתוֹלִין אוֹתָם עֲלֵיהֶם, וְנִמְצְאוּ מְחֻקִּין וּתְחוּבִין בַּקַּרְקַע, פורפו\\\"ינט בְּלַעַז:\",3,0],[2,128,19,29,\"אל תחלל את בתך להזנותה. בְּמוֹסֵר בִּתּוֹ פְנוּיָה לְבִיאָה שֶׁלֹּא לְשֵׁם קִדּוּשִׁין (סנהדרין ע\\\"ו):\",1,0],[2,128,19,29,\"ולא תזנה הארץ. אִם אַתָּה עוֹשֶׂה כֵּן, הָאָרֶץ מְזַנָּה אֶת פֵּרוֹתֶיהָ לַעֲשׂוֹתָן בְּמָקוֹם אַחֵר וְלֹא בְאַרְצְכֶם, וְכֵן הוּא אוֹמֵר (ירמיהו ג'), וַיִּמָּנְעוּ רְבִיבִים וְגוֹ' (תוספתא, קידושין א'):\",2,0],[2,128,19,30,\"ומקדשי תיראו. לֹא יִכָּנֵס בְּמַקְלוֹ וּבְמִנְעָלוֹ וּבַאֲפֻנְדָּתוֹ וּבְאָבָק שֶׁעַל רַגְלָיו (ברכות נ\\\"ד); וְאַעַ\\\"פִּי שֶׁאֲנִי מַזְהִירְכֶם עַל הַמִּקְדָּשׁ, אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ — אֵין בִּנְיַן הַמִּקְדָּשׁ דּוֹחֶה שַׁבָּת (ספרא):\",1,0],[2,128,19,31,\"אל תפנו. אַזְהָרָה לְבַעַל אוֹב וְיִדְּעוֹנִי; בַּעַל אוֹב זֶה פִּיתוֹם הַמְדַבֵּר מִשֶּׁחְיוֹ, וְיִדְּעוֹנִי הַמַּכְנִיס עֶצֶם חַיָּה שֶׁשְּׁמָה יַדּוּעַ לְתוֹךְ פִּיו וְהָעֶצֶם מְדַבֵּר (סנהדרין ס\\\"ה):\",1,0],[2,128,19,31,\"אל תבקשו. לִהְיוֹת עֲסוּקִים בָּם, שֶׁאִם תַּעַסְקוּ בָם, אַתֶּם מִטַּמְּאִין לְפָנַי וַאֲנִי מְתַעֵב אֶתְכֶם:\",2,0],[2,128,19,31,\"אני ה' אלהיכם. דְּעוּ אֶת מִי אַתֶּם מַחֲלִיפִין בְּמִי (ספרא):\",3,0],[2,128,19,32,\"מפני שיבה תקום. יָכוֹל זָקֵן אַשְׁמַאי, תַּ\\\"ל זָקֵן, אֵין זָקֵן אֶלָּא שֶׁקָּנָה חָכְמָה (קידושין ל\\\"ב):\",1,0],[2,128,19,32,\"והדרת פני זקן. אֵיזֶהוּ הִדּוּר? לֹא יֵשֵׁב בִּמְקוֹמוֹ וְלֹא יִסְתֹּר אֶת דְּבָרָיו: יָכוֹל יַעֲצִים עֵינָיו כְּמִי שֶׁלֹּא רָאָהוּ? לְכָךְ נֶאֱמַר ויראת מאלהיך, שֶׁהֲרֵי דָּבָר זֶה מָסוּר לְלִבּוֹ שֶׁל עוֹשֵׂהוּ, שֶׁאֵין מַכִּיר בּוֹ אֶלָּא הוּא, וְכָל דָּבָר הַמָּסוּר לַלֵּב נֶאֱמַר בוֹ וְיָרֵאתָ מֵּאֱלֹהֶיךָ (שם):\",2,0],[2,128,19,33,\"לא תונו. אוֹנָאַת דְּבָרִים; לֹא תֹאמַר לוֹ אֶמֶשׁ הָיִיתָ עוֹבֵד עֲ\\\"זָ וְעַכְשָׁו אַתָּה בָא לִלְמֹד תּוֹרָה שֶׁנִּתְּנָה מִפִּי הַגְּבוּרָה (בבא מציעא נ\\\"ח):\",1,0],[2,128,19,34,\"כי גרים הייתם. מוּם שֶׁבְּךָ אַל תֹּאמַר לַחֲבֵרְךָ (שם נ\\\"ט):\",1,0],[2,128,19,34,\"אני ה' אלהיכם. אֱלֹהֶיךָ וֵאלֹהָיו אֲנִי:\",2,0],[2,128,19,35,\"לא תעשו עול במשפט. אִם לְדִין, הֲרֵי כְּבָר נֶאֱמַר לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט (פסוק ט\\\"ו), וּמַהוּ מִשְׁפָּט הַשָּׁנוּי כָּאן? הוּא הַמִּדָּה וְהַמִּשְׁקָל וְהַמְּשׂוּרָה, מְלַמֵּד שֶׁהַמּוֹדֵד נִקְרָא דַיָּן, שֶׁאִם שִׁקֵּר בַּמִּדָּה הֲרֵי הוּא כִמְקַלְקֵל אֶת הַדִּין, וְקָרוּי עַוָּל, שָׂנאוּי וּמְשֻׁקָּץ, חֵרֶם וְתוֹעֵבָה, וְגוֹרֵם לַחֲמִשָּׁה דְבָרִים הָאֲמוּרִים בַּדַּיָּן — מְטַמֵּא אֶת הָאָרֶץ, וּמְחַלֵּל אֶת הַשֵּׁם, וּמְסַלֵּק אֶת הַשְּׁכִינָה, וּמַפִּיל אֶת יִשְׂרָאֵל בַּחֶרֶב, וּמַגְלֶה אוֹתָם מֵאַרְצָם (ספרא):\",1,0],[2,128,19,35,\"במדה. זוֹ מִדַּת הָאָרֶץ (שם):\",2,0],[2,128,19,35,\"במשקל. כְּמַשְׁמָעוֹ:\",3,0],[2,128,19,35,\"ובמשורה. הִיא מִדַּת הַלַּח וְהַיָּבֵשׁ (בבא מציעא ס\\\"א):\",4,0],[2,128,19,36,\"אבני צדק. הֵם הַמִּשְׁקוֹלוֹת שֶׁשּׁוֹקְלִין כְּנֶגְדָּן:\",1,0],[2,128,19,36,\"איפת. הִיא מִדַּת הַיָּבֵשׁ:\",2,0],[2,128,19,36,\"והין. זוֹ הִיא מִדַּת הַלַּח:\",3,0],[2,128,19,36,\"אשר הוצאתי אתכם. עַל מְנָת כֵּן; דָּ\\\"אַ אֲנִי הִבְחַנְתִּי בְּמִצְרַיִם בֵּין טִפָּה שֶׁל בְּכוֹר לְטִפָּה שֶׁאֵינָהּ שֶׁל בְּכוֹר, וַאֲנִי הַנֶּאֱמָן לִפָּרַע מִמִּי שֶׁטּוֹמֵן מִשְׁקְלוֹתָיו בַּמֶּלַח לְהוֹנוֹת אֶת הַבְּרִיּוֹת שֶׁאֵין מַכִּירִין בָּהֶם (בבא מציעא ס\\\"א):\",4,0],[2,128,20,2,\"ואל בני ישראל תאמר. עוֹנְשִׁין עַל הָאַזְהָרוֹת:\",1,0],[2,128,20,2,\"מות יומת. בְּבֵית דִּין, וְאִם אֵין כֹּחַ בְּבֵית דִּין, עַם הָאָרֶץ מְסַיְּעִין אוֹתָן (ספרא):\",2,0],[2,128,20,2,\"עם הארץ. עַם שֶׁבְּגִינוֹ נִבְרֵאת הָאָרֶץ, עַם שֶׁעֲתִידִין לִירַשׁ הָאָרֶץ עַל יְדֵי מִצְווֹת הַלָּלוּ (שם):\",3,0],[2,128,20,3,\"אתן את פני. פְּנַאי שֶׁלִּי — פּוֹנֶה אֲנִי מִכָּל עֲסָקַי וְעוֹסֵק בּוֹ (שם):\",1,0],[2,128,20,3,\"באיש. וְלֹא בַצִּבּוּר (שם), שֶׁאֵין כָּל הַצִּבּוּר נִכְרָתִין:\",2,0],[2,128,20,3,\"כי מזרעו נתן למלך. לְפִי שֶׁנֶּאֱמַר מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ (דברים י\\\"ח), בֶּן בְּנוֹ וּבֶן בִּתּוֹ מִנַּיִן? תַּ\\\"ל כִּי מִזַּרְעוֹ נָתַן לַמֹּלֶךְ, זֶרַע פָּסוּל מִנַּיִן? תַּ\\\"ל בְּתִתּוֹ מִזַּרְעוֹ לַמֹּלֶךְ (ספרא; סנהדרין ס\\\"ד):\",3,0],[2,128,20,3,\"למען טמא את מקדשי. אֶת כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא מְקֻדֶּשֶׁת לִי, כִּלְשׁוֹן וְלֹא יְחַלֵּל אֶת מִקְדָּשַׁי (ויקרא כ\\\"א):\",4,0],[2,128,20,4,\"ואם העלם יעלימו. אִם הֶעְלִימוּ בְּדָבָר אֶחָד, סוֹף שֶׁיַּעְלִימוּ בִדְבָרִים הַרְבֵּה; אִם הֶעְלִימוּ סַנְהֶדְרֵי קְטַנָּה, סוֹף שֶׁיַּעְלִימוּ סַנְהֶדְרֵי גְדוֹלָה (ספרא):\",1,0],[2,128,20,5,\"ובמשפחתו. אָמַר רַבִּי שִׁמְעון וכִי מִשְׁפָּחָה מֶה חָטְאָה? אֶלָּא לְלַמֶּדְךָ שֶׁאֵין לְךָ מִשְׁפָּחָה שֶׁיֵּשׁ בָּהּ מוֹכֵס שֶׁאֵין כֻּלָּם מוֹכְסִין — שֶׁכֻּלָּן מְחַפִּין עָלָיו (ספרא; שבועות ל\\\"ט):\",1,0],[2,128,20,5,\"והכרתי אתו. לָמָּה נֶאֱמַר? לְפִי שֶׁנֶּאֱמַר ובמשפחתו יָכוֹל יִהְיוּ כָל הַמִּשְׁפָּחָה בְּהִכָּרֵת, תַּ\\\"ל אֹתוֹ — אוֹתוֹ בְּהִכָּרֵת וְלֹא כָל הַמִּשְׁפָּחָה בְּהִכָּרֵת אֶלָּא בְּיִסּוּרִין (שם):\",2,0],[2,128,20,5,\"לזנות אחרי המלך. לְרַבּוֹת שְׁאַר עֲ\\\"זָ שֶׁעֲבָדָהּ בְּכָךְ וַאֲפִלּוּ אֵין זוֹ עֲבוֹדָתָהּ (ספרא):\",3,0],[2,128,20,7,\"והתקדשתם. זוֹ פְּרִישׁוּת עֲ\\\"זָ (שם):\",1,0],[2,128,20,9,\"אביו ואמו קלל. לְרַבּוֹת לְאַחַר מִיתָה (שם; סנהדרין פ\\\"ה):\",1,0],[2,128,20,9,\"דמיו בו. זוֹ סְקִילָה, וְכֵן כָּל מָקוֹם שֶׁנֶּאֱמַר דָּמָיו בּוֹ, דְּמֵיהֶם בָּם; וְלָמַדְנוּ מֵאוֹב וְיִדְּעוֹנִי, שֶׁנֶּאֱמַר בָּהֶם בָּאֶבֶן יִרְגְּמוּ אֹתָם דְּמֵיהֶם בָּם (ספרא; כריתות ה'). וּפְשׁוּטוֹ שֶׁל מִקְרָא, כְּמוֹ דָּמוֹ בְרֹאשׁוֹ (יהושע ב') — אֵין נֶעֱנָשׁ עַל מִיתָתוֹ אֶלָּא הוּא, שֶׁהוּא גָרַם לְעַצְמוֹ שֶׁיֵּהָרֵג:\",2,0],[2,128,20,10,\"ואיש. פְּרָט לְקָטָן:\",1,0],[2,128,20,10,\"אשר ינאף את אשת איש. פְּרָט לְאֵשֶׁת קָטָן, לִמְּדָנוּ שֶׁאֵין לְקָטָן קִדּוּשִׁין, וְעַל אֵיזוֹ אֵשֶׁת אִישׁ חִיַּבְתִּי לְךָ?\",2,0],[2,128,20,10,\"אשר ינאף את אשת רעהו. פְּרָט לְאֵשֶׁת גּוֹי, לִמְּדָנוּ שֶׁאֵין קִדּוּשִׁין לְגוֹי (ספרא; סנהדרין נ\\\"ב):\",3,0],[2,128,20,10,\"מות יומת הנאף והנאפת. כָּל מִיתָה הָאֲמוּרָה בַתּוֹרָה סְתָם, אֵינָהּ אֶלָּא חֶנֶק (ספרא; סנהדרין נ\\\"ה):\",4,0],[2,128,20,12,\"תבל עשו. גְּנַאי; לָשׁוֹן אַחֵר מְבַלְבְּלִין זֶרַע הָאָב בְּזֶרַע הַבֵּן:\",1,0],[2,128,20,13,\"משכבי אשה. מַכְנִיס כְּמִכְחוֹל בִּשְׁפוֹפֶרֶת:\",1,0],[2,128,20,14,\"ישרפו אתו ואתהן. אֵי אַתָּה יָכוֹל לוֹמַר אִשְׁתּוֹ הָרִאשׁוֹנָה יִשְׂרְפוּ, שֶׁהֲרֵי נְשָׂאָהּ בְּהֶתֵּר וְלֹא נֶאֶסְרָה עָלָיו, אֶלָּא אִשָּׁה וְאִמָּהּ הַכְּתוּבין כָּאן שְׁתֵּיהֶן לְאִסּוּר — שֶׁנָּשָׂא חֲמוֹתוֹ וְאִמָּהּ; וְיֵשׁ מֵרַבּוֹתֵינוּ שֶׁאוֹמְרִים אֵין כָּאן אֶלָּא חֲמוֹתוֹ, וּמַהוּ אֶתְהֶן? אֶת אַחַת מֵהֶן וְלָשׁוֹן יְוָנִי הוּא הֵן אַחַת (ספרא; סנהדרין ע\\\"ו):\",1,0],[2,128,20,15,\"ואת הבהמה תהרגו. אִם אָדָם חָטָא בְּהֵמָה מֶה חָטְאָה? אֶלָּא מִפְּנֵי שֶׁבָּאָה לָאָדָם תַּקָּלָה עַל יָדָהּ לְפִיכָךְ אָמַר הַכָּתוּב תִּסָּקֵל, קַל וָחֹמֶר לָאָדָם, שֶׁיּוֹדֵעַ לְהַבְחִין בֵּין טוֹב לְרַע, וְגוֹרֵם רָעָה לַחֲבֵרוֹ לַעֲבֹר עֲבֵרָה; כַּיּוֹצֵא בַדָּבָר אַתָּה אוֹמֵר אַבֵּד תְּאַבְּדוּן אֶת כָּל הַמְּקֹמוֹת (דברים י\\\"ב), הֲרֵי דְבָרִים קַל וָחֹמֶר, וּמָה אִילָנוֹת שֶׁאֵינָן רוֹאִין וְאֵינָן שׁוֹמְעִין, עַל שֶׁבָּאת תַּקָּלָה עַל יָדָם אָמְרָה תוֹרָה הַשְׁחֵת, שְׂרֹף וְכַלֵּה, הַמַּטֶּה אֶת חֲבֵרוֹ מִדֶּרֶךְ חַיִּים לְדַרְכֵי מִיתָה, עַל אַחַת כַּמָּה וְכַמָּה (ספרא):\",1,0],[2,128,20,17,\"חסד הוא. לְשׁוֹן אֲרַמִּי חֶרְפָּה חִסּוּדָא; וּמִדְרָשׁוֹ אִם תֹּאמַר קַיִן נָשָׂא אֲחוֹתוֹ חֶסֶד עָשָׂה הַמָּקוֹם, לִבְנוֹת עוֹלָמוֹ מִמֶּנּוּ, שֶׁנֶּאֱמַר (תהילים פ\\\"ט), עוֹלָם חֶסֶד יִבָּנֶה (ספרא; סנהדרין נ\\\"ח):\",1,0],[2,128,20,18,\"הערה. גִּלָּה, וְכֵן כָּל לְשׁוֹן עֶרְוָה גִּלּוּי הוּא, וְהַוָּי\\\"ו יוֹרֶדֶת בַּתֵּיבָה לְשֵׁם דָּבָר כְּמוֹ זַעֲוָה מִגִּזְרַת וְלֹא קָם וְלֹא זָע (אסתר ה'), וְכֵן אַחֲוָה מִגִּזְרַת אָח. וְהַעֲרָאָה זוֹ נֶחְלְקוּ בָהּ רַבּוֹתֵינוּ, יֵשׁ אוֹמְרִים זוֹ נְשִׁיקַת שַׁמָּשׁ, וְיֵשׁ אוֹמְרִים זוֹ הַכְנָסַת עֲטָרָה (יבמות נ\\\"ה):\",1,0],[2,128,20,19,\"וערות אחות אמך וגו'. שָׁנָה הַכָּתוּב בְּאַזְהָרָתָן, לוֹמַר שֶׁהֻזְהַר עֲלֵיהֶן בֵּין עַל אֲחוֹת אָבִיו וְאִמּוֹ מִן הָאָב, בֵּין עַל אַחְיוֹתֵיהֶן מִן הָאֵם, אֲבָל עֶרְוַת אֵשֶׁת אֲחִי אָבִיו לֹא הֻזְהַר אֶלָּא עַל אֵשֶׁת אֲחִי אָבִיו מִן הָאָב (עי' יבמות נ\\\"ד):\",1,0],[2,128,20,20,\"אשר ישכב את דדתו. הַמִּקְרָא הַזֶּה בָּא לְלַמֵּד עַל כָּרֵת הָאָמוּר לְמַעְלָה שֶׁהוּא בְעֹנֶשׁ הֲלִיכַת עֲרִירִי:\",1,0],[2,128,20,20,\"ערירים. כְּתַרְגּוּמוֹ, בְּלָא וְלָד, וְדוֹמֶה לוֹ וְאָנֹכִי הוֹלֵךְ עֲרִירִי (בראשית ט\\\"ו); יֵשׁ לוֹ בָנִים, קוֹבְרָן, אֵין לוֹ בָנִים, מֵת בְּלֹא בָנִים, לְכָךְ שִׁנָּה בִשְׁנֵי מִקְרָאוֹת אֵלּוּ — עֲרִירִים \\\"יָמֻתוּ\\\", עֲרִירִים \\\"יִהְיוּ\\\", ערירים ימתו. אִם יִהְיוּ לוֹ בִשְׁעַת עֲבֵרָה לֹא יִהְיוּ לוֹ כְּשֶׁיָּמוּת, לְפִי שֶׁקּוֹבְרָן בְּחַיָּיו, ערירים יהיו. אִם אֵין לוֹ בִּשְׁעַת עֲבֵרָה, יִהְיֶה כָל יָמָיו כְּמוֹ שֶׁהוּא עַכְשָׁו (ספרא; יבמות נ\\\"ה):\",2,0],[2,128,20,21,\"נדה הוא. הַשְּׁכִיבָה הַזֹּאת מְנֻדָּה הִיא וּמְאוּסָה; וְרַבּוֹתֵינוּ דָּרְשׁוּ לֶאֱסֹר הַעֲרָאָה בָהּ כְּנִדָּה שֶׁהַעֲרָאָה מְפֹרֶשֶׁת בָּהּ — אֶת מְקֹרָהּ הֶעֱרָה (יבמות נ\\\"ד):\",1,0],[2,128,20,23,\"ואקץ. לְשׁוֹן מִאוּס, כְּמוֹ קַצְתִּי בְחַיַּי (בראשית כ\\\"ז), כְּאָדָם שֶׁהוּא קָץ בִּמְזוֹנוֹ (ספרא):\",1,0],[2,128,20,25,\"והבדלתם בין הבהמה הטהרה לטמאה. אֵין צָרִיךְ לוֹמַר בֵּין פָּרָה לַחֲמוֹר, שֶׁהֲרֵי מֻבְדָּלִין וְנִכָּרִין הֵם, אֶלָּא בֵּין טְהוֹרָה לְךָ לִטְמֵאָה לְךָ — בֵּין שֶׁנִּשְׁחַט רֻבּוֹ שֶׁל סִימָן לְנִשְׁחַט חֶצְיוֹ, וְכַמָּה בֵּין רֻבּוֹ לְחֶצְיוֹ? מְלֹא שְׂעָרָה (ספרא):\",1,0],[2,128,20,25,\"אשר הבדלתי לכם לטמא. לֶאֱסֹר:\",2,0],[2,128,20,26,\"ואבדל אתכם מן העמים להיות לי. אִם אַתֶּם מֻבְדָּלִים מֵהֶם הֲרֵי אַתֶּם שֶׁלִּי, וְאִם לָאו הֲרֵי אַתֶּם שֶׁל נְבוּכַדְנֶאצַּר וַחֲבֵרָיו; רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה אוֹמֵר מִנַּיִן שֶׁלֹּא יֹאמַר אָדָם נַפְשִׁי קָצָה בִּבְשַׂר חֲזִיר, אִי אֶפְשִׁי לִלְבֹּשׁ כִּלְאַיִם, אֲבָל יֹאמַר אֶפְשִׁי וּמָה אֶעֱשֶׂה וְאָבִי שֶׁבַּשָּׁמַיִם גָּזַר עָלַי? תַּ\\\"ל וָאַבְדִּל אֶתְכֶם מִן הָעַמִּים לִהְיוֹת לִי, שֶׁתְּהֵא הַבְדָּלַתְכֶם מֵהֶם לִשְׁמִי — פּוֹרֵשׁ מִן הָעֲבֵרָה וּמְקַבֵּל עָלָיו עֹל מַלְכוּת שָׁמָיִם (ספרא):\",1,0],[2,128,20,27,\"כי יהיה בהם אוב וגו'. כָּאן נֶאֱמַר בָּהֶם מִיתָה וּלְמַעְלָה כָרֵת, עֵדִים וְהַתְרָאָה בִּסְקִילָה, מֵזִיד בְּלֹא הַתְרָאָה בְּהִכָּרֵת, וְשִׁגְגָתָם חַטָּאת, וְכֵן בְּכָל חַיָּבֵי מִיתוֹת שֶׁנֶּאֱמַר בָּהֶם כָּרֵת:\",1,0],[2,128,21,1,\"אמר אל הכהנים. אמר ואמרת, לְהַזְהִיר גְּדוֹלִים עַל הַקְּטַנִּים (יבמות קי\\\"ד):\",1,0],[2,128,21,1,\"בני אהרן. יָכוֹל חֲלָלִים תַּ\\\"ל הַכֹּהֲנִים:\",2,0],[2,128,21,1,\"בני אהרן. אַף בַּעֲלֵי מוּמִין בְּמַשְׁמָע:\",3,0],[2,128,21,1,\"בני אהרן. וְלֹא בְּנוֹת אַהֲרֹן (ספרא):\",4,0],[2,128,21,1,\"לא יטמא בעמיו. בְּעוֹד שֶׁהַמֵּת בְּתוֹךְ עַמָּיו, יָצָא מֵת מִצְוָה (שם):\",5,0],[2,128,21,2,\"כי אם לשארו. אֵין שְׁאֵרוֹ אֶלָּא אִשְׁתּוֹ (שם; יבמות כ\\\"ב):\",1,0],[2,128,21,3,\"הקרובה. לְרַבּוֹת אֶת הָאֲרוּסָה (ספרא; יבמות ס'):\",1,0],[2,128,21,3,\"אשר לא היתה לאיש. לְמִשְׁכָּב:\",2,0],[2,128,21,3,\"לה יטמא. מִצְוָה (ספרא; זבחים ק'):\",3,0],[2,128,21,4,\"לא יטמא בעל בעמיו להחלו. לֹא יִטַּמָּא לְאִשְׁתּוֹ פְּסוּלָה שֶׁהוּא מְחֻלָּל בָּהּ בְּעוֹדָהּ עִמּוֹ, וְכֵן פְּשׁוּטוֹ שֶׁל מִקְרָא: לֹא יִטַּמָּא בַּעַל בִּשְׁאֵרוֹ בְּעוֹד שֶׁהוּא בְּתוֹךְ עַמָּיו — שֶׁיֵּשׁ לָהּ קוֹבְרִין, שֶׁאֵינָהּ מֵת מִצְוָה, וּבְאֵיזֶה שְׁאֵר אָמַרְתִּי? בְּאוֹתוֹ שֶׁהוּא לְהֵחַלּוֹ — לְהִתְחַלֵּל הוּא מִכְּהֻנָּתוֹ (עי' ספרא; יבמות צ'):\",1,0],[2,128,21,5,\"לא יקרחה קרחה. עַל מֵת וַהֲלֹא אַף יִשְׂרָאֵל הֻזְהֲרוּ עַל כָּךְ? אֶלָּא לְפִי שֶׁנֶּאֱמַר בְּיִשְׂרָאֵל בֵּין עֵינֵיכֶם (דברים י\\\"ד), יָכוֹל לֹא יְהֵא חַיָּב עַל כָּל הָרֹאשׁ, תַּ\\\"ל בְּרֹאשָׁם, וְיִלָּמְדוּ יִשְׂרָאֵל מִכֹּהֲנִים בִּגְזֵרָה שָׁוָה, נֶאֱמַר כָּאן קָרְחָה וְנֶאֱמַר בְּיִשְׂרָאֵל קָרְחָה, מַה כָּאן כָּל הָרֹאשׁ אַף לְהַלָּן כָּל הָרֹאשׁ בְּמַשְׁמָע — כָּל מָקוֹם שֶׁיִּקְרַח בָּרֹאשׁ, וּמַה לְּהַלָּן עַל מֵת, אַף כָּאן עַל מֵת (מכות כ'):\",1,0],[2,128,21,5,\"ופאת זקנם לא יגלחו. לְפִי שֶׁנֶּאֱמַר בְּיִשְֹרָאֵל לֹא תַשְׁחִית, יָכוֹל לִקְּטוֹ בְּמַלְקֵט וּרְהִיטְנִי יְהֵא חַיָּב, לְכָךְ נֶאֱמַר לֹא יְגַלֵּחוּ. שֶׁאֵינוֹ חַיָּב אֶלָּא עַל דָּבָר הַקָּרוּי גִּלּוּחַ וְיֵשׁ בּוֹ הַשְׁחָתָה, וְזֶהוּ תַעַר (שם):\",2,0],[2,128,21,5,\"ובבשרם לא ישרטו שרטת. לְפִי שֶׁנֶּאֱמַר בְּיִשְׂרָאֵל וְשֶׂרֶט לָנֶפֶשׁ לֹא תִתְּנוּ (ויקרא י\\\"ט), יָכוֹל שָׂרַט חָמֵשׁ שְׂרִיטוֹת לֹא יְהֵא חַיָּב אֶלָּא אַחַת, תַּ\\\"ל לֹא יִשְׂרְטוּ שָׂרָטֶת, לְחַיֵּב עַל כָּל שְׂרִיטָה וּשְׂרִיטָה, שֶׁתֵּבָה זוֹ יְתֵרָה הִיא לִדְרֹשׁ, שֶׁהָיָה לוֹ לִכְתֹּב לֹא יִשְׂרְטוּ וַאֲנִי יוֹדֵעַ שֶׁהִיא שָׂרֶטֶת (ספרא; מב' כ'):\",3,0],[2,128,21,6,\"קדשים יהיו. עַל כָּרְחָם יַקְדִּישׁוּם בֵּית דִּין בְּכָךְ (ספרא):\",1,0],[2,128,21,7,\"זנה. שֶׁנִּבְעֲלָה בְעִילַת יִשְׂרָאֵל הָאָסוּר לָהּ, כְּגוֹן חַיָּבֵי כָּרֵתוֹת אוֹ נָתִין אוֹ מַמְזֵר (ספרא; יבמות ס\\\"א):\",1,0],[2,128,21,7,\"חללה. שֶׁנּוֹלְדָה מִן הַפְּסוּלִים שֶׁבַּכְּהֻנָּה, כְּגוֹן בַּת אַלְמָנָה מִכֹּהֵן גָּדוֹל אוֹ בַת גְּרוּשָׁה (וַחֲלוּצָה) מִכֹּהֵן הֶדְיוֹט, וְכֵן שֶׁנִּתְחַלְּלָה מִן הַכְּהֻנָּה עַל יְדֵי בִיאַת אֶחָד מִן הַפְּסוּלִים לִכְהֻנָּה (עי' ספרא, קידושין ע\\\"ז):\",2,0],[2,128,21,8,\"וקדשתו. עַל כָּרְחוֹ, שֶׁאִם לֹא רָצָה לְגָרֵשׁ הַלְקֵהוּ וְיַסְּרֵהוּ עַד שֶׁיְּגָרֵשׁ (ספרא; יבמות פ\\\"ח):\",1,0],[2,128,21,8,\"קדש יהיה לך. נְהֹג בּוֹ קְדֻשָּׁה, לִפְתֹּחַ רִאשׁוֹן בְּכָל דָּבָר וּלְבָרֵךְ רִאשׁוֹן בַּסְּעוּדָה (הוריות י\\\"ב):\",2,0],[2,128,21,9,\"כי תחל לזנות. כְּשֶׁתִּתְחַלֵּל עַ\\\"יְ זְנוּת, שֶׁהָיְתָה בָהּ זִקַּת בַּעַל וְזָנְתָה, אוֹ מִן הָאֵרוּסִין אוֹ מִן הַנִּשּׂוּאִין; וְרַבּוֹתֵינוּ נֶחְלְקוּ בַדָּבָר וְהַכֹּל מוֹדִים שֶׁלֹּא דִּבֵּר הַכָּתוּב בִּפְנוּיָה (עי' סנהדרין נ\\\"א):\",1,0],[2,128,21,9,\"את אביה היא מחללת. חִלְּלָה וּבִזְּתָה אֶת כְּבוֹדוֹ, שֶׁאוֹמְרִים עָלָיו אָרוּר שֶׁזּוֹ יָלַד, אָרוּר שֶׁזּוֹ גִּדֵּל (שם):\",2,0],[2,128,21,10,\"לא יפרע. לֹא יְגַדֵּל פֶּרַע עַל אֵבֶל, וְאֵיזֶהוּ גִּדּוּל פֶּרַע? יוֹתֵר מִשְּׁלוֹשִׁים יוֹם (שם):\",1,0],[2,128,21,11,\"ועל כל נפשת מת וגו'. בְּאֹהֶל הַמֵּת:\",1,0],[2,128,21,11,\"נפשת מת. לְהָבִיא רְבִיעִית דָּם מִן הַמֵּת שֶׁמְּטַמֵּא בָאֹהֶל (שם):\",2,0],[2,128,21,11,\"לאביו ולאמו לא יטמא. לֹא בָא אֶלָּא לְהַתִּיר לוֹ מֵת מִצְוָה (ספרא; נזיר מ\\\"ז):\",3,0],[2,128,21,12,\"ומן המקדש לא יצא. אֵינוֹ הוֹלֵךְ אַחַר הַמִּטָּה (סנהדרין י\\\"ח), וְעוֹד מִכָּאן לָמְדוּ רַבּוֹתֵינוּ שֶׁכֹּהֵן גָּדוֹל מַקְרִיב אוֹנֵן, וְכֵן מַשְׁמָעוֹ: אַף אִם מֵתוּ אָבִיו וְאִמּוֹ אֵינוֹ צָרִיךְ לָצֵאת מִן הַמִּקְדָּשׁ אֶלָּא עוֹבֵד עֲבוֹדָה:\",1,0],[2,128,21,12,\"ולא יחלל את מקדש. שֶׁאֵינוֹ מְחַלֵּל בְּכָךְ אֶת הָעֲבוֹדָה, שֶׁהִתִּיר לוֹ הַכָּתוּב, הָא כֹּהֵן הֶדְיוֹט שֶׁעָבַד אוֹנֵן חִלֵּל (זבחים ט\\\"ז; סנהדרין פ\\\"ח):\",2,0],[2,128,21,14,\"וחללה. שֶׁנּוֹלְדָה מִפְּסוּלֵי כְהֻנָּה (קידושין ע\\\"ז):\",1,0],[2,128,21,15,\"ולא יחלל זרעו. הָא אִם נָשָׂא אַחַת מִן הַפְּסוּלוֹת, זַרְעוֹ הֵימֶנָּה חָלָל מִדִּין קְדֻשַּׁת כְּהֻנָּה (שם):\",1,0],[2,128,21,17,\"לחם אלהיו. מַאֲכַל אֱלֹהָיו, כָּל סְעוּדָה קְרוּיָה לֶחֶם, כְּמוֹ \\\"עֲבַד לְחֶם רַב\\\" (דניאל ה'):\",1,0],[2,128,21,18,\"כי כל איש אשר בו מום לא יקרב. אֵינוֹ דִין שֶׁיִּקְרַב, כְּמוֹ הַקְרִיבֵהוּ נָא לְפֶחָתֶךָ (מלאכי א'):\",1,0],[2,128,21,18,\"חרם. שֶׁחָטְמוֹ שָׁקוּעַ בֵּין שְׁתֵּי הָעֵינַיִם, שֶׁכּוֹחֵל שְׁתֵּי עֵינָיו כְּאַחַת (ספרא; בכורות מ\\\"ג):\",2,0],[2,128,21,18,\"שרוע. שֶׁאֶחָד מֵאֵבָרָיו גָּדוֹל מֵחֲבֵרוֹ — עֵינוֹ אַחַת גְּדוֹלָה וְעֵינוֹ אַחַת קְטַנָּה, אוֹ שׁוֹקוֹ אַחַת אֲרֻכָּה מֵחֲבֶרְתָּהּ (ספרא; בכורות מ'):\",3,0],[2,128,21,20,\"או גבן. שׁורי\\\"ציולש בְּלַעַז, שֶׁגְּבִינֵי עֵינָיו שְׂעָרָן אָרֹךְ וְשׁוֹכֵב:\",1,0],[2,128,21,20,\"או דק. שֶׁיֵּשׁ לוֹ בְעֵינָיו דֹּק, שֶׁקּוֹרִים טיל\\\"א, כְּמוֹ \\\"הַנּוֹטֶה כַדֹּק\\\" (ישעיהו מ'):\",2,0],[2,128,21,20,\"או תבלל. דָּבָר הַמְבַלְבֵּל אֶת הָעַיִן, כְּגוֹן חוּט לָבָן הַנִּמְשָׁךְ מִן הַלֹּבֶן וּפוֹסֵק בַּסִּירָא, שֶׁהוּא עֹגֶל הַמַּקִּיף אֶת הַשָּׁחֹר שֶׁקּוֹרִים פרוני\\\"לא, וְהַחוּט הַזֶּה פּוֹסֵק אֶת הָעֹגֶל וְנִכְנָס בַּשָּׁחֹר; וְתַרְגּוּם תְּבַלּוּל \\\"חִלִּיז\\\", לְשׁוֹן חִלָּזוֹן, שֶׁהוּא דוֹמֶה לְתוֹלַעַת אוֹתוֹ הַחוּט, וְכֵן כִּנּוּהוּ חַכְמֵי יִשְֹרָאֵל בְּמוּמֵי הַבְּכוֹר חִלָּזוֹן, נָחָשׁ, עֵינָב (בכורות ל\\\"ח):\",3,0],[2,128,21,20,\"גרב או ילפת. מִינֵי שְׁחִין הֵם; גָּרָב זוֹ הַחֶרֶס, שְׁחִין הַיָּבֵשׁ מִבִּפְנִים וּמִבַּחוּץ, יַלֶּפֶת הִיא חֲזָזִית הַמִּצְרִית, וְלָמָּה נִקְרֵאת יַלֶּפֶת? שֶׁמְּלַפֶּפֶת וְהוֹלֶכֶת עַד יוֹם הַמִּיתָה, וְהוּא לַח מִבַּחוּץ וְיָבֵשׁ מִבִּפְנִים, וּבְמָקוֹם אַחֵר קוֹרֵא לַגָּרָב שְׁחִין הַלַּח מִבַּחוּץ וְיָבֵשׁ מִבִּפְנִים, שֶׁנֶּאֱמַר \\\"וּבַגָּרָב וּבֶחָרֶס\\\" (דברים כ\\\"ח), כְּשֶׁסָּמַךְ גָּרָב אֵצֶל חֶרֶס, קוֹרֵא לַיַּלֶּפֶת גָּרָב, וּכְשֶׁהוּא סָמוּךְ אֵצֶל יַלֶּפֶת, קוֹרֵא לַחֶרֶס גָּרָב, כָּךְ מְפֹרָשׁ בִּבְכוֹרוֹת (דף מ\\\"א):\",4,0],[2,128,21,20,\"מרוח אשך. לְפִי הַתַּרְגּוּם מְרַס פַּחֲדִין, שֶׁפְּחָדָיו מְרֻסָּסִין — שֶׁבֵּיצִים שֶׁלּוֹ כְתוּתִין, פְּחָדִין כְּמוֹ \\\"גִּידֵי פַחֲדָו יְשֹׂרָגוּ\\\" (איוב מ'):\",5,0],[2,128,21,21,\"כל איש אשר בו מום. לְרַבּוֹת שְׁאָר מוּמִין:\",1,0],[2,128,21,21,\"מום בו. בְּעוֹד מוּמוֹ בּוֹ פָּסוּל, הָא אִם עָבַר מוּמוֹ כָּשֵׁר (ספרא):\",2,0],[2,128,21,21,\"לחם אלהיו. כָּל מַאֲכָל קָרוּי לֶחֶם:\",3,0],[2,128,21,22,\"מקדשי הקדשים. אֵלּוּ קָדְשֵׁי הַקֳּדָשִׁים:\",1,0],[2,128,21,22,\"ומן הקדשים יאכל. אֵלּוּ קָדָשִׁים קַלִּים, וְאִם נֶאֶמְרוּ קָדְשֵׁי הַקֳּדָשִׁים לָמָּה נֶאֱמַר קָדָשִׁים קַלִּים? אִם לֹא נֶאֱמַר, הָיִיתִי אוֹמֵר בְּקָדְשֵׁי הַקֳּדָשִׁים יֹאכַל בַּעַל מוּם, שֶׁמָּצִינוּ שֶׁהֻתְּרוּ לְזָר, שֶׁאָכַל מֹשֶׁה בְּשַׂר הַמִּלּוּאִים, אֲבָל בְּחָזֶה וְשׁוֹק שֶׁל קָדָשִׁים קַלִּים לֹא יֹאכַל, שֶׁלֹּא מָצִינוּ זָר חוֹלֵק בָּהֶן, לְכָךְ נֶאֶמְרוּ קָדָשִׁים קַלִּים, כָּךְ מְפֹרָשׁ בִּזְבָחִים (דף ק\\\"א):\",2,0],[2,128,21,23,\"אך אל הפרכת. לְהַזּוֹת שֶׁבַע הַזָּאוֹת שֶׁעַל הַפָּרֹכֶת.\",1,0],[2,128,21,23,\"ואל המזבח. הַחִיצוֹן; וּשְׁנֵיהֶם הֻצְרְכוּ לִכָּתֵב, וּמְפֹרָשׁ בְּתֹ\\\"כֹּ:\",2,0],[2,128,21,23,\"ולא יחלל את מקדשי. שֶׁאִם עָבַד עֲבוֹדָתוֹ מְחֻלֶּלֶת לִפָּסֵל (ספרא):\",3,0],[2,128,21,24,\"וידבר משה. הַמִּצְוָה הַזֹּאת.\",1,0],[2,128,21,24,\"אל אהרן ואל בניו ואל כל בני ישראל. לְהַזְהִיר בֵּית דִּין עַל הַכֹּהֲנִים (עי' ספרא):\",2,0],[2,128,22,2,\"וינזרו. אֵין נְזִירָה אֶלָּא פְרִישָׁה, וְכֵן הוּא אוֹמֵר \\\"וַיִּנָּזֵר מֵאַחֲרַי\\\" (יחזקאל י\\\"ד), \\\"נָזֹרוּ אָחוֹר\\\" (ישעיהו א') — יִפְרְשׁוּ מִן הַקֳּדָשִׁים בִּימֵי טֻמְאָתָן (ספרא):\",1,0],[2,128,22,2,\"וינזרו מקדשי בני ישראל, אשר הם מקדשים לי ולא יחללו את שם קדשי. סָרֵס הַמִּקְרָא וְדָרְשֵׁהוּ:\",2,0],[2,128,22,2,\"אשר הם מקדשים לי. לְרַבּוֹת קָדְשֵׁי כֹהֲנִים עַצְמָן:\",3,0],[2,128,22,3,\"כל איש אשר יקרב. אֵין קְרִיבָה זוֹ אֶלָּא אֲכִילָה, וְכֵן מָצִינוּ שֶׁנֶּאֶמְרָה אַזְהָרַת אֲכִילַת קָדָשִׁים בְּטֻמְאָה בִּלְשׁוֹן נְגִיעָה, \\\"בְּכָל קֹדֶשׁ לֹא תִגָּע\\\" (ויקרא י\\\"ב), אַזְהָרָה לָאוֹכֵל, וּלְמָדוּהָ רַבּוֹתֵינוּ מִגְּזֵרָה שָׁוָה; וְאִאֶ\\\"ל שֶׁחַיָּב עַל הַנְּגִיעָה, שֶׁהֲרֵי נֶאֱמַר כָּרֵת עַל הָאֲכִילָה בְּצַו אֶת אַהֲרֹן (ויקרא ז'), שְׁתֵּי כָּרֵתוֹת זוֹ אֵצֶל זוֹ, וְאִם עַל הַנְּגִיעָה חַיָּב, לֹא הֻצְרַךְ לְחַיְּבוֹ עַל הָאֲכִילָה וְכֵן נִדְרַשׁ בְּתֹ\\\"כֹּ: וְכִי יֵשׁ נוֹגֵעַ חַיָּב? אִם כֵּן מַה תַּ\\\"ל יִקְרַב? מִשֶּׁיִּכְשַׁר לִקָּרֵב, שֶׁאֵין חַיָּבִים עָלָיו מִשּׁוּם טֻמְאָה אֶלָּא אִ\\\"כֵּ קָרְבוּ מַתִּירָיו (ספרא; זבחים מ\\\"ה): וְאִ\\\"תֹּ שָׁלוֹשׁ כָּרֵתוֹת בְּטֻמְאַת כֹּהֲנִים לָמָּה, כְּבָר נִדְרְשׁוּ בְּמַסֶּכֶת שְׁבוּעוֹת (דף ז'), אַחַת לִכְלָל וְאַחַת לִפְרָט וְכוּ':\",1,0],[2,128,22,3,\"וטמאתו עליו. וְטֻמְאַת הָאָדָם עָלָיו, יָכוֹל בַּבָּשָׂר הַכָּתוּב מְדַבֵּר — וְטֻמְאָתוֹ שֶׁל בָּשָׂר עָלָיו — וּבְטָהוֹר שֶׁאָכַל אֶת הַטָּמֵא הַכָּתוּב מְדַבֵּר, עַל כָּרְחֲךָ מִמַּשְׁמָעוֹ אַתָּה לָמֵד — בְּמִי שֶׁטֻּמְאָתוֹ פּוֹרַחַת מִמֶּנּוּ הַכָּתוּב מְדַבֵּר, וְזֶהוּ הָאָדָם שֶׁיֵּשׁ לוֹ טָהֳרָה בִּטְבִילָה (ספרא):\",2,0],[2,128,22,3,\"ונכרתה. יָכוֹל מִצַּד זֶה לְצַד זֶה — יִכָּרֵת מִמְּקוֹמוֹ וְיִתְיַשֵּׁב בְּמָקוֹם אַחֵר — תַּ\\\"ל אני ה', בְּכָל מָקוֹם אֲנִי (שם):\",3,0],[2,128,22,4,\"מזרע אהרן. אין לי אלא זרעו, גופו מנין, תלמוד לומר והוא צרוע, שיכול הואיל ומקריב אונן יקריב צרוע וזב, תלמוד לומר והוא:\",1,0],[2,128,22,4,\"עד אשר יטהר. ביאת השמש, או אינו אלא טבילה, נאמר כאן וטהר, ונאמר למטה וטהר (פסוק ז) ובא השמש וטהר, מה להלן ביאת שמש, אף כאן ביאת שמש:\",2,0],[2,128,22,4,\"בכל טמא נפש. בְּמִי שֶׁנִּטְמָא בְמֵת:\",3,0],[2,128,22,5,\"בכל שרץ אשר יטמא לו. בְּשִׁעוּר הָרָאוּי לְטַמֵּא — בְּכָעֲדָשָׁה (חגיגה י\\\"א):\",1,0],[2,128,22,5,\"או באדם. בְּמֵת:\",2,0],[2,128,22,5,\"אשר יטמא לו. בְּשִׁעוּרוֹ לְטַמֵּא וְזֶהוּ כַּזַּיִת (אהלות פ\\\"ב):\",3,0],[2,128,22,5,\"לכל טמאתו. לְרַבּוֹת נוֹגֵעַ בְּזָב וְזָבָה נִדָּה וְיוֹלֶדֶת:\",4,0],[2,128,22,6,\"נפש אשר תגע בו. בְּאֶחָד מִן הַטְּמֵאִים הַלָלוּ:\",1,0],[2,128,22,7,\"ואחר יאכל מן הקדשים. נִדְרֶשֶׁת בִּיבָמוֹת (דף ע\\\"ד), בִּתְרוּמָה שֶׁמֻּתָּר לְאָכְלָהּ בְּהַעֲרֵב הַשֶּׁמֶשׁ:\",1,0],[2,128,22,7,\"מן הקדשים. וְלֹא כָל הַקֳּדָשִׁים:\",2,0],[2,128,22,8,\"נבלה וטרפה לא יאכל לטמאה בה. לְעִנְיַן הַטֻּמְאָה הִזְהִיר כָּאן, שֶׁאִם אָכַל נִבְלַת עוֹף טָהוֹר שֶׁאֵין לָהּ טֻמְאַת מַגָּע וּמַשָּׂא אֶלָּא טֻמְאַת אֲכִילָה בְּבֵית הַבְּלִיעָה, אָסוּר לֶאֱכֹל בַּקֳּדָשִׁים; וְצָרִיךְ לוֹמַר \\\"וּטְרֵפָה\\\" — מִי שֶׁיֵּשׁ בְּמִינוֹ טְרֵפָה, יָצָא נִבְלַת עוֹף טָמֵא שֶׁאֵין בְּמִינוֹ טְרֵפָה:\",1,0],[2,128,22,9,\"ושמרו את משמרתי. מִלֶּאֱכֹל תְּרוּמָה בְּטֻמְאַת הַגּוּף (סנהדרין פ\\\"ג):\",1,0],[2,128,22,9,\"ומתו בו. לִמְּדָנוּ שֶׁהִיא מִיתָה בִידֵי שָׁמָיִם (שם):\",2,0],[2,128,22,10,\"לא יאכל קדש. בִּתְרוּמָה הַכָּתוּב מְדַבֵּר, שֶׁכָּל הָעִנְיָן דִּבֵּר בָּהּ:\",1,0],[2,128,22,10,\"תושב כהן ושכיר. תּוֹשָׁבוֹ שֶׁל כֹּהֵן וּשְׂכִירוֹ, לְפִיכָךְ \\\"תּוֹשַׁב\\\" זֶה נָקוּד פַּתָּח, לְפִי שֶׁהוּא דָּבוּק; וְאֵיזֶהוּ תּוֹשָׁב? זֶה נִרְצָע שֶׁהוּא קָנוּי לוֹ עַד הַיּוֹבֵל, וְאֵיזֶהוּ שָֹכִיר? זֶה קָנוּי קִנְיַן שָׁנִים שֶׁיּוֹצֵא בְשֵׁשׁ, בָּא הַכָּתוּב וְלִמֶּדְךָ כָּאן שֶׁאֵין גּוּפוֹ קָנוּי לַאֲדוֹנָיו לֶאֱכֹל בִּתְרוּמָתוֹ (ספרא; יבמות ע'):\",2,0],[2,128,22,11,\"וכהן כי יקנה נפש. עֶבֶד כְּנַעֲנִי שֶׁקָּנוּי לְגוּפוֹ:\",1,0],[2,128,22,11,\"ויליד ביתו. אֵלּוּ בְנֵי הַשְּׁפָחוֹת; וְאֵשֶׁת כֹּהֵן אוֹכֶלֶת בִּתְרוּמָה מִן הַמִּקְרָא הַזֶּה, שֶׁאַף הִיא קִנְיַן כַּסְפּוֹ, וְעוֹד לָמֵד מִמִּקְרָא אַחֵר (במדבר י\\\"ח), כָּל טָהוֹר בְּבֵיתְךָ וְגוֹ' בְּסִפְרֵי:\",2,0],[2,128,22,12,\"לאיש זר. לְלֵוִי וְיִשְׂרָאֵל (ספרא):\",1,0],[2,128,22,13,\"אלמנה וגרושה. מִן הָאִישׁ הַזָּר:\",1,0],[2,128,22,13,\"וזרע אין לה. מִמֶּנּוּ:\",2,0],[2,128,22,13,\"ושבה. הָא אִם יֵשׁ לָהּ זֶרַע מִמֶּנּוּ, אֲסוּרָה בִתְרוּמָה כָּל זְמַן שֶׁהַזֶּרַע קַיָּם (יבמות ע\\\"ז):\",3,0],[2,128,22,13,\"וכל זר לא יאכל בו. לֹא בָא אֶלָּא לְהוֹצִיא אֶת הָאוֹנֵן — שֶׁמֻּתָּר בִּתְרוּמָה, זָרוּת אָמַרְתִּי לְךָ וְלֹא אֲנִינוּת (שם שם ס\\\"ח):\",4,0],[2,128,22,14,\"כי יאכל קדש. תְּרוּמָה:\",1,0],[2,128,22,14,\"ונתן לכהן את הקדש. דָּבָר הָרָאוּי לִהְיוֹת קֹדֶשׁ, שֶׁאֵינוֹ פוֹרֵעַ לוֹ מָעוֹת, אֶלָּא פֵּרוֹת שֶׁל חֻלִּין וְהֵן נַעֲשִֹין תְּרוּמָה (פסחים ל\\\"ב):\",2,0],[2,128,22,15,\"ולא יחללו וגו'. לְהַאֲכִילָם לְזָרִים:\",1,0],[2,128,22,16,\"והשיאו אותם. אֶת עַצְמָם יִטְעֲנוּ עָוֹן באכלם את קדשיהם שֶׁהֻבְדְּלוּ לְשֵׁם תְּרוּמָה, וְקָדְשׁוּ וְנֶאֶסְרוּ עֲלֵיהֶן; וְאֻנְקְלוֹס שֶׁתִּרְגֵּם \\\"בְּמֵיכָלְהוֹן בְּסוֹאֲבָא\\\", שֶׁלֹּא לְצֹרֶךְ תִּרְגְּמוֹ כֵן:\",1,0],[2,128,22,16,\"והשיאו אותם. זֶה אֶחָד מִשְּׁלוֹשָׁה אֶתִים שֶׁהָיָה רַבִּי יִשְׁמָעֵאל דּוֹרֵשׁ בַּתּוֹרָה שֶׁמְּדַבְּרִים בָּאָדָם עַצְמוֹ, וְכֵן \\\"בְּיוֹם מְלֹאת יְמֵי נִזְרוֹ יָבִיא אֹתוֹ\\\" (במדבר ו') — הוּא יָבִיא אֶת עַצְמוֹ, וְכֵן \\\"וַיִּקְבֹּר אֹתוֹ בַגַּי\\\" (דברים ל\\\"ד) — הוּא קָבַר אֶת עַצְמוֹ, כָּךְ נִדְרָשׁ בְּסִפְרֵי:\",2,0],[2,128,22,18,\"נדריהם. הֲרֵי עָלַי:\",1,0],[2,128,22,18,\"נדבותם. הֲרֵי זוֹ:\",2,0],[2,128,22,19,\"לרצנכם. הָבִיאוּ דָּבָר הָרָאוּי לְרַצּוֹת אֶתְכֶם לְפָנַי, שֶׁיְּהֵא לָכֶם לְרָצוֹן, אפיי\\\"מנט בְּלַעַז, וְאֵיזֶהוּ הָרָאוּי לְרָצוֹן?\",1,0],[2,128,22,19,\"תמים זכר בבקר בכבשים ובעזים. אֲבָל בְּעוֹלַת הָעוֹף אֵין צָרִיךְ תַּמּוּת וְזַכְרוּת, וְאֵינוֹ נִפְסָל בְּמוּם אֶלָּא בְּחֶסְרוֹן אֵבֶר (ספרא):\",2,0],[2,128,22,21,\"לפלא נדר. לְהַפְרִישׁ בְּדִבּוּרוֹ:\",1,0],[2,128,22,22,\"עורת. שֵׁם דָּבָר שֶׁל מוּם עִוָּרוֹן בְּלָשׁוֹן נְקֵבָה — שֶׁלֹּא יְהֵא בוֹ מוּם שֶׁל עִוָּרוֹן:\",1,0],[2,128,22,22,\"או שבור. לֹא יִהְיֶה:\",2,0],[2,128,22,22,\"חרוץ. רִיס שֶׁל עַיִן שֶׁנִּסְדַּק אוֹ שֶׁנִּפְגַּם וְכֵן שְׂפָתוֹ שֶׁנִּסְדְּקָה אוֹ נִפְגְּמָה (בכורות ל\\\"ח):\",3,0],[2,128,22,22,\"יבלת. ורו\\\"אה בְּלַעַז:\",4,0],[2,128,22,22,\"גרב. מִין חֲזָזִית וְכֵן יַלֶּפֶת, וּלְשׁוֹן יַלֶּפֶת כְּמוֹ וַיִּלְפֹּת שִׁמְשׁוֹן (שופטים ט\\\"ז), שֶׁאֲחוּזָה בוֹ עַד יוֹם מִיתָה, שֶׁאֵין לָהּ רְפוּאָה:\",5,0],[2,128,22,22,\"לא תקריבו. שָׁלוֹשׁ פְּעָמִים, לְהַזְהִיר עַל הַקְדָּשָׁתָן וְעַל שְׁחִיטָתָן וְעַל זְרִיקַת דָּמָן (תמורה ו'):\",6,0],[2,128,22,22,\"ואשה לא תתנו. אַזְהָרַת הַקְטָרָתָן:\",7,0],[2,128,22,23,\"שרוע. אֵבֶר גָּדוֹל מֵחֲבֵרוֹ:\",1,0],[2,128,22,23,\"וקלוט. פַּרְסוֹתָיו קְלוּטוֹת (בכורות מ'):\",2,0],[2,128,22,23,\"נדבה תעשה אתו. לְבֶדֶק הַבַּיִת:\",3,0],[2,128,22,23,\"ולנדר. לַמִּזְבֵּחַ:\",4,0],[2,128,22,23,\"לא ירצה. אֵי זֶה הֶקְדֵּשׁ בָּא לְרַצּוֹת? הֱוֵי אוֹמֵר זֶה הֶקְדֵּשׁ הַמִּזְבֵּחַ (תמורה ז'):\",5,0],[2,128,22,24,\"ומעוך וכתות ונתוק וכרות. בַּבֵּיצִים אוֹ בַגִּיד:\",1,0],[2,128,22,24,\"מעוך. בֵּיצָיו מְעוּכִין בַּיָּד:\",2,0],[2,128,22,24,\"כתות. כְּתוּשִׁים יוֹתֵר מִמָּעוּךְ:\",3,0],[2,128,22,24,\"נתוק. תְּלוּשִׁין בַּיָּד עַד שֶׁנִּפְסְקוּ חוּטִים שֶׁתְּלוּיִים בָּהֶן, אֲבָל נְתוּנִים הֵם בְּתוֹךְ הַכִּיס, וְהַכִּיס לֹא נִתְלַשׁ:\",4,0],[2,128,22,24,\"וכרות. כְּרוּתִין בִּכְלִי וְעוֹדָן בַּכִּיס (בכורות ל\\\"ט):\",5,0],[2,128,22,24,\"[ומעוך. תַּרְגּוּמוֹ וְדִי מְרִיס, זֶהוּ לְשׁוֹנוֹ בַּאֲרָמִית, לְשׁוֹן כְּתִישָׁה:\",6,0],[2,128,22,24,\"וכתות תַּרְגּוּמוֹ וְדִי רְסִיס, כְּמוֹ \\\"הַבַּיִת הַגָּדוֹל רְסִיסִים\\\" (עמוס ו') — בְּקִיעוֹת דַּקּוֹת, וְכֵן \\\"קָנֶה הַמְרֻסָּס\\\" (שבת פ'):]\",7,0],[2,128,22,24,\"ובארצכם לא תעשו. דָּבָר זֶה לְסָרֵס שׁוּם בְּהֵמָה וְחַיָּה, וַאֲפִלּוּ טְמֵאָה, לְכָךְ נֶאֱמַר בְּאַרְצְכֶם לְרַבּוֹת כָּל אֲשֶׁר בְּאַרְצְכֶם, שֶׁאִאֶ\\\"לֹ לֹא נִצְטַוּוּ עַל הַסֵּרוּס אֶלָּא בָאָרֶץ, שֶׁהֲרֵי סֵרוּס חוֹבַת הַגּוּף הִיא וְכָל חוֹבַת הַגּוּף נוֹהֶגֶת בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ:\",8,0],[2,128,22,25,\"ומיד בן נכר. שֶׁהֵבִיא קָרְבָּן בְּיַד כֹּהֵן לְהַקְרִיבוֹ לַשָּׁמַיִם לא תקריבו לוֹ בַּעַל מוּם; וְאַעַ\\\"פִּ שֶׁלֹּא נֶאֶסְרוּ בַעֲלֵי מוּמִים לְקָרְבַּן בְּנֵי נֹחַ אֶלָּא אִ\\\"כֵּ מְחֻסְּרֵי אֵבֶר, זֹאת נוֹהֶגֶת בְּבָמָה שֶׁבַּשָּׂדוֹת, אֲבָל עַל הַמִּזְבֵּחַ שֶׁבַּמִּשְׁכָּן לֹא תַקְרִיבוּ, אֲבָל תְּמִימָה תְקַבְּלוּ מֵהֶם, לְכָךְ נֶאֱמַר לְמַעְלָה אִישׁ אִישׁ, לְרַבּוֹת אֶת הַגּוֹיִם שֶׁנּוֹדְרִים נְדָרִים וּנְדָבוֹת כְּיִשְׂרָאֵל (חולין י\\\"ג):\",1,0],[2,128,22,25,\"משחתם. חִבּוּלְהוֹן:\",2,0],[2,128,22,25,\"לא ירצו לכם. לְכַפֵּר עֲלֵיכֶם:\",3,0],[2,128,22,27,\"כי יולד. פְּרָט לְיוֹצֵא דֹפֶן (שם ל\\\"ח):\",1,0],[2,128,22,28,\"אתו ואת בנו. נוֹהֵג בַּנְּקֵבָה — שֶׁאָסוּר לִשְׁחֹט הָאֵם וְהַבֵּן אוֹ הַבַּת, וְאֵינוֹ נוֹהֵג בַּזְּכָרִים, וּמֻתָּר לִשְׁחֹט הָאָב וְהַבֵּן (שם ע\\\"ח):\",1,0],[2,128,22,28,\"אתו ואת בנו. אַף בְּנוֹ וְאוֹתוֹ בְּמַשְׁמָע (שם פ\\\"ב):\",2,0],[2,128,22,29,\"לרצנכם תזבחו. תְּחִלַּת זְבִיחַתְכֶם הִזָּהֲרוּ שֶׁתְּהֵא לְרָצוֹן לָכֶם, וּמַהוּ הָרָצוֹן?\",1,0],[2,128,22,29,\"ביום ההוא יאכל. לֹא בָא לְהַזְהִיר אֶלָּא שֶׁתְּהֵא שְׁחִיטָה עַל מְנָת כֵּן — אַל תִּשְׁחֲטוּהוּ עַל מְנָת לְאָכְלוֹ לְמָחָר, שֶׁאִם תַּחְשְׁבוּ בוֹ מַחֲשֶׁבֶת פְּסוּל לֹא יְהֵא לָכֶם לְרָצוֹן; דָּ\\\"אַ לרצנכם — לְדַעְתְּכֶם, מִכָּאן לַמִּתְעַסֵּק שֶׁפָּסוּל בִּשְׁחִיטַת קָדָשִׁים; וְאַעַ\\\"פִּ שֶּׁפֵּרֵט בַּנֶּאֱכָלִים לִשְׁנֵי יָמִים, חָזַר וּפֵרֵט בַּנֶּאֱכָלִין לְיוֹם אֶחָד שֶׁתְּהֵא זְבִיחָתָן עַל מְנָת לְאָכְלָן בִּזְמַנָּן:\",2,0],[2,128,22,30,\"ביום ההוא יאכל. לֹא בָא לְהַזְהִיר אֶלָּא שֶׁתְּהֵא שְׁחִיטָה עַל מְנָת כֵּן, שֶׁאִם לִקְבֹּעַ לוֹ זְמַן אֲכִילָה, כְּבָר כָּתוּב וּבְשַׂר זֶבַח תּוֹדַת שְׁלָמָיו וְגוֹ' (ויקרא ז'):\",1,0],[2,128,22,30,\"אני ה'. דַּע מִי גָזַר עַל הַדָּבָר וְאַל יֵקַל בְּעֵינֶיךָ:\",2,0],[2,128,22,31,\"ושמרתם. זוֹ הַמִּשְׁנָה:\",1,0],[2,128,22,31,\"ועשיתם. זֶה הַמַּעֲשֶׂה (ספרא):\",2,0],[2,128,22,32,\"ולא תחללו. לַעֲבֹר עַל דְּבָרַי מְזִידִין; מִמַּשְׁמָע שֶׁנֶּאֱמַר וְלֹא תְחַלְּלוּ מַה תַּ\\\"לֹ וְנִקְדַּשְׁתִּי? מְסֹר עַצְמְךָ וְקַדֵּשׁ שְׁמִי. יָכוֹל בְּיָחִיד, תַּ\\\"לֹ בתוך בני ישראל; וּכְשֶׁהוּא מוֹסֵר עַצְמוֹ יִמְסֹר עַצְמוֹ עַל מְנָת לָמוּת, שֶׁכָּל הַמּוֹסֵר עַצְמוֹ עַל מְנָת הַנֵּס, אֵין עוֹשִֹׁין לוֹ נֵס, שֶׁכֵּן מָצִינוּ בַחֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה שֶׁלֹּא מָסְרוּ עַצְמָן עַל מְנָת הַנֵּס, שֶׁנֶּאֱמַר (דניאל נ'), \\\"וְהֵן לָא יְדִיעַ לֶהֱוֵא לָךְ מַלְכָּא\\\" וְגוֹ', מַצִּיל וְלֹא מַצִּיל — \\\"יְדִיעַ לֶהֱוֵא לָךְ\\\" וְגו' (ספרא):\",1,0],[2,128,22,33,\"המוציא אתכם. עַל מְנָת כֵּן:\",1,0],[2,128,22,33,\"אני ה'. נֶאֱמָן לְשַׁלֵּם שָׂכָר (שם):\",2,0],[2,128,23,2,\"דבר אל בני ישראל, מועדי ה'. עֲשֵׂה מוֹעֲדוֹת שֶׁיִּהְיוּ יִשְֹרָאֵל מְלֻמָּדִין בָּהֶם, שֶׁמְּעַבְּרִים אֶת הַשָּׁנָה עַל גָּלֻיּוֹת שֶׁנֶּעֶקְרוּ מִמְּקוֹמָן לַעֲלוֹת לָרֶגֶל וַעֲדַיִן לֹא הִגִּיעוּ לִירוּשָׁלַיִם (ספרא):\",1,0],[2,128,23,3,\"ששת ימים. מָה עִנְיַן שַׁבָּת אֵצֶל מוֹעֲדוֹת? לְלַמֶּדְךָ שֶׁכָּל הַמְחַלֵּל אֶת הַמּוֹעֲדוֹת מַעֲלִין עָלָיו כְּאִלּוּ חִלֵּל אֶת הַשַּׁבָּתוֹת, וְכָל הַמְקַיֵּם אֶת הַמּוֹעֲדוֹת מַעֲלִין עָלָיו כְּאִלּוּ קִיֵּם אֶת הַשַּׁבָּתוֹת (שם):\",1,0],[2,128,23,4,\"אלה מועדי ה'. לְמַעְלָה מְדַבֵּר בְּעִבּוּר שָׁנָה וְכָאן מְדַבֵּר בְּקִדּוּשׁ הַחֹדֶשׁ:\",1,0],[2,128,23,5,\"בין הערבים. מִשֵּׁשׁ שָׁעוֹת וּלְמַעְלָה (שם):\",1,0],[2,128,23,5,\"פסח לה'. הַקְרָבַת קָרְבָּן שֶׁשְּׁמוֹ פֶּסַח:\",2,0],[2,128,23,8,\"והקרבתם אשה וגו'. הֵם הַמּוּסָפִין הָאֲמוּרִים בְּפָרָשַׁת פִּינְחָס, וְלָמָּה נֶאֶמְרוּ כָאן? לוֹמַר שֶׁאֵין הַמּוּסָפִין מְעַכְּבִין זֶה אֶת זֶה:\",1,0],[2,128,23,8,\"והקרבתם אשה לה'. מִכָּל מָקוֹם — אִם אֵין פָּרִים הָבֵא אֵילִים, וְאִם אֵין פָּרִים וְאֵילִים הָבֵא כְבָשִׂים (שם):\",2,0],[2,128,23,8,\"שבעת ימים. כָּל מָקוֹם שֶׁנֶּאֱמַר שִׁבְעַת שֵׁם דָּבָר הוּא — שָׁבוּעַ שֶׁל יָמִים, שטי\\\"נא בְּלַעַז, וְכֵן כָּל לְשׁוֹן שְׁמוֹנַת שֵׁשֶׁת חֲמֵשֶׁת שְׁלוֹשֶׁת:\",3,0],[2,128,23,8,\"מלאכת עבדה. אֲפִלּוּ מְלָאכוֹת הַחֲשׁוּבוֹת לָכֶם עֲבוֹדָה וְצֹרֶךְ — שֶׁיֵּשׁ חֶסְרוֹן כִּיס בְּבַטָּלָה שֶׁלָּהֶן — כְּגוֹן דָּבָר הָאָבֵד, כָּךְ הֵבַנְתִּי מִתֹּ\\\"כֹּ, דְּקָתָנֵי יָכוֹל אַף חֻלּוֹ שֶׁל מוֹעֵד יְהֵא אָסוּר בִּמְלֶאכֶת עֲבוֹדָה וְכוּ':\",4,0],[2,128,23,10,\"ראשית קצירכם. שֶׁתְּהֵא רִאשׁוֹנָה לַקָּצִיר (ספרא):\",1,0],[2,128,23,10,\"עמר. עֲשִׂירִית הָאֵיפָה כָּךְ הָיְתָה שְׁמָהּ, כְּמוֹ וַיָּמֹדּוּ בָעֹמֶר (שמות ט\\\"ז):\",2,0],[2,128,23,11,\"והניף. כָּל תְּנוּפָה מוֹלִיךְ וּמֵבִיא מַעֲלֶה וּמוֹרִיד, מוֹלִיךְ וּמֵבִיא לַעֲצֹר רוּחוֹת רָעוֹת, מַעֲלֶה וּמוֹרִיד לַעֲצֹר טְלָלִים רָעִים (מנחות ס\\\"ב):\",1,0],[2,128,23,11,\"לרצנכם. אִם תַּקְרִיבוּ כְּמִשְׁפָּט זֶה יִהְיֶה לְרָצוֹן לָכֶם:\",2,0],[2,128,23,11,\"ממחרת השבת. מִמָּחֳרַת יוֹם טוֹב הָרִאשׁוֹן שֶׁל פֶּסַח, שֶׁאִם אַתָּה אוֹמֵר שַׁבַּת בְּרֵאשִׁית אֵי אַתָּה יוֹדֵעַ אֵיזֶהוּ (ספרא; מנחות ס\\\"ו):\",3,0],[2,128,23,12,\"ועשיתם … כבש. חוֹבָה לָעֹמֶר הוּא בָא:\",1,0],[2,128,23,13,\"ומנחתו. מִנְחַת נְסָכָיו:\",1,0],[2,128,23,13,\"שני עשרנים. כְּפוּלָה הָיְתָה:\",2,0],[2,128,23,13,\"ונסכו יין רביעת ההין. אַעַ\\\"פִּ שֶׁמִּנְחָתוֹ כְפוּלָה אֵין נְסָכָיו כְּפוּלִים:\",3,0],[2,128,23,14,\"וקלי. קֶמַח עָשׂוּי מִכַּרְמֶל רַךְ שֶׁמְּיַבְּשִׁין אוֹתוֹ בַּתַּנּוּר:\",1,0],[2,128,23,14,\"וכרמל. הֵן קְלָיוֹת, שֶׁקּוֹרִין גרניי\\\"ליש:\",2,0],[2,128,23,14,\"בכל משבתיכם. נֶחְלְקוּ בוֹ חַכְמֵי יִשְֹרָאֵל, יֵשׁ שֶׁלָּמְדוּ מִכָּאן שֶׁהֶחָדָשׁ נוֹהֵג בְּחוּצָה לָאָרֶץ, וְיֵ\\\"אֹ לֹא בָא אֶלָּא לְלַמֵּד שֶׁלֹּא נִצְטַוּוּ עַל הֶחָדָשׁ אֶלָּא לְאַחַר יְרֻשָּׁה וִישִׁיבָה, מִשֶּׁכִּבְּשׁוּ וְחִלְּקוּ (קידושין ל\\\"ז):\",3,0],[2,128,23,15,\"ממחרת השבת. מִמָּחֳרַת יוֹם טוֹב:\",1,0],[2,128,23,15,\"תמימת תהיינה. מְלַמֵּד שֶׁמַּתְחִיל וּמוֹנֶה מִבָּעֶרֶב, שֶׁאִם לֹא כֵן אֵינָן תְּמִימוֹת (ספרא; מנחות ס\\\"ו):\",2,0],[2,128,23,16,\"השבת השביעת. כְּתַרְגּוּמוֹ שְׁבוּעֲתָא שְׁבִיעֵתָא:\",1,0],[2,128,23,16,\"עד ממחרת השבת השביעת תספרו. וְלֹא עַד בִּכְלָל, וְהֵן אַרְבָּעִים וְתִשְׁעָה יוֹם:\",2,0],[2,128,23,16,\"חמשים יום והקרבתם מנחה חדשה לה'. בַּיּוֹם הַחֲמִשִּׁים תַּקְרִיבוּהָ, וְאוֹמֵר אֲנִי זֶה מִדְרָשׁוֹ, אֲבָל פְּשׁוּטוֹ עַד מִמָּחֳרַת הַשַּׁבָּת הַשְּׁבִיעִת שֶׁהוּא יוֹם חֲמִשִּׁים תִּסְפְּרוּ, וּמִקְרָא מְסֹרָס הוּא:\",3,0],[2,128,23,16,\"מנחה חדשה. הִיא הַמִּנְחָה הָרִאשׁוֹנָה שֶׁהוּבְאָה מִן הֶחָדָשׁ, וְאִ\\\"תֹּ הֲרֵי קָרְבָה מִנְחַת הָעֹמֶר אֵינָהּ כִּשְׁאָר כָּל הַמְּנָחוֹת, שֶׁהִיא בָאָה מִן הַשְּׂעוֹרִים (מנחות י\\\"ד):\",4,0],[2,128,23,17,\"ממושבתיכם. וְלֹא מִחוּצָה לָאָרֶץ (ספרא):\",1,0],[2,128,23,17,\"לחם תנופה. לֶחֶם תְּרוּמָה, הַמּוּרָם לְשֵׁם גָּבוֹהַּ, וְזוֹ הִיא הַמִּנְחָה הַחֲדָשָׁה הָאֲמוּרָה לְמַעְלָה:\",2,0],[2,128,23,17,\"בכורים. רִאשׁוֹנָה לְכָל הַמְּנָחוֹת, אַף לְמִנְחַת קְנָאוֹת הַבָּאָה מִן שְׂעוֹרִים לֹא תִּקְרַב מִן הֶחָדָשׁ קֹדֶם לִשְׁתֵּי הַלֶּחֶם (שם):\",3,0],[2,128,23,18,\"על הלחם. בִּגְלַל הַלֶּחֶם, חוֹבָה לַלֶּחֶם (ספרא; מנחות מ\\\"ה):\",1,0],[2,128,23,18,\"ומנחתם ונסכיהם. כְּמִשְׁפַּט מִנְחָה וּנְסָכִים הַמְפֹרָשִׁים בְּכָל בְּהֵמָה בְּפָרָשַׁת נְסָכִים, שְׁלוֹשָׁה עֶשְׂרוֹנִים לַפָּר וּשְׁנֵי עֶשְׂרוֹנִים לָאַיִל וְעִשָּׂרוֹן לַכֶּבֶשׂ, זוֹ הִיא הַמִּנְחָה, וְהַנְּסָכִים חֲצִי הַהִין לַפָּר וּשְׁלִישִׁית הַהִין לָאַיִל וּרְבִיעִית הַהִין לַכֶּבֶשׂ:\",2,0],[2,128,23,19,\"ועשיתם שעיר עזים. יָכוֹל שִׁבְעַת הַכְּבָשִׂים וְהַשָּׂעִיר הָאֲמוּרִים כָּאן הֵם ז' הַכְּבָשִׂים וְהַשָּׂעִיר הָאֲמוּרִים בְּחֻמַּשׁ הַפְּקוּדִים, כְּשֶׁאַתָּה מַגִּיעַ אֵצֶל פָּרִים וְאֵילִים אֵינָן הֵם, אֱמֹר מֵעַתָּה אֵלּוּ לְעַצְמָן וְאֵלּוּ לְעַצְמָן — אֵלּוּ קָרְבוּ בִּגְלַל הַלֶּחֶם וְאֵלּוּ לַמּוּסָפִין (שם):\",1,0],[2,128,23,20,\"והניף הכהן אתם, תנופה. מְלַמֵּד שֶׁטְּעוּנִין תְּנוּפָה חַיִּים, יָכוֹל כֻּלָּם, תַּ\\\"לֹ \\\"עַל שְׁנֵי כְבָשִֹים\\\" (עי' מנחות ס\\\"ב):\",1,0],[2,128,23,20,\"קדש יהיו. לְפִי שֶׁשַּׁלְמֵי יָחִיד קָדָשִׁים קַלִּים, הֻזְקַק לוֹמַר בְּשַׁלְמֵי צִבּוּר שֶׁהֵן קָדְשֵׁי קָדָשִׁים:\",2,0],[2,128,23,22,\"ובקצרכם. חָזַר וְשָׁנָה, לַעֲבֹר עֲלֵיהֶם בִּשְׁנֵי לָאוין; אָמַר ר' אַבְדִּימֵי בְּרַבִּי יוֹסֵף, מָה רָאָה הַכָּתוּב לִתְּנָהּ בְאֶמְצַע הָרְגָלִים — פֶּסַח וַעֲצֶרֶת מִכָּאן וְרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים וְחַג מִכָּאן — ? לְלַמֶּדְךָ שֶׁכָּל הַנּוֹתֵן לֶקֶט שִׁכְחָה וּפֵאָה לֶעָנִי כָּרָאוּי, מַעֲלִין עָלָיו כְּאִלּוּ בָּנָה בֵּית הַמִּקְדָּשׁ וְהִקְרִיב קָרְבְּנוֹתָיו בְּתוֹכוֹ (ספרא):\",1,0],[2,128,23,22,\"תעזב. הַנַּח לִפְנֵיהֶם וְהֵם יִלְקְטוּ, וְאֵין לְךָ לְסַיֵּעַ לְאֶחָד מֵהֶם (פאה פ\\\"ה):\",2,0],[2,128,23,22,\"אני ה' אלהיכם. נֶאֱמָן לְשַׁלֵּם שָׂכָר:\",3,0],[2,128,23,24,\"זכרון תרועה. זִכְרוֹן פְּסוּקֵי זִכְרוֹנוֹת וּפְסוּקֵי שׁוֹפָרוֹת (ספרא: ראש השנה ל\\\"ב) לִזְכֹּר לָכֶם עֲקֵדַת יִצְחָק שֶׁקָּרַב תַּחְתָּיו אַיִל:\",1,0],[2,128,23,25,\"והקרבתם אשה. הַמּוּסָפִין הָאֲמוּרִין בְּחֻמַּשׁ הַפְּקוּדִים:\",1,0],[2,128,23,27,\"אך. כָּל אַכִין וְרַקִּין שֶׁבַּתּוֹרָה מִעוּטִים — מְכַפֵּר הוּא לַשָּׁבִים וְאֵינוֹ מְכַפֵּר עַל שֶׁאֵינָם שָׁבִים (ספרא):\",1,0],[2,128,23,30,\"והאבדתי. לְפִי שֶׁהוּא אוֹמֵר כָּרֵת בְּכָל מָקוֹם וְאֵינִי יוֹדֵעַ מַה הוּא, כְּשֶׁהוּא אוֹמֵר וְהַאֲבַדְתִּי, לִמֵּד עַל הַכָּרֵת שֶׁאֵינוֹ אֶלָּא אֲבַדּוֹן:\",1,0],[2,128,23,31,\"כל מלאכה וגו'. לַעֲבֹר עָלָיו בְּלָאוִין הַרְבֵּה, אוֹ לְהַזְהִיר עַל מְלֶאכֶת לַיְלָה כִּמְלֶאכֶת יוֹם:\",1,0],[2,128,23,35,\"מקרא קדשׁ. קַדְּשֵׁהוּ בִכְסוּת נְקִיָּה וּבִתְפִלָּה, וּבִשְׁאָר יָמִים טוֹבִים בְּמַאֲכָל וּבְמִשְׁתֶּה וּבִכְסוּת נְקִיָּה וּבִתְפִלָּה (עי' ספרא):\",1,0],[2,128,23,36,\"עצרת הוא. עָצַרְתִּי אֶתְכֶם אֶצְלִי; כְּמֶלֶךְ שֶׁזִּמֵּן אֶת בָּנָיו לִסְעוּדָה לְכָךְ וְכָךְ יָמִים, כֵּיוָן שֶׁהִגִּיעַ זְמַנָּן לִפָּטֵר, אָמַר, בָּנַי בְּבַקָּשָׁה מִכֶּם עַכְּבוּ עִמִּי עוֹד יוֹם אֶחָד, קָשָׁה עָלַי פְּרֵדַתְכֶם:\",1,0],[2,128,23,36,\"כל מלאכת עבדה. אֲפִלּוּ מְלָאכָה שֶׁהִיא עֲבוֹדָה לָכֶם, שֶׁאִם לֹא תַעֲשׂוּהָ יֵשׁ חֶסְרוֹן כִּיס בַּדָּבָר.\",2,0],[2,128,23,36,\"לא תעשו. יָכוֹל אַף חֻלּוֹ שֶׁל מוֹעֵד יְהֵא אָסוּר בִּמְלֶאכֶת עֲבוֹדָה, תַּ\\\"לֹ \\\"הִוא\\\" (שם):\",3,0],[2,128,23,37,\"עלה ומנחה. מִנְחַת נְסָכִים הַקְּרֵבָה עִם הָעוֹלָה:\",1,0],[2,128,23,37,\"דבר יום ביומו. חֹק הַקָּצוּב בְּחֻמַּשׁ הַפְּקוּדִים:\",2,0],[2,128,23,37,\"דבר יום ביומו. הָא אִם עָבַר יוֹמוֹ בָּטֵל קָרְבָּנוֹ (עי' ספרא):\",3,0],[2,128,23,39,\"אך בחמשה עשר יום, תחגו. קָרְבַּן שְׁלָמִים לַחֲגִיגָה, יָכוֹל תִּדְחֶה אֶת הַשַּׁבָּת, תַּ\\\"לֹ אַךְ, הוֹאִיל וְיֵשׁ לָהּ תַּשְׁלוּמִין כָּל שִׁבְעָה:\",1,0],[2,128,23,39,\"באספכם את תבואת הארץ. שֶׁיְּהֵא חֹדֶשׁ שְׁבִיעִי זֶה בָּא בִּזְמַן אֲסִיפָה, מִכָּאן שֶׁנִּצְטַוּוּ לְעַבֵּר אֶת הַשָּׁנִים, שֶׁאִם אֵין הָעִבּוּר, פְּעָמִים שֶׁהוּא בְאֶמְצַע הַקַּיִץ אוֹ הַחֹרֶף:\",2,0],[2,128,23,39,\"תחגו. שַׁלְמֵי חֲגִיגָה:\",3,0],[2,128,23,39,\"שבעת ימים. אִם לֹא הֵבִיא בָזֶה, יָבִיא בָזֶה, יָכוֹל יְהֵא מְבִיאָן כָּל שִׁבְעָה, תַּלְמוּד לוֹמַר וחגתם אתו — יוֹם אֶחָד בְּמַשְׁמָע וְלֹא יוֹתֵר, וְלָמָּה נֶאֱמַר שִׁבְעָה? לְתַשְׁלוּמִין (חגיגה ט'):\",4,0],[2,128,23,40,\"פרי עץ הדר. עֵץ שֶׁטַּעַם עֵצוֹ וּפִרְיוֹ שָׁוֶה (סכה ל\\\"ה):\",1,0],[2,128,23,40,\"הדר. הַדָּר בְּאִילָנוֹ מִשָּׁנָה לְשָׁנָה, וְזֶהוּ אֶתְרוֹג (שם):\",2,0],[2,128,23,40,\"כפת תמרים. חָסֵר וי\\\"ו, לִמֵּד שֶׁאֵינָהּ אֶלָּא אַחַת:\",3,0],[2,128,23,40,\"וענף עץ עבת. שֶׁעֲנָפָיו קְלוּעִים כַּעֲבוֹתוֹת וְכַחֲבָלִים, וְזֶהוּ הֲדַס, הֶעָשׂוּי כְּמִין קְלִיעָה (שם ל\\\"ב):\",4,0],[2,128,23,42,\"האזרח. זֶה אֶזְרָח, בישראל — לְרַבּוֹת אֶת הַגֵּרִים (ספרא):\",1,0],[2,128,23,43,\"כי בסכות הושבתי. עַנְנֵי כָבוֹד (שם; מכילתא י\\\"ב):\",1,0],[2,128,24,2,\"צו את בני ישראל. זוֹ פָרָשַׁת מִצְוַת הַנֵּרוֹת, וּפָרָשַׁת וְאַתָּה תְּצַוֶּה לֹא נֶאֶמְרָה אֶלָּא עַל סֵדֶר מְלֶאכֶת הַמִּשְׁכָּן, לְפָרֵשׁ צֹרֶךְ הַמְּנוֹרָה, וְכֵן מַשְׁמָע: וְאַתָּה סוֹפְךָ לְצַוּוֹת אֶת בְּנֵי יִשְׂרָאֵל עַל כָּךְ:\",1,0],[2,128,24,2,\"שמן זית זך. שְׁלוֹשָׁה שְׁמָנִים יוֹצְאִים מִן הַזַּיִת, הָרִאשׁוֹן קָרוּי זָךְ, וְהֵן מְפֹרָשִׁין בִּמְנָחוֹת (דף פ\\\"ו) וּבְתֹ\\\"כֹּ:\",2,0],[2,128,24,2,\"תמיד. מִלַּיְלָה לְלַיְלָה, כְּמוֹ עוֹלַת תָּמִיד, שֶׁאֵינָהּ אֶלָּא מִיּוֹם לְיוֹם:\",3,0],[2,128,24,3,\"לפרכת העדת. שֶׁלִּפְנֵי הָאָרוֹן שֶׁהוּא קָרוּי עֵדוּת; וְרַבּוֹתֵינוּ דָרְשׁוּ עַל נֵר מַעֲרָבִי, שֶׁהוּא עֵדוּת לְכָל בָּאֵי עוֹלָם שֶׁהַשְּׁכִינָה שׁוֹרָה בְיִשְׂרָאֵל, שֶׁנּוֹתֵן בָּהּ שֶׁמֶן כְּמִדַּת חַבְרוֹתֶיהָ, וּמִמֶּנָּה הָיָה מַתְחִיל וּבָהּ הָיָה מְסַיֵּם (שבת כ\\\"ב; מנחות פ\\\"ו):\",1,0],[2,128,24,3,\"יערך אתו אהרן מערב עד בקר. יַעֲרֹךְ אוֹתוֹ עֲרִיכָה הָרְאוּיָה לְמִדַּת כָּל הַלַּיְלָה, וְשִׁעֲרוּ חֲכָמִים חֲצִי לֹג לְכָל נֵר וָנֵר, וְהֵן כְּדַאי אַף לְלֵילֵי תְּקוּפַת טֵבֵת, וּמִדָּה זוֹ הֻקְבְּעָה לָהֶם (מנחות פ\\\"ט):\",2,0],[2,128,24,4,\"המנרה הטהרה. שֶׁהִיא זָהָב טָהוֹר; דָּ\\\"אַ עַל טָהֳרָהּ שֶׁל מְנוֹרָה, שֶׁמְּטַהֲרָהּ וּמְדַשְּׁנָהּ תְּחִלָּה מִן הָאֵפֶר (עי' ספרא):\",1,0],[2,128,24,6,\"שש המערכת. שֵׁשׁ חַלּוֹת הַמַּעֲרֶכֶת הָאַחַת:\",1,0],[2,128,24,6,\"השלחן הטהר. שֶׁל זָהָב טָהוֹר; דָּ\\\"אַ: עַל טָהֳרוֹ שֶׁל שֻׁלְחָן, שֶׁלֹּא יִהְיוּ הַסְּנִיפִין מַגְבִּיהִין אֶת הַלֶּחֶם מֵעַל גַּבֵּי הַשֻּׁלְחָן (שם; מנחות צ\\\"ז):\",2,0],[2,128,24,7,\"ונתת על המערכת. עַל כָּל אַחַת מִשְּׁתֵי הַמַּעֲרָכוֹת; וְהָיוּ שְׁנֵי בְזִיכֵי לְבוֹנָה מְלֹא קֹמֶץ לְכָל אַחַת:\",1,0],[2,128,24,7,\"והיתה. הַלְּבוֹנָה הַזֹּאת:\",2,0],[2,128,24,7,\"ללחם לאזכרה. שֶׁאֵין מִן הַלֶּחֶם לְגָבוֹהַּ כְּלוּם, אֶלָּא הַלְּבוֹנָה נִקְטֶרֶת כְּשֶׁמְּסַלְּקִין אוֹתוֹ בְּכָל שַׁבָּת וְשַׁבָּת, וְהִיא לְזִכָּרוֹן לַלֶּחֶם, שֶׁעַל יָדָהּ הוּא נִזְכָּר לְמַעְלָה, כַּקֹּמֶץ שֶׁהִיא אַזְכָּרָה לַמִּנְחָה (עי' ספרא):\",3,0],[2,128,24,9,\"והיתה. הַמִּנְחָה הַזֹּאת, שֶׁכָּל דָּבָר הַבָּא מִן הַתְּבוּאָה בִּכְלַל מִנְחָה הוּא:\",1,0],[2,128,24,9,\"ואכלהו. מוּסָב עַל הַלֶּחֶם שֶׁהוּא לְשׁוֹן זָכָר:\",2,0],[2,128,24,10,\"ויצא בן אשה ישראלית. מֵהֵיכָן יָצָא? רַבִּי לֵוִי אוֹמֵר מֵעוֹלָמוֹ יָצָא, רַבִּי בְּרֶכְיָה אוֹמֵר מִפָּרָשָׁה שֶׁלְּמַעְלָה יָצָא, לִגְלֵג וְאָמַר \\\"בְּיוֹם הַשַּׁבָּת יַעַרְכֶנּוּ\\\" דֶּרֶךְ הַמֶּלֶךְ לֶאֱכֹל פַּת חַמָּה בְכָל יוֹם, שֶׁמָּא פַּת צוֹנֶנֶת שֶׁל תִּשְׁעָה יָמִים, בִּתְמִיהָ? וּמַתְנִיתָא אֲמַרָה מִבֵּית דִּינוֹ שֶׁל מֹשֶׁה יָצָא, מְחֻיָּב, בָּא לִטַּע אָהֳלוֹ בְתוֹךְ מַחֲנֵה דָן, אָמְרוּ לוֹ מַה טִּיבְךָ לְכָאן? אָמַר לָהֶם מִבְּנֵי דָּן אֲנִי, אָמְרוּ לוֹ \\\"אִישׁ עַל דִּגְלוֹ בְאֹתֹת לְבֵית אֲבֹתָם\\\" כְּתִיב (במדבר ב'), נִכְנַס לְבֵית דִּינוֹ שֶׁל מֹשֶׁה וְיָצָא מְחֻיָּב, עָמַד וְגִדֵּף (ספרא, ויקרא ל\\\"ב):\",1,0],[2,128,24,10,\"בן איש מצרי. הוּא הַמִּצְרִי שֶׁהָרַג מֹשֶׁה (שם):\",2,0],[2,128,24,10,\"בתוך בני ישראל. מְלַמֵּד שֶׁנִּתְגַיֵּר (ספרא):\",3,0],[2,128,24,10,\"וינצו במחנה. עַל עִסְקֵי הַמַּחֲנֶה:\",4,0],[2,128,24,10,\"ואיש הישראלי. זֶה שֶׁכְּנֶגְדּוֹ שֶׁמִּחָה בוֹ מִטַּע אָהֳלוֹ:\",5,0],[2,128,24,11,\"ויקב. כְּתַרְגּוּמוֹ \\\"וּפָרֵשׁ\\\", שֶׁנָּקַב שֵׁם הַמְיֻחָד וְגִדֵּף, וְהוּא שֵׁם הַמְפֹרָשׁ שֶׁשָּׁמַע מִסִּינַי (ספרא):\",1,0],[2,128,24,11,\"ושם אמו שלמית בת דברי. שִׁבְחָן שֶׁל יִשְֹרָאֵל שֶׁפִּרְסְמָהּ הַכָּתוּב לְזוֹ, לוֹמַר שֶׁהִיא לְבַדָּהּ הָיְתָה זוֹנָה:\",2,0],[2,128,24,11,\"שלמית. דַּהֲוָה פִּטְפְּטָה \\\"שְׁלָם עֲלָךְ\\\", \\\"שְׁלָם עֲלֵיכוֹן\\\", מְפַטְפֶּטֶת בִּדְבָרִים, שׁוֹאֶלֶת בִּשְׁלוֹם הַכֹּל:\",3,0],[2,128,24,11,\"בת דברי. דַּבְּרָנִית הָיְתָה, מְדַבֶּרֶת עִם כָּל אָדָם, לְפִיכָךְ קִלְקְלָה:\",4,0],[2,128,24,11,\"למטה דן. מַגִּיד שֶׁהָרָשָׁע גּוֹרֵם גְּנַאי לוֹ, גְּנַאי לְאָבִיו, גְּנַאי לְשִׁבְטוֹ; כַּיּוֹצֵא בוֹ \\\"אָהֳלִיאָב בֶּן אֲחִיסָמָךְ לְמַטֵּה דָן\\\" (שמות ל\\\"א), שֶׁבַח לוֹ, שֶׁבַח לְאָבִיו, שֶׁבַח לְשִׁבְטוֹ (ספרא):\",5,0],[2,128,24,12,\"ויניחהו. לְבַדּוֹ, וְלֹא הִנִּיחוּ מְקוֹשֵׁשׁ עִמּוֹ — שֶׁשְּׁנֵיהֶם הָיוּ בְּפֶרֶק אֶחָד — וְיוֹדְעִים הָיוּ שֶׁהַמְּקוֹשֵׁשׁ בְּמִיתָה, אֲבָל לֹא פֹרַשׁ לָהֶם בְּאֵיזוֹ מִיתָה לְכָךְ נֶאֱמַר (במדבר ט\\\"ו), כִּי לֹא פֹרַשׁ מַה יֵּעָשֶֹה לוֹ; אֲבָל בַּמְּקַלֵּל הוּא אוֹמֵר לִפְרֹשׁ לָהֶם, שֶׁלֹּא הָיוּ יוֹדְעִים אִם חַיָּב מִיתָה אִם לָאו (ספרא; סנהדרין ע\\\"ח):\",1,0],[2,128,24,14,\"השמעים. אֵלּוּ הָעֵדִים:\",1,0],[2,128,24,14,\"כל. לְהָבִיא אֶת הַדַּיָּנִים (ספרא):\",2,0],[2,128,24,14,\"את ידיהם. אוֹמְרִים לוֹ דָּמְךָ בְּרֹאשְׁךָ, וְאֵין אָנוּ נֶעֱנָשִׁים בְּמִיתָתְךָ, שֶׁאַתָּה גָרַמְתָּ לְךָ (שם):\",3,0],[2,128,24,14,\"כל העדה. בְּמַעֲמַד כָּל הָעֵדָה, (מִכָּאן) שֶׁשְּׁלוּחוֹ שֶׁל אָדָם כְּמוֹתוֹ (עי' שם):\",4,0],[2,128,24,15,\"ונשא חטאו. בְּכָרֵת כְּשֶׁאֵין הַתְרָאָה:\",1,0],[2,128,24,16,\"ונקב שם. אֵינוֹ חַיָּב עַד שֶׁיְּפָרֵשׁ אֶת הַשֵּׁם, וְלֹא הַמְקַלֵּל בְּכִנוּי (סנהדרין נ\\\"ו):\",1,0],[2,128,24,16,\"ונקב. לְשׁוֹן קְלָלָה כְּמוֹ (במדבר כ\\\"ג) \\\"מָה אֶקֹּב\\\" (סנהדרין נ\\\"ו):\",2,0],[2,128,24,17,\"ואיש כי יכה. לְפִי שֶׁנֶּאֱמַר מַכֵּה אִישׁ וָמֵת (שמות כ\\\"א), אֵין לִי אֶלָּא שֶׁהָרַג אֶת הָאִישׁ, אִשָּׁה וְקָטָן מִנַּיִן? תַּ\\\"לֹ \\\"כָּל נֶפֶשׁ אָדָם\\\":\",1,0],[2,128,24,20,\"כן ינתן בו. פֵּרְשׁוּ רַבּוֹתֵינוּ שֶׁאֵינוֹ נְתִינַת מוּם מַמָּשׁ אֶלָּא תַּשְׁלוּמֵי מָמוֹן, שָׁמִין אוֹתוֹ כְּעֶבֶד, לְכָךְ כָּתוּב בּוֹ לְשׁוֹן נְתִינָה — דָּבָר הַנָּתוּן מִיָּד לְיָד (בבא קמא פ\\\"ד; כתובות ל\\\"ב):\",1,0],[2,128,24,21,\"ומכה בהמה ישלמנה. לְמַעְלָה דִּבֵּר בְּהוֹרֵג בְּהֵמָה וְכָאן דִּבֵּר בְּעוֹשֶׂה בָהּ חַבּוּרָה:\",1,0],[2,128,24,21,\"ומכה אדם יומת. אֲפִלּוּ לֹא הֲרָגוֹ אֶלָּא עָשָׂה בוֹ חַבּוּרָה, שֶׁלֹּא נֶאֱמַר כָּאן נֶפֶשׁ; וּבְמַכֵּה אָבִיו וְאִמּוֹ דִּבֵּר הַכָּתוּב, וּבָא לְהַקִּישׁוֹ לְמַכֵּה בְהֵמָה, מַה מַּכֵּה בְהֵמָה מֵחַיִּים, אַף מַכֵּה אָבִיו מֵחַיִּים, פְּרָט לְמַכֶּה לְאַחַר מִיתָה; לְפִי שֶׁמָּצִינוּ שֶׁהַמְקַלְּלוֹ לְאַחַר מִיתָה חַיָּב, הֻצְרַךְ לוֹמַר בַּמַּכֶּה שֶׁפָּטוּר, וּמַה בִּבְהֵמָה בְּחַבָּלָה, שֶׁאִם אֵין חַבָּלָה אֵין תַּשְׁלוּמִין, אַף מַכֵּה אָבִיו אֵינוֹ חַיָּב עַד שֶׁיַּעֲשֶֹה בוֹ חַבּוּרָה (ספרא; סנהדרין פ\\\"ד):\",2,0],[2,128,24,22,\"אני ה' אלהיכם. אֱלֹהֵי כֻלְּכֶם, כְּשֵׁם שֶׁאֲנִי מְיַחֵד שְׁמִי עֲלֵיכֶם, כָּךְ אֲנִי מְיַחֲדוֹ עַל הַגֵּרִים:\",1,0],[2,128,24,23,\"ובני ישראל עשו. כָּל הַמִּצְוָה הָאֲמוּרָה בַּסְּקִילָה בְּמָקוֹם אַחֵר — דְּחִיָּה, רְגִימָה וּתְלִיָּה (עי' ספרא; סנהדרין מ\\\"ג):\",1,0],[2,128,25,1,\"בהר סיני. מָה עִנְיַן שְׁמִטָּה אֵצֶל הַר סִינַי? וַהֲלֹא כָל הַמִּצְוֹת נֶאֶמְרוּ מִסִּינַי? אֶלָּא מַה שְּׁמִטָּה נֶאֶמְרוּ כְלָלוֹתֶיהָ וּפְרָטוֹתֶיהָ וְדִקְדּוּקֶיהָ מִסִּינַי אַף כֻּלָּן נֶאֶמְרוּ כְלָלוֹתֵיהֶן וְדִקְדּוּקֵיהֶן מִסִּינַי, כָּךְ שְׁנוּיָה בְּתֹ\\\"כֹּ; וְנִרְאֶה לִי שֶׁכָּךְ פֵּרוּשָׁהּ: לְפִי שֶׁלֹּא מָצִינוּ שְׁמִטַּת קַרְקָעוֹת שֶׁנִּשְׁנֵית בְּעַרְבוֹת מוֹאָב בְּמִשְׁנֵה תוֹרָה, לָמַדְנוּ שֶׁכְּלָלוֹתֶיהָ וּפְרָטוֹתֶיהָ כֻּלָּן נֶאֶמְרוּ מִסִּינַי, וּבָא הַכָּתוּב וְלִמֵּד כָּאן עַל כָּל דִּבּוּר שֶׁנִּדְבַּר לְמֹשֶׁה, שֶׁמִּסִּינַי הָיוּ כֻלָּם, כְּלָלוֹתֵיהֶן וְדִקְדּוּקֵיהֶן, וְחָזְרוּ וְנִשְׁנוּ בְּעַרְבוֹת מוֹאָב:\",1,0],[2,128,25,2,\"שבת לה'. לְשֵׁם ה', כְּשֵׁם שֶׁנֶּאֱמַר בְּשַׁבַּת בְּרֵאשִׁית (עי' ספרא):\",1,0],[2,128,25,4,\"יהיה לארץ. לַשָּׂדוֹת וְלַכְּרָמִים:\",1,0],[2,128,25,4,\"לא תזמר. שֶׁקּוֹצְצִין זְמוֹרוֹתֶיהָ, וְתַרְגּוּמוֹ לָא תִכְסָח, וְדוֹמֶה לוֹ \\\"קוֹצִים כְּסוּחִים\\\" (ישעיהו ל\\\"ג), \\\"שְֹרֻפָה בָאֵשׁ כְּסוּחָה\\\" (תהילים פ'):\",2,0],[2,128,25,5,\"את ספיח קצירך. אֲפִלּוּ לֹא זְרַעְתָּהּ וְהִיא צָמְחָה מִן הַזֶּרַע שֶׁנָּפַל בָּהּ בְּעֵת הַקָּצִיר וְהוּא קָרוּי סָפִיחַ:\",1,0],[2,128,25,5,\"לא תקצור. לִהְיוֹת מַחֲזִיק בּוֹ כִּשְׁאָר קָצִיר, אֶלָּא הֶפְקֵר יִהְיֶה לַכֹּל:\",2,0],[2,128,25,5,\"נזירך. שֶׁהִנְזַרְתָּ וְהִפְרַשְׁתָּ בְנֵי אָדָם מֵהֶם וְלֹא הִפְקַרְתָּם:\",3,0],[2,128,25,5,\"לא תבצר. אוֹתָם אֵינְךָ בוֹצֵר, אֶלָּא מִן הַמֻּפְקָר:\",4,0],[2,128,25,6,\"והיתה שבת הארץ וגו'. אַעַ\\\"פִּ שֶׁאֲסַרְתִּים עָלֶיךָ, לֹא בַאֲכִילָה וְלֹא בַּהֲנָאָה אֲסַרְתִּים, אֶלָּא שֶׁלֹּא תִנְהֹג בָהֶם כְּבַעַל הַבַּיִת, אֶלָּא הַכֹּל יִהְיוּ שָׁוִים בָּהּ, אַתָּה וּשְׂכִירְךָ וְתוֹשָׁבְךָ:\",1,0],[2,128,25,6,\"שבת הארץ לכם לאכלה. מִן הַשָּׁבוּת אַתָּה אוֹכֵל, וְאִי אַתָּה אוֹכֵל מִן הַשָּׁמוּר (ספרא):\",2,0],[2,128,25,6,\"לך ולעבדך ולאמתך. לְפִי שֶׁנֶאֱמַר וְאָכְלוּ אֶבְיֹנֵי עַמֶּךָ (שמות כ\\\"ג), יָכוֹל יִהְיוּ אֲסוּרִים בַּאֲכִילָה לָעֲשִׁירִים, תַּ\\\"לֹ לְךָ וּלְעַבְדְּךָ וְלַאֲמָתֶךָ, הֲרֵי בְעָלִים וַעֲבָדִים וּשְׁפָחוֹת אֲמוּרִים כָּאן (ספרא):\",3,0],[2,128,25,6,\"ולשכירך ולתושבך. אַף הַגּוֹיִם (שם):\",4,0],[2,128,25,7,\"ולבהמתך ולחיה. אִם חַיָּה אוֹכֶלֶת, בְּהֵמָה לֹא כָּל שֶׁכֵּן, שֶׁמְּזוֹנוֹתֶיהָ עָלֶיךָ, מַה תַּ\\\"לֹ וְלִבְהֶמְתְּךָ? מַקִּישׁ בְּהֵמָה לַחַיָּה, כָּל זְמַן שֶׁחַיָּה אוֹכֶלֶת מִן הַשָּׂדֶה, הַאֲכֵל לִבְהֶמְתְּךָ מִן הַבַּיִת, כָּלָה לַחַיָּה מִן הַשָּׂדֶה, כַּלֵּה לִבְהֶמְתְּךָ מִן הַבַּיִת (שם; תענית ו'):\",1,0],[2,128,25,8,\"שבתת שנים. שְׁמִטּוֹת שָׁנִים, יָכוֹל יַעֲשֶׂה שֶׁבַע שָׁנִים רְצוּפוֹת שְׁמִטָּה וְיַעֲשֶׂה יוֹבֵל אַחֲרֵיהֶם, תַּ\\\"לֹ שֶׁבַע שָׁנִים שֶׁבַע פְּעָמִים, הֱוֵי אוֹמֵר כָּל שְׁמִטָּה וּשְׁמִטָּה בִּזְמַנָּהּ (ספרא):\",1,0],[2,128,25,8,\"והיו לך ימי שבע וגו'. מַגִּיד לְךָ, שֶׁאַעַ\\\"פִּ שֶׁלֹּא עָשִׂיתָ שְׁמִטּוֹת, עֲשֵׂה יוֹבֵל לְסוֹף מ\\\"ט שָׁנָה; וּפְשׁוּטוֹ שֶׁל מִקְרָא: יַעֲלֶה לְךָ חֶשְׁבּוֹן שְׁנוֹת הַשְּׁמִטּוֹת לְמִסְפַּר מ\\\"ט:\",2,0],[2,128,25,9,\"והעברת. לְשׁוֹן \\\"וַיַּעֲבִירוּ קוֹל בַּמַּחֲנֶה\\\" (שמות ל\\\"ו), לְשׁוֹן הַכְרָזָה (ראש השנה ל\\\"ד):\",1,0],[2,128,25,9,\"ביום הכפרים. מִמַּשְׁמָע שֶׁנֶּאֱמַר בְּיוֹם הַכִּפּוּרִים, אֵינִי יוֹדֵעַ שֶׁהוּא בֶּעָשׂוֹר לַחֹדֶשׁ? אִם כֵּן לָמָּה נֶאֱמַר בעשור לחדש? אֶלָּא לוֹמַר לְךָ, תְּקִיעַה בֶּעָשׂוֹר לַחֹדֶשׁ דּוֹחָה שַׁבָּת בְּכָל אַרְצְכֶם, וְאֵין תְּקִיעַת רֹאשׁ הַשָּׁנָה דּוֹחָה שַׁבָּת בְּכָל אַרְצְכֶם אֶלָּא בְּבֵית דִּין בִּלְבָד (ספרא):\",2,0],[2,128,25,10,\"וקדשתם. בִּכְנִיסָתָהּ מְקַדְּשִׁין אוֹתָהּ בְּבֵית דִּין, וְאוֹמְרִים מְקֻדֶּשֶׁת הַשָּׁנָה (ראש השנה כ\\\"ד):\",1,0],[2,128,25,10,\"וקראתם דרור. לָעֲבָדִים, בֵּין נִרְצַע בֵּין שֶׁלֹּא כָלוּ לוֹ שֵׁשׁ שָׁנִים מִשֶּׁנִּמְכַּר: אָמַר רַבִּי יְהוּדָה מַהוּ לְשׁוֹן דְּרוֹר? כִּמְדַיַּר בֵּי דַיְרָא וְכוּ' — שֶׁדָּר בְּכָל מָקוֹם שֶׁהוּא רוֹצֶה וְאֵינוֹ בִרְשׁוּת אֲחֵרִים (ספרא; ראש השנה ט'):\",2,0],[2,128,25,10,\"יובל הוא. שָׁנָה זֹאת מֻבְדֶּלֶת מִשְּׁאָר שָׁנִים בִּנְקִיבַת שֵׁם לָהּ לְבַדָּהּ, וּמַה שְּׁמָהּ? יוֹבֵל שְׁמָהּ, עַל שֵׁם תְּקִיעַת שׁוֹפָר:\",3,0],[2,128,25,10,\"ושבתם איש אל אחזתו. שֶׁהַשָּׂדוֹת חוֹזְרוֹת לְבַעְלֵיהֶן:\",4,0],[2,128,25,10,\"ואיש אל משפחתו תשבו. לְרַבּוֹת אֶת הַנִּרְצָע (קידושין ט\\\"ו):\",5,0],[2,128,25,11,\"יובל הוא שנת החמשים שנה. מַה תַּ\\\"לֹ? לְפִי שֶׁנֶּאֱמַר וְקִדַּשְׁתֶּם וְגוֹ' כִּדְאִיתָא בְּרֹאשׁ הַשָּׁנָה (דף ח') וּבְתֹ\\\"כֹּ:\",1,0],[2,128,25,11,\"את נזריה. אֶת הָעֲנָבִים הַמְשֻׁמָּרִים, אֲבָל בּוֹצֵר אַתָּה מִן הַמֻּפְקָרִים; כְּשֵׁם שֶׁנֶּאֱמַר בַּשְּׁבִיעִית כָּךְ נֶאֱמַר בַּיּוֹבֵל, נִמְצְאוּ שְׁתֵּי שָׁנִים קְדוֹשׁוֹת סְמוּכוֹת זוֹ לָזוֹ — שְׁנַת מ\\\"ט שְׁמִטָּה, וּשְׁנַת הַחֲמִשִּׁים יוֹבֵל:\",2,0],[2,128,25,12,\"קדש תהיה לכם. תּוֹפֶסֶת דָּמֶיהָ כְּהֶקְדֵּשׁ, יָכוֹל תֵּצֵא הִיא לְחֻלִּין, תַּ\\\"לֹ תהיה — בַּהֲוָיָתָהּ תְּהֵא (ספרא; סוכה מ'):\",1,0],[2,128,25,12,\"מן השדה תאכלו. עַ\\\"יְ הַשָּׂדֶה אַתָּה אוֹכֵל מִן הַבַּיִת, שֶׁאִם כָּלָה לַחַיָּה מִן הַשָּׂדֶה, אַתָּה צָרִיךְ לְבַעֵר מִן הַבַּיִת; כְּשֵׁם שֶׁנֶּאֱמַר בַּשְּׁבִיעִית כָּךְ נֶאֱמַר בַּיּוֹבֵל (ספרא):\",2,0],[2,128,25,13,\"תשבו איש אל אחזתו. וַהֲרֵי כְבָר נֶאֱמַר וְשַׁבְתֶּם אִישׁ אֶל אֲחֻזָּתוֹ? אֶלָּא לְרַבּוֹת הַמּוֹכֵר שָׂדֵהוּ וְעָמַד בְּנוֹ וּגְאָלָהּ שֶׁחוֹזֶרֶת לְאָבִיו בַּיּוֹבֵל (שם):\",1,0],[2,128,25,14,\"וכי תמכרו וגו'. לְפִי פְשׁוּטוֹ כְמַשְׁמָעוֹ; וְעוֹד יֵשׁ דְּרָשָׁה: מִנַּיִן כְּשֶׁאַתָּה מוֹכֵר, מְכֹר לְיִשְׂרָאֵל חֲבֵרְךָ? תַּ\\\"לֹ וְכִי תִמְכְּרוּ מִמְכָּר — לַעֲמִיתְךָ מְכֹר, וּמִנַּיִן שֶׁאִם בָּאתָ לִקְנוֹת קְנֵה מִיִּשְׂרָאֵל חֲבֵרְךָ? תַּ\\\"לֹ אוֹ קָנֹה — מִיַּד עֲמִיתֶךָ (ספרא):\",1,0],[2,128,25,14,\"אל תונו. זוֹ אוֹנָאַת מָמוֹן (בבא מציעא נ\\\"ח):\",2,0],[2,128,25,15,\"במספר שנים אחר היובל תקנה. זֶהוּ פְשׁוּטוֹ לְיַשֵּׁב הַמִּקְרָא עַל אָפְנָיו: עַל הָאוֹנָאָה בָּא לְהַזְהִיר, כְּשֶׁתִּמְכֹּר אוֹ תִקְנֶה קַרְקַע, דְּעוּ כַּמָּה שָׁנִים יֵשׁ עַד הַיּוֹבֵל, וּלְפִי הַשָּׁנִים וּתְבוּאוֹת הַשָּׂדֶה שֶׁהִיא רְאוּיָה לַעֲשׂוֹת יִמְכֹּר הַמּוֹכֵר וְיִקְנֶה הַקּוֹנֶה, שֶׁהֲרֵי סוֹפוֹ לְהַחֲזִירָהּ לוֹ בִּשְׁנַת הַיּוֹבֵל, אִם יֵשׁ שָׁנִים מֻעָטוֹת וְזֶה מוֹכְרָהּ בְּדָמִים יְקָרִים, הֲרֵי נִתְאַנָּה לוֹקֵחַ, וְאִם יֵשׁ שָׁנִים מְרֻבּוֹת וְאָכַל מִמֶּנָּה תְּבוּאוֹת הַרְבֵּה, הֲרֵי נִתְאַנָּה מוֹכֵר, לְפִיכָךְ צָרִיךְ לִקְנוֹתָהּ לְפִי הַזְּמַן, וְזֶהוּ שֶׁנֶּאֱמַר בְּמִסְפַּר שְׁנֵי תְבוּאֹת יִמְכָּר לָךְ — לְפִי מִנְיַן שְׁנֵי הַתְּבוּאוֹת שֶׁתְּהֵא עוֹמֶדֶת בְּיַד הַלּוֹקֵחַ תִּמְכֹּר לוֹ. וְרַבּוֹתֵינוּ דָרְשׁוּ מִכָּאן שֶׁהַמּוֹכֵר שָׂדֵהוּ אֵינוֹ רַשַּׁאי לִגְאֹל פָּחוֹת מִשְׁתֵּי שָׁנִים — שֶׁתַּעֲמֹד שְׁתֵּי שָׁנִים בְּיַד הַלּוֹקֵחַ מִיּוֹם לְיוֹם, וַאֲפִלּוּ יֵשׁ שָׁלוֹשׁ תְּבוּאוֹת בְּאוֹתָן שְׁתֵּי שָׁנִים, כְּגוֹן שֶׁמְּכָרָהּ לוֹ בְּקָמוֹתֶיהָ; וּשְׁנֵי אֵינוֹ יוֹצֵא מִפְּשׁוּטוֹ — כְּלוֹמַר מִסְפַּר שָׁנִים שֶׁל תְּבוּאוֹת וְלֹא שֶׁל שִׁדָּפוֹן, וּמִעוּט שָׁנִים שְׁנַיִם (ספרא; ערכין כ\\\"ט):\",1,0],[2,128,25,16,\"תרבה מקנתו. תִּמְכְּרֶנָּה בְיֹקֶר:\",1,0],[2,128,25,16,\"תמעיט מקנתו. תַּמְעִיט בְּדָמֶיהָ:\",2,0],[2,128,25,17,\"ולא תונו איש את עמיתו. כָּאן הִזְהִיר עַל אוֹנָאַת דְּבָרִים, שֶׁלֹּא יַקְנִיט אֶת חֲבֵרוֹ וְלֹא יַשִּׂיאֶנּוּ עֵצָה שֶׁאֵינָהּ הוֹגֶנֶת לוֹ, לְפִי דַּרְכּוֹ וַהֲנָאָתוֹ שֶׁל יוֹעֵץ, וְאִ\\\"תֹּ מִי יוֹדֵעַ אִם נִתְכַּוַּנְתִּי לְרָעָה? לְכָךְ נֶאֱמַר וְיָרֵאתָ מֵּאֱלֹהֶיךָ — הַיּוֹדֵעַ מַחֲשָׁבוֹת הוּא יוֹדֵעַ. כָּל דָּבָר הַמָּסוּר לַלֵּב, שֶׁאֵין מַכִּיר אֶלָּא מִי שֶׁהַמַּחֲשָׁבָה בְלִבּוֹ, נֶאֱמַר בּוֹ וְיָרֵאתָ מֵּאֱלֹהֶיךָ (ספרא; בבא מציעא נ\\\"ח):\",1,0],[2,128,25,18,\"וישבתם על הארץ לבטח. שֶׁבַּעֲוֹן שְׁמִטָּה יִשְׂרָאֵל גּוֹלִים, שֶׁנֶּאֱמַר \\\"אָז תִּרְצֶה הָאָרֶץ אֶת שַׁבְּתֹתֶיהָ, וְהִרְצָת אֶת שַׁבְּתֹתֶיהָ\\\" (ויקרא כ\\\"ו), וְשִׁבְעִים שָׁנָה שֶׁל גָּלוּת בָּבֶל כְּנֶגֶד שִׁבְעִים שְׁמִטּוֹת שֶׁבִּטְּלוּ הָיוּ:\",1,0],[2,128,25,19,\"ונתנה הארץ וגו', וישבתם לבטח עליה. שֶׁלֹּא תִדְאֲגוּ מִשְּׁנַת בַּצֹּרֶת:\",1,0],[2,128,25,19,\"ואכלתם לשבע. אַף בְּתוֹךְ הַמֵּעַיִם תְּהֵא בוֹ בְּרָכָה (עי' ספרא):\",2,0],[2,128,25,20,\"ולא נאסף. אֶל הַבַּיִת:\",1,0],[2,128,25,20,\"את תבואתנו. כְּגוֹן יַיִן וּפֵרוֹת הָאִילָן וּסְפִיחִין הַבָּאִים מֵאֵלֵיהֶם:\",2,0],[2,128,25,21,\"לשלש השנים. לִקְצָת הַשִּׁשִּׁית — מִנִּיסָן וְעַד רֹ\\\"הַ, וְלַשְּׁבִיעִית, וְלַשְּׁמִינִית, שֶׁיִּזְרְעוּ בַשְּׁמִינִית בְּמַרְחֶשְׁוָן וְיִקְצְרוּ בְנִיסָן:\",1,0],[2,128,25,22,\"עד השנה התשיעת. עַד חַג הַסֻּכּוֹת שֶׁל תְּשִׁיעִית, שֶׁהוּא עֵת בֹּא תְּבוּאָתָהּ שֶׁל שְׁמִינִית לְתוֹךְ הַבַּיִת, שֶׁכָּל יְמוֹת הַקַּיִץ הָיוּ בַשָּׂדֶה בַּגְּרָנוֹת, וּבְתִשְׁרֵי הוּא עֵת הָאָסִיף לַבַּיִת; וּפְעָמִים שֶׁהָיְתָה צְרִיכָה לַעֲשׂוֹת לְאַרְבַּע שָׁנִים — בַּשִּׁשִּׁית שֶׁלִּפְנֵי הַשְּׁמִטָּה הַשְּׁבִיעִית, שֶׁהֵן בְּטֵלִין מֵעֲבוֹדַת קַרְקַע שְׁתֵּי שָׁנִים רְצוּפוֹת — הַשְּׁבִיעִית וְהַיּוֹבֵל, וּמִקְרָא זֶה נֶאֱמַר בִּשְׁאָר הַשְּׁמִטּוֹת כֻּלָּן:\",1,0],[2,128,25,23,\"והארץ לא תמכר. לִתֵּן לָאו עַל חֲזָרַת שָׂדוֹת לַבְּעָלִים בַּיּוֹבֵל, שֶׁלֹּא יְהֵא הַלּוֹקֵחַ כּוֹבְשָׁהּ:\",1,0],[2,128,25,23,\"לצמתת. לִפְסִיקָה, לִמְכִירָה פְסוּקָה עוֹלָמִית:\",2,0],[2,128,25,23,\"כי לי הארץ. אַל תֵּרַע עֵינְךָ בָהּ שֶׁאֵינָהּ שֶׁלְּךָ (ספרא):\",3,0],[2,128,25,24,\"ובכל ארץ אחזתכם. לְרַבּוֹת בָּתִּים וְעֶבֶד עִבְרִי, וְדָבָר זֶה מְפֹרָשׁ בְּקִדּוּשִׁין בְּפֶרֶק רִאשׁוֹן (דף כ\\\"א). וּלְפִי פְשׁוּטוֹ סָמוּךְ לְפָרָשָׁה שֶׁלְּאַחֲרָיו, שֶׁהַמּוֹכֵר אֲחֻזָּתוֹ רַשָּׁאִי לְגָאֳלָהּ לְאַחַר שְׁתֵּי שָׁנִים, אוֹ הוּא אוֹ קְרוֹבוֹ, וְאֵין הַלּוֹקֵחַ יָכוֹל לְעַכֵּב:\",1,0],[2,128,25,25,\"כי ימוך אחיך ומכר. מְלַמֵּד שֶׁאֵין אָדָם רַשַּׁאי לִמְכֹּר שָׂדֵהוּ אֶלָּא מֵחֲמַת דֹּחַק עֹנִי (עי' ספרא):\",1,0],[2,128,25,25,\"מאחזתו. וְלֹא כֻּלָּהּ, לִמֵּד דֶּרֶךְ אֶרֶץ, שֶׁיְּשַׁיֵּר שָׂדֶה לְעַצְמוֹ:\",2,0],[2,128,25,25,\"וגאל את ממכר אחיו. וְאֵין הַלּוֹקֵחַ יָכוֹל לְעַכֵּב:\",3,0],[2,128,25,26,\"ואיש כי לא יהיה לו גאל. וְכִי יֵשׁ לְךָ אָדָם בְּיִשְֹרָאֵל שֶׁאֵין לוֹ גּוֹאֲלִים? אֶלָּא גּוֹאֵל שֶׁיּוּכַל לִגְאֹל מִמְכָּרוֹ (קידושין כ\\\"א):\",1,0],[2,128,25,27,\"וחשב את שני ממכרו. \\\"כַּמָּה שָׁנִים הָיוּ עַד הַיּוֹבֵל? כָּךְ וְכָךְ, וּבְכַמָּה מְכַרְתִּיהָ לְךָ? בְּכָךְ וְכָךְ, עָתִיד הָיִיתָ לְהַחֲזִירָהּ בַּיּוֹבֵל, נִמְצֵאתָ קוֹנֶה מִסְפַּר הַתְּבוּאוֹת כְּפִי חֶשְׁבּוֹן שֶׁל כָּל שָׁנָה, אָכַלְתָּ אוֹתָהּ שָׁלוֹשׁ שָׁנִים אוֹ אַרְבַּע, הוֹצֵא אֶת דְּמֵיהֶן מִן הַחֶשְׁבוֹן וְטֹל אֶת הַשְּׁאָר\\\"; וְזֶהוּ וְהֵשִׁיב אֶת הָעֹדֵף בִּדְמֵי הַמֶּקַח עַל הָאֲכִילָה שֶׁאֲכָלָהּ וְיִתְּנֵם לַלּוֹקֵחַ:\",1,0],[2,128,25,27,\"לאיש אשר מכר לו. הַמּוֹכֵר הַזֶּה שֶׁבָּא לְגָאֳלָהּ:\",2,0],[2,128,25,28,\"די השיב לו. מִכָּאן שֶׁאֵינוֹ גוֹאֵל לַחֲצָאִין (ספרא; ערכין ל'):\",1,0],[2,128,25,28,\"עד שנת היובל. שֶׁלֹּא יִכָּנֵס לְתוֹךְ אוֹתָהּ שָׁנָה כְּלוּם, שֶׁהַיּוֹבֵל מְשַׁמֵּט בִּתְחִלָּתוֹ (ספרא; ערכין כ\\\"ח):\",2,0],[2,128,25,29,\"בית מושב עיר חומה. בַּיִת בְּתוֹךְ עִיר הַמֻּקֶּפֶת חוֹמָה מִימוֹת יְהוֹשֻׁעַ בִּן נוּן (ספרא):\",1,0],[2,128,25,29,\"והיתה גאלתו. לְפִי שֶׁנֶּאֱמַר בְּשָׂדֶה שֶׁיָּכוֹל לְגָאֳלָהּ מִשְּׁתֵי שָׁנִים וָאֵילָךְ כָּל זְמַן שֶׁיִּרְצֶה, וּבְתוֹךְ שְׁתֵּי שָׁנִים הָרִאשׁוֹנִים אֵינוֹ יָכוֹל לְגָאֳלָהּ, הֻצְרַךְ לְפָרֵט בָּזֶה שֶׁהוּא חִלּוּף — שֶׁאִם רָצָה לִגְאֹל בְּשָׁנָה רִאשׁוֹנָה גּוֹאֲלָהּ, וּלְאַחַר מִכָּאן אֵינוֹ גוֹאֲלָהּ:\",2,0],[2,128,25,29,\"והיתה גאלתו. שֶׁל בַּיִת:\",3,0],[2,128,25,29,\"ימים. יְמֵי שָׁנָה שְׁלֵמָה קְרוּיִים יָמִים, וְכֵן \\\"תֵּשֵׁב הַנַּעֲרָה אִתָּנוּ יָמִים\\\" (בראשית כ\\\"ד):\",4,0],[2,128,25,30,\"וקם הבית … צמיתת. יָצָא מִכֹּחוֹ שֶׁל מוֹכֵר וְעוֹמֵד בְּכֹחוֹ שֶׁל קוֹנֶה:\",1,0],[2,128,25,30,\"אשר לא חמה. \\\"לוֹ\\\" קָרֵינָן, אָמְרוּ רַבּוֹתֵינוּ זִ\\\"לִ אַעַ\\\"פִּ שֶׁאֵין לוֹ עַכְשָׁיו הוֹאִיל וְהָיְתָה לוֹ קֹדֶם לָכֵן; וְעִיר נְקֵבָה הִיא, וְהֻצְרַךְ לִכְתֹּב \\\"לָהּ\\\", אֶלָּא מִתּוֹךְ שֶׁצָּרִיךְ לִכְתֹּב \\\"לֹא\\\" בִּפְנִים, תִּקְּנוּ \\\"לוֹ\\\" בַּמָּסֹרֶת — זֶה נוֹפֵל עַל זֶה:\",2,0],[2,128,25,30,\"לא יצא ביבל. אָמַר רַב סַפְרָא אִם פָּגַע בּוֹ יוֹבֵל בְּתוֹךְ שְׁנָתוֹ לֹא יֵצֵא (עי' ערכין ל\\\"א):\",3,0],[2,128,25,31,\"ובתי החצרים. כְּתַרְגּוּמוֹ \\\"פַּצְחִין\\\" — עֲיָרוֹת פְּתוּחוֹת מֵאֵין חוֹמָה, וְיֵשׁ הַרְבֵּה בְּסֵפֶר יְהוֹשֻׁעַ, \\\"הֶעָרִים וְחַצְרֵיהֶם\\\" (יהושע י\\\"ג), \\\"בְּחַצְרֵיהֶם וּבְטִירֹתָם\\\" (בראשית כ\\\"ה):\",1,0],[2,128,25,31,\"על שדה הארץ יחשב. הֲרֵי הֵן כְּשָׂדוֹת, הַנִּגְאָלִים עַד הַיּוֹבֵל וְיוֹצְאִין בַּיּוֹבֵל לַבְּעָלִים אִם לֹא נִגְאֲלוּ:\",2,0],[2,128,25,31,\"גאלה תהיה לו. מִיָּד, אִם יִרְצֶה, וּבָזֶה יָפֶה כֹחוֹ מִכֹּחַ שָׂדוֹת, שֶׁהַשָּׂדוֹת אֵין נִגְאֲלוֹת עַד שְׁתֵּי שָׁנִים (ערכין ל\\\"ג):\",3,0],[2,128,25,31,\"וביבל יצא. בְּחִנָּם:\",4,0],[2,128,25,32,\"וערי הלוים. אַרְבָּעִים וּשְׁמוֹנֶה עִיר שֶׁנִתְּנוּ לָהֶם:\",1,0],[2,128,25,32,\"גאלת עולם. גּוֹאֵל מִיָּד, אֲפִלּוּ לִפְנֵי שְׁתֵּי שָׁנִים, אִם מָכְרוּ שָׂדֶה מִשְּׂדוֹתֵיהֶם הַנְּתוּנוֹת לָהֶם בְּאַלְפַּיִם אַמָּה סְבִיבוֹת הֶעָרִים, אוֹ אִם מָכְרוּ בַיִת בְּעִיר חוֹמָה, גּוֹאֲלִין לְעוֹלָם וְאֵינוֹ חָלוּט לְסוֹף שָׁנָה (שם):\",2,0],[2,128,25,33,\"ואשר יגאל מן הלוים. וְאִם יִקְנֶה בַיִת אוֹ עִיר מֵהֶם וְיֵצֵא בַיּוֹבֵל אוֹתוֹ מִמְכָּר שֶׁל בַּיִת אוֹ שֶׁל עִיר וְיָשׁוּב לַלֵּוִי שֶׁמְּכָרוֹ, וְלֹא יִהְיֶה חָלוּט כִּשְׁאָר בָּתֵּי עָרֵי חוֹמָה שֶׁל יִשְׂרָאֵל, וּגְאֻלָּה זוֹ לְשׁוֹן מְכִירָה; דָּ\\\"אַ, לְפִי שֶׁנֶּאֱמַר גְּאֻלַּת עוֹלָם תִּהְיֶה לַלְוִיִּם, יָכוֹל לֹא דִּבֵּר הַכָּתוּב אֶלָּא בְּלוֹקֵחַ יִשְׂרָאֵל שֶׁקָּנָה בַיִת בְּעָרֵי הַלְוִיִּם, אֲבָל לֵוִי שֶׁקָּנָה מִלֵּוִי, יִהְיֶה חָלוּט, תַּ\\\"לֹ וַאֲשֶׁר יִגְאַל מִן הַלְוִיִּם — אַף הַגּוֹאֵל מִיַּד לֵוִי גּוֹאֵל גְּאֻלַּת עוֹלָם:\",1,0],[2,128,25,33,\"ויצא ממכר בית. הֲרֵי זוֹ מִצְוָה אַחֶרֶת, וְאִם לֹא גְאָלָהּ, יוֹצְאָה בַיּוֹבֵל וְאֵינוֹ נֶחְלָט לְסוֹף שָׁנָה כְּבַיִת שֶׁל יִשְֹרָאֵל:\",2,0],[2,128,25,33,\"כי בתי ערי הלוים הוא אחזתם. לֹא הָיָה לָהֶם נַחֲלַת שָׂדוֹת וּכְרָמִים, אֶלָּא עָרִים לָשֶׁבֶת וּמִגְרְשֵׁיהֶם, לְפִיכָךְ הֵם לָהֶם בִּמְקוֹם שָׂדוֹת, וְיֵשׁ לָהֶם גְּאֻלָּה כְשָׂדוֹת, כְּדֵי שֶׁלֹּא תֻּפְקַע נַחֲלָתָם מֵהֶם:\",3,0],[2,128,25,34,\"ושדה מגרש עריהם לא ימכר. מֶכֶר גִּזְבָּר, שֶׁאִם הִקְדִּישׁ בֶּן לֵוִי אֶת שָׂדֵהוּ וְלֹא גְאָלָהּ וּמְכָרָהּ גִּזְבָּר, אֵינָהּ יוֹצְאָה לַכֹּהֲנִים בַּיּוֹבֵל כְּמוֹ שֶׁנֶּאֱמַר בְּיִשְׂרָאֵל וְאִם מָכַר אֶת הַשָּׂדֶה לְאִישׁ אַחֵר לֹא יִגָּאֵל עוֹד (ויקרא כ\\\"ז), אֲבָל בֶּן לֵוִי גּוֹאֵל לְעוֹלָם:\",1,0],[2,128,25,35,\"והחזקת בו. אַל תַּנִּיחֵהוּ שֶׁיֵּרֵד וְיִפֹּל וְיִהְיֶה קָשֶׁה לַהֲקִימוֹ, אֶלָּא חַזְּקֵהוּ מִשְּׁעַת מוֹטַת הַיָּד; לְמָה זֶה דוֹמֶה? לְמַשּׂאוֹי שֶׁעַל הַחֲמוֹר, עוֹדֵהוּ עַל הַחֲמוֹר אֶחָד תּוֹפֵס בּוֹ וּמַעֲמִידוֹ, נָפַל לָאָרֶץ, חֲמִשָּׁה אֵין מַעֲמִידִין אוֹתוֹ:\",1,0],[2,128,25,35,\"גר ותושב. אַף אִם הוּא גֵּר אוֹ תוֹשָׁב; וְאֵיזֶהוּ תוֹשָׁב? כָּל שֶׁקִּבֵּל עָלָיו שֶׁלֹּא לַעֲבֹד עֲ\\\"זָ וְאוֹכֵל נְבֵלוֹת (עי' ספרא):\",2,0],[2,128,25,36,\"נשך ותרבית. חַד שַׁוִּינְהוּ רַבָּנָן, וְלַעֲבֹר עָלָיו בִּשְׁנֵי לָאוִין (בבא מציעא ס'):\",1,0],[2,128,25,36,\"ויראת מאלהיך. לְפִי שֶׁדַּעְתּוֹ שֶׁל אָדָם נִמְשֶׁכֶת אַחַר הָרִבִּית, וְקָשֶׁה לִפְרֹשׁ הֵימֶנּוּ, וּמוֹרֶה לְעַצְמוֹ הֶתֵּר בִּשְׁבִיל מְעוֹתָיו שֶׁהָיוּ בְטֵלוֹת אֶצְלוֹ, הֻצְרַךְ לוֹמַר וְיָרֵאתָ מֵּאֱלֹהֶיךָ, אוֹ הַתּוֹלֶה מְעוֹתָיו בְּגוֹי כְּדֵי לְהַלְווֹתָם לְיִשְֹרָאֵל בְּרִבִּית, הֲרֵי זֶה דָבָר הַמָּסוּר לְלִבּוֹ שֶׁל אָדָם וּמַחֲשַׁבְתּוֹ, לְכָךְ הֻצְרַךְ לוֹמַר וְיָרֵאתָ מֵּאֱלֹהֶיךָ (שם ס\\\"א):\",2,0],[2,128,25,38,\"אשר הוצאתי וגו'. וְהִבְחַנְתִּי בֵין בְּכוֹר לְשֶׁאֵינוֹ בְכוֹר, אַף אֲנִי יוֹדֵעַ וְנִפְרָע מִן הַמַּלְוֶה מָעוֹת לְיִשְׂרָאֵל בְּרִבִּית וְאוֹמֵר שֶׁל גּוֹי הֵם; דָּ\\\"אַ: אֲשֶׁר הוֹצֵאתִי אֶתְכֶם מֵאֶרֶץ מִצְרַיִם עַל מְנָת שֶׁתְּקַבְּלוּ עֲלֵיכֶם מִצְוֹתַי, וַאֲפִלּוּ הֵן כְּבֵדוֹת עֲלֵיכֶם:\",1,0],[2,128,25,38,\"לתת לכם את ארץ כנען. בִּשְׂכַר שֶׁתְּקַבְּלוּ מִצְוֹתַי:\",2,0],[2,128,25,38,\"להיות לכם לאלהים. שֶׁכָּל הַדָּר בְּאֶרֶץ יִשְׂרָאֵל אֲנִי לוֹ לֵאלֹהִים וְכָל הַיּוֹצֵא מִמֶּנָּה כְּעוֹבֵד עַ\\\"זָ (ספרא; כתובות ק\\\"י):\",3,0],[2,128,25,39,\"עבדת עבד. עֲבוֹדָה שֶׁל גְּנַאי שֶׁיְּהֵא נִכָּר בָּהּ כְּעֶבֶד, שֶׁלֹּא יוֹלִיךְ כֵּלָיו אַחֲרָיו לְבֵית הַמֶּרְחָץ וְלֹא יַנְעִיל לוֹ מִנְעָלָיו (עי' ספרא):\",1,0],[2,128,25,40,\"כשכיר כתושב. עֲבוֹדַת קַרְקַע וּמְלֶאכֶת אֻמָּנוּת כִּשְׁאָר שְׂכִירִים הִתְנַהֵג בּוֹ:\",1,0],[2,128,25,40,\"עד שנת היבל. אִם פָּגַע בּוֹ יוֹבֵל לִפְנֵי שֵׁשׁ שָׁנִים הַיּוֹבֵל מוֹצִיאוֹ:\",2,0],[2,128,25,41,\"הוא ובניו עמו. אָמַר רַ' שִׁמְעוֹן אִם הוּא נִמְכַּר, בָּנָיו מִי מְכָרָן? אֶלָּא מִכָּאן שֶׁרַבּוֹ חַיָּב בִּמְזוֹנוֹת בָּנָיו (קידושין כ\\\"ב):\",1,0],[2,128,25,41,\"ואל אחזת אבתיו. אֶל כְּבוֹד אֲבוֹתָיו, וְאֵין לְזַלְזְלוֹ בְּכָךְ (ספרא; מכילתא י\\\"ג):\",2,0],[2,128,25,41,\"אחזת. חֲזָקַת:\",3,0],[2,128,25,42,\"כי עבדי הם. שְׁטָרִי קוֹדֵם (ספרא):\",1,0],[2,128,25,42,\"לא ימכרו ממכרת עבד. בְּהַכְרָזָה — \\\"כָּאן יֵשׁ עֶבֶד לִמְכֹּר\\\" וְלֹא יַעֲמִידֶנּוּ עַל אֶבֶן הַלֶּקַח (ספרא):\",2,0],[2,128,25,43,\"לא תרדה בו בפרך. מְלָאכָה שֶׁלֹּא לְצֹרֶךְ, כְּדֵי לְעַנּוֹתוֹ, אַל תֹּאמַר לוֹ, הָחֵם לִי אֶת הַכּוֹס הַזֶּה וְהוּא אֵינוֹ צָרִיךְ, עֲדֹר תַּחַת הַגֶּפֶן עַד שֶׁאָבֹא; שֶׁמָּא תֹאמַר אֵין מַכִּיר בַּדָּבָר אִם לְצֹרֶךְ אִם לָאו, וְאוֹמֵר אֲנִי לוֹ שֶׁהוּא לְצֹרֶךְ, הֲרֵי הַדָּבָר הַזֶּה מָסוּר לְלִבּוֹ, לְכָךְ נֶאֱמַר \\\"וְיָרֵאתָ\\\" (שם):\",1,0],[2,128,25,44,\"ועבדך ואמתך אשר יהיו לך. אִם תֹּאמַר אִם כֵּן בְּמָה אֶשְׁתַּמֵּשׁ? בַּעֲבָדַי אֵינִי מוֹשֵׁל, בָּאֻמּוֹת אֵינִי נוֹחֵל, שֶׁהֲרֵי הִזְהַרְתַּנִי לֹא תְחַיֶּה כָּל נְשָׁמָה, אֶלָּא מִי יְשַׁמְּשֵׁנִי?\",1,0],[2,128,25,44,\"מאת הגוים. הֵם יִהְיוּ לְךָ לַעֲבָדִים (שם):\",2,0],[2,128,25,44,\"אשר סביבתיכם. וְלֹא שֶׁבְּתוֹךְ גְּבוּל אַרְצְכֶם, שֶׁהֲרֵי בָהֶם אָמַרְתִּי לֹא תְחַיֶּה כָּל נְשָׁמָה:\",3,0],[2,128,25,45,\"וגם מבני התושבים. שֶׁבָּאוּ מִסְּבִיבוֹתֵיכֶם לִשָּׂא נָשִׁים בְּאַרְצְכֶם, וְיָלְדוּ לָהֶם, הַבֵּן הוֹלֵךְ אַחַר הָאָב, וְאֵינוֹ בִּכְלַל לֹא תְחַיֶּה, אֶלָּא אַתָּה מֻתָּר לִקְנוֹתוֹ כְּעֶבֶד (קידושין כ\\\"ז):\",1,0],[2,128,25,45,\"מהם תקנו. אוֹתָם תִּקְנוּ:\",2,0],[2,128,25,46,\"והתנחלתם אתם לבניכם. הַחֲזִיקוּ בָהֶם לְנַחֲלָה לְצֹרֶךְ בְּנֵיכֶם אַחֲרֵיכֶם; וְלֹא יִתָּכֵן לְפָרֵשׁ הַנְחִילוּם לִבְנֵיכֶם, שֶׁאִם כֵּן הָיָה לוֹ לִכְתֹּב \\\"וְהִנְחַלְתֶּם\\\" אוֹתָם לִבְנֵיכֶם, וְהִתְנַחַלְתֶּם כְּמוֹ וְהִתְחַזַּקְתֶּם:\",1,0],[2,128,25,46,\"איש באחיו. לְהָבִיא נָשִׂיא בְעַמָּיו וּמֶלֶךְ בִּמְשָׁרְתָיו שֶׁלֹּא לִרְדּוֹת בְּפָרֶךְ:\",2,0],[2,128,25,47,\"יד גר ותושב. גֵּר וְהוּא תוֹשָׁב, כְּתַרְגּוּמוֹ עָרֵל תוֹתָב, וְסוֹפוֹ מוֹכִיח — וְנִמְכַּר \\\"לְגֵר תּוֹשָׁב\\\":\",1,0],[2,128,25,47,\"וכי תשיג יד גר ותושב עמך. מִי גָּרַם לוֹ שֶׁיַּעֲשִׁיר? דִּבּוּקוֹ עִמְּךָ.\",2,0],[2,128,25,47,\"ומך אחיך עמו. מִי גָּרַם לוֹ שֶׁיָּמוּךְ? דִּבּוּקוֹ עִמּוֹ, עַל יְדֵי שֶׁלָּמַד מִמַּעֲשָׂיו:\",3,0],[2,128,25,47,\"משפחת גר. זֶה הַגּוֹי, כְּשֶׁהוּא אוֹמֵר לְעֵקֶר, זֶה הַנִּמְכָּר לְעֲ\\\"זַ עַצְמָהּ, לִהְיוֹת לָהּ שַׁמָּשׁ, וְלֹא לֶאֱלֹהוּת אֶלָּא לַחֲטֹב עֵצִים וְלִשְׁאֹב מַיִם (ספרא; בבא קמא קי\\\"ג):\",4,0],[2,128,25,48,\"גאלה תהיה לו. מִיָּד, אַל תַּנִּיחֵהוּ שֶׁיִּטָּמַע:\",1,0],[2,128,25,50,\"עד שנת היבל. שֶׁהֲרֵי כָל עַצְמוֹ לֹא קְנָאוֹ אֶלָּא לְעָבְדוֹ עַד הַיּוֹבֵל, שֶׁהֲרֵי בַיּוֹבֵל יֵצֵא, כְּמוֹ שֶׁנֶּאֱמַר לְמַטָּה וְיָצָא בִּשְׁנַת הַיֹּבֵל; וּבְגוֹי שֶׁתַּחַת יָדְךָ הַכָּתוּב מְדַבֵּר (ספרא; קידושין ט\\\"ז), וְאַעַפִּ\\\"כֵ לֹא תָבֹא עָלָיו בַּעֲקִיפִין מִפְּנֵי חִלּוּל הַשֵּׁם (בבא קמא קי\\\"ג), אֶלָּא כְּשֶׁבָּא לִגָּאֵל, יְדַקְדֵּק בַּחֶשְׁבּוֹן, לְפִי הַמַּגִּיעַ בְּכָל שָׁנָה וְשָׁנָה יְנַכֶּה לוֹ הַגּוֹי מִן דָּמָיו, אִם הָיוּ עֶשְׂרִים שָׁנָה מִשֶּׁנִמְכַּר עַד הַיּוֹבֵל, וּקְנָאוֹ בְּעֶשְׂרִים מָנֶה, נִמְצָא שֶׁקָּנָה הַגּוֹי עֲבוֹדַת שָׁנָה בְּמָנֶה, וְאִם שָׁהָה זֶה אֶצְלוֹ חָמֵשׁ שָׁנִים, וּבָא לִגָּאֵל, יְנַכֶּה לוֹ חֲמִשָּׁה מָנִים, וְיִתֵּן לוֹ הָעֶבֶד ט\\\"ו מָנִים, וְזֶהוּ והיה כסף ממכרו במספר שנים:\",1,0],[2,128,25,50,\"כימי שכיר יהיה עמו — חֶשְׁבּוֹן הַמַּגִּיעַ לְכָל שָׁנָה וְשָׁנָה יַחֲשֹׁב, כְּאִלּוּ נִשְׂכַּר עִמּוֹ כָּל שָׁנָה בְּמָנֶה, וִינַכֶּה לוֹ:\",2,0],[2,128,25,51,\"אם עוד רבות בשנים. עַד הַיּוֹבֵל:\",1,0],[2,128,25,51,\"לפיהן. הַכֹּל כְּמוֹ שֶׁפֵּרַשְׁתִּי:\",2,0],[2,128,25,53,\"לא ירדנו בפרך לעיניך. כְּלוֹמַר וְאַתָּה רוֹאֶה (ספרא):\",1,0],[2,128,25,54,\"ואם לא יגאל באלה. בְּאֵלֶּה הוּא נִגְאָל וְאֵינוֹ נִגְאָל בְּשֵׁשׁ (קידושין ט\\\"ו):\",1,0],[2,128,25,54,\"הוא ובניו עמו. הַגּוֹי חַיָּב בִּמְזוֹנוֹת בָּנָיו:\",2,0],[2,128,25,55,\"כי לי בני ישראל עבדים. שְׁטָרִי קוֹדֵם:\",1,0],[2,128,25,55,\"אני ה' אלהיכם. כָּל הַמְשַׁעְבְּדָן מִלְּמַטָּה כְּאִלּוּ מְשַׁעְבְּדוֹ מִלְמַעְלָה (ספרא):\",2,0],[2,128,26,1,\"לא תעשו לכם אלילים. כְּנֶגֶד זֶה הַנִּמְכָּר לְגוֹי, שֶׁלֹּא יֹאמַר הוֹאִיל וְרַבִּי מְגַלֶּה עֲרָיוֹת, אַף אֲנִי כְּמוֹתוֹ, הוֹאִיל וְרַבִּי עוֹבֵד עָ\\\"זָ, אַף אֲנִי כְּמוֹתוֹ, הוֹאִיל וְרַבִּי מְחַלֵּל שַׁבָּת, אַף אֲנִי כְּמוֹתוֹ, לְכָךְ נֶאֶמְרוּ מִקְרָאוֹת הַלָּלוּ; וְאַף הַפָּרָשִׁיּוֹת הַלָּלוּ נֶאֶמְרוּ עַל הַסֵּדֶר: בַּתְּחִלָּה הִזְהִיר עַל הַשְּׁבִיעִית, וְאִם חָמַד מָמוֹן וְנֶחְשַׁד עַל הַשְּׁבִיעִית, סוֹפוֹ לִמְכֹּר מִטַּלְטְלָיו, לְכָךְ סָמַךְ לָהּ וְכִי תִמְכְּרוּ מִמְכָּר — (מַה כְּתִיב בֵּיהּ? אוֹ קָנֹה מִיַּד עֲמִיתֶךָ — דָּבָר הַנִּקְנֶה מִיָּד לְיָד) — לֹא חָזַר בּוֹ, סוֹף מוֹכֵר אֲחֻזָּתוֹ, לֹא חָזַר בּוֹ, סוֹף מוֹכֵר אֶת בֵּיתוֹ, לֹא חָזַר בּוֹ, סוֹף לֹוֶה בְרִבִּית — כָּל אֵלּוּ הָאַחֲרוֹנוֹת קָשׁוֹת מִן הָרִאשׁוֹנוֹת — לֹא חָזַר בּוֹ, סוֹף מוֹכֵר אֶת עַצְמוֹ, לֹא חָזַר בּוֹ, לֹא דַיּוֹ לְיִשְׂרָאֵל אֶלָּא אֲפִלּוּ לְגוֹי:\",1,0],[2,128,26,1,\"ואבן משכית. לְשׁוֹן כִּסּוּי, כְּמוֹ \\\"וְשַׂכֹּתִי כַפִּי\\\" (שמות ל\\\"ג), שֶׁמְּכַסִּין הַקַּרְקַע בְּרִצְפַּת אֲבָנִים:\",2,0],[2,128,26,1,\"להשתחות עליה. אֲפִלּוּ לַשָּׁמַיִם, לְפִי שֶׁהִשְׁתַּחֲוָאָה בְּפִשּׁוּט יָדַיִם וְרַגְלַיִם הִיא וְאָסְרָה תוֹרָה לַעֲשׂוֹת כֵּן חוּץ מִן הַמִּקְדָּשׁ (מגילה כ\\\"ב):\",3,0],[2,128,26,2,\"אני ה'. נֶאֱמָן לְשַׁלֵּם שָׂכָר:\",1,0],[2,128,26,3,\"אם בחקתי תלכו. יָכוֹל זֶה קִיּוּם הַמִּצְווֹת, כְּשֶׁהוּא אוֹמֵר וְאֶת מִצְוֹתַי תִּשְׁמְרוּ וַעֲשִיתֶם אֹתָם הֲרֵי קִיּוּם הַמִּצְווֹת אָמוּר, הָא מָה אֲנִי מְקַיֵּם אִם בְּחֻקֹּתַי תֵּלֵכוּ? שֶׁתִּהְיוּ עֲמֵלִים בַּתּוֹרָה (ספרא):\",1,0],[2,128,26,3,\"ואת מצותי תשמרו. הֱווּ עֲמֵלִים בַּתּוֹרָה עַל מְנָת לִשְׁמֹר וּלְקַיֵּם, כְּמוֹ שֶׁנֶּאֱמַר \\\"וּלְמַדְתֶּם אֹתָם וּשְׁמַרְתֶּם לַעֲשֹׂתָם\\\" (דברים ה'):\",2,0],[2,128,26,4,\"בעתם. בְּשָׁעָה שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לָצֵאת, כְּגוֹן בְּלֵילֵי שַׁבָּתוֹת (ספרא; תענית כ\\\"ג):\",1,0],[2,128,26,4,\"ועץ השדה. הֵן אִילָנֵי סְרָק, וַעֲתִידִין לַעֲשׂוֹת פֵּרוֹת (ספרא):\",2,0],[2,128,26,5,\"והשיג לכם דיש את בציר. שֶׁיְּהֵא הַדַּיִשׁ מְרֻבֶּה, וְאַתֶּם עֲסוּקִים בּוֹ עַד הַבָּצִיר, וּבַבָּצִיר תַּעַסְקוּ עַד שְׁעַת הַזֶּרַע (ספרא):\",1,0],[2,128,26,5,\"ואכלתם לחמכם לשבע. אוֹכֵל קִמְעָא וְהוּא מִתְבָּרֵךְ בְּמֵעָיו:\",2,0],[2,128,26,6,\"ונתתי שלום. שֶׁמָּא תֹאמְרוּ, הֲרֵי מַאֲכָל וַהֲרֵי מִשְׁתֶּה, אִם אֵין שָׁלוֹם אֵין כְּלוּם, תַּ\\\"לֹ אַחַר כָּל זֹאת \\\"וְנָתַתִּי שָׁלוֹם בָּאָרֶץ\\\"; מִכָּאן שֶׁהַשָּׁלוֹם שָׁקוּל כְּנֶגֶד הַכֹּל, וְכֵן הוּא אוֹמֵר (ישעיה מ\\\"ה) \\\"עוֹשֶׂה שָׁלוֹם וּבוֹרֵא אֶת הַכֹּל\\\":\",1,0],[2,128,26,6,\"וחרב לא תעבר בארצכם. אֵצָ\\\"לֹ שֶׁלֹּא יָבֹאוּ לַמִּלְחָמָה, אֶלָּא אֲפִלּוּ לַעֲבֹר דֶּרֶךְ אַרְצְכֶם מִמְּדִינָה לִמְדִינָה (ספרא):\",2,0],[2,128,26,7,\"לפניכם לחרב. אִישׁ בְּחֶרֶב רֵעֵהוּ (שם):\",1,0],[2,128,26,8,\"ורדפו מכם. מִן הַחַלָּשִׁים שֶׁבָּכֶם וְלֹא מִן הַגִּבּוֹרִים שֶׁבָּכֶם (שם):\",1,0],[2,128,26,8,\"חמשה מאה ומאה מכם רבבה. וְכִי כָךְ הוּא הַחֶשְׁבּוֹן? וַהֲלֹא לֹא הָיָה צָרִיךְ לוֹמַר אֶלָּא מֵאָה מִכֶּם שְׁנֵי אֲלָפִים יִרְדֹּפוּ, אֶלָּא אֵינוֹ דּוֹמֶה מֻעֲטִין הָעוֹשִׂים אֶת הַתּוֹרָה לִמְרֻבִּין הָעוֹשִׂין אֶת הַתּוֹרָה (שם):\",2,0],[2,128,26,8,\"ונפלו איביכם וגו'. שֶׁיִּהְיוּ נוֹפְלִין לִפְנֵיכֶם שֶׁלֹּא כְדֶרֶךְ הָאָרֶץ (שם):\",3,0],[2,128,26,9,\"ופניתי אליכם. אֶפְנֶה מִכָּל עֲסָקַי לְשַׁלֵּם שְׂכַרְכֶם. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁשָּׂכַר פּוֹעֲלִים וְכוּ', כִּדְאִיתָא בְּתֹ\\\"כֹּ:\",1,0],[2,128,26,9,\"והפריתי אתכם. בִּפְרִיָּה וּרְבִיָּה:\",2,0],[2,128,26,9,\"והרביתי אתכם. בְּקוֹמָה זְקוּפָה (ספרא):\",3,0],[2,128,26,9,\"והקימתי את בריתי אתכם. בְּרִית חֲדָשָׁה, לֹא כַבְּרִית הָרִאשׁוֹנָה שֶׁהֵפַרְתֶּם אוֹתָהּ אֶלָּא בְּרִית חֲדָשָׁה שֶׁלֹּא תּוּפַר, שֶׁנֶּאֱמַר (ירמיהו ל\\\"א) \\\"וְכָרַתִּי אֶת בֵּית יִשְׂרָאֵל וְאֶת בֵּית יְהוּדָה בְּרִית חֲדָשָׁה לֹא כַבְּרִית וְגוֹ'\\\" (ספרא):\",4,0],[2,128,26,10,\"ואכלתם ישן נושן. הַפֵּרוֹת יִהְיוּ מִשְׁתַּמְרִין וְטוֹבִים לְהִתְיַשֵּׁן, שֶׁיְּהֵא יָשָׁן הַנּוֹשָׁן שֶׁל שָׁלוֹשׁ שָׁנִים יָפֶה לֶאֱכֹל מִשֶּׁל אֶשְׁתָּקַד (בבא בתרא צ\\\"א):\",1,0],[2,128,26,10,\"וישן מפני חדש תוציאו. שֶׁיִּהְיוּ הַגְּרָנוֹת מְלֵאוֹת חָדָשׁ וְהָאוֹצָרוֹת מְלֵאוֹת יָשָׁן, וּצְרִיכִים אַתֶּם לְפַנּוֹת הָאוֹצָרוֹת לְמָקוֹם אַחֵר, לָתֵת הֶחָדָשׁ לְתוֹכָן (שם):\",2,0],[2,128,26,11,\"ונתתי משכני. זֶה בֵּית הַמִּקְדָּשׁ (ספרא: עירובין ב'):\",1,0],[2,128,26,11,\"ולא תגעל נפשי. אֵין רוּחִי קָצָה בָכֶם; כָּל גְּעִילָה לְשׁוֹן פְּלִיטַת דָּבָר הַבָּלוּעַ בְּדָבָר, כְּמוֹ \\\"כִּי שָׁם נִגְעַל מָגֵן גִּבּוֹרִים\\\" (שמואל ב א') — לֹא קִבֵּל הַמְּשִׁיחָה, שֶׁמּוֹשְׁחִין מָגֵן שֶׁל עוֹר בְּחֵלֶב מְבֻשָּׁל כְּדֵי לְהַחֲלִיק מֵעָלָיו מַכַּת חֵץ אוֹ חֲנִית, שֶׁלֹּא יִקֹּב הָעוֹר:\",2,0],[2,128,26,12,\"והתהלכתי בתוככם. אֲטַיֵּל עִמָּכֶם בְּגַן עֵדֶן כְּאֶחָד מִכֶּם, וְלֹא תִהְיוּ מִזְדַּעְזְעִים מִמֶּנִּי, יָכוֹל לֹא תִירְאוּ מִמֶּנִּי, תַּ\\\"לֹ \\\"וְהָיִיתִי לָכֶם לֵאלֹהִים\\\" (ספרא):\",1,0],[2,128,26,13,\"אני ה' אלהיכם. כְּדַאי אֲנִי שֶׁתַּאֲמִינוּ בִי שֶׁאֲנִי יָכוֹל לַעֲשׂוֹת כָּל אֵלֶּה, שֶׁהֲרֵי הוֹצֵאתִי אֶתְכֶם מֵאֶרֶץ מִצְרַיִם וְעָשִׂיתִי לָכֶם נִסִּים גְּדוֹלִים:\",1,0],[2,128,26,13,\"מטת. כְּמִין יָתֵד בִּשְׁנֵי רָאשֵׁי הָעֹל הַמְעַכְּבִים הַמּוֹסֵרָה שֶׁלֹּא תֵצֵא מֵרֹאשׁ הַשּׁוֹר וְיַתִּיר הַקֶּשֶׁר, כְּמוֹ \\\"עֲשֵֹה לְךָ מוֹסֵרוֹת וּמֹטוֹת\\\" (ירמיהו כ\\\"ז), קבילייא בְּלַעַז:\",2,0],[2,128,26,13,\"קוממיות. בְּקוֹמָה זְקוּפָה (ספרא):\",3,0],[2,128,26,14,\"ואם לא תשמעו לי. לִהְיוֹת עֲמֵלִים בַּתּוֹרָה, לָדַעַת מִדְרַשׁ חֲכָמִים. יָכוֹל לְקִיּוּם הַמִּצְווֹת? כְּשֶׁהוּא אוֹמֵר וְלֹא תַעֲשׂוּ וְגוֹ' הֲרֵי קִיּוּם מִצְווֹת אָמוּר, הָא מָה אֲנִי מְקַיֵּם וְאִם לֹא תִשְׁמְעוּ לִי? לִהְיוֹת עֲמֵלִים בַּתּוֹרָה, וּמַה תַּ\\\"לֹ לִי? אֵין לִי אֶלָּא זֶה הַמַּכִּיר אֶת רִבּוֹנוֹ וּמְכַוֵּן לִמְרֹד בּוֹ, וְכֵן בְּנִמְרוֹד \\\"גִּבּוֹר צַיִד לִפְנֵי ה'\\\" (בראשית י'), שֶׁמַּכִּירוֹ וּמִתְכַּוֵּן לִמְרֹד בּוֹ, וְכֵן בְּאַנְשֵׁי סְדוֹם \\\"רָעִים וְחַטָּאִים לַה' מְאֹד\\\" (שם י\\\"ג), מַכִּירִים אֶת רִבּוֹנָם וּמִתְכַּוְּנִים לִמְרֹד בּוֹ (ספרא):\",1,0],[2,128,26,14,\"ולא תעשו. מִשֶּׁלֹּא תִלְמְדוּ לֹא תַעֲשׂוּ, הֲרֵי שְׁתֵּי עֲבֵרוֹת:\",2,0],[2,128,26,15,\"ואם בחקתי תמאסו. מוֹאֵס בַּאֲחֵרִים הָעוֹשִׂים:\",1,0],[2,128,26,15,\"משפטי תגעל נפשכם. שׂוֹנֵא הַחֲכָמִים:\",2,0],[2,128,26,15,\"לבלתי עשות. מוֹנֵעַ אֶת אֲחֵרִים מֵעֲשׂוֹת:\",3,0],[2,128,26,15,\"את כל מצותי. כּוֹפֵר שֶׁלֹּא צִוִּיתִים, לְכָךְ נֶאֱמַר \\\"אֶת כָּל מִצְוֹתַי\\\" וְלֹא נֶאֱמַר \\\"אֶת כָּל הַמִּצְוֹת\\\":\",4,0],[2,128,26,15,\"להפרכם את בריתי. כּוֹפֵר בָּעִקָּר; הֲרֵי שֶׁבַע עֲבֵרוֹת, הָרִאשׁוֹנָה גוֹרֶרֶת הַשְּׁנִיָּה, וְכֵן עַד הַשְּׁבִיעִית, וְאֵלּוּ הֵן: לֹא לָמַד, וְלֹא עָשָׂה, מוֹאֵס בַּאֲחֵרִים הָעוֹשִׂים, שׂוֹנֵא אֶת הַחֲכָמִים, מוֹנֵעַ אֶת הָאֲחֵרִים, כּוֹפֵר בַּמִּצְווֹת, כּוֹפֵר בָּעִקָּר:\",5,0],[2,128,26,16,\"והפקדתי עליכם. וְצִוִּיתִי עֲלֵיכֶם:\",1,0],[2,128,26,16,\"השחפת. חֹלִי שֶׁמְּשַׁחֵף אֶת הַבָּשָׂר, אנפו\\\"ליש בלעז, דּוֹמֶה לְנָפוּחַ שֶׁהוּקַלָּה נְפִיחָתוֹ וּמַרְאִית פָּנָיו זְעוּפָה:\",2,0],[2,128,26,16,\"הקדחת. חֹלִי שֶׁמַּקְדִּיחַ אֶת הַגּוּף וּמְחַמְּמוֹ וּמַבְעִירוֹ, כְּמוֹ \\\"כִּי אֵשׁ קָדְחָה בְאַפִּי\\\" (דברים ל\\\"ב):\",3,0],[2,128,26,16,\"מכלות עינים ומדיבת נפש. הָעֵינַיִם צוֹפוֹת וְכָלוֹת לִרְאוֹת שֶׁיֵּקַל וְיֵרָפֵא, וְסוֹף שֶׁלֹּא יֵרָפֵא, וְיִדְאֲבוּ הַנְּפָשׁוֹת שֶׁל מִשְׁפַּחְתּוֹ בְּמוֹתוֹ; כָּל תַּאֲוָה שֶׁאֵינָהּ בָּאָה וְתוֹחֶלֶת מְמֻשָּׁכָה קְרוּיָה כִלְיוֹן עֵינַיִם:\",4,0],[2,128,26,16,\"וזרעתם לריק. תִּזְרְעוּ וְלֹא תִצְמַח, וְאִם תִּצְמַח ואכלהו איביכם:\",5,0],[2,128,26,17,\"ונתתי פני. פְּנַאי שֶׁלִּי — פּוֹנֶה אֲנִי מִכָּל עֲסָקַי לְהָרַע לָכֶם:\",1,0],[2,128,26,17,\"ורדו בכם שנאיכם. כְּמַשְׁמָעוֹ, יִשְׁלְטוּ בָכֶם: אַגָּדַת תֹּ\\\"כֹּ מִפָּרָשָׁה זוֹ:\",2,0],[2,128,26,17,\"אף אני אעשה זאת. אֵינִי מְדַבֵּר אֶלָּא בְּאַף, וְכֵן \\\"אַף אֲנִי אֵלֵךְ עִמָּכֶם בְּקֶרִי\\\" (פסוק מ\\\"א):\",3,0],[2,128,26,17,\"והפקדתי עליכם. שֶׁיִּהְיוּ הַמַּכּוֹת פּוֹקְדוֹת אֶתְכֶם מִזוֹ לְזוֹ, עַד שֶׁהָרִאשׁוֹנָה פְקוּדָה אֶצְלְכֶם, אָבִיא אַחֶרֶת וְאֶסְמְכֶנָּה לָהּ:\",4,0],[2,128,26,17,\"בהלה. מַכָּה הַמְבַהֶלֶת אֶת הַבְּרִיּוֹת, וְאֵי זוֹ? זוֹ מַכַּת מוֹתָן:\",5,0],[2,128,26,17,\"את השחפת. יֵשׁ לְךָ אָדָם שֶׁהוּא חוֹלֶה וּמֻטָּל בַּמִּטָּה אֲבָל בְּשָׂרוֹ שָׁמוּר עָלָיו, תַּ\\\"לֹ \\\"שַׁחֶפֶת\\\", שֶׁהוּא נִשְׁחָף, אוֹ עִתִּים שֶׁהוּא נִשְׁחָף אֲבָל נֹחַ וְאֵינוֹ מַקְדִּיחַ, תַּ\\\"לֹ \\\"וְאֶת הַקַּדַּחַת\\\", מְלַמֵּד שֶׁהוּא מַקְדִּיחַ, אוֹ עִתִּים שֶׁהוּא מַקְדִּיחַ אֲבָל סָבוּר הוּא בְעַצְמוֹ שֶׁיִּחְיֶה, תַּ\\\"לֹ \\\"מְכַלּוֹת עֵינַיִם\\\", אוֹ הוּא אֵינוֹ סָבוּר בְּעַצְמוֹ שֶׁיִּחְיֶה, אֲבָל אֲחֵרִים סְבוּרִים שֶׁיִּחְיֶה, תַּ\\\"לֹ \\\"וּמְדִיבֹת נָפֶשׁ\\\":\",6,0],[2,128,26,17,\"וזרעתם לריק זרעכם. זוֹרְעָהּ וְאֵינָהּ מַצְמַחַת, וּמֵעַתָּה מָה אוֹיְבֵיכֶם בָּאִים וְאוֹכְלִים? תַּ\\\"לֹ \\\"וַאֲכָלֻהוּ אֹיְבֵיכֶם\\\", הָא כֵיצַד? זוֹרְעָהּ שָׁנָה רִאשׁוֹנָה וְאֵינָהּ מַצְמַחַת, שָׁנָה שְׁנִיָּה מַצְמַחַת, וְאוֹיְבִים בָּאִים וּמוֹצְאִים תְּבוּאָה לִימֵי הַמָּצוֹר, וְשֶׁבִּפְנִים מֵתִים בָּרָעָב, שֶׁלֹּא לִקְּטוּ תְּבוּאָה אֶשְׁתָּקַד; דָּ\\\"אַ: \\\"וּזְרַעְתֶּם לָרִיק זַרְעֲכֶם\\\", כְּנֶגֶד הַבָּנִים וְהַבָּנוֹת הַכָּתוּב מְדַבֵּר, שֶׁאַתָּה עָמֵל בָּהֶם וּמְגַדְּלָן, וְהַחֵטְא בָּא וּמְכַלֶּה אוֹתָם, שֶׁנֶּאֱמַר \\\"אֲשֶׁר טִפַּחְתִּי וְרִבִּיתִי אֹיְבִי כִלָּם\\\" (איכה ב'):\",7,0],[2,128,26,17,\"ונתתי פני בכם. כְּמוֹ שֶׁנֶּאֱמַר בַּטּוֹבָה \\\"וּפָנִיתִי אֲלֵיכֶם\\\", כָּךְ נֶאֱמַר בָּרָעָה \\\"וְנָתַתִּי פָנַי\\\"; מָשְׁלוּ מָשָׁל, לְמֶלֶךְ שֶׁאָמַר לַעֲבָדָיו, פּוֹנֶה אֲנִי מִכָּל עֲסָקַי וְעוֹסֵק אֲנִי עִמָּכֶם לְרָעָה:\",8,0],[2,128,26,17,\"ונגפתם לפני איביכם. שֶׁיְּהֵא הַמָּוֶת הוֹרֵג אֶתְכֶם מִבִּפְנִים, וּבַעֲלֵי דְבָבֵיכוֹן מַקִּיפִין אֶתְכֶם מִבַּחוּץ:\",9,0],[2,128,26,17,\"ורדו בכם שנאיכם. שֶׁאֵינִי מַעֲמִיד שׂוֹנְאִים אֶלָּא מִכֶּם וּבָכֶם, שֶׁבְּשָׁעָה שֶׁאֻמּוֹת הָעוֹלָם עוֹמְדִים עַל יִשְׂרָאֵל, אֵינָם מְבַקְּשִׁים אֶלָּא מַה שֶּׁבַּגָּלוּי, שֶׁנֶאֱמַר \\\"וְהָיָה אִם זָרַע יִשְׂרָאֵל וְעָלָה מִדְיָן וַעֲמָלֵק וּבְנֵי קֶדֶם וְגוֹ' וַיַּחֲנוּ עֲלֵיהֶם וַיַּשְׁחִיתוּ אֶת יְבוּל הָאָרֶץ\\\" (שופטים ו'), אֲבָל בְּשָׁעָה שֶׁאֲעֲמִיד עֲלֵיכֶם מִכֶּם וּבָכֶם, הֵם מְחַפְּשִׂים אַחַר הַמַּטְמוֹנִיּוֹת שֶׁלָּכֶם, וְכֵן הוּא אוֹמֵר \\\"וַאֲשֶׁר אָכְלוּ שְׁאֵר עַמִּי וְעוֹרָם מֵעֲלֵיהֶם הִפְשִׁיטוּ וְגוֹ'\\\" (מיכה ג'):\",10,0],[2,128,26,17,\"ונסתם. מִפְּנֵי אֵימָה:\",11,0],[2,128,26,17,\"ואין רדף אתכם. מִבְּלִי כֹחַ (ספרא):\",12,0],[2,128,26,18,\"ואם עד אלה. וְאִם בְּעוֹד אֵלֶּה לא תשמעו:\",1,0],[2,128,26,18,\"ויספתי. עוֹד יִסּוּרִין אַחֵרִים:\",2,0],[2,128,26,18,\"שבע על חטאתיכם. שֶׁבַע פֻּרְעָנֻיּוֹת עַל שֶׁבַע עֲבֵרוֹת הָאֲמוּרוֹת לְמַעְלָה:\",3,0],[2,128,26,19,\"ושברתי את גאון עזכם. זֶה בֵּית הַמִּקְדָּשׁ, וְכֵן הוּא אוֹמֵר \\\"הִנְנִי מְחַלֵּל אֶת מִקְדָּשִׁי גְּאוֹן עֻזְּכֶם\\\" (יחזקאל כ\\\"ד):\",1,0],[2,128,26,19,\"ונתתי את שמיכם כברזל ואת ארצכם כנחשה. זוֹ קָשָׁה מִשֶּׁל מֹשֶׁה, שֶׁשָּׁם הוּא אוֹמֵר \\\"וְהָיוּ שָׁמֶיךָ אֲשֶׁר עַל רֹאשְׁךָ נְחֹשֶׁת וְגו'\\\" (דברים כ\\\"ח), שֶׁיִּהְיוּ הַשָּׁמַיִם מַזִּיעִין כְּדֶרֶךְ שֶׁהַנְּחֹשֶׁת מַזִּיעָה, וְהָאָרֶץ אֵינָהּ מַזִּיעָה כְּדֶרֶךְ שֶׁאֵין הַבַּרְזֶל מַזִּיעַ, וְהִיא מְשַׁמֶּרֶת פֵּרוֹתֶיהָ, אֲבָל כָּאן הַשָּׁמַיִם לֹא יִהְיוּ מַזִּיעִין כְּדֶרֶךְ שֶׁאֵין הַבַּרְזֶל מַזִּיעַ, וִיהֵא חֹרֶב בָּעוֹלָם, וְהָאָרֶץ תְּהֵא מַזִּיעָה כְּדֶרֶךְ שֶׁהַנְּחֹשֶׁת מַזִּיעָה, וְהִיא מְאַבֶּדֶת פֵּרוֹתֶיהָ (ספרא):\",2,0],[2,128,26,20,\"ותם לריק כחכם. הֲרֵי אָדָם שֶׁלֹּא עָמַל, שֶׁלֹּא חָרַשׁ, שֶׁלֹּא זָרַע, שֶׁלֹּא נִכֵּשׁ, שֶׁלֹּא כִּסֵּחַ, שֶׁלֹּא עָדַר, וּבִשְׁעַת הַקָּצִיר בָּא שִׁדָּפוֹן וּמַלְקֶה אוֹתוֹ, אֵין בְּכָךְ כְּלוּם, אֲבָל אָדָם שֶׁעָמַל וְחָרַשׁ וְזָרַע וְנִכֵּשׁ וְכִסֵּחַ וְעָדַר וּבָא שִׁדָּפוֹן וּמַלְקֶה אוֹתוֹ, הֲרֵי שִׁנָּיו שֶׁל זֶה קֵהוֹת:\",1,0],[2,128,26,20,\"ולא תתן ארצכם את יבולה. אַף מַה שֶּׁאַתָּה מוֹבִיל לָהּ בִּשְׁעַת הַזֶּרַע (ספרא):\",2,0],[2,128,26,20,\"ועץ הארץ. אֲפִלּוּ מִן הָאָרֶץ יְהֵא לָקוּי, שֶׁלֹּא יַחֲנִיט פֵּרוֹתָיו בִּשְׁעַת הַחֲנָטָה (שם):\",3,0],[2,128,26,20,\"לא יתן. מְשַׁמֵּשׁ לְמַעְלָה וּלְמַטָּה, אָעֵץ וְאַפְּרִי:\",4,0],[2,128,26,20,\"לא יתן פריו. כְּשֶׁהוּא מַפְרֶה מַשִּׁיר פֵּרוֹתָיו, הֲרֵי שְׁתֵּי קְלָלוֹת, וְיֵשׁ כָּאן שֶׁבַע פֻּרְעָנֻיּוֹת (ספרא):\",5,0],[2,128,26,21,\"ואם תלכו עמי קרי. רַבּוֹתֵינוּ אָמְרוּ עֲרַאי, בְּמִקְרֶה, שֶׁאֵינוֹ אֶלָּא לִפְרָקִים, כֵּן תֵּלְכוּ עֲרַאי בְּמִצְווֹת; וּמְנַחֵם פֵּרֵשׁ לְשׁוֹן מְנִיעָה, וְכֵן \\\"הֹקַר רַגְלְךָ\\\" (משלי כ\\\"ה), וְכֵן \\\"יְקַר רוּחַ\\\" (שם י\\\"ז), וְקָרוֹב לָשׁוֹן זֶה לְתַרְגּוּמוֹ שֶׁל אֻנְקְלוֹס, לְשׁוֹן קֹשִׁי, שֶׁמַּקְשִׁין לִבָּם לִמָּנַע מֵהִתְקָרֵב אֵלַי:\",1,0],[2,128,26,21,\"שבע כחטאתיכם. שֶׁבַע פֻּרְעָנֻיּוֹת אֲחֵרִים, בְּמִסְפַּר שֶׁבַע כְּחַטֹּאתֵיכֶם (ספרא):\",2,0],[2,128,26,22,\"והשלחתי. לְשׁוֹן גֵּרוּי:\",1,0],[2,128,26,22,\"ושכלה אתכם. אֵין לִי אֶלָּא חַיָּה מְשַׁכֶּלֶת שֶׁדַּרְכָּהּ בְּכָךְ, בְּהֵמָה שֶׁאֵין דַּרְכָּהּ בְּכָךְ מִנַּיִן? תַּ\\\"לֹ \\\"וְשֶׁן בְּהֵמֹת אֲשַׁלַּח בָּם\\\" (דברים ל\\\"ב), הֲרֵי שְׁתַּיִם. וּמִנַּיִן שֶׁתְּהֵא מְמִיתָה בִנְשִׁיכָתָהּ? תַּ\\\"לֹ \\\"עִם חֲמַת זֹחֲלֵי עָפָר\\\" (שם), מָה אֵלּוּ נוֹשְׁכִין וּמְמִיתִין אַף אֵלּוּ נוֹשְׁכִין וּמְמִיתִין, כְּבָר הָיוּ שָׁנִים בְּאֶרֶץ יִשְׂרָאֵל חֲמוֹר נוֹשֵׁךְ וּמֵמִית, עָרוֹד נוֹשֵׁךְ וּמֵמִית:\",2,0],[2,128,26,22,\"ושכלה אתכם. אֵלּוּ הַקְּטַנִּים:\",3,0],[2,128,26,22,\"והכריתה את בהמתכם. מִבַּחוּץ:\",4,0],[2,128,26,22,\"והמעיטה אתכם. מִבִּפְנִים:\",5,0],[2,128,26,22,\"ונשמו דרכיכם. שְׁבִילִים גְּדוֹלִים וּשְׁבִילִים קְטַנִּים; הֲרֵי שֶׁבַע פֻּרְעָנֻיּוֹת: שֵׁן בְּהֵמָה, וְשֵׁן חַיָּה, חֲמַת זוֹחֲלֵי עָפָר, וְשִׁכְּלָה, וְהִכְרִיתָה, וְהִמְעִיטָה, וְנָשַׁמּוּ:\",6,0],[2,128,26,23,\"לא תוסרו לי. לָשׁוּב אֵלַי:\",1,0],[2,128,26,25,\"נקם ברית. יֵשׁ נָקָם שֶׁאֵינוֹ בַּבְּרִית, כְּדֶרֶךְ שְׁאָר נְקָמוֹת, וְזֶהוּ סִמּוּי עֵינָיו שֶׁל צִדְקִיָּהוּ (ספרא). דָּ\\\"אַ: נקם ברית נִקְמַת בְּרִיתִי אֲשֶׁר עֲבַרְתֶּם. כָּל הֲבָאַת חֶרֶב שֶׁבַּמִּקְרָא הִיא מִלְחֶמֶת חֲיָלוֹת אוֹיְבִים:\",1,0],[2,128,26,25,\"ונאספתם. מִן הַחוּץ אֶל תּוֹךְ הֶעָרִים מִפְּנֵי הַמָּצוֹר (שם):\",2,0],[2,128,26,25,\"ושלחתי דבר בתוככם. עַ\\\"יְ הַדֶּבֶר ונתתם ביד הָאוֹיְבִים הַצָּרִים עֲלֵיכֶם, לְפִי שֶׁאֵין מְלִינִים אֶת הַמֵּת בִּירוּשָׁלַיִם, וּכְשֶׁהֵם מוֹצִיאִים אֶת הַמֵּת לְקָבְרוֹ נִתָּנִין בְּיַד אוֹיֵב (שם):\",3,0],[2,128,26,26,\"מטה לחם. לְשׁוֹן מִשְׁעָן, כְּמוֹ מַטֵּה עֹז (ירמיהו מ\\\"ח):\",1,0],[2,128,26,26,\"בשברי לכם מטה לחם. אֶשְׁבֹּר לָכֶם כָּל מִסְעַד אֹכֶל, וְהֵם חִצֵּי רָעָב (יחזקאל ה'):\",2,0],[2,128,26,26,\"ואפו עשר נשים לחמכם בתנור אחד. מֵחֹסֶר עֵצִים (ספרא):\",3,0],[2,128,26,26,\"והשיבו לחמכם במשקל. שֶׁתְּהֵא הַתְּבוּאָה נִרְקֶבֶת וְנַעֲשֵׂית פַּת נְפֹלֶת, וּמִשְׁתַּבֶּרֶת בַּתַּנּוּר, וְהֵן יוֹשְׁבוֹת וְשׁוֹקְלוֹת אֶת הַשְּׁבָרִים לְחַלְּקָם בֵּינֵיהֶם (שם):\",4,0],[2,128,26,26,\"ואכלתם ולא תשבעו. זֶהוּ מְאֵרָה בְּתוֹךְ הַמֵּעַיִם בַּלֶּחֶם, הֲרֵי שֶׁבַע פֻּרְעָנֻיּוֹת: חֶרֶב, מָצוֹר, דֶּבֶר, שֶׁבֶר מַטֵּה לֶחֶם, חֹסֶר עֵצִים, פַּת נְפֹלֶת, מְאֵרָה בַמֵּעַיִם; וְנִתַּתֶּם אֵינָהּ מִן הַמִּנְיָן, הִיא הַחֶרֶב:\",5,0],[2,128,26,30,\"במתיכם. מִגְדָּלִים וּבִירָנִיּוֹת:\",1,0],[2,128,26,30,\"חמניכם. מִין עֲ\\\"זָ שֶׁמַּעֲמִידִין עַל הַגַּגּוֹת, וְעַל שֵׁם שֶׁמַּעֲמִידִין בַּחַמָּה, קְרוּיִין חַמָּנִים (ספרא ויקרא י\\\"ט):\",2,0],[2,128,26,30,\"ונתתי את פגריכם. תְּפוּחֵי רָעָב הָיוּ, וּמוֹצִיאִים יִרְאָתָם מֵחֵיקָם וּמְנַשְּׁקִים אוֹתָם, וּכְרֵיסָן נִבְקַעַת וְנוֹפֵל עָלֶיהָ (ספרא; סנהדרין ס\\\"ג):\",3,0],[2,128,26,30,\"וגעלה נפשי אתכם. זֶה סִלּוּק שְׁכִינָה (ספרא):\",4,0],[2,128,26,31,\"ונתתי את עריכם חרבה. יָכוֹל מֵאָדָם, כְּשֶׁהוּא אוֹמֵר וַהֲשִׁמֹּתִי אֲנִי אֶת הָאָרֶץ הֲרֵי אָדָם אָמוּר, הָא מָה אֲנִי מְקַיֵּם חָרְבָּה? מֵעוֹבֵר וָשָׁב:\",1,0],[2,128,26,31,\"והשמותי את מקדשיכם. יָכוֹל מִן הַקָּרְבָּנוֹת, כְּשֶׁהוּא אוֹמֵר וְלֹא אָרִיחַ הֲרֵי קָרְבָּנוֹת אֲמוּרִים, הָא מָה אֲנִי מְקַיֵּם וַהֲשִׁמּוֹתִי אֶת מִקְדְּשֵׁיכֶם? מִן הַגְּדוּדִיּוֹת — שַׁיָּרוֹת שֶׁל יִשְׂרָאֵל שֶׁהָיוּ מִתְקַדְּשׁוֹת וְנוֹעָדוֹת לָבֹא שָׁם; הֲרֵי שֶׁבַע פֻּרְעָנֻיּוֹת: אֲכִילַת בְּשַׂר בָּנִים וּבָנוֹת וְהַשְׁמָדַת בָּמוֹת הֲרֵי שְׁתַּיִם — כְּרִיתוּת חַמָּנִים אֵין כָּאן פֻּרְעָנוּת, אֶלָּא עַ\\\"יְ הַשְׁמָדַת הַבִּירָנִיּוֹת יִפְּלוּ הַחַמָּנִים שֶׁבְּרָאשֵׁי הַגַּגּוֹת וְיִכָּרְתוּ — וְנָתַתִּי אֶת פִּגְרֵיכֶם וְגוֹ' הֲרֵי שָׁלוֹשׁ, סִלּוּק שְׁכִינָה אַרְבַּע, חֻרְבַּן עָרִים, שִׁמְמוֹן מִקְדָּשׁ מִן הַגְּדוּדִיּוֹת, וְלֹא אָרִיחַ קָרְבָּנוֹת, הֲרֵי שֶׁבַע:\",2,0],[2,128,26,32,\"והשמתי אני את הארץ. זוֹ מִדָּה טוֹבָה לְיִשְׂרָאֵל, שֶׁלֹּא יִמְצְאוּ הָאוֹיְבִים נַחַת רוּחַ בְּאַרְצָם, שֶׁתְּהֵא שׁוֹמֵמָה מִיּוֹשְׁבֶיהָ (ספרא):\",1,0],[2,128,26,33,\"ואתכם אזרה בגוים. זוֹ מִדָּה קָשָׁה, שֶׁבְּשָׁעָה שֶׁבְּנֵי הַמְּדִינָה גּוֹלִים לְמָקוֹם אֶחָד, רוֹאִים זֶה אֶת זֶה וּמִתְנַחֲמִין, וְיִשְׂרָאֵל נִזְרוּ כְבַמְּזָרֶה — כְּאָדָם הַזּוֹרֶה שְׂעוֹרִים בְּנָפָה וְאֵין אַחַת מֵהֶן דְּבוּקָה בַחֲבֶרְתָּהּ (שם):\",1,0],[2,128,26,33,\"והריקתי. כְּשֶׁשּׁוֹלֵף הַחֶרֶב מִתְרוֹקֵן הַנָּדָן; וּמִדְרָשׁוֹ חֶרֶב הַנִּשְׁמֶטֶת אַחֲרֵיכֶם אֵינָהּ חוֹזֶרֶת מַהֵר, כְּאָדָם שֶׁמֵּרִיק אֶת הַמַּיִם וְאֵין סוֹפָן לַחֲזֹר (ספרא):\",2,0],[2,128,26,33,\"והיתה ארצכם שממה. שֶׁלֹּא תְמַהֲרוּ לָשׁוּב לְתוֹכָהּ, וּמִתּוֹךְ כָּךְ עָרֵיכֶם יִהְיוּ חָרְבָּה — נִרְאוֹת לָכֶם חֲרֵבוֹת, שֶׁבְּשָׁעָה שֶׁאָדָם גּוֹלֶה מִבֵּיתוֹ וּמִכַּרְמוֹ וּמֵעִירוֹ וְסוֹפוֹ לַחֲזֹר, כְּאִלּוּ אֵין כַּרְמוֹ וּבֵיתוֹ חֲרֵבִים, כָּךְ שְׁנוּיָה בְּתֹ\\\"כֹּ:\",3,0],[2,128,26,34,\"אז תרצה. תְּפַיֵּס אֶת כַּעַס הַמָּקוֹם שֶׁכָּעַס עַל שְׁמִטּוֹתֶיהָ:\",1,0],[2,128,26,34,\"והרצת. לַמֶּלֶךְ את שבתתיה:\",2,0],[2,128,26,35,\"כל ימי השמה. לְשׁוֹן הֵעָשׂוֹת, וּמֵ\\\"ם דָּגֵשׁ בִּמְקוֹם כֵּפֶל שְׁמָמָה:\",1,0],[2,128,26,35,\"את אשר לא שבתה. שִׁבְעִים שָׁנָה שֶׁל גָּלוּת בָּבֶל הֵן הָיוּ כְּנֶגֶד שִׁבְעִים שְׁנוֹת הַשְּׁמִטָּה וְיוֹבֵל שֶׁהָיוּ בַּשָּׁנִים שֶׁהִכְעִיסוּ יִשְׂרָאֵל בְּאַרְצָם לִפְנֵי הַמָּקוֹם — אַרְבַּע מֵאוֹת וּשְׁלוֹשִׁים שָׁנָה; שְׁלוֹשׁ מֵאוֹת וְתִשְׁעִים הָיוּ שְׁנֵי עֲוֹנָם מִשֶּׁנִּכְנְסוּ לָאָרֶץ עַד שֶׁגָּלוּ עֲשֶׂרֶת הַשְּׁבָטִים, וּבְנֵי יְהוּדָה הִכְעִיסוּ לְפָנָיו אַרְבָּעִים שָׁנָה מִשֶּׁגָּלוּ עֲשֶׂרֶת הַשְּׁבָטִים עַד חָרְבוֹת יְרוּשָׁלַיִם, הוּא שֶׁנֶּאֱמַר בִּיחֶזְקֵאל \\\"וְאַתָּה שְׁכַב עַל צִדְּךָ הַשְּׂמָאלִי וְגוֹ', וְכִלִּיתָ אֶת אֵלֶּה וְגוֹ', וְשָׁכַבְתָּ עַל צִדְּךָ הַיְמָנִי אַרְבָּעִים יוֹם וְנָשָׂאתָ אֶת עֲוֹן בֵּית יְהוּדָה\\\", וּנְבוּאָה זוֹ נֶאֶמְרָה לִיחֶזְקֵאל בַּשָּׁנָה הַחֲמִשִּׁית לְגָלוּת הַמֶּלֶךְ יְהוֹיָכִין, וְעוֹד עָשׂוּ שֵׁשׁ שָׁנִים עַד גָּלוּת צִדְקִיָּהוּ, הֲרֵי אַרְבָּעִים וְשֵׁשׁ; וְאִ\\\"תֹּ שְׁנוֹת מְנַשֶּׁה חֲמִשִּׁים וְחָמֵשׁ הָיוּ, מְנַשֶּׁה עָשָֹה תְשׁוּבָה שְׁלוֹשִׁים וְשָׁלוֹשׁ שָׁנָה, וְכָל שְׁנוֹת רִשְׁעוֹ עֶשְֹרִים וּשְׁתַּיִם, כְּמוֹ שֶׁאָמְרוּ בְּאַגָּדַת חֵלֶק, וְשֶׁל אָמוֹן שְׁתַּיִם, וְאַחַת עֶשְֹרֵה לִיהוֹיָקִים, וּכְנֶגְדָּן לְצִדְקִיָּהוּ; צֵא וַחֲשֹׁב לְאַרְבַּע מֵאוֹת וּשְׁלוֹשִׁים וְשֵׁשׁ שָׁנָה שְׁמִטִּין וְיוֹבְלוֹת שֶׁבָּהֶם, וְהֵם שֵׁשׁ עֶשְׂרֶה לְמֵאָה — אַרְבַּע עֶשְׂרֵה שְׁמִטִּין וּשְׁנַיִם יוֹבְלוֹת, הֲרֵי לְאַרְבַּע מֵאוֹת שָׁנָה שִׁשִּׁים וְאַרְבַּע, לִשְׁלוֹשִׁים וְשֵׁשׁ שָׁנָה חָמֵשׁ שְׁמִטּוֹת, הֲרֵי שִׁבְעִים חָסֵר אַחַת, וְעוֹד שָׁנָה יְתֵרָה, שֶׁנִּכְנְסָה בַשְּׁמִטָּה הַמַּשְׁלֶמֶת לְשִׁבְעִים, וַעֲלֵיהֶם נִגְזַר שִׁבְעִים שָׁנָה שְׁלֵמִים, וְכֵן הוּא אוֹמֵר בְּדִבְרֵי הַיָמִים (דברי הימים ב' ל\\\"ו), עַד רָצְתָה הָאָרֶץ אֶת שַׁבְּתוֹתֶיהָ … לְמַלֹּאות שִׁבְעִים שָׁנָה (סדר עולם):\",2,0],[2,128,26,36,\"והבאתי מרך. פַּחַד וְרֹךְ לֵבָב; מ\\\"ם שֶׁל מֹרֶךְ יְסוֹד נוֹפֵל הוּא, כְּמוֹ מ\\\"ם שֶׁל מוֹעֵד וְשֶׁל מוֹקֵשׁ:\",1,0],[2,128,26,36,\"ונסו מנסת חרב. כְּאִלּוּ רוֹדְפִים הוֹרְגִים אוֹתָם:\",2,0],[2,128,26,36,\"עלה נדף. שֶׁהָרוּחַ דּוֹחֲפוֹ וּמַכֵּהוּ עַל עָלֶה אַחֵר וּמְקַשְׁקֵשׁ וּמוֹצִיא קוֹל, וְכֵן תַּרְגּוּמוֹ קַל טַרְפָּא דְשָׁקִיף, לְשׁוֹן חֲבָטָה, \\\"שְׁדוּפוֹת קָדִים\\\" (בראשית מ\\\"א) — שְׁקִיפָן קִדּוּם, לְשׁוֹן מַשְׁקוֹף, מְקוֹם חֲבָטַת הַדֶּלֶת, וְכֵן תַּרְגּוּמוֹ שֶׁל \\\"חַבּוּרָה\\\" (שמות כ\\\"א) — מַשְׁקוֹפֵי:\",3,0],[2,128,26,37,\"וכשלו איש באחיו. כְּשֶׁיָּרוּצוּ לָנוּס יִכָּשְׁלוּ זֶה בָזֶה, כִּי יִבָּהֲלוּ לָרוּץ:\",1,0],[2,128,26,37,\"כמפני חרב. כְּאִלּוּ בּוֹרְחִים מִלִּפְנֵי הוֹרְגִים, שֶׁיְּהֵא בִלְבָבָם פַּחַד, וְכָל שָׁעָה סְבוּרִים שֶׁאָדָם רוֹדְפָם; וּמִדְרָשׁוֹ וְכָשְׁלוּ אִישׁ בְּאָחִיו, זֶה נִכְשָׁל בַּעֲוֹנוֹ שֶׁל זֶה, שֶׁכָּל יִשְׂרָאֵל עֲרֵבִין זֶה לָזֶה (ספרא; סנהדרין כ\\\"ז):\",2,0],[2,128,26,38,\"ואבדתם בגוים. כְּשֶׁתִּהְיוּ פְזוּרִים, תִּהְיוּ אֲבוּדִים זֶה מִזֶּה (עי' ספרא):\",1,0],[2,128,26,38,\"ואכלה אתכם. אֵלּוּ הַמֵּתִים בַּגּוֹלָה:\",2,0],[2,128,26,39,\"בעונת אבתם אתם. כְּשֶׁעֲווֹנוֹת אֲבוֹתָם אִתָּם — כְּשֶׁאוֹחֲזִים מַעֲשֵׂה אֲבוֹתֵיהֶם בִּידֵיהֶם (שם):\",1,0],[2,128,26,39,\"ימקו. לְשׁוֹן הֲמַסָּה, כְּמוֹ יִמַּסּוּ, וְכָמוֹהוּ \\\"תִּמַּקְנָה בְחֹרֵיהֶן\\\" (זכריה י\\\"ד), \\\"נָמַקּוּ חַבּוּרֹתָי\\\" (תהילים ל\\\"ח):\",2,0],[2,128,26,41,\"והבאתי אתם. אֲנִי בְעַצְמִי אֲבִיאֵם; זוֹ מִדָּה טוֹבָה לְיִשְׂרָאֵל, שֶׁלֹּא יִהְיוּ אוֹמְרִים, הוֹאִיל וְגָלִינוּ בֵּין הָאֻמּוֹת נַעֲשֶׂה כְמַעֲשֵׂיהֶם, אֲנִי אֵינִי מַנִּיחָם, אֶלָּא מַעֲמִיד אֲנִי אֶת נְבִיאַי וּמַחֲזִירָן לְתַחַת כְּנָפַי, שֶׁנֶּאֱמַר (יחזקאל כ\\\"א), \\\"וְהָעֹלָה עַל רוּחֲכֶם הָיוֹ לֹא תִהְיֶה וְגוֹ' חַי אָנִי … אִם לֹא בְּיָד חֲזָקָה וְגוֹ'\\\" (ספרא):\",1,0],[2,128,26,41,\"או אז יכנע. כְּמוֹ \\\"אוֹ נוֹדַע כִּי שׁוֹר נַגָּח הוּא\\\" (שמות כ\\\"א) — אִם אָז יִכָּנַע; לָשׁוֹן אַחֵר אוּלַי — שֶׁמָּא אָז יִכָּנַע לְבָבָם וְגוֹ':\",2,0],[2,128,26,41,\"ואז ירצו את עונם. יְכַפְּרוּ עַל עֲווֹנָם בְּיִסּוּרֵיהֶם:\",3,0],[2,128,26,42,\"וזכרתי את בריתי יעקוב. בַּחֲמִשָּׁה מְקוֹמוֹת נִכְתַּב מָלֵא, וְאֵלִיָּהוּ חָסֵר בַּחֲמִשָּׁה מְקוֹמוֹת — יַעֲקֹב נָטַל אוֹת מִשְּׁמוֹ שֶׁל אֵלִיָּהוּ עֵרָבוֹן שֶׁיָּבֹא וִיבַשֵּׂר גְּאֻלַּת בָּנָיו:\",1,0],[2,128,26,42,\"וזכרתי את בריתי יעקוב. לָמָּה נִמְנוּ אֲחוֹרַנִּית? כְּלוֹמַר, כְּדַאי הוּא יַעֲקֹב הַקָּטָן לְכָךְ, וְאִם אֵינוֹ כְדַאי, הֲרֵי יִצְחָק עִמּוֹ, וְאִם אֵינוֹ כְדַאי, הֲרֵי אַבְרָהָם עִמּוֹ שֶׁהוּא כְדַאי, וְלָמָּה לֹא נֶאֶמְרָה זְכִירָה בְיִצְחָק? אֶלָּא אֲפָרוֹ שֶׁל יִצְחָק נִרְאֶה לְפָנַי צָבוּר וּמֻנָּח עַל הַמִּזְבֵּחַ (ספרא):\",2,0],[2,128,26,43,\"יען וביען. גְּמוּל וּבִגְמוּל אֲשֶׁר בְּמִשְׁפָּטַי מָאָסוּ (עי' ספרא):\",1,0],[2,128,26,44,\"ואף גם זאת. וְאַף אֲפִלּוּ אֲנִי עוֹשֶׂה עִמָּהֶם זֹאת הַפֻּרְעָנוּת אֲשֶׁר אָמַרְתִּי בהיותם בארץ איביהם, לֹא אֶמְאָסֵם לְכַלֹּתָם וּלְהָפֵר בְּרִיתִי אֲשֶׁר אִתָּם:\",1,0],[2,128,26,45,\"ברית ראשנים. שֶׁל שְׁבָטִים (ספרא):\",1,0],[2,128,26,46,\"והתורת. אַחַת בִּכְתָב וְאַחַת בְּעַל פֶּה, מַגִּיד שֶׁכֻּלָּם נִתְּנוּ לְמֹשֶׁה בְּסִינַי (שם):\",1,0],[2,128,27,2,\"כי יפלא. יַפְרִישׁ בְּפִיו:\",1,0],[2,128,27,2,\"בערכך נפשת. לִתֵּן עֵרֶךְ נְפָשׁוֹת — לוֹמַר עֵרֶךְ דָּבָר שֶׁנַּפְשׁוֹ תְלוּיָה בוֹ עָלַי (עי' ספרא; ערכין ד'):\",2,0],[2,128,27,3,\"והיה ערכך וגו'. אֵין עֵרֶךְ זֶה לְשׁוֹן דָּמִים, אֶלָּא בֵּין שֶׁהוּא יָקָר בֵּין שֶׁהוּא זוֹל, כְּפִי שָׁנָיו הוּא הָעֵרֶךְ הַקָּצוּב עָלָיו בְּפָרָשָׁה זוֹ:\",1,0],[2,128,27,3,\"ערכך. כְּמוֹ עֵרֶךְ, וְכֵפֶל הַכָּפִי\\\"ן לֹא יָדַעְתִּי מֵאֵיזֶה לָשׁוֹן הוּא:\",2,0],[2,128,27,5,\"ואם מבן חמש שנים. לֹא שֶׁיְּהֵא הַנּוֹדֵר קָטָן — שֶׁאֵין בְּדִבְרֵי קָטָן כְּלוּם — אֶלָּא גָּדוֹל שֶׁאָמַר עֵרֶךְ קָטָן זֶה שֶׁהוּא בֶן חָמֵשׁ שָׁנִים עָלַי (עי' ערכין ב'):\",1,0],[2,128,27,7,\"ואם מבן ששים שנה וגו'. כְּשֶׁמַּגִּיעַ לִימֵי הַזִּקְנָה, הָאִשָּׁה קְרוֹבָה לְהֵחָשֵׁב כְּאִישׁ, לְפִיכָךְ הָאִישׁ פּוֹחֵת בְּהִזְדַּקְּנוֹ יוֹתֵר מִשְּׁלִישׁ בְּעֶרְכּוֹ, וְהָאִשָּׁה אֵינָהּ פוֹחֶתֶת אֶלָּא שְׁלִישׁ בְּעֶרְכָּהּ, דְּאָמְרֵי אִינְשֵׁי \\\"סָבָא בְּבֵיתָא, פַּחָא בְּבֵיתָא, סָבְתָא בְּבֵיתָא סִימָא בְּבֵיתָא וְסִימָנָא טָבָא בְּבֵיתָא\\\" (ערכין י\\\"ט):\",1,0],[2,128,27,8,\"ואם מך הוא. שֶׁאֵין יָדוֹ מַשֶּׂגֶת לִתֵּן הָעֵרֶךְ הַזֶּה.\",1,0],[2,128,27,8,\"והעמידו. לַנֶּעֱרָךְ לִפְנֵי הַכֹּהֵן, וְיַעֲרִיכֶנּוּ לְפִי הַשָּׂגַת יָדוֹ שֶׁל מַעֲרִיךְ:\",2,0],[2,128,27,8,\"על פי אשר תשיג. לְפִי מַה שֶּׁיֶּשׁ לוֹ יְסַדְּרֶנּוּ, וְיַשְׁאִיר לוֹ כְּדֵי חַיָּיו: מִטָּה, כַּר וְכֶסֶת, וּכְלֵי אֻמָּנוּת; אִם הָיָה חַמָּר מַשְׁאִיר לוֹ חֲמוֹרוֹ (בבא מציעא קי\\\"ד; ערכין כ\\\"ג):\",3,0],[2,128,27,9,\"כל אשר יתן ממנו. אָמַר רַגְלָהּ שֶׁל זוֹ עוֹלָה, דְּבָרָיו קַיָּמִין, וְתִמָּכֵר לְצָרְכֵי עוֹלָה, וְדָמֶיהָ חֻלִּין חוּץ מִדְּמֵי אוֹתוֹ הָאֵבֶר (ספרא; ערכין ה'):\",1,0],[2,128,27,10,\"טוב ברע. תָּם בְּבַעַל מוּם.\",1,0],[2,128,27,10,\"או רע בטוב. וְכָל שֶׁכֵּן טוֹב בְּטוֹב וְרַע בְּרַע (עי' תמורה ט'):\",2,0],[2,128,27,11,\"ואם כל בהמה טמאה. בְּבַעֲלַת מוּם הַכָּתוּב מְדַבֵּר, שֶׁהִיא טְמֵאָה לְהַקְרָבָה, וְלִמֶּדְךָ הַכָּתוּב שֶׁאֵין קָדָשִׁים תְּמִימִים יוֹצְאִין לְחֻלִּין בְּפִדְיוֹן אֶלָּא אִם כֵּן הֻמְּמוּ (שם ל\\\"ג):\",1,0],[2,128,27,12,\"כערכך הכהן כן יהיה. לִשְׁאָר כָּל אָדָם הַבָּא לִקְנוֹתָהּ מִיַּד הֶקְדֵּשׁ:\",1,0],[2,128,27,13,\"ואם גאל יגאלנה. בַּבְּעָלִים הֶחֱמִיר הַכָּתוּב לְהוֹסִיף חֹמֶשׁ, וְכֵן בְּמַקְדִּישׁ בַּיִת, וְכֵן בְּמַקְדִּישׁ אֶת הַשָּׂדֶה, וְכֵן בְּפִדְיוֹן מַעֲשֵֹר שֵׁנִי — הַבְּעָלִים מוֹסִיפִין חֹמֶשׁ וְלֹא שְׁאָר כָּל אָדָם (שם כ\\\"ה):\",1,0],[2,128,27,16,\"והיה ערכך לפי זרעו. לֹא כְּפִי שָׁוְיָהּ, אַחַת שָׂדֶה טוֹבָה וְאַחַת שָׂדֶה רָעָה פִּדְיוֹן הֶקְדֵּשָׁן שָׁוֶה — בֵּית כֹּר שְׂעוֹרִים בַּחֲמִשִּׁים שְׁקָלִים — כָּךְ גְּזֵרַת הַכָּתוּב, וְהוּא שֶׁבָּא לְגָאֳלָהּ בִּתְחִלַּת הַיּוֹבֵל. וְאִם בָּא לְגָאֳלָהּ בְאֶמְצָעוֹ, נוֹתֵן לְפִי הַחֶשְׁבּוֹן סֶלַע וּפֻנְדְּיוֹן לְשָׁנָה, לְפִי שֶׁאֵינָהּ הֶקְדֵּשׁ אֶלָּא לְמִנְיַן שְׁנוֹת הַיּוֹבֵל, שֶׁאִם נִגְאֲלָה הֲרֵי טוֹב, וְאִם לָאו הַגִּזְבָּר מוֹכְרָהּ בַּדָּמִים הַלָּלוּ לְאַחֵר, וְעוֹמֶדֶת בְּיַד הַלּוֹקֵחַ עַד הַיּוֹבֵל כִּשְׁאָר כָּל הַשָּׂדוֹת הַמְּכוּרוֹת, וּכְשֶׁהִיא יוֹצְאָה מִיָּדוֹ חוֹזֶרֶת לַכֹּהֲנִים שֶׁל אוֹתוֹ מִשְׁמָר שֶׁהַיּוֹבֵל פּוֹגֵעַ בּוֹ, וּמִתְחַלֶּקֶת בֵּינֵיהֶם, זֶהוּ הַמִּשְׁפָּט הָאָמוּר בְּמַקְדִּישׁ שָׂדֶה, וְעַכְשָׁו אֲפָרְשֶׁנּוּ עַל סֵדֶר הַמִּקְרָאוֹת:\",1,0],[2,128,27,17,\"אם משנת היבל יקדיש וגו'. אִם מִשֶּׁעָבְרָה שְׁנַת הַיּוֹבֵל מִיָּד הִקְדִּישָׁהּ, וּבָא זֶה לְגָאֳלָהּ מִיָּד.\",1,0],[2,128,27,17,\"כערכך יקום. כָּעֵרֶךְ הַזֶּה הָאָמוּר יִהְיֶה — חֲמִשִּׁים כֶּסֶף יִתֵּן:\",2,0],[2,128,27,18,\"ואם אחר היבל יקדיש. וְכֵן אִם הִקְדִּישָׁהּ מִשְּׁנַת הַיֹּבֵל וְנִשְׁתַּהָת בְּיַד גִּזְבָּר, וּבָא זֶה לְגָאֳלָהּ אַחַר הַיּוֹבֵל.\",1,0],[2,128,27,18,\"וחשב לו הכהן את הכסף על פי השנים הנותרת. כְּפִי חֶשְׁבּוֹן; כֵּיצַד? הֲרֵי קָצַב דָּמֶיהָ שֶׁל אַרְבָּעִים וְתֵשַׁע שָׁנָה חֲמִשִּׁים שֶׁקֶל, הֲרֵי שֶׁקֶל לְכָל שָׁנָה וְשֶׁקֶל יָתֵר עַל כֻּלָּן, וְהַשֶּׁקֶל אַרְבָּעִים וּשְׁמוֹנָה פֻנְדְּיוֹן, הֲרֵי סֶלַע וּפֻנְדְּיוֹן לְשָׁנָה, אֶלָּא שֶׁחָסֵר פֻּנְדְּיוֹן אֶחָד לְכֻלָּן, וְאָמְרוּ רַבּוֹתֵינוּ שֶׁאוֹתוֹ פֻּנְדְּיוֹן קַלְבּוֹן לִפְרוֹטְרוֹט, וְהַבָּא לִגְאֹל, יִתֵּן סֶלַע וּפֻנְדְּיוֹן לְכָל שָׁנָה לַשָּׁנִים הַנּוֹתָרוֹת עַד שְׁנַת הַיּוֹבֵל (עי' ספרא; ערכין כ\\\"ד):\",2,0],[2,128,27,18,\"ונגרע מערכך. מִנְיַן הַשָּׁנִים שֶׁמִּשְּׁנַת הַיּוֹבֵל עַד שְׁנַת הַפִּדְיוֹן:\",3,0],[2,128,27,19,\"ואם גאל יגאל. הַמַּקְדִּישׁ אוֹתוֹ, יוֹסִיף חֹמֶשׁ עַל הַקִּצְבָּה הַזֹּאת:\",1,0],[2,128,27,20,\"ואם לא יגאל את השדה. הַמַּקְדִּישׁ:\",1,0],[2,128,27,20,\"ואם מכר. הַגִּזְבָּר:\",2,0],[2,128,27,20,\"את השדה לאיש אחר לא יגאל עוד. לָשׁוּב בְּיַד הַמַּקְדִּישׁ:\",3,0],[2,128,27,21,\"והיה השדה בצאתו ביבל. מִיַּד הַלּוֹקְחוֹ מִן הַגִּזְבָּר, כְּדֶרֶךְ שְׁאָר שָׂדוֹת הַיּוֹצְאוֹת מִיַּד לוֹקְחֵיהֶם בַּיּוֹבֵל:\",1,0],[2,128,27,21,\"קדש לה'. לֹא שֶׁיָּשׁוּב לְהֶקְדֵּשׁ בֶּדֶק הַבַּיִת, לְיַד הַגִּזְבָּר, אֶלָּא כשדה החרם הַנָּתוּן לַכֹּהֲנִים — שֶׁנֶּאֱמַר \\\"כָּל חֵרֶם בְּיִשְׂרָאֵל לְךָ יִהְיֶה\\\" (במדבר י\\\"ח) — אַף זוֹ תִּתְחַלֵּק לַכֹּהֲנִים שֶׁל אוֹתוֹ מִשְׁמָר שֶׁיּוֹם הַכִּפּוּרִים שֶׁל יוֹבֵל פּוֹגֵעַ בּוֹ (ערכין כ\\\"ח):\",2,0],[2,128,27,22,\"ואם את שדה מקנתו וגו'. חִלּוּק יֵשׁ בֵּין שְׂדֵה מִקְנָה לִשְׂדֵה אֲחֻזָּה, שֶׁשְּׂדֵה מִקְנָה לֹא תִתְחַלֵּק לַכֹּהֲנִים בַּיּוֹבֵל, לְפִי שֶׁאֵינוֹ יָכוֹל לְהַקְדִּישָׁהּ אֶלָּא עַד הַיּוֹבֵל, שֶׁהֲרֵי בַיּוֹבֵל הָיְתָה עֲתִידָה לָצֵאת מִיָּדוֹ וְלָשׁוּב לַבְּעָלִים, לְפִיכָךְ אִם בָּא לְגָאֳלָהּ, יִגְאַל בַּדָּמִים הַלָּלוּ הַקְּצוּבִים לִשְׂדֵה אֲחֻזָּה; וְאִם לֹא יִגְאַל, וְיִמְכְּרֶנָּה גִּזְבָּר לְאַחֵר, אוֹ אִם יִגְאַל הוּא בשנת היובל ישוב השדה לאשר קנהו מאתו — אוֹתוֹ שֶׁהִקְדִּישׁ, וּפֶן תֹּאמַר \\\"לַאֲשֶׁר קָנָהוּ\\\" הַלּוֹקֵחַ הַזֶּה הָאַחֲרוֹן מֵאִתּוֹ, וְזֶהוּ הַגִּזְבָּר, לְכָךְ הֻצְרַךְ לוֹמַר לאשר לו אחזת הארץ — מִירֻשַּׁת אָבוֹת, וְזֶהוּ בְּעָלִים הָרִאשׁוֹנִים שֶׁמְּכָרוּהָ לַמַּקְדִּישׁ (ערכין כ\\\"ו):\",1,0],[2,128,27,25,\"וכל ערכך יהיה בשקל הקדש. כָּל עֶרְכְּךָ שֶׁכָּתוּב בּוֹ שְׁקָלִים, יִהְיֶה בְשֶׁקֶל הַקֹּדֶשׁ:\",1,0],[2,128,27,25,\"עשרים גרה. עֶשְׂרִים מָעוֹת, כָּךְ הָיוּ מִתְּחִלָּה, וּלְאַחַר מִכָּאן הוֹסִיפוּ שְׁתוּת, וְאָמְרוּ רַבּוֹתֵינוּ שֵׁשׁ מָעָה כֶּסֶף דִּינָר, עֶשְׂרִים וְאַרְבַּע מָעוֹת לְסֶלַע (עי' בכורות נ'):\",2,0],[2,128,27,26,\"לא יקדיש איש אתו. לְשֵׁם קָרְבָּן אַחֵר, לְפִי שֶׁאֵינוֹ שֶׁלּוֹ (עי' ערכין כ\\\"ט):\",1,0],[2,128,27,27,\"ואם בבהמה הטמאה וגו'. אֵין הַמִּקְרָא הַזֶּה מוּסָב עַל הַבְּכוֹר, שֶׁאֵין לוֹמַר בִּבְכוֹר בְּהֵמָה טְמֵאָה וּפָדָה בְּעֶרְכְּךָ, וַחֲמוֹר אֵין זֶה, שֶׁהֲרֵי אֵין פִּדְיוֹן פֶּטֶר חֲמוֹר אֶלָּא טָלֶה, וְהוּא מַתָּנָה לַכֹּהֵן, וְאֵינוֹ לְהֶקְדֵּשׁ, אֶלָּא הַכָּתוּב מוּסָב עַל הַהֶקְדֵּשׁ, שֶׁהַכָּתוּב שֶׁל מַעְלָה דִּבֵּר בְּפִדְיוֹן בְּהֵמָה טְהוֹרָה שֶׁהֻמְּמָה, וְכָאן דִּבֵּר בְּמַקְדִּישׁ בְּהֵמָה טְמֵאָה לְבֶדֶק הַבַּיִת:\",1,0],[2,128,27,27,\"ופדה בערכך. כְּפִי מַה שֶּׁיַּעֲרִיכֶנָּה הַכֹּהֵן:\",2,0],[2,128,27,27,\"ואם לא יגאל. עַל יְדֵי בְעָלִים:\",3,0],[2,128,27,27,\"ונמכר בערכך. לַאֲחֵרִים:\",4,0],[2,128,27,28,\"אך כל חרם וגו'. נֶחְלְקוּ רַבּוֹתֵינוּ בַּדָּבָר, יֵ\\\"אֹ סְתָם חֲרָמִים לְהֶקְדֵּשׁ, וּמָה אֲנִי מְקַיֵּם כָּל חֵרֶם בְּיִשְׂרָאֵל לְךָ יִהְיֶה? בְּחֶרְמֵי כֹהֲנִים, שֶׁפֵּרֵשׁ וְאָמַר הֲרֵי זֶה חֵרֶם לַכֹּהֵן; וְיֵשׁ שֶׁאָמְרוּ, סְתָם חֲרָמִים לַכֹּהֵן (עי' ספרא; ערכין כ\\\"ח):\",1,0],[2,128,27,28,\"לא ימכר ולא יגאל. אֶלָּא יִנָּתֵן לַכֹּהֵן: לְדִבְרֵי הָאוֹמֵר סְתָם חֲרָמִים לַכֹּהֲנִים, מְפֹרָשׁ מִקְרָא זֶה בִּסְתָם חֲרָמִים, וְהָאוֹמֵר סְתָם חֲרָמִים לְבֶדֶק הַבַּיִת, מְפָרֵשׁ מִקְרָא זֶה בְּחֶרְמֵי כֹהֲנִים — שֶׁהַכֹּל מוֹדִים שֶׁחֶרְמֵי כֹהֲנִים אֵין לָהֶם פִּדְיוֹן עַד שֶׁיָּבֹאוּ לְיַד כֹּהֵן וְחֶרְמֵי גָּבוֹהַּ נִפְדִּים:\",2,0],[2,128,27,28,\"כל חרם קדש קדשים הוא. הָאוֹמֵר סְתָם חֲרָמִים לְבֶדֶק הַבַּיִת, מֵבִיא רְאָיָה מִכָּאן, וְהָאוֹמֵר סְתָם חֲרָמִים לַכֹּהֲנִים, מְפָרֵשׁ \\\"כָּל חֵרֶם קֹדֶשׁ קָדָשִׁים הוּא\\\" לְלַמֵּד שֶׁחֶרְמֵי כֹהֲנִים חָלִים עַל קָדְשֵׁי קָדָשִׁים וְעַל קָדָשִׁים קַלִּים, וְנוֹתֵן לַכֹּהֵן, כְּמוֹ שֶׁשָּׁנִינוּ בְמַסֶּכֶת עֲרָכִין (דף כ\\\"ח), אִם נֵדֶר, נוֹתֵן דְּמֵיהֶן, וְאִם נְדָבָה, נוֹתֵן אֶת טוֹבָתָהּ:\",3,0],[2,128,27,28,\"מאדם. כְּגוֹן שֶׁהֶחֱרִים עֲבָדָיו וְשִׁפְחוֹתָיו הַכְּנַעֲנִים:\",4,0],[2,128,27,29,\"כל חרם אשר יחרם וגו'. הַיּוֹצֵא לֵהָרֵג וְאָמַר אֶחָד עֶרְכּוֹ עָלַי, לֹא אָמַר כְּלוּם (ספרא; ערכין ו'):\",1,0],[2,128,27,29,\"מות יומת. הֲרֵי הוֹלֵךְ לָמוּת, לְפִיכָךְ לֹא יִפָּדֶה — אֵין לוֹ לֹא דָמִים וְלֹא עֵרֶךְ:\",2,0],[2,128,27,30,\"וכל מעשר הארץ. בְּמַעֲשֵׂר שֵׁנִי הַכָּתוּב מְדַבֵּר:\",1,0],[2,128,27,30,\"מזרע הארץ. דָּגָן:\",2,0],[2,128,27,30,\"מפרי העץ. תִּירוֹשׁ וְיִצְהָר:\",3,0],[2,128,27,30,\"לה' הוא. קְנָאוֹ הַשֵּׁם. וּמִשֻּׁלְחָנוֹ צִוָּה לְךָ לַעֲלוֹת וְלֶאֱכֹל בִּירוּשָׁלַיִם, כְּמוֹ שֶׁנֶּאֱמַר (דברים י\\\"ד), וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךָ, מַעְשַׂר דְּגָנְךָ תִּירֹשְׁךָ וְגוֹ' (עי' קידושין נ\\\"ד):\",4,0],[2,128,27,31,\"ממעשרו. וְלֹא מִמַּעְשַׂר חֲבֵרוֹ — הַפּוֹדֶה מַעֲשֵׂר שֶׁל חֲבֵרוֹ אֵין מוֹסִיף חֹמֶשׁ, וּמַה הִיא גְאֻלָּתוֹ? יִפְדֶנּוּ כְּדֵי לְהַתִּירוֹ בַאֲכִילָה בְכָל מָקוֹם, וְהַמָּעוֹת יַעֲלֶה וְיֹאכַל בִירוּשָׁלַיִם, כְּמוֹ שֶׁנֶּאֱמַר (דברים י\\\"ד), וְנָתַתָּה בַּכָּסֶף וְגוֹ' (עי' קידושין כ\\\"ד):\",1,0],[2,128,27,32,\"תחת השבט. כְּשֶׁבָּא לְעַשְּׂרָן, מוֹצִיאָן בַּפֶּתַח זֶה אַחַר זֶה, וְהָעֲשִֹירִי מַכֶּה בְּשֵׁבֶט צְבוּעָה בְסִקְרָא, לִהְיוֹת נִכָּר שֶׁהוּא מַעֲשֵׂר, כֵּן עוֹשֶׂה לִטְלָאִים וְלַעֲגָלִים שֶׁל כָּל שָׁנָה וְשָׁנָה (בכו' נ\\\"ח):\",1,0],[2,128,27,32,\"יהיה קדש. לִקְרַב לַמִּזְבֵּחַ דָּמוֹ וְאֵמוּרָיו, וְהַבָּשָׂר נֶאֱכָל לַבְּעָלִים, שֶׁהֲרֵי לֹא נִמְנָה עִם שְׁאָר מַתְּנוֹת כְּהֻנָה, וְלֹא מָצִינוּ שֶׁיְּהֵא נָתוּן בְּשָׂרוֹ לַכֹּהֲנִים:\",2,0],[2,128,27,33,\"לא יבקר וגו'. לְפִי שֶׁנֶּאֱמַר \\\"וְכֹל מִבְחַר נִדְרֵיכֶם\\\" (דברים י\\\"ב), יָכוֹל יְהֵא בוֹרֵר וּמוֹצִיא אֶת הַיָּפֶה, תַּ\\\"לֹ \\\"לֹא יְבַקֵּר בֵּין טוֹב לָרַע\\\" — בֵּין תָּם בֵּין בַּעַל מוּם חָלָה עָלָיו קְדֻשָּׁה — וְלֹא שֶׁיִּקְרַב בַּעַל מוּם, אֶלָּא יֵאָכֵל בְּתוֹרַת מַעֲשֵׂר וְאָסוּר לִגָּזֵז וְלֵעָבֵד (עי' בכורות י\\\"ד):\",1,0],[2,129,1,1,\"מַשָּׂא דְבַר ה׳. פורפור״ט בְּלַעַ״ז, דָּבָר הַנִּמְסָר לְמַלְאָכִי לָשֵׂאת אוֹתוֹ אֶל בְּנֵי יִשְׂרָאֵל.\",1,0],[2,129,1,1,\"בְּיַד מַלְאָכִי. כְּבָר הָיָה מָסוּר בְּיָדוֹ זֶה יָמִים רַבִּים. מִכָּאן דָּרְשׁוּ רַבּוֹתֵינוּ בִּבְרַיְתָא דִּמְכִילְתָּא, שֶׁכָּל הַנְּבִיאִים עָמְדוּ עַל הַר סִינַי, וְשָׁם נִמְסְרוּ לָהֶם הַנְּבוּאוֹת. וְכֵן (ישעיהו מח:טז) אוֹמֵר: ״מֵעֵת הֱיוֹתָהּ שָׁם אָנִי, וְעַתָּה ה׳ אֱלֹהִים שְׁלָחַנִי״.\",2,0],[2,129,1,2,\"וָאֹהַב אֶת יַעֲקֹב. לָתֵת לוֹ אֶת ״אֶרֶץ חֶמְדָּה צְבִי צִבְאוֹת גּוֹיִם״ (ירמיהו ג:יט) – אֶרֶץ שֶׁצָּבִין כָּל צִבְאוֹת הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת בָּהּ.\",1,0],[2,129,1,3,\"וְאֶת עֵשָׂו שָׂנֵאתִי. לְדוֹחֲפוֹ אֶל אֶרֶץ שֵׂעִיר מִפְּנֵי יַעֲקֹב אָחִיו. וּמִנְהָג שֶׁבָּעוֹלָם, מִי שֶׁיֵּשׁ לוֹ שְׁנֵי בָּנִים, לַבְּכוֹר הוּא בּוֹרֵר לוֹ מָנָה יָפָה.\",1,0],[2,129,1,3,\"וָאָשִׂים אֶת הָרָיו שְׁמָמָה. אֵינָן דּוֹמִין לְהָרֵי יִשְׂרָאֵל.\",2,0],[2,129,1,3,\"לְתַנּוֹת מִדְבָּר. מְעוֹן תַּנִּים.\",3,0],[2,129,1,4,\"כִּי תֹאמַר אֱדוֹם רֻשַּׁשְׁנוּ. וְאִם יֹאמְרוּ מַחֲרִיבֵי הַמִּקְדָּשׁ: מִתְּחִלָּתֵנוּ רָשִׁים הָיִינוּ, אֲבָל מֵעַתָּה שֶׁהֶעֱשַׁרְנוּ מִבִּזַּת יְרוּשָׁלַיִם נָשׁוּב וְנִבְנֶה חֳרָבוֹת שֶׁלָּנוּ – כֹּה אָמַר ה׳ וְגוֹ׳.\",1,0],[2,129,1,5,\"יִגְדַּל ה׳ מֵעַל לִגְבוּל יִשְׂרָאֵל. יַרְאֶה גְּדֻלָּתוֹ מֵעַל לִגְבוּלֵנוּ לְהוֹדִיעַ כִּי אֲנַחְנוּ עַמּוֹ. וְיוֹנָתָן תִּרְגֵּם: ״יִסְגֵּא יְקָרָא דַה׳, וְאַפְתֵּי יָת תְּחוּם אַרְעָא דְיִשְׂרָאֵל״.\",1,0],[2,129,1,6,\"בֵּן. יֵשׁ עָלָיו לְכַבֵּד אָב, וְכֵן עֶבֶד אֲדוֹנָיו. וְאַתֶּם קְרוּיִין בָּנִים וַעֲבָדִים, וְעַתָּה אִם אָב אֲנִי לָכֶם אַיֵּה כְבוֹדִי.\",1,0],[2,129,1,6,\"אָמַר ה׳ צְבָאוֹת לָכֶם. אַתֶּם הַכֹּהֲנִים הַבּוֹזִים אֶת שְׁמִי.\",2,0],[2,129,1,6,\"וַאֲמַרְתֶּם בַּמֶּה בָזִינוּ. כְּלוֹמַר יָדַעְתִּי שֶׁתֹּאמְרוּ לִי: ״בַּמֶּה בָזִינוּ״? הֲרֵי הַבִּזָּיוֹן.\",3,0],[2,129,1,7,\"מַגִּישִׁים עַל מִזְבְּחִי וְגוֹ׳: וַאֲמַרְתֶּם. כְּלוֹמַר, וְאִם תֹּאמְרוּן: ״בַּמֶּה גֵאַלְנוּךָ״? – גָּאַלְנוּ לְךָ אֶת לֶחֶם מִזְבְּחֶךָ. אֲנִי מֵשִׁיב לָכֶם, כִּי בְּזֹאת גֵּאַלְתֶּם אוֹתִי בְּאָמְרְכֶם: ״שֻׁלְחַן ה׳ נִבְזֶה הוּא״. בּוֹזִים הָיוּ לַחֲלֹק אִישׁ בְּאָחִיו בַּמְּנָחוֹת וּבַקֳּדָשִׁים, וְאוֹמֵר: מֵאַחַר שֶׁהוּא אָסוּר לָנוּ לַחֲלֹק מִנְחָה כְּנֶגֶד מִנְחָה וְזֶבַח כְּנֶגֶד זֶבַח, וְטֹרַח וְעָמָל הוּא לַחֲלֹק כָּל מִנְחָה וּמִנְחָה בִּשְׁבִיל כַּזַּיִת אוֹ כַּפּוֹל הַמַּגִּיעַ לְכָל אֶחָד וְאֶחָד.\",1,0],[2,129,1,8,\"אֵין רָע. וְכִי אֵין דָּבָר זֶה רָע?\",1,0],[2,129,1,9,\"וְעַתָּה חַלּוּ נָא פְנֵי. וְעַתָּה אַתֶּם הַכֹּהֲנִים הָעוֹשִׂים הָרַע הַזֹּאת, אֵיךְ יַעֲלֶה בִּלְבַבְכֶם לִהְיוֹת שְׁלוּחֵי יִשְׂרָאֵל לְבַקֵּשׁ עֲלֵיהֶם רַחֲמִים? הֲרֵי מִיֶּדְכֶם הָיְתָה זֹאת הָרָעָה.\",1,0],[2,129,1,9,\"הֲיִשָּׂא. אֶת פְּנֵיכֶם לִשְׁמֹעַ תְּפִלָּה מִפִּיכֶם, וְלָחֹן אֶת שׁוֹלְחֵיכֶם?\",2,0],[2,129,1,10,\"מִי גַם בָּכֶם וְיִסְגֹּר דְּלָתַיִם. הַלְוַאי וְיָקוּם אִישׁ טוֹב בָּכֶם שֶׁיִּסְגֹּר דַּלְתֵי מִקְדָּשִׁי לְבִלְתִּי הָבִיא שָׁם קָרְבָּן מְתֹעֵבָה הַזֹּאת.\",1,0],[2,129,1,10,\"וְלֹא תָאִירוּ מִזְבְּחִי חִנָּם. בָּאִישִׁים שֶׁאֵינִי מִתְרַצֶּה בָּהֶם, שֶׁהֲרֵי אֵין לִי חֵפֶץ בָּכֶם. וְרַבּוֹתֵינוּ דָּרְשׁוּ בְּתוֹרַת כֹּהֲנִים: אָדָם אוֹמֵר לַחֲבֵרוֹ: ״הָגֵף לִי אֶת הַדֶּלֶת הַזּוֹ״ – אֵין תוֹבֵעַ עָלֶיהָ שָׂכָר; ״הַדְלֵק לִי אֶת הַנֵּר הַזֶּה״ – אֵין שׁוֹאֵל עָלֶיהָ שָׂכָר. וְאַתֶּם – מִי בָּכֶם שֶׁסָּגַר דְּלָתַי חִנָּם? וְלֹא הֵאַרְתֶּם מִזְבְּחִי חִנָּם. קַל וָחֹמֶר שֶׁלֹּא עֲשִׂיתֶם חִנָּם דְּבָרִים שֶׁדַּרְכָּן לַעֲשׂוֹתָן בְּשָׂכָר. לְפִיכָךְ אֵין לִי חֵפֶץ בָּכֶם.\",2,0],[2,129,1,11,\"גָּדוֹל שְׁמִי בַּגּוֹיִם. אָמְרוּ רַבּוֹתֵינוּ: דְּקָרוּ לֵיהּ אֱלָהָא דֶּאֱלָהַיָּא. אֲפִלּוּ מִי שֶׁיֵּשׁ לוֹ עֲבוֹדָה זָרָה יוֹדֵעַ (שֶׁיֵּשׁ אֱלוֹהַּ) שֶׁהוּא עַל כֻּלָּם. וּבְכָל מָקוֹם מִתְנַדְּבִים לִשְׁמִי, אַף הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. וְרַבּוֹתֵינוּ פֵּרְשׁוּ: אֵלּוּ תַּלְמִידֵי חֲכָמִים הָעוֹסְקִים בְּהִלְכוֹת עֲבוֹדָה בְּכָל מָקוֹם. וְכֵן כָּל תְּפִלּוֹת יִשְׂרָאֵל שֶׁמִּתְפַּלְּלִין בְּכָל מָקוֹם, הֲרֵי הֵן לִי כְּמִנְחָה טְהוֹרָה. וְכֵן תִּרְגֵּם יוֹנָתָן: ״וְכָל עִדָּן דְּאַתּוּן עָבְדִין רְעוּתִי, אֲנִי מְקַבֵּל צְלוֹתְכוֹן, וּשְׁמִי רַבָּא מִתְקַדַּשׁ עַל יְדֵיכוֹן, וּצְלוֹתְכוֹן כְּקָרְבַּן דָּכֵי קֳדָמַי״. וְכֵן פֵּרַשׁ הַמִּקְרָא: וְלָמָּה אַתֶּם מְחַלְּלִין שְׁמִי? וַהֲלֹא גָּדוֹל הוּא בַּגּוֹיִם. וַאֲנִי אַהֲבָתִי וְחִבַּתִּי עֲלֵיכֶם, שֶׁבְּכָל מָקוֹם שֶׁאַתֶּם מִתְפַּלְּלִין לְפָנַי, וְאַף בַּגּוֹלָה, מֻקְטָר וּמֻגָּשׁ הוּא לִשְׁמִי.\",1,0],[2,129,1,11,\"וּמִנְחָה טְהוֹרָה. הוּא לִי, כִּי עַל יֶדְכֶם שְׁמִי נוֹרָא בַּגּוֹיִם, וְאַתֶּם מְחַלְּלִין אוֹתִי וְאֶת שְׁמִי.\",2,0],[2,129,1,12,\"וְנִיבוֹ נִבְזֶה אָכְלוֹ. נִיבוֹ שֶׁל מִזְבֵּחַ הַשָּׁגוּר בְּשִׂפְתוֹתֵיכֶם, זֶהוּ: ״תָּמִיד נִבְזֶה אָכְלוֹ״ – אַתֶּם אוֹמְרִים עָלָיו. כְּלוֹמַר, כְּבָר הוֹצֵאתֶם עָלָיו דִּבָּה זוֹ, וְנִיב זֶה הֶחֱזַקְתֶּם לְמִזְבְּחִי.\",1,0],[2,129,1,12,\"אָכְלוֹ. מַאֲכָלוֹ.\",2,0],[2,129,1,13,\"וַאֲמַרְתֶּם הִנֵּה מַתְּלָאָה. בְּהֵמָה כְּחוּשָׁה, וְאָנוּ עֲנִיִּים וְאֵין יְכֹלֶת לְהַשִּׂיג לְמִבְחַר נְדָרִים. וְכֵן תִּרְגֵּם יוֹנָתָן: ״הָא דְאַיְתִינָא מְלִיאוּתָנָא״.\",1,0],[2,129,1,13,\"וְהִפַּחְתֶּם אוֹתוֹ. זוֹ אַחַת מִשְּׁמוֹנֶה עֶשְׂרֵה תֵּבוֹת שֶׁל תִּקּוּן סוֹפְרִים. ״הִפַּחְתֶּם אוֹתוֹ״ – ״אוֹתִי״ נִכְתַּב, אֶלָּא שֶׁכִּנָּה הַכָּתוּב וּכְתָבוֹ ״אוֹתוֹ״. ״וְהִפַּחְתֶּם״ וְהִדְאַבְתֶּם – לְשׁוֹן ״מַפַּח נָפֶשׁ״ (איוב יא:כ).\",2,0],[2,129,1,13,\"אוֹתִי. וְאֶת שֻׁלְחָנִי.\",3,0],[2,129,1,14,\"נוֹכֵל. מִתְנַכֵּל בְּמִרְמָה, בְּדִבְרֵי שֶׁקֶר לְפָנַי, לֵאמֹר: ״אֵין לִי טוֹבָה מִזּוֹ״.\",1,0],[2,129,1,14,\"וְיֵשׁ בְּעֶדְרוֹ זָכָר. אַיִל הֶהָגוּן לְעוֹלָה, וְהוּא נוֹדֵר זֶבַח.\",2,0],[2,129,1,14,\"מָשְׁחָת. בַּעַל מוּם, כְּמוֹ (ויקרא כב:כה) ״מָשְׁחָתָם בָּהֶם״.\",3,0],[2,129,2,1,\"אֲלֵיכֶם. הַכֹּהֲנִים, אֲנִי מְצַוֶּה הַמִּצְוָה הַזֹּאת, שֶׁלֹּא תַּקְרִיבוּ אֵלֶּה עַל מִזְבְּחִי.\",1,0],[2,129,2,2,\"וְאָרוֹתִי. וְקִלַּלְתִּי אֶת בִּרְכוֹתֵיכֶם – מַה שֶּׁצָּרִיךְ לְבָרֵךְ לָכֶם: הַדָּגָן, וְהַתִּירוֹשׁ, וְהַיִּצְהָר.\",1,0],[2,129,2,2,\"וְגַם אָרוֹתִיהָ. וּבֶאֱמֶת אֵין לִתְלוֹת הַדָּבָר עַל תְּנַאי שֶׁתָּלִיתִי בְּ״אִם לֹא יִשְׁמַע״, כִּי יָדַעְתִּי שֶׁלֹּא תִשְׁמְעוּ. לְפִיכָךְ אֲנִי מֵעַתָּה אָרוֹתִיהָ.\",2,0],[2,129,2,3,\"וְזֵרִיתִי פֶרֶשׁ. שֶׁל בְּהֵמוֹת חַגֵּיכֶם עַל פְּנֵיכֶם. כְּלוֹמַר, לֹא תְקַבְּלוּ שָׂכָר מֵאִתִּי כִּי אִם לְרָעָה, לְבֹשֶׁת, וְאֶגְעַר לָכֶם אֶת זֶרַע הַשָּׂדֶה.\",1,0],[2,129,2,3,\"וְנָשָׂא אֶתְכֶם אֵלָיו. פֶּרֶשׁ בְּהֵמוֹת קָרְבְּנוֹתֵיכֶם יִשָּׂא אֶתְכֶם אֵלָיו, לִהְיוֹת זוֹלְלִים וְנִבְזִים כָּמוֹהוּ.\",2,0],[2,129,2,4,\"לִהְיוֹת בְּרִיתִי אֶת לֵוִי. שֶׁאֲנִי חָפֵץ שֶׁתִּתְקַיְּמוּ (אִתִּי) בַּבְּרִית שֶׁכָּרַתִּי לְשֵׁבֶט לֵוִי.\",1,0],[2,129,2,5,\"הַחַיִּים וְהַשָּׁלוֹם. שֶׁנֶּאֱמַר לְפִינְחָס ״אֶת בְּרִיתִי שָׁלוֹם״ (במדבר כה:יב), וְהֻבְטַח לוֹ וּלְזַרְעוֹ אַחֲרָיו. הֲרֵי שֶׁיְּהֵא זַרְעוֹ בַּחַיִּים.\",1,0],[2,129,2,5,\"וָאֶתְּנֵם לוֹ. שֶׁיְּקַבְּלֵם בְּמוֹרָא, וְכֵן עָשָׂה וַיִּירָאֵנִי.\",2,0],[2,129,2,5,\"נִחַת. לְשׁוֹן ׳חִתַּת׳ – נִתְיָרֵא.\",3,0],[2,129,2,6,\"בְּשָׁלוֹם וּבְמִישׁוֹר הָלַךְ אִתִּי. אַהֲרֹן וְאֶלְעָזָר וּפִינְחָס. וְכֵן בְּמַעֲשֵׂה הָעֵגֶל, הֵשִׁיבוּ כָּל שִׁבְטֵיהֶם מֵעָוֹן, שֶׁנֶּאֱמַר: ״וַיֵּאָסְפוּ אֵלָיו כָּל בְּנֵי לֵוִי״ (שמות לב:כו).\",1,0],[2,129,2,7,\"כִּי שִׂפְתֵי כֹהֵן. עֲלֵיהֶם מוּטָל לִשְׁמֹר דַּעַת. לָמָּה? שֶׁהֲרֵי תוֹרָה יְבַקְשׁוּ מִפִּיהוּ, שֶׁכְּבָר דָּבָר זֶה מָסוּר לָהֶם: ״יוֹרוּ מִשְׁפָּטֶיךָ לְיַעֲקֹב״ (דברים לג:י).\",1,0],[2,129,2,7,\"כִּי מַלְאַךְ. שְׁלוּחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמַלְאֲכֵי הַשָּׁרֵת, לְשָׁרֵת לְפָנָיו וְלִכָּנֵס לִפְנִים בִּמְחִיצָתוֹ.\",2,0],[2,129,2,10,\"לְחַלֵּל בְּרִית אֲבֹתֵינוּ. בְּרִית שֶׁכָּרַת הַקָּדוֹשׁ בָּרוּךְ הוּא עִם אֲבוֹתֵינוּ בְּסִינַי.\",1,0],[2,129,2,11,\"כִּי חִלֵּל יְהוּדָה. אֶת עַצְמוֹ, שֶׁהָיָה קֹדֶשׁ לַה׳, ״רֵאשִׁית תְּבוּאָתוֹ״ (ירמיהו ב:ג).\",1,0],[2,129,2,11,\"וּבָעַל בַּת אֵל נֵכָר. שֶׁנָּשְׂאוּ נָשִׁים נָכְרִיּוֹת בְּבָבֶל, וַאֲפִלּוּ הַכֹּהֲנִים, כְּמוֹ שֶׁמְּפֹרָשׁ בְּסֵפֶר (עזרא ט). וְרַבּוֹתֵינוּ אָמְרוּ: מַלְאָכִי זֶה עֶזְרָא.\",2,0],[2,129,2,12,\"עֵר וְעֹנֶה. עֵר בַּתַּלְמִידִים, וְעֹנֶה בַּחֲכָמִים. ״עֵר״ – לְשׁוֹן ׳אָדָם חָרִיף׳.\",1,0],[2,129,2,12,\"וּמַגִּישׁ מִנְחָה. וְאִם כֹּהֵן הוּא, לֹא יִהְיֶה לוֹ בֵּן מַגִּישׁ מִנְחָה.\",2,0],[2,129,2,13,\"שֵׁנִית תַּעֲשׂוּ. הָרִאשׁוֹנָה שֶׁהוֹכַחְתִּי הַרְבֵּה, הִיא קָשָׁה – שֶׁנָּשָׂא נָכְרִיּוֹת וַאֲפִלּוּ הוּא פָּנוּי. וְזֹאת שֵׁנִית, קָשָׁה מִמֶּנָּה, שֶׁהַנָּשׂוּי יִשְׂרְאֵלִית נָשְׂאוּ עֲלֵיהֶם אֶת הַנָּכְרִיּוֹת, לְפִי שֶׁנִּתְפַּחֲמוּ הַיִּשְׂרְאֵלִיּוֹת בָּרָעָב וּבַגּוֹלָה, וְנִתְגַּנּוּ עֲלֵיהֶם. וְהָיָה מוֹשִׁיבָהּ בְּבֵיתוֹ צְרוּרָה כְּאַלְמְנוֹת חַיּוֹת, וְהַנָּכְרִית הָיְתָה גְּבֶרֶת.\",1,0],[2,129,2,13,\"כַּסּוֹת דִּמְעָה אֶת מִזְבַּח. שֶׁהָיוּ בָּאוֹת לִפְנֵי מִזְבַּח ה׳ וּבוֹכוֹת לְפָנָיו, וְאוֹמְרוֹת: ״מָה חָטָאנוּ, וּמַה מָּצְאוּ אֲנָשֵׁינוּ בָּנוּ עָוֶל? הִנְּנוּ לִפְנֵי הַמִּזְבֵּחַ לְהִבָּדֵק כְּסוֹטוֹת״.\",2,0],[2,129,2,13,\"מֵאֵין עוֹד פְּנוֹת וְגוֹ׳. עַד שֶׁאֵינְכֶם כְּדַי שֶׁאֶפְנֶה אֶל מִנְחַתְכֶם וְלָקַחַת רִצּוּי מִיֶּדְכֶם.\",3,0],[2,129,2,13,\"וַאֲנָקָה. לְשׁוֹן ׳אֲנָחָה׳, שֶׁאָדָם מִצְטַעֵר בְּלִבּוֹ. דמוניש״א בְּלַעַ״ז. וְאָב לְכֻלָּם: ״הֵאָנֵק דֹּם״ (יחזקאל כד:יז). וְאִם ״אֲנָקָה״ לְשׁוֹן ׳צְעָקָה׳, הֵיכָן הַדְּמָמָה? וְתַרְגּוּמוֹ: ״דְּמִדַּנְקִין״. וְכֵן תִּרְגֵּם (שם כ״ד) ״וּנְקֹטֹתֶם בִּפְנֵיכֶם״ – ״וּתְדַנְקוּן״. לְשׁוֹן אָדָם הַנּוֹהֵם וּמִצְטַעֵר בְּעַצְמוֹ.\",4,0],[2,129,2,15,\"וְלֹא אֶחָד עָשָׂה. הַקָּדוֹשׁ בָּרוּךְ הוּא לְאָדָם וְחַוָּה תְּחִלָּה.\",1,0],[2,129,2,15,\"וּשְׁאָר. הָרוּחוֹת וְהַנְּפָשׁוֹת לִי הָיוּ. מֵאָדָם הָרִאשׁוֹן יָצְאוּ כֻּלָּם.\",2,0],[2,129,2,15,\"וּמָה הָאֶחָד מְבַקֵּשׁ. הָאֶחָד שֶׁבַּזּוּג מְבַקֵּשׁ לִמְצֹא עֲלִילוֹת לְאִשְׁתּוֹ שֶׁהִיא בַּת זוּגוֹ, שֶׁהוּא זֶרַע אֱלֹהִים. מָה הוּא תּוֹעֵבָה שֶׁמְּבַזֶּה אוֹתָהּ? וְזֶהוּ לְשׁוֹן תַּרְגּוּם שֶׁל יוֹנָתָן, אֶלָּא שֶׁיּוֹנָתָן תִּרְגֵּם: ״וּמָה הָאֶחָד מְבַקֵּשׁ כִּי אִם זֶרַע אֱלֹהִים״. וְהַפֵּרוּשׁ נָכוֹן, אִם לֹא שֶׁ״הָאֶחָד״ נָקוּד בְּטַעַם זָקֵף. נוֹתֵק טַעַם הַזָּקֵף אֶת תֵּבַת ״מְבַקֵּשׁ״ מִלְּהִתְחַבֵּר עִם ״וּמָה הָאֶחָד״, וְסָמְכוֹ אֵצֶל ״זֶרַע אֱלֹהִים״. וְיֵשׁ פִּתְרוֹן עַל פִּי הָאַגָּדָה, שֶׁנִּתְקַבְּצוּ נוֹשְׂאֵי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֶל הַנָּבִיא, אָמְרוּ לוֹ: ״וְלֹא אַבְרָהָם עָשָׂה כֵן, שֶׁנָּשָׂא הָגָר עַל אִשְׁתּוֹ״? וְאָמַר לָהֶם: ״וּשְׁאָר רוּחַ לוֹ״ – לֹא דַעְתּוֹ כְּדַעְתְּכֶם, לֹא נָתַן בָּהּ עֵינָיו, דַּעַת אַחֶרֶת הָיְתָה לוֹ. אָמְרוּ לוֹ: ״וּמָה הָאֶחָד מְבַקֵּשׁ״ – מָה הָיְתָה דַּעְתּוֹ? אָמַר לָהֶם: ״לִהְיוֹת לוֹ זֶרַע אֱלֹהִים״. וְתַרְגּוּם שֶׁל יוֹנָתָן הֻכְשַׁר בְּעֵינַי, שֶׁלֹּא מָצִינוּ לֹא בַּמִּקְרָא וְלֹא בַּמִּשְׁנָה ׳שְׁאָר׳ מְשַׁמֵּשׁ לְשׁוֹן ׳אַחֵר׳, אֶלָּא בְּמָקוֹם שֶׁאָדָם יָכוֹל לְפָרְשׁוֹ בִּלְשׁוֹן שִׁירַיִם, כְּמוֹ (דניאל ז:ז) ״אָכְלָה וּמַדְּקָה, וּשְׁאָרָא בְּרַגְלַהּ רָפְסָה״, וּבִלְשׁוֹן מִשְׁנָה: ״וּשְׁאָר חַיָּבֵי מִיתוֹת״ – חוּץ מֵאוֹתָן שֶׁפֵּרַשׁ. אֲבָל לְשׁוֹן שֶׁ׳אַחֵר׳ מְשַׁמֵּשׁ, אֵין ׳שְׁאָר׳ מְשַׁמֵּשׁ.\",3,0],[2,129,2,15,\"וְנִשְׁמַרְתֶּם בְּרוּחֲכֶם. וּבְאֵשֶׁת נְעוּרֶיךָ אַל יִבְגֹּד רוּחֶךָ.\",4,0],[2,129,2,16,\"כִּי שָׂנֵא שַׁלַּח. וְרַבּוֹתֵינוּ חֲלוּקִין בָּהּ בְּמַסֶּכֶת גִּטִּין. יֵשׁ מֵהֶם אוֹמְרִים: אִם שָׂנֵאתָ, שַׁלַּח אוֹתָהּ בְּגֵט וְתִנָּשֵׂא לְאַחֵר.\",1,0],[2,129,2,16,\"וְכִסָּה חָמָס עַל לְבוּשׁוֹ. אֲבָל זֹאת – כְּלוּם הוֹגֶנֶת לַעֲשׂוֹת, שֶׁתִּפְרֹס עָלֶיהָ טַלִּיתְךָ לְהַחֲזִיקָהּ לְךָ כְּאִשְׁתְּךָ, וְהֶחָמָס פָּרוּשׂ עַל אוֹתָהּ טַלִּית, שֶׁבְּלִבְּךָ עָלֶיהָ שִׂנְאָה, וְאַתָּה מַקְנִיטָהּ וּמְצַעֲרָהּ תָּמִיד?\",2,0],[2,129,2,17,\"בֶּאֱמׇרְכֶם כָּל עֹשֵׂה רָע וְגוֹ׳. אוֹ אַיֵּה אֱלֹהֵי הַמִּשְׁפָּט. לְפִי שֶׁאַתֶּם רוֹאִים דֶּרֶךְ רְשָׁעִים צָלֵחָה, וְצַדִּיקִים מְעֻנִּים וְנִכְשָׁלִים, אוֹמְרִים אַתֶּם בִּלְבַבְכֶם אַחַת מִשְּׁתֵּי דְרָכִים הַלָּלוּ: ״כָּל עֹשֵׂה רָע טוֹב בְּעֵינָיו״, אוֹ אֵין דִּין וְאֵין דַּיָּן לִפָּרַע. וְכֵן פִּתְרוֹן לְשׁוֹן הַמִּקְרָא: ״כָּל עֹשֵׂה רָע טוֹב בְּעֵינָיו״ – לְכָךְ הוּא מַצְלִיחַ אוֹתָם. ״אוֹ״ אִם אֵין זֹאת, ״אַיֵּה אֱלֹהֵי הַמִּשְׁפָּט״ שֶׁאֵינוֹ נִפְרָע מֵהֶם.\",1,0],[2,129,3,1,\"הִנְנִי שֹׁלֵחַ מַלְאָכִי. לְבָעֵר אֶת הָרְשָׁעִים.\",1,0],[2,129,3,1,\"וּמַלְאַךְ הַבְּרִית. נוֹקֵם נְקַם בְּרִית.\",2,0],[2,129,3,1,\"וּפִנָּה דֶרֶךְ. מִן הָרְשָׁעִים.\",3,0],[2,129,3,1,\"הָאָדוֹן אֲשֶׁר אַתֶּם מְבַקְשִׁים. אֱלֹהֵי הַמִּשְׁפָּט.\",4,0],[2,129,3,2,\"וּמִי מְכַלְכֵּל. וּמִי יָכִיל.\",1,0],[2,129,3,2,\"וּמִי הָעוֹמֵד. שֶׁיּוּכַל לַעֲמֹד.\",2,0],[2,129,3,2,\"וּכְבֹרִית מְכַבְּסִים. כְּבוֹרִית שֶׁל מְכַבְּסִים, שֶׁמַּעֲבִיר אֶת כָּל הַכֶּתֶם, כֵּן יַעֲבִיר כָּל הָרִשְׁעָה. בּוֹרִית – עֵשֶׂב הוּא שֶׁמַּעֲבִיר אֶת הַכֶּתֶם, בְּלַעַ״ז שנייר״א. וּלְשׁוֹן ׳בּוֹרִית׳ – יְדַבֵּר הַמְּצַחְצֵחַ וּמְטַהֵר, כְּמוֹ (תהלים עג:א) ״לְבָרֵי לֵבָב״.\",3,0],[2,129,3,3,\"וְיָשַׁב מְצָרֵף. יִפְנֶה מִכָּל עֲסָקָיו לִהְיוֹת כְּצוֹרֵף הַמְּצָרֵף וּמְטַהֵר כֶּסֶף.\",1,0],[2,129,3,6,\"כִּי אֲנִי ה׳ לֹא שָׁנִיתִי. אַף עַל פִּי שֶׁאֲנִי מַאֲרִיךְ אַפִּי, לֹא שִׁנָּה דַּעְתִּי עָלַי מִבָּרִאשׁוֹנָה, לֶאֱהֹב אֶת הָרַע וְלִשְׂנֹא אֶת הַטּוֹב.\",1,0],[2,129,3,6,\"וְאַתֶּם בְּנֵי יַעֲקֹב. אַף עַל פִּי שֶׁמֵּתִים אַתֶּם בְּרָעַתְכֶם וְלֹא גָבִיתִי מִן הָרְשָׁעִים בַּחַיִּים.\",2,0],[2,129,3,6,\"לֹא כְלִיתֶם. אֵינְכֶם כָּלִים מִלְּפָנַי, וְהִנַּחְתִּי לִי הַנְּפָשׁוֹת לִגְבּוֹת מֵהֶם דִּינִי בְּגֵיהִנֹּם. וְכֵן תִּרְגֵּם יוֹנָתָן: ״וְאַתּוּן דְּבֵית יַעֲקֹב דְּמַאן דְּמִית בְּעָלְמָא הָדֵין דִּינֵיהּ פָּסוֹק״. כְּלוֹמַר, אַתֶּם סְבוּרִים לוֹמַר: דִּינִי בָּטֵל, שֶׁאֵין עוֹד לִפָּרַע מִמֶּנּוּ. וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ: ״לֹא שָׁנִיתִי״ – לֹא הִכֵּיתִי אֶת מִי וְשָׁנִיתִי לוֹ. אֲבָל אֶתְכֶם, הֶעֱמַדְתִּי אַחַר פֻּרְעָנוּת הַרְבֵּה, וְחִצַּי כָּלִים, וְאַתֶּם אֵינְכֶם כָּלִים.\",3,0],[2,129,3,8,\"הֲיִקְבַּע אָדָם. רַבּוֹתֵינוּ דָּרְשׁוּ לְשׁוֹן ׳גְּזֵלָה׳, וּלְשׁוֹן אֲרַמִּי הוּא.\",1,0],[2,129,3,8,\"הַמַּעֲשֵׂר וְהַתְּרוּמָה. שֶׁאַתֶּם גּוֹזְלִים מִן הַכֹּהֲנִים וּמִן הַלְוִיִּם, הִיא גְּזֵלָתִי.\",2,0],[2,129,3,9,\"בַּמְּאֵרָה אַתֶּם נֵאָרִים. עַל עָוֹן זֶה, שֶׁאֲנִי שׁוֹלֵחַ קְלָלָה בְּמַעֲשֵׂה יְדֵיכֶם, וְאַף עַל פִּי כֵן אוֹתִי אַתֶּם קוֹבְעִים.\",1,0],[2,129,3,10,\"וִיהִי טֶרֶף. יְהִי מָזוֹן מָצוּי לְשַׁמָּשַׁי.\",1,0],[2,129,3,11,\"וְגָעַרְתִּי לָכֶם בָּאֹכֵל. בֶּחָסִיל וְגָזָם, הָאוֹכֵל לָכֶם אֶת תְּבוּאַת הַשָּׂדֶה וְהַגֶּפֶן.\",1,0],[2,129,3,12,\"אֶרֶץ חֵפֶץ. אֶרֶץ שֶׁחֶפְצִי בָּהּ.\",1,0],[2,129,3,14,\"שָׁוְא עֲבֹד אֱלֹהִים. עַל חִנָּם נַעַבְדֶנּוּ, כִּי לֹא נְקַבֵּל שָׂכָר.\",1,0],[2,129,3,14,\"קְדֹרַנִּית. בִּשְׁפַל רוּחַ.\",2,0],[2,129,3,15,\"וְעַתָּה אֲנַחְנוּ מְאַשְּׁרִים וְגוֹ׳. אֲנַחְנוּ עֲבַדְנוּהוּ וְשָׁמַרְנוּ מִשְׁמַרְתּוֹ, וְעַתָּה רוֹאִים אֵלּוּ הָרְשָׁעִים מַצְלִיחִים, עַד כִּי מְאַשְּׁרִים אָנוּ אוֹתָם עַל מַעֲשֵׂה רִשְׁעָם.\",1,0],[2,129,3,15,\"גַּם בָּחֲנוּ אֱלֹהִים. לוֹמַר: ״נִרְאֶה מַה יּוּכַל לַעֲשׂוֹת לָנוּ״. וַיִּמָּלֵטוּ מִן הָרָעָה, וְלֹא נִכְשְׁלוּ.\",2,0],[2,129,3,16,\"אָז נִדְבְּרוּ וְגוֹ׳. אֲנִי מֵשִׁיב עַל דִּבְרֵיכֶם: אָז, בַּעֲשׂוֹת הָרְשָׁעִים רִשְׁעָם, וְהַטּוֹבִים הָלְכוּ קְדוֹרַנִּית מִפָּנַי, שֶׁנִּדְבְּרוּ יִרְאֵי ה׳ שֶׁלֹּא לִדָּבֵק בְּמַעֲשֵׂיהֶם הָרָעִים. וַאֲנִי - לֹא נִשְׁכְּחוּ דִבְרֵיכֶם מִלְּפָנַי, וְאַף עַל פִּי שֶׁאֵינִי מְמַהֵר לְהָשִׁיב גְּמוּל, כִּי הִקְשַׁבְתִּי וְשָׁמַעְתִּי, וְצִוִּיתִי לִכְתֹּב לָהֶם סֵפֶר זִכָּרוֹן, וְהָיוּ לִי דִבְרֵיהֶם מְקֻיָּמִים.\",1,0],[2,129,3,17,\"לַיוֹם אֲשֶׁר אֲנִי עֹשֶׂה סְגֻלָּה. אֲשֶׁר אָצַרְתִּי וְהִנַּחְתִּי לְשַׁלֵּם בּוֹ גְּמוּלִי, שָׁם אַרְאֶה אֶתְכֶם מַה בֵּין צַדִּיק לְרָשָׁע.\",1,0],[2,129,3,17,\"סְגֻלָּה. אוֹצָר, איישטו״י בְּלַעַ״ז.\",2,0],[2,129,3,19,\"כִּי הִנֵּה הַיּוֹם בָּא. יוֹם זֶה לְשׁוֹן שֶׁמֶשׁ הוּא, שֶׁכָּךְ אָמְרוּ חֲכָמִים: אֵין גֵּיהִנֹּם לֶעָתִיד לָבֹא, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִיא חַמָּה מִנַּרְתִּיקָהּ, וּרְשָׁעִים נִדּוֹנִים בָּהּ, וְצַדִּיקִים מִתְרַפְּאִין בָּהּ. וְזֶהוּ שֶׁנֶּאֱמַר: ״וְזָרְחָה לָכֶם יִרְאֵי וְגוֹ׳״.\",1,0],[2,129,3,19,\"שֹׁרֶשׁ וְעָנָף. ״בְּרָא וּבַר בְּרָא״.\",2,0],[2,129,3,20,\"וּפִשְׁתֶּם. לְשׁוֹן ׳שֹׁמֶן׳, כְּמוֹ (ירמיהו נ:יא) ״כִּי תָפוּשׁוּ כְּעֶגְלָה דָשָׁה״.\",1,0],[2,129,3,20,\"מַרְבֵּק. הַנִּכְנֶסֶת לָרִבְקָה לְפַטֵּם, קופי״לא בְּלַעַ״ז.\",2,0],[2,129,3,21,\"וְעַסּוֹתֶם. וּכְבַשְׁתֶּם. לְשׁוֹן מִעוּךְ, וְדוֹמֶה לוֹ: ״וְשָׁם עָשׂוּ דַּדֵּי בְּתוּלֵיהֶן״ (יחזקאל כג:ג).\",1,0],[2,129,3,24,\"וְהֵשִׁיב לֵב אָבוֹת. לְהַקָּדוֹשׁ בָּרוּךְ הוּא.\",1,0],[2,129,3,24,\"עַל בָּנִים. עַל יְדֵי בָּנִים. יֹאמַר לַבָּנִים דֶּרֶךְ אַהֲבָה וְרָצוֹן: ״לְכוּ וְדַבְּרוּ אֶל אֲבוֹתֵיכֶם לֶאֱחֹז בְּדַרְכֵי הַמָּקוֹם״. וְכֵן ״וְלֵב בָּנִים עַל אֲבוֹתָם״. כָּךְ שָׁמַעְתִּי מִשְּׁמוֹ שֶׁל רַבִּי מְנַחֵם. וְרַבּוֹתֵינוּ דָּרְשׁוּ בְּמַסֶּכֶת עֵדֻיּוֹת: לָשׂוּם שָׁלוֹם בָּעוֹלָם.\",2,0],[2,130,1,1,\"דְּבַר. הַמּוֹרַשְׁתִּי מֵעִיר מוֹרָשָׁה:\",1,0],[2,130,1,2,\"וִיהִי בָכֶם לְעֵד. שֶׁנִּבֵּאתִי לָכֶם בִּשְׁמוֹ וְהִתְרֵיתִי בָּכֶם:\",1,0],[2,130,1,3,\"יוֹצֵא מִמְּקוֹמוֹ. מִכִּסֵּא רַחֲמִים לְכִסֵּא הַדִּין:\",1,0],[2,130,1,3,\"וְדָרַךְ עַל בָּמֳתֵי אָרֶץ. עַל הָרָמִים וְגַסֵּי הָרוּחַ:\",2,0],[2,130,1,4,\"כַּדּוֹנַג. שַׁעֲוָה:\",1,0],[2,130,1,4,\"מֻגָּרִים בְּמוֹרָד. תִּרְגֵּם יוֹנָתָן: ״דְּאֲשִׁידִין בְּמוֹדְרוֹן״, מֻגָּרִים לְשׁוֹן ׳זִיבַת מַיִם׳ וְכֵן ״עֵינִי נִגְּרָה״ (איכה ג:מט), ״נִגָּרוֹת בְּיוֹם אַפּוֹ״ (איוב כ:כח), ״פָּרַץ נַחַל מֵעִם גָּר״ (שם כח), ״וַיַּגֵּר מִזֶּה״ (תהלים עה:ט):\",2,0],[2,130,1,6,\"לְעִי הַשָּׂדֶה. ״לִיגָרֵי חַקְלָן״. לְשׁוֹן ׳גַּלִּים׳ כְּמוֹ ״יְגַר שָׂהֲדוּתָא״ (בראשית לא:מז):\",1,0],[2,130,1,6,\"וְהִגַּרְתִּי לַגַּי אֲבָנֶיהָ. וְהִסְחַבְתִּי כְּמוֹ הַ״מֻּגָּרִים בְּמוֹרָד״:\",2,0],[2,130,1,7,\"כִּי מֵאֶתְנַן זוֹנָה קִבָּצָה. כָּל הַהוֹן הַזֶּה:\",1,0],[2,130,1,7,\"וְעַד אֶתְנַן זוֹנָה יָשׁוּבוּ. וּלְטִמְיוֹן כִּשְׁאָר אֶתְנַנֵּי זוֹנָה יָשׁוּבוּ כָּל קִבּוּצֶיהָ, וְיוֹנָתָן תִּרְגֵּם: ״וּלְבֵית פָּלְחֵי טָעוּתָא יִתְמַסְּרוּן כָּל קִבּוּצֶיהָ״:\",2,0],[2,130,1,8,\"שׁוֹלָל. מִשְׁתַּגֵּעַ כְּשׁוֹטֶה בְּתִמְהוֹן לֵב, כְּמוֹ ״אֶשְׁתּוֹלְלוּ אַבִּירֵי לֵב״ (תהלים עו), ״וְסָר מֵרָע מִשְׁתּוֹלֵל״ (ישעיהו נט) וְהַתָּי״ו הִיא בָּאָה לְשַׁמֵּשׁ בַּתֵּיבָה בִּלְשׁוֹן מִתְפַּעֵל וְנִתְפַּעֵל, וְכֵן הִלּוּךְ תֵּיבָה שֶׁתְּחִלַּת יְסוֹדָהּ שִׁי״ן אוֹ סָמֶ״ךְ כְּשֶׁבָּאוּ עָלָיו תָּי״ו בִּלְשׁוֹן מִתְפַּעֵל וְנִתְפַּעֵל נִכְנֶסֶת תּוֹךְ הַתֵּיבָה כְּמוֹ ׳מִשְׁתּוֹלֵל׳, אוֹמֵר אֲנִי שֶׁהוּא מִלְּשׁוֹן שׁוֹגֵג כְּמוֹ ״לֹא תַשְׁלֶה אוֹתִי״ (מלכים ב ד:כח), ״עַל הַשַּׁל״ (שמואל ב ו:ז), ״דִּי יֵאמַר שָׁלוּ״ (דניאל ג):\",1,0],[2,130,1,9,\"כִּי אֲנוּשָׁה מַכּוֹתֶיהָ. כִּי חוֹלָה הִיא בְּמַכּוֹתֶיהָ, כְּמוֹ ״וַיֵּאָנַשׁ״ (שמואל ב יב):\",1,0],[2,130,1,10,\"בְּגַת אַל תַּגִּידוּ. פֶּן יִשְׂמְחוּ לָנוּ פְּלִשְׁתִּים:\",1,0],[2,130,1,10,\"בְּבֵית לְעַפְרָה. עָפְרַת אֲבִי הָעֶזְרִי:\",2,0],[2,130,1,10,\"עָפָר הִתְפַּלָּשִׁי. לָשׁוֹן נוֹפֵל עַל הַלָּשׁוֹן וְכֵן יוֹשֶׁבֶת שָׁפִיר עֶרְיָה בֹּשֶׁת וְכֵן לֹא יָצְאָה יוֹשֶׁבֶת צַאֲנָן כֻּלָּם לְפִי שֵׁם הָעִיר לְשׁוֹן הַקִּינָה. הִתְפַּלָּשִׁי הִתְגַּלְגְּלִי. פִּתְרוֹנוֹ לְפִי עִנְיָנוֹ הִתְעַפְּרִי:\",3,0],[2,130,1,11,\"עִבְרִי לָכֶם. הִתְחִיל בִּלְשׁוֹן יְחִידוּת נְקֵבָה כִּמְדַבֵּר אֶל כְּנֵסִיָּה הָעִיר כְּמוֹ שֶׁנֶּאֱמַר יוֹשֶׁבֶת שָׁפִיר כֻּלָּם בְּשֵׁם כְּנֵסִיָּה אַחַת וְאָמַר לָכֶם כִּמְדַבֵּר אֶל הָרַבִּים שֶׁהֲרֵי לָרַבִּים הוּא אוֹמֵר:\",1,0],[2,130,1,11,\"יוֹשֶׁבֶת שָׁפִיר. שֵׁם הָעִיר:\",2,0],[2,130,1,11,\"עֶרְיָה בֹשֶׁת. גְּלוּיָה בֵּית הַבֹּשֶׁת כַּאֲשֶׁר נִקְרֵאת שָׁפִיר שֶׁהוּא שֵׁם נֵפֶל הַיּוֹצֵא מֵרַחְמָהּ שֶׁל אִשָּׁה:\",3,0],[2,130,1,11,\"לֹא יָצְאָה יוֹשֶׁבֶת צַאֲנָן. ״לָא יִפְּקוּן מְשֵׁזְבִין יָתְבֵי צַאֲנָן״:\",4,0],[2,130,1,11,\"מִסְפַּד בֵּית הָאֵצֶל יִקַּח מִכֶּם עֶמְדָּתוֹ. הַמִּסְפֵּד שֶׁגְּרַמְתֶּם לַנִּגְזָלִים שֶׁאַתֶּם גּוֹזְלִים נַחֲלָתוֹ כְּדֵי לְהַגִּישׁ בַּיִת בְּבַיִת שָׂדֶה בְּשָׂדֶה זֶה אֵצֶל זֶה, הוּא יִקַּח מִכֶּם עֲמָדְתוֹ מַעֲמַד הַבִּנְיָנִים שֶׁבְּנִיתֶם וְהֶעֱמַדְתֶּם עַל נַחֲלָתָם, בֵּית הָאֵצֶל איוטמנ״ט בְּלַעַ״ז:\",5,0],[2,130,1,12,\"כִּי חָלָה לְטוֹב. כִּי קִוְּתָה לְטוֹבָה אוֹתָהּ הַיּוֹשֶׁבֶת בְּשַׁלְוָתָהּ וּמַמְרָה עַל פִּי הַנְּבִיאִים:\",1,0],[2,130,1,12,\"כִּי יָרַד רָע. הֲרֵי כִּי זֶה מְשַׁמֵּשׁ בִּלְשׁוֹן אֶלָּא הִיא חָלָה לְטוֹב אֲבָל מִפְּנֵי מְרוּתָהּ יָרַד לָהּ רָע:\",2,0],[2,130,1,13,\"רְתֹם הַמֶּרְכָּבָה לָרֶכֶשׁ. אִסְרוּ הַמֶּרְכָּבָה לָרֶכֶשׁ שֶׁהוּא קַל לָרוּץ וְתִבְרְחוּ. וְאָמַר דּוּנַשׁ שֶׁהוּא לְשׁוֹן עַרְבִי:\",1,0],[2,130,1,14,\"לָכֵן תִּתְּנִי שִׁלּוּחִים עַל מוֹרֶשֶׁת גַּת. עַל אֲשֶׁר תִּתְּנִי שִׁלּוּחִים עַל מַלְכוּת דָּוִד אֲשֶׁר הוֹרִישׁ אֶתְכֶם גַּת כְּעִנְיָן שֶׁנֶּאֱמַר (דברי הימים א יח) ״וַיִּקַּח דָּוִד אֶת גַּת מִיַּד פְּלִשְׁתִּים״, וְאַתֶּם מוֹאֲסִים בּוֹ כְּמוֹ שֶׁנֶּאֱמַר (ישעיהו ח) ״יַעַן אֲשֶׁר מָאַס הָעָם הַזֶּה אֶת מֵי הַשִּׁלֹחַ וְגוֹמֵר״, לְפִיכָךְ בָּתֵּי אַכְזִיב שֶׁהָיְתָה מֵאֶרֶץ יְהוּדָה וְנִמְשְׁכוּ אַחַר פֶּקַח בֶּן רְמַלְיָהוּ, סוֹפָן לִהְיוֹת לְאַכְזָב לְמַלְכֵי יִשְׂרָאֵל שֶׁיֵּהָרֵג פֶּקַח בֶּן רְמַלְיָהוּ וְיִכְזְבוּ הַנִּסְמָכִים עָלָיו. וּבִימֵי אָחָז נִתְנַבֵּאת נְבוּאָה זוֹ:\",1,0],[2,130,1,14,\"לָכֵן תִּתְּנִי שִׁלּוּחִים. פֵּרוּשׁ לָכֵן כְּמוֹ עַל אֲשֶׁר כְּמוֹ (ישעיהו יז) ״עַל כֵּן תִּטְּעִי נִטְעֵי נַעֲמָנִים״ עַל אֲשֶׁר נְטַעְתִּיךְ נִטְעֵי נַעֲמָנִים וְאַתְּ נֶהְפַּכְתְּ לִזְמוֹרוֹת זָר:\",2,0],[2,130,1,14,\"בָּתֵּי אַכְזִיב לְאַכְזָב. לָשׁוֹן נוֹפֵל עַל הַלָּשׁוֹן מֵאַגָּדַת חֵלֶק לָמַדְתִּי מִדְרַשׁ מִקְרָא זֶה כָּךְ:\",3,0],[2,130,1,15,\"עוֹד הַיּוֹרֵשׁ אָבִיא לָךְ. אוֹיְבִים שֶׁיּוֹרִישׁוּ אוֹתָךְ אֶת הַיּוֹשֶׁבֶת בְּמָרֵשָׁה, יוֹרֵשׁ לְמָרֵשָׁה לָשׁוֹן נוֹפֵל עַל הַלָּשׁוֹן:\",1,0],[2,130,1,15,\"עַד עֲדֻלָּם. שֶׁהוּא לְפָנִים מִן הַגְּבוּל יָסוֹג אָחוֹר וְיָבֹא כְּבוֹד יִשְׂרָאֵל שֶׁיִּכְבְּשׁוּ הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת מִגְּבוּלָם עַד עֲדֻלָּם כֵּן תִּרְגֵּם יוֹנָתָן: ״עַד עֲדֻלָּם יֵיתוּן בִּתְחוּם אַרְעָא דְיִשְׂרָאֵל״. וּמִדְרַשׁ אַגָּדָה שְׁמַעְתִּיו מִשְּׁמוֹ שֶׁל רַבִּי מְנַחֵם עוֹד הַיּוֹרֵשׁ אָבִיא לָךְ רְאוּיִים הָיוּ בְּנֵי עֵילָם לִירַשׁ אֶת אֶרֶץ יִשְׂרָאֵל שֶׁהוּא הָיָה בְּכוֹר לִבְנֵי שֵׁם, וּבִשְׁבִיל אַהֲבַת אֲבוֹתֵיכֶם הֲסִבּוֹתִיהָ לִבְנֵי אַרְפַּכְשַׁד, עַתָּה אָבִיא אֶת כַּשְׂדִּים וְאֶת בְּנֵי עֵילָם עֲלֵיהֶם:\",2,0],[2,130,1,16,\"קָרְחִי. רֹאשֵׁךְ:\",1,0],[2,130,1,16,\"וָגֹזִּי. שְׂעָרֵךְ כְּמוֹ (איוב א) ״וַיָּגָז אֶת רֹאשׁוֹ״ לְשׁוֹן תְּלִישַׁת שֵׂעָר:\",2,0],[2,130,1,16,\"כַּנֶּשֶׁר. כְּתַרְגּוּמוֹ ״כְּנִשְׁרָא דְּנָתְרוּ גַדְפּוֹהִי״. דֶּרֶךְ הַנֶּשֶׁר לִמְרֹט רוֹב כְּנָפָיו:\",3,0],[2,130,2,1,\"וּפֹעֲלֵי רָע עַל מִשְׁכְּבוֹתָם. כָּל הַלַּיְלָה גּוֹמְרִים בְּלִבָּם אֵיךְ יַעֲשׂוּ הָרָעָה לַבֹּקֶר:\",1,0],[2,130,2,2,\"וּבָתִּים וְנָשָׂאוּ. מוּסָב עַל וְחָמְדוּ חוֹמְדִים בָּתִּים:\",1,0],[2,130,2,2,\"וְנָשָׂאוּ. כְּמוֹ ׳וְלָקְחוּ׳:\",2,0],[2,130,2,3,\"וְלֹא תֵלְכוּ רוֹמָה. ״וְלָא תַּהֲכוּן בְּקוֹמָה זְקוּפָה״:\",1,0],[2,130,2,4,\"וְנָהָה נְהִי נִהְיָה. וְנָהָה לְשׁוֹן עָתִיד, כְּמוֹ וְעָשָׂה וּפָנָה. וְנָהָה הַמְּקוֹנֵן וְאָמַר נְהִי נִהְיָה בָּעוֹלָם וּמַהוּ הַנְּהִי אֲשֶׁר נִהְיָה אָמַר שָׁדוֹד נְשַׁדֻּנוּ אוֹיְבֵינוּ שְׁדָדוּנוּ. וְלָשׁוֹן נְשַׁדֻּנוּ שֶׁכָּתַב בּוֹ נוּ״ן בִּתְחִלָּה וְלֹא כָתַב שַׁדּוּנוּ, מִפְּנֵי שֶׁבָּא לְשַׁמֵּשׁ שְׁנֵי לְשׁוֹנוֹת, לְשׁוֹן נִפְעַלְנוּ וְלָשׁוֹן פְּעַלְנוּ. אִלּוּ כָּתַב נִשְׁדַּנוּ הָיָה הַלָּשׁוֹן מוּסָב עַל הַנִּשְׁדָּדִים וְלֹא אֶל הַשּׁוֹדְדִים, וְאִם כָּתַב שַׁדּוּנוּ הָיָה מוּסָב אֶל הַשּׁוֹדְדִים וְלֹא לַנִּשְׁדָּדִים, עַכְשָׁיו מוּסָב לִשְׁנֵיהֶם נְתָנָנוּ בְּיַד אֲשֶׁר שַׁדּוּנוּ וּבְלַעַ״ז שומי״ר דימשטיור״א נשו״ט. דָּבָר אַחֵר נְשַׁדֻּנוּ אֲנַחְנוּ גָּרַמְנוּ לְעַצְמֵנוּ שֶׁשְּׁדָדוּנוּ:\",1,0],[2,130,2,4,\"חֵלֶק עַמִּי יָמִיר. נַחֲלַת חֵלֶק עַמִּי נֶחְלַף לְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:\",2,0],[2,130,2,4,\"אֵיךְ יָמִישׁ לִי לְשׁוֹבֵב שָׂדֵינוּ יְחַלֵּק. אֵיךְ יָסוּר אֵלַי עוֹד לְהָשִׁיב לָנוּ שְׂדוֹתֵינוּ אֲשֶׁר יְחַלֵּק אוֹתָם הָעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת הַזֶּה לוֹ, אֵיךְ אֶפְשָׁר לְשׁוֹבְבָם עוֹד לִי. כָּל אֵלֶּה דִּבְרֵי הַמְּקוֹנֵן וְנוֹשֵׂא הַמָּשָׁל. אֵיךְ יָמִישׁ לִי קומ״א שדיטורנר״א אמו״י כְּמוֹ סוּרָה אֵלַי וַיָּסַר אֵלָיו:\",3,0],[2,130,2,5,\"מַשְׁלִיךְ חֶבֶל. חוֹלֵק נַחֲלָה, שֶׁכֵּן דֶּרֶךְ לְחַלֵּק נַחֲלָה בְּחֶבֶל הַמִּדָּה:\",1,0],[2,130,2,6,\"אַל תַּטִּפוּ יַטִּיפוּן. אַל תִּנָּבְאוּ לְהוֹכִיחָם לָכֶם הַנְּבִיאִים אֲנִי אוֹמֵר אֲשֶׁר תַּטִּיפוּ תָּמִיד:\",1,0],[2,130,2,6,\"לֹא יִסַּג כְּלִמּוֹת. פֶּן יַשִּׂיגוּן אֶתְכֶם כְּלִימוֹת מֵאִתָּם כְּעִנְיָן שֶׁנֶּאֱמַר (משלי ט:ח) ״אַל תּוֹכַח לֵץ״, כָּל טִיף לְשׁוֹן ׳נְבוּאָה׳ כְּמוֹ (עמוס ז:טז) ״וְלֹא תַטִּיף עַל בֵּית יִשְׂחָק״, (יחזקאל כא:ב) ״וְהַטֵּף אֶל דָּרוֹם״:\",2,0],[2,130,2,7,\"הֶאָמוּר בֵּית יַעֲקֹב. הֲזֹאת יֹאמְרוּ בֵּית יַעֲקֹב כְּשֶׁשּׁוֹמְעִים אֶת הָרָעָה אֲשֶׁר נְבִיאַי מִתְנַבְּאִים לָהֶם:\",1,0],[2,130,2,7,\"הֲקָצַר רוּחַ ה׳. שֶׁמָּא אֵין יְכֹלֶת עַתָּה לְפָנָיו לְהֵיטִיב וְאֵין רוּחוֹ רְחָבָה עָלָיו לְטוֹב כַּאֲשֶׁר הָיְתָה בַּיָּמִים הָרִאשׁוֹנִים:\",2,0],[2,130,2,7,\"אִם אֵלֶּה מַעֲלָלָיו. כְּלוֹמַר לְהָרַע:\",3,0],[2,130,2,7,\"הֲלֹא דְבָרַי יֵיטִיבוּ עִם הַיָּשָׁר הוֹלֵךְ. אֲנִי לֹא קָצְרָה רוּחִי וְלֹא אֵלֶּה מַעֲלָלַי זוּלָתִי לָרְשָׁעִים אַךְ אֶת הַיָּשָׁר הוֹלֵךְ הֵיטֵב אֵיטִיב לוֹ:\",4,0],[2,130,2,8,\"וְאֶתְמוּל עַמִּי לְאוֹיֵב יְקוֹמֵם. הַמִּקְרָא מְחֻבָּר לְשֶׁל מַעְלָה הֵימֶנּוּ אֲנִי טוֹב וּמֵטִיב אֲנִי וְאֶת הַדָּבָר אֲשֶׁר לְמוּלוֹ וּבַעֲבוּרוֹ עַמִּי אוֹתוֹ יְקוֹמֵם לְאוֹיֵב לוֹ:\",1,0],[2,130,2,8,\"מִמּוּל שַׂלְמָה אֶדֶר תַּפְשִׁיטוּן. כְּנֶגֶד אֲשֶׁר אַתֶּם גּוֹזְלִים הַשַּׂלְמָה וּלְבוּשׁ תִּפְאֶרֶת וּמַפְשִׁיטִים מֵעַל כָּל הָעוֹבְרִים עֲלֵיכֶם בַּדֶּרֶךְ:\",2,0],[2,130,2,8,\"מֵעוֹבְרִים בֶּטַח שׁוּבֵי מִלְחָמָה. מִמַּה שֶׁהָיוּ סְבוּרִין לִהְיוֹת עוֹבְרִין בֶּטַח, הֵם נֶהֶפְכוּ לִהְיוֹת שׁוּבֵי מִלְחָמָה כִּבְנֵי אָדָם הַשָּׁבִים מִן הַמִּלְחָמָה חַסְרֵי מִבְּגָדִים וּמָזוֹן שֶׁלָּקְחוּ אוֹיְבֵיהֶם מַה שֶּׁעֲלֵיהֶם, שׁוּבֵי כְּמוֹ (ירמיהו ב:כא) ״סוּרֵי הַגֶּפֶן נָכְרִיָּה״ (צפניה ג) ״נוּגֵי מִמּוֹעֵד״:\",3,0],[2,130,2,9,\"נְשֵׁי עַמִּי תְּגָרְשׁוּן מִבֵּית תַּעֲנֻגֶיהָ. שֶׁאַתֶּם הוֹרְגִים אֶת בַּעֲלֵיהֶן וְהֵן יוֹשְׁבוֹת אַלְמָנוֹת, אוֹ לְפִי שֶׁאַתֶּם נוֹטְלִין אֶת מָמוֹן בַּעֲלֵיהֶם וְהֵם יוֹשְׁבִים וּמְצִירִים וְאֵין מְשַׂמְּחִין אֶת נְשׁוֹתֵיהֶן:\",1,0],[2,130,2,9,\"תִּקְחוּ הֲדָרִי. הֲדַר הוֹד וְעֹשֶׁר שֶׁנָּתַתִּי לָהֶם:\",2,0],[2,130,2,10,\"קוּמוּ וּלְכוּ כִּי לֹא זֹאת הַמְּנוּחָה. קוּמוּ וּגְלוּ מִן הָאָרֶץ כִּי לֹא כְּדֶרֶךְ זוֹ נְתַתִּיהָ לָכֶם לִמְנוּחָה:\",1,0],[2,130,2,10,\"בַּעֲבוּר טָמְאָה תְּחַבֵּל וְחֶבֶל נִמְרָץ. כִּי לְמַעַן טַמֵּא אוֹתָהּ הִיא עוֹשָׂה חֲבוּרַת חֶבְלֵי רְשָׁעִים, תְּחַבֵּל לְשׁוֹן ׳אֲגֻדּוֹת׳ כְּמוֹ (שמואל א י:ה) ״חֶבֶל נְבִיאִים״ (תהלים קיט:סא) ״חֶבְלֵי רְשָׁעִים״ וְכֵן תִּרְגֵּם יוֹנָתָן: ״מִסְתַּיְּעִין עֲלָהּ״, לְשׁוֹן ׳סִיעָה׳:\",2,0],[2,130,2,10,\"וְחֶבֶל נִמְרָץ. וּבְעֵת אֲגֻדָּתָם כְּבָר נוֹעֲצוּ בֵּינֵיהֶם וּפֵרְשׁוּ לָמָּה הֵם מִתְחַבְּרִים:\",3,0],[2,130,2,10,\"נִמְרָץ. דָּבָר מְפֹרָשׁ בָּאֵר הֵיטֵב כְּמוֹ (איוב ו:כה) ״מַה נִּמְרְצוּ אִמְרֵי״ ״מַה יַּמְרִיצְךָ״ (שם טז) ״קְלָלָה נִמְרֶצֶת״ (מלכים א ב):\",4,0],[2,130,2,11,\"לוּ אִישׁ הוֹלֵךְ רוּחַ. לוּ מוֹצְאִים אִישׁ הוֹלֵךְ רוּחַ אִישׁ שֶׁקֶר מִתְנַבֵּא לָהֶם שֶׁיִּשְׁתַּכְּרוּ בְּיַיִן וּבְשֵׁכָר הוּא יִהְיֶה נָבִיא מְקֻבָּל לָעָם הַזֶּה:\",1,0],[2,130,2,12,\"אָסֹף אֶאֱסֹף. עוֹד יָמִים בָּאִים וַאֲקַבֵּץ אֶתְכֶם:\",1,0],[2,130,2,12,\"כְּצֹאן בָּצְרָה. כְּצֹאן רַבָּה הַנְּתוּנָה בְּמִבְצְרֵי גִּדְרוֹת צֹאן:\",2,0],[2,130,2,12,\"בְּתוֹךְ הַדָּבְרוֹ. תִּרְגֵּם יוֹנָתָן: ״כְּעֶדְרָא בְּגוֹ דִּירָא״, מָקוֹם שֶׁהוּא מִתְנַהֵג שָׁם וְכֵן (ישעיה ה) ״וְרָעוּ כְבָשִׂים כְּדָבְרָם״:\",3,0],[2,130,2,12,\"תְּהִימֶנָה מֵאָדָם. תִּהְיֶינָה הֶעָרִים הוֹמִיּוֹת מֵרֹב אָדָם אֲשֶׁר בְּקִרְבָּהּ:\",4,0],[2,130,2,13,\"עָלָה הַפֹּרֵץ. מוֹשִׁיעָם הַפּוֹרֵץ גִּדְרַת סִירִים וּמְסוּכוֹת חֲדָקִים לְיַשֵּׁר לִפְנֵיהֶם הַדֶּרֶךְ:\",1,0],[2,130,3,2,\"גֹּזְלֵי עוֹרָם. שֶׁל בֵּית יִשְׂרָאֵל שֶׁהֵם רָאשִׁים וּקְצִינִים עֲלֵיהֶם כְּמוֹ שֶׁאָמַר רָאשֵׁי בֵּית יַעֲקֹב וּקְצִינֵי בֵּית יִשְׂרָאֵל:\",1,0],[2,130,3,3,\"שְׁאֵר עַמִּי. בְּשַׂר עַמִּי:\",1,0],[2,130,3,3,\"וְאֶת עַצְמוֹתֵיהֶם פִּצֵּחוּ. פָּתְחוּ לְהוֹצִיא הַמֹּחַ, כְּמוֹ (שם יד) ״פִּצְחוּ רִנָּה״ פִּתְחוּ פֶּה בְּרִנָּה:\",2,0],[2,130,3,3,\"וּפָרְשׂוּ כַּאֲשֶׁר בַּסִּיר. וּמְשַׁבְּרִים הָאֵבָרִים כַּאֲשֶׁר יִשְׁבְּרוּ הַנְּתָחִים הַנִּתָּנִים בַּסִּיר לְבַשֵּׁל. וּפָרְשׂוּ לְשׁוֹן ׳שֶׁבֶר׳ כְּמוֹ ״פָּרֹס לָרָעֵב״ (ישעיה נח) ״וְלֹא יִפְרְסוּ לָהֶם״ (ירמיה טז) ״פֵּרְשָׂה צִיּוֹן״ (איכה א):\",3,0],[2,130,3,3,\"קַלָּחַת. קלדיי״רא בְּלַעַ״ז:\",4,0],[2,130,3,4,\"אָז יִזְעֲקוּ אֶל ה׳. אָז בְּבֹא אוֹתוֹ הָעֵת הָאָמוּר לְמַעְלָה אָסֹף אֶאֱסֹף יַעֲקֹב יִזְעֲקוּ אֶל ה׳ לְהֵיטִיב לָהֶם בִּרְצוֹן עַמּוֹ וְשִׂמְחַת גּוֹיוֹ וְלֹא יַעֲנֶה אוֹתָם:\",1,0],[2,130,3,5,\"הַנֹּשְׁכִים בְּשִׁנֵּיהֶם. וְאוֹכְלִים בְּשַׂר בְּהֵמוֹת פְּטוּמוֹת הַמַּאֲכִילִים אוֹתָם עַמִּי הַטּוֹעִים אַחֲרֵיהֶם:\",1,0],[2,130,3,5,\"וְקָרְאוּ שָׁלוֹם. וְכַאֲשֶׁר יַאֲכִילוּ יִקְרְאוּ וְיִתְנַבְּאוּ לָהֶם שָׁלוֹם:\",2,0],[2,130,3,5,\"וְקִדְּשׁוּ עָלָיו מִלְחָמָה. וְהִזְמִינוּ עָלָיו לְמִלְחָמָה:\",3,0],[2,130,3,7,\"מַעֲנֵה אֱלֹהִים. מַעֲנֵה נָקוּד קָמַץ (רוֹצֶה לוֹמַר צֵירֵי), לְפִי שֶׁהוּא דָבוּק אֶל הַשֵּׁם:\",1,0],[2,130,3,12,\"עִיִּין. דְּגוֹרִין:\",1,0],[2,130,4,1,\"וְנָהֲרוּ. וְנִקְבְּצוּ שָׁם יַחַד כַּנְּהָרוֹת הַהוֹלְכִים אֶל הַיָּם:\",1,0],[2,130,4,3,\"וְשָׁפַט. מִשְׁפָּט זֶה לְשׁוֹן ׳תּוֹכָחָה׳ הוּא דשרימנ״ט בְּלַעַ״ז:\",1,0],[2,130,4,4,\"כִּי פִי ה׳ צְבָאוֹת דִּבֵּר. וְהֵיכָן דִּבֵּר ״וְנָתַתִּי שָׁלוֹם בָּאָרֶץ״ (ויקרא כו:ו):\",1,0],[2,130,4,5,\"יֵלְכוּ אִישׁ בְּשֵׁם אֱלֹהָיו. יֵלְכוּ לַאֲבַדּוֹן עַל שֶׁעָבְדוּ עֲבוֹדָה זָרָה כֵּן תִּרְגֵּם יוֹנָתָן:\",1,0],[2,130,4,6,\"אֹסְפָה הַצֹּלֵעָה. ״אַכְנִישׁ מְטַלְטְלַיָּא״ וְכֵן תַּרְגּוּם יוֹנָתָן, וְלִי נִרְאֶה לְשׁוֹן ׳מַרְפֵּא׳ כְּמוֹ ״וַאֲסַפְתּוֹ מִצָּרַעְתּוֹ״ (מלכים ב ה):\",1,0],[2,130,4,6,\"וַאֲשֶׁר הֲרֵעוֹתִי. וְאוֹתָם שֶׁהֲרֵעוֹתִי לָהֶם בַּעֲוֹנָם:\",2,0],[2,130,4,8,\"וְאַתָּה מִגְדַּל עֵדֶר. תִּרְגֵּם יוֹנָתָן: ״וְאַתְּ מְשִׁיחָא דְיִשְׂרָאֵל דְּטָמִיר מִן קֳדָם חוֹבֵי כְּנִישְׁתָּא דְצִיּוֹן״. פֵּרוּשׁ מִגְדַּל לְשׁוֹן ׳מָעוֹז׳ וְתַרְגּוּם עֵדֶר ׳כְּנֶסֶת יִשְׂרָאֵל׳ וְתִרְגֵּם עֹפֶל לְשׁוֹן ׳אֹפֶל׳. וְיֵשׁ לְפָרֵשׁ מִגְדַּל עֵדֶר בֵּית הַמִּקְדָּשׁ וְעֹפֶל לְשׁוֹן ׳מִגְדַּל עוֹז׳ וְכֵן ״עוֹפֶל וָבַחַן״ (ישעיה לב):\",1,0],[2,130,4,8,\"עָדֶיךָ תֵּאתֶה. שְׁאֵרִית הַצּוֹלֵעָה וְהַנַּהֲלָאָה כֻּלָּם יִקָּבְצוּ אֵלֶיךָ:\",2,0],[2,130,4,8,\"וּבָאָה הַמֶּמְשָׁלָה הָרִאשׁוֹנָה. תָּבֹא הַמֶּמְשָׁלָה שְׁלֵמָה כֻּלָּהּ אֶל בֵּית דָּוִד בִּירוּשָׁלַיִם כַּאֲשֶׁר הָיְתָה בַּתְּחִלָּה עַד שֶׁלֹּא נֶחְלְקָה. וּמַה הִיא הַמֶּמְשָׁלָה הָרִאשׁוֹנָה הַמַּמְלָכָה לְבַת יְרוּשָׁלָיִם:\",3,0],[2,130,4,9,\"עַתָּה. שֶׁאַתְּ מוֹרֶדֶת בִּי:\",1,0],[2,130,4,9,\"לָמָּה תָּרִיעִי רֵעַ. שִׁיתִי לִבֵּךְ לָמָּה אַתְּ צְרִיכָה לְבַקֵּשׁ רֵעִים וַאֲהוּבִים מַלְכֵי מִצְרַיִם וּמַלְכֵי אַשּׁוּר לַעֲזֹר:\",2,0],[2,130,4,10,\"חוּלִי. לְשׁוֹן ׳חַלְחָלָה׳ כְּמוֹ (כאן) ״כִּי הֶחֱזִיקֵךְ חִיל״, וְהַלָּשׁוֹן נוֹפֵל עַל יוֹלֶדֶת:\",1,0],[2,130,4,10,\"וָגֹחִי. כִּרְעִי וּשְׁחִי עַל גְּחוֹנֵךְ. וְכֵן בִּלְשׁוֹן מִשְׁנָה ״כּוֹתֶל הַגּוֹחֶה לִרְשׁוּת הָרַבִּים״:\",2,0],[2,130,4,10,\"תֵּצְאִי מִקִּרְיָה. מִירוּשָׁלַיִם לָלֶכֶת בַּגּוֹלָה:\",3,0],[2,130,4,10,\"וְשָׁכַנְתְּ בַּשָּׂדֶה. תְּהִי שְׁכִינָתֵךְ חֲרוּשָׁה כַּשָּׂדֶה:\",4,0],[2,130,4,11,\"הָאוֹמְרִים תֶּחֱנָף. עַתָּה תִּתְחַיֵּב צִיּוֹן בְּחַטֹּאתֶיהָ וְיִפָּקֵד עָלֶיהָ עֲוֹנָהּ:\",1,0],[2,130,4,11,\"וְתַחַז בְּצִיּוֹן עֵינֵינוּ. וְתִרְאֶינָה בָּהּ עֵינֵינוּ מַה שֶּׁאִוִּינוּ לִרְאוֹת בָּהּ:\",2,0],[2,130,4,12,\"כִּי קִבְּצָם כֶּעָמִיר גֹּרְנָה. וְסוֹפוֹ לְקַבְּצָם אֶל עֵמֶק יְהוֹשָׁפָט וּסְבִיבוֹת יְרוּשָׁלַיִם לְמִלְחָמָה, כְּמוֹ שֶׁמְּקַבְּצִין עָמִיר כְּדֵי לְדוּשָׁם שָׁם, אַף הֵם חֵיל גּוֹג וּמָגוֹג לְרָעָתָם נֶאֶסְפוּ. וְיֹאמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לִכְנֶסֶת יִשְׂרָאֵל קוּמִי וָדוֹשִׁי בַת צִיּוֹן:\",1,0],[2,130,4,13,\"וְהַחֲרַמְתִּי. לְשׁוֹן ׳הֶקְדֵּשׁ׳:\",1,0],[2,130,4,13,\"בִּצְעָם. מַה שֶּׁכִּנְּסוּ מִגְּזֵלָה וְחָמָס:\",2,0],[2,130,4,13,\"וְחֵילָם. ״וְנִכְסֵיהוֹן״:\",3,0],[2,130,4,14,\"עַתָּה תִּתְגּוֹדְדִי בַת גְּדוּד. עַתָּה בְּעֵת גְּזֵרָתָהּ הָרָעָה עַל הֶעָוֹן כִּי גָבַר, תִּתְגּוֹדְדִי בַּת גְּדוּד בַּת כַּשְׂדִּים, קִבְצִי גְדוּדִין כִּי עַתָּה הוּא אֲשֶׁר תִּצְלְחִי בַּגְּדוּד אֲשֶׁר שָׂם מָצוֹר עָלֵינוּ:\",1,0],[2,130,4,14,\"בַּשֵּׁבֶט יַכּוּ עַל הַלֶּחִי. מִי גָרַם לָךְ לְהַצְלִיחַ אֶת אֲשֶׁר יִשְׂרָאֵל מַלְעִיבִים עַל נְבִיאֵיהֶם וְשׁוֹפְטֵיהֶם וּמַכִּים אוֹתָם עַל הַלֶּחִי. כָּךְ הָיוּ עוֹשִׂים, וְכֵן מָצִינוּ בִּפְסִיקְתָּא וְכֵן יְשַׁעְיָה הוּא אוֹמֵר (ישעיהו נ:ו) ״גֵּוִי נָתַתִּי לְמַכִּים״:\",2,0],[2,130,5,1,\"וְאַתָּה בֵּית לֶחֶם אֶפְרָתָה. שֶׁיָּצָא דָוִד מִשָּׁם שֶׁנֶּאֱמַר בּוֹ (שמואל א יז:נח) ״עַבְדְּךָ יִשַׁי בֵּית הַלַּחְמִי״ וּבֵית לֶחֶם קָרוּי אֶפְרָת שֶׁנֶּאֱמַר (בראשית מח:ז) ״בְּדֶרֶךְ אֶפְרָת הִיא בֵּית לָחֶם״:\",1,0],[2,130,5,1,\"צָעִיר לִהְיוֹת בְּאַלְפֵי יְהוּדָה. רָאוּי הָיִיתָ לִהְיוֹת צָעִיר בְּמִשְׁפְּחוֹת יְהוּדָה מִפְּנֵי פְּסֹלֶת רוּת הַמּוֹאֲבִיָּה שֶׁבָּךְ:\",2,0],[2,130,5,1,\"מִמְּךָ לִי יֵצֵא. מָשִׁיחַ בֶּן דָּוִד וְכֵן הוּא אוֹמֵר (תהלים קיח:כב) ״אֶבֶן מָאֲסוּ הַבּוֹנִים״:\",3,0],[2,130,5,1,\"וּמוֹצָאֹתָיו מִקֶּדֶם. ״לִפְנֵי שֶׁמֶשׁ יִנּוֹן שְׁמוֹ״ (שם):\",4,0],[2,130,5,2,\"לָכֵן יִתְּנֵם עַד עֵת יוֹלֵדָה. יִתְּנֵם בְּיַד אוֹיְבֵיהֶם עַד בֹּא הָעֵת אֲשֶׁר חָלָה וְיָלְדָה צִיּוֹן אֶת בָּנֶיהָ, צִיּוֹן אֲשֶׁר הֶחֱזִיקָה עַתָּה חִיל כַּיּוֹלֵדָה וְעַכְשָׁיו הִיא קְרוּיָה יוֹלֶדֶת. וְרַבּוֹתֵינוּ אָמְרוּ מִכָּאן אֵין בֶּן דָּוִד בָּא עַד שֶׁתִּפְשׁוֹט הַמַּלְכוּת הָרְשָׁעָה תִּשְׁעָה חֳדָשִׁים עַל כָּל הָעוֹלָם כֻּלּוֹ, אַךְ לְפִי פְשׁוּטוֹ זֶהוּ הַצָּעָה שֶׁפֵּרַשְׁתִּי:\",1,0],[2,130,5,2,\"וְיֶתֶר אֶחָיו. שֶׁל מֶלֶךְ יְהוּדָה כְּלוֹמַר שְׁאָר שֵׁבֶט יְהוּדָה:\",2,0],[2,130,5,2,\"יְשׁוּבוּן עַל בֵּית יִשְׂרָאֵל. יִתְחַבְּרוּ עִם שְׁאָר הַשְּׁבָטִים וְהָיוּ לְמַמְלָכָה אַחַת וְלֹא יֵחָצוּ עוֹד לִשְׁתֵּי מַמְלָכוֹת:\",3,0],[2,130,5,3,\"וְרָעָה. וּפִרְנֵס אֶת יִשְׂרָאֵל:\",1,0],[2,130,5,3,\"וְיָשָׁבוּ. מִן הַגָּלֻיּוֹת:\",2,0],[2,130,5,3,\"כִּי עַתָּה יִגְדַּל. מַלְכָּם:\",3,0],[2,130,5,3,\"עַד אַפְסֵי אָרֶץ. וֶהֱבִיאוּם מִנְחָה אֵלָיו בַּסּוּסִים וּבָרֶכֶב:\",4,0],[2,130,5,4,\"וְהָיָה זֶה שָׁלוֹם. גָּמוּר וְקָבוּעַ בְּאֵין הֶפְסֵק עוֹד וְלֹא יִדְמֶה לִשְׁאָר הַתְּשׁוּעוֹת שֶׁהָיוּ צָרוֹת אַחֲרֵיהֶן:\",1,0],[2,130,5,4,\"אַשּׁוּר כִּי יָבֹא. הֲרֵי כִּי מְשַׁמֵּשׁ בִּלְשׁוֹן ׳אִם׳, אִם יָבֹא בְּאַרְצֵנוּ כַּאֲשֶׁר בָּא עַתָּה:\",2,0],[2,130,5,4,\"וַהֲקֵמֹנוּ עָלָיו שִׁבְעָה רֹעִים. שִׁבְעָה וּשְׁמוֹנָה, רַבּוֹתֵינוּ פֵּרְשׁוּ שְׁמוֹתֵיהֶן בְּמַסֶּכֶת סֻכָּה וְאֵינִי יוֹדֵעַ מֵהֵיכָן לָמְדוּ:\",3,0],[2,130,5,5,\"וְרָעוּ אֶת אֶרֶץ אַשּׁוּר. וְיְרוֹצְצוּ כְּמוֹ (שם ב) ״תְּרֹעֵם בְּשֵׁבֶט בַּרְזֶל״:\",1,0],[2,130,5,5,\"וְאֶת אֶרֶץ נִמְרֹד. הִיא בָּבֶל:\",2,0],[2,130,5,5,\"בִּפְתָחֶיהָ. בְּשַׁעֲרֵי מְדִינוֹתֶיהָ:\",3,0],[2,130,5,6,\"כְּטַל מֵאֵת ה׳. שֶׁאֵין בָּא לָעוֹלָם עַל יְדֵי אָדָם וְלֹא יְבַקְשׁוּ פְּנֵי אָדָם עָלָיו, כָּךְ לֹא יְקַוֶּה יִשְׂרָאֵל לְעֶזְרַת אִישׁ כִּי אִם בַּה׳:\",1,0],[2,130,5,7,\"כְּאַרְיֵה בְּבַהֲמוֹת יַעַר. כָּךְ יְהִי מַלְכָּם שַׁלִּיט בַּכֹּל:\",1,0],[2,130,5,7,\"וְרָמַס וְטָרַף. רָמַס הִיא דְרִיסַת הָאֲרִי כְּשֶׁהוּא רָעֵב וְאוֹכְלוֹ בִּמְקוֹמוֹ, וְטָרַף הוּא כְּשֶׁנּוֹשֵׂא אֶת הַטֶּרֶף לִמְעוֹנוֹתָיו בִּשְׁבִיל גּוּרוֹתָיו וּלְבִיאוֹתָיו:\",2,0],[2,130,5,9,\"וְהִכְרַתִּי סוּסֶיךָ. הִיא עֶזְרַת מִצְרַיִם שֶׁאַתֶּם נִשְׁעָנִים עֲלֵיהֶם לְהַמְצִיאֲכֶם סוּסִים:\",1,0],[2,130,5,10,\"וְהִכְרַתִּי עָרֵי אַרְצֶךָ. וְלֹא תִצְטָרֵךְ לְעָרֵי מִבְצָר:\",1,0],[2,130,5,13,\"וְהִשְׁמַדְתִּי עָרֶיךָ. ״וַאֲשֵׁיצֵי בַּעֲלֵי דְבָבָךְ״, וְכֵן (ישעיהו יד:כא) ״וּמָלְאוּ פְנֵי תֵבֵל עָרִים״ וְכֵן (שמואל א כח) ״וַיְהִי עָרֶךָ״:\",1,0],[2,130,6,1,\"אֶת הֶהָרִים. אֶת הָאָבוֹת.\",1,0],[2,130,6,1,\"הַגְּבָעוֹת. הָאִמָּהוֹת.\",2,0],[2,130,6,3,\"מֶה עָשִׂיתִי לְךָ. תֵּן לִבְּךָ לְהַכִּיר מַה טּוֹב עָשִׂיתִי לְךָ.\",1,0],[2,130,6,3,\"וּמָה הֶלְאֵתִיךָ. בַּעֲבוֹדָתִי.\",2,0],[2,130,6,3,\"עֲנֵה בִי. הָעֵד בִּי.\",3,0],[2,130,6,4,\"כִּי הֶעֱלִיתִיךָ. אַף עַל פִּי שֶׁעָשִׂיתִי לְךָ כָּל הַטּוֹבָה הַזֹּאת, לֹא הֶלְאֵתִיךָ בַּעֲבוֹדָה גְדוֹלָה וּבְקָרְבָּנוֹת גְּדוֹלִים.\",1,0],[2,130,6,4,\"אֶת מֹשֶׁה אַהֲרֹן וּמִרְיָם. תִּרְגֵּם יוֹנָתָן: ״מֹשֶׁה לְאַלְפָא מְסוֹרַת דִּינִין וְאַהֲרֹן לְכַפָּרָא עַל עַמָּא וּמִרְיָם לְאוֹרָאָה לְנָשִׁיָא״.\",2,0],[2,130,6,5,\"וּמֶה עָנָה אֹתוֹ בִּלְעָם בֶּן בְּעוֹר. ״מָה אֶזְעֹם לֹא זָעַם ה׳״ (במדבר כ״ג:ח), שֶׁלֹּא כָּעַסְתִּי כָּל אוֹתָן הַיָּמִים.\",1,0],[2,130,6,5,\"מִן הַשִּׁטִּים. שֶׁחֲטָאתֶם לִי שָׁם, דְּעוּ צִדְקוֹתַי שֶׁלֹּא מָנַעְתִּי טוֹבָתִי וְעֶזְרָתִי מִכֶּם עַד הֵבֵאתִי אֶתְכֶם לַגִּלְגָּל וְכָבַשְׁתִּי לִפְנֵיכֶם שָׁם אֶת הָאָרֶץ.\",2,0],[2,130,6,6,\"אִכַּף. אֶהְיֶה כָּפוּף.\",1,0],[2,130,6,7,\"נַחֲלֵי שָׁמֶן. לִמְנָחוֹת.\",1,0],[2,130,6,7,\"הַאֶתֵּן בְּכוֹרִי. קָרְבָּן לְפִשְׁעִי.\",2,0],[2,130,6,8,\"הִגִּיד. הַקָּדוֹשׁ בָּרוּךְ הוּא לְךָ אָדָם מַה טּוֹב לְךָ לַעֲשׂוֹת.\",1,0],[2,130,6,8,\"וְהַצְנֵעַ לֶכֶת. תִּרְגֵּם יוֹנָתָן: ״הֱוֵי צָנוּעַ לְמֵיהַךְ בְּדַחֲלָא דְאֱלָהָךְ״. דָּבָר אַחֵר: וְהַצְנֵעַ לֶכֶת, לֹא כְּמִדַּת הַקָּדוֹשׁ בָּרוּךְ הוּא מִדַּת בָּשָׂר וָדָם, מִדַּת בָּשָׂר וָדָם אָדָם מְבַיֵּשׁ אֶת חֲבֵרוֹ וּבָא לְפַיְּסוֹ וְאוֹמֵר לוֹ אֵינִי מִתְרַצֶּה לְךָ עַד שֶׁיָּבֹא פְּלוֹנִי וּפְלוֹנִי שֶׁבִּזִיתָנִי לִפְנֵיהֶם, אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵין חָפֵץ אֶלָּא שֶׁיָּשׁוּב אֵלָיו בֵּינוֹ לְבֵין עַצְמוֹ.\",2,0],[2,130,6,9,\"קוֹל ה׳ לָעִיר יִקְרָא. ״קָל נְבִיָּא דַה׳ עַל קַרְתָּא״ מַכְרִיזִין לָהֶם תְּשׁוּבָה.\",1,0],[2,130,6,9,\"וְתוּשִׁיָּה יִרְאֶה שְׁמֶךָ. וְתוּשִׁיָּה קוֹרֵא לָהֶם הַנָּבִיא אֲשֶׁר רוֹאֶה אֶת שְׁמֶךָ, אֲשֶׁר נוֹתֵן לֵב לְהִתְבּוֹנֵן וְלִרְאוֹת דְּרָכֶיךָ. וְתוּשִׁיָּה מוּסָב עַל מִקְרָא שֶׁלְּמַעְלָה הֵימֶנּוּ.\",2,0],[2,130,6,9,\"שִׁמְעוּ מַטֶּה וּמִי יְעָדָהּ. הַטּוּ אֹזֶן וְשִׁמְעוּ מַטֵּה הַפֻּרְעָנוּת אֲשֶׁר תִּרְדֶּה אֶתְכֶם שֶׁהַנְּבִיאִים מַתְרִים בָּכֶם, וְשִׁמְעוּ מִי הוּא אֲשֶׁר יִיעֵד אוֹתוֹ הַפֻּרְעָנוּת אִם יְכֹלֶת בְּיָדוֹ לְקַיֵּם מַה שֶּׁגּוֹזֵר. וְיוֹנָתָן לֹא כֵן תִּרְגֵּם.\",3,0],[2,130,6,9,\"(וְתוּשִׁיָּה יִרְאֶה שְׁמֶךָ. מִכָּאן שֶׁכָּל מִי שֶׁאוֹמֵר בְּכָל יוֹם מִקְרָא הַמִּתְחִיל וּמְסַיֵּם כְּמוֹ שֶׁמִּתְחִיל וּמְסַיֵּם שְׁמוֹ הַתּוֹרָה מַצִּילוֹ מִגֵּיהִנֹּם).\",4,0],[2,130,6,10,\"עוֹד הַאִשׁ בֵּית רָשָׁע אוֹצְרוֹת רֶשַׁע. הֵ״א הָאֵשׁ נְקוּדָה פַּתָּח לְפִי שֶׁהִיא תֵּמַהּ, וְכֵן פֵּרוּשׁוֹ עוֹד לְשׁוֹן אֹרֶךְ יָמִים הוּא, הָאֵשׁ כְּמוֹ הֲיֵשׁ (וּבְדִבְרֵי הַיָּמִים א׳ ב׳) מָצִינוּ אִישַׁי אֲבִי דָוִד בִּמְקוֹם יִשַׁי אַף כָּאן אֵשׁ בִּמְקוֹם יֵשׁ וְכֵן (בִּשְׁמוּאֵל ב׳ י״ד:י״ט) ״אִם אֵשׁ לְהֵמִין וּלְהַשְׂמִאיל״ אִם יֵשׁ לְהַאֲמִין וּלְהַשְׂמִאיל, וְיוֹנָתָן תִּרְגֵּם כֵּן ״הַאִית״ שֶׁיַּעֲלֶה בִּלְבַבְכֶם שֶׁיִּתְקַיֵּם בֵּית רָשָׁע לְאֹרֶךְ יָמִים וְאוֹצְרוֹת רֶשַׁע.\",1,0],[2,130,6,10,\"וְאֵיפַת רָזוֹן זְעוּמָה. מִדָּה קְטַנָּה שֶׁעֲשִׁירֵיכֶם מְרַמִּים בָּהּ הָעֲנִיִּים וּמְבִיאִין אוֹתָן לִידֵי רָזוֹן, וְהוּא זְעוּמָה בְּאַפּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.\",2,0],[2,130,6,13,\"הֶחֱלֵיתִי הַכּוֹתֶךָ. הֶאֱנַשְׁתִּי מַכּוֹתֶיךָ חֲזָקוֹת וְחוֹלוֹת וַאֲנוּשׁוֹת.\",1,0],[2,130,6,13,\"הַשְׁמֵם. לְהַשְׁמִימְךָ עַל חַטֹּאתֶיךָ.\",2,0],[2,130,6,14,\"וְיֶשְׁחֲךָ בְּקִרְבֶּךָ. הַמַּאֲכָל שֶׁתֹּאכַל אַכְנִיס בּוֹ מְאֵרָה בְּתוֹךְ הַמֵּעַיִם וְיִגְרוֹם לְךָ חֹלִי שֶׁתְּהֵא חוֹלֶה וְהוֹלֵךְ שָׁחוֹחַ, וְכֵן מְפָרֵשׁ אוֹתוֹ בְּסִפְרֵי מִנַּיִן אַף בְּתוֹךְ הַמֵּעַיִם תַּלְמוּד לוֹמַר וְיֶשְׁחֲךָ בְּקִרְבֶּךָ בְּפָרָשַׁת וְהָיָה עֵקֶב בְּמִדְרַשׁ תָּמִיד עֵינֵי ה׳ אֱלֹהֶיךָ בָּהּ. וְאַף יוֹנָתָן תִּרְגֵּם כֵּן ״וִיהֵי לָךְ לְמַרְעָא מְתָא בִּמְעֵיךְ״.\",1,0],[2,130,6,14,\"וְתַסֵּג. אֶת אוֹיְבֶיךָ הַמּוֹלִיכִים בָּנֶיךָ וּבְנוֹתֶיךָ בַּשְּׁבִי וְלֹא תְפַלְּטֵם, וְאִם תְּפַלְּטֵם סוֹפָם לַחֶרֶב. וּמִשְּׁמוֹ שֶׁל רַבִּי מְנַחֵם שָׁמַעְתִּי וְתַסֵּג לְתַאֲוַת תַּשְׁמִישׁ וְלֹא תַפְלִיט, לֹא יִהְיֶה לְךָ כֹּחַ לִפְלֹט שִׁכְבַת זֶרַע וְאִם תְּפַלְּטֵם סוֹפָהּ לַחֶרֶב אֶתֵּן אֶתְכֶם. וְיוֹנָתָן תִּרְגֵּם לָשׁוֹן הָרִאשׁוֹן.\",2,0],[2,130,6,16,\"וְיִשְׁתַּמֵּר חֻקּוֹת עָמְרִי. וְיָדַעְתִּי כִּי לֹא תִשְׁמְעוּ אֵלַי כִּי יִשְׁתַּמֵּר עַל יְדֵיכֶם וּבֵינֵיכֶם כָּל חֻקּוֹת עָמְרִי וְאַחְאָב.\",1,0],[2,130,6,16,\"וְחֶרְפַּת עַמִּי תִּשָּׂאוּ. אַתֶּם תְּקַבְּלוּן עֲוֹן הַחֶרְפָּה שֶׁהָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת מְחָרְפִין אֶת עַמִּי שֶׁהֵעִידָה בָּהֶם תּוֹרָה עַל כָּךְ (דברים כ״ה:י״ד) ״לֹא יִהְיֶה לְךָ אֵיפָה וְאֵיפָה״ וְהֵם אֵינָם שׁוֹמְרִים.\",2,0],[2,130,7,1,\"אַלְלַי לִי. הַנָּבִיא מְקוֹנֵן עַל עַצְמוֹ אוֹי לִי שֶׁהָעֳמַדְתִּי לְנָבִיא בָּעֵת הַזֹּאת שֶׁאֵין בְּנֵי אָדָם צַדִּיקִים בַּדּוֹר.\",1,0],[2,130,7,1,\"כְּאָסְפֵּי קַיִץ. נָקוּד חֲטַף קָמַץ שֶׁאֵינוֹ לְשׁוֹן פּוֹעֵל כְּמוֹ ׳יוֹשֵׁב׳ אוֹמֵר אֶלָּא לְשׁוֹן מִפְעָל כְּמוֹ (ישעיהו ל״ג:ד) ״אֹסֶף הֶחָסִיל״ כַּאֲסִיפַת קַיִץ וְהֵם סוֹפֵי תְאֵנִים שֶׁהֵן רָעוֹת, וְכֵן תִּרְגֵּם יוֹנָתָן ״כְּסִיּוּפֵי קַיְטָא״.\",2,0],[2,130,7,1,\"כְּעוֹלְלוֹת בָּצִיר. תִּרְגֵּם יוֹנָתָן: ״כְּעוֹלְלָן בָּתַר קְטוּף״.\",3,0],[2,130,7,1,\"אֵין אֶשְׁכּוֹל לֶאֱכוֹל. כְּתַרְגּוּמוֹ ״לֵית גְּבַר דְּבֵיהּ עוֹבָדִין טָבִין״.\",4,0],[2,130,7,1,\"בִּכּוּרָה. תְּאֵנָה טוֹבָה הַמִּתְבַּשֶּׁלֶת בְּעִתָּהּ, כְּתַרְגּוּמוֹ ״לְטָבְיָא חֲמֵדַת נַפְשִׁי״.\",5,0],[2,130,7,2,\"וְיָשָׁר בָּאָדָם אָיִן. אָדָם יָשָׁר בִּבְנֵי אָדָם אָיִן.\",1,0],[2,130,7,2,\"יָצוּדוּ חֵרֶם. יָצוּדוּ בְּחֶרְמָם וּבִמְצוּדָתָם.\",2,0],[2,130,7,3,\"עַל הָרַע כַּפַּיִם לְהֵיטִיב. עַל שְׂכַר הָרָעַת כַּפֵּיכֶם אַתֶּם מְקַוִּים שֶׁיֵּיטִיב לָכֶם.\",1,0],[2,130,7,3,\"הַשַּׂר שׁוֹאֵל. שֹׁחַד.\",2,0],[2,130,7,3,\"וְהַשּׁוֹפֵט. הַדָּן אֶת הַדִּין גַּם הוּא בְּשִׁלּוּם אוֹמֵר לְשׁוֹפֵט חֲבֵרוֹ כְּשֶׁהוּא גַּזְלָן וּמְחֻיָּב בַּדִּין, שַׁלֵּם לִי גְּמוּלִי בָּזֶה וַאֲנִי אֲזַכֶּה אוֹתְךָ בְּדִין אַחֵר.\",3,0],[2,130,7,3,\"וְהַגָּדוֹל דֹּבֵר הַוַּת נַפְשׁוֹ. הַמֶּלֶךְ אוֹ הַנָּשִׂיא אוֹמֵר בַּדִּין רְצוֹן נַפְשׁוֹ, הַוַּת נַפְשׁוֹ דְּבַר הַהֹוֶה לִרְצוֹנוֹ. וּלְנַפְשׁוֹ כְּמוֹ (ירמיהו ט״ו:א) ״אֵין נַפְשִׁי אֶל הָעָם הַזֶּה״ וְכֵן תִּרְגֵּם יוֹנָתָן: ״תַּחְמוּדֵי נַפְשֵׁיהּ״.\",4,0],[2,130,7,3,\"וַיְעַבְּתוּהָ. עֲשָׂאוּהָ קְלִיעָה שֶׁל חֵטְא בֵּין שְׁלָשְׁתָּן כַּעֲבוֹתוֹת הָעֲגָלָה חֲטָאָה, שֶׁהָעֲבוֹת מְשֻׁלֶּשֶׁת הִיא, כָּךְ מָצָאתִי בְּתַרְגּוּם יְרוּשַׁלְמִי ״עֲבַדְנוּהָ כִּקְלִיעָה דְחוֹבִין״.\",5,0],[2,130,7,4,\"טוֹבָם כְּחֵדֶק. ״טָבָא דְאִית בְּהוֹן קָשֶׁה לְמֵיפַּק מִן יְדֵיהּ כַּד מִן חֲדָקָא״ קָשֶׁה לָצֵאת מִיָּדוֹ כְּמוֹ הַקּוֹצִים הַנִּסְבָּכִין בַּצֶּמֶר.\",1,0],[2,130,7,4,\"יָשָׁר מִמְּסוּכָה. יָשָׁר שֶׁבָּהֶם רַע מִמְּסוּכַת קוֹצִים וּמְסוּכָה כְּמוֹ (ישעיהו ה:ה) ״הָסֵר מְשׂוּכָּתוֹ״.\",2,0],[2,130,7,4,\"יוֹם מְצַפֶּיךָ. יוֹם שֶׁאַתָּה מְצַפֶּה בּוֹ לְטוֹבָה תָּבֹא פְּקֻדָּתְךָ.\",3,0],[2,130,7,4,\"מְבוּכָתָם. עִרְבּוּלֵיהוֹן כְּמוֹ (שמות י״ד:ג) ״נְבֻכִים הֵם״ מְהוּמָתָם.\",4,0],[2,130,7,5,\"אַל תַּאֲמִינוּ בְרֵעַ. כְּמַשְׁמָעוֹ, וְרַבּוֹתֵינוּ פֵּרְשׁוּ כְּלַפֵּי מַעְלָה אַל תֶּחֱטָאוּ וְתֹאמְרוּ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֲבֵנוּ וְהוּא יִמְחוֹל לָנוּ.\",1,0],[2,130,7,5,\"מִשּׁוֹכֶבֶת חֵיקֶךָ. נִשְׁמָתְךָ הִיא תָּעִיד בְּךָ.\",2,0],[2,130,7,5,\"פִּתְחֵי פִיךָ. דִּבְרֵי פִיךָ פְּתִיחוֹת פִּיךָ.\",3,0],[2,130,7,7,\"וַאֲנִי בַּה׳ אֲצַפֶּה. הַנָּבִיא אוֹמֵר כֵּן.\",1,0],[2,130,7,8,\"אַל תִּשְׂמְחִי אוֹיַבְתִּי. בָּבֶל וְעִיר הַחַיֶּבֶת רוֹמִי (ספרים אחרים: בָּבֶל וּפָרַס הַחַיֶּבֶת).\",1,0],[2,130,7,11,\"יוֹם לִבְנוֹת גְּדֵרָיִךְ. מוּסָב עַל הָאֹמְרָה אֵלַי וְעוֹד הִיא אוֹמֶרֶת אֵלַי יוֹם לִבְנוֹת גְּדֵרָיִךְ שֶׁאַתְּ מְצַפָּה לוֹ אוֹתוֹ הַיּוֹם יִרְחַק חֹק זְמַנּוֹ יַאֲרִיךְ וְלֹא יָבֹא לְעוֹלָם.\",1,0],[2,130,7,12,\"יוֹם הוּא וְעָדֶיךָ יָבֹא. הַנָּבִיא אוֹמֵר אוֹתוֹ הַיּוֹם שֶׁאַתֶּם מַלְעִיגִים עָלָיו לֵאמֹר בָּטֵל וְהָלַךְ לוֹ, יוֹם הַהוּא שָׁמוּר וְנָצוּר וְלֹא בָּטֵל עָדֶיךָ יָבֹא בָּבֶל לְהַחֲרִיבֵךְ.\",1,0],[2,130,7,12,\"לְמִנִּי אַשּׁוּר. אֲשֶׁר הוּא רֹאשׁ לִמְרֵעֵינוּ.\",2,0],[2,130,7,12,\"וְעָרֵי מָצוֹר. כְּלוֹמַר וְעַד עָרֵי מָצוֹר, וְיוֹנָתָן תִּרְגֵּם ״וּדְמִן חוּרְמִינֵי רַבְּתָא״.\",3,0],[2,130,7,12,\"וְיָם מִיָּם. וְהַיּוֹשְׁבִים עַל יָם הָאַחֲרוֹן אֲשֶׁר הוּא בַּמַּעֲרָב.\",4,0],[2,130,7,12,\"וְהַר הָהָר. כְּמוֹ וְיוֹשְׁבֵי הָהָר וְיוֹנָתָן לֹא כֵן תִּרְגֵּם.\",5,0],[2,130,7,12,\"יוֹם לִבְנוֹת גְּדֵרָיִךְ. הַנָּבִיא מְבַשְּׂרוֹ לְיִשְׂרָאֵל שֶׁיֵּשׁ יוֹם כָּמוּס וּמוּכָן לִבְנוֹת גִּדְרוֹת חָרְבוֹתֵיהֶן, יוֹם הַהוּא יִרְחַק וִיבַטֵּל מֵעֲלֵיכֶם חֹק גְּזֵרוֹת הַבַּבְלִיִּים וּפַרְסִיִּים.\",6,0],[2,130,7,12,\"יוֹם הוּא וְעָדֶיךָ יָבֹא. ״בְּעִדָּנָא הַהִיא יִתְכַּנְּשׁוּן גָּלְוָותָא דְיִשְׂרָאֵל דְּמִן אַתּוּר וְגוֹ׳״.\",7,0],[2,130,7,13,\"וְהָיְתָה הָאָרֶץ. אֶרֶץ הַבַּבְלִיִּים וּפַרְסִיִּים.\",1,0],[2,130,7,14,\"שֹׁכְנִי לְבָדָד. שֶׁיְּהֵא שׁוֹכֵן בֶּטַח בָּדָד.\",1,0],[2,130,7,14,\"יַעַר בְּתוֹךְ כַּרְמֶל. תִּרְגֵּם יוֹנָתָן: ״דַּהֲווֹ צָדִין בְּחוּרְשָׁא יִתְיַתְבוּן כְּכַרְמְלָא״, אוֹתָן שֶׁהָיוּ שׁוֹמְמִים כִּיעָרִוֹת יִשְׁכְּנוּ לְבָדָד בְּתוֹךְ כַּרְמֶל שֶׁהוּא מָקוֹם מְיֻשָּׁב. וְיֵשׁ לְפָרֵשׁ שֹׁכְנִי לְבָדָד בַּיְּעָרִים לֹא יִרְאוּ מֵחַיּוֹת הַשָּׂדֶה כִּבְתוֹךְ כַּרְמֶל.\",2,0],[2,130,7,17,\"כְּזוֹחֲלֵי אֶרֶץ. הֵם נְחָשִׁים הַזּוֹחֲלִים עַל גְּחוֹנָם בַּעֲפַר הָאָרֶץ.\",1,0],[2,130,7,17,\"יִרְגְּזוּ מִמִּסְגְּרוֹתֵיהֶם. יֶחֶרְדוּ מֵרֹב דֹּחַק אִסּוּרֵיהֶם וּמַסְגֵּר כִּלְאָם.\",2,0],[2,130,7,20,\"תִּתֵּן אֱמֶת לְיַעֲקֹב. תִּרְגֵּם יוֹנָתָן: ״תִּתְיְהַב קוּשְׁטֵיהּ דְּיַעֲקֹב לִבְנוֹהִי כְּמָה דְקַיָּמְתָּא לֵיהּ בְּבֵית אֵל טָבוּת אַבְרָהָם לְזַרְעֵיהּ בַּתְרוֹהִי כְּמָה דְקַיָּמְתָּא לֵיהּ בֵּין בִּתְרַיָּא תִּדְכַּר לָנָא עֲקֵדַת יִצְחָק״, תִּתֵּן לָנוּ בֶּאֱמֶת אֲשֶׁר הִבְטַחְתָּ לְיַעֲקֹב הָאֱמֶת לָנוּ דְּבָרֶיךָ אֲשֶׁר הִבְטַחְתָּ לְיַעֲקֹב ״כִּי לֹא אֶעֱזָבְךָ״ (בראשית כ״ט).\",1,0],[2,130,7,20,\"חֶסֶד לְאַבְרָהָם. שְׂכַר חֶסֶד אֲשֶׁר לְאַבְרָהָם אֲשֶׁר צִוָּה לְבָנָיו ״לִשְׁמֹר דֶּרֶךְ ה׳ לַעֲשׂוֹת צְדָקָה וּמִשְׁפָּט״, וּלְכָךְ לֹא נֶאֱמַר וְחֶסֶד אֶלָּא חֶסֶד הָאֱמֶת שֶׁתְּאַמֵּת לָנוּ אֶת הַבְטָחַת יַעֲקֹב הִיא תִּהְיֶה תַשְׁלוּם גְּמוּל חַסְדּוֹ שֶׁל אַבְרָהָם.\",2,0],[2,130,7,20,\"אֲשֶׁר נִשְׁבַּעְתָּ. בַּעֲקֵדָתוֹ שֶׁל יִצְחָק ״בִּי נִשְׁבַּעְתִּי נְאֻם ה׳ יַעַן אֲשֶׁר עָשִׂיתָ וְגוֹמֵר״.\",3,0],[2,131,1,1,\"מַשָּׂא נִינְוֵה. תִּרְגֵּם יוֹנָתָן ״מַטַּל כָּס דִּלְוָוט לְאַשְׁקָאָה יָת נִינְוֵה״.\",1,0],[2,131,1,1,\"סֵפֶר חֲזוֹן נַחוּם. חָזוֹן נָקוּד קָמָץ לְפִי שֶׁאֵינוֹ דָבוּק וְאֵינוֹ דוֹמֶה לַחֲזוֹן יְשַׁעְיָהוּ שֶׁהוּא נָקוּד חֲטַף פַּתַּח, וְכֵן פֵּרוּשׁ סֵפֶר חֲזוֹן כְּבָר נִכְתַּב עָלֶיהָ, וְהוּא נְבוּאַת יוֹנָה בֶּן אֲמִתַּי וְעַתָּה חָזַר וְנִתְנַבֵּא עָלֶיהָ נַחוּם הָאֶלְקוֹשִׁי אֶת הַמַּשָּׂא הַזֶּה. אֶלְקוֹשׁ הָיָה שֵׁם עִירוֹ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״מִלְּקַדְמִין אִתְנַבִּי עֲלָהּ יוֹנָה בַּר אַמְתַּי וְתָבַת מֵחוֹבָהָא, וְכַדּוּ דְּאוֹסִיפַת לְמֵיחְטֵי תָּב וְאִתְנַבִּי עֲלָהּ נַחוּם דְּמִבֵּית אֶלְקוֹשׁ״.\",2,0],[2,131,1,2,\"אֵל קַנּוֹא וְנוֹקֵם ה׳. עַל זַרְעוֹ שֶׁל סַנְחֵרִיב נִתְנַבֵּא נַחוּם וּבִימֵי מְנַשֶּׁה, כְּמוֹ שֶׁמָּצִינוּ בְּסֵדֶר עוֹלָם.\",1,0],[2,131,1,2,\"אֵל קַנּוֹא וְנוֹקֵם ה׳. מֵאָז שֶׁנִּפְרַע לְיִשְׂרָאֵל מֵאוֹיְבֵיהֶם וְגַם עֲדַיִן עַתָּה נוֹקֵם הוּא וּבַעַל חֵמָה וְעָתִיד הוּא לִהְיוֹת נוֹקֵם לְצָרָיו שֶׁהֶחֱרִיבוּ אֶת אַרְצוֹ וְהִגְלוּ אֶת עַמּוֹ וְנוֹטֵר הוּא אֶת אֵיבָתוֹ לַבַּבְלִיִּים. וְר״שׁ אוֹמֵר שָׁלוֹשׁ נְקִימוֹת הַלָּלוּ כְּנֶגֶד שָׁלוֹשׁ גְלִיּוֹת שֶׁהִגְלָה סַנְחֵרִיב אֶת יִשְׂרָאֵל, כְּמוֹ שֶׁמָּצִינוּ בְּסֵדֶר עוֹלָם.\",2,0],[2,131,1,3,\"ה׳ אֶרֶךְ אַפַּיִם וּגְדָל כֹּחַ. גְּדָל כֹּחַ הוּא וְהַיְכֹלֶת בְּיָדוֹ לְהִנָּקֵם וַאֲשֶׁר לֹא מִהֵר נִקְמָתוֹ לְפִי שֶׁאֶרֶךְ אַפַּיִם הוּא וּמִכָּל מָקוֹם נַקֵּה לֹא יְנַקֶּה.\",1,0],[2,131,1,3,\"ה׳ בְּסוּפָה וּבִשְׂעָרָה דַּרְכּוֹ. הֵם שְׁלוּחָיו לְהִפָּרַע מֵאוֹיְבָיו, שֶׁנֶּאֱמַר בְּמִצְרַיִם (שמות יד:כא) ״בְּרוּחַ קָדִים עַזָּה״, וּבְדוֹר הַמַּבּוּל (איוב ד:ט) ״מִנִּשְׁמַת אֱלוֹהַּ יֹאבֵדוּ״, בְּצֹר נֶאֱמַר (יחזקאל כו:כו) ״רוּחַ קָדִים שִׁבְּרֵךְ״.\",2,0],[2,131,1,3,\"וְעָנָן אֲבַק רַגְלָיו. גַּם הוּא דֶּרֶךְ נִקְמָתוֹ, (שמות יד:כד) ״וַיַּשְׁקֵף אֶל מַחֲנֵה מִצְרַיִם בְּעַמּוּד אֵשׁ וְעָנָן״, (יחזקאל ל:יח) ״הִיא עָנָן יְכַסֶּנָּה״.\",3,0],[2,131,1,4,\"גּוֹעֵר בַּיָּם. כְּמַשְׁמָעוֹ, וְדֻגְמָא הוּא כְּלַפֵּי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁנִּמְשְׁלוּ לַמַּיִם, כָּעִנְיָן שֶׁנֶּאֱמַר (ישעיהו יז:יב) ״לְאֻמִּים כִּשְׁאוֹן מַיִם כַּבִּירִים יִשָּׁאוּן״.\",1,0],[2,131,1,4,\"וְכָל הַנְּהָרוֹת הֶחֱרִיב. כָּאן נִבָּא שֶׁעָתִיד הַקָּבָּ״ה לְהַמְלִיךְ אֶת נְבוּכַדְנֶצַּר (ירמיה כה) בִּימֵי יְהוֹיָקִים וְיִתֵּן אֶת אַשּׁוּר וְאֶת כָּל הָאֲרָצוֹת לַחֶרֶב.\",2,0],[2,131,1,4,\"אֻמְלַל בָּשָׁן וְכַרְמֶל. מוֹשָׁבוֹת הַטּוֹבִים.\",3,0],[2,131,1,4,\"וּפֶרַח לְבָנוֹן אֻמְלָל. חַכְמֵי יִשְׂרָאֵל פֵּרְשׁוּ כְּלַפֵּי מִינֵי מְגָדִים שֶׁנָּטַע שְׁלֹמֹה בְּבֵית הַמִּקְדָּשׁ שֶׁהָיוּ שֶׁל זָהָב, וְכֵיוָן שֶׁנִּכְנְסוּ גּוֹיִם לַהֵיכָל יָבְשׁוּ.\",4,0],[2,131,1,5,\"הָרִים רָעֲשׁוּ מִמֶּנּוּ. הַמְּלָכִים וְהַשָּׂרִים מֵהַכַּשְׂדִּים יִפְחֲדוּ מִגְּזֵרָתוֹ.\",1,0],[2,131,1,5,\"וַתִּשָּׂא הָאָרֶץ. מַשְׂאַת עָשָׁן.\",2,0],[2,131,1,6,\"נִתְּכָה. הִגִּיעַ לָאָרֶץ, כְּמוֹ (שמות ט:לג) ״וּמָטָר לֹא נִתַּךְ אָרְצָה״.\",1,0],[2,131,1,6,\"נִתְּצוּ מִמֶּנּוּ. מֵאֵימָתוֹ.\",2,0],[2,131,1,7,\"טוֹב ה׳ לְמָעוֹז. וְאַף בְּשָׁעָה שֶׁהוּא נִפְרָע מֵאוֹיְבָיו לֹא זָזוּ רַחֲמָיו מִלְּהֵיטִיב לִירֵאָיו, וְלֹא כְּמִדַּת בָּשָׂר וָדָם שֶׁכְּשֶׁהוּא עָסוּק בָּזוֹ אֵינוֹ פָּנוּי בָּזוֹ, כָּעִנְיָן שֶׁנֶּאֱמַר (שמות טו:ג) ״ה׳ אִישׁ מִלְחָמָה ה׳ שְׁמוֹ״, כְּמוֹ שֶׁהוּא בִּמְכִלְתִּין.\",1,0],[2,131,1,7,\"וְיֹדֵעַ. אֶת צָרְכֵי חוֹסֵי בוֹ.\",2,0],[2,131,1,8,\"וּבְשֶׁטֶף עֹבֵר. וּבְחֵמָה שׁוֹטֶפֶת.\",1,0],[2,131,1,8,\"כָּלָה יַעֲשֶׂה מְקוֹמָהּ. שֶׁל אֶרֶץ, וּמוּסָב זֶה עַל ״וַתִּשָּׂא הָאָרֶץ מִפָּנָיו״ כְּמוֹ שֶׁאָמוּר לְמַעְלָה.\",2,0],[2,131,1,9,\"כָּלָה הוּא עֹשֶׂה. לְנִינְוֵה וּמַלְכֵי אַשּׁוּר לֹא יִשְׁנֶה לָהֶם עוֹד פַּעַם אַחֶרֶת.\",1,0],[2,131,1,10,\"כִּי עַד סִירִים סְבֻכִים. כְּלוֹמַר פִּתְאֹם תָּבֹא עֲלֵיהֶם מַכָּתָם וְלֹא יֵרְדוּ מִכְּבוֹדָם מְעַט מְעַט, כִּי בְּעוֹד שֶׁהַסִּירִים וְהַקּוֹצִים נִסְבָּכִים נִשְׁרָשִׁים בְּחָזְקָה.\",1,0],[2,131,1,10,\"וּכְסָבְאָם סְבוּאִים. וְעוֹדָם בְּמִשְׁתֵּיהֶן וּבְשִׂמְחָתָן, וְיֵשׁ פּוֹתְרִין ״כִּי עַד סִירִים״ לְשׁוֹן ׳הֲסָרָה׳.\",2,0],[2,131,1,10,\"אֻכְּלוּ כְּקַשׁ יָבֵשׁ. אֲשֶׁר נִתְמַלֵּא וְנִגְמַר בִּשּׁוּלוֹ וְיָבֵשׁ.\",3,0],[2,131,1,10,\"מָלֵא. אשובי״ר בְּלַעַ״ז, וְכֵן ״מְלֵאָתְךָ״, ״הַמְלֵאָה הַזֶּרַע״.\",4,0],[2,131,1,11,\"מִמֵּךְ. אַתְּ נִינְוֵה.\",1,0],[2,131,1,11,\"יָצָא. סַנְחֵרִיב הַחוֹשֵׁב רָעָה, דִּמָּה לְהַחֲרִיב דִּירַת מַטָּה וּמַעְלָה. כָּתוּב אֶחָד אוֹמֵר (מלכים ב יט:כג) ״וְאָבֹא מְלוֹן קִצֹּה״, וְכָתוּב אֶחָד אוֹמֵר (ישעיהו לז:כד) ״וְאָבֹא מְרוֹם קִצּוֹ״. בִּתְחִלָּה אַחֲרִיב דִּירָה שֶׁל מַטָּה, וּלְבַסּוֹף דִּירָה שֶׁל מַעְלָה, כִּדְאִיתָא בְּחֵלֶק (דף צד).\",2,0],[2,131,1,12,\"אִם שְׁלֵמִים וְכֵן רַבִּים. יָפֶה תַּרְגּוּם שֶׁל יוֹנָתָן מְיֻשָּׁב עַל הַמִּקְרָא: ״אִם יְהוֹן שְׁלֵמִים בְּעֵצָה״ שֶׁיְּהוּ כֻּלָּם שָׁוִים בְּהַסְכָּמָה אַחַת, וְכֵן אִם יִהְיוּ רַבִּים מְאֹד אַנְשֵׁי נִינְוֵה אוֹיְבֶיךָ יְרוּשָׁלַיִם, וְכֵן אַף אִם גָּזּוּ חִדְּקַל וְעָבְרוּ אֶת פְּרָת לָצוּר עָלֶיהָ לֹא יַצְלִיחוּ, שֶׁהֲרֵי ״עִנִּיתִיךְ וְלֹא אֲעַנֵּךְ עוֹד״. וְעוֹד שָׁמַעְתִּי: ״אִם שְׁלֵמִים״ – אַנְשֵׁי נִינְוֵה בִּגְדֻלָּתָם, ״וְכֵן״ – אִם יְהוּ עוֹד רַבִּים וְנִכְבָּדִים יוֹתֵר, ״וְכֵן נָגוֹזּוּ וְעָבָר״ – וְכֵן אֲגִיזֵם וְאַעֲבִירֵם. הֲרֵי זֶה כְּמוֹ (שמות א:יב) ״וְכַאֲשֶׁר יְעַנּוּ אֹתוֹ כֵּן יִרְבֶּה״.\",1,0],[2,131,1,12,\"וְעִנִּיתִךְ לֹא אֲעַנֵּךְ עוֹד. אֲעַנֶּה אוֹתְךָ בַּפַּעַם הַזֹּאת כָּלָה וְנֶחֱרָצָה וְלֹא אֶזְקַק לְךָ עוֹד. וְרַבּוֹתֵינוּ דָּרְשׁוּ לְעִנְיַן מַעֲשֵׂה הַצְּדָקָה בְּמַסֶּכֶת גִּטִּין, אַךְ אֵינוֹ עַל סֵדֶר שְׁאָר הַנְּבוּאָה.\",2,0],[2,131,1,13,\"וְעַתָּה אֶשְׁבֹּר מֹטֵהוּ מֵעָלָיִךְ. שְׁכִינָה אוֹמֶרֶת כֵּן לַנָּבִיא שֶׁהוּא יִשְׂרְאֵלִי: אֶשְׁבֹּר מֹטֵהוּ שֶׁל אַשּׁוּר מֵעָלֶיךָ וּמֵעַמִּי.\",1,0],[2,131,1,14,\"וְצִוָּה עָלֶיךָ ה׳. עַתָּה מוּסָב הַדִּבּוּר אֶל מֶלֶךְ אַשּׁוּר.\",1,0],[2,131,1,14,\"לֹא יִזָּרַע מִשִּׁמְךָ עוֹד. לֹא יַעֲמֹד מִמְּךָ מֶלֶךְ.\",2,0],[2,131,1,14,\"מִבֵּית אֱלֹהֶיךָ אַכְרִית פֶּסֶל וּמַסֵּכָה. וְאָשִׂים אֶת בֵּית אֱלֹהֶיךָ קִבְרֶךָ. שָׁם תִּבְרַח לְהִמָּלֵט וְשָׁם תֵּהָרֵג, כְּמוֹ שֶׁכָּתוּב שֶׁנֶּהֱרַג אָבִיךָ בֵּית נִסְרוֹךְ אֱלֹהָיו.\",3,0],[2,131,1,14,\"כִּי קַלּוֹתָ. בְּעֵינַי.\",4,0],[2,131,2,1,\"שַׁלְּמִי נְדָרָיִךְ. אֲשֶׁר נָדַרְתָּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא אִם יַצִּילְךָ מִכַּף סַנְחֵרִיב מֶלֶךְ אַשּׁוּר, כִּי עַתָּה נִצַּלְתָּ.\",1,0],[2,131,2,1,\"כִּי לֹא יוֹסִיף עוֹד לַעֲבָר בָּךְ. אוֹתוֹ הַבְּלִיַּעַל.\",2,0],[2,131,2,1,\"כֻּלֹּה נִכְרָת. הוּא וְזַרְעוֹ.\",3,0],[2,131,2,2,\"עָלָה מֵפִיץ עַל פָּנַיִךְ נָצוֹר מְצוּרָה. הַמֵּפִיץ אֲשֶׁר עָלָה עַל פָּנֶיךָ אֶל אֶרֶץ יְהוּדָה בִּימֵי יְחִזְקִיָּהוּ, עַכְשָׁיו הוּא נָצוֹר מְצוּרָה, נְבוּכַדְנֶצַּר מֶלֶךְ בָּבֶל שֶׁהוּא צָר עָלָיו.\",1,0],[2,131,2,2,\"צַפֵּה דֶרֶךְ. הַבֵּט אַתָּה אִישׁ יְהוּדָה עַל אֵם הַדְּרָכִים וְתִרְאֶה אֶת הַהוֹלְכִים לָצוּר עָלָיו, וְיִתְחַזְּקוּ מָתְנֶיךָ וְאַמֵּץ כֹּחַ מְאֹד.\",2,0],[2,131,2,3,\"כִּגְאוֹן יִשְׂרָאֵל. כְּמוֹ שֶׁהָיָה כְּבָר.\",1,0],[2,131,2,3,\"בְּקָקוּם. בְּזָזוּם וְהֵרִיקוּם, לְשׁוֹן ׳בְּקִיקָה׳ נוֹפֵל עַל גֶּפֶן.\",2,0],[2,131,2,4,\"מָגֵן גִּבּוֹרֵיהוּ. שֶׁל נְבוּכַדְנֶצַּר הַצָּרִים עַל אַשּׁוּר.\",1,0],[2,131,2,4,\"מְאָדָּם. מְאָדָּמִים הֵם. וְאַנְשֵׁי חֵילָם מְתֻלָּעִים. לְבוּשֵׁי זְהוֹרִית.\",2,0],[2,131,2,4,\"בָּאֵשׁ פְּלָדוֹת הָרֶכֶב בְּיוֹם הֲכִינוֹ. בְּיוֹם שֶׁהוּא מוּכָן לָצֵאת בַּצָּבָא מְצַחְצֵחַ רֶכֶב בַּרְזֶל שֶׁלּוֹ, וְלֹא יָדַעְתִּי מַהוּ פְּלָדוֹת, וְאוֹמֵר אֲנִי שֶׁהוּא מִין הַמְּצַחְצַחַת בַּרְזֶל יָפֶה, וְיֵשׁ פּוֹתְרִין פְּלָדוֹת לְשׁוֹן ׳לַפִּיד אֵשׁ׳ בְּדֶרֶךְ הַהֵפֶךְ.\",3,0],[2,131,2,4,\"וְהַבְּרֹשִׁים הָרְעָלוּ. תִּרְגֵּם יוֹנָתָן: ״וְרַבְנֵי מַשְׁרִיתְהוֹן מְסַרְבְּלִין בְּצִבְעוֹנִין״.\",4,0],[2,131,2,4,\"הָרְעָלוּ. מְעֻטָּפִין, וְדוֹמֶה לוֹ (ישעיהו ג:יט) ״הַנְּטִיפוֹת וְהַשֵּׁרוֹת וְהָרְעָלוֹת״. וּבִלְשׁוֹן מִשְׁנָה שָׁנִינוּ ״מַדְיוֹת רְעוּלוֹת״ מַסֶּכֶת שַׁבָּת (דף ס״ה, ע״ש).\",5,0],[2,131,2,5,\"יִתְהוֹלְלוּ. יִנְהֲגוּ עַצְמָן בְּשִׁגָּעוֹן.\",1,0],[2,131,2,5,\"יִשְׁתַּקְשְׁקוּן. תִּרְגֵּם יוֹנָתָן: ״קָל נְקוּשׁ זַיְּנֵיהוֹן מִשְׁתְּמַע״, וְהוּא מִלְּשׁוֹן ״וְהֵשִׁיקוּ הַיְקָבִים״ (יואל ב:כד), ״כְּמַשַּׁק גֵּבִים״ (ישעיהו לג:ד), לְשׁוֹן ׳הַשְׁמָעַת קוֹל׳.\",2,0],[2,131,2,5,\"יְרוֹצֵצוּ. יְרוֹעֲעוּ אֶת הַשּׁוֹמְעִים כַּבְּרָקִים הַלָּלוּ הַטּוֹרְדִים אֶת הַבְּרִיּוֹת, כֵּן תִּרְגֵּם יוֹנָתָן.\",3,0],[2,131,2,6,\"יִזְכֹּר. מֶלֶךְ אַשּׁוּר אֶת אַדִּירָיו וְגִבּוֹרָיו וִידַמֶּה בְּלִבּוֹ לָצֵאת וּלְהִלָּחֵם, וְהֵם יִכָּשְׁלוּ בַּהֲלִיכָתָם.\",1,0],[2,131,2,6,\"יְמַהֲרוּ חוֹמָתָהּ. לָנוּס, לָרוּץ אֶל חוֹמַת הָעִיר. כָּל תֵּיבָה הַצְּרִיכָה לָמֶ״ד בִּתְחִלָּתָהּ הִטִּיל לָהּ הֵ״א בְּסוֹפָהּ.\",2,0],[2,131,2,6,\"וְהֻכַן הַסֹּכֵךְ. תִּרְגֵּם יוֹנָתָן: ״יְבַנּוּן מַגְדְּלַיָּא״. וְיֵשׁ לְפָרֵשׁ ״וְהֻכַן הַסֹּכֵךְ״ – וְהַמֶּלֶךְ נִזְדַּיֵּן בִּכְלֵי זֵינוֹ, כְּמוֹ ״מִמְשַׁח הַסּוֹכֵךְ״, לְשׁוֹן ׳מוֹשֵׁל׳.\",3,0],[2,131,2,7,\"שַׁעֲרֵי הַנְּהָרוֹת. שַׁעֲרֵי הָעִיר אֲשֶׁר מִצַּד הַנְּהָרוֹת.\",1,0],[2,131,2,7,\"וְהַהֵיכָל נָמוֹג. נִרְעַד וְנָע מִכֹּחַ אַבְנֵי בְּלִיסְטְרָא הַנִּזְרָקִים בִּכְתָלָיו הַנִּקְרָא בומ״א.\",2,0],[2,131,2,8,\"וְהֻצַּב. הִיא הַמַּלְכָּה הַנִּצֶּבֶת לִימִין הַמֶּלֶךְ, כְּדַאֲמְרִינָן (תהילים מה:י) ״נִצְּבָה שֵׁגַל לִימִינְךָ״.\",1,0],[2,131,2,8,\"גֻּלְּתָה הֹעֲלָתָה. בְּגִלּוּי הָלְכָה בַּשְּׁבִי וְהָעֳלְתָה מִן הָעִיר.\",2,0],[2,131,2,8,\"מְנַהֲגוֹת כְּקוֹל יוֹנִים. מְנַהֲגוֹת עַצְמָן בְּקִינָה כְּקוֹל יוֹנִים הַמְּקוֹנְנִים. מְנַהֲגוֹת – שרימייצנ״ט בְּלַעַ״ז.\",3,0],[2,131,2,8,\"מְתֹפְפֹת עַל לִבְבֵהֶן. תִּרְגֵּם יוֹנָתָן: מַקִּישׁוֹת יְדֵיהֶן עַל לִבָּן כְּהַקִּישׁ בַּתּוּפִים.\",4,0],[2,131,2,9,\"וְנִינְוֵה כִּבְרֵכַת מַיִם מִימֵי הִיא. מִיּוֹם שֶׁהִיא נַעֲשֵׂית יָשְׁבָה בְּשַׁלְוָה וְאֵין מֵנִיד, כִּבְרֵכַת מַיִם מְכֻנָּסִין שֶׁאֵין זָזִים מִמְּקוֹמָם.\",1,0],[2,131,2,9,\"וְהֵמָּה. עַתָּה מֵרֹב דָּחֳקָם לָמְדוּ לָנוּס וְנָסִים.\",2,0],[2,131,2,9,\"עִמְדוּ עֲמֹדוּ. אוֹמְרִים לָהֶם וְאֵין מַפְנֶה לִבּוֹ לִשְׁמֹעַ וְלַעֲמֹד.\",3,0],[2,131,2,10,\"בֹּזּוּ כֶסֶף. אַתֶּם הַבָּאִים עַל נִינְוֵה.\",1,0],[2,131,2,10,\"וְאֵין קֵצֶה. אֵין חֶשְׁבּוֹן.\",2,0],[2,131,2,10,\"לְתְּכוּנָה. לְאוֹצְרוֹתֵיהֶם. עַל שֵׁם שֶׁהַכֶּסֶף וְהַזָּהָב הַנָּתוּן בָּאוֹצָר נָתוּן בְּחֶשְׁבּוֹן, כְּמָה דְאַתְּ אָמַר ״אֶת הַכֶּסֶף הַמְתֻכָּן״ (מלכים ב יב:יב).\",3,0],[2,131,2,10,\"כָּבֹד מִכָּל כְּלִי חֶמְדָּה. לְשׁוֹן ׳הַכְבָּדָה׳, כְּמוֹ (לקמן ג:טו) ״הִתְכַּבֵּד כַּיֶּלֶק״, לְשׁוֹן ׳מְכַבֵּד הַבַּיִת׳, אשקוונ״ט בְּלַעַ״ז, וּלְכַבֵּד אוֹתָם מִכָּל כְּלֵי חֶמְדָּתָא. וְכֵן תִּרְגֵּם יוֹנָתָן: ״סָפוּ מִכָּל מָנֵי חֶמְדָּתָא״, ׳כָּבֹד׳ כְּמוֹ זָכוֹר וְשָׁמוֹר.\",4,0],[2,131,2,11,\"בּוּקָה. רֵיקָנִית.\",1,0],[2,131,2,11,\"וּמְבוּקָה. וּמְרוֹקֶנֶת עַל יְדֵי בּוֹקְקִים.\",2,0],[2,131,2,11,\"וּמְבֻלָּקָה. מְפֹרֶצֶת בְּחוֹמוֹתֶיהָ, אישברטיר״א בְּלַעַ״ז.\",3,0],[2,131,2,11,\"וּפִק בִּרְכַּיִם. כִּשְׁלוֹן בִּרְכַּיִם, כְּמוֹ (שמואל א כה:לא) ״לְפוּקָה וּלְמִכְשׁוֹל״.\",4,0],[2,131,2,11,\"קִבְּצוּ פָארוּר. שַׁחְרוּרִית כַּקְּדֵרָה.\",5,0],[2,131,2,12,\"אַיֵּה מְעוֹן אֲרָיוֹת. קִינָה הִיא עַל נִינְוֵה שֶׁהָיְתָה מְדוֹר מְלָכִים גִּבּוֹרִים וַחֲזָקִים כַּאֲרָיוֹת.\",1,0],[2,131,2,12,\"אֲשֶׁר הָלַךְ אַרְיֵה לָבִיא שָׁם. תִּרְגֵּם יוֹנָתָן: ״אֲתַר דַּהֲווֹ אָזְלִין מַלְכִּין וְשָׁבְקִין תַּמָּן בְּנֵיהוֹן, הָא כְּאַרְיָה דְּשָׁרֵי לְרוּחְצָן״.\",2,0],[2,131,2,13,\"אַרְיֵה טֹרֵף בְּדֵי גּוֹרוֹתָיו. כְּתַרְגּוּמוֹ: מַלְכֵּיהּ הֲיוּ מְבִיאִים שָׁלָל רַב עַד שֶׁהָיָה דֵּי לִבְנֵי בֵּיתָם.\",1,0],[2,131,2,13,\"וּמְחַנֵּק. בְּהֵמוֹת לְצֹרֶךְ לִבְאוֹתָיו, כְּלוֹמַר מַרְבֶּה אוֹצְרוֹתָיו לְבָנָיו.\",2,0],[2,131,2,13,\"וַיְמַלֵּא טֶרֶף חֹרָיו. תִּרְגֵּם יוֹנָתָן: ״וּמְמַלָּן אוֹצְרוֹתֵיהֶן חֲטוּף״.\",3,0],[2,131,2,14,\"רִכְבָּהּ. רֹב רֶכֶב שֶׁבָּהּ, קרטדי״ן בְּלַעַ״ז, הֵ״א יְתֵרָה, הֵפֶךְ הַלָּשׁוֹן לְרִבּוּי מַרְכָּבוֹת, וְכֵן (יחזקאל כד:ו) ״סִיר אֲשֶׁר חֶלְאָתָהּ בָּהּ״, זֹהַם רַב.\",1,0],[2,131,2,14,\"וְלֹא יִשָּׁמַע עוֹד קוֹל מַלְאָכֵכֵה. קוֹל מַלְאָכֵיךְ, כְּמוֹ שֶׁעָשָׂה כְּבָר רַבְשָׁקֵה וַחֲבֵרָיו שְׁלוּחֵי אַשּׁוּר (ישעיה לז:יג) ״וַיִּקְרָא בְקוֹל גָּדוֹל יְהוּדִית״.\",2,0],[2,131,3,1,\"פֶּרֶק. גֶּזֶל שֶׁמְּפָרְקוֹ מִיַּד בְּעָלָיו.\",1,0],[2,131,3,1,\"לֹא יָמִישׁ טָרֶף. מִתּוֹכָהּ תָּמִיד.\",2,0],[2,131,3,2,\"קוֹל שׁוֹט. לְהַכּוֹת סוּסִים הָיָה נִשְׁמָע בָּהּ תָּמִיד.\",1,0],[2,131,3,2,\"וְקוֹל רַעַשׁ. אוֹפַנֵּי מַרְכָּבוֹת.\",2,0],[2,131,3,2,\"וְסוּס דֹּהֵר. דּוֹלֵג וּמְקַפֵּץ, וְכֵן ״מִדַּהֲרוֹת דַּהֲרוֹת אַבִּירָיו״ (שופטים ה:כב).\",3,0],[2,131,3,3,\"וְלַהַב חֶרֶב. רולימל״א בְּלַעַ״ז, כִּי סַכִּין וְחֶרֶב קָרוּי ׳לַהַב׳, כְּמוֹ (שם ד:כב) ״וַיָּבֹא הַנִּצָּב אַחַר הַלַּהַב״.\",1,0],[2,131,3,3,\"וּבְרַק חֲנִית. חֲנִית מְרוּטָה וּמַבְרֶקֶת, אוֹר יוֹצֵא מִמֶּנָּה, פלנדו״ר בְּלַעַ״ז.\",2,0],[2,131,3,3,\"וְכֹבֶד פָּגֶר. הָיוּ מַרְבִּים פְּגָרִים וְלֹא הָיָה חֶשְׁבּוֹן לִגְוִיּוֹת נִבְלוֹתֶיהָ הַמֻּשְׁלָכוֹת בָּהּ, עַד שֶׁהָיוּ הָעוֹבְרִים נִכְשָׁלִים בִּגְוִיּוֹת הַפְּגָרִים.\",3,0],[2,131,3,4,\"מֵרֹב זְנוּנֵי זוֹנָה. מֵרֹב חֲנוּפוֹת עִיר שֶׁהָיוּ יוֹדְעִים לְפַתּוֹת לֵב מַלְכֵי הָאָרֶץ לְהִתְחַבֵּר עִמָּם, וְסוֹף הָיוּ כּוֹבְשִׁים אוֹתָם תַּחְתֵּיהֶם.\",1,0],[2,131,3,5,\"שׁוּלַיִךְ. הֵם שִׁפּוּלֵי בִּגְדֵי הָאִשָּׁה.\",1,0],[2,131,3,5,\"מַעְרֵךְ. גִּלּוּיֵךְ, כְּמוֹ (מיכה א:יא) ״עֶרְיָה בֹשֶׁת״.\",2,0],[2,131,3,6,\"שִׁקֻּצִים. בְּגָדִים צוֹאִים הַמְנַוְּלִים אוֹתָךְ. לְפִי הָעִנְיָן שֶׁדִּמָּה אוֹתָהּ לְזוֹנָה, דִּבֵּר הַכָּתוּב.\",1,0],[2,131,3,6,\"כְּרֹאִי. כְּזֶבֶל, לְשׁוֹן ״וְהֵסִיר אֶת מֻרְאָתוֹ בְּנֹצָתָהּ״ (ויקרא א:טז).\",2,0],[2,131,3,7,\"יִדּוֹד מִמֵּךְ. יִתְרַחֵק מִמֵּךְ.\",1,0],[2,131,3,8,\"הֲתֵיטְבִי מִנֹּא אָמוֹן. וּמַה תִּבְטְחִי בְּעָשְׁרֵךְ וּבִגְבוּרָתֵךְ, וְכִי גְּדוֹלָה אַתְּ מִנֹּא, הִיא אֲלֶכְּסַנְדְּרִיָּה שֶׁל מִצְרַיִם, אָמוֹן לְשׁוֹן ׳פְּדַגוֹג׳, מִנֹּא הַגְּדוֹלָה שֶׁהָיְתָה אוֹמֶנֶת מַלְכֵי מִצְרַיִם, דִּמְרַבֵּי בָּהּ מַלְכּוּ.\",1,0],[2,131,3,8,\"אֲשֶׁר חֵיל יָם. אֲשֶׁר הָיָה הַיָּם לָהּ לְחַיִל וּלְחוֹמָה, שׁוּרָא וּבַר שׁוּרָא.\",2,0],[2,131,3,9,\"כּוּשׁ עָצְמָה. כּוּשִׁים הָיוּ לָהּ לְחֹזֶק.\",1,0],[2,131,3,9,\"פּוּט וְלוּבִים הָיוּ בְּעֶזְרָתֵךְ. וְהַפּוּטִים וְהַלּוּבִים אֲשֶׁר הָיוּ בְּעֶזְרָתֵךְ, גַּם הֵם הָיוּ בְּחֵילָהּ.\",2,0],[2,131,3,10,\"גַּם הִיא לַגּוֹלָה הָלְכָה. אַף הִיא הָלְכָה בַּגּוֹלָה, אַף עַל פִּי כֵן גְּדֻלָּתָהּ לֹא עָמְדָה לִפְנֵי נְבוּכַדְנֶצַּר.\",1,0],[2,131,3,10,\"רֻתְּקוּ. נִכְבְּלוּ, לְשׁוֹן ״רְתֻקוֹת כֶּסֶף״ (ישעיהו מ:יט), ״עֲשֵׂה הָרַתּוֹק״ (יחזקאל ז:כג), שַׁלְשְׁלָאוֹת.\",2,0],[2,131,3,10,\"בַּזִּקִּים. שַׁלְשְׁלָאוֹת.\",3,0],[2,131,3,11,\"גַּם אַתְּ. אַף לְפִי גְּדֻלָּתֵךְ תִּשְׁכְּרִי כְּמוֹתָהּ בְּכוֹס הַתַּרְעֵלָה וְתִהְיֶה נֶעֱלָמָה.\",1,0],[2,131,3,12,\"כָּל מִבְצָרַיִךְ תְּאֵנִים עִם בִּכּוּרִים. כָּל עָרֵי מִבְצָרֶיךָ יִהְיוּ נוֹחִים לִכָּבֵשׁ וְלָבֹז מַה שֶּׁבְּתוֹכָהּ, כְּאִילָנֵי תְאֵנִים, וּכְשֶׁהֵן עִם בִּכּוּרוֹת מְבֻשֶּׁלֶת שֶׁבָּהֶם, שֶׁכְּשֶׁמְּנִיעִים הָאִילָן נוֹפְלִים הַבִּכּוּרִים לְתוֹךְ פִּי הָאוֹכְלִים.\",1,0],[2,131,3,12,\"תְּאֵנִים. אִילָנֵי תְאֵנִים.\",2,0],[2,131,3,12,\"אִם יִנּוֹעוּ. אֲשֶׁר אִם יִנּוֹעוּ בְּיַד אָדָם בְּחָזְקָה.\",3,0],[2,131,3,14,\"מֵי מָצוֹר שַׁאֲבִי לָךְ. עִיר שֶׁבָּאִים לָצוּר עָלֶיהָ, אוֹסְפִים לָהֶם בְּנֵי הָעִיר מַיִם רַבִּים לְתוֹכָהּ בְּתוֹךְ חֲבִיּוֹת לִשְׁתּוֹת בִּימֵי הַמָּצוֹר, כְּשֶׁאֵין בְּתוֹכָהּ בּוֹרוֹת.\",1,0],[2,131,3,14,\"בֹּאִי בְּטִיט וְרִמְסִי. אוֹתוֹ לַעֲשׂוֹת מִמֶּנּוּ לְבֵנִים, כְּדֵי לְחַזֵּק בּוֹ בִּדְקֵי הַחוֹמוֹת.\",2,0],[2,131,3,14,\"הַחֲזִיקִי מַלְבֵּן. אַחֲזִי בְּיָדֵךְ הַמַּלְבֵּן הֶעָשׂוּי לִדְפוּס הַלְּבֵנִים לִלְבֹּן בְּתוֹכָהּ.\",3,0],[2,131,3,15,\"הִתְכַּבֵּד. בְּמַטְאֲטֵי הַשְׁמֵד.\",1,0],[2,131,3,15,\"כַּיֶּלֶק. הַגּוֹמֵר וּמְכַלֶּה כָּל יֶרֶק הַשָּׂדֶה, וְיֵשׁ פּוֹתְרִין ״הִתְכַּבֵּד כַּיֶּלֶק״ – תִּתְכַּסִּי בְּכֹבֶד גְּיָסוֹת כְּיֶלֶק, וְ״הִתְכַּבֵּד״ לְשׁוֹן עַם כָּבֵד.\",2,0],[2,131,3,16,\"יֶלֶק פָּשַׁט וַיָּעֹף. יִהְיוּ קַלִּים לָצֵאת בִּסְחוֹרָה כְּיֶלֶק שֶׁפּוֹשֵׁט וְעוֹף.\",1,0],[2,131,3,17,\"מִנְּזָרַיִךְ. שָׂרַיִךְ, וְהַמֵּ״ם יְסוֹד וְשֹׁרֶשׁ בַּתֵּיבָה, כְּמֵ״ם שֶׁל מִשְׁמַרְתְּךָ וְשֶׁל מִשְׁמַעְתֶּךָ וְשֶׁל מִנְעָלֶיךָ, וּפְעָמִים שֶׁהִיא נוֹפֶלֶת מִמֶּנָּה, כְּמוֹ ״נְזִיר אֶחָיו״ (בראשית מט:כו), וְכֵן ״נְזִירֶיהָ שָׂרֶיהָ״ (איכה ד:ז).\",1,0],[2,131,3,17,\"וְטַפְסְרַיִךְ. הַמְּמוּנִּים שֶׁלָּךְ.\",2,0],[2,131,3,17,\"כְּגוֹב גּוֹבָי. כְּחַיָּלֵי גּוֹבַאי גּוֹבָי, קומלנגשטדי״ץ בְּלַעַ״ז.\",3,0],[2,131,3,17,\"הַחוֹנִים בַּגְּדֵרוֹת בְּיוֹם קָרָה. כֵּן דֶּרֶךְ הָאַרְבֶּה וְהַזְּבוּב הֶחָסִיל וְהַיֶּלֶק בְּעֵת הַקֹּר נִדְבָּקִים בַּכְּתָלִים, וּכְשֶׁיָּבֹא חֹם הֵן נוֹדְדִים מִשָּׁם וְהוֹלְכִים לָהֶם, כָּךְ יִגְלוּ כָּל עַמֵּךְ.\",4,0],[2,131,3,17,\"וְנוֹדַד. וּמִטַּלְטֵל.\",5,0],[2,131,3,17,\"וְלֹא נוֹדַע מְקוֹמוֹ אַיָּם. אֵיפֹה הֵם וְאָנָה הָלְכוּ.\",6,0],[2,131,3,18,\"נָמוּ רֹעֶיךָ. לְשׁוֹן ׳תְּנוּמָה׳.\",1,0],[2,131,3,18,\"יִשְׁכְּנוּ. אֵין יְכוֹלִים לָקוּם.\",2,0],[2,131,3,18,\"נָפֹשׁוּ. כְּמוֹ ׳נָפֹצוּ׳, וְכָל הָאוֹתִיּוֹת הַיּוֹצֵאת מִמּוֹצָא אֶחָד מִתְחַלְּפוֹת זוֹ בָּזוֹ, זַיִ״ן שִׁי״ן סָמֶ״ךְ צָדִ״י, כֻּלָּן יוֹצְאִין מִסּוֹף הַלָּשׁוֹן וְשׁוּלֵי הַשִּׁנַּיִם.\",3,0],[2,131,3,19,\"אֵין כֵּהָה לְשִׁבְרֶךָ. אֵין מֵצֵר עַל שִׁבְרֶךָ, כִּי הַכֹּל שְׂמֵחִים. כֵּהָה לְשׁוֹן דָּבָר עָמוּם.\",1,0],[2,131,3,19,\"תָּקְעוּ כַף. לִשְׂמֹחַ.\",2,0],[2,132,1,1,\"דִּבְרֵי נְחֶמְיָה וְגוֹ׳. מִכָּאן וָאֵילָךְ כָּתַב נְחֶמְיָה סֵפֶר זֶה:\",1,0],[2,132,1,1,\"שְׁנַת עֶשְׂרִים. הִיא שְׁנַת עֶשְׂרִים לְדָרְיָוֶשׁ הַמֶּלֶךְ שֶׁהוּא אַרְתַּחְשַׁשְׂתָּא. וּבְמַסֶּכֶת רֹאשׁ הַשָּׁנָה מָצָאנוּ: שְׁנַת עֶשְׂרִים ״שְׁנַת עֶשְׂרִים״ לִגְזֵרָה שָׁוָה, מִן הַכָּתוּב שֶׁנֶּאֱמַר לְמַטָּה ״וַיְהִי בְחֹדֶשׁ נִיסָן שְׁנַת עֶשְׂרִים לְאַרְתַּחְשַׁשְׂתָּא וְגוֹ׳״ (נחמיה ב:א). וּמֵחֹדֶשׁ תִּשְׁרֵי הָיוּ מוֹנִין לְחֶשְׁבּוֹן הַשָּׁנִים, וְעַל כֵּן נֶאֱמַר כָּאן: וַיְהִי בְחֹדֶשׁ כִּסְלֵו שְׁנַת עֶשְׂרִים וְגוֹ׳, וְהוּא כִּסְלֵו הַבָּא לְאַחַר תִּשְׁרֵי, וּלְמַטָּה נֶאֱמַר ״וַיְהִי בְחֹדֶשׁ נִיסָן שְׁנַת עֶשְׂרִים וְגוֹמֵר״, הוּא נִיסָן שֶׁבְּאוֹתָהּ שָׁנָה. וְאֵינִי יָכוֹל לִפְתֹּר וְלוֹמַר מִנִּיסָן הָיוּ מוֹנִין לְחֶשְׁבּוֹן שְׁנוֹתֵיהֶם, וְאוֹתוֹ מַעֲשֶׂה הַכָּתוּב לְמַטָּה שֶׁנֶּאֱמַר ״וַיְהִי בְחֹדֶשׁ נִיסָן וְגוֹ׳״ הָיָה קֹדֶם מַעֲשֶׂה זֶה שֶׁנֶּאֱמַר וַיְהִי בְחֹדֶשׁ כִּסְלֵו שְׁנַת עֶשְׂרִים וְגוֹ׳, וְאֵין מֻקְדָּם וּמְאֻחָר בָּהֶם, דָּבָר זֶה אֵינִי יָכוֹל לִפְתֹּר וְלוֹמַר, וְהַפָּרָשִׁיּוֹת מוֹכִיחוֹת, שֶׁאַף אוֹתוֹ מַעֲשֶׂה שֶׁל פָּרָשָׁה שְׁנִיָּה לֹא הָיְתָה כִּי אִם בִּשְׁבִיל מַעֲשֶׂה זֶה שֶׁל פָּרָשָׁה זֹאת רִאשׁוֹנָה:\",2,0],[2,132,1,2,\"אֶחָד מֵאַחַי. אֶחָד מֵחֲבֵרַי:\",1,0],[2,132,1,2,\"וָאֶשְׁאָלֵם עַל הַיְּהוּדִים וְגוֹ׳. שָׁאַלְתִּי לָהֶם עַל עִנְיַן פְּלֵיטַת הַיְּהוּדִים אֲשֶׁר נִשְׁאֲרוּ בִּירוּשָׁלַיִם מִן הַשֶּׁבִי שֶׁל בָּבֶל:\",2,0],[2,132,1,2,\"הַפְּלֵיטָה. עַל שֵׁם שֶׁנִּצּוֹלוּ מִגָּלוּת בָּבֶל:\",3,0],[2,132,1,2,\"וְעַל יְרוּשָׁלִָם. וְעַל עִנְיַן הָעִיר שָׁאַלְתִּי אֲלֵיהֶם:\",4,0],[2,132,1,3,\"וַיֹּאמְרוּ לִי. הֵשִׁיבוּ לִי עַל רִאשׁוֹן רִאשׁוֹן וְעַל אַחֲרוֹן אַחֲרוֹן, תְּחִלָּה עַל עִנְיַן הַיְּהוּדִים וְאַחַר כָּךְ עַל עִנְיַן הַחוֹמוֹת וְהַשְּׁעָרִים:\",1,0],[2,132,1,3,\"הַנִּשְׁאָרִים וְגוֹ׳. אוֹתָם הַיְּהוּדִים אֲשֶׁר נִשְׁאֲרוּ שָׁם בִּמְדִינַת יְרוּשָׁלַיִם, הֵם נְתוּנִים בְּרָעָה גְדוֹלָה וּבְחֶרְפָּה, לְפִי שֶׁהָעוֹבְדֵי כוֹכָבִים בּוֹזְזִים וְשׁוֹלְלִים אוֹתָם:\",2,0],[2,132,1,3,\"וְחוֹמַת יְרוּשָׁלִַם מְפֹרָצֶת. וְחוֹמַת הָעִיר הֲרֵי הִיא פְּרוּצָה, וְהַשְּׁעָרִים שְׂרוּפִים בָּאֵשׁ כְּקַדְמָתָן; שֶׁיִּשְׂרָאֵל לֹא בָּנוּ חוֹמוֹת הָעִיר וּשְׁעָרֶיהָ כִּי אִם בִּנְיַן בֵּית הַמִּקְדָּשׁ לְבַדּוֹ:\",3,0],[2,132,1,3,\"נִצְּתוּ. כְּמוֹ נוּצְתוּ (ספרים אחרים: נִצְּתוּ כמו נִתְּצוּ):\",4,0],[2,132,1,4,\"יָמִים. כַּמָּה יָמִים:\",1,0],[2,132,1,5,\"אָנָּא. לְשׁוֹן בַּקָּשָׁה וּתְחִנָּה:\",1,0],[2,132,1,6,\"קַשֶּׁבֶת. כְּמוֹ קוֹשֶׁבֶת כּוּ׳, כַּאֲשֶׁר יֹאמַר מֵ״אָהַב״ (בראשית כז:ט) ״אוֹהֵב״ (שמואל א יח:טז), כֵּן יֹאמַר מִן קָשַׁב קוֹשֵׁב וְקוֹשֶׁבֶת:\",1,0],[2,132,1,7,\"חֲבוֹל. שֵׁם דָּבָר, לְשׁוֹן הַשְׁחָתָה. וְחֵי״ת נִנְקְדָה בַּחֲטַף פַּתָּח. וְאֵינִי יָכוֹל לְפוֹתְרוֹ בִּלְשׁוֹן פָּעוּל, שֶׁאִם כֵּן הָיָה לוֹ לִנְקֹד חֵי״ת בְּקָמַץ גָּדוֹל:\",1,0],[2,132,1,7,\"חָבַלְנוּ. לְשׁוֹן הַשְׁחָתָה, כְּמוֹ (דניאל ו:כג) ״חֲבוּלָא לָא עֲבַדְתְּ״, וְכֵן חִבְּרוֹ מְנַחֵם:\",2,0],[2,132,1,9,\"אִם יִהְיֶה נִדַּחֲכֶם. כְּעִנְיָן שֶׁנֶּאֱמַר: ״אִם יִהְיֶה נִדַּחֲךָ וְגוֹ׳״ (דְּבָרִים ל:ד):\",1,0],[2,132,1,11,\"אָנָּא אֲדֹנָי תְּהִי נָא אָזְנְךָ קַשֶּׁבֶת. בִּתְחִלַּת תְּפִלָּתוֹ אָמַר לָשׁוֹן זֶה שֶׁל תְּחִנָּה, וְכֵן לְאַחַר תְּפִלָּתוֹ:\",1,0],[2,132,1,11,\"לְעַבְדְּךָ הַיּוֹם וְגוֹ׳. כָּךְ הָיָה מִתְפַּלֵּל עַל עַצְמוֹ:\",2,0],[2,132,1,11,\"לִפְנֵי הָאִישׁ הַזֶּה. לִפְנֵי הַמֶּלֶךְ:\",3,0],[2,132,1,11,\"מַשְׁקֶה. כְּמוֹ (בראשית מ:א) ״מַשְׁקֵה לְמֶלֶךְ מִצְרָיִם״, וְזֶה שֶׁפֵּרַשְׁתִּי לְמַעְלָה (עזרא ב:סג). כְּדִבְרֵי רַבּוֹתֵינוּ: הַתִּרְשָׁתָא הוּא נְחֶמְיָה:\",4,0],[2,132,2,1,\"לְאַרְתַּחְשַׁסְתְּא. הוּא דָּרְיָוֶשׁ (עזרא ד:ה), וְעַל שֵׁם הַמַּלְכוּת נִקְרָא כָּךְ:\",1,0],[2,132,2,1,\"יַיִן לְפָנָיו. הֵבִיאוּ יַיִן לִפְנֵי הַמֶּלֶךְ בֶּחָצֵר:\",2,0],[2,132,2,1,\"וָאֶשָּׂא אֶת הַיַּיִן. וְאָנֹכִי נָשָׂאתִי אֶת כּוֹס הַיַּיִן וּנְתַתִּיהָ לַמֶּלֶךְ. וְכָךְ הוּא הַמִּנְהָג, שֶׁהַמֵּבִיא יַיִן בַּחֲצַר הַמֶּלֶךְ אֵינוֹ נוֹשֵׂא וְנוֹתְנוֹ לַמֶּלֶךְ, אֲבָל שַׂר הַמַּשְׁקִים מְקַבֵּל כּוֹס הַיַּיִן מִיַּד הַמֵּבִיא וְהוּא נוֹשֵׂא וְנוֹתְנוֹ לַמֶּלֶךְ:\",3,0],[2,132,2,1,\"לֹא הָיִיתִי רַע לְפָנָיו. וַאֲנִי לֹא הָיִיתִי רָגִיל לִהְיוֹת רַע לְפָנָיו בְּרוֹעַ פָּנִים, כִּי אִם שָׂמֵחַ וְטוֹב לֵב, וְעַתָּה הָיִיתִי זוֹעֵף בְּרוֹעַ פָּנִים:\",4,0],[2,132,2,2,\"וְאַתָּה אֵינְךָ חוֹלֶה. וַהֲרֵי אֵין אַתָּה חוֹלֶה:\",1,0],[2,132,2,2,\"אֵין זֶה. אֵין הַמַּעֲשֶׂה הַזֶּה כִּי אִם רֹעַ לֵב, שֶׁיֵּשׁ בִּלְבָבְךָ עָלַי לַהֲמִיתֵנִי בְּסַם הַמָּוֶת בִּשְׁתִיַּת כּוֹס זֶה:\",2,0],[2,132,2,2,\"וָאִירָא הַרְבֵּה מְאֹד. וְנִתְיָרֵאתִי מְאֹד עַל כָּךְ, שֶׁלֹּא יַעֲלִיל עָלַי הַמֶּלֶךְ עֲלִילָה:\",3,0],[2,132,2,3,\"מַדּוּעַ לֹא יֵרְעוּ פָנַי. מַדּוּעַ לֹא יִהְיוּ פָנַי רָעִים:\",1,0],[2,132,2,3,\"אֲשֶׁר הָעִיר יְרוּשָׁלַיִם, שֶׁהִיא בֵּית קִבְרוֹת אֲבוֹתַי, חֲרֵבָה:\",2,0],[2,132,2,4,\"עַל מַה זֶּה אַתָּה מְבַקֵּשׁ. אֵי זֶה דָּבָר תְּבַקֵּשׁ מִמֶּנִּי וְאֶעֱשֶׂה לְךָ:\",1,0],[2,132,2,4,\"וָאֶתְפַּלֵּל. וְאָמַרְתִּי לִפְנֵי הַמֶּלֶךְ בִּתְפִלָּתִי: כֵּן יְהִי רָצוֹן מִלְּפָנֵי אֱלֹהֵי הַשָּׁמָיִם, שֶׁתְּמַלֵּא שְׁאֵלָתִי וּבַקָּשָׁתִי:\",2,0],[2,132,2,5,\"אֲשֶׁר תִּשְׁלָחֵנִי. שֶׁתִּתֵּן לִי רְשׁוּת לַעֲלוֹת לִירוּשָׁלַיִם וְלִבְנוֹתָהּ:\",1,0],[2,132,2,6,\"וַיֹּאמֶר לִי הַמֶּלֶךְ. בְּשָׁעָה שֶׁדִּבֵּר אֵלַי הַמֶּלֶךְ הָיְתָה אִשְׁתּוֹ הַמַּלְכָּה יוֹשֶׁבֶת אֶצְלוֹ:\",1,0],[2,132,2,6,\"וְהַשֵּׁגַל. אִשְׁתּוֹ הַמַּלְכָּה, כְּעִנְיָן שֶׁנֶּאֱמַר (דניאל ה:ב) ״שֵׁגְלָתֵהּ וּלְחֵנָתֵהּ״. שֶׁכֵּן נוֹהֵג הַמִּקְרָא לִכְתֹּב הַמַּלְכָּה אֵצֶל הַפִּלֶגֶשׁ ״נָשָׁיו וּפִילַגְשָׁיו״ (דברי הימים ב יא:כא), כְּמוֹ ״מְלָכוֹת וּפִילַגְשִׁים״ (שיר השירים ו:ט):\",2,0],[2,132,2,6,\"עַד מָתַי יִהְיֶה מַהֲלָכְךָ. מָתַי תִּרְצֶה שֶׁיְּהֵא מַהֲלָכְךָ וּמַסָּעֲךָ?:\",3,0],[2,132,2,6,\"וּמָתַי תָּשׁוּב. וּמָתַי דַּעְתְּךָ לַחֲזוֹר?:\",4,0],[2,132,2,6,\"יִשְׁלָחֵנִי. נָתַן לִי רְשׁוּת לָלֶכֶת:\",5,0],[2,132,2,6,\"וָאֶתְּנָה לוֹ זְמָן. נָתַתִּי לוֹ זְמָן לַחֲזוֹר:\",6,0],[2,132,2,7,\"אִגְּרוֹת יִתְּנוּ לִי. סוֹפְרֶיךָ עַל רְשׁוּתְךָ וְדַעְתְּךָ, חֲתוּמוֹת בְּחוֹתָמְךָ, עַל פַּחֲוַת עֵבֶר הַנָּהָר שֶׁל צַד אֶרֶץ יִשְׂרָאֵל:\",1,0],[2,132,2,7,\"אֲשֶׁר יַעֲבִירוּנִי. וִיתַיְּרוּנִי לְשָׁלוֹם:\",2,0],[2,132,2,7,\"עַד אֲשֶׁר אָבוֹא. לִירוּשָׁלַיִם אֲשֶׁר בִּמְדִינַת יְהוּדָה:\",3,0],[2,132,2,8,\"וְאִגֶּרֶת אֶל אָסָף. וְתִשְׁלַח כְּתַב אִגֶּרֶת אֶל אָסָף:\",1,0],[2,132,2,8,\"שׁוֹמֵר הַפַּרְדֵּס. מְמֻנֶּה הָיָה עַל הַיְּעָרִים אֲשֶׁר לַמֶּלֶךְ:\",2,0],[2,132,2,8,\"לְקָרוֹת. מִשְׁקַל חָזָק לַעֲשׂוֹת תִּקְרוֹת וְקוֹרוֹת לְשַׁעֲרֵי בִּירוֹת הַר הַבַּיִת, שֶׁהֲרֵי בֵּית הַמִּקְדָּשׁ בָּנוּ בְּבִנְיָנוֹ, אֲבָל שַׁעֲרֵי חוֹמוֹת הַר הַבַּיִת וְחוֹמַת הֶחָצֵר אֲשֶׁר סָבִיב בֵּית הַמִּקְדָּשׁ לֹא בָּנוּ עֲדַיִן:\",3,0],[2,132,2,8,\"וּלְחוֹמַת הָעִיר. וְלַעֲשׂוֹת קוֹרוֹת לְחוֹמַת הָעִיר:\",4,0],[2,132,2,8,\"וְלַבַּיִת אֲשֶׁר אָבוֹא אֵלָיו. וְלַעֲשׂוֹת בַּיִת אֲשֶׁר אֵשֵׁב בּוֹ לְצָרְכִּי:\",5,0],[2,132,2,8,\"וַיִּתֶּן לִי הַמֶּלֶךְ. אֶת כָּל אֲשֶׁר שָׁאַלְתִּי מִמֶּנּוּ:\",6,0],[2,132,2,8,\"כְּיַד. כְּפִי יָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָיְתָה טוֹבָה עָלָי לְהַצְלִיחֵנִי:\",7,0],[2,132,2,9,\"וָאֶתְּנָה לָהֶם אֵת אִגְּרוֹת הַמֶּלֶךְ. לְמַעַן יְתַיְּרוּנִי לְשָׁלוֹם:\",1,0],[2,132,2,9,\"שָׂרֵי חַיִל וּפָרָשִׁים. שָׁלַח הַמֶּלֶךְ עִמִּי לִכְבוֹדִי, לְמַעַן אֵלֵךְ לְשָׁלוֹם:\",2,0],[2,132,2,10,\"וַיִּשְׁמַע סַנְבַלַּט וְגוֹ׳. כַּאֲשֶׁר שָׁמְעוּ שֶׁבָּאתִי לְבַקֵּשׁ טוֹבָה עַל יִשְׂרָאֵל וְלִבְנוֹת חוֹמוֹת יְרוּשָׁלַיִם, וַיֵּרַע בְּעֵינֵיהֶם, כִּי הָיוּ צָרֵי יְהוּדָה וּבִנְיָמִין (עזרא ד:א):\",1,0],[2,132,2,11,\"וָאֱהִי שָׁם יָמִים שְׁלֹשָׁה. הָיִיתִי בִּירוּשָׁלַיִם יָמִים שְׁלֹשָׁה וּלְסוֹף שְׁלֹשֶׁת יָמִים קַמְתִּי בַלַּיְלָה אֲנִי וַאֲנָשִׁים מְעַטִּים עִמִּי וְלֹא הִגַּדְתִּי לְשׁוּם אָדָם אֶת אֲשֶׁר נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא בְּלִבִּי:\",1,0],[2,132,2,12,\"וּבְהֵמָה אֵין עִמִּי. כִּי כָל הָאֲנָשִׁים מוּעָטִים אֲשֶׁר עִמִּי הָלְכוּ בְרַגְלֵיהֶם, אֲבָל אֲנִי לְבַדִּי הָיִיתִי רוֹכֵב עַל בְּהֵמָה; שֶׁלֹּא הָיוּ רוֹצִים לִרְכֹּב עַל סוּסֵיהֶם, לְמַעַן יִהְיוּ יוֹצְאִים מִן הָעִיר בְּצִנְעָא, בְּלֹא יְדִיעַת אָדָם. וְהֵם הָלְכוּ לִשְׁבֹּר וּלְהַפִּיל חוֹמוֹת הָעִיר בַּלַּיְלָה, וּלְהַרְבּוֹת פִּרְצוֹתֶיהָ, לְמַעַן יִהְיוּ בְּנֵי הָעִיר לְמָחָר לְהוּטִים וּמַסְכִּימִים בְּעֵצָה אַחַת עִם נְחֶמְיָה לִבְנוֹת חוֹמוֹת הָעִיר, וְכֵן מוֹכִיחַ הַמַּעֲשֶׂה בְּתוֹךְ הַפָּרָשָׁה:\",1,0],[2,132,2,13,\"וָאֵצְאָה בְשַׁעַר הַגַּיְא. יָצָאתִי בְּאוֹתוֹ שַׁעַר בַּלַּיְלָה עִם הָאֲנָשִׁים אֲשֶׁר עִמִּי לְצַד אוֹתוֹ מָקוֹם שֶׁל עֵין הַתַּנִּין וּלְאוֹתוֹ שַׁעַר הָאַשְׁפֹּת שֶׁבְּחוֹמוֹת הָעִיר. וְהָיִיתִי פּוֹרֵץ בַּחוֹמָה, וְהַחוֹמָה הָיְתָה נוֹחָה לְהַפִּילָהּ וְלִפְרֹץ בָּהּ לְפִי שֶׁהָיְתָה שְׂרוּפָה בָאֵשׁ:\",1,0],[2,132,2,13,\"אֲשֶׁר הֵם פְּרוּצִים. שֶׁהֵם אוֹתָם מְקוֹמוֹת שֶׁהָיוּ פְּרוּצִים וְהֵם פָּרְצוּ בָּהֶם יוֹתֵר:\",2,0],[2,132,2,14,\"וָאֶעֱבֹר אֶל שַׁעַר הָעַיִן. וְרָצִיתִי לַעֲבֹר אֶל אוֹתָן מְקוֹמוֹת שֶׁבְּחוֹמַת הָעִיר וּבְאוֹתָן פְּרָצוֹת, וְאֵין מָקוֹם בְּאוֹתָן פְּרָצוֹת לַעֲבֹר בֵּינֵיהֶם רוֹכֵב עַל הַבְּהֵמוֹת, שֶׁהָיוּ פְּרָצוֹת קְטַנּוֹת:\",1,0],[2,132,2,15,\"וָאֱהִי עוֹלֶה. וְהָיִיתִי עוֹלֶה מִצַּד אֶחָד בַּלַּיְלָה, וְהָיִיתִי שׁוֹבֵר בַּחוֹמָה עִם הָאֲנָשִׁים אֲשֶׁר עִמִּי:\",1,0],[2,132,2,15,\"וָאָשׁוּב וָאָבוֹא. וְכַאֲשֶׁר חָזַרְתִּי בָּאתִי דֶּרֶךְ שַׁעַר הַגַּיְא:\",2,0],[2,132,2,16,\"וְהַסְּגָנִים. אֲשֶׁר בָּעִיר, לֹא הָיוּ יוֹדְעִין לְהֵיכָן הָלַכְתִּי וְאֶת הַמַּעֲשֶׂה אֲשֶׁר עָשִׂיתִי׃\",1,0],[2,132,2,16,\"עַד כֵּן. עַד עַתָּה:\",2,0],[2,132,2,17,\"וָאוֹמַר אֲלֵיהֶם. לְמָחָר אָמַרְתִּי לָהֶם:\",1,0],[2,132,2,17,\"וְלֹא נִהְיֶה עוֹד חֶרְפָּה. שֶׁלֹּא יִהְיוּ צָרֵינוּ בּוֹזְזִים וְשׁוֹלְלִים אוֹתָנוּ:\",2,0],[2,132,2,18,\"אֶת יַד אֱלֹהַי. אֲשֶׁר נָתַן לִי חֵן וְהַצְלָחָה לִפְנֵי הַמֶּלֶךְ:\",1,0],[2,132,2,18,\"לַטּוֹבָה. הַכֹּל נִתְכַּוְּנוּ לְטוֹבָה, לִבְנוֹת חוֹמַת הָעִיר וּמִגְדָּלֶיהָ:\",2,0],[2,132,2,19,\"וַיַּלְעִיגוּ. כַּאֲשֶׁר שָׁמְעוּ הַצָּרִים שְׁמוּעַת בִּנְיַן חוֹמַת הָעִיר, הָיוּ מַלְעִיגִים עָלֵינוּ:\",1,0],[2,132,2,19,\"הֲעַל הַמֶּלֶךְ. אִם עַל הַמֶּלֶךְ אַתֶּם מוֹרְדִים לִבְנוֹת חוֹמַת הָעִיר כְּדֵי לִמְרוֹד בּוֹ:\",2,0],[2,132,2,20,\"וְלָכֶם אֵין חֵלֶק. מַה לָּכֶם בְּבִנְיַן חוֹמַת הָעִיר הַזֹּאת כִּי אֵין לָכֶם חֵלֶק בָּהּ:\",1,0],[2,132,3,1,\"שַׁעַר הַצֹּאן. כָּךְ שְׁמוֹ שֶׁל שַׁעַר:\",1,0],[2,132,3,1,\"הֵמָּה קִדְּשׁוּהוּ. לְאוֹתוֹ שַׁעַר בִּקְדֻשַּׁת הָעִיר:\",2,0],[2,132,3,1,\"דַּלְתוֹתָיו. שֶׁל שַׁעַר:\",3,0],[2,132,3,1,\"וְעַד מִגְדַּל הַמֵּאָה. כָּךְ שְׁמוֹ שֶׁל מִגְדָּל:\",4,0],[2,132,3,2,\"וְעַל יָדוֹ. אֵצֶל יָדוֹ, בְּסָמוּךְ לוֹ שֶׁל כָּל בּוֹנֶה וּבוֹנֶה שֶׁבָּנוּ אוֹתוֹ בְּבִנְיָן שֶׁל שַׁעַר הַצֹּאן:\",1,0],[2,132,3,2,\"בָּנוּ אַנְשֵׁי יְרֵחוֹ. שֶׁכָּךְ הָיוּ מִנְהָגָם: הַלָּלוּ הָיוּ בּוֹנִים כָּאן בְּחוֹמַת הָעִיר עַד תַּשְׁלוּם בִּנְיָנָהּ הַמּוּטָל עֲלֵיהֶם, וְהָאֲחֵרִים הָיוּ בּוֹנִים סָמוּךְ לַבִּנְיָן הָרִאשׁוֹן, וְכָךְ הָיָה מִנְהָגָם בָּזֶה אַחַר זֶה עַד שֶׁנִּבְנֵית כָּל הַחוֹמָה:\",2,0],[2,132,3,2,\"וְעַל. כְּמוֹ (במדבר ב:כ) ״וְעָלָיו מַטֵּה מְנַשֶּׁה״, בְּסָמוּךְ, וְכֵן פִּתְרוֹנוֹ: סָמוּךְ לְבִנְיָן יָדוֹ. וְהַמִּקְרָא לֹא דִקְדֵּק בִּלְשׁוֹנוֹ, פְּעָמִים שֶׁהוּא אוֹמֵר: עַל יָדוֹ, וּפְעָמִים שֶׁהוּא אוֹמֵר: עָלָיו, וְאַחֲרָיו הֶחֱזִיק:\",3,0],[2,132,3,3,\"וְאֵת שַׁעַר הַדָּגִים. כָּךְ שֵׁם הַשַּׁעַר:\",1,0],[2,132,3,3,\"הֵמָּה קֵרוּהוּ. נָתְנוּ הַקּוֹרוֹת וְתִקְרוֹת עַל הַשַּׁעַר:\",2,0],[2,132,3,3,\"קֵרוּהוּ. מִשְׁקָל חָזָק, כְּמוֹ מִן קָרָה, דּוּגְמַת ״הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו״ (תהילים קד:ג). וְקוּ״ף שֶׁל קֵרוּהוּ אֵינָהּ נְהוּגָה לִינָּקֵד בְּחִירִ״ק בְּעִנְיָן זֶה מִפְּנֵי רֵי״שׁ שֶׁל אַחֲרֶיהָ, כְּמוֹ ״בֵּרַךְ״ (תהילים י:ג), ״חֵרֵף עֹשֵׂהוּ״ (משלי יז:ה), ״וּבֵרַכְתִּיהָ וְהָיְתָה לְגוֹיִם״ (בראשית יז:טז), ״וְזֵרִיתִים בָּאֲרָצוֹת״ (יחזקאל כט:יב):\",3,0],[2,132,3,3,\"מַנְעוּלָיו. מַסְגְּרָיו שֶׁשְׁוִירְלָ״ץ בְּלַעַ״ז:\",4,0],[2,132,3,4,\"הֶחֱזִיק. לִבְנוֹת הַבִּנְיָן:\",1,0],[2,132,3,5,\"הַתְּקוֹעִים. כָּךְ הָיוּ נִקְרָאִים עַל שֵׁם מְקוֹמָם שֶׁהָיָה תְּקוֹעַ:\",1,0],[2,132,3,5,\"אַדִּירֵיהֶם. עֲשִׁירִים שֶׁל תְּקוֹעַ:\",2,0],[2,132,3,5,\"לֹא הֵבִיאוּ צַוָּרָם. לֹא סִיְּעוּ בַּעֲבוֹדָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, לִבְנוֹת חוֹמַת הָעִיר:\",3,0],[2,132,3,6,\"וְאֵת שַׁעַר הַיְשָׁנָה. כָּךְ שְׁמָהּ:\",1,0],[2,132,3,7,\"לְכִסֵּא פַּחַת עֵבֶר הַנָּהָר. כִּסֵּא אֶחָד בָּנָה כְּדֵי לֵישֵׁב בּוֹ אוֹתוֹ פַּחַת שֶׁל עֵבֶר הַנָּהָר:\",1,0],[2,132,3,8,\"צוֹרְפִים. אוֹתָהּ מִשְׁפָּחָה הָיְתָה נִקְרֵאת עַל שֵׁם אוּמָּנוּתָם:\",1,0],[2,132,3,8,\"וַיַּעַזְבוּ יְרוּשָׁלִַם. מִלְּאוּהָ עָפָר עַד הַחוֹמָה הָרְחָבָה, כְּדֵי לְהַחֲזִיקָהּ:\",2,0],[2,132,3,9,\"שַׂר חֲצִי פֶּלֶךְ יְרוּשָׁלִָם. שַׂר הָיָה עַל חֲצִי הָעָם שֶׁבִּירוּשָׁלַיִם, פֶּלֶךְ לְשׁוֹן דֻּכָּסוּת וּמַלְכוּת:\",1,0],[2,132,3,10,\"וְנֶגֶד בֵּיתוֹ. נָפַל חֶלְקוֹ לִבְנוֹת שֶׁהָיָה בֵּיתוֹ סָמוּךְ לְאוֹתוֹ מָקוֹם שֶׁל חוֹמַת הָעִיר:\",1,0],[2,132,3,11,\"מִדָּה שֵׁנִית. כְּאוֹתָהּ מִדָּה אֲשֶׁר בָּנָה חֲבֵירוֹ שֶׁל מַעְלָה, גַּם הוּא בָּנָה כְּמוֹתוֹ, מִדָּה שֵׁנִית בְּבִנְיַן הַחוֹמָה. אֵינוֹ נוֹפֵל לוֹמַר לְשׁוֹן מִדָּה בְּבִנְיַן הַשְּׁעָרִים, לְפִי שֶׁאֵין לָהֶם כִּי אִם בְּבִנְיַן חֵלֶק שֶׁל חוֹמָה, שֶׁלֹּא מָצִינוּ בְּכָל הַפָּרָשָׁה בְּבִנְיַן הַשְּׁעָרִים לְשׁוֹן מִדָּה:\",1,0],[2,132,3,11,\"וְאֵת מִגְדַּל הַתַּנּוּרִים. גַּם הוּא בָּנָה אוֹתוֹ מִגְדָּל שֶׁשְּׁמוֹ כָּךְ. כָּל הַמִּגְדָּלִים הַלָּלוּ שֶׁבַּפָּרָשָׁה הָיוּ בְנוּיִים בְּחוֹמַת הָעִיר סָבִיב:\",2,0],[2,132,3,12,\"הוּא וּבְנוֹתָיו. שַׁלּוּם וּבְנוֹתָיו הֶחֱזִיקוּ לִבְנוֹת הַבִּנְיָן:\",1,0],[2,132,3,13,\"עַד שַׁעַר הַשְּׁפוֹת. וְשַׁעַר הָאַשְׁפּוֹת לֹא הָיָה בִּכְלָל:\",1,0],[2,132,3,15,\"שַׂר פֶּלֶךְ הַמִּצְפָּה. שַׂר וְדֻוכּוֹס הַמִּצְפָּה:\",1,0],[2,132,3,15,\"הוּא יִבְנֶנּוּ. הוּא הָיָה בּוֹנֶה אוֹתוֹ שַׁעַר:\",2,0],[2,132,3,15,\"וִיטַלְלֶנּוּ. וְהוּא הָיָה מְסַכֵּךְ אוֹתוֹ, לְשׁוֹן מְטַלַלְתָּא:\",3,0],[2,132,3,15,\"וְאֵת חוֹמַת בְּרֵכַת הַשֶּׁלַח. שֶׁהוּא נוֹטֶה לְצַד גַּן הַמֶּלֶךְ:\",4,0],[2,132,3,15,\"וְעַד הַמַּעֲלוֹת. הֵם הָיוּ מַכִּירִים מְקוֹמוֹת הַלָּלוּ:\",5,0],[2,132,3,16,\"בֵּית צוּר. שֵׁם מָקוֹם:\",1,0],[2,132,3,17,\"לְפִלְכּוֹ. מֵאוֹתָהּ שְׂרָרָה חֲצִי פֶלֶךְ בָּנָה בִּנְיָן זֶה. לְפִלְכּוֹ כָּ״ף דְּגוּשָׁה, כַּאֲשֶׁר יֹאמַר מִן מֶלֶךְ מַלְכּוֹ, מִן עֶבֶד עַבְדּוֹ, כֵּן יֹאמַר מִן פֶּלֶךְ פִּלְכּוֹ; שֶׁאוֹת אַחֲרוֹנָה שֶׁל שֵׁם דָּבָר מֵאוֹתִיּוֹת בג״ד כפ״ת דְּגוּשׁוֹת:\",1,0],[2,132,3,18,\"אֲחֵיהֶם. הַלְוִיִּם:\",1,0],[2,132,3,19,\"מִנֶּגֶד עֲלוֹת הַנֶּשֶׁק. כְּנֶגֶד אוֹתוֹ מָקוֹם שֶׁהָיוּ עוֹלִים הַגִּבּוֹרִים אֶל הַנֶּשֶׁק. לְפִי פְּשׁוּטוֹ שֶׁל מִקְרָא נִרְאֶה שֶׁהָיָה שָׁם מָקוֹם אֶחָד בְּסָמוּךְ לַחוֹמָה וּכְלֵי זַיִן שֶׁל נֶשֶׁק הַגִּבּוֹרִים הָיוּ נוֹתְנִין (ספרים אחרים: נְתוּנִים) שָׁם כְּעִנְיָן שֶׁנֶּאֱמַר ״עָרֵי מִבְצָר וְהַנֶּשֶׁק״ (מלכים ב י:ב):\",1,0],[2,132,3,19,\"הַמִּקְצוֹעַ. לְקֶרֶן זָוִית שֶׁל חוֹמָה׃\",2,0],[2,132,3,20,\"הֶחֱרָה. פִּתְרוֹנוֹ לְפִי עִנְיָנוֹ, וְכֶפֶל לָשׁוֹן הוּא עַל הַחִזּוּק:\",1,0],[2,132,3,21,\"מִפֶּתַח בֵּית אֶלְיָשִׁיב וְעַד תַּכְלִית וְגוֹ׳. מִנֶּגֶד אוֹתוֹ בַּיִת בָּנָה בִּנְיָנוֹ:\",1,0],[2,132,3,23,\"נֶגֶד בֵּיתָם. שֶׁהָיָה שָׁם בְּסָמוּךְ לַחוֹמָה:\",1,0],[2,132,3,25,\"וְהַמִּגְדָּל הַיּוֹצֵא. מִגְדָּל אֶחָד הָיָה בַּחוֹמָה שֶׁהוּא יוֹצֵא וּבוֹלֵט מִבִּפְנִים:\",1,0],[2,132,3,26,\"וְהַנְּתִינִים הָיוּ יֹשְׁבִים בָּעֹפֶל. וְהַנְּתִינִים הָיוּ יוֹשְׁבִים בְּאוֹתוֹ מָחוֹז, וְהָיוּ בּוֹנִים אוֹתוֹ מָחוֹז שֶׁלָּהֶם שֶׁהָיָה סָמוּךְ לַחוֹמָה עַד נֶגֶד שַׁעַר הַמַּיִם שֶׁל צַד הַמִּזְרָח:\",1,0],[2,132,3,28,\"אִישׁ לְנֶגֶד בֵּיתוֹ. כָּל אֶחָד הָיָה בּוֹנֶה כְּנֶגֶד בֵּיתוֹ:\",1,0],[2,132,3,30,\"וְחָנוּן בֶּן צָלָף הַשִּׁשִּׁי. בָּנִים הַרְבֵּה הָיוּ לוֹ לְצָלָף, וְחָנוּן הוּא הַשִּׁשִּׁי:\",1,0],[2,132,3,30,\"מִדָּה שֵׁנִי. כְּמוֹ ״שֵׁנִית״ (נחמיה ג:כז):\",2,0],[2,132,3,30,\"נִשְׁכָּתוֹ. כְּמוֹ לִשְׁכָּתוֹ, לִשְׁכָּה אַחַת הָיְתָה לוֹ שָׁם סָמוּךְ לַחוֹמָה:\",3,0],[2,132,3,31,\"בֶּן הַצּוֹרְפִי. אִישׁ הַצּוֹרֵף, וְנִקְרָא שֶׁל שֵׁם אוּמָנוּתוֹ:\",1,0],[2,132,3,32,\"וּבֵין עֲלִיַּת הַפִּנָּה לְשַׁעַר הַצֹּאן. תְּחִלַּת הַבִּנְיָן הִתְחִילוּ לִבְנוֹת שַׁעַר הַצֹּאן, שֶׁנֶּאֱמַר ״וַיִּבְנוּ אֶת שַׁעַר הַצֹּאן וְגוֹ׳״ (נחמיה ג:א). כָּךְ הָיוּ בּוֹנִין הַחוֹמָה מִסָּבִיב בָּזֶה אַחַר זֶה:\",1,0],[2,132,3,34,\"לִפְנֵי אֶחָיו וְחֵיל שֹׁמְרוֹן. לִפְנֵי חֲבֵירָיו וְחֵיל שֹׁמְרוֹן שֶׁהָיוּ צָרֵי יְהוּדָה:\",1,0],[2,132,3,34,\"מָה הַיְּהוּדִים. מַדּוּעַ הַיְּהוּדִים כָּךְ הֵם עוֹשִׂים?:\",2,0],[2,132,3,34,\"הָאֲמֵלָלִים. עִנְיַן חֲלָשׁוּת וְרִפְיוֹן:\",3,0],[2,132,3,34,\"הֲיַעַזְבוּ לָהֶם. וְכִי הֵם סְבוּרִים אֲשֶׁר יַעַזְבוּ וְיַנִּיחוּ לָהֶם הָעוֹבְדֵי כוֹכָבִים לִבְנוֹת?:\",4,0],[2,132,3,34,\"הֲיִזְבָּחוּ. אִם יִזְבְּחוּ לָהֶם אֶת זִבְחֵיהֶם תָּמִיד כְּמוֹ שֶׁהֵם סְבוּרִים:\",5,0],[2,132,3,34,\"הַיְכַלּוּ בַיּוֹם. אִם יְכַלּוּ וְיַשְׁלִימוּ מְלַאכְתָּם אֲשֶׁר הִתְחִילוּ בְּיוֹם א׳? לוֹמַר שֶׁלֹּא יַנִּיחוּם הָעוֹבְדֵי כוֹכָבִים לִגְמֹר אֶת בִּנְיָנָם:\",6,0],[2,132,3,34,\"הֲיְחַיּוּ. אִם יְחַיּוּ וִיתַקְּנוּ וְיַחֲזִירוּ הָאֲבָנִים לְקַדְמָתָן לִהְיוֹת קָשׁוֹת וַחֲזָקוֹת מִן הֶעָפָר:\",7,0],[2,132,3,34,\"מֵעֲרֵמוֹת. עִנְיַן חֳמָרִים וְתִלִּים:\",8,0],[2,132,3,34,\"וְהֵמָּה שְׂרוּפוֹת. וְהָאֲבָנִים הָיוּ שְׂרוּפוֹת וְנַעֲשֵׂית עָפָר. כָּךְ הָיוּ מַלְעִיגִים וּמִתְלוֹצְצִים עַל בִּנְיַן הַחוֹמָה, שֶׁהָיוּ בּוֹנִין מִן הָאֲבָנִים שְׂרוּפוֹת שֶׁנָּפְלוּ לָאָרֶץ מִן הָאֵשׁ כַּאֲשֶׁר נִשְׂרְפָה יְרוּשָׁלָיִם:\",9,0],[2,132,3,35,\"וְטוֹבִיָּה הָעַמּוֹנִי אֶצְלוֹ. טוֹבִיָּה הָיָה אֶצְלוֹ שֶׁל סַנְבַלָּט:\",1,0],[2,132,3,35,\"וַיֹּאמֶר. וְכָךְ הָיָה אוֹמֵר וּמַלְעִיג:\",2,0],[2,132,3,35,\"גַּם אֲשֶׁר הֵם בּוֹנִים. אַף הַבִּנְיָן הַזֶּה אֲשֶׁר הֵם בּוֹנִים:\",3,0],[2,132,3,35,\"אִם יַעֲלֶה שׁוּעָל. עַל הַבִּנְיָן לִפְרֹץ חוֹמַת הָעִיר, מַה יְּהֵא עָלָיו? לוֹמַר שֶׁאֵין לַבִּנְיָן תַּקָּנָה, וְכָל מִי שֶׁיִּרְצֶה יָבֹא וְיִפְרֹץ בּוֹ:\",4,0],[2,132,3,36,\"שְׁמַע אֱלֹהֵינוּ. כַּאֲשֶׁר שָׁמַעְתִּי בְּלַעֲגָם עָלֵינוּ הִתְפַּלַּלְתִּי תְּפִלָּה זֹאת:\",1,0],[2,132,3,36,\"בְּאֶרֶץ שִׁבְיָה. שֶׁיִּגְלוּ מֵעַל אַדְמָתָם כַּאֲשֶׁר גָּלִינוּ:\",2,0],[2,132,3,37,\"וְאַל תְּכַס. כְּמוֹ וְאַל תְּכַסֶּה, דּוּגְמַת ״וְסוֹד אַחֵר אַל תְּגַל״ (משלי כה:ט), כְּמוֹ אַל תְּגַלֶּה:\",1,0],[2,132,3,37,\"כִּי הִכְעִיסוּ. אֲשֶׁר הִכְעִיסוּ נֶגֶד הַבּוֹנִים לְהַלְעִיגָם:\",2,0],[2,132,3,38,\"וַתִּקָּשֵׁר. כַּאֲשֶׁר נִתְקַשְּׁרָה הַחוֹמָה וְנִבְנֵית עַד חֶצְיָהּ, אָז הָיָה לֵב הָעָם לָהוּט וּמָשׁוּךְ לַעֲשׂוֹת בִּנְיַן הַחוֹמָה:\",1,0],[2,132,4,1,\"כִּי עָלְתָה אֲרוּכָה. שֶׁנִּבְנְתָה הַחוֹמָה:\",1,0],[2,132,4,1,\"אֲרוּכָה. עִנְיַן חוֹבֶשׁ וּתְרוּפָה:\",2,0],[2,132,4,1,\"כִּי הֵחֵלּוּ הַפְּרוּצִים לְהִסָּתֵם. אֲשֶׁר הִתְחִילוּ אַנְשֵׁי הָעִיר שֶׁהָיוּ פְּרוּצִים עַד עַתָּה מֵאֵין חוֹמָה הָיוּ עַתָּה סְתוּמִים בְּבִנְיַן הַחוֹמָה:\",3,0],[2,132,4,2,\"וְלַעֲשׂוֹת לוֹ תּוֹעָה. לַעֲשׂוֹת לוֹ בְּבִנְיַן הַחוֹמָה קִלְקוּל וְהַשְׁחָתָה. תּוֹעָה כְּמוֹ ״וּלְדַבֵּר אֶל ה׳ תּוֹעָה״ (ישעיהו לב:ו):\",1,0],[2,132,4,3,\"עֲלֵיהֶם. עַל הַבּוֹנִים:\",1,0],[2,132,4,3,\"מִפְּנֵיהֶם. מִפְּנֵי הָאוֹיְבִים:\",2,0],[2,132,4,4,\"וַיֹּאמֶר יְהוּדָה. כָּךְ הָיוּ אוֹמְרִים וּמִתְאוֹנְנִים אַנְשֵׁי יְהוּדָה:\",1,0],[2,132,4,4,\"כָּשַׁל כֹּחַ הַסַּבָּל. הַסּוֹבְלִים וְעוֹמְסִים הָאֲבָנִים וְהָעֵצִים לְבִנְיַן הַחוֹמָה נִכְשְׁלוּ בְכֹחָם, שֶׁאֵין בָּהֶם כֹּחַ לִבְנוֹת מִפְּנֵי הָאוֹיְבִים:\",2,0],[2,132,4,4,\"וְעָפָר הַרְבֵּה. עֲדַיִן יֵשׁ טִיט וְחֹמֶר הַרְבֵּה לִיתֵּן בְּבִנְיַן הַחוֹמָה, לוֹמַר שֶׁעֲדַיִן הַמְּלָאכָה גְּדוֹלָה עָלֵינוּ לִבְנוֹת, וַאֲנַחְנוּ לֹא נוּכַל לִבְנוֹת בַּחוֹמָה מִפְּנֵי פַּחַד הָאוֹיְבִים:\",3,0],[2,132,4,5,\"וַיֹּאמְרוּ צָרֵינוּ. כָּךְ הָיָה נְחֶמְיָה מְסַפֵּר וְהוֹלֵךְ:\",1,0],[2,132,4,5,\"לֹא יֵדְעוּ וְלֹא יִרְאוּ. כָּךְ הָיוּ אוֹמְרִים צָרֵינוּ עָלֵינוּ: לֹא יֵדְעוּ וְלֹא יַכִּירוּ יִשְׂרָאֵל בָּנוּ עַד אֲשֶׁר נָבוֹא פִּתְאוֹם לְתוֹכָם וְנַהֲרֹג אוֹתָם, וּבְדָבָר זֶה נִשְׁבֹּת וּנְבַטֵּל הַבִּנְיָן:\",2,0],[2,132,4,6,\"וַיְהִי כַּאֲשֶׁר בָּאוּ הַיְּהוּדִים. וְעַתָּה נֶאֶסְפוּ הַצָּרִים אֲשֶׁר נִתְקַשְּׁרוּ יַחַד לָבֹא לְהִלָּחֵם בָּנוּ עִם הַיְּהוּדִים אֲשֶׁר הָיוּ בֵּינוֹתָם בְּאַרְצוֹתָם, וְאוֹתָם הַיְּהוּדִים אֲשֶׁר נִתְחַבְּרוּ עִמָּהֶם בָּאוּ לִפְנֵי הַחַיִל כְּדֶרֶךְ אַנְשֵׁי הַמִּלְחָמָה לְדַבֵּר אֵלֵינוּ. וּבָעִנְיָן הַזֶּה הֶעֱרִימוּ הַיְּהוּדִים אֶת הָאוֹיְבִים וַיְהִי כַּאֲשֶׁר בָּאוּ הַיְּהוּדִים הַיּוֹשְׁבִים אֶצְלָם וְגוֹ׳:\",1,0],[2,132,4,6,\"וַיֹּאמְרוּ לָנוּ עֶשֶׂר פְּעָמִים. הִתְרוּ בָּנוּ אוֹתָם הַיְּהוּדִים עַד עֶשֶׂר פְּעָמִים לְהִלָּחֵם בְּאוֹיְבֵינוּ כִּי הֵם בָּאִים לַמִּלְחָמָה, וְכָךְ אָמְרוּ לָנוּ: מִכָּל הַמְּקוֹמוֹת וְגוֹ׳ מִכָּל אוֹתָן הַמְּקוֹמוֹת שֶׁתִּהְיוּ נְפוֹצִים שָׁם בְּבִנְיַן הַחוֹמָה אָנָה וָאָנָה, תִּהְיוּ זְהִירִים לִהְיוֹת נֶאֱסָפִים יַחַד עַד אֲשֶׁר תָּשׁוּבוּ עָלֵינוּ בְּיַחַד לְהִלָּחֵם בָּנוּ:\",2,0],[2,132,4,7,\"וָאַעֲמִיד מִתַּחְתְּיוֹת. לַחוֹמָה, כַּאֲשֶׁר שָׁמַעְתִּי דִּבְרֵיהֶם הֶעֱמַדְתִּי מִתַּחְתְּיוֹת לְאוֹתוֹ מָקוֹם סָבִיב לִירוּשָׁלַיִם מֵאֲחוֹרֵי לְחוֹמַת הָעִיר בַּצְּחִיחִים:\",1,0],[2,132,4,7,\"לְמִשְׁפָּחוֹת. מִן הָעָם מִגִּבּוֹרִים שֶׁבָּהֶם, עִם כְּלֵי זַיִן שֶׁבָּהֶם, לְהִלָּחֵם בְּאוֹיְבֵינוּ כַּאֲשֶׁר יָבֹאוּ:\",2,0],[2,132,4,7,\"וָאַעֲמִיד מִתַּחְתְּיוֹת וְגוֹ׳ וָאַעֲמִיד אֶת הָעָם וְגוֹ׳. מִקְרָא זֶה דּוּגְמַת ״וְהָיוּ הַמַּיִם אֲשֶׁר תִּקַּח מִן הַיְאֹר וְגוֹ׳ וְהָיוּ לְדָם בַּיַּבָּשֶׁת״ (שמות ד:ט), ״כִּי הִנֵּה אוֹיְבֶיךָ ה׳ כִּי הִנֵּה אוֹיְבֶיךָ יֹאבֵדוּ״ (תהלים צב:י), ״עוּרִי עוּרִי דְּבוֹרָה עוּרִי עוּרִי דַּבְּרִי שִׁיר״ (שופטים ה:יב), ״לֹא לָנוּ ה׳ לֹא לָנוּ״ (תהלים קטו:א):\",3,0],[2,132,4,8,\"וָאֵרֶא וָאָקוּם. וְכַאֲשֶׁר רָאִיתִי הָאוֹיְבִים בָּאִים, קַמְתִּי לְדַבֵּר אֶל הַחוֹרִים וְהַסְּגָנִים לְזָרְזָם לְהִלָּחֵם בְּאוֹיְבֵינוּ:\",1,0],[2,132,4,8,\"עַל אֲחֵיכֶם. בִּשְׁבִיל אֲחֵיכֶם:\",2,0],[2,132,4,9,\"כִּי נוֹדַע לָנוּ. הַדָּבָר אֲשֶׁר בָּאוּ לְהִלָּחֵם בָּנוּ:\",1,0],[2,132,4,9,\"וַנָּשָׁב כֻּלָּנוּ. חָזַרְנוּ כֻּלָּנוּ מִמָּקוֹם שֶׁנֶּאֱסַפְנוּ יַחַד לִקְרַאת הָאוֹיְבִים, כָּל אֶחָד וְאֶחָד בִּמְלַאכְתּוֹ לְבִנְיַן הַחוֹמָה:\",2,0],[2,132,4,10,\"וַיְהִי מִן הַיּוֹם הַהוּא. וּמֵאוֹתוֹ יוֹם וָהָלְאָה הָיוּ חֲצִי הַגִּבּוֹרִים עוֹשִׂים בְּבִנְיַן הַחוֹמָה, וּשְׁאָר חֲצִי הַגִּבּוֹרִים הָיוּ מְזֻיָּנִים בִּכְלֵי זֵינָם לִשְׁמֹר אֲחֵיהֶם הָעוֹשִׂים בַּמְּלָאכָה:\",1,0],[2,132,4,10,\"וְהָרְמָחִים. וָ״ו יְתֵרָה, כְּמוֹ וָ״ו שֶׁל ״וְאַיָּה וַעֲנָה״ (בראשית לו:כד):\",2,0],[2,132,4,10,\"וְהַשָּׂרִים. הָיוּ מְחֻבָּרִים אַחֲרֵי כָּל שֵׁבֶט יְהוּדָה, לִהְיוֹת זְהִירִים בַּמִּלְחָמָה:\",3,0],[2,132,4,11,\"הַבּוֹנִים בַּחוֹמָה וְגוֹ׳. אוֹתָם שֶׁהָיוּ בּוֹנִין וְאוֹתָן שֶׁהָיוּ עוֹמְסִים וְנוֹשְׂאִים הַמַּשָּׂאוֹת, בְּיָד אַחַת הָיוּ עוֹשִׂים מְלַאכְתָּן וּבְיָד אַחַת הָיוּ נוֹשְׂאִים כְּלֵי זַיִן:\",1,0],[2,132,4,11,\"הַשֶּׁלַח. כְּלִי קְרָב, כְּמוֹ ״מֵעֲבוֹר בַּשֶּׁלַח״ (איוב לג:יח). וְכֵן חִבְּרוֹ מְנַחֵם:\",2,0],[2,132,4,12,\"וְהַבּוֹנִים. כֵּיצַד הֵם בּוֹנִים? שֶׁהָיוּ כֻלָּם חֲגוּרִים אִישׁ חַרְבּוֹ עַל מָתְנָיו וּבוֹנִים:\",1,0],[2,132,4,12,\"אֶצְלִי. הוּא הָיָה תָּדִיר אֶצְלִי:\",2,0],[2,132,4,13,\"הַרְבֵּה. הִיא גְּדוֹלָה:\",1,0],[2,132,4,14,\"יִלָּחֶם לָנוּ. יִלָּחֵם בַּעֲדֵינוּ:\",1,0],[2,132,4,16,\"אִישׁ וְנַעֲרוֹ. כָּל אֶחָד וְאֶחָד מִן הַבּוֹנִים וּבָחוּר אֶחָד עִמּוֹ:\",1,0],[2,132,4,16,\"יָלִינוּ בְּתוֹךְ יְרוּשָׁלִָם. וְהַלַּיְלָה הָיָה לָהֶם לְמִשְׁמָר וְהַיּוֹם עוֹשִׂים מְלָאכָה, נִמְצָא שֶׁלֹּא הָיוּ יְשֵׁנִים כְּלוּם:\",2,0],[2,132,4,17,\"אֵין אֲנַחְנוּ פּוֹשְׁטִים בְּגָדֵינוּ. תָּמִיד הָיִינוּ זְרִיזִים בַּמִּשְׁמָר:\",1,0],[2,132,4,17,\"אִישׁ שִׁלְחוֹ הַמָּיִם. מֵיסַב עַל אֵין שֶׁלְּמַעְלָה, כְּמוֹ (שמואל א ב:ג) ״יֵצֵא עָתָק מִפִּיכֶם״. אֵין אִישׁ מִמֶּנּוּ פּוֹשֵׁט בְּגָדָיו לִשְׁכַּב אוֹ לִרְחֹץ אוֹתָם בַּמַּיִם. וְכֶפֶל לָשׁוֹן הוּא עַל אֵין אֲנַחְנוּ פוֹשְׁטִים:\",2,0],[2,132,4,17,\"שִׁלְחוֹ. הַפְּשָׁט כְּמוֹ ״וּפָשַׁט אֶת בְּגָדָיו״ (ויקרא ו:ד), דִּמְתֻּרְגָּם ״וְשָׁלַח״:\",3,0],[2,132,5,1,\"וַתְּהִי צַעֲקַת הָעָם וּנְשֵׁיהֶם גְּדוֹלָה. דַּלַּת הָעָם הָעֲנִיִּים הָיוּ צוֹעֲקִים מְאֹד:\",1,0],[2,132,5,1,\"אֶל אֲחֵיהֶם הַיְּהוּדִים. בִּשְׁבִיל אֲחֵיהֶם הַיְּהוּדִים הָעֲשִׁירִים:\",2,0],[2,132,5,2,\"וְיֵשׁ אֲשֶׁר אוֹמְרִים. נוֹתֵן טַעַם לִדְבָרָיו לָמָּה הָיוּ צוֹעֲקִים: יֵשׁ מֵהֶם מִדַּלַּת הָעָם שֶׁהָיוּ אוֹמְרִים אֲנַחְנוּ רַבִּים עִם בָּנֵינוּ וּבְנוֹתֵינוּ וְנִקְחָה דָגָן וְעַתָּה יֵשׁ לָנוּ לִמְכֹּר בָּנֵינוּ וּבְנוֹתֵינוּ לִיקַּח מֵהֶם דָגָן לְמַעַן נִחְיֶה. כָּךְ הָיוּ צוֹעֲקִים עַל הַיְּהוּדִים הָעֲשִׁירִים שֶׁלֹּא הָיוּ רוֹצִים לְפַרְנְסָם:\",1,0],[2,132,5,3,\"וְיֵשׁ אֲשֶׁר אוֹמְרִים שְׂדוֹתֵינוּ וְגוֹ׳. וְיֵשׁ מֵהֶם בָּעֲנִיִּים שֶׁהָיוּ מִתְאוֹנְנִים וְאוֹמְרִים: שָׂדוֹת וּכְרָמִים וּבָתִּים נָתַן לַאֲחֵרִים בְּעֵרָבוֹן וּמַשְׁכּוֹן לִיקַּח דָּגָן לִמְזוֹנוֹתֵינוּ:\",1,0],[2,132,5,3,\"בָּרָעָב. אַחֲרֵי שֶׁאֵין מְוַתְּרִים לָנוּ הָעֲשִׁירִים מִנִּכְסֵיהֶם לְפַרְנָסָתֵנוּ:\",2,0],[2,132,5,4,\"וְיֵשׁ אֲשֶׁר אוֹמְרִים לָוִינוּ כֶסֶף. וְיֵשׁ מֵהֶם אֲשֶׁר אוֹמְרִים: כְּבָר לָוִינוּ כֶסֶף מֵאֲחֵרִים עַל שְׂדוֹתֵינוּ וּכְרָמֵינוּ לִפְרֹעַ מַס הַמֶּלֶךְ, וּמֵעַכְשָׁיו אֵין לָנוּ כְּלוּם לְצֹרֶךְ פַּרְנָסָתֵנוּ:\",1,0],[2,132,5,4,\"לְמִדַּת הַמֶּלֶךְ. לְמַס הַמֶּלֶךְ, כְּמוֹ ״מִנְדָּה בְלוֹ וַהֲלָךְ״ (עזרא ד:יג):\",2,0],[2,132,5,5,\"וְעַתָּה כִּבְשַׂר אַחֵינוּ בְשָׂרֵנוּ. וְעַכְשָׁיו אָנוּ חֲשׁוּבִים וּמְיֻחָסִים כְּאַחֵינוּ שֶׁהֵם עֲשִׁירִים:\",1,0],[2,132,5,5,\"כִּבְנֵיהֶם בָּנֵינוּ. כִּבְנֵיהֶם שֶׁהֵם חֲשׁוּבִים וּמְיֻחָסִים, כְּמוֹ כֵן מְיֻחָסִים בָּנֵינוּ:\",2,0],[2,132,5,5,\"וְהִנֵּה אֲנַחְנוּ כֹבְשִׁים. וְעַתָּה יֵשׁ לָנוּ לִהְיוֹת כֹּבְשִׁים וְנוֹתְנִים בָּנֵינוּ וּבְנוֹתֵינוּ לַאֲחֵרִים עַל עֵסֶק מְזוֹנוֹתֵינוּ:\",3,0],[2,132,5,5,\"וְיֵשׁ מִבְּנוֹתֵינוּ נִכְבָּשׁוֹת. וּכְבָר יֵשׁ קְצָת מִבְּנוֹתֵינוּ שֶׁהֵן נִכְבָּשׁוֹת לַאֲחֵרִים לְעַבְדוּת:\",4,0],[2,132,5,5,\"וְאֵין לְאֵל יָדֵינוּ. וְאֵין כֹּחַ בְּיָדֵינוּ לִפְדּוֹתָם:\",5,0],[2,132,5,5,\"וּשְׂדוֹתֵינוּ וּכְרָמֵינוּ לַאֲחֵרִים. אַף שָׂדוֹת וּכְרָמִים מָסַרְנוּ בְּיַד אֲחֵרִים לְפַרְנָסָתֵנוּ, וּמַה נֹּאכַל מֵעַתָּה, כִּי אֵין לָנוּ בַּמֶּה לְהִתְפַּרְנֵס:\",6,0],[2,132,5,7,\"וַיִּמָּלֵךְ. וַיִּוָּעֵץ לִבִּי בְּעַצְמִי:\",1,0],[2,132,5,7,\"וָאָרִיבָה. נִתְוַכַּחְתִּי עִם הַחוֹרִים וְהַסְּגָנִים שֶׁהֵם הָעֲשִׁירִים:\",2,0],[2,132,5,7,\"מַשָּׁא אִישׁ בְּאָחִיו אַתֶּם. נוֹשִׁים מַדּוּעַ אַתֶּם כָּךְ עוֹשִׂים? הָיָה לָכֶם לְפַרְנֵס הָעֲנִיִּים הַלָּלוּ, וְאַתֶּם מַלְוִים לָהֶם מָמוֹן לִכְבּוֹשׁ בְּנֵיהֶם וּבְנוֹתֵיהֶם וּשְׂדוֹתֵיהֶם וְכַרְמֵיהֶם וּבָתֵּיהֶם:\",3,0],[2,132,5,7,\"וָאֶתֵּן עֲלֵיהֶם קְהִלָּה גְדוֹלָה. הִקְהַלְתִּי וְאָסַפְתִּי עֲלֵיהֶם קְהִלָּה גְדוֹלָה לִצְעוֹק עֲלֵיהֶם, כְּדֵי לְבַיְּשָׁם:\",4,0],[2,132,5,8,\"וָאֹמְרָה לָהֶם. וְכֵן אָמַרְתִּי לָהֶם: אֲנַחְנוּ קָנִינוּ כְּבָר אֶת אַחֵינוּ הַיְּהוּדִים אֲשֶׁר בַּשִּׁבְיָה מִיַּד הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁהָיוּ נִמְכָּרִים לָהֶם:\",1,0],[2,132,5,8,\"כְּדֵי בָּנוּ. בְּאוֹתוֹ דֵּי מָמוֹן שֶׁבְּיָדֵינוּ:\",2,0],[2,132,5,8,\"וְגַם אַתֶּם. וְאַף אַתֶּם תִּמְכְּרוּ לְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֶת אֲחֵיכֶם הַנִּכְבָּשִׁים תַּחַת יְדֵיכֶם לַעֲבָדִים:\",3,0],[2,132,5,8,\"וְנִמְכְּרוּ לָנוּ. וְהַמַּעֲשֶׂה יָבֹא לִידֵי כָּךְ שֶׁיִּהְיוּ מְכוּרִים לָנוּ מִיַּד הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. (אִם כֵּן לָמָּה תִּמְכְּרוּ אוֹתָם כֵּיוָן שֶׁמֻּכְרָחִים אֲנַחְנוּ לִפְדּוֹתָם. כן הוא בספרים אחרים):\",4,0],[2,132,5,8,\"וַיַּחֲרִישׁוּ. שָׁתְקוּ וְנִתְבַּיְּשׁוּ וְלֹא יָדְעוּ מַה לְּהָשִׁיב:\",5,0],[2,132,5,9,\"לֹא טוֹב הַדָּבָר. רַע הַדָּבָר בִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,132,5,9,\"מֵחֶרְפַּת. מִפְּנֵי חֶרְפּוֹת הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁהֵם אוֹיְבֵינוּ:\",2,0],[2,132,5,10,\"וְגַם אֲנִי אַחַי וּנְעָרַי. אַף אֲנִי וַחֲבֵרַי נוֹשִׁים בָּהֶם מָמוֹן, וַאֲנַחְנוּ נַעֲזֹב וְנִמְחֹל לָהֶם כָּל הַהַלְוָאוֹת הַלָּלוּ:\",1,0],[2,132,5,10,\"נוֹשִׁים. כְּמוֹ (מלכים ב ד:א) ״וְהַנֹּשֶׁה בָּא לָקַחַת״:\",2,0],[2,132,5,11,\"הָשִׁיבוּ נָא. וְאַף אַתֶּם תַּעֲשׂוּ כָּמוֹנִי לִמְחֹל לָהֶם כָּל חוֹבוֹתֵיהֶם:\",1,0],[2,132,5,11,\"וּמְאַת הַכֶּסֶף. וְרוֹב הַכֶּסֶף שֶׁהֵם חַיָּבִים לָכֶם עִם הַדָּגָן וְתִירוֹשׁ וְגוֹ׳:\",2,0],[2,132,5,12,\"וַיֹּאמְרוּ נָשִׁיב. וְהֵם אָמְרוּ לְהָשִׁיב וְלִמְחֹל הַכֹּל:\",1,0],[2,132,5,12,\"לַעֲשׂוֹת כַּדָּבָר הַזֶּה. שֶׁיְּהוּ מוֹחֲלִים גַּם הֵם:\",2,0],[2,132,5,13,\"גַּם חָצְנִי נָעַרְתִּי. אַף אֲנִי בְּגָדַי נִעַרְתִּי. חָצְנִי כְּמוֹ ״וְהֵבִיאוּ בָנַיִךְ בְּחֹצֶן״ (ישעיה מט:כב):\",1,0],[2,132,5,13,\"נָעַרְתִּי. אֵישְׁקוֹלִיי״ר בְּלַעַ״ז, כְּמוֹ ״הִתְנַעֲרִי מֵעָפָר״ (ישעיה נב:ב):\",2,0],[2,132,5,13,\"כָּכָה יְנַעֵר. כָּכָה יְנַעֵר הַקָּדוֹשׁ בָּרוּךְ הוּא מִן הָעוֹלָם וּמִנִּכְסֵיהֶם כָּל אוֹתָם שֶׁלֹּא יִהְיוּ מוֹחֲלִין חוֹבוֹתֵיהֶם:\",3,0],[2,132,5,13,\"נָעוּר וָרֵק. בְּלֹא נְכָסִים:\",4,0],[2,132,5,14,\"אֲשֶׁר צִוָּה אוֹתִי. הַמֶּלֶךְ:\",1,0],[2,132,5,14,\"פֶּחָם. כְּמוֹ פֶּחָה שָׁלְטָן, דּוּגְמַת רֵיקָם שֶׁהוּא כְּמוֹ רֵֵיקָה:\",2,0],[2,132,5,14,\"מִשְּׁנַת עֶשְׂרִים. לְמֶלֶךְ דָּרְיָוֶשׁ, כִּי אָז עָלָה מִבָּבֶל, שֶׁנֶּאֱמַר (נחמיה ב:א) ״וַיְהִי בְחֹדֶשׁ נִיסָן שְׁנַת עֶשְׂרִים וְגוֹ׳״:\",3,0],[2,132,5,14,\"שָׁנִים שְׁתֵּים עֶשְׂרֵה. שֶׁהֵם שְׁתֵּים עֶשְׂרֵה שָׁנָה:\",4,0],[2,132,5,14,\"אֲנִי וְאַחַי. אֲנִי וַחֲבֵרַי אֲשֶׁר בָּאוּ עִמִּי:\",5,0],[2,132,5,14,\"לֶחֶם הַפֶּחָה לֹא אָכַלְתִּי. לֶחֶם שֶׁהוּא רָאוּי לְמַאֲכַל הַפֶּחָה, שֶׁהָעָם נוֹתְנִין אוֹתוֹ אֶל הַפֶּחָה מִן הַמַּס:\",6,0],[2,132,5,15,\"הִכְבִּידוּ עַל הָעָם. הִכְבִּידוּ מַס עַל הָעָם:\",1,0],[2,132,5,15,\"וַיִּקְחוּ. וְהָיוּ לוֹקְחִים מֵהֶם בִּשְׁבִיל הַמַּס לֶחֶם וָיַיִן אַחַר נְתִינַת אַרְבָּעִים שְׁקָלִים שֶׁל כֶּסֶף, וְכָךְ הָיוּ רְגִילִים בְּכָל שָׁנָה:\",2,0],[2,132,5,15,\"גַּם נַעֲרֵיהֶם. שֶׁל פַּחוֹת:\",3,0],[2,132,5,16,\"הַחוֹמָה. חוֹמַת הָעִיר:\",1,0],[2,132,5,16,\"הֶחֱזַקְתִּי. הִתְעַסַּקְתִּי לַעֲסוֹק בָּהּ תָּדִיר:\",2,0],[2,132,5,16,\"וְשָׂדֶה לֹא קָנִינוּ. וּבַשָּׂדוֹת שֶׁל הַיְּהוּדִים שֶׁהָיוּ בּוֹנִים הַחוֹמָה לֹא קָנִינוּ אֲנִי וּבְנֵי סִיעָתִי עַל עֵסֶק דָּחְקָם, שֶׁהָיוּ עוֹסְקִין בְּבִנְיַן הַחוֹמָה, אֲבָל הָיִיתִי נוֹתֵן לָהֶם מָמוֹן כְּדֵי לִבְנוֹת הַבִּנְיָן:\",3,0],[2,132,5,16,\"עַל הַמְּלָאכָה. לִבְנוֹת תָּדִיר:\",4,0],[2,132,5,17,\"מֵאָה וַחֲמִשִּׁים אִישׁ. הָיוּ אוֹכְלִים עַל שֻׁלְחָנִי, לְבַד הַגֵּרִים הַבָּאִים אֵלֵינוּ מִן הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, שֶׁאַף הֵם הָיוּ אוֹכְלִים עַל שֻׁלְחָנִי:\",1,0],[2,132,5,18,\"וַאֲשֶׁר הָיָה נַעֲשֶׂה. וּבְכָל יוֹם וָיוֹם הָיוּ אוֹכְלִים עַל שֻׁלְחָנִי שׁוֹר אֶחָד וְשֵׁשׁ צֹאן וְצִפֳּרִים הַרְבֵּה:\",1,0],[2,132,5,18,\"בְּרוּרוֹת. פִּתְרוֹנוֹ לְפִי עִנְיָנוֹ: שֵׁשׁ צֹאן עֲשׂוּיוֹת, כְּעִנְיָן שֶׁנֶּאֱמַר ״חָמֵשׁ צֹאן עֲשׂוּיוֹת״ (שמואל א כה:יח):\",2,0],[2,132,5,18,\"נַעֲשׂוּ לִי. לְשׁוֹן תִּקּוּן, כְּמוֹ ״וּבֶן הַבָּקָר אֲשֶׁר עָשָׂה״ (בראשית יח:ח):\",3,0],[2,132,5,18,\"וּבֵין עֲשֶׂרֶת יָמִים. וּבְכָל יוֹם וָיוֹם הָיוּ שׁוֹתִים יַיִן הַרְבֵּה כְּדֵי שִׁיעוּר סִפּוּק שֶׁל עֲשֶׂרֶת יָמִים:\",4,0],[2,132,5,18,\"וְעִם זֶה. וּבִשְׁבִיל כָּל מַעֲשֶׂה זֶה שֶׁהָיִיתִי מוֹצִיא הוֹצָאוֹת כָּל כָּךְ:\",5,0],[2,132,5,18,\"לֶחֶם. שֶׁל מַס הָרָאוּי לַפֶּחָה לֹא בִקַּשְׁתִּי וְלֹא שָׁאַלְתִּי מִן הָעָם, שֶׁהֲרֵי כָּבְדָה וְחָזָקָה עֲבוֹדַת בִּנְיַן הַחוֹמָה עֲלֵיהֶם:\",6,0],[2,132,6,1,\"וְלֹא נוֹתַר בָּהּ. בְּחוֹמַת הָעִיר:\",1,0],[2,132,6,1,\"דְּלָתוֹת לֹא הֶעֱמַדְתִּי. שֶׁלֹּא נַעֲשׂוּ דְלָתוֹת בְּשַׁעֲרֵי הָעִיר:\",2,0],[2,132,6,2,\"בַּכְּפִירִים. שֵׁם מָקוֹם הוּא:\",1,0],[2,132,6,2,\"בְּבִקְעַת אוֹנוֹ. כָּךְ שֵׁם הַבִּקְעָה:\",2,0],[2,132,6,2,\"וְהֵמָּה חוֹשְׁבִים. הֵבַנְתִּי מֵהֶם שֶׁהָיוּ חוֹשְׁבִים עָלַי לְהָרְגֵנִי שָׁם:\",3,0],[2,132,6,3,\"מְלָאכָה גְדוֹלָה אֲנִי עֹשֶׂה. מִבִּנְיָנֵי (הָעִיר. ספרים אחרים) הֶעָפָר:\",1,0],[2,132,6,3,\"לָמָּה תִשְׁבַּת. לָמָּה תִּהְיֶה הַמְּלָאכָה בְּטֵלָה?\",2,0],[2,132,6,3,\"כַּאֲשֶׁר אַרְפֶּהָ. יָדִי מִן הַבִּנְיָן:\",3,0],[2,132,6,3,\"וְיָרַדְתִּי אֲלֵיכֶם. לְדַבֵּר וּלְהִוָּעֵד אֲלֵיכֶם:\",4,0],[2,132,6,5,\"אֶת נַעֲרוֹ. עַל יְדֵי נַעֲרוֹ:\",1,0],[2,132,6,5,\"וְאִגֶּרֶת פְּתוּחָה בְּיָדוֹ. כָּתַב אִגֶּרֶת שָׁלַח לִי עַל יָדוֹ:\",2,0],[2,132,6,6,\"כָּתוּב בָּהּ. בְּאוֹתָהּ אִגֶּרֶת:\",1,0],[2,132,6,6,\"בַּגּוֹיִם נִשְׁמָע. שֶׁנּוֹדַע לְכָל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁאַתָּה וְכָל הַיְּהוּדִים חוֹשְׁבִים לִמְרוֹד:\",2,0],[2,132,6,6,\"וְגַשְׁמוּ אוֹמֵר. גַּשְׁמוּ הוּא גֶּשֶׁם הָעֲרָבִי (נחמיה ב:יט), וּפִתְרוֹנוֹ כְּאָדָם שֶׁאוֹמֵר לַחֲבֵירוֹ כָּךְ הוּא הַדָּבָר וּפְלוֹנִי אוֹמֵר:\",3,0],[2,132,6,6,\"כַּדְּבָרִים הָאֵלֶּה. מוּסָב עַל כָּתוּב בָּהּ; וּמִקְרָא מְסֹרָס הוּא, וַהֲרֵי הוּא כְּאִלּוּ נֶאֱמַר: כָּתוּב בָּהּ כַּדְּבָרִים הָאֵלֶּה בַּגּוֹיִם נִשְׁמָע וְגוֹ׳:\",4,0],[2,132,6,7,\"וְגַם נְבִיאִים וְגוֹ׳. עַד וְנִוָּעֲצָה יַחְדָּו הָיָה כָתוּב בָּאִגֶּרֶת:\",1,0],[2,132,6,7,\"נְבִיאִים. בַּעֲלֵי לָשׁוֹן, כְּמוֹ ״בּוֹרֵא נִיב שְׂפָתָיִם״ (ישעיה נז:יט):\",2,0],[2,132,6,7,\"לֵאמֹר. שֶׁאוֹמְרִים: יֵשׁ מֶלֶךְ בִּיהוּדָה:\",3,0],[2,132,6,7,\"וְעַתָּה יִשָּׁמַע לַמֶּלֶךְ. אַחֲרֵי שֶׁנִּקְרֵאתָ מֶלֶךְ יִשָּׁמַע לַמֶּלֶךְ כַּדְּבָרִים הָאֵלֶּה:\",4,0],[2,132,6,8,\"כִּי מִלִּבְּךָ. הֲרֵי כִּי בִּמְקוֹם אֶלָּא:\",1,0],[2,132,6,8,\"בּוֹדָם. קוֹנְטְרַבְנְטַאלְ״שׁ בְּלַעַ״ז, כְּמוֹ אֲשֶׁר בָּדָה מִלִּבּוֹ:\",2,0],[2,132,6,9,\"כִּי כֻלָּם. כִּי כָּל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:\",1,0],[2,132,6,9,\"מְיָרְאִים אוֹתָנוּ. מִתְיָרְאִים מִמֶּנּוּ, וְכָךְ הֵם אוֹמְרִים: יִרְפּוּ יְדֵיהֶם וְגוֹ׳:\",2,0],[2,132,6,9,\"וְעַתָּה חַזֵּק אֶת יָדָי. לְסַיְּעֵנִי בְּבִנְיַן הַחוֹמָה:\",3,0],[2,132,6,10,\"וְהוּא עָצוּר. שֶׁמְּצָאוֹ בְּבֵיתוֹ:\",1,0],[2,132,6,10,\"וַיֹּאמֶר נִוָּעֵד. אוֹתוֹ שְׁמַעְיָה הָיָה נְבִיא שֶׁקֶר, וְקִבֵּל שֹׁחַד מִן סַנְבַלַּט וַחֲבֵרָיו לְהַפְחִיד אֶת נְחֶמְיָה, כְּדֵי לְבַטֵּל אֶת הַמְּלָאכָה:\",2,0],[2,132,6,10,\"כִּי בָאִים לְהָרְגֶךָ. שֶׁהֲרֵי יָבוֹאוּ לְהָרְגְךָ סַנְבַלַּט וַחֲבֵרָיו:\",3,0],[2,132,6,10,\"וְלַיְלָה בָּאִים. וְעַל כֵּן הִזְהִירוּ לִיכָּנֵס בַּהֵיכָל וְלִסְגֹּר הַדְּלָתוֹת עָלָיו, שֶׁעֲדַיִן לֹא נַעֲשׂוּ דַלְתוֹת שַׁעֲרֵי הָעִיר, כְּמָה שֶׁנֶּאֱמַר בִּתְחִלַּת הַפָּרָשָׁה: ״גַּם עַד הָעֵת הַהִיא דְּלָתוֹת לֹא הֶעֱמַדְתִּי בַשְּׁעָרִים״ (נחמיה ו:א):\",4,0],[2,132,6,11,\"הַאִישׁ כָּמוֹנִי יִבְרָח. בִּתְמִיהָּ אִם אִישׁ כָּמוֹנִי יִבְרָח לִיכָּנֵס בַּהֵיכָל:\",1,0],[2,132,6,11,\"לֹא אָבוֹא. לֹא אֶכָּנֵס שָׁם מִפְּנֵי פַּחַד הַמִּיתָה, וְלֹא אֶעֱבֹר עַל הַמִּצְוָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יָבוֹא וְיִכָּנֵס זָר בְּהֵיכָלוֹ:\",2,0],[2,132,6,12,\"וָאַכִּירָה. הִכַּרְתִּי בִּדְבָרָיו שֶׁלֹּא שְׁלָחוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדָבָר זֶה שֶׁאֶעֱבֹר עֲבֵרָה מִפְּנֵי פַּחַד הַמִּיתָה:\",1,0],[2,132,6,12,\"כִּי הַנְּבוּאָה דִּבֶּר עָלַי. שֶׁהֲרֵי הוּא דִּבֵּר הַדְּבָרִים הַלָּלוּ עָלַי בְּשֵׁם נְבוּאָה:\",2,0],[2,132,6,12,\"שְׂכָרוֹ. כָּל אֶחָד וְאֶחָד מֵהֶם שְׂכָרוֹ, וְנָתְנוּ לוֹ שָׂכָר לְהַפְחִידֵנִי וּלְבַטֵּל בְּבִנְיַן הַחוֹמָה:\",3,0],[2,132,6,13,\"לְמַעַן שָׂכוּר הוּא. אָמַר לִי הַדְּבָרִים הַלָּלוּ:\",1,0],[2,132,6,13,\"לְמַעַן אִירָא. כְּדֵי שֶׁאֶתְיָרֵא מֵהֶם לִהְיוֹת עוֹשֶׂה כֵּן לִיכָּנֵס בַּהֵיכָל וְלִהְיוֹת חוֹטֵא:\",2,0],[2,132,6,13,\"וְהָיָה לָהֶם לְשֵׁם רָע. לְמַעַן שֶׁיִּהְיֶה לָהֶם לְשֵׁם רָע, לְחָרְפֵנִי בַּעֲבֵרָה זוֹ:\",3,0],[2,132,6,14,\"וְגַם לְנוֹעַדְיָה הַנְּבִיאָה. הִיא וּשְׁאָר נְבִיאֵי הַשֶּׁקֶר קִבְּלוּ שָׂכָר מִסַּנְבַלַּט וַחֲבֵרָיו כְּדֵי לְהַפְחִידֵנִי בִּנְבוּאַת שִׁקְרֵיהֶם:\",1,0],[2,132,6,15,\"בְּעֶשְׂרִים וַחֲמִשָּׁה. יָמִים לְחֹדֶשׁ אֱלוּל בִּשְׁנַת עֶשְׂרִים לְדָרְיָוֶשׁ הַמֶּלֶךְ, שֶׁבִּשְׁנַת עֶשְׂרִים לְדָרְיָוֶשׁ עָלָה נְחֶמְיָה מִבָּבֶל וּבְאוֹתָהּ שָׁנָה בָּנָה חָרְבוֹת יְרוּשָׁלָיִם:\",1,0],[2,132,6,15,\"לַחֲמִשִּׁים וּשְׁנַיִם יוֹם. סוֹף חֲמִשִּׁים וּשְׁתַּיִם יוֹם מִיּוֹם שֶׁהִתְחִילוּ לִבְנוֹתוֹ נִגְמַר בִּנְיַן הַחוֹמָה:\",2,0],[2,132,6,16,\"וַיְהִי כַּאֲשֶׁר שָׁמְעוּ כָּל אוֹיְבֵינוּ. דָּבָר זֶה שֶׁנִּשְׁלַם בִּנְיַן הַחוֹמָה:\",1,0],[2,132,6,16,\"וַיִּרְאוּ כָל הַגּוֹיִם. וְכַאֲשֶׁר רָאוּ כָל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁנִּגְמַר בִּנְיַן חוֹמַת הָעִיר:\",2,0],[2,132,6,16,\"וַיִּפְּלוּ מְאֹד בְּעֵינֵיהֶם. נָפְלוּ הֵם עַצְמָם בְּעֵינֵיהֶם שֶׁהָיוּ מוֹאֲסִים בְּעַצְמָם, כִּי נָפַל פַּחַד הַיְּהוּדִים עֲלֵיהֶם:\",3,0],[2,132,6,17,\"חוֹרֵי יְהוּדָה. שָׂרֵי יְהוּדָה:\",1,0],[2,132,6,17,\"עַל טוֹבִיָּה. אֶל טוֹבִיָּה. יִשְׂרָאֵל רָשָׁע הָיָה:\",2,0],[2,132,6,17,\"וַאֲשֶׁר לְטוֹבִיָּה. וְאִגֶּרֶת אֲשֶׁר לְטוֹבִיָּה:\",3,0],[2,132,6,18,\"כִּי רַבִּים בִּיהוּדָה. שֶׁהָיוּ שָׂרִים רַבִּים בִּיהוּדָה אֲשֶׁר הָיוּ לוֹ לְטוֹבִיָּה בַּעֲלֵי בְּרִית וּשְׁבוּעָה:\",1,0],[2,132,6,18,\"כִּי חָתָן הוּא. אוֹתוֹ טוֹבִיָּה לִשְׁכַנְיָה:\",2,0],[2,132,6,18,\"וִיהוֹחָנָן בְּנוֹ. שֶׁל טוֹבִיָּה:\",3,0],[2,132,6,18,\"בַּת מְשֻׁלָּם. אוֹתוֹ מְשֻׁלָּם שַׂר וְגָדוֹל הָיָה:\",4,0],[2,132,6,19,\"גַּם טוֹבוֹתָיו. שֶׁל טוֹבִיָּה הָיוּ מְסַפְּרִים לְפָנַי אוֹתָן בַּעֲלֵי שְׁבוּעָתוֹ וּקְרוֹבָיו:\",1,0],[2,132,6,19,\"טוֹבוֹתָיו. שֶׁשְׁפְּרוֹאוּצְ״שׁ בְּלַעַ״ז:\",2,0],[2,132,6,19,\"הָיוּ מוֹצִיאִים לוֹ. לְהַגִּיד לוֹ לְטוֹבִיָּה:\",3,0],[2,132,6,19,\"אִגְּרוֹת שָׁלַח טוֹבִיָּה. אִגְּרוֹת הָיָה שׁוֹלֵחַ תָּדִיר לְהַפְחִידֵנִי, שֶׁלֹּא לִבְנוֹת בִּנְיַן הַחוֹמָה:\",4,0],[2,132,7,1,\"וַיִּפָּקְדוּ. עַתָּה נַעֲשׂוּ הַלְוִיִּם פְּקוּדִים עַל פְּקִידוּתָן, לִהְיוֹתָן שׁוֹעֲרִים וּמְשׁוֹרְרִים מִן הַלְוִיִּם בְּבֵית הַמִּקְדָּשׁ:\",1,0],[2,132,7,2,\"עַל יְרוּשָׁלִָם. לִשְׁמֹר שַׁעֲרֵי יְרוּשָׁלָיִם:\",1,0],[2,132,7,2,\"מֵרַבִּים. מִיָּמִים רַבִּים:\",2,0],[2,132,7,3,\"עַד חֹם הַשֶּׁמֶשׁ. עַד חֲצִי הַיּוֹם, שֶׁהָיָה הַיּוֹם גָּדוֹל:\",1,0],[2,132,7,3,\"וְעַד הֵם עוֹמְדִים. וּבְעוֹד שֶׁהַשְּׁעָרִים פְּתוּחִים יִהְיוּ עוֹמְדִים, שֶׁלֹּא יָזוּזוּ עַד יָגִיפוּ וְיִסְגְּרוּ הַדְּלָתוֹת, וְהָרוֹצֶה לָצֵאת יֵצֵא מִן הָעִיר וְהָרוֹצֶה לִיכָּנֵס יָבֹא וְיִכָּנֵס. כָּל כָּךְ הָיוּ עוֹשִׂים מִפְּנֵי הָאוֹיְבִים:\",2,0],[2,132,7,3,\"וֶאֱחֹזוּ. יֹאחֲזוּ הַדְּלָתוֹת לְסָגְרָם:\",3,0],[2,132,7,3,\"מִשְׁמְרוֹת יוֹשְׁבֵי יְרוּשָׁלַ͏ִם. מִיּוֹשְׁבֵי יְרוּשָׁלִַם הֶעֱמִידוּ מִשְׁמָרוֹת, גִּיטְ״שׁ בְּלַעַ״ז:\",4,0],[2,132,7,4,\"רַחֲבַת יָדַיִם. רְחַבַת מָקוֹם וּגְדוֹלָה:\",1,0],[2,132,7,5,\"לְהִתְיַחֵשׂ. לַחֲקוֹר יִחוּסָן:\",1,0],[2,132,7,5,\"הָעוֹלִים בָּרִאשׁוֹנָה. מֵאוֹתָן הַיְּהוּדִים הָעוֹלִים עִם עֶזְרָא בָּרִאשׁוֹנָה:\",2,0],[2,132,7,5,\"וָאֶמְצָא כָתוּב בּוֹ. כָּל אֵלֶּה הַדְּבָרִים הָיוּ כְתוּבִים בְּאוֹתָהּ אִגֶּרֶת:\",3,0],[2,132,7,6,\"אֵלֶּה בְּנֵי הַמְּדִינָה וְגוֹ׳. עַד ״וְהַגּוֹרָלוֹת הִפַּלְנוּ עַל קָרְבַּן הָעֵצִים״ (נחמיה י:לה):\",1,0],[2,132,7,6,\"וְלִיהוּדָה. לִמְדִינַת יְהוּדָה׃\",2,0],[2,132,7,6,\"אִישׁ לְעִירוֹ. כָּל אֶחָד לְעִירוֹ:\",3,0],[2,132,7,7,\"הַבָּאִים עִם זְרֻבָּבֶל. אֲשֶׁר בָּאוּ מִשְּׁבִי הַגּוֹלָה עִם זְרֻבָּבֶל:\",1,0],[2,132,7,7,\"יֵשׁוּעַ. הוּא יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק הַכֹּהֵן הַגָּדוֹל (חגי א:א). חֶשְׁבּוֹנוֹת הַלָּלוּ פְּעָמִים הֵם מְכֻוָּנִים עִם חֶשְׁבּוֹנוֹת שֶׁל מַעְלָה, פְּעָמִים יֵשׁ שֶׁאֵינָם מְכֻוָּנִים זֶה כְּנֶגֶד זֶה; וְלֹא דִקְדֵּק הַמִּקְרָא בַּחֶשְׁבּוֹנוֹת כָּל כָּךְ, אֲבָל הַכְּלָל שָׁוֶה (עַיֵּן בְּעֶזְרָא סִימָן ב פ״ב וְצָרִיךְ עִיּוּן יסוד ושרש העבודה) לְכָאן וּלְכָאן, שֶׁנֶּאֱמַר ״כָּל הַקָּהָל כְּאֶחָד וְגוֹ׳״ (נחמיה ז:סו). וְעַל זֶה הַכְּלָל סָמַךְ כּוֹתֵב הַסֵּפֶר, וְלֹא דִקְדֵּק בְּחֶשְׁבּוֹן הַפְּרָטִיּוֹת כָּל כָּךְ, וְהַכֹּל מְפֹרָשׁ לְמַעְלָה:\",2,0],[2,132,8,2,\"בְּיוֹם אֶחָד לַחֹדֶשׁ הַשְּׁבִיעִי. הוּא יוֹם שֶׁל רֹאשׁ הַשָּׁנָה (ראש השנה א,א):\",1,0],[2,132,8,3,\"מִן הָאוֹר. שֶׁל תְּחִלַּת הַיּוֹם:\",1,0],[2,132,8,3,\"אֶל סֵפֶר הַתּוֹרָה. הָיוּ כָל הָעָם מַטִּים אָזְנֵיהֶם:\",2,0],[2,132,8,4,\"אֲשֶׁר עָשׂוּ לַדָּבָר. אוֹתוֹ מִגְדַּל עֵץ עָשׂוּ לְשֵׁם כָּךְ, לִקְרוֹת שָׁם עָלָיו סֵפֶר הַתּוֹרָה:\",1,0],[2,132,8,5,\"כִּי מֵעַל כָּל הָעָם הָיָה. וְעַל כֵּן רָאוּהוּ כֻּלָּם:\",1,0],[2,132,8,5,\"וּכְפִתְחוֹ עָמְדוּ כָל הָעָם. וְכַאֲשֶׁר פְּתָחוֹ לִקְרוֹת שָׁתְקוּ כָּל הָעָם׃\",2,0],[2,132,8,5,\"עָמְדוּ. לְשׁוֹן שְׁתִיקָה (שָׁתְקוּ), כְּמוֹ ״עָמְדוּ וְלֹא עָנוּ עוֹד״ (אִיּוֹב לב:טז):\",3,0],[2,132,8,6,\"בְּמֹעַל יְדֵיהֶם. בִּנְשִׂיאוּת יְדֵיהֶם, שֶׁנָּשְׂאוּ כַפֵּיהֶם לְמַעְלָה לְהוֹדוֹת לְהַקָּדוֹשׁ בָּרוּךְ הוּא, כְּעִנְיָן שֶׁנֶּאֱמַר: ״וַיִּפְרֹשׂ כַּפָּיו הַשָּׁמָיִם״ (מְלָכִים א ח:כב):\",1,0],[2,132,8,7,\"מְבִינִים אֶת הָעָם. שֶׁהָיוּ מְתַרְגְּמִין לָעָם דִּבְרֵי תוֹרָה:\",1,0],[2,132,8,7,\"עַל עָמְדָם. שֶׁהָיוּ עוֹמְדִים עַל רַגְלֵיהֶם:\",2,0],[2,132,8,8,\"וְשׂוּם שֵׂכֶל. וְשִׂימַת חָכְמָה, וְשׂוּם לְשׁוֹן פָּעוּל:\",1,0],[2,132,8,9,\"הַיּוֹם קָדוֹשׁ. כִּי יוֹם רֹאשׁ הַשָּׁנָה הוּא:\",1,0],[2,132,8,9,\"כִּי בוֹכִים כָּל הָעָם. מִפְּנֵי שֶׁלֹּא קִיְּמוּ הַתּוֹרָה כָּרָאוּי:\",2,0],[2,132,8,10,\"לְאֵין נָכוֹן לוֹ. לֶעָנִי שֶׁאֵין מְזֻמָּן לוֹ מַאֲכָלוֹ:\",1,0],[2,132,8,11,\"מַחְשִׁים. הָיוּ מַזְהִירִין לְכָל הָעָם לַחֲשׁוֹת, שֶׁלֹּא יִבְכּוּ עוֹד:\",1,0],[2,132,8,11,\"הַסּוּ. לְשׁוֹן שְׁתִיקָה, כְּמוֹ ״וַיַּהַס כָּלֵב״ (במדבר יג:ל):\",2,0],[2,132,8,13,\"וּבַיּוֹם הַשֵּׁנִי. שֶׁל רֹאשׁ הַשָּׁנָה:\",1,0],[2,132,8,15,\"וַאֲשֶׁר יַשְׁמִיעוּ. וְצִוּוּ אֲשֶׁר יַשְׁמִיעוּ קוֹל לָחוֹג אֶת חַג הַסֻּכּוֹת, וְכֵן נוֹהֵג הַמִּקְרָא לְדַבֵּר כָּעִנְיָן הַזֶּה, כְּמוֹ ״אֱמֹר לַנַּעַר וְיַעֲבֹר לְפָנֵינוּ״ (שמואל א ט:כז):\",1,0],[2,132,8,15,\"וַעֲלֵי הֲדַס. מְפֹרָשׁ בְּמַסֶּכֶת סֻכָּה (סוכה יב,א): זֶה הֲדַס שׁוֹטֶה, שֶׁאֵינוֹ רָאוּי לְלוּלָב כִּי אִם לַעֲשׂוֹת סֻכָּה:\",2,0],[2,132,8,15,\"וַעֲלֵי תְמָרִים. לְלוּלָב:\",3,0],[2,132,8,15,\"וַעֲלֵי עֵץ עָבֹת. זֶה הֲדַס הָרָאוּי לְלוּלָב, כַּמְּפֹרָשׁ בְּמַסֶּכֶת סֻכָּה (סוכה לב,ב):\",4,0],[2,132,8,18,\"יוֹם בְּיוֹם. בְּכָל יוֹם וָיוֹם:\",1,0],[2,132,9,1,\"וַאֲדָמָה עֲלֵיהֶם. הֶעֱלוּ עָפָר עַל רֹאשָׁם:\",1,0],[2,132,9,2,\"מִכָּל בְּנֵי נֵכָר. וּמִנְּשֵׁיהֶם שֶׁל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, כְּמוֹ שֶׁנֶּאֱמַר לְמַעְלָה (נחמיה יג):\",1,0],[2,132,9,4,\"עַל מַעֲלֵה הַלְוִיִּם. מַעֲלוֹת הָיוּ שָׁם שֶׁהַלְוִיִּם עוֹמְדִים שָׁם עֲלֵיהֶם בְּשָׁעָה שֶׁאָמְרוּ שִׁירָה:\",1,0],[2,132,9,5,\"מִן הָעוֹלָם וְעַד הָעוֹלָם. מִתְּחִלַּת הָעוֹלָם וְעַד תַּכְלִיתוֹ יְהִי בָּרוּךְ:\",1,0],[2,132,9,5,\"וִיבָרְכוּ שֵׁם כְּבוֹדֶךָ. עַכְשָׁיו דִּבְּרוּ הַלְוִיִּם כְּלַפֵּי שְׁכִינָה בִּתְפִלָּה: וִיבָרְכוּ שֵׁם כְּבוֹדֶךָ כִּי הוּא גָּדוֹל וּמְרוֹמָם עַל כָּל בְּרָכָה וּתְהִלָּה, כִּי כָל הַבְּרָכוֹת וּתְהִלּוֹת שֶׁלּוֹ הֵם. דָּבָר אַחֵר: וּמְרוֹמַם עַל כָּל בְּרָכָה וּתְהִלָּה שֶׁאֵין בְּרִיָּה יְכוֹלָה לְבָרְכוֹ וּלְהַלְּלוֹ כְּפִי גָדְלוֹ וְרוֹמְמוּתוֹ, שֶׁהוּא מְרוֹמָם וְנִשָּׂא יוֹתֵר מַה שֶּׁאֵין הַפֶּה יְכוֹלָה לְדַבֵּר:\",2,0],[2,132,9,7,\"וְשַׂמְתָּ. טַעֲמוֹ לְמַעְלָה בַּשִּׂי״ן, לְפִי שֶׁמַּשְׁמָעוּתוֹ בִּלְשׁוֹן עָבָר:\",1,0],[2,132,9,8,\"וְכָרוֹת עִמּוֹ. לְשׁוֹן פָּעוּל:\",1,0],[2,132,9,10,\"כִּי הֵזִידוּ. כִּי הִרְשִׁיעוּ עֲלֵיהֶם, כְּמוֹ ״כִּי בַדָּבָר אֲשֶׁר זָדוּ עֲלֵיהֶם״ (שמות יח:יא):\",1,0],[2,132,9,10,\"שֵׁם. רָצוֹן בְּלַעַ״ז:\",2,0],[2,132,9,12,\"יוֹמָם. בְּכָל יוֹם וָיוֹם:\",1,0],[2,132,9,13,\"וְדַבֵּר. כְּמוֹ וּלְדַבֵּר, כְּמוֹ שֶׁנֶּאֱמַר ״מִן הַשָּׁמַיִם הִשְׁמִיעֲךָ אֶת קוֹלוֹ לְיַסְּרֶךָּ״ (דברים ד:לו):\",1,0],[2,132,9,15,\"לִרְעָבָם. מִן רָעָב יֹאמַר לִרְעָבָם, כְּמוֹ מִן צָמָא לִצְמָאָם:\",1,0],[2,132,9,15,\"אֲשֶׁר נָשָׂאתָ אֶת יָדְךָ. בִּשְׁבוּעָה, כְּמוֹ ״אֲשֶׁר נָשָׂאתִי אֶת יָדִי לָתֵת אֹתָהּ״ (שמות ו:ח):\",2,0],[2,132,9,17,\"בְּמִרְיָם. בִּשְׁבִיל מְרִי שֶׁלָּהֶם:\",1,0],[2,132,9,19,\"בְּהַדֶּרֶךְ. כְּמוֹ בַּדֶּרֶךְ׃\",1,0],[2,132,9,22,\"לְפֵאָה. כְּמוֹ לִהְיוֹת לְצַד זָוִית אַחַת מֻחְלָקִים, בְּלִי לְהִתְעָרֵב עִם גּוֹיֵי הָאֲרָצוֹת:\",1,0],[2,132,9,24,\"וַתַּכְנַע. וְהִכְנַעְתָּ:\",1,0],[2,132,9,27,\"וְאַתָּה מִשָּׁמַיִם תִּשְׁמָע. הָיִיתָ שׁוֹמֵעַ:\",1,0],[2,132,9,30,\"וַתִּמְשֹׁךְ עֲלֵיהֶם. מָשַׁכְתָּ עֲלֵיהֶם רַחֲמִים, שֶׁלֹּא לְהַשְׁחִיתָם:\",1,0],[2,132,9,33,\"עַל כָּל הַבָּא. עַל כָּל מַעֲשֵׂה יִסּוּרֶיךָ הָרָעִים אֲשֶׁר בָּאוּ עָלֵינוּ:\",1,0],[2,132,9,36,\"הִנֵּה אֲנַחְנוּ עֲבָדִים עָלֶיהָ. שֶׁאֲנַחְנוּ מַעֲלִים מַס לְכָל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:\",1,0],[2,132,9,37,\"וּתְבוּאָתָהּ. שֶׁל אֶרֶץ יִשְׂרָאֵל:\",1,0],[2,132,9,37,\"מַרְבָּה. מַעֲדַנֵּי מַאֲכָלִים לְמַלְכֵי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:\",2,0],[2,132,9,37,\"אֲשֶׁר נָתַתָּה עָלֵינוּ. שֶׁהֵם מוֹשְׁלִים בָּנוּ:\",3,0],[2,132,10,1,\"וּבְכָל זֹאת. וּבְכָל הָרָעָה הַזֹּאת הַבָּאָה עָלֵינוּ אֲנַחְנוּ כּוֹרְתִים אֲמָנָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא, לְהַאֲמִין וְלִבְטוֹחַ בּוֹ:\",1,0],[2,132,10,1,\"וְכוֹתְבִים. וַאֲנַחְנוּ כּוֹתְבִים בַּסֵּפֶר לְקַבֵּל מַלְכוּתוֹ עָלֵינוּ, לְמַעַן תִּהְיֶה לָנוּ לְעֵדוּת:\",2,0],[2,132,10,1,\"וְעַל הֶחָתוּם. שֶׁרוֹב גְּדוֹלִים וַחֲשׁוּבִים שֶׁבָּנוּ חֲתוּמִים עַל סֵפֶר קַבָּלַת הַמִּצְוֹת לִהְיוֹת לָנוּ לְעֵדוּת:\",3,0],[2,132,10,2,\"וְעַל הַחֲתוּמִים. עַתָּה מוֹנֶה וְהוֹלֵךְ הַחֲתוּמִים בַּסֵּפֶר לְעֵדוּת קִבּוּל הַמִּצְוֹת:\",1,0],[2,132,10,2,\"נְחֶמְיָה הַתִּרְשָׁתָא. שֵׁם אֶחָד הוּא, וְזֶהוּ שֶׁפֵּרַשְׁתִּי (עזרא ב:סג) דְּהַתִּרְשָׁתָא הוּא נְחֶמְיָה. וְלָמָּה נִקְרָא שְׁמוֹ הַתִּרְשָׁתָא? שֶׁהִתִּירוּ לוֹ חֲכָמִים לִשְׁתּוֹת יֵין נֶסֶךְ, לְפִי שֶׁהָיָה מַשְׁקֶה לַמֶּלֶךְ:\",2,0],[2,132,10,29,\"וְכָל הַנִּבְדָּל. הֵם הַגֵּרִים שֶׁנִּבְדְּלוּ מִתּוֹרַת הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, לִהְיוֹת דְּבוּקִים וּמְחֻבָּרִים אֶל תּוֹרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְלִשְׁמֹר מִצְוֹתָיו:\",1,0],[2,132,10,30,\"עַל אֲחֵיהֶם. עִם אֲחֵיהֶם:\",1,0],[2,132,10,30,\"אַדִּירֵיהֶם. גְּדוֹלִים שֶׁבָּהֶם:\",2,0],[2,132,10,32,\"הַמִּקָּחוֹת. הַסְּחוֹרוֹת:\",1,0],[2,132,10,32,\"שֶׁבֶר. תְּבוּאָה, כְּמוֹ ״בַּשֶּׁבֶר אֲשֶׁר הֵם שֹׁבְרִים״ (בראשית מז:יד):\",2,0],[2,132,10,32,\"וּבְיוֹם קֹדֶשׁ. שֶׁל יוֹם טוֹב:\",3,0],[2,132,10,32,\"וְנִטֹּשׁ אֶת הַשָּׁנָה הַשְּׁבִיעִית. כְּעִנְיָן שֶׁנֶּאֱמַר: ״וְהַשְּׁבִיעִת תִּשְׁמְטֶנָּה וּנְטַשְׁתָּהּ״ (שמות כג:יא):\",4,0],[2,132,10,32,\"וּמַשָּׁא כָל יָד. הַשְׁמָטַת מִלְוֶה בַּשְּׁבִיעִית (דברים טו:ב):\",5,0],[2,132,10,34,\"וְכָל מְלֶאכֶת בֵּית אֱלֹהֵינוּ. לַעֲשׂוֹת מִן הַכֶּסֶף:\",1,0],[2,132,10,35,\"הִפַּלְנוּ. כַּמָּה יָבִיא כָּל אֶחָד:\",1,0],[2,132,10,35,\"קֻרְבַּן הָעֵצִים. תִּקְרֹבֶת שֶׁל עֲצֵי הַמַּעֲרָכָה לַמִּזְבֵּחַ:\",2,0],[2,132,10,35,\"לְבֵית אֲבוֹתֵינוּ. שֶׁהִיא בֵּית קְדֻשַּׁת אֲבוֹתֵינוּ:\",3,0],[2,132,10,36,\"וּבִכּוּרֵי כָּל פְּרִי כָּל עֵץ. בִּכּוּרֵי שֶׁל כָּל פְּרִי הָאִילָן הֵם מִדִּבְרֵי חֲכָמִים:\",1,0],[2,132,10,38,\"נָבִיא לַכֹּהֲנִים אֶל לִשְׁכוֹת. כִּי שָׁם הָיוּ רְגִילִים:\",1,0],[2,132,10,38,\"הַמְעַשְּׂרִים בְּכָל עָרֵי עֲבוֹדָתֵנוּ. שֶׁנּוֹטְלִים מַעַשְׂרוֹתֵיהֶם בְּכָל עָרֵי יִשְׂרָאֵל:\",2,0],[2,132,10,39,\"בַּעְשֵׂר. לְשׁוֹן בַּעְשׂוֹר:\",1,0],[2,132,10,39,\"אֶת מַעֲשַׂר הַמַּעֲשֵׂר. שֶׁהָיוּ הַלְוִיִּם מְעַשְּׂרִים מַעֲשֵׂר מִן הַמַּעֲשֵׂר וּמְבִיאִים אוֹתוֹ לַכֹּהֲנִים שֶׁלֹּא הָיוּ עוֹזְבִים אֶת בֵּית הַמִּקְדָּשׁ:\",2,0],[2,132,11,1,\"אֶחָד מִן הָעֲשָׂרָה. שֶׁבְּיִשְׂרָאֵל, לְמַעַן יֵשְׁבוּ בִּירוּשָׁלַיִם לִשְׁמֹר הָעִיר:\",1,0],[2,132,11,1,\"וְתֵשַׁע הַיָּדוֹת. תִּשְׁעָה חֲלָקִים שֶׁבְּיִשְׂרָאֵל:\",2,0],[2,132,11,2,\"הַמִּתְנַדְּבִים. אֲשֶׁר נָדְבָה רוּחָם אוֹתָם לִהְיוֹת יוֹשְׁבִים בִּירוּשָׁלַיִם לִשְׁמֹר הָעִיר מִן הָאוֹיְבִים:\",1,0],[2,132,11,3,\"וְאֵלֶּה רָאשֵׁי הַמְּדִינָה אֲשֶׁר יָשְׁבוּ בִּירוּשָׁלִָם. הוּא שֶׁנֶּאֱמַר בְּסָמוּךְ וּבִירוּשָׁלִַם יָשְׁבוּ בְּנֵי יְהוּדָה וְגוֹ׳:\",1,0],[2,132,11,4,\"מִבְּנֵי יְהוּדָה עֲתָיָה וְגוֹ׳. חוֹזֵר וּמְפָרֵשׁ מִבְּנֵי יְהוּדָה מִי וָמִי הָיוּ. וְכָל הַפָּרָשָׁה אֵינָהּ מוֹנָה כִּי אִם הַגְּדוֹלִים וְהַחֲשׁוּבִים שֶׁבָּהֶם:\",1,0],[2,132,11,9,\"פָּקִיד. מְמֻנֶּה:\",1,0],[2,132,11,9,\"מִשְׁנֶה. אַחַר (הַפָּקִיד):\",2,0],[2,132,11,11,\"נְגִד. מְמֻנֶּה:\",1,0],[2,132,11,11,\"נְגִיד בֵּית הָאֱלֹהִים. מְמֻנֶּה עַל בֵּית אֱלֹהִים:\",2,0],[2,132,11,12,\"וַאֲחֵיהֶם עֹשֵׂה הַמְּלָאכָה לַבָּיִת. וְחַבְרֵיהֶם שֶׁהָיוּ עוֹבְדִים עֲבוֹדַת הַבַּיִת וְקָרְבְּנוֹתָיו:\",1,0],[2,132,11,13,\"רָאשִׁים לְאָבוֹת. רָאשֵׁי בֵית אָב מִמִּשְׁפְּחוֹת הַכֹּהֲנִים:\",1,0],[2,132,11,14,\"וּפָקִיד עֲלֵיהֶם. מְמֻנֶּה עֲלֵיהֶם:\",1,0],[2,132,11,16,\"עַל הַמְּלָאכָה הַחִיצוֹנָה. אֲשֶׁר לַבַּיִת, כְּגוֹן בִּנְיָנֵי בֶדֶק הַבַּיִת וַעֲצֵי הַמַּעֲרָכָה שֶׁהָיוּ מְבִיאִים מִבַּחוּץ:\",1,0],[2,132,11,17,\"רֹאשׁ הַתְּחִלָּה יְהוֹדֶה לַתְּפִלָּה. הוּא הָיָה רֹאשׁ וּמְמֻנֶּה וְגָדוֹל לִפְתֹּחַ תְּחִלָּה לְהוֹדוֹת בַּתְּפִלָּה וּבִזְמִירוֹת שִׁירוֹתֵיהֶם שֶׁל לְוִיִּם. יְהוֹדֶה כְּמוֹ יוֹדֶה, וְהַהֵ״א נִכְנֶסֶת בַּתֵּיבָה שֶׁלֹּא לְצֹרֶךְ, כְּמוֹ יוֹסֵף יְהוֹסֵף (תהלים פא:ו):\",1,0],[2,132,11,19,\"וְהַשּׁוֹעֲרִים. מְמֻנִּין עַל שַׁעֲרֵי הַמִּקְדָּשׁ:\",1,0],[2,132,11,20,\"אִישׁ בְּנַחֲלָתוֹ. כָּל אֶחָד בְּנַחֲלָתוֹ הָיוּ יוֹשְׁבִים׃\",1,0],[2,132,11,21,\"בָּעֹפֶל. מָקוֹם אֶחָד אֲשֶׁר בִּירוּשָׁלַיִם:\",1,0],[2,132,11,21,\"עַל הַנְּתִינִים. מְמֻנִּים עַל הַנְּתִינִים:\",2,0],[2,132,11,22,\"וּפְקִיד הַלְוִיִּם. מְמֻנֶּה עַל הַלְוִיִּם אֲשֶׁר בִּירוּשָׁלִַם:\",1,0],[2,132,11,22,\"לְנֶגֶד מְלֶאכֶת. עַל מְלֶאכֶת הַבַּיִת מְמֻנֶּה, כְּגוֹן בִּנְיָנֵי בֶּדֶק הַבַּיִת וּשְׁאָר דְּבָרִים שֶׁמּוֹצִיאִין מָמוֹן לְמַעֲשֵׂה (לְמַעֲשַׂר) הַבַּיִת, כְּעִנְיָן שֶׁנֶּאֱמַר לְמַעְלָה ״וְשַׁבְּתַי וְיוֹזָבָד עַל הַמְּלָאכָה הַחִיצוֹנָה וְגוֹ׳״ (נחמיה יא:טז)׃\",2,0],[2,132,11,23,\"כִּי מִצְוַת הַמֶּלֶךְ עֲלֵיהֶם. וְהַמֶּלֶךְ הָיָה מַאֲמִין בָּהֶם:\",1,0],[2,132,11,23,\"עַל הַמְשׁוֹרְרִים. לְהוֹצִיא מָמוֹן מֵאוֹצַר הַמֶּלֶךְ דָּרְיָוֶשׁ:\",2,0],[2,132,11,23,\"דְּבַר יוֹם בְּיוֹמוֹ. כְּדֵי לַעֲשׂוֹת צָרְכֵי הַבַּיִת:\",3,0],[2,132,11,24,\"לְיַד הַמֶּלֶךְ. הוּא הָיָה מִצְרָן לַעֲצַת הַמֶּלֶךְ דָּרְיָוֶשׁ:\",1,0],[2,132,11,24,\"לְכָל דָּבָר. לְכָל דִּבְרֵיהֶם אֲשֶׁר לָעָם לְדַבֵּר עֲלֵיהֶם אֶל הַמֶּלֶךְ:\",2,0],[2,132,11,36,\"מַחְלְקוֹת יְהוּדָה לְבִנְיָמִין. הָיוּ מְחַלְּקִין בְּמַחְלְקוֹתָם אָנָה וָאָנָה בְּאֶרֶץ יְהוּדָה וּבִנְיָמִין:\",1,0],[2,132,12,1,\"וְיֵשׁוּעַ. הוּא יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל:\",1,0],[2,132,12,7,\"בִּימֵי יֵשׁוּעַ. שֶׁהָיוּ רָאשִׁים בִּימֵי יְהוֹשֻׁעַ כֹּהֵן גָּדוֹל:\",1,0],[2,132,12,8,\"הֻיְּדוֹת. מִן כְּלֵי שִׁיר, לוֹמַר שִׁירָה:\",1,0],[2,132,12,9,\"לְמִשְׁמָרוֹת. כְּמוֹ שֶׁמָּצִינוּ (דברי הימים א כד:א ואילך) שֶׁהַלְוִיִּם הָיוּ חֲלוּקִים לְעֶשְׂרִים וְאַרְבָּעָה מִשְׁמָרוֹת:\",1,0],[2,132,12,10,\"וְיֵשׁוּעַ הוֹלִיד אֶת יוֹיָקִים וְגוֹ׳. כָּל אֵלּוּ שֶׁבְּמִקְרָא זֶה הָיוּ כֹּהֲנִים גְּדוֹלִים:\",1,0],[2,132,12,12,\"וּבִימֵי יוֹיָקִים. שֶׁהָיָה כֹּהֵן גָּדוֹל הָיוּ כֹהֲנִים הַלָּלוּ, הֵם הָיוּ רָאשִׁים, רָאשֵׁי בֵּית אָב לְמִשְׁמְרוֹתָם:\",1,0],[2,132,12,12,\"לִשְׂרָיָה מְרָיָה. לְמִשְׁמֶרֶת שֶׁל שְׂרָיָה הָיָה מְרָיָה רֹאשׁ בֵּית אָב, וּלְמִשְׁמֶרֶת שֶׁל יִרְמְיָה הָיָה חֲנַנְיָה רֹאשׁ בֵּית אָב, וְכֵן כֻּלָּם. וְאֶת אֲשֶׁר לֹא פֵּרַשׁ כָּל הָעֶשְׂרִים וְאַרְבַּע מִשְׁמָרוֹת, לֹא דִקְדֵּק הַמִּקְרָא בְּכָךְ לִמְנוֹתָם כֻּלָּם:\",2,0],[2,132,12,22,\"הַלְוִיִּם בִּימֵי אֶלְיָשִׁיב. הַלְוִיִּם הַלָּלוּ הָיוּ רָאשֵׁי בֵית אָבוֹת בְּמִשְׁמְרוֹת הַלְוִיִּם בִּימֵי אֶלְיָשִׁיב הַכֹּהֵן הַגָּדוֹל, וְהַכֹּהֲנִים הַמְּנוּיִין לְמַעְלָה בְּסָמוּךְ (פסוקים א-כא) הֵם הָיוּ רָאשֵׁי בֵית אָבוֹת בְּמִשְׁמְרוֹתָם גַּם בִּימֵי אֶלְיָשִׁיב:\",1,0],[2,132,12,22,\"עַל מַלְכוּת. בִּימֵי מַלְכוּת דָּרְיָוֶשׁ הָיָה דָּבָר זֶה:\",2,0],[2,132,12,23,\"וְעַד יְמֵי יוֹחָנָן. כָּל אוֹתָן שֶׁהָיוּ רָאשֵׁי אָבוֹת הַלְוִיִּם עַד יְמֵי יוֹחָנָן כֹּהֵן גָּדוֹל מְנוּיִין שָׁם בְּדִבְרֵי הַיָּמִים:\",1,0],[2,132,12,24,\"מִשְׁמָר לְעֻמַּת מִשְׁמָר. שֶׁהָיוּ חֲלוּקִים בְּמִשְׁמְרוֹתָם לוֹמַר שִׁירָה:\",1,0],[2,132,12,25,\"שׁוֹעֲרִים מִשְׁמָר. שׁוֹעֲרִים הָיוּ בְמִשְׁמָר שֶׁלָּהֶם, לִשְׁמֹר שַׁעֲרֵי הַבַּיִת:\",1,0],[2,132,12,25,\"בָּאֲסוּפֵּי. כְּמוֹ בְּסִפֵּי הַשְּׁעָרִים (דברי הימים א ט:כב):\",2,0],[2,132,12,26,\"אֵלֶּה בִּימֵי יוֹיָקִים. אֵלֶּה הָיוּ שׁוֹעֲרִים בִּימֵי יוֹיָקִים:\",1,0],[2,132,12,27,\"וּבַחֲנֻכַּת חוֹמַת יְרוּשָׁלִָם. בְּתַשְׁלוּם חוֹמַת הָעִיר, לְקַדֵּשׁ אֶת הָעִיר:\",1,0],[2,132,12,27,\"וּבְתוֹדוֹת. וּבְהוֹדָאוֹת:\",2,0],[2,132,12,28,\"וּמִן הַכִּכָּר. אֲשֶׁר סְבִיבוֹת יְרוּשָׁלִַם בָּאוּ הַמְשׁוֹרְרִים:\",1,0],[2,132,12,30,\"וַיִּטַּהֲרוּ. תְּחִלָּה טִהֲרוּ אֶת עַצְמָן, וְאַחַר כָּךְ טִהֲרוּ אֶת אֲחֵרִים:\",1,0],[2,132,12,30,\"וְאֶת הַשְּׁעָרִים וְאֶת הַחוֹמָה. שֶׁלֹּא תִהְיֶה טֻמְאָה שָׁם בָּעִיר:\",2,0],[2,132,12,31,\"מֵעַל לַחוֹמָה. שֶׁקִּדֵּשׁ אֶת הָעִיר, וְהָלְכוּ הַשָּׂרִים וּבֵית דִּין וְהַכֹּהֲנִים וְהַלְוִיִּם עִם שְׁתֵּי תוֹדוֹת סָבִיב לָעִיר. הַכֹּל כַּמְפֹרָשׁ בְּמַסֶּכֶת שְׁבוּעוֹת (שבועות טו,א), כְּדֵי לְקַדֵּשׁ אֶת הָעִיר:\",1,0],[2,132,12,31,\"שְׁתֵּי תוֹדוֹת. שְׁתֵּי לַחְמֵי תוֹדָה, כָּל לֶחֶם וָלֶחֶם קָרוּי תּוֹדָה:\",2,0],[2,132,12,31,\"וְתַהֲלוּכוֹת לַיָּמִין. וְכַאֲשֶׁר יָצְאוּ מִן הָעִיר כְּדֵי לְסוֹבְבָהּ, הָלְכוּ לְצַד יְמִינָהּ:\",3,0],[2,132,12,34,\"יְהוּדָה וּבִנְיָמִין. שְׁנֵי שָׂרִים הָיוּ:\",1,0],[2,132,12,36,\"וְאֶחָיו. חֲבֵירָיו שֶׁל זְכַרְיָה הַכֹּהֵן (נחמיה יב:לה):\",1,0],[2,132,12,37,\"וְעַל שַׁעַר הָעַיִן. לִפְנֵי שַׁעַר הָעַיִן הָלְכוּ סְבִיבוֹת הָעִיר:\",1,0],[2,132,12,37,\"וְנֶגְדָּם עָלוּ. וּלְפָנֵיהֶם עָלוּ מִשַּׁעַר הָעַיִן לְמַעֲלוֹת שֶׁל עִיר דָּוִד וְאוֹתָן מַעֲלוֹת הָיוּ לַחוֹמָה:\",2,0],[2,132,12,38,\"וְהַתּוֹדָה הַשֵּׁנִית הַהוֹלֶכֶת לְמוֹל. תּוֹדָה אַחֶרֶת שֶׁהָיְתָה שֵׁנִית לַחֲבֶרְתָּהּ הָיְתָה הוֹלֶכֶת נֶגֶד חֲבֶרְתָּהּ בְּשָׁוֶה, וְלֹא זוֹ אַחַר זוֹ:\",1,0],[2,132,12,38,\"וַאֲנִי אַחֲרֶיהָ. וַאֲנִי הָיִיתִי הוֹלֵךְ אַחֲרֶיהָ שֶׁל תּוֹדָה:\",2,0],[2,132,12,39,\"וְעָמְדוּ. שָׁם הָיוּ עוֹמְדִים, שֶׁלֹּא לֵילֵךְ יוֹתֵר:\",1,0],[2,132,12,40,\"שְׁתֵּי הַתּוֹדוֹת. שֶׁנָּשְׂאוּ אוֹתָם לְבֵית הַמִּקְדָּשׁ:\",1,0],[2,132,12,41,\"בַּחֲצוֹצְרוֹת. הָיוּ תּוֹקְעִין מִתּוֹךְ שִׂמְחָתָן:\",1,0],[2,132,12,44,\"וַיִּפָּקְדוּ. לְשׁוֹן פְּקִידוּת:\",1,0],[2,132,12,44,\"הַנְּשָׁכוֹת. כְּמוֹ הַלְּשָׁכוֹת שֶׁל בֵּית הַמִּקְדָּשׁ:\",2,0],[2,132,12,44,\"לִכְנוֹס בָּהֶם. וּבְאוֹתָן הַלְּשָׁכוֹת הָיוּ נוֹתְנִים כָּל מַתְּנוֹתֵיהֶם שֶׁל כֹּהֲנִים וּלְוִיִּם, וּמִשָּׁם הָיוּ חוֹלְקִין בֵּינֵיהֶם:\",3,0],[2,132,12,44,\"מְנָאוֹת. כְּמוֹ מָנוֹת (נחמיה ח:י):\",4,0],[2,132,12,44,\"לַכֹּהֲנִים לַלְוִיִּם. כֹּהֲנִים הָיוּ נוֹטְלִים הָרָאוּי לָהֶם וְהַלְוִיִּם הָרָאוּי לָהֶם:\",5,0],[2,132,12,44,\"הָעוֹמְדִים. וּמְשַׁמְּשִׁים שָׁם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּתוֹדוֹת וְהוֹדָאוֹת:\",6,0],[2,132,12,47,\"מְנָיוֹת. כְּמוֹ מָנוֹת (נחמיה ח:י):\",1,0],[2,132,12,47,\"וּמַקְדִּישִׁים לַלְוִיִּם. הָיוּ נוֹתְנִים בְּמַעֲשֵׂר לַלְוִיִּם, וְהֵם הָיוּ נוֹטְלִים מַעֲשֵׂר מִן הַמַּעֲשֵׂר וְנוֹתְנִים לַכֹּהֲנִים:\",2,0],[2,132,13,3,\"כָּל עֵרֶב. כָּל תַּעֲרוֹבוֹת הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, כְּמוֹ ״וְגַם עֵרֶב רַב עָלָה אִתָּם״ (שמות יב:לח):\",1,0],[2,132,13,4,\"וְלִפְנֵי מִזֶּה. וּמִקֹּדֶם לָכֵן:\",1,0],[2,132,13,4,\"קָרוֹב לְטוֹבִיָּה. אוֹתוֹ אֶלְיָשִׁיב הַכֹּהֵן הָיָה קָרוֹב לְטוֹבִיָּה חֲבֵרוֹ שֶׁל סַנְבַלַּט, וְנָתַן שָׁם הַכֹּהֵן כֵּלָיו שֶׁל טוֹבִיָּה:\",2,0],[2,132,13,5,\"וַיַּעַשׂ. אֶלְיָשִׁיב:\",1,0],[2,132,13,5,\"לְפָנִים. שָׁם הָיוּ נוֹתְנִים קֹדֶם שֶׁבָּאתִי לִירוּשָׁלָיִם:\",2,0],[2,132,13,5,\"מִצְוַת הַלְוִיִּם. מַתָּנוֹת הָרְאוּיוֹת לַלְוִיִּם:\",3,0],[2,132,13,6,\"וּבְכָל זֶה. וּבְכָל הַמַּעֲשֶׂה הַזֶּה בָּאתִי אֶל הַמֶּלֶךְ וְחָזַרְתִּי לְבָבֶל:\",1,0],[2,132,13,6,\"נִשְׁאַלְתִּי. שֶׁיִּתֵּן לִי רְשׁוּת לַעֲלוֹת לִירוּשָׁלַיִם וְלַחֲזוֹר:\",2,0],[2,132,13,9,\"וָאֹמְרָה. צִוִּיתִי לְטַהֵר, וַיְטַהֲרוּ הַלְּשָׁכוֹת וְגוֹמֵר:\",1,0],[2,132,13,10,\"מְנָיוֹת. מָנוֹת (נחמיה ח:י):\",1,0],[2,132,13,10,\"לֹא נִתָּנָה. שֶׁלֹּא נָתְנוּ יִשְׂרָאֵל שָׁם הַמַּתָּנוֹת, וְעַל כֵּן בָּרְחוּ וְהָלְכוּ לָהֶם אָנָה וָאָנָה לִשְׁאֹל מַתְּנוֹתֵיהֶם, וְלֹא הָיוּ עוֹסְקִים כָּל כָּךְ בַּעֲבוֹדָתָם:\",2,0],[2,132,13,11,\"וָאֶקְבְּצֵם. קִבַּצְתִּי אֶת הַכֹּהֲנִים וְהַלְוִיִּם לְהַעֲמִידָם עַל מִשְׁמַרְתָּם בַּעֲבוֹדָתָם, וְכָל יִשְׂרָאֵל הָיוּ מְבִיאִים לָהֶם שָׁם מַתְּנוֹתָם:\",1,0],[2,132,13,13,\"כִּי נֶאֱמָנִים. הָיוּ לַחֲלֹק הַמַּתָּנוֹת בֵּינֵיהֶם:\",1,0],[2,132,13,15,\"הָעֲרֵמוֹת. אֲלֻמּוֹת שֶׁל תְּבוּאָה:\",1,0],[2,132,13,15,\"וָאָעִיד. הֵעִידוֹתִי בָּהֶם שֶׁלֹּא לַעֲשׂוֹת:\",2,0],[2,132,13,15,\"בְּיוֹם מִכְרָם צָיִד. בְּיוֹם שֶׁהָיוּ מוֹכְרִים מָזוֹן וְצַיִד, צַיִד כְּמוֹ ״וַיִּתֵּן לָהֶם צֵידָה לַדֶּרֶךְ״ (בראשית מה:כא):\",3,0],[2,132,13,16,\"וְהַצּוֹרִים. סוֹחֲרִים שֶׁל צוֹר מְבִיאִים דָּגִים לִמְכּוֹר:\",1,0],[2,132,13,19,\"וַיְהִי כַּאֲשֶׁר צָלְלוּ. כַּאֲשֶׁר נָטוּ הַצְּלָלִים שֶׁל עֶרֶב שַׁבָּת בַּשְּׁעָרִים (ירמיהו ו:ד), צִוִּיתִי לִסְגֹּר דַּלְתוֹת הָעִיר, שֶׁלֹּא יִפָּתְחוּ עַד אַחַר שַׁבָּת, שֶׁלֹּא יָבוֹאוּ הָרוֹכְלִים בָּעִיר לִמְכֹּר סְחוֹרָתָן, כְּדֵי שֶׁלֹּא יְחַלְּלוּ יִשְׂרָאֵל אֶת הַשַּׁבָּת עַל יְדֵיהֶם:\",1,0],[2,132,13,20,\"וַיָּלִינוּ. וְהָיוּ לָנִים הָרוֹכְלִים וְהַסּוֹחֲרִים בְּיוֹם הַשַּׁבָּת מִחוּץ לִירוּשָׁלַיִם פַּעַם אַחַת וּשְׁתֵּי פְעָמִים, כְּדֵי שֶׁיָּבוֹאוּ בְנֵי יִשְׂרָאֵל לִפְתֹּחַ הַשְּׁעָרִים וְלִקְנוֹת מֵהֶם בַּשַּׁבָּת:\",1,0],[2,132,13,21,\"וָאֹמְרָה אֲלֵיהֶם. הִתְרֵיתִי בְּאוֹתָם הָרוֹכְלִים:\",1,0],[2,132,13,21,\"אִם תִּשְׁנוּ. אִם תּוֹסִיפוּ לַעֲשׂוֹת פַּעַם שְׁנִיָּה:\",2,0],[2,132,13,21,\"מִן הָעֵת. מִן אוֹתוֹ יוֹם וָהָלְאָה לֹא בָאוּ בְּיוֹם הַשַּׁבָּת:\",3,0],[2,132,13,23,\"הוֹשִׁיבוּ נָשִׁים. אֲשֶׁר נָשְׂאוּ לָהֶם נָשִׁים שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:\",1,0],[2,132,13,24,\"חֲצִי מְדַבֵּר. הַרְבֵּה מִבְּנֵיהֶם הָיוּ מְדַבְּרִים לְשׁוֹן אַשְׁדּוֹדִית כְּאִמּוֹתָם:\",1,0],[2,132,13,25,\"וָאַכֶּה. נָתַתִּי לָהֶם מַלְקִיּוֹת לְהַלְקוֹתָם כְּדֵי לְהוֹכִיחָם וּלְהַזְכִּירָם:\",1,0],[2,132,13,26,\"גַּם אוֹתוֹ הֶחֱטִיאוּ. כָּל שֶׁכֵּן שֶׁתִּהְיוּ חוֹטְאִים עַל יְדֵי נְשֵׁיכֶם שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, וְזֶהוּ שֶׁנֶּאֱמַר בְּסָמוּךְ וְלָכֶם הֲנִשְׁמַע וְגוֹ׳ בִּתְמִיהָּה. כְּלוֹמַר: שְׁלֹמֹה מֶלֶךְ יִשְׂרָאֵל נִמְצָא חָטָא עַל יְדֵי נָשִׁים שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, וְאַתֶּם נְשָׂאתֶם נָשִׁים שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת לִהְיוֹת חוֹטְאִין:\",1,0],[2,132,13,28,\"וּמִבְּנֵי יוֹיָדָע… חָתָן לְסַנְבַּלַּט. אֶחָד מִבְּנֵי יוֹיָדָע חָתָן לְסַנְבַּלַּט צוֹרֵר הַיְּהוּדִים, וְהִבְרַחְתִּיהוּ מֵעָלָי, לְמַעַן לֹא יִהְיֶה רָגִיל בִּירוּשָׁלַיִם בִּשְׁבִיל חֲתָנוֹ, לִרְאוֹת אֶת הָעִיר וְאֶת מוֹצָאֶיהָ וְאֶת מוֹבָאֶיהָ:\",1,0],[2,132,13,29,\"זָכְרָה לָהֶם. הַטּוֹבָה אֲשֶׁר עָשׂוּ:\",1,0],[2,132,13,31,\"בְּעִתִּים. לְעִתִּים הָיוּ כּוֹרְתִים עֵצִים לַמַּעֲרָכָה:\",1,0],[2,132,13,31,\"וְלַבִּכּוּרִים. שֶׁהָיוּ מְבִיאִים בִּכּוּרִים בְּפֶרֶק אֶחָד, לְכָל דָּבָר וְדָבָר קָבַעְתִּי זְמַנּוֹ:\",2,0],[2,133,1,1,\"וידבר. במדבר סיני באחד לחדש וגו'. מִתּוֹךְ חִבָּתָן לְפָנָיו מוֹנֶה אוֹתָם כָּל שָׁעָה — כְּשֶׁיָּצְאוּ מִמִּצְרַיִם מְנָאָן, וּכְשֶׁנָּפְלוּ בָּעֵגֶל מְנָאָן לֵידַע מִנְיַן הַנּוֹתָרִים, כְּשֶׁבָּא לְהַשְׁרוֹת שְׁכִינָתוֹ עֲלֵיהֶם מְנָאָם, בְּאֶחָד בְּנִיסָן הוּקַם הַמִּשְׁכָּן וּבְאֶחָד בְּאִיָּר מְנָאָם:\",1,0],[2,133,1,2,\"למשפחתם. לֵידַע מִנְיַן כָּל שֵׁבֶט וָשֵׁבֶט:\",1,0],[2,133,1,2,\"לבית אבתם. מִי שֶׁאָבִיו מִשֵּׁבֶט אֶחָד וְאִמּוֹ מִשֵּׁבֶט אַחֵר יָקוּם עַל שֵׁבֶט אָבִיו (עי' בבא בתרא ק\\\"ט):\",2,0],[2,133,1,2,\"לגלגלתם. עַ\\\"יְ שְׁקָלִים — בֶּקַע לַגֻּלְגֹּלֶת:\",3,0],[2,133,1,3,\"כל יצא צבא. מַגִּיד שֶׁאֵין יוֹצֵא בַּצָּבָא פָּחוּת מִבֶּן עֶשְׂרִים:\",1,0],[2,133,1,4,\"ואתכם יהיו. כְּשֶׁתִּפְקְדוּ אוֹתָם יִהְיוּ עִמָּכֶם נְשִׂיא כָל שֵׁבֶט וָשֵׁבֶט:\",1,0],[2,133,1,16,\"אלה קרואי העדה. הַנִּקְרָאִים לְכָל דְּבַר חֲשִׁיבוּת שֶׁבָּעֵדָה:\",1,0],[2,133,1,17,\"האנשים האלה. אֶת שְׁנֵים עָשָׂר נְשִׂיאִים הַלָּלוּ:\",1,0],[2,133,1,17,\"אשר נקבו. לוֹ כָּאן בשמות:\",2,0],[2,133,1,18,\"ויתילדו על משפחתם. הֵבִיאוּ סִפְרֵי יִחוּסֵיהֶם וְעֵדֵי חֶזְקַת לֵדָתָם, כָּל אֶחָד וְאֶחָד לְהִתְיַחֵס עַל הַשֵּׁבֶט (עי' ילקוט תרפ\\\"ד):\",1,0],[2,133,1,49,\"אך את מטה לוי לא תפקד. כְּדַאי הוּא לִגְיוֹן שֶׁל מֶלֶךְ לִהְיוֹת נִמְנֶה לְבַדּוֹ (תנחומא); דָּ\\\"אַ, צָפָה הַקָּבָּ\\\"ה שֶׁעֲתִידָה לַעֲמֹד גְּזֵרָה עַל כָּל הַנִּמְנִין מִבֶּן עֶשְֹרִים שָׁנָה וָמַעְלָה שֶׁיָּמוּתוּ בַמִּדְבָּר, אָמַר אַל יִהְיוּ אֵלּוּ בִכְלָל, לְפִי שֶׁהֵם שֶׁלִּי, שֶׁלֹּא טָעוּ בָעֵגֶל (שם; בבא בתרא קכ\\\"א):\",1,0],[2,133,1,50,\"ואתה הפקד את הלוים. כְּתַרְגּוּמוֹ \\\"מַנִּי\\\", לְשׁוֹן מִנּוּי שְׂרָרָה עַל דָּבָר שֶׁהוּא מְמֻנֶּה עָלָיו, כְּמוֹ \\\"וְיַפְקֵד הַמֶּלֶךְ פְּקִידִים\\\" (אסתר ב'):\",1,0],[2,133,1,51,\"יורידו אתו. כְּתַרְגּוּמוֹ \\\"יְפָרְקוּן\\\", כְּשֶׁבָּאִין לִסַּע בַּמִּדְבָּר מִמַּסָּע לְמַסָּע הָיוּ מְפָרְקִין אוֹתוֹ מֵהֲקָמָתוֹ, וְנוֹשְׂאִין אוֹתוֹ עַד מָקוֹם אֲשֶׁר יִשְׁכֹּן שָׁם הֶעָנָן, וְיַחֲנוּ שָׁם וּמְקִימִין אוֹתוֹ:\",1,0],[2,133,1,51,\"והזר הקרב. לַעֲבוֹדָתָם זוֹ:\",2,0],[2,133,1,51,\"יומת. בִּידֵי שָׁמַיִם:\",3,0],[2,133,1,52,\"ואישׁ על דגלו. כְּמוֹ שֶׁהַדְּגָלִים סְדוּרִים בְּסֵפֶר זֶה – שְׁלֹשָׁה שְׁבָטִים לְכָל דֶּגֶל:\",1,0],[2,133,1,53,\"ולא יהיה קצף. אִם תַּעֲשׂוּ כְּמִצְוֹתַי לֹא יִהְיֶה קֶצֶף, וְאִם לָאו, שֶׁיִּכָּנְסוּ זָרִים בַּעֲבוֹדָתָם זוֹ, יִהְיֶה קֶצֶף, כְּמוֹ שֶׁמָּצִינוּ בְמַעֲשֵׂה קֹרַח (במדבר י\\\"ז), כִּי יָצָא הַקֶּצֶף וְגוֹ':\",1,0],[2,133,2,2,\"באתת. כָּל דֶּגֶל יִהְיֶה לוֹ אוֹת מַפָּה צְבוּעָה תְלוּיָה בוֹ, צִבְעוֹ שֶׁל זֶה לֹא כְצִבְעוֹ שֶׁל זֶה, צֶבַע כָּל אֶחָד כְּגוֹן אַבְנוֹ הַקְּבוּעָה בַחֹשֶׁן, וּמִתּוֹךְ כָּךְ יַכִּיר כָּל אֶחָד אֶת דִּגְלוֹ; דָּ\\\"אַ: בְּאוֹתוֹת לְבֵית אֲבוֹתָם, בְּאוֹת שֶׁמָּסַר לָהֶם יַעֲקֹב אֲבִיהֶם כְּשֶׁנְּשָׂאוּהוּ מִמִּצְרַיִם שֶׁנֶּאֱמַר (בראשית נ') \\\"וַיַּעֲשׂוּ בָנָיו לוֹ כֵּן כַּאֲשֶׁר צִוָּם, יְהוּדָה וְיִשָּׂשכָר וּזְבוּלוּן יִשָּׂאוּהוּ מִן הַמִּזְרָח, וּרְאוּבֵן וְשִׁמְעוֹן וְגָד מִן הַדָּרוֹם וְכוּ'\\\", כִּדְאִיתָא בְתַנְחוּמָא בְּפַרָשָׁה זוֹ:\",1,0],[2,133,2,2,\"מנגד. מֵרָחוֹק מִיל, כְּמוֹ שֶׁנֶּאֱמַר בִּיהוֹשֻׁעַ \\\"אַךְ רָחוֹק יִהְיֶה בֵּינֵיכֶם וּבֵנָיו כְּאַלְפַּיִם אַמָּה\\\" (יהושע ג'), שֶׁיּוּכְלוּ לָבֹא בְּשַׁבָּת; מֹשֶׁה וְאַהֲרֹן וּבָנָיו וְהַלְוִיִּם חוֹנִים בְּסָמוּךְ לוֹ:\",2,0],[2,133,2,3,\"קדמה. לְפָנִים הַקְּרוּיָה קֶדֶם: וְאֵיזוֹ זוֹ רוּחַ מִזְרָחִית, וְהַמַּעֲרָב קָרוּי אָחוֹר:\",1,0],[2,133,2,9,\"ראשנה יסעו. כְּשֶׁרוֹאִין הֶעָנָן מִסְתַּלֵּק, תּוֹקְעִין הַכֹּהֲנִים בַּחֲצוֹצְרוֹת, וְנוֹסֵעַ מַחֲנֵה יְהוּדָה תְחִלָּה, וּכְשֶׁהוֹלְכִין הוֹלְכִין כְּדֶרֶךְ חֲנִיָּתָן — הַלְוִיִּם וְהָעֲגָלוֹת בָּאֶמְצָע, דֶּגֶל יְהוּדָה בַּמִּזְרָח, וְשֶׁל רְאוּבֵן בַּדָּרוֹם, וְשֶׁל אֶפְרַיִם בַּמַּעֲרָב, וְשֶׁל דָּן בַּצָּפוֹן:\",1,0],[2,133,2,17,\"ונסע אהל מועד. לְאַחַר שְׁנֵי דְגָלִים הַלָּלוּ:\",1,0],[2,133,2,17,\"כאשר יחנו כן יסעו. כְּמוֹ שֶׁפֵּרַשְׁתִּי, הֲלִיכָתָן כַּחֲנִיָּתָן, כָּל דֶּגֶל מְהַלֵּךְ לָרוּחַ הַקָּבוּעַ לוֹ:\",2,0],[2,133,2,17,\"על ידו. עַל מְקוֹמוֹ, וְאֵין לְשׁוֹן יָד זָז מִמַּשְׁמָעוֹ, רוּחַ שֶׁל צִדּוֹ קָרוּי עַל יָדוֹ – הַסְּמוּכָה לוֹ לְכָל הוֹשָׁטַת יָדוֹ, אינשו\\\"ן איש\\\"א בְּלַעַז:\",3,0],[2,133,2,20,\"ועליו. כְּתַרְגּוּמוֹ \\\"וְדִסְמִיכִין עֲלוֹהִי\\\":\",1,0],[2,133,3,1,\"ואלה תולדת אהרן ומשה. וְאֵינוֹ מַזְכִּיר אֶלָּא בְנֵי אַהֲרֹן וְנִקְרְאוּ תוֹלְדוֹת מֹשֶׁה, לְפִי שֶׁלִּמְּדָן תּוֹרָה, מְלַמֵּד שֶׁכָּל הַמְלַמֵּד אֶת בֶּן חֲבֵרוֹ תּוֹרָה מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ יְלָדוֹ (סנהדרין י\\\"ט):\",1,0],[2,133,3,1,\"ביום דבר ה' את משה. נַעֲשׂוּ אֵלּוּ הַתּוֹלָדוֹת שֶׁלּוֹ, שֶׁלִּמְּדָן מַה שֶּׁלָּמַד מִפִּי הַגְּבוּרָה:\",2,0],[2,133,3,4,\"על פני אהרן. בְּחַיָּיו:\",1,0],[2,133,3,6,\"ושרתו אתו. וּמַהוּ הַשֵּׁרוּת?\",1,0],[2,133,3,6,\"ושמרו את משמרתו. לְפִי שֶׁשְּׁמִירַת הַמִּקְדָּשׁ עָלָיו שֶׁלֹּא יִקְרַב זָר, כְּמוֹ שֶׁנֶּאֱמַר \\\"אַתָּה וּבָנֶיךָ וּבֵית אָבִיךָ אִתָּךְ תִּשְׂאוּ אֶת עֲוֹן הַמִּקְדָּשׁ\\\" (במדבר י\\\"ח), וְהַלְוִיִּם הַלָּלוּ מְסַיְּעִין אוֹתָם, זוֹ הִיא הַשֵּׁרוּת:\",2,0],[2,133,3,7,\"ושמרו את משמרתו. כָּל מִנּוּי שֶׁהָאָדָם מְמֻנֶּה עָלָיו וּמֻטָּל עָלָיו לַעֲשׂוֹתוֹ קָרוּי מִשְׁמֶרֶת בְּכָל הַמִּקְרָא וּבִלְשׁוֹן הַמִּשְׁנָה, כְּמוֹ שֶׁאָמוּר בְּבִגְתָן וָתֶרֶשׁ \\\"וַהֲלֹא אֵין מִשְׁמַרְתִּי וּמִשְׁמַרְתְּךָ שָׁוָה\\\" (מגילה י\\\"ג), וְכֵן מִשְׁמְרוֹת כְהֻנָּה וּלְוִיָּה:\",1,0],[2,133,3,8,\"ואת משמרת בני ישראל. שֶׁכֻּלָּן הָיוּ זְקוּקִין לְצָרְכֵי הַמִּקְדָּשׁ, אֶלָּא שֶׁהַלְוִיִּם בָּאִים תַּחְתֵּיהֶם בִּשְׁלִיחוּתָם, לְפִיכָךְ לוֹקְחִים מֵהֶם הַמַּעַשְׂרוֹת בִּשְׂכָרָן, שֶׁנֶּאֱמַר \\\"כִּי שָׂכָר הוּא לָכֶם חֵלֶף עֲבֹדַתְכֶם\\\" (במדבר י\\\"ח):\",1,0],[2,133,3,9,\"נתונם המה לו. לְעֶזְרָה:\",1,0],[2,133,3,9,\"מאת בני ישראל. כְּמוֹ מִתּוֹךְ בְּנֵי יִשׂרָאֵל, כְּלוֹמַר מִשְּׁאָר כָּל הָעֵדָה נִבְדְּלוּ לְכָךְ בִּגְזֵרַת הַמָּקוֹם וְהוּא נְתָנָם לוֹ, שֶׁנֶּאֱמַר \\\"וָאֶתְּנָה אֶת הַלְוִיִּם נְתֻנִים\\\" וְגוֹ' (במדבר ח'):\",2,0],[2,133,3,10,\"ואת אהרן ואת בניו תפקד. לְשׁוֹן פְּקִידוּת, וְאֵינוֹ לְשׁוֹן מִנְיָן:\",1,0],[2,133,3,10,\"ושמרו את כהנתם. קַבָּלַת דָּמִים וּזְרִיקָה וְהַקְטָרָה וַעֲבוֹדוֹת הַמְּסוּרוֹת לַכֹּהֲנִים:\",2,0],[2,133,3,12,\"ואני הנה לקחתי. וַאֲנִי מֵהֵיכָן זָכִיתִי בָהֶן מתוך בני ישראל שֶׁיִּהְיוּ יִשְׂרָאֵל שׂוֹכְרִין אוֹתָן לְשֵׁרוּת שֶׁלִּי? עַ\\\"יְ הַבְּכוֹרוֹת זָכִיתִי בָהֶם וּלְקַחְתִּים תְּמוּרָתָם. לְפִי שֶׁהָיְתָה הָעֲבוֹדָה בַּבְּכוֹרוֹת, וּכְשֶׁחָטְאוּ בָעֵגֶל נִפְסְלוּ, וְהַלְוִיִּם שֶׁלֹּא עָבְדוּ עֲ\\\"זָ נִבְחֲרוּ תַחְתֵּיהֶם (עי' זבחים קי\\\"ב):\",1,0],[2,133,3,15,\"מבן חדש ומעלה. מִשֶּׁיָּצָא מִכְּלַל נְפָלִים הוּא נִמְנֶה לִקָּרֵא שׁוֹמֵר מִשְׁמֶרֶת הַקֹּדֶשׁ; אָ\\\"רַ יְהוּדָה בְּרַבִּי שָׁלוֹם לָמוּד הוּא אוֹתוֹ הַשֵּׁבֶט לִהְיוֹת נִמְנֶה מִן הַבֶּטֶן, שֶׁנֶּאֱמַר \\\"אֲשֶׁר יָלְדָה אֹתָהּ לְלֵוִי בְּמִצְרָיִם\\\" (במדבר כ״ו:נ״ט), — עִם כְּנִיסָתָהּ בְּפֶתַח מִצְרַיִם יָלְדָה אוֹתָהּ וְנִמְנֵית בְּשִׁבְעִים נֶפֶשׁ, שֶׁכְּשֶׁאַתָּה מוֹנֶה חֶשְׁבּוֹנָם לֹא תִמְצָאֵם אֶלָּא שִׁבְעִים חָסֵר אֶחָד, וְהִיא הִשְׁלִימָה אֶת הַמִּנְיָן (תנחומא):\",1,0],[2,133,3,16,\"על פי ה'. אָמַר מֹשֶׁה לִפְנֵי הַקָּבָּ\\\"ה, הֵיאַךְ אֲנִי נִכְנָס לְתוֹךְ אָהֳלֵיהֶם לָדַעַת מִנְיַן יוֹנְקֵיהֶם? אָמַר לוֹ הַקָּבָּ\\\"ה, עֲשֵׂה אַתָּה שֶׁלְּךְ וַאֲנִי אֶעֱשֶׂה שֶׁלִּי, הָלַךְ מֹשֶׁה וְעָמַד עַל פֶּתַח הָאֹהֶל וְהַשְּׁכִינָה מַקְדֶּמֶת לְפָנָיו, וּבַת קוֹל יוֹצְאָה מִן הָאֹהֶל וְאוֹמֶרֶת כָּךְ וָכָךְ תִּינוֹקוֹת יֵשׁ בְּאֹהֶל זֶה, לְכָךְ נֶאֱמַר עַל פִּי ה':\",1,0],[2,133,3,21,\"לגרשון משפחת הלבני. כְּלוֹמַר, לְגֵרְשׁוֹן הָיוּ הַפְּקוּדִים מִשְׁפַּחַת הַלִּבְנִי וּמִשְׁפַּחַת הַשִּׁמְעִי — פְּקוּדֵיהֶם כָּךְ וְכָךְ:\",1,0],[2,133,3,25,\"המשכן. יְרִיעוֹת הַתַּחְתּוֹנוֹת:\",1,0],[2,133,3,25,\"והאהל. יְרִיעוֹת עִזִּים הָעֲשׂוּיוֹת לְגַג:\",2,0],[2,133,3,25,\"מכסהו. עוֹרוֹת אֵילִים וּתְחָשִׁים:\",3,0],[2,133,3,25,\"ומסך פתח. הוּא הַוִּילוֹן:\",4,0],[2,133,3,26,\"ואת מיתריו. שֶׁל הַמִשְׁכָּן וְהָאֹהֶל, וְלֹא שֶׁל חָצֵר:\",1,0],[2,133,3,29,\"משפחת בני קהת יחנו … תימנה. וּסְמוּכִין לָהֶם דֶּגֶל רְאוּבֵן הַחוֹנִים תֵּימָנָה — אוֹי לָרָשָׁע אוֹי לִשְׁכֵנוֹ, לְכָךְ לָקוּ מֵהֶם דָּתָן וַאֲבִירָם וּמָאתַיִם וַחֲמִשִּׁים אִישׁ עִם קֹרַח וַעֲדָתוֹ, שֶׁנִּמְשְׁכוּ עִמָּהֶם בְּמַחֲלָקְתָּם (תנחומא):\",1,0],[2,133,3,31,\"והמסך. הִיא הַפָּרֹכֶת, שֶׁאַף הִיא קְרוּיָה פָּרֹכֶת הַמָּסָךְ:\",1,0],[2,133,3,32,\"ונשיא נשיאי הלוי. מְמֻנֶּה עַל כֻּלָּם, וְעַל מַה הִיא נְשִׂיאוּתוֹ —\",1,0],[2,133,3,32,\"פקדת שמרי משמרת — עַל יָדוֹ הִיא פְּקֻדַּת כֻּלָּם:\",2,0],[2,133,3,38,\"משה ואהרן ובניו. וּסְמוּכִין לָהֶם דֶּגֶל מַחֲנֵה יְהוּדָה, וְהַחוֹנִים עָלָיו יִשָּׂשכָר וּזְבוּלֻן — טוֹב לַצַּדִיק טוֹב לִשְׁכֵנוֹ, לְפִי שֶׁהָיוּ שְׁכֵנָיו שֶׁל מֹשֶׁה שֶׁהָיָה עוֹסֵק בַּתּוֹרָה, נַעֲשׂוּ גְדוֹלִים בַּתּוֹרָה, שֶׁנֶּאֱמַר \\\"יְהוּדָה מְחֹקְקִי\\\" (תהלים ס, ט), \\\"וּמִבְּנֵי יִשָּׂשכָר יוֹדְעֵי בִינָה וְגוֹ' מָאתַיִם\\\" (דהי\\\"א י\\\"ב) — רָאשֵׁי סַנְהֶדְרָאוֹת, \\\"וּמִזְּבוּלֻן מֹשְׁכִים בְּשֵׁבֶט סֹפֵר\\\" (שופטים ה, יד) (תנחומא):\",1,0],[2,133,3,39,\"אשר פקד משה ואהרן. נָקוּד עַל וְאַהֲרֹן, לוֹמַר שֶׁלֹּא הָיָה בְּמִנְיַן הַלְוִיִּם (בכורות ד'):\",1,0],[2,133,3,39,\"שנים ועשרים אלף. וּבִפְרָטָן אַתָּה מוֹצֵא שְׁלֹשׁ מֵאוֹת יְתֵרִים — בְּנֵי גֵּרְשׁוֹן שִׁבְעַת אֲלָפִים וַחֲמֵשׁ מֵאוֹת, בְּנֵי קְהָת שְׁמוֹנַת אֲלָפִים וְשֵׁשׁ מֵאוֹת, בְּנֵי מְרָרִי שֵׁשֶׁת אֲלָפִים וּמָאתָיִם; וְלָמָּה לֹא כְלָלָן עִם הַשְּׁאָר וְיִפְדּוּ אֶת הַבְּכוֹרוֹת וְלֹא יִהְיוּ זְקוּקִים הַשְּׁלֹשָׁה וְשִׁבְעִים וּמָאתַיִם בְּכוֹרוֹת הָעוֹדְפִים עַל הַמִּנְיָן לְפִדְיוֹן? אָמְרוּ רַבּוֹתֵינוּ בְמַסֶּכֶת בְּכוֹרוֹת (דף ה'), אוֹתָן שְׁלֹשׁ מֵאוֹת לְוִיִּם בְּכוֹרוֹת הָיוּ, וְדַיָּם שֶׁיַּפְקִיעוּ עַצְמָם מִן הַפִּדְיוֹן:\",2,0],[2,133,3,40,\"פקד כל בכר זכר מבן חדש ומעלה. מִשֶּׁיָּצָא מִכְּלַל סְפֵק נְפָלִים:\",1,0],[2,133,3,45,\"ואת בהמת הלוים וגו'. לֹא פָדוּ בְהֵמוֹת הַלְוִיִּם אֶת בְּכוֹרֵי בְהֵמָה טְהוֹרָה שֶׁל יִשְׂרָאֵל אֶלָּא אֶת פִּטְרֵי חֲמוֹרֵיהֶם, וְשֶׂה אֶחָד שֶׁל בֶּן לֵוִי פָּטַר כַּמָּה פִטְרֵי חֲמוֹרִים שֶׁל יִשְׂרָאֵל. תֵּדַע, שֶׁהֲרֵי מָנָה הָעוֹדְפִים בָּאָדָם וְלֹא מָנָה הָעוֹדְפִים בַּבְּהֵמָה (שם ד'):\",1,0],[2,133,3,46,\"ואת פדויי השלשה וגו'. וְאֶת הַבְּכוֹרוֹת הַצְּרִיכִין לְהִפָּדוֹת בָּהֶם, אֵלּוּ שְׁלֹשָׁה וְשִׁבְעִים וּמָאתַיִם הָעֹדְפִים בָּהֶם יְתֵרִים עַל הַלְוִיִּם, מֵהֶם תִּקַּח חמשת שקלים לגלגלת; כָּךְ הָיְתָה מְכִירָתוֹ שֶׁל יוֹסֵף, עֶשְׂרִים כֶּסֶף, שֶׁהָיָה בְּכוֹרָהּ שֶׁל רָחֵל (ב\\\"ר פ\\\"ד):\",1,0],[2,133,3,49,\"העדפים על פדויי הלוים. עַל אוֹתָן שֶׁפָּדוּ הַלְוִיִּם בְּגוּפָן:\",1,0],[2,133,3,50,\"חמשה וששים ושלש מאות ואלף. כָּךְ סְכוּם הַחֶשְׁבּוֹן: חֲמֵשֶׁת שְׁקָלִים לַגֻּלְגֹּלֶת — לְמָאתַיִם בְּכוֹרוֹת אֶלֶף שֶׁקֶל, לְשִׁבְעִים בְּכוֹרוֹת שְׁלֹשׁ מֵאוֹת וַחֲמִשִּׁים שֶׁקֶל, וְשָׁלֹשׁ בְּכוֹרוֹת חֲמִשָּׁה עָשָׂר שֶׁקֶל; אָמַר, כֵּיצַד אֶעֱשֶׂה? בְּכוֹר שֶׁאֹמַר לוֹ תֵּן חֲמֵשֶׁת שְׁקָלִים, יֹאמַר לִי \\\"אֲנִי מִפְּדוּיֵי הַלְוִיִּם\\\". מֶה עָשָׂה? הֵבִיא שְׁנַיִם וְעֶשְׂרִים אֶלֶף פְּתָקִין וְכָתַב עֲלֵיהֶם \\\"בֶּן לֵוִי\\\" וּמָאתַיִם וְשִׁבְעִים וּשְׁלֹשָׁה פְּתָקִין כָּתַב עֲלֵיהֶן \\\"חֲמֵשֶׁת שְׁקָלִים\\\", בְּלָלָן וּנְתָנָן בַּקַּלְפִּי, אָמַר לָהֶם, בּוֹאוּ וּטְלוּ פִתְקֵיכֶם לְפִי הַגּוֹרָל (סנהדרין י\\\"ז):\",1,0],[2,133,4,2,\"נשא את ראש וגו'. מְנֵה מֵהֶם אֶת הָרְאוּיִין לַעֲבוֹדַת מַשָּׂא, וְהֵם מִבֶּן שְׁלֹשִׁים וְעַד בֶּן חֲמִשִּׁים שָׁנָה, וְהַפָּחוּת מִשְּׁלֹשִׁים לֹא נִתְמַלֵּא כֹחוֹ, מִכָּאן אָמְרוּ (אבות פ\\\"ה) \\\"בֶּן שְׁלֹשִׁים לַכֹּחַ\\\", וְהַיּוֹתֵר עַל בֶּן חֲמִשִּׁים כֹּחוֹ מַכְחִישׁ מֵעַתָּה:\",1,0],[2,133,4,4,\"קדש הקדשים. הַמְקֻדָּשׁ שֶׁבְּכֻלָּן – הָאָרוֹן וְהַשֻּׁלְחָן וְהַמְּנוֹרָה וְהַמִּזְבְּחוֹת וְהַפָּרֹכֶת וּכְלֵי שָׁרֵת:\",1,0],[2,133,4,5,\"ובא אהרן ובניו וגו'. יַכְנִיסוּ כָל כְּלִי וּכְלִי לְנַרְתֵּקוֹ הַמְפֹרָשׁ לוֹ בְּפָרָשָׁה זוֹ, וְלֹא יִצְטָרְכוּ הַלְוִיִּם בְּנֵי קְהָת אֶלָּא לָשֵׂאת:\",1,0],[2,133,4,5,\"בנסע המחנה. כְּשֶׁהֶעָנָן מִסְתַּלֵּק, הֵן יוֹדְעִין שֶׁיִּסְּעוּ:\",2,0],[2,133,4,7,\"קערת וכפת וקשות ומנקית. כְּבָר פֵּרַשְׁתִּי בִּמְלֶאכֶת הַמִּשְׁכָּן:\",1,0],[2,133,4,7,\"הנסך. הַכִּסּוּי, לְשׁוֹן מָסָךְ, כְּדִכְתִיב \\\"אֲשֶׁר יֻסַּךְ בָּהֵן\\\" (שמות כ\\\"ה):\",2,0],[2,133,4,9,\"מלקחיה. כְּמִין צְבַת שֶׁמּוֹשֵׁךְ בָּהּ אֶת הַפְּתִילָה לְכָל צַד שֶׁיִּרְצֶה:\",1,0],[2,133,4,9,\"מחתתיה. כְּמִין כַּף קְטַנָּה, וְשׁוּלֶיהָ פְשׁוּטִין וְלֹא סְגַלְגַּלִּים, וְאֵין לָהּ מְחִצָּה לְפָנֶיהָ אֶלָּא מִצִּדֶּיהָ, וְחוֹתֶה בָהּ אֶת דֶּשֶׁן הַנֵּרוֹת כְּשֶׁמְּטִיבָן:\",2,0],[2,133,4,9,\"נרתיה. לוצי\\\"ש בְּלַעַז, שֶׁנּוֹתְנִים בָּהֶן הַשֶּׁמֶן וְהַפְּתִילוֹת:\",3,0],[2,133,4,10,\"אל מכסה עור תחש. כְּמִין מַרְצוּף:\",1,0],[2,133,4,12,\"את כל כלי השרת אשר ישרתו בם בקדש. בְּתוֹךְ הַמִּשְׁכָּן שֶׁהוּא קֹדֶשׁ, וְהֵן כְּלֵי הַקְּטֹרֶת שֶׁמְּשָׁרְתִין בָּהֶם בְּמִּזְבֵּחַ הַפְּנִימִי:\",1,0],[2,133,4,13,\"ודשנו את המזבח. מִזְבַּח הַנְּחֹשֶׁת:\",1,0],[2,133,4,13,\"ודשנו. יִטְּלוּ אֶת הַדֶּשֶׁן מֵעָלָיו:\",2,0],[2,133,4,13,\"ופרשו עליו בגד ארגמן. וְאֵשׁ שֶׁיָּרְדָה מִן הַשָּׁמַיִם רְבוּצָה תַּחַת הַבֶּגֶד כַּאֲרִי בִּשְׁעַת הַמַּסָּעוֹת, וְאֵינָהּ שׂוֹרַפְתּוֹ, שֶׁהָיוּ כוֹפִין עָלֶיהָ פְּסַכְתֵּר שֶׁל נְחֹשֶׁת (יומא כ\\\"א):\",3,0],[2,133,4,14,\"מחתת. שֶׁבָּהֶם חוֹתִין גֶּחָלִים לִתְרוּמַת הַדֶּשֶׁן, הָעֲשׂוּיָה כְּמִין מַחֲבַת שֶׁאֵין לָהּ אֶלָּא שָׁלֹשׁ מְחִצּוֹת, וּמִלְּפָנֶיהָ שׁוֹאֶבֶת אֶת הַגְּחָלִים:\",1,0],[2,133,4,14,\"מזלגת. צִנּוֹרִיּוֹת שֶׁל נְחֹשֶׁת שֶׁבָּהֶן מַכִּין בָּאֵבָרִים שֶׁעַל הַמִּזְבֵּחַ לְהָפְכָן, כְּדֵי שֶׁיִּתְעַכְּלוּ יָפֶה וּמַהֵר:\",2,0],[2,133,4,14,\"יעים. הֵם מַגְרֵפוֹת, וּבְלַעַז וודי\\\"ל, וְהֵן שֶׁל נְחֹשֶׁת, וּבָהֶן מְכַבְּדִין אֶת הַדֶּשֶׁן מֵעַל הַמִּזְבֵּחַ:\",3,0],[2,133,4,15,\"לכסת את הקדש. הָאָרוֹן וְהַמִּזְבֵּחַ:\",1,0],[2,133,4,15,\"ואת כל כלי הקדש. הַמְּנוֹרָה וּכְלֵי שָׁרֵת:\",2,0],[2,133,4,15,\"ומתו. שֶׁאִם יִגְּעוּ — חַיָּבִין מִיתָה בִידֵי שָׁמַיִם:\",3,0],[2,133,4,16,\"ופקדת אלעזר. שֶׁהוּא מְמֻנֶּה עֲלֵיהֶם לָשֵֹאת אוֹתָם, שֶׁמֶן וּקְטֹרֶת וְשֶׁמֶן הַמִּשְׁחָה, ומנחת התמיד — עָלָיו מֻטָּל לְצַוּוֹת וּלְזָרֵז וּלְהַקְרִיב בְּעֵת חֲנִיָּתָן (תלמוד ירושלמי שבת פ\\\"י):\",1,0],[2,133,4,16,\"פקדת כל המשכן. וְעוֹד הָיָה מְמֻנֶּה עַל מַשָּׂא בְנֵי קְהָת, לְצַוּוֹת אִישׁ עַל עֲבוֹדָתוֹ וְעַל מַשָּׂאוֹ, וְהוּא המשכן וכל אשר בו, כָּל הַסְּדוּרִים לְמַעְלָה בְּפָרָשָׁה זוֹ, אֲבָל מַשָּׂא בְנֵי גֵרְשׁוֹן וּמְרָרִי שֶׁאֵינָהּ מִקֹּדֶשׁ הַקֳּדָשִׁים עַ\\\"פִּ אִיתָמָר הָיָה, כְּמוֹ שֶׁכָּתוּב בְּפָרָשַׁת נָשֹׂא:\",2,0],[2,133,4,18,\"אל תכריתו. אַל תִּגְרְמוּ לָהֶם שֶׁיָּמוּתוּ:\",1,0],[2,133,4,20,\"ולא יבאו לראות כבלע את הקדש. לְתוֹךְ נַרְתֵּק שֶׁלּוֹ, כְּמוֹ שֶׁפֵּרַשְׁתִּי לְמַעְלָה בְּפָרָשָׁה זוֹ, וּפָרְשׂוּ עָלָיו בֶּגֶד פְּלוֹנִי וְכִסּוּ אוֹתוֹ בְּמִכְסֶה פְּלוֹנִי, וּבִלּוּעַ שֶׁלּוֹ הוּא כִסּוּיוֹ:\",1,0],[2,133,4,22,\"נשא את ראש בני גרשון גם הם. כְּמוֹ שֶׁצִּוִּיתִיךָ עַל בְּנֵי קְהָת, לִרְאוֹת כַּמָּה יֵשׁ שֶׁהִגִּיעוּ לִכְלַל עֲבוֹדָה:\",1,0],[2,133,4,25,\"את יריעת המשכן. עֶשֶׂר תַּחְתּוֹנוֹת:\",1,0],[2,133,4,25,\"ואת אהל מועד. יְרִיעֹת עִזִּים הָעֲשׂוּיוֹת לְאֹהֶל עָלָיו:\",2,0],[2,133,4,25,\"מכסהו. עוֹרוֹת אֵילִים מְאָדָּמִים:\",3,0],[2,133,4,25,\"מסך פתח. וִילוֹן הַמִּזְרָחִי:\",4,0],[2,133,4,26,\"אשר על המשכן. כְּלוֹמַר הַקְּלָעִים וְהַמָּסָךְ שֶׁל חָצֵר, הַסּוֹכְכִים וּמְגִנִּים עַל הַמִּשְׁכָּן וְעַל מִזְבַּח הַנְּחֹשֶׁת סָבִיב:\",1,0],[2,133,4,26,\"ואת כל אשר יעשה להם. כְּתַרְגּוּמוֹ \\\"וְיָת כָּל דִּי יִתְּמְסַר לְהוֹן\\\" — לִבְנֵי גֵּרְשׁוֹן:\",2,0],[2,133,4,27,\"על פי אהרון ובניו. וְאֵיזֶה מֵהַבָּנִים מְמֻנֶּה עֲלֵיהֶם? ביד איתמר בן אהרון הכהן:\",1,0],[2,133,4,32,\"ויתדתם ומיתריהם. שֶׁל עַמּוּדִים; שֶׁהֲרֵי יִתְדוֹת וּמֵיתְרֵי הַקְּלָעִים בְּמַשָּׂא בְנֵי גֵרְשׁוֹן הָיוּ, וִיתֵדוֹת וּמֵיתָרִים הָיוּ לַיְרִיעוֹת וְלַקְּלָעִים מִלְּמַטָּה, שֶׁלֹּא תַגְבִּיהֵם הָרוּחַ, וִיתֵדוֹת וּמֵיתָרִים הָיוּ לָעַמּוּדִים סָבִיב לִתְלוֹת בָּהֶם הַקְּלָעִים בִּשְׂפָתָם הָעֶלְיוֹנָה בִּכְלוּנְסוֹת וְקוּנְדָּסִין, כְּמוֹ שֶׁשְּׁנוּיָה בִמְלֶאכֶת הַמִּשְׁכָּן:\",1,0],[2,133,4,47,\"עבדת עבדה. הִיא הַשִּׁיר בִּמְצִלְתַּיִם וְכִנּוֹרוֹת, שֶׁהִיא עֲבוֹדָה לַעֲבוֹדָה אַחֶרֶת (ערכין י\\\"א):\",1,0],[2,133,4,47,\"ועבדת משא. כְּמַשְׁמָעוֹ:\",2,0],[2,133,4,49,\"ופקדיו אשר צוה ה' את משה. וְאוֹתָן הַפְּקוּדִים הָיוּ בְמִּצְוָה מִבֶּן שְׁלֹשִׁים שָׁנָה וְעַד בֶּן חֲמִשִּׁים:\",1,0],[2,133,5,2,\"צו את בני ישראל וגו'. פָּרָשָׁה זוֹ נֶאֶמְרָה בַּיּוֹם שֶׁהוּקַם הַמִּשְׁכָּן, וּשְׁמוֹנֶה פָרָשִׁיּוֹת נֶאֶמְרוּ בוֹ בַיּוֹם, כִּדְאִיתָא בְּמַסֶּכֶת גִּטִּין בְּפֶרֶק הַנִּזָּקִין (גיטין דף ס'):\",1,0],[2,133,5,2,\"וישלחו מן המחנה. שָׁלֹשׁ מַחֲנוֹת הָיוּ שָׁם בִּשְׁעַת חֲנִיָּתָן, תּוֹךְ הַקְּלָעִים הִיא מַחֲנֵה שְׁכִינָה, חֲנִיַּת הַלְוִיִּם סָבִיב כְּמוֹ שֶׁמְּפֹרָשׁ בְּפָרָשַׁת בְּמִדְבַּר סִינַי, הִיא מַחֲנֵה לְוִיָּה, וּמִשָּׁם וְעַד סוֹף מַחֲנֵה הַדְּגָלִים לְכָל אַרְבַּע הָרוּחוֹת הִיא מַחֲנֵה יִשְׂרָאֵל; הַצָּרוּעַ נִשְׁתַּלַּח חוּץ לְכֻלָּן, הַזָּב מֻתָּר בְּמַחֲנֵה יִשְׂרָאֵל וּמְשֻׁלָּח מִן הַשְּׁתַיִם, וְטָמֵא לָנֶפֶשׁ מֻתָּר אַף בְּשֶׁל לְוִיָּה, וְאֵינוֹ מְשֻׁלָּח אֶלָּא מִשֶּׁל שְׁכִינָה, וְכָל זֶה דָּרְשׁוּ רַבּוֹתֵינוּ מִן הַמִּקְרָאוֹת בְּמַסֶּ' פְּסָחִים (דף ס\\\"ז):\",2,0],[2,133,5,2,\"טמא לנפש. \\\"דִּמְסָאָב לִטְמֵי נַפְשָׁא דֶאֱנָשָׁא\\\", אוֹמֵר אֲנִי שֶׁהוּא לְשׁוֹן עַצְמוֹת אָדָם בִּלְשׁוֹן אֲרַמִּי. וְהַרְבֵּה יֵשׁ בִּבְ\\\"רַ, \\\"אַדְרִיאָנוּס שְׁחִיק טַמְיָא\\\", שְׁחִיק עֲצָמוֹת:\",3,0],[2,133,5,6,\"למעל מעל בה'. הֲרֵי חָזַר וְכָתַב כָּאן פָּרָשַׁת גּוֹזֵל וְנִשְׁבָּע עַל שֶׁקֶר, הִיא הָאֲמוּרָה בְפָרָשַׁת וַיִּקְרָא \\\"וּמָעֲלָה מַעַל בַּה' וְכִחֵשׁ בַּעֲמִיתוֹ וְגוֹ'\\\", וְנִשְׁנֵית כָּאן בִּשְׁבִיל שְׁנֵי דְבָרִים שֶׁנִּתְחַדְּשׁוּ בָהּ, הָאֶחָד שֶׁכָּתַב \\\"וְהִתְוַדּוּ\\\", לִמֵּד שֶׁאֵינוֹ חַיָּב חֹמֶשׁ וְאָשָׁם עַ\\\"פִּ עֵדִים עַד שֶׁיּוֹדֶה בַדָּבָר, וְהַשֵּׁנִי עַל גֶּזֶל הַגֵּר שֶׁהוּא נָתוּן לַכֹּהֲנִים (עי' ספרי):\",1,0],[2,133,5,7,\"את אשמו בראשו. הוּא הַקֶּרֶן שֶׁנִּשְׁבָּע עָלָיו (ב\\\"ק ק\\\"י):\",1,0],[2,133,5,7,\"לאשר אשם לו. לְמִי שֶׁנִּתְחַיֵּב לוֹ (כתובות י\\\"ט):\",2,0],[2,133,5,8,\"ואם אין לאיש גאל. שֶׁמֵּת הַתּוֹבֵעַ שֶׁהִשְׁבִּיעוֹ וְאֵין לוֹ יוֹרְשִׁים:\",1,0],[2,133,5,8,\"להשיב האשם אליו. כְּשֶׁנִּמְלַךְ זֶה לְהִתְוַדּוֹת עַל עֲוֹנוֹ; וְאָמְרוּ רַבּוֹתֵינוּ וְכִי יֵשׁ לְךָ אָדָם בְּיִשְׂרָאֵל שֶׁאֵין לוֹ גּוֹאֲלִים, אוֹ בֵן, אוֹ אָח, אוֹ שְׁאֵר בָּשָׂר הַקָּרוֹב מִמִּשְׁפַּחַת אָבִיו לְמַעְלָה עַד יַעֲקֹב? אֶלָּא זֶה הַגֵּר שֶׁמֵּת וְאֵין לוֹ יוֹרְשִׁים (סנהדרין ס\\\"ח):\",2,0],[2,133,5,8,\"האשם המושב. זֶה הַקֶּרֶן וְהַחֹמֶשׁ (בבא קמא ק\\\"י):\",3,0],[2,133,5,8,\"לה' לכהן. קְנָאוֹ הַשֵּׁם וּנְתָנוֹ לַכֹּהֵן שֶׁבְּאוֹתוֹ מִשְׁמָר (ספרי):\",4,0],[2,133,5,8,\"מלבד איל הכפרים. הָאָמוּר בְּוַיִּקְרָא שֶׁהוּא צָרִיךְ לְהָבִיא:\",5,0],[2,133,5,9,\"וכל תרומה וגו'. אָמַר רַ' יִשְׁמָעֵאל וְכִי תְרוּמָה מַקְרִיבִין לַכֹּהֵן? וַהֲלֹא הוּא הַמְחַזֵּר אַחֲרֶיהָ לְבֵית הַגְּרָנוֹת, וּמַה תַּ\\\"ל אֲשֶׁר יַקְרִיבוּ לַכֹּהֵן? אֵלּוּ הַבִּכּוּרִים, שֶׁנֶּאֱמַר בָּהֶם (שמות כ\\\"ג), \\\"תָּבִיא בֵּית ה' אֱלֹהֶיךָ\\\", וְאֵינִי יוֹדֵעַ מַה יֵּעָשֶׂה בָהֶם, תַּ\\\"ל \\\"לַכֹּהֵן לוֹ יִהְיֶה\\\", בָּא הַכָּתוּב וְלִמֵּד עַל הַבִּכּוּרִים שֶׁיִּהְיוּ נִתָּנִין לַכֹּהֵן (ספרי):\",1,0],[2,133,5,10,\"ואיש את קדשיו לו יהיו. לְפִי שֶׁנֶּאֶמְרוּ מַתְּנוֹת כְּהֻנָּה וּלְוִיָּה, יָכוֹל יָבוֹאוּ וְיִטְּלוּם בִּזְרוֹעַ, תַּ\\\"ל \\\"וְאִישׁ אֶת קֳדָשָׁיו לוֹ יִהְיוּ\\\", מַגִּיד שֶׁטּוֹבַת הֲנָאָתָן לַבְּעָלִים, וְעוֹד מִדְרָשִׁים הַרְבֵּה דָרְשׁוּ בוֹ בְּסִפְרֵי; וּמִ\\\"אַ וְאִישׁ אֶת קֳדָשָׁיו לוֹ יִהְיוּ, מִי שֶׁמְּעַכֵּב מַעַשְׂרוֹתָיו וְאֵינוֹ נוֹתְנָן, לוֹ יִהְיוּ הַמַּעַשְׂרוֹת — סוֹף שֶׁאֵין שָׂדֵהוּ עוֹשֶׂה אֶלָּא אֶחָד מֵעֲשָׂרָה שֶׁהָיְתָה לְמוּדָה לַעֲשׂוֹת (תנחומא ראה):\",1,0],[2,133,5,10,\"איש אשר יתן לכהן. מַתָּנוֹת הָרְאוּיוֹת לוֹ:\",2,0],[2,133,5,10,\"לו יהיה. מָמוֹן הַרְבֵּה (ברכות סג.):\",3,0],[2,133,5,12,\"איש איש כי תשטה אשתו. מַה כָּתוּב לְמַעְלָה מִן הָעִנְיָן? \\\"וְאִישׁ אֶת קֳדָשָׁיו לוֹ יִהְיוּ\\\", אִם אַתָּה מְעַכֵּב מַתְּנוֹת הַכֹּהֵן, חַיֶּיךָ שֶׁתִּצְטָרֵךְ לָבֹא אֶצְלוֹ לְהָבִיא לוֹ אֶת הַסּוֹטָה:\",1,0],[2,133,5,12,\"איש איש. לְלַמֶּדְךָ שֶׁמּוֹעֶלֶת בִּשְׁתַּיִם – בְּאִישׁ מִלְחָמָה שֶׁלְּמַעְלָה, וְאִישָׁהּ מִלְּמַטָּה:\",2,0],[2,133,5,12,\"כי תשטה אשתו. שָׁנוּ רַבּוֹתֵינוּ אֵין הַמְנָאֲפִין נוֹאֲפִין עַד שֶׁתִּכָּנֵס בָּהֶן רוּחַ שְׁטוּת, דִּכְתִיב \\\"כִּי תִשְׂטֶה\\\" וְכָתוּב בּוֹ \\\"נֹאֵף אִשָּׁה חֲסַר לֵב\\\" (משלי ו'); וּפְשׁוּטוֹ שֶׁל מִקְרָא: כי תשטה — תֵּט מִדַּרְכֵי צְנִיעוּת וְתֵחָשֵׁד בְּעֵינָיו, כְּמוֹ \\\"שְׂטֵה מֵעָלָיו וַעֲבֹר\\\" (שם ד'), \\\"אַל יֵשְׂטְ אֶל דְּרָכֶיהָ לִבֶּךָ\\\" (שם ז'):\",3,0],[2,133,5,12,\"ומעלה בו מעל. וּמַהוּ הַמַּעַל? ושכב איש אתה:\",4,0],[2,133,5,13,\"ושכב איש. פְּרָט לְקָטָן וּמִי שֶׁאֵינוֹ אִישׁ (ספרי):\",1,0],[2,133,5,13,\"אתה שכבת זרע. שְׁכִיבָתָהּ פּוֹסֶלֶת אוֹתָהּ, וְאֵין שְׁכִיבַת אֲחוֹתָהּ פּוֹסֶלֶת אוֹתָהּ (כְּמַעֲשֶׂה בִשְׁתֵּי אֲחָיוֹת שֶׁהָיוּ דּוֹמוֹת זוֹ לָזוֹ):\",2,0],[2,133,5,13,\"ונעלם מעיני אישה. פְּרָט לְסוּמָא, הָא אִם הָיָה רוֹאֶה וּמְעַמְעֵם אֵין הַמַּיִם בּוֹדְקִין אוֹתָהּ (ספרי):\",3,0],[2,133,5,13,\"ונסתרה. שִׁעוּר שֶׁתֵּרָאֶה לְטֻמְאַת בִּיאָה:\",4,0],[2,133,5,13,\"ועד אין בה. הָא אִם יֵשׁ בָּהּ אֲפִלּוּ עֵד אֶחָד שֶׁאָמַר נִטְמֵאת לֹא הָיְתָה שׁוֹתָה (סוטה ד'):\",5,0],[2,133,5,13,\"ועד אין בה. בְּטֻמְאָה, אֲבָל יֵשׁ עֵדִים לִסְתִירָה (שם ב'):\",6,0],[2,133,5,13,\"נתפשה. נֶאֶנְסָה, כְּמוֹ \\\"וּתְפָשָׂהּ וְשָׁכַב עִמָּהּ\\\" (דברים כ\\\"ב):\",7,0],[2,133,5,14,\"ועבר עליו. קֹדֶם לַסְּתִירָה:\",1,0],[2,133,5,14,\"רוח קנאה וקנה. פֵּרְשׁוּ רַבּוֹתֵינוּ לְשׁוֹן הַתְרָאָה, שֶׁמַּתְרֶה בָהּ, אַל תִּסָּתְרִי עִם אִישׁ פְּלוֹנִי:\",2,0],[2,133,5,14,\"והוא נטמאה או עבר עליו וגו'. כְּלוֹמַר הוּא הִתְרָה בָּהּ, וְעָבְרָה עַל הַתְרָאָתוֹ, וְאֵין יָדוּעַ אִם נִטְמְאָה אִם לָאו:\",3,0],[2,133,5,15,\"קמח. שֶׁלֹּא יְהֵא מִסֹּלֶת:\",1,0],[2,133,5,15,\"שערים. וְלֹא חִטִּים, הִיא עָשְׂתָה מַעֲשֵׂה בְהֵמָה וְקָרְבָּנָהּ מַאֲכַל בְּהֵמָה (סוטה י\\\"ד):\",2,0],[2,133,5,15,\"לא יצק עליו שמן. שֶׁלֹּא יְהֵא קָרְבָּנָהּ מְהֻדָּר, שֶׁהַשֶּׁמֶן קָרוּי אוֹר, וְהִיא עָשְׂתָה בַחֹשֶׁךְ:\",3,0],[2,133,5,15,\"ולא יתן עליו לבנה. שֶׁהָאִמָּהוֹת נִקְרְאוּ לְבוֹנָה, שֶׁנֶּאֱמַר \\\"וְאֶל גִּבְעַת הַלְּבוֹנָה\\\" (שה\\\"ש ד'), וְהִיא פֵרְשָׁה מִדַּרְכֵיהֶן:\",4,0],[2,133,5,15,\"כי מנחת קנאת הוא. הַקֶּמַח הַזֶּה, קֶמַח לָשׁוֹן זָכָר:\",5,0],[2,133,5,15,\"מנחת קנאת. מְעוֹרֶרֶת עָלֶיהָ שְׁתֵּי קְנָאוֹת, קִנְאַת הַמָּקוֹם וְקִנְאַת הַבַּעַל (ספרי):\",6,0],[2,133,5,17,\"מים קדשים. שֶׁקָּדְשׁוּ בַכִּיּוֹר, לְפִי שֶׁנַּעֲשָׂה מִנְּחֹשֶׁת מַרְאוֹת הַצּוֹבְאוֹת, וְזוֹ פֵרְשָׁה מִדַּרְכֵיהֶן, שֶׁהָיוּ נִבְעָלוֹת לְבַעְלֵיהֶן בְּמִצְרַיִם תַּחַת הַתַּפּוּחַ וְזוֹ קִלְקְלָה לְאַחֵר, תִּבָּדֵק בּוֹ:\",1,0],[2,133,5,17,\"בכלי חרש. הִיא הִשְׁקָת אֶת הַנּוֹאֵף יַיִן מְשֻׁבָּח בְּכוֹסוֹת מְשֻׁבָּחִים, לְפִיכָךְ תִּשְׁתֶּה מַיִם הַמָּרִים בִּמְקִדָּה בְזוּיָה שֶׁל חֶרֶס (סוטה ט'):\",2,0],[2,133,5,18,\"והעמיד הכהן וגו'. וַהֲלֹא כְבָר נֶאֱמַר \\\"וְהֶעֱמִדָהּ לִפְנֵי ה'\\\"? אֶלָּא מַסִּיעִין הָיוּ אוֹתָהּ מִמָּקוֹם לְמָקוֹם כְּדֵי לְיַגְּעָהּ וְתִטָּרֵף דַּעְתָּהּ וְתוֹדֶה (סוטה ח'):\",1,0],[2,133,5,18,\"ופרע. סוֹתֵר אֶת קְלִיעַת שְׂעָרָהּ, כְּדֵי לְבַזּוֹתָהּ, מִכָּאן לִבְנוֹת יִשְׂרָאֵל שֶׁגִּלּוּי הָרֹאשׁ גְּנַאי לָהֶן (כתובות ע\\\"ב):\",2,0],[2,133,5,18,\"לפני ה'. בְּשַׁעַר נִקָּנוֹר, הוּא שַׁעַר הָעֲזָרָה הַמִּזְרָחִי, דֶּרֶךְ כָּל הַנִּכְנָסִים (סוטה ז'):\",3,0],[2,133,5,18,\"ונתן על כפיה. לְיַגְּעָהּ, אוּלַי תִּטָּרֵף דַּעְתָּהּ וְתוֹדֶה, וְלֹא יִמָּחֶה שֵׁם הַמְיֻחָד עַל הַמָּיִם (שם י\\\"ד):\",4,0],[2,133,5,18,\"המרים. עַל שֵׁם סוֹפָן, שֶׁהֵם מָרִים לָהּ (שם כ'):\",5,0],[2,133,5,18,\"המאררים. הַמְחַסְּרִים אוֹתָהּ מִן הָעוֹלָם, לְשׁוֹן \\\"סִלּוֹן מַמְאִיר\\\" (יחזקאל כ\\\"ח), וְלֹא יִתָּכֵן לְפָרֵשׁ מַיִם אֲרוּרִים, שֶׁהֲרֵי קְדוֹשִׁים הֵן, וְלֹא אֲרוּרִים כָּתַב הַכָּתוּב, אֶלָּא מְאָרְרִים אֶת אֲחֵרִים, וְאַף אֻנְקְלוֹס לֹא תִרְגֵּם \\\"לִיטַיָּא\\\" אֶלָּא \\\"מְלַטְטַיָּא\\\" — שֶׁמַּרְאוֹת קְלָלָה בְּגוּפָהּ שֶׁל זוֹ:\",6,0],[2,133,5,19,\"והשביע אתה וגו'. וּמַה הִיא הַשְּׁבוּעָה? אִם לֹא שָׁכַב הִנָּקִי, הָא אִם שָׁכַב, חִנָּקִי, שֶׁמִּכְּלַל לָאו אַתָּה שׁוֹמֵעַ הֵן, אֶלָּא שֶׁמִּצְוָה לִפְתֹּחַ בְּדִינֵי נְפָשׁוֹת תְּחִלָּה לִזְכוּת (שם י\\\"ז; שבועות ל\\\"ו; סנהדרין ל\\\"ג):\",1,0],[2,133,5,20,\"ואת כי שטית. כִּי מְשַׁמֵּשׁ בִּלְשׁוֹן אִם:\",1,0],[2,133,5,21,\"בשבעת האלה. שְׁבוּעָה שֶׁל קְלָלָה:\",1,0],[2,133,5,21,\"יתן ה' אותך לאלה. שֶׁיִּהְיוּ הַכֹּל מְקַלְלִין בִּיךְ — \\\"יְבוֹאֵךְ כְּדֶרֶךְ שֶׁבָּא לִפְלוֹנִית\\\":\",2,0],[2,133,5,21,\"ולשבעה. שֶׁיִּהְיוּ הַכֹּל נִשְׁבָּעִין בִּיךְ —\\\"אִם לֹא יֶאֱרַע לִי כְּדֶרֶךְ שֶׁאֵרַע לִפְלוֹנִית\\\", וְכֵן הוּא אוֹמֵר \\\"וְהִנַּחְתֶּם שִׁמְכֶם לִשְׁבוּעָה לִבְחִירַי\\\" (ישעיהו ס\\\"ה), שֶׁהַצַּדִּיקִים נִשְׁבָּעִים בְּפֻרְעֲנוּתָן שֶׁל רְשָׁעִים, וְכֵן לְעִנְיַן הַבְּרָכָה, \\\"וְנִבְרְכוּ וְגוֹ'\\\" (בראשית י\\\"ב), \\\"בְּךָ יְבָרֵךְ יִשְׂרָאֵל לֵאמֹר\\\" (שם מ\\\"ח):\",3,0],[2,133,5,21,\"את ירכך. בִּקְלָלָה הִקְדִּים יָרֵךְ לַבֶּטֶן, לְפִי שֶׁבָּהּ הִתְחִילָה בַעֲבֵרָה תְּחִלָּה (סוטה ח'):\",4,0],[2,133,5,21,\"צבה. כְּתַרְגּוּמוֹ, נְפוּחָה:\",5,0],[2,133,5,22,\"לצבות בטן. כְּמוֹ לְהַצְבּוֹת בֶּטֶן, זֶהוּ שִׁמּוּשׁ פַּתָּח שֶׁהַלָּמֶ\\\"ד נְקוּדָה בוֹ. וְכֵן \\\"לַנְחֹתָם הַדֶּרֶךְ\\\" (שמות י\\\"ג), \\\"לַרְאֹתְכֶם בַּדֶּרֶךְ אֲשֶׁר תֵּלְכוּ בָהּ\\\" (דברים א'), וְכֵן \\\"לַנְפִּל יָרֵךְ\\\" — לְהַנְפִּיל יָרֵךְ, שֶׁהַמַּיִם מַצְבִּים אֶת הַבֶּטֶן וּמַפִּילִים אֶת הַיָּרֵךְ:\",1,0],[2,133,5,22,\"לצבות בטן ולנפל ירך. בִּטְנוֹ וִירֵכוֹ שֶׁל בּוֹעֵל, אוֹ אֵינוֹ אֶלָּא נִבְעֶלֶת, כְּשֶׁהוּא אוֹמֵר \\\"אֶת יְרֵכֵךְ נֹפֶלֶת וְאֶת בִּטְנֵךְ צָבָה\\\" הֲרֵי שֶׁל נִבְעֶלֶת אָמוּר (סוטה כ\\\"ח):\",2,0],[2,133,5,22,\"אמן אמן. קַבָּלַת שְׁבוּעָה – אָמֵן עַל הָאָלָה אָמֵן עַל הַשְּׁבוּעָה, אָמֵן אִם מֵאִישׁ זֶה אָמֵן אִם מֵאִישׁ אַחֵר, אָמֵן שֶׁלֹּא סָטִיתִי אֲרוּסָה וּנְשׂוּאָה שׁוֹמֶרֶת יָבָם וּכְנוּסָה (שם י\\\"ח):\",3,0],[2,133,5,24,\"והשקה את האשה. אֵין זֶה סֵדֶר הַמַּעֲשֶׂה, שֶׁהֲרֵי בַתְּחִלָּהּ מַקְרִיב מִנְחָתָהּ, אֶלָּא הַכָּתוּב מְבַשֶּׂרְךָ שֶׁכְּשֶׁיַּשְׁקֶנָּה יָבֹאוּ בָהּ לְמָרִים; לְפִי שֶׁנֶּאֱמַר בֶּטֶן וְיָרֵךְ, מִנַּיִן לִשְׁאָר כָּל הַגּוּף? תַּ\\\"ל ובאו בה — בְּכֻלָּהּ, אִ\\\"כַּ מַה תַּ\\\"ל בֶּטֶן וְיָרֵךְ? לְפִי שֶׁהֵן הִתְחִילוּ בַעֲבֵרָה תְּחִלָּה לְפִיכָךְ הִתְחִיל מֵהֶם הַפֻּרְעָנוּת (ספרי):\",1,0],[2,133,5,24,\"למרים. לִהְיוֹת לָהּ רָעִים וּמָרִים:\",2,0],[2,133,5,25,\"והניף. מוֹלִיךְ וּמֵבִיא מַעֲלֶה וּמוֹרִיד, וְאַף הִיא מְנִיפָה עִמּוֹ, שֶׁיָּדָהּ לְמַעְלָה מִיָּדוֹ שֶׁל כֹּהֵן:\",1,0],[2,133,5,25,\"והקריב אתה. זוֹ הִיא הַגָּשָׁתָהּ בְּקֶרֶן דְּרוֹמִית מַעֲרָבִית שֶׁל מִזְבֵּחַ קֹדֶם קְמִיצָה, כִּשְׁאָר מְנָחוֹת (סוטה י\\\"ד):\",2,0],[2,133,5,26,\"אזכרתה. הוּא הַקֹּמֶץ, שֶׁעַ\\\"יְ הַקְטָרָתוֹ הַמִּנְחָה בָאָה לְזִכָּרוֹן לְגָבוֹהַּ (ספרי):\",1,0],[2,133,5,27,\"והשקה את המים. לְרַבּוֹת, שֶׁאִם אָמְרָה אֵינִי שׁוֹתָה לְאַחַר שֶׁנִּמְחֲקָה מְגִלָּה, מְעַרְעֲרִין אוֹתָהּ וּמַשְׁקִין אוֹתָהּ בְּעַל כָּרְחָהּ, אֶלָּא אִ\\\"כֵּ אָמְרָה טְמֵאָה אֲנִי (ספרי; סוטה כ'):\",1,0],[2,133,5,27,\"וצבתה בטנה וגו'. אַעַ\\\"פִּ שֶׁבַּקְּלָלָה הִזְכִּיר יָרֵךְ תְּחִלָּה, הַמַּיִם אֵין בּוֹדְקִין אֶלָּא כְּדֶרֶךְ כְּנִיסָתָן בָּהּ (שם ט'):\",2,0],[2,133,5,27,\"והיתה האשה לאלה. כְּמוֹ שֶׁפֵּרַשְׁתִּי, שֶׁיְּהֵא הַכֹּל אָלִין בָּהּ:\",3,0],[2,133,5,27,\"בקרב עמה. הֶפְרֵשׁ יֵשׁ בֵּין אָדָם הַמִּתְנַוֵּל בְּמָקוֹם שֶׁנִּכָּר, לְאָדָם הַמִּתְנַוֵּל בְּמָקוֹם שֶׁאֵינוֹ נִכָּר:\",4,0],[2,133,5,28,\"ואם לא נטמא האשה. בִּסְתִירָה זוֹ:\",1,0],[2,133,5,28,\"וטהרה הוא. מִמָּקוֹם אַחֵר:\",2,0],[2,133,5,28,\"ונקתה. מִמַּיִם הַמְאָרְרִים, וְלֹא עוֹד אֶלָּא ונזרעה זרע — אִם הָיְתָה יוֹלֶדֶת בְּצַעַר תֵּלֵד בְּרֶוַח, אִם הָיְתָה יוֹלֶדֶת שְׁחֹרִים, מֵעַתָּה יוֹלֶדֶת לְבָנִים:\",3,0],[2,133,5,30,\"או איש. כְּמוֹ \\\"אוֹ נוֹדַע\\\" (שמות כ\\\"א), כְּלוֹמַר אִם אִישׁ קַנַּאי הוּא, לְכָךְ והעמיד את האשה.\",1,0],[2,133,5,31,\"ונקה האיש מעון. אִם בְּדָקוּהָ הַמַּיִם, אַל יִדְאַג לוֹמַר \\\"חַבְתִּי בְמִיתָתָהּ\\\", נָקִי הוּא מִן הָעֹנֶשׁ; דָּ\\\"אַ: מִשֶּׁיַּשְׁקֶנָּה תְּהֵא אֶצְלוֹ בְּהֶתֵּר, וְנִקָּה מֵעָוֹן, שֶׁהַסּוֹטָה אֲסוּרָה לְבַעְלָהּ (ספרי):\",1,0],[2,133,6,2,\"כי יפלא. יַפְרִישׁ; לָמָּה נִסְמְכָה פָרָשַׁת נָזִיר לְפָרָשַׁת סוֹטָה? לוֹמַר לְךָ שֶׁכָּל הָרוֹאֶה סוֹטָה בְקִלְקוּלָהּ יַזִּיר עַצְמוֹ מִן הַיַּיִן, שֶׁהוּא מֵבִיא לִידֵי נִאוּף (סוטה ב'):\",1,0],[2,133,6,2,\"נדר נזיר. אֵין נְזִירָה בְכָל מָקוֹם אֶלָּא פְּרִישָׁה, אַף כָּאן שֶׁפֵּרֵשׁ מִן הַיַּיִן:\",2,0],[2,133,6,2,\"להזיר לה'. לְהַבְדִּיל עַצְמוֹ מִן הַיַּיִן לְשֵׁם שָׁמַיִם:\",3,0],[2,133,6,3,\"מיין ושכר. כְּתַרְגּוּמוֹ \\\"מֵחֲמַר חֲדַת וְעַתִּיק\\\", שֶׁהַיַּיִן מְשַׁכֵּר כְּשֶׁהוּא יָשָׁן:\",1,0],[2,133,6,3,\"וכל משרת. לְשׁוֹן צְבִיעָה בְּמַיִם וְכָל מַשְׁקֶה; וּבִלְשׁוֹן מִשְׁנָה יֵשׁ הַרְבֵּה, אֵין שׁוֹרִין דְּיוֹ וְסַמָּנִים (שבת י\\\"ז), נָזִיר שֶׁשָּׁרָה פִתּוֹ (נזיר ל\\\"ד):\",2,0],[2,133,6,4,\"חרצנים. הֵם הַגַּרְעִינִין:\",1,0],[2,133,6,4,\"זג. הֵם קְלִפוֹת שֶׁמִּבַּחוּץ, שֶׁהַחַרְצַנִּים בְּתוֹכָן כְּעִנְבָּל בְּזוּג:\",2,0],[2,133,6,5,\"קדש יהיה. הַשֵּׂעָר שֶׁלּוֹ, לְגַדֵּל הַפֶּרַע שֶׁל שְׂעַר רֹאשׁוֹ (ספרי; תענית י\\\"א):\",1,0],[2,133,6,5,\"פרע. נָקוּד פַּתָּח קָטָן אַף שֶׁהוּא דָּבוּק לִשְׂעַר רֹאשׁוֹ — פֶּרַע שֶׁל שֵׂעָר, וּפֵרוּשׁ שֶׁל פֶּרַע, גִּדּוּל שֶׁל שֵׂעָר, וְכֵן \\\"אֶת רֹאשׁוֹ לֹא יִפְרָע\\\" (ויקרא כ\\\"א), וְאֵין קָרוּי פֶּרַע פָּחוֹת מִשְּׁלֹשִׁים יוֹם (ספרי; סנהדרין כ\\\"ב):\",2,0],[2,133,6,8,\"כל ימי נזרו קדש הוא. זוֹ קְדֻשַּׁת הַגּוּף, מִלִּטַּמֵּא לְמֵתִים (ספרי):\",1,0],[2,133,6,9,\"בפתע. זֶה אֹנֶס:\",1,0],[2,133,6,9,\"פתאום. זֶה שׁוֹגֵג, וְיֵ\\\"א פֶּתַע פִּתְאֹם דָּבָר אֶחָד הוּא – מִקְרֶה שֶׁל פִּתְאוֹם:\",2,0],[2,133,6,9,\"וכי ימות מת עליו. בָּאֹהֶל שֶׁהוּא בוֹ:\",3,0],[2,133,6,9,\"ביום טהרתו. בְּיוֹם הַזָּאָתוֹ, אוֹ אֵינוֹ אֶלָּא בַשְּׁמִינִי שֶׁהוּא טָהוֹר לְגַמְרֵי, תַּ\\\"ל \\\"בַּיּוֹם הַשְּׁבִיעִי\\\", אִי שְׁבִיעִי יָכוֹל אֲפִלּוּ לֹא הִזָּה, תַּ\\\"ל \\\"בְּיוֹם טָהֳרָתוֹ\\\" (ספרי):\",4,0],[2,133,6,10,\"וביום השמיני יבא שתי תרים. לְהוֹצִיא אֶת הַשְּׁבִיעִי, אוֹ אֵינוֹ אֶלָּא לְהוֹצִיא אֶת הַתְּשִׁיעִי ? קָבַע זְמַן לַקְּרֵבִין וְקָבַע זְמַן לַמַּקְרִיבִין, מַה קְּרֵבִין הִכְשִׁיר שְׁמִינִי וּמִשְּׁמִינִי וָהָלְאָה, אַף מַקְרִיבִין שְׁמִינִי וּמִשְּׁמִינִי וָהָלְאָה (שם):\",1,0],[2,133,6,11,\"מאשר חטא על הנפש. שֶׁלֹּא נִזְהַר מִטֻּמְאַת הַמֵּת, רַבִּי אֶלְעָזָר הַקַּפָּר אוֹמֵר, שֶׁצִּעֵר עַצְמוֹ מִן הַיַּיִן (ספרי; נזיר י\\\"ט):\",1,0],[2,133,6,11,\"וקדש את ראשו. לַחֲזֹר וּלְהַתְחִיל מִנְיַן נְזִירוּתוֹ:\",2,0],[2,133,6,12,\"והזיר לה' את ימי נזרו. יַחֲזֹר וְיִמְנֶה נְזִירוּתוֹ כְּבַתְּחִלָּה:\",1,0],[2,133,6,12,\"והימים הראשנים יפלו. לֹא יַעֲלוּ מִן הַמִּנְיָן:\",2,0],[2,133,6,13,\"יביא אתו. יָבִיא אֶת עַצְמוֹ, וְזֶה אֶחָד מִשְּׁלֹשָׁה אֶתִים שֶׁהָיָה רַבִּי יִשְׁמָעֵאל דּוֹרֵשׁ כֵּן, כַּיּוֹצֵא בוֹ \\\"וְהִשִּׂיאוּ אוֹתָם עֲוֹן אַשְׁמָה\\\" (ויקרא כ\\\"ב) — אֶת עַצְמָם, כַּיּוֹצֵא בוֹ \\\"וַיִּקְבֹּר אֹתוֹ בַגַּי\\\" (דברים ל\\\"ד) — הוּא קָבַר אֶת עַצְמוֹ:\",1,0],[2,133,6,15,\"ומנחתם ונסכיהם. שֶׁל עוֹלָה וּשְׁלָמִים; לְפִי שֶׁהָיוּ בִכְלָל, וְיָצְאוּ לִדּוֹן בְּדָבָר חָדָשׁ — שֶׁיִּטָּעֲנוּ לֶחֶם — הֶחֱזִירָן לִכְלָלָן, שֶׁיִּטָּעֲנוּ נְסָכִים כְּדִין עוֹלָה וּשְׁלָמִים (ספרי):\",1,0],[2,133,6,15,\"חלות מצות ורקיקי מצות. עֶשֶׂר מִכָּל מִין:\",2,0],[2,133,6,17,\"זבח שלמים לה' על סל המצות. יִשְׁחַט אֶת הַשְּׁלָמִים עַל מְנָת לְקַדֵּשׁ אֶת הַלֶּחֶם (עי' מנחות מ\\\"ו):\",1,0],[2,133,6,17,\"את מנחתו ואת נסכו. שֶׁל אַיִל:\",2,0],[2,133,6,18,\"וגלח הנזיר פתח אוהל מועד. יָכוֹל יְגַלֵּחַ בָּעֲזָרָה, הֲרֵי זֶה דֶּרֶךְ בִּזָּיוֹן, אֶלָּא וְגִלַּח הַנָּזִיר לְאַחַר שְׁחִיטַת הַשְּׁלָמִים שֶׁכָּתוּב בָּהֶן \\\"וּשְׁחָטוֹ פֶּתַח אֹהֶל מוֹעֵד\\\":\",1,0],[2,133,6,18,\"אשר תחת זבח השלמים. תַּחַת הַדּוּד שֶׁהוּא מְבַשְּׁלָן בּוֹ, לְפִי שֶׁשַּׁלְמֵי נָזִיר הָיוּ מִתְבַּשְּׁלִין בָּעֲזָרָה, שֶׁצָּרִיךְ לִטֹּל הַכֹּהֵן הַזְּרוֹעַ אַחַר שֶׁנִּתְבַּשְּׁלָה וּלְהָנִיף לִפְנֵי ה' (עי' נזיר מ\\\"ה):\",2,0],[2,133,6,19,\"הזרע בשלה. לְאַחַר שֶׁנִּתְבַּשְּׁלָה (חולין פ\\\"ח):\",1,0],[2,133,6,20,\"קדש הוא לכהן. הַחַלָּה וְהָרָקִיק וְהַזְּרוֹעַ תְּרוּמָה הֵן לַכֹּהֵן:\",1,0],[2,133,6,20,\"על חזה התנופה. מִלְּבַד חָזֶה וְשׁוֹק הָרְאוּיִים לוֹ מִכָּל שְׁלָמִים מוּסָף עַל שַׁלְמֵי נָזִיר הַזְּרוֹעַ הַזֶּה, לְפִי שֶׁהָיוּ שַׁלְמֵי נָזִיר בִּכְלָל, וְיָצְאוּ לִדּוֹן בַּדָּבָר הֶחָדָשׁ — לְהַפְרָשַׁת זְרוֹעַ — הֻצְרַךְ לְהַחֲזִירָן לִכְלָלָן לִדּוֹן אַף בְּחָזֶה וְשׁוֹק (ספרי):\",2,0],[2,133,6,21,\"מלבד אשר תשיג ידו. שֶׁאִם אָמַר הֲרֵינִי נָזִיר עַל מְנָת לְגַלֵּחַ עַל מֵאָה עוֹלוֹת וְעַל מֵאָה שְׁלָמִים, כְּפִי נִדְרוֹ אֲשֶׁר יִדֹּר כֵּן יַעֲשֶֹה — מוּסָף עַל תּוֹרַת נִזְרוֹ: עַל תּוֹרַת הַנָּזִיר, מוּסָף וְלֹא יֶחְסַר, שֶׁאִם אָמַר הֲרֵינִי נָזִיר חָמֵשׁ נְזִירוֹת עַל מְנָת לְגַלֵּחַ עַל שָׁלֹשׁ בְּהֵמוֹת הַלָּלוּ, אֵין אֲנִי קוֹרֵא בוֹ \\\"כַּאֲשֶׁר יִדֹּר כֵּן יַעֲשֶֹה\\\" (שם):\",1,0],[2,133,6,23,\"אמור. כְּמוֹ זָכוֹר, שָׁמוֹר, בְּלַעַז דישנ\\\"ט:\",1,0],[2,133,6,23,\"אמור להם. שֶׁיִּהְיוּ כֻלָּם שׁוֹמְעִים (שם):\",2,0],[2,133,6,23,\"אמור. מָלֵא — לֹא תְבָרְכֵם בְּחִפָּזוֹן וּבַהֲלוּת, אֶלָּא בְכַוָּנָה וּבְלֵב שָׁלֵם (תנחומא):\",3,0],[2,133,6,24,\"יברכך. שֶׁיִּתְבָּרְכוּ נְכָסֶיךָ:\",1,0],[2,133,6,24,\"וישמרך. שֶׁלֹּא יָבֹאוּ עָלֶיךָ שׁוֹדְדִים לִטֹּל מָמוֹנְךָ; שֶׁהַנּוֹתֵן מַתָּנָה לְעַבְדּוֹ אֵינוֹ יָכוֹל לְשָׁמְרוֹ מִכָּל אָדָם, וְכֵיוָן שֶׁבָּאִים לִסְטִים עָלָיו וְנוֹטְלִין אוֹתָהּ מִמֶּנּוּ, מַה הֲנָאָה יֵשׁ לוֹ בְּמַתָּנָה זוֹ? אֲבָל הַקָּבָּ\\\"ה, הוּא הַנּוֹתֵן, הוּא הַשּׁוֹמֵר; וְהַרְבֵּה מִדְרָשִׁים דָּרְשׁוּ בוֹ בְּסִפְרֵי:\",2,0],[2,133,6,25,\"יאר השם פניו אליך. יַרְאֶה לְךָ פָּנִים שׂוֹחֲקוֹת, פָּנִים צְהֻבּוֹת:\",1,0],[2,133,6,25,\"ויחנך. יִתֵּן לְךָ חֵן (תנחומא):\",2,0],[2,133,6,26,\"ישא ה' פניו אליך. יִכְבֹּשׁ כַּעֲסוֹ:\",1,0],[2,133,6,27,\"ושמו את שמי. יְבָרְכוּם בַּשֵּׁם הַמְפֹרָשׁ (ספרי):\",1,0],[2,133,6,27,\"ואני אברכם. לְיִשְׂרָאֵל, וְאַסְכִּים עִם הַכֹּהֲנִים; דָּ\\\"אַ, וַאֲנִי אֲבָרְכֵם — לַכֹּהֲנִים (חולין מ\\\"ט):\",2,0],[2,133,7,1,\"ויהי ביום כלות משה. כלת כְּתִיב — יוֹם הֲקָמַת הַמִּשְׁכָּן הָיוּ יִשְׂרָאֵל כְּכַלָּה הַנִּכְנֶסֶת לַחֻפָּה (פסיקתא; תנחומא):\",1,0],[2,133,7,1,\"כלות משה. בְּצַלְאֵל וְאָהֳלִיאָב וְכָל חֲכַם לֵב עָשׂוּ אֶת הַמִּשְׁכָּן, וּתְלָאוֹ הַכָּתוּב בְּמֹשֶׁה, לְפִי שֶׁמָּסַר נַפְשׁוֹ עָלָיו, לִרְאוֹת תַּבְנִית כָּל דָּבָר וְדָבָר כְּמוֹ שֶׁהֶרְאָהוּ בָהָר, לְהוֹרוֹת לְעוֹשֵׂי הַמְּלָאכָה, וְלֹא טָעָה בְּתַבְנִית אַחַת; וְכֵן מָצִינוּ בְּדָוִד, לְפִי שֶׁמָּסַר נַפְשׁוֹ עַל בִּנְיַן בֵּית הַמִּקְדָּשׁ, שֶׁנֶּאֱמַר \\\"זְכוֹר ה' לְדָוִד אֵת כָּל עֻנּוֹתוֹ אֲשֶׁר נִשְׁבַּע לַה'\\\" וְגוֹ' (תהילים קל\\\"ב), לְפִיכָךְ נִקְרָא עַל שְׁמוֹ, שֶׁנֶּאֱמַר (מ\\\"א י\\\"ב) \\\"רְאֵה בֵיתְךָ דָּוִד\\\" (תנחומא):\",2,0],[2,133,7,1,\"כלות משה להקים. וְלֹא נֶאֱמַר בְּיוֹם הָקִים, מְלַמֵּד שֶׁכָּל שִׁבְעַת יְמֵי הַמִּלּוּאִים הָיָה מֹשֶׁה מַעֲמִידוֹ וּמְפָרְקוֹ, וּבְאוֹתוֹ הַיּוֹם הֶעֱמִידוֹ וְלֹא פֵּרְקוֹ, לְכָךְ נֶאֱמַר \\\"כַּלּוֹת מֹשֶׁה לְהָקִים\\\" — אוֹתוֹ הַיּוֹם כָּלוּ הֲקָמוֹתָיו, וְרֹאשׁ חֹדֶשׁ נִיסָן הָיָה, בַּשֵּׁנִי נִשְׂרְפָה הַפָּרָה, בַּשְּׁלִישִׁי הִזּוּ הַזָּיָה רִאשׁוֹנָה, וּבַשְּׁבִיעִי גִּלְּחוּ (ספרי):\",3,0],[2,133,7,2,\"הם נשיאי המטת. שֶׁהָיוּ שׁוֹטְרִים עֲלֵיהֶם בְּמִצְרַיִם וְהָיוּ מֻכִּים עֲלֵיהֶם, שֶׁנֶּאֱמַר (שמות ה') וַיֻּכּוּ שֹׁטְרֵי בְּנֵי יִשְׂרָאֵל וְגוֹ' (ספרי):\",1,0],[2,133,7,2,\"הם העמדים על הפקדים. שֶׁעָמְדוּ עִם מֹשֶׁה וְאַהֲרֹן כְּשֶׁמָּנוּ אֶת יִשְֹרָאֵל, שֶׁנֶּאֱמַר \\\"וְאִתְּכֶם יִהְיוּ וְגוֹ'\\\" (במדבר א'):\",2,0],[2,133,7,3,\"שש עגלת צב. אֵין צָב אֶלָּא מְחֻפִּים, וְכֵן \\\"וּבַצַּבִּים וּבַפְּרָדִים\\\" (ישעיה ס\\\"ו); עֲגָלוֹת מְכֻסּוֹת קְרוּיוֹת צַבִּים:\",1,0],[2,133,7,3,\"ויקריבו אותם לפני המשכן. שֶׁלֹּא קִבֵּל מֹשֶׁה מִיָּדָם עַד שֶׁנֶּאֱמַר לוֹ מִפִּי הַמָּקוֹם; אָמַר רַבִּי נָתָן מָה רָאוּ הַנְּשִׂיאִים לְהִתְנַדֵּב כָּאן בַּתְּחִלָּה, וּבִמְלֶאכֶת הַמִּשְׁכָּן לֹא הִתְנַדְּבוּ תְּחִלָּה? אֶלָּא כָּךְ אָמְרוּ הַנְּשִׂיאִים, יִתְנַדְּבוּ צִבּוּר מַה שֶּׁיִּתְנַדְּבוּ, וּמַה שֶּׁמְּחַסְּרִין, אָנוּ מַשְׁלִימִין, כֵּיוָן שֶׁרָאוּ שֶׁהִשְׁלִימוּ צִבּוּר אֶת הַכֹּל, שֶׁנֶּאֱמַר \\\"וְהַמְּלָאכָה הָיְתָה דַיָּם\\\" (שמות ל\\\"ו), אָמְרוּ מֵעַתָּה מַה לָּנוּ לַעֲשׂוֹת? הֵבִיאוּ אַבְנֵי הַשֹּׁהַם וְהַמִּלּוּאִים לָאֵפוֹד וְלַחֹשֶׁן, לְכָךְ הִתְנַדְּבוּ כָּאן תְּחִלָּה (ספרי):\",2,0],[2,133,7,7,\"כפי עבדתם. שֶׁהָיָה מַשָּׂא בְנֵי גֵרְשׁוֹן קַל מִשֶּׁל מְרָרִי, שֶׁהָיוּ נוֹשְׂאִים הַקְּרָשִׁים וְהָעַמּוּדִים וְהָאֲדָנִים:\",1,0],[2,133,7,9,\"כי עבדת הקדש עלהם. מַשָּׂא דְּבַר הַקְּדֻשָּׁה — הָאָרוֹן וְהַשֻּׁלְחָן וְגוֹ', לְפִיכָךְ בַּכָּתֵף יִשָּׂאוּ:\",1,0],[2,133,7,10,\"ויקריבו הנשאים את חנכת המזבח. לְאַחַר שֶׁהִתְנַדְּבוּ הָעֲגָלוֹת וְהַבָּקָר לָשֵׂאת הַמִּשְׁכָּן, נְשָׂאָם לִבָּם לְהִתְנַדֵּב קָרְבְּנוֹת הַמִּזְבֵּחַ לְחַנְּכוֹ:\",1,0],[2,133,7,10,\"ויקריבו הנשיאם את קרבנם לפני המזבח. כִּי לֹא קִבֵּל מֹשֶׁה מִיָּדָם עַד שֶׁנֶּאֱמַר לוֹ מִפִּי הַגְּבוּרָה (ספרי):\",2,0],[2,133,7,11,\"יקריבו את קרבנם לחנכת המזבח. וַעֲדַיִן לֹא הָיָה יוֹדֵעַ מֹשֶׁה הֵיאַךְ יַקְרִיבוּ, אִם כְּסֵדֶר תּוֹלְדוֹתָם, אִם כְּסֵדֶר הַמַּסָּעוֹת, עַד שֶׁנֶּאֱמַר לוֹ מִפִּי הַקָּבָּ\\\"ה יַקְרִיבוּ לַמַּסָּעוֹת, אִישׁ יוֹמוֹ (שם):\",1,0],[2,133,7,12,\"ביום הראשון. אוֹתוֹ הַיּוֹם נָטַל עֶשֶׂר עֲטָרוֹת, רִאשׁוֹן לְמַעֲשֵׂה בְרֵאשִׁית, רִאשׁוֹן לַנְּשִׂיאִים וְכוּ', כִּדְאִיתָא בְסֵדֶר עוֹלָם:\",1,0],[2,133,7,12,\"למטה יהודה. יִחֲסוֹ הַכָּתוּב עַל שִׁבְטוֹ, וְלֹא שֶׁגָּבָה מִשִּׁבְטוֹ וְהִקְרִיב, אוֹ אֵינוֹ אוֹמֵר \\\"לְמַטֵּה יְהוּדָה\\\" אֶלָּא שֶׁגָּבָה מִשִּׁבְטוֹ וְהֵבִיא, תַּ\\\"ל \\\"זֶה קָרְבַּן נַחְשׁוֹן\\\" — מִשֶּׁלּוֹ הֵבִיא (שם):\",2,0],[2,133,7,13,\"שניהם מלאים סלת. לְמִנְחַת נְדָבָה:\",1,0],[2,133,7,14,\"עשרה זהב. כְּתַרְגּוּמוֹ, מִשְׁקַל עֶשֶׂר שִׁקְלֵי הַקֹּדֶשׁ הָיָה בָהּ:\",1,0],[2,133,7,14,\"מלאה קטרת. לֹא מָצִינוּ קְטֹרֶת לְיָחִיד וְלֹא עַל מִזְבֵּחַ הַחִיצוֹן אֶלָּא זוֹ בִּלְבַד, וְהוֹרָאַת שָׁעָה הָיְתָה (מנחות נ'):\",2,0],[2,133,7,15,\"פר אחד. מְיֻחָד שֶׁבְּעֶדְרוֹ (עי' ספרי):\",1,0],[2,133,7,16,\"שעיר עזים אחד לחטאת. לְכַפֵּר עַל קֶבֶר הַתְּהוֹם — טֻמְאַת סָפֵק (עי' ספרי):\",1,0],[2,133,7,18,\"הקריב נתנאל בן צוער … הקרב את קרבנו. מַה תַּ\\\"ל \\\"הִקְרִיב\\\" בְּשִׁבְטוֹ שֶׁל יִשָּׂשכָר מַה שֶּׁלֹּא נֶאֱמַר בְּכָל הַשְּׁבָטִים? לְפִי שֶׁבָּא רְאוּבֵן וְעִרְעֵר וְאָמַר: אַחַר שֶׁקְּדָמַנִי יְהוּדָה, אַקְרִיב אֲנִי אַחֲרָיו, אָמַר לוֹ מֹשֶׁה מִפִּי הַגְּבוּרָה נֶאֱמַר לִי שֶׁיַּקְרִיבוּ כְּסֵדֶר מַסָּעוֹת — לְדִגְלֵיהֶם, לְכָךְ אָמַר הִקְרִב אֶת קָרְבָּנוֹ, וְהוּא חָסֵר יוֹ\\\"ד, שֶׁהוּא מַשְׁמַע הַקְרֵב, לְשׁוֹן צִוּוּי, שֶׁמִּפִּי הַגְּבוּרָה נִצְטַוָּה \\\"הַקְרֵב\\\". וּמַהוּ הִקְרִיב הִקְרִיב שְׁנֵי פְעָמִים? שֶׁבִּשְׁבִיל שְׁנֵי דְבָרִים זָכָה לְהַקְרִיב שֵׁנִי לַשְּׁבָטִים, אַחַת שֶׁהָיוּ יוֹדְעִים בַּתּוֹרָה, שֶׁנֶּאֱמַר \\\"וּמִבְּנֵי יִשָּׂשכָר יוֹדְעֵי בִינָה לַעִתִּים\\\" (דבהי\\\"א י\\\"ב), וְאַחַת שֶׁהֵם נָתְנוּ עֵצָה לַנְּשִׂיאִים לְהִתְנַדֵּב קָרְבָּנוֹת הַלָּלוּ. וּבִיסוֹדוֹ שֶׁל רַבִּי מֹשֶׁה הַדַּרְשָׁן מָצָאתִי, אָמַר רַבִּי פִּנְחָס בֶּן יָאִיר נְתַנְאֵל בֶּן צוּעָר הִשִּׂיאָן עֵצָה זוֹ:\",1,0],[2,133,7,19,\"קערת כסף. מִנְיַן אוֹתִיוֹתָיו בְּגִימַטְרִיָּא תתק\\\"ל, כְּנֶגֶד שְׁנוֹתָיו שֶׁל אָדָם הָרִאשׁוֹן:\",1,0],[2,133,7,19,\"שלשים ומאה משקלה. עַל שֵׁם שֶׁכְּשֶׁהֶעֱמִיד תּוֹלָדוֹת לְקִיּוּם הָעוֹלָם בֶּן ק\\\"ל שָנָה הָיָה, שֶׁנֶּאֱמַר \\\"וַיְחִי אָדָם שְׁלֹשִׁים וּמְאַת שָׁנָה וַיּוֹלֶד\\\" וְגוֹ' (בראשית ה'):\",2,0],[2,133,7,19,\"מזרק אחד כסף. בְּגִימַטְרִיָּא תק\\\"ך, עַל שֵׁם נֹחַ שֶׁהֶעֱמִיד תּוֹלָדוֹת בֶּן ת\\\"ק שָׁנָה, וְעַל שֵׁם עֶשְֹרִים שָׁנָה שֶׁנִּגְזְרָה גְּזֵרַת הַמַּבּוּל קֹדֶם תּוֹלְדוֹתָיו — כְּמוֹ שֶׁפֵּרַשְׁתִּי אֵצֶל \\\"וְהָיוּ יָמָיו מֵאָה וְעֶשְׂרִים שָׁנָה\\\" (שם ו') — לְפִיכָךְ נֶאֱמַר — מִזְרָק אֶחָד כֶּסֶף, וְלֹא נֶאֱמַר מִזְרָק כֶּסֶף אֶחָד כְּמוֹ שֶׁנֶּאֱמַר בַּקְּעָרָה, לוֹמַר שֶׁאַף אוֹתִיּוֹת שֶׁל אֶחָד מִצְטָרְפוֹת לַמִּנְיָן:\",3,0],[2,133,7,19,\"שבעים שקל. כְּנֶגֶד שִׁבְעִים אֻמּוֹת שֶׁיָּצְאוּ מִבָּנָיו:\",4,0],[2,133,7,20,\"כף אחת. כְּנֶגֶד הַתּוֹרָה שֶׁנִּתְּנָה מִיָּדוֹ שֶׁל הַקָּבָּ\\\"ה:\",1,0],[2,133,7,20,\"עשרה זהב. כְּנֶגֶד עֲשֶׂרֶת הַדִּבְּרוֹת:\",2,0],[2,133,7,20,\"מלאה קטרת. גִּימַטְרִיָּא שֶׁל קְטֹרֶת תרי\\\"ג מִצְוֹת, וּבִלְבַד שֶׁתַּחֲלִיף קוֹ\\\"ף בְּדָלֶ\\\"ת עַ\\\"יְ א\\\"ת ב\\\"ש ג\\\"ר ד\\\"ק:\",3,0],[2,133,7,21,\"פר אחד. כְּנֶגֶד אַבְרָהָם, שֶׁנֶּאֱמַר בּוֹ \\\"וַיִּקַּח בֶּן בָּקָר\\\" (שם י\\\"ח):\",1,0],[2,133,7,21,\"איל אחד. כְּנֶגֶד יִצְחָק, \\\"וַיִּקַּח אֶת הָאַיִל\\\" וְגוֹ' (שם כ\\\"ב):\",2,0],[2,133,7,21,\"כבש אחד. כְּנֶגֶד יַעֲקֹב, \\\"וְהַכְּשָׂבִים הִפְרִיד יַעֲקֹב\\\" (שם ל'):\",3,0],[2,133,7,22,\"שעיר עיזים. לְכַפֵּר עַל מְכִירַת יוֹסֵף שֶׁנֶּאֱמַר בּוֹ \\\"וַיִּשְׁחֲטוּ שְׂעִיר עִזִּים\\\" (שם ל\\\"ז):\",1,0],[2,133,7,23,\"ולזבח השלמים בקר שנים. כְּנֶגֶד מֹשֶׁה וְאַהֲרֹן שֶׁנָּתְנוּ שָׁלוֹם בֵּין יִשְׂרָאֵל לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם:\",1,0],[2,133,7,23,\"אלים כבשים ועתדים. שְׁלֹשָׁה מִינִים כְּנֶגֶד כֹּהֲנִים וּלְוִיִּם וְיִשְׂרְאֵלִים, וּכְנֶגֶד תּוֹרָה נְבִיאִים וּכְתוּבִים, שָׁלֹשׁ חֲמִשִּׁיּוֹת כְּנֶגֶד חֲמִשָּׁה חֻמְשִׁין וַחֲמֵשֶׁת הַדִּבְּרוֹת הַכְּתוּבִין עַל לוּחַ אֶחָד וַחֲמִשָּׁה הַכְּתוּבִים עַל הַשֵּׁנִי; עַד כָּאן בִּיסוֹדוֹ שֶׁל רַבִּי מֹשֶׁה הַדַּרְשָׁן:\",2,0],[2,133,7,24,\"ביום השלישי נשיא וגו'. בַּיּוֹם הַשְּׁלִישִׁי הָיָה הַנָּשִׂיא הַמַּקְרִיב זְבוּלֻן, וְכֵן כֻּלָּם, אֲבָל בִּנְתַנְאֵל שֶׁנֶּאֱמַר בּוֹ הִקְרִיב נְתַנְאֵל, נוֹפֵל אַחֲרָיו הַלָּשׁוֹן לוֹמַר נְשִׂיא יִשָּׂשכָר, לְפִי שֶׁכְּבָר הִזְכִּיר שְׁמוֹ וְהַקְרָבָתוֹ, וּבַשְּׁאָר שֶׁלֹּא נֶאֱמַר בָּהֶן הִקְרִיב, נוֹפֵל עֲלֵיהֶן לָשׁוֹן זֶה — נָשִׂיא לִבְנֵי פְלוֹנִי — אוֹתוֹ הַיּוֹם הָיָה הַנָּשִׂיא הַמַּקְרִיב לְשֵׁבֶט פְּלוֹנִי:\",1,0],[2,133,7,84,\"ביום המשח אתו. בּוֹ בַיּוֹם שֶׁנִּמְשַׁח הִקְרִיב, וּמָה אֲנִי מְקַיֵּם \\\"אַחֲרֵי הִמָּשַׁח\\\" (פסוק פ\\\"ח)? שֶׁנִּמְשַׁח תְּחִלָּה וְאַ\\\"כַּ הִקְרִיב, אוֹ אַחֲרֵי הִמָּשַׁח — לְאַחַר זְמַן וְלֹא בָא לְלַמֵּד בְּיוֹם הִמָּשַׁח אֶלָּא לוֹמַר שֶׁנִּמְשַׁח בַּיּוֹם? כְּשֶׁהוּא אוֹמֵר (ויקרא ז') \\\"בְּיוֹם מָשְׁחוֹ אֹתָם\\\", לָמַדְנוּ שֶׁנִּמְשַׁח בַּיּוֹם, וּמַתַּ\\\"ל \\\"בְּיוֹם הִמָּשַׁח אֹתוֹ\\\" ? בַּיּוֹם שֶׁנִּמְשַׁח הִקְרִיב (ספרי):\",1,0],[2,133,7,84,\"קערת כסף שתים עשרה. הֵם הֵם שֶׁהִתְנַדְּבוּ, וְלֹא אֵרַע בָּהֶם פְּסוּל (שם):\",2,0],[2,133,7,85,\"שלשים ומאה הקערה האחת וגו'. מַה תַּ\\\"ל? לְפִי שֶׁנֶּאֱמַר \\\"שְׁלֹשִׁים וּמֵאָה\\\" וְלֹא פֵּרֵשׁ בְּאֵיזוֹ שֶׁקֶל, לְכָךְ חָזַר וּשְׁנָאָהּ כָּאן, וְכָלַל בְּכֻלָּן — כל כסף הכלים, בשקל הקדש:\",1,0],[2,133,7,85,\"כל כסף הכלים וגו'. לִמֶּדְךָ שֶׁהָיוּ כְלֵי הַמִּקְדָּשׁ מְכֻוָּנִים בְּמִשְׁקָלָן — שׁוֹקְלָן אֶחָד אֶחָד, וְשׁוֹקְלָן כֻּלָּן כְּאֶחָד — לֹא רִבָּה וְלֹא מִעֵט (שם):\",2,0],[2,133,7,86,\"כפות זהב שתים עשרה. לָמָּה נֶאֱמַר? לְפִי שֶׁנֶּאֱמַר כַּף אַחַת עֲשָׂרָה זָהָב, הִיא שֶׁל זָהָב וּמִשְׁקָלָהּ עֲשָׂרָה שְׁקָלִים שֶׁל כֶּסֶף, אוֹ אֵינוֹ אֶלָּא כַּף אַחַת שֶׁל כֶּסֶף וּמִשְׁקָלָהּ עֲשָׂרָה שִׁקְלֵי זָהָב — וְשִׁקְלֵי זָהָב אֵין מִשְׁקָלָם שָׁוֶה לְשֶׁל כֶּסֶף — תַּ\\\"ל \\\"כַּפּוֹת זָהָב\\\" — שֶׁל זָהָב הָיוּ (שם):\",1,0],[2,133,7,89,\"ובבא משה. שְׁנֵי כְתוּבִים הַמַּכְחִישִׁים זֶה אֶת זֶה, שְׁלִישִׁי בָא וְהִכְרִיעַ בֵּינֵיהֶם, כָּתוּב אֶחָד אוֹמֵר \\\"וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד\\\" (ויקרא א') — וְהוּא חוּץ לַפָּרֹכֶת — וְכָתוּב אֶחָד אוֹמֵר \\\"וְדִבַּרְתִּי אִתְּךָ מֵעַל הַכַּפֹּרֶת\\\" (שמות כ\\\"ה), בָּא זֶה וְהִכְרִיעַ בֵּינֵיהֶם: מֹשֶׁה בָא אֶל אֹהֶל מוֹעֵד, וְשָׁם שׁוֹמֵעַ אֶת הַקּוֹל הַבָּא מֵעַל הַכַּפֹּרֶת מִבֵּין שְׁנֵי הַכְּרוּבִים — הַקּוֹל יוֹצֵא מִן הַשָּׁמַיִם לְבֵין שְׁנֵי הַכְּרוּבִים, וּמִשָּׁם יָצָא לְאֹהֶל מוֹעֵד (ספרי):\",1,0],[2,133,7,89,\"וישמע את הקול. יָכוֹל קוֹל נָמוּךְ, תַּ\\\"ל \\\"אֶת הַקּוֹל\\\", הוּא הַקּוֹל שֶׁנִּדְבַּר עִמּוֹ בְּסִינַי, וּכְשֶׁמַּגִּיעַ לַפֶּתַח הָיָה נִפְסָק וְלֹא הָיָה יוֹצֵא חוּץ לָאֹהֶל:\",2,0],[2,133,7,89,\"מדבר. כְּמוֹ מִתְדַּבֵּר, כְּבוֹדוֹ שֶׁל מַעְלָה לוֹמַר כֵּן, מְדַּבֵּר בֵּינוֹ לְבֵין עַצְמוֹ, וּמֹשֶׁה שׁוֹמֵעַ מֵאֵלָיו:\",3,0],[2,133,7,89,\"וידבר אליו. לְמַעֵט אֶת אַהֲרֹן מִן הַדִּבְּרוֹת (עי' ספרי):\",4,0],[2,133,8,2,\"בהעלתך. לָמָּה נִסְמְכָה פָרָשַׁת הַמְּנוֹרָה לְפָרָשַׁת הַנְּשִׂיאִים? לְפִי שֶׁכְּשָׁרָאָה אַהֲרֹן חֲנֻכַּת הַנְּשִׂיאִים חָלְשָׁה אָז דַּעְתּוֹ, שֶׁלֹּא הָיָה עִמָּהֶם בַּחֲנֻכָּה לֹא הוּא וְלֹא שִׁבְטוֹ, אָמַר לוֹ הַקָּבָּ\\\"ה חַיֶּיךָ שֶׁלְּךָ גְדוֹלָה מִשֶּׁלָּהֶם, שֶׁאַתָּה מַדְלִיק וּמֵטִיב אֶת הַנֵּרוֹת (עי' תנחומא):\",1,0],[2,133,8,2,\"בהעלתך. עַל שֵׁם שֶׁהַלַּהַב עוֹלֶה, כָּתוּב בְּהַדְלָקָתָן לְשׁוֹן עֲלִיָּה, שֶׁצָּרִיךְ לְהַדְלִיק עַד שֶׁתְּהֵא שַׁלְהֶבֶת עוֹלָה מֵאֵלֶיהָ (שבת כ\\\"א), וְעוֹד דָּרְשׁוּ רַבּוֹתֵינוּ מִכָּאן שֶׁמַּעֲלָה הָיְתָה לִפְנֵי הַמְּנוֹרָה, שֶׁעָלֶיהָ הַכֹּהֵן עוֹמֵד וּמֵטִיב (ספרי):\",2,0],[2,133,8,2,\"אל מול פני המנורה. אֶל מוּל נֵר הָאֶמְצָעִי, שֶׁאֵינוֹ בַקָּנִים אֶלָּא בְּגוּף שֶׁל מְנוֹרָה (עי' מנחות צ\\\"ח):\",3,0],[2,133,8,2,\"יאירו שבעת הנרות. שִׁשָּׁה שֶׁעַל שֵׁשֶׁת הַקָּנִים, שְׁלֹשָׁה הַמִּזְרָחִיִּים פּוֹנִים לְמוּל הָאֶמְצָעִי — הַפְּתִילוֹת שֶׁבָּהֶן — וְכֵן שְׁלֹשָׁה הַמַּעֲרָבִיִּים רָאשֵׁי הַפְּתִילוֹת לְמוּל הָאֶמְצָעִי, וְלָמָּה? כְּדֵי שֶׁלֹּא יֹאמְרוּ, לְאוֹרָהּ הוּא צָרִיךְ (עי' תנחומא):\",4,0],[2,133,8,3,\"ויעש כן אהרן. לְהַגִּיד שִׁבְחוֹ שֶׁל אַהֲרֹן שֶׁלֹּא שִׁנָּה (ספרי):\",1,0],[2,133,8,4,\"וזה מעשה המנרה. שֶׁהֶרְאָהוּ הַקָּבָּ\\\"ה בְּאֶצְבַּע, לְפִי שֶׁנִּתְקַשָּׁה בָהּ, לְכָךְ נֶאֱמַר \\\"וְזֶה\\\":\",1,0],[2,133,8,4,\"מקשה. בטדי\\\"ץ בְּלַעַז, לְשׁוֹן \\\"דָּא לְדָא נָקְשָׁן\\\" (דניאל ה'), עֶשֶׁת שֶׁל כִּכַּר זָהָב הָיְתָה, וּמַקִּישׁ בְּקֻרְנָס, וְחוֹתֵךְ בְּכַשִּׁיל, לְפַשֵּׁט אֵבָרֶיהָ כְּתִקְנָן, וְלֹא נַעֲשֵׂית אֵבָרִים אֵבָרִים עַ\\\"יְ חִבּוּר (עי' ספרא):\",2,0],[2,133,8,4,\"עד ירכה. יְרֵכָהּ הִיא הַשִּׁדָּה שֶׁעַל הָרַגְלַיִם, חָלוּל, כְּדֶרֶךְ מְנוֹרוֹת כֶּסֶף שֶׁלִּפְנֵי הַשָּׂרִים:\",3,0],[2,133,8,4,\"עד ירכה עד פרחה. כְּלוֹמַר גּוּפָהּ שֶׁל מְנוֹרָה כֻּלָּהּ וְכָל הַתָּלוּי בָּהּ:\",4,0],[2,133,8,4,\"עד ירכה. שֶׁהוּא אֵבָר גָּדוֹל:\",5,0],[2,133,8,4,\"עד פרחה. שֶׁהוּא מַעֲשֶׂה דַק שֶׁבָּהּ, הַכֹּל מִקְשָׁה; וְדֶרֶךְ \\\"עַד\\\" לְשַׁמֵּשׁ בְּלָשׁוֹן זֶה, כְּמוֹ \\\"מִגָּדִישׁ וְעַד קָמָה וְעַד כֶּרֶם זָיִת\\\" (שופטים ט\\\"ו):\",6,0],[2,133,8,4,\"כמראה אשר הראה וגו'. כַּתַּבְנִית אֲשֶׁר הֶרְאָהוּ בָהָר, כְּמוֹ שֶׁנֶּאֱמַר (שמות כ\\\"ה) — וּרְאֵה וַעֲשֵׂה בְתַבְנִיתָם וְגוֹ' (ספרי):\",7,0],[2,133,8,4,\"כן עשה את המנרה. מִי שֶׁעֲשָׂאָהּ; וּמִ\\\"אַ, עַל יְדֵי הַקָּבָּ\\\"ה נַעֲשֵׂית מֵאֵלֶיהָ (תנחומא):\",8,0],[2,133,8,6,\"קח את הלוים. קָחֵם בִּדְבָרִים — אַשְׁרֵיכֶם שֶׁתִּזְכּוּ לִהְיוֹת שַׁמָּשִׁים לַמָּקוֹם:\",1,0],[2,133,8,7,\"הזה עליהם מי חטאת. שֶׁל אֵפֶר הַפָּרָה מִפְּנֵי טְמֵאֵי מֵתִים שֶׁבָּהֶם:\",1,0],[2,133,8,7,\"והעבירו תער. מָצָאתִי בְדִבְרֵי רַבִּי מֹשֶׁה הַדַּרְשָׁן לְפִי שֶׁנִּתְּנוּ כַפָּרָה עַל הַבְּכוֹרוֹת שֶׁעָבְדוּ עֲ\\\"זָ, וְהִיא קְרוּיָה זִבְחֵי מֵתִים, וְהַמְּצֹרָע קָרוּי מֵת, הִזְקִיקָם תִּגְלַחַת כִּמְצוֹרָעִים:\",2,0],[2,133,8,8,\"ולקחו פר בן בקר. וְהוּא עוֹלָה, כְּמוֹ שֶׁכָּתוּב \\\"וַעֲשֵֹה … וְאֶת הָאֶחָד עֹלָה\\\", וְהוּא קָרְבַּן צִבּוּר בַּעֲ\\\"זָ:\",1,0],[2,133,8,8,\"ופר שני. מַה תַּ\\\"ל שֵׁנִי? לוֹמַר לְךָ מָה עוֹלָה לֹא נֶאֱכֶלֶת, אַף חַטָּאת לֹא נֶאֱכֶלֶת. וּבְזוֹ יֵשׁ סֶמֶךְ לִדְבָרָיו בְּת\\\"כֹּ; וְאוֹמֵר אֲנִי שֶׁהוֹרָאַת שָׁעָה הָיְתָה, שֶׁשָּׂעִיר הָיָה לָהֶם לְהָבִיא לְחַטַּאת עֲ\\\"זָ עִם פַּר הָעוֹלָה:\",2,0],[2,133,8,9,\"והקהלת את כל עדת. לְפִי שֶׁהַלְוִיִּם נִתָּנִים קָרְבַּן כַּפָּרָה תַּחְתֵּיהֶם, יָבֹאוּ וְיַעַמְדוּ עַל קָרְבָּנָם וְיִסְמְכוּ אֶת יְדֵיהֶם עֲלֵיהֶם:\",1,0],[2,133,8,11,\"והניף אהרן את הלוים תנופה. כְּדֶרֶךְ שֶׁאֲשַׁם מְצֹרָע טָעוּן תְּנוּפָה חַי; שָׁלֹשׁ תְּנוּפוֹת נֶאֶמְרוּ בְּפָרָשָׁה זוֹ: הָרִאשׁוֹנָה — לִבְנֵי קְהָת, לְכָךְ נֶאֱמַר בָּם \\\"וְהָיוּ לַעֲבֹד אֶת עֲבֹדַת ה'\\\", לְפִי שֶׁעֲבוֹדַת קֹדֶשׁ הַקֳּדָשִׁים עֲלֵיהֶם — הָאָרוֹן וְהַשֻּׁלְחָן וְגוֹ'; הַשְּׁנִיָּה — לִבְנֵי גֵרְשׁוֹן, לְכָךְ נֶאֱמַר בָּם \\\"תְּנוּפָה לַה'\\\", שֶׁאַף עֲלֵיהֶם הָיְתָה עֲבוֹדַת הַקֹּדֶשׁ — יְרִיעוֹת וּקְרָסִים הַנִּרְאוֹת בְּבֵית קֹדֶשׁ הַקֳּדָשִׁים, וְהַשְּׁלִישִׁית — לִבְנֵי מְרָרִי:\",1,0],[2,133,8,16,\"נתנים נתנים. נְתוּנִים לְמַשָּׂא, נְתוּנִים לָשִׁיר:\",1,0],[2,133,8,16,\"פטרת. פְּתִיחַת:\",2,0],[2,133,8,17,\"כי לי כל בכור. שֶׁלִּי הָיוּ הַבְּכוֹרוֹת בְּקַו הַדִּין, שֶׁהֲגִנֹּתִי עֲלֵיהֶם בֵּין בְּכוֹרֵי מִצְרַיִם וְלָקַחְתִּי אוֹתָם לִי — עַד שֶׁטָּעוּ בָעֵגֶל, וְעַכְשָׁו \\\"וָאֶקַּח אֶת הַלְוִיִּם\\\":\",1,0],[2,133,8,19,\"ואתנה וגו'. חֲמִשָּׁה פְעָמִים נֶאֶמְרוּ בְנֵי יִשְׂרָאֵל בְּמִקְרָא זֶה, לְהוֹדִיעַ חִבָּתָן, שֶׁנִּכְפַּל אַזְכְּרוֹתֵיהֶן בְּמִקְרָא אֶחָד כְּמִנְיַן חֲמִשָּׁה חֻמְשֵׁי תוֹרָה, וְכָךְ רָאִיתִי בִּבְ\\\"רַ:\",1,0],[2,133,8,19,\"ולא יהיה בבני ישראל נגף. שֶׁלֹא יִצְטָרְכוּ לָגֶשֶׁת אֶל הַקֹּדֶשׁ, שֶׁאִם יִגְּשׁוּ יִהְיֶה נֶגֶף:\",2,0],[2,133,8,20,\"ויעש משה ואהרן וכל עדת וגו'. מֹשֶׁה הֶעֱמִידָן וְאַהֲרֹן הֱנִיפָן, וְיִשְׂרָאֵל סָמְכוּ אֶת יְדֵיהֶם:\",1,0],[2,133,8,22,\"כאשר צוה ה' … כן עשו. לְהַגִּיד שֶׁבַח הָעוֹשִׂין וְהַנַּעֲשֶׂה בָהֶן, שֶׁאֶחָד מֵהֶם לֹא עִכֵּב:\",1,0],[2,133,8,24,\"זאת אשר ללוים. שָׁנִים פּוֹסְלִים וְאֵין הַמּוּמִין פּוֹסְלִים בָּהֶם (ספרי; חולין כ\\\"ד):\",1,0],[2,133,8,24,\"מבן חמש ועשרים. וּבְמָקוֹם אַחֵר אוֹמֵר \\\"מִבֶּן שְׁלֹשִׁים שָׁנָה\\\" (במדבר ד'), הָא כֵיצַד? מִבֶּן כ\\\"ה בָּא לִלְמֹד הִלְכוֹת עֲבוֹדָה וְלוֹמֵד חָמֵשׁ שָׁנִים וּבֶן שְׁלֹשִׁים עוֹבֵד, מִכָּאן לְתַלְמִיד שֶׁלֹּא רָאָה סִימָן יָפֶה בְּמִשְׁנָתוֹ בְּחָמֵשׁ שָׁנִים שׁוּב אֵינוֹ רוֹאֶה (ספרי; חולין כ\\\"ד):\",2,0],[2,133,8,25,\"ולא יעבד עוד. עֲבוֹדַת מַשָּׂא בַּכָּתֵף, אֲבָל חוֹזֵר הוּא לִנְעִילַת שְׁעָרִים וְלָשִׁיר וְלִטְעֹן עֲגָלוֹת, וְזֶהוּ וְשֵׁרֵת אֶת אֶחָיו — עִם אֲחוֹהִי, כְּתַרְגּוּמוֹ:\",1,0],[2,133,8,26,\"לשמר משמרת. לַחֲנוֹת סָבִיב לָאֹהֶל וּלְהָקִים וּלְהוֹרִיד בִּשְׁעַת הַמַּסָּעוֹת:\",1,0],[2,133,9,1,\"בחדש הראשון. פָּרָשָׁה שֶׁבְּרֹאשׁ הַסֵּפֶר לֹא נֶאֶמְרָה עַד אִיָּר, לָמַדְתָּ שֶׁאֵין סֵדֶר מֻקְדָּם וּמְאֻחָר בַּתּוֹרָה, וְלָמָּה לֹא פָתַח בְּזוֹ? מִפְּנֵי שֶׁהִיא גְנוּתָן שֶׁל יִשְׂרָאֵל, שֶׁכָּל אַרְבָּעִים שָׁנָה שֶׁהָיוּ יִשְׂרָאֵל בַּמִדְבָּר לֹא הִקְרִיבוּ אֶלָּא פֶּסַח זוֹ בִּלְבָד (ספרי; תוספתא קידושין ל\\\"ח):\",1,0],[2,133,9,2,\"במועדו. אַף בְּשַׁבָּת, בְּמוֹעֲדוֹ — אַף בְּטֻמְאָה (ספרי):\",1,0],[2,133,9,3,\"ככל חקתיו. אֵלּוּ מִצְוֹת שֶׁבְּגוּפוֹ — שֶֹה תָמִים זָכָר בֶּן שָׁנָה:\",1,0],[2,133,9,3,\"וככל משפטיו. אֵלּוּ מִצְוֹת שֶׁעַל גּוּפוֹ מִמָּקוֹם אַחֵר, כְּגוֹן שִׁבְעַת יָמִים לְמַצָּה וּלְבִעוּר חָמֵץ (מִצְוֹת שֶׁבְּגוּפוֹ — שֶׂה תָמִים זָכָר בֶּן שָׁנָה; שֶׁעַל גּוּפוֹ — צְלִי אֵשׁ רֹאשׁוֹ עַל כְּרָעָיו וְעַל קִרְבּוֹ; שֶׁחוּץ לְגוּפוֹ — מַצָּה וּבִעוּר חָמֵץ):\",2,0],[2,133,9,4,\"וידבר משה וגו'. מַה תַּ\\\"ל? וַהֲלֹא נֶאֱמַר \\\"וַיְדַבֵּר מֹשֶׁה אֶת מֹעֲדֵי ה'\\\", אֶלָּא כְּשֶׁשָּׁמַע פָּרָשַׁת מוֹעֲדִים מִסִּינַי אָמַר לָהֶם, וְחָזַר וְהִזְהִירָם בִּשְׁעַת מַעֲשֶׂה (ספרי):\",1,0],[2,133,9,6,\"לפני משה ולפני אהרן. כְּשֶׁשְּׁנֵיהֶן יוֹשְׁבִין בְּבֵית הַמִּדְרָשׁ בָּאוּ וּשְׁאָלוּם, וְלֹא יִתָּכֵן לוֹמַר זֶה אַחַר זֶה, שֶׁאִם מֹשֶׁה לֹא הָיָה יוֹדֵעַ אַהֲרֹן מִנַּיִן לוֹ (ספרי; בבא בתרא קי\\\"ט):\",1,0],[2,133,9,7,\"למה נגרע. אָמַר לָהֶם אֵין קָדָשִׁים קְרֵבִים בְּטֻמְאָה, אָמְרוּ לוֹ יִזָּרֵק הַדָּם עָלֵינוּ בְכֹהֲנִים טְהוֹרִים וְיֵאָכֵל הַבָּשָֹר לִטְהוֹרִים, אָמַר לָהֶם \\\"עִמְדוּ וְאֶשְׁמְעָה\\\" — כְּתַלְמִיד הַמֻּבְטָח לִשְׁמֹעַ מִפִּי רַבּוֹ; אַשְׁרֵי יְלוּד אִשָּׁה שֶׁכָּךְ מֻבְטָח, שֶׁכָּל זְמַן שֶׁהָיָה רוֹצֶה הָיָה מְדַבֵּר עִם הַשְּׁכִינָה; וּרְאוּיָה הָיְתָה פָרָשָׁה זוֹ לֵאָמֵר עַ\\\"יְ מֹשֶׁה כִּשְׁאָר כָּל הַתּוֹרָה כֻּלָּה, אֶלָּא שֶׁזָּכוּ אֵלּוּ שֶׁתֵּאָמֵר עַל יְדֵיהֶן, שֶׁמְּגַלְגְּלִין זְכוּת עַ\\\"יְ זַכַּאי (שם):\",1,0],[2,133,9,10,\"או בדרך רחקה. נָקוּד עָלָיו, לוֹמַר, לֹא שֶׁרְחוֹקָה וַדַּאי, אֶלָּא שֶׁהָיָה חוּץ לְאַסְקֻפַּת הָעֲזָרָה כָּל זְמַן שְׁחִיטָה (פסח' צ\\\"ג); פֶּסַח שֵׁנִי מַצָּה וְחָמֵץ עִמּוֹ בַּבַּיִת, וְאֵין שָׁם יוֹם טוֹב, וְאֵין אִסּוּר חָמֵץ אֶלָא עִמּוֹ בַאֲכִילָתוֹ (שם צ\\\"ה):\",1,0],[2,133,9,14,\"וכי יגור אתכם גר ועשה פסח. יָכוֹל כָּל הַמִּתְגַּיֵּר יַעֲשֶׂה פֶסַח מִיָּד, תַּ\\\"ל \\\"חֻקָּה אַחַת\\\" וְגוֹ', אֶלָּא כָּךְ מַשְׁמָעוֹ — \\\"וְכִי יָגוּר אִתְּכֶם גֵּר\\\" וּבָא לַעֲשׂוֹת פֶּסַח עִם חֲבֵרָיו, \\\"כְּחֻקַּת הַפֶּסַח וּכְמִשְׁפָּטוֹ יַעֲשֶׂה\\\" (ספרי):\",1,0],[2,133,9,15,\"המשכן לאהל העדת. הַמִּשְׁכָּן הֶעָשׂוּי לִהְיוֹת אֹהֶל לְלוּחוֹת הָעֵדוּת:\",1,0],[2,133,9,15,\"יהיה על המשכן. כְּמוֹ הֹוֶה עַל הַמִּשְׁכָּן, וְכֵן לְשׁוֹן כָּל הַפָּרָשָׁה:\",2,0],[2,133,9,17,\"העלות הענן. כְּתַרְגּוּמוֹ אִסְתַּלָּקוּת, וְכֵן \\\"וְנַעֲלָה הֶעָנָן\\\", וְלֹא יִתָּכֵן לִכְתֹּב וּלְפִי עֲלוֹת הֶעָנָן, וְעָלָה הֶעָנָן, שֶׁאֵין זֶה לְשׁוֹן סִלּוּק אֶלָּא צִמּוּחַ וַעֲלִיָּה, כְּמוֹ \\\"הִנֵּה עָב קְטַנָּה כְּכַף אִישׁ עֹלָה מִיָּם\\\" (מלכים א י\\\"ח):\",1,0],[2,133,9,18,\"על פי ה' יסעו. שָׁנִינוּ בִּמְלֶאכֶת הַמִּשְׁכָּן: כֵּיוָן שֶׁהָיוּ יִשְׂרָאֵל נוֹסְעִים, הָיָה עַמּוּד הֶעָנָן מִתְקַפֵּל וְנִמְשָׁךְ עַל גַּבֵּי בְנֵי יְהוּדָה כְּמִין קוֹרָה, תָּקְעוּ וְהֵרִיעוּ וְתָקְעוּ, לֹא הָיָה מְהַלֵּךְ עַד שֶׁמֹּשֶׁה אוֹמֵר קוּמָה ה' — זוֹ בְּסִפְרֵי — וְנָסַע דֶּגֶל מַחֲנֵה יְהוּדָה:\",1,0],[2,133,9,18,\"ועל פי ה' יחנו. כֵּיוָן שֶׁהָיָה יִשְׂרָאֵל חוֹנִים עַמּוּד הֶעָנָן הָיָה מִתַּמֵּר וְעוֹלֶה וְנִמְשָׁךְ עַל גַּבֵּי בְנֵי יְהוּדָה כְּמִין סֻכָּה, וְלֹא הָיָה נִפְרָשׂ עַד שֶׁמֹּשֶׁה אוֹמֵר \\\"שׁוּבָה ה' רִבְבוֹת אַלְפֵי יִשְׂרָאֵל\\\", הֱוֵי אוֹמֵר \\\"עַ\\\"פִּ ה' וּבְיַד מֹשֶׁה\\\" (ברייתא דמל\\\"ה פי\\\"ג):\",2,0],[2,133,9,20,\"ויש. כְּלוֹמַר, וּפְעָמִים:\",1,0],[2,133,9,20,\"ימים מספר. יָמִים מוּעָטִים:\",2,0],[2,133,9,22,\"או ימים. שָׁנָה, כְּמוֹ \\\"יָמִים תִּהְיֶה גְּאֻלָּתוֹ\\\" (ויקרא כ\\\"ה):\",1,0],[2,133,10,2,\"(עשה לך. שֶׁיִּהְיוּ תוֹקְעִין לְפָנֶיךָ כְּמֶלֶךְ, כְּמוֹ שֶׁנֶּאֱמַר \\\"וַיְהִי בִישֻׁרוּן מֶלֶךְ\\\":\",1,0],[2,133,10,2,\"עשה לך. מִשֶּׁלְּךָ:\",2,0],[2,133,10,2,\"עשה לך. אַתָּה עֲשֵׂה וּמִשְׁתַּמֵּשׁ בָּהֶם וְלֹא אַחֵר):\",3,0],[2,133,10,2,\"למקרא העדה. כְּשֶׁתִּרְצֶה לְדַבֵּר עִם סַנְהֶדְרִין וּשְׁאָר הָעָם וְתִקְרָאֵם לֶאֱסֹף אֵלֶיךָ, תִּקְרָאֵם עַ\\\"יְ חֲצוֹצְרוֹת:\",4,0],[2,133,10,2,\"ולמסע את המחנות. בִּשְׁעַת סִלּוּק מַסָּעוֹת תִּתְקְעוּ בָהֶם לְסִימָן, נִמְצֵאתָ אַתָּה אוֹמֵר עַ\\\"פִּ שְׁלֹשָׁה הָיוּ נוֹסְעִים — עַל פִּי הַקָּבָּ\\\"ה וְעַ\\\"פִּ מֹשֶׁה וְעַ\\\"פִּ הַחֲצוֹצְרוֹת (ברייתא דמל\\\"ה פי\\\"ג):\",5,0],[2,133,10,2,\"מקשה. מִן הָעֶשֶׁת תַּעֲשֶׂה בְּהַקָּשַׁת הַקֻּרְנָס:\",6,0],[2,133,10,3,\"ותקעו בהן. בִּשְׁתֵּיהֶן, וְהוּא סִימָן לְמִקְרָא הָעֵדָה, שֶׁנֶּאֱמַר \\\"וְנוֹעֲדוּ אֵלֶיךָ כָּל הָעֵדָה אֶל פֶּתַח אֹהֶל מוֹעֵד\\\":\",1,0],[2,133,10,4,\"ואם באחת יתקעו. הוּא סִימָן לְמִקְרָא הַנְּשִׂיאִים, שֶׁנֶּאֱמַר \\\"וְנוֹעֲדוּ אֵלֶיךָ הַנְּשִׂיאִים\\\", וְאַף הֵן יְעִידָתָן אֶל פֶּתַח אֹהֶל מוֹעֵד, וּמִגְּזֵרָה שָׁוָה הוּא בָא בְּסִפְרֵי:\",1,0],[2,133,10,5,\"ותקעתם תרועה. סִימָן מַסַּע הַמַּחֲנוֹת תְּקִיעָה תְּרוּעָה וּתְקִיעָה, כָּךְ הוּא נִדְרָשׁ בְּסִפְרֵי מִן הַמִּקְרָאוֹת הַיְתֵרִים:\",1,0],[2,133,10,7,\"ובהקהיל את הקהל וגו'. לְפִי שֶׁהוּא אוֹמֵר \\\"וְהָיוּ לְךָ לְמִקְרָא הָעֵדָה וּלְמַסַּע אֶת הַמַּחֲנוֹת\\\", מַה מִּקְרָא הָעֵדָה תּוֹקֵעַ בְּב' כֹּהֲנִים וּבִשְׁתֵּיהֶם — שֶׁנֶּאֱמַר \\\"וְתָקְעוּ בָהֵן\\\" וְגוֹ' — אַף מַסַּע הַמַּחֲנוֹת בִּשְׁתֵּיהֶם, יָכוֹל מַה מַּסַּע הַמַּחֲנוֹת תּוֹקֵעַ וּמֵרִיעַ וְתוֹקֵעַ, אַף מִקְרָא הָעֵדָה תּוֹקֵעַ וּמֵרִיעַ וְתוֹקֵעַ — וּמֵעַתָּה אֵין חִלּוּק בֵּין מִקְרָא הָעֵדָה לְמַסַּע אֶת הַמַּחֲנוֹת — תַּ\\\"ל \\\"וּבְהַקְהִיל אֶת הַקָּהָל\\\" וְגוֹ', לוֹמַר שֶׁאֵין תְּרוּעָה לְמִקְרָא הָעֵדָה, וְהוּא הַדִּין לַנְּשִׂיאִים, הֲרֵי סִימָן לִשְׁלָשְׁתָּם, מִקְרָא הָעֵדָה בִּשְׁתַּיִם וְשֶׁל נְשִֹיאִים בְּאַחַת — וְזוֹ וָזוֹ אֵין בָּהֶם תְּרוּעָה — וּמַסַּע הַמַּחֲנוֹת בִּשְׁתַּיִם עַ\\\"יְ תְרוּעָה וּתְקִיעָה (ספרי):\",1,0],[2,133,10,8,\"ובני אהרן … יתקעו. בַּמִּקְרָאוֹת וּבַמַּסָּעוֹת הַלָּלוּ:\",1,0],[2,133,10,10,\"על עלתיכם. בְּקָרְבַּן צִבּוּר הַכָּתוּב מְדַבֵּר (ערכין י\\\"א):\",1,0],[2,133,10,10,\"אני ה' אלהיכם. מִכָּאן לָמַדְנוּ מַלְכִיּוֹת עִם זִכְרוֹנוֹת וְשׁוֹפָרוֹת, שֶׁנֶּאֱמַר \\\"וּתְקַעְתֶּם\\\" —זוֹ שׁוֹפָרוֹת, \\\"לְזִכָּרוֹן\\\" — זוֹ זִכְרוֹנוֹת, \\\"אֲנִי ה' אֱלֹהֵיכֶם\\\" — זוֹ מַלְכִיּוֹת וְכוּ' (ספרי):\",2,0],[2,133,10,11,\"בחדש השני. נִמְצֵאתָ אַתָּה אוֹמֵר, שְׁנֵים עָשָׂר חֹדֶשׁ חָסֵר עֲשָׂרָה יָמִים עָשׂוּ בְחוֹרֵב, שֶׁהֲרֵי בְּרֹאשׁ חֹדֶשׁ סִיוָן חָנוּ שָׁם וְלֹא נָסְעוּ עַד עֶשְׂרִים בְּאִיָּר לַשָּׁנָה הַבָּאָה:\",1,0],[2,133,10,12,\"למסעיהם. כַּמִּשְׁפָּט הַמְפֹרָשׁ לְמַסַּע דִּגְלֵיהֶם, מִי רִאשׁוֹן וּמִי אַחֲרוֹן:\",1,0],[2,133,10,12,\"במדבר פארן. קִבְרוֹת הַתַּאֲוָה בְּמִדְבַּר פָּארָן הָיָה, וְשָׁם חָנוּ מִמַּסָּע זֶה:\",2,0],[2,133,10,17,\"והורד המשכן. כֵּיוָן שֶׁנּוֹסֵעַ דֶּגֶל יְהוּדָה, נִכְנְסוּ אַהֲרֹן וּבָנָיו וּפָרְקוּ אֶת הַפָּרֹכֶת וְכִסּוּ בָהּ אֶת הָאָרוֹן, שֶׁנֶּאֱמַר \\\"וּבָא אַהֲרֹן וּבָנָיו בִּנְסֹעַ הַמַּחֲנֶה\\\" (במדבר ד'), וּבְנֵי גֵרְשׁוֹן וּבְנֵי מְרָרִי פוֹרְקִין הַמִּשְׁכָּן וְטוֹעֲנִין אוֹתוֹ בָּעֲגָלוֹת, וְהָאָרוֹן וּכְלֵי הַקֹּדֶשׁ שֶׁל מַשָּׂא בְנֵי קְהָת עוֹמְדִים מְכֻסִּין וּנְתוּנִין עַל הַמּוֹטוֹת עַד שֶׁנָּסַע דֶּגֶל מַחֲנֵה רְאוּבֵן, וְאַ\\\"כַּ \\\"וְנָסְעוּ הַקְּהָתִים\\\" (עי' תנחומא):\",1,0],[2,133,10,21,\"נשאי המקדש. נוֹשְׂאֵי דְבָרִים הַמְקֻדָּשִׁים:\",1,0],[2,133,10,21,\"והקימו את המשכן. בְּנֵי גֵרְשׁוֹן וּבְנֵי מְרָרִי שֶׁהָיוּ קוֹדְמִים לָהֶם מַסַּע שְׁנֵי דְגָלִים, הָיוּ מְקִימִין אֶת הַמִּשְׁכָּן כְּשֶׁהָיָה הֶעָנָן שׁוֹכֵן, וְסִימַן הַחֲנִיָּה נִרְאֶה בְּדֶגֶל מַחֲנֵה יְהוּדָה, וְהֵם חוֹנִים וַעֲדַיִן בְּנֵי קְהָת בָּאִים מֵאַחֲרֵיהֶם עִם שְׁנֵי דְגָלִים הָאַחֲרוֹנִים, הָיוּ בְנֵי גֵרְשׁוֹן וּבְנֵי מְרָרִי מְקִימִין אֶת הַמִּקְדָּשׁ; וּכְשֶׁבָּאִים בְּנֵי קְהָת מוֹצְאִים אוֹתוֹ עַל מְכוֹנוֹ, וּמַכְנִיסִין בּוֹ הָאָרוֹן וְהַשֻּׁלְחָן וְהַמְּנוֹרָה וְהַמִּזְבְּחוֹת, וְזֶהוּ מַשְׁמָעוּת הַמִּקְרָא — וְהֵקִימוּ מְקִימֵי הַמִּשְׁכָּן אוֹתוֹ עד טֶרֶם באם שֶׁל בְּנֵי קְהָת:\",2,0],[2,133,10,25,\"מאסף לכל המחנת. תַּלְמוּד יְרוּשַׁלְמִי: לְפִי שֶׁהָיָה שִׁבְטוֹ שֶׁל דָּן מְרֻבֶּה בְּאֻכְלוֹסִים, הָיָה נוֹסֵעַ בָּאַחֲרוֹנָה, וְכָל מִי שֶׁהָיָה מְאַבֵּד דָּבָר הָיָה מַחֲזִירוֹ לוֹ; אִית מַאן דַּאֲמַר כְּתֵבָה הָיוּ מְהַלְּכִין, וּמַפִּיק לָהּ מִן \\\"כַּאֲשֶׁר יַחֲנוּ כֵּן יִסָּעוּ\\\", וְאִית דְּאָמְרֵי כְּקוֹרָה הָיוּ מְהַלְּכִין, וּמַפִּיק לָהּ מִן \\\"מְאַסֵּף לְכָל הַמַּחֲנֹת\\\" (תלמוד ירושלמי ערובין ה'):\",1,0],[2,133,10,28,\"אלה מסעי. זֶה סֵדֶר מַסְעֵיהֶם:\",1,0],[2,133,10,28,\"ויסעו. בַּיּוֹם הַהוּא נָסְעוּ:\",2,0],[2,133,10,29,\"חבב. הוּא יִתְרוֹ שֶׁנֶּאֱמַר \\\"מִבְּנֵי חֹבָב חֹתֵן מֹשֶׁה\\\" (שופטים ד'), וּמַה תַּ\\\"ל \\\"וַתָּבֹאנָה אֶל רְעוּאֵל אֲבִיהֶן\\\"? מְלַמֵּד שֶׁהַתִּינוֹקוֹת קוֹרִין לַאֲבִי אֲבִיהֶן אַבָּא; וְשֵׁמוֹת הַרְבֵּה הָיוּ לוֹ, \\\"יִתְרוֹ\\\" עַל שֵׁם שֶׁיִּתֵּר פָּרָשָׁה אַחַת בַּתּוֹרָה, \\\"חוֹבָב\\\" עַל שֶׁחִבֵּב אֶת הַתּוֹרָה וְכוּ' (ספרי):\",1,0],[2,133,10,29,\"נסעים אנחנו אל המקום. מִיָּד — עַד שְׁלֹשָׁה יָמִים אָנוּ נִכְנָסִין לָאָרֶץ, שֶׁבְּמַסָּע זֶה הָרִאשׁוֹן נָסְעוּ עַל מְנָת לִכָּנֵס לְאֶרֶץ יִשְׂרָאֵל, אֶלָּא שֶׁחָטְאוּ בְּמִתְאוֹנְנִים; וּמִפְּנֵי מָה שִׁתֵּף מֹשֶׁה עַצְמוֹ עִמָּהֶם? שֶׁעֲדַיִן לֹא נִגְזְרָה גְזֵרָה עָלָיו וּכְסָבוּר שֶׁהוּא נִכְנָס (עי' שם):\",2,0],[2,133,10,30,\"אל ארצי ואל מולדתי. אִם בִּשְׁבִיל נְכָסַי, אִם בִּשְׁבִיל מִשְׁפַּחְתִּי:\",1,0],[2,133,10,31,\"אל נא תעזב. אֵין נָא אֶלָּא לְשׁוֹן בַּקָּשָׁה, שֶׁלֹּא יֹאמְרוּ לֹא נִתְגַּיֵּר יִתְרוֹ מֵחִבָּה, סָבוּר הָיָה שֶׁיֵּשׁ לַגֵּרִים חֵלֶק בָּאָרֶץ, עַכְשָׁו שֶׁרָאָה שֶׁאֵין לָהֶם חֵלֶק, הִנִּיחָם וְהָלַךְ לוֹ (שם):\",1,0],[2,133,10,31,\"כי על כן ידעת חנתנו במדבר. כִּי נָאֶה לְךָ לַעֲשׂוֹת זֹאת, עַל אֲשֶׁר יָדַעְתָּ חֲנוֹתֵנוּ בַּמִּדְבָּר וְרָאִיתָ נִסִּים וּגְבוּרוֹת שֶׁנַּעֲשׂוּ לָנוּ:\",2,0],[2,133,10,31,\"כי על כן ידעת. כְּמוֹ עַל אֲשֶׁר יָדַעְתָּ, כְּמוֹ \\\"כִּי עַל כֵּן לֹא נְתַתִּיהָ לְשֵׁלָה בְנִי\\\" (בראשית ל\\\"ח), \\\"כִּי עַל כֵּן עֲבַרְתֶּם\\\" (בראשית י\\\"ט), \\\"כִּי עַל כֵּן בָּאוּ\\\" (בראשית י\\\"ט), \\\"כִּי עַל כֵּן רָאִיתִי פָנֶיךָ\\\" (בראשית ל\\\"ג):\",3,0],[2,133,10,31,\"והיית לנו לעינים. לְשׁוֹן עָבָר, כְּתַרְגּוּמוֹ; דָּ\\\"אַ: לְשׁוֹן עָתִיד — כָּל דָּבָר וְדָבָר שֶׁיִּתְעַלֵּם מֵעֵינֵינוּ, תִּהְיֶה מֵאִיר עֵינֵינוּ; דָּ\\\"אַ: שֶׁתְּהֵא חָבִיב עָלֵינוּ כְּגַלְגַּל עֵינֵינוּ, שֶׁנֶּאֱמַר (דברים י') \\\"וַאֲהַבְתֶּם אֶת הַגֵּר\\\" (ספרי):\",4,0],[2,133,10,32,\"והיה הטוב ההוא. מַה טּוֹבָה הֵטִיבוּ לוֹ? אָמְרוּ, כְּשֶׁהָיוּ יִשְׂרָאֵל מְחַלְּקִין אֶת הָאָרֶץ, הָיָה דֻּשְׁנָהּ שֶׁל יְרִיחוֹ ת\\\"ק אַמָּה עַל ת\\\"ק אַמָּה וְהִנִּיחוּהוּ מִלַּחֲלֹק, אָמְרוּ מִי שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ בְּחֶלְקוֹ הוּא יִטְּלֶנּוּ, וּבֵין כָּךְ וּבֵין כָּךְ נְתָנוּהוּ לִבְנֵי יִתְרוֹ לְיוֹנָדָב בֶּן רֵכָב שֶׁנֶּאֱמַר \\\"וּבְנֵי קֵינִי חֹתֵן מֹשֶׁה עָלוּ מֵעִיר הַתְּמָרִים\\\" וְגוֹ' (שופטים א'):\",1,0],[2,133,10,33,\"דרך שלשת ימים. מַהֲלַךְ שְׁלֹשֶׁת יָמִים הָלְכוּ בְיוֹם אֶחָד, שֶׁהָיָה הַקָּבָּ\\\"ה חָפֵץ לְהַכְנִיסָם לָאָרֶץ מִיָּד (ספרי):\",1,0],[2,133,10,33,\"וארון ברית ה' נסע לפניהם דרך שלשת ימים. זֶה הָאָרוֹן הַיּוֹצֵא עִמָּהֶם לַמִּלְחָמָה וּבוֹ שִׁבְרֵי לוּחוֹת מוּנָחִים, וּמַקְדִּים לִפְנֵיהֶם דֶּרֶךְ שְׁלֹשֶׁת יָמִים, לְתַקֵּן לָהֶם מְקוֹם חֲנִיָּה (שם; תלמוד ירושלמי שקלים ו'):\",2,0],[2,133,10,34,\"וענן ה' עליהם יומם. שִׁבְעָה עֲנָנִים כְּתוּבִים בְּמַסְעֵיהֶם, אַרְבָּעָה מֵאַרְבַּע רוּחוֹת, וְאֶחָד לְמַעְלָה, וְאֶחָד לְמַטָּה, וְאֶחָד לִפְנֵיהֶם מַנְמִיךְ אֶת הַגָּבוֹהַּ וּמַגְבִּיהַּ אֶת הַנָּמוּךְ וְהוֹרֵג נְחָשִׁים וְעַקְרַבִּים (ספרי; מכילתא שמות י\\\"ג):\",1,0],[2,133,10,34,\"מן המחנה. מִמְּקוֹם חֲנִיָּתָן:\",2,0],[2,133,10,35,\"ויהי בנסע הארן. עָשָֹה לוֹ סִימָנִיּוֹת מִלְּפָנָיו וּמִלְּאַחֲרָיו לוֹמַר שֶׁאֵין זֶה מְקוֹמוֹ, וְלָמָּה נִכְתַּב כָּאן? כְּדֵי לְהַפְסִיק בֵּין פֻּרְעָנוּת לְפֻרְעָנוּת וְכוּ', כִּדְאִיתָא בְּכָל כִּתְבֵי הַקֹּדֶשׁ (שבת קט\\\"ו):\",1,0],[2,133,10,35,\"קומה ה'. לְפִי שֶׁהָיָה מַקְדִּים לִפְנֵיהֶם מַהֲלַךְ שְׁלֹשָׁה יָמִים, הָיָה מֹשֶׁה אוֹמֵר עֲמֹד וְהַמְתֵּן לָנוּ וְאַל תִּתְרַחֵק יוֹתֵר. תַּנְחוּמָא בְּוַיַּקְהֵל:\",2,0],[2,133,10,35,\"ויפצו איביך. הַמְכֻנָּסִין:\",3,0],[2,133,10,35,\"וינסו משנאיך. אֵלּוּ הָרוֹדְפִים:\",4,0],[2,133,10,35,\"משנאיך. אֵלּוּ שׂוֹנְאֵי יִשְׂרָאל, שֶׁכָּל הַשּׂוֹנֵא אֶת יִשְׂרָאֵל שׂוֹנֵא אֶת מִי שֶׁאָמַר וְהָיָה הָעוֹלָם, שֶׁנֶּאֱמַר \\\"וּמְשַׂנְאֶיךָ נָשְׂאוּ רֹאשׁ\\\" (תהלים פ\\\"ג), וּמִי הֵם? \\\"עַל עַמְּךָ יַעֲרִימוּ סוֹד\\\":\",5,0],[2,133,10,36,\"שובה ה'. מְנַחֵם תִּרְגְּמוֹ לְשׁוֹן מַרְגּוֹעַ, וְכֵן \\\"בְּשׁוּבָה וָנַחַת תִּוָּשֵׁעוּן\\\" (ישעיהו ל'):\",1,0],[2,133,10,36,\"רבבות אלפי ישראל. מַגִּיד שֶׁאֵין הַשְּׁכִינָה שׁוֹרָה בְּיִשְׂרָאֵל פְּחוּתִים מִשְּׁנֵי אֲלָפִים וּשְׁתֵּי רְבָבוֹת (יבמות ס\\\"ד):\",2,0],[2,133,11,1,\"ויהי העם כמתאננים. אֵין הָעָם אֶלָּא רְשָׁעִים, וְכֵן הוּא אוֹמֵר \\\"מָה אֶעֱשֶׂה לָעָם הַזֶּה\\\" (שמות י\\\"ז), וְאוֹמֵר \\\"הָעָם הַזֶּה הָרָע\\\" (ירמיהו י\\\"ג); וּכְשֶׁהֵם כְּשֵׁרִים קְרוּאִים \\\"עַמִּי\\\", שֶׁנֶּאֱמַר \\\"שַׁלַּח עַמִּי\\\" (שמות ח׳:ט״ז), \\\"עַמִּי מֶה עָשִׂיתִי לְךָ\\\" (מיכה ו'):\",1,0],[2,133,11,1,\"כמתאננים. אֵין מִתְאוֹנְנִים אֶלָּא לְשׁוֹן עֲלִילָה — מְבַקְּשִׁים עֲלִילָה הֵיאַךְ לִפְרֹשׁ מֵאַחֲרֵי הַמָּקוֹם, וְכֵן הוּא אוֹמֵר בְּשִׁמְשׁוֹן (שופטים י\\\"ד), \\\"כִּי תֹאֲנָה הוּא מְבַקֵּשׁ\\\" (ספרי):\",2,0],[2,133,11,1,\"רע באזני ה'. תּוֹאֲנָה שֶׁהִיא רָעָה בְּאָזְנֵי ה', שֶׁמִּתְכַּוְּנִים שֶׁתָּבֹא בְּאָזְנָיו וְיַקְנִיט, אָמְרוּ: אוֹי לָנוּ, כַּמָּה לֻבַּטְנוּ בַּדֶּרֶךְ הַזֶּה, שְׁלֹשָׁה יָמִים שֶׁלֹּא נַחְנוּ מֵעִנּוּי הַדֶּרֶךְ:\",3,0],[2,133,11,1,\"ויחר אפו. אֲנִי הָיִיתִי מִתְכַּוֵּן לְטוֹבַתְכֶם — שֶׁתִּכָּנְסוּ לָאָרֶץ מִיָּד:\",4,0],[2,133,11,1,\"בקצה המחנה. בְּמֻּקְצִין שֶׁבָּהֶם לְשִׁפְלוּת, אֵלּוּ עֵרֶב רַב, רַבִּי שִׁמְעוֹן בֶּן מְנַסְיָא אוֹמֵר, בַּקְּצִינִים שֶׁבָּהֶם וּבַגְּדוֹלִים (עי' ספרי):\",5,0],[2,133,11,2,\"ויצעק העם אל משה. מָשָׁל לְמֶלֶךְ בָּשָׂר וָדָם שֶׁכָּעַס עַל בְּנוֹ, וְהָלַךְ הַבֵּן אֵצֶל אוֹהֲבוֹ שֶׁל אָבִיו וְאָמַר לוֹ צֵא וּבַקֵּשׁ עָלַי מֵאַבָּא:\",1,0],[2,133,11,2,\"ותשקע האש. שָׁקְעָה בִּמְקוֹמָהּ, שֶׁאִלּוּ חָזְרָה לְאַחַת הָרוּחוֹת הָיְתָה מְקַפֶּלֶת וְהוֹלֶכֶת כָּל אוֹתוֹ הָרוּחַ (ספרי):\",2,0],[2,133,11,4,\"והאספסף. אֵלּוּ עֵרֶב רַב שֶׁנֶּאֶסְפוּ עֲלֵיהֶם בְּצֵאתָם מִמִּצְרַיִם:\",1,0],[2,133,11,4,\"וישבו גם בני ישראל ויבכו. עִמָּהֶם:\",2,0],[2,133,11,4,\"מי יאכלנו בשר. וְכִי לֹא הָיָה לָהֶם בָּשָׂר? וַהֲלֹא כְּבָר נֶאֱמַר \\\"וְגַם עֵרֶב רַב עָלָה אִתָּם וְצֹאן וּבָקָר\\\" וְגוֹ' (שמות י\\\"ב), וְאִ\\\"תֹּ אֲכָלוּם, וַהֲלֹא בִּכְנִיסָתָן לָאָרֶץ נֶאֱמַר \\\"וּמִקְנֶה רַב הָיָה לִבְנֵי רְאוּבֵן\\\" וְגוֹ' (במדבר ל\\\"ב)? אֶלָּא שֶׁמְּבַקְשִׁים עֲלִילָה (ספרי):\",3,0],[2,133,11,5,\"אשר נאכל במצרים חנם. אִ\\\"תֹּ שֶׁמִּצְרִיִּים נוֹתְנִים לָהֶם דָּגִים חִנָּם, וַהֲלֹא כְּבָר נֶאֱמַר \\\"וְתֶבֶן לֹא יִנָּתֵן לָכֶם\\\" (שמות ה'), אִם תֶּבֶן לֹא הָיוּ נוֹתְנִין לָהֶם חִנָּם, דָּגִים הָיוּ נוֹתְנִין לָהֶם חִנָּם? וּמַהוּ אוֹמֵר חִנָּם, חִנָּם מִן הַמִּצְוֹת (ספרי):\",1,0],[2,133,11,5,\"את הקשאים. אָמַר רַבִּי שִׁמְעוֹן מִפְּנֵי מָה הַמָּן מִשְׁתַּנֶּה לְכָל דָּבָר חוּץ מֵאֵלּוּ? מִפְּנֵי שֶׁהֵן קָשִׁים לַמְּנִיקוֹת, אוֹמְרִים לְאִשָּׁה אַל תֹּאכְלִי שׁוּם וּבָצָל מִפְּנֵי הַתִּינוֹק, מָשָׁל לְמֶלֶךְ וְכוּ', כִּדְאִיתָא בְּסִפְרֵי:\",2,0],[2,133,11,5,\"הקשאים. הֵם קוקומבר\\\"שׂ בְּלַעַז:\",3,0],[2,133,11,5,\"אבטיחים. בודיק\\\"ש:\",4,0],[2,133,11,5,\"החציר. כְּרֵישִׁין, פוריל\\\"ש (תַּרְגּוּמוֹ יָת בּוֹצִינַיָּא וְכוּ'):\",5,0],[2,133,11,6,\"אל המן עינינו. מָן בַּשַּׁחַר, מָן בָּעֶרֶב:\",1,0],[2,133,11,7,\"והמן כזרע גד. מִי שֶׁאָמַר זֶה לֹא אָמַר זֶה, יִשְֹרָאֵל אוֹמְרִים \\\"בִּלְתִּי אֶל הַמָּן עֵינֵינוּ\\\" וְהַקָּבָּ\\\"ה הִכְתִּיב בַּתּוֹרָה \\\"וְהַמָּן כִּזְרַע גַּד\\\" וְגוֹ', כְּלוֹמַר רְאוּ בָּאֵי עוֹלָם עַל מָה מִתְלוֹנְנִים בָּנַי, וְהַמָּן כָּךְ וְכָךְ הוּא חָשׁוּב:\",1,0],[2,133,11,7,\"כזרע גד. עָגֹל כְּגִידָּא — זֶרַע קוליינדר\\\"ו:\",2,0],[2,133,11,7,\"הבדלח. שֵׁם אֶבֶן טוֹבָה קריסט\\\"ל:\",3,0],[2,133,11,8,\"שטו. אֵין שִׁיּוּט אֶלָּא לְשׁוֹן טִיּוּל, אישבנ\\\"ייר — בְּלֹא עָמָל:\",1,0],[2,133,11,8,\"וטחנו ברחים וגו'. לֹא יָרַד בָּרֵחַיִם וְלֹא בַקְּדֵרָה וְלֹא בַמְּדוֹכָה, אֶלָּא מִשְׁתַּנֶּה הָיָה טַעֲמוֹ לַנִּטְחָנִין וְלַנְּדוֹכִין וְלַמְבֻשָּׁלִין (ספרי):\",2,0],[2,133,11,8,\"בפרור. קְדֵרָה:\",3,0],[2,133,11,8,\"לשד השמן. לִחְלוּחַ שֶׁל שֶׁמֶן, כָּךְ פֵּרְשׁוֹ דּוּנָשׁ, וְדוֹמֶה לוֹ \\\"נֶהְפַּךְ לְשַׁדִּי בְּחַרְבֹנֵי קַיִץ\\\" (תהילים ל\\\"ב), וְהַלָּמֶ\\\"ד יְסוֹד, — נֶהְפַּךְ לִחְלוּחִי בְּחַרְבוֹנֵי קַיִץ. וְרַבּוֹתֵינוּ פֵרְשׁוּהוּ לְשׁוֹן שָׁדַיִם, אַךְ אֵין עִנְיַן שָׁדַיִם אֵצֶל שֶׁמֶן; וְאִאֶ\\\"ל לְשַׁד הַשָּׁמֶן לְשׁוֹן \\\"וַיִּשְׁמַן יְשֻׁרוּן\\\" (דברים ל\\\"ב), שֶׁאִם כֵּן הָיָה הַמֵּ\\\"ם נָקוּד קָמָץ וְטַעְמוֹ לְמַטָּה תַּחַת הַמֵּ\\\"ם, עַכְשָׁו שֶׁהַמֵּ\\\"ם נָקוּד פַּתָּח קָטָן וְהַטַּעַם תַּחַת הַשִּׁי\\\"ן, לְשׁוֹן שֶׁמֶן הוּא, וְהַשִּׁ\\\"ין הַנְּקוּדָה בְּקָמָץ גָּדוֹל וְאֵינָהּ נְקוּדָה בְּפַתָּח קָטָן מִפְּנֵי שֶׁהוּא סוֹף פָּסוּק. דָּ\\\"אַ: לְשַׁד לְשׁוֹן נוֹטָרִיקוֹן — לִישׁ שֶׁמֶן דְּבַשׁ, כְּעִסָּה הַנִּלּוֹשָׁה בְּשֶׁמֶן וּקְטוּפָה בִדְבַשׁ. וְתַרְגּוּם שֶׁל אֻנְקְלוֹס דִּמְתַרְגֵּם \\\"דְּלִישׁ בְּמִשְׁחָא\\\" נוֹטֶה לְפִתְרוֹנוֹ שֶׁל דּוּנָשׁ, שֶׁהָעִסָּה הַנִּלּוֹשָׁה בְשֶׁמֶן לַחְלוּחִית שֶׁמֶן יֵשׁ בָּהּ:\",4,0],[2,133,11,10,\"בכה למשפחתיו. מִשְׁפָּחוֹת מִשְׁפָּחוֹת נֶאֱסָפִים וּבוֹכִים לְפַרְסֵם תַּרְעֻמְתָּן בְּגָלוּי. וְרַבּוֹתֵינוּ אָמְרוּ (יומא ע\\\"ה) לְמִשְׁפְּחֹתָיו, עַל עִסְקֵי מִשְׁפָּחוֹת —עַל עֲרָיוֹת הַנֶּאֱסָרוֹת לָהֶם:\",1,0],[2,133,11,12,\"כי תאמר אלי. שֶׁאַתָּה אוֹמֵר אֵלַי שָׂאֵהוּ בְחֵיקֶךָ; וְהֵיכָן אָמַר לוֹ כֵן? \\\"לֵךְ נְחֵה אֶת הָעָם\\\" (שמות ל\\\"ב), וְאוֹמֵר \\\"וַיְצַוֵּם אֶל בְּנֵי יִשְׂרָאֵל\\\" (שם ו') — עַל מְנָת שֶׁיִּהְיוּ סוֹקְלִים אֶתְכֶם וּמְחָרְפִים אֶתְכֶם (ספרי):\",1,0],[2,133,11,12,\"על האדמה אשר נשבעת לאבתיו. אַתָּה אוֹמֵר לִי לְשֵׂאתָם בְּחֵיקִי:\",2,0],[2,133,11,15,\"ואם ככה את עושה לי. תָּשַׁשׁ כֹּחוֹ שֶׁל מֹשֶׁה כִּנְקֵבָה כְּשֶׁהֶרְאָהוּ הַקָּבָּ\\\"ה הַפֻּרְעָנוּת שֶׁהוּא עָתִיד לְהָבִיא עֲלֵיהֶם עַל זֹאת, אָמַר לְפָנָיו, אִם כֵּן, הָרְגֵנִי תְּחִלָּה:\",1,0],[2,133,11,15,\"ואל אראה ברעתי. בְּרָעָתָם הָיָה לוֹ לִכְתֹּב, אֶלָּא שֶׁכִּנָּה הַכָּתוּב, וְזֶה אֶחָד מִתִּקּוּנֵי סוֹפְרִים בַּתּוֹרָה לְכִנּוּי וּלְתִקּוּן לָשׁוֹן:\",2,0],[2,133,11,16,\"אספה לי. הֲרֵי תְשׁוּבָה לִתְלוּנָתְךָ שֶׁאָמַרְתָּ לֹא אוּכַל אָנֹכִי לְבַדִּי; וְהַזְּקֵנִים הָרִאשׁוֹנִים הֵיכָן הָיוּ? וַהֲלֹא אַף בְּמִצְרַיִם יָשְׁבוּ עִמָּהֶם, שֶׁנֶּאֱמַר (שמות ג') \\\"לֵךְ וְאָסַפְתָּ אֶת זִקְנֵי יִשְׂרָאֵל\\\"? אֶלָּא בְּאֵשׁ תַּבְעֵרָה מֵתוּ; וּרְאוּיִים הָיוּ לְכָךְ מִסִּינַי, דִּכְתִיב \\\"וַיֶּחֱזוּ אֶת הָאֱלֹהִים\\\" (שם כ\\\"ד) — שֶׁנָּהֲגוּ קַלּוּת רֹאשׁ כְּנוֹשֵׁךְ פִּתּוֹ וּמְדַבֵּר בִּפְנֵי הַמֶּלֶךְ, וְזֶהוּ \\\"וַיֹּאכְלוּ וַיִּשְׁתּוּ\\\", וְלֹא רָצָה הַקָּבָּ\\\"ה לִתֵּן אֲבֵלוּת בְּמַתַּן תּוֹרָה וּפָרַע לָהֶם כָּאן (תנחומא):\",1,0],[2,133,11,16,\"אשר ידעת כי הם וגו'. אוֹתָן שֶׁאַתָּה מַכִּיר שֶׁנִּתְמַנּוּ עֲלֵיהֶם שׁוֹטְרִים בְּמִצְרַיִם בַּעֲבוֹדַת פֶּרֶךְ וְהָיוּ מְרַחֲמִים עֲלֵיהֶם וּמֻכִּים עַל יָדָם, שֶׁנֶּאֱמַר \\\"וַיֻּכּוּ שֹׁטְרֵי בְנֵי יִשְׂרָאֵל\\\" (שמות ה'), עַתָּה יִתְמַנּוּ בִגְדֻלָּתָן כְּדֶרֶךְ שֶׁנִּצְטַעֲרוּ בְּצָרָתָן (עי' ספרי):\",2,0],[2,133,11,16,\"ולקחת אתם. קָחֵם בִּדְבָרִים, \\\"אַשְׁרֵיכֶם שֶׁנִּתְמַנִּיתֶם פַּרְנָסִים עַל בָּנָיו שֶׁל מָקוֹם\\\":\",3,0],[2,133,11,16,\"והתיצבו שם עמך. כְּדֵי שֶׁיִּרְאוּ יִשְׂרָאֵל וְיִנְהֲגוּ בָהֶם גְּדֻלָּה וְכָבוֹד, וְיֹאמְרוּ חֲבִיבִין אֵלּוּ שֶׁנִּכְנְסוּ עִם מֹשֶׁה לִשְׁמֹעַ דִּבּוּר מִפִּי הַקָּבָּ\\\"ה (שם):\",4,0],[2,133,11,17,\"וירדתי. זוֹ אַחַת מֵעֶשֶׂר יְרִידוֹת הַכְּתוּבוֹת בַּתּוֹרָה (שם):\",1,0],[2,133,11,17,\"ודברתי עמך. וְלֹא עִמָּהֶם (שם):\",2,0],[2,133,11,17,\"ואצלתי. כְּתַרְגּוּמוֹ \\\"וַאֲרַבֵּי\\\", כְּמוֹ \\\"וְאֶל אֲצִילֵי בְּנֵי יִשְֹרָאֵל\\\" (שמות כ\\\"ד):\",3,0],[2,133,11,17,\"ושמתי עליהם. לְמָה מֹשֶׁה דוֹמֶה בְאוֹתָהּ שָׁעָה? לְנֵר שֶׁמּוּנַח עַל גַּבֵּי מְנוֹרָה וְהַכֹּל מַדְלִיקִין הֵימֶנּוּ וְאֵין אוֹרוֹ חָסֵר כְּלוּם (ספרי):\",4,0],[2,133,11,17,\"ונשאו אתך. הַתְנֵה עִמָּהֶם עַל מְנָת שֶׁיְּקַבְּלוּ עֲלֵיהֶם טֹרַח בָּנַי, שֶׁהֵם טַרְחָנִים וְסַרְבָנִים (שם):\",5,0],[2,133,11,17,\"ולא תשא אתה לבדך. הֲרֵי תְשׁוּבָה לְמַה שֶּׁאָמַרְתָּ לֹא אוּכַל אָנֹכִי לְבַדִּי:\",6,0],[2,133,11,18,\"התקדשו. הַזְמִינוּ עַצְמְכֶם לְפֻרְעָנוּת, וְכֵן הוּא אוֹמֵר (ירמיהו י\\\"ב) \\\"וְהַקְדִּשֵׁם לְיוֹם הֲרֵגָה\\\" (ספרי):\",1,0],[2,133,11,20,\"עד חדש ימים. זוֹ בַכְּשֵׁרִים, שֶׁמִּתְמַצִּין עַל מִטּוֹתֵיהֶן וְאַחַר כָּךְ נִשְׁמָתָן יוֹצְאָה, וּבָרְשָׁעִים הוּא אוֹמֵר \\\"הַבָּשָׂר עוֹדֶנּוּ בֵּין שִׁנֵּיהֶם\\\" (פסוק ל\\\"ג), כָּךְ הִיא שְׁנוּיָה בְסִפְרֵי, אֲבָל בִּמְכִילְתָּא שְׁנוּיָה חִלּוּף, הָרְשָׁעִים אוֹכְלִים וּמִצְטַעֲרִין שְׁלֹשִׁים יוֹם, וְהַכְּשֵׁרִים הַבָּשָׂר עוֹדֶנּוּ בֵּין שִׁנֵּיהֶם (עי' יומא ע\\\"ה):\",1,0],[2,133,11,20,\"עד אשר יצא מאפכם. כְּתַרְגּוּמוֹ \\\"דִי תְקוֹצוּן בֵּיהּ\\\", יְהֵא דוֹמֶה לָכֶם כְּאִלּוּ אֲכַלְתֶּם מִמֶּנּוּ יוֹתֵר מִדַּאי עַד שֶׁיּוֹצֵא וְנִגְעָל לַחוּץ דֶּרֶךְ הָאָף:\",2,0],[2,133,11,20,\"והיה לכם לזרא. שֶׁתִּהְיוּ מְרַחֲקִין אוֹתוֹ יוֹתֵר מִמַּה שֶּׁקֵּרַבְתֶּם, וּבְדִבְרֵי רַבִּי מֹשֶׁה הַדַּרְשָׁן רָאִיתִי שֶׁיֵּשׁ לָשׁוֹן שֶׁקּוֹרִין לַחֶרֶב זָרָא:\",3,0],[2,133,11,20,\"את ה' אשר בקרבכם. אִם לֹא שֶׁנָּטַעְתִּי שְׁכִינָתִי בֵינֵיכֶם, לֹא גָבַהּ לְבַבְכֶם לִכָּנֵס לְכָל הַדְּבָרִים הַלָּלוּ (ספרי):\",4,0],[2,133,11,21,\"שש מאות אלף רגלי. לֹא חָשׁ לִמְנוֹת אֶת הַפְּרָט שְׁלֹשֶׁת אֲלָפִים הַיְתֵרִים; וְרַבִּי מֹשֶׁה הַדַּרְשָׁן פֵּרֵשׁ, שֶׁלֹּא בָכוּ אֶלָּא אוֹתָן שֶׁיָּצְאוּ מִמִּצְרַיִם:\",1,0],[2,133,11,22,\"הצאן ובקר ישחט. זֶה אֶחָד מֵאַרְבָּעָה דְּבָרִים שֶׁהָיָה רַבִּי עֲקִיבָא דּוֹרֵשׁ וְאֵין רַבִּי שִׁמְעוֹן דּוֹרֵשׁ כְּמוֹתוֹ, רַבִּי עֲקִיבָא אוֹמֵר שש מאות אלף רגלי ואתה אמרת בשר אתן להם ואכלו חדש ימים הצאן ובקר, הַכֹּל כְּמַשְׁמָעוֹ, מִי מַסְפִּיק לָהֶם? כָּעִנְיָן שֶׁנֶּאֱמַר (ויקרא כ\\\"ה) \\\"וּמָצָא כְּדֵי גְאֻלָּתוֹ\\\". וְאֵיזוֹ קָשָׁה, זוֹ אוֹ שִׁמְעוּ נָא הַמֹּרִים? אֶלָּא לְפִי שֶׁלֹּא אָמַר בָּרַבִּים, חִסֵּךְ לוֹ הַכָּתוּב וְלֹא נִפְרַע מִמֶּנּוּ, וְזוֹ שֶׁל מְרִיבָה הָיְתָה בְּגָלוּי, לְפִיכָךְ לֹא חִסֵּךְ לוֹ הַכָּתוּב; רַבִּי שִׁמְעוֹן אוֹמֵר, חַס וְשָׁלוֹם, לֹא עָלְתָה עַל דַּעְתּוֹ שֶׁל אוֹתוֹ צַדִיק כָּךְ, מִי שֶׁכָּתוּב בּוֹ \\\"בְּכָל בֵּיתִי נֶאֱמָן הוּא\\\" (במדבר י\\\"ב) יֹאמַר אֵין הַמָּקוֹם מַסְפִּיק לָנוּ? אֶלָּא כָּךְ אָמַר, שש מאות אלף רגלי וגו' ואתה אמרת בשר אתן לְחֹדֶשׁ יָמִים, וְאַחַר כָּךְ תַּהֲרֹג אֻמָּה גְדוֹלָה כָּזוֹ, הצאן ובקר ישחט להם כְּדֵי שֶׁיֵּהָרְגוּ וּתְהִי אֲכִילָה זוֹ מַסְפַּקְתָּן עַד עוֹלָם? וְכִי שִׁבְחֲךָ הוּא זֶה? אוֹמְרִים לוֹ לַחֲמוֹר טֹל כֹּר שְׂעוֹרִים וְנַחְתֹּךְ רֹאשְׁךָ? הֱשִׁיבוֹ הַקָּבָּ\\\"ה, וְאִם לֹא אֶתֵּן יֹאמְרוּ שֶׁקָּצְרָה יָדִי, הֲטוֹב בְּעֵינֶיךָ שֶׁיַּד ה' תִּקְצַר בְּעֵינֵיהֶם? יֹאבְדוּ הֵם וּמֵאָה כַּיּוֹצֵא בָהֶם וְאַל תְּהִי יָדִי קְצָרָה לִפְנֵיהֶם אֲפִלּוּ שָׁעָה אַחַת:\",1,0],[2,133,11,23,\"עתה תראה היקרך דברי. רַבָּן גַּמְלִיאֵל בְּנוֹ שֶׁל רַבִּי יְהוּדָה הַנָּשִׂיא אוֹמֵר, אִי אֶפְשָׁר לַעֲמֹד עַל הַטָּפֵל, מֵאַחַר שֶׁאֵינָן מְבַקְשִׁים אֶלָּא עֲלִילָה, לֹא תַסְפִּיק לָהֶם, סוֹפָן לָדוּן אַחֲרֶיךָ: אִם אַתָּה נוֹתֵן לָהֶם בְּשַׂר בְּהֵמָה גַסָּה, יֹאמְרוּ דַּקָּה בִקַּשְׁנוּ, וְאִם אַתָּה נוֹתֵן לָהֶם דַּקָּה, יֹאמְרוּ גַּסָּה בִקַּשְׁנוּ, חַיָּה וָעוֹף בִּקַּשְׁנוּ, דָּגִים וַחֲגָבִים בִּקַּשְׁנוּ, אָמַר לוֹ, אִם כֵּן יֹאמְרוּ שֶׁקָּצְרָה יָדִי, אָמַר לְפָנָיו, הֲרֵינִי הוֹלֵךְ וּמְפַיְּסָן, אָמַר לוֹ עתה תראה היקרך דברי — שֶׁלֹּא יִשְׁמְעוּ לְךָ. הָלַךְ מֹשֶׁה לְפַיְּסָן, אָמַר לָהֶם היד ה' תקצר, \\\"הֵן הִכָּה צוּר וַיָּזוּבוּ מַיִם וְגוֹ' הֲגַם לֶחֶם יוּכַל תֵּת\\\" (תהלים ע\\\"ח), אָמְרוּ, פְּשָׁרָה הִיא זוֹ, אֵין בּוֹ כֹּחַ לְמַלֹּאות שְׁאֵלָתֵנוּ; וְזֶהוּ שֶׁנֶּאֱמַר ויצא משה וידבר אל העם, כֵּיוָן שֶׁלֹּא שָׁמְעוּ לוֹ, ויאסף שבעים איש וגו' (עי' ספרי):\",1,0],[2,133,11,25,\"ולא יספו. לֹא נִתְנַבְּאוּ אֶלָּא אוֹתוֹ הַיּוֹם לְבַדּוֹ, כָּךְ מְפֹרָשׁ בְּסִפְרֵי, וְאֻנְקְלוֹס תִּרְגֵּם \\\"וְלָא פָסְקִין\\\", שֶׁלֹּא פָסְקָה נְבוּאָה מֵהֶם:\",1,0],[2,133,11,26,\"וישארו שני אנשים. מֵאוֹתָן שֶׁנִּבְחֲרוּ, אָמְרוּ אֵין אָנוּ כְּדַאי לִגְדֻלָּה זוֹ (עי' סנהדרין י\\\"ז):\",1,0],[2,133,11,26,\"והמה בכתבים. בַּמְבֹרָרִים שֶׁבָּהֶם לְסַנְהֶדְרִין, וְנִכְתְּבוּ כֻלָּם נְקוּבִים בְּשֵׁמוֹת וְעַ\\\"יְ גּוֹרָל, לְפִי שֶׁהַחֶשְׁבּוֹן עוֹלֶה לְי\\\"ב שְׁבָטִים שִׁשָּׁה שִׁשָּׁה לְכָל שֵׁבֶט וָשֵׁבֶט, חוּץ מִשְּׁנֵי שְׁבָטִים שֶׁאֵין מַגִּיעַ אֲלֵיהֶם אֶלָּא חֲמִשָּׁה חֲמִשָּׁה, אָמַר מֹשֶׁה אֵין שֵׁבֶט שׁוֹמֵעַ לִי לִפְחוֹת מִשִּׁבְטוֹ זָקֵן אֶחָד, מֶה עָשָׂה, נָטַל ע\\\"ב פְתָקִין וְכָתַב עַל שִׁבְעִים \\\"זָקֵן\\\" וְעַל שְׁנַיִם חָלָק וּבֵרֵר מִכָּל שֵׁבֶט וָשֵׁבֶט שִׁשָּה, וְהָיוּ ע\\\"ב, אָמַר לָהֶם, טְלוּ פִתְקֵיכֶם מִתּוֹךְ קַלְפִּי, מִי שֶׁעָלָה בְיָדוֹ \\\"זָקֵן\\\" נִתְקַדֵּשׁ, מִי שֶׁעָלָה בְיָדוֹ חָלָק אָמַר לוֹ, הַמָּקוֹם לֹא חָפֵץ בָּךְ (ספרי; סנהדרין י\\\"ז):\",2,0],[2,133,11,27,\"וירץ הנער. יֵ\\\"א גֵּרְשׁוֹם בֶּן מֹשֶׁה הָיָה (עי' ילקוט):\",1,0],[2,133,11,28,\"כלאם. הַטֵּל עֲלֵיהֶם צָרְכֵי צִבּוּר וְהֵם כָּלִים מֵאֲלֵיהֶם; דָּ\\\"אַ, תְּנֵם אֶל בֵּית הַכֶּלֶא, לְפִי שֶׁהָיוּ מִתְנַבְּאִים מֹשֶׁה מֵת וִיהוֹשֻׁעַ מַכְנִיס אֶת יִשְׂרָאֵל לָאָרֶץ (עי' ספרי):\",1,0],[2,133,11,29,\"המקנא אתה לי. הֲקִנְאָתִי אַתָּה מְקַנֵּא:\",1,0],[2,133,11,29,\"לי. כְּמוֹ בִּשְׁבִילִי; כָּל לְשׁוֹן קִנְאָה אָדָם הַנּוֹתֵן לֵב עַל הַדָּבָר, אוֹ לִנְקֹם, אוֹ לַעֲזֹר, אנפר\\\"מנט בְּלַעַז, אוֹחֵז בְּעֹבִי הַמַּשָּׂא:\",2,0],[2,133,11,30,\"ויאסף משה. מִפֶּתַח אֹהֶל מוֹעֵד:\",1,0],[2,133,11,30,\"אל המחנה. נִכְנְסוּ אִישׁ לְאָהֳלוֹ:\",2,0],[2,133,11,30,\"ויאסף. לְשׁוֹן כְּנִיסָה אֶל הַבַּיִת, כְּמוֹ \\\"וַאֲסַפְתּוֹ אֶל תּוֹךְ בֵּיתֶךָ\\\" (דברים כב, ב), וְאָב לְכֻלָּם \\\"יִצְבֹּר וְלֹא יֵדַע מִי אֹסְפָם\\\" (תהלים לט, ז), מְלַמֵּד שֶׁלֹא הֵבִיא עֲלֵיהֶם פֻּרְעָנוּת עַד שֶׁנִּכְנְסוּ הַצַּדִּיקִים אִישׁ לְאָהֳלוֹ (ספרי):\",3,0],[2,133,11,31,\"ויגז. וַיַּפְרִיחַ, וְכֵן \\\"כִּי גָז חִישׁ\\\" (תהילים צ'), וְכֵן \\\"נָגוֹזּוּ וְעָבָר\\\" (נחום א'):\",1,0],[2,133,11,31,\"ויטש. וַיַּפְשֵׁט, כְּמוֹ \\\"וְהִנֵּה נְטֻשִׁים עַל פְּנֵי כָל הָאָרֶץ\\\" (שמואל א ל'), \\\"וּנְטַשְׁתִּיךָ הַמִּדְבָּרָה\\\" (יחזקאל כ\\\"ט):\",2,0],[2,133,11,31,\"וכאמתים. פּוֹרְחוֹת בַּגֹּבַהּ, עַד שֶׁהֵן כְּנֶגֶד לִבּוֹ שֶׁל אָדָם, כְּדֵי שֶׁלֹּא יְהֵא טוֹרֵחַ בַּאֲסִיפָתָן לֹא לְהַגְבִּיהַּ וְלֹא לִשְׁחוֹת (ספרי):\",3,0],[2,133,11,32,\"הממעיט. מִי שֶׁאוֹסֵף פָּחוֹת מִכֻּלָּם, הָעֲצֵלִים וְהַחִגְּרִים, אסף עשרה חמרים (שם):\",1,0],[2,133,11,32,\"וישטחו. עָשׂוּ אוֹתָן מַשְׁטִיחִין מַשְׁטִיחִין (שם):\",2,0],[2,133,11,33,\"טרם יכרת. כְּתַרְגּוּמוֹ \\\"עַד לָא פְסַק\\\"; דָּ\\\"אַ, אֵינוֹ מַסְפִּיק לְפָסְקוֹ בְּשִׁנָּיו עַד שֶׁנִּשְׁמָתוֹ יוֹצְאָה:\",1,0],[2,133,12,1,\"ותדבר. אֵין דִּבּוּר בְּכָל מָקוֹם אֶלָּא לָשׁוֹן קָשָׁה, וְכֵן הוּא אוֹמֵר \\\"דִּבֶּר הָאִישׁ אֲדֹנֵי הָאָרֶץ אִתָּנוּ קָשׁוֹת\\\" (בראשית מ\\\"ב), וְאֵין אֲמִירָה בְּכָל מָקוֹם אֶלָּא לְשׁוֹן תַּחֲנוּנִים, וְכֵן הוּא אוֹמֵר \\\"וַיֹּאמַר אַל נָא אַחַי תָּרֵעוּ\\\" (בראשית י\\\"ט), \\\"וַיֹּאמֶר שִׁמְעוּ נָא דְבָרָי\\\" (פסוק ו), כָּל נָא לְשׁוֹן בַּקָּשָׁה (ספרי):\",1,0],[2,133,12,1,\"ותדבר מרים ואהרן. הִיא פָתְחָה בְדִּבּוּר תְּחִלָּה, לְפִיכָךְ הִקְדִּימָהּ הַכָּתוּב, וּמִנַּיִן הָיְתָה יוֹדַעַת מִרְיָם שֶׁפֵּרֵשׁ מֹשֶׁה מִן הָאִשָּׁה? רַבִּי נָתָן אוֹמֵר מִרְיָם הָיְתָה בְצַד צִפּוֹרָה בְּשָׁעָה שֶׁנֶּאֱמַר לְמֹשֶׁה אֶלְדָּד וּמֵידָד מִתְנַבְּאִים בַּמַּחֲנֶה, כֵּיוָן שֶׁשָּׁמְעָה צִפּוֹרָה, אָמְרָה אוֹי לְנְשׁוֹתֵיהֶן שֶׁל אֵלּוּ אִם הֵם נִזְקָקִים לִנְבוּאָה, שֶׁיִּהְיוּ פוֹרְשִׁין מִנְּשׁוֹתֵיהֶן כְּדֶרֶךְ שֶׁפֵּרֵשׁ בַּעְלִי מִמֶּנִּי, וּמִשָּׁם יָדְעָה מִרְיָם וְהִגִּידָה לְאַהֲרֹן; וּמַה מִּרְיָם שֶׁלֹּא נִתְכַּוְּנָה לִגְנוּתוֹ כָּךְ נֶעֶנְשָׁה, קַל וָחֹמֶר לִמְסַפֵּר בִּגְנוּתוֹ שֶׁל חֲבֵרוֹ (ספרי):\",2,0],[2,133,12,1,\"האשה הכשית. מַגִּיד שֶׁהַכֹּל מוֹדִים בְּיָפְיָהּ כְּשֵׁם שֶׁהַכֹּל מוֹדִים בְּשַׁחֲרוּתוֹ שֶׁל כּוּשִׁי (שם):\",3,0],[2,133,12,1,\"כושית. בְּגִימַטְרִיָּא יְפַת מַרְאֶה:\",4,0],[2,133,12,1,\"על אדות האשה. עַל אוֹדוֹת גֵּרוּשֶׁיהָ:\",5,0],[2,133,12,1,\"כי אשה כשית לקח. מַה תַּ\\\"ל? אֶלָּא יֵשׁ לְךְ אִשָּׁה נָאָה בְּיָפְיָהּ וְאֵין נָאָה בְמַעֲשֶׂיהָ, בְּמַעֲשֶׂיהָ וְלֹא בְיָפְיָהּ, אֲבָל זֹאת נָאָה בַכֹּל:\",6,0],[2,133,12,1,\"האשה הכשית. עַל שֵׁם נוֹיָהּ נִקְרֵאת כּוּשִׁית, כְּאָדָם הַקּוֹרֵא אֶת בְּנוֹ נָאֶה כּוּשִׁי, כְּדֵי שֶׁלֹּא תִּשְׁלֹט בּוֹ עַיִן רָעָה:\",7,0],[2,133,12,1,\"כי אשה כשית לקח. וְעַתָּה גֵּרְשָׁהּ:\",8,0],[2,133,12,2,\"הרק אך. עִמּוֹ לְבַדּוֹ דִּבֶּר ה':\",1,0],[2,133,12,2,\"הלא גם בנו. וְלֹא פֵרַשְׁנוּ מִדֶּרֶךְ אֶרֶץ (ספרי):\",2,0],[2,133,12,3,\"ענו. שָׁפָל וְסַבְלָן:\",1,0],[2,133,12,4,\"פתאם. נִגְלָה עֲלֵיהֶם פִּתְאֹם וְהֵם טְמֵאִין בְּדֶרֶךְ אֶרֶץ, וְהָיוּ צוֹעֲקִים \\\"מַיִם מַיִם\\\" לְהוֹדִיעָם שֶׁיָּפֶה עָשָׂה מֹשֶׁה שֶׁפֵּרֵשׁ מִן הָאִשָּׁה, מֵאַחַר שֶׁנִּגְלֵית עָלָיו שְׁכִינָה תָּדִיר וְאֵין עֵת קְבוּעָה לַדִּבּוּר (עי' ילקוט):\",1,0],[2,133,12,4,\"צאו שלשתכם. מַגִּיד שֶׁשְּׁלָשְׁתָּן נִקְרְאוּ בְדִבּוּר אֶחָד מַה שֶּׁאִי אֶפְשָׁר לַפֶּה לוֹמַר וְלָאֹזֶן לִשְׁמֹעַ (ספרי):\",2,0],[2,133,12,5,\"בעמוד ענן. יָצָא יְחִידִי שֶׁלֹּא כְמִדַּת בָּשָׂר וָדָם, מֶלֶךְ בָּשָׂר וָדָם כְּשֶׁיּוֹצֵא לַמִּלְחָמָה יוֹצֵא בְּאֻכְלוּסִים וּכְשֶׁיּוֹצֵא לְשָׁלוֹם יוֹצֵא בְמוּעָטִין, וּמִדַּת הַקָּבָּ\\\"ה יוֹצֵא לַמִּלְחָמָה יְחִידִי, שֶׁנֶּאֱמַר \\\"אִישׁ מִלְחָמָה\\\" (שמות ט\\\"ו), וְיוֹצֵא לְשָׁלוֹם בְּאֻכְלוּסִין, שֶׁנֶּאֱמַר (תהילים ס\\\"ח) \\\"רֶכֶב אֱלֹהִים רִבֹּתַיִם אַלְפֵי שִׁנְאָן\\\" (ספרי):\",1,0],[2,133,12,5,\"ויקרא אהרן ומרים. שֶׁיִּהְיוּ נִמְשָׁכִין וְיוֹצְאִין מִן הֶחָצֵר לִקְרַאת הַדִּבּוּר:\",2,0],[2,133,12,5,\"ויצאו שניהם. וּמִפְּנֵי מָה מְשָׁכָן וְהִפְרִישָן מִמֹּשֶׁה? לְפִי שֶׁאוֹמְרִים מִקְצָת שִׁבְחוֹ שֶׁל אָדָם בְּפָנָיו וְכֻלּוֹ שֶׁלֹּא בְּפָנָיו, וְכֵן מָצִינוּ בְּנֹחַ, שֶׁלֹא בְּפָנָיו נֶאֱמַר \\\"אִישׁ צַדִּיק תָּמִים\\\" (בראשית ו'), וּבְפָנָיו נֶאֱמַר \\\"כִּי אֹתְךָ רָאִיתִי צַדִּיק לְפָנַי\\\" (שם ז'); דָּ\\\"אַ, שֶׁלֹּא יִשְׁמַע בִּנְזִיפָתוֹ שֶׁל אַהֲרֹן (ספרי):\",3,0],[2,133,12,6,\"שמעו נא דברי. אֵין נָא אֶלָּא לְשׁוֹן בַּקָּשָׁה (שם):\",1,0],[2,133,12,6,\"אם יהיה נביאכם. אִם יִהְיוּ לָכֶם נְבִיאִים:\",2,0],[2,133,12,6,\"ה' במראה אליו אתודע. שְׁכִינַת שְׁמִי אֵין נִגְלֵית עָלָיו בְּאַסְפַּקְלַרְיָא הַמְּאִירָה אֶלָּא בַּחֲלוֹם וְחִזָּיוֹן:\",3,0],[2,133,12,8,\"פה אל פה. אָמַרְתִּי לוֹ לִפְרֹשׁ מִן הָאִשָּׁה (שם), וְהֵיכָן אָמַרְתִּי לוֹ? בְּסִינַי — \\\"לֵךְ אֱמֹר לָהֶם שׁוּבוּ לָכֶם לְאָהֳלֵיכֶם וְאַתָּה פֹּה עֲמֹד עִמָּדִי\\\" (דברים ה'):\",1,0],[2,133,12,8,\"ומראה ולא בחדת. מַרְאֶה זֶה מַרְאֵה דִבּוּר, שֶׁאֲנִי מְפָרֵשׁ לוֹ דִּבּוּרִי בְּמַרְאִית פָּנִים שֶׁבּוֹ, וְאֵינִי סוֹתְמוֹ לוֹ בְחִידוֹת, כָּעִנְיָן שֶׁנֶּאֱמַר לִיחֶזְקֵאל (יחזקאל י\\\"ז), \\\"חוּד חִידָה\\\" וְגוֹ'; יָכוֹל מַרְאֵה שְׁכִינָה? תַּ\\\"ל (שמות ל\\\"ג), \\\"לֹא תוּכַל לִרְאֹת אֶת פָּנָי\\\" (ספרי):\",2,0],[2,133,12,8,\"ותמנת ה' יביט. זֶה מַרְאֵה אֲחוֹרַיִם, כָּעִנְיָן שֶׁנֶּאֱמַר (שמות ל\\\"ג), \\\"וְרָאִיתָ אֶת אֲחֹרָי\\\" (ספרי):\",3,0],[2,133,12,8,\"בעבדי במשה. אֵינוֹ אוֹמֵר בְּעַבְדִּי מֹשֶׁה, אֶלָּא בְּעַבְדִּי בְמֹשֶׁה — בְּעַבְדִּי אַעַ\\\"פִּ שֶׁאֵינוֹ מֹשֶׁה, בְּמֹשֶׁה אֲפִלּוּ אֵינוֹ עַבְדִּי כְּדַאי הֱיִיתֶם לִירוֹא מִפָּנָיו, וְכָל שֶׁכֵּן שֶׁהוּא עַבְדִּי, וְעֶבֶד מֶלֶךְ מֶלֶךְ, וְהָיָה לָכֶם לוֹמַר אֵין הַמֶּלֶךְ אוֹהֲבוֹ חִנָּם, וְאִם תֹּאמְרוּ אֵינִי מַכִּיר בְּמַעֲשָׂיו — זוֹ קָשָׁה מִן הָרִאשׁוֹנָה (שם):\",4,0],[2,133,12,9,\"ויחר אף ה' בם וילך. מֵאַחַר שֶׁהוֹדִיעָם סִרְחוֹנָם גָּזַר עֲלֵיהֶם נִדּוּי, קַ\\\"וָ לְבָשָׂר וָדָם, שֶׁלֹּא יִכְעֹס עַל חֲבֵרוֹ עַד שֶׁיּוֹדִיעֶנּוּ סִרְחוֹנוֹ (ספרי):\",1,0],[2,133,12,10,\"והענן סר. וְאַחֲ\\\"כַּ והנה מרים מצרעת כשלג, מָשָׁל לְמֶלֶךְ שֶׁאָמַר לְפֵדָגוֹג, רְדֵה אֶת בְּנִי, אֲבָל לֹא תִרְדֶּנּוּ עַד שֶׁאֵלֵךְ מֵאֶצְלְךָ, שֶׁרַחֲמַי עָלָיו (שם):\",1,0],[2,133,12,11,\"נואלנו. כְּתַרְגּוּמוֹ, לְשׁוֹן אֱוִיל:\",1,0],[2,133,12,12,\"אל נא תהי. אֲחוֹתֵנוּ זוֹ:\",1,0],[2,133,12,12,\"כמת. שֶׁהַמְּצֹרָע חָשׁוּב כַּמֵּת, מַה מֵּת מְטַמֵּא בְּבִיאָה אַף מְצֹרָע מְטַמֵּא בְּבִיאָה (שם):\",2,0],[2,133,12,12,\"אשר בצאתו מרחם אמו. אִמֵּנוּ הָיָה לוֹ לוֹמַר, אֶלָּא שֶׁכִּנָּה הַכָּתוּב, וְכֵן חֲצִי בְשָׂרוֹ, חֲצִי בְשָׂרֵנוּ הָיָה לוֹ לוֹמַר, אֶלָּא שֶׁכִּנָּה הַכָּתוּב, מֵאַחַר שֶׁיָּצְתָה מֵרֶחֶם אִמֵּנוּ, הִיא לָנוּ כְּאִלּוּ נֶאֱכַל חֲצִי בְשָׂרֵנוּ, כָּעִנְיָן שֶׁנֶּאֱמַר \\\"כִּי אָחִינוּ בְשָׂרֵנוּ הוּא\\\" (בראשית ל\\\"ז), וּלְפִי מַשְׁמָעוֹ, אַף הוּא נִרְאֶה כֵן, אֵין רָאוּי לְאָח לְהַנִּיחַ אֶת אֲחוֹתוֹ לִהְיוֹת כַּמֵּת:\",3,0],[2,133,12,12,\"אשר בצאתו. מֵאַחַר שֶׁיָּצָא זֶה מֵרֶחֶם אִמּוֹ שֶׁל זֶה, שֶׁיֵּשׁ כֹּחַ בְּיָדוֹ לַעֲזֹר וְאֵינוֹ עוֹזְרוֹ — הֲרֵי נֶאֱכָל חצי בשרו, שֶׁאָחִיו בְּשָׂרוֹ הוּא; דָּ\\\"אַ, אל נא תהי כמת — אִם אֵינְךָ רוֹפְאָהּ בִּתְפִלָּה, מִי מַסְגִּירָהּ, מִי מְטַהֲרָהּ? אֲנִי אִ\\\"אֶ לִרְאוֹתָהּ, שֶׁאֲנִי קָרוֹב וְאֵין קָרוֹב רוֹאֶה אֶת הַנְּגָעִים, וְכֹהֵן אַחֵר אֵין בָּעוֹלָם, וְזֶהוּ אשר בצאתו מרחם אמו:\",4,0],[2,133,12,13,\"אל נא רפא נא לה. בָּא הַכָּתוּב לְלַמֶּדְךָ דֶּרֶךְ אֶרֶץ, שֶׁהַשּׁוֹאֵל דָּבָר מֵחֲבֵרוֹ צָרִיךְ לוֹמַר שְׁנַיִם אוֹ שְׁלֹשָׁה דִבְרֵי תַחֲנוּנִים וְאַ\\\"כַּ יְבַקֵּשׁ שְׁאֵלוֹתָיו (ספרי):\",1,0],[2,133,12,13,\"לאמר. מַה תַּ\\\"ל ? אָמַר לוֹ הֲשִׁיבֵנִי אִם אַתָּה מְרַפֵּא אוֹתָהּ אִם לָאו עַד שֶׁהֱשִׁיבוֹ וְאָבִיהָ יָרֹק יָרַק וְגוֹ'; רַאֶבֶּ\\\"עֲ אוֹמֵר בְּאַרְבָּעָה מְקוֹמוֹת בִּקֵּשׁ מֹשֶׁה מִלִּפְנֵי הַקָּבָּ\\\"ה לַהֲשִׁיבוֹ אִם יַעֲשֶׂה שְׁאֵלוֹתָיו אִם לָאו: כַּיּוֹצֵא בוֹ, \\\"וַיְדַבֵּר מֹשֶׁה לִפְנֵי ה' לֵאמֹר\\\" וְגוֹ' (שמות ו'), מַה תַּ\\\"ל \\\"לֵאמֹר\\\"? הֲשִׁיבֵנִי אִם גּוֹאֲלָם אַתָּה אִם לָאו עַד שֶׁהֱשִׁיבוֹ \\\"עַתָּה תִרְאֶה\\\" וְגוֹ', כַּיּוֹצֵא בוֹ, \\\"וַיְדַבֵּר מֹשֶׁה לִפְנֵי ה' לֵאמֹר יִפְקֹד ה' אֱלֹהֵי הָרוּחֹת לְכָל בָּשָׂר\\\" (במדבר כ\\\"ז), הֱשִׁיבוֹ \\\"קַח לְךָ\\\", כַּיּוֹצֵא בוֹ \\\"וָאֶתְחַנַּן אֶל ה' בָּעֵת הַהִוא לֵאמֹר\\\" (דברים ג'), הֱשִׁיבוֹ \\\"רַב לָךְ\\\" (ספרי):\",2,0],[2,133,12,13,\"רפא נא לה. מִפְּנֵי מָה לֹא הֶאֱרִיךְ מֹשֶׁה בִּתְפִלָּה? שֶׁלֹּא יִהְיוּ יִשְׂרָאֵל אוֹמְרִים, אֲחוֹתוֹ עוֹמֶדֶת בְּצָרָה וְהוּא עוֹמֵד וּמַרְבֶּה בִתְפִלָּה (ספרי) (דָּ\\\"אַ, שֶׁלֹּא יֹאמְרוּ יִשְׂרָאֵל, בִּשְׁבִיל אֲחוֹתוֹ הוּא מַאֲרִיךְ בִּתְפִלָּה אֲבָל בִּשְׁבִילֵנוּ אֵינוֹ מַאֲרִיךְ בִּתְפִלָּה):\",3,0],[2,133,12,14,\"ואביה ירק ירק בפניה. וְאִם אָבִיהָ הֶרְאָה לָהּ פָּנִים זוֹעֲפוֹת, הלא תכלם שבעת ימים? קַ\\\"וָ לִשְׁכִינָה י\\\"ד יוֹם, אֶלָּא דַּיּוֹ לַבָּא מִן הַדִּין לִהְיוֹת כַּנִּדּוֹן, לְפִיכָךְ אַף בִּנְזִיפָתִי תסגר שבעת ימים (שם; בבא קמא כ\\\"ה):\",1,0],[2,133,12,14,\"ואחר תאסף. אוֹמֵר אֲנִי, כָּל הָאֲסִיפוֹת הָאֲמוּרוֹת בִּמְצֹרָעִים עַל שֵׁם שֶׁהוּא מְשֻׁלָּח מִחוּץ לַמַּחֲנֶה, וּכְשֶׁהוּא נִרְפָּא נֶאֱסָף אֶל הַמַּחֲנֶה, לְכָךְ כָּתוּב בּוֹ אֲסִיפָה, לְשׁוֹן הַכְנָסָה:\",2,0],[2,133,12,15,\"והעם לא נסע. זֶה הַכָּבוֹד חָלַק לָהּ הַמָּקוֹם בִּשְׁבִיל שָׁעָה אַחַת שֶׁנִּתְעַכְּבָה לְמֹשֶׁה כְּשֶׁהֻשְׁלַךְ לַיְאוֹר, שֶׁנֶּאֱמַר (שמות ב') \\\"וַתֵּתַצַּב אֲחֹתוֹ מֵרָחֹק\\\" וְגוֹ' (סוטה ט'):\",1,0],[2,133,13,2,\"שלח לך אנשים. לָמָּה נִסְמְכָה פָרָשַׁת מְרַגְּלִים לְפָרָשַׁת מִרְיָם? לְפִי שֶׁלָּקְתָה עַל עִסְקֵי דִבָּה, שֶׁדִּבְּרָה בְאָחִיהָ, וּרְשָׁעִים הַלָּלוּ רָאוּ וְלֹא לָקְחוּ מוּסָר (תנחומא):\",1,0],[2,133,13,2,\"שלח לך. לְדַעְתְּךָ, אֲנִי אֵינִי מְצַוֶּה לְךָ, אִם תִּרְצֶה שְׁלַח; לְפִי שֶׁבָּאוּ יִשְׂרָאֵל וְאָמְרוּ נִשְׁלְחָה אֲנָשִׁים לְפָנֵינוּ, כְּמָה שֶׁנֶּאֱמַר \\\"וַתִּקְרְבוּן אֵלַי כֻּלְּכֶם\\\" וְגוֹ' (דברים א'), וּמֹשֶׁה נִמְלַךְ בִּשְׁכִינָה, אָמַר, אָמַרְתִּי לָהֶם שֶׁהִיא טוֹבָה, שֶׁנֶּאֱמַר \\\"אַעֲלֶה אֶתְכֶם מֵעֳנִי מִצְרַיִם\\\" וְגוֹ' (שמות ג'), חַיֵּיהֶם שֶׁאֲנִי נוֹתֵן לָהֶם מָקוֹם לִטְעוֹת בְּדִבְרֵי מְרַגְּלִים, לְמַעַן לֹא יִירָשׁוּהָ (תנחומא):\",2,0],[2,133,13,3,\"על פי ה'. בִּרְשׁוּתוֹ, שֶׁלֹּא עִכֵּב עַל יָדוֹ:\",1,0],[2,133,13,3,\"כלם אנשים. כָּל אֲנָשִׁים שֶׁבַּמִּקְרָא לְשׁוֹן חֲשִׁיבוּת, וְאוֹתָהּ שָׁעָה כְּשֵׁרִים הָיוּ:\",2,0],[2,133,13,16,\"ויקרא משה להושע וגו'. הִתְפַּלֵּל עָלָיו יָהּ יוֹשִׁיעֲךָ מֵעֲצַת מְרַגְּלִים (סוטה ל\\\"ד):\",1,0],[2,133,13,17,\"עלו זה בנגב. הוּא הָיָה הַפְּסֹלֶת שֶׁל אֶרֶץ יִשְׂרָאֵל, שֶׁכֵּן דֶּרֶךְ הַתַּגָּרִים מַרְאִין אֶת הַפְּסֹלֶת תְּחִלָּה, וְאַ\\\"כַּ מַרְאִים אֶת הַשֶּׁבַח (תנחומא):\",1,0],[2,133,13,18,\"את הארץ מה הוא. יֵשׁ אֶרֶץ מְגַדֶּלֶת גִּבּוֹרִים וְיֵשׁ אֶרֶץ מְגַדֶּלֶת חַלָּשִׁים, יֵשׁ מְגַדֶּלֶת אֻכְלוּסִין וְיֵשׁ מְמַעֶטֶת אֻכְלוּסִין:\",1,0],[2,133,13,18,\"החזק הוא הרפה. סִימָן מָסַר לָהֶם: אִם בִּפְרָזִים יוֹשְׁבִין, חֲזָקִים הֵם, שֶׁסּוֹמְכִין עַל גְּבוּרָתָם, וְאִם בְּעָרִים בְּצוּרוֹת הֵם יוֹשְׁבִין חַלָּשִׁים הֵם (שם):\",2,0],[2,133,13,19,\"הבמחנים. תַּרְגּוּמוֹ \\\"הַבְפַצְחִין\\\", כְּרַכִּין פְּצוּחִין וּפְתוּחִין מֵאֵין חוֹמָה:\",1,0],[2,133,13,19,\"הטובה הוא. בְּמַעְיָנוֹת וּתְהוֹמוֹת טוֹבִים וּבְרִיאִים:\",2,0],[2,133,13,20,\"היש בה עץ. אִם יֵשׁ בָּהֶם אָדָם כָּשֵׁר שֶׁיָּגֵן עֲלֵיהֶם בִּזְכוּתוֹ (עי' בבא בתרא ט\\\"ו):\",1,0],[2,133,13,20,\"בכורי ענבים. יָמִים שֶׁהָעֲנָבִים מִתְבַּשְּׁלִין בְּבִכּוּר:\",2,0],[2,133,13,21,\"ממדבר צן עד רחב לבא חמת. הָלְכוּ בִגְבוּלֶיהָ בְאֹרֶךְ וּבְרֹחַב כְּמִין גַּ\\\"ם, הָלְכוּ רוּחַ גְּבוּל דְּרוֹמִית מִמִּקְצוֹעַ מִזְרָח עַד מִקְצוֹעַ מַעֲרָב, כְּמוֹ שֶׁצִּוָּה מֹשֶׁה עֲלוּ זֶה בַנֶּגֶב — דֶּרֶךְ גְּבוּל דְּרוֹמִית מִזְרָחִית עַד הַיָּם — שֶׁהַיָּם הוּא גְבוּל מַעֲרָבִי, וּמִשָּׁם חָזְרוּ וְהָלְכוּ כָּל גְּבוּל מַעֲרָבִי עַל שְׂפַת הַיָּם עַד לְבֹא חֲמָת, שֶׁהוּא אֵצֶל הֹר הָהָר בְּמִקְצוֹעַ מַעֲרָבִית צְפוֹנִית, כְּמוֹ שֶׁמְּפֹרָשׁ בִּגְבוּלוֹת הָאָרֶץ בְּפָרָשַׁת אֵלֶּה מַסְעֵי:\",1,0],[2,133,13,22,\"ויבא עד חברון. כָּלֵב לְבַדּוֹ הָלַךְ שָׁם וְנִשְׁתַּטֵּחַ עַל קִבְרֵי אָבוֹת שֶׁלֹּא יְהֵא נִסָּת לַחֲבֵרָיו לִהְיוֹת בַּעֲצָתָם, וְכֵן הוּא אוֹמֵר (דברים א'), \\\"וְלוֹ אֶתֵּן אֶת הָאָרֶץ אֲשֶׁר דָּרַךְ בָּהּ\\\", וּכְתִיב (שופטים א') \\\"וַיִּתְּנוּ לְכָלֵב אֶת חֶבְרוֹן\\\" (סוטה ל\\\"ד):\",1,0],[2,133,13,22,\"שבע שנים נבנתה. אֶפְשַׁר שֶׁבָּנָה חָם אֶת חֶבְרוֹן לִכְנַעַן בְּנוֹ הַקָּטָן קֹדֶם שֶׁיִּבְנֶה אֶת צֹעַן לְמִצְרַיִם בְּנוֹ הַגָּדוֹל? אֶלָּא שֶׁהָיְתָה מְבֻנָּה בְּכָל טוּב עַל אֶחָד מִשִּׁבְעָה בְצֹעַן, וּבָא לְהוֹדִיעֲךָ שִׁבְחָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל, שֶׁאֵין לְךָ טְרָשִׁין בְּאֶרֶץ יִשְׂרָאֵל יוֹתֵר מֵחֶבְרוֹן — לְפִיכָךְ הִקְצוּהָ לְקִבְרוֹת מֵתִים — וְאֵין לְךָ מְעֻלָּה בְּכָל הָאֲרָצוֹת כְּמִצְרַיִם, שֶׁנֶּאֱמַר \\\"כְּגַן ה' כְּאֶרֶץ מִצְרַיִם\\\" (בראשית י\\\"ג), וְצֹעַן הִיא הַמְעֻלָּה שֶׁבְּאֶרֶץ מִצְרַיִם, שֶׁשָּׁם מוֹשַׁב הַמְּלָכִים, שֶׁנֶּאֱמַר \\\"כִּי הָיוּ בְצֹעַן שָׂרָיו\\\" (ישעיהו ל'), וְהָיְתָה חֶבְרוֹן טוֹבָה מִמֶּנָּה שִׁבְעָה חֲלָקִים (סוטה ל\\\"ד; כתובות קי\\\"ב):\",2,0],[2,133,13,23,\"זמורה. שׂוֹכַת גֶּפֶן, וְאֶשְׁכּוֹל שֶׁל עֲנָבִים תָּלוּי בָּהּ:\",1,0],[2,133,13,23,\"וישאהו במוט בשנים. מִמַּשְׁמַע שֶׁנֶּאֱמַר \\\"וַיִּשָּׂאֻהוּ בַמּוֹט\\\" אֵינִי יוֹדֵעַ שֶׁהוּא בִשְׁנַיִם? מַה תַּ\\\"ל \\\"בִּשְׁנָיִם\\\"? בִּשְׁנֵי מוֹטוֹת. הָא כֵיצַד? שְׁמוֹנָה נָטְלוּ אֶשְׁכּוֹל, אֶחָד נָטַל תְּאֵנָה וְאֶחָד רִמּוֹן; יְהוֹשֻׁעַ וְכָלֵב לֹא נָטְלוּ כְלוּם, לְפִי שֶׁכָּל עַצְמָם לְהוֹצִיא דִּבָּה נִתְכַּוְּנוּ — כְּשֵׁם שֶׁפִּרְיָהּ מְשֻׁנֶּה כָּךְ עַמָּהּ מְשֻׁנֶּה; וְאִם חָפֵץ אַתָּה לֵידַע כַּמָּה מַשּׂאוֹי אֶחָד מֵהֶם, צֵא וּלְמַד מֵאֲבָנִים שֶׁהֵקִימוּ בַּגִּלְגָּל — הֵרִימוּ לָהֶם אִיש אֶבֶן אַחַת מִן הַיַּרְדֵן עַל שִׁכְמוֹ וֶהֱקִימוּהָ בַּגִּלְגָּל (יהושע ד') — וּשְׁקָלוּם רַבּוֹתֵינוּ מִשְׁקַל כָּל אַחַת אַרְבָּעִים סְאָה, וּגְמִירֵי טוּנָא דְּמִידְלֵי אֱינַשׁ עַל כַּתְפֵּיהּ אֵינוֹ אֶלָּא שְׁלִישׁ מַשּׂאוֹי כַּמַּשּׂאוֹי שֶׁמְּסַיְּעִין אוֹתוֹ לְהָרִים (סוטה ל\\\"ד):\",2,0],[2,133,13,25,\"וישבו מתור הארץ מקץ ארבעים יום. וַהֲלֹא אַרְבַּע מֵאוֹת פַּרְסָה עַל אַרְבַּע מֵאוֹת פַּרְסָה הִיא, וּמַהֲלַךְ אָדָם בֵּינוֹנִי עֶשֶׂר פַּרְסָאוֹת לַיּוֹם, הֲרֵי מַהֲלַךְ אַרְבָּעִים יוֹם מִן הַמִּזְרָח לַמַּעֲרָב — וְהֵם הָלְכוּ אָרְכָּהּ וְרָחְבָּהּ? אֶלָּא שֶׁגָּלוּי לִפְנֵי הַקָּבָּ\\\"ה שֶׁיִּגְזֹר עֲלֵיהֶם יוֹם לַשָּׁנָה, קִצֵּר לִפְנֵיהֶם אֶת הַדֶּרֶךְ (שם):\",1,0],[2,133,13,26,\"וילכו ויבאו. מַהוּ וַיֵּלְכוּ? לְהַקִּישׁ הֲלִיכָתָן לְבִיאָתָן, מַה בִּיאָתָן בְּעֵצָה רָעָה אַף הֲלִיכָתָן בְּעֵצָה רָעָה (שם ל\\\"ה):\",1,0],[2,133,13,26,\"וישיבו אתם דבר. אֶת מֹשֶׁה וְאֶת אַהֲרֹן:\",2,0],[2,133,13,27,\"זבת חלב ודבש הוא. כָּל דְּבַר שֶׁקֶר שֶׁאֵין אוֹמְרִים בּוֹ קְצָת אֱמֶת בִּתְחִלָּתוֹ, אֵין מִתְקַיֵּם בְּסוֹפוֹ:\",1,0],[2,133,13,28,\"בצרות. לְשׁוֹן חֹזֶק, וְתַרְגּוּמוֹ \\\"כְּרִיכַן\\\", לְשׁוֹן בִּירָנִיּוֹת עֲגֻלּוֹת, וּבְלָשׁוֹן אֲרַמִּי כְּרִיךְ עָגוֹל:\",1,0],[2,133,13,29,\"עמלק יושב וגו'. לְפִי שֶׁנִּכְווּ בַּעֲמָלֵק כְּבָר, הִזְכִּירוּהוּ מְרַגְּלִים כְּדֵי לְיָרְאָם (תנחומא):\",1,0],[2,133,13,29,\"ועל יד הירדן. יָד כְּמַשְׁמָעוֹ, אֵצֶל הַיַּרְדֵּן, וְלֹא תוּכְלוּ לַעֲבֹר:\",2,0],[2,133,13,30,\"ויהס כלב. הִשְׁתִּיק אֶת כֻּלָּם:\",1,0],[2,133,13,30,\"אל משה. לִשְׁמֹעַ מַה שֶּׁיְּדַבֵּר בְּמֹשֶׁה, צָוַח וְאָמַר \\\"וְכִי זוֹ בִּלְבַד עָשָׂה לָנוּ בֶן עַמְרָם?\\\" הַשּׁוֹמֵעַ הָיָה סָבוּר שֶׁבָּא לְסַפֵּר בִּגְנוּתוֹ, וּמִתּוֹךְ שֶׁהָיָה בְלִבָּם עַל מֹשֶׁה בִּשְׁבִיל דִּבְרֵי הַמְרַגְּלִים, שָׁתְקוּ כֻלָּם לִשְׁמֹעַ גְּנוּתוֹ, אָמַר \\\"וַהֲלֹא קָרַע לָנוּ אֶת הַיָּם וְהוֹרִיד לָנוּ אֶת הַמָּן וְהֵגִיז לָנוּ אֶת הַשְּׂלָו\\\":\",2,0],[2,133,13,30,\"עלה נעלה. אֲפִלּוּ בַּשָּׁמַיִם, וְהוּא אוֹמֵר עֲשׂוּ סֻלָּמוֹת וַעֲלוּ שָׁם, נַצְלִיחַ בְּכָל דְּבָרָיו (סוטה ל\\\"ה):\",3,0],[2,133,13,30,\"ויהס. לְשׁוֹן שְׁתִיקָה, וְכֵן \\\"הַס כָּל בָּשָׂר\\\" (זכריה ב'), \\\"הַס כִּי לֹא לְהַזְכִּיר\\\" (עמוס ו'), כֵּן דֶּרֶךְ בְּנֵי אָדָם, הָרוֹצֶה לְשַׁתֵּק אֲגֻדַּת אֲנָשִׁים אוֹמֵר \\\"שי\\\"ט\\\":\",4,0],[2,133,13,31,\"חזק הוא ממנו. כִּבְיָכוֹל כְּלַפֵּי מַעְלָה אָמְרוּ (סוטה כ\\\"ה):\",1,0],[2,133,13,32,\"אכלת יושביה. בְּכָל מָקוֹם שֶׁעָבַרְנוּ מְצָאנוּם קוֹבְרֵי מֵתִים, וְהַקָּבָּ\\\"ה עָשָׂה לְטוֹבָה, כְּדֵי לְטָרְדָם בְּאֶבְלָם וְלֹא יִתְּנוּ לֵב לָאֵלּוּ:\",1,0],[2,133,13,32,\"אנשי מדות. גְּדוֹלִים וּגְבוֹהִים, וְצָרִיךְ לָתֵת לָהֶם מִדָּה, כְּגוֹן גָּלְיָת \\\"גָּבְהוֹ שֵׁשׁ אַמּוֹת וָזָרֶת\\\" (שמואל א י\\\"ז), וְכֵן \\\"אִישׁ מָדוֹן\\\" (שמואל ב כ\\\"א), \\\"אִישׁ מִדָּה\\\" (מלכים א י\\\"א):\",2,0],[2,133,13,33,\"הנפילים. עֲנָקִים, מִבְּנֵי שַׁמְחָזַאי וַעֲזָאֵל שֶׁנָּפְלוּ מִן הַשָּׁמַיִם בִּימֵי דּוֹר אֱנוֹשׁ:\",1,0],[2,133,13,33,\"וכן היינו בעיניהם. שָׁמַעְנוּ אוֹמְרִים זֶה לָזֶה, נְמָלִים יֵשׁ בַּכְּרָמִים כַּאֲנָשִׁים (סוטה ל\\\"ה):\",2,0],[2,133,13,33,\"ענק. שֶׁמַּעֲנִיקִים חַמָּה בְּקוֹמָתָן (שם ל\\\"ד):\",3,0],[2,133,14,1,\"כל העדה. סַנְהֶדְרָאוֹת (תנחומא יב):\",1,0],[2,133,14,2,\"לו מתנו. הַלְוַאי וָמַתְנוּ:\",1,0],[2,133,14,4,\"נתנה ראש. כְּתַרְגוּמוֹ \\\"נְמַנֵּי רֵישָׁא\\\" — נָשִׂים עָלֵינוּ מֶלֶךְ; וְרַבּוֹתֵינוּ פֵרְשׁוּ, לְשׁוֹן עֲ\\\"זָ (סנהדרין ק\\\"ז):\",1,0],[2,133,14,9,\"אל תמרדו. וְשׁוּב ואתם אל תראו:\",1,0],[2,133,14,9,\"כי לחמנו הם. נֹאכְלֵם כַּלֶּחֶם:\",2,0],[2,133,14,9,\"סר צלם. מְגִנָּם וְחָזְקָם, כְּשֵׁרִים שֶׁבָּהֶם מֵתוּ — אִיּוֹב שֶׁהָיָה מֵגֵן עֲלֵיהֶם (סוטה ל\\\"ה); (דָּ\\\"אַ, צִלּוֹ שֶׁל הַמָּקוֹם סָר עֲלֵיהֶם):\",3,0],[2,133,14,10,\"לרגום אתם. אֶת יְהוֹשֻׁעַ וְכָלֵב:\",1,0],[2,133,14,10,\"וכבוד ה'. הֶעָנָן יָרַד שָׁם:\",2,0],[2,133,14,11,\"עד אנה. עַד הֵיכָן:\",1,0],[2,133,14,11,\"ינאצני. יַרְגִּיזוּנִי:\",2,0],[2,133,14,11,\"בכל האתות. בִּשְׁבִיל כָּל הַנִּסִּים שֶׁעָשִׂיתִי לָהֶם, הָיָה לָהֶם לְהַאֲמִין שֶׁהַיְכֹלֶת בְּיָדִי לְקַיֵּם הַבְטָחָתִי:\",3,0],[2,133,14,12,\"ואורישנו. לְשׁוֹן תֵּרוּכִין, וְאִ\\\"תֹּ מָה אֶעֱשֶׂה לִשְׁבוּעַת אָבוֹת?\",1,0],[2,133,14,12,\"ואעשה אתך לגוי גדול. שֶׁאַתָּה מִזַּרְעָם:\",2,0],[2,133,14,13,\"ושמעו מצרים. וְשָׁמְעוּ אֶת אֲשֶׁר תַּהַרְגֵם:\",1,0],[2,133,14,13,\"כי העלית. כִּי מְשַׁמֵּשׁ בִּלְשׁוֹן אֲשֶׁר, וְהֵם רָאוּ אֶת אֲשֶׁר הֶעֱלִיתָ בְּכֹחֲךָ הַגָּדוֹל אוֹתָם מִקִּרְבָּם, וּכְשֶׁיִּשְׁמְעוּ שֶׁאַתָּה הוֹרְגָם לֹא יֹאמְרוּ שֶׁחָטְאוּ לְךָ, אֶלָּא יֹאמְרוּ שֶׁכְּנֶגְדָּם יָכֹלְתָּ לְהִלָּחֵם אֲבָל כְּנֶגֶד יוֹשְׁבֵי הָאָרֶץ לֹא יָכֹלְתָּ לְהִלָּחֵם, וְזוֹ הִיא:\",2,0],[2,133,14,14,\"ואמרו אל יושב הארץ הזאת. כְּמוֹ עַל יוֹשֵׁב הָאָרֶץ הַזֹּאת — וּמַה יֹּאמְרוּ עֲלֵיהֶם? מַה שֶּׁאָמוּר בְּסוֹף הָעִנְיָן:\",1,0],[2,133,14,14,\"מבלתי יכלת ה'. בִּשְׁבִיל שֶׁשָּׁמְעוּ כִּי אַתָּה ה' שׁוֹכֵן בְּקִרְבָּם וְעַיִן בְּעַיִן אַתָּה נִרְאֶה לָהֶם, וְהַכֹּל בְּדֶרֶךְ חִבָּה וְלֹא הִכִּירוּ בְךָ שֶׁנִּתְּקָה אַהֲבָתְךָ מֵהֶם עַד הֵנָּה:\",2,0],[2,133,14,15,\"המתה את העם הזה כאיש אחד. פִּתְאֹם, וּמִתּוֹךְ כָּךְ יֹאמְרוּ הַגּוֹיִם אֲשֶׁר שָׁמְעוּ וְגוֹ':\",1,0],[2,133,14,16,\"מבלתי יכלת וגו'. לְפִי שֶׁיּוֹשְׁבֵי הָאָרֶץ חֲזָקִים וְגִבּוֹרִים, וְאֵינוֹ דוֹמֶה פַרְעֹה לִשְׁלֹשִׁים וְאֶחָד מְלָכִים, זֹאת יֹאמְרוּ עַל יוֹשְׁבֵי הָאָרֶץ הַזֹּאת, מִבִּלְתִּי יְכֹלֶת — מִתּוֹךְ שֶׁלֹא הָיָה יְכֹלֶת בְּיָדוֹ לַהֲבִיאָם — שְׁחָטָם:\",1,0],[2,133,14,16,\"יכלת. שֵׁם דָּבָר הוּא:\",2,0],[2,133,14,17,\"(יגדל נא כח ה'. לַעֲשׂוֹת דִּבּוּרְךָ:)\",1,0],[2,133,14,17,\"כאשר דברת לאמר. וּמַהוּ הַדִּבּוּר?\",2,0],[2,133,14,18,\"ה' ארך אפים. לַצַּדִּיקִים וְלָרְשָׁעִים; כְּשֶׁעָלָה מֹשֶׁה לַמָּרוֹם מְצָאוֹ לְהַקָּבָּ\\\"ה שֶׁהָיָה יוֹשֵׁב וְכוֹתֵב ה' אֶרֶךְ אַפַּיִם, אָמַר לוֹ, לַצַּדִּיקִים? אָמַר לוֹ הַקָּבָּ\\\"ה אַף לָרְשָׁעִים, אָמַר לוֹ רְשָׁעִים יֹאבֵדוּ, אָמַר לוֹ חַיֶּיךָ שֶׁתִּצְטָרֵךְ לַדָּבָר; כְּשֶׁחָטְאוּ יִשְׂרָאֵל בָּעֵגֶל וּבַמְּרַגְּלִים הִתְפַּלֵּל מֹשֶׁה לְפָנָיו בְּאֶרֶךְ אַפַּיִם, אָמַר לוֹ הַקָּבָּ\\\"ה וַהֲלֹא אָמַרְתָּ לִי לַצַּדִּיקִים? אָמַר לוֹ וַהֲלֹא אָמַרְתָּ לִי אַף לָרְשָׁעִים, יגדל נא כח ה' לַעֲשׂוֹת דִּבּוּרְךָ (סנהדרין קי\\\"א):\",1,0],[2,133,14,18,\"ונקה. לַשָּׁבִים:\",2,0],[2,133,14,18,\"לא ינקה. לְשֶׁאֵינָן שָׁבִים (יומא פ\\\"ו):\",3,0],[2,133,14,20,\"כדברך. בִּשְׁבִיל מַה שֶּׁאָמַרְתָּ \\\"פֶּן יֹאמְרוּ מִבִּלְתִּי יְכֹלֶת ה'\\\":\",1,0],[2,133,14,21,\"ואולם. כְּמוֹ אֲבָל זֹאת אֶעֱשֶׂה לָהֶם:\",1,0],[2,133,14,21,\"חי אני. לְשׁוֹן שְׁבוּעָה, כְּשֵׁם שֶׁאֲנִי חַי וּכְבוֹדִי יִמָּלֵא אֶת כָּל הָאָרֶץ, כָּךְ אֲקַיֵּם לָהֶם כִּי כָל הָאֲנָשִׁים הָרֹאִים וְגוֹ', (אם יראו את הארץ. הֲרֵי זֶה מִקְרָא מְסֹרָס — חַי אָנִי כִּי כָל הָאֲנָשִׁים אִם יִרְאוּ אֶת הָאָרֶץ וּכְבוֹדִי יִמָּלֵא אֶת כָּל הָאָרֶץ, שֶׁלֹּא יִתְחַלֵּל שְׁמִי בַמַּגֵפָה הַזֹּאת לֵאמֹר מִבִּלְתִּי יְכֹלֶת ה' לַהֲבִיאָם, שֶׁלֹּא אֲמִיתֵם פִּתְאֹם כְּאִיש אֶ' אֶלָּא בְּאִחוּר מ' שָׁנָה מְעַט מְעַט):\",2,0],[2,133,14,22,\"וינסו. כְּמַשְׁמָעוֹ:\",1,0],[2,133,14,22,\"זה עשר פעמים. שְׁנַיִם בַּיָּם וּשְׁנַיִם בַּמָּן וּשְׁנַיִם בַּשְּׂלָו וכוּ', כִּדְאִיתָא בְמַסֶּכֶת עֲרָכִין (דף ט\\\"ו):\",2,0],[2,133,14,23,\"אם יראו. לֹא יִרְאוּ:\",1,0],[2,133,14,23,\"לא יראהו. לֹא יִרְאוּ אֶת הָאָרֶץ:\",2,0],[2,133,14,24,\"רוח אחרת. שְׁתֵּי רוּחוֹת, אַ' בַּפֶה וְאַ' בְּלֵב, לַמְּרַגְּלִים אָמַר אֲנִי עִמָּכֶם בָּעֵצָה, וּבְלִבּוֹ הָיָה לוֹמַר הָאֱמֶת, וְעַל יְדֵי כֵן הָיָה בוֹ כֹּחַ לְהַשְׁתִּיקָם, כְּמוֹ שֶׁנֶּאֱמַר (במדבר י\\\"ג), \\\"וַיַּהַס כָּלֵב\\\", שֶׁהָיוּ סְבוּרִים שֶׁיֹּאמַר כְּמוֹתָם, זֶהוּ שֶׁנֶּאֱמַר בְּסֵ' יְהוֹשֻׁעַ \\\"וָאָשֵׁב אֹתוֹ דָּבָר כַּאֲשֶׁר עִם לְבָבִי\\\" (יהושע י\\\"ד) — וְלֹא כַּאֲשֶׁר עִם פִּי (תנחומא):\",1,0],[2,133,14,24,\"וימלא אחרי. וַיְמַלֵּא אֶת לִבּוֹ אַחֲרַי, וְזֶה מִקְרָא קָצָר:\",2,0],[2,133,14,24,\"אשר בא שמה. חֶבְרוֹן תִּנָּתֵן לוֹ:\",3,0],[2,133,14,24,\"יורשנה. כְּתַרְגּוּמוֹ \\\"יְתַרְכֻנַּהּ\\\", יוֹרִישׁוּ אֶת הָעֲנָקִים וְאֶת הָעָם אֲשֶׁר בָּהּ, וְאֵין לְתַרְגְּמוֹ \\\"יַרְתִּינַהּ\\\" אֶלָּא בִּמְקוֹם יִירָשֶׁנָּה:\",4,0],[2,133,14,25,\"והעמלקי וגו'. אִם תֵּלְכוּ שָׁם יַהַרְגוּ אֶתְכֶם, מֵאַחַר שֶׁאֵינִי עִמָּכֶם:\",1,0],[2,133,14,25,\"מחר פנו. לַאֲחוֹרֵיכֶם, וסעו לכם וגו':\",2,0],[2,133,14,27,\"לעדה הרעה וגו'. אֵלּוּ הַמְרַגְּלִים, מִכָּאן לָעֵדָה שֶׁהִיא עֲשָׂרָה (מגילה כ\\\"ג):\",1,0],[2,133,14,27,\"אשר המה מלינים. אֶת יִשְׂרָאֵל עָלַי:\",2,0],[2,133,14,27,\"את תלנות בני ישראל אשר המה. הַמְרַגְּלִים מלינים אוֹתָם עלי, שמעתי:\",3,0],[2,133,14,28,\"חי אני. לְשׁוֹן שְׁבוּעָה, אִם לֹא כֵן אֶעֱשֶׂה — כִּבְיָכוֹל אֵינִי חַי:\",1,0],[2,133,14,28,\"כאשר דברתם. שֶׁבִּקַּשְׁתֶּם מִמֶּנִּי \\\"אוֹ בַּמִּדְבָּר הַזֶּה לוּ מָתְנוּ\\\" (פסוק ב'):\",2,0],[2,133,14,29,\"וכל פקדיכם לכל מספרכם. כָּל הַנִּמְנֶה לְכָל מִסְפָּר שֶׁאַתֶּם נִמְנִים בּוֹ, כְּגוֹן לָצֵאת וְלָבֹא לַצָּבָא וְלָתֵת שְׁקָלִים, כָּל הַמְּנוּיִים לְכָל אוֹתָן מִסְפָּרוֹת יָמוּתוּ, וְאֵלּוּ הֵן מבן עשרים שנה וגו'; לְהוֹצִיא שִׁבְטוֹ שֶׁל לֵוִי שֶׁאֵין פְּקוּדֵיהֶם מִבֶּן עֶשְׂרִים:\",1,0],[2,133,14,32,\"ופגריכם אתם. כְּתַרְגּוּמוֹ, לְפִי שֶׁדִּבֵּר עַל הַבָּנִים לְהַכְנִיסָם לָאָרֶץ וּבִקֵּשׁ לוֹמַר וְאַתֶּם תָּמוּתוּ, נוֹפֵל לָשׁוֹן זֶה כָּאן לוֹמַר \\\"אתם\\\":\",1,0],[2,133,14,33,\"ארבעים שנה. לֹא מֵת אֶחָד מֵהֶם פָּחוּת מִבֶּן שִׁשִּׁים, לְכָךְ נִגְזַר אַרְבָּעִים, כְּדֵי שֶׁיִּהְיוּ אוֹתָם שֶׁל בְּנֵי עֶשְׂרִים מַגִּיעִין לִכְלַל שִׁשִּׁים; שָׁנָה רִאשׁוֹנָה הָיְתָה בִכְלָל, וְאַעַ\\\"פִּ שֶׁקָּדְמָה לְשִׁלּוּחַ הַמְרַגְּלִים, לְפִי שֶׁמִּשֶּׁעָשׂוּ אֶת הָעֶגֶל עָלְתָה גְזֵרָה זוֹ בְמַחֲשָׁבָה, אֶלָּא שֶׁהִמְתִּין לָהֶם עַד שֶׁתִּתְמַלֵּא סְאָתָם, וְזֶהוּ שֶׁנֶּאֱמַר \\\"וּבְיוֹם פָּקְדִי\\\" — בַּמְרַגְּלִים — \\\"וּפָקַדְתִּי עֲלֵיהֶם חַטָּאתָם\\\" (שמות ל\\\"ב); וְאַף כָּאן נֶאֱמַר \\\"תִּשְׂאוּ אֶת עֲוֹנֹתֵיכֶם\\\" — שְׁתֵּי עֲוֹנוֹת, שֶׁל עֵגֶל וְשֶׁל תְּלוּנָה, וְחָשַׁב לָהֶם בְּמִנְיַן חַיֵּיהֶם מִקְצָת שָׁנָה כְּכֻלָּהּ, וּכְשֶׁנִּכְנְסוּ לִשְׁנַת שִׁשִּׁים מֵתוּ אוֹתָם שֶׁל בְּנֵי עֶשְׂרִים:\",1,0],[2,133,14,33,\"ונשאו את זנותיכם. כְּתַרְגּוּמוֹ \\\"וִיקַבְּלוּן יָת חוֹבֵיכוֹן\\\":\",2,0],[2,133,14,34,\"את תנואתי. שֶׁהֲנִיאוֹתֶם אֶת לְבַבְכֶם מֵאַחֲרַי, תנואה לְשׁוֹן הֲסָרָה, כְּמוֹ \\\"כִּי הֵנִיא אָבִיהָ אֹתָהּ\\\" (במדבר ל):\",1,0],[2,133,14,36,\"וישבו וילינו עליו. וּכְשֶׁשָּׁבוּ מִתּוּר הָאָרֶץ הִרְעִימוּ עָלָיו אֶת כָּל הָעֵדָה בְּהוֹצָאַת דִּבָּה, אוֹתָם אֲנָשִׁים וימתו; כָּל הוֹצָאַת דִּבָּה לְשׁוֹן חִנּוּךְ דְּבָרִים, שֶׁמַּלְקִיחִים לְשׁוֹנָם לְאָדָם לְדַבֵּר בּוֹ, כְּמוֹ \\\"דּוֹבֵב שִׂפְתֵי יְשֵׁנִים\\\" (שיר השירים ז'), וְיֶשְׁנָהּ לְטוֹבָה וְיֶשְׁנָהּ לְרָעָה, לְכָךְ נֶאֱמַר כָּאן מוצאי דבת הארץ רעה, שֶׁיֵּשׁ דִּבָּה שֶׁהִיא טוֹבָה:\",1,0],[2,133,14,36,\"דבה. פרליר\\\"ש בְּלַעַז:\",2,0],[2,133,14,37,\"במגפה לפני ה'. בְּאוֹתָהּ מִיתָה הַהֲגוּנָה לָהֶם, מִדָּה כְּנֶגֶד מִדָּה, הֵם חָטְאוּ בַּלָּשׁוֹן, וְנִשְׁתַּרְבֵּב לְשׁוֹנָם עַד טַבּוּרָם וְתוֹלָעִים יוֹצְאִים מִלְּשׁוֹנָם וּבָאִין לְתוֹךְ טַבּוּרָם, לְכָךְ נֶאֱמַר \\\"בַּמַּגֵּפָה\\\" וְלֹא \\\"בְמַגֵּפָה\\\", וְזֶהוּ לפני ה' — בְּאוֹתָהּ הָרְאוּיָה לָהֶם עַ\\\"פִּ מִדּוֹתָיו שֶׁל הַקָּבָּ\\\"ה שֶׁהוּא מוֹדֵד מִדָּה כְּנֶגֶד מִדָּה (סוטה ל\\\"ה):\",1,0],[2,133,14,38,\"ויהושע וכלב … חיו וגו'. מַה תַּ\\\"ל חיו מן האנשים ההם? אֶלָּא מְלַמֵּד שֶׁנָּטְלוּ חֶלְקָם שֶׁל מְרַגְּלִים בָּאָרֶץ וְקָמוּ תַחְתֵּיהֶם לַחַיִּים (בבא בתרא קי\\\"ח):\",1,0],[2,133,14,40,\"אל ראש ההר. הוּא הַדֶּרֶךְ הָעוֹלֶה לְאֶרֶץ יִשְׂרָאֵל:\",1,0],[2,133,14,40,\"הננו ועלינו אל המקום. לְאֶרֶץ יִשְׂרָאֵל:\",2,0],[2,133,14,40,\"אשר אמר ה'. לְתִתָּהּ לָנוּ, שָׁם נַעֲלֶה:\",3,0],[2,133,14,40,\"כי חטאנו. עַל אֲשֶׁר אָמַרְנוּ הֲלוֹא טוֹב לָנוּ שׁוּב מִצְרָיְמָה:\",4,0],[2,133,14,41,\"והוא לא תצלח. זוֹ שֶׁאַתֶּם עוֹשִׂים לֹא תִצְלָח:\",1,0],[2,133,14,43,\"כי על כן שבתם. כְּלוֹמַר, כִּי זֹאת תָּבֹא לָכֶם עַל אֲשֶׁר שַׁבְתֶּם וְגוֹ':\",1,0],[2,133,14,44,\"ויעפלו. לְשׁוֹן חֹזֶק, וְכֵן \\\"הִנֵּה עֻפְּלָה\\\" (חבקוק ב'), אינג\\\"ריש בְּלַעַז, לְשׁוֹן עַזּוּת, וְכֵן \\\"עֹפֶל בַּת צִיּוֹן\\\" (מיכה ד'), \\\"עֹפֶל וָבַחַן\\\" (ישעיהו ל\\\"ב), וּמִדְרַשׁ תַּנְחוּמָא מְפָרְשׁוֹ לְשׁוֹן אֹפֶל — הָלְכוּ חֲשֵׁכִים, שֶׁלֹא בִרְשׁוּת:\",1,0],[2,133,14,45,\"ויכתום. כְּמוֹ \\\"וָאֶכֹּת אֹתוֹ טָחוֹן\\\" (דברים ט') — מַכָּה אַחַר מַכָּה:\",1,0],[2,133,14,45,\"עד החרמה. שֵׁם הַמָּקוֹם נִקְרָא עַל שֵׁם הַמְּאֹרָע:\",2,0],[2,133,15,2,\"‬כי תבאו. בִּשֵּׂר לָהֶם שֶׁיִּכָּנְסוּ לָאָרֶץ:\",1,0],[2,133,15,3,\"ועשיתם אשה. אֵין זֶה צִוּוּי, אֶלָּא כְּשֶׁתָּבֹאוּ שָׁם וְתַעֲלֶה עַל לְבַבְכֶם לַעֲשׂוֹת אִשֶּׁה לַה':\",1,0],[2,133,15,3,\"לפלא נדר או בנדבה וגו'. אוֹ שֶׁתַּעֲשׂוּ הָאִשֶּׁה בִּשְׁבִיל חוֹבַת מוֹעֲדֵיכֶם, שֶׁחִיַּבְתִּי אֶתְכֶם לַעֲשׂוֹת בַּמּוֹעֵד:\",2,0],[2,133,15,3,\"ריח ניחח. נַחַת רוּחַ לְפָנַי:\",3,0],[2,133,15,4,\"והקריב המקריב. תַּקְרִיבוּ נְסָכִים וּמִנְחָה לְכָל בְּהֵמָה; הַמִּנְחָה כָּלִיל וְהַשֶּׁמֶן נִבְלָל בְּתוֹכָהּ, וְהַיַּיִן לַסְּפָלִים, כְּמוֹ שֶׁשָּׁנִינוּ בְמַסֶּכֶת סֻכָּה (דף מ\\\"ח):\",1,0],[2,133,15,5,\"לכבש האחד. עַל כָּל הָאָמוּר לְמַעְלָה הוּא מוּסָב — עַל הַמִּנְחָה וְעַל הַשֶּׁמֶן וְעַל הַיָּיִן:\",1,0],[2,133,15,6,\"או לאיל. וְאִם אַיִל הוּא; וְרַבּוֹתֵינוּ דָרְשׁוּ \\\"אוֹ\\\" — לְרַבּוֹת אֶת הַפַּלְגָּס לְנִסְכֵּי אַיִל (מנחות צ\\\"א):\",1,0],[2,133,15,10,\"אשה ריח. אֵינוֹ מוּסָב אֶלָּא עַל הַמִּנְחָה וְהַשֶּׁמֶן, אֲבָל הַיַּיִן אֵינוֹ אִשֶּׁה, שֶׁאֵינוֹ נִתָּן עַל הָאֵשׁ:\",1,0],[2,133,15,11,\"או לשה וגו'. בֵּין שֶׁהוּא בַכְּבָשִׂים בֵּין שֶׁהוּא בָעִזִּים; כֶּבֶשׂ וָשֶׂה קְרוּיִם בְּתוֹךְ שְׁנָתָם, אַיִל בֶּן שְׁלֹשָׁה עָשָׂר חֹדֶשׁ וְיוֹם אֶחָד:\",1,0],[2,133,15,12,\"כמספר אשר תעשו. כְּמִסְפַּר הַבְּהֵמוֹת אֲשֶׁר תַּקְרִיבוּ לְקָרְבָּן, ככה תעשו נְסָכִים לְכָל אֶחָד מֵהֶם — כְּמִסְפָּרָם שֶׁל בְּהֵמוֹת מִסְפָּרָם שֶׁל נְסָכִים:\",1,0],[2,133,15,15,\"ככם כגר. כְּמוֹתְכֶם כֵּן גֵּר, וְכֵן דֶּרֶךְ לְשׁוֹן עִבְרִית, \\\"כְּגַן ה' כְּאֶרֶץ מִצְרַיִם\\\" (בראשית י\\\"ג) — כֵּן אֶרֶץ מִצְרַיִם, \\\"כָּמוֹנִי כָמוֹךָ כְּעַמִּי כְעַמֶּךָ\\\" (מלכים א כ\\\"ב):\",1,0],[2,133,15,18,\"בבאכם אל הארץ. מְשֻׁנָּה בִּיאָה זוֹ מִכָּל בִּיאוֹת שֶׁבַּתּוֹרָה, שֶׁבְּכֻלָּן נֶאֱמַר כִּי תָבֹא, כִּי תָבֹאוּ, לְפִיכָךְ כֻּלָּן לְמֵדוֹת זוֹ מִזּוֹ, וְכֵיוָן שֶׁפֵּרֵט לְךָ הַכָּתוּב בְּאַחַת מֵהֶן שֶׁאֵינָהּ אֶלָּא לְאַחַר יְרֻשָּׁה וִישִׁיבָה, אַף כֻּלָּן כֵּן, אֲבָל זוֹ נֶאֱמַר בָּהּ \\\"בְּבֹאֲכֶם\\\" — מִשֶּׁנִּכְנְסוּ בָהּ וְאָכְלוּ מִלַּחְמָהּ נִתְחַיְּבוּ בְחַלָּה (ספרי):\",1,0],[2,133,15,20,\"ראשית ערסתכם. כְּשֶׁתָּלוּשׁוּ כְדֵי עִסַּתְכֶם שֶׁאַתֶּם רְגִילִין לָלוּשׁ בַּמִּדְבָּר — וְכַמָּה הִיא? \\\"וַיָּמֹדּוּ בָעֹמֶר\\\" (שמות ט\\\"ז), \\\"עֹמֶר לַגֻּלְגֹּלֶת\\\" (שם) — תָּרִימוּ מֵרֵאשִׁיתָהּ, כְּלוֹמַר קֹדֶם שֶׁתֹּאכְלוּ מִמֶּנָּה, רֵאשִׁית חֶלְקָהּ חלה אַחַת תרימו תרומה לְשֵׁם ה' (עירובין פ\\\"ג):\",1,0],[2,133,15,20,\"חלה. טורטי\\\"ל בְּלַעַז:\",2,0],[2,133,15,20,\"כתרומת גרן. שֶׁלֹּא נֶאֱמַר בָּהּ שִׁעוּר וְלֹא כִתְרוּמַת מַעֲשֵׂר, שֶׁנֶּאֱמַר בָּהּ שִׁעוּר (ספרי), אֲבָל חֲכָמִים נָתְנוּ שִׁעוּר — לְבַעַל הַבַּיִת אֶחָד מֵעֶשְׂרִים וְאַרְבָּעָה וּלְנַחְתּוֹם אֶחָד מֵאַרְבָּעִים וּשְׁמוֹנָה (חלה ב'):\",3,0],[2,133,15,21,\"מראשית ערסתיכם. לָמָּה נֶאֱמַר? לְפִי שֶׁנֶּאֱמַר \\\"רֵאשִׁית עֲרִסֹתֵכֶם\\\", שׁוֹמֵעַ אֲנִי רִאשׁוֹנָה שֶׁבָּעִסּוֹת, תַּ\\\"ל מראשית — מִקְצָתָהּ וְלֹא כֻלָּהּ (ספרי):\",1,0],[2,133,15,21,\"תתנו לה' תרומה. לְפִי שֶׁלֹּא שָׁמַעְנוּ שִׁעוּר לְחַלָּה נֶאֱמַר \\\"תִּתְּנוּ\\\" — שֶׁיְּהֵא בָהּ כְּדֵי נְתִינָה (שם):\",2,0],[2,133,15,22,\"וכי תשגו ולא תעשו. עֲ\\\"זָ הָיְתָה בִּכְלַל כל המצוות שֶׁהַצִּבּוּר מְבִיאִין עָלֵיהָ פַר, וַהֲרֵי הַכָּתוּב מוֹצִיאָהּ כָּאן מִכְּלָלָן, לִדּוֹן בְּפַר לְעוֹלָה וְשָׂעִיר לְחַטָּאת (ספרי):\",1,0],[2,133,15,22,\"וכי תשגו וגו'. בַּעֲ\\\"זָ הַכָּתוּב מְדַבֵּר, אוֹ אֵינוֹ אֶלָּא בְאַחַת מִכָּל הַמִּצְוֹת, תַּ\\\"ל את כל המצות האלה — מִצְוָה אַחַת שֶׁהִיא כְּכָל הַמִּצְוֹת, מַה הָעוֹבֵר עַל כָּל הַמִּצְוֹת פּוֹרֵק עֹל וּמֵפֵר בְּרִית וּמְגַלֶּה פָנִים, אַף מִצְוָה זוֹ פּוֹרֵק בָּהּ עֹל וּמֵפֵר בְּרִית וּמְגַלֶּה פָנִים, וְאֵיזוֹ? זוֹ עֲ\\\"זָ (שם):\",2,0],[2,133,15,22,\"אשר דבר ה' אל משה. אָנֹכִי וְלֹא יִהְיֶה לְךָ מִפִּי הַגְּבוּרָה שְׁמַעְנוּם כְּדִכְתִיב (תהילים ס\\\"ב) \\\"אַחַת דִּבֶּר אֱלֹהִים שְׁתַּיִם זוּ שָׁמָעְנוּ\\\" (הוריות ח'):\",3,0],[2,133,15,23,\"את כל אשר צוה וגו'. מַגִּיד שֶׁכָּל הַמּוֹדֶה בַּעֲ\\\"זָ כְּכוֹפֵר בְּכָל הַתּוֹרָה כֻּלָּהּ וּבְכָל מַה שֶּׁנִּתְנַבְּאוּ הַנְּבִיאִים, שֶׁנֶּאֱמַר מן היום אשר צוה ה' והלאה:\",1,0],[2,133,15,24,\"אם מעיני העדה נעשתה לשגגה. אִם מֵעֵינֵי הָעֵדָה נֶעֶשְׂתָה עֲבֵרָה זוֹ עַל יְדֵי שׁוֹגֵג — שֶׁשָּׁגוּ וְהוֹרוּ עַל אַחַת מִן הָעֲבוֹדוֹת שֶׁהִיא מֻתֶּרֶת לַעֲבֹד עֲ\\\"זָ בְּכָךְ (שם ה'):\",1,0],[2,133,15,24,\"לחטת. חָסֵר א', שֶׁאֵינוֹ כִשְׁאָר חַטָּאוֹת, שֶׁכָּל חַטָּאוֹת שֶׁבַּתּוֹרָה הַבָּאוֹת עִם עוֹלָה הַחַטָּאת קוֹדֶמֶת לָעוֹלָה, שֶׁנֶּא' (ויקרא ה'), \\\"וְאֶת הַשֵּׁנִי יַעֲשֶׂה עֹלָה\\\", וְזוֹ עוֹלָה קוֹדֶמֶת לְחַטָּאת (שם ט\\\"ו):\",2,0],[2,133,15,25,\"הביאו את קרבנם אשה לה'. זֶה הָאָמוּר בַּפָּרָשָׁה, הוּא פַר הָעוֹלָה שֶׁנֶּאֱמַר \\\"אִשֶּׁה לַה'\\\" (ספרי):\",1,0],[2,133,15,25,\"וחטאתם. זֶה הַשָּׂעִיר:\",2,0],[2,133,15,27,\"תחטא בשגגה. בַּעֲ\\\"זָ:\",1,0],[2,133,15,27,\"עז בת שנתה. שְׁאָר עֲבֵרוֹת יָחִיד מֵבִיא כִשְׂבָּה אוֹ שְׂעִירָה, וּבְזוֹ קָבַע לָהּ שְׂעִירָה (שם):\",2,0],[2,133,15,30,\"ביד רמה. בְמֵזִיד:\",1,0],[2,133,15,30,\"מגדף. מְחָרֵף, כְּמוֹ \\\"וְהָיְתָה חֶרְפָּה וּגְדוּפָה\\\" (יחזקאל ה'), \\\"אֲשֶׁר גִּדְּפוּ נַעֲרֵי מֶלֶךְ אַשּׁוּר\\\" (ישעיהו ל\\\"ז), וְעוֹד דָּרְשׁוּ רַבּוֹתֵינוּ מִכָּאן לַמְּבָרֵךְ אֶת הַשֵּׁם שֶׁהוּא בְכָרֵת (כריתות ז'):\",2,0],[2,133,15,31,\"דבר ה'. אַזְהָרַת עֲ\\\"זָ מִפִּי הַגְּבוּרָה וְהַשְּׁאָר מִפִּי מֹשֶׁה (סנהדרין צ\\\"ט):\",1,0],[2,133,15,31,\"עונה בה. בִּזְמַן שֶׁעֲוֹנָהּ בָּהּ — שֶׁלֹּא עָשָׂה תְשׁוּבָה:\",2,0],[2,133,15,32,\"ויהיו … במדבר וימצאו. בִּגְנוּתָן שֶׁל יִשְׂרָאֵל דִּבֵּר הַכָּתוּב, שֶׁלֹא שָׁמְרוּ אֶלָּא שַׁבָּת רִאשׁוֹנָה, וּבַשְּׁנִיָּה בָא זֶה וְחִלְּלָהּ (ספרי):\",1,0],[2,133,15,33,\"המצאים אתו מקשש. שֶׁהִתְרוּ בוֹ וְלֹא הִנִּיחַ מִלְּקוֹשֵׁשׁ, אַף מִשֶׁמְּצָאוּהוּ וְהִתְרוּ בוֹ (שם; סנהדרין מ\\\"א):\",1,0],[2,133,15,34,\"כי לא פרש מה יעשה לו. בְּאֵיזוֹ מִיתָה יָמוּת, אֲבָל יוֹדְעִים הָיוּ שֶׁמְּחַלֵּל שַׁבָּת בְּמִיתָה (שם ע\\\"ח):\",1,0],[2,133,15,35,\"רגום. עָשֹׂה, פשנ\\\"ט, וְכֵן הָלוֹךְ אלנ\\\"ט, וְכֵן \\\"זָכוֹר\\\" (שמות כ, ח) וְ\\\"שָׁמוֹר\\\" (דברים ה, יב):\",1,0],[2,133,15,36,\"ויציאו אתו. מִכָּאן שֶׁבֵּית הַסְּקִילָה חוּץ וְרָחוֹק מִבֵּית דִּין (ספרי):\",1,0],[2,133,15,38,\"ועשו להם ציצת. עַל שֵׁם הַפְּתִילִים הַתְּלוּיִם בָּהּ, כְּמוֹ (יחזקאל ח'), \\\"וַיִּקָּחֵנִי בְּצִיצִת רֹאשִׁי\\\" (מנחות מ\\\"ב). דָּ\\\"אַ: ציצת עַל שֵׁם וּרְאִיתֶם אֹתוֹ, כְּמוֹ \\\"מֵצִיץ מִן הַחֲרַכִּים\\\" (שיר השירים ב'):\",1,0],[2,133,15,38,\"תכלת. צֶבַע יָרֹק שֶׁל חִלָּזוֹן:\",2,0],[2,133,15,39,\"וזכרתם את כל מצות ה'. שֶׁמִּנְיַן גִּימַטְרִיָּא שֶׁל צִיצִית שֵׁשׁ מֵאוֹת, וּשְׁמוֹנָה חוּטִין וַחֲמִשָּׁה קְשָׁרִים הֲרֵי תרי\\\"ג (תנחומא):\",1,0],[2,133,15,39,\"ולא תתורו אחרי לבבכם. כְּמוֹ \\\"מִתּוּר הָאָרֶץ\\\" (במדבר י\\\"ג); הַלֵּב וְהָעֵינַיִם הֵם מְרַגְּלִים לַגּוּף, מְסַרְסְרִים לוֹ אֶת הָעֲבֵרוֹת, הָעַיִן רוֹאָה וְהַלֵּב חוֹמֵד וְהַגּוּף עוֹשֶׂה אֶת הָעֲבֵרָה (תנחומא):\",2,0],[2,133,15,41,\"אני ה'. נֶאֱמָן לְשַׁלֵּם שָׂכָר:\",1,0],[2,133,15,41,\"אלהיכם. נֶאֱמָן לִפָּרַע:\",2,0],[2,133,15,41,\"אשר הוצאתי אתכם. עַל מְנָת כֵּן פָּדִיתִי אֶתְכֶם שֶׁתְּקַבְּלוּ עֲלֵיכֶם גְּזֵרוֹתַי:\",3,0],[2,133,15,41,\"אני ה' אלהיכם. עוֹד לָמָּה נֶאֱמַר? כְּדֵי שֶׁלֹּא יֹאמְרוּ יִשְׂרָאֵל מִפְּנֵי מָה אָמַר הַמָּקוֹם? לֹא שֶׁנַּעֲשֶׂה וְנִטֹּל שָֹכָר? אָנוּ לֹא עוֹשִׂים וְלֹא נוֹטְלִים שָׂכָר עַל כָּרְחֲכֶם אֲנִי מַלְכְּכֶם, וְכֵן הוּא אוֹמֵר (יחזקאל כ'), \\\"אִם לֹא בְּיָד חֲזָקָה … אֶמְלוֹךְ עֲלֵיכֶם\\\" (ספרי). דָּ\\\"אַ, לָמָּה נֶאֱמַר יְצִיאַת מִצְרַיִם? אֲנִי הוּא שֶׁהִבְחַנְתִּי בְמִצְרַיִם בֵּין טִפָּה שֶׁל בְּכוֹר לְשֶׁאֵינָהּ שֶׁל בְּכוֹר, אֲנִי הוּא עָתִיד לְהַבְחִין וְלִפָּרַע מִן הַתּוֹלֶה קָלָא אִילָן בְּבִגְדּוֹ וְאוֹמֵר תְּכֵלֶת הִיא. וּמִיסוֹדוֹ שֶׁל רַבִּי מֹשֶׁה הַדַּרְשָׁן הֶעְתַּקְתִּי: לָמָּה נִסְמְכָה פָרָשַׁת מְקוֹשֵׁשׁ לְפָרָשַׁת עֲ\\\"זָ? לוֹמַר שֶׁהַמְחַלֵּל אֶת הַשַּׁבָּת כְּעוֹבֵד עֲ\\\"זָ, שֶׁאַף הִיא שְׁקוּלָה כְּכָל הַמִּצְוֹת, וְכֵן הוּא אוֹמֵר בְּעֶזְרָא (נחמיה ט׳:י״ד) \\\"וְעַל הַר סִינַי יָרַדְתָּ וַתִּתֵּן לְעַמְּךָ תּוֹרָה וּמִצְוֹת וְאֶת שַׁבַּת קָדְשְׁךָ הוֹדַעְתָ לָהֶם\\\"; וְאַף פָּרָשַׁת צִיצִית לְכָךְ נִסְמְכָה לָאֵלּוּ לְפִי שֶׁאַף הִיא שְׁקוּלָה כְנֶגֶד כָּל הַמִּצְוֹת, שֶׁנֶּאֱמַר וַעֲשִׂיתֶם אֶת כָּל מִצְוֹתָי:\",4,0],[2,133,15,41,\"על כנפי בגדיהם. כְּנֶגֶד \\\"וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים\\\" (שמות יט, ד) ; עַל אַרְבַּע כַּנְפוֹת, וְלֹא בַעֲלַת שָׁלֹשׁ וְלֹא בַעֲלַת חָמֵשׁ, כְּנֶגֶד אַרְבַּע לְשׁוֹנוֹת שֶׁל גְּאֻלָּה שֶׁנֶּאֱמַר בְּמִצְרַיִם \\\"וְהוֹצֵאתִי וְהִצַּלְתִּי וְגָאַלְתִּי וְלָקַחְתִּי\\\" (שמות ו'):\",5,0],[2,133,15,41,\"פתיל תכלת. עַל שֵׁם שִׁכּוּל בְּכוֹרוֹת — תַּרְגּוּמוֹ שֶׁל שִׁכּוּל תִּכְלָא — וּמַכָּתָם הָיְתָה בַלַּיְלָה, וְכֵן צֶבַע הַתְּכֵלֶת דּוֹמֶה לָרָקִיעַ הַמַּשְׁחִיר לְעֵת עֶרֶב; וּשְׁמוֹנָה חוּטִין שֶׁבָּהּ כְּנֶגֶד שְׁמוֹנָה יָמִים שֶׁשָּׁהוּ יִשְׂרָאֵל מִשֶּׁיָּצְאוּ מִמִּצְרַיִם עַד שֶׁאָמְרוּ שִׁירָה עַל הַיָּם:\",6,0],[2,133,16,1,\"ויקח קרח. פָּרָשָׁה זוֹ יָפֶה נִדְרֶשֶׁת בְּמִדְרַשׁ רַבִּי תַנְחוּמָא:\",1,0],[2,133,16,1,\"ויקח קרח. לָקַח אֶת עַצְמוֹ לְצַד אֶחָד לִהְיוֹת נֶחֱלָק מִתּוֹךְ הָעֵדָה לְעוֹרֵר עַל הַכְּהֻנָּה, וְזֶהוּ שֶׁתִּרְגֵם אֻנְקְלוֹס \\\"וְאִתְפְּלֵג\\\" — נֶחֱלַק מִשְּׁאָר הָעֵדָה לְהַחֲזִיק בְּמַחֲלֹקֶת, וְכֵן \\\"מַה יִּקָּחֲךָ לִבֶּךָ\\\" (איוב ט\\\"ו) — לוֹקֵחַ אוֹתְךָ לְהַפְלִיגְךָ מִשְּׁאָר בְּנֵי אָדָם. דָּ\\\"אַ: ויקח קרח, מָשַׁךְ רָאשֵׁי סַנְהֶדְרָאוֹת שֶׁבָּהֶם בִּדְבָרִים, כְּמוֹ שֶׁנֶּאֱמַר \\\"קַח אֶת אַהֲרֹן\\\" (ויקרא ח'), \\\"קְחוּ עִמָּכֶם דְּבָרִים\\\" (הושע י\\\"ד):\",2,0],[2,133,16,1,\"בן יצהר בן קהת בן לוי. וְלֹא הִזְכִּיר \\\"בֶּן יַעֲקֹב\\\", שֶׁבִּקֵּשׁ רַחֲמִים עַל עַצְמוֹ שֶׁלֹא יִזָּכֵר שְׁמוֹ עַל מַחְלְקוֹתָם, שֶׁנֶּאֱמַר \\\"בִּקְהָלָם אַל תֵּחַד כְּבֹדִי\\\" (בראשית מ\\\"ט), וְהֵיכָן נִזְכַּר שְׁמוֹ עַל קֹרַח? בְּהִתְיַחֲסָם עַל הַדּוּכָן בְּדִבְרֵי הַיָּמִים, שֶׁנֶּאֱמַר (דהי\\\"א ו') \\\"בֶּן אֶבְיָסָף בֶּן קֹרַח בֶּן יִצְהָר בֶּן קְהָת בֶּן לֵוִי בֶּן יִשְׂרָאֵל\\\":\",3,0],[2,133,16,1,\"דתן ואבירם. בִּשְׁבִיל שֶׁהָיָה שֵׁבֶט רְאוּבֵן שָׁרוּי בַּחֲנִיָּתָם תֵּימָנָה שָׁכֵן לִקְהָת וּבָנָיו הַחוֹנִים תֵּימָנָה, נִשְׁתַּתְּפוּ עִם קֹרַח בְּמַחֲלָקְתּוֹ — \\\"אוֹי לָרָשָׁע אוֹי לִשְׁכֵנוֹ\\\". וּמָה רָאָה קֹרַח לַחֲלֹק עִם מֹשֶׁה? נִתְקַנֵּא עַל נְשִׂיאוּתוֹ שֶׁל אֱלִיצָפָן בֶּן עֻזִּיאֵל, שֶׁמִּנָּהוּ מֹשֶׁה נָשִׂיא עַל בְּנֵי קְהָת עַל פִּי הַדִּבּוּר, אָמַר קֹרַח, אַחֵי אַבָּא אַרְבָּעָה הָיוּ, שֶׁנֶּאֱמַר (שמות ו') \\\"וּבְנֵי קְהָת\\\" וְגוֹ', עַמְרָם הַבְּכוֹר נָטְלוּ שְׁנֵי בָנָיו גְּדֻלָּה, אֶחָד מֶלֶךְ וְאֶחָד כֹּהֵן גָּדוֹל, מִי רָאוּי לִטֹּל אֶת הַשְּׁנִיָּה? לֹא אֲנִי שֶׁאֲנִי בֶּן יִצְהָר, שֶׁהוּא שֵׁנִי לְעַמְרָם, וְהוּא מִנָּה נָשִׂיא אֶת בֶּן אָחִיו הַקָּטָן מִכֻּלָּם, הֲרֵינִי חוֹלֵק עָלָיו וּמְבַטֵּל אֶת דְּבָרָיו. מֶה עָשָׂה? עָמַד וְכָנַס ר\\\"נ רָאשֵׁי סַנְהֶדְרָאוֹת — רֻבָּן מִשֵּׁבֶט רְאוּבֵן שְׁכֵנָיו וְהֵם אֱלִיצוּר בֶּן שְׁדֵיאוּר וַחֲבֵרָיו וְכַיּוֹצֵא בוֹ, שֶׁנֶּאֱמַר נְשִׂיאֵי עֵדָה קְרִאֵי מוֹעֵד וּלְהַלָּן הוּא אוֹמֵר (במדבר א') \\\"אֵלֶּה קְרוּאֵי הָעֵדָה\\\" — וְהִלְבִּישָׁן טַלִּיתוֹת שֶׁכֻּלָּן תְּכֵלֶת, בָּאוּ וְעָמְדוּ לִפְנֵי מֹשֶׁה, אָמְרוּ לוֹ טַלִּית שֶׁכֻּלָּהּ שֶׁל תְּכֵלֶת חַיֶּבֶת בְּצִיצִית אוֹ פְטוּרָה? אָמַר לָהֶם חַיֶּבֶת, הִתְחִילוּ לִשְׂחֹק עָלָיו, אֶפְשָׁר טַלִּית שֶׁל מִין אַחֵר חוּט אֶחָד שֶׁל תְּכֵלֶת פּוֹטְרָהּ, זוֹ שֶׁכֻּלָּהּ תְּכֵלֶת לֹא תִפְטֹר אֶת עַצְמָהּ? (תנחומא):\",4,0],[2,133,16,1,\"בני ראובן. דָּתָן וַאֲבִירָם וְאוֹן בֶּן פֶּלֶת:\",5,0],[2,133,16,3,\"רב לכם. הַרְבֵּה יוֹתֵר מִדַּאי לְקַחְתֶּם לְעַצְמְכֶם גְּדֻלָּה:\",1,0],[2,133,16,3,\"כלם קדשים. כֻּלָּם שָׁמְעוּ דְבָרִים בְּסִינַי מִפִּי הַגְּבוּרָה:\",2,0],[2,133,16,3,\"ומדוע תתנשאו. אִם לָקַחְתָּ אַתָּה מַלְכוּת, לֹא הָיָה לְךָ לִבְרֹר לְאָחִיךָ כְּהֻנָּה, לֹא אַתֶּם לְבַדְּכֶם שְׁמַעְתֶּם בְּסִינַי \\\"אָנֹכִי ה' אֱלֹהֶיךָ\\\", כָּל הָעֵדָה שָׁמְעוּ (שם):\",3,0],[2,133,16,4,\"ויפל על פניו. מִפְּנֵי הַמַּחֲלֹקֶת, שֶׁכְּבָר זֶה בְיָדָם סִרְחוֹן רְבִיעִי, חָטְאוּ בָעֵגֶל, \\\"וַיְחַל מֹשֶׁה\\\" (שמות ל\\\"ב), בַּמִּתְאוֹנְנִים, \\\"וַיִּתְפַּלֵּל מֹשֶׁה\\\" (במדבר י\\\"א), בַּמְּרַגְּלִים, \\\"וַיֹּאמֶר מֹשֶׁה אֶל ה' וְשָׁמְעוּ מִצְרַיִם\\\" (שם י\\\"ד), בְּמַחֲלָקְתּוֹ שֶׁל קֹרַח נִתְרַשְּׁלוּ יָדָיו, מָשָׁל לְבֶן מֶלֶךְ שֶׁסָּרַח עַל אָבִיו, וּפִיֵּס עָלָיו אוֹהֲבוֹ פַּעַם וּשְׁתַּיִם וְשָׁלֹשׁ, כְּשֶׁסָּרַח רְבִיעִית, נִתְרַשְּׁלוּ יְדֵי הָאוֹהֵב הַהוּא, אָמַר עַד מָתַי אַטְרִיחַ עַל הַמֶּלֶךְ? שֶׁמָּא לֹא יְקַבֵּל עוֹד מִמֶּנִּי (תנחומא):\",1,0],[2,133,16,5,\"בקר וידע וגו'. עַתָּה עֵת שִׁכְרוּת הוּא לָנוּ וְלֹא נָכוֹן לְהֵרָאוֹת לְפָנָיו, וְהוּא הָיָה מִתְכַּוֵּן לִדְחוֹת שֶׁמָּא יַחְזְרוּ בָהֶם (שם):\",1,0],[2,133,16,5,\"בקר וידע ה' את אשר לו. לַעֲבוֹדַת לְוִיָּה:\",2,0],[2,133,16,5,\"ואת הקדוש. לִכְהֻנָּה:\",3,0],[2,133,16,5,\"והקריב. אוֹתָם אליו; וְהַתַּרְגּוּם מוֹכִיחַ כֵּן \\\"וִיקָרֵב לָקֳדָמוֹהִי\\\", \\\"יְקָרֵב לְשִׁמּוּשֵׁיהּ\\\"; וּמִ\\\"אַ בקר, אָ\\\"ל מֹשֶׁה, גְּבוּלוֹת חָלַק הַקָּבָּ\\\"ה בְּעוֹלָמוֹ, יְכוֹלִים אַתֶּם לַהֲפֹךְ בֹּקֶר לְעֶרֶב? כֵּן תּוּכְלוּ לְבַטֵּל אֶת זוֹ שֶׁנֶּאֱמַר \\\"וַיְהִי עֶרֶב וַיְהִי בֹקֶר וַיַּבְדֵּל\\\" (בראשית א'), כָּךְ \\\"וַיִּבָּדֵל אַהֲרֹן לְהַקְדִּישׁוֹ\\\" וְגוֹ' (דהי\\\"א כ\\\"ג):\",4,0],[2,133,16,6,\"זאת עשו קחו לכם מחתות. מָה רָאָה לוֹמַר לָהֶם כָּךְ? אָמַר לָהֶם, בְּדַרְכֵי הַגּוֹיִם יֵשׁ נִימוּסִים הַרְבֵּה וְכוּמָרִים הַרְבֵּה וְכֻלָם (אֵין) מִתְקַבְּצִים בְּבַיִת אֶחָד, אָנוּ אֵין לָנוּ אֶלָּא ה' אֶחָד, אָרוֹן אֶחָד, וְתוֹרָה אַחַת וּמִזְבֵּחַ אֶחָד וְכֹהֵן גָּדוֹל אֶחָד, וְאַתֶּם ר\\\"ן אִישׁ מְבַקְּשִׁים כְּהֻנָּה גְדוֹלָה, אַף אֲנִי רוֹצֶה בְכָךְ, הֵא לָכֶם תַּשְׁמִישׁ חָבִיב מִכֹּל, הִיא הַקְּטֹרֶת הַחֲבִיבָה מִכָּל הַקָּרְבָּנוֹת, וְסַם הַמָּוֶת נִתַּן בְּתוֹכוֹ, שֶׁבּוֹ נִשְׂרְפוּ נָדָב וַאֲבִיהוּ, לְפִיכָךְ הִתְרָה בָהֶם והיה האיש אשר יבחר ה' הוא הקדש — כְּבָר הוּא בִקְדֻשָּׁתוֹ, וְכִי אֵין אָנוּ יוֹדְעִים שֶׁמִּי שֶׁיִּבְחַר הוּא הַקָּדוֹשׁ? אֶלָּא אָמַר לָהֶם מֹשֶׁה, הֲרֵינִי אוֹמֵר לָכֶם, שֶׁלֹּא תִּתְחַיְּבוּ, מִי שֶׁיִּבְחַר בוֹ יֵצֵא חַי וְכֻלְּכֶם אוֹבְדִין (תנחומא):\",1,0],[2,133,16,6,\"מחתות. כֵּלִים שֶׁחוֹתִין בָּהֶם גֶּחָלִים וְיֵשׁ לָהֶם בֵּית יָד:\",2,0],[2,133,16,7,\"רב לכם בני לוי. דָּבָר גָּדוֹל אָמַרְתִּי לָכֶם; וְלֹא טִפְּשִׁים הָיוּ, שֶׁכָּךְ הִתְרָה בָהֶם וְקִבְּלוּ עֲלֵיהֶם לְקָרֵב? הֵם חָטְאוּ עַל נַפְשׁוֹתָם, שֶׁנֶּאֱמַר \\\"אֵת מַחְתּוֹת הַחַטָּאִים הָאֵלֶּה בְּנַפְשֹׁתָם\\\" (במדבר י״ז:ג׳), וְקֹרַח שֶׁפִּקֵּחַ הָיָה מָה רָאָה לִשְׁטוּת זֶה? עֵינוֹ הִטְעַתּוּ, רָאָה שַׁלְשֶׁלֶת גְּדוֹלָה יוֹצְאָה מִמֶּנּוּ — שְׁמוּאֵל שֶׁשָּׁקוּל כְּנֶגֶד מֹשֶׁה וְאַהֲרֹן — אָמַר בִּשְׁבִילוֹ אֲנִי נִמְלָט, וְכ\\\"ד מִשְׁמָרוֹת עוֹמְדוֹת לִבְנֵי בָנָיו, כֻּלָּם מִתְנַבְּאִים בְּרוּחַ הַקֹּדֶשׁ, שֶׁנֶּאֱמַר \\\"כָּל אֵלֶּה בָנִים לְהֵימָן\\\" (דברי הימים א כ\\\"ה ה'), אָמַר אֶפְשָׁר כָּל הַגְּדֻלָּה הַזֹּאת עֲתִידָה לַעֲמֹד מִמֶּנִּי וַאֲנִי אֶדּוֹם? לְכָךְ נִשְׁתַּתֵּף לָבֹא לְאוֹתָהּ חֲזָקָה, שֶׁשָּׁמַע מִפִּי מֹשֶׁה שֶׁכֻּלָּם אוֹבְדִים וְאֶחָד נִמְלָט, \\\"אֲשֶׁר יִבְחַר ה' הוּא הַקָּדוֹשׁ\\\" — טָעָה וְתָלָה בְעַצְמוֹ, וְלֹא רָאָה יָפֶה, לְפִי שֶׁבָּנָיו עָשׂוּ תְשׁוּבָה, וּמֹשֶׁה הָיָה רוֹאֶה. — תַּנְחוּמָא:\",1,0],[2,133,16,7,\"רב לכם. דָּבָר גָּדוֹל נְטַלְתֶּם בְּעַצְמְכֶם לַחֲלֹק עַל הַקָּבָּ\\\"ה:\",2,0],[2,133,16,8,\"ויאמר משה אל קרח שמעו נא בני לוי. הִתְחִיל לְדַבֵּר עִמּוֹ בִּדְבָרִים רַכִּים, כֵּיוָן שֶׁרָאָהוּ קְשֵׁה עֹרֶף, אָמַר עַד שֶׁלֹּא יִשְׁתַּתְּפוּ שְׁאָר הַשְּׁבָטִים וְיֹאבְדוּ עִמּוֹ, אֲדַבֵּר גַּם אֶל כֻּלָּם, הִתְחִיל לְזָרֵז בָּהֶם \\\"שִׁמְעוּ נָא בְּנֵי לֵוִי\\\" (תנחומא):\",1,0],[2,133,16,9,\"ולעמד לפני העדה. לָשִׁיר עַל הַדּוּכָן:\",1,0],[2,133,16,10,\"ויקרב אתך. לְאוֹתוֹ שֵׁרוּת שֶׁהִרְחִיק מִמֶּנּוּ שְׁאָר עֲדַת יִשְֹרָאֵל:\",1,0],[2,133,16,11,\"לכן. בִּשְׁבִיל כָּךְ אתה וכל עדתך הנעדים אִתְּךָ עַל ה', כִּי בְשְׁלִיחוּתוֹ עָשִׂיתִי לָתֵת כְּהֻנָּה לְאַהֲרֹן, וְלֹא לָנוּ הוּא הַמַּחֲלֹקֶת הַזֶּה (שם):\",1,0],[2,133,16,12,\"וישלח משה וגו'. מִכָּאן שֶׁאֵין מַחֲזִיקִין בְּמַחֲלֹקֶת, שֶׁהָיָה מֹשֶׁה מְחַזֵּר אַחֲרֵיהֶם לְהַשְׁלִימָם בְּדִבְרֵי שָׁלוֹם (סנהדרין ק\\\"י):\",1,0],[2,133,16,12,\"לא נעלה. פִּיהֶם הִכְשִׁילָם, שֶׁאֵין לָהֶם אֶלָּא יְרִידָה:\",2,0],[2,133,16,14,\"ותתן לנו. הַדָּבָר מוּסָב עַל \\\"לֹא\\\" הָאָמוּר לְמַעְלָה, כְּלוֹמַר לֹא הֲבִיאוֹתָנוּ וְלֹא נָתַתָּ לָנוּ נַחֲלַת שָֹדֶה וָכֶרֶם; אָמַרְתָּ לָנוּ \\\"אַעֲלֶה אֶתְכֶם מֵעֳנִי מִצְרַיִם אֶל אֶרֶץ טוֹבָה\\\" וְגוֹ' (שמות ג'), מִשָּׁם הוֹצֵאתָנוּ, וְלֹא אֶל אֶרֶץ זָבָת חָלָב וּדְבַשׁ הֲבִיאֹתָנוּ, אֶלָּא גָּזַרְתָּ עָלֵינוּ לַהֲמִיתֵנוּ בַּמִּדְבָּר, שֶׁאָמַרְתָּ לָנוּ \\\"בַּמִּדְבָּר הַזֶּה יִפְּלוּ פִגְרֵיכֶם\\\" (במדבר י\\\"ד):\",1,0],[2,133,16,14,\"העיני האנשים ההם תנקר וגו'. אֲפִלּוּ אַתָּה שׁוֹלֵחַ לְנַקֵּר אֶת עֵינֵינוּ אִם לֹא נַעֲלֶה אֵלֶיךָ, לֹא נַעֲלֶה:\",2,0],[2,133,16,14,\"האנשים ההם. כְּאָדָם הַתּוֹלֶה קִלְלָתוֹ בַּחֲבֵרוֹ:\",3,0],[2,133,16,15,\"ויחר למשה מאד. נִצְטַעֵר עַד לִמְאֹד:\",1,0],[2,133,16,15,\"אל תפן אל מנחתם. לְפִי פְשׁוּטוֹ הַקְּטֹרֶת שֶׁהֵם מַקְרִיבִין לְפָנֶיךָ מָחָר אַל תֵּפֶן אֲלֵיהֶם; וּמִדְרָשׁוֹ: אָמַר, יוֹדֵעַ אֲנִי שֶׁיֵּשׁ לָהֶם חֵלֶק בִתְמִידֵי צִבּוּר, אַף חֶלְקָם לֹא יְקֻבַּל לְפָנֶיךָ לְרָצוֹן, תַּנִּיחֶנּוּ הָאֵשׁ וְלֹא תֹאכְלֶנּוּ (תנחומא):\",2,0],[2,133,16,15,\"לא חמור אחד מהם נשאתי. לֹא חֲמוֹרוֹ שֶׁל אֶחָד מֵהֶם נָטַלְתִּי. אֲפִלּוּ כְּשֶׁהָלַכְתִּי מִמִּדְיָן לְמִצְרַיִם וְהִרְכַּבְתִּי אֶת אִשְׁתִּי וְאֶת בָּנַי עַל הַחֲמוֹר, וְהָיָה לִי לִטֹּל אוֹתוֹ הַחֲמוֹר מִשֶּׁלָּהֶם, לֹא נָטַלְתִּי אֶלָּא מִשֶּׁלִּי; וְתַ\\\"אֻ \\\"שְׁחָרִית\\\", לְשׁוֹן אֲרַמִּי כָּךְ נִקְרֵאת אַנְגַּרְיָא שֶׁל מֶלֶךְ \\\"שַׁחֲוָר\\\":\",3,0],[2,133,16,16,\"והם. עֲדָתְךָ:\",1,0],[2,133,16,17,\"והקרבתם איש מחתתו. הַחֲמִשִּׁים וּמָאתַיִם אִישׁ שֶׁבָּכֶם:\",1,0],[2,133,16,19,\"ויקהל עליהם קרח. בְּדִבְרֵי לֵצָנוּת, כָּל הַלַּיְלָה הַהוּא הָלַךְ אֵצֶל הַשְּׁבָטִים וּפִתָּה אוֹתָם — \\\"כִּסְבוּרִין אַתֶּם שֶׁעָלַי לְבַדִּי אֲנִי מַקְפִּיד? אֵינִי מַקְפִּיד אֶלָּא בִּשְׁבִיל כֻּלְּכֶם, אֵלּוּ בָאִין וְנוֹטְלִין כָּל הַגְּדֻלּוֹת, לוֹ הַמַּלְכוּת וּלְאָחִיו הַכְּהֻנָּה\\\" עַד שֶׁנִּתְפַּתּוּ כֻלָּם (שם):\",1,0],[2,133,16,19,\"וירא כבוד ה'. בָּא בְּעַמּוּד עָנָן:\",2,0],[2,133,16,22,\"אל אלהי הרוחת. יוֹדֵעַ מַחֲשָׁבוֹת; אֵין מִדָּתְךָ כְּמִדַּת בָּשָׂר וָדָם, מֶלֶךְ בָּשָׂר וָדָם שֶׁסָּרְחָה עָלָיו מִקְצָת מְדִינָה, אֵינוֹ יוֹדֵעַ מִי הַחוֹטֵא, לְפִיכָךְ כְּשֶׁהוּא כוֹעֵס נִפְרָע מִכֻּלָּם, אֲבָל אַתָּה, לְפָנֶיךָ גְלוּיוֹת כָּל הַמַּחֲשָׁבוֹת וְיוֹדֵעַ אַתָּה מִי הַחוֹטֵא (שם):\",1,0],[2,133,16,22,\"האיש אחד. הוּא הַחוֹטֵא וְאַתָּה עַל כָּל הָעֵדָה תִּקְצֹף; אָמַר הַקָּבָּ\\\"ה, יָפֶה אֲמַרְתֶּם, אֲנִי יוֹדֵעַ וּמוֹדִיעַ מִי חָטָא וּמִי לֹא חָטָא (שם):\",2,0],[2,133,16,24,\"העלו. כְּתַרְגּוּמוֹ, הִסְתַּלְּקוּ מִסְּבִיבוֹת מִשְׁכַּן קֹרַח:\",1,0],[2,133,16,25,\"ויקם משה. כְּסָבוּר שֶׁיִּשְּׂאוּ לוֹ פָנִים וְלֹא עָשׂוּ:\",1,0],[2,133,16,27,\"יצאו נצבים. בְּקוֹמָה זְקוּפָה — לְחָרֵף וּלְגַדֵּף, כְּמוֹ (שמואל א י\\\"ז) \\\"וַיִּתְיַצֵּב אַרְבָּעִים יוֹם\\\" דְּגָלְיָת (תנחומא):\",1,0],[2,133,16,27,\"ונשיהם ובניהם וטפם. בֹּא וּרְאֵה כַּמָּה קָשָׁה הַמַּחֲלֹקֶת, שֶׁהֲרֵי בֵית דִּין שֶׁל מַטָּה אֵין עוֹנְשִׁין אֶלָּא עַד שֶׁיָּבִיא שְׁתֵּי שְׂעָרוֹת, וּבֵית דִּין שֶׁל מַעְלָה עַד עֶשְׂרִים שָׁנָה, וְכָאן אָבְדוּ אַף יוֹנְקֵי שָׁדַיִם (שם):\",2,0],[2,133,16,28,\"לעשות את כל המעשים האלה. שֶׁעָשִׂיתִי עַל פִּי הַדִּבּוּר, לָתֵת לְאַהֲרֹן כְּהֻנָּה גְדוֹלָה וּבָנָיו סְגָנֵי כְהֻנָּה, וֶאֱלִיצָפָן נְשִׂיא הַקְּהָתִי:\",1,0],[2,133,16,29,\"לא ה' שלחני. אֶלָּא אֲנִי עָשִׂיתִי הַכֹּל מִדַּעְתִּי, וּבְדִין הוּא חוֹלֵק עָלַי:\",1,0],[2,133,16,30,\"ואם בריאה. חֲדָשָׁה:\",1,0],[2,133,16,30,\"יברא ה'. לְהָמִית אוֹתָם בְּמִיתָה שֶׁלֹּא מֵת בָּהּ אָדָם עַד הֵנָּה, וּמַה הִיא הַבְּרִיאָה?\",2,0],[2,133,16,30,\"ופצתה האדמה את פיה וְתִבְלָעֵם, אָז וידעתם כי נאצו הֵם אֶת הַקָּבָּ\\\"ה, וַאֲנִי מִפִּי הַגְּבוּרָה אָמַרְתִּי; וְרַבּוֹתֵינוּ פֵרְשׁוּ: וְאִם בְּרִיאָה פֶה לָאָרֶץ מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית מוּטָב, וְאִם לָאו יִבְרָא ה' (סנהדרין ק\\\"י):\",3,0],[2,133,16,34,\"נסו לקלם. בִּשְׁבִיל הַקּוֹל הַיּוֹצֵא עַל בְּלִיעָתָן:\",1,0],[2,133,17,2,\"ואת האש. שֶׁבְּתוֹךְ הַמַּחְתּוֹת:\",1,0],[2,133,17,2,\"זרה הלאה. לָאָרֶץ מֵעַל הַמַּחְתּוֹת:\",2,0],[2,133,17,2,\"כי קדשו. הַמַּחְתּוֹת וַאֲסוּרִין בַּהֲנָאָה, שֶׁהֲרֵי עֲשָׂאוּם כְּלֵי שָׁרֵת:\",3,0],[2,133,17,3,\"החטאים האלה בנפשתם. שֶׁנַּעֲשׂוּ פוֹשְׁעִים בְּנַפְשׁוֹתָם, שֶׁנֶּחְלְקוּ עַל הַקָּבָּ\\\"ה:\",1,0],[2,133,17,3,\"רקעי. רְדוּדִין:\",2,0],[2,133,17,3,\"פחים. טַסִּים מְרֻדָּדִין, טינדי\\\"ש בלעז:\",3,0],[2,133,17,3,\"צפוי למזבח. לְמִזְבַּח הַנְּחֹשֶׁת:\",4,0],[2,133,17,3,\"ויהיו לאות. לְזִכָּרוֹן — שֶׁיֹּאמְרוּ, אֵלּוּ הָיוּ מֵאוֹתָן שֶׁנֶּחְלְקוּ עַל הַכְּהֻנָּה וְנִשְׂרְפוּ:\",5,0],[2,133,17,4,\"וירקעום. איטינ\\\"דריש בְּלַעַז:\",1,0],[2,133,17,5,\"ולא יהיה כקרח. כְּדֵי שֶׁלֹּא יִהְיֶה כְקֹרַח:\",1,0],[2,133,17,5,\"כאשר דבר ה' ביד משה לו. כְּמוֹ עָלָיו — עַל אַהֲרֹן דִּבֵּר אֶל מֹשֶׁה שֶׁיִּהְיוּ הוּא וּבָנָיו כֹּהֲנִים, לְפִיכָךְ \\\"לֹא יִקְרַב אִישׁ זָר אֲשֶׁר לֹא מִזֶּרַע אַהֲרֹן\\\" וְגוֹ'; וְכֵן כָּל לִי וְלוֹ וְלָהֶם הַסְּמוּכִים אֵצֶל דִּבּוּר, פִּתְרוֹנָם כְּמוֹ עַל. וּמִדְרָשׁוֹ — עַל קֹרַח, וּמַהוּ \\\"בְיַד מֹשֶׁה\\\" וְלֹא כָתַב \\\"אֶל מֹשֶׁה\\\"? רֶמֶז לַחוֹלְקִים עַל הַכְּהֻנָּה שֶׁלּוֹקִין בְּצָרַעַת כְּמוֹ שֶׁלָּקָה מֹשֶׁה בְּיָדוֹ, שֶׁנֶּאֱמַר \\\"וַיּוֹצִאָהּ וְהִנֵּה יָדוֹ מְצֹרַעַת כַּשָּׁלֶג\\\" (שמות ד'), וְעַל כֵּן לָקָה עֻזִּיָּהוּ בְּצָרַעַת (דברי הימים ב' כ\\\"ו):\",2,0],[2,133,17,11,\"וכפר עליהם. רָז זֶה מָסַר לוֹ מַלְאַךְ הַמָּוֶת כְּשֶׁעָלָה לָרָקִיעַ, שֶׁהַקְּטֹרֶת עוֹצֵר הַמַּגֵּפָה, כִּדְאִיתָא בְמַסֶּכֶת שַׁבָּת (דף פ\\\"ט):\",1,0],[2,133,17,13,\"ויעמד בין המתים וגו'. אָחַז אֶת הַמַּלְאָךְ וְהֶעֱמִידוֹ עַל כָּרְחוֹ, אָמַר לוֹ הַמַּלְאָךְ, הַנַּח לִי לַעֲשׂוֹת שְׁלִיחוּתִי, אָמַר לוֹ מֹשֶׁה צִוַּנִי לְעַכֵּב עַל יָדְךָ, אָמַר לוֹ אֲנִי שְׁלוּחוֹ שֶׁל מָקוֹם וְאַתָּה שְׁלוּחוֹ שֶׁל מֹשֶׁה, אָמַר לוֹ אֵין מֹשֶׁה אוֹמֵר כְּלוּם מִלִּבּוֹ אֶלָּא מִפִּי הַגְּבוּרָה, אִם אֵין אַתָּה מַאֲמִין, הֲרֵי הַקָּבָּ\\\"ה וּמֹשֶׁה אֶל פֶּתַח אֹהֶל מוֹעֵד, בֹּא עִמִּי וּשְׁאַל, וְזֶהוּ שֶׁנֶּאֱמַר וישב אהרן אל משה; דָּ\\\"אַ, לָמָּה בַקְּטֹרֶת? לְפִי שֶׁהָיוּ יִשְׂרָאֵל מְלִיזִים וּמְרַנְּנִים אַחַר הַקְּטֹרֶת לוֹמַר סַם הַמָּוֶת הוּא — עַל יָדוֹ מֵתוּ נָדָב וַאֲבִיהוּא, עַל יָדוֹ נִשְׂרְפוּ חֲמִשִּׁים וּמָאתַיִם אִישׁ — אָמַר הַקָּבָּ\\\"ה, תִּרְאוּ שֶׁעוֹצֵר מַגֵּפָה הוּא וְהַחֵטְא הוּא הַמֵּמִית (מכילתא שמות י\\\"ז):\",1,0],[2,133,17,18,\"כי מטה אחד. אַעַ\\\"פִּ שֶׁחִלַּקְתִּים לִשְׁתֵּי מִשְׁפָּחוֹת, מִשְׁפַּחַת כְּהֻנָּה לְבַד וּלְוִיָּה לְבַד, מִכָּל מָקוֹם שֵׁבֶט אֶחָד הוּא:\",1,0],[2,133,17,20,\"והשכתי. כְּמוֹ \\\"וַיָּשֹׁכּוּ הַמָּיִם\\\" (בראשית ח'), \\\"וַחֲמַת הַמֶּלֶךְ שָׁכָכָה\\\" (אסתר ז'):\",1,0],[2,133,17,21,\"בתוך מטותם. הִנִּיח בָּאֶמְצַע, שֶׁלֹּא יֹאמְרוּ, מִפְּנֵי שֶׁהִנִּיחוֹ בְצַד שְׁכִינָה פָּרַח (תנחומא אחרי מות):\",1,0],[2,133,17,23,\"ויצא פרח. כְּמַשְׁמָעוֹ:\",1,0],[2,133,17,23,\"ציץ. הוּא חֲנָטַת הַפְּרִי כְּשֶׁהַפֶּרַח נוֹפֵל:\",2,0],[2,133,17,23,\"ויגמל שקדים. כְּשֶׁהֻכַּר הַפְּרִי הֻכַּר שֶׁהֵן שְׁקֵדִים, לְשׁוֹן \\\"וַיִּגְדַּל הַיֶּלֶד וַיִּגָּמַל\\\" (בראשית כ\\\"א), וְלָשׁוֹן זֶה מָצוּי בִּפְרִי הָאִילָן, כְּמוֹ \\\"וּבֹסֶר גֹּמֵל יִהְיֶה נִצָּה\\\" (ישעיהו י\\\"ח), וְלָמָּה שְׁקֵדִים? הוּא הַפְּרִי הַמְמַהֵר לְהַפְרִיחַ מִכָּל הַפֵּרוֹת, אַף הַמְעוֹרֵר עַל הַכְּהֻנָּה פֻּרְעֲנוּתוֹ מְמַהֶרֶת לָבֹא, כְּמוֹ שֶׁמָּצִינוּ בְעֻזִּיָּהוּ \\\"וְהַצָּרַעַת זָרְחָה בְמִצְחוֹ\\\" (דברי הימים ב' כ\\\"ו); תַּרְגּוּמוֹ \\\"וְכָפִית שִׁגְדִּין\\\", כְּמִין אֶשְׁכּוֹל שְׁקֵדִים יַחַד כְּפוּתִים זֶה עַל זֶה:\",3,0],[2,133,17,25,\"למשמרת לאות. לְזִכָּרוֹן שֶׁבָּחַרְתִּי בְּאַהֲרֹן לְכֹהֵן וְלֹא יִלּוֹנוּ עוֹד עַל הַכְּהֻנָּה:\",1,0],[2,133,17,25,\"ותכל תלונתם. כְּמוֹ וּתְכַלֶּה תְּלֻנּוֹתָם; לָשׁוֹן זֶה שֵׁם מִפְעָל יָחִיד לְשׁוֹן נְקֵבָה, כְּמוֹ תְלֻנָּתָם, מרמור\\\"יש בלעז; וְיֵשׁ חִלּוּק בֵּין תְּלֻנּוֹתָם לִתְלֻנָּתָם, תְּלֻנָּתָם תְּלֻנָּה אַחַת, תְּלֻנּוֹתָם שֵׁם דָּבָר בִּלְשׁוֹן יָחִיד וַאֲפִלּוּ הֵם תְּלֻנּוֹת הַרְבֵּה:\",2,0],[2,133,17,28,\"כל הקרב הקרב וגו'. אֵין אָנוּ יְכוֹלִין לִהְיוֹת זְהִירִין בְּכָךְ, כֻּלָּנוּ רַשָּׁאִין לְהִכָּנֵס לַחֲצַר אֹהֶל מוֹעֵד, וְאֶחָד שֶׁיַּקְרִיב עַצְמוֹ יוֹתֵר מֵחֲבֵרוֹ וְיִכָּנֵס לְתוֹךְ אֹהֶל מוֹעֵד יָמוּת:\",1,0],[2,133,17,28,\"האם תמנו לגוע. שֶׁמָּא הֻפְקַרְנוּ לְמִיתָה?:\",2,0],[2,133,18,1,\"ויאמר ה' אל אהרן. לְמֹשֶׁה אָמַר שֶׁיֹּאמַר לְאַהֲרֹן, לְהַזְהִירוֹ עַל תַּקָּנַת יִשְׂרָאֵל שֶׁלֹּא יִכָּנְסוּ לַמִּקְדָּשׁ:\",1,0],[2,133,18,1,\"אתה ובניך ובית אביך. הֵם בְּנֵי קְהָת אֲבִי עַמְרָם:\",2,0],[2,133,18,1,\"תשאו את עון המקדש. עֲלֵיכֶם אֲנִי מַטִּיל עֹנֶשׁ הַזָּרִים שֶׁיֶּחֶטְאוּ בְעִסְקֵי הַדְּבָרִים הַמְקֻדָּשִׁים הַמְּסוּרִים לָכֶם, הוּא הָאֹהֶל וְהָאָרוֹן וְהַשֻּׁלְחָן וּכְלֵי הַקֹּדֶשׁ — אַתֶּם תֵּשְׁבוּ וְתַזְהִירוּ עַל כָּל זָר הַבָּא לִגַּע:\",3,0],[2,133,18,1,\"ואתה ובניך. הַכֹּהֲנִים:\",4,0],[2,133,18,1,\"תשאו את עון כהנתכם. שֶׁאֵינָהּ מְסוּרָה לַלְוִיִּם, וְתַזְהִירוּ הַלְוִיִּם הַשּׁוֹגְגִים שֶׁלֹּא יִגְּעוּ אֲלֵיכֶם בַּעֲבוֹדַתְכֶם:\",5,0],[2,133,18,2,\"וגם אחיך. בְּנֵי גֵרְשׁוֹן וּבְנֵי מְרָרִי:\",1,0],[2,133,18,2,\"וילוו. וְיִתְחַבְּרוּ אֲלֵיכֶם, לְהַזְהִיר גַּם אֶת הַזָּרִים מִלִּקְרַב אֲלֵיהֶם:\",2,0],[2,133,18,2,\"וישרתוך. בִּשְׁמִירַת הַשְּׁעָרִים וּלְמַנּוֹת מֵהֶם גִּזְבָּרִין וַאֲמַרְכָּלִין (ספרי):\",3,0],[2,133,18,4,\"וזר לא יקרב אליכם. אֶתְכֶם אֲנִי מַזְהִיר עַל כָּךְ:\",1,0],[2,133,18,5,\"ולא יהיה עוד קצף. כְּמוֹ שֶׁהָיָה כְבָר, שֶׁנֶּאֱמַר (במדבר י\\\"ז) \\\"כִּי יָצָא הַקֶּצֶף\\\" (ספרי):\",1,0],[2,133,18,6,\"לכם מתנה נתנים. יָכוֹל לַעֲבוֹדַתְכֶם שֶׁל הֶדְיוֹט, תַּ\\\"ל \\\"לַה'\\\", כְּמוֹ שֶׁמְּפֹרָשׁ לְמַעְלָה, לִשְׁמֹר מִשְׁמֶרֶת גִּזְבָּרִין וַאֲמַרְכָּלִין:\",1,0],[2,133,18,7,\"עבדת מתנה. בְּמַתָּנָה נְתַתִּיהָ לָכֶם:\",1,0],[2,133,18,8,\"ואני הנה נתתי לך. בְּשִׂמְחָה, לְשׁוֹן שִׂמְחָה הוּא זֶה, כְּמוֹ \\\"הִנֵּה הוּא יֹצֵא לִקְרָאתֶךָ וְרָאֲךָ וְשָׂמַח בְּלִבּוֹ\\\" (שמות ד'); מָשָׁל לְמֶלֶךְ שֶׁנָּתַן שָׂדֶה לְאוֹהֲבוֹ, וְלֹא כָתַב וְלֹא חָתַם וְלֹא הֶעֱלָה בְעַרְכָּאִין, בָּא אֶחָד וְעִרְעֵר עַל הַשָּׂדֶה, אָמַר לוֹ הַמֶּלֶךְ כָּל מִי שֶׁיִּרְצֶה יָבֹא וִיעַרְעֵר לְנֶגְדְּךָ, הֲרֵינִי כוֹתֵב וְחוֹתֵם לְךָ וּמַעֲלֶה בְעַרְכָּאִין, אַף כָּאן, לְפִי שֶׁבָּא קֹרַח וְעִרְעֵר כְּנֶגֶד אַהֲרֹן עַל הַכְּהֻנָּה, בָּא הַכָּתוּב וְנָתַן לוֹ כ\\\"ד מַתְּנוֹת כְּהֻנָּה בִּבְרִית מֶלַח עוֹלָם, וְלְכָךְ נִסְמְכָה פָרָשָׁה זוֹ לְכָאן (ספרי):\",1,0],[2,133,18,8,\"משמרת תרומתי. שֶׁאַתָּה צָרִיךְ לְשָׁמְרָן בְּטָהֳרָה:\",2,0],[2,133,18,8,\"למשחה. לִגְדֻלָּה (שם):\",3,0],[2,133,18,9,\"מן האש. לְאַחַר הַקְטָרַת הָאִשִּׁים:\",1,0],[2,133,18,9,\"כל קרבנם. כְּגוֹן זִבְחֵי שַׁלְמֵי צִבּוּר:\",2,0],[2,133,18,9,\"מנחתם חטאתם ואשמתם. כְּמַשְׁמָעוֹ:\",3,0],[2,133,18,9,\"אשר ישיבו לי. זֶה גֶּזֶל הַגֵּר (שם; זבחים מ\\\"ד):\",4,0],[2,133,18,10,\"בקדש הקדשים תאכלנו וגו'. לִמֵּד עַל קָדְשֵׁי קֳדָשִׁים שֶׁאֵין נֶאֱכָלִין אֶלָּא בָּעֲזָרָה לְזִכְרֵי כְהֻנָּה:\",1,0],[2,133,18,11,\"תרומת מתנם. הַמּוּרָם מִן הַתּוֹדָה וּמֵהַשְּׁלָמִים וּמֵאֵיל נָזִיר:\",1,0],[2,133,18,11,\"לכל תנופת. שֶׁהֲרֵי אֵלּוּ טְעוּנִין תְּנוּפָה:\",2,0],[2,133,18,11,\"כל טהור. וְלֹא טְמֵאִים; דָּ\\\"אַ: כָּל טָהוֹר לְרַבּוֹת אִשְׁתּוֹ:\",3,0],[2,133,18,12,\"ראשיתם. הִיא תְּרוּמָה גְדוֹלָה:\",1,0],[2,133,18,18,\"כחזה התנופה וכשוק הימין. שֶׁל שְׁלָמִים שֶׁנֶּאֱכָלִין לַכֹּהֲנִים וְלִנְשֵׁיהֶם לִבְנֵיהֶם וּלְעַבְדֵיהֶם לִשְׁנֵי יָמִים וְלַיְלָה אֶחָד, אַף הַבְּכוֹר נֶאֱכָל לִשְׁנֵי יָמִים וְלַיְלָה אֶחָד:\",1,0],[2,133,18,18,\"לך יהיה. בָּא רַבִּי עֲקִיבָא וְלִמֵּד, וְהוֹסִיף לְךָ הַכָּתוּב הֲוָיָה אַחֶרֶת, שֶׁלֹא תֹאמַר, כְּחָזֶה וְשׁוֹק שֶׁל תּוֹדָה שֶׁאֵינוֹ נֶאֱכָל אֶלָּא לְיוֹם וָלַיְלָה (זבחים נ\\\"ז):\",2,0],[2,133,18,19,\"כל תרומת הקדשים. מֵחִבָּתָהּ שֶל פָּרָשָׁה זוֹ כְּלָלָהּ בַּתְּחִלָּה וּכְלָלָהּ בַּסּוֹף וּפָרַט בָּאֶמְצַע (עי' ספרי):\",1,0],[2,133,18,19,\"ברית מלח עולם. כָּרַת בְּרִית עִם אַהֲרֹן בְּדָבָר הַבָּרִיא וּמִתְקַיֵּם וּמַבְרִיא אֶת אֲחֵרִים (שם):\",2,0],[2,133,18,19,\"ברית מלח. כַּבְּרִית הַכְּרוּתָה לַמֶּלַח שֶׁאֵינוֹ מַסְרִיחַ לְעוֹלָם:\",3,0],[2,133,18,20,\"וחלק לא יהיה לך בתוכם. אַף בַּבִּזָּה (שם):\",1,0],[2,133,18,23,\"והם. הַלְוִיִּם — יִשְׂאוּ עֲוֹנָם שֶׁל יִשְׂרָאֵל, שֶׁעֲלֵיהֶם לְהַזְהִיר הַזָּרִים מִגֶּשֶׁת אֲלֵיהֶם:\",1,0],[2,133,18,24,\"אשר ירימו לה' תרומה. הַכָּתוּב קְרָאוֹ תְּרוּמָה עַד שֶׁיַּפְרִישׁ מִמֶּנּוּ תְּרוּמַת מַעֲשֵׂר:\",1,0],[2,133,18,27,\"ונחשב לכם תרומתכם כדגן מן הגרן. תְּרוּמַת מַעֲשֵׂר שֶׁלָּכֶם אֲסוּרָה לְזָרִים וְלִטְמֵאִין, וְחַיָּבִין עָלֶיהָ מִיתָה וְחֹמֶשׁ כִּתְרוּמָה גְדוֹלָה שֶׁנִּקְרֵאת רֵאשִׁית דָּגָן מִן הַגֹּרֶן:\",1,0],[2,133,18,27,\"וכמלאה מן היקב. תְּרוּמַת תִּירוֹשׁ וְיִצְהָר הַנִּטֶּלֶת מִן הַיְקָבִים:\",2,0],[2,133,18,27,\"מלאה. לְשׁוֹן בִּשּׁוּל — תְּבוּאָה שֶׁנִּתְמַלֵּאת:\",3,0],[2,133,18,27,\"יקב. הוּא הַבּוֹר שֶׁלִּפְנֵי הַגַּת שֶׁהַיַּיִן יוֹרֵד לְתוֹכוֹ, וְכָל לְשׁוֹן יֶקֶב חֲפִירַת קַרְקַע הוּא, וְכֵן \\\"יִקְבֵי הַמֶּלֶךְ\\\" (זכריה י\\\"ד), הוּא יָם אוֹקְיָנוֹס, חֲפִירָה שֶׁחָפַר מַלְכּוֹ שֶׁל עוֹלָם:\",4,0],[2,133,18,28,\"כן תרימו גם אתם. כְּמוֹ שֶׁיִּשְׂרָאֵל מְרִימִים מִגָּרְנָם וּמִיִּקְבֵיהֶם, תָּרִימוּ גַּם אַתֶּם מִמַּעֲשֵׂר שֶׁלָּכֶם, כִּי הוּא נַחֲלַתְכֶם:\",1,0],[2,133,18,29,\"מכל מתנתיכם תרימו את כל תרומת ה'. בִּתְרוּמָה גְדוֹלָה הַכָּתוּב מְדַבֵּר, שֶׁאִם הִקְדִּים לֵוִי אֶת הַכֹּהֵן בַּכְּרִי וְקִבֵּל מַעְשְׂרוֹתָיו קֹדֶם שֶׁיִּטֹּל כֹּהֵן תְּרוּמָה גְדוֹלָה מִן הַכְּרִי, צָרִיךְ לְהַפְרִישׁ הַלֵּוִי מִן הַמַּעֲשֵׂר תְּחִלָּה אֶחָד מֵחֲמִשִּׁים לִתְרוּמָה גְדוֹלָה, וְיַחֲזֹר וְיַפְרִישׁ תְּרוּמַת מַעֲשֵׂר (ספרי):\",1,0],[2,133,18,30,\"בהרימכם את חלבו ממנו. לְאַחַר שֶׁתָּרִימוּ תְרוּמַת מַעֲשֵׂר מִמֶּנּוּ:\",1,0],[2,133,18,30,\"ונחשב הַמּוֹתָר לַלְוִיִּם חֻלִּין גְּמוּרִין:\",2,0],[2,133,18,30,\"כתבואת גרן לישראל, שֶׁלֹּא תֹאמַר הוֹאִיל וּקְרָאוֹ הַכָּתוּב תְּרוּמָה — שֶׁנֶּאֱמַר \\\"כִּי אֶת מַעְשַׂר בְּנֵי יִשְׂרָאֵל אֲשֶׁר יָרִימוּ לַה' תְּרוּמָה\\\" — יָכוֹל יְהֵא כֻלּוֹ אָסוּר, תַּ\\\"ל \\\"וְנֶחְשַׁב לַלְוִיִּם כִּתְבוּאַת גֹּרֶן\\\", מַה שֶּׁל יִשְׂרָאֵל חֻלִּין, אַף שֶׁל לֵוִי חֻלִּין (עי' ספרי):\",3,0],[2,133,18,31,\"בכל מקום. אֲפִלּוּ בְּבֵית הַקְּבָרוֹת (שם):\",1,0],[2,133,18,32,\"ולא תשאו עליו חטא וגו'. הָא אִם לֹא תָרִימוּ תִּשְׂאוּ חֵטְא:\",1,0],[2,133,18,32,\"ולא תמותו. הָא אִם תְּחַלְּלוּ תָּמוּתוּ:\",2,0],[2,133,19,2,\"זאת חקת התורה. לְפִי שֶׁהַשָּׂטָן וְאֻמּוֹת הָעוֹלָם מוֹנִין אֶת יִשְׂרָאֵל, לוֹמַר מַה הַמִּצְוָה הַזֹּאת וּמַה טַּעַם יֵשׁ בָּהּ? לְפִיכָךְ כָּתַב בָּהּ חֻקָּה — גְּזֵרָה הִיא מִלְּפָנַי, אֵין לְךָ רְשׁוּת לְהַרְהֵר אַחֲרֶיהָ (יומא ס\\\"ז):\",1,0],[2,133,19,2,\"ויקחו אליך. לְעוֹלָם הִיא נִקְרֵאת עַל שִׁמְךָ — פָּרָה שֶׁעָשָׂה מֹשֶׁה בַּמִּדְבָּר:\",2,0],[2,133,19,2,\"אדמה תמימה. שֶׁתְּהֵא תְמִימָה בְּאַדְמִימוּת, שֶׁאִם הָיוּ בָהּ שְׁתֵּי שְׂעָרוֹת שְׁחֹרוֹת פְּסוּלָה (פרה פ\\\"ב):\",3,0],[2,133,19,3,\"אלעזר. מִצְוָתָהּ בַּסְּגָן (ספרי):\",1,0],[2,133,19,3,\"אל מחוץ למחנה. חוּץ לְשָׁלוֹשׁ מַחֲנוֹת:\",2,0],[2,133,19,3,\"ושחט אתה לפניו. זָר שׁוֹחֵט וְאֶלְעָזָר רוֹאֶה (שם; יומא מ\\\"ב):\",3,0],[2,133,19,4,\"אל נכח פני אהל מועד. עוֹמֵד בְּמִזְרָחוֹ שֶׁל יְרוּשָׁלַיִם וּמִתְכַּוֵּן וְרוֹאֶה פִתְחוֹ שֶׁל הֵיכָל בִּשְׁעַת הַזָּאַת הַדָּם (ספרי; זבחים ק\\\"ה):\",1,0],[2,133,19,7,\"אל המחנה. לְמַחֲנֵה שְׁכִינָה, שֶׁאֵין טָמֵא מְשֻׁלָּח חוּץ לִשְׁתֵּי מַחֲנוֹת אֶלָּא זָב וּבַעַל קֶרִי וּמְצֹרָע (עי' פסחים ס\\\"ז):\",1,0],[2,133,19,7,\"וטמא הכהן עד הערב. סָרְסֵהוּ וְדָרְשֵׁהוּ — וְטָמֵא עַד הָעֶרֶב וְאַחַר יָבֹא אֶל הַמַּחֲנֶה:\",2,0],[2,133,19,9,\"והניח מחוץ למחנה. לִשְׁלֹשָׁה חֲלָקִים מְחַלְּקָהּ, אֶחָד נָתַן בְּהַר הַמִּשְׁחָה, וְאֶחָד מִתְחַלֵּק לְכָל הַמִּשְׁמָרוֹת, וְאֶחָד נָתַן בַּחֵיל (ספרי; פרה פ\\\"ג), זֶה שֶׁל מִשְׁמָרוֹת הָיָה חוּץ לָעֲזָרָה, לִטֹּל מִמֶּנּוּ בְּנֵי הָעֲיָרוֹת וְכָל הַצְּרִיכִין לִטָּהֵר, וְזֶה שֶׁבְּהַר הַמִּשְׁחָה כֹּהֲנִים גְּדוֹלִים לְפָרוֹת אֲחֵרוֹת מְקַדְּשִׁין הֵימֶנָּה, וְזֶה שֶׁבַּחֵיל נָתוּן לְמִשְׁמֶרֶת מִגְּזֵרַת הַכָּתוּב, שֶׁנֶּאֱמַר והיתה לעדת בני ישראל למשמרת:\",1,0],[2,133,19,9,\"למי נדה. לְמֵי הַזָּיָה, כְּמוֹ \\\"וַיַּדּוּ אֶבֶן בִּי\\\" (איכה ג'), \\\"לְיַדּוֹת אֶת קַרְנוֹת הַגּוֹיִם\\\" (זכריה ב'), לְשׁוֹן זְרִיקָה:\",2,0],[2,133,19,9,\"חטאת הוא. לְשׁוֹן חִטּוּי, כִּפְשׁוּטוֹ, וּלְפִי הִלְכוֹתָיו קְרָאָהּ הַכָּתוּב חַטָּאת, לוֹמַר שֶׁהִיא כְּקָדָשִׁים לֵאָסֵר בַּהֲנָאָה (עי' ספרי; מנחות נ\\\"א):\",3,0],[2,133,19,12,\"הוא יתחטא בו. בָּאֵפֶר הַזֶּה:\",1,0],[2,133,19,13,\"במת בנפש. וְאֵי זֶה מֵת? שֶׁל נֶפֶשׁ הָאָדָם, לְהוֹצִיא נֶפֶשׁ בְּהֵמָה שֶׁאֵין טֻמְאָתָהּ צְרִיכָה הַזָּאָה; דָּ\\\"אַ, בנפש זוֹ רְבִיעִית דָּם (חולין ע\\\"ב):\",1,0],[2,133,19,13,\"את משכן ה' טמא. אִם נִכְנַס לָעֲזָרָה אֲפִלּוּ בִטְבִילָה בְּלֹא הַזָּאַת שְׁלִישִׁי וּשְׁבִיעִי:\",2,0],[2,133,19,13,\"עוד טמאתו בו, אַף עַל פִּי שֶׁטָּבַל:\",3,0],[2,133,19,14,\"כל הבא אל האהל. בְּעוֹד שֶׁהַמֵּת בְּתוֹכוֹ:\",1,0],[2,133,19,15,\"וכל כלי פתוח. בִּכְלִי חֶרֶס הַכָּתוּב מְדַבֵּר, שֶׁאֵין מְקַבֵּל טֻמְאָה מִגַּבּוֹ אֶלָּא מִתּוֹכוֹ, לְפִיכָךְ אִם אֵין מְגוּפַת צְמִידָתוֹ פְּתוּלָה עָלָיו יָפֶה בְּחִבּוּר, טָמֵא הוּא, הָא אִם יֵשׁ צָמִיד פָּתִיל עָלָיו טָהוֹר (שם כ\\\"ה):\",1,0],[2,133,19,15,\"פתיל. לְשׁוֹן מְחֻבָּר בִּלְשׁוֹן עֲרָבִי, וְכֵן (בראשית ל') \\\"נַפְתּוּלֵי אֱלֹהִים נִפְתַּלְתִּי\\\" — נִתְחַבַּרְתִּי עִם אֲחוֹתִי:\",2,0],[2,133,19,16,\"על פני השדה. רַבּוֹתֵינוּ דָרְשׁוּ לְרַבּוֹת גּוֹלֵל וְדוֹפֵק (ספרי; חולין ע\\\"ב). וּפְשׁוּטוֹ — עַל פְּנֵי הַשָּׂדֶה, שֶׁאֵין שָׁם אֹהֶל, מְטַמֵּא הַמֵּת שָׁם בִּנְגִיעָה:\",1,0],[2,133,19,19,\"וחטאו ביום השביעי. הוּא גְמַר טָהֳרָתוֹ (עי' ספרי):\",1,0],[2,133,19,20,\"ואיש אשר יטמא וגו'. אִם נֶאֱמַר מִקְדָּשׁ לָמָּה נֶאֱמַר מִשְׁכָּן? כו' כִּדְאִיתָא בִשְׁבוּעוֹת (דף ט\\\"ז):\",1,0],[2,133,19,21,\"ומזה מי הנדה. רַבּוֹתֵינוּ אָמְרוּ שֶׁהַמַּזֶּה טָהוֹר, וְזֶה בָא לְלַמֵּד שֶׁהַנּוֹשֵׂא מֵי חַטָּאת טָמֵא טֻמְאָה חֲמוּרָה לְטַמֵּא בְגָדִים שֶׁעָלָיו, מַה שֶּׁאֵין כֵּן בַּנּוֹגֵעַ, וְזֶה שֶׁהוֹצִיא בִּלְשׁוֹן \\\"מַזֶּה\\\", לוֹמַר לְךָ שֶׁאֵינָן מְטַמְּאִין עַד שֶׁיְּהֵא בָהֶן שִׁעוּר הַזָּאָה (נדה ט'):\",1,0],[2,133,19,21,\"והנגע, יטמא. וְאֵין טָעוּן כִּבּוּס בְּגָדִים:\",2,0],[2,133,19,22,\"וכל אשר יגע בו הטמא. הַזֶּה שֶׁנִּטְמָא בְּמֵת, יטמא:\",1,0],[2,133,19,22,\"והנפש הנגעת בּוֹ: בִּטְמֵא מֵת:\",2,0],[2,133,19,22,\"תטמא עד הערב. כָּאן לָמַדְנוּ שֶׁהַמֵּת אֲבִי אֲבוֹת הַטֻּמְאָה, וְנוֹגֵעַ בּוֹ אַב הַטֻּמְאָה וּמְטַמֵּא אָדָם; זֶה פֵרוּשָׁהּ לְפִי מַשְׁמָעָהּ וְהִלְכוֹתֶיהָ. וּמִ\\\"אַ הֶעְתַּקְתִּי מִיסוֹדוֹ שֶׁל רַבִּי מֹשֶׁה הַדַּרְשָׁן וְזֶהוּ:\",3,0],[2,133,19,22,\"ויקחו אליך. מִשֶּׁלָּהֶם, כְּשֵׁם שֶׁהֵם פֵּרְקוּ נִזְמֵי הַזָּהָב לָעֵגֶל מִשֶּׁלָּהֶם, כָּךְ יָבִיאוּ זוֹ לְכַפָּרָה מִשֶּׁלָּהֶם:\",4,0],[2,133,19,22,\"פרה אדמה. מָשָׁל לְבֶן שִׁפְחָה שֶׁטִּנֵּף פָּלָטִין שֶׁל מֶלֶךְ, אָמְרוּ תָּבֹא אִמּוֹ וּתְקַנֵּחַ הַצּוֹאָה, כָּךְ תָּבֹא פָרָה וּתְכַפֵּר עַל הָעֵגֶל (תנחומא):\",5,0],[2,133,19,22,\"אדמה. עַל שֵׁם \\\"אִם יַאְדִּימוּ כַתּוֹלָע\\\" (ישעיהו א'), שֶׁהַחֵטְא קָרוּי אָדֹם:\",6,0],[2,133,19,22,\"תמימה. עַל שֵׁם יִשְׂרָאֵל שֶׁהָיוּ תְמִימִים, וְנַעֲשׂוּ בוֹ בַּעֲלֵי מוּמִין, תָּבֹא זוֹ וּתְכַפֵּר עֲלֵיהֶם וְיַחְזְרוּ לְתַמּוּתָם:\",7,0],[2,133,19,22,\"לא עלה עליה על. כְּשֵׁם שֶׁפָּרְקוּ מֵעֲלֵיהֶם עֹל שָׁמַיִם:\",8,0],[2,133,19,22,\"אל אלעזר הכהן. כְּשֵׁם שֶׁנִּקְהֲלוּ עַל אַהֲרֹן, שֶׁהוּא כֹּהֵן, לַעֲשׂוֹת הָעֵגֶל; וּלְפִי שֶׁאַהֲרֹן עָשָׂה אֶת הָעֵגֶל לֹא נִתְּנָה לוֹ עֲבוֹדָה זוֹ עַל יָדוֹ, שֶׁאֵין קַטֵּיגוֹר נַעֲשֶׂה סַנֵּיגוֹר:\",9,0],[2,133,19,22,\"ושרף את הפרה. כְּשֵׁם שֶׁנִּשְׂרַף הָעֵגֶל:\",10,0],[2,133,19,22,\"עץ ארז ואזוב ושני תולעת. שְׁלֹשָׁה מִינִין הַלָּלוּ כְּנֶגֶד שְׁלֹשֶׁת אַלְפֵי אִישׁ שֶׁנָּפְלוּ בָעֵגֶל, וְאֶרֶז הוּא הַגָּבוֹהַּ מִכָּל הָאִילָנוֹת וְאֵזוֹב נָמוּךְ מִכֻּלָּם, סִימָן שֶׁהַגָּבוֹהַּ שֶׁנִּתְגָּאָה וְחָטָא יַשְׁפִּיל אֶת עַצְמוֹ כְּאֵזוֹב וְתוֹלַעַת וְיִתְכַּפֵּר לוֹ:\",11,0],[2,133,19,22,\"למשמרת. כְּמוֹ שֶׁפֶּשַׁע הָעֵגֶל שָׁמוּר לְדוֹרוֹת לְפֻרְעָנוּת, וְאֵין לְךָ פְּקֻדָּה שֶׁאֵין בָּהּ מִפְּקֻדַּת הָעֵגֶל, שֶׁנֶּאֱמַר \\\"וּבְיוֹם פָּקְדִי וּפָקַדְתִּי\\\" וְגוֹ' (שמות ל\\\"ב), וּכְשֵׁם שֶׁהָעֵגֶל מְטַמֵּא כָּל הָעוֹסְקִים בּוֹ, כָּךְ פָּרָה תְטַמֵּא כָּל הָעוֹסְקִין בּוֹ, וּכְשֵׁם שֶׁנִּטְהֲרוּ בְּאֶפְרוֹ, שֶׁנֶּאֱמַר \\\"וַיִּזֶר עַל פְּנֵי הַמַּיִם\\\" וְגוֹ' (שם), כָּךְ \\\"וְלָקְחוּ לַטָּמֵא מֵעֲפַר שְׂרֵפַת הַחַטָּאת\\\" וְגוֹ\\\":\",12,0],[2,133,20,1,\"כל העדה. עֵדָה הַשְּׁלֵמָה, שֶׁכְּבָר מֵתוּ מֵתֵי מִדְבָּר וְאֵלּוּ פֵרְשׁוּ לַחַיִּים:\",1,0],[2,133,20,1,\"ותמת שם מרים. לָמָּה נִסְמְכָה פָרָשַׁת מִיתַת מִרְיָם לְפָרָשַׁת פָּרָה אֲדֻמָּה? לוֹמַר לְךָ, מַה קָּרְבָּנוֹת מְכַפְּרִין, אַף מִיתַת צַדִּיקִים מְכַפֶּרֶת (מועד קטן כ\\\"ח):\",2,0],[2,133,20,1,\"ותמת שם מרים. אַף הִיא בִנְשִׁיקָה מֵתָה, וּמִפְּנֵי מָה לֹא נֶאֱמַר בָּהּ \\\"עַל פִּי ה'\\\"? שֶׁאֵינוֹ דֶּרֶךְ כָּבוֹד שֶׁל מַעְלָה, וּבְאַהֲרֹן נֶאֱמַר \\\"עַל פִּי ה'\\\" בְּאֵלֶּה מַסְעֵי (במדבר ל\\\"ג):\",3,0],[2,133,20,2,\"ולא היה מים לעדה. מִכָּאן שֶׁכָּל אַרְבָּעִים שָׁנָה הָיָה לָהֶם הַבְּאֵר בִּזְכוּת מִרְיָם (תענית ט'):\",1,0],[2,133,20,3,\"ולו גוענו. הַלְוַאי שֶׁגָּוַעְנוּ:\",1,0],[2,133,20,3,\"בגוע אחינו. בְּמִיתַת אַחֵינוּ בַּדֶּבֶר, לִמֵּד שֶׁמִּיתַת צָמָא מְגֻנָּה מִמֶּנָּה:\",2,0],[2,133,20,3,\"בגוע. שֵׁם דָּבָר הוּא, כְּמוֹ בְּמִיתַת אַחֵינוּ, וְלֹא יִתָּכֵן לְפָרְשׁוֹ כְּשֶׁמֵּתוּ אַחֵינוּ, שֶׁאִם כֵּן הָיָה לוֹ לִנָּקֵד בִּגְוֹעַ:\",3,0],[2,133,20,8,\"ואת בעירם. מִכָּאן שֶׁחָס הַקָּבָּ\\\"ה עַל מָמוֹנָם שֶׁל יִשְׂרָאֵל:\",1,0],[2,133,20,10,\"ויקהלו וגו'. זֶה אֶחָד מִן הַמְּקוֹמוֹת שֶׁהֶחֱזִיק מוּעָט אֶת הַמְרֻבֶּה (בראשית רבה ה'):\",1,0],[2,133,20,10,\"המן הסלע הזה נוציא. לְפִי שֶׁלֹּא הָיוּ מַכִּירִין אוֹתוֹ, לְפִי שֶׁהָלַךְ הַסֶּלַע וְיָשַׁב לוֹ בֵּין הַסְּלָעִים כְּשֶׁנִּסְתַּלֵּק הַבְּאֵר, וְהָיוּ יִשְׂרָאֵל אוֹמְרִים לָהֶם מַה לָּכֶם מֵאֵי זֶה סֶלַע תּוֹצִיאוּ לָנוּ מַיִם? לְכָךְ אָמַר לָהֶם המרים — סַרְבָנִים, לְשׁוֹן יְוָנִי שׁוֹטִים, מוֹרִים אֶת מוֹרֵיהֶם, הֲמִן הַסֶּלַע הַזֶּה שֶׁלֹּא נִצְטַוִּינוּ עָלָיו נוֹצִיא לָכֶם מַיִם? (תנחומא):\",2,0],[2,133,20,11,\"פעמים. לְפִי שֶׁבָּרִאשׁוֹנָה לֹא הוֹצִיא אֶלָּא טִפִּין, לְפִי שֶׁלֹּא צִוָּה הַמָּקוֹם לְהַכּוֹתוֹ, אֶלָּא \\\"וְדִבַּרְתֶּם אֶל הַסֶּלַע\\\", וְהֵמָּה דִּבְּרוּ אֶל סֶלַע אַחֵר וְלֹא הוֹצִיא, אָמְרוּ, שֶׁמָּא צָרִיךְ לְהַכּוֹתוֹ כְּבָרִאשׁוֹנָה, שֶׁנֶּאֱמַר \\\"וְהִכִּיתָ בַצּוּר\\\" (שמות י\\\"ז), וְנִזְדַּמֵּן לָהֶם אוֹתוֹ סֶלַע וְהִכָּהוּ (תנחומא):\",1,0],[2,133,20,12,\"יען לא האמנתם בי. גִּלָּה הַכָּתוּב שֶׁאִלּוּלֵי חֵטְא זֶה בִּלְבַד הָיוּ נִכְנָסִין לָאָרֶץ, כְּדֵי שֶׁלֹּא יֹאמְרוּ עֲלֵיהֶם כַּעֲוֹן דּוֹר הַמִּדְבָּר שֶׁנִּגְזַר עֲלֵיהֶם שֶׁלֹּא יִכָּנְסוּ, כָּךְ הָיָה עֲוֹן מֹשֶׁה וְאַהֲרֹן; וַהֲלֹא \\\"הֲצֹאן וּבָקָר יִשָּׁחֵט\\\" (במדבר יא, כב) קָשָׁה מִזּוֹ? אֶלָּא לְפִי שֶׁבַּסֵּתֶר, חִסֵּךְ עָלָיו הַכָּתוּב, וְכָאן שֶׁבְּמַעֲמַד כָּל יִשְׂרָאֵל, לֹא חִסֵּךְ עָלָיו הַכָּתוּב מִפְּנֵי קִדּוּשׁ הַשֵּׁם:\",1,0],[2,133,20,12,\"להקדישני. שֶׁאִלּוּ דִּבַּרְתֶּם אֶל הַסֶּלַע וְהוֹצִיא, הָיִיתִי מְקֻדָּשׁ לְעֵינֵי הָעֵדָה, וְאוֹמְרִים מַה סֶּלַע זֶה שֶׁאֵינוֹ מְדַבֵּר וְאֵינוֹ שׁוֹמֵעַ וְאֵינוֹ צָרִיךְ לְפַרְנָסָה מְקַיֵּם דִּבּוּרוֹ שֶׁל מָקוֹם, קַל וָחֹמֶר אָנוּ:\",2,0],[2,133,20,12,\"לכן לא תביאו. בִּשְׁבוּעָה, כְּמוֹ \\\"וְלָכֵן נִשְׁבַּעְתִּי לְבֵית עֵלִי\\\" (שמואל א ג'), נִשְׁבַּע בִּקְפִיצָה שֶׁלֹּא יַרְבּוּ בִתְפִלָּה עַל כָּךְ:\",3,0],[2,133,20,13,\"המה מי מריבה. הֵם הַנִּזְכָּרִים בְּמָקוֹם אַחֵר; אֶת אֵלּוּ רָאוּ אִצְטַגְנִינֵי פַרְעֹה, שֶׁמּוֹשִׁיעָן שֶׁל יִשְׂרָאֵל לוֹקֶה בַמַּיִם, לְכָךְ גָּזְרוּ (שמות א') \\\"כָּל הַבֵּן הַיִּלּוֹד הַיְאֹרָה תַּשְׁלִיכֻהוּ\\\" (סנהדרין ק\\\"א):\",1,0],[2,133,20,13,\"ויקדש בם. שֶׁמֵּתוּ מֹשֶׁה וְאַהֲרֹן עַל יָדָם; כְּשֶׁהַקָּבָּ\\\"ה עוֹשֶׂה דִּין בִּמְקֻדָּשָׁיו הוּא יָראוּי וּמִתְקַדֵּשׁ עַל הַבְּרִיּוֹת, וְכֵן הוּא אוֹמֵר \\\"נוֹרָא אֱלֹהִים מִמִּקְדָּשֶׁיךָ\\\" (תהילים ס\\\"ח), וְכֵן הוּא אוֹמֵר \\\"בִּקְרֹבַי אֶקָּדֵשׁ\\\" (ויקרא י'):\",2,0],[2,133,20,14,\"אחיך ישראל. מָה רָאָה לְהַזְכִּיר כָּאן אַחֲוָה? אֶלָּא אָמַר לוֹ אַחִים אֲנַחְנוּ, בְּנֵי אַבְרָהָם, שֶׁנֶּאֱמַר לוֹ \\\"כִּי גֵר יִהְיֶה זַרְעֲךָ\\\" (בראשית ט\\\"ו), וְעַל שְׁנֵינוּ הָיָה אוֹתוֹ הַחוֹב לְפָרְעוֹ (תנחומא):\",1,0],[2,133,20,14,\"אתה ידעת את כל התלאה. לְפִיכָךְ פֵּרֵשׁ אֲבִיכֶם מֵעַל אָבִינוּ, שֶׁנֶּאֱמַר \\\"וַיֵּלֶךְ אֶל אֶרֶץ מִפְּנֵי יַעֲקֹב אָחִיו\\\" (בראשית ל״ו:ו׳) — מִפְּנֵי הַשְּׁטָר חוֹב הַמֻּטָּל עֲלֵיהֶם, וְהִטִּילוֹ עַל יַעֲקֹב:\",2,0],[2,133,20,15,\"וירעו לנו. סָבַלְנוּ צָרוֹת רַבּוֹת:\",1,0],[2,133,20,15,\"ולאבתינו. מִכָּאן שֶׁהָאָבוֹת מִצְטַעֲרִים בַּקֶּבֶר כְּשֶׁפֻּרְעָנוּת בָּאָה עַל יִשְֹרָאֵל (עי' תנחומא):\",2,0],[2,133,20,16,\"וישמע קלנו. בַּבְּרָכָה שֶׁבֵּרְכָנוּ אָבִינוּ \\\"הַקֹּל קוֹל יַעֲקֹב\\\", שֶׁאָנוּ צוֹעֲקִים וְנַעֲנִים (תנחומא בשלח):\",1,0],[2,133,20,16,\"מלאך. זֶה מֹשֶׁה, מִכָּאן שֶׁהַנְּבִיאִים קְרוּאִים מַלְאָכִים, וְאוֹמֵר \\\"וַיִּהְיוּ מַלְעִבִים בְּמַלְאֲכֵי הָאֱלֹהִים\\\" (דברי הימים ב' ל\\\"ו):\",2,0],[2,133,20,17,\"נעברה נא בארצך. אֵין לְךָ לְעוֹרֵר עַל הַיְרֻשָּׁה שֶׁל אֶרֶץ יִשְׂרָאֵל, כְּשֵׁם שֶׁלֹּא פָרַעְתָּ הַחוֹב, עֲשֵׂה לָנוּ עֵזֶר מְעַט לַעֲבֹר דֶּרֶךְ אַרְצְךָ:\",1,0],[2,133,20,17,\"ולא נשתה מי באר. מֵי בוֹרוֹת הָיָה צָרִיךְ לוֹמַר, אֶלָּא כָּךְ אָמַר מֹשֶׁה, אַעַ\\\"פִּ שֶׁיֵּשׁ בְּיָדֵנוּ מָן לֶאֱכֹל וּבְאֵר לִשְׁתּוֹת, לֹא נִשְׁתֶּה מִמֶּנּוּ, אֶלָּא נִקְנֶה מִכֶּם אֹכֶל וּמַיִם לַהֲנָאַתְכֶם, מִכָּאן לְאַכְסְנַאי אַעַ\\\"פִּ שֶׁיֵּשׁ בְּיָדוֹ לֶאֱכֹל יִקְנֶה מִן הַחֶנְוָנִי, כְּדֵי לְהַנּוֹת אֶת אֻשְׁפִּיזוֹ (תנחומא):\",2,0],[2,133,20,17,\"דרך המלך נלך וגו'. אָנוּ חוֹסְמִים אֶת בְּהֶמְתֵּנוּ וְלֹא יִטּוּ לְכָאן וּלְכָאן לֶאֱכֹל (שם):\",3,0],[2,133,20,18,\"פן בחרב אצא לקראתך. אַתֶּם מִתְגָּאִים בְּקוֹל שֶׁהוֹרִישְׁכֶם אֲבִיכֶם וְאוֹמְרִים \\\"וַנִּצְעַק אֶל ה' וַיִּשְׁמַע קֹלֵנוּ\\\", וַאֲנִי אֵצֵא עֲלֵיכֶם בְּמַה שֶּׁהוֹרִישֵׁנִי אָבִי \\\"וְעַל חַרְבְּךָ תִחְיֶה\\\" (בראשית כ\\\"ז):\",1,0],[2,133,20,19,\"רק אין דבר. אֵין שׁוּם דָּבָר מַזִּיקְךָ:\",1,0],[2,133,20,20,\"וביד חזקה. בְּהַבְטָחַת זְקֵנֵנוּ \\\"וְהַיָּדַיִם יְדֵי עֵשָׂו\\\" (שם):\",1,0],[2,133,20,22,\"כל העדה. כֻּלָּם שְׁלֵמִים וְעוֹמְדִים לִכָּנֵס לָאָרֶץ, שֶׁלֹּא הָיָה בָּהֶן אֶחָד מֵאוֹתָם שֶׁנִּגְזְרָה גְזֵרָה עֲלֵיהֶם, שֶׁכְּבָר כָּלוּ מֵתֵי מִדְבָּר וְאֵלּוּ מֵאוֹתָן שֶׁכָּתוּב בָּהֶן (דברים ד') \\\"חַיִּים כֻּלְּכֶם הַיּוֹם\\\" (תנחומא):\",1,0],[2,133,20,22,\"הר ההר. הַר עַל גַּבֵּי הַר, כְּתַפּוּחַ קָטָן עַל גַּבֵּי תַפּוּחַ גָּדוֹל, וְאַעַ\\\"פִּ שֶׁהֶעָנָן הוֹלֵךְ לִפְנֵיהֶם וּמַשְׁוֶה אֶת הֶהָרִים, שְׁלֹשָׁה נִשְׁאֲרוּ בָהֶן — הַר סִינַי לַתּוֹרָה וְהֹר הָהָר לִקְבוּרַת אַהֲרֹן וְהַר נְבוֹ לִקְבוּרַת מֹשֶׁה (תנחומא):\",2,0],[2,133,20,23,\"על גבול ארץ אדום. מַגִּיד שֶׁמִּפְּנֵי שֶׁנִּתְחַבְּרוּ כָאן לְהִתְקָרֵב לְעֵשָׂו הָרָשָׁע, נִפְרְצוּ מַעֲשֵׂיהֶם וְחָסְרוּ הַצַּדִּיק הַזֶּה, וְכֵן הַנָּבִיא אוֹמֵר לִיהוֹשָׁפָט (דברי הימים ב' כ') \\\"בְּהִתְחַבֶּרְךָ עִם אֲחַזְיָהוּ פָּרַץ ה' אֶת מַעֲשֶׂיךָ\\\" (תנחומא):\",1,0],[2,133,20,25,\"קח את אהרן. בִּדְבָרִים שֶׁל נִחוּמִים — אֱמֹר לוֹ, אַשְׁרֶיךָ שֶׁתִּרְאֶה כִתְרְךָ נָתוּן לְבִנְךָ, מַה שֶּׁאֵין אֲנִי זַכַּאי לְכָךְ (שם):\",1,0],[2,133,20,26,\"את בגדיו. אֶת בִּגְדֵי כְהֻנָּה גְדוֹלָה הִלְבִּישָׁהוּ וְהִפְשִׁיטָם מֵעָלָיו, לְתִתָּם עַל בְּנוֹ בְּפָנָיו; אָמַר לוֹ הִכָּנֵס לַמְּעָרָה וְנִכְנַס, רָאָה מִטָּה מֻצַּעַת וְנֵר דָּלוּק, אָמַר לוֹ עֲלֵה לַמִּטָּה וְעָלָה, פְּשֹׁט יָדֶיךָ וּפָשַׁט, קְמֹץ פִּיךָ וְקָמַץ, עֲצֹם עֵינֶיךָ וְעָצַם, מִיָּד חָמַד מֹשֶׁה לְאוֹתָהּ מִיתָה, וְזֶהוּ שֶׁנֶּאֱמַר לוֹ (דברים ל\\\"ב) \\\"כַּאֲשֶׁר מֵת אַהֲרֹן אָחִיךָ\\\" — מִיתָה שֶׁנִתְאַוִּיתָ לָהּ (ספרי שם):\",1,0],[2,133,20,27,\"ויעש משה. אַעַ\\\"פִּ שֶׁהַדָּבָר קָשֶׁה לוֹ, לֹא עִכֵּב (תנחומא):\",1,0],[2,133,20,29,\"ויראו כל העדה. כְּשֶׁרָאוּ מֹשֶׁה וְאֶלְעָזָר יוֹרְדִים וְאַהֲרֹן לֹא יָרַד, אָמְרוּ הֵיכָן הוּא אַהֲרֹן? אָמַר לָהֶם מֵת, אָמְרוּ אֶפְשָׁר מִי שֶׁעָמַד כְּנֶגֶד הַמַּלְאָךְ וְעָצַר אֶת הַמַּגֵּפָה יִשְׁלֹט בוֹ מַלְאַךְ הַמָּוֶת? מִיָּד בִּקֵּשׁ מֹשֶׁה רַחֲמִים וְהֶרְאוּהוּ מַלְאֲכֵי הַשָּׁרֵת לָהֶם מֻטָּל בַּמִּטָּה, רָאוּ וְהֶאֱמִינוּ (שם):\",1,0],[2,133,20,29,\"כל בית ישראל. הָאֲנָשִׁים וְהַנָּשִׁים, לְפִי שֶׁהָיָה אַהֲרֹן רוֹדֵף שָׁלוֹם וּמַטִּיל אַהֲבָה בֵּין בַּעֲלֵי מְרִיבָה וּבֵין אִישׁ לְאִשְׁתּוֹ (אדר\\\"נ י\\\"ב):\",2,0],[2,133,20,29,\"כי גוע. אוֹמֵר אֲנִי שֶׁהַמְתַּרְגֵּם דְּהָא מִית טוֹעֶה הוּא, אֶלָּא אִם כֵּן מְתַרְגֵּם וַיִּרְאוּ וְאִתְחֲזִיאוּ, שֶׁלֹּא אָמְרוּ רַבּוֹתֵינוּ כִּי זֶה מְשַׁמֵּשׁ בִּלְשׁוֹן דְּהָא אֶלָּא עַל מִדְרָשׁ שֶׁנִּסְתַּלְּקוּ עַנְנֵי הַכָּבוֹד, וְכִדְאָמַר רַבִּי אַבָּהוּ (ראש השנה ג'), אַל תִּקְרֵי וַיִּרְאוּ, אֶלָּא וַיֵּרָאוּ, וְעַל לָשׁוֹן זֶה נוֹפֵל לְשׁוֹן דְּהָא, לְפִי שֶׁהִיא נְתִינַת טַעַם לְמַה שֶּׁלְּמַעְלָה הֵימֶנּוּ — לָמָּה וַיֵּרָאוּ? לְפִי שֶׁהֲרֵי מֵת אַהֲרֹן; אֲבָל עַל תַּרְגּוּם \\\"וְחָזוּ כָל כְּנִשְׁתָּא\\\" אֵין לְשׁוֹן דְּהָא נוֹפֵל אֶלָּא לְשׁוֹן אֲשֶׁר, שֶׁהוּא מִגִּזְרַת שִׁמּוּשׁ אִי, שֶׁמָּצִינוּ אִם מְשַׁמֵּשׁ בִּלְשׁוֹן אֲשֶׁר, כְּמוֹ \\\"וְאִם מַדּוּעַ לֹא תִקְצַר רוּחִי\\\" (איוב כ\\\"א), וְהַרְבֵּה מְפֹרָשִׁים מִזֶּה הַלָּשׁוֹן — \\\"אִם חֲרוּצִים יָמָיו\\\" (שם י\\\"ד):\",3,0],[2,133,21,1,\"וישמע הכנעני. שָׁמַע שֶׁמֵּת אַהֲרֹן וְנִסְתַּלְּקוּ עַנְנֵי כָבוֹד כו', כִּדְאִיתָא בְּרֹאשׁ הַשָּׁנָה (דף ג'), וַעֲמָלֵק מֵעוֹלָם רְצוּעַת מַרְדּוּת לְיִשְׂרָאֵל, מְזֻמָּן בְּכָל עֵת לְפֻרְעָנוּת:\",1,0],[2,133,21,1,\"ישב הנגב. זֶה עֲמָלֵק, שֶׁנֶּאֱמַר \\\"עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב\\\" (במדבר י\\\"ג), וְשִׁנָּה אֶת לְשׁוֹנוֹ לְדַבֵּר בִּלְשׁוֹן כְּנַעַן, כְּדֵי שֶׁיִּהְיוּ יִשְׂרָאֵל מִתְפַּלְּלִים לְהַקָּבָּ\\\"ה לָתֵת כְּנַעֲנִים בְּיָדָם, וְהֵם אֵינָן כְּנַעֲנִים, רָאוּ יִשְׂרָאֵל לְבוּשֵׁיהֶם כִּלְבוּשֵׁי עֲמָלֵקִים וּלְשׁוֹנָם לְשׁוֹן כְּנַעַן, אָמְרוּ נִתְפַּלֵּל סְתָם, שֶׁנֶּאֱמַר \\\"אִם נָתֹן תִּתֵּן אֶת הָעָם הַזֶּה בְּיָדִי\\\" (עי' ילקוט שמעוני תשס\\\"ד):\",2,0],[2,133,21,1,\"דרך האתרים. דֶּרֶךְ הַנֶּגֶב, שֶׁהָלְכוּ בּוֹ מְרַגְּלִים, שֶׁנֶּאֱמַר \\\"וַיַּעֲלוּ בַנֶּגֶב\\\" (במדבר י\\\"ג); דָּבָר אַחֵר: דֶּרֶךְ הָאֲתָרִים, דֶּרֶךְ הַתַּיָּר הַגָּדוֹל הַנּוֹסֵעַ לִפְנֵיהֶם, שֶׁנֶּאֱמַר (שם י') \\\"דֶּרֶךְ שְׁלֹשֶׁת יָמִים לָתוּר לָהֶם מְנוּחָה\\\" (תנחומא):\",3,0],[2,133,21,1,\"וישב ממנו שבי. אֵינָהּ אֶלָּא שִׁפְחָה אַחַת (ילקוט שמעוני שם):\",4,0],[2,133,21,2,\"והחרמתי. אַקְדִּישׁ שְׁלָלָם לְגָבוֹהַּ:\",1,0],[2,133,21,3,\"ויחרם אתהם. בַּהֲרִיגָה:\",1,0],[2,133,21,3,\"ואת עריהם. חֶרְמֵי גָבוֹהַּ:\",2,0],[2,133,21,4,\"דרךְ ים סוף. כֵּיוָן שֶׁמֵּת אַהֲרֹן וּבָאת עֲלֵיהֶם מִלְחָמָה זוֹ, חָזְרוּ לַאֲחוֹרֵיהֶם דֶּרֶךְ יַם סוּף, הוּא הַדֶּרֶךְ שֶׁחָזְרוּ לָהֶם כְּשֶׁנִּגְזַר עֲלֵיהֶם גְּזֵרַת מְרַגְּלִים, שֶׁנֶּאֱמַר \\\"וּסְעוּ הַמִּדְבָּרָה דֶּרֶךְ יַם סוּף\\\" (דברים א'), וְכָאן חָזְרוּ לַאֲחוֹרֵיהֶם שֶׁבַע מַסָּעוֹת, שֶׁנֶּאֱמַר \\\"וּבְנֵי יִשְׂרָאֵל נָסְעוּ מִבְּאֵרֹת בְּנֵי יַעֲקָן מוֹסֵרָה שָׁם מֵת אַהֲרֹן\\\", וְכִי בְמוֹסֵרָה מֵת? וַהֲלֹא בְהֹר הָהָר מֵת? אֶלָּא שָׁם חָזְרוּ וְהִתְאַבְּלוּ עָלָיו וְהִסְפִּידוּהוּ כְּאִלּוּ הוּא בִפְנֵיהֶם; וְצֵא וּבְדֹק בַּמַּסָּעוֹת וְתִמְצְאֵם שֶׁבַע מַסָּעוֹת מִן מוֹסֵרָה עַד הֹר הָהָר (תנחומא):\",1,0],[2,133,21,4,\"לסבב את ארץ אדום. שֶׁלֹּא נְתָנָם לַעֲבֹר בְּאַרְצוֹ:\",2,0],[2,133,21,4,\"ותקצר נפש העם בדרך. בְּטֹרַח הַדֶּרֶךְ שֶׁהֻקְשָׁה לָהֶם, אָמְרוּ עַכְשָׁו הָיִינוּ קְרוֹבִים לִכָּנֵס לָאָרֶץ וְאָנוּ חוֹזְרִים לַאֲחוֹרֵינוּ, כָּךְ חָזְרוּ אֲבוֹתֵינוּ וְנִשְׁתָּהוּ שְׁלֹשִׁים וּשְׁמוֹנֶה שָׁנָה עַד הַיּוֹם, לְפִיכָךְ קָצְרָה נַפְשָׁם בְּעִנּוּי הַדֶּרֶךְ, וּבְלַעַ\\\"ז אנקרוט\\\"לור; וְלֹא יִתָּכֵן לוֹמַר וַתִּקְצַר נֶפֶשׁ הָעָם בַּדָּרֶךְ — בִּהְיוֹתוֹ בַדֶּרֶךְ, וְלֹא פֵּרֵשׁ בּוֹ בַּמֶּה קָצְרָה, שֶׁכָּל מָקוֹם שֶׁתִּמְצָא קִצּוּר נֶפֶש בַּמִּקְרָא מְפֹרָשׁ שָׁם בַּמֶּה קָצְרָה, כְּגוֹן \\\"וַתִּקְצַר נַפְשִׁי בָּהֶם\\\" (זכריה י\\\"א), וּכְגוֹן \\\"וַתִּקְצַר נַפְשׁוֹ בַּעֲמַל יִשְׂרָאֵל\\\" (שופטים י'), וְכָל דָּבָר קָשֶׁה עַל אָדָם נוֹפֵל בּוֹ לְשׁוֹן קִצּוּר נֶפֶשׁ, כְּאָדָם שֶׁהַטֹּרַח בָּא עָלָיו וְאֵין דַּעְתּוֹ רְחָבָה לְקַבֵּל אוֹתוֹ הַדָּבָר וְאֵין לוֹ מָקוֹם בְּתוֹךְ לִבּוֹ לָגוּר שָׁם הַצַּעַר, וּבְדָבָר הַמַּטְרִיחַ נוֹפֵל לְשׁוֹן גֹּדֶל, שֶׁגָּדוֹל הוּא וְכָבֵד עַל הָאָדָם, כְּגוֹן \\\"וְגַם נַפְשָׁם בָּחֲלָה בִי\\\" (זכריה י\\\"א) — גָּדְלָה עָלַי, \\\"וְיִגְאֶה כַּשַּׁחַל תְּצוּדֵנִי\\\" (איוב י'); כְּלָלוֹ שֶׁל פֵּרוּשׁ, כָּל לְשׁוֹן קִצּוּר נֶפֶשׁ בְּדָבָר לָשׁוֹן שֶׁאֵין יָכוֹל לְסָבְלוֹ הוּא — שֶׁאֵין הַדַּעַת סוֹבַלְתּוֹ:\",3,0],[2,133,21,5,\"באלהים ובמשה. הִשְׁווּ עֶבֶד לְקוֹנוֹ (תנחומא):\",1,0],[2,133,21,5,\"למה העליתנו. שְׁנֵיהֶם שָׁוִים:\",2,0],[2,133,21,5,\"ונפשנו קצה. אַף זֶה לְשׁוֹן קִצּוּר נֶפֶשׁ וּמִאוּס:\",3,0],[2,133,21,5,\"בלחם הקלקל. לְפִי שֶׁהַמָּן נִבְלָע בָּאֵבָרִים קְרָאוּהוּ קְלֹקֵל, אָמְרוּ, עָתִיד הַמָּן הַזֶּה שֶׁיִּתְפַּח בְּמֵעֵינוּ, כְּלוּם יֵשׁ יְלוּד אִשָּׁה שֶׁמַּכְנִיס וְאֵינוֹ מוֹצִיא? (יומא ע\\\"ה):\",4,0],[2,133,21,6,\"את הנחשים השרפים. שֶׁשּׂוֹרְפִים אֶת הָאָדָם בְּאֶרֶס שִׁנֵּיהֶם:\",1,0],[2,133,21,6,\"וינשכו את העם. יָבֹא נָחָשׁ שֶׁלָּקָה עַל הוֹצָאַת דִּבָּה וְיִפָּרַע מִמּוֹצִיאֵי דִּבָּה, יָבֹא נָחָשׁ שֶׁכָּל הַמִּינִין נִטְעָמִין לוֹ טַעַם אֶחָד וְיִפָּרַע מִכְּפוּיֵי טוֹבָה שֶׁדָּבָר אֶחָד מִשְׁתַּנֶּה לָהֶם לְכַמָּה מַטְעַמִּים (תנחומא):\",2,0],[2,133,21,7,\"ויתפלל משה. מִכָּאן לְמִי שֶׁמְּבַקְשִׁים מִמֶּנּוּ, שֶׁלֹּא יְהֵא אַכְזָרִי מִלִּמְחֹל (עי' תנחומא):\",1,0],[2,133,21,8,\"על נס. עַל כְּלוֹנָס, שֶׁקּוֹרִין פירק\\\"א בְּלַעַז, וְכֵן \\\"וְכַנֵּס עַל הַגִּבְעָה\\\" (ישעיהו ל'), \\\"אָרִים נִסִּי\\\" (שם מ\\\"ט), \\\"שְׂאוּ נֵס\\\" (שם י\\\"ג); וּלְפִי שֶׁהוּא גָּבוֹהַּ לְאוֹת וְלִרְאָיָה, קוֹרְאוֹ נֵס:\",1,0],[2,133,21,8,\"כל הנשוך. אֲפִלּוּ כֶלֶב אוֹ חֲמוֹר נוֹשְׁכוֹ הָיָה נִזּוֹק וּמִתְנַוְּנֶה וְהוֹלֵךְ, אֶלָּא שֶׁנְּשִׁיכַת הַנָּחָשׁ מְמַהֶרֶת לְהָמִית, לְכָךְ נֶאֱמַר כָּאן וְרָאָה אֹתוֹ — רְאִיָּה בְעָלְמָא — וּבִנְשִׁיכַת הַנָּחָשׁ נֶאֱמַר \\\"וְהִבִּיט\\\" — וְהָיָה אִם נָשַׁךְ הַנָּחָשׁ אֶת אִישׁ וְהִבִּיט וְגוֹ' — שֶׁלֹּא הָיָה מְמַהֵר נְשׁוּךְ הַנַּחַשׁ לְהִתְרַפְּאוֹת אֶלָּא אִם כֵּן מַבִּיט בּוֹ בְּכַוָּנָה; וְאָמְרוּ רַבּוֹתֵינוּ וְכִי נָחָשׁ מֵמִית אוֹ מְחַיֶּה? אֶלָּא, בִּזְמַן שֶׁהָיוּ יִשְׂרָאֵל מִסְתַּכְּלִין כְּלַפֵּי מַעְלָה וּמְשַׁעְבְּדִין אֶת לִבָּם לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם הָיוּ מִתְרַפְּאִים, וְאִם לָאו הָיוּ נִמּוֹקִים (ראש השנה כ\\\"ט):\",2,0],[2,133,21,9,\"נחש נחשת. לֹא נֶאֱמַר לוֹ לַעֲשׂוֹתוֹ שֶׁל נְחֹשֶׁת, אֶלָּא אָמַר מֹשֶׁה, הַקָּבָּ\\\"ה קוֹרְאוֹ נָחָשׁ וַאֲנִי אֶעֱשֶׂנּוּ שֶׁל נְחֹשֶׁת, לָשׁוֹן נוֹפֵל עַל לָשׁוֹן (בראשית רבה ל\\\"א):\",1,0],[2,133,21,11,\"בעיי העברים. לֹא יָדַעְתִּי לָמָּה נִקְרָא שְׁמָם עִיִּים, וְעִי לְשׁוֹן חָרְבָּה הִיא — דָּבָר הַטָּאוּט בְּמַטְאֲטֵא, וְהָעַיִ\\\"ן בּוֹ יְסוֹד לְבַדָּהּ, וְהוּא מִלְּשׁוֹן \\\"יָעִים\\\" (שמות כ\\\"ז), \\\"וְיָעָה בָרָד\\\" (ישעיהו כ\\\"ח):\",1,0],[2,133,21,11,\"העברים. דֶּרֶךְ מַעֲבַר הָעוֹבְרִים שָׁם אֶת הַר נְבוֹ אֶל אֶרֶץ כְּנַעַן, שֶׁהוּא מַפְסִיק בֵּין אֶרֶץ מוֹאָב לְאֶרֶץ אֱמוֹרִי:\",2,0],[2,133,21,11,\"על פני מואב ממזרח השמש. בְּמִזְרָחָהּ שֶׁל אֶרֶץ מוֹאָב:\",3,0],[2,133,21,13,\"מגבל האמרי. תְּחוּם סוֹף מֶצֶר שֶׁלָּהֶם, וְכֵן גְּבוּל מוֹאָב — לְשׁוֹן קָצֶה וָסוֹף:\",1,0],[2,133,21,13,\"מעבר ארנון. הִקִּיפוּ אֶרֶץ מוֹאָב כָּל דְּרוֹמָהּ וּמִזְרָחָהּ עַד שֶׁבָּאוּ מֵעֵבֶר הַשֵּׁנִי לְאַרְנוֹן בְּתוֹךְ אֶרֶץ הָאֱמוֹרִי בִּצְפוֹנָהּ שֶׁל אֶרֶץ מוֹאָב:\",2,0],[2,133,21,13,\"היצא מגבל האמרי. רְצוּעָה יוֹצְאָה מִגְּבוּל הָאֱמוֹרִי וְהִיא שֶׁל אֱמוֹרִיִּים, וְנִכְנֶסֶת לִגְבוּל מוֹאָב עַד אַרְנוֹן שֶׁהוּא גְּבוּל מוֹאָב, וְשָׁם חָנוּ יִשְֹרָאֵל וְלֹא בָאוּ לִגְבוּל מוֹאָב, כי ארנון גבול מואב, וְהֵם לֹא נָתְנוּ לָהֶם רְשׁוּת לַעֲבֹר בְּאַרְצָם, וְאַעַ\\\"פִּי שֶׁלֹּא פֵרְשָׁהּ מֹשֶׁה, פֵּרְשָׁהּ יִפְתָּח, כְּמוֹ שֶׁאָמַר יִפְתָּח (שופטים י\\\"א) \\\"וְגַם אֶל מֶלֶךְ מוֹאָב שָׁלַח וְלֹא אָבָה\\\", וּמֹשֶׁה רְמָזָהּ (דברים ב'), \\\"כַּאֲשֶׁר עָשׂוּ לִי בְּנֵי עֵשָׂו הַיֹּשְׁבִים בְּשֵׂעִיר וְהַמּוֹאָבִים הַיֹּשְׁבִים בְּעָר\\\" — מָה אֵלּוּ לֹא נְתָנוּם לַעֲבֹר בְּתוֹךְ אַרְצָם אֶלָּא הִקִּיפוּם סָבִיב, אַף מוֹאָב כֵּן:\",3,0],[2,133,21,14,\"על כן יאמר. עַל חֲנִיָּה זוֹ וְנִסִּים שֶׁנַּעֲשׂוּ בָהּ יאמר בספר מלחמת ה' — כְּשֶׁמְּסַפְּרִים נִסִּים שֶׁנַּעֲשׂוּ לַאֲבוֹתֵינוּ יְסַפְּרוּ אֶת וָהֵב וגו':\",1,0],[2,133,21,14,\"את והב. כְּמוֹ אֶת יָהֵב, כְּמוֹ שֶׁיֵּאָמֵר מִן יעד וָעֵד, כֵּן יֵאָמֵר מִן יהב וָהֵב, וְהַוָּי\\\"ו יְסוֹד הוּא, כְּלוֹמַר אֶת אֲשֶׁר יָהַב לָהֶם וְהִרְבָּה נִסִּים בְּיַם סוּף:\",2,0],[2,133,21,14,\"ואת הנחלים ארנון. כְּשֵׁם שֶׁמְּסַפְּרִים בְּנִסֵּי יַם סוּף, כָּךְ יֵשׁ לְסַפֵּר בְּנִסֵּי נַחֲלֵי אַרְנוֹן, שֶׁאַף כָּאן נַעֲשׂוּ נִסִּים גְּדוֹלִים, וּמָה הֵם הַנִּסִּים?\",3,0],[2,133,21,15,\"ואשד הנחלים. תַּרְגּוּם שֶׁל שֶׁפֶךְ \\\"אֶשֶׁד\\\" — שֶׁפֶךְ הַנְּחָלִים שֶׁנִּשְׁפַּךְ שָׁם דַּם אֱמוֹרִיִּים, שֶׁהָיוּ נֶחְבָּאִים שָׁם, לְפִי שֶׁהָיוּ הֶהָרִים גְּבוֹהִים וְהַנַּחַל עָמֹק וְקָצָר וְהֶהָרִים סְמוּכִים זֶה לָזֶה — אָדָם עוֹמֵד עַל הָהָר מִזֶּה וּמְדַבֵּר עִם חֲבֵרוֹ בָּהָר הַזֶּה — וְהַדֶּרֶךְ עוֹבֵר בְּתוֹךְ הַנַּחַל, אָמְרוּ אֱמוֹרִיִּים, כְּשֶׁיִּכָּנְסוּ יִשְׂרָאֵל לָאָרֶץ לְתוֹךְ הַנַּחַל לַעֲבֹר, נֵצֵא מִן הַמְּעָרוֹת שֶׁבֶּהָרִים שֶׁלְּמַעְלָה מֵהֶם, וְנַהַרְגֵם בְּחִצִּים וְאַבְנֵי בָּלִיסְטְרָאוֹת, וְהָיוּ אוֹתָן הַנְּקָעִים בָּהָר שֶׁל צַד מוֹאָב, וּבָהָר שֶׁל צַד אֱמוֹרִיִּים הָיוּ כְּנֶגֶד אוֹתָן נְקָעִים כְּמִין קְרָנוֹת וְשָׁדַיִם בּוֹלְטִין לַחוּץ, כֵּיוָן שֶׁבָּאוּ יִשְׂרָאֵל לַעֲבֹר, נִזְדַּעְזַע הָהָר שֶׁל אֶרֶץ יִשְׂרָאֵל כְּשִׁפְחָה הַיּוֹצֵאת לְהַקְבִּיל פְּנֵי גְבִרְתָּהּ, וְנִתְקָרֵב לְצַד הָהָר שֶׁל מוֹאָב וְנִכְנְסוּ אוֹתָן הַשָּׁדַיִם לְתוֹךְ אוֹתָן נְקָעִים וַהֲרָגוּם, וְזֶהוּ אֲשֶׁר נָטָה לְשֶׁבֶת עָר — שֶׁהָהָר נָטָה מִמְּקוֹמוֹ וְנִתְקָרֵב לְצַד מוֹאָב וְנִדְבַּק בּוֹ, וְזֶהוּ וְנִשְׁעַן לִגְבוּל מוֹאָב (תנחומא; ברכות נ\\\"ד):\",1,0],[2,133,21,16,\"ומשם בארה. מִשָּׁם בָּא הָאֶשֶׁד אֶל הַבְּאֵר; כֵּיצַד? אָמַר הַקָּבָּ\\\"ה מִי מוֹדִיעַ לְבָנַי הַנִּסִּים הַלָּלוּ? הַמָּשָׁל אוֹמֵר \\\"נָתַתָּ פַּת לְתִינוֹק הוֹדִיעַ לְאִמּוֹ\\\". לְאַחַר שֶׁעָבְרוּ חָזְרוּ הֶהָרִים לִמְקוֹמָם, וְהַבְּאֵר יָרְדָה לְתוֹךְ הַנַּחַל וְהֶעֶלְתָה מִשָּׁם דַּם הַהֲרוּגִים וּזְרוֹעוֹת וְאֵבָרִים וּמוֹלַכְתָּן סָבִיב הַמַּחֲנֶה, וְיִשְׂרָאֵל רָאוּ וְאָמְרוּ שִׁירָה:\",1,0],[2,133,21,17,\"עלי באר. מִתּוֹךְ הַנַּחַל וְהַעֲלִי מַה שֶּׁאַתְּ מַעֲלָה; וּמִנַּיִן שֶׁהַבְּאֵר הוֹדִיעָה לָהֶם? שֶׁנֶּאֱמַר \\\"וּמִשָּׁם בְּאֵרָה\\\", וְכִי מִשָּׁם הָיְתָה, וַהֲלֹא מִתְּחִלַּת אַרְבָּעִים שָׁנָה הָיְתָה עִמָּהֶם? אֶלָּא שֶׁיָּרְדָה לְפַרְסֵם אֶת הַנִּסִּים (תנחומא); וְכֵן אָז יָשִׁיר … הַשִּׁירָה הַזֹּאת נֶאֶמְרָה בְּסוֹף אַרְבָּעִים וְהַבְּאֵר נִתְּנָה לָהֶם מִתְּחִלַּת אַרְבָּעִים, מָה רָאָה לִכָּתֵב כָּאן? אֶלָּא הָעִנְיָן הַזֶּה נִדְרָשׁ לְמַעְלָה הֵימָנוּ:\",1,0],[2,133,21,18,\"באר חפרוה. זֹאת הִיא הַבְּאֵר אֲשֶׁר חֲפָרוּהָ שָׂרִים — מֹשֶׁה וְאַהֲרֹן:\",1,0],[2,133,21,18,\"במשענתם. בַּמַּטֶּה:\",2,0],[2,133,21,18,\"וממדבר. נִתְּנָה לָהֶם:\",3,0],[2,133,21,19,\"וממתנה נחליאל. כְּתַרְגּוּמוֹ:\",1,0],[2,133,21,20,\"ומבמות הגיא אשר בשדה מואב. כִּי שָׁם מֵת מֹשֶׁה וְשָׁם בָּטְלָה הַבְּאֵר; דָּ\\\"אַ, כָּרוּהָ נְדִיבֵי הָעָם — כָּל נָשִׂיא וְנָשִׂיא כְּשֶׁהָיוּ חוֹנִים נוֹטֵל מַקְלוֹ וּמוֹשֵׁךְ אֵצֶל דִּגְלוֹ וּמַחֲנֵהוּ, וּמֵי הַבְּאֵר נִמְשָׁכִין דֶּרֶךְ אוֹתוֹ סִימָן וּבָאִין לִפְנֵי חֲנִיַּת כָּל שֵׁבֶט וָשֵׁבֶט (תנחומא):\",1,0],[2,133,21,20,\"במחקק. עַל פִּי מֹשֶׁה שֶׁנִּקְרָא מְחוֹקֵק, שֶׁנֶּאֱמַר \\\"כִּי שָׁם חֶלְקַת מְחֹקֵק סָפוּן\\\" (דברים ל\\\"ג); וְלָמָּה לֹא נִזְכַּר מֹשֶׁה בְּשִׁירָה זוֹ? לְפִי שֶׁלָּקָה עַל יְדֵי הַבְּאֵר, וְכֵיוָן שֶׁלֹּא נִזְכַּר שְׁמוֹ שֶׁל מֹשֶׁה לֹא נִזְכַּר שְׁמוֹ שֶׁל הַקָּבָּ\\\"ה, מָשָׁל לְמֶלֶךְ שֶׁהָיוּ מְזַמְּנִין אוֹתוֹ לִסְעוּדָה, אָמַר אִם אוֹהֲבִי שָׁם אֲנִי שָׁם, וְאִם לָאו אֵינִי הוֹלֵךְ (תנחומא):\",2,0],[2,133,21,20,\"ראש הפסגה. כְּתַרְגּוּמוֹ \\\"רֵישׁ רָמָתָא\\\":\",3,0],[2,133,21,20,\"פסגה. לְשׁוֹן גֹּבַהּ, וְכֵן \\\"פַּסְּגוּ אַרְמְנוֹתֶיהָ\\\" (תהילים מ\\\"ח) — הַגְבִּיהוּ אַרְמְנוֹתֶיהָ:\",4,0],[2,133,21,20,\"ונשקפה. אוֹתָהּ הַפִּסְגָּה עַל פְּנֵי הַמָּקוֹם שֶׁשְּׁמוֹ יְשִׁימוֹן, וְהוּא לְשׁוֹן מִדְבָּר שֶׁהוּא שָׁמֵם; דָּבָר אַחֵר וְנִשְׁקָפָה הַבְּאֵר עַל פְּנֵי הַיְשִׁימוֹן, שֶׁנִּגְנְזָה בְּיַמָּהּ שֶׁל טְבֶרְיָא, וְהָעוֹמֵד עַל הַיְשִׁימוֹן מַבִּיט וְרוֹאֶה כְּמִין כְּבָרָה בַּיָּם, וְהִיא הַבְּאֵר, כָּךְ דָּרַשׁ רַבִּי תַנְחוּמָא:\",5,0],[2,133,21,21,\"וישלח ישראל מלאכים. וּבְמָקוֹם אַחֵר תּוֹלֶה הַשְּׁלִיחוּת בְּמֹשֶׁה, שֶׁנֶּאֱמַר \\\"וָאֶשְׁלַח מַלְאָכִים מִמִּדְבַּר קְדֵמוֹת\\\" (דברים ב'), וְכֵן \\\"וַיִּשְׁלַח מֹשֶׁה מַלְאָכִים מִקָּדֵשׁ אֶל מֶלֶךְ אֱדוֹם\\\" (במדבר כ'), וּבְיִפְתָּח הוּא אוֹמֵר (שופטים י\\\"א) \\\"וַיִּשְׁלַח יִשְׂרָאֵל מַלְאָכִים אֶל מֶלֶךְ אֱדוֹם\\\" וְגוֹ', הַכְּתוּבִים הַלָּלוּ צְרִיכִין זֶה לָזֶה, זֶה נוֹעֵל וְזֶה פוֹתֵחַ, שֶׁמֹּשֶׁה הוּא יִשְׂרָאֵל וְיִשְׂרָאֵל הֵם מֹשֶׁה, לוֹמַר לְךָ שֶׁנְּשִׂיא הַדּוֹר הוּא כְּכָל הַדּוֹר, כִּי הַנָּשִׂיא הוּא הַכֹּל (תנחומא):\",1,0],[2,133,21,22,\"אעברה בארצך. אַעַ\\\"פִּ שֶׁלֹּא נִצְטַוּוּ לִפְתֹּחַ לָהֶם בְּשָׁלוֹם בִּקְּשׁוּ מֵהֶם שָׁלוֹם (שם):\",1,0],[2,133,21,23,\"ולא נתן סיחן וגו'. לְפִי שֶׁכָּל מַלְכֵי כְנַעַן הָיוּ מַעֲלִין לוֹ מַס, שֶׁהָיָה שׁוֹמְרָם שֶׁלֹּא יַעַבְרוּ עֲלֵיהֶם גְּיָסוֹת, כֵּיוָן שֶׁאָמְרוּ לוֹ יִשְׂרָאֵל אֶעְבְּרָה בְאַרְצֶךָ, אָ\\\"לָ, כָּל עַצְמִי אֵינִי יוֹשֵׁב כָּאן אֶלָּא לְשָׁמְרָם מִפְּנֵיכֶם, וְאַתֶּם אוֹמְרִים כָּךְ (תנחומא):\",1,0],[2,133,21,23,\"ויצא לקראת ישראל. אִלּוּ הָיְתָה חֶשְׁבּוֹן מְלֵאָה יַתּוּשִׁין אֵין כָּל בְּרִיָּה יְכוֹלָה לְכָבְשָׁהּ, וְאִם הָיָה סִיחוֹן בִּכְפָר חַלָּשׁ אֵין כָּל אָדָם יָכוֹל לְכָבְשׁוֹ, וְכָל שֶׁכֵּן שֶׁהָיָה בְּחֶשְׁבּוֹן; אָמַר הַקָּבָּ\\\"ה מָה אֲנִי מַטְרִיחַ עַל בָּנַי כָּל זֹאת לָצוּר עַל כָּל עִיר וָעִיר? נָתַן בְּלֵב כָּל אַנְשֵׁי הַמִּלְחָמָה לָצֵאת מִן הָעֲיָרוֹת, וְנִתְקַבְּצוּ כֻלָּם לְמָקוֹם אֶחָד וְשָׁם נָפְלוּ, וּמִשָּׁם הָלְכוּ יִשְׂרָאֵל אֶל הֶעָרִים וְאֵין עוֹמֵד לְנֶגְדָּם, כִּי אֵין שָׁם אֶלָּא נָשִׁים וָטָף (שם):\",2,0],[2,133,21,24,\"כי עז. וּמַהוּ חָזְקוֹ? הַתְרָאָתוֹ שֶׁל הַקָּבָּ\\\"ה שֶׁאָמַר לָהֶם אַל תְּצֻרֵם וְגוֹ' (דברים ב'):\",1,0],[2,133,21,25,\"בנתיה. כְּפָרִים הַסְּמוּכִים לָהּ:\",1,0],[2,133,21,26,\"והוא נלחם. לָמָּה הֻצְרַךְ לִכָּתֵב? לְפִי שֶׁנֶּאֱמַר (שם) \\\"אַל תָּצַר אֶת מוֹאָב\\\", וְחֶשְׁבּוֹן מִשֶּׁל מוֹאָב הָיְתָה, כָּתַב לָנוּ שֶׁסִּיחוֹן לְקָחָהּ מֵהֶם וְעַל יָדוֹ טָהֲרָה לְיִשְֹרָאֵל (חולין ס'; גיטין ל\\\"ח):\",1,0],[2,133,21,26,\"מידו. מֵרְשׁוּתוֹ (בבא מציעא נ\\\"ו):\",2,0],[2,133,21,27,\"על כן. עַל אוֹתָהּ מִלְחָמָה שֶׁנִּלְחַם סִיחוֹן בְּמוֹאָב:\",1,0],[2,133,21,27,\"יאמרו המשלים. בִּלְעָם, שֶׁנֶּאֱמַר בּוֹ \\\"וַיִּשָּׂא מְשָׁלוֹ\\\" (במדבר כ\\\"ג):\",2,0],[2,133,21,27,\"המשלים. בִּלְעָם וּבְעוֹר, וְהֵם אָמְרוּ:\",3,0],[2,133,21,27,\"באו חשבון. שֶׁלֹּא הָיָה סִיחוֹן יָכוֹל לְכָבְשָׁהּ וְהָלַךְ וְשָׂכַר אֶת בִּלְעָם לְקַלְּלוֹ (תנחומא); וְזֶהוּ שֶׁאָמַר לוֹ בָּלָק \\\"כִּי יָדַעְתִּי אֵת אֲשֶׁר תְּבָרֵךְ מְבֹרָךְ\\\" וְגוֹ' (במדבר כ\\\"ב):\",4,0],[2,133,21,27,\"תבנה ותכונן. חֶשְׁבּוֹן בְּשֵׁם סִיחוֹן לִהְיוֹת עִירוֹ:\",5,0],[2,133,21,28,\"כי אש יצאה מחשבון. מִשֶּׁכְּבָשָׁהּ סִיחוֹן:\",1,0],[2,133,21,28,\"אכלה ער מואב. שֵׁם אוֹתָהּ הַמְּדִינָה קָרוּי עָר בְּלָשׁוֹן עִבְרִי וּלְחָיַת בְּלָשׁוֹן אֲרַמִּי:\",2,0],[2,133,21,28,\"ער מואב. עָר שֶׁל מוֹאָב:\",3,0],[2,133,21,29,\"אוי לך מואב. שֶׁקִּלְּלוּ אֶת מוֹאָב שֶׁיִּמָּסְרוּ בְיָדוֹ (תנחומא):\",1,0],[2,133,21,29,\"כמוש. שֵׁם אֱלֹהֵי מוֹאָב:\",2,0],[2,133,21,29,\"נתן. הַנּוֹתֵן אֶת בָּנָיו שֶׁל מוֹאָב:\",3,0],[2,133,21,29,\"פליטם — נָסִים וּפְלֵטִים מֵחֶרֶב וְאֶת בְּנוֹתָיו בַּשְּׁבִית וְגוֹ':\",4,0],[2,133,21,30,\"ונירם אבד. מַלְכוּת שֶׁלָּהֶם:\",1,0],[2,133,21,30,\"אבד חשבון עד דיבן — מַלְכוּת וְעֹל שֶׁהָיָה לְמוֹאָב בְּחֶשְׁבּוֹן אָבַד מִשָּׁם, וְכֵן עַד דִּיבֹן; תַּרְגּוּם שֶׁל סָר \\\"עַד\\\", כְּלוֹמַר סָר נִיר מִדִּיבֹן; נִיר לְשׁוֹן מַלְכוּת וְעֹל מֶמְשֶׁלֶת אִישׁ, כְּמוֹ \\\"לְמַעַן הֱיוֹת נִיר לְדָוִד עַבְדִּי\\\" (מ\\\"א י\\\"א):\",2,0],[2,133,21,30,\"ונשים. שִׁי\\\"ן דְּגוּשָׁה, לְשׁוֹן שְׁמָמָה, כָּךְ יֹאמְרוּ הַמֹּשְׁלִים, \\\"וַנַּשִּׁים אוֹתָם עַד נֹפַח\\\" — הֲשִׁמּוֹנוּם עַד נֹפַח:\",3,0],[2,133,21,32,\"וישלח משה לרגל את יעזר. הַמְרַגְּלִים לְכָדוּהָ, אָמְרוּ לֹא נַעֲשֶׂה כָּרִאשׁוֹנִים, בְּטוּחִים אָנוּ בְּכֹחַ תְּפִלָּתוֹ שֶׁל מֹשֶׁה לְהִלָּחֵם (תנחומא):\",1,0],[2,133,21,34,\"אל תירא אתו. שֶׁהָיָה מֹשֶׁה יָרֵא לְהִלָּחֵם, שֶׁמָּא תַּעֲמֹד לוֹ זְכוּתוֹ שֶׁל אַבְרָהָם, שֶׁנֶּאֱמַר \\\"וַיָּבֹא הַפָּלִיט\\\" (בראשית י\\\"ד) — הוּא עוֹג שֶׁפָּלַט מִן הָרְפָאִים שֶׁהִכּוּ כְּדָרְלָעֹמֶר וַחֲבֵרָיו בְּעַשְׁתְּרוֹת קַרְנַיִם, שֶׁנֶּאֱמַר (דברים ג') \\\"רַק עוֹג מֶלֶךְ הַבָּשָׁן נִשְׁאַר מִיֶּתֶר הָרְפָאִים\\\" (נדה ס\\\"א):\",1,0],[2,133,21,35,\"ויכו אתו. מֹשֶׁה הֲרָגוֹ, כִּדְאִיתָא בִבְרָכוֹת בְּהָרוֹאֶה (ברכות דף נ\\\"ד), עֲקַר טוּרָא בַּר תְּלָתָא פַרְסֵי וְכוּ':\",1,0],[2,133,22,2,\"וירא בלק בן צפור את כל אשר עשה ישראל לאמרי. אָמַר, אֵלּוּ שְׁנֵי מְלָכִים שֶׁהָיִינוּ בְטוּחִים עֲלֵיהֶם לֹא עָמְדוּ בִּפְנֵיהֶם, אָנוּ עַל אַחַת כַּמָּה וְכַמָּה, לְפִיכָךְ \\\"וַיָּגָר מוֹאָב\\\" (תנחומא):\",1,0],[2,133,22,3,\"ויגר. לְשׁוֹן מוֹרָא, כְּמוֹ \\\"גּוּרוּ לָכֶם\\\" (איוב י\\\"ט):\",1,0],[2,133,22,3,\"ויקץ מואב. קָצוּ בְחַיֵּיהֶם:\",2,0],[2,133,22,4,\"אל זקני מדין. וַהֲלֹא מֵעוֹלָם הָיוּ שׂוֹנְאִים זֶה אֶת זֶה, שֶׁנֶּאֱמַר \\\"הַמַּכֶּה אֶת מִדְיָן בִּשְׂדֵה מוֹאָב\\\" (בראשית ל\\\"ו), שֶׁבָּאוּ מִדְיָן עַל מוֹאָב לַמִּלְחָמָה? אֶלָּא מִיִּרְאָתָן שֶׁל יִשְׂרָאֵל עָשׂוּ שָׁלוֹם בֵּינֵיהֶם; וּמָה רָאָה מוֹאָב לִטֹּל עֵצָה מִמִּדְיָן? כֵּיוָן שֶׁרָאוּ אֶת יִשְׂרָאֵל נוֹצְחִים שֶׁלֹּא כְמִנְהַג הָעוֹלָם, אָמְרוּ מַנְהִיגָם שֶׁל אֵלּוּ בְּמִדְיָן נִתְגַּדֵּל, נִשְׁאַל מֵהֶם מַה מִּדָּתוֹ, אָמְרוּ לָהֶם אֵין כֹּחוֹ אֶלָּא בְּפִיו, אָמְרוּ, אַף אָנוּ נָבֹא עֲלֵיהֶם בְּאָדָם שֶׁכֹּחוֹ בְּפִיו (תנחומא):\",1,0],[2,133,22,4,\"כלחך השור. כָּל מַה שֶּׁהַשּׁוֹר מְלַחֵךְ אֵין בּוֹ בְרָכָה (שם):\",2,0],[2,133,22,4,\"בעת ההוא. לֹא הָיָה רָאוּי לְמַלְכוּת, מִנְּסִיכֵי מִדְיָן הָיָה, וְכֵיוָן שֶׁמֵּת סִיחוֹן מִנּוּהוּ עֲלֵיהֶם לְצֹרֶךְ שָׁעָה (שם):\",3,0],[2,133,22,5,\"פתורה. כְּשֻׁלְחָנִי זֶה שֶׁהַכֹּל מְרִיצִין לוֹ מָעוֹת, כָּךְ כָּל הַמְּלָכִים מְרִיצִין לוֹ אִגְּרוֹתֵיהֶם, וּלְפִי פְשׁוּטוֹ שֶׁל מִקְרָא כָּךְ שֵׁם הַמָּקוֹם (שם):\",1,0],[2,133,22,5,\"ארץ בני עמו. שֶׁל בָּלָק, מִשָּׁם הָיָה, וְזֶה הָיָה מִתְנַבֵּא וְאוֹמֵר לוֹ, עָתִיד אַתָּה לִמְלֹךְ; וְאִם תֹּאמַר מִפְּנֵי מָה הִשְׁרָה הַקָּבָּ\\\"ה שְׁכִינָתוֹ עַל גּוֹי רָשָׁע? כְּדֵי שֶׁלֹּא יִהְיֶה פִתְחוֹן פֶּה לָאֻמּוֹת לוֹמַר, אִלּו הָיוּ לָנוּ נְבִיאִים, חָזַרְנוּ לְמוּטָב, הֶעֱמִיד לָהֶם נְבִיאִים וְהֵם פָּרְצוּ גֶדֶר הָעוֹלָם, שֶׁבַּתְּחִלָּה הָיוּ גְדוּרִים בַּעֲרָיוֹת, וְזֶה נָתַן לָהֶם עֵצָה לְהַפְקִיר עַצְמָן לִזְנוּת:\",2,0],[2,133,22,5,\"לקרא לו. הַקְּרִיאָה הָיְתָה שֶׁלּוֹ וְלַהֲנָאָתוֹ, שֶׁהָיָה פוֹסֵק לוֹ מָמוֹן הַרְבֵּה:\",3,0],[2,133,22,5,\"עם יצא ממצרים. וְאִם תֹּאמַר מַה מַּזִּיקְךָ?\",4,0],[2,133,22,5,\"הנה כסה את עין הארץ. סִיחוֹן וְעוֹג שֶׁהָיוּ שׁוֹמְרִים אוֹתָנוּ עָמְדוּ עֲלֵיהֶם וַהֲרָגוּם:\",5,0],[2,133,22,5,\"והוא ישב ממלי. חָסֵר כְּתִיב, קְרוֹבִים הֵם לְהַכְרִיתֵנִי כְּמוֹ (תהילים קי\\\"ח) כִּי אֲמִילַם (תנחומא):\",6,0],[2,133,22,6,\"נכה בו. אֲנִי וְעַמִּי נַכֶּה בָהֶם. דָּ\\\"אַ — לְשׁוֹן מִשְׁנָה הוּא (ב\\\"מ ק\\\"ה), מְנַכֶּה לוֹ מִן הַדָּמִים — לְחַסֵּר מֵהֶם מְעַט (תנחומא):\",1,0],[2,133,22,6,\"כי ידעתי וגו'. עַל יְדֵי מִלְחֶמֶת סִיחוֹן שֶׁעֲזַרְתּוֹ לְהַכּוֹת אֶת מוֹאָב:\",2,0],[2,133,22,7,\"וקסמים בידם. כָּל מִינֵי קְסָמִים, שֶׁלֹּא יֹאמַר אֵין כְּלֵי תַשְׁמִישִׁי עִמִּי; דָּ\\\"אַ — קֶסֶם זֶה נָטְלוּ בְיָדָם זִקְנֵי מִדְיָן, אָמְרוּ אִם יָבֹא עִמָּנוּ בַּפַּעַם הַזֹּאת יֵשׁ בּוֹ מַמָּשׁ, וְאִם יִדְחֵנוּ אֵין בּוֹ תוֹעֶלֶת, לְפִיכָךְ כְּשֶׁאָמַר לָהֶם \\\"לִינוּ פֹה הַלַּיְלָה\\\" אָמְרוּ אֵין בּוֹ תִקְוָה, הִנִּיחוּהוּ וְהָלְכוּ לָהֶם, שֶׁנֶּאֱמַר \\\"וַיֵּשְׁבוּ שָׂרֵי מוֹאָב עִם בִּלְעָם\\\", אֲבָל זִקְנֵי מִדְיָן הָלְכוּ לָהֶם (שם):\",1,0],[2,133,22,8,\"לינו פה הלילה. אֵין רוּחַ הַקֹּדֶשׁ שׁוֹרָה עָלָיו אֶלָּא בַּלַּיְלָה, וְכֵן לְכָל נְבִיאֵי אֻמּוֹת הָעוֹלָם, וְכֵן לָבָן בַּחֲלוֹם הַלַּיְלָה, שֶׁנֶּאֱמַר (בראשית ל\\\"א) \\\"וַיָּבֹא אֱלֹהִים אֶל לָבָן הָאֲרַמִּי בַּחֲלוֹם הַלַּיְלָה\\\" כְּאָדָם הַהוֹלֵךְ אֵצֶל פִּילַגְשׁוֹ בְּהֵחָבֵא (תנחומא; ויקרא רבה א'):\",1,0],[2,133,22,8,\"כאשר ידבר ה' אלי. אִם יַמְלִיכֵנִי לָלֶכֶת עִם בְּנֵי אָדָם כְּמוֹתְכֶם, אֵלֵךְ עִמָּכֶם, שֶׁמָּא אֵין כְּבוֹדוֹ לְתִתִּי לַהֲלֹךְ אֶלָּא עִם שָׂרִים גְּדוֹלִים מִכֶּם:\",2,0],[2,133,22,8,\"וישבו. לְשׁוֹן עַכָּבָה:\",3,0],[2,133,22,9,\"מי האנשים האלה עמך. לְהַטְעוֹתוֹ בָא, אָמַר פְּעָמִים שֶׁאֵין הַכֹּל גָּלוּי לְפָנָיו, אֵין דַּעְתּוֹ שָׁוָה עָלָיו, אַף אֲנִי אֶרְאֶה עֵת שֶׁאוּכַל לְקַלֵּל וְלֹא יָבִין (תנחומא):\",1,0],[2,133,22,10,\"בלק בן צפור וגו'. אַעַ\\\"פִּ שֶׁאֵינִי חָשׁוּב בְּעֵינֶיךָ, חָשׁוּב אֲנִי בְּעֵינֵי הַמְּלָכִים (שם):\",1,0],[2,133,22,11,\"קבה לי. זוֹ קָשָׁה מֵאָרָה לִּי, שֶׁהוּא נוֹקֵב וּמְפָרֵשׁ (שם):\",1,0],[2,133,22,11,\"וגרשתיו. מִן הָעוֹלָם, וּבָלָק לֹא אָמַר אֶלָּא וַאֲגָרְשֶׁנּוּ מִן הָאָרֶץ — אֵינִי מְבַקֵּשׁ אֶלָּא לְהַסִּיעָם מֵעָלַי, וּבִלְעָם הָיָה שׂוֹנְאָם יוֹתֵר מִבָּלָק (שם):\",2,0],[2,133,22,12,\"לא תלך עמהם. אָמַר לוֹ אִם כֵּן אֲקַלְּלֵם בִּמְקוֹמִי, אָמַר לוֹ לא תאר את העם, אָמַר לוֹ אִם כֵּן אֲבָרְכֵם, אָמַר לוֹ אֵינָם צְרִיכִים לְבִרְכָתְךָ, כי ברוך הוא, מָשָׁל, אוֹמְרִים לְצִרְעָה לֹא מִדֻּבְשֵׁךְ וְלֹא מֵעֻקְצֵךְ (שם):\",1,0],[2,133,22,13,\"להלך עמכם. אֶלָּא עִם שָׂרִים גְּדוֹלִים מִכֶּם, לָמַדְנוּ שֶׁרוּחוֹ גְבוֹהָה, וְלֹא רָצָה לְגַלּוֹת שֶׁהוּא בִרְשׁוּתוֹ שֶׁל מָקוֹם, אֶלָּא בִלְשׁוֹן גַּסּוּת, לְפִיכָךְ ויסף עוד בלק:\",1,0],[2,133,22,17,\"כי כבד אכבדך מאד. יוֹתֵר מִמַּה שֶּׁהָיִיתָ נוֹטֵל לְשֶׁעָבַר אֲנִי נוֹתֵן לְךָ (שם):\",1,0],[2,133,22,18,\"מלא ביתו כסף וזהב. לָמַדְנוּ שֶׁנַּפְשׁוֹ רְחָבָה וּמְחַמֵּד מָמוֹן אֲחֵרִים, אָמַר רָאוּי לוֹ לִתֵּן לִי כָּל כֶּסֶף וְזָהָב שֶׁלּוֹ, שֶׁהֲרֵי צָרִיךְ לִשְׂכֹּר חַיָּלוֹת רַבּוֹת, סָפֵק נוֹצֵחַ סָפֵק אֵינוֹ נוֹצֵחַ, וַאֲנִי וַדַּאי נוֹצֵחַ (שם):\",1,0],[2,133,22,18,\"לא אוכל לעבר. עַל כָּרְחוֹ גִלָּה שֶׁהוּא בִרְשׁוּת אַחֵרִים, וְנִתְנַבֵּא כָאן שֶׁאֵינוֹ יָכוֹל לְבַטֵּל הַבְּרָכוֹת שֶׁנִּתְבָּרְכוּ הָאָבוֹת מִפִּי הַשְּׁכִינָה (שם):\",2,0],[2,133,22,19,\"גם אתם. פִּיו הִכְשִׁילוֹ — גַּם אַתֶּם סוֹפְכֶם לֵילֵךְ בְּפַחֵי נֶפֶשׁ כָּרִאשׁוֹנִים:\",1,0],[2,133,22,19,\"מה יסף. לֹא יְשַׁנֶּה דְבָרָיו מִבְּרָכָה לִקְלָלָה, הַלְוַאי שֶׁלֹּא יוֹסִיף לְבָרֵךְ; כָּאן נִתְנַבֵּא שֶׁעָתִיד לְהוֹסִיף לָהֶם בְּרָכוֹת עַל יָדוֹ (שם):\",2,0],[2,133,22,20,\"אם לקרא לך. אִם הַקְּרִיאָה שֶׁלְּךָ וְסָבוּר אַתָּה לִטֹּל עָלֶיהָ שָׂכָר, קום לך אתם:\",1,0],[2,133,22,20,\"ואך. עַל כָּרְחֲךָ את הדבר אשר אדבר אליך אתו תעשה; וְאַף עַל פִּי כֵן וַיֵּלֶךְ בִּלְעָם, אָמַר שֶׁמָּא אֲפַתֶּנּוּ וְיִתְרַצֶּה:\",2,0],[2,133,22,21,\"ויחבש את אתנו. מִכָּאן שֶׁהַשִּׂנְאָה מְקַלְקֶלֶת אֶת הַשּׁוּרָה, שֶׁחָבַשׁ הוּא בְּעַצְמוֹ; אָמַר הַקָּבָּ\\\"ה רָשָׁע כְּבָר קְדָמְךָ אַבְרָהָם אֲבִיהֶם, שֶׁנֶּאֱמַר (בראשית כ\\\"ב) \\\"וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר וַיַּחֲבֹשׁ אֶת חֲמֹרוֹ\\\" (תנחומא):\",1,0],[2,133,22,21,\"עם שרי מואב. לִבּוֹ כְּלִבָּם שָׁוֶה:\",2,0],[2,133,22,22,\"כי הולך הוא. רָאָה שֶׁהַדָּבָר רַע בְּעֵינֵי הַמָּקוֹם וְנִתְאַוָּה לֵילֵךְ:\",1,0],[2,133,22,22,\"לשטן לו. מַלְאָךְ שֶׁל רַחֲמִים הָיָה, וְהָיָה רוֹצֶה לְמָנְעוֹ מִלַּחֲטֹא, שֶׁלֹּא יֶחֱטָא וְיֹאבַד (שם):\",2,0],[2,133,22,22,\"ושני נעריו עמו. מִכָּאן לְאָדָם חָשׁוּב הַיּוֹצֵא לַדֶּרֶךְ יוֹלִיךְ עִמּוֹ שְׁנֵי אֲנָשִׁים לְשַׁמְּשׁוֹ, וְחוֹזְרִים וּמְשַׁמְּשִׁים זֶה אֶת זֶה (שם):\",3,0],[2,133,22,23,\"ותרא האתון. וְהוּא לֹא רָאָה שֶׁנָּתַן הַקָּבָּ\\\"ה רְשׁוּת לַבְּהֵמָה לִרְאוֹת יוֹתֵר מִן הָאָדָם, שֶׁמִּתּוֹךְ שֶׁיֵּשׁ בּוֹ דַּעַת, תִּטָּרֵף דַּעְתּוֹ כְּשֶׁיִּרְאֶה מַזִּיקִין:\",1,0],[2,133,22,23,\"וחרבו שלופה בידו. אָמַר, רָשָׁע זֶה הִנִּיחַ כְּלִי אֻמָּנוּתוֹ, שֶׁכְּלִי זֵינָן שֶׁל אֻמּוֹת הָעוֹלָם בַּחֶרֶב, וְהוּא בָא עֲלֵיהֶם בְּפִיו שֶׁהוּא אֻמָּנוּת שֶׁלָּהֶם, אַף אֲנִי אֶתְפֹּשׂ אֶת שֶׁלּוֹ וְאָבֹא עָלָיו בְּאֻמָּנוּתוֹ, וְכֵן סוֹפוֹ — \\\"וְאֵת בִּלְעָם בֶּן בְּעוֹר הָרְגוּ בֶחָרֶב\\\" (במדבר ל\\\"א):\",2,0],[2,133,22,24,\"במשעול. כְּתַרְגּוּמוֹ \\\"בִּשְׁבִיל\\\", וְכֵן \\\"אִם יִשְׂפֹּק עֲפַר שֹׁמְרוֹן לִשְׁעָלִים\\\" (מלכים א כ') — עָפָר הַנִּדְבָּק בְּכַפּוֹת הָרַגְלַיִם בְּהִלּוּכָן, וְכֵן \\\"מִי מָדַד בְּשָׁעֳלוֹ מַיִם\\\" (ישעיהו מ') — בְּרַגְלָיו וּבְהִלּוּכוֹ:\",1,0],[2,133,22,24,\"גדר מזה וגדר מזה. סְתָם גָּדֵר שֶׁל אֲבָנִים הוּא:\",2,0],[2,133,22,25,\"ותלחץ. הִיא עַצְמָהּ:\",1,0],[2,133,22,25,\"וַתִּלְחַץ: אֶת אֲחֵרִים — את רגל בלעם:\",2,0],[2,133,22,26,\"ויוסף מלאך ה' עבור. לַעֲבֹר עוֹד לְפָנָיו — לַהֲלֹךְ לִהְיוֹת לְפָנָיו בְּמָקוֹם אַחֵר, כְּמוֹ \\\"וְהוּא עָבַר לִפְנֵיהֶם\\\" (בראשית ל\\\"ג); וּמִדְרַשׁ אַגָּדָה יֵשׁ בְּתַנְחוּמָא: מָה רָאָה לַעֲמֹד בִּשְׁלֹשָׁה מְקוֹמוֹת? סִימָנֵי אָבוֹת הֶרְאָהוּ:\",1,0],[2,133,22,28,\"זה שלש רגלים. רָמַז לוֹ: אַתָּה מְבַקֵּשׁ לַעֲקֹר אֻמָּה הַחוֹגֶגֶת שָׁלֹשׁ רְגָלִים בַּשָּׁנָה? (תנחומא):\",1,0],[2,133,22,29,\"התעללת. כְּתַרְגּוּמוֹ, לְשׁוֹן גְּנַאי וּבִזָּיוֹן:\",1,0],[2,133,22,29,\"לו יש חרב בידי. גְּנוּת גְּדוֹלָה הָיָה לוֹ דָבָר זֶה בְּעֵינֵי הַשָּׂרִים — זֶה הוֹלֵךְ לַהֲרֹג אֻמָּה שְׁלֵמָה בְּפִיו וּלְאָתוֹן זוֹ צָרִיךְ כְּלֵי זַיִן:\",2,0],[2,133,22,30,\"ההסכן הסכנתי. כְּתַרְגּוּמוֹ, וְכֵן \\\"הַלְאֵל יִסְכָּן גָּבֶר\\\" (איוב כ\\\"ב); וְרַבּוֹתֵינוּ דָרְשׁוּ מִקְרָא זֶה בַּתַּלְמוּד, אָמְרוּ לֵיהּ מַאי טַעְמָא לָא רְכַבְתְּ אַסּוּסְיָא? אֲמַר לְהוּ בִּרְטִיבָא שְׁדַאי לֵיהּ כו', כִּדְאִיתָא בְמַסֶּכֶת עֲ\\\"זָ (דף ד'):\",1,0],[2,133,22,32,\"כי ירט הדרך לנגדי. רַבּוֹתֵינוּ חַכְמֵי הַמִּשְׁנָה דְּרָשׁוּהוּ נוֹטָרִיקוֹן — יָרְאָה, רָאֲתָה, נָטְתָה בִּשְׁבִיל שֶׁהַדֶּרֶךְ לְנֶגְדִּי (שבת קכ\\\"ה), כְּלוֹמַר לְקִנְאָתִי וּלְהַקְנִיטֵנִי; וּלְפִי מַשְׁמָעוֹ כִּי חָרַד הַדֶּרֶךְ לְנֶגְדִּי, לְשׁוֹן רֶטֶט — כִּי רָאִיתִי בַעַל הַדֶּרֶךְ שֶׁחָרַד וּמִהֵר הַדֶּרֶךְ שֶׁהוּא לְכַעְסִי וּלְהַמְרוֹתִי, וּמִקְרָא קָצָר הוּא, כְּמוֹ \\\"וַתְּכַל דָּוִד\\\" (שמואל ב י\\\"ג); לִישָׁנָא אַחֲרִינָא יָרַט לְשׁוֹן רָצוֹן, וְכֵן \\\"עַל יְדֵי רְשָׁעִים יִרְטֵנִי\\\" (איוב ט\\\"ז) — מְפַיֵּס וּמְנַחֵם אוֹתִי עַל יְדֵי רְשָׁעִים שֶׁאֵינָן אֶלָּא מַקְנִיטִים:\",1,0],[2,133,22,33,\"אולי נטתה. כְּמוֹ לוּלֵי, פְּעָמִים שֶׁאוּלַי מְשַׁמֵּשׁ בִּלְשׁוֹן לוּלֵי:\",1,0],[2,133,22,33,\"גם אתכה הרגתי. הֲרֵי זֶה מִקְרָא מְסֹרָס וְהוּא כְמוֹ גַּם הָרַגְתִּי אוֹתְךָ, כְּלוֹמַר, לֹא הָעַכָּבָה בִּלְבַד קְרָאַתְךָ עַל יָדִי, כִּי גַם הַהֲרִיגָה:\",2,0],[2,133,22,33,\"ואותה החייתי. וְעַתָּה מִפְּנֵי שֶׁדִּבְּרָה וְהוֹכִיחַתְךָ, וְלֹא יָכֹלְתָּ לַעֲמֹד בְּתוֹכַחְתָּהּ — כְּמוֹ שֶׁכָּתוּב ויאמר לא — הֲרַגְתִּיהָ, שֶׁלֹּא יֹאמְרוּ, זוֹ הִיא שֶׁסִּלְּקָה בִלְעָם בְּתוֹכַחְתָּהּ וְלֹא יָכוֹל לְהָשִׁיב, שֶׁחָס הַמָּקוֹם עַל כְּבוֹד הַבְּרִיּוֹת, וְכֵן (ויקרא כ') \\\"וְהָרַגְתָּ אֶת הָאִשָּׁה וְאֶת הַבְּהֵמָה\\\", וְכֵן (שם) \\\"אֶת הַבְּהֵמָה תַּהֲרֹגוּ\\\" (תנחומא):\",3,0],[2,133,22,34,\"כי לא ידעתי. גַּם זֶה גְנוּתוֹ, וְעַל כָּרְחוֹ הוֹדָה, שֶׁהוּא הָיָה מִשְׁתַּבֵּחַ שֶׁיּוֹדֵעַ דַּעַת עֶלְיוֹן, וּפִיו הֵעִיד לֹא יָדַעְתִּי (שם):\",1,0],[2,133,22,34,\"אם רע בעיניך אשובה לי. לְהַתְרִיס נֶגֶד הַמָּקוֹם הִיא תְשׁוּבָה זוֹ, אָמַר לוֹ הוּא בְעַצְמוֹ צִוַּנִי לָלֶכֶת וְאַתָּה מַלְאָךְ מְבַטֵּל אֶת דְּבָרָיו, לָמוּד הוּא בְּכָךְ שֶׁאוֹמֵר דָּבָר וּמַלְאָךְ מַחֲזִירוֹ, אָמַר לְאַבְרָהָם \\\"קַח נָא אֶת בִּנְךָ\\\" וְגוֹ' (בראשית כ\\\"ב), וְעַל יְדֵי מַלְאָךְ בִּטֵּל אֶת דְּבָרוֹ, אַף אֲנִי אִם רַע בְּעֵינֶיךָ צָרִיךְ אֲנִי לָשׁוּב:\",2,0],[2,133,22,35,\"לך עם האנשים. בַּדֶּרֶךְ שֶׁאָדָם רוֹצֶה לֵילֵךְ בָּהּ, מוֹלִיכִין אוֹתוֹ:\",1,0],[2,133,22,35,\"לך עם האנשים. כִּי חֶלְקְךָ עִמָּהֶם וְסוֹפְךָ לֹאבַד מִן הָעוֹלָם (מכות י'):\",2,0],[2,133,22,35,\"ואפס. עַל כָּרְחֲךָ את הדבר אשר אדבר וגו':\",3,0],[2,133,22,35,\"עם שרי בלק. שָֹמַח לְקַלְּלֵם כְּמוֹתָם:\",4,0],[2,133,22,36,\"וישמע בלק. שָׁלַח שְׁלוּחִים לְבַשְּׂרוֹ:\",1,0],[2,133,22,36,\"אל עיר מואב. אֶל מֶטְרוֹפּוֹלִין שֶׁלּוֹ — עִיר הַחֲשׁוּבָה שֶׁלּוֹ, לוֹמַר רְאֵה מָה אֵלּוּ מְבַקְשִׁים לַעֲקֹר (תנחומא):\",2,0],[2,133,22,37,\"האמנם לא אוכל כבדך. נִתְנַבֵּא שֶׁסּוֹפוֹ לָצֵאת מֵעִמּוֹ בְקָלוֹן (שם):\",1,0],[2,133,22,39,\"קרית חצות. עִיר מְלֵאָה שְׁוָקִים, אֲנָשִׁים וָטַף בְּחוּצוֹתֶיהָ, לוֹמַר רְאֵה וְרַחֵם שֶׁלֹּא יֵעָקְרוּ אֵלּוּ:\",1,0],[2,133,22,40,\"בקר וצאן. דָּבָר מוּעָט:\",1,0],[2,133,22,41,\"במות בעל. כְּתַרְגּוּמוֹ, \\\"לְרָמַת דַּחַלְתֵּהּ\\\", שֵׁם עֲ\\\"זָ:\",1,0],[2,133,23,3,\"אולי יקרה ה' לקראתי. אֵינוֹ רָגִיל לְדַבֵּר עִמִּי בַּיּוֹם:\",1,0],[2,133,23,3,\"וילך שפי. כְּתַרְגּוּמוֹ יְחִידִי, לְשׁוֹן שֹׁפִי וְשֶׁקֶט, שֶׁאֵין עִמּוֹ אֶלָּא שְׁתִיקָה:\",2,0],[2,133,23,4,\"ויקר. לְשׁוֹן עֲרַאי, לְשׁוֹן גְּנַאי, לְשׁוֹן טֻמְאַת קֶרִי, כְּלוֹמַר בְּקֹשִׁי וּבְבִזָּיוֹן, וְלֹא הָיָה נִגְלֶה אֵלָיו בַּיּוֹם אֶלָּא בִּשְׁבִיל לְהַרְאוֹת חִבָּתָן שֶׁל יִשְׂרָאֵל (בראשית רבה נ\\\"ב):\",1,0],[2,133,23,4,\"את שבעת המזבחת. שִׁבְעָה מִזְבְּחֹת עָרַכְתִּי אֵין כְּתִיב כָּאן, אֶלָּא אֶת שִׁבְעַת הַמִּזְבְּחֹת, אָמַר לְפָנָיו אֲבוֹתֵיהֶם שֶׁל אֵלּוּ בָּנוּ לְפָנֶיךָ שִׁבְעָה מִזְבְּחוֹת וַאֲנִי עָרַכְתִּי כְּנֶגֶד כֻּלָּן, אַבְרָהָם בָּנָה אַרְבָּעָה — \\\"וַיִּבֶן שָׁם מִזְבֵּחַ לַה' הַנִּרְאֶה אֵלָיו\\\" (בראשית י\\\"ב), \\\"וַיַּעְתֵּק מִשָּׁם הָהָרָה\\\" וְגוֹ' (שם), \\\"וַיֶּאֱהַל אַבְרָהָם\\\" וְגוֹ' (שם י\\\"ג), וְאֶחָד בְּהַר הַמּוֹרִיָּה; וְיִצְחָק בָּנָה אֶחָד — \\\"וַיִּבֶן שָׁם מִזְבֵּחַ\\\" וְגוֹ' (שם כ\\\"ו), וְיַעֲקֹב בָּנָה שְׁתַּיִם, אֶחָד בִּשְׁכֶם וְאֶחָד בְּבֵית אֵל:\",2,0],[2,133,23,4,\"ואעל פר ואיל במזבח. וְאַבְרָהָם לֹא הֶעֱלָה אֶלָּא אַיִל אֶחָד (תנחומא צו):\",3,0],[2,133,23,7,\"ארה לי יעקב ולכה זעמה ישראל. בִּשְׁנֵי שְׁמוֹתֵיהֶם אָמַר לוֹ לְקַלְּלָם שֶׁמָּא אֶחָד מֵהֶם אֵינוֹ מֻבְהָק:\",1,0],[2,133,23,8,\"מה אקב לא קבה אל. כְּשֶׁהָיוּ רְאוּיִים לְהִתְקַלֵּל לֹא נִתְקַלְּלוּ — כְּשֶׁהִזְכִּיר אֲבִיהֶם אֶת עֲוֹנָם \\\"כִּי בְאַפָּם הָרְגוּ אִישׁ\\\", לֹא קִלֵּל אֶלָּא אַפָּם, שֶׁנֶּאֱמַר \\\"אָרוּר אַפָּם\\\" (בראשית מ\\\"ט); כְּשֶׁנִּכְנַס אֲבִיהֶם בְּמִרְמָה אֵצֶל אָבִיו הָיָה רָאוּי לְהִתְקַלֵּל, מַה נֶּאֱמַר שָׁם? \\\"גַּם בָּרוּךְ יִהְיֶה\\\" (שם כ\\\"ז), בַּמְבָרְכִים נֶאֱמַר \\\"אֵלֶּה יַעַמְדוּ לְבָרֵךְ אֶת הָעָם\\\", בַּמְקַלְּלִים לֹא נֶאֱמַר וְאֵלֶּה יַעַמְדוּ לְקַלֵּל אֶת הָעָם אֶלָּא \\\"וְאֵלֶּה יַעַמְדוּ עַל הַקְּלָלָה\\\" (דברים כ\\\"ז) — לֹא רָצָה לְהַזְכִּיר עֲלֵיהֶם שֵׁם קְלָלָה (תנחומא):\",1,0],[2,133,23,8,\"לא זעם ה'. אֲנִי אֵין כֹּחִי אֶלָּא שֶׁאֲנִי יוֹדֵעַ לְכַוֵּן הַשָּׁעָה שֶׁהַקָּבָּ\\\"ה כוֹעֵס בָּהּ, וְהוּא לֹא כָעַס כָּל הַיָּמִים הַלָּלוּ שֶׁבָּאתִי אֵלֶיךָ, וְזֶהוּ שֶׁנֶּאֱמַר (מיכה ו') \\\"עַמִּי זְכָר נָא מַה יָּעַץ\\\" וְגוֹ' \\\"וּמֶה עָנָה אֹתוֹ בִּלְעָם\\\" וְגוֹ' \\\"לְמַעַן דַּעַת צִדְקוֹת ה'\\\" (סנהדרין ק\\\"ה):\",2,0],[2,133,23,9,\"כי מראש צרים אראנו. אֲנִי מִסְתַּכֵּל בְּרֵאשִׁיתָם וּבִתְחִלַּת שָׁרְשֵׁיהֶם וַאֲנִי רוֹאֶה אוֹתָם מְיֻסָּדִים וַחֲזָקִים כְּצוּרִים וּגְבָעוֹת הַלָּלוּ עַל יְדֵי אָבוֹת וְאִמָּהוֹת (תנחומא):\",1,0],[2,133,23,9,\"הן עם לבדד ישכן. הוּא אֲשֶׁר זָכוּ לוֹ אֲבוֹתָיו — לִשְׁכֹּן בָּדָד, כְּתַרְגּוּמוֹ:\",2,0],[2,133,23,9,\"ובגוים לא יתחשב. כְּתַרְגּוּמוֹ, לֹא יִהְיוּ נַעֲשִׂין כָּלָה עִם שְׁאָר הָאֻמּוֹת, שֶׁנֶּאֱמַר (ירמיהו ל') \\\"כִּי אֶעֱשֶׂה כָלָה בְּכָל הַגּוֹיִם\\\" וְגוֹ', אֵינָן נִמְנִין עִם הַשְּׁאָר. דָּ\\\"אַ — כְּשֶׁהֵן שְׂמֵחִין אֵין אֻמָּה שְׂמֵחָה עִמָּהֶם, שֶׁנֶּאֱמַר \\\"ה' בָּדָד יַנְחֶנּוּ\\\" (דברים ל\\\"ב), וּכְשֶׁהָאֻמּוֹת בְּטוֹבָה הֵן אוֹכְלִין עִם כָּל אֶחָד וְאֶחָד וְאֵין עוֹלֶה לָהֶם מִן הַחֶשְׁבּוֹן, וְזֶהוּ ובגוים לא יתחשב (תנחומא):\",3,0],[2,133,23,10,\"מי מנה עפר יעקב וגו'. כְּתַרְגּוּמוֹ \\\"דַּעְדְּקַיָּא דְבֵית יַעֲקֹב\\\", מֵאַרְבַּע מַשִּׁרְיָתָא — מֵאַרְבָּעָה דְּגָלִים; דָּ\\\"אַ, עֲפַר יַעֲקֹב, אֵין חֶשְׁבּוֹן בַּמִּצְוֹת שֶׁהֵם מְקַיְּמִין בְּעָפָר, \\\"לֹא תַחֲרֹשׁ בְּשׁוֹר וּבַחֲמֹר\\\" (דברים כ\\\"ב), \\\"לֹא תִזְרַע כִּלְאָיִם\\\" (ויקרא י\\\"ט), אֵפֶר פָּרָה וַעֲפַר סוֹטָה וְכַיּוֹצֵא בָהֶם (תנחומא):\",1,0],[2,133,23,10,\"ומספר את רבע ישראל. רְבִיעוֹתֵיהֶן, זֶרַע הַיּוֹצֵא מִן הַתַּשְׁמִישׁ שֶׁלָּהֶם (עי' נדה ל\\\"א):\",2,0],[2,133,23,10,\"תמת נפשי מות ישרים. שֶׁבָּהֶם:\",3,0],[2,133,23,13,\"וקבנו לי. לְשׁוֹן צִוּוּי, קַלְּלֵהוּ לִי:\",1,0],[2,133,23,14,\"שדה צפים. מָקוֹם גָּבוֹהַּ הָיָה שֶׁשָּׁם הַצּוֹפֶה עוֹמֵד לִשְׁמֹר אִם יָבֹא חַיִל עַל הָעִיר:\",1,0],[2,133,23,14,\"ראש הפסגה. בִּלְעָם לֹא הָיָה קוֹסֵם כְּבָלָק, רָאָה בָלָק שֶׁעֲתִידָה פִרְצָה לְהִפָּרֵץ בְּיִשָׂרָאֵל מִשָּׁם, שֶׁשָּׁם מֵת מֹשֶׁה, כְּסָבוּר שֶׁשָּׁם תָּחוּל עֲלֵיהֶם הַקְּלָלָה וְזוֹ הִיא הַפִּרְצָה שֶׁאֲנִי רוֹאֶה (תנחומא):\",2,0],[2,133,23,15,\"אקרה כה. מֵאֵת הַקָּבָּ\\\"ה, אקרה — לְשׁוֹן אִתְפַּעֵל:\",1,0],[2,133,23,16,\"וישם דבר בפיו. וּמַה הִיא הַשִּׂימָה הַזֹּאת? וּמֶה חָסֵר הַמִּקְרָא בְּאָמְרוֹ \\\"שׁוּב אֶל בָּלָק וְכֹה תְדַבֵּר\\\"? אֶלָּא כְּשֶׁהָיָה שׁוֹמֵעַ שֶׁאֵינוֹ נִרְשֶׁה לְקַלֵּל אָמַר מָה אֲנִי חוֹזֵר אֵצֶל בָּלָק לְצַעֲרוֹ? וְנָתַן לוֹ הַקָּבָּ\\\"ה רֶסֶן וְחַכָּה בְּפִיו, כְּאָדָם הַפּוֹקֵס בְּהֵמָה בְּחַכָּה לְהוֹלִיכָהּ אֶל אֲשֶׁר יִרְצֶה, אָמַר לוֹ עַל כָּרְחֲךָ תָּשׁוּב אֶל בָּלָק (שם):\",1,0],[2,133,23,17,\"ושרי מואב אתו. וּלְמַעְלָה הוּא אוֹמֵר \\\"וְכָל שָׂרֵי מוֹאָב\\\", כֵּיוָן שֶׁרָאוּ שֶׁאֵין בּוֹ תִקְוָה הָלְכוּ לָהֶם מִקְצָתָם וְלֹא נִשְׁאֲרוּ אֶלָּא מִקְצָתָם:\",1,0],[2,133,23,17,\"מה דבר ה'. לְשׁוֹן צְחוֹק הוּא זֶה, כְּלוֹמַר אֵינְךָ בִרְשׁוּתְךָ (שם):\",2,0],[2,133,23,18,\"קום בלק. כֵּיוָן שֶׁרָאָהוּ מְצַחֵק בּוֹ, נִתְכַּוֵּן לְצַעֲרוֹ — \\\"עֲמֹד עַל רַגְלֶיךָ, אֵינְךָ רַשַּׁאי לֵישֵׁב, וַאֲנִי שָׁלוּחַ אֵלֶיךָ בִשְׁלִיחוּתוֹ שֶׁל מָקוֹם\\\" (שם):\",1,0],[2,133,23,18,\"בנו צפר. לְשׁוֹן מִקְרָא הוּא זֶה, כְּמוֹ \\\"חַיְתוֹ יָעַר\\\" (תהלים נ') \\\"וְחַיְתוֹ אֶרֶץ\\\" (בראשית א'), \\\"לְמַעְיְנוֹ מָיִם\\\" (תהילים קי\\\"ד):\",2,0],[2,133,23,19,\"לא איש וגו'. כְּבָר נִשְׁבַּע לָהֶם לַהֲבִיאָם וּלְהוֹרִישָׁם אֶרֶץ שִׁבְעָה אֻמּוֹת וְאַתָּה סָבוּר לַהֲמִיתָם בַּמִּדְבָּר?:\",1,0],[2,133,23,19,\"ההוא אמר וגו'. בִּלְשׁוֹן תֵּמַהּ, וְתַרְגּוּמוֹ וְתָיְבִין וּמִתְמַלְּכִין — חוֹזְרִים וְנִמְלָכִין לַחֲזֹר בָּהֶם:\",2,0],[2,133,23,20,\"הנה ברך לקחתי. אַתָּה שׁוֹאֲלֵנִי \\\"מַה דִּבֶּר ה'?\\\", קִבַּלְתִּי מִמֶּנּוּ לְבָרֵךְ אוֹתָם:\",1,0],[2,133,23,20,\"וברך ולא אשיבנה. הוּא בֵּרֵךְ אוֹתָם וַאֲנִי לֹא אָשִׁיב אֶת בִּרְכָתוֹ:\",2,0],[2,133,23,20,\"וברך. כְּמוֹ וּבִרֵּךְ, וְכֵן הִיא גִזְרַת רֵי\\\"ש, כְּמוֹ (תהלים ע\\\"ד) \\\"אוֹיֵב חֵרֵף\\\" כְּמוֹ חִרֵּף, וְכֵן (שם מ') \\\"וּבֹצֵעַ בֵּרֵךְ\\\" — הַמְהַלֵּל וּמְבָרֵךְ אֶת הַגּוֹזֵל וְאוֹמֵר אַל תִּירָא כִּי לֹא תֵעָנֵשׁ, שָׁלוֹם יִהְיֶה לְךָ, מַרְגִּיז הוּא לְהַקָּבָּ\\\"ה; וְאֵין לוֹמַר ברך שֵׁם דָּבָר, שֶׁאִם כֵּן הָיָה נָקוּד בְּפַתָּ\\\"ח קָטָן וְטַעְמוֹ לְמַעְלָה, אֲבָל לְפִי שֶׁהוּא לְשׁוֹן פִּעֵל, הוּא נָקוּד קָמָץ קָטָן וְטַעְמוֹ לְמַטָּה:\",3,0],[2,133,23,21,\"לא הביט און ביעקב וגו'. כְּתַרְגּוּמוֹ; דָּבָר אַחֵר אַחֲרֵי פְשׁוּטוֹ הוּא נִדְרָשׁ מִדְרָשׁ נָאֶה —\",1,0],[2,133,23,21,\"לא הביט. הַקָּבָּ\\\"ה און שֶׁבְּיַעֲקֹב — כְּשֶׁהֵן עוֹבְרִין עַל דְּבָרָיו אֵינוֹ מְדַקְדֵּק אַחֲרֵיהֶם לְהִתְבּוֹנֵן בְּאוֹנִיּוֹת שֶׁלָּהֶם וַעֲמָלָן שֶׁהֵן עוֹבְרִין עַל דָּתוֹ:\",2,0],[2,133,23,21,\"עמל. לְשׁוֹן עֲבֵרָה, כְּמוֹ \\\"וְהָרָה עָמָל\\\" (תהלים ז'), \\\"כִּי אַתָּה עָמָל וָכַעַס תַּבִּיט\\\" (שם י'), לְפִי שֶׁהָעֲבֵרָה הִיא עָמָל לִפְנֵי הַמָּקוֹם:\",3,0],[2,133,23,21,\"ה' אלהיו עמו. אֲפִלּוּ מַכְעִיסִין וּמַמְרִים לְפָנָיו, אֵינוֹ זָז מִתּוֹכָן:\",4,0],[2,133,23,21,\"ותרועת מלך בו. לְשׁוֹן חִבָּה וְרֵעוּת, כְּמוֹ (שמואל ב ט\\\"ו) \\\"רֵעֶה דָּוִד\\\" — אוֹהֵב דָּוִד, (שופטים ט\\\"ו) \\\"וַיִּתְּנָהּ לְמֵרֵעֵהוּ\\\", וְכֵן תִּרְגֵּם אֻנְקְלוֹס \\\"וּשְׁכִינַת מַלְכְּהוֹן בֵּינֵהוֹן\\\":\",5,0],[2,133,23,22,\"אל מוציאם ממצרים. אַתָּה אָמַרְתָּ \\\"הִנֵּה עַם יָצָא מִמִּצְרַיִם\\\", לֹא יָצָא מֵעַצְמוֹ, אֶלָּא הָאֱלֹהִים הוֹצִיאָם:\",1,0],[2,133,23,22,\"כתועפת ראם לו. כְּתֹקֶף רוּם וְגֹבַהּ שֶׁלּוֹ, וְכֵן \\\"וְכֶסֶף תּוֹעָפוֹת\\\" (איוב כ\\\"ב) לְשׁוֹן מָעוֹז הֵמָּה, וְאוֹמֵר אֲנִי שֶׁהוּא לְשׁוֹן \\\"וְעוֹף יְעוֹפֵף\\\" (בראשית א') — הַמְעוֹפֵף בְּרוּם וְגֹבַהּ, תֹקֶף רַב הוּא זֶה, וְתוֹעֲפֹת רְאֵם — עֲפִיפַת גֹּבַהּ; דָּ\\\"אַ, תּוֹעֲפוֹת רְאֵם — תֹּקֶף רְאֵמִים, וְאָמְרוּ רַבּוֹתֵינוּ אֵלּוּ הַשֵּׁדִים (עי' גיטין ס\\\"ח):\",2,0],[2,133,23,23,\"כי לא נחש ביעקב. כִּי רְאוּיִים הֵם לִבְרָכָה, שֶׁאֵין בָּהֶם מְנַחֲשִׁים וְקוֹסְמִים:\",1,0],[2,133,23,23,\"כעת יאמר ליעקב וגו'. עוֹד עָתִיד לִהְיוֹת עֵת כָּעֵת הַזֹּאת אֲשֶׁר תִּגָּלֶה חִבָּתָן לְעֵין כֹּל, שֶׁהֵן יוֹשְׁבִין לְפָנָיו וּלְמֵדִים תּוֹרָה מִפִּיו וּמְחִצָּתָן לִפְנִים מִמַּלְאֲכֵי הַשָּׁרֵת וְהֵם יִשְׁאֲלוּ לָהֶם מה פעל אל? וְזֶהוּ שֶׁנֶּאֱמַר (ישעיהו ל') \\\"וְהָיוּ עֵינֶיךָ רֹאוֹת אֶת מוֹרֶיךָ\\\". דָּ\\\"אַ — יאמר ליעקב אֵינוֹ לְשׁוֹן עָתִיד אֶלָּא לְשׁוֹן הֹוֶה, אֵינָן צְרִיכִין לִמְנַחֵשׁ וְקוֹסֵם, כִּי בְכָל עֵת שֶׁצָּרִיךְ לְהֵאָמֵר לְיַעֲקֹב וּלְיִשְׂרָאֵל מַה פָּעַל הַקָּבָּ\\\"ה וּמַה גְּזֵרוֹתָיו בַּמָּרוֹם, אֵינָן מְנַחֲשִׁים וְקוֹסְמִים אֶלָּא נֶאֱמַר לָהֶם עַל פִּי נְבִיאֵיהֶם מַה הִיא גְזֵרַת הַמָּקוֹם, אוֹ אוּרִים וְתֻמִּים מַגִּידִים לָהֶם (תנחומא); וְאֻנְקְלוֹס לֹא תִרְגֵּם כֵּן:\",2,0],[2,133,23,24,\"הן עם כלביא יקום וגו'. כְּשֶׁהֵן עוֹמְדִין מִשְּׁנָתָם שַׁחֲרִית, הֵן מִתְגַּבְּרִין כְּלָבִיא וְכַאֲרִי לַחֲטֹף אֶת הַמִּצְוֹת — לִלְבֹּשׁ טַלִּית, לִקְרֹא אֶת שְׁמַע וּלְהָנִיחַ תְּפִלִּין:\",1,0],[2,133,23,24,\"לא ישכב. בַּלַּיְלָה עַל מִטָּתוֹ עַד שֶׁהוּא אוֹכֵל וּמְחַבֵּל כָּל מַזִּיק הַבָּא לְטָרְפוֹ, כֵּיצַד? קוֹרֵא אֶת שְׁמַע עַל מִטָּתוֹ וּמַפְקִיד רוּחוֹ בְּיַד הַמָּקוֹם, בָּא מַחֲנֶה וְגַיִס לְהַזִּיקָם, הַקָּבָּ\\\"ה שׁוֹמְרָם וְנִלְחָם מִלְחֲמוֹתָם וּמַפִּילָם חֲלָלִים (שם); דָּ\\\"אַ — הן עם כלביא יקום וגו', כְּתַרְגּוּמוֹ:\",2,0],[2,133,23,24,\"ודם חללים ישתה. נִתְנַבֵּא שֶׁאֵין מֹשֶׁה מֵת עַד שֶׁיַּפִּיל מַלְכֵי מִדְיָן חֲלָלִים וְיֵהָרֵג הוּא עִמָּהֶם, שֶׁנֶּאֱמַר (יהושע י\\\"ג) \\\"וְאֶת בִּלְעָם בֶּן בְּעוֹר הַקּוֹסֵם הָרְגוּ בְנֵי יִשְׂרָאֵל בַּחֶרֶב אֶל חַלְלֵיהֶם\\\" (עי' תנחומא):\",3,0],[2,133,23,25,\"גם קב לא תקבנו. גַם רִאשׁוֹן מוֹסִיף עַל גַּם הַשֵּׁנִי וְגַם הַשֵּׁנִי עַל גַּם רִאשׁוֹן, וְכֵן \\\"גַּם לִי גַם לָךְ לֹא יִהְיֶה\\\" (מלכים א ג'), וְכֵן \\\"גַּם בָּחוּר גַּם בְּתוּלָה\\\" (דברים ל\\\"ב):\",1,0],[2,133,23,27,\"וקבתו לי. אֵין זֶה לְשׁוֹן צִוּוּי כְּמוֹ וְקָבְנוֹ, אֶלָּא לְשׁוֹן עָתִיד — אוּלַי יִישַׁר בְּעֵינָיו וְתִקָּבֶנּוּ לִי מִשָּׁם, מלדי\\\"רש בְּלַעַז:\",1,0],[2,133,23,28,\"ראש הפעור. קוֹסֵם גָּדוֹל הָיָה בָלָק וְרָאָה שֶׁהֵן עֲתִידִין לִלְקוֹת עַל יְדֵי פְעוֹר, וְלֹא הָיָה יוֹדֵעַ בַּמֶּה, אָמַר שֶׁמָּא הַקְּלָלָה תָחוּל עֲלֵיהֶם מִשָּׁם וְכֵן כָּל הַחוֹזִים בַּכּוֹכָבִים רוֹאִים וְאֵינָם יוֹדְעִים מָה רוֹאִים (סוטה י\\\"ב):\",1,0],[2,133,24,1,\"וירא בלעם כי טוב וגו'. אָמַר אֵינִי צָרִיךְ לִבְדֹּק עוֹד בְּהַקָּבָּ\\\"ה, כִּי לֹא יַחְפֹּץ לְקַלְּלָם:\",1,0],[2,133,24,1,\"לא הלך כפעם בפעם. כַּאֲשֶׁר עָשָׂה שְׁתֵּי פְעָמִים:\",2,0],[2,133,24,1,\"לקראת נחשים. לְנַחֵשׁ אוּלַי יִקָּרֶה ה' לִקְרָתוֹ כִּרְצוֹנוֹ, אָמַר רוֹצֶה וְלֹא רוֹצֶה לְקַלְּלָם, אַזְכִּיר עֲוֹנוֹתֵיהֶם, וְהַקְּלָלָה עַל הַזְכָּרַת עֲוֹנוֹתֵיהֶם תָּחוּל:\",3,0],[2,133,24,1,\"וישת אל המדבר פניו. כְּתַרְגּוּמוֹ:\",4,0],[2,133,24,2,\"וישא בלעם את עיניו. בִּקֵּשׁ לְהַכְנִיס בָּהֶם עַיִן רָעָה, וַהֲרֵי יֵשׁ לְךָ שָׁלֹשׁ מִדּוֹתָיו — עַיִן רָעָה וְרוּחַ גְּבוֹהָה וְנֶפֶשׁ רְחָבָה הָאֲמוּרִים לְמַעְלָה:\",1,0],[2,133,24,2,\"שכן לשבטיו. רָאָה כָל שֵׁבֶט וְשֵׁבֶט שׁוֹכֵן לְעַצְמוֹ וְאֵינָן מְעֹרָבִין, רָאָה שֶׁאֵין פִּתְחֵיהֶם מְכֻוָּנִין זֶה כְנֶגֶד זֶה, שֶׁלֹּא יָצִיץ לְתוֹךְ אֹהֶל חֲבֵרוֹ:\",2,0],[2,133,24,2,\"ותהי עליו רוח אלהים. עָלָה בְלִבּוֹ שֶׁלֹּא יְקַלְּלֵם:\",3,0],[2,133,24,3,\"בנו בער. כְּמוֹ \\\"לְמַעְיְנוֹ מָיִם\\\" (תהלים קי\\\"ד); וּמִ\\\"אַ שְׁנֵיהֶם הָיוּ גְדוֹלִים מֵאֲבוֹתֵיהֶם, בָּלָק בְּנוֹ צִפּוֹר — אָבִיו בְּנוֹ הוּא בְמַלְכוּת, וּבִלְעָם גָּדוֹל מֵאָבִיו בִּנְבִיאוּת — מָנֶה בֶן פְּרָס הָיָה (סנהדרין ק\\\"ה; תנחומא):\",1,0],[2,133,24,3,\"שתם העין. עֵינוֹ נְקוּרָה וּמוּצֵאת לַחוּץ וְחֹר שֶׁלָּהּ נִרְאֶה פָתוּחַ, וּלְשׁוֹן מִשְׁנָה הוּא, כְּדֵי שֶׁיִשְׁתֹּם וְיִסְתֹּם וְיִגֹּב (עבודה זרה ס\\\"ט); וְרַבּוֹתֵינוּ אָמְרוּ, לְפִי שֶׁאָמַר וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל — שֶׁהַקָּבָּ\\\"ה יוֹשֵׁב וּמוֹנֶה רְבִיעוֹתֵיהֶן שֶׁל יִשְׂרָאֵל, מָתַי תָּבֹא טִפָּה שֶׁנּוֹלַד הַצַּדִּיק מִמֶּנּוּ, אָמַר בְּלִבּוֹ, מִי שֶׁהוּא קָדוֹשׁ וּמְשָׁרְתָיו קְדוֹשִׁים יִסְתַּכֵּל בִּדְבָרִים הַלָּלוּ? וְעַל דָּבָר זֶה נִסְמַת עֵינוֹ שֶׁל בִּלְעָם (נדה ל\\\"א); וְיֵשׁ מְפָרְשִׁים שתם העין — פְּתוּחַ הָעַיִן, כְּמוֹ שֶׁתִּרְגֵּם אֻנְקְלוֹס, וְעַל שֶׁאָמַר שְׁתֻם הָעָיִן וְלֹא אָמַר שְׁתוּם הָעֵינַיִם, לָמַדְנוּ שֶׁסּוּמָא בְאַחַת מֵעֵינָיו הָיָה (סנהדרין ק\\\"ה):\",2,0],[2,133,24,4,\"נפל וגלוי עינים. פְּשׁוּטוֹ כְתַרְגּוּמוֹ — שֶׁאֵין נִרְאֶה עָלָיו אֶלָּא בַּלַּיְלָה כְּשֶׁהוּא שׁוֹכֵב; וּמִדְרָשׁוֹ: כְּשֶׁהָיָה נִגְלֶה עָלָיו לֹא הָיָה בוֹ כֹּחַ לַעֲמֹד עַל רַגְלָיו וְנוֹפֵל עַל פָּנָיו, לְפִי שֶׁהָיָה עָרֵל, וּמָאוּס לִהְיוֹת נִגְלֶה עָלָיו בְּקוֹמָה זְקוּפָה לְפָנָיו:\",1,0],[2,133,24,5,\"מה טבו אהליך. עַל שֶׁרָאָה פִתְחֵיהֶם שֶׁאֵינָן מְכֻוָּנִין זֶה מוּל זֶה:\",1,0],[2,133,24,5,\"משכנתיך. חֲנִיּוֹתֶיךָ, כְּתַרְגּוּמוֹ; דָּבָר אַחֵר, מה טבו אהליך — מַה טֹּבוּ אֹהֶל שִׁילֹה וּבֵית עוֹלָמִים בְּיִשּׁוּבָן, שֶׁמַּקְרִיבִין בָּהֶן קָרְבָּנוֹת לְכַפֵּר עֲלֵיכֶם:\",2,0],[2,133,24,5,\"משכנתיך. אַף כְּשֶׁהֵן חֲרֵבִין, לְפִי שֶׁהֵן מַשְׁכּוֹן עֲלֵיכֶם, וְחֻרְבָּנָן כַּפָּרָה עַל הַנְּפָשׁוֹת, שֶׁנֶּאֱמַר \\\"כִּלָּה ה' אֶת חֲמָתוֹ\\\" (איכה ד'), וּבַמֶּה כִלָּה? (שם) \\\"וַיַּצֶּת אֵשׁ בְּצִיּוֹן\\\" (תנחומא משפטים):\",3,0],[2,133,24,6,\"כנחלים נטיו. שֶׁנֶּאֶרְכוּ וְנִמְשְׁכוּ לִנְטוֹת לְמֵרָחוֹק; אָמְרוּ רַבּוֹתֵינוּ מִבִּרְכוֹתָיו שֶׁל אוֹתוֹ רָשָׁע אָנוּ לְמֵדִים מֶה הָיָה בְלִבּוֹ לְקַלְּלָם כְּשֶׁאָמַר לְהָשִׁית אֶל הַמִּדְבָּר פָּנָיו, וּכְשֶׁהָפַךְ הַמָּקוֹם אֶת פִּיו, בֵּרְכָם מֵעֵין אוֹתָם קְלָלוֹת שֶׁבִּקֵּשׁ לוֹמַר כו', כִּדְאִיתָא בְחֵלֶק (סנהדרין ק\\\"ה ב):\",1,0],[2,133,24,6,\"כאהלים. כְּתַרְגּוּמוֹ, לְשׁוֹן \\\"מֹר וַאֲהָלוֹת\\\" (תהלים מ\\\"ה):\",2,0],[2,133,24,6,\"נטע ה'. בְּגַן עֵדֶן; לָשׁוֹן אַחֵר כאהלים נטע ה' — כַּשָּׁמַיִם הַמְּתוּחִין כְּאֹהֶל:\",3,0],[2,133,24,6,\"נטע ה'. לְשׁוֹן נְטִיעָה מָצִינוּ בְאֹהָלִים, שֶׁנֶּאֱמַר \\\"וְיִטַּע אָהֳלֵי אַפַּדְנוֹ\\\" (דניאל י\\\"א):\",4,0],[2,133,24,7,\"מדליו. מִבְּאֵרוֹתָיו, וּפֵרוּשׁוֹ כְּתַרְגּוּמוֹ:\",1,0],[2,133,24,7,\"וזרעו במים רבים. לְשׁוֹן הַצְלָחָה הוּא זֶה — כְּזֶרַע הַזָּרוּעַ עַל פְּנֵי הַמַּיִם:\",2,0],[2,133,24,7,\"וירם מאגג מלכו. מֶלֶךְ רִאשׁוֹן שֶׁלָּהֶם יִכְבֹּשׁ אֶת אֲגַג מֶלֶךְ עֲמָלֵק:\",3,0],[2,133,24,7,\"ותנשא מלכתו. שֶׁל יַעֲקֹב יוֹתֵר וְיוֹתֵר, שֶׁיָּבֹא אַחֲרָיו דָּוִד וּשְׁלֹמֹה:\",4,0],[2,133,24,8,\"אל מוציאו ממצרים. מִי גוֹרֵם לָהֶם הַגְּדֻלָּה הַזֹּאת? אֵל הַמּוֹצִיאָם מִמִּצְרַיִם בְּתֹקֶף וְרוּם שֶׁלּוֹ, יֹאכַל אֶת הַגּוֹיִם שֶׁהֵם צָרָיו:\",1,0],[2,133,24,8,\"ועצמתיהם. שֶׁל צָרִים:\",2,0],[2,133,24,8,\"יגרם. מְנַחֵם פָּתַר בּוֹ לְשׁוֹן שְׁבִירָה, וְכֵן \\\"לֹא גָרְמוּ לַבֹּקֶר\\\" (צפניה ג'), וְכֵן \\\"וְאֶת חֲרָשֶׂיהָ תְּגָרֵמִי\\\" (יחזקאל כ\\\"ג), וַאֲנִי אוֹמֵר לְשׁוֹן עֶצֶם הוּא, שֶׁמְּגָרֵר הַבָּשָׂר בְּשִׁנָּיו מִסָּבִיב, וְהַמֹּחַ שֶׁבִּפְנִים, וּמַעֲמִיד הָעֶצֶם עַל עַרְמִימוּתוֹ:\",3,0],[2,133,24,8,\"וחציו ימחץ. אֻנְקְלוֹס תִּרְגֵּם חֶצְיוֹ שֶׁל צָרִים — חֲלֻקָּה שֶׁלָּהֶם, כְּמוֹ (בראשית מ\\\"ט) \\\"בַּעֲלֵי חִצִּים\\\" — מָרֵי פַּלְגּוּתָא, וְכֵן יִמְחָץ לְשׁוֹן \\\"וּמָחֲצָה וְחָלְפָה רַקָּתוֹ\\\" (שופטים ה') — שֶׁיֶחֱצוּ אֶת אַרְצָם. וְיֵשׁ לִפְתֹּר לְשׁוֹן חִצִּים מַמָּשׁ — חִצָּיו שֶׁל הַקָּבָּ\\\"ה יִמְחַץ בְּדָמָם שֶׁל צָרִים, יִטְבֹּל וְיִצְטַבַּע בְּדָמָם, כְּמוֹ \\\"לְמַעַן תִּמְחַץ רַגְלְךָ בְּדָם\\\" (תהלים ס\\\"ח), וְאֵינוֹ זָז מִלָּשׁוֹן מַכָּה, כְּמוֹ \\\"מָחַצְתִּי\\\" (דברים ל\\\"ב), שֶׁהַצָּבוּעַ בְּדָם נִרְאֶה כְּאִלּוּ מָחוּץ וְנָגוּעַ:\",4,0],[2,133,24,9,\"כרע שכב כארי. כְּתַרְגּוּמוֹ — יִתְיַשְּׁבוּ בְאַרְצָם בְּכֹחַ וּגְבוּרָה:\",1,0],[2,133,24,10,\"ויספק. הִכָּה זוֹ עַל זוֹ:\",1,0],[2,133,24,13,\"לעבר את פי ה'. כָּאן לֹא נֶאֱמַר \\\"אֱלֹהַי\\\" כְּמוֹ שֶׁנֶּאֱמַר בָּרִאשׁוֹנָה (כ\\\"ב י\\\"ח), לְפִי שֶׁיָּדַע שֶׁנִּבְאַשׁ בְּהַקָּבָּ\\\"ה וְנִטְרַד:\",1,0],[2,133,24,14,\"הולך לעמי. מֵעַתָּה הֲרֵינִי כִשְׁאָר עַמִּי, שֶׁנִּסְתַּלֵּק הַקָּבָּ\\\"ה מֵעָלָיו:\",1,0],[2,133,24,14,\"לכה איעצך. מַה לְּךָ לַעֲשׂוֹת, וּמַה הִיא הָעֵצָה? אֱלֹהֵיהֶם שֶׁל אֵלּוּ שׂוֹנֵא זִמָּה הוּא כו', כִּדְאִיתָא בְחֵלֶק (סנהדרין ק\\\"ו); תֵּדַע שֶׁבִּלְעָם הִשִּׂיא עֵצָה זוֹ לְהַכְשִׁילָם בְּזִמָּה, שֶׁהֲרֵי נֶאֱמַר \\\"הֵן הֵנָּה הָיוּ לִבְנֵי יִשְׂרָאֵל בִּדְבַר בִּלְעָם\\\" (במדבר ל\\\"א):\",2,0],[2,133,24,14,\"אשר יעשה העם הזה לעמך. מִקְרָא קָצָר הוּא זֶה: אִיעָצְךָ לְהַכְשִׁילָם וְאֹמַר לְךָ מַה שֶּׁהֵן עֲתִידִין לְהָרַע לְמוֹאָב בְּאַחֲרִית הַיָּמִים — \\\"וּמָחַץ פַּאֲתֵי מוֹאָב\\\"; הַתַּרְגּוּם מְפָרֵשׁ קֹצֶר הָעִבְרִי:\",3,0],[2,133,24,16,\"וידע דעת עליון. לְכַוֵּן הַשָּׁעָה שֶׁכּוֹעֵס בָּהּ (סנהדרין ק\\\"ה):\",1,0],[2,133,24,17,\"אראנו. רוֹאֶה אֲנִי שִׁבְחוֹ שֶׁל יַעֲקֹב וּגְדֻלָּתוֹ, אַךְ לֹא עַתָּה הִיא, אֶלָּא לְאַחַר זְמַן:\",1,0],[2,133,24,17,\"דרך כוכב. כְּתַרְגּוּמוֹ, לְשׁוֹן \\\"דָּרַךְ קַשְׁתּוֹ\\\" (איכה ב'), שֶׁהַכּוֹכָב עוֹבֵר כְּחֵץ, וּבְלַעַז דישט\\\"נט, כְּלוֹמַר יָקוּם מַזָּל:\",2,0],[2,133,24,17,\"וקם שבט. מֶלֶךְ רוֹדֶה וּמוֹשֵׁל:\",3,0],[2,133,24,17,\"ומחץ פאתי מואב. זֶה דָוִד שֶׁנֶּאֱמַר בּוֹ \\\"הַשְׁכֵּב אוֹתָם אַרְצָה וַיְמַדֵּד שְׁנֵי חֲבָלִים לְהָמִית\\\" וְגוֹ' (שמואל ב ח'):\",4,0],[2,133,24,17,\"וקרקר. לְשׁוֹן קוֹרֶה, כְּמוֹ \\\"אֲנִי קַרְתִּי\\\" (מלכים ב י\\\"ט), \\\"מַקֶּבֶת בּוֹר נֻקַּרְתֶּם\\\" (ישעיהו נ\\\"א), \\\"יִקְּרוּהָ עֹרְבֵי נַחַל\\\" (משלי ל'), פורי\\\"ר בְּלַעַ\\\"ז:\",5,0],[2,133,24,17,\"כל בני שת. כָּל הָאֻמּוֹת, שֶׁכֻּלָּם יָצְאוּ מִן שֵׁת בְּנוֹ שֶׁל אָדָם הָרִאשׁוֹן:\",6,0],[2,133,24,18,\"והיה ירשה שעיר. לְאוֹיְבָיו יִשְׂרָאֵל:\",1,0],[2,133,24,19,\"וירד מיעקב. וְעוֹד יִהְיֶה מוֹשֵׁל אַחֵר מִיַּעֲקֹב:\",1,0],[2,133,24,19,\"והאביד שריד מעיר. הַחֲשׁוּבָה שֶׁל אֱדוֹם, הִיא רוֹמִי, וְעַל מֶלֶךְ הַמָּשִׁיחַ אוֹמֵר כֵּן, שֶׁנֶּאֱמַר בּוֹ \\\"וְיֵרְדְּ מִיָּם עַד יָם\\\" (תהלים ע\\\"ב) \\\"וְלֹא יִהְיֶה שָׂרִיד לְבֵית עֵשָׂו\\\" (עוב' י\\\"ח):\",2,0],[2,133,24,20,\"וירא את עמלק. נִסְתַּכֵּל בְּפֻרְעֲנוּתוֹ שֶׁל עֲמָלֵק:\",1,0],[2,133,24,20,\"ראשית גוים עמלק. הוּא קָדַם אֶת כֻּלָּם לְהִלָּחֵם בְּיִשְׂרָאֵל — וְכָךְ תִּרְגֵּם אֻנְקְלוֹס — ואחריתו לֵאָבֵד בְּיָדָם, שֶׁנֶּאֱמַר \\\"תִּמְחֶה אֶת זֵכֶר עֲמָלֵק\\\" (דברים כ\\\"ה):\",2,0],[2,133,24,21,\"וירא את הקיני. לְפִי שֶׁהָיָה קֵינִי תָּקוּעַ אֵצֶל עֲמָלֵק, כָּעִנְיָן שֶׁנֶּאֱמַר \\\"וַיֹּאמֶר שָׁאוּל אֶל הַקֵּינִי\\\" וְגוֹ' (שמואל א ט\\\"ו), הִזְכִּירוֹ אַחַר עֲמָלֵק; נִסְתַּכֵּל בִּגְדֻלָּתָן שֶׁל בְּנֵי יִתְרוֹ שֶׁנֶּאֱמַר בָּהֶם (דבהי\\\"א ב') \\\"תִּרְעָתִים שִׁמְעָתִים שׂוּכָתִים\\\" (ספרי במדבר י'; סנהדרין ק\\\"ד):\",1,0],[2,133,24,21,\"איתן מושבך. תָּמֵהַּ אֲנִי מֵהֵיכָן זָכִיתָ לְכָךְ הֲלֹא אַתָּה עִמִּי הָיִיתָ בַּעֲצַת \\\"הָבָה נִתְחַכְּמָה לוֹ\\\" (שמות א'), וְעַתָּה נִתְיַשַּׁבְתָּ בְאֵיתָן וּמָעוֹז שֶׁל יִשְׂרָאֵל (סנהדרין ק\\\"ו):\",2,0],[2,133,24,22,\"כי אם יהיה לבער קין וגו'. אַשְׁרֶיךָ שֶׁנִּתְקַעְתָּ לְתֹקֶף זֶה, שֶׁאֵינְךָ נִטְרָד עוֹד מִן הָעוֹלָם, כִּי אַף אִם אַתָּה עָתִיד לִגְלוֹת עִם עֲשֶׂרֶת הַשְּׁבָטִים, וְתִהְיֶה לְבָעֵר מִמָּקוֹם שֶׁנִּתְיַשַּׁבְתָּ שָׁם, מַה בְּכָךְ?\",1,0],[2,133,24,22,\"עד מה אשור תשבך. עַד הֵיכָן הוּא מַגְלֶה אוֹתְךָ? שֶׁמָּא לַחְלַח וְחָבוֹר? אֵין זֶה טֵרוּד מִן הָעוֹלָם, אֶלָּא טִלְטוּל מִמָּקוֹם לְמָקוֹם, וְתָשׁוּב עִם שְׁאָר הַגָּלֻיּוֹת:\",2,0],[2,133,24,23,\"וישא משלו וגו'. כֵּיוָן שֶׁהִזְכִּיר אֶת שְׁבִיַּת אַשּׁוּר, אָמַר אוי מי יחיה משמו אל, מִי יָכוֹל לְהַחֲיוֹת אֶת עַצְמוֹ מִשּׂוּמוֹ אֶת אֵלֶּה — שֶׁלֹּא יָשִׂים עָלָיו הַגּוֹזֵר אֶת אֵלֶּה, שֶׁיַּעֲמֹד סַנְחֵרִיב וִיבַלְבֵּל אֶת כָּל הָאֻמּוֹת, וְעוֹד יָבֹאוּ:\",1,0],[2,133,24,24,\"צים מיד כתים. וְיַעַבְרוּ כִתִּיִּים, שֶׁהֵן רוֹמִיִּים, בְּבִירָנִיּוֹת גְּדוֹלוֹת עַל אַשּׁוּר:\",1,0],[2,133,24,24,\"וענו עבר. וְעִנּוּ אוֹתָם שֶׁבְּעֵבֶר הַנָּהָר:\",2,0],[2,133,24,24,\"וגם הוא עדי אבד. וְכֵן פֵּרֵשׁ דָּנִיֵּאל \\\"עַד דִּיקְטִילַת חֵיוְתָא וְהוּבַד גִּשְׁמַהּ\\\" (דניאל ז'):\",3,0],[2,133,24,24,\"וצים. סְפִינוֹת גְּדוֹלוֹת, כְּדִכְתִיב (ישעיהו ל\\\"ג) \\\"וְצִי אַדִּיר\\\", תַּרְגּוּמוֹ \\\"וּבוּרְנִי רַבְּתָא\\\" (יומא ע\\\"ז):\",4,0],[2,133,25,1,\"בשטים. כָּךְ שְׁמָהּ:\",1,0],[2,133,25,1,\"לזנות אל בנות מואב. עַל יְדֵי עֲצַת בִּלְעָם, כִּדְאִיתָא בְחֵלֶק (סנהדרין ק\\\"ו):\",2,0],[2,133,25,2,\"וישתחוו לאלהיהן. כְּשֶׁתָּקַף יִצְרוֹ וְאוֹמֵר לָהּ הִשָּׁמְעִי לִי, וְהִיא מוֹצִיאָה לוֹ דְּמוּת פְּעוֹר מֵחֵיקָהּ וְאוֹמֶרֶת לוֹ הִשְׁתַּחֲוֵה לָזֶה:\",1,0],[2,133,25,3,\"פעור. עַל שֵׁם שֶׁפּוֹעֲרִין לְפָנָיו פִּי הַטַּבַּעַת וּמוֹצִיאִין רְעִי, וְזוֹ הִיא עֲבוֹדָתוֹ (סנהדרין ס'):\",1,0],[2,133,25,3,\"ויחר אף ה' בישראל. שָׁלַח בָּהֶם מַגֵּפָה:\",2,0],[2,133,25,4,\"קח את כל ראשי העם. לִשְׁפֹּט אֶת הָעוֹבְדִים לִפְעוֹר:\",1,0],[2,133,25,4,\"והוקע אותם. אֶת הָעוֹבְדִים:\",2,0],[2,133,25,4,\"והוקע. הִיא תְלִיָּה, כְּמוֹ שֶׁמָּצִינוּ בִּבְנֵי שָׁאוּל \\\"וְהוֹקַעֲנוּם לַה'\\\" (שמואל ב כ״א:ו׳) וְשָׁם תְּלִיָּה מְפֹרֶשֶׁת (סנהדרין ל\\\"ד); עֲ\\\"זָ בִּסְקִילָה וְכָל הַנִּסְקָלִין נִתְלִין (סנהדרין מ\\\"ה):\",3,0],[2,133,25,4,\"נגד השמש. לְעֵין כֹּל. וּמִ\\\"אַ: הַשֶּׁמֶשׁ מוֹדִיעַ אֶת הַחוֹטְאִים, הֶעָנָן נִקְפָּל מִכְּנֶגְדּוֹ וְהַחַמָּה זוֹרַחַת עָלָיו:\",4,0],[2,133,25,5,\"הרגו איש אנשיו. כָּל אֶחָד וְאֶחָד מִדַּיָּנֵי יִשְׂרָאֵל הָיָה הוֹרֵג שְׁנַיִם, וְדַּיָּנֵי יִשְֹרָאֵל שְׁמוֹנַת רִבּוֹא וּשְׁמוֹנַת אֲלָפִים כִּדְאִיתָא בְסַנְהֶ' (דף י\\\"ח:):\",1,0],[2,133,25,6,\"והנה איש מבני ישראל בא. נִתְקַבְּצוּ שִׁבְטוֹ שֶׁל שִׁמְעוֹן אֵצֶל זִמְרִי שֶׁהָיָה נָשִׂיא שֶׁלָּהֶם, אָמְרוּ לוֹ, אָנוּ נִדּוֹנִין בְּמִיתָה וְאַתָּה יוֹשֵׁב וְכוּ' כִּדְאִיתָא בְּאֵלּוּ הֵן הַנִּשְׂרָפִין (סנהדרין פ\\\"ב):\",1,0],[2,133,25,6,\"את המדינית. כָּזְבִּי בַת צוּר:\",2,0],[2,133,25,6,\"לעיני משה. אָמְרוּ לוֹ, מֹשֶׁה, זוֹ אֲסוּרָה אוֹ מֻתֶּרֶת? אִם תֹּאמַר אֲסוּרָה, בַּת יִתְרוֹ מִי הִתִּירָהּ לְךָ, וְכוּ', כִּדְאִיתָא הָתָם:\",3,0],[2,133,25,6,\"והמה בכים. נִתְעַלְּמָה מִמֶּנּוּ הֲלָכָה, גָּעוּ כֻלָּם בִּבְכִיָּה; בָּעֵגֶל עָמַד מֹשֶׁה כְּנֶגֶד שִׁשִּׁים רִבּוֹא, שֶׁנֶּאֱמַר \\\"וַיִּטְחַן עַד אֲשֶׁר דָּק\\\" וְגוֹ' (שמות ל\\\"ב), וְכָאן רָפוּ יָדָיו? אֶלָּא כְּדֵי שֶׁיָּבֹא פִינְחָס וְיִטֹּל אֶת הָרָאוּי לוֹ (תנחומא):\",4,0],[2,133,25,7,\"וירא פינחס. רָאָה מַעֲשֶׂה וְנִזְכַּר הֲלָכָה — אָמַר לוֹ לְמֹשֶׁה מְקֻבַּלְנִי מִמְּךָ הַבּוֹעֵל אֲרַמִּית קַנָּאִין פּוֹגְעִין בּוֹ. אָמַר לוֹ \\\"קַרְיָנָא דְּאִגַּרְתָּא אִיהוּ לֶיהֱוֵי פַּרְוַנְקָא\\\", מִיָּד ויקח רמח בידו וגו' (סנהדרין פ\\\"ב):\",1,0],[2,133,25,8,\"אל הקבה. אֶל הָאֹהֶל:\",1,0],[2,133,25,8,\"אל קבתה. כְּמוֹ \\\"וְהַלְּחָיַיִם וְהַקֵּבָה\\\" (דברים י\\\"ח), כִּוֵּן בְּתוֹךְ זַכְרוּת שֶׁל זִמְרִי וְנַקְבוּת שֶׁלָּהּ וְרָאוּ כֻלָּם שֶׁלֹא לְחִנָּם הֲרָגָם, וְהַרְבֵּה נִסִּים נַעֲשׂוּ לוֹ כו', כִּדְאִיתָא הָתָם:\",2,0],[2,133,25,11,\"פינחס בן אלעזר בן אהרן הכהן. לְפִי שֶׁהָיוּ הַשְּׁבָטִים מְבַזִּים אוֹתוֹ — הַרְאִיתֶם בֶּן פּוּטִי זֶה שֶׁפִּטֵּם אֲבִי אִמּוֹ עֲגָלִים לַעֲ\\\"זָ וְהָרַג נְשִׂיא שֵׁבֶט מִיִּשְׂרָאֵל? לְפִיכָךְ בָּא הַכָּתוּב וְיִחֲסוֹ אַחַר אַהֲרֹן (סנהדרין פ\\\"ב):\",1,0],[2,133,25,11,\"בקנאו את קנאתי. בְּנָקְמוֹ אֶת נִקְמָתִי — בְּקָצְפּוֹ אֶת הַקֶּצֶף שֶׁהָיָה לִי לִקְצֹף; כָּל לְשׁוֹן קִנְאָה הוּא הַמִּתְחָרֶה לִנְקֹם נִקְמַת דָּבָר, אנפרט\\\"מנט בְּלַעַ\\\"ז:\",2,0],[2,133,25,12,\"את בריתי שלום. שֶׁתְּהֵא לוֹ לִבְרִית שָׁלוֹם, כְּאָדָם הַמַּחֲזִיק טוֹבָה וְחַנּוֹת לְמִי שֶׁעוֹשֶׂה עִמּוֹ טוֹבָה, אַף כָּאן פֵּרֵשׁ לוֹ הַקָּבָּ\\\"ה שְׁלוֹמוֹתָיו:\",1,0],[2,133,25,13,\"והיתה לו. בְרִיתִי זֹאת:\",1,0],[2,133,25,13,\"ברית כהנת עולם. שֶׁאַף עַל פִּי שֶׁכְּבָר נִתְּנָה כְהֻנָּה לְזַרְעוֹ שֶׁל אַהֲרֹן, לֹא נִתְּנָה אֶלָּא לְאַהֲרֹן וּלְבָנָיו שֶׁנִּמְשְׁחוּ עִמּוֹ וּלְתוֹלְדוֹתֵיהֶן שֶׁיּוֹלִידוּ אַחַר הַמְשָׁחָתָן, אֲבָל פִּינְחָס שֶׁנּוֹלַד קֹדֶם לָכֵן וְלֹא נִמְשַׁח לֹא בָא לִכְלַל כְּהֻנָּה עַד כָּאן; וְכֵן שָׁנִינוּ בִזְבָחִים (דף ק\\\"א) לֹא נִתְכַּהֵן פִּינְחָס עַד שֶׁהֲרָגוֹ לְזִמְרִי:\",2,0],[2,133,25,13,\"לאלהיו. בִּשְׁבִיל אֱלֹהָיו, כְּמוֹ \\\"הַמְקַנֵּא אַתָּה לִי\\\" (במדבר י\\\"א), \\\"וְקִנֵּאתִי לְצִיּוֹן\\\" (זכריה ח') — בִּשְׁבִיל צִיּוֹן:\",3,0],[2,133,25,14,\"ושם איש ישראל וגו'. בְּמָקוֹם שֶׁיִּחֵס אֶת הַצַּדִּיק לְשֶׁבַח, יִחֵס אֶת הָרָשָׁע לִגְנַאי (תנחומא):\",1,0],[2,133,25,14,\"נשיא בית אב לשמעני. לְאֶחָד מֵחֲמֵשֶׁת בָּתֵּי אָבוֹת שֶׁהָיוּ לְשֵׁבֶט שִׁמְעוֹן; דָּ\\\"אַ — לְהוֹדִיעַ שִׁבְחוֹ שֶׁל פִּינְחָס, שֶׁאַף עַל פִּי שֶׁזֶּה הָיָה נָשִׂיא, לֹא מָנַע אֶת עַצְמוֹ מִלְּקַנֵּא לְחִלּוּל הַשֵּׁם, לְכָךְ הוֹדִיעֲךָ הַכָּתוּב מִי הוּא הַמֻּכֶּה:\",2,0],[2,133,25,15,\"ושם האשה המכה וגו'. לְהוֹדִיעֲךָ שִׂנְאָתָן שֶׁל מִדְיָנִים — שֶׁהִפְקִירוּ בַּת מֶלֶךְ לִזְנוּת כְּדֵי לְהַחֲטִיא אֶת יִשְׂרָאֵל (שם):\",1,0],[2,133,25,15,\"ראש אמות. אֶחָד מֵחֲמֵשֶׁת מַלְכֵי מִדְיָן \\\"אֶת אֱוִי וְאֶת רֶקֶם וְאֶת צוּר\\\" וְגוֹ' (במדבר ל״א:ח׳), וְהוּא הָיָה חָשׁוּב מִכֻּלָּם, שֶׁנֶּאֱמַר \\\"רֹאשׁ אֻמּוֹת\\\", וּלְפִי שֶׁנָּהַג בִּזָּיוֹן בְּעַצְמוֹ לְהַפְקִיר בִּתּוֹ, מְנָאוֹ שְׁלִישִׁי (שם):\",2,0],[2,133,25,15,\"בית אב. חֲמִשָּׁה בָתֵּי אָבוֹת הָיוּ לְמִדְיָן: \\\"עֵיפָה וָעֵפֶר וַחֲנֹךְ וַאֲבִידָע וְאֶלְדָּעָה\\\" (בראשית כ\\\"ה), וְזֶה הָיָה מֶלֶךְ לְאֶחָד מֵהֶם:\",3,0],[2,133,25,17,\"צרור. כְּמוֹ זָכוֹר, שָׁמוֹר, לְשׁוֹן הוֹוֶה — עֲלֵיכֶם לְאַיֵּב אוֹתָם:\",1,0],[2,133,25,18,\"כי צוררים הם לכם וגו' על דבר פעור. שֶׁהִפְקִירוּ בְּנוֹתֵיהֶם לִזְנוּת, כְּדֵי לְהַטְעוֹתְכֶם אַחַר פְּעוֹר. וְאֶת מוֹאָב לֹא צִוָּה לְהַשְׁמִיד, מִפְּנֵי רוּת שֶׁהָיְתָה עֲתִידָה לָצֵאת מֵהֶם, כִּדְאָמְרִינַן בְּבָבָא קַמָּא (לח ב):\",1,0],[2,133,26,1,\"ויהי אחרי המגפה וגו'. מָשָׁל לְרוֹעֶה שֶׁנִּכְנְסוּ זְאֵבִים לְתוֹךְ עֶדְרוֹ וְהָרְגוּ בָהֶן וְהוּא מוֹנֶה אוֹתָן לֵידַע מִנְיַן הַנּוֹתָרוֹת; דָּבָר אַחֵר — כְּשֶׁיָּצְאוּ מִמִּצְרַיִם וְנִמְסְרוּ לְמֹשֶׁה נִמְסְרוּ לוֹ בְּמִנְיָן, עַכְשָׁו שֶׁקָּרַב לָמוּת וּלְהַחֲזִיר צֹאנוֹ מַחֲזִירָן בְּמִנְיָן (תנחומא):\",1,0],[2,133,26,2,\"לבית אבתם. עַל שֵׁבֶט הָאָב יִתְיַחֲסוּ וְלֹא אַחַר הָאֵם (בבא בתרא ק\\\"ט):\",1,0],[2,133,26,3,\"וידבר משה ואלעזר הכהן אתם. דִּבְּרוּ עִמָּם עַל זֹאת שֶׁצִּוָּה הַמָּקוֹם לִמְנוֹתָם:\",1,0],[2,133,26,3,\"לאמר. אָמְרוּ לָהֶם צְרִיכִים אַתֶּם לִמָּנוֹת מבן עשרים שנה ומעלה:\",2,0],[2,133,26,4,\"כאשר צוה וגו'. שֶׁיְּהֵא מִנְיָנָם מִבֶּן עֶשְֹרִים שָׁנָה וָמַעְלָה, שֶׁנֶּאֱמַר \\\"כָּל הָעֹבֵר עַל הַפְּקֻדִים\\\" וגו' (שמות ל'):\",1,0],[2,133,26,5,\"משפחת החנכי. לְפִי שֶׁהָיוּ הָאֻמּוֹת מְבַזִּין אוֹתָם וְאוֹמְרִים מָה אֵלּוּ מִתְיַחֲסִין עַל שִׁבְטֵיהֶם? סְבוּרִים הֵם שֶׁלֹּא שָׁלְטוּ הַמִּצְרִיִּים בְּאִמּוֹתֵיהֶם? אִם בְּגוּפָם הָיוּ מוֹשְׁלִים, קַל וָחֹמֶר בִּנְשׁוֹתֵיהֶם, לְפִיכָךְ הִטִּיל הַקָּבָּ\\\"ה שְׁמוֹ עֲלֵיהֶם — ה\\\"א מִצַּד זֶה וְיוֹ\\\"ד מִצַּד זֶה — לוֹמַר, מֵעִיד אֲנִי עֲלֵיהֶם שֶׁהֵם בְּנֵי אֲבוֹתֵיהֶם, וְזֶה הוּא שֶׁמְּפֹרָשׁ עַל יְדֵי דָוִד (תהילים קכ\\\"ב) \\\"שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל\\\" — הַשֵּׁם הַזֶּה מֵעִיד עֲלֵיהֶם לְשִׁבְטֵיהֶם, לְפִיכָךְ בְּכֻלָּם כָּתַב הַחֲנֹכִי, הַפַּלֻּאִי, אֲבָל בְּיִמְנָה לֹא הֻצְרַךְ לוֹמַר \\\"מִשְׁפַּחַת הַיִּמְנִי\\\" לְפִי שֶׁהַשֵּׁם קָבוּעַ בּוֹ — יוֹ\\\"ד בָּרֹאשׁ וה\\\"א בַּסּוֹף (ילקוט שמעוני):\",1,0],[2,133,26,9,\"אשר הצו. אֶת יִשְׂרָאֵל על משה:\",1,0],[2,133,26,9,\"בהצתם. אֶת הָעָם על ה':\",2,0],[2,133,26,9,\"הצו. הִשִּׂיאוּ אֶת יִשְׂרָאֵל לָרִיב עַל מֹשֶׁה, לְשׁוֹן הִפְעִילוּ:\",3,0],[2,133,26,10,\"ויהיו לנס. לְאוֹת וּלְזִכָּרוֹן, \\\"לְמַעַן אֲשֶׁר לֹא יִקְרַב אִישׁ זָר\\\" (במדבר י\\\"ז) לַחֲלֹק עוֹד עַל הַכְּהֻנָּה:\",1,0],[2,133,26,11,\"ובני קרח לא מתו. הֵם הָיוּ בָעֵצָה תְּחִלָּה, וּבִשְׁעַת הַמַּחֲלֹקֶת הִרְהֲרוּ תְשׁוּבָה בְלִבָּם, לְפִיכָךְ נִתְבַּצֵּר לָהֶם מָקוֹם גָּבוֹהַ בַּגֵיהִנּוֹם וְיָשְׁבוּ שָׁם (סנהדרין ק\\\"י):\",1,0],[2,133,26,13,\"לזרח. הוּא צֹחַר, לְשׁוֹן צֹהַר, אֲבָל מִשְׁפַּחַת אֹהַד בָּטְלָה, וְכֵן חָמֵשׁ מִשֵּׁבֶט בִּנְיָמִין, שֶׁהֲרֵי בַּעֲשָׂרָה בָנִים יָרַד לְמִצְרַיִם וְכָאן לֹא מָנָה אֶלָּא חֲמִשָּׁה, וְכֵן אֶצְבּוֹן לְגָד, הֲרֵי שֶׁבַע מִשְׁפָּחוֹת (תנחומא); וּמָצָאתִי בְתַלְמוּד יְרוּשַׁלְמִי שֶׁכְּשֶׁמֵּת אַהֲרֹן נִסְתַּלְּקוּ עַנְנֵי כָבוֹד, וּבָאוּ הַכְּנַעֲנִים לְהִלָּחֵם בְּיִשְׂרָאֵל, וְנָתְנוּ לֵב לַחֲזֹר לְמִצְרַיִם, וְחָזְרוּ לַאֲחוֹרֵיהֶם שְׁמוֹנֶה מַסָּעוֹת — מֵהֹר הָהָר לְמוֹסֵרָה — שֶׁנֶּאֱמַר \\\"וּבְנֵי יִשְׂרָאֵל נָסְעוּ מִבְּאֵרֹת בְּנֵי יַעֲקָן מוֹסֵרָה שָׁם מֵת אַהֲרֹן\\\" (דברים י'), וַהֲלֹא בְהֹר הָהָר מֵת וּמִמּוֹסֵרָה עַד הֹר הָהָר שְׁמוֹנֶה מַסָּעוֹת יֵשׁ לְמַפְרֵעַ? אֶלָּא שֶׁחָזְרוּ לַאֲחוֹרֵיהֶם וְרָדְפוּ בְנֵי לֵוִי אַחֲרֵיהֶם לְהַחֲזִירָם וְהָרְגוּ מֵהֶם שֶׁבַע מִשְׁפָּחוֹת, וּמִבְּנֵי לֵוִי נָפְלוּ אַרְבַּע מִשְׁפָּחוֹת: מִשְׁפַּחַת שִׁמְעִי וְעֻזִּיאֵלִי, וּמִבְּנֵי יִצְהָר לֹא נִמְנוּ כָּאן אֶלָּא מִשְׁפַּחַת הַקָּרְחִי, וְהָרְבִיעִית לֹא יָדַעְתִּי מַה הִיא (תלמוד ירושלמי סוטה א'); וְרַבִּי תַּנְחוּמָא דָרַשׁ שֶׁמֵּתוּ בַּמַּגֵּפָה בִּדְבַר בִּלְעָם, אֲבָל לְפִי הַחִסָּרוֹן שֶׁחָסַר מִשֵּׁבֶט שִׁמְעוֹן בְּמִנְיָן זֶה מִמִּנְיָן הָרִאשׁוֹן שֶׁבְּמִדְבַּר סִינַי, נִרְאֶה שֶׁכָּל כ\\\"ד אֶלֶף נָפְלוּ מִשִּׁבְטוֹ שֶׁל שִׁמְעוֹן:\",1,0],[2,133,26,16,\"לאזני. אוֹמֵר אֲנִי שֶׁזּוֹ מִשְׁפַּחַת אֶצְבּוֹן (בראשית מ\\\"ו), וְאֵינִי יוֹדֵעַ לָמָּה לֹא נִקְרֵאת מִשְׁפַּחְתּוֹ עַל שְׁמוֹ:\",1,0],[2,133,26,24,\"לישוב. הוּא יוֹב הָאָמוּר בְּיוֹרְדֵי מִצְרַיִם, כִּי כָל הַמִּשְׁפָּחוֹת נִקְרְאוּ עַל שֵׁם יוֹרְדֵי מִצְרַיִם, וְהַנּוֹלָדִין מִשָּׁם וָהָלְאָה לֹא נִקְרְאוּ הַמִּשְׁפָּחוֹת עַל שְׁמָם, חוּץ מִמִּשְׁפְּחוֹת אֶפְרַיִם וּמְנַשֶּׁה שֶׁנּוֹלְדוּ כֻלָּם בְּמִצְרַיִם, וְאַרְדְּ וְנַעֲמָן בְּנֵי בֶלַע בֶּן בִּנְיָמִין; וּמָצָאתִי בִיסוֹדוֹ שֶׁל רַבִּי מֹשֶׁה הַדַּרְשָׁן, שֶׁיָּרְדָה אִמָּן מִמִּצְרַיִם כְּשֶׁהָיְתָה מְעֻבֶּרֶת מֵהֶם, לְכָךְ נֶחְלְקוּ לְמִשְׁפָּחוֹת כְּחֶצְרוֹן וְחָמוּל שֶׁהָיוּ בְנֵי בָנִים לִיהוּדָה, וְחֶבֶר וּמַלְכִּיאֵל שֶׁהָיוּ בְנֵי בָנִים שֶׁל אָשֵׁר; וְאִם אַגָּדָה הִיא הֲרֵי טוֹב, וְאִם לָאו, אוֹמֵר אֲנִי שֶׁהָיוּ לְבֶלַע בְּנֵי בָנִים הַרְבֵּה, וּמִשְּׁנַיִם הַלָּלוּ, אַרְדְּ וְנַעֲמָן, יָצְאָה מִכָּל אֶחָד מִשְׁפָּחָה רַבָּה, וְנִקְרְאוּ תוֹלְדוֹת שְׁאָר הַבָּנִים עַל שֵׁם בֶּלַע, וְתוֹלְדוֹת הַשְּׁנַיִם הַלָּלוּ נִקְרְאוּ עַל שְׁמָם, וְכֵן אֲנִי אוֹמֵר בִּבְנֵי מָכִיר שֶׁנֶּחְלְקוּ לִשְׁתֵּי מִשְׁפָּחוֹת, אַחַת נִקְרֵאת עַל שְׁמוֹ, וְאַחַת נִקְרֵאת עַל שֵׁם גִּלְעָד בְּנוֹ; חָמֵשׁ מִשְׁפָּחוֹת חָסְרוּ מִבָּנָיו שֶׁל בִּנְיָמִין, כָּאן נִתְקַיְּמָה מִקְצַת נְבוּאַת אִמּוֹ שֶׁקְּרָאַתּוּ בֶן אוֹנִי — בֶּן אֲנִינוּתִי, וּבְפִילֶגֶשׁ בְּגִבְעָה (שופטים כ') נִתְקַיְּמָה כֻּלָּה. זוֹ מָצָאתִי בִיסוֹדוֹ שֶׁל רַ' מֹשֶׁה הַדַּרְשָׁן:\",1,0],[2,133,26,36,\"ואלה בני שותלח וגו'. שְׁאָר בְּנֵי שׁוּתֶלַח נִקְרְאוּ תוֹלְדוֹתֵיהֶם עַל שֵׁם שׁוּתֶלַח, וּמֵעֵרָן יָצְאָה מִשְׁפָּחָה רַבָּה וְנִקְרֵאת עַל שְׁמוֹ, וְנֶחְשְׁבוּ בְנֵי שׁוּתֶלַח לִשְׁתֵּי מִשְׁפָּחוֹת, צֵא וַחֲשֹׁב וְתִמְצָא בְּפָרָשָׁה זוֹ חֲמִשִּׁים וְשֶׁבַע מִשְׁפָּחוֹת וּמִבְּנֵי לֵוִי שְׁמוֹנֶה הֲרֵי שִׁשִּׁים וְחָמֵשׁ, וְזֶהוּ שֶׁנֶּאֱמַר \\\"כִּי אַתֶּם הַמְעַט\\\" וְגוֹ' — ה\\\"א מְעַט, חָמֵשׁ אַתֶּם חֲסֵרִים מִמִּשְׁפְּחוֹת כָּל הָעַמִּים, שֶׁהֵן שִׁבְעִים. אַף זוֹ הֵבַנְתִּי מִיסוֹדוֹ שֶׁל רַבִּי מֹשֶׁה הַדַּרְשָׁן, אַךְ הֻצְרַכְתִּי לִפְחֹת וּלְהוֹסִיף בִּדְבָרָיו:\",1,0],[2,133,26,38,\"לאחירם. הוּא אֵחִי שֶׁיָּרַד לְמִצְרַיִם, וּלְפִי שֶׁנִּקְרָא עַל שֵׁם יוֹסֵף שֶׁהָיָה אָחִיו וְרָם מִמֶּנּוּ נִקְרָא אֲחִירָם:\",1,0],[2,133,26,39,\"לשפופם. הוּא מֻפִּים, עַל שֵׁם שֶׁהָיָה יוֹסֵף שָׁפוּף בֵּין הָאֻמּוֹת:\",1,0],[2,133,26,42,\"לשוחם. הוּא חֻשִׁים:\",1,0],[2,133,26,46,\"ושם בת אשר שרח. לְפִי שֶׁהָיְתָה קַיֶּמֶת בְּחַיֶּיהָ מְנָאָהּ כָּאן (סדר עולם):\",1,0],[2,133,26,53,\"לאלה תחלק הארץ. וְלֹא לַפְּחוּתִים מִבֶּן עֶשְׂרִים אַעַ\\\"פִּ שֶׁבָּאוּ לִכְלַל עֶשְׂרִים בְּטֶרֶם חִלּוּק הָאָרֶץ; שֶׁהֲרֵי שֶׁבַע שָׁנִים כָּבְשׁוּ וְשֶׁבַע חִלְּקוּ, לֹא נָטְלוּ חֵלֶק בָּאָרֶץ אֶלָּא אֵלּוּ שֵׁשׁ מֵאוֹת אֶלֶף וָאֶלֶף, וְאִם הָיוּ לְאֶחָד מֵהֶם שִׁשָּׁה בָנִים לֹא נָטְלוּ אֶלָּא חֵלֶק אֲבִיהֶם לְבַדּוֹ (בבא בתרא קי\\\"ז):\",1,0],[2,133,26,54,\"לרב תרבה נחלתו. לְשֵׁבֶט שֶׁהָיָה מְרֻבֶּה בְּאֻכְלוּסִין נָתְנוּ חֵלֶק רַב, וְאַף עַל פִּי שֶׁלֹא הָיוּ הַחֲלָקִים שָׁוִים, שֶׁהֲרֵי הַכֹּל לְפִי רִבּוּי הַשֵּׁבֶט חָלְקוּ הַחֲלָקִים, לֹא עָשׂוּ אֶלָּא עַ\\\"יְ גוֹרָל, וְהַגּוֹרָל הָיָה עַל פִּי רוּחַ הַקֹּדֶשׁ, כְּמוֹ שֶׁמְּפֹרָשׁ בְּבָבָא בַתְרָא (דף קכ\\\"ב): אֶלְעָזָר הַכֹּהֵן הָיָה מְלֻבָּשׁ בְּאוּרִים וְתֻמִּים וְאוֹמֵר בְּרוּחַ הַקֹּדֶשׁ אִם שֵׁבֶט פְּלוֹנִי עוֹלֶה, תְּחוּם פְּלוֹנִי עוֹלֶה עִמּוֹ, וְהַשְּׁבָטִים הָיוּ כְתוּבִים בִּשְׁנֵים עָשָׂר פְּתָקִין וְי\\\"ב גְּבוּלִין בְּי\\\"ב פְּתָקִין, וּבְלָלוּם בַּקַּלְפִּי, וְהַנָּשִׂיא מַכְנִיס יָדוֹ לְתוֹכוֹ וְנוֹטֵל שְׁנַיִם פְּתָקִין, עוֹלֶה בְיָדוֹ פֶּתֶק שֶׁל שֵׁם שִׁבְטוֹ וּפֶתֶק שֶׁל גְּבוּל הַמְפֹרָשׁ לוֹ, וְהַגּוֹרָל עַצְמוֹ הָיָה צוֹוֵחַ וְאוֹמֵר אֲנִי הַגּוֹרָל עָלִיתִי לִגְבוּל פְּלוֹנִי לְשֵבֶט פְּלוֹנִי, שֶׁנֶּאֱמַר \\\"עַל פִּי הַגּוֹרָל\\\", וְלֹא נִתְחַלְּקָה הָאָרֶץ בְּמִדָּה, לְפִי שֶׁיֵּשׁ גְּבוּל מְשֻׁבָּח מֵחֲבֵרוֹ, אֶלָּא בְשׁוּמָא, בֵּית כֹּר רַע כְּנֶגֶד בֵּית סְאָה טוֹב, הַכֹּל לְפִי הַדָּמִים:\",1,0],[2,133,26,55,\"לשמות מטות אבתם. אֵלּוּ יוֹצְאֵי מִצְרַיִם; שִׁנָּה הַכָּתוּב נַחֲלָה זוֹ מִכָּל הַנְּחָלוֹת שֶׁבַּתּוֹרָה, שֶׁכָּל הַנְּחָלוֹת הַחַיִּים יוֹרְשִׁים אֶת הַמֵּתִים וְכָאן מֵתִים יוֹרְשִׁים אֶת הַחַיִּים, כֵּיצַד? שְׁנֵי אַחִים מִיּוֹצְאֵי מִצְרַיִם שֶׁהָיוּ לָהֶם בָּנִים בְּבָאֵי הָאָרֶץ, לָזֶה אֶחָד וְלָזֶה שְׁלֹשָׁה, הָאֶחָד נָטַל חֵלֶק אֶחָד וְהַשְּׁלֹשָׁה נָטְלוּ שְׁלֹשָׁה, שֶׁנֶּאֱמַר לָאֵלֶּה תֵּחָלֵק הָאָרֶץ, חָזְרָה נַחֲלָתָן אֵצֶל אֲבִי אֲבִיהֶן וְחָלְקוּ הַכֹּל בְּשָׁוֶה, וְזֶהוּ שֶׁנֶּאֱמַר לשמות מטות אבתם ינחלו — שֶׁאַחַר שֶׁנָּטְלוּ הַבָּנִים, חִלְּקוּהָ לְפִי הָאָבוֹת שֶׁיָּצְאוּ מִמִּצְרַיִם, וְאִלּוּ מִתְּחִלָּה חִלְּקוּהָ לְמִנְיַן יוֹצְאֵי מִצְרַיִם לֹא הָיוּ נוֹטְלִין אֵלּוּ הָאַרְבָּעָה אֶלָּא שְׁנֵי חֲלָקִים, עַכְשָׁו נָטְלוּ אַרְבָּעָה חֲלָקִים (ספרי; בבא בתרא קי\\\"ז):\",1,0],[2,133,26,55,\"אך בגורל. יָצְאוּ יְהוֹשֻׁעַ וְכָלֵב, וְכֵן הוּא אוֹמֵר \\\"וַיִּתְּנוּ לְכָלֵב אֶת חֶבְרוֹן כַּאֲשֶׁר דִּבֶּר מֹשֶׁה\\\" (שופטים א'), וְאוֹמֵר (יהושע י\\\"ט) \\\"עַל פִּי ה' נָתְנוּ לוֹ אֶת הָעִיר אֲשֶׁר שָׁאָל\\\" (ספרי):\",2,0],[2,133,26,55,\"מטות אבתם. יָצְאוּ גֵרִים וַעֲבָדִים:\",3,0],[2,133,26,56,\"על פי הגורל. הַגּוֹרָל הָיָה מְדַבֵּר, כְּמוֹ שֶׁפֵּרַשְׁתִּי, מַגִּיד שֶׁנִּתְחַלְּקָה בְרוּחַ הַקֹּדֶשׁ  :\",1,0],[2,133,26,58,\"אלה משפחת לוי. חָסֵר כָּאן מִשְׁפְּחוֹת הַשִּׁמְעִי וְהָעָזִּיאֵלִי וּקְצָת מִן הַיִּצְהָרִי:\",1,0],[2,133,26,59,\"אשר ילדה אתה ללוי במצרים. לֵדָתָהּ בְּמִצְרַיִם וְאֵין הוֹרָתָהּ בְּמִצְרַיִם, כְּשֶׁנִּכְנְסוּ לְתוֹךְ הַחוֹמָה יְלָדַתָּה, וְהִיא הִשְׁלִימָה מִנְיַן שִׁבְעִים, שֶׁהֲרֵי בִפְרָטָן אֵי אַתָּה מוֹצֵא אֶלָּא שִׁשִּׁים וָתֵשַׁע:\",1,0],[2,133,26,62,\"כי לא התפקדו בתוך בני ישראל. לִהְיוֹת נִמְנִין בְּנֵי עֶשְׂרִים שָׁנָה, מַה טַּעַם? כי לא נתן להם נחלה, וְהַנִּמְנִין מִבֶּן עֶשְׂרִים שָׁנָה הָיוּ בְנֵי נַחֲלָה, שֶׁנֶּאֱמַר \\\"אִישׁ לְפִי פְקֻדָיו יֻתַּן נַחֲלָתוֹ\\\":\",1,0],[2,133,26,64,\"ובאלה לא היה איש וגו'. אֲבָל עַל הַנָּשִׁים לֹא נִגְזְרָה גְזֵרַת הַמְרַגְּלִים, לְפִי שֶׁהֵן הָיוּ מְחַבְּבוֹת אֶת הָאָרֶץ, הָאֲנָשִׁים אוֹמְרִים נִתְּנָה רֹאשׁ וְנָשׁוּבָה מִצְרַיְמָה, וְהַנָּשִׁים אוֹמְרוֹת \\\"תְּנָה לָּנוּ אֲחֻזָּה\\\", לְכָךְ נִסְמְכָה פָרָשַׁת בְּנוֹת צְלָפְחָד לְכָאן (תנחומא):\",1,0],[2,133,27,1,\"למשפחת מנשה בן יוסף. לָמָּה נֶאֱמַר? וַהֲלֹא כְבָר נֶאֱמַר בן מנשה, אֶלָּא לוֹמַר לְךָ, יוֹסֵף חִבֵּב אֶת הָאָרֶץ, שֶׁנֶּאֱמַר \\\"וְהַעֲלִתֶם אֶת עַצְמֹתַי\\\" וְגוֹ' (בראשית נ') וּבְנוֹתָיו חִבְּבוּ אֶת הָאָרֶץ, שֶׁנֶּאֱמַר תְּנָה לָּנוּ אֲחֻזָּה, וּלְלַמֶּדְךָ שֶׁהָיוּ כֻלָּם צַדִּיקִים, שֶׁכָּל מִי שֶׁמַּעֲשָׂיו וּמַעֲשֵׂה אֲבוֹתָיו סְתוּמִים וּפֵרֵט לְךָ הַכָּתוּב בְּאֶחָד מֵהֶם לְיַחֲסוֹ לְשֶׁבַח, הֲרֵי זֶה צַדִּיק בֶּן צַדִּיק, וְאִם יִחֲסוֹ לִגְנַאי, כְּגוֹן \\\"בָּא יִשְׁמָעֵאל בֶּן נְתַנְיָה בֶּן אֱלִישָׁמָע\\\" (מלכים ב כ\\\"ה), בְיָדוּעַ שֶׁכָּל הַנִּזְכָּרִים עִמּוֹ רְשָׁעִים הָיוּ (ספרי):\",1,0],[2,133,27,1,\"מחלה נעה וגו'. וּלְהַלָּן (במדבר לו יא) הוּא אוֹמֵר \\\"וַתִּהְיֶינָה מַחְלָה תִרְצָה\\\", מַגִּיד שֶׁכֻּלָּן שְׁקוּלוֹת — זוֹ כְּזוֹ, לְפִיכָךְ שִׁנָּה אֶת סִדְרָן (שם):\",2,0],[2,133,27,2,\"לפני משה ולפני אלעזר. מַגִּיד שֶׁלֹּא עָמְדוּ לִפְנֵיהֶם אֶלָּא בִשְׁנַת הָאַרְבָּעִים, אַחַר שֶׁמֵּת אַהֲרֹן (שם):\",1,0],[2,133,27,2,\"לפני משה. וְאַחַר כָּךְ לִפְנֵי אֶלְעָזָר? אֶפְשַׁר אִם מֹשֶׁה לֹא יָדַע אֶלְעָזָר יוֹדֵעַ? אֶלָּא סָרֵס הַמִּקְרָא וְדָרְשֵׁהוּ, דִּבְרֵי רַבִּי יֹאשִׁיָּה. אַבָּא חָנָן מִשּׁוּם רַבִּי אֶלְעָזָר אוֹמֵר, בְּבֵית הַמִּדְרָשׁ הָיוּ יוֹשְׁבִים וְעָמְדוּ לִפְנֵי כֻלָּם (שם; בבא בתרא קי\\\"ט):\",2,0],[2,133,27,3,\"והוא לא היה וגו'. לְפִי שֶׁהָיוּ בָאוֹת לוֹמַר בחטאו מת, נִזְקְקוּ לוֹמַר לֹא בְחֵטְא מִתְלוֹנְנִים וְלֹא בַעֲדַת קֹרַח שֶׁהִצּוּ עַל הַקָּבָּ\\\"ה הָיָה, אֶלָּא בְּחֶטְאוֹ לְבַדּוֹ מֵת, וְלֹא הֶחֱטִיא אֶת אֲחֵרִים עִמּוֹ (ספרי); רַבִּי עֲקִיבָא אוֹמֵר מְקוֹשֵׁשׁ עֵצִים הָיָה וְרַבִּי שִׁמְעוֹן אוֹמֵר מִן הַמַּעְפִּילִים הָיָה (שבת צ\\\"ו):\",1,0],[2,133,27,4,\"למה יגרע שם אבינו. אָנוּ בִּמְקוֹם בֵּן עוֹמְדוֹת, וְאִם אֵין הַנְּקֵבוֹת חֲשׁוּבוֹת זֶרַע, תִּתְיַבֵּם אִמֵּנוּ לְיָבָם (בבא בתרא קיט):\",1,0],[2,133,27,4,\"כי אין לו בן. הָא אִם הָיָה לוֹ בֵן, לֹא הָיוּ תוֹבְעוֹת כְּלוּם, מַגִּיד שֶׁחַכְמָנִיּוֹת הָיוּ (שם):\",2,0],[2,133,27,5,\"ויקרב משה את משפטן. נִתְעַלְּמָה הֲלָכָה מִמֶּנּוּ, וְכָאן נִפְרַע עַל שֶׁנָּטַל עֲטָרָה לוֹמַר (דברים א') \\\"וְהַדָּבָר אֲשֶׁר יִקְשֶׁה מִכֶּם תַּקְרִבוּן אֵלַי\\\"; דָּ\\\"אַ — רְאוּיָה הָיְתָה פָרָשָׁה זוֹ לְהִכָּתֵב עַל יְדֵי מֹשֶׁה, אֶלָּא שֶׁזָּכוּ בְנוֹת צְלָפְחָד וְנִכְתְּבָה עַל יָדָן (בבא בתרא קי\\\"ט; סנהדרין ח'):\",1,0],[2,133,27,7,\"כן בנות צלפחד דברת. כְּתַרְגּוּמוֹ, \\\"יָאוּת\\\" — כָּךְ כְּתוּבָה פָרָשָׁה זוֹ לְפָנַי בַּמָּרוֹם, מַגִּיד שֶׁרָאֲתָה עֵינָן מַה שֶּׁלֹּא רָאֲתָה עֵינוֹ שֶׁל מֹשֶׁה (תנחומא):\",1,0],[2,133,27,7,\"כן בנות צלפחד דברת. יָפֶה תָּבְעוּ, אַשְׁרֵי אָדָם שֶׁהַקָּבָּ\\\"ה מוֹדֶה לִדְבָרָיו (ספרי):\",2,0],[2,133,27,7,\"נתן תתן. שְׁנֵי חֲלָקִים, חֵלֶק אֲבִיהֶן שֶׁהָיָה מִיּוֹצְאֵי מִצְרַיִם, וְחֶלְקוֹ עִם אֶחָיו בְּנִכְסֵי חֵפֶר (בבא בתרא קי\\\"ח):\",3,0],[2,133,27,7,\"והעברת. לְשׁוֹן עֶבְרָה הוּא בְּמִי שֶׁאֵינוֹ מַנִּיחַ בֵּן לְיָרְשׁוֹ. דָּ\\\"אַ — עַל שֵׁם שֶׁהַבַּת מַעֲבֶרֶת נַחֲלָה מִשֵּׁבֶט לְשֵׁבֶט, שֶׁבְּנָהּ וּבַעְלָהּ יוֹרְשִׁין אוֹתָהּ — שֶׁ\\\"לֹא תִסֹּב נַחֲלָה\\\" (במדבר ל\\\"ו) לֹא נִצְטַוָּה אֶלָּא לְאוֹתוֹ הַדּוֹר בִּלְבַד (בבא בתרא ק\\\"כ) — וְכֵן וְהַעֲבַרְתֶּם אֶת נַחֲלָתוֹ לְבִתּוֹ, בְּכֻלָּן הוּא אוֹמֵר \\\"וּנְתַתֶּם\\\" וּבַבַּת הוּא אוֹמֵר \\\"וְהַעֲבַרְתֶּם\\\":\",4,0],[2,133,27,11,\"לשארו הקרב אליו ממשפחתו. וְאֵין מִשְׁפָּחָה קְרוּיָה אֶלָּא מִצַּד הָאָב (שם ק\\\"ט):\",1,0],[2,133,27,12,\"עלה אל הר העברים. לָמָּה נִסְמְכָה לְכָאן? כֵּיוָן שֶׁאָמַר הַקָּבָּ\\\"ה נָתֹן תִּתֵּן לָהֶם, אָמַר אוֹתִי צִוָּה הַמָּקוֹם לְהַנְחִיל, שֶׁמָּא הֻתְּרָה הַגְּזֵרָה וְאֶכָּנֵס לָאָרֶץ? אָמַר לוֹ הַקָּבָּ\\\"ה גְּזֵרָתִי בִּמְקוֹמָהּ עוֹמֶדֶת. דָּ\\\"אַ — כֵּיוָן שֶׁנִּכְנַס מֹשֶׁה לְנַחֲלַת בְּנֵי גָד וּבְנֵי רְאוּבֵן שָׂמַח וְאָמַר, כִּמְדֻמֶּה שֶׁהֻתַּר לִי נִדְרִי; מָשָׁל לְמֶלֶךְ שֶׁגָּזַר עַל בְּנוֹ שֶׁלֹּא יִכָּנֵס לְפֶתַח פָּלָטִין שֶׁלּוֹ, נִכְנַס לַשַּׁעַר וְהוּא אַחֲרָיו, לֶחָצֵר וְהוּא אַחֲרָיו, לַטְּרַקְלִין וְהוּא אַחֲרָיו, כֵּיוָן שֶׁבָּא לִכָּנֵס לַקִּיטוֹן, אָמַר לוֹ בְּנִי מִכָּאן וָאֵילָךְ אַתָּה אָסוּר לִכָּנֵס (ספרי):\",1,0],[2,133,27,13,\"כאשר נאסף אהרן אחיך. מִכָּאן שֶׁנִּתְאַוָּה מֹשֶׁה לְמִיתָתוֹ שֶׁל אַהֲרֹן (שם); דָּ\\\"אַ — אֵין אַתָּה טוֹב מִמֶּנּוּ, \\\"עַל אֲשֶׁר לֹא קִדַּשְׁתֶּם\\\" (דברים לב, נא), הָא אִם קִדַּשְׁתֶּם אוֹתִי עֲדַיִן לֹא הִגִּיעַ זְמַנְכֶם לְהִפָּטֵר (שם); בְּכָל מָקוֹם שֶׁכָּתַב מִיתָתָם כָּתַב סֻרְחָנָם, לְפִי שֶׁנִּגְזְרָה גְזֵרָה עַל דּוֹר הַמִּדְבָּר לָמוּת בַּמִּדְבָּר בְּעָוֹן שֶׁלֹּא הֶאֱמִינוּ, לְכָךְ בִּקֵּשׁ מֹשֶׁה שֶׁיִּכָּתֵב סֻרְחָנוֹ, שֶׁלֹּא יֹאמְרוּ אַף הוּא מִן הַמַּמְרִים הָיָה, מָשָׁל לִשְׁתֵּי נָשִׁים שֶׁלּוֹקוֹת בְּבֵית דִּין, אַחַת קִלְקְלָה וְאַחַת אָכְלָה פַגֵּי שְׁבִיעִית וְכוּ', אַף כָּאן בְּכָל מָקוֹם שֶׁהִזְכִּיר מִיתָתָן הִזְכִּיר סֻרְחָנָן, לְהוֹדִיעַ שֶׁלֹּא הָיְתָה בָהֶם אֶלָּא זוֹ בִּלְבַד (יומא פ\\\"ו):\",1,0],[2,133,27,14,\"הם מי מריבת קדש. הֵם לְבַדָּם — אֵין בָּהֶם עָוֹן אַחֵר; דָּ\\\"אַ — הֵם שֶׁהִמְרוּ בְמָרָה, הֵם הָיוּ שֶׁהִמְרוּ בְיַם סוּף, הֵם עַצְמָם שֶׁהִמְרוּ בְמִדְבַּר צִן:\",1,0],[2,133,27,15,\"וידבר משה אל ה' וגו'. לְהוֹדִיעַ שִׁבְחָן שֶׁל צַדִּיקִים, כְּשֶׁנִּפְטָרִים מִן הָעוֹלָם מַנִּיחִים צָרְכָּן, וְעוֹסְקִין בְּצָרְכֵי צִבּוּר (ספרי):\",1,0],[2,133,27,15,\"לאמר. אָמַר לוֹ, הֲשִׁיבֵנִי אִם אַתָּה מְמַנֶּה לָהֶם פַּרְנָס אִם לָאו (שם):\",2,0],[2,133,27,16,\"יפקד ה'. כֵּיוָן שֶׁשָּׁמַע מֹשֶׁה שֶׁאָמַר לוֹ הַמָּקוֹם תֵּן נַחֲלַת צְלָפְחָד לִבְנוֹתָיו, אָמַר הִגִּיעַ שָׁעָה שֶׁאֶתְבַּע צָרְכִּי — שֶׁיִּירְשׁוּ בָּנַי אֶת גְּדֻלָּתִי, אָמַר לוֹ הַקָּבָּ\\\"ה לֹא כָךְ עָלְתָה בְמַחֲשָׁבָה לְפָנַי, כְּדַאי הוּא יְהוֹשֻׁעַ לִטֹּל שְׂכַר שִׁמּוּשׁוֹ שֶׁלֹּא מָשׁ מִתּוֹךְ הָאֹהֶל (שמות ל״ג:י״א), וְזֶהוּ שֶׁאָמַר שְׁלֹמֹה (משלי כ\\\"ז) \\\"נוֹצֵר תְּאֵנָה יֹאכַל פִּרְיָהּ\\\" (תנחומא):\",1,0],[2,133,27,16,\"אלהי הרוחת. לָמָּה נֶאֱמַר? אָמַר לְפָנָיו, רִבּוֹנוֹ שֶׁל עוֹלָם, גָּלוּי לְפָנֶיךָ דַּעְתּוֹ שֶׁל כָּל אֶחָד וְאֶחָד, וְאֵינָן דּוֹמִין זֶה לָזֶה, מַנֵּה עֲלֵיהֶם מַנְהִיג שֶׁיְּהֵא סוֹבֵל כָּל אֶחָד וְאֶחָד לְפִי דַעְתּוֹ (ילקוט שמעוני):\",2,0],[2,133,27,17,\"אשר יצא לפניהם. לֹא כְדֶרֶךְ מַלְכֵי הָאֻמּוֹת שֶׁיּוֹשְׁבִים בְּבָתֵּיהֶם וּמְשַׁלְּחִין אֶת חַיָּלוֹתֵיהֶם לַמִּלְחָמָה, אֶלָּא כְּמוֹ שֶׁעָשִׂיתִי אֲנִי, שֶׁנִּלְחַמְתִּי בְסִיחוֹן וּבְעוֹג, שֶׁנֶּאֱמַר (במדבר כ\\\"א) \\\"אַל תִּירָא אֹתוֹ\\\", וּכְדֶרֶךְ שֶׁעָשָׂה יְהוֹשֻׁעַ, שֶׁנֶּאֱמַר \\\"וַיֵּלֶךְ יְהוֹשֻׁעַ אֵלָיו וַיֹּאמֶר לוֹ הֲלָנוּ אַתָּה\\\" וְגוֹ' (יהושע ה'), וְכֵן בְּדָוִד הוּא אוֹמֵר (שמואל א י\\\"ח) \\\"כִּי הוּא יוֹצֵא וָבָא לִפְנֵיהֶם\\\" — יוֹצֵא בָּרֹאשׁ וְנִכְנָס בָּרֹאשׁ (ספרי):\",1,0],[2,133,27,17,\"ואשר יוציאם. בִּזְכֻיּוֹתָיו:\",2,0],[2,133,27,17,\"ואשר יביאם. בִּזְכֻיּוֹתָיו. דָּ\\\"אַ — ואשר יביאם, שֶׁלֹּא תַעֲשֶׂה לוֹ כְּדֶרֶךְ שֶׁאַתָּה עוֹשֶׂה לִּי, שֶׁאֵינִי מַכְנִיסָן לָאָרֶץ (ילקוט שמעוני):\",3,0],[2,133,27,18,\"קח לך. קָחֶנּוּ בִּדְבָרִים — אַשְׁרֶיךָ שֶׁזָּכִיתָ לְהַנְהִיג בָּנָיו שֶׁל מָקוֹם:\",1,0],[2,133,27,18,\"לך. אֶת שֶׁבָּדוּק לְךָ, אֶת שֶׁאַתָּה מַכִּיר:\",2,0],[2,133,27,18,\"אשר רוח בו. כַּאֲשֶׁר שָׁאַלְתָּ, שֶׁיּוּכַל לַהֲלֹךְ כְּנֶגֶד רוּחוֹ שֶׁל כָּל אֶחָד וְאֶחָד (ספרי):\",3,0],[2,133,27,18,\"וסמכת את ידך עליו. תֵּן לוֹ מְתֻרְגְּמָן שֶׁיִּדְרֹשׁ בְּחַיֶּיךָ, שֶׁלֹּא יֹאמְרוּ עָלָיו, לֹא הָיָה לוֹ לְהָרִים רֹאשׁ בִּימֵי מֹשֶׁה:\",4,0],[2,133,27,19,\"וצויתה אתו. עַל יִשְׂרָאֵל, דַּע שֶׁטַּרְחָנִין הֵם, סַרְבָנִים הֵם, עַל מְנָת שֶׁתְּקַבֵּל עָלֶיךָ (ספרי במדבר י\\\"א):\",1,0],[2,133,27,20,\"ונתתה מהודך עליו. זֶה קֵרוּן עוֹר פָּנִים:\",1,0],[2,133,27,20,\"מהודך. וְלֹא כָּל הוֹדְךָ, וּמָצִינוּ לְמֵדִין פְּנֵי מֹשֶׁה כַּחַמָּה פְּנֵי יְהוֹשֻׁעַ כַּלְּבָנָה (ספרי; בבא בתרא ע\\\"ה):\",2,0],[2,133,27,20,\"למען ישמעו כל עדת בני ישראל. שֶׁיִּהְיוּ נוֹהֲגִין בּוֹ כָּבוֹד וְיִרְאָה, כְּדֶרֶךְ שֶׁנּוֹהֲגִין בְּךָ:\",3,0],[2,133,27,21,\"ולפני אלעזר הכהן יעמד. הֲרֵי שְׁאֵלָתְךָ שֶׁשָּׁאַלְתָּ, שֶׁאֵין הַכָּבוֹד הַזֶּה זָז מִבֵּית אָבִיךָ, שֶׁאַף יְהוֹשֻׁעַ יְהֵא צָרִיךְ לְאֶלְעָזָר (תנחומא):\",1,0],[2,133,27,21,\"ושאל לו. כְּשֶׁיִּצְטָרֵךְ לָצֵאת לַמִּלְחָמָה:\",2,0],[2,133,27,21,\"על פיו. שֶׁל אֶלְעָזָר:\",3,0],[2,133,27,21,\"וכל העדה. סַנְהֶדְרִין:\",4,0],[2,133,27,22,\"ויקח את יהושע. לְקָחוֹ בִדְבָרִים וְהוֹדִיעוֹ מַתַּן שְׂכַר פַּרְנְסֵי יִשְׂרָאֵל לָעוֹלָם הַבָּא (ספרי):\",1,0],[2,133,27,23,\"ויסמך את ידיו. בְּעַיִן יָפָה, יוֹתֵר וְיוֹתֵר מִמַּה שֶּׁנִּצְטַוָּה, שֶׁהַקָּבָּ\\\"ה אָמַר לוֹ \\\"וְסָמַכְתָּ אֶת יָדְךָ\\\", וְהוּא עָשָׂה בִּשְׁתֵּי יָדָיו, וַעֲשָׂאוֹ כִכְלִי מָלֵא וְגָדוּשׁ, וּמִלְּאוֹ חָכְמָתוֹ בְּעַיִן יָפָה (שם):\",1,0],[2,133,27,23,\"כאשר דבר ה'. אַף לְעִנְיַן הַהוֹד — נָתַן מֵהוֹדוֹ עָלָיו:\",2,0],[2,133,28,2,\"צו את בני ישראל. מָה אָמוּר לְמַעְלָה? יִפְקֹד ה', אָמַר לוֹ הַקָּבָּ\\\"ה עַד שֶׁאַתָּה מְצַוֵּנִי עַל בָּנַי, צַוֵּה אֶת בָּנַי עָלַי, מָשָׁל לְבַת מֶלֶךְ שֶׁהָיְתָה נִפְטֶרֶת מִן הָעוֹלָם וְהָיְתָה מְפַקֶּדֶת בַּעְלָהּ עַל בָּנֶיהָ וְכוּ' כִּדְאִיתָא בְסִפְרֵי:\",1,0],[2,133,28,2,\"קרבני. זֶה הַדָּם:\",2,0],[2,133,28,2,\"לחמי. אֵלּוּ אֵמוּרִין, וְכֵן הוּא אוֹמֵר (ויקרא ג') \\\"וְהִקְטִירָם הַכֹּהֵן הַמִּזְבֵּחָה לֶחֶם אִשֶּׁה\\\" (ספרי):\",3,0],[2,133,28,2,\"לאשי. הַנִּתָּנִין לְאִשֵּׁי מִזְבְּחִי:\",4,0],[2,133,28,2,\"תשמרו. שֶׁיִּהְיוּ כֹּהֲנִים וּלְוִיִּם וְיִשְׂרָאֵל עוֹמְדִין עַל גַּבָּיו, מִכָּאן לָמְדוּ וְתִקְּנוּ מַעֲמָדוֹת (תענית כ\\\"ו):\",5,0],[2,133,28,2,\"במועדו. בְּכָל יוֹם הוּא מוֹעֵד הַתְּמִידִים:\",6,0],[2,133,28,3,\"ואמרת להם. אַזְהָרָה לְבֵית דִּין (ספרי):\",1,0],[2,133,28,3,\"שנים ליום. כִּפְשׁוּטוֹ, וְעִקָּרוֹ בָא לְלַמֵּד שֶׁיִּהְיוּ נִשְׁחָטִין כְּנֶגֶד הַיּוֹם — תָּמִיד שֶׁל שַׁחַר בַּמַּעֲרָב וְשֶׁל בֵּין הָעַרְבַּיִם בְּמִזְרָחָן שֶׁל טַבָּעוֹת (ספרי; יומא ס\\\"ב):\",2,0],[2,133,28,4,\"את הכבש אחד. אַעַ\\\"פִּ שֶׁכְּבָר נֶאֱמַר בְּפָרָשַׁת וְאַתָּה תְּצַוֶּה \\\"וְזֶה אֲשֶׁר תַּעֲשֶׂה\\\" וְגוֹ' (שמות כט לח), הִיא הָיְתָה אַזְהָרָה לִימֵי הַמִּלּוּאִים וְכָאן צִוָּה לַדּוֹרוֹת:\",1,0],[2,133,28,5,\"סלת למנחה. מִנְחַת נְסָכִים:\",1,0],[2,133,28,6,\"העשיה בהר סיני. כְּאוֹתָן שֶׁנַּעֲשׂוּ בִּימֵי הַמִּלּוּאִים; דָּ\\\"אַ — העשיה בהר סיני, הִקִּישׁ עוֹלַת תָּמִיד לְעוֹלַת הַר סִינַי — אוֹתָהּ שֶׁנִּתְקָרְבָה לִפְנֵי מַתַּן תּוֹרָה — שֶׁכָּתוּב בָּהּ (שם כ\\\"ד) \\\"וַיָּשֶֹם בָּאֲגָנֹת\\\", מְלַמֵּד שֶׁטְּעוּנָה כְּלִי (ספרי):\",1,0],[2,133,28,7,\"ונסכו. יַיִן:\",1,0],[2,133,28,7,\"בקדש הסך. עַל הַמִּזְבֵּחַ יִתְנַסְּכוּ:\",2,0],[2,133,28,7,\"נסך שכר. יַיִן הַמְשַׁכֵּר, פְּרָט לְיַיִן מִגִּתּוֹ (בבא בתרא צ\\\"ז):\",3,0],[2,133,28,8,\"ריח ניחח. נַחַת רוּחַ לְפָנַי שֶׁאָמַרְתִּי וְנַעֲשָׂה רְצוֹנִי (ספרי):\",1,0],[2,133,28,10,\"עלת שבת בשבתו. וְלֹא עוֹלַת שַׁבָּת זוֹ בְּשַׁבָּת אַחֶרֶת, הֲרֵי שֶׁלֹּא הִקְרִיב בְּשַׁבָּת זוֹ שׁוֹמֵעַ אֲנִי יַקְרִיב שְׁתַּיִם לַשַּׁבָּת הַבָּאָה, תַּ\\\"ל \\\"בְּשַׁבַּתּוֹ\\\", מַגִּיד שֶׁאִם עָבַר יוֹמוֹ בָּטֵל קָרְבָּנוֹ (ספרי):\",1,0],[2,133,28,10,\"על עלת התמיד. אֵלּוּ מוּסָפִין, לְבַד אוֹתָן שְׁנֵי כְבָשִׂים שֶׁל עוֹלַת הַתָּמִיד, וּמַגִּיד שֶׁאֵין קְרֵבִין אֶלָּא בֵּין שְׁנֵי הַתְּמִידִין, וְכֵן בְּכָל הַמּוּסָפִין נֶאֱמַר עַל עֹלַת הַתָּמִיד לְתַלְמוּד זֶה:\",2,0],[2,133,28,12,\"ושלשה עשרנים. כְּמִשְׁפַּט נִסְכֵּי פַר, שֶׁכֵּן הֵן קְצוּבִין בְּפָרָשַׁת נְסָכִים:\",1,0],[2,133,28,14,\"זאת עלת חדש בחדשו. שֶׁאִם עָבַר יוֹמוֹ בָּטֵל קָרְבָּנוֹ וְשׁוּב אֵין לוֹ תַשְׁלוּמִין:\",1,0],[2,133,28,15,\"ושעיר עזים וגו'. כָּל שְׂעִירֵי הַמּוּסָפִין בָּאִין לְכַפֵּר עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו, הַכֹּל כְּמוֹ שֶׁמְּפֹרָשׁ בְּמַסֶּכֶת שְׁבוּעוֹת (דף ט'), וְנִשְׁתַּנָּה שְׂעִיר רֹאשׁ חֹדֶשׁ שֶׁנֶּאֱמַר בּוֹ \\\"לַה'\\\"; לְלַמֶּדְךָ שֶׁמְּכַפֵּר עַל שֶׁאֵין בּוֹ יְדִיעָה לֹא בַתְּחִלָּה וְלֹא בַסּוֹף — שֶׁאֵין מַכִּיר בַּחֵטְא אֶלָּא הַקָּבָּ\\\"ה בִלְבָד, וּשְׁאָר הַשְּׂעִירִים לְמֵדִין מִמֶּנוּ; וּמִדְרָשׁוֹ בָּאַגָּדָה, אָמַר הַקָּבָּ\\\"ה הָבִיאוּ כַפָּרָה עָלַי עַל שֶׁמִּעַטְתִּי אֶת הַיָּרֵחַ (חולין ס'):\",1,0],[2,133,28,15,\"על עלת התמיד יעשה. כָּל הַקָּרְבָּן הַזֶּה:\",2,0],[2,133,28,15,\"ונסכו. אֵין \\\"וְנִסְכּוֹ\\\" מוּסָב עַל הַשָּׂעִיר, שֶׁאֵין נְסָכִים לְחַטָּאת:\",3,0],[2,133,28,18,\"כל מלאכת עבדה. אֲפִלּוּ מְלָאכָה הַצְּרִיכָה לָכֶם, כְּגוֹן דָּבָר הָאָבֵד, הַמֻּתָּר בְּחֻלּוֹ שֶׁל מוֹעֵד, אֲסוּרָה בְּי\\\"ט:\",1,0],[2,133,28,19,\"פרים. כְּנֶגֶד אַבְרָהָם שֶׁנֶּאֱמַר \\\"וְאֶל הַבָּקָר רָץ אַבְרָהָם\\\" (בראשית י\\\"ח):\",1,0],[2,133,28,19,\"אילים. כְּנֶגֶד אֵילוֹ שֶׁל יִצְחָק:\",2,0],[2,133,28,19,\"כבשים. כְּנֶגֶד יַעֲקֹב שֶׁנֶּאֱמַר \\\"וְהַכְּשָׂבִים הִפְרִיד יַעֲקֹב\\\" (שם ל'); בִּיסוֹדוֹ שֶׁל רַ' מֹשֶׁה הַדַּרְשָׁן רָאִיתִי זֹאת:\",3,0],[2,133,28,24,\"כאלה תעשו ליום. שֶׁלֹּא יִהְיוּ פוֹחֲתִין וְהוֹלְכִין כְּפָרֵי הֶחָג (ספרי):\",1,0],[2,133,28,26,\"וביום הבכורים. חַג הַשָּׁבוּעוֹת קָרוּי בִּכּוּרֵי קְצִיר חִטִּים עַל שֵׁם שְׁתֵּי הַלֶּחֶם, שֶׁהֵם רִאשׁוֹנִים לְמִנְחַת חִטִּים הַבָּאִים מִן הֶחָדָשׁ (מנחות פ\\\"ד):\",1,0],[2,133,28,31,\"תמימם יהיו לכם ונסכיהם. אַף הַנְּסָכִים יִהְיוּ תְמִימִים, לָמְדוּ רַבּוֹתֵינוּ מִכָּאן שֶׁהַיַּיִן שֶׁהֶעֱלָה קְמָחִין פָּסוּל לִנְסָכִים (שם פ\\\"ז):\",1,0],[2,133,29,6,\"מלבד עלת החדש. מוּסְפֵי רֹאשׁ חֹדֶשׁ שֶׁהוּא בְיוֹם רֹאשׁ הַשָּׁנָה:\",1,0],[2,133,29,11,\"מלבד חטאת הכפרים. שָׂעִיר הַנַּעֲשֶׂה בִּפְנִים הָאָמוּר בְּאַחֲרֵי מוֹת, שֶׁגַּם הוּא חַטָּאת:\",1,0],[2,133,29,11,\"ועלת התמיד. וּמִלְּבַד עוֹלַת הַתָּמִיד תַּעֲשׂוּ עוֹלוֹת הַלָּלוּ:\",2,0],[2,133,29,11,\"ונסכיהם. מוּסָב עַל הַמּוּסָפִין הַכְּתוּבִים וְעַל תַּעֲשׂוּ, וְהוּא לְשׁוֹן צִוּוּי — מִלְּבַד עוֹלַת הַתָּמִיד וּמִנְחָתָהּ תַּעֲשׂוּ אֶת אֵלֶּה וְנִסְכֵּיהֶם, וְכֵן כָּל נִסְכֵּיהֶם הָאֲמוּרִים בְּכָל הַמּוֹעֲדוֹת חוּץ מִשֶּׁל קָרְבְּנוֹת הֶחָג, שֶׁכָּל וְנִסְכָּהּ, וְנִסְכֵּיהֶם, וּנְסָכֶיהָ שֶׁבָּהֶם מוּסַבִּים עַל הַתָּמִיד, וְאֵינָן לְשׁוֹן צִוּוּי, שֶׁהֲרֵי נִסְכֵּיהֶם שֶׁל מוּסָפִין כְּתוּבִין לְעַצְמָן בְּכָל יוֹם וָיוֹם:\",3,0],[2,133,29,18,\"ומנחתם ונסכיהם לפרים. פָּרֵי הֶחָג שִׁבְעִים הֵם כְּנֶגֶד שִׁבְעִים אֻמּוֹת, וּמִתְמַעֲטִים וְהוֹלְכִים, סִימָן כְּלָיָה הִיא לָהֶם, וּבִימֵי הַמִּקְדָּשׁ הָיוּ מְגִנִּים עֲלֵיהֶם מִן הַיִּסּוּרִין (סוכה נ\\\"ה):\",1,0],[2,133,29,18,\"ולכבשים. כְּנֶגֶד יִשְׂרָאֵל שֶׁנִּקְרְאוּ \\\"שֶׂה פְזוּרָה\\\" (ירמיהו נ'), וְהֵם קְבוּעִים, וּמִנְיָנָם תִּשְׁעִים וּשְׁמוֹנָה, לְכַלּוֹת מֵהֶם תִּשְׁעִים וּשְׁמוֹנֶה קְלָלוֹת שֶׁבְּמִשְׁנֵה תוֹרָה; בַּשֵּׁנִי נֶאֱמַר וְנִסְכֵּיהֶם עַל שְׁנֵי תְמִידֵי הַיּוֹם, וְלֹא שִׁנָּה הַלָּשׁוֹן אֶלָּא לִדְרֹשׁ, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זִ\\\"לִ (ספרי; שבת ק\\\"נ) בַּשֵּׁנִי וְנִסְכֵּיהֶם, בַּשִּׁשִּׁי וּנְסָכֶיהָ, בַּשְּׁבִיעִי כְּמִשְׁפָּטָם, מֵ\\\"ם יוֹ\\\"ד מֵ\\\"ם הֲרֵי כָאן מַיִם, רֶמֶז לְנִסּוּךְ הַמַּיִם מִן הַתּוֹרָה בֶּחָג:\",2,0],[2,133,29,35,\"עצרת תהיה לכם. עֲצוּרִים בַּעֲשִׂיַּת מְלָאכָה; דָּ\\\"אַ, עצרת — עִצְרוּ מִלָּצֵאת, מְלַמֵּד שֶׁטָּעוּן לִינָה; וּמִדְרָשׁוֹ בַאַגָּדָה לְפִי שֶׁכָּל יְמוֹת הָרֶגֶל הִקְרִיבוּ כְנֶגֶד שִׁבְעִים אֻמּוֹת, וּבָאִין לָלֶכֶת, אָמַר לָהֶם הַמָּקוֹם בְּבַקָּשָׁה מִכֶּם עֲשׂוּ לִי סְעוּדָה קְטַנָּה כְּדֵי שֶׁאֵהָנֶה מִכֶּם (סוכה נ\\\"ה):\",1,0],[2,133,29,36,\"פר אחד איל אחד. אֵלּוּ כְנֶגֶד יִשְׂרָאֵל, הִתְעַכְּבוּ לִי מְעַט עוֹד, וּלְשׁוֹן חִבָּה הוּא זֶה, כְּבָנִים הַנִּפְטָרִים מֵאֲבִיהֶם וְהוּא אוֹמֵר לָהֶם קָשָׁה עָלַי פְּרֵדַתְכֶם, עַכְּבוּ עוֹד יוֹם אֶחָד, מָשָׁל לְמֶלֶךְ שֶׁעָשָׂה סְעוּדָה כוּ', כִּדְאִיתָא בְמַסֶּכֶת סֻכָּה (שם); וּבְמִדְרַשׁ רַבִּי תַנְחוּמָא: לִמְּדָה תוֹרָה דֶּרֶךְ אֶרֶץ שֶׁמִּי שֶׁיֵּשׁ לוֹ אַכְסְנַאי יוֹם רִאשׁוֹן יַאֲכִילֶנּוּ פְּטוּמוֹת, לְמָחָר יַאֲכִילֶנּוּ דָּגִים, לְמָחָר בְּשַׂר בְּהֵמָה, לְמָחָר מַאֲכִילוֹ קִטְנִית, לְמָחָר מַאֲכִילוֹ יָרָק, פּוֹחֵת וְהוֹלֵךְ כְּפָרֵי הֶחָג:\",1,0],[2,133,29,39,\"אלה תעשו לה' במועדיכם. דָּבָר הַקָּצוּב לְחוֹבָה:\",1,0],[2,133,29,39,\"לבד מנדריכם. אִם בָּאתֶם לִדּוֹר קָרְבָּנוֹת בָּרֶגֶל, מִצְוָה הִיא בְּיֶדְכֶם, אוֹ נְדָרִים אוֹ נְדָבוֹת שֶׁנְּדַרְתֶּם כָּל הַשָּׁנָה, הַקְרִיבוּם בָּרֶגֶל, שֶׁמָּא יִקְשֶׁה לוֹ לַחֲזֹר וְלַעֲלוֹת לִירוּשָׁלַיִם וּלְהַקְרִיב נְדָרָיו וְנִמְצָא עוֹבֵר בְּבַל תְּאַחֵר:\",2,0],[2,133,30,1,\"ויאמר משה אל בני ישראל. לְהַפְסִיק הָעִנְיָן, דִּבְרֵי רַבִּי יִשְׁמָעֵאל, לְפִי שֶׁעַד כָּאן דְּבָרָיו שֶׁל מָקוֹם וּפָרָשַׁת נְדָרִים מַתְחֶלֶת בְּדִבּוּרוֹ שֶׁל מֹשֶׁה, הֻצְרַךְ לְהַפְסִיק תְּחִלָּה וְלוֹמַר שֶׁחָזַר מֹשֶׁה וְאֲמָרָהּ פָרָשָׁה זוֹ לְיִשְׂרָאֵל, שֶׁאִם לֹא כֵן, יֵשׁ בְּמַשְׁמַע שֶׁלֹּא אָמַר לָהֶם זוֹ, אֶלָּא בְּפָרָשַׁת נְדָרִים הִתְחִיל דְּבָרָיו:\",1,0],[2,133,30,2,\"ראשי המטות. חָלַק כָּבוֹד לַנְּשִׂיאִים לְלַמְּדָם תְּחִלָּה וְאַחַר כָּךְ לְכָל בְּנֵי יִשְׂרָאֵל; וּמִנַּיִן שֶׁאַף שְׁאָר הַדִּבְּרוֹת כֵּן? תַּלְמוּד לוֹמַר (שמות ל\\\"ד) \\\"וַיָּשֻׁבוּ אֵלָיו אַהֲרֹן וְכָל הַנְּשִׂאִים בָּעֵדָה וַיְדַבֵּר מֹשֶׁה אֲלֵהֶם, וְאַחֲרֵי כֵן נִגְּשׁוּ כָּל בְּנֵי יִשְׂרָאֵל\\\". וּמָה רָאָה לְאָמְרָהּ כָּאן? לִמֵּד שֶׁהֲפָרַת נְדָרִים בְּיָחִיד מֻמְחֶה, וְאִם אֵין יָחִיד מֻמְחֶה, מֵפֵר בִּשְׁלֹשָׁה הֶדְיוֹטוֹת; אוֹ יָכוֹל שֶׁלֹּא אָמַר מֹשֶׁה פָרָשָׁה זוֹ אֶלָּא לַנְּשִׂיאִים בִּלְבַד? נֶאֱמַר כָּאן \\\"זֶה הַדָּבָר\\\" וְנֶאֱמַר בִּשְׁחוּטֵי חוּץ (ויקרא י\\\"ז) \\\"זֶה הַדָּבָר\\\", מַה לְּהַלָּן נֶאֶמְרָה לְאַהֲרֹן וּלְבָנָיו וּלְכָל בְּנֵי יִשְׂרָאֵל — שֶׁנֶּאֱמַר \\\"דַּבֵּר אֶל אַהֲרֹן\\\" וְגוֹ' — אַף זוֹ נֶאֶמְרָה לְכֻלָּן (ספרי; נדרים ע\\\"ח):\",1,0],[2,133,30,2,\"זה הדבר. מֹשֶׁה נִתְנַבֵּא בְּ\\\"כֹה אָמַר ה' כַּחֲצֹת הַלַּיְלָה\\\" (שמות י\\\"א) וְהַנְּבִיאִים נִתְנַבְּאוּ בְּ\\\"כֹה אָמַר ה'\\\", מוּסָף עֲלֵיהֶם מֹשֶׁה שֶׁנִּתְנַבֵּא בִּלְשׁוֹן \\\"זֶה הַדָּבָר\\\". דָּ\\\"אַ — זה הדבר מִעוּט הוּא, לוֹמַר שֶׁהֶחָכָם בִּלְשׁוֹן הַתָּרָה, וּבַעַל בִּלְשׁוֹן הֲפָרָה, כִּלְשׁוֹן הַכָּתוּב כָּאן, וְאִם חִלְּפוּ — אֵין מֻתָּר וְאֵין מוּפָר (ספרי; נדרים ע\\\"ז):\",2,0],[2,133,30,3,\"נדר. הָאוֹמֵר הֲרֵי עָלַי קוֹנָם שֶׁלֹּא אֹכַל אוֹ שֶׁלֹּא אֶעֱשֶׂה דָבָר פְּלוֹנִי; יָכוֹל אֲפִלּוּ נִשְׁבַּע שֶׁיֹּאכַל נְבֵלוֹת אֲנִי קוֹרֵא עָלָיו כְּכָל הַיֹּצֵא מִפִּיו יַעֲשֶׂה? תַּ\\\"ל לאסר אסר — לֶאֱסֹר אֶת הַמֻּתָּר וְלֹא לְהַתִּיר אֶת הָאָסוּר (ספרי):\",1,0],[2,133,30,3,\"לא יחל דברו. כְּמוֹ לֹא יְחַלֵּל דְּבָרוֹ — לֹא יַעֲשֶׂה דְּבָרוֹ חֻלִּין (שם):\",2,0],[2,133,30,4,\"בבית אביה. בִּרְשׁוּת אָבִיהָ וַאֲפִלּוּ אֵינָהּ בְּבֵיתוֹ (שם):\",1,0],[2,133,30,4,\"בנעריה. וְלֹא קְטַנָּה וְלֹא בוֹגֶרֶת, שֶׁהַקְּטַנָּה אֵין נִדְרָהּ נֶדֶר, וְהַבּוֹגֶרֶת אֵינָהּ בִּרְשׁוּתוֹ שֶׁל אָבִיהָ לְהָפֵר נְדָרֶיהָ; וְאֵי זוֹ הִיא קְטַנָּה? אָמְרוּ רַבּוֹתֵינוּ בַּת י\\\"א שָׁנָה וְיוֹם אֶחָד נְדָרֶיהָ נִבְדָּקִין, אִם יָדְעָה לְשֵׁם מִי נָדְרָה וּלְשֵׁם מִי הִקְדִּישָׁה, נִדְרָהּ נֶדֶר, בַּת י\\\"ב שָׁנָה וְיוֹם אֶחָד אֵינָהּ צְרִיכָה לִבָּדֵק:\",2,0],[2,133,30,6,\"ואם הניא אביה אתה. אִם מָנַע אוֹתָהּ מִן הַנֶּדֶר, כְּלוֹמַר שֶׁהֵפֵר לָהּ. הֲנָאָה זוֹ אֵינִי יוֹדֵעַ מַה הִיא, כְּשֶׁהוּא אוֹמֵר \\\"וְאִם בְּיוֹם שְׁמֹעַ אִישָהּ יָנִיא אוֹתָהּ וְהֵפֵר\\\" (פסוק ט') הֱוֵי אוֹמֵר הֲנָאָה זוֹ הֲפָרָה. וּפְשׁוּטוֹ לְשׁוֹן מְנִיעָה וַהֲסָרָה, וְכֵן \\\"וְלָמָּה תְנִיאוּן\\\" (במדבר ל\\\"ב), וְכֵן \\\"שֶׁמֶן רֹאשׁ אַל יָנִי רֹאשִׁי\\\" (תהילים קמ\\\"א), וְכֵן \\\"וִידַעְתֶּם אֶת תְּנוּאָתִי\\\" (במדבר י\\\"ד) — אֶת אֲשֶׁר סַרְתֶּם מֵעָלַי:\",1,0],[2,133,30,6,\"וה' יסלח לה. בַּמֶּה הַכָּתוּב מְדַבֵּר? בְּאִשָּׁה שֶׁנָּדְרָה בְנָזִיר וְשָׁמַע בַּעְלָהּ וְהֵפֵר לָהּ וְהִיא לֹא יָדְעָה וְעוֹבֶרֶת עַל נִדְרָהּ וְשׁוֹתָה יַיִן וּמִטַּמְּאָה לְמֵתִים, זוֹ הִיא שֶׁצְּרִיכָה סְלִיחָה וְאַעַ\\\"פִּ שֶׁהוּא מוּפָר, וְאִם הַמּוּפָרִין צְרִיכִים סְלִיחָה, קַ\\\"וָ לְשֶׁאֵינָן מוּפָרִים (עי' קידושין פ\\\"א):\",2,0],[2,133,30,7,\"ואם היו תהיה לאיש. זוֹ אֲרוּסָה, אוֹ אֵינוֹ אֶלָּא נְשׂוּאָה? כְּשֶׁהוּא אוֹמֵר \\\"וְאִם בֵּית אִישָׁהּ נָדָרָה\\\" הֲרֵי נְשׂוּאָה אָמוּר, וְכָאן בַּאֲרוּסָה, וּבָא לַחֲלֹק בָּהּ שֶׁאָבִיהָ וּבַעְלָהּ מְפֵרִין נְדָרֶיהָ, הֵפֵר הָאָב וְלֹא הֵפֵר הַבַּעַל, אוֹ הֵפֵר הַבַּעַל וְלֹא הֵפֵר הָאָב, הֲרֵי זֶה אֵינוֹ מוּפָר, וְאֵין צָרִיךְ לוֹמַר אִם קִיֵּם אֶחָד מֵהֶם:\",1,0],[2,133,30,7,\"ונדריה עליה. שֶׁנָּדְרָה בְּבֵית אָבִיהָ, וְלֹא שָׁמַע בָּהֶן אָבִיהָ וְלֹא הוּפְרוּ וְלֹא הוּקְמוּ (עי' ספרי):\",2,0],[2,133,30,8,\"ושמע אישה וגו'. הֲרֵי לְךָ שֶׁאִם קִיֵּם הַבַּעַל שֶׁהוּא קַיָּם:\",1,0],[2,133,30,9,\"והפר את נדרה. יָכוֹל אֲפִלּוּ לֹא הֵפֵר הָאָב, תַּ\\\"ל (פסוק י\\\"ז) \\\"בִּנְעֻרֶיהָ בֵּית אָבִיהָ\\\" — כָּל שֶׁבִּנְעוּרֶיהָ בִּרְשׁוּת אָבִיהָ הִיא (ספרי שם):\",1,0],[2,133,30,10,\"כל אשר אסרה על נפשה יקום עליה. לְפִי שֶׁאֵינָהּ לֹא בִרְשׁוּת אָב וְלֹא בִרְשׁוּת בַּעַל, וּבְאַלְמָנָה מִן הַנִּשּׂוּאִין הַכָּתוּב מְדַבֵּר, אֲבָל אַלְמָנָה מִן הָאֵרוּסִין — מֵת הַבַּעַל נִתְרוֹקְנָה וְחָזְרָה רְשׁוּת לָאָב (נדרים ע'):\",1,0],[2,133,30,11,\"ואם בית אשה נדרה. בִּנְשׂוּאָה הַכָּתוּב מְדַבֵּר (שם ס\\\"ז):\",1,0],[2,133,30,14,\"כל נדר וכל שבעת אסר וגו'. לְפִי שֶׁאָמַר שֶׁהַבַּעַל מֵפֵר, יָכוֹל כָּל נְדָרִים בְמַשְׁמָע, תַּ\\\"ל לענת נפש — אֵינוֹ מֵפֵר אֶלָּא נִדְרֵי עִנּוּי נֶפֶשׁ בִּלְבַד, וְהֵם מְפֹרָשִׁים בְּמַסֶּ' נְדָרִים (דף ע\\\"ט):\",1,0],[2,133,30,15,\"מיום אל יום. שֶׁלֹּא תֹאמַר מֵעֵת לְעֵת, לְכָךְ נֶאֱמַר \\\"מִיּוֹם אֶל יוֹם\\\", לְלַמֶּדְךָ שֶׁאֵין מֵפֵר אֶלָּא עַד שֶׁתֶּחְשַׁךְ (נדרים ע\\\"ו):\",1,0],[2,133,30,16,\"אחרי שמעו. אַחֲרֵי שֶׁשָּׁמַע וְקִיֵּם, שֶׁאָמַר אֶפְשִׁי בּוֹ, וְחָזַר וְהֵפֵר לָהּ אֲפִלּוּ בּוֹ בַּיּוֹם:\",1,0],[2,133,30,16,\"ונשא את עונה. הוּא נִכְנָס תַּחְתֶּיהָ. לָמַדְנוּ מִכָּאן שֶׁהַגּוֹרֵם תַּקָּלָה לַחֲבֵרוֹ הוּא נִכְנָס תַּחְתָּיו לְכָל עֳנָשִׁין:\",2,0],[2,133,31,2,\"מאת המדינים. וְלֹא מֵאֵת הַמּוֹאָבִים, שֶׁהַמּוֹאָבִים נִכְנְסוּ לַדָּבָר מֵחֲמַת יִרְאָה, שֶׁהָיוּ יְרֵאִים מֵהֶם שֶׁיִּהְיוּ שׁוֹלְלִים אוֹתָם, שֶׁלֹּא נֶאֱמַר אֶלָּא \\\"וְאַל תִּתְגָּר בָּם מִלְחָמָה\\\" (דברים ב'), אֲבָל מִדְיָנִים נִתְעַבְּרוּ עַל רִיב לֹא לָהֶם; דָּ\\\"אַ, מִפְּנֵי שְׁנֵי פְרֵידוֹת טוֹבוֹת שֶׁיֵּשׁ לִי לְהוֹצִיא מֵהֶם — רוּת הַמּוֹאֲבִיָּה וְנַעֲמָה הָעַמּוֹנִית (בבא קמא ל\\\"ח):\",1,0],[2,133,31,3,\"וידבר משה וגו'. אַעַ\\\"פִּ שֶׁשָּׁמַע שֶׁמִּיתָתוֹ תְלוּיָה בַּדָּבָר עָשָׂה בְשִׂמְחָה וְלֹא אֵחַר (ספרי):\",1,0],[2,133,31,3,\"החלצו. כְּתַרְגּוּמוֹ, לְשׁוֹן חֲלוּצֵי צָבָא — מְזֻיָּנִים:\",2,0],[2,133,31,3,\"אנשים. צַדִּיקִים, וְכֵן \\\"בְּחַר לָנוּ אֲנָשִׁים\\\" (שמות י\\\"ז), וְכֵן \\\"אֲנָשִׁים חֲכָמִים וִידֻעִים\\\" (דברים א'):\",3,0],[2,133,31,3,\"נקמת ה'. שֶׁהָעוֹמֵד כְּנֶגֶד יִשְׂרָאֵל כְּאִלּוּ עוֹמֵד כְּנֶגֶד הַקָּבָּ\\\"ה:\",4,0],[2,133,31,4,\"לכל מטות ישראל. לְרַבּוֹת שֵׁבֶט לֵוִי (ספרי):\",1,0],[2,133,31,5,\"וימסרו. לְהוֹדִיעֲךָ שִׁבְחָן שֶׁל רוֹעֵי יִשְׂרָאֵל כַּמָּה הֵם חֲבִיבִים עַל יִשְׂרָאֵל, עַד שֶׁלֹּא שָׁמְעוּ בְמִיתָתוֹ מַה הוּא אוֹמֵר? \\\"עוֹד מְעַט וּסְקָלֻנִי\\\" (שמות י\\\"ז), וּמִשֶּׁשָּׁמְעוּ שֶׁמִּיתַת מֹשֶׁה תְלוּיָה בְנִקְמַת מִדְיָן לֹא רָצוּ לָלֶכֶת עַד שֶׁנִּמְסְרוּ עַל כָּרְחָן (ספרי):\",1,0],[2,133,31,6,\"אתם ואת פינחס. מַגִּיד שֶׁהָיָה פִינְחָס שָׁקוּל כְּנֶגֶד כֻּלָּם (ספרי); וּמִפְּנֵי מָה הָלַךְ פִּינְחָס וְלֹא הָלַךְ אֶלְעָזָר? אָמַר הַקָּבָּ\\\"ה מִי שֶׁהִתְחִיל בַּמִּצְוָה, שֶׁהָרַג כָּזְבִּי בַת צוּר, יִגְמֹר; דָּ\\\"אַ — שֶׁהָלַךְ לִנְקֹם נִקְמַת יוֹסֵף אֲבִי אִמּוֹ, שֶׁנֶּאֱמַר \\\"וְהַמְּדָנִים מָכְרוּ אֹתוֹ\\\" (בראשית ל\\\"ז); וּמִנַּיִן שֶׁהָיְתָה אִמּוֹ שֶׁל פִּינְחָס מִשֶּׁל יוֹסֵף? שֶׁנֶּאֱמַר \\\"מִבְּנוֹת פּוּטִיאֵל\\\" (שמות ו') — מִזֶּרַע יִתְרוֹ שֶׁפִּטֵּם עֲגָלִים לַעֲ\\\"זָ, וּמִזֶּרַע יוֹסֵף שֶׁפִּטְפֵּט בְּיִצְרוֹ (סוטה מ\\\"ג); דָּבָר אַחֵר — שֶׁהָיָה מְשׁוּחַ מִלְחָמָה (שם):\",1,0],[2,133,31,6,\"וכלי הקדש. זֶה הָאָרוֹן וְהַצִּיץ, שֶׁהָיָה בִּלְעָם עִמָּהֶם וּמַפְרִיחַ מַלְכֵי מִדְיָן בִּכְשָׁפִים וְהוּא עַצְמוֹ פוֹרֵחַ עִמָּהֶם, הֶרְאָה לָהֶם אֶת הַצִּיץ שֶׁהַשֵּׁם חָקוּק בּוֹ וְהֵם נוֹפְלִים, לְכָךְ נֶאֱמַר \\\"עַל חַלְלֵיהֶם\\\" בְּמַלְכֵי מִדְיָן — שֶׁנּוֹפְלִים עַל הַחֲלָלִים מִן הָאֲוִיר, וְכֵן בְּבִלְעָם כָּתוּב \\\"עַל חַלְלֵיהֶם\\\" בְּסֵ' יְהוֹשֻׁעַ (תנחומא):\",2,0],[2,133,31,6,\"בידו. בִּרְשׁוּתוֹ, וְכֵן (במדבר כ\\\"א) \\\"וַיִּקַּח אֶת כָּל אַרְצוֹ מִיָּדוֹ\\\" (ספרי):\",3,0],[2,133,31,8,\"חמשת מלכי מדין. וְכִי אֵינִי רוֹאֶה שֶׁחֲמִשָּׁה מָנָה הַכָּתוּב? לָמָּה הֻזְקַק לוֹמַר חֲמֵשֶׁת? אֶלָּא לְלַמֶּדְךָ שֶׁשָּׁווּ כֻלָּם בָּעֵצָה וְהֻשְׁווּ כֻלָּם בַּפֻּרְעָנוּת (שם); בִּלְעָם הָלַךְ שָׁם לִטֹּל שְׂכַר עֶשְׂרִים וְאַרְבָּעָה אֶלֶף שֶׁהִפִּיל מִיִּשְׂרָאֵל בַּעֲצָתוֹ, וְיָצָא מִמִּדְיָן לִקְרַאת יִשְׂרָאֵל וּמַשִּׂיאָן עֵצָה רָעָה — אָמַר לָהֶם אִם כְּשֶׁהֱיִיתֶם שִׁשִּׁים רִבּוֹא לֹא יְכָלְתֶּם לָהֶם, וְעַכְשָׁיו בְּי\\\"ב אֶלֶף אַתֶּם בָּאִים לְהִלָּחֵם? — נָתְנוּ לוֹ שְׂכָרוֹ מִשָּׁלֵם וְלֹא קִפְּחוּהוּ (ספרי):\",1,0],[2,133,31,8,\"בחרב. הוּא בָא עַל יִשְׂרָאֵל וְהֶחֱלִיף אֻמָּנוּתוֹ בְּאֻמָּנוּתָם, שֶׁאֵין נוֹצְחִים אֶלָּא בְּפִיהֶם וְעַל יְדֵי תְפִלָּה וּבַקָּשָׁה, וּבָא הוּא וְתָפַשׂ אֻמָּנוּתָם לְקַלְּלָם בְּפִיו, אַף הֵם בָּאוּ עָלָיו וְהֶחֱלִיפוּ אֻמָּנוּתָם בְּאֻמָּנוּת הָאֻמּוֹת שֶׁבָּאִין בַּחֶרֶב, שֶׁנֶּאֱמַר \\\"וְעַל חַרְבְּךָ תִחְיֶה\\\" (בראשית כ\\\"ז):\",2,0],[2,133,31,10,\"טירתם. מְקוֹם נוֹטִירִין שֶׁלָּהֶם, שֶׁהוּא לְשׁוֹן מוֹשַׁב כּוּמָרִים יוֹדְעֵי חֻקֵּיהֶם; דָּ\\\"אַ — לְשׁוֹן מוֹשַׁב שָׂרֵיהֶם, כְּמוֹ שֶׁמְּתֻרְגָּם \\\"סַרְנֵי פְלִשְׁתִּים\\\" (שמואל א ו') — טוּרְנֵי פְלִשְׁתָּאֵי:\",1,0],[2,133,31,11,\"ויקחו את כל השלל וגו'. מַגִּיד שֶׁהָיוּ כְשֵׁרִים וְצַדִּיקִים, וְלֹא נֶחְשְׁדוּ עַל הַגֶּזֶּל לִשְׁלֹחַ יָד בַּבִּזָּה שֶׁלֹּא בִרְשׁוּת, שֶׁנֶּאֱמַר את כל השלל וגו', וַעֲלֵיהֶם מְפֹרָשׁ בַּקַּבָּלָה \\\"שִׁנַּיִךְ כְּעֵדֶר הָרְחֵלִים\\\" וְגוֹ' (שיר השירים ו׳:ו׳) — אַף אַנְשֵׁי הַמִּלְחָמָה שֶׁבָּךְ כֻּלָּם צַדִּיקִים:\",1,0],[2,133,31,11,\"שלל. הֵן מִטַּלְטְלִין שֶׁל מַלְבּוּשׁ וְתַכְשִׁיטִין:\",2,0],[2,133,31,11,\"בז. הוּא בִזַּת מִטַּלְטְלִין שֶׁאֵינָם תַּכְשִׁיט:\",3,0],[2,133,31,11,\"מלקוח. אָדָם וּבְהֵמָה, וּבְמָקוֹם שֶׁכָּתוּב שְׁבִי אֵצֶל מַלְקוֹחַ, שְׁבִי בָאָדָם וּמַלְקוֹחַ בַּבְּהֵמָה:\",4,0],[2,133,31,13,\"ויצאו משה ואלעזר הכהן. לְפִי שֶׁרָאוּ אֶת נַעֲרֵי יִשְׂרָאֵל יוֹצְאִים לַחֲטֹף מִן הַבִּזָּה (ספרי):\",1,0],[2,133,31,14,\"ויקצף משה על פקודי החיל. מְמֻנִּים עַל הַחַיִל, לְלַמֶּדְךָ שֶׁכָּל סִרְחוֹן הַדּוֹר תָּלוּי בַּגְּדוֹלִים שֶׁיֵּשׁ כֹּחַ בְּיָדָם לִמְחוֹת (שם):\",1,0],[2,133,31,16,\"הן הנה. מַגִּיד שֶׁהָיוּ מַכִּירִים אוֹתָן — זוֹ הִיא שֶׁנִּכְשַׁל פְּלוֹנִי בָהּ (ילקוט שמעוני תשפ\\\"ה):\",1,0],[2,133,31,16,\"בדבר בלעם. אָמַר לָהֶם אֲפִלּוּ אַתֶּם מַכְנִיסִין כָּל הֲמוֹנוֹת שֶׁבָּעוֹלָם אֵין אַתֶּם יְכוֹלִים לָהֶם, שֶׁמָּא מְרֻבִּים אַתֶּם מִן הַמִּצְרִיִּים שֶׁהָיוּ שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר? בֹּאוּ וְאַשִּׂיאֲכֶם עֵצָה, אֱלֹהֵיהֶם שֶׁל אֵלּוּ שׂוֹנֵא זִמָּה הוּא וְכוּ' כִּדְאִיתָא בְחֵלֶק (דף ק\\\"ו) וּבְסִפְרֵי:\",2,0],[2,133,31,17,\"וכל אשה ידעת אישׁ. רְאוּיָה לִבָּעֵל, אַעַ\\\"פִּ שֶׁלֹּא נִבְעֲלָה, וְלִפְנֵי הַצִּיץ הֶעֱבִירוּם, וְהָרְאוּיָה לִבָּעֵל פָּנֶיהָ מוֹרִיקוֹת (יבמות ס'):\",1,0],[2,133,31,17,\"הרגו. לָמָּה חָזַר וְאָמַר? לְהַפְסִיק הָעִנְיָן, דִּבְרֵי רַבִּי יִשְׁמָעֵאל, שֶׁאִם אֲנִי קוֹרֵא הִרְגוּ כָל זָכָר בַּטָּף וְכָל אִשָּׁה יֹדַעַת אִישׁ וְכֹל הַטַּף בַּנָּשִׁים וְגוֹ', אֵינִי יוֹדֵעַ אִם לַהֲרֹג עִם הַזְּכָרִים אוֹ לְהַחֲיוֹת עִם הַטַּף, לְכָךְ נֶאֱמַר הֲרֹגוּ:\",2,0],[2,133,31,19,\"מחוץ למחנה. שֶׁלֹּא יִכָּנְסוּ לָעֲזָרָה:\",1,0],[2,133,31,19,\"כל הרג נפש. רַ' מֵאִיר אוֹמֵר בְּהוֹרֵג בְּדָבָר הַמְקַבֵּל טֻמְאָה הַכָּתוּב מְדַבֵּר, וְלִמֶּדְךָ הַכָּתוּב שֶׁהַכְּלִי מְטַמֵּא אָדָם בְּחִבּוּרֵי הַמֵּת כְּאִלּוּ נוֹגֵעַ בַּמֵּת עַצְמוֹ, אוֹ יָכוֹל אֲפִלּוּ זָרַק בּוֹ חֵץ וַהֲרָגוֹ? תַּלְמוּד לוֹמַר וכל נגע בחלל, הִקִּישׁ הוֹרֵג לְנוֹגֵעַ, מַה נּוֹגֵעַ עַל יְדֵי חִבּוּרוֹ, אַף הוֹרֵג עַ\\\"יְ חִבּוּרוֹ (ספרי במדבר י\\\"ט):\",2,0],[2,133,31,19,\"תתחטאו. בְּמֵי נִדָּה כְּדִין שְׁאָר טְמֵאֵי מֵתִים, שֶׁאַף לְדִבְרֵי הָאוֹמְרִים קִבְרֵי גוֹיִם אֵינָם מְטַמְּאִין בָּאֹהֶל, שֶׁנֶּאֱמַר (יחזקאל ל\\\"ד) \\\"וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם\\\" — אַתֶּם קְרוּיִם אָדָם — מוֹדֶה הוּא שֶׁהַגּוֹיִם מְטַמְּאִים בְּמַגַּע וּבְמַשָּׂא, שֶׁלֹּא נֶאֱמַר אָדָם אֶלָּא אֵצֶל טֻמְאַת אָהֳלוֹת, שֶׁנֶּאֱמַר \\\"אָדָם כִּי יָמוּת בְּאֹהֶל\\\" (במדבר י\\\"ט):\",3,0],[2,133,31,19,\"אתם ושביכם. לֹא שֶׁהַגּוֹיִם מְקַבְּלִין טֻמְאָה וּצְרִיכִין הַזָּאָה, אֶלָּא מָה אַתֶּם בְּנֵי בְרִית, אַף שְׁבִיכֶם כְּשֶׁיָּבֹאוּ לַבְּרִית וְיִטָּמְאוּ, צְרִיכִין הַזָּאָה (ספרי):\",4,0],[2,133,31,20,\"וכל מעשה עזים. לְהָבִיא כְלֵי הַקַּרְנַיִם וְהַטְּלָפַיִם וְהָעֲצָמוֹת (חולין כ\\\"ה):\",1,0],[2,133,31,21,\"ויאמר אלעזר הכהן וגו'. לְפִי שֶׁבָּא מֹשֶׁה לִכְלַל כַּעַס בָּא לִכְלַל טָעוּת, שֶׁנִּתְעַלְּמוּ מִמֶּנּוּ הִלְכוֹת גִּעוּלֵי גּוֹיִם, וְכֵן אַתָּה מוֹצֵא בַשְּׁמִינִי לַמִּלּוּאִים, שֶׁנֶּאֱמַר \\\"וַיִּקְצֹף עַל אֶלְעָזָר וְעַל אִיתָמָר\\\" (ויקרא י') — בָּא לִכְלַל כַּעַס בָּא לִכְלַל טָעוּת, וְכֵן בְּשִׁמְעוּ נָא הַמֹּרִים (במדבר כ') \\\"וַיַּךְ אֶת הַסֶּלַע\\\" — עַל יְדֵי הַכַּעַס טָעָה (ספרי; פסחים ס\\\"ו):\",1,0],[2,133,31,21,\"אשר צוה ה' וגו'. תָּלָה הַהוֹרָאָה בְּרַבּוֹ (עי' ספרי):\",2,0],[2,133,31,22,\"אך את הזהב וגו'. אַעַ\\\"פִּ שֶׁלֹּא הִזְהִיר לָכֶם מֹשֶׁה אֶלָּא עַל הִלְכוֹת טֻמְאָה, עוֹד יֵשׁ לְהַזְהִיר לָכֶם עַל הִלְכוֹת גִּעוּל, וְ\\\"אַךְ\\\" לְשׁוֹן מִעוּט, כְּלוֹמַר מְמֻעָטִין אַתֶּם מִלְּהִשְׁתַּמֵּשׁ בַּכֵּלִים אֲפִלּוּ לְאַחַר טָהֲרָתָן מִטֻּמְאַת הַמֵּת עַד שֶׁיִּטְהֲרוּ מִבְּלִיעַת אִסּוּר נְבֵלוֹת; וְרַבּוֹתֵינוּ אָמְרוּ, אך את הזהב לוֹמַר, שֶׁצָּרִיךְ לְהַעֲבִיר חֲלוּדָה שֶׁלּוֹ קֹדֶם שֶׁיַּגְעִילֶנּוּ, וְזֶהוּ לְשׁוֹן אך, שֶׁלֹּא יְהֵא שָׁם חֲלוּדָה אַךְ הַמַּתֶּכֶת יִהְיֶה כְּמוֹ שֶׁהוּא:\",1,0],[2,133,31,23,\"כל דבר אשר יבא באש. לְבַשֵּׁל בּוֹ כְּלוּם:\",1,0],[2,133,31,23,\"תעבירו באש. כְּדֶרֶךְ תַּשְׁמִישׁוֹ הַגְעָלָתוֹ — מִי שֶׁתַּשְׁמִישׁוֹ עַל יְדֵי חַמִּין יַגְעִילֶנּוּ בְחַמִּין, וּמִי שֶׁתַּשְׁמִישׁוֹ עַ\\\"יְ צְלִי, כְּגוֹן הַשְּׁפוּד וְהָאַסְכְּלָה, יְלַבְּנוֹ בָּאוּר (עבודה זרה ע\\\"ד):\",2,0],[2,133,31,23,\"אך במי נדה יתחטא. לְפִי פְשׁוּטוֹ חִטּוּי זֶה לְטַהֲרוֹ מִטֻּמְאַת מֵת, אָמַר לָהֶם צְרִיכִין הַכֵּלִים גִּעוּל לְטַהֲרָם מִן הָאִסּוּר וְחִטּוּי לְטַהֲרָן מִן הַטֻּמְאָה; וְרַבּוֹתֵינוּ דָרְשׁוּ מִכָּאן שֶׁאַף לְהַכְשִׁירָן מִן הָאִסּוּר הִטְעִין טְבִילָה לִכְלֵי מַתָּכוֹת, וּמֵי נִדָּה הַכְּתוּבִין כָּאן דָּרְשׁוּ מַיִם הָרְאוּיִם לִטְבֹּל בָּהֶם נִדָּה, וְכַמָּה הֵם? אַרְבָּעִים סְאָה (שם ע\\\"ה):\",3,0],[2,133,31,23,\"וכל אשר לא יבא באש. כָּל דָּבָר שֶׁאֵין תַּשְׁמִישׁוֹ עַל יְדֵי הָאוּר, כְּגוֹן כּוֹסוֹת וּצְלוֹחִיּוֹת שֶׁתַּשְׁמִישָׁן בְּצוֹנֵן וְלֹא בָלְעוּ אִסּוּר:\",4,0],[2,133,31,23,\"תעבירו במים. מַטְבִּילָן וְדַיּוֹ, וְדַוְקָא כְלֵי מַתָּכוֹת:\",5,0],[2,133,31,24,\"אל המחנה. לְמַחֲנֵה שְׁכִינָה, שֶׁאֵין טְמֵא מֵת טָעוּן שִׁלּוּחַ מִמַּחֲנֵה לְוִיָּה וּמִמַּחֲנֵה יִשְׂרָאֵל:\",1,0],[2,133,31,26,\"שא את ראש. קַח אֶת הַחֶשְׁבּוֹן:\",1,0],[2,133,31,27,\"וחצית את המלקוח בין תפשי המלחמה וגו'. חֶצְיוֹ לָאֵלּוּ וְחֶצְיוֹ לָאֵלּוּ:\",1,0],[2,133,31,32,\"ויהי המלקוח יתר הבז. לְפִי שֶׁלֹּא נִצְטַוּוּ לְהָרִים מֶכֶס מִן הַמִּטַּלְטְלִין אֶלָּא מִן הַמַּלְקוֹחַ, כָּתַב אֶת הַלָּשׁוֹן הַזֶּה ויהי המלקוח, שֶׁבָּא לִכְלַל חֲלֻקָּה וְלִכְלַל מֶכֶס, שֶׁהָיָה עוֹדֵף עַל בַּז הַמִּטַּלְטְלִין אשר בזזו עם הצבא איש לו וְלֹא בָא לִכְלַל חֲלֻקָּה — מִסְפַּר הַצֹּאן וְגוֹ':\",1,0],[2,133,31,42,\"וממחצית בני ישראל אשר חצה משה. לָעֵדָה, וְהוֹצִיאָהּ לָהֶם מן האנשים הצבאים:\",1,0],[2,133,31,43,\"ותהי מחצת העדה. כָּךְ וְכָךְ:\",1,0],[2,133,31,47,\"ויקח משה וגו'.\",1,0],[2,133,31,48,\"הפקדים. הַמְמֻנִּים:\",1,0],[2,133,31,49,\"ולא נפקד. לֹא נֶחְסַר, וְתַרְגּוּמוֹ \\\"לָא שְׁגָא\\\", אַף הוּא בִּלְשׁוֹן אֲרַמִי חִסָּרוֹן, כְּמוֹ \\\"אָנֹכִי אֲחַטֶּנָּה\\\" (בראשית ל\\\"א) תַרְגּוּמוֹ \\\"דַּהֲוַת שָׁגְיָא מִמִּנְיָנָא\\\", וְכֵן \\\"כִּי יִפָּקֵד מוֹשָׁבֶךָ\\\" (שמואל א כ') — יֶחְסַר מְקוֹם מוֹשָׁבְךָ, אִישׁ הָרָגִיל לֵישֵׁב שָׁם, וְכֵן \\\"וַיִּפָּקֵד מְקוֹם דָּוִד\\\" (שם) — נֶחְסַר מְקוֹמוֹ וְאֵין אִישׁ יוֹשֵׁב שָׁם:\",1,0],[2,133,31,50,\"אצעדה. אֵלּוּ צְמִידִים שֶׁל רֶגֶל:\",1,0],[2,133,31,50,\"וצמיד. שֶׁל יָד:\",2,0],[2,133,31,50,\"עגיל. נִזְמֵי אֹזֶן:\",3,0],[2,133,31,50,\"וכומז. דְּפוּס שֶׁל בֵּית הָרֶחֶם, לְכַפֵּר הִרְהוּר הַלֵּב שֶׁל בְּנוֹת מִדְיָן (שבת ס\\\"ד):\",4,0],[2,133,32,3,\"עטרות ודיבן וגו'. מֵאֶרֶץ סִיחוֹן וְעוֹג הָיוּ:\",1,0],[2,133,32,6,\"האחיכם. לְשׁוֹן תְּמִיהָה הוּא:\",1,0],[2,133,32,7,\"ולמה תניאון. תָּסִירוּ וְתַמְנִיעוּ לִבָּם מֵעֲבֹר, שֶׁיִּהְיוּ סְבוּרִים שֶׁאַתֶּם יְרֵאִים לַעֲבֹר מִפְּנֵי הַמִּלְחָמָה וְחֹזֶק הֶעָרִים וְהָעָם:\",1,0],[2,133,32,8,\"מקדש ברנע. כָּךְ שְׁמָהּ, וּשְׁתֵּי קָדֵשׁ הָיוּ:\",1,0],[2,133,32,12,\"הקנזי. חוֹרְגוֹ שֶׁל קְנַז הָיָה וְיָלְדָה לוֹ אִמּוֹ שֶׁל כָּלֵב אֶת עָתְנִיאֵל (סוטה י\\\"א):\",1,0],[2,133,32,13,\"וינעם. וַיְטַלְטְלֵם, מִן \\\"נָע וָנָד\\\" (בראשית ד):\",1,0],[2,133,32,14,\"לספות. כְּמוֹ \\\"סְפוּ שָׁנָה עַל שָׁנָה\\\" (ישעיהו כ\\\"ט), \\\"עֹלוֹתֵיכֶם סְפוּ\\\" וְגוֹ' (ירמיהו ז'), לְשׁוֹן תּוֹסֶפֶת:\",1,0],[2,133,32,16,\"נבנה למקננו פה. חָסִים הָיוּ עַל מָמוֹנָם יוֹתֵר מִבְּנֵיהֶם וּבְנוֹתֵיהֶם, שֶׁהִקְדִּימוּ מִקְנֵיהֶם לְטַפָּם. אָמַר לָהֶם מֹשֶׁה \\\"לֹא כֵן, עֲשׂוּ הָעִקָּר עִקָּר וְהַטָּפֵל טָפֵל, בְּנוּ לָכֶם תְּחִלָּה עָרִים לְטַפְּכֶם וְאַחַר כֵּן גְּדֵרוֹת לְצֹאנְכֶם\\\" (תנחומא):\",1,0],[2,133,32,17,\"ואנחנו נחלץ חשים. נִזְדַּיֵּן מְהִירִים, כְּמוֹ \\\"מַהֵר שָׁלָל חָשׁ בַּז\\\" (ישעיהו ח'), \\\"יְמַהֵר יָחִישָׁה\\\" (שם ה'):\",1,0],[2,133,32,17,\"לפני בני ישראל. בְּרָאשֵׁי גְּיָסוֹת, מִתּוֹךְ שֶׁגִּבּוֹרִים הָיוּ, שֶׁכֵּן נֶאֱמַר בְּגָד (דברים ל\\\"ג) \\\"וְטָרַף זְרוֹעַ אַף קָדְקֹד\\\"; וְאַף מֹשֶׁה חָזַר וּפֵרֵשׁ לָהֶם בְּאֵלֶּה הַדְּבָרִים (דברים ג') \\\"וָאֲצַו אֶתְכֶם בָּעֵת הַהִוא וְגוֹ' חֲלוּצִים תַּעַבְרוּ לִפְנֵי אֲחֵיכֶם בְּנֵי יִשְׂרָאֵל כָּל בְּנֵי חָיִל\\\", וּבִירִיחוֹ כְּתִיב (יהושע ו') \\\"וְהֶחָלוּץ עוֹבֵר (הֹלֵךְ) לִפְנֵיהֶם\\\" — זֶה רְאוּבֵן וְגָד שֶׁקִּיְּמוּ תְנָאָם:\",2,0],[2,133,32,17,\"וישב טפנו. בְּעוֹדֵנוּ אֵצֶל אַחֵינוּ:\",3,0],[2,133,32,17,\"בערי המבצר. שֶׁנִּבְנֶה עַכְשָׁו:\",4,0],[2,133,32,19,\"מעבר לירדן והלאה. בָּעֵבֶר הַמַּעֲרָבִי:\",1,0],[2,133,32,19,\"כי באה נחלתנו. כְּבָר קִבַּלְנוּהָ בָּעֵבֶר הַמִּזְרָחִי:\",2,0],[2,133,32,24,\"לצנאכם. תֵּבָה זוֹ מִגִּזְרַת \\\"צֹנֶה וַאֲלָפִים כֻּלָּם\\\" (תהלים ח') שֶׁאֵין בּוֹ אָלֶ\\\"ף מַפְסִיק בֵּין נוּ\\\"ן לַצָּדִ\\\"י, וְאָלֶ\\\"ף שֶׁבָּא כָאן אַחַר הַנּוּ\\\"ן בִּמְקוֹם הֵ\\\"א שֶׁל צֹנֶה הוּא; מִיסוֹדוֹ שֶׁל רַ' מֹשֶׁה הַדַּרְשָׁן לָמַדְתִּי כֵן:\",1,0],[2,133,32,24,\"והיצא מפיכם תעשו. לְגָבוֹהַּ, שֶׁקִּבַּלְתֶּם עֲלֵיכֶם לַעֲבֹר לַמִּלְחָמָה עַד כִּבּוּשׁ וְחִלּוּק, שֶׁמֹּשֶׁה לֹא בִּקֵּשׁ מֵהֶם אֶלָּא \\\"וְנִכְבְּשָׁה … וְאַחַר תָּשׁוּבוּ\\\" וְהֵם קִבְּלוּ עֲלֵיהֶם \\\"עַד הִתְנַחֵל\\\", הֲרֵי הוֹסִיפוּ לְהִתְעַכֵּב שֶׁבַע שֶׁחָלְקוּ, וְכֵן עָשׂוּ:\",2,0],[2,133,32,25,\"ויאמר בני גד. כֻּלָּם כְּאִישׁ אֶחָד:\",1,0],[2,133,32,28,\"ויצו להם. כְּמוֹ עֲלֵיהֶם, וְעַל תְּנָאָם מִנָּה אֶלְעָזָר וִיהוֹשֻׁעַ, כְּמוֹ \\\"ה' יִלָּחֵם לָכֶם\\\" (שמות י\\\"ד):\",1,0],[2,133,32,32,\"ואתנו אחזת נחלתנו. כְּלוֹמַר בְּיָדֵינוּ וּבִרְשׁוּתֵנוּ תְהִי אֲחֻזַּת נַחֲלָתֵנוּ מֵעֵבֶר הַזֶּה:\",1,0],[2,133,32,36,\"ערי מבצר וגדרת צאן. זֶה סוֹף פָּסוּק מוּסָב עַל תְּחִלַּת הָעִנְיָן — וַיִּבְנוּ בְנֵי גָד אֶת הֶעָרִים הַלָּלוּ לִהְיוֹת עָרֵי מִבְצָר וְגִדְרֹת צֹאן:\",1,0],[2,133,32,38,\"ואת נבו ואת בעל מעון מוסבת שם. נְבוֹ וּבַעַל מְעוֹן שְׁמוֹת עֲ\\\"זָ הֵם, וְהָיוּ הָאֱמוֹרִיִּים קוֹרִים עָרֵיהֶם עַל שֵׁם עֲ\\\"זָ שֶׁלָּהֶם, וּבְנֵי רְאוּבֵן הֵסֵבּוּ אֶת שְׁמָם לְשֵׁמוֹת אֲחֵרִים, וְזֶהוּ מוסבת שם — נְבוֹ וּבַעַל מְעוֹן מוּסַבּוֹת לְשֵׁם אַחֵר:\",1,0],[2,133,32,38,\"ואת שבמה. בָּנוּ שִׂבְמָה, וְהִיא שְׂבָם הָאֲמוּרָה לְמַעְלָה:\",2,0],[2,133,32,39,\"ויורש. כְּתַרְגּוּמוֹ \\\"וְתָרִיךְ\\\", שֶׁתֵּבַת ריש מְשַׁמֶּשֶׁת שְׁתֵּי מַחֲלָקוֹת, לְשׁוֹן יְרֻשָּׁה וּלְשׁוֹן הוֹרָשָׁה שֶׁהוּא טֵרוּד וְתֵרוּךְ:\",1,0],[2,133,32,41,\"חותיהם. כַּפְרָנֵיהוֹן:\",1,0],[2,133,32,41,\"ויקרא אתהן חות יאיר. לְפִי שֶׁלֹּא הָיוּ לוֹ בָנִים קְרָאַתָם בִּשְׁמוֹ לְזִכָּרוֹן:\",2,0],[2,133,32,42,\"ויקרא לה נבח. \\\"לָה\\\" אֵינוֹ מַפִּיק הֵ\\\"א, וְרָאִיתִי בִיסוֹדוֹ שֶׁל רַ' מֹשֶׁה הַדַּרְשָׁן לְפִי שֶׁלֹּא נִתְקַיֵּם לָהּ שֵׁם זֶה לְפִיכָךְ הוּא רָפֶה, שֶׁמַּשְׁמָעוּת מִדְרָשׁוֹ כְּמוֹ לֹא; וּתְמֵהַנִי מַה יִּדְרֹשׁ בִּשְׁתֵּי תֵבוֹת הַדּוֹמוֹת לָהּ \\\"וַיֹּאמֶר לָה בֹעַז\\\" (רות ב'), \\\"לִבְנוֹת לָה בַיִת\\\" (זכריה ה'):\",1,0],[2,133,33,1,\"אלה מסעי. לָמָּה נִכְתְּבוּ הַמַּסָּעוֹת הַלָּלוּ? לְהוֹדִיעַ חֲסָדָיו שֶׁל מָקוֹם, שֶׁאַעַ\\\"פִּ שֶׁגָּזַר עֲלֵיהֶם לְטַלְטְלַם וְלַהֲנִיעָם בַּמִּדְבָּר, לֹא תֹאמַר שֶׁהָיוּ נָעִים וּמְטֻלְטָלִים מִמַּסָּע לְמַסָּע כָּל אַרְבָּעִים שָׁנָה וְלֹא הָיְתָה לָהֶם מְנוּחָה, שֶׁהֲרֵי אֵין כָּאן אֶלָּא אַרְבָּעִים וּשְׁתַּיִם מַסָּעוֹת, צֵא מֵהֶם י\\\"ד שֶׁכֻּלָּם הָיוּ בְּשָׁנָה רִאשׁוֹנָה קֹדֶם גְּזֵרָה, מִשֶּׁנָּסְעוּ מֵרַעְמְסֵס עַד שֶׁבָּאוּ לְרִתְמָה שֶׁמִּשָּׁם נִשְׁתַּלְּחוּ מְרַגְּלִים, שֶׁנֶּאֱמַר \\\"וְאַחַר נָסְעוּ הָעָם מֵחֲצֵרוֹת\\\" וְגוֹ' (במדבר י\\\"ב), \\\"שְׁלַח לְךָ אֲנָשִׁים\\\" וְגוֹ' (שם י\\\"ג), וְכָאן (פסוק י\\\"ח) הוּא אוֹמֵר \\\"וַיִּסְעוּ מֵחֲצֵרֹת וַיַּחֲנוּ בְּרִתְמָה\\\", לָמַדְתָּ שֶׁהִיא בְמִדְבַּר פָּארָן; וְעוֹד הוֹצֵא מִשָּׁם ח' מַסָּעוֹת שֶׁהָיוּ לְאַחַר מִיתַת אַהֲרֹן — מֵהֹר הָהָר עַד עַרְבוֹת מוֹאָב — בִּשְׁנַת הָאַרְבָּעִים, נִמְצָא שֶׁכָּל שְׁמוֹנֶה וּשְׁלֹשִׁים שָׁנָה לֹא נָסְעוּ אֶלָּא עֶשְׂרִים מַסָּעוֹת, זֶה מִיסוֹדוֹ שֶׁל רַבִּי מֹשֶׁה. וְרַבִּי תַנְחוּמָא דָרַשׁ בּוֹ דְּרָשָׁה אַחֶרֶת: מָשָׁל לְמֶלֶךְ שֶׁהָיָה בְנוֹ חוֹלֶה וְהוֹלִיכוֹ לְמָקוֹם רָחוֹק לְרַפֹּאתוֹ, כֵּיוָן שֶׁהָיוּ חוֹזְרִין הִתְחִיל אָבִיו מוֹנֶה כָל הַמַּסָּעוֹת, אָמַר לוֹ, כָּאן יָשַׁנְנוּ, כָּאן הוֹקַרְנוּ, כָּאן חָשַׁשְׁתָּ אֶת רֹאשְׁךָ וְכוּ':\",1,0],[2,133,33,4,\"ומצרים מקברים. טְרוּדִים בְּאֶבְלָם:\",1,0],[2,133,33,18,\"ויחנו ברתמה. עַל שֵׁם לָשׁוֹן הָרָע שֶׁל מְרַגְּלִים, שֶׁנֶּאֱמַר \\\"מַה יִּתֵּן לְךָ וּמַה יֹּסִיף לָךְ לָשׁוֹן רְמִיָּה חִצֵּי גִבּוֹר שְׁנוּנִים עִם גַּחֲלֵי רְתָמִים\\\" (תהלים ק\\\"כ):\",1,0],[2,133,33,38,\"על פי ה'. מְלַמֵּד שֶׁמֵּת בִּנְשִׁיקָה:\",1,0],[2,133,33,40,\"וישמע הכנעני. לְלַמֶּדְךָ שֶׁמִּיתַת אַהֲרֹן הִיא הַשְּׁמוּעָה, שֶׁנִּסְתַּלְּקוּ עַנְנֵי כָבוֹד וּכְסָבוּר שֶׁנִּתְּנָה רְשׁוּת לְהִלָּחֵם בְּיִשְׂרָאֵל, לְפִיכָךְ חָזַר וּכְתָבָהּ (ראש השנה ג'):\",1,0],[2,133,33,44,\"בעיי העברים. לְשׁוֹן חֳרָבוֹת וְגַלִּים כְּמוֹ \\\"לְעִי הַשָּׂדֶה\\\" (מיכה א'), \\\"שָׂמוּ אֶת יְרוּשָׁלַיִם לְעִיִּים\\\" (תהלים ע\\\"ט):\",1,0],[2,133,33,49,\"מבית הישמת עד אבל השטים. כָּאן לִמֶּדְךָ שִׁעוּר מַחֲנֵה יִשְׂרָאֵל י\\\"ב מִיל, דִּאָמַר רַבָּה בַּר בַּר חָנָה לְדִידִי חָזֵי לִי הַהוּא אַתְרָא וְכוּ' (עירובין נ\\\"ה):\",1,0],[2,133,33,49,\"אבל השטים. מִישׁוֹר שֶׁל שִׁטִּים אָבֵל שְׁמוֹ:\",2,0],[2,133,33,51,\"כי אתם עברים את הירדן וגו' והורשתם וגו'. וַהֲלֹא כַמָּה פְעָמִים הֻזְהֲרוּ עַל כָּךְ? אֶלָּא כָּךְ אָמַר לָהֶם מֹשֶׁה כְּשֶׁאַתֶּם עוֹבְרִים בַּיַּרְדֵּן בַּיַּבָּשָׁה עַל מְנָת כֵּן תַּעַבְרוּ, וְאִם לָאו — מַיִם בָּאִין וְשׁוֹטְפִין אֶתְכֶם, וְכֵן מָצִינוּ שֶׁאָמַר לָהֶם יְהוֹשֻׁעַ (יהושע ד') בְּעוֹדָם בַּיַּרְדֵּן (סוטה ל\\\"ד):\",1,0],[2,133,33,52,\"והורשתם. וְגֵרַשְׁתֶּם:\",1,0],[2,133,33,52,\"משכיתם. כְּתַרְגּוּמוֹ — \\\"בֵּית סִגְדַּתְהוֹן\\\", עַל שֵׁם שֶׁהָיוּ מְסַכְּכִין אֶת הַקַּרְקַע בְּרִצְפַּת אֲבָנִים שֶׁל שַׁיִשׁ לְהִשְׁתַּחֲווֹת עֲלֵיהֶם בְּפִשּׁוּט יָדַיִם וְרַגְלַיִם, כְּדִכְתִיב \\\"וְאֶבֶן מַשְׂכִּית לֹא תִתְּנוּ בְּאַרְצְכֶם לְהִשְׁתַּחֲוֹת עָלֶיהָ\\\" (ויקרא כ\\\"ו):\",2,0],[2,133,33,52,\"מסכתם. כְּתַרְגּוּמוֹ — \\\"מַתְּכַתְהוֹן\\\":\",3,0],[2,133,33,53,\"והורשתם את הארץ. וְהוֹרַשְׁתֶּם אוֹתָהּ מִיּוֹשְׁבֶיהָ, וְאָז וישבתם בה — תּוּכְלוּ לְהִתְקַיֵּם בָּהּ, וְאִם לָאו — לֹא תוּכְלוּ לְהִתְקַיֵּם בָּהּ:\",1,0],[2,133,33,54,\"אל אשר יצא לו שמה. מִקְרָא קָצָר הוּא זֶה: אֶל מָקום אשר יצא לו שמה הגורל לו יהיה:\",1,0],[2,133,33,54,\"למטות אבתיכם. לְפִי חֶשְׁבּוֹן יוֹצְאֵי מִצְרַיִם (בבא בתרא קי\\\"ז); דָּ\\\"אַ — בְּי\\\"ב גְּבוּלִין כְּמִנְיַן הַשְּׁבָטִים:\",2,0],[2,133,33,55,\"והיה אשר תותירו מהם. יִהְיוּ לָכֶם לְרָעָה:\",1,0],[2,133,33,55,\"לשכים בעיניכם. לִיתֵדוֹת הַמְנַקְּרוֹת עֵינֵיכֶם, תַּרְגּוּם שֶׁל יְתֵדוֹת \\\"שִׂיכַיָּא\\\":\",2,0],[2,133,33,55,\"ולצנינם. פּוֹתְרִין בּוֹ הַפּוֹתְרִים לְשׁוֹן מְסוּכַת קוֹצִים הַסּוֹכֶכֶת אֶתְכֶם, לִסְגֹּר וְלִכְלֹא אֶתְכֶם מֵאֵין יוֹצֵא וָבָא:\",3,0],[2,133,33,55,\"וצררו אתכם. כְּתַרְגּוּמוֹ:\",4,0],[2,133,34,2,\"זאת הארץ אשר תפל לכם וגו'. לְפִי שֶׁהַרְבֵּה מִצְוֹת נוֹהֲגוֹת בָּאָרֶץ וְאֵין נוֹהֲגוֹת בְּחוּצָה לָאָרֶץ, הֻצְרַךְ לִכְתֹּב מִצְרָנֵי גְבוּלֵי רוּחוֹתֶיהָ סָבִיב, לוֹמַר לְךָ מִן הַגְּבוּלִים הַלָּלוּ וְלִפְנִים הַמִּצְוֹת נוֹהֲגוֹת (עי' גיטין ח'):\",1,0],[2,133,34,2,\"תפל לכם. עַל שֵׁם שֶׁנִּתְחַלְּקָה בְגוֹרָל נִקְרֵאת חֲלֻקָּה לְשׁוֹן נְפִילָה; וּמִ\\\"אַ אוֹמֵר עַ\\\"יְ שֶׁהִפִּיל הַקָּבָּ\\\"ה שָׂרֵיהֶם שֶׁל שִׁבְעָה אֻמּוֹת מִן הַשָּׁמַיִם וּכְפָתָן לִפְנֵי מֹשֶׁה אָמַר לוֹ רְאֵה אֵין בָּהֶם עוֹד כֹּחַ (עי' תנחומא):\",2,0],[2,133,34,3,\"והיה לכם פאת נגב. רוּחַ דְּרוֹמִית אֲשֶׁר מִן הַמִּזְרָח לַמַּעֲרָב:\",1,0],[2,133,34,3,\"ממדבר צן. אֲשֶׁר אֵצֶל אֱדוֹם מַתְחִיל מִקְצוֹעַ דְרוֹמִית מִזְרָחִית שֶׁל אֶרֶץ תִּשְׁעַת הַמַּטּוֹת; כֵּיצַד? שָׁלוֹשׁ אֲרָצוֹת יוֹשְׁבוֹת בִּדְרוֹמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל זוֹ אֵצֶל זוֹ — קְצָת אֶרֶץ מִצְרַיִם וְאֶרֶץ אֱדוֹם כֻּלָּהּ וְאֶרֶץ מוֹאָב כֻּלָּהּ, אֶרֶץ מִצְרַיִם בְּמִקְצוֹעַ דְּרוֹמִית מַעֲרָבִית, שֶׁנֶּאֱמַר בְּפָרָשָׁה זוֹ מֵעַצְמוֹן נַחְלָה מִצְרָיִם וְהָיוּ תוֹצְאֹתָיו הַיָּמָּה, וְנַחַל מִצְרַיִם הָיָה מְהַלֵּךְ עַל פְּנֵי כָל אֶרֶץ מִצְרַיִם שֶׁנֶּאֱמַר (יהושע י\\\"ג) \\\"מִן הַשִּׁיחוֹר אֲשֶׁר עַל פְּנֵי מִצְרַיִם\\\", וּמַפְסִיק בֵּין אֶרֶץ מִצְרַיִם לְאֶרֶץ יִשְׂרָאֵל, וְאֶרֶץ אֱדוֹם אֶצְלָהּ לְצַד הַמִּזְרָח, וְאֶרֶץ מוֹאָב אֵצֶל אֶרֶץ אֱדוֹם בְּסוֹף הַדָּרוֹם לַמִּזְרָח. וּכְשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, אִם רָצָה הַמָּקוֹם לְקָרֵב אֶת כְּנִיסָתָם לָאָרֶץ, הָיָה מַעֲבִירָם אֶת הַנִּילוּס לְצַד צָפוֹן וּבָאִין לְאֶרֶץ יִשְׂרָאֵל, וְלֹא עָשָׂה כֵן, וְזֶהוּ שֶׁנֶּאֱמַר (שמות י\\\"ג) \\\"וְלֹא נָחָם אֱלֹהִים דֶּרֶךְ אֶרֶץ פְּלִשְׁתִּים\\\", שֶׁהֵם יוֹשְׁבִים עַל הַיָּם בְּמַעֲרָבָהּ שֶׁל אֶרֶץ כְּנַעַן — כָּעִנְיָן שֶׁנֶּאֱמַר בַּפְּלִשְׁתִּים (צפניה ב') \\\"יֹשְׁבֵי חֶבֶל הַיָּם גּוֹי כְּרֵתִים\\\" — וְלֹא נָחָם אוֹתוֹ הַדֶּרֶךְ, אֶלָּא הֱסִבָּן וְהוֹצִיאָם דֶּרֶךְ דְּרוֹמָהּ אֶל הַמִּדְבָּר, וְהוּא שֶׁקְּרָאוֹ יְחֶזְקֵאל (יחזקאל כ') \\\"מִדְבַּר הָעַמִּים\\\", לְפִי שֶׁהָיוּ כַמָּה אֻמּוֹת יוֹשְׁבִים בְּצִדּוֹ; וְהוֹלְכִין אֵצֶל דְּרוֹמָהּ מִן הַמַּעֲרָב כְּלַפֵּי מִזְרָח תָּמִיד עַד שֶׁבָּאוּ לִדְרוֹמָהּ שֶׁל אֶרֶץ אֱדוֹם, וּבִקְּשׁוּ מִמֶּלֶךְ אֱדוֹם שֶׁיַּנִּיחֵם לַעֲבֹר דֶּרֶךְ אַרְצוֹ וּלְהִכָּנֵס לָאָרֶץ דֶּרֶךְ רָחְבָּהּ וְלֹא רָצָה, וְהֻצְרְכוּ לִסְבֹּב אֶת כָּל דְּרוֹמָהּ שֶׁל אֱדוֹם עַד בּוֹאָם לִדְרוֹמָהּ שֶׁל אֶרֶץ מוֹאָב, שֶׁנֶּאֱמַר (שופטים י\\\"א) \\\"וְגַם אֶל מֶלֶךְ מוֹאָב שָׁלַח וְלֹא אָבָה\\\", וְהָלְכוּ כָּל דְּרוֹמָהּ שֶׁל מוֹאָב עַד סוֹפָהּ, וּמִשָּׁם הָפְכוּ פְנֵיהֶם לַצָּפוֹן עַד שֶׁסָּבְבוּ כָל מֶצֶר מִזְרָחִי שֶׁלָּהּ לְרָחְבָּהּ; וּכְשֶׁכִּלּוּ אֶת מִזְרָחָהּ, מָצְאוּ אֶת אֶרֶץ סִיחוֹן וְעוֹג שֶׁהָיוּ יוֹשְׁבִין בְּמִזְרָחָהּ שֶׁל אֶרֶץ כְּנַעַן וְהַיַּרְדֵּן מַפְסִיק בֵּינֵיהֶם, וְזֶהוּ שֶׁנֶּאֱמַר בְּיִפְתָּח (שם) \\\"וַיֵּלֶךְ בַּמִּדְבָּר וַיָּסָב אֶת אֶרֶץ אֱדוֹם וְאֶת אֶרֶץ מוֹאָב וַיָּבֹא מִמִּזְרַח שֶׁמֶשׁ לְאֶרֶץ מוֹאָב\\\", וְכָבְשׁוּ אֶת אֶרֶץ סִיחוֹן וְעוֹג שֶׁהָיְתָה בִּצְפוֹנָהּ שֶׁל אֶרֶץ מוֹאָב וְקָרְבוּ עַד הַיַּרְדֵּן, וְהוּא כְנֶגֶד מִקְצוֹעַ צָפוֹנָה מַעֲרָבָה שֶׁל אֶרֶץ מוֹאָב; נִמְצָא שֶׁאֶרֶץ כְּנַעַן שֶׁבְּעֵבֶר הַיַּרְדֵּן לַמַּעֲרָב, הָיָה מִקְצוֹעַ דְּרוֹמִית מִזְרָחִית שֶׁלָּהּ אֵצֶל אֱדוֹם:\",2,0],[2,133,34,4,\"ונסב לכם הגבול מנגב למעלה עקרבים. כָּל מָקוֹם שֶׁנֶּאֱמַר \\\"וְנָסַב\\\" אוֹ \\\"וְיָצָא\\\" מְלַמֵּד שֶׁלֹּא הָיָה הַמֶּצֶר שָׁוֶה אֶלָּא הוֹלֵךְ וְיוֹצֵא לַחוּץ; יוֹצֵא הַמֶּצֶר וְעוֹקֵם לְצַד צְפוֹנוֹ שֶׁל עוֹלָם, בַּאֲלַכְסוֹן לַמַּעֲרָב, וְעוֹבֵר הַמֶּצֶר בִּדְרוֹמָהּ שֶׁל מַעֲלֵה עַקְרַבִּים, נִמְצָא מַעֲלֵה עַקְרַבִּים לִפְנִים מִן הַמֶּצֶר:\",1,0],[2,133,34,4,\"ועבר צנה. אֶל צִן, כְּמוֹ מִצְרַיְמָה:\",2,0],[2,133,34,4,\"והיו תוצאתיו. קְצוֹתָיו, בִּדְרוֹמָהּ שֶׁל קָדֵשׁ בַּרְנֵעַ:\",3,0],[2,133,34,4,\"ויצא חצר אדר. מִתְפַּשֵּׁט הַמֶּצֶר וּמַרְחִיב לְצַד צָפוֹן שֶׁל עוֹלָם וְנִמְשָׁךְ עוֹד בַּאֲלַכְסוֹן לַמַּעֲרָב, וּבָא לוֹ לַחֲצַר אַדָּר, וּמִשָּׁם לְעַצְמוֹן, וּמִשָּׁם לְנַחַל מִצְרַיִם; וּלְשׁוֹן וְנָסַב הָאָמוּר כָּאן, לְפִי שֶׁכָּתַב וְיָצָא חֲצַר אַדָּר, שֶׁהִתְחִיל לְהַרְחִיב מִשֶּׁעָבַר אֶת קָדֵשׁ בַּרְנֵעַ, וְרֹחַב אוֹתָהּ רְצוּעָה שֶׁבָּלְטָה לְצַד צָפוֹן הָיְתָה מִקָּדֵשׁ בַּרְנֵעַ עַד עַצְמוֹן, וּמִשָּׁם וָהָלְאָה נִתְקַצֵּר הַמֶּצֶר וְנָסַב לְצַד הַדָּרוֹם וּבָא לוֹ לְנַחַל מִצְרַיִם, וּמִשָּׁם לְצַד הַמַּעֲרָב אֶל הַיָּם הַגָּדוֹל שֶׁהוּא מֶצֶר מַעֲרָבָהּ שֶׁל כָּל אֶרֶץ יִשְׂרָאֵל, נִמְצָא שֶׁנַּחַל מִצְרַיִם בְּמִקְצוֹעַ מַעֲרָבִית דְּרוֹמִית:\",4,0],[2,133,34,5,\"והיו תוצאתיו הימה. אֶל מֶצֶר הַמַּעֲרָב שֶׁאֵין עוֹד גְּבוּל נֶגֶב מַאֲרִיךְ לְצַד הַמַּעֲרָב מִשָּׁם וָהָלְאָה:\",1,0],[2,133,34,6,\"וגבול ים. וּמֶצֶר מַעֲרָבִי מַהוּ?\",1,0],[2,133,34,6,\"והיה לכם הים הגדול. לְמֶצֶר:\",2,0],[2,133,34,6,\"וגבול. הַנִּסִּין שֶׁבְּתוֹךְ הַיָּם אַף הֵם מִן הַגְּבוּל, וְהֵם אִיִּים שֶקּוֹרִין איזל\\\"ס:\",3,0],[2,133,34,7,\"גבול צפון. מֶצֶר צָפוֹן:\",1,0],[2,133,34,7,\"מן הים הגדל תתאו לכם הר ההר. שֶׁהוּא בְמִקְצוֹעַ צְפוֹנִית מַעֲרָבִית וְרֹאשׁוֹ מַשְׁפִּיעַ וְנִכְנָס לְתוֹךְ הַיָּם, וְיֵשׁ מֵרֹחַב הַיָּם לִפְנִים הֵימֶנּוּ וְחוּצָה הֵימֶנּוּ:\",2,0],[2,133,34,7,\"תתאו. תְּשַׁפְּעוּ לָכֶם, לִנְטוֹת מִמַּעֲרָב לַצָּפוֹן, אֶל הֹר הָהָר:\",3,0],[2,133,34,7,\"תתאו. לְשׁוֹן סִבָּה, כְּמוֹ \\\"אֶל תָּא הָרָצִים\\\" (מלכים א י\\\"ד), \\\"וְתָאֵי הַשַּׁעַר\\\" (יחזקאל מ') — הַיָּצִיעַ, שֶׁקּוֹרִין אפנדי\\\"ץ, שֶׁהוּא מוּסָב וּמְשֻׁפָּע:\",4,0],[2,133,34,8,\"מהר ההר. תָּסֹבּוּ וְתֵלְכוּ אֶל מֶצֶר הַצָּפוֹן לְצַד הַמִּזְרָח, וְתִפְגְּעוּ בִּלְבֹא חֲמָת, זוֹ אַנְטוֹכְיָא:\",1,0],[2,133,34,8,\"תוצאת הגבל. סוֹפֵי הַגְּבוּל; כָּל מָקוֹם שֶׁנֶּאֱמַר תּוֹצְאוֹת הַגְּבוּל, אוֹ הַמֶּצֶר כָּלֶה שָׁם לְגַמְרֵי וְאֵינוֹ עוֹבֵר לְהַלָּן כְּלָל, אוֹ מִשָּׁם מִתְפַּשֵּׁט וּמַרְחִיב וְיוֹצֵא לַאֲחוֹרָיו לְהִמָּשֵׁךְ לְהַלָּן בַּאֲלַכְסוֹן יוֹתֵר מִן הָרֹחַב הָרִאשׁוֹן, וּלְעִנְיַן רֹחַב הַמִּדָּה הָרִאשׁוֹן קְרָאוֹ תּוֹצָאוֹת, שֶׁשָּׁם כָּלְתָה אוֹתָהּ מִדָּה:\",2,0],[2,133,34,9,\"והיו תוצאתיו חצר עינן. הוּא הָיָה סוֹף הַמֶּצֶר הַצְּפוֹנִי, וְנִמְצֵאת חֲצַר עֵינָן בְּמִקְצוֹעַ צְפוֹנִית מִזְרָחִית, וּמִשָּׁם והתאויתם לכם אֶל מֶצֶר הַמִּזְרָחִי:\",1,0],[2,133,34,10,\"והתאויתם. לְשׁוֹן הֲסִבָּה וּנְטִיָּה, כְּמוֹ \\\"תְּתָאוּ\\\":\",1,0],[2,133,34,10,\"שפמה. בַּמֶּצֶר הַמִּזְרָחִי, וּמִשָּׁם הָרִבְלָה:\",2,0],[2,133,34,11,\"מקדם לעין. שֵׁם מָקוֹם, וְהַמֶּצֶר הוֹלֵךְ בְּמִזְרָחוֹ, נִמְצָא הָעַיִן לִפְנִים מִן הַמֶּצֶר וּמֵאֶרֶץ יִשְׂרָאֵל הוּא:\",1,0],[2,133,34,11,\"וירד הגבול. כָּל שֶׁהַגְּבוּל הוֹלֵךְ מִצָּפוֹן לַדָּרוֹם הוּא יוֹרֵד וְהוֹלֵךְ:\",2,0],[2,133,34,11,\"ומחה על כתף ים כנרת קדמה. שֶׁיְּהֵא יָם כִּנֶּרֶת תּוֹךְ לַגְּבוּל, בַּמַּעֲרָב, וְהַגְּבוּל בְּמִזְרַח יָם כִּנֶּרֶת, וּמִשָּׁם יָרַד אֶל הַיַּרְדֵּן, וְהַיַּרְדֵּן מוֹשֵׁךְ וּבָא מִן הַצָּפוֹן לַדָּרוֹם בַּאֲלַכְסוֹן, נוֹטֶה לְצַד מִזְרָח מִתְקָרֵב לְצַד אֶרֶץ כְּנַעַן כְּנֶגֶד יָם כִּנֶּרֶת, וּמוֹשֵׁךְ לְצַד מִזְרָחָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל (כְּנֶגֶד יָם כִּנֶּרֶת) עַד שֶׁנּוֹפֵל בְּיָם הַמֶּלַח, וּמִשָּׁם כָּלֶה הַגְּבוּל בְּתוֹצְאוֹתָיו אֶל יָם הַמֶּלַח, שֶׁמִּמֶּנּוּ הַתְחָלַת מֶצֶר מִקְצוֹעַ דְּרוֹמִית מִזְרָחִית, הֲרֵי סוֹבֶבֶת אוֹתָהּ לְאַרְבַּע רוּחוֹתֶיהָ:\",3,0],[2,133,34,15,\"קדמה מזרחה. אֶל פְּנֵי הָעוֹלָם, שֶׁהֵם בַּמִּזְרָח, שֶׁרוּחַ מִזְרָחִית קְרוּיָה פָנִים וּמַעֲרָבִית קְרוּיָה אָחוֹר, לְפִיכָךְ דָּרוֹם לַיָּמִין וְצָפוֹן לַשְּׂמֹאל:\",1,0],[2,133,34,17,\"אשר ינחלו לכם. בִּשְׁבִילְכֶם; כָּל נָשִׂיא וְנָשִׂיא אַפּוֹטְרוֹפּוֹס לְשִׁבְטוֹ וּמְחַלֵּק נַחֲלַת הַשֵּׁבֶט לַמִּשְׁפָּחוֹת וְלַגְּבָרִים, וּבוֹרֵר לְכָל אֶחָד וְאֶחָד חֵלֶק הָגוּן, וּמַה שֶּׁהֵם עוֹשִׂים יִהְיֶה עָשׂוּי כְּאִלּוּ עֲשָׂאוּם שְׁלוּחִים; וְלֹא יִתָּכֵן לְפָרֵשׁ לכם זֶה כְּכָל לָכֶם שֶׁבַּמִּקְרָא, שֶׁאִם כֵּן הָיָה לוֹ לִכְתֹּב יַנְחִילוּ לָכֶם, יִנְחֲלוּ מַשְׁמַע שֶׁהֵם נוֹחֲלִים לָכֶם — בִּשְׁבִילְכֶם וּבִמְקוֹמְכֶם, כְּמוֹ \\\"ה' יִלָּחֵם לָכֶם\\\" (שמות י\\\"ד):\",1,0],[2,133,34,18,\"לנחל את הארץ. שֶׁיְּהֵא נוֹחֵל וְחוֹלֵק אוֹתָהּ בִּמְקוֹמְכֶם:\",1,0],[2,133,34,29,\"לנחל את בני ישראל. שֶׁהֵם יַנְחִילוּ אוֹתָהּ לָכֶם לְמַחְלְקוֹתֶיהָ:\",1,0],[2,133,35,2,\"ומגרש. רֶוַח מָקוֹם חָלָק חוּץ לָעִיר סָבִיב, לִהְיוֹת לְנוֹי לָעִיר, וְאֵין רַשָּׁאִין לִבְנוֹת שָׁם בַּיִת וְלֹא לִנְטֹעַ כֶּרֶם וְלֹא לִזְרֹעַ זְרִיעָה:\",1,0],[2,133,35,3,\"ולכל חיתם. לְכָל צָרְכֵּיהֶם:\",1,0],[2,133,35,4,\"אלף אמה סביב. וְאַחֲרָיו הוּא אוֹמֵר אַלְפַּיִם אַמָּה, הָא כֵיצַד? אַלְפַּיִם הוּא נוֹתֵן לָהֶם סָבִיב, וּמֵהֶם אֶלֶף הַפְּנִימִיִּים לְמִגְרָשׁ וְהַחִיצוֹנִים לְשָׂדוֹת וּכְרָמִים:\",1,0],[2,133,35,11,\"והקריתם. אֵין הַקְרָיָה אֶלָּא לְשׁוֹן הַזְמָנָה, וְכֵן הוּא אוֹמֵר \\\"כִּי הִקְרָה ה' אֱלֹהֶיךָ לְפָנָי\\\" (בראשית כ\\\"ז):\",1,0],[2,133,35,12,\"מגאל. מִפְּנֵי גּוֹאֵל הַדָּם, שֶׁהוּא קָרוֹב לַנִּרְצָח:\",1,0],[2,133,35,13,\"שש ערי מקלט. מַגִּיד שֶׁאַעַ\\\"פִּ שֶׁהִבְדִּיל מֹשֶׁה בְּחַיָּיו שָׁלוֹשׁ עָרִים בְּעֵבֶר הַיַּרְדֵּן, לֹא הָיוּ קוֹלְטוֹת עַד שֶׁנִּבְחֲרוּ שָׁלֹשׁ שֶׁנָּתַן יְהוֹשֻׁעַ בְּאֶרֶץ כְּנַעַן (ספרי; מכות ט'):\",1,0],[2,133,35,14,\"את שלש הערים וגו'. אַעַ\\\"פִּ שֶׁבְּאֶרֶץ כְּנַעַן תִּשְׁעָה שְׁבָטִים וְכָאן אֵינָן אֶלָּא שְׁנַיִם וָחֵצִי, הִשְׁוָה מִנְיַן עָרֵי הַמִּקְלָט שֶׁלָּהֶם, מִשּׁוּם דִּבְגִלְעָד נְפִישֵׁי רוֹצְחִים, דִּכְתִיב (הושע ו') \\\"גִּלְעָד קִרְיַת פֹּעֲלֵי אָוֶן עֲקֻבָּה מִדָּם\\\" (שם):\",1,0],[2,133,35,16,\"ואם בכלי ברזל הכהו. אֵין זֶה מְדַבֵּר בְּהוֹרֵג בְּשׁוֹגֵג הַסָּמוּךְ לוֹ, אֶלָּא בְּהוֹרֵג בְּמֵזִיד, וּבָא לְלַמֵּד שֶׁהַהוֹרֵג בְּכָל דָּבָר צָרִיךְ שֶׁיְּהֵא בוֹ שִׁעוּר כְּדֵי לְהָמִית, שֶׁנֶּאֱמַר בְּכֻלָּם \\\"אֲשֶׁר יָמוּת בּוֹ\\\", דִּמְתַּרְגְּמִינַן \\\"דְּהִיא כְמִסַּת דִּימוּת בֵּיהּ\\\", חוּץ מִן הַבַּרְזֶל, שֶׁגָּלוּי וְיָדוּעַ לִפְנֵי הַקָּבָּ\\\"ה שֶׁהַבַּרְזֶל מֵמִית בְּכָל שֶׁהוּא, אֲפִלּוּ מַחַט, לְפִיכָךְ לֹא נָתְנָה בוֹ תּוֹרָה שִׁעוּר לִכְתֹּב בּוֹ אֲשֶׁר יָמוּת בּוֹ; וְאִם תֹּאמַר בְּהוֹרֵג בְּשׁוֹגֵג הַכָּתוּב מְדַבֵּר, הֲרֵי הוּא אוֹמֵר לְמַטָּה אוֹ בכל אבן אשר ימות בה בלא ראות וְגוֹ', לִמֵּד עַל הָאֲמוּרִים לְמַעְלָה שֶׁבְּהוֹרֵג בְּמֵזִיד הַכָּתוּב מְדַבֵּר:\",1,0],[2,133,35,17,\"באבן יד. שֶׁיֵּשׁ בָּהּ מְלֹא יָד (ספרי):\",1,0],[2,133,35,17,\"אשר ימות בה. שֶׁיֵּשׁ בָּהּ שִׁעוּר לְהָמִית, כְּתַרְגּוּמוֹ; לְפִי שֶׁנֶּאֱמַר \\\"וְהִכָּה אִישׁ אֶת רֵעֵהוּ בְּאֶבֶן\\\" (שמות כ\\\"א), וְלֹא נָתַן בָּהּ שִׁעוּר, יָכוֹל כָּל שֶׁהוּא, לְכָךְ נֶאֱמַר אשר ימות בה:\",2,0],[2,133,35,18,\"או בכלי עץ יד. לְפִי שֶׁנֶּאֱמַר (שם) \\\"וְכִי יַכֶּה אִישׁ אֶת עַבְדּוֹ אוֹ אֶת אֲמָתוֹ בַּשֵּׁבֶט\\\", יָכוֹל כָּל שֶׁהוּא, לְכָךְ נֶאֱמַר \\\"בְּעֵץ אֲשֶׁר יָמוּת בּוֹ\\\" — שֶׁיְּהֵא בּוֹ כְּדֵי לְהָמִית (ספרי):\",1,0],[2,133,35,19,\"בפגעו בו. אֲפִלּוּ בְּתוֹךְ עָרֵי מִקְלָט:\",1,0],[2,133,35,20,\"בצדיה. כְּתַרְגּוּמוֹ, \\\"בְּכָמְנָא\\\" — בְּמַאֲרָב:\",1,0],[2,133,35,22,\"בפתע. בְּאֹנֶס, וְתַרְגּוּמוֹ \\\"בִּתְכֵיף\\\", שֶׁהָיָה סָמוּךְ לוֹ וְלֹא הָיָה לוֹ שָׁהוּת לְהִזָּהֵר עָלָיו:\",1,0],[2,133,35,23,\"או בכל אבן אשר ימות בה. הִכָּהוּ:\",1,0],[2,133,35,23,\"בלא ראות. שֶׁלֹּא רָאָהוּ:\",2,0],[2,133,35,23,\"ויפל עליו. מִכָּאן אָמְרוּ הַהוֹרֵג דֶּרֶךְ יְרִידָה גּוֹלֶה, דֶּרֶךְ עֲלִיָּה אֵינוֹ גוֹלֶה (מכות ל'):\",3,0],[2,133,35,25,\"עד מות הכהן הגדול. שֶׁהוּא בָא לְהַשְׁרוֹת שְׁכִינָה בְיִשְׂרָאֵל וּלְהַאֲרִיךְ יְמֵיהֶם, וְהָרוֹצֵחַ בָּא לְסַלֵּק אֶת הַשְּׁכִינָה מִיִּשְׂרָאֵל וּמְקַצֵּר אֶת יְמֵי הַחַיִּים, אֵינוֹ כְדַאי שֶׁיְּהֵא לִפְנֵי כֹּהֵן גָּדוֹל (ספרי); דָּבָר אַחֵר — לְפִי שֶׁהָיָה לוֹ לְכֹהֵן גָּדוֹל לְהִתְפַּלֵּל שֶׁלֹּא תֶאֱרַע תַּקָּלָה זוֹ לְיִשְׂרָאֵל בְּחַיָּיו (עי' מכות י\\\"א):\",1,0],[2,133,35,25,\"אשר משח אותו בשמן הקדש. לְפִי פְשׁוּטוֹ מִן הַמִּקְרָאוֹת הַקְּצָרִים הוּא, שֶׁלֹּא פֵּרֵשׁ מִי מְשָׁחוֹ, אֶלָּא כְּמוֹ אֲשֶׁר מְשָׁחוֹ הַמּוֹשֵׁחַ אוֹתוֹ בְּשֶׁמֶן הַקֹּדֶשׁ; וְרַבּוֹתֵינוּ דְרָשׁוּהוּ בְמַסֶּכֶת מַכּוֹת (שם) לִרְאָיַת דָּבָר, לְלַמֵּד שֶׁאִם עַד שֶׁלֹּא נִגְמַר דִּינוֹ מֵת הַכֹּהֵן גָּדוֹל וּמִנּוּ אַחֵר תַּחְתָּיו, וּלְאַחַר מִכָּאן נִגְמַר דִּינוֹ, חוֹזֵר בְּמִיתָתוֹ שֶׁל שֵׁנִי, שֶׁנֶּאֱמַר אשר משח אתו, וְכִי הוּא מוֹשְׁחוֹ לַכֹּהֵן אוֹ הַכֹּהֵן מָשַׁח אוֹתוֹ? אֶלָּא לְהָבִיא אֶת הַנִּמְשָׁח בְּיָמָיו שֶׁמַּחֲזִירוֹ בְּמִיתָתוֹ:\",2,0],[2,133,35,27,\"אין לו דם. הֲרֵי הוּא כְּהוֹרֵג אֶת הַמֵּת, שֶׁאֵין לוֹ דָּם:\",1,0],[2,133,35,29,\"בכל מושבתיכם. לִמֵּד שֶׁתְּהֵא סַנְהֶדְרִין קְטַנָּה נוֹהֶגֶת בְּחוּצָה לָאָרֶץ כָּל זְמַן שֶׁנּוֹהֶגֶת בְּאֶרֶץ יִשְׂרָאֵל (מכות ז'):\",1,0],[2,133,35,30,\"כל מכה נפש וגו'. הַבָּא לְהָרְגוֹ עַל שֶׁהִכָּה אֶת הַנֶּפֶשׁ (עי' ספרי):\",1,0],[2,133,35,30,\"לפי עדים ירצח. שֶׁיָּעִידוּ שֶׁבְּמֵזִיד וּבְהַתְרָאָה הֲרָגוֹ:\",2,0],[2,133,35,31,\"ולא תקחו כפר. לֹא יִפָּטֵר בְּמָמוֹן (כתובות ל\\\"ז):\",1,0],[2,133,35,32,\"ולא תקחו כפר לנוס אל עיר מקלטו. לְמִי שֶׁנָּס אֶל עִיר מִקְלָט, שֶׁהָרַג בְּשׁוֹגֵג, אֵינוֹ נִפְטָר מִגָּלוּת בְּמָמוֹן, לִתֵּן כֹּפֶר לשוב לשבת בארץ טֶרֶם יָמוּת הַכֹּהֵן (שם):\",1,0],[2,133,35,32,\"לנוס. כְּמוֹ לַנָּס, כְּמוֹ \\\"שׁוּבֵי מִלְחָמָה\\\" (מיכה ב') — שֶׁשָּׁבוּ מִן הַמִּלְחָמָה, וְכֵן \\\"נוּגֵי מִמּוֹעֵד\\\" (צפניה ג'), וְכֵן \\\"כִּי מֻלִים הָיוּ\\\" (יהושע ה'); כַּאֲשֶׁר תֹּאמַר שׁוּב עַל מִי שֶׁשָּׁב כְּבָר, וּמוּל עַל שֶׁמָּל כְּבָר, כֵּן תֹּאמַר לָנוּס עַל מִי שֶׁנָּס כְּבָר, וְקוֹרֵהוּ נוּס, כְּלוֹמַר מֻבְרָח. וְאִם תֹּאמַר לָנוּס — לִבְרֹחַ, וּתְפָרְשֵׁהוּ לֹא תִקְחוּ כֹפֶר לְמִי שֶׁיֵּשׁ לוֹ לִבְרֹחַ לְפָטְרוֹ מִן הַגָּלוּת (עי' ספרי), לֹא יָדַעְתִּי הֵיאַךְ יֹאמַר לָשׁוּב לָשֶׁבֶת בָּאָרֶץ, הֲרֵי עֲדַיִן לֹא נָס, וּמֵהֵיכָן יָשׁוּב?:\",2,0],[2,133,35,33,\"ולא תחניפו. לֹא תַרְשִׁיעוּ, כְּתַרְגּוּמוֹ — \\\"וְלָא תְחַיְבוּן\\\":\",1,0],[2,133,35,34,\"אשר אני שכן בתוכה. שֶׁלֹּא תַשְׁכִּינוּ אוֹתִי בְטֻמְאָתָהּ:\",1,0],[2,133,35,34,\"כי אני ה' שכן בתוך בני ישראל. אַף בִּזְמַן שֶׁהֵם טְמֵאִים שְׁכִינָה בֵינֵיהֶם (ספרי):\",2,0],[2,133,36,3,\"ונוסף על נחלת המטה. שֶׁהֲרֵי בְנָהּ יוֹרְשָׁהּ, וְהַבֵּן מִתְיַחֵס עַל שֵׁבֶט אָבִיו:\",1,0],[2,133,36,4,\"ואם יהיה היבל. מִכָּאן הָיָה רַ' יְהוּדָה אוֹמֵר עָתִיד הַיּוֹבֵל שֶׁיִּפְסֹק (ספרא ויקרא ב'):\",1,0],[2,133,36,4,\"ואם יהיה היובל. כְּלוֹמַר, אֵין זוֹ מְכִירָה שֶׁחוֹזֶרֶת בַּיּוֹבֵל, שֶׁהַיְרֻשָּׁה אֵינָהּ חוֹזֶרֶת, וַאֲפִלּוּ אִם יִהְיֶה הַיּוֹבֵל לֹא תַחֲזֹר הַנַּחֲלָה לְשִׁבְטוֹ, וְנִמְצָא שֶׁנּוֹסְפָה על נחלת המטה אשר תהיינה להם:\",2,0],[2,133,36,8,\"וכל בת ירשת נחלה. שֶׁלֹּא הָיָה בֵן לְאָבִיהָ:\",1,0],[2,133,36,11,\"מחלה תרצה וגו'. כָּאן מְנָאָן לְפִי גְדֻלָּתָן זוֹ מִזּוֹ בַּשָּׁנִים, וְנִשְּׂאוּ כְּסֵדֶר תּוֹלְדוֹתָן, וּבְכָל הַמִּקְרָא מְנָאָן לְפִי חָכְמָתָן, וּמַגִּיד שֶׁשְּׁקוּלוֹת זוֹ כְּזוֹ (עי' בבא בתרא ק\\\"כ):\",1,0],[2,134,1,1,\"חֲזוֹן עֹבַדְיָה. מַאי שְׁנָא עֹבַדְיָה לֶאֱדוֹם וְלֹא נִיבָּא נְבוּאָה אַחֶרֶת? אָמְרוּ חֲכָמִים: עֹבַדְיָה גֵּר אֲדוֹמִי הָיָה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מֵהֶם וּבָהֶם אָבִיא עֲלֵיהֶם. יָבֹא עֹבַדְיָה שֶׁדָּר בֵּין שְׁנֵי רְשָׁעִים, אַחְאָב וְאִיזֶבֶל, וְלֹא לָמַד מִמַּעֲשֵׂיהֶם, וְיִפְרַע מֵעֵשָׂו הָרָשָׁע שֶׁדָּר בֵּין שְׁנֵי צַדִּיקִים, יִצְחָק וְרִבְקָה, וְלֹא לָמַד מִמַּעֲשֵׂיהֶם:\",1,0],[2,134,1,2,\"הִנֵּה קָטֹן נְתַתִּיךָ. כְּלַפֵּי שֶׁקְּרָאוֹ אָבִיו בְּנוֹ הַגָּדוֹל וְאִמּוֹ בְּנָהּ הַגָּדוֹל, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: לְפָנַי קָטֹן הוּא. רַבּוֹתֵינוּ דָּרְשׁוּ: קָטֹן - שֶׁלֹּא הָיָה לָהֶם לֹא כְּתָב וְלֹא לָשׁוֹן:\",1,0],[2,134,1,2,\"בָּזוּי. שֶׁלֹּא הָיוּ מַעֲמִידִין מֶלֶךְ בֶּן מֶלֶךְ:\",2,0],[2,134,1,3,\"שֹׁכְנִי בְחַגְוֵי סֶלַע. סוֹמֵךְ עַל מִשְׁעֶנֶת אֲבוֹתָיו אַבְרָהָם וְיִצְחָק, וְהֵם לֹא יוֹעִילוּ לוֹ. חַגְוֵי כְּמוֹ ״וְהָיְתָה אַדְמַת יְהוּדָה לְמִצְרַיִם לְחָגָּא״ (ישעיהו יט:יז), ברייטיינ״א בְּלַעַ״ז. וְאַל תִּתְמַהּ עַל וָי״ו שֶׁל חַגְוֵי שֶׁהִיא כְּוָי״ו שֶׁל קְצָוֵי (תהלים סה:ו) וּכְוָי״ו שֶׁל כִּמְטַחֲוֵי (בראשית כא:טז), שֶׁאֵין יְסוֹד בַּתֵּיבָה אֶלָּא טֵי״ת וְחֵי״ת:\",1,0],[2,134,1,5,\"בָּאוּ לְךָ. עָלֶיךָ:\",1,0],[2,134,1,5,\"אֵיךְ נִדְמֵיתָה. לָמָּה נִרְדַּמְתָּה דוּמָם עַד שֶׁגָּנְבוּ כָּל רְצוֹנָם:\",2,0],[2,134,1,5,\"הֲלֹא בּוֹצְרִים יַשְׁאִירוּ עוֹלֵלוֹת. וְאֵלֶּה לֹא יַשְׁאִירוּ לְךָ כְּלוּם, כִּי יַחְפְּשׂוּךָ וִיגַלּוּ וְיִדְרְשׁוּ מַצְפּוּנֶיךָ:\",3,0],[2,134,1,6,\"נִבְעוּ. תַּרְגּוּם יוֹנָתָן: אִיתְגַּלְיָין, וּלְשׁוֹן אֲרָמִית נִבְעוּ נִתְבַּקְּשׁוּ, וְכֵן ״אִם תִּבְעָיוּן בְּעָיוּ״ (ישעיהו כא:יב):\",1,0],[2,134,1,7,\"עַד הַגְּבוּל שִׁלְּחוּךָ. אוֹתָם שֶׁהִבְטִיחוּךָ לְעֶזְרָה בָּאוּ עִמְּךָ וְלִוּוּךָ עַד גְּבוּל אַרְצְךָ עַד הַסְּפָר, שֶׁשָּׁם בָּאוּ עָלֶיךָ לַמִּלְחָמָה, וּבְזֹאת הִשִּׂיאוּךָ וְהִצְלִיחוּ:\",1,0],[2,134,1,7,\"יָכְלוּ לְךָ. לְפַתּוֹתְךָ לָצֵאת וְשָׁבוּ מֵאַחֲרֶיךָ:\",2,0],[2,134,1,7,\"לַחְמְךָ יָשִׂימוּ מָזוֹר תַּחְתֶּיךָ. אַף מַאֲכָלְךָ שָׂם לְךָ אָחִיךָ יַעֲקֹב לְמָזוֹר, שֶׁנָּתַן לְךָ לֶחֶם וּנְזִיד עֲדָשִׁים וְעַל יָדוֹ בָּזִיתָ הַבְּכוֹרָה:\",3,0],[2,134,1,7,\"מָזוֹר. חֳלִי:\",4,0],[2,134,1,9,\"וְחַתּוּ גִבּוֹרֶיךָ תֵּימָן. יֵחַתּוּ וְיִפְחֲדוּ לָנוּס אֶל אֶרֶץ יִשְׁמָעֵאל. וְתַרְגּוּם יוֹנָתָן: וְיִתְבָּרוּן גִּבָּרָךְ יָתְבֵי אַרְעָא דְרוֹמָא:\",1,0],[2,134,1,9,\"לְמַעַן יִכָּרֶת. כָּל אִישׁ גִּבּוֹר:\",2,0],[2,134,1,9,\"מֵהַר עֵשָׂו מִקָּטֶל. מֵרוֹב הֶרֶג שֶׁיָּבֹא עֲלֵיכֶם:\",3,0],[2,134,1,10,\"מֵחֲמַס אָחִיךָ יַעֲקֹב. בִּשְׁבִיל חָמָס שֶׁעָשִׂיתָ לְיַעֲקֹב:\",1,0],[2,134,1,11,\"בְּיוֹם עֲמָדְךָ מִנֶּגֶד. שֶׁלֹּא בָאתָ לַעֲזוֹר לוֹ:\",1,0],[2,134,1,11,\"גַּם אַתָּה כְּאַחַד מֵהֶם. אַעֲלֶה אֲנִי עָלֶיךָ כְּאִלּוּ אַתָּה מִן הַבָּאִים עֲלֵיהֶם:\",2,0],[2,134,1,12,\"וְאַל תֵּרֶא בְיוֹם אָחִיךָ. לֹא הָיָה לְךָ לְהַבִּיט וְלַעֲמוֹד מִנֶּגֶד:\",1,0],[2,134,1,12,\"בְּיוֹם נָכְרוֹ. בְּיוֹם הִסְגִּירוֹ בְּיַד אוֹיֵב, הוּא הַבַּבְלִיִּים. וְכֵן הוּא אוֹמֵר בְּשָׁאוּל ״נִכַּר אֹתוֹ אֱלֹהִים בְּיָדִי״ (שמואל א כג:ז), הִסְגִּיר אוֹתוֹ בְּיָדִי:\",2,0],[2,134,1,13,\"וְאַל תִּשְׁלַחְנָה בְחֵילוֹ. אַל תִּשְׁלַחְנָה יָדְךָ בִּנְכָסָיו, כֵּן תִּרְגֵּם יוֹנָתָן. וּמִקְרָא קָצָר הוּא וְצָרִיךְ לְהוֹסִיף עָלָיו יָדְךָ:\",1,0],[2,134,1,14,\"וְאַל תַּעֲמֹד עַל הַפֶּרֶק. מָקוֹם שֶׁהַבּוֹרְחִים יוֹצְאִים דֶּרֶךְ שָׁם לִימָּלֵט, וּבִלְשׁוֹן לַעַ״ז קוֹרְאִים אוֹתוֹ טרו״ג:\",1,0],[2,134,1,16,\"כַּאֲשֶׁר שְׁתִיתֶם עַל הַר קָדְשִׁי. כְּמָה דַחֲדִיתוּן עַל מְחַת טוּרָא דְקוּדְשִׁי:\",1,0],[2,134,1,16,\"וְלָעוּ. כְּתַרְגּוּמוֹ: וְיִסְתַּלְעֲמוּן, לְשׁוֹן מְהוּמָה וְשִׁמָּמוֹן וְטֵרוּף דַּעַת, אישטורדישו״ן בְּלַעַ״ז:\",2,0],[2,134,1,17,\"אֵת מוֹרָשֵׁיהֶם. נִכְסֵי עַמְמַיָּא דַּהֲווֹ מַחְסְנִין לְהוֹן:\",1,0],[2,134,1,18,\"כִּי ה׳ דִּבֵּר. וְהֵיכָן דִּבֵּר? ״וְיֵרְדְּ מִיַּעֲקֹב וְהֶאֱבִיד שָׂרִיד וְגוֹ׳״ (במדבר כד:יט):\",1,0],[2,134,1,19,\"וְיָרְשׁוּ הַנֶּגֶב. יִשְׂרָאֵל שֶׁהָיוּ יוֹשְׁבִין בִּדְרוֹמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל יִירְשׁוּ אֶת הַר עֵשָׂו שֶׁהוּא בְּמֵצַר דָּרוֹם, וּבְנֵי הַשְּׁפֵלָה יִירְשׁוּ אֶת אֶרֶץ פְּלִשְׁתִּים וְאֶת הַר אֶפְרַיִם וְאֶת הַר שׁוֹמְרוֹן:\",1,0],[2,134,1,19,\"וּבִנְיָמִין אֶת הַגִּלְעָד. וּבְנֵי מְנַשֶּׁה שֶׁהָיְתָה אֶרֶץ גִּלְעָד שֶׁלָּהֶם יִפְשְׁטוּ לָהֶם מֵהַלְאָה לִגְבוּלוֹתֶיהָ שֶׁל אֶרֶץ יִשְׂרָאֵל בְּמִזְרָחָהּ:\",2,0],[2,134,1,20,\"וְגָלוּת הַחֵל הַזֶּה. תִּרְגֵּם יוֹנָתָן: עַמָּא הָדֵין. הַחֵל לְשׁוֹן חַיִל, כְּמוֹ ״וַיָּבֹא יְרוּשָׁלַיִם בְּחֵיל כָּבֵד״ (ישעיהו לו:ב) דְּרַבְשָׁקֵה, אֶלָּא שֶׁזֶּה חָסֵר יוֹ״ד. וְיֵשׁ עוֹד לְפָרֵשׁ הַחֵל הַזֶּה - גָּלוּת הַגַּיְא הַזֶּה:\",1,0],[2,134,1,20,\"לִבְנֵי יִשְׂרָאֵל אֲשֶׁר כְּנַעֲנִים עַד צָרְפַת. גָּלוּת אֲשֶׁר הוּא מִבְּנֵי יִשְׂרָאֵל שֶׁגָּלוּ מֵעֲשֶׂרֶת הַשְּׁבָטִים לְאֶרֶץ כְּנַעֲנִים עַד צָרְפַת:\",2,0],[2,134,1,20,\"וְגָלוּת יְרוּשָׁלַ͏ִם אֲשֶׁר בִּסְפָרַד. שֶׁהֵם מִבְּנֵי יְהוּדָה אֲשֶׁר גָּלוּ לִסְפָרַד, הֵם יִירְשׁוּ אֶת עָרֵי הַנֶּגֶב שֶׁבִּדְרוֹמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל. וְאוֹמְרִים הַפּוֹתְרִים: צָרְפַת הוּא הַמַּלְכוּת שֶׁקּוֹרִין פרנצ״א בְּלַעַ״ז. סְפָרַד תִּרְגֵּם יוֹנָתָן: אספמיא:\",3,0],[2,134,1,21,\"וְעָלוּ. שָׂרֵי יִשְׂרָאֵל מוֹשִׁיעִים בְּהַר צִיּוֹן:\",1,0],[2,134,1,21,\"לִשְׁפֹּט אֶת הַר עֵשָׂו. לִיפָּרַע מֵהַר עֵשָׂו אֲשֶׁר עָשׂוּ לְיִשְׂרָאֵל. לִשְׁפֹּט יושטיציי״ר בְּלַעַ״ז:\",2,0],[2,134,1,21,\"הַר עֵשָׂו. תַּרְגּוּם יוֹנָתָן: כַּרְכָּא רַבָּא דְעֵשָׂו:\",3,0],[2,134,1,21,\"וְהָיְתָה לַה׳ הַמְּלוּכָה. לִמֶּדְךָ שֶׁאֵין מַלְכוּתוֹ שְׁלֵימָה עַד שֶׁיִּפָּרַע מֵעֲמָלֵק:\",4,0],[2,135,1,1,\"מִשְׁלֵי. כָּל דְּבָרָיו דֻּגְמוֹת וּמְשָׁלִים; מְשַׁל הַתּוֹרָה בְּאִשָּׁה טוֹבָה, וּמְשַׁל הָעוֹבְדֵי גִּלּוּלִים בְּאִשָּׁה זוֹנָה:\",1,0],[2,135,1,2,\"לָדַעַת חָכְמָה וּמוּסָר. הַמְּשָׁלִים הָאֵלּוּ אָמַר לְהוֹדִיעַ לַבְּרִיּוֹת חָכְמָה וּמוּסָר שֶׁיִּהְיוּ עֲמֵלִים בַּתּוֹרָה, שֶׁהִיא חָכְמָה וּמוּסָר וּבִינָה:\",1,0],[2,135,1,3,\"צֶדֶק וּמִשְׁפָּט וּמֵישָׁרִים. צֶדֶק, צְדָקָה מִמָּמוֹנוֹ. וּמִשְׁפָּט, לִשְׁפּוֹט אֱמֶת. וּמֵישָׁרִים, הִיא הַפְּשָׁרָה דֶּרֶךְ חָלָק וּמִישׁוֹר שָׁוֶה לָזֶה וְלָזֶה:\",1,0],[2,135,1,4,\"לָתֵת לִפְתָאיִם עָרְמָה. מְשָׁלִים אֵלּוּ אָמַר קֹהֶלֶת לִקְנוֹת בָּהֶם הַפְּתָאיִם עָרְמָה, לְנַעַר דַּעַת, וְגַם לְנַעַר הַמְנֻעָר מִכָּל לִמּוּד שֶׁלֹּא לָמַד עֲדַיִן כְּלוּם:\",1,0],[2,135,1,4,\"מְזִמָּה. מַחֲשֶׁבֶת עֵצָה:\",2,0],[2,135,1,5,\"יִשְׁמַע חָכָם. הַמְּשָׁלִים הַלָּלוּ:\",1,0],[2,135,1,5,\"וְיוֹסֶף. עַל חָכְמָתוֹ:\",2,0],[2,135,1,5,\"לֶקַח. לִמּוּד:\",3,0],[2,135,1,5,\"חָכָם. זֶה בַּעַל הַשְּׁמוּעָה:\",4,0],[2,135,1,5,\"וְנָבוֹן. מוֹסִיף עַל יְדִיעַת חָכָם, שֶׁיּוֹדֵעַ לְהָבִין דָּבָר מִתּוֹךְ דָּבָר וּמוֹסִיף עַל שְׁמוּעָתוֹ:\",5,0],[2,135,1,6,\"לְהָבִין מָשָׁל וּמְלִיצָה. שֶׁיִּתְּנוּ לֵב לְהָבִין בַּמִּקְרָאוֹת שְׁנֵי הַדְּרָכִים: הַמָּשָׁל וְהַמְּלִיצָה, שֶׁיָּבִינוּ אֶת מָה הִמְשִׁיל לַמְּלִיצָה. וְאַף מִן הַמְּלִיצָה לֹא יָסוּרוּ לִבָּם, שֶׁגַּם הִיא צְרִיכִים לְהָבִין. כְּשֶׁאָמַר ״לְהַצִּילְךָ מֵאִשָּׁה זָרָה״ וְ״נָכְרִיָּה״ (משלי ב:טז) – עַל עֲבוֹדָה זָרָה נֶאֱמַר, הֲרֵי הַמָּשָׁל. וְאַף הַמְּלִיצָה שֶׁהוֹצִיא מְשָׁלוֹ בִּלְשׁוֹן ׳אִשָּׁה׳ – הָבֵן בָּהּ וְהִזָּהֵר מֵאִשָּׁה (  זוֹנָה):\",1,0],[2,135,1,6,\"דִּבְרֵי חֲכָמִים וְחִידוֹתָם. דּוֹרְשֵׁי רְשִׁימוֹת: מִקְרָא מָלֵא וְחָסֵר, רֶמֶז, דִּמְיוֹן וְחִידָה:\",2,0],[2,135,1,7,\"יִרְאַת ה׳ רֵאשִׁית דָּעַת. עַד כָּאן פֵּרֵשׁ לְצֹרֶךְ מָה עָשָׂה שְׁלֹמֹה הַסֵּפֶר הַזֶּה, וְעַתָּה מַתְחִיל הַסֵּפֶר:\",1,0],[2,135,1,7,\"יִרְאַת ה׳ רֵאשִׁית דָּעַת. הִיא תְּרוּמַת עִקַּר הַדַּעַת וְהִיא תִּהְיֶה לְךָ הָרִאשׁוֹנָה לָדַעַת. לִפְנֵי חָכְמָתְךָ הַקְדֵּם לְיִרְאָה אֶת יוֹצְרְךָ, וְהִיא תִּתֵּן בְּלִבְּךָ לַעֲשׂוֹת בְּחָכְמָה וּבְדַעַת, כִּי הָאֱוִילִים, אֲשֶׁר אֵינָם יְרֵאִים אֶת ה׳, הֵם בּוֹזִים אֶת הַחָכְמָה וְאֶת הַמּוּסָר:\",2,0],[2,135,1,8,\"שְׁמַע בְּנִי מוּסַר אָבִיךָ. מַה שֶּׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה בִּכְתָב וְעַל פֶּה:\",1,0],[2,135,1,8,\"אִמֶּךָ. אוּמָּתְךָ, כְּנֶסֶת יִשְׂרָאֵל, כְּמוֹ: ״מָה אִמְּךָ לְבִיָּא״ (יחזקאל יט:ב). וְהֵם דִּבְרֵי סוֹפְרִים, שֶׁחִדְּשׁוּ וְהוֹסִיפוּ וְעָשׂוּ סְיָגִים לַתּוֹרָה:\",2,0],[2,135,1,9,\"לִוְיַת חֵן. חִבּוּר שֶׁל חֵן הֵם לְרֹאשְׁךָ, כְּלוֹמַר: הַתּוֹרָה וְהַמּוּסָר יִהְיוּ לְרֹאשְׁךָ לִוְיַת חֵן, וְכַעֲנָקִים שֶׁל עֲדִי זָהָב יִהְיוּ:\",1,0],[2,135,1,9,\"לְגַרְגְּרוֹתֶיךָ. לְצַוָּארְךָ, וְעַל שֵׁם שֶׁהַקָּנֶה עֲשׂוּיָה טַבָּעוֹת טַבָּעוֹת, קוֹרֵא הַצַּוָּאר בִּלְשׁוֹן רַבִּים:\",2,0],[2,135,1,10,\"חַטָּאִים. חוֹטְאִים:\",1,0],[2,135,1,10,\"אַל תֹּבֵא. אַל תֹּאבֶה לָהֶם:\",2,0],[2,135,1,11,\"נֶאֶרְבָה לְדָם. לִשְׁפּוֹךְ דָּם:\",1,0],[2,135,1,11,\"נִצְפְּנָה. לְשׁוֹן ״מַאֲרָב״ (יהושע ח:ט):\",2,0],[2,135,1,11,\"נִצְפְּנָה לְנָקִי חִנָּם. הַכָּתוּב אוֹמֵר שֶׁצְּפִינָתָם לְנָקִי – חִנָּם הוּא:\",3,0],[2,135,1,12,\"נִבְלָעֵם. לַנְּקִיִּים כְּשֶׁהֵם חַיִּים:\",1,0],[2,135,1,12,\"כְּשְׁאוֹל. הַבּוֹלֵעַ כָּל גּוּף שָׁלֵם:\",2,0],[2,135,1,12,\"וּתְמִימִים. אֵינוֹ לְשׁוֹן צַדִּיקִים, אֶלָּא מִלְּשׁוֹן שְׁלֵמִים: נִבְלָעֵם כְּשֶׁהֵם שְׁלֵמִים, כְּאָדָם הַיּוֹרֵד בְּתוֹךְ הַבּוֹר כְּשֶׁהוּא שָׁלֵם. כְּלוֹמַר: בְּעוֹדָם בְּעָשְׁרָם נַהַרְגֵם, וְנִירַשׁ נִכְסֵיהֶם:\",3,0],[2,135,1,14,\"גּוֹרָלְךָ תַּפִּיל בְּתוֹכֵנוּ. אִם תִּרְצֶה תַּחֲלֹק, אוֹ אִם תִּרְצֶה יִהְיֶה בְּשֻׁתָּפוּת:\",1,0],[2,135,1,14,\"כִּיס אֶחָד יִהְיֶה לְכֻלָּנוּ. בְּיַחַד:\",2,0],[2,135,1,16,\"לָרַע יָרוּצוּ. לְרָעַת עַצְמָם הֵם רָצִים, וְאֵינָם יוֹדְעִים לָתֵת לֵב לַדָּבָר:\",1,0],[2,135,1,17,\"כִּי חִנָּם מְזֹרָה הָרָשֶׁת. כִּי הָעוֹפוֹת הָרוֹאוֹת חִטִּים וְקִטְנִיּוֹת מְזוֹרִים עַל הָרֶשֶׁת, חִנָּם הוּא בְּעֵינֵיהֶם, שֶׁאֵינָם מַכִּירִים עַל מָה הִיא נִזְרֶת, וְיוֹרְדִין בָּהּ וְאוֹכְלִין:\",1,0],[2,135,1,18,\"וְהֵם לְדָמָם יֶאֱרֹבוּ. וְהַצַּיָּדִים יֶאֱרֹבוּ לְדָמָם שֶׁל עוֹפוֹת:\",1,0],[2,135,1,19,\"כֵּן אָרְחוֹת כָּל בֹּצֵעַ בָּצַע. גּוֹזֵל גְּזֵילָה נָאָה וְנֶחְמֶדֶת הִיא לוֹ, וְחִנָּם הִיא לוֹ (משלי א:יז), וְסוֹפוֹ אֶת נֶפֶשׁ בְּעָלָיו יִקָּח. נֶפֶשׁ עַצְמוֹ, שֶׁנַּעֲשָׂה עַכְשָׁיו בַּעַל הַמָּמוֹן שֶׁגָּזַל מֵחֲבֵרוֹ:\",1,0],[2,135,1,20,\"חָכְמוֹת בַּחוּץ תָּרֹנָּה. הֲרֵי חָכְמוֹתֶיהָ שֶׁל תּוֹרָה בְּחוּצוֹתֶיהָ תִּזְעַקְנָה לְהַזְהִירְכֶם לָסוּר עֲלֵיהֶם. וּמָה הֵן חוּצוֹתֶיהָ? בָּתֵּי מִדְרָשׁוֹת:\",1,0],[2,135,1,20,\"בָּרְחוֹבוֹת. בִּמְקוֹם שֶׁמַּרְחִיבִין אוֹתָהּ. כָּךְ דָּרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, בחקותי ד):\",2,0],[2,135,1,21,\"בְּרֹאשׁ הוֹמִיּוֹת תִּקְרָא. בְּמָקוֹם שֶׁהִיא נִשְׁמַעַת וְנִכְרֶזֶת, שָׁם הִיא קוֹרֵאת וְאוֹמֶרֶת עִנְיָן שֶׁלְּמַטָּה: עַד מָתַי פְּתָיִם וְגוֹ׳:\",1,0],[2,135,1,21,\"בְּפִתְחֵי שְׁעָרִים. הֵם מְקוֹם יְשִׁיבַת הַזְּקֵנִים:\",2,0],[2,135,1,22,\"פְּתָיִם. הַמִּתְפַּתִּים עַל יְדֵי מְסִיתִים וּמִינִים:\",1,0],[2,135,1,22,\"תְּאֵהֲבוּ פֶתִי. הֲסָתָה שֵׁם דָּבָר לְ״פַתְיוּת״ (משלי ט:יג), כְּמוֹ ״כֶּלִי״ (במדבר יט:יז), ״קֶרִי״ (ויקרא כו:כא), (שני סא״א) ״שֶׁפִי״ (במדבר כג:ג):\",2,0],[2,135,1,24,\"נָטִיתִי יָדִי. לִרְמֹז לָהֶם לָסוּר אֵלַי, כְּאָדָם הַמְרַמֵּז לַחֲבֵרוֹ בְּיָדוֹ וְנוֹטֶה יָדוֹ אֵלָיו, לָסוּר אֵלָיו:\",1,0],[2,135,1,25,\"וַתִּפְרְעוּ. וּתְבַטְּלוּ:\",1,0],[2,135,1,25,\"כָּל עֲצָתִי. שֶׁיָּעַצְתִּי לְגַדֵּל אֶתְכֶם בָּעוֹלָם:\",2,0],[2,135,1,27,\"כְּשׁוֹאָה. כְּעָנָן הָעוֹלֶה פִּתְאוֹם:\",1,0],[2,135,1,27,\"כְּסוּפָה. טוֹרְבִּילוֹ״ן בְּלַעַ״ז:\",2,0],[2,135,1,27,\"יֶאֱתֶה. יָבֹא:\",3,0],[2,135,1,28,\"יְשַׁחֲרוּנְנִי. יְבַקְשׁוּנִי:\",1,0],[2,135,1,31,\"מִפְּרִי דַרְכָּם. הַפֵּרוֹת שֶׁאוֹכְלִים בְּחַיֵּיהֶם בַּצָּרוֹת הַמּוֹצְאוֹת אוֹתָם, וְהַקֶּרֶן שְׁמוּרָה לָהֶם בַּגֵּיהִנֹּם:\",1,0],[2,135,1,32,\"מְשׁוּבַת פְּתָיִם. אֶת אֲשֶׁר לִבָּם שׁוֹבָב:\",1,0],[2,135,1,32,\"וְשַׁלְוַת כְּסִילִים תְּאַבְּדֵם. לְפִי שֶׁרוֹאִים הָרְשָׁעִים שֶׁהֵם מַצְלִיחִים, נִדְבָּקִים בְּרָעָתָם וְאֵינָם חוֹזְרִין:\",2,0],[2,135,1,33,\"יִשְׁכָּן בֶּטַח. בָּעוֹלָם הַזֶּה:\",1,0],[2,135,1,33,\"וְשַׁאֲנַן. לְעוֹלָם הַבָּא:\",2,0],[2,135,1,33,\"מִפַּחַד רָעָה. מִדִּינָהּ שֶׁל גֵּיהִנֹּם:\",3,0],[2,135,1,33,\"וְשַׁאֲנַן. וִיהִי שָׁלֵיו וְשָׁקֵט, וְשַׁאֲנַן לְשׁוֹן עָתִיד לָכֵן נָקוּד פַּתַּח:\",4,0],[2,135,2,1,\"בְּנִי אִם תִּקַּח אֲמָרָי. בְּנִי תִּהְיֶה  אִם תִּקַּח אֲמָרָי:\",1,0],[2,135,2,2,\"לְהַקְשִׁיב לַחָכְמָה. לַעֲסוֹק בַּתּוֹרָה:\",1,0],[2,135,2,5,\"אָז תָּבִין יִרְאַת ה׳. מוּסָב עַל עִנְיָן שֶׁלְּמַעְלָה, שֶׁאָמַר כִּי אִם לַבִּינָה תִקְרָא:\",1,0],[2,135,2,6,\"כִּי ה׳ יִתֵּן חָכְמָה. הָא לָמַדְתָּ שֶׁגְּדוֹלָה הִיא, שֶׁהֲרֵי נִתְּנָה מִפִּי הַקָּדוֹשׁ בָּרוּךְ הוּא, לְכָךְ אַתָּה צָרִיךְ לִקְנוֹתָהּ:\",1,0],[2,135,2,7,\"יִצְפֹּן לַיְשָׁרִים תּוּשִׁיָּה. גְּנָזָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶצְלוֹ (תנחומא, לך לך יא) עֶשְׂרִים וָשֵׁשׁ דּוֹרוֹת עַד שֶׁנְּתָנָהּ לְדוֹר הַמִּדְבָּר:\",1,0],[2,135,2,7,\"מָגֵן לְהוֹלְכֵי תֹם. (יִצְפֹּן מָגֵן לְהוֹלְכֵי תֹם), כְּלוֹמַר: וְהִיא תִּהְיֶה לְךָ לְמָגֵן:\",2,0],[2,135,2,8,\"לִנְצֹר אָרְחוֹת מִשְׁפָּט. שֶׁעַל יָדָהּ יִנְצְרוּ אָרְחוֹת מִשְׁפָּט, וְהוּא דֶּרֶךְ חֲסִידָיו יִשְׁמֹר. שֶׁלֹּא יִכָּשְׁלוּ:\",1,0],[2,135,2,11,\"מְזִמָּה תִּשְׁמֹר עָלֶיךָ. הַתּוֹרָה תִּשְׁמֹר עָלֶיךָ:\",1,0],[2,135,2,12,\"מֵאִישׁ מְדַבֵּר תַּהְפֻּכוֹת. הֵם הָאֶפִּיקוֹרְסִין שֶׁמַּטְעִין אֶת יִשְׂרָאֵל מֵאֱמוּנָתָן וּמְהַפְּכִין אֶת הַתּוֹרָה לְרָעָה:\",1,0],[2,135,2,15,\"וּנְלוֹזִים בְּמַעְגְּלוֹתָם. כָּל לְשׁוֹן ׳נָלוֹז׳ לְשׁוֹן ׳עַקְמִימוּת׳ הוּא, שֶׁבְּכָל מָקוֹם הוּא סָמוּךְ לְ׳עִקֵּשׁ׳ (משלי ד:כד), וְ׳עִקֵּשׁ׳ הוּא לְשׁוֹן ׳עָקוֹם׳, כְּמוֹ שֶׁנֶּאֱמַר ״וּמַעֲקַשִּׁים לְמִישׁוֹר״ (ישעיה מב:טז):\",1,0],[2,135,2,15,\"וּנְלוֹזִים בְּמַעְגְּלוֹתָם. הֵם עֲקוּמִים בְּדַרְכֵיהֶם הַמְקֻלְקָלִים:\",2,0],[2,135,2,16,\"מֵאִשָּׁה זָרָה. מִכְּנֵסִיָּה שֶׁל אֲפִיקוֹרְסוּת וְהִיא הַמִּינוּת. וְלֹא יִתָּכֵן לוֹמַר, שֶׁלֹּא דִּבֵּר אֶלָּא עַל הַמְנָאֶפֶת מַמָּשׁ, כִּי מַה שִּׁבְחָהּ שֶׁל תּוֹרָה שֶׁאָמַר כָּאן לְהַצִּילְךָ מֵאִשָּׁה זָרָה וְלֹא מֵעֲבֵירָה אַחֶרֶת? אֶלָּא זוֹ מִינוּת, שֶׁהוּא פְּרִיקַת עֹל שֶׁל כָּל הַמִּצְווֹת:\",1,0],[2,135,2,18,\"כִּי שָׁחָה אֶל מָוֶת בֵּיתָהּ. מוּסָב עַל לְהַצִּילְךָ וְגוֹ׳, כִּי תָבֹא אֶל בֵּיתָהּ, יָשַׁח וּמַחֲלִיק כְּמִדְרוֹן הַיּוֹרֵד אֶל מָוֶת. וְהַתּוֹרָה תִּשְׁמֹר עָלֶיךָ מִנְּפִילָה זוֹ, הֲרֵי דָּבָר גָּדוֹל הוּא לְךָ:\",1,0],[2,135,2,18,\"רְפָאִים. נִרְפִּים מִדֶּרֶךְ הַטּוֹב וְנֶעֱזָבִים מֵאֵין סוֹמֵךְ, עַד שֶׁנּוֹפְלִים בַּגֵּיהִנֹּם:\",2,0],[2,135,2,19,\"לֹא יְשׁוּבוּן. יִקְשֶׁה בְּעֵינֵיהֶם לִפְרֹשׁ מִמֶּנָּה וְלַחֲזֹר בָּהֶם:\",1,0],[2,135,2,20,\"לְמַעַן תֵּלֵךְ. מוּסָב עַל הַמִּקְרָא שֶׁלְּמַעְלָה לְהַצִּילְךָ מִדֶּרֶךְ רָעָה, לְמַעַן הוֹלִיכְךָ בְּדֶרֶךְ טוֹבִים:\",1,0],[2,135,2,21,\"כִּי יְשָׁרִים יִשְׁכְּנוּ אָרֶץ. לָעוֹלָם הַבָּא:\",1,0],[2,135,2,21,\"יִוָּתְרוּ בָהּ. כְּשֶׁיֵּרְדוּ רְשָׁעִים לְגֵיהִנֹּם:\",2,0],[2,135,3,2,\"אֹרֶךְ יָמִים וְגוֹ׳ וְשָׁלוֹם יוֹסִיפוּ לָךְ. תּוֹרָתִי וּמִצְווֹתַי:\",1,0],[2,135,3,5,\"בְּטַח אֶל ה׳. וּפַזֵּר מְעוֹתֶיךָ לְבַקֵּשׁ לְךָ רַב לִלְמֹד מִמֶּנּוּ, וְאֶל בִּינָתְךָ אַל תִּשָּׁעֵן:\",1,0],[2,135,3,7,\"אַל תְּהִי חָכָם בְּעֵינֶיךָ. לִהְיוֹת מוֹאֵס בְּדִבְרֵי מוֹכִיחֶךָ:\",1,0],[2,135,3,8,\"רִפְאוּת תְּהִי לְשָׁרֶּךָ. הַחָכְמָה. שָׁרֶּךָ כְּמוֹ ״שָׁרְרֵךְ״ (שיר השירים ז:ג), וְזֶהוּ טִיבּוּרֶךָ:\",1,0],[2,135,3,8,\"וְשִׁקּוּי לְעַצְמוֹתֶיךָ. הוּא הַמֹּחַ, כְּעִנְיָן שֶׁנֶּאֱמַר ״וּמֹחַ עַצְמוֹתָיו יְשֻׁקֶּה״ (איוב כא:כד):\",2,0],[2,135,3,9,\"מֵהוֹנֶךָ. מִכָּל מַה שֶּׁחֲנָנְךָ, אֲפִלּוּ מִקּוֹל עָרֵב. (אַל תִּקְרִי מֵהוֹנֶךָ אֶלָּא מִגְּרוֹנֶךָ):\",1,0],[2,135,3,9,\"וּמֵרֵאשִׁית. אֵלּוּ תְּרוּמוֹת וּמַעַשְׂרוֹת:\",2,0],[2,135,3,11,\"מוּסַר ה׳ בְּנִי אַל תִּמְאָס. אִם יָבוֹאוּ עָלֶיךָ יִסּוּרִין, יִהְיוּ חֲבִיבִין עָלֶיךָ (תנחומא, יתרו טז):\",1,0],[2,135,3,11,\"וְאַל תָּקֹץ. מִלְּשׁוֹן ״קַצְתִּי בְחַיַּי״ (בראשית כז:מו):\",2,0],[2,135,3,12,\"וּכְאָב אֶת בֵּן יִרְצֶה. שֶׁרוֹצֶה בִּבְנוֹ לְהֵיטִיב לוֹ וִיפַיְּסֵהוּ לְאַחַר שֶׁמַּכֵּהוּ בַּשֵּׁבֶט, כֵּן יֶעֱרַב לְךָ הַטּוֹבָה אַחַר הַמַּכָּה:\",1,0],[2,135,3,13,\"אַשְׁרֵי אָדָם מָצָא חָכְמָה וְאָדָם יָפִיק תְּבוּנָה. שֶׁלּוֹמֵד חָכְמָה עַד שֶׁשְּׁגוּרָה הִיא לְהוֹצִיא מִפִּיו:\",1,0],[2,135,3,14,\"כִּי טוֹב סַחְרָהּ מִסְּחַר כָּסֶף. כָּל חִלּוּפִין שֶׁאָדָם מַחֲלִיף בִּסְחוֹרָה, זֶה נוֹטֵל זֶה וְזֶה נוֹטֵל זֶה. אֲבָל הָאוֹמֵר לַחֲבֵירוֹ: שְׁנֵה לִי פִּרְקְךָ וַאֲנִי אֶשְׁנֶה לְךָ פִּרְקִי, נִמְצְאוּ שְׁנֵיהֶם בְּיַד כָּל אֶחָד וְאֶחָד:\",1,0],[2,135,3,14,\"חָרוּץ. מִין זָהָב הוּא:\",2,0],[2,135,3,15,\"וְכָל־חֲפָצֶיךָ. כָּל חֲמֻדּוֹתֶיךָ:\",1,0],[2,135,3,15,\"לֹא יִשְׁווּ בָהּ. לֹא יִהְיוּ שָׁוִין בְּשָׁוְיָהּ וְדָמֵיהֶן בְּדָמֶיהָ:\",2,0],[2,135,3,16,\"בִּימִינָהּ. לַמְּיַמִּינִים בָּהּ וְעוֹסְקִים בָּהּ לִשְׁמָהּ, אֹרֶךְ יָמִים, וְכָל שֶׁכֵּן עֹשֶׁר וְכָבוֹד. וְלַמַּשְׂמִאילִים בָּהּ, שֶׁעוֹסְקִים בָּהּ שֶׁלֹּא לִשְׁמָהּ, מִכָּל מָקוֹם עֹשֶׁר וְכָבוֹד יֵשׁ (שבת סג.):\",1,0],[2,135,3,18,\"לַמַּחֲזִיקִים בָּהּ. לָאוֹחֲזִים בָּהּ, כְּמוֹ ״וַיִּשְׁלַח יָדוֹ וַיַּחֲזֶק בּוֹ״ (שמות ד:ד):\",1,0],[2,135,3,18,\"וְתוֹמְכֶיהָ מְאֻשָּׁר. הַמִּתְקָרְבִים לָהּ, וְכֵן כָּל לְשׁוֹן תְּמִיכָה שֶׁבְּסֵפֶר זֶה – שֶׁהוּא אוֹחֵז בָּהּ:\",2,0],[2,135,3,19,\"ה׳ בְּחָכְמָה יָסַד אָרֶץ. עַל פִּי הַתּוֹרָה, וְהִיא הַתּוֹרָה וְהִיא הַתְּבוּנָה וְהוּא הַדַּעַת. וְאַחַר שֶׁכָּל הָעוֹלָם נִבְרָא בָהֶם, לְכָךְ:\",1,0],[2,135,3,20,\"יִרְעֲפוּ. כְּמוֹ יַטִּיפוּ:\",1,0],[2,135,3,21,\"אַל יָלֻזוּ מֵעֵינֶיךָ. אַל יִתְעַקְּמוּ מִנֶּגֶד עֵינֶיךָ לַהֲסִירָם מִכְּנֶגְדְּךָ:\",1,0],[2,135,3,22,\"וְיִהְיוּ חַיִּים לְנַפְשֶׁךָ. שֶׁהֲרֵי עֵץ חַיִּים הוּא:\",1,0],[2,135,3,22,\"וְחֵן לְגַרְגְּרוֹתֶיךָ. שֶׁהֲרֵי זֶה שִׁבְחָהּ הָאָמוּר לְמַעְלָה ״וַעֲנָקִים לְגַרְגְּרוֹתֶיךָ״ (משלי א:ט):\",2,0],[2,135,3,23,\"לֹא תִגּוֹף. לְשׁוֹן כִּשָּׁלוֹן, אצופי״ר בְּלַעַ״ז, וְכֵן ״פֶּן תִּגּוֹף בָּאֶבֶן״ (תהלים צא:יב), וְכֵן ״בְּטֶרֶם יִתְנַגְּפוּ רַגְלֵיכֶם״ (ירמיה יג:טז), וְכֵן ״וְנָגְפוּ אִשָּׁה הָרָה״ (שמות כא:כב):\",1,0],[2,135,3,24,\"וְשָׁכַבְתָּ וְעָרְבָה שְׁנָתֶךָ. וְתִנְעַם שְׁנָתְךָ כְּשֶׁתִּישַׁן, שֶׁלֹּא תִירָא מִפַּחַד פִּתְאוֹם:\",1,0],[2,135,3,25,\"וּמִשּׁוֹאַת. כְּשֶׁתָּבוֹא עַל הָרְשָׁעִים:\",1,0],[2,135,3,26,\"כִּי ה׳ יִהְיֶה בְכִסְלֶךָ. בְּמִבְטַחֲךָ. דָּבָר אַחֵר: בַּדְּבָרִים שֶׁאַתָּה כְּסִיל בָּהֶן. כָּךְ מָצָאתִי בִּירוּשַׁלְמִי (פאה א:א):\",1,0],[2,135,3,27,\"אַל תִּמְנַע טוֹב מִבְּעָלָיו. אִם רָאִיתָ חֲבֵירְךָ חָפֵץ לְהֵיטִיב לָעֲנִיִּים, אַל תִּמְנָעֵהוּ:\",1,0],[2,135,3,27,\"בִּהְיוֹת לְאֵל יָדְךָ. לְהַחֲדִילוֹ. דָּבָר אַחֵר: אַל תִּמְנַע טוֹב מִבְּעָלָיו, אַל תִּמְנַע צְדָקָה מִן הֶעָנִי, בִּהְיוֹת לְאֵל יָדְךָ לַעֲשׂוֹת צְדָקָה, שֶׁמָּא יָבוֹא יוֹם וְאֵין לְאֵל יָדְךָ:\",2,0],[2,135,3,28,\"וְכֵן אַל תֹּאמַר לְרֵעֲךָ. לֶעָנִי:\",1,0],[2,135,3,28,\"וְיֵשׁ אִתָּךְ. מַה שֶּׁתִּתֵּן לוֹ. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (בבא מציעא קי:): לֵךְ וָשׁוּב; עַל ״שְׂכַר שָׂכִיר״ (דברים טו:יח):\",2,0],[2,135,3,29,\"אַל תַּחֲרֹשׁ עַל רֵעֲךָ. אַל תַּחְשֹׁב. וְאֵינוֹ זָז מִמַּשְׁמָעוּת חֲרִישָׁה: מַה דֶּרֶךְ הַחוֹרֵשׁ – מֵכִין מָקוֹם לִזְמַן הַזְּרִיעָה, אַף הַחוֹשֵׁב רָעָה מֵכִין מָקוֹם תַּחְבּוּלוֹת בְּלִבּוֹ, אֵיךְ יַעֲמֹד וְיַעֲשֶׂנָּה:\",1,0],[2,135,3,30,\"אַל תָּרִיב עִם אָדָם. לְהִתְלוֹנֵן עָלָיו:\",1,0],[2,135,3,30,\"אִם לֹא גְמָלְךָ רָעָה. שֶׁעָבַר עַל הַמִּצְוָה הַכְּתוּבָה בַּתּוֹרָה ״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״ (ויקרא יט:יח). וּמִי שֶׁהוּא רָשָׁע, רַשַּׁאי אַתָּה לְשָׂנְאוֹ:\",2,0],[2,135,3,31,\"אַל תְּקַנֵּא בְּאִישׁ חָמָס. לַעֲשׂוֹת כְּמַעֲשָׂיו, אִם תִּרְאֵהוּ מַצְלִיחַ:\",1,0],[2,135,3,32,\"כִּי תוֹעֲבַת ה׳ נָלוֹז. מְעֻוָּת בִּדְרָכָיו:\",1,0],[2,135,3,32,\"וְאֶת יְשָׁרִים סוֹדוֹ. וְעִם יְשָׁרִים סוֹדוֹ:\",2,0],[2,135,3,34,\"אִם לַלֵּצִים. אָדָם נִמְשָׁךְ אַחֲרֵיהֶם, לְסוֹף אַף הוּא יִהְיֶה לֵץ עִמָּהֶם:\",1,0],[2,135,3,34,\"וְלַעֲנָוִים יִתֶּן חֵן. אִם לַעֲנָוִים יִתְחַבֵּר, סוֹף שֶׁיִּתְּנוּ מַעֲשָׂיו חֵן בְּעֵינֵיהֶם שֶׁל בְּרִיּוֹת:\",2,0],[2,135,3,35,\"כָּבוֹד חֲכָמִים יִנְחָלוּ וּכְסִילִים מֵרִים קָלוֹן. לְעַצְמוֹ מַפְרִישׁ קָלוֹן לְחֶלְקוֹ:\",1,0],[2,135,4,1,\"שִׁמְעוּ בָנִים מוּסַר אָב. הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,135,4,2,\"נָתַתִּי לָכֶם. הַנָּבִיא מִתְנַבֵּא וּמְדַבֵּר בִּשְׁלִיחוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וַהֲרֵי הוּא כְּפִיו:\",1,0],[2,135,4,3,\"כִּי בֵן הָיִיתִי לְאָבִי. אִם תֹּאמַר: שְׁלֹמֹה הָיָה שׂוֹנֵא הַבְּרִיּוֹת, שֶׁהִזְהִירָן עַל הַגָּזֵל וְעַל הָעֲרָיוֹת, דָּבָר שֶׁנַּפְשׁוֹ שֶׁל אָדָם מִתְאַוָּה לָהֶם, לְכָךְ נֶאֱמַר: כִּי בֵן הָיִיתִי וְגוֹ׳ רַךְ וְיָחִיד וְגוֹ׳. שֶׁהָיָה אוֹהֵב אוֹתִי יוֹתֵר:\",1,0],[2,135,4,4,\"וַיּוֹרֵנִי. עַל כָּךְ וַיּוֹכִיחֵנִי וַיֹּאמֶר לִי יִתְמָךְ דְבָרַי לִבֶּךָ. וּלְפִי שֶׁהוֹכִיחֵנִי בִּדְבָרִים אֵלּוּ, לְכָךְ אֲנִי מַזְהִירְכֶם עַל כָּךְ (רבי יוסף קרא). דָּבָר אַחֵר: כִּי בֵן הָיִיתִי לְאָבִי, הַנָּבִיא אוֹמֵר: בֵּן הָיִיתִי לְהַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִשְׁרָה רוּחוֹ עָלַי. וּמָצִינוּ שֶׁקְּרָאוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁלֹמֹה בֵּן, שֶׁנֶּאֱמַר ״אֲנִי אֶהְיֶה לּוֹ לְאָב וְגוֹ׳״ (שמואל ב ז:יד):\",1,0],[2,135,4,4,\"רַךְ וְיָחִיד לִפְנֵי אִמִּי. לְאֻמָּתִי אֲנִי נִבְחָר וְחָבִיב כְּבֵן רַךְ וְיָחִיד, לְכָךְ וַיּוֹרֵנִי אָבִי:\",2,0],[2,135,4,6,\"אַל תַּעַזְבֶהָ וְגוֹ׳ אֱהָבֶהָ. אֱהוֹב אוֹתָהּ:\",1,0],[2,135,4,7,\"רֵאשִׁית חָכְמָה קְנֵה חָכְמָה. תְּחִלַּת חָכְמָתְךָ לְמוֹד מֵאֲחֵרִים, קְנֵה לְךָ שְׁמוּעָה מִפִּי הָרַב, וְאַחַר כָּךְ בְּכָל קִנְיָנְךָ קְנֵה בִינָה, תִּתְבּוֹנֵן בָּהּ מֵעַצְמְךָ לְהַשְׂכִּיל הַטְּעָמִים, דָּבָר מִתּוֹךְ דָּבָר:\",1,0],[2,135,4,8,\"סַלְסְלֶהָ. חַפְּשֶׂהָ, הֱיֵה חוֹזֵר עָלֶיהָ לְדַקְדֵּק בָּהּ. כְּמוֹ ״כְּבוֹצֵר עַל סַלְסִלּוֹת״ (ירמיהו ו:ט) – הַחוֹזֵר וְהוֹלֵךְ בַּכֶּרֶם וּמֵשִׁיב יָדוֹ לְבַקֵּשׁ אֶת הָעוֹלֵלוֹת. וּבִלְשׁוֹן חֲכָמִים (תנחומא, וישב ח): מְסַלְסֵל בִּשְׂעָרוֹ:\",1,0],[2,135,4,9,\"תִּתֵּן לְרֹאשְׁךָ לִוְיַת חֵן. חֶבְרַת חֵן, כְּמוֹ ״לִוְיַת חֵן הֵם לְרֹאשֶׁךָ״ (משלי א:ט):\",1,0],[2,135,4,10,\"שמע בני וקח אמרי וגו':\",1,0],[2,135,4,12,\"בְּלֶכְתְּךָ לֹא יֵצַר צַעֲדֶךָ. מִי שֶׁאֵינוֹ מַרְחִיק רַגְלָיו, קָרוֹב לִיפּוֹל:\",1,0],[2,135,4,13,\"הַחֲזֵק בַּמּוּסָר אַל תֶּרֶף. אֱחוֹז בַּתּוֹרָה, כְּמוֹ ״וְהַחֲזִיקִי אֶת יָדֵךְ בּוֹ״ (בראשית כא:יח), ״וַיִּשְׁלַח יָדוֹ וַיַּחֲזֶק בּוֹ״ (שמות ד:ד):\",1,0],[2,135,4,14,\"בְּאֹרַח רְשָׁעִים אַל תָּבֹא וְאַל תְּאַשֵּׁר. וְאַל תִּדְרֹךְ, כְּמוֹ ״בַּאֲשֻׁרוֹ אָחֲזָה רַגְלִי״ (איוב כג:יא), וְכֵן ״וְנָבוֹן יָבִין לַאֲשֻׁרוֹ״ (משלי יד:טו):\",1,0],[2,135,4,15,\"פְּרָעֵהוּ. בַּטְּלֵהוּ:\",1,0],[2,135,4,15,\"שְׂטֵה מֵעָלָיו. סוּר:\",2,0],[2,135,4,16,\"כִּי לֹא יִשְׁנוּ. אֵינָם יְכוֹלִין לִישֹׁן:\",1,0],[2,135,4,18,\"וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. שֶׁהוֹלֵךְ וּמֵאִיר מֵעַמּוּד הַשַּׁחַר:\",1,0],[2,135,4,18,\"עַד נְכוֹן הַיּוֹם. עַד חֲצוֹת הַיּוֹם, שֶׁהוּא בֵּרוּרוֹ שֶׁל יוֹם:\",2,0],[2,135,4,19,\"דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה לֹא יָדְעוּ בַּמֶּה יִכָּשֵׁלוּ. פִּתְאוֹם יָבֹא לָהֶם מִכְשׁוֹל, וְלֹא יֵדְעוּ לְהִזָּהֵר מִמֶּנּוּ:\",1,0],[2,135,4,20,\"בְּנִי לִדְבָרַי הַקְשִׁיבָה וְגוֹ׳:\",1,0],[2,135,4,22,\"לְמוֹצְאֵיהֶם. לְשׁוֹן מְצִיאָה:\",1,0],[2,135,4,23,\"מִכָּל מִשְׁמָר. מִכָּל מַה שֶּׁאָמְרָה תּוֹרָה הִשָּׁמֶר נְצֹר לִבְּךָ (מֵעֲבוֹר עָלָיו), בֵּין עֲבֵרָה קַלָּה בֵּין עֲבֵרָה חֲמוּרָה:\",1,0],[2,135,4,23,\"כִּי מִמֶּנּוּ תּוֹצְאוֹת חַיִּים. כִּי מֵאוֹתוֹ שֶׁהוּא קַל יִהְיוּ לְךָ חַיִּים וְשָׂכָר גָּדוֹל אִם תְּקַיְּמֶנּוּ. כָּךְ דָּרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, כי תצא ב):\",2,0],[2,135,4,24,\"הָסֵר מִמְּךָ עִקְּשׁוּת פֶּה. לֹא תַּעֲשֶׂה דָבָר שֶׁיַּלְעִיזוּ בּוֹ הַבְּרִיּוֹת וְיַעֲקִימוּ עָלֶיךָ פִּיהֶם:\",1,0],[2,135,4,24,\"עִקְּשׁוּת פֶּה. לְשׁוֹן עִקּוּם, כְּמוֹ ״תָּם אָנִי וַיַּעְקְּשֵׁנִי״ (איוב ט:כ). וּבַמִּשְׁנָה (חולין נו.): שִׁנֶּיהָ עֲקוּמוֹת וַעֲקוּשׁוֹת:\",2,0],[2,135,4,24,\"וּלְזוּת שְׂפָתַיִם. עִקְּמִימוּת שְׂפָתַיִם, שֶׁלֹּא יַרְחִיבוּ הַבְּרִיּוֹת פֶּה עָלֶיךָ:\",3,0],[2,135,4,25,\"עֵינֶיךָ לְנֹכַח יַבִּיטוּ. יִסְתַּכְּלוּ אֶל הָאֱמֶת וְאֶל הַיֹּשֶׁר:\",1,0],[2,135,4,25,\"יַיְשִׁרוּ נֶגְדֶּךָ. יִסְתַּכְּלוּ עַל הַיְשָׁרָה, לְיַשֵּׁר דַּרְכְּךָ נֶגְדֶּךָ:\",2,0],[2,135,4,26,\"פַּלֵּס מַעְגַּל רַגְלֶךָ. שְׁקוֹל דַּרְכְּךָ: הֶפְסֵד מִצְוָה כְּנֶגֶד שְׂכָרָהּ, וּשְׂכַר עֲבֵרָה כְּנֶגֶד הֶפְסֵדָהּ (אבות ב:א), וְאָז כָּל דְּרָכֶיךָ יִכֹּנוּ:\",1,0],[2,135,4,27,\"אַל תֵּט יָמִין וּשְׂמֹאול. מִן הַמִּשְׁקָל הַטּוֹב:\",1,0],[2,135,5,1,\"בְּנִי לְחָכְמָתִי הַקְשִׁיבָה וְגוֹ׳:\",1,0],[2,135,5,3,\"כִּי נֹפֶת תִּטֹּפְנָה. לְשׁוֹן ״מָתוֹק״ (משלי כד:יג):\",1,0],[2,135,5,3,\"שִׂפְתֵי זָרָה. אֲפִיקוֹרְסוּת:\",2,0],[2,135,5,3,\"וְחָלָק מִשֶּׁמֶן חִכָּהּ. לְשׁוֹן ״חֵךְ״ (איוב יב:יא):\",3,0],[2,135,5,5,\"רַגְלֶיהָ יוֹרְדוֹת מָוֶת שְׁאוֹל צְעָדֶיהָ יִתְמֹכוּ. לְשׁוֹן קוּרְבָה:\",1,0],[2,135,5,6,\"אֹרַח חַיִּים פֶּן תְּפַלֵּס. כָּךְ דְּרָשׁוּהוּ חֲכָמִים (דברים רבה ו:ב): סִלְסֵל הַקָּדוֹשׁ בָּרוּךְ הוּא מַתַּן שְׂכָרָן שֶׁל מִצְווֹת וְלֹא פֵּרְשָׁן, כְּדֵי שֶׁלֹּא יִרְאֶה אָדָם מִצְוָה שֶׁמַּתַּן שְׂכָרָהּ מְרֻבֶּה וְיִדְבַּק בָּהּ, וְיַנִּיחַ שְׁאָר הַמִּצְווֹת. וְזֶה פִּתְרוֹנוֹ: כְּדֵי שֶׁלֹּא תְּפַלֵּס אָרְחוֹת הַתּוֹרָה, אֵי זוֹ לִיקַּח וְאֵי זוֹ לְהַנִּיחַ, לְכָךְ נָעוּ מַעְגְּלֹתֶיהָ. הֵנִיעַ הַקָּדוֹשׁ בָּרוּךְ הוּא נְתִיבוֹתֶיהָ וְלֹא הוֹדִיעָם. זֶהוּ מִדְרַשׁ אַגָּדָה (תנחומא, עקב ב). אֲבָל לְפִי סֵדֶר הַמִּקְרָאוֹת שֶׁכָּתוּב אַחֲרָיו הַרְחֵק מֵעָלֶיהָ דַרְכֶּךָ – נִרְאֶה, שֶׁעֲדַיִן לֹא הִפְסִיק בְּעִנְיַן אִשָּׁה הַזּוֹנָה, וְכֵן יֵשׁ לְפָרֵשׁ: אֹרַח חַיִּים פֶּן תְּפַלֵּס. אַל תִּשְׁקֹל אֹרַח חַיִּים אֵצֶל אוֹתָהּ זָרָה, לוֹמַר: אֵיזוֹ לַעֲשׂוֹת זוֹ אוֹ זוֹ? כִּי מַעְגְּלוֹת הַזּוֹנָה נָעוּ לִשְׁאוֹל, וְלֹא תֵדַע לְהִזָּהֵר עַד אֲשֶׁר תָּנוּעַ וְתִפּוֹל:\",1,0],[2,135,5,7,\"וְעַתָּה בָנִים שִׁמְעוּ לִי וְאַל תָּסוּרוּ מֵאִמְרֵי פִי:\",1,0],[2,135,5,9,\"פֶּן תִּתֵּן לַאֲחֵרִים הוֹדֶךָ. פֶּן תַּפְנֶה לִבְּךָ לֵאלֹהִים אֲחֵרִים, לָתֵת לָהֶם תִּפְאֶרֶת הוֹדְךָ וְשִׁבְחֲךָ:\",1,0],[2,135,5,9,\"וּשְׁנוֹתֶיךָ לְאַכְזָרִי. לְשַׂר שֶׁל גֵּיהִנֹּם:\",2,0],[2,135,5,10,\"פֶּן יִשְׂבְּעוּ זָרִים כֹּחֶךָ. נְבִיאֵי הַבַּעַל הַגּוֹבִין מָמוֹן בְּשִׁקְרֵיהֶם וּבְפַחֲזוּתָם (ירמיהו כג:לב):\",1,0],[2,135,5,10,\"וַעֲצָבֶיךָ. עֲצָבֶיךָ וִיגִיעֲךָ, שֶׁנֶּעֱצַבְתָּ וְטָרַחְתָּ בּוֹ:\",2,0],[2,135,5,10,\"בְּבֵית נָכְרִי. בְּבֵית עוֹבְדֵי גִּלּוּלִים:\",3,0],[2,135,5,11,\"וְנָהַמְתָּ בְאַחֲרִיתֶךָ. סוֹף שֶׁתִּנְהוֹם בְּאַחֲרִיתֶךָ:\",1,0],[2,135,5,14,\"כִּמְעַט הָיִיתִי בְכָל רָע. כְּפֶשַׂע בֵּינִי וּבֵין גֵּיהִנֹּם, (כְּלוֹמַר: בִּשְׁבִיל דָּבָר מוּעָט הָיִיתִי עַכְשָׁיו בְּכָל רָע, שֶׁלֹּא שָׁמַעְתִּי לְקוֹל מוֹרַי; שֶׁאִלּוּ שָׁמַעְתִּי לָהֶם, לֹא יֶאֱרַע בִּי כָּךְ רבי יוסף קרא):\",1,0],[2,135,5,15,\"שְׁתֵה מַיִם מִבּוֹרֶךָ. מִבּוֹר שֶׁנָּתַן לְךָ הַקָּדוֹשׁ בָּרוּךְ הוּא לְחֶלְקְךָ, הִיא תּוֹרַת מֹשֶׁה:\",1,0],[2,135,5,15,\"בּוֹרֶךָ. מַיִם מְכֻנָּסִים:\",2,0],[2,135,5,15,\"וְנוֹזְלִים מִתּוֹךְ בְּאֵרֶךָ. מַיִם חַיִּים. כְּלוֹמַר: תְּחִלָּה כְּמַיִם מְכֻנָּסִים, וּלְבַסּוֹף נוֹבְעִין הֵם וְהוֹלְכִין:\",3,0],[2,135,5,16,\"יָפוּצוּ מַעְיְנוֹתֶיךָ חוּצָה. סוֹף שֶׁתִּקְנֶה תַּלְמִידִים, וְתוֹרֶה הוֹרָאוֹת בָּרַבִּים, וְיֵצֵא לְךָ שֵׁם:\",1,0],[2,135,5,16,\"בָּרְחוֹבוֹת. עִיר תְּפוּצֶינָה פַּלְגֵי מֵימֶיךָ:\",2,0],[2,135,5,17,\"יִהְיוּ לְךָ לְבַדֶּךָ. אַתָּה לְבַדְּךָ תִּתְכַּבֵּד בָּהֶם, וְלֹא יַחֲלֹק אַחֵר עִמְּךָ. לְפִי שֶׁאָמַר לְמַעְלָה פֶּן יִשְׂבְּעוּ זָרִים כֹּחֶךָ, אָמַר כָּאן יִהְיוּ לְךָ לְבַדֶּךָ; וּמִתּוֹךְ כָּךְ:\",1,0],[2,135,5,18,\"יְהִי מְקוֹרְךָ בָרוּךְ וּשְׂמַח מֵאֵשֶׁת נְעוּרֶיךָ. הִיא הַתּוֹרָה שֶׁלָּמַדְתָּ מִנְּעוּרֶיךָ:\",1,0],[2,135,5,19,\"תִּשְׁגֶּה תָמִיד. רָאִיתִי בְּדִבְרֵי רַבִּי מֹשֶׁה הַדַּרְשָׁן: תִּשְׁגֶּה. תַּעֲסֹק תָּמִיד, וְהוּא לְשׁוֹן עֲרָבִי. וְהֵבִיא רְאָיָה, כְּמוֹ ׳לְבַקֵּשׁ שְׁגִייָה – לְבַקֵּשׁ עֵסֶק׳; וְלֹא יָדַעְתִּי אֵיפֹה נִשְׁנֵית. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (עירובין נד:): לְשׁוֹן ׳מַשְׁגֶּה׳ כְּמַשְׁמָעוֹ: בַּעֲבוּר אַהֲבָתָהּ תִּהְיֶה שׁוֹגֵג בִּשְׁאָר עֲסָקֶיךָ, כִּי הִיא מְשַׁמֶּרֶת עַל שֶׁלְּךָ. אָמְרוּ עָלָיו עַל רַבִּי אֱלִיעֶזֶר בֶּן פְּדָת, שֶׁהָיָה דּוֹרֵשׁ בַּשּׁוּק הַתַּחְתּוֹן, וְסְדִינוֹ מֻטָּל בַּשּׁוּק הָעֶלְיוֹן. פַּעַם אַחַת בָּא אָדָם אֶחָד וּמָצָא נָחָשׁ כָּרוּךְ עָלָיו:\",1,0],[2,135,5,21,\"כִּי נֹכַח עֵינֵי ה׳ דַּרְכֵי אִישׁ וְגוֹ׳ מְפַלֵּס. – שׁוֹקֵל דְּרָכָיו וְיוֹדֵעַ כַּמָּה עֲוֹנוֹת וְכַמָּה זְכֻיּוֹת בְּיָדוֹ:\",1,0],[2,135,5,22,\"עֲווֹנוֹתָיו יִלְכְּדֻנוֹ. כְּמוֹ יִלְכְּדוּהוּ:\",1,0],[2,135,5,22,\"וּבְחַבְלֵי חַטָּאתוֹ יִתָּמֵךְ. יִתָּלֶה, שֶׁהַתָּלוּי נִתְמָךְ בַּחֶבֶל שֶׁהוּא תָּלוּי בָּהּ:\",2,0],[2,135,5,23,\"הוּא יָמוּת בְּאֵין מוּסָר. בִּשְׁבִיל שֶׁלֹּא לָקַח מוּסָר:\",1,0],[2,135,6,1,\"בְּנִי אִם עָרַבְתָּ. עֲרֵבוּת מָמוֹן כְּמַשְׁמָעוֹ, פֵּרְשׁוּ רַבּוֹתֵינוּ (בבא בתרא קעג:):\",1,0],[2,135,6,2,\"נוֹקַשְׁתָּ בְאִמְרֵי פִיךָ. שֶׁתָּקַעְתָּ כַּף לְהִדָּבֵר עִם הַזָּרִים (יומא פז.):\",1,0],[2,135,6,3,\"לֵךְ הִתְרַפֵּס. הַתֵּר לוֹ פַּס יָד, לְשַׁלֵּם לוֹ מָמוֹנוֹ:\",1,0],[2,135,6,3,\"וּרְהַב רֵעֶיךָ. וְאִם אֵין לוֹ מָמוֹן עִמְּךָ, אֶלָּא שֶׁנּוֹקַשְׁתָּ בְּאִמְרֵי פִיךָ לְדַבֵּר לוֹ קָשׁוֹת, הַרְבֵּה עָלָיו רֵעִים לְבַקֵּשׁ מִמֶּנּוּ שֶׁיִּמְחוֹל לְךָ:\",2,0],[2,135,6,3,\"דָּבָר אַחֵר: בְּנִי אִם עָרַבְתָּ לְרֵעֶךָ. אַחַר שֶׁנַּעֲשֵׂיתָ עָרֵב לְהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא רֵעֲךָ, כְּדִכְתִיב ״זֶה דוֹדִי וְזֶה רֵעִי״ (שיר השירים ה:טז), וְקִבַּלְתָּ עָלֶיךָ בְּסִינַי וּבְעַרְבוֹת מוֹאָב בְּאָלָה וּבִשְׁבוּעָה לִשְׁמֹר מִצְווֹתָיו:\",3,0],[2,135,6,3,\"תָּקַעְתָּ לַזָּר כַּפֶּיךָ. שֶׁתָּשׁוּב וְתָסוּר מִדְּרָכָיו וְתִדְבַּק בָּאֶפִּיקוֹרְסִין לָלֶכֶת בְּדַרְכֵיהֶם:\",4,0],[2,135,6,3,\"נוֹקַשְׁתָּ בְּאִמְרֵי פִיךָ. שֶׁתָּקַעְתָּ כַּף לְהִדָּבֵר עִם הַזָּרִים:\",5,0],[2,135,6,3,\"עֲשֵׂה זֹאת אֵפוֹא בְּנִי וְהִנָּצֵל. הוֹאִיל וּבָאתָ בְכַף רֵעֶךָ בְּסִינַי, וְקִבַּלְתָּ אֱלֹהוּתוֹ עָלֶיךָ:\",6,0],[2,135,6,3,\"לֵךְ הִתְרַפֵּס. הִכָּנַע לְפָנָיו כַּאֲסְקוּפָּה הַנִּרְפֶּסֶת וְנִדְרֶסֶת:\",7,0],[2,135,6,3,\"וּרְהַב רֵעֶיךָ. הַרְבֵּה רֵעִים שֶׁיִּתְפַּלְּלוּ עָלֶיךָ לְפָנָיו. וְכֵן נִדְרַשׁ בְּמִדְרַשׁ תְּהִלִּים :\",8,0],[2,135,6,5,\"הִנָּצֵל כִּצְבִי מִיָּד. מַהֵר וְהִשָּׁמֵט מִשָּׁם כִּצְבִי הַנִּמְלָט מִיַּד הָאָדָם:\",1,0],[2,135,6,6,\"לֵךְ אֶל נְמָלָה עָצֵל וְגוֹ׳. וַחֲכָם – וְהִתְחַכֵּם:\",1,0],[2,135,6,7,\"אֲשֶׁר אֵין לָהּ קָצִין. שֶׁיּוֹכִיחַ אוֹתָהּ וִיזָרְזֶנָּה וְיוֹצִיא מִיָּדָהּ אִם תִּגְזֹל דָּבָר מֵחֲבֶרְתָּהּ, וְאַף עַל פִּי כֵן:\",1,0],[2,135,6,8,\"תָּכִין בַּקַּיִץ לַחְמָהּ אָגְרָה בַקָּצִיר מַאֲכָלָהּ. מְזוֹנָהּ, כָּל אַחַת וְאַחַת אֵינָהּ גּוֹזֶלֶת מֵחֲבֶרְתָּהּ:\",1,0],[2,135,6,10,\"חִבּוּק יָדַיִם. הַיָּשֵׁן חוֹבֵק יָדָיו, אַבְרַאצַ״ר בְּלַעַ״ז:\",1,0],[2,135,6,11,\"וּבָא כִמְהַלֵּךְ רֵאשֶׁךָ. אִם תַּעֲשֶׂה כֵּן יָבֹא חֶסְרוֹנְךָ, וְדָבָר שֶׁאַתָּה רָשׁ מִמֶּנּוּ יָבֹא לְךָ מִיָּד, כְּאָדָם הַמְהַלֵּךְ מַהֵר; וּמַחְסֹרְךָ יָבֹא וְיִתְמַלֵּא:\",1,0],[2,135,6,11,\"כְּאִישׁ מָגֵן. הַבָּא מַהֵר לְהָגֵן עַל אֲדוֹנָיו. הַמִּקְרָאוֹת אֵלּוּ – עִקָּרָן מָשָׁל עַל הַמִּתְעַצְּלִין לַעֲסֹק בַּתּוֹרָה:\",2,0],[2,135,6,12,\"הוֹלֵךְ עִקְּשׁוּת פֶּה. הַהוֹלֵךְ בַּעֲקִימַת שְׂפָתַיִם:\",1,0],[2,135,6,13,\"קוֹרֵץ בְּעֵינָיו. רְמִיזוֹת שֶׁל מִרְמָה:\",1,0],[2,135,6,13,\"מוֹלֵל בְּרַגְלָיו. כְּלוֹמַר: מְשַׁפְשֵׁף זֶה עַל זֶה:\",2,0],[2,135,6,13,\"וּמֹרֶה בְּאֶצְבְּעוֹתָיו. כֻּלָּם מִן לְשׁוֹן רְמָזִים הֵם, זֶה נוֹפֵל עַל הָעַיִן וְזֶה נוֹפֵל עַל הָרֶגֶל וְזֶה נוֹפֵל עַל הָאֶצְבַּע. וְהָעִקָּר – הוּא מְדַבֵּר עַל הָרְשָׁעִים הַמְּסִיתִין אֶת הַבְּרִיּוֹת לַעֲבוֹדָת גִּלּוּלִים:\",3,0],[2,135,6,14,\"מִדְיָנִים יְשַׁלֵּחַ. בֵּין אָדָם לְבוֹרְאוֹ:\",1,0],[2,135,6,15,\"פִּתְאוֹם. וּפֶתַע לְשׁוֹן תְּכִיפָה הִיא. וְלֹא יָדַע אֶת הַמַּפָּלָה הַקְּרוֹבָה לִפּוֹל עָלָיו:\",1,0],[2,135,6,16,\"שֵׁשׁ הֵנָּה שָׂנֵא ה׳ וְשֶׁבַע. תּוֹעֲבַת נַפְשׁוֹ, כְּלוֹמַר: גַּם הַשְּׁבִיעִית עִמָּהֶם:\",1,0],[2,135,6,19,\"יָפִיחַ. לְשׁוֹן דִּבּוּר הוּא, כִּי כָל דִּבּוּר בְּרוּחַ הַפֶּה הוּא:\",1,0],[2,135,6,20,\"נְצֹר בְּנִי מִצְוַת אָבִיךָ:\",1,0],[2,135,6,21,\"עָנְדֵם. לְשׁוֹן קֶשֶׁר הוּא, כְּמוֹ ״אֶעֶנְדֶנּוּ עֲטָרוֹת לִי״ (איוב לא:לו):\",1,0],[2,135,6,22,\"בְּהִתְהַלֶּכְךָ. בְּחַיֶּיךָ:\",1,0],[2,135,6,22,\"תַּנְחֶה אוֹתָךְ. כְּמוֹ תַּנְהִיגְךָ:\",2,0],[2,135,6,22,\"בְּשָׁכְבְּךָ. בַּקֶּבֶר:\",3,0],[2,135,6,22,\"וְהַקִיצוֹתָ הִיא תְשִׂיחֶךָ. לִתְחִיַּת הַמֵּתִים, לַעֲמֹד בַּדִּין:\",4,0],[2,135,6,22,\"הִיא תְשִׂיחֶךָ. תָּלִיץ בַּעֲדֶךָ (תנחומא, ויצא ב):\",5,0],[2,135,6,23,\"כִּי נֵר מִצְוָה וְתוֹרָה אוֹר. כְּמוֹ שֶׁהָאוֹר מֵאִיר לָעוֹלָם תָּמִיד, כָּךְ הַתּוֹרָה עוֹמֶדֶת זְכוּתָהּ לְעוֹלָם אֶל הָאָדָם; וּזְכוּת מִצְוָה לְפִי שָׁעָה, כְּאוֹר הַנֵּר. דָּבָר אַחֵר: כִּי נֵר מִצְוָה וְגוֹ׳ מִצְוַת הָאָב הוּא נֵר: כָּל מִי שֶׁמְּקַיֵּם מִצְוַת אָבִיו, כְּאִלּוּ נוֹטֵל נֵר בְּיָדוֹ לְהַדְלִיק בִּמְקוֹם חֹשֶׁךְ, וְאִם אָבַד שׁוּם דָּבָר, שָׁם הוּא מוֹצְאוֹ לְאוֹרוֹ. וְכֵן מִי שֶׁהוּא מְקַיֵּם הוֹרָאַת אִמּוֹ, אוֹרָה הִיא לוֹ; וְכֵן הוּא אוֹמֵר ״אַל תִּטֹּשׁ תּוֹרַת אִמֶּךָ״ (משלי א:ח). וְכֵן הוּא וַדַּאי, שֶׁמִּקְרָא זֶה מְדַבֵּר בְּמִצְוַת אָבִיו וְאִמּוֹ, דִּכְתִיב ״מְקַלֵּל אָבִיו וְאִמּוֹ יִדְעַךְ נֵרוֹ בֶּאֱשׁוּן חֹשֶׁךְ״ (משלי כ:כ). וְאִם נֵר שֶׁל אָדָם יִדְעַךְ (כּוֹהֶה) כְּשֶׁאֵין מְקַיֵּם מִצְוֹת, נִמְצָא כְּשֶׁמְּקַיֵּם מִצְוֹת, מֵאִיר נֵרוֹ (רבי יוסף קרא):\",1,0],[2,135,6,23,\"וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר. תּוֹכְחוֹת הַמּוּסָר הֵם מַטִּים אֶת הָאָדָם לְחַיִּים, נִמְצָא שֶׁהֵם דֶּרֶךְ הַחַיִּים:\",2,0],[2,135,6,24,\"לִשְׁמָרְךָ מֵאֵשֶׁת רָע. הַתּוֹרָה תִּשְׁמָרְךָ מֵאִשָּׁה שֶׁל מִנְהָג רָע. וְעַל כָּרְחֲךָ לֹא דִּבֵּר שְׁלֹמֹה אִשָּׁה רָעָה, אֶלָּא כְּנֶגֶד עֲבוֹדַת גִּלּוּלִים שֶׁהִיא שְׁקוּלָה כְּנֶגֶד הַכֹּל. שֶׁאִם תֹּאמַר: אִשָּׁה זוֹנָה מַמָּשׁ, וְכִי כָּל שְׂכָרָהּ וְשִׁבְחָהּ שֶׁל תּוֹרָה שֶׁשּׁוֹמֶרֶת מִן הַזּוֹנָה לְבַדָּהּ?! אֶלָּא עַל כָּרְחֲךָ זוֹ עֲבוֹדַת גִּלּוּלִים, שֶׁהִיא חֲמוּרָה כְּנֶגֶד הַכֹּל:\",1,0],[2,135,6,24,\"מֵחֶלְקַת לָשׁוֹן. מִטְּחוֹת עֵינַיִם שֶׁל לָשׁוֹן נָכְרִיָּה:\",2,0],[2,135,6,25,\"וְאַל תִּקָּחֲךָ. וְאַל תִּטּוֹל חָכְמָתְךָ מִמְּךָ בְּעַפְעַפֵּי עֵינֶיהָ, שֶׁקּוֹרֶצֶת בָּהֶם, בְּעַפְעַפֶּיהָ:\",1,0],[2,135,6,26,\"כִּי בְעַד אִשָּׁה זוֹנָה עַד כִּכַּר לָחֶם. לִידֵי עֲנִיּוּת וְחֹסֶר כָּל טוֹב:\",1,0],[2,135,6,26,\"נֶפֶשׁ יְקָרָה תָצוּד. נֶפֶשׁ שֶׁהָיְתָה יְקָרָה קוֹדֶם לָכֵן, בָּאָה וְצָדָה לְגֵיהִנֹּם (סוטה ד:):\",2,0],[2,135,6,27,\"הֲיַחְתֶּה אִישׁ. הֲיִשְׁאַב אִישׁ גֶּחָלִים בְּשִׁפּוּלֵי בְגָדָיו וְלֹא יִשָּׂרְפוּ?! כָּל לְשׁוֹן חֲתִיַּת גֶּחָלִים לְשׁוֹן שְׁאִיבָה הוּא כְּמַשְׁמָעָהּ: כְּשֶׁמְּמַלֵּא הַכְּלִי בְּתוֹךְ הַמְּדוּרָה:\",1,0],[2,135,6,29,\"אֶל אֵשֶׁת רֵעֵהוּ. כְּמַשְׁמָעוֹ. וְאַף עַל עֲבוֹדָת גִּלּוּלִים יֵשׁ לְדָרְשָׁהּ (שמות רבה לג:ז), שֶׁהִיא מְיֻחֶדֶת לַגּוֹיִם וְלֹא לְךָ:\",1,0],[2,135,6,30,\"לֹא יָבוּזוּ וְגוֹ׳ וְנִמְצָא יְשַׁלֵּם וְגוֹ׳ נֹאֵף אִשָּׁה וְגוֹ׳. שְׁלָשְׁתָּם מְחֻבָּרִים בְּדִבּוּר אֶחָד. אִם יִגְנֹב הַגַּנָּב גְּנֵבָה אֵין לְבַזּוֹתוֹ כָּל כָּךְ כְּמוֹ הַנּוֹאֵף, לָמָּה כִּי לְרַעֲבוֹן נַפְשׁוֹ הוּא עוֹשֶׂה וְאוּלַי אֵין לוֹ מַה יֹּאכַל, וּכְשֶׁנִּמְצָא יֵשׁ לוֹ תַּקָּנָה בְּתַשְׁלוּמִין, וּלְכָל הַיּוֹתֵר יְשַׁלֵּם שִׁבְעָתַיִם כְּלוֹמַר תַּשְׁלוּמֵי כֶּפֶל הַרְבֵּה וַאֲפִלּוּ חֲמִשִּׁים עַל אֶחָד, וְיֵשׁ מְפָרְשִׁים שִׁבְעָתַיִם כְּמוֹ גּוֹנֵב שׁוֹר וְכֵלָיו וּטְבָחוֹ שֶׁמְּשַׁלֵּם חֲמִשָּׁה בָקָר וְתַשְׁלוּמֵי כֶּפֶל עַל הַכֵּלִים (שמות כא:לז) הֲרֵי שִׁבְעָה: אֶת כָּל הוֹן בֵּיתוֹ יִתֵּן. וַאֲפִלּוּ צָרִיךְ לִמְכֹּר כָּל אֲשֶׁר לוֹ עַל זֶה מִכָּל מָקוֹם יֵשׁ לוֹ תַּקָּנָה וּמִתְּחִלָּה מֵחֲמַת רָעָב עָשָׂה, אֲבָל:\",1,0],[2,135,6,32,\"נוֹאֵף אִשָּׁה חֲסַר לֵב. הוּא, שֶׁהֲרֵי לֹא לְרַעֲבוֹן עָשָׂה:\",1,0],[2,135,6,32,\"מַשְׁחִית נַפְשׁוֹ הוּא יַעֲשֶׂנָּה. הַזִּמָּה:\",2,0],[2,135,6,33,\"נֶגַע וְקָלוֹן יִמְצָא. עַל עֲבוֹדַת גִּלּוּלִים וְעַל גִּלּוּי עֲרָיוֹת הַנְּגָעִים בָּאִים:\",1,0],[2,135,6,34,\"כִּי קִנְאָה. מִתְקַנֵּא בּוֹ לְהִפָּרַע בּוֹ חֲמָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא גִּבּוֹר עַל כֹּל, וְלֹא יַחְמוֹל בְּיוֹם נָקָם:\",1,0],[2,135,6,35,\"לֹא יִשָּׂא. פָּנִים, לְכָל מָמוֹן לְכַפֵּר עַל אֲשֶׁר כָּפַר בּוֹ וְנִדְבַּק בַּעֲבוֹדַת גִּלּוּלִים. וְרַבּוֹתֵינוּ דָּרְשׁוּ (תוספתא בבא קמא ז:יג): לֹא יָבוּזוּ לַגַּנָּב, זֶה הַמִּתְגַּנֵּב מֵאַחַר חֲבֵירוֹ הוֹלֵךְ לְבֵית הַמִּדְרָשׁ וְעוֹסֵק בַּתּוֹרָה, וְנִמְצָא יְשַׁלֵּם שִׁבְעָתַיִם, סוֹפוֹ שֶׁמִּתְמַנֶּה דַּיָּן וּמוֹרֶה הוֹרָאוֹת שֶׁאֵין שִׁבְעָתַיִם אֶלָּא תּוֹרָה שֶׁנֶּאֱמַר ״מְזֻקָּק שִׁבְעָתָיִם״ (תהלים יב:ז):\",1,0],[2,135,7,1,\"בני שמור אמרי ומצותי:\",1,0],[2,135,7,2,\"וְתוֹרָתִי כְּאִישׁוֹן עֵינֶיךָ. שָׁחוֹר שֶׁל עַיִן שֶׁהוּא דּוֹמֶה לַחֹשֶׁךְ, כְּמוֹ אִישׁוֹן לַיְלָה:\",1,0],[2,135,7,4,\"(אֲחוֹתִי אָתְּ. קָרְבֶנָּה אֵלֶיךָ):\",1,0],[2,135,7,4,\"וּמוֹדָע. קָרוֹב, כְּמוֹ ״בֹּעַז מוֹדַעְתֵּנוּ״ (רות ג:ב) – קְרוֹבֵנוּ. כְּלוֹמַר: קָרְבֶנָּה אֶצְלְךָ תָּמִיד:\",2,0],[2,135,7,7,\"אָבִינָה. הִבְחַנְתִּי וְרָאִיתִי:\",1,0],[2,135,7,8,\"אֵצֶל פִּנָּה. פִּנָּה שֶׁל זוֹנָה וַעֲבוֹדַת גִּלּוּלִים:\",1,0],[2,135,7,10,\"וְהִנֵּה אִשָּׁה. כְּמַשְׁמָעָהּ. דָּבָר אַחֵר: אֶחָד מִן אֶפִּיקוֹרְסִים:\",1,0],[2,135,7,10,\"שִׁית זוֹנָה. כְּמוֹ ״שְׁתוֹתֵיהֶם״ (שמואל ב י:ד), כְּלוֹמַר: עֶרְוַת זוֹנָה:\",2,0],[2,135,7,10,\"וּנְצוּרַת לֵב. כְּמוֹ ״עִיר נְצוּרָה״ (ישעיה א:ח) הַמּוּקֶּפֶת כַּרְכּוֹם, וְכֵן לִבָּהּ שֶׁל זוֹ מוּקֶּפֶת זִמָּה אִוֶּלֶת:\",3,0],[2,135,7,11,\"וְסוֹרָרֶת. סָרָה מִן הַדֶּרֶךְ:\",1,0],[2,135,7,14,\"זִבְחֵי שְׁלָמִים עָלָי. כְּלוֹמַר: סְעוּדָּה גְּדוֹלָה הֲכִינוֹתִי, כִּי הַיּוֹם הִקְרַבְתִּי נְדָרַי וּשְׁלָמַי:\",1,0],[2,135,7,15,\"וָאֶמְצָאֶךָּ. כְּדֵי שֶׁאֶמְצָאֶךָּ:\",1,0],[2,135,7,16,\"מַרְבַּדִּים. בִּגְדֵי חֹפֶשׁ וְנוֹי, וְדֻגְמָתוֹ בְּסוֹף הַסֵּפֶר, שֶׁנֶּאֱמַר ״מַרְבַדִּים עָשְׂתָה לָּהּ״ (משלי לא:כב):\",1,0],[2,135,7,16,\"רָבַדְתִּי עַרְשִׂי. קִשַּׁטְתִּי:\",2,0],[2,135,7,16,\"חֲטוּבוֹת אֵטוּן מִצְרָיִם. מְהֻלָּלוֹת בִּגְדֵי כְּלֵי פִשְׁתָּן חֲשׁוּבִין הַבָּאִים מִמִּצְרַיִם, שֶׁשָּׁם הַפִּשְׁתָּן מָצוּי, כְּדִכְתִיב בְּסֵפֶר (ישעיהו יט:ט) ״וּבֹשׁוּ עֹבְדֵי פִשְׁתִּים״. אֵטוּן תַּרְגּוּם ״מֵיתְרֵיהֶם״ (שמות לה:יח) ״אֲטוּנֵיהוֹן״:\",3,0],[2,135,7,17,\"נַפְתִּי מִשְׁכָּבִי. הֲנִיפוֹתִי הָרֵיחַ, כְּמֵנִיף בְּסוּדָר בְּבֵית הַבֹּשֶׂם, לְהָבִיא הָרֵיחַ מִלְמַעְלָה לְמַטָּה. וְדוּנָשׁ פֵּרֵשׁ לְשׁוֹן קִטּוּר, וְאָמַר שֶׁאֵין לוֹ דִּמְיוֹן:\",1,0],[2,135,7,19,\"כִּי אֵין הָאִישׁ בְּבֵיתוֹ. רְאִיתֶם שֶׁסִּלֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁכִינָתוֹ, וְכָל טוֹב נָתַן לְעוֹבְדֵי גִּלּוּלִים:\",1,0],[2,135,7,20,\"צְרוֹר הַכֶּסֶף. הַטּוֹבִים שֶׁבָּהֶם הָרַג:\",1,0],[2,135,7,20,\"לְיוֹם הַכֵּסֶא. לִזְמַן הַמּוֹעֵד הַקָּבוּעַ, וְכֵן ״בַּכֶּסֶה לְיוֹם חַגֵּנוּ״ (תהלים פא:ד):\",2,0],[2,135,7,21,\"הִטַּתּוּ. לְאוֹתוֹ חֲסַר לֵב (משלי ז:ז) אֵלֶיהָ:\",1,0],[2,135,7,21,\"בְּרֹב לִקְחָהּ. שֶׁהִיא לְמוּדָה לְהַרְגִּיל בְּכָךְ אֲנָשִׁים:\",2,0],[2,135,7,21,\"בְּחֵלֶק שְׂפָתֶיהָ. בְּדִבּוּר חֲלַקְלַק תַּדִּיחֶנּוּ מִן הַדֶּרֶךְ:\",3,0],[2,135,7,22,\"וּכְעֶכֶס. זֶה אֶרֶס נָחָשׁ:\",1,0],[2,135,7,22,\"אֶל מוּסַר אֱוִיל. כְּנָחָשׁ הַמְּמַהֵר לָרוּץ בִּשְׁלִיחוּת הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַסֵּר הָאֱוִיל, הַמְחֻיָּב לַמָּקוֹם בָּרוּךְ הוּא, כֵּן זֶה רָץ אַחֲרֶיהָ עַד שֶׁנִּכְשַׁל בָּהּ, וַיְפַלַּח חִצָּהּ אֶת כְּבֵדוֹ:\",2,0],[2,135,7,23,\"כְּמַהֵר צִפּוֹר. לָרוּץ אֶל הַפַּח, וְאֵינוֹ יוֹדֵעַ כִּי הַפַּח נִפְרַשׂ שָׁם בְּנַפְשׁוֹ שֶׁל צִפּוֹר:\",1,0],[2,135,7,24,\"וְעַתָּה בָנִים שִׁמְעוּ לִי וְגוֹ׳:\",1,0],[2,135,8,1,\"הֲלֹא חָכְמָה תִקְרָא. הֲלֹא הַתּוֹרָה מַכְרֶזֶת אֲלֵיכֶם דְּבָרִים הָאֲמוּרִים לְמַטָּה בָּעִנְיָן:\",1,0],[2,135,8,3,\"לְפִי קָרֶת. תִּקְרָה הַנְּתוּנָה עַל הַשַּׁעַר, וְיוֹשְׁבִים עָלֶיהָ:\",1,0],[2,135,8,3,\"תָּרֹנָּה. תִּזְעַקְנָה. וּמָה הִיא אוֹמֶרֶת? אֲלֵיכֶם אִישִׁים אֶקְרָא:\",2,0],[2,135,8,6,\"שִׁמְעוּ כִּי נְגִידִים אֲדַבֵּר. דִּבְרֵי נְגִידוּת וַחֲשִׁיבוּת:\",1,0],[2,135,8,8,\"נִפְתָּל וְעִקֵּשׁ. עַקְמוּמִיּוּת:\",1,0],[2,135,8,10,\"מֵחָרוּץ. מִמִּינֵי הַזָּהָב הוּא:\",1,0],[2,135,8,11,\"מִפְּנִינִים. מַרְגָּלִיּוֹת:\",1,0],[2,135,8,11,\"לֹא יִשְׁווּ בָהּ. לֹא יִדְמוּ לְשָׁוְיָהּ:\",2,0],[2,135,8,12,\"שָׁכַנְתִּי עָרְמָה. אֵצֶל עָרְמָה, שֶׁכֵּיוָן שֶׁלָּמַד אָדָם תּוֹרָה, נִכְנַס בּוֹ עַרְמִימוּת שֶׁל כָּל דָּבָר (סוטה כא:):\",1,0],[2,135,8,13,\"יִרְאַת ה׳ שְׂנֹאת רָע. זֶהוּ הַמּוּסָר שֶׁהַחָכְמָה מַכְרֶזֶת לַבְּרִיּוֹת:\",1,0],[2,135,8,15,\"בִּי מְלָכִים יִמְלֹכוּ. שֶׁהַדִּינִים וְהַמִּשְׁפָּטִים אֲנִי מְלַמְּדָם:\",1,0],[2,135,8,17,\"אֵהַב. כְּמוֹ אֶאֱהַב:\",1,0],[2,135,8,17,\"אֹהֲבַי. אֹהֲבֶיהָ כְּתִיב, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: אֲנִי אֹהֲבֶיהָ שֶׁל תּוֹרָה אֵהָב. זוֹ שָׁמַעְתִּי מֵרַבִּי אַהֲרֹן, בְּשֵׁם רַבִּי נָתָן:\",2,0],[2,135,8,17,\"יִמְצָאֻנְנִי. נוּ״ן יְתֵרָה: חֲמִשִּׁים שַׁעֲרֵי בִינָה אַמְצִיאֶנּוּ:\",3,0],[2,135,8,21,\"לְהַנְחִיל אוֹהֲבַי יֵשׁ. יֵשׁ אִתִּי נַחֲלָה רַבָּה:\",1,0],[2,135,8,22,\"רֵאשִׁית דַּרְכּוֹ. קוֹדֶם בְּרִיאָתוֹ שֶׁל עוֹלָם (פסחים נד.):\",1,0],[2,135,8,23,\"נִסַּכְתִּי מֵרֹאשׁ. לְשׁוֹן נְסִיכֵי בְּנֵי אָדָם (מיכה ה:ד):\",1,0],[2,135,8,24,\"חוֹלָלְתִּי. נִבְרֵאתִי:\",1,0],[2,135,8,25,\"בְּטֶרֶם הָרִים הָטְבָּעוּ. בְּתוֹךְ הַמָּיִם:\",1,0],[2,135,8,26,\"אֶרֶץ וְחוּצוֹת. אֶרֶץ יִשְׂרָאֵל וּשְׁאָר אֲרָצוֹת (תענית י.):\",1,0],[2,135,8,26,\"וְרֹאשׁ עַפְרוֹת תֵּבֵל. אָדָם הָרִאשׁוֹן (סנהדרין לח.):\",2,0],[2,135,8,27,\"בְּחֻקּוֹ חוּג עַל פְּנֵי תְהוֹם. כְּשֶׁרָקַע חוּג הָאָרֶץ עַל הַמַּיִם, חֹק גְּבוּל בַּל יַעֲבֹר:\",1,0],[2,135,8,27,\"חוּג. לְשׁוֹן הֶקֵּף, כְּמוֹ ״וּבַמְּחוּגָה יְתָאֲרֵהוּ״ (ישעיה מד:יג). קוֹנְפָּא״שׁ בְּלַעַ״ז:\",2,0],[2,135,8,28,\"בַּעֲזוֹז. כְּשֶׁהִגְבִּיר מַעְיְנוֹת תְּהוֹם:\",1,0],[2,135,8,29,\"בְּשׂוּמוֹ לַיָּם חֻקּוֹ. וְגָזַר עַל יַם סוּף כְּשֶׁבְּרָאוֹ, עַל מְנָת לְהִבָּקַע לִפְנֵי מֹשֶׁה (שמות יד:כא):\",1,0],[2,135,8,29,\"בְּחֻקּוֹ מוֹסְדֵי אָרֶץ. בְּחִקָּתוֹ, מִלְּשׁוֹן חֻקּוֹ; כְּמוֹ ״עַל כַּפַּיִם חַקֹּתִיךְ״ (ישעיה מט:טז); וְכֵן ״וּמֵחֵיק הָאָרֶץ״ (יחזקאל מג:יד):\",2,0],[2,135,8,30,\"אָמוֹן. גְּדֵלָה אֶצְלוֹ, לְשׁוֹן ״הָאֲמוּנִים עֲלֵי תוֹלָע״ (איכה ד:ה):\",1,0],[2,135,8,30,\"יוֹם יוֹם. אַלְפַּיִם שָׁנָה (תהלים צ:ד; ויקרא רבה יט:א):\",2,0],[2,135,8,31,\"מְשַׂחֶקֶת בְּתֵבֵל אַרְצוֹ. כָּל דּוֹרוֹת הָרְשָׁעִים שֶׁהָיוּ מֵאָדָם וְעַד נֹחַ וּמִנֹּחַ וְעַד אַבְרָהָם הָיִיתִי מְשַׂחֶקֶת עֲלֵיהֶם:\",1,0],[2,135,8,31,\"וְשַׁעֲשֻׁעַי. צָפִיתִי עַד בֹּא דּוֹר הַמִּדְבָּר וִיקַבְּלוּנִי:\",2,0],[2,135,8,32,\"וְעַתָּה בָנִים שִׁמְעוּ לִי:\",1,0],[2,135,8,33,\"וְאַל תִּפְרָעוּ. וְאַל תְּבַטְּלוּ מוּסָרִי:\",1,0],[2,135,8,34,\"לִשְׁקֹד. לִשְׁמֹר:\",1,0],[2,135,8,34,\"עַל דַּלְתוֹתַי. לְהִכָּנֵס רִאשׁוֹן לְבֵית הַמִּדְרָשׁ וּלְבֵית הַכְּנֶסֶת וְלָצֵאת אַחֲרוֹן:\",2,0],[2,135,9,1,\"חָכְמוֹת בָּנְתָה בֵיתָהּ. בְּחָכְמָה בָּנָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם:\",1,0],[2,135,9,1,\"חָצְבָה עַמּוּדֶיהָ שִׁבְעָה. שִׁבְעַת יְמֵי בְרֵאשִׁית. דָּבָר אַחֵר: שִׁבְעָה סְפָרִים שֶׁיֵּשׁ בַּתּוֹרָה – ״וַיְהִי בִּנְסֹעַ הָאָרֹן״ (במדבר י:לה) סֵפֶר לְעַצְמוֹ; בְּמַסֶּכֶת שַׁבָּת (שבת קטז.):\",2,0],[2,135,9,2,\"טָבְחָה טִבְחָהּ מָסְכָה יֵינָהּ. מְזָגָם בְּמַיִם, כְּמוֹ יַיִן חָזָק שֶׁאֵינוֹ רָאוּי לִשְׁתּוֹת חַי:\",1,0],[2,135,9,2,\"אַף עָרְכָה שֻׁלְחָנָהּ. כָּל יְצִירַת לַח וְיָבֵשׁ:\",2,0],[2,135,9,3,\"שָׁלְחָה נַעֲרוֹתֶיהָ. אָדָם וְחַוָּה (סנהדרין לח.), דָּבָר אַחֵר: מֹשֶׁה וְאַהֲרֹן (ויקרא רבה א,ד):\",1,0],[2,135,9,4,\"מִי פֶתִי יָסוּר הֵנָּה. וְיִלְמַד אוֹתִי וְיֶחְכַּם:\",1,0],[2,135,9,5,\"לְכוּ לַחֲמוּ בְלַחֲמִי וּשְׁתוּ בְּיַיִן מָסָכְתִּי. בְּיַיִן שֶׁמָּזַגְתִּי:\",1,0],[2,135,9,6,\"עִזְבוּ פְתָאיִם וִחְיוּ. אֶת דֶּרֶךְ הַפַּתְיוּת:\",1,0],[2,135,9,6,\"וְאִשְׁרוּ. לְשׁוֹן פַּעַם, כְּמוֹ ״בַּאֲשֻׁרוֹ אָחֲזָה רַגְלִי״ (איוב כג:יא):\",2,0],[2,135,9,7,\"וּמוֹכִיחַ לְרָשָׁע מוּמוֹ. מוּם הוּא לַמּוֹכִיחַ, שֶׁזֶּה מְחָרְפוֹ וְאֵינוֹ שׁוֹמֵעַ לוֹ. זוֹ הִיא אַזְהָרָה שֶׁאָסוּר לְדַבֵּר עִם הַמְּסִיתִים מִדֶּרֶךְ הַיְשָׁרָה, אֲפִלּוּ לְהוֹכִיחָם וּלְקָרְבָם:\",1,0],[2,135,9,9,\"תֵּן לְחָכָם וְיֶחְכַּם עוֹד. לְתַלְמִיד הָגוּן שְׁנֵה. וּמִדְרַשׁ אַגָּדָה (שמות רבה נ:ב): נֶאֱמַר לְנֹחַ ״מִכָּל הַבְּהֵמָה הַטְּהוֹרָה וְגוֹ׳״ (בראשית ז:ב), וּכְשֶׁיָּצָא ״וַיִּקַּח מִכָּל הַבְּהֵמָה וְגוֹ׳״ (בראשית ח:כ). אָמַר: מָה רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַרְבּוֹת בְּאֵלּוּ? אֶלָּא שֶׁרָצָה שֶׁאַקְרִיב לוֹ מֵהֶן:\",1,0],[2,135,9,9,\"הוֹדַע לְצַדִּיק. חָכְמָה וְהוּא יוֹסֶף לֶקַח. מִדַּעְתּוֹ וְעַל שְׁמוּעָתוֹ:\",2,0],[2,135,9,10,\"תְּחִלַּת חָכְמָה יִרְאַת ה׳, וְדַעַת קְדוֹשִׁים. הִיא עִקַּר הַבִּינָה:\",1,0],[2,135,9,11,\"וְיוֹסִיפוּ לְךָ שְׁנוֹת חַיִּים. שָׁנִים שֶׁל חַיִּים הֵם שֶׁל פַּרְנָסָה וְעֹשֶׁר:\",1,0],[2,135,9,16,\"חֲסַר לֵב, וְאָמְרָה לּוֹ. הַדְּבָרִים הַלָּלוּ, מָה אָמְרָה לוֹ:\",1,0],[2,135,9,17,\"מַיִם גְּנוּבִים יִמְתָּקוּ. אֵין טַעַם בִּיאַת פְּנוּיָה כְּטַעַם אֵשֶׁת אִישׁ. אַף לְעִנְיַן הַמִּצְוָה, מַיִם גְּנוּבִים יִמְתָּקוּ. שֶׁהָיוּ יְרֵאִים לַעֲשׂוֹת בְּגָלוּי וְעוֹשִׂין בְּסֵתֶר:\",1,0],[2,135,10,1,\"מִשְׁלֵי שְׁלֹמֹה בֵּן חָכָם יְשַׂמַּח אָב. זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא (מדרש משלי י:א). דָּבָר אַחֵר: אָבִיו מַמָּשׁ:\",1,0],[2,135,10,1,\"וּבֵן כְּסִיל תּוּגַת אִמּוֹ. תָּמִיד הוּא עִם אִמּוֹ בַּבַּיִת, וְרוֹאָה אֶת שְׁטוּתוֹ וּמְצֵרָה. וּלְפִי הַמָּשָׁל: בֵּן כְּסִיל כְּמוֹ יָרָבְעָם בֶּן נְבָט (ברכות לה:):\",2,0],[2,135,10,1,\"תּוּגַת אִמּוֹ. תּוּגַת כְּנִסִיּוֹתוֹ:\",3,0],[2,135,10,2,\"לֹא יוֹעִילוּ אוֹצְרוֹת רֶשַׁע. שֶׁהָיָה מִשְׁתַּבֵּחַ בְּעָשְׁרוֹ, שֶׁנֶּאֱמַר: ״וַיֹּאמֶר אֶפְרַיִם אַךְ עָשַׁרְתִּי וְגוֹמֵר״ (הושע יב:ט):\",1,0],[2,135,10,2,\"וּצְדָקָה תַּצִּיל מִמָּוֶת. וְאִם תֹּאמַר: צַדִּיק שֶׁיְּבַזְבֵּז נְכָסָיו לִצְדָקָה, מֵהֵיכָן יִתְפַּרְנֵס?\",2,0],[2,135,10,3,\"לֹא יַרְעִיב ה׳ נֶפֶשׁ צַדִּיק, וְהַוַּת רְשָׁעִים יֶהְדֹּף. יִדְחוֹף אוֹתָם וְתִפּוֹל:\",1,0],[2,135,10,4,\"רָאשׁ עֹשֶׂה כַף רְמִיָּה. מִי שֶׁעָנִי בַּתּוֹרָה, מוֹרֶה הוֹרָאוֹת שֶׁקֶר:\",1,0],[2,135,10,4,\"כַּף רְמִיָּה. מֹאזְנַיִם שֶׁל רְמִיָּה. לְפִי פְּשׁוּטוֹ מַשְׁמַע בַּתַּגָּרִים:\",2,0],[2,135,10,4,\"וְיַד חָרוּצִים. יְשָׁרִים, שֶׁחוֹרְצִים דָּבָר בַּאֲמִתּוֹ וּמִשְׁפָּטוֹ בְּלֹא עַוְלָה:\",3,0],[2,135,10,6,\"וּפִי רְשָׁעִים יְכַסֶּה חָמָס. הֶחָמָס יְכַסֶּה עַל פִּיהֶם וְיַהַרְגֵם:\",1,0],[2,135,10,7,\"זֵכֶר צַדִּיק לִבְרָכָה. הַמַּזְכִּיר צַדִּיק מְבָרְכוֹ:\",1,0],[2,135,10,7,\"וְשֵׁם רְשָׁעִים יִרְקָב. רִקָּבוֹן עוֹלֶה בִּשְׁמָם, שֶׁאֵין אָדָם חָפֵץ לְהַזְכִּיר שְׁמוֹ וְהוּא מִשְׁתַּכֵּחַ מֵאֵלָיו (יומא לח:):\",2,0],[2,135,10,8,\"חֲכַם לֵב יִקַּח מִצְוֺת. מֹשֶׁה רַבֵּינוּ, שֶׁכָּל יִשְׂרָאֵל הָיוּ עוֹסְקִין בְּבִזַּת מִצְרַיִם, וְהוּא הָיָה עוֹסֵק בְּמִצְוֹת, שֶׁנֶּאֱמַר ״וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף וְגוֹ׳״ (שמות יג:יט):\",1,0],[2,135,10,8,\"וֶאֱוִיל שְׂפָתַיִם יִלָּבֵט. לְשׁוֹן יְגִיעָה. וְיֵשׁ בְּסִפְרֵי בְּפָרָשָׁה ״וַיְהִי הָעָם כְּמִתְאֹנְנִים״ (במדבר יא:א): אָמְרוּ: כַּמָּה נִתְלַבַּטְנוּ בַדֶּרֶךְ:\",2,0],[2,135,10,9,\"וּמְעַקֵּשׁ דְּרָכָיו יִוָּדֵעַ. יִשָּׁבֵר וְיִתְיַסֵּר, כְּמוֹ ״וַיֹּדַע בָּהֶם אֶת אַנְשֵׁי סֻכּוֹת״ (שופטים ח:טז):\",1,0],[2,135,10,10,\"קוֹרֵץ עַיִן יִתֵּן עַצָּבֶת. זֶה הַמֵּסִית אָדָם בִּקְרִיצוֹתָיו לְרָעָה:\",1,0],[2,135,10,11,\"מְקוֹר חַיִּים פִּי צַדִּיק וּפִי רְשָׁעִים וְגוֹ׳. פִּיהֶם יְכַסֶּה חָמָס שֶׁבְּלִבָּם, שֶׁמַּחֲלִיקִין אֶת שִׂפְתֵיהֶם וְשִׂנְאָה טְמוּנָה בְּלִבָּם. וְאֵין פִּתְרוֹן מִקְרָא זֶה דּוֹמֶה לְפִתְרוֹן הָעֶלְיוֹן (משלי י:ו), וְהָעִנְיָן יוֹרֶה עֲלֵיהֶם:\",1,0],[2,135,10,12,\"שִׂנְאָה תְּעוֹרֵר מְדָנִים. אֲפִלּוּ עֲבֵרָה שֶׁנִּתְּנָה לְשִׁכְחָה נִזְכֶּרֶת עַל יְדֵי מַרְבִּית עֲוֹנוֹת; בָּאָה שִׂנְאָה אַחֲרוֹנָה וּמְעוֹרֶרְתָּן. שֶׁכֵּן יְחֶזְקֵאל הוֹכִיחַ אֶת יִשְׂרָאֵל עַל עֲבֵרוֹת מִצְרַיִם: ״וָאֹמַר אֲלֵהֶם אִישׁ אֶת שִׁקּוּצֵי עֵינָיו הַשְׁלִיכוּ וְגוֹ׳״ (יחזקאל כ:ז) – כַּמָּה שָׁנִים הָיְתָה שִׂנְאָה זוֹ כְּבוּשָׁה וְלֹא הִזְכִּירָהּ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד עַכְשָׁו, שֶׁהִרְבּוּ עֲבֵרוֹת עַל פִּשְׁעֵיהֶם (ויקרא רבה ז:א):\",1,0],[2,135,10,12,\"וְעַל כָּל פְּשָׁעִים תְּכַסֶּה אַהֲבָה. כְּשֶׁיִּשְׂרָאֵל מֵטִיבִים מַעֲשֵׂיהֶם, הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַסֶּה עַל פְּשָׁעֵיהֶם:\",2,0],[2,135,10,13,\"בְּשִׂפְתֵי נָבוֹן תִּמָּצֵא חָכְמָה. כְּשֶׁאָדָם מוֹכִיחַ לְנָבוֹן, מֵשִׁיב לוֹ: חָטָאתִי! כְּגוֹן דָּוִד שֶׁאָמַר לְנָתָן: ״חָטָאתִי״ (שמואל ב יב:יג):\",1,0],[2,135,10,13,\"וְשֵׁבֶט לְגֵו חֲסַר לֵב. אֲבָל חֲסַר לֵב אֵינוֹ שׁוֹמֵעַ עַד שֶׁיִּלְקֶה, כְּמוֹ פַּרְעֹה (שמות ז:יד-יא:י):\",2,0],[2,135,10,14,\"חֲכָמִים יִצְפְּנוּ דָעַת. יִשְׁמְרוּהוּ בְּלִבָּם, שֶׁלֹּא יִשְׁכָּחוּהוּ:\",1,0],[2,135,10,15,\"הוֹן עָשִׁיר. בַּתּוֹרָה:\",1,0],[2,135,10,15,\"קִרְיַת עֻזּוֹ. הִיא לוֹ:\",2,0],[2,135,10,15,\"מְחִתַּת דַּלִּים רֵישָׁם. עֲנִיּוּתָם, שֶׁלֹּא עָסְקוּ בַּתּוֹרָה, הִיא מְחִתָּתָם:\",3,0],[2,135,10,16,\"פְּעֻלַּת צַדִּיק לְחַיִּים. כְּמַשְׁמָעוֹ. וּמִדְרַשׁ אַגָּדָה (דברים רבה ב:כ): שְׁלֹמֹה עָשָׂה פְּעֻלַּת הַמִּקְדָּשׁ לְחַיֵּיהֶם שֶׁל יִשְׂרָאֵל, לְכַפָּרָתָן:\",1,0],[2,135,10,16,\"וּתְּבוּאַת רָשָׁע. תְּבוּאָתוֹ (  הֲבָאָתוֹ) שֶׁל מְנַשֶּׁה (דברי הימים ב לג:ז), שֶׁהִכְנִיס בּוֹ הַסֶּמֶל, הִיא הָיְתָה לְחַטָּאת:\",2,0],[2,135,10,17,\"אֹרַח לְחַיִּים. הַשּׁוֹמֵר מוּסָר הִיא הַדֶּרֶךְ לְחַיִּים:\",1,0],[2,135,10,17,\"וְעוֹזֵב תּוֹכַחַת מַתְעֶה. אֶת עַצְמוֹ וְאֶת אֲחֵרִים:\",2,0],[2,135,10,18,\"מְכַסֶּה שִׂנְאָה שִׂפְתֵי שָׁקֶר. הֶחָנֵף שְׂפָתָיו שֶׁקֶר, וּמְכַסֶּה שִׂנְאָה בְּלִבּוֹ:\",1,0],[2,135,10,18,\"וּמוֹצִיא דִבָּה הוּא כְסִיל. לַעַז, שֶׁיִּהְיוּ אֲנָשִׁים דּוֹבְבִין בּוֹ עַל חֲבֵירוֹ:\",2,0],[2,135,10,19,\"בְּרֹב דְּבָרִים לֹא יֶחְדַּל פָּשַׁע. הַמַּרְבֶּה דְבָרִים מֵבִיא חֵטְא:\",1,0],[2,135,10,19,\"וְחוֹשֵׂךְ שְׂפָתָיו. הוּא הַמַּשְׂכִּיל:\",2,0],[2,135,10,20,\"כֶּסֶף נִבְחָר לְשׁוֹן צַדִּיק. שֶׁיּוֹדֵעַ לְהוֹכִיחַ:\",1,0],[2,135,10,20,\"לֵב רְשָׁעִים כִּמְעָט. שֶׁאֵינוֹ שׁוֹמֵעַ לְתוֹכַחַת צַדִּיק. וּמִדְרַשׁ רַבִּי תַּנְחוּמָא אוֹמֵר (תנחומא, כי תשא ו): עַל עִדּוֹ הַנָּבִיא נֶאֱמַר, שֶׁקָּרָא עַל הַמִּזְבֵּחַ בְּבֵית אֵל; וְיָרָבְעָם, אַף עַל פִּי שֶׁיָּבְשָׁה יָדוֹ, לֹא קִבֵּל תּוֹכֵחָה, שֶׁנֶּאֱמַר ״חַל נָא אֶת פְּנֵי ה׳ אֱלֹהֶיךָ וְגוֹ׳״ (מלכים א יג:ו) וְלֹא ׳אֱלֹהַי׳; וְאוֹמֵר ״וַתָּשָׁב יָדוֹ כְּבָרִאשֹׁנָה״ (מלכים א יג:ו) – עוֹמֵד וּמַקְטִיר לַעֲבוֹדַת גִּלּוּלִים, וְאַף בַּסּוֹף כֵּן:\",2,0],[2,135,10,21,\"שִׂפְתֵי צַדִּיק יִרְעוּ רַבִּים וְגוֹ׳. שֶׁרַבִּים אוֹכְלִים בִּזְכוּתוֹ וּבִתְפִלָּתוֹ:\",1,0],[2,135,10,22,\"בִּרְכַּת ה׳ הִיא תַעֲשִׁיר, וְלֹא יוֹסִיף עֶצֶב עִמָּהּ. אֵין צָרִיךְ לְהִתְיַגֵּעַ לְהַעֲשִׁיר בּוֹ, דַּי בַּבְּרָכָה מַה שֶּׁהוּא מְבָרְכוֹ:\",1,0],[2,135,10,23,\"כְּשְׂחוֹק לִכְסִיל עֲשׂוֹת זִמָּה. עֲצַת חַטָּאִים:\",1,0],[2,135,10,23,\"וְחָכְמָה כִּשְׂחוֹק לְאִישׁ תְּבוּנָה. כְּלוֹמַר: קַלָּה הִיא בְּעֵינָיו לַעֲשׂוֹת:\",2,0],[2,135,10,24,\"מְגוֹרַת רָשָׁע. מַה שֶּׁהוּא יָרֵא יָבֹא לוֹ. דּוֹר הַפְּלַגָּה יָרְאוּ וְאָמְרוּ ״פֶּן נָפוּץ״ (בראשית יא:ד), וְסוֹפָן כְּתִיב ״וַיָּפֶץ ה׳ אֹתָם מִשָּׁם״ (בראשית יא:ח):\",1,0],[2,135,10,24,\"וְתַאֲוַת צַדִּיקִים יִתֵּן. מִי שֶׁבְּיָדוֹ לִתְּנָהּ (לָתֵת):\",2,0],[2,135,10,25,\"כַּעֲבוֹר סוּפָה וְאֵין רָשָׁע. פִּתְאוֹם בָּא עֶבְרַת רוּחַ סְעָרָה, נִכְרַת הָרָשָׁע מִמְּקוֹמוֹ:\",1,0],[2,135,10,28,\"תּוֹחֶלֶת צַדִּיקִים שִׂמְחָה. סוֹפָהּ מִתְקַיֶּמֶת וּשְׂמֵחִים:\",1,0],[2,135,10,28,\"וְתִקְוַת רְשָׁעִים תֹּאבֵד. כִּי לֹא תָבֹא:\",2,0],[2,135,10,29,\"מָעוֹז לַתֹּם דֶּרֶךְ ה׳ וּמְחִתָּה. הִיא לְפוֹעֲלֵי אָוֶן שֶׁאֵינָן הוֹלְכִין בָּהּ, וְהִיא נִפְרַעַת מֵהֶם:\",1,0],[2,135,10,30,\"צַדִּיק לְעוֹלָם בַּל יִמּוֹט. כְּשֶׁהוּא מָט אֵין מוֹטָתוֹ מוֹטַת עוֹלָם, כִּי יִפּוֹל וְקָם (משלי כד:טז):\",1,0],[2,135,10,31,\"פִּי צַדִּיק יָנוּב חָכְמָה. יְדַבֵּר, לְשׁוֹן ״נִיב שְׂפָתָיִם״ (ישעיהו נז:יט):\",1,0],[2,135,10,32,\"שִׂפְתֵי צַדִּיק יֵדְעוּן רָצוֹן. יוֹדְעִים לְרַצּוֹת וּלְפַיֵּס אֶת בּוֹרְאָם, וְיוֹדְעִים לְרַצּוֹת אֶת הַבְּרִיּוֹת וּלְהַטִּיל שָׁלוֹם בֵּינֵיהֶם:\",1,0],[2,135,11,2,\"בָּא זָדוֹן וַיָּבֹא קָלוֹן וְאֶת צְנוּעִים חָכְמָה. תָּבוֹא חָכְמָה:\",1,0],[2,135,11,3,\"תֻּמַּת יְשָׁרִים תַּנְחֵם. תַּנְהֲלֵם:\",1,0],[2,135,11,3,\"וְסֶלֶף בּוֹגְדִים יְשָׁדֵּם. יְשָׁדְדֵם:\",2,0],[2,135,11,6,\"צִדְקַת יְשָׁרִים תַּצִּילֵם וּבְהַוַּת בֹּגְדִים יִלָּכֵדוּ. בַּהַוּוֹת שֶׁהֵם עוֹשִׂים הֵם נִלְכָּדִים. וְהַמִּקְרָא מְסֹרָס הוּא, כְּלוֹמַר: וּבוֹגְדִים בְּהַוַּת יִלָּכֵדוּ:\",1,0],[2,135,11,7,\"בְּמוֹת אָדָם רָשָׁע תֹּאבַד תִּקְוָה. תִּקְוַת כָּל הַבּוֹטְחִים בּוֹ:\",1,0],[2,135,11,7,\"וְתוֹחֶלֶת אוֹנִים אָבָדָה. תּוֹחֶלֶת בָּנָיו, שֶׁהֵם אוֹנוֹ, אָבְדָה, כִּי בִּזְכוּתוֹ לֹא תָבוֹא לָהֶם טוֹבָה. אֲבָל בְּמוֹת צַדִּיקִים יֵשׁ לִבְנֵיהֶם מִבְטָח בְּצִדְקָתָם:\",2,0],[2,135,11,8,\"צַדִּיק מִצָּרָה נֶחֱלָץ. בְּמוֹת רָשָׁע, וְלַמִּקְרָא הָעֶלְיוֹן (משלי יא:ז) זֶה מְחֻבָּר:\",1,0],[2,135,11,9,\"בְּפֶה חָנֵף. חָנֵף הַמֵּסִית חֲבֵרוֹ בְּדֶרֶךְ רַע, מַשְׁחִיתוֹ בְּפִיו:\",1,0],[2,135,11,9,\"וּבְדַעַת צַדִּיקִים יֵחָלֵצוּ. וְהַצַּדִּיק נֶחֱלָץ מִמֶּנּוּ בְּדַעַת הַתּוֹרָה, שֶׁהִזְהִירָה עָלָיו ״לֹא תֹאבֶה לוֹ וְגוֹ׳״ (דברים יג:ט):\",2,0],[2,135,11,11,\"תָּרוּם קָרֶת. תִּתְקַיֵּם תִּקְרַת הַבַּיִת בְּגָבְהָהּ מִלִּפּוֹל. בְּעוֹד שֶׁהָיוּ מַלְכֵי יְהוּדָה יְשָׁרִים, הֶעֱמִידָה תְּפִלָּתָם אֶת בֵּית הַמִּקְדָּשׁ:\",1,0],[2,135,11,12,\"וְאִישׁ תְּבוּנוֹת יַחֲרִישׁ. כְּשֶׁמְּבַזֵּהוּ הֶחָסֵר לֵב; כְּמוֹ שָׁאוּל, דִּכְתִיב ״וַיִּבְזֻהוּ וְלֹא הֵבִיאוּ לוֹ מִנְחָה וַיְהִי כְּמַחֲרִישׁ״ (שמואל א י:כז):\",1,0],[2,135,11,14,\"בְּאֵין תַּחְבֻּלוֹת. כְּשֶׁהַצָּרָה בָּאָה עַל יִשְׂרָאֵל, וְאֵינָן נוֹתְנִין לֵב לְהָבִין לְהִתְעַנּוֹת וְלַעֲשׂוֹת תְּשׁוּבָה, יִפָּל עָם:\",1,0],[2,135,11,15,\"רַע יֵרוֹעַ. הָרָשָׁע יִתְרוֹצֵץ, אֲשֶׁר עָרַב לִבּוֹ לַעֲבוֹדַת גִּלּוּלִים:\",1,0],[2,135,11,15,\"וְשׂוֹנֵא תוֹקְעִים. תּוֹקְעִים כַּף לַעֲשׂוֹת רַע וְלָלֶכֶת בַּעֲצָתָם, וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ (יבמות קט:) בְּעַרְבוּת מָמוֹן:\",2,0],[2,135,11,16,\"תִּתְמֹךְ כָּבוֹד. כְּנֶסֶת יִשְׂרָאֵל תְּקָרֵב תָּמִיד לִכְבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא וְתוֹרָתוֹ:\",1,0],[2,135,11,16,\"וְעָרִיצִים יִתְמְכוּ עֹשֶׁר. בְּנֵי אֱדוֹם מִתְקָרְבִים אֵצֶל גְּנֵיבוֹת מָמוֹן וְגָזֵל:\",2,0],[2,135,11,17,\"גּוֹמֵל נַפְשׁוֹ. גּוֹמֵל טוֹבָה לִקְרוֹבָיו. אִישׁ חָסֶד אִישׁ שֶׁהוּא חָסִיד:\",1,0],[2,135,11,17,\"וְעֹכֵר שְׁאֵרוֹ אַכְזָרִי. וְהָאַכְזָרִי הוּא עוֹכֵר אֶת קְרוֹבָיו:\",2,0],[2,135,11,18,\"רָשָׁע עֹשֶׂה פְעֻלַּת שָׁקֶר. פְּעֻלָּתוֹ שֶׁל רָשָׁע מְשַׁקֶּרֶת לוֹ, כְּסָבוּר שֶׁתִּתְקַיֵּם בּוֹ הַצְלָחָתוֹ, וְהַכֹּל אָבַד:\",1,0],[2,135,11,18,\"וְזוֹרֵעַ צְדָקָה שֶׂכֶר אֱמֶת. וְהַזּוֹרֵעַ צְדָקָה הִיא פְּעֻלָּה שֶׁל אֱמֶת, כִּי בְּוַדַּאי בָּטוּחַ הוּא שֶׁיְּקַבֵּל פָּעֳלוֹ בַּסּוֹף:\",2,0],[2,135,11,18,\"שֶׂכֶר. קְרוֹנִיאָ״ל בְּלַעַ״ז, כְּאָדָם הַסּוֹכֵר אַמַּת הַמַּיִם כְּדֵי לִלְקוֹט דָּגִים, וּבָטוּחַ שֶׁיִּמְצָא שָׁם דָּגִים הַרְבֵּה. וְדוֹמֶה לוֹ ״כָּל עֹשֵׂי שֶׂכֶר אַגְמֵי נָפֶשׁ״ (ישעיהו יט:י):\",3,0],[2,135,11,19,\"כֵּן צְדָקָה לְחַיִּים. אֲמִתּוֹ שֶׁל צְדָקָה סוֹפָהּ לְחַיִּים, כְּמוֹ ״כֵּן בְּנוֹת צְלָפְחָד דֹּבְרוֹת״ (במדבר כז:ז):\",1,0],[2,135,11,21,\"יָד לְיָד. כְּלוֹמַר: מִיַּד הַקָּדוֹשׁ בָּרוּךְ הוּא לְיָדוֹ תָּבוֹא לוֹ שְׂכַר פְּעֻלָּתוֹ, וְלֹא יִנָּקֶה מִן הָרָעָה אֲשֶׁר עָשָׂה (סוטה ד:):\",1,0],[2,135,11,22,\"נֶזֶם זָהָב בְּאַף חֲזִיר. שֶׁמְּלַכְלֵךְ אוֹתָהּ בָּאַשְׁפּוֹת, כֵּן תַּלְמִיד חָכָם הַסָּר מִן הַדֶּרֶךְ הַטּוֹבָה:\",1,0],[2,135,11,22,\"וְסָרַת טָעַם. פּוֹרֵשׁ מִן הַתּוֹרָה:\",2,0],[2,135,11,23,\"תִּקְוַת רְשָׁעִים עֶבְרָה. בְּטוּחִים וּמְקַוִּים לְגֵיהִנֹּם:\",1,0],[2,135,11,24,\"יֵשׁ מְפַזֵּר. מְמוֹנוֹ, כְּגוֹן לִצְדָקָה, וְנוֹסָף עוֹד:\",1,0],[2,135,11,24,\"וְחוֹשֵׂךְ. עַצְמוֹ מִיֹּשֶׁר, אַךְ לְמַחְסוֹר יִהְיֶה לוֹ:\",2,0],[2,135,11,25,\"נֶפֶשׁ בְּרָכָה. שֶׁהוּא וַתְרָן בְּמָמוֹנוֹ. וְכָל לְשׁוֹן בְּרָכָה – פִּישׁוֹן בְּלַעַ״ז:\",1,0],[2,135,11,25,\"וּמַרְוֶה. שֶׁמַּשְׂבִּיעַ אֶת הָעֲנִיִּים:\",2,0],[2,135,11,25,\"גַּם הוּא יוֹרֶא. יִשְׂבַּע טוֹב:\",3,0],[2,135,11,26,\"מוֹנֵעַ בָּר. מְלַמֵּד תּוֹרָה:\",1,0],[2,135,11,27,\"שׁוֹחֵר טוֹב. הֶחָפֵץ לְהַדְרִיךְ אֶת הַבְּרִיּוֹת בְּדֶרֶךְ טוֹבָה, וּמוֹכִיחַ וּמְיַסֵּר אוֹתָם:\",1,0],[2,135,11,27,\"יְבַקֵּשׁ רָצוֹן. הוּא חָפֵץ שֶׁיִּהְיֶה הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָּם, וּמִתְפַּיֵּס עִמָּם. רָצוֹן, אפיימינ״ט בְּלַעַ״ז:\",2,0],[2,135,11,29,\"עוֹכֵר בֵּיתוֹ יִנְחַל רוּחַ. אָדָם עָצֵל שֶׁיִּנְחַל רוּחַ תָּמִיד, וְאֵינוֹ יָגֵעַ בַּתּוֹרָה וְלֹא בִמְלָאכָה, סוֹף עוֹכֵר אֶת בְּנֵי בֵיתוֹ, שֶׁאֵין לָהֶם מַה לֶּאֱכֹל:\",1,0],[2,135,11,30,\"פְּרִי צַדִּיק. גְּמוּל פֵּירוֹת מַעֲשֵׂה הַצַּדִּיקִים עֵץ חַיִּים הֵם לָעוֹלָם:\",1,0],[2,135,11,30,\"וְלֹקֵחַ נְפָשׁוֹת חָכָם. מִי שֶׁהוּא חָכָם, קוֹנֶה לוֹ נְפָשׁוֹת. שֶׁמְּלַמְּדָם דֶּרֶךְ טוֹב, וַהֲרֵי הֵם לוֹ כְּאִלּוּ קְנָאָם, כְּעִנְיָן שֶׁנֶּאֱמַר ״וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן״ (בראשית יב:ה):\",2,0],[2,135,11,31,\"הֵן צַדִּיק בָּאָרֶץ יְשֻׁלָּם. לָמָּה יִבְטַח הָרָשָׁע בְּשָׁעָה שֶׁמַּצְלַחַת לוֹ? הֲלֹא הוּא רוֹאֶה שֶׁהַצַּדִּיק מִשְׁתַּלֵּם שְׂכַר הָעֲבֵירָה שֶׁבְּיָדוֹ בְּעוֹדוֹ עַל הָאָרֶץ בַּחַיִּים:\",1,0],[2,135,11,31,\"וְאַף כִּי רָשָׁע וְחוֹטֵא. וְכָל שֶׁכֵּן שֶׁסּוֹפוֹ שֶׁל רָשָׁע לְהִשְׁתַּלֵּם לוֹ, אוֹ בְּחַיָּיו אוֹ בְּמוֹתוֹ:\",2,0],[2,135,12,2,\"טוֹב יָפִיק. מוֹצִיא מִן הַקָּדוֹשׁ בָּרוּךְ הוּא נַחַת רוּחַ, לְהָבִיא טוֹבָה לָעוֹלָם:\",1,0],[2,135,12,2,\"וְאִישׁ מְזִמּוֹת יַרְשִׁיעַ. בַּעַל עֲלִילוֹת יַרְשִׁיעַ – מְחַיֵּב אֶת הַבְּרִיּוֹת לְהָבִיא רָעָה, וְכֵן הוּא אוֹמֵר ״וְחוֹטֵא אֶחָד יְאַבֵּד טוֹבָה הַרְבֵּה״ (קהלת ט:יח):\",2,0],[2,135,12,3,\"לֹא יִכּוֹן אָדָם בְּרֶשַׁע. לֹא יִתְבַּסֵּס:\",1,0],[2,135,12,4,\"וּכְרָקָב. תּוֹלַעַת הַנִּכְנָס תּוֹךְ הָעֲצָמוֹת וְטוֹחֵן אוֹתָם, כֵּן אִשָּׁה מְבִישָׁה וְרָעָה, שֶׁמַּעֲשֶׂיהָ בּוֹשִׁים:\",1,0],[2,135,12,6,\"דִּבְרֵי רְשָׁעִים אֱרָב דָּם. יוֹעֲצִים לִרְצוֹחַ בְּיָדָם אוֹ עַל יְדֵי עֵדוּת שֶׁקֶר:\",1,0],[2,135,12,6,\"וּפִי יְשָׁרִים. כְּשֶׁשּׁוֹמְעִים אֶת עֲצָתָם, יַצִּילוּם לַנִּרְדָּפִים, שֶׁמְּגַלִּים אֶת עֲצָתָם; אוֹ אִם עֵדִים הֵם, מְזִמִּין אוֹתָם:\",2,0],[2,135,12,7,\"הָפוֹךְ רְשָׁעִים. כְּמוֹ ״לַהֲפֹךְ״, כְּמַהְפֵּכַת רֶגַע (איכה ד:ו) נֶהְפָּכִים:\",1,0],[2,135,12,7,\"וְאֵינָם. כָּלִים, כְּגוֹן סְדוֹם (בראשית יט:כד-כה):\",2,0],[2,135,12,7,\"וּבֵית צַדִּיקִים יַעֲמֹד. יִתְקַיֵּם:\",3,0],[2,135,12,8,\"לְפִי שִׂכְלוֹ יְהֻלַּל אִישׁ. אִם חָכָם מְעַט אוֹ הַרְבֵּה, הַכֹּל לְפִי שִׂכְלוֹ יִטֹּל שְׂכָרוֹ:\",1,0],[2,135,12,8,\"וְנַעֲוֵה לֵב. שֶׁהֵנִיעַ לִבּוֹ לְגַמְרֵי מִן הַתּוֹרָה, הוּא יִהְיֶה לָבוּז:\",2,0],[2,135,12,8,\"נַעֲוֵה. כְּמוֹ ״נַעֲוֵיתִי מִשְּׁמֹעַ״ (ישעיה כא:ג), וְכֵן ״בֶּן נַעֲוַת הַמַּרְדּוּת״ (שמואל א כ:ל). וְיֵשׁ לוֹמַר נַעֲוֵה – מִי שֶׁלִּבּוֹ נָעוּעַ, מִגִּזְרַת ״נָע וָנָד״ (בראשית ד:יב). כַּאֲשֶׁר יֹאמַר ״זַעֲוָה״ (דברים כח:כה) מִגִּזְרַת ״זָע״ (אסתר ה:ט):\",3,0],[2,135,12,9,\"טוֹב נִקְלֶה. בְּעֵינָיו, וְנַעֲשָׂה עֶבֶד לְעַצְמוֹ:\",1,0],[2,135,12,9,\"מִמִּתְכַּבֵּד. בְּעֵינָיו, וְאוֹמֵר: גְּנַאי הוּא לִי לַעֲמֹל בִּמְלָאכָה, שֶׁאֲנִי מִבְּנֵי אָדָם גְּדוֹלִים; וְסוֹפוֹ לִהְיוֹת חֲסַר לָחֶם:\",2,0],[2,135,12,10,\"יוֹדֵעַ צַדִּיק נֶפֶשׁ בְּהֶמְתּוֹ. מַה בְּהֶמְתּוֹ וּבְנֵי בֵיתוֹ צְרִיכִים:\",1,0],[2,135,12,11,\"עוֹבֵד אַדְמָתוֹ יִשְׂבַּע לָחֶם. כְּמַשְׁמָעוֹ, וּלְפִי מְשָׁלוֹ: שֶׁחוֹזֵר עַל תַּלְמוּדוֹ תָּמִיד, שֶׁלֹּא יִשְׁתַּכַּח:\",1,0],[2,135,12,12,\"חָמַד רָשָׁע. לִהְיוֹת נִזּוֹן וּמִתְפַּרְנֵס מִמְּצוֹד רְשָׁעִים, שֶׁצָּדִין אֶת הַבְּרִיּוֹת בִּגְזֵלוֹת וְחָמָס:\",1,0],[2,135,12,12,\"וְשֹׁרֶשׁ צַדִּיקִים יִתֵּן. מַה שֶּׁהוּא רָאוּי לִיתֵּן, וְהוּא הַפְּרִי:\",2,0],[2,135,12,13,\"בְּפֶשַׁע שְׂפָתַיִם. בְּפֶשַׁע שִׂפְתֵי דּוֹר הַמַּבּוּל, שֶׁאָמְרוּ: ״מַה שַׁדַּי כִּי נַעַבְדֶנּוּ״ (איוב כא:טו), בָּא לָהֶם מוֹקֵשׁ רָע, וְנֹחַ הַצַּדִּיק יָצָא מֵהַצָּרָה (תנחומא, נח טז):\",1,0],[2,135,12,14,\"מִפְּרִי פִי אִישׁ. מִשְּׂכַר פִּיהֶם שֶׁל עוֹסְקֵי תוֹרָה, אוֹכְלִים טוֹב בָּעוֹלָם הַזֶּה, וְהַקֶּרֶן קַיֶּמֶת לָהֶם לָעוֹלָם הַבָּא:\",1,0],[2,135,12,16,\"אֱוִיל בַּיּוֹם יִוָּדַע כַּעְסוֹ. בְּיוֹם שֶׁהוּא כּוֹעֵס, בּוֹ בַּיּוֹם הוֹדִיעַ כַּעְסוֹ, שֶׁהוּא מִתְגָּרֶה וּמְחָרֵף חֲבֵירוֹ בָּרַבִּים, וְאֵין מַעְצָר לְרוּחוֹ. אֲבָל הֶעָרוּם כֹּסֶה קָלוֹן וְאֵינוֹ מְמַהֵר לָרִיב. וּמִדְרַשׁ אַגָּדָה: בְּיוֹם שֶׁנִּבְרָא אָדָם הָרִאשׁוֹן נוֹדַע סוּרְחָנוֹ (עבודה זרה ח.), וְהַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא עָרוּם, לֹא רָצָה לְשַׁחֵת בְּרִיּוֹתָיו, כִּסָּה קְלוֹנוֹ (חגיגה יב.) וְדָחָה לִגְזֵרָתוֹ מִיּוֹם שֶׁל אָדָם לְיוֹם שֶׁלּוֹ, שֶׁהוּא אֶלֶף שָׁנָה (תהלים צ:ד; במדבר רבה יד:יב):\",1,0],[2,135,12,17,\"יָפִיחַ אֱמוּנָה יַגִּיד צֶדֶק. מִי שֶׁמְּדַבֵּר אֱמוּנָה מַגִּיד בְּדִין עֵדוּת צֶדֶק לְזַכּוֹת הַזַּכַּאי:\",1,0],[2,135,12,18,\"יֵשׁ בּוֹטֶה. מְדַבֵּר, כְּמוֹ ״לְבַטֵּא בִשְׂפָתַיִם״ (ויקרא ה:ד):\",1,0],[2,135,12,18,\"כְּמַדְקְרוֹת חָרֶב. שֶׁמְּסַכְסֵךְ אֶת הַבְּרִיּוֹת וְגוֹרֵם לָהֶם לַהֲרֹג:\",2,0],[2,135,12,18,\"וּלְשׁוֹן חֲכָמִים. הַמֵּבִיא שָׁלוֹם בֵּין אָדָם לַחֲבֵירוֹ:\",3,0],[2,135,12,18,\"מַרְפֵּא. לַמִּבְטָא הַהוּא:\",4,0],[2,135,12,19,\"שְׂפַת אֱמֶת תִּכּוֹן לָעַד. תִּתְבַּסֵּס וּתְקַיֵּם:\",1,0],[2,135,12,19,\"וְעַד אַרְגִּיעָה. לִמְעַט רֶגַע הוּא כָּלֶה וְהוֹלֵךְ, שֶׁהַשֶּׁקֶר אֵין לוֹ רַגְלַיִם:\",2,0],[2,135,12,20,\"מִרְמָה בְּלֶב חֹרְשֵׁי רָע. וּמִתּוֹךְ שֶׁהֵם טְרוּדִים בְּמַחֲשָׁבוֹת שֶׁל תַּרְמִית, אֵין לָהֶם שִׂמְחָה, וּלְיוֹעֲצֵי שָׁלוֹם שִׂמְחָה:\",1,0],[2,135,12,21,\"לֹא יְאֻנֶּה לַצַּדִּיק. לֹא יֶאֱרַע, לֹא תִזְדַּמֵּן לוֹ עֲבֵרָה בְּלִי דַעַת:\",1,0],[2,135,12,23,\"אָדָם עָרוּם כּוֹסֶה דָּעַת. אֲפִלּוּ בְּחָכְמָתוֹ הוּא צָנוּעַ, וְכָל שֶׁכֵּן לְדִבְרֵי שְׁטוּת הוּא מְכַסֶּה. אֲבָל וְלֵב כְּסִילִים יִקְרָא אִוֶּלֶת. מַכְרִיז אִוֶּלֶת בְּקוֹל רָם:\",1,0],[2,135,12,24,\"יַד חָרֻצִים. יְשָׁרִים:\",1,0],[2,135,12,24,\"תִּמְשׁוֹל. תַּעֲשִׁיר:\",2,0],[2,135,12,25,\"דְּאָגָה בְלֶב אִישׁ יַשְׁחֶנָּה. יְשִׂיחֶנָּה מִדַּעְתּוֹ:\",1,0],[2,135,12,25,\"וְדָבָר טוֹב יְשַׂמְּחֶנָּה. יַעֲסֹק בַּתּוֹרָה, וְהִיא תְּשַׂמַּח אֶת הַדְּאָגָה שֶׁבְּלִבּוֹ וְתַצִּילֶנּוּ מִמֶּנָּה. וּלְדִבְרֵי הָאוֹמֵר: יְשִׂיחֶנָּה לַאֲחֵרִים, כָּךְ סוֹפוֹ שֶׁל מִקְרָא: וְדָבָר טוֹב. שֶׁיְּנַחֲמֶנּוּ חֲבֵרוֹ, יְשַׂמַּח אֶת הַדְּאָגָה:\",2,0],[2,135,12,26,\"יָתֵר מֵרֵעֵהוּ צַדִּיק. הַצַּדִּיק מְוַתֵּר מִדּוֹתָיו וְעוֹבֵר עֲלֵיהֶם יָתֵר, לְרֵיי״שׁ בְּלַעַ״ז:\",1,0],[2,135,12,26,\"וְדֶרֶךְ רְשָׁעִים. שֶׁהִיא לְמוּדָה לְהָרַע, הִיא תַּתְעֵם:\",2,0],[2,135,12,27,\"לֹא יַחֲרֹךְ. מְחֻבָּר לַמִּקְרָא שֶׁלְּפָנָיו, כְּלוֹמַר: דֶּרֶךְ רָשָׁע תַּתְעֵהוּ, וְלֹא יַחֲרֹךְ אֶת צֵידוֹ שֶׁל רְמִיָּה שֶׁלּוֹ:\",1,0],[2,135,12,27,\"לֹא יַחֲרֹךְ. לֹא יַצְלִיחַ בְּתַרְמִיתוֹ. וּלְפִי שֶׁדִּבֵּר בִּלְשׁוֹן צַיִד, נוֹפֵל בּוֹ לְשׁוֹן חֲרִיכָה, שֶׁהַצַּיָּד הַמַּצְלִיחַ צָד אֶת הָעוֹפוֹת וְחוֹרְכָן בָּאֵשׁ:\",2,0],[2,135,12,27,\"וְהוֹן אָדָם יָקָר חָרוּץ. מִקְרָא מְסֹרָס הוּא וְהוֹן אָדָם שֶׁהוּא חָרוּץ יָקָר הוּא, מָמוֹן אָדָם כָּשֵׁר יָקָר הוּא:\",3,0],[2,135,12,27,\"חָרוּץ. עוֹשֶׂה אֱמֶת, כְּמוֹ ״יַד חֲרוּצִים תַּעֲשִׁיר״ (משלי י:ד):\",4,0],[2,135,12,28,\"בְּאֹרַח צְדָקָה חַיִּים וְדֶרֶךְ נְתִיבָה. שֶׁל צְדָקָה:\",1,0],[2,135,12,28,\"אַל מָוֶת. לֹא יָמוּת:\",2,0],[2,135,13,1,\"בֵּן חָכָם מוּסַר אָב. מִקְרָא קָצָר הוּא: בֵּן חָכָם שׁוֹאֵל וְאוֹהֵב מוּסַר אָב. וְיֵשׁ אוֹמְרִים: בִּשְׁבִיל מוּסַר הָאָב הוּא חָכָם:\",1,0],[2,135,13,1,\"וְלֵץ. לֹא שָׁמַע גְּעָרָה שֶׁאֵינוֹ מְקַבֵּל תּוֹכָחוֹת:\",2,0],[2,135,13,2,\"מִפְּרִי פִי אִישׁ יֹאכַל טוֹב. מִשְּׂכַר תּוֹרָתוֹ יֹאכַל טוֹב בָּעוֹלָם הַזֶּה, וְהַקֶּרֶן קַיֶּמֶת לָעוֹלָם הַבָּא:\",1,0],[2,135,13,2,\"וְנֶפֶשׁ בֹּגְדִים חָמָס. וְחֵפֶץ בּוֹגְדִים חָמָס, כְּמוֹ ״אִם יֵשׁ אֶת נַפְשְׁכֶם״ (בראשית כג:ח), ״אַל תִּתְּנֵנִי בְּנֶפֶשׁ צָרָי״ (תהלים כז:יב):\",2,0],[2,135,13,3,\"נוֹצֵר פִּיו שׁוֹמֵר נַפְשׁוֹ פֹּשֵׂק שְׂפָתָיו. פּוֹתֵחַ שְׂפָתָיו לְדַבֵּר תָּמִיד כָּל רוּחוֹ, מִן ״וַתְּפַשְּׂקִי אֶת רַגְלַיִךְ״ (יחזקאל טז:כה) לְשׁוֹן רָחָב:\",1,0],[2,135,13,4,\"מִתְאַוָּה וָאַיִן נַפְשׁוֹ עָצֵל. מִתְאַוָּה נַפְשׁוֹ לְכָל טוֹב וָאַיִן:\",1,0],[2,135,13,4,\"וְנֶפֶשׁ חָרֻצִים תְּדֻשָּׁן: יְשָׁרִים הָאוֹכְלִים יְגִיעַ כַּפֵּיהֶם. זֶהוּ מַשְׁמָעוֹ לְפִי פְּשׁוּטוֹ. וּלְפִי מְשָׁלוֹ: לֶעָתִיד יִרְאֶה בִּכְבוֹד תַּלְמִידֵי חֲכָמִים וְיִתְאַוֶּה, וְלֹא יַשִּׂיג לוֹ:\",2,0],[2,135,13,5,\"דְּבַר שֶׁקֶר יִשְׂנָא צַדִּיק. הַצַּדִּיק שׂוֹנֵא דְּבַר שֶׁקֶר, אֲבָל הָרָשָׁע מְקַבְּלוֹ:\",1,0],[2,135,13,5,\"יַבְאִישׁ וְיַחְפִּיר. אֶת הַבְּרִיּוֹת בְּכָךְ:\",2,0],[2,135,13,6,\"וְרִשְׁעָה תְּסַלֵּף חַטָּאת. כְּמוֹ חוֹטֵא, וְעַל שֶׁהוּא רָשָׁע גָּמוּר קוֹרְאֵהוּ חַטָּאת. וּמַשְׁמָעוּתָהּ: אֶת הַחוֹטֵא תְּסַלֵּף רִשְׁעָתוֹ, תְּקַלְקֵל אוֹתוֹ וְתַשְׁפִּילֵהוּ. כָּל סִלּוּף – קִלְקוּל וְכִשָּׁלוֹן הוּא, כְּמוֹ ״אִוֶּלֶת אָדָם תְּסַלֵּף דַּרְכּוֹ״ (משלי יט:ג), וְתָבוֹא עָלָיו רָעָה:\",1,0],[2,135,13,7,\"יֵשׁ מִתְעַשֵּׁר וְאֵין כֹּל. מַרְאֶה עַצְמוֹ עָשִׁיר. דָּבָר אַחֵר: יֵשׁ אָדָם שֶׁהוּא מִתְעַשֵּׁר בְּסוֹפוֹ, וְאֵין לוֹ כְּלוּם בִּתְחִלָּתוֹ, וְיֵשׁ שֶׁהוּא בָּא לִידֵי עֲנִיּוּת מִמָּמוֹן גָּדוֹל. דָּבָר אַחֵר: מִתְעַשֵּׁר בְּגֶזֶל עֲנִיִּים, וְסוֹף אֵין לוֹ כְּלוּם, וְיֵשׁ מִתְרוֹשֵׁשׁ עַל יְדֵי שֶׁפִּזֵּר וְנָתַן לָאֶבְיוֹנִים, וְהוֹן רָב מוּכָן לוֹ:\",1,0],[2,135,13,8,\"כֹּפֶר נֶפֶשׁ אִישׁ עָשְׁרוֹ. עָשְׁרוֹ שֶׁל אָדָם הוּא כֹּפֶר נַפְשׁוֹ, שֶׁעָשָׂה מִמֶּנּוּ צְדָקָה:\",1,0],[2,135,13,8,\"וְרָשׁ לֹא שָׁמַע גְּעָרָה. וּבִלְבַד שֶׁלֹּא יַשְׁמִיעַ גְּעָרָה לָרָשׁ שֶׁנּוֹתֵן לוֹ וְאֵינוֹ מַכְלִימוֹ. דָּבָר אַחֵר: כֹּפֶר נֶפֶשׁ אִישׁ עָשְׁרוֹ, תּוֹרָתוֹ:\",2,0],[2,135,13,8,\"וְרָשׁ. בְּדִבְרֵי תוֹרָה לֹא שָׁמַע גְּעָרָה. אֵינוֹ יוֹדֵעַ לָסוּר מִן הָרָעָה, לְפִי שֶׁלֹּא נִזְהָר. וּמִדְרַשׁ אַגָּדָה: עַל ״מַחֲצִית הַשֶּׁקֶל״ מְדַבֵּר, שֶׁהִטִּיל הַכָּתוּב עַל כָּל יִשְׂרָאֵל, וְהִשְׁוָה בּוֹ דַּל וְעָשִׁיר (שמות ל:טו); שֶׁאֵין הָרָשׁ שׁוֹמֵעַ גְּעָרָה וּכְלִמָּה מִן הֶעָשִׁיר, לֵאמֹר לוֹ: חֶלְקִי גָּדוֹל מֵחֶלְקְךָ בְּקָרְבְּנוֹת צִבּוּר:\",3,0],[2,135,13,9,\"יִדְעָךְ. לְשׁוֹן קְפִיצָה, שֶׁהַשַּׁלְהֶבֶת קוֹפֶצֶת וְנִכְרֶתֶת:\",1,0],[2,135,13,10,\"רַק בְּזָדוֹן יִתֵּן מַצָּה. מַחֲלֹקֶת:\",1,0],[2,135,13,10,\"וְאֶת נוֹעָצִים. וְעִם הַמִּתְיַעֲצִים תָּלִין חָכְמָה:\",2,0],[2,135,13,11,\"הוֹן מֵהֶבֶל יִמְעָט. עוֹשֶׂה גִּרְסָתוֹ חֲבִילוֹת חֲבִילוֹת יִמְעָט, שֶׁיִּשְׁתַּכַּח מִמֶּנּוּ מְעַט מְעַט (עבודה זרה יט.):\",1,0],[2,135,13,12,\"תּוֹחֶלֶת מְמֻשָּׁכָה. מַבְטִיחַ עַצְמוֹ עַל חֲבֵירוֹ וְאֵינוֹ עוֹשֶׂה:\",1,0],[2,135,13,12,\"מַחֲלָה לֵב. מְבִיאָה חוֹלִי לַלֵּב, וְאֵין מַחֲלָה זֶה שֵׁם דָּבָר כְּמוֹ ״וַהֲסִרֹתִי מַחֲלָה מִקִּרְבֶּךָ״ (שמות כג:כה) אֶלָּא כְּמוֹ ״מַעֲלֵה גֵרָה״ (ויקרא יא:ה):\",2,0],[2,135,13,12,\"וְעֵץ חַיִּים תַּאֲוָה בָאָה. מְסֹרָס הוּא, כְּלוֹמַר: תַּאֲוָה בָאָה הֲרֵי הוּא כְּעֵץ חַיִּים. תּוֹחֶלֶת שֶׁהוֹחִיל הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל וְצִפָּה שֶׁיָּשׁוּבוּ, וְהֵם לֹא שָׁבוּ, סוֹף בָּאָה לָהֶם לְמַחֲלַת לֵב; וּכְשֶׁתַּאֲוָתוֹ בָאָה, שֶׁהֵם עוֹשִׂין רְצוֹנוֹ, עֵץ חַיִּים הִיא לָהֶם:\",3,0],[2,135,13,13,\"בָּז לְדָבָר יֵחָבֶל לוֹ. הַבּוֹזֶה אֶחָד מִדִּבְרֵי תוֹרָה, סוֹף מִתְמַשְׁכֵּן עָלָיו:\",1,0],[2,135,13,13,\"וִירֵא מִצְוָה הוּא יְשֻׁלָּם. יְקַבֵּל שָׂכָר. וּמִדְרַשׁ תְּהִלִּים דּוֹרֵשׁ בָּז לְדָבָר יֵחָבֶל לוֹ עַל דָּוִד שֶׁאָמַר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: רִבּוֹנוֹ שֶׁל עוֹלָם, מָה הֲנָאָה בַּשּׁוֹטִים שֶׁבָּרָאתָ? אָמַר לוֹ: חַיֶּיךָ, סוֹף שֶׁתִּצְטָרֵךְ לְשִׁטּוּת; כְּשֶׁבָּא לִפְנֵי אָכִישׁ לְהִשְׁתַּגֵּעַ ״וַיּוֹרֶד רִירוֹ עַל זְקָנוֹ וְגוֹמֵר״ (שמואל א כא:יד):\",2,0],[2,135,13,14,\"תּוֹרַת חָכָם מְקוֹר חַיִּים. שֶׁהִיא מְלַמְּדַתּוֹ לָסוּר מִמֹּקְשֵׁי מָוֶת:\",1,0],[2,135,13,15,\"וְדֶרֶךְ בּוֹגְדִים אֵיתָן. קָשֶׁה לוֹ וְלַאֲחֵרִים:\",1,0],[2,135,13,16,\"כָּל עָרוּם יַעֲשֶׂה בְדָעַת. מַעֲשֵׂהוּ, כְּגוֹן דָּוִד: ״יְבַקְשׁוּ לַאדֹנִי הַמֶּלֶךְ נַעֲרָה בְתוּלָה וְגוֹמֵר״ (מלכים א א:ב):\",1,0],[2,135,13,16,\"וּכְסִיל יִפְרֹשׂ אִוֶּלֶת. זֶה אֲחַשְׁוֵרוֹשׁ, ״וְיַפְקֵד הַמֶּלֶךְ״ (אסתר ב:ג). יוֹדְעִים הָיוּ שֶׁלֹּא יִשָּׂא לְכֻלָּם, וּמִי שֶׁהָיָה לוֹ בַת הִטְמִינָהּ (מגילה יב:):\",2,0],[2,135,13,17,\"מַלְאָךְ רָשָׁע יִפֹּל בְּרָע. כְּגוֹן בִּלְעָם, שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא ״לֵךְ עִם הָאֲנָשִׁים״ (במדבר כב:כ, לה), וְהִרְשִׁיעַ לְהַשִּׂיא לְבָלָק עֵצָה רָעָה; לְכָךְ נָפַל בַּחֶרֶב (במדבר לא:ח):\",1,0],[2,135,13,17,\"וְצִיר אֱמוּנִים מַרְפֵּא. זֶה מֹשֶׁה רַבֵּינוּ:\",2,0],[2,135,13,18,\"רֵישׁ וְקָלוֹן. דַּלּוּת וְקָלוֹן בָּאִים עַל פּוֹרֵעַ מוּסָר:\",1,0],[2,135,13,19,\"תֶּעֱרַב לְנָפֶשׁ. כְּשֶׁבָּאָה תַּאֲוָתוֹ לוֹ לָאָדָם, הִיא עֲרֵבָה לְנַפְשׁוֹ; וּלְכָךְ תּוֹעֲבַת כְּסִיל לָסוּר מֵרָע, לְפִי שֶׁעָרֵב לָהֶם לְמַלֵּא תַּאֲוָתָם:\",1,0],[2,135,13,19,\"נִהְיָה. הֹוֶה. דָּבָר אַחֵר: תַּאֲוָה נִהְיָה הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְאַוֶּה שֶׁיַּעֲשׂוּ יִשְׂרָאֵל רְצוֹנוֹ, וּבִהְיוֹת תַּאֲוָתוֹ בָּאָה, עֲרֵבָה לוֹ. וְתוֹעֲבַת רְשָׁעִים – שֶׁיָּסוּרוּ מֵרָעָתָם, לְמַלֹּאות תַּאֲוָתָם:\",2,0],[2,135,13,20,\"הוֹלֵךְ אֶת חֲכָמִים. יֶחְכָּם, וְרֹעֶה כְסִילִים הַמְחַבֵּר לוֹ כְּסִילִים לִהְיוֹת לוֹ רֵעִים:\",1,0],[2,135,13,20,\"יֵרוֹעַ. יְרוּצַּץ:\",2,0],[2,135,13,21,\"חַטָּאִים תְּרַדֵּף רָעָה. אָדָם רָשָׁע, רִשְׁעָתוֹ רוֹדַפְתּוֹ עַד הִשָּׁמְדוֹ:\",1,0],[2,135,13,22,\"טוֹב יַנְחִיל. אֶת זְכוּתוֹ וְאֶת מָמוֹנוֹ לִבְנֵי בָנָיו, אֲבָל חוֹטֵא אֵינוֹ מַנְחִיל לְבָנָיו, כִּי צָפוּן חֵילוֹ וּמָמוֹנוֹ לַצַּדִּיק, כְּמוֹ שֶׁכָּתוּב ״וַתָּשֶׂם אֶסְתֵּר אֶת מָרְדֳּכַי עַל בֵּית הָמָן״ (אסתר ח:ב):\",1,0],[2,135,13,23,\"רָב אֹכֶל נִיר רָאשִׁים. רָאִיתִי בַּמָּסֹרֶת הַגְּדוֹלָה: רָב אֹכֶל. שְׁלֹשִׁים וּשְׁלֹשָׁה ׳רָב׳ – קְמָצִין, וְזֶהוּ חֲטַף קָמַץ, וּמְחֻבָּר עִם אֹכֶל בְּמַקֵּף; וְ׳אֹכֶל׳ רָאִיתִי שָׁם: נָקוּד פַּתַּח (ר״ל סגול שהוא פתח קטן) וְטַעֲמוֹ לְעֵילָא, כְּמוֹ ״אֶת כָּל אֹכֶל הַשָּׁנִים הַטּוֹבוֹת״ (בראשית מא:לה). וּלְפִי נְקֻדָּתוֹ, זֶה פִּתְרוֹנוֹ: הַרְבֵּה תְּבוּאָה בָּאָה לָעוֹלָם עַל יְדֵי נִיר אֲנָשִׁים דַּלִּים, כְּלוֹמַר: הַרְבֵּה תּוֹרָה יוֹצְאָה עַל יְדֵי תַּלְמִידִים, שֶׁרַבּוֹתֵיהֶם לְמֵדִין מֵהֶם מִתּוֹךְ פִּלְפּוּלָם שֶׁמְּפַלְפְּלִים בַּהֲלָכָה:\",1,0],[2,135,13,23,\"וְיֵשׁ נִסְפֶּה. וְיֵשׁ הַרְבֵּה מֵהֶם שֶׁהֵם כָּלִים מִן הָעוֹלָם בִּשְׁבִיל לֹא מִשְׁפָּט שֶׁאֵינָן נוֹהֲגִין כַּשּׁוּרָה, וּלְעִנְיַן הַתְּבוּאָה יֵשׁ תְּבוּאָה לוֹקָה בִּשְׁבִיל בְּעָלֶיהָ שֶׁאֵינוֹ מוֹצִיא מַעַשְׂרוֹתֶיהָ וּמַתְּנוֹת עֲנִיִּים כַּמִּשְׁפָּט, וְרַבּוֹתֵינוּ פֵּרְשׁוּ בְּמַסֶּכֶת חֲגִיגָה (חגיגה ד:-ה.), וְיֵשׁ נִסְפֶּה עַל שְׁלוּחוֹ שֶׁל מַלְאַךְ הַמָּוֶת שֶׁמְּחַלֵּף שֵׁם בְּשֵׁם וּמֵמִית אֶת שֶׁלֹּא הִגִּיעַ זְמַנּוֹ אֲבָל אִם כֵּן הוּא אֵין עִנְיַן סוֹף הַפָּסוּק לְרֹאשׁוֹ:\",2,0],[2,135,13,24,\"חוֹשֵׂךְ שִׁבְטוֹ. סוֹפוֹ שֶׁשּׂוֹנֵא אֶת בְּנוֹ, שֶׁרוֹאֵהוּ בְּסוֹפוֹ יוֹצֵא לְתַרְבּוּת רָעָה:\",1,0],[2,135,13,24,\"שִׁחֲרוֹ מוּסָר. תָּמִיד לַבְּקָרִים מְיַסְּרֵהוּ:\",2,0],[2,135,13,25,\"לְשֹׂבַע נַפְשׁוֹ. דּוֹמֶה שֶׁיְּהֵא שָׂבֵעַ (סא״א ונכתב תחתיו):\",1,0],[2,135,13,25,\"תֶּחְסָר. אֵינוֹ דּוֹמֶה שֶׁיְּהֵא שָׂבֵעַ:\",2,0],[2,135,14,1,\"חַכְמוֹת נָשִׁים בָּנְתָה בֵיתָהּ. חָכְמוֹת נָקוּד פַּתָּח, שֶׁאֵינוֹ שֵׁם דָּבָר, אֶלָּא הַחֲכָמוֹת שֶׁבַּנָּשִׁים בּוֹנוֹת אֶת בָּתֵּיהֶם – שֶׁמִּתְקַיְּמוֹת עַל יְדֵיהֶן; כְּמוֹ אִשְׁתּוֹ שֶׁל אוֹן בֶּן פֶּלֶת, כְּמוֹ שֶׁמְּפֹרָשׁ בְּפֶרֶק ׳חֵלֶק׳ (סנהדרין קט:-קי.):\",1,0],[2,135,14,1,\"וְאִוֶּלֶת. וְאִשָּׁה שׁוֹטָה:\",2,0],[2,135,14,1,\"בְּיָדֶיהָ תֶּהֶרְסֶנּוּ. תַּהֲרֹס בֵּיתָהּ; זוֹ אִשְׁתּוֹ שֶׁל קֹרַח (במדבר טז:א):\",3,0],[2,135,14,2,\"הוֹלֵךְ בְּיָשְׁרוֹ יְרֵא. מִי שֶׁהוּא יְרֵא ה׳, וּמִי שֶׁהוּא נְלוֹז דְּרָכִים, כְּלוֹמַר: עוֹקֵם דְּרָכָיו:\",1,0],[2,135,14,2,\"בוזהו. לְהַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,135,14,3,\"בְּפִי אֱוִיל חֹטֶר גַּאֲוָה. מַקֵּל שֶׁל גַּאֲוָה, כְּגוֹן פַּרְעֹה, שֶׁאָמַר ״מִי ה׳ אֲשֶׁר אֶשְׁמַע בְּקוֹלוֹ״ (שמות ה:ב):\",1,0],[2,135,14,3,\"תִּשְׁמוּרֵם. כְּמוֹ ״תִּשְׁמְרֵם״ (משלי כב:יח) – תִּשְׁמֹר אֶת הַחֲכָמִים:\",2,0],[2,135,14,4,\"בְּאֵין אֲלָפִים אֵבוּס בָּר. בְּאֵין שְׁוָורִים הָאֵבוּס רֵיקָם, שֶׁאֲפִלּוּ תֶּבֶן אֵין מָצוּי בַּבַּיִת:\",1,0],[2,135,14,4,\"בָּר. נָקִי וְרֵיקָם, כְּלוֹמַר: בְּמָקוֹם שֶׁאֵין תַּלְמִידֵי חֲכָמִים אֵין הוֹרָאָה נִמְצֵאת כַּהֲלָכָה:\",2,0],[2,135,14,5,\"וְיָפִיחַ כְּזָבִים. וְתָמִיד מְדַבֵּר כָּזָב עֵד שָׁקֶר:\",1,0],[2,135,14,6,\"בִּקֶּשׁ לֵץ חָכְמָה. כְּשֶׁהוּא צָרִיךְ אֶל הַחָכְמָה אֵינוֹ מוֹצְאָהּ בְּלִבּוֹ:\",1,0],[2,135,14,7,\"לֵךְ מִנֶּגֶד לְאִישׁ כְּסִיל. מֵהִתְחַבֵּר תָּמִיד אֶצְלוֹ:\",1,0],[2,135,14,7,\"וּבַל יָדַעְתָּ. סוֹפְךָ שֶׁלֹּא יָדַעְתָּ חָכְמָה:\",2,0],[2,135,14,8,\"חָכְמַת עָרוּם. מִי שֶׁהוּא חָכָם הָבִין דַּרְכּוֹ לְפַלֵּס אָרְחוֹתָיו:\",1,0],[2,135,14,8,\"וְאִוֶּלֶת כְּסִילִים. הִיא הַמִּרְמָה שֶׁבְּלִבָּם, סוֹפָהּ שֶׁמְּבִיאָתָם לִידֵי טִפְּשׁוּת:\",2,0],[2,135,14,9,\"אֱוִילִים יָלִיץ אָשָׁם. שֶׁהֵם חוֹטְאִים, שֶׁצְּרִיכִין לָתֵת מָמוֹן לְמִי שֶׁחָטְאוּ לוֹ, וְיָלִיץ בַּעֲדָם אֲשָׁמָם, שֶׁהֵם מְבִיאִים מְמוֹנָם לוֹ; כְּמוֹ הַפְּלִשְׁתִּים שֶׁנֶּאֱמַר ״קְחוּ לָכֶם חֲמִשָּׁה טְחוֹרֵי זָהָב וַחֲמִשָּׁה עַכְבְּרֵי זָהָב וְגוֹמֵר וּנְתַתֶּם לֵאלֹהֵי יִשְׂרָאֵל כָּבוֹד אוּלַי יָקֵל אֶת יָדוֹ מֵעֲלֵיכֶם״ (שמואל א ו:ד-ה):\",1,0],[2,135,14,9,\"אָשָׁם. אַמֶנְדָ״א בְּלַעַ״ז:\",2,0],[2,135,14,9,\"וּבֵין יְשָׁרִים רָצוֹן. אַפֵּיְימִינְ״ט בְּלַעַ״ז, הַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה לָהֶם:\",3,0],[2,135,14,10,\"לֵב יוֹדֵעַ מָרַּת נַפְשׁוֹ. טָרְחוֹ וִיגִיעוֹ שֶׁעָמַל בַּתּוֹרָה, לְפִיכָךְ בְּשִׂמְחָתוֹ לֹא יִתְעָרַב זָר כְּשֶׁיְּקַבֵּל שְׂכָרוֹ לֶעָתִיד. דָּבָר אַחֵר: לֵב יוֹדֵעַ מָרַּת נַפְשׁוֹ יִשְׂרָאֵל שֶׁהֵם מָרֵי נֶפֶשׁ בַּגָּלוּת וְהָיוּ נֶהֱרָגִים עַל קְדֻשַּׁת הַשֵּׁם וּבְשִׂמְחָתוֹ לֹא יִתְעָרַב זָר לֶעָתִיד. בֵּית רְשָׁעִים. בֵּית אֲרַם יִשָּׁמֵד.\",1,0],[2,135,14,12,\"יֵשׁ דֶּרֶךְ יָשָׁר לִפְנֵי אִישׁ. עוֹבֵר עֲבֵירָה וְאוֹמֵר אֵין בָּהּ עֲבֵירָה. דָּבָר אַחֵר: יֵשׁ דֶּרֶךְ יָשָׁר לִפְנֵי אִישׁ. דֶּרֶךְ עָצֵל יְשָׁרָה הָיְתָה בְּעֵינֵי עֵשָׂו שֶׁהָיָה אִישׁ שָׂדֶה (בראשית כה:כז), וְאַחֲרִיתָהּ וְגוֹ׳:\",1,0],[2,135,14,13,\"גַּם בִּשְׂחוֹק. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׂחֵק עִמָּהֶם בָּעוֹלָם הַזֶּה, יִכְאַב לִבָּם לֶעָתִיד לָבֹא. וְכֵן הוּא אוֹמֵר ״וְאַתֶּם תִּצְעֲקוּ מִכְּאֵב לֵב״ (ישעיהו סה:יד):\",1,0],[2,135,14,14,\"מִדְּרָכָיו יִשְׂבַּע סוּג לֵב. עֵשָׂו:\",1,0],[2,135,14,14,\"וּמֵעָלָיו אִישׁ טוֹב. יַעֲקֹב:\",2,0],[2,135,14,15,\"פֶּתִי יַאֲמִין. לְדִבְרֵיהֶם וְנִסָּת אַחֲרֵיהֶם. דָּבָר אַחֵר: בִּשְׂחוֹק יִכְאַב לֵב, ״שְׂחוֹק לִכְסִיל עֲשׂוֹת זִמָּה״ (משלי י:כג), וְסוֹפוֹ יִכְאַב לֵב. סוּג לֵב – רָשָׁע, כְּמוֹ ״כֶּסֶף סִיגִים״ (משלי כו:כג). סוּג הוּא שֵׁם הַפְּסֹלֶת, סוּג הוּא הַכֶּסֶף הַמְעֻרְבָּב בַּפְּסֹלֶת:\",1,0],[2,135,14,15,\"וּמֵעָלָיו אִישׁ טוֹב. וּמִמַּעַל לוֹ לָרָשָׁע, יִהְיֶה הַצַּדִּיק:\",2,0],[2,135,14,15,\"פֶּתִי יַאֲמִין. לְאַנְשֵׁי רָכִיל:\",3,0],[2,135,14,15,\"וְעָרוּם יָבִין לַאֲשׁוּרוֹ. לִפְסִיעוֹתָיו, כְּלוֹמַר: יְצַפֶּה מִלָּרִיב, וְיַמְתִּין עַד יִוָּדַע לוֹ אֶל נָכוֹן (שמואל א כו:ד):\",4,0],[2,135,14,16,\"חָכָם יָרֵא. מִן הַפּוּרְעָנוּת:\",1,0],[2,135,14,16,\"וְסָר מֵרָע. מִן הָרָעָה:\",2,0],[2,135,14,16,\"וּכְסִיל מִתְעַבֵּר. מִתְחַזֵּק לַעֲבֹד בְּחָזְקָה:\",3,0],[2,135,14,16,\"וּבוֹטֵחַ. וּמַחֲלִיק וְנוֹפֵל בָּאָרֶץ, כְּמוֹ ״בְּאֶרֶץ שָׁלוֹם אַתָּה בוֹטֵחַ״ (ירמיה יב:ה), וְתִרְגֵּם יוֹנָתָן: ״אַתְּ מִתְבַּטַּח וְנָפוֹל״ – מַחֲלִיק. וְיֵשׁ מְפָרְשִׁים: בִּטָּחוֹן מַמָּשׁ, בְּהֵיכָלוֹ; בּוֹטֵחַ לוֹמַר: לֹא תְבוֹאֵנִי רָעָה:\",4,0],[2,135,14,17,\"קְצַר אַפַּיִם. הַמְּמַהֵר לִנְקֹם כַּעֲסוֹ:\",1,0],[2,135,14,17,\"וְאִישׁ מְזִמּוֹת. מַחֲשָׁבוֹת עֵצָה רָעָה:\",2,0],[2,135,14,18,\"יַכְתִּירוּ דָעַת. יַעֲשׂוּהוּ כֶּתֶר לְרֹאשָׁם, וְסוֹף:\",1,0],[2,135,14,19,\"שָׁחוּ רָעִים לִפְנֵי טוֹבִים. לֶעָתִיד:\",1,0],[2,135,14,20,\"גַּם לְרֵעֵהוּ יִשָּׂנֵא רָשׁ. אֲפִלּוּ לְשׁוֹשְׁבִינָיו וְאוֹהֲבָיו. גַּם לְשׁוֹן אֲפִלּוּ:\",1,0],[2,135,14,20,\"יִשָּׂנֵא רָשׁ. עַם הָאָרֶץ שֶׁאֵינוֹ יוֹדֵעַ לִנְהוֹג כַּשּׁוּרָה:\",2,0],[2,135,14,23,\"בְּכָל־עֶצֶב. בְּכָל יְגִיעַ מְלָאכָה יִהְיֶה רֶוַח, אֲבָל דִּבְרֵי הֶבֶל אַךְ לְמַחְסוֹר:\",1,0],[2,135,14,24,\"עֲטֶרֶת חֲכָמִים עָשְׁרָם. שֶׁהֵם עֲשִׁירִים בַּתּוֹרָה:\",1,0],[2,135,14,24,\"וְאִוֶּלֶת כְּסִילִים אִוֶּלֶת. קַלְקַלְתָּן שֶׁל כְּסִילִים הִיא הָאִוֶּלֶת, שֶׁנִּתְעַצֵּל מִן הַחָכְמָה:\",2,0],[2,135,14,26,\"בְּיִרְאַת ה׳ מִבְטַח עֹז. נֶאֱמַר בְּאַבְרָהָם ״כִּי עַתָּה יָדַעְתִּי כִּי יְרֵא אֱלֹהִים אַתָּה״ (בראשית כב:יב), וְהִבְטִיחוֹ ״כִּי בָרֵךְ אֲבָרֶכְךָ וְגוֹ׳״ (בראשית כב:יז):\",1,0],[2,135,14,26,\"וּלְבָנָיו יִהְיֶה הוּא:\",2,0],[2,135,14,26,\"מַחְסֶה. שֶׁיֵּחָסוּ וְיִתְחַבֵּא בְּצֵל זְכוּתוֹ:\",3,0],[2,135,14,28,\"בְּרָב עָם. שֶׁהַצִּבּוּר זַכָּאִים – הַדְרַת הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא:\",1,0],[2,135,14,28,\"וּבְאֶפֶס לְאֹם. כְּשֶׁאֵינָם דְּבֵקִים בּוֹ:\",2,0],[2,135,14,28,\"מְחִתַּת רָזוֹן. חֶסְרוֹן רַזְנוּתוֹ הוּא, כִּבְיָכוֹל נוֹתֵן מִכְּבוֹדוֹ לֵאלֹהֵי נֵכָר וּמַשְׁלִיט אֶת הָאֻמּוֹת עַל בָּנָיו:\",3,0],[2,135,14,29,\"מֵרִים אִוֶּלֶת. מַפְרִישָׁהּ לְחֶלְקוֹ:\",1,0],[2,135,14,30,\"חַיֵּי בְשָׂרִים לֵב מַרְפֵּא. לֵב בָּשָׂר, שֶׁהוּא רוֹפֵא אֶת הָרָעָה וְעוֹבֵר עַל מִדּוֹתָיו, הוּא חַיֵּי בְּרִיּוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֵן בָּשָׂר וָדָם:\",1,0],[2,135,14,30,\"וּרְקַב עֲצָמוֹת קִנְאָה. אָדָם בַּעַל חֵמָה, רִקָּבוֹן עֲצָמוֹת הוּא לַכֹּל:\",2,0],[2,135,14,32,\"וְחֹסֶה בְמוֹתוֹ צַדִּיק. כְּשֶׁיָּמוּת, הוּא בָּטוּחַ שֶׁיָּבֹא לְגַן עֵדֶן:\",1,0],[2,135,14,33,\"בְּלֵב נָבוֹן תָּנוּחַ חָכְמָה. תִּשְׁכֹּן וְתִשְׁקֹט בְּנַחַת, לְשׁוֹן מְנוּחָה וּמַרְגּוֹעַ:\",1,0],[2,135,14,33,\"וּבְקֶרֶב כְּסִילִים תִּוָּדֵעַ. מְעַט חָכְמָה שֶׁבְּלִבּוֹ מַכְרִיזָה; אִיסְתְּרָא בְּלָגִינָא קִישׁ קִישׁ קָרְיָא (בבא מציעא פה:):\",2,0],[2,135,14,34,\"צְדָקָה תְרוֹמֵם גּוֹי. יִשְׂרָאֵל:\",1,0],[2,135,14,34,\"וְחֶסֶד לְאֻמִּים חַטָּאת. הֵם עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁגּוֹזְלִים מִזֶּה וְנוֹתְנִים לָזֶה:\",2,0],[2,135,14,35,\"וְעֶבְרָתוֹ תִּהְיֶה לְעֶבֶד מֵבִישׁ (בבא בתרא י:):\",1,0],[2,135,15,4,\"וְסֶלֶף בָּהּ שֶׁבֶר בְּרוּחַ. כְּשֶׁיְּסַלֵּף בַּלָּשׁוֹן, סוֹפָהּ לְהָבִיא עָלָיו שֶׁבֶר הַבָּא בְּרוּחַ קָדִים, הַמּוּכָנָה לְהִפָּרַע מִן הָרְשָׁעִים, כְּמוֹ שֶׁאָמַר ״בְּרוּחַ קָדִים עַזָּה״ (שמות יד:כא), ״בְּרוּחַ קָדִים אֲפִיצֵם״ (ירמיה יח:יז), ״בְּרוּחַ קָדִים תְּשַׁבֵּר אֳנִיּוֹת תַּרְשִׁישׁ״ (תהלים מח:ח):\",1,0],[2,135,15,6,\"בֵּית צַדִּיק חֹסֶן רָב. בֵּית הַמִּקְדָּשׁ שֶׁבָּנָה דָּוִד הַצַּדִּיק חֹסֶן רַב וּמִגְדַּל עֹז לְיִשְׂרָאֵל:\",1,0],[2,135,15,6,\"וּבִתְבוּאַת רָשָׁע נֶעְכָּרֶת. וּבַהֲבָאַת הַצֶּלֶם שֶׁהֵבִיא מְנַשֶּׁה (דברי הימים ב לג:ז) בָּהּ נֶעְכְּרָה (דברים רבה ב:כ):\",2,0],[2,135,15,7,\"שִׂפְתֵי חֲכָמִים יְזָרוּ דָעַת. יַכְתִּירוּ דַעַת, כְּמוֹ ״זֵר זָהָב״ (שמות כה:יא):\",1,0],[2,135,15,7,\"לֹא כֵן. אֵינוֹ אֱמֶת:\",2,0],[2,135,15,8,\"זֶבַח רְשָׁעִים. תּוֹעֵבָה בָּלָק וּבִלְעָם (במדבר כב-כד):\",1,0],[2,135,15,8,\"וּתְפִלַּת יְשָׁרִים. זֶה מֹשֶׁה :\",2,0],[2,135,15,10,\"מוּסָר רָע לְעוֹזֵב אֹרַח. יִסּוּרִים קָשִׁים מוּכָנִים לְעוֹבֵר אֹרַח שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,135,15,11,\"שְׁאוֹל וַאֲבַדּוֹן נֶגֶד ה׳. גָּלוּי לְפָנָיו כָּל אֲשֶׁר בְּתוֹכָהּ:\",1,0],[2,135,15,11,\"אַף כִּי. קַל וָחֹמֶר הוּא:\",2,0],[2,135,15,13,\"לֵב שָׂמֵחַ יֵיטִיב פָּנִים. אִם תְּשַׂמַּח לִבּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּלֶכְתְּךָ בִּדְרָכָיו, וְיֵיטִיב לְךָ פָּנָיו לַעֲשׂוֹת כָּל רְצוֹנְךָ. וְאִם תְּעַצְּבֵהוּ, יַרְאֶה לְךָ רוּחַ נְכֵאָה, כְּמָה דְּאַתְּ אָמַר (בראשית ו:ו-ז) ״וַיִּתְעַצֵּב אֶל לִבּוֹ וַיֹּאמֶר ה׳ אֶמְחֶה אֶת הָאָדָם וְגוֹמֵר״. רוּחַ נְכֵאָה טלנ״ט, רוּחַ שֶׁל זַעַף:\",1,0],[2,135,15,15,\"כָּל יְמֵי עָנִי רָעִים. וַאֲפִלּוּ שַׁבָּתוֹת וְיָמִים טוֹבִים, דְּאָמַר שְׁמוּאֵל (סנהדרין ק:): שִׁנּוּי וֶסֶת תְּחִלַּת חֳלִי מֵעַיִם:\",1,0],[2,135,15,15,\"וְטוֹב לֵב. מִי שֶׁלִּבּוֹ טוֹב בְּעָשְׁרוֹ:\",2,0],[2,135,15,15,\"מִשְׁתֶּה תָמִיד. כָּל שְׁנוֹתָיו דּוֹמוֹת לוֹ יְמֵי מִשְׁתֶּה, לְלַמֶּדְךָ שֶׁיְּהֵא אָדָם שָׂמֵחַ בְּחֶלְקוֹ (אבות ד:א). וְרַבּוֹתֵינוּ דָּרְשׁוּ מַה שֶּׁדָּרְשׁוּ בְּחֵלֶק (סנהדרין ק:-קא.):\",3,0],[2,135,15,16,\"טוֹב מְעַט בְּיִרְאַת ה׳ מֵאוֹצָר רָב וּמְהוּמָה בוֹ. קוֹל בְּנֵי אָדָם צוֹעֲקִים, שֶׁנַּעֲשָׂה הָאוֹצָר מִגֶּזֶל וְחָמָס. כְּמוֹ ״וּרְאוּ מְהוּמוֹת רַבּוֹת בְּתוֹכָהּ וַעֲשׁוּקִים בְּקִרְבָּהּ״ (עמוס ג:ט):\",1,0],[2,135,15,17,\"מִשּׁוֹר אָבוּס. שֶׁאוֹבְסִין לוֹ הַמַּאֲכָל בְּפִיו עַל כָּרְחוֹ כְּדֵי לְפַטְּמוֹ, וְכֵן ״בַּרְבֻּרִים אֲבוּסִים״ (מלכים א ד:כג). וְיֵשׁ לְמוֹשְׁלוֹ כְּנֶגֶד קֹמֶץ מְעַט שֶׁל עָנִי שֶׁחָבִיב מִשּׁוֹר חַטָּאת שֶׁל רָשָׁע. דָּבָר אַחֵר: טוֹב אֲרֻחַת יָרָק לָתֵת לֶעָנִי, וְאַהֲבָה שָׁם לְהַרְאוֹת לוֹ פָּנִים יָפוֹת מִשּׁוֹר אָבוּס לְהַאֲכִילוֹ בָּשָׂר שָׁמֵן וְיַרְאֵנוּ פָּנִים זוֹעֲפוֹת:\",1,0],[2,135,15,18,\"אִישׁ חֵמָה יְגָרֶה מָדוֹן. אָדָם שֶׁאֵין מַעֲצוֹר לְרוּחוֹ לְהַאֲרִיךְ חֲמָתוֹ, יְגָרֶה מָדוֹן:\",1,0],[2,135,15,18,\"וְאֶרֶךְ אַפַּיִם. שֶׁאֵינוֹ מְמַהֵר לְהִנָּקֵם וְלָרִיב:\",2,0],[2,135,15,18,\"יַשְׁקִיט רִיב. שֶׁהוּא כָּלֶה וְשָׁקַט מֵעָלָיו (  מֵאֵלָיו):\",3,0],[2,135,15,19,\"דֶּרֶךְ עָצֵל כִּמְשׂוּכַת חָדֶק. דּוֹמֶה בְּעֵינָיו כְּאִלּוּ הַדְּרָכִים גְּדוּרִים לְפָנָיו בְּגֶדֶר חֲדָקִים:\",1,0],[2,135,15,19,\"מְשׂוּכַת. גָּדֵר, כְּמוֹ ״הָסֵר מְשׂוּכָתוֹ״ (ישעיה ה:ה). חָדֶק – קוֹצִים:\",2,0],[2,135,15,19,\"וְאֹרַח יְשָׁרִים סְלוּלָה. כְּבוּשָׁה וּמוּפְנָה. וּמִדְרַשׁ אַגָּדָה (תנחומא, כי תשא א): דַּרְכּוֹ שֶׁל עֵשָׂו כְּקוֹץ זֶה הַנִּסְבָּךְ בְּגִזַּת צֶמֶר, אִם תִּטְּלֵהוּ מִכָּאן, הוּא מִתְעָרֶה בְּכָאן; כָּךְ אֵין אָדָם יָכוֹל לָצֵאת יְדֵי עֲלִילוֹתָיו בְּלֹא מָמוֹן:\",3,0],[2,135,15,20,\"בֵּן חָכָם יְשַׂמַּח אָב וּכְסִיל אָדָם בּוֹזֶה אִמּוֹ. גּוֹרֵם לְאִמּוֹ שֶׁמְּבַזִּים אוֹתָהּ:\",1,0],[2,135,15,21,\"אִוֶּלֶת. שִׂמְחָה הִיא לַחֲסַר לֵב:\",1,0],[2,135,15,22,\"הָפֵר מַחֲשָׁבוֹת בְּאֵין סוֹד. בְּלֹא עֵצָה לֹא תָקוּם מַחֲשָׁבָה:\",1,0],[2,135,15,23,\"שִׂמְחָה לָאִישׁ בְּמַעֲנֵה פִיו. כְּמַשְׁמָעוֹ: עַל יְדֵי מַעֲנֶה רַךְ וְדִבּוּר נַחַת, הַבְּרִיּוֹת אוֹהֲבִים אוֹתוֹ. וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ עַל בַּעֲלֵי גִּירְסָא (סנהדרין קא.): אִם מוֹצְאִים בְּפִיהֶם מַעֲנֶה, אָז תִּתְקַיֵּם בָּם וְיִשְׂמְחוּ:\",1,0],[2,135,15,23,\"וְדָבָר בְּעִתּוֹ מַה טּוֹב. שׁוֹאֲלִים בְּהִלְכוֹת הַפֶּסַח וּבְהִלְכוֹת הֶחָג בִּזְמַנּוֹ (פסחים ו.):\",2,0],[2,135,15,24,\"אֹרַח חַיִּים לְמַעְלָה לְמַשְׂכִּיל. כְּמוֹ ״שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ״ (ישעיהו ו:ב), כְּלוֹמַר: לִפְנֵי הֶחָכָם קְשׁוּטָה וּמוּכָנָה אֹרַח חַיִּים:\",1,0],[2,135,15,27,\"עוֹכֵר בֵּיתוֹ. שֶׁהוּא בּוֹצֵעַ בָּצַע:\",1,0],[2,135,15,27,\"וְשׂוֹנֵא מַתָּנוֹת יִחְיֶה. מֵאַחַר שֶׁהוּא שׂוֹנֵא מַתָּנוֹת, כָּל שֶׁכֵּן שֶׁשּׂוֹנֵא אֶת הַגָּזֵל:\",2,0],[2,135,15,28,\"לֵב צַדִּיק יֶהְגֶּה לַעֲנוֹת. יַחְשֹׁב וְיָבִין מַה יַּעֲנֶה, קֹדֶם שֶׁיָּשִׁיב דָּבָר:\",1,0],[2,135,15,30,\"מְאוֹר עֵינַיִם. בַּתּוֹרָה:\",1,0],[2,135,15,30,\"יְשַׂמַּח לֵב. שֶׁשּׁוֹאֲלִין מִמֶּנּוּ דָּבָר וְיוֹדֵעַ מַה לְּהָשִׁיב. וּלְפִי פְּשׁוּטוֹ כְּמַשְׁמָעוֹ: דָּבָר שֶׁהוּא תַּאֲוָה לְמַרְאוֹת עֵינַיִם, יְשַׂמַּח הַלֵּב וּמְצַחְצֵחַ תּוּגַת הַלֵּב, כְּגוֹן גַּן יָרָק וּנְהָרוֹת הַמּוֹשְׁכִים:\",2,0],[2,135,15,33,\"וְלִפְנֵי כָבוֹד עֲנָוָה. הָעֲנָוָה גּוֹרֶמֶת שֶׁהַכָּבוֹד בָּא:\",1,0],[2,135,16,1,\"לְאָדָם מַעַרְכֵי לֵב. הוּא סוֹדֵר עֲצָתוֹ וּדְבָרָיו בְּלִבּוֹ:\",1,0],[2,135,16,1,\"וּמֵה׳ מַעֲנֵה לָשׁוֹן. כְּשֶׁבָּא לְהָשִׁיב, הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׂכִּילוֹ בִּדְבָרָיו, אוֹ אִם זָכָה מְזַמֵּן לוֹ מַעֲנֶה טוֹב:\",2,0],[2,135,16,2,\"וְתֹכֵן רוּחוֹת ה׳. וּמוֹנֶה הַלְּבָבוֹת, מִי הַטּוֹב וּמִי הָרָע:\",1,0],[2,135,16,3,\"גֹּל אֶל ה׳ מַעֲשֶׂיךָ. גַּלְגֵּל וְהַשְׁלֵךְ עָלָיו צְרָכֶיךָ וְיִכֹּנוּ מַחְשְׁבֹתֶיךָ. דָּבָר אַחֵר: גֹּל אֶל ה׳ מַעֲשֶׂיךָ, הִתְפַּלֵּל לְפָנָיו עַל כָּל צְרָכֶיךָ:\",1,0],[2,135,16,3,\"וְיִכֹּנוּ. יִתְבַּסְּסוּ וְיִתְקַיְּמוּ:\",2,0],[2,135,16,4,\"כֹּל פָּעַל ה׳ לְמַעֲנֵהוּ. הַכֹּל עָשָׂה בִּשְׁבִיל קִלּוּסוֹ, כְּמוֹ ״עֱנוּ לַה׳ בְּתוֹדָה״ (תהלים קמז:ז). דָּבָר אַחֵר: לְהָעִיד עָלָיו, כְּלוֹמַר: פָּעֳלוֹ מֵעִיד עָלָיו עַל גְּבוּרוֹתָיו. שְׁנֵיהֶם בְּהַגָּדַת תְּהִלִּים:\",1,0],[2,135,16,4,\"וְגַם רָשָׁע. עָשָׂה לְהַנִּיחוֹ לְיוֹם רָעָה, וְכָל זֶה לְקִלּוּסוֹ:\",2,0],[2,135,16,5,\"יָד לְיָד לֹא יִנָּקֶה. מִיָּד לְיָד בָּא לוֹ גְּמוּל גֹּבַהּ לִבּוֹ:\",1,0],[2,135,16,6,\"וּבְיִרְאַת ה׳ סוּר מֵרָע. עַל יְדֵי יִרְאַת ה׳ סוּר מֵרָע:\",1,0],[2,135,16,7,\"בִּרְצוֹת ה׳ דַּרְכֵי אִישׁ גַּם אוֹיְבָיו יַשְׁלִם אִתּוֹ. יֵרָצֶה לוֹ שֶׁיִּהְיוּ שְׁלֵמִים עִמּוֹ:\",1,0],[2,135,16,9,\"לֵב אָדָם יְחַשֵּׁב דַּרְכּוֹ. לָלֶכֶת דֶּרֶךְ יָשָׁר:\",1,0],[2,135,16,9,\"וַה׳ יָכִין צַעֲדוֹ. כְּמוֹ שֶׁשָּׁנִינוּ (שבת קד.): הַבָּא לִטָּהֵר מְסַיְּעִין לוֹ:\",2,0],[2,135,16,10,\"קֶסֶם עַל שִׂפְתֵי מֶלֶךְ. עַל שִׂפְתֵי חָכָם הַיּוֹשֵׁב בְּדִין:\",1,0],[2,135,16,11,\"פֶּלֶס וּמֹאזְנֵי מִשְׁפָּט וְגוֹ׳. לְשַׁלֵּם לָאָדָם כְּפָעֳלוֹ, מִשְׁפָּט יוּשְׁטִיצָ״ה בְּלַעַ״ז, פֵּרָעוֹן עֲוֹנוֹת הָאָדָם בְּפֶלֶס וּמֹאזְנַיִם:\",1,0],[2,135,16,11,\"מַעֲשֵׂהוּ כָּל אַבְנֵי כִיס. כַּאֲשֶׁר יֵשׁ בְּאַבְנֵי כִיס מִשְׁקָלוֹת גְּדוֹלוֹת וּקְטַנּוֹת, הַכֹּל לְפִי פָּעֳלוֹ שֶׁל אָדָם:\",2,0],[2,135,16,12,\"תּוֹעֲבַת מְלָכִים עֲשׂוֹת רֶשַׁע. דָּבָר תָּעוּב הוּא לַדַּיָּנִין וְאֵין הָגוּן לָהֶם לַעֲשׂוֹת רֶשַׁע:\",1,0],[2,135,16,14,\"חֲמַת מֶלֶךְ. הוּא כְּמַלְאֲכֵי מָוֶת, כִּשְׁלוּחֵי מִיתָתָם:\",1,0],[2,135,16,14,\"וְאִישׁ חָכָם יְכַפְּרֶנָּה. יְפַיְּסֶנָּה:\",2,0],[2,135,16,15,\"בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים. מִי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַסְבִּיר לוֹ פָּנִים, חַיִּים הוּא לוֹ, לְכָךְ צָרִיךְ אָדָם לְיַשֵּׁר דַּרְכּוֹ לְפָנָיו:\",1,0],[2,135,16,15,\"וּרְצוֹנוֹ כְּעָב מַלְקוֹשׁ. מִי שֶׁהוּא מְרֻצֶּה לוֹ, רְצוֹנוֹ טוֹב לוֹ כְּעָב הַמֵּבִיא אֶת הַמָּטָר:\",2,0],[2,135,16,19,\"טוֹב שְׁפַל רוּחַ. טוֹב לְהִתְחַבֵּר אֶת עֲנָוִים וְלִהְיוֹת אִתָּם שְׁפַל רוּחַ, מִהֱיוֹת מְחַלֵּק שָׁלָל אֶת גֵּאִים:\",1,0],[2,135,16,20,\"מַשְׂכִּיל עַל דָּבָר יִמְצָא טוֹב. הַנּוֹתֵן לֵב לְהִתְבּוֹנֵן עַל דְּבָרָיו לְפַלֵּס אֶת דְּרָכָיו יִמְצָא טוֹב:\",1,0],[2,135,16,20,\"וּבוֹטֵחַ בַּה׳ אַשְׁרָיו. כְּשֶׁהוּא מְפַלֵּס דְּרָכָיו וְרוֹאֶה בָּהּ מִצְוָה שֶׁיֵּשׁ בָּהּ סַכָּנָה אוֹ חֶסְרוֹן כִּיס, וּבוֹטֵחַ בְּהַקָּדוֹשׁ בָּרוּךְ הוּא וְעוֹשֶׂה הַטּוֹב:\",2,0],[2,135,16,20,\"אַשְׁרָיו. הֵן אֲשׁוּרָיו שֶׁלּוֹ:\",3,0],[2,135,16,21,\"לַחֲכַם לֵב יִקָּרֵא נָבוֹן. שֶׁלָּמַד חָכְמָה מֵרַבּוֹ:\",1,0],[2,135,16,21,\"יִקָּרֵא נָבוֹן. סוֹפוֹ שֶׁיִּהְיֶה נָבוֹן בִּדְבָרִים, מְפֻלְפָּל בְּחָכְמָתוֹ, וְיִקְרְאוּ אוֹתוֹ נָבוֹן:\",2,0],[2,135,16,21,\"וּמֶתֶק שְׂפָתַיִם יוֹסִיף לֶקַח. כְּשֶׁאָדָם מַטְעִים דְּבָרָיו לְתַלְמִיד וּמַמְתִּיק דְּבָרָיו בִּטְעָמִים, יוֹסִיף לֶקַח:\",3,0],[2,135,16,22,\"מְקוֹר חַיִּים שֵׂכֶל. לִבְעָלָיו וְכֵן פִּתְרוֹן הַמִּקְרָא: שֵׂכֶל הַבְּעָלִים מְקוֹר חַיִּים הוּא לוֹ:\",1,0],[2,135,16,22,\"וּמוּסַר אֱוִילִים אִוֶּלֶת. יִסּוּרֵי אֱוִילִים עַל יְדֵי אִוֶּלֶת בָּאִים לָהֶם, וְכֵן מַשְׁמָעוֹ: הָאִוֶּלֶת יִסּוּרִין הוּא לָאֱוִילִים:\",2,0],[2,135,16,23,\"לֵב חָכָם יַשְׂכִּיל פִּיהוּ. לִבּוֹ מְלַמֵּד אֶת פִּיו לְדַבֵּר צָחוֹת. (וְעַל שְׂפָתָיו יוֹסִיף לִבּוֹ לֶקַח):\",1,0],[2,135,16,24,\"צוּף דְּבַשׁ. מְתוֹק דְּבַשׁ, בְּרִישְׁקָ״ה בְּלַעַ״ז:\",1,0],[2,135,16,24,\"אִמְרֵי נֹעַם. דִּבְרֵי תוֹרָה:\",2,0],[2,135,16,25,\"יֵשׁ דֶּרֶךְ. שֶׁהוּא יָשָׁר לִפְנֵי אִישׁ:\",1,0],[2,135,16,26,\"עָמְלָה לוֹ. לְצָרְכּוֹ הוּא עָמֵל:\",1,0],[2,135,16,26,\"כִּי אָכַף עָלָיו פִּיהוּ. כְּשֶׁפִּיהוּ כּוֹפֵהוּ וְתוֹבֵעַ לוֹ מַאֲכָל, אָז עֲמָלוֹ עוֹמֶדֶת לוֹ, שֶׁאָכַל מַה שֶּׁעָמַל כְּבָר:\",2,0],[2,135,16,27,\"כּוֹרֶה רָעָה. בְּלִבּוֹ חוֹרֵשׁ הָרָע:\",1,0],[2,135,16,27,\"וְעַל. שְׂפָתָיו כְּאֵשׁ צָרָבֶת הָרָעָה כְּאֵשׁ שׂוֹרֶפֶת עַל שְׂפָתָיו, עַד שֶׁמּוֹצִיאָהּ בְּפִיו וְגוֹמְרָהּ:\",2,0],[2,135,16,27,\"כְּאֵשׁ צָרָבֶת. שׂוֹרֶפֶת, כְּמוֹ ״וְנִצְרְבוּ בָהּ כָּל פָּנִים״ (יחזקאל כא:ג):\",3,0],[2,135,16,28,\"וְנִרְגָּן מַפְרִיד אַלּוּף. וְעַל יְדֵי רִיגּוּנוֹ וְתַרְעוֹמְתּוֹ מַפְרִיד מִמֶּנּוּ אַלּוּפוֹ שֶׁל עוֹלָם (בראשית רבה כ:ב):\",1,0],[2,135,16,30,\"עוֹצֶה עֵינָיו. לְשׁוֹן קְרִיצָה, וְכֵן ״אִיעֲצָה עָלֶיךָ עֵינִי״ (תהילים לב:ח):\",1,0],[2,135,16,30,\"כִּלָּה רָעָה. כְּמוֹ ״כִּי כָלְתָה אֵלָיו הָרָעָה וְגוֹמֵר״ (אסתר ז:ז), וְגוֹרֵם לָבֹא רָעָה לָעוֹלָם:\",2,0],[2,135,16,31,\"בְּדֶרֶךְ צְדָקָה תִּמָּצֵא. עַל יְדֵי הַצְּדָקָה מַאֲרִיכִין יְמֵיהֶם:\",1,0],[2,135,16,32,\"וּמוֹשֵׁל בְּרוּחוֹ. כּוֹבֵשׁ אֶת יִצְרוֹ (אבות ד:א):\",1,0],[2,135,16,33,\"בַּחֵיק יוּטַל אֶת הַגּוֹרָל. בֵּינוֹ לְבֵין עַצְמוֹ אָדָם מֵטִיל גּוֹרָל:\",1,0],[2,135,16,33,\"וּמֵה׳ כָּל מִשְׁפָּטוֹ. לִבְרוֹר לְכָל אֶחָד וְאֶחָד חֶלְקוֹ:\",2,0],[2,135,17,1,\"טוֹב פַּת חֲרֵבָה וְשַׁלְוָה בָהּ. טוֹב הָיָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲרִיב בֵּיתוֹ וְעִירוֹ, וְהָיָה בְשַׁלְוָה מֵעֲבֵירוֹתֵיהֶן שֶׁל יִשְׂרָאֵל:\",1,0],[2,135,17,1,\"מִבַּיִת מָלֵא זִבְחֵי רִיב. שֶׁהָיוּ מַקְרִיבִין זִבְחֵי רִיב בְּבֵיתוֹ:\",2,0],[2,135,17,2,\"עֶבֶד מַשְׂכִּיל וְגוֹ׳. עַל שֶׁהִשְׂכִּיל נְבוּכַדְנֶצַּר לִפְסֹעַ שָׁלֹשׁ פְּסִיעוֹת לִכְבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, עָלָה לִגְדֻלָּה וּמָשַׁל בְּיִשְׂרָאֵל, שֶׁהוֹבִישׁוּ מַעֲשֵׂיהֶם וְחָלַק נַחֲלָתָם לְעֵינֵיהֶם. דָּבָר אַחֵר: גֵּר צֶדֶק טוֹב מֵאֶזְרָח רָשָׁע, וְלֶעָתִיד לָבוֹא יְחַלֵּק שָׁלָל וְנַחֲלָה בְּתוֹךְ בְּנֵי יִשְׂרָאֵל, שֶׁנֶּאֱמַר ״וְהָיָה בַשֵּׁבֶט אֲשֶׁר גָּר הַגֵּר וְגוֹ׳״ (יחזקאל מז:כג):\",1,0],[2,135,17,3,\"מַצְרֵף לַכֶּסֶף. כְּלִי שֶׁצּוֹרְפִין בּוֹ כֶּסֶף וְעוֹשִׂין אוֹתוֹ מֵאֵפֶר מִקְלֶה עַל גַּבֵּי חֶרֶס, קָרוּי מַצְרֵף:\",1,0],[2,135,17,3,\"וְכוּר לַזָּהָב. כְּלִי שֶׁצּוֹרְפִין בּוֹ אֶת הַזָּהָב, כְּלִי שֶׁזּוֹקְקִין בּוֹ אֶת הַזָּהָב, כְּמוֹ קְדֵרָה שְׁבוּרָה, קְרוּיָה כּוּר:\",2,0],[2,135,17,3,\"מַצְרֵף לַכֶּסֶף וְכוּר לַזָּהָב. הַמַּצְרֵף עָשׂוּי לִצְרֹף כֶּסֶף לִמְלַאכְתּוֹ וְכֵן הַכּוּר לְזַקֵּק הַזָּהָב, אֲבָל הַלְּבָבוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא זוֹקְקָן וּבוֹחֲנָן וְיוֹדֵעַ מַחְשְׁבוֹתָן:\",3,0],[2,135,17,4,\"מֵרַע. רָשָׁע:\",1,0],[2,135,17,4,\"מַקְשִׁיב עַל שְׂפַת אָוֶן שֶׁקֶר. מְקַבֵּל לָשׁוֹן הָרָע וְעֵדֵי שֶׁקֶר:\",2,0],[2,135,17,4,\"מֵזִין. מַאֲזִין, מִי שֶׁהוּא מְשַׁקֵּר מַאֲזִין עַל לְשׁוֹן הַוֺּת:\",3,0],[2,135,17,6,\"עֲטֶרֶת זְקֵנִים. כְּשֶׁרוֹאִים בְּנֵי בְנֵיהֶם הוֹלְכִין בְּדֶרֶךְ טוֹבָה:\",1,0],[2,135,17,6,\"וְתִפְאֶרֶת בָּנִים אֲבוֹתָם. כְּשֶׁאֲבוֹתֵיהֶם צַדִּיקִים, הִיא תִּפְאֶרֶת הַבָּנִים:\",2,0],[2,135,17,7,\"שְׂפַת יֶתֶר. דִּבְרֵי גַּאֲוָה:\",1,0],[2,135,17,7,\"אַף כִּי לְנָדִיב. וְכָל שֶׁכֵּן שֶׁלֹּא נָאֶה שְׂפַת שֶׁקֶר לְנָדִיב:\",2,0],[2,135,17,8,\"אֶבֶן חֵן. כְּשֶׁהָאָדָם בָּא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְפַיְּסוֹ בִּדְבָרִים וְשָׁב לוֹ, אֶבֶן חֵן וּמַרְגָּלִיּוֹת הִיא בְּעֵינָיו:\",1,0],[2,135,17,8,\"אֶל כָּל אֲשֶׁר יִפְנֶה יַשְׂכִּיל. בְּכָל מַה שֶּׁיְּבַקֵּשׁ מִמֶּנּוּ מַצְלִיחוֹ:\",2,0],[2,135,17,9,\"מְכַסֶּה פֶּשַׁע מְבַקֵּשׁ אַהֲבָה. אִם יֶחֱטָא אִישׁ לְאִישׁ, וְזֶה מְכַסֶּה עָלָיו וְאֵינֶנּוּ מַזְכִּיר לוֹ חַטָּאתוֹ וְאֵינוֹ מַרְאֶה לוֹ פָּנִים זוֹעֲמוֹת, גּוֹרֵם לוֹ שֶׁיֹּאהַב אוֹתוֹ:\",1,0],[2,135,17,9,\"וְשׁוֹנֶה בְדָבָר. שֶׁנּוֹטֵר אֵיבָה וּמַזְכִּירוֹ: כָּךְ וְכָךְ עָשִׂיתָ לִי! מִיָּד:\",2,0],[2,135,17,9,\"מַפְרִיד אַלּוּף. אָז מַפְרִיד מִמֶּנּוּ אַלּוּפוֹ שֶׁל עוֹלָם שֶׁהוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִזְהִירוֹ ״לֹא תִקֹּם וְלֹא תִטֹּר״ (ויקרא יט:יח):\",3,0],[2,135,17,10,\"תֵּחַת גְּעָרָה בְמֵבִין. תַּחַת זוֹ טַעֲמוֹ לְמַעְלָה בַּתָּי״ו, מַה שֶּׁאֵין כֵּן בְּכָל הַמִּקְרָא, לְכָךְ אֲנִי אוֹמֵר שֶׁהִיא שֵׁם דָּבָר כְּמוֹ ״חִתַּת״ (בראשית לה:ה), וְכֵן פֵּרוּשׁוֹ: הַכְנָעַת גְּעָרָה נִכֶּרֶת בְּמֵבִין יוֹתֵר מִמֵּאָה מַכּוֹת שֶׁמַּכִּין אֶת הַכְּסִיל:\",1,0],[2,135,17,11,\"אַךְ מְרִי יְבַקֶּשׁ רָע. כְּלוֹמַר: מִי שֶׁכָּל דְּבָרָיו מְרִי וְסַרְבָנוּת הוּא יְבַקֵּשׁ רָע תָּמִיד:\",1,0],[2,135,17,12,\"פָּגוֹשׁ דֹּב שַׁכּוּל בְּאִישׁ. טוֹב לָאָדָם שֶׁיִּפְגַּע בּוֹ דֹּב מְשַׁכֵּל, וְאַל יִפְגַּע בּוֹ אֶחָד מִן הַכְּסִילִים הַמְּסִיתִים אוֹתוֹ לָסוּר מֵה׳ וּמִתּוֹרָתוֹ:\",1,0],[2,135,17,14,\"פּוֹטֵר מַיִם רֵאשִׁית מָדוֹן. הַמַּתְחִיל בִּמְרִיבָה הוּא כְּפוֹתֵחַ חוֹר בְּגִדְרֵי אַגְפֵי אַמַּת הַמַּיִם וְהַמַּיִם יוֹצְאִין בּוֹ, וְהַחוֹר הוֹלֵךְ וּמַרְחִיב. כֵּן הַמָּדוֹן הוֹלֵךְ וְגָדֵל תָּמִיד:\",1,0],[2,135,17,14,\"וְלִפְנֵי הִתְגַּלַּע. קוֹדֶם שֶׁתִּתְגַּלַּע חֶרְפָּתְךָ נְטוֹשׁ אֶת הָרִיב (סנהדרין ו:):\",2,0],[2,135,17,16,\"לָמָּה זֶּה מְחִיר בְּיַד כְּסִיל לִקְנוֹת חָכְמָה. לִלְמֹד תּוֹרָה:\",1,0],[2,135,17,16,\"וְלֶב אָיִן. וְאֵין בְּלִבּוֹ לְקַיְּמָהּ, וְאֵינוֹ לוֹמֵד תּוֹרָה אֶלָּא לִקְנוֹת שֵׁם:\",2,0],[2,135,17,17,\"בְּכָל עֵת אוֹהֵב הָרֵעַ. לְעוֹלָם הֱוֵי אוֹהֵב רֵעִים, לִקְנוֹת אוֹהֲבִים:\",1,0],[2,135,17,17,\"וְאָח לְצָרָה יִוָּלֵד. לְעֵת הַצָּרָה יִוָּלֵד לְךָ הָרֵעַ כְּאָח, לַעֲזֹר לְךָ וּלְהִשְׁתַּתֵּף בְּצָרָתְךָ:\",2,0],[2,135,17,18,\"אָדָם חֲסַר לֵב תּוֹקֵעַ כָּף. עֲרֵבוּת מָמוֹן. דָּבָר אַחֵר: תּוֹקֵעַ כַּף לָרְשָׁעִים כְּדֵי לָלֶכֶת בְּדַרְכֵיהֶם, וַהֲרֵי כְּבָר עֹרֵב עֲרֻבָּה לִפְנֵי רֵעֵהוּ. כְּבָר עָרַב לְהַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁמֹר מִצְווֹתָיו:\",1,0],[2,135,17,19,\"אוֹהֵב פֶּשַׁע. לִפְשׁוֹעַ בַּחֲבֵירוֹ:\",1,0],[2,135,17,19,\"אוֹהֵב מַצָּה. לְהִתְקוֹטֵט וְלָרִיב:\",2,0],[2,135,17,19,\"מַגְבִּיהַּ פִּתְחוֹ. מְדַבֵּר בְּגַאֲוָה, כְּמוֹ ״שְׁמֹר פִּתְחֵי פִיךָ״ (מיכה ז:ה):\",3,0],[2,135,17,22,\"לֵב שָׂמֵחַ יֵיטִיב גֵּהָה. כְּשֶׁהָאָדָם שָׂמֵחַ בְּחֶלְקוֹ, פָּנָיו מְאִירִין:\",1,0],[2,135,17,23,\"שֹׁחַד מֵחֵיק רָשָׁע יִקָּח. הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל דִּבְרֵי הַכְנָעָה וּפִיּוּס מֵחֵיק הָרְשָׁעִים, כְּלוֹמַר: בַּסֵּתֶר בֵּינוֹ לְבֵינָם:\",1,0],[2,135,17,23,\"לְהַטּוֹת אָרְחוֹת מִשְׁפָּט. לַהֲפֹךְ דִּינוֹ מֵרָעָה לְטוֹבָה:\",2,0],[2,135,17,24,\"אֶת פְּנֵי מֵבִין חָכְמָה. הַחָכְמָה לִפְנֵי מֵבִין הוּא:\",1,0],[2,135,17,24,\"וְעֵינֵי כְסִיל בִּקְצֵה אָרֶץ. לוֹמַר: אֵין הַחָכְמָה מְצוּיָה לְפָנַי כִּי רְחוֹקָה הִיא מִמֶּנִּי, אֵיךְ אוּכַל לִשְׁנוֹת סֵדֶר נְזִיקִין שֶׁהוּא שְׁלֹשִׁים פְּרָקִים, מַסֶּכֶת כֵּלִים – שְׁלֹשִׁים פְּרָקִים, מַסֶּכֶת שַׁבָּת – עֶשְׂרִים וְאַרְבָּעָה פְּרָקִים. אֲבָל לֶחָכָם הוּא דָּבָר קַל: הַיּוֹם שׁוֹנֶה שְׁנֵי פְרָקִים וּמָחָר שְׁנַיִם, וְאוֹמֵר: כָּךְ עָשׂוּ אוֹתָן שֶׁהָיוּ לְפָנַי מֵעוֹלָם:\",2,0],[2,135,17,25,\"כַּעַס לְאָבִיו בֵּן כְּסִיל. כְּגוֹן יָרָבְעָם כַּעַס הוּא לְהַקָּדוֹשׁ בָּרוּךְ הוּא (מלכים א יב:כו-לג):\",1,0],[2,135,17,25,\"וּמֶמֶר לְיוֹלַדְתּוֹ. לִכְנֶסֶת יִשְׂרָאֵל, שֶׁהֶחֱטִיא אוֹתָם:\",2,0],[2,135,17,26,\"גַּם עֲנוֹשׁ לַצַּדִּיק לֹא טוֹב. לֹא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לִמְחוֹת שֵׁם יִשְׂרָאֵל מֵעַל הָאָרֶץ, כִּי לֹא טוֹב בְּעֵינָיו לַעֲנוֹשׁ כֻּלָּם:\",1,0],[2,135,17,26,\"לְהַכּוֹת נְדִיבִים עַל יֹשֶׁר. לְהַכּוֹת הַטּוֹבִים שֶׁבָּהֶם שֶׁהָיוּ נְדִיבִים עֲלֵי יֹשֶׁר, שֶׁנֶּאֱמַר: ״וְהִשְׁאַרְתִּי בְיִשְׂרָאֵל שִׁבְעַת אֲלָפִים כָּל הַבִּרְכַּיִם אֲשֶׁר לֹא כָרְעוּ לַבַּעַל״ (מלכים א יט:יח):\",2,0],[2,135,17,26,\"נְדִיבִים עַל יֹשֶׁר. דֻּגְמַת הָאָמוּר בְּמָקוֹם אַחֵר ״וְנָדִיב נְדִיבוֹת יָעָץ וְהוּא עַל נְדִיבוֹת יָקוּם״ (ישעיהו לב:ח), נִמְצָא ״נָדִיב״ עַל ״נְדִיבוֹת״:\",3,0],[2,135,17,27,\"חוֹשֵׂךְ אֲמָרָיו. מִי שֶׁהוּא יוֹדֵעַ דַּעַת אֵינוֹ מַרְבֶּה בִּדְבָרִים:\",1,0],[2,135,17,27,\"יְקַר רוּחַ. מוֹנֵעַ דְּבָרִים אִישׁ תְּבוּנָה:\",2,0],[2,135,18,1,\"לְתַאֲוָה יְבַקֵּשׁ נִפְרָד. מִי שֶׁהוּא נִפְרָד מֵהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא לִשְׁמֹר מִצְווֹתָיו, לְתַאֲוַת לִבּוֹ וְיִצְרוֹ הָרַע הוּא רוֹדֵף, וְסוֹף בְּכָל תּוּשִׁיָּה יִתְגַּלָּע. בֵּין חֲכָמִים תִּגָּלֶה חֶרְפָּתוֹ. וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ (נזיר כג:) בְּלוֹט שֶׁנִּפְרַד מֵאַבְרָהָם עַל תַּאֲוַת לִבּוֹ, שֶׁנֶּאֱמַר ״וַיִּבְחַר לוֹ לוֹט אֵת כָּל כִּכַּר הַיַּרְדֵּן״ (בראשית יג:יא). כָּל הַמִּקְרָא הַזֶּה עַל שֵׁם נִיאוּף נֶאֱמַר, וְסוֹפוֹ נִתְגַּלָּה קְלוֹנוֹ בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת: ״לֹא יָבֹא עַמּוֹנִי וּמוֹאָבִי״ (דברים כג:ד):\",1,0],[2,135,18,2,\"כִּי אִם בְּהִתְגַּלּוֹת לִבּוֹ. כִּי אִם בְּגִלּוּי לִבּוֹ, הוּא חָפֵץ לְגַלּוֹת מַה שֶּׁבְּלִבּוֹ:\",1,0],[2,135,18,3,\"וְעִם קָלוֹן. תָּבוֹא חֶרְפָּה – מִי שֶׁבּוֹחֵר בְּקָלוֹן וְנִאוּף, חֶרְפָּה הִיא לוֹ:\",1,0],[2,135,18,4,\"דִּבְרֵי פִי אִישׁ. כָּל אִישׁ שֶׁבַּמִּקְרָא לְשׁוֹן גִּבּוֹר גָּדוֹל בִּגְבוּרָה הוּא:\",1,0],[2,135,18,4,\"מְקוֹר חָכְמָה. כְּנַחַל נוֹבֵעַ וּכְמַיִם עֲמֻקִּים:\",2,0],[2,135,18,5,\"שְׂאֵת פְּנֵי רָשָׁע לֹא טוֹב. כַּאֲשֶׁר פֵּרְשׁוּ רַבּוֹתֵינוּ (יומא פז.): לֹא טוֹב לָהֶם לָרְשָׁעִים שֶׁנּוֹשְׂאִים לָהֶם פָּנִים בָּעוֹלָם הַזֶּה וְנִפְרָעִין מֵהֶן לָעוֹלָם הַבָּא:\",1,0],[2,135,18,5,\"טוֹב וְגוֹ׳. טוֹב לָהֶם לַצַּדִּיקִים שֶׁמַּכְרִיעִין לָהֶם כַּף מֹאזְנַיִם לְחַיְּבָם בָּעוֹלָם הַזֶּה וְנִפְרָעִין מֵהֶן בְּחַיֵּיהֶן לָעוֹלָם הַבָּא. וּלְפִי פְּשׁוּטוֹ – כְּמַשְׁמָעוֹ:\",2,0],[2,135,18,6,\"שִׂפְתֵי כְסִיל יָבֹאוּ בְרִיב. כָּל דְּבָרָיו בָּאִים בִּלְשׁוֹן תִּגְרָה:\",1,0],[2,135,18,6,\"וּפִיו לְמַהֲלֻמוֹת יִקְרָא. קוֹרֵא לְיִסּוּרִין לַהֲבִיאָם עָלָיו:\",2,0],[2,135,18,8,\"דִּבְרֵי נִרְגָּן כְּמִתְלַהֲמִים. מַהֲלוּמוֹת:\",1,0],[2,135,18,9,\"גַּם מִתְרַפֶּה בִמְלַאכְתּוֹ. פּוֹרֵשׁ מִן הַתּוֹרָה וְהוּא תַּלְמִיד חָכָם:\",1,0],[2,135,18,9,\"לְבַעַל מַשְׁחִית. לַשָּׂטָן:\",2,0],[2,135,18,10,\"מִגְדַּל עֹז שֵׁם ה׳ בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. וְהוּא מִתְחַזֵּק:\",1,0],[2,135,18,11,\"וּכְחוֹמָה נִשְׂגָּבָה. עָשְׁרוֹ לוֹ בְּחַדְרֵי מַשְׂכִּיתוֹ. מִפְּנֵי שֶׁהַבַּיִת נִרְצָף בְּרִצְפַּת אֲבָנִים הַסּוֹכְכִים עַל הָאָרֶץ, קָרוּי אֶבֶן מַשְׂכִּית:\",1,0],[2,135,18,14,\"רוּחַ אִישׁ. רוּחַ גֶּבֶר שֶׁהוּא אִישׁ גִּבּוֹר וְאֵינוֹ נוֹתֵן דְּאָגָה בְּלִבּוֹ וּמְקַבֵּל כָּל הַבָּא עָלָיו בְּשִׂמְחָה וּבְחִבָּה:\",1,0],[2,135,18,14,\"יְכַלְכֵּל מַחֲלֵהוּ. אֵין כֹּחוֹ סָר מֵעָלָיו:\",2,0],[2,135,18,16,\"מַתָּן אָדָם יַרְחִיב. כִּפְשׁוּטוֹ, וּמִדְרָשׁוֹ (במדבר רבה יג:יז): בְּנוֹתְנֵי צְדָקָה מְדַבֵּר, שֶׁמַּרְחִיב לוֹ חֶלְקוֹ לֶעָתִיד לָבוֹא, וְגַם בְּחַיָּיו לִפְנֵי גְדוֹלִים יַנְחֶנּוּ, וְאוֹמְרִים עָלָיו שֶׁהוּא חָשׁוּב:\",1,0],[2,135,18,18,\"וּבֵין עֲצוּמִים יַפְרִיד. אֵלּוּ בַּעֲלֵי דִינִין, כְּמוֹ ״הַגִּישׁוּ עֲצוּמוֹתֵיהֶם״ (ישעיה מא:כא). וּבַמִּשְׁנָה (סנהדרין לא:): שְׁנַיִם שֶׁנִּתְעַצְּמוּ בַדִּין. עַל שֵׁם שֶׁמְּרִיבוֹתָם עֲצוּמוֹת קְרוּיִים עֲצוּמִים, אוֹ לְשׁוֹן ׳חוֹזֶק׳ אוֹ לְשׁוֹן ׳אוֹטֶם׳, כְּמוֹ ״עֹצֵם עֵינָיו״ (ישעיה לג:טו):\",1,0],[2,135,18,19,\"אָח נִפְשָׁע מִקִּרְיַת עֹז. יֵשׁ אָח נִפְשָׁע מֵאָחִיו וּמְאַבֵּד בְּמִרְדּוֹ קִרְיַת עֹז, כְּגוֹן לוֹט בְּאַבְרָהָם (בראשית יג), עֵשָׂו בְּיַעֲקֹב (בראשית כז:מא-מג):\",1,0],[2,135,18,19,\"וּמִדְיָנִים כִּבְרִיחַ אַרְמוֹן. וּמְרִיבָה שֶׁבֵּינֵיהֶם מַפְרִידָתָם לְעוֹלָם כִּבְרִיחַ זֶה שֶׁנּוֹעֲלִים בּוֹ שַׁעֲרֵי אַרְמוֹן, שֶׁלֹּא יִכָּנְסוּ בּוֹ (נזיר כג,א-ב):\",2,0],[2,135,18,21,\"וְאֹהֲבֶיהָ יֹאכַל פִּרְיָהּ. אוֹהֵב אֶת לְשׁוֹנוֹ וּמַרְגִּיל לַתּוֹרָה אוֹכֵל שְׂכָרָהּ בָּעוֹלָם הַזֶּה (תנחומא, מצרע ב):\",1,0],[2,135,18,22,\"מָצָא אִשָּׁה מָצָא טוֹב. מָצָא תּוֹרָה, וּכְמַשְׁמָעוֹ: אִשָּׁה טוֹבָה:\",1,0],[2,135,18,22,\"וַיָּפֶק רָצוֹן. וְיוֹצִיא; זֶה פְּשׁוּטוֹ. דָּבָר אַחֵר: אָדָם שֶׁמָּצָא אִשָּׁה וּמָצָא טוֹב וַיָּפֶק רְצוֹנוֹ, אוֹתוֹ הָאִישׁ מוֹצִיא רָצוֹן מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי יוֹסֵף קָרָא:\",2,0],[2,135,18,23,\"תַּחֲנוּנִים יְדַבֶּר רָשׁ. דֶּרֶךְ זֶה בְּכָךְ וְדֶרֶךְ זֶה בְּכָךְ; לִמֶּדְךָ דֶּרֶךְ אֶרֶץ, שֶׁאַף עַל פִּי שֶׁעָשִׁיר יַעֲנֶה עַזּוֹת, הָרָשׁ יְדַבֵּר תַּחֲנוּנִים. וְכֵן הָעִנְיָן הָרַב לַתַּלְמִיד:\",1,0],[2,135,18,24,\"אִישׁ רֵעִים לְהִתְרֹעֵעַ. אָדָם שֶׁקּוֹנֶה לוֹ רֵעִים עוֹד יָבוֹא יוֹם שֶׁיִּצְטָרֵךְ לָהֶם וִיקָרְבֵהוּ. וְאִם תֹּאמַר: מַה בְּכָךְ – יֵשׁ אוֹהֵב דָּבֵק מֵאָח, שֶׁיְּקָרְבֵהוּ יוֹתֵר מִקְּרוֹבָיו וְאֶחָיו:\",1,0],[2,135,19,2,\"גַּם בְּלֹא דַעַת נֶפֶשׁ לֹא טוֹב. אֵין טוֹב לָאָדָם שֶׁהוּא בְּלֹא תּוֹרָה:\",1,0],[2,135,19,2,\"וְאָץ בְּרַגְלַיִם חוֹטֵא. הַחוֹטֵא רוֹפֵס וְדָשׁ הָעֲווֹנוֹת בַּעֲקֵבָיו, וְאוֹמֵר: קַל הוּא זֶה, אֶעֱבוֹר עָלָיו. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (עירובין ק:): גַּם בְּלֹא דַעַת, בְּכוֹפֶה אֶת אִשְׁתּוֹ לְתַשְׁמִישׁ הַמִּטָּה בְּעַל כָּרְחָהּ:\",2,0],[2,135,19,2,\"וְאָץ בְּרַגְלַיִם חוֹטֵא. זֶה הַבּוֹעֵל וְשׁוֹנֶה. דָּבָר אַחֵר: זֶה הַמְהַלֵּךְ עַל גַּבֵּי עֲשָׂבִים בְּשַׁבָּת (שבת צה.):\",3,0],[2,135,19,3,\"אִוֶּלֶת אָדָם תְּסַלֵּף דַּרְכּוֹ. בַּעֲוֹנוֹ בָּא לוֹ הָרָע, כִּי בְּאִוַּלְתּוֹ תְּסַלֵּף דַּרְכּוֹ וְעָבַר עֲבֵירוֹת וְנִפְרָעִין מִמֶּנּוּ, וּבְבוֹא לוֹ הַצָּרָה זוֹעֵף לִבּוֹ עַל הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְמַהֵר אַחַר מִדַּת הַדִּין, כְּגוֹן אֲחֵי יוֹסֵף שֶׁאָמְרוּ ״מַה זֹּאת עָשָׂה אֱלֹהִים לָנוּ״ (בראשית מב:כח):\",1,0],[2,135,19,4,\"הוֹן יוֹסִיף רֵעִים רַבִּים. אוֹהֲבִים רַבִּים. וְיֵשׁ לְפוֹתְרוֹ בְּמִי שֶׁלָּמַד תּוֹרָה:\",1,0],[2,135,19,6,\"רַבִּים יְחַלּוּ פְנֵי נָדִיב וְכָל הָרֵעַ. הַכֹּל נַעֲשִׂים רֵעִים לְאִישׁ מַתָּן. יֵשׁ לְפוֹתְרוֹ בְּנוֹתְנֵי צְדָקָה וְיֵשׁ לְפוֹתְרוֹ בְּמַרְבִּיצֵי תוֹרָה:\",1,0],[2,135,19,7,\"כָּל אֲחֵי רָשׁ. קְרוֹבָיו:\",1,0],[2,135,19,7,\"אַף כִּי מֵרֵעֵהוּ רָחֲקוּ. וְכָל שֶׁכֵּן מֵרֵעָיו וְשׁוֹשְׁבִינָיו וְאוֹהֲבָיו:\",2,0],[2,135,19,7,\"מְרַדֵּף אֲמָרִים. לֹא הֵמָּה אוֹמֵר: פְּלוֹנִי וּפְלוֹנִי קְרוֹבַי, וּפְלוֹנִי וּפְלוֹנִי מֵרֵעַי, וְהַכֹּל דִּבְרֵי הֶבֶל. וְיֵשׁ לְפוֹתְרוֹ בְּמִי שֶׁהוּא רָשׁ בַּתּוֹרָה וּבְמַעֲשִׂים טוֹבִים:\",3,0],[2,135,19,7,\"מְרַדֵּף אֲמָרִים לֹא הֵמָּה. מְחַזֵּר לְהוֹרוֹת הֲלָכָה וְלָאו בְּיָדוֹ, וְהַמִּדְרָשׁ פּוֹתְרוֹ בְּיוֹסֵף שֶׁהָיָה מוֹצִיא עַל אֶחָיו דִּבָּה, וְאָמַר לְאָבִיו שֶׁהֵן חֲשׁוּדִין עַל אֵבֶר מִן הַחַי, לְכָךְ שְׂנֵאוּהוּ וְנִקְרָא רָשׁ לְפִי שֶׁהָיָה מוֹצִיא דִּבַּת שֶׁקֶר עֲלֵיהֶם. וּמְחַזֵּר אַחַר אֲמָרִים לֹא הֵמָּה. לוֹ קְרִינָן וּמְרַדֵּף אֲמָרִים לַהֲנָאָתוֹ, וּלְעִנְיַן יוֹסֵף לוֹ הֵמָּה, כִּי עָלָיו חָזְרוּ דִּבָּתוֹ הוּא הָיָה אוֹמֵר שֶׁהָיוּ אוֹכְלִים אֵבֶר מִן הַחַי וְהַכָּתוּב מֵעִיד עֲלֵיהֶם אֲפִלּוּ בִּשְׁעַת הַקַּלְקָלָה הָיוּ שׁוֹחֲטִין שְׂעִיר עִזִּים שֶׁנֶּאֱמַר ״וַיִּשְׁחֲטוּ שְׂעִיר עִזִּים״ (בראשית לז:לא). הוּא אָמַר שֶׁהָיוּ מְזַלְזְלִין בִּבְנֵי הַשְּׁפָחוֹת לְכָךְ ״לְעֶבֶד נִמְכַּר יוֹסֵף״ (תהלים קה:יז), הוּא אָמַר שֶׁהָיוּ נוֹתְנִים עֵינֵיהֶם בִּבְנוֹת הָאָרֶץ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא חַיֶּיךָ שֶׁאֲנִי מְגָרֶה בְּךָ אֶת הַדֹּב לְכָךְ ״וַתִּשָּׂא אֵשֶׁת אֲדֹנָיו וְגוֹ׳״ (בראשית לט:ז) (בראשית רבה פד:ז):\",4,0],[2,135,19,10,\"לֹא נָאוֶה לִכְסִיל תַּעֲנוּג אַף כִּי לְעֶבֶד. קַל וָחֹמֶר הוּא, שֶׁאֵין נָאֶה שֶׁעֶבֶד יִמְשֹׁל בִּנְדִיבִים:\",1,0],[2,135,19,11,\"שֵׂכֶל אָדָם הֶאֱרִיךְ אַפּוֹ. כְּמוֹ לְהַאֲרִיךְ, אִם עָשָׂה כֵּן שֵׂכֶל הוּא לוֹ:\",1,0],[2,135,19,11,\"וְתִפְאַרְתּוֹ. הוּא שֶׁיַּעֲבֹר עַל מִדּוֹתָיו:\",2,0],[2,135,19,12,\"נַהַם כַּכְּפִיר זַעַף מֶלֶךְ. הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,135,19,13,\"וְדֶלֶף טוֹרֵד. דֶּלֶף גְּשָׁמִים הַיּוֹרֵד בַּבַּיִת וּמַטְרִיחַ וְטוֹרֵד לְיוֹשְׁבֵי הַבַּיִת, כָּךְ מִדְיְנֵי אִשָּׁה רָעָה:\",1,0],[2,135,19,15,\"עַצְלָה תַּפִּיל תַּרְדֵּמָה. הָעַצְלוּת מְבִיאָה לִידֵי שֵׁינָה, זוֹ הִיא הַמְּלִיצָה. אֲבָל הַמָּשָׁל – עַל הַמִּתְעַצֵּל בְּתַלְמוּדוֹ; סוֹף שֶׁשּׁוֹאֲלִין דְּבַר חָכְמָה מִמֶּנּוּ וְהוּא נִרְדָּם:\",1,0],[2,135,19,15,\"וְנֶפֶשׁ רְמִיָּה תִרְעָב. סוֹף שֶׁיְּהֵא עָנִי; וְכֵן הָרַמַּאי בְּתַלְמוּדוֹ, לַעֲשׂוֹת תּוֹרָתוֹ חֲבִילוֹת, סוֹף שֶׁהוּא יִשְׁכַּח:\",2,0],[2,135,19,16,\"שׁוֹמֵר מִצְוָה שׁוֹמֵר נַפְשׁוֹ בּוֹזֵה דְרָכָיו יָמוּת. שֶׁאֵינוֹ נוֹתֵן לִבּוֹ לְשָׁקְלָן:\",1,0],[2,135,19,17,\"מַלְוֵה ה׳ חוֹנֵן דָּל וּגְמוּלוֹ יְשַׁלֶּם לוֹ. כְּשֶׁיֶּחֱלֶה וְיִטֶּה לָמוּת, צִדְקָתוֹ מְלִיצָה עָלָיו לִפְנֵי מִדַּת הַדִּין, לוֹמַר: הֶעָנִי הָיְתָה נַפְשׁוֹ מְפַרְכֶּסֶת לָצֵאת בָּרָעָב וְזֶה פִּרְנְסָהּ וְהֶחֱזִירָהּ לְגוּפָהּ, אַף אֲנִי אַחֲזִיר לוֹ נַפְשׁוֹ:\",1,0],[2,135,19,18,\"יַסֵּר בִּנְךָ כִּי יֵשׁ תִּקְוָה וְאֶל הֲמִיתוֹ אַל תִּשָּׂא נַפְשֶׁךָ. אַל תַּכֵּהוּ מַכַּת מָוֶת:\",1,0],[2,135,19,19,\"גְּדׇל חֵמָה נֹשֵׂא עֹנֶשׁ וְגוֹ׳. אִם תַּעֲבִיר עַל חֲמָתְךָ וְתַצִּיל אֶת שׂוֹנַאֲךָ אִם רָאִיתָ רָעָה בָּאָה לוֹ, עוֹד תּוֹסִיף יָמִים וְטוֹבָה:\",1,0],[2,135,19,22,\"תַּאֲוַת אָדָם חַסְדּוֹ. עִקָּר שֶׁהַבְּרִיּוֹת מִתְאַוִּים לָאָדָם בַּעֲבוּר חַסְדּוֹ:\",1,0],[2,135,19,22,\"וְטוֹב רָשׁ מֵאִישׁ כָּזָב. וְאִם אִישׁ כָּזָב הוּא וּמַבְטִיחַ וְאֵינוֹ עוֹשֶׂה, טוֹב אִישׁ רָשׁ מִמֶּנּוּ:\",2,0],[2,135,19,23,\"וְשָׂבֵעַ יָלִין. הַיָּרֵא אֶת הַשֵּׁם, שֶׁלֹּא יִפָּקֶד בְּשׁוּם רָעָה:\",1,0],[2,135,19,24,\"טָמַן עָצֵל יָדוֹ בַּצַּלָּחַת. בְּיוֹרָה חַמָּה, שֶׁכְּשֶׁיַּעַבְרוּהָ מִן הָאוּר וּפִנּוּהָ רֵיקָנִית, מְחַמֵּם יָדוֹ בְּתוֹכָהּ. וְדוֹמֶה לוֹ ״בִּשְּׁלוּ בַּסִּירוֹת וּבַדְּוָדִים וּבַצֵּלָחוֹת״ (דברי הימים ב לה:יג). וּמִשּׁוּם רַבֵּינוּ יִצְחָק הַלֵּוִי שָׁמַעְתִּי: בַּצַּלָּחַת. מִלְּשׁוֹן תַּרְגּוּם ״וַיְבַקַּע״ (בראשית כב:ג): ״וְצָלַח״, בִּשְׁעַת הַצִּנָּה וְהַגְּלִיד, עַל שֵׁם שֶׁהַקּוֹר וְהַגְּלִיד מְבַקְּעִין וְצוֹלְחִים הַיָּדַיִם. וַאֲנִי שָׁמַעְתִּי: בַּצַּלָּחַת. קֶרַע הֶחָלוּק, שֶׁקּוֹרִין פאנדאדור״י בְּלַעַ״ז, כְּלוֹמַר: טוֹמְנָהּ בְּחֵיקוֹ (סא״א):\",1,0],[2,135,19,25,\"לֵץ תַּכֶּה וּפֶתִי יַעְרִם. עַל מַכּוֹת פַּרְעֹה וּמִלְחֶמֶת עֲמָלֵק הֶחְכִּים יִתְרוֹ וְנִתְגַּיֵּר (תנחומא, יתרו ג):\",1,0],[2,135,19,26,\"מְשַׁדֶּד אָב יַבְרִיחַ אֵם. מַבְרִיחַ אֵם:\",1,0],[2,135,19,26,\"בֵּן מֵבִישׁ וּמַחְפִּיר. דְּרָכָיו. עַל יְדֵי שֶׁרָאֲתָה שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית מְשַׂחֵק לַעֲבוֹדַת גִּלּוּלִים וְגִלּוּי עֲרָיוֹת, גָּרַם זֶה שֶׁנִּשְׁתַּלְּחָה אִמּוֹ, ״וַיֵּרַע הַדָּבָר מְאֹד בְּעֵינֵי אַבְרָהָם״ (בראשית כא:יא):\",2,0],[2,135,19,27,\"חֲדַל בְּנִי לִשְׁמֹעַ וְגוֹ׳. מִקְרָא קָצָר הוּא וְזֶהוּ פֵּרוּשׁוֹ: חֲדַל בְּנִי לִשְׁגּוֹת מֵאִמְרֵי דָעַת בִּשְׁבִיל לִשְׁמֹעַ מוּסָר:\",1,0],[2,135,19,27,\"חֲדַל לִשְׁגּוֹת כְּמוֹ מִלִּשְׁגּוֹת, וְכֵן ״וְחָדַל לַעֲשׂוֹת הַפֶּסַח״ (במדבר ט:יג), וְכֵן ״כִּי חָדַל לִסְפֹּר״ (בראשית מא:מט):\",2,0],[2,135,19,28,\"עֵד בְּלִיַּעַל יָלִיץ מִשְׁפָּט. יָעִיד לְאָדָם מְלִיצַת מִשְׁפְּטֵי יִסּוּרִין וּמִיתָה:\",1,0],[2,135,19,28,\"וּפִי רְשָׁעִים יְבַלַּע אָוֶן. הָאָוֶן יִבְלָעֵהוּ:\",2,0],[2,135,19,29,\"נָכוֹנוּ לַלֵּצִים. הַקָּדוֹשׁ בָּרוּךְ הוּא זִמֵּן לוֹ שְׁפָטִים שֶׁל צָרַעַת לָזֶה הַלֵּץ הַמְסַפֵּר בְּלָשׁוֹן הָרָע (במדבר רבה יג:ד):\",1,0],[2,135,20,2,\"נַהַם כַּכְּפִיר אֵימַת מֶלֶךְ מִתְעַבְּרוֹ. מְכַעֲסוֹ:\",1,0],[2,135,20,3,\"כָּבוֹד לָאִישׁ שֶׁבֶת מֵרִיב. לָנוּחַ מִמְּרִיבָה:\",1,0],[2,135,20,3,\"וְכָל אֱוִיל. שֶׁאֵינוֹ שָׁבַת מֵרִיב, תִּגָּלֶה קְלוֹנוֹ:\",2,0],[2,135,20,4,\"מֵחֹרֶף עָצֵל לֹא יַחֲרֹשׁ. מִפְּנֵי הַצִּנָּה יוֹשֵׁב הֶעָצֵל וְאֵינוֹ עוֹשֶׂה מְלָאכָה וְאֵינוֹ עוֹסֵק בַּתּוֹרָה:\",1,0],[2,135,20,5,\"מַיִם עֲמֻקִּים עֵצָה בְלֶב אִישׁ. הֲלָכָה בְּלֵב חָכָם סְתוּמָה:\",1,0],[2,135,20,5,\"וְאִישׁ תְּבוּנָה יִדְלֶנָּה. וְתַלְמִיד נָבוֹן בָּא וְדָלָה אוֹתָהּ מִמֵּעָיו:\",2,0],[2,135,20,6,\"רָב אָדָם יִקְרָא אִישׁ חַסְדּוֹ. הַרְבֵּה יֵשׁ בְּנֵי אָדָם הַבּוֹטְחִים אֶל אוֹהֲבֵיהֶם הַמַּבְטִיחִים אוֹתָם חֶסֶד וְקוֹרְאִים לָהֶם בְּעֵת דָּחְקָם:\",1,0],[2,135,20,6,\"אִישׁ חַסְדּוֹ. הַמַּבְטִיחַ לוֹ לַעֲשׂוֹת חֶסֶד:\",2,0],[2,135,20,6,\"וְאִישׁ אֱמוּנִים מִי יִמְצָא. הַמַּבְטִיחַ וְעוֹשֶׂה:\",3,0],[2,135,20,8,\"מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא דִין. כְּפִשׁוּטוֹ, אוֹ יֵשׁ לְפָרְשׁוֹ כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא, וְיֵשׁ לְפָרְשׁוֹ כְּנֶגֶד שׁוֹפְטֵי אֱמֶת:\",1,0],[2,135,20,12,\"אֹזֶן שֹׁמַעַת וְעַיִן רֹאָה וְגוֹ׳. כְּלוֹמַר: מַעֲשֵׂה יָדָיו הֵם, וְהוּא חָפֵץ בְּאֹזֶן שׁוֹמַעַת מוּסָר וְעַיִן הָרוֹאָה אֶת הַנּוֹלָד:\",1,0],[2,135,20,13,\"אַל תֶּאֱהַב שֵׁנָה פֶּן תִּוָּרֵשׁ. כִּי תֵעָשֶׂה רָשׁ:\",1,0],[2,135,20,14,\"רַע רַע יֹאמַר הַקּוֹנֶה. הַקּוֹנֶה תּוֹרָה עַל יְדֵי הַדְּחָק וְיִסּוּרֵי רְעָבוֹן, אוֹמֵר: אוֹי לִי עַל רָעָה זֹאת וְהַצָּרָה הַזֹּאת. וּכְשֶׁהוֹלֵךְ לוֹ מָלֵא חָכְמָה אָז יִתְהַלָּל עַל הַצַּעַר שֶׁנִּצְטַעֵר:\",1,0],[2,135,20,14,\"וְאֹזֵל לוֹ. וְהוֹלֵךְ לוֹ:\",2,0],[2,135,20,17,\"עָרֵב לָאִישׁ לֶחֶם שָׁקֶר. נִיאוּף אֵשֶׁת אִישׁ:\",1,0],[2,135,20,17,\"וְאַחַר יִמָּלֵא פִיהוּ חָצָץ. אֲבָנִים דַּקּוֹת, וְכֵן ״וַיַּגְרֵס בֶּחָצָץ״ (איכה ג:טז):\",2,0],[2,135,20,18,\"מַחֲשָׁבוֹת בְּעֵצָה תִכּוֹן וּבְתַחְבֻּלוֹת עֲשֵׂה מִלְחָמָה. אִם בָּאתָ לְהִלָּחֵם כְּנֶגֶד הַשָּׂטָן, בֹּא בְּתַחְבּוּלוֹת תְּשׁוּבָה וּתְפִלָּה וְתַעֲנִית:\",1,0],[2,135,20,19,\"גּוֹלֶה סוֹד הוֹלֵךְ רָכִיל וּלְפֹתֶה שְׂפָתָיו. הַמְדַבֵּר חֲלָקוֹת לְפַתּוֹתְךָ וּלְהַסִּיתְךָ:\",1,0],[2,135,20,20,\"מְקַלֵּל אָבִיו וְאִמּוֹ יִדְעַךְ נֵרוֹ בֶּאֱשׁוּן חֹשֶׁךְ. בְּהַנְשִׁיף וּבְהַשְׁחִיר הַחֹשֶׁךְ, כְּלוֹמַר: בְּבֹא הָרָעָה:\",1,0],[2,135,20,21,\"נַחֲלָה מְבֹהֶלֶת בָּרִאשׁוֹנָה. שֶׁנִּבְהַל לְמַהֵר וְלִטּוֹל תְּחִלָּה, כְּגוֹן בְּנֵי גָד וּבְנֵי רְאוּבֵן שֶׁמִּהֲרוּ לִטּוֹל חֶלְקָם בְּעֵבֶר הַיַּרְדֵּן וְדִבְּרוּ בְּבֶהָלָה, שֶׁנֶּאֱמַר ״גִּדְרֹת צֹאן נִבְנֶה לְמִקְנֵנוּ פֹּה וְעָרִים לְטַפֵּנוּ״ (במדבר לב:טז) – עָשׂוּ אֶת הָעִקָּר טָפֵל, שֶׁהִקְדִּימוּ צֹאנָם לְטַפָּם (תנחומא, מטות ז):\",1,0],[2,135,20,21,\"וְאַחֲרִיתָהּ לֹא תְבֹרָךְ. שֶׁגָּלוּ כַּמָּה שָׁנִים קֹדֶם שְׁאָר הַשְּׁבָטִים, כְּמוֹ שֶׁמְּפֹרָשׁ בְּסֵדֶר עוֹלָם (סדר עולם רבה כב) וּבְמִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, מסעי י); ״בִּשְׁנַת שְׁתַּיִם לְאָחָז וַיָּעַר ה׳ אֶת רוּחַ מֶלֶךְ אַשּׁוּר וְגוֹ׳״ (דברי הימים א ה:כו), וּשְׁאָר שְׁבָטִים גָּלוּ בִּשְׁנַת שֵׁשׁ לְחִזְקִיָּהוּ הִיא הַתְּשִׁיעִית לְהוֹשֵׁעַ בֶּן אֵלָה (מלכים ב יז:א-ו):\",2,0],[2,135,20,25,\"מוֹקֵשׁ אָדָם יָלַע קֹדֶשׁ. כְּשֶׁאָדָם נִכְשָׁל וְנוֹקֵשׁ בַּעֲבֵירוֹת, מְקַלְקֵל אֶת קְדֻשָּׁתוֹ; כְּמוֹ ״וְשָׁתוּ וְלָעוּ״ (עובדיה א:טז):\",1,0],[2,135,20,25,\"וְאַחַר נְדָרִים לְבַקֵּר. צָרִיךְ אָדָם לַחֲזֹר אַחַר קָרְבָּנוֹת, לִנְדֹּר וּלְהָבִיא וּלְבַקֵּשׁ עַל נַפְשׁוֹ:\",2,0],[2,135,20,26,\"מְזָרֶה רְשָׁעִים. פַּרְעֹה וְחֵילוֹ (שמות יד:כח):\",1,0],[2,135,20,26,\"מֶלֶךְ חָכָם. הַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,135,20,26,\"וַיָּשֶׁב עֲלֵיהֶם אוֹפָן. גַּלְגַּל מִדָּתָם הֵשִׁיב עֲלֵיהֶם, ״וַיְנַהֲגֵהוּ בִּכְבֵדֻת״ (שמות יד:כה) כְּנֶגֶד ״וְהַכְבֵּד אֶת לִבּוֹ״ (שמות ח:יא):\",3,0],[2,135,20,27,\"נֵר ה׳ נִשְׁמַת אָדָם. הַנְּשָׁמָה שֶׁבְּקִרְבּוֹ מְעִידָה עָלָיו בַּדִּין (פסיקתא רבתי ח):\",1,0],[2,135,20,29,\"תִּפְאֶרֶת בַּחוּרִים כֹּחָם. כְּמוֹ שֶׁתִּפְאֶרֶת בַּחוּרִים כֹּחָם, כֵּן הַדְרַת זְקֵנִים שֵׂיבָה:\",1,0],[2,135,20,30,\"חַבֻּרוֹת פֶּצַע תַּמְרוּק בְּרָע. דָּרְשׁוּ רַבּוֹתֵינוּ (ילקוט שמעוני משלי תתקנט): הַמְמָרֵק עַצְמוֹ לִדְבַר עֲבֵירָה, סוֹף בָּא לִידֵי פְּצָעִים וְחַבּוּרוֹת:\",1,0],[2,135,20,30,\"וּמַכּוֹת חַדְרֵי בָטֶן. זֶה הַהִדְרוֹקָן (בבא מציעא קז:):\",2,0],[2,135,21,2,\"כָּל דֶּרֶךְ אִישׁ יָשָׁר בְּעֵינָיו וְתוֹכֵן. וּמוֹנֶה:\",1,0],[2,135,21,4,\"רוּם עֵינַיִם. גַּסּוּת הָרוּחַ:\",1,0],[2,135,21,4,\"וּרְחַב לֵב. חָפֵץ לְמַלֹּאות תַּאֲוַת לִבּוֹ, הוּא נִיר שֶׁל רְשָׁעִים – חֲרִישׁוּתָם וּמַחְשְׁבוֹתָם הוּא חַטָּאתָם:\",2,0],[2,135,21,5,\"מַחְשְׁבוֹת חָרוּץ. אָדָם יָשָׁר הַמִּתְהַלֵּךְ בֶּאֱמֶת וּבְמִשְׁפָּט חָרוּץ:\",1,0],[2,135,21,5,\"אַךְ לְמוֹתָר. לְהַצְלָחָה וּלְרֶוַח בָּאוֹת:\",2,0],[2,135,21,5,\"וְכָל אָץ. דּוֹחֵק אֶת הַשָּׁעָה:\",3,0],[2,135,21,6,\"פֹּעַל אוֹצָרוֹת. לְהַרְבּוֹת הוֹן. בִּלְשׁוֹן שָׁקֶר:\",1,0],[2,135,21,6,\"הֶבֶל נִדָּף וְגוֹ׳. מוֹקְשֵׁי (  מְבַקְּשֵׁי) מָוֶת הֵם לוֹ:\",2,0],[2,135,21,7,\"יְגוֹרֵם. יָגוּר אוֹתָם:\",1,0],[2,135,21,8,\"הֲפַכְפַּךְ דֶּרֶךְ אִישׁ וָזָר. אִישׁ וְהוּא זָר, סָר מִן הַמִּצְוָה, דַּרְכּוֹ הֲפַכְפַּךְ:\",1,0],[2,135,21,9,\"וּבֵית חָבֶר. שֶׁנִּכְנָס לְבֵית חֲבֵירוֹ לְדַבֵּר עִם אִשְׁתּוֹ. וּמִדְרַשׁ אַגָּדָה (אבות דרבי נתן לד,ו; סנהדרין קג:): נִיבָּא שֶׁסּוֹף הַשְּׁכִינָה לְהִסְתַּלֵּק מֵעַל יִשְׂרָאֵל שֶׁהֵם כְּאֵשֶׁת מִדְיָנִים:\",1,0],[2,135,21,9,\"וּבֵית חָבֶר. בַּיִת שֶׁמְּחַבְּרִים בּוֹ רֵעִים לְהַקָּדוֹשׁ בָּרוּךְ הוּא, כְּגוֹן צֶלֶם שֶׁהֶעֱמִיד מְנַשֶּׁה בְּהֵיכַל ה׳ (מלכים ב כא:ז):\",2,0],[2,135,21,11,\"בַּעֲנׇשׁ לֵץ יֶחְכַּם פֶּתִי. עַל יְדֵי יִסּוּרֵי הַלֵּצִים הַפְּתָאִים מִתְחַכְּמִים וְשָׁבִים בִּתְשׁוּבָה:\",1,0],[2,135,21,12,\"מַשְׂכִּיל צַדִּיק. צַדִּיקוֹ שֶׁל עוֹלָם, הוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, נוֹתֵן לֵב לְהַכְרִית בֵּית רָשָׁע, כְּגוֹן זֵכֶר עֲמָלֵק (שמות יז:יד):\",1,0],[2,135,21,14,\"מַתָּן בַּסֵּתֶר. צְדָקָה:\",1,0],[2,135,21,14,\"וְשֹׁחַד בַּחֵק. אַף זוֹ צְדָקָה. יִכְפֶּה אָף, יִכְפֶּה חֵמָה עַזָּה:\",2,0],[2,135,21,15,\"שִׂמְחָה לַצַּדִּיק עֲשׂוֹת מִשְׁפָּט. שִׂמְחָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת דִּין בַּצַּדִּיקִים כְּדֵי לְזַכּוֹתָם לְחַיֵּי הָעוֹלָם הַבָּא, וְשִׂמְחָה לַצַּדִּיק שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵבִיא יִסּוּרִין עֲלֵיהֶם כְּדֵי שֶׁיִּזְכּוּ לָעוֹלָם הַבָּא. כָּךְ נִדְרַשׁ בְּמִדְרַשׁ תְּהִלִּים:\",1,0],[2,135,21,15,\"וּמְחִתָּה. הִיא לְפֹעֲלֵי אָוֶן, לְפִי שֶׁאֵין נוֹתְנִין לֵב לָשׁוּב וְאֵין הַיִּסּוּרִין מוֹעִילִין לָהֶן, וּמִצְטַעֲרִין וְלֹא לְהוֹעִיל:\",2,0],[2,135,21,16,\"אָדָם תּוֹעֶה מִדֶּרֶךְ הַשְׂכֵּל. פּוֹרֵשׁ מִן הַתּוֹרָה:\",1,0],[2,135,21,16,\"בִּקְהַל רְפָאִים. בַּעֲדַת גֵּיהִנֹּם (בבא בתרא עט.):\",2,0],[2,135,21,17,\"אִישׁ מַחְסוֹר. מִי שֶׁאוֹהֵב שִׂמְחַת מִשְׁתֶּה תָּמִיד:\",1,0],[2,135,21,18,\"כֹּפֶר לַצַּדִּיק רָשָׁע וְתַחַת יְשָׁרִים בּוֹגֵד. צַדִּיק נֶחְלָץ וְרָשָׁע בָּא תַּחְתָּיו (ירושלמי ברכות ט:א), כְּגוֹן מָרְדְּכַי וְהָמָן (אסתר ז:ט-י):\",1,0],[2,135,21,19,\"טוֹב שֶׁבֶת בְּאֶרֶץ מִדְבָּר. גַּם זֶה עַל סִלּוּק הַשְּׁכִינָה נֶאֱמַר:\",1,0],[2,135,21,20,\"וּכְסִיל אָדָם. וּכְסִילוּת שֶׁל אָדָם:\",1,0],[2,135,21,22,\"עִיר גִּבּוֹרִים עָלָה חָכָם. זֶה מֹשֶׁה רַבֵּינוּ שֶׁעָלָה לְבֵין הַמַּלְאָכִים גִּבּוֹרֵי כֹחַ (תהלים קג:כ). וַיּוֹרֶד וְגוֹ׳. תּוֹרָה:\",1,0],[2,135,21,24,\"יָהִיר. גַּס רוּחַ, סוֹפוֹ לִהְיוֹת לֵץ שֶׁאֵינוֹ חָשׁ לִשְׁמוֹעַ מוּסָר:\",1,0],[2,135,21,26,\"וְצַדִּיק יִתֵּן. כָּל צָרְכֵי בֵיתוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְזַמֵּן לוֹ:\",1,0],[2,135,21,27,\"אַף כִּי בְזִמָּה יְבִיאֶנּוּ. וְכָל שֶׁכֵּן כְּשֶׁהוּא מְבִיאוֹ לְהַרְשִׁיעוֹ, וּבְעֵצָה רָעָה, כְּגוֹן קָרְבְּנוֹת בִּלְעָם וּבָלָק, שֶׁלֹּא הָיוּ מְבִיאִים אֶלָּא לְקַלֵּל אֶת יִשְׂרָאֵל (במדבר כג):\",1,0],[2,135,21,28,\"וְאִישׁ שׁוֹמֵעַ. שֶׁקִּבֵּל מַה שֶּׁכָּתוּב בַּתּוֹרָה ״לֹא תַעֲנֶה בְרֵעֲךָ וְגוֹ׳״ (שמות כ:יג):\",1,0],[2,135,21,28,\"לָנֶצַח. תָּמִיד:\",2,0],[2,135,21,29,\"הֵעֵז אִישׁ רָשָׁע בְּפָנָיו. הָרָשָׁע מַרְאֶה עַזּוּתוֹ בִּשְׁעַת כַּעֲסוֹ:\",1,0],[2,135,21,29,\"בְּפָנָיו. מִלְּשׁוֹן ״אַף״ (משלי כט:כב):\",2,0],[2,135,21,30,\"אֵין חָכְמָה וְגוֹ׳. אֵין כָּל חָכָם וְנָבוֹן חָשׁוּב לְנֶגֶד ה׳, כָּל מָקוֹם שֶׁיֵּשׁ חִלּוּל הַשֵּׁם, אֵין חוֹלְקִין כָּבוֹד לָרַב (ברכות יט:):\",1,0],[2,135,22,1,\"נִבְחָר שֵׁם מֵעֹשֶׁר רָב. שֵׁם טוֹב:\",1,0],[2,135,22,1,\"מִכֶּסֶף וּמִזָּהָב. נִבְחָר חֵן טוֹב:\",2,0],[2,135,22,2,\"עוֹשֵׂה כֻלָּם ה׳. כְּשֶׁעָנִי אוֹמֵר לֶעָשִׁיר: פַּרְנְסֵנִי, וְהוּא עוֹנֶה קָשׁוֹת, עוֹשֵׂה כֻלָּם ה׳. הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה אוֹתָם חֲדָשִׁים, לָזֶה עָנִי וְלָזֶה עָשִׁיר (תמורה טז.):\",1,0],[2,135,22,3,\"עָרוּם רָאָה רָעָה. עֹנֶשׁ שֶׁל עֲבֵרָה, וְנִסְתָּר וְלֹא עָבַר עֲבֵרָה:\",1,0],[2,135,22,4,\"עֵקֶב עֲנָוָה. בִּשְׁבִיל הָעֲנָוָה יִרְאַת ה׳ בָּאָה. דָּבָר אַחֵר: עֲנָוָה עִקָּר, וְהַיִּרְאָה טְפֵלָה וְעָקֵב לָהּ, מִדְרָס לְרַגְלֶיהָ (ירושלמי שבת א,ג):\",1,0],[2,135,22,5,\"צִנִּים פַּחִים. כְּמוֹ ״לִצְנִינִם בְּצִדֵּיכֶם״ (במדבר לג:נה), ״וּבָאוּ עָלַיִךְ הֹצֶן״ (יחזקאל כג:כד), לְשׁוֹן גְּדוּדִים וְלִסְטִים:\",1,0],[2,135,22,5,\"צִנִּים פַּחִים. הֵם טְמוּנִים בְּדַרְכֵי הַמְּעַקֵּשׁ דְּרָכָיו, כְּלוֹמַר: יִסּוּרִים מוּכָנִים לוֹ:\",2,0],[2,135,22,5,\"שׁוֹמֵר נַפְשׁוֹ יִרְחַק מֵהֶם. שֶׁמְּיַשֵּׁר מַעֲשָׂיו יִנָּצֵל מֵהֶם:\",3,0],[2,135,22,6,\"חֲנוֹךְ לַנַּעַר. לְפִי מַה שֶּׁתְּלַמֵּד לַנַּעַר וּתְחַנְּכֵהוּ בִּדְבָרִים, אִם לְטוֹב אִם לְרַע, גַּם כִּי יַזְקִין לֹא יָסוּר מִמֶּנָּה:\",1,0],[2,135,22,7,\"עָשִׁיר בְּרָשִׁים יִמְשׁוֹל. עַם הָאָרֶץ צָרִיךְ לְתַלְמִיד חָכָם לְעוֹלָם (שבת קלט.):\",1,0],[2,135,22,8,\"זוֹרֵעַ עַוְלָה. יִקְצָר אָוֶן לְפִי זְרִיעָתוֹ קְצִירָתוֹ, לְפִי פְּעֻלָּתוֹ יִהְיֶה קַבָּלַת מַשְׂכֻּרְתּוֹ:\",1,0],[2,135,22,8,\"וְשֵׁבֶט עֶבְרָתוֹ יִכְלֶה. קְנֵה הַשִּׁבֹּלֶת שֶׁלּוֹ כָּלֶה וְהוֹלֵךְ לוֹ. יֵשׁ אוֹמְרִים (סא״א): שֵׁבֶט חֲמָתוֹ, שֶׁרוֹדֶה בְּנֵי אָדָם, כָּלֶה וְהוֹלֵךְ לוֹ, לְפִי שֶׁמַּפְסִיד אֶת יְכָלְתּוֹ:\",2,0],[2,135,22,10,\"גָּרֵשׁ לֵץ. יֵצֶר הָרָע:\",1,0],[2,135,22,11,\"אוֹהֵב טְהׇר לֵב חֵן שְׂפָתָיו. מִי שֶׁשְּׂפָתָיו חֵן:\",1,0],[2,135,22,11,\"רֵעֵהוּ מֶלֶךְ. הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֲבוֹ וּמְחַבְּבוֹ (בראשית רבה מא, ה):\",2,0],[2,135,22,13,\"אָמַר עָצֵל אֲרִי בַחוּץ. אֵיךְ אֵצֵא לִלְמֹד תּוֹרָה?\",1,0],[2,135,22,14,\"שׁוּחָה עֲמֻקָּה פִּי זָרוֹת. פִּי עוֹבְדֵי גִּלּוּלִים:\",1,0],[2,135,22,14,\"זְעוּם ה׳. מִי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׂוֹנְאוֹ, נוֹפֵל וְנִכְשָׁל בָּהּ:\",2,0],[2,135,22,14,\"זְעוּם. נָזוּף מִלְּפָנָיו:\",3,0],[2,135,22,16,\"עוֹשֵׁק דָּל לְהַרְבּוֹת לוֹ. עֹשֶׁר:\",1,0],[2,135,22,16,\"נוֹתֵן לְעָשִׁיר. סוֹף שֶׁנּוֹתֵן מָמוֹנוֹ לְעוֹבְדֵי גִּלּוּלִים הָעֲשִׁירִים, וְאַךְ לְמַחְסוֹר הוּא בָּא:\",2,0],[2,135,22,17,\"הַט אָזְנְךָ וּשְׁמַע דִּבְרֵי חֲכָמִים. לִלְמוֹד תּוֹרָה מֵחָכָם כָּל שֶׁהוּא:\",1,0],[2,135,22,17,\"וְלִבְּךָ תָּשִׁית לְדַעְתִּי. וְאִם רַבְּךָ רָשָׁע, לֹא תִלְמוֹד מִמַּעֲשָׂיו (חגיגה טו:):\",2,0],[2,135,22,18,\"כִּי נָעִים. יְהִי לְךָ לְאַחַר זְמַן אִם תִּשְׁמְרֵם וְתִצְפְּנֵם בְּבִטְנֶךָ, שֶׁלֹּא תִּשְׁכָּחֵם. וְאֵימָתַי יִהְיוּ שְׁמוּרִים בְּלִבְּךָ? בִּזְמַן שֶׁיִּכּוֹנוּ עַל שְׂפָתֶיךָ. כַּאֲשֶׁר תּוֹצִיאֵם בְּפִיךָ (עירובין נד.):\",1,0],[2,135,22,19,\"לִהְיוֹת בַּה׳ מִבְטַחֶךָ הוֹדַעְתִּיךָ. אֲנִי מוֹדִיעֲךָ שֶׁתִּבְטַח בַּה׳ וְתַעֲסֹק בַּתּוֹרָה, וְלֹא תֹאמַר: אֵיךְ אֲבַטֵּל מִמְּלַאכְתִּי וְאֵיךְ אֶתְפַּרְנֵס?\",1,0],[2,135,22,20,\"הֲלֹא כָתַבְתִּי לְךָ שָׁלִשִׁים. תּוֹרָה וּנְבִיאִים וּכְתוּבִים:\",1,0],[2,135,22,21,\"לְהוֹדִיעֲךָ קֹשְׁטְ. שָׁלִישִׁים כָּתַבְתִּי לְךָ כְּדֵי שֶׁתָּבִין מִתּוֹכָם קֹשְׁטְ אִמְרֵי אֱמֶת. לְהָשִׁיב אֲמָרִים אֱמֶת:\",1,0],[2,135,22,21,\"לְשֹׁלְחֶיךָ. לְשׁוֹאֲלְךָ הוֹרָאָה:\",2,0],[2,135,22,22,\"אַל תִּגְזָל דָּל. אַל תִּגְזְלֶנּוּ כִּי תִרְאֶנּוּ דַּל, בַּעֲבוּר שֶׁהוּא דַּל, וְאֵין לוֹ כֹּחַ לַעֲמֹד נֶגְדְּךָ:\",1,0],[2,135,22,23,\"כִּי ה׳ יָרִיב רִיבָם וְקָבַע. וְיִגְזֹל אֶת הַנֶּפֶשׁ:\",1,0],[2,135,22,23,\"קוֹבְעֵיהֶם. גּוֹזְלֵיהֶם. וּבִלְשׁוֹן אֲרַמִּי קְבִיעָה – גְּזֵלָה בְּמַסֶּכֶת רֹאשׁ הַשָּׁנָה (ראש השנה כו,א-ב): אֲתָא הַהוּא גַּבְרָא לְקַמֵּיהּ אָמַר לֵיהּ: קַבְּעַן פְּלַנְיָא וְכוּ׳:\",2,0],[2,135,22,24,\"אַל תִּתְרַע. אַל תִּתְחַבֵּר, לְשׁוֹן רֵעוּת:\",1,0],[2,135,22,25,\"פֶּן תֶּאֱלַף. פֶּן תִּלְמַד:\",1,0],[2,135,22,26,\"אַל תְּהִי בְתוֹקְעֵי כָף בָּעוֹרְבִים מַשָּׁאוֹת. הַלְוָאוֹת, כְּמוֹ ״מַשַּׁאת מְאוּמָה״ (דברים כד:י):\",1,0],[2,135,22,28,\"אַל תַּסֵּג גְּבוּל עוֹלָם. אַל תָּשֵׁג אָחוֹר מִנְהַג אֲבוֹתֶיךָ. וְאָמְרוּ זִכְרוֹנָם לִבְרָכָה (תורת כהנים קדושים פרשתא א פרק ג): הַמַּנִּיחַ כַּלְכָּלָה תַּחַת הַגֶּפֶן בִּשְׁעַת בְּצִירָה כְּדֵי שֶׁיִּפּוֹל בְּתוֹכוֹ הַפֶּרֶט, עַל זֶה נֶאֱמַר אַל תַּסֵּג גְּבוּל וְגוֹ׳. תַּסֵּג כְּמוֹ ״יִסּוֹגוּ אָחוֹר״ (תהלים קכט:ה):\",1,0],[2,135,23,1,\"כִּי תֵשֵׁב לִלְחוֹם. לֶאֱכוֹל:\",1,0],[2,135,23,1,\"בִּין תָּבִין. תֵּן לִבְּךָ לָדַעַת מִי הוּא, אִם עֵינוֹ צָרָה אוֹ יָפָה:\",2,0],[2,135,23,2,\"וְשַׂמְתָּ שַׂכִּין בְּלֹעֶךָ. בִּלְחָיֶיךָ; אִם רָאִיתָ עֵינוֹ צָרָה, אַל תֹּאכַל מִשֶּׁלּוֹ:\",1,0],[2,135,23,2,\"אִם בַּעַל נֶפֶשׁ אָתָּה. אִם רַעַבְתָּן אַתָּה וְתָאֵב לֶאֱכוֹל, טוֹב לִתְחוֹב סַכִּין בֵּין שִׁנֶּיךָ. וְרַבּוֹתֵינוּ דָּרְשׁוּ (חולין ו.) בְּתַלְמִיד הַיּוֹשֵׁב לִפְנֵי רַבּוֹ; אִם יוֹדֵעַ בְּרַבּוֹ שֶׁיַּחֲזִיר לוֹ תְּשׁוּבָה עַל כָּל דָּבָר שֶׁיִּשְׁאָלֵהוּ, יְדַקְדֵּק וְיִשְׁאַל שְׁמוּעָתוֹ, וְאִם לָאו – יִשְׁתּוֹק:\",2,0],[2,135,23,3,\"אַל תִּתְאָו לְמַטְעַמּוֹתָיו. אֶלָּא פְּרוֹשׁ מִמֶּנּוּ וְלֵךְ לִפְנֵי רַב הָגוּן, וְלֹא תְּבַיְּשֵׁהוּ בִּשְׁאֵלוֹת, אַחַר שֶׁלֹּא יֵדַע לְהָשִׁיב:\",1,0],[2,135,23,4,\"אַל תִּיגַע לְהַעֲשִׁיר. לַעֲשׂוֹת גִּירְסָתְךָ חֲבִילוֹת חֲבִילוֹת, כִּי סוֹף שֶׁתִּשְׁכָּחֶנָּה:\",1,0],[2,135,23,5,\"הֲתָעִיף עֵינֶיךָ בּוֹ. כְּרֶגַע, שֶׁתִּכְפּוֹל עֵינֶיךָ לְעָצְמוֹ, וְאֵין אוֹתָהּ גִּירְסָא מְצוּיָה בְּךָ:\",1,0],[2,135,23,5,\"הֲתָעִיף. כְּמוֹ ״וְכָפַלְתָּ״ (שמות כו:ט): ״וְתָעֵיף״ (תרגום אונקלוס):\",2,0],[2,135,23,7,\"כִּי כְּמוֹ שָׁעַר בְּנַפְשׁוֹ. שָׁעַר זֶה נָקוּד חֶצְיוֹ פַּתָּח וְחֶצְיוֹ קָמַץ וְטַעֲמוֹ לְמַטָּה, לְכָךְ הוּא פֹּעַל וְלֹא שֵׁם דָּבָר; שֶׁאִם הָיָה שֵׁם דָּבָר הָיָה קָמַץ וְטַעֲמוֹ לְמַעְלָה כְּכָל שַׁעַר שֶׁבַּמִּקְרָא. וּפִתְרוֹנוֹ: כְּאִלּוּ שָׁפַךְ הָאוֹכֵל הַזֶּה מְרָה בְּנַפְשׁוֹ שֶׁל רַע הָעַיִן כֵּן הוּא שָׁעַר מִן לְשׁוֹן ״הַתְּאֵנִים הַשֹּׁעָרִים״ (ירמיהו כט:יז) הַמָּרִים:\",1,0],[2,135,23,8,\"פִּתְּךָ. שֶׁאֲכַלְתּוֹ בְּבֵיתוֹ, סוֹף שֶׁתְּקִיאֶנָּה מִפְּנֵי הַבּוּשָׁה:\",1,0],[2,135,23,8,\"וְשִׁחַתָּ דְּבָרֶיךָ הַנְּעִימִים. חַנּוֹת שֶׁהֶחֱזַקְתָּ וְדִבַּרְתָּ לוֹ דְּבָרִים רַכִּים, הַכֹּל אִבַּדְתָּ:\",2,0],[2,135,23,10,\"וּבִשְׂדֵי יְתוֹמִים. בְּלֶקֶט שִׁכְחָה וּפֵאָה הָרָאוּי לָהֶם:\",1,0],[2,135,23,16,\"בְּדַבֵּר שְׂפָתֶיךָ מֵישָׁרִים. עַל יְדֵי שֶׁחָכַם לִבֶּךָ:\",1,0],[2,135,23,17,\"אַל יְקַנֵּא לִבְּךָ בַּחַטָּאִים. בְּהַצְלָחָתָם, לִהְיוֹת רָשָׁע כְּמוֹתָם (ברכות ז:):\",1,0],[2,135,23,18,\"כִּי אִם יֵשׁ אַחֲרִית. אִם זֶה מְשַׁמֵּשׁ בִּלְשׁוֹן אֲשֶׁר, כְּלוֹמַר: אֲשֶׁר בַּעֲבוּר זֶה יֵשׁ אַחֲרִית תִּקְוָה אֵלֶיךָ:\",1,0],[2,135,23,19,\"שְׁמַע אַתָּה בְנִי וַחֲכָם וְאַשֵּׁר בַּדֶּרֶךְ לִבֶּךָ. מֵאַחַר שֶׁתִּתְחַכֵּם תּוּכַל לָלֶכֶת בְּדַרְכֵי לִבְּךָ, כִּי לֵב חָכָם לֹא יַשִּׁיאֲךָ לַעֲבֵרָה:\",1,0],[2,135,23,21,\"כִּי סוֹבֵא וְזוֹלֵל יִוָּרֵשׁ. ״יִתְמַסְכֵּן״ (תרגום יונתן):\",1,0],[2,135,23,21,\"וּקְרָעִים תַּלְבִּישׁ נוּמָה. הָעַצְלוּת וְהַתְּנוּמָה תַּלְבִּישׁ אוֹתְךָ בְּגָדִים קְרוּעִים:\",2,0],[2,135,23,23,\"אֱמֶת קְנֵה. וְאִם לֹא תִמְצָא לִלְמֹד בְּחִנָּם לְמֹד בְּשָׂכָר, וְאַל תֹּאמַר: כְּשֵׁם שֶׁלָּמַדְתִּי בְּשָׂכָר, כָּךְ אֲלַמְּדֶנָּה בְּשָׂכָר (בכורות כט.):\",1,0],[2,135,23,27,\"וּבְאֵר צָרָה. אֶשְׁטְרֵיינָ״א בְּלַעַ״ז:\",1,0],[2,135,23,28,\"אַף הִיא כְּחֶתֶף. פִּתְאוֹם:\",1,0],[2,135,23,28,\"וּבוֹגְדִים בְּאָדָם תּוֹסִיף. מְרַבָּה בְּיִשְׂרָאֵל בּוֹגְדִים לַה׳, וְעַל הָאֲפִיקוֹרְסִין מְדַבֵּר:\",2,0],[2,135,23,29,\"לְמִי אוֹי לְמִי אֲבוֹי. לְשׁוֹן צְעָקָה וִילָלָה:\",1,0],[2,135,23,29,\"לְמִי מִדְיָנִים לְמִי שִׂיחַ. לְמִי שֶׁיֵּשׁ לוֹ מִדְיָנִים עִם הַבְּרִיּוֹת וְשִׂיחָה יְתֵרָה, לוֹ אוֹי וַאֲבוֹי, כִּי בְּרֹב דְּבָרִים רֹב פֶּשַׁע (משלי י:יט):\",2,0],[2,135,23,29,\"לְמִי חַכְלִילוּת עֵינָיִם. מֵרוֹב יַיִן מַאֲדִימִים עֵינָיו, וּגְנַאי הוּא (תנחומא, שמיני ה):\",3,0],[2,135,23,30,\"מִמְסָךְ. מִמֶּזֶג, וְהוּא שֵׁם דָּבָר כְּמוֹ ״מִמְכָּר״ (ויקרא כה:יד):\",1,0],[2,135,23,30,\"לַחְקֹר מִמְסָךְ. שֶׁחוֹקְרִין וּבוֹדְקִין הֵיכָן מוֹכְרִין יַיִן טוֹב:\",2,0],[2,135,23,31,\"אַל תֵּרֶא יַיִן כִּי יִתְאַדָּם. אַל תִּתֵּן בּוֹ עֵינֶיךָ:\",1,0],[2,135,23,31,\"כִּי יִתֵּן בַּכּוֹס עֵינוֹ יִתְהַלֵּךְ בְּמֵישָׁרִים. הַמַּרְבֶּה שִׁכְרוּת, כָּל עֲבֵרוֹת דּוֹמוֹת לוֹ לְמִישׁוֹר, כָּל הַדְּרָכִים יְשָׁרִים בְּעֵינָיו:\",2,0],[2,135,23,31,\"בַּכּוֹס. בַּכִּיס כְּתִיב, כְּלוֹמַר: הַשּׁוֹתֶה נוֹתֵן עַיִן בַּכּוֹס וְהַחֶנְוָנִי – בְּכִיסוֹ שֶׁל זֶה (יומא עד:-עה.):\",3,0],[2,135,23,32,\"יַפְרִישׁ. לְשׁוֹן עֲקִיצָה, פויינ״ט בְּלַעַ״ז, ״בְּמַלְמַד הַבָּקָר״ (שופטים ג:לא) תַּרְגּוּם: ״בְּפָרַשׁ תּוֹרֵי״ (תרגום יונתן), וּבַגְּמָרָא (בבא מציעא פ.): דְּנָקִיט פַּרְשָׁא, אגוילו״ן בְּלַעַ״ז. וְיֵשׁ פּוֹתְרִין: מַפְרִישׁוֹ מִן הַחַיִּים:\",1,0],[2,135,23,33,\"עֵינֶיךָ יִרְאוּ זָרוֹת. כְּשֶׁתִּשְׁתַּכֵּר, הַיַּיִן בּוֹעֵר בְּךָ וּמַשִּׂיאֲךָ לְהַבִּיט בְּזוֹנוֹת:\",1,0],[2,135,23,34,\"וְהָיִיתָ. מְשֻׁגָּע (דברים כח:לד):\",1,0],[2,135,23,34,\"כְּשׁוֹכֵב בְּלֶב יָם וּכְשׁוֹכֵב בְּרֹאשׁ חִבֵּל. תֹּרֶן הַסְּפִינָה נוֹחַ לִפּוֹל מִמֶּנּוּ:\",2,0],[2,135,23,35,\"הִכּוּנִי בַל חָלִיתִי וְגוֹ׳. כְּשֶׁיִּקַץ מִיֵּינוֹ אֵינוֹ מַרְגִּישׁ בְּכָל הָרָעוֹת שֶׁעָבְרוּ עָלָיו, וְחוֹזֵר לִשְׁתּוֹת:\",1,0],[2,135,24,5,\"גֶּבֶר חָכָם בְּעוֹז. אִישׁ חָכָם הוּא תָּמִיד בְּעוֹז:\",1,0],[2,135,24,7,\"רָאמוֹת לֶאֱוִיל חָכְמוֹת. מִין אֶבֶן יְקָרָה שֶׁאֵינָהּ מְצוּיָה, כְּמָה דְתֵימָא ״רָאמוֹת וְגָבִישׁ״ (איוב כח:יח). כְּלוֹמַר: כָּל חָכְמָה דּוֹמָה לַכְּסִיל כְּאֶבֶן יְקָרָה וּכְמַרְגָּלִיּוֹת לִקְנוֹת, לוֹמַר: אֵיךְ אֶעֱסֹק בַּתּוֹרָה, מָתַי תַּעֲלֶה בְּיָדִי? אֲבָל הֶחָכָם שׁוֹנֶה הַיּוֹם מְעַט וּלְמָחָר מְעַט (דברים רבה ח:ג):\",1,0],[2,135,24,8,\"מְחַשֵּׁב לְהָרֵעַ. חוֹרֵשׁ תַּחְבּוּלוֹת רֶשַׁע:\",1,0],[2,135,24,8,\"לוֹ בַּעַל מְזִמּוֹת יִקְרָאוּ. גּוֹרֵם לוֹ רַע, שֶׁהַבְּרִיּוֹת קוֹרְאִים לוֹ: בַּעַל מְזִמּוֹת. עֲצַת רְשָׁעִים:\",2,0],[2,135,24,9,\"זִמַּת אִוֶּלֶת. עֲצַת אִוֶּלֶת חַטָּאת לִבְעָלֶיהָ:\",1,0],[2,135,24,9,\"וְתוֹעֲבַת לְאָדָם לֵץ. לֵיצָנוּת הִיא הַמְּתַעֶבֶת אֶת הָאָדָם עַל הַקָּדוֹשׁ בָּרוּךְ הוּא וְעַל הַבְּרִיּוֹת:\",2,0],[2,135,24,10,\"הִתְרַפִּיתָ. מִן הַתּוֹרָה:\",1,0],[2,135,24,10,\"בְּיוֹם צָרָה צַר כֹּחֶכָה. מַלְאֲכֵי הַשָּׁרֵת לֹא יִהְיוּ מְאַמְּצִין כֹּחֲךָ. זֶה מִדְרַשׁ חֲכָמִים (ברכות סג.). וּלְפִי פְּשׁוּטוֹ: הִתְרַפִּיתָ בְּיוֹם צָרַת אֲהוּבְךָ לַעֲמוֹד מִנֶּגֶד:\",2,0],[2,135,24,10,\"צַר כֹּחֶכָה. בְּיוֹם פּוּרְעָנוּתְךָ, דִּכְתִיב ״אִם הַחֲרֵשׁ תַּחֲרִישִׁי וְגוֹ׳״ (אסתר ד:יד):\",3,0],[2,135,24,11,\"הַצֵּל לְקוּחִים וְגוֹ׳. לְהַצִּיל אֶת הַלְּקוּחִים לַמָּוֶת, אֶת הַמָטִים לַהֶרֶג:\",1,0],[2,135,24,11,\"אִם תַּחְשׂוֹךְ. מִלְּהַצִּילָם, עַל זֶה אָמַרְתִּי ״צַר כֹּחֲךָ״ (משלי כד:י):\",2,0],[2,135,24,12,\"כִּי תֹאמַר. שֶׁמָּא תֹּאמַר, וְזֶהוּ כִּי מְשַׁמֵּשׁ בִּלְשׁוֹן דִּלְמָא:\",1,0],[2,135,24,13,\"אֱכָל בְּנִי דְבַשׁ. כְּלוֹמַר: דֶּרֶךְ בְּנֵי אָדָם לֶאֱכֹל דְּבַשׁ כִּי טוֹב הוּא. אַף כֵּן דְּעֵה חָכְמָה לְנַפְשֶׁךָ. וּכְשֵׁם שֶׁאַתָּה רוֹדֵף לֶאֱכֹל דְּבַשׁ, כֵּן תְּהֵא רוֹדֵף לָדַעַת חָכְמָה:\",1,0],[2,135,24,14,\"אִם מָצָאתָ אוֹתָהּ, אָז יֵשׁ אַחֲרִית:\",1,0],[2,135,24,19,\"אַל תִּתְחַר. לִהְיוֹת כְּמוֹתָם, כְּמוֹ ״אֵיךְ תְּתַחֲרֶה״ (ירמיהו יב:ה), ״כִּי אַתָּה מִתְחַרֶה בָאָרֶז״ (ירמיהו כב:טו):\",1,0],[2,135,24,21,\"יְרָא אֶת ה׳ בְּנִי וָמֶלֶךְ. יְרָא אֶת הַמֶּלֶךְ, וּבִלְבַד שֶׁלֹּא יְסִירְךָ מִיִּרְאַת ה׳, וּלְעוֹלָם יִרְאַת ה׳ קוֹדֶמֶת:\",1,0],[2,135,24,21,\"עִם שׁוֹנִים אַל תִּתְעָרָב. הָאוֹמְרִים: שְׁתֵּי רָשֻׁיּוֹת יֵשׁ:\",2,0],[2,135,24,22,\"וּפִיד שְׁנֵיהֶם. שֶׁבֶר עֲבוֹדַת גִּלּוּלִים וְשֶׁבֶר עוֹבְדֶיהָ:\",1,0],[2,135,24,23,\"גַּם אֵלֶּה לַחֲכָמִים. כָּל הַדְּבָרִים שֶׁבָּעִנְיָן שֶׁלְּמַטָּה אֲמוּרִים לַחֲכָמִים הַיּוֹשְׁבִים בְּדִין, שֶׁלֹּא יַכִּירוּ פָנִים בְּמִשְׁפָּט כִּי לֹא טוֹב (תנחומא, משפטים ד):\",1,0],[2,135,24,26,\"שְׂפָתַיִם יִשָּׁק. רְאוּיִים כָּל שְׂפָתַיִם לְנַשְּׁקוֹ:\",1,0],[2,135,24,27,\"הָכֵן בַּחוּץ. זֶה מִקְרָא:\",1,0],[2,135,24,27,\"וְעַתְּדָהּ בַּשָּׂדֶה. זוֹ מִשְׁנָה:\",2,0],[2,135,24,27,\"אַחַר וּבָנִיתָ בֵיתֶךָ. זוֹ גְּמָרָא (סוטה מד.). דָּבָר אַחֵר: כְּמַשְׁמָעוֹ, בַּתְּחִלָּה קַח לְךָ שָׂדוֹת וּכְרָמִים, וְאַחַר כָּךְ וְעַתְּדָהּ, לְשׁוֹן ״עַתּוּדִים״ (בראשית לא:י) – שִׂים לְךָ בְּהֵמוֹת בַּשָּׂדֶה, וְאַחַר וּבָנִיתָ בֵיתֶךָ. תִּקַּח אִשָּׁה:\",3,0],[2,135,24,28,\"וְהַפִּתִּיתָ בִּשְׂפָתֶיךָ. תִּתְפַּתֶּה לְרֵעֲךָ בְּדִבּוּרְךָ:\",1,0],[2,135,24,30,\"אִישׁ עָצֵל. שֶׁאֵינוֹ חוֹזֵר עַל גִּרְסַת תַּלְמוּדוֹ:\",1,0],[2,135,24,31,\"קִמְּשׂוֹנִים. חוֹחִים:\",1,0],[2,135,24,31,\"כָּסּוּ. נִכְסוּ:\",2,0],[2,135,24,31,\"חֲרֻלִּים. גְּדוֹלִים מִקִּמְּשׂוֹנִים, וַהֲרֵי הֵם חַדִּים כְּקוֹצִים:\",3,0],[2,135,24,31,\"וְגֶדֶר אֲבָנָיו נֶהֱרָסָה. כָּךְ מִי שֶׁאֵינוֹ חוֹזֵר עַל תַּלְמוּדוֹ, מִתְּחִלָּה מְשַׁכֵּחַ רָאשֵׁי פְרָקִים, וְסוֹף מְחַלֵּף דִּבְרֵי חֲכָמִים מִזֶּה לָזֶה (אבות דרבי נתן כד,ו), שֶׁאוֹמֵר עַל טָהוֹר טָמֵא וְעַל טָמֵא טָהוֹר, וְהוּא מַחֲרִיב אֶת הָעוֹלָם:\",4,0],[2,135,24,34,\"מִתְהַלֵּךְ רֵישֶׁךָ. הַדְּבָרִים שֶׁאַתָּה רָשׁ מֵהֶם יָבוֹאוּ לְךָ בִּמְרוּצָה:\",1,0],[2,135,25,1,\"גַּם אֵלֶּה מִשְׁלֵי שְׁלֹמֹה אֲשֶׁר הֶעְתִּיקוּ. חָזַר לְדוֹרְשָׁם, כְּשֶׁנִּתְמַנָּה חִזְקִיָּהוּ לְמֶלֶךְ וְהוּא הוֹשִׁיב תַּלְמִידִים בְּכָל עִיר, כְּדְאָמְרִינַן בְּפֶרֶק חֵלֶק (סנהדרין צד:): בָּדְקוּ מִדָּן וְעַד בְּאֵר שֶׁבַע וְלֹא מָצְאוּ עַם הָאָרֶץ:\",1,0],[2,135,25,1,\"הֶעְתִּיקוּ. הֶחֱזִיקוּ:\",2,0],[2,135,25,2,\"כְּבוֹד אֱלֹהִים הַסְתֵּר דָּבָר. כְּגוֹן מַעֲשֵׂה מֶרְכָּבָה (יחזקאל א) וּמַעֲשֵׂה בְרֵאשִׁית (בראשית א):\",1,0],[2,135,25,2,\"וּכְבוֹד מְלָכִים חֲקֹר דָּבָר. כְּשֶׁאַתָּה דּוֹרֵשׁ בִּכְבוֹד מְלָכִים אוֹ בִּכְבוֹד חֲכָמִים שֶׁעָשׂוּ סְיָגִים לַתּוֹרָה וּבַגְּזֵרוֹת שֶׁגָּזְרוּ בָּהֶם, יֵשׁ לְךָ לַחֲקֹר וְלִדְרֹשׁ וְלִשְׁאֹל טַעַם לַדָּבָר. אֲבָל כְּשֶׁתִּדְרֹשׁ בְּמַעֲשֵׂה מֶרְכָּבָה וּבְמַעֲשֵׂה בְרֵאשִׁית וּבַחֻקִּים הַכְּתוּבִים בַּתּוֹרָה, כְּגוֹן חֻקִּים וּדְבָרִים שֶׁהַשָּׂטָן מְקַטְרֵג עֲלֵיהֶם וּמֵשִׁיב עֲלֵיהֶם, בַּאֲכִילַת חֲזִיר וְכִלְאֵי כֶּרֶם וְשַׁעַטְנֵז, אֵין לְךָ לַחֲקֹר רַק לְהַסְתִּיר, וְלוֹמַר: גְּזֵרַת מֶלֶךְ הוּא:\",2,0],[2,135,25,3,\"אֵין חֵקֶר. לְרוּם שָׁמַיִם וּלְעוֹמֶק הָאָרֶץ וּלְלֵב מְלָכִים אֵין חֵקֶר, שֶׁכַּמָּה דִינִים בָּאִים לִפְנֵיהֶם וְכַמָּה מִלְחָמוֹת, וּצְרִיכִים לָתֵת לֵב לְכֻלָּם. וְאִם כָּל הַלְּשׁוֹנוֹת מְדַבְּרִים וְכָל הַיָּדַיִם כּוֹתְבִין, אֵינָן יְכוֹלִין לִכְתּוֹב חֲלָלָהּ שֶׁל רְשׁוּת:\",1,0],[2,135,25,4,\"הָגוֹ סִיגִים מִכָּסֶף. מָשׁוּךְ, כְּמוֹ ״כַּאֲשֶׁר הֹגָה מִן הַמְּסִלָּה״ (שמואל ב כ:יג); כְּשֵׁם שֶׁאֵין הַכְּלִי שֶׁל כֶּסֶף יוֹצֵא לִמְלֶאכֶת צוֹרֵף עַד שֶׁיּוֹצִיאוּ מִמֶּנּוּ סִיגִים שֶׁל נְחֹשֶׁת שֶׁבּוֹ, כָּךְ אֵין צִבּוּר נִפְטָרִין מֵעֹנֶשׁ עַד שֶׁיּוֹצִיאוּ מִתּוֹכָם הָרְשָׁעִים וְיַעֲשׂוּ בָּהֶם דִּין:\",1,0],[2,135,25,6,\"אַל תִּתְהַדַּר לִפְנֵי מֶלֶךְ. לְהֵרָאוֹת כְּבוֹדְךָ וּלְהִתְגָּאוֹת לִפְנֵי מֶלֶךְ אוֹ לַעֲמֹד לִפְנֵי מִי שֶׁגָּדוֹל מִמְּךָ, כִּי טוֹב שֶׁיֹּאמְרוּ לְךָ עֲלֵה הֵנָּה מִשֶּׁתָּבוֹא בְּלֹא רְשׁוּתוֹ וְיֹאמְרוּ לְךָ צֵא:\",1,0],[2,135,25,7,\"אֲשֶׁר רָאוּ עֵינֶיךָ. שֶׁדָּבָר זֶה אֱמֶת:\",1,0],[2,135,25,8,\"פֶּן מַה תַּעֲשֶׂה. פֶּן תָּבֹא לִידֵי לֹא תֵדַע מַה לַּעֲשׂוֹת בְּאַחֲרִיתָהּ:\",1,0],[2,135,25,9,\"רִיבְךָ רִיב אֶת רֵעֶךָ. וְאִם עַל כָּרְחֲךָ אַתָּה צָרִיךְ לָרִיב וּלְהוֹכִיחַ עִם רֵעֶךָ, מִכָּל מָקוֹם, סוֹד אַחֵר אַל תְּגָל. לֹא תַזְכִּיר לוֹ דֹּפִי אֲבוֹתָיו שֶׁמֵּתוּ, שֶׁאֵין הַכֹּל יוֹדְעִין אוֹתוֹ וְאַתָּה מְגַלֵּהוּ (סנהדרין מד:):\",1,0],[2,135,25,10,\"פֶּן יְחַסֶּדְךָ שׁוֹמֵעַ. ״חֶרְפַּת מִצְרַיִם״ (יהושע ה:ט) מְתַרְגְּמִינָן: ״חֲסוּדָא דְּמִצְרָאֵי״, פֶּן יְחַסֶּדְךָ, הַשּׁוֹמֵעַ וְיִקְרָאֲךָ מוֹצִיא דִּבָּה:\",1,0],[2,135,25,11,\"תַּפּוּחֵי זָהָב. כְּעֵין כַּפְתּוֹרִין מְצֻיָּרִין עַל מַשְׂכִּיּוֹת כָּסֶף. מַשְׂכִּיּוֹת כֵּלִים הַמְצֻפִּין בְּכֶסֶף, כְּמוֹ ״וְשַׂכֹּתִי כַפִּי״ (שמות לג:כב):\",1,0],[2,135,25,11,\"דָּבָר דָּבוּר עַל אָפְנָיו. עַל כַּנּוֹ, וְדוּגְמָתוֹ ״נָשָׂאתִי אֵימֶיךָ אָפוּנָה״ (תהלים פח:טז) – מְבֻסֶּסֶת וּמְיֻשֶּׁבֶת בְּקִרְבִּי. וְאֵין זֶה מִגִּזְרַת ׳אוֹפַן וְגַלְגַּל׳ (ישעיהו כח:כז-כח), שֶׁאִלּוּ כֵּן, הָיָה נָקוּד פַּתָּ״ח תַּחַת הַפֵּ״א כְּמוֹ ״הָאוֹפַנִּים״ (מלכים א ז:לב), וְלֹא יִפֹּל בּוֹ נְקֻדַּת חֲטַף קָמַץ:\",2,0],[2,135,25,12,\"נֶזֶם זָהָב וַחֲלִי כָתֶם. עֲדִי קְבוּצַת זָהָב, כְּמוֹ ״וַתַּעַד נִזְמָהּ וְחֶלְיָתָהּ״ (הושע ב:טו), כְּמוֹ ״חֲלָאִים״ (שיר השירים ז:ב):\",1,0],[2,135,25,12,\"כֶּתֶם. לְשׁוֹן תַּכְשִׁיט זָהָב, וְכֵן ״כֶּתֶם פָּז״ (שיר השירים ה:יא):\",2,0],[2,135,25,13,\"כְּצִנַּת שֶׁלֶג. כְּקוֹר יְמֵי שֶׁלֶג שֶׁאָדָם מִתְאַוֶּה לוֹ בִּימֵי קָצִיר, וְלֹא שֶׁלֶג מַמָּשׁ, שֶׁהַשֶּׁלֶג לֹא טוֹב הוּא בִּשְׁעַת קָצִיר:\",1,0],[2,135,25,14,\"נְשִׂיאִים וְרוּחַ וְגוֹ׳. כַּאֲשֶׁר יִהְיֶה תּוֹחֶלֶת שָׁוְא כְּשֶׁהַשָּׁמַיִם מִתְקַשְּׁרִים בֶּעָבִים וְהָרוּחַ מְנַשֶּׁבֶת וְאָדָם מְצַפֶּה שֶׁיָּבֹא גֶשֶׁם וְלֹא בָא, וְהֵם מִצְטַעֲרִים וְכָלוֹת עֵינֵיהֶם, כָּךְ אִישׁ מִתְפָּאֵר לוֹמַר: כָּךְ וְכָךְ צְדָקָה אֶתֵּן לְיַד גַּבַּאי, וְהוּא מְשַׁקֵּר, וְכָלוֹת עֵינֵי עֲנִיִּים לְמַתְּנָתוֹ וְאֵינָהּ בָּאָה:\",1,0],[2,135,25,15,\"בְּאֹרֶךְ אַפַּיִם יְפֻתֶּה קָצִין. בְּעוֹד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַאֲרִיךְ אַפּוֹ וְאֵינוֹ נִפְרָע, יִתְּנוּ לֵב הַחוֹטְאִים לְפַתּוֹתוֹ בִּתְשׁוּבָה וּתְפִלָּה:\",1,0],[2,135,25,15,\"וְלָשׁוֹן רַכָּה. בִּתְפִלָּה וְתַחֲנוּנִים:\",2,0],[2,135,25,15,\"תִּשְׁבָּר גָּרֶם. עֶצֶם קֹשִׁי הַגְּזֵרָה:\",3,0],[2,135,25,16,\"דְּבַשׁ מָצָאתָ וְגוֹ׳:\",1,0],[2,135,25,17,\"הוֹקַר רַגְלְךָ. כְּשֵׁם שֶׁאִם מָצָאתָ דְּבַשׁ וְהוּא מָתוֹק לְחִכְּךָ, אַתָּה צָרִיךְ שֶׁלֹּא תֹּאכַל מִמֶּנּוּ פֶּן תִּשְׂבָּעֶנּוּ וַהֲקֵאֹתוֹ, כָּךְ הוֹקַר רַגְלְךָ מִבֵּית רֵעֶךָ אַע״פּ שֶׁהוּא מְקָרֶבְךָ, מְנַע מִלָּבֹא שָׁם יוֹם יוֹם פֶּן יִשְׂבָּעֲךָ וְיִשְׂנָא אוֹתְךָ. וּלְעִנְיַן מִדְרָשׁוֹ (חגיגה ז.): אַל תְּהִי רָגִיל לַחֲטֹא שׁוֹגֵג וּלְהָבִיא תָּמִיד חַטָּאוֹת וַאֲשָׁמוֹת לְבֵית ה׳ שֶׁנִּקְרָא רֵעַ לְיִשְׂרָאֵל, דִּכְתִיב ״זֶה דוֹדִי וְזֶה רֵעִי״ (שיר השירים ה:טז):\",1,0],[2,135,25,18,\"מֵפִיץ וְחֶרֶב. שֵׁם כְּלֵי מִלְחָמָה:\",1,0],[2,135,25,19,\"שֵׁן רֹעָה. רְצוּצָה:\",1,0],[2,135,25,19,\"מוּעָדֶת. כְּמוֹ ״וְלֹא מָעֲדוּ קַרְסֻלָּי״ (תהלים יח:לז):\",2,0],[2,135,25,19,\"מִבְטָח בּוֹגֵד. מְכַזֵּב בּוֹ בְּיוֹם צָרָתוֹ כְּשֵׁן רְצוּצָה וּמוּעֶדֶת:\",3,0],[2,135,25,20,\"מַעֲדֶה בֶּגֶד בְּיוֹם קָרָה. ״בֶּגֶד עִדִּים״ (ישעיה סד:ה): בֶּגֶד מוּסָר, כְּלִי שֶׁהוּא רָאוּי לַהֲסִירוֹ מֵעָלָיו לְפִי שֶׁהוּא בָּלוּי; כְּדִמְתַרְגְּמִינָן ״וַיָּסַר״ (בראשית ח:יג): ״וְיַעְדֵּי״ (תרגום אונקלוס). וְזֶה פִּתְרוֹנוֹ: בֶּגֶד בָּלוּי הֲרֵי הוּא בְּיוֹם קָרָה כְּחֹמֶץ עַל נָתֶר. נָתֶר. מִין אֲדָמָה רַכָּה, כְּגוֹן אֲדָמָה שֶׁלָּנוּ הַנִּקְרָא קְרִידָ״א, וְהָיוּ חוֹקְקִים אוֹתָהּ וְעוֹשִׂין כֵּלִים; וְאִם יִפֹּל בּוֹ חֹמֶץ, מְמַסְמְסוֹ וְנִשְׁחָת. אַף שָׁר בַּשִּׁרִים עַל לֶב רָע. דּוֹמֶה לִשְׁנֵיהֶם. וּמַה הוּא שָׁר בַּשִּׁירִים? זֶה הַמְּלַמֵּד תּוֹרָה לְתַלְמִיד רָשָׁע אֲשֶׁר אֵין בְּלִבּוֹ לְקַיְּמָהּ (חולין קלג.):\",1,0],[2,135,25,21,\"אִם רָעֵב שֹׂנַאֲךָ. כְּמַשְׁמָעוֹ, וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ (סוכה נב,א-ב) עַל יֵצֶר הָרָע: אִם רָעֵב הוּא וְאוֹמֵר לְךָ לְהַשְׂבִּיעוֹ בַּעֲבֵרוֹת, מְשׁוֹךְ אֶת עַצְמְךָ לְבֵית הַמִּדְרָשׁ וְהַאֲכִילֵהוּ מִלַּחְמָהּ שֶׁל תּוֹרָה, וְכֵן הַשְׁקֵהוּ מָיִם. מִימֶיהָ שֶׁל תּוֹרָה:\",1,0],[2,135,25,22,\"כִּי גֶחָלִים. הֵם לוֹ שֶׁאַתָּה חֹתֶה וְשׁוֹאֵב מִן הַמְּדוּרָה לָתֵת עַל רֹאשׁוֹ:\",1,0],[2,135,25,22,\"חוֹתֶה. כָּל שְׁאִיבַת גֶּחָלִים מִתּוֹךְ הַהֶסֵּק קָרֵי חוֹתֶה, כְּדַאֲמַר ״לַחְתּוֹת אֵשׁ מִיָּקוּד״ (ישעיהו ל:יד):\",2,0],[2,135,25,22,\"וַה׳ יְשַׁלֶּם לָךְ. יַשְׁלִימֶנּוּ עִמָּךְ, שֶׁלֹּא יִתְגַּבֵּר עָלֶיךָ:\",3,0],[2,135,25,23,\"רוּחַ צָפוֹן תְּחוֹלֵל גָּשֶׁם. תּוֹלִיד וְתִבְרָא אֶת הַגֶּשֶׁם:\",1,0],[2,135,25,23,\"וּפָנִים נִזְעָמִים תְּחוֹלֵל לְשׁוֹן סָתֶר. לָשׁוֹן הָרָע גּוֹרֵם שֶׁיִּהְיוּ פְּנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא נִזְעָמִים. וְכֵן דִּמְיוֹן פִּתְרוֹן הַמִּקְרָא: רוּחַ צָפוֹן עֲשׂוּיָה לְחוֹלֵל גָּשֶׁם, וְלְשׁוֹן סָתֶר עֲשׂוּיָה לְפָנִים נִזְעָמִים:\",2,0],[2,135,25,24,\"טוֹב שֶׁבֶת עַל פִּנַּת גָּג. עַל סִלּוּק הַשְּׁכִינָה נֶאֱמַר (איכה רבה פתיחתא כה):\",1,0],[2,135,25,24,\"מֵאֵשֶׁת מִדְיָנִים. כְּנֶסֶת יִשְׂרָאֵל שֶׁהִרְשִׁיעוּ אֶת מַעֲשֵׂיהֶם וְהִקְנִיטוּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,135,25,24,\"וּבֵית חָבֶר. בַּיִת שֶׁחִבְּרוּ בּוֹ גִּלּוּלִים לַשְּׁכִינָה:\",3,0],[2,135,25,25,\"עַל נֶפֶשׁ עֲיֵפָה. עֲשׂוּיָה לְהָשִׁיב נֶפֶשׁ עֲיֵפָה:\",1,0],[2,135,25,25,\"וּשְׁמוּעָה טוֹבָה. אַף הִיא שָׁוָה לָהֶם, וְכֵן יַעֲקֹב: ״וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם״ (בראשית מה:כז):\",2,0],[2,135,25,26,\"מַעְיָן נִרְפָּשׂ. עָכוּר בָּרַגְלַיִם:\",1,0],[2,135,25,26,\"צַדִּיק מָט לִפְנֵי רָשָׁע. כְּשֶׁהַצַּדִּיק מָט לִפְנֵי הָרָשָׁע וְיָרֵא לְהוֹכִיחַ עַל פָּנָיו דַּרְכּוֹ, שָׂנאוּי הַדָּבָר כְּמַעְיָן נִרְפָּשׂ וּמָקוֹר נִשְׁחָת:\",2,0],[2,135,25,27,\"אָכוֹל דְּבַשׁ. לֶאֱכוֹל דְּבַשׁ יוֹתֵר מִדַּאי. רֶמֶז הַדָּבָר לְדוֹרֵשׁ בְּמַעֲשֵׂה מֶרְכָּבָה (יחזקאל א) וּבְמַעֲשֵׂה בְרֵאשִׁית (בראשית א) לְגַלּוֹת לָרַבִּים, וְעַמֵּי הָאָרֶץ מְלַגְלְגִים עַל הַדְּבָרִים, וְשׁוֹאֲלִים מַה לְּמַעְלָה מַה לְּמַטָּה:\",1,0],[2,135,25,27,\"וְחֵקֶר כְּבוֹדָם כָּבוֹד. וְהֵיכָן הַחֵקֶר רָאוּי לִהְיוֹת? בְּדִבְרֵי חֲכָמִים, אֲשֶׁר כְּבוֹדָם כָּבוֹד בִּגְזֵרוֹתֵיהֶם, יֵשׁ לִשְׁאוֹל מָה טַעַם גָּזְרוּ כָּךְ, וְלָמָּה סִיְּגוּ בְּכָל גְּזֵרָה וּגְזֵרָה:\",2,0],[2,135,26,1,\"כַּשֶּׁלֶג בַּקַּיִץ. בְּשָׁעָה שֶׁשּׁוֹטְחִין הַתְּאֵנִים בַּחַמָּה לְיַבְּשָׁן וְלַעֲשׂוֹת קְצִיעוֹת, כְּדַאֲמַר ״הַלֶּחֶם וְהַקַּיִץ לֶאֱכֹל הַנְּעָרִים״ (שמואל ב טז:ב):\",1,0],[2,135,26,2,\"כַּצִּפּוֹר לָנוּד. שֶׁהוּא נָד, וְכַדְּרוֹר שֶׁהוּא חוֹזֵר לְקִנּוֹ:\",1,0],[2,135,26,2,\"כֵּן קִלְלַת חִנָּם לוֹ תָבוֹא. לְמִי שֶׁהוֹצִיאָהּ בְּפִיו:\",2,0],[2,135,26,2,\"דְּרוֹר. הוּא עוֹף הַנִּקְרָא רונדל״ע בְּלַעַ״ז, וְנִקְרָא דְּרוֹר – שֶׁדָּרָה בַּבַּיִת כְּבַשָּׂדֶה:\",3,0],[2,135,26,3,\"שׁוֹט לַסּוּס. הוּא עָשׂוּי, וְאַף שֵׁבֶט נָכוֹן לְגֵו כְּסִילִים. יִסּוּרִין מוּכָנִין לָרָשָׁע (שמות רבה ט:ח):\",1,0],[2,135,26,4,\"אַל תַּעַן כְּסִיל. בְּדִבְרֵי רִיב וּמַצָּה, פֶּן תִּשְׁוֶה לּוֹ:\",1,0],[2,135,26,5,\"עֲנֵה כְסִיל. הַבָּא לַהֲסִיתְךָ לַעֲבוֹדָה זָרָה, הוֹדַע לוֹ אִוַּלְתּוֹ:\",1,0],[2,135,26,5,\"פֶּן יִהְיֶה חָכָם בְּעֵינָיו. וְטַעַם שְׁנֵי פְסוּקִים אֵלּוּ מְפֹרָשׁ בְּתוֹכָם: אַל תַּעַן בְּדָבָר שֶׁתִּשְׁוֶה לוֹ אִם תַּעֲנֵהוּ, עֲנֵה כְסִיל בְּדָבָר שֶׁאִם לֹא תַעֲנֵהוּ יִהְיֶה חָכָם בְּעֵינָיו:\",2,0],[2,135,26,6,\"מְקַצֶּה רַגְלַיִם חָמָס שׁוֹתֶה. מִי שֶׁשּׁוֹלֵחַ דְּבָרִים בְּיַד כְּסִיל הוּא מְקַצֶּה רַגְלֵי שְׁלוּחִים הַרְבֵּה, לַחֲזוֹר וְלִשְׁלֹחַ לְתַקֵּן מַה שֶּׁעִוֵּת הָרִאשׁוֹן, אֲשֶׁר שְׁלָחוֹ בַּתְּחִלָּה; וְשׁוֹתֶה חָמָס. שֶׁחֲבֵרוֹ זוֹעֵף עָלָיו עַל שְׁלִיחוּת הַכְּסִיל:\",1,0],[2,135,26,7,\"דַּלְיוּ שׁוֹקַיִם מִפִּסֵּחַ. גָּבְהוּ, כְּמוֹ ״דָּלּוּ עֵינַי״ (ישעיהו לח:יד); הַשּׁוֹקַיִם שֶׁל כָּל אָדָם נִרְאִין לַפִּסֵּחַ גְּבוֹהִים מִמֶּנּוּ. וְדָבָר זֶה מָשָׁל בְּפִי כְסִיל, הָאוֹמֵר אוֹתוֹ עַל לִמּוּד הַחָכְמָה: אֵיךְ אָנוּ בָּאִים לִלְמֹד הַחָכְמָה? נִפְלָאָה וּגְבוֹהָה הִיא מִמֶּנּוּ! הַמָּשָׁל אוֹמֵר: דַּלְיוּ שׁוֹקַיִם מִפִּסֵּחַ:\",1,0],[2,135,26,8,\"בְּמַרְגֵּמָה. פְרוֹנְדוֹלָ״א בְּלַעַ״ז, שֶׁאֶבֶן שֶׁצּוֹרְרִין בּוֹ לֹא לְהִתְקַיֵּם הִיא שָׁם, שֶׁעוֹמֶדֶת לְהִזָּרֵק. כָּךְ הַנּוֹתֵן לִכְסִיל כָּבוֹד אֵינוֹ שֶׁל קַיָּמָא. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה דָּרְשׁוּ (חולין קלג.) עַל הַמְּלַמֵּד תּוֹרָה לְתַלְמִיד שֶׁאֵינוֹ הָגוּן, שֶׁהוּא כְּזוֹרֵק אֶבֶן לְמַרְקוּלִיס:\",1,0],[2,135,26,9,\"חוֹחַ עָלָה בְיַד שִׁכּוֹר. כְּחוֹחַ שֶׁהוּא נִדְבָּק בְּיַד שִׁכּוֹר, כֵּן הַמָּשָׁל הָאָמוּר לְמַטָּה (משלי כו:י) נִדְבָּק בְּפִי הַכְּסִיל לִהְיוֹת לָהֶם לְחוֹחַ וּלְקוֹץ מַכְאִיב. וּמַהוּ הַמָּשָׁל?\",1,0],[2,135,26,10,\"רַב מְחוֹלֵל כֹּל. הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אֶת הַכֹּל וְדָן אֶת הַכֹּל; כַּכְּסִיל כֶּחָכָם, אֵין אָנוּ צְרִיכִין לְשׁוּם חָכְמָה:\",1,0],[2,135,26,10,\"וְשׂוֹכֵר כְּסִיל. לֹא כְּבָשָׂר וָדָם שֶׁלֹּא יִשְׂכֹּר אֶלָּא פּוֹעֲלִים בְּקִיאִים וְלֹא יִשְׂכֹּר אֶלָּא הָעוֹסְקִים בִּמְלַאכְתּוֹ, אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא מְחוֹלֵל כֹּל וְשׂוֹכֵר הַכְּסִילִים וְשׂוֹכֵר עוֹבֵר דְּרָכִים הַבַּטְלָנִים מִכָּל מְלָאכָה. וּמִדְרַשׁ אַגָּדָה: וְשׂוֹכֵר כְּסִיל מִלְּשׁוֹן ״וַיִּסָּכְרוּ מַעְיְנוֹת תְּהוֹם״ (בראשית ח:ב), וּלְשׁוֹן ״עֹשֵׂי שֶׂכֶר״ (ישעיהו יט:י): הַקָּדוֹשׁ בָּרוּךְ הוּא סוֹכֵר מַזַּל כְּסִיל הַמְשַׁמֵּשׁ בִּימוֹת הַחַמָּה מִתִּשְׁרֵי וְאֵילָךְ, וּמֵאָז הוּא סוֹכֵר וְסוֹגֵר כָּל עוֹבְרֵי הַיָּם מִלֵּילֵךְ בּוֹ עַד הַפֶּסַח. וּבְדִבְרֵי רַבִּי מֹשֶׁה רָאִיתִי: רַב מְחוֹלֵל כֹּל עָשִׁיר יֵשׁ לוֹ פְּעֻלּוֹת הַרְבֵּה, וְאִם שׂוֹכֵר כְּסִיל בִּמְלַאכְתּוֹ הִנֵּה הוּא כְּשׂוֹכֵר כָּל עוֹבְרֵי דֶרֶךְ שֶׁרוֹאִין בְּקִלְקוּל הַמְּלָאכָה, לְהוֹרוֹת אֵיךְ יִתָּכֵן וְאֵיךְ יֵשׁ לוֹ לִפְעֹל; וְדָבָר רֵיק הוּא, וְאֵינוֹ עִנְיָן כָּאן:\",2,0],[2,135,26,15,\"בַּצַּלָּחַת. בְּיוֹרָה חַמָּה נוֹתֵן יָדוֹ, מִפְּנֵי הַקֹּר:\",1,0],[2,135,26,16,\"מְשִׁיבֵי טָעַם. חֲכָמִים:\",1,0],[2,135,26,17,\"מַחֲזִיק בְּאָזְנֵי כָלֶב. הָעוֹבֵר לְהִתְעַבֵּר עַל רִיב לֹא לוֹ הֲרֵי הוּא כְּאוֹחֵז בְּאָזְנֵי כָּלֶב, הַגּוֹרֵם שֶׁיִּשְּׁכֶנּוּ עַל חִנָּם:\",1,0],[2,135,26,18,\"כְּמִתְלַהְלֵהַּ. כְּמִתְיַגֵּעַ לִירוֹת זִיקִים שֶׁל אֵשׁ, כְּמוֹ ״וּבְזִיקוֹת בְּעַרְתֶּם״ (ישעיה נ:יא), מִלְּשׁוֹן ׳זִיקוּקִים דִּינוּר׳ (ברכות נח:). דָּבָר אַחֵר: זִיקִים. ׳פְרוֹנְזוֹלָ״שׁ׳, מִלְּשׁוֹן ״אַבְנֵי קָלַע״ (זכריה ט:טו), וְכֵן בַּגְּמָרָא (בבא מציעא צד.): זִיקְתָא פְּסִיק לָן; וְיוֹרֶה חִצִּים וָמָוֶת:\",1,0],[2,135,26,19,\"כֵּן אִישׁ רִמָּה. מְפַתֶּה וּמֵסִית אֶת חֲבֵירוֹ מִדַּרְכֵי חַיִּים לְדַרְכֵי מָוֶת, וּכְשֶׁחֲבֵירוֹ מַרְגִּישׁ שֶׁהוּא מַתְעֶה אוֹתוֹ, אוֹמֵר: מְצַחֵק אָנִי (בראשית רבה נג,יא):\",1,0],[2,135,26,20,\"בְּאֶפֶס עֵצִים. כְּלוֹמַר שְׁנֵי דְבָרִים אֵלּוּ שָׁוִין: כְּשֵׁם שֶׁבְּאֶפֶס עֵצִים תִּכְבֶּה אֵשׁ, כָּךְ בְּאֵין נִרְגָּן שֶׁל לָשׁוֹן הָרָע הַמְסַכְסֵךְ בַּעֲלֵי רִיב, יִשְׁתֹּק מָדוֹן:\",1,0],[2,135,26,21,\"פֶּחָם לְגֶחָלִים וְעֵצִים לְאֵשׁ. פֶּחָם שֶׁל אֵשׁ עָשׂוּי לְהַבְעִיר גֶּחָלִים עֲמוּמוֹת וְעֵצִים עֲשׂוּיִן לְהַסִּיק אֵשׁ, וְאִישׁ מָדוֹן לְחַרְחַר רִיב:\",1,0],[2,135,26,22,\"כְּמִתְלַהֲמִים. לְשׁוֹן מִתְלַחֲמִים. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה פֵּרְשׁוּ (ספרי דברים כד) כְּמִתְלַהֲמִים: כְּמֵת לָהֶם. דִּבְרֵי הַמְרַגְּלִים הָיוּ לָהֶם לְמִיתָה:\",1,0],[2,135,26,22,\"חַדְרֵי בָטֶן. הִיא מִיתַת הַדְּרוֹקָן:\",2,0],[2,135,26,23,\"מְצֻפֶּה עַל חָרֶשׂ. כְּסִיגֵי כֶסֶף הַמְּדֻבָּקִים עַל הַחֶרֶשׂ שֶׁצּוֹרְפִין אוֹתוֹ בּוֹ, וְהוּא מַבְהִיק כְּאִלּוּ הוּא כֶּסֶף, וְאֵין בּוֹ תּוֹעֶלֶת, כֵּן שְׂפָתַיִם דֹּלְקִים וְלֶב רָע. הָרוֹדְפִים אַחַר הַבְּרִיּוֹת לַהֲסִיתָם בַּחֲלָקוֹת וּמְדַבְּרִים אֶחָד בַּפֶּה וְאֶחָד בַּלֵּב:\",1,0],[2,135,26,23,\"וְלֵב רָע. נִרְאִין כְּאוֹהֲבִין וְהֵם אוֹיְבִים:\",2,0],[2,135,26,23,\"דּוֹלְקִים. כְּמוֹ ״דָּלַקְתָּ אַחֲרָי״ (בראשית לא:לו):\",3,0],[2,135,26,24,\"יִנָּכֵר שׂוֹנֵא. בְּדִבּוּרוֹ מִתְנַכֵּר הַשּׂוֹנֵא, שֶׁלֹּא יַכִּירוּ שֶׁהוּא שׂוֹנֵא. דִישְׁקְנוֹיִישְׁ״ט בְּלַעַ״ז:\",1,0],[2,135,26,26,\"תִּכַּסֶּה שִׂנְאָה. הָעוֹשֶׂה מַעֲשָׂיו בַּמַּחְשָׁךְ וּמְכַסֶּה בְּמַשָּׁאוֹן, שֶׁהוּא חֹשֶׁךְ (  שׁוֹאַת חֹשֶׁךְ), אֶת הַדָּבָר הַשָּׂנאוּי לְהַקָּדוֹשׁ בָּרוּךְ הוּא, סוֹף שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה רָעָתוֹ בְקָהָל, שֶׁיַּכִּירוּ בּוֹ שֶׁהוּא רָשָׁע (סוטה ט.):\",1,0],[2,135,26,27,\"כּוֹרֶה שַׁחַת. כְּגוֹן בִּלְעָם, שֶׁהִשִּׂיא עֵצָה לְבָלָק עַל יִשְׂרָאֵל וְהִפִּיל מֵהֶם עֶשְׂרִים וְאַרְבָּעָה אֶלֶף (במדבר כה:ט), וּבָא לְמִדְיָן לִתְבּוֹעַ שְׂכָרוֹ וְנֶהֱרַג בְּיַד יִשְׂרָאֵל (במדבר לא:ח):\",1,0],[2,135,26,27,\"וְגוֹלֵל. כְּלוֹמַר: סוֹפוֹ שֶׁל הַמַּעֲמִיד מִכְשׁוֹל, שֶׁיִּכָּשֵׁל בּוֹ:\",2,0],[2,135,26,27,\"וְגוֹלֵל אֶבֶן. מְגַלְּלוֹ מִמָּקוֹם לְמָקוֹם, שֶׁיִּכָּשְׁלוּ בּוֹ בְּנֵי אָדָם. וְאַגָּדָה פּוֹתְרוֹ (תנחומא בובר, וירא כח) בַּאֲבִימֶלֶךְ שֶׁהָרַג שִׁבְעִים אֶחָיו עַל אֶבֶן אַחַת, וְסוֹף מֵת בָּאֶבֶן, שֶׁנֶּאֱמַר ״וַתַּשְׁלֵךְ אִשָּׁה אַחַת פֶּלַח רֶכֶב וַתָּרִץ גֻּלְגָּלְתּוֹ וְגוֹ׳״ (שופטים ט:נג):\",3,0],[2,135,26,28,\"יִשְׂנָא דַכָּיו. מִי שֶׁמְּקַבֵּל לָשׁוֹן הָרָע שׂוֹנֵא אֶת הַנִּדְכָּאִים תַּחְתָּיו, שֶׁכֵּן עַל לָשׁוֹן הָרָע רָדַף שָׁאוּל לְדָוִד וְהָרַג נוֹב (שמואל א כב:יח-יט):\",1,0],[2,135,26,28,\"וּפֶה חָלָק. פֶּה שֶׁל חֲלַקְלַקּוּת:\",2,0],[2,135,26,28,\"יַעֲשֶׂה מִדְחֶה. עוֹשֶׂה דִּיחוּי, שֶׁדּוֹחֶה אֶת מְקַבְּלוֹ מֵעַל הַקָּדוֹשׁ בָּרוּךְ הוּא:\",3,0],[2,135,27,1,\"אַל תִּתְהַלֵּל. אַל תִּתְפָּאֵר עַכְשָׁיו בְּדָבָר שֶׁעָתִיד לִהְיוֹת לְיוֹם מָחָר:\",1,0],[2,135,27,1,\"כִּי לֹא תֵדַע מַה יֵּלֶד יוֹם. שֶׁמָּא הַיּוֹם יִוָּלֵד שׁוּם רָעָה, שֶׁיְּבַטֵּל מַחְשְׁבוֹת מָחָר:\",2,0],[2,135,27,3,\"וְנֵטֶל. מַשָּׂא:\",1,0],[2,135,27,3,\"וְכַעַס אֱוִיל. שֶׁהָאֱוִיל מַכְעִיס לְהַקָּדוֹשׁ בָּרוּךְ הוּא, גּוֹרֵם לְהָבִיא כַּעַס לָעוֹלָם:\",2,0],[2,135,27,4,\"וְשֶׁטֶף אָף וּמִי יַעֲמֹד. לִפְנֵי קִנְאָתוֹ שֶׁל קַנָּא וְנַקָּם:\",1,0],[2,135,27,6,\"וְנַעְתָּרוֹת. לְשׁוֹן גֹּדֶל, כְּמוֹ ״הַעְתַּרְתֶּם עָלַי״ (יחזקאל לה:יג):\",1,0],[2,135,27,7,\"תָּבוּס נֹפֶת. תִּרְמוֹס בְּרֶגֶל, כְּמוֹ ״נָבוּס קָמֵינוּ״ (תהלים מד:ו):\",1,0],[2,135,27,7,\"כָּל־מַר מָתוֹק. כָּל דָּבָר מַר, מָתוֹק לָהּ. וְיֵשׁ לְפוֹתְרוֹ בְּתַלְמוּד תּוֹרָה: הַמַּרְאֶה אֶת עַצְמוֹ כְּשָׂבֵעַ, שֶׁאֵינוֹ מִתְאַוֶּה לְדִבְרֵי תוֹרָה לְתַאֲוַת נֶפֶשׁ, תָּבוּס נֹפֶת. אַף הַטְּעָמִים הַמְיֻשָּׁבִים עַל הַלֵּב אֵינָם חֲשׁוּבִים עָלָיו; וְהַמִּתְאַוֶּה לָהּ, אֲפִלּוּ דְּבָרִים הַבָּאִים לוֹ בִּמְרִירוּת וּבִיגִיעָה הֵם מְתוּקִים לוֹ:\",2,0],[2,135,27,8,\"נוֹדֶדֶת מִן קִנָּהּ. שֶׁהוֹלֶכֶת וּמִטַּלְטֶלֶת, כֵּן הָאִישׁ הַנּוֹדֵד מִמְּקוֹמוֹ. תַּלְמִיד חָכָם הַנּוֹדֵד מִן הַלִּמּוּד, מִלַּחֲזֹר עַל גִּרְסָתוֹ:\",1,0],[2,135,27,9,\"שֶׁמֶן וּקְטֹרֶת. רֵיחַ שֶׁמֶן אֲפַרְסְמוֹן וְרֵיחַ קְטֹרֶת מְשַׂמְּחִין לֵב:\",1,0],[2,135,27,9,\"וּמֶתֶק רֵעֵהוּ מֵעֲצַת נָפֶשׁ. מִי שֶׁחֲבֵרוֹ מְקָרְבוֹ וּמְמַתֵּק לוֹ בִּדְבָרָיו, הוּא טוֹב מִמַּה שֶׁנַּפְשׁוֹ יוֹעַצְתּוֹ. דָּבָר אַחֵר: וּמֶתֶק רֵעֵהוּ הַמַּכְשִׁיר מַעֲשָׂיו, שֶׁהֵן מְתוּקִין לְהַקָּדוֹשׁ בָּרוּךְ הוּא, טוֹב לוֹ מִמַּה שֶׁהוּא מְמַלֵּא תַּאֲוַת לִבּוֹ:\",2,0],[2,135,27,10,\"רֵעֲךָ. וְרֵעַ אָבִיךָ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרָא רֵעַ לְיִשְׂרָאֵל, וְרֵעַ אָבִיךָ שֶׁחִיבֵּב אֶת אֲבוֹתֶיךָ:\",1,0],[2,135,27,10,\"אַל תַּעֲזֹב. אִם עָזַבְתָּ, יָבֹא עָלֶיךָ פֻּרְעָנוּת:\",2,0],[2,135,27,10,\"וּבֵית אָחִיךָ. אַל תִּבְטַח בִּבְנֵי עֵשָׂו וְיִשְׁמָעֵאל שֶׁיְּקָרְבוּךָ. מָצִינוּ (תנחומא, יתרו ה): כְּשֶׁגָּלוּ יִשְׂרָאֵל לְבָבֶל הָיוּ אוֹמְרִים לְמוֹלִיכֵיהֶם בְּקוֹלָר: בְּבַקָּשָׁה מִכֶּם, הוֹלִיכוּנוּ בְּדֶרֶךְ אַחֵינוּ בְּנֵי עֵשָׂו וְיִשְׁמָעֵאל, וְהָיוּ בְּנֵי יִשְׁמָעֵאל יוֹצְאִים לִקְרָאתָם וּמְקַדְּמִין אוֹתָם בְּמִינֵי מְלוּחִים וְנוֹדוֹת נְפוּחִים:\",3,0],[2,135,27,10,\"מֵאָח רָחוֹק. טוֹב שֶׁיִּשְׁכּוֹן בֵּינֵיכֶם הַקָּרוֹב לְקוֹרְאָיו (תהלים קמה:יח), מִשֶּׁתָּבוֹאוּ אֵצֶל אָח שֶׁנִּתְרַחֵק, לֵאמֹר ״יִקְרְבוּ יְמֵי אֵבֶל אָבִי וְגוֹ׳״ (בראשית כז:מא):\",4,0],[2,135,27,11,\"חֲכַם בְּנִי. הִתְחַכֵּם בְּנִי:\",1,0],[2,135,27,11,\"וְשַׂמַּח לִבִּי. וּתְהֵא לִבִּי שָׂמֵחַ בְּךָ:\",2,0],[2,135,27,12,\"עָרוּם רָאָה רָעָה. רוֹאֶה פֻּרְעָנוּת הַבָּאָה עַל הָאָרֶץ וְנִסְתָּר הֵימֶנָּה, שֶׁמָּשַׁךְ יָדוֹ מִן הָעֲבֵירָה. וּפְתָאיִם לֹא נִסְתְּרוּ אֶלָּא עָבְרוּ בְּדֶרֶךְ רָעָה:\",1,0],[2,135,27,12,\"וְנֶעֱנָשׁוּ. וְנִפְסְדוּ:\",2,0],[2,135,27,13,\"כִּי עָרַב זָר. אָדָם שֶׁנַּעֲשָׂה עָרֵב, גּוֹרֵם שֶׁאָמַר הַדַּיָּן לַמַּלְוֶה: קַח בִּגְדוֹ! (בבא מציעא קטו.):\",1,0],[2,135,27,14,\"מְבָרֵךְ רֵעֵהוּ. יֵשׁ מְשַׁבֵּחַ אֶת חֲבֵירוֹ יוֹם יוֹם, וְהַבְּרָכָה נֶהֱפֶכֶת לִקְלָלָה, שֶׁאוֹמְרִים עָלָיו שֶׁהוּא וַתְרָן בְּמָמוֹנוֹ וְעָשִׁיר, וְהַכֹּל בָּאִין וְשׁוֹאֲלִין מִמֶּנּוּ, וְהַמַּלְכוּת מִתְגָּרֶת בּוֹ לִגְבּוֹת מָמוֹן. כָּךְ נִדְרַשׁ בְּמַסֶּכֶת עֲרָכִין (ערכין טז.). וְעוֹד יֵשׁ בְּמִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, בלק כד): כְּנֶגֶד בִּלְעָם שֶׁהָיָה מְבָרֵךְ אֶת יִשְׂרָאֵל בְּקוֹל רָם, שֶׁנֶּאֱמַר ״וַיִּשָּׂא מְשָׁלוֹ וְגוֹ׳״ (במדבר כג:ז), לְשׁוֹן נְשִׂיאוּת קוֹל, וְסוֹפוֹ יָעַץ לְהַחֲטִיאָם:\",1,0],[2,135,27,15,\"דֶּלֶף טוֹרֵד. גֶּשֶׁם הַנּוֹטֵף מִן הַגַּג לְתוֹךְ הַבַּיִת וְטוֹרֵד אֶת בְּנֵי הַבַּיִת:\",1,0],[2,135,27,15,\"בְּיוֹם סַגְרִיר. יוֹם הַגֶּשֶׁם, שֶׁהַכֹּל נִסְגָּרִים בְּבָתֵּיהֶם:\",2,0],[2,135,27,15,\"וְאֵשֶׁת מְדִינִים נִשְׁתָּוָה. שְׁנֵיהֶם שָׁוִין (יבמות סג:):\",3,0],[2,135,27,16,\"צוֹפְנֶיהָ צָפַן רוּחַ. מִי שֶׁסָּבוּר לְשָׁמְרָהּ מִתְּזְנוּתֶיהָ, צְפוּנַת רוּחַ הוּא; כְּשֵׁם שֶׁאִי אֶפְשָׁר לִצְפֹּן הָרוּחַ, כֵּן הִיא, לֹא תִצָּפֵנֶה:\",1,0],[2,135,27,16,\"וְשֶׁמֶן יְמִינוֹ יִקְרָא. קוֹרֵא הוּא הַצָּרַעַת לָבוֹא עָלָיו עַד שֶׁיְּגָרְשֶׁנָּה, כַּמְּצֹרָע הַמִּטַּהֵר בְּשֶׁמֶן בְּבֹהֶן יָדוֹ הַיְמָנִית (ויקרא יד:יז):\",2,0],[2,135,27,17,\"יַחַד פְּנֵי רֵעֵהוּ. יַחַד תַּלְמִידֵי חֲכָמִים מְחַדְּדִין זֶה לָזֶה בַּהֲלָכָה (תענית ז.):\",1,0],[2,135,27,18,\"יֹאכַל פִּרְיָהּ. וְכֵן שׁוֹמֵר אֲדוֹנָיו יְכֻבָּד, וְיֹאכַל פְּרִי מַעֲלָלָיו:\",1,0],[2,135,27,19,\"כַּמַּיִם. הַלָּלוּ הַפָּנִים שֶׁאַתָּה מַרְאֶה לְתוֹכָן, הֵן מַרְאוֹת לְךָ:\",1,0],[2,135,27,19,\"כֵּן לֵב הָאָדָם לָאָדָם. חֲבֵרוֹ, לְפִי מַה שֶּׁאָדָם יוֹדֵעַ שֶׁחֲבֵרוֹ אוֹהֲבוֹ, כֵּן הוּא מַרְאֶה לוֹ פָּנִים:\",2,0],[2,135,27,20,\"שְׁאוֹל וַאֲבַדֹּה. לֹא תִשְׂבַּעְנָה מִלְּקַבֵּל אֶת הָרְשָׁעִים לְתוֹכָם, כְּשֵׁם שֶׁעֵינֵי הָאָדָם רָשָׁע לֹא תִשְׂבַּעְנָה מִלָּשׁוּט אַחַר יֵצֶר הָרָע, מִלְּמַלְּאוֹת תַּאֲוָתוֹ:\",1,0],[2,135,27,21,\"מַצְרֵף. כְּלִי עָשׂוּי לְצָרֵף כֶּסֶף וְהַכּוּר עָשׂוּי לִבְחוֹן זָהָב, וְאִישׁ נִצְרָף וּמִתְחַשֵּׁב לְפִי מַהֲלָלוֹ. עַל יְדֵי שֶׁהַבְּרִיּוֹת מְהַלְּלוֹת אוֹתוֹ בְּמַעֲשָׂיו הַטּוֹבִים, נִבְחָן לָרַבִּים, אִם טוֹב אִם רַע:\",1,0],[2,135,27,22,\"הָרִיפוֹת. חִטִּים הַנִּדּוֹכִים בַּמַּכְתֵּשׁ:\",1,0],[2,135,27,22,\"מַכְתֵּשׁ. אֲסִיתָא (חולין נב.), מוֹרְטִיוֹ״ר בְּלַעַ״ז:\",2,0],[2,135,27,22,\"בַּעֱלִי. הוּא בּוּכְנָא, פּוֹלִי״ן מוֹרְטְר״וֹ בְּלַעַ״ז. עַל שֵׁם שֶׁמַּעֲלִין אוֹתוֹ וּמַכִּין בּוֹ תָּמִיד נִקְרָא עֱלִי:\",3,0],[2,135,27,23,\"פְּנֵי צֹאנֶךָ. אַל יֵקַלּוּ בְּעֵינֶיךָ לְהִתְבּוֹנֵן בָּם תָּמִיד מַה הֵם צְרִיכִים:\",1,0],[2,135,27,24,\"כִּי לֹא לְעוֹלָם חֹסֶן. שֶׁאִם אַתָּה עָשִׁיר בְּכֶסֶף וּבְזָהָב, שֶׁמָּא לֹא יִתְקַיֵּם לְעוֹלָם. לְכָךְ אַל תְּבַזֶּה דְּבָרִים קְטַנִּים שֶׁלְּךָ:\",1,0],[2,135,27,25,\"גָּלָה חָצִיר. כְּשֶׁגָּלָה הֶחָצִיר בִּימֵי נִיסָן וְיִרְאָה הַדֶּשֶׁא וְנֶאֶסְפוּ עֲשָׂבִים לִצְמֹחַ, אָז יֵיטִיב לְךָ, שֶׁיִּהְיוּ גִּזּוֹתֵיהֶם שֶׁל כְּבָשִׂים לִלְבוּשֶׁךָ:\",1,0],[2,135,27,26,\"וּמְחִיר שָׂדֶה. יִשְׁווּ לְךָ הָעַתּוּדִים, כִּי תֹּאכַל הַבָּשָׂר וְתִמְכֹּר הָעוֹרוֹת:\",1,0],[2,135,27,27,\"וְדֵי. פַּרְנָסָתְךָ:\",1,0],[2,135,27,27,\"לְלַחְמְךָ וּלְלֶחֶם בֵּיתֶךָ. תִּסְתַּפֵּק בַּחֲלֵב הָעִזִּים. הֲרֵי מְלִיצָתוֹ. וְהַמָּשָׁל כֵּן הוּא: פְּנֵי צֹאנְךָ – הָרַב הַמִּתְמַנֶּה עַל הַצִּבּוּר, יִשָּׂאֵם בְּחֵיקוֹ וִינַהֲלֵם לְאַט (ישעיהו מ:יא), כִּי לֹא לְעוֹלָם חֹסֶן, וּבָזֹאת יֹאכַל פֵּרוֹת, וְהַקֶּרֶן קַיֶּמֶת:\",2,0],[2,135,27,27,\"גָּלָה חָצִיר. כְּשֶׁיִּתְפַּשְּׁטוּ שְׁמוּעוֹתָיו וְתִגְדַּל הַתּוֹרָה עַל יָדוֹ, אָז יִהְיוּ הַכְּבָשִׂים הָאֵלֶּה לְבוּשׁוֹ, יִהְיוּ הַתַּלְמִידִים לוֹ לְשֵׁם וּלְבוּשׁ הוֹד וְהָדָר:\",3,0],[2,135,28,1,\"נָסוּ וְאֵין רוֹדֵף רָשָׁע. נָסוּ הָרְשָׁעִים כְּשֶׁיָּבֹא אֵידָם וְיִפְּלוּ בְּדָבָר קַל מֵאֵין רוֹדֵף:\",1,0],[2,135,28,1,\"וְצַדִּיקִים. אַמִּיץ לִבָּם (עמוס ב:טז) בְּהַקָּדוֹשׁ בָּרוּךְ הוּא כִּכְפִיר אֲשֶׁר יִבְטַח בִּגְבוּרָתוֹ:\",2,0],[2,135,28,2,\"בְּפֶשַׁע אֶרֶץ רַבִּים שָׂרֶיהָ. שֶׁזֶּהוּ פֻּרְעָנוּת לָאָרֶץ, בִּהְיוֹת שָׂרֶיהָ רַבִּים הָרוֹדְפִים רַק אַחַר בִּצְעָם:\",1,0],[2,135,28,2,\"וּבְאָדָם מֵבִין. וּבִשְׁבִיל אָדָם מֵבִין יִתְאָרֵךְ הַפּוּרְעָנוּת מִלָּבוֹא:\",2,0],[2,135,28,3,\"גֶּבֶר רָשׁ. דַּיָּן עַם הָאָרֶץ:\",1,0],[2,135,28,3,\"עוֹשֵׁק דַּלִּים. בְּדִין עַל שֶׁאֵינוֹ מָתוּן בְּדִין, הֲרֵי הוּא כְּמָטָר הַסּוֹחֵף אֶת הַשָּׂדֶה וְאֵין עוֹשֶׂה פֵּרוֹת:\",2,0],[2,135,28,3,\"סוֹחֵף. שׁוֹטֵף, וּבַמִּשְׁנָה (כתובות ז,ח): ״נִסְתַּחֲפָה שָׂדֵהוּ״, וְכֵן ״נִסְחַף אַבִּירֶיךָ״ (ירמיהו מו:טו) – נִשְׁטְפוּ וּמָעֲדוּ וְכָשְׁלוּ:\",3,0],[2,135,28,5,\"אַנְשֵׁי רָע לֹא יָבִינוּ מִשְׁפָּט. אֵינָם מְשִׂימִים לֵב לְפוּרְעָנִיּוֹת הָעֲתִידוֹת, שֶׁיִּתְבּוֹנְנוּ בָּהּ וְיָשׁוּבוּ מִדַּרְכָּם וְיִנָּצְלוּ:\",1,0],[2,135,28,5,\"וּמְבַקְשֵׁי ה׳ יָבִינוּ כֹל. טוֹבָה וְרָעָה. מִשְׁפָּט. יוֹשְׁטִיצָ״א בְּלַעַ״ז; כָּךְ פֵּרֵשׁ רַבִּי תַּנְחוּמָא (תנחומא, בראשית לז) עַל דּוֹר הַמַּבּוּל:\",2,0],[2,135,28,6,\"טוֹב רָשׁ. אַף עָנִי שֶׁבַּתּוֹרָה:\",1,0],[2,135,28,6,\"וְהוֹלֵךְ בְּתֻמּוֹ. בְּמַעֲשִׂים טוֹבִים:\",2,0],[2,135,28,7,\"וְרוֹעֶה זוֹלְלִים. מְחַבֵּר לוֹ זוֹלְלִים, וְהוּא לְשׁוֹן רֵעִים:\",1,0],[2,135,28,8,\"מַרְבֶּה הוֹנוֹ בְּנֶשֶׁךְ וְתַרְבִּית לְחוֹנֵן דַּלִּים. הָרְשׁוּת שׁוֹמְעִין עָלָיו שֶׁהוּא מִתְעַשֵּׁר בְּלֹא מִשְׁפָּט, וְנוֹטְלִין מָמוֹנוֹ, וּבוֹנִין בּוֹ גְּשָׁרִים וּמְתַקְּנִין בּוֹ הַדְּרָכִים, וְזֶהוּ חֲנִינַת דַּלִּים. כָּךְ דְּרָשׁוֹ רַבִּי תַּנְחוּמָא (תנחומא, משפטים ה):\",1,0],[2,135,28,10,\"בִּשְׁחוּתוֹ. מִלְּשׁוֹן שַׁחַת:\",1,0],[2,135,28,11,\"אִישׁ עָשִׁיר וְדַל מֵבִין. כְּנֶגֶד רַב וְתַלְמִיד הוּא מְדַבֵּר, שֶׁהַתַּלְמִיד חוֹקֵר וְעַל יָדוֹ הָרַב מִתְחַכֵּם:\",1,0],[2,135,28,12,\"יְחֻפַּשׂ אָדָם. יִתְחַפֵּשׂ בְּכָל מִינֵי עֲלִילוֹת:\",1,0],[2,135,28,13,\"וּמוֹדֶה וְעוֹזֵב. מוֹדֶה פְּשָׁעָיו וְעוֹזְבָם מִשּׁוּב בָּם עוֹד:\",1,0],[2,135,28,14,\"מְפַחֵד תָּמִיד. דּוֹאֵג מֵעֹנֶשׁ, וּבְכָךְ מִתְרַחֵק מֵעֲבֵירָה:\",1,0],[2,135,28,15,\"אֲרִי נוֹהֵם. הוּא לָהֶם:\",1,0],[2,135,28,15,\"וְדֹב שׁוֹקֵק. נְהִימָה לַאֲרִי וּשְׁקִיקָה לַדֹּב, שְׁנֵיהֶם לְשׁוֹן צְעָקָה:\",2,0],[2,135,28,16,\"חֲסַר תְּבוּנוֹת. מִתּוֹךְ שֶׁהוּא חֲסַר תְּבוּנָה הוּא רַב מַעֲשַׁקּוֹת, כִּי אֵינוֹ נוֹתֵן לֵב עַל חַיָּיו וּמַרְבֶּה לַעֲשֹׁק; שֶׁהֲרֵי הַשׂוֹנֵא בֶצַע יַאֲרִיךְ יָמִים:\",1,0],[2,135,28,17,\"אָדָם עָשׁוּק בְּדַם נָפֶשׁ. (שֶׁיֵּשׁ עָלָיו עֹשֶׁק דָּם) הוּא הַמַּחֲטִיא אֶת חֲבֵרוֹ וְאָבְדָה נַפְשׁוֹ עַל יָדוֹ:\",1,0],[2,135,28,17,\"עַד בּוֹר יָנוּס. עַד יוֹם מוֹתוֹ יָנוּס לְעֶזְרָה, שֶׁיִּתְכַּפֵּר לוֹ:\",2,0],[2,135,28,17,\"וְאַל יִתְמְכוּ בוֹ. מִשָּׁמַיִם לְהַסְפִּיק בְּיָדוֹ לָשׁוּב, שֶׁלֹּא יְהֵא הוּא בְּגַן עֵדֶן וְתַלְמִידוֹ בְּגֵיהִנֹּם. כָּךְ נִדְרַשׁ בְּמַסֶּכֶת יוֹמָא (יומא פז.):\",3,0],[2,135,28,18,\"יִפּוֹל בְּאֶחָת. בְּרָעָה אַחַת, וְאֵין תְּקוּמָה לְמַפַּלְתּוֹ:\",1,0],[2,135,28,19,\"יִשְׂבַּע רִישׁ. עֲנִיּוּת:\",1,0],[2,135,28,20,\"אִישׁ אֱמוּנוֹת. הַנּוֹתֵן מַעַשְׂרוֹתָיו בֶּאֱמוּנָה, שֶׁאֵין עֵד בַּדָּבָר אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא, רוֹאֶה וּמַרְבֶּה לוֹ בְּרָכָה:\",1,0],[2,135,28,20,\"וְאָץ לְהַעֲשִׁיר. דּוֹחֵק הַשָּׁעָה לְהִתְעַשֵּׁר בְּשֶׁל עֲנִיִּים:\",2,0],[2,135,28,21,\"יִפְשַׁע גָּבֶר. הַמַּטֶּה מִשְׁפָּט:\",1,0],[2,135,28,22,\"נִבְהָל לַהוֹן. מְמַהֵר לְהַרְבּוֹת הוֹן וְגוֹזֵל תְּרוּמוֹתָיו וּמַעַשְׂרוֹתָיו (תנחומא, בהר א):\",1,0],[2,135,28,22,\"כִּי חֶסֶר יְבוֹאֶנּוּ. חִסָּרוֹן יָבֹא לוֹ, שֶׁהַמְּאֵרָה מִשְׁתַּלַּחַת בְּמַעֲשֵׂי יָדָיו:\",2,0],[2,135,28,23,\"מוֹכִיחַ אָדָם וְגוֹ׳. עַל עֲבֵירוֹת שֶׁבְּיָדוֹ וּמַפְרִישׁוֹ מֵהֶם:\",1,0],[2,135,28,23,\"אַחֲרַי חֵן. לְאַחַר זְמַן חֵן יִמְצָא בְּעֵינָיו יוֹתֵר מִמַּחֲלִיק לָשׁוֹן. מָצִינוּ בִּבְרֵאשִׁית רַבָּה (בראשית רבה מד:ה): כָּל מָקוֹם שֶׁנֶּאֱמַר ׳אַחֲרֵי׳ אֵינוֹ אֶלָּא מֻפְלָג, ׳אַחַר׳ סָמוּךְ. בְּתַנְחוּמָא (תנחומא, הוספה לפרשת דברים ב) עַל ״אֵלֶּה הַדְּבָרִים״ (דברים א:א): מוֹכִיחַ אָדָם אַחֲרַי, זֶה מֹשֶׁה שֶׁהוֹכִיחַ אֶת יִשְׂרָאֵל אַחַר הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנִּקְרְאוּ ׳אָדָם׳, שֶׁנֶּאֱמַר ״אָדָם אַתֶּם״ (יחזקאל לד:לא), וְנֶאֱמַר בּוֹ ״כִּי מָצָאתָ חֵן בְּעֵינַי״ (שמות לג:יז); מִמַּחֲלִיק לָשׁוֹן. זֶה בִּלְעָם, הָאוֹמֵר לְיִשְׂרָאֵל דְּבָרִים מְתֻקָּנִים ״מַה טֹּבוּ אֹהָלֶיךָ יַעֲקֹב״ (במדבר כד:ה). מֹשֶׁה מַכְרִיז: ״הִשָּׁמְרוּ לָכֶם פֶּן יִפְתֶּה״ (דברים יא:טז), וּבִלְעָם מַכְרִיז וּמַחֲנִיף: עֲשׂוּ תַּאֲוַתְכֶם וְאֵינוֹ מַקְפִּיד! ״לֹא אִישׁ אֵל וִיכַזֵּב״ (במדבר כג:יט) – בָּאֻמּוֹת, אֲבָל בָּכֶם אוֹמֵר וְלֹא יַעֲשֶׂה (ראה שם). וּשְׁלֹמֹה צָוַח עַל שְׁנֵיהֶם: ״נֶאֱמָנִים פִּצְעֵי אוֹהֵב וְנַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא״ (משלי כז:ו):\",2,0],[2,135,28,24,\"גּוֹזֵל אָבִיו. הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,135,28,24,\"וְאִמּוֹ. כְּנֶסֶת יִשְׂרָאֵל: הַמַּחֲטִיא אֶת הָרַבִּים, שֶׁגּוֹזֵל הַקָּדוֹשׁ בָּרוּךְ הוּא, מַפְרִיד מִמֶּנּוּ בָּנָיו וְגוֹזֵל מֵהֶם טוֹבָה:\",2,0],[2,135,28,24,\"מַשְׁחִית. יָרָבְעָם (סנהדרין קב.):\",3,0],[2,135,28,25,\"רְחַב נֶפֶשׁ. לְהַשִּׂיג כָּל תַּאֲוָתוֹ:\",1,0],[2,135,28,25,\"יְגָרֶה מָדוֹן. מְגָרֶה עָלָיו מִדַּת הַדִּין:\",2,0],[2,135,28,27,\"נוֹתֵן לָרָשׁ. צְדָקָה:\",1,0],[2,135,28,27,\"(אֵין מַחְסוֹר. לְהַרְבּוֹת לוֹ צְדָקָה סא״א). וְכֵן הָרַב שֶׁאֵינוֹ מוֹנֵעַ תּוֹרָה מִפִּי הַתַּלְמִיד:\",2,0],[2,135,29,1,\"מַקְשֶׁה עֹרֶף. מִלִּשְׁמֹעַ:\",1,0],[2,135,29,1,\"פֶּתַע יִשָּׁבֵר. מַהֵר יִשָּׁבֵר:\",2,0],[2,135,29,3,\"וְרוֹעֶה. מְחַבֵּר לוֹ זוֹנוֹת. וְרַבּוֹתֵינוּ אָמְרוּ (עירובין סד.): הָאוֹמֵר שְׁמוּעָה זוֹ נָאָה – אֶשְׁנֶנָּה, וְזוֹ אֵינָהּ נָאָה – לֹא אֶשְׁנֶנָּה. וְסִיּוּעַ בַּמִּקְרָא, שֶׁאֵין ״זוֹנוֹת״ בַּמִּקְרָא מָלֵא אֶלָּא זֶה בִּלְבַד:\",1,0],[2,135,29,4,\"יַעֲמִיד אָרֶץ. אִם שׁוֹפֵט אֱמֶת הוּא, יַעֲמִיד אָרֶץ:\",1,0],[2,135,29,4,\"וְאִישׁ תְּרוּמוֹת. אִישׁ גֵאוּת, שֶׁאֵינוֹ חָשׁ לִהְיוֹת מָתוּן בַּדִּין. וְרַבּוֹתֵינוּ אָמְרוּ (כתובות קה:): אִם הַדַּיָּן דּוֹמֶה לְמִי שֶׁאֵינוֹ צָרִיךְ לִקְנוֹת אוֹהֲבִים וְלִיקַּח שֹׁחַד, הוּא יַעֲמִיד אָרֶץ, וְאִם דּוֹמֶה לְכֹהֵן הַשּׁוֹאֵל תְּרוּמוֹת עַל הַגְּרָנוֹת, הוּא יֶהֶרְסֶנָּה:\",2,0],[2,135,29,5,\"מַחֲלִיק. מְדַבֵּר חֲלָקוֹת:\",1,0],[2,135,29,6,\"בְּפֶשַׁע אִישׁ רָע. יָבֹא מוֹקֵשׁ:\",1,0],[2,135,29,6,\"וְצַדִּיק. שֶׁלֹּא הָלַךְ בִּדְרָכָיו, יָרוּן וְשָׂמֵחַ:\",2,0],[2,135,29,7,\"דִּין דַּלִּים. יִסּוּרֵי דַלִּים וּמַה הֵם צְרִיכִים, וְנוֹתֵן לָהֶם לֵב:\",1,0],[2,135,29,8,\"יָפִיחוּ. יַלְהִיבוּ, כְּלַהֶבֶת אֵשׁ הַנָּפוּחַ בָּרוּחַ:\",1,0],[2,135,29,9,\"אִישׁ חָכָם נִשְׁפָּט. מִתְוַכֵּחַ עִם הָאֱוִיל:\",1,0],[2,135,29,9,\"וְאֵין נָחַת. בֵּין מַרְאֶה לוֹ פָּנִים זְעוּפוֹת בֵּין שֶׁמַּרְאֵהוּ פָּנִים שׂוֹחֲקוֹת, אֵין נַחַת לֹא בָזוֹ וְלֹא בָזוֹ, אֵינוֹ מוֹצֵא קוֹרַת רוּחַ. מָצִינוּ בַאֲמַצְיָה, שֶׁהֶרְאָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא פָּנִים שׂוֹחֲקוֹת וּמָסַר בְּיָדוֹ אֱדוֹם, וּבְשׁוּבוֹ מֵהַכּוֹת (דברי הימים ב כה:יד) וַיָּבֵא אֶת אֱלֹהֵיהֶם וְלָהֶם הִשְׁתַּחֲוָה. לְאָחָז הֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא פָּנִים זוֹעֲפוֹת וּמְסָרוֹ בְּיַד מַלְכֵי אֲרָם, וַיִּזְבַּח לֵאלֹהֵי דַמֶּשֶׂק כִּי אָמַר אֱלֹהֵי אֲרָם מְעַזְּרִים לָהֶם (דברי הימים ב כח:כג):\",2,0],[2,135,29,10,\"יְבַקְשׁוּ נַפְשׁוֹ. לְשׁוֹן חִבָּה, וְנִרְאֶה שֶׁכֵּן הוּא, כְּמָה שֶׁאָמַר דָּוִד לְאֶבְיָתָר: ״אֲשֶׁר יְבַקֵּשׁ אֶת נַפְשִׁי יְבַקֵּשׁ אֶת נַפְשֶׁךָ״ (שמואל א כב:כג) – מִי שֶׁיִּגְמֹל לִי חֶסֶד יִגְמֹל לְךָ. וְאֵין הַפּוֹתְרִים מוֹדִים לִי:\",1,0],[2,135,29,11,\"בְּאָחוֹר יְשַׁבְּחֶנָּה. כְּשֶׁיּוֹצִיא הַכְּסִיל כָּל רוּחוֹ, בָּא הֶחָכָם וְיַשְׁפִּילֶנּוּ בְּמַעֲנֵה לְשׁוֹנוֹ. וְדוֹמֶה לוֹ ״מַשְׁבִּיחַ שְׁאוֹן יַמִּים״ (תהלים סה:ח); ״בְּשׂוֹא גַלָּיו אַתָּה תְשַׁבְּחֵם״ (תהלים פט:י):\",1,0],[2,135,29,13,\"וְאִישׁ תְּכָכִים. אִישׁ מְזִמּוֹת, בַּעַל תּוֹרָה. וְרַבּוֹתֵינוּ (תמורה טז.; ויקרא רבה לד,ד) פֵּרְשׁוּ: תַּלְמִיד שֶׁאָמַר לָרַב הַשְׁנֵינִי פֶּרֶק אֶחָד, וּמְלַמְּדוֹ:\",1,0],[2,135,29,15,\"וְנַעַר מְשֻׁלָּח. שֶׁשְּׁלָחוֹ אָבִיו לָלֶכֶת בְּדַרְכֵי לִבּוֹ, סוֹפוֹ מֵבִישׁ אִמּוֹ. יִשְׁמָעֵאל, עַל שֶׁהָיָה רָשָׁע, גָּרַם לְשָׂרָה שֶׁאָמְרָה לְאַבְרָהָם ״גָּרֵשׁ אֶת הָאָמָה וְגוֹמֵר״ (בראשית כא:י):\",1,0],[2,135,29,18,\"בְּאֵין חָזוֹן יִפָּרַע עָם. כְּשֶׁגּוֹרְמִין יִשְׂרָאֵל שֶׁהַנְּבוּאָה מִסְתַּלֶּקֶת מֵהֶם, עַל יְדֵי שֶׁהֵם מַלְעִיבִים בַּנְּבִיאִים (דברי הימים ב לו:טז), יִפְרְצוּ בָם פְּרָצוֹת וְיוֹצְאִין לְתַרְבּוּת רָעָה:\",1,0],[2,135,29,19,\"כִּי יָבִין וְאֵין מַעֲנֶה. כֵּיוָן שֶׁרוֹאֵהוּ שֶׁמּוֹכִיחוֹ, שׁוֹתֵק, וְהוּא חוֹזֵר וּמְקַלְקֵל; לְכָךְ צָרִיךְ לְיַסְּרוֹ בְּמַכּוֹת וְעוֹנְשִׁין. וְלֹא דִּבֵּר עַל עֶבֶד מַמָּשׁ, אֶלָּא עַל כָּל הַמַּמְרִים דִּבְרֵי הַשּׁוֹפְטִים:\",1,0],[2,135,29,20,\"אָץ בִּדְבָרָיו. מְמַהֵר וְנִבְהָל לְהָשִׁיב:\",1,0],[2,135,29,20,\"תִּקְוָה לִכְסִיל מִמֶּנּוּ. יֵשׁ לַכְּסִיל תִּקְוָה יוֹתֵר מִמֶּנּוּ:\",2,0],[2,135,29,21,\"מְפַנֵּק מִנֹּעַר עַבְדּוֹ. יֵצֶר הָרָע:\",1,0],[2,135,29,21,\"מָנוֹן. שַׁלִּיט, וְכֵן ״לִפְנֵי שֶׁמֶשׁ יִנּוֹן שְׁמוֹ״ (תהלים עב:יז); וְכֵן כָּל ׳נִין׳ שֶׁבַּמִּקְרָא, שֶׁהַנִּין קָם תַּחַת אָבִיו לִשְׁלוֹט בִּנְכָסָיו:\",2,0],[2,135,29,22,\"אִישׁ אַף יְגָרֶה מָדוֹן. כְּמַשְׁמָעוֹ. מָדוֹן מִדַּת הַדִּין:\",1,0],[2,135,29,23,\"יִתְמֹךְ כָּבוֹד. יִקְרַב אֶל הַכָּבוֹד וְתוֹמֵךְ בּוֹ תָּמִיד:\",1,0],[2,135,29,24,\"אָלָה יִשְׁמַע. שֶׁמַּשְׁבִּיעִין אוֹתוֹ: אִם רָאִיתָ פְּלוֹנִי שֶׁגָּנַב לִי כָּךְ וְכָךְ; וּמִתּוֹךְ שֶׁהוּא חוֹלֵק עִמּוֹ, אֵינוֹ מַגִּיד:\",1,0],[2,135,29,25,\"חֶרְדַּת אָדָם יִתֵּן מוֹקֵשׁ. מְסֹרָס הוּא: מוֹקֵשׁ, עֲבֵרָה, יִתֵּן חֲרָדָה לָאָדָם. דָּבָר אַחֵר: כְּמַשְׁמָעוֹ: מִתּוֹךְ שֶׁאָדָם צַר עַיִן, וְחָרֵד, אִם יַעֲשֶׂה צְדָקָה, יִצְטָרֵךְ אֶל הַבְּרִיּוֹת; חֲרָדָה זוֹ תִּתֵּן לוֹ מוֹקֵשׁ. וְהָרִאשׁוֹן נוֹחַ לִי:\",1,0],[2,135,29,26,\"פְּנֵי מוֹשֵׁל. לָדוּן לְפָנָיו:\",1,0],[2,135,29,26,\"וּמֵה׳ מִשְׁפַּט אִישׁ. אִם יִזְכֶּה אוֹ אִם יִתְחַיֵּב. וּבַמּוֹשְׁלִים דִּבֵּר הַכָּתוּב:\",2,0],[2,135,29,27,\"יְשַׁר דָּרֶךְ. אָדָם שֶׁהוּא יָשָׁר בִּדְרָכָיו:\",1,0],[2,135,30,1,\"אָגוּר בֶּן יָקֶה. דִּבְרֵי שְׁלֹמֹה שֶׁאָגַר אֶת הַבִּינָה וְהֵקִיאָהּ, כָּךְ פֵּרְשׁוּהוּ חֲכָמִים (תנחומא, וארא ה):\",1,0],[2,135,30,1,\"הַמַּשָּׂא. נְבוּאָה זוֹ אָמַר עַל כֵּן:\",2,0],[2,135,30,1,\"נְאֻם הַגֶּבֶר לְאִיתִיאֵל. אָמַר הַגֶּבֶר, זֶה שְׁלֹמֹה, הַמַּשָּׂא הַזֶּה עַל עַצְמוֹ, בִּשְׁבִיל אִיתִיאֵל – עַל שֶׁסָּמַךְ עַל חָכְמָתוֹ לְהַרְבּוֹת זָהָב וְסוּסִים וְנָשִׁים שֶׁהוּזְהַר מִלְּהַרְבּוֹת. וְכֵן אָמַר: אִיתִיאֵל וְאֻכָל, אַרְבֶּה נָשִׁים וְלֹא יָסוּרוּ אֶת לְבָבִי, אַרְבֶּה זָהָב וְלֹא אָסוּר, אַרְבֶּה סוּסִים וְלֹא אָשׁוּב אֶת הָעָם מִצְרַיְמָה (דברים יז:טז-יז):\",3,0],[2,135,30,1,\"לְאִיתִיאֵל וְאֻכָל. בִּשְׁבִיל שֶׁאָמַר: אִתִּי אֵל, וְאוּכַל לַעֲשׂוֹת וְלֹא אֶכָּשֵׁל. לְאִיתִיאֵל, עַל אִיתִיאֵל, כְּמוֹ ״וְאָמַר פַּרְעֹה לִבְנֵי יִשְׂרָאֵל״ (שמות יד:ג) – עַל בְּנֵי יִשְׂרָאֵל:\",4,0],[2,135,30,2,\"כִּי בַעַר אָנֹכִי. עַל שֶׁסָּמַכְתִּי עַל חָכְמָתִי בְּדָבָר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא דָּאַג, שֶׁמָּא יָבוֹא לִידֵי עֲבֵירָה:\",1,0],[2,135,30,3,\"וְלֹא לָמַדְתִּי חָכְמָה. וְלֹא דַעַת קְדוֹשִׁים יָדַעְתִּי, שֶׁגָּרַעְתִּי אוֹ הוֹסַפְתִּי עַל דִּבְרֵי מֹשֶׁה:\",1,0],[2,135,30,4,\"מִי עָלָה שָׁמַיִם. כְּמֹשֶׁה (שמות יט:ג):\",1,0],[2,135,30,4,\"מִי אָסַף רוּחַ. פִּיחַ הַכִּבְשָׁן (שמות ט:י):\",2,0],[2,135,30,4,\"מִי צָרַר מַיִם. ״קָפְאוּ תְהוֹמוֹת, נִצְּבוּ כְמוֹ נֵד״ (שמות טו:ח) בִּתְפִלָּתוֹ שֶׁל מֹשֶׁה:\",3,0],[2,135,30,4,\"מִי הֵקִים. אֶת הַמִּשְׁכָּן, שֶׁבַּהֲקָמָתוֹ נִתְבַּסְּסוּ כָּל אַפְסֵי אָרֶץ. כָּךְ נִדְרַשׁ בַּפְּסִיקְתָּא (פסיקתא רבתי א,ד):\",4,0],[2,135,30,4,\"מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ. אִם תֹּאמַר: כְּבָר הָיָה דֻּגְמָתוֹ, אֱמוֹר: מַה שֵּׁם בְּנוֹ? אֵיזוֹ מִשְׁפָּחָה יָצְאָה מִמֶּנּוּ, וְנֵדַע מִי הוּא?\",5,0],[2,135,30,4,\"כִּי תֵדָע. אִם תֵּדַע מִי הוּא, וְאֵיךְ לֹא יָרֵאתָ לַעֲבֹר עַל דְּבָרָיו?\",6,0],[2,135,30,5,\"כָּל אִמְרַת אֱלוֹהַּ צְרוּפָה. מְזֻקָּקָה, וְלֹא כָתַב דָּבָר שֶׁלֹּא לְצֹרֶךְ, וְהָיָה לִי לִיזָּהֵר:\",1,0],[2,135,30,6,\"פֶּן יוֹכִיחַ בְּךָ וְנִכְזָבְתָּ. יוֹכִיחַ עַל פָּנֶיךָ, שֶׁעַל יְדֵי תוֹסַפְתְּךָ אַתָּה בָּא לִידֵי עֲבֵירָה, וְכָל שֶׁכֵּן אִם תִּגְרַע:\",1,0],[2,135,30,7,\"שְׁתַּיִם שָׁאַלְתִּי מֵאִתָּךְ. עַכְשָׁיו מְדַבֵּר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,135,30,8,\"רֵאשׁ. דַּלּוּת:\",1,0],[2,135,30,8,\"הַטְרִיפֵנִי. לְשׁוֹן מָזוֹן, וְכֵן ״טֶרֶף נָתַן לִירֵאָיו״ (תהלים קיא:ה):\",2,0],[2,135,30,9,\"פֶּן אֶשְׂבַּע. מִתּוֹךְ עֹשֶׁר, וְכִחַשְׁתִּי בַּהַקָּדוֹשׁ בָּרוּךְ הוּא מֵרוֹב גַּאֲוָה. וּמַהוּ הַכְּחָשָׁה?\",1,0],[2,135,30,9,\"וְאָמַרְתִּי מִי ה׳. כְּלוֹמַר: אֵין אֱלֹהִים:\",2,0],[2,135,30,9,\"וְתָפַשְׂתִּי שֵׁם אֱלֹהָי. לְהַרְגִּיל לְהִשָּׁבַע בּוֹ לַשֶּׁקֶר:\",3,0],[2,135,30,10,\"אַל תַּלְשֵׁן עֶבֶד. אַל תִּמְסֹר דִּין עַל אָדָם לִצְעֹק עָלָיו לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וַאֲפִלּוּ הוּא רָשָׁע אֲשֶׁר אָבִיו יְקַלֵּל, וְכָל הַתּוֹעֵבוֹת הָאֲמוּרוֹת כָּאן בּוֹ. וּרְאָיָה לַדָּבָר מֵהוֹשֵׁעַ בֶּן בְּאֵרִי, כִּדְאִיתָא בִּפְסָחִים בְּפֶרֶק ׳הָאִשָּׁה׳ (פסחים פז.), שֶׁהִלְשִׁין אֶת יִשְׂרָאֵל וְאָמַר: הַחֲלִיפֵם בְּאֻמָּה אַחֶרֶת! אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: ״קַח לְךָ אֵשֶׁת זְנוּנִים״ (הושע א:ב):\",1,0],[2,135,30,13,\"דּוֹר מָה רָמוּ עֵינָיו. זֶה גַּסּוּת הָרוּחַ:\",1,0],[2,135,30,14,\"דּוֹר חֲרָבוֹת שִׁנָּיו. הַחִיצוֹנוֹת:\",1,0],[2,135,30,14,\"מְתַלְּעֹתָיו. שִׁנָּיו הַפְּנִימִיּוֹת:\",2,0],[2,135,30,14,\"וּמַאֲכָלוֹת. סַכִּינִים:\",3,0],[2,135,30,15,\"לַעֲלוּקָה. מְנַחֵם פָּתַר לַעֲלוּקָה כְּמַשְׁמָעוֹ, לָמַדְנוּ שֶׁהוּא עֲרָבִי. וְהַפּוֹתְרִים אוֹמְרִים שֶׁהוּא לְשׁוֹן שְׁאוֹל וּמוֹרָד. וְכֵן בְּמִדְרַשׁ תְּהִלִּים לָמַדְנוּ כֵּן, שֶׁפּוֹתֵר שְׁתֵּי בָנוֹת – גַּן עֵדֶן וְגֵיהִנֹּם; זוֹ אוֹמֶרֶת: תְּנוּ לִי צַדִּיקִים, וְזוֹ אוֹמֶרֶת: תְּנוּ לִי רְשָׁעִים:\",1,0],[2,135,30,15,\"אַרְבַּע לֹא אָמְרוּ הוֹן. הַרְבֵּה יֵשׁ לָנוּ:\",2,0],[2,135,30,16,\"וְעֹצֶר רָחַם. תַּשְׁמִישׁ:\",1,0],[2,135,30,17,\"לִיקְּהַת אֵם. לִקְמָטִים הַנִּקְבָּצִים וְנִקְהִין בִּפְנֵי אִמּוֹ, לְשׁוֹן ״יִקְּהַת עַמִּים״ (בראשית מט:י) – קְבוּצַת עַמִּים. וְהַיּוֹ״ד יְסוֹד, כְּמוֹ ״יִפְעַת״ (יחזקאל כח:ז), ״וְיַעֲלַת חֵן״ (משלי ה:יט):\",1,0],[2,135,30,17,\"יִקְּרוּהָ. לְשׁוֹן ״תְּנַקֵּר״ (במדבר טז:יד), ״נִקְרַת הַצּוּר״ (שמות לג:כב), פוריי״ר בְּלַעַ״ז. יָבֹא הָעוֹרֵב שֶׁהוּא אַכְזָרִי עַל בָּנָיו, וְיִקְּרוּהָ, וְלֹא יֹאכְלֶנָּה וְלֹא יֵהָנֶה בָּהּ, וְיָבֹא נֶשֶׁר שֶׁהוּא רַחֲמָנִי עַל בָּנָיו וְיֹאכְלוּהָ וְיֵהָנֶה בָּהּ. הָעוֹרֵב אַכְזָרִי הוּא, כְּמוֹ שֶׁנֶּאֱמַר ״לִבְנֵי עֹרֵב אֲשֶׁר יִקְרָאוּ״ (תהלים קמז:ט), וְהַנֶּשֶׁר רַחֲמָנִי, שֶׁנֶּאֱמַר ״יִשָּׂאֵהוּ עַל אֶבְרָתוֹ״ (דברים לב:יא; ראה תנחומא עקב ב):\",2,0],[2,135,30,18,\"נִפְלְאוּ מִמֶּנִּי. נִכְסוּ מִשֶּׁחָלְפוּ מֵעֵינַי, וְאֵינִי יוֹדֵעַ לְהֵיכָן הָלְכוּ, שֶׁמְּמַהֲרִין לְהִסָּתֵר מִן הָעַיִן:\",1,0],[2,135,30,20,\"וּמָחֲתָה. כּוֹפָה פִּיהָ לְמַטָּה, כְּדִכְתִיב ״כַּאֲשֶׁר יִמְחֶה הַצַּלַּחַת מָחָה וְהָפַךְ עַל פָּנֶיהָ״ (מלכים ב כא:יג):\",1,0],[2,135,30,20,\"אָכְלָה. לָשׁוֹן נְקִיָּה דִּבֵּר הַכָּתוּב (יומא עה.):\",2,0],[2,135,30,28,\"שְׂמָמִית. אַרִינְיָ״א בְּלַעַ״ז:\",1,0],[2,135,30,28,\"בְּיָדַיִם תְּתַפֵּשׂ. בְּיָדָהּ הִיא אוֹחֶזֶת וּמִתְדַּבֶּקֶת בַּכְּתָלִים (בראשית רבה סו,ז):\",2,0],[2,135,30,29,\"מְטִיבֵי צָעַד. הוֹלְכִים וּמַצְלִיחִים בִּגְבוּרָתָם:\",1,0],[2,135,30,31,\"זַרְזִיר מָתְנַיִם אוֹ תָיִשׁ. לֹא יָדַעְתִּי מַהוּ, וּלְפִי הַמַּשְׁמָע הִיא חַיָּה תְּשׁוּשָׁה מָתְנַיִם:\",1,0],[2,135,30,31,\"וּמֶלֶךְ אַלְקוּם. לֹא יָדַעְתִּי מַה הוּא לְפִי פְּשׁוּטוֹ. וּמִדְרַשׁ אַגָּדָה פּוֹתְרִין חָמֵשׁ פָּרָשִׁיּוֹת אֵלּוּ שֶׁל אַרְבַּע דְּבָרִים כְּנֶגֶד אַרְבַּע מַלְכֻיּוֹת, לְפִי שֶׁנִּתְאַמְּצָה מֶמְשַׁלְתָּן עַל יִשְׂרָאֵל בְּעָוֹן שֶׁעָבְרוּ עַל חֲמִשָּׁה חוּמְשֵׁי תּוֹרָה, הִזְכִּירָם חֲמִשָּׁה פְּעָמִים:\",2,0],[2,135,30,31,\"(טז) שְׁאוֹל וְעֹצֶר רָחַם. שְׁאוֹל מַלְכוּת בָּבֶל, שֶׁנֶּאֱמַר בִּנְבוּכַדְנֶצַּר ״הִרְחִיב כַּשְּׁאוֹל נַפְשׁוֹ״ (חבקוק ב:ה). וְעֹצֶר רָחַם זוֹ הִיא מָדַי שֶׁבִּימֵיהֶם עָצְרוּ רַחֲמִים מִיִּשְׂרָאֵל, שֶׁנֶּאֱמַר ״לְהַשְׁמִיד לַהֲרֹג וּלְאַבֵּד״ (אסתר ג:יג):\",3,0],[2,135,30,31,\"אֶרֶץ לֹא שָׂבְעָה מַּיִם. זוֹ יָוָן, שֶׁלֹּא שָׂבְעָה מִלִּגְזֹר גְּזֵרוֹת רָעוֹת עַל יִשְׂרָאֵל:\",4,0],[2,135,30,31,\"וְאֵשׁ לֹא אָמְרָה הוֹן. נֶגֶד עֵשָׂו, שֶׁעָשָׂה בְּחֵמָה בּוֹעֶרֶת עַל יִשְׂרָאֵל, שֶׁאָמְרוּ לְהַשְׁמִיד טַף וְנָשִׁים בְּיוֹם אֶחָד (אסתר ג:יג). וְכֵן:\",5,0],[2,135,30,31,\"(יט) דֶּרֶךְ הַנֶּשֶׁר. זוֹ בָּבֶל, ״הַנֶּשֶׁר הַגָּדוֹל… אֶרֶךְ הָאֵבֶר״ (יחזקאל יז:ג):\",6,0],[2,135,30,31,\"נָחָשׁ. זוֹ מָדַי (דניאל ח:כ):\",7,0],[2,135,30,31,\"דֶּרֶךְ אֳנִיָּה בְלֶב יָם. זוֹ יָוָן, שֶׁהִיא קַלָּה בִּגְזֵרוֹתֶיהָ (משלי ל:יט):\",8,0],[2,135,30,31,\"דֶּרֶךְ גֶּבֶר בְּעַלְמָה. זוֹ פָּרַס שֶׁאָמְרָה: ״לְעוֹלָם אֶהְיֶה גְבֶרֶת״ (ישעיהו מז:ז):\",9,0],[2,135,30,31,\"(כ) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת. זוֹ הָרָעָה גָּרְמָה לָהֶם לִכְנֶסֶת יִשְׂרָאֵל שֶׁנָּאֲפָה בַּעֲבוֹדַת גִּלּוּלִים, וּכְדַאי הוּא הַפּוּרְעָנִיּוֹת לָבוֹא לָהּ:\",10,0],[2,135,30,31,\"וְאָמְרָה לֹא פָעַלְתִּי אָוֶן. כְּדַאֲמַר ״הִנְנִי נִשְׁפָּט אוֹתָךְ עַל אָמְרֵךְ לֹא חָטָאתִי״ (ירמיה ב:לה). [עד כאן לשוֹן רש״י שבמק״ג]:\",11,0],[2,135,30,31,\"(כא) רָגְזָה אֶרֶץ. אֶרֶץ יִשְׂרָאֵל:\",12,0],[2,135,30,31,\"(כב) תַּחַת עֶבֶד. זֶה נְבוּכַדְנֶצַּר שֶׁהָיָה עֶבֶד לִמְרוֹדַךְ בַּלְאֲדָן וְכוֹתֵב אִגְּרוֹתָיו, כְּדִגְרָסִינַן בְּחוּלִין (סנהדרין צו.):\",13,0],[2,135,30,31,\"וְנָבָל כִּי יִשְׂבַּע לָחֶם. זֶה אֲחַשְׁוֵרוֹשׁ שֶׁעָשָׂה מִשְׁתֶּה מֵאָה וּשְׁמוֹנִים יוֹם (אסתר א:ד):\",14,0],[2,135,30,31,\"(כג) שְׂנוּאָה כִּי תִבָּעֵל. כְּנֶגֶד יָוָן:\",15,0],[2,135,30,31,\"וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. זֶה עֵשָׂו, שֶׁהָיָה לוֹ לַעֲבֹד לְיַעֲקֹב וְנֶהְפַּךְ הַדְּבָרִים:\",16,0],[2,135,30,31,\"(כה) הַנְּמָלִים עַם לֹא עָז. זוֹ בָּבֶל, שֶׁנֶּאֱמַר: ״הֵן אֶרֶץ כַּשְׂדִּים זֶה הָעָם לֹא הָיָה״ (ישעיהו כג:יג):\",17,0],[2,135,30,31,\"וַיָּכִינוּ בַקַּיִץ לַחְמָם. נְבוּכַדְנֶצַּר עָשָׂה כָבוֹד אֶחָד לְהַקָּדוֹשׁ בָּרוּךְ הוּא בִּימֵי מְרֹדַךְ בַּלְאֲדָן אֲשֶׁר שָׁלַח סְפָרִים לְחִזְקִיָּהוּ וְכָתַב שָׁם: שְׁלָם לְמַלְכָּא חִזְקִיָּהוּ, שְׁלָם לְקַרְתָּא דִירוּשְׁלֵם, שְׁלָם לֶאֱלָהָא רַבָּא. וּנְבוּכַדְנֶצַּר כּוֹתֵב אִגְּרוֹתָיו הָיָה, וְלֹא הָיָה שָׁם אוֹתוֹ הַיּוֹם; וּכְשֶׁבָּא וְסִפְּרוּ לוֹ מַה שֶּׁעָשׂוּ, אָמַר לָהֶם: אֱלָהָא רַבָּא קְרִיתוּ לֵיהּ וּכְתַבִיתוּ לֵיהּ בְּסוֹף? רָץ אַחַר הַשָּׁלִיחַ וְהֶחֱזִירוֹ. בִּשְׁבִיל אוֹתוֹ מְרוּצָה זָכָה לַמַּלְכוּת; הֲרֵי שֶׁהֵכִין בַּקַּיִץ לַחְמוֹ כְּדֶרֶךְ הַנְּמָלָה (סנהדרין צו.):\",18,0],[2,135,30,31,\"(כו) שְׁפַנִּים עַם לֹא־עָצוּם. זֶה מָדַי וּפָרָס:\",19,0],[2,135,30,31,\"וַיָּשִׂימוּ בַסֶּלַע בֵּיתָם: שֶׁבָּנוּ בֵּית הַמִּקְדָּשׁ:\",20,0],[2,135,30,31,\"(כח) שַׁמָּמִית בְּיָדַיִם תְּתַפֵּשׂ. זֶה עֵשָׂו שֶׁנֶּאֱמַר ״וְהַיָּדַיִם יְדֵי עֵשָׂו״ (בראשית כז:כב):\",21,0],[2,135,30,31,\"בְּהֵיכְלֵי מֶלֶךְ. שֶׁנִּכְנַס לְהֵיכַל מֶלֶךְ וְהֶחֱרִיבוֹ:\",22,0],[2,135,30,31,\"(ל) לַיִשׁ גִּבּוֹר בַּבְּהֵמָה. זֶה נְבוּכַדְנֶצַּר, שֶׁנֶּאֱמַר (ירמיהו ד:ז) ״עָלָה אַרְיֵה מִסֻּבְּכוֹ״:\",23,0],[2,135,30,31,\"זַרְזִיר מָתְנַיִם. זוֹ מָדַי וּפָרַס, שֶׁזֵּרְזוּ מָתְנֵיהֶם וְהָרְגוּ לְבֵלְשַׁצַּר וְנָטְלוּ מַלְכוּת בָּבֶל (דניאל ה:ל):\",24,0],[2,135,30,31,\"אוֹ תָיִשׁ. זֶה יָוָן שֶׁנִּקְרָא תַּיִשׁ, שֶׁנֶּאֱמַר: ״וְהַצָּפִיר הַשָּׂעִיר״ הוּא ״מֶלֶךְ יָוָן״ (דניאל ח:כא):\",25,0],[2,135,30,31,\"וּמֶלֶךְ אַלְקוּם עִמּוֹ. זוֹ אֻמַּת אֲרָם, שֶׁאָמַר ״אֲנִי וְאַפְסִי עוֹד״ (ישעיה מז:ח), אֵין נִצָּב לְעֻמָּתוֹ, אַלְקוּם – אֵין עוֹמֵד עִמּוֹ:\",26,0],[2,135,30,32,\"אִם נָבַלְתָּ בְהִתְנַשֵּׂא. אִם נִתְנַבַּלְתָּ עַל יְדֵי חֲבֵירְךָ שֶׁחֵירְפְךָ (  עַל יְדֵי דַּבּוּרְךָ שֶׁחֵרַפְתָּ וְגִדַּפְתָּ) אֶת עַצְמְךָ, סוֹפְךָ לְהִנָּשֵׂא בַּדָּבָר:\",1,0],[2,135,30,32,\"וְאִם זַמּוֹתָ. בְּלִבְּךָ לְהִתְקוֹטֵט, שִׂים יָד עַל פֶּה וּשְׁתוֹק:\",2,0],[2,135,30,33,\"כִּי מִיץ חָלָב. כִּי כַּאֲשֶׁר תֵּצֵא חֶמְאָה עַל יְדֵי מִיץ חָלָב וְדָם עַל יְדֵי מִיץ הַחוֹטֶם יוֹתֵר מִדַּי, כֵּן יֵצֵא רִיב עַל יְדֵי מִיץ אַפַּיִם שֶׁל כַּעַס. מִיץ סְחִיטָה פרימדור״א בְּלַעַ״ז, כְּמוֹ ״וַיִּמֶץ טַל וְגוֹ׳״ (שופטים ו:לח). וְרַבּוֹתֵינוּ פֵּרְשׁוּ (ברכות סג:): אִם נִבַּלְתָּ עַצְמְךָ עַל דִּבְרֵי תוֹרָה, לִדְרוֹשׁ וְלִשְׁאוֹל סְפֵקוֹתֶיךָ לְרַבְּךָ, וַאֲפִלּוּ נִרְאֵיתָ לוֹ כְּשׁוֹטֶה בְּלֹא לֵב, סוֹפְךָ שֶׁתְּהֵא מְנֻשָּׂא; וְאִם זַמּוֹתָ – אִם שַׂמְתָּ זְמָם עַל פִּיךָ וְחָסַמְתָּ אוֹתוֹ וְלֹא שָׁאַלְתָּ לוֹ הַכֹּל, סוֹפְךָ כְּשֶׁיִּשְׁאָלְךָ דְּבַר הֲלָכָה, תִּתֵּן יָד לַפֶּה וְתֵאָלֵם, שֶׁלֹּא תֵדַע לַעֲנוֹת כְּלוּם בּוֹ. כַּאֲשֶׁר מִיץ חָלָב יוֹצִיא חֶמְאָה, כֵּן מִיץ אַפַּיִם. שֶׁרַבְּךָ כּוֹעֵס בְּךָ שֶׁלֹּא הֲבִינוֹתָ מַהֵר, וְאַתָּה מִתְנַבֵּל עָלֶיהָ – סוֹף יוֹצִיא מִפִּיךָ אַחַר זְמַן הֲלָכוֹת רַבּוֹת וְהוֹרָאוֹת:\",1,0],[2,135,31,1,\"דִּבְרֵי לְמוּאֵל מֶלֶךְ. דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ שֶׁאָמַר לְמוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּלוֹמַר: בִּשְׁבִיל שֶׁהֶעֱוָה כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא. לְמוּאֵל לָאֵל, כְּמוֹ ״לְמוֹ פִי״ (איוב מ:ד). דְּבָרִים לִשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאָמַר הַמֶּלֶךְ:\",1,0],[2,135,31,1,\"מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ. כְּשֶׁהִתְחַתֵּן עִם בַּת פַּרְעֹה בְּיוֹם חֲנֻכַּת בֵּית הַמִּקְדָּשׁ, וְהִכְנִיסָה לוֹ כַּמָּה מִינֵי כְּלֵי זֶמֶר, וְנֵעוֹר כָּל הַלַּיְלָה, וְיָשַׁן לְמָחֳרָת עַד אַרְבַּע שָׁעוֹת; כִּדְאִיתָא בִּפְסִיקְתָּא (ויקרא רבה יב, ה), וְהָיוּ מַפְתְּחוֹת בֵּית הַמִּקְדָּשׁ תַּחַת מְרַאֲשׁוֹתָיו. וְעַל אוֹתָהּ שָׁעָה שָׁנִינוּ (עדיות ו, א): עַל תָּמִיד שֶׁל שַׁחַר שֶׁקָּרַב בְּאַרְבַּע שָׁעוֹת, וְנִכְנְסָה אִמּוֹ וְהוֹכִיחַתּוּ עַל הַמַּעֲשֶׂה הַזֶּה:\",2,0],[2,135,31,1,\"מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ. מַשָּׂא שֶׁל מָשָׁל שֶׁיִּסְּרַתּוּ אִמּוֹ (סנהדרין ע:):\",3,0],[2,135,31,2,\"מַה בְּרִי. מֶה זֹּאת עָשִׂיתָ, וְהִגַּדְתָּ שֶׁאַתָּה בְּנִי וְלֹא בֶן אָבִיךָ? הַכֹּל יוֹדְעִין שֶׁאָבִיךָ צַדִּיק גָּמוּר הָיָה, וְאִם אַתָּה רָשָׁע, יֹאמְרוּ: אִמּוֹ גָּרְמָה לוֹ:\",1,0],[2,135,31,2,\"בַּר בִּטְנִי. כָּל נְשֵׁי אָבִיךָ, כֵּיוָן שֶׁמִּתְעַבְּרוֹת אֵינָן שָׁבוֹת לְתַשְׁמִישׁ; וַאֲנִי דָּחַקְתִּי וְנִכְנַסְתִּי כְּדֵי שֶׁיְּהֵא לִי בֵּן מְלֻבָּן וּמְזֹרָז, שֶׁהַתַּשְׁמִישׁ יָפֶה כָּל שִׁשָּׁה חֳדָשִׁים אַחֲרוֹנִים:\",2,0],[2,135,31,2,\"וּמֶה בַּר נְדָרָי. כָּל נְשֵׁי אָבִיךָ הָיוּ נוֹדְרוֹת שֶׁיְּהֵא לָהֶן בֵּן הָגוּן לַמַּלְכוּת, וַאֲנִי נָדַרְתִּי שֶׁיְּהֵא לִי בֵּן מְלֻבָּן בַּתּוֹרָה:\",3,0],[2,135,31,3,\"אַל תִּתֵּן. אַל תַּתִּישׁ:\",1,0],[2,135,31,3,\"לַנָּשִׁים חֵילֶךָ. כֹּחֲךָ:\",2,0],[2,135,31,4,\"אַל לַמְּלָכִים לְמוֹאֵל. אֵין זֶה דָּבָר הָגוּן לַמְּלָכִים, שֶׁהֵם לְהַקָּדוֹשׁ בָּרוּךְ הוּא. לְמוֹאֵל כְּמוֹ ״לְמוֹ פִי״ (איוב מ:ד):\",1,0],[2,135,31,4,\"אַל לַמְּלָכִים שְׁתוֹ יָיִן. אֵין נָאֶה לָהֶם לְהִשְׁתַּכֵּר:\",2,0],[2,135,31,4,\"אֵי שֵׁכָר. כְּמוֹ אֵין שֵׁכָר:\",3,0],[2,135,31,5,\"מְחֻקָּק. הַכָּתוּב בַּתּוֹרָה, וְכָל שֶׁכֵּן מַה שֶּׁהוּא בְּגִרְסָא:\",1,0],[2,135,31,6,\"לְאוֹבֵד. לְמִי שֶׁסּוֹפוֹ לְאִבּוּד, לָרְשָׁעִים (עירובין סה.):\",1,0],[2,135,31,6,\"לְמָרֵי נָפֶשׁ. הַמִּצְטַעֲרִין עַל עָנְיָם וְעַל אֶבְלָם (במדבר רבה י:ד):\",2,0],[2,135,31,8,\"כָּל בְּנֵי חֲלוֹף. אֵלּוּ הֵן הַיְתוֹמִים, שֶׁחָלְפָה עֶזְרָתָם וְהָלְכָה לָהּ:\",1,0],[2,135,31,11,\"וְשָׁלָל לֹא יֶחְסָר. כְּלוֹמַר: לֹא יֶחְסַר טוֹב:\",1,0],[2,135,31,15,\"טֶרֶף. מָזוֹן:\",1,0],[2,135,31,15,\"וְחֹק. הוּא מָזוֹן הַקָּצוּב לָהֶם:\",2,0],[2,135,31,19,\"בַּכִּישׁוֹר. שֶׁקּוֹרִין וִוירְטוֹי״ל בְּלַעַ״ז, הַמַּכְשִׁיר אֶת הַפֶּלֶךְ לִטְווֹת. פָלֶךְ פּוּשִׁי״ל בְּלַעַ״ז:\",1,0],[2,135,31,21,\"לֹא תִירָא לְבֵיתָהּ. לִבְנֵי בֵיתָהּ:\",1,0],[2,135,31,21,\"מִשָּׁלֶג. מִצִּנָּה:\",2,0],[2,135,31,21,\"לְבוּשׁ שָׁנִים. בִּגְדֵי צִבְעוֹנִין:\",3,0],[2,135,31,22,\"מַרְבַּדִּים. מַצָּעוֹת נָאוֹת לַמִּטָּה, כְּמוֹ ״מַרְבַּדִּים רִבַּדְתִּי״ (משלי ז:טז):\",1,0],[2,135,31,23,\"נוֹדָע בַּשְּׁעָרִים בַּעְלָהּ. נִכָּר הוּא בֵּין חֲבֵירָיו מִפְּנֵי מַלְבּוּשָׁיו שֶׁהֵם נָאִים:\",1,0],[2,135,31,24,\"לַכְּנַעֲנִי. תַּגָּר:\",1,0],[2,135,31,25,\"לְיוֹם אַחֲרוֹן. בְּיוֹם מוֹתָהּ נִפְטֶרֶת בְּשֵׁם טוֹב:\",1,0],[2,135,31,25,\"וַתִּשְׂחַק. כָּל יָמֶיהָ עַל יוֹם מִיתָתָהּ, שֶׁיְּהֵא נִכְבָּד בְּשֵׁם טוֹב:\",2,0],[2,135,31,27,\"צוֹפִיָּה. הִיא בְּבֵיתָהּ נוֹתֶנֶת לֵב עַל צָרְכֵי בְּנֵי בֵיתָהּ, אֵיךְ יִנְהֲגוּ בֶּאֱמֶת וּצְנִיעוּת:\",1,0],[2,135,31,29,\"רַבּוֹת בָּנוֹת. כָּךְ מְאַשְּׁרִין אוֹתָהּ בַּעְלָהּ וּבָנֶיהָ:\",1,0],[2,135,31,30,\"שֶׁקֶר הַחֵן. אֵשֶׁת הַחֵן וְיוֹפִי אֵין מְהַלְּלִין אוֹתָהּ, אֶלָּא הַכֹּל הֶבֶל וְשֶׁקֶר; אֲבָל אִשָּׁה יִרְאַת ה׳ הִיא לְבַד תִתְהַלָּל:\",1,0],[2,135,31,31,\"מַעֲשֶׂיהָ. כִּשְׁרוֹן מַעֲשֶׂיהָ מֵעִיד עָלֶיהָ, לְהַלְּלָהּ בְּשַׁעַר הָעִיר כָּל יוֹצֵא וָבָא. זוֹ הַמְּלִיצָה שֶׁפֵּרַשְׁתִּי. אֲבָל לְפִי הַמָּשָׁל עַל הַתּוֹרָה וְלוֹמְדֶיהָ הַפָּרָשָׁה מִתְבָּאֶרֶת:\",1,0],[2,135,31,31,\"(י) אֵשֶׁת חַיִל. הִיא הַתּוֹרָה:\",2,0],[2,135,31,31,\"מִי יִמְצָא. אַשְׁרֵי הַזּוֹכֶה לִמְצֹא אוֹתָהּ:\",3,0],[2,135,31,31,\"מִפְּנִינִים. מַרְגָּלִיּוֹת:\",4,0],[2,135,31,31,\"(יא) וְשָׁלָל לֹא יֶחְסָר. אוֹכֵל פֵּרוֹת בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא:\",5,0],[2,135,31,31,\"(יג) דָּרְשָׁה צֶמֶר וּפִשְׁתִּים. לְפִי שֶׁהִמְשִׁילָהּ לְאִשָּׁה, דִּבֵּר לְפִי הַמְּלִיצָה כְּצָרְכֵי מְלֶאכֶת הַנָּשִׁים, וְהַמָּשָׁל כָּךְ הוּא: דּוֹרֶשֶׁת הַתּוֹרָה מִקְרָא, מִשְׁנָה, מִדְרָשׁ, וּמְחַזֶּרֶת אַחֲרֵיהֶם, שֶׁהֵם צָרְכֵי הַתַּלְמִידִים:\",6,0],[2,135,31,31,\"(יד) הָיְתָה כָּאֳנִיּוֹת סוֹחֵר. מְבִיאָה הִיא לְלוֹמְדֶיהָ בְּרָכָה וּמָזוֹן:\",7,0],[2,135,31,31,\"(טו) וַתָּקָם בְּעוֹד לַיְלָה. מַשְׁכִּימִים בָּאַשְׁמוֹרֶת (מסכת ברכות ג:):\",8,0],[2,135,31,31,\"וְתִתֵּן טֶרֶף לְבֵיתָהּ. שׁוֹנֶה הָרַב לַתַּלְמִידִים הַחֹק הַקָּצוּב לָהֶם:\",9,0],[2,135,31,31,\"(טז) זָמְמָה שָׂדֶה. זָמְמָה בְּזֶמֶם וּבְרֶסֶן אֶת ״עֵשָׂו אִישׁ שָׂדֶה״ (בראשית כה:כז):\",10,0],[2,135,31,31,\"וַתִּקָּחֵהוּ. מִן הָעוֹלָם, לְהַאֲבִידוֹ:\",11,0],[2,135,31,31,\"מִפְּרִי מַעֲשֶׂיהָ נָטְעָה כֶרֶם. יִשְׂרָאֵל, לְקַיְּמָם לְחַיֵּי הָעוֹלָם הַבָּא:\",12,0],[2,135,31,31,\"(יח) טָעֲמָה. דְּבוּרָהּ:\",13,0],[2,135,31,31,\"לֹא יִכְבֶּה בַלַּיְלָה נֵרָהּ. בְּלֵיל כְּתִיב, חָסֵר ה׳: בְּלֵיל שִׁמּוּרִים שֶׁנִּגְּפוּ הַמִּצְרִיִּים (שמות יב:מב) הֵאִירָה לְיִשְׂרָאֵל וְהֵגִינָה עֲלֵיהֶם:\",14,0],[2,135,31,31,\"(יט) בַּכִּישׁוֹר. בְּכִשְׁרוֹן מַעֲשֶׂיהָ:\",15,0],[2,135,31,31,\"תָּמְכוּ פָלֶךְ. ״מַשְׁעֵן וּמַשְׁעֵנָה״ (ישעיה ג:א), כְּמוֹ ״מַחֲזִיק בַּפֶּלֶךְ״ (שמואל ב ג:כט):\",16,0],[2,135,31,31,\"(כ) כַּפָּהּ פָּרְשָׂה. לְמִי שֶׁמֵּשִׂים עַצְמוֹ עָלֶיהָ כְּעָנִי, בּוֹ הִיא מִתְקַיֶּמֶת (אבות ו:ד):\",17,0],[2,135,31,31,\"(כא) לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג. שֶׁדָּנִין בּוֹ הָרְשָׁעִים מֵאֵשׁ לְשֶׁלֶג (גֵּיהִנֹּם):\",18,0],[2,135,31,31,\"לָבֻשׁ שָׁנִים. בְּרִית דַּם מִילָה. דָּבָר אַחֵר: מְלֻבָּשִׁים בְּכֶפֶל ״נָתֹן תִּתֵּן״ (דברים טו:י), ״פָּתֹחַ תִּפְתַּח״ (דברים טו:ח), ״הַעֲנֵיק תַּעֲנִיק״ (דברים טו:יד). כָּל אֵלּוּ מַצִּילִין אוֹתָן מִשֶּׁלֶג גֵּיהִנֹּם. כָּךְ הוּא נִדְרָשׁ בַּתַּנְחוּמָה (יל״ש משלי תתקסד):\",19,0],[2,135,31,31,\"(כד) סָדִין עָשְׂתָה. לְבוּשׁ תִּפְאֶרֶת נוֹתֶנֶת לַחֲכָמִים:\",20,0],[2,135,31,31,\"וַחֲגוֹר נָתְנָה לַכְּנַעֲנִי. ( ) (לְמִי) לְפִי שֶׁהוּא חָגוּר בִּסְחוֹרָתָהּ, נוֹתְנָה אֵזוֹר לְמָתְנֵיהֶם:\",21,0],[2,135,31,31,\"(כה) לְיוֹם אַחֲרוֹן. אֵין לָהֶם לְהִתְעַצֵּב מִמִּדַּת הַדִּין כִּי יִנָּצְלוּ מִמֶּנּוּ, וְכָל יְמֵי חַיֵּיהֶם יִשְׂחֲקוּ לְיוֹם הַדִּין. מִי שֶׁאֵינוֹ צָרִיךְ לִדְאֹג נוֹפֵל בַּדָּבָר לְשׁוֹן צְחוֹק, כְּמוֹ ״וְיִשְׂחַק לְרַעַשׁ כִּידוֹן״ (איוב מא:כא):\",22,0],[2,135,31,31,\"(כז) צוֹפִיָּה הֲלִיכוֹת בֵּיתָהּ. הַתּוֹרָה מְלַמֶּדֶתָם דֶּרֶךְ הַטּוֹב, לִפְרוֹשׁ מֵעֲבֵירָה:\",23,0],[2,135,31,31,\"(כח) קָמוּ בָנֶיהָ. הַתַּלְמִידִים:\",24,0],[2,135,31,31,\"בַּעְלָהּ. הַקָּדוֹשׁ בָּרוּךְ הוּא:\",25,0],[2,135,31,31,\"(ל) שֶׁקֶר הַחֵן. שָׁב עַל כָּל הָעוֹבְדֵי גִּלּוּלִים:\",26,0],[2,135,31,31,\"וְהֶבֶל. גְּדוּלָּתָן וְיָפְיָן:\",27,0],[2,135,31,31,\"תְּנוּ לָהּ. לֶעָתִיד לָבֹא:\",28,0],[2,135,31,31,\"מִפְּרִי יָדֶיהָ. תִּפְאֶרֶת וּגְדוּלָּה, עֹז, פְּאֵר וּמֶמְשָׁלָה:\",29,0],[2,136,1,1,\"אַשְׁרֵי הָאִישׁ. בַּעֲשָׂרָה לְשׁוֹנוֹת שֶׁל זֶמֶר נֶאֱמַר סֵפֶר זֶה, בְּנִצּוּחַ, בְּנִגּוּן, בְּמִזְמוֹר, בְּשִׁיר, בְּהַלֵּל, בִּתְפִלָּה, בִּבְרָכָה, בְּהוֹדָאָה, בְּאַשְׁרֵי, בְּהַלְלוּיָהּ, כְּנֶגֶד עֲשָׂרָה בְּנֵי אָדָם שֶׁאֲמָרוּהוּ, אָדָם, מַלְכִּי צֶדֶק, אַבְרָהָם, מֹשֶׁה, דָּוִד, שְׁלֹמֹה, אָסָף, וּשְׁלֹשָׁה בְּנֵי קֹרַח, וַחֲלוּקִין עַל יְדוּתוּן (קהלת רבה ז,לט). יֵשׁ אוֹמְרִים: אָדָם הָיָה כְּמוֹ שֶׁכָּתוּב בְּדִבְרֵי הַיָּמִים (דברי הימים א טז:לח), וְיֵשׁ אוֹמְרִים: אֵין יְדוּתוּן שֶׁבְּסֵפֶר זֶה אֶלָּא עַל שֵׁם הַדָּתוֹת וְהַדִּינִים שֶׁל גְּזֵרוֹת שֶׁעָבְרוּ עָלָיו וְעַל יִשְׂרָאֵל:\",1,0],[2,136,1,1,\"אַשְׁרֵי הָאִישׁ. (לישפלישמנ״ץ בלע״ז) אִשּׁוּרָיו שֶׁל אִישׁ וּתְהִלּוֹתָיו שֶׁל אָדָם אֵלּוּ הֵם אֲשֶׁר לֹא הָלַךְ, כִּי מִתּוֹךְ שֶׁלֹּא הָלַךְ לֹא עָמָד, וּמִתּוֹךְ שֶׁלֹּא עָמַד לֹא יָשָׁב:\",2,0],[2,136,1,1,\"לֵצִים. (גאבור״ש בלע״ז. מלה נשנית גאבערס בל״א שפעטטער:)\",3,0],[2,136,1,2,\"כִּי אִם בְּתוֹרַת ה׳ חֶפְצוֹ. הָא לָמַדְתָּ, שֶׁמּוֹשַׁב לֵצִים מְבִיאוֹ לִידֵי בִּטּוּל תּוֹרָה (עבודה זרה יח:):\",1,0],[2,136,1,2,\"וּבְתוֹרָתוֹ יֶהְגֶּה. בִּתְחִלָּה הִיא נִקְרֵאת תּוֹרַת ה׳, וּמִשֶּׁעָמַל בָּהּ הִיא נִקְרֵאת תּוֹרָתוֹ (עבודה זרה יט.):\",2,0],[2,136,1,2,\"יֶהְגֶּה. כָּל לְשׁוֹן הֶגֶה בַּלֵּב הוּא, כְּמָה דְאַתְּ אָמַר ״וְהֶגְיוֹן לִבִּי״ (תהלים יט:טו), ״לִבְּךָ יֶהְגֶּה אֵימָה״ (ישעיהו לג:יח), ״כִּי שֹׁד יֶהְגֶּה לִבָּם״ (משלי כד:ב):\",3,0],[2,136,1,3,\"שָׁתוּל. פְּלַנְדִי״ץ בְּלַעַ״ז:\",1,0],[2,136,1,3,\"פַּלְגֵי. רָאוּיְיָארוֹ״שׁ בְּלַעַ״ז:\",2,0],[2,136,1,3,\"וְעָלֵהוּ לֹא יִבּוֹל. אֲפִלּוּ הַפְּסֹלֶת שֶׁבּוֹ לְצֹרֶךְ הִיא. שִׂיחָתָן שֶׁל תַּלְמִידֵי חֲכָמִים לְצֹרֶךְ הִיא וּצְרִיכָה לִמּוּד (עבודה זרה יט:):\",3,0],[2,136,1,3,\"לֹא יִבּוֹל. לְשׁוֹן כָּמוֹשׁ, פְּלִישְׁטִי״ר בְּלַעַ״ז:\",4,0],[2,136,1,4,\"כַּמּוֹץ. לְשׁוֹן קַשׁ, קוֹמְבְּלָ״א בְּלַעַ״ז:\",1,0],[2,136,1,5,\"עַל כֵּן וְגוֹ׳. דָּבוּק הוּא לַמִּקְרָא שֶׁל אַחֲרָיו:\",1,0],[2,136,1,6,\"כִּי יוֹדֵעַ ה׳ וְגוֹ׳. לְפִי שֶׁהוּא יוֹדֵעַ דֶּרֶךְ צַדִּיקִים, וּלְפָנָיו הוּא לְהַכִּירָהּ תָּמִיד, וְדֶרֶךְ רְשָׁעִים שְׂנוּאָה בְּעֵינָיו וּמַעֲבִירָהּ מִלְּפָנָיו, עַל כֵּן לֹא תְהֵא הֲקָמַת רֶגֶל לָרְשָׁעִים לְיוֹם הַדִּין, וְלַחַטָּאִים לִיכָּתֵב בַּעֲדַת צַדִּיקִים:\",1,0],[2,136,2,1,\"לָמָּה רָגְשׁוּ גוֹיִם. רַבּוֹתֵינוּ (ברכות ז:) דָּרְשׁוּ אֶת הָעִנְיָן עַל מֶלֶךְ הַמָּשִׁיחַ, וּלְפִי מַשְׁמָעוֹ וּלִתְשׁוּבַת הַמִּינִים יִהְיֶה נָכוֹן לְפוֹתְרוֹ עַל דָּוִד עַצְמוֹ, כְּעֵין שֶׁנֶּאֱמַר ״וַיִּשְׁמְעוּ פְלִשְׁתִּים כִּי מָשְׁחוּ יִשְׂרָאֵל אֶת דָּוִד לְמֶלֶךְ עֲלֵיהֶם וַיִּקָּבְצוּ פְלִשְׁתִּים אֶת מַחֲנֵיהֶם״ (שמואל ב ה:יז), וְנָפְלוּ בְיָדוֹ, וַעֲלֵיהֶם אָמַר לָמָּה רָגְשׁוּ גוֹיִם וְנִתְקַבְּצוּ כֻּלָּם:\",1,0],[2,136,2,1,\"וּלְאֻמִּים יֶהְגּוּ. בְּלִבָּם רִיק:\",2,0],[2,136,2,1,\"וּלְאֻמִּים. מְנַחֵם פָּתַר לְאֻמִּים וְאֻמִּים וְגוֹיִם כֻּלָּם קְרוֹבֵי עִנְיָן:\",3,0],[2,136,2,2,\"יִתְיַצְּבוּ מַלְכֵי אֶרֶץ וְרוֹזְנִים נוֹסְדוּ יָחַד וְגוֹ׳. וְרוֹזְנִים. שִׁינְיוֹ״רְשׁ בְּלַעַ״ז:\",1,0],[2,136,2,2,\"נוֹסְדוּ. לְשׁוֹן סוֹד, פורקונשילרוו״ט בְּלַעַ״ז. וּמַה הִיא הָעֵצָה?\",2,0],[2,136,2,3,\"נְנַתְּקָה אֶת מוֹסְרוֹתֵימוֹ. דִּישְׁרוֹנְפְרוֹיְמ״שׁ לוֹיְקוֹרַאנְגְל״שׁ בְּלַעַ״ז, אֵלּוּ רְצוּעוֹת שֶׁקּוֹשְׁרִין הָעוֹל בָּהֶם:\",1,0],[2,136,2,3,\"עֲבוֹתֵימוֹ. לוֹיִקוֹרְדוֹ״שׁ בְּלַעַ״ז:\",2,0],[2,136,2,4,\"יִשְׂחָק, יִלְעַג, יְדַבֵּר. לְשׁוֹן הֹוֶה הֵם מְשַׁמְּשִׁין:\",1,0],[2,136,2,5,\"אָז יְדַבֵּר אֵלֵימוֹ. כְּמוֹ עֲלֵיהֶם, וּמַה הוּא הַדִּבּוּר?\",1,0],[2,136,2,6,\"וַאֲנִי נָסַכְתִּי מַלְכִּי. לָמָּה רְגַשְׁתֶּם, וַאֲנִי מִנִּיתִי לִי אֶת זֶה לִנְסֹךְ וְלִמְלֹךְ עַל צִיּוֹן הַר קָדְשִׁי?\",1,0],[2,136,2,7,\"אֲסַפְּרָה אֶל חוֹק. אָמַר דָּוִד: חֹק קָצוּב הוּא, וּמְקַבֵּל עָלַי לְסַפֵּר זֹאת וּלְהוֹדִיעַ:\",1,0],[2,136,2,7,\"ה׳ אָמַר אֵלַי. עַל יְדֵי נָתָן וְגָד וּשְׁמוּאֵל (שמואל ב ז:ד; שמואל א ג:כא):\",2,0],[2,136,2,7,\"בְּנִי אַתָּה. רֹאשׁ לְיִשְׂרָאֵל, הַקְּרוּיִין בַּתּוֹרָה ״בְּנִי בְכוֹרִי״ (שמות ד:כב), וְהֵם יִתְקַיְּמוּ עַל יָדְךָ. כְּמוֹ שֶׁנֶּאֱמַר בְּאַבְנֵר (שמואל ב ג:יח): ״כֹּה אָמַר ה׳ בְּיַד דָּוִד עַבְדִּי אוֹשִׁיעַ אֶת עַמִּי יִשְׂרָאֵל״, וּבִשְׁבִילָם אַתָּה לְפָנַי כְּבֵן, שֶׁכֻּלָּם תְּלוּיִין בְּךָ:\",3,0],[2,136,2,7,\"אֲנִי הַיּוֹם. שֶׁהִמְלַכְתִּיךָ עֲלֵיהֶם:\",4,0],[2,136,2,7,\"יְלִדְתִּיךָ. לִהְיוֹת קָרוּי בְּנִי, וְחָבִיב עָלַי כְּבֵן בִּשְׁבִילָם; כְּמוֹ שֶׁנֶּאֱמַר (דברי הימים א יד:ב) ״וַיֵּדַע דָּוִיד כִּי הֱכִינוֹ ה׳ לְמֶלֶךְ עַל יִשְׂרָאֵל וְכִי נִשֵּׂאת מַלְכוּתוֹ בַּעֲבוּר עַמּוֹ יִשְׂרָאֵל״, וּמָצִינוּ בְּמַלְכֵי יִשְׂרָאֵל הַחֲבִיבִין לְפָנָיו שֶׁקְּרוּיִין בָּנִים, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב ז:יד) בִּשְׁלֹמֹה ״הוּא יִהְיֶה לִּי לְבֵן וַאֲנִי אֶהְיֶה לּוֹ לְאָב״. וְעוֹד מָצִינוּ בְּדָוִד בְּמִזְמוֹר פ״ט ״הוּא יִקְרָאֵנִי אָבִי אָתָּה אֵלִי וְצוּר יְשׁוּעָתִי״ (תהלים פט:כז):\",5,0],[2,136,2,8,\"שְׁאַל מִמֶּנִּי. הִתְפַּלֵּל אֵלַי בְּכָל עֵת שֶׁאַתָּה בָּא לְהִלָּחֵם בְּאוֹיְבֶיךָ:\",1,0],[2,136,2,9,\"תְּרֹעֵם. תְּרוֹצְצֵם:\",1,0],[2,136,2,9,\"בְּשֵׁבֶט בַּרְזֶל. הִיא הַחֶרֶב:\",2,0],[2,136,2,9,\"תְּנַפְּצֵם. תְּשַׁבְּרֵם, וְהוּא לְשׁוֹן נָפוֹץ בְּכָל הַמִּקְרָא: חֶרֶס הַמְּשֻׁבָּר לִשְׁבָרִים דַּקִּים:\",3,0],[2,136,2,10,\"וְעַתָּה מְלָכִים הַשְׂכִּילוּ. נְבִיאֵי יִשְׂרָאֵל אַנְשֵׁי רַחֲמִים, וּמוֹכִיחִים אֻמּוֹת הָעוֹלָם לָסוּר מֵרָעָתָם (תנחומא, בלק א), שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא פּוֹשֵׁט יָד לָרְשָׁעִים וְלַצַּדִּיקִים:\",1,0],[2,136,2,11,\"וְגִילוּ בִּרְעָדָה. כְּשֶׁתָּבוֹא אוֹתָהּ רְעָדָה שֶׁכָּתוּב בָּהּ (ישעיהו לג:יד) ״אָחֲזָה רְעָדָה חֲנֵפִים״, תָּגִילוּ וְתִשְׂמְחוּ אִם עֲבַדְתֶּם אֶת ה׳:\",1,0],[2,136,2,12,\"נַשְּׁקוּ בַר. זָרְזוּ עַצְמְכֶם בְּבַר לֵב. (נוסח אחר) נַשְּׁקוּ בַר. אַרְנִישְׁמְנְט בְּלַעַ״ז, וּמְנַחֵם פָּתַר אוֹתוֹ לְשׁוֹן תַּאֲוָה כְּמוֹ ״וְאֶל אִישֵׁךְ תְּשׁוּקָתֵךְ״ (בראשית ג:טז):\",1,0],[2,136,2,12,\"פֶּן יֶאֱנַף. פֶּן יִקְצֹף:\",2,0],[2,136,2,12,\"וְתֹאבְדוּ דֶרֶךְ. כְּעִנְיָן שֶׁנֶּאֱמַר ״וְדֶרֶךְ רְשָׁעִים תֹּאבֵד״ (תהלים א:ו):\",3,0],[2,136,2,12,\"כִּי יִבְעַר כִּמְעַט אַפּוֹ. כִּי בְרֶגַע מוּעָט יִבְעַר אַפּוֹ עֲלֵיכֶם פִּתְאוֹם, וְאוֹתָהּ שָׁעָה אַשְׁרֵי כָּל חוֹסֵי בוֹ – יִהְיוּ נִכָּרִים אִשּׁוּרֵי הַחוֹסִים בּוֹ:\",4,0],[2,136,3,1,\"מִזְמוֹר לְדָוִד בְּבָרְחוֹ. הַרְבֵּה דְּרָשׁוֹת דָּרְשׁוּ בְּנֵי אַגָּדָה בַּדָּבָר, וְרַבּוֹתֵינוּ אָמְרוּ (ברכות ז:): מִשֶּׁאָמַר לוֹ הַנָּבִיא ״הִנְנִי מֵקִים עָלֶיךָ רָעָה מִתּוֹךְ בֵּיתֶךָ״ (שמואל ב יב:יא) הָיָה לִבּוֹ סוֹעֵר שֶׁמָּא עֶבֶד אוֹ מַמְזֵר יָקוּם עָלַי שֶׁאֵינוֹ מְרַחֵם עָלַי, כֵּיוָן שֶׁיָּדַע שֶׁבְּנוֹ הוּא שָׂמַח. וּמִדְרַשׁ אַגָּדָה: עַל שֶׁרָאָה טַכְסִיסוֹ קַיֶּמֶת, שֶׁהָיוּ עֲבָדָיו וְהַכְּרֵתִי וְהַפְּלֵתִי, שֶׁהֵם סַנְהֶדְרִין, מַחֲזִיקִים אֲדָנוּתוֹ עֲלֵיהֶם; כְּשֶׁאָמַר לָהֶם ״קוּמוּ וְנִבְרְחָה מִפְּנֵי אַבְשָׁלוֹם״ (שמואל ב טו:יד), מַה כְּתִיב שָׁם? ״כֹּל אֲשֶׁר יִבְחַר אֲדֹנִי הַמֶּלֶךְ הִנֵּה עֲבָדֶיךָ״ (שמואל ב טו:טו); וּכְשֶׁבָּא מַחֲנַיִם, ״וְשֹׁבִי בֶן נָחָשׁ וּמָכִיר בֶּן עַמִּיאֵל וּבַרְזִלַּי הַגִּלְעָדִי״ (שמואל ב יז:כז) יָצְאוּ לִקְרָאתוֹ וְכִלְכְּלוּהוּ שָׁם:\",1,0],[2,136,3,2,\"רַבִּים קָמִים עָלָי. בְּנֵי אָדָם גְּדוֹלִים בַּתּוֹרָה, גְּדוֹלִים בְּחָכְמָה, גְּדוֹלִים בְּעֹשֶׁר, גְּדוֹלִים בְּקוֹמָה; כְּגוֹן שָׁאוּל (שמואל א טז:ז) וִילִידֵי הָרָפָה (שמואל ב כא:טז-כב), דּוֹאֵג (שמואל א כא:ח) וַאֲחִיתֹפֶל (שמואל ב טו:יב):\",1,0],[2,136,3,3,\"אוֹמְרִים לְנַפְשִׁי. עַל נַפְשִׁי:\",1,0],[2,136,3,3,\"אֵין יְשׁוּעָתָה לּוֹ בֵאלֹהִים סֶלָה. לְפִי שֶׁבָּא עַל אֵשֶׁת אִישׁ:\",2,0],[2,136,3,6,\"אֲנִי שָׁכַבְתִּי וָאִישָׁנָה. לִבִּי אָטוּם בִּדְאָגָה וָפַחַד:\",1,0],[2,136,3,6,\"הֱקִיצוֹתִי. מִדְּאָגָתִי, כִּי בָטַחְתִּי כִּי ה׳ יִסְמְכֵנִי:\",2,0],[2,136,3,7,\"שָׁתוּ. לְשׁוֹן ״שְׁאִיָּה״ (ישעיה כד:יב) גאטירנ״ט בְּלַעַ״ז. וְיֵשׁ אוֹמְרִים: שָׁתוּ כְּמוֹ שָׂמוּ, כְּמוֹ ״לְמַעַן שִׁתִי אֹתֹתַי״ (שמות י:א):\",1,0],[2,136,3,8,\"כִּי הִכִּיתָ אֶת כָּל אוֹיְבַי לֶחִי. מַכַּת בִּזָּיוֹן הִיא, כְּמָה דְאַתְּ אָמַר: ״יִתֵּן לְמַכֵּהוּ לֶחִי״ (איכה ג:ל), ״בַּשֵּׁבֶט יַכּוּ עַל הַלֶּחִי״ (מיכה ד:יד). וּמִדְרַשׁ אַגָּדָה: מַכַּת הַפֶּה, כְּמָה דְאַתְּ אָמַר: ״וַיְצַו אֶל בֵּיתוֹ וַיֵּחָנַק״ (שמואל ב יז:כג):\",1,0],[2,136,3,8,\"שִׁנֵּי רְשָׁעִים. גְּבוּרָתָם:\",2,0],[2,136,3,9,\"לַה׳ הַיְשׁוּעָה וְגוֹ׳. עָלָיו לְהוֹשִׁיעַ אֶת עֲבָדָיו וְאֶת עַמּוֹ, וְעַל עַמּוֹ מוּטָּל לְבָרֵךְ וּלְהוֹדוֹת לוֹ סֶּלָה:\",1,0],[2,136,4,1,\"לַמְנַצֵּחַ בִּנְגִינוֹת. מִזְמוֹר זֶה יָסַד דָּוִד, שֶׁיֹּאמְרוּהוּ בְּנֵי לֵוִי הַמְנַצְּחִין בִּנְגִינוֹת בְּשִׁיר עַל הַדּוּכָן. לְשׁוֹן נִצּוּחַ נוֹפֵל בַּמִּתְחַזְּקִים בָּעֲבוֹדָה, כְּעִנְיָן שֶׁנֶּאֱמַר ״יַעַמְדוּ הַלְוִיִּם מִבֶּן עֶשְׂרִים שָׁנָה וָמַעְלָה לְנַצֵּחַ עַל מְלֶאכֶת בֵּית ה׳״ (עזרא ג:ח):\",1,0],[2,136,4,2,\"בַּצָּר הִרְחַבְתָּ לִּי. בַּיָּמִים שֶׁעָבְרוּ עָלַי, וּמֵעַתָּה חָנֵּנִי וּשְׁמַע תְּפִלָּתִי:\",1,0],[2,136,4,3,\"בְּנֵי אִישׁ. בְּנֵי אַבְרָהָם יִצְחָק וְיַעֲקֹב הַקְּרוּיִים אִישׁ, בְּאַבְרָהָם נֶאֱמַר (בראשית כ:ז) ״הָשֵׁב אֶת אֵשֶׁת הָאִישׁ״, בְּיִצְחָק נֶאֱמַר (בראשית כד:סה) ״מִי הָאִישׁ הַלָּזֶה״, בְּיַעֲקֹב נֶאֱמַר (בראשית כה:כז) ״אִישׁ תָּם״:\",1,0],[2,136,4,3,\"עַד מֶה כְבוֹדִי לִכְלִמָּה. עַד מָתַי אַתֶּם מְבַזִּים אוֹתִי? הֲרְאִיתֶם אֶת בֶּן יִשַׁי (שמואל א כב:ט), ״מִי דָוִד וּמִי בֶן יִשָׁי״ (שמואל א כה:י), ״בִּכְרָת בְּנִי עִם בֶּן יִשַׁי״ (שמואל א כב:ח), ״כִּי בוֹחֵר אַתָּה לְבֶן יִשַׁי״ (שמואל א כ:ל), אֵין לִי שֵׁם?\",2,0],[2,136,4,3,\"תְּבַקְשׁוּ כָזָב. תִּרְדְּפוּ לִמְצוֹא כְּזָבִים, כְּגוֹן הַזִּיפִים שֶׁמַּלְשִׁינִים עָלַי, וְלִי הָיוּ מַרְאִים שָׁלוֹם, וְכַיּוֹצֵא בָהֶם דִּילָטוֹרִין שֶׁהָיוּ בִּימֵי שָׁאוּל: ״הֲלֹא דָוִד מִסְתַּתֵּר בְּגִבְעַת הַחֲכִילָה״ (שמואל א כג:יט), וְכֵן הַרְבֵּה:\",3,0],[2,136,4,4,\"הִפְלָה. הִבְדִּיל:\",1,0],[2,136,4,5,\"רִגְזוּ. חִרְדוּ מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאַל תֶּחֱטָאוּ:\",1,0],[2,136,4,5,\"אִמְרוּ בִלְבַבְכֶם עַל מִשְׁכַּבְכֶם. הָשִׁיבוּ עַל לְבַבְכֶם שֶׁהִזְהִיר הַקָּדוֹשׁ בָּרוּךְ הוּא עַל כָּךְ:\",2,0],[2,136,4,6,\"זִבְחוּ זִבְחֵי צֶדֶק. הַצְדִּיקוּ מַעֲשֵׂיכֶם, וַהֲרֵי אַתֶּם כִּמְקְרִיבִים זְבָחִים:\",1,0],[2,136,4,6,\"וּבִטְחוּ אֶל ה׳. שֶׁיַּשְׁפִּיעַ לָכֶם טוֹבָה, וְאַל תֶּחֱטָאוּ לוֹ בִּשְׁבִיל מָמוֹן, שֶׁאַתֶּם מְצַפִּים לְקַבֵּל שָׂכָר מֵאֵת שָׁאוּל:\",2,0],[2,136,4,7,\"רַבִּים אוֹמְרִים מִי יַרְאֵנוּ טוֹב. רַבִּים מִיִּשְׂרָאֵל יֵשׁ שֶׁרוֹאִין רְשָׁעִים בְּעֹשֶׁר וּבְשַׁלְוָה וְאוֹמְרִים: מִי יַרְאֵנוּ טוֹב לִהְיוֹת עֲשִׁירִים וּמַשִּׂיגֵי תַּאֲוָה כָּאֵלּוּ?\",1,0],[2,136,4,7,\"נְסָה עָלֵינוּ. הָרֵם עָלֵינוּ לְנֵס אֶת אוֹר פָּנֶיךָ, לְשׁוֹן ״הָרִימוּ נֵס״ (ישעיהו סב:י), ״אָרִים נִסִּי״ (ישעיהו מט:כב). לָשׁוֹן אַחֵר: נְסָה עָלֵינוּ. רֶפְלַנְבִּי״ר בְּלַעַ״ז, כְּמוֹ ״אַבְנֵי נֵזֶר מִתְנוֹסְסוֹת״ (זכריה ט:טז). אֲבָל אֲנִי אֵינִי מְקַנֵּא בָּהֶם, כִּי שִׂמְחָה נְתוּנָה בְלִבִּי מֵעֵת דְּגָנָם וְתִירוֹשָׁם רַבּוּ. בָּטוּחַ אֲנִי: אִם לְמַכְעִיסִים כָּךְ, לְעוֹשֵׂי רְצוֹנוֹ עַל אַחַת כַּמָּה וְכַמָּה, לֶעָתִיד, שֶׁהוּא יוֹם קִבּוּל שְׂכָרָם:\",2,0],[2,136,4,9,\"בְּשָׁלוֹם יַחְדָּו אֶשְׁכְּבָה וְאִישָׁן. אִם הָיוּ יִשְׂרָאֵל בְּשָׁלוֹם יַחְדָּו עִמִּי, הָיִיתִי שׁוֹכֵב וְיָשֵׁן בֶּטַח וְלֹא הָיִיתִי יָרֵא מִכָּל צַר וְאוֹיֵב:\",1,0],[2,136,4,9,\"לְבָדָד לָבֶטַח. כְּמוֹ ״בֶּטַח בָּדָד עֵין יַעֲקֹב״ (דברים לג:כח), לְשׁוֹן מִבְטָח וָשֶׁקֶט הוּא, שֶׁאֵינוֹ צָרִיךְ לְהוֹשִׁיב גְּיָסוֹת עִמּוֹ:\",2,0],[2,136,5,1,\"אֶל הַנְּחִילוֹת. מְנַחֵם פָּתַר בְּכֻלָּן: נְחִילוֹת וַעֲלָמוֹת, גִּתִּית, יְדוּתוּן – כֻּלָּם שְׁמוֹת כְּלֵי זֶמֶר הֵם, וּנְעִימַת הַמִּזְמוֹר הָיְתָה לְפִי שִׁיר הָרָאוּי לְאוֹתוֹ כְּלִי. וּמִדְרַשׁ אַגָּדָה יֵשׁ מְפָרְשִׁים נְחִילוֹת לְשׁוֹן נַחֲלָה; וְאֵין זֶה מַשְׁמָעוּת הַתֵּיבָה, וְגַם עִנְיַן הַמִּזְמוֹר אֵינוֹ מְדַבֵּר בְּנַחֲלָה. וְיִתָּכֵן לִפְתּוֹר נְחִילוֹת – גְּיָסוֹת, כְּמוֹ נָחִיל שֶׁל דְּבוֹרִים (בבא קמא י:); וּכְמוֹ ״וְנַחֲלֵי בְלִיַּעַל״ (שמואל ב כב:ה), וְתִרְגֵּם יוֹנָתָן: ״סִיעַת חַיָּבִין״. תְּפִלָּה בִּשְׁבִיל גְּיָסוֹת אוֹיְבִים הַבָּאִים עַל יִשְׂרָאֵל; וְאוֹמֵר הַמְשׁוֹרֵר מִזְמוֹר הַזֶּה בִּשְׁבִיל כָּל יִשְׂרָאֵל:\",1,0],[2,136,5,2,\"אֲמָרַי הַאֲזִינָה ה׳. כְּשֶׁיֵּשׁ בִּי כֹּחַ לִשְׁאֹל צְרָכַי לְפָנֶיךָ, וּכְשֶׁאֵין בִּי כֹּחַ לְהִתְפַּלֵּל לְפָנֶיךָ וְהַדְּאָגָה עֲצוּרָה בְּלִבִּי, בִּינָה הֲגִיגִי. הָבֵן הֲגִיוֹן לִבִּי. כָּךְ מְפֹרָשׁ בַּמִּדְרָשׁ. כָּל בִּינָה שֶׁבַּמִּקְרָא הַטַּעַם תַּחַת הַנּוּ״ן, חוּץ מִזֶּה וַחֲבֵרוֹ (איוב לד:טז) ״וְאִם בִּינָה שִׁמְעָה זֹאת״, שֶׁאֵינוֹ שֵׁם דָּבָר אֶלָּא לְשׁוֹן הָבֵן, כְּמוֹ (משלי כג:א) ״בִּין תָּבִין אֶת אֲשֶׁר לְפָנֶיךָ״, לְפִיכָךְ הַטַּעַם תַּחַת הַבֵּי״ת:\",1,0],[2,136,5,4,\"בֹּקֶר תִּשְׁמַע קוֹלִי. בַּבֹּקֶר אֲנִי קוֹרֵא לְךָ עֲלֵיהֶם, שֶׁהוּא עֵת מִשְׁפָּט בָּרְשָׁעִים, כְּמוֹ שֶׁנֶּאֱמַר ״לַבְּקָרִים אַצְמִית כָּל רִשְׁעֵי אָרֶץ״ (תהלים קא:ח), ״הֱיֵה זְרוֹעָם לַבְּקָרִים״ (ישעיהו לג:ב), ״כִּי בַבֹּקֶר בַּבֹּקֶר יַעֲבֹר״ (ישעיהו כח:יט):\",1,0],[2,136,5,4,\"בֹּקֶר אֶעֱרָךְ לְךָ. תְּפִלָּתִי עַל זֹאת, אֶעֱרֹךְ לְשׁוֹן מַעֲרָכָה הוּא, כָּךְ חִבְּרוֹ מְנַחֵם:\",2,0],[2,136,5,4,\"וַאֲצַפֶּה. שֶׁתַּעֲשֶׂה בָּהֶם מִשְׁפָּטִים:\",3,0],[2,136,5,5,\"כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה. וְנָאֶה לְךָ לְאַבֵּד הָרִשְׁעָה מִן הָעוֹלָם:\",1,0],[2,136,5,5,\"לֹא יְגֻרְךָ רָע. לֹא יָגוּר אֶצְלְךָ:\",2,0],[2,136,5,6,\"הוֹלְלִים. מִשְׁתַּטִּים, וּבִלְשׁוֹן מִשְׁנָה מְעֻרְבָּבִין:\",1,0],[2,136,5,7,\"אִישׁ דָּמִים וּמִרְמָה. זֶה עֲמָלֵק וְזַרְעוֹ:\",1,0],[2,136,5,8,\"וַאֲנִי אָבוֹא בֵיתֶךָ. לְהוֹדוֹת לְךָ בְּרֹב חַסְדְּךָ שֶׁהִפְלֵאתָ עָלֵינוּ, לְהַרְאוֹתֵנוּ נְקָמָה מֵהֶם:\",1,0],[2,136,5,9,\"שׁוֹרְרָי. עוֹיְנַי הַמְּצַפִּים שֶׁאֶבְגּוֹד בְּךָ וְתַעַזְבֵנִי, שׁוֹרְרָי כְּמוֹ ״אֲשׁוּרֶנּוּ וְלֹא קָרוֹב״ (במדבר כד:יז):\",1,0],[2,136,5,10,\"כִּי אֵין בְּפִיהוּ נְכוֹנָה. נִרְאִים כְּאוֹהֲבִים, וְהֵם אוֹיְבִים:\",1,0],[2,136,5,10,\"קִרְבָּם הַוּוֹת. מַחְשְׁבוֹתָם מִרְמָה:\",2,0],[2,136,5,10,\"קֶבֶר פָּתוּחַ גְּרוֹנָם. לִבְלֹעַ יְגִיעַ אֲחֵרִים כְּקֶבֶר הַבּוֹלֵעַ אֶת הַגּוּף:\",3,0],[2,136,5,10,\"יַחֲלִיקוּן. דִּבְרֵי חֲלַקְלַקּוֹת:\",4,0],[2,136,5,11,\"מִמּוֹעֲצוֹתֵיהֶם. שֶׁהֵם יוֹעֲצִים עַל יִשְׂרָאֵל, וְאָז יִשְׂמְחוּ כָּל חוֹסֵי בָךְ:\",1,0],[2,136,5,12,\"וְתָסֵךְ עָלֵימוֹ. תָּגוֹנֵן וּתְסוֹכֵךְ עָלֵימוֹ:\",1,0],[2,136,5,12,\"וְיַעְלְצוּ בְךָ. כְּשֶׁיִּרְאוּ שֶׁאַתָּה תְּבָרֵךְ רֵעֶיךָ וְאוֹהֲבֶיךָ:\",2,0],[2,136,5,13,\"כַּצִּנָּה. הַמַּקֶּפֶת שָׁלֹשׁ רוּחוֹתָיו שֶׁל אָדָם:\",1,0],[2,136,5,13,\"רָצוֹן. נַחַת רוּחַ, אֵפִּימַנְ״ט בְּלַעַ״ז:\",2,0],[2,136,5,13,\"תַּעְטְרֶנּוּ. תְּסוֹבְבֶנּוּ, כְּמוֹ (שמואל א כג:כו) ״וְשָׁאוּל וַאֲנָשָׁיו עוֹטְרִים אֶל דָּוִד וְאֶל אֲנָשָׁיו״:\",3,0],[2,136,6,1,\"עַל הַשְּׁמִינִית. כִּנּוֹר שֶׁל שְׁמוֹנָה נִימִין, וְשְׁמִינִית שְׁמוֹ. וְכֵן מָצִינוּ (דברי הימים א טו:כא) פְּלוֹנִי וּבָנָיו ״עַל הַשְּׁמִינִית לְנַצֵּחַ״:\",1,0],[2,136,6,3,\"אֻמְלַל. נִשְׁחַת וְדַל כֹּחַ (קונפונדו״ץ בלע״ז), כְּמוֹ ״הַיְּהוּדִים הָאֲמֵלָלִים״ דְּעֶזְרָא (נחמיה ג:לד):\",1,0],[2,136,6,4,\"וְאַתָּה ה׳ עַד מָתָי. תַּבִּיט וְאֵינְךָ רוֹפֵא?\",1,0],[2,136,6,5,\"שׁוּבָה ה׳. מֵחֲרוֹנְךָ:\",1,0],[2,136,6,5,\"חַלְּצָה נַפְשִׁי. מֵחוֹלְיִי:\",2,0],[2,136,6,7,\"אַשְׂחֶה בְכָל לַיְלָה מִטָּתִי. לְשׁוֹן ״סְחִי וּמָאוֹס״ (איכה ג:מה), ״וְהָיְתָה נִבְלָתָם כַּסּוּחָה״ (ישעיהו ה:כה) – מְמָאֵס אֲנִי מִטָּתִי בִּדְמָעוֹת. וּמְנַחֵם חִבְּרוֹ עִם ״כַּאֲשֶׁר יְפָרֵשׂ הַשֹּׂחֶה לִשְׂחוֹת״ (ישעיהו כה:יא), וְעִם ״מֵי שָׂחוּ״ (יחזקאל מז:ה):\",1,0],[2,136,6,7,\"בְּדִמְעָתִי עַרְשִׂי אַמְסֶה. אֲלַחְלֵחַ וְאַרְטִיב כְּמוֹ מַיִם:\",2,0],[2,136,6,8,\"עָשְׁשָׁה. לְשׁוֹן עֲשָׁשִׁית, עַיִן שֶׁמְּאוֹרָהּ כֵּהָה, וְדוֹמֶה לוֹ כְּאִלּוּ הוּא רוֹאֶה דֶּרֶךְ זְכוּכִית שֶׁכְּנֶגֶד עֵינָיו. וּמְנַחֵם פֵּרְשׁוֹ לְשׁוֹן רִקָּבוֹן, כְּמוֹ (תהלים לא:יא) ״וַעֲצָמַי עָשֵׁשׁוּ״, וְכֵן כָּל לְשׁוֹן עָשׁ:\",1,0],[2,136,6,8,\"עָתְקָה. נִתְיַשְּׁנָה וְנִזְדַּקְּנָה עֵינִי בִּכְהִיַּת אוֹר, וּמְנַחֵם חִבְּרוֹ עִם ״וַיַּעְתֵּק מִשָּׁם הָהָרָה״ (בראשית יב:ח):\",2,0],[2,136,6,8,\"בְּכָל צוֹרְרָי. בִּשְׁבִיל צָרוֹת שֶׁמְּצִירִין לִי:\",3,0],[2,136,6,11,\"יֵבֹשׁוּ וְיִבָּהֲלוּ וְגוֹ׳. מַהוּ יָשׁוּבוּ יֵבֹשׁוּ פַּעַם שְׁנִיָּה? אָמַר רַבִּי יוֹחָנָן : לֶעָתִיד לָבוֹא הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אֶת הָרְשָׁעִים וּמְחַיְּבָן לַגֵּיהִנֹּם, וְהֵם מִתְרַעֲמִין עָלָיו, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲזִירָן וְחוֹזֵר וּמַרְאֶה גִּלְיוֹנִין שֶׁלָּהֶם וְדָן אוֹתָם וּמִתְחַיְּבִין, וְהוּא מַחֲזִירָן לַגֵּיהִנֹּם. הֲרֵי בּוּשָׁה כְּפוּלָה. רַבִּי שְׁמוּאֵל בַּר נַחְמָנִי אוֹמֵר : לֶעָתִיד לָבֹא כָּל אֻמָּה קוֹרְאָה לֵאלֹהֶיהָ וְאֵין עוֹנֶה, וְחוֹזְרִין וְקוֹרְאִין לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְאוֹמֵר לָהֶם: אִלּוּ אֵלַי קְרָאתֶם תְּחִלָּה, הָיִיתִי עוֹנֶה אֶתְכֶם. עַכְשָׁו עֲשִׂיתֶם עֲבוֹדַת גִּלּוּלִים עִקָּר וְאוֹתִי טְפֵלָה, לְפִיכָךְ אֵינִי עוֹנֶה, שֶׁנֶּאֱמַר ״יִשְׁוְעוּ וְאֵין מוֹשִׁיעַ״ (תהלים יח:מב) – זוֹ עֲבוֹדַת גִּלּוּלִים, וְאַחַר כָּךְ ״אֶל ה׳ וְלֹא עָנָם״ (שם). לְכָךְ נֶאֱמַר: יָשֻׁבוּ יֵבֹשׁוּ:\",1,0],[2,136,6,11,\"רָגַע. בִּמְעַט זְמַן:\",2,0],[2,136,7,1,\"שִׁגָּיוֹן לְדָוִד. מְנַחֵם אָמַר שֶׁגַּם זֶה אֶחָד מִשְּׁמוֹת הַזֶּמֶר עַל שֵׁם הַכְּלִי, וְכֵן פֵּרֵשׁ ״עַל שִׁגְיֹנוֹת״ (חבקוק ג:א), וְרַבּוֹתֵינוּ פֵּרְשׁוּ לְשׁוֹן מִשְׁגֶּה שֶׁנִּתְוַדָּה וְנִתְפַּלֵּל עַל הַשִּׁגָּיוֹן שֶׁאָמַר שִׁירָה עַל מַפַּלְתּוֹ שֶׁל שָׁאוּל כְּמוֹ שֶׁנֶּאֱמַר ״וַיְדַבֵּר דָּוִד לַה׳ וְגוֹ׳״ (שמואל ב כב:א), אֲבָל עִנְיַן הַמִּזְמוֹר אֵינוֹ מוֹכִיחַ עַל כָּךְ. וְאוֹמֵר אֲנִי שֶׁאֲמָרוֹ עַל עִסְקֵי יִשְׁבִּי בְנֹב (שמואל ב כא:טז) שֶׁבָּא עָלָיו עַל עָנְשׁוֹ שֶׁל שָׁאוּל כְּמוֹ שֶׁפֵּרְשׁוּ רַבּוֹתֵינוּ שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יָדְךָ נִטְרַד דּוֹאֵג הָאֲדוֹמִי עַל יָדְךָ נֶהֱרַג שָׁאוּל וּבָנָיו כוּ׳ (כִּדְאִיתָא בְּחֵלֶק שְׁגִיאוֹת שֶׁבִּקֵּשׁ דָּוִד לְהַקָּדוֹשׁ בָּרוּךְ הוּא לְהִמָּסֵר בְּיַד שׂוֹנֵא וְלֹא יִכְלֶה זַרְעוֹ ס״א אינו), וְהָפַךְ דָּוִד אֶת תְּפִלָּתוֹ וְהִתְפַּלֵּל שֶׁלֹּא יִפֹּל בְּיַד אוֹיֵב. וְכֵן פִּתְרוֹנוֹ מִשְׁגֶּה שָׁר דָּוִד לַה׳ עַל שֶׁשָּׁגַג לוֹמַר לְהַקָּדוֹשׁ בָּרוּךְ הוּא לְמָסְרוֹ בְּיַד אוֹיֵב עַל דִּבְרֵי שָׁאוּל שֶׁנֶּהֱרַג עַל יָדוֹ. דָּבָר אַחֵר: עַל שִׁגָּיוֹן כְּנַף הַמְּעִיל אֲשֶׁר כָּרַת לְשָׁאוּל (שמואל א כד:ה):\",1,0],[2,136,7,1,\"כּוּשׁ. מַה כּוּשִׁי מְשֻׁנֶּה בְּעוֹרוֹ, אַף שָׁאוּל מְשֻׁנֶּה בְּמַעֲשָׂיו (מועד קטן טז:):\",2,0],[2,136,7,3,\"פּוֹרֵק. לְשׁוֹן ״פָּרְקוּ נִזְמֵי הַזָּהָב״ (שמות לב:ב):\",1,0],[2,136,7,4,\"אִם עָשִׂיתִי זֹאת. מַה שֶּׁמְפֹרָשׁ אַחֲרָיו:\",1,0],[2,136,7,5,\"אִם גָּמַלְתִּי שׁוֹלְמִי רָע. אִם גְּמַלְתִּיו כִּגְמוּלוֹ:\",1,0],[2,136,7,5,\"וָאֲחַלְּצָה צוֹרְרִי רֵיקָם. שִׁחַתִּי אֶת חֲלִיצָתוֹ בְּכָרְתִּי אֶת כְּנַף מְעִילוֹ, אִם לְהַשְׁחִית וּלְחַלְּצוֹ וּלְהַעֲמִידוֹ רֵיקָם וּבְשִׂנְאָה עָשִׂיתִי? אֶלָּא לְהוֹדִיעוֹ, שֶׁהָיָה מָסוּר בְּיָדִי לְהָרְגוֹ וְלֹא הֲרַגְתִּיו. וָאֲחַלְּצָה לְשׁוֹן הַפְשָׁטָה:\",2,0],[2,136,7,7,\"קוּמָה ה׳ בְּאַפֶּךָ. עַל שׂוֹנְאַי, כְּגוֹן יִשְׁבִּי וְאֶחָיו וּפְלִשְׁתִּים (שמואל ב כא:טז), שֶׁלֹּא אֶמָּסֵר בְּיָדָם:\",1,0],[2,136,7,7,\"הִנָּשֵׂא. הִתְפָּאֵר לְהַרְאוֹת נִקְמַת עֶבְרָה בְּהִתְעַבֶּרְךָ עֲלֵיהֶם:\",2,0],[2,136,7,7,\"וְעוּרָה אֵלַי. שֶׁאוּכַל לַעֲשׂוֹת בָּהֶם מִשְׁפָּט נְקָמָה אֲשֶׁר צִוִּיתָ, וְהֵיכָן צִוִּיתָ? ״תְּרֹעֵם בְּשֵׁבֶט בַּרְזֶל״ (תהלים ב:ט), ״וְאָיַבְתִּי אֶת אֹיְבֶיךָ״ (שמות כג:כב). זֶה מָצָאתִי בַמִּדְרָשׁ:\",3,0],[2,136,7,8,\"וַעֲדַת לְאֻמִּים תְּסוֹבְבֶךָּ. אִם יַחְזְרוּ אַחֲרֶיךָ לְהוֹשִׁיעָם אַל תִּשְׁמַע לְקוֹלָם, הִתְרַחֵק מֵעֲלֵיהֶם וְשׁוּב וְשֵׁב בִּמְקוֹמְךָ בַּמָּרוֹם רפיש״א בְּלַעַ״ז. דָּבָר אַחֵר: לַמָּרוֹם שׁוּבָה לְהַרְאוֹת לָהֶם שֶׁיָּדְךָ עֶלְיוֹנָה:\",1,0],[2,136,7,9,\"ה׳ יָדִין עַמִּים. הֲפוֹךְ הַדִּין מֵעָלֵינוּ וּתְנֵהוּ עַל הָרְשָׁעִים:\",1,0],[2,136,7,9,\"יָדִין. לְשׁוֹן יִסּוּרִין:\",2,0],[2,136,7,9,\"שָׁפְטֵנִי ה׳ כְּצִדְקִי. שְׁפוֹט לְפִי מַעֲשִׂים טוֹבִים שֶׁבְּיָדָם וְלֹא לְפִי הָעֲבֵירוֹת:\",3,0],[2,136,7,10,\"יִגְמָר. לְשׁוֹן כִּלָּיוֹן, וְכֵן פָּתַר מְנַחֵם ״גָּמַר אֹמֶר״ (תהלים עז:ט), ״גָּמַר חָסִיד״ (תהלים יב:ב), וְכֵן כֻּלָּם (ס״א אינו):\",1,0],[2,136,7,10,\"וּתְכוֹנֵן צַדִּיק וּבֹחֵן לִבּוֹת. אַתָּה יוֹדֵעַ מִי הוּא הַצַּדִּיק שֶׁתְּכוֹנְנֵהוּ:\",2,0],[2,136,7,10,\"אֱלֹהִים צַדִּיק. כֵּן שְׁמֶךָ:\",3,0],[2,136,7,12,\"שׁוֹפֵט צַדִּיק. אַתָּה לִשְׁפּוֹט צֶדֶק:\",1,0],[2,136,7,12,\"זוֹעֵם בְּכָל יוֹם. כְּשֶׁרוֹאֶה אֶת מַעֲשֵׂה הָרְשָׁעִים:\",2,0],[2,136,7,13,\"אִם לֹא יָשׁוּב. הָרָשָׁע מֵרִשְׁעוֹ:\",1,0],[2,136,7,13,\"חַרְבּוֹ יִלְטוֹשׁ. הַקָּדוֹשׁ בָּרוּךְ הוּא עָלָיו יִלְטוֹשׁ, פוֹרְבִּירָ״א בְּלַעַ״ז, וְיִדְרֹךְ קַשְׁתּוֹ:\",2,0],[2,136,7,14,\"וְלוֹ. וְלָרָשָׁע הֵכִין הַקָּדוֹשׁ בָּרוּךְ הוּא כְּלֵי מָוֶת:\",1,0],[2,136,7,14,\"לְדֹלְקִים. לְרוֹדְפִים, כְּמוֹ ״כִּי דָלַקְתָּ אַחֲרָי״ (בראשית לא:לו). וְכֵן פֵּרוּשׁוֹ: חִצָּיו לַהֲרֹג אֶת הָרְשָׁעִים הַדּוֹלְקִים אֶת הַצַּדִּיקִים יִפְעַל הַקָּדוֹשׁ בָּרוּךְ הוּא וְיַזְמִינֵם לַהֲמִיתָם. כָּל דְּלִיקָה לְשׁוֹן רְדִיפָה הִיא:\",2,0],[2,136,7,15,\"יְחַבֶּל. לְשׁוֹן הֵרָיוֹן וְלֵידָה, כְּמוֹ ״שָׁמָּה חִבְּלַתְךָ אִמֶּךָ״ (שיר השירים ח:ה):\",1,0],[2,136,7,15,\"וְהָרָה עָמָל וְיָלַד שָׁקֶר. כָּל מַה שֶּׁהוּא מוֹלִיד וְיָגֵעַ – הַכֹּל מְשַׁקֵּר בּוֹ, שֶׁאֵינוֹ מִתְקַיֵּם בְּיָדוֹ; מַתְלָא אָמַר : כָּל מַה דְּשִׁקְרָא מוֹלִיד, פַּחְתָּא נָסְבָא:\",2,0],[2,136,7,18,\"אוֹדֶה ה׳ כְּצִדְקוֹ. כְּשֶׁיַּצְדִּיק הַדִּין הַגָּמוּר לִשְׁפּוֹט הָרְשָׁעִים כְּרִשְׁעָם:\",1,0],[2,136,8,1,\"הַגִּתִּית. כְּלִי זֶמֶר שֶׁבָּא מִגַּת, שָׁם מְצוּיִים אוּמָּנִים לַעֲשׂוֹתָם. וְרַבּוֹתֵינוּ אָמְרוּ (בראשית רבה טז,ד): עַל אֱדוֹם שֶׁעֲתִידָה לִידָּרֵךְ כְּגַת, כְּמוֹ שֶׁנֶּאֱמַר ״פּוּרָה דָּרַכְתִּי לְבַדִּי״ (ישעיה סג:ג); אַךְ עִנְיַן הַמִּזְמוֹר אֵינוֹ מוֹכִיחַ:\",1,0],[2,136,8,2,\"מָה אַדִּיר שִׁמְךָ. יוֹתֵר מִכְּדֵי כֹּחַ מִדַּת הַתַּחְתּוֹנִים, לֹא הָיוּ הַתַּחְתּוֹנִים כְּדַאי שֶׁתִּשְׁרֶה שְׁכִינָתְךָ בֵּינֵיהֶם:\",1,0],[2,136,8,2,\"אֲשֶׁר תְּנָה הוֹדְךָ עַל הַשָּׁמָיִם. רָאוּי שֶׁתִּתְּנֵהוּ עַל הַשָּׁמַיִם, וְאַתָּה בַּעֲנָוָתְךָ הַגְּדוֹלָה יִסַּדְתָּ עֹז וְגוֹמֵר:\",2,0],[2,136,8,3,\"יִסַּדְתָּ עֹז מִפִּי עוֹלְלִים וְיוֹנְקִים. הִשְׁרֵיתָ שְׁכִינָתְךָ בַּמִּקְדָּשׁ, וְתִקַּנְתָּ לְהוֹדוֹת לְךָ עֹז מִפִּי הַלְוִיִּם וְהַכֹּהֲנִים, שֶׁהֵם בְּנֵי אָדָם גְּדֵלִים בְּלִכְלוּךְ, כְּעוֹלְלִים וְיוֹנְקֵי שָׁדַיִם. עוֹלְלִים לְשׁוֹן ״וְעוֹלַלְתִּי בֶעָפָר קַרְנִי״ (איוב טז:טו), וְעַל שֵׁם הַלִּכְלוּךְ נִקְרְאוּ כָּל תִּינוֹקוֹת עוֹלְלִים:\",1,0],[2,136,8,3,\"לְמַעַן צוֹרְרֶיךָ. לְהוֹדִיעָם כִּי עַמְּךָ אֲנַחְנוּ:\",2,0],[2,136,8,3,\"לְהַשְׁבִּית. חֶרְפַּת אוֹיֵב וּמִתְנַקֵּם, הָאוֹמֵר: לֹא טוֹבִים אַתֶּם מֵהָאֻמּוֹת. וַאֲנִי, כְּשֶׁאֲנִי רוֹאֶה שָׁמֶיךָ וְגוֹמֵר, אֲנִי תָּמֵהַּ בְּלִבִּי: מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ:\",3,0],[2,136,8,6,\"וַתְּחַסְּרֵהוּ מְעַט מֵאֱלֹהִים וְגוֹמֵר. מֵאֱלֹהִים לְשׁוֹן מַלְאָכִים, שֶׁנָּתַתָּ כֹּחַ בִּיהוֹשֻׁעַ לְהַדְמִים הַחַמָּה וּלְיַבֵּשׁ אֶת הַיַּרְדֵּן, בְּמֹשֶׁה לִקְרֹעַ מֵי יַם סוּף וְלַעֲלוֹת לַמָּרוֹם, וּבְאֵלִיָּהוּ לְהַחֲיוֹת אֶת הַמֵּת:\",1,0],[2,136,8,8,\"צֹנֶה וַאֲלָפִים. צֹאן וּבָקָר, כְּמוֹ (דברים ז:יג) ״שְׁגַר אֲלָפֶיךָ״. צֹנֶה לְשׁוֹן פְּעֻלָּה הוּא, כְּמוֹ ״וּגְדֵרֹת לְצֹנַאֲכֶם״ (במדבר לב:כד), אוביילדי״ץ בְּלַעַ״ז. יֵשׁ מִדְרְשֵׁי אַגָּדָה וְאֵינָם מִתְיַשְּׁבִין לְפִי הַמִּקְרָאוֹת:\",1,0],[2,136,9,1,\"עַלמוּת לַבֵּן. יֵשׁ פּוֹתְרִין עַל מוּת לַבֵּן עַל מֵת בְּנוֹ אַבְשָׁלוֹם, וְלֹא יִתָּכֵן פִּתְרוֹנוֹ מִפְּנֵי אוֹמֵר לַבֵּן וְלֹא אָמַר הַבֵּן, וְאֵין לוֹ בַּמִּזְמוֹר עֵדוּת וְזִכָּרוֹן לְאַמֵּץ זֶה הַפִּתְרוֹן. וְיֵשׁ פּוֹתְרִין עַל מוּת לַבֵּן נָבָל וְאַף זֶה לֹא יִתָּכֵן לַהֲפֹךְ אֶת הַשֵּׁם וְאֵין בַּמִּזְמוֹר זִכְרוֹנוֹ (ס״א אינו). וְרָאִיתִי בַּמְּסוֹרָה הַגְּדוֹלָה שֶׁהִיא תֵּבָה אַחַת שֶׁהֲרֵי חָבֵר לָהּ ״וְהוּא יְנַהֲגֵנוּ עַלְמוּת״ (תהלים מח:טו). פָּתְרוּ מְנַחֵם וְדוּנַשׁ מַה שֶּׁפֵּתְרוּ וְאֵינוֹ נִרְאֶה בְּעֵינַי. וְרָאִיתִי בִּפְסִיקְתָּא שֶׁהָעִנְיָן מְדַבֵּר בַּעֲמָלֵק גָּעַרְתָּ גוֹיִם שִׁמַּם מָחִיתָ. וְאוֹמֵר אֲנִי לַמְנַצֵּחַ עַלְמוּת לַבֵּן שִׁיר זֶה לֶעָתִיד לָבֹא כְּשֶׁיִּתְלַבֵּן יַלְדוּתָן וְשַׁחֲרוּתָן שֶׁל יִשְׂרָאֵל וְתִגָּלֶה צִדְקָתָם וְתִקְרַב יְשׁוּעָתָם שֶׁיִּמָּחֶה עֲמָלֵק וְזַרְעוֹ, עֲלָמוֹת יַלְדוּת, לַבֵּן כְּמוֹ לְלַבֵּן. וּמְנַחֵם פָּתַר עַלְמוּת לַבֵּן, נְגִינוֹת לְלַמֵּד, וְכֹה פִּתְרוֹנוֹ לַמְנַצֵּחַ עַל מוּת לַבֵּן לַמְשׁוֹרֵר נְגִינוֹת לְלַמֵּד, וִיהִי לַבֵּן כְּמוֹ לְהָבִין וּלְבוֹנֵן, עַלְמוּת עַל שֵׁם כְּלִי שִׁיר שֶׁשְּׁמוֹ עֲלָמוֹת כְּמוֹ שֶׁאָמַר ״עַל עֲלָמוֹת שִׁיר״ (תהלים מו:א). וְדוּנַשׁ פָּתַר לַבֵּן שֵׁם אָדָם שֶׁהָיָה שְׁמוֹ לַבֵּן שֶׁהָיָה נִלְחָם בְּדָוִד בַּיָּמִים הָהֵם, וּמַה שֶׁהוּא אוֹמֵר גָּעַרְתָּ גוֹיִם אִבַּדְתָּ רָשָׁע הָרָשָׁע הַזֶּה הוּא לַבֵּן הַהוֹרֵג עַם נְקִיִּים, וְאַף עַל פִּי שֶׁאֵין אַתָּה רוֹאֶה בְּמָקוֹם אַחֵר אָדָם שֶׁהָיָה שְׁמוֹ לַבֵּן רַק בַּמָּקוֹם הַזֶּה, כֵּן אַתָּה מוֹצֵא בִּשְׁמוֹת אֲחֵרִים שֶׁאֵינָן נִכְתָּבִים בַּמִּקְרָא רַק פַּעַם אַחַת:\",1,0],[2,136,9,2,\"כָּל נִפְלְאוֹתֶיךָ. גְּאֻלָּה הָאַחֲרוֹנָה שֶׁשְּׁקוּלָה כְּנֶגֶד כָּל הַנִּסִּים, כְּמוֹ שֶׁנֶּאֱמַר (ירמיהו טז:יד) ״לֹא יֵאָמֵר עוֹד חַי ה׳ אֲשֶׁר הֶעֱלָה וְגוֹמֵר״:\",1,0],[2,136,9,5,\"מִשְׁפָּטִי וְדִינִי. תֵּיבוֹת כְּפוּלוֹת בַּמִּקְרָא וְאֵין חִילּוּק בֵּינֵיהֶם, כְּמוֹ ״עֵדִי וְסַהֲדִי בַּמְּרוֹמִים״ (איוב טז:יט), ״עֲצָמָיו אֲפִיקֵי נְחוּשָׁה גְּרָמָיו כִּמְטִיל בַּרְזֶל״ (איוב מ:יח):\",1,0],[2,136,9,5,\"מִשְׁפָּטִי וְדִינִי. בַּשָּׁמַיִם:\",2,0],[2,136,9,5,\"יָשַׁבְתָּ לְכִסֵּא. כִּסֵּא הַמִּשְׁפָּט:\",3,0],[2,136,9,6,\"גָּעַרְתָּ גוֹיִם. עֲמָלֵק, ״רֵאשִׁית גּוֹיִם״ (במדבר כד:כ):\",1,0],[2,136,9,6,\"אִבַּדְתָּ רָשָׁע. אֲבוֹתָיו:\",2,0],[2,136,9,6,\"שְׁמָם מָחִיתָ. ״כִּי מָחֹה אֶמְחֶה״ (שמות יז:יד):\",3,0],[2,136,9,7,\"הָאוֹיֵב תַּמּוּ. כִּי חֳרָבוֹת הַשִּׂנְאָה לָנֶצַח הֵם עָלָיו כְּחֶרֶב חַדָּה. דָּבָר אַחֵר: חֳרָבוֹת לָנֶצַח – אוֹתוֹ אוֹיֵב שֶׁחֳרָבוֹת שִׂנְאָתוֹ הָיְתָה עָלֵינוּ לָנֶצַח, וְזֶהוּ עֲמָלֵק שֶׁנֶּאֱמַר בּוֹ ״וְעֶבְרָתוֹ שָׁמְרָה נֶצַח״ (עמוס א:יא). לָשׁוֹן אַחֵר: חֳרָבוֹת – לְשׁוֹן חֻרְבָּן, וְכֵן פִּתְרוֹנוֹ: הָאוֹיֵב תַּמּוּ חֳרָבוֹת לָנֶצַח, וְכֵן נֶאֱמַר ״שִׁמְמוֹת עוֹלָם אֶתֶּנְךָ וְעָרֶיךָ לֹא תָשֻׁבְנָה״ (יחזקאל לה:ט):\",1,0],[2,136,9,7,\"וְעָרִים נָתַשְׁתָּ. ״כִּי תֹאמַר אֱדוֹם רֻשַּׁשְׁנוּ וְנָשׁוּב וְנִבְנֶה חֳרָבוֹת כֹּה אָמַר ה׳ צְבָאוֹת הֵמָּה יִבְנוּ וַאֲנִי אֶהֱרוֹס״ (מלאכי א:ד):\",2,0],[2,136,9,7,\"אָבַד זִכְרָם. אוֹתָהּ הַשָּׁעָה:\",3,0],[2,136,9,8,\"וַה׳ לְעוֹלָם יֵשֵׁב וְגוֹ׳. שֵׁם שָׁלֵם וְכִסֵּא שָׁלֵם, כְּמוֹ שֶׁנֶּאֱמַר: כִּסְאוֹ; אֲבָל קוֹדֶם שֶׁיִּמָּחֶה כְּתִיב ״כִּי יָד עַל כֵּס יָהּ״ (שמות יז:טז) – כֵּס חָסֵר וְשֵׁם חָלוּק:\",1,0],[2,136,9,9,\"וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק יָדִין לְאֻמִּים בְּמֵישָׁרִים. עַד בֹּא הַקֵּץ הָיָה רָגִיל לְשָׁפְטָם בְּרַחֲמִים, לְפִי מֵישָׁרִים הַמְצוּוִין בָּהֶם. דָּן אוֹתָם בַּלַּיְלָה, כְּשֶׁהֵם יְשֵׁנִים מִן הָעֲבֵירוֹת:\",1,0],[2,136,9,10,\"וִיהִי ה׳ מִשְׂגָּב לַדָּךְ. לְשׁוֹן ״דַּכָּא״ (תהלים צ:ג), אִילָאמִינְשִׁי״ה בְּלַעַ״ז. לֶעָתִיד, כְּשֶׁיְּכוֹנֵן לְמִשְׁפָּט כִּסְאוֹ, יְהִי מִשְׂגָּב לְיִשְׂרָאֵל, שֶׁהֵם דַּכִּים:\",1,0],[2,136,9,10,\"לְעִתּוֹת בַּצָּרָה. עִתִּים שֶׁל צָרָה:\",2,0],[2,136,9,12,\"זַמְּרוּ לַה׳ יוֹשֵׁב צִיּוֹן. כְּשֶׁיַּחֲזִיר יְשִׁיבָתוֹ לְצִיּוֹן יְזַמְּרוּ לוֹ כֵּן:\",1,0],[2,136,9,13,\"אוֹתָם זָכָר. אֶת הַדָּמִים שֶׁנִּשְׁפְּכוּ בְּיִשְׂרָאֵל:\",1,0],[2,136,9,14,\"חָנְנֵנִי ה׳. עַתָּה בַּגּוֹלָה:\",1,0],[2,136,9,14,\"מְרוֹמְמִי. בִּגְאֻלָּתְךָ:\",2,0],[2,136,9,16,\"טָבְעוּ גוֹיִם. זוֹ הִיא הַתְּהִלָּה אֲשֶׁר אֲסַפֵּר:\",1,0],[2,136,9,17,\"נוֹדַע ה׳. כָּל זֶה מִן הַתְּהִלָּה, נוֹדַע ה׳ לַבְּרִיּוֹת כִּי שַׁלִּיט הוּא וּמוֹשֵׁל וְנוֹקֵם לְאוֹיְבָיו, שֶׁהֲרֵי מִשְׁפָּט עָשָׂה בָּהֶם. יוּשְׁטִיצָ״א בְּלַעַ״ז:\",1,0],[2,136,9,17,\"נוֹקֵשׁ רָשָׁע. נִכְשַׁל רָשָׁע:\",2,0],[2,136,9,17,\"הִגָּיוֹן. נֶהְגֶּה זֹאת סֶלָה:\",3,0],[2,136,9,18,\"לִשְׁאוֹלָה. אָמַר רַבִּי נְחֶמְיָה (יבמות יג:): כָּל תֵּיבָה הַצְּרִיכָה לָמֶ״ד בִּתְחִלָּתָהּ, הִטִּיל לָהּ הֵ״א בְּסוֹפָהּ, כְּגוֹן ״מִצְרַיְמָה״(בראשית יב:י) ״מִדְבָּרָה״ (מלכים א יט:טו). הֵתִיבוּן לֵיהּ: וְהָכְתִיב יָשׁוּבוּ רְשָׁעִים לִשְׁאוֹלָה? אָמַר רַבִּי אַבָּא בַּר זַבְדִּי: לַמַּדְרֵגָה הַתַּחְתּוֹנָה שֶׁל שְׁאוֹל. וּמַהוּ יָשׁוּבוּ? לְאַחַר שֶׁיֵּצְאוּ מִגֵּיהִנֹּם וְיַעַמְדוּ בַדִּין וְיִתְחַיְּבוּ, יָשׁוּבוּ לַמַּדְרֵגָה תַּחְתִּית שֶׁל גֵּיהִנֹּם:\",1,0],[2,136,9,19,\"כִּי לֹא לָנֶצַח יִשָּׁכַח. יִשְׂרָאֵל הָאֶבְיוֹן מִלִּפְקוֹד עֲלֵיהֶם מַה שֶּׁשִּׁעְבְּדוּ בוֹ, וְתִקְוַת עֲנִיִּים לֹא תֹאבַד לָעַד:\",1,0],[2,136,9,20,\"קוּמָה ה׳. דָּוִד הָיָה מִתְפַּלֵּל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁיָּקוּם וִימַהֵר לַעֲשׂוֹת זֹאת:\",1,0],[2,136,9,20,\"אַל יָעֹז. עֲמָלֵק לְאֹרֶךְ יָמִים בִּגְדֻלָּתוֹ:\",2,0],[2,136,9,20,\"עַל פָּנֶיךָ. בִּשְׁבִיל הַכַּעַס שֶׁהִכְעִיסוּךָ בְּמִקְדָּשֶׁךָ:\",3,0],[2,136,9,21,\"מוֹרָה. מָרוּת וְעוֹל. דָּבָר אַחֵר: מוֹרָה לְשׁוֹן הַשְׁלָכָה, לְשׁוֹן ״יָרָה בַיָּם״ (שמות טו:ד). וְיֵשׁ אוֹמְרִים: מוֹרָה לְשׁוֹן תַּעַר (ס״א אינו):\",1,0],[2,136,9,21,\"יֵדְעוּ גוֹיִם. שֶׁהֵם אֱנוֹשׁ, וְלֹא אֱלֹהוּת לִהְיוֹת גְּבוּרָתָם שׁוֹלֶטֶת:\",2,0],[2,136,10,1,\"תַּעְלִים לְעִתּוֹת בַּצָּרָה. תַּעְלִים עֵינַיִם לְעִתּוֹת הַצָּרָה:\",1,0],[2,136,10,2,\"יִדְלַק. יִרְדֹּף, כְּמוֹ ״כִּי דָלַקְתָּ אַחֲרָי״ (בראשית לא:לו):\",1,0],[2,136,10,2,\"יִתָּפְשׂוּ בִּמְזִמּוֹת זוּ חָשָׁבוּ. נִתְפָּסִים הֵם הָעֲנִיִּים בִּמְזִמּוֹת שֶׁהָרְשָׁעִים חוֹשְׁבִים עֲלֵיהֶם:\",2,0],[2,136,10,3,\"כִּי הִלֵּל רָשָׁע. מוּסָב עַל לָמָּה ה׳ תַּעֲמֹד בְּרָחוֹק, כִּי עַתָּה עֲמָלֵק הָרָשָׁע מִתְהַלֵּל שֶׁמַּשִּׂיג כָּל תַּאֲוַת נַפְשׁוֹ:\",1,0],[2,136,10,3,\"וּבוֹצֵעַ בֵּרֵךְ נִאֵץ ה׳. וְהַגַּזְלָן שִׁבַּח אֶת עַצְמוֹ לֵאמֹר: נִאֵץ ה׳, וְשָׁלוֹם יִהְיֶה לִי (דברים כט:יח):\",2,0],[2,136,10,3,\"בֵּרֵךְ. כְּמוֹ בֵּרַךְ, לְשׁוֹן פִּעֵל. וְתֵדַע, שֶׁאִלּוּ הָיָה שֵׁם דָּבָר, הָיָה הַטַּעַם לְמַעְלָה בָּאוֹת הָרִאשׁוֹנָה, וְהָיָה נָקוּד פַּתַּח, וְזֶה נָקוּד קָמַץ קָטָן וְטַעֲמוֹ לְמַטָּה בָּרֵי״שׁ. וְאַל תִּתְמַהּ עַל בֵּרֵךְ שֶׁלֹּא אָמַר בֵּרַךְ, שֶׁהַרְבֵּה תֵּבוֹת שֶׁל רֵי״שׁ מְשַׁמְּשׁוֹת כָּךְ, כְּגוֹן ״אוֹיֵב חֵרֵף ה׳״ (תהלים עד:יח), וְלֹא נֶאֱמַר חֵרַף:\",3,0],[2,136,10,3,\"נִאֵץ. כְּמוֹ חֵרֵף, וְכֵן כָּל לְשׁוֹן נִיאוּץ. כָּךְ פָּתַר מְנַחֵם:\",4,0],[2,136,10,4,\"רָשָׁע כְּגֹבַהּ אַפּוֹ. שֶׁהוּא גְּבַהּ רוּחַ, וּמַגְבִּיהַּ וְזוֹקֵף פָּנָיו וְאַפּוֹ בְּגַבְהוּתוֹ:\",1,0],[2,136,10,4,\"בַּל יִדְרֹשׁ. כָּל מְזִמּוֹתָיו אוֹמְרוֹת לוֹ: בַּל יִדְרֹשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל מַה שֶּׁאֶעֱשֶׂה, כִּי אֵין מִשְׁפָּט:\",2,0],[2,136,10,4,\"אֵין אֱלֹהִים. לֵית דִּין וְלֵית דַּיָּן (שבת קנה.):\",3,0],[2,136,10,5,\"יָחִילוּ. יַצְלִיחוּ, וְדוֹמֶה לוֹ (איוב כ:כא) ״עַל כֵּן לֹא יָחִיל טוּבוֹ״. וְיֵשׁ מְפָרְשִׁים יָחִילוּ כְּמוֹ (שמואל ב ג:כט) ״יָחֻלוּ עַל רֹאשׁ יוֹאָב״:\",1,0],[2,136,10,5,\"מָרוֹם מִשְׁפָּטֶיךָ מִנֶּגְדּוֹ. מְסֻלָּקִים וּמְרֻחָקִים מִשְׁפְּטֵי יִסּוּרִין וּפוּרְעָנִיּוֹת שֶׁלְּךָ מִנֶּגְדּוֹ, שֶׁאֵינָם בָּאִים עָלָיו:\",2,0],[2,136,10,5,\"כָּל צוֹרְרָיו יָפִיחַ בָּהֶם. בְּהַפָּחַת רוּחַ הוּא מֵפִיחַ בָּהֶם, וְהֵם נוֹפְלִים לְפָנָיו:\",3,0],[2,136,10,6,\"לְדוֹר וָדוֹר אֲשֶׁר לֹא בְרָע. לֹא תָבֹא עָלַי רָעָה לְדוֹרוֹתַי:\",1,0],[2,136,10,7,\"וְתֹךְ. לְשׁוֹן מַחֲשָׁבָה רָעָה הַלָּנָה בְּתוֹכוֹ תָּמִיד:\",1,0],[2,136,10,8,\"עֵינָיו לְחֵלְכָה יִצְפֹּנוּ. עֵינָיו שֶׁל עֲמָלֵק לְיִשְׂרָאֵל, שֶׁהֵם חֵילְךָ, יֶאֱרֹבוּ:\",1,0],[2,136,10,8,\"לְחֵלְכָה. עָלֶיךָ יַעֲזֹב חֵלְכָה, שְׁנֵיהֶם בַּמְּסוֹרֶת מִן מִלִּין הַמְשַׁמְּשִׁין כָּה בִּמְקוֹם ךָ, כְּגוֹן (שמות ז:כט) ״וּבְכָה וּבְעַמְּךָ״ (משלי ב:יא) ״תְּבוּנָה תִנְצְּרֶכָּה״ (שמות כט:לה) ״כָּל אֲשֶׁר צִוִּיתִי אֹתְכָה״ (שמואל א א:כו) ״הַנִּצֶּבֶת עִמְּכָה״. לָמַדְנוּ מִמְּסוֹרֶת שֶׁחֵלְכָה כְּמוֹ חֵילְךָ חֵיל שֶׁלְּךָ, וּמְנַחֵם פָּתַר אוֹתָהּ לְחֵלְכָה יִצְפֹּנוּ וְכֵן יַעֲזֹב חֵלְכָה כְּמוֹ וְנָפַל בַּעֲצוּמָיו חֵלְכָאִים עִנְיַן נְמוּכִים וּמְרוּדִים, וְכָה יְסוֹד הַמִּלָּה:\",2,0],[2,136,10,10,\"יִדְכֶּה יָשׁוֹחַ. כָּךְ דֶּרֶךְ הָאוֹרֵב, שֶׁמְּדַכֶּה וּמַשְׁפִּיל וּמַקְטִין עַצְמוֹ, כְּדֵי שֶׁלֹּא יְהֵא נִכָּר:\",1,0],[2,136,10,10,\"וְנָפַל בַּעֲצוּמָיו חֵלְכָּאִים. חֵיל נִשְׁבָּרִים. רָאִיתִי בַּמְּסוֹרָה הַגְּדוֹלָה חֵלְכָּאִים אַחַת מֵחֲמֵשׁ עֶשְׂרֵה תֵּיבוֹת הַכְּתוּבוֹת תֵּיבָה אַחַת וְנִקְרָאוֹת שְׁתֵּי תֵיבוֹת, וּכְמוֹ ״וַתֹּאמֶר לֵאָה בָּגָד״ (בראשית ל:יא) ״אֵשְׁדָּת לָמוֹ״ (דברים לג:ב) ״מַלְכֶּם תְּדַכְּאוּ עַמִּי״ (ישעיה ג:טו). אַף זֶה חֵלְכָּאִים, חֵיל שֶׁל נִשְׁבָּרִים, כָּאִים לְשׁוֹן ״וְנִכְאֵה לֵבָב לְמוֹתֵת״ (תהלים קט:טז) וְאִם תֹּאמַר הַנּוּ״ן מִן הַשֹּׁרֶשׁ יוֹכִיחַ עָלָיו ״יַעַן הַכְּאוֹת לֵב צַדִּיק״ (יחזקאל יג:כב) לָמַדְנוּ הַנּוּ״ן שֶׁל נִכְאֶה כְּנוּ״ן שֶׁל ״נִמְבְזֶה״ (שמואל א טו:ט) וְנוּ״ן שֶׁל נִקְלֶה וְכֵן פִּתְרוֹנוֹ וְנָפַל בַּעֲצוּמָיו שֶׁל רָשָׁע זֶה בִּרְמִיזוֹתָיו וּבִקְרִיצוֹתָיו לְשׁוֹן ״הַגִּישׁוּ עַצְמוֹתֵיכֶם״ (ישעיה מא:כא) ״עֹצֵם עֵינָיו״ (ישעיה לג:טו), חֵיל שֶׁל עֲנִיִּים. דָּבָר אַחֵר בַּעֲצוּמָיו עַל יְדֵי גִבּוֹרָיו, אָמַר רַבִּי סִימוֹן אֵין הָרָשָׁע הַזֶּה מֵטִיל בַּקְּלִירוֹס שֶׁלּוֹ פֵּרוּשׁ חֵיל אֶלָּא גִבּוֹרִים כְּמוֹתוֹ, שֶׁנֶּאֱמַר ״וּלְגֻבְרִין גִּבָּרֵי חַיִל דִּי בְחֵילֵהּ אֲמַר לְכַפָּתָה לְשַׁדְרַךְ מֵישַׁךְ וַעֲבֵד נְגוֹ״ (דניאל ג:כ). וּמְנַחֵם פָּתַר חֵלְכָּאִים כְּמוֹ דַּל וְחֵלֶךְ וְהַכָּ״ף יְסוֹד בַּתֵּיבָה:\",2,0],[2,136,10,13,\"עַל מֶה נִאֵץ רָשָׁע. לְהַקָּדוֹשׁ בָּרוּךְ הוּא, לְפִי שֶׁאָמַר בְּלִבּוֹ לֹא תִדְרֹשׁ:\",1,0],[2,136,10,14,\"רָאִיתָה. מַה שֶּׁהוּא עוֹשֶׂה וְאַתָּה מַחֲרִישׁ:\",1,0],[2,136,10,14,\"כִּי אַתָּה. כֵּן דַּרְכְּךָ, שֶׁתַּבִּיט עָמָל וָכַעַס:\",2,0],[2,136,10,14,\"לָתֵת בְּיָדֶךָ. בְּכֹחֲךָ אַתָּה נוֹתֵן יָד לָרְשָׁעִים לְהַצְלִיחַ בְּרִשְׁעָם:\",3,0],[2,136,10,14,\"עָלֶיךָ יַעֲזֹב חֵלֵכָה. יִשְׂרָאֵל עַמְּךָ, שֶׁהֵם חֵילְךָ, הֵם עוֹזְבִים עָלֶיךָ אֶת הַמַּשָּׂא שֶׁתַּעֲשֶׂה דִּין בָּרְשָׁעִים. וּמְנַחֵם פֵּתַר יַעֲזֹב לְשׁוֹן עֶזְרָה כְּמוֹ ״עָזֹב תַּעֲזֹב עִמּוֹ״ (שמות כג:ה), וּמְנַחֵם פֵּתַר חֵלְכָה לְשׁוֹן דַּל וְחֵלֶךְ וְכ׳ יְסוֹד בַּתֵּיבָה:\",4,0],[2,136,10,14,\"יָתוֹם אַתָּה הָיִיתָ עוֹזֵר. בְּיָמִים רִאשׁוֹנִים:\",5,0],[2,136,10,15,\"שְׁבֹר זְרוֹעַ. שֶׁל עֲמָלֵק הָרָשָׁע:\",1,0],[2,136,10,15,\"וְרָע תִּדְרוֹשׁ רִשְׁעוֹ בַּל תִּמְצָא. פּוֹשְׁעֵי יִשְׂרָאֵל, כְּשֶׁרוֹאִין אֶת הָרְשָׁעִים מַצְלִיחִין, לִבָּם נוֹשְׂאָם לְהַרְשִׁיעַ. אֲבָל מִשֶּׁתִּשְׁבֹּר אֶת זְרוֹעַ הָרְשָׁעִים, אִם בָּאתָ לִדְרוֹשׁ רִשְׁעָם שֶׁל רִשְׁעֵי יִשְׂרָאֵל, לֹא תִמְצָאֶנּוּ:\",2,0],[2,136,10,16,\"ה׳ מֶלֶךְ עוֹלָם וָעֶד. מֵאַחַר שֶׁיֹּאבְדוּ גוֹיִם מֵאַרְצוֹ:\",1,0],[2,136,10,18,\"לִשְׁפֹּט יָתוֹם. לַעֲשׂוֹת מִשְׁפָּטָם שֶׁל יִשְׂרָאֵל, הַיְתוֹמִים וְדַכִּים:\",1,0],[2,136,10,18,\"בַּל יוֹסִיף עוֹד. עֵשָׂו:\",2,0],[2,136,10,18,\"לַעֲרֹץ אֱנוֹשׁ. לְכַתֵּת וְלִשְׁבֹּר אֶת הָאֲנוּשִׁים וְחוֹלִים:\",3,0],[2,136,11,1,\"אֵיךְ תֹּאמְרוּ לְנַפְשִׁי נוּדִי וְגוֹ׳. זֶהוּ דֻּגְמַת ״כִּי גֵרְשׁוּנִי הַיּוֹם מֵהִסְתַּפֵּחַ בְּנַחֲלַת ה׳״ (שמואל א כו:יט), שֶׁגֵּרְשׁוּהוּ מֵאֶרֶץ לְחוּצָה לָאָרֶץ. וְכָאן הוּא אוֹמֵר: בַּה׳ חָסִיתִי, שֶׁיַּחֲזִירֵנִי לְהִסְתַּפֵּחַ בְּנַחֲלָתִי. אֵיךְ תֹּאמְרוּ אַתֶּם טוֹרְדִים לְנַפְשִׁי נוּדִי הַרְכֶם עֲבוֹר הַר שֶׁלָּכֶם אַתָּה צִפּוֹר הַנּוֹדֵד, שֶׁכָּל אָדָם הַמִּטַּלְטֵל נִמְשָׁל לְצִפּוֹר הַנּוֹדֶדֶת מִן קִנָּהּ, כְּדִכְתִיב ״כְּצִפּוֹר נוֹדֶדֶת מִן קִנָּהּ כֵּן אִישׁ נוֹדֵד מִמְּקוֹמוֹ״ (משלי כז:ח), שֶׁנָּדַד קִנֶּךָ שֶׁטְּרַדְנוּךָ מִכָּל הָהָר כְּצִפּוֹר הַנּוֹדֶדֶת. נוּדוּ כְּתִיב, שֶׁהוּא נִדְרָשׁ אַף בְּיִשְׂרָאֵל, שֶׁהָאֻמּוֹת אוֹמְרִים לָהֶם כֵּן:\",1,0],[2,136,11,2,\"כִּי הִנֵּה הָרְשָׁעִים. דּוֹאֵג וְדִילָטוֹרֵי הַדּוֹר, הַמְּטִילִין אֵיבָה בֵּינִי וּבֵין שָׁאוּל (דברים רבה ה:י):\",1,0],[2,136,11,2,\"יִדְרְכוּן. לְשׁוֹן דְּרִיכָה נוֹפֵל בְּקֶשֶׁת, שֶׁכְּשֶׁהוּא חָזָק, צָרִיךְ לִיתֵּן רַגְלוֹ עָלָיו כְּשֶׁרוֹצֶה לִנְטוֹתוֹ:\",2,0],[2,136,11,2,\"קֶשֶׁת. לְשׁוֹנָם יִדְרְכוּ קַשְׁתָּם שֶׁקֶר (ירמיהו ט:ב):\",3,0],[2,136,11,2,\"כּוֹנְנוּ חִצָּם עַל יֶתֶר. הַקֶּשֶׁת קוֹרְדָ״א דְּאַרְ״ק בְּלַעַ״ז:\",4,0],[2,136,11,2,\"לִירוֹת. אַהֲגִיטֵ״ר בְּלַעַ״ז:\",5,0],[2,136,11,2,\"בְּמוֹ אֹפֶל. בַּמִּסְתָּר:\",6,0],[2,136,11,2,\"לְיִשְׁרֵי לֵב. דָּוִד וְכֹהֲנֵי נוֹב (שמואל ב כב):\",7,0],[2,136,11,3,\"כִּי הַשָּׁתוֹת יֵהָרֵסוּן. עַל יֶדְכֶם נֶהֶרְגוּ כֹּהֲנֵי ה׳ הַצַּדִּיקִים, שֶׁהֵם שָׁתוֹת שֶׁל עוֹלָם:\",1,0],[2,136,11,3,\"צַדִּיק מַה פָּעָל. דָּוִד, שֶׁלֹּא חָטָא, מַה פָּעַל בְּכָל זֹאת? אַתֶּם תִּשְׂאוּ עָוֹן, וְלֹא אֲנִי:\",2,0],[2,136,11,4,\"ה׳ בְּהֵיכַל קָדְשׁוֹ. הָרוֹאֶה וּבוֹחֵן מַעֲשֵׂיהֶם, וְאַף עַל פִּי שֶׁבַּשָּׁמַיִם כִּסְאוֹ גָּבוֹהַּ, עֵינָיו יֶחֱזוּ אֶתְכֶם בָּאָרֶץ:\",1,0],[2,136,11,5,\"ה׳ צַדִּיק יִבְחָן. וְאִם מִפְּנֵי שֶׁאֲנִי לוֹקֶה וְנִרְדָּף עַל יֶדְכֶם אַתֶּם מִתְהַלְּלִים לֵאמֹר ״אֱלֹהִים עֲזָבוֹ״ (תהלים עא:יא), לֹא כֵּן הוּא. אַךְ כֵּן מִדָּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַסֵּר וּלְנַסּוֹת הַצַּדִּיקִים וְלֹא אֶת הָרְשָׁעִים. הַפִּשְׁתָּנִי הַזֶּה כָּל זְמַן שֶׁיּוֹדֵעַ שֶׁפִּשְׁתָּנוֹ יָפָה הוּא מַקִּישׁ עָלֶיהָ, וּכְשֶׁאֵינוֹ יָפָה הוּא מְמַעֵט בִּכְתִישָׁה לְפִי שֶׁמִּתְנַתֶּקֶת (בראשית רבה לב:ג):\",1,0],[2,136,11,5,\"שָׂנְאָה נַפְשׁוֹ. וּמַצְנִיעַ לוֹ אֶת גְּמוּל עֲווֹנוֹתָיו לְעוֹלָם אָרוֹךְ, וְאָז יַמְטֵר עֲלֵיהֶם בַּגֵּיהִנֹּם:\",2,0],[2,136,11,6,\"פַּחִים. לְשׁוֹן פֶּחָמִים:\",1,0],[2,136,11,6,\"זִלְעָפוֹת. לְשׁוֹן שְׂרֵפָה. וּמְנַחֵם פָּתַר אוֹתוֹ לְשׁוֹן ״שַׁעַר קָטֶב״ (ישעיה כח:ב), וְכֵן ״מִפְּנֵי זַלְעֲפוֹת רָעָב״ (איכה ה:י), ״זִלְעָפָה אֲחָזַתְנִי״ (תהלים קיט:נג), כְּלוֹמַר שָׂעֲרוּ שַׂעַר (יחזקאל כז:לה) (ס״א אינו):\",2,0],[2,136,11,7,\"כִּי צַדִּיק ה׳ צְדָקוֹת אָהֵב. וִירַחֵם עַל הַצַּדִּיק, וְאוֹהֵב אוֹתָם שֶׁפָּנִימוֹ יֶחֱזוּ יָשָׁר:\",1,0],[2,136,11,7,\"יָשָׁר יֶחֱזוּ פָנֵימוֹ. מוּסָב עַל צַדִּיק ה׳, צְדָקוֹת אָהֵב וְאוֹתָם אֲשֶׁר יָשָׁר יֶחֱזוּ פָנֵימוֹ. וְרַבּוֹתֵינוּ (סנהדרין כו,א-ב) פָּתְרוּ הָרְשָׁעִים יִדְרְכוּן קֶשֶׁת עַל שֶׁבְנָא וְסִיעָתוֹ, וּפָתְרוּ לְיִשְׁרֵי לֵב עַל חִזְקִיָּהוּ וְסִיעָתוֹ:\",2,0],[2,136,11,7,\"כִּי הַשָּׁתוֹת יֵהָרֵסוּן. אִם הַשָּׁתוֹת נֶהֶרְסוּ עַל יְדֵיהֶם, צַדִּיקוֹ שֶׁל עוֹלָם מַה פָּעַל? וְאֵין סֵדֶר הַמִּקְרָאוֹת נוֹפֵל עַל הַמִּדְרָשׁ:\",3,0],[2,136,12,1,\"עַל הַשְּׁמִינִית. כִּנּוֹר שֶׁל שְׁמוֹנָה נִימִין:\",1,0],[2,136,12,2,\"גָּמַר. כָּלָה:\",1,0],[2,136,12,2,\"פַסּוּ. פֵיילִירִינְ״ט בְּלַעַ״ז, כְּמוֹ אָפְסוּ, וְכֵן פָּתַר מְנַחֵם:\",2,0],[2,136,12,2,\"כִּי פַסּוּ אֱמוּנִים מִבְּנֵי אָדָם. הַכֹּל מְשַׁקְּרִים בִּי וּמְרַגְּלִים אֶת הַמְּקוֹמוֹת אֲשֶׁר אָנֹכִי מִתְחַבֵּא שָׁם וּמַגִּידִים לְשָׁאוּל ״הֲלֹא דָוִד מִסְתַּתֵּר עִמָּנוּ״ (תהלים נד:ב; שמואל א כג:יט):\",3,0],[2,136,12,3,\"בְּלֵב וָלֵב. בִּשְׁנֵי לְבָבוֹת: לִי מַרְאִים שָׁלוֹם, וְיֵשׁ שִׂנְאָה טְמוּנָה בְּלִבָּבָם:\",1,0],[2,136,12,5,\"לִלְשׁוֹנֵנוּ נַגְבִּיר. בִּלְשׁוֹנֵנוּ נִתְגַּבֵּר:\",1,0],[2,136,12,6,\"מִשֹּׁד עֲנִיִּים. מֵחֲמַת שׁוֹד עֲנִיִּים הַנִּשְׁדָּדִים עַל יֶדְכֶם, כְּגוֹן אֲנִי וַאֲנָשַׁי וְכֹהֲנֵי נוֹב (שמואל א כב), וּמֵחֲמַת אַנְקַת אֶבְיוֹנִים, יֹאמַר ה׳ עַתָּה אָקוּם לְעֶזְרָתָם:\",1,0],[2,136,12,6,\"אָשִׁית בְּיֵשַׁע יָפִיחַ לוֹ. אֲשִׁיתֵם בְּיֵשַׁע יְדַבֵּר עֲלֵיהֶם:\",2,0],[2,136,12,6,\"יָפִיחַ. לְשׁוֹן דִּבּוּר, הַרְבֵּה יֵשׁ בְּסֵפֶר מִשְׁלֵי (משלי ו:יט), וּבַחֲבַקּוּק: ״וְיָפֵחַ לַקֵּץ וְלֹא יְכַזֵּב״ (חבקוק ב:ג). וּמְנַחֵם פָּתַר אוֹתוֹ לְשׁוֹן מוֹקֵשׁ, כְּמוֹ ״הַפַּח נִשְׁבָּר״ (תהלים קכד:ז):\",3,0],[2,136,12,7,\"אִמְרוֹת ה׳ אֲמָרוֹת טְהוֹרוֹת. הֵן שֶׁיֵּשׁ יְכֹלֶת בְּיָדוֹ לְקַיְּמָם, אֲבָל אִמְרוֹת בְּנֵי אָדָם אֵינָם אֲמָרוֹת, שֶׁהֵם מֵתִים וְאֵין בְּיָדָם לְקַיֵּם:\",1,0],[2,136,12,7,\"טְהוֹרוֹת. בְּרוּרוֹת וּמִתְקַיְּמוֹת, כָּל מַה שֶּׁמַּבְטִיחַ עוֹשֶׂה (פסיקתא רבתי יד). וַהֲרֵי הִבְטִיחַנִי יְשׁוּעָה וּמַלְכוּת:\",2,0],[2,136,12,7,\"כֶּסֶף צָרוּף. הֲרֵי הֵן כְּכֶסֶף צָרוּף הַגָּלוּי לְכָל הָאָרֶץ. בַּעֲלִיל. לְשׁוֹן גִּלּוּי הוּא בִּלְשׁוֹן הַמִּשְׁנָה בֵּין שֶׁנִּרְאָה בַּעֲלִיל בֵּין שֶׁלֹּא נִרְאָה בַּעֲלִיל כוּ׳ (ראש השנה כא:). וְיֵשׁ מְפָרְשִׁים בַּעֲלִיל לְשׁוֹן מַעֲלָה, וְכֵן פֵּרוּשׁוֹ כֶּסֶף צָרוּף בַּעֲלִיל לָאָרֶץ, כְּלוֹמַר כַּכֶּסֶף הַצָּרוּף בַּמְּשֻׁבָּח שֶׁבֶּעָפָר וּבָעֶלְיוֹן שֶׁבּוֹ כִּי כּוּר הַמְּצָרֵף יַעֲשֶׂה אָדָם מִן הֶעָפָר הַמְּשֻׁבָּח. לָשׁוֹן אַחֵר בַּעֲלִיל כְּמוֹ עֱלִי ״בְּתוֹךְ הָרִיפוֹת בַּעֱלִי״ (משלי כז:כב), וְהוּא שֵׁם כְּלִי שֶׁכּוֹתְשִׁין בְּתוֹכוֹ, וְכֵן בַּעֲלִיל הַכּוּר שֶׁמַּתִּיכִין לְתוֹכוֹ הַזָּהָב וְהַכֶּסֶף. וְזֶה אֵינוֹ נִרְאֶה, לְפִי שֶׁאֵינוֹ קוֹרֵא עֱלִי הַמַּכְתֵּשׁ שֶׁכּוֹתְשִׁין לְתוֹכוֹ אֶלָּא יַד הַמַּכְתֵּשׁ שֶׁכּוֹתְשִׁין בּוֹ שֶׁקּוֹרִין פילאו״ן בְּלַעַז. לָשׁוֹן אַחֵר בַּעֲלִיל לְשׁוֹן בַּעַל יָד, כְּלוֹמַר אֲדוֹן הָאָרֶץ וְשֶׁבַח הַמִּלָּה כְּנֶגֶד הַשֵּׁם, וְזֶה תַּרְגּוּם יוֹנָתָן הוּא לְשׁוֹן אַדְנוּת, וְאָמַר כִּי אִמְרוֹתֵינוּ כֶּסֶף צָרוּף מֵאֲדוֹן הָאָרֶץ שֶׁהוּא הַשֵּׁם שֶׁהוּא צָרַף וְזִקֵּק אוֹתָם (ס״א אינו):\",3,0],[2,136,12,8,\"תִּשְׁמְרֵם. לְאוֹתָם עֲנִיִּים וְאֶבְיוֹנִים הַנִּרְדָּפִים מִן הַדּוֹר זוּ, שֶׁהֵם דַּלְטוֹרִין. מְזֻקָּק שִׁבְעָתַיִם. מִדְרַשׁ אַגָּדָה יֵשׁ, וּמְיֻשָּׁב עַל הַסֵּדֶר: רַבִּי יְהוֹשֻׁעַ דְּסִכְנִין בְּשֵׁם רַבִּי לֵוִי: תִּינוֹקוֹת שֶׁהָיוּ בִּימֵי דָוִד, עַד שֶׁלֹּא טָעֲמוּ טַעַם חֵטְא הָיוּ יוֹדְעִים לִדְרוֹשׁ אֶת הַתּוֹרָה בְּמ״ם טי״ת פָּנִים לְכָל צַד, וְזֶהוּ שִׁבְעָתַיִם. וְהָיָה דָוִד מִתְפַּלֵּל עֲלֵיהֶם: רִבּוֹנוֹ שֶׁל עוֹלָם, רְאֵה כַּמָּה תּוֹרָתְךָ וְאִמְרָתְךָ בְּרוּרָה וּמְזֻקֶּקֶת שִׁבְעָתַיִם בְּלִבָּם! אַתָּה ה׳ תִּשְׁמְרֵם, שְׁמוֹר אוֹתָם בְּלִבָּם. תִּצְּרֶנּוּ מִן הַדּוֹר הַזֶּה, שֶׁלֹּא יִלְמְדוּ דַרְכֵיהֶם לִהְיוֹת דַּלְטוֹרִין:\",1,0],[2,136,12,9,\"סָבִיב רְשָׁעִים יִתְהַלָּכוּן. לִטְמוֹן מוֹקְשִׁים לְהַכְשִׁילֵנִי:\",1,0],[2,136,12,9,\"כְּרֻם זֻלּוּת לִבְנֵי אָדָם. מִקִּנְאָתָם, שֶׁעֵינָם רָעָה בִּגְדֻלָּתִי, שֶׁנִּלְקַחְתִּי מֵאַחֲרֵי הַצֹּאן לְמֶלֶךְ (שמואל ב ז:ח). וְזֶהוּ פִּתְרוֹנוֹ: כְּרֻם זֻלּוּת לִבְנֵי אָדָם, כְּשֶׁמִּתְרוֹמֵם אִישׁ הַזּוֹלֵל בְּעֵינֵי בְּנֵי אָדָם. וְזֶהוּ דֻּגְמָא הָאָמוּר בְּמָקוֹם אַחֵר: ״אֶבֶן מָאֲסוּ הַבּוֹנִים״ (תהלים קיח:כב). וּמִדְרַשׁ אַגָּדָה פּוֹתְרוֹ עַל יִשְׂרָאֵל לֶעָתִיד לָבֹא, כְּשֶׁיִּתְרוֹמְמוּ. וּמְנַחֵם פָּתַר כְּרֻם זֻלּוּת לִבְנֵי אָדָם כְּרֵאם הַזּוֹלֵל לֶאֱכֹל בְּנֵי אָדָם, וְיִהְיֶה כְּרֻם כְּמוֹ רוּם וְרֵאם (איוב לט:ט; במדבר כג:כב), וְזֻלּוּת כְּמוֹ ״זוֹלֵל וְסוֹבֵא״ (דברים כא:כ). וְכֵן פִּתְרוֹנוֹ: סָבִיב רְשָׁעִים יִתְהַלָּכוּן, סְבִיבוֹת הֶעָנִי הוֹלְכִים רְשָׁעִים לְבָלְעוֹ חִנָּם כְּרֻם זֻלּוּת לִבְנֵי אָדָם:\",2,0],[2,136,13,2,\"עַד אָנָה. אַרְבַּע פְּעָמִים כְּנֶגֶד אַרְבָּעָה גָּלֻיּוֹת, וּבִשְׁבִיל כָּל יִשְׂרָאֵל נֶאֱמַר:\",1,0],[2,136,13,4,\"פֶּן אִישַׁן הַמָּוֶת. שֶׁהַמִּיתָה נִקְרֵאת שֵׁינָה, ״וְיָשְׁנוּ שְׁנַת עוֹלָם״ (ירמיהו נא:לט):\",1,0],[2,136,14,1,\"אָמַר נָבָל בְּלִבּוֹ וְגוֹ׳. שְׁנֵי מִזְמוֹרִים אָמַר דָּוִד בְּסֵפֶר זֶה בְּעִנְיָן אֶחָד: הָרִאשׁוֹן עַל נְבוּכַדְנֶצַּר, וְהַשֵּׁנִי (תהלים נג) עַל טִיטוּס הָרָשָׁע. זֶה נִתְנַבֵּא עַל נְבוּכַדְנֶצַּר, שֶׁעָתִיד לִיכָּנֵס לַהֵיכָל וּלְהַחֲרִיבוֹ, וְאֵין אֶחָד מִכָּל חֵילוֹתָיו מוֹחֶה בְּיָדוֹ:\",1,0],[2,136,14,1,\"אֵין אֱלֹהִים. וְאֶעֱלֶה עַל בָּמֳתֵי עָב (ישעיהו יד:יד):\",2,0],[2,136,14,1,\"הִשְׁחִיתוּ הִתְעִיבוּ עֲלִילָה. מַעֲלָלִים:\",3,0],[2,136,14,3,\"הַכֹּל סָר וְגוֹ׳. אֵין אִישׁ בְּחֵילוֹתָיו מוֹחֶה בְּיָדוֹ:\",1,0],[2,136,14,3,\"נֶאֱלָחוּ. נֶהֶפְכוּ לְקִלְקוּל:\",2,0],[2,136,14,4,\"הֲלֹא יָדְעוּ. הֲלֹא סוֹפָם יָדְעוּ מַה שֶּׁעָלְתָה בָּהֶם?\",1,0],[2,136,14,4,\"אוֹכְלֵי עַמִּי. זַרְעוֹ שֶׁל נְבוּכַדְנֶצַּר:\",2,0],[2,136,14,4,\"אָכְלוּ לֶחֶם. עָשׂוּ מִשְׁתֶּה: ״בֵּלְשַׁאצַּר מַלְכָּא עֲבַד לְחֶם רַב״ (דניאל ה:א):\",3,0],[2,136,14,4,\"ה׳ לֹא קָרָאוּ. לֹא חֲשָׁבוּהוּ וְלֹא זָכְרוּ נִפְלְאוֹתָיו וְנוֹרְאוֹתָיו בְּמִשְׁתֵּיהֶם, וְנִשְׁתַּמְּשׁוּ בְּכֵלָיו. וְרַבּוֹתֵינוּ פֵּרְשׁוּ : כָּל שֶׁלֹּא הָיָה גּוֹזֵל אֶת יִשְׂרָאֵל לֹא הָיָה טוֹעֵם טַעַם עָרֵב בְּמַאֲכָלוֹ, אֹכְלֵי עַמִּי נִדְמֶה לָהֶם כְּאוֹכְלֵי לֶחֶם שֶׁטָּעֲמוּ טַעַם מַאֲכָל עָרֵב:\",4,0],[2,136,14,5,\"שָׁם פָּחֲדוּ פָחַד. שֶׁנִּשְׁתַּלֵּם גְּמוּלוֹ לְבֵלְשַׁצַּר וְכוּ׳:\",1,0],[2,136,14,5,\"כִּי אֱלֹהִים בְּדוֹר צַדִּיק. בְּדוֹרוֹ שֶׁל יְכָנְיָה שֶׁהָיוּ צַדִּיקִים:\",2,0],[2,136,14,6,\"עֲצַת עָנִי תָבִישׁוּ. אַתֶּם אוֹמְרִים שֶׁעֲצָתָם שֶׁל יִשְׂרָאֵל בּוּשָׁה, עַל שֶׁהֵם בּוֹטְחִים בַּה׳, כִּי ה׳ מַחְסֵהוּ:\",1,0],[2,136,14,7,\"מִי יִתֵּן. אָז יִקְרַב הַיּוֹם שֶׁיִּתֵּן מִצִּיּוֹן יְשׁוּעַת יִשְׂרָאֵל, וְאָז יָגֵל יַעֲקֹב יִשְׂמַח יִשְׂרָאֵל:\",1,0],[2,136,15,2,\"וְדוֹבֵר אֱמֶת בִּלְבָבוֹ. הַטּוֹב שֶׁהוּא אוֹמֵר בִּלְבָבוֹ הוּא אֱמֶת, וְאֵינוֹ אֶחָד בַּפֶּה וְאֶחָד בַּלֵּב (ס״א אינו):\",1,0],[2,136,15,3,\"לֹא רָגַל עַל לְשׁוֹנוֹ. אַנְקוּשָׁ״א בְּלַעַ״ז, כְּמוֹ ״וַיְרַגֵּל בְּעַבְדְּךָ״ (שמואל ב יט:כח). מִזְמוֹר זֶה לְהוֹדִיעַ מִדַּת חֲסִידוּת:\",1,0],[2,136,15,3,\"וְחֶרְפָּה לֹא נָשָׂא. רֵיפוֹרְטָ״א בְּלַעַ״ז:\",2,0],[2,136,15,3,\"עַל קְרוֹבוֹ. אִם עָבַר קְרוֹבוֹ עֲבֵרָה שֶׁיֵּשׁ בָּהּ עֹנֶשׁ, עֲנָשׁוֹ בְּמִשְׁפָּט וְלֹא נָשָׂא עָלָיו חֶרְפָּתוֹ, שֶׁיְּהֵא פִּתְחוֹן פֶּה לַמְחָרֵף לוֹמַר: כָּךְ עָבַר פְּלוֹנִי קְרוֹבְךָ וְחִפִּיתָ עָלָיו:\",3,0],[2,136,15,4,\"נִבְזֶה בְּעֵינָיו נִמְאָס. מִי שֶׁהוּא נִבְזֶה בְּרִשְׁעָתוֹ נִמְאָס בְּעֵינָיו שֶׁל צַדִּיק, כְּגוֹן חִזְקִיָּהוּ שֶׁגֵּרֵר עַצְמוֹת אָבִיו בְּבִזָּיוֹן:\",1,0],[2,136,15,4,\"נִשְׁבַּע לְהָרַע. לְעַצְמוֹ:\",2,0],[2,136,15,4,\"וְלֹא יָמִיר. שְׁבוּעָתוֹ, קַל וָחֹמֶר שֶׁאֵינָהּ מֵמִירָהּ בְּדָבָר שֶׁאֵינָהּ לְרָעָתוֹ:\",3,0],[2,136,15,5,\"וְשֹׁחַד לֹא לָקָח. עַל עָנִי לְהַרְשִׁיעוֹ בַּדִּין, לְהַטּוֹת מִשְׁפָּטוֹ. וְעוֹד פֵּרְשׁוּהוּ רַבּוֹתֵינוּ (ספרי דברים קמד): לֹא לָקַח שֹׁחַד עַל נָקִי לְנַקּוֹתוֹ בְּדִינוֹ, קַל וָחֹמֶר שֶׁאֵינוֹ לוֹקֵחַ שֹׁחַד לְהַטּוֹת הַמִּשְׁפָּט:\",1,0],[2,136,15,5,\"לֹא יִמּוֹט. וְהוּא רָאוּי לָגוּר בְּאָהָלֶיךָ (ספרים אחרין אינו):\",2,0],[2,136,15,5,\"לֹא יִמּוֹט לְעוֹלָם. אִם יִמּוֹט, אֵין מֻטָּתוֹ מֻטָה עוֹלָם, אֶלָּא מִתְמוֹטֵט וְעוֹלֶה:\",3,0],[2,136,16,1,\"מִכְתָּם לְדָוִד. אָמְרוּ רַבּוֹתֵינוּ (סוטה י:): לְדָוִד שֶׁהָיָה מָךְ וְתָם, שֶׁהָיְתָה מַכָּתוֹ תַמָּה, שֶׁנּוֹלַד מָהוּל. וְאֵין שִׁיטַת הַמִּקְרָא נוֹפֵל עַל הַמִּדְרָשׁ כָּאן. יֵשׁ מִזְמוֹר שֶׁנֶּאֱמַר בּוֹ ״לְדָוִד מִכְתָּם״ (תהלים נו:א), שָׁם יֵשׁ לְפָרֵשׁ: שִׁיר זֶה לְדָוִד שֶׁהָיָה מָךְ וְתָם, אֲבָל כָּאן שֶׁנֶּאֱמַר מִכְתָּם לְדָוִד אֵין לְפָרְשׁוֹ כֵּן. וְאוֹמֵר אֲנִי שֶׁהוּא אֶחָד מִן שְׁמוֹת מִינֵי נְעִימוֹת הַזֶּמֶר וְחִלּוּק בִּנְעִימוֹת הַשִּׁיר. דָּבָר אַחֵר: מִכְתָּם לְדָוִד לְשׁוֹן עֲטָרָה כְּמוֹ ״כֶּתֶם״ (שיר השירים ה:יא), שֶׁמַּשְׁמָע דָּבָר זֶה הָיָה רָגִיל לוֹמַר דָּוִד שָׁמְרֵנִי אֵל כִּי חָסִיתִי בָךְ וְהָיָה לוֹ כַּעֲטָרָה, שֶׁנֶּאֱמַר (תהלים ה:יג) ״כִּי כַצִּנָּה רָצוֹן תַּעְטְרֶנּוּ״ (ס״א אינו):\",1,0],[2,136,16,2,\"אָמַרְתְּ לַה׳ אֲדֹנָי אָתָּה וְגוֹ׳. לִכְנֶסֶת יִשְׂרָאֵל אָמַר דָּוִד: יֵשׁ עָלַיִךְ לוֹמַר לַה׳: אָדוֹן אַתָּה, וְיָדְךָ עַל הָעֶלְיוֹנָה לְכָל הַבָּא עָלַי. דָּבָר אַחֵר: אָמַרְתְּ לַה׳ אֲדֹנָי אָתָּה, לְנַפְשׁוֹ הָיָה אוֹמֵר. וְכֵן מָצִינוּ דֻגְמָתוֹ: ״וַתְּכַל דָּוִד״ (שמואל ב יד:לט), וּפִתְרוֹנוֹ: ׳וַתְּכַל נֶפֶשׁ דָּוִד׳; אַף כָּאן: אָמַרְתְּ נַפְשִׁי לַה׳ – אַתְּ, נַפְשִׁי, יֵשׁ עָלַיִךְ לוֹמַר כֵּן לְהַקָּדוֹשׁ בָּרוּךְ הוּא (ס״א אינו):\",1,0],[2,136,16,2,\"טוֹבָתִי בַּל עָלֶיךָ. טוֹבוֹת שֶׁאַתָּה עוֹשֶׂה לִי, לֹא עָלֶיךָ הֵם לְגָמְלֵנִי, כִּי לֹא בְצִדְקָתִי אַתָּה מֵטִיב לִי:\",2,0],[2,136,16,3,\"לִקְדוֹשִׁים אֲשֶׁר בָּאָרֶץ הֵמָּה. בִּשְׁבִיל הַקְּדוֹשִׁים אֲשֶׁר הֵמָּה קְבוּרִים בָּאָרֶץ, אֲשֶׁר הִתְהַלְּכוּ לְפָנֶיךָ בֶּאֱמֶת:\",1,0],[2,136,16,3,\"וְאַדִּירֵי כָּל חֶפְצִי בָם. הֵם הָאַדִּירִים, אֲשֶׁר כָּל חֶפְצִי בָם וְכָל צְרָכַי נַעֲשִׂים בִּשְׁבִילָם:\",2,0],[2,136,16,4,\"יִרְבּוּ עַצְּבוֹתָם וְגוֹ׳. כָּל זֶה אָמְרִי לַה׳: יִרְבּוּ עַצְּבוֹתָם שֶׁל כּוֹפְרִים בְּךָ, הַמְּהִירִים וַחֲרֵדִים לַעֲבוֹדַת אֵל אַחֵר. לָשׁוֹן אַחֵר: מָהָרוּ לְשׁוֹן ״מֹהַר״ (בראשית לד:יב), דוֹאִירְנְ״ט בְּלַעַ״ז:\",1,0],[2,136,16,4,\"בַּל אַסִּיךְ נִסְכֵּיהֶם מִדָּם. אֲנִי לֹא אֶהְיֶה כְּמוֹתָם, לִזְרֹק דָּם לַעֲבוֹדָה זָרָה, וְלֹא אֶשָּׂא שֵׁם עֲבוֹדָה זָרָה עַל שְׂפָתַי:\",2,0],[2,136,16,5,\"ה׳ מְנָת חֶלְקִי וְכוֹסִי. כָּל טוֹבָתִי הֵימֶנּוּ. לָשׁוֹן אַחֵר: וְכוֹסִי וְחֶשְׁבּוֹנִי, כְּמוֹ ״תָּכֹסּוּ עַל הַשֶּׂה״ (שמות יב:ד), וְכֵן חִבְּרוֹ מְנַחֵם:\",1,0],[2,136,16,5,\"אַתָּה תּוֹמִיךְ גּוֹרָלִי. אַתָּה הוּא אֲשֶׁר הֲנִיחוֹתָ יָדִי עַל הַחֵלֶק הַטּוֹב, שֶׁנֶּאֱמַר: ״הַחַיִּים וְהַמָּוֶת נָתַתִּי וְגוֹמֵר וּבָחַרְתָּ בַּחַיִּים״ (דברים ל:יט). כְּאָדָם הָאוֹהֵב אֶחָד מִבָּנָיו וּמַנִּיחַ יָדוֹ עַל הַחֵלֶק הַטּוֹב וְאוֹמֵר: אֶת זֶה בְּחַר לְךָ:\",2,0],[2,136,16,5,\"תּוֹמִיךְ. הִשְׁפַּלְתָּ יָדִי עַל הַגּוֹרָל, לְשׁוֹן ״יִמַּךְ הַמְּקָרֶה״ (קהלת י:יח) – יִשְׁפַּל. כָּךְ הוּא נִדְרָשׁ בַּסִּפְרִי (ספרי דברים כג). וְגַם יֵשׁ לְפוֹתְרוֹ לְשׁוֹן תְּמִיכָה, לְמִדְרַשׁ הָאַגָּדָה, כְּמוֹ ״וַיִּתְמֹךְ יַד אָבִיו״ (בראשית מח:יז):\",3,0],[2,136,16,6,\"חֲבָלִים נָפְלוּ לִי בַּנְּעִימִים. כְּשֶׁנָּפַל לִי הַגּוֹרָל לִהְיוֹת בְּחֶלְקְךָ, חֶבֶל נָעִים הוּא זֶה. אַף עָלַי שָׁפְרָה נַחֲלָה כָּזוֹ:\",1,0],[2,136,16,7,\"אֲבָרֵךְ אֶת ה׳. עַד כָּאן נִבָּא דָּוִד עַל כְּנֶסֶת יִשְׂרָאֵל שֶׁתֹּאמַר כֵּן, וְעַכְשָׁיו אוֹמֵר: וַאֲנִי, גַּם אֲנִי אֲבָרֵךְ אֶת ה׳ אֲשֶׁר יְעָצָנִי לִבְחוֹר בַּחַיִּים וְלָלֶכֶת בִּדְרָכָיו:\",1,0],[2,136,16,7,\"אַף לֵילוֹת יִסְּרוּנִי כִלְיוֹתָי. לְיִרְאָה אוֹתוֹ וּלְאַהֲבָה. וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ עַל אַבְרָהָם אָבִינוּ, שֶׁלָּמַד תּוֹרָה מֵאֵלָיו עַד שֶׁלֹּא נִתְּנָה תּוֹרָה. אַף אָנוּ צְרִיכִין לְיַשֵּׁב הַמִּקְרָאוֹת עַל סִדְרָן:\",2,0],[2,136,16,8,\"שִׁוִּיתִי ה׳ לְנֶגְדִּי תָמִיד. בְּכָל מַעֲשַׂי שַׂמְתִּי מוֹרָאוֹ לְנֶגֶד עֵינַי, וְלָמָּה? כִּי מִימִינִי הוּא תָּמִיד לְעָזְרֵנִי לְבַל אֶמּוֹט. דָּבָר אַחֵר: שִׁוִּיתִי ה׳ לְנֶגְדִּי תָמִיד. סֵפֶר תּוֹרָה הָיָה עִמּוֹ לִקְרוֹת בּוֹ כָּל יְמֵי חַיָּיו (דברים יז:יט), וְזֶה שֶׁאָמַר: מִימִינִי בַּל אֶמּוֹט. עַל שֵׁם הַתּוֹרָה שֶׁנִּתְּנָה בִּימִינוֹ, שֶׁאֲנִי עוֹסֵק בָּהּ וּלְפִיכָךְ בַּל אֶמּוֹט (סנהדרין כב.) (ס״א אינו):\",1,0],[2,136,16,9,\"לָכֵן שָׂמַח לִבִּי וְגוֹ׳. לְפִי שֶׁאֲנִי בּוֹטֵחַ כִּי לֹא תַעֲזֹב נַפְשִׁי לִשְׁאוֹל, שֶׁהֲרֵי בַּעֲוֹן עֲבֵרָה גְּדוֹלָה שֶׁהָיְתָה בְּיָדִי בִּשַּׂרְתַּנִי ״גַּם ה׳ הֶעֱבִיר חַטָּאתְךָ״ (שמואל ב יב:יג), קַל וָחֹמֶר שֶׁמֵּעַתָּה לֹא תַעַזְבֵנִי לָסוּר מִמְּךָ:\",1,0],[2,136,16,11,\"תּוֹדִיעֵנִי אֹרַח חַיִּים. לְשׁוֹן עָתִיד הוּא, וְאֵינוֹ לְשׁוֹן תְּפִלָּה:\",1,0],[2,136,16,11,\"שֹׂבַע שְׂמָחוֹת. שִׂמְחָה שֶׁאֵין לָהּ קֵץ וְתַכְלָה הִיא הַשִּׂמְחָה שֶׁל עָתִיד (ס״א אינו):\",2,0],[2,136,16,11,\"אֶת פָּנֶיךָ. שְׂמָחוֹת אֲשֶׁר לְפָנֶיךָ, בַּכַּת הַקְּרוֹבָה לְךָ:\",3,0],[2,136,17,2,\"מִלְּפָנֶיךָ מִשְׁפָּטִי יֵצֵא. עֲבֵירוֹת שֶׁבְּיָדִי, שֶׁאֲנִי רָאוּי לְהִשָּׁפֵט עֲלֵיהֶם בְּיִסּוּרִין, יֵצְאוּ מִלְּפָנֶיךָ, וְלֹא יָבוֹאוּ לְפָנֶיךָ בַּדִּין:\",1,0],[2,136,17,2,\"עֵינֶיךָ תֶּחֱזֶינָה מֵישָׁרִים. אִם יֵשׁ בְּיָדִי זְכֻיּוֹת, בָּהֶן תֶּחֱזֶינָה בְּמֵישָׁרִים עֵינֶיךָ:\",2,0],[2,136,17,3,\"בָּחַנְתָּ לִבִּי וְגוֹ׳. יָדַעְתִּי כִּי יֵשׁ עֲבֵירָה בְּיָדִי, וְאִם מִשְׁפַּט עָנְשִׁי יָבֹא לְפָנֶיךָ לֹא אֶצְדַּק בַּדִּין, אֲשֶׁר כְּבָר בָּחַנְתָּ לִבִּי:\",1,0],[2,136,17,3,\"פָּקַדְתָּ לַּיְלָה. לְעֵת הָעֶרֶב בַּעֲוֹן בַּת שֶׁבַע, שֶׁנֶּאֱמַר ״וַיְהִי לְעֵת הָעֶרֶב וַיָּקָם דָּוִד וְגוֹמֵר״ (שמואל ב יא:ב):\",2,0],[2,136,17,3,\"צְרַפְתַּנִי. נִסִּיתַנִי:\",3,0],[2,136,17,3,\"בַּל תִּמְצָא. לֹא מָצָאתָ בִּי חֶפְצְךָ:\",4,0],[2,136,17,3,\"זַמֹּתִי בַּל יַעֲבָר פִּי. אִם תַּעֲלֶה עוֹד בְּמַחֲשַׁבְתִּי לִיבָּחֵן לְפָנֶיךָ, בַּל יַעֲבָר פִּי לוֹמַר עוֹד בְּחָנֵנִי וְנַסֵּנִי, כְּמוֹ שֶׁאָמַרְתִּי כְּבָר כְּמוֹ שֶׁנֶּאֱמַר ״בְּחָנֵנִי ה׳ וְנַסֵּנִי״ (תהלים כו:ב). שֶׁאָמַר דָּוִד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: מִפְּנֵי מָה אוֹמְרִים אֱלֹהֵי אַבְרָהָם וְאֵין אוֹמְרִים אֱלֹהֵי דָוִד? אָמַר לוֹ: אֲנִי בְּחַנְתִּיו בְּעֶשֶׂר נִסְיוֹנוֹת וְנִמְצָא שָׁלֵם. אָמַר בְּחָנֵנִי וְנַסֵּנִי, כִּדְאִיתָא בְּמַסֶּכֶת שַׁבָּת (שבת קנג:):\",5,0],[2,136,17,4,\"לִפְעֻלּוֹת אָדָם בִּדְבַר שְׂפָתֶיךָ וְגוֹ׳, תָּמוֹךְ אֲשׁוּרַי וְגוֹ׳. מֵאָז וָהָלְאָה לְכָל פְּעֻלַּת אָדָם שֶׁבָּאתִי לִפְעֹל, אֲנִי שָׁמַרְתִּי בִּשְׁבִיל דְּבַר שְׂפָתֶיךָ אָרְחוֹת פָּרִיץ לִנְטוֹת מֵהֶם, שֶׁלֹּא אֵלֵךְ בָּהֶם, אַךְ לִתְמֹךְ אֲשׁוּרַי תָּמִיד בְּמַעְגְּלוֹתֶיךָ, לֹא נָמוֹטוּ מֵהֶם פְּעָמַי. פֵּרוּשׁ אַחֵר: לִפְעֻלּוֹת אָדָם בִּדְבַר שְׂפָתֶיךָ וְגוֹ׳, לְפִי שֶׁצָּרִיךְ אָדָם לְהִשְׁתַּמֵּשׁ בִּפְעֻלּוֹתָיו לְפִי יִשְׁרַת דְּבַר שְׂפָתֶיךָ אֲשֶׁר אָמַרְתָּ ״לֹא תִנְאָף״ (שמות כ:יג), אֲנִי שָׁמַרְתִּי אָרְחוֹת פָּרִיץ אַף עַל פִּי שֶׁעָשִׂיתִי שֶׁלֹּא כָּרָאוּי בְּטוֹבָתְךָ:\",1,0],[2,136,17,5,\"תָּמוֹךְ אֲשֻׁרַי וְגוֹ׳. מֵאָז וָהָלְאָה לְכָל פְּעֻלַּת אָדָם שֶׁבָּאתִי לִפְעוֹל אֶת הַמֵּישָׁרִים תֶּחֱזֶינָה עֵינֶיךָ, וְהַמִּשְׁפָּט מִלְּפָנֶיךָ יֵצֵא:\",1,0],[2,136,17,6,\"כִּי תַעֲנֵנִי אֵל. כִּי בָּטוּחַ אֲנִי שֶׁתַּעֲנֵנִי:\",1,0],[2,136,17,7,\"הַפְלֵה חֲסָדֶיךָ. דֵּשִׁיבְרָ״א בְּלַעַ״ז, כְּמוֹ ״וְנִפְלִינוּ אֲנִי וְעַמְּךָ״ (שמות לג:טז). מוֹשִׁיעַ בִּימִינְךָ אֶת הַחוֹסִים בְּךָ מִמִּתְקוֹמְמִים עֲלֵיהֶם. הַפְלֵה חֲסָדֶיךָ מוֹשִׁיעַ חוֹסִים הֲרֵי זֶה מִקְרָא מְסֹרָס: הַפְלֵה חֲסָדֶיךָ לְהוֹשִׁיעַ בִּימִינְךָ אֶת הַחוֹסִים וְגוֹ׳:\",1,0],[2,136,17,8,\"כְּאִישׁוֹן. הוּא הַשָּׁחוֹר שֶׁבָּעַיִן, שֶׁהָאוֹר תָּלוּי בּוֹ. וְעַל שֵׁם שַׁחֲרוּרִיתוֹ הוּא קָרוּי אִישׁוֹן, לְשׁוֹן חֹשֶׁךְ (משלי כ:כ). וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֵכִין לוֹ שׁוֹמֵר, אֶת רִיסֵי הָעַיִן הַמְכַסִּין אוֹתוֹ תָּמִיד:\",1,0],[2,136,17,9,\"זוּ שַׁדּוּנִי. בִּשְׁבִיל זֹאת שֶׁשּׁוֹדְדִים אוֹתִי אוֹיְבַי, אֲשֶׁר בְּנֶפֶשׁ יַקִּיפוּ עָלָי. לִטּוֹל נַפְשִׁי:\",1,0],[2,136,17,10,\"חֶלְבָּמוֹ סָגְרוּ. בְּחֶלְבָּם וּבְשֻׁמָּנָם סָגְרוּ לִבָּם וְעֵינֵיהֶם מֵהַבִּיט אֶל פָּעֳלְךָ לִירָאָה מִפָּנֶיךָ:\",1,0],[2,136,17,11,\"אַשֻּׁרֵינוּ עַתָּה סְבָבוּנוּ. אֶת עֲקֵבֵנוּ עַתָּה סְבָבוּנוּ הָאוֹיְבִים, וְעֵינֵיהֶם יָשִׁיתוּ לִנְטוֹת בָּאָרֶץ לִפְשֹׁט בָּאָרֶץ. וְנִרְאֶה לִי שֶׁנִּתְפַּלֵּל דָּוִד תְּפִלָּה זוֹ לְאַחַר שֶׁבָּא לְיָדוֹ מַעֲשֶׂה שֶׁל אוּרִיָּה, וְיוֹאָב וְיִשְׂרָאֵל הָיוּ בְּאֶרֶץ בְּנֵי עַמּוֹן צָרִים עַל רַבָּה (שמואל ב יא:א), וַיִּירָא דָּוִד שֶׁלֹּא יִכָּשְׁלוּ שָׁם בִּשְׁבִיל עֲבֵרָה שֶׁבְּיָדוֹ, וְיִשְׁמְעוּ פְלִשְׁתִּים וּמוֹאָב וֶאֱדוֹם וְכָל שְׁכֵנֵי אֶרֶץ יִשְׂרָאֵל הָרָעִים הַמְצַפִּים לְיוֹם אֵידָם, וְיָבֹאוּ עֲלֵיהֶם:\",1,0],[2,136,17,12,\"יִכְסוֹף. יַחְמוֹד, כְּמוֹ ״כִּי נִכְסֹף נִכְסַפְתָּ״ (בראשית לא:ל):\",1,0],[2,136,17,13,\"קַדְּמָה פָנָיו. שֶׁל אוֹיֵב:\",1,0],[2,136,17,13,\"הַכְרִיעֵהוּ. קַפַּח אֶת רַגְלָיו וְיִכְרַע וְיִפּוֹל:\",2,0],[2,136,17,13,\"פַּלְּטָה נַפְשִׁי. מִכָּל רָשָׁע שֶׁהוּא חַרְבְּךָ, שֶׁאַתָּה מַשְׁלִיטוֹ לִיפָּרַע מִן הַמְחֻיָּבִים לְךָ:\",3,0],[2,136,17,14,\"מִמְּתִים יָדְךָ. מִן הַמֵּתִים בְּיָדְךָ עַל מִטָּתָם אֲנִי בּוֹחֵר לִהְיוֹת:\",1,0],[2,136,17,14,\"מִמְּתִים מֵחֶלֶד. מֵאוֹתָם שֶׁמֵּתִים בְּזִקְנָה, מִשֶּׁהֶעֱלוּ חֲלֻדָּה, רְדוּיִילָ״א בְּלַעַ״ז, וּמִן הַצַּדִּיקִים אֲשֶׁר חֶלְקָם בַּחַיִּים:\",2,0],[2,136,17,14,\"וּצְפוּנְךָ תְּמַלֵּא בִטְנָם. וּמֵאוֹתָם אֲשֶׁר תְּמַלֵּא מְעֵיהֶם מִטּוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ (תהלים לא:כ):\",3,0],[2,136,17,14,\"יִתְרָם. נִכְסֵיהֶם אֲשֶׁר יַשְׁאִירוּ בְּמוֹתָם:\",4,0],[2,136,17,15,\"אֲנִי בְּצֶדֶק אֶחֱזֶה פָנֶיךָ. לֶעָתִיד, אוֹ בְּצֶדֶק אֶחֱזֶה פָנֶיךָ מִשְׁפָּטִי הוֹצֵא מִלְּפָנֶיךָ, וְהַצְּדָקוֹת שֶׁבְּיָדִי אֱחוֹז, וּבָהֶם אֶחֱזֶה פָנֶיךָ:\",1,0],[2,136,17,15,\"אֶשְׂבְּעָה בְהָקִיץ תְּמוּנָתֶךָ. אֶשְׂבְּעָה מֵרְאִיַּת תְּמוּנָתְךָ בְּהָקִיץ הַמֵּתִים מִשְּׁנָתָם. לָשׁוֹן אַחֵר: אֶשְׂבְּעָה מֵרְאוֹת פָּנֶיךָ בְּהָקִיץ הַמֵּתִים מִשְּׁנָתָם, שֶׁהֵם בִּדְמוּת תְּמוּנָתְךָ, שֶׁכֵּן נֶאֱמַר ״כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם״ (בראשית ט:ו):\",2,0],[2,136,18,1,\"בְּיוֹם הִצִּיל ה׳ אוֹתוֹ וְגוֹ׳. כְּשֶׁהִזְקִין, וּכְבָר עָבְרוּ עָלָיו כָּל צָרוֹתָיו וְנִצּוֹל מֵהֶם:\",1,0],[2,136,18,1,\"וּמִיַּד שָׁאוּל. וַהֲלֹא שָׁאוּל בִּכְלָל הָיָה? אֶלָּא לְפִי שֶׁהָיָה קָשֶׁה עָלָיו וְרוֹדְפוֹ יוֹתֵר מִכֻּלָּם. כְּיוֹצֵא בַדָּבָר אַתָּה אוֹמֵר: ״וְרָאוּ אֶת הָאָרֶץ וְאֶת יְרִיחוֹ״ (יהושע ב:א):\",2,0],[2,136,18,2,\"אֶרְחָמְךָ. אֲאַהֶבְךָ, כְּדִמְתַרְגֵּם ״וְאָהַבְתָּ״ (ויקרא יט:יח): ״וְתִרְחַם״ (תרגום אונקלוס):\",1,0],[2,136,18,3,\"סַלְעִי. שֶׁעֲזַרְתַּנִי בְּסֶלַע הַמַּחְלְקוֹת, כְּשֶׁהָיִיתִי מְצֻמְצָם בֵּין שָׁאוּל וַאֲנָשָׁיו לְהִתָּפֵס, כְּמוֹ שֶׁנֶּאֱמַר: ״וְשָׁאוּל וַאֲנָשָׁיו עוֹטְרִים אֶל דָּוִד וְגוֹמֵר״ (שמואל א כג:כו):\",1,0],[2,136,18,3,\"וּמְצוּדָתִי. לְשׁוֹן מִבְצָר:\",2,0],[2,136,18,3,\"צוּרִי. לְשׁוֹן סֶלַע:\",3,0],[2,136,18,3,\"אֶחֱסֶה. אַבְרִיאַיְי״ר בְּלַעַ״ז:\",4,0],[2,136,18,3,\"אֶחֱסֶה בּוֹ. אֶתְכַּסֶּה בְּצִלּוֹ, כְּעִנְיָן שֶׁנֶּאֱמַר ״וּמִבְּלִי מַחְסֶה חִבְּקוּ צוּר״ (איוב כד:ח) – שֶׁהַסְּלָעִים כִּסּוּי וּמָגֵן לְהוֹלְכֵי דְרָכִים מִן הָרוּחוֹת וּמִזֶּרֶם גְּשָׁמִים:\",5,0],[2,136,18,4,\"מְהֻלָּל אֶקְרָא ה׳. בְּהִלּוּלִים אֶקְרָא וְאֶתְפַּלֵּל לְפָנָיו תָּמִיד, כְּלוֹמַר אַף לִפְנֵי הַתְּשׁוּעָה אֲנִי מְהַלְּלוֹ, לְפִי שֶׁבָּטוּחַ אֲנִי שֶׁאִוָּשֵׁעַ מֵאוֹיְבַי:\",1,0],[2,136,18,5,\"אֲפָפוּנִי חֶבְלֵי מָוֶת. פְּעָמִים רַבּוֹת סְבָבוּנִי רְשָׁעִים, אֲפָפוּנִי כְּמוֹ סְבָבוּנִי, וְכֵן ״אָפְפוּ עָלַי רָעוֹת״ (תהלים מ:יג):\",1,0],[2,136,18,5,\"חֶבְלֵי מָוֶת. מַחֲנוֹת אוֹיְבִים, כְּמוֹ ״חֶבֶל נְבִיאִים״ בְּסֵפֶר שְׁמוּאֵל (שמואל א י:ה). וְיוֹנָתָן תִּרְגֵּם: ״כְּאִתְּתָא דְּיָתְבָא עַל מַתְבְּרָא״, לְשׁוֹן ״חֶבְלֵי יוֹלֵדָה״ (הושע יג:יג):\",2,0],[2,136,18,5,\"וְנַחֲלֵי בְלִיַּעַל. אַף הוּא לְשׁוֹן גְּיָסוֹת שׁוֹטְפִים כְּנַחַל:\",3,0],[2,136,18,6,\"חֶבְלֵי שְׁאוֹל. כְּמוֹ חֶבְלֵי מָוֶת – ״מַשְׁרְיָן רַשִׁיעָן״ (תרגום יונתן שמואל ב כב:ו), וַאֲנִי מָה הָיִיתִי עוֹשֶׂה?\",1,0],[2,136,18,7,\"בַּצַּר לִי אֶקְרָא. אֲנִי הָיִיתִי קוֹרֵא לַה׳ תָּמִיד:\",1,0],[2,136,18,8,\"וַתִּגְעַשׁ וַתִּרְעַשׁ הָאָרֶץ. אֵינוֹ מְחֻבָּר לְמִקְרָא עֶלְיוֹן, אֶלָּא מְחֻבָּר רֹאשׁוֹ לְסוֹפוֹ: כִּי חָרָה לוֹ וַתִּגְעַשׁ וַתִּרְעַשׁ הָאָרֶץ. כִּי מְשַׁמֵּשׁ בִּלְשׁוֹן כַּאֲשֶׁר: כְּשֶׁחָרָה לוֹ וּבָא לִנְקֹם נִקְמַת עַמּוֹ וַעֲבָדָיו מִפַּרְעֹה וּמֵעַמּוֹ, גָּעֲשָׁה וְרָעֲשָׁה הָאָרֶץ:\",1,0],[2,136,18,9,\"עָלָה עָשָׁן בְּאַפּוֹ. אַנְשִׁישְׁנַארִילַ״שׁ בְּלַעַ״ז, כֵּן דֶּרֶךְ כָּל חֲרוֹן אַף לְהַעֲלוֹת עָשָׁן מִנְּחִירָיו:\",1,0],[2,136,18,10,\"וַיֵּט שָׁמַיִם וַיֵּרַד. לַעֲבוֹר בְּאֶרֶץ מִצְרַיִם. וַיֵּרַד כְּמַשְׁמָעוֹ. לָשׁוֹן אַחֵר: אִיאַנְטְבִּ״שׁ בְּלַעַ״ז:\",1,0],[2,136,18,11,\"וַיֵּדֶא. וַיָּעֹף, כְּמוֹ ״כַּאֲשֶׁר יִדְאֶה הַנָּשֶׁר״ (דברים כח:מט):\",1,0],[2,136,18,12,\"חֶשְׁכַת מַיִם. שֶׁבְּעָבֵי שְׁחָקִים הֵם חֹשֶׁךְ אֲשֶׁר סְבִיבוֹתָיו. וְשֶׁמָּא תֹּאמַר: לִפְנִים מִן הַחֹשֶׁךְ אֵין אוֹר? תַּלְמוּד לוֹמַר: מִנֹּגַהּ אֲשֶׁר נֶגְדּוֹ וּמִתּוֹךְ מְחִיצָתוֹ, אֶת עָבָיו אֲשֶׁר סְבִיבוֹתָיו בּוֹקְעִים וְעוֹבְרִים בָּרָד וְגַחֲלֵי אֵשׁ:\",1,0],[2,136,18,13,\"עָבְרוּ. טְרִישְׁפָּא״שְׁנְט בְּלַעַ״ז, הַבָּרָד בּוֹקֵעַ וְעוֹבֵר עַל הַמִּצְרִיִּים עַל יָם סוּף (שמות יד:כא-כח):\",1,0],[2,136,18,16,\"וַיֵּרָאוּ אֲפִיקֵי מַיִם. כְּשֶׁנִּבְקַע הַיָּם:\",1,0],[2,136,18,16,\"וַיִּגָּלוּ מוֹסְדוֹת תֵּבֵל. שֶׁכָּל מֵימוֹת שֶׁבָּעוֹלָם נִבְקְעוּ:\",2,0],[2,136,18,16,\"מִנִּשְׁמַת. מִנְּשִׁיבַת:\",3,0],[2,136,18,17,\"יִשְׁלַח מִמָּרוֹם. מַלְאָכָיו לְהַצִּיל אֶת יִשְׂרָאֵל מִן הַיָּם וּמִמִּצְרַיִם:\",1,0],[2,136,18,17,\"יַמְשֵׁנִי. לְשׁוֹן הוֹצָאָה, כְּמוֹ ״כִּי מִן הַמַּיִם מְשִׁיתִהוּ״ (שמות ב:י):\",2,0],[2,136,18,19,\"יְקַדְּמוּנִי. אוֹיְבַי הָיוּ מְמַהֲרִין וּמַקְדִּימִין לָבֹא עָלַי בְיוֹם אֵידִי וַיְהִי ה׳ וְגוֹמֵר:\",1,0],[2,136,18,21,\"כְּצִדְקִי. כְּצֶדֶק לֶכְתִּי אַחֲרָיו בַּמִּדְבָּר (ירמיהו ב:ב):\",1,0],[2,136,18,21,\"כְּבֹר. לְשׁוֹן נְקִיּוּת, כְּמוֹ ״וּבַר לֵבָב״ (תהלים כד:ד). דָּבָר אַחֵר: יִשְׁלַח מִמָּרוֹם יִקָּחֵנִי – כְּנֶגֶד עַצְמוֹ אָמַר, עַל שֵׁם הַמַּלְאָךְ שֶׁבָּא בְּסֶלַע הַמַּחְלְקוֹת לִפְצוֹת אֶת שָׁאוּל מֵעָלָיו, שֶׁנֶּאֱמַר ״וּמַלְאָךְ בָּא אֶל שָׁאוּל וְגוֹמֵר״ (שמואל א כג:כז):\",2,0],[2,136,18,21,\"כְּצִדְקִי. שֶׁלֹּא הֲרַגְתִּיו בְּכָרְתִי אֶת כְּנַף מְעִילוֹ (שמואל א כד:ד):\",3,0],[2,136,18,23,\"כִּי כָל מִשְׁפָּטָיו לְנֶגְדִּי. תָּמִיד שַׂמְתִּים אוֹתָם לְנֶגֶד עֵינַי:\",1,0],[2,136,18,26,\"עִם חָסִיד תִּתְחַסָּד. כְּלוֹמַר: לְפִי שֶׁכֵּן דְּרָכָיו, לִגְמוֹל מִדָּה כְּנֶגֶד מִדָּה. חָסִיד, תָּמִים, נָבָר – כְּנֶגֶד שְׁלֹשָׁה אָבוֹת:\",1,0],[2,136,18,27,\"עִם נָבָר. נֶאֱמָן:\",1,0],[2,136,18,27,\"עִם עִקֵּשׁ. כְּנֶגֶד פַּרְעֹה:\",2,0],[2,136,18,29,\"כִּי אַתָּה תָּאִיר נֵרִי. כְּשֶׁנִּלְחַם בַּלַּיְלָה בִּגְדוּד עֲמָלֵק הַבָּא עַל צִקְלַג, שֶׁנֶּאֱמַר ״וַיַּכֵּם דָּוִד מֵהַנֶּשֶׁף וְעַד הָעֶרֶב לְמָחֳרָתָם״ (שמואל א ל:יז):\",1,0],[2,136,18,30,\"כִּי בְךָ. בְּמִבְטַחֲךָ:\",1,0],[2,136,18,30,\"וּבֵאלֹהַי אֲדַלֶּג שׁוּר. כְּשֶׁבָּא לְהִלָּחֵם עַל יְבוּס וְאָמַר: ״כָּל מַכֵּה יְבוּסִי יִהְיֶה לְרֹאשׁ וּלְשַׂר״ (דברי הימים א יא:ו), הֵבִיא יוֹאָב בְּרוֹשׁ רַעֲנָן וּכּפָפוֹ, וְנִתְלָה בּוֹ וְעָלָה עַל הַחוֹמָה. אָמַר דָּוִד: ״יֶהֶלְמֵנִי צַדִּיק וְגוֹמֵר״ (תהלים קמא:ה), קִצֵּר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַחוֹמָה וְדִלֵּג. בְּמִדְרַשׁ תְּהִלִּים:\",2,0],[2,136,18,31,\"צְרוּפָה. בְּרוּרָה; מַבְטִיחַ וְעוֹשֶׂה:\",1,0],[2,136,18,33,\"וַיִּתֵּן תָּמִים דַּרְכִּי. הֵסִיר מִדְּרָכַי כָּל תַּקָּלָה וּמִכְשׁוֹל, עַד שֶׁנַּעֲשָׂה שָׁלֵם וְכָבוּשׁ:\",1,0],[2,136,18,34,\"מְשַׁוֶּה רַגְלַי כָּאַיָּלוֹת. רַגְלֵי הַנְּקֵבוֹת עוֹמְדוֹת בְּיֹשֶׁר יוֹתֵר מִשֶּׁל זְכָרִים:\",1,0],[2,136,18,35,\"וְנִחֲתָה קֶשֶׁת נְחוּשָׁה זְרוֹעֹתָי. וְנִחֲתָה לְשׁוֹן דְּרִיכַת קֶשֶׁת, כְּמוֹ ״חִצֶּיךָ נִחֲתוּ בִי״ (תהלים לח:ג), וּפֹעַל שֶׁלּוֹ נָחַת וּכְשֶׁמִּתְפַּעֵל בָּא דָּגֵשׁ וּמְחַסֵּר אֶת הַנּוּ״ן וְנִחֲתָה מִגִּזְרַת נִנְחֲתָה כְּמוֹ ״נִחַר גְּרוֹנִי״ (תהלים סט:ד) מִגִּזְרַת נִנְחַר, כְּמוֹ ״נָחַר מַפֻּחַ״ (ירמיהו ו:כט) נִדַּף מִגִּזְרָה נִנְדַּף, ״עֵינִי נִגְּרָה״ (איכה ג:מט) כְּמוֹ נִנְגְּרָה, נִתְּנָה כְּמוֹ נִנְתְּנָה, נִגַּף מִגִּזְרַת נִנְגַּף. וְאֵין לְפוֹתְרוֹ מִגִּזְרַת חָתָה, שֶׁהָיָה לוֹ לוֹמַר נִחְתְּתָה כְּמוֹ מִן עָשָׂה נֶעֶשְׂתָה מִן עָנָה נַעֲנְתָה. דָּבָר אַחֵר: וְנִחֲתָה קֶשֶׁת נְחוּשָׁה זְרוֹעֹתָי חִיֵּת לְשׁוֹן דְּרִיכַת קֶשֶׁת כְּמוֹ ״חִצֶּיךָ נִחֲתוּ״ (תהלים לח:ג) הַנּוּ״ן אֵינָהּ יְסוֹד בַּתֵּבָה אֶלָּא כְּמוֹ נִחֲלוּ וְנִדְרְכָה קֶשֶׁת נְחוּשָׁה עַל יְדֵי זְרוֹעוֹתַי, קַשָּׁתוֹת שֶׁל נְחֹשֶׁת הָיוּ תְּלוּיוֹת לוֹ לְדָוִד בְּבֵיתוֹ וְרוֹאִין אוֹתָם מַלְכֵי הָאֻמּוֹת וְאוֹמְרִים זֶה לָזֶה אַתָּה סָבוּר שֶׁיֵּשׁ כֹּחַ בְּיַד דָּוִד לְדוֹרְכָן אֵין זֶה אֶלָּא לְיָרְאֵנוּ, וְהוּא הָיָה שׁוֹמֵעַ וְדוֹרְכָן בִּפְנֵיהֶם:\",1,0],[2,136,18,36,\"וְעַנְוַתְךָ תַרְבֵּנִי. הִרְבֵּיתָה מִדַּת עֲנָוְתְךָ לְהִתְנַהֵג בָּהּ עִמִּי:\",1,0],[2,136,18,37,\"תַּרְחִיב צַעֲדִי תַחְתָּי. הַמַּרְחִיב צְעָדָיו אֵינוֹ נוֹחַ לִיפּוֹל, וְכֵן הוּא אוֹמֵר ״בְּלֶכְתְּךָ לֹא יֵצַר צַעֲדֶךָ״ (משלי ד:יב):\",1,0],[2,136,18,37,\"מָעֲדוּ. אִיקְלוֹרְגִירִינְ״ט בְּלַעַ״ז:\",2,0],[2,136,18,37,\"קַרְסֻלָּי. הֵם הָרַגְלַיִם מִן הָאִסְתּוֹרִין, שֶׁקּוֹרִין קָבִילָ״א בְּלַעַ״ז, וּלְמַטָּה:\",3,0],[2,136,18,41,\"נָתַתָּה לִּי עֹרֶף. פּוֹנִים לִי עָרְפָּם וּבוֹרְחִים:\",1,0],[2,136,18,42,\"יְשַׁוְּעוּ. לַעֲבוֹדָה זָרָה שֶׁלָּהֶם:\",1,0],[2,136,18,42,\"וְאֵין מוֹשִׁיעַ. שֶׁאֵין בָּהּ יְכֹלֶת, וְחוֹזְרִים וְקוֹרְאִים אֶל ה׳, וְלֹא עָנָם:\",2,0],[2,136,18,43,\"וְאֶשְׁחָקֵם. לְשׁוֹן כְּתִישָׁה:\",1,0],[2,136,18,43,\"אֲרִיקֵם. כְּטִיט הַנָּרוּק, שֶׁאֵינוֹ עָב. כְּמוֹ ״הֵם מְרִיקִים שַׂקֵּיהֶם״ (בראשית מב:לה), ״לֹא הוּרַק מִכְּלִי אֶל כֶּלִי״ (ירמיהו מח:יא):\",2,0],[2,136,18,44,\"תְּפַלְּטֵנִי מֵרִיבֵי עָם. שֶׁלֹּא אֵעָנֵשׁ בְּדִין יִשְׂרָאֵל לְהַטּוֹת מִשְׁפָּט, וְלֹא לְשַׁעְבֵּד בְּיִשְׂרָאֵל יוֹתֵר מִן הָרְשׁוּת:\",1,0],[2,136,18,44,\"תְּשִׂימֵנִי לְרֹאשׁ גּוֹיִם. שֶׁאֵין עֹנֶשׁ בָּהֶם:\",2,0],[2,136,18,45,\"לְשֵׁמַע אֹזֶן. אֲפִילּוּ שֶׁלֹּא בְּפָנַי, אֶלָּא שֶׁיִּשְׁמְעוּ שְׁלִיחוּתִי:\",1,0],[2,136,18,45,\"יִשָּׁמְעוּ לִי. יָסוּרוּ אֶל מִשְׁמַעְתִּי, וְיִהְיוּ נִשְׁמָעִים לִדְבָרַי:\",2,0],[2,136,18,45,\"יְכַחֲשׁוּ לִי. מֵחֲמַת יִרְאָה:\",3,0],[2,136,18,46,\"יִבֹּלוּ. יִלְאוּ, כְּמוֹ ״נָבֹל תִּבֹּל״ (שמות יח:יח), דִּמְתַרְגֵּם ״מִילְאָה תִּילְאָה״. וּמְנַחֵם פֵּירֵשׁ כְּמוֹ ״אַחֲרֵי בְלֹתִי״ (בראשית יח:יב), וְכֵן פֵּירֵשׁ ״נָבֹל תִּבֹּל״:\",1,0],[2,136,18,46,\"וְיַחְרְגוּ. לְשׁוֹן אֵימָה. ״מֵחֲדָרִים אֵימָה״ (דברים לב:כה) מְתַרְגְּמִינָן: ״חַרְגַּת מוֹתָא״:\",2,0],[2,136,18,46,\"מִמִּסְגְּרוֹתֵיהֶם. מֵחֲמַת יִסּוּרֵי מַסְגְּרוֹת כֶּלֶא שֶׁאֲנִי מַסְגִּירָם שָׁם וּמְיַסְּרָן בָּהֶן. וְיַחְרְגוּ מִמִּסְגְּרוֹתֵיהֶם מְנַחֵם פָּתַר אוֹתוֹ לְשׁוֹן רִפְיוֹן חֲגוֹרָה, וְכֵן פֵּרוּשׁוֹ: וְיִתְרַפּוּ מִמִּסְגְּרוֹתֵיהֶם. וְדוּנָ״שׁ פָּתַר וְיַחְרְגוּ מִמִּסְגְּרוֹתֵיהֶם וְיִפְסְחוּ מִכַּבְלֵיהֶם הַנְּתוּנִים עַל רַגְלֵיהֶם. וּפִתְרוֹן וְיַחְרְגוּ ״וְיִפְסְחוּ״ (ויקרא כא:יח), כְּדִמְתַרְגְּמִינָן ״חֲגִירָא״:\",3,0],[2,136,18,47,\"חַי ה׳. הָעוֹשֶׂה לִי כָּל זֹאת:\",1,0],[2,136,18,48,\"הַנּוֹתֵן נְקָמוֹת לִי. נוֹתֵן בִּי כֹּחַ לְהִנָּקֵם מֵאוֹיְבַי:\",1,0],[2,136,18,48,\"וַיַּדְבֵּר. וְיַהֲרֹג, לְשׁוֹן דֶּבֶר. לָשׁוֹן אַחֵר: כְּמוֹ ״וַיִּנְהַג״ (שמות ג:א), דִּמְתַרְגְּמִינַן: ״וּדְבַר״. וְכֵן חִבְּרוֹ מְנַחֵם, וְגַם כֵּן חִבֵּר ״יַדְבֵּר עַמִּים תַּחְתֵּינוּ״ (תהלים מז:ד):\",2,0],[2,136,18,48,\"תַּחְתָּי. בִּמְקוֹמִי וְחִלּוּפִי, כְּעִנְיָן שֶׁנֶּאֱמַר ״וָאֶתֵּן אָדָם תַּחְתֶּיךָ״ (ישעיהו מג:ד) – ״נָתַתִּי כָפְרְךָ מִצְרַיִם״ (ישעיהו מג:ג):\",3,0],[2,136,19,2,\"הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל. הַמְשׁוֹרֵר עַצְמוֹ פֵּרַשׁ אֶת הַדָּבָר: אֵין אֹמֶר וְאֵין דְּבָרִים. אֵינָן מְדַבְּרִים עִם הַבְּרִיּוֹת, אֶלָּא מִתּוֹךְ שֶׁבְּכָל הָאָרֶץ יָצָא קַוָּם וּמְאִירִים לַבְּרִיּוֹת, מִתּוֹךְ כָּךְ מְסַפְּרִים הַבְּרִיּוֹת כְּבוֹד אֵל וּמוֹדִים וּמְבָרְכִין עַל הַמְּאוֹרוֹת:\",1,0],[2,136,19,2,\"וּמַעֲשֵׂה יָדָיו מַגִּיד הָרָקִיעַ. הַכּוֹכָבִים וְהַמַּזָּלוֹת, שֶׁהֵם מַעֲשֵׂה יָדָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֲשֶׁר הֵם שָׁם, כְּמוֹ שֶׁנֶּאֱמַר ״וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם״ (בראשית א:יז), וּמִשָּׁם מַגִּידִים כְּבוֹדוֹ:\",2,0],[2,136,19,3,\"יוֹם לְיוֹם יַבִּיעַ אֹמֶר. מַעֲשֵׂה בְרֵאשִׁית מִתְחַדֵּשׁ מִיּוֹם אֶל יוֹם; לָעֶרֶב חַמָּה שׁוֹקַעַת וְזוֹרַחַת לַבֹּקֶר, וּמִתּוֹךְ כָּךְ יַבִּיעוּ הַבְּרִיּוֹת אִמְרֵי שֶׁבַח עַל יְדֵי הַיָּמִים וְהַלֵּילוֹת, שֶׁמּוֹרִים אֶת הַבְּרִיּוֹת לְקַלֵּס וּלְהוֹדוֹת. מְנַחֵם פֵּתַר ״יַבִּיעַ״ לְשׁוֹן ״מַעְיָן נוֹבֵעַ״:\",1,0],[2,136,19,3,\"יְחַוֶּה. לְשׁוֹן הַגָּדָה:\",2,0],[2,136,19,5,\"בְּכָל הָאָרֶץ יָצָא קַוָּם. קַו הַשָּׁמַיִם שֶׁהֵם נִמְתָּחִים עַל פְּנֵי כָּל הָאָרֶץ, וּמֵחֲמַת כֵּן בִּקְצֵה תֵבֵל מִלֵּיהֶם שֶׁהַכֹּל מְדַבְּרִים בַּנִּפְלָאוֹת שֶׁהֵם רוֹאִים:\",1,0],[2,136,19,5,\"לַשֶּׁמֶשׁ שָׂם. הַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,136,19,5,\"אֹהֶל בָּהֶם. בַּשָּׁמַיִם, מִכָּאן שֶׁהַשֶּׁמֶשׁ נָתוּן בְּתוֹךְ תִּיקוֹ (תנחומא, תצוה ח):\",3,0],[2,136,19,6,\"וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ. בְּכָל בֹּקֶר, וְזֶהוּ שֶׁאָמַר הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל:\",1,0],[2,136,19,7,\"וּתְקוּפָתוֹ עַל קְצוֹתָם. הַקָּפַת סִבּוּבוֹ מִקָּצֶה אֶל קָצֶה:\",1,0],[2,136,19,7,\"וְאֵין נִסְתָּר מֵחַמָּתוֹ. אִילְמָלֵא נִיתַּן בָּרָקִיעַ הַתַּחְתּוֹן, לֹא הָיָה אָדָם נִסְתָּר מִפָּנָיו מִפְּנֵי חֲמִימוּתוֹ. שֶׁחַמָּה וּלְבָנָה בָּרָקִיעַ הַשֵּׁנִי, כְּדְאָמְרִינַן (חגיגה יב:): שִׁבְעָה רְקִיעִים הֵם: וִילוֹן, רָקִיעַ, שְׁחָקִים, זְבוּל, מָכוֹן, מָעוֹן, עֲרָבוֹת. וּמוֹנֶה לָהֶם כְּסִדְרָן: וִילוֹן אֵינוֹ מְשַׁמֵּשׁ כְּלוּם, רָקִיעַ יֵשׁ בּוֹ חַמָּה וּלְבָנָה, כּוֹכָבִים וּמַזָּלוֹת וְכוּ׳:\",2,0],[2,136,19,8,\"תּוֹרַת ה׳ תְּמִימָה. גַּם הִיא מְאִירָה כַּשֶּׁמֶשׁ, כְּמוֹ שֶׁנֶּאֱמַר בְּסוֹף הָעִנְיָן מְאִירַת עֵינָיִם וְאוֹמֵר (משלי ו:כג) ״כִּי נֵר מִצְוָה וְתוֹרָה אוֹר״. דָּבָר אַחֵר: וְאֵין נִסְתָּר מֵחַמָּתוֹ לְיוֹם הַדִּין וְלִהַט אוֹתָם הַיּוֹם הַבָּא (מלאכי ג:יט), אֲבָל תּוֹרַת ה׳ תְּמִימָה הִיא מְשִׁיבַת נָפֶשׁ לְדַרְכֵי חַיִּים וּמְגִנָּה הִיא עַל לוֹמְדֶיהָ מֵאוֹתוֹ לַהַט, כְּמוֹ שֶׁנֶּאֱמַר ״וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא וְגוֹמֵר״ (מלאכי ג:כ):\",1,0],[2,136,19,8,\"עֵדוּת ה׳ נֶאֱמָנָה. נֶאֱמֶנֶת הִיא לְהָעִיד בְּלוֹמְדֶיהָ:\",2,0],[2,136,19,8,\"מְשִׁיבַת נָפֶשׁ. מְשִׁיבָתוֹ מִדַּרְכֵי מִיתָה לְדַרְכֵי חַיִּים. תּוֹרַת, עֵדוּת, פִּקּוּדֵי, מִצְוַת, יִרְאַת, מִשְׁפְּטֵי – שִׁשָּׁה, כְּנֶגֶד שִׁשָּׁה סִדְרֵי מִשְׁנָה (ברכות יא:), וּבֵין כָּל שֵׁם וָשֵׁם חֲמִשָּׁה תֵּבוֹת עִם הַשֵּׁם עַצְמוֹ, כְּנֶגֶד חֲמִשָּׁה חוּמְשֵׁי תּוֹרָה. וְחוֹתֵם בְּסוֹפָן: אֱמֶת צָדְקוּ יַחְדָּו. כֻּלָּם יַחַד מְתֻקָּנִים בְּחֶסֶד וֶאֱמֶת:\",3,0],[2,136,19,8,\"מַחְכִּימַת פֶּתִי. נוֹתֶנֶת חָכְמָה לַפְּתָאִים:\",4,0],[2,136,19,9,\"בָּרָה. מַצְהֶרֶת:\",1,0],[2,136,19,11,\"וְנֹפֶת צוּפִים. וּמֶתֶק צוּפִים בְּרוֹיְ״קָאשׁ בְּלַעַ״ז. וּמְנַחֵם פָּתַר וְנֹפֶת לְשׁוֹן טִפָּה, וְכֵן ״נֹפֶת תִּטֹּפְנָה״ (משלי ה:ג), ״נָפַתִּי מִשְׁכָּבִי״ (משלי ז:יז) (ס״א אינו):\",1,0],[2,136,19,12,\"בְּשָׁמְרָם עֵקֶב רָב. נִזְהַרְתִּי בִּשְׁמִירָתָם בִּשְׁבִיל רֹב טוּבְךָ אֲשֶׁר צָפַנְתָּ (תהלים לא:כ), וְלַלָּשׁוֹן הַזֶּה עֵקֶב כְּמוֹ ״עֵקֶב אֲשֶׁר שָׁמַע אַבְרָהָם בְּקוֹלִי״ (בראשית כו:ה). דָּבָר אַחֵר: עֵקֶב רָב. סוֹפָן שֶׁל תַּלְמִידֵי חֲכָמִים לָבֹא לִידֵי גְדֻלָּה. עֵקֶב לְשׁוֹן סוֹף, וְיֵשׁ לוֹ חָבֵר בִּלְשׁוֹן מִשְׁנָה: עִקְּבוֹת מְשִׁיחָא (סוטה ט:טו):\",1,0],[2,136,19,13,\"שְׁגִיאוֹת מִי יָבִין. אֲנִי נִזְהַרְתִּי בָּהֶם, אֲבָל אִי אֶפְשָׁר לְהִזָּהֵר שֶׁלֹּא אֶשְׁגֶּה בָּהֶם, וְאַתָּה נַקֵּנִי מִנִּסְתָּרוֹת שֶׁנִּסְתְּרוּ מִמֶּנִּי, וְלֹא יָדַעְתִּי בְּחֶטְאִי בִּשְׁגָגָה:\",1,0],[2,136,19,14,\"גַּם מִזֵּדִים. מִן הַזְּדוֹנוֹת:\",1,0],[2,136,19,14,\"אָז אֵיתָם. אֶהְיֶה תָּמִים. אָמְרוּ חֲכָמִים : לְמָה דָּוִד דּוֹמֶה? לְכוּתִי הַמְחַזֵּר עַל הַפְּתָחִים, וְהֵם מַעֲרִימִים בַּדָּבָר יוֹתֵר מִכָּל אָדָם: תְּנוּ לִי מַיִם לִשְׁתּוֹת, דָּבָר שֶׁאֵין בּוֹ חֶסְרוֹן כִּיס. מִשֶּׁשָּׁתָה אָמַר: יֵשׁ כָּאן בָּצָל קָטָן? מִשֶּׁנָּתְנוּ לוֹ אוֹמֵר: יֵשׁ בָּצָל בְּלֹא מֶלַח? מִשֶּׁנָּתְנוּ לוֹ אָמַר: תְּנוּ לִי מְעַט לֶחֶם, שֶׁלֹּא יַזִּיקֵנִי הַבָּצָל. כָּךְ אָמַר דָּוִד: בִּתְחִלָּה עַל הַשְּׁגָגוֹת, וְאַחַר כָּךְ עַל הַזְּדוֹנוֹת, וְאַחַר כָּךְ עַל הַמְּרָדִים. פְּשָׁעִים אֵלּוּ הַמְּרָדִים, שֶׁמִּתְכַּוֵּן לְהַכְעִיס, וְכֵן הוּא אוֹמֵר (מלכים ב ג:ז): ״מֶלֶךְ מוֹאָב פָּשַׁע בִּי״:\",2,0],[2,136,19,15,\"יִהְיוּ לְרָצוֹן. לְפִיּוּס, לְרַצּוֹתְךָ:\",1,0],[2,136,20,2,\"יַעַנְךָ ה׳ בְּיוֹם צָרָה. הַמִּזְמוֹר הַזֶּה עַל שֵׁם שֶׁהָיָה שׁוֹלֵחַ אֶת יוֹאָב וְאֶת כָּל יִשְׂרָאֵל לַמִּלְחָמָה, וְהוּא הָיָה עוֹמֵד בִּירוּשָׁלַיִם וּמִתְפַּלֵּל עֲלֵיהֶן, כְּעִנְיָן שֶׁנֶּאֱמַר ״טוֹב כִּי תִהְיֶה לָנוּ מֵעִיר לַעֲזוֹר״ (שמואל ב יח:ג); וְאָמְרוּ רַבּוֹתֵינוּ (סנהדרין מט.): אִילְמָלֵא דָוִד, לֹא עָשָׂה יוֹאָב מִלְחָמָה:\",1,0],[2,136,20,2,\"שֵׁם אֱלֹהֵי יַעֲקֹב. שֶׁהִבְטִיחוֹ בְּלֶכְתּוֹ לְחָרָן (בראשית כח:יג-טו), וְשָׁמַר הַבְטָחָתוֹ. לְכָךְ נֶאֱמַר: אֱלֹהֵי יַעֲקֹב:\",2,0],[2,136,20,3,\"מִקֹּדֶשׁ. מֵהֵיכַל קָדְשׁוֹ, שֶׁהוּא שׁוֹכֵן שָׁם:\",1,0],[2,136,20,4,\"מִנְחוֹתֶיךָ וְעוֹלָתְךָ. הֵם הַתְּפִלּוֹת שֶׁאַתֶּם מִתְפַּלְּלִים בַּמִּלְחָמָה:\",1,0],[2,136,20,4,\"יְדַשְּׁנֶה סֶלָה. לְשׁוֹן שׁוּמָן, כְּמוֹ (דברים לא:כ) ״וְאָכַל וְשָׂבַע וְדָשֵׁן״, כְּלוֹמַר: יְקַבְּלֵם בְּרָצוֹן כְּעוֹלוֹת מְחִים:\",2,0],[2,136,20,6,\"נְרַנְּנָה בִּישׁוּעָתֶךָ. כְּשֶׁיּוֹשִׁיעַ אוֹתְךָ הַקָּדוֹשׁ בָּרוּךְ הוּא, נְרַנְּנָה כֻּלָּנוּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,136,20,6,\"וּבִשְׁמוֹ נִדְגֹּל. נִתְאַסֵּף וְנַעֲשֶׂה חַיִל (תהלים ס:יד):\",2,0],[2,136,20,7,\"עַתָּה יָדַעְתִּי. זוֹ הִיא הָרְנָנָה שֶׁנְּרַנֵּן עַתָּה בַּתְּשׁוּעָה זוֹ שֶׁבָּאָה לְיוֹאָב וּלְיִשְׂרָאֵל, יָדַעְתִּי שֶׁחָפֵץ הַמָּקוֹם בִּי וְעָנָנִי מִשְּׁמֵי קָדְשׁוֹ, כִּי תְּשׁוּעָתָם הִיא תְּשׁוּעָתִי:\",1,0],[2,136,20,8,\"אֵלֶּה בָרֶכֶב. יֵשׁ מִן הָאֻמּוֹת שֶׁבּוֹטְחִים בְּרֶכֶב בַּרְזֶל שֶׁלָּהֶם וְיֵשׁ שֶׁבּוֹטְחִים בְּסוּסֵיהֶם, אֲבָל אֲנַחְנוּ בְּשֵׁם ה׳ נַזְכִּיר כִּי לוֹ הַיְשׁוּעָה. נַזְכִּיר לְשׁוֹן הַקְטָרָה וּתְפִלָּה, כְּמוֹ (ישעיהו סו:ג) ״מַזְכִּיר לְבוֹנָה״ (ויקרא ב:ב) ״אֶת אַזְכָּרָתָהּ״. וּלְפִיכָךְ הֵמָּה יִכְרְעוּ וְיִפֹּלוּ:\",1,0],[2,136,20,9,\"וַאֲנַחְנוּ קַּמְנוּ וַנִּתְעוֹדָד. נִתְגַּבֵּר עֲלֵיהֶם, כְּמוֹ ״מְעוֹדֵד עֲנָוִים״ (תהלים קמז:ו), לְשׁוֹן עֹז:\",1,0],[2,136,21,2,\"בְּעָזְּךָ יִשְׂמַח מֶלֶךְ. רַבּוֹתֵינוּ פָּתְרוּהוּ עַל מֶלֶךְ הַמָּשִׁיחַ, וְנָכוֹן הַדָּבָר לְפוֹתְרוֹ עוֹד עַל דָּוִד עַצְמוֹ, לִתְשׁוּבַת אֲחֵרִים שֶׁדָּרְשׁוּ בוֹ שֶׁאַחַר שֶׁלָּקַח אֶת בַּת שֶׁבַע אָמַר מִזְמוֹר זֶה:\",1,0],[2,136,21,3,\"וַאֲרֶשֶׁת. לְשׁוֹן דִּבּוּר, וְאֵין לוֹ דִּמְיוֹן. וּמְנַחֵם הֵבִיא לוֹ חָבֵר: ״כְּרִשְׁיוֹן כּוֹרֶשׁ מֶלֶךְ פָּרַס״ (עזרא ג:ז), וּשְׁנֵיהֶם לְשׁוֹן מִבְטָא שְׂפָתַיִם:\",1,0],[2,136,21,4,\"כִּי תְקַדְּמֶנּוּ בִּרְכוֹת טוֹב. קֹדֶם שֶׁשָּׁאַלְתִּי מִמְּךָ, הִקְדַּמְתָּ לִי בִּרְכָתְךָ עַל יְדֵי נָתָן הַנָּבִיא ״וְהַקִימוֹתִי אֶת זַרְעֲךָ וְגוֹמֵר״ (שמואל ב ז:יב), ״וַהֲכִינֹתִי אֶת כִּסֵּא מַמְלַכְתְּךָ עַל יִשְׂרָאֵל לְעוֹלָם״ (שמואל ב ז:יג):\",1,0],[2,136,21,4,\"תָּשִׁית לְרֹאשׁוֹ עֲטֶרֶת פָּז. ״וַיִּקַּח עֲטֶרֶת מַלְכָּם וַתְּהִי עַל רֹאשׁ דָּוִד״ (שמואל ב יב:ל):\",2,0],[2,136,21,5,\"חַיִּים שָׁאַל מִמְּךָ. כְּשֶׁהָיִיתִי בּוֹרֵחַ לְחוּצָה לָאָרֶץ מִפְּנֵי שָׁאוּל, הָיִיתִי מִתְפַּלֵּל: ״אֶתְהַלֵּךְ לִפְנֵי ה׳ בְּאַרְצוֹת הַחַיִּים״ (תהלים קטז:ט):\",1,0],[2,136,21,5,\"נָתַתָּה לוֹ. שֶׁהֲשִׁיבוֹתַנִי לְאֶרֶץ יִשְׂרָאֵל:\",2,0],[2,136,21,5,\"אֹרֶךְ יָמִים. לְמַלְכוּתִי, שֶׁאָמַרְתָּ: ״וַהֲכִינֹתִי אֶת־כִּסֵּא מַמְלַכְתְּךָ עַד־עוֹלָם״ (שמואל ב ז:יג):\",3,0],[2,136,21,6,\"תְּשַׁוֶּה. מְנַחֵם פָּתַר תְּשַׁוֶּה, ״תָּשִׂים״ (בראשית ו:טז), ״תָּשִׁית״ (תהלים כא:ד), לָשׁוֹן אֶחָד לָהֶם:\",1,0],[2,136,21,7,\"תְּחַדֵּהוּ. לְשׁוֹן חֶדְוָה:\",1,0],[2,136,21,7,\"אֶת פָּנֶיךָ. בְּגַן עֵדֶן. וְרַבּוֹתֵינוּ, שֶׁדְּרָשׁוּהוּ בְּמֶלֶךְ הַמָּשִׁיחַ, הֵבִיאוּ רְאָיָה לַדָּבָר: ״וְעַד עַתִּיק יוֹמַיָּא מְטָה וּקְדָמוֹהִי הַקְרְבוּהִי״ (דניאל ז:יג); וְאוֹמֵר ״וְהִקְרַבְתִּיו וְנִגַּשׁ אֵלָי״ (ירמיה ל:כא):\",2,0],[2,136,21,8,\"בַּל יִמּוֹט. וּבְחֶסֶד עֶלְיוֹן הוּא בּוֹטֵחַ שֶׁלֹּא יִמּוֹט:\",1,0],[2,136,21,9,\"תִּמְצָא יָדְךָ לְכָל אוֹיְבֶיךָ. כָּל מַכַּת יָדְךָ שֶׁיֵּשׁ לְךָ לְהָבִיא, הָבֵא עַל אוֹיְבֶיךָ:\",1,0],[2,136,21,10,\"לְעֵת פָּנֶיךָ. לְעֵת זַעְמְךָ:\",1,0],[2,136,21,10,\"בְּאַפּוֹ יְבַלְּעֵם. תְּפִלָּה הִיא זוֹ:\",2,0],[2,136,21,11,\"פִּרְיָמוֹ מֵאֶרֶץ תְּאַבֵּד. לְהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא מִתְפַּלֵּל שֶׁיְּאַבֵּד זַרְעוֹ שֶׁל עֲמָלֵק הָרָשָׁע:\",1,0],[2,136,21,12,\"כִּי נָטוּ עָלֶיךָ רָעָה. כְּנֶגֶד טִיטוּס הָרָשָׁע, שֶׁאָמַר: הָרַג אֶת עַצְמוֹ! (גיטין נו:):\",1,0],[2,136,21,12,\"בַּל יוּכָלוּ. לַעֲשׂוֹתָהּ:\",2,0],[2,136,21,13,\"כִּי תְשִׁיתֵמוֹ שֶׁכֶם. אֲשֶׁר תָּשִׁית אוֹתָם לְחֵלֶק, שֶׁיְּחַלְּקוּ יִשְׂרָאֵל אֶת מָמוֹנָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיהו כג:יח) ״וְהָיָה סַחְרָהּ וְאֶתְנַנָּהּ וְגוֹמֵר״:\",1,0],[2,136,21,13,\"בְּמֵיתָרֶיךָ תְּכוֹנֵן עַל פְּנֵיהֶם. בְּמֵיתְרֵי קַשְּׁתוֹתֶיךָ תְּכוֹנֵן חִצֶּיךָ וְתַזְמִינֵם לִירוֹת עַל פְּנֵיהֶם:\",2,0],[2,136,21,14,\"רוּמָה ה׳ בְּעֻזֶּךָ. עַל הַקָּמִים, וְנָשִׁירָה וּנְזַמְּרָה (ספרים אחרי אינו):\",1,0],[2,136,22,1,\"אַיֶּלֶת הַשַּׁחַר. שֵׁם כְּלִי שִׁיר. דָּבָר אַחֵר: עַל כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא ״אַיֶּלֶת אֲהָבִים״ (משלי ה:יט) ״הַנִּשְׁקָפָה כְּמוֹ שַׁחַר״ (שיר השירים ו:י); וְרַבּוֹתֵינוּ (מגילה טו:) דְּרָשׁוּהוּ בְּאֶסְתֵּר. וּמְנַחֵם פָּתַר אַיֶּלֶת – לְשׁוֹן מָעוֹז, כְּמוֹ אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה:\",1,0],[2,136,22,1,\"הַשָּׁחַר. לְשׁוֹן שַׁחֲרִית, וּמְנַחֵם פָּתַר לְשׁוֹן בִּקּוּר, כְּמוֹ ״שֹׁחֵר טוֹב יְבַקֵּשׁ רָצוֹן״ (משלי יא:כז), וּכְמוֹ ״לְשַׁחֵר פָּנֶיךָ״ (משלי ז:טו):\",2,0],[2,136,22,2,\"לָמָּה עֲזַבְתָּנִי. עֲתִידָה הִיא לָלֶכֶת בַּגּוֹלָה, וְאָמַר דָּוִד תְּפִלָּה זוֹ עַל הֶעָתִיד:\",1,0],[2,136,22,2,\"רָחוֹק מִישׁוּעָתִי. וּמִדִּבְרֵי שַׁאֲגָתִי:\",2,0],[2,136,22,3,\"אֶקְרָא יוֹמָם. אֲנִי קוֹרֵא לְךָ מִיּוֹם אֶל יוֹם, וְאֵינְךָ עוֹנֶה:\",1,0],[2,136,22,4,\"וְאַתָּה קָדוֹשׁ. וְיוֹשֵׁב לִשְׁמֹעַ תְּהִלּוֹת יִשְׂרָאֵל מִיָּמִים קַדְמוֹנִים:\",1,0],[2,136,22,7,\"וְאָנֹכִי תוֹלַעַת. כָּל יִשְׂרָאֵל מְכַנֶּה כְּאִישׁ אֶחָד:\",1,0],[2,136,22,8,\"יַפְטִירוּ. יִפְתְּחוּ, כְּמוֹ פֶּטֶר רֶחֶם וּפֶטֶר חֲמוֹר (שמות יג:יב), ״פּוֹטֵר מַיִם״ (משלי יז:יד):\",1,0],[2,136,22,9,\"גֹּל אֶל ה׳. כְּמוֹ לָגוֹל, יֵשׁ לָאָדָם לְגוֹלֵל יְהָבוֹ וּמַשָּׂאוֹ לְיוֹצְרוֹ לְמַעַן יְפַלְּטֵהוּ:\",1,0],[2,136,22,10,\"גּוֹחִי. מוֹצִיאִי מוֹשְׁכִי, כְּמוֹ ״יָגִיחַ יַרְדֵּן אֶל פִּיהוּ״ (איוב מ:כג):\",1,0],[2,136,22,10,\"מַבְטִיחִי עַל שְׁדֵי אִמִּי. זִמַּנְתָּ לָאָדָם שָׁדַיִם לִישָּׁעֵן עֲלֵיהֶם לְמִחְיָה:\",2,0],[2,136,22,11,\"עָלֶיךָ הָשְׁלַכְתִּי מֵרָחֶם. נִשְׁלַכְתִּי מֵרֶחֶם מֵאָז הוֹצֵאתַנִי מֵרֶחֶם, כְּמָה דְאַתְּ אָמַר (ישעיהו מו:ג) ״עֲמוּסִים מִנִּי בֶטֶן״ – מֵאָז נוֹלְדוּ הַשְּׁבָטִים נְשָׂאָם וְנִהֲלָם:\",1,0],[2,136,22,13,\"פָּרִים רַבִּים. מַלְכֻיּוֹת חֲזָקִים:\",1,0],[2,136,22,13,\"אַבִּירֵי בָשָׁן. גַּם הוּא לְשׁוֹן פָּרִים בַּבָּשָׁן, שֶׁהֵם שְׁמֵנִים:\",2,0],[2,136,22,13,\"כִּתְּרוּנִי. סְבָבוּנִי כְּכֶתֶר הַמַּקֶּפֶת אֶת הָרֹאשׁ:\",3,0],[2,136,22,14,\"אַרְיֵה טֹרֵף. נְבוּכַדְנֶצַּר (מגילה יא.):\",1,0],[2,136,22,15,\"כַּדּוֹנָג. שַׁעֲוָה הַנִּמּוֹחָה מֵחוֹם הָאֵשׁ:\",1,0],[2,136,22,16,\"מַלְקוֹחָי. הֵם הַחֲנִיכַיִם שֶׁקּוֹרִין פאליי״ש בְּלַעַ״ז, כְּשֶׁאָדָם מֵיצֵר אֵין רוֹק מָצוּי בְּפִיו. וּמְנַחֵם פֵּתַר מַלְקוֹחָי אנטיילא״ש בְּלַעַ״ז, כְּמוֹ ״בַּמֶּלְקָחַיִם לָקַח״ (ישעיה ו:ו) וְהַמַּלְקוֹחַ הֵן הַשִּׁנַּיִם אֲשֶׁר דּוֹמוֹת לְמַלְקְחֵי חָרָשִׁים (ס״א אינו):\",1,0],[2,136,22,16,\"וְלַעֲפַר מָוֶת. לְדַכְּאוֹת מִיתָה:\",2,0],[2,136,22,16,\"תִּשְׁפְּתֵנִי. אַתָּה תּוֹשִׁיבֵנִי, לְשׁוֹן שְׁפִיתַת קְדֵרָה, ״שְׁפֹת הַסִּיר״ (יחזקאל כד:ג), וּמְנַחֵם פָּתַר כָּל לְשׁוֹן שְׁפִיתָה לְשׁוֹן שִׂימָה:\",3,0],[2,136,22,17,\"כָּאֲרִי יָדַי וְרַגְלָי. כְּאִלּוּ הֵם מְדֻכָּאִים בְּפִי אֲרִי, וְכֵן אָמַר חִזְקִיָּה ״כָּאֲרִי כֵּן יְשַׁבֵּר כָּל עַצְמוֹתַי״ (ישעיהו לח:יג):\",1,0],[2,136,22,18,\"אֲסַפֵּר כָּל עַצְמוֹתָי. כְּאֵב עֲצָמַי:\",1,0],[2,136,22,18,\"הֵמָּה יַבִּיטוּ. שְׂמֵחִים לְאֵידִי:\",2,0],[2,136,22,19,\"וְעַל לְבוּשִׁי יַפִּילוּ גוֹרָל. בּוֹזְזִים אֶת נְכָסַי:\",1,0],[2,136,22,20,\"אֱיָלוּתִי. כֹּחִי, כְּמוֹ ״הָיִיתִי כְּגֶבֶר אֵין אַיָּל״ (תהלים פח:ה), וּכְמוֹ ״יֵשׁ לְאֵל יָדִי״ (בראשית לא:כט):\",1,0],[2,136,22,22,\"הוֹשִׁיעֵנִי מִפִּי אַרְיֵה. כַּאֲשֶׁר מִקַּרְנֵי רֵאמִים עֲנִיתָנִי, זֶה הָאֱמוֹרִי, אֲשֶׁר ״כְּגֹבַהּ אֲרָזִים גָּבְהוֹ״ (עמוס ב:ט) שְׁלֹשִׁים וְאֶחָד מְלָכִים (יהושע יב:ט-כד):\",1,0],[2,136,22,23,\"אֲסַפְּרָה שִׁמְךָ לְאֶחָי. בְּהִתְאַסֵּף כָּל כְּנֵסִיּוֹתַי, וְכֵן אוֹמֵר לָהֶם: יִרְאֵי ה׳ הַלְלוּהוּ. אֵלּוּ הַגֵּרִים (תהלים כב:כט), וְכָל זֶרַע יַעֲקֹב:\",1,0],[2,136,22,24,\"וְגוּרוּ. לְשׁוֹן יִרְאָה:\",1,0],[2,136,22,25,\"עֱנוּת עָנִי. צַעֲקַת דַּל, כָּל עֲנִיָּה שֶׁבַּמִּקְרָא לְשׁוֹן צְעָקָה. וְעוֹד יֵשׁ לִפְתּוֹר עֱנוּת לְשׁוֹן הַכְנָעָה, כְּמוֹ ״לַעֲנֹת מִפָּנַי״ (שמות י:ג), שֶׁהוּא נִכְנָע וּמִתְפַּלֵּל לְפָנֶיךָ:\",1,0],[2,136,22,27,\"יֹאכְלוּ עֲנָוִים. לְעֵת הַגְּאֻלָּה, לִימוֹת הַמָּשִׁיחַ:\",1,0],[2,136,22,27,\"יְחִי לְבַבְכֶם לָעַד. כָּל זֶה אוֹמֵר לִפְנֵיהֶם:\",2,0],[2,136,22,28,\"יִזְכְּרוּ וְיָשׁוּבוּ אֶל ה׳. יִזְכְּרוּ הָאוּמּוֹת הָרָעָה שֶׁמְּצָאַתְנוּ כְּשֶׁיִּרְאוּ אֶת הַטּוֹבָה, וְיָשׁוּבוּ אֶל ה׳:\",1,0],[2,136,22,29,\"כִּי לַה׳ הַמְּלוּכָה. כִּי יִרְאוּ שֶׁחוֹזֶרֶת לְךָ הַמְּלוּכָה וְהַמֶּמְשָׁלָה:\",1,0],[2,136,22,30,\"אָכְלוּ וַיִּשְׁתַּחֲווּ כָּל דִּשְׁנֵי אֶרֶץ. הֲרֵי זֶה מִקְרָא מְסֹרָס: אָכְלוּ עֲנָוִים כָּל דִּשְׁנֵי אֶרֶץ וַיִּשְׁתַּחֲווּ לַה׳ בְּהַלֵּל וְהוֹדָאָה עַל הַטּוֹבָה, דִּשְׁנֵי אֶרֶץ טוּב חֵלֶב הָאָרֶץ. כָּל זֶה יִרְאוּ אַפְסֵי הָאָרֶץ וְיָשׁוּבוּ אֶל ה׳:\",1,0],[2,136,22,30,\"לְפָנָיו יִכְרְעוּ. אָז כָּל מֵתֵי הָרְשָׁעִים מִתּוֹךְ גֵּיהִנֹּם, וְלֹא יְרַחֵם עֲלֵיהֶם לְחַיּוֹת אֶת נַפְשָׁם מִגֵּיהִנֹּם:\",2,0],[2,136,22,30,\"וְנַפְשׁוֹ. שֶׁל כָּל אֶחָד וְאֶחָד:\",3,0],[2,136,22,30,\"לֹא חִיָּה. לֹא יְחַיֶּה. רַבּוֹתֵינוּ דָּרְשׁוּ מִן הַמִּקְרָא הַזֶּה, שֶׁהַמֵּתִים לִפְנֵי מִיתָתָם, בְּשָׁעַת נְטִילַת נְשָׁמָה, רוֹאִין פְּנֵי שְׁכִינָה:\",4,0],[2,136,22,31,\"זֶרַע יַעַבְדֶנּוּ וְגוֹ׳. זֶרַע יִשְׂרָאֵל אֲשֶׁר תָּמִיד עוֹבְדִים אוֹתוֹ:\",1,0],[2,136,22,31,\"יְסֻפַּר לַאדֹנָי לַדּוֹר. סָרֵס הַמִּקְרָא וְדָרְשֵׁהוּ: יְסֻפַּר לְדוֹר אַחֲרוֹן לְשֵׁם ה׳ וּלְשַׁבְּחוֹ, אֶת אֲשֶׁר עָשָׂה לְאוֹתוֹ זֶרַע:\",2,0],[2,136,22,32,\"יָבֹאוּ. הָרִאשׁוֹנִים וְיַגִּידוּ צִדְקָתוֹ לְעַם הַנּוֹלָד, כִּי עָשָׂה לָהֶם צְדָקָה:\",1,0],[2,136,23,1,\"מִזְמוֹר לְדָוִד. אָמְרוּ רַבּוֹתֵינוּ : כָּל מָקוֹם שֶׁנֶּאֱמַר ״מִזְמוֹר לְדָוִד״, מְנַגֵּן וְאַחַר כָּךְ שׁוֹרָה עָלָיו שְׁכִינָה. מִזְמוֹר, לְהָבִיא רוּחַ הַקֹּדֶשׁ לְדָוִד. וְכָל שֶׁנֶּאֱמַר בּוֹ ״לְדָוִד מִזְמוֹר״, שָׁרְתָה עָלָיו שְׁכִינָה וְאַחַר כָּךְ אָמַר שִׁירָה:\",1,0],[2,136,23,1,\"ה׳ רוֹעִי. בַּמִּדְבָּר הַזֶּה שֶׁאֲנִי הוֹלֵךְ בּוֹ בָּטוּחַ אֲנִי, שֶׁלֹּא אֶחְסָר כְּלוּם:\",2,0],[2,136,23,2,\"בִּנְאוֹת דֶּשֶׁא. בִּנְוֵה דְּשָׁאִין, לְפִי שֶׁהִתְחִיל לְדַמּוֹת מְזוֹנוֹתָיו לְמִרְעֵה בְּהֵמָה שֶׁאָמַר ה׳ רוֹעִי, נוֹפֵל עַל הַלָּשׁוֹן שֶׁל ה׳ רוֹעִי נְאוֹת דֶּשֶׁא. וּמִזְמוֹר זֶה אָמַר דָּוִד בְּיַעַר חֲרֵת (שמואל א כב:ה). לָמָּה נִקְרָא שְׁמוֹ יַעַר חֲרֵת? שֶׁהָיָה מְנֻגָּב כַּחֶרֶס וְהִרְטִיבוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מִטּוּב שֶׁל הָעוֹלָם הַבָּא (מדרש תהלים כג:ו):\",1,0],[2,136,23,3,\"נַפְשִׁי יְשׁוֹבֵב. רוּחִי, שֶׁהוּפַג בַּצָּרוֹת וּבַמְּנוּסָה, יְשׁוֹבֵב לְקַדְמוּתוֹ:\",1,0],[2,136,23,3,\"בְּמַעְגְּלֵי צֶדֶק. בְּדַרְכֵי מִישׁוֹר, שֶׁלֹּא אֶפּוֹל בְּיַד אוֹיְבִי:\",2,0],[2,136,23,4,\"בְּגֵיא צַלְמָוֶת. בְּאֶרֶץ חֹשֶׁךְ, וְעַל מִדְבַּר זִיף אָמַר (שמואל א כג:יג,כח). כָּל צַלְמָוֶת לְשׁוֹן חֹשֶׁךְ פֵּרְשׁוֹ דוּנַשׁ בֶּן לַבְרַט:\",1,0],[2,136,23,4,\"שִׁבְטְךָ וּמִשְׁעַנְתֶּךָ. יִסּוּרִים שֶׁבָּאוּ עָלַי וּמִשְׁעָן שֶׁאֲנִי בָּטוּחַ עַל חַסְדְּךָ, שְׁנֵיהֶם יְנַחֲמוּנִי – שֶׁיִּהְיוּ לִי לִסְלֹחַ עָוֹן; וּבָטוּחַ אֲנִי, שֶׁתַּעֲרֹךְ לְפָנַי שֻׁלְחָן – הִיא הַמַּלְכוּת:\",2,0],[2,136,23,5,\"דִּשַּׁנְתָּ בַשֶּׁמֶן רֹאשִׁי. כְּבָר נִמְשַׁחְתִּי עַל פִּיךָ לְמֶלֶךְ:\",1,0],[2,136,23,5,\"כּוֹסִי רְוָיָה. לְשׁוֹן שֹׂבַע:\",2,0],[2,136,24,1,\"לַה׳ הָאָרֶץ. אֶרֶץ יִשְׂרָאֵל:\",1,0],[2,136,24,1,\"תֵּבֵל. שְׁאָר אֲרָצוֹת:\",2,0],[2,136,24,2,\"עַל יַמִּים יְסָדָהּ. שִׁבְעָה יַמִּים מַקִּיפִין אֶרֶץ יִשְׂרָאֵל וְאַרְבַּע נְהָרוֹת, יַרְדֵּן, וְיַרְמוּךְ, קַרְמִיוֹן, וּפוּגָה :\",1,0],[2,136,24,3,\"מִי יַעֲלֶה בְהַר ה׳. אַף עַל פִּי שֶׁכָּל יוֹשְׁבֵי תֵבֵל שֶׁלּוֹ, אֵין הַכֹּל כְּדַאי לִיקָרֵב אֵלָיו, אֶלָּא נְקִי כַפַּיִם וְגוֹמֵר:\",1,0],[2,136,24,4,\"לֹא נָשָׂא לַשָּׁוְא נַפְשִׁי. לֹא נִשְׁבַּע בִּשְׁמִי וּבְנַפְשִׁי לַשָּׁוְא. מָצִינוּ לְשׁוֹן שְׁבוּעָה נוֹפֵל עַל נֶפֶשׁ, שֶׁנֶּאֱמַר: ״נִשְׁבַּע ה׳ צְבָאוֹת בְּנַפְשׁוֹ״ (ירמיהו נא:יד):\",1,0],[2,136,24,6,\"זֶה. שֶׁכָּךְ מַעֲשָׂיו, הוּא דּוֹר דֹּרְשָׁו:\",1,0],[2,136,24,7,\"שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם. בִּימֵי שְׁלֹמֹה בְּנוֹ, כְּשֶׁבָּא לְהַכְנִיס אָרוֹן לְבֵית קָדְשֵׁי הַקֳּדָשִׁים, וְדָבְקוּ שְׁעָרִים זוֹ בְּזוֹ, אָמַר עֶשְׂרִים וְאַרְבַּע רְנָנוֹת וְלֹא נַעֲנָה, עַד שֶׁאָמַר: ״אַל תָּשֵׁב פְּנֵי מְשִׁיחֶךָ זָכְרָה לְחַסְדֵי דָּוִיד עַבְדֶּךָ״ (דברי הימים ב ו:מב):\",1,0],[2,136,24,9,\"פִּתְחֵי עוֹלָם. פְּתָחִים שֶׁקְּדֻשָּׁתָן עוֹלָמִית:\",1,0],[2,136,25,1,\"נַפְשִׁי אֶשָּׂא. אֲכַוֵּן לִבִּי:\",1,0],[2,136,25,3,\"הַבּוֹגְדִים רֵיקָם. הַגַּזְלָנִים הַחַמְסָנִים הַמּוֹשִׁיבִים אֶת הָעֲנִיִּים רֵיקָם מִנִּכְסֵיהֶם, כְּמוֹ ״וָאֲחַלְּצָה צוֹרְרִי רֵיקָם״ (תהלים ז:ה):\",1,0],[2,136,25,5,\"הַדְרִיכֵנִי. אַדְרִיצִימוֹ״י בְּלַעַ״ז:\",1,0],[2,136,25,5,\"אוֹתְךָ קִוִּיתִי כָּל הַיּוֹם. הוּא הָעוֹלָם הַזֶּה, שֶׁהוּא יוֹם לָאֻמּוֹת וְלַיְלָה לְיִשְׂרָאֵל:\",2,0],[2,136,25,6,\"כִּי מֵעוֹלָם הֵמָּה. מִימוֹת אָדָם הָרִאשׁוֹן, שֶׁאָמַרְתָּ לוֹ: ״בְּיוֹם אֲכָלְךָ מִמֶּנּוּ מוֹת תָּמוּת״ (בראשית ב:יז), וְנָתַתָּ לוֹ יוֹם מִשֶּׁלְּךָ, שֶׁהוּא אֶלֶף שָׁנִים:\",1,0],[2,136,25,7,\"כְּחַסְדְּךָ זְכָר לִי. הָרָאוּי לְחַסְדְּךָ זְכוֹר לִי, אֵלּוּ מַעֲשִׂים טוֹבִים שֶׁבְּיָדִי:\",1,0],[2,136,25,8,\"טוֹב וְיָשָׁר ה׳. וְחָפֵץ לְהַצְדִּיק בְּרִיּוֹתָיו:\",1,0],[2,136,25,8,\"עַל כֵּן יוֹרֶה חַטָּאִים בַּדָּרֶךְ. תְּשׁוּבָה. דָּבָר אַחֵר: יוֹרֶה חַטָּאִים הָרוֹצְחִים, שֶׁנֶּאֱמַר ״תָּכִין לְךָ הַדֶּרֶךְ וְגוֹ׳״ (דברים יט:ג). מִקְלָט מִקְלָט הָיָה כָּתוּב עַל פָּרָשַׁת דְּרָכִים וְכוּ׳, כִּדְאִיתָא בְּמַכּוֹת (מכות י.-י:):\",2,0],[2,136,25,11,\"לְמַעַן שִׁמְךָ. הָרַב סְלַח לַעֲוֹנִי:\",1,0],[2,136,25,11,\"כִּי רַב הוּא. כִּי נָאֶה לָרַב לִסְלֹחַ עָוֹן רַב:\",2,0],[2,136,25,12,\"מִי זֶה הָאִישׁ יְרֵא ה׳. הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֶנּוּ בְּדֶרֶךְ שֶׁהוּא יִבְחַר, הוּא דֶּרֶךְ הַטּוֹב:\",1,0],[2,136,25,13,\"נַפְשׁוֹ בְּטוֹב תָּלִין. כְּשֶׁיָּלִין בַּקֶּבֶר, תָּלִין בְּטוֹבָה נַפְשׁוֹ:\",1,0],[2,136,25,16,\"כִּי יָחִיד וְעָנִי אָנִי. וַעֲוֹן רַבִּים תָּלוּי בִּי, וּלְנֶגְדָּן אֲנִי יָחִיד. לְפִיכָךְ פְּנֵה אֵלַי וְחָנֵּנִי, כִּי תְפִלָּתִי צְרִיכָה לִתְשׁוּעַת כָּל יִשְׂרָאֵל:\",1,0],[2,136,25,18,\"רְאֵה עָנְיִי וַעֲמָלִי. וְעַל יְדֵיהֶם שָׂא לְכָל חַטֹּאותָי:\",1,0],[2,136,25,19,\"וְשִׂנְאַת חָמָס. שֶׁלֹּא כַּדִּין:\",1,0],[2,136,25,21,\"יִצְּרוּנִי. יִשְׁמְרוּנִי:\",1,0],[2,136,26,1,\"שָׁפְטֵנִי ה׳. וּבְמָקוֹם אַחֵר הוּא אוֹמֵר: ״אַל תָּבֹא בְמִשְׁפָּט וְגוֹ׳״ (תהלים קמג:ב). אָמַר דָּוִד: כְּשֶׁאַתָּה דָּן אֶת הָרְשָׁעִים, שָׁפְטֵנִי, כִּי לְפִי הָרְשָׁעִים אֲנִי צַדִּיק, וּכְשֶׁאַתָּה דָּן אֶת הַצַּדִּיקִים, אַל תְּבִיאֵנִי בְמִשְׁפָּט:\",1,0],[2,136,26,4,\"וְעִם נַעֲלָמִים. הַנִּכְנָסִין בַּסֵּתֶר, לַעֲשׂוֹת בַּמַּחְשָׁךְ מַעֲשֵׂיהֶם (ישעיה כט:טו):\",1,0],[2,136,26,4,\"לֹא אָבוֹא. אֵינִי רָגִיל לָבוֹא וְלִיכָּנֵס בִּמְקַהֲלָם:\",2,0],[2,136,26,6,\"בְּנִקָּיוֹן. שֶׁאֵין גָּזֵל בַּמִּצְווֹת שֶׁאֲנִי מְקַיֵּם. לוּלָב הַגָּזוּל פָּסוּל (סוכה ג.):\",1,0],[2,136,26,7,\"לַשְׁמִעַ. כְּמוֹ לְהַשְׁמִיעַ:\",1,0],[2,136,26,7,\"כָּל נִפְלְאוֹתֶיךָ. זֶה הַלֵּל שֶׁיֵּשׁ בּוֹ לְשֶׁעָבַר, וְיֵשׁ בּוֹ לְגוֹג, וְיֵשׁ בּוֹ לִימוֹת הַמָּשִׁיחַ, וְיֵשׁ בּוֹ לֶעָתִיד לָבֹא:\",2,0],[2,136,26,10,\"זִמָּה. כָּל זִמָּה שֶׁבַּמִּקְרָא לְשׁוֹן מַחֲשָׁבָה, יֵשׁ לְטוֹבָה וְיֵשׁ לְרָעָה:\",1,0],[2,136,26,12,\"רַגְלִי עָמְדָה בְמִישׁוֹר. בְּדֶרֶךְ יְשָׁרָה:\",1,0],[2,136,27,3,\"בְּזֹאת אֲנִי בוֹטֵחַ. בְּמַה שֶׁאָמַר לְמַעְלָה ה׳ מָעוֹז חַיַּי:\",1,0],[2,136,27,4,\"וּלְבַקֵּר בְּהֵיכָלוֹ. לֵירָאוֹת שָׁם בְּכָל בֹּקֶר וָבֹקֶר. כָּךְ פֵּרְשׁוֹ דּוֹנָשׁ, וּמְנַחֵם חִבְּרוֹ עִם ״לֹא יְבַקֵּר בֵּין טוֹב לָרָע״ (ויקרא כז:לג), אֲבָל דּוֹנָשׁ פָּתַר לְשׁוֹן בֹּקֶר:\",1,0],[2,136,27,5,\"כִּי יִצְפְּנֵנִי בְּסֻכֹּה. בָּטוּחַ אֲנִי שֶׁיִּצְפְּנֵנִי בְּבֵית מִקְדָּשׁוֹ, וְשָׁנִינוּ בְּסֵדֶר עוֹלָם (סדר עולם רבה יח) שֶׁהַמִּקְרָא הַזֶּה נֶאֱמַר עַל יוֹאָשׁ בֶּן אֲחַזְיָה שֶׁהִסְתִּירָתוֹ יְהוֹשֶׁבַע אֲחוֹתוֹ בַּעֲלִיַּת בֵּית קָדְשֵׁי הַקֳּדָשִׁים, כְּעִנְיָן שֶׁנֶּאֱמַר ״וַיְהִי אִתָּהּ בֵּית ה׳ מִתְחַבֵּא שֵׁשׁ שָׁנִים״ (מלכים ב יא:ג):\",1,0],[2,136,27,5,\"בְּצוּר יְרוֹמְמֵנִי. הֶעֱמִיד עַל סֶלַע רַגְלִי (תהלים מ:ג):\",2,0],[2,136,27,6,\"זִבְחֵי תְרוּעָה. זְבָחִים שֶׁאוֹמֵר עֲלֵיהֶם שִׁיר:\",1,0],[2,136,27,8,\"לְךָ אָמַר לִבִּי בַּקְּשׁוּ פָנָי. בִּשְׁבִילְךָ, בִּשְׁלִיחוּתֶיךָ אוֹמֵר (לִי) לִבִּי: בַּקְּשׁוּ כֻּלְּכֶם, יִשְׂרָאֵל, אֶת פָּנַי; וַאֲנִי שׁוֹמֵעַ לוֹ, אֶת פָּנֶיךָ ה׳ אֲבַקֵּשׁ:\",1,0],[2,136,27,8,\"לְךָ. כְּמוֹ ״הֵן אֲנִי כְפִיךָ לָאֵל״ (איוב לג:ו) – בִּמְקוֹמוֹ, ״אִם לָאֵל תְּרִיבוּן״ (איוב יג:ח) – בִּמְקוֹמוֹ, אַף כָּאן לְךָ אָמַר לִבִּי. בִּמְקוֹמְךָ בָּא אֵלַי לִבִּי לוֹמַר כֵּן:\",2,0],[2,136,27,9,\"אַל תַּט. אַל תַּכְרִיעַ, כְּמוֹ ״וַיֵּט שָׁמַיִם״ (תהלים יח:י):\",1,0],[2,136,27,10,\"כִּי אָבִי וְאִמִּי עֲזָבוּנִי. בִּשְׁעַת תַּשְׁמִישׁ לַהֲנָאָתָן נִתְכַּוְּנוּ; כֵּיוָן שֶׁגָּמְרוּ הֲנָאָתָן, זֶה הוֹפֵךְ פָּנָיו אֵילָךְ וְזֶה הוֹפֵךְ פָּנָיו אֵילָךְ:\",1,0],[2,136,27,10,\"וַה׳ יַאַסְפֵנִי. הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אֶת הַטִּפָּה וְצָר אֶת הָעֻבָּר (ויקרא רבה יד, ה):\",2,0],[2,136,27,12,\"בְּנֶפֶשׁ צָרָי. בְּתַאֲוַת שׂוֹנְאַי, לִהְיוֹת תַּאֲוָתָם מִתְקַיֶּמֶת עָלַי:\",1,0],[2,136,27,12,\"וִיפֵחַ חָמָס. דּוֹבְרֵי רָעָה. לָשׁוֹן אַחֵר: לְשׁוֹן מוֹקֵשׁ (ס״א אינו):\",2,0],[2,136,27,13,\"לוּלֵא הֶאֱמַנְתִּי וְגוֹ׳. אִם לֹא שֶׁהֶאֱמַנְתִּי בְּהַקָּדוֹשׁ בָּרוּךְ הוּא, כְּבָר קָמוּ בִי אוֹתָם עֵדֵי שֶׁקֶר וְכִלּוּנִי. לוּלֵא נָקוּד עָלָיו, לְמִדְרָשׁ שֶׁדָּרְשׁוּ רַבּוֹתֵינוּ (ברכות ד.): יוֹדֵעַ אֲנִי שֶׁאַתָּה נוֹתֵן שָׂכָר לַצַּדִּיקִים לָעוֹלָם הַבָּא, אֲבָל אֵינִי יוֹדֵעַ אִם יֵשׁ לִי חֵלֶק עִמָּהֶם אִם לָאו:\",1,0],[2,136,27,14,\"וְקַוֵּה אֶל ה׳. וְאִם לֹא תִתְקַבֵּל תְּפִלָּתְךָ, חֲזוֹר וְקַוֵּה (ברכות לב:):\",1,0],[2,136,28,3,\"אַל תִּמְשְׁכֵנִי. אַל תַּרְגִּילֵנִי עִם רְשָׁעִים. אטרירא״ש מו״י בְּלַעַ״ז:\",1,0],[2,136,28,7,\"וּמִשִּׁירִי אֲהוֹדֶנּוּ. וּמַה הִיא הַהוֹדָיָה? ה׳ עֹז לָמוֹ לְאוֹתָן הַתְּלוּיִין בּוֹ בְּעֵת שֶׁמָּעוֹז יְשׁוּעוֹת מְשִׁיחוֹ הוּא:\",1,0],[2,136,28,9,\"וּרְעֵם. לְשׁוֹן מִרְעֶה:\",1,0],[2,136,29,1,\"הָבוּ לַה׳. הָכִינוּ לַה׳ וְהָכִינוּ לוֹ, אַתֶּם, בְּנֵי אֵילֵי הָאָרֶץ; מִכָּאן שֶׁאוֹמְרִים ׳אָבוֹת׳ (ראש השנה לב.). וּמְנַחֵם חִבֵּר הָבוּ לְשׁוֹן נְתִינָה:\",1,0],[2,136,29,1,\"אֵלִים. שָׂרִים (ס״א אינו):\",2,0],[2,136,29,1,\"הָבוּ לַה׳ כָּבוֹד וָעֹז. מִכָּאן שֶׁאוֹמְרִים גְּבוּרוֹת (ראש השנה לב.):\",3,0],[2,136,29,2,\"כְּבוֹד שְׁמוֹ. זוֹ קְדֻשַּׁת הַשֵּׁם (ראש השנה לב.), וְיֵשׁ בְּמִזְמוֹר זֶה שְׁמוֹנֶה עֶשְׂרֵה אַזְכָּרוֹת, וּכְנֶגְדָּן תִּקְּנוּ שְׁמוֹנֶה עֶשְׂרֵה בְּרָכוֹת:\",1,0],[2,136,29,3,\"קוֹל ה׳ עַל הַמָּיִם. עַל יַם סוּף יַרְעֵם מִשָּׁמַיִם ה׳ וְגוֹ׳ (תהלים יח:יד):\",1,0],[2,136,29,3,\"הִרְעִים. טוֹרְמִינְטָאוּ״שׁ בְּלַעַ״ז:\",2,0],[2,136,29,4,\"קוֹל ה׳ בַּכֹּחַ. בְּשָׁעַת מַתַּן תּוֹרָה צִמְצֵם אֶת קוֹלוֹ לְפִי כֹּחָן שֶׁל יִשְׂרָאֵל, שֶׁנֶּאֱמַר ״וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל״ (שמות יט:יט) – בְּקוֹלוֹ שֶׁל מֹשֶׁה (ברכות מה.):\",1,0],[2,136,29,5,\"קוֹל ה׳ שׁוֹבֵר אֲרָזִים. הָאֻמּוֹת, כְּעִנְיָן שֶׁנֶּאֱמַר (שמואל א ז:י) ״וַיַּרְעֵם ה׳ בְּקוֹל גָּדוֹל עַל פְּלִשְׁתִּים וְגוֹ׳״, (ישעיהו ל:לא) ״כִּי מִקּוֹל ה׳ יֵחַת אַשּׁוּר״. וּבִשְׁעַת מַתַּן תּוֹרָה (דברים ה:כג) ״כִּי מִי כָל בָּשָׂר וְגוֹמֵר וַיֶּחִי״ – אַתָּה שָׁמַעְתָּ וְחָיִיתָ, וְאֻמּוֹת הָעוֹלָם שׁוֹמְעִים וּמֵתִים (תנחומא, שמות כה):\",1,0],[2,136,29,6,\"וַיַּרְקִידֵם כְּמוֹ עֵגֶל. אֶת הָאֲרָזִים וְאֶת הֶהָרִים שֶׁבָּאוּ לִשְׁמֹעַ מַתַּן תּוֹרָה (שמות יט:יז):\",1,0],[2,136,29,6,\"לְבָנוֹן וְשִׂרְיוֹן. שֵׁמוֹת הֶהָרִים:\",2,0],[2,136,29,7,\"חוֹצֵב לַהֲבוֹת אֵשׁ. טַיְלַנְ״ט בְּלַעַ״ז, וְרַבּוֹתֵינוּ פֵּרְשׁוּ (מכילתא יתרו בחדש ט), שֶׁהָיָה הַדִּבּוּר שֶׁל עֲשֶׂרֶת הַדִּבְּרוֹת יוֹצֵא בְּלַהֲבוֹת אֵשׁ מִפִּיו וְנֶחְקָק עַל הַלּוּחוֹת כְּתַבְנִיתָם:\",1,0],[2,136,29,8,\"יָחִיל מִדְבָּר. לְשׁוֹן ״חִיל כַּיּוֹלֵדָה״ (ירמיה ו:כד; תהלים מח:ז):\",1,0],[2,136,29,8,\"יָחִיל ה׳ מִדְבַּר קָדֵשׁ. הוּא מִדְבַּר סִינַי, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ בְּמַסֶּכֶת שַׁבָּת (שבת פט.): חֲמִשָּׁה שֵׁמוֹת נִקְרְאוּ לוֹ: מִדְבַּר סִינַי, מִדְבַּר צִין, מִדְבַּר קָדֵשׁ, מִדְבַּר קַדְמוֹת, מִדְבַּר פָּארָן. מִדְבַּר קָדֵשׁ שֶׁנִּתְקַדְּשׁוּ יִשְׂרָאֵל עָלָיו:\",2,0],[2,136,29,9,\"קוֹל ה׳ יְחוֹלֵל אַיָּלוֹת. יְפַחִיד וְיָחִיל לֶעָתִיד אֶת הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, שֶׁהֵם עַכְשָׁיו עוֹמְדִים בְּחוֹזֶק כְּאַיָּלוֹת, כְּעִנְיָן שֶׁנֶּאֱמַר ״מְשַׁוֶּה רַגְלַי כָּאַיָּלוֹת״ (תהלים יח:לד). אָמַר רַבִּי פִּנְחָס: כָּאֵילִים אֵין כְּתִיב כָּאן אֶלָּא כָּאַיָּלוֹת, כַּנְּקֵבוֹת שֶׁרַגְלֵי הַנְּקֵבוֹת עוֹמְדוֹת בְּיוֹשֶׁר יוֹתֵר מִן הַזְּכָרִים. לָשׁוֹן אַחֵר: יְחוֹלֵל קְרִיאָ״ה בְּלַעַ״ז, כְּמוֹ ״לִפְנֵי גְבָעוֹת חוֹלָלְתִּי״ (משלי ח:כה) (ס״א אינו):\",1,0],[2,136,29,9,\"וַיֶּחֱשֹׂף יְעָרוֹת. כְּמוֹ ״מַחְשֹׂף הַלָּבָן״ (בראשית ל:לז), יְקַלֵּף עֲצֵי הַיַּעַר, כְּלוֹמַר יַפְשִׁיט מִכְּבוֹדָם הַמְּשׁוּלִים כַּעֲצֵי הַיַּעַר ״אֲשֶׁר כְּגֹבַהּ אֲרָזִים גָּבְהוֹ״ (עמוס ב:ט):\",2,0],[2,136,29,9,\"וּבְהֵיכָלוֹ. שֶׁיִּבָּנֶה:\",3,0],[2,136,29,9,\"כֻּלּוֹ אוֹמֵר כָּבוֹד. הַכֹּל יְקַלְּסוּהוּ שָׁם וְיֹאמְרוּ:\",4,0],[2,136,29,10,\"ה׳ לַמַּבּוּל יָשָׁב. בִּגְדֻלָּתוֹ יְחִידִי, וְגַם עַתָּה וַיֵּשֶׁב ה׳ לְבַדּוֹ מֶלֶךְ לְעוֹלָם, ״וְהָאֱלִילִים כָּלִיל יַחֲלֹף״ (ישעיה ב:יח), אֲבָל לְעַמּוֹ יִתֵּן עֹז וּבִרְכַּת שָׁלוֹם. וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ בְּמַתַּן תּוֹרָה (מדרש תהלים כט:ב) שֶׁנִּתְפַּחֲדוּ וְנִתְבַּהֲלוּ הָאֻמּוֹת וּבָאוּ לָהֶם אֵצֶל בִּלְעָם וְאָמְרוּ לוֹ: מַה קּוֹל הֶהָמוֹן שֶׁשָּׁמַעְנוּ? שֶׁמָּא מַבּוּל הוּא בָּא לְהָבִיא לָעוֹלָם? אָמַר לָהֶם: כְּבָר נִשְׁבַּע שֶׁלֹּא יָבִיא מַבּוּל, אֶלָּא קוֹל הֶהָמוֹן שֶׁשְּׁמַעְתֶּם, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן תּוֹרָה לְעַמּוֹ:\",1,0],[2,136,30,1,\"שִׁיר חֲנֻכַּת הַבַּיִת. שֶׁיֹּאמְרוּהוּ הַלְוִיִּם בַּחֲנֻכַּת הַבַּיִת בִּימֵי שְׁלֹמֹה:\",1,0],[2,136,30,2,\"אֲרוֹמִמְךָ ה׳ כִּי דִלִּיתָנִי. הִגְבַּהְתָּנִי:\",1,0],[2,136,30,2,\"וְלֹא שִׂמַּחְתָּ אוֹיְבַי לִי. כְּמוֹ עָלַי, שֶׁהָיוּ אוֹמְרִים: אֵין לְדָוִד חֵלֶק לָעוֹלָם הַבָּא, וּכְשֶׁרָאוּ שֶׁבִּשְׁבִילוֹ נִפְתְּחוּ הַדְּלָתוֹת לָאָרוֹן, אָז יָדְעוּ שֶׁמָּחַל לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אוֹתוֹ עָוֹן, וְנֶהֶפְכוּ פְּנֵי שׂוֹנְאֵי דָוִד כְּשׁוּלֵי קְדֵרָה (שבת ל.):\",2,0],[2,136,30,3,\"וַתִּרְפָּאֵנִי. הִיא סְלִיחַת עָוֹן, כְּמוֹ ״וְשָׁב וְרָפָא לוֹ״ (ישעיהו ו:י):\",1,0],[2,136,30,4,\"מִיׇּרְדִי בוֹר. כְּמוֹ מִירִידָתִי לַבּוֹר, שֶׁלֹּא אֵרֵד לַגֵּיהִנֹּם:\",1,0],[2,136,30,5,\"זַמְּרוּ לַה׳ חֲסִידָיו. עַל מָה שֶׁעָשָׂה לִי, כִּי יְכוֹלִים אַתֶּם לַחֲסוֹת בּוֹ שֶׁיֵּיטִיב לָכֶם; וַאֲפִלּוּ אַתֶּם שְׁרוּיִים בְּצַעַר, אַל תִּירָאוּ:\",1,0],[2,136,30,6,\"כִּי רֶגַע. קָטָן בְּאַפּוֹ:\",1,0],[2,136,30,6,\"חַיִּים בִּרְצוֹנוֹ. וְחַיִּים אֲרֻכִּים יֵשׁ בְּהֵרָצוֹתוֹ וּבְהִפָּיְסוֹ (ברכות ז.):\",2,0],[2,136,30,7,\"וַאֲנִי אָמַרְתִּי בְשַׁלְוִי. בְּשַׁלְוָתִי הָיִיתִי חוֹשֵׁב לֹא אֶמּוֹט לְעוֹלָם, אֲבָל אֵין הַדָּבָר בִּרְשׁוּתִי כִּי אִם בִּרְשׁוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא: בִּרְצוֹנוֹ הֶעֱמִיד אֶת הֲרָרִי, אֶת גְּדֻלָּתִי, לִהְיוֹת עֹז, וְכֵיוָן שֶׁהִסְתִּיר פָּנָיו מִמֶּנִּי, מִיָּד הָיִיתִי נִבְהָל:\",1,0],[2,136,30,9,\"אֵלֶיךָ ה׳ אֶקְרָא וְגוֹ׳ וְאֶתְחַנָּן. תָּמִיד לֵאמֹר לְפָנֶיךָ: מַה בֶּצַע בְּדָמִי וְגוֹ׳, וְאַתָּה שָׁמַעְתָּ קוֹלִי וְהָפַכְתָּ מִסְפְּדִי לְמָחוֹל לִי:\",1,0],[2,136,30,12,\"פִּתַּחְתָּ. אֵלַאקְ״שׁ בְּלַעַ״ז, כְּמוֹ (בראשית כד:לב) ״וַיְפַתַּח אֶת הַגְּמַלִּים״, וְרַבּוֹתֵינוּ דָּרְשׁוּ כָּל הַמִּזְמוֹר עַל מָרְדְּכַי וְאֶסְתֵּר וְהָמָן, בִּפְסִיקְתָּא זוּטָא (פסיקתא זוטרתא):\",1,0],[2,136,30,12,\"וַאֲנִי אָמַרְתִּי בְשַׁלְוִי, אָמַר הָמָן. אֵלֶיךָ ה׳ אֶקְרָא, אָמְרָה אֶסְתֵּר וְכוּ׳ עַד הָיָה עוֹזֵר לִי. הָפַכְתָּ מִסְפְּדִי לְמָחוֹל לִי, אָמַר מָרְדֳּכַי וְכָל יִשְׂרָאֵל:\",2,0],[2,136,31,3,\"מְצוּדוֹת. פְּלֵיְישִׁי״ץ בְּלַעַ״ז:\",1,0],[2,136,31,4,\"תַּנְחֵנִי. מוֹנַארַאשְׁמוֹ״י בְּלַעַ״ז, כְּמוֹ ״לֵךְ נְחֵה אֶת הָעָם וְגוֹ׳״ (שמות לב:לד):\",1,0],[2,136,31,6,\"בְּיָדְךָ אַפְקִיד רוּחִי. קוֹמַנְדְרִיָ״ה בְּלַעַ״ז, אַפְקִיד רוּחִי תָּמִיד לְפִי שֶׁאַתָּה פָּדִיתָה אוֹתִי מִצָּרָה:\",1,0],[2,136,31,7,\"הַשּׁוֹמְרִים הַבְלֵי שָׁוְא. הַמְצַפִּים לִתְשׁוּעַת עֲבוֹדָה זָרָה:\",1,0],[2,136,31,9,\"הִסְגַּרְתַּנִי. לִיבְרַאשְׁ״מְווִי. וּמְנַחֵם חִבֵּר אוֹתוֹ לְשׁוֹן סְגִירָה, וְכֵן כָּל לְשׁוֹן סָגַר:\",1,0],[2,136,31,10,\"עָשְׁשָׁה. כָּהֲתָה, לְשׁוֹן עֲשָׁשִׁית. שֶׁאָדָם נוֹתֵן זְכוּכִית לְנֶגֶד עֵינָיו לִרְאוֹת לְעֵבֶר הַזְּכוּכִית דָּבָר, אֵין אוֹתָהּ מַרְאָה בְּרוּרָה:\",1,0],[2,136,31,11,\"וַעֲצָמַי עָשֵׁשׁוּ. לְשׁוֹן רָקָב, כְּאִלּוּ אֲכָלָם עָשׁ:\",1,0],[2,136,31,12,\"מִכָּל צוֹרְרַי. מֵאֵת כָּל צוֹרְרַי, הָיִיתִי חֶרְפָּה לְגִדּוּף:\",1,0],[2,136,31,12,\"וְלִשְׁכֵנַי. אֲנִי חֶרְפָּה מְאֹד וּפַחַד לִמְיֻדָּעָי. אֵמִישְׁקְטִיֵישְׁנ״ץ. מִתְפַּחֲדִים עַל קוֹרוֹתַי:\",2,0],[2,136,31,13,\"כִּכְלִי אוֹבֵד. הַהוֹלֵךְ לְאִבּוּד; כָּל לְשׁוֹן אֲבֵדָה, אֵין הַלָּשׁוֹן נוֹפֵל עַל בַּעַל אֲבֵדָה, לוֹמַר ׳הוּא אִבֵּד אוֹתָהּ׳, אֶלָּא ׳הָאֲבֵדָה אוֹבֶדֶת מִמֶּנּוּ׳, כְּמָה דְאַתְּ אָמַר: ״אֲשֶׁר תֹּאבַד מִמֶּנּוּ״ (דברים כב:ג); ״הָאֹבֶדֶת לֹא בִקַּשְׁתֶּם״ (יחזקאל לד:ד):\",1,0],[2,136,31,14,\"דִּבַּת רַבִּים. עֲצַת רַבִּים. דִּבַּת לְשׁוֹן ״דּוֹבֵב שִׂפְתֵי יְשֵׁנִים״ (שיר השירים ז:י) וְכֵן כָּל דִּבָּה שֶׁבַּמִּקְרָא פרלר״יץ בְּלַעַ״ז:\",1,0],[2,136,31,14,\"מָגוֹר מִסָּבִיב. שֶׁמְּיָרְאִין וּמְפַחֲדִין אוֹתִי:\",2,0],[2,136,31,14,\"בְּהִוָּסְדָם. בְּהִתְיַעֲצָם:\",3,0],[2,136,31,14,\"זָמָמוּ. לְשׁוֹן מַחֲשָׁבָה:\",4,0],[2,136,31,16,\"בְּיָדְךָ עִתּוֹתָי. עִתִּים הָעוֹבְרִים עָלַי, עַל פִּיךָ הֵם וּבִגְזֵרוֹתֶיךָ:\",1,0],[2,136,31,18,\"אַל אֵבוֹשָׁה וְגוֹ׳. אַחֲרֵי שֶׁקְּרָאתִיךָ, אֵין נָאֶה שֶׁאֵבוֹשׁ:\",1,0],[2,136,31,18,\"יִדְּמוּ לִשְׁאוֹל. יִשְׁתַּתְּקוּ וְיֵאָלְמוּ לָמוּת:\",2,0],[2,136,31,19,\"הַדּוֹבְרוֹת עַל צַדִּיק עָתָק. שֶׁאוֹמְרוֹת לְשָׁאוּל עָלַי: דָּוִד מְבַקֵּשׁ רָעָתְךָ:\",1,0],[2,136,31,19,\"עָתָק. סָרָה, דָּבָר שֶׁאֵינוֹ; כְּמוֹ ״וַיַּעְתֵּק מִשָּׁם״ (בראשית יב:ח). וְדוּנָשׁ פָּתַר אוֹתוֹ לְשׁוֹן דָּבָר גָּדוֹל וְקָשֶׁה, כְּמוֹ ״עָתְקוּ גַם גָּבְרוּ חָיִל״ (איוב כא:ז); ״הוֹן עָתֵק״ (משלי ח:יח); ״וְלִמְכַסֶּה עָתִיק״ (ישעיה כג:יח) (ס״א אינו):\",2,0],[2,136,31,20,\"מָה רַב טוּבְךָ. יָדַעְתִּי לָעוֹלָם הַבָּא יֵשׁ שָׂכָר טוֹב לִירֵאֶיךָ, וּמִכָּל מָקוֹם בָּעוֹלָם הַזֶּה שֶׁהָרְשָׁעִים מַקִּיפִים אוֹתָם, אֲנִי מִתְפַּלֵּל עֲלֵיהֶם שֶׁתַּסְתִּירֵם בְּסֵתֶר פָּנֶיךָ:\",1,0],[2,136,31,21,\"מֵרֻכְסֵי אִישׁ. מֵחֲבוּרֵי רְשָׁעִים הַמִּתְקַשְּׁרִים יַחַד לְהָרַע לָהֶם:\",1,0],[2,136,31,22,\"בְּעִיר מָצוֹר. בִּקְעִילָה, כְּשֶׁאָמַר שָׁאוּל עָלַי ״נִסְגַּר לָבוֹא בְּעִיר דְּלָתַיִם וּבְרִיחַ״ (שמואל א כג:ז):\",1,0],[2,136,31,23,\"וַאֲנִי אָמַרְתִּי בְחָפְזִי. כְּשֶׁיָּצָאתִי מִקְּעִילָה וּבָאתִי אֶל מִדְבַּר מָעוֹן, וְהָיִיתִי נֶחְפָּז לָלֶכֶת מִפְּנֵי שָׁאוּל כִּי הִשִּׂיגַנִי, וְשָׁאוּל וַאֲנָשָׁיו עוֹטְרִים אֵלַי וְאֶל אֲנָשַׁי לְתָפְשָׂם (שמואל א כג:כו):\",1,0],[2,136,31,23,\"אָמַרְתִּי. בְּלִבִּי:\",2,0],[2,136,31,23,\"נִגְרַזְתִּי. נִכְרַתְּתִי, לְשׁוֹן גַּרְזֶן הַכּוֹרֵת אֶת הָעֵץ. עַל שֵׁם גְּזִירָתוֹ נִקְרָא גַּרְזֶן. כָּךְ פֵּרֵשׁ דּוּנַשׁ. וּמְנַחֵם חִבְּרוֹ כְּמוֹ ״נִגְרַשְׁתִּי״ (יונה ב:ה), וְאֵין לוֹ דִּמְיוֹן בַּתּוֹרָה (ס״א אינו):\",3,0],[2,136,31,24,\"אֱמוּנִים נֹצֵר ה׳. שׁוֹמֵר ה׳ אֶת הַמַּאֲמִינִים בִּישׁוּעָתוֹ וְסוֹמְכִים עָלָיו:\",1,0],[2,136,31,24,\"עַל יֶתֶר. מִדָּה בְּמִדָּה, מְכֻוֶּנֶת כְּחֵץ עַל יֶתֶר הַקֶּשֶׁת. אוֹ יֵשׁ לִפְתּוֹר עַל יֶתֶר – חֶבֶל כְּנֶגֶד חֶבֶל, קַו כְּנֶגֶד קַו. לָשׁוֹן אַחֵר: יֶתֶר הוּא לְשׁוֹן גַּאֲוָה, כְּמוֹ ״יִתְרָה עָשָׂה״ (ישעיהו טו:ז), פֵּרוּשׁ וּמְשַׁלֵּם עַל יֶתֶר – בְּגַאֲוָה לְעוֹשֵׂי גַאֲוָה (ס״א אינו):\",2,0],[2,136,31,25,\"חִזְקוּ וְיַאֲמֵץ לְבַבְכֶם. כְּמוֹ שֶׁרְאִיתֶם שֶׁעָשָׂה לִי לְהוֹשִׁיעֵנִי, שֶׁהוֹחַלְתִּי לוֹ:\",1,0],[2,136,32,1,\"לְדָוִד מַשְׂכִּיל. אָמְרוּ חֲכָמִים (פסחים קיז.): כָּל מִזְמוֹר שֶׁנֶּאֱמַר בּוֹ מַשְׂכִּיל, עַל יְדֵי מְתוּרְגְּמָן אֲמָרוֹ:\",1,0],[2,136,32,1,\"אַשְׁרֵי נְשׂוּי פֶּשַׁע. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹשֵׂא פֶּשַׁע וּמְכַסֶּה חֲטָאָיו:\",2,0],[2,136,32,1,\"נְשׂוּי. אַנְפוֹרְדוֹנִי״ץ בְּלַעַ״ז:\",3,0],[2,136,32,2,\"וְלֹא יַחְשֹׁב לוֹ עָוֺן. וּבִלְבַד שֶׁלֹּא תִּהְיֶה בְּרוּחוֹ רְמִיָּה לִהְיוֹת בְּדַעְתּוֹ לָשׁוּב אֶל קִיאוֹ (משלי כו:יא):\",1,0],[2,136,32,3,\"כִּי הֶחֱרַשְׁתִּי. כַּאֲשֶׁר הֶחֱרַשְׁתִּי מִלְּהִתְוַדּוֹת עַל פְּשָׁעַי לְפָנֶיךָ:\",1,0],[2,136,32,3,\"בָּלוּ עֲצָמָי. מֵרוֹב אַנְחוֹתַי וּדְאָגוֹתַי כָּל הַיּוֹם שֶׁהָיִיתִי דּוֹאֵג מִפְּנֵי הַפֻּרְעָנוּת:\",2,0],[2,136,32,4,\"כִּי יוֹמָם וָלַיְלָה. הָיָה כָבֵד עָלַי מוֹרָא יָדְךָ וּגְזֵרוֹתֶיךָ:\",1,0],[2,136,32,4,\"נֶהְפַּךְ לְשַׁדִּי. לַחְלוּחַ שֶׁלִּי, וְכֵן ״לְשַׁד הַשֶּׁמֶן״ (במדבר יא:ח), לַחְלוּחַ שֶׁמֶן. כָּךְ פֵּרְשׁוֹ דוּנַשׁ, וּמְנַחֵם חִבֵּר לְשׁוֹן שְׁדִידָה כְּמוֹ ״מִשֹּׁד עֲנִיִּים״ (תהלים יב:ו), ״רְשָׁעִים זוּ שַׁדּוּנִי״ (תהלים יז:ט):\",2,0],[2,136,32,4,\"בְּחַרְבוֹנֵי קַיִץ. עַד שֶׁיִּיבַשׁ בְּחֹרֶב הַקַּיִץ מִפְּנֵי דַּאֲגַת כֹּבֶד יָדְךָ, שֶׁהָיִיתִי דּוֹאֵג עַל חַטָּאתִי; וּלְפִיכָךְ:\",3,0],[2,136,32,5,\"חַטָּאתִי אוֹדִיעֲךָ. תָּמִיד וּלְשׁוֹן הֹוֶה הוּא, כִּי אָמַרְתִּי: טוֹב שֶׁאוֹדֶה עֲלֵי פְשָׁעַי לַה׳. וְעַתָּה כְּשֶׁהוֹדֵיתִי וְאָמַרְתִּי לְנָתָן הַנָּבִיא ״חָטָאתִי״ (שמואל ב יב:יג), נָשָׂאתָ עֲוֺן חַטָּאתִי, כְּעִנְיָן שֶׁנֶּאֱמַר (שם): ״גַּם ה׳ הֶעֱבִיר חַטָּאתְךָ וְגוֹ׳״:\",1,0],[2,136,32,6,\"לְעֵת מְצוֹא. בְּהִמָּצְאֲךָ לְקַבֵּל תְּפִלָּתוֹ, וּמַה הִיא זֹאת? רַק לְשֵׁטֶף מַיִם רַבִּים אֲשֶׁר לֹא יַגִּיעוּ אֵלָיו – שֶׁלֹּא יִפֹּל בְּיַד הָאֻמּוֹת, שֶׁהֵם כְּמַיִם שׁוֹטְפִים. וְכֵן מָצִינוּ שֶׁהִתְפַּלֵּל דָּוִד עַל זֹאת וְאָמַר: ״נִפְּלָה נָּא בְיַד ה׳ כִּי רַבִּים רַחֲמָיו וּבְיַד אָדָם אַל אֶפֹּלָה״ (שמואל ב כד:יד):\",1,0],[2,136,32,7,\"אַתָּה סֵתֶר לִי. לְהִסָּתֵר בְּצִלְּךָ מִפְּנֵי פַּחַד אוֹיֵב:\",1,0],[2,136,32,7,\"תִּצְּרֵנִי. כְּמוֹ תִּשְׁמְרֵנִי:\",2,0],[2,136,32,7,\"רָנֵּי פַלֵּט. רִנָּה שֶׁל הַצָּלָה:\",3,0],[2,136,32,7,\"תְּסוֹבְבֵנִי. לְשׁוֹן הֹוֶה הוּא: סִבַּבְתַּנִי תָּמִיד רָנֵּי פַלֵּט. וְכָךְ אָמַרְתָּ לִי:\",4,0],[2,136,32,8,\"אַשְׂכִּילְךָ וְאוֹרְךָ. דֶּרֶךְ לָלֶכֶת:\",1,0],[2,136,32,8,\"אִיעֲצָה. אֶרְמֹז לְךָ בְּעֵינִי רֶמֶז מַה תַּעֲשֶׂה, אִיעֲצָה לְשׁוֹן קְרִיצַת עַיִן כְּמוֹ ״עֹצֵם עֵינָיו לַחְשֹׁב תַּהְפֻּכוֹת״ (משלי טז:ל):\",2,0],[2,136,32,9,\"אַל תִּהְיוּ כְּסוּס כְּפֶרֶד. שֶׁאֵינוֹ מֵבִין בֵּין הָעוֹשֶׂה לוֹ טוֹבָה לְעוֹשֶׂה לוֹ רָעָה, כְּשֶׁאַתָּה מְמַתְּגָם בּוֹ בְּמֶתֶג הוּא בּוֹלֵם פִּיו וּמְכַסְכֵּס בְּרִסְנוֹ, וּכְשֶׁאַתָּה מְקָרְדוֹ וּמְקַרְצְפוֹ אַתָּה צָרִיךְ לִבְלֹם וְלִסְגֹּר פִּיו וּלְיַסְּרוֹ בְּמֶתֶג וָרֶסֶן כְּשֶׁאַתָּה מְעַדֵּהוּ עֲדִי וּמְיַפֵּהוּ:\",1,0],[2,136,32,9,\"בַּל קְרֹב אֵלֶיךָ. שֶׁלֹּא יִקְרַב אֵלֶיךָ, לְהַזִּיקְךָ כְּשֶׁאַתָּה מְיַפֵּהוּ. בְּמֶתֶג וָרֶסֶן עֶדְיוֹ לִבְלוֹם. בִּשְׁעַת עֶדְיוֹ, שֶׁאַתָּה מְקַרְדּוֹ וּמְקַרְצְפוֹ, אַתָּה צָרִיךְ לְסוֹגְרוֹ בְּמֶתֶג וָרֶסֶן שֶׁלֹּא יִקְרַב אֵלֶיךָ. בְּלִימָה בִּלְשׁוֹן מִשְׁנָה לְשׁוֹן מַסְגֵּר: פִּיו בָּלוּם, רַגְלָיו מְבֻלָּמוֹת (בכורות מ:). וּמְנַחֵם חִבֵּר לִבְלוֹם וְכֵן ״עַל בְּלִימָה״ (איוב כו:ז) לְשׁוֹן תֹּכֶן (ס״א אינו):\",2,0],[2,136,33,2,\"בְּנֵבֶל עָשׂוֹר. שֶׁל עֶשֶׂר מִינֵי נְעִימָה (ערכין יג:):\",1,0],[2,136,33,7,\"כַּנֵּד. לְשׁוֹן גּוֹבַהּ, וְכֵן תַּרְגּוּם אוּנְקְלוֹס ״נִצְּבוּ כְמוֹ נֵד״ (שמות טו:ח): ״קָמוּ כְשׁוּר״, וְכֵן פֵּרֵשׁ מְנַחֵם, וְאֵין ׳נֵד׳ וְ׳נֹאד׳ שָׁוִין:\",1,0],[2,136,33,7,\"נוֹתֵן בְּאוֹצָרוֹת תְּהוֹמוֹת. תַּחַת הָאָרֶץ:\",2,0],[2,136,33,14,\"הִשְׁגִּיחַ. הִבִּיט:\",1,0],[2,136,33,15,\"הַיּוֹצֵר יַחַד לִבָּם. לֵב כֻּלָּם יַחַד וְיוֹדֵעַ כָּל הַמַּחֲשָׁבוֹת, וְרַבּוֹתֵינוּ (ראש השנה יח.) הֱסִיבוּהוּ אֶל מִמְּכוֹן שִׁבְתּוֹ הִשְׁגִּיחַ, הַיּוֹצֵר יַחַד לִבָּם, וְדָרְשׁוּ מִכָּאן שֶׁכֻּלָּן נִסְקָרִין בִּסְקִירָה אַחַת:\",1,0],[2,136,34,1,\"בְּשַׁנּוֹתוֹ אֶת טַעְמוֹ. כְּעִנְיָן שֶׁנֶּאֱמַר (שמואל א כא:יד) ״וַיְתָו עַל דַּלְתוֹת הַשַּׁעַר וְגוֹ׳ וַיְשַׁנּוּ אֶת טַעְמוֹ בְּעֵינֵיהֶם״, שֶׁשִּׁנָּה דְּבָרוֹ וְטַעְמוֹ וְעָשָׂה עַצְמוֹ שׁוֹטֶה וְהוֹרִיד רִירוֹ עַל זְקָנוֹ (ס״א אינו):\",1,0],[2,136,34,1,\"לִפְנֵי אֲבִימֶלֶךְ. כָּךְ כָּל מַלְכֵי פְלִשְׁתִּים נִקְרָאִים, וְכָל מַלְכֵי מִצְרַיִם פַּרְעֹה. וְאַף עַל פִּי שֶׁשְּׁמוֹ אָכִישׁ, קוֹרִין לוֹ אֲבִימֶלֶךְ. וּמִדְרַשׁ אַגָּדָה: שֶׁהָיָה צַדִּיק כַּאֲבִימֶלֶךְ (בראשית כ) שֶׁלֹּא רָצָה לְהָרְגוֹ, וַאֲנָשָׁיו אוֹמְרִים לוֹ ״הֲלֹא זֶה דָּוִד מֶלֶךְ הָאָרֶץ״ (שמואל א כא:יב), כִּדְאִיתָא בְּמִדְרַשׁ תְּהִלִּים:\",2,0],[2,136,34,3,\"בַּה׳ תִּתְהַלֵּל נַפְשִׁי. מִתְפָּאֵר אֲנִי וּמִתְהַלֵּל שֶׁיֵּשׁ לִי פַּטְרוֹן כָּזֶה לְהוֹשִׁיעַ וּלְהָגֵן:\",1,0],[2,136,34,3,\"תִּתְהַלֵּל נַפְשִׁי. שֶׁפּוֹרְוְונְטְרָ״א בְּלַעַ״ז:\",2,0],[2,136,34,3,\"יִשְׁמְעוּ עֲנָוִים. נִפְלָאוֹת שֶׁעָשָׂה לִי, מִתּוֹךְ מַהֲלָלִי יָבִינוּ אוֹתָם וְיִשְׂמָחוּ:\",3,0],[2,136,34,5,\"מְגוּרוֹתַי. לְשׁוֹן פַּחַד, כְּמוֹ ״וַיָּגָר מוֹאָב״ (במדבר כב:ג):\",1,0],[2,136,34,6,\"הִבִּיטוּ אֵלָיו. כָּל אוֹתָם שֶׁהִבִּיטוּ אֵלָיו מִתּוֹךְ צָרָתָם:\",1,0],[2,136,34,6,\"וְנָהָרוּ. הֵאִירוּ פְנֵיהֶם:\",2,0],[2,136,34,6,\"יֶחְפָּרוּ. יִתְבַּיְּשׁוּ, כְּמוֹ ״וְחָפְרָה הַלְּבָנָה וּבוֹשָׁה הַחַמָּה״ (ישעיהו כד:כג):\",3,0],[2,136,34,9,\"טַעֲמוּ וּרְאוּ כִּי טוֹב ה׳. טַעֲמוּ דְּבָרוֹ:\",1,0],[2,136,34,10,\"יִרְאוּ. יִהְיוּ יְרֵאִים, לְשׁוֹן צִוּוּי:\",1,0],[2,136,34,11,\"רָשׁוּ. לְשׁוֹן דַּלּוּת:\",1,0],[2,136,34,11,\"כָּל טוֹב. נִיסוֹ״ן בִּי״ן בְּלַעַ״ז, כְּמוֹ ״כָּל מְלָאכָה״ (שמות יב:טז):\",2,0],[2,136,34,15,\"בַּקֵּשׁ שָׁלוֹם. בִּמְקוֹמְךָ:\",1,0],[2,136,34,15,\"וְרָדְפֵהוּ. בְּמָקוֹם אַחֵר (תנחומא, חקת כב):\",2,0],[2,136,34,17,\"פְּנֵי. פָּנִים שֶׁל זַעַם לִישַׁאיְרָא״שׁ בְּלַעַ״ז, כְּמוֹ (ויקרא כ:ה) ״וְשַׂמְתִּי פָנַי בָּאִישׁ הַהוּא״, כָּךְ חִבְּרוֹ מְנַחֵם:\",1,0],[2,136,34,18,\"צָעֲקוּ. הַצַּדִּיקִים וַה׳ שָׁמֵעַ:\",1,0],[2,136,34,20,\"רַבּוֹת רָעוֹת צַדִּיק. הַרְבֵּה רָעוֹת וּפְחָדִים בָּאוֹת עָלָיו, וּמִכֻּלָּם נִצּוֹל:\",1,0],[2,136,34,21,\"שׁוֹמֵר. הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל עַצְמוֹתָיו:\",1,0],[2,136,34,22,\"תְּמוֹתֵת רָשָׁע רָעָה. תְּמוֹתֵת אֶת הָרָשָׁע הָרָעָה שֶׁהוּא עוֹשֶׂה:\",1,0],[2,136,34,22,\"תְּמוֹתֵת. תָּמִית:\",2,0],[2,136,34,23,\"לֹא יֶאְשְׁמוּ. לֹא יִתְחָרְטוּ לֵאמֹר: אָשַׁמְנוּ שֶׁחָסִינוּ בְּךָ; רִיפוֹנְטִירוֹנְ״ט בְּלַעַ״ז:\",1,0],[2,136,35,1,\"רִיבָה ה׳ אֶת יְרִיבַי. עֲשֵׂה מְרִיבָה עִם אוֹתָם שֶׁעוֹשִׂים מְרִיבָה עִמִּי:\",1,0],[2,136,35,1,\"לְחַם. לְשׁוֹן מִלְחָמָה, וְכֵן לֹחֲמָי: הִלָּחֵם עִם הַנִּלְחָמִים עִמִּי:\",2,0],[2,136,35,3,\"וְהָרֵק חֲנִית. הִזְדַּיֵּן, כְּמוֹ ״אָרִיק חַרְבִּי״ (שמות טו:ט), ״וַיָּרֶק אֶת חֲנִיכָיו״ (בראשית יד:יד):\",1,0],[2,136,35,3,\"וּסְגֹר לִקְרַאת רֹדְפָי. הָגֵן בֵּינִי וּבֵינֵיהֶם כִּמְחִיצָּה:\",2,0],[2,136,35,3,\"לְנַפְשִׁי. אִימוֹיְמֵאִימָ״שׁ בְּלַעַ״ז, כְּמוֹ ״כָּרוּ שׁוּחָה לְנַפְשִׁי״ (ירמיהו יח:כ):\",3,0],[2,136,35,6,\"חֹשֶׁךְ וַחֲלַקְלַקּוֹת. שְׁנֵיהֶם יַחַד, כְּדֵי שֶׁיַּחֲלִיקוּ רַגְלֵיהֶם בַּחֲלַקְלַקּוֹת, וְהַחֹשֶׁךְ אֵינוֹ מַנִּיחָם לְהִשָּׁמֵר מִן הַחֲלַקְלַקּוֹת. כְּמָה דְאַתְּ אָמַר ״לָכֵן יִהְיֶה דַרְכָּם לָהֶם כַּחֲלַקְלַקּוֹת בָּאֲפֵלָה יִדָּחוּ וְנָפְלוּ בָהּ״ (ירמיה כג:יב):\",1,0],[2,136,35,7,\"חָפְרוּ לְנַפְשִׁי. שׁוּחָה לִיפּוֹל בָּהּ:\",1,0],[2,136,35,8,\"שׁוֹאָה. חֹשֶׁךְ, בְּרוּאִינָ״ה בְּלַעַ״ז:\",1,0],[2,136,35,8,\"וְרִשְׁתּוֹ אֲשֶׁר טָמַן. כֵּן דֶּרֶךְ לִטְמוֹן הָרֶשֶׁת וּלְכַסּוֹתוֹ בְּקַשׁ אוֹ בְּעָפָר, כְּדֵי שֶׁלֹּא יַרְגִּישׁ בָּהּ הָעוֹבֵר עָלֶיהָ עַד שֶׁנִּלְכַּד בָּהּ:\",2,0],[2,136,35,9,\"וְנַפְשִׁי תָּגִיל. כְּשֶׁאֶרְאֶה בְּמַפַּלְתָּם:\",1,0],[2,136,35,10,\"כָּל עַצְמוֹתַי. יְקַלְּסוּךָ עַל כָּךְ, כִּי עַתָּה:\",1,0],[2,136,35,11,\"יְקוּמוּן. עָלַי תָּמִיד עֵדֵי חָמָס וְגוֹ׳:\",1,0],[2,136,35,13,\"וּתְפִלָּתִי עַל חֵיקִי תָשׁוּב. כְּלוֹמַר: וְאִם יֹאמְרוּ לֹא עִנֵּיתִי נַפְשִׁי אֶלָּא לְרָעָתָם, שֶׁיִּכְבַּד עֲלֵיהֶם חָלְיָם, תְּפִלָּתִי שֶׁהִתְפַּלַּלְתִּי עֲלֵיהֶם תָּשׁוּב עָלַי:\",1,0],[2,136,35,14,\"כְּרֵעַ כְּאָח לִי הִתְהַלָּכְתִּי. כְּאִלּוּ הָיוּ לִי אָחִי וְרֵעִי הִתְהַלַּכְתִּי, מֵיצַר עֲלֵיהֶם עַל צָרָתָם:\",1,0],[2,136,35,14,\"כַּאֲבֶל. אִם כְּבֵן הַמִּתְאַבֵּל עַל אִמּוֹ, אוֹ כְּאֵם הַמִּתְאַבֶּלֶת עַל בְּנָהּ:\",2,0],[2,136,35,14,\"קוֹדֵר. לְשׁוֹן שַׁחֲרוּת:\",3,0],[2,136,35,14,\"שַׁחוֹתִי. לְשׁוֹן שִׁפְלוּת:\",4,0],[2,136,35,15,\"וּבְצַלְעִי שָׂמְחוּ וְנֶאֱסָפוּ. וּכְשֶׁאֲנִי צוֹלֵעַ, שֶׁשֶּׁבֶר בָּא עָלַי, שָׂמְחוּ וְנֶאֱסָפוּ:\",1,0],[2,136,35,15,\"נֶאֶסְפוּ עָלַי נֵכִים. אֲנָשִׁים פִּסְחִים, כְּמוֹ שֶׁאָנוּ מְתַרְגְּמִינָן ״נָכֶה״: ״חֲגִירָא״ (תרגום יונתן מלכים ב כג:כט), וּמְנַחֵם חִבְּרוֹ כְּמוֹ ״נְכָאִים״ (ישעיה טז:ז), אימנויישי״ץ בְּלַעַ״ז:\",2,0],[2,136,35,15,\"קָרְעוּ וְלֹא דָמּוּ. אִלּוּ הָיוּ קוֹרְעִין אֶת בְּשָׂרִי, לֹא הָיָה דָמִי שׁוֹתֵת לָאָרֶץ כְּשֶׁמַּלְבִּינִין פָּנַי:\",3,0],[2,136,35,16,\"בְּחַנְפֵי לַעֲגֵי מָעוֹג וְגוֹ׳. בִּשְׁבִיל חֲנִיפוּת שֶׁל לֵיצָנוּת, אֲכִילָה וּשְׁתִיָּה, שֶׁמַּחֲנִיפִין לְשָׁאוּל בִּשְׁבִיל שֶׁיַּאֲכִילֵם וְיַשְׁקֵם, חוֹרְקִים עָלַי שִׁנֵּיהֶם:\",1,0],[2,136,35,16,\"מָעוֹג. לְשׁוֹן אֲכִילָה, כְּמוֹ ״אִם יֶשׁ לִי מָעוֹג״ דְּאֵלִיָּהוּ (מלכים א יז:יב). וּמְנַחֵם פָּתַר אוֹתוֹ לְשׁוֹן ״עֻגָה קְטַנָּה״ (מלכים א יז:יג), וְכֵן ״אִם יֶשׁ לִי מָעוֹג״:\",2,0],[2,136,35,17,\"כַּמָּה תִּרְאֶה. כַּמָּה אֹרֶךְ אַפַּיִם יֵשׁ לְפָנֶיךָ, לִרְאוֹת כָּל אֵלֶּה:\",1,0],[2,136,35,17,\"מִשּׁוֹאֵיהֶם. מֵחֹשֶׁךְ שֶׁלָּהֶם:\",2,0],[2,136,35,17,\"מִכְּפִירִים יְחִידָתִי. מוּסָב עַל הָשִׁיבָה נַפְשִׁי: הָשִׁיבָה מִכְּפִירִים יְחִידָתִי, (יְחִידָתִי נִשְׁמָתִי ס״א אינו):\",3,0],[2,136,35,19,\"אֹיְבַי שֶׁקֶר. שֶׁשּׂוֹנְאִין אוֹתִי עַל דְּבַר שֶׁקֶר, שֶׁמְּעִידִין עָלַי מַה שֶּׁלֹּא עָלָה בְמַחֲשַׁבְתִּי מֵעוֹלָם. אַל יִשְׂמְחוּ בִּמְפַלְתִּי:\",1,0],[2,136,35,19,\"שׂוֹנְאַי. שֶׁשּׂוֹנְאִים אוֹתִי, אַל יִקְרְצוּ עָלַי עָיִן וְלִלְעוֹג בְּעֵינֵיהֶם עַל מַפַּלְתִּי:\",2,0],[2,136,35,19,\"יִקְרְצוּ. צִינַאנְ״ט בְּלַעַ״ז:\",3,0],[2,136,35,20,\"עַל רִגְעֵי אֶרֶץ. עַל דַּכָּאֵי אֶרֶץ, וְכֵן ״רֹגַע הַיָּם״ (ירמיהו לא:לה), ״עוֹרִי רָגַע״ (איוב ז:ה), וְכֵן פֵּרֵשׁ דּוּנַשׁ:\",1,0],[2,136,35,21,\"הֶאָח הֶאָח. לְשׁוֹן שִׂמְחָה מִתְהַלֵּל בְּתַאֲוַת לִבּוֹ מֵרוֹב שִׂמְחָתָם שֶׁרוֹאִים תַּאֲוָתָם מִתְקַיֶּמֶת:\",1,0],[2,136,35,23,\"הָעִירָה וְהָקִיצָה. פַּמַלְיָא שֶׁל מַעְלָה, לִשְׁפּוֹט מִשְׁפָּטִי מֵאוֹיְבַי (סנהדרין לח:):\",1,0],[2,136,36,2,\"נְאֻם פֶּשַׁע לָרָשָׁע בְּקֶרֶב לִבִּי וְגוֹ׳. הֲרֵי זֶה מִקְרָא מְסֹרָס: יֵשׁ בְּקֶרֶב לִבִּי, שֶׁהַפֶּשַׁע, הוּא יֵצֶר הָרָע, אוֹמֵר לָרָשָׁע שֶׁלֹּא יְהֵא פַּחַד אֱלֹהִים לְנֶגֶד עֵינָיו:\",1,0],[2,136,36,2,\"וּבְּקֶרֶב לִבִּי. כְּאָדָם שֶׁאוֹמֵר: כִּמְדֻמֶּה אֲנִי:\",2,0],[2,136,36,3,\"כִּי הֶחֱלִיק. הַפֶּשַׁע עַל הָרָשָׁע בַּחֲלַקְלַקּוֹת בְּעֵינָיו, כְּדֵי שֶׁיִּמְצָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עֲוֹנוֹ, לִשְׂנֹא אוֹתוֹ:\",1,0],[2,136,36,4,\"חָדַל לְהַשְׂכִּיל לְהֵיטִיב. מָנַע עַצְמוֹ מֵהַשְׂכִּיל, לְהֵיטִיב מַעֲשָׂיו:\",1,0],[2,136,36,5,\"יִתְיַצֵּב עַל דֶּרֶךְ לֹא טוֹב. הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְפָנָיו דֶּרֶךְ הַטּוֹב וְדֶרֶךְ הַמָּוֶת, וְהוּא בּוֹחֵר לוֹ דֶּרֶךְ לֹא טוֹב:\",1,0],[2,136,36,6,\"ה׳ בַּשָּׁמַיִם חַסְדֶּךָ. בִּשְׁבִיל רְשָׁעִים הַלָּלוּ אַתָּה מְסַלֵּק חֶסֶד מִן הַתַּחְתּוֹנִים, וּמַגְבִּיהַּ אֱמוּנָתְךָ עַד שְׁחָקִים לְסַלְּקָהּ מִבְּנֵי אָדָם:\",1,0],[2,136,36,7,\"צִדְקָתְךָ. יְקָרָה מִן הַבְּרִיּוֹת כְּהַרְרֵי אֵל, בִּשְׁבִיל מַעֲשֵׂי הָרְשָׁעִים, וּמִשְׁפָּטֶךָ בָּאִים לָעוֹלָם עַד תְּהוֹם רַבָּה (ויקרא רבה כז:א). דָּבָר אַחֵר: צִדְקָתְךָ כְּהַרְרֵי אֵל מִי שֶׁאַתָּה רוֹצֶה לַעֲשׂוֹת צְדָקָה עִמּוֹ, אַתָּה מַגְבִּיהוֹ וּמְתַקְּפוֹ כְּהַרְרֵי אֵל, לְשׁוֹן תּוֹקֶף, כְּמוֹ (יחזקאל יז:יג) ״וְאֶת אֵילֵי הָאָרֶץ לָקָח״:\",1,0],[2,136,36,7,\"מִשְׁפָּטֶיךָ תְּהוֹם רַבָּה. מִי שֶׁאַתָּה רוֹצֶה לָדוּן אוֹתוֹ וְלִיקַּח נִקְמָתְךָ מִמֶּנּוּ, אַתָּה מוֹרִידוֹ עַד תְּהוֹם רַבָּה:\",2,0],[2,136,36,7,\"מִשְׁפָּטֶיךָ. יוּשְׁטִיצָ״א בְּלַעַ״ז:\",3,0],[2,136,36,7,\"אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה׳. בְּנֵי אָדָם שֶׁהֵם עֲרוּמִים בְּדַעַת כְּאָדָם הָרִאשׁוֹן וּמְשִׂימִין עַצְמָן כַּבְּהֵמָה בַּעֲנָוָה, תּוֹשִׁיעַ ה׳:\",4,0],[2,136,36,8,\"מַה יָּקָר חַסְדְּךָ. אֵינוֹ כְּדַאי לְהִמָּשֵׁךְ עַל הָרְשָׁעִים הַלָּלוּ, אֲבָל בְּנֵי אָדָם אֲשֶׁר בְּצֵל כְּנָפֶיךָ יֶחֱסָיוּן הֵם יִרְוְיוּן מִדֶּשֶׁן בֵּיתֶךָ וְגוֹ׳:\",1,0],[2,136,36,12,\"אַל תְּבוֹאֵנִי רֶגֶל גַּאֲוָה. אַל תָּבוֹא עִמִּי רֶגֶל הָרְשָׁעִים הַלָּלוּ בְּעֵת קִבּוּל שָׂכָר לִהְיוֹת חֶלְקָם עִם הַצַּדִּיקִים, (לשון חלק אהלא פרט״יאה בלע״ז ס״א אינו):\",1,0],[2,136,36,12,\"וְיַד רְשָׁעִים אַל תְּנִדֵנִי. מִמְּקוֹמִי בְּבוֹאִי לִירַשׁ מִשְׁנֶה, חֶלְקִי וְחֶלְקוֹ (שֶׁל רָשָׁע) בַּטּוֹבָה, כְּעִנְיָן שֶׁנֶּאֱמַר (ישעיהו סא:ז): ״לָכֵן בְּאַרְצָם מִשְׁנֶה יִירָשׁוּ״. וְאָז:\",2,0],[2,136,36,13,\"שָׁם נָפְלוּ פֹּעֲלֵי אָוֶן. שָׁם יָבִינוּ בְּמַפַּלְתָּם, וְשָׁם דֹּחוּ וְלֹא יָכְלוּ קוּם:\",1,0],[2,136,37,1,\"אַל תִּתְחַר בַּמְּרֵעִים. מוֹכִיחַ אֶת יִשְׂרָאֵל הוּא שֶׁלֹּא יִתְחָרוּ בְּהַצְלָחַת הַמְּרֵעִים לַעֲשׂוֹת כְּמַעֲשֵׂיהֶם, כְּמוֹ ״וְאֵיךְ תְּתַחֲרֶה אֶת הַסּוּסִים״ (ירמיה יב:ה) לָרוּץ בִּמְרוּצָתָם, הָאָטִיר בְּלַעַ״ז:\",1,0],[2,136,37,1,\"אַל תְּקַנֵּא בְּעוֹשֵׂי עַוְלָה. לַעֲשׂוֹת עַוְלָה כְּמוֹתָם:\",2,0],[2,136,37,2,\"יִמָּלוּ. שְׁרוֹנְ״ט טְרַנְקִיי״ץ בְּלַעַ״ז, לְשׁוֹן כְּרִיתָה:\",1,0],[2,136,37,3,\"בְּטַח בַּה׳. וְאַל תֹּאמַר: אִם לֹא אֶגְזֹל וְאֶגְנֹב, אוֹ אֶתֵּן לֶעָנִי צְדָקָה, בַּמֶּה אֶתְפַּרְנֵס?\",1,0],[2,136,37,3,\"וַעֲשֵׂה טוֹב. וְאָז תִּשְׁכֹּן אֶרֶץ לְאֹרֶךְ יָמִים:\",2,0],[2,136,37,3,\"וּרְעֵה אֱמוּנָה. תֹּאכַל וְתִתְפַּרְנֵס מִשְּׂכַר הָאֱמוּנָה שֶׁהֶאֱמַנְתָּ בְּהַקָּדוֹשׁ בָּרוּךְ הוּא לִסְמֹךְ עָלָיו וְלַעֲשׂוֹת טוֹב:\",3,0],[2,136,37,4,\"וְהִתְעַנַּג עַל ה׳. הִתְעַנֵּג בְּתַפְנוּקִים עַל מִשְׁעַנְתּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,136,37,5,\"גּוֹל עַל ה׳ דַּרְכֶּךָ. גַּלְגֵּל עָלָיו כָּל צְרָכֶיךָ:\",1,0],[2,136,37,7,\"דּוֹם לַה׳. הַמְתֵּן לִישׁוּעָתוֹ, כְּמוֹ ״אִם כֹּה יֹאמְרוּ אֵלֵינוּ דֹּמּוּ״ דִּיהוֹנָתָן (שמואל א יד:ט). וּמְנַחֵם חִבְּרוֹ לְשׁוֹן דְּמָמָה, כְּמוֹ ״וַיִּדֹּם אַהֲרֹן״ (ויקרא י:ג). וְגַם כֵּן פָּתַר ״טוֹב וְיָחִיל וְדוּמָם״ (איכה ג:כו). וְדוּנָשׁ מוֹדֶה לוֹ:\",1,0],[2,136,37,7,\"וְהִתְחוֹלֵל. לְשׁוֹן ״תּוֹחֶלֶת״ (משלי יג:יב):\",2,0],[2,136,37,7,\"אַל תִּתְחַר. לֹאמַר: אַרְשִׁיעַ כְּמוֹתוֹ וְאַצְלִיחַ כְּמוֹתוֹ:\",3,0],[2,136,37,8,\"הֶרֶף מֵאַף. הֶרֶף מֵהַרְשִׁיעַ, שֶׁלֹּא יָבֹא עָלֶיךָ אַף:\",1,0],[2,136,37,8,\"וַעֲזֹב. דָּבָר הַמֵּבִיא עָלֶיךָ חֲמָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,136,37,9,\"כִּי מְרֵעִים. שֶׁאַתָּה רוֹאֶה עַתָּה מַצְלִיחִים, הֵם יִכָּרֵתוּן:\",1,0],[2,136,37,10,\"וְעוֹד מְעַט. כְּשֶׁתַּמְתִּין עוֹד מְעַט, תִּרְאֶה כִּי אֵין הָרָשָׁע:\",1,0],[2,136,37,10,\"וְהִתְבּוֹנַנְתָּ עַל מְקוֹמוֹ. וְתִסְתַּכֵּל עַל מָקוֹם שֶׁהָיָה שָׁם, וְאֵינֶנּוּ, כִּי מֵת וְאָבַד:\",2,0],[2,136,37,12,\"וְחֹרֵק. כְּמוֹ ״חָרְקוּ שֵׁן״ (איכה ב:טז), אַרְקִי״נְט בְּלַעַ״ז:\",1,0],[2,136,37,14,\"חֶרֶב פָּתְחוּ. הָרְשָׁעִים פָּתְחוּ, אַנְקוֹמַנְצִירְנְט בְּלַעַ״ז, תָּגָר וְחֵרוּם מַתְחִילִים הָרְשָׁעִים מֵאֲלֵיהֶם:\",1,0],[2,136,37,16,\"טוֹב מְעַט לַצַּדִּיק. טוֹבִים מְעַט אֲנָשִׁים שֶׁהוֹלְכִים לְעֶזְרַת הַצַּדִּיקִים:\",1,0],[2,136,37,16,\"מֵהֲמוֹן רְשָׁעִים רַבִּים. אַמְרָפֶל וַחֲבֵירָיו שֶׁהִתְחִילוּ מִלְחָמָה בָּעוֹלָם בִּשְׁבִיל לִשְׁבּוֹת אֶת לוֹט וּלְהִתְגָּרוֹת בְּאַבְרָהָם (בראשית יד:א-טו), מְעַט אֲנָשִׁים שֶׁהָיוּ עִם אַבְרָהָם הִצְלִיחוּ וְהָרְגוּ כָּל אוֹתָן הָאוּכְלְסִין (תנחומא, לך לך ז):\",2,0],[2,136,37,18,\"יוֹדֵעַ ה׳ יְמֵי תְמִימִים. מַכִּיר אֶת מַעֲשֵׂי יְמֵיהֶם:\",1,0],[2,136,37,18,\"וְנַחֲלָתָם. וְקִבּוּל שְׂכָרָם מֵאִתּוֹ לְעוֹלָם תִּהְיֶה:\",2,0],[2,136,37,20,\"כִּיקַר כָּרִים. כְּאוֹר עֲנַן בֹּקֶר הַנִּרְאֶה שַׁחֲרִית, מַלְבִּין עַל מֶרְחֲבֵי בִּקְעָה שֶׁאֵינוֹ מִתְקַיֵּם. כָּרִים מִישׁוֹר, כְּמוֹ ״כַּר נִרְחָב״ (ישעיה ל:כג):\",1,0],[2,136,37,20,\"כִּיקַר. לְשׁוֹן ״אוֹר יְקָרוֹת״ (זכריה יד:ו), וְיֵשׁ פּוֹתְרִין כִּיקַר כָּרִים, כִּכְבוֹד כְּבָשִׂים שֶׁמְּפַטְּמִין אוֹתָן לַטֶּבַח:\",2,0],[2,136,37,21,\"לֹוֶה רָשָׁע וְלֹא יְשַׁלֵּם וְצַדִּיק חוֹנֵן וְנוֹתֵן. הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא צַדִּיקוֹ שֶׁל עוֹלָם, חוֹנֵן מִשֶּׁלּוֹ וְנוֹתֵן לָזֶה שֶׁהִלְוָה מַה שֶּׁהוּא גּוֹזֵל מִמֶּנּוּ:\",1,0],[2,136,37,22,\"כִּי מְבֹרָכָיו. שֶׁל צַדִּיקוֹ שֶׁל עוֹלָם יִירְשׁוּ אָרֶץ:\",1,0],[2,136,37,23,\"מִצְעֲדֵי גֶבֶר. מִי שֶׁהוּא גִּבּוֹר בְּיִרְאַת הַקָּדוֹשׁ בָּרוּךְ הוּא, לִישׁ פָּאשׁ דוּפוֹרְט בְּלַעַ״ז:\",1,0],[2,136,37,23,\"כּוֹנָנוּ. פוּרִינְ״ט אַפִּיטַיְי״ץ בְּלַעַ״ז:\",2,0],[2,136,37,24,\"יִפֹּל. לָבוּרְגָ״א בְּלַעַ״ז, לְשׁוֹן ״וַתִּפֹּל מֵעַל הַגָּמָל״ (בראשית כד:סד):\",1,0],[2,136,37,24,\"כִּי. כְּמוֹ אִם:\",2,0],[2,136,37,24,\"לֹא יוּטָל. לֹא יֻשְׁלַךְ לִהְיוֹת נֶעֱזָב:\",3,0],[2,136,37,25,\"נַעַר הָיִיתִי. פָּסוּק זֶה, שַׂר הָעוֹלָם אֲמָרוֹ, דְּאִילּוּ דָּוִד לֹא קָשִׁישׁ כּוּלֵּי הַאי (יבמות טז:):\",1,0],[2,136,37,26,\"כָּל הַיּוֹם. הַצַּדִּיק חוֹנֵן עֲנִיִּים וּמַלְוֶה לָהֶם:\",1,0],[2,136,37,26,\"וְזַרְעוֹ. זֶה שֶׁהוּא זוֹרֵעַ לִצְדָקָה, סוֹפוֹ לִבְרָכָה:\",2,0],[2,136,37,30,\"פִּי צַדִּיק יֶהְגֶּה. תְּחִלָּה בְּלִבּוֹ חָכְמָה, לִרְאוֹת דִּין שֶׁפָּסְקָה תּוֹרָה לְכָל דָּבָר, וְאַחַר כָּךְ לְשׁוֹנוֹ תְּדַבֵּר מִשְׁפָּט:\",1,0],[2,136,37,31,\"לֹא תִמְעַד אֲשׁוּרָיו. לֹא יַחֲלִיקוּ צְעָדָיו:\",1,0],[2,136,37,35,\"וּמִתְעָרֶה. מַשְׁרִישׁ, כְּמוֹ ״עָרוֹת עַל יְאוֹר״ (ישעיהו יט:ז). וּבִלְשׁוֹן מִשְׁנָה יֵשׁ הַרְבֵּה: ״אִילָן שֶׁנִּפְשַׁח וּמְעוֹרֶה בַּקְּלִפָּה״ (עוקצין ג:ח):\",1,0],[2,136,37,35,\"כְּאֶזְרָח רַעֲנָן. כְּאֶחָד מֵאֶזְרְחֵי הָאָרֶץ הַנִּשְׁרָשִׁים וּמְמֻלָּאִים בִּנְכָסִים. וְכֵן פֵּרֵשׁ מְנַחֵם: כְּאֶזְרָח רַעֲנָן – מִתְלַחְלֵחַ וּמִצְטַמֵּחַ כְּאֵשֶׁל הַנִּשְׁרָשׁ. וְאֶזְרָח מֵאֶזְרְחֵי בְּנֵי אָדָם – אַנְשֵׁי שָׁרָשִׁים הֵמָּה (ס״א אינו):\",2,0],[2,136,37,37,\"שְׁמׇר תָּם. הִסְתַּכְּלוּ בְּדַרְכֵי הַתְּמִימִים, לִלְמֹד מִמַּעֲשֵׂיהֶם:\",1,0],[2,136,37,37,\"כִּי אַחֲרִית לְאִישׁ שָׁלוֹם. אִם רֵאשִׁית אֵין לוֹ, אַחֲרִית יֵשׁ לוֹ. אֲבָל פּוֹשְׁעִים וְחַטָּאִים וּרְשָׁעִים – אַחֲרִיתָם נִכְרְתָה וְנִשְׁמְדוּ יַחְדָּיו:\",2,0],[2,136,38,1,\"מִזְמוֹר לְדָוִד לְהַזְכִּיר. לְאוֹמְרוֹ בִּשְׁעַת צָרָה, לְהַזְכִּיר צָרָתָם שֶׁל יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וּכְנֶגֶד כָּל יִשְׂרָאֵל אֲמָרוֹ:\",1,0],[2,136,38,3,\"נִחֲתוּ. נִזְרְקוּ. לְשׁוֹן נַחַת נוֹפֵל בִּנְטִיַּת קֶשֶׁת, וּלְפִי שֶׁעַל יְדֵי דְּרִיכַת הַקֶּשֶׁת נִזְרָקִים הַחִצִּים, כְּתִיב נִחֲתוּ בִי, וְכֵן (שמות טו:ט) ״אָרִיק חַרְבִּי״, הָיָה לוֹ לִכְתֹּב אָרִיק תַּעְרִי, אֶלָּא לְפִי שֶׁכְּשֶׁמּוֹצִיאִין חֶרֶב מִתַּעְרָהּ הַתַּעַר רֵיק מִמֶּנָּה, לְכָךְ תּוֹלֶה הָרֵיקוּת בַּחֶרֶב, וְכֵן (תהלים יח:לה) ״וְנִחֲתָה קֶשֶׁת נְחוּשָׁה״. וְאֵין הַנּוּ״ן שֹׁרֶשׁ בַּתֵּבָה, שֶׁאִם הָיְתָה שֹׁרֶשׁ הָיָה לוֹ לוֹמַר נִנְחֲתוּ בִי, אֲבָל נוּ״ן שֶׁל נָחֲתוּ וְכֵן שֶׁל וַתִּנְחַת אֵינָהּ שֹׁרֶשׁ וְנוֹפֶלֶת לִפְרָקִים כְּמוֹ וְנוּ״ן שֶׁל נָגַף, נָשַׁךְ, נָדַר, נָקַם, כְּשֶׁמִּתְפַּעֵל יֹאמַר נִגַּף נִשַּׁךְ נִדַּר נִקַּם כְּמוֹ נִנְגַף נִנְשַׁךְ נִנְדַר נִנְקַם שֶׁהַדָּגֵשׁ בָּא בַתֵּבָה בִּמְקוֹם נוּ״ן, וְכֵן (ויקרא כו:לו) ״עָלֶה נִדָּף״, (איכה ג:מט) ״עֵינִי נִגְּרָה״, כְּמוֹ נִנְדַּף נִנְגְּרָה, כֵּן יֹאמַר נָחֲתוּ כְּמוֹ נִנְחֲתוּ, וְכֵן (תהלים יח:לה) ״וְנִחֲתָה קֶשֶׁת נְחוּשָׁה״ כְּמוֹ וְנִנְחֲתָה, שֶׁדֶּרֶךְ הַחֵי״ת לְהִתְנַהֵג כְּמִנְהַג דַּגְשׁוּת בְּרֹב מְקוֹמוֹת, כְּגוֹן (מלכים א יג:יח) ״כִּחֵשׁ לוֹ״, וּמִמִּשְׁקַל דָּגוּשׁ כְּמוֹ דִּבֵּר מִגִּזְרַת וַיְדַבֵּר, כָּךְ כִּחֵשׁ מִגִּזְרַת (בראשית יח:טו) ״וַתְּכַחֵשׁ שָׂרָה״, וְלֹא יֹאמַר כֵּחַשׁ כַּאֲשֶׁר יֹאמַר מִן הַמְבָרֵךְ בֵּרַךְ וְלֹא יֹאמַר בִּרֵךְ כַּאֲשֶׁר יֹאמַר דִּבֵּר, לְפִי שֶׁאֵין דַּגְשׁוּת נִכָּר בְּרֵי״שׁ, אֲבָל בְּחֵי״ת נִכָּר דַּגְשׁוּת, וְכֵן (דברים לב:ה) ״שִׁחֵת,״ כְּמוֹ כִּפֵּר דִּבֵּר. אַף כָּאן יֹאמַר נָחֲתוּ כְּמוֹ נִגְּשׁוּ נִתְּנוּ מִגְּזַר נָחַת נָתַן נָגַשׁ, וְהַנּוּ״ן יְסוֹד נוֹפֵל לִכָּנֵס דָּגֵשׁ בִּמְקוֹמָהּ כְּשֶׁהִיא מִתְפַּעֵל, וְכֵן (שמואל א ב:ד) ״קֶשֶׁת גִּבֹּרִים חַתִּים״ מִגִּזְרַת נָחַת וְחָתַת, כַּאֲשֶׁר יֹאמַר מִן נָסַב סָבַב, מִן נָשַׁם שָׁמַם, (ויקרא כו:לב) ״וְנָשַׁמּוּ דַרְכֵיכֶם״, (שם) ״וְשָׁמְמוּ עָלֶיהָ״, וְכֵן בָּלַל נָבַל (בראשית יא:ט) ״כִּי שָׁם בָּלַל ה׳״, (בראשית יא:ז) ״וְנָבְלָה שָׁם שְׂפָתָם״, כֵּן יֹאמַר נָחַת וְחָתַת בִּלְשׁוֹן פָּעַל:\",1,0],[2,136,38,3,\"וַתִּנְחַת עָלַי יָדֶךָ. פֵּירוּשׁ לְחִצֶּיךָ נִחֲתוּ בִי, וְכֵן פִּתְרוֹנוֹ: מַה דֶּרֶךְ בַּקֶּשֶׁת לִירוֹת הַחִצִּים? יָד שֶׁלְּךָ הִיא נִחֲתָה בַּקֶּשֶׁת לְהַפִּיל עָלַי חִצִּים. וַתִּנְחַת לְשׁוֹן וַתֵּרֵד, וּבָזֶה הַנּוּ״ן שֹׁרֶשׁ בַּתֵּיבָה. וְכֵן ״וְנִחֲתָה קֶשֶׁת נְחוּשָׁה״ (לעיל יח:לה), אֵין הַנּוּ״ן שֹׁרֶשׁ בַּתֵּיבָה (ס״א אינו):\",2,0],[2,136,38,4,\"מְתֹם. תְּמִימוּת, אינטרי״ן בְּלַעַ״ז:\",1,0],[2,136,38,5,\"יִכְבְּדוּ. כְּבֵדִים:\",1,0],[2,136,38,7,\"נַעֲוֵיתִי. לְשׁוֹן אֲחָזַתּוֹ עֲוִית (חולין ס:), אֵישְׁטוֹרְדִישׁוֹ״ן בְּלַעַ״ז:\",1,0],[2,136,38,8,\"כְּסָלַי מָלְאוּ נִקְלֶה. בְּמַחֲשַׁבְתִּי אֲנִי קַל בְּעֵינֵי עַצְמִי:\",1,0],[2,136,38,9,\"נְפוּגוֹתִי. נֶחֱלַפְתִּי, לְשׁוֹן ״וַיָּפָג לִבּוֹ״ (בראשית מה:כו), ״מֵאֵין הֲפֻגוֹת״ (איכה ג:מט):\",1,0],[2,136,38,10,\"כָּל תַּאֲוָתִי. אַתָּה יוֹדֵעַ צְרָכַי:\",1,0],[2,136,38,11,\"סְחַרְחַר. מֻקָּף יָגוֹן, וְזֶהוּ מִתֵּיבוֹת הַכְּפוּלוֹת, כְּמוֹ ״יְרַקְרַק אֲדַמְדַּם״ (ויקרא יג:מט), סְגַלְגַּל (נדרים סו:), ״חֳמַרְמְרוּ״ (איכה א:כ):\",1,0],[2,136,38,12,\"מִנֶּגֶד נִגְעִי יַעֲמֹדוּ. אוֹתָם נִרְאִין לִי כְּאוֹהֲבִים בִּשְׁעַת הֲנָאָתָן, וּכְשֶׁרוֹאִין שֶׁהַנֶּגַע בָּא עָלַי אֵין עוֹמְדִין לִי בִּשְׁעַת דָּחְקִי, אֶלָּא מִנֶּגְדִּי יַעֲמֹדוּ וְאֵינָם עוֹזְרִים לִי:\",1,0],[2,136,38,12,\"וּקְרוֹבַי. שֶׁמַּרְאִים לִי עַצְמָם קְרוֹבִים:\",2,0],[2,136,38,13,\"וַיְנַקְשׁוּ מְבַקְשֵׁי. מוֹקְשִׁים לִי:\",1,0],[2,136,38,13,\"יֶהְגּוּ. יַחְשְׁבוּ:\",2,0],[2,136,38,14,\"וַאֲנִי כְחֵרֵשׁ. יִשְׂרָאֵל שׁוֹמְעִים חֶרְפָּתָם מִן הַמְּחָרְפִים, וְאֵינָם מְשִׁיבִים. וְלָמָּה? כִּי לְךָ הוֹחַלְתִּי, שֶׁתִּגְאָלֵנִי וְתוֹשִׁיעֵנִי מֵהֶם (שבת פח:):\",1,0],[2,136,38,17,\"כִּי אָמַרְתִּי פֶּן יִשְׂמְחוּ לִי. לְכָךְ אָנוּ שׁוֹתְקִים, כִּי אוֹמְרִים אָנוּ בְּלִבֵּנוּ: אִם נְשִׁיבֵם עַזּוּת, שֶׁמָּא יִרְאוּ בְּמַפַּלְתֵּנוּ וְיִשְׂמְחוּ לָנוּ בְּמוֹט רַגְלֵינוּ, וְיַגְדִּילוּ עָלֵינוּ לוֹמַר: הֲלֹא הֱיִיתֶם מִתְפָּאֲרִים בִּתְשׁוּעַתְכֶם?\",1,0],[2,136,38,18,\"כִּי אֲנִי לְצֶלַע נָכוֹן. לְכָךְ אָנוּ דּוֹאֲגִים פֶּן יִשְׂמְחוּ לָנוּ, לְפִי שֶׁמְּלֻמָּדִים אָנוּ בְּמַכּוֹת וּמוּכָנִים וּמְזֻמָּנִים לְשֶׁבֶר תָּמִיד:\",1,0],[2,136,38,18,\"וּמַכְאוֹבִי נֶגְדִּי. מְזֻמָּן הוּא לָבֹא עָלַי תָּמִיד:\",2,0],[2,136,38,19,\"כִּי עֲוֺנִי אַגִּיד. לִבִּי מַגִּיד לִי אֶת עֲוֺנִי, וּלְפִיכָךְ אֲנִי דּוֹאֵג וְיָרֵא מֵחַטָּאתִי, שֶׁלֹּא יִגְרֹם לִי צֶלַע וּמַכְאוֹב:\",1,0],[2,136,38,20,\"חַיִּים עָצֵמוּ. מַעֲצִימִים חַיִּים בְּשָׁלוֹם וּבְטוֹבָה:\",1,0],[2,136,38,20,\"וְרַבּוּ. וְהִגְדִּילוּ שׂוֹנְאַי עַל דִּבְרֵי שָׁקֶר:\",2,0],[2,136,38,21,\"תַּחַת רָדְפִי טוֹב. בִּשְׁבִיל שֶׁאֲנַחְנוּ דְּבֵקִים בַּהַקָּדוֹשׁ בָּרוּךְ הוּא וּבְמִצְווֹתָיו:\",1,0],[2,136,39,1,\"לִידוּתוּן. שֵׁם אָדָם אֶחָד מִן הַמְשׁוֹרְרִים (דברי הימים א טז:מא-מב), וְגַם כְּלִי שִׁיר הָיָה שָׁם שֶׁשְּׁמוֹ יְדוּתוּן (תהלים סב:א). וּמִדְרַשׁ אַגָּדָה: עַל הַדָּתוֹת וְעַל הַדִּינִין וְהַגְּזֵרוֹת שֶׁל צָרָה הַנִּגְזֶרֶת עַל יִשְׂרָאֵל:\",1,0],[2,136,39,2,\"אָמַרְתִּי אֶשְׁמְרָה דְרָכַי וְגוֹ׳. אֲנַחְנוּ הָיָה בְלִבֵּנוּ לִשְׁמֹר אֶת עַצְמֵנוּ עַל כָּל הַצָּרוֹת הַבָּאוֹת עָלֵינוּ, שֶׁלֹּא נְהַרְהֵר וְנְדַבֵּר קָשֶׁה אַחַר מִדַּת הַדִּין, אַף עַל פִּי שֶׁהָרְשָׁעִים לְנֶגְדֵּנוּ הַמְּצִירִים לָנוּ:\",1,0],[2,136,39,2,\"מַחְסוֹם. כְּמוֹ ״לֹא תַחְסֹם שׁוֹר״ (דברים כה:ד), אמושלמנ״ט בְּלַעַ״ז. וְנֶאֱלַמְנוּ דוּמִיָּה יָמִים רַבִּים, וְגַם הֶחֱשֵׁינוּ מִטּוֹב אֲפִלּוּ מִדִּבְרֵי תוֹרָה מִפְּנֵי יִרְאָתָם, וּמִתּוֹךְ כָּךְ כְּאֵבֵנוּ נֶעְכַּר וְנִבְהַל. וּכְשֶׁשָּׁתַקְנוּ חַם לִבֵּנוּ בְּקִרְבֵּנוּ, וּבְהֶגְיוֹן לִבֵּנוּ בּוֹעֵר בָּנוּ כְּמוֹ אֵשׁ, וְהוּא גּוֹרֵם לָנוּ שֶׁאָנוּ מְדַבְּרִים בִּלְשׁוֹנֵנוּ (בְּלַחַשׁ ס״א אינו) לְפָנֶיךָ. וְזוֹ הִיא שֶׁאָנוּ מְדַבְּרִים: הוֹדִיעֵנו ה׳ קִצֵּנוּ, עַד מָתַי נִהְיֶה בַצָּרָה, וְנֵדַע מָתַי נִהְיֶה אֲנַחְנוּ חֲדֵלִים מִמֶּנָּה:\",2,0],[2,136,39,6,\"הִנֵּה טְפָחוֹת. מְדוּדִים הֵם יְמֵי הָאָדָם כְּדָבָר הַנִּמְדָּד בִּטְפָחִים, כֵּן יְמֵי הָאָדָם קְצוּבִים. וְחֶלְדִּי. וְזִקְנָתֵנוּ כְּאַיִן נֶגְדֶּךָ, חֶלֶד, לְשׁוֹן חֲלוּדָה רדוייל בְּלַעַ״ז:\",1,0],[2,136,39,6,\"כָּל אָדָם נִצָּב. כָּל אָדָם חַי, הֶבֶל הֵם חַיָּיו וּמַצָּבוֹ:\",2,0],[2,136,39,7,\"אַךְ בְּצֶלֶם. בְּחֹשֶׁךְ, פֵּרְשׁוֹ דּוּנַשׁ לְשׁוֹן ״צַלְמָוֶת״ (ישעיה ט:א), וּמְנַחֵם פֵּרְשׁוֹ צֶלֶם מַמָּשׁ כְּמוֹ ״כִּי בְצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם״ (בראשית ט:ו), וְלֹא יִתָּכְנוּ דְּבָרָיו:\",1,0],[2,136,39,7,\"אַךְ הֶבֶל. הוּא כָּל הַהֲמִיָּה וְתַאֲוָה שֶׁלָּהֶם:\",2,0],[2,136,39,7,\"יִצְבֹּר. תְּבוּאָה בַּשָּׂדֶה כָּל יְמוֹת הַקָּצִיר:\",3,0],[2,136,39,7,\"וְלֹא יֵדַע מִי אֹסְפָם. אֵינוֹ יוֹדֵעַ מִי אֲסָפָם לַבַּיִת, שֶׁמָּא לִפְנֵי הָאָסִיף יָמוּת:\",4,0],[2,136,39,8,\"וְעַתָּה מַה קִּוִּיתִי. מָה הִיא הַשְּׁאֵלָה אֲשֶׁר אֲנִי שׁוֹאֵל וּמְיַחֵל מִמְּךָ? אֵינוֹ אֶלָּא שֶׁמִּפְּשָׁעַי הַצִּילֵנִי:\",1,0],[2,136,39,9,\"חֶרְפַּת נָבָל. חֶרְפַּת הַנָּבָל אַל תְּשִׂימֵנִי, הָבֵא גַּם עָלָיו נְגָעִים וּמַכְאוֹבוֹת, שֶׁלֹּא יוּכַל לוֹמַר לִי: אַתֶּם לוֹקִים וְאָנוּ אֵין אָנוּ לוֹקִים. וְהַתְּפִלָּה הַזֹּאת גָּרְמָה לְהָבִיא יִסּוּרֵי חֳלָאִים עֲלֵיהֶם (בראשית רבה פח:א):\",1,0],[2,136,39,10,\"כִּי אַתָּה עָשִׂיתָ. שֶׁהֵבֵאתָ עָלֵינוּ צָרָה:\",1,0],[2,136,39,11,\"מִתִּגְרַת יָדְךָ. מִמּוֹרָא מַכּוֹתֶיךָ. תִּגְרַת לְשׁוֹן ״וַיָּגָר מוֹאָב״ (במדבר כב:ג), וְהַתָּי״ו יְסוֹד נוֹפֵל בַּתֵּיבָה כְּמוֹ תְּנוּבָה תְּלוּנָה תְּקוּמָה תְּחִנָּה, כֵּן פֵּירֵשׁ מְנַחֵם. וַאֲנִי אוֹמֵר שֶׁאֵין תִּגְרַת לְשׁוֹן מָגוֹר, שֶׁהָיָה לוֹ לוֹמַר תְּגוּרָה כַּאֲשֶׁר יֹאמַר מִן וַיָּשָׁב תְּשׁוּבָה וַיָּקָם וַיָּרָם וַיָּלֶן תְּקוּמָה תְּרוּמָה תְּלוּנָה, כֵּן אָמַר וַיָּגָר תְּגוּרָה אוֹ מְגוֹרָה כְּמוֹ ״מָגוֹר מִסָּבִיב״ (ירמיהו כ:ג), ״מְגוּרָתָם אָבִיא לָהֶם״ (ישעיהו סו:ד). הָא לָמַדְתָּ שֶׁאֵין תִּגְרַת אֶלָּא כְּמוֹ ״לָמָּה תִּתְגָּרֶה בְּרָעָה״ (דברי הימים ב כה:יט), ״אַל תִּתְגָּרוּ בָם״ (דברים ב:ה), שֶׁהַפּוֹעַל שֶׁלּוֹ גָּרָה, כְּמוֹ קִוָּה אִוָּה צִוָּה שֶׁפְּעֻלָּתָם תִּקְוָה תַּאֲוָה מִצְוָה, כֵּן יֹאמַר מִן גָּרָה תִּגְרַת. וְכֵן פֵּירוּשׁוֹ: מִמַּכַּת יָדְךָ אֲשֶׁר אַתָּה מְגָרֶה עָלַי אֲנִי כָלִיתִי:\",1,0],[2,136,39,12,\"בְּתוֹכָחוֹת. הַכְּתוּבוֹת בַּתּוֹרָה (ויקרא כו; דברים כח) עַל עֲוֹנִינוּ שֶׁהֶעֱוִינוּ לְפָנֶיךָ, וְיִסַּרְתָּנוּ בָּהֶם:\",1,0],[2,136,39,12,\"וַתֶּמֶס כָּעָשׁ חֲמוּדוֹ. הִרְקַבְתָּ בְּשָׂרֵינוּ כְּבֶגֶד שֶׁאֲכָלוֹ עָשׁ:\",2,0],[2,136,39,12,\"חֲמוּדוֹ. בְּשָׂרוֹ, שֶׁהוּא חֶמְדָּתוֹ:\",3,0],[2,136,39,14,\"הָשַׁע מִמֶּנִּי. הֶרֶף יָדְךָ מִלְּהַלְקוֹתִי:\",1,0],[2,136,39,14,\"וְאַבְלִיגָה. וְאֶתְחַזְּקָה:\",2,0],[2,136,40,2,\"קַוֺּה קִוִּיתִי ה׳. בְּמִצְרַיִם, וּמִזְמוֹר זֶה גַּם הוּא כְּנֶגֶד כָּל יִשְׂרָאֵל:\",1,0],[2,136,40,2,\"וַיֵּט אֵלַי. אָזְנוֹ:\",2,0],[2,136,40,3,\"מִבּוֹר שָׁאוֹן. מֵאֲסִירִים שֶׁל מִצְרַיִם וּמִשָּׁאוֹן הֲמִיַּת יָם:\",1,0],[2,136,40,3,\"מִטִּיט הַיָּוֵן. מִן הַיָּם. הַיָּוֵן לְשׁוֹן רֶפֶשׁ, פיינ״ש בְּלַעַ״ז:\",2,0],[2,136,40,3,\"כּוֹנֵן. הֵכִין אֲשׁוּרַי וּצְעָדַי:\",3,0],[2,136,40,4,\"שִׁיר חָדָשׁ. שִׁירַת הַיָּם (שמות טו:א-כו):\",1,0],[2,136,40,5,\"רְהָבִים. לְשׁוֹן גַּסּוּת, כְּמוֹ ״יִרְהֲבוּ הַנַּעַר״ (ישעיהו ג:ה), ״שֶׁהֵם הִרְהִיבוּנִי״ (שיר השירים ו:ה):\",1,0],[2,136,40,5,\"וְשָׂטֵי כָזָב. מְשַּׁטִים מִדֶּרֶךְ הַיָּשָׁר אַחֲרֵי הַכָּזָב. שָׂטֵי – אִיטוּרְנָ״אנְץ בְּלַעַ״ז:\",2,0],[2,136,40,6,\"נִפְלְאוֹתֶיךָ וּמַחְשְׁבֹתֶיךָ אֵלֵינוּ. בִּשְׁבִילֵנוּ בָּרָאתָ עוֹלָמְךָ, קָרַעְתָּ לָנוּ אֶת הַיָּם וְחָשַׁבְתָּ מֵרָחוֹק לְהֵיטִיב לָנוּ. אִחַרְתָּנוּ בַמִּדְבָּר אַרְבָּעִים שָׁנָה מִפְּנֵי הָאֱמוֹרִים, שֶׁקִּצְּצוּ אֶת הָאִילָנוֹת וְהֶחֱרִיבוּ אַרְצָם כְּשֶׁשָּׁמְעוּ שֶׁיִּשְׂרָאֵל יוֹצְאִין לָלֶכֶת לָרֶשֶׁת אֶת אַרְצָם (מכילתא בשלח ויהי פתיחתא):\",1,0],[2,136,40,6,\"אֵין עֲרוֹךְ אֵלֶיךָ. אֵין לְדַמּוֹת לְךָ כָּל שַׂר וּמוֹשִׁיעַ, לְשׁוֹן עֵרֶךְ כְּמוֹ ״כְּעֶרְכְּךָ״ (ויקרא כז:יב), אהפרישי״ר בְּלַעַ״ז:\",2,0],[2,136,40,6,\"אַגִּידָה וַאֲדַבֵּרָה. אִם בָּאתִי לְהַגִּיד וּלְדַבֵּר, עָצְמוּ מִסַּפֵּר:\",3,0],[2,136,40,7,\"זֶבַח וּמִנְחָה לֹא חָפַצְתָּ. בְּיוֹם מַתַּן תּוֹרָה כְּעִנְיָן שֶׁנֶּאֱמַר ״וְעַתָּה אִם תִּשְׁמַע בְּקוֹל ה׳ וְגוֹ׳״ (שמות יט:ה), וְכֵן הוּא אוֹמֵר ״כִּי לֹא דִבַּרְתִּי אֶת אֲבוֹתֵיכֶם וְלֹא צִוִּיתִים וְגוֹ׳ עַל דִּבְרֵי עוֹלָה אוֹ זָבַח״ (ירמיהו ז:כב) ״כִּי יַקְרִיב מִכֶּם״ אָמַרְתִּי (ויקרא א:ב) וְלֹא הִזְקַקְתִּי חוֹבָה לְהַכְבִּיד עֲלֵיהֶם, תְּמִידִין וּמוּסָפִין אֵינָם אֶלָּא נַחַת רוּחַ שֶׁאָמַרְתִּי וְנַעֲשָׂה רְצוֹנִי וְדָבָר מוּעָט (ס״א אינו):\",1,0],[2,136,40,7,\"אָזְנַיִם כָּרִיתָ לִּי. לֵאמֹר ״שִׁמְעוּ בְקוֹלִי״ (ירמיה ז:כג):\",2,0],[2,136,40,7,\"כָּרִיתָ. עֲשִׂיתָם חֲלוּלִים לִשְׁמֹעַ:\",3,0],[2,136,40,8,\"אָז. בִּשְׁעַת מַתַּן תּוֹרָה אָמַרְתִּי לְפָנֶיךָ: הִנֵּה בָאתִי אֵלֶיךָ בִּמְסוֹרֶת בְּרִיתְךָ (יחזקאל כ:לז), ״נַעֲשֶׂה וְנִשְׁמָע״ (שמות כד:ז). דָּבָר זוֹ כָּתוּב עֵדוּת עָלַי בִּמְגִלַּת סֵפֶר. בְּתוֹרַת מֹשֶׁה:\",1,0],[2,136,40,9,\"וְתוֹרָתְךָ בְּתוֹךְ מֵעָי. אַף מַאֲכָלִי, עַל פִּי תוֹרָתְךָ הוּא:\",1,0],[2,136,40,10,\"בִּשַּׂרְתִּי צֶדֶק. שִׁירָה עַל הַיָּם (שמות טו:א-כ), וְשִׁירָה עַל הַבְּאֵר (במדבר כא:יז-כ), שִׁירַת דְּבוֹרָה (שופטים ה):\",1,0],[2,136,40,10,\"לֹא אֶכְלָא. לֹא אֶמְנַע, לְשׁוֹן ״וַיִּכָּלֵא הַגֶּשֶׁם״ (בראשית ח:ב):\",2,0],[2,136,40,12,\"לֹא תִכְלָא רַחֲמֶיךָ. לֹא תִמְנַע:\",1,0],[2,136,40,12,\"יִצְּרוּנִי. יִשְׁמְרוּנִי:\",2,0],[2,136,40,13,\"אָפְפוּ. סָבְבוּ:\",1,0],[2,136,40,15,\"לִסְפּוֹתָהּ. לְכַלּוֹתָהּ, כְּדִמְתַרְגְּמִינָן (דברים ב:יד) ״עַד תֹּם כָּל הַדּוֹר״ – ״עַד דְּסָף כָּל דָּרָא״:\",1,0],[2,136,40,16,\"יָשֹׁמּוּ. יִתְמָהוּ:\",1,0],[2,136,40,16,\"עַל עֵקֶב בָּשְׁתָּם. כְּשֶׁיְּקַבְּלוּ בָּשְׁתָּם עַל עֵקֶב, הַכֹּל בְּמִדָּה שֶׁמָּדְדוּ וּבְדֶרֶךְ שֶׁהָלְכוּ לְמוּלִי. עַל עֵקֶב ״וְעִקְּבוֹתֶיךָ לֹא נוֹדָעוּ״ (תהלים עז:כ); ״צְאִי לָךְ בְּעִקְבֵי הַצֹּאן״ (שיר השירים א:ח) – כֻּלָּם לְשׁוֹן מִדְרַךְ כַּף רֶגֶל הֵם, טְרַצִי״שׁ בְּלַעַ״ז. עַל עֵקֶב אַנְצִי״שׁ טְרַצִ״ישׁ:\",2,0],[2,136,40,16,\"הָאוֹמְרִים לִי הֶאָח. הָאוֹמְרִים עָלַי בִּשְׁבִילִי הֶאָח, כְּשֶׁהַצָּרָה בָּאָה מִתְהַלְּלִים בְּאֵידִי. כָּל עָנִי וְאֶבְיוֹן שֶׁבִּתְהִלִּים אֵינוֹ אֶלָּא כְּנֶגֶד יִשְׂרָאֵל:\",3,0],[2,136,40,18,\"יַחֲשָׁב לִי. יִתֵּן לִי לֵב לַחֲשֹׁב עֲנִיּוּתִי וְאֶבְיוֹנוּתִי לְהוֹשִׁיעֵנִי:\",1,0],[2,136,40,18,\"יַחֲשָׁב לִי. פֶּנְשׁוֹיִי״ט בְּלַעַ״ז:\",2,0],[2,136,41,2,\"אֶל דָּל. חוֹלֶה, לְבַקְּרוֹ; כְּעִנְיָן שֶׁנֶּאֱמַר ״מַדּוּעַ אַתָּה כָּכָה דַּל״ (שמואל ב יג:ד) דְּאַמְנוֹן:\",1,0],[2,136,41,2,\"בְּיוֹם רָעָה. זֶה גֵּיהִנֹּם (נדרים מ.), וּבָעוֹלָם הַזֶּה מַה שְּׂכָרוֹ?\",2,0],[2,136,41,3,\"ה׳ יִשְׁמְרֵהוּ וִיחַיֵּהוּ. לְמִי שֶׁמְּבַקְּרוֹ וּמֵטִיב לוֹ (נדרים מ.):\",1,0],[2,136,41,4,\"עַל עֶרֶשׂ דְּוָי. עֶרֶשׂ לִי״ט בְּלַעַ״ז. וְ״הִנֵּה עַרְשׂוֹ עֶרֶשׂ בַּרְזֶל״ (דברים ג:יא), כְּשֶׁיֶּחֱלֶה גַּם הוּא יִסְעָדֶנּוּ, מַהוּ עַל עֶרֶשׂ דְּוָי? זֶה יוֹם שְׁבִיעִי שֶׁל חוֹלִי שֶׁהוּא דָּוֶה מְאוֹד, כָּךְ נִדְרַשׁ בְּאַגָּדַת תְּהִלִּים:\",1,0],[2,136,41,4,\"כָּל מִשְׁכָּבוֹ הָפַכְתָּ בְחָלְיוֹ. אַף בְּשָׁעָה שֶׁחָלְיוֹ כָּבֵד עָלָיו, שֶׁנֶּהְפַּךְ כָּל מַרְגּוֹעוֹ וּמְנוּחָתוֹ:\",2,0],[2,136,41,5,\"אֲנִי אָמַרְתִּי ה׳ חָנֵּנִי. אֲנִי אֵין לִי מְבַקְּרִים לְטוֹבָה, וּכְשֶׁאֲנִי צוֹעֵק מִתּוֹךְ חוֹלְיִי וְאוֹמֵר ה׳ חָנֵּנִי וְגוֹ׳, אוֹיְבַי שְׂמֵחִים עָלַי וְאוֹמְרִים דָּבָר הָרַע לִי: מָתַי יָמוּת וְגוֹ׳:\",1,0],[2,136,41,7,\"שָׁוְא יְדַבֵּר. מַרְאֶה עַצְמוֹ כְּאִלּוּ הוּא מֵיצֵר, וּכְשֶׁהוּא יוֹשֵׁב לְפָנַי, יִקְבָּץ לִבּוֹ מַחְשְׁבוֹת אָוֶן לְעַצְמוֹ, מָה רָעָה יְדַבֵּר בְּצֵאתוֹ; וּכְשֶׁיּוֹצֵא לַחוּץ מְדַבֵּר אוֹתָהּ:\",1,0],[2,136,41,8,\"עָלַי יַחְשְׁבוּ דָּבָר שֶׁהוּא רָעָה לִי, וּמָה הַמַּחֲשָׁבָה?\",1,0],[2,136,41,9,\"דְּבַר בְּלִיַּעַל יָצוּק בּוֹ. כָּל רִשְׁעֻיּוֹת שֶׁעָשָׂה, יָצוּקוּ וְיִשְׁתַּפְּכוּ בְּגוּפוֹ; וְהוֹאִיל וַאֲשֶׁר שָׁכַב לֹא יוֹסִיף לָקוּם, כָּךְ מְקַלְלִים אוֹתִי:\",1,0],[2,136,41,10,\"הִגְדִּיל עָלַי עָקֵב. מַאֲרָב, כְּמוֹ ״וְאֶת עֲקֵבוֹ מִיָּם לָעִיר״ (יהושע ח:יג):\",1,0],[2,136,41,12,\"בְּזֹאת יָדַעְתִּי וְגוֹ׳. כְּשֶׁתְּחָנֵּנוּ וּתְקִימֵנוּ אֵדַע כִּי חָפַצְתָּ בִּי, כַּאֲשֶׁר לֹא יָרִיעַ אוֹיְבִי תְּרוּעַת שִׂמְחָה עָלַי, וְאֶרְאֶה כִּי בְּתֻמִּי תָּמַכְתָּ בִּי:\",1,0],[2,136,41,14,\"בָּרוּךְ ה׳. כְּשֶׁאָקוּם מֵחָלְיִי אֲבָרֶכְךָ כֵּן:\",1,0],[2,136,42,1,\"לִבְנֵי קֹרַח. אַסִּיר וְאֶלְקָנָה וַאֲבִיאָסָף (שמות ו:כד) הֵם הָיוּ תְּחִלָּה בַּעֲצַת אֲבִיהֶם, וּבִשְׁעַת הַמַּחֲלֹקֶת פָּרְשׁוּ. וּכְשֶׁנִּבְלְעוּ כָּל סְבִיבוֹתֵיהֶם וּפָתְחָה הָאָרֶץ אֶת פִּיהָ, נִשְׁאַר מְקוֹמָם בְּתוֹךְ פִּי הָאָרֶץ, כְּעִנְיָן שֶׁנֶּאֱמַר ״וּבְנֵי קֹרַח לֹא מֵתוּ״ (במדבר כו:יא). וְשָׁם אָמְרוּ שִׁירָה, וְשָׁם יִסְּדוּ הַמִּזְמוֹרִים הַלָּלוּ, וְעָלוּ מִשָּׁם, וְשָׁרְתָה עֲלֵיהֶם רוּחַ הַקֹּדֶשׁ וְנִתְנַבְּאוּ עַל הַגָּלֻיּוֹת וְעַל חֻרְבַּן הַבַּיִת וְעַל מַלְכוּת בֵּית דָּוִד:\",1,0],[2,136,42,2,\"כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם. לְשׁוֹן עָרֹג נוֹפֵל עַל קוֹל הָאַיָּל, כַּאֲשֶׁר יִפֹּל לְשׁוֹן נַהַם לָאֲרִי וְשָׁקוֹק לַדֹּב וּגְעָה לַשְּׁוָרִים, וְצִפְצוּף לָעוֹפוֹת. אָמְרוּ רַבּוֹתֵינוּ : הָאַיָּלָה הַזֹּאת חֲסִידָה שֶׁבַּחַיּוֹת, וּכְשֶׁהַחַיּוֹת צְמֵאוֹת לַמַּיִם הֵם מִתְכַּנְּסוֹת אֵלֶיהָ שֶׁתִּתְלֶה עֵינֶיהָ לַמָּרוֹם, וּמָה הִיא עוֹשָׂה? חוֹפֶרֶת גּוּמָא וּמַכְנֶסֶת קַרְנֶיהָ לְתוֹכָהּ וְגוֹעָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְרַחֵם עָלֶיהָ וְהַתְּהוֹם מַעֲלָה לָהּ מַיִם:\",1,0],[2,136,42,2,\"כְּאַיָּל תַּעֲרֹג. כְּאַיֶּלֶת תַּעֲרוֹג לֹא נֶאֱמַר וְכְאַיָּל יַעֲרוֹג לֹא נֶאֱמַר, אֶלָּא כְּאַיָּל תַּעֲרֹג. דִּבֵּר הַכָּתוּב בְּזָכָר וּבִנְקֵבָה: הַזָּכָר עוֹרֵג עַל עֵסֶק הַמַּיִם כְּמוֹ שֶׁפֵּרַשְׁנוּ, הַנְּקֵבָה כְּשֶׁהִיא כּוֹרַעַת לֵילֵד וְהִיא צוֹעֶקֶת, הַקָּדוֹשׁ בָּרוּךְ הוּא מְרַחֵם עָלֶיהָ. וּמְנַחֵם חִבֵּר תַּעֲרֹג עִם ״לְחָיָיו כַּעֲרוּגַת הַבֹּשֶׂם״ (שיר השירים ה:יג), אָכֵן לֹא יִתָּכְנוּ דְּבָרָיו. גַּם דּוֹנַשׁ פָּתַר אוֹתוֹ לְשׁוֹן קוֹל שֶׁל אַיָּל (ס״א אינו):\",2,0],[2,136,42,3,\"מָתַי אָבוֹא וְאֵרָאֶה פְּנֵי אֱלֹהִים. לַעֲלוֹת לָרֶגֶל; וְנִתְנַבֵּא כָּאן חֻרְבַּן הַבַּיִת. וְנֶאֱמַר כָּאן ״מַה תִּשְׁתּוֹחֲחִי״ שָׁלֹשׁ פְּעָמִים (תהלים מב:ו, יב; תהלים מג:ה), כְּנֶגֶד שָׁלֹשׁ מַלְכֻיּוֹת הָעֲתִידוֹת לְבַטֵּל עֲבוֹדַת הַמִּקְדָּשׁ, וְיִשְׂרָאֵל צוֹעֲקִים וְנִגְאָלִים: מַלְכוּת בָּבֶל וְיָוָן וֶאֱדוֹם:\",1,0],[2,136,42,3,\"צָמְאָה נַפְשִׁי. כְּנֶסֶת יִשְׂרָאֵל אוֹמֶרֶת כֵּן בְּגָלוּת בָּבֶל:\",2,0],[2,136,42,4,\"הָיְתָה לִּי דִמְעָתִי לֶחֶם. מִכָּאן שֶׁהַצָּרָה מַשְׂבַּעַת אֶת הָאָדָם, וְאֵינוֹ מְבַקֵּשׁ לֶאֱכֹל. וְכֵן הוּא אוֹמֵר בְּחַנָּה: ״וַתִּבְכֶּה וְלֹא תֹאכַל״ (שמואל א א:ז):\",1,0],[2,136,42,5,\"אֵלֶּה אֶזְכְּרָה כִּי אֶעֱבֹר בַּסָּךְ. פַּשְׁוִויָּ״ה בְּלַעַ״ז, אֶת זֹאת אֲנִי זוֹכֶרֶת וְנַפְשִׁי מִשְׁתַּפֶּכֶת בְּזָכְרִי עֲלִיַּת הָרְגָלִים, שֶׁהָיִיתִי עוֹבֶרֶת בִּגְדוּדֵי בְּנֵי אָדָם וּמְדַדָּה עִמָּהֶם עַד בֵּית אֱלֹהִים. סָךְ לְשׁוֹן חֶשְׁבּוֹן, סַךְ בְּנֵי אָדָם, דָּבָר אַחֵר: סָךְ לְשׁוֹן סְכָךְ וְסֻכָּה, כְּלוֹמַר בְּעֶגְלַת צָב שֶׁהָיוּ מְחֻפּוֹת כְּמִין סֻכָּה וּשְׁמָן בִּלְשׁוֹן אַגָּדָה סְקַפְּסְטָאוֹת וְאִסְקוֹפִיטִי:\",1,0],[2,136,42,5,\"אֶדַּדֵּם. אֶדַּדֶּה עִמָּהֶם, כְּמוֹ מְדַדִּים עֲגָלִים וּסְיָחִים, וְהָאִשָּׁה מְדַדָּה אֶת בְּנָהּ (שבת קכח:). וְתֵיבָה זוֹ מְשַׁמֶּשֶׁת כִּשְׁתֵּי תֵיבוֹת, אֶדַּדֶּה עִמָּהֶם, אטוויי״אמוץ שנבל״א בְּלַעַ״ז. וּמְנַחֵם חִבְּרוֹ לְשׁוֹן יְדִידוּת כְּמוֹ ״נָתַתִּי אֶת יְדִידוּת נַפְשִׁי בְּכַף אוֹיְבֶיהָ״ (ירמיה יב:ז). וְדוֹנָשׁ פָּתַר אֶדַּדֵּם לְשׁוֹן דְּמָמָה, וְכֵן ״דּוֹם לַה׳ וְהִתְחוֹלֵל לוֹ״ (תהלים לז:ז). וּפִתְרוֹן אֶדַּדֵּם אֵאָלֵם וְאַחֲרִישׁ עַד אָבֹא בֵּית אֱלֹהִים בְּרִנָּה, כְּמוֹ ״אֶשְׁמְרָה לְפִי מַחְסוֹם בְּעוֹד רָשָׁע לְנֶגְדִּי״ (תהלים לט:ב), וּכְמוֹ ״וַאֲנִי כְחֵרֵשׁ לֹא אֶשְׁמָע וּכְאִלֵּם לֹא יִפְתַּח פִּיו״ (תהלים לח:יד). וְדָם הוּא שֹׁרֶשׁ בַּתֵּיבָה:\",2,0],[2,136,42,5,\"אֶדַּדֵּם. אֶדְדֶּה עִמָּהֶם, כְּמוֹ ״וְלֹא יָכְלוּ דַּבְּרוֹ לְשָׁלוֹם״ (בראשית לז:ד) – דַּבֵּר עִמּוֹ בְּשָׁלוֹם:\",3,0],[2,136,42,5,\"הָמוֹן חוֹגֵג. שֶׁהָיוּ הוֹלְכִים לָחֹג, וְעַל כָּכָה יִסֵּד הַפַּיָּט (בשחרית פרשת שקלים ביוצר של אלה אזכרה עיין שם) ״עֹצֶם הָמוֹן חוֹגֵג וְשׁוֹטֵף כַּנָּהָר״, וּמִדְרַשׁ אַגָּדָה לְשׁוֹן יְוָנִי, שֶׁקּוֹרִין לִבְרֵכַת מַיִם חוֹגְגִין:\",4,0],[2,136,42,6,\"תִּשְׁתּוֹחֲחִי. לְשׁוֹן ״כִּי שָׁחָה לֶעָפָר נַפְשֵׁנוּ״ (תהלים מד:כו). וְשָׁח, כְּשֶׁהוּא מְדַבֵּר עַל מִתְפַּעֵל הַתָּי״ו חוֹלֶקֶת אֶת אוֹתִיּוֹת שָׁרְשֵׁי הַתֵּיבָה, כְּדֶרֶךְ כָּל תֵּיבָה שֶׁיְּסוֹדָהּ שִׁי״ן בִּתְחִלָּתָהּ:\",1,0],[2,136,42,6,\"הוֹחִילִי. הַמְתִּינִי וְצַפִּי לַגְּאֻלָּה:\",2,0],[2,136,42,7,\"אֶזְכָּרְךָ מֵאֶרֶץ יַרְדֵּן. מִמַּה שֶּׁעָשִׂיתָ לָנוּ בַּיַּרְדֵּן וַהֲרֵי חֶרְמוֹן, אַחַר כָּל הַכַּעַס שֶׁהִכְעַסְנוּךָ בְּשִׁטִּים (במדבר כה:א-ב), הוֹבַשְׁתָּ לָנוּ אֶת הַיַּרְדֵּן (יהושע ג:טז):\",1,0],[2,136,42,7,\"מֵהַר מִצְעָר. מֵהַר סִינַי שֶׁהוּא צָעִיר לִשְׁאָר הֶהָרִים. אַחַר שֶׁהִכְעַסְנוּךָ בּוֹ בְּמַעֲשֵׂה הָעֵגֶל, סָלַחְתָּ לַעֲוֹנֵינוּ וְהָלַכְתָּ עִמָּנוּ (שמות לב-לג). כָּל אֵלֶּה אֲנִי זוֹכֵר שֶׁמָּנַעְתָּ מִלְּהֵטִיב לִי, וּגְזֵרוֹתֶיךָ מִתְחַדְּשׁוֹת עָלַי זוֹ אַחַר זוֹ:\",2,0],[2,136,42,8,\"תְּהוֹם אֶל תְּהוֹם קוֹרֵא. צָרָה קוֹרְאָה לַחֲבֶרְתָּהּ:\",1,0],[2,136,42,8,\"לְקוֹל צִנּוֹרֶיךָ. טִישְׁקְנַאלְ״שׁ בְּלַעַ״ז, הַמְּקַלְּחִים עָלַי פֻּרְעָנוּת כְּמַיִם שׁוֹטְפִים, עַד כִּי כָּל מִשְׁבָּרֶיךָ וְגַלֶּיךָ עָלַי עָבָרוּ. מִשְׁבָּרֶיךָ לְשׁוֹן גַּלֵּי יָם, עַל שֶׁהָיָה גַּלָּיו עוֹלִים לְמַעְלָה וּמִשְׁתַּבְּרִים וְנוֹפְלִים:\",2,0],[2,136,42,9,\"יוֹמָם יְצַוֶּה ה׳ חַסְדּוֹ. יָבוֹא הָאוֹר וִיצַוֶּה ה׳ חַסְדּוֹ לָנוּ:\",1,0],[2,136,42,9,\"וּבַלַּיְלָה. בַּחֹשֶׁךְ הַצָּרָה:\",2,0],[2,136,42,9,\"שִׁירֹה עִמִּי. תְּהֵא חֲנִיָּתוֹ בְּתוֹכֵנוּ, שִׁירָה לְשׁוֹן חֲנִיָּה, כְּדִמְתַרְגְּמִינָן ״וַיִּחַן״ (שמות יט:ב) ״וּשְׁרָא״. זוֹ לָמַדְתִּי מִתּוֹךְ מָסֹרֶת הַגְּדוֹלָה שֶׁחִבֵּר אֶת זֶה עִם ״וַיְהִי שִׁירוֹ חֲמִשָּׁה וָאָלֶף״ (מלכים א ה:יב), בְּאַלְפָ״א בֵּיתָ״א שֶׁל שְׁתֵּי תֵיבוֹת הַחֲלוּקִים בְּפִתְרוֹנָן, לִמֵּד שֶׁאֵין זֶה לְשׁוֹן שִׁיר. וּמִדְרַשׁ הָאַגָּדָה פּוֹתְרוֹ לְשׁוֹן שִׁיר, וְכָךְ הוּא פּוֹתְרוֹ: שֶׁכָּךְ יִשְׂרָאֵל אוֹמְרִים לְהַקָּדוֹשׁ בָּרוּךְ הוּא, זָכְרֵנוּ מַה שֶּׁעָשִׂיתָ לָנוּ בְּמִצְרַיִם, מִצְוָה אַחַת שֶׁצִּוִּיתָנוּ בַּיּוֹם בְּעֶרֶב פֶּסַח וּשְׁמַרְנוּהָ, וּבַלַּיְלָה גְּאַלְתָּנוּ וְשַׁרְנוּ לְפָנֶיךָ אֶת הַהַלֵּל, וְעַכְשָׁיו הַרְבֵּה מִצְווֹת אֲנִי שׁוֹמֶרֶת, וְעַל זֹאת אוֹמְרָה לְאֵל סַלְעִי לָמָּה שְׁכַחְתָּנִי וְגוֹ׳:\",3,0],[2,136,42,10,\"קוֹדֵר. לְשׁוֹן שַׁחֲרוּת, כְּמוֹ ״וְקָדַר עֲלֵיהֶם״ (מיכה ג:ו):\",1,0],[2,136,42,11,\"בְּרֶצַח בְּעַצְמוֹתַי חֵרְפוּנִי צוֹרְרָי. נִדְמֶה לִי כְּאִלּוּ הוֹרְגִים אוֹתִי, כָּךְ עָצוּר בְּעַצְמוֹתַי (ירמיהו כ:ט) מַה שֶּׁצּוֹרְרַי מַכְעִיסִין וּמְחָרְפִין אוֹתִי:\",1,0],[2,136,42,12,\"פָּנַי וֵאלֹהָי. הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא אוֹר פָּנַי וֵאלֹהַי, עֲדַיִן יֵשׁ לִי בּוֹ תִּקְוָה, וְלָמָּה תֶּהֱמִי?\",1,0],[2,136,43,1,\"שָׁפְטֵנִי. הַקְּמֵנִי:\",1,0],[2,136,43,1,\"מִגּוֹי לֹא חָסִיד. הוּא אֱדוֹם, שֶׁגָּר בֵּין שְׁנֵי צַדִּיקִים וְלֹא לָמַד מִמַּעֲשֵׂיהֶם (סנהדרין לט:):\",2,0],[2,136,43,3,\"שְׁלַח אוֹרְךָ וַאֲמִתְּךָ. מֶלֶךְ הַמָּשִׁיחַ שֶׁנִּדְמָה לְאוֹר, שֶׁנֶּאֱמַר (תהלים קלב:יז) ״עָרַכְתִּי נֵר לִמְשִׁיחִי״, וְאֵלִיָּהוּ הַנָּבִיא שֶׁהוּא אֲמִתִּי, נָבִיא נֶאֱמָן:\",1,0],[2,136,43,3,\"יַנְחוּנִי. מִינְטְרוֹ״נְט מוֹ״י בְּלַעַ״ז:\",2,0],[2,136,43,4,\"אֶל אֵל. אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא שִׂמְחַת גִּילִי:\",1,0],[2,136,43,4,\"וְאוֹדְךָ בְכִנּוֹר. עַל שֶׁהוֹצֵאתַנִי:\",2,0],[2,136,44,2,\"בְּאָזְנֵינוּ שָׁמַעְנוּ. מִכָּאן אַתָּה לָמֵד שֶׁהָיוּ מְדַבְּרִים בְּנֵי קֹרַח בִּשְׁבִיל דּוֹרוֹת הַלָּלוּ הַבָּאִים אַחֲרֵיהֶם, שֶׁאִלּוּ בִּשְׁבִיל עַצְמָם לֹא הָיָה לָהֶם לוֹמַר אֲבוֹתֵינוּ סִפְּרוּ לָנוּ, שֶׁהֲרֵי הֵם עַצְמָם רָאוּ נִסֵּי הַמִּדְבָּר וְהַיָּם וְהַיַּרְדֵּן וּמִלְחֲמוֹת יְהוֹשֻׁעַ. כָּךְ מְפֹרָשׁ בְּאַגָּדַת תְּהִלִּים (מדרש תהלים מד:א):\",1,0],[2,136,44,3,\"תָּרַע לְאֻמִּים. הֲרֵעוֹתָ לְשִׁבְעָה אֻמּוֹת גְּדוֹלוֹת וְשִׁלַּחְתָּם מִפָּנֵינוּ, וְאַתָּה בְּיָדְךָ כֹּחֲךָ הוֹרַשְׁתָּם מִתּוֹךְ אַרְצָם וַתִּטָּעֵם לַאֲבוֹתֵינוּ בְּתוֹכָהּ:\",1,0],[2,136,44,4,\"רְצִיתָם. לְשׁוֹן רָצוֹן:\",1,0],[2,136,44,5,\"צַוֵּה יְשׁוּעוֹת יַעֲקֹב. גַּם לַבָּאִים אַחֲרֵינוּ:\",1,0],[2,136,44,6,\"נָבוּס קָמֵינוּ. נִרְמֹס וְנִרְפֹּס אוֹיְבֵינוּ, לְשׁוֹן ״מִתְבּוֹסֶסֶת בְּדָמָיִךְ״ (יחזקאל טז:ו), ״תָּבוּס נֹפֶת״ (משלי כז:ז), ״וְהָיוּ כְגִבּוֹרִים בּוֹסִים בְּטִיט חוּצוֹת״ (זכריה י:ה):\",1,0],[2,136,44,10,\"אַף זָנַחְתָּ וַתַּכְלִימֵנוּ. אַף אִם אַתָּה תַּכְלִימֵנוּ אָנוּ שִׁמְךָ לְעוֹלָם נוֹדֶה:\",1,0],[2,136,44,11,\"תְּשִׁיבֵנוּ אָחוֹר. לְשׁוֹן הֹוֶה הוּא:\",1,0],[2,136,44,11,\"שָׁסוּ לָמוֹ. בָּזְזוּ נְכָסֵינוּ אִישׁ לוֹ:\",2,0],[2,136,44,12,\"זֵרִיתָנוּ. אֶפַנְדִישְׁנוֹ״שׁ בְּלַעַ״ז:\",1,0],[2,136,44,20,\"כִּי דִכִּיתָנוּ בִּמְקוֹם תַּנִּים. כִּי זֶה מְשַׁמֵּשׁ בִּלְשׁוֹן כַּאֲשֶׁר: וְאַף כַּאֲשֶׁר הִשְׁפַּלְתָּנוּ בְּאֶרֶץ עֲרָבָה וְשׁוּחָה (ירמיהו ב:ו), מִדְבָּר מְקוֹם תַּנִּים, וְכִסִּיתָ עָלֵינוּ בְצַלְמָוֶת חֹשֶׁךְ, אַף בְּכָל זֹאת אִם שָׁכַחְנוּ שֵׁם אֱלֹהֵינוּ, הוּא יַחֲקֹר זֹאת, כִּי הוּא יוֹדֵעַ תַּעֲלֻמוֹת וְגוֹ׳:\",1,0],[2,136,44,23,\"כְּצֹאן טִבְחָה. כְּצֹאן שֶׁל טַבָּח:\",1,0],[2,136,44,27,\"וּפְדֵנוּ לְמַעַן חַסְדֶּךָ. אֵין אָנוּ בָּאִים בְּכֹחַ מַעֲשֵׂינוּ, אֶלָּא לְמַעַן חַסְדְּךָ עֲשֵׂה:\",1,0],[2,136,45,1,\"עַל שׁוֹשַׁנִּים. לִכְבוֹד תַּלְמִידֵי חֲכָמִים יִסְּדוּ הַשִּׁיר הַזֶּה, שֶׁהֵם רַכִּים כְּשׁוֹשַׁנִּים וְנָאִים כְּשׁוֹשַׁנִּים, וּמַרְטִיבִים מַעֲשִׂים טוֹבִים כְּשׁוֹשַׁנִּים (שיר השירים ב:ג):\",1,0],[2,136,45,1,\"מַשְׂכִּיל. עַל יְדֵי תּוּרְגְּמָן (פסחים קיז.):\",2,0],[2,136,45,1,\"שִׁיר יְדִידוֹת. שִׁיר אֲהוּבִים, שִׁיר שֶׁל שֶׁבַח לָהֶם, לְהַאֲהִיבָם עַל הַבְּרִיּוֹת וּלְהַאֲהִיב תּוֹרָתָם עֲלֵיהֶם:\",3,0],[2,136,45,2,\"רָחַשׁ לִבִּי. כָּךְ הִתְחִיל הַמְשׁוֹרֵר בְּשִׁירוֹ: הִשְׁרִיץ לִבִּי בְּקִרְבִּי דָּבָר טוֹב בְּשִׁבְחֲךָ אַתָּה, תַּלְמִיד חָכָם;\",1,0],[2,136,45,2,\"רָחַשׁ. לְשׁוֹן נַעֲנוּעַ, וְכֵן כָּל לְשׁוֹן שִׁירוּץ וְרִיחוּשׁ:\",2,0],[2,136,45,2,\"אוֹמֵר אָנִי מַעֲשַׂי לַמֶּלֶךְ. הַשִּׁיר הַזֶּה שֶׁיִּסַּדְתִּי וְעָשִׂיתִי, אֲנִי אוֹמְרוֹ לַמֶּלֶךְ, שֶׁנֶּאֱמַר (משלי ח:טו) ״בִּי מְלָכִים יִמְלֹכוּ״:\",3,0],[2,136,45,2,\"לְשׁוֹנִי. צַח בְּשִׁירִים כְּעֵט סוֹפֵר מָהִיר. רָאִיתִי בִּיסוֹדוֹ שֶׁל רַבִּי מֹשֶׁה הַדַּרְשָׁן: מָהִיר בִּלְשׁוֹן עֲרָבִי בָּקִי:\",4,0],[2,136,45,3,\"יָפְיָפִיתָ מִבְּנֵי אָדָם. הָעוֹסְקִים בִּמְלֶאכֶת חַיֵּי שָׁעָה, לָמָּה? לְפִי שֶׁהוּצַק חֵן בְּשִׂפְתוֹתֶיךָ לְהוֹרוֹת כַּהֲלָכָה. הוּצַק – כְּמוֹ נִשְׁפַּךְ, כְּמוֹ ״מוּצָקוֹת״ (זכריה ד:ב), ״וַיִּצֹק עָלֶיהָ שֶׁמֶן״ (ויקרא ב:א):\",1,0],[2,136,45,3,\"עַל כֵּן בֵּרַכְךָ. כְּמוֹ שֶׁנֶּאֱמַר ״ה׳ עֹז לְעַמּוֹ יִתֵּן״, וּמַה שְּׂכָרָן? ״ה׳ יְבָרֵךְ אֶת עַמּוֹ בַשָּׁלוֹם״ (תהלים כט:יא):\",2,0],[2,136,45,4,\"חֲגוֹר חַרְבְּךָ עַל יָרֵךְ. לְהִלָּחֵם מִלְחַמְתָּהּ שֶׁל תּוֹרָה, וְהוּא הוֹדְךָ וְהוּא הֲדָרֶךָ:\",1,0],[2,136,45,5,\"עַל דְּבַר אֱמֶת. לְהוֹרוֹת כַּדָּת, וּלְהִתְנַהֵג בְּעַנְוַת צֶדֶק:\",1,0],[2,136,45,5,\"וְתוֹרְךָ. הַתּוֹרָה וּדְבַר הָאֱמֶת שֶׁתַּעֲסֹק בּוֹ, הִיא תוֹרֶה אוֹתְךָ טַכְסִיסֵי הַמִּלְחָמָה לַעֲשׂוֹת יְמִינֶךָ נוֹרָאוֹת. לְפִי שֶׁהִזְכִּיר תַּלְמוּד תּוֹרָה בִּלְשׁוֹן מִלְחָמָה, נוֹפֵל בּוֹ לְשׁוֹן יָמִין הַמְיֻמֶּנֶת לְהִלָּחֵם, (כְּלוֹמַר הֶסְדֵּר לְהִלָּחֵם בְּיַד יָמִין):\",2,0],[2,136,45,6,\"חִצֶּיךָ שְׁנוּנִים בְּלֵב אוֹיְבֵי הַמֶּלֶךְ. שְׁנוּנִים אֲגִיֵּישׁוֹ״ץ בְּלַעַ״ז, וַהֲרֵי זֶה מִקְרָא מְסֹרָס. מָצִינוּ שֶׁהַתַּלְמִידִים קְרוּיִים חִצִּים, שֶׁנֶּאֱמַר ״כְּחִצִּים בְּיַד גִּבּוֹר כֵּן בְּנֵי הַנְּעוּרִים״ (תהלים קכז:ד). וְתַלְמִידֵי חֲכָמִים (הַמְּזֻיָּנִים) בַּהֲלָכָה קְרוּיִים אוֹיְבִים זֶה לָזֶה לְפִי שָׁעָה, שֶׁנֶּאֱמַר ״לֹא יֵבֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר״ (תהלים קכז:ה):\",1,0],[2,136,45,6,\"עַמִּים תַּחְתֶּיךָ יִפְּלוּ. בִּשְׂכַר הַתּוֹרָה יִפְּלוּ הָעוֹבְדֵי גִּלּוּלִים תַּחְתֵּיהֶם שֶׁל יִשְׂרָאֵל:\",2,0],[2,136,45,7,\"כִּסְאֲךָ אֱלֹהִים. כִּסְאֲךָ, שַׂר וְשׁוֹפֵט, לְעוֹלָם וָעֶד; כְּעִנְיָן שֶׁנֶּאֱמַר ״נְתַתִּיךָ אֱלֹהִים לְפַרְעֹה״ (שמות ז:א). וְלָמָּה? בִּשְׁבִיל שֶׁשֵּׁבֶט מִישׁוֹר שֵׁבֶט מַלְכוּתֶךָ. שֶׁמִּשְׁפָּטֶיךָ אֱמֶת וְרָאוּי אַתָּה לִמְלוֹךְ:\",1,0],[2,136,45,8,\"מְשָׁחֲךָ וְגוֹ׳ שֶׁמֶן שָׂשׂוֹן. כָּל לְשׁוֹן גְּדֻלָּה נוֹפֵל עָלֶיהָ לְשׁוֹן מְשִׁיחַת שֶׁמֶן, כְּדַת הַמְּלָכִים:\",1,0],[2,136,45,9,\"מֹר וַאֲהָלוֹת קְצִיעוֹת. ״קִדָּה״ (שמות ל:כד) מְתַרְגְּמִינָן ״קְצִיעֲתָא״:\",1,0],[2,136,45,9,\"כָּל בִּגְדוֹתֶיךָ. כָּל בְּגָדֶיךָ מְרִיחִים כְּרֵיחַ בְּשָׂמִים, וּמִדְרָשׁוֹ (ירושלמי פאה א, א): כָּל בְּגִידוֹתֶיךָ וְסִרְחוֹנֶיךָ מִתְכַּפְּרִים וּמְרִיחִים רֵיחַ עָרֵב:\",2,0],[2,136,45,9,\"מִן הֵיכְלֵי שֵׁן מִנִּי שִׂמְּחוּךָ. יוֹתֵר מֵהֵיכְלֵי שֵׁן מְשֻׁבָּחִים הַהֵיכָלוֹת הַמְּתֻקָּנִים לְךָ בְּגַן עֵדֶן לְשַׂמֵּחֲךָ בָּהֶם. שֵׁן אִיבוֹיְיר״א בְּלַעַ״ז:\",3,0],[2,136,45,9,\"מִנִּי שִׂמְּחוּךָ. הֵיכָלוֹת אֲשֶׁר מִנִּי, הֵם שִׂמְּחוּךָ, הַנּוֹתְנִים שְׂכָרְךָ:\",4,0],[2,136,45,10,\"בְּנוֹת מְלָכִים. יִהְיוּ מְבַקְּרוֹת אוֹתְךָ, כְּעִנְיָן שֶׁנֶּאֱמַר: ״וְשָׂרוֹתֵיהֶם מֵינִיקוֹתַיִךְ״ (ישעיהו מט:כג):\",1,0],[2,136,45,10,\"בְּיִקְּרוֹתֶיךָ. קוֹ״ף דָּגוּשׁ, לְפִי שֶׁהוּא לְשׁוֹן בִּקּוּר, וְאַף עַל פִּי שֶׁכָּתוּב יוֹ״ד לְפָנֶיהָ. רָאִיתִי בְּנִקּוּד רַב סְעַדְיָה תֵּיבָה זוֹ סְדוּרָה עִם ״מִי נָתַן לִמְשִׁיסָּה יַעֲקֹב״ (ישעיהו מב:כד), שֶׁכָּתוּב בּוֹ יוֹ״ד וְהַסָּמֶ״ךְ מֻדְגֶּשֶׁת. וּמְנַחֵם חִבְּרוֹ לְשׁוֹן יוֹקֶר, כְּמוֹ ״יְקָר מִכְּלִי פָז״ (איוב כח:יז) (ס״א אינו):\",2,0],[2,136,45,10,\"שֵׁגַל. מַלְכָּה, כְּמוֹ ״וְהַשֵּׁגַל יוֹשֶׁבֶת אֶצְלוֹ״ (נחמיה ב:ו), ״וְיִשְׁתּוֹן בְּהוֹן מַלְכָּא רַבְרְבָנוֹהִי שֵׁגְלָתֵיהּ וּלְחֵינָתֵיהּ״ (דניאל ה:ב). אִשְׁתְּךָ תִּתְיַצֵּב לִימִינְךָ:\",3,0],[2,136,45,10,\"בְּכֶתֶם אוֹפִיר. בִּקְבוּצַת עֲדִי זָהָב הַבָּא מֵאוֹפִיר:\",4,0],[2,136,45,11,\"שִׁמְעִי בַת וּרְאִי. שִׁמְעִי כְּנֶסֶת יִשְׂרָאֵל וּרְאִי דֶּרֶךְ הַטּוֹב (שיר השירים רבה א:ג):\",1,0],[2,136,45,11,\"וְהַטִּי אָזְנֵךְ. לַתּוֹרָה:\",2,0],[2,136,45,11,\"וְשִׁכְחִי עַמֵּךְ. מֵעֵבֶר הַנָּהָר שֶׁאַתְּ גְּדֵלָה בֵּינֵיהֶם:\",3,0],[2,136,45,11,\"וּבֵית אָבִיךְ. עֲבוֹדָה זָרָה שֶׁעָבְדוּ אֲבוֹתֶיךָ בְּעֵבֶר הַנָּהָר (יהושע כד:ב):\",4,0],[2,136,45,12,\"וְיִתְאָו הַמֶּלֶךְ יָפְיֵךְ. וְאִם תַּעֲשִׂי כֵּן, יִתְאַוֶּה הַמֶּלֶךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לְנוֹיֵי מַעֲשַׂיִךְ:\",1,0],[2,136,45,13,\"וּבַת צֹר בְּמִנְחָה פָּנַיִךְ יְחַלּוּ. כְּמוֹ ״וַיְחַל מֹשֶׁה״ (שמות לב:יא), וּבִשְׂכַר זֶה תִּזְכּוּ שֶׁיָּבִיאוּ לְךָ אֲשְׁכָּרִים וְדוֹרוֹן אוֹתָם שֶׁהֵם עַכְשָׁיו עֲשִׁירֵי עָם:\",1,0],[2,136,45,14,\"כָּל כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה וְגוֹ׳. אוֹתָם שֶׁכָּל כָּבוֹד תָּלוּי בָּהֶם, וְהֵם כְּנֵסִיּוֹת שֶׁל מֶלֶךְ אֲשֶׁר נָהֲגוּ עַצְמָם בִּצְנִיעוּת, עַתָּה בִּגְדֵיהֶם חֲשׁוּבִים מִמִּשְׁבְּצוֹת זָהָב שֶׁל כֹּהֲנִים גְּדוֹלִים (תנחומא, וישלח ו). מִשְׁבְּצוֹת קָאטוֹנ״שׁ בְּלַעַ״ז:\",1,0],[2,136,45,15,\"לִרְקָמוֹת תּוּבַל לַמֶּלֶךְ. בְּבִגְדֵי רִקְמָה יְבִיאוּם מִנְחָה לַמֶּלֶךְ עַל כָּל הָאָרֶץ. רְקָמוֹת אברודי״ץ בְּלַעַ״ז, זֶה שֶׁנֶּאֱמַר ״וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה וְגוֹ׳״ (ישעיהו סו:כ):\",1,0],[2,136,45,15,\"בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ. יֵלְכוּ אַחֲרֵיהֶם כְּעִנְיָן שֶׁנֶּאֱמַר (זכריה ח:כג) ״וְהֶחֱזִיקוּ בִּכְנַף אִישׁ יְהוּדִי וְגוֹ׳ לֵאמֹר נֵלְכָה עִמָּכֶם כִּי שָׁמַעְנוּ אֱלֹהִים עִמָּכֶם״:\",2,0],[2,136,45,15,\"מוּבָאוֹת לָךְ. כְּלַפֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר הַמְשׁוֹרֵר:\",3,0],[2,136,45,17,\"תַּחַת אֲבֹתֶיךָ וְגוֹ׳. לְכָל אֶחָד מִיִּשְׂרָאֵל אָמַר:\",1,0],[2,136,45,18,\"אַזְכִּירָה שִׁמְךָ. כְּלַפֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר הַמְשׁוֹרֵר:\",1,0],[2,136,46,1,\"עַל עֲלָמוֹת. שֵׁם שֶׁל כְּלִי שִׁיר בְּדִבְרֵי הַיָּמִים (דברי הימים א טו:כ):\",1,0],[2,136,46,3,\"בְּהָמִיר אָרֶץ. לֶעָתִיד לָבוֹא, בַּיּוֹם שֶׁנֶּאֱמַר ״וְהָאָרֶץ כַּבֶּגֶד תִּבְלֶה״ (ישעיה נא:ו). רָאוּ בְּנֵי קֹרַח נֵס שֶׁנַּעֲשָׂה לָהֶם, שֶׁנִּבְלְעוּ כָּל סְבִיבוֹתֵיהֶם וְהֵם עָמְדוּ בָּאֲוִיר, וְאָמְרוּ לְיִשְׂרָאֵל בְּרוּחַ הַקֹּדֶשׁ, שֶׁדּוּגְמַת הַנֵּס הַזֶּה יִהְיֶה עָשׂוּי לָהֶם לֶעָתִיד (סנהדרין קי.):\",1,0],[2,136,46,4,\"יֶהֱמוּ יֶחְמְרוּ מֵימָיו. יְגָרְשׁוּ רֶפֶשׁ וְחֹמֶר וָטִיט (ישעיהו נז:כ) כְּמִשְׁפָּטָם, וּמְנַחֵם חִבְּרוֹ כְּמוֹ ״מֵעַי חֳמַרְמָרוּ״, (איכה א:כ) רגורזרונ״ט בְּלַעַ״ז:\",1,0],[2,136,46,4,\"יִרְעֲשׁוּ הָרִים בְּגַאֲוָתוֹ. שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנִּזְכָּר בְּרֹאשׁ הַמִּזְמוֹר (תהלים מו:ב):\",2,0],[2,136,46,5,\"נָהָר פְּלָגָיו. שׁוֹשְׁרוֹיִישִׁיל״שׁ בְּלַעַ״ז:\",1,0],[2,136,46,5,\"נָהָר. גַּן עֵדֶן (בראשית ב:י):\",2,0],[2,136,46,6,\"לִפְנוֹת בֹּקֶר. לְקֵץ הַגְּאֻלָּה:\",1,0],[2,136,46,7,\"הָמוּ גוֹיִם. לְשׁוֹן ״הוֹמֶה״ (מלכים א א:מא):\",1,0],[2,136,46,7,\"תָּמוּג. תָּמֵס, כֵּן פָּתַר מְנַחֵם (שמות טו:טו) ״נָמֹגוּ כָּל יוֹשְׁבֵי כְנָעַן״, וְכֵן (יחזקאל כא:כ) ״לָמוּג לֵב״, אֲבָל דּוּנָשׁ פָּתַר אוֹתָם לְשׁוֹן הֲנָעָה, וְכֵן (שמואל א יד:טז) ״הֶהָמוֹן נָמוֹג וַיֵּלֶךְ וַהֲלֹם״ וְכֵן כֻּלָּם:\",2,0],[2,136,46,9,\"אֲשֶׁר שָׂם שַׁמּוֹת. אֲשֶׁר שָׂם אַרְצוֹת הַגּוֹיִם שְׁמָמָה:\",1,0],[2,136,46,10,\"מַשְׁבִּית מִלְחָמוֹת. מֵעָלֵינוּ:\",1,0],[2,136,46,10,\"עַד קְצֵה הָאָרֶץ. שֶׁכָּל אַרְצוֹת הַגּוֹיִם יִהְיוּ עִמָּנוּ בְּשָׁלוֹם:\",2,0],[2,136,46,10,\"קֶשֶׁת. הַגּוֹיִם יְשַׁבֵּר:\",3,0],[2,136,46,10,\"עֲגָלוֹת יִשְׂרֹף בָּאֵשׁ. רִכְבֵי מִלְחָמוֹת:\",4,0],[2,136,46,11,\"הַרְפּוּ. עַצְמְכֶם מִלָּבוֹא עוֹד עַל יְרוּשָׁלַיִם:\",1,0],[2,136,46,11,\"וּדְעוּ כִּי אָנֹכִי אֱלֹהִים. שֶׁאֶעֱשֶׂה דִּין בָּכֶם:\",2,0],[2,136,46,11,\"אָרוּם בָּאָרֶץ. אֶתְרוֹמֵם בְּנִקְמָתִי אֲשֶׁר אֶעֱשֶׂה בַּגּוֹיִם:\",3,0],[2,136,47,2,\"תִּקְעוּ כָף. הִתְעָרְבוּ יַחַד זֶה עִם זֶה לְהָרִיעַ לֵאלֹהִים בְּקוֹל רִנָּה:\",1,0],[2,136,47,4,\"יַדְבֵּר עַמִּים תַּחְתֵּינוּ. יִתֵּן דֶּבֶר בָּעוֹבְדֵי כוֹכָבִים תַּחַת נַפְשֵׁנוּ, לִהְיוֹת חֲמָתוֹ מִתְקָרֶרֶת בָּהֶם וְאֵלּוּ נִצּוֹלִים, כְּעִנְיָן שֶׁנֶּאֱמַר: ״וְנָתַתִּי כָפְרְךָ מִצְרַיִם וְגוֹ׳״ (ישעיהו מג:ג). וּמְנַחֵם חִבֵּר יַדְבֵּר לְשׁוֹן הַנְהָגָה:\",1,0],[2,136,47,5,\"יִבְחַר לָנוּ וְגוֹ׳. וְיַחֲזִירֵנוּ לְתוֹכָהּ, וְאָז יִתְעַלֶּה בִּתְרוּעָה וְקוֹל שׁוֹפָר – שֶׁנִּתְקַע לְפָנָיו בְּשִׁיר עַל עוֹלוֹת וְזִבְחֵי שְׁלָמִים, וְנֹאמַר: זַמְּרוּ אֱלֹהִים וְגוֹ׳:\",1,0],[2,136,47,9,\"מָלַךְ אֱלֹהִים עַל גּוֹיִם. כָּךְ יֹאמְרוּ הַכֹּל:\",1,0],[2,136,47,9,\"יָשַׁב עַל כִּסֵּא קָדְשׁוֹ. עַכְשָׁיו הַכִּסֵּא שָׁלֵם וּבִגְדוּלָּה נִכֶּרֶת (פסיקתא רבתי ג:טז), וְיַגִּידוּ כִּי נֶאֶסְפוּ לְעִירוֹ:\",2,0],[2,136,47,10,\"נְדִיבֵי עַמִּים. שֶׁהִתְנַדְּבוּ עַצְמָם לִטְבֹּחַ וְלַהֲרֹג עַל קְדֻשַּׁת שְׁמוֹ:\",1,0],[2,136,47,10,\"עַם אֱלֹהֵי אַבְרָהָם. שֶׁהָיָה נְדִיב לֵב הָרִאשׁוֹן תְּחִלָּה לַגֵּרִים (סוכה מט:). עַתָּה נוֹדַע כִּי לֵאלֹהִים מָגִנֵּי אֶרֶץ הַיְכֹלֶת בְּיָדוֹ לִהְיוֹת לְמָגֵן עַל כָּל הַבּוֹטְחִים בּוֹ:\",2,0],[2,136,48,2,\"בְּעִיר אֱלֹהֵינוּ. לֶעָתִיד לָבֹא, כְּשֶׁיִּבְנֶה אֶת עִירוֹ, יִהְיֶה בִּשְׁבִילָהּ גָּדוֹל וּמְהֻלָּל:\",1,0],[2,136,48,3,\"יְפֵה נוֹף. עִיר שֶׁהוּא נוֹף יָפֶה, לְשׁוֹן נוֹף שֶׁל אִילָן. דָּבָר אַחֵר: כַּלַּת שֶׁל יוֹפִי, שֶׁכֵּן קוֹרִין בְּכַרְכֵּי הַיָּם לְכַלָּה נִינְפִי (ראש השנה כו.). וּמְנַחֵם חִבְּרוֹ כְּמוֹ ״שְׁלֹשֶׁת הַנָּפֶת״ (יהושע יז:יא), קוֹנְטְרִיאָ״ה בְּלַעַ״ז. אֲבָל דּוֹנָשׁ פָּתַר אוֹתוֹ לְשׁוֹן נוֹף שֶׁל אִילָן, וְנִקְרָא הַר צִיּוֹן, יְפֵה נוֹף כִּי הוּא הַר הַזֵּיתִים (ס״א אינו):\",1,0],[2,136,48,3,\"מְשׂוֹשׂ כָּל הָאָרֶץ. וּמַה הִיא מְשׂוֹשָׂהּ? יַרְכְּתֵי צָפוֹן, אַנְגְלָ״שׁ בְּלַעַ״ז, ״יֶרֶךְ הַמִּזְבֵּחַ צָפוֹנָה״ (ויקרא א:יא) שֶׁשָּׁם שׁוֹחֲטִין חַטָּאוֹת וַאֲשָׁמוֹת, וּמִי שֶׁהָיָה עָצֵב עַל עֲבֵרוֹת שֶׁבְּיָדוֹ מֵבִיא חַטָּאוֹת וַאֲשָׁמוֹת וּמִתְכַּפֵּר לוֹ, וְהוּא יוֹצֵא מִשָּׁם שָׂמֵחַ; וְעַל יְדֵי הַקָּרְבָּנוֹת טוֹבָה בָּאָה:\",2,0],[2,136,48,4,\"נוֹדַע לְמִשְׂגָּב. כְּשֶׁיִּשְׁכֹּן בָּהּ לֶעָתִיד, יֹאמְרוּ כֵּן:\",1,0],[2,136,48,5,\"הַמְּלָכִים נוֹעֲדוּ. לְהִלָּחֵם עָלֶיהָ בְּמִלְחֶמֶת גּוֹג וּמָגוֹג (יחזקאל לח:א-ג):\",1,0],[2,136,48,5,\"עָבְרוּ יַחְדָּו. לַמִּלְחָמָה:\",2,0],[2,136,48,6,\"הֵמָּה רָאוּ. אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹצֵא וְנִלְחָם בַּגּוֹיִם הָהֵם, כֵּן תָּמָהוּ:\",1,0],[2,136,48,6,\"נֶחְפָּזוּ. פוֹרְנְ״ט אָטוֹרְדִי״ץ בְּלַעַ״ז, כְּמוֹ ״וּבְפַחֲזוּתָם״ (ירמיהו כג:לב):\",2,0],[2,136,48,8,\"בְּרוּחַ קָדִים. הוּא לְשׁוֹן פּוּרְעָנוּת, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִפְרָע בּוֹ מִן הָרְשָׁעִים, כְּמוֹ שֶׁנֶּאֱמַר ״וַיּוֹלֶךְ ה׳ אֶת הַיָּם בְּרוּחַ קָדִים וְגוֹ׳״ (שמות יד:כא). וְכֵן בְּצוֹר: ״רוּחַ הַקָּדִים שִׁבְּרֵךְ בְּלֵב יַמִּים״ (יחזקאל כז:כו). ״כְּרוּחַ קָדִים אֲפִיצֵם לִפְנֵי אוֹיֵב״ (ירמיהו יח:יז):\",1,0],[2,136,48,8,\"אֳנִיּוֹת תַּרְשִׁישׁ. הֵם שְׁכֵינֵי צוֹר, הִיא אַפְרִיקָא, וּמֵאֱדוֹם הִיא:\",2,0],[2,136,48,9,\"כַּאֲשֶׁר שָׁמַעְנוּ. הַנֶּחָמוֹת מִפִּי הַנְּבִיאִים כֵּן רָאִינוּ:\",1,0],[2,136,48,10,\"דִּמִּינוּ אֱלֹהִים חַסְדֶּךָ. הַנָּבִיא חוֹזֵר וּמִתְפַּלֵּל לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְאוֹמֵר: דִּמִּינוּ וְקִוִּינוּ אֶל חַסְדֶּךָ, לִרְאוֹת תְּשׁוּעָתְךָ זוֹ בְּקֶרֶב הֵיכָלֶךָ. וּמְנַחֵם פָּתַר אוֹתוֹ לְשׁוֹן מַחֲשָׁבָה, כְּמוֹ ״אַל תְּדַמִּי בְנַפְשֵׁךְ״ (אסתר ד:יג):\",1,0],[2,136,48,11,\"כְּשִׁמְךָ אֱלֹהִים כֵּן תְּהִלָּתְךָ. כַּאֲשֶׁר שִׁמְךָ גָּדוֹל, כֵּן תְּהִלָּתְךָ גָּדוֹל בְּפִי כֹּל:\",1,0],[2,136,48,12,\"תָּגֵלְנָה בְּנוֹת יְהוּדָה. כָּל שְׁאָר עָרֵי יְהוּדָה הֵם לְצִיּוֹן בָּנוֹת, כְּמוֹ ״וַיִּלְכֹּד אֶת קְנָת וְאֶת בְּנֹתֶיהָ״ (במדבר לב:מב):\",1,0],[2,136,48,12,\"לְמַעַן מִשְׁפָּטֶיךָ. שֶׁתַּעֲשֶׂה דִּין בָּאֻמּוֹת:\",2,0],[2,136,48,13,\"סֹבּוּ צִיּוֹן. אַתֶּם, הַבּוֹנִים אוֹתָהּ:\",1,0],[2,136,48,13,\"סִפְרוּ. לְשׁוֹן מִנְיָן: דְּעוּ כַּמָּה מִגְדָּלִים רְאוּיִים לָהּ:\",2,0],[2,136,48,14,\"לְחֵילָה. לְחוֹמוֹתֶיהָ, כְּמוֹ ״חֵיל וְחוֹמָה״ (איכה ב:ח):\",1,0],[2,136,48,14,\"פַּסְּגוּ אַרְמְנוֹתֶיהָ. הַגְבִּיהוּ בִּירְנִיּוֹתֶיהָ, כְּמוֹ ״אַשְׁדּוֹת הַפִּסְגָּה״ (דברים ג:יז) דִּמְתַרְגְּמִינָן ״רָמָתָא״:\",2,0],[2,136,48,14,\"לְמַעַן תְּסַפְּרוּ. אֶת גָּבְהָהּ וְאֶת יָפְיָהּ לְדוֹר שֶׁאַחֲרֵיכֶם:\",3,0],[2,136,48,15,\"עַלְמוּת. כְּאָדָם הַמַּנְהִיג אֶת בְּנוֹ קָטָן לְאַט, וּמְנַחֵם פָּתַר אוֹתוֹ לְשׁוֹן עוֹלָם, וְכֵן פִּתְרוֹנוֹ יְנַהֲגֵנוּ לְעוֹלָמִים:\",1,0],[2,136,49,2,\"שִׁמְעוּ זֹאת כָּל הָעַמִּים. לְפִי שֶׁמִּזְמוֹר זֶה מְיֻסָּד עַל בְּנֵי אָדָם הַבּוֹטְחִים בְּעָשְׁרָם, אָמַר: כָּל הָעַמִּים, שֶׁכֻּלָּם צְרִיכִים יִסּוּר:\",1,0],[2,136,49,2,\"חָלֶד. הִיא הָאָרֶץ, עַל שֵׁם שֶׁהִיא נוֹשֶׁנֶת וַחֲלוּדָה, רדוייל״ייא בְּלַעַ״ז; וְרַבּוֹתֵינוּ פֵּרְשׁוּ (חולין קכז.): עַל שֵׁם הַחוּלְדָּה, שֶׁהִיא בַּיַּבָּשָׁה וְאֵינָהּ בַּיָּם; דְּתָנוּ רַבָּנָן (חולין קכז.): כָּל שֶׁיֵּשׁ בַּיַּבָּשָׁה יֵשׁ בַּיָּם, חוּץ מִן הַחוּלְדָּה:\",2,0],[2,136,49,3,\"גַּם בְּנֵי אָדָם. בְּנֵי אַבְרָהָם, שֶׁנִּקְרָא ״הָאָדָם הַגָּדוֹל בָּעֲנָקִים״ (יהושע יד:טו): בְּנֵי יִשְׁמָעֵאל וּבְנֵי קְטוּרָה:\",1,0],[2,136,49,3,\"גַּם בְּנֵי אִישׁ. בְּנֵי נֹחַ, שֶׁנִּקְרָא ״אִישׁ צַדִּיק״ (בראשית ו:ט):\",2,0],[2,136,49,4,\"וְהָגוּת לִבִּי. מַחְשְׁבוֹת לִבִּי, תְּבוּנוֹת הֵם:\",1,0],[2,136,49,5,\"אַטֶּה לְמָשָׁל אָזְנִי. לְדִבְרֵי תוֹרָה, שֶׁנִּקְרֵאת ״מְשַׁל הַקַּדְמוֹנִי״ (שמואל א כד:יג):\",1,0],[2,136,49,5,\"אֶפְתַּח. לָכֶם חִידָתִי זֹאת בְּכִנּוֹר, וְזוֹ הִיא הַחִידָה: לָמָּה אֲנִי צָרִיךְ לִירָא בִּימֵי רָע בְּיוֹם פְּקֻדַּת עָוֹן? לְפִי שֶׁעֲוֹן עֲקֵבַי יְסוּבֵּנִי. עֲוֹנוֹת שֶׁאֲנִי דָּשׁ בֶּעָקֵב, שֶׁאֲנִי מְזַלְזֵל בָּהֶם, שֶׁהֵם בְּעֵינַי עֲבֵרוֹת קַלּוֹת – הֵם מַרְשִׁיעוֹת אוֹתִי בַּדִּין. וְכָל שֶׁכֵּן הָעֲשִׁירִים:\",2,0],[2,136,49,7,\"הַבּוֹטְחִים עַל חֵילָם. וּמָה בֶּצַע בְּמָמוֹנָם, הֲלֹא:\",1,0],[2,136,49,8,\"אָח. לֹא יוּכַל לִפְדּוֹת אֶת אָחִיו בְּמָמוֹנוֹ, לְפִי שֶׁאִם בָּאִים לִפְדּוֹת אִישׁ אֶת אָחִיו יִתְיַקֵּר פִּדְיוֹן נַפְשָׁם מִכָּל הוֹן. לְפִיכָךְ עַל כָּרְחוֹ חָדֵל הוּא לְעוֹלָם מִלְּפַדּוֹתוֹ:\",1,0],[2,136,49,9,\"וְיֵקַר. (שֶׁיִּחְיֶה לָנֶצַח וְלֹא יִרְאֶה הַשַּׁחַת) וּמְנַחֵם חִבְּרוֹ לְשׁוֹן מְנִיעָה כְּמוֹ ״אוֹקִיר אֱנוֹשׁ מִפָּז״ (ישעיה יג:יב), ״וְהָלַכְתִּי עִמָּכֶם בַּחֲמַת קֶרִי״ (ויקרא כו:כח), כְּלוֹמַר וְיִמָּנַע פִּדְיוֹן נַפְשָׁם:\",1,0],[2,136,49,11,\"כִּי יִרְאֶה חֲכָמִים יָמוּתוּ. וְאֵין נִצּוֹלִין מִן הַמָּוֶת, לְפִיכָךְ עַל כָּרְחוֹ הוּא חָדֵל לִיגַע וְלִטְרֹחַ עַל פִּדְיוֹן אָחִיו:\",1,0],[2,136,49,11,\"חֵילָם. מָמוֹנָם. בַּחֲכָמִים נֶאֱמַר מִיתָה, שֶׁאֵינָם מֵתִים בָּעוֹלָם הַזֶּה אֶלָּא הַגּוּף בִּלְבַד, וּבִכְסִיל וּבַעַר נֶאֱמַר אֲבֵדָה:\",2,0],[2,136,49,12,\"קִרְבָּם בָּתֵּימוֹ לְעוֹלָם. מַחְשְׁבוֹתָם לִבְנוֹת לָהֶם בָּתִּים שֶׁיִּתְקַיְּמוּ לְעוֹלָם:\",1,0],[2,136,49,12,\"קָרְאוּ בִשְׁמוֹתָם. אֶת בָּתֵּיהֶם שֶׁהֵם בּוֹנִים לְמַעַן יִהְיֶה לָהֶם לְזִכָּרוֹן, ״וְיִקְרָא שֵׁם הָעִיר כְּשֵׁם בְּנוֹ חֲנוֹךְ״ (בראשית ד:יז). אַנְטִיוֹכוּס בָּנָה אַנְטוֹכִיָא, סְלִיקוּס בָּנָה סְלִיקִיָא:\",2,0],[2,136,49,13,\"בִּיקָר. לְשׁוֹן יְקָר וְתִפְאֶרֶת (ס״א אינו):\",1,0],[2,136,49,13,\"נִמְשַׁל. לְשׁוֹן מָשָׁל:\",2,0],[2,136,49,13,\"נִדְמוּ. לְשׁוֹן דְּמָמָה:\",3,0],[2,136,49,14,\"כֵּסֶל. שִׁטּוּת:\",1,0],[2,136,49,14,\"וְאַחֲרֵיהֶם בְּפִיהֶם יִרְצוּ סֶלָה. וְהַבָּאִים אַחֲרֵיהֶם יְדַבְּרוּ בָהֶם וִיסַפְּרוּ בְּפִיהֶם מַה אֵרַע לָרִאשׁוֹנִים:\",2,0],[2,136,49,14,\"יִרְצוּ. לְשׁוֹן הַרְצָאַת דְּבָרִים, רטרירונ״ש בְּלַעַ״ז, וַחֲזַ״ל פֵּרְשׁוּ (שבת לא:): זֶה דַּרְכָּם שֶׁל רְשָׁעִים שֶׁסּוֹפָם אֲבוּדִים, אֲבָל כֵּסֶל לָמוֹ – חֵלֶב יֵשׁ לָהֶם עַל כִּסְלֵיהֶם וּמְכַסּוֹת אֶת כִּלְיוֹתֵיהֶם וְאֵינָן יוֹעֲצוֹת אוֹתָם לָשׁוּב מֵרָעָתָם. וְשֶׁמָּא תֹּאמַר שִׁכְחָה הִיא לָהֶם עַל שֶׁשָּׁכְחוּ שֶׁסּוֹפָם לָמוּת? תַּלְמוּד לוֹמַר: וְאַחֲרֵיהֶם בְּפִיהֶם יִרְצוּ, כְּלוֹמַר: יוֹם אַחֲרִיתָם תָּמִיד בְּפִיהֶם, וְאֵין חֲרֵדִים מִמֶּנּוּ:\",3,0],[2,136,49,15,\"כַּצֹּאן לִשְׁאוֹל שַׁתּוּ. כַּצֹּאן הַמִּתְאַסֵּף לַדִּיר כֵּן הֵם לִשְׁאוֹל:\",1,0],[2,136,49,15,\"שַׁתּוּ. דְּגוּשׁוֹת הַתָּי״ו בִּמְקוֹם תָּי״ו שְׁנִיָּה: לִשְׁאוֹל שׁוֹתְתוּ, לְשׁוֹן שְׁתוּתֶיהָ שֶׁל שְׁאוֹל, לַמַּדְרֵגָה הַתַּחְתּוֹנָה. וְכֵן ״שַׁתּוּ בַשָּׁמַיִם פִּיהֶם״ (תהלים עג:ט), גַּם הוּא לְשׁוֹן שְׁתוּת: קָבְעוּ בַשָּׁמַיִם פִּיהֶם, לְשׁוֹנָם הָרָע:\",2,0],[2,136,49,15,\"מָוֶת יִרְעֵם. מַלְאַךְ הַמָּוֶת יֹאכְלֵם, וְאַל תִּתְמַהּ עַל לְשׁוֹן אֲכִילָה זוֹ, שֶׁכֵּן מָצִינוּ בְּמָקוֹם אַחֵר ״יֹאכַל בַּדָּיו בְּכוֹר מָוֶת״ (איוב יח:יג). לָשׁוֹן אַחֵר: לְשׁוֹן רְצִיצָה, כְּמוֹ ״הֲיָרֹעַ בַּרְזֶל״ (ירמיה טו:יב):\",3,0],[2,136,49,15,\"וַיִּרְדּוּ בָם יְשָׁרִים לַבֹּקֶר. לְיוֹם הַגְּאֻלָּה, כְּשֶׁיִּזְרַח בָּקְרָם שֶׁל יִשְׂרָאֵל יִהְיוּ רוֹדִים בָּהֶם, כְּמוֹ שֶׁנֶּאֱמַר ״וְעַסּוֹתֶם רְשָׁעִים וְגוֹ׳״ (מלאכי ג:כא):\",4,0],[2,136,49,15,\"וְצוּרָם לְבַלּוֹת שְׁאוֹל. צוּרָתָם שֶׁל רְשָׁעִים תְּבַלֶּה אֶת הַשְּׁאוֹל, גֵּיהִנֹּם כָּלֶה וְהֵם אֵינָם כָּלִים:\",5,0],[2,136,49,15,\"מִזְּבֻל לוֹ. מִהְיוֹת לָהֶם מָדוֹר; וְהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִיא חַמָּה מִנַּרְתִּיקָהּ וּמְלַהֶטֶת אוֹתָם, שֶׁנֶּאֱמַר ״וְלִהַט אֹתָם הַיּוֹם הַבָּא״ (מלאכי ג:יט). וְרַבּוֹתֵינוּ פֵּרְשׁוּ מִזְּבֻל לוֹ עַל שֶׁפָּשְׁטוּ יְדֵיהֶם בַּזְּבוּל, שֶׁהֶחֱרִיבוּ אֶת בֵּית הַמִּקְדָּשׁ (מדרש תהלים מט:ג):\",6,0],[2,136,49,16,\"אַךְ אֱלֹהִים יִפְדֶּה נַפְשִׁי. אֲבָל אֲנִי, שֶׁהִטֵּיתִי לְמָשָׁל אָזְנִי (תהלים מט:ה), אֱלֹהִים יִפְדֶּה נַפְשִׁי שֶׁלֹּא אֵלֵךְ אֶל שְׁאוֹל, כִּי יִקָּחֵנִי בְּחַיַּי לָלֶכֶת בִּדְרָכָיו:\",1,0],[2,136,49,19,\"כִּי נַפְשׁוֹ בְּחַיָּיו יְבָרֵךְ. הָרָשָׁע מְבָרֵךְ אֶת נַפְשׁוֹ בְּחַיָּיו וְאוֹמֵר: שָׁלוֹם עָלֶיךָ נַפְשִׁי (תנחומא, משפטים ב), לֹא יְאֻנְךָ לָךְ שׁוּם רָעָה. אֲבָל אֲחֵרִים אֵין אוֹמְרִים עָלָיו כֵּן:\",1,0],[2,136,49,19,\"וְיוֹדוּךָ כִּי תֵיטִיב לָךְ. וְאַתָּה, אִם תִּשְׁמַע לִדְבָרַי, הַכֹּל יוֹדוּךָ, כִּי תֵיטִיב לְנַפְשְׁךָ לְיַשֵּׁר אֶת דְּרָכֶיךָ:\",2,0],[2,136,49,20,\"תָּבוֹא עַד דּוֹר אֲבוֹתָיו. כְּשֶׁתַּשְׁלִים יָמֶיךָ וְתָמוּת, תָּבֹא וְתִרְאֶה אֶת דּוֹר הָרְשָׁעִים אֲבוֹתָיו שֶׁל רָשָׁע נִדּוֹנִים בַּגֵּיהִנֹּם (סנהדרין קד:), אֲשֶׁר עַד נֵצַח לֹא יִרְאוּ אוֹר:\",1,0],[2,136,49,21,\"אָדָם בִּיקָר וְלֹא יָבִין. דֶּרֶךְ הַחַיִּים נְתוּנָה לְפָנָיו, שֶׁאִם יֵלֵךְ בָּהּ הֲרֵי נִכְבָּד, אֵינוֹ מֵבִין אֶת הַטּוֹב:\",1,0],[2,136,50,1,\"אֵל אֱלֹהִים ה׳. אֶקְרָא (אֱלֹהֵי הָאֱלֹהִים ה׳ שְׁמוֹ):\",1,0],[2,136,50,1,\"דִּבֶּר וַיִּקְרָא אָרֶץ. וְהוּא הוֹפִיעַ מִצִּיּוֹן שֶׁהוּא מִכְלַל יֹפִי:\",2,0],[2,136,50,2,\"מִכְלַל. שֵׁם דָּבָר, פְּרַמְנְ״ט בְּלַעַ״ז:\",1,0],[2,136,50,3,\"יָבֹא אֱלֹהֵינוּ וְאַל יֶחֱרַשׁ. עוֹד עַל דַּם עֲבָדָיו הַשָּׁפוּךְ (תהלים עט:י):\",1,0],[2,136,50,4,\"יִקְרָא אֶל הַשָּׁמַיִם. לִפְקֹד עַל שַׂר הָאֻמּוֹת שֶׁבַּמָּרוֹם:\",1,0],[2,136,50,4,\"וְאֶל הָאָרֶץ. לִפְקֹד עַל מַלְכֵי מִצְרַיִם (ישעיהו כד:כא):\",2,0],[2,136,50,4,\"לָדִין עַמּוֹ. לִנְקֹם נִקְמַת עַמּוֹ, כְּמוֹ ״כִּי יָדִין עַמּוֹ״ וְ״דַם עֲבָדָיו יִקּוֹם״ (דברים לב:לו, מג):\",3,0],[2,136,50,5,\"אִסְפוּ לִי חֲסִידָי. וְעוֹד יִקְרָא לַשָּׁמַיִם וְלָאָרֶץ שֶׁיַּאַסְפוּ לוֹ הַגָּלֻיּוֹת, כְּעִנְיָן שֶׁנֶּאֱמַר ״עוּרִי צָפוֹן וּבֹאִי תֵימָן״ (שיר השירים ד:טז):\",1,0],[2,136,50,5,\"כֹּרְתֵי בְרִיתִי עֲלֵי זָבַח. שֶׁקִּבְּלוּ אֶת הַתּוֹרָה בִּבְרִית וְזֶבַח, כְּעִנְיָן שֶׁנֶּאֱמַר ״הִנֵּה דַם הַבְּרִית אֲשֶׁר כָּרַת ה׳ וְגוֹמֵר״ (שמות כד:ח):\",2,0],[2,136,50,8,\"לֹא עַל זְבָחֶיךָ אוֹכִיחֶךָ. אִם אֵינְךָ מֵבִיא לִי זְבָחֶיךָ וְלֹא עוֹלֹתֶיךָ נֶגְדִּי תָמִיד, אֵינִי שָׂם עֵינִי וְלִבִּי עַל כָּךְ:\",1,0],[2,136,50,9,\"לֹא אֶקַּח מִבֵּיתְךָ פָר. לֹא שֶׁלְּךָ הֵם, אֶלָּא שֶׁלִּי:\",1,0],[2,136,50,9,\"מִמִּכְלְאֹתֶיךָ. הוּא דִּיר הַצֹּאן, כְּמוֹ ״גָּזַר מִמִּכְלָה צֹאן״ (חבקוק ג:יז), פַּאר״ק בְּלַעַ״ז:\",2,0],[2,136,50,10,\"בְּהֵמוֹת בְּהַרְרֵי אָלֶף. הוּא (שׁוֹר) שֶׁהוּא רוֹעֶה אֶלֶף הָרִים לְיוֹם, וְכָל יוֹם וָיוֹם הֵם צוֹמְחִים. יֵשׁ מְפָרְשִׁים אֶלֶף הָרִים אוֹ אֶלֶף פַּרְסָאוֹת אוֹ שֵׁם אֶלֶף פָּרִים, וְיֵשׁ מְפָרְשִׁים שֶׁהוּא כְּמוֹ ״שְׁגַר אֲלָפֶיךָ״ (דברים ז:יג), כְּלוֹמַר הָרִים מְלֵאִים בָּקָר בַּעֲבוּר שֶׁהִזְכִּיר לֹא אֶקַּח מִבֵּיתְךָ פָר:\",1,0],[2,136,50,11,\"וְזִיז שָׂדַי עִמָּדִי. רֶמֶשׂ הַשָּׂדֶה. זִיז, עַל שֶׁהֵם זָזִים מִמָּקוֹם לְמָקוֹם. אישמובימנ״ט בְּלַעַ״ז:\",1,0],[2,136,50,11,\"עִמָּדִי. אֲנִי יוֹדֵעַ אֶת כֻּלָּם:\",2,0],[2,136,50,13,\"הַאוֹכַל בְּשַׂר אַבִּירִים. לֹא אָמַרְתִּי לְךָ לְהָבִיא זֶבַח שֶׁאֲנִי צָרִיךְ לַאֲכִילָה, אֶלָּא נַחַת רוּחַ לְפָנַי, שֶׁאָמַרְתִּי וְנַעֲשָׂה רְצוֹנִי:\",1,0],[2,136,50,14,\"זְבַח לֵאלֹהִים תּוֹדָה. הִתְוַדֵּה עַל מַעֲשֶׂיךָ וְשׁוּב אֵלַי, זֶהוּ זֶבַח שֶׁאֲנִי חָפֵץ בּוֹ; וְאַחַר כָּךְ שַׁלֵּם לְעֶלְיוֹן נְדָרֶיךָ, כִּי אָז יִתְקַבְּלוּ לְרָצוֹן:\",1,0],[2,136,50,15,\"וּתְכַבְּדֵנִי. שֶׁזֶּה הוּא כְּבוֹדִי, שֶׁאוֹשִׁיעַ אֶת הַבּוֹטְחִים בִּי:\",1,0],[2,136,50,16,\"וְתִשָּׂא בְרִיתִי. תּוֹרָתִי:\",1,0],[2,136,50,18,\"וַתִּרֶץ עִמּוֹ. נִתְרַצֵּיתָ לָלֶכֶת עִמּוֹ:\",1,0],[2,136,50,19,\"תַּצְמִיד מִרְמָה. תַּרְגִּיל אֶצְלְךָ רְמִיָּה לְדַבֵּר רָעָה, תַּצְמִיד אגוטא״ש בְּלַעַ״ז, כְּמוֹ (במדבר יט:טו) ״צָמִיד פָּתִיל״ (ס״א אינו):\",1,0],[2,136,50,20,\"תֵּשֵׁב. בְּמוֹשַׁב לֵצִים:\",1,0],[2,136,50,20,\"בְּבֶן אִמְּךָ. שֶׁאֵין לְךָ דִּין וְרִיב עִמּוֹ, שֶׁאֵינוֹ יוֹרֵשׁ עִמְּךָ:\",2,0],[2,136,50,20,\"דּוֹפִי. דָּבָר גְּנַאי לִדְחוֹתוֹ, לְשׁוֹן ״יֶהְדֳּפֶנּוּ״ (במדבר לה:כ):\",3,0],[2,136,50,21,\"דִּמִּיתָ. סָבוּר אַתָּה שֶׁאֶהְיֶה כָמוֹךָ, לְהִתְרַצּוֹת בְּמַעֲשֶׂיךָ הָרָעִים. (וְיֵשׁ מְפָרְשִׁים דִּמִּיתָ כִּי אֵינֶנִּי יוֹדֵעַ הַנִּסְתָּרוֹת):\",1,0],[2,136,50,23,\"זוֹבֵחַ תּוֹדָה. הַמֵּבִיא לִי זֶבַח שֶׁל תְּשׁוּבָה וְהוֹדָאָה עַל עֲווֹנוֹתָיו, הוּא יְכַבְּדָנְנִי:\",1,0],[2,136,50,23,\"וְשָׂם דֶּרֶךְ. הַשָּׁב אֵלַי אֲנִי מְלַמֵּד וְשָׂם דֶּרֶךְ לַחוֹטְאִים לָשׁוּב אֵלַי, אֲנִי אַרְאֶנּוּ בִּישׁוּעָתִי:\",2,0],[2,136,51,5,\"וְחַטָּאתִי נֶגְדִּי תָמִיד. מִתּוֹךְ שֶׁאֲנִי מִתְחָרֵט וְדוֹאֵג עָלָיו, דּוֹמֶה לִי כְּאִלּוּ הוּא לְפָנַי תָּמִיד כָּל שָׁעָה:\",1,0],[2,136,51,6,\"לְךָ לְבַדְּךָ חָטָאתִי. לְפִיכָךְ בְּיָדְךָ לִסְלֹחַ, וְאַף מַה שֶׁהֲרֵעוֹתִי לְאוּרִיָּה (שמואל ב יא) לֹא חָטָאתִי אֶלָּא לְךָ, שֶׁהִזְהַרְתָּ עַל הַדָּבָר:\",1,0],[2,136,51,6,\"לְמַעַן תִּצְדַּק בְּדָבְרֶךָ. כְּמוֹ בְּמִנְהָגְךָ (ס״א אינו), כֹּחַ הָיָה לִי לְהִתְגַּבֵּר עַל יִצְרִי אֶלָּא שֶׁלֹּא יֹאמְרוּ הָעֶבֶד נִצַּח אֶת רַבּוֹ, שֶׁאָמַרְתִּי לְפָנֶיךָ בְּחָנֵנִי וְנַסֵּנִי (תהלים כו:ב) וּבְחַנְתַּנִי וְלֹא נִמְצֵאתִי שָׁלֵם כְּדֵי שֶׁתִּצְדַּק אַתָּה וְלֹא אֲנִי (סנהדרין קז.). דָּבָר אַחֵר לְמַעַן תִּצְדַּק בְּדָבְרֶךָ, אִם תִּמְחֹל לִי, תִּצְדַּק בְּדִינְךָ לְנֹכַח כָּל הָרְשָׁעִים שֶׁאֵינָם שָׁבִים, שֶׁלֹּא יוּכְלוּ לוֹמַר כְּאִלּוּ עָשִׂינוּ תְּשׁוּבָה לֹא הוֹעַלְנוּ:\",2,0],[2,136,51,7,\"הֵן בְּעָווֹן חוֹלָלְתִּי. וְאֵיךְ לֹא אֶחֱטָא וְעִקַּר יְצִירָתִי עַל יְדֵי תַשְׁמִישׁ הוּא, שֶׁכַּמָּה עֲוֹנוֹת בָּאִים עַל יָדוֹ (ויקרא רבה יד:ה). דָּבָר אַחֵר: עִקַּר יְצִירָתִי מִזָּכָר וּנְקֵבָה, שֶׁכֻּלָּם מְלֵאִים עָוֹן. יֵשׁ מִדְרָשִׁים לְמִקְרָא זֶה, וְאֵינָם מִתְיַשְּׁבִים לְפִי עִנְיַן הַמְדַבֵּר בַּמִּזְמוֹר:\",1,0],[2,136,51,7,\"יֶחֱמַתְנִי. לְשׁוֹן חֲמִימוּת, כְּמוֹ (בראשית ל:לח) ״וַיֵּחַמְנָה הַצֹּאן בְּבֹאָן לִשְׁתּוֹת״ (ס״א אינו):\",2,0],[2,136,51,8,\"הֵן אֱמֶת חָפַצְתָּ בַטֻּחוֹת. וַהֲרֵינִי מוֹדֶה עַל הָאֱמֶת, כִּי חָטָאתִי:\",1,0],[2,136,51,8,\"בַּטֻּחוֹת. אֵלּוּ כְּלָיוֹת, שֶׁהֵן חֲלָקוֹת. וּמְנַחֵם חִבְּרוֹ עִם ״כִּמְטַחֲוֵי קֶשֶׁת״ (בראשית כא:טז), וְכֵן ״מִי שָׁת בַּטֻּחוֹת חָכְמָה״ (איוב לח:לו). פִּתְרוֹנוֹ לְשׁוֹן מֶשֶׁךְ: כִּי כַּאֲשֶׁר יֵשׁ לַקֶּשֶׁת מֶשֶׁךְ, כֵּן יֵשׁ מֶשֶׁךְ לַדַּעַת (ס״א אינו):\",2,0],[2,136,51,8,\"וּבְסָתוּם חָכְמָה תוֹדִיעֵנִי. וּבַלֵּב שֶׁהוּא סָתוּם, הוֹדַעְתַּנִי חָכְמָה לְהִתְוַדּוֹת:\",3,0],[2,136,51,9,\"תְּחַטְּאֵנִי בְאֵזוֹב. כְּמוֹ שֶׁמְּטַהֵר הַמְּצֹרָע וְטָמֵא מֵת (ויקרא יד:ד; במדבר יט:ו):\",1,0],[2,136,51,10,\"תַּשְׁמִיעֵנִי שָׂשׂוֹן וְשִׂמְחָה. סְלִיחַת הֶחָטְא:\",1,0],[2,136,51,10,\"עֲצָמוֹת דִּכִּיתָ. כְּשֶׁכָּעַסְתָּ עָלַי:\",2,0],[2,136,51,12,\"לֵב טָהוֹר בְּרָא לִי אֱלֹהִים. שֶׁלֹּא אֶכָּשֵׁל עוֹד:\",1,0],[2,136,51,13,\"וְרוּחַ קָדְשְׁךָ אַל תִּקַּח מִמֶּנִּי. שֶׁלֹּא יְהֵא רוּחַ הַקֹּדֶשׁ מְרֻחָק מִמֶּנִּי (ס״א אינו):\",1,0],[2,136,51,14,\"הָשִׁיבָה לִּי שְׂשׂוֹן יִשְׁעֶךָ. רוּחַ הַקֹּדֶשׁ שֶׁנִּסְתַּלְּקָה מֵעָלַי (סנהדרין קז.):\",1,0],[2,136,51,14,\"נְדִיבָה. לְשׁוֹן נְדִיבוּת, קְצִינוּת:\",2,0],[2,136,51,15,\"אֲלַמְּדָה פוֹשְׁעִים דְּרָכֶיךָ. וּמִמֶּנִּי יִלְמְדוּ וְיָשׁוּבוּ, אִם יִרְאוּ שֶׁתִּסְלַח לִי:\",1,0],[2,136,51,16,\"הַצִּילֵנִי מִדָּמִים. שֶׁלֹּא אָמוּת בַּחֶרֶב, עַל עָנְשׁוֹ שֶׁל אוּרִיָּה שֶׁהָרַגְתִּי (שמואל ב יא:טו,יז):\",1,0],[2,136,51,17,\"אֲדֹנָי שְׂפָתַי תִּפְתָּח. מְחוֹל לִי, וִיהִי לִי פִּתְחוֹן פֶּה לְהַגִּיד תְּהִלָּתֶךָ:\",1,0],[2,136,51,18,\"כִּי לֹא תַחְפֹּץ זֶבַח. שֶׁאֵין זֶבַח חַטָּאת בָּא עַל הַמֵּזִיד:\",1,0],[2,136,51,18,\"וְאֶתֵּנָה. שֶׁאִם תַּחְפֹּץ אֶתְּנֶנּוּ לְךָ:\",2,0],[2,136,51,20,\"הֵיטִיבָה. לִבְנוֹת בֵּית מִקְדָּשְׁךָ בְּתוֹכָהּ בִּימֵי שְׁלֹמֹה בְּנִי:\",1,0],[2,136,52,3,\"מַה תִּתְהַלֵּל. וְתִתְפָּאֵר בָּרָעָה שֶׁאַתָּה עוֹשֶׂה, אַתָּה הַגִּבּוֹר בַּתּוֹרָה (סנהדרין קו:):\",1,0],[2,136,52,3,\"חֶסֶד אֵל כָּל הַיּוֹם. לְהַצִּיל אֶת הַנִּרְדָּף עַל יָדְךָ. דָּבָר אַחֵר: חֶסֶד אֵל כָּל הַיּוֹם, אִלּוּ לֹא נָתַן לִי אֲחִימֶלֶךְ לֶחֶם, מְדֻמֶּה אַתָּה שֶׁאָמוּת בָּרָעָב? יֵשׁ חֶסֶד בַּהַקָּדוֹשׁ בָּרוּךְ הוּא עַל יִשְׂרָאֵל כָּל הַיּוֹם, וְאִם לֹא נָתַן לִי, יִתְּנוּ לִי אֲחֵרִים:\",2,0],[2,136,52,4,\"מְלֻטָּשׁ. מְחֻדָּד:\",1,0],[2,136,52,4,\"עוֹשֵׂה רְמִיָּה. חוֹתֵךְ הַבָּשָׂר עִם הַשֵּׂעָר:\",2,0],[2,136,52,7,\"יִתָּצְךָ. לְשׁוֹן נְתִיצָה:\",1,0],[2,136,52,7,\"יַחְתְּךָ. לְשׁוֹן שְׁבִירָה:\",2,0],[2,136,52,7,\"וְיִסָּחֲךָ. וְיַעַקְרְךָ:\",3,0],[2,136,52,7,\"וְשָׁרֶשְׁךָ. יְשָׁרֵשׁ אַחֲרֶיךָ לַעֲקוֹר כָּל הַשָּׁרָשִׁים, דִּירָארִיצִינֶ״ר בְּלַעַ״ז:\",4,0],[2,136,52,8,\"וְעָלָיו יִשְׂחָקוּ. וְזֶה הַשְּׂחוֹק שֶׁיֹּאמְרוּ עָלָיו: הִנֵּה זֶה הַגֶּבֶר אֲשֶׁר לֹא שָׂם מִבְטַחוֹ בַּהַקָּדוֹשׁ בָּרוּךְ הוּא, רְאוּ מֶה עָלְתָה בּוֹ!\",1,0],[2,136,52,9,\"יָעֹז בְּהַוָּתוֹ. מִתְגַּבֵּר הָיָה בְּרִשְׁעוֹ:\",1,0],[2,136,52,10,\"וַאֲנִי. הַנִּרְדָּף עַתָּה בְּיָדְךָ אֶהְיֶה כְּזַיִת רַעֲנָן בְּבֵית אֱלֹהִים, בְּבָנִים וּבִבְנֵי בָנִים בְּבֵית הַקָּדוֹשׁ בָּרוּךְ הוּא (ברכות נז.):\",1,0],[2,136,52,11,\"כִּי עָשִׂיתָ. כְּשֶׁתַּעֲשֶׂה לִי זֹאת, וּכְלַפֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר מִקְרָא זֶה:\",1,0],[2,136,53,1,\"עַל מָחֲלַת. שֵׁם כְּלִי שִׁיר. דָּבָר אַחֵר: עַל מַחֲלָתָן שֶׁל יִשְׂרָאֵל, כְּשֶׁיַּחֲרִיב הַבַּיִת. וּכְבָר אָמַר מִזְמוֹר אַחֵר דּוּגְמַת זֶה ״אָמַר נָבָל בְּלִבּוֹ אֵין אֱלֹהִים וְגוֹ׳״ (תהלים יד:א), הָאֶחָד עַל חֻרְבַּן בַּיִת רִאשׁוֹן, וְזֶה עַל בַּיִת שֵׁנִי:\",1,0],[2,136,53,2,\"אָמַר נָבָל בְּלִבּוֹ. זֶה עַל טִיטוּס, כְּשֶׁגִּדֵּר אֶת הַפָּרֹכֶת וְחַרְבּוֹ מְטַפְטֵף דָּם. אָמַר: הָרַג אֶת עַצְמוֹ (גיטין נו:):\",1,0],[2,136,53,4,\"כֻּלּוֹ סָג. לְשׁוֹן ״סִיגִים״ (יחזקאל כב:יח):\",1,0],[2,136,53,4,\"אֵין גַּם אֶחָד. מִכָּל חֵילָיו שֶׁיִּמְחֶה בְּיָדוֹ:\",2,0],[2,136,53,5,\"הֲלֹא. יֵשׁ לֵידַע לְאוֹכְלֵי עַמִּי כְּמַאֲכַל לֶחֶם וֵאלֹהִים לֹא קָרָאוּ, שֶׁסּוֹפָם שֶׁיִּפְחֲדוּ שָׁם פַּחַד בְּאַחֲרִית הַיָּמִים:\",1,0],[2,136,53,6,\"לֹא הָיָה פַחַד. זֶה כַּפַּחַד הָרִאשׁוֹן שֶׁאֵרַע לְבֵלְשַׁצַּר, כִּי בַּגְּאֻלָּה זוֹ פִּזַּר הַקָּדוֹשׁ בָּרוּךְ הוּא עַצְמוֹת חוֹנָךְ הַחוֹנִים עָלַיִךְ יְרוּשָׁלַיִם, כְּעִנְיָן שֶׁנֶּאֱמַר: ״הָמֵק בְּשָׂרוֹ וְגוֹ׳״ (זכריה יד:יב). וְכֵן פְּתָרוֹ מְנַחֵם, וְדוּנַשׁ פָּתַר אוֹתוֹ כְּמוֹ ״חֲנֹךְ לַנַּעַר עַל פִּי דַרְכּוֹ״ (משלי כב:ו), וְכָ״ף שֶׁל חוֹנָךְ הִיא יְסוֹד בַּמִּלָּה כְּכָ״ף שֶׁל חֲנוֹךְ (ס״א אינו):\",1,0],[2,136,53,6,\"הֱבִישׁוֹתָה. אַתָּה ה׳ אֶת כָּל אוֹיְבַי, כִּי מְאַסְתָּם:\",2,0],[2,136,54,3,\"וּבִגְבוּרָתְךָ תְדִינֵנִי. תִּנְקֹם נִקְמָתִי, כְּמוֹ ״כִּי יָדִין ה׳ עַמּוֹ״ (דברים לב:לו):\",1,0],[2,136,54,7,\"לְשׁוֹרְרָי. לְעוֹיְנַי, לְשׁוֹן ״אֲשׁוּרֶנּוּ וְלֹא קָרוֹב״ (במדבר כד:יז):\",1,0],[2,136,54,7,\"בַּאֲמִתְּךָ. מִתּוֹךְ שֶׁאַתָּה אֲמִתִּי, וְאָמַרְתָּ לִיפָּרַע מֵהוֹלְכֵי רָכִיל וְרוֹדְפֵי הֶרֶג (תהלים קא:ה), לְכָךְ הַצְמִיתֵם:\",2,0],[2,136,55,3,\"אָרִיד בְּשִׂיחִי. אֶתְאוֹנֵן בְּצַעֲרִי, כְּמוֹ ״זְכֹר עָנְיִי וּמְרוּדִי״ (איכה ג:יט), ״וְיָרַדְתִּי עַל הֶהָרִים״ (שופטים יא:לז). וּמְנַחֵם פָּתַר לְשׁוֹן מֶמְשָׁלָה, כְּמוֹ ״וּרְדוּ בִדְגַת הַיָּם״, וְשִׂיחִי לְשׁוֹן שִׂיחַ, ״לְמִי שִׂיחַ״ (משלי כג:כט) (ס״א אינו):\",1,0],[2,136,55,4,\"עָקַת. לְשׁוֹן מָצוֹק:\",1,0],[2,136,55,4,\"כִּי יָמִיטוּ עָלַי אָוֶן. דּוֹאֵג וַאֲחִיתֹפֶל מַכְרִיעִים עָלַי עֲוֹנוֹת לְהוֹרוֹת שֶׁאֲנִי בֶן מָוֶת, וּמַתִּירִים אֶת דָּמִי (שמואל א כב:ט-יט; שמואל ב טו:לא):\",2,0],[2,136,55,5,\"יָחִיל. דּוֹאֵג:\",1,0],[2,136,55,8,\"הִנֵּה אַרְחִיק נְדֹד וְגוֹ׳, אָחִישָׁה מִפְלָט לִי. אִם הָיוּ לִי כְּנָפַיִם הָיִיתִי מַרְחִיק לָנוּד וּמְמַהֵר לְהַצִּיל נַפְשִׁי מִיָּדָם, שֶׁהֵם כְּרוּחַ סוֹעָה רוּחַ סְעָרָה עוֹקֶרֶת אִילָנוֹת כְּמוֹ ״וַיִּסַּע כָּעֵץ״ (איוב יט:י). וּמְנַחֵם חִבֵּר סוֹעָה כְּמוֹ ״וַיִּסְעוּ בְּנֵי יִשְׂרָאֵל״ (שמות יב:לז):\",1,0],[2,136,55,10,\"בָּלַע. דפא״יי בְּלַעַ״ז, כְּמוֹ ״הֵשִׁיב יָדוֹ מִבַּלֵּעַ״ (איכה ב:ח). כֵּן פָּתַר מְנַחֵם (ס״א אינו):\",1,0],[2,136,55,10,\"פַּלַּג לְשׁוֹנָם. הַבְדִּילֵהוּ שֶׁלֹּא יִשְׁמַע אָדָם לָהֶם. וּמְנַחֵם פָּתַר פַּלַּג לְשׁוֹן חִלּוּק (סא״א):\",2,0],[2,136,55,10,\"כִּי רָאִיתִי חָמָס וָרִיב בָּעִיר. עַל יָדָם:\",3,0],[2,136,55,11,\"יְסוֹבְבֻהָ. הֶחָמָס וְהָרִיב:\",1,0],[2,136,55,12,\"הַוּוֹת. שְׁבָרִים:\",1,0],[2,136,55,12,\"תּוֹךְ וּמִרְמָה. לְשׁוֹן מַכָּה:\",2,0],[2,136,55,13,\"כִּי לֹא אוֹיֵב יְחָרְפֵנִי. מִיָּמַי שֶׁאֶשָּׂא חֶרְפָּתִי, אֶלָּא קַמְתִּי עָלָיו וַהֲרַגְתִּיו:\",1,0],[2,136,55,13,\"לֹא מְשַׂנְאִי עָלַי הִגְדִּיל. וַאֲנִי בָּרַחְתִּי וְנִסְתַּרְתִּי מִמֶּנּוּ, אֲבָל עַתָּה עַל כָּרְחִי אֲנִי נוֹשֵׂא אֶת חֶרְפָּתְךָ שֶׁאַתָּה תְּחָרְפֵנִי, לְפִי שֶׁאַתָּה אָדָם גָּדוֹל בַּתּוֹרָה:\",2,0],[2,136,55,14,\"אֱנוֹשׁ כְּעֶרְכִּי. אִישׁ חָשׁוּב כָּמוֹנִי:\",1,0],[2,136,55,14,\"וּמְיֻדָּעִי. כְּמוֹ אַלּוּפִי, לְשׁוֹן ״וָאֵדָעֲךָ בְשֵׁם״ (שמות לג:יז), דִּמְתַרְגְּמִינָן ״וְרַבִּיתָךְ״. וּמְנַחֵם פֵּירֵשׁ: כִּי לֹא אוֹיֵב יְחָרְפֵנִי וְאֶשָּׂא, יֵשׁ עָלָיו מִן הָעִנְיָן מִי יִתֵּן לִי אֵבֶר כַּיּוֹנָה אָעוּפָה וְאֶשְׁכֹּנָה, אִילּוּ יָכֹלְתִּי לְהַעֲלוֹת אֵבֶר הָיִיתִי טָס וְנוֹדֵד מִפְּנֵי עָקַת רָשָׁע, כִּי בְּצֵאתִי מִקֶּרֶב מְעָרַת פָּרִיצִים לָלוּן בַּמִּדְבָּר סֶלָה, אָז לֹא אוֹיֵב יְחָרְפֵנִי וְלֹא הָיִיתִי נוֹשֵׂא כְּלִמָּתִי וּבָשְׁתִּי, וְלֹא נִסְתַּרְתִּי מִפָּנָיו כַּאֲשֶׁר הָיִיתִי נִסְתָּר מִפְּנֵיהֶם כְּשֶׁהָיִיתִי בְתוֹכָם. וּפִתְרוֹן זֶה לֹא יִתָּכֵן מִפְּנֵי הַפְּסוּקִים הַכְּתוּבִים אַחֲרֵיהֶם, וְהֵם וְאַתָּה אֱנוֹשׁ כְּעֶרְכִּי אַלּוּפִי וּמְיֻדָּעִי אֲשֶׁר יַחְדָּו נַמְתִּיק סוֹד בְּבֵית אֱלֹהִים נְהַלֵּךְ בְּרָגֶשׁ. לָכֵן פּוֹתֵר אוֹתוֹ דּוּנַשׁ בְּעִנְיָן אַחֵר, וְזֶה פִּתְרוֹנוֹ: כִּי לֹא אוֹיֵב יְחָרְפֵנִי וְאֶשָּׂא חֶרְפָּתוֹ, וְלֹא מְשַׂנְאִי עָלַי הִגְדִּיל וְאֶסָּתֵר מִמֶּנּוּ, כִּי אִם אַלּוּפִי וּמְיֻדָּעִי אֲשֶׁר יַחְדָּיו נַמְתִּיק סוֹד בְּבֵית אֱלֹהִים נְהַלֵּךְ בְּרָגֶשׁ. וְהַדָּבָר הַזֶּה יָדוּעַ, כִּי הָאָדָם קָשֶׁה עָלָיו חֶרְפַּת הָאוֹהֵב מֵחֶרְפַּת הָאוֹיֵב, וְגַם יוּכַל לְהִסָּתֵר מֵאוֹיְבוֹ וְלֹא יוּכַל לְהִסָּתֵר מֵאוֹהֲבוֹ בְּהַגִּידוֹ לוֹ אֶת כָּל לִבּוֹ. כֵּן מוֹכִיחַ הָעִנְיָן:\",2,0],[2,136,55,15,\"אֲשֶׁר יַחְדָּו. הָיִינוּ רְגִילִים לְהַמְתִּיק סוֹד בַּתּוֹרָה, וּבְבֵית אֱלֹהִים הָיִינוּ מְהַלְּכִים בְּרָגֶשׁ, בְּרוֹב עָם:\",1,0],[2,136,55,15,\"בְּבֵית אֱלֹהִים. בָּתֵּי מִדְרָשׁוֹת:\",2,0],[2,136,55,16,\"יַשִּׁי מָוֶת עָלֵימוֹ. יַשִּׁיא הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם אֶת מַלְאַךְ הַמָּוֶת, יַשִּׁי יְסַכְסֵךְ וְיָסִית לְשׁוֹן ״הַנָּחָשׁ הִשִּׁיאַנִי וָאֹכַל״ (בראשית ג:יג), וּמְנַחֵם פָּתַר יַשִּׁי לְשׁוֹן יֵשׁ כְּמוֹ ״אִם יֶשְׁכֶם עוֹשִׂים״ (בראשית כד:מט) ״אֲשֶׁר יֶשְׁנוֹ פֹּה״ (דברים כט:יד):\",1,0],[2,136,55,16,\"בִּמְגוּרָם. בִּמְלוֹנָם:\",2,0],[2,136,55,18,\"עֶרֶב וָבֹקֶר וְצָהֳרַיִם. עַרְבִית וְשַׁחֲרִית וּמִנְחָה, שָׁלֹשׁ תְּפִלּוֹת (ברכות כו:):\",1,0],[2,136,55,19,\"מִקְּרָב לִי. מִן הַמִּלְחָמָה הַבָּאָה עָלַי:\",1,0],[2,136,55,19,\"כִּי בְרַבִּים הָיוּ עִמָּדִי וְגוֹ׳. כִּי זֹאת עָשָׂה לִי בִּשְׁבִיל הָרַבִּים שֶׁהָיוּ בְּעֶזְרָתִי לְהִתְפַּלֵּל עָלַי, שֶׁנֶּאֱמַר ״וְכָל יִשְׂרָאֵל וִיהוּדָה אֹהֵב אֶת דָּוִד״ (שמואל א יח:טז):\",2,0],[2,136,55,20,\"יִשְׁמַע אֵל. תְּפִלָּתָם שֶׁל אוֹתָם רַבִּים:\",1,0],[2,136,55,20,\"וְיַעֲנֵם. הַמֶּלֶךְ שֶׁהוּא יֹשֵׁב קֶדֶם:\",2,0],[2,136,55,20,\"אֲשֶׁר אֵין חֲלִיפוֹת לָמוֹ. לְאוֹתָם הָרְשָׁעִים הָרוֹדְפִים אוֹתִי אֵין נוֹתְנִים לִבָּם אֶל יוֹם חֲלִיפָתָם, אֵין חֲרֵדִים מִיּוֹם הַמִּיתָה:\",3,0],[2,136,55,21,\"שָׁלַח יָדָיו. זֶה אֲחִיתֹפֶל הָרָשָׁע (שמואל ב טו:לא):\",1,0],[2,136,55,21,\"שָׁלַח. טָאנְדִ״יט בְּלַעַ״ז:\",2,0],[2,136,55,21,\"בִּשְׁלוֹמָיו. בְּמַה שֶּׁהָיָה שָׁקֵט וְשָׁלֵם עִמּוֹ:\",3,0],[2,136,55,22,\"חָלְקוּ. לְשׁוֹן חֲלַקְלַקּוֹת:\",1,0],[2,136,55,22,\"מַחְמָאוֹת. לְשׁוֹן חֶמְאָה, וְהַמֵּ״ם הָרִאשׁוֹנָה יְסוֹד נוֹפֵל הִיא בַּתֵּיבָה, כְּמֵ״ם שֶׁל מַעֲשֶׂה וּכְמֵ״ם שֶׁל ״מַאֲמָר״ (אסתר א:טו):\",2,0],[2,136,55,22,\"וּקְרָב לִבּוֹ. לִבּוֹ לְמִלְחָמָה:\",3,0],[2,136,55,22,\"וְהֵמָּה פְתִחוֹת. מְנַחֵם פָּתַר לְשׁוֹן חֲרָבוֹת, כְּמוֹ ״וְאֶת אֶרֶץ נִמְרֹד בְּפִתְחֶיהָ״ (מיכה ה:ה): כְּפִיּוֹת חֶרֶב (ס״א אינו). וְאוֹמֵר אֲנִי: לְשׁוֹן קְלָלָה הוּא בִּלְשׁוֹן אֲרַמִּי, כְּדַאֲמַר: כָּתַב אֲמֵימַר פְּתִיחָא עֲלָהּ – וְהוּא שְׁטַר שַׁמְתָּא:\",4,0],[2,136,55,23,\"יְהָבְךָ. מַשָּׂאֲךָ, רוּחַ הַקֹּדֶשׁ מֵשִׁיב לוֹ כֵּן:\",1,0],[2,136,55,23,\"יְכַלְכְּלֶךָ. יִסְבּוֹל מַשָּׂאֲךָ, כְּמוֹ (מלכים א ח:כז) ״הַשָּׁמַיִם וּשְׁמֵי הַשָּׁמַיִם לֹא יְכַלְכְּלוּךָ״. לְשׁוֹן ״כִּלְכּוּל״ מְתֻרְגָּם ״מְסוֹבַר״ כְּתַרְגּוּם יוֹנָתָן בֶּן עֻזִּיאֵל:\",2,0],[2,136,55,23,\"מוֹט. מְעִידַת רֶגֶל:\",3,0],[2,136,56,1,\"יוֹנַת אֵלֶם רְחוֹקִים. עַל עַצְמוֹ אָמַר, שֶׁהָיָה רָחוֹק מֵאֶרֶץ יִשְׂרָאֵל אֵצֶל אָכִישׁ, וְהָיוּ אֶחָיו שֶׁל גָּלְיָת מְבַקְּשִׁים רְשׁוּת מֵאָכִישׁ לְהָרְגוֹ, שֶׁנֶּאֱמַר ״הֲלֹא זֶה דָּוִד מֶלֶךְ הָאָרֶץ״ (שמואל א כא:יב), וְהוּא הָיָה בֵּינֵיהֶם כְּיוֹנָה אִלֶּמֶת (סוטה י:):\",1,0],[2,136,56,2,\"שְׁאָפַנִי. מְצַפִּים לְבָלְעֵנִי, גולושי״ר בְּלַעַ״ז, כְּמוֹ ״שָׁאֲפָה רוּחַ״ (ירמיה ב:כד):\",1,0],[2,136,56,2,\"לֹחֵם. לְשׁוֹן מִלְחָמָה:\",2,0],[2,136,56,3,\"מָרוֹם. הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא יוֹשֵׁב מָרוֹם:\",1,0],[2,136,56,5,\"בֵּאלֹהִים אֲהַלֵּל דְּבָרוֹ. אַף בְּשָׁעָה שֶׁהוּא בָּא עִמִּי בְּמִדַּת הַדִּין, אֲהַלֵּל דְּבָרוֹ וְאֶבְטַח בּוֹ:\",1,0],[2,136,56,6,\"כָּל הַיּוֹם דְּבָרַי יְעַצֵּבוּ. מְעַצְּבִים אוֹתִי רוֹדְפַי, עַד שֶׁכָּל דִּבְרֵי פִּי עֶצֶב וּצְעָקָה:\",1,0],[2,136,56,7,\"יָגוּרוּ יִצְפּוֹנוּ. הֵמָּה אוֹרְבִים וְלָנִים בַּמָּקוֹם שֶׁהֵם מְקַוִּים שֶׁאֲנִי אֵלֵךְ שָׁם, וְשׁוֹמְרִים אֶת עֲקֵבַי, טר״צש בְּלַעַ״ז, לְרַגְּלֵנִי וּלְהוֹלִיךְ רוֹדְפַי שָׁם. כָּל זֶה הָיָה מְקֻבָּל עַל רִשְׁעֵי יִשְׂרָאֵל הָאוֹרְבִים לוֹ, וּמֵאֵימָתָם בָּרַח אֵצֶל אָכִישׁ (שמואל א כא:יא):\",1,0],[2,136,56,7,\"יָגוּרוּ. יָלִינוּ:\",2,0],[2,136,56,7,\"יִצְפּוֹנוּ. יֶאֱרֹבוּ:\",3,0],[2,136,56,7,\"כַּאֲשֶׁר קִוּוּ נַפְשִׁי. כְּשֶׁהֵם יוֹדְעִים וּמְקַוִּים לִי: דֶּרֶךְ זוֹ יֵלֵךְ:\",4,0],[2,136,56,8,\"עַל אָוֶן פַּלֶּט לָמוֹ. לִמְצוֹא הַצָּלָה וְעֹשֶׁר עַל דְּבַר עָוֹן וָרֶשַׁע, פַּלֶּט כְּמוֹ לְפַלֵּט; מְצַפִּים שָׂכָר מֵאֵת שָׁאוּל עַל כָּךְ:\",1,0],[2,136,56,8,\"בְּאַף עַמִּים הוֹרֵד. בְּאַפְּךָ הוֹרֵד אוּמָּה זוֹ שֶׁאֲנִי בְּתוֹכָם מֵחָכְמָתָם וּמִמַּחְשְׁבוֹתָם, שֶׁאוֹמְרִים לְהָרְגֵנִי:\",2,0],[2,136,56,9,\"נוֹדִי סָפַרְתָּה. אַתָּה יָדַעְתָּ מִנְיַן הַמְּקוֹמוֹת שֶׁנָּדַדְתִּי לִבְרֹחַ:\",1,0],[2,136,56,9,\"שִׂימָה דִמְעָתִי בְנֹאדֶךָ. שִׂים דִּמְעָתִי בְּנֹאד שֶׁלְּךָ, וּתְהֵא שְׁמוּרָה לְפָנֶיךָ:\",2,0],[2,136,56,9,\"הֲלֹא בְּסִפְרָתֶךָ. בְּמִנְיָנְךָ תִּתְּנֶנָּה, לִמְנוֹתָהּ עִם שְׁאָר צָרוֹתַי. (וּמְנַחֵם חֲבֵרוֹ לְשׁוֹן סֵפֶר מַמָּשׁ):\",3,0],[2,136,56,11,\"בֵּאלֹהִים אֲהַלֵּל, בַּה׳ אֲהַלֵּל. עַל מִדַּת הַדִּין וְעַל מִדַּת הָרַחֲמִים אֲהַלֵּל (ירושלמי ברכות ט,ה):\",1,0],[2,136,56,14,\"בְּאוֹר הַחַיִּים. לָשׁוּב לְאֶרֶץ יִשְׂרָאֵל:\",1,0],[2,136,57,1,\"לַמְנַצֵּחַ אַל תַּשְׁחֵת. כָּךְ כִּנָּה דָּוִד הַמִּזְמוֹר הַזֶּה בִּשְׁבִיל שֶׁהָיָה קָרוֹב לָמוּת, וְיִסֵּד מִזְמוֹר זֶה לֵאמֹר: אַל תַּשְׁחֵת אוֹתִי ה׳:\",1,0],[2,136,57,2,\"חָנֵּנִי, חָנֵּנִי. חָנֵּנִי שֶׁלֹּא אֶהֱרֹג וְשֶׁלֹּא אֵהָרֵג (שמואל א כד:יא):\",1,0],[2,136,57,2,\"עַד יַעֲבֹר הַוּוֹת. עַד תַּעֲבֹר הָרָעָה:\",2,0],[2,136,57,4,\"חֵרֵף שֹׁאֲפִי. וְיוֹשִׁיעֵנִי מֵחֶרְפַּת שֹׁאֲפִי הָאוֹמֵר לְבָלְעֵנִי. שֹׁאֲפִי גּוֹלוֹשְׁנְטְמוֹ״י בְּלַעַ״ז:\",1,0],[2,136,57,5,\"נַפְשִׁי בְּתוֹךְ לְבָאִם. אַבְנֵר וְעַמָשָׂא, שֶׁהָיוּ לְבָאִים בַּתּוֹרָה וְאֵינָם מוֹחִים בְּשָׁאוּל:\",1,0],[2,136,57,5,\"אֶשְׁכְּבָה לוֹהֲטִים. אֶשְׁכְּבָה בְּלוֹהֲטִים, אַנְפַנְבְּלוֹיְיאַנְ״ץ בְּלַעַ״ז, בֵּין הַזִּיפִים שֶׁלּוֹהֲטִים אַחַר לָשׁוֹן הָרָע (שמואל א כג:יט-כ):\",2,0],[2,136,57,6,\"רוּמָה עַל הַשָּׁמַיִם. הִסְתַּלֵּק מִן הַתַּחְתּוֹנִים, שֶׁאֵינָם כְּדַי שֶׁתִּשְׁרֶה שְׁכִינָתְךָ בֵּינֵיהֶם, וְעַל הָאָרֶץ תִּתְכַּבֵּד בָּזוֹ:\",1,0],[2,136,57,7,\"כָּפַף נַפְשִׁי. הָאוֹיֵב:\",1,0],[2,136,57,7,\"נָפְלוּ בְתוֹכָהּ. סוֹפָן לִיפּוֹל בְּתוֹכָהּ. כָּפַף קְלִינָ״א בְּלַעַ״ז, לְשׁוֹן ״וְזוֹקֵף לְכָל הַכְּפוּפִים״ (תהלים קמה:יד):\",2,0],[2,136,57,8,\"נָכוֹן לִבִּי אֱלֹהִים נָכוֹן לִבִּי. נֶאֱמָן עִמְּךָ בְּמִדַּת הַדִּין וְנֶאֱמָן עִמְּךָ בְּמִדַּת הָרַחֲמִים (ירושלמי ברכות ט,ה):\",1,0],[2,136,57,9,\"עוּרָה כְבוֹדִי. וְלֹא אִישַׁן עַד שָׁלֹשׁ שָׁעוֹת בִּכְבוֹדִי כִּשְׁאָר מְלָכִים (משנה ברכות א:ב):\",1,0],[2,136,57,9,\"עוּרָה הַנֵּבֶל וְכִנּוֹר. הָעִירָה אוֹתִי אַתָּה, הַנֵּבֶל וְכִנּוֹר הַתָּלוּי עַל מִטָּתִי, פָּתוּחַ לְצַד הַצָּפוֹן; וְכֵיוָן שֶׁמַּגִּיעַ חֲצוֹת לַיְלָה, רוּחַ צְפוֹנִית מְנַשֶּׁבֶת בּוֹ, וְדָוִד עוֹמֵד וְעוֹסֵק בַּתּוֹרָה (ברכות ג:):\",2,0],[2,136,57,9,\"אָעִירָה שָּׁחַר. אֲנִי מְעוֹרֵר אֶת הַשַּׁחַר, וְאֵין הַשַּׁחַר מְעוֹרְרֵנִי (ברכות ג:):\",3,0],[2,136,58,1,\"מִכְתָּם. שֵׁם נְעִימוּת שִׁיר:\",1,0],[2,136,58,2,\"הַאֻמְנָם. לְשׁוֹן אֱמוּנָה הוּא:\",1,0],[2,136,58,2,\"הַאֻמְנָם אֵלֶם צֶדֶק תְּדַבֵּרוּן וְגוֹ׳. מִזְמוֹר זֶה אָמַר עַל שֶׁבָּא אֶל הַמַּעְגָּל אֲשֶׁר שָׁאוּל שׁוֹכֵב שָׁם, וְלָקַח אֶת הַחֲנִית וְאֶת הַצַּפַּחַת וְהָלַךְ לוֹ, וְקָרָא: ״הֲלֹא תַעֲנֶה אַבְנֵר״ (שמואל א כו:יד), כְּלוֹמַר: הֲלֹא יֵשׁ לְךָ עַתָּה לְהוֹכִיחַ לְשָׁאוּל וּלְהַרְאוֹתוֹ, שֶׁעַל חִנָּם הוּא רוֹדְפֵנִי; שֶׁאִלּוּ רָצִיתִי הֲרַגְתִּיו. וְכָךְ אָמַר בְּשִׁירוֹ: הַאֻמְנָם נֶאֱלַם מִפִּיכֶם הַצֶּדֶק שֶׁהָיָה לָכֶם לְדַבֵּר, וְהַמֵּישָׁרִים שֶׁהָיָה לָכֶם לִשְׁפֹּט הַצֶּדֶק אֲשֶׁר תְּדַבֵּרוּן:\",2,0],[2,136,58,3,\"אַף בְּלֵב עוֹלוֹת תִּפְעָלוּן. וְלֹא עוֹד, אֶלָּא שֶׁבִּלְבַבְכֶם אַתֶּם חוֹרְשִׁים רָעָה לִפְעוֹל עָוֶל:\",1,0],[2,136,58,3,\"עוֹלוֹת. כְּמוֹ עֲוָלוֹת, כַּאֲשֶׁר יֵאָמֵר מִן שׁוֹר – שְׁוָרִים, וּמֵעִיר – עֲיָרִים: ״וּשְׁלֹשִׁים עֲיָרִים לָהֶם״ (שופטים י:ד), שֶׁהֵם לְשׁוֹן עִיר וְקִרְיָה:\",2,0],[2,136,58,3,\"בָּאָרֶץ חֲמַס יְדֵיכֶם תְּפַלֵּסוּן. בְּתוֹךְ הָאָרֶץ אַתֶּם מַכְרִיעִים חֲמַס יְדֵיכֶם, עַד שֶׁהוּא שׁוֹקֵל מִשְׁקָל רַב. תְּפַלֵּסוּן קוֹנְטֶרְפֵּיי״שׁץ בְּלַעַ״ז:\",3,0],[2,136,58,4,\"זֹרוּ רְשָׁעִים מֵרָחֶם. מִמְּעֵי אִמָּם הֵם נַעֲשִׂים זָרִים לְהַקָּדוֹשׁ בָּרוּךְ הוּא, כְּדֶרֶךְ שֶׁעָשָׂה עֵשָׂו: ״וַיִּתְרוֹצְצוּ הַבָּנִים בְּקִרְבָּהּ״ (בראשית כה:כב):\",1,0],[2,136,58,4,\"זֹרוּ. נָזוֹרוּ, כְּמוֹ ״שֹׁמּוּ שָׁמַיִם״ (ירמיהו ב:יב), ״וַיְמָרְרֻהוּ וָרֹבּוּ״ (בראשית מט:כג), ״רֹמּוּ מְעָט״ (איוב כד:כד), כֻּלָּן לְשׁוֹן נִפְעֲלוּ:\",2,0],[2,136,58,5,\"חֲמַת לָמוֹ. אֶרֶס יֵשׁ לָהֶם לַהֲרוֹג אֶת הַבְּרִיּוֹת כִּדְמוּת הַנָּחָשׁ:\",1,0],[2,136,58,5,\"כְּמוֹ פֶתֶן חֵרֵשׁ יַאְטֵם אָזְנוֹ. הַנָּחָשׁ, כְּשֶׁהוּא מַזְקִין, נַעֲשֶׂה חֵרֵשׁ בְּאָזְנוֹ אַחַת וְאוֹטֵם הַשֵּׁנִית בֶּעָפָר, שֶׁלֹּא יִשְׁמַע אֶת הַלַּחַשׁ, כְּשֶׁחַבָּר מַשְׁבִּיעוֹ שֶׁלֹּא יַזִּיק:\",2,0],[2,136,58,6,\"אֲשֶׁר לֹא יִשְׁמַע וְגוֹ׳. מְחֻבָּר לַמִּקְרָא שֶׁלְּפָנָיו, וְאוֹטֵם אָזְנוֹ בִּשְׁבִיל שֶׁלֹּא יִשְׁמַע לְקוֹל מְלַחֲשִׁים:\",1,0],[2,136,58,6,\"חוֹבֵר חֲבָרִים. שֶׁיּוֹדֵעַ לִלְחוֹשׁ אֶת הַנְּחָשִׁים (שבת קנג:):\",2,0],[2,136,58,7,\"מַלְתְּעוֹת. שִׁנַּיִם הַפְּנִימִיּוֹת, שֶׁקּוֹרִין מייש״ליש בְּלַעַ״ז:\",1,0],[2,136,58,8,\"יִמָּאֲסוּ. לְעַצְמָם שֶׁיִּהְיוּ נִמְאָסִים בְּעֵינֵיהֶם מִדְּאָגָה, וּכְמוֹ בַמַּיִם יִתְהַלָּכוּ. דּוּגְמָתוֹ (יחזקאל כא:יב) ״כָּל בִּרְכַּיִם תֵּלַכְנָה מַּיִם״ מִדְּמָעוֹת (ס״א אינו):\",1,0],[2,136,58,8,\"יִדְרֹךְ חִצָּו. הַקָּדוֹשׁ בָּרוּךְ הוּא לְנֶגְדָּם, כְּדֵי שֶׁיִּתְמוֹלְלוּ. יִתְמוֹלְלוּ שיאנ״ט פרוייאיי״ץ בְּלַעַ״ז:\",2,0],[2,136,58,9,\"שַׁבְּלוּל. יֵשׁ פּוֹתְרִין לימצ״א בְּלַעַ״ז, וְיֵשׁ פּוֹתְרִין כְּמוֹ ״שִׁבֹּלֶת מַיִם״ (תהלים סט:ג), וְכָפַל הַלָּמֶ״ד כְּמוֹ מִן ״יִמַּל קְצִירוֹ״ (איוב יח:טז), ״יְמוֹלֵל״ (תהלים צ:ו):\",1,0],[2,136,58,9,\"תֶּמֶס. נָמֵס וְהוֹלֵךְ, תֶּמֶס שֵׁם דָּבָר הוּא, הַמֵּ״ם יְסוֹד וְעִקָּר הוּא, וְהַתָּי״ו בּוֹ יְסוֹד נוֹפֵל, כְּמוֹ תָּי״ו שֶׁל ״תֶּבֶל עָשׂוּ״ (ויקרא כ:יב):\",2,0],[2,136,58,9,\"נֵפֶל אֵשֶׁת. טַלְפָּ״א בְּלַעַ״ז, שֶׁאֵין לָהּ עֵינַיִם, וְהִיא ״תִּנְשֶׁמֶת״ (ויקרא יא:ל) דִּמְתַרְגְּמִינָן ״אֲשׁוּתָא״, כָּךְ פֵּרְשׁוּהוּ רַבּוֹתֵינוּ (מועד קטן ו:). וְיֵשׁ פּוֹתְרִין: נֵפֶל שֶׁל אִשָּׁה. כְּמוֹ ״אֵשֶׁת הַזִּמָּה״ (יחזקאל כג:מד), וְיֵשׁ תָּי״ו בְּלֹא דְבֵקוּת כְּמוֹ ״עֲטֶרֶת תִּפְאֶרֶת תְּמַגְּנֶךָּ״ (משלי ד:ט), כְּמוֹ נֵפֶל שֶׁל אִשָּׁה שֶׁלֹּא חָזוּ הַנְּפָלִים שֶׁמֶשׁ. וְלַלָּשׁוֹן רִאשׁוֹן הֲוֵי נֵפֶל וְאֵשֶׁת כְּמוֹ ״וַאֲנִי כְּכֶבֶשׂ אַלּוּף״ (ירמיה יא:יט) שֶׁהוּא כְּמוֹ כֶּבֶשׂ וְאַלּוּף, וּפֵירֵשׁ מְנַחֵם כְּכֶבֶשׂ וְאַלּוּף הוּא שׁוֹר, אַף כָּאן נֵפֶל וְאֵשֶׁת (צִוָּה לְהַגִּיהַּ ס״א אינו):\",3,0],[2,136,58,10,\"בְּטֶרֶם יָבִינוּ סִירוֹתֵיכֶם אָטָד. אֲשֶׁר בְּטֶרֶם יֵדְעוּ קוֹצִים רַכִּים שֶׁלָּכֶם לִהְיוֹת אֲטָדִים קָשִׁים, כְּלוֹמַר: עַד שֶׁלֹּא יִגְדְּלוּ בְּנֵי הָרְשָׁעִים:\",1,0],[2,136,58,10,\"כְּמוֹ חַי כְּמוֹ חָרוֹן. כְּלוֹמַר: בִּגְבוּרָה וּבְחֹזֶק וּבְחָרוֹן יִסְעָרֵם הַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,136,58,10,\"חַי. לְשׁוֹן גְּבוּרָה:\",3,0],[2,136,58,12,\"וְיֹאמַר אָדָם אַךְ פְּרִי לַצַּדִּיק. וְאָז יֹאמְרוּ הַבְּרִיּוֹת: וַדַּאי יֵשׁ פֵּרוֹת וְתַשְׁלוּם שָׂכָר בְּמַעֲשֵׂה הַצַּדִּיקִים, שֶׁנָּקַם הַקָּדוֹשׁ בָּרוּךְ הוּא נִקְמָתָם:\",1,0],[2,136,58,12,\"יֵשׁ אֱלֹהִים. דַּיָּן, שׁוֹפֵט רְשָׁעִים בָּאָרֶץ:\",2,0],[2,136,59,1,\"אַל תַּשְׁחֵת. כָּךְ קָרָא שֵׁם הַמִּזְמוֹר, עַל שֵׁם שֶׁהָיָה קָרוֹב לָמוּת וְלִהְיוֹת נִשְׁחָת, מְבַקֵּשׁ רַחֲמִים עַל הַדָּבָר:\",1,0],[2,136,59,1,\"וַיִּשְׁמְרוּ אֶת הַבַּיִת. כְּשֶׁאָמְרָה לָהֶם מִיכַל: ״חוֹלֶה הוּא״ (שמואל א יט:יד), וְהִבְרִיחַתּוֹ בַּלַּיְלָה:\",2,0],[2,136,59,4,\"יָגוּרוּ עָלַי. לָנִים בְּבֵיתִי לְשָׁמְרֵנִי:\",1,0],[2,136,59,5,\"בְּלִי עָוֺן. לֹא חָטָאתִי לָהֶם:\",1,0],[2,136,59,5,\"וְיִכּוֹנָנוּ. מְזֻמָּנִים לַהֲרוֹג:\",2,0],[2,136,59,6,\"הָקִיצָה לִפְקֹד כָּל הַגּוֹיִם. וְאֶת הָרְשָׁעִים שְׁפוֹט כְּמִשְׁפְּטֵי הַגּוֹיִם, וַעֲלֵיהֶם אַל תָּחֹן:\",1,0],[2,136,59,7,\"יָשׁוּבוּ לָעֶרֶב וְגוֹ׳, הִנֵּה יַבִּיעוּן בְּפִיהֶם. פִּתְרוֹן שְׁנֵי מִקְרָאוֹת הַלָּלוּ נוֹפֵל זֶה עַל זֶה, יָשׁוּבוּ לָעֶרֶב לֹא דַיָּם מַה שֶּׁעָשׂוּ בַּיּוֹם אֶלָּא אַף לָעֶרֶב יָשׁוּבוּ עַל רָעָתָם לִשְׁמֹר שֶׁלֹּא אֶבְרַח וְאֵצֵא מִן הָעִיר, וּמַה עָשׂוּ בַּיּוֹם? הִנֵּה כָּל הַיּוֹם יַבִּיעוּ בְּפִיהֶם לְרַגֵּל עָלַי אֶל שָׁאוּל:\",1,0],[2,136,59,8,\"חֲרָבוֹת בְּשִׂפְתוֹתֵיהֶם. וְאוֹמְרִים בְּלִבָּם: מִי שׁוֹמֵעַ?\",1,0],[2,136,59,9,\"וְאַתָּה ה׳. אֲשֶׁר תִּלְעַג תִּשְׂחַק גַּם לָרְשָׁעִים הַלָּלוּ:\",1,0],[2,136,59,10,\"עֻזּוֹ אֵלֶיךָ אֶשְׁמֹרָה. עֻזּוֹ וְתָקְפּוֹ שֶׁל אוֹיְבִי הֶחָזָק עָלַי, אֵלֶיךָ אֶשְׁמֹרָה וַאֲצַפֶּה לְעָזְרֵנִי הֵימֶנּוּ:\",1,0],[2,136,59,11,\"יְקַדְּמֵנִי. יַקְדִּים לִי עֶזְרָתִי קוֹדֶם שֶׁתִּשְׁלוֹט בִּי יַד שׂוֹנְאַי:\",1,0],[2,136,59,11,\"יַרְאֵנִי בְשׁוֹרְרָי. מַה שֶּׁאֲנִי תָּאֵב לִרְאוֹת:\",2,0],[2,136,59,12,\"אַל תַּהַרְגֵם. שֶׁאֵין זוֹ נְקָמָה הַנִּכֶּרֶת:\",1,0],[2,136,59,12,\"פֶּן יִשְׁכְּחוּ עַמִּי. כִּי כָל הַמֵּתִים מִשְׁתַּכְּחִים, אֶלָּא הֲנִיעֵמוֹ מִנִּכְסֵיהֶם שֶׁיִּהְיוּ עֲנִיִּים, וְהִיא נְקָמָה שֶׁתִּזָּכֵר לְאֹרֶךְ יָמִים:\",2,0],[2,136,59,13,\"חַטַּאת. שֶׁל פִּיהֶם הוּא דְּבַר שְׂפָתֵימוֹ, וְנִלְכָּדִים בִּגְאוֹנָם הָעֲנִיִּים הַנִּרְדָּפִים עַל יְדֵיהֶם, מִפְּנֵי הָאָלָה וְהַכַּחַשׁ שֶׁהֵם מְסַפְּרִים:\",1,0],[2,136,59,14,\"כַּלֵּה. אוֹתָם בַּחֲמָתְךָ מֶלֶךְ הַשּׁוֹפֵט, וְיֵדְעוּ כִּי אַתָּה מוֹשֵׁל בְּיַעֲקֹב:\",1,0],[2,136,59,15,\"וְיָשׁוּבוּ לָעֶרֶב. מְחֻבָּר לַמִּקְרָא הָעֶלְיוֹן חֲטַאת פִּימוֹ, הֵם מְדַבְּרִים בַּיּוֹם, וְלָעֶרֶב הֵם שָׁבִים לֶאֱרֹב אוֹתָם שֶׁהִלְשִׁינוּ עֲלֵיהֶם:\",1,0],[2,136,59,16,\"הֵמָּה יְנִיעוּן לֶאֱכֹל. כַּאֲשֶׁר עָשׂוּ הַכְּלָבִים כָּל הַלַּיְלָה אִם אֵינָם שְׂבֵעִים, שֶׁיָּלִינוּ מִתּוֹךְ שָׂבְעָם וְיִישְׁנוּ:\",1,0],[2,136,59,17,\"וַאֲנִי. כְּשֶׁאֶמָּלֵט מֵהֶם לַבֹּקֶר, אָשִׁיר עֻזֶּךָ:\",1,0],[2,136,59,18,\"עֻזִּי אֵלֶיךָ. אֵלֶיךָ שֶׁאַתָּה ״עֻזִּי וּמָעוּזִּי״ (ירמיה טז:יט), אֵלֶיךָ אֲזַמֵּרָה:\",1,0],[2,136,60,1,\"עַל שׁוּשַׁן עֵדוּת מִכְתָּם לְדָוִד לְלַמֵּד. (תוספת מִכְתָּם לְשׁוֹן ״כֶּתֶם פָּז״ (שיר השירים ה:יא) דָּבָר חָמוּד, וְרַבּוֹתֵינוּ דָּרְשׁוּ עַל דָּוִד שֶׁהָיָה מַנְהִיג עַצְמוֹ כְּמָךְ וְתָם אֲפִלּוּ בְּמַלְכוּתוֹ וְאַגָּדָה אַחֶרֶת שֶׁהָיְתָה מַכָּתוֹ תַמָּה שֶׁנּוֹלַד מָהוּל עד כאן ס״א אינו) מִכְתָּם לְדָוִד עַל עֵדוּתָן שֶׁל סַנְהֶדְרִין שֶׁנִּמְשְׁלוּ לְשׁוֹשַׁנָּה, שֶׁנֶּאֱמַר ״שָׁרְרֵךְ אַגַּן הַסַּהַר וְגוֹ׳״ (שיר השירים ז:ג) ״סוּגָה בַּשּׁוֹשַׁנִּים״, כְּשֶׁנִּצְרַךְ שֶׁיְּלַמְּדוּהוּ מַה יַּעֲשֶׂה כְּשֶׁנִּלְחַם עִם אֲרַם נַהֲרַיִם וְשָׁלַח אֶת יוֹאָב עֲלֵיהֶם, אָמְרוּ לוֹ לְיוֹאָב וְלֹא מִבָּנָיו שֶׁל יַעֲקֹב אַתֶּם הֵיכָן הִיא הַשְּׁבוּעָה שֶׁנִּשְׁבַּע לְלָבָן ״עַד הַגַּל הַזֶּה״ (בראשית לא:נב), וְלֹא הָיָה יוֹדֵעַ מַה לְּהָשִׁיב, בָּא לוֹ אֵצֶל דָּוִד אָמַר לְדָוִד כָּךְ אָמְרוּ לִי בְּנֵי אֲרָם בָּאוּ וְשָׁאֲלוּ אֶת סַנְהֶדְרִין אָמְרוּ לָהֶם וְלֹא הֵם עָבְרוּ תְּחִלָּה אֶת הַשְּׁבוּעָה שֶׁאָמַר (במדבר כג:ז) ״מִן אֲרָם יַנְחֵנִי בָלָק מֶלֶךְ מוֹאָב״, וְעוֹד כּוּשַׁן רִשְׁעָתַיִם (שופטים ג:ח) אֲרַמִּי הָיָה:\",1,0],[2,136,60,2,\"בְּהַצּוֹתוֹ. כְּמוֹ ״בְּהַצּוֹתָם עַל ה׳״ (במדבר כו:ט), שֶׁנִּלְחַם בָּהֶם עַל שֶׁעָזְרוּ לִבְנֵי עַמּוֹן:\",1,0],[2,136,60,2,\"וַיָּשָׁב יוֹאָב וַיַּךְ אֶת אֱדוֹם וְגוֹ׳. שְׁמוֹנָה עָשָׂר אֶלֶף הַכְּתוּבִים בִּמְלָכִים (שמואל ב ח:יג) וּבְדִבְרֵי הַיָּמִים (דברי הימים א יח:יב) הָרַג אֲבִישַׁי פַּעַם רִאשׁוֹנָה, שֵׁשֶׁת אֲלָפִים, וְיוֹאָב שְׁנֵים עָשָׂר אֶלֶף, כְּשֶׁשָּׁב מֵהַכּוֹת אֶת אֲרָם:\",2,0],[2,136,60,3,\"זְנַחְתָּנוּ פְרַצְתָּנוּ. כְּשֶׁנָּפְלָה אֱדוֹם בְּיָדוֹ, צָפָה בְּרוּחַ הַקֹּדֶשׁ שֶׁעֲתִידִים אֲדוֹמִיִּים לִמְשֹׁל בְּיִשְׂרָאֵל וְלִגְזֹר בְּיִשְׂרָאֵל גְּזֵרוֹת רָעוֹת. עָמַד וּבִקֵּשׁ רַחֲמִים עַל שִׁעְבּוּד הַגָּלֻיּוֹת. הַרְבֵּה צָרוֹת סָבַלְנוּ בִּימֵי הַשּׁוֹפְטִים מֵאוֹיְבֵינוּ סָבִיב:\",1,0],[2,136,60,3,\"אָנַפְתָּ. קָצַפְתָּ עָלֵינוּ, מֵעַתָּה תְּשׁוֹבֵב רְצוֹנְךָ עָלֵינוּ:\",2,0],[2,136,60,4,\"הִרְעַשְׁתָּה. אַרְצֵנוּ בְּכַמָּה גְּיָסוֹת:\",1,0],[2,136,60,4,\"פְּצַמְתָּהּ. שָׁבַרְתָּ אוֹתָהּ, וְרָאִיתִי בְּדִבְרֵי דוּנָשׁ שֶׁהוּא לְשׁוֹן עֲרָבִי, אֲבָל לֹא פֵּרֵשׁ אוֹתוֹ. וּבִיסוֹדוֹ שֶׁל רַבִּי מֹשֶׁה הַדַּרְשָׁן פֵּרְשׁוֹ לְשׁוֹן קְרִיעָה, וּרְאָיָה הֵבִיא לַדָּבָר: ״וְקָרַע לוֹ חַלּוֹנָי״ (ירמיהו כב:יד) מְתֻרְגָּם: ״וּפְצִים״. אַךְ אֲנִי אוֹמֵר: ״וּפְצִים״ שֶׁתִּרְגֵּם יוֹנָתָן – לְשׁוֹן תִּקּוּן חַלּוֹן הוּא, כְּכָל הַפְּתָחִים שֶׁיֵּשׁ לָהֶם פְּצִימִין (מנחות לד.):\",2,0],[2,136,60,4,\"רְפָה שְׁבָרֶיהָ כִּי מָטָה. לְשׁוֹן רְפוּאָה, אַף עַל פִּי שֶׁכָּתוּב בְּהֵ״א. הַרְבֵּה תֵּיבוֹת מְשַׁמְּשׁוֹת כֵּן:\",3,0],[2,136,60,4,\"כִּי מָטָה. לְשׁוֹן שִׁפְלוּת:\",4,0],[2,136,60,5,\"יַיִן תַּרְעֵלָה. הָאוֹטֵם אֶת הַלֵּב וְעוֹטְפוֹ. רַעַל לְשׁוֹן עֲטִיפָה הוּא, כְּמוֹ ״וְהַבְּרוֹשִׁים הָרְעָלוּ״ (נחום ב:ד). וּבִלְשׁוֹן מִשְׁנָה: מָדִיּוֹת רְעוּלוֹת (שבת ו:ו):\",1,0],[2,136,60,6,\"נָתַתָּה לִּירֵאֶיךָ נֵּס. נִסְיוֹנוֹת שֶׁל צָרוֹת הַרְבֵּה:\",1,0],[2,136,60,6,\"לְהִתְנוֹסֵס. לִהְיוֹת מְנֻסִּים בָּהֶם, אִם יַעַמְדוּ בְּיִרְאָתֶךָ:\",2,0],[2,136,60,6,\"מִפְּנֵי קֹשֶׁט. לְקַשֵּׁט מִדּוֹתֶיךָ בָּעוֹלָם, שֶׁכְּשֶׁתִּתֵּן לָהֶם הַטּוֹבָה לֹא יְהַרְהֲרוּ הָאֻמּוֹת אַחֲרֶיךָ, אֶלָּא יְקַשְּׁטוּ דִּינֶיךָ וְיֹאמְרוּ: יָפֶה הֵיטִיב לָהֶם, כִּי הֵם עָמְדוּ לוֹ בְּכַמָּה נִסְיוֹנוֹת:\",3,0],[2,136,60,7,\"יֵחָלְצוּן. יִנָּצְלוּ מֵרָע:\",1,0],[2,136,60,7,\"הוֹשִׁיעָה יְמִינְךָ. אֲשֶׁר הֲשִׁיבוֹתָ אָחוֹר (איכה ב:ג) בְּהִתְחַזֵּק אוֹיְבֵיהֶם עֲלֵיהֶם:\",2,0],[2,136,60,7,\"וַעֲנֵנִי. כִּי אִם תַּעֲנֵנִי יֵחָלְצוּ הֵם, שֶׁאֲנִי נִלְחָם בִּשְׁבִילָם:\",3,0],[2,136,60,8,\"אֱלֹהִים דִּבֶּר בְּקָדְשׁוֹ. שֶׁיְּקַבֵּץ הַגָּלוּת וְזַרְעוֹ יִמְשְׁלוּ בָהֶם (ס״א אינו). דָּבָר אַחֵר: אֱלֹהִים דִּבֶּר בְּקָדְשׁוֹ שֶׁאֶהְיֶה מֶלֶךְ עֲלֵיהֶם:\",1,0],[2,136,60,8,\"אֶעְלֹזָה. בִּישׁוּעָתוֹ. בְּפֵרוּשׁ אַחֵר מָצָאתִי: אֱלֹהִים דִּבֶּר בְּקָדְשׁוֹ לְעָזְרֵנִי, כְּדִכְתִיב (שמואל ב ג:יח) ״כִּי בְיַד דָּוִד עַבְדִּי אוֹשִׁיעַ אֶת עַמִּי יִשְׂרָאֵל״:\",2,0],[2,136,60,8,\"אֲחַלְּקָה שְׁכֶם. אֲחַלֵּק לָהֶם שְׁכֶם בְּנִכְסֵי אוֹיְבֵיהֶם:\",3,0],[2,136,60,8,\"וְעֵמֶק סֻכּוֹת אֲמַדֵּד. סֻכּוֹת זֶה אֵינִי יוֹדֵעַ מֵאֵיזֶה אֻמָּה הִיא. לֹא יָדַעְתִּי סֻכּוֹת שֶׁבָּאוּ לוֹ יִשְׂרָאֵל כְּשֶׁנָּסְעוּ יִשְׂרָאֵל מֵרַעְמְסֵס (שמות יב:לז) הֵיכָן הוּא. וּבְפֵרוּשִׁים אֲחֵרִים מָצָאתִי אֲחַלְּקָה שְׁכֶם, אַחֲזִיר לָהֶם נַחֲלַת יַעֲקֹב אֲבִיהֶם. וְעֵמֶק סֻכּוֹת אֲמַדֵּד, כְּשֶׁאֲחַלְּקֵהוּ לְיִשְׂרָאֵל. שְׁכֶם וְסֻכּוֹת בִּקְצֵה אֶרֶץ כְּנַעַן הָיָה, כְּמוֹ שֶׁמָּצִינוּ תְּחִלַּת בִּיאָתוֹ שֶׁל יַעֲקֹב לָאָרֶץ דֶּרֶךְ סֻכּוֹת שְׁכֶם (בראשית לג:יז-יח). דָּבָר אַחֵר: וְעֵמֶק סֻכּוֹת אֲמַדֵּד, סֻכּוֹת לְשׁוֹן צוּרוֹת וְדִמְיוֹנוֹת כְּמוֹ שֶׁנֶּאֱמַר ״וְאֵת סֻכּוֹת בְּנוֹת״ (מלכים ב יז:ל):\",4,0],[2,136,60,8,\"אֲמַדֵּד. אֲנִי מוֹדֵד אֶת צוּרָתָם, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב ב:ח): ״שְׁנֵי חֲבָלִים לְהָמִית וּמְלֹא הַחֶבֶל לְהַחֲיוֹת״ (ס״א אינו):\",5,0],[2,136,60,9,\"לִי גִלְעָד. לִמְלוֹךְ עֲלֵיהֶם:\",1,0],[2,136,60,9,\"מְחֹקְקִי. שָׂרִים שֶׁלִּי. מְחוֹקֵק לְשׁוֹן שְׂרָרָה, שֶׁמְּחוֹקֵק וְשׁוֹלֵחַ סְפָרִים וּמְצַוֶּה, כְּמוֹ ״לֹא יָסוּר שֵׁבֶט מִיהוּדָה וּמְחֹקֵק מִבֵּין רַגְלָיו״ (בראשית מט:י) (ס״א אינו):\",2,0],[2,136,60,10,\"מוֹאָב סִיר רַחְצִי. אֶשְׁתַּמֵּשׁ בָּהֶם כְּסִיר שֶׁל נְחוֹשֶׁת הַמּוּכָן לִרְחוֹץ בּוֹ:\",1,0],[2,136,60,10,\"נַעֲלִי. מַסְגֵּר שֶׁלִּי:\",2,0],[2,136,60,10,\"עָלַי פְּלֶשֶׁת הִתְרֹעָעִי. הִתְחַבְּרִי עַל מֶמְשַׁלְתִּי לִהְיוֹת מְשֻׁעְבָּדִים לִי, כִּי גַת מֵאֶרֶץ פְּלִשְׁתִּים, וְכֵן עַזָּה (שמואל א ו:יז), שֶׁכְּבָשָׁן דָּוִד:\",3,0],[2,136,60,11,\"מִי יוֹבִלֵנִי עִיר מָצוֹר. אוֹ לְעִיר מִבְצָר לִכְבּוֹשׁ אֶת בָּצְרָה אִם לֹא אַתָּה תַּעֲזֹר אוֹתִי עַל מִבְצְרֵי אֱדוֹם מִי יֹבִילֵנִי וּמִי יַנְחֵנִי עֲלֵיהֶם, בְּפֵרוּשִׁים אֲחֵרִים מָצָאתִי כֵּן עַל מִבְצְרֵי אֱדוֹם אֲשֶׁר נָחִיתִי עַתָּה עֲלֵיהֶם:\",1,0],[2,136,60,12,\"וְלֹא תֵצֵא. וְאֵינְךָ יוֹצֵא:\",1,0],[2,136,60,14,\"יָבוּס. יִרְמוֹס:\",1,0],[2,136,61,3,\"מִקְּצֵה הָאָרֶץ. אַף עַל פִּי שֶׁאֲנִי רָחוֹק מֵאֲנָשַׁי שֶׁאֲנִי מְשַׁלֵּחַ עַל אוֹיְבַי לַמִּלְחָמָה:\",1,0],[2,136,61,3,\"אֵלֶיךָ אֶקְרָא בַּעֲטֹף לִבִּי. עֲלֵיהֶם. וְעַל מָה אֲנִי קוֹרֵא לְךָ? שֶׁתַּנְחֵנִי בְּצוּר – שֶׁהוּא רָם וְחָזָק מִמֶּנִּי:\",2,0],[2,136,61,5,\"אָגוּרָה בְאָהָלְךָ עוֹלָמִים. זַכֵּנִי בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא (בכורות לא:):\",1,0],[2,136,61,6,\"נָתַתָּ יְרֻשַּׁת יִרְאֵי שְׁמֶךָ. הֶחֱזַרְתָּ עָרֵי יְרֻשָּׁתָם עַל יָדִי:\",1,0],[2,136,61,7,\"יָמִים עַל יְמֵי מֶלֶךְ תּוֹסִיף. אִם נִגְזַר עָלַי לָמוּת בָּחוּר, הוֹסִיף יָמִים עַל יָמַי, עַד שֶׁשְּׁנוֹתַי יִהְיוּ שִׁבְעִים שָׁנָה כְּמוֹ שְׁנֵי דֹר וָדֹר:\",1,0],[2,136,61,8,\"יֵשֵׁב. הַמֶּלֶךְ לְעוֹלָם לִפְנֵי אֱלֹהִים:\",1,0],[2,136,61,8,\"חֶסֶד וֶאֱמֶת. שֶׁהוּא עוֹסֵק בָּהֶם, יִהְיוּ מְזֻמָּנִים לְנָצְרוֹ:\",2,0],[2,136,61,8,\"מָן. הַזְמָנָה, כְּמוֹ ״וַיְמַן ה׳ קִיקָיוֹן״ (יונה ד:ו):\",3,0],[2,136,61,9,\"כֵּן אֲזַמְּרָה. כְּמוֹ שֶׁתֵּיטִיב לִי, כֵּן אֲזַמְּרָה שִׁמְךָ, לִהְיוֹתִי מְשַׁלֵּם נְדָרַי יוֹם יוֹם:\",1,0],[2,136,62,1,\"עַל יְדוּתוּן. שֵׁם כְּלִי שִׁיר, וּמִדְרַשׁ אַגָּדָה : עַל הַדָּתוֹת וְעַל הַדִּינִין הַנִּגְזָרִים עַל יִשְׂרָאֵל מֵאוֹיְבֵיהֶם:\",1,0],[2,136,62,2,\"דּוּמִיָּה נַפְשִׁי. מְצַפָּה נַפְשִׁי, כְּמוֹ ״דּוֹם לַה׳ וְהִתְחוֹלֵל לוֹ״ (תהלים לז:ז):\",1,0],[2,136,62,3,\"לֹא אֶמּוֹט רַבָּה. מְטוֹת גְּדוֹלוֹת, וּמִדְרַשׁ אַגָּדָה: רַבָּה גֵּיהִנֹּם:\",1,0],[2,136,62,4,\"תְּהוֹתְתוּ. מְנַחֵם פֵּירֵשׁ מִגִּזְרַת ״הֵתָיוּ לְאָכְלָה״ (ירמיהו יב:ט), ״וַיֵּתֵא רָאשֵׁי עָם״ (דברים לג:כא): עַד אָנָה תֵּאָסְפוּ עַל אִישׁ. וְלִי נִרְאֶה שֶׁיֵּשׁ לְפוֹתְרוֹ לְשׁוֹן ״הַוּוֹת״ (תהלים ה:י), וִיהֵא הֵ״א וְתָי״ו שֹׁרֶשׁ: כַּאֲשֶׁר יֹאמַר מִן ׳מֵת׳ – ׳מוֹת׳, כָּךְ נֹאמַר מִן יְסוֹד ׳הֵת׳ – ׳הוֹת׳, וּלְשׁוֹן רַבִּים ׳הַוּוֹת׳; וְהוּא לְשׁוֹן מַחֲשֶׁבֶת שֶׁבֶר וְתַרְמִית. וְיֵשׁ מְפָרְשִׁין: תְּהוֹתְתוּ כְּמוֹ תַּאֲרִיכוּ לְשׁוֹנְכֶם עַל בְּנֵי אָדָם בְּרַע. וְדִמּוּהָּ לִלְשׁוֹן הָעֲרָב כְּשֶׁמַּרְבֶּה בִּדְבָרִים (ס״א אינו):\",1,0],[2,136,62,4,\"כְּקִיר נָטוּי. הַמּוּכָן לִיפּוֹל עַל בְּנֵי אָדָם:\",2,0],[2,136,62,5,\"מִשְּׂאֵתוֹ. לְפִי שֶׁאַתֶּם יְגוּרִים מִן בְּנֵי אָדָם שֶׁמָּא יִמְלֹךְ וִישַׁלֵּם גְּמוּלְכֶם, יְעַצְתֶּם לְהַדִּיחַ עָלָיו הָרָעָה:\",1,0],[2,136,62,5,\"בְּפִיו. שֶׁל כָּל אֶחָד וְאֶחָד מֵהֶם יְבָרֵכוּ:\",2,0],[2,136,62,5,\"וּבְקִרְבָּם. וּבְמַחְשְׁבוֹתָם יְקַלְלוּ סֶלָה:\",3,0],[2,136,62,10,\"אַךְ הֶבֶל בְּנֵי אָדָם. וְאַל תִּירְאוּ מֵהֶם מֵאַחַר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲסֶה לָנוּ בְּעֵת צָרָה סֶלָה:\",1,0],[2,136,62,10,\"בְּמֹאזְנַיִם לַעֲלוֹת. אִם בָּאוּ לַעֲלוֹת בְּמֹאזְנַיִם וְהַבְלֵיהֶם שָׁוִים, כֵּן פְּשׁוּטוֹ. וּמִדְרָשׁוֹ לְעִנְיַן הַזּוּגוֹת (ויקרא רבה כט:ח):\",2,0],[2,136,62,11,\"חַיִל כִּי יָנוּב. אִם תִּרְאוּ רְשָׁעִים שֶׁמָּמוֹנָם מַצְלִיחַ וְגָדֵל, אַל תָּשִׁיתוּ לֵב:\",1,0],[2,136,62,11,\"חַיִל. מָמוֹן:\",2,0],[2,136,62,11,\"יָנוּב. יִצְמַח, לְשׁוֹן ״תְּנוּבָה״ (ישעיה כז:ו):\",3,0],[2,136,62,12,\"אַחַת דִּבֶּר אֱלֹהִים. שֶׁשָּׁמַעְתִּי מִתּוֹכָהּ שְׁתַּיִם, וּמָה הֵן שְׁתַּיִם? כִּי עֹז לְךָ לְשַׁלֵּם לְאִישׁ כְּמַעֲשֵׂהוּ, וְהַשֵּׁנִי כִּי לְךָ ה׳ הַחֶסֶד. וּמֵאֵיזֶה דִּבּוּר שְׁמַעְנוּם? מִדִּבּוּר שֵׁנִי שֶׁל עֲשֶׂרֶת הַדִּבְּרוֹת שָׁמַעְנוּ מִמֶּנּוּ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא פּוֹקֵד עָוֹן וְנוֹצֵר חֶסֶד, שֶׁנֶּאֱמַר בּוֹ (שמות כ:ה) ״פֹּקֵד עֲוֹן אָבוֹת וְגוֹ׳״. לְכָךְ בָּטוּחַ אֲנִי שֶׁיְּשַׁלֵּם שָׂכָר טוֹב לַצַּדִּיקִים וּפֻרְעָנוּת לָרְשָׁעִים. זוֹ לָמַדְתִּי מִיסוֹדוֹ שֶׁל ר׳ מֹשֶׁה הַדַּרְשָׁן. וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ (מכילתא יתרו בחדש ז) בְּזָכוֹר וְשָׁמוֹר בְּדִבּוּר אֶחָד נֶאֶמְרוּ:\",1,0],[2,136,62,13,\"וּלְךָ אֲדֹנָי חָסֶד. וּמַהוּ הַחֶסֶד? כִּי אַתָּה תְשַׁלֵּם לְאִישׁ כְּמַעֲשֵׂהוּ, וְלֹא מַעֲשֵׂהוּ מַמָּשׁ אֶלָּא מִקְצָתוֹ, כְּעִנְיָן שֶׁנֶּאֱמַר: ״כִּי אַתָּה אֱלֹהֵינוּ חָשַׂכְתָּ לְמַטָּה מֵעֲוֹנֵנוּ״ (עזרא ט:יג). כָּךְ נִדְרַשׁ בְּאַגָּדַת תְּהִלִּים (מדרש תהלים סב:ד). וְיֵשׁ לִפְתֹּר עוֹד: וּלְךָ ה׳ הַחֶסֶד, כִּי יֵשׁ בְּיָדְךָ לְשַׁלֵּם לְאִישׁ כְּמַעֲשֵׂהוּ:\",1,0],[2,136,63,1,\"בְּמִדְבַּר יְהוּדָה. בּוֹרֵחַ מִפְּנֵי שָׁאוּל (שמואל א כב-כד):\",1,0],[2,136,63,2,\"אֲשַׁחֲרֶךָּ. אֲבַקֵּשׁ וְאֶדְרוֹשׁ לְךָ, כְּמוֹ ״וְשִׁחַרְתַּנִי וְאֵינֶנִּי״ (איוב ז:כא), ״אִם אַתָּה תְּשַׁחֵר אֶל אֵל״ (איוב ח:ה):\",1,0],[2,136,63,2,\"צָמְאָה לְךָ נַפְשִׁי. צָמֵא וְתָאֵב אֲנִי לָבוֹא אֵלֶיךָ בְּבֵית תְּפִלָּתְךָ:\",2,0],[2,136,63,2,\"כָּמַהּ לְךָ בְשָׂרִי. לְשׁוֹן תַּאֲוָה, וְאֵין לוֹ דִּמְיוֹן:\",3,0],[2,136,63,2,\"בְּאֶרֶץ צִיָּה. בַּמִּדְבָּר:\",4,0],[2,136,63,3,\"כֵּן בַּקֹּדֶשׁ חֲזִיתִיךָ וְגוֹ׳. כְּמוֹ כַּאֲשֶׁר: צָמֵאתִי לִרְאוֹת עֻזְּךָ וּכְבוֹדְךָ כְּדֶרֶךְ שֶׁחֲזִיתִיךָ בַּמִּקְדָּשׁ, מִשְׁכַּן שִׁילֹה; תִּשְׂבַּע נַפְשִׁי בְּמַרְאוֹת עֻזְּךָ וּכְבוֹדֶךָ:\",1,0],[2,136,63,5,\"כֵּן אֲבָרֶכְךָ בְחַיָּי. כְּמוֹ אָז, כִּי ״אָז״ (דברים כט:יט) מְתַרְגְּמִינָן: ״וּבְכֵן״. כְּלוֹמַר: אָז, כְּשֶׁאָבוֹא לְפָנֶיךָ, אֲבָרֶכְךָ כָּל יְמֵי חַיַּי:\",1,0],[2,136,63,5,\"בְּשִׁמְךָ אֶשָּׂא כַפָּי. לְהִתְפַּלֵּל וּלְהַלֵּל:\",2,0],[2,136,63,6,\"וְשִׂפְתֵי רְנָנוֹת. לְשׁוֹנוֹת שֶׁל רְנָנוֹת, כְּמוֹ ״וַיְהִי כָל הָאָרֶץ שָׂפָה אֶחָת״ (בראשית יא:א) דִּמְתַרְגְּמִינַן: ״לִישָׁנָא חַד״:\",1,0],[2,136,63,7,\"עַל יְצוּעָי. כְּשֶׁאֲנִי שׁוֹכֵב עַל מִשְׁכָּבִי, אֲנִי זוֹכֵר אַהֲבָתְךָ:\",1,0],[2,136,63,7,\"בָּאַשְׁמֻרוֹת. הַלַּיְלָה:\",2,0],[2,136,63,7,\"אֶהְגֶּה בָּךְ. אֶחְשֹׁב בְּךָ:\",3,0],[2,136,63,9,\"בִּי תָּמְכָה יְמִינֶךָ. שֶׁלֹּא אֶפּוֹל:\",1,0],[2,136,63,10,\"וְהֵמָּה. אוֹיְבַי:\",1,0],[2,136,63,10,\"לְשׁוֹאָה יְבַקְשׁוּ נַפְשִׁי. בָּאִים עָלַי בְּמַאֲרָב בְּיוֹם אֲפֵלָה, שֶׁלֹּא אַרְגִּישׁ בָּהֶם:\",2,0],[2,136,63,10,\"יָבֹאוּ בְּתַחְתִּיּוֹת הָאָרֶץ. בְּמָקוֹם שָׁפָל, שְׁאוֹל וְשׁוּחָה, יָבֹאוּ וְיִפְּלוּ:\",3,0],[2,136,63,11,\"יַגִּירֻהוּ עַל יְדֵי חָרֶב. יָבוֹאוּ עַל רוֹדְפֵי אוֹיְבִים, וִיגִירוּהוּ כָּל אֶחָד מֵהֶם עַל יְדֵי חֶרֶב שֶׁיָּמִיתוּ אוֹתוֹ. וּמִקְרָא קָצָר הוּא זֶה שֶׁלֹּא פֵּירֵשׁ מִי יְגִירוּהוּ. יַגִּירֻהוּ לְשׁוֹן גְּרִירָה, כְּמוֹ ״מוֹגָרִים בַּמּוֹרָד״ (מיכה א:ד), ״פָּרַץ נַחַל מֵעִם גָּר״ (איוב כח:ד):\",1,0],[2,136,63,11,\"(מָצָאתִי מְנָת שׁוּעָלִים. יִשּׁוּבָם חָרֵב, שׁוּעָלִים יֵלְכוּ בוֹ (איכה ה:יח)):\",2,0],[2,136,63,12,\"וְהַמֶּלֶךְ יִשְׂמַח. עַל עַצְמוֹ הָיָה אוֹמֵר, שֶׁהֲרֵי כְּבָר הָיָה נִמְשַׁח:\",1,0],[2,136,63,12,\"יִתְהַלֵּל כָּל הַנִּשְׁבָּע בּוֹ. כְּשֶׁיִּרְאוּ שֶׁתּוֹשִׁיעֵנִי, יִתְהַלְּלוּ וְיִתְפָּאֲרוּ כָּל הַדְּבֵקִים בְּךָ וְנִשְׁבָּעִים בִּשְׁמֶךָ:\",2,0],[2,136,63,12,\"כִּי יִסָּכֵר. יִסָּתֵם, כְּמוֹ ״וַיִּסָּכְרוּ כָּל מַעְיְנוֹת תְּהוֹם רַבָּה״ (בראשית ח:ב):\",3,0],[2,136,64,2,\"שְׁמַע אֱלֹהִים קוֹלִי בְשִׂיחִי. מִזְמוֹר זֶה דָּרְשׁוּהוּ בַּעֲלֵי אַגָּדַת תְּהִלִּים עַל דָּנִיֵּאל שֶׁהוּשְׁלַךְ לְגוֹב אֲרָיוֹת, וְיָפֶה נוֹפֵל כָּל לְשׁוֹן הַמִּזְמוֹר עַל הָאַגָּדָה. צָפָה דָוִד בְּרוּחַ הַקֹּדֶשׁ כָּל הַמְּאוֹרָע לוֹ, וְהִתְפַּלֵּל עָלָיו; שֶׁדָּנִיֵּאל מִזַּרְעוֹ הָיָה, כְּמוֹ שֶׁנֶּאֱמַר לְחִזְקִיָּה: ״וּמִבָּנֶיךָ אֲשֶׁר תּוֹלִיד יִקָּחוּ וְהָיוּ סָרִיסִים בְּהֵיכַל מֶלֶךְ בָּבֶל״ (ישעיהו לט:ז) – אֵלּוּ דָּנִיֵּאל חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה:\",1,0],[2,136,64,2,\"מִפַּחַד אוֹיֵב. אֵלּוּ הָאֲחַשְׁדַּרְפְּנִים שֶׁנִּתְיַעֲצוּ עָלָיו, שֶׁנֶּאֱמַר (דניאל ו:ה) ״אֱדַיִן סָרְכַיָּא וַאֲחַשְׁדַּרְפְּנַיָּא הֲווֹ בָעַיִן עִלָּה לְהַשְׁכָּחָה לְדָנִיֵּאל״:\",2,0],[2,136,64,3,\"מֵרִגְשַׁת פֹּעֲלֵי אָוֶן. שֶׁהֵם מִתְרַגְּשִׁים לְבַקֵּשׁ לִי עֲלִילוֹת מָוֶת, כְּדִכְתִיב ״אַרְגִּישׁוּ עַל מַלְכָּא וְגוֹ׳״ (דניאל ו:ז):\",1,0],[2,136,64,4,\"דָּרְכוּ חִצָּם. הוּא לְשׁוֹנָם הָרָע:\",1,0],[2,136,64,5,\"לִירוֹת בַּמִּסְתָּרִים תָּם. יוֹרוּהוּ בְּחִצֵּיהֶם:\",1,0],[2,136,64,6,\"יְסַפְּרוּ לִטְמוֹן מוֹקְשִׁים. יְדַבְּרוּ אֶל הַמֶּלֶךְ בְּעָרְמָה דְּבָרִים טְמוּנִים, שֶׁאֲפִלּוּ הַמֶּלֶךְ לֹא הֵבִין לָמָּה הָיוּ עוֹשִׂין כָּךְ. וְהֵם הָיוּ מִתְכַּוְּנִים לִטְמוֹן לְדָנִיֵּאל מוֹקְשִׁים לְהִלָּכֵד בָּהֶם, שֶׁאָמְרוּ לְדָרְיָוֶשׁ: ״אִתְיְעַטוּ כָּל סָרְכֵי מַלְכוּתָא וְגוֹ׳ לְקַיָּמָא קְיָם מַלְכָּא וְגוֹ׳״ (דניאל ו:ח), שֶׁלֹּא יִתְפַּלֵּל שׁוּם אָדָם תְּפִלָּתוֹ לִפְנֵי שׁוּם אֱלוֹהַּ חוּץ מִמְּךָ עַד שְׁלֹשִׁים יוֹם:\",1,0],[2,136,64,7,\"יְחַפְּשׂוּ עוֹלוֹת. מְבַקְּשִׁים עֲלִילוֹת, כְּמוֹ שֶׁנֶּאֱמַר ״הֲווֹ בָּעַיִן עִלָּה הַשְׁכָּחָה לְדָנִיֵּאל״ (דניאל ו:ה):\",1,0],[2,136,64,7,\"תַּמְנוּ. בְּלִבָּם וְלֹא גִלּוּ דַּעְתָּם אֶת חֵפֶשׂ הָעֲלִילָה הַמְחֻפָּשׂ עַל יָדָם, וְקֶרֶב מַחְשְׁבוֹתָם עֹמֶק לִבָּם:\",2,0],[2,136,64,7,\"וְקֶרֶב אִישׁ. אִישׁ מֵהֶם: כָּל אֶחָד וְאֶחָד טָמַן מַחֲשַׁבְתּוֹ:\",3,0],[2,136,64,8,\"וַיּוֹרֵם אֱלֹהִים. יָרָה אוֹתָם לְגוֹב הָאֲרָיוֹת, כְּדִכְתִיב (דניאל ו:כה): ״וַאֲמַר מַלְכָּא וְהַיְתִיו לְגֻבְרַיָּא אִלֵּךְ דִּי אֲכַלוּ קַרְצוֹהִי דִּי דָנִיֵּאל וּלְגֹב אַרְיָוָתָא רְמוֹ וְגוֹ׳״:\",1,0],[2,136,64,9,\"וַיַּכְשִׁילוּהוּ עָלֵימוֹ לְשׁוֹנָם. הַכִּשָּׁלוֹן שֶׁדִּמּוּ לְהַכְשִׁילוֹ, עָלֵימוֹ נֶהְפַּךְ לְשׁוֹנָם:\",1,0],[2,136,64,9,\"יִתְנֹדְדוּ. בְּרֹאשָׁם, לְהָנִיעַ רֹאשׁ וְלִשְׂחוֹק עֲלֵיהֶם כָּל רֹאֵה בָם:\",2,0],[2,136,64,11,\"יִשְׂמַח צַדִּיק. דָּנִיֵּאל:\",1,0],[2,136,64,11,\"וְיִתְהַלְלוּ כָּל יִשְׁרֵי לֵב. יִתְפָּאֲרוּ עַל יֹשֶׁר לִבָּם וְיִשְׁתַּבְּחוּ בְּעַצְמָם, כִּי בְּטוּחִים הֵם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בְּעֶזְרָתָם:\",2,0],[2,136,65,2,\"לְךָ דֻמִיָּה תְהִלָּה. הַשְּׁתִיקָה תְּהִלָּה לְךָ, לְפִי שֶׁאֵין קֵץ לְשִׁבְחֲךָ; וְהַמַּרְבֶּה בְּשֶׁבַח אֵינוֹ אֶלָּא גּוֹרֵעַ:\",1,0],[2,136,65,2,\"אֱלֹהִים בְּצִיּוֹן. אֱלֹהִים הַשּׁוֹכֵן בְּצִיּוֹן, (מצאתי ״שִׂימוּ כָבוֹד תְּהִלָּתוֹ״ (תהלים סו:ב), לֹא יוֹתֵר מִדַּאי, אַךְ דֻּמִיָּה תְהִלָּה, וְכִמְדוּמֶּה הַלְלוּהוּ בְּאֵימָה בִּלְשׁוֹן הַלְלוּיָהּ שֵׁם בֶּן שְׁתֵּי אוֹתִיּוֹת, מְתֻרְגָּם ״דְּחִילָא״ ״עָזִּי וְזִמְרָת יָהּ״ (שמות טו:ב) ״וְיָד עַל כֵּס יָהּ״ (שמות יז:טז) וְלָשׁוֹן ״וְגִילוּ בִּרְעָדָה״ (תהלים ב:יא) דּוֹמֶה לָזֶה) דָּבָר אַחֵר לְךָ דֻמִיָּה תְהִלָּה אֱלֹהִים בְּצִיּוֹן אֶת אֲשֶׁר דּוֹמַמְתָּ וְהֶחֱרַשְׁתָּ עַל מַה שֶּׁעָשָׂה אוֹיְבֶיךָ בְּצִיּוֹן תְּהִלָּה הָיָה לְךָ שֶׁהַיְּכֹלֶת בְּיָדְךָ לְהִנָּקֵם וְאַתָּה מַאֲרִיךְ אַף:\",2,0],[2,136,65,4,\"דִּבְרֵי עֲוֺנֹת גָּבְרוּ מֶנִּי. וְאֵין אָנוּ יְכוֹלִים לְהַסְפִּיק לְסַדֵּר כֻּלָּם לְפָנֶיךָ, לְפִי שֶׁהֵם רַב, אֶלָּא בִּכְלָל אֶחָד אָנוּ מִתְפַּלְּלִים לְפָנֶיךָ, שֶׁפְּשָׁעֵינוּ אַתָּה תְכַפְּרֵם:\",1,0],[2,136,65,5,\"אַשְׁרֵי. מִי אֲשֶׁר תִּבְחַר וּתְקָרֵב, אֲשֶׁר יִשְׁכֹּן בַּחֲצֵרֶיךָ:\",1,0],[2,136,65,5,\"נִשְׂבְּעָה בְּטוּב. שֶׁבְּבֵיתֶךָ וּמִקְּדֻשַּׁת הֵיכָלֶךָ, שֶׁשְּׁכִינָתְךָ שׁוֹרָה שָׁם:\",2,0],[2,136,65,6,\"נוֹרָאוֹת בְּצֶדֶק תַּעֲנֵנוּ. בְּצִדְקָתְךָ תַּעֲנֵנוּ, לַעֲשׂוֹת נוֹרָאוֹת בַּגּוֹיִם:\",1,0],[2,136,65,6,\"מִבְטָח. אַתָּה וּמָנוֹס לְכָל יוֹשְׁבֵי קַצְווֹת אֶרֶץ, מִקְּצֵה הָאָרֶץ וְעַד קָצֵהוּ:\",2,0],[2,136,65,6,\"וְיָם רְחוֹקִים. אֲפִלּוּ לָרְחוֹקִים שֶׁבַּיָּם אַתָּה מִבְטָח, שֶׁבְּכָל מָקוֹם מֶמְשַׁלְתְּךָ:\",3,0],[2,136,65,7,\"מֵכִין הָרִים בְּכֹחוֹ. שֶׁמַּצְמִיחַ הֶהָרִים, שֶׁהֵם קָשִׁים, בְּכֹחוֹ, וּמְזַמֵּן וּמֵכִין בָּהֶן מְזוֹנוֹת וּמֵכִין מָטָר, כְּדִכְתִיב (תהלים קמז:ח) ״הַמֵּכִין לָאָרֶץ מָטָר הַמַּצְמִיחַ הָרִים״:\",1,0],[2,136,65,7,\"נֶאְזָר בִּגְבוּרָה. לְפִי שֶׁבָּא לְהַזְכִּיר גְּבוּרַת גְּשָׁמִים, אָמַר: נֶאֱזָר בִּגְבוּרָה:\",2,0],[2,136,65,8,\"מַשְׁבִּיחַ. מַשְׁפִּיל, וְכֵן ״וְחָכָם בְּאָחוֹר יְשַׁבְּחֶנָּה״ (משלי כט:יא), ״בְּשׂוֹא גַלָּיו אַתָּה תְשַׁבְּחֵם״ (תהלים פט:י):\",1,0],[2,136,65,9,\"מוֹצָאֵי בֹקֶר וָעֶרֶב תַּרְנִין. לְךָ אֶת הַבְּרִיּוֹת יוֹשְׁבֵי הַקְּצָווֹת, בַּבֹּקֶר אוֹמְרִים בָּרוּךְ יוֹצֵר הַמְּאוֹרוֹת, וּבָעֶרֶב בָּרוּךְ הַמַּעֲרִיב עֲרָבִים:\",1,0],[2,136,65,10,\"פָּקַדְתָּ הָאָרֶץ. כְּשֶׁאַתָּה חָפֵץ לְהֵיטִיב, אַתָּה פּוֹקֵד אֶת הָאָרֶץ וּמַשְׁקֶה אוֹתָם:\",1,0],[2,136,65,10,\"רַבַּת תַּעְשְׁרֶנָּה. הַרְבֵּה אַתָּה מְעַשְּׁרָהּ מִפֶּלֶג שֶׁלְּךָ, שֶׁהוּא מָלֵא מָיִם (תענית ח:), וְתָכִין בּוֹ דְּגָנָם שֶׁל יוֹשְׁבֵי קְצָווֹת, כִּי בְּכֵן אַתָּה מֵכִין אוֹתָהּ:\",2,0],[2,136,65,11,\"תְּלָמֶיהָ. הֵן שׁוּרוֹת הַמַּחֲרֵשָׁה:\",1,0],[2,136,65,11,\"רַוֵּה. כְּמוֹ לְרַוָּה:\",2,0],[2,136,65,11,\"נַחֵת גְּדוּדֶיהָ. כְּמוֹ לְנַחֵת גְּדוּדֶיהָ, לְהָנִיחַ לִגְדוּדֶיהָ לַעֲשׂוֹת נַחַת לַבְּרִיּוֹת. אַתָּה תְּמֹגְגֶנָּה בִּרְבִיבִים שֶׁל מָטָר:\",3,0],[2,136,65,11,\"תְּמֹגְגֶנָּה. לְשׁוֹן הֲמָסָה:\",4,0],[2,136,65,12,\"עִטַּרְתָּ שְׁנַת טוֹבָתֶךָ. עַל יְדֵי הַגְּשָׁמִים אַתָּה מְעַטֵּר בְּכָל טוֹב אֶת הַשָּׁנָה שֶׁאַתָּה חָפֵץ לְהֵיטִיב:\",1,0],[2,136,65,12,\"וּמַעְגָּלֶיךָ. הֵם הַשָּׁמַיִם, שֶׁהֵם אֲבַק רַגְלֶיךָ:\",2,0],[2,136,65,12,\"יִרְעֲפוּן. יִטְּפוּן:\",3,0],[2,136,65,12,\"דָּשֶׁן. שׁוּמָן:\",4,0],[2,136,65,13,\"יִרְעֲפוּ. הַשָּׁמַיִם בִּנְאוֹת הַמִּדְבָּר:\",1,0],[2,136,65,14,\"לָבְשׁוּ כָרִים הַצֹּאן. יִתְלַבְּשׁוּן הַשָּׁרוֹן וְהָעֲרָבָה מִן הַצֹּאן, הַבָּאִים לִרְעוֹת הַדֶּשֶׁא אֲשֶׁר הִצְמִיחַ הַמָּטָר:\",1,0],[2,136,65,14,\"וַעֲמָקִים יַעַטְפוּ בָר. עַל יְדֵי הַמָּטָר יִהְיוּ מְעֻטָּפִים הָעֲמָקִים בִּתְבוּאָה, וְאָז יִתְרוֹעֲעוּ הַבְּרִיּוֹת תְּרוּעַת שִׂמְחָה וְיָשִׁירוּ מֵרֹב הַבְּרָכָה:\",2,0],[2,136,66,2,\"זַמְּרוּ כְבוֹד שְׁמוֹ. זַמְּרוּ בִּכְבוֹד שְׁמוֹ. אִי נַמִּי: סַפְּרוּ כְּבוֹד שְׁמוֹ בְּזֶמֶר וְשִׁיר:\",1,0],[2,136,66,3,\"מַה נּוֹרָא. כָּל אֶחָד מִמַּעֲשֶׂיךָ:\",1,0],[2,136,66,3,\"בְּרֹב עֻזְּךָ. כְּשֶׁאַתָּה מַרְאֶה לָעוֹלָם עֻזְּךָ עַל יְדֵי דֶּבֶר אוֹ חֶרֶב אוֹ רָעָב אוֹ בְּרָקִים:\",2,0],[2,136,66,3,\"אוֹיְבֶיךָ. הָרְשָׁעִים, מֵרוֹב פַּחַד מוֹדִים עַל כַּחַשׁ וַעֲבֵירוֹת שֶׁבְּיָדָם:\",3,0],[2,136,66,5,\"נוֹרָא עֲלִילָה. יָראוּי עַל בְּנֵי אָדָם פֶּן יִמְצָא לָהֶם פֶּשַׁע, כִּי כָל מַעֲשֵׂיהֶם גְּלוּיִים לְךָ:\",1,0],[2,136,66,6,\"הָפַךְ יָם לְיַבָּשָׁה. יַם סוּף:\",1,0],[2,136,66,6,\"שָׁם נִשְׂמְחָה בּוֹ. מָצָאתִי: שָׁם הָיָה דָּבָר שֶׁהַיָּם נִשְׂמַח בּוֹ, כְּלוֹמַר שֶׁרָאָה הַיָּם אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,136,66,7,\"אַל יָרוּמוּ. אַל תְּהִי יָדָם רָמָה:\",1,0],[2,136,66,8,\"בָּרְכוּ עַמִּים אֱלֹהֵינוּ. עַל נִפְלְאוֹתָיו, שֶׁהוּא שָׂם נַפְשֵׁנוּ בַּחַיִּים בַּגָּלוּת, וְאֵינְכֶם יְכוֹלִים לְהַשְׁמִיד אוֹתָנוּ:\",1,0],[2,136,66,10,\"כִּי בְחַנְתָּנוּ. בְּצָרָה בַּגּוֹלָה:\",1,0],[2,136,66,10,\"צְרַפְתָּנוּ. לְהָסִיר הַסִּיגִים מִמֶּנּוּ שֶׁנָּשׁוּב בִּתְשׁוּבָה לְפָנֶיךָ, כְּמוֹ שֶׁצּוֹרְפִים הַכֶּסֶף לְהָסִיר הַסִּיגִים מִמֶּנּוּ:\",2,0],[2,136,66,11,\"הֲבֵאתָנוּ בַמְּצוּדָה. בְּמָקוֹם צַר כְּמוֹ בְּמַאֲסָר:\",1,0],[2,136,66,11,\"מוּעָקָה. לְשׁוֹן מַסְגֵּר וְכָל הַמֵּעִיק וּהַמֵּצִיק כָּמוֹהוּ:\",2,0],[2,136,66,12,\"הִרְכַּבְתָּ אֱנוֹשׁ לְרֹאשֵׁנוּ. מַלְכֵי כָּל אוּמָּה וְאוּמָּה (פסיקתא רבתי ה:ב):\",1,0],[2,136,66,13,\"אָבוֹא בֵיתְךָ. בִּבְנוֹתְךָ בֵּית הַמִּקְדָּשׁ נְשַׁלֵּם נְדָרֵינוּ שֶׁנָּדַרְנוּ בַּגּוֹלָה:\",1,0],[2,136,66,15,\"מֵחִים. שְׁמֵנִים, לְשׁוֹן מֹחַ:\",1,0],[2,136,66,16,\"כָּל יִרְאֵי אֱלֹהִים. הֵם הַגֵּרִים שֶׁיִּתְגַּיְּרוּ:\",1,0],[2,136,66,17,\"אֵלָיו פִּי קָרָאתִי. כְּשֶׁהָיִינוּ בַּגּוֹלָה קְרָאנוּהוּ וְסִפַּרְנוּ רוֹמְמוֹתָיו בִּלְשׁוֹנֵנוּ:\",1,0],[2,136,66,17,\"וְרוֹמַם. כְּמוֹ וְנִתְרוֹמֵם. מָצָאתִי בְּפִי קָרָאתִי אֵלָיו וְרוֹמַם שֵׁם מִלָּה: רוֹמְמוּת שֶׁלּוֹ מוּכָן תַּחַת לְשׁוֹנִי, לְהוֹצִיאוֹ בַּפֶּה, כְּמוֹ ״יַכְחִידֶנָּה תַּחַת לְשׁוֹנוֹ״ (איוב כ:יב):\",2,0],[2,136,66,18,\"אָוֶן אִם־רָאִיתִי וְגוֹ׳. לֹא פָּעַל עִמָּנוּ כַּחֲטָאתֵינוּ, עָשָׂה עִמָּנוּ כְּלֹא רוֹאֶה וְלֹא שׁוֹמֵעַ אָוֶן שֶׁבִּלְבָבֵנוּ:\",1,0],[2,136,66,19,\"אָכֵן. בֶּאֱמֶת יֵשׁ לָדַעַת:\",1,0],[2,136,66,20,\"אֲשֶׁר לֹא הֵסִיר תְּפִלָּתִי. מִלְּפָנָיו, וְחַסְדּוֹ לֹא הֵסִיר מֵאִתִּי:\",1,0],[2,136,67,2,\"יָאֵר פָּנָיו. לְהַרְאוֹת פָּנִים שׂוֹחֲקוֹת, לָתֵת טַל וּמָטָר:\",1,0],[2,136,67,3,\"לָדַעַת בָּאָרֶץ דַּרְכֶּךָ. לְהוֹדִיעַ שֶׁמִּדָּתְךָ לְהֵיטִיב לְעַמְּךָ, וְעַל זֶה יוֹדוּךָ וְיִשְׂמְחוּ וִירַנְּנוּ לְאֻמִּים:\",1,0],[2,136,67,5,\"כִּי תִשְׁפֹּט עַמִּים מִישׁוֹר. לִזְכוּת:\",1,0],[2,136,67,5,\"תַּנְחֵם. תְּנַהֲגֵם בְּדֶרֶךְ הַמִּישׁוֹר, וְעַל זֹאת יוֹדוּךָ עַמִּים כֻּלָּם:\",2,0],[2,136,67,7,\"אֶרֶץ נָתְנָה יְבוּלָהּ. וְגַם אֶל הָאָרֶץ שֶׁנָּתְנָה יְבוּלָהּ וְעַל אֲשֶׁר יְבָרְכֵנוּ הַשֵּׁם (ס״א אינו):\",1,0],[2,136,67,8,\"וְיִירְאוּ אוֹתוֹ כָּל אַפְסֵי אָרֶץ. שֶׁיֹּאמְרוּ: רְאוּ אֵלּוּ שֶׁהָיוּ יִרְאֵי הַשֵּׁם, אֵיךְ בֵּרְכָם וְגִדְּלָם!\",1,0],[2,136,68,2,\"יָקוּם אֱלֹהִים יָפוּצוּ אוֹיְבָיו. עֲמָלֵק וְכַיּוֹצֵא בּוֹ (בראשית רבה סה,יח):\",1,0],[2,136,68,3,\"כְּהִנְדֹּף. כְּהִתְנַדֵּף; כַּאֲשֶׁר יִתְנַדֵּף הֶעָשָׁן, כֵּן תִּנְדְּפֵם:\",1,0],[2,136,68,3,\"מִפְּנֵי אֱלֹהִים. מִפְּנֵי הָאָרוֹן בִּימֵי מֹשֶׁה, ״וּבְנֻחֹה יֹאמַר שׁוּבָה ה׳ וְגוֹ׳״ (במדבר י:לו):\",2,0],[2,136,68,4,\"וְיָשִׂישׂוּ בְשִׂמְחָה. וְזֶהוּ הַמָּשׂוֹשׂ, וְכֵן יֹאמְרוּ: שִׁירוּ לֵאלֹהִים וְגוֹ׳:\",1,0],[2,136,68,5,\"סֹלּוּ. לְשׁוֹן שֶׁבַח, וְכֵן ״לֹא תְסֻלֶּה בְּכֶתֶם״ (איוב כח:טז), ״הַמְסֻלָּאִים בַּפָּז״ (איכה ד:ב):\",1,0],[2,136,68,5,\"בְּיָהּ שְׁמוֹ. בְּשֵׁם יָ״הּ, שֶׁהוּא לְשׁוֹן יִרְאָה, כְּדִמְתַרְגְּמִינָן: ״דְּחִילָא״ ״עָזִּי וְזִמְרָת יָהּ״ (תהלים קיח:יד), וְכֵן ״כִּי יָד עַל כֵּס יָהּ״ (שמות יז:טז) בְּתַרְגּוּם, וְכֵן ״כִּי בְיָהּ ה׳״ (ישעיה כו:ד) ״אֲרֵי בְּכֵן תִּתְפָּרְקוּן בְּמֵימְרָא דְּחִילָא ה׳ וְתַקִּיף עָלְמָא״. אוֹמֵר הַמְשׁוֹרֵר: שַׁבְּחוּ לְפָנָיו וְגוּרוּ מִפָּנָיו וְעִלְזוּ, וְזֶהוּ דֻּגְמַת הָאָמוּר בְּמָקוֹם אַחֵר ״וְגִילוּ בִּרְעָדָה״ (תהלים ב:יא):\",2,0],[2,136,68,6,\"אֲבִי יְתוֹמִים. זֶהוּ הַשֶּׁבַח שֶׁתְּשַׁבְּחוּ לְפָנָיו, כָּל הָעִנְיָן עַד סוֹף כָּל הַמִּזְמוֹר:\",1,0],[2,136,68,6,\"אֲבִי יְתוֹמִים. שֶׁנַּעֲשָׂה אָב לְיִשְׂרָאֵל שֶׁהֵם יְתוֹמִים, כְּמוֹ שֶׁנֶּאֱמַר ״יְתוֹמִים הָיִינוּ וְאֵין אָב״ (איכה ה:ג):\",2,0],[2,136,68,6,\"וְדַיַּן אַלְמָנוֹת. שֶׁעָשָׂה מִשְׁפָּטָהּ שֶׁל יְרוּשָׁלַיִם, שֶׁנֶּאֱמַר בָּהּ ״הָיְתָה כְּאַלְמָנָה״ (איכה א:א):\",3,0],[2,136,68,7,\"מוֹשִׁיב יְחִידִים בַּיְתָה. יִשְׂרָאֵל, שֶׁהָיוּ מְפֻזָּרִין, כִּנְּסָם יַחַד אִישׁ אִישׁ מִנִּדְחוֹ וְהוֹשִׁיבָם בַּיִת שָׁלֵם וּכְנֵסִיָּה שְׁלֵימָה (איכה רבה פתיחתא כט):\",1,0],[2,136,68,7,\"מוֹצִיא אֲסִירִים בַּכּוֹשָׁרוֹת. הוֹצִיא אֶת יִשְׂרָאֵל מִמִּצְרַיִם בְּחֹדֶשׁ שֶׁהוּא כָּשֵׁר לְהוֹלְכֵי דְרָכִים, לֹא חַמָּה וְלֹא צִנָּה (ספרי דברים קכד):\",2,0],[2,136,68,7,\"אַךְ סוֹרְרִים. מִצְרַיִם:\",3,0],[2,136,68,7,\"שָׁכְנוּ צְחִיחָה. וְנִשְׁאֲרָה אַרְצָם צִיָּה וּצְמֵאָה (מצאתי):\",4,0],[2,136,68,8,\"בְּצַעְדְּךָ. כְּשֶׁצָּעַדְתָּ בְּצַעַדְךָ, בְּצַעַד שֶׁלְּךָ:\",1,0],[2,136,68,8,\"סֶלָה. שָׁם הֶרְאֵיתַנִי זֶה דַּרְכְּךָ לְעוֹלָם: לְכָל צָרָה – גְּאֻלָּה:\",2,0],[2,136,68,9,\"זֶה סִינַי. גַּם הוּא רָעַשׁ מִפְּנֵי ה׳ אֱלֹהֵי יִשְׂרָאֵל:\",1,0],[2,136,68,10,\"גֶּשֶׁם נְדָבוֹת תָּנִיף. עוֹד זֹאת עָשִׂיתָ לָנוּ: אִם הֻצְרַכְנוּ לִגְשָׁמִים, הֲנִיפוֹתָ וְהִטַּלְתָּ עָלֵינוּ תָּמִיד גִּשְׁמֵי נְדָבָה וּבְרָכָה:\",1,0],[2,136,68,10,\"נַחֲלָתְךָ וְנִלְאָה אַתָּה כוֹנַנְתָּהּ. כְּשֶׁהָיְתָה נַחֲלַת אַרְצְךָ נִלְאָה וּצְמֵאָה לְמָטָר, אַתָּה כוֹנַנְתָּ אוֹתָהּ. (מצאתי) נַחֲלָתְךָ וְנִלְאָה הַקְּרוּיָה נַחֲלָתְךָ וְהִיא נִלְאָה, כְּלוֹמַר: פְּעָמִים שֶׁהִיא כָּךְ:\",2,0],[2,136,68,11,\"חַיָּתְךָ יָשְׁבוּ בָהּ. עֲדָתְךָ יָשְׁבוּ בָהּ, כְּמוֹ ״וַיֵּאָסְפוּ פְלִשְׁתִּים אֶת מַחֲנֵיהֶם לַחַיָּה״ (שמואל ב כג:יא). דָּבָר אַחֵר: חַיָּתְךָ, כְּנֶסֶת יִשְׂרָאֵל קְרוּיָה בְּהֶמְתּוֹ וְחַיָּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,136,68,11,\"תָּכִין בְּטוֹבָתְךָ. כְּשֶׁיָּצְאוּ מִמִּצְרַיִם הֲסִבּוֹתָם בַּמִּדְבָּר אַרְבָּעִים שָׁנָה, לְפִי שֶׁעָמְדוּ כְּנַעֲנִיִּים וְגָדְעוּ אֶת הָאִילָנוֹת; וּבְתוֹךְ כָּךְ שֶׁעִכְּבוּ בַמִּדְבָּר, עָמְדוּ וְתִקְּנוּ הַכֹּל (מכילתא בשלח ויהי פתיחתא):\",2,0],[2,136,68,12,\"אֲדֹנָי יִתֶּן אֹמֶר הַמְבַשְּׂרוֹת וְגוֹ׳. אֹמֶר מַאֲמָר; עוֹד הוּא יִשְׁאַג בְּקוֹל לְהַשְׁמִיעַ צִבְאוֹת הַגּוֹיִם הָרַבִּים, וּמַהוּ הָאֹמֶר?\",1,0],[2,136,68,13,\"מַלְכֵי צְבָאוֹת הַגּוֹיִם יִדֹּדוּן יִדֹּדוּן. יִתְנַדּוּ וְיֻשְׁלְכוּ מִתּוֹךְ אֶרֶץ יִשְׂרָאֵל, וּכְנֶסֶת יִשְׂרָאֵל שֶׁהִיא נְוַת בַּיִת תְּחַלֵּק אֶת שְׁלָלָם, כְּמוֹ שֶׁנֶּאֱמַר ״וְהָיָה סַחְרָהּ וְאֶתְנַנָּהּ קֹדֶשׁ וְגוֹמֵר״ (ישעיהו כג:יח):\",1,0],[2,136,68,14,\"אִם תִּשְׁכְּבוּן בֵּין שְׁפַתָּיִם וְגוֹ׳. כָּל זֶה הָאֹמֶר יֹאמַר לָהֶם: אִם אַתֶּם שְׁכַבְתֶּם בֵּין תְּחוּמֵיכֶם וְהִתְעַנַּגְתֶּם בְּתַעֲנוּגִים, זֹאת יוֹנָתִי, כְּנֵסִיָּתִי, כְּנָפֶיהָ נֶחְפָּה בַכֶּסֶף. וּמַהוּ הַכֶּסֶף וְהֶחָרוּץ? בְּפָרֵשׂ שַׁדַּי וְגוֹ׳ כְּשֶׁפֵּרַשׂ הַקָּדוֹשׁ בָּרוּךְ הוּא לִפְנֵיהֶם תּוֹרָתוֹ, אֲשֶׁר הַמְּלָכִים נִשְׁלָגִים וּמִתְלַבְּנִים בָּהּ בְּאֶרֶץ צַלְמָוֶת וְחֹשֶׁךְ, אָז נֶחְפּוּ כְנָפֶיהָ (כַּנְפֵי יוֹנָָָָה) בְּכַסְפָּהּ וְחֶמְדָּתָהּ שֶׁל תּוֹרָה וּמִצְווֹת. כַּנְפֵי יוֹנָה. פְּלוּמָ״א בְּלַעַ״ז:\",1,0],[2,136,68,14,\"וְאֶבְרוֹתֶיהָ. כְּנָפֶיהָ שֶׁעוֹפֶפֶת בָּהֶן:\",2,0],[2,136,68,14,\"בִּירַקְרַק חָרוּץ. פָּתַר דּוּנָשׁ בֶּן לַבְרַט: הֶחָרוּץ הוּא זָהָב, וְלָכָךְ נְתָנוֹ הַמְשׁוֹרֵר אֵצֶל הַכֶּסֶף, וִירַקְרַק הֶחָרוּץ הוּא הַזָּהָב אֲשֶׁר יוּבָא מֵאֶרֶץ הַחֲוִילָה וּמֵאֶרֶץ כּוּשׁ, זָהָב טוֹב מְאֹד מְאֹד (בראשית ב:יא-יג; איוב כח:יט). לֹא הוּא יָרוֹק וְלֹא הוּא אָדוֹם, וְלָכָךְ קְרָאוֹ יְרַקְרַק; כְּמוֹ ״לָבָן אֲדַמְדָּם״ (ויקרא יג:מב) – שֶׁאֵינוֹ לֹא לָבָן וְלֹא אָדוֹם. לְכָךְ נִכְפַּל: יְרַקְרַק, אֲדַמְדָּם:\",3,0],[2,136,68,15,\"בְּפָרֵשׂ. לְשׁוֹן ״וּפָרְשׂוּ אֶת הַשִּׂמְלָה״ (דברים כב:יז), בּוֹרְרִין אֶת הַדָּבָר כְּשִׂמְלָה חֲדָשָׁה (כתובות מו.):\",1,0],[2,136,68,15,\"מְלָכִים. אֵלּוּ תַּלְמִידֵי חֲכָמִים, כְּמוֹ שֶׁנֶּאֱמַר: (משלי ח:טו) ״בִּי מְלָכִים יִמְלֹכוּ״:\",2,0],[2,136,68,16,\"הַר אֱלֹהִים הַר בָּשָׁן. וְהֵיכָן פֵּרְשָׁהּ? בְּהַר סִינַי, שֶׁהוּא הַר אֱלֹהִים סָמוּךְ לַבָּשָׁן בְּעֵבֶר הַיַּרְדֵּן:\",1,0],[2,136,68,16,\"הַר גַּבְנֻנִּים. הַר הַמְיֻחָד שֶׁבֶּהָרִים:\",2,0],[2,136,68,16,\"גַּבְנֻנִּים. לְשׁוֹן הָרִים, עַל שֵׁם גָּבְהָם, כְּמוֹ ״וַתִּבְנִי לָךְ גָּב״ (יחזקאל טז:כד). כָּל דָּבָר גָּבוֹהַּ קָרוּי גַּב:\",3,0],[2,136,68,17,\"לָמָּה תְּרַצְּדוּן הָרִים גַּבְנֻנִּים. כָּל זֶה מוּסָב עַל ה׳ יִתֵּן אֹמֶר. עוֹד יֹאמַר לָהֶם לָמָּה תְּרַצְּדוּן הָרִים גַּבְנֻנִּים, לָמָּה תְּאָרְבוּן אַתֶּם הַהָרִים גַּבְנֻנִּים הַגְּבוֹהִים לְהַשְׁחִית אֶת הָהָר אֲשֶׁר חָמַד אֱלֹהִים לְשִׁבְתּוֹ לִשְׁרוֹת עָלָיו שְׁכִינָה, הוּא הַר הַבַּיִת? אַף הוּא לָנֶצַח יִשְׁכֹּן שָׁם, קְדֻשָּׁתוֹ קְדֻשַּׁת עוֹלָם. מִשֶּׁנִּבְחַר לְשִׁבְתּוֹ, לֹא שָׁרְתָה שְׁכִינָה בְּמָקוֹם אַחֵר. רָאִיתִי בִּיסוֹדוֹ שֶׁל רַבִּי מֹשֶׁה הַדַּרְשָׁן: רָצַד הוּא מַאֲרָב בִּלְשׁוֹן עֲרָבִי, אֲבָל מְנַחֵם פֵּרֵשׁ תְּרַצְּדוּן כְּמוֹ תְּרַקְּדוּן, אַף אוֹתוֹ לָשׁוֹן נוֹפֵל עַל הַשִּׁיטָה הַזֹּאת:\",1,0],[2,136,68,18,\"רֶכֶב אֱלֹהִים וְגוֹ׳. עוֹד זֶה מוּסָב עַל ה׳ יִתֵּן אֹמֶר לְהַזְכִּיר חִבַּת עַמּוֹ: אַף כְּשֶׁנִּגְלָה רֶכֶב אֱלֹהִים רִבֹּתַיִם שֶׁל אַלְפַּיִם שִׁנְאָנִים. שְׁנוּנִים, מַלְאָכִים חַדִּים, וַה׳ הָיָה בֵּינֵיהֶם בְּסִינַי בַּקֹּדֶשׁ, אַף שָׁם:\",1,0],[2,136,68,19,\"עָלִיתָ. אַתָּה נָגִיד עַמּוֹ מֹשֶׁה בֶּן עַמְרָם לַמָּרוֹם, שָׁבִיתָ שֶׁבִי אֶת הַתּוֹרָה, וְלָקַחְתָּ מַתָּנוֹת מִן הָעֶלְיוֹנִים וּלְתִתָּם לִבְנֵי אָדָם:\",1,0],[2,136,68,19,\"וְאַף סוֹרְרִים לִשְׁכֹּן יָהּ אֱלֹהִים. אַף עוֹד גָּרַמְתָּ שֶׁשָּׁכַן הַקָּדוֹשׁ בָּרוּךְ הוּא בַּמִּשְׁכָּן בְּתוֹךְ עַם שֶׁהָיוּ סוֹרְרִים וּמַמְרִים וּמַקְצִיפִים אוֹתוֹ:\",2,0],[2,136,68,20,\"בָּרוּךְ אֲדֹנָי וְגוֹ׳. זֶה מִן הַשִּׁיר הָאָמוּר לְמַעְלָה, שִׁירוּ לֵאלֹהִים:\",1,0],[2,136,68,20,\"יַעֲמָס לָנוּ. יִתֵּן לָנוּ יְשׁוּעָה רַבָּה מִכָּל עֹמֶס כְּכָל אֲשֶׁר נוּכַל שְׂאֵת, (מצאתי יוֹם יוֹם יַעֲמָס לָנוּ כָּל הַיָּמִים כֵּן נוֹהֵג בָּנוּ לְכָל צָרָה יְשׁוּעָה):\",2,0],[2,136,68,21,\"הָאֵל לָנוּ אֵל לְמוֹשָׁעוֹת. אֵל מוֹשִׁיעַ הוּא לָנוּ, וּלְפָנָיו יֵשׁ הַרְבֵּה תּוֹצָאוֹת מִינֵי מָוֶת. תּוֹצָאוֹת דְּרָכִים אֶל הַמָּוֶת, אַךְ לֹא עָלֵינוּ הוּא נוֹתְנָם, אֲבָל יִמְחַץ בָּהֶם רֹאשׁ אוֹיְבָיו:\",1,0],[2,136,68,22,\"קָדְקֹד שֵׂעָר. קָדְקֳדוֹ שֶׁל עֵשָׂו שֶׁהוּא אִישׁ שָׂעִיר (בראשית כז:יא), הַמִּתְהַלֵּךְ תָּמִיד בַּאֲשָׁמָיו (וְאֵינוֹ חוֹזֵר מֵרָעָתוֹ):\",1,0],[2,136,68,23,\"אָמַר ה׳ מִבָּשָׁן אָשִׁיב. כִּי כֵן הִבְטִיחַ, לְהָשִׁיב אוֹתָנוּ מִתּוֹךְ אַבִּירֵי בָשָׁן וּמֵאִיֵּי הַיָּם (ישעיה יא:יא):\",1,0],[2,136,68,24,\"לְמַעַן תִּמְחַץ. רַגְלֵינוּ בְּדָם. כְּשֶׁיִּמְחַץ אֶת רֹאשׁ הָאוֹיֵב, תְּהֵא רַגְלֵינוּ בּוֹקַעַת בְּדָמָם. תִּמְחַץ לְשׁוֹן בּוֹקֵעַ בְּתוֹךְ הַדָּם, כְּמוֹ ״מָחֲצָה וְחָלְפָה רַקָּתוֹ״ (שופטים ה:כו) כְּמוֹ בָּקְעָה. וּלְשׁוֹן מִשְׁנָה הוּא: וְהָיוּ עוֹלֵי רְגָלִים בּוֹקְעִים עַד אַרְכֻּבּוֹתֵיהֶם בְּדָם. דָּבָר אַחֵר: תִּמְחַץ שֵׁם כְּלִי שֶׁשּׁוֹאֲבִין בּוֹ יַיִן מִן הַבּוֹר מַחַץ שְׁמוֹ בְּמַסֶּכֶת עֲבוֹדַת גִּלּוּלִים (עבודה זרה עד:):\",1,0],[2,136,68,24,\"מֵאוֹיְבִים. מִדַּם הָאוֹיְבִים:\",2,0],[2,136,68,24,\"מִנֵּהוּ. תִּהְיֶה פַּרְנָסָתוֹ, כְּדְאָמְרִינַן: מַאי מַשְׁמַע דְּ״מָן״ לִישְׁנָא דִּמְזוֹנֵי הוּא? דִּכְתִיב (דניאל א:י) ״אֲשֶׁר מִנָּה אֶת מַאֲכַלְכֶם וְגוֹמֵר״ (סוכה לט:):\",3,0],[2,136,68,25,\"רָאוּ הֲלִיכוֹתֶיךָ אֱלֹהִים. כְּלוֹמַר: לְאֵלּוּ נָאֶה לְךָ לְהוֹשִׁיעַ, שֶׁכְּשֶׁרָאוּ הֲלִיכוֹתֶיךָ בִּקְדֻשָּׁתְךָ בַּיָּם, קִדְּמוּ שָׁרִים לְשׁוֹרֵר לְפָנֶיךָ שִׁירַת הַיָּם (שמות טו:א), וְאַחֲרֵיהֶם בָּאוּ הַנּוֹגְנִים, אֵלּוּ הַמַּלְאָכִים:\",1,0],[2,136,68,26,\"בְּתוֹךְ עֲלָמוֹת תּוֹפֵפוֹת. בְּתוֹךְ מִרְיָם וְנַעֲרוֹתֶיהָ אֲשֶׁר לָקְחָה הַתֹּף בְּיָדָהּ (שמות טו:כ) וְאָמְרוּ בְּשִׁבְחָם:\",1,0],[2,136,68,27,\"בְּמַקְהֵלוֹת בָּרְכוּ אֱלֹהִים אֲדֹנָי מִמְּקוֹר יִשְׂרָאֵל. אַף עוּבָּרִים מִמְּעֵי אִמָּן אָמְרוּ שִׁירָה:\",1,0],[2,136,68,28,\"שָׁם בִּנְיָמִין. הַצָּעִיר נַעֲשָׂה רוֹדֶה עֲלֵיהֶם:\",1,0],[2,136,68,28,\"רֹדֵם. כְּמוֹ רוֹדָם בְּקָמָ״ץ, מִשָּׁם זָכָה לִהְיוֹת מֶלֶךְ, לְפִי שֶׁיָּרַד תְּחִלָּה לַיָּם. וְכֵן אָמַר לוֹ שְׁמוּאֵל לְשָׁאוּל: ״הֲלוֹא אִם קָטֹן אַתָּה בְּעֵינֶיךָ רֹאשׁ שִׁבְטֵי יִשְׂרָאֵל אָתָּה״ (שמואל א טו:יז), וְתִרְגְּמוֹ יוֹנָתָן: ״שִׁבְטָא דְבִנְיָמִין עֲבַר בְּיַמָּא בְּרֵישׁ כָּל שְׁאָר שִׁבְטַיָּא״:\",2,0],[2,136,68,28,\"שָׂרֵי יְהוּדָה רִגְמָתָם. מִתְקַנְּאִים בָּהֶם וְזוֹרְקִין בָּהֶם אֲבָנִים, וְכֵן שָׂרֵי זְבוּלוּן וְנַפְתָּלִי. וְכֵן אָמַר לוֹ: צִוָּה אֱלֹהֶיךָ עֻזֶּךָ (ס״א אינו). דָּבָר אַחֵר: (רִגְמָתָם – רִקְמָתָם, לְבוּשָׁן בִּגְדֵי וְכוּ׳) רִקְמָתָם לְשׁוֹן אַרְגָּמָן, כָּךְ חִבְּרוֹ מְנַחֵם:\",3,0],[2,136,68,29,\"עוּזָּה אֱלֹהִים וְגוֹ׳. עַכְשָׁיו חוֹזֵר הַמְשׁוֹרֵר לִתְפִלָּתוֹ שֶׁהִתְפַּלֵּל יָקוּם אֱלֹהִים וְיָפוּצוּ אוֹיְבָיו :עוּזָּה אֱלֹהִים וְהִתְגַּבֵּר, אֲשֶׁר כָּל אֵלֶּה פָּעַלְתָּ לָּנוּ:\",1,0],[2,136,68,30,\"מֵהֵיכָלֶךָ עַל יְרוּשָׁלִָם. וּמִמַּה שֶּׁיִּרְאוּ הַמְּלָכִים כְּבוֹד הֵיכָלְךָ אֲשֶׁר עַל יְרוּשָׁלַיִם, יוֹבִילוּ לְךָ דּוֹרוֹן וְשָׁי:\",1,0],[2,136,68,31,\"גְּעַר חַיַּת קָנֶה. זֶה עֲמָלֵק שֶׁנִּמְשַׁל כְּחַיַּת יַעַר הַדָּר בֵּין הַקָּנִים (תהלים פ:יד):\",1,0],[2,136,68,31,\"עֲדַת אַבִּירִים בְּעֶגְלֵי עַמִּים. עַם שֶׁשָּׁמְנוּ וְעָשְׁתוּ כְּפָרִים אַבִּירִים בְּתוֹךְ שְׁאָר הָאֻמּוֹת, שֶׁאֵינָם אֶלָּא כַּעֲגָלִים לְנֶגְדָּם:\",2,0],[2,136,68,31,\"מִתְרַפֵּס בְּרַצֵּי כָסֶף. אֵינָם מִתְרַצִּים לְכָל אָדָם, אֶלָּא אִם כֵּן מְרַצֶּה לָהֶם מָעוֹת (פסחים קיח:):\",3,0],[2,136,68,31,\"בִּזַּר עַמִּים. פִּזְּרוּ אֶת הַשְּׁבָטִים, כְּמָה דְאַתְּ אָמַר: ״אַף חֹבֵב עַמִּים״ (דברים לג:ג). וְתָמִיד קְרָבוֹת יֶחְפָּצוּן, חֲפֵצִים לְהִלָּחֵם בָּנוּ:\",4,0],[2,136,68,32,\"יֶאֱתָיוּ חַשְׁמַנִּים. וְאָז, כְּשֶׁתַּחֲרִיב אֶת עֲמָלֵק וְיָקוּם מֶלֶךְ הַמָּשִׁיחַ, יָבִיאוּ לְךָ דּוֹרוֹנוֹת מִמִּצְרַיִם וּמִכּוּשׁ. וּמְנַחֵם פָּתַר חַשְׁמַנִּים שֵׁם מְדִינָה יוֹשְׁבֵי חַשְׁמוֹנָה (במדבר לג:כט), וְהַפּוֹתְרִים פּוֹתְרִין אוֹתוֹ לְשׁוֹן דּוֹרוֹן:\",1,0],[2,136,68,33,\"שִׁירוּ לֵאלֹהִים. שֶׁהֶרְאָם גָּדְלוֹ וְגָאַל אֶת עַמּוֹ:\",1,0],[2,136,68,34,\"הֵן יִתֵּן. הֵן נוֹתֵן:\",1,0],[2,136,68,36,\"נוֹרָא אֱלֹהִים מִמִּקְדָּשֶׁיךָ. מִמַּה שֶׁהֶחֱרַבְתּוֹ אַתָּה יָראוּי, אִם לְמִקְדָּשׁוֹ לֹא נָשָׂא פָנִים קַל וָחוֹמֶר לָרְשָׁעִים. וּמִדְרַשׁ אַגָּדָה: אַל תִּקְרֵי מִמִּקְדָּשֶׁיךָ אֶלָּא מִמְּקֻדָּשֶׁיךָ, שֶׁכְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִּין בַּצַּדִּיקִים מִתְיָרֵא וּמִתְעַלֶּה וּמִתְקַלֵּס, וְכֵן הוּא אוֹמֵר ״בִּקְרֹבַי אֶקָּדֵשׁ״ (ויקרא י:ג) ״וְנִקְדַּשׁ בִּכְבֹדִי״ (שמות כט:מג) בְּמִיתַת שְׁנֵי בְּנֵי אַהֲרֹן (זבחים קטו:). וְרַבּוֹתֵינוּ דָּרְשׁוּ כָּל הַמִּזְמוֹר עַד בָּרוּךְ ה׳ יוֹם יוֹם עַל מַתַּן תּוֹרָה וְגֶשֶׁם נְדָבוֹת בְּמַתַּן תּוֹרָה וְחַיָּתְךָ יָשְׁבוּ בָהּ. וַאֲנִי אֵין לִבִּי מִתְיַשֵּׁב לְאֻמָּן לְשׁוֹן יָשְׁבוּ בָהּ בִּלְשׁוֹן נִתְיַשְּׁבוּ בַּתּוֹרָה, וְהָהָר חָמַד אֱלֹהִים לְשִׁבְתּוֹ אֵין מִתְיַשֵּׁב לְדָרְשׁוֹ עַל הַר סִינַי שֶׁהֲרֵי לֹא לְשִׁבְתּוֹ חֲמָדוֹ וְלֹא לִשְׁכֹּן בּוֹ לָנֶצַח, וְכָאן כְּתִיב יִשְׁכֹּן לָנֶצַח וְכֵן מַלְכֵי צְבָאוֹת פֵּרְשׁוּ כְּמוֹ מַלְאֲכֵי צְבָאוֹת וְאֵין זֶה לְשׁוֹן הַמִּקְרָא:\",1,0],[2,136,69,1,\"עַל שׁוֹשַׁנִּים. עַל יִשְׂרָאֵל שֶׁהֵם ״כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים״ (שיר השירים ב:ב), שֶׁהַחוֹחִים מְנַקְּבִין אוֹתָם, וְהִתְפַּלֵּל עֲלֵיהֶם:\",1,0],[2,136,69,2,\"כִּי בָאוּ מַיִם. הָאֻמּוֹת:\",1,0],[2,136,69,3,\"בִּיוֵן מְצוּלָה. בְּבוֹץ, טִיט שֶׁל מְצוּלָה:\",1,0],[2,136,69,3,\"וְשִׁבֹּלֶת. הוּא שֶׁטֶף חֹזֶק הַנָּהָר, פִּי״ל בְּלַעַ״ז:\",2,0],[2,136,69,4,\"נִחַר. יָבֵשׁ, כְּמוֹ ״חָרָה מִנִּי חֹרֶב״ (איוב ל:ל):\",1,0],[2,136,69,4,\"כָּלוּ עֵינַי. כָּל תּוֹחֶלֶת מְמֻשָּׁכָה קְרוּיָה כִּלְיוֹן עֵינַיִם, כְּמוֹ ״וְכָלוֹת אֲלֵיהֶם כָּל הַיּוֹם״ (דברים כח:לב), ״מְכַלּוֹת עֵינַיִם״ (ויקרא כו:טז), ״וְעֵינֵי רְשָׁעִים תִּכְלֶינָה״ (איוב יא:כ):\",2,0],[2,136,69,5,\"אֹיְבַי שֶׁקֶר. שׂוֹנְאִים אוֹתִי עַל שֶׁקֶר, שֶׁאֵין אֲנִי רוֹדֵף אַחַר שֶׁקֶר שֶׁלָּהֶם לִתְפֹּשׂ טָעוּתָם:\",1,0],[2,136,69,5,\"אָז אָשִׁיב. כְּשֶׁהֵם נֶאֱסָפִים עָלַי, אֲנִי מְשַׁחֵד אוֹתָם בְּמָמוֹן מַה שֶּׁלֹּא גָזַלְתִּי מֵהֶם:\",2,0],[2,136,69,7,\"אַל יֵבֹשׁוּ בִי קֹוֶיךָ. אַל תַּנִּיחֵנִי בְּיָדָם, פֶּן יֵבֹשׁוּ קֹוֶיךָ בְּמַה שֶּׁמְּאֹרָע בִּי וְיֹאמְרוּ: הֲלֹא כָּךְ אֵרַע לְמִי שֶׁהָיָה מְקַוֶּה לְהַקָּדוֹשׁ בָּרוּךְ הוּא!\",1,0],[2,136,69,9,\"לְאֶחָי. לְעֵשָׂו (בראשית כה:כה):\",1,0],[2,136,69,10,\"קִנְאַת בֵּיתְךָ. רָאוּ הַחִבָּה שֶׁנָּהַגְתָּ בָּנוּ בְּעוֹד בֵּיתְךָ קַיָּם, וְנִתְקַנְּאוּ בִי:\",1,0],[2,136,69,11,\"וָאֶבְכֶּה בַצּוֹם נַפְשִׁי. בְּתַעֲנִיתִי:\",1,0],[2,136,69,11,\"וַתְּהִי לַחֲרָפוֹת לִי. מַה שֶּׁאֲנִי בּוֹכֶה וּמִתְעַנֶּה לְפָנֶיךָ, הֵם מִתְלוֹצְצִים עָלַי:\",2,0],[2,136,69,13,\"וּנְגִינוֹת. בִּי לְשׁוֹתֵי שֵׁכָר (ס״א אינו):\",1,0],[2,136,69,14,\"וַאֲנִי תְפִלָּתִי לְךָ ה׳. יְהִי עֵת תְּפִלָּתִי עֵת רָצוֹן:\",1,0],[2,136,69,16,\"וְאַל תֶּאְטַר. וְאַל תִּסְגֹּר עָלַי:\",1,0],[2,136,69,16,\"בְּאֵר. צָרָה נָכְרִיָּה זוֹ, אֶת פִּיהָ לִבְלָעֵנִי:\",2,0],[2,136,69,16,\"תֶּאְטַר. כְּמוֹ ״אִטֵּר יַד יְמִינוֹ״ (שופטים ג:טו) – סָגוּר יַד יְמִינוֹ, שֶׁאֵינוֹ מִשְׁתַּמֵּשׁ בָּהּ:\",3,0],[2,136,69,19,\"קָרְבָה אֶל נַפְשִׁי. (קְרַב אֵלַי):\",1,0],[2,136,69,19,\"גְאָלָהּ. גְּאוֹל אוֹתָהּ:\",2,0],[2,136,69,21,\"וָאָנוּשָׁה. וָאֵאָנַשׁ וָאֶחֱלֶה, כְּמוֹ ״כִּי אֲנוּשָׁה מַכּוֹתֶיהָ״ (מיכה א:ט), וּכְמוֹ ״וַיֵּאָנַשׁ הַיֶּלֶד״ דְּבַת שֶׁבַע (שמואל ב יב:טו). וְאִם תֹּאמַר: הֵיאַךְ הָאָלֶ״ף זוֹ מְשַׁמֶּשֶׁת שֹׁרֶשׁ וּמְשַׁמֶּשֶׁת שִׁמּוּשׁ הַמֵּסֵב הַדִּבּוּר אֶל הַמְדַבֵּר? כֵּן דֶּרֶךְ תֵּבָה שֶׁתְּחִלָּתָהּ אָלֶ״ף, כְּגוֹן: ״וָאֹהַב אֶת יַעֲקֹב״ (מלאכי א:ב), ״אֲנִי אֹהֲבַי אֵהָב״ (משלי ח:יז) – הֲרֵי הוּא כְּמוֹ ׳וָאֶאֱהַב׳, וְכֵן ״אָסֹף אָסֵף״ (צפניה א:ב) – כְּמוֹ ׳אֶאֱסֹף׳:\",1,0],[2,136,69,21,\"לָנוּד. שֶׁיָּבוֹאוּ לִי אוֹהֲבִים לָנוּד לִי וּלְנַחֲמֵנִי (איוב ב:יא):\",2,0],[2,136,69,22,\"בְּבָרוּתִי. בִּסְעוּדָתִי, כְּמוֹ ״תָּבֹא נָא תָמָר אֲחוֹתִי… וְאֶבְרֶה מִיָּדָהּ״ (שמואל ב יג:ו):\",1,0],[2,136,69,22,\"רֹאשׁ. מָרָה:\",2,0],[2,136,69,23,\"וְלִשְׁלוֹמִים. כְּשֶׁיְּקַוּוּ לְשָׁלוֹם, יֵהָפֵךְ שְׁלוֹמָם לְמוֹקֵשׁ:\",1,0],[2,136,69,27,\"כִּי. אֶת הָעָם הַזֶּה אֲשֶׁר אַתָּה הִכִּיתָ:\",1,0],[2,136,69,27,\"רָדָפוּ. אַתָּה קָצַפְתָּ מְעַט וְהֵם עָזְרוּ לְרָעָה (זכריה א:טו):\",2,0],[2,136,69,27,\"וְאֶל מַכְאוֹב חֲלָלֶיךָ יְסַפֵּרוּ. דִּבְרֵיהֶם לָבוֹא בְּעֵצָה: נַשְׁחִיתֵם ״בִּהְיוֹתָם כֹּאֲבִים״ (בראשית לד:כה):\",3,0],[2,136,69,32,\"וְתִיטַב. הִלּוּלִי לַה׳:\",1,0],[2,136,69,32,\"מִשּׁוֹר פָּר. הוּא שׁוֹר שֶׁהִקְרִיב אָדָם הָרִאשׁוֹן, שֶׁנִּבְרָא בְּקוֹמָתוֹ; וּבַיּוֹם שֶׁנִּקְרָא שׁוֹר, בּוֹ בַיּוֹם הֱבִיאוֹ. שֶׁהַשּׁוֹר בֶּן יוֹמוֹ קָרוּי שׁוֹר, שֶׁנֶּאֱמַר: ״שׁוֹר אוֹ כֶשֶׂב אוֹ עֵז כִּי יִוָּלֵד״ (ויקרא כ״ב:כ״ז). בּוֹ בַיּוֹם נִדְמָה לְפַר, שֶׁהוּא בֶּן שָׁלֹשׁ (ראש השנה י.):\",2,0],[2,136,69,32,\"מַקְרִן מַפְרִיס. קַרְנוֹתָיו קָדְמוּ לְפַרְסוֹתָיו, שֶׁהֲרֵי בְּקוֹמָתוֹ וּבְקַרְנָיו נִבְרָא, וְרֹאשׁוֹ יָצָא מִן הָאָרֶץ תְּחִלָּה; כְּדֶרֶךְ כָּל הַנּוֹלָדִים הוֹצִיאַתָן הָאָרֶץ, נִמְצְאוּ קַרְנָיו קָדְמוּ לְרַגְלָיו (חולין ס.):\",3,0],[2,136,70,1,\"לְדָוִד לְהַזְכִּיר. לְשׁוֹן תְּפִלָּה הוּא, כְּמוֹ ״וַאֲנַחְנוּ בְּשֵׁם ה׳ אֱלֹהֵינוּ נַזְכִּיר״ (תהלים כ:ח), וְכֵן בְּדִבְרֵי הַיָּמִים ״לְהַזְכִּיר וּלְהוֹדוֹת לַה׳״ (דברי הימים א טז:ד). וּבְמִדְרַשׁ תְּהִלִּים רָאִיתִי: מָשָׁל לְמֶלֶךְ שֶׁכָּעַס עַל צֹאנוֹ וְסָתַר אֶת הַדִּיר וְהוֹצִיא אֶת הַצֹּאן וְאֶת הָרוֹעֶה. אַחַר זְמַן הֶחֱזִיר אֶת הַצֹּאן וּבָנָה אֶת הַדִּיר, וְלֹא הִזְכִּיר אֶת הָרוֹעֶה. אָמַר הָרוֹעֶה: הֲרֵי הַצֹּאן מֻחְזָר וְהַדִּיר בָּנוּי, וַאֲנִי אֵינִי נִזְכָּר? כָּךְ, לְמַעְלָה מִן הָעִנְיָן נֶאֱמַר ״כִּי אֱלֹהִים יוֹשִׁיעַ צִיּוֹן וְגוֹ׳״ (תהלים סט:לו), ״וְאוֹהֲבֵי שְׁמוֹ יִשְׁכְּנוּ בָהּ״ (תהלים סט:לז): הֲרֵי הַדִּיר בָּנוּי וְהַצֹּאן כָּנוּס, וְהָרוֹעֶה (זֶה דָוִד) לֹא נִזְכָּר. לְכָךְ נֶאֱמַר: לְדָוִד לְהַזְכִּיר אֱלֹהִים לְהַצִּילֵנִי:\",1,0],[2,136,70,4,\"יָשׁוּבוּ עַל עֵקֶב בָּשְׁתָּם. מִדָּה בְּמִדָּה, כְּמוֹ שֶׁעָשׂוּ לִי:\",1,0],[2,136,70,4,\"עַל עֵקֶב. בְּאוֹתוֹ מַעְגָּל עַצְמוֹ, אנציש״טראציש בְּלַעַ״ז:\",2,0],[2,136,70,4,\"הָאוֹמְרִים. עָלַי:\",3,0],[2,136,70,4,\"הֶאָח הֶאָח. לְשׁוֹן חֶדְוָה, בִּרְאוֹתוֹ בְּאוֹיְבוֹ כִּרְצוֹנוֹ:\",4,0],[2,136,70,6,\"חוּשָׁה לִּי. לְעֶזְרָה:\",1,0],[2,136,71,3,\"לָבוֹא תָּמִיד. בְּאוֹתוֹ מָעוֹן, לְהִנָּצֵל בְּתוֹכוֹ מִן הָרוֹדֵף:\",1,0],[2,136,71,3,\"צִוִּיתָ לְהוֹשִׁיעֵנִי. פְּעָמִים רַבּוֹת הוֹשַׁעְתַּנִי עַל יְדֵי שְׁלוּחֶיךָ:\",2,0],[2,136,71,4,\"וְחוֹמֵץ. כְּמוֹ ״חוֹמֵס״ (משלי ח:לו), וְכֵן ״אַשְּׁרוּ חָמוֹץ״ (ישעיה א:יז), נִגְזָל:\",1,0],[2,136,71,6,\"אַתָּה גוֹזִי. אַתָּה מוֹצִיאִי וּמַעֲבִירִי, כְּמוֹ ״וַיָּגָז שַׂלְוִים״ (במדבר יא:לא), ״כִּי גָז חִישׁ וַנָּעוּפָה״ (תהלים צ:י):\",1,0],[2,136,71,7,\"כְּמוֹפֵת הָיִיתִי לְרַבִּים. רַבִּים רָאוּ צָרוֹתַי וְדָאֲגוּ, פֶּן יִקְרָאֵם דֻּגְמַת צָרָתִי, פֶּן אֶהְיֶה לָהֶם לְאוֹת: כַּאֲשֶׁר הוּקְרָה לָזֶה כֵּן יִקְרֶה לָנוּ, כְּעִנְיָן שֶׁנֶּאֱמַר ״וְהָיָה יְחֶזְקֵאל לָכֶם לְמוֹפֵת״ (יחזקאל כד:כד):\",1,0],[2,136,71,9,\"לְעֵת זִקְנָה. אִם זָקַנְתִּי בַּחֲטָאִים, כְּלוֹמַר, שֶׁחָטָאתִי הַרְבֵּה:\",1,0],[2,136,71,10,\"כִּי אָמְרוּ אוֹיְבַי לִי. אָמְרוּ אוֹיְבַי עָלַי וְנוֹעֲצוּ יַחְדָּו, לֵאמֹר: אֱלֹהִים עֲזָבוֹ – אֵין אָנוּ נֶעֱנָשִׁין עָלָיו, שֶׁכְּבָר נִכְשַׁל בַּעֲבֵירָה:\",1,0],[2,136,71,14,\"וַאֲנִי תָּמִיד אֲיַחֵל. לִישׁוּעָתְךָ, וּכְשֶׁתּוֹשִׁיעֵנִי אוֹסִיף עַל תְּהִלָּתֶךָ:\",1,0],[2,136,71,15,\"לֹא יָדַעְתִּי סְפֹרוֹת. שֶׁל צְדָקוֹת וְהַתְּשׁוּעוֹת שֶׁעָשִׂיתָ עִמִּי:\",1,0],[2,136,71,16,\"אָבוֹא. לְהוֹדוֹת וּלְהַלֵּל בִּגְבוּרָתְךָ:\",1,0],[2,136,71,17,\"וְעַד הֵנָּה. עַד הַיּוֹם בְּמַה שֶּׁעָבַר עָלַי:\",1,0],[2,136,71,17,\"וְעַד זִקְנָה וְשֵׂיבָה. לִכְשֶׁאַגִּיעַ לְשִׁשִּׁים וְשִׁבְעִים אַל תַּעַזְבֵנִי (אבות ה,כה) (ס״א אינו):\",2,0],[2,136,71,18,\"לְכָל יָבוֹא גְּבוּרָתֶךָ. לְכָל אֲשֶׁר יָבוֹא אֶצְלִי אַגִּיד גְּבוּרָָָָָָתֶיךָ:\",1,0],[2,136,71,19,\"וְצִדְקָתְךָ אֱלֹהִים. אֲשֶׁר הִיא עַד מָרוֹם, שְׁנֵי הַמִּקְרָאוֹת מְחֻבָּרִים עִם אַגִּיד זְרוֹעֲךָ לְדוֹר:\",1,0],[2,136,71,23,\"תְּרַנֵּנָּה שְׂפָתַי. עִם זֶמֶר קוֹל הַכִּנּוֹר, כְּשֶׁאֲזַמְּרָה לָּךְ בְכִּנּוֹר:\",1,0],[2,136,72,1,\"לִשְׁלֹמֹה. עַל שְׁלֹמֹה בְּנוֹ הִתְפַּלֵּל תְּפִלָּה זוֹ, שֶׁצָּפָה בְּרוּחַ הַקֹּדֶשׁ, שֶׁהוּא עָתִיד לִשְׁאוֹל מֵאֵת הַקָּדוֹשׁ בָּרוּךְ הוּא לֵב לְהָבִין לִשְׁמֹעַ מִשְׁפָּט (מלכים א ג:ט):\",1,0],[2,136,72,1,\"מִשְׁפָּטֶיךָ. חָכְמַת דִּינְךָ שֶׁצִּוִּיתָ בַּתּוֹרָה:\",2,0],[2,136,72,1,\"וְצִדְקָתְךָ. לְצַדֵּק אֶת הַדִּין:\",3,0],[2,136,72,1,\"מֶלֶךְ וּבֶן מֶלֶךְ. שְׁנֵיהֶם בִּשְׁלֹמֹה אֲמוּרִים. דָּבָר אַחֵר: מִשְׁפָּטֶיךָ לְמֶלֶךְ תֵּן, הַיִּסּוּרִין יְהוּ כָּלִים בִּי, וְהַצְּדָקָה עֲשֵׂה לִבְנִי, שֶׁיִּהְיֶה שָׁלוֹם בְּיָמָיו:\",4,0],[2,136,72,3,\"יִשְׂאוּ הָרִים. בְּיָמָיו:\",1,0],[2,136,72,3,\"שָׁלוֹם לָעָם. וּמַהוּ הַשָּׁלוֹם שֶׁהֶהָרִים נוֹשְׂאִין? כְּשֶׁהֵן עוֹשִׂין פֵּרוֹת, אֵין עֵין הַבְּרִיּוֹת צָרָה, וְקוֹרֵא אִישׁ לְרֵעֵהוּ אֶל תַּחַת גֶּפֶן וְאֶל תַּחַת תְּאֵנָה (זכריה ג:י):\",2,0],[2,136,72,3,\"וּגְבָעוֹת בִּצְדָקָה. וּגְבָעוֹת יִשְׂאוּ לָהֶם שָׁלוֹם עַל יְדֵי הַצְּדָקָה שֶׁיַּעֲשׂוּ:\",3,0],[2,136,72,5,\"יִירָאוּךָ עִם שָׁמֶשׁ. מִמֶּנִּי יִלְמְדוּ יִשְׂרָאֵל לְיִרְאָה אוֹתְךָ כָּל יְמֵי הַשֶּׁמֶשׁ וְהַיָּרֵחַ, לְדוֹר דּוֹרִים:\",1,0],[2,136,72,5,\"וְלִפְנֵי יָרֵחַ. בְּעוֹד הַיָּרֵחַ קַיָּם וְהֵם לְפָנָיו, וְהַרְבֵּה יֵשׁ בִּלְשׁוֹן מִשְׁנָה (ביכורים ב,ג): בִּפְנֵי הַבַּיִת וְשֶׁלֹּא בִּפְנֵי הַבַּיִת:\",2,0],[2,136,72,6,\"יֵרֵד כְּמָטָר עַל גֵּז. יֵרֵד דְּבָרוֹ בְּתוֹךְ עַמְּךָ וּבְלִבָּם כְּמָטָר הַיּוֹרֵד עַל יֶרֶק הַגָּזוּז, שֶׁהוּא צָרִיךְ לִגְשָׁמִים לְאַחַר שֶׁגְּזָזוּהוּ. כְּעִנְיָן שֶׁנֶּאֱמַר: ״וְהִנֵּה לֶקֶשׁ אַחַר גִּזֵּי הַמֶּלֶךְ״ (עמוס ז:א):\",1,0],[2,136,72,6,\"זַרְזִיף אָרֶץ. לְשׁוֹן טִיפִּים הוּא בִּלְשׁוֹן אֲרַמִּי; בְּמַסֶּכֶת יוֹמָא (יומא פז.): הֲווֹ מָטוּ זַרְזִיפֵי דְמַיָּא:\",2,0],[2,136,72,7,\"יִפְרַח בְּיָמָיו צַדִּיק. יִשְׂרָאֵל:\",1,0],[2,136,72,7,\"וְרֹב שָׁלוֹם. יִפְרַח בְּיָמָיו, וִיהִי שָׁלוֹם זֶה אָרוֹךְ עַד לְעוֹלָם. וְכָל תְּפִלָּה זוֹ נִתְקַיְּמָה חוּץ מִדָּבָר הַזֶּה; לְפִי שֶׁשְּׁלֹמֹה חָטָא לְפִיכָךְ לֹא נִמְשְׁכָה מַלְכוּתוֹ, שֶׁהַמַּלְכוּת נִמְסְרָה לְדָוִד עַל תְּנַאי ״אִם יִשְׁמְרוּ בָנֶיךָ אֶת דַּרְכָּם״ (מלכים א ב:ד). וְיִשְׂרָאֵל פָּרְחוּ בְיָמָיו, שֶׁנֶּאֱמַר ״יְהוּדָה וְיִשְׂרָאֵל רַבִּים כַּחוֹל וְגוֹ׳״ (מלכים א ד:כ), וְרֹב שָׁלוֹם הָיָה, שֶׁנֶּאֱמַר ״וַיֵּשֶׁב יְהוּדָה וְיִשְׂרָאֵל לָבֶטַח אִישׁ תַּחַת גַּפְנוֹ כָּל יְמֵי שְׁלֹמֹה״ (מלכים א ה:ה):\",2,0],[2,136,72,8,\"וְיֵרְדְּ מִיָּם עַד יָם. כָּל אֶרֶץ יִשְׂרָאֵל, מִיַּם סוּף וְעַד יָם פְּלִשְׁתִּים (שמות כג:לא):\",1,0],[2,136,72,8,\"וּמִנָּהָר עַד אַפְסֵי אָרֶץ. ״כִּי הוּא רוֹדֶה בְּכָל עֵבֶר הַנָּהָר וְגוֹמֵר״ (מלכים א ה:ד):\",2,0],[2,136,72,9,\"צִיִּים. כִּתּוֹת שֶׁל שָׂרִים, כְּדִמְתַרְגֵּם ״וְצִים מִיַּד כִּתִּים״ (במדבר כד:כד): ״וְסִיעָן יִסְתַּחְרָן מֵרוֹמָאֵי״:\",1,0],[2,136,72,10,\"מַלְכֵי תַרְשִׁישׁ וְאִיִּים מִנְחָה יָשִׁיבוּ. ״כִּי אֳנִי תַרְשִׁישׁ לַמֶּלֶךְ בַּיָּם עִם אֳנִי חִירָם אַחַת לְשָׁלֹשׁ שָׁנִים תָּבֹא אֳנִי תַרְשִׁישׁ וְגוֹ׳״ (מלכים א י:כב):\",1,0],[2,136,72,10,\"מַלְכֵי שְׁבָא. מַלְכַּת שְׁבָא (מלכים א י:א):\",2,0],[2,136,72,10,\"אֶשְׁכָּר. דּוֹרוֹן:\",3,0],[2,136,72,11,\"כָּל גּוֹיִם יַעַבְדוּהוּ. ״וְכָל הָאָרֶץ״ מְבִיאִים מִנְחָה לִשְׁלֹמֹה (מלכים א י:כד), ״וְהֵמָּה מְבִיאִין אִישׁ מִנְחָתוֹ״ (מלכים א י:כה):\",1,0],[2,136,72,14,\"מִתּוֹךְ וּמֵחָמָס. מִמַּכּוֹת וּמִגָּזֵל. מָצָאתִי מִתּוֹךְ לְשׁוֹן תּוֹךְ תּוֹכוֹת, בַּעֲלֵי מְזִמּוֹת חוֹרְשֵׁי אָוֶן, כְּמוֹ ״אִישׁ תְּכָכִים״ (משלי כט:יג):\",1,0],[2,136,72,14,\"יִגְאַל נַפְשָׁם. עַל יְדֵי מִשְׁפָּט וּצְדָקָה שֶׁיַּעֲשֶׂה בָּהֶם:\",2,0],[2,136,72,15,\"וִיחִי. שְׁלֹמֹה:\",1,0],[2,136,72,15,\"וְיִתֶּן לוֹ. הַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,136,72,15,\"מִזְּהַב שְׁבָא. וְכֵן הָיְתָה: ״גַּם עֹשֶׁר גַּם כָּבוֹד אֲשֶׁר לֹא הָיָה כָמוֹךָ וְגוֹמֵר״ (מלכים א ג:יג):\",3,0],[2,136,72,15,\"וְיִתְפַּלֵּל בַּעֲדוֹ תָּמִיד וְגוֹ׳. הִיא הַתְּפִלָּה הִיא הַבְּרָכָה; כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר לָאָדָם: בָּרוּךְ תִּהְיֶה, לְשׁוֹן תְּפִלָּה הוּא:\",4,0],[2,136,72,16,\"פִּסַּת בַּר. לְשׁוֹן פִּסְיוֹן, תּוֹסֶפֶת וְרִבּוּי. וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ (כתובות קיא:; שבת ל:): לְשׁוֹן גְּלוּסְקָאוֹת לִימוֹת הַמָּשִׁיחַ, וְכָל הַמִּזְמוֹר בְּמֶלֶךְ הַמָּשִׁיחַ. דָּבָר אַחֵר: פִּסַּת בַּר לְשׁוֹן רָצוֹן, כְּמוֹ פַּיִיס, שֶׁהַבְּרִיּוֹת מִתְפַּיְּסִין וּמִתְרַצִּין מֵאֵת הַמָּקוֹם כְּשֶׁנּוֹתֵן שׂוֹבַע בָּעוֹלָם:\",1,0],[2,136,72,16,\"יִרְעַשׁ כַּלְּבָנוֹן פִּרְיוֹ. חִטִּין גַּסִּין כְּפֵירוֹת הָאִילָן, כַּכְּלָיוֹת שֶׁל שׁוֹר הַגָּדוֹל, שֶׁהָיָה בִּימֵי שִׁמְעוֹן בֶּן שָׁטַח (כתובות קיא:):\",2,0],[2,136,72,16,\"וְיָצִיצוּ. יִשְׂרָאֵל:\",3,0],[2,136,72,16,\"מֵעִיר. מִתּוֹךְ יְרוּשָׁלַיִם כְּעֵשֶׂב הָאָרֶץ:\",4,0],[2,136,72,17,\"יְהִי שְׁמוֹ. שֶׁל שְׁלֹמֹה נִזְכָּר לְעוֹלָם בְּעָשְׁרוֹ וּבְחָכְמָתוֹ:\",1,0],[2,136,72,17,\"לִפְנֵי שֶׁמֶשׁ יִנּוֹן שְׁמוֹ. כָּל יְמֵי הַשֶּׁמֶשׁ יִגְדַּל שְׁמוֹ:\",2,0],[2,136,72,17,\"יִנּוֹן. לְשׁוֹן מַלְכוּת וְשָׂרָרָה, כְּמוֹ (משלי כט:כא) ״וְאַחֲרִיתוֹ יִהְיֶה מָנוֹן״, (בראשית כא:כג) ״וּלְנִינִי״ – הַשַּׁלִּיט עַל נְכָסַי אַחֲרַי, (תהלים עד:ח) ״אָמְרוּ בְלִבָּם נִינָם יָחַד״ – מַלְכֵיהֶם יָחַד (מגילה י:):\",3,0],[2,136,72,17,\"וְיִתְבָּרְכוּ בוֹ. אָדָם אוֹמֵר לִבְנוֹ: תְּהִי חָכָם וְעָשִׁיר כִּשְׁלֹמֹה:\",4,0],[2,136,72,18,\"בָּרוּךְ ה׳. הָעוֹשֶׂה נִפְלָאוֹת גְּדוֹלוֹת בְּרֶדֶת הָאֵשׁ מִן הַשָּׁמַיִם עַל יְדֵי שְׁלֹמֹה בְּנִי (דברי הימים ב ז:א):\",1,0],[2,136,72,20,\"כָּלּוּ תְפִלּוֹת דָּוִד. רַבּוֹתֵינוּ דָּרְשׁוּ כָּלּוּ, כָּל אֵלּוּ תְפִלּוֹת דָּוִד לִכְלוֹל כָּל הַסֵּפֶר עַל שֵׁם דָּוִד, וְאַף מַה שֶּׁאָמְרוּ בְּנֵי קֹרַח וַעֲשָׂרָה זְקֵנִים עַל שֵׁם שֶׁהוּא נִקְרָא נְעִים זְמִירוֹת יִשְׂרָאֵל (שמואל ב כג:א). וְיֵשׁ לִפְתּוֹר כָּלּוּ כְּמוֹ נִסְתַּיְּמוּ, כְּמוֹ ״רוֹמּוּ מְעַט״ (איוב כד:כד), ״שֹׁמּוּ שָׁמַיִם״ (ירמיה ב:יב). וְאִם כֵּן הוּא, לֹא נִכְתַּב הַמִּזְמוֹר בִּמְקוֹמוֹ, וְאֵין מֻקְדָּם וּמְאֻחָר בַּסֵּפֶר. וְנִרְאִין הַדְּבָרִים שֶׁלְּעֵת זִקְנָתוֹ, כְּשֶׁהִמְלִיךְ אֶת שְׁלֹמֹה, אֲמָרוֹ:\",1,0],[2,136,73,1,\"אַךְ טוֹב לְיִשְׂרָאֵל אֱלֹהִים. לְפִי שֶׁעִנְיַן הַמִּזְמוֹר מְדַבֵּר בַּצָּרוֹת הַבָּאוֹת עַל עוֹבְדֵי הַמָּקוֹם, לְכָךְ פָּתַח בּוֹ כָּךְ. וְזֶהוּ פֵּרוּשׁוֹ: אַף עַל פִּי שֶׁאֲנִי צוֹעֵק וּמִתְמֵהַּ עַל צָרוֹתֵיהֶם שֶׁל יִשְׂרָאֵל, יָדַעְתִּי כִּי הַקָּדוֹשׁ בָּרוּךְ הוּא טוֹב לָהֶם, וּלְטוֹבָתָם הוּא מֵבִיא עֲלֵיהֶם אֶת הָרָעָה כְּדֵי לְזַכּוֹתָם לְחַיֵּי הָעוֹלָם הַבָּא:\",1,0],[2,136,73,2,\"וַאֲנִי. מִטֶּרֶם שׂוּמִי זֹאת אֶל לִבִּי:\",1,0],[2,136,73,2,\"כִּמְעַט נָטָיוּ רַגְלָי וְשֻׁפְּכוּ אֲשֻׁרַי. לִנְטוֹת מֵאַחֲרֵי הַמָּקוֹם:\",2,0],[2,136,73,3,\"כִּי קִנֵּאתִי בַּהוֹלְלִים. בִּמְעַרְבְּבֵי דַרְכֵיהֶם אֲשֶׁר הָיִיתִי רוֹאֶה אֶת שְׁלוֹמָם:\",1,0],[2,136,73,3,\"בַּהוֹלְלִים. מְעַרְבְּבִים, כְּמוֹ (ישעיהו א:כב) ״סָבְאֵךְ מָהוּל בַּמָּיִם״ (ס״א אינו):\",2,0],[2,136,73,4,\"כִּי אֵין חַרְצֻבּוֹת לְמוֹתָם. לְשׁוֹן אֲסִירָה, כְּמוֹ ״פַּתֵּחַ חַרְצֻבּוֹת רֶשַׁע״ (ישעיה נח:ו), מַסְגְּרֵי כַּבְלֵי רֶשַׁע שֶׁאוֹסְרִין בָּהֶן הָעֲנִיִּים. אַף כָּאן: אֵין יִסּוּרִין לְמִיתָתָם, הַמֵּתִים בָּהֶם מֵהֶם בְּרִיאִים כְּאוּלָם, בְּלֹא יִסּוּרִין. וְרַבּוֹתֵינוּ פֵּרְשׁוּ חַרְצֻבּוֹת נוֹטְרִיקוֹן: שֶׁאֵין חֲרֵדִין וְעַצְבִין מִיּוֹם הַמִּיתָה (שבת לא:). דָּבָר אַחֵר: שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מְאַחֵר צִבְיוֹנָם (פֵּרוּשׁ רְצוֹנָם):\",1,0],[2,136,73,6,\"לָכֵן עֲנָקַתְמוֹ גַאֲוָה. בַּעֲבוּר זֶה שֶׁאֵין יִסּוּרִין בָּאִין עֲלֵיהֶם, הֶעֱנִיקָתַם הַגַּאֲוָה לַעֲלוֹת עַל צַוָּארָם גַּסּוּת הָרוּחַ:\",1,0],[2,136,73,6,\"יַעֲטָף שִׁית חָמָס לָמוֹ. הֶחָמָס שֶׁעוֹשִׂין, עוֹשֶׂה אוֹתָם שְׁמֵנִים וְעוֹטֵף אֶת שְׁתוֹתֵיהֶם וַעֲגָבוֹתֵיהֶם בְּעֹבִי שׁוּמָן וּבָשָׂר:\",2,0],[2,136,73,7,\"יָצָא מֵחֵלֶב עֵינֵימוֹ. עֵינֵיהֶם בּוֹלְטוֹת מֵרֹב שׁוּמָן, כָּל אָדָם כָּחוּשׁ עֵינָיו מְשׁוּקָּעוֹת:\",1,0],[2,136,73,7,\"עָבְרוּ מַשְׂכִּיּוֹת לֵבָב. יוֹתֵר מִמַּה שֶּׁלִּבָּם מְיַחֵל וּמְצַפֶּה, בָּאָה לָהֶם תַּאֲוָתָם. עָבְרוּ בָּהֶם בְּהַשָּׂגַת יָדָם אֶת תַּאֲוַת לִבָּם:\",2,0],[2,136,73,8,\"יָמִיקוּ. אֶת רֵעֵיהֶם:\",1,0],[2,136,73,8,\"וִידַבְּרוּ בְרָע עֹשֶׁק. לַעֲשׁוֹק אֶבְיוֹנִים:\",2,0],[2,136,73,8,\"מִמָּרוֹם יְדַבֵּרוּ. כְּגוֹן פַּרְעֹה וְסַנְחֵרִיב וּנְבוּכַדְנֶצַּר: ״מִי ה׳ אֲשֶׁר אֶשְׁמַע בְּקוֹלוֹ״ (שמות ה:ב), ״מִי בְּכָל אֱלֹהֵי הָאֲרָצוֹת״ (מלכים ב יח:לה), ״אֶעֱלֶה עַל בָּמֳתֵי עָב״ (ישעיהו יד:יד). וְזֶהוּ שָׁתוּ בַשָּׁמַיִם פִּיהֶם:\",3,0],[2,136,73,10,\"לָכֵן יָשׁוּב עַמּוֹ הֲלֹם. לְפִי שֶׁעַמּוֹ רוֹאִים ״דֶּרֶךְ רְשָׁעִים צָלֵחָה״ (ירמיה יב:א), יָשׁוּבוּ עַל דֶּרֶךְ הָרְשָׁעִים לָלֶכֶת בְּדַרְכֵיהֶם:\",1,0],[2,136,73,10,\"הֲלֹם. כְּמוֹ ״מִי הֲבִיאֲךָ הֲלֹם״ (שופטים יח:ג) – פֹּה:\",2,0],[2,136,73,10,\"וּמֵי מָלֵא יִמָּצוּ לָמוֹ. וּמַיִם שֶׁל פֶּלֶג הַמָּלֵא, הֵם דִּבְרֵי תוֹרָה, נֶחְשָׁבִים לָמוֹ תַּמְצִית וּמְזֻלְזָלִים בְּעֵינֵיהֶם:\",3,0],[2,136,73,11,\"וְאָמְרוּ אֵיכָה יָדַע אֵל. אֵיכָה נוּכַל לוֹמַר שֶׁיֵּשׁ דֵּעָה בְּהַקָּדוֹשׁ בָּרוּךְ הוּא, וְתוֹרָתוֹ אֱמֶת?\",1,0],[2,136,73,12,\"הִנֵּה אֵלֶּה רְשָׁעִים. הֵם וְעוֹבְרִים עַל תּוֹרָתוֹ, וַהֲרֵי הֵם שְׁלֵוִים בָּעוֹלָם וּמַגְדִּילִים כֹּחַ וְעֹשֶׁר:\",1,0],[2,136,73,12,\"וְשַׁלְוֵי עוֹלָם. לְשׁוֹן שַׁלְוָה:\",2,0],[2,136,73,12,\"הִשְׂגּוּ. הִגְדִּילוּ, וּמְנַחֵם פֵּירֵשׁ ״יָשׁוּב עַמּוֹ הֲלוֹם״ (תהלים י:י), יָשׁוּב הָרָשָׁע לַהֲלוֹם אֶת עַמּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהָרִאשׁוֹן לָמַדְתִּי מִדְּבָרָיו שֶׁל רַבִּי מֵאִיר בַּר יִצְחָק שְׁלִיחַ צִבּוּר זַצַ״ל:\",3,0],[2,136,73,13,\"אַךְ רִיק זִכִּיתִי לְבָבִי. כָּל זֶה מוּסָב עַל וְאָמְרוּ אֵיכָה יָדַע אֵל, וְגַם אוֹמֵר: אַךְ לָרִיק וְעַל חִנָּם אָנוּ שׁוֹמְרִים מִצְווֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וַהֲרֵי אָנוּ נְגוּעִים כָּל הַיּוֹם:\",1,0],[2,136,73,14,\"וְתוֹכַחְתִּי. נִרְאֵית כָּל הַיּוֹם תָּמִיד, מִבֹּקֶר לְבֹקֶר מִתְחַדְּשׁוֹת צָרוֹת חֲדָשׁוֹת:\",1,0],[2,136,73,15,\"אִם אָמַרְתִּי אֲסַפְּרָה כְמוֹ. אָמַר אָסָף: אִם אָמַרְתִּי בְּלִבִּי לְסַפֵּר אֶת הַכֹּל כְּמוֹ שֶׁהוּא, כָּל מַה שֶּׁעַמּוֹ אוֹמֵר עַל זֹאת:\",1,0],[2,136,73,15,\"הִנֵּה דוֹר בָּנֶיךָ בָגָדְתִּי. כְּלוֹמַר אָשִׂים אוֹתָם בּוֹגְדִים וּרְשָׁעִים:\",2,0],[2,136,73,16,\"וָאֲחַשְּׁבָה. בְּלִבִּי:\",1,0],[2,136,73,16,\"לָדַעַת זֹאת. מַה הִיא מִדָּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּן הוּא עָמָל בְעֵינָי. נִרְאֵית הָיְתָה מִדָּה זֹאת לִי עָמָל וְלֹא מִשְׁפָּט:\",2,0],[2,136,73,17,\"עַד. אֲשֶׁר בָּאתִי אֶל מִקְדְּשֵׁי אֵל. אֲשֶׁר בִּירוּשָׁלַיִם, וְרָאִיתִי מַה שֶּׁאֵרַע בְּסַנְחֵרִיב (מלכים ב יט:לה-לו), וְאָז הֵבִינוֹתִי לְאַחֲרִית הָרְשָׁעִים שֶׁהוּא לַאֲבַדּוֹן וְאָמַרְתִּי: אַךְ כָּל הַטּוֹבָה הַבָּאָה לָהֶם חֲלָקוֹת הֵם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲלִיק לָהֶם הַדֶּרֶךְ שֶׁלָּהֶם, שֶׁתְּהֵא נוֹחָה וַחֲלָקָה, לְמַעַן לֹא יִתְּנוּ לֵב לָשׁוּב אֵלָיו וְיֹאבְדוּ:\",1,0],[2,136,73,18,\"אַךְ בַּחֲלָקוֹת תָּשִׁית לָמוֹ. כָּל הַטּוֹבָה הַבָּאָה לָהֶם, שֶׁהֲרֵי סוֹפָם הִפַּלְתָּם לְמַשּׁוּאוֹת:\",1,0],[2,136,73,19,\"מִן בַּלָּהוֹת. מִן שֵׁדִים:\",1,0],[2,136,73,20,\"כַּחֲלוֹם מֵהָקִיץ. כְּשֵׁינָה שֶׁאֵין לָהּ קֵץ, שֶׁהוּא שֵׁינַת עוֹלָם, כֵּן הָיְתָה לָהֶם: ״וַיֵּצֵא מַלְאַךְ ה׳ וַיַּךְ בְּמַחֲנֵה אַשּׁוּר״ (ישעיהו לז:לו; מלכים ב יט:לה):\",1,0],[2,136,73,20,\"אֲדֹנָי בָּעִיר צַלְמָם תִּבְזֶה. בִּירוּשָׁלַיִם, שֶׁהֵרֵעוּ עָלֶיהָ, שָׁם נִתְבַּזָּה צֶלֶם דְּמוּתָם וְנִשְׂרְפוּ כֻּלָּם:\",2,0],[2,136,73,21,\"כִּי יִתְחַמֵּץ לְבָבִי. מִטֶּרֶם שֶׁרָאִיתִי מַפָּלָה זוֹ בְּרוּחַ הַקֹּדֶשׁ הָיָה לְבָבִי מִתְחַמֵּץ עַל דֶּרֶךְ הָרְשָׁעִים שֶׁצָּלְחָה (ירמיה יב:א), וּבְכִלְיוֹתַי הָיִיתִי מִשְׁתּוֹנָן, לְשׁוֹן חֶרֶב שָׁנוּן (משלי כה:יח), וּכְשֶׁהוּא מִתְפַּעֵל הַתָּי״ו נִתֶּנֶת בְּאֶמְצַע שֹׁרֶשׁ הַתֵּיבָה כְּדֶרֶךְ כָּל תֵּיבָה שֶׁיְּסוֹד תְּחִלָּתָהּ שִׁי״ן:\",1,0],[2,136,73,22,\"וַאֲנִי. הָיִיתִי בַעַר וְלֹא הָיִיתִי יוֹדֵעַ מַה הִיא הַמִּדָּה, וְכִבְהֵמָה הָיִיתִי עִמָּךְ:\",1,0],[2,136,73,23,\"וַאֲנִי. אַף עַל פִּי שֶׁהָיִיתִי רוֹאֶה כָּל זֶה, תָּמִיד הָיִיתִי עִמָּךְ. וְלֹא זַזְתִּי מִיִּרְאָתְךָ:\",1,0],[2,136,73,23,\"אָחַזְתָּ בְּיַד יְמִינִי. לְהַחֲזִיקֵנִי בְּיִרְאָתְךָ, כְּשֶׁקָּרְבוּ רַגְלַי לִנְטוֹת מִדַּרְכֶּךָ; כְּמוֹ שֶׁאָמַר לְמַעְלָה כִּמְעַט נָטָיוּ רַגְלָי:\",2,0],[2,136,73,24,\"תַּנְחֵנִי. נְחִיתַנִי:\",1,0],[2,136,73,24,\"וְאַחַר כָּבוֹד תִּקָּחֵנִי. אִלּוּ הָיָה טַעַם עַל כָּבוֹד, הָיָה פִּתְרוֹנוֹ: לְאַחַר שֶׁהִשְׁלַמְתָּ לְסַנְחֵרִיב כָּל הַכָּבוֹד שֶׁפָּסַקְתָּ לוֹ, תִּקָּחֵנוּ אֵלֶיךָ. הִפְלֵאתָ נִסֶּיךָ לְיִשְׂרָאֵל וְהֶחֱרַבְתָּ אֶת סַנְחֵרִיב. עַכְשָׁיו שֶׁהַטַּעַם עַל וְאַחַרֵי כֵּן, זֶה פִּתְרוֹנוֹ: וְאַחַר, לְכָבוֹד תִּקָּחֵנִי – מְשַׁכְתַּנִי אֵלֶיךָ לְכָבוֹד וּלְתִפְאֶרֶת:\",2,0],[2,136,73,25,\"מִי לִי בַשָּׁמָיִם. שׁוּם מַלְאָךְ שֶׁבָּחַרְתִּי לִי לֶאֱלוֹהַּ? לֹא בָחַרְתִּי אֶלָּא אוֹתְךָ:\",1,0],[2,136,73,26,\"כָּלָה שְׁאֵרִי. נִתְאַוָּה בְּשָׂרִי וּלְבָבִי לְךָ:\",1,0],[2,136,73,26,\"כָּלָה שְׁאֵרִי. לְשׁוֹן תַּאֲוָה, כְּמוֹ ״כָּלְתָה לִתְשׁוּעָתְךָ נַפְשִׁי״ (תהלים קיט:פא):\",2,0],[2,136,73,27,\"זוֹנֶה מִמֶּךָּ. נִפְרָד מִמְּךָ:\",1,0],[2,136,73,28,\"מַלְאֲכוֹתֶיךָ. שְׁלִיחוּתֶיךָ, רוּחַ הַקֹּדֶשׁ הַבָּא בְּלִבִּי לֵאמֹר:\",1,0],[2,136,74,1,\"יֶעְשַׁן אַפְּךָ. כָּל הַכּוֹעֵס, נְחִירָיו מוֹצִיאִין עָשָׁן:\",1,0],[2,136,74,2,\"קָנִיתָ קֶדֶם. לִפְנֵי בְּרִייַת עוֹלָם, שֶׁנֶּאֱמַר ״מָעוֹן אַתָּה הָיִיתָ לָּנוּ, בְּטֶרֶם הָרִים יֻלָּדוּ״ (תהלים צ:א-ב):\",1,0],[2,136,74,2,\"זֶה שָׁכַנְתָּ בּוֹ. תִּקּוּן לָשׁוֹן הוּא, כְּמוֹ ״זוּ חָטָאנוּ לוֹ״ (ישעיהו מב:כד), וְהוּא כְּמוֹ אֲשֶׁר שָׁכַנְתָּ בּוֹ:\",2,0],[2,136,74,3,\"הָרִימָה פְעָמֶיךָ לְמַשֻּׁאוֹת נֶצַח. הַגְבֵּהַּ פְּעִימוֹת וּבֶהָלוֹת שֶׁלְּךָ שֶׁיְּהוּ לְאוֹיְבֶיךָ לְמַשֻּׁאוֹת נֶצַח, עַל כָּל אֲשֶׁר הֵרַע הָאוֹיֵב בְּבֵית הַמִּקְדָּשׁ. כֵּן חִבְּרוֹ מְנַחֵם עִם ״וַתִּפָּעֶם רוּחוֹ״ (בראשית מא:ח):\",1,0],[2,136,74,3,\"לְמַשֻּׁאוֹת. לְשׁוֹן חֻרְבָּן, כְּמוֹ ״שָׁאִיָּה״ (ישעיהו כד:יב), ״תִּשָּׁאֶה שְׁמָמָה״ (ישעיהו ו:יא) (ס״א אינו):\",2,0],[2,136,74,4,\"מוֹעֲדֶךָ. הוּא בֵּית הַמִּקְדָּשׁ, אֲשֶׁר נֶאֱמַר בּוֹ ״וְנוֹעַדְתִּי לְךָ שָׁם״ (שמות כה:כב):\",1,0],[2,136,74,4,\"שָׂמוּ אוֹתוֹתָם. כְּשֶׁגָּבְרָה יָדָם לְהַחֲרִיבוֹ, אָז שָׂמוּ לָהֶם אֶת אוֹתוֹת קְסָמֵיהֶם שֶׁהֵם אוֹתוֹת אֱמֶת. וּמָה הֵם הַקְּסָמִים? ״קִלְקַל בַּחִצִּים שָׁאַל בַּתְּרָפִים״ (יחזקאל כא:כו):\",2,0],[2,136,74,5,\"יִוָּדַע כְּמֵבִיא לְמַעְלָה בִּסְבָךְ עֵץ קַרְדֻּמּוֹת. יוֹדֵעַ הָאוֹיֵב, כְּשֶׁהָיָה מַכֶּה בְּשַׁעֲרֵי פִּתְחֵי הַמִּקְדָּשׁ, שֶׁהוּא כְּמֵבִיא מַכּוֹתָיו לְמַעְלָה בָּרָקִיעַ. וּמִנַּיִן הָיָה יוֹדֵעַ? שֶׁהֲרֵי הָיָה רוֹאֶה שֶׁהָיָה הָעֵץ מְסַבֵּךְ וְאוֹחֵז אֶת הַקַּרְדֻּמּוֹת וּבוֹלְעָן, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ (סנהדרין צו:): כּוּלְּהוּ בְּלַעְתִּינְהוּ חַד תַּרְעָא דִּירוּשָׁלַיִם:\",1,0],[2,136,74,5,\"בִּסְבׇךְ עֵץ קַרְדֻּמּוֹת. לְשׁוֹן ״נֶאֱחַז בַּסְּבַךְ״ (בראשית כב:יג), הָעֵץ סוֹבֵךְ אוֹתָם וְהֵם נִסְבָּכִין בּוֹ:\",2,0],[2,136,74,6,\"וְעַתָּה. אַף עַל פִּי שֶׁהָיָה רוֹאֶה שֶׁלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא קָשֶׁה, לֹא נִמְנַע מִלְּהַלֹּם כָּל פְּתָּחֶיהָ וְכָל שְׁעָרֶיהָ יָחַד:\",1,0],[2,136,74,6,\"בְּכַשִּׁיל וְכֵילַפֹּת. כְּלֵי מַשְׁחִית שֶׁל נַגָּרִים הֵם, ״וּבְקַרְדֻּמּוֹת בָּאוּ לָהּ״ (ירמיהו מו:כב) תַּרְגּוּם יוֹנָתָן ״בְּכַשִׁילַיָּא״. כֵּילַפֹּת לְשׁוֹן עֲרָבִי הוּא, כָּךְ פֵּרֵשׁ דּוֹנָשׁ, וְהוּא מִכְּלֵי הַנַּגָּרִים:\",2,0],[2,136,74,6,\"יַהֲלֹמוּן. הָאוֹיְבִים:\",3,0],[2,136,74,8,\"אָמְרוּ בְלִבָּם נִינָם יָחַד. נִינָם מוֹשְׁלֵיהֶם, וְכֵן (תהלים עב:יז) ״יָנוֹן שְׁמוֹ״, (משלי כט:כא) ״וְאַחֲרִיתוֹ יִהְיֶה מָנוֹן״. כָּל מוֹשְׁלֵיהֶם מַחֲשָׁבָה אַחַת לָהֶם, הָרִאשׁוֹנִים כָּאַחֲרוֹנִים, לְהִזְדַּוֵּג לְפַטְרוֹנָם שֶׁל יִשְׂרָאֵל תְּחִלָּה וְאַחַר כָּךְ יִזְדַּוְּגוּ לָהֶם. וְתֵדַע שֶׁהֲרֵי שָׂרְפוּ כָל מוֹעֲדֵי אֵל שֶׁהָיוּ בָּאָרֶץ, כָּל בָּתֵּי וַעַד שֶׁלּוֹ: פְּלִשְׁתִּים הֶחֱרִיבוּ שִׁילֹה, נְבוּכַדְנֶאצַּר הֶחֱרִיב בַּיִת רִאשׁוֹן, וַאֲחֵרִים הֶחֱרִיבוּ בַּיִת שֵׁנִי:\",1,0],[2,136,74,9,\"אוֹתוֹתֵינוּ. שֶׁהִבְטַחְתָּנוּ בְּיַד נְבִיאֶיךָ, אֵין אָנוּ רוֹאִים אוֹתָם בְּיָמִים רַבִּים שֶׁאָנוּ בַּגּוֹלָה. נִתְנַבֵּא אָסָף עַל יְמֵי הַגָּלוּת:\",1,0],[2,136,74,9,\"עַד מָה. עַד מָתַי נִהְיֶה בַּצָּרָה זוֹ?\",2,0],[2,136,74,11,\"מִקֶּרֶב חֵיקְךָ כַלֵּה. הַשְׁלִיכָהּ וְהוֹצֵא אוֹתָהּ מִתּוֹךְ חֵיקְךָ וְהִלָּחֵם בְּאוֹיְבֶיךָ, כַּלֵּה לְשׁוֹן גָּרֵשׁ כְּמוֹ ״כָּלָה גָּרֵשׁ יְגָרֵשׁ״ (שמות יא:א):\",1,0],[2,136,74,12,\"וֵאלֹהִים מַלְכִּי מִקֶּדֶם. וַהֲרֵי אַתָּה תְּשׁוּעָתֵנוּ מִקֶּדֶם:\",1,0],[2,136,74,13,\"רָאשֵׁי תַנִּינִים. הֵם מִצְרַיִם שֶׁנִּקְרְאוּ תַנִּינִים, שֶׁנֶּאֱמַר: ״הַתַּנִּים הַגָּדוֹל וְגוֹ׳״ (יחזקאל כט:ג):\",1,0],[2,136,74,14,\"רָאשֵׁי לִוְיָתָן. פַּרְעֹה נִקְרָא כֵּן, שֶׁנֶּאֱמַר: ״יִפְקֹד ה׳ בְּחַרְבּוֹ הַקָּשָׁה עַל לִוְיָתָן וְגוֹ׳״ (ישעיה כז:א):\",1,0],[2,136,74,14,\"תִּתְּנֶנּוּ מַאֲכָל לְעָם לְצִיִּים. נָתַתָּ מָמוֹנוֹ לְעַם יִשְׂרָאֵל לְאָכְלוֹ, לְצִיִּים לְכִתּוֹת וּצְבָאוֹת שֶׁהוֹצֵאתָ:\",2,0],[2,136,74,14,\"צִיִּים. סִיעוֹת, כְּמוֹ (במדבר כד:כד) ״וְצִים מִיַּד כִּתִּים״ כְּתַרְגּוּמוֹ ״וְסִיעָן״:\",3,0],[2,136,74,15,\"אַתָּה בָקַעְתָּ. לְיִשְׂרָאֵל מִן הַצּוּר מַעְיָנוֹת (שמות יז:ו):\",1,0],[2,136,74,15,\"אַתָּה הוֹבַשְׁתָּ. יַרְדֵּן, שֶׁהוּא נָהָר אֵיתָן (יהושע ג:טו):\",2,0],[2,136,74,16,\"לְךָ יוֹם. גְּאֻלָּתָם שֶׁל יִשְׂרָאֵל:\",1,0],[2,136,74,16,\"אַף לְךָ לָיְלָה. וְעַמְּךָ הָיוּ בְּצָרוֹת הַלָּיְלָה:\",2,0],[2,136,74,16,\"אַתָּה הֲכִינוֹתָ מָאוֹר וָשָׁמֶשׁ. אַתָּה הֲכִינוֹתָ לָהֶם מְאוֹר הַתּוֹרָה:\",3,0],[2,136,74,17,\"אַתָּה הִצַּבְתָּ. לָהֶם כָּל גְּבוּלוֹת אַרְצָם בְּכָל טוֹב:\",1,0],[2,136,74,17,\"קַיִץ וָחֹרֶף אַתָּה יְצַרְתָּם. הֲרֵי זֶה דּוּגְמַת ״שְׁבֻעוֹת חֻקּוֹת קָצִיר יִשְׁמָר לָנוּ״ (ירמיהו ה:כד), לֹא שִׁנִּיתָ לָנוּ סֵדֶר הַשָּׁנִים:\",2,0],[2,136,74,18,\"זְכׇר זֹאת אוֹיֵב וְגוֹ׳. וְאַחֲרֵי שֶׁכָּל תְּשׁוּעָתֵנוּ בְּךָ, זְכׇר זֹאת, אֲשֶׁר הָאוֹיֵב חֵרֵף אוֹתְךָ בְּהַשְׁמִידוֹ אוֹתָנוּ:\",1,0],[2,136,74,19,\"אַל תִּתֵּן לְחַיַּת. לִגְדוּדֵי הָאֻמּוֹת, כְּמוֹ ״וַיֵּאָסְפוּ פְלִשְׁתִּים לַחַיָּה״ (שמואל ב כג:יא):\",1,0],[2,136,74,19,\"נֶפֶשׁ תּוֹרֶךָ. תּוֹר שֶׁלְּךָ. וְיוֹנָתָן תִּרְגֵּם לְשׁוֹן ״תּוֹרִים״ וּ״בְנֵי יוֹנָה״ (ויקרא א:יד). הַתּוֹר הַזֶּה, מִשֶּׁמֵּת הַזָּכָר, בֶּן זוּגָהּ, אֵינָהּ מִזְדַּוֶּגֶת לְאַחֵר. אַף יִשְׂרָאֵל לֹא הֶחֱלִיפוּךָ בְּאֵל אַחֵר, אַף עַל פִּי שֶׁרִחַקְתָּ מֵהֶם וְהָיוּ כְּאַלְמָנָה (שיר השירים רבה א:סג):\",2,0],[2,136,74,19,\"חַיַּת עֲנִיֶּיךָ. נֶפֶשׁ עֲנִיֶּיךָ:\",3,0],[2,136,74,20,\"הַבֵּט לַבְּרִית. אֲשֶׁר כָּרַתָּ אֶת אֲבוֹתֵינוּ:\",1,0],[2,136,74,20,\"נְאוֹת חָמָס. נְוֵה חָמָס, לְשׁוֹן מָדוֹר:\",2,0],[2,136,74,21,\"אַל יָשׁוֹב דַּךְ נִכְלָם. אַל יָשׁוֹב דַּךְ מִלְּפָנֶיךָ, בִּתְפִלָּתוֹ, נִכְלָם:\",1,0],[2,136,74,22,\"חֶרְפָּתְךָ. גִּדּוּפֶיךָ, כְּמוֹ זֹאת אוֹיֵב חֵרֵף:\",1,0],[2,136,75,1,\"אַל תַּשְׁחֵת. אֶת יִשְׂרָאֵל (שו״ט עה:א):\",1,0],[2,136,75,2,\"הוֹדִינוּ לְךָ אֱלֹהִים. עַל הַטּוֹבָה הוֹדִינוּ אַף עַל הָרָעָה, וְקָרוֹב בְּפִינוּ שִׁמְךָ תָּמִיד (ברכות נד.):\",1,0],[2,136,75,2,\"סִפְּרוּ. דּוֹרוֹתֵינוּ נִפְלְאוֹתֶיךָ תָּמִיד:\",2,0],[2,136,75,3,\"כִּי אֶקַּח מוֹעֵד. כְּשֶׁיֵּשׁ לָנוּ יוֹם טוֹב, אֵין אָנוּ עֲסוּקִים בְּנִבּוּל פֶּה וְקַלּוּת רֹאשׁ:\",1,0],[2,136,75,3,\"אֲנִי מֵישָׁרִים אֶשְׁפֹּט. אָנוּ נוֹתְנִין אֶל לִבֵּנוּ לְהַלֶּלְךָ וּלְשַׁבֵּחֲךָ מֵעֵין הַמְּאֹרָע לַיּוֹם:\",2,0],[2,136,75,4,\"נְמוֹגִים אֶרֶץ וְכָל יוֹשְׁבֶיהָ וְגוֹ׳. בְּיוֹם מַתַּן תּוֹרָה, כְּשֶׁהָיוּ נְמוֹגִים הָאָרֶץ וְכָל יוֹשְׁבֶיהָ מִתְּנַאי שֶׁהִתְנֵיתָ עִם מַעֲשֵׂה בְרֵאשִׁית (שבת פח.): אִם לֹא יְקַבְּלוּ וְכוּ׳ תַּחְזְרוּ לְתֹהוּ וָבֹהוּ:\",1,0],[2,136,75,4,\"תִּכַּנְתִּי עַמּוּדֶיהָ. כְּשֶׁאָמַרְתִּי: ״נַעֲשֶׂה וְנִשְׁמַע״ (שמות כד:ז):\",2,0],[2,136,75,5,\"לַהוֹלְלִים. לָרְשָׁעִים הַמְעַרְבְּבִים אֶת יִשְׂרָאֵל:\",1,0],[2,136,75,7,\"כִּי לֹא מִמּוֹצָא. הַשֶּׁמֶשׁ וּמִמַּעֲרָבוֹ, וְלֹא מִן הַמִּדְבָּרוֹת שֶׁאַתֶּם מְפָרְשִׂים בְּשַׁיָּרָא לְהַרְבּוֹת מָמוֹן, לֹא בְכָל אֵלֶּה לְהָרִים קֶרֶן:\",1,0],[2,136,75,8,\"כִּי אֱלֹהִים שׁוֹפֵט. עַל כָּל הָרָעָה שֶׁעֲשִׂיתֶם:\",1,0],[2,136,75,8,\"זֶה יַשְׁפִּיל וְזֶה יָרִים. הַגְּבוֹהִים יַשְׁפִּיל וְהַנְּמוּכִים יָרִים (תנחומא, מטות ט):\",2,0],[2,136,75,9,\"כִּי כוֹס. הַתַּרְעֵלָה בְּיָדוֹ:\",1,0],[2,136,75,9,\"וְיַיִן חָמַר. חָזָק, וִינוֹ״שׁ בְּלַעַ״ז:\",2,0],[2,136,75,9,\"מָלֵא מֶסֶךְ. הַכּוֹס מָלֵא מֶזֶג, לִמְזֹג וּלְהַשְׁקוֹת אֶת כָּל הַגּוֹיִם:\",3,0],[2,136,75,9,\"וַיַּגֵּר מִזֶּה. מִזֶּה הַכּוֹס יָפִיץ וְיִקְלַח אֶת מִשְׁתֵּיהֶם, לְשׁוֹן ״כְּמַיִם מֻגָּרִים״ (מיכה א:ד):\",4,0],[2,136,75,10,\"וַאֲנִי אַגִּיד לְעוֹלָם. מֵאָז וָהָלְאָה, אֶת נִקְמָתוֹ וּגְבוּרָתוֹ:\",1,0],[2,136,75,11,\"וְכָל קַרְנֵי רְשָׁעִים. שֶׁל עֲמָלֶק:\",1,0],[2,136,75,11,\"אֲגַדֵּעַ. כְּעִנְיָן שֶׁנֶּאֱמַר (יחזקאל כה:יד) ״וְנָתַתִּי אֶת נִקְמָתִי בֶאֱדוֹם בְּיַד עַמִּי יִשְׂרָאֵל, יִשְׂרָאֵל יְגַדְּעוּ קֶרֶן עֲמָלֵק וְגוֹ׳״, וְאָז תְּרוֹמַמְנָה קַרְנוֹת צַדִּיק שֶׁל עוֹלָם יִשְׂרָאֵל, שֶׁהֵם שִׁבְחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:\",2,0],[2,136,76,4,\"שָׁמָּה שִׁבַּר רִשְׁפֵי קָשֶׁת. שֶׁל סַנְחֵרִיב וְאוּכְלוּסָיו (מלכים ב יט:לה):\",1,0],[2,136,76,4,\"רִשְׁפֵי קָשֶׁת. אֵין רִשְׁפֵי קֶשֶׁת לְשׁוֹן ״רִשְׁפֵּי אֵשׁ״ (שיר השירים ח:ו) שֶׁאֵין לְשׁוֹן רִשְׁפֵּי אֵשׁ נוֹפְלִים בְּקֶשֶׁת, וְזֶה רָפֵי וְרִשְׁפֵּי אֵשׁ דָּגוּשׁ. וְרִשְׁפֵי קֶשֶׁת לְשׁוֹן ״וּלְחוּמֵי רֶשֶׁף״ (דברים לב:כד) דִּמְתַרְגְּמִינָן ״עוֹף״, ״וּבְנֵי רֶשֶׁף יַגְבִּיהוּ עוּף״ (איוב ה:ז). וְכֵן ״וּמִקְנֵיהֶם לָרְשָׁפִים״ (תהלים עח:מח) לְצִפֳּרִים, וְכֵן וּבְנֵי רֶשֶׁף בְּנֵי עֲפִיפָה הֵם שֵׁדִים יַגְבִּיהוּ לָעוּף. אַף זֶה לְשׁוֹן חִצִּים הַמְעוֹפְפִים כְּעִנְיָן שֶׁנֶּאֱמַר ״וּמֵחֵץ יָעוּף יוֹמָם״ (תהלים צא:ה), שָׁמָּה שִׁבַּר רִשְׁפֵי קָשֶׁת חִצִּים שֶׁהַקֶּשֶׁת מְעוֹפֵף. וְכָל הַמִּזְמוֹר הַזֶּה מְדַבֵּר בְּמַפֶּלֶת סַנְחֵרִיב שֶׁלֹּא מָצִינוּ אוֹיֵב נוֹפֵל בִּירוּשָׁלַיִם אֶלָּא הוּא:\",2,0],[2,136,76,5,\"נָאוֹר אַתָּה אַדִּיר. לְשׁוֹן ״נִאֵר מִקְדָּשׁוֹ״ (איכה ב:ז), ״נֵאַרְתָּ בְרִית עַבְדֶּךָ״ (תהלים פט:מ) – מְנָאֵר אֶת אוֹיְבֶיךָ וְקָמֶיךָ וּמְטַאטְאָן מִן הָעוֹלָם. נָאוֹר עַל שֵׁם מַעֲשָׂיו נִקְרָא, כְּמוֹ ״חַנּוּן״ (שמות כב:כו), וְ״רַחוּם״ (תהלים קיא:ד), וְ״קַנּוֹא״ (יהושע כד:יט) – עַל שֵׁם שֶׁהוּא חוֹנֵן, שֶׁהוּא מְרַחֵם, שֶׁהוּא מְקַנֵּא:\",1,0],[2,136,76,5,\"אַדִּיר מֵהַרְרֵי טָרֶף. חָזָק מֵעֲנָקִים טוֹרְפִים הַגְּבוֹהִים כְּהָרִים, וּלְנֶגְדְּךָ אֵין גְּבוּרָתָם נוֹדַעַת:\",2,0],[2,136,76,6,\"אֶשְׁתּוֹלְלוּ. כְּמוֹ הִשְׁתּוֹלְלוּ; כְּמוֹ ״וְאַחֲרֵי כֵן אֶתְחַבַּר אֲחַזְיָה וְגוֹ׳״ (דברי הימים ב כ:לה) – כְּמוֹ הִתְחַבֵּר. וְנִגְזַר אֶשְׁתּוֹלְלוּ מִגִּזְרַת ״מוֹלִיךְ יוֹעֲצִים שׁוֹלָל״ (איוב יב:יז), וְהוּא לְשׁוֹן מִשְׁגֶּה וְ״שָׁלוּ״ (דניאל ג:כט), כְּשׁוֹטִים שׁוֹגִים; וְהַתָּי״ו נוֹפֶלֶת בִּלְשׁוֹן הַמִּתְפַּעֵל בְּאֶמְצַע הַתֵּיבָה, בְּכָל תֵּיבָה שֶׁתְּחִלָּתָהּ שִׁי״ן:\",1,0],[2,136,76,6,\"נָמוּ שְׁנָתָם. נִרְדְּמוּ בְּשֵׁינָה, לְשׁוֹן ״תְּנוּמָה״ (תהלים קלב:ד):\",2,0],[2,136,76,6,\"וְלֹא מָצְאוּ יְדֵיהֶם. וְכֹחָם, כְּשֶׁבָּאתָ לִפָּרַע מֵהֶם:\",3,0],[2,136,76,7,\"נִרְדָּם וְרֶכֶב וָסוּס. וָי״ו שֶׁל וְרֶכֶב טְפֵלָה הִיא, כְּמוֹ ״אֵלֶּה בְנֵי צִבְעוֹן וְאַיָּה וַעֲנָה״ (בראשית לו:כד) – וָי״ו שֶׁל וְאַיָּה טְפֵלָה הִיא:\",1,0],[2,136,76,8,\"מֵאָז אַפֶּךָ. מִשָּׁעָה שֶׁאַתָּה כּוֹעֵס:\",1,0],[2,136,76,9,\"מִשָּׁמַיִם הִשְׁמַעְתָּ דִּין. כְּשֶׁנִּתְנַבֵּא יְשַׁעְיָה עַל פּוּרְעָנוּתוֹ שֶׁל סַנְחֵרִיב, וְנִתְקַיֵּם בּוֹ: אֶרֶץ יִשְׂרָאֵל, שֶׁיָּרְאָה מִמֶּנּוּ וּמֵאוּכְלוּסָיו, אָז שָׁקָטָה:\",1,0],[2,136,76,10,\"בְּקוּם לַמִּשְׁפָּט אֱלֹהִים. לַעֲשׂוֹת מִשְׁפָּט מֵאוֹיְבָיו, לְהוֹשִׁיעַ חִזְקִיָּהוּ וְסִיעָתוֹ:\",1,0],[2,136,76,11,\"כִּי חֲמַת אָדָם תּוֹדֶךָּ. כַּעֲסָן שֶׁל רְשָׁעִים גּוֹרֵם שֶׁהַבְּרִיּוֹת מוֹדִים לְהַקָּדוֹשׁ בָּרוּךְ הוּא, כְּשֶׁהֵם מַרְאִין כַּעֲסָם וְהַקָּבָּ״ה נִפְרָע מֵהֶם הַכֹּל מְקַלְּסִין לְפָנָיו, וְאַף הֵם עַצְמָם מְקַלְּסִין לְפָנָיו כְּשֶׁרוֹאִין שֶׁאֵין כַּעֲסָן כְּלוּם, כְּמוֹ שֶׁמָּצִינוּ בִּנְבוּכַדְנֶצַּר כְּשֶׁהִשְׁלִיךְ חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה לְכִבְשַׁן הָאֵשׁ מַה נֶּאֱמַר שָׁם ״יְהֵא שְׁמֵיהּ דֶּאֱלָהָא מְבָרַךְ וְגוֹ׳״ (דניאל ג:כח). וְעַל יְדֵי כֵן שְׁאֵרִית הַחֵמֹת תַּחְגֹּר תְּעַכֵּב וְתַחְדֹּל, שְׁאָר הָרְשָׁעִים מְעֻכָּבִים וְנִמְנָעִים מִלְּהַרְאוֹת גַּאֲוָתָם וַחֲמָתָם. תַּחְגֹּר לְשׁוֹן עֲכָבָה בִּלְשׁוֹן מִשְׁנָה (בכורות לז:): פְּגִימַת הַסַּכִּין כְּדֵי שֶׁתַּחְגֹּר בּוֹ הַצִּפֹּרֶן. וְשָׁמַעְתִּי מִשְּׁמוֹ שֶׁל רַבִּי אֶלְעָזָר הַגָּאוֹן בַּר׳ יִצְחָק שֶׁהָיָה מֵבִיא הַמִּקְרָא הַזֶּה עֵדוּת לְאוֹתָהּ מִשְׁנָה. וְיֵשׁ עוֹד לִפְתֹּר חֲגִירָה זוֹ כְּמַשְׁמָעָהּ לְשׁוֹן חֲגוֹרָה, וּפֵרוּשׁוֹ לְךָ נָאֶה לַחֲגֹר חֵמָה וְלַעֲטוֹת קִנְאָה כִּי הַכֹּחַ וְהַיְּכֹלֶת שֶׁלְּךָ, וּלְשׁוֹן שְׁאֵרִית זֶה הוּא מֵאַחַר שֶׁחֲמַת אָדָם אֵינוֹ כְּלוּם נִשְׁאֲרוּ כָּל חֲגוֹרוֹת חֵמָה לְךָ:\",1,0],[2,136,76,12,\"נִדְרוּ וְשַׁלְּמוּ. נִדְרֵיכֶם:\",1,0],[2,136,76,12,\"כָּל סְבִיבָיו. הַשּׁוֹמְעִים תְּשׁוּעָה זוֹ, וְכֵן עָשׂוּ, כְּמוֹ שֶׁכָּתוּב (ישעיהו יט:יח) ״יִהְיוּ חָמֵשׁ עָרִים בְּאֶרֶץ מִצְרַיִם מְדַבְּרוֹת שְׂפַת כְּנַעַן וְנִשְׁבָּעוֹת לַה׳ צְבָאוֹת״:\",2,0],[2,136,76,12,\"יוֹבִילוּ שַׁי לַמּוֹרָא. לָמָּה? לְפִי שֶׁבְּעֵת חֶפְצוֹ:\",3,0],[2,136,76,13,\"יִבְצֹר רוּחַ. גַּסָּה שֶׁל נְדִיבִים, מְמַעֵט גַּאֲוָתָם. יִבְצֹר יְמַעֵט, כְּמוֹ (בראשית יא:ו) ״לֹא יִבָּצֵר מֵהֶם״:\",1,0],[2,136,77,1,\"עַל יְדוּתוּן. עַל הַדָּתוֹת וְעַל הַדִּינִין הָעוֹבְרִים עַל יִשְׂרָאֵל:\",1,0],[2,136,77,3,\"יָדִי. מַכָּתִי:\",1,0],[2,136,77,3,\"לַיְלָה נִגְּרָה. בַּגָּלוּת זֶה שֶׁהוּא כְּלַיְלָה, הִיא נִגְּרָה לֵחָה וּמָרָה:\",2,0],[2,136,77,3,\"וְלֹא תָפוּג. וְלֹא תִדְמֶה נִגְּרָתָהּ:\",3,0],[2,136,77,4,\"אֶזְכְּרָה אֱלֹהִים. הַחֶסֶד שֶׁהָיָה רָגִיל לַעֲשׂוֹת לִי בִּימֵי חִבָּתִי:\",1,0],[2,136,77,4,\"אָשִׂיחָה. בְּאוֹתָן חֲסָדִים וְטוֹבוֹת:\",2,0],[2,136,77,4,\"וְתִתְעַטֵּף רוּחִי. פַּשְׁמִי״ר בְּלַעַ״ז:\",3,0],[2,136,77,5,\"אָחַזְתָּ שְׁמֻרוֹת עֵינָי. שְׁמוּרוֹת לְשׁוֹן אַשְׁמוּרוֹת הַלַּיְלָה, שֶׁאָדָם נֵעוֹר מִשְּׁנָתוֹ וְדַעְתּוֹ מְיֻשֶּׁבֶת וְלִבּוֹ חוֹזֵר עָלָיו. וַאֲנִי אֵינִי כֵּן בַּלַּיְלָה זוֹ שֶׁל גָּלוּת: תָּמִיד עֵינַי נִדְבָּקוֹת, כְּאָדָם נִרְדָּם מֵאֹטֶם לֵב. בַּצָּרוֹת שֶׁאֲנִי רוֹאֶה נִפְעֲמָה רוּחִי וְאֵין הַדִּבּוּר בִּי:\",1,0],[2,136,77,6,\"חִשַּׁבְתִּי יָמִים מִקֶּדֶם. לִזְכֹּר הַחֲסָדִים שֶׁעָשִׂיתָ עִם אֲבוֹתֵינוּ:\",1,0],[2,136,77,7,\"אֶזְכְּרָה נְגִינָתִי בַּלָּיְלָה. בִּימֵי הַגָּלוּת הַזֶּה הַדּוֹמֶה לַלַּיְלָה אֲנִי זוֹכֵר אֶת נְגִינוֹתַי שֶׁהָיִיתִי מְנַגֵּן בִּימֵי קֶדֶם בְּבֵית הַמִּקְדָּשׁ:\",1,0],[2,136,77,7,\"עִם לְבָבִי אָשִׂיחָה. אֲנִי מְחַשֵּׁב וְרוּחִי מְחַפֵּשׂ (פסיקתא רבתי יז), מַה הִיא כֵּן מִדָּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וַאֲנִי תָּמֵהַּ: הַלְּעוֹלָמִים יִזְנַח?\",2,0],[2,136,77,9,\"הֶאָפֵס. שֶׁמָּא כָּלָה חַסְדּוֹ?\",1,0],[2,136,77,9,\"גָּמַר אֹמֶר. גְּזֵרַת עוֹלָם שֶׁלֹּא יָשׁוּב מֵחֲרוֹנוֹ עוֹד?\",2,0],[2,136,77,10,\"הֲשָׁכַח חַנּוֹת. לִהְיוֹת חוֹנֵן, חַנּוֹת כְּמוֹ ״עֲשׂוֹת״ (בראשית ב:ד) ״רְאוֹת״ (שמות י:כח), לָשׁוֹן אַחֵר: חַנּוֹת חֲנִינוֹת:\",1,0],[2,136,77,10,\"אִם קָפַץ בְּאַף רַחֲמָיו סֶלָה. לְשׁוֹן ״לֹא תִקְפֹּץ יָדְךָ״ (דברים טו:ז), כְּלוֹמַר אִם סָגַר הָרַחֲמִים לְעוֹלָם בִּשְׁבִיל הַחֵמָה:\",2,0],[2,136,77,11,\"וָאֹמַר חַלּוֹתִי הִיא. מַחֲשַׁבְתִּי אוֹמֶרֶת כִּי אֵין זֹאת אֶלָּא לְהַחֲלוֹתִי וּלְיָרְאֵנִי לָשׁוּב אֵלָיו:\",1,0],[2,136,77,11,\"חַלּוֹתִי. כְּמוֹ לְחַלּוֹתִי, לְשׁוֹן חֹלִי וְחִיל:\",2,0],[2,136,77,11,\"שְׁנוֹת יְמִין עֶלְיוֹן. אֶת אֲשֶׁר נִשְׁתַּנֵּית יְמִין עֶלְיוֹן, שֶׁהָיְתָה נֶאְדָּרִי בַּכֹּחַ רוֹעֶצֶת אוֹיֵב (שמות טו:ו), וְעַכְשָׁיו הֵשִׁיב אָחוֹר יְמִינוֹ (איכה ב:ג):\",3,0],[2,136,77,13,\"וְהָגִיתִי בְכָל פָּעֳלֶךָ. שֶׁעָשִׂיתָ לָנוּ כְּבָר:\",1,0],[2,136,77,14,\"בַּקֹּדֶשׁ דַּרְכֶּךָ. דֶּרֶךְ מִדָּתְךָ לְקַדֵּשׁ אֶת שִׁמְךָ בָּעוֹלָם, לַעֲשׂוֹת דִּין בָּרְשָׁעִים:\",1,0],[2,136,77,17,\"רָאוּךָ מַיִם. רַבִּים כְּשֶׁנִּגְלֵיתָ עַל הַיָּם (שמות יד:כא):\",1,0],[2,136,77,18,\"זֹרְמוּ מַיִם עָבוֹת. שְׁחָקִים נָטְפוּ זֶרֶם מַיִם עָבִים:\",1,0],[2,136,77,18,\"חֲצָצֶיךָ. כְּמוֹ חִצֶּיךָ:\",2,0],[2,136,77,19,\"בַּגַּלְגַּל. כְּמוֹ כַּגַּלְגַּל, קוֹל רַעַמְךָ כַּגַּלְגַּל עַל הַיָּם לָהוּם אֶת מַחֲנֵה מִצְרַיִם (שמות יד:כד):\",1,0],[2,136,77,20,\"וְעִקְּבוֹתֶיךָ לֹא נוֹדָעוּ. אֵין הַפְּסִיעוֹת נִכָּרוֹת עַל הַמַּיִם. וְעִקְּבוֹתֶיךָ טְרַצְ״שׁ בְּלַעַ״ז:\",1,0],[2,136,78,2,\"בְּמָשָׁל פִּי. הֵם דִּבְרֵי תוֹרָה (שבת קמה.):\",1,0],[2,136,78,4,\"לֹא נְכַחֵד מִבְּנֵיהֶם. וְגַם אֲנוּ לֹא נְכַחֵד מִבְּנֵיהֶם שֶׁל אֲבוֹתֵינוּ מִלְּהוֹדִיעָם מַה שֶּׁסִּפְּרוּ לָנוּ:\",1,0],[2,136,78,7,\"כִּסְלָם. תּוֹחַלְתָּם, וְכֵן ״אִם שַׂמְתִּי זָהָב כִּסְלִי״ (איוב לא:כד):\",1,0],[2,136,78,8,\"כַּאֲבוֹתָם. שֶׁהָיוּ בְּמִצְרַיִם וּבַמִּדְבָּר:\",1,0],[2,136,78,9,\"בְּנֵי אֶפְרַיִם. שֶׁיָּצְאוּ מִמִּצְרַיִם בִּזְרוֹעַ לִפְנֵי הַקֵּץ וּבָטְחוּ בִּגְבוּרָתָם וּבְחִצֵּיהֶם, וְסוֹפָם הָפְכוּ לָנוּס בְּיוֹם קְרָב, כַּמְפֹרָשׁ בְּדִבְרֵי הַיָּמִים: ״וַיַּהַרְגוּם אַנְשֵׁי גַת הַנּוֹלָדִים בָּאָרֶץ״ (דברי הימים א ז:כא):\",1,0],[2,136,78,9,\"רוֹמֵי. מַשְׁלִיכִין וְזוֹרְקִין, כְּמוֹ ״רָמָה בַיָּם״ (שמות טו:א):\",2,0],[2,136,78,12,\"נֶגֶד אֲבוֹתָם עָשָׂה פֶלֶא. אַחֲרֵי כֵן, כְּשֶׁהִגִּיעַ הַקֵּץ, אַף הֵם וַיּוֹסִיפוּ לַחֲטֹא לוֹ, כְּמוֹ שֶׁמְּסַיֵּם וְהוֹלֵךְ:\",1,0],[2,136,78,12,\"נֶגֶד אֲבוֹתָם. אַבְרָהָם, יִצְחָק וְיַעֲקֹב בָּאוּ עַל הַיָּם, וְהֶרְאָם הַקָּדוֹשׁ בָּרוּךְ הוּא הֵיאַךְ הוּא גּוֹאֵל אֶת בְּנֵיהֶם (בראשית רבה צב:ב):\",2,0],[2,136,78,13,\"כְּמוֹ נֵד. תֵּל גָּבוֹהַּ, כְּדִמְתַרְגְּמִינָן ״נִצְּבוּ כְמוֹ נֵד״ (שמות טו:ח): ״קָמוּ כְשׁוּר״ (תרגום אונקלוס):\",1,0],[2,136,78,15,\"יְבַקַּע צוּרִים. ״וְהִכִּיתָ בַצּוּר וְגוֹ׳״ (שמות יז:ו):\",1,0],[2,136,78,15,\"וַיַּשְׁקְ כִּתְהוֹמוֹת רַבָּה. אַף כְּשֶׁהָיוּ הוֹלְכִים בְּתוֹךְ הַיָּם שֶׁמֵּימָיו מְלוּחִים, הִמְתִּיק לָהֶם מַעְיָנוֹת בְּתוֹךְ הַתְּהוֹם:\",2,0],[2,136,78,16,\"וַיּוֹרֶד כַּנְּהָרוֹת מָיִם. שֶׁהָיוּ נוֹזְלִין מִן הַבְּאֵר, וְהַנְּשִׂיאִים הָיוּ עוֹשִׂין שִׂרְטוּט בְּמַשְׁעֲנוֹתָם, וְהַמַּיִם נִמְשָׁכִים אַחֲרֵיהֶם לְכָל חֲנִיַּת שֵׁבֶט וָשֵׁבֶט, כְּעִנְיָן שֶׁנֶּאֱמַר ״בִּמְחֹקֵק בְּמִשְׁעֲנֹתָם״ (במדבר כא:יח); כְּמוֹ שֶׁמְּפֹרָשׁ בְּאַרְבָּעִים וְתֵשַׁע מִדּוֹת (תנחומא, חקת כא):\",1,0],[2,136,78,17,\"לְמָרוֹת. לְהַקְנִיט, כְּמוֹ ״מַמְרִים הֱיִיתֶם״ (דברים ט:ז):\",1,0],[2,136,78,20,\"שְׁאֵר. בָּשָׂר:\",1,0],[2,136,78,21,\"וְאֵשׁ נִשְּׂקָה בְיַעֲקֹב. כְּמוֹ ״וּבָעֲרוּ וְהִשִּׂיקוּ״ (יחזקאל לט:ט), שֶׁהוּא לְשׁוֹן הֶסֵּק וּתְבֵעָרָה. כְּדִכְתִיב ״וַתִּבְעַר בָּם אֵשׁ ה׳״ (במדבר יא:א):\",1,0],[2,136,78,25,\"לֶחֶם אַבִּירִים. לַחְמָם שֶׁל מַלְאָכִים, דָּבָר אַחֵר: אַבִּירִים אֵיבָרִים, שֶׁהָיָה נִבְלָע בְּכָל הָאֵיבָרִים וְלֹא הָיוּ צְרִיכִים לִנְקָבֵיהֶם (יומא עה:):\",1,0],[2,136,78,26,\"יַסַּע קָדִים. ״וְרוּחַ נָסַע מֵאֵת ה׳ וַיָּגָז שַׂלְוִים״ (במדבר יא:לא):\",1,0],[2,136,78,27,\"שְׁאֵר. בָּשָׂר:\",1,0],[2,136,78,30,\"לֹא זָרוּ מִתַּאֲוָתָם. לֹא נַעֲשׂוּ זָרִים מִתַּאֲוָתָם, כִּי כָּל תַּאֲוָתָם הִשִּׂיגוּ:\",1,0],[2,136,78,30,\"עוֹד אָכְלָם בְּפִיהֶם. וְאַף ה׳ חָרָה בָּעָם (במדבר יא:לג). דָּבָר אַחֵר לֹא זָרוּ מִתַּאֲוָתָם לֹא נִתְרַחֲקוּ מִתַּאֲוָתָם עַד שֶׁבָּאָת לָהֶם הַפּוּרְעָנוּת:\",2,0],[2,136,78,31,\"וּבַחוּרֵי יִשְׂרָאֵל. נִבְחָרִים שֶׁבָּהֶם, ״וְהָאֲסַפְסוּף״ (במדבר יא:ד) הֵם הַזְּקֵנִים, שֶׁנֶּאֱמַר בָּהֶם ״אֶסְפָה לִי״ (במדבר יא:טז):\",1,0],[2,136,78,34,\"אִם הֲרָגָם וּדְרָשׁוּהוּ וְגוֹ׳. אַף הִיא לֹא בֶאֱמֶת, אֶלָּא בְּפִתּוּי בַּפֶּה, וְכִזְּבוּ בִּלְשׁוֹנָם:\",1,0],[2,136,78,37,\"וְלִבָּם לֹא. כְּפִיהֶם נָכוֹן, וְאַף עַל פִּי כֵן וְהוּא רַחוּם לָהֶם וּמְכַפֵּר עֲוֹנָם תָּמִיד וְלֹא הִשְׁחִיתָם:\",1,0],[2,136,78,38,\"וְהִרְבָּה. פְּעָמִים רַבּוֹת:\",1,0],[2,136,78,38,\"לְהָשִׁיב אַפּוֹ. מֵהֶם, וְאַף אִם נִפְרָע מֵהֶם, לֹא הֵעִיר עֲלֵיהֶם כָּל חֲמָתוֹ, כִּי אִם מְעַט מְעַט. לְפִי שֶׁזָּכַר כִּי בָשָׂר הֵמָּה, וְיֵצֶר הָרָע טָמוּן בְּלִבָּם, וְהוּא רוּחַ הוֹלֵךְ – כְּשֶׁיָּמוּתוּ, וְלֹא יָשׁוּב אוֹתוֹ רוּחַ בָּהֶם לָעוֹלָם הַבָּא: כְּשֶׁיִּחְיוּ, אֵין יֵצֶר הָרָע שׁוֹלֵט בָּהֶם. וְלֹא יִתָּכֵן לְפָרֵשׁ רוּחַ הוֹלֵךְ וְלֹא יָשׁוּב – רוּחָם שֶׁל חַיִּים בָּהֶם, שֶׁאִם אָמַרְתָּ כֵּן, כָּפַרְתָּ בִּתְחִיַּת הַמֵּתִים. וְכֵן מְפֹרָשׁ בְּאַגָּדַת תְּהִלִּים:\",2,0],[2,136,78,40,\"כַּמָּה. פְּעָמִים יַמְרוּהוּ תָּמִיד בַּמִּדְבָּר:\",1,0],[2,136,78,41,\"הִתְווּ. לְשׁוֹן סִימָן, כְּמוֹ ״וְהִתְוִיתָ תָּו״ (יחזקאל ט:ד). וְסִימָן הוּא לְשׁוֹן מוֹפֵת וְנִסָּיוֹן. בִּקְשׁוּ מִמֶּנּוּ אוֹת וְסִימָן: ״הֲיֵשׁ ה׳ בְּקִרְבֵּנוּ אִם אָיִן״ (שמות יז:ז):\",1,0],[2,136,78,45,\"וְתַשְׁחִיתֵם. שׁוֹמְטִין אֶת בֵּיצֵיהֶם (שמות רבה י:ד):\",1,0],[2,136,78,47,\"בַּחֲנָמַל. שֵׁם אַרְבֶּה, וּמִדְרָשׁוֹ : בָּא חָן וּמָל, הָיָה מוֹלֵל אֶת יֶרֶק הָעֵץ וְהָעֵשֶׂב וְאוֹכְלוֹ:\",1,0],[2,136,78,48,\"וַיַּסְגֵּר לַבָּרָד בְּעִירָם. כְּשֶׁהִתְחִיל הַבָּרָד לֵירֵד, הַמִּצְרִי מַבְרִיחַ צֹאנוֹ לַבַּיִת, וְהַבָּרָד נַעֲשָׂה לְמוּלוֹ כְּמִין כּוֹתֶל, וְהַמִּצְרִי שׁוֹחֲטוֹ וְנוֹתְנוֹ עַל כְּתֵיפוֹ לְהוֹלִיכוֹ לַבַּיִת וּלְאָכְלוֹ, וְהָעוֹף בָּא וְנוֹטְלוֹ הֵימֶנּוּ. וְזֶה וּמִקְנֵיהֶם לָרְשָׁפִים לָעוֹפוֹת, כְּמוֹ ״וּבְנֵי רֶשֶׁף יַגְבִּיהוּ עוּף״ (איוב ה:ז). זֶה מִדְרָשׁוֹ. וּלְפִי פְשׁוּטוֹ: לָרְשָׁפִים רִשְׁפֵּי אֵשׁ, כְּדִכְתִיב ״וְאֵשׁ מִתְלַקַּחַת בְּתוֹךְ הַבָּרָד״ (שמות ט:כד):\",1,0],[2,136,78,50,\"יְפַלֵּס נָתִיב לְאַפּוֹ. אַף עַל פִּי שֶׁבְּאַף נִשְׁתַּלְּחוּ הַמַּכּוֹת לֹא שִׁמְּשׁוּ אֶלָּא שְׁלִיחוּתָם, מַה שֶּׁנִּצְטַוּוּ לְהָמִית הֵמִיתוּ וְלֹא הַכֹּל, בִּנְתִיבוֹתָם הָלְכוּ. בְּפֵרוּשִׁים אֲחֵרִים מָצָאתִי כֵּן: יְפַלֵּס נָתִיב לְאַפּוֹ כְּשֶׁהִכָּה כָל בְּכוֹר בְּמִצְרַיִם (שמות יב:כט), הוֹרָה דֶּרֶךְ לַמַּשְׁחִית בְּאַף לָבוֹא אֶל בָּתֵּי מִצְרַיִם וְלֹא לְבָתֵּי בְּנֵי יִשְׂרָאֵל (שמות יב:כג):\",1,0],[2,136,78,50,\"וְחַיָּתָם. גּוּפָם:\",2,0],[2,136,78,55,\"וַיְגָרֶשׁ מִפְּנֵיהֶם. שֶׁבַע אֻמּוֹת:\",1,0],[2,136,78,55,\"בְּאָהֳלֵיהֶם. שֶׁל גּוֹיִם:\",2,0],[2,136,78,56,\"וַיְנַסּוּ וַיַּמְרוּ. בִּימֵי הַשּׁוֹפְטִים:\",1,0],[2,136,78,57,\"כְּקֶשֶׁת רְמִיָּה. שֶׁאֵינָהּ זוֹרֶקֶת חֵץ לְמָקוֹם שֶׁהַמּוֹרֶה חָפֵץ:\",1,0],[2,136,78,61,\"וַיִּתֵּן לַשְּׁבִי עֻזּוֹ. מָסַר הָאָרוֹן וְהַלּוּחוֹת בְּיַד פְּלִשְׁתִּים (שמואל א ד:יא):\",1,0],[2,136,78,63,\"בַּחוּרָיו אָכְלָה אֵשׁ. עֶבְרָתוֹ:\",1,0],[2,136,78,63,\"לֹא הוּלָּלוּ. לֹא נִכְלְלוּ לְאַפִּרְיוֹן וְחוּפָּה, שֶׁמֵּתוּ הַבַּחוּרִים בַּמִּלְחָמָה:\",2,0],[2,136,78,63,\"הוּלָּלוּ. לְשׁוֹן הִלּוּלָא בַּאֲרָמִית (ברכות לא.), וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ עַל נָדָב וַאֲבִיהוּא, וְאֵין לִבִּי מִתְיַשֵּׁב לְפָרְשׁוֹ כֵּן, שֶׁהֲרֵי כְּבָר הִתְחִיל בְּמִשְׁכַּן שִׁילֹה:\",3,0],[2,136,78,64,\"כֹּהֲנָיו בַּחֶרֶב נָפָלוּ. חָפְנִי וּפִינְחָס (שמואל א ד:יא):\",1,0],[2,136,78,64,\"וְאַלְמְנוֹתָיו לֹא תִבְכֶּינָה. אַף אַלְמְנָתוֹ לֹא נִיתְּנָה לִבְכּוֹתוֹ, שֶׁאַף הִיא מֵתָה בְּיוֹם הַשְּׁמוּעָה, כְּמוֹ שֶׁנֶּאֱמַר: ״וַתִּכְרַע וַתֵּלֶד כִּי נֶהֶפְכוּ עָלֶיהָ צִירֶיהָ״ (שמואל א ד:יט):\",2,0],[2,136,78,65,\"מִתְרוֹנֵן. מִתְעוֹרֵר וּמִתְגַּבֵּר בְּדִבּוּר לְהָקִיץ מִיֵּינוֹ, מִתְרוֹנֵן לְשׁוֹן רִנָּה הוּא:\",1,0],[2,136,78,66,\"וַיַּךְ צָרָיו אָחוֹר. מַכּוֹת אֲחוֹרַיִם בָּעֳפוֹלִים וּבַטְּחוֹרִים (שמואל א ה:ו), וְהוּא חֶרְפַּת גִּדּוּף לָהֶם עוֹלָמִית:\",1,0],[2,136,78,67,\"וַיִּמְאַס בְּאֹהֶל יוֹסֵף. הוּא שִׁילֹה שֶׁהוּא בְּחֶלְקוֹ שֶׁל יוֹסֵף (זבחים קיח.):\",1,0],[2,136,78,69,\"וַיִּבֶן כְּמוֹ רָמִים מִקְדָּשׁוֹ וְגוֹ׳. כְּמוֹ שָׁמַיִם וָאָרֶץ שֶׁנֶּאֶמְרוּ בָּהֶם שְׁתֵּי יָדַיִם, שֶׁנֶּאֱמַר ״אַף יָדִי יָסְדָה אֶרֶץ וִימִינִי טִפְּחָה שָׁמָיִם״ (ישעיה מח:יג), אַף בֵּית הַמִּקְדָּשׁ בִּשְׁתֵּי יָדַיִם שֶׁנֶּאֱמַר ״כּוֹנְנוּ יָדֶיךָ״ (שמות טו:יז). דָּבָר אַחֵר: כְּמוֹ רָמִים מִקְדָּשׁוֹ כְּאֶרֶץ יְסָדָהּ. מַה שָּׁמַיִם וָאָרֶץ אֵין לָהֶם חֲלִיפִין, אַף מִקְדָּשׁ אֵין לוֹ חֲלִיפִין לְהַשְׁרוֹת שָׁם שְׁכִינָה:\",1,0],[2,136,78,70,\"מִמִּכְלְאוֹת צֹאן. דִּירֵי צֹאן, כְּמוֹ ״גָּזַר מִמִּכְלָה צֹאן״ (חבקוק ג:יז):\",1,0],[2,136,78,71,\"מֵאַחַר עָלוֹת הֱבִיאוֹ. שֶׁהָיָה רוֹעֶה לְאָבִיו הַצֹּאן הַמְּנִיקוֹת, שֶׁהָיָה רַחֲמָנִי וּמוֹצִיא הַגְּדָיִּים תְּחִלָּה וּמַאֲכִילָן רָאשֵׁי עֲשָׂבִים הָעֶלְיוֹנִים שֶׁהֵם רַכִּים, וּמוֹצִיא הַתְּיָשִׁים אַחֲרֵיהֶם וְאוֹכְלִין אֶמְצַע הָעֲשָׂבִים, וְאַחַר כָּךְ מוֹצִיא הַזְּקֵנוֹת וְאוֹכְלוֹת הַשָּׁרָשִׁים. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: רָאוּי הוּא זֶה לִהְיוֹת רוֹעֶה אֶת עַמִּי:\",1,0],[2,136,79,1,\"לְעִיִּים. לְגַלִּים. וּמַהוּ מִזְמוֹר, וַהֲלֹא קִינָה הִיא?! אֶלָּא לְפִי שֶׁנֶּאֱמַר ״כִּלָּה ה׳ אֶת חֲמָתוֹ״ (איכה ד:יא), וּבַמֶּה כִּלָּה? ״וַיַּצֶּת אֵשׁ בְּצִיּוֹן״ (איכה ד:יא) – מִזְמוֹר וְשִׁיר הוּא, שֶׁשָּׁפַךְ חֲמָתוֹ עַל עֵצִים וְעַל הָאֲבָנִים וְלֹא עָשָׂה כְּלָיָה בְּבָנָיו:\",1,0],[2,136,79,2,\"בְּשַׂר חֲסִידֶיךָ. וַהֲלֹא רְשָׁעִים הָיוּ? אֶלָּא מִשֶּׁקִּבְּלוּ פֻּרְעָנוּתָם, הֲרֵי הֵם חֲסִידִים. וְכֵן הוּא אוֹמֵר ״וְנִקְלָה אָחִיךָ״ (דברים כה:ג) – כֵּיוָן שֶׁלָּקָה, אָחִיךָ הוּא. כֵּן מְפֹרָשׁ בָּאַגָּדָה:\",1,0],[2,136,79,4,\"וָקֶלֶס. לְשׁוֹן דִּבָּה, לְדַבֵּר בָּם, כְּמוֹ ״לְמָשָׁל״ (דברים כח:לז):\",1,0],[2,136,79,5,\"עַד מָה. עַד מָתַי?\",1,0],[2,136,79,5,\"תֶּאֱנַף. תִּקְצֹף:\",2,0],[2,136,79,5,\"קִנְאָתֶךָ. חֲמָתְךָ שֶׁאַתָּה מְקַנֵּא לְהִנָּקֵם, לְשׁוֹן ״אֵל קַנָּא״ (שמות כ:ה). אִינְפְרִינְמַנְ״ט בְּלַעַ״ז:\",3,0],[2,136,79,11,\"הוֹתֵר. פַּתַּח אֲסִירִים מִמַּסְגֵּר שֶׁלָּהֶם, כְּמוֹ ״מַתִּיר אֲסוּרִים״ (תהלים קמו:ז), ״שָׁלַח מֶלֶךְ וַיַּתִּירֵהוּ״ (תהלים קה:כ):\",1,0],[2,136,79,11,\"בְּנֵי תְמוּתָה. בְּנֵי הַנֶּהֱרֶגֶת עָלֶיךָ, תְמוּתָה אִינְמוֹרִינִיד״א בְּלַעַ״ז, וְיֵשׁ דּוּגְמָתוֹ בִּלְשׁוֹן חֲכָמִים: מוּטָב שֶׁיֹּאכְלוּ יִשְׂרָאֵל בְּשַׂר תְּמוּתָה שְׁחוּטָה וְאַל יֹאכְלוּ בְּשַׂר תְּמוּתָה נְבֵלָה, וּפֵרוּשׁוֹ בְּשַׂר מְסֻכֶּנֶת שֶׁשְּׁחָטָהּ בְּמַסֶּכֶת קִדּוּשִׁין (קדושין כא:-כב.):\",2,0],[2,136,80,1,\"אֶל שׁוֹשַׁנִּים. אֶל יִשְׂרָאֵל (שיר השירים ב:ב):\",1,0],[2,136,80,1,\"עֵדוּת לְאָסָף מִזְמוֹר. מִזְמוֹר שֶׁל עֵדוּת, שֶׁרָמַז לָהֶם בּוֹ שָׁלֹשׁ גָּלֻיּוֹת וְהִתְפַּלֵּל עֲלֵיהֶם, שֶׁהֲרֵי נֶאֱמַר בְּמִזְמוֹר זֶה שָׁלֹשׁ פְּעָמִים הֲשִׁיבֵנוּ הָאֵר פָּנֶיךָ וְנִוָּשֵׁעָה; וְרָמַז לָהֶם בּוֹ צָרוֹת הָעֲתִידוֹת לָבֹא לָהֶם בִּימֵי בֵּית יֵהוּא מִמַּלְכֵי אֲרָם, שֶׁנֶּאֱמַר (מלכים ב יג:ז) בִּימֵי יְהוּא ״כִּי אִבְּדָם מֶלֶךְ אֲרָם וַיְשִׂימֵם כֶּעָפָר לָדוּשׁ״:\",2,0],[2,136,80,2,\"רֹעֵה יִשְׂרָאֵל. מַנְהִיגָם וּפַרְנָס שֶׁלָּהֶם:\",1,0],[2,136,80,2,\"יוֹסֵף. וְכָל יִשְׂרָאֵל נִקְרָאִים עַל שֵׁם יוֹסֵף, לְפִי שֶׁהוּא פִּרְנְסָם וְכִלְכְּלָם בִּימֵי הָרָעָב (בראשית מז:יב):\",2,0],[2,136,80,2,\"יוֹשֵׁב הַכְּרוּבִים. כְּמוֹ שֶׁנֶּאֱמַר ״וְנוֹעַדְתִּי לְךָ שָׁם וְגוֹ׳״ (שמות כה:כב):\",3,0],[2,136,80,2,\"הוֹפִיעָה. הַרְאֵה גְּבוּרָתְךָ:\",4,0],[2,136,80,3,\"לִפְנֵי אֶפְרַיִם וּבִנְיָמִן וּמְנַשֶּׁה. כְּשֶׁיִּהְיוּ צְרִיכִים לִתְשׁוּעָתְךָ, אַף עַל פִּי שֶׁהֵם רְשָׁעִים וְאֵינָם כְּדַי, עוֹרְרָה גְּבוּרָתֶךָ לָהֶם. וְלָמָּה? כִּי לְכָה לִישׁוּעָתָה לָּנוּ, לְךָ נָאֶה וְעָלֶיךָ לְהוֹשִׁיעַ, בֵּין חַיָּבִים וּבֵין זַכָּאִים. כְּמוֹ שֶׁנֶּאֱמַר לְמֹשֶׁה בְּמִצְרַיִם: (שמות ג:ז) ״רָאֹה רָאִיתִי אֶת עֳנִי עַמִּי״. שְׁתֵּי רְאִיּוֹת הַלָּלוּ לָמָּה? רוֹאֶה אֲנִי שֶׁהֵם עֲתִידִים לְהַכְעִיסֵנִי, וְאַף עַל פִּי כֵן רָאִיתִי אֶת עָנְיָם, מִפְּנֵי הַשְּׁבוּעָה שֶׁנִּשְׁבַּעְתִּי לְאַבְרָהָם (תנחומא, שמות כ):\",1,0],[2,136,80,3,\"אֶפְרַיִם. בְּמִלְחֶמֶת אֲרָם, כְּשֶׁצָּר עַל שׁוֹמְרוֹן (מלכים א כ:א) וְשָׁלַח מַלְאָכִים לְאַחְאָב: ״כַּסְפְּךָ וּזְהָבְךָ לִי הוּא וְנָשֶׁיךָ וּבָנֶיךָ הַטּוֹבִים לִי הֵם״ (מלכים א כ:ג):\",2,0],[2,136,80,3,\"מְנַשֶּׁה. בִּימֵי יְהוֹאָשׁ בֶּן יְהוֹאָחָז, שֶׁנֶּאֱמַר: ״כִּי רָאָה ה׳ בָּעֳנִי יִשְׂרָאֵל״ (מלכים ב יג:כו), ״כִּי אִבְּדָם מֶלֶךְ אֲרָם וַיְשִׂימֵם כֶּעָפָר לָדוּשׁ״ (מלכים ב יג:ז), וְהִכּוּ שָׁלֹשׁ פְּעָמִים בַּמִּלְחָמָה, שֶׁנֶּאֱמַר שָׁם: ״שָׁלֹשׁ פְּעָמִים הִכָּהוּ יוֹאָשׁ וַיָּשֶׁב אֶת עָרֵי יִשְׂרָאֵל״ (מלכים ב יג:כה). בְּפֵרוּשִׁים אֲחֵרִים מָצָאתִי שֶׁנֶּאֱמַר: ״שָׁלֹשׁ פְּעָמִים תַּכֶּה אֶת אֲרָם״ וַאֲשֶׁר הֵשִׁיב אֶת עָרֵי יִשְׂרָאֵל:\",3,0],[2,136,80,3,\"בִּנְיָמִין. בִּימֵי אֲחַשְׁוֵרוֹשׁ, שֶׁהָיוּ מָרְדְּכַי וְאֶסְתֵּר בְּסַכָּנָה, וְכָל הַדּוֹר תָּלוּי בָּהֶם (מגילה יב.):\",4,0],[2,136,80,3,\"וּלְכָה לִישֻׁעָתָה לָּנוּ. אֵין זֶה לְשׁוֹן הֲלִיכָה, אֶלָּא כְּמוֹ ״לְךָ״, וְכֵן הוּא בַּמָּסֹרֶת ״וּלְכָה אֵיפוֹא״ דְּיַעֲקֹב (בראשית כז:לז), ״וּלְכָה אֵין בְּשׂוֹרָה מוֹצֵאת״ (שמואל ב יח:כב), ״שִׂמְלָה לְכָה קָצִין תִּהְיֶה לָּנוּ וְגוֹ׳״ (ישעיהו ג:ו):\",5,0],[2,136,80,4,\"הֲשִׁיבֵנוּ. בְּגָלוּת בָּבֶל שֶׁהָיָה מָרְדֳּכַי שָׁם (אסתר ב:ה):\",1,0],[2,136,80,5,\"עַד מָתַי עָשַׁנְתָּ. בַּצָּרוֹת מַלְכֵי יָוָן שֶׁהֵרֵעוּ מְאֹד לְיִשְׂרָאֵל:\",1,0],[2,136,80,6,\"הֶאֱכַלְתָּם לֶחֶם דִּמְעָה. בְּמִצְרָיִם:\",1,0],[2,136,80,6,\"וַתַּשְׁקֵמוֹ בִּדְמָעוֹת שָׁלִישׁ. בְּבָבֶל, שֶׁהָיוּ שִׁבְעִים שָׁנָה, שֶׁהוּא שְׁלִישׁ שֶׁל מָאתַיִם וְעֶשֶׂר שֶׁל מִצְרַיִם. זוֹ לָמַדְתִּי מִיסוֹדוֹ שֶׁל רַבִּי מֹשֶׁה הַדַּרְשָׁן. וְיֵשׁ לִפְתּוֹר: עַל שֵׁם שֶׁמַּלְכוּת יָוָן הָיְתָה הַצָּרָה הַשְּׁלִישִׁית. וְאִם תֹּאמַר: רְבִיעִית הִיא, שֶׁהֲרֵי פָּרַס וּמָדַי קָדְמוּ? כָּל שִׁבְעִים שָׁנָה שֶׁל בָּבֶל אֵינָהּ אֶלָּא גָּלוּת אַחַת. וּמְנַחֵם פֵּרֵשׁ: שָׁלִישׁ שֵׁם שֶׁל כְּלִי שֶׁשּׁוֹתִין בּוֹ, וְכֵן פֵּרֵשׁ ״וְכָל בַּשָּׁלִישׁ עֲפַר הָאָרֶץ״ (ישעיהו מ:יב). וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ עַל שָׁלֹשׁ דְּמָעוֹת שֶׁהוֹרִיד עֵשָׂו, שֶׁנֶּאֱמַר בּוֹ ״וַיִּצְעַק צְעָקָה״ (בראשית כז:לד) – הֲרֵי אַחַת, ״גְּדֹלָה״ – הֲרֵי שְׁתַּיִם, ״וּמָרָה״ – הֲרֵי שָׁלֹשׁ, וַעֲלֵיהֶם זָכָה לִחְיוֹת עַל חַרְבּוֹ: ״וְהָיָה כַּאֲשֶׁר תָּרִיד וְגוֹ׳״ (בראשית כז:מ):\",2,0],[2,136,80,7,\"תְּשִׂימֵנוּ מָדוֹן. אַתָּה שָׂם אוֹתָנוּ מָדוֹן לְכָל שְׁכֵנֵינוּ, שֶׁנִּתְגָּרוּ בָּנוּ יָוָן:\",1,0],[2,136,80,8,\"הֲשִׁיבֵנוּ וְנִוָּשֵׁעָה. מִבְּנֵי יָוָן:\",1,0],[2,136,80,9,\"גֶּפֶן מִמִּצְרַיִם תַּסִּיעַ וְגוֹ׳. חָזַר וְרָמַז עַל גָּלוּת אֲרַמִּיִּים: גֶּפֶן יִשְׂרָאֵל אֲשֶׁר הִסַּעְתָּ מִמִּצְרַיִם, עָקַרְתָּ מִשָּׁם (חולין צב.), כְּמוֹ ״וַיַּסַּע כָּעֵץ תִּקְוָתִי״ (איוב יט:י), וְאַחַר כָּךְ גֵּרַשְׁתָּ שִׁבְעָה גוֹיִם וּנְטַעְתָּם בְּאַרְצָם:\",1,0],[2,136,80,10,\"פִּנִּיתָ לְפָנֶיהָ. אֶת הַיּוֹשְׁבִים שָׁם:\",1,0],[2,136,80,10,\"וַתַּשְׁרֵשׁ שָׁרָשֶׁיהָ. הִשְׁרִישָׁה שָׁרָשֶׁיהָ:\",2,0],[2,136,80,11,\"וַעֲנָפֶיהָ. כְּמוֹ אַרְזֵי אֵל, אֲרָזִים חֲזָקִים. כְּלוֹמַר: מְלָכִים אַדִּירִים:\",1,0],[2,136,80,12,\"תְּשַׁלַּח קְצִירֶהָ. שִׁלְּחָה פְּאוֹרוֹתֶיהָ, כְּמוֹ ״וְעָשָׂה קָצִיר״ (איוב יד:ט):\",1,0],[2,136,80,12,\"עַד יָם. עַד הַיָּם הַגָּדוֹל הָיָה גְבוּלָהּ (במדבר לד:ו):\",2,0],[2,136,80,12,\"וְאֶל נָהָר יוֹנְקוֹתֶיהָ. רָחְבּוֹ שֶׁל אֶרֶץ יִשְׂרָאֵל מִמִּדְבָּר עַד הַנָּהָר נְהַר פְּרָת (יהושע א:ד):\",3,0],[2,136,80,13,\"לָמָּה. עַתָּה:\",1,0],[2,136,80,13,\"פָּרַצְתָּ גְדֵרֶיהָ. שֶׁל אוֹתָהּ הַכֶּרֶם:\",2,0],[2,136,80,13,\"וְאָרוּהָ כָּל עֹבְרֵי דָרֶךְ. לִקְּטוּהָ כָּל הַבָּא, כְּמוֹ ״אָרִיתִי מוֹרִי עִם בְּשָׂמִי״ (שיר השירים ה:א), וְכֵן בִּלְשׁוֹן מִשְׁנָה: כִּמְלֹא אוֹרֶה וְסַלּוֹ (שביעית א:ב):\",3,0],[2,136,80,14,\"יְכַרְסְמֶנָּה חֲזִיר מִיָּעַר. כְּמוֹ שָׂדֶה שֶׁקִּרְסְמוּהָ נְמָלִים (פאה ב:ז) בִּלְשׁוֹן מִשְׁנָה, וְהוּא לְשׁוֹן נְתִיקָה:\",1,0],[2,136,80,14,\"מִיָּעַר. הָעַיִ״ן תְּלוּיָה (וכאלו נכתב באל״ף). זָכוּ יִשְׂרָאֵל, הֲרֵי עֵשָׂו אוֹיְבָם כְּחַיַּת הַיְאוֹר שֶׁאֵין לָהֶם כֹּחַ לַעֲלוֹת בַּיַּבָּשָׁה, וּבִזְמַן שֶׁהַפֻּרְעָנוּת נִגְזַר עֲלֵיהֶם מִתְגַּבֵּר כְּחַיַּת הַיַּעַר שֶׁהִיא מַשְׁחֶתֶת וְהוֹרֶגֶת. וַחֲזִיר מִיָּעַר הוּא עֲמָלֵק, כְּמוֹ דִּכְתִיב (דניאל ז:ז) ״אָכְלָה וּמְדַקָּה וּשְׁאָרָא בְּרַגְלַהּ רָפְסָה״, וְיֵשׁ לוֹ (לֶחָזִיר) מִקְצָת סִימָנֵי טָהֳרָה. אַף עֲמָלֵק יֵשׁ לוֹ זְכוּת אָבוֹת:\",2,0],[2,136,80,14,\"וְזִיז שָׂדַי. כָּל רֶמֶשׂ הַשָּׂדֶה, וּלְשׁוֹן זִיז – שֶׁהוּא זָז מִמְּקוֹמוֹ וְהוֹלֵךְ:\",3,0],[2,136,80,14,\"יִרְעֶנָּה. רוֹעֶה עָלֶיהָ וַעֲנָפֶיהָ וְאוֹכְלָן:\",4,0],[2,136,80,16,\"וְכַנָּה אֲשֶׁר נָטְעָה יְמִינֶךָ. הַמְבֻסֶּסֶת וְהַמְיֻשֶּׁבֶת לְשׁוֹן ״וַהֲשִׁיבְךָ עַל כַּנֶּךָ״ (בראשית מ:יג):\",1,0],[2,136,80,16,\"וְעַל בֵּן אִמַּצְתָּ לָּךְ. וְעַל עֵשָׂו, שֶׁהָיָה בֵּן חָבִיב לְאָבִיו, שֶׁהָיָה קוֹרֵא אוֹתוֹ בְּנִי (בראשית כז:א), אִמַּצְתָּ גֶּפֶן יַעֲקֹב לָךְ, שֶׁנֶּאֱמַר: ״וְאֶת אָחִיךָ תַּעֲבֹד״ (בראשית כז:מ). עַכְשָׁיו:\",2,0],[2,136,80,17,\"שְׂרוּפָה בָאֵשׁ. כְּסוּחָה, לְשׁוֹן ״לֹא תִזְמוֹר״ (ויקרא כה:ד), תִּרְגֵּם אוּנְקְלוֹס ״לָא תִכְסַח״:\",1,0],[2,136,80,17,\"יֹאבֵדוּ. תָּמִיד הֵם הוֹלְכִין וְאוֹבְדִין מִגַּעֲרַת פָּנֶיךָ וְזַעְפְּךָ:\",2,0],[2,136,80,18,\"תְּהִי יָדְךָ עַל אִישׁ יְמִינֶךָ. תָּשִׁיב מַכּוֹתֶיךָ עַל עֵשָׂו, שֶׁהוּא אִישׁ הָעוֹמֵד לְהִפָּרַע יְמִינְךָ מִמֶּנּוּ:\",1,0],[2,136,80,18,\"וְעַל בֶּן אָדָם. אֲשֶׁר אִמַּצְתָּ לְךָ לִהְיוֹת מוֹשָׁבוֹ ״מִשְׁמַנֵּי הָאָרֶץ״ (בראשית כז:לט):\",2,0],[2,136,80,19,\"וְלֹא נָסוֹג מִמֶּךָּ. וְאַל תִּגְרֹם לָנוּ לִהְיוֹת נְסוֹגִים מִמֶּךָּ:\",1,0],[2,136,80,19,\"תְּחַיֵּנוּ. מִן הַגָּלוּת וְנַזְכִּיר טוֹבָתְךָ וּגְבוּרָתְךָ, וְאָז נִקְרָא בִּשְׁמֶךָ:\",2,0],[2,136,80,20,\"ה׳ אֱלֹהִים צְבָאוֹת. כָּאן נֶאֶמְרוּ שָׁלֹשׁ אַזְכָּרוֹת (שֶׁל שֵׁמוֹת), וּבָאֶמְצָעִי שְׁתֵּי אַזְכָּרוֹת (תהלים פ:ח), וּבָרִאשׁוֹן אַזְכָּרָה אַחַת (תהלים פ:ד). הַכֹּל לְפִי חֹזֶק הַגָּלֻיּוֹת וְהַצָּרָה וְהַגְּאֻלָּה:\",1,0],[2,136,81,1,\"עַל הַגִּתִּית. כְּלִי שִׁיר הַבָּא מִגַּת:\",1,0],[2,136,81,2,\"הָרִיעוּ. בְּרֹאשׁ הַשָּׁנָה (ראש השנה ל:):\",1,0],[2,136,81,3,\"כִּנּוֹר נָעִים עִם נָבֶל. רַבִּי חִיָּיא בַּר אַבָּא אוֹמֵר: הוּא נֵבֶל הוּא כִּנּוֹר, וְרַבִּי שִׁמְעוֹן אוֹמֵר: נִימִין (וִיתֵדוֹת) יְתֵרוֹת שֶׁבֵּין זֶה לָזֶה. לָמָּה נִקְרָא שְׁמוֹ נֵבֶל? שֶׁהוּא מְנַבֵּל כָּל מִינֵי זֶמֶר:\",1,0],[2,136,81,4,\"בַּחֹדֶשׁ. בְּחִדּוּשׁ הַלְּבָנָה:\",1,0],[2,136,81,4,\"בַּכֵּסֶה. יוֹם מוֹעֵד קָבוּעַ לְכָךְ, וְכֵן ״לְיוֹם הַכֵּסֶא יָבֹא בֵיתוֹ״ (משלי ז:כ) – לַמּוֹעֵד הַקָּבוּעַ (ביצה טז.):\",2,0],[2,136,81,5,\"כִּי חֹק. הוּא לְיִשְׂרָאֵל מֵאֵת הַקָּדוֹשׁ בָּרוּךְ הוּא לִתְקֹעַ בְּאוֹתוֹ הַיּוֹם, וְהוּא יוֹם הַמִּשְׁפָּט לְהַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,136,81,6,\"עֵדוּת בִּיהוֹסֵף שָׂמוֹ. בְּרֹאשׁ הַשָּׁנָה יָצָא יוֹסֵף מִבֵּית הָאֲסוּרִים (ראש השנה י:):\",1,0],[2,136,81,6,\"שְׂפַת לֹא יָדַעְתִּי אֶשְׁמָע. מְפֹרָשׁ בְּמַסֶּכֶת סוֹטָה (סוטה לו:), שֶׁלִּמְּדוֹ גַבְרִיאֵל שִׁבְעִים לָשׁוֹן:\",2,0],[2,136,81,7,\"מִדּוּד. מֵעֲבוֹדַת עַבְדוּת לְבַשֵּׁל קְדֵרוֹת כְּדֶרֶךְ שְׁאָר הָעֲבָדִים:\",1,0],[2,136,81,7,\"מִדּוּד. קְדֵרָה, כְּמוֹ ״וְהִכָּה בַכִּיּוֹר אוֹ בַדּוּד״ (שמואל א ב:יד):\",2,0],[2,136,81,8,\"בַּצָּרָה קָרָאתָ. לִי כֻּלְּכֶם קְרָאתֶם מִצָּרַת עֲבוֹדַת סִבְלוֹת מִצְרַיִם, וָאֲחַלֵּץ אֶתְכֶם:\",1,0],[2,136,81,8,\"אֶעֶנְךָ בְּסֵתֶר רַעַם. אַתָּה קְרָאתַנִי בְּסֵתֶר, בֵּינִי וּבֵינֶךָ, וַאֲנִי עָנִיתִיךָ בְּקוֹל רַעַם; הוֹדַעְתִּי גְּבוּרוֹת וְנוֹרָאוֹת בְּפַרְהֶסְיָא:\",2,0],[2,136,81,8,\"אֶבְחָנְךָ עַל מֵי מְרִיבָה סֶלָה. וְאַף עַל פִּי שֶׁגָּלוּי וּבָחוּן לְפָנַי, שֶׁאַתֶּם עֲתִידִים לְהַמְרוֹתִי בְּמֵי מְרִיבָה (במדבר כ), כָּךְ שְׁנוּיָה בַּמְּכִילְתָּא (מכילתא יתרו בחדש א):\",3,0],[2,136,81,9,\"שְׁמַע עַמִּי. אַחֲרֵי שֶׁכָּל זֹאת עָשִׂיתִי לְךָ, כְּדַאי אַתָּה לִשְׁמֹעַ לִי:\",1,0],[2,136,81,11,\"הַרְחֶב פִּיךָ. לִשְׁאוֹל מִמֶּנִּי כָּל תַּאֲוַת לִבְּךָ:\",1,0],[2,136,81,11,\"וַאֲמַלְאֵהוּ. כְּכָל אֲשֶׁר תִּשְׁאַל אֲמַלֵּא:\",2,0],[2,136,81,13,\"בִּשְׁרִירוּת לִבָּם. בְּמַרְאִית לִבָּם, כְּמוֹ ״לְמַעַן שׁוֹרְרָי״ (תהלים ה:ט):\",1,0],[2,136,81,14,\"לוּ עַמִּי שׁוֹמֵעַ לִי. עֲדַיִן אִם הָיוּ רוֹצִין לָשׁוּב לִי וְלִשְׁמֹעַ אֵלַי:\",1,0],[2,136,81,15,\"כִּמְעַט אוֹיְבֵיהֶם אַכְנִיעַ. בְּשָׁעָה מוּעֶטֶת הָיִיתִי מַכְנִיעַ אוֹיְבֵיהֶם:\",1,0],[2,136,81,15,\"אָשִׁיב יָדִי. אָשִׁיב מַכָּתִי מֵעֲלֵיכֶם לָתֵת אוֹתָהּ עֲלֵיהֶם, וְאָז:\",2,0],[2,136,81,16,\"מְשַׂנְאֵי ה׳ יְכַחֲשׁוּ לוֹ וִיהִי עִתָּם. פּוּרְעָנוּתָם לְעוֹלָם:\",1,0],[2,136,81,17,\"וַיַּאֲכִילֵהוּ. לְיִשְׂרָאֵל:\",1,0],[2,136,81,17,\"וּמִצּוּר. הִשְׂבִּיעָם דְּבַשׁ כְּשֶׁהָלְכוּ בִדְרָכָיו, כְּעִנְיָן שֶׁנֶּאֱמַר: ״וַיֵּנִקֵהוּ דְבַשׁ מִסֶּלַע״ (דברים לב:יג):\",2,0],[2,136,82,1,\"אֱלֹהִים נִצָּב בַּעֲדַת אֵל. לִרְאוֹת אִם אֱמֶת יִשְׁפֹּטוּ. וְאַתֶּם, הַדַּיָּנִים, עַד מָתַי תִּשְׁפְּטוּ עָוֶל?!\",1,0],[2,136,82,3,\"הַצְדִּיקוּ. אִם זַכַּאי הוּא בְּדִינוֹ, אַל תַּהַפְּכוּ דִינוֹ לְטוֹבָה בִּשְׁבִיל לָשֵׂאת פְּנֵי רְשָׁעִים:\",1,0],[2,136,82,5,\"לֹא יָדְעוּ. הַדַּיָּנִין הַמְעַוְּתִים אֶת הַדִּין:\",1,0],[2,136,82,5,\"וְלֹא יָבִינוּ. אֶת אֲשֶׁר בִּשְׁבִיל הֶעָוֹן הַזֶּה יִתְהַלְּכוּ בַּחֲשֵׁכָה (עַל דֶּרֶךְ ״כִּי הַשֹּׁחַד יְעַוֵּר וְגוֹ׳״ (שמות כג:ח)), וְיִמּוֹטוּ עַל כָּךְ מוֹסְדֵי אָרֶץ:\",2,0],[2,136,82,6,\"אֱלֹהִים אַתֶּם. מַלְאָכִים; כְּשֶׁנָּתַתִּי לָכֶם אֶת הַתּוֹרָה, נְתַתִּיהָ לָכֶם עַל מְנָת שֶׁאֵין מַלְאַךְ הַמָּוֶת שׁוֹלֵט עוֹד בָּכֶם:\",1,0],[2,136,82,7,\"אָכֵן כְּאָדָם תְּמוּתוּן. אָכֵן כְּאָדָם הָרִאשׁוֹן תְּמוּתוּן, אַחֲרֵי שֶׁחִבַּלְתֶּם מַעֲשֵׂיכֶם כְּמוֹהוּ (עבודה זרה ה,א; מכילתא יתרו בחדש ט):\",1,0],[2,136,82,7,\"וּכְאַחַד הַשָּׂרִים. הָרִאשׁוֹנִים שֶׁמֵּתוּ, כֵּן תִּפֹּלוּ. וּמִדְרַשׁ אַגָּדָה : כְּאַחַד הַשָּׂרִים שֶׁל מַעְלָה, שֶׁנֶּאֱמַר (ישעיהו כד:כא): ״יִפְקֹד ה׳ עַל צְבָא הַמָּרוֹם בַּמָּרוֹם״:\",2,0],[2,136,82,8,\"קוּמָה אֱלֹהִים. אָסָף הִתְחִיל לְהִתְפַּלֵּל שֶׁיָּקוּם וְיַכְרִית אוֹתָם הַדַּיָּנִין הַמְקֻלְקָלִין מִיִּשְׂרָאֵל:\",1,0],[2,136,82,8,\"כִּי אַתָּה. הוּא הַנּוֹחֵל הַגּוֹיִם, וְהַכֹּל בְּיָדְךָ לִשְׁפּוֹט:\",2,0],[2,136,83,2,\"אַל דֳּמִי לָךְ. אַל תִּתֵּן שְׁתִיקָה לְעַוּוֹתָתֵינוּ שֶׁאוֹיְבֵינוּ מְרֵיעִים לָנוּ:\",1,0],[2,136,83,6,\"עָלֶיךָ בְּרִית יִכְרֹתוּ. בְּרִית זוֹ אֵינָהּ אֶלָּא עָלֶיךָ, לְהַשְׁכִּיחַ אֶת שִׁמְךָ, שֶׁאֵין אַתָּה קָרוּי אֱלֹהִים אֶלָּא לָנוּ אֱלֹהֵי יִשְׂרָאֵל, וּמֵאַחַר שֶׁלֹּא יִזָּכֵר שֵׁם יִשְׂרָאֵל אַף שִׁמְךָ הַגָּדוֹל אֵינוֹ נִזְכָּר. כָּךְ מָצָאתִי:\",1,0],[2,136,83,9,\"גַּם אַשּׁוּר. אַף אַשּׁוּר שֶׁהָיָה נִזְהָר עַד הַיּוֹם מִשְּׁאָר עֵצָה סְכָלָה וְלֹא יִתְחַבֵּר עִם מְרֵעִים, כְּמָה דְאַתְּ אָמַר (בראשית י:יא) ״מִן הָאָרֶץ הַהִיא יָצָא אַשּׁוּר״, שֶׁיָּצָא מֵעֲצַת דּוֹר הַפְּלַגָּה, כָּאן נִלְוָה עִמָּם וַעֲזָרָם לְרָעָה (בפרושים אחרים מצאתי כן). גַּם אַשּׁוּר נִלְוָה עִמָּם וְגוֹ׳. גַּם זֶה שֶׁהָיָה מְחַבֵּב מִתְּחִלָּתוֹ מַעֲשִׂים טוֹבִים שֶׁפֵּרַשׁ מֵעֲצַת נִמְרוֹד שֶׁנֶּאֱמַר מִן הָאָרֶץ הַהִיא יָצָא אַשּׁוּר, אַף הוּא חָזַר לִהְיוֹת רָשָׁע. לְכָךְ נִשְׁתַּתֵּף לְהַחֲרִיב בֵּיתְךָ (בראשית רבה לז:ד):\",1,0],[2,136,83,9,\"הָיוּ זְרוֹעַ. כָּל אֵלֶּה נָתְנוּ כֹּחַ וְעֶזְרָה לְמוֹאָב וְעַמּוֹן שְׁכֵנֵינוּ לָבֹא עָלֵינוּ:\",2,0],[2,136,83,10,\"עֲשֵׂה לָהֶם כְּמִדְיָן. עַל יְדֵי גִּדְעוֹן (שופטים ז-ח):\",1,0],[2,136,83,10,\"כְּסִיסְרָא. עַל יְדֵי בָּרָק (שופטים ד:ט):\",2,0],[2,136,83,11,\"נִשְׁמְדוּ בְעֵין דֹּאר. אֵינִי יוֹדֵעַ אֵיזוֹ מִן הַמִּלְחָמוֹת הָיְתָה בְּעֵין דֹּאר, שֶׁל גִּדְעוֹן (שופטים ז:א) אוֹ שֶׁל בָּרָק (שופטים ה:יט):\",1,0],[2,136,83,11,\"הָיוּ דֹמֶן. ״זֶבֶל מְפֻזָּר״, תִּרְגֵּם יוֹנָתָן:\",2,0],[2,136,83,13,\"אֲשֶׁר אָמְרוּ. הַגּוֹיִם הָאֵלּוּ הָאֲמוּרִים לְמַעְלָה, אֱדוֹם וְיִשְׁמָעֵאל וְכָל חֲבֵרֵיהֶם:\",1,0],[2,136,83,13,\"נִירְשָׁה לָּנוּ אֵת נְאוֹת אֱלֹהִים. אֶת נְוֵה בֵּית אֱלֹהִים:\",2,0],[2,136,83,14,\"שִׁיתֵמוֹ כַגַּלְגַּל. וּכְקַשׁ הַנִּדָּפִים מִפְּנֵי רוּחַ, וּמַהוּ גַּלְגַּל? הוּא רָאשֵׁי קוֹצֵי הַשָּׂדֶה הַקְּרוּיִים קרדנ״ש בְּלַעַ״ז, וּכְשֶׁמַּגִּיעִין יְמֵי הַחֹרֶף נִתָּקִים וְנִשְׁחָתִים מֵאֲלֵיהֶם וּפוֹרְחִין מְעַט מְעַט, וְדוֹמֶה אוֹתוֹ הַנִּתָּק מֵהֶם כְּמִין גַּלְגַּלֵּי אוֹפַן עֲגָלָה, וְהָרוּחַ מוֹלִיכָתָן:\",1,0],[2,136,83,16,\"וּבְסוּפָתְךָ. טוֹרְבִּילְיוֹ״ן בְּלַעַ״ז:\",1,0],[2,136,84,2,\"מַה יְּדִידוֹת מִשְׁכְּנוֹתֶיךָ. כַּמָּה אֲהוּבוֹת וַחֲבִיבוֹת מִשְׁכְּנוֹתֶיךָ:\",1,0],[2,136,84,3,\"נִכְסְפָה. נֶחְמְדָה:\",1,0],[2,136,84,3,\"כָּלְתָה. נִתְאַוְּתָה, כְּמוֹ ״וַתְּכַל דָּוִד הַמֶּלֶךְ לָצֵאת אֶל אַבְשָׁלוֹם״ (שמואל ב יג:לט):\",2,0],[2,136,84,3,\"לְחַצְרוֹת ה׳. כִּי חָרְבוּ, וְעַל הַגָּלוּת אָמְרָה:\",3,0],[2,136,84,3,\"לִבִּי וּבְשָׂרִי יְרַנְּנוּ. יִתְפַּלְּלוּ עַל זֹאת:\",4,0],[2,136,84,4,\"גַּם צִפּוֹר מָצְאָה בַיִת. בְּחֻרְבָּנוֹ קִנְּנוּ בוֹ הַצִּפֳּרִים. וּמִדְרַשׁ אַגָּדָה: בְּבִנְיָנוֹ מְדַבֵּר, וְהַצִּפּוֹר הִיא כְּנֶסֶת יִשְׂרָאֵל:\",1,0],[2,136,84,4,\"אֲשֶׁר שָׁתָה. שָׂמָה:\",2,0],[2,136,84,5,\"אַשְׁרֵי. מִי שֶׁיַּגִּיעַ עוֹד לֵישֵׁב בְּבֵיתֶךָ, וְעוֹד יְהַלְלוּךָ בְּתוֹכוֹ:\",1,0],[2,136,84,6,\"עֹז לוֹ בָךְ. אֲשֶׁר שָׂם אוֹתְךָ עֹז מִבְטַחוֹ:\",1,0],[2,136,84,6,\"מְסִלּוֹת בִּלְבָבָם. מְחַשֵּׁב בְּלִבּוֹ מְסִלּוֹת דְּרָכָיו לְיַשֵּׁר אֶת דַּרְכּוֹ:\",2,0],[2,136,84,7,\"עוֹבְרֵי בְּעֵמֶק הַבָּכָא. אוֹתָם הָעוֹבְרִים עַל דָּתְךָ, וְהִנָּם בְּעוּמְקָהּ שֶׁל גֵּיהִנֹּם בִּבְכִי וִילָלָה:\",1,0],[2,136,84,7,\"מַעְיָן יְשִׁיתוּהוּ. בְּדִמְעוֹת עֵינֵיהֶם:\",2,0],[2,136,84,7,\"גַּם בְּרָכוֹת יַעְטֶה מוֹרֶה. מְבָרְכִים וּמוֹדִים לִשְׁמוֹ, וְאוֹמְרִים: יָפֶה דָּן אוֹתָנוּ וֶאֱמֶת דִּינוֹ, וּבְרָכוֹת יַעֲטֶה לָנוּ הַמּוֹרִים אוֹתָנוּ לָלֶכֶת בְּדֶרֶךְ הַטּוֹב, וְלֹא שָׁמַעְנוּ לוֹ:\",3,0],[2,136,84,8,\"יֵלְכוּ מֵחַיִל אֶל חָיִל. אוֹתָם הַנִּזְכָּרִים לְמַעְלָה יוֹשְׁבֵי בֵיתֶךָ אֲשֶׁר מְסִלּוֹת בִּלְבָבָם):\",1,0],[2,136,84,8,\"מֵחַיִל אֶל חָיִל. מִבֵּית הַמִּדְרָשׁ לְבֵית הַכְּנֶסֶת, וְיֵרָאֶה צְבָאָם וְחֵילָם אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּצִיּוֹן:\",2,0],[2,136,84,9,\"שִׁמְעָה תְפִלָּתִי. לִבְנוֹת בֵּיתֶךָ:\",1,0],[2,136,84,10,\"מָגִנֵּנוּ. הוּא בֵּית הַמִּקְדָּשׁ הַמֵּגִין עָלֵינוּ:\",1,0],[2,136,84,10,\"וְהַבֵּט פְּנֵי (דָּוִד) מְשִׁיחֶךָ. וְהִסְתַּכֵּל בְּחֲסָדָיו וּבְטָרְחוֹ אֲשֶׁר טָרַח וְיָגַע עַל בִּנְיָנוֹ:\",2,0],[2,136,84,11,\"כִּי טוֹב יוֹם. אֶחָד בַּחֲצֵרֶיךָ וּלְמָחָר יָמוּת, מִלִּחְיוֹת אֶלֶף שָׁנִים בְּמָקוֹם אַחֵר:\",1,0],[2,136,84,11,\"בָּחַרְתִּי הִסְתּוֹפֵף. עַל הַסַּף וְעַל הַמְּזוּזוֹת לִשְׁקוֹד:\",2,0],[2,136,84,11,\"מִדּוּר בְּאָהֳלֵי רֶשַׁע. מִלִּהְיוֹת דָּר בְּשַׁלְוָה בְּאָהֳלֵי עֵשָׂו הָרָשָׁע לְהִדָּבֵק בָּהֶם:\",3,0],[2,136,84,12,\"כִּי שֶׁמֶשׁ וּמָגֵן. יֵשׁ לִפְתֹּר שֶׁמֶשׁ כְּמַשְׁמָעוֹ, וּמִדְרַשׁ תְּהִלִּים פּוֹתְרוֹ לְשׁוֹן שִׁנֵּי חוֹמָה:\",1,0],[2,136,85,2,\"רָצִיתָ ה׳ אַרְצֶךָ וְגוֹ׳. אִם שַׁבְתָּ שְׁבוּת יַעֲקֹב וְנָשָׂאתָ אֶת עֲוֹנָם וְכִסִּיתָ חַטָּאתָם, וְאָסַפְתָּ עֶבְרָתְךָ מֵהֶם וַהֲשִׁיבוֹתָ עַצְמְךָ מֵחֲרוֹן אַפֶּךָ, אָז רָצִיתָ אַרְצֶךָ וְעוֹלָמְךָ מִתְרַצֶּה. וְכָל זְמַן שֶׁלֹּא תַּעֲשֶׂה זֹאת, אֵין אַרְצְךָ וְעוֹלָמְךָ מִתְרַצֶּה:\",1,0],[2,136,85,5,\"שׁוּבֵנוּ. שׁוּב אַתָּה וַהֲשִׁיבֵנוּ (שוחר טוב פה:ג):\",1,0],[2,136,85,7,\"הֲלֹא אַתָּה. סוֹפְךָ שֶׁתָּשׁוּב תְּחַיֵּנוּ, שֶׁהֲרֵי הִבְטַחְתָּנוּ כֵּן עַל יְדֵי נְבִיאֶךָ (יחזקאל לז):\",1,0],[2,136,85,9,\"אֶשְׁמְעָה מַה יְדַבֵּר. אֶזְכֶּה לִשְׁמֹעַ מַה יְדַבֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁיְּדַבֵּר שָׁלוֹם אֶל עַמּוֹ:\",1,0],[2,136,85,9,\"לְכִסְלָה. לְשִׁטּוּת, לַחֲטֹא לְפָנָיו:\",2,0],[2,136,85,11,\"חֶסֶד וֶאֱמֶת נִפְגָּשׁוּ. שֶׁיִּהְיוּ יִשְׂרָאֵל דּוֹבְרֵי אֱמֶת, וּמִן הַשָּׁמַיִם יִפְגֹּשׁ בָּהֶם הַחֶסֶד:\",1,0],[2,136,85,11,\"צֶדֶק וְשָׁלוֹם נָשָׁקוּ. הַצְּדָקָה שֶׁהָיוּ יִשְׂרָאֵל עוֹשִׂים, וְהַשָּׁלוֹם מֵאֵת הַקָּדוֹשׁ בָּרוּךְ הוּא, יִהְיוּ נוֹשְׁקִין זֶה לָזֶה, כְּלוֹמַר: וְהָיָה מַעֲשֵׂה הַצְּדָקָה שָׁלוֹם (ישעיה לב:יז):\",2,0],[2,136,85,12,\"אֱמֶת מֵאֶרֶץ תִּצְמָח וְגוֹ׳. כְּשֶׁהָיוּ יִשְׂרָאֵל דּוֹבְרִים אֱמֶת, וְיַשְׁקִיפוּ מִן הַשָּׁמַיִם צְדָקָה שֶׁהֵם עוֹשִׂים בָּאָרֶץ:\",1,0],[2,136,85,13,\"גַּם ה׳ יִתֵּן הַטּוֹב. ״יִפְתַּח אוֹצָרוֹ אֶת הַשָּׁמַיִם לָתֵת מָטָר״ (דברים כח:יב), כְּדֵי לַעֲשׂוֹת אַרְצוֹ אֶת יְבוּלָהּ:\",1,0],[2,136,85,14,\"וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו. וְיָשֵׂם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַצֶּדֶק בְּדַרְכֵי פְּעָמָיו שֶׁיִּתְנַהֵג בָּהֶם אֶת בָּנָיו:\",1,0],[2,136,86,2,\"כִּי חָסִיד אָנִי. שֶׁאֲנִי שׁוֹמֵעַ גִּדּוּפִי וְחֶרְפָּתִי, וִיכֹלֶת בְּיָדִי לְהִנָּקֵם, וַאֲנִי שׁוֹתֵק. כָּךְ הִיא בְּאַגָּדַת תְּהִלִּים. דָּבָר אַחֵר פֵּרְשׁוּ רַבּוֹתֵינוּ בִּבְרָכוֹת (ברכות ד.): וְלֹא חָסִיד אֲנִי, שֶׁכָּל מַלְכֵי מִזְרָח וּמַעֲרָב יוֹשְׁבִין בִּכְבוֹדָן, וַאֲנִי יָדַי מְלֻכְלָכוֹת בְּדָם וּבְשָׁפִיר וּבְשִׁלְיָא וְכוּ׳?\",1,0],[2,136,86,3,\"כָּל הַיּוֹם. כָּל הַגָּלוּת, שֶׁהוּא יוֹם לָאֻמּוֹת וְלַיְלָה לְיִשְׂרָאֵל. כָּךְ מְפֹרָשׁ בְּאַגָּדַת תְּהִלִּים:\",1,0],[2,136,86,4,\"נַפְשִׁי אֶשָּׂא. לִבִּי אֲכַוֵּן:\",1,0],[2,136,86,8,\"וְאֵין כְּמַעֲשֶׂיךָ. הַמַּקְדִּים עֶלְיוֹנִים לְתַחְתּוֹנִים:\",1,0],[2,136,86,10,\"וְעֹשֵׂה נִפְלָאוֹת אַתָּה אֱלֹהִים לְבַדֶּךָ. עַד שֶׁלֹּא נִבְרְאוּ הַמַּלְאָכִים נִבְרְאוּ הַשָּׁמַיִם וְהָאָרֶץ (שו״ט פו, ג). לְפִיכָךְ יְכַבְּדוּ כָל הַגּוֹיִם לִשְׁמֶךָ:\",1,0],[2,136,86,13,\"מִשְּׁאוֹל תַּחְתִּיָּה. דֶּרֶךְ הַמְנַאֲפִים לְהִנָּתֵן בְּעוּמְקָהּ שֶׁל שְׁאוֹל, וּמִשָּׁם הִצַּלְתַּנִי, שֶׁאָמַר לִי נָתָן הַנָּבִיא: ״גַּם ה׳ הֶעֱבִיר חַטָּאתְךָ״ (שמואל ב יב:יג):\",1,0],[2,136,86,14,\"זֵדִים קָמוּ עָלַי. דּוֹאֵג וַאֲחִיתֹפֶל:\",1,0],[2,136,86,14,\"וְלֹא שָׂמוּךָ לְנֶגְדָּם. לֹא זָכְרוּ אֲשֶׁר רָאוּ שֶׁמְּשָׁחַנִי שְׁמוּאֵל עַל פִּיךָ (שמואל א טז:יב):\",2,0],[2,136,86,16,\"לְבֶן אֲמָתֶךָ. בֶּן הָאָמָה מַשְׁפִּיל אֶת עַצְמוֹ לִפְנֵי אֲדוֹנָיו יוֹתֵר מִמִּקְנַת כֶּסֶף, שֶׁבֶּן הָאָמָה יְלִיד בַּיִת הוּא וְגָדַל בְּחֵיק אֲדוֹנָיו:\",1,0],[2,136,86,17,\"עֲשֵׂה עִמִּי אוֹת לְטוֹבָה. שֶׁיְּהֵא נִכָּר לַאֲחֵרִים שֶׁמָּחַלְתָּ לִי:\",1,0],[2,136,86,17,\"וְיִרְאוּ שׂוֹנְאַי. הָאוֹת וְיֵבֹשׁוּ, וְלֹא שָׁמַע לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לִיתֵּן הָאוֹת בְּיָמָיו, אֶלָּא בִּימֵי שְׁלֹמֹה בְּנוֹ, כְּשֶׁדָּבְקוּ הַשְּׁעָרִים זֶה בָּזֶה וְלֹא נִפְתְּחוּ עַד שֶׁאָמַר (דברי הימים ב ו:מב): ״אַל תָּשֵׁב פְּנֵי מְשִׁיחֶךָ זָכְרָה לְחַסְדֵי דָּוִד עַבְדֶּךָ״:\",2,0],[2,136,87,1,\"יְסוּדָתוֹ בְּהַרְרֵי קֹדֶשׁ. יְסוּדַת מִזְמוֹר זֶה; עַל הַר צִיּוֹן וִירוּשָׁלַיִם יְסָדוֹ הַמְשׁוֹרֵר:\",1,0],[2,136,87,3,\"נִכְבָּדוֹת מְדֻבָּר בָּךְ. אַתְּ, יְרוּשָׁלַיִם, דִּבְרֵי כָבוֹד נִדְבְּרוּ בָּךְ מִפִּי הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמָה הֵן הַנִּכְבָּדוֹת? שֶׁאַתְּ עִיר הָאֱלֹהִים סֶלָה:\",1,0],[2,136,87,4,\"אַזְכִּיר רַהַב וּבָבֶל לְיוֹדְעָי. עוֹד זֹאת דִּבֵּר עָלֶיךָ: אַזְכִּיר אֶת מִצְרַיִם וְאֶת בָּבֶל עַל יוֹדְעַי, לְהָבִיא מִנְחָה, כְּעִנְיָן שֶׁנֶּאֱמַר (ישעיהו סו:כ) ״וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם וְגוֹ׳ מִנְחָה לַה׳ וְגוֹ׳״:\",1,0],[2,136,87,4,\"הִנֵּה פְלֶשֶׁת וְצוֹר עִם כּוּשׁ. גַּם הֵם כְּמִצְרַיִם וּבָבֶל יִתְּנוּ לֵב לְבַקֵּשׁ וְלִזְכֹּר אֶת כָּל אֶחָד וְאֶחָד:\",2,0],[2,136,87,4,\"זֶה יוּלַּד שָׁם. זֶה הָיָה מִמִּשְׁפָּחוֹת הַנּוֹלָדִים בְּצִיּוֹן, כְּעִנְיָן שֶׁנֶּאֱמַר: ״וְאַתֶּם תְּלֻקְּטוּ לְאַחַד אֶחָד״ (ישעיה כז:יב):\",3,0],[2,136,87,5,\"וּלְצִיּוֹן יֵאָמַר אִישׁ וְאִישׁ יֻלַּד בָּהּ. וּכְשֶׁיְּבִיאוּם מִנְחָה לַה׳ בְּצִיּוֹן, יֵאָמַר לָהֶם עַל כָּל אֶחָד וְאֶחָד: זֶה מֵאוֹתָם שֶׁגָּלוּ מִמֵּךְ וּמִתּוֹלְדוֹתֵיהֶם. עִנְיָן אַחֵר: הַמְשׁוֹרֵר אוֹמֵר אַזְכִּיר לְעַמִּי וּלְיוֹדְעַי אֶת גְּדֻלּוֹת מִצְרַיִם וּבָבֶל, שֶׁהֵם רוֹאִים עַתָּה אֶת גְּדֻלָּתָם. הִנֵּה פְלֶשֶׁת וְצוֹר עִם כּוּשׁ, מִפְּנֵי שֶׁהֵם סְמוּכִים לְרַהַב וּבָבֶל, מְנַשְּׂאִים אוֹתָם כָּל הָאֻמּוֹת וְאוֹמְרִים עֲלֵיהֶם: זֶה יֻלַּד שָׁם – בְּמִצְרַיִם וּבָבֶל:\",1,0],[2,136,87,5,\"וּלְצִיּוֹן יֵאָמַר וְגוֹ׳. וְהַשֶּׁבַח הַזֶּה שֶׁהוּא עַכְשָׁיו לְרַהַב וּבָבֶל, יָסוֹב לְצִיּוֹן, וְעָלֶיהָ יְהוּ אוֹמְרִים: פְּלוֹנִי יֻלַּד בָּהּ:\",2,0],[2,136,87,5,\"וְהוּא יְכוֹנְנֶהָ עֶלְיוֹן. וְהַקָּדוֹשׁ בָּרוּךְ הוּא יְכוֹנְנֶהָ לְמַעְלָה מִכָּל הָעֲיָרוֹת:\",3,0],[2,136,87,6,\"ה׳ יִסְפֹּר בִּכְתוֹב עַמִּים וְגוֹ׳. מִקְרָא מְסֹרָס זֶה, וְסֶלָה הָאָמוּר לְסוֹפוֹ מוּסָב כְּלַפֵּי רֹאשׁוֹ: ה׳ יִסְפֹּר בִּכְתוֹב עַמִּים סֶלָה, כְּלוֹמַר לֶעָתִיד כְּשֶׁיִּכְתֹּב הַקָּדוֹשׁ בָּרוּךְ הוּא הָעוֹבְדֵי גִּלּוּלִים לְדֵרָאוֹן, יִמְנֶה אֶת יִשְׂרָאֵל הַנִּבְלָעִים בְּתוֹכָם וְאֶת הַנֶּאֱנָסִים בֵּינֵיהֶם וְיוֹצִיאֵם מִתּוֹכָם וְיֹאמַר זֶה יֻלַּד מֵאוֹתָם שֶׁל צִיּוֹן וְיִבְרוֹר אוֹתָם לוֹ. וְזֶה שֶׁאָמַר יְשַׁעְיָה: ״וְגַם מֵהֶם אֶקַּח לַכֹּהֲנִים וְלַלְוִיִּם״ (ישעיהו סו:כא), מִן הַגּוֹיִם הַמְּבִיאִים אוֹתָם מִנְחָה אֶקַּח הַנִּבְלָעִים בְּתוֹכָם, וְיִהְיֶה בָהֶם כֹּהֲנִים וּלְוִיִּם שֶׁאֵינָם נִכָּרִים וּלְפָנַי גְּלוּיִים הֵם אָמַר ה׳. וְהֵיכָן אָמַר? ״הַנִּסְתָּרוֹת לַה׳ אֱלֹהֵינוּ״ (דברים כט:כח):\",1,0],[2,136,87,7,\"וְשָׁרִים כְּחוֹלְלִים. עַל זֹאת, כְּחוֹלְלִים לְשׁוֹן ״מְחוֹלְלִים״ (שופטים כא:כג):\",1,0],[2,136,87,7,\"כָּל־מַעְיָנַי. כָּל קְרָבַי:\",2,0],[2,136,87,7,\"בָּךְ. בִּישׁוּעָתְךָ (שיר השירים רבה א:לב):\",3,0],[2,136,88,1,\"עַל מָחֲלַת לְעַנּוֹת. עַל חוֹלַת אַהֲבָה וְעִנּוּיָהּ, שֶׁהִיא מְעֻנָּה בְּיִסּוּרֵי הַגָּלוּת:\",1,0],[2,136,88,1,\"מַשְׂכִּיל. כָּל מָקוֹם שֶׁנֶּאֱמַר מַשְׂכִּיל, עַל יְדֵי תּוּרְגְּמָן נֶאֱמַר; שֶׁהָיָה הַנָּבִיא מַעֲמִיד תּוּרְגְּמָן לְפָנָיו, וּכְשֶׁרוּחַ הַנְּבוּאָה בָּאָה לוֹ, אוֹמֵר אֶת הַנְּבוּאָה לַתּוּרְגְּמָן, וְהוּא מַשְׁמִיעָהּ (פסחים קיז.):\",2,0],[2,136,88,1,\"לְהֵימָן הָאֶזְרָחִי. אֶחָד מִן הַמְשׁוֹרְרִים בִּכְלֵי שִׁיר, וְיִסְּדוּהוּ בְּנֵי קֹרַח אֶת הַמִּזְמוֹר הַזֶּה שֶׁיֹּאמְרֵהוּ הֵימָן עַל הַדּוּכָן (דברי הימים א ו:לג):\",3,0],[2,136,88,1,\"לְהֵימָן הָאֶזְרָחִי. מִבְּנֵי זֶרַח בֶּן יְהוּדָה הָיָה, שֶׁהוּא מְיֻחָס (דברי הימים א ב:ו) וּבְנֵי זֶרַח זִמְרִי וְאֵיתָן וְהֵימָן וְכַלְכֹּל וְדַרְדַּע כֻּלָּם חֲמִשָּׁה. הָיוּ חֲכָמִים גְּדוֹלִים, כְּמוֹ שֶׁנֶּאֱמַר בִּשְׁלֹמֹה (מלכים א ה:יא) ״וַיֶּחְכַּם מִכָּל הָאָדָם מֵאֵיתָן הָאֶזְרָחִי וְהֵימָן וְכַלְכֹּל וְדַרְדַּע בְּנֵי מָחוֹל״. וְיִסְּדוּ מִזְמוֹרִים וְנִקְבְּעוּ בְּסֵפֶר תְּהִלִּים, לְכָךְ נִקְרְאוּ בְּנֵי מָחוֹל. כָּךְ מָצָאתִי בְּפֵרוּשִׁים מְדֻיָּקִים:\",4,0],[2,136,88,2,\"יוֹם צָעַקְתִּי. וְגַם בַלַּיְלָה אֲנִי נָכוֹן נֶגְדֶּךָ:\",1,0],[2,136,88,4,\"כִּי שָׂבְעָה בְרָעוֹת נַפְשִׁי. עַל כְּנֶסֶת יִשְׂרָאֵל הוּא אוֹמֵר:\",1,0],[2,136,88,5,\"אֵין אֱיָל. אֵין כֹּחַ, כְּמוֹ ״אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה״ (תהלים כב:כ):\",1,0],[2,136,88,6,\"בַּמֵּתִים חָפְשִׁי. הִנְנִי בֵּין הַמֵּתִים חָפְשִׁי מִן הָעוֹלָם, וְכָל שֶׁהֵם הַמֵּתִים חָפְשִׁים מִן הָעוֹלָם:\",1,0],[2,136,88,6,\"מִיָּדְךָ נִגְזָרוּ. מִמִּצְווֹתֶיךָ נִגְזְרוּ מִן הָעוֹלָם:\",2,0],[2,136,88,7,\"בְּבוֹר תַּחְתִּיּוֹת. הוּא הַגָּלוּת:\",1,0],[2,136,88,8,\"סָמְכָה. נִשְׁעֲנָה וְתָלָה עָלַי:\",1,0],[2,136,88,8,\"וְכָל־מִשְׁבָּרֶיךָ עִנִּיתָ סֶּלָה. מִשְׁבָּרִים לְשׁוֹן גַּלֵּי הַיָּם הֵם, כָּל סַעֲרַת אַפְּךָ, בְּכֻלָּם עִנִּיתָ אוֹתִי תָּמִיד (עירובין נד.):\",2,0],[2,136,88,9,\"שַׁתַּנִי תוֹעֵבוֹת לָמוֹ. הָאֻמּוֹת שֶׁהָיִיתִי חֲשׁוּבָה בְּעֵינֵיהֶם, עַכְשָׁיו אֲנִי נִמְאֶסֶת לָהֶם:\",1,0],[2,136,88,9,\"כָּלוּא. נֶחְבַּשׁ בַּכֶּלֶא וְאֵינִי יָכוֹל לָצֵאת:\",2,0],[2,136,88,11,\"הֲלַמֵּתִים. הֲלָרְשָׁעִים, שֶׁאַף בְּחַיֵּיהֶם קְרוּיִין מֵתִים (ברכות יח.), הֲלָהֶם אַתָּה עוֹשֶׂה פֶּלֶא וְנִסִּים?\",1,0],[2,136,88,11,\"אִם רְפָאִים יָקוּמוּ יוֹדוּךָ. שֶׁמָּא אֵלּוּ הָאֻמּוֹת שֶׁרִפּוּ יְדֵיהֶם מֵעֲבוֹדָתְךָ וּמִתּוֹרָתְךָ יָקוּמוּ וְיוֹדוּךָ? בִּתְמִיהָה:\",2,0],[2,136,88,12,\"הֲיְסֻפַּר בַּקֶּבֶר חַסְדֶּךָ. אִם נָמוּת בְּיַד אוֹיְבֵינוּ, כְּלוּם נוּכַל לְסַפֵּר שִׁבְחֲךָ בַּקֶּבֶר?\",1,0],[2,136,88,16,\"וְגֹוֵעַ מִנֹּעַר. מֵת מִתּוֹךְ תִּשְׁנוֹק מִיתָה חֲטוּפָה, כְּמוֹ (שמות יד:כז) ״וַיְנַעֵר ה׳״. וַיְנַעֵר פֵּרֵשׁ מְנַחֵם לְשׁוֹן חֲבִיטָה, כְּמוֹ ״נוֹעֵר כַּפָּיו מִתְּמֹךְ בַּשֹּׁחַד״ (ישעיהו לג:טו), ״הִתְנַעֲרִי מֵעָפָר קוּמִי שְׁבִי״ (ישעיהו נב:ב), ״וְהָיָה הֶחָסֹן לִנְעֹרֶת״ (ישעיהו א:לא), ״וְיִנָּעֲרוּ רְשָׁעִים מִמֶּנָּה״ (איוב לח:יג), ״כָּכָה יְהֵא נָעוּר וָרִיק״ (נחמיה ה:יג):\",1,0],[2,136,88,16,\"אָפוּנָה. מְיֻשֶּׁבֶת וּמְבֻסֶּסֶת אֵימָתְךָ בְּלִבִּי, אָפוּנָה לְשׁוֹן ״דָּבָר דָּבֻר עַל אָפְנָיו״ (משלי כה:יא), עַל מְכוֹנָיו:\",2,0],[2,136,88,19,\"מְיֻדָּעַי מַחְשָׁךְ. נֶחְשַׁכְתִּי וְנֶחְדַּלְתִּי מֵהֶם:\",1,0],[2,136,89,1,\"לְאֵיתָן הָאֶזְרָחִי. גַּם הוּא אֶחָד מִן חֲמִשָּׁה אַחִים הַמְשׁוֹרְרִים, וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ (בבא בתרא טו.) בְּאַבְרָהָם אָבִינוּ עַל שֵׁם ״מִי הֵעִיר מִמִּזְרָח״ (ישעיהו מא:ב):\",1,0],[2,136,89,2,\"אוֹדִיעַ אֱמוּנָתְךָ בְּפִי. אֶת שֶׁיְּדַעְתִּיךָ, שֶׁאַתָּה שׁוֹמֵר הַבְטָחָתְךָ וּמְאַמֵּן דְּבָרֶיךָ:\",1,0],[2,136,89,3,\"כִּי אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. כִּי אָמַרְתִּי: עַד עוֹלָם יִבָּנֶה בְחֶסֶד כִּסֵּא דָוִד, כְּמוֹ שֶׁנֶּאֱמַר ״וְכֹנַנְתִּי כִּסֵּא מַמְלַכְתּוֹ וְגוֹ׳״ (שמואל ב ז:יג). דָּבָר אַחֵר: סָבוּר הָיִיתִי שֶׁיְּהֵא הָעוֹלָם בָּנוּי בְּחַסְדְּךָ וְתָכִין אֱמוּנָתְךָ בַשָּׁמַיִם, שֶׁתְּהֵא נְכוֹנָה וּמְקֻיֶּמֶת. וּמַה הִיא הָאֱמוּנָה? אוֹתָהּ הַהַבְטָחָה שֶׁהִבְטַחְתָּ אֶת דָּוִד עַל יְדֵי נָתָן הַנָּבִיא לֵאמֹר: כָּרַתִּי בְרִית לִבְחִירִי לְהָכִין עַד עוֹלָם זַרְעוֹ:\",1,0],[2,136,89,6,\"וְיוֹדוּ שָׁמַיִם פִּלְאֲךָ. אִם הָיִיתָ שׁוֹמֵר הַבְטָחָתְךָ:\",1,0],[2,136,89,6,\"אַף אֱמוּנָתְךָ. אֱמוּנַת דְּבָרֶיךָ יוֹדוּ בִּקְהַל קְדוֹשִׁים:\",2,0],[2,136,89,7,\"יַעֲרֹךְ לַה׳. יְהֵא נַעֲרָץ כְּמוֹתוֹ:\",1,0],[2,136,89,8,\"בְּסוֹד קְדוֹשִׁים רַבָּה. בְּסוֹד רַב שֶׁל מַלְאָכִים:\",1,0],[2,136,89,10,\"בְּשׂוֹא גַלָּיו. בְּהִנָּשֵׂא גַלָּיו:\",1,0],[2,136,89,10,\"אַתָּה תְשַׁבְּחֵם. תַּשְׁפִּילֵם, וְכֵן ״וְחָכָם בְּאָחוֹר יְשַׁבְּחֶנָּה״ (משלי כט:יא), וְכֵן ״מַשְׁבִּיחַ שְׁאוֹן יַמִּים״ (תהלים סה:ח):\",2,0],[2,136,89,11,\"רָהַב. מִצְרַיִם (ישעיהו ל:ז):\",1,0],[2,136,89,16,\"יוֹדְעֵי תְרוּעָה. שֶׁיּוֹדְעִין לְרַצּוֹת אֶת בּוֹרְאָם בְּרֹאשׁ הַשָּׁנָה בִּתְרוּעָה, שֶׁמְּסַדְּרִים עָלֶיהָ מַלְכֻיּוֹת, זִכְרוֹנוֹת וְשׁוֹפָרוֹת (ויקרא רבה כט, ד):\",1,0],[2,136,89,18,\"וּבִרְצוֹנְךָ. שֶׁאַתָּה מִתְרַצֶּה לָהֶם, אפימאנ״ט בְּלַעַ״ז:\",1,0],[2,136,89,20,\"לַחֲסִידֶיךָ. נָתָן הַנָּבִיא וְגָד הַחוֹזֶה:\",1,0],[2,136,89,20,\"שִׁוִּיתִי עֵזֶר. עַל דָּוִד, לַעֲזוֹר לוֹ תָּמִיד:\",2,0],[2,136,89,23,\"לֹא יַשִּׁיא אוֹיֵב בּוֹ. לֹא יִגְבַּר עָלָיו לִהְיוֹת לוֹ כְּנוֹשֶׁה (שמות כב:כד):\",1,0],[2,136,89,28,\"בְּכוֹר אֶתְּנֵהוּ. גָּדוֹל אֶתְּנֵהוּ:\",1,0],[2,136,89,33,\"וּפָקַדְתִּי בְשֵׁבֶט פִּשְׁעָם. כָּךְ אָמַר לוֹ נָתָן הַנָּבִיא עַל שְׁלֹמֹה (שמואל ב ז:יד): ״אֲשֶׁר בְּהַעֲוֹתוֹ וְהוֹכַחְתִּיו בְּשֵׁבֶט אֲנָשִׁים״, זֶה רְזוֹן בֶּן אֶלְיָדָע שֶׁעָמַד לְשָׂטָן לוֹ, וּבְנִגְעֵי בְנֵי אָדָם זֶה אַשְׁמְדַאי, שֶׁהַשֵּׁדִים בְּנֵי אָדָם הָרִאשׁוֹן הָיוּ (בראשית רבה כ:יא):\",1,0],[2,136,89,36,\"אִם לְדָוִד אֲכַזֵּב. לְשׁוֹן ״לֹא יְכַזְּבוּ מֵימָיו״ (ישעיהו נח:יא), פיילנצ״א בְּלַעַ״ז:\",1,0],[2,136,89,38,\"וְעֵד בַּשָּׁחַק נֶאֱמָן. הַיָּרֵחַ וְהַשֶּׁמֶשׁ עֵדִים לוֹ, שֶׁכָּל זְמַן שֶׁהֵם קַיָּמִים, יִתְקַיֵּם מַלְכוּתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (ירמיהו לג:כ-כא): ״אִם תָּפֵרוּ אֶת בְּרִיתִי הַיּוֹם וְאֶת בְּרִיתִי הַלָּיְלָה גַּם בְּרִיתִי תוּפַר אֶת דָּוִד עַבְדִּי״:\",1,0],[2,136,89,39,\"וְאַתָּה זָנַחְתָּ. דִּקְדַּקְתָּ אַחַר בָּנָיו לַחֲשׁוֹב עֲוֹנָם, עַד אֲשֶׁר זְנַחְתָּם וּמְאַסְתָּם בִּימֵי צִדְקִיָּהוּ (מלכים ב כה:א):\",1,0],[2,136,89,40,\"נֵאַרְתָּה. בִּטַּלְתָּ:\",1,0],[2,136,89,41,\"כָּל גְּדֵרוֹתָיו. שֶׁבָּנָה בִּירוּשָׁלַיִם:\",1,0],[2,136,89,41,\"מִבְצָרָיו. הַר הַבַּיִת וּמְצוּדַת צִיּוֹן:\",2,0],[2,136,89,44,\"אַף תָּשִׁיב צוּר חַרְבּוֹ. הֲשִׁיבוֹתָ אָחוֹר וְהָפַכְתָּ אֶת חִדּוּד חַרְבּוֹ, כְּמוֹ ״חַרְבוֹת צֻרִים״ (יהושע ה:ב), וְכֵן ״כָּל כְּלִי יוּצַר עָלַיִךְ״ (ישעיהו נד:יז):\",1,0],[2,136,89,44,\"וְלֹא הֲקֵימוֹתוֹ. וְלֹא הֶעֱמַדְתּוֹ מִלִּפּוֹל:\",2,0],[2,136,89,45,\"הִשְׁבַּתָּ מִטְּהָרוֹ. זְרִיחָתוֹ, כְּמוֹ ״צָהֳרַיִם״ דִּמְתַרְגְּמִינָן: ״טִיהֲרָא״, וּכְמוֹ (שמות כד:י) ״וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר״:\",1,0],[2,136,89,45,\"לָאָרֶץ מִגַּרְתָּה. הִשְׁפַּלְתָּ וְהִשְׁחַתָּ, כָּל לְשׁוֹן שְׁחִיָּה בְּתַרְגּוּם יוֹנָתָן ״מְגַר״:\",2,0],[2,136,89,48,\"זְכׇר אֲנִי מֶה חָלֶד. מַה זִּקְנָה יֵשׁ לִי? הֲלֹא מְעַט יָמַי, וְדַי לְךָ שֶׁאַתָּה נִפְרָע מִמֶּנִּי בְּמוֹתִי קְצַר יָמִים:\",1,0],[2,136,89,48,\"עַל מַה שָּׁוְא. לְחִנָּם וְלַהֶבֶל בָּרָאתָ כָל בְּנֵי אָדָם:\",2,0],[2,136,89,51,\"שְׂאֵתִי בְחֵיקִי כָּל רַבִּים עַמִּים. בַּגּוֹלָה אֲנִי נוֹשֵׂא סִבְלָם וּמַשָּׂאָם:\",1,0],[2,136,89,52,\"עִקְּבוֹת מְשִׁיחֶךָ. סוֹפֵי מֶלֶךְ הַמָּשִׁיחַ, וּלְשׁוֹן מִשְׁנָה הוּא (סוטה ט,טו): בְּעִקְּבוֹת הַמָּשִׁיחַ חוּצְפָּא יִסְגֵּא:\",1,0],[2,136,89,53,\"בָּרוּךְ ה׳ לְעוֹלָם. עַל כָּל אֲשֶׁר עָשָׂה לָנוּ:\",1,0],[2,136,90,1,\"תְּפִלָּה לְמֹשֶׁה. אַחַד עָשָׂר מִזְמוֹרִים מִכָּאן עַד ״לְדָוִד מִזְמוֹר״ (תהלים קא:א), כֻּלָּם מֹשֶׁה אֲמָרָם. כְּנֶגְדָּם בֵּרַךְ אַחַד עָשָׂר בְּרָכוֹת לְאַחַד עָשָׂר שְׁבָטִים בְּזֹאת הַבְּרָכָה (דברים לג:א):\",1,0],[2,136,90,1,\"מָעוֹן אַתָּה הָיִיתָ לָּנוּ. מָעוֹן מָדוֹר וּמָנוֹס לָבֹא שָׁם הָיִיתָ לָנוּ:\",2,0],[2,136,90,1,\"בְּדֹר וָדֹר. מֵעוֹלָם, כִּי אַתָּה מִקֶּדֶם הַכֹּל הָיִיתָ:\",3,0],[2,136,90,2,\"בְּטֶרֶם הָרִים יוּלָּדוּ. נִבְרְאוּ, וּבְטֶרֶם חוֹלַלְתָּ אֶרֶץ וְתֵבֵל. וּמֵעוֹלָם רִאשׁוֹן וְעַד עוֹלָם אַחֲרוֹן אַתָּה אֵל:\",1,0],[2,136,90,3,\"תָּשֵׁב אֱנוֹשׁ עַד דַּכָּא. מֵבִיא אַתָּה יִסּוּרִין עַל הָאָדָם עַד שֶׁאַתָּה מַחֲזִירוֹ לִהְיוֹת תְּשׁוּשׁ כֹּחַ וְקָרוֹב לַמָּוֶת, וַתֹּאמֶר לוֹ בְּיִסּוּרִין שׁוּבוּ בְנֵי אָדָם מִדַּרְכֵיכֶם הָרָעִים:\",1,0],[2,136,90,4,\"כִּי אֶלֶף שָׁנִים בְּעֵינֶיךָ. אֶלֶף שָׁנִים שֶׁל בְּנֵי אָדָם הֵם כְּיוֹם אֶחָד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְעוֹד מִן הַלַּיְלָה עִמּוֹ, כִּי יוֹם אֶחָד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְעַט מִן הַלַּיְלָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם אֶלֶף שָׁנִים, שֶׁהֲרֵי לֹא אָמַר הַכָּתוּב שֶׁיְּהֵא יוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶחָד כְּאֶלֶף שָׁנִים, אֲבָל כְּשֶׁיָּצָא מְעַט מִן הַלַּיְלָה עִמּוֹ אָז יוֹמוֹ שָׁלֵם וַהֲוֵי אֶלֶף שָׁנִים, וּלְכָךְ מֵת אָדָם הָרִאשׁוֹן תּוֹךְ אֶלֶף, שֶׁאִם הָיָה חַי אֶלֶף הָיָה יוֹתֵר מִיּוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְשֶׁמָּא שִׁעוּר אוֹתָהּ אַשְׁמוּרָה הוּא כְּמוֹ שֶׁיֵּשׁ מִמִּיתַת אָדָם הָרִאשׁוֹן עַד אֶלֶף שָׁנִים, וַאֲנַן לֹא יָדְעִינָן כַּמָּה הֲוֵי אוֹתָהּ אַשְׁמוּרָה כִּי אִם מִסְּבָרָא (מצאתי). כִּי אֶלֶף שָׁנִים בְּעֵינֶיךָ וְגוֹ׳. וּכְשֶׁעָלְתָה תְשׁוּבָה בְּדַעְתְּךָ מִתְּחִלָּה יָפֶה דַּנְתָּ וּבָרָאתָ אוֹתָהּ, וּרְאוּיִין הָיוּ הַשָּׁנִים לְכָךְ לְפִי (שֶׁלֹּא) הָיוּ יְמֵי בְּנֵי אָדָם רַבִּים שֶׁלֹּא הָיוּ אֶלֶף שָׁנִים בְּעֵינֶיךָ אֶלָּא כְּיוֹם הוֹלֵךְ שֶׁעָבַר וְחָלַף וּמְעַט מִן הַלַּיְלָה עִמּוֹ, שֶׁהֲרֵי אָמַרְתָּ לְאָדָם הָרִאשׁוֹן (בראשית ב:יז) ״כִּי בְּיוֹם אֲכָלְךָ מִמֶּנּוּ מוֹת תָּמוּת״ וְחָיָה תְּשַׁע מֵאוֹת וּשְׁלֹשִׁים שָׁנָה, נִמְצְאוּ אֶלֶף שָׁנִים עוֹלִים לְיוֹם שָׁלֵם וּמְעַט מִן הַלַּיְלָה עִמּוֹ:\",1,0],[2,136,90,4,\"כְּיוֹם אֶתְמוֹל כִּי יַעֲבֹר. שֶׁכְּבָר עָבַר:\",2,0],[2,136,90,5,\"זְרַמְתָּם שֵׁנָה יִהְיוּ. עַכְשָׁיו חֲטַפְתָּם לְאוֹתָם הַשָּׁנִים וַהֲבֵאתָם לְיָמִים מוּעָטִים, שֶׁאֵינָם אֶלָּא כְּשֵׁנַת תְּנוּמָה; שֶׁשְּׁנֵי הַדּוֹרוֹת שִׁבְעִים שָׁנָה הֵם, כְּמוֹ שֶׁמְּפֹרָשׁ בְּסוֹף הָעִנְיָן: יְמֵי שְׁנוֹתֵינוּ בָהֶם שִׁבְעִים שָׁנָה, וְהֵם חֲשׁוּבִים שֵׁנָה אַחַת; כְּעִנְיָן (תהלים קכו:א) ״בְּשׁוּב ה׳ אֶת שִׁיבַת צִיּוֹן הָיִינוּ כְּחֹלְמִים״, וְעַל שִׁבְעִים שָׁנָה שֶׁל גָּלוּת בָּבֶל נֶאֱמַר:\",1,0],[2,136,90,5,\"זְרַמְתָּם. לְשׁוֹן שְׁטִיפָה, כְּמוֹ ״זֶרֶם מַיִם״ (חבקוק ג:י):\",2,0],[2,136,90,5,\"בַּבֹּקֶר כֶּחָצִיר יַחֲלֹף. הַנּוֹלָד בַּלַּיְלָה מֵת בַּבֹּקֶר, לְסוֹף הַשֵּׁנָה; וְאִם\",3,0],[2,136,90,6,\"בַּבֹּקֶר יָצִיץ. מִיָּד חָלַף, וְעַד בֹּא הָעֶרֶב יְמוֹלֵל וְיָבֵשׁ, לָמָּה?\",1,0],[2,136,90,7,\"כִּי כָלִינוּ בְאַפֶּךָ וְגוֹ׳. וְעַל כָּל זֹאת:\",1,0],[2,136,90,8,\"שַׁתָּה עֲוֺנֹתֵינוּ לְנֶגְדֶּךָ, וְאֶת עֲלֻמֵנוּ – אֶת חַטֹּאת נְעוּרֵינוּ, שַׂמְתָּ לִמְאוֹר פָּנֶיךָ:\",1,0],[2,136,90,8,\"עֲלֻמֵינוּ. נְעוּרֵינוּ, כְּמוֹ (שמואל א יז:נו) ״בֶּן מִי זֶה הָעֶלֶם״:\",2,0],[2,136,90,8,\"לִמְאוֹר פָּנֶיךָ. לְמוּלְךָ לְהַבִּיט בָּהֶם:\",3,0],[2,136,90,9,\"פָּנוּ בְעֶבְרָתֶךָ. וּפָנוּ וְנִבְעֲרוּ וְהָלְכוּ לָהֶם בְּעֶבְרָתֶךָ:\",1,0],[2,136,90,9,\"כְּמוֹ הֶגֶה. כְּדִבּוּר הַמְּמַהֵר לִכְלוֹת:\",2,0],[2,136,90,10,\"יְמֵי שְׁנוֹתֵינוּ בָהֶם שִׁבְעִים שָׁנָה. שְׁנוֹתֵינוּ אֵלֶּה בַּעֲוֹנוֹתֵינוּ אֵלֶּה וּבַעֲלוּמֵינוּ אֵלֶּה שִׁבְעִים שָׁנָה הֵם:\",1,0],[2,136,90,10,\"וְאִם בִּגְבוּרוֹת. וְאִם הַרְבֵּה גָּבְרוּ יָמָיו, שְׁמוֹנִים שָׁנָה הֵם:\",2,0],[2,136,90,10,\"וְרָהְבָּם עָמָל וָאָוֶן. וְכָל הַגְּדֻלָּה וְהַשְּׂרָרָה שֶׁיֵּשׁ לוֹ לָאָדָם בַּיָּמִים הָאֵלֶּה אֵינָם אֶלָּא עָמָל וָאָוֶן, וְלָמָּה? שֶׁהֲרֵי כִּי גָז חִישׁ וַנָּעֻפָה. בְּתוֹךְ עֶבְרָה מַהֵר אָנוּ עָפִים וּמֵתִים:\",3,0],[2,136,90,10,\"גָּז. לְשׁוֹן הַעֲבָרָה, כְּמוֹ ״נָגֹזּוּ וְעָבָר״ (נחום א:יב), ״וַיָּגָז שַׂלְוִים מִן הַיָּם״ (במדבר יא:לא):\",4,0],[2,136,90,11,\"מִי יוֹדֵעַ עֹז אַפֶּךָ. בְּיָמִים מוּעָטִים כָּאֵלֶּה מִי יִקְנֶה לוֹ לֵב לָדַעַת אֶת עֹז אַפְּךָ לְיִרְאָה אוֹתְךָ, וְאַתָּה כְיִרְאָתְךָ עֶבְרָתֶךָ. כְּשֵׁם שֶׁאַתָּה יָרָאוּי כֵּן עֶבְרָתְךָ קָשָׁה, וְנִפְרָע מִן הַחוֹטְאִים:\",1,0],[2,136,90,12,\"לִמְנוֹת יָמֵינוּ כֵּן הוֹדַע. כַּאֲשֶׁר בַּתְּחִלָּה, הוֹדַע בָּעוֹלָם אֶת מִנְיַן יָמֵינוּ אֲרֻכִּים, וְכֵיוָן שֶׁנַּאֲרִיךְ יָמִים, נוּכַל לִקְנוֹת לֵב וְנָבִיא בְּתוֹכָם לְבַב חָכְמָה. וְנָבִיא לְשׁוֹן הֲבָאָה (בבא בתרא יב.). (וְיֵשׁ אוֹמְרִים לִמְנוֹת יָמֵינוּ כֵּן, כִּמְנִין כ״ן – שִׁבְעִים שָׁנָה, וְנָמוּת לְפִי שִׁעוּר יָמֵינוּ שֶׁהֵן מְעַט, כֵּן תְּיַסֵּר אוֹתָנוּ וְכֵן ״וַיֹּדֵעַ בָּהֶם אַנְשֵׁי סֻכּוֹת״ (שופטים ח:טז) (ס״א אינו)):\",1,0],[2,136,90,13,\"שׁוּבָה ה׳. מֵחֲרוֹן אַפֶּךָ:\",1,0],[2,136,90,13,\"וְהִנָּחֵם. חֲשׁוֹב מַחֲשָׁבָה טוֹבָה עַל עֲבָדֶיךָ:\",2,0],[2,136,90,14,\"שַׂבְּעֵנוּ בַבֹּקֶר חַסְדֶּךָ. בְּיוֹם הַגְּאֻלָּה וְהַתְּשׁוּעָה, שֶׁהוּא בֹּקֶר לְלֵיל הַצָּרָה וְהָאֲנָחָה וְהַחֲשֵׁכָה:\",1,0],[2,136,90,14,\"וּנְרַנְּנָה וְנִשְׂמְחָה בְּכָל יָמֵינוּ. כְּלוֹמַר בְּכָל הַצָּרוֹת שֶׁעָבְרוּ עָלֵינוּ בְּיָמֵינוּ אֵלֶּה:\",2,0],[2,136,90,15,\"שַׂמְּחֵנוּ כִּימוֹת עִנִּיתָנוּ. שַׂמְּחֵנוּ לִימוֹת מְשִׁיחֵנוּ כְּמִנְיַן יָמוֹת שֶׁעִנִּיתָנוּ בַּגָּלֻיּוֹת, וּכְמִנְיַן שְׁנוֹת אֲשֶׁר רָאִינוּ רָעָה:\",1,0],[2,136,90,17,\"וִיהִי נֹעַם אֲדֹ׳ אֱלֹהֵינוּ. שְׁכִינָתוֹ וְתַנְחוּמָיו:\",1,0],[2,136,90,17,\"וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ. לְשׁוֹן תְּחִנָּה הוּא, כּוֹנְנָה כְּמוֹ ״שָׁמְרָה״ (תהלים כה:כ) ״שָׁפְטָה״ (תהלים פב:ח):\",2,0],[2,136,90,17,\"כּוֹנְנֵהוּ. כּוֹנֵן אוֹתוֹ, וּשְׁנֵי פְּעָמִים וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנֵהוּ: אֶחָד עַל מְלֶאכֶת הַמִּשְׁכָּן, שֶׁבֵּרְכָן לְיִשְׂרָאֵל וְהִתְפַּלֵּל שֶׁתִּשְׁרֶה שְׁכִינָה בְּמַעֲשֵׂה יְדֵיהֶם בַּמִּשְׁכָּן, וְאַחַת שֶׁתְּהֵא בְּרָכָה בְּמַעֲשֵׂה יְדֵיהֶם:\",3,0],[2,136,91,1,\"יוֹשֵׁב בְּסֵתֶר עֶלְיוֹן. מִי שֶׁהוּא חוֹסֶה בְּסֵתֶר כַּנְפֵי הַשְּׁכִינָה, הוּא יִתְלוֹנָן בְּצִלּוֹ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵגִין עָלָיו. הֲרֵי מֹשֶׁה רַבֵּינוּ זֶה מַשִּׂיא אֶת בְּנֵי הָאָדָם לַחֲסוֹת בְּכַנְפֵי הַשְּׁכִינָה:\",1,0],[2,136,91,1,\"יוֹשֵׁב בְּסֵתֶר עֶלְיוֹן. כְּמוֹ ״בְּצִלּוֹ חָמַדְתִּי וְיָשַׁבְתִּי״ (שיר השירים ב:ג):\",2,0],[2,136,91,1,\"שַׁדַּי. לְשׁוֹן חוֹזֶק:\",3,0],[2,136,91,2,\"אוֹמַר לַה׳ מַחְסִי. הוּא וּמְצוּדָתִי, וְהַכֹּל יִלְמְדוּ מִמֶּנִּי. וְלָמָּה אֲנִי אוֹמֵר כֵּן?\",1,0],[2,136,91,3,\"כִּי הוּא יַצִּילְךָ מִפַּח יָקוּשׁ וְגוֹ׳. לְכָל אֶחָד וְאֶחָד הוּא אוֹמֵר יוֹשֵׁב בְּסֵתֶר עֶלְיוֹן:\",1,0],[2,136,91,4,\"בְּאֶבְרָתוֹ. כָּנָף:\",1,0],[2,136,91,4,\"יָסֶךְ. יְסוֹכֵךְ:\",2,0],[2,136,91,4,\"תֶּחְסֶה. תִּתְכַּסֶּה:\",3,0],[2,136,91,4,\"צִנָּה וְסֹחֵרָה. הוּא צִנָּה הַמַּקֶּפֶת אֶת הָאָדָם קָרוֹב לְאַרְבַּע רוּחוֹתָיו, סֹחֵרָה לְשׁוֹן סְחוֹר סְחוֹר (שבת יג.):\",4,0],[2,136,91,5,\"לֹא תִירָא. אִם תִּבְטַח בּוֹ:\",1,0],[2,136,91,5,\"מֵחֵץ יָעוּף יוֹמָם. שֵׁד הַמְּעוֹפֵף כְּחֵץ:\",2,0],[2,136,91,6,\"מִדֶּבֶר וּמִקֶּטֶב. שֵׁמוֹת שֵׁדִים הֵם, זֶה מַזִּיק בַּלַּיְלָה וְזֶה מַזִּיק בַּצָּהֳרַיִם (פסחים קיא:):\",1,0],[2,136,91,6,\"יָשׁוּד. ״יְשׁוֹדֵד״ (הושע י:ב):\",2,0],[2,136,91,7,\"יִפֹּל מִצִּדְּךָ אֶלֶף. לְשׁוֹן חֲנִיָּה, כְּמוֹ ״עַל פְּנֵי כָל אֶחָיו נָפָל״ (בראשית כה:יח):\",1,0],[2,136,91,7,\"מִצִּדְּךָ. מִשְּׂמֹאלְךָ יַחֲנוּ אֶלֶף שֵׁדִים, וְאֵלֶיךָ לֹא יִגָּשׁ לְהַזִּיק:\",2,0],[2,136,91,8,\"וְשִׁלֻּמַת. כִּלָּיוֹן, וְלָמָּה?\",1,0],[2,136,91,9,\"כִּי אַתָּה. אָמַרְתָּ ה׳ מַחְסִי. וַהֲרֵי זֶה מִקְרָא קָצָר:\",1,0],[2,136,91,9,\"עֶלְיוֹן שַׂמְתָּ מְעוֹנֶךָ. אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא שַׂמְתָּ מְעוֹן מִבְטַחֲךָ:\",2,0],[2,136,91,10,\"לֹא תְאֻנֶּה. לֹא תִקְרֶה, וְכֵן ״וְהָאֱלֹהִים אִנָּה לְיָדוֹ״ (שמות כא:יג):\",1,0],[2,136,91,12,\"פֶּן תִּגֹּף. פֶּן תִּכָּשֵׁל, וְכֵן כָּל לְשׁוֹן נְגִיפָה; אצופי״ר בְּלַעַ״ז:\",1,0],[2,136,92,1,\"מִזְמוֹר שִׁיר. שֶׁל לְוִיִּם (נְבִיאִים):\",1,0],[2,136,92,1,\"לְיוֹם הַשַּׁבָּת. שֶׁאוֹמְרִים אוֹתוֹ בְּשַׁבָּתוֹת, וְהוּא מְדַבֵּר בְּעִנְיַן הָעוֹלָם הַבָּא שֶׁכֻּלּוֹ שַׁבָּת (ראש השנה לא.):\",2,0],[2,136,92,3,\"לְהַגִּיד בַּבֹּקֶר חַסְדֶּךָ. בְּעֵת הַגְּאֻלָּה:\",1,0],[2,136,92,3,\"וֶאֱמוּנָתְךָ בַּלֵּילוֹת. וּבְעוֹד צָרַת הַגָּלוּת לְהַאֲמִין בְּךָ שֶׁתִּשְׁמֹר הַבְטָחָתְךָ, כָּל זֶה נָאֶה וְטוֹב:\",2,0],[2,136,92,4,\"עֲלֵי עָשׂוֹר וַעֲלֵי נָבֶל. כִּנּוֹר שֶׁל עֲשָׂרָה נִימִין (ערכין יג:):\",1,0],[2,136,92,7,\"אִישׁ בַּעַר לֹא יֵדָע. אֶת הָאָמוּר לְמַטָּה:\",1,0],[2,136,92,8,\"בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב. אֵינָם יוֹדְעִים שֶׁהַפְרָחָתָם אֵינָהּ אֶלָּא לְהַשְׁמִידָם עֲדֵי עַד, שֶׁמְּשַׁלֵּם לְשׂוֹנְאָיו עַל פְּנֵיהֶם לְהַאֲבִידָם (דברים ז:י):\",1,0],[2,136,92,9,\"וְאַתָּה מָרוֹם. בְּכָל מִשְׁפָּטֶיךָ יָדְךָ עַל הָעֶלְיוֹנָה, שֶׁהַכֹּל מַצְדִּיקִים עֲלֵיהֶם אֶת דִּינְךָ:\",1,0],[2,136,92,11,\"בַּלֹּתִי בְּשֶׁמֶן רַעֲנָן. לְבַלּוֹתִי בְּשֶׁמֶן שֶׁל שְׂרָרָה, בַּלֹּתִי כְּמוֹ (במדבר טו:ט) ״בָּלוּל בַּשֶּׁמֶן״:\",1,0],[2,136,92,12,\"בְּשׁוּרָי. בְּעוֹיְינַי, כְּמוֹ ״בְּשׁוֹרְרַי״ (תהלים ה:ט):\",1,0],[2,136,92,12,\"בַּקָּמִים עָלַי מְרֵעִים. עַל הָרְשָׁעִים הַקָּמִים עָלַי שָׁמְעוּ אָזְנַי מֵאֲחוֹרֵי הַפַּרְגּוֹד (סנהדרין פט:) שֶׁלֹּא יוֹעִילוּ לְכַלּוֹת אוֹתָנוּ, כָּךְ שָׁמַעְתִּי:\",2,0],[2,136,92,13,\"צַדִּיק כַּתָּמָר יִפְרָח וְגוֹ׳. כַּתָּמָר – לַעֲשׂוֹת פֵּרוֹת, וּכְאֶרֶז בַּלְּבָנוֹן – לְהַחֲלִיף גִּזְעוֹ:\",1,0],[2,136,92,14,\"שְׁתוּלִים. יִהְיוּ הַצַּדִּיקִים בְּבֵית ה׳:\",1,0],[2,136,92,15,\"יְנוּבוּן. יִצְמְחוּן:\",1,0],[2,136,92,15,\"דְּשֵׁנִים. שְׁמֵנִים וְרַעֲנַנִּים יִהְיוּ, וְאָז יַגִּידוּ כִּי יָשָׁר ה׳:\",2,0],[2,136,93,1,\"ה׳ מָלַךְ. יֹאמְרוּ לֶעָתִיד:\",1,0],[2,136,93,1,\"אַף תִּכּוֹן תֵּבֵל. בְּמָלְכוֹ תִּשְׂמַח הָאָרֶץ:\",2,0],[2,136,93,3,\"נָשְׂאוּ נְהָרוֹת ה׳. לְשׁוֹן צְעָקָה וְקוֹבְלָן הוּא זֶה: אֲהָהּ ה׳, הִנֵּה הָאֻמּוֹת הַשּׁוֹטְפִים כַּנְּהָרוֹת נָשְׂאוּ קוֹלָם יֶהֱמָיוּן, וְאֶת דּוּךְ עָמְקֵי נִבְכֵיהֶם יִשְׂאוּ וְיַגְבִּיהוּ תָּמִיד לְהִתְגָּאוֹת נֶגְדֶּךָ. כָּל לְשׁוֹן דָּכָא לְשׁוֹן עֹמֶק וְשִׁפְלוּת:\",1,0],[2,136,93,4,\"מִקֹּלוֹת מַיִם רַבִּים וְגוֹ׳. יָדַעְתִּי אֲנִי, כִּי יוֹתֵר מִקּוֹלוֹת הַמַּיִם הָרַבִּים אֲשֶׁר יֶהֱמָיוּן עָלֵינוּ (ישעיה יז:יב), וּמֵאַדִּירֵי מִשְׁבְּרֵי הַיָּם הַזֶּה, אַתָּה אַדִּיר בַּמָּרוֹם ה׳, וְיָדְךָ תַּקִּיפָה עֲלֵיהֶם:\",1,0],[2,136,93,5,\"עֵדֹתֶיךָ. שֶׁהֵעִידוּ וְהִבְטִיחוּ נְבִיאֶיךָ לְבֵיתְךָ, שֶׁהוּא נַאֲוָה קֹדֶשׁ:\",1,0],[2,136,93,5,\"נֶאֶמְנוּ מְאֹד לְבֵיתְךָ. וּלְאֹרֶךְ יָמִים הוּא מְצַפֶּה לָהֶם, וְאַף עַל פִּי שֶׁאָרְכוּ הַיָּמִים, נֶאֱמָנִים הֵם לַה׳ מְאֹד:\",2,0],[2,136,93,5,\"נַאֲוָה. כְּמוֹ ״נְאוֹת אֱלֹהִים״ (תהלים פג:יג), לְשׁוֹן נָוֶה. וְתֵדַע שֶׁכָּל נָאוֶה שֶׁבַּמִּקְרָא אֵינָן מְפִיקִין אָלֶ״ף, לְפִי שֶׁהֵם לְשׁוֹן נוֹי, וְזֶה מֵפִיק אָלֶ״ף:\",3,0],[2,136,94,1,\"הוֹפִיעַ. הֶרְאָה וְגַלֵּה לָנוּ אֶת נִקְמָתְךָ:\",1,0],[2,136,94,4,\"יִתְאַמְּרוּ. יִשְׁתַּבְּחוּ, כְּמוֹ ״הֶאֱמַרְתָּ״ וְ״הֶאֱמִירְךָ״ (דברים כו:יז-יח):\",1,0],[2,136,94,8,\"בִּינוּ בּוֹעֲרִים בָּעָם. קְצָת שׁוֹטִים שֶׁבָּעוֹלָם:\",1,0],[2,136,94,9,\"הֲנֹטַע אֹזֶן. שֶׁמָּא הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנָּטַע אֹזֶן, לֹא יִשְׁמָע צַעֲקַת עַמּוֹ וְעָנְיוֹ?\",1,0],[2,136,94,10,\"הֲלֹא יוֹכִיחַ. יְיַסֵּר אֶתְכֶם עַל כָּךְ:\",1,0],[2,136,94,11,\"ה׳ יוֹדֵעַ. מַחְשְׁבוֹתֵיכֶם שֶׁאַתֶּם סְבוּרִין לְהִתְגָּאוֹת בְּנֵזֶר הַמְּלוּכָה, וְתֵדְעוּ כִּי הֶבֶל הֵם:\",1,0],[2,136,94,12,\"אַשְׁרֵי הַגֶּבֶר. אַשְׁרֵיהֶם הַצַּדִּיקִים הַמְעֻנִּים תַּחַת יְדֵיכֶם, וּבִלְבַד שֶׁיִּהְיוּ עוֹסְקִין בַּתּוֹרָה וּבַמִּצְווֹת (תנחומא, מקץ טז):\",1,0],[2,136,94,13,\"לְהַשְׁקִיט לוֹ מִימֵי רָע. כִּי הַיִּסּוּרִין גּוֹרְמִין לוֹ לְהַשְׁקִיט לָהֶם מִימֵי דִּין גֵּיהִנֹּם, עַד שֶׁיִּרְאֶה שֶׁיִּכָּרֶה לָרָשָׁע שַׁחַת:\",1,0],[2,136,94,15,\"כִּי עַד צֶדֶק יָשׁוּב מִשְׁפָּט. הַיִּסּוּרִין שֶׁלָּהֶם, עַד שֶׁיִּצְדְּקוּ בִּשְׁבִילָם. וְאַחַר הַמִּשְׁפָּט כָּל יִשְׁרֵי לֵב יִתְקַבְּצוּ, כִּי יִטְּלוּ שְׂכָרָם:\",1,0],[2,136,94,16,\"מִי יָקוּם לִי. זְכוּת מִי יַעֲמֹד לָנוּ בֵּין הַמְּרֵעִים הַלָּלוּ?\",1,0],[2,136,94,17,\"דּוּמָה. ״דּוּמִיָּה״ (תהלים לט:ג):\",1,0],[2,136,94,20,\"הֲיְחָבְרְךָ כִּסֵּא הַוּוֹת. הֲיוּכַל לְהִדָּמוֹת לְךָ הָאֻמּוֹת הַיּוֹצְרִים צְלָמִים וּמַסֵּכוֹת שֶׁל עָמָל?\",1,0],[2,136,94,20,\"עֲלֵי חֹק. בִּשְׁבִיל חֹק, לִהְיוֹת חֹק לָהֶם עֲבוֹדָתָם:\",2,0],[2,136,94,21,\"יָגוֹדּוּ. יֵאָסְפוּ גְדוּדִים עַל נֶפֶשׁ צַדִּיק לַהֲרֹג:\",1,0],[2,136,94,21,\"יַרְשִׁיעוּ. יְחַיְּבוּ בַדִּין לְהָרְגוֹ:\",2,0],[2,136,94,23,\"אוֹנָם. אוֹנְסָם, כְּמוֹ ״יִצְפֹּן לְבָנָיו אוֹנוֹ״ (איוב כא:יט):\",1,0],[2,136,95,4,\"וְתוֹעֲפוֹת. לְשׁוֹן גֹּבַהּ, כְּעוֹף הַמְּעוֹפֵף:\",1,0],[2,136,95,6,\"נִבְרְכָה. לְשׁוֹן ״וַיַּבְרֵךְ אֶת הַגְּמַלִּים״ (בראשית כד:יא):\",1,0],[2,136,95,7,\"הַיּוֹם. בָּעוֹלָם הַזֶּה אִם בְּקוֹלוֹ תִשְׁמָעוּ:\",1,0],[2,136,95,9,\"בְּחָנוּנִי. חִנָּם:\",1,0],[2,136,95,9,\"גַּם רָאוּ פָעֳלִי. בְּמִצְרָיִם (שמות ז:ג-יב:לו):\",2,0],[2,136,95,10,\"אַרְבָּעִים שָׁנָה. קַטְתִּי בָהֶם, רַבְתִּי עִמָּהֶם, לְשׁוֹן ״נָקְטָה נַפְשִׁי בְּחַיָּי״ (איוב י:א). נִלְחַמְתִּי בָם אַרְבָּעִים שָׁנָה לַהֲמִיתָם בַּמִּדְבָּר, כִּי אָמַרְתִּי תֹּעֵי לֵבָב הֵם:\",1,0],[2,136,95,11,\"אֶל מְנוּחָתִי. לְאֶרֶץ יִשְׂרָאֵל וְלִירוּשָׁלַיִם אֲשֶׁר קְרָאתִים מְנוּחָה, שֶׁנֶּאֱמַר (תהלים קלב:יד) ״זֹאת מְנוּחָתִי עֲדֵי עַד״:\",1,0],[2,136,96,1,\"שִׁיר חָדָשׁ. מִזְמוֹר זֶה עַל הֶעָתִיד, וְסוֹפוֹ מוֹכִיחַ כִּי בָא לִשְׁפֹּט אֶת הָאָרֶץ. בְּכָל מָקוֹם שִׁיר חָדָשׁ עַל הֶעָתִיד:\",1,0],[2,136,96,7,\"הָבוּ לַה׳ מִשְׁפְּחוֹת עַמִּים. וּמָה תִּתְּנוּ לוֹ? הָבוּ לַה׳ כָּבוֹד וָעֹז:\",1,0],[2,136,96,10,\"ה׳ מָלָךְ. לֶעָתִיד לָבוֹא יְהֵא שִׁיר זֶה:\",1,0],[2,136,96,10,\"יָדִין עַמִּים בְּמֵישָׁרִים. אוֹתָם שֶׁיַּהֲפֹךְ לָהֶם שָׂפָה בְרוּרָה (צפניה ג:ט):\",2,0],[2,136,96,10,\"בְּמֵישָׁרִים. זְכֻיּוֹת:\",3,0],[2,136,96,11,\"יִרְעַם הַיָּם. לְהָרִים קוֹל בִּתְהִלָּה:\",1,0],[2,136,96,12,\"כָּל עֲצֵי יָעַר. כָּל שָׁלְטוֹנֵי הָאֻמּוֹת:\",1,0],[2,136,97,1,\"ה׳ מָלַךְ. בְּנָטְלוֹ הַמְּלוּכָה מֵעֲמָלֵק וּמִזַּרְעוֹ (שמות יז:יד-טז):\",1,0],[2,136,97,1,\"תָּגֵל הָאָרֶץ. זֶהוּ שֶׁאָמַר (יחזקאל לה:יד) ״כִּשְׂמוֹחַ כָּל הָאָרֶץ שְׁמָמָה אֶעֱשֶׂה לָּךְ״, עַל עֲמָלֵק נִתְנַבֵּא כֵּן:\",2,0],[2,136,97,3,\"אֵשׁ לְפָנָיו תֵּלֵךְ. בְּמִלְחֶמֶת גּוֹג וּמָגוֹג, דִּכְתִיב בְּמִלְחַמְתּוֹ (יחזקאל לח:כב) ״וְנִשְׁפַּטְתִּי אִתּוֹ בְּדֶבֶר וּבְדָם וְגֶשֶׁם שׁוֹטֵף וְאַבְנֵי אֶלְגָּבִישׁ אֵשׁ וְגָפְרִית״:\",1,0],[2,136,97,4,\"בְּרָקָיו. זָהֳרוּרָיו, לָשׁוֹן ״לְמַעַן הֱיֹה לָהּ בָּרָק מוֹרָטָה״ (יחזקאל כא:טו):\",1,0],[2,136,97,4,\"וַתָּחֵל. ״בַּיּוֹם הַהוּא יִהְיֶה רַעַשׁ גָּדוֹל עַל אַדְמַת יִשְׂרָאֵל וְרָעֲשׁוּ מִפָּנָיו דְּגֵי הַיָּם״ (יחזקאל לח:יט-כ):\",2,0],[2,136,97,4,\"וַתָּחֵל. לְשׁוֹן ״חִיל כַּיּוֹלֵדָה״ (תהלים מח:ז; מיכה ד:ט):\",3,0],[2,136,97,5,\"כַּדּוֹנַג נָמַסּוּ. דִּכְתִיב ״וְנֶהֶרְסוּ הֶהָרִים וְנָפְלוּ הַמַּדְרֵגוֹת״ (יחזקאל לח:כ):\",1,0],[2,136,97,5,\"כַּדּוֹנַג. כְּשַׁעֲוָה:\",2,0],[2,136,97,7,\"יֵבֹשׁוּ כָּל עוֹבְדֵי פֶסֶל. דִּכְתִיב (ישעיהו ב:יח) ״וְהָאֱלִילִים כָּלִיל יַחֲלֹף״:\",1,0],[2,136,97,7,\"הַמִּתְהַלְלִים. הַמִּתְפָּאֲרִים לַעֲבוֹדַת גִּלּוּלִים:\",2,0],[2,136,97,8,\"מִשְׁפָּטֶיךָ. נִקְמָתְךָ:\",1,0],[2,136,97,11,\"אוֹר זָרוּעַ לַצַּדִּיק. זְרִיעָה מַמָּשׁ, מוּכֶנֶת לִצְמֹחַ לָהֶם:\",1,0],[2,136,98,1,\"שִׁירוּ לַה׳. כָּל אֵלֶּה לֶעָתִיד:\",1,0],[2,136,98,8,\"נְהָרוֹת יִמְחֲאוּ כָף. הַנְּבִיאִים דִּבְּרוּ בְּלָשׁוֹן שֶׁהָאֹזֶן שׁוֹמַעַת, לֹא שֶׁיְּהֵא לַנְּהָרוֹת כַּף, אֶלָּא לְשׁוֹן שִׂמְחָה וְחֶדְוָה:\",1,0],[2,136,99,1,\"יִרְגְּזוּ עַמִּים. מְדַבֵּר בְּמִלְחֶמֶת גּוֹג וּמָגוֹג, וְאָז יִרְגְּזוּ עַמִּים כְּעִנְיָן שֶׁנֶּאֱמַר (זכריה יד:יב) ״וְזֹאת תִּהְיֶה הַמַּגֵּפָה וְגוֹ׳״:\",1,0],[2,136,99,1,\"תָּנוּט. לְשׁוֹן ״נָטָיוּ רַגְלָי״ (תהלים עג:ב):\",2,0],[2,136,99,3,\"יוֹדוּ שִׁמְךָ. יוֹדוּ אֶת עֹז מֶלֶךְ הָאוֹהֵב מִשְׁפָּט (תהלים עג:ב):\",1,0],[2,136,99,4,\"וְעֹז מֶלֶךְ. מוּסָב עַל מִקְרָא הָעֶלְיוֹן:\",1,0],[2,136,99,4,\"אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. פְּשָׁרָה וְשִׂימַת שָׁלוֹם בֵּין אֲנָשִׁים כּוֹנַנְתָּ, בְּאָמְרְךָ (שמות כג:ה) ״כִּי תִרְאֶה חֲמוֹר שׂוֹנַאֲךָ רוֹבֵץ וְגוֹ׳״, (שמות כג:ד) ״כִּי תִפְגַּע שׁוֹר אוֹיִבְךָ״ וּמִי הוּא שֶׁיִּרְאֶה אֶת שׂוֹנְאוֹ גּוֹמֵל לוֹ חֶסֶד שֶׁלֹּא יִדְּבֶנּוּ לִבּוֹ לְחַבְּקוֹ וּלְנַשְּׁקוֹ, תַּנְחוּמָא (תנחומא, משפטים א):\",2,0],[2,136,99,7,\"בְּעַמּוּד עָנָן יְדַבֵּר אֲלֵיהֶם. אַף עִם שְׁמוּאֵל, וְזֶה הוּא שֶׁנֶּאֱמַר (שמואל א ט:יא-יב) ״הֲיֵשׁ בָּזֶה הָרֹאֶה וַתַּעֲנֶינָה אוֹתָם וַתֹּאמַרְנָה יֵשׁ״, רָאוּ הֶעָנָן קָשׁוּר עַל פִּתְחוֹ, כְּמָה דְאַתְּ אָמַר ״וְיֵשׁ אֲשֶׁר יִהְיֶה הֶעָנָן״ (במדבר ט:כ):\",1,0],[2,136,99,7,\"שָׁמְרוּ עֵדֹתָיו וְחֹק נָתַן לָמוֹ. וְחֹק אֲשֶׁר נָתַן לָמוֹ:\",2,0],[2,136,99,8,\"אֵל נוֹשֵׂא. עֲוֹן יִשְׂרָאֵל:\",1,0],[2,136,99,8,\"הָיִיתָ לָהֶם. בִּשְׁבִילָם:\",2,0],[2,136,99,8,\"וְנוֹקֵם. הָיִיתָ עַל עֲלִילוֹתָם, מֹשֶׁה וְאַהֲרֹן ״שִׁמְעוּ נָא הַמּוֹרִים״ (במדבר כ:י), שְׁמוּאֵל עַל שֶׁלֹּא הִדְרִיךְ בָּנָיו בְּדֶרֶךְ טוֹבָה (שמואל א ח:ג), מֵת בָּחוּר (אגדת בראשית מא:א):\",3,0],[2,136,99,9,\"כִּי קָדוֹשׁ ה׳ אֱלֹהֵינוּ. עַל אֲשֶׁר הוּא מְדַקְדֵּק עִם הַצַּדִּיקִים הוּא מְקֻדָּשׁ בָּעוֹלָם, וְכֵן הוּא אוֹמֵר ״וְנִקְדַּשׁ בִּכְבוֹדִי״ (שמות כט:מג), בִּמְכֻבָּדַי (זבחים קטו:):\",1,0],[2,136,100,1,\"מִזְמוֹר לְתוֹדָה. לְהוֹדָיָה, לְאָמְרוֹ עַל זִבְחֵי תּוֹדָה:\",1,0],[2,136,100,2,\"עִבְדוּ אֶת ה׳ בְּשִׂמְחָה. וְכָל כָּךְ לָמָּה? דְּעוּ כִּי ה׳ הוּא הָאֱלֹהִים כְּשֶׁמְּשַׁלֵּם שְׂכַר פְּעֻלַּתְכֶם, אֲבָל עוֹבְדֵי עֲבוֹדַת גִּלוּלִים אֵין לָהֶם לַעֲבֹד בְּשִׂמְחָה שֶׁאֵין מְשַׁלְּמִין שָׂכָר:\",1,0],[2,136,100,3,\"הוּא עָשָׂנוּ וְלֹא. כְּשֶׁלֹּא הָיִינוּ בָּעוֹלָם:\",1,0],[2,136,100,4,\"בְּתוֹדָה. בְּהוֹדָיָה:\",1,0],[2,136,100,5,\"וְעַד דֹּר וָדֹר. קַיֶּמֶת אֱמוּנָתוֹ. כָּל לְשׁוֹן אֱמֶת וֶאֱמוּנָה, אֲמָנַת הַבְטָחָה, שֶׁמַּאֲמִין וּמַבְטִיחַ הַבְטָחָתוֹ:\",1,0],[2,136,101,1,\"חֶסֶד וּמִשְׁפָּט אָשִׁירָה. כְּשֶׁאַתָּה עוֹשֶׂה עִמִּי חֶסֶד, אֲקַלֶּסְךָ: בָּרוּךְ הַטּוֹב וְהַמֵּטִיב, וּכְשֶׁאַתָּה עוֹשֶׂה בִּי מִשְׁפָּט, אֲנִי אָשִׁיר: בָּרוּךְ דַּיַּן הָאֱמֶת, בֵּין כָּךְ וּבֵין כָּךְ לְךָ ה׳ אֲזַמֵּרָה:\",1,0],[2,136,101,2,\"אַשְׂכִּילָה. אֶתֵּן לֵב עַל דֶּרֶךְ הַתָּמִים:\",1,0],[2,136,101,2,\"מָתַי תָּבוֹא אֵלָי. הַדֶּרֶךְ הַיְשָׁרָה לְהִתְהַלֵּךְ בָּהּ, וְאֶתְהַלֵּךְ בְּתָם לְבָבִי אַף בְּקֶרֶב בֵּיתִי. בְּהַצְנֵעַ כְּמוֹ בְּפַרְהֶסְיָא:\",2,0],[2,136,101,3,\"סֵטִים. לְשׁוֹן ״כִּי תִשְׂטֶה אִשְׁתּוֹ״ (במדבר ה:יב), לָסוּר מִן הַדֶּרֶךְ. דִּישְׁטוֹלְ״מַנְט בְּלַעַ״ז:\",1,0],[2,136,101,4,\"רָע לֹא אֵדָע. לֹא אֹהַב, לֹא אַכִּיר בְּדָבָר רָע:\",1,0],[2,136,101,5,\"אוֹתוֹ לֹא אוּכָל. שֶׁיְּהֵא חֲבֵרִי, שֶׁלֹּא אֶלְמַד מִמַּעֲשָׂיו:\",1,0],[2,136,101,8,\"לַבְּקָרִים אַצְמִית. מִדֵּי יוֹם יוֹם אַכְרִית מְעַט מְעַט רִשְׁעֵי יִשְׂרָאֵל הַמְחֻיָּבִין מִיתָה:\",1,0],[2,136,102,1,\"תְּפִלָּה לְעָנִי. יִשְׂרָאֵל שֶׁהֵם עַם עָנִי:\",1,0],[2,136,102,1,\"כִּי יַעֲטֹף. בְּהִתְעַטֵּף נַפְשָׁם בְּצָרָה (יונה ב:ח):\",2,0],[2,136,102,4,\"נִחָרוּ. הַנּוּ״ן מְשַׁמֶּשֶׁת, כְּמוֹ ״נַעֲשׂוּ״ (תהלים לג:ו), ״נִקְבּוּ״ (במדבר א:יז), וְהוּא לְשׁוֹן יֹבֶשׁ, כְּמוֹ ״וְעַצְמִי חָרָה מִנִּי חֹרֶב״ (איוב ל:ל), ״נָחַר מַפֻּחַ״ (ירמיה ו:כט):\",1,0],[2,136,102,7,\"דָּמִיתִי לִקְאַת מִדְבָּר. לִקְאַת שֵׁם עוֹף הוּא:\",1,0],[2,136,102,7,\"כְּכוֹס חֳרָבוֹת. שֵׁם עוֹף, כְּמוֹ ״אֶת הַכּוֹס וְאֶת הַשָּׁלָךְ וְאֶת הַיַּנְשׁוּף״ (ויקרא יא:יז):\",2,0],[2,136,102,7,\"חֳרָבוֹת. מִדְבָּרוֹת. דָּמִיתִי לִקְאַת מִדְבָּר. כָּךְ אָנוּ נְדוּדִים מִמְּקוֹמֵנוּ לָלֶכֶת בַּגּוֹלָה:\",3,0],[2,136,102,8,\"שָׁקַדְתִּי. הִתְבּוֹנַנְתִּי בְּעַצְמִי וְהִנְּנִי כְּצִפּוֹר הַבּוֹדֵד עַל גָּג, יוֹשֵׁב לְבַדּוֹ בְּאֵין זוּג:\",1,0],[2,136,102,8,\"בּוֹדֵד. יוֹשֵׁב בָּדָד:\",2,0],[2,136,102,9,\"מְהוֹלָלַי. הַמִּתְלוֹצְצִים בִּי, לְשׁוֹן ״הוֹלְלוּת״ (קהלת א:יז):\",1,0],[2,136,102,9,\"בִּי נִשְׁבָּעוּ. רָאוּ בְרָעָתִי וְנִשְׁבָּעִים בִּי וְאוֹמְרִים: אִם לֹא יֶאֱרַע בִּי כְּמוֹ שֶׁאֵרַע לְיִשְׂרָאֵל, כֹּה יַעֲשֶׂה לִי כְּמוֹ לְיִשְׂרָאֵל:\",2,0],[2,136,102,10,\"בִּבְכִי מָסָכְתִּי. בְּדִמְעָה מָזַגְתִּי:\",1,0],[2,136,102,11,\"כִּי נְשָׂאתַנִי. תְּחִלָּה וְהִגְבַּהְתַּנִי, וְעַתָּה הִשְׁלַכְתַּנִי מִשָּׁמַיִם אָרֶץ (איכה ב:א); וְאִם לֹא נְשָׂאתַנִי תְּחִלָּה, לֹא הָיְתָה חֶרְפָּתִי רַבָּה כָּל כָּךְ:\",1,0],[2,136,102,12,\"כְּצֵל נָטוּי. לְעֵת עֶרֶב, כְּשֶׁהַצְּלָלִים נוֹטִים, וּכְשֶׁחֲשֵׁכָה, אֵין נִכָּרִים אֶלָּא כָּלִים וְהוֹלְכִים:\",1,0],[2,136,102,13,\"וְאַתָּה. אֲשֶׁר לְעוֹלָם תֵּשֵׁב, וְנִשְׁבַּעְתָּ לָנוּ בְּךָ (שמות לב:יג) – כְּשֵׁם שֶׁאַתָּה קַיָּם, יֵשׁ עָלֶיךָ לְקַיְּמֵנוּ. לְפִיכָךְ:\",1,0],[2,136,102,14,\"אַתָּה תָקוּם תְּרַחֵם צִיּוֹן כִּי עֵת לְחֶנְנָהּ. כִּי בְךָ הִבְטַחְתָּ (דברים לב:לו) ״כִּי יִרְאֶה כִּי אָזְלַת יָד״, וַהֲרֵי אָזְלַת יָד:\",1,0],[2,136,102,15,\"כִּי רָצוּ. אָהֲבוּ אַף אֶת אֲבָנֶיהָ וְאֶת עֲפָרָהּ. וּמִדְרַשׁ אַגָּדָה: כְּשֶׁיָּצָא יְכָנְיָה וְגָלוּתוֹ, נָשְׂאוּ עִמָּהֶם מֵאַבְנֵי יְרוּשָׁלַיִם וַעֲפָרָהּ לִבְנוֹת לָהֶם בְּבָבֶל בֵּית הַכְּנֶסֶת:\",1,0],[2,136,102,16,\"וְיִירְאוּ גוֹיִם אֶת. שִׁמְךָ כְּשֶׁתּוֹשִׁיעַ אֶת עַמְּךָ:\",1,0],[2,136,102,18,\"הָעַרְעָר. הַצּוֹעֵק, כְּמוֹ (ישעיהו טו:ה) ״זַעֲקַת שֶׁבֶר יְעֹעֵרוּ״. דָּבָר אַחֵר: עַרְעָר, הָרוּס וְנִשְׁחָת, כְּמוֹ (תהלים קלז:ז) ״עָרוּ עָרוּ״:\",1,0],[2,136,102,19,\"תִּכָּתֶב זֹאת. כָּךְ יֹאמְרוּ רוֹאֵי הַיְשׁוּעָה: תִּכָּתֵב הַיְשׁוּעָה הַזֹּאת לְסַפֵּר אוֹתָהּ לְדוֹר אַחֲרוֹן:\",1,0],[2,136,102,19,\"וְעַם נִבְרָא. שֶׁנַּעֲשָׂה בְּרִיָּה חֲדָשָׁה, לָצֵאת מֵעַבְדוּת לְחֵרוּת, מֵאֹפֶל לְאוֹר גָּדוֹל:\",2,0],[2,136,102,20,\"אֶל אֶרֶץ הִבִּיט. לִרְאוֹת בָּעֳנִי עַמּוֹ:\",1,0],[2,136,102,21,\"תְּמוּתָה. חוֹלֶה לָמוּת, אינמורינד״א בְּלַעַ״ז):\",1,0],[2,136,102,24,\"עִנָּה בַדֶּרֶךְ כֹּחִי. חוֹזֵר לְקוֹבְלוֹ הָרִאשׁוֹן: כִּי נְשָׂאתַנִי וַתַּשְׁלִיכֵנִי, יָמַי כְּצֵל נָטוּי, עִנָּה בַדֶּרֶךְ אוֹיְבִי כֹּחִי:\",1,0],[2,136,102,25,\"אוֹמַר. לַה׳ אֵלִי. אַתָּה:\",1,0],[2,136,102,25,\"אַל תַּעֲלֵנִי בַּחֲצִי יָמָי. אַל תְּסַלֵּק אוֹתָנוּ לְהַשְׁמִידֵנוּ מִן הָאֲדָמָה בְּיַד אוֹיְבֵינוּ בַּחֲצִי יָמֵינוּ. וּמַה הֵם יָמֵינוּ? כָּל יְמוֹת דוֹר דּוֹרִים שְׁנוֹתֶיךָ, הִבְטַחְתָּ לְקַיְּמֵנוּ לְפָנֶיךָ, כְּמוֹ שֶׁאָמַר בְּסוֹף הַמִּזְמוֹר וּשְׁנוֹתֶיךָ לֹא יִתָּמּוּ, וְזֶרַע עֲבָדֶיךָ לְפָנֶיךָ יִכּוֹן:\",2,0],[2,136,102,26,\"לְפָנִים. מִתְּחִלָּה:\",1,0],[2,136,102,27,\"כַּלְּבוּשׁ תַּחֲלִיפֵם. כְּאָדָם הַהוֹפֵךְ לְבוּשׁוֹ לְפוֹשְׁטוֹ:\",1,0],[2,136,102,28,\"וְאַתָּה הוּא. הָעוֹמֵד וְקַיָּם:\",1,0],[2,136,103,1,\"בָּרְכִי נַפְשִׁי. חֲמִשָּׁה בָּרֲכִי נַפְשִׁי יֵשׁ כָּאן, כְּנֶגֶד חֲמִשָּׁה עוֹלָמוֹת שֶׁאָדָם דָּר בָּהֶם, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ בְּמַסֶּכֶת בְּרָכוֹת (ברכות י.): דָּר בִּמְעֵי אִמּוֹ, יָנַק מִשְּׁדֵי אִמּוֹ, וְכֵן כֻּלָּם:\",1,0],[2,136,103,5,\"תִּתְחַדֵּשׁ כַּנֶּשֶׁר נְעוּרָיְכִי. כַּנֶּשֶׁר הַזֶּה שֶׁמְּחַדֵּשׁ כְּנָפָיו וְנוֹצָה מִשָּׁנָה לְשָׁנָה. וְיֵשׁ מִדְרַשׁ אַגָּדָה (בראשית רבה יט, ה) עַל מִין נֶשֶׁר, שֶׁכְּשֶׁמַּזְקִין חוֹזֵר לְנַעֲרוּתוֹ:\",1,0],[2,136,103,7,\"יוֹדִיעַ דְּרָכָיו. מוֹדִיעַ דְּרָכָיו לְמֹשֶׁה:\",1,0],[2,136,103,14,\"זָכוּר כִּי עָפָר אֲנָחְנוּ. זָכוּר הוּא וְלֹא שָׁכַח שֶׁאֲנַחְנוּ עָפָר, וְיוֹדֵעַ שֶׁאֱנוֹשׁ כֶּחָצִיר יָמָיו וְגוֹ׳:\",1,0],[2,136,103,16,\"רוּחַ עָבְרָה בּוֹ. אִם עָבְרָה חֳלִי שֶׁל מִיתָה:\",1,0],[2,136,103,19,\"מָשָׁלָה. מוֹשֶׁלֶת:\",1,0],[2,136,103,22,\"בָּרְכוּ ה׳ כָּל מַעֲשָׂיו. אֲשֶׁר הֵם בְּכָל מְקוֹמוֹת שֶׁמֶּמְשַׁלְתּוֹ שָׁם:\",1,0],[2,136,104,2,\"עוֹטֶה אוֹר. בָּרָקִיעַ כַּשַּׂלְמָה:\",1,0],[2,136,104,4,\"עוֹשֶׂה מַלְאָכָיו רוּחוֹת. עוֹשֶׂה אֶת הָרוּחוֹת שְׁלוּחָיו:\",1,0],[2,136,104,6,\"תְּהוֹם כַּלְּבוּשׁ כִּסִּיתוֹ. זֶה דּוּגְמַת הָאָמוּר בְּמָקוֹם אַחֵר: ״בְּשׂוּמִי עָנָן לְבוּשׁוֹ וְגוֹ׳״ (איוב לח:ט):\",1,0],[2,136,104,6,\"תְּהוֹם. הוּא הַיָּם:\",2,0],[2,136,104,6,\"עַל הָרִים יַעַמְדוּ. מֵי אוֹקְיָינוֹס גָּבוֹהַּ מִכָּל הָעוֹלָם עוֹמֵד עַל הֶהָרִים, וְכֵן הוּא אוֹמֵר (עמוס ה:ח, ט:ו) ״הַקּוֹרֵא לְמֵי הַיָּם וַיִּשְׁפְּכֵם עַל פְּנֵי הָאָרֶץ״. אֵין שְׁפִיכָה אֶלָּא מִלְמַעְלָה לְמַטָּה:\",3,0],[2,136,104,7,\"מִן גַּעֲרָתְךָ יְנוּסוּן. כְּשֶׁאָמַרְתָּ (בראשית א:ט) ״יִקָּווּ הַמַּיִם״, וּמֵאוֹתוֹ הַקּוֹל יֵחָפֵזוּן וְנִקְווּ אֶל מָקוֹם אֲשֶׁר יִסַּדְתָּ לָהֶם:\",1,0],[2,136,104,9,\"גְּבוּל שַׂמְתָּ. לָהֶם הַחוֹל אֲשֶׁר סָבִיב שְׂפָתוֹ:\",1,0],[2,136,104,12,\"עֲלֵיהֶם עוֹף הַשָּׁמַיִם יִשְׁכּוֹן. עַל הַמַּעְיָנוֹת:\",1,0],[2,136,104,12,\"מִבֵּין עֳפָאיִם. עַנְפֵי אִילָנוֹת, וְכֵן ״עָפְיֵּהּ שַׁפִּיר״ (דניאל ד:ט):\",2,0],[2,136,104,15,\"מַצְמִיחַ חָצִיר וְגוֹ׳. וְיַיִן אֲשֶׁר יְשַׂמַּח לְבַב אֱנוֹשׁ גַּם אוֹתוֹ יוֹצִיא מִן הָאָרֶץ, וְשֶׁמֶן לְהַצְהִיל בּוֹ פָּנִים:\",1,0],[2,136,104,15,\"וְלֶחֶם. אֲשֶׁר לֵב אֱנוֹשׁ יִסְעָד:\",2,0],[2,136,104,16,\"עֲצֵי ה׳. בְּגַן עֵדֶן (בראשית רבה טו, א):\",1,0],[2,136,104,17,\"צִפֳּרִים יְקַנֵּנוּ. יִשְׂרָאֵל יִשְׁכְּנוּ שָׁם:\",1,0],[2,136,104,17,\"יְקַנֵּנוּ. לְשׁוֹן ״קַן צִפּוֹר״ (דברים כב:ו):\",2,0],[2,136,104,18,\"הָרִים הַגְּבֹהִים. בָּרָא לַיְּעֵלִים:\",1,0],[2,136,104,18,\"מַחְסֶה. כָּל לְשׁוֹן מַחְסֶה לְשׁוֹן צֵל וּמַחְבָּא, שֶׁאָדָם מִתְכַּסֶּה שָׁם מִן הַזֶּרֶם וּמִן הַמָּטָר (ישעיהו כה:ד). אַבְרִ״י בְּלַעַ״ז:\",2,0],[2,136,104,19,\"לְמוֹעֲדִים. לִמְנוֹת בּוֹ זְמַנִּים וּרְגָלִים (ראש השנה כה.):\",1,0],[2,136,104,19,\"שֶׁמֶשׁ יָדַע מְבוֹאוֹ. אֲבָל יָרֵחַ לֹא יָדַע מְבוֹאוֹ, פְּעָמִים שֶׁבָּא בַּאֲרֻכָּה, פְּעָמִים שֶׁבָּא בַּקְּצָרָה (ראש השנה כה.):\",2,0],[2,136,104,20,\"תָּשֶׁת חֹשֶׁךְ וִיהִי לָיְלָה. בְּכָל יוֹם אַתָּה מַחְשִׁיךְ וּמַעֲרִיב אֶת הַשֶּׁמֶשׁ וְהָיָה לָיְלָה, וּבּוֹ תִּרְמֹשׂ כָּל חַיְתוֹ יָעַר:\",1,0],[2,136,104,22,\"תִּזְרַח הַשֶּׁמֶשׁ יֵאָסֵפוּן. בַּמִּסְתָּרִים וְנֶחְבָּאִים שָׁם מִבְּנֵי אָדָם, וְאָז כָּל אָדָם יוֹצֵא לְפָעֳלוֹ:\",1,0],[2,136,104,24,\"קִנְיָנֶךָ. מִקְנֵה קִנְיָן שֶׁלְּךָ, כְּמוֹ ״קוֹנֵה שָׁמַיִם וָאָרֶץ״ (בראשית יד:יט). הַכֹּל קָנוּי לְךָ:\",1,0],[2,136,104,25,\"וּרְחַב יָדָיִם. רָחָב מָקוֹם, לְרֵיי״שׁ בְּלַעַ״ז:\",1,0],[2,136,104,26,\"לְשַׂחֶק בּוֹ. שָׁלֹשׁ שָׁעוֹת בַּיּוֹם, כָּךְ אָמְרוּ רַבּוֹתֵינוּ בְּמַסֶּכֶת עֲבוֹדָה זָרָה (עבודה זרה ג:), וְכָךְ מְפֹרָשׁ בְּסֵפֶר אִיּוֹב: ״הֲתְשַׂחֶק בּוֹ כַּצִּפּוֹר״ (איוב מ:כט):\",1,0],[2,136,104,29,\"תּוֹסֵף רוּחָם. לְשׁוֹן כִּלָּיוֹן, כְּמוֹ ״סָפוּ תַמּוּ״ (תהלים עג:יט):\",1,0],[2,136,104,30,\"תְּשַׁלַּח רוּחֲךָ. בִּתְחִיַּת הַמֵּתִים:\",1,0],[2,136,104,32,\"יִגַּע בֶּהָרִים וְיֶעֱשָׁנוּ. כְּמוֹ שֶׁמְּפֹרָשׁ בְּסִינַי: ״וְהַר סִינַי עָשַׁן כֻּלּוֹ״ (שמות יט:יח):\",1,0],[2,136,104,33,\"בְּעוֹדִי. כְּמוֹ ״בְּעוֹדֶנִּי חַי״ (דברים לא:כז):\",1,0],[2,136,104,35,\"יִתַּמּוּ חַטָּאִים. חוֹטְאִים (ברכות י.):\",1,0],[2,136,105,1,\"עֲלִילוֹתָיו. מַעֲלָלָיו:\",1,0],[2,136,105,3,\"הִתְהַלְלוּ בְּשֵׁם קָדְשׁוֹ. הִתְפָּאֲרוּ בְּמָעוֹז שֵׁם קָדְשׁוֹ, שֶׁיֵּשׁ לָכֶם פַּטְרוֹן כָּמוֹהוּ. הִתְהַלְלוּ פוֹרְוַונְטִי״ץ וו״ש בְּלַעַ״ז:\",1,0],[2,136,105,8,\"דָּבָר צִוָּה לְאֶלֶף דּוֹר. הַתּוֹרָה, אֲשֶׁר צִוָּה לְהוֹדִיעָהּ בָּעוֹלָם לְאַחַר אֶלֶף דּוֹר; וְרָאָה שֶׁאֵין הָעוֹלָם מִתְקַיֵּם בְּלֹא תּוֹרָה, וְהֶעֱבִיר מֵהֶם תְּשַׁע מֵאוֹת וְשִׁבְעִים וְאַרְבָּעָה דּוֹרוֹת. וְיֵשׁ לִפְתֹּר כִּפְשׁוּטוֹ: זָכַר לְיִשְׂרָאֵל בְּרִיתוֹ אֲשֶׁר צִוָּה, וְהִבְטִיחַ לִשְׁמֹר לָהֶם לְאֶלֶף דּוֹר, כְּעִנְיָן ״שֹׁמֵר הַבְּרִית וְהַחֶסֶד לְאֹהֲבָיו וּלְשֹׁמְרֵי מִצְוֹתָיו לְאֶלֶף דּוֹר״ (דברים ז:ט):\",1,0],[2,136,105,11,\"לֵאמֹר לְךָ אֶתֵּן אֶת אֶרֶץ כְּנָעַן וְגוֹ׳. הוּא הַבְּרִית אֲשֶׁר כָּרַת לָהֶם (בראשית טו:יח):\",1,0],[2,136,105,13,\"וַיִּתְהַלְּכוּ מִגּוֹי אֶל גּוֹי. אַבְרָהָם גָּר בְּאֶרֶץ פְּלִשְׁתִּים וּבְמִצְרַיִם וּבְאֶרֶץ כְּנַעַן (בראשית כא:לד; יב:י; יג:יב), וְכֵן יִצְחָק (בראשית כו:א-לה), וְכֵן יַעֲקֹב (בראשית מב:א-לח; מו:א-לד). כֻּלָּם גָּלוּ מִגֵּרוּת לְגֵרוּת:\",1,0],[2,136,105,14,\"וַיּוֹכַח עֲלֵיהֶם מְלָכִים. ״וַיְנַגַּע ה׳ אֶת פַּרְעֹה״ (בראשית יב:יז), ״כִּי עָצוֹר עָצַר ה׳ בְּעַד כָּל רֶחֶם לְבֵית אֲבִימֶלֶךְ״ (בראשית כ:יח):\",1,0],[2,136,105,15,\"אַל תִּגְּעוּ בִמְשִׁיחָי. בִּגְדוֹלַי, כָּל מְשִׁיחָה לְשׁוֹן שְׂרָרָה וּגְדֻלָּה:\",1,0],[2,136,105,16,\"וַיִּקְרָא רָעָב. כְּדֵי לְהַגְלוֹתָם לְמִצְרַיִם (בראשית מב:א-ב) (מצאתי):\",1,0],[2,136,105,17,\"שָׁלַח לִפְנֵיהֶם אִישׁ. וַיִּשְׁלָחֵנִי אֱלֹהִים לִפְנֵיכֶם (בראשית מה:ה), וְאֵיזֶה אִישׁ? יוֹסֵף שֶׁנִּמְכַּר:\",1,0],[2,136,105,18,\"בַּרְזֶל בָּאָה נַפְשׁוֹ. אָמַר רַבִּי הוּנָא בַּר אִידִי (תנחומא, וישב ח): שַׁרְתּוֹעַ עָשְׂתָה לוֹ תַּחַת זְקָנוֹ, שֶׁאִם יַרְכִּין פָּנָיו הַשַּׁרְתּוֹעַ מַכֵּהוּ. שַׁרְתּוֹעַ פֵּרוּשׁ שַׁפּוּד:\",1,0],[2,136,105,19,\"עַד עֵת בֹּא דְבָרוֹ. שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְקַיֵּם גְּזֵרָתוֹ, שֶׁיִּתְגַּלְגֵּל הַדָּבָר וְיֵרְדוּ יִשְׂרָאֵל לְמִצְרַיִם:\",1,0],[2,136,105,19,\"אִמְרַת ה׳ צְרָפָתְהוּ. בְּחָנַתְהוּ לְיוֹסֵף, שֶׁנִּתְנַסָּה וְכָבַשׁ אֶת יִצְרוֹ בְּאֵשֶׁת אֲדוֹנָיו (בראשית לט:ז-יב), וְעָלֶיהָ נִתְיַיסֵּר וְנִצְרַף בְּיִסּוּרִין לְתִתּוֹ אֶל בֵּית הַסֹּהַר (בראשית לט:כ):\",2,0],[2,136,105,20,\"שָׁלַח מֶלֶךְ וַיַּתִּירֵהוּ. שָׁלַח פַּרְעֹה מֶלֶךְ מִצְרַיִם שְׁלוּחָיו וַיַּתִּירֵהוּ, שָׁלַח מוֹשֵׁל עַמִּים הוּא פַּרְעֹה וַיְפַתְּחֵהוּ:\",1,0],[2,136,105,22,\"לֶאְסֹר שָׂרָיו בְּנַפְשׁוֹ. לְשׁוֹן חִבָּה הוּא זֶה, כְּמוֹ ״וְנֶפֶשׁ יְהוֹנָתָן נִקְשְׁרָה בְּנֶפֶשׁ דָּוִד״ (שמואל א יח:א). כְּשֶׁפָּתַר הַחֲלוֹם חִבְּבוּהוּ כֻּלָּם. אָמַר רַבִּי אִידִי: שָׂרוֹ כְּתִיב, זֶה הָיָה פּוֹטִיפַר:\",1,0],[2,136,105,24,\"וַיֶּפֶר. הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עַמּוֹ, הִפְרָה וְהִרְבָּה אוֹתָם:\",1,0],[2,136,105,28,\"וְלֹא מָרוּ אֶת דְּבָרוֹ. הַמַּכּוֹת שֶׁצִּוָּה עֲלֵיהֶם בָּאוּ בְּמִצְוֹתָיו וְלֹא שִׁנּוּ אֶת דְּבָרוֹ (תנחומא, בא א):\",1,0],[2,136,105,30,\"שָׁרַץ אַרְצָם צְפַרְדְּעִים. אָמַר רַבִּי יוֹחָנָן (שמות רבה י:ד): בְּכָל מָקוֹם שֶׁהָיוּ רוֹבְצִים מַיִם, הָיוּ רוֹבְצִים צְפַרְדְּעִים:\",1,0],[2,136,105,40,\"שָׁאַל וַיָּבֵא שְׂלָו. שָׁאַל יִשְׂרָאֵל בָּשָׂר, וַיָּבֵא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא שְׂלָוִים:\",1,0],[2,136,105,41,\"הָלְכוּ בַצִּיּוֹת נָהָר. הָלְכוּ נְהָרוֹת מִן הַבְּאֵר בְּאֶרֶץ צִיָּה:\",1,0],[2,136,105,42,\"כִּי זָכַר. הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת דְּבַר קָדְשׁוֹ אֲשֶׁר עִם אַבְרָהָם עַבְדּוֹ, שֶׁהִבְטִיחוֹ (בראשית טו:יד,טז) ״וְאַחֲרֵי כֵן יֵצְאוּ בִּרְכֻשׁ גָּדוֹל״, ״וְדוֹר רְבִיעִי יָשׁוּבוּ הֵנָּה״:\",1,0],[2,136,106,4,\"בִּרְצוֹן עַמֶּךָ. בְּהֵרָצוֹתְךָ לְעַמֶּךָ:\",1,0],[2,136,106,7,\"וַיַּמְרוּ עַל יָם. הָיוּ מִקְּטַנֵּי אֲמָנָה; אָמְרוּ: כְּשֵׁם שֶׁאָנוּ עוֹלִים מִכָּאן מִצַּד זֶה, אַף הַמִּצְרִיִּים עוֹלִים מִצַּד אַחֵר, וְיָבוֹאוּ אַחֲרֵינוּ; עַד שֶׁרָמַז הַקָּדוֹשׁ בָּרוּךְ הוּא לַיָּם וְהֵקִיאָם לַיַּבָּשָׁה. אָז ״וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת עַל שְׂפַת הַיָּם״ (שמות יד:ל), לְפִיכָךְ ״וַיַּאֲמִינוּ בַּה׳״ (שמות יד:לא); אֲבָל מִתְּחִלָּה לֹא הֶאֱמִינוּ (פסחים קיח:) (מצאתי):\",1,0],[2,136,106,9,\"וַיּוֹלִיכֵם בַּתְּהוֹמוֹת כַּמִּדְבָּר. יַם סוּף הָיָה בַמִּדְבָּר, דִּכְתִיב ״סָגַר עֲלֵיהֶם הַמִּדְבָּר וְגוֹ׳״ (שמות יד:ג). ״דֶּרֶךְ שְׁלֹשֶׁת יָמִים וְגוֹ׳״ (במדבר י:לג):\",1,0],[2,136,106,13,\"לֹא חִכּוּ לַעֲצָתוֹ. לֹא קִוּוּ לוֹ:\",1,0],[2,136,106,14,\"וַיִּתְאַוּוּ תַאֲוָה. ״מִי יַאֲכִילֵנוּ בָּשָׂר״ (במדבר יא:ד):\",1,0],[2,136,106,15,\"וַיְשַׁלַּח רָזוֹן בְּנַפְשָׁם. ״וְאַף ה׳ חָרָה בָעָם״ (במדבר יא:לג):\",1,0],[2,136,106,16,\"וַיְקַנְאוּ לְמֹשֶׁה. בַּמִּדְבָּר הִכְעִיסוּהוּ, כְּמוֹ ״קִנְאוּנִי בְלֹא אֵל״ (דברים לב:כא) (מצאתי).:\",1,0],[2,136,106,17,\"תִּפְתַּח אֶרֶץ וְגוֹ׳. נִרְאֶה שֶׁחָלַק כָּבוֹד לִבְנֵי קֹרַח מִלְּהַזְכִּיר אֲבִיהֶם, תָּלָה הַקַּלְקָלָה בְּדָתָן וַאֲבִירָם:\",1,0],[2,136,106,18,\"וַתִּבְעַר אֵשׁ. ״וַתֹּאכַל אֶת מַקְרִיבֵי הַקְּטֹרֶת״ (במדבר טז:לה):\",1,0],[2,136,106,20,\"אוֹכֵל עֵשֶׂב. אֵין לְךָ מְתֹעָב וּמְשֻׁקָּץ מִן הַשּׁוֹר, בְּשָׁעָה שֶׁהוּא אוֹכֵל עֵשֶׂב (מכילתא בשלח ויהי ו), שֶׁהוּא מוֹצִיא פֶּרֶשׁ רַבָּה וְהוּא מְלֻכְלָךְ בָּהּ. ס״א: רִירוֹ:\",1,0],[2,136,106,24,\"וַיִּמְאֲסוּ בְּאֶרֶץ חֶמְדָּה. בְּשִׁלּוּחַ מְרַגְּלִים, וְהוֹצִיאוּ דִבָּה עַל הָאָרֶץ (במדבר יג:לב):\",1,0],[2,136,106,26,\"וַיִּשָּׂא יָדוֹ. בִּשְׁבוּעָה:\",1,0],[2,136,106,27,\"וּלְהַפִּיל זַרְעָם בַּגּוֹיִם. מֵאוֹתוֹ שָׁעָה נִגְזַר עֲלֵיהֶם חֻרְבַּן הַבַּיִת, שֶׁהֲרֵי לֵיל תִּשְׁעָה בְּאָב בָּכוּ, וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: הֵם בָּכוּ בְּכִיָּה שֶׁל חִנָּם, וַאֲנִי אֶקְבַּע לָהֶם בְּכִיָּה לְדוֹרוֹת (תענית כט.):\",1,0],[2,136,106,33,\"כִּי הִמְרוּ. מֹשֶׁה וְאַהֲרֹן:\",1,0],[2,136,106,33,\"אֶת רוּחוֹ. בְּ״שִׁמְעוּ נָא הַמּוֹרִים״ (במדבר כ:י):\",2,0],[2,136,106,33,\"וַיְבַטֵּא בִּשְׂפָתָיו. שְׁבוּעָה: ״לָכֵן לֹא תָבִיאוּ אֶת הַקָּהָל הַזֶּה וְגוֹ׳״ (במדבר כ:יב):\",3,0],[2,136,106,34,\"לֹא הִשְׁמִידוּ. בִּימֵי יְהוֹשֻׁעַ:\",1,0],[2,136,106,34,\"אֶת הָעַמִּים. אֲשֶׁר אָמַר ה׳ לָהֶם (דברים כ:טז) ״לֹא תְחַיֶּה כָּל נְשָׁמָה״, (שמות כג:לג) ״לֹא יֵשְׁבוּ בְּאַרְצְךָ״, וְהֵם הִנִּיחוּם לָשֶׁבֶת בְּקִרְבָּם לְמַס עוֹבֵד (שופטים א:כז):\",2,0],[2,136,106,41,\"וַיִּתְּנֵם בְּיַד גּוֹיִם. בִּימֵי הַשּׁוֹפְטִים, בֵּין שׁוֹפֵט לְשׁוֹפֵט, כְּגוֹן עֶגְלוֹן וְכוּשַׁן רִשְׁעָתַיִם וְסִיסְרָא וּפְלִשְׁתִּים וּמִדְיָן (שופטים ג-ד) (מצאתי):\",1,0],[2,136,106,43,\"פְּעָמִים רַבּוֹת יַצִּילֵם. כַּמָּה פְּעָמִים מַכְעִיסִים וְהוּא מַאֲרִיךְ אַפּוֹ וּמַצִּילָם:\",1,0],[2,136,106,43,\"וַיָּמֹכּוּ בַּעֲוֺנָם. נַעֲשׂוּ שְׁפָלִים בַּעֲוֺנָם:\",2,0],[2,136,106,44,\"וַיַּרְא בַּצַּר. מִתּוֹךְ תְּפִלָּה:\",1,0],[2,136,106,44,\"בְּשָׁמְעוֹ אֶת רִנָּתָם. מִתּוֹךְ זְכוּת אָבוֹת:\",2,0],[2,136,106,45,\"וַיִּזְכֹּר לָהֶם בְּרִיתוֹ. מִתּוֹךְ תְּשׁוּבָה:\",1,0],[2,136,106,45,\"וַיִּנָּחֵם כְּרֹב חֲסָדָו. מִתּוֹךְ הַקֵּץ בְּשָׁמְעוֹ הוֹשִׁיעֵנוּ וְגוֹ׳. אַף מֹשֶׁה כְּלָלָם בְּפָסוּק אֶחָד ״בַּצַּר לְךָ וּמְצָאוּךָ וְגוֹ׳״ (דברים ד:ל):\",2,0],[2,136,106,47,\"הוֹשִׁיעֵנוּ. גַּם עַתָּה ה׳ אֱלֹהֵינוּ:\",1,0],[2,136,106,48,\"מִן הָעוֹלָם וְעַד הָעוֹלָם. מִן עָלְמָא הָדֵין וְעַד עָלְמָא דְּאָתֵי (סנהדרין צב.) (ס״א אינו):\",1,0],[2,136,107,1,\"הוֹדוּ לַה׳:\",1,0],[2,136,107,2,\"יֹאמְרוּ גְּאוּלֵי ה׳. כְּשֶׁיִּפְדֵּם מִיַּד צָר :\",1,0],[2,136,107,4,\"תָּעוּ בַמִּדְבָּר וְגוֹ׳. וְהוֹלְכֵי מִדְבָּרוֹת אַף הֵם צְרִיכִין לְהוֹדוֹת, שֶׁהֲרֵי פְּעָמִים שֶׁהֵם תּוֹעִים וּרְעֵבִים וּצְמֵאִים (ברכות נד:):\",1,0],[2,136,107,7,\"וַיַּדְרִיכֵם. וַיְנַהֲגֵם, לְפִיכָךְ יוֹדוּ לַה׳ חַסְדּוֹ:\",1,0],[2,136,107,10,\"יוֹשְׁבֵי חֹשֶׁךְ וְצַלְמָוֶת. אַף הָאֲסוּרִים בְּבֵית הַסֹּהַר צְרִיכִים לְהוֹדוֹת, כְּשֶׁיּוֹצְאִין מִבֵּית אֲסוּרֵיהֶם:\",1,0],[2,136,107,11,\"כִּי הִמְרוּ אִמְרֵי אֵל. אֵין פּוּרְעָנוּת בָּאָה עַל הָאָדָם אֶלָּא בַּעֲוֹנוֹ:\",1,0],[2,136,107,16,\"כִּי שִׁבַּר דַּלְתוֹת נְחֹשֶׁת. שֶׁהָיוּ נְעוּלִים בִּפְנֵיהֶם:\",1,0],[2,136,107,17,\"אֱוִילִים מִדֶּרֶךְ פִּשְׁעָם. אֲשֶׁר מֵעֲוֹנוֹתֵיהֶם יִתְעַנּוּ בְּיִסּוּרֵי חֳלָאִים, אַף הֵם מִן הַצְּרִיכִין לְהוֹדוֹת. יֵשׁ סִמָּנִיּוֹת בְּפָרָשָׁה זוֹ (כְּלוֹמַר כְּתוּבוֹת שֵׁשׁ נוני״ן הֲפוּכִין) וּבָאִין לִדְרֹשׁ בִּמְקוֹם אַכִּין וְרַקִּין לְמַעֵט, לוֹמַר צָעֲקוּ קֹדֶם גְּזַר דִּין נַעֲנִין, לְאַחַר גְּזַר דִּין אֵינָם נַעֲנִין:\",1,0],[2,136,107,27,\"יָחוֹגּוּ. לְשׁוֹן שֶׁבֶר הוּא, וְכֵן ״בְּחַגְוֵי הַסֶּלַע״ (שיר השירים ב:יד), וְכֵן ״וְהָיְתָה אַדְמַת יְהוּדָה לְמִצְרַיִם לְחָגָּא״ (ישעיהו יט:יז):\",1,0],[2,136,107,30,\"וַיִּשְׂמְחוּ כִּי יִשְׁתֹּקוּ. הַגַּלִּים:\",1,0],[2,136,107,30,\"וַיַּנְחֵם. וַיְנַהֲגֵם:\",2,0],[2,136,107,30,\"מָחוֹז. לְשׁוֹן גְּבוּל, וּמְנַחֵם חִבְּרוֹ עִם ״וַחֲזוּתְכֶם אֶת שְׁאוֹל״ (ישעיה כח:יח) – גְּבוּלֵינוּ, שֶׁלֹּא יִכָּנֵס בִּגְבוּלֵינוּ. וְכֵן ״מַחֲזֶה אֶל מַחֲזֶה שָׁלֹשׁ פְּעָמִים״ (מלכים א ז:ד). בְּתַנְחוּמָא מָצָאתִי:\",3,0],[2,136,107,32,\"וִירוֹמְמוּהוּ בִּקְהַל עָם. צָרִיךְ לְאוֹדוֹיֵי בְּאַפֵּי בֵּי עֲשָׂרָה (ברכות נד:):\",1,0],[2,136,107,32,\"וּבְמוֹשַׁב זְקֵנִים. וְתָרֵין מִנַּיְיהוּ צוּרְבָא מֵרַבָּנָן (בבא בתרא טו.):\",2,0],[2,136,107,33,\"יָשֵׂם נְהָרוֹת לְמִדְבָּר. כְּלוֹמַר: נוֹתֵן יִשּׁוּבֵי הָאֻמּוֹת לְחֻרְבָּן:\",1,0],[2,136,107,34,\"לִמְלֵחָה. לִהְיוֹת כְּאֶרֶץ מְלֵחָה מֵעֲשׂוֹת פֶּרִי:\",1,0],[2,136,107,35,\"יָשֵׂם מִדְבָּר לַאֲגַם מַיִם. נוֹתֵן יִשּׁוּב חָרֵב לְבִנְיָן וּמַחֲזִירוֹ לְקַדְמוּתוֹ:\",1,0],[2,136,107,39,\"וַיִּמְעֲטוּ וַיָּשֹׁחוּ. וְהֵם מִתְּחִלָּה הָיוּ שָׁחִין וּמוּעָטִין מֵעֹצֶר רָעָה וְיָגוֹן:\",1,0],[2,136,107,41,\"וַיָּשֶׂם כַּצֹּאן מִשְׁפָּחוֹת. וַיָּשֶׂם הָאֶבְיוֹן מִשְׁפַּחַת זַרְעוֹ כַּצֹּאן – רַבִּים:\",1,0],[2,136,107,42,\"קָפְצָה. סָתְמָה, כְּמוֹ ״לֹא תִקְפֹּץ אֶת יָדְךָ״ (דברים טו:ז):\",1,0],[2,136,108,2,\"נָכוֹן לִבִּי. נֶאֱמָן עִמְּךָ:\",1,0],[2,136,108,2,\"אַף כְּבוֹדִי. הוּא מַה שֶּׁאֲנִי מְשׁוֹרֵר לְךָ. דָּבָר אַחֵר: אַף כְּבוֹדִי. אַף לְפִי כְבוֹדִי לֹא אֶמָּנַע לְשׁוֹרֵר לוֹ, וְלֹא אֲחַלֵּק לְעַצְמִי כָּבוֹד:\",2,0],[2,136,108,3,\"אָעִירָה שָּׁחַר. דֶּרֶךְ שְׁאָר מְלָכִים, הַשַּׁחַר מְעוֹרְרָם, וַאֲנִי מְעוֹרֵר אֶת הַשַּׁחַר; שֶׁאֲנִי קָם חֲצוֹת לַיְלָה (תהלים קיט:סב), שֶׁהַנֵּבֶל וְהַכִּנּוֹר מְעוֹרְרֵנִי; כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ (ברכות ג:): כִּנּוֹר הָיָה תָּלוּי לְמַעְלָה מִמִּטָּתוֹ שֶׁל דָּוִד; כֵּיוָן שֶׁהִגִּיעַ חֲצִי הַלַּיְלָה, רוּחַ צְפוֹנִית מְנַשֶּׁבֶת בּוֹ, וְהוּא מְנַגֵּן מֵאֵלָיו:\",1,0],[2,136,108,5,\"מֵעַל שָׁמַיִם. וְכָתוּב אֶחָד אוֹמֵר עַד שָׁמַיִם (תהלים נז:יא)? פֵּרְשׁוּ רַבּוֹתֵינוּ (פסחים נ:): כָּאן בְּעוֹשִׂין לִשְׁמָהּ, כָּאן בְּעוֹשִׂין שֶׁלֹּא לִשְׁמָהּ:\",1,0],[2,136,108,7,\"וַעֲנֵנִי. שֶׁכָּל עַמְּךָ וִידִידֶיךָ תְּלוּיִין בִּי:\",1,0],[2,136,108,8,\"אֱלֹהִים דִּבֶּר בְּקָדְשׁוֹ. שֶׁאֶמְלֹךְ וְיָבֹא הָעֵת וְאֶעֱלֹז בִּדְבָרוֹ (תהלים ס:ח):\",1,0],[2,136,108,8,\"אֲחַלְּקָה שְׁכֶם. אֲחַלְּקָה אֶרֶץ אוֹיְבִי לְיִשְׂרָאֵל, שְׁכֶם חֵלֶק כְּמוֹ (בראשית מח:כב) ״שְׁכֶם אַחַד עַל אַחֶיךָ״ (וְעֵמֶק סֻכּוֹת אֲמַדֵּד):\",2,0],[2,136,108,10,\"מוֹאָב סִיר רַחְצִי. כְּלוֹמַר: עַבְדִּי וְשַׁמָּשִׁי, כִּכְלִי תַשְׁמִישׁ שֶׁמִּשְׁתַּמְּשִׁין בּוֹ:\",1,0],[2,136,108,10,\"עַל אֱדוֹם אַשְׁלִיךְ. עֲבוֹדָתִי, שֶׁיִּהְיוּ מַלְכֵיהֶם נוֹטְלִין מִנְעָלַי בְּרַגְלִי:\",2,0],[2,136,108,10,\"אֶתְרוֹעָע. אָרִיעַ לָהֶם קוֹל לְיָרְאָם מִפָּנַי:\",3,0],[2,136,108,11,\"מִי יֹבִילֵנִי. לִימוֹת הַמָּשִׁיחַ לִפְשׁוֹט יָד בְּעֵשָׂו בְּעָרֵי מִבְצָרִים, מִי שֶׁנָּחַנִי כְּבָר עַל אֱדוֹם שֶׁהִכִּיתִי בָהֶם ״בְּגֵיא מֶלַח שְׁמוֹנָה עָשָׂר אֶלֶף״ (שמואל ב ח:יג):\",1,0],[2,136,109,1,\"אֱלֹהֵי תְהִלָּתִי אַל תֶּחֱרַשׁ. עַל כָּל יִשְׂרָאֵל נֶאֱמַר:\",1,0],[2,136,109,2,\"כִּי פִי רָשָׁע. עֵשָׂו:\",1,0],[2,136,109,4,\"תַּחַת אַהֲבָתִי אוֹתְךָ יִשְׂטְנוּנִי:\",1,0],[2,136,109,4,\"וַאֲנִי תְפִלָּה. וַאֲנִי מִתְפַּלֵּל אֵלֶיךָ תָּמִיד (מצאתי):\",2,0],[2,136,109,5,\"רָעָה תַּחַת טוֹבָה. שִׁבְעִים פָּרִים אֲנִי מַקְרִיב בְּכָל שָׁנָה בִּשְׁבִיל שִׁבְעִים אֻמּוֹת, וּמְבַקֵּשׁ לִגְשָׁמִים, וְהֵם מְרֵיעִים לִי:\",1,0],[2,136,109,7,\"בְּהִשָּׁפְטוֹ. לְפָנֶיךָ יֵצֵא מִדִּינְךָ מְחֻיָּב וְרָשָׁע:\",1,0],[2,136,109,8,\"פְּקֻדָּתוֹ. גְּדֻלָּתוֹ, פְּרוֹבוֹשְׁטִיאָ״ה בְּלַעַ״ז, כְּמוֹ ״וְיַפְקֵד הַמֶּלֶךְ פְּקִידִים״ (אסתר ב:ג):\",1,0],[2,136,109,10,\"וְשִׁאֵלוּ וְדָרְשׁוּ מֵחָרְבוֹתֵיהֶם. הַכֹּל יִשְׁאֲלוּ עֲלֵיהֶם: מַה נִּהְיְתָה בִּפְלוֹנִי וּפְלוֹנִי? מִתּוֹךְ קוֹל חוּרְבָּה שֶׁיָּצָא עֲלֵיהֶם:\",1,0],[2,136,109,10,\"וְדָרְשׁוּ. מַשְׁמָע: מֵאֵת אֲחֵרִים, שֶׁהֲרֵי נָקוּד חֲטַף קָמַץ, וְכֵן וְשִׁאֵלוּ. מִפִּי אֲחֵרִים הוּא מַשְׁמָע, שֶׁיִּשְׁאֲלוּ אֲחֵרִים עֲלֵיהֶם. וְיֵשׁ לִפְתּוֹר וְשִׁאֵלוּ, מִמִּשְׁקַל חָזָק: יִהְיוּ מְשַׁאֲלִים עַל הַפְּתָחִים:\",2,0],[2,136,109,11,\"יְנַקֵּשׁ נוֹשֶׁה לְכָל אֲשֶׁר לוֹ. אָדָם הַטּוֹרֵחַ מְחַזֵּר וְלָהוּט לַעֲשׂוֹת דָּבָר, נוֹפֵל בּוֹ לָשׁוֹן מִתְנַקֵּשׁ, כְּלוֹמַר: מֻטְרָף וּמִתְלַבֵּט, כְּמוֹ ״וְאַרְכֻּבָּתֵהּ דָּא לְדָא נָקְשָׁן״ (דניאל ה:ו), וְכֵן ״פֶּן תִּנָּקֵשׁ אַחֲרֵיהֶם״ (דברים יב:ל). אַף כָּאן יִהְיֶה הַנּוֹשֶׁה בְּעֵשָׂו אֶת עֲבוֹדָתוֹ שֶׁנֶּאֱמַר ״וְרַב יַעֲבֹד צָעִיר״ (בראשית כה:כג). לָשׁוֹן אַחֵר: יִהְיֶה הַנּוֹשֶׁה נוֹגֵעַ וְנִקְרָב לְכָל אֲשֶׁר לוֹ, יְנַקֵּשׁ שייטאצופי״ץ בְּלַעַ״ז. יְהִי מִשְׁפַּט הַנּוֹשֶׁה נוֹקֵשׁ וְנִשְׁעָן עַל כָּל מָמוֹנוֹ, וְזֶהוּ יַעֲקֹב הַנּוֹשֶׁה בְּעֵשָׂו אֶת עֲבוֹדָתוֹ שֶׁנֶּאֱמַר ״וְרַב יַעֲבֹד צָעִיר״ (בראשית כה:כג) מָצָאתִי:\",1,0],[2,136,109,13,\"בְּדוֹר אַחֵר. שֶׁיָּבֹא אַחַר כּוֹרְתוֹ, יִמַּח שְׁמוֹ וְטִבְעוֹ, שֶׁאֲפִלּוּ זִכָּרוֹן לֹא יִפֹּל עָלָיו בְּפִי הַדּוֹר הַנּוֹלָד בָּעוֹלָם לְאַחַר שֶׁנִּשְׁחַת שְׁמוֹ. שארטרמיר״א בְּלַעַ״ז:\",1,0],[2,136,109,14,\"עֲוֺן אֲבוֹתָיו. עָוֹן שֶׁהֶעֱוָה עַל אֲבוֹתָיו, לְאַבְרָהָם שֶׁגָּרַע חָמֵשׁ שָׁנִים מֵחַיָּיו (בראשית רבה סג,יב), וּלְאָבִיו גָּרַם כִּהְיוֹן עֵינַיִם (בראשית רבה סה,ד-ה):\",1,0],[2,136,109,14,\"וְחַטַּאת אִמּוֹ. שֶׁהִשְׁחִית רַחְמָהּ וְשֶׁגָּרַם לְהַעֲלִים יוֹם קְבוּרָתָהּ מִן הַבְּרִיּוֹת, שֶׁלֹּא יְקַלְלוּהָ שֶׁיָּצָא מִכְּרֵסָהּ עֵשָׂו, כְּמוֹ שֶׁנֶּאֱמַר (בראשית לה:ח) ״וַתָּמָת דְּבוֹרָה מֵינֶקֶת רִבְקָה וְגוֹמֵר אַלּוֹן בָּכוּת״, בִּלְשׁוֹן יְוָנִי קוֹרִין לְאַחֵר אַלּוֹן, שֶׁאֵבֶל אַחֵר הָיָה לְיַעֲקֹב עִם שֶׁל דְּבוֹרָה, שֶׁמֵּתָה אִמּוֹ וְהֶעֱלִימוּ מִיתָתָהּ:\",2,0],[2,136,109,15,\"יִהְיוּ. הָעֲוֹנוֹת הָאֵלֶּה נֶגֶד ה׳ תָּמִיד:\",1,0],[2,136,109,15,\"וְיַכְרֵת מֵאֶרֶץ זִכְרָם. שֶׁל עֵשָׂו וְאַלּוּפָיו:\",2,0],[2,136,109,16,\"יַעַן אֲשֶׁר לֹא זָכַר עֲשׂוֹת חָסֶד. לַעֲסוֹק בְּאֵבֶל אָבִיו, כְּמוֹ שֶׁעָשָׂה יַעֲקֹב נְזִיד עֲדָשִׁים לְנַחֵם אֶת יִצְחָק (בראשית כה:כט), שֶׁבְּאוֹתוֹ הַיּוֹם מֵת אַבְרָהָם (בבא בתרא טז:):\",1,0],[2,136,109,16,\"אִישׁ עָנִי. יִשְׂרָאֵל:\",2,0],[2,136,109,17,\"וַיֶּאֱהַב קְלָלָה. קִלְלָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּפַר בּוֹ:\",1,0],[2,136,109,18,\"וַיִּלְבַּשׁ קְלָלָה. הִכְנִיס עַצְמוֹ בִּקְלָלָה, וְנוֹחָה לוֹ פְּרִיקַת עֹל הַקָּרְבָּן וּבִרְכַּת כֹּהֲנִים וְקִלְלַת הָאֻמּוֹת:\",1,0],[2,136,109,19,\"תְּהִי לוֹ. הַקְּלָלָה מַעֲטֶה כְּבֶגֶד (מצאתי):\",1,0],[2,136,109,19,\"וּלְמֵזַח תָּמִיד. חֲגוֹרָה, וְכֵן ״וּמְזִיחַ אֲפִיקִים רִפָּה״ (איוב יב:כא) אֵזוֹר הַחֲזָקִים פִּתֵּחַ:\",2,0],[2,136,109,23,\"כְּצֵל כִּנְטוֹתוֹ. לְעֵת עֶרֶב:\",1,0],[2,136,109,23,\"נִנְעַרְתִּי. לְשׁוֹן תִּשְׁנוֹק וְטֵרוּף וְאֹטֶם כָּאַרְבֶּה שֶׁהוּא נוֹדֵד וְנָע וּמְטֹרָף (ירושלמי ברכות ד.) (מצאתי):\",2,0],[2,136,109,29,\"וְיַעֲטוּ כַמְעִיל. הָעוֹטֶה וְעוֹטֵף כָּל הַגּוּף לְכָל לְבוּשׁ:\",1,0],[2,136,110,1,\"נְאֻם ה׳ לַאדֹנִי. רַבּוֹתֵינוּ דְּרָשׁוּהוּ בְּאַבְרָהָם אָבִינוּ, וַאֲנִי אֲפָרְשֶׁנּוּ כְּדִבְרֵיהֶם: נְאֻם ה׳ לְאַבְרָהָם, שֶׁקְּרָאוּהוּ הָעוֹלָם אֲדֹנִי ״שְׁמָעֵנִי אֲדֹנִי״ (בראשית כג:יא):\",1,0],[2,136,110,1,\"שֵׁב לִימִינִי. הִתְעַכֵּב לִתְשׁוּעָתִי וְהִתְחוֹלֵל לַה׳, אֵין יְשִׁיבָה אֶלָּא עַכָּבָה, וְכֵן הוּא אוֹמֵר: ״וַתֵּשְׁבוּ בְקָדֵשׁ״ (דברים א:מו):\",2,0],[2,136,110,1,\"לִימִינִי. לִתְשׁוּעַת יְמִינִי:\",3,0],[2,136,110,1,\"עַד אָשִׁית אוֹיְבֶיךָ. אַמְרָפֶל וַחֲבֵרָיו (בראשית יד:א):\",4,0],[2,136,110,2,\"מַטֵּה. לְשׁוֹן מִשְׁעָן, כְּמוֹ ״כָּל מַטֵּה לֶחֶם״ (תהלים קה:טז):\",1,0],[2,136,110,2,\"מַטֵּה עֻזְּךָ יִשְׁלַח ה׳ מִצִּיּוֹן. כְּשֶׁתָּשׁוּב מִן הַמִּלְחָמָה וַאֲנָשֶׁיךָ עֲיֵפִים וְרוֹדְפִים, יִשְׁלַח לְךָ ה׳ אֶת מַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם לְהוֹצִיא לֶחֶם וָיַיִן (בראשית יד:יז-יח):\",2,0],[2,136,110,2,\"רְדֵה. בַּמִּלְחָמָה:\",3,0],[2,136,110,2,\"בְּקֶרֶב אוֹיְבֶיךָ. לָבֶטַח:\",4,0],[2,136,110,3,\"עַמְּךָ נְדָבוֹת בְּיוֹם חֵילֶךָ. כְּשֶׁתֶּאֱסֹף חַיִל לִרְדֹּף אַחֲרֵיהֶם, יִתְנַדְּבוּ עַמְּךָ וְאוֹהֲבֶיךָ לָצֵאת עִמְּךָ, כְּמוֹ שֶׁמָּצִינוּ (בראשית יד:יד) ״וַיָּרֶק אֶת חֲנִיכָיו יְלִידֵי בֵיתוֹ״ וְלֹא יוֹתֵר, וְעָנֵר וְאֶשְׁכֹּל וּמַמְרֵא הִתְנַדְּבוּ מֵאֲלֵיהֶם לָצֵאת לָלֶכֶת אַחֲרָיו בְּעֶזְרָתוֹ:\",1,0],[2,136,110,3,\"בְּהַדְרֵי קֹדֶשׁ מֵרֶחֶם מִשְׁחָר. זֹאת תִּהְיֶה לְךָ בִּזְכוּת הַדְרַת קְדֻשָּׁה שֶׁהָיָה בְּךָ מִבֶּטֶן אִמֶּךָ, שֶׁהִכִּיר בּוֹרְאוֹ בֶּן שָׁלֹשׁ שָׁנִים (נדרים לב.):\",2,0],[2,136,110,3,\"מֵרֶחֶם מִשְׁחָר. מִשֶּׁנָּפַלְתָּ מִן הָרֶחֶם, כְּמוֹ מְשִׁילִין פֵּרוֹת דֶּרֶךְ אֲרֻבָּה בְּיוֹם טוֹב (ביצה לה:), וְאִיכָּא דְּתָנֵי מַשְׁחִירִין:\",3,0],[2,136,110,3,\"לְךָ טַל יַלְדוּתֶיךָ. לְךָ יֵחָשֵׁב יַלְדוּתֶיךָ. דַּרְכֵי יֹשֶׁר שֶׁהִנְהַגְתָּ בָּהֶם בְּיַלְדוּתֶיךָ יִהְיֶה לְךָ לְנֹעַם, כַּטַּל זֶה שֶׁהוּא נָעִים וְנוֹחַ:\",4,0],[2,136,110,4,\"נִשְׁבַּע ה׳ וְלֹא יִנָּחֵם. לְפִי שֶׁהָיָה מִתְיָרֵא שֶׁלֹּא יֵעָנֵשׁ עַל הָאוּכְלוֹסִין שֶׁהָרַג, נֶאֱמַר לוֹ (בראשית טו:א) ״אַל תִּירָא אַבְרָם וְגוֹ׳״. לֹא יִנָּחֵם עַל הַטּוֹבָה אֲשֶׁר דִּבֵּר עָלֶיךָ:\",1,0],[2,136,110,4,\"אַתָּה כֹהֵן לְעוֹלָם עַל דִּבְרָתִי מַלְכִּי צֶדֶק. מִמְּךָ תֵּצֵא הַכְּהֻנָּה וּמַלְכוּת, לִהְיוֹת בָּנֶיךָ יוֹרְשִׁין אֶת שֵׁם אֲבִי אָבִיךָ הַכְּהֻנָּה וְהַמַּלְכוּת שֶׁנִּתְּנוּ לוֹ:\",2,0],[2,136,110,4,\"דִּבְרָתִי מַלְכִּי צֶדֶק. יוֹ״ד יְתֵרָה, כְּמוֹ ״רַבָּתִי עָם״ (איכה א:א). עַל דִּבְרַת מַלְכִּי צֶדֶק – עַל פְּקֻדַּת מַלְכִּי צֶדֶק. אַתָּה כֹהֵן. יֵשׁ בְּמַשְׁמָע כֹּהֵן – כְּהֻנָּה וּשְׂרָרָה, כְּמוֹ ״וּבְנֵי דָוִד כֹּהֲנִים הָיוּ״ (שמואל ב ח:יח):\",3,0],[2,136,110,5,\"אֲדֹנָי. אֲשֶׁר הָיָה עַל יְמִינְךָ בַּמִּלְחָמָה:\",1,0],[2,136,110,5,\"מָחַץ בְּיוֹם אַפּוֹ מְלָכִים. אֶת אַרְבָּעָה מְלָכִים הוּא יָדִין בַּגּוֹיִם מָלֵא גְוִיּוֹת, זוֹ הִיא בְּשׂוֹרַת בְּרִית בֵּין הַבְּתָרִים שֶׁנֶּאֱמַר לוֹ עַל מִצְרַיִם: ״וְגַם אֶת הַגּוֹי אֲשֶׁר יַעֲבֹדוּ דָּן אָנֹכִי״ (בראשית טו:יד):\",2,0],[2,136,110,6,\"מָלֵא גְוִיּוֹת. אֲסִיפַת פְּגָרִים, מָלֵא לְשׁוֹן אֲסִיפָה כְּמוֹ ״קָרְאוּ אַחֲרֶיךָ מָלֵא״ (ירמיהו יב:ו), ״אֲשֶׁר יִקָּרֵא עָלָיו מְלֹא רֹעִים״ (ישעיהו לא:ד). וְהֵיכָן דָּן מָלֵא גְוִיּוֹת? ״אֶת מִצְרַיִם מֵת עַל שְׂפַת הַיָּם״ (שמות יד:ל):\",1,0],[2,136,110,6,\"מָחַץ רֹאשׁ עַל אֶרֶץ רַבָּה. זוֹ הִיא דֻּגְמַת נְבוּאַת ״מָחַצְתָּ רֹּאשׁ מִבֵּית רָשָׁע״ (חבקוק ג:יג) – רֹאשׁ פַּרְעֹה, שֶׁהָיָה רֹאשׁ וְשַׂר עַל אֶרֶץ גְּדוֹלָה וַחֲשׁוּבָה עַל כָּל הָאֲרָצוֹת, כְּמוֹ שֶׁנֶּאֱמַר ״מוֹשֵׁל עַמִּים וַיְפַתְּחֵהוּ״ (תהלים קה:כ) – שֶׁהָיוּ כָּל הָאֻמּוֹת תַּחַת מֶמְשֶׁלֶת מִצְרָיִם:\",2,0],[2,136,110,7,\"מִנַּחַל בַּדֶּרֶךְ יִשְׁתֶּה וְגוֹ׳. מִנִּילוּס הַנָּהָר בְּדֶרֶךְ הֲלִיכָתוֹ הָיְתָה אַרְצוֹ שׁוֹתָה וְלֹא הָיְתָה צְרִיכָה לְמֵי גְשָׁמִים, עַל כֵּן הָיָה מֵרִים רֹאשׁ וּמִתְפָּאֵר ״לִי יְאוֹרִי וַאֲנִי עֲשִׂיתִנִי״ (יחזקאל כט:ג). עִנְיָן אַחֵר יֵשׁ לְפָרֵשׁ הַמִּזְמוֹר הַזֶּה בְּדָוִד:\",1,0],[2,136,110,7,\"(א) נְאֻם ה׳ לַאדֹנִי. עַל עִסְקֵי אֲדוֹנִי שָׁאוּל, כְּשֶׁהָיִיתִי נִרְדָּף מִפָּנָיו:\",2,0],[2,136,110,7,\"לַאדֹנִי. עַל אֲדוֹנִי, כְּמוֹ ״וְאָמַר פַּרְעֹה לִבְנֵי יִשְׂרָאֵל״ (שמות יד:ג), ״וַיִּשְׁאֲלוּ אַנְשֵׁי הַמָּקוֹם לְאִשְׁתּוֹ״ (בראשית כו:ז):\",3,0],[2,136,110,7,\"שֵׁב לִימִינִי. הִתְעַכֵּב וְהַמְתֵּן לִישׁוּעָתִי:\",4,0],[2,136,110,7,\"(ב) מַטֵּה עֻזְּךָ יִשְׁלַח ה׳ מִצִּיּוֹן. מַעֲשִׂים טוֹבִים הַמְצֻיָּנִין בְּיָדְךָ. דָּבָר אַחֵר: עוֹד תִּמְלֹךְ בְּצִיּוֹן, וְשָׁם יְשֻׁלַּח לְךָ מַטֵּה עֹז, וְאָז תִּרְדֶּה בְּקֶרֶב אוֹיְבֶיךָ:\",5,0],[2,136,110,7,\"(ג) עַמְּךָ נְדָבוֹת בְּיוֹם חֵילֶךָ. עַם יִשְׂרָאֵל יִתְנַדְּבוּ לְעֶזְרָתְךָ בְּיוֹם שֶׁתַּעֲשֶׂה חַיִל, כְּמוֹ שֶׁמְּפֹרָשׁ (דברי הימים א יב:כא) שֶׁהָיוּ נִקְבָּצִים עָלָיו מִכָּל שֵׁבֶט וָשֵׁבֶט ״בְּלֶכְתּוֹ אֶל צִקְלַג נָפְלוּ עָלָיו מִמְּנַשֶּׁה וְגוֹמֵר״ ״וּמִן הַגָּדִי נִבְדְּלוּ אֶל דָּוִד וְגוֹמֵר״ (שם;ט):\",6,0],[2,136,110,7,\"בְּהַדְרֵי קֹדֶשׁ מֵרֶחֶם מִשְׁחָר. בִּשְׁבִיל הַדְרַת קְדֻשָּׁה שֶׁהָיֳה בְךָ מִנְּעוּרֶיךָ:\",7,0],[2,136,110,7,\"לְךָ טַל יַלְדוּתֶךָ. יַלְדוּת טוֹבָה וּפֶרֶק נָאֶה שֶׁהָיָה בְּךָ, תִּהְיֶה לְךָ כַּטַּל שֶׁהוּא נָעִים וְעָרֵב, וְתַעֲשֶׂה לְךָ פֵּרוֹת לְהַצְלִיחֲךָ:\",8,0],[2,136,110,7,\"(ד) נִשְׁבַּע ה׳ וְגוֹ׳. שֶׁהַמַּלְכוּת תְּהֵא שֶׁלְּךָ עוֹלָמִית:\",9,0],[2,136,110,7,\"אַתָּה כֹהֵן לְעוֹלָם. וְאֵיזוֹ מִן הַכְּהֻנּוֹת? כְּהֻנָּה שֶׁהִיא לְמַעְלָה מִכְּהֻנַּת מַלְכִּי צֶדֶק, וְזֶהוּ הַמַּלְכוּת שֶׁהִיא לְמַעְלָה מִכְּהֻנָּה גְּדוֹלָה בִּשְׁלֹשִׁים מַעֲלוֹת (אבות ו:ה):\",10,0],[2,136,110,7,\"עַל דִּבְרָתִי מַלְכִּי צֶדֶק. לְמַעְלָה מִכְּהֻנַּת מַלְכִּי צֶדֶק שֶׁהָיָה ״כֹּהֵן לְאֵל עֶלְיוֹן״ (בראשית יד:יח), וְאִם תֹּאמַר: אַף הוּא מֶלֶךְ הָיָה, מְלוּכַת מַלְכִּי צֶדֶק אֵינָהּ מְלוּכָה חֲשׁוּבָה כְּנֶגֶד יִשְׂרָאֵל:\",11,0],[2,136,110,7,\"(ה) אֲדֹנִי. יִהְיֶה תָּמִיד עַל יְמִינְךָ לְהוֹשִׁיעֲךָ:\",12,0],[2,136,110,7,\"אֲשֶׁר מָחַץ בְּיוֹם אַפּוֹ מְלָכִים. שֶׁנִּלְחֲמוּ עִם אַבְרָהָם (בראשית יד:טו) וְעִם יְהוֹשֻׁעַ (יהושע י-יב) וְעִם בָּרָק (שופטים ד-ה):\",13,0],[2,136,110,7,\"(ו) יָדִין בַּגּוֹיִם מָלֵא גְוִיּוֹת. וְעוֹד בִּימֵי חִזְקִיָּהוּ בִּנְךָ יָדִין בְּאוּכְלוּסֵי סַנְחֵרִיב קִבּוּץ פְּגָרִים מֵתִים, וְיִמְחַץ בְּסַנְחֵרִיב שֶׁהוּא רֹאשָׁהּ שֶׁל נִינְוֵה וְאַשּׁוּר שֶׁהִיא אֶרֶץ רַבָּה, אֲשֶׁר מִנַּחַל בַּדֶּרֶךְ הָיָה שׁוֹתֶה, שֶׁנִּתְפָּאֵר שֶׁשָּׁתוּ אוּכְלוּסָיו מִימֵי הַיַּרְדֵּן, שֶׁנֶּאֱמַר (ישעיהו לז:כה) ״אֲנִי קַרְתִּי וְשָׁתִיתִי מַיִם וְאַחֲרִיב וְגוֹ׳״:\",14,0],[2,136,110,7,\"(ז) עַל כֵּן יָרִים רֹאשׁ. הָיָה מִשְׁתַּבֵּחַ וּמִתְפָּאֵר בְּגָדְלוֹ:\",15,0],[2,136,111,1,\"הַלְלוּיָהּ וְגוֹ׳. מִזְמוֹר זֶה הוּסַד בְּאָלֶף בֵּית, אוֹת אֶחָד בְּרֹאשׁ הַפָּסוּק וְאֶחָד בְּאֶמְצָעוּתָיו, וְכֵן כֻּלָּם מֵאָלֶ״ף וְעַד תָּי״ו, וּכְמוֹ כֵן מִזְמוֹר הַשֵּׁנִי. הָרִאשׁוֹן מְדַבֵּר בְּשִׁבְחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַשֵּׁנִי מְסַפֵּר בְּשִׁבְחוֹ שֶׁל צַדִּיק:\",1,0],[2,136,111,4,\"זֵכֶר עָשָׂה. קָבַע לְיִשְׂרָאֵל שַׁבָּתוֹת וּמוֹעֲדִים וּמִצְווֹת שֶׁנֶּאֶמְרוּ בָּהֶם ״וְזָכַרְתָּ כִּי הָיִיתָ בְּמִצְרָיִם״ (דברים טו:טו), לְפִי שֶׁהוּא חַנּוּן וְרַחוּם עַל בָּנָיו וְחָפֵץ לְהַצְדִּיקָם:\",1,0],[2,136,111,5,\"טֶרֶף נָתַן. מָזוֹן:\",1,0],[2,136,111,6,\"כֹּחַ מַעֲשָׂיו הִגִּיד לְעַמּוֹ. כְּשֶׁנָּתַן לָהֶם נַחֲלַת גּוֹיִם הוֹדִיעָם כֹּחוֹ וּגְבוּרָתוֹ. וּמִדְרַשׁ תַּנְחוּמָא (תנחומא, בראשית יא) כָּתַב לְיִשְׂרָאֵל מַעֲשֵׂה בְרֵאשִׁית, לְהוֹדִיעָם שֶׁהָאָרֶץ שֶׁלּוֹ וּבְיָדוֹ לְהוֹשִׁיב בָּהּ כָּל מִי שֶׁיִּרְצֶה וְלַעֲקֹר אֵלּוּ וּלְהוֹשִׁיב אֲחֵרִים, שֶׁלֹּא יוּכְלוּ הָאֻמּוֹת לוֹמַר לְיִשְׂרָאֵל גַּזְלָנִים אַתֶּם שֶׁכְּבַשְׁתֶּם אֶרֶץ שִׁבְעָה גּוֹיִם:\",1,0],[2,136,111,8,\"סְמוּכִים. הֵם פְּקוּדָיו עַל סֶמֶךְ עֹז, מְחֻזָּקִין בָּעֳנָשִׁין וְאַזְהָרוֹת, וְהַפָּרָשִׁיּוֹת קְבוּעוֹת זוֹ עַל זוֹ כְּסֵדֶר וְלִדְרֹשׁ. וְזֶהוּ שֶׁאָמַר שְׁלֹמֹה: ״שׁוֹקָיו עַמּוּדֵי שֵׁשׁ וְגוֹ׳״ (שיר השירים ה:טו):\",1,0],[2,136,112,2,\"דּוֹר יְשָׁרִים. אֲשֶׁר יְבֹרָךְ יִהְיֶה זַרְעוֹ:\",1,0],[2,136,112,4,\"זָרַח בַּחֹשֶׁךְ אוֹר. כְּמוֹ הִזְרִיחַ, וּמִדְרָשׁוֹ: הוּא עַצְמוֹ כִּבְיָכוֹל נַעֲשָׂה לָהֶם אוֹר, כְּמוֹ ״ה׳ אוֹרִי וְיִשְׁעִי״ (תהלים כז:א):\",1,0],[2,136,112,5,\"טוֹב אִישׁ חוֹנֵן וּמַלְוֶה וְגוֹ׳. שֶׁחוֹנֵן דַּלִּים וּמַלְוֶה לָהֶם, וְאֵינוֹ מְדַקְדֵּק לוֹמַר: אֵין יְכֹלֶת בְּיָדִי, וְאֶת דְּבָרָיו הַצְּרִיכִין לוֹ בְּמַאֲכָל וּבְמִשְׁתֶּה וּבִכְסוּת מְכַלְכֵּל בְּמִשְׁפָּט וּבְמִדָּה, וְחָס עַל נְכָסָיו:\",1,0],[2,136,112,5,\"יְכַלְכֵּל דְּבָרָיו בְּמִשְׁפָּט. מַנְהִיג חֲפָצָיו (חולין פד:):\",2,0],[2,136,112,7,\"נָכוֹן לִבּוֹ. נֶאֱמָן לִבּוֹ לְיוֹצְרוֹ:\",1,0],[2,136,112,8,\"סָמוּךְ לִבּוֹ. נִשְׁעָן וּבָטוּחַ עַל הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,136,112,10,\"רָשָׁע יִרְאֶה וְכָעָס. לְשׁוֹן פֹּעַל כְּמוֹ וַיִּכְעַס, לְפִיכָךְ נָקוּד חֶצְיוֹ קָמַץ וְחֶצְיוֹ פַּתַּח וְטַעֲמוֹ לְמַטָּה:\",1,0],[2,136,113,5,\"מִי כַּה׳ אֱלֹהֵינוּ. בַּשָּׁמַיִם וּבָאָרֶץ, שֶׁהוּא מַגְבִּיהִי לָשָׁבֶת וּמַשְׁפִּיל לִרְאוֹת. מַגְבִּיהִי, מַשְׁפִּילִי, מְקִימִי, לְהוֹשִׁיבִי, מוֹשִׁיבִי – כֻּלָּם יוֹ״ד יְתֵרָה בָּהֶם:\",1,0],[2,136,113,9,\"עֲקֶרֶת הַבַּיִת. צִיּוֹן, שֶׁהִיא כַּעֲקָרָה, יוֹשִׁיבֶנָּה:\",1,0],[2,136,113,9,\"אֵם הַבָּנִים שְׂמֵחָה. ״כִּי חָלָה גַּם יָלְדָה צִיּוֹן אֶת בָּנֶיהָ״ (ישעיהו סו:ח):\",2,0],[2,136,114,1,\"מֵעַם לוֹעֵז. עַם שְׂפַת לָשׁוֹן אַחֵר שֶׁאֵינוֹ לְשׁוֹן הַקֹּדֶשׁ, וְחֲבֵרוֹ: ״אֶת עַם נוֹעָז לֹא תִרְאֶה עַם עִמְקֵי שָׂפָה וְגוֹ׳״ (ישעיה לג:יט), וְנוּ״ן וְלָמֶ״ד נֶחְלָפוֹת זוֹ בָּזוֹ, כְּמוֹ ״נִשְׁכָּה״ שֶׁהוּא לִשְׁכָּה בְּסֵפֶר עֶזְרָא (נחמיה יג:ז-ח):\",1,0],[2,136,114,2,\"הָיְתָה יְהוּדָה לְקָדְשׁוֹ. לָקַח יְהוּדָה לְגוֹרַל חֶבְלוֹ וּקְדֻשָּׁתוֹ, וְאַף הֵם קִדְּשׁוּ שְׁמוֹ בִּירִידַת הַיָּם, כְּעִנְיָן שֶׁנֶּאֱמַר (תהלים סח:כח) ״שָׂרֵי יְהוּדָה רִגְמָתָם״. וּכְמוֹ כֵן נִדְרַשׁ בָּאַגָּדָה מִקְרָא זֶה הָיְתָה יְהוּדָה לְקָדְשׁוֹ, שֶׁקָּפַץ נַחְשׁוֹן לְתוֹךְ הַיָּם וְאָמַר: אֲנִי אֵרֵד תְּחִלָּה. וְזֶהוּ שֶׁאָמַר הָיְתָה יְהוּדָה לְקָדְשׁוֹ:\",1,0],[2,136,114,3,\"הַיַּרְדֵּן יִסֹּב לְאָחוֹר. שֶׁכָּל מֵימֵי בְרֵאשִׁית נִבְקְעוּ:\",1,0],[2,136,114,7,\"חוּלִי אָרֶץ. הַמְּחוֹלֵל אֶרֶץ, יוֹ״ד יְתֵרָה בּוֹ, כְּמוֹ ״מַגְבִּיהִי״ (תהלים קיג:ה) ״מַשְׁפִּילִי״ (תהלים קיג:ו) וְ״הַהֹפְכִי״ (תהלים קיד:ח):\",1,0],[2,136,114,8,\"לְמַעְיְנוֹ מָיִם. וָי״ו יְתֵירָה, כְּמוֹ וָי״ו שֶׁל ״וְחַיְתוֹ יַעַר״ (תהלים נ:י):\",1,0],[2,136,115,1,\"לֹא לָנוּ. לֹא בִּשְׁבִילֵנוּ וּבְכֹשֶׁר מַעֲשֵׂינוּ תַּעֲשֶׂה עִמָּנוּ:\",1,0],[2,136,115,1,\"כִּי לְשִׁמְךָ תֵּן כָּבוֹד. כְּדֵי שֶׁלֹּא יֹאמְרוּ: אַיֵּה נָא אֱלֹהֵיהֶם?\",2,0],[2,136,115,7,\"וְלֹא יְמִישׁוּן. לְשׁוֹן ״יְמֻשֵּׁנִי אָבִי״ (בראשית כז:יב):\",1,0],[2,136,115,11,\"יִרְאֵי ה׳. אֵלּוּ הַגֵּרִים:\",1,0],[2,136,116,1,\"אָהַבְתִּי כִּי יִשְׁמַע ה׳ אֶת קוֹלִי. כָּךְ אָמַר דָּוִד לְאַחַר שֶׁנִּפְטַר שָׁאוּל וְהוּא מָלַךְ, שׁוּבִי נַפְשִׁי לִמְנוּחָיְכִי כִּי ה׳ גָּמַל עָלָיְכִי, חֶסֶד, וְלָךְ קוֹנִי אֲנִי מִתְאַוֶּה, כִּי חִלַּצְתָּ נַפְשִׁי מִמָּוֶת:\",1,0],[2,136,116,1,\"אָהַבְתִּי כִּי יִשְׁמַע ה׳. תָּאַבְתִּי שֶׁיִּשְׁמַע ה׳ אֶת קוֹלִי (ס״א אינו):\",2,0],[2,136,116,2,\"וּבְיָמַי אֶקְרָא. בִּימֵי צָרָתִי אֶקְרָאֶנּוּ, וּבִימֵי גְּאֻלָּתִי אֲשַׁבְּחֶנּוּ (תנחומא, יתרו טז):\",1,0],[2,136,116,3,\"חֶבְלֵי מָוֶת. חֲבוּרוֹת אוֹיְבֵינוּ הַמְּבַקְשִׁים לַהֲמִיתֵנִי:\",1,0],[2,136,116,3,\"חֶבְלֵי מָוֶת. ״חֶבְלֵי שְׁאוֹל״ (תהלים יח:ו) – כֻּלָּם לְשׁוֹן חֲבוּרוֹת הֵם, כְּמוֹ ״חֶבֶל נְבִיאִים״ (שמואל א י:ה):\",2,0],[2,136,116,3,\"וּמְצָרֵי שְׁאוֹל. גְּבוּלֵי שְׁאוֹל:\",3,0],[2,136,116,9,\"בְּאַרְצוֹת הַחַיִּים. אֶרֶץ יִשְׂרָאֵל, שֶׁגֵּרְשׁוּנִי אוֹיְבַי וְרוֹדְפַי מִמֶּנָּה בִּימֵי שָׁאוּל, וְעַל כָּרְחָם חָזַרְתִּי:\",1,0],[2,136,116,10,\"הֶאֱמַנְתִּי כִּי אֲדַבֵּר. הֶאֱמַנְתִּי אֶת דִּבְרֵי צִיבָא שֶׁאָמַר עַל מְפִיבֹשֶׁת, כְּשֶׁאֲדַבֵּר ״הִנֵּה לְךָ כֹּל אֲשֶׁר לִמְפִיבֹשֶׁת״ (שמואל ב טז:ד). אָז אֲנִי עָנִיתִי מְאֹד. דִּבַּרְתִּי קָשֶׁה וְנַעֲנֵיתִי לְךָ:\",1,0],[2,136,116,11,\"אֲנִי אָמַרְתִּי בְחָפְזִי. לָנוּס מִפְּנֵי אַבְשָׁלוֹם (שמואל ב טו:יד):\",1,0],[2,136,116,11,\"כָּל הָאָדָם כֹּזֵב. וּבוֹגֵד בְּאוֹהֵב בּוֹ, כִּי רָאִיתִי אֶת בְּנִי בּוֹגֵד בִּי וּמְבַקֵּשׁ אֶת נַפְשִׁי, וְכָל יִשְׂרָאֵל גּוֹמְלִים לִי רָעָה תַּחַת טוֹבָה. לְפִיכָךְ הֶאֱמַנְתִּי לְצִיבָא וְאָמַרְתִּי: אַף מְפִיבֹשֶׁת כּוֹזֵב וּבוֹגֵד בִּי (שמואל ב טז:ד). כָּל לְשׁוֹן כָּזָב אֵינוֹ אֶלָּא לְשׁוֹן חֶסְרוֹן מִבְטָח שֶׁבָּטְחוּ עָלָיו, פילנ״צא בְּלַעַ״ז, כְּמוֹ (ישעיה נח:יא) ״אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו״. וְיֵשׁ פּוֹתְרִין אוֹתוֹ אֲנִי אָמַרְתִּי בְחָפְזִי בְּסֶלַע הַמַּחְלְקוֹת, שֶׁהָיוּ שָׁאוּל וַאֲנָשָׁיו עוֹטְרִין עָלַי וְאֶל אֲנָשַׁי לְתָפְשֵׂנִי, וְשָׁם נֶאֱמַר ״וַיְהִי דָוִד נֶחְפָּז לָלֶכֶת״ (שמואל א כג:כו). כָּל אָדָם כֹּזֵב, אַף שְׁמוּאֵל הַנָּבִיא שֶׁהוּא נֶאֱמָן לְנָבִיא אַף הוּא כּוֹזֵב, שֶׁמְּשָׁחַנִי לְמֶלֶךְ (מצאתי):\",2,0],[2,136,116,13,\"כּוֹס יְשׁוּעוֹת אֶשָּׂא. אָבִיא הַנְּסָכִים עַל הַתּוֹדוֹת שֶׁנָּדַרְתִּי, כְּמוֹ שֶׁאָמַר לְךָ אֶזְבַּח זֶבַח תּוֹדָה, וְעַל אוֹתוֹ הַכּוֹס בְּשִׁמְךָ אֶקְרָא עַל הַיְשׁוּעָה זוֹ. שֶׁכֵּן אֵין הַלֵּוִי אוֹמֵר שִׁירָה אֶלָּא עַל הַיַּיִן:\",1,0],[2,136,116,14,\"נֶגְדָה נָּא לְכָל עַמּוֹ. נֶגֶד כָּל עַמּוֹ:\",1,0],[2,136,116,15,\"יָקָר בְּעֵינֵי ה׳. הֶרְאַנִי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁדָּבָר קָשֶׁה וְכָבֵד הוּא בְּעֵינָיו לְהָמִית אֶת חֲסִידָיו:\",1,0],[2,136,116,15,\"הַמָּוְתָה. הַמָּוֶת, כְּמוֹ ״הַבַּיְתָה״ (בראשית לט:יא), ״הַחוּצָה״ (בראשית לט:יב):\",2,0],[2,136,116,16,\"עַבְדְּךָ בֶּן אֲמָתֶךָ. אֵינוֹ דּוֹמֶה תַּרְבּוּת עֶבֶד הַלָּקוּחַ מִן הַשּׁוּק לִילוּד מִשְׁפָּחָה שֶׁבַּבַּיִת:\",1,0],[2,136,116,16,\"פִּתַּחְתָּ לְמוֹסֵרָי. הִתַּרְתָּ מֵעַל צַוָּארִי מוֹסֵרוֹת וּמוֹטוֹת:\",2,0],[2,136,116,17,\"זֶבַח תּוֹדָה. זִבְחֵי הוֹדָיָה עַל הַנִּסִּים שֶׁעָשִׂיתָ לִי:\",1,0],[2,136,116,18,\"נְדָרַי. קָרְבָּנוֹת שֶׁנָּדַרְתִּי:\",1,0],[2,136,116,19,\"בְּתוֹכֵכִי. כְּמוֹ בְּתוֹכֵךְ:\",1,0],[2,136,117,2,\"כִּי גָבַר עָלֵינוּ חַסְדּוֹ. כְּלוֹמַר: וְאַף כִּי אֲנַחְנוּ, אֲשֶׁר גָּבַר עָלֵינוּ חַסְדּוֹ:\",1,0],[2,136,117,2,\"וֶאֱמֶת ה׳ לְעוֹלָם. שֶׁשָּׁמַר הַבְטָחָתוֹ שֶׁהִבְטִיחַ אֶת הָאָבוֹת (בראשית טו:יח-כא):\",2,0],[2,136,118,2,\"הוֹדוּ לַה׳ וְגוֹ׳ יֹאמַר נָא יִשְׂרָאֵל. לְפִי שֶׁלְּעוֹלָם חַסְדּוֹ :\",1,0],[2,136,118,4,\"יִרְאֵי ה׳. אֵלּוּ בְּנֵי לֵוִי, שֶׁכָּתוּב בָּהֶם (שמות לב:כו) ״מִי לַה׳ אֵלַי וַיֵּאָסְפוּ אֵלָיו כָּל בְּנֵי לֵוִי״ בְּמַעֲשֵׂה הָעֵגֶל, וְנִלְחֲמוּ עִם יִשְׂרָאֵל כְּשֶׁאָמְרוּ (במדבר יד:ד) ״נִתְּנָה רֹאשׁ וְנָשׁוּבָה מִצְרָיְמָה״:\",1,0],[2,136,118,8,\"טוֹב לַחֲסוֹת בַּה׳ וְגוֹ׳. חֶסְיוֹן זֶה אֵינוֹ אֶלָּא לְשׁוֹן חֶסְיוֹן צֵל, וְדָבָר מוּעָט הוּא:\",1,0],[2,136,118,8,\"מִבְּטֹחַ. דָּבָר בָּרִיא וְסֶמֶךְ חָזָק, וְאַף עַל פִּי כֵן לַחֲסוֹת בַּה׳ טוֹב מֵהַבְטָחַת בְּנֵי אָדָם:\",2,0],[2,136,118,10,\"כָּל גּוֹיִם סְבָבוּנִי. מְדַבֵּר בְּמִלְחֲמוֹת גּוֹג וּמָגוֹג (יחזקאל לח-לט) שֶׁכָּל הַגּוֹיִם יִהְיוּ שָׁם, כְּמוֹ שֶׁנֶּאֱמַר ״וְאָסַפְתִּי אֶת כָּל הַגּוֹיִם אֶל יְרוּשָׁלִַם לַמִּלְחָמָה״ (זכריה יד:ב):\",1,0],[2,136,118,10,\"אֲמִילַם. אַכְרִיתֵם, לְשׁוֹן ״יְמוֹלֵל וְיָבֵשׁ״ (תהלים צ:ו):\",2,0],[2,136,118,12,\"דֹּעֲכוּ כְּאֵשׁ קוֹצִים. כָּל לְשׁוֹן דְּעִיכָה נוֹפֵל עַל לְשׁוֹן קְפִיצָה וְנִתּוּר: מְמַהֵר לִהְיוֹת נִתָּר וְנִתָּק מִמְּקוֹמוֹ. עַל כֵּן הוּא נוֹפֵל עַל לְשׁוֹן אֵשׁ וְעַל לְשׁוֹן מַיִם, כְּמוֹ ״נִדְעֲכוּ מִמְּקוֹמָם״ (איוב ו:יז), וְכֵן ״יָמַי נִדְעָכוּ״ (איוב יז:א), וְכֵן ״נֵרוֹ עָלָיו יִדְעָךְ״ (איוב יח:ו), כְּדֶרֶךְ שַׁלְהֶבֶת הַנִּתֶּקֶת מִן הַפְּתִילָה וְעוֹלָה לְמַעְלָה כְּשֶׁהִיא כָּבָה:\",1,0],[2,136,118,13,\"דַּחֹה דְחִיתַנִי לִנְפֹּל. אַתָּה, אוֹיְבִי:\",1,0],[2,136,118,14,\"עָזִּי וְזִמְרָת יָהּ וַיְהִי לִי לִישׁוּעָה. עָזִּי וְזִמְרַת גְּבוּרַת הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה לִי לִישׁוּעָה. עָזִּי יוֹ״ד יְתֵירָהף כִּי לֹא מָצִינוּ בַמִּקְרָא עָזִּי נָקוּד חֲטַף קָמַץ אֶלָּא שׁוּרֵק, חוּץ מִשְּׁלֹשָׁה מְקוֹמוֹת שֶׁהוּא סָמוּךְ אֵצֶל וְזִמְרַת, וְעַל כָּרְחֲךָ וְזִמְרַת דָּבוּק לְתֵיבַת הַשֵּׁם, וְאֵינְךָ יָכוֹל לְפָרְשׁוֹ וְזִמְרָתִי, וְאַל תִּתְמַהּ עַל וַיְהִי לִי, שֶׁלֹּא אָמַר הָיָה לִי לִישׁוּעָה, שֶׁהַרְבֵּה כָּאֵלֶּה בַמִּקְרָא, ״וַאֲשֶׁר לֹא שָׂם לִבּוֹ וְגוֹ׳ וַיַּעֲזֹב אֶת עֲבָדָיו וְגוֹ׳״ (שמות ט:כא) הָיָה לוֹ לִכְתֹּב עָזַב:\",1,0],[2,136,118,15,\"קוֹל רִנָּה וִישׁוּעָה. תִּהְיֶה לֶעָתִיד בְּאָהֳלֵי צַדִּיקִים, וּמַהוּ קוֹל הָרִנָּה? יְמִין ה׳ עֹשָׂה חָיִל, יְרַנְּנוּ, יְמִין ה׳ רוֹמֵמָה וְגוֹ׳:\",1,0],[2,136,118,16,\"יְמִין ה׳ רוֹמֵמָה. מִדְרַשׁ אַגָּדָה: עֶלְיוֹנִים בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיָמִין, לְפִיכָךְ לֹא שָׁלְטָה בָּהֶם מִיתָה, שֶׁנֶּאֱמַר ״אַף יָדִי יָסְדָה אֶרֶץ״ (ישעיה מח:יג) זֶה שְׂמֹאל ״וִימִינִי טִפְּחָה שָׁמַיִם״ (ישעיה מח:יג) זֶה יָמִין. וְכֵן אָמַר הַמְשׁוֹרֵר יְמִין ה׳ רוֹמֵמָה שֶׁבָּרָאתָ אוֹתָם שֶׁבְּרוּמוֹ שֶׁל עוֹלָם, הִיא יְמִין ה׳ שֶׁתַּעֲשֶׂה חֲיָלוֹת שֶׁל צַדִּיקִים לֶעָתִיד לָבוֹא, וְגַם בָּהּ יְחַיֶּה אוֹתָם וְיִחְיוּ לְעוֹלָם, וְאָז לֹא אָמוּת כִּי אֶחְיֶה לְעוֹלָם:\",1,0],[2,136,118,17,\"לֹא אָמוּת. אֲנִי, כְּנֶסֶת יִשְׂרָאֵל, כְּעוֹבְדֵי גִּלּוּלִים, מִיתַת עוֹלָם כִּי אֶחְיֶה וְגוֹ׳:\",1,0],[2,136,118,18,\"יַסֹּר יִסְּרַנִּי יָּהּ. בַּגָּלוּת, וְשָׁם נִתְכַּפְּרוּ כָּל עֲוֹנוֹתַי, וְלַמָּוֶת לֹא נְתָנָנִי:\",1,0],[2,136,118,19,\"פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. וְאֵלּוּ הֵן שַׁעֲרֵי צֶדֶק?\",1,0],[2,136,118,20,\"זֶה הַשַּׁעַר. שֶׁל בֵּית הַמִּקְדָּשׁ שֶׁהוּא לַה׳, וְהַצַּדִּיקִים יָבֹאוּ בוֹ, וְשָׁם אוֹדְךָ כִּי עֲנִיתָנִי מִן הַגָּלוּת:\",1,0],[2,136,118,22,\"אֶבֶן מָאֲסוּ הַבּוֹנִים. עַם שֶׁהָיוּ שָׁפָל בֵּין הָאֻמּוֹת:\",1,0],[2,136,118,23,\"מֵאֵת ה׳ הָיְתָה זֹּאת. כָּךְ יֹאמְרוּ הַכֹּל:\",1,0],[2,136,118,26,\"בָּרוּךְ הַבָּא בְּשֵׁם ה׳. יֹאמְרוּ לִמְבִיאֵי הַבִּכּוּרִים וּלְעוֹלֵי הָרְגָלִים:\",1,0],[2,136,118,26,\"בֵּרַכְנוּכֶם. בֵּרַכְנוּ אֶתְכֶם:\",2,0],[2,136,118,27,\"אִסְרוּ חַג בַּעֲבוֹתִים. הַזְּבָחִים וְהַחֲגִיגוֹת שֶׁהָיוּ נְקִיִּים וּבְדוּקִין מִמּוּם קוֹשְׁרִין בְּכַרְעֵי מִטּוֹתֵיהֶם, עַד שֶׁיְּבִיאוּם לָעֲזָרָה בְּקַרְנוֹת הַמִּזְבֵּחַ. וְיֵשׁ לִפְתּוֹר כָּל סוֹף הַמִּזְמוֹר הַזֶּה מִלֹּא אָמוּת כִּי אֶחְיֶה בְּדָוִד עַצְמוֹ:\",1,0],[2,136,118,27,\"(יח) יִסּוֹר יִסְּרַנִּי יָּהּ. עַל מַעֲשֵׂה בַת שֶׁבַע בְּיִסּוּרִין, כְּגוֹן ״תַּחַת הַכִּבְשָׂה יְשַׁלֵּם אַרְבַּעְתַּיִם״ (שמואל ב יב:ו). שִׁשָּׁה חֳדָשִׁים נִצְטָרַע דָּוִד (יומא כב:):\",2,0],[2,136,118,27,\"וְלָמוּת לֹא נְתָנָנִי. שֶׁנֶּאֱמַר: ״גַּם ה׳ הֶעֱבִיר חַטָּאתְךָ לֹא תָמוּת״ (שמואל ב יב:יג):\",3,0],[2,136,118,27,\"(יט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. וְאֵלּוּ הֵן שַׁעֲרֵי צֶדֶק? אוֹתָם הַשְּׁעָרִים שֶׁל בָּתֵּי כְנֵסִיּוֹת וּמִדְרָשׁוֹת, אֲשֶׁר הֵם לַה׳, וְהַצַּדִּיקִים בָּאִים בָּהֶם:\",4,0],[2,136,118,27,\"(כא) אוֹדְךָ כִּי עֲנִיתָנִי. מִכָּאן וָאֵילָךְ אָמַר דָּוִד וּשְׁמוּאֵל וְיִשַׁי וַאֲחֵי דָוִד, כְּמוֹ שֶׁמְּפֹרָשׁ בְּעַרְבֵי פְסָחִים (פסחים קיט.): מִי שֶׁאָמַר זֶה לֹא אָמַר זֶה:\",5,0],[2,136,119,3,\"אַף לֹא פָעֲלוּ עַוְלָה. אַשְׁרֵיהֶם אִם כָּל זֶה בָּהֶם:\",1,0],[2,136,119,3,\"בִּדְרָכָיו הָלָכוּ. אַף עַל פִּי שֶׁלֹּא פָּעֲלוּ עַוְלָה, אֵין שְׂכָרָם שָׁלֵם אֶלָּא אִם כֵּן בִּדְרָכָיו הָלָכוּ. וְכֵן הוּא אוֹמֵר ״סוּר מֵרָע וַעֲשֵׂה טוֹב״ (תהלים לד:טו) – אַף עַל פִּי שֶׁאַתָּה סָר מֵרָע, אֵין הַכֹּל שָׁלֵם אֶלָּא אִם כֵּן תַּעֲשֶׂה טוֹב (מדרש אגדה):\",2,0],[2,136,119,5,\"אַחֲלַי יִכֹּנוּ דְרָכָי. אָלֶ״ף יְסוֹד בַּתֵּיבָה, הַנּוֹפֵל מִמֶּנּוּ לִפְרָקִים, כְּמוֹ אָלֶ״ף שֶׁבְּ״אַחֲוָתִי בְאָזְנֵיכֶם״ (איוב יג:יז) וְאָלֶ״ף שֶׁל ״אָסוּךְ שָׁמֶן״ (מלכים ב ד:ב). אַחֲלַי תְּפִלּוֹתַי אֵלּוּ הֵן: שֶׁיִּכּוֹנוּ דְרָכָי. וְכֵן ״אַחֲלֵי אֲדֹנִי לִפְנֵי הַנָּבִיא אֲשֶׁר בְּשֹׁמְרוֹן וְגוֹ׳״ (מלכים ב ה:ג) – צָרְכֵי אֲדוֹנִי, לְהִתְפַּלֵּל שֶׁיֵּלֵךְ לִפְנֵי הַנָּבִיא אֲשֶׁר בְּשׁוֹמְרוֹן. וְלָשׁוֹן אַחֲלִיּוּת שוהיי״ט בְּלַעַ״ז, כְּאָדָם הָאוֹמֵר: הַלְוַאי וְהָיִיתִי נָבִיא וְחָכָם:\",1,0],[2,136,119,11,\"בְּלִבִּי צָפַנְתִּי. לֹא נְתַתִּיהָ לְהִשְׁתַּכֵּחַ מִמֶּנִּי:\",1,0],[2,136,119,16,\"אֶשְׁתַּעֲשָׁע. אֶתְעַסֵּק, כְּמוֹ ״יִשְׁעֶה הָאָדָם עַל עֹשֵׂהוּ״ (ישעיהו יז:ז), ״וְאַל יִשְׁעוּ בְּדִבְרֵי שָׁקֶר״ (שמות ה:ט):\",1,0],[2,136,119,17,\"גְּמֹל עַל עַבְדְּךָ. דָּבָר שֶׁאֶחְיֶה בּוֹ בִּגְמוּל חַסְדְּךָ:\",1,0],[2,136,119,18,\"נִפְלָאוֹת מִתּוֹרָתֶךָ. דְּבָרִים הַמְכֻסִּים בָּהּ, שֶׁאֵינָם מְפֹרָשִׁים בָּהּ:\",1,0],[2,136,119,18,\"מִתּוֹרָתֶךָ. נִפְלָאִים מִפֵּירוּשֵׁי תּוֹרָתֶךָ שֶׁאֵינָם מְפוֹרָשִׁים בָּהּ (מצאתי):\",2,0],[2,136,119,19,\"גֵּר אָנֹכִי בָאָרֶץ. יָמִים מוּעָטִים:\",1,0],[2,136,119,19,\"אַל תַּסְתֵּר מִמֶּנִּי. מִצְוֹתֶיךָ הַנֶּעֱלָמוֹת שֶׁאוּכַל לְקַיְּמָם, שֶׁאִם לֹא עַכְשָׁיו אֵימָתַי:\",2,0],[2,136,119,20,\"גָּרְסָה. מִשְׁתַּבֶּרֶת נַפְשִׁי מֵחֲמַת תַּאֲוָה, כְּמוֹ ״גֶּרֶשׂ כַּרְמֶל״ (ויקרא ב:יד). וּמְנַחֵם חִבֵּר לְתַאֲבָה עִם ״מְתָאֵב אָנֹכִי אֶת גְּאוֹן יַעֲקֹב״ (עמוס ו:ח), וּשְׁנֵיהֶם לְשׁוֹן שֶׁבֶר:\",1,0],[2,136,119,22,\"גַּל מֵעָלַי. לְשׁוֹן גִּלְגּוּל, כְּמוֹ ״וַיָּגֶל אֶת הָאָבֶן״ (בראשית כט:י):\",1,0],[2,136,119,23,\"בִּי נִדְבָּרוּ. אַף עַל פִּי שֶׁמַּלְכֵי אֻמּוֹת הָעוֹלָם מִתְלוֹצְצִים עָלַי שֶׁאֲנִי עוֹסֵק בַּתּוֹרָה:\",1,0],[2,136,119,24,\"שַׁעֲשׁוּעָי. עִסְקִי:\",1,0],[2,136,119,25,\"חַיֵּנִי כִּדְבָרֶךָ. כְּמוֹ שֶׁהִבְטַחְתַּנִי עַל יְדֵי נָתָן הַנָּבִיא טוֹבָה (שמואל ב ז:יב-טז):\",1,0],[2,136,119,26,\"סִפַּרְתִּי. לְךָ אֶת צְרָכַי וְאֶת חֲטָאתִי, וְאַתָּה עֲנִיתָנִי:\",1,0],[2,136,119,28,\"דָּלְפָה נַפְשִׁי. נָטְפָה, כְּלוֹמַר: נֶחְסֶרֶת וְהוֹלֶכֶת:\",1,0],[2,136,119,30,\"מִשְׁפָּטֶיךָ שִׁוִּיתִי. שַׂמְתִּי עַצְמִי לְמִשְׁפָּטֶיךָ וְדָבַקְתִּי בְּעֵדוֹתֶיךָ, לִבְחוֹר בְּדֶרֶךְ אֱמוּנָה. לְךָ אֲנִי שׁוֹאֵל: דֶּרֶךְ שֶׁקֶר הָסֵר מִמֶּנִּי:\",1,0],[2,136,119,33,\"וְאֶצְּרֶנָּה עֵקֶב. אֶשְׁמְרֶנָּה בְּכָל מַעְגְּלוֹתֶיהָ וְעִקְּבֵי נְתִיבוֹתֶיהָ, לְשׁוֹן עֲקֵבִים, טְרָאצֵ״שׁ בְּלַעַ״ז:\",1,0],[2,136,119,38,\"הָקֵם לְעַבְדְּךָ אִמְרָתֶךָ. אֲשֶׁר הִבְטַחְתַּנִי:\",1,0],[2,136,119,38,\"אֲשֶׁר לְיִרְאָתֶךָ. שֶׁאֶהְיֶה אֲנִי וְזַרְעִי יִרְאֵי שְׁמֶךָ, שֶׁעַל מְנָת כֵּן הִבְטַחְתַּנִי: ״אִם יִשְׁמְרוּ בָנֶיךָ אֶת דַּרְכָּם וְגוֹ׳״ (מלכים א ב:ד):\",2,0],[2,136,119,39,\"הַעֲבֵר חֶרְפָּתִי. מְחוֹל לִי עַל אוֹתוֹ עָוֹן, וְשׁוּב לֹא יוּכְלוּ אוֹיְבַי לְחָרְפֵנִי בּוֹ:\",1,0],[2,136,119,39,\"כִּי מִשְׁפָּטֶיךָ טוֹבִים. וּכְבָר אֲנִי מְקַבֵּל עָלַי לְשַׁלֵּם הַכִּבְשָׂה אַרְבַּעְתַּיִם (שמואל ב יב:ו):\",2,0],[2,136,119,41,\"וִיבֹאֻנִי. תְּשׁוּעָתְךָ תָּבֹא אֵלַי כְּאִמְרָתֶךָ שֶׁהִבְטַחְתַּנִי:\",1,0],[2,136,119,43,\"וְאַל תַּצֵּל מִפִּי דְבַר אֱמֶת. וְאַל תַּבְדֵּל מִפִּי דְּבַר אֱמֶת, כְּמוֹ ״וַיַּצֵּל אֱלֹהִים אֶת מִקְנֵה אֲבִיכֶם״ (בראשית לא:ט) (מצאתי):\",1,0],[2,136,119,43,\"דְּבַר אֱמֶת עַד מְאֹד. בְּכָל הוֹרָאוֹתַי וּבְכָל דִּינַי, שֶׁלֹּא אֶכָּשֵׁל בָּהֶם:\",2,0],[2,136,119,43,\"יִחָלְתִּי. קִוִּיתִי:\",3,0],[2,136,119,45,\"וְאֶתְהַלְּכָה בָרְחָבָה. בַּהֲלָכָה מְרֻוַּחַת וּפוֹשֶׁטֶת בְּיִשְׂרָאֵל:\",1,0],[2,136,119,45,\"דָּרָשְׁתִּי. בִּקַּשְׁתִּי:\",2,0],[2,136,119,49,\"זְכֹר דָּבָר. אֲשֶׁר יִחַלְתַּנִי עַל יְדֵי נָתָן הַנָּבִיא לְעַבְדֶּךָ (שמואל ב ז:יב-טז):\",1,0],[2,136,119,52,\"מִשְׁפָּטֶיךָ מֵעוֹלָם. שֶׁאַתָּה מֵבִיא יִסּוּרִין וְחוֹזֵר מֵחֲמָתְךָ וְסוֹלֵחַ, וְעַל כֵּן אֶתְנֶחָם:\",1,0],[2,136,119,55,\"זָכַרְתִּי בַלַּיְלָה. בְּעֵת צָרָה וַאֲפֵלָה:\",1,0],[2,136,119,56,\"זֹאת הָיְתָה לִּי. עֲטֶרֶת הַהוֹלֶמֶת אוֹתִי לִי לְעֵדוּת, וּלְזַרְעִי הָרָאוּי לִמְלוֹךְ, בִּשְׂכַר שֶׁפִּקֻּדֶיךָ נָצָרְתִּי. כָּךְ דְּרָשׁוּהוּ חַכְמֵי יִשְׂרָאֵל (עבודה זרה מד.) (מצאתי):\",1,0],[2,136,119,57,\"לִשְׁמֹר דְּבָרֶיךָ. קַיֵּם דְּבָרֶיךָ שֶׁיִּחַלְתַּנִי בְּכָךְ, אַתָּה חֶלְקִי:\",1,0],[2,136,119,58,\"חִלִּיתִי פָנֶיךָ. בִּלְשׁוֹן ״חֶלְקִי ה׳ אָמְרָה נַפְשִׁי עַל כֵּן אוֹחִיל לוֹ״ (איכה ג:כד):\",1,0],[2,136,119,59,\"חִשַּׁבְתִּי דְרָכָי. הֶפְסֵד מִצְוָה כְּנֶגֶד שְׂכָרָהּ, וּשְׂכַר עֲבֵרָה כְּנֶגֶד הֶפְסֵדָהּ, לְפִיכָךְ וָאָשִׁיבָה רַגְלַי אֶל עֵדוֹתֶיךָ, כִּי רָאִיתִי שֶׁהִיא הַטּוֹבָה שֶׁבְּכֻלָּן (ויקרא רבה לה.):\",1,0],[2,136,119,61,\"חֶבְלֵי רְשָׁעִים עִוְּדוּנִי. סִיעוֹת שֶׁל רְשָׁעִים שְׁלָלוּנִי, כְּמוֹ ״יֹאכַל עַד״ (בראשית מט:כז), כָּךְ חִבְּרוֹ מְנַחֵם. וְיֵשׁ לְפוֹתְרוֹ לְשׁוֹן עוֹד, כְּלוֹמַר: נוֹסְפוּ וְרָבוּ עָלַי:\",1,0],[2,136,119,67,\"טֶרֶם אֶעֱנֶה. אוֹתְךָ בְּמִצְוֹתֶיךָ, טֶרֶם הָגִיתִי בָּהֶם בְּבָתֵּי מִדְרָשׁוֹת אֲנִי שֹׁגֵג בָּהֶם וְחוֹטֵא. וְעַתָּה מִשֶּׁנַּעֲנֵיתִי בָּהֶם תּוֹרָתְךָ שָׁמָרְתִּי, שֶׁהַמִּדְרָשׁ מְלַמְּדֵנִי לָסוּר מִן הָעֲבֵירָה. לָכֵן אֲנִי מְבַקֵּשׁ מִמְּךָ טוּב טַעַם וָדַעַת לַמְּדֵנִי:\",1,0],[2,136,119,67,\"אֶעֱנֶה. לְשׁוֹן שׁוֹנֶה וְהוֹגֶה בְּבֵית הַמִּדְרָשׁ הוּא, כְּמוֹ תַּעַן לְשׁוֹנִי אִמְרָתֶךָ. וְכֵן ״יַכְרֵת ה׳ לָאִישׁ אֲשֶׁר יַעֲשֶׂנָּה עֵר וְעֹנֶה מֵאָהֳלֵי יַעֲקֹב״ (מלאכי ב:יב), עֵר בַּחֲכָמִים וְעוֹנֶה בַּתַּלְמִידִים:\",2,0],[2,136,119,69,\"טָפְלוּ עָלַי שֶׁקֶר. חִבְּרוּ עָלַי שֶׁקֶר, וְכֵן ״וְתִטְפֹּל עַל עֲוֹנִי״ (איוב יד:יז):\",1,0],[2,136,119,71,\"טוֹב לִי כִּי עֻנֵּיתִי. שֶׁנִּתְיַסַּרְתִּי וְעֻנֵּיתִי לְמַעַן אָשׁוּב מִדֶּרֶךְ רָעָה וְאֶשְׁמֹר חֻקֶּיךָ. בְּפֵרוּשִׁים אֲחֵרִים מָצָאתִי כֵּן: טוֹב לִי כִּי עֻנֵּיתִי וְגוֹ׳, טוֹב הָיָה בְּעֵינַי כְּשֶׁהָיִיתִי סוֹבֵל יִסּוּרִים כְּדֵי לִלְמֹד תּוֹרָה בְּצַעַר:\",1,0],[2,136,119,74,\"יְרֵאֶיךָ יִרְאוּנִי. בְּטוֹבָה וְיִשְׂמָחוּ, כִּי כִּגְמוּלִי גְּמוּלָם, שֶׁהֲרֵי מִיְּרֵאֶיךָ אֲנִי וְלִדְבָרְךָ יִחָלְתִּי:\",1,0],[2,136,119,75,\"וֶאֱמוּנָה עִנִּיתָנִי. בְּדִין עִנִּיתָנִי:\",1,0],[2,136,119,78,\"כִּי שֶׁקֶר עִוְּתוּנִי. כִּי עַל חִנָּם הִרְשִׁיעוּנִי (מצאתי). אוֹמֵר אֲנִי: עַל לִבּוּן פָּנִים, שֶׁאוֹמֵר לוֹ: הַבָּא עַל אֵשֶׁת אִישׁ – מִיתָתוֹ בַּמֶּה? וְהוּא לֹא חָטָא (סנהדרין קז.):\",1,0],[2,136,119,79,\"יָשׁוּבוּ לִי יְרֵאֶיךָ. שֶׁפֵּרְשׁוּ הֵימֶנּוּ סַנְהֶדְרִין כְּשֶׁנִּצְטָרַע מֵאוֹתוֹ עָוֹן (סנהדרין קז.). אַף אִם גְּרוּשָׁה הִיא נָתַן עֵינָיו בָּהּ, כָּל הַנּוֹגֵעַ לֹא יִנָּקֶה (משלי ו:כט):\",1,0],[2,136,119,81,\"כָּלְתָה וְגוֹ׳ נַפְשִׁי. אִוְּתָה:\",1,0],[2,136,119,82,\"כָּלוּ עֵינַי. צוֹפִים תָּמִיד עַד כִּי כָּלוּ:\",1,0],[2,136,119,83,\"כְּנֹאד בְּקִיטוֹר. כְּנֹאד שֶׁל עוֹר הַמִּתְיַבֵּשׁ בֶּעָשָׁן:\",1,0],[2,136,119,84,\"מָתַי תַּעֲשֶׂה. שֶׁאֶרְאֶה בְּיָמַי:\",1,0],[2,136,119,85,\"כָּרוּ לִי זֵדִים שִׁיחוֹת. שֶׁלֹּא כַתּוֹרָה הַבָּאִים לְפָסְלֵנִי:\",1,0],[2,136,119,86,\"כָּל מִצְוֺתֶיךָ אֱמוּנָה. מוֹאָבִי וְלֹא מוֹאָבִית (יבמות עז.), וְהֵם עַל שֶׁקֶר רָדְפוּ לְאָסְרֵנִי:\",1,0],[2,136,119,86,\"שֶׁקֶר רְדָפוּנִי. לַשָּׁוְא רְדָפוּנִי אוֹיְבַי:\",2,0],[2,136,119,87,\"כִּמְעַט כִּלּוּנִי. כְּלֹא הָיִיתִי אֶהְיֶה בָּאָרֶץ (איוב י:יט), וַאֲנִי עָמַדְתִּי עַל בֻּרְיִי, וְכֵן לִי קִוּוּ רְשָׁעִים לְאַבְּדֵנִי מִבֹּא בַּקָּהָל:\",1,0],[2,136,119,96,\"לְכָל תִּכְלָה וְגוֹ׳. לְסַלְסֵל וּלְפַלְפֵּל בָּהּ, וְכֵן ״פִּתַּחְתָּ לְמוֹסֵרָי״ (תהלים קטז:טז):\",1,0],[2,136,119,96,\"לְכָל תִּכְלָה. לְכָל סִיּוּם דָּבָר יֵשׁ קֵץ גְבוּל, אֲבָל מִצְוָתְךָ אֵין קֵץ וּגְבוּל לְתַכְלִיתָם (מצאתי):\",2,0],[2,136,119,98,\"מֵאוֹיְבַי תְּחַכְּמֵנִי מִצְוֺתֶךָ. עַל דּוֹאֵג וַאֲחִיתֹפֶל אָמְרוּ, דְּלָא אָתְיָא לְהוּ שְׁמַעְתָּא אֲלִיבָּא דְהִלְכְתָא (סוטה כא.). לְעוֹלָם סוֹד הַתּוֹרָה בְּיָדִי, שֶׁכֵּן מִכָּל מְלַמְּדַי הִשְׂכַּלְתִּי. מִזֶּה לָמַדְתִּי קְצָת וּמִזֶּה לָמַדְתִּי קְצָת (לְאַחַר שֶׁלָּמַדְתִּי מֵרַבִּי מֻבְהָק):\",1,0],[2,136,119,99,\"שִׂיחָה לִי. כָּל שִׂיחָתִי הָיְתָה בָּם:\",1,0],[2,136,119,101,\"כָּלִאתִי רַגְלָי. מָנַעְתִּי, כְּמוֹ ״אֲשֶׁר כְּלִיתִנִי הַיּוֹם מִבּוֹא בְדָמִים״ (שמואל א כה:לג):\",1,0],[2,136,119,103,\"נִמְלְצוּ. נִמְתְּקוּ:\",1,0],[2,136,119,105,\"נֵר לְרַגְלִי דְבָרֶךָ. כְּשֶׁאֲנִי בָּא לְהוֹרוֹת הוֹרָאָה, אֲנִי רוֹאֶה בַּתּוֹרָה, וְהִיא מַפְרֶשֶׁת אוֹתִי מִן הָאִסּוּר כְּנֵר הַמַּצִּיל אֶת הָאָדָם מִן הַפְּחָתִים:\",1,0],[2,136,119,107,\"נַעֲנֵיתִי. נַעֲשֵׂיתִי עָנִי וְשָׁפָל, כְּמוֹ ״לֵעָנוֹת מִפָּנַי״ (שמות י:ג), וְ״עָנָה גְאוֹן יִשְׂרָאֵל בְּפָנָיו״ (הושע ה:ה) תַּרְגּוּם יוֹנָתָן: ״וְיִמָּאךְ״. וְעָנִי חָשׁוּב כְּמֵת, לְפִיכָךְ חַיֵּנִי כִדְבָרֶךָ:\",1,0],[2,136,119,107,\"נַעֲנֵיתִי. חֳלִי הוּא שֶׁמְּטָרֵף אֶת הַדַּעַת, וּשְׁמוֹ עֲנִיָּה בִּלְשׁוֹן מִשְׁנָה (חולין ס:):\",2,0],[2,136,119,108,\"נִדְבוֹת פִּי. דָּבָר רָצוּי שֶׁפִּי מִתְנַדֵּב לְךָ, כָּל נְדָבָה לְשׁוֹן רָצוֹן הוּא:\",1,0],[2,136,119,109,\"נַפְשִׁי בְכַפִּי תָמִיד. הַרְבֵּה נִסְתַּכַּנְתִּי, בִּסְכָנוֹת רַבּוֹת קְרוֹבוֹת לְמִיתָה, וְאַף עַל פִּי כֵן אֲנִי תוֹרָתְךָ לֹא שָׁכָחְתִּי (על דרך חש בראשו יעסוק בתורה):\",1,0],[2,136,119,112,\"לְעוֹלָם עֵקֶב. עַל מַעְגְּלוֹתָם וְעַל נְתִיבוֹתָם:\",1,0],[2,136,119,113,\"סֵעֲפִים שָׂנֵאתִי. חוֹשְׁבֵי מַחְשְׁבוֹת אָוֶן, כְּמוֹ (איוב כ:ב) ״לָכֵן שְׂעִיפַי יְשִׁיבוּנִי״, (מלכים א יח:כא) ״עַל שְׁתֵּי הַסְּעִפִּים״. כְּשֶׁאַתָּה קוֹרֵא סְעִיפִים הוּא שֵׁם הַמַּחֲשָׁבָה, וּכְשֶׁאַתָּה קוֹרֵא סֵעֲפִים נוֹפֵל הַלָּשׁוֹן עַל הַחוֹשְׁבִים אוֹתָם:\",1,0],[2,136,119,117,\"וְאֶשְׁעָה בְחֻקֶּיךָ. וְאֶתְעַסֵּק, כְּמוֹ ״וְאַל יִשְׁעוּ בְּדִבְרֵי שָׁקֶר״ (שמות ה:ט). דָּבָר אַחֵר: וְאֶשְׁעָה לְשׁוֹן סִפּוּר וְשִׁנּוּן, כְּדִמְתַרְגְּמִינָן ״וְלִשְׁנִינָה״ (דברים כח:לז): ״וּלְשׁוֹעִין״ (תרגום אונקלוס):\",1,0],[2,136,119,118,\"סָלִיתָ. רָמַסְתָּ, נְתַתָּם לְמִרְמָס, כְּמוֹ ״סִלָּה כָּל אַבִּירַי ה׳״ (איכה א:טו):\",1,0],[2,136,119,120,\"סָמַר. כְּמוֹ (איוב ד:טו) ״תְּסַמֵּר שַׂעֲרַת בְּשָׂרִי״, כְּאָדָם שֶׁעָמְדוּ שַׂעֲרוֹתָיו. הִירִיצִיי״ר בְּלַעַ״ז:\",1,0],[2,136,119,120,\"וּמִמִּשְׁפָּטֶיךָ יָרֵאתִי. מִפֻּרְעָנוּת גְּזֵרוֹתֶיךָ:\",2,0],[2,136,119,122,\"עֲרֹב עַבְדְּךָ. לְשׁוֹן הַצָּלָה, גרנטיי״ה בְּלַעַ״ז. הֱיֵה עָרֵב בִּשְׁבִילִי לְנֶגֶד הָרָעָה (כְּלוֹמַר הָיָה עָרֵב שֶׁאֶשְׁמֹר פְּקוּדֶיךָ):\",1,0],[2,136,119,123,\"וּלְאִמְרַת צִדְקֶךָ. הַבְטָחָה שֶׁהִבְטַחְתַּנִי:\",1,0],[2,136,119,126,\"עֵת לַעֲשׂוֹת לַה׳ וְגוֹ׳. מוּסָב עַל מִקְרָא שֶׁלְּפָנָיו הֲבִינֵנִי וְאֵדְעָה עֵדוֹתֶיךָ, לְהָבִין עֵת לַעֲשׂוֹת לְשִׁמְךָ, אֵיךְ יַעֲשׂוּ אוֹתָם שֶׁהֵפֵרוּ תוֹרָתֶךָ לִמְצֹא רָצוֹן וּסְלִיחָה וְתִמָּצֵא לָהֶם, וְאֶעֱשֶׂה כֵּן עַל כָּל עֲבֵירָה שֶׁבְּיָדִי. וְרַבּוֹתֵינוּ דָּרְשׁוּ מִמֶּנּוּ שֶׁעוֹבְרִין עַל דִּבְרֵי תוֹרָה כְּדֵי לַעֲשׂוֹת סְיָג וְגָדֵר לְיִשְׂרָאֵל, כְּגוֹן גִּדְעוֹן וְאֵלִיָּה בְּהַר הַכַּרְמֶל שֶׁהִקְרִיבוּ בַּבָּמָה (ברכות סג.). עוֹד רָאִיתִי נִדְרָשׁ בָּאַגָּדָה (ירושלמי ברכות ט:ד, מדרש שמואל א:א) פֵּרוּשׁ: אִישׁ פָּנוּי וְטַיְלָן הָעוֹשֶׂה תוֹרָתוֹ עִתִּים מֵפֵר בְּרִית, שֶׁאָדָם (פָּנוּי) צָרִיךְ לִהְיוֹת יָגֵעַ בַּתּוֹרָה כָּל שָׁעוֹת הַיּוֹם:\",1,0],[2,136,119,127,\"עַל כֵּן אָהַבְתִּי. עַל אֲשֶׁר אָהַבְתִּי מִצְוֹתֶיךָ רָאוּי לְךָ לְלַמְּדֵנִי עֵת רָצוֹן וּמָה אֶעֱשֶׂה לְךָ וְתִרְצֵנִי. יֵשׁ עַל כֵּן הַרְבֵּה שֶׁפִּתְרוֹנוֹ עַל אֲשֶׁר, כְּמוֹ ״כִּי עַל כֵּן רָאִיתִי פָנֶיךָ״ (בראשית לג:י), ״כִּי עַל כֵּן יָדַעְתָּ חֲנֹתֵנוּ״ (במדבר י:לא), ״עַל כֵּן יִתְרָה עָשָׂה״ (ישעיהו טו:ז):\",1,0],[2,136,119,128,\"כָּל פִּקּוּדֵי כֹל יִשָּׁרְתִּי. כָּל פִּקּוּדֵי – כָּל דָּבָר אֲשֶׁר צִוִּיתָ בְּתוֹרָתֶךָ:\",1,0],[2,136,119,128,\"יִשָּׁרְתִּי. יָשְׁרוּ בְּעֵינַי, וְאָמַרְתִּי עֲלֵיהֶם: יָשְׁרוּ. כָּל זֶה כְּדַאי אֲנִי שֶׁתִּמְחוֹל וְתִרְצֶה לִי:\",2,0],[2,136,119,129,\"פְּלָאוֹת עֵדְוֺתֶיךָ. מְכֻסִּים הֵם וְנִפְלָאִים עֵדְוֺתֶיךָ מִבְּנֵי אָדָם. יֵשׁ מִצְווֹת קַלּוֹת שֶׁהִרְבֵּיתָ בְּמַתַּן שְׂכָרָן, כְּגוֹן שִׁלּוּחַ הַקֵּן (דברים כב:ו-ז):\",1,0],[2,136,119,129,\"עַל כֵּן נְצָרָתַם נַפְשִׁי. כֻּלָּם, כִּי לֹא נוֹדַע אֵיזֶה יִכְשַׁר (קהלת יא:ו):\",2,0],[2,136,119,130,\"פֵּתַח דְּבָרֶיךָ יָאִיר. תְּחִלַּת דְּבָרֶיךָ הֵאִירוּ אֶת לֵב יִשְׂרָאֵל, שֶׁאַתָּה הַמֵּבִין פְּתָיִים בְּאָמְרְךָ (שמות כ:ב) ״אָנֹכִי אֲשֶׁר הוֹצֵאתִיךָ״, הוֹדַעְתָּם בַּטּוֹבָה שֶׁעָשִׂיתָ לָהֶם, שֶׁקְּנִיתָם מִבֵּית עֲבָדִים לָדַעַת כִּי אָדוֹן אַתָּה לָהֶם וִיקַבְּלוּ אֱלֹהוּתְךָ עֲלֵיהֶם, ״לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים וְגוֹ׳״, וְאַחַר כָּךְ גָּזַרְתָּ גְּזֵרוֹתֶיךָ. דָּבָר אַחֵר: פֵּתַח דְּבָרֶיךָ יָאִיר תְּחִלַּת דְּבָרֶיךָ בְּמַעֲשֵׂה בְרֵאשִׁית (בראשית א:ג) ״יְהִי אוֹר״:\",1,0],[2,136,119,130,\"מֵבִין פְּתָיִים. מִשָּׁם יָבִינוּ הַכֹּל וְיִפְתְּחוּ (לְהַתְחִיל וְלִפְתֹּחַ) בְּדִבְרֵי תוֹרָה, תַּנְחוּמָא (תנחומא, ויקהל ו):\",2,0],[2,136,119,131,\"וָאֶשְׁאָפָה. לְשׁוֹן בְּלִיעָה, כְּמוֹ ״שָׁאֲפָה רוּחַ״ (ירמיהו ב:כד):\",1,0],[2,136,119,134,\"פְּדֵנִי מֵעֹשֶׁק אָדָם. מִיֵּצֶר הָרָע הָעוֹשֵׁק אֶת הַבְּרִיּוֹת. בְּפֵרוּשִׁים אֲחֵרִים מָצָאתִי פְּדֵנִי מֵעֹשֶׁק אָדָם, פְּדֵנִי מֵעוֹשְׁקוֹ שֶׁל אָדָם:\",1,0],[2,136,119,139,\"צִמְּתַתְנִי קִנְאָתִי. הַקִּנְאָה שֶׁאֲנִי מְקַנֵּא לְשִׁמְךָ עַל הַשּׁוֹכְחֵי דְבָרֶיךָ, הִיא צוֹמְתָה אוֹתִי וּמַקְנֶטֶת אוֹתִי בָּהֶם (מצאתי):\",1,0],[2,136,119,141,\"צָעִיר אָנֹכִי וְנִבְזֶה. כְּמָה דְאַתְּ אָמַר ״וְדָוִד הוּא הַקָּטָן״ (שמואל א יז:יד), נִבְזֶה אֲנִי לְהַקְטִין עַצְמִי אֵצֶל עוֹסְקֵי תוֹרָה לְהִתְלַמֵּד, כִּי פִּקֻּדֶיךָ לֹא שָׁכָחְתִּי מִלְּסַלְסֵל וּמִלְּפַלְפֵּל בָּהֶם בְּצִדְקָתְךָ שֶׁבְּתוֹכָן צֶדֶק וֶאֱמֶת עוֹלָמִית, וְאַף כִּי מְצָאוּנִי צָרוֹת הָיוּ הֵם עִסְקִי, וּלְעוֹלָם הֲבִינֵנִי צִדְקָם וְאֶחְיֶה בָהֶם ״כִּי הִיא חַיֶּיךָ וְגוֹמֵר״ (דברים ל:כ):\",1,0],[2,136,119,146,\"(הַסִּימָן שֶׁל עֵדֹתֶיךָ דָּמָה בֶּן פֶּרֶ״ץ, הַוָּי״ו חוֹלָם, אֲבָל מִשְּׁאָר עֵדֹתֶיךָ הַדָּלֶ״ת חוֹלָם):\",1,0],[2,136,119,148,\"אַשְׁמֻרוֹת. חֲצִי הַלַּיְלָה, שְׁתֵּי אַשְׁמוּרוֹת (איכה רבה ב:כב); וּלְדִבְרֵי הָאוֹמֵר (איכה רבה ב:כב) ׳שָׁלֹשׁ מִשְׁמָרוֹת הֲוֵי לַיְלָה׳, הָיָה דָּוִד עוֹמֵד מִמִּטָּתוֹ בִּשְׁלִישׁ הַלַּיְלָה הָרִאשׁוֹנָה וְעוֹסֵק בַּתּוֹרָה עַד חֲצוֹת, כְּמוֹ שֶׁנֶּאֱמַר: לָשִׂיחַ בְּאִמְרָתֶךָ, וּמֵחֲצוֹת וּלְהַלָּן עוֹסֵק בְּשִׁירוֹת וְתוּשְׁבָּחוֹת, כְּמוֹ שֶׁנֶּאֱמַר חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ:\",1,0],[2,136,119,150,\"קָרְבוּ רוֹדְפֵי זִמָּה. עֲצַת חַטָּאִים הוֹלְכִים בַּעֲצַת חַטָּאֵיהֶם, וּמִתְרַחֲקִים מִתּוֹרָתְךָ לִקָּרֵב אֶל עֲצַת רָעָתָם:\",1,0],[2,136,119,151,\"קָרוֹב אַתָּה. לָרְחוֹקִים הַלָּלוּ הַמִּתְרַחֲקִים מִתּוֹרָתֶךָ, אִם יָשׁוּבוּ מִדַּרְכָּם:\",1,0],[2,136,119,152,\"קֶדֶם יָדַעְתִּי מֵעֵדֹתֶיךָ. קוֹדֶם הֱיוֹת הַדָּבָר יְדַעְתִּיו מִתּוֹךְ עֵדֹתֶיךָ: קֹדֶם יָרְשׁוּ אֶת הָאָרֶץ צִוִּיתָ לָהֶם עַל הַבִּכּוּרִים וּתְרוּמוֹת וּמַעַשְׂרוֹת, וְקֹדֶם הֲנִיחוֹת לָהֶם מֵאוֹיְבֵיהֶם צִוִּיתָ לָהֶם ״וְהָיָה בְּהָנִיחַ ה׳ אֱלֹהֶיךָ לְךָ וְגוֹ׳״ (דברים כה:יט) לְהַעֲמִיד מֶלֶךְ וּלְהַכְרִית עֲמָלֵק וְלִבְנוֹת בֵּית הַבְּחִירָה (סנהדרין כ:):\",1,0],[2,136,119,152,\"כִּי לְעוֹלָם יְסַדְתָּם. כִּי עַל כָּל הַדְּבָרִים הָעֲתִידִים לִהְיוֹת לְסוֹף הָעוֹלָם יִסַּדְתָּ עֵדוֹתֶיךָ:\",2,0],[2,136,119,160,\"רֹאשׁ דְּבָרְךָ אֱמֶת. סוֹף דְּבָרְךָ הוֹכִיחַ עַל הָרֹאשׁ שֶׁהוּא אֱמֶת, שֶׁכְּשֶׁשָּׁמְעוּ הָאֻמּוֹת ״אָנֹכִי״ וְ״לֹא יִהְיֶה לְךָ״ וְ״לֹא תִשָּׂא״ (שמות כ:ב-ז) אָמְרוּ: הַכֹּל לַהֲנָאָתוֹ וְלִכְבוֹדוֹ. כֵּיוָן שֶׁשָּׁמְעוּ ״כַּבֵּד״, ״לֹא תִרְצַח״, ״לֹא תִנְאָף״ (שמות כ:יב-יג), הוֹדוּ עַל רֹאשׁ דְּבָרְךָ שֶׁהוּא אֱמֶת (קידושין לא.):\",1,0],[2,136,119,162,\"שָׂשׂ אָנֹכִי עַל אִמְרָתֶךָ. עַל הַבְטָחָתְךָ שֶׁהִבְטַחְתַּנִי. דָּבָר אַחֵר: עַל אַחַת מֵאִמְרוֹתֶיךָ הַסְּתוּמוֹת, כְּשֶׁאֲנִי מֵבִין בָּהּ. וְרַבּוֹתֵינוּ דָּרְשׁוּ עַל הַמִּילָה (מנחות מג:): שֶׁהָיָה דָוִד בְּבֵית הַמֶּרְחָץ וְרָאָה עַצְמוֹ בְּלֹא צִיצִית וּבְלֹא תְּפִילִּין וּבְלֹא תּוֹרָה, אָמַר: אוֹי לִי שֶׁאֲנִי עָרוֹם מִכָּל מִצְווֹת. כֵּיוָן שֶׁנִּסְתַּכֵּל בַּמִּילָה שָׂמַח, וְאָמַר בְּצֵאתוֹ (מִבֵּית הַמֶּרְחָץ): שָׂשׂ אָנֹכִי עַל אִמְרָתֶךָ, הַמִּילָה שֶׁמִּתְּחִלָּה נִתְּנָה בְּמַאֲמָר וְלֹא בְדִבּוּר, שֶׁנֶּאֱמַר (בראשית יז:ט): ״וַיֹּאמֶר אֱלֹהִים אֶל אַבְרָהָם וְאַתָּה אֶת בְּרִיתִי תִשְׁמֹר״:\",1,0],[2,136,119,164,\"שֶׁבַע בַּיּוֹם. שַׁחֲרִית שְׁתַּיִם לִפְנֵי קְרִיאַת שְׁמַע וְאַחַת לְאַחֲרֶיהָ, וּבָעֶרֶב שְׁתַּיִם לְפָנֶיהָ וּשְׁתַּיִם לְאַחֲרֶיהָ (ברכות יא:):\",1,0],[2,136,119,164,\"עַל מִשְׁפְּטֵי צִדְקֶךָ. עַל קְרִיאַת שְׁמַע שֶׁהִיא דִּבְרֵי תוֹרָה (ברכות כא.):\",2,0],[2,136,119,166,\"שִׂבַּרְתִּי. הוֹחַלְתִּי:\",1,0],[2,136,119,168,\"כָּל דְּרָכַי נֶגְדֶּךָ. אַתָּה יוֹדֵעַ כָּל דְּרָכַי:\",1,0],[2,136,119,169,\"כִּדְבָרְךָ הֲבִינֵנִי. דִּבְרֵי תוֹרָתְךָ כְּהִלְכָתָן וְכַהֲוָיָתָן:\",1,0],[2,136,119,171,\"תַּבַּעְנָה. תְּדַבֵּרְנָה:\",1,0],[2,136,119,172,\"תַּעַן לְשׁוֹנִי. כָּל עֲנִיָּה לְשׁוֹן קוֹל רָם הוּא, וְאָב לְכֻלָּם ״וְעָנוּ הַלְוִיִּם וְאָמְרוּ״ (דברים כז:יד):\",1,0],[2,136,120,1,\"שִׁיר הַמַּעֲלוֹת. שֶׁיֹּאמְרוּ הַלְוִיִּם אוֹתוֹ עַל חֲמֵשׁ עֶשְׂרֵה מַעֲלוֹת הַיּוֹרְדוֹת מֵעֶזְרַת יִשְׂרָאֵל עַד עֶזְרַת נָשִׁים, וְיֵשׁ כָּאן חֲמִשָּׁה עָשָׂר מִזְמוֹרִים שֶׁל שִׁיר הַמַּעֲלוֹת (סוכה ה:ד). וְרַבּוֹתֵינוּ אָמְרוּ שֶׁיִּסְּדָן דָּוִד לְהַעֲלוֹת אֶת הַתְּהוֹם, כְּמוֹ שֶׁמְּפֹרָשׁ בְּמַסֶּכֶת סֻכָּה (סוכה נג.). וּלְפִי אַגָּדָה פִּתְרוֹנוֹ שִׁיר לְמֵאָה עוֹלוֹת (ירושלמי סנהדרין י:ב):\",1,0],[2,136,120,2,\"מִשְּׂפַת שֶׁקֶר. זַרְעוֹ שֶׁל הָרָשָׁע, שֶׁצָּדִין אֶת הַבְּרִיּוֹת בְּפִיהֶם בַּעֲלִילוֹת רֶשַׁע:\",1,0],[2,136,120,3,\"מַה יִּתֵּן לְךָ. הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,136,120,3,\"וּמַה יּוֹסִיף לְךָ. שְׁמִירָה וּמְחִיצּוֹת, הֲרֵי אַתְּ נְתוּנָה לִפְנִים מִשְּׁתֵּי מְחִיצּוֹת (ערכין טו:):\",2,0],[2,136,120,4,\"חִצֵּי גִבּוֹר שְׁנוּנִים. וַהֲרֵי אַתְּ הוֹרֶגֶת בְּמָקוֹם רָחוֹק כְּחֵץ:\",1,0],[2,136,120,4,\"עִם גַּחֲלֵי רְתָמִים. כָּל הַגֶּחָלִים, כָּבוּ מִבַּחוּץ – כָּבוּ מִבִּפְנִים, וְאֵלּוּ כָּבוּ מִבַּחוּץ וְלֹא מִבִּפְנִים (בראשית רבה צח:יט). דָּבָר אַחֵר (ערכין טו:): מַה יִּתֵּן לְךָ. מַה סוֹפוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לִגְזֹר עָלֶיךָ? חִצֵּי גִבּוֹרִים עִם גַּחֲלֵי רְתָמִים. חִצִּים מִלְמַעְלָה וְגֵיהִנֹּם מִלְּמַטָּה:\",2,0],[2,136,120,5,\"אוֹיָה לִי. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל כִּי כְּבָר לָקִיתִי בְּגָלֻיּוֹת רַבִּים, הֲרֵי גַּרְתִּי מֶשֶׁךְ עִם בְּנֵי יֶפֶת (בראשית י:ב) בְּמַלְכוּת פָּרַס וְיָוָן וּמֶשֶׁךְ (יומא י.):\",1,0],[2,136,120,7,\"אֲנִי שָׁלוֹם. עִמָּהֶם:\",1,0],[2,136,120,7,\"וְכִי אֲדַבֵּר. עֲלֵיהֶם שָׁלוֹם, הֵמָּה בָּאִים לְהִלָּחֵם בִּי:\",2,0],[2,136,121,1,\"(שִׁיר לַמַּעֲלוֹת. הַפְּשָׁט כְּשֶׁהָיוּ הַלְוִיִּם מַתְחִילִין לַעֲלוֹת בַּמַּעֲלוֹת אָמְרוּ שִׁיר זֶה, אַף עַל פִּי שֶׁזֶּה הַשִּׁיר לֹא נִכְתַּב בָּרִאשׁוֹנָה אֵין מֻקְדָּם וּמְאֻחָר (ס״א מצאתי)):\",1,0],[2,136,121,1,\"שִׁיר לַמַּעֲלוֹת. רֶמֶז בְּמִּזְמוֹר שֵׁנִי לַמַּעֲלוֹת הָעוֹלוֹת לַצַּדִּיקִים לֶעָתִיד לָבֹא מִתַּחַת עֵץ הַחַיִּים לְכִסֵּא הַכָּבוֹד, דְּתַנְיָא בְּסִפְרֵי (ספרי דברים פיסקא מז): שִׁיר הַמַּעֲלוֹת אֵין כָּתוּב כָּאן אֶלָּא שִׁיר לַמַּעֲלוֹת – שִׁיר לְמִי שֶׁעָתִיד לַעֲשׂוֹת מַעֲלוֹת לַצַּדִּיקִים לֶעָתִיד לָבֹא. וְזֶהוּ שֶׁיִּסֵּד הַקָּלִיר (בסילוק דיוצר של יום ב׳ דסוכות שיסד ר׳ אליעזר הקליר שהוא בנו של רשב״י בחגיגה פ׳ אין דורשין ע״ש): ״וּמִתַּחְתֶּיהָ שְׁלֹשִׁים מַעֲלוֹת, זוֹ לְמַעְלָה מִזּוֹ עַד כִּסֵּא הַכָּבוֹד טָסוֹת וְעוֹלוֹת, בְּשִׂיחַ נְעִימוֹת שִׁיר הַמַּעֲלוֹת״:\",2,0],[2,136,122,1,\"שָׂמַחְתִּי בְּאוֹמְרִים לִי. שָׁמַעְתִּי בְּנֵי אָדָם שֶׁאוֹמְרִים: מָתַי יָמוּת אוֹתוֹ זָקֵן וְיִמְלוֹךְ שְׁלֹמֹה בְּנוֹ וְיִבְנֶה בֵּית הַמִּקְדָּשׁ וְנַעֲלֶה לָרֶגֶל? וַאֲנִי שָׂמֵחַ (מכות י.):\",1,0],[2,136,122,2,\"עוֹמְדוֹת הָיוּ רַגְלֵינוּ. בַּמִּלְחָמָה בְּכָל מָקוֹם בִּשְׁבִיל שְׁעָרַיִךְ יְרוּשָׁלָ͏ִם, שֶׁעוֹסְקִין בָּהֶן בַּתּוֹרָה (מכות י.):\",1,0],[2,136,122,3,\"יְרוּשָׁלַ͏ִם הַבְּנוּיָה. כְּשֶׁיִּבְנֶה שְׁלֹמֹה בְּנִי בֵּית הַמִּקְדָּשׁ בְּתוֹכָהּ, תְּהֵא בְּנוּיָה בִּשְׁכִינָה וּמִקְדָּשׁ וְאָרוֹן וּמִזְבֵּחַ:\",1,0],[2,136,122,3,\"כְּעִיר שֶׁחֻבְּרָה לָּהּ. כְּשִׁילֹה, שֶׁדִּמָּה הַכָּתוּב זוֹ לָזוֹ, שֶׁנֶּאֱמַר (דברים יב:ט) ״אֶל הַמְּנוּחָה וְאֶל הַנַּחֲלָה״: מְנוּחָה זוֹ שִׁילֹה, נַחֲלָה זוֹ יְרוּשָׁלַיִם (ספרי דברים סו). וְרַבּוֹתֵינוּ אָמְרוּ (תענית ה.): יֵשׁ יְרוּשָׁלַיִם הַבְּנוּיָה בַּשָּׁמַיִם, וַעֲתִידָה יְרוּשָׁלַיִם שֶׁל מַטָּה לִהְיוֹת כְּמוֹתָהּ:\",2,0],[2,136,122,4,\"שֶׁשָּׁם עָלוּ שְׁבָטִים. אֲשֶׁר שָׁם, בְּשִׁילֹה, עָלוּ שְׁבָטִים כְּשֶׁעָלוּ מִמִּצְרַיִם, וְנִקְבַּע הַמִּשְׁכָּן בְּתוֹכָהּ:\",1,0],[2,136,122,4,\"שִׁבְטֵי יָהּ. שֶׁהוּא עֵדוּת לְיִשְׂרָאֵל. לְפִי שֶׁהָיוּ הָאֻמּוֹת מֵלִיזִין אַחֲרֵיהֶם כְּשֶׁיָּצְאוּ מִמִּצְרַיִם וְאוֹמְרִים עֲלֵיהֶם שֶׁהֵם מַמְזֵרִים, אִם בְּגוּפָם הָיוּ שׁוֹלְטִין הַמִּצְרִים בִּנְשׁוֹתֵיהֶם לֹא כָּל שֶׁכֵּן. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: אֲנִי מֵעִיד עֲלֵיהֶם שֶׁהֵם בְּנֵי אֲבוֹתֵיהֶם. הֵטִיל שְׁמוֹ עֲלֵיהֶם: הָרְאוּבֵנִי הַשִּׁמְעוֹנִי (במדבר כו:ז,יד), הוֹסִיף עֲלֵיהֶם אוֹתִיּוֹת הַשֵּׁם אַחַת מִכָּאן וְאַחַת מִכָּאן. נִמְצָא הַשֵּׁם הַזֶּה יָהּ עֵדוּת לְיִשְׂרָאֵל:\",2,0],[2,136,122,5,\"כִּי שָׁמָּה יָשְׁבוּ וְגוֹ׳. כִּי גַם בִּירוּשָׁלַיִם תִּשְׁרֶה הַשְּׁכִינָה, וְיָשְׁבוּ שָׁם כִּסְאוֹת לִשְׁפֹּט בָּהֶם אֶת הָאוּמּוֹת (תנחומא, קדושים א), וְכִּסְאוֹת מְלוּכָה לְבֵית דָּוִד:\",1,0],[2,136,122,6,\"שַׁאֲלוּ שְׁלוֹם יְרוּשָׁלִָם. וְאִמְרוּ לָהּ יִשְׁלָיוּ אֹהֲבָיִךְ, וִיהִי שָׁלוֹם בְּחֵילֵךְ:\",1,0],[2,136,122,8,\"לְמַעַן. יִשְׂרָאֵל אַחַי וְרֵעָי:\",1,0],[2,136,122,8,\"אֲדַבְּרָה נָּא. אֲנִי, דָּוִד הַמֶּלֶךְ, שָׁלוֹם בָּךְ:\",2,0],[2,136,123,1,\"שִׁיר וְגוֹ׳ הַיֹּשְׁבִי. יוֹ״ד יְתֵירָה:\",1,0],[2,136,123,4,\"הַלַּעַג הַשַּׁאֲנַנִּים. לַעַג הַגּוֹיִם הַשַּׁאֲנַנִּים שָׂבַעְנוּ:\",1,0],[2,136,123,4,\"הַבּוּז. שֶׁבָּזוּ אֶת גֵּיא הַיּוֹנִים, הִיא יְרוּשָׁלַיִם:\",2,0],[2,136,123,4,\"לְגֵאִיוֹנִים. כְּתִיב חַד וְקָרִינָן תְּרֵין:\",3,0],[2,136,124,3,\"בַּחֲרוֹת אַפָּם בָּנוּ. כְּשֶׁחָרָה אַפָּם בָּנוּ. בַּחֲרוֹת. כְּמוֹ ״בַּעֲשׂוֹת״ (יחזקאל כג:כא):\",1,0],[2,136,124,4,\"נַחְלָה. לְשׁוֹן חוֹלִי:\",1,0],[2,136,124,7,\"נַפְשֵׁנוּ [כְּצִפּוֹר] נִמְלְטָה. מֵהֶם כְּצִפּוֹר אֲשֶׁר נִמְלְטָה מִפַּח יוֹקְשִׁים:\",1,0],[2,136,125,1,\"שִׁיר הַמַּעֲלוֹת הַבֹּטְחִים בַּה׳. לֹא יִמּוֹטוּ כְּהַר צִיּוֹן אֲשֶׁר לֹא יִמּוֹט, כִּי כַּאֲשֶׁר יְרוּשָׁלַיִם הָרִים סָבִיב לָהּ, כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא סָבִיב לְעַמּוֹ:\",1,0],[2,136,125,3,\"כִּי לֹא יָנוּחַ שֵׁבֶט הָרֶשַׁע עַל גּוֹרַל הַצַּדִּיקִים. (כִּי לֹא יִתֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת מֶמְשֶׁלֶת הָרְשָׁעִים לָנוּחַ עַל הַצַּדִּיקִים), לְמַעַן כִּי הַצַּדִּיקִים נִזְהָרִין מִלִּשְׁלֹחַ יְדֵיהֶם בְּעַוְלָה:\",1,0],[2,136,125,5,\"וְהַמַּטִּים עֲקַלְקַלּוֹתָם. עַל הַבְּרִיּוֹת לִמְצוֹא עֲלִילוֹת רֶשַׁע, יוֹלִיכֵם ה׳ אֶת פֹּעֲלֵי אָוֶן:\",1,0],[2,136,126,1,\"בְּשׁוּב ה׳ אֶת שִׁיבַת צִיּוֹן. מִגָּלוּת בָּבֶל הָיִינוּ כְּחוֹלְמִים:\",1,0],[2,136,126,4,\"כַּאֲפִיקִים בַּנֶּגֶב. כַּאֲפִיקֵי מַיִם בְּאֶרֶץ יְבֵשָׁה שֶׁמְּלַחְלְחִין אוֹתָהּ, כָּךְ נִהְיֶה מַרְטִיבִין בְּשׁוּבְךָ אֶת שְׁבוּתֵינוּ אֲשֶׁר הַזּוֹרְעִים בָּהּ, בְּאֶרֶץ צִיָּה, בְּדִמְעָה – דּוֹאֲגִים, שֶׁסְּבוּרִים שֶׁמָּא לֹא תִצְמַח, בְּרִנָּה קוֹצְרִין עַל יְדֵי אֲפִיקֵי הַמַּיִם כְּשֶׁהֵם מְשֻׁלָּחִין בָּהּ:\",1,0],[2,136,126,6,\"הָלוֹךְ יֵלֵךְ וּבָכֹה וְגוֹ׳. כָּךְ יִשְׂרָאֵל זוֹרְעִין לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא צְדָקָה בְּדִמְעָה בַּגָּלוּת, וּבְרִנָּה יִקְצֹרוּ כְּשֶׁתִּשְׁלַם מַשְׂכֻּרְתָּם לֶעָתִיד:\",1,0],[2,136,127,1,\"שִׁיר הַמַּעֲלוֹת לִשְׁלֹמֹה. שִׁיר זֶה אָמַר דָּוִד עַל שְׁלֹמֹה בְּנוֹ שֶׁצָּפָה בְּרוּחַ הַקֹּדֶשׁ שֶׁעָתִיד לִבְנוֹת בֵּית הַמִּקְדָּשׁ וּבוֹ בַיּוֹם יִשָּׂא שְׁלֹמֹה אֶת בַּת פַּרְעֹה, וְעַל זֶה נֶאֱמַר (ירמיהו לב:לא) ״כִּי עַל אַפִּי וְעַל חֲמָתִי הָיְתָה לִּי הָעִיר הַזֹּאת לְמִן הַיּוֹם אֲשֶׁר בָּנוּ אוֹתָהּ״. לְכָךְ אָמַר הַמִּזְמוֹר הַזֶּה: לָמָּה לְךָ בְּנִי לִבְנוֹת בַּיִת וְלָסוּר מֵאַחֲרֵי הַמָּקוֹם מֵאַחַר שֶׁאֵינוֹ חָפֵץ בָּהּ, לַשָּׁוְא עָמְלוּ בוֹנָיו בּוֹ:\",1,0],[2,136,127,1,\"שָׁוְא שָׁקַד שׁוֹמֵר. עַל חִנָּם צוֹפֶה בָּהּ הַשּׁוֹמֵר:\",2,0],[2,136,127,2,\"שָׁוְא לָכֶם. בַּעֲלֵי הָאוּמָּנִיּוֹת הַמַּשְׁכִּימִים וּמְאַחֲרִים לִמְלַאכְתָּם וּמִתְפַּרְנְסִים בְּעִצָּבוֹן וּבִיגִיעָה בְּלֶחֶם הָעֲצָבִים שֶׁל טֹרַח:\",1,0],[2,136,127,2,\"כֵּן יִתֵּן. הַקָּדוֹשׁ בָּרוּךְ הוּא פַּרְנָסָה לְמִי שֶׁמְּנַדֵּד שֵׁנָה מֵעֵינָיו בִּשְׁבִיל לַעֲסֹק בַּתּוֹרָה:\",2,0],[2,136,127,2,\"לִידִידוֹ שֵׁנָא. לִמְנַדֵּד מֵעֵינָיו שֵׁינָה (כתובות סב.):\",3,0],[2,136,127,3,\"הִנֵּה נַחֲלַת ה׳. לְאוֹתוֹ הָאִישׁ:\",1,0],[2,136,127,3,\"בָּנִים. אֵלּוּ הַתַּלְמִידִים שֶׁהוּא מַעֲמִיד, שֶׁהֵם לוֹ כְּבָנִים (ספרי דברים לד):\",2,0],[2,136,127,3,\"שָׂכָר פְּרִי הַבָּטֶן. שְׂכַר פְּרִי הַתּוֹרָה שֶׁבַּלֵּב, שֶׁנֶּאֱמַר: ״כִּי נָעִים כִּי תִשְׁמְרֵם בְּבִטְנֶךָ״ (משלי כב:יח):\",3,0],[2,136,127,4,\"כְּחִצִּים בְּיַד גִּבּוֹר. לְהִלָּחֵם בָּם אֶת אוֹיְבָיו:\",1,0],[2,136,127,4,\"כֵּן בְּנֵי הַנְּעוּרִים. הַתַּלְמִידִים שֶׁאָדָם מַעֲמִיד מִנְּעוּרָיו:\",2,0],[2,136,127,5,\"אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ. מֵאוֹתָם חִצִּים, אַשְׁפָּה תִּיק הַחִצִּים שֶׁקּוֹרִין קויכרי״ן בְּלַעַ״ז:\",1,0],[2,136,127,5,\"לֹא יֵבֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר. תַּלְמִידֵי חֲכָמִים, שֶׁמְּנַצְּחִין זֶה אֶת זֶה בַּהֲלָכָה וְנִרְאִים כְּאוֹיְבִים זֶה לָזֶה (קדושין ל.) (תוספות):\",2,0],[2,136,128,1,\"שִׁיר הַמַּעֲלוֹת אַשְׁרֵי כָּל יְרֵא ה׳. כָּל אֵלּוּ תּוֹכָחוֹת וּמוּסָרִים, לְפִי שֶׁכָּתוּב ״אַשְׁרֵי הָאִישׁ״ (תהלים א:א), ״אַשְׁרֵי אִישׁ״ (תהלים קיב:א), לְכָךְ נֶאֱמַר כָּאן כָּל, לְרַבּוֹת אִשָּׁה:\",1,0],[2,136,128,2,\"יְגִיעַ כַּפֶּיךָ. הַנֶּהֱנֶה מִיגִיעַ כַּפּוֹ נוֹחֵל שְׁנֵי עוֹלָמוֹת (ברכות ח.):\",1,0],[2,136,128,3,\"כְּגֶפֶן פֹּרִיָּה. בָּנֶיהָ מְרֻבִּין:\",1,0],[2,136,128,3,\"בְּיַרְכְּתֵי בֵיתֶךָ. לְפִי שֶׁדֶּרֶךְ תַּשְׁמִישׁ לִהְיוֹת בְּצִנְעָה. דָּבָר אַחֵר בְּיַרְכְּתֵי. אִם אִשְׁתְּךָ נִדָּה תְּשִׂימֶנָּה בְּיַרְכְּתֵי בֵיתֶךָ שֶׁלֹּא תִּתְרַגֵּל אֶצְלָהּ:\",2,0],[2,136,128,3,\"בָּנֶיךָ כִּשְׁתִילֵי זֵיתִים. מַה זֵּיתִים אֵין לָהֶם הַרְכָּבָה, כָּךְ אֵין בְּבָנֶיךָ פְּסוּל:\",3,0],[2,136,128,5,\"מִצִּיּוֹן. שֶׁהוּא שַׁעַר הַשָּׁמַיִם (בראשית כח:יז):\",1,0],[2,136,128,5,\"בְּטוּב יְרוּשָׁלִָם. ״וְשָׂמַחְתָּ בְכָל הַטּוֹב״ (דברים כו:יא):\",2,0],[2,136,128,6,\"וּרְאֵה בָנִים לְבָנֶיךָ. וְלֹא יָבוֹאוּ לִקְטָטָה עֲבוּר חֲלִיצָה, וְאָז שָׁלוֹם עַל יִשְׂרָאֵל. תּוֹסְפוֹת:\",1,0],[2,136,128,6,\"בָּנִים לְבָנֶיךָ. יִירְשׁוּ נַחֲלָה, וְאֵין אִשָּׁה זְקוּקָה לְיָבָם, אָז שָׁלוֹם בָּעוֹלָם:\",2,0],[2,136,129,3,\"חֹרְשִׁים הֶאֱרִיכוּ לְמַעֲנִיתָם. הוּא תֶּלֶם הַמַּחֲרֵשָׁה, ״כַּבַּחֲצִי מַעֲנָה צֶמֶד שָׂדֶה״ (שמואל א יד:יד):\",1,0],[2,136,129,6,\"שֶׁקַּדְמַת שָׁלַף יָבֵשׁ. שֶׁקּוֹדֶם שֶׁיִּשְׁלְפוּהוּ וְיִתְלְשׁוּהוּ מִמְּקוֹמוֹ הוּא יָבֵשׁ:\",1,0],[2,136,129,7,\"וְחִצְנוֹ. כְּמוֹ ״וְהֵבִיאוּ בָנַיִךְ בְּחֹצֶן״ (ישעיהו מט:כב), אֵיישִׁילָ״א בְּלַעַ״ז, וְכֵן ״גַּם חָצְנִי נִעַרְתִּי״ (נחמיה ה:יג):\",1,0],[2,136,130,4,\"כִּי עִמְּךָ הַסְּלִיחָה. לֹא נָתַתָּ רְשׁוּת לְשָׁלִיחַ לִסְלֹחַ, כְּמוֹ שֶׁנֶּאֱמַר ״כִּי לֹא יִשָּׂא לְפִשְׁעֲכֶם״ (שמות כג:כא):\",1,0],[2,136,130,4,\"לְמַעַן תִּוָּרֵא. עַל זֹאת, שֶׁלֹּא יְהֵא אָדָם בָּטוּחַ עַל סְלִיחַת אַחֵר:\",2,0],[2,136,130,5,\"קִוִּיתִי ה׳ קִוְּתָה נַפְשִׁי. קִוּוּי אַחַר קִוּוּי, כְּעֵין ״קַוֵּה אֶל ה׳ חֲזַק וְיַאֲמֵץ לִבֶּךָ וְקַוֵּה״ (תהלים כז:יד), כְּעֵין מִשֹּׁמְרִים לַבֹּקֶר שֹׁמְרִים לַבֹּקֶר:\",1,0],[2,136,130,6,\"נַפְשִׁי לַה׳ מִשֹּׁמְרִים לַבֹּקֶר. הֲרֵינִי מִן הַמְצַפִּים לַגְּאֻלָּה:\",1,0],[2,136,130,6,\"שׁוֹמְרִים לַבֹּקֶר. מְצַפִּין וְחוֹזְרִין וּמְצַפִּין, קֵץ אַחַר קֵץ (מצאתי):\",2,0],[2,136,131,1,\"ה׳ לֹא גָבַהּ לִבִּי וְגוֹ׳. לֹא נָהַגְתִּי שְׂרָרָה, לֹא עָשִׂיתִי גְדוֹלוֹת: תַּעֲנוּגוֹת בִּנְיָנִים וּנְטִיעוֹת כְּעֵין שֶׁעָשָׂה בְנִי. הִנְנִי עָלֶיךָ כְּמִי שֶׁאֵין לוֹ יָדַיִם וְרַגְלַיִם, כְּגֹלֶם מֻטָּל לְנֶגְדְּךָ (ס״א אינו):\",1,0],[2,136,131,2,\"שִׁוִּיתִי וְדוֹמַמְתִּי. עָלֶיךָ נַפְשִׁי כְּגָמֻל, שֶׁהוּא נָתוּן עֲלֵי אִמּוֹ; גָּמֻל. יוֹנֵק שָׁדַיִם:\",1,0],[2,136,131,2,\"כְּגָמוּל עֲלֵי נַפְשִׁי. נַפְשִׁי בְּקִרְבִּי לְנֶגְדְּךָ כְּיוֹנֵק שְׁדֵי אִמּוֹ:\",2,0],[2,136,132,1,\"שִׁיר הַמַּעֲלוֹת זְכוֹר ה׳ לְדָוִד אֵת כָּל עֻנּוֹתוֹ. עִנּוּי נַפְשׁוֹ אֲשֶׁר טָרַח וְעָמַל לִמְצֹא לְךָ מָקוֹם (תנחומא, נשא יג):\",1,0],[2,136,132,5,\"עַד אֶמְצָא מָקוֹם. עַד שֶׁיִּוָּדַע הֵיכָן יִהְיֶה מְקוֹם מִקְדָּשׁ (מצאתי):\",1,0],[2,136,132,6,\"שְׁמַעֲנוּהָ. הַבְּשׂוֹרָה:\",1,0],[2,136,132,6,\"בְּאֶפְרָתָה. בְּמָקוֹם הֶחָשׁוּב וְהַמְעֻלֶּה, כְּמוֹ (שמואל א א:א) ״בֶּן תֹּחוּ בֶן צוּף אֶפְרָתִי״ – חָשׁוּב, אַבְגִינוֹס. דָּבָר אַחֵר: שְׁמַעֲנוּהָ בְאֶפְרָתָה בְּסֵפֶר יְהוֹשֻׁעַ (יהושע טו) שֶׁבָּא מֵאֶפְרַיִם, בְּכָל הַתְּחוּמִין הוּא אוֹמֵר (יהושע טו:ו-יח) ״וְעָלָה הַגְּבוּל״ ״וְתָאַר הַגְּבוּל״, וְכָאן הוּא אוֹמֵר (יהושע טו:ח) ״וְעָלָה הַגְּבוּל אֶל כֶּתֶף הַיְבוּסִי יְרוּשָׁלִָם״. נִמְצֵאת יְרוּשָׁלִַם גָּבוֹהַּ מִכָּל הָאֲרָצוֹת, וְהוּא רָאוּי לְבֵית הַמִּקְדָּשׁ, שֶׁנֶּאֱמַר (דברים יז:ח) ״וְקַמְתָּ וְעָלִיתָ אֶל הַמָּקוֹם וְגוֹ׳״, מְלַמֵּד שֶׁבֵּית הַמִּקְדָּשׁ גָּבוֹהַּ מִכָּל אֶרֶץ יִשְׂרָאֵל. כָּךְ נִדְרַשׁ בִּשְׁחִיטַת קָדָשִׁים (זבחים נד:):\",2,0],[2,136,132,6,\"מְצָאנוּהָ בִּשְׂדֵי יָעַר. בִּגְבוּל בִּנְיָמִין שֶׁנִּמְשַׁל לְחַיַּת הַיַּעַר, שֶׁנֶּאֱמַר: ״בִּנְיָמִין זְאֵב יִטְרָף״ (בראשית מט:כז):\",3,0],[2,136,132,7,\"נָבוֹאָה. שָׁמָּה לְמִשְׁכְּנוֹתָיו:\",1,0],[2,136,132,10,\"אַל תָּשֵׁב פְּנֵי מְשִׁיחֶךָ. שְׁלֹמֹה, בְּבוֹאוֹ לְהַכְנִיס שָׁם אֶת הָאָרוֹן (שבת ל.):\",1,0],[2,136,132,12,\"וְעֵדוֹתִי זוֹ אֲלַמְּדֵם. זוֹ אֲשֶׁר אֲלַמְּדֵם:\",1,0],[2,136,132,15,\"צֵידָה. מְזוֹנָהּ:\",1,0],[2,136,132,18,\"יָצִיץ. יָאִיר, כְּמוֹ ״וְנֹצְצִים כְּעֵין נְחֹשֶׁת״ (יחזקאל א:ז):\",1,0],[2,136,133,1,\"שִׁיר וְגוֹ׳ הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. כְּשֶׁיֵּשֵׁב הַקָּדוֹשׁ בָּרוּךְ הוּא בְּבֵית הַבְּחִירָה עִם יִשְׂרָאֵל הַקְּרוּיִין אַחִים וְרֵעִים (שיר השירים ה:א), וְיִהְיֶה גַּם הוּא יַחַד עִמָּהֶם:\",1,0],[2,136,133,2,\"כַּשֶּׁמֶן הַטּוֹב. שֶׁנִּמְשַׁח בּוֹ אַהֲרֹן הַכֹּהֵן:\",1,0],[2,136,133,2,\"שֶׁיּוֹרֵד. מֵרֹאשׁוֹ אֶל זְקָנוֹ אֶל פִּי רֹאשׁ הַכֻּתֹּנֶת שֶׁלּוֹ, שֶׁהַזָּקָן שׁוֹכֵב עַל פִּי הַכֻּתֹּנֶת. כֵּן נָעִים טַל חֶרְמוֹן שֶׁגָּבוֹהַּ עַל הַרְרֵי צִיּוֹן, וְהַטַּל יוֹרֵד מֵחֶרְמוֹן לְהַרְרֵי צִיּוֹן. כְּשֵׁם שֶׁשֶּׁמֶן הַמִּשְׁחָה לִגְדֻלָּה, כָּךְ הַר צִיּוֹן לְתִפְאֶרֶת וּלְכָבוֹד לְיִשְׂרָאֵל. כַּשֶּׁמֶן הַטּוֹב כֵּן טַל חֶרְמוֹן. כָּזֶה כֵּן זֶה, כְּמוֹ ״וְהָיָה כָעָם כַּכֹּהֵן״ (הושע ד:ט). וְרַבּוֹתֵינוּ דָּרְשׁוּ שֶׁבֶת אַחִים, מֹשֶׁה וְאַהֲרֹן לְעִנְיַן מְעִילָה בְּשֶׁמֶן הַמִּשְׁחָה בְּמַסֶּכֶת הוֹרָיוֹת (הוריות יב.) כָּל הַמִּזְמוֹר. אֲבָל יֵשׁ בְּדִבְרֵי תוֹרָה וְקַבָּלָה מָשָׁל וּמְלִיצָה וְדִבְרֵי חֲכָמִים וְחִידוֹתָם, וְעִקַּר שִׁיר הַמַּעֲלוֹת עַל בֵּית הַמִּקְדָּשׁ נֶאֱמַר:\",2,0],[2,136,135,1,\"הַלְלוּיָהּ הַלְלוּ אֶת שֵׁם ה׳ וְגוֹ׳:\",1,0],[2,136,135,7,\"בְּרָקִים לַמָּטָר עָשָׂה. הֵם זַהֲרוּרֵי הָרָקִיעַ הַמַּבְרִיקִים וּמֵאִירִים לִפְנֵי הַמָּטָר, שֶׁקּוֹרִין אשליילד״ש בְּלַעַ״ז:\",1,0],[2,136,135,7,\"מוֹצֵא. לְשׁוֹן מְצִיאָה, כְּלוֹמַר: אוֹצָרוֹת תִּקֵּן לָרוּחַ, וְשָׁם הֵם מְצוּיִין לוֹ לְשָׁלְחָם בְּמִשְׁלַחְתּוֹ:\",2,0],[2,136,135,9,\"בְּתוֹכֵכִי. כְּמוֹ בְּתוֹכֵךְ:\",1,0],[2,136,135,13,\"ה׳ שִׁמְךָ לְעוֹלָם. כִּגְדֻלָּתְךָ וּכְמֶמְשַׁלְתְּךָ אָז כֵּן הוּא גַּם עַתָּה, וְהַיְּכֹלֶת בְּיָדְךָ לָדוּן וְלִנְקֹם נִקְמָתֵנוּ:\",1,0],[2,136,135,14,\"כִּי יָדִין ה׳ עַמּוֹ. יִשְׁפֹּט מִשְׁפָּטָם מֵאוֹיְבֵיהֶם:\",1,0],[2,136,135,14,\"יִתְנֶחָם. יִתְעַשֵּׁת (יִתְעַכֵּב):\",2,0],[2,136,135,17,\"אַף אֵין יֶשׁ רוּחַ בְּפִיהֶם. גַּם רוּחַ אֵין בְּפִיהֶם אֲפִלּוּ כַּבְּהֵמָה זוֹ, כָּל שֶׁכֵּן שֶׁלֹּא יְדַבְּרוּ כְּאָדָם. וּמֵאַחַר שֶׁאֵין בָּהֶם רוּחַ, אֵין צָרִיךְ לְפָרֵשׁ רוּחַ הַחֹטֶם. אַף זֶה פַּתָּח, וְ״אַף לָהֶם וְלֹא יְרִיחוּן״ (תהלים קטו:ו) קָמַץ (ס״א אינו):\",1,0],[2,136,135,20,\"יִרְאֵי ה׳. אֵלּוּ הַגֵּרִים (מדרש תהלים כב:כט) (מצאתי):\",1,0],[2,136,136,4,\"לְעֹשֵׂה נִפְלָאוֹת גְּדוֹלוֹת לְבַדּוֹ. בָּרִאשׁוֹנָה לֹא נִבְרָא מַלְאָךְ כְּשֶׁעֲשָׂאָן לַנִּפְלָאוֹת הַלָּלוּ הַשָּׁמַיִם וְהָאָרֶץ, הַשֶּׁמֶשׁ וְהַיָּרֵחַ:\",1,0],[2,136,136,10,\"לְמַכֵּה מִצְרַיִם בִּבְכוֹרֵיהֶם. בְּכוֹרֵיהֶם לֹא נֶאֱמַר, אֶלָּא בִּבְכוֹרֵיהֶם: עָמְדוּ בְּכוֹרִים וְקִפְּחוּ שׁוֹקָן שֶׁל אֲבִיהֶם הַמְעַכְּבִים בְּיִשְׂרָאֵל כְּשֶׁשָּׁמְעוּ נֶגַע עֲשִׂירִי מִפִּי מֹשֶׁה:\",1,0],[2,136,136,13,\"לִגְזָרִים. שְׁנֵים עָשָׂר קְרָעִים לִשְׁנֵים עָשָׂר שְׁבָטִים:\",1,0],[2,136,136,17,\"מְלָכִים גְּדוֹלִים. כָּאן רָמַז שְׁלֹשִׁים וְאֶחָד מְלָכִים, וְהִשְׁוָה לָהֶם פַּרְעֹה וְחֵילוֹ וּמַכַּת מִצְרַיִם לִמְלָכִים אַדִּירִים קָשִׁים מֵהֶם. שָׁקוּל סִיחוֹן כְּנֶגֶד כֻּלָּם, כָּל אֶחָד לְעַצְמוֹ. וְכֵן פֵּרֵשׁ לְמַעְלָה: ״לְסִיחוֹן מֶלֶךְ הָאֱמֹרִי וּלְעוֹג מֶלֶךְ הַבָּשָׁן וּלְכֹל מַמְלְכוֹת כְּנָעַן״ (תהלים קלה:יא). כֵּן בָּאַגָּדָה:\",1,0],[2,136,136,23,\"שֶׁבְּשִׁפְלֵנוּ זָכַר לָנוּ. בְּמִצְרַיִם זָכַר לָנוּ (שמות ב:כד):\",1,0],[2,136,136,24,\"וַיִּפְרְקֵנוּ. מִתּוֹכָם, וְהִפְלִיא לָנוּ כָּל זֶה:\",1,0],[2,136,136,25,\"נוֹתֵן לֶחֶם. רָמַז כָּאן חֶסֶד (כָּל הַמַּעֲשִׂים):\",1,0],[2,136,136,26,\"הוֹדוּ לְאֵל הַשָּׁמָיִם. הַמֵּכִין בָּהֶם מָזוֹן לְכָל בְּרִיָּה. עֶשְׂרִים וְשִׁשָּׁה ״כִּי לְעוֹלָם חַסְדּוֹ״ נֶאֶמְרוּ בְּמִזְמוֹר זֶה, כְּנֶגֶד עֶשְׂרִים וְשִׁשָּׁה דּוֹרוֹת שֶׁהָיָה הָעוֹלָם בְּלֹא תּוֹרָה וְנִתְקַיֵּם בְּחַסְדּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,136,137,1,\"עַל נַהֲרוֹת בָּבֶל שָׁם יָשַׁבְנוּ. כְּשֶׁיָּרַדְנוּ לַגּוֹלָה, וּשְׁאָלָם נְבוּכַדְנֶצַּר שֶׁיָּשִׁירוּ לוֹ כְּמוֹ שֶׁהָיוּ מְשׁוֹרְרִין עַל הַדּוּכָן (פסיקתא רבתי לא):\",1,0],[2,136,137,2,\"עַל עֲרָבִים. עַרְבֵי נַחַל (ויקרא כג:מ):\",1,0],[2,136,137,3,\"וְתוֹלָלֵינוּ שִׂמְחָה. מִינֵי כְּלֵי זֶמֶר עַל שֵׁם שֶׁהֵם תּוֹלִין (שֶׁתּוֹלִין) אוֹתָם, כָּךְ פֵּרְשׁוּ מְנַחֵם, וְתוֹלָלֵינוּ שִׂמְחָה וְתוֹלָלֵינוּ שֶׁל שִׂמְחָה. וְיֵשׁ לִפְתֹּר תּוֹלָלֵינוּ אוֹיְבֵינוּ שֶׁהֵם מְהוֹלְלִים וּמְשַׁטִּים בָּנוּ לְשׁוֹן ״וּמְהוֹלְלַי בִּי נִשְׁבָּעוּ״ (תהלים קב:ט):\",1,0],[2,136,137,5,\"אִם אֶשְׁכָּחֵךְ יְרוּשָׁלִָם. כְּנֶסֶת יִשְׂרָאֵל אוֹמֶרֶת כֵּן:\",1,0],[2,136,137,6,\"אִם לֹא אַעֲלֶה אֶת יְרוּשָׁלִַם. אֶת זִכְרוֹן אֵבֶל חֻרְבָּנָהּ אַעֲלֶה לְהַזְכִּירוֹ בְּרֹאשׁ כָּל שִׂמְחָתִי (בבא בתרא ס:):\",1,0],[2,136,137,7,\"עָרוּ עָרוּ. לְשׁוֹן חֻרְבָּן, וְכֵן ״חוֹמוֹת בָּבֶל הָרְחָבָה עַרְעֵר תִּתְעַרְעָר״ (ירמיה נא:נח), וְכֵן ״עָרוֹת יְסוֹד״ (חבקוק ג:יג). וְאֵינוֹ נוֹפֵל אֶלָּא עַל דָּבָר שֶׁעוֹקְרִין שָׁרָשָׁיו מֵהָאָרֶץ:\",1,0],[2,136,138,1,\"נֶגֶד אֱלֹהִים אֲזַמְּרֶךָּ. לְעֵינֵי הַשָּׂרִים (מַלְאָכִים):\",1,0],[2,136,138,2,\"כִּי הִגְדַּלְתָּ עַל כָּל שִׁמְךָ אִמְרָתֶךָ. שִׁמְךָ בַּעַל גְּבוּרוֹת (תפילת העמידה) ״קַנּוֹא וְנוֹקֵם״ (נחום א:ב), וְאִמְרַת הַבְטָחַת טוּבְךָ וְחַסְדְּךָ הִגְדַּלְתָּ עַל כָּל שִׁמְךָ, שֶׁאַתָּה מַעֲבִיר לָנוּ עַל מִדּוֹתֶיךָ וְסוֹלֵחַ לָנוּ:\",1,0],[2,136,138,3,\"תַּרְהִיבֵנִי. הִגְדַּלְתַּנִי:\",1,0],[2,136,138,4,\"כִּי שָׁמְעוּ. כְּשֶׁשָּׁמְעוּ אִמְרֵי פִיךָ ״לֹא תִרְצַח לֹא תִנְאָף״ (שמות כ:יג), הוֹדוּ עַל אִמְרֵי פִיךָ עַל ״אָנֹכִי״ וְ״לֹא יִהְיֶה לְךָ״ (שמות כ:ב-ג). כְּדַי הוּא לְהַקְבִּילָם עֹל מַלְכוּתוֹ עֲלֵיהֶם תְּחִלָּה, וְאַחַר כָּךְ יִגְזֹר כָּל גְּזֵרוֹתָיו (קידושין לא.):\",1,0],[2,136,138,6,\"יְיֵדָע. יְיַסֵּר, כְּמוֹ ״וַיּוֹדַע בָּהֶם אֶת אַנְשֵׁי סֻכּוֹת״ (שופטים ח:טז):\",1,0],[2,136,138,8,\"יִגְמֹר בַּעֲדִי. יַסְכִּים עַל יְדֵי בַּקָּשׁוֹתַי:\",1,0],[2,136,138,8,\"מַעֲשֵׂי יָדֶיךָ. בְּבֵית הַבְּחִירָה, שֶׁנֶּאֱמַר בּוֹ ״כּוֹנְנוּ יָדֶיךָ״ (שמות טו:יז):\",2,0],[2,136,139,2,\"בָּנְתָה לְרֵעִי מֵרָחוֹק. בָּנְתָה מֵרָחוֹק לְמָשְׁכֵנִי אֶל רֵעוּתְךָ וְחִבָּתְךָ:\",1,0],[2,136,139,2,\"לְרֵעִי. לְקָרְבֵנִי אֵלֶיךָ:\",2,0],[2,136,139,3,\"אָרְחִי וְרִבְעִי זֵרִיתָ. דַּרְכִּי וְרִבְצִי וְשָׁכְנִי סִבַּבְתָּ מְחִיצָה, שֶׁאֵין לִי לַעֲשׂוֹת דָּבָר בְּלֹא יְדִיעָתְךָ. זֵרִיתָ לְשׁוֹן ״זֵר זָהָב סָבִיב״ (שמות כה:כד), וְכֵן חִבְּרוֹ מְנַחֵם. וְרַבּוֹתֵינוּ דָּרְשׁוּ (נדה לא.) עַל טִפַּת תַּשְׁמִישׁ שֶׁהַוָּלָד נוֹצָר מִן הַבָּרוּר שֶׁבָּהּ, וּפֵירוּשׁוֹ זֵרִיתָ לְשׁוֹן זוֹרֶה הַתְּבוּאָה לִבְרוֹר אֶת הַפְּסוֹלֶת שֶׁבָּהּ:\",1,0],[2,136,139,3,\"הִסְכַּנְתָּה. לָמַדְתָּ:\",2,0],[2,136,139,5,\"אָחוֹר וָקֶדֶם צַרְתָּנִי. פָּנַי וַאֲחוֹרַי:\",1,0],[2,136,139,5,\"כַּפֶּכָה. אֻכָּפְךָ וְרִידּוּיְךָ, דִּישְׁטְרוֹיְ״ט בְּלַעַ״ז:\",2,0],[2,136,139,6,\"פְּלִיאָה דַעַת וְגוֹ׳. מְכֻסֶּה וְנֶעְלָם מִמֶּנִּי מָקוֹם לִבְרֹחַ מִפָּנֶיךָ (מצאתי):\",1,0],[2,136,139,8,\"וְאַצִּיעָה. מַצָּע וּמִשְׁכָּב:\",1,0],[2,136,139,9,\"אֶשָּׂא כַנְפֵי שָׁחַר. אִם אֶשָּׂא לִי כְּנָפַיִם כַּשַּׁחַר הַזֶּה הַמַּבְהִיק לְפִי שָׁעָה מִסּוֹף הָעוֹלָם לְסוֹפוֹ, כֵּן אֲמַהֵר לָעוּף עַד אֲשֶׁר אֶשְׁכֹּן בְּאַחֲרִית יָם:\",1,0],[2,136,139,11,\"וָאֹמַר אַךְ חֹשֶׁךְ יְשׁוּפֵנִי. אִם אָמַרְתִּי: אֶהְיֶה נִסְתָּר בַּמַּחְשָׁךְ, וְהַחֹשֶׁךְ יַחְשִׁיךְ עָלַי וְלֹא תִרְאֵנִי. יְשׁוּפֵנִי לְשׁוֹן ״נֶשֶׁף״ (איוב כד:טו):\",1,0],[2,136,139,11,\"וְלַיְלָה אוֹר בַּעֲדֵנִי. וְהַלַּיְלָה יְהִי מַאֲפִיל לְנֶגְדִּי, אוֹר זֶה לְשׁוֹן אֹפֶל הוּא, כְּמוֹ ״יָפִיץ עָנָן אוֹרוֹ״ (איוב לז:יא), וְכֵן ״כָּל כּוֹכְבֵי אוֹר״ (תהלים קמח:ג), וְכֵן ״וַיָּאֶר אֶת הַלַּיְלָה״ (שמות יד:כ):\",2,0],[2,136,139,12,\"גַּם. שָׁם אֵין לִי מָנוֹס, כִּי כָּל חֹשֶׁךְ לֹא יַחְשִׁיךְ מִמֶּךָּ:\",1,0],[2,136,139,12,\"כַּחֲשֵׁיכָה כָּאוֹרָה. שְׁנֵיהֶם שָׁוִין לְךָ:\",2,0],[2,136,139,13,\"כִּלְיוֹתָי. הַחוֹשְׁבִים כָּל מַחְשְׁבוֹתַי:\",1,0],[2,136,139,13,\"תְּסֻכֵּנִי. תְּסוֹכְכֵנִי:\",2,0],[2,136,139,15,\"עֻשֵּׂיתִי בַסֵּתֶר. בְּתַשְׁמִישׁ:\",1,0],[2,136,139,15,\"בְּתַחְתִּיּוֹת אָרֶץ. בַּמָּדוֹר הַתַּחְתּוֹן שֶׁבִּמְעֵי אִמִּי (נידה לא.):\",2,0],[2,136,139,16,\"גָּלְמִי רָאוּ עֵינֶיךָ. מֵאָז בָּרָאתָ אֶת הָעוֹלָם רָאוּ עֵינֶיךָ אֶת כָּל גּוֹלְמֵי הַדּוֹרוֹת הַבָּאִים:\",1,0],[2,136,139,16,\"גָּלְמִי. זָהֳרָתִי וְתַבְנִית צוּרָתִי בְּטֶרֶם הִוָּלְדִי וּבְטֶרֶם בּוֹאִי לָעוֹלָם רָאוּ עֵינֶיךָ:\",2,0],[2,136,139,16,\"וְעַל סִפְרְךָ כֻּלָּם יִכָּתֵבוּ. וְכָל יְצוּרֵי עוֹלָם, כָּמוֹנִי כָּמוֹהֶם, גַּם כֻּלָּם בְּטֶרֶם הִבָּרְאָם יַחְדָּיו גְּלוּיִים לְפָנֶיךָ:\",3,0],[2,136,139,16,\"יָמִים יֻצָּרוּ וְלֹא אֶחָד בָּהֶם. כָּל מַעֲשֵׂה הָאָדָם וְתַכְלִיתִיהֶם גְּלוּיִים לְפָנֶיךָ כְּאִלּוּ יֻצָּרוּ כְּבָר, אַף עַל פִּי שֶׁלֹּא הָיָה אֶחָד מִכֻּלָּם וְלֹא הָיָה עֲדַיִן כְּאֶחָד בָּעוֹלָם. וְאֵלּוּ הֵם פִּלְאֵי ״מִפְעֲלוֹת אֱלֹהִים״ (תהלים סו:ה) וּמִשְׁפַּט גְּבוּרָתוֹ, שֶׁעֲתִידוֹת גְּלוּיִים לְפָנָיו טֶרֶם תָּבֹאנָה. וְכֵן הוּא אוֹמֵר ״בְּטֶרֶם אֶצָּרְךָ בַבֶּטֶן וְגוֹ׳״ (ירמיהו א:ה):\",4,0],[2,136,139,16,\"וְעַל סִפְרְךָ כֻּלָּם יִכָּתֵבוּ. סֵפֶר תּוֹלְדוֹת אָדָם שֶׁהֶרְאֵיתָ לְאָדָם הָרִאשׁוֹן (בראשית ה:א):\",5,0],[2,136,139,16,\"כֻּלָּם יִכָּתֵבוּ. כְּמוֹ נִכְתְּבוּ:\",6,0],[2,136,139,16,\"יָמִים יֻצָּרוּ וְלֹא אֶחָד בָּהֶם. לְסוֹף יָמִים רַבִּים הָיוּ עֲתִידִין לְהִבָּרְאוֹת, וְלֹא הָיָה עֲדַיִן אֶחָד מֵהֶם נִבְרָא בָּהֶן. לְפִי הַמָּסֹרֶת שֶׁכָּתוּב וְלֹא זֶהוּ פֵּרוּשׁוֹ, וּלְפִי הַמִּקְרָא שֶׁהוּא נִקְרָא וְלוֹ כָּךְ פֵּרוּשׁוֹ: יָמִים יֻצָּרוּ. הֶרְאָהוּ יָמִים הָעֲתִידִים לְהִבָּרְאוֹת, וּלְחֶלְקוֹ בֵּרַר אֶחָד אֶת יוֹם הַשַּׁבָּת. דָּבָר אַחֵר: זֶה יוֹם הַכִּפּוּרִים לִסְלִיחָה:\",7,0],[2,136,139,17,\"וְלִי מַה יָּקְרוּ רֵעֶיךָ. כְּנֶסֶת יִשְׂרָאֵל אוֹמֶרֶת: מַה נִּכְבְּדוּ בְּעֵינַי הַצַּדִּיקִים שֶׁבְּכָל דּוֹר וָדוֹר:\",1,0],[2,136,139,17,\"וּמֶה עָצְמוּ רָאשֵׁיהֶם. חֶשְׁבּוֹן סְפִירוֹתֵיהֶם, לְשׁוֹן ״כִּי תִשָּׂא אֶת רֹאשׁ בְּנֵי יִשְׂרָאֵל״ (שמות ל:יב):\",2,0],[2,136,139,18,\"אֶסְפְּרֵם מֵחוֹל. אִם בָּאתִי לִסְפֹּר אֶת טוֹב מַעֲשֵׂיהֶם, מֵחוֹל יִרְבּוּן:\",1,0],[2,136,139,18,\"הֱקִיצוֹתִי וְעוֹדִי עִמָּךְ. הִנְנִי בָּאתִי עַתָּה לְקֵץ הַדּוֹרוֹת אֲשֶׁר קָצַבְתָּ מֵאָז עַד הַיּוֹם, וְעוֹד דּוֹר זֶה עִמְּךָ וּבְיִרְאָתֶךָ, וְלֹא נָטִיתִי מֵאַחֲרֶיךָ:\",2,0],[2,136,139,19,\"אִם תִּקְטֹל וְגוֹ׳. הַלְוַאי וְתִקְטוֹל אֶת עֲמָלֵק הָרָשָׁע:\",1,0],[2,136,139,20,\"יֹאמְרוּךָ לִמְזִמָּה. מַזְכִּירִים שִׁמְךָ עַל כָּל מַחְשְׁבוֹת רָעָתָם וּמְכַנִּים אֱלֹהוּתְךָ לַעֲבוֹדַת גִּלוּלִים:\",1,0],[2,136,139,20,\"נָשֻׂא לַשָּׁוְא. כְּמוֹ נָשְׂאוּ לַשָּׁוְא:\",2,0],[2,136,139,20,\"עָרֶיךָ. אוֹיְבֶיךָ. נָשְׂאוּ לַשָּׁוְא אוֹיְבֶיךָ אֶת שְׁמֶךָ:\",3,0],[2,136,139,24,\"אִם דֶּרֶךְ עֹצֶב וְגוֹ׳. אִם דֶּרֶךְ מַעֲצֵבָה וְקִלְקוּל בִּי:\",1,0],[2,136,140,3,\"יָגוּרוּ מִלְחָמוֹת. יִהְיוּ מִלְחָמוֹת בִּמְגוּרֵיהֶם וּבְמוֹשְׁבוֹתָם:\",1,0],[2,136,140,4,\"חֲמַת עַכְשׁוּב. חֲמַת – לְשׁוֹן אֶרֶס, כְּמוֹ ״חֲמַת תַּנִּינִים יֵינָם״ (דברים לב:לג). שֶׁאִם תְּפָרְשֵׁהוּ לְשׁוֹן ׳אַף׳, וְכִי לְשׁוֹן ׳אַף׳ נוֹפֵל אֵצֶל ׳יַיִן׳? אֶלָּא לְשׁוֹן ׳אֶרֶס׳, וִיצוֹ״שׁ בְּלַעַ״ז; וְכֵן נוֹפֵל כָּאן לְשׁוֹן ׳אֶרֶס׳ תַּחַת הַ׳שָּׂפָה׳:\",1,0],[2,136,140,4,\"עַכְשׁוּב. עַכָּבִישׁ, אִירֵיינָ״א בְּלַעַ״ז:\",2,0],[2,136,140,6,\"וַחֲבָלִים פָּרְשׂוּ רֶשֶׁת. דֶּרֶךְ הָרֶשֶׁת לִקְשֹׁר חֶבֶל אָרֹךְ בְּרֹאשָׁהּ, וְהַצַּיָּד, כְּשֶׁרוֹאֶה אֶת הָעוֹפוֹת שׁוֹכְנִים תַּחַת הָרֶשֶׁת, מוֹשֵׁךְ הַחֶבֶל, וְהָרֶשֶׁת נוֹפֵל עַל הָעוֹפוֹת:\",1,0],[2,136,140,6,\"לְיַד מַעְגָּל. אֵצֶל נְתִיבָתִי וּפְעָמַי:\",2,0],[2,136,140,6,\"לְיַד. אֵצֶל, כְּמוֹ ״רְאוּ חֶלְקַת יוֹאָב אֶל יָדִי״ (שמואל ב יד:ל):\",3,0],[2,136,140,9,\"מַאֲוַיֵּי רָשָׁע. עֲמָלֵק הָרָשָׁע (מגילה ו.):\",1,0],[2,136,140,9,\"זְמָמוֹ אַל תָּפֵק. מַחֲשַׁבְתּוֹ אַל תַּצְלִיחַ:\",2,0],[2,136,140,9,\"יָרוּמוּ סֶּלָה. כִּי יִתְגָּאוּ סֶלָה. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (בראשית רבה עה:ט): זְמָמוֹ לְשׁוֹן רֶסֶן הַזּוֹמֵם אֶת פִּי הַגָּמָל, וּלְשׁוֹן מִשְׁנָה הוּא (שבת ה.):\",3,0],[2,136,140,9,\"אַל תָּפֵק. אַל תּוֹצִיא מִלְּחָיָיו:\",4,0],[2,136,140,10,\"רֹאשׁ מְסִבָּי. חֲבוּרַת חֶשְׁבּוֹן גְּדוּדֵי עֵשָׂו הָאוֹמְרִים לְהָסֵב אוֹתִי מֵעָלֶיךָ, עֲמַל שְׂפָתֵיהֶם יְכַסֵּם (מצאתי):\",1,0],[2,136,140,11,\"יִמּוֹטוּ. יִהְיוּ מוּטִים הַגֶּחָלִים עֲלֵיהֶם, יִשְׁכְּבוּ בָּהֶם עַד שֶׁיִּתְמוֹטְטוּ וְיִכְבּוּ מֵאֲלֵיהֶם. נִמְצָא הַגּוּף כָּלֶה וְאָבֵד:\",1,0],[2,136,140,11,\"בָּאֵשׁ יַפִּילֵם. הַמַּפִּיל וְנוֹקֵם גֶּחָלִים שֶׁל גֵּיהִנֹּם (בראשית רבה כ:א) בְּמַהֲמוֹרוֹת יַפִּילֵם לְבַל יָקוּמוּ עוֹד:\",2,0],[2,136,140,11,\"בְּמַהֲמוֹרוֹת. בְּמִלְחָמוֹת וְתָגָר, לְשׁוֹן ״מַמְרִים הֱיִיתֶם״ (דברים ט:כד):\",3,0],[2,136,140,12,\"אִישׁ לָשׁוֹן. עֵשָׂו, כִּי צַיִד בְּפִיו (בראשית כה:כח) – צָד אֶת אָבִיו בְּפִיו (בראשית רבה סג:י):\",1,0],[2,136,140,12,\"יְצוּדֶנּוּ. הָרַע שֶׁהוּא עוֹשֶׂה הוּא יְצוּדֶנּוּ:\",2,0],[2,136,140,13,\"יָדַעְתִּי כִּי. סוֹף הַדְּבָרִים יַעֲשֶׂה ה׳ דִּין עָנִי וְיִנְקֹם נִקְמַת עֲבָדָיו:\",1,0],[2,136,140,14,\"אַךְ. יְמַהֵר וְיַעֲשֶׂה, כְּדֵי שֶׁיּוֹדוּ צַדִּיקִים לִשְׁמוֹ:\",1,0],[2,136,141,2,\"מַשְׂאַת כַּפַּי. מַה שֶּׁאֲנִי נוֹשֵׂא כַּפַּי אֵלֶיךָ:\",1,0],[2,136,141,3,\"שִׁיתָה ה׳ שָׁמְרָה לְפִי. בְּהִתְפַּלְּלִי לְפָנֶיךָ, לִהְיוֹתִי מְדַבֵּר צַחוֹת, שֶׁיִּהְיוּ לְרָצוֹן:\",1,0],[2,136,141,3,\"דַּל שְׂפָתָי. הִיא שָׂפָה הָעֶלְיוֹנָה (כְּמוֹ דְּלָתוֹת שִׂפְתֵי):\",2,0],[2,136,141,4,\"אַל תַּט לִבִּי. אַל יִהְיֶה נוֹטֶה לָרָע:\",1,0],[2,136,141,4,\"אֶת אִישִׁים. עִם אֲנָשִׁים (מצאתי):\",2,0],[2,136,141,4,\"וּבַל אֶלְחַם בְּמַנְעַמֵּיהֶם. וְלֹא אֶהְיֶה מֵסֵב בִּסְעוּדָתָם:\",3,0],[2,136,141,5,\"יֶהֶלְמֵנִי צַדִּיק חֶסֶד וְיוֹכִיחֵנִי. טוֹב לִי שֶׁיּוֹכִיחֵנִי וִייַסְּרֵנִי נָבִיא אֱמֶת וְצֶדֶק, שֶׁכָּל מַהֲלוּמָיו וְתוֹכַחְתּוֹ חֶסֶד:\",1,0],[2,136,141,5,\"שֶׁמֶן רֹאשׁ אַל יָנִי רֹאשִׁי. שֶׁמֶן מַלְכוּת שֶׁהוּצַק עַל רֹאשִׁי, כְּמוֹ שֶׁנֶּאֱמַר ״דִּשַּׁנְתָּ בַשֶּׁמֶן רֹאשִׁי״ (תהלים כג:ה), אַל יָסִיר אֶת רֹאשִׁי מִתּוֹכַחַת הַצַּדִּיק לָלֶכֶת וְלִלְחֹם אֶת פּוֹעֲלֵי אָוֶן:\",2,0],[2,136,141,5,\"כִּי עוֹד. כִּי כָּל עוֹד וּתְפִלָּתִי בְּפִי, הֲרֵי הִיא בִּשְׁבִיל רָעוֹתֵיהֶם שֶׁל פּוֹעֲלֵי אָוֶן, שֶׁלֹּא אֶכָּשֵׁל בָּהֶם:\",3,0],[2,136,141,6,\"נִשְׁמְטוּ בִידֵי סֶלַע שׁוֹפְטֵיהֶם. כִּי דַיָּנֵיהֶם וּמַנְהִיגֵיהֶם שֶׁל אֵלּוּ נִשְׁמְטוּ מִדֶּרֶךְ הַטּוֹב בְּיַד יֵצֶר הָרָע וְלֵב הָאֶבֶן וְקָשֶׁה כַּסֶּלַע:\",1,0],[2,136,141,6,\"וְשָׁמְעוּ אֲמָרַי. הַנְּעִימִים שֶׁאֲנִי מְדַבֵּר בְּמִצְוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֵינָם שָׁבִים מִדַּרְכָּם הָרָעָה. וְרַבּוֹתֵינוּ בִּבְרַיְתָא דְּסִפְרָא דְּרָשׁוּהוּ (ספרי דברים כו) בְּמֹשֶׁה וְאַהֲרֹן שֶׁמֵּתוּ עַל יְדֵי הַסֶּלַע (במדבר כ:יב), אֲבָל אֵינִי יָכוֹל לְיַשֵּׁב הַמִּקְרָא סוֹפוֹ לְרֹאשׁוֹ. וְיֵשׁ לְיַשְּׁבוֹ וְלוֹמַר: דּוֹמִין אֵלּוּ לְעִקְּשׁוּת לְאוֹתָן שֶׁמֵּתוּ מֹשֶׁה וְאַהֲרֹן עַל יְדֵי הַסֶּלַע עַל יְדֵיהֶם, כִּי אַף אֵלּוּ שָׁמְעוּ אֲמָרַי נְעִימִים וְאֵינָם שָׁבִים:\",2,0],[2,136,141,7,\"כְּמוֹ פוֹלֵחַ. עֵצִים:\",1,0],[2,136,141,7,\"וּבוֹקֵעַ בָּאָרֶץ. כֵּן נִפְזְרוּ עֲצָמֵינוּ לְהַגִּיעַ לְפֶתַח הַמָּוֶת בִּשְׁבִיל רָעוֹתֵיהֶם שֶׁל עוֹבְרֵי עֲבֵרָה:\",2,0],[2,136,141,7,\"פּוֹלֵחַ. לְשׁוֹן בִּקּוּעַ, כְּמוֹ ״יְפַלַּח כִּלְיוֹתָי״ (איוב טז:יג):\",3,0],[2,136,141,8,\"כִּי אֵלֶיךָ ה׳ אֲדֹנָי עֵינָי. מוּסָב לַמִּקְרָאוֹת שֶׁל מַעְלָה שִׁיתָה שָׁמְרָה לְפִי וְאַל תַּט, כִּי עָלֶיךָ עֵינָי וְגוֹ׳:\",1,0],[2,136,141,8,\"אַל תְּעַר נַפְשִׁי. אַל תְּשַׁלַּח נַפְשִׁי מִלְּפָנֶיךָ, כְּמוֹ ״וַתְּעַר כַּדָּהּ אֶל הַשֹּׁקֶת״ (בראשית כד:כ):\",2,0],[2,136,141,10,\"יִפְּלוּ בְמַכְמוֹרָיו רְשָׁעִים. יִפּוֹל הָרָשָׁע עַצְמוֹ בְּמַכְמוֹרָיו שֶׁהוּא פּוֹרֵשׂ לְרַגְלִי:\",1,0],[2,136,142,1,\"בַּמְּעָרָה. שֶׁכָּרַת בָּהּ כְּנַף הַמְּעִיל אֲשֶׁר לְשָׁאוּל (שמואל א כד:ד):\",1,0],[2,136,142,4,\"וְאַתָּה יָדַעְתָּ נְתִיבָתִי. כַּמָּה מוֹקְשִׁים יֵשׁ בָּהּ:\",1,0],[2,136,142,5,\"וְאֵין לִי מַכִּיר. אֵין בְּכָל מְשָׁרְתֵי שָׁאוּל שֶׁיִּמְחֶה בְיָדוֹ:\",1,0],[2,136,142,8,\"בִּי יַכְתִּירוּ צַדִּיקִים. בִּשְׁבִילִי יַכְתִּירוּךָ צַדִּיקִים וְיוֹדוּ לִשְׁמֶךָ שֶׁאַתָּה סוֹמֵךְ אֶת יְרֵאֶיךָ:\",1,0],[2,136,143,1,\"בֶּאֱמוּנָתְךָ. לְהַאֲמִין הַבְטָחָה שֶׁהִבְטַחְתַּנִי:\",1,0],[2,136,143,3,\"כִּי רָדַף אוֹיֵב נַפְשִׁי. כְּלוֹמַר: אִם חָטָאתִי לְךָ, הֲרֵי לָקִיתִי. וּכְנֶגֶד כָּל יִשְׂרָאֵל נֶאֱמַר מִזְמוֹר זֶה:\",1,0],[2,136,143,4,\"יִשְׁתּוֹמֵם. לְשׁוֹן אֹטֶם וְתִמָּהוֹן, כְּמוֹ ״וָאֵשֵׁב שָׁם שִׁבְעַת יָמִים מַשְׁמִים בְּתוֹכָם״ (יחזקאל ג:טו); ״וַתֵּשֶׁב תָּמָר וְשֹׁמֵמָה״ (שמואל ב יג:כ):\",1,0],[2,136,143,5,\"זָכַרְתִּי יָמִים מִקֶּדֶם. שֶׁהִפְלֵיתָ לָנוּ נִסִּים רַבִּים:\",1,0],[2,136,143,6,\"כְּאֶרֶץ עֲיֵפָה. בַּגּוֹלָה:\",1,0],[2,136,143,7,\"כָּלְתָה רוּחִי. הַמִּתְאַוֶּה וְאֵינוֹ מַשִּׂיג קָרוּי ״כִּלְיוֹן עֵינַיִם״ (דברים כח:סה) וְכִלְיוֹן רוּחַ:\",1,0],[2,136,143,8,\"בַּבֹּקֶר. בִּצְמֹחַ הַגְּאֻלָּה (מצאתי):\",1,0],[2,136,143,8,\"הוֹדִיעֵנִי דֶרֶךְ זוּ. נָשָׂאתִי נַפְשִׁי אֵלֶיךָ שֶׁתְּקַבֵּל שְׁאֵלָתִי (ס״א אינו):\",2,0],[2,136,143,9,\"אֵלֶיךָ כִסִּיתִי. תְּלָאוֹתַי, אֲנִי מְכַסֶּה מִכָּל אָדָם לְהַגִּידָם אֵלֶיךָ:\",1,0],[2,136,144,2,\"הָרוֹדֵד עַמִּי תַחְתָּי. הָרוֹקֵעַ וְשׁוֹטֵחַ אֶת עַמִּי לִרְבֹּץ בִּמְקוֹמוֹ, כְּמוֹ ״שׁוֹטֵחַ לַגּוֹיִם״ (איוב יב:כג) מַגְדִּיל אוֹתָם. רוֹדֵד תַּרְגּוּם שֶׁל רוֹקֵעַ, כְּדִמְתַרְגֵּם ״וַיְרַקְּעוּ״ (שמות לט:ג): ״וְרַדִּידוּ״. וְיֵשׁ פּוֹתְרִים: הָרוֹדֵד עַמִּים תַּחְתִּי, הַמַּחֲלִישׁ עַמִּים תַּחְתִּי. אַךְ בְּסֵפֶר מְדֻיָּק מֻגֶּה עַמִּי, וּמְסוֹרָה עָלָיו: שְׁלֹשָׁה סְבִירִין עַמִּים וְקוֹרִין עַמִּי. וְעַל תַּחְתִּי יֵשׁ מְסוֹרָה עָלָיו: תַּחְתָּיו קְרִי:\",1,0],[2,136,144,3,\"מָה אָדָם. מַה פָּרַס וְיִשְׁמָעֵאל לְפָנֶיךָ, כִּי יְדַעְתָּם לְהַרְבּוֹת לָהֶם גְּדֻלָּה?\",1,0],[2,136,144,4,\"יָמָיו כְּצֵל עוֹבֵר. שְׁלֹמֹה אָמַר ״וַיַּעֲשֵׂם כַּצֵּל״ (קהלת ו:יב), וְלֹא פֵּרַשׁ אִם צֵל דֶּקֶל אוֹ צֵל כּוֹתֶל שֶׁהֵם קְבוּעִים. כְּבָר פֵּרַשׁ אָבִיו: כְּצֵל עוֹבֵר. צִלּוֹ שֶׁל עוֹף הַפּוֹרֵחַ (קהלת רבה א:ב):\",1,0],[2,136,144,7,\"פְּצֵנִי. הוֹצִיאֵנִי, וּלְשׁוֹן הַצָּלָה הוּא, וְכֵן ״הַפּוֹצֶה אֶת דָּוִד עַבְדּוֹ״ (תהלים קמד:י) (מצאתי):\",1,0],[2,136,144,8,\"פִּיהֶם דִּבֶּר שָׁוְא וְגוֹ׳. תָּלָה הַכָּתוּב שָׁוְא בַּפֶּה וְשֶׁקֶר בַּיָּמִין, בָּאוּ לְסַפֵּר בַּפֶּה בּוֹדִים גּוּזְמָא עַל שָׁוְא אַף לְשַׁנּוֹת אֶת הַיָּדוּעַ, בָּאוּ לִפְשֹׁט יְמִינָם לִשְׁבוּעָה חָדְלוּ מִשָּׁוְא שֶׁנִּתְפַּס עָלָיו כְּגַנָּב אֲבָל בְּשֶׁקֶר נִשְׁבָּעִין שֶׁכָּךְ גּוֹרָלָם:\",1,0],[2,136,144,10,\"הַנּוֹתֵן תְּשׁוּעָה לַמְּלָכִים. מְדַבֵּר עַל ״סֶלַע הַמַּחְלְקוֹת״ (שמואל א כג:כח) שֶׁהָיָה דָּוִד קָרוֹב לִיתָּפֵשׂ בְּיַד שָׁאוּל, וּבָא מַלְאָךְ אֶל שָׁאוּל: ״מַהֲרָה וְלֵכָה וְגוֹ׳״ (שמואל א כג:כז). הִצִּיל אֶת שָׁאוּל מִהְיוֹת שׁוֹפֵךְ דָּם נָקִי, וְאֶת דָּוִד מִהְיוֹת נֶהֱרָג:\",1,0],[2,136,144,11,\"פְּצֵנִי וְהַצִּילֵנִי. כַּאֲשֶׁר פָּצִיתָ אָז, כֵּן פְּצֵנִי עַתָּה:\",1,0],[2,136,144,12,\"אֲשֶׁר בָּנֵינוּ וְגוֹ׳. כְּלוֹמַר: גַּם עַתָּה דּוֹר זֶה כָּשֵׁר הוּא:\",1,0],[2,136,144,12,\"בָּנֵינוּ כִּנְטִעִים. שֶׁאֵין בָּהֶם מוּם, כָּל כָּךְ הֵם מְנֻקִּים מֵעֲבֵירָה (מצאתי):\",2,0],[2,136,144,12,\"מְגֻדָּלִים בִּנְעוּרֵיהֶם. בְּשֵׁם טוֹב זֶה, שֶׁהֵם כִּנְטִיעִים בְּנַעֲרוּתָם, גְּדֵלִים כָּל יְמֵיהֶם. וְאִי אֶפְשָׁר לְקַיֵּם כָּל שֶׁבַח זֶה אֶלָּא בְּדוֹרוֹ שֶׁל חִזְקִיָּהוּ:\",3,0],[2,136,144,12,\"בְּנוֹתֵינוּ. גְּבוֹהוֹת קוֹמָה נָאָה כְזָוִיֹּת שֶׁל בַּיִת אֲבָנִים, שֶׁזָּוִיּוֹת אֶבֶן מְכֻוָּנוֹת כְּנֶגֶד חֲבֶרְתָּהּ וְעוֹלָה לְמַעְלָה עַד שֶׁהַזָּוִיּוֹת מְיֻשָּׁרוֹת:\",4,0],[2,136,144,12,\"מְחֻטָּבוֹת תַּבְנִית הֵיכָל. מְהֻלָּלוֹת בְּפִי רוֹאֵיהֶן, וּמְדַמִּין אוֹתָם לְתַבְנִית קוֹמַת הַהֵיכָל. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (פסחים פז.) בְּנוֹתֵינוּ כְזָוִיֹּת. מִתְמַלְּאוֹת תַּאֲוָה כְּזָוִיּוֹת מִזְבֵּחַ הַמְּלֵאוֹת דָּם, וְאֵינָן נִבְעָלוֹת אֶלָּא לְבַעֲלֵיהֶן:\",5,0],[2,136,144,13,\"מְזָוֵינוּ מְלֵאִים. זָוִיּוֹת אוֹצְרוֹתֵינוּ מְלֵאִים טוֹב:\",1,0],[2,136,144,13,\"מְפִיקִים מִזַּן אֶל זָן. מַסְפִּיקִים מָזוֹן מִשָּׁנָה לְשָׁנָה, מִזַּן אֶל זָן מִשְּׁעַת אָסִיף מָזוֹן לְשָׁנָה זוֹ עַד זְמַן אָסִיף לְשָׁנָה אַחֶרֶת, זָן גוֹבִירְנִיי״ל בְּלַעַ״ז:\",2,0],[2,136,144,13,\"מַאֲלִיפוֹת מְרֻבָּבוֹת. לַאֲלָפִים וְלִרְבָבוֹת עוֹשׂוֹת פְּרִי:\",3,0],[2,136,144,14,\"אַלּוּפֵינוּ מְסֻבָּלִים. אַלּוּפִים גְּדוֹלִים שֶׁבָּנוּ נִסְבָּלִים עַל קְטַנֵּיהֶם, שֶׁהַקְּטַנִּים נִשְׁמָעִים לַגְּדוֹלִים, וּמִתּוֹךְ כָּךְ אֵין פֶּרֶץ בָּנוּ:\",1,0],[2,136,144,14,\"וְאֵין יוֹצֵאת. אֵין שְׁמוּעָה רָעָה יוֹצֵאת לְמֵרָחוֹק:\",2,0],[2,136,144,14,\"וְאֵין צְוָחָה. וְאֵין קוֹל מְהוּמוֹת מִלְחָמָה:\",3,0],[2,136,144,15,\"שֶׁכָּכָה לּוֹ. שֶׁכָּל טוֹבָה הַזֹּאת שֶׁלּוֹ:\",1,0],[2,136,145,4,\"דּוֹר לְדוֹר יְשַׁבַּח מַעֲשֶׂיךָ. וְגַם אֲנִי הֲדַר כְּבוֹד הוֹדְךָ אָשִׂיחָה:\",1,0],[2,136,145,6,\"וְעֱזוּז נוֹרְאוֹתֶיךָ יֹאמֵרוּ. וְגַם אֲנִי גְּדֻלָּתְךָ אֲסַפְּרֶנָּה:\",1,0],[2,136,145,7,\"זֵכֶר רַב טוּבְךָ יַבִּיעוּ. דּוֹר לְדוֹר גְּבוּרָתְךָ יְדַבֵּרוּ זֶה לָזֶה לֵאמֹר: טוֹב לָנוּ לְהוֹדִיעַ לִבְנֵי הָאָדָם גְּבוּרוֹתָיו וּכְבוֹד הֲדַר מַלְכוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (מצאתי):\",1,0],[2,136,145,14,\"נוּ״ן חֲסֵרָה מֵאָלְפָ״א בֵּיתָ״א, לְפִי שֶׁרָאָה דָּוִד בָּהּ מַפָּלָה קָשָׁה: ״נָפְלָה וְלֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל״ (עמוס ה:ב), וְחָזַר וּסְמָכָהּ בְּרוּחַ הַקֹּדֶשׁ: סוֹמֵךְ ה׳ לְכָל הַנּוֹפְלִים (ברכות ד:):\",1,0],[2,136,145,16,\"וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן. כְּדֵי פַרְנָסָתוֹ הוּא מַשְׂבִּיעַ אֶת טוּבוֹ וְאֶת רְצוֹנוֹ וְאֶת בִּרְכָתוֹ. רָצוֹן אפיימנ״ט בְּלַעַ״ז:\",1,0],[2,136,145,21,\"תְּהִלַּת ה׳ יְדַבֶּר פִּי. וְגַם כָּל בָּשָׂר יְבָרֵךְ אֶת שֵׁם קָדְשׁוֹ לְעוֹלָם וָעֶד:\",1,0],[2,136,146,2,\"אֲזַמְּרָה לֵאלֹהַי בְּעוֹדִי. בְּעוֹד אֲנִי חַי:\",1,0],[2,136,146,4,\"עֶשְׁתֹּנוֹתָיו. מַחְשְׁבוֹתָיו:\",1,0],[2,136,146,5,\"אַשְׁרֵי. מִי שֶׁאֵל יַעֲקֹב בְּעֶזְרוֹ, שֶׁהִבְטִיחוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא ״הִנֵּה אָנֹכִי עִמָּךְ וּשְׁמַרְתִּיךָ וַהֲשִׁיבֹתִיךָ״ (בראשית כח:טו). וְלָמָּה אַשְׁרָיו? לְפִי שֶׁהוּא עוֹשֶׂה שָׁמַיִם וָאָרֶץ וְאֶת הַיָּם, וְכֵיוָן שֶׁהַכֹּל שֶׁלּוֹ, יֵשׁ בְּיָדוֹ לְשָׁמְרוֹ בַּיָּם וּבַיַּבָּשָׁה. אֲבָל מֶלֶךְ עוֹבֵד גִּלּוּלִים, אִם שׁוֹמְרוֹ בַּיַּבָּשָׁה אֵינוֹ יָכוֹל לְשָׁמְרוֹ בַּיָּם:\",1,0],[2,136,146,6,\"הַשּׁוֹמֵר אֱמֶת לְעוֹלָם. לְסוֹף דּוֹרוֹת רַבִּים הוּא מְקַיֵּם וְשׁוֹמֵר אֲמִתַּת הַבְטָחָתוֹ:\",1,0],[2,136,146,9,\"יְעוֹדֵד. לְשׁוֹן כֹּחַ:\",1,0],[2,136,146,10,\"יִמְלֹךְ ה׳ לְעוֹלָם. יְקַיֵּם אֶת מַלְכוּתוֹ בִּשְׁמִירַת בָּנָיו:\",1,0],[2,136,147,1,\"כִּי טוֹב זַמְּרָה. כִּי טוֹב לְזַמֵּר לוֹ:\",1,0],[2,136,147,9,\"לַחְמָהּ. מַאֲכָלָהּ:\",1,0],[2,136,147,9,\"לִבְנֵי עוֹרֵב. פֵּרְשׁוּ רַבּוֹתֵינוּ (ויקרא רבה יט, א), שֶׁהוּא אַכְזָרִי עַל בָּנָיו, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְרַחֵם עֲלֵיהֶם וּמַזְמִין לָהֶם יַתּוּשִׁין מִתּוֹךְ צוֹאָתָם וְנִכְנָסִין לְתוֹךְ פִּיהֶם:\",2,0],[2,136,147,10,\"לֹא בִגְבוּרַת הַסּוּס יֶחְפָּץ. הַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,136,147,10,\"לֹא בְשׁוֹקֵי הָאִישׁ יִרְצֶה. וְלֹא בְּקַלּוּת מְרוּצַת שׁוֹקֵי הָאִישׁ יִרְצֶה:\",2,0],[2,136,147,14,\"חֵלֶב חִטִּים. טוּב חִטִּים שְׁמֵנִים:\",1,0],[2,136,147,16,\"כְּפוֹר. גְּלִיזָ״א בְּלַעַ״ז:\",1,0],[2,136,147,17,\"מַשְׁלִיךְ קַרְחוֹ כְפִתִּים. הַמַּיִם מַגְלִידִים וְנַעֲשִׂין פְּתִיתִין פְּתִיתִין, וּמִדְרַשׁ אַגָּדָה כְפִתִּים הַכֹּל לְפִי מַשָּׂא הַבְּרִיּוֹת: הֶעָנִי לְפִי חוֹסֶר מַלְבּוּשָׁיו מֵיקֵל עָלָיו:\",1,0],[2,136,147,17,\"מִי יַעֲמֹד. שֶׁלֹּא יְהֵא צוֹנֵן בְּקָרָתוֹ:\",2,0],[2,136,147,18,\"יִשְׁלַח דְּבָרוֹ וְיַמְסֵם. לְאוֹתָם פִּתִּים:\",1,0],[2,136,147,18,\"יַשֵּׁב רוּחוֹ. רוּחַ מַעֲרָבִי לְהַשְׁבִּית הַקֶּרַח, וְיִזְּלוּ מָיִם:\",2,0],[2,136,148,3,\"כּוֹכְבֵי אוֹר. כּוֹכְבֵי לַיְלָה:\",1,0],[2,136,148,6,\"חׇק נָתַן. בָּהֶם, זֶה יְשַׁמֵּשׁ בַּיּוֹם וְזֶה יְשַׁמֵּשׁ בַּלַּיְלָה וְלֹא יַעֲבוֹר אוֹתוֹ חֹק:\",1,0],[2,136,148,7,\"תַּנִּינִים. דָּגִים גְּדוֹלִים:\",1,0],[2,136,148,8,\"וּבָרָד. גְּלַצָ״א בְּלַעַ״ז:\",1,0],[2,136,148,8,\"שֶׁלֶג. נֵיי״ף בְּלַעַ״ז:\",2,0],[2,136,148,8,\"וְקִיטוֹר. עִנְיַן שׁוֹאָה שֶׁקּוֹרִין בְּרוּאִינ״ה בְּלַעַ״ז:\",3,0],[2,136,148,8,\"רוּחַ סְעָרָה. הָעוֹשָׂה אֶת דְּבָרוֹ וּשְׁלִיחוּתוֹ, וְאָמְרוּ רַבּוֹתֵינוּ (חגיגה יב:) שֶׁהַדְּבָרִים הַלָּלוּ הָיוּ תְּחִלָּתָם גְּנוּזִים בַּשָּׁמַיִם, וּבָא דָּוִד וְהוֹרִידָן לָאָרֶץ, לְפִי שֶׁהֵם מִינֵי פֻּרְעָנִיּוֹת, וְאֵין נָאֶה לָהֶם לִהְיוֹת גְּנוּזִין בִּמְגוּרָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:\",4,0],[2,136,149,6,\"רוֹמְמוֹת אֵל בִּגְרוֹנָם. וְהֵם לְחֶרֶב פִּיפִיּוֹת בְּיָדָם:\",1,0],[2,136,149,8,\"בַּזִּקִּים. שַׁרְשְׁרָאוֹת:\",1,0],[2,136,149,9,\"מִשְׁפָּט כָּתוּב. ״וְנָתַתִּי אֶת נִקְמָתִי בֶּאֱדוֹם וְגוֹמֵר״ (יחזקאל כה:יד), וְאִם תֹּאמַר עֲדַיִן לֹא נוֹלַד יְחֶזְקֵאל כְּשֶׁאָמַר דָּוִד זֹאת? נִתְנַבֵּא דָּוִד עַל קֵץ הַגְּאֻלָּה, וּכְשֶׁיָּבֹא הַקֵּץ, כְּבָר כָּתוּב הוּא הַמִּשְׁפָּט זֶה יָמִים רַבִּים:\",1,0],[2,136,150,4,\"בְּמִנִּים וְעוּגָב. מִינֵי כְּלֵי שִׁיר הֵם:\",1,0],[2,136,150,5,\"בְּצִלְצְלֵי שָׁמַע. מְצִלְתַּיִם הַמַּשְׁמִיעִים קוֹל:\",1,0],[2,136,150,5,\"שָׁמַע. שֵׁם דָּבָר הוּא, כְּמוֹ שֶׁמַע בְּסֶגוֹל, וּמִפְּנֵי הָאֶתְנַחְתָּא הוּא נָקוּד קָמַץ גָּדוֹל, וּלְכָךְ טַעֲמוֹ לְמַעְלָה תַּחַת הַשִּׁי״ן. סְלִיק סֵפֶר תְּהִלִּים:\",2,0],[2,137,1,1,\"וַיְהִי בִּימֵי שְׁפֹט הַשֹּׁפְטִים. לִפְנֵי מְלֹךְ מֶלֶךְ שָׁאוּל, שֶׁהָיוּ הַדּוֹרוֹת מִתְפַּרְנְסִים עַל יְדֵי שׁוֹפְטִים. וּבִימֵי אִבְצָן הָיָה, שֶׁאָמְרוּ רַבּוֹתֵינוּ, אִבְצָן זֶה בֹּעַז:\",1,0],[2,137,1,1,\"וַיֵּלֶךְ אִישׁ. עָשִׁיר גָּדוֹל הָיָה וּפַרְנַס הַדּוֹר. וְיָצָא מֵאֶרֶץ יִשְׂרָאֵל לְחוּץ לָאָרֶץ מִפְּנֵי צָרוּת הָעָיִן, שֶׁהָיְתָה עֵינוֹ צָרָה בָעֲנִיִּים הַבָּאִים לְדָחְקוֹ, לְכַךְ נֶעֱנַשׁ:\",2,0],[2,137,1,2,\"אֶפְרָתִים. חֲשׁוּבִים. וְכֵן \\\"בֶּן תֹּחוּ בֶן צוּף אֶפְרָתִי\\\" אֶבְגִּינוֹס. רְאֵה חֲשִׁיבוּתָם, שֶׁהֲרֵי הִשִּׂיא עֶגְלוֹן מֶלֶךְ מוֹאָב אֶת בִּתּוֹ לְמַחְלוֹן, דְּאָמַר מַר, רוּת בִּתּוֹ שֶׁל עֶגְלוֹן הָיְתָה. דָּבָר אַחֵר, \\\"אֶפְרָתִים\\\", בֵּית לֶחֶם קְרוּיָה אֶפְרָת:\",1,0],[2,137,1,3,\"אִישׁ נָעֳמִי. לָמָּה נֶאֱמַר? מִכַּאן אָמְרוּ, אֵין אִישׁ מֵת אֶלָּא לְאִשְׁתּוֹ. (וְאָמַר \\\"אִישׁ נָעֳמִי\\\" כְּלוֹמַר, לְפִי שֶׁהוּא הָיָה אִישׁ נָעֳמִי וְשׁוֹלֵט עָלֶיהָ וְהִיא טְפֵלָה לוֹ, לָכֵן, פָּגְעָה בוֹ מִדַּת הַדִּין וְלֹא בָהּ):\",1,0],[2,137,1,5,\"גַם שְׁנֵיהֶם. מַהוּ \\\"גַם\\\"? בַּתְּחִלָּה לָקוּ בְמָמוֹנָם וּמֵתוּ גְמַלֵּיהֶם וּמִקְנֵיהֶם, וְאַחַר כָּךְ מֵתוּ גַם הֵם:\",1,0],[2,137,1,7,\"וַתֵּצֵא מִן הַמָּקוֹם. לָמָּה נֶאֱמַר? הֲרֵי כְבָר נֶאֱמַר: \\\"וַתָּשָׁב מִשְּׂדֵי מוֹאָב\\\", וּמֵהֵיכָן תָּשׁוּב אִם לֹא תֵצֵא מִן הַמָּקוֹם שֶׁהָיְתָה שָׁם? אֶלָּא מַגִּיד שֶׁיְּצִיאַת צַדִּיק מִן הַמָּקוֹם נִכֶּרֶת וְעוֹשָׂה רשֶׁם. פָּנָה זִיוָהּ, פָּנָה הֲדָרָהּ, פָּנָה שִׁבְחָהּ שֶׁל עִיר. וְכֵן \\\"וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע\\\":\",1,0],[2,137,1,12,\"כִּי זָקַנְתִּי מִהְיוֹת לְאִישׁ. שֶׁאֶנָּשֵׂא לוֹ וְאוֹלִיד בָּנִים וְתִנָּשְׂאוּ לָהֶם, שֶׁאֵינָם אֲסוּרִים לָכֶם וְאֵינְכֶם אֲסוּרוֹת לָהֶם מִשּׁוּם אֵשֶׁת אָחִיו שֶׁלֹּא הָיָה בְעוֹלָמוֹ שֶׁאֵינָהּ זְקוּקָה לְיָבָם, לְפִי שֶׁלֹּא הָיוּ לְמַחְלוֹן וְכִלְיוֹן קִדּוּשִׁין בָּהֶן שֶׁנָּכְרִיּוֹת הָיוּ וְלֹא נִתְגַּיְּרוּ וְעַכְשָׁיו הֵן בָּאוֹת לְהִתְגַּיֵּר כְּמוֹ שֶׁנֶּאֱמַר, \\\"כִּי אִתָּךְ נָשׁוּב לְעַמֵּךְ\\\". מֵעַתָּה, נִהְיֶה לְעַם אֶחָד:\",1,0],[2,137,1,12,\"כִּי אָמַרְתִּי יֶשׁ לִי תִקְוָה. כִּי אֲפִלּוּ אָמַר לִי לִבִּי יֶשׁ לִי תִקְוָה לִנָּשֵׂא עוֹד וְלָלֶדֶת בָּנִים:\",2,0],[2,137,1,12,\"גַּם הָיִיתִי הַלַּיְלָה לְאִישׁ. וְיוֹתֵר מִכֵּן, אֲפִלּוּ הָרִיתִי הַלַּיְלָה זְכָרִים:\",3,0],[2,137,1,12,\"וְגַם יָלַדְתִּי בָנִים. אוֹ אֲפִלּוּ כְּבָר יָלַדְתִּי בָנִים:\",4,0],[2,137,1,13,\"הֲלָהֵן תְּשַׂבֵּרְנָה. בִּתְמִיהַּ, שֶׁמָּא לָהֶם תְּצַפֶּינָה עַד אֲשֶׁר יִגְדָּלוּ? לְשׁוֹן \\\"שִׂבְרוֹ עַל ה' אֱלֹהָיו\\\":\",1,0],[2,137,1,13,\"תֵּעָגֵנָה. לְשׁוֹן אָסוּר וְכָלוּא כְּמוֹ \\\"עָג עוּגָה וְעָמַד בְּתוֹכָהּ\\\". וְיֵשׁ פּוֹתְרִין לְשׁוֹן עִגּוּן, וְלֹא יִתָּכֵן, שֶׁאִם כֵּן הָיָה לוֹ לִנָּקֵד הַנּוּ\\\"ן דָּגֵשׁ אוֹ לִכְתֹּב שְׁנֵי נוּנִי\\\"ן:\",2,0],[2,137,1,13,\"כִּי יָצְאָה בִי יַד ה'. אָמַר רַבִּי לֵוִי, כָּל מָקוֹם שֶׁנֶּאֱמַר \\\"יַד ה'\\\" מַכַּת דֶּבֶר הוּא. וּבִנְיַן אָב לְכֻלָּם \\\"הִנֵּה יַד ה' הוֹיָה\\\":\",3,0],[2,137,1,15,\"הִנֵּה שָׁבָה יְבִמְתֵּךְ. זֶה טַעְמוֹ לְמַעְלָה תַּחַת הַשִּׁי\\\"ן לְפִי שֶׁהוּא לְשׁוֹן עָבַר. \\\"וּבַבֹּקֶר הִיא שָׁבָה\\\" טַעְמוֹ לְמַטָּה בַּבֵי\\\"ת לְפִי שֶׁהוּא לְשׁוֹן הֹוֶה, וְכֵן כָּל כַּיּוֹצֵא בָהֶם:\",1,0],[2,137,1,16,\"אַל תִּפְגִּעִי בִי. אַל תִּפְצְרִי בִי:\",1,0],[2,137,1,16,\"כִּי אֶל אֲשֶׁר תֵּלְכִי אֵלֵךְ. מִכַּאן אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, גֵּר שֶׁבָּא לְהִתְגַּיֵּר מוֹדִיעִין לוֹ מִקְצַת עֳנָשִׁים, שֶׁאִם בָּא לַחֲזֹר בּוֹ יַחֲזֹר, שֶׁמִּתּוֹךְ דְּבָרֶיהָ שֶׁל רוּת אַתָּה לָמֵד מַה שֶּׁאָמְרָה לָהּ נָעֳמִי. \\\"אָסוּר לָנוּ לָצֵאת חוּץ לַתְּחוּם בַּשַּׁבָּת\\\". אָמְרָה לָהּ, \\\"בַּאֲשֶׁר תֵּלְכִי אֵלֵךְ\\\". \\\"אָסוּר לָנוּ לְהִתְיַחֵד נְקֵבָה עִם זָכָר שֶׁאֵינוֹ אִישָׁהּ\\\". אָמְרָה לָהּ, \\\"בַּאֲשֶׁר תָּלִינִי אָלִין\\\". \\\"עַמֵּנוּ מֻבְדָּלִים מִשְּׁאָר עַמִּים בְּתַרְיַ\\\"ג מִצְוֹת\\\", \\\"עַמֵּךְ עַמִּי\\\". \\\"אָסוּר לָנוּ עֲבוֹדַת כּוֹכָבִים, \\\"אֱלֹהַיִךְ אֱלֹהָי\\\". \\\"אַרְבַּע מִיתוֹת נִמְסְרוּ לְבֵית דִּין, \\\"בַּאֲשֶׁר תָּמוּתִי אָמוּת\\\". \\\"שְׁנֵי קְבָרִים נִמְסְרוּ לְבֵית דִּין, אֶחָד לְנִסְקָלִין וְנִשְׂרָפִין וְאֶחָד לְנֶהֱרָגִין וְנֶחְנָקִין\\\". אָמְרָה לָהּ, \\\"וְשָׁם אֶקָּבֵר\\\":\",2,0],[2,137,1,17,\"כֹּה יַעֲשֶׂה ה' לִי. כַּאֲשֶׁר הִתְחִיל לְהָרַע, שֶׁיָּצְאָה בִי יָדוֹ לְהָמִית אִישִׁי וְלֵירֵד מִנְּכָסַי:\",1,0],[2,137,1,17,\"וְכֹה יוֹסִיף. אִם יַפְרִיד בֵּינִי וּבֵינֵךְ כִּי אִם הַמָּוֶת:\",2,0],[2,137,1,18,\"וַתֶּחְדַּל לְדַבֵּר אֵלֶיהָ. מִכַּאן אָמְרוּ, אֵין מַרְבִּין עָלָיו וְאֵין מְדַקְדְּקִין עָלָיו:\",1,0],[2,137,1,19,\"וַתֵּלַכְנָה שְׁתֵּיהֶם. אָמַר רַבִּי אַבָּהוּ, \\\"בֹּא וּרְאֵה כַּמָּה חֲבִיבִים הַגֵּרִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁנָּתְנָה דַעְתָּהּ לְהִתְגַּיֵּר, הִשְׁוָה אוֹתָהּ הַכָּתוּב לְנָעֳמִי\\\":\",1,0],[2,137,1,19,\"וַתֵּהֹם כָּל הָעִיר. נַעֲשֵׂית הוֹמִיָּה כָל הָעִיר. כֻּלָּם נִתְקַבְּצוּ לִקְבֹּר אִשְׁתּוֹ שֶׁל בֹּעַז שֶׁמֵּתָה בּוֹ בַיּוֹם:\",2,0],[2,137,1,19,\"הֲזֹאת נָעֳמִי. הַהֵ\\\"א נְקוּדָה חֲטָף מִפְּנֵי שֶׁהִיא בִתְמִיהַּ, הֲזֹאת נָעֳמִי שֶׁרְגִילָה לָצֵאת בַּצַּבִּים וּבַפְּרָדִים? חֲזִיתֶם מֶה עָלְתָה לָהּ עַל אֲשֶׁר יָצָאת לְחוּצָה לָאָרֶץ:\",3,0],[2,137,1,21,\"מְלֵאָה הָלַכְתִּי. בְּעֹשֶׁר וּבָנִים. דָּבָר אַחֵר: שֶׁהָיְתָה מְעֻבֶּרֶת:\",1,0],[2,137,1,21,\"עָנָה בִי. הֵעִיד עָלַי שֶׁהִרְשַׁעְתִּי לְפָנָיו. דָּבָר אַחֵר: עָנָה בִי מִדַּת הַדִּין, כְּמוֹ \\\"וְעָנָה גְאוֹן יִשְׂרָאֵל\\\":\",2,0],[2,137,1,22,\"בִּתְחִלַּת קְצִיר שְׂעֹרִים. בִּקְצִירַת הָעֹמֶר הַכָּתוּב מְדַבֵּר:\",1,0],[2,137,2,1,\"מוֹדַע. קָרוֹב. בֶּן אָחִיו שֶׁל אֱלִימֶלֶךְ הָיָה. אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, אֱלִימֶלֶךְ וְשַׂלְמוֹן אֲבִי בֹעַז וּפְלֹנִי אַלְמֹנִי הַגּוֹאֵל וַאֲבִי נָעֳמִי כֻּלָּם בְּנֵי נַחְשׁוֹן בֶּן עַמִּינָדָב הָיוּ, וְלֹא הוֹעִילָה לָהֶם זְכוּת אֲבוֹתָם בְּצֵאתָם מֵאֶרֶץ לְחוּצָה לָאָרֶץ:\",1,0],[2,137,2,2,\"אֵלְכָה נָּא הַשָּׂדֶה. לְאֶחָד מִשְּׂדוֹת אַנְשֵׁי הָעִיר אַחֲרֵי אֶחָד מֵהֶם \\\"אֲשֶׁר אֶמְצָא חֵן בְּעֵינָיו\\\", שֶׁלֹּא יִגְעַר בִּי:\",1,0],[2,137,2,2,\"וַאֲלַקְּטָה בַשִּׁבֳּלִים אַחַר אֲשֶׁר אֶמְצָא חֵן בְּעֵינָיו. אַחַר מִי אֲשֶׁר אֶמְצָא חֵן בְּעֵינָיו:\",2,0],[2,137,2,3,\"וַתֵּלֶךְ וַתָּבוֹא וַתְּלַקֵּט בַּשָּׂדֶה. מָצִינוּ בְמִדְרַשׁ רוּת, עַד לָא אֲזָלַת אָתַת? שֶׁהוּא אוֹמֵר \\\"וַתָּבוֹא\\\", וְאַחַר \\\"וַתְּלַקֵּט\\\". אֶלָּא שֶׁהָיְתָה מְסַמֶּנֶת הַדְּרָכִים קֹדֶם שֶׁנִכְנְסָה לַשָּׂדֶה, וְהָלְכָה וּבָאָה וְחָזְרָה לָעִיר כְּדֵי לַעֲשׂוֹת סִמָּנִים וְצִיּוּנִים שֶׁלֹּא תִטְעֶה בַּשְּׁבִילִין וְתֵדַע לָשׁוּב:\",1,0],[2,137,2,3,\"וַיִּקֶר מִקְרֶהָ. לָבֹא בְחֶלְקַת הַשָּׂדֶה אֲשֶׁר לְבֹעַז:\",2,0],[2,137,2,5,\"לְמִי הַנַּעֲרָה הַזֹּאת. וְכִי דַרְכּוֹ שֶׁל בֹּעַז לִשְׁאֹל בְּנָשִׁים? אֶלָּא, דִּבְרֵי צְנִיעוּת וְחָכְמָה רָאָה בָהּ. שְׁתֵּי שִׁבֳּלִים לִקְּטָה, שְׁלשָׁה אֵינָהּ לִקְּטָה. וְהָיְתָה מְלַקֶּטֶת עוֹמְדוֹת מְעֻמָּד וְשׁוֹכְבוֹת מְיֻשָּׁב, כְּדֵי שֶׁלֹּא תִשְׁחֶה:\",1,0],[2,137,2,6,\"הַשָּׁבָה עִם נָעֳמִי. הַטַּעַם לְמַעְלָה תַּחַת הַשִּׁי\\\"ן, לְפִי שֶׁהוּא לְשׁוֹן עָבַר וְאֵינָהּ לְשׁוֹן פּוֹעֶלֶת:\",1,0],[2,137,2,7,\"וַתֹּאמֶר. בְּלִבָּהּ:\",1,0],[2,137,2,7,\"אֲלַקְּטָה נָּא. לֶקֶט הַשִּׁבֳּלִים:\",2,0],[2,137,2,7,\"וְאָסַפְתִּי בָעֳמָרִים. שִׁכְחָה שֶׁל עֳמָרִים:\",3,0],[2,137,2,9,\"וְצָמִת וְהָלַכְתְּ אֶל הַכֵּלִים. וְאִם תִּצְמְאִי אַל תִּכָּלְמִי מִלֶּכֶת וְלִשְׁתּוֹת מִכְּלֵי הַמַּיִם אֲשֶׁר יִשְׁאֲבוּן הַנְּעָרִים:\",1,0],[2,137,2,13,\"לֹא אֶהְיֶה כְּאַחַת שִׁפְחֹתֶךָ. אֵינֶנִּי חֲשׁוּבָה כְּאַחַת מִן הַשְּׁפָחוֹת שֶּׁלְּךָ:\",1,0],[2,137,2,14,\"וְטָבַלְתְּ פִּתֵּךְ בַּחֹמֶץ. מִכַּאן שֶׁהַחֹמֶץ יָפֶה לְשָׁרָב:\",1,0],[2,137,2,14,\"וַיִּצְבָּט לָהּ קָלִי. וַיּוֹשֶׁט לָהּ. וְאֵין לוֹ דִמְיוֹן בַּמִּקְרָא אֶלָּא בִלְשׁוֹן מִשְׁנָה: אֲחוֹרַיִם וְתָוֶךְ וּבֵית הַצְּבִיטָה:\",2,0],[2,137,2,16,\"וְגַם שֹׁל תָּשֹׁלּוּ. שָׁכוֹחַ תִּשְׁכְּחוּ, עֲשׂוּ עַצְמֵיכֶם כְּאִלּוּ אַתֶּם שׁוֹכְחִים. תַּרְגּוּם שֶׁל שְׁגָגָה שְׁלוּתָא, וְכֵן \\\"עַל הַשַּׁל\\\". דָּבָר אַחֵר, לְשׁוֹן \\\"כִּי יִשַּׁל זֵיתֶךָ\\\":\",1,0],[2,137,2,16,\"צְבָתִים. עֳמָרִים קְטַנִּים. וְיֵשׁ דֻּגְמָתוֹ בִּלְשׁוֹן מִשְׁנָה, מְצָאָן צְבָתִים אוֹ כְרִיכוֹת:\",2,0],[2,137,2,19,\"יְהִי מַכִּירֵךְ בָּרוּךְ. בַּעַל הַשָּׂדֶה שֶׁנָּשָׂא וְנָתַן לָךְ פָּנִים לִלְקֹט בְּשָׂדֵהוּ:\",1,0],[2,137,2,20,\"אֶת הַחַיִּים וְאֶת הַמֵּתִים. שֶׁזָּן וּמְפַרְנֵס אֶת הַחַיִּים וְנִטְפָּל בְּצָרְכֵי הַמֵּתִים:\",1,0],[2,137,3,2,\"מֹדַעְתָּנוּ. קְרוֹבֵנוּ:\",1,0],[2,137,3,2,\"הִנֵּה הוּא זֹרֶה. הַמּוֹץ. וונטו\\\"ר בְּלַעַ\\\"ז:\",2,0],[2,137,3,2,\"הַלָּיְלָה. שֶׁהָיָה הַדּוֹר פָּרוּץ בִּגְנֵבָה וְגָזֵל, וְהָיָה יָשֵׁן בְּגָרְנוֹ לִשְׁמֹר גָּרְנוֹ:\",3,0],[2,137,3,3,\"וְרָחַצְתְּ. מִטִּנּוּף עֲבוֹדַת כּוֹכָבִים שֶׁלָּךְ:\",1,0],[2,137,3,3,\"וָסַכְתְּ. אֵלּוּ מִצְוֹת:\",2,0],[2,137,3,3,\"וְשַׂמְתְּ שִׂמְלֹתַיִךְ. בְּגָדִים שֶׁל שַׁבָּת:\",3,0],[2,137,3,3,\"וְיָרַדְתְּ הַגֹּרֶן. וְיָרַדְתִּי כְּתִיב זְכוּתִי תֵרֵד עִמָּךְ:\",4,0],[2,137,3,3,\"אַל תִּוָּדְעִי לָאִישׁ. לְבֹעַז:\",5,0],[2,137,3,6,\"וַתֵּרֶד הַגֹּרֶן וַתַּעַשׂ. הִיא אָמְרָה לָהּ \\\"וְרָחַצְתְּ וָסַכְתְּ וְשַׂמְתְּ שִׂמְלוֹתַיִךְ עָלַיִךְ\\\", וְאַחַר כָּךְ \\\"וְיָרַדְתְּ הַגֹּרֶן. וְהִיא לֹא עָשְׂתָה כֵן. אֶלָּא אָמְרָה, \\\"אִם אֵרֵד כְּשֶׁאֲנִי מְקֻשֶּׁטֶת, הַפּוֹגֵעַ בִּי וְהָרוֹאֶה אוֹתִי יֹאמַר שֶׁאֲנִי זוֹנָה\\\". לְפִיכָךְ, יָרְדָה בַתְּחִלָּה הַגֹּרֶן וְאַחַר כָּךְ קִשְּׁטָה אֶת עַצְמָהּ כַּאֲשֶׁר צִוַּתָּהּ חֲמוֹתָהּ:\",1,0],[2,137,3,7,\"וַיִּיטַב לִבּוֹ. עָסַק בַּתּוֹרָה:\",1,0],[2,137,3,7,\"וַתָּבֹא בַלָּט. בְּנַחַת:\",2,0],[2,137,3,8,\"וַיֶּחֱרַד הָאִישׁ. כְּסָבוּר שֵׁד הוּא וּבִקֵּשׁ לִזְעֹק, וְהִיא אֲחָזַתּוּ וּלְפָפַתּוּ בִּזְרוֹעוֹתֶיהָ:\",1,0],[2,137,3,8,\"וַיִּלָּפֵת. וַיֵּאָחֵז כְּמוֹ וַיִּלְפֹּת שִׁמְשׁוֹן:\",2,0],[2,137,3,8,\"וְהִנֵּה אִשָּׁה. נָתַן יָדוֹ עַל רֹאשָׁהּ וְהִכִּיר שֶׁהִיא אִשָּׁה:\",3,0],[2,137,3,9,\"וּפְָרַשְׂתָּ כְנָפֶךָ. כְּנַף בִּגְדְּךָ לְכַסּוֹתִי בְטַלִּיתְךָ וְהוּא לְשׁוֹן נִשּׂוּאִין:\",1,0],[2,137,3,9,\"כִּי גֹאֵל אָתָּה. לִגְאֹל נַחֲלַת אִישִׁי כְּמוֹ שֶׁנֶּאֱמַר, \\\"וּבָא גוֹאֲלוֹ הַקָּרוֹב אֵלָיו וְגָאַל וגו'\\\". וַחֲמוֹתִי וַאֲנִי צְרִיכוֹת לִמְכֹּר נַחֲלָתֵנוּ, וְעַתָּה עָלֶיךָ לִקְנוֹת. קְנֵה גַם אוֹתִי עִמָּהּ שֶׁיִּזָּכֵר שֵׁם הַמֵּת עַל נַחֲלָתוֹ, כְּשֶׁאָבֹא עַל הַשָּׂדֶה יֹאמְרוּ \\\"זֹאת אֵשֶׁת מַחְלוֹן\\\":\",2,0],[2,137,3,10,\"מִן הָרִאשׁוֹן. אֲשֶׁר עָשִׂית עִם חֲמוֹתֵךְ:\",1,0],[2,137,3,12,\"וְעַתָּה כִּי אָמְנָם כִּי. אִם כְּתִיב וְלֹא קְרִי. כְּלוֹמַר, מַשְׁמַע סָפֵק וַדַּאי יֵשׁ גּוֹאֵל קָרוֹב מִמֶּנִּי. (סְפָרִים אַחֵרִים: \\\"כִּי אִם\\\" מַשְׁמַע סָפֵק וְהוּא וַדַּאי.) אָמַר רַבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, שַׂלְמוֹן וֶאֱלִימֶלֶךְ וְטוֹב אַחִים הָיוּ. וּמַהוּ \\\"אֲשֶׁר לְאָחִינוּ לֶאֱלִימֶלֶךְ\\\"? לְעוֹלָם קוֹרֵא אָדָם אֶת דּוֹדוֹ אָחִיו, כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"וַיִּשְׁמַע אַבְרָם כִּי נִשְׁבָּה אָחִיו\\\". וַהֲלֹא אַבְרָהָם דּוֹדוֹ הָיָה? כָּךְ הָיָה בֹעַז לֶאֱלִימֶלֶךְ בֶּן אָחִיו, קְרוֹבוֹ שֶׁל מַחְלוֹן, אֲבָל טוֹב הָיָה קָרוֹב יוֹתֵר:\",1,0],[2,137,3,12,\"קָרוֹב מִמֶּנִּי. שֶׁהוּא אָח וַאֲנִי בֶן אָח:\",2,0],[2,137,3,13,\"לִינִי הַלַּיְלָה. לִינִי בְלֹא אִישׁ:\",1,0],[2,137,3,13,\"חַי ה'. אָמְרָה לוֹ \\\"בִּדְבָרִים אַתָּה מוֹצִיאֵנִי\\\". קָפַץ וְנִשְׁבַּע לָהּ שֶׁאֵינוֹ מוֹצִיאָהּ בִּדְבָרִים. וְיֵשׁ מֵרַבּוֹתֵינוּ אָמְרוּ, \\\"לְיִצְרוֹ נִשְׁבַּע, שֶׁהָיָה יִצְרוֹ מְקַטְרְגוֹ, אַתָּה פָנוּי וְהִיא פְנוּיָה, בֹּא עָלֶיהָ\\\". וְנִשְׁבַּע שֶׁלֹּא יָבֹא עָלֶיהָ אֶלָּא עַל יְדֵי נִשּׂוּאִין:\",2,0],[2,137,3,14,\"וַיֹּאמֶר אַל יִוָּדַע. מוּסָב עַל \\\"וַתָּקָם בְּטֶרֶם יַכִּיר\\\". הוּא זֵרְזָהּ לָקוּם, כִּי אָמַר בְּלִבּוֹ, \\\"אֵין כְּבוֹדִי שֶׁיִּוָּדַע כִּי בָאָה הָאִשָּׁה הַגֹּרֶן:\",1,0],[2,137,3,15,\"שֵׁשׁ שְׂעֹרִים. אִי אֶפְשַׁר לוֹמַר שֵׁשׁ סְאִין, שֶׁאֵין דַּרְכָּהּ שֶׁל אִשָּׁה לָשֵׂאת כְּמַשּׂאוֹי זֶה, אֶלָּא שֵׁשׁ שְׂעוֹרִים מַמָּשׁ. וְרָמַז לָהּ שֶׁעָתִיד לָצֵאת מִמֶּנָּה בֵּן שֶׁמִּתְבָּרֵךְ בְּשֵׁשׁ בְּרָכוֹת: \\\"רוּחַ חָכְמָה וּבִינָה, עֵצָה וּגְבוּרָה, רוּחַ דַּעַת וְיִרְאַת ה'\\\":\",1,0],[2,137,3,18,\"כִּי אִם כִּלָּה. הָאִישׁ אֶת הַדָּבָר הַיּוֹם:\",1,0],[2,137,4,1,\"פְּלֹנִי אַלְמֹנִי. וְלֹא נִכְתַּב שְׁמוֹ לְפִי שֶׁלֹּא אָבָה לִגְאֹל:\",1,0],[2,137,4,1,\"פְּלֹנִי אַלְמֹנִי. מְתֻרְגָּם בַּנְּבִיאִים \\\"כַּסִּי וְטָמִיר\\\":\",2,0],[2,137,4,1,\"פְּלֹנִי. מְכֻסֶּה וְנֶעְלָם לְשׁוֹן \\\"כִּי יִפָּלֵא\\\", \\\"הֲיִפָּלֵא מֵהַ' דָּבָר\\\":\",3,0],[2,137,4,1,\"אַלְמֹנִי. אַלְמוֹן מִבְּלִי שֵׁם. (סְפָרִים אֲחֵרִים, אַלְמֹנִי שֶׁהָיָה אַלְמָן מִדִּבְרֵי תוֹרָה, שֶׁהָיָה לוֹ לִדְרשׁ, עַמּוֹנִי וְלֹא עַמּוֹנִית, מוֹאָבִי וְלֹא מוֹאָבִית וְהוּא אָמַר, \\\"פֶּן אַשְׁחִית אֶת נַחֲלָתִי\\\":)\",4,0],[2,137,4,4,\"וְאֵדְעָה כִּי אֵין זוּלָתְךָ. קָרוֹב לִגְאוֹל:\",1,0],[2,137,4,5,\"וּמֵאֵת רוּת הַמּוֹאֲבִיָּה. אַתָּה צָרִיךְ לִקְנוֹת, וְהִיא אֵינָהּ מִתְרַצָּה אֶלָּא אִם כֵּן תִּשָּׂאֶנָּה:\",1,0],[2,137,4,6,\"פֶּן אַשְׁחִית אֶת נַחֲלָתִי. זַרְעִי. כְּמוֹ \\\"נַחֲלַת ה' בָּנִים\\\". לָתֵת פְּגַם בְּזַרְעִי, שֶׁנֶּאֱמַר, \\\"לֹא יָבֹא עַמּוֹנִי וּמוֹאָבִי\\\". וְטָעָה בְּ\\\"עַמּוֹנִי וְלֹא עַמּוֹנִית\\\":\",1,0],[2,137,4,7,\"עַל הַגְּאוּלָּה. זוּ מְכִירָה:\",1,0],[2,137,4,7,\"תְּמוּרָה. זוּ חֲלִיפִין:\",2,0],[2,137,4,7,\"שָׁלַף אִישׁ נַעֲלוֹ. זֶהוּ קִנְיָן. כְּמוֹ שֶׁאָנוּ קוֹנִין בְּסוּדָר בִּמְקוֹם נַעַל. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה נֶחְלְקוּ בַדָּבָר, מִי נָתַן לְמִי. יֵשׁ אוֹמְרִים קוֹנִין בְּכֶלְיוֹ שֶׁל קוֹנֶה וּבֹעַז נָתַן לַגּוֹאֵל, וְיֵשׁ אוֹמְרִים קוֹנִין בְּכֶלְיוֹ שֶׁל מַקְנֶה וְגוֹאֵל נָתַן לְבֹעַז:\",3,0],[2,137,4,7,\"וְזֹאת הַתְּעוּדָה בְּיִשְׂרָאֵל. מִשְׁפַּט הָעֵדוּת:\",4,0],[2,137,4,10,\"לְהָקִים שֵׁם הַמֵּת עַל נַחֲלָתוֹ. מִתּוֹךְ שֶׁאִשְׁתּוֹ יוֹצְאָה וּבָאָה בַּנַּחֲלָה, וּמַכְנֶסֶת וּמוֹצִיאָה, אוֹמְרִים \\\"זֹאת הָיְתָה אֵשֶׁת מַחְלוֹן\\\", וּשְׁמוֹ נִזְכָּר עָלֶיהָ:\",1,0],[2,137,4,11,\"כְּרָחֵל וּכְלֵאָה. אַף עַל פִּי שֶׁהָיוּ מִשֵּׁבֶט יְהוּדָה וּמִבְּנֵי לֵאָה, מוֹדִים הֵם עַל רָחֵל שֶׁהָיְתָה עִקָּרָהּ שֶׁל בַּיִת, וְהִקְדִּימוּ רָחֵל לְלֵאָה:\",1,0],[2,137,4,11,\"וּקְרָא שֵׁם. כְּלוֹמַר, \\\"יִגְדַּל שְׁמֶךָ\\\":\",2,0],[2,137,4,12,\"כְּבֵית פֶּרֶץ. שֶׁיָּצְאוּ מִמֶּנּוּ:\",1,0],[2,137,4,18,\"וְאֵלֶּה תּוֹלְדוֹת פָּרֶץ. לְפִי שֶׁיִּחֵס אֶת דָּוִד עַל שְׁמָהּ שֶׁל רוּת הַמּוֹאֲבִיָּה חָזַר וְיִחֲסוֹ עַל שֵׁם יְהוּדָה:\",1,0],[2,138,1,1,\"אחת דיבר אלהים, שתים זו שמעתי (תהלים סב יב). מקרא אחד יוצא לכמה טעמים, וסוף דבר אין לך מקרא יוצא מידי פשוטו ומשמעו. ואף על פי שדיברו הנביאים דבריהם בדוגמא, צריך ליישב הדוגמא על אופניה ועל סדרה, כמו שהמקראות סדורים זה אחר זה.\",1,0],[2,138,1,1,\"וראיתי לספר הזה כמה מדרשי אגדה: יש סודרים כל הספר הזה במדרש אחד; ויש מפוזרים בכמה מדרשי אגדה מקראות לבדם, ואינם מתיישבים על לשון המקרא וסדר המקראות. ואמרתי בלבי לתפוש משמעות המקרא ליישב ביאורם על סדרם, והמדרשות מרבותינו אקבעם מדרש ומדרש, איש איש במקומו.\",2,0],[2,138,1,1,\"ואומר אני, שראה שלמה ברוח הקודש שעתידין ישראל לגלות גולה אחר גולה, חורבן אחר חורבן, ולהתאונן בגלות זה על כבודם הראשון, ולזכור חיבה ראשונה אשר היו סגולה לו מכל העמים לאמר (הושע ב ז) אלכה ואשובה אל אישי הראשון כי טוב לי אז מעתה, ויזכרו את חסדיו ואת מעלם אשר מעלו, ואת הטובות אשר אמר לתת להם באחרית הימים. ויסד הספר הזה ברוח הקודש, בלשון אשה צרורה אלמנות חיות, משתוקקת על בעלה, מתרפקת על דודה, מזכרת אהבת נעוריה אליו, ומודה על פשעה. אף דודה, צר לו בצרתה, ומזכיר חסדי נעוריה ונוי יופיה וכשרון פעליה, בהם נקשר עימה באהבה עזה, להודיעה כי לא מלבו ענה, ולא שילוחיה שילוחין, כי עוד היא אשתו והוא אישה, והוא עתיד לשוב אליה.\",3,0],[2,138,1,1,\"שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה. שָׁנוּ רַבּוֹתֵינוּ: \\\"כָּל שְׁלֹמֹה (דְּקָשֶׁה לָהֶם לָמָּה לֹא מְיַחֲסוֹ אַחַר אָבִיו כְּמוֹ בְמִשְׁלֵי וְקֹהֶלֶת) הָאֲמוּרִים בְּשִׁיר הַשִּׁירִים קֹדֶשׁ, מֶלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ\\\". שִׁיר שֶׁהוּא עַל כָּל הַשִּׁירִים, אֲשֶׁר נֶאֱמַר לְהַקָּדוֹשׁ בָּרוּךְ הוּא מֵאֵת עֲדָתוֹ וְעַמּוֹ, כְּנֶסֶת יִשְׂרָאֵל. אָמַר רַבִּי עֲקִיבָא: \\\"לֹא הָיָה הָעוֹלָם כְּדַאי כַּיּוֹם שֶׁנִּתַּן בּוֹ שִׁיר הַשִּׁירִים לְיִשְׂרָאֵל, שֶׁכָּל הַכְּתוּבִים קֹדֶשׁ וְשִׁיר הַשִּׁירִים קֹדֶשׁ קָדָשִׁים\\\". אָמַר רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה: \\\"לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁנָּטַל סְאָה חִטִּים וּנְתָנָהּ לְנַחְתּוֹם. אָמַר לוֹ: 'הוֹצֵא לִי כָךְ וְכָךְ סֹלֶת, כָּךְ וְכָךְ סֻבִּין, כָּךְ וְכָךְ מֻרְסָן, וְסָלִיתָ לִי מִתּוֹכָהּ גְּלֻסְקִיָּא אַחַת, מְנֻפָּה וּמְעֻלָּה'. כָּךְ, כָּל הַכְּתוּבִים קֹדֶשׁ, וְשִׁיר הַשִּׁירִים קֹדֶשׁ קָדָשִׁים, שֶׁכֻּלּוֹ יִרְאַת שָׁמַיִם וְקִבּוּל עֹל מַלְכוּתוֹ\\\":\",4,0],[2,138,1,2,\"יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. זֶה הַשִּׁיר אוֹמֶרֶת בְּפִיהָ בְּגָלוּתָהּ וּבְאַלְמְנוּתָהּ: \\\"מִי יִתֵּן וְיִשָּׁקֵנִי הַמֶּלֶךְ שְׁלֹמֹה מִנְּשִׁיקוֹת פִּיהוּ כְּמוֹ מֵאָז, לְפִי שֶׁיֵּשׁ מְקוֹמוֹת שֶׁנּוֹשְׁקִין עַל גַּב הַיָּד וְעַל הַכָּתֵף, אַךְ אֲנִי מִתְאַוָּה וְשׁוֹקֶקֶת לִהְיוֹתוֹ נוֹהֵג עִמִּי כַמִּנְהָג הָרִאשׁוֹן, כְּחָתָן אֶל כַּלָּה, פֶּה אֶל פֶּה\\\":\",1,0],[2,138,1,2,\"כִּי טוֹבִים. לִי דוֹדֶיךָ מִכָּל מִשְׁתֵּה יַיִן וּמִכָּל עֹנֶג וְשִׂמְחָה. וְלָשׁוֹן עִבְרִי הוּא לִהְיוֹת כָּל סְעֻדַּת עֹנֶג וְשִׂמְחָה נִקְרֵאת עַל שֵׁם הַיַּיִן, כְּעִנְיָן שֶׁנֶּאֱמַר \\\"אֶל בֵּית מִשְׁתֵּה הַיַּיִן\\\", \\\"בַּשִּׁיר לֹא יִשְׁתּוּ יָיִן\\\", \\\"וְהָיָה כִנּוֹר וָנֶבֶל תֹּף וְחָלִיל וָיַיִן מִשְׁתֵּיהֶם\\\". זֶהוּ בֵאוּר מַשְׁמָעוֹ. וְנֶאֱמַר דֻּגְמָא שֶׁלּוֹ עַל שֵׁם שֶׁנָּתַן לָהֶם תּוֹרָתוֹ וְדִבֵּר עִמָּהֶם פָּנִים אֶל פָּנִים. וְאוֹתָם דּוֹדִים עוֹדָם עֲרֵבִים עֲלֵיהֶם מִכָּל שַׁעֲשׁוּעַ. וּמֻבְטָחִים מֵאִתּוֹ לְהוֹפִיעַ עוֹד עֲלֵיהֶם לְבָאֵר לָהֶם סוֹד טְעָמֶיהָ וּמִסְתַּר צְפוּנוֹתֶיהָ, וּמְחַלִּים פָּנָיו לְקַיֵּם דְּבָרוֹ. וְזֶהוּ: \\\"יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ\\\":\",2,0],[2,138,1,3,\"לְרֵיחַ שְׁמָנֶיךָ טוֹבִים. שֵׁם טוֹב נִקְרָא עַל שֵׁם 'שֶׁמֶן טוֹב':\",1,0],[2,138,1,3,\"לְרֵיחַ שְׁמָנֶיךָ טוֹבִים. שֶׁהֵרִיחוּ בָהֶם אַפְסֵי אֶרֶץ אֲשֶׁר שָׁמְעוּ שִׁמְעֲךָ הַטּוֹב בַּעֲשׂוֹתְךָ נוֹרָאוֹת בְּמִצְרָיִם:\",2,0],[2,138,1,3,\"שֶׁמֶן תּוּרַק. נִקְרָא שְׁמֶךָ, לִהְיוֹת נֶאֱמַר עָלֶיךָ, \\\"אַתָּה שֶׁמֶן אֲשֶׁר תּוּרַק תָּמִיד לִהְיוֹת רֵיחַ עָרֵב שֶׁלְּךָ יוֹצֵא לְמֵרָחוֹק\\\", שֶׁכֵּן דֶּרֶךְ שֶׁמֶן עָרֵב, בְּכָל עֵת שֶׁהוּא בִצְלוֹחִית חֲתוּמָה, אֵין רֵיחוֹ נוֹדֵף, פּוֹתְחָהּ וּמֵרִיק שַׁמְנָהּ לִכְלִי אַחֵר, רֵיחוֹ נוֹדֵף:\",3,0],[2,138,1,3,\"עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. בָּא יִתְרוֹ לְקוֹל הַשְּׁמוּעָה וְנִתְגַּיֵּר. אַף רָחָב הַזּוֹנָה אָמְרָה \\\"כִּי שָׁמַעְנוּ אֵת אֲשֶׁר הוֹבִישׁ וגו'\\\", וְעַל יְדֵי כֵן \\\"כִּי ה' אֱלֹהֵיכֶם הוּא אֱלֹהִים בַּשָּׁמַיִם וגו'\\\":\",4,0],[2,138,1,3,\"עֲלָמוֹת. בְּתוּלוֹת, לְפִי שֶׁהַדִּבּוּר דִּמָּהוּ לְבָחוּר שֶׁאֲהוּבָתוֹ מְחַבַּבְתּוֹ. וּלְפִי הַדֻּגְמָא: הָ\\\"עֲלָמוֹת\\\" הֵן הָאֻמּוֹת:\",5,0],[2,138,1,4,\"מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה. אֲנִי שָׁמַעְתִּי מִשְּׁלוּחֶיךָ רֶמֶז שֶׁאָמַרְתָּ לְמָשְׁכֵנִי, וַאֲנִי אָמַרְתִּי, \\\"אַחֲרֶיךָ נָרוּצָה\\\" לִהְיוֹת לְךָ לְאִשָּׁה:\",1,0],[2,138,1,4,\"הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו. וְגַם הַיּוֹם הַזֶּה, עוֹדֶנָּה לִי גִילָה וְשִׂמְחָה אֲשֶׁר נִדְבַּקְתִּי בָךְ:\",2,0],[2,138,1,4,\"נַזְכִּירָה דֹדֶיךָ. גַּם הַיּוֹם בְּאַלְמְנוּת חַיּוּת, תָּמִיד אַזְכִּיר דּוֹדֶיךָ הָרִאשׁוֹנִים מִכָּל מִשְׁתֵּה עֹנֶג וְשִׂמְחָה:\",3,0],[2,138,1,4,\"מֵישָׁרִים אֲהֵבוּךָ. אַהֲבָה עַזָּה, אַהֲבַת מִישׁוֹר בְּלִי עֲקִיבָה וּרְכָסִים (לְשׁוֹן פָּסוּק \\\"וְהָיָה הֶעָקֹב לְמִישׁוֹר וְהָרְכָסִים לְבִקְעָה\\\"). אֲשֶׁר 'אֲהֵבוּךָ' אֲנִי וַאֲבוֹתַי בְּאוֹתָן הַיָּמִים. זֶהוּ פְשׁוּטוֹ לְפִי עִנְיָנוֹ. וּלְפִי דֻגְמָתוֹ, הֵם מַזְכִּירִים לְפָנָיו חֶסֶד נְעוּרִים, אַהֲבַת כְּלוּלוֹת, לֶכְתָּם אַחֲרָיו בַּמִּדְבָּר, אֶרֶץ צִיָּה וְצַלְמָוֶת, וְגַם צֵדָה לֹא עָשׂוּ לָהֶם, וְהֶאֱמִינוּ בוֹ וּבִשְׁלוּחוֹ, וְלֹא אָמְרוּ: \\\"הֵיאַךְ נֵצֵא לַמִּדְבָּר, לֹא מְקוֹם זֶרַע וּמְזוֹנוֹת\\\"? וְהָלְכוּ אַחֲרָיו, וְהוּא הֱבִיאָם לְתוֹךְ חַדְרֵי הֶקֵּף עֲנָנָיו. בְּזוּ, עוֹדָם הַיּוֹם גָּלִים וּשְׂמֵחִים בּוֹ אַף לְפִי עָנְיָם וְצָרָתָם, וּמִשְׁתַּעְשְׁעִים בַּתּוֹרָה, וְשָׁם מַזְכִּירִים דּוֹדָיו מִיַּיִן וּמִישׁוֹר אַהֲבָתָם אוֹתוֹ:\",4,0],[2,138,1,5,\"שְׁחוֹרָה אֲנִי וְנָאוָה וגו'. אַתֶּם רַעְיוֹתַי, אַל אֵקַל בְּעֵינֵיכֶם אַף אִם עֲזָבַנִי אִישִׁי מִפְּנֵי שַׁחֲרוּת שֶׁבִּי, כִּי שְׁחוֹרָה אֲנִי עַל יְדֵי שְׁזִיפַת הַשֶּׁמֶשׁ, וְנָאוָה אֲנִי בְחִתּוּךְ אֵבָרִים נָאִים. אִם אֲנִי שְׁחוֹרָה כְּאָהֳלֵי קֵדָר הַמַּשְׁחִירִים מִפְּנֵי הַגְּשָׁמִים, שֶׁהֵם פְּרוּסִים תָּמִיד בַּמִּדְבָּרוֹת, קַלָּה אֲנִי לְהִתְכַּבֵּס לִהְיוֹת כִּירִיעוֹת שְׁלֹמֹה. דֻּגְמָא הִיא זוּ: אוֹמֶרֶת כְּנֶסֶת יִשְׂרָאֵל לָאֻמּוֹת: \\\"שְׁחוֹרָה אֲנִי בְמַעֲשַׂי וְנָאָה אֲנִי בְמַעֲשֵׂה אֲבוֹתַי, וְאַף בְּמַעֲשַׂי, יֵשׁ מֵהֶם נָאִים, אִם יֵשׁ בִּי עֲוֹן הָעֵגֶל, יֵשׁ בִּי כְנֶגְדּוֹ זְכוּת קַבָּלַת הַתּוֹרָה\\\". וְקוֹרֵא לָאֻמּוֹת \\\"בְּנוֹת יְרוּשָׁלַיִם\\\" עַל שֵׁם שֶׁהִיא עֲתִידָה לֵעָשׂוֹת מֶטְרוֹפּוֹלִין לְכֻלָּן, כְּמוֹ שֶׁנִּבָּא יְחֶזְקֵאל \\\"וְנָתַתִּי אֶתְהֶן לָךְ לְבָנוֹת\\\", כְּמוֹ \\\"עֶקְרוֹן וּבְנֹתֶיהָ\\\":\",1,0],[2,138,1,6,\"אַל תִּרְאֻנִי. אַל תִּסְתַּכְּלוּ בִי לְבִזָּיוֹן כְּמוֹ \\\"כִּי רָאוּ בַּאֲרוֹן ה'\\\":\",1,0],[2,138,1,6,\"שֶׁאֲנִי שְׁחַרְחֹרֶת. לְפִי שֶׁאֵין שַׁחֲרוּתִי וְכִעוּרִי מִמְּעֵי אִמִּי, אֶלָּא עַל יְדֵי שְׁזִיפַת הַשֶּׁמֶשׁ, שֶׁאוֹתוֹ שַׁחֲרוּת נוֹחַ לְהִתְלַבֵּן כְּשֶׁיַּעֲמֹד בַּצֵּל:\",2,0],[2,138,1,6,\"בְּנֵי אִמִּי נִחֲרוּ בִי. הֵם בְּנֵי מִצְרַיִם שֶׁגָּדַלְתִּי בָהֶם, וְעָלוּ עִמִּי בְעֵרֶב רַב, הֵם נִחֲרוּ בִי בַהֲסָתָתָם וּפִתּוּיָם עַד שֶׁשָׂמוּנִי,\",3,0],[2,138,1,6,\"נֹטֵרָה אֶת הַכְּרָמִים. וְשָׁם שְׁזָפַתְנִי הַשֶּׁמֶשׁ וְהֻשְׁחַרְתִּי, כְּלוֹמַר: נְתָנוּנִי עוֹבֶדֶת אֱלֹהִים אֲחֵרִים, וְכַרְמִי שֶׁהָיָה שֶׁלִּי מֵאֲבוֹתַי, לֹא נָטָרְתִּי. מָצִינוּ פַּרְנָסִים נִקְרָאִים בַּמִּקְרָא בִּלְשׁוֹן \\\"כְּרָמִים\\\", שֶׁנֶּאֱמַר \\\"וְנָתַתִּי לָהּ אֶת כְּרָמֶיהָ מִשָּׁם\\\" וּמְתַרְגְּמִינָן: \\\"וַאֲמַנֵּי לָהּ יַת פַּרְנָסָהָא\\\", וְכֵן \\\"לֹא יִפְנֶה דֶרֶךְ כְּרָמִים\\\":\",4,0],[2,138,1,7,\"הַגִּידָה לִּי שֶׁאָהֲבָה נַפְשִׁי. עַכְשָׁיו רוּחַ הַקֹּדֶשׁ חוֹזֵר וּמְדַמֶּה אוֹתָהּ לְצֹאן הַחֲבִיבָה עַל הָרוֹעֶה. אוֹמֶרֶת כְּנֶסֶת יִשְׂרָאֵל לְפָנָיו כְּאִשָּׁה לְבַעְלָהּ: \\\"הַגִּידָה לִּי שֶׁאָהֲבָה נַפְשִׁי אֵיכָה תִרְעֶה צֹאנְךָ בֵּין הַזְּאֵבִים הַלָּלוּ אֲשֶׁר הֵם בְּתוֹכָם, וְאֵיכָה תַּרְבִּיצֵם בַּצָּהֳרָיִם\\\" בַּגָּלוּת הַזֶּה, שֶׁהִיא עֵת צָרָה לָהֶם כַּצָּהֳרַיִם שֶׁהִיא עֵת צָרָה לַצֹּאן\\\"?\",1,0],[2,138,1,7,\"שַׁלָּמָה אֶהְיֶה כְּעֹטְיָה. \\\"וְאִם תּאמַר: \\\"מָה אִכְפַּת לָךְ\\\"? אֵין זֶה כְבוֹדְךָ שֶׁאֶהְיֶה כַאֲבֵלָה עוֹטָה עַל שָׂפָה, בּוֹכִיָּה עַל צֹאנִי\\\":\",2,0],[2,138,1,7,\"עַל עֶדְרֵי חֲבֵרֶיךָ. אֵצֶל עֶדְרֵי שְׁאָר הָרוֹעִים שֶׁהֵם רוֹעִים צֹאן כְּמוֹתְךָ, כְּלוֹמַר: בֵּין גְּדוּדֵי הָאֻמּוֹת הַסְּמוּכִים עַל אֱלֹהִים אֲחֵרִים וְיֵשׁ לָהֶם מְלָכִים וְשָׂרִים מַנְהִיגִים אוֹתָם:\",3,0],[2,138,1,8,\"אִם לֹא תֵדְעִי לָךְ. זוּ הִיא תְשׁוּבַת הָרוֹעֶה: \\\"אִם לֹא תֵדְעִי לָךְ לְהֵיכָן תֵּלְכִי לִרְעוֹת צֹאנֵךְ, אַתְּ הַיָּפָה בַּנָּשִׁים, שֶׁחָדַל הָרוֹעֶה מִלְּהַנְהִיג אוֹתָם:\",1,0],[2,138,1,8,\"צְאִי לָךְ בְּעִקְבֵי הַצֹּאן. הִסְתַּכְּלִי בִפְסִיעוֹת דֶּרֶךְ שֶׁהָלְכוּ הַצֹּאן, וְהָעֲקֵבִים נִכָּרִים, טראצי\\\"ט בְּלַעַ\\\"ז, וְכֵן הַרְבֵּה בַמִּקְרָא, \\\"וְעִקְּבוֹתֶיךָ לֹא נוֹדָעוּ\\\", \\\"נֶחְמְסוּ עֲקֵבָיִךְ\\\", \\\"וְהוּא יָגֻד עָקֵב\\\", יָשׁוּב עַל עֲקֵבָיו. וְאוֹתוֹ הַדֶּרֶךְ לֵכִי: וּרְעִי אֶת גְּדִיֹּתַיִךְ\",2,0],[2,138,1,8,\"עַל מִשְׁכְּנוֹת הָרֹעִים. בֵּין מִשְׁכְּנוֹת שְׁאָר הָרוֹעִים שֶׁאַתְּ אֶצְלָם. וְזֶה הַדֻּגְמָא: אִם לֹא תֵדְעִי לָךְ, כְּנֵסִיָּתִי וַעֲדָתִי, הַיָּפָה בַּנָּשִׁים, בִּשְׁאָר אֻמּוֹת, אֵיכָה תִרְעִי וְתִנָּצְלִי מִיַּד הַמְּצִיקִים לָךְ לִהְיוֹת בֵּינֵיהֶם וְלֹא יֹאבְדוּ בָנַיִךְ, הִתְבּוֹנְנִי בְּדַרְכֵי אֲבוֹתַיִךְ הָרִאשׁוֹנִים שֶׁקִּבְּלוּ תוֹרָתִי וְשָׁמְרוּ מִשְׁמַרְתִּי וּמִצְוֹתַי, וּלְכִי בְדַרְכֵיהֶם. וְאַף בִּשְׂכַר זֹאת תִּרְעִי גְדִיּוֹתַיִךְ אֵצֶל שָׂרֵי הָאֻמּוֹת. וְכֵן אָמַר יִרְמְיָה \\\"הַצִּיבִי לָךְ צִיֻּנִים. . . שִׁתִי לִבֵּךְ לַמְסִלָּה וגו'\\\":\",3,0],[2,138,1,9,\"לְסֻסָתִי בְּרִכְבֵי פַרְעֹה דִּמִּיתִיךְ רַעְיָתִי. למ\\\"ד זוֹ כְּמוֹ למ\\\"ד \\\"לְקוֹל תִּתּוֹ הֲמוֹן מַיִם\\\" וּכְמוֹ למ\\\"ד \\\"לְרֵיחַ שְׁמָנֶיךָ\\\". לִקְבוּצַת סוּסִים הַרְבֵּה שֶׁאָסַפְתִּי מַחֲנוֹתַי לָצֵאת לִקְרָאתֵךְ בְּרִכְבֵי פַרְעֹה לְהוֹשִׁיעֵךְ, כְּמוֹ שֶׁנֶּאֱמַר \\\"דָּרַכְתָּ בַיָּם סוּסֶיךָ\\\", סוּסִים הַרְבֵּה. שָׁם 'דִּמִּיתִיךְ רַעְיָתִי', שִׁתַּקְתִּיךְ מִצַּעֲקָתֵךְ, שֶׁנֶּאֱמַר \\\"וְאַתֶּם תַּחֲרִשׁוּן\\\". זֹאת רָאִיתִי בְּסִפְרֵי אַגָּדָה. דָּבָר אַחֵר: דִּמִּיתִיךְ רַעְיָתִי. שָׁם הֶרְאֵיתִי לַכֹּל שֶׁרַעְיָתִי אַתְּ:\",1,0],[2,138,1,9,\"לְסֻסָתִי. קְבוּצַת סוּסִים וּבִלְשׁוֹן לַעַ\\\"ז קבלייש\\\"א:\",2,0],[2,138,1,9,\"דִּמִּיתִיךְ. אדישמא\\\"י בְּלַעַ\\\"ז כְּמוֹ \\\"אוֹתִי דִּמּוּ לַהֲרֹג\\\", כִּי שָׁם קִּשַּׁטְתִּיךְ בְּקִשּׁוּטִים נָאִים:\",3,0],[2,138,1,10,\"נָאווּ לְחָיַיִךְ בַּתּוֹרִים. שׁוּרוֹת נִזְמֵי אֹזֶן וּמִצְחַת זָהָב:\",1,0],[2,138,1,10,\"צַוָּארֵךְ בַּחֲרוּזִים. עֲנָקֵי זָהָב וּמַרְגָּלִיּוֹת חֲרוּזוֹת בִּפְתִילֵי זָהָב שֶׁל בִּזַּת הַיָּם:\",2,0],[2,138,1,11,\"תּוֹרֵי זָהָב נַעֲשֶׂה לָּךְ. נִמְלַכְנוּ אֲנִי וּבֵית דִּינִי לִפְנֵי בֹא פַרְעֹה, שֶׁאַשִּׁיאֶנּוּ וַאֲחַזֵּק אֶת לִבּוֹ לִרְדֹּף אַחֲרַיִךְ עִם כָּל שֶׁבַח גִּנְזֵי אוֹצְרוֹתָיו, כְּדֵי שֶׁנַּעֲשֶׂה לָךְ תּוֹרֵי קִשּׁוּטֵי הַזָּהָב:\",1,0],[2,138,1,11,\"עִם נְקֻדּוֹת הַכָּסֶף. שֶׁהָיָה בְיָדֵךְ כְּבָר, שֶׁהוֹצֵאת מִמִּצְרַיִם, שֶׁגְּדוֹלָה הָיְתָה בִזַּת הַיָּם מִבִּזַּת מִצְרָיִם:\",2,0],[2,138,1,11,\"נְקֻדּוֹת. כְּלֵי כֶסֶף מְנֻקָּדִים וּמְצֻיָּרִים בַּחֲבַרְבּוּרוֹת וְגַוָּנִים:\",3,0],[2,138,1,12,\"עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ. מְשִׁיבָה כְנֶסֶת יִשְׂרָאֵל וְאוֹמֶרֶת: \\\"כָּל זֶה אֱמֶת, טוֹבָה גְמַלְתַּנִי וַאֲנִי גְמַלְתִּיךָ רָעָה, כִּי בְעוֹד הַמֶּלֶךְ עַל הַשֻּׁלְחָן מְסִבַּת חֻפָּתוֹ,\",1,0],[2,138,1,12,\"נִרְדִּי נָתַן רֵיחוֹ. חִלּוּף לְהַבְאִישׁ, בְּעוֹד שֶׁהַשְּׁכִינָה בְסִינַי, קִלְקַלְתִּי בָעֵגֶל\\\". וּלְשׁוֹן חִבָּה כָּתַב הַכָּתוּב, \\\"נָתַן רֵיחוֹ\\\", וְלֹא כָתַב \\\"הִבְאִישׁ\\\" אוֹ \\\"הִסְרִיחַ\\\", לְפִי שֶׁדִּבֵּר הַכָּתוּב בְּלָשׁוֹן נְקִיָּה. (עַיֵּן בְּרַשִׁ\\\"י בְּמַסֶּכֶת שַׁבָּת, פֶּרֶק רַבִּי עֲקִיבָא, דְּהַטַּעַם דְּלָא כְתִיב \\\"הִבְאִישׁ\\\" אוֹ \\\"הִסְרִיחַ\\\" מִשּׁוּם חִבָּה. אָכֵן לְפֵרוּשׁ הַתּוֹסָפוֹת שָׁם, שֶׁפֵּרַשׁ: וְהָכִי קָאָמַר, מַה שֶּׁכָּתַב \\\"נָתַן וְלֹא \\\"עָזַב\\\" זֶהוּ מִשּׁוּם חִבָּה, אָכֵן מַה שֶּׁלֹא כָתַב \\\"הִבְאִישׁ\\\" אוֹ \\\"הִסְרִיחַ\\\" זֶהוּ בְלַאו הָכִי, מִשּׁוּם לָשׁוֹן נְקִיָּה):\",2,0],[2,138,1,13,\"צְרוֹר הַמֹּר דּוֹדִי לִי. דּוֹדִי נַעֲשָׂה לִי כְמִי שֶׁיֵּשׁ לוֹ צְרוֹר הַמּוֹר בְּחֵיקוֹ, וְאָמַר לוֹ: הֲרֵי לְךָ צְרוֹר זֶה, שֶׁיִּתֵּן רֵיחַ טוֹב מִן הָרִאשׁוֹן שֶׁאִבַּדְתָּ. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נִתְרַצָּה לְיִשְׂרָאֵל עַל מַעֲשֵׂה הָעֵגֶל וּמָצָא לָהֶם כַּפָּרָה עַל עֲוֹנָם, וְאָמַר: \\\"הִתְנַדְּבוּ לַמִּשְׁכָּן, וְיָבֹא זְהַב הַמִּשְׁכָּן וִיכַפֵּר עַל זְהַב הָעֵגֶל\\\":\",1,0],[2,138,1,13,\"בֵּין שָׁדַי יָלִין. אַף עַל פִּי שֶׁמָּעַלְתִּי בּוֹ, אָמַר לִשְׁכֹּן שָׁם:\",2,0],[2,138,1,13,\"בֵּין שָׁדַי. בֵּין שְׁנֵי בַדֵּי הָאָרוֹן:\",3,0],[2,138,1,14,\"אֶשְׁכֹּל הַכֹּפֶר. יֵשׁ בֹּשֶׂם שֶׁשְּׁמוֹ כֹּפֶר, כְּמוֹ \\\"כְּפָרִים עִם נְרָדִים\\\", וְעָשׂוּי כְּעֵין אֶשְׁכֹּלוֹת:\",1,0],[2,138,1,14,\"בְּכַרְמֵי עֵין גֶּדִי. שֵׁם מָקוֹם, וְשָׁם הוּא מָצוּי. וְרָאִיתִי בָּאַגָּדָה שֶׁאוֹתָן כְּרָמִים עוֹשִׂין פֵּרוֹת אַרְבָּעָה אוֹ חֲמִשָּׁה פְעָמִים בַּשָּׁנָה. וְדֻגְמָא הִיא לְכַמָּה כַפָּרוֹת וּמְחִילוֹת, שֶׁמָּחַל לָהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא עַל כַּמָּה נִסְיוֹנוֹת שֶׁנִּסּוּהוּ בַמִּדְבָּר:\",2,0],[2,138,1,15,\"הִנָּךְ יָפָה רַעְיָתִי. אֲנִי הָיִיתִי בוֹשָׁה בְקִלְקוּלִי, וְהוּא חִזְּקַנִי בְדִבְרֵי רִצּוּיִים, לוֹמַר \\\"סָלַחְתִּי כִּדְבָרֶיךָ\\\". וַהֲרֵי אַתְּ יָפָה וְיָפָה כִּי עֵינַיִךְ יוֹנִים, כְּלוֹמַר: כַּלָּה שֶׁעֵינֶיהָ כְעוּרִים כָּל גּוּפָהּ צָרִיךְ בְּדִיקָה, וְשֶׁעֵינֶיהָ נָאִים אֵין גּוּפָהּ צָרִיךְ בְּדִיקָה. וְהַדֻּגְמָא זוֹ הִיא: מָחַלְתִּי לָךְ עַל עֲוֹנֵךְ, וַהֲרֵי אַתְּ יָפָה בְ'נַעֲשֶׂה' וְהִנָּךְ יָפָה בְ'נִשְׁמָע', יָפָה בְמַעֲשֵׂה אָבוֹת, יָפָה בְמַעֲשָׂיִךְ:\",1,0],[2,138,1,15,\"כִּי עֵינַיִךְ יוֹנִים. צַדִּיקִים יֵשׁ בְּיָדֵךְ שֶׁדָּבְקוּ בִי, כְּיוֹנָה זוּ שֶׁמִּשֶּׁמַּכֶּרֶת אֶת בֶּן זוּגָהּ אֵינָהּ מַנִּיחַתּוּ שֶׁיִּזְדַּוֵּג לְאַחֵר. כָּךְ \\\"וַיֵּאָסְפוּ אֵלָיו כָּל בְּנֵי לֵוִי\\\" וְלֹא טָעוּ בָעֵגֶל. וְעוֹד: הִנָּךְ יָפָה בִמְלֶאכֶת הַמִּשְׁכָּן, שֶׁנֶּאֱמַר \\\"וְהִנֵּה עָשׂוּ אֹתָהּ וגו' וַיְבָרֶךְ אֹתָם משֶׁה\\\". הֲרֵי שֶׁקִּלְּסָם עַל כָּךְ:\",2,0],[2,138,1,16,\"הִנְּךָ יָפֶה דוֹדִי אַף נָעִים. לֹא הַיֹּפִי שֶׁלִּי אֶלָּא שֶׁלְּךָ. אַתָּה הוּא הַיָּפֶה:\",1,0],[2,138,1,16,\"אַף נָעִים. שֶׁעָבַרְתָּ עַל פְּשָׁעַי וְהִשְׁרֵיתָ שְׁכִינָתְךָ בְּתוֹכֵנוּ. וְזֶהוּ קִלּוּס שֶׁל יְרִידַת הָאֵשׁ \\\"וַיַּרְא כָּל הָעָם וַיָּרֹנּוּ\\\":\",2,0],[2,138,1,16,\"אַף עַרְשֵׂנוּ רַעֲנָנָה. עַל יְדֵי נְעִימוֹתֶיךָ, הִנֵּה רַעֲנָנָה עַרְשֵׂנוּ בְּבָנֵינוּ וּבִבְנוֹתֵינוּ שֶׁהֵם כֻּלָּם נִקְבָּצִים אֵלֶיךָ פֹה, שֶׁנֶּאֱמַר \\\"וַתִּקָּהֵל הָעֵדָה וגו'\\\". הַמִּשְׁכָּן קָרוּי מִטָּה, שֶׁנֶּאֱמַר \\\"הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה\\\". וְכֵן הַמִּקְדָּשׁ קָרוּי מִטָּה, שֶׁנֶּאֱמַר בְּיוֹאָשׁ \\\"\\\"בַּחֲדַר הַמִּטּוֹת\\\" אֲשֶׁר \\\"בְּבֵית הָאֱלֹקִים\\\", עַל שֶׁהֵם פִּרְיָן וְרִבְיָן שֶׁל יִשְׂרָאֵל:\",3,0],[2,138,1,17,\"קֹרוֹת בָּתֵּינוּ אֲרָזִים. שֶׁבַח הַמִּשְׁכָּן הוּא זֶה:\",1,0],[2,138,1,17,\"רָהִיטֵנוּ. לֹא יָדַעְתִּי אִם לְשׁוֹן קְרָשִׁים אוֹ לְשׁוֹן בְּרִיחִים, אַךְ יָדַעְתִּי שֶׁאַף בִּלְשׁוֹן מִשְׁנָה שָׁנִינוּ: רָהִיטֵי בֵיתוֹ שֶׁל אָדָם הֵם מְעִידִים בּוֹ:\",2,0],[2,138,2,1,\"חֲבַצֶּלֶת. הִיא שׁוֹשַׁנָּה:\",1,0],[2,138,2,1,\"שׁוֹשַׁנַּת הָעֲמָקִים. נָאָה מִשּׁוֹשַׁנַּת הֶהָרִים לְפִי שֶׁמַּרְטֶבֶת תָּמִיד, שֶׁאֵין כֹּחַ הַחַמָּה שׁוֹלֵט שָׁם:\",2,0],[2,138,2,2,\"כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים. שֶׁמְּנַקְּבִין אוֹתָהּ, וְתָמִיד הִיא עוֹמֶדֶת בְּנוֹיָהּ וְאַדְמִימוּתָהּ, \\\"כֵּן רַעְיָתִי בֵּין הַבָּנוֹת\\\", מְפַתּוֹת אוֹתָהּ לִרְדֹּף אַחֲרֵיהֶם לִזְנוֹת כְּמוֹתָם אַחֲרֵי אֱלֹהִים אֲחֵרִים, וְהִיא עוֹמֶדֶת בֶּאֱמוּנָתָהּ:\",1,0],[2,138,2,3,\"כְּתַפּוּחַ. אִילָן שֶׁל תַּפּוּחִים, כְּשֶׁהוּא בֵּין אִילָנֵי סְרָק, הוּא חָבִיב מִן כֻּלָּן, שֶׁפִּרְיוֹ טוֹב בְּטַעַם וּבְרֵיחַ:\",1,0],[2,138,2,3,\"כֵּן דּוֹדִי בֵּין הַבָּנִים. בֵּין הַבַּחוּרִים. הַדֻּגְמָא: כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל הָאֱלֹהִים נִבְחָר. לְפִיכָךְ, \\\"בְּצִלּוֹ חִמַּדְתִּי וְיָשַׁבְתִּי\\\". וּמִדְרַשׁ אַגָּדָה: הַתַּפּוּחַ הַזֶּה, הַכֹּל בּוֹרְחִים הֵימֶנּוּ, לְפִי שֶׁאֵין לוֹ צֵל. כָּךְ בָּרְחוּ כָל הָאֻמּוֹת מֵעַל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַתַּן תּוֹרָה, אֲבָל אֲנִי, \\\"בְּצִלּוֹ חִמַּדְתִּי וְיָשַׁבְתִּי\\\":\",2,0],[2,138,2,4,\"אֶל בֵּית הַיָּיִן. אֹהֶל מוֹעֵד שֶׁשָּׁם נִתְּנוּ פְרָטֶיהָ וּבֵאוּרֶיהָ שֶׁל תּוֹרָה:\",1,0],[2,138,2,4,\"וְדִגְלוֹ עָלַי אַהֲבָה. וּקְבוּצָתוֹ שֶׁדְּגָלַנִי אֵלָיו, אַהֲבָה הִיא עָלַי, עוֹדֶנִּי זוֹכֶרֶת אַהֲבָתוֹ. וְדִגְלוֹ אטר\\\"ייט בְּלַעַ\\\"ז:\",2,0],[2,138,2,5,\"סַמְּכוּנִי. עַתָּה, כְּמִדַּת הַחוֹלִים, בַּאֲשִׁישֵׁי עֲנָבִים אוֹ בַאֲשִׁישׁוֹת סֹלֶת נְקִיָּה:\",1,0],[2,138,2,5,\"רַפְּדוּנִי. רַפְּדוּ רְפִידָתִי סְבִיבוֹתַי בַּתַּפּוּחִים לְרֵיחַ טוֹב, כְּדֶרֶךְ הַחוֹלִים, כִּי חוֹלָה אֲנִי לְאַהֲבָתוֹ, כִּי צָמֵאתִי לוֹ פֹה בְגָלוּתִי. רְפִידָה לְשׁוֹן מַצָּע הִיא, כְּמוֹ \\\"יִרְפַּד חָרוּץ עֲלֵי טִיט\\\":\",2,0],[2,138,2,6,\"שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. בַּמִּדְבָּר:\",1,0],[2,138,2,6,\"וִימִינוֹ תְּחַבְּקֵנִי. דֶּרֶךְ שְׁלשֶׁת יָמִים נוֹסֵעַ לָתוּר לָהֶם מְנוּחָה, וּבִמְקוֹם הַמְנוּחָה מוֹרִיד לָהֶם מָן וּשְׂלָיו. כָּל זֶה אֲנִי זוֹכֶרֶת עַתָּה בְּגָלוּתִי, וְחוֹלָה לְאַהֲבָתוֹ:\",2,0],[2,138,2,7,\"הִשְׁבַּעְתִּי אֶתְכֶם. אַתֶּם הָאֻמּוֹת:\",1,0],[2,138,2,7,\"בִּצְבָאוֹת אוֹ בְּאַיְלוֹת. שֶׁתִּהְיוּ הֶפְקֵר וּמַאֲכָל כִּצְבָיִים וְאַיָּלִים:\",2,0],[2,138,2,7,\"אִם תָּעִירוּ וְאִם תְּעוֹרְרוּ אֶת הָאַהֲבָה. שֶׁבֵּינִי לְדוֹדִי, לְשַׁנּוֹתָהּ וּלְהַחֲלִיפָהּ וּלְבַקֵּשׁ מִמֶּנִּי לְהִתְפַּתּוֹת אַחֲרֵיכֶם:\",3,0],[2,138,2,7,\"עַד שֶׁתֶּחְפָּץ. בְּכָל עוֹד שֶׁהִיא תְקוּעָה בְלִבִּי וְהוּא חָפֵץ בִּי:\",4,0],[2,138,2,7,\"עַד שֶׁתֶּחְפָּץ. כְּמוֹ \\\"עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ\\\", בְּעוֹד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ:\",5,0],[2,138,2,7,\"אִם תָּעִירוּ. אִם תַּשְׂנִיאוּ, כְּמוֹ \\\"וַיְהִי עָרֶךָ\\\", \\\"וּפִשְׁרֵהּ לְעָרָיךְ\\\":\",6,0],[2,138,2,7,\"וְאִם תְּעוֹרְרוּ. כְּמוֹ \\\"הָעוֹרֵר עַל הַשָּׂדֶה\\\" קלניי\\\"ר בְּלַעַ\\\"ז. יֵשׁ מִדְרְשֵׁי אַגָּדָה רַבִּים וְאֵינָם מִתְיַשְּׁבִים עַל סֵדֶר הַדְּבָרִים, כִּי רוֹאֶה אֲנִי שֶׁנִּתְנַבֵּא שְׁלֹמֹה וְדִבֵּר עַל יְצִיאַת מִצְרַיִם וְעַל מַתַּן תּוֹרָה וְהַמִּשְׁכָּן וּבִיאַת הָאָרֶץ וּבֵית הַבְּחִירָה וְגָלוּת בָּבֶל וּבִיאַת בַּיִת שֵׁנִי וְחֻרְבָּנוֹ:\",7,0],[2,138,2,8,\"קוֹל דּוֹדִי. חוֹזֵר הַמְשׁוֹרֵר עַל הָרִאשׁוֹנוֹת. כְּאָדָם שֶׁקִּצֵּר דְּבָרָיו וְחוֹזֵר וְאוֹמֵר: לֹא אָמַרְתִּי לִפְנֵיכֶם רֵאשִׁית הַדְּבָרִים. הוּא הִתְחִיל וְאָמַר: \\\"הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו\\\", וְלֹא סִפֵּר הֵיאַךְ פְּקָדָם בְּמִצְרַיִם בִּלְשׁוֹן חִבָּה. וְעַכְשָׁיו חוֹזֵר וְאוֹמֵר: מְשִׁיכָה זוֹ שֶׁאָמַרְתִּי לָכֶם, שֶׁמְּשָׁכַנִי דוֹדִי וְרַצְתִּי אַחֲרָיו, כֵּן הָיְתָה: נוֹאָשׁ הָיִיתִי אוֹמֶרֶת לִגְאֻלָּה עַד תּם אַרְבַּע מֵאוֹת שָׁנָה שֶׁנֶּאֱמְרוּ בֵּין הַבְּתָרִים, וְ. . .\",1,0],[2,138,2,8,\"קוֹל דּוֹדִי הִנֵּה זֶה בָּא לִפְנֵי הַקֵּץ כִּמְדַלֵּג עַל הֶהָרִים וּמְקַפֵּץ בַּגְּבָעוֹת:\",2,0],[2,138,2,9,\"דּוֹמֶה דוֹדִי לִצְבִי. בְּקַלּוּת מְרוּצָתוֹ, שֶׁמִּהֵר לָבֹא כִצְבִי וּכְעֹפֶר הָאַיָּלִים. עֹפֶר אַיָּל בָּחוּר:\",1,0],[2,138,2,9,\"הִנֵּה זֶה עוֹמֵד וגו'. סְבוּרָה הָיִיתִי לֵישֵׁב עֲגוּנָה עוֹד יָמִים רַבִּים. וְהִנֵּה הוּא הוֹדִיעַ שֶׁהָיָה עוֹמֵד וּמֵצִיץ מִן חַלּוֹנוֹת הַשָּׁמַיִם אֶת הֶעָשׂוּי לִי, שֶׁנֶּאֱמַר \\\"רָאֹה רָאִיתִי אֶת עֳנִי עַמִּי וגו'\\\":\",2,0],[2,138,2,10,\"עָנָה. לְשׁוֹן עֲנִיָּה וּלְשׁוֹן צַעֲקַת קוֹל רָם, וְזֶה בִּנְיַן אָב לְכֻלָּם \\\"וְעָנוּ הַלְוִיִּם\\\":\",1,0],[2,138,2,10,\"וְאָמַר לִי. עַל יְדֵי משֶׁה:\",2,0],[2,138,2,10,\"קוּמִי לָךְ. \\\"אַעֲלֶה אֶתְכֶם מֵעֳנִי מִצְרַיִם\\\":\",3,0],[2,138,2,11,\"הִנֵּה הַסְּתָו עָבָר. אֵין עַכְשָׁיו טֹרַח בַּדֶּרֶךְ. סְתָו חֹרֶף. תַּרְגּוּם חֹרֶף סִתְוָא:\",1,0],[2,138,2,12,\"הַנִּצָּנִים נִרְאוּ בָאָרֶץ. קָרְבוּ יְמֵי הַחַמָּה, שֶׁהָאִילָנוֹת מוֹצִיאִין פְּרָחִים, וְהוֹלְכֵי דְרָכִים מִתְעַנְּגִים לִרְאוֹתָם:\",1,0],[2,138,2,12,\"עֵת הַזָּמִיר הִגִּיעַ. שֶׁהָעוֹפוֹת נוֹתְנִין זֶמֶר וְקוֹל עָרֵב לְהוֹלְכֵי דְרָכִים:\",2,0],[2,138,2,12,\"וְקוֹל הַתּוֹר. כְּמַשְׁמָעוֹ: תּוֹרִים וּבְנֵי יוֹנָה. דֶּרֶךְ הָעוֹפוֹת לִהְיוֹת מְשׁוֹרְרִים וּמְצַפְצְפִים בִּימֵי נִיסָן:\",3,0],[2,138,2,13,\"הַתְּאֵנָה חָנְטָה פַגֶּיהָ. כְּמַשְׁמָעוֹ:\",1,0],[2,138,2,13,\"וְהַגְּפָנִים סְמָדַר. כְּשֶׁנּוֹפֵל הַפֶּרַח וְהָעֲנָבִים מֻבְדָּלִים זֶה מִזֶּה וְנִכָּרִים כָּל עֲנָבָה לְעַצְמָהּ, קְרוּיָה סְמָדַר. כָּל הָעִנְיָן הַזֶּה, לְפִי פְשׁוּטוֹ, לְשׁוֹן חִבַּת פִּתּוּי, שֶׁבָּחוּר מְרַצֶּה אֶת אֲרוּסָתוֹ לֵילֵךְ אַחֲרָיו, כֵּן עָשָׂה לִי דוֹדִי:\",2,0],[2,138,2,13,\"עָנָה דוֹדִי. עַל יְדֵי משֶׁה:\",3,0],[2,138,2,13,\"וְאָמַר לִי. עַל יְדֵי אַהֲרֹן:\",4,0],[2,138,2,13,\"קוּמִי לָךְ. זָרְזִי עַצְמֵךְ, \\\"וְיִשְׁאֲלוּ אִישׁ מֵאֵת רֵעֵהוּ\\\":\",5,0],[2,138,2,13,\"כִּי הִנֵּה הַסְּתָו עָבָר. אֵלּוּ אַרְבַּע מֵאוֹת שָׁנָה, דִּלַּגְתִּים לִמְנוֹתָם מִשֶּׁנּוֹלַד יִצְחָק:\",6,0],[2,138,2,13,\"הַגֶּשֶׁם. שֶׁהוּא טַרְחוּתוֹ שֶׁל סְתָו, חָלַף וְהָלַךְ לוֹ. כְּלוֹמַר, שְׁמוֹנִים וְשֵׁשׁ שָׁנָה שֶׁל קשִׁי הַשִּׁעְבּוּד נִגְזְרוּ עֲלֵיכֶם וְהָלְכוּ לָהֶם. מִשֶּׁנּוֹלְדָה מִרְיָם, הִקְשׁוּ הַמִּצְרִים שִׁעְבּוּד עַל יִשְׂרָאֵל, וּלְכָךְ נִקְרֵאת מִרְיָם עַל שֶׁמֵּרְרוּם:\",7,0],[2,138,2,13,\"הַנִּצָּנִים נִרְאוּ בָאָרֶץ. הֲרֵי משֶׁה וְאַהֲרֹן מוּכָנִים לָכֶם לְכָל צָרְכֵיכֶם:\",8,0],[2,138,2,13,\"עֵת הַזָּמִיר הִגִּיעַ. שֶׁאַתֶּם עֲתִידִים לוֹמַר שִׁירָה עַל הַיָּם:\",9,0],[2,138,2,13,\"וְקוֹל הַתּוֹר. קוֹל הַתַּיָּר הַגָּדוֹל. דָּבָר אַחֵר: \\\"קוֹל הַתּוֹר\\\": קוֹל שֶׁהִגִּיעַ זְמַן יְצִיאַתְכֶם מִמִּצְרָיִם:\",10,0],[2,138,2,13,\"הַתְּאֵנָה חָנְטָה פַגֶּיהָ. הִגִּיעַ זְמַן שֶׁל בִּכּוּרִים לִקְרֹב, שֶׁתִּכָּנְסוּ לָאָרֶץ:\",11,0],[2,138,2,13,\"וְהַגְּפָנִים סְמָדַר. קָרֵב זְמַן נִסְכֵּי הַיָּיִן. דָּבָר אַחֵר: כְּשֵׁרִים שֶׁבָּכֶם חָנְטוּ וְהֵנֵצוּ לְפָנַי מַעֲשִׂים טוֹבִים וְהֵרִיחוּ רֵיחַ טוֹב:\",12,0],[2,138,2,13,\"קוּמִי לָכְי. כְּתִיב יו\\\"ד יְתֵרָה, \\\"קוּמִי לָךְ\\\" לְקַבֵּל עֲשֶׂרֶת הַדִּבְּרוֹת.\",13,0],[2,138,2,13,\"דָּבָר אַחֵר: הַתְּאֵנָה חָנְטָה פַגֶּיהָ. אֵלּוּ פּוֹשְׁעֵי יִשְׂרָאֵל שֶׁכָּלוּ בִשְׁלשֶׁת יְמֵי אֲפֵלָה:\",14,0],[2,138,2,13,\"וְהַגְּפָנִים סְמָדַר נָתְנוּ רֵיחַ. אֵלּוּ הַנִּשְׁאָרִים מֵהֶם, עָשׂוּ תְשׁוּבָה וְנִתְקַבְּלוּ. כָּךְ נִדְרַשׁ בִּפְסִיקְתָּא:\",15,0],[2,138,2,14,\"יוֹנָתִי בְּחַגְוֵי הַסֶּלַע. זֶה נֶאֱמַר עַל אוֹתָהּ שָׁעָה שֶׁרָדַף פַּרְעֹה אַחֲרֵיהֶם וְהִשִׂיגָם חוֹנִים עַל הַיָּם, וְאֵין מָקוֹם לָנוּס לִפְנֵיהֶם מִפְּנֵי הַיָּם, וְלֹא לְהִפָּנוֹת מִפְּנֵי חַיּוֹת רָעוֹת. לְמָה הָיוּ דוֹמִין בְּאוֹתָהּ שָׁעָה? לְיוֹנָה שֶׁבּוֹרַחַת מִפְּנֵי הַנֵּץ וְנִכְנְסָה בִנְקִיקֵי הַסְּלָעִים, וְהָיָה הַנָּחָשׁ נוֹשֵׁף בָּהּ. תִּכָּנֵס לִפְנִים, הֲרֵי הַנָּחָשׁ, תֵּצֵא לַחוּץ, הֲרֵי הַנֵּץ. אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: \\\"הַרְאִינִי אֶת מַרְאַיִךְ\\\", אֶת כִּשְׁרוֹן פְּעֻלָּתֵךְ, לְמִי אַתְּ פּוֹנָה בְּעֵת צָרָה:\",1,0],[2,138,2,14,\"הַשְׁמִיעִנִי אֶת קוֹלֵךְ. \\\"וַיִּצְעֲקוּ בְנֵי יִשְׂרָאֵל אֶל ה'\\\":\",2,0],[2,138,2,14,\"בְּחַגְוֵי. בִּנְקִיקֵי, וְהוּא לְשׁוֹן שֶׁבֶר, וְדוֹמֶה לוֹ \\\"יָחוֹגּוּ וְיָנוּעוּ\\\". \\\"וְהָיְתָה אַדְמַת יְהוּדָה לְמִצְרַיִם לְחָגָּא\\\". וּכְשֶׁהֵן רַבִּים, קוֹרֵא לָהֶן חַגְוֵי, וְכֵן: קָצָה קַצְוֵי, וְכֵן \\\"וַיִּכְרֹת אֶת מַדְוֵיהֶם\\\":\",3,0],[2,138,2,14,\"הַמַּדְרֵגָה. אישקלוי\\\"ש בְּלַעַ\\\"ז. כְּשֶׁעוֹשִׂין חָרִיץ סְבִיבוֹת הַמִּגְדָלִים וְשׁוֹפְכִים הֶעָפָר לְמַעְלָה לְהַגְבִּיהַּ הַתֵּל סָבִיב, עוֹשִׂין אוֹתוֹ מַדְרֵגוֹת מַדְרֵגוֹת זוּ לְמַעְלָה מִזּוּ:\",4,0],[2,138,2,14,\"בְּסֵתֶר הַמַּדְרֵגָה. פְּעָמִים שֶׁיֵשׁ בָּהֶן חוֹרִים וְנִכְנָסִים שָׁם שְׁרָצִים וְעוֹפוֹת:\",5,0],[2,138,2,15,\"אֶחֱזוּ לָנוּ שׁוּעָלִים. שָׁמַע הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת קוֹלָם, צִוָּה אֶת הַיָּם וּשְׁטָפָם. זֶהוּ: \\\"אֶחֱזוּ לָנוּ הַשּׁוּעָלִים הַלָּלוּ\\\", הַקְּטַנִּים עִם הַגְּדוֹלִים, שֶׁאַף הַקְּטַנִּים הָיוּ מְחַבְּלִים אֶת הַכְּרָמִים בְּעוֹד כְּרָמֵינוּ סְמָדַר, שֶׁהָעֲנָבִים דַּקִּים. כְּשֶׁהָיְתָה בַת יִשְׂרָאֵל יוֹלֶדֶת זָכָר וְהִיא טוֹמַנְתּוֹ, וְהָיוּ הַמִּצְרִים נִכְנָסִים לְבָתֵּיהֶם וּמְחַפְּשִׂין אֶת הַזְּכָרִים, וְהַתִּינוֹק טָמוּן, וְהוּא בֶן שָׁנָה אוֹ בֶן שְׁנָתַיִם. וְהֵן מְבִיאִין תִּינוֹקוֹת מִבֵּית מִצְרִי, וְתִינוֹק מִצְרִי מְדַבֵּר, וְתִינוֹק יִשְׂרָאֵל עוֹנֵהוּ מִמָּקוֹם שֶׁטָּמוּן שָׁם, וְהָיוּ תוֹפְשִׂין וּמַשְׁלִיכִין אוֹתוֹ לַיְאוֹר. וְלָמָּה קָרָא אוֹתָם שׁוּעָלִים? מָה הַשּׁוּעָל הַזֶּה מַבִּיט לִפְנוֹת לַאֲחוֹרָיו לִבְרֹחַ, אַף מִצְרִים מַבִּיטִים לַאֲחוֹרֵיהֶם, שֶׁנֶּאֱמַר \\\"אָנוּסָה מִפְּנֵי יִשְׂרָאֵל\\\":\",1,0],[2,138,2,15,\"שֻׁעָלִים קְטַנִּים. כְּתִיב חָסֵר וי\\\"ו עַל שֵׁם שֶׁהָיָה נִפְרָע מֵהֶם בְּמַיִם, שֶׁנִּמְדְּדוּ בְשָּׁעֳלוֹ שֶׁל מָקוֹם:\",2,0],[2,138,2,16,\"דּוֹדִי לִי וַאֲנִי לוֹ. הוּא כָל צְרָכָיו תָּבַע מִמֶּנִּי, וְלֹא צִוָּה אֶלָּא לִי: \\\"עֲשׂוּ פֶסַח, קַדְּשׁוּ בְכוֹרוֹת, עֲשׂוּ מִשְׁכָּן, הַקְרִיבוּ עוֹלוֹת\\\", וְלֹא תָבַע מֵאֻמָּה אַחֶרֶת:\",1,0],[2,138,2,16,\"וַאֲנִי לוֹ. כָּל צְרָכַי תָּבַעְתִּי מִמֶּנּוּ וְלֹא מֵאֱלֹהִים אֲחֵרִים:\",2,0],[2,138,2,16,\"הָרֹעֶה. אֶת צֹאנוֹ:\",3,0],[2,138,2,16,\"בַּשּׁוֹשַׁנִּים. בְּמִרְעֶה טוֹב וְנוֹחַ וְיָפֶה:\",4,0],[2,138,2,17,\"עַד שֶׁיָּפוּחַ הַיּוֹם. מוּסָב לַמִּקְרָא שֶׁל מַעְלָה הֵימֶנּוּ: \\\"דּוֹדִי לִי וַאֲנִי לוֹ\\\", עַד זְמָן שֶׁגָּרַם הֶעָוֹן וּשְׁזָפַתְנִי הַשֶּׁמֶשׁ כְּחֹם הַיּוֹם וְגָבַר הַשָּׁרָב:\",1,0],[2,138,2,17,\"וְנָסוּ הַצְּלָלִים. חָטָאנוּ בָעֵגֶל, חָטָאנוּ בַמְרַגְּלִים. \\\"וְנָסוּ הַצְּלָלִים\\\", זְכֻיּוֹת הַמְגִנּוֹת עָלֵינוּ, פָּרַקְתִּי עֻלּוֹ:\",2,0],[2,138,2,17,\"סֹב דְּמֵה לְךָ דוֹדִי. גָּרַמְתִּי לוֹ לְהִסְתַּלֵּק מֵעָלַי עַל הָרִים הַמֻּפְלָגִים מִמֶּנִּי:\",3,0],[2,138,2,17,\"בָתֶר. לְשׁוֹן חֲלֻקָּה וְהַפְלָגָה:\",4,0],[2,138,3,1,\"עַל מִשְׁכָּבִי בַּלֵּילוֹת. בַּצַּר לִי, שֶׁיָּשַׁבְתִּי אֲפֵלָה כָּל שְׁלשִׁים וּשְׁמֹנֶה שָׁנָה שֶׁהָיוּ יִשְׂרָאֵל נְזוּפִים:\",1,0],[2,138,3,1,\"בִּקַּשְׁתִּיו וְלֹא מְצָאתִיו. \\\"כִּי לֹא אֶעֱלֶה בְּקִרְבְּךָ\\\", \\\"כִּי אֵינֶנִּי בְּקִרְבְּכֶם\\\":\",2,0],[2,138,3,2,\"אָקוּמָה נָּא וגו' אֲבַקְשָׁה. \\\"וַיְחַל משֶׁה\\\", \\\"אֶעֱלֶה אֶל ה'\\\":\",1,0],[2,138,3,3,\"מְצָאוּנִי הַשֹּׁמְרִים. משֶׁה וְאַהֲרֹן:\",1,0],[2,138,3,3,\"אֵת שֶׁאָהֲבָה נַפְשִׁי רְאִיתֶם. מַה מְּצָאתֶם בְּפִיו?\",2,0],[2,138,3,4,\"כִּמְעַט שֶׁעָבַרְתִּי מֵהֶם. קָרוֹב לִפְרִישָׁתָם מִמֶּנִּי לְסוֹף אַרְבָּעִים שָׁנָה:\",1,0],[2,138,3,4,\"עַד שֶׁמָּצָאתִי. שֶׁהָיָה עִמִּי בִּימֵי יְהוֹשֻׁעַ לִכְבּשׁ שְׁלשִׁים וְאֶחָד מְלָכִים:\",2,0],[2,138,3,4,\"אֲחַזְתִּיו וְלֹא אַרְפֶּנּוּ. לֹא נָתַתִּי לוֹ רִפְיוֹן עַד שֶׁהֲבִיאוֹתִיו אֶל מִשְׁכַּן שִׁילֹה בִּשְׁבִיל כָּל זֹאת שֶׁעָשָׂה לִי:\",3,0],[2,138,3,5,\"הִשְׁבַּעְתִּי אֶתְכֶם. הָאֻמּוֹת, בִּהְיוֹתִי גוֹלָה בֵינֵיכֶם:\",1,0],[2,138,3,5,\"אִם תָּעִירוּ וְאִם תְּעוֹרְרוּ. אַהֲבַת דּוֹדִי מִמֶּנִּי עַל יְדֵי פִתּוּי וַהֲסָתָה, לְעָזְבוֹ וְלָשׁוּב מֵאַחֲרָיו:\",2,0],[2,138,3,5,\"עַד שֶׁתֶּחְפָּץ. בְּעוֹד שֶׁאַהֲבָתוֹ חָפֵץ עָלַי:\",3,0],[2,138,3,6,\"מִי זֹאת עֹלָה מִן הַמִּדְבָּר. כְּשֶׁהָיִיתִי מְהַלֶּכֶת בַּמִּדְבָּר וְהָיָה עַמּוּד הָאֵשׁ וְהֶעָנָן הוֹלְכִים לְפָנַי וְהוֹרְגִים נְחָשִׁים וְעַקְרַבִּים וְשׂוֹרְפִין הַקּוֹצִים וְהַבַּרְקָנִים לַעֲשׂוֹת דֶּרֶךְ מִישׁוֹר, וְהָיָה הֶעָנָן וְהֶעָשָׁן וְרוֹאִין אוֹתָן הָאֻמּוֹת וּמַתְמִיהוֹת עַל גְּדֻלָּתִי, וְאוֹמְרוֹת: \\\"מִי זֹאת\\\"? כְּלוֹמַר, כַּמָּה גְדוֹלָה הִיא זֹאת הָעוֹלָה מִן הַמִּדְבָּר וגו':\",1,0],[2,138,3,6,\"כְּתִימְרוֹת עָשָׁן. גָּבֹהַּ וְזָקוּף כְּתָמָר:\",2,0],[2,138,3,6,\"מְקֻטֶּרֶת מֹר. עַל שֵׁם עֲנַן הַקְּטֹרֶת שֶׁהָיָה מִתַּמֵּר מֵעַל מִזְבֵּחַ הַפְּנִימִי:\",3,0],[2,138,3,6,\"רוֹכֵל. בַּשָׂם הַמּוֹכֵר כָּל מִינֵי בְשָׂמִים:\",4,0],[2,138,3,6,\"אַבְקַת. עַל שֵׁם שֶׁכּוֹתְשִׁין אוֹתוֹ וְשׁוֹחֲקִין הָדֵק כְּאָבָק:\",5,0],[2,138,3,7,\"הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה. אֹהֶל מוֹעֵד וְהָאָרוֹן שֶׁהָיוּ נוֹשְׂאִין בַּמִּדְבָּר:\",1,0],[2,138,3,7,\"שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ. שִׁשִּׁים רִבּוֹא סָבִיב לָהּ:\",2,0],[2,138,3,7,\"מִגִּבֹּרֵי יִשְׂרָאֵל. מִיּוֹצְאֵי הַצָּבָא, לְבַד פְּחוּתִים מִבֶּן עֶשְׂרִים וְהַיְתֵרִים עַל בְּנֵי שִׁשִּׁים:\",3,0],[2,138,3,8,\"מְלֻמְּדֵי מִלְחָמָה. מִלְחַמְתָּהּ שֶׁל תּוֹרָה, וְכֵן הַכֹּהֲנִים הַסּוֹבְבִים אוֹתָהּ הַחוֹנִים סְבִיבוֹת הַמִּשְׁכָּן, מְלֻמְּדֵי סֵדֶר עֲבוֹדָתָם:\",1,0],[2,138,3,8,\"אִישׁ חַרְבּוֹ. כְּלֵי זֵינוֹ הֵן מְסֹרֶת וְסִימָנִים, שֶׁמַּעֲמִידִים עַל יָדָם אֶת הַגִּרְסָא וְהַמְסוֹרָה שֶׁלֹּא תִשְׁתַּכַּח:\",2,0],[2,138,3,8,\"מִפַּחַד בַּלֵּילוֹת. פֶּן יִשְׁכָּחוּהָ, וְיָבוֹאוּ עֲלֵיהֶם צָרוֹת וְכֵן הוּא אוֹמֵר: \\\"נַשְּׁקוּ בַר פֶּן יֶאֱנַף וְתאבְדוּ דֶרֶךְ\\\":\",3,0],[2,138,3,9,\"אַפִּרְיוֹן עָשָׂה לוֹ. זֶה אֹהֶל מוֹעֵד שֶׁנִּקְבַּע בְּמִשְׁכַּן שִׁילֹה, עָשָׂה לוֹ אַפִּרְיוֹן, חֻפַּת כֶּתֶר לְכָבוֹד:\",1,0],[2,138,3,10,\"רְפִידָתוֹ. מִשְׁכָּבוֹ וּמִשְׁכָּנוֹ עַל הַכַּפֹּרֶת שֶׁהוּא זָהָב:\",1,0],[2,138,3,10,\"מֶרְכָּבוֹ אַרְגָּמָן. זֶה הַפָּרֹכֶת, שֶׁהָיָה תָלוּי וְ'רוֹכֵב' עַל כְּלוֹנְסָאוֹת מֵעַמּוּד לְעַמּוּד:\",2,0],[2,138,3,10,\"תּוֹכוֹ רָצוּף. סָדוּר בְּרִצְפַּת אַהֲבָה, אָרוֹן וְכַפֹּרֶת וּכְרוּבִים וְלוּחוֹת:\",3,0],[2,138,3,10,\"מִבְּנוֹת יְרוּשָׁלָיִם. אֵלּוּ יִשְׂרָאֵל, יְרֵאִים וּשְׁלֵמִים לְהַקָּדוֹשׁ בָּרוּךְ הוּא:\",4,0],[2,138,3,11,\"בְּנוֹת צִיּוֹן. בָּנִים שֶׁמְּצֻיָּנִין לוֹ בְמִילָה וּבִתְפִלִּין וּבְצִיצִית:\",1,0],[2,138,3,11,\"בַּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ. אֹהֶל מוֹעֵד שֶׁהוּא מְעֻטָּר בְּגַוָּנִין: תְּכֵלֶת וְאַרְגָּמָן וְתוֹלַעַת שָׁנִי. אָמַר רַבִּי נְחוּנְיָא: שָׁאַל רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי אֶת רַבִּי אֶלְעָזָר בְּרַבִּי יוֹסֵי: אֶפְשָׁר שֶׁשָּׁמַעְתָּ מֵאָבִיךָ מַהוּ: \\\"בַּעֲטָרָה שֶׁעִטְּרָה לוֹ אִמּוֹ\\\"? אָמַר לוֹ: מָשָׁל לְמֶלֶךְ שֶׁהָיְתָה לוֹ בַת יְחִידָה וְהָיָה אוֹהֲבָהּ בְּיוֹתֵר. לֹא זָז מֵחַבְּבָהּ עַד שֶׁקְּרָאָהּ בִּתִּי, שֶׁנֶּאֱמַר \\\"שִׁמְעִי בַת וּרְאִי\\\". לֹא זָז מֵחַבְּבָהּ עַד שֶׁקְּרָאָהּ אֲחוֹתִי, שֶׁנֶּאֱמַר: \\\"פִּתְחִי לִי אֲחֹתִי רַעְיָתִי\\\". לֹא זָז מֵחַבְּבָהּ עַד שֶׁקְּרָאָהּ אִמִּי, שֶׁנֶּאֱמַר \\\"הַקְשִׁיבוּ אֵלַי עַמִּי וּלְאֻמִּי אֵלַי הַאֲזִינוּ\\\". \\\"וּלְאִמִּי\\\" כְּתִיב. עָמַד רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי וּנְשָׁקוֹ עַל רֹאשׁוֹ וכו':\",2,0],[2,138,3,11,\"בְּיוֹם חֲתֻנָּתוֹ. יוֹם מַתַּן תּוֹרָה, שֶׁעִטְּרוּהוּ לָהֶם לְמֶלֶךְ וְקִבְּלוּ עֻלּוֹ:\",3,0],[2,138,3,11,\"וּבְיוֹם שִׂמְחַת לִבּוֹ. זֶה שְׁמִינִי לְמִלּוּאִים, שֶׁנִּתְחַנֵּךְ בּוֹ הַמִּשְׁכָּן בַּמִּדְבָּר:\",4,0],[2,138,4,1,\"הִנָּךְ יָפָה רַעְיָתִי. קִלְּסָן וְרִצָּן וְעָרְבוּ עָלָיו קָרְבְּנוֹתֵיהֶם:\",1,0],[2,138,4,1,\"עַד שֶׁיָּפוּחַ הַיּוֹם. שֶׁחָטְאוּ לְפָנַי בִּימֵי חָפְנִי וּפִינְחָס:\",2,0],[2,138,4,1,\"עֵינַיִךְ יוֹנִים. גַּוֹּנַיִךְ וּמַרְאִיתֵךְ וְדֻגְמָתֵךְ כַּיּוֹנָה הַזֹּאת הַדְּבֵקָה בְּבֶן זוּגָהּ, וּכְשֶׁשּׁוֹחֲטִין אוֹתָהּ אֵינָהּ מְפַרְכֶּסֶת אֶלָּא פוֹשֶׁטֶת צַוָּארָהּ, כָּךְ אַתְּ נָתַתְּ שֶׁכֶם לִסְבֹּל עֻלִּי וּמוֹרָאִי: מִבַּעַד לְצַמָּתֵךְ\",3,0],[2,138,4,1,\"שַׂעְרֵךְ כְּעֵדֶר הָעִזִּים. הַקִּלּוּס הַזֶּה דֻּגְמַת קִלּוּס אִשָּׁה הַנֶּאֱהֶבֶת לֶחָתָן. מִבִּפְנִים לְקִשּׁוּרַיִךְ שַׂעְרֵךְ נָאֶה וּמַבְהִיק כְּצֹהַר וְלַבְנוּנִית כִּשְׂעַר עִזִּים לְבָנוֹת הַיּוֹרְדוֹת מִן הֶהָרִים וּשְׂעָרָן מַבְהִיק מֵרָחוֹק. וְהַדֻּגְמָא שֶׁדִּמָּה כְנֶסֶת יִשְׂרָאֵל לְכָךְ, זוֹ הִיא: מִבִּפְנִים לְמַחֲנוֹתַיִךְ וּמִשְׁכְּנוֹתַיִךְ, אַף הָרֵקִים שֶׁבֵּיךְ חֲבִיבִין עָלַי כְּיַעֲקֹב וּבָנָיו שֶׁגָּלְשׁוּ לָרֶדֶת מֵהַר הַגִּלְעָד כְּשֶׁהִשִׂיגָם לָבָן שָׁם. דָּבָר אַחֵר: כְּאוֹתָן שֶׁצָּבְאוּ עַל מִדְיָן בְּעֵבֶר הַיַּרְדֵּן שֶׁהִיא בְאֶרֶץ גִּלְעָד. וְלָשׁוֹן זֶה בְּמִדְרַשׁ שִׁיר הַשִּׁירִים:\",4,0],[2,138,4,1,\"מִבַּעַד. הוּא לְשׁוֹן מִבִּפְנִים, שֶׁרֹב \\\"בְּעַד\\\" שֶׁבַּמִּקְרָא דָבָר הַמֵּסֵךְ וּמֵגֵן נֶגֶד דָּבָר אַחֵר, כְּמוֹ \\\"וּבְעַד כּוֹכָבִים יַחְתּם\\\", \\\"הָאָרֶץ בְּרִיחֶיהָ בַעֲדִי\\\", \\\"הַבְעַד עֲרָפֶל\\\". וּ\\\"מִבַּעַד\\\" הוּא הַדָּבָר שֶׁהוּא מִבִּפְנִים לְאוֹתוֹ \\\"בְּעַד\\\". לְכָךְ הוּא אוֹמֵר \\\"מִבַּעַד\\\":\",5,0],[2,138,4,1,\"צַמָּתֵךְ. לְשׁוֹן דָּבָר הַמְצַמְצֵם הַשֵּׂעָר שֶׁלֹּא יַפְרִיחַ לָצֵאת, וְזוֹ הִיא הַשְּׂבָכָה וְהַקִּשּׁוּרִים. וְלֹא יִתָּכֵן לְפָרֵשׁ צַמָּתֵךְ לְשׁוֹן צֹמֶת, שֶׁתְּהֵא הַתי\\\"ו מֻשְׁרֶשֶׁת בַּתֵּבָה, שֶׁאִם כֵּן, הָיָה לָהּ לִהְיוֹת דְּגוּשָׁה כְּשֶׁהִיא נִסְמֶכֶת לְה\\\"א לִפְעֹל בָּהּ פְּעֻלַּת נְקֵבָה, אוֹ לְוי\\\"ו לִפְעֹל בּוֹ פְּעֻלַּת זָכָר כְּמוֹ תי\\\"ו שֶׁל שַׁבָּת, כְּשֶׁהוּא נוֹתְנָהּ לִנְקֵבָה הִיא מֻדְגֶּשֶׁת, כְּמוֹ \\\"חַגָּהּ, חָדְשָׁהּ, וְשַׁבַּתָּהּ\\\", וְכֵן לְזָכָר, \\\"עוֹלַת שַׁבַּת בְּשַׁבַּתּוֹ\\\". וְתי\\\"ו שֶׁל צַמָּתֵךְ שֶׁהִיא רָפָה, עַל כָּרְחֵנוּ בָאָה בִמְקוֹם ה\\\"א, וִיהֵא שֵׁם הַקִּשּׁוּר צַמָּה. וּכְשֶׁהוּא סָמוּךְ לְתִתּוֹ לְזָכָר אוֹ לִנְקֵבָה, תֵּהָפֵךְ הַה\\\"א לְתי\\\"ו רָפָה, כְּגוֹן שִׁפְחָה תֵהָפֵךְ לוֹמַר שִׁפְחָתוֹ, שִׁפְחָתָהּ. וְכֵן אָמָה, אֲמָתוֹ, אֲמָתָהּ. עֶרְוָה, עֶרְוָתוֹ, עֶרְוָתָהּ. וְכֵן זֶה: צַמָּה, צַמָּתוֹ, צַמָּתָהּ, צַמָּתִי, צַמָּתֵךְ:\",6,0],[2,138,4,1,\"שֶׁגָּלְשׁוּ. שֶׁנִּקְרְחוּ. גִּבֵּחַ מְתֻרְגָּם גְּלוֹשׁ. כְּשֶׁהַבְּהֵמוֹת יוֹרְדוֹת מִן הָהָר, נִמְצָא הָהָר נִקְרָח וּמְמֹרָט מֵהֶם:\",7,0],[2,138,4,2,\"שִׁנַּיִךְ כְּעֵדֶר הַקְּצוּבוֹת וגו'. אַף קִלּוּס זֶה בִלְשׁוֹן נוֹי אִשָּׁה:\",1,0],[2,138,4,2,\"שִׁנַּיִךְ. דַּקּוֹת וּלְבָנוֹת וּסְדוּרוֹת עַל סִדּוּרָן כְּצֶמֶר וְסֵדֶר עֵדֶר הָרְחֵלִים הַבְּרוּרוֹת מִשְּׁאָר הַצֹּאן בְּקֶצֶב וּמִנְיָן. נִמְסָרוֹת לְרוֹעֶה חָכָם וְהָגוּן לִזָּהֵר בְּצַמְרָן, שֶׁעוֹשִׂין אוֹתָן לִכְלֵי מֵילַת. וּמְשַׁמְּרִין אוֹתָן מֵעֵת לֵדָתָן שֶׁלֹּא יִתְלַכְלֵךְ הַצֶּמֶר, וְרוֹחֲצִין אוֹתָם מִיּוֹם אֶל יוֹם:\",2,0],[2,138,4,2,\"שֶׁכֻּלָּם מַתְאִימוֹת. לְשׁוֹן מְתם. \\\"אֵין מְתם בִּבְשָׂרִי\\\", כְּלוֹמַר: תְּמִימוֹת אינטרי\\\"ש בְּלַעַ\\\"ז:\",3,0],[2,138,4,2,\"וְשַׁכֻּלָה. שׁוּם שְׁכוֹל וּמוּם אֵין בָּהֶם. וְנֶאֱמַר הַדֻּגְמָא הַזּוּ עַל שֵׁם גִּבּוֹרֵי יִשְׂרָאֵל, הַכּוֹרְתִים וְאוֹכְלִים אוֹיְבֵיהֶם בְּשִׁנֵּיהֶם סְבִיבוֹתָם. וַהֲרֵי הֵם מִתְרַחֲקִין מִן הַגָּזֵל שֶׁל יִשְׂרָאֵל וּמִן הָעֲרָיוֹת, שֶׁלֹּא יִתְלַכְלְכוּ בַעֲבֵרָה. וְנֶאֱמַר קִלּוּס זֶה עַל שְׁנֵים עָשָׂר אֶלֶף אִישׁ שֶׁצָּבְאוּ עַל מִדְיָן בְּקֶצֶב וּמִנְיָן, שֶׁלֹּא נֶחְשַׁד אֶחָד מֵהֶם עַל הָעֲרָיוֹת, שֶׁנֶּאֱמַר \\\"וְלֹא נִפְקַד מִמֶּנּוּ אִישׁ\\\". וְאַף עַל הִרְהוּר הַלֵּב הֵבִיאוּ כַפָּרָתָן. וְאַף עַל הַגָּזֵל לֹא נֶחְשְׁדוּ, שֶׁהֵעִיד עֲלֵיהֶם הַכָּתוּב \\\"וַיִּקְחוּ אֶת כָּל הַשָּׁלָל וַיָּבִאוּ אֶל משֶׁה וְאֶל אֶלְעָזָר הַכֹּהֵן וגו'\\\". וְלֹא הִבְרִיחַ אֶחָד מֵהֶן פָּרָה אַחַת אוֹ חֲמוֹר אֶחָד:\",4,0],[2,138,4,3,\"כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ. נָאוֹת לְהַבְטִיחַ וְלִשְׁמֹר הַבְטָחָתָם, כְּמוֹ שֶׁעָשׂוּ הַמְרַגְּלִים לְרָחָב הַזּוֹנָה, שֶׁאָמְרוּ לָהּ \\\"אֶת תִּקְוַת חוּט הַשָּׁנִי וגו'\\\", וְשָׁמְרוּ הַבְטָחָתָם:\",1,0],[2,138,4,3,\"וּמִדְבָּרֵךְ. דִּבּוּרֵךְ, וַהֲרֵי הוּא מִגִּזְרַת \\\"הַנִּדְבָּרִים בְּךָ אֵצֶל הַקִּירוֹת\\\", \\\"אָז נִדְבְּרוּ יִרְאֵי ה'\\\". פרלדי\\\"ץ בְּלַעַ\\\"ז:\",2,0],[2,138,4,3,\"רַקָּתֵךְ. הִיא גֹבַהּ הַפָּנִים שֶׁקּוֹרִין פומילי\\\"ש בְּלַעַ\\\"ז אֵצֶל הָעֵינַיִם, וּבִלְשׁוֹן גְּמָרָא קוֹרִין אוֹתוֹ רוּמָנֵי דְאַפֵּי. וְדוֹמִין לְפֶלַח, חֲצִי רִמּוֹן מִבַּחוּץ שֶׁהוּא אָדֹם וּסְגַלְגַּל. הֲרֵי קִלּוּס בְּנוֹי אִשָּׁה. וְהַדֻּגְמָא פֵּרְשׁוּ רַבּוֹתֵינוּ: רֵיקָנִים שֶׁבֵּיךְ מְלֵאִים מִצְוֹת כְּרִמּוֹן:\",3,0],[2,138,4,3,\"מִבַּעַד לְצַמָּתֵךְ. מִבִּפְנִים לְקִשּׁוּרַיִךְ:\",4,0],[2,138,4,4,\"כְּמִגְדַּל דָּוִיד צַוָּארֵךְ. קוֹמָה זְקוּפָה נוֹי בְּאִשָּׁה. וְהַדֻּגְמָא \\\"כְּמִגְדַּל דָּוִד\\\", הוּא מְצוּדַת צִיּוֹן שֶׁהוּא מְקוֹם חֹזֶק וְעֹפֶל וּמִבְצָר, כָּךְ הוּא \\\"צַוָּארֵךְ\\\", זוּ לִשְׁכַּת הַגָּזִית, שֶׁהָיְתָה חָזְקָן וּמִבְצָרָן שֶׁל יִשְׂרָאֵל. וְאוֹתוֹ הַמִּגְדָּל \\\"בָּנוּי לְתַלְפִּיּוֹת\\\", בָּנוּי לְנוֹי, לִהְיוֹת הַכֹּל מִסְתַּכְּלִין בּוֹ לִלְמֹד צוּרוֹתָיו וְנוֹי מְלֶאכֶת תַּבְנִיתוֹ. וְהוּא מִגִּזְרַת: \\\"מַלְּפֵנוּ מִבַּהֲמוֹת אָרֶץ\\\", וְהַתי\\\"ו בְ\\\"תַלְפִּיּוֹת כְּמוֹ תי\\\"ו שֶׁבְּ\\\"תַּרְמִית\\\" וּבְ\\\"תַּבְנִית\\\":\",1,0],[2,138,4,4,\"אֶלֶף הַמָּגֵן תָּלוּי עָלָיו. כָּךְ מִנְהַג הַשָרִים לִתְלוֹת מָגִנֵּיהֶם וְשִׁלְטֵיהֶם בְּכָתְלֵי הַמִּגְדָּלִים:\",2,0],[2,138,4,4,\"שִׁלְטֵי. אַשְׁפּוֹת שֶׁנּוֹתְנִין בָּהֶם חִצִּים, כְּמוֹ: \\\"הָבֵרוּ הַחִצִּים מִלְאוּ הַשְּׁלָטִים\\\", וְדוֹמָה לוֹ לִשְׁכַּת הַגָּזִית, שֶׁמִּשָּׁם הוֹרָאָה יוֹצְאָה, שֶׁהַתּוֹרָה מָגֵן לְיִשְׂרָאֵל. וְיֵשׁ לוֹמַר, אֶלֶף הַמָּגֵן כְּמוֹ מָגֵן הָאֶלֶף, עַל שֵׁם \\\"דָּבָר צִוָּה לְאֶלֶף דּוֹר\\\":\",3,0],[2,138,4,4,\"כֹּל שִׁלְטֵי הַגִּבֹּרִים. מָצִינוּ שֶׁהַתַּלְמִידִים נִקְרָאִים עַל שֵׁם חִצִּים וּשְׁלָטִים, כְּעִנְיָן שֶׁנֶּאֱמַר \\\"כְּחִצִּים בְּיַד גִּבּוֹר כֵּן בְּנֵי הַנְּעוּרִים. אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם\\\":\",4,0],[2,138,4,5,\"שְׁנֵי שָׁדַיִךְ. הַמֵּינִיקוֹת אוֹתָךְ, זֶה משֶׁה וְאַהֲרֹן:\",1,0],[2,138,4,5,\"כִּשְׁנֵי עֳפָרִים תְּאוֹמֵי צְבִיָּה. דֶּרֶךְ צְבִיָּה לִהְיוֹת יוֹלֶדֶת תְּאוֹמִים. כָּךְ שְׁנֵיהֶם שָׁוִים, שְׁקוּלִים זֶה כָזֶה. דָּבָר אַחֵר: \\\"שְׁנֵי שָׁדַיִךְ\\\" עַל שֵׁם הַלּוּחוֹת \\\"תְּאוֹמֵי צְבִיָּה\\\" שֶׁהֵם מְכֻוָּנוֹת בְּמִדָּה אַחַת, וַחֲמִשָּׁה דִּבְּרוֹת עַל זוֹ וַחֲמִשָּׁה עַל זוֹ מְכֻוָּנִין דִּבּוּר כְּנֶגֶד דִּבּוּר: \\\"אָנֹכִי\\\" כְּנֶגֶד \\\"לֹא תִרְצַח\\\", שֶׁהָרוֹצֵחַ מְמַעֵט אֶת הַדְּמוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. \\\"לֹא יִהְיֶה לְךָ\\\" כְּנֶגֶד \\\"לֹא תִנְאָף\\\", שֶׁהַזּוֹנֶה אַחַר עֲבוֹדַת כּוֹכָבִים, דֶּרֶךְ אִשָּׁה הַמְנָאֶפֶת תַּחַת אִישָׁהּ תִּקַּח אֶת זָרִים. \\\"לֹא תִשָּׂא\\\" כְּנֶגֶד \\\"לֹא תִגְנֹב\\\", שֶׁהַגּוֹנֵב סוֹפוֹ לִשָּׁבַע לַשֶּׁקֶר. \\\"זָכוֹר\\\" כְּנֶגֶד \\\"לֹא תַעֲנֶה\\\", שֶׁהַמְחַלֵּל אֶת הַשַּׁבָּת מֵעִיד שֶׁקֶר בְּבוֹרְאוֹ, לוֹמַר שֶׁלֹּא שָׁבַת בְּשַׁבַּת בְּרֵאשִׁית. \\\"כַּבֵּד\\\" כְּנֶגֶד \\\"לֹא תַחְמֹד\\\", שֶׁהַחוֹמֵד סוֹפוֹ לְהוֹלִיד בֵּן שֶׁמַּקְלֶה אוֹתוֹ וּמְכַבֵּד לְמִי שֶׁאֵינוֹ אָבִיו:\",2,0],[2,138,4,5,\"הָרֹעִים. אֶת צֹאנָם בַּשּׁוֹשַׁנִּים וּמַדְרִיכִים אוֹתָם בְּדֶרֶךְ נוֹחָה וִישָׁרָה:\",3,0],[2,138,4,6,\"עַד שֶׁיָּפוּחַ הַיּוֹם. עַד שֶׁתִּתְפַּשֵּׁט הַחַמָּה:\",1,0],[2,138,4,6,\"וְנָסוּ הַצְּלָלִים. הִיא עֵת שָׁרָב וְחֹם הַיּוֹם אֲנִי אַצִּילֵךְ וְאַתְּ עֲרֵבָה עָלַי:\",2,0],[2,138,4,6,\"הַיּוֹם. הוּא הַשֶּׁמֶשׁ, וְכֵן \\\"לְרוּחַ הַיּוֹם\\\", וְכֵן \\\"כִּי הִנֵּה הַיּוֹם בָּא בֹּעֵר כַּתַּנּוּר\\\". וּמִשֶּׁיָּפוּחַ הַיּוֹם, \\\"אֵלֶךְ לִי בְהַר הַמּוֹרִיָּה\\\", בְּבֵית עוֹלָמִים. בִּבְרֵאשִׁית רַבָּה. כְּלוֹמַר: מִשֶּׁחָטְאוּ אָז לְפָנַי לְחַלֵּל אֶת קָדָשַׁי וְלִנְאֹץ מִנְחָתִי בִימֵי חָפְנִי וּפִנְחָס, אֶסְתַּלֵּק מֵעֲלֵיכֶם וְאֶטּשׁ מִשְׁכָּן הַזֶּה וְאֶבְחַר לִי בְהַר הַמּוֹרִיָּה, בְּבֵית עוֹלָמִים. וְשָׁם \\\"כֻּלָּךְ יָפָה . . . וּמוּם אֵין בָּךְ\\\", וְאֶרְצֶה שָׁם כָּל קָרְבְּנוֹתַיִךְ:\",3,0],[2,138,4,8,\"אִתִּי מִלְּבָנוֹן כַּלָּה. כְּשֶׁתִּגְלוּ מִלְּבָנוֹן זֶה, אִתִּי תִגְלוּ, כִּי אֲנִי אֶגְלֶה עִמָּכֶם:\",1,0],[2,138,4,8,\"אִתִּי מִלְּבָנוֹן תָּבוֹאִי. וּכְשֶׁתָּשׁוּבוּ מִן הַגּוֹלָה, אֲנִי אָשׁוּב עִמָּכֶם, וְאַף כָּל יְמֵי הַגּוֹלָה, בְּצָרָתֵךְ לִי צָר. וְעַל כֵּן כָּתַב, \\\"אִתִּי מִלְּבָנוֹן תָּבוֹאִי\\\", כְּשֶׁתִּגְלוּ מִלְּבָנוֹן זֶה, אִתִּי תָבוֹאִי, וְלֹא כָתַב, \\\"אִתִּי לִלְבָנוֹן תָּבוֹאִי\\\", לוֹמַר, מִשְּׁעַת יְצִיאַתְכֶם מִכָּאן עַד שְׁעַת בִּיאַתְכֶם כָּאן, אֲנִי עִמָּכֶם בְּכֹל אֲשֶׁר תֵּצְאוּ וְתָבוֹאוּ:\",2,0],[2,138,4,8,\"תָּשׁוּרִי מֵרֹאשׁ אֲמָנָה. בְּקַבְּצִי אֶת נִדָּחַיִךְ, תִּסְתַּכְּלִי וְתִתְבּוֹנְנִי מַה שְׂכַר פְּעֻלָּתֵךְ מֵרֵאשִׁית הָאֱמוּנָה שֶׁהֶאֱמַנְתְּ בִּי: לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר, וּמַסָּעוֹתַיִךְ וַחֲנִיּוֹתַיִךְ עַל פִּי, וּבִיאָתֵךְ לְרֹאשׁ שְׂנִיר וְחֶרְמוֹן שֶׁהָיוּ מְעוֹנוֹת אֲרָיוֹת, סִיחוֹן וְעוֹג. דָּבָר אַחֵר: \\\"מֵרֹאשׁ אֲמָנָה\\\", הַר הוּא בִּגְבוּל צְפוֹנָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל וּשְׁמוֹ אֲמָנָה, וּבִלְשׁוֹן מִשְׁנָה טוּרֵי אַמְנוֹן, וְהֹר הָהָר שֶׁנֶּאֱמַר בּוֹ \\\"מִן הַיָּם הַגָּדוֹל תְּתָאוּ לָכֶם הֹר הָהָר\\\". וּכְשֶׁהַגָּלֻיּוֹת נִקְבָּצוֹת וּמַגִּיעוֹת שָׁם, הֵם צוֹפִים מִשָּׁם וְרוֹאִין גְּבוּל אֶרֶץ יִשְׂרָאֵל וַאֲוִירָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל, וּשְׂמֵחִים וְאוֹמְרִים הוֹדָיָה. לְכָךְ נֶאֱמַר: \\\"תָּשׁוּרִי מֵרֹאשׁ אֲמָנָה\\\":\",3,0],[2,138,4,9,\"לִבַּבְתִּנִי. מָשַׁכְתְּ אֶת לִבִּי אֵלַיִךְ:\",1,0],[2,138,4,9,\"בְּאַחַת מֵעֵינַיִךְ. הַרְבֵּה דֻגְמוֹת טוֹבוֹת שֶׁבֵּיךְ, לוּלֵא הָיְתָה בֵיךְ אֶלָּא אַחַת מֵהֶן הָיִיתִי מְחַבְּבֵךְ בְּיוֹתֵר, וְכָל שֶׁכֵּן בְּכֻלָּן, וְכֵן: \\\"בְּאַחַד עֲנָק מִצַּוְּרֹנָיִךְ\\\", בְּאֶחָד מֵרְבִידֵי עַנְקֵי קִשּׁוּטַיִךְ. הֵם תַּכְשִׁיטֵי מִצְוָה שֶׁיִּשְׂרָאֵל מְצֻיָּנִין בָּהֶם. דָּבָר אַחֵר: \\\"בְּאַחַד עֲנָק\\\", בְּאֶחָד מֵאֲבוֹתַיִךְ, הוּא \\\"אֶחָד הָיָה\\\" מְיֻחָד, וְזֶה אַבְרָהָם הַנִּקְרָא עֲנָק: \\\"הָאָדָם הַגָּדוֹל בַּעֲנָקִים\\\":\",2,0],[2,138,4,10,\"מַה יָּפוּ דֹדַיִךְ. כָּל מָקוֹם שֶׁהֶרְאֵית לִי שָׁם חִבָּה יָפֶה הוּא בְעֵינַי: גִּלְגָּל, שִׁילֹה, נוֹב וְגִבְעוֹן, וּבֵית עוֹלָמִים. הוּא שֶׁיָּסַד הַבַּבְלִי: \\\"מְנוּחָה וּשְׁאָר וִעוּדִים\\\". \\\"מְנוּחָה\\\", זוּ יְרוּשָׁלַיִם. \\\"וּשְׁאָר וִעוּדִים\\\", מָקוֹם שֶׁנִּתְוַעֲדָה שָׁם שְׁכִינָה לְיִשְׂרָאֵל:\",1,0],[2,138,4,10,\"וְרֵיחַ שְׁמָנַיִךְ. שֵׁם טוֹב:\",2,0],[2,138,4,11,\"נֹפֶת. מָתוֹק:\",1,0],[2,138,4,11,\"תִּטֹּפְנָה שִׂפְתוֹתַיִךְ. טַעֲמֵי תוֹרָה:\",2,0],[2,138,4,11,\"וְרֵיחַ שַׂלְמֹתַיִךְ. מִצְוֹת הֲגוּנוֹת הַנּוֹהֲגוֹת בְּשַׂלְמוֹתַיִךְ: צִיצִית, תְּכֵלֶת, בִּגְדֵי כְהֻנָּה, אִסּוּר שַׁעַטְנֵז:\",3,0],[2,138,4,12,\"גַּן נָעוּל. עַל שֵׁם צְנִיעוּת בְּנוֹת יִשְׂרָאֵל שֶׁאֵין פְּרוּצוֹת בַּעֲרָיוֹת:\",1,0],[2,138,4,12,\"גַּל נָעוּל. יֵשׁ לְפָרְשׁוֹ לְשׁוֹן מַעְיָן כְּמוֹ \\\"גֻּלּוֹת עִלִּיּוֹת\\\". וְיֵשׁ לְפָרְשׁוֹ לְשׁוֹן שַׁעַר, וְהוּא לָשׁוֹן אֲרַמִּי, בַּתַּלְמוּד: \\\"טְרוֹקוּ גַלֵּי\\\":\",2,0],[2,138,4,13,\"שְׁלָחַיִךְ. אֶרֶץ יְבֵשָׁה קְרוּיָה בֵּית הַשְּׁלָחִין, וְצָרִיךְ לְהַשְׁקוֹתָהּ תָּמִיד. וּשְׂדֵה בֵית הַבַּעַל יָפֶה הֵימֶנָּה. וְכָאן קִלֵּס הַיָּבֵשׁ, שְׁלָחַיִךְ הֲרֵי הֵן מְלֵאִין כָּל טוּב כְּפַרְדֵּס רִמּוֹנִים. וְזֶה עַל שֵׁם קְטַנִּים שֶׁבְּיִשְׂרָאֵל מַרְטִיבִים מַעֲשִׂים טוֹבִים כְּפַרְדֵּס רִמּוֹנִים:\",1,0],[2,138,4,13,\"כְּפָרִים עִם נְרָדִים. מִינֵי בְשָׂמִים הֵם:\",2,0],[2,138,4,15,\"מַעְיַן גַּנִּים. כָּל זֶה מוּסָב עַל \\\"שְׁלָחַיִךְ\\\", וּמְקַלְּסָן כְּמַעְיָן הַמַּשְׁקֶה אוֹתָן. וְהַדֻּגְמָא: עַל שֵׁם טְבִילוֹת טֹהַר שֶׁבְּנוֹת יִשְׂרָאֵל טוֹבְלוֹת:\",1,0],[2,138,4,15,\"וְנֹזְלִים מִן לְבָנוֹן. מִמְּקוֹם נְקִיּוּת בְּאֵין עֲכִירַת טִיט:\",2,0],[2,138,4,16,\"עוּרִי צָפוֹן וּבוֹאִי תֵימָן. אַחַר שֶׁעָרַב עָלַי רֵיחֵךְ וְנוֹי מִשְׁכְּנוֹתַיִךְ, אֲנִי מְצַוֶּה אֶת הָרוּחוֹת צָפוֹן וְתֵימָן לְהָפִיחַ בְּגַנֵּךְ לָצֵאת רֵיחֵךְ הַטּוֹב לְמֵרָחוֹק, וְהַדֻּגְמָא: עַל שֵׁם שֶׁהַגָּלֻיּוֹת מִתְקַבְּצוֹת, וּמִכָּל הַגּוֹיִם מְבִיאִים אוֹתָם מִנְחָה לִירוּשָׁלַיִם, וּבִימֵי הַבִּנְיָן יִהְיוּ יִשְׂרָאֵל נִקְבָּצִים שָׁם לְמוֹעֲדִים וְלִרְגָלִים, וְיִשְׂרָאֵל מְשִׁיבִין: \\\"יָבֹא דוֹדִי לְגַנּוֹ\\\", אִם אַתָּה שָׁם הַכֹּל שָׁם:\",1,0],[2,138,5,1,\"בָּאתִי לְגַנִּי. בִּימֵי חֲנֻכַּת הַבָּיִת:\",1,0],[2,138,5,1,\"אָרִיתִי. לָקַטְתִּי, וְהוּא לְשׁוֹן מִשְׁנָה: \\\"כִּמְלֹא אוֹרֶה וְסַלּוֹ\\\", וְאַף לְשׁוֹן מִקְרָא \\\"וְאָרוּהָ כָּל עֹבְרֵי דָרֶךְ\\\". וְנֶאֱמַר עַל שֵׁם הַקְּטֹרֶת, שֶׁהִקְטִירוּ קְטֹרֶת יָחִיד הַנְּשִׂיאִים עַל מִזְבֵּחַ הַחִיצוֹן וְנִתְקַבְּלָה, וְהוּא דָבָר שֶׁאֵינוֹ נוֹהֵג לְדוֹרוֹת. וְעַל כֵּן נֶאֱמַר: \\\"אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי\\\". יֵשׁ דְּבַשׁ שֶׁהוּא גָדֵל בְּקָנִים, כְּעִנְיָן שֶׁנֶּאֱמַר: \\\"בְּיַעְרַת הַדְּבָשׁ\\\". וְ\\\"יַעְרַת\\\" הִיא לְשׁוֹן קָנֶה, כְּמוֹ \\\"וַתָּשֶׂם בַּסּוּף\\\", וְשַׁוִּיתָהּ בְּיַעֲרָא. וּמוֹצְצִין הַדְּבַשׁ וּמַשְׁלִיכִין הָעֵץ. וַאֲנִי מֵרֹב חִבָּה \\\"אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי\\\", אָכַלְתִּי הַקָּנֶה עִם הַדְּבַשׁ, אֶת שֶׁאֵינוֹ רָאוּי עִם הָרָאוּי, קְטֹרֶת נְדָבָה, וְכֵן שְׂעִירֵי חַטָּאת שֶׁהִקְרִיבוּ הַנְּשִׂיאִים, וְאֵין חַטָּאת קְרֵבָה נְדָבָה, וַאֲנִי קִבַּלְתִּים בּוֹ בַיּוֹם:\",2,0],[2,138,5,1,\"שָׁתִיתִי יֵינִי. הֵם הַנְּסָכִים:\",3,0],[2,138,5,1,\"עִם חֲלָבִי. מָתְקוּ וְצַחוּ מֵחָלָב:\",4,0],[2,138,5,1,\"אִכְלוּ רֵעִים. בְּאֹהֶל מוֹעֵד אַהֲרֹן וּבָנָיו, וּבְבֵית עוֹלָמִים הַכֹּהֲנִים כֻּלָּם:\",5,0],[2,138,5,1,\"שְׁתוּ וְשִׁכְרוּ דּוֹדִים. אֵלּוּ יִשְׂרָאֵל אוֹכְלֵי בְשַׂר זֶבַח הַשְּׁלָמִים שֶׁהִקְרִיבוּ לַחֲנֻכַּת הַמִּזְבֵּחַ:\",6,0],[2,138,5,2,\"אֲנִי יְשֵׁנָה. כְּשֶׁהָיִיתִי שְׁלֵוָה וּשְׁקֵטָה בְּבַיִת רִאשׁוֹן, נוֹאַשְׁתִּי מֵעֲבֹד הַקָּדוֹשׁ בָּרוּךְ הוּא כִּישֵׁנָה וְנִרְדָּמֶת:\",1,0],[2,138,5,2,\"וְלִבִּי עֵר. זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. כָּךְ נִדְרַשׁ בִּפְסִיקְתָּא:\",2,0],[2,138,5,2,\"וְלִבִּי עֵר. הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא צוּר לְבָבִי וְחֶלְקִי עֵר לְשָׁמְרֵנִי וּלְהֵיטִיב לִי:\",3,0],[2,138,5,2,\"קוֹל דּוֹדִי דוֹפֵק. מַשְׁרֶה שְׁכִינָתוֹ עַל הַנְּבִיאִים וּמַזְהִיר עַל יְדֵיהֶם הַשְׁכֵּם וְשָׁלוֹחַ:\",4,0],[2,138,5,2,\"פִּתְחִי לִי. אַל תִּגְרְמִי לִי שֶׁאֶסְתַּלֵּק מֵעָלַיִךְ:\",5,0],[2,138,5,2,\"שֶׁרֹאשִׁי נִמְלָא טָל. לְשׁוֹן אָדָם שֶׁבָּא בַלַּיְלָה דּוֹפֵק עַל פֶּתַח אֲהוּבָתוֹ. אוֹמֵר כֵּן: \\\"בִּשְׁבִיל חִבָּתֵךְ בָּאתִי בַּלַּיְלָה בְּעֵת הַטַּל אוֹ הַגֶּשֶׁם\\\". וְהַדֻּגְמָא: \\\"שֶׁרֹאשִׁי נִמְלָא טָל\\\" שֶׁאֲנִי מָלֵא רָצוֹן וְנַחַת רוּחַ אַבְרָהָם אָבִיךְ, שֶׁעָרְבוּ עָלַי מַעֲשָׂיו כַּטַּל, וְהִנְנִי בָא אֵלַיִךְ טָעוּן בְּרָכוֹת וְשִׁלּוּם שְׂכַר מַעֲשִׂים טוֹבִים אִם תָּשׁוּבִי אֵלָי:\",6,0],[2,138,5,2,\"קְוֻצּוֹתַי רְסִיסֵי לָיְלָה. אַף בְּיָדִי הַרְבֵּה קְבוּצוֹת מִינֵי פֻרְעָנִיּוֹת לִפָּרַע מֵעוֹזְבַי וּמִמְּנַאֲצַי. \\\"טַל\\\" הוּא לְשׁוֹן נַחַת:\",7,0],[2,138,5,2,\"רְסִיסֵי לָיְלָה. גִּשְׁמֵי לַיְלָה שֶׁהֵן טוֹרַח וַעֲיֵפוּת. \\\"רְסִיסֵי\\\" תַּרְגּוּם שֶׁל \\\"רְבִיבִים\\\", \\\"וְכִרְבִיבִים עֲלֵי עֵשֶׂב,\\\" \\\"וְכִרְסִיסֵי מַלְקוֹשָׁא\\\" קְווּצּוֹת הֵן דִּבּוּקֵי שַׂעֲרוֹת הָרֹאשׁ הַמְדֻבָּקִים יַחַד שֶׁקּוֹרִין פלוצייל\\\"ש. וּלְפִי שֶׁאָחַז הַמִּקְרָא בִלְשׁוֹן טַל וּמָטָר, אָחַז בִּלְשׁוֹן רֹאשׁ וּקְוֻצּוֹת, שֶׁדֶּרֶךְ טַל וּמָטָר לְהֵאָחֵז בַּשֵׂעָר וּבַקְּוֻצּוֹת. וְיֵשׁ לְפָרֵשׁ \\\"טַל וּרְסִיסֵי לָיְלָה\\\" שְׁנֵיהֶם לְטוֹבָה שְׂכַר מִצְוֹת קַלּוֹת הַנּוֹחוֹת לְהֵעָשׂוֹת כְּטַל, וּשְׂכַר מִצְוֹת חֲמוּרוֹת הַקָּשׁוֹת כְּטוֹרַח רְסִיסֵי לָיְלָה:\",8,0],[2,138,5,3,\"פָּשַׁטְתִּי אֶת כֻּתָּנְתִּי. כְּלוֹמַר, כְּבָר לִמַּדְתִּי לְעַצְמִי דְרָכִים אֲחֵרִים; לֹא אוּכַל לָשׁוּב אֵלֶיךָ עוֹד, כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"וּמִן אָז חָדַלְנוּ לְקַטֵּר לִמְלֶכֶת הַשָּׁמַיִם וגו'\\\" שֶׁהָיוּ הַדְּרָכִים הָאֵלֶּה יְשָׁרִים בְּעֵינֵיהֶם. וּלְשׁוֹן \\\"פָּשַׁטְתִּי אֶת כֻּתָּנְתִּי, רָחַצְתִּי אֶת רַגְלַי\\\", לְשׁוֹן תְּשׁוּבַת הָאִשָּׁה הַמְנָאֶפֶת שֶׁאֵינָהּ רוֹצָה לִפְתּוֹחַ לְבַעְלָהּ הַדָּלֶת, וּלְפִי שֶׁפָּתַח הַכָּתוּב בִּלְשׁוֹן \\\"אֲנִי יְשֵׁנָה, קוֹל דּוֹדִי דוֹפֵק\\\", סִיֵּם בִּלְשׁוֹן תְּשׁוּבָה הַנּוֹפֶלֶת עַל לְשׁוֹן דּוֹפֵק עַל הַדֶּלֶת בְּעֵת מִשְׁכַּב הַשֵּׁנָה בַלֵּילוֹת:\",1,0],[2,138,5,4,\"דּוֹדִי שָׁלַח יָדוֹ מִן הַחוֹר. שֶׁאֵצֶל הַדֶּלֶת, וְרָאִיתִי יָדוֹ, וְנֶהֶפְכוּ עָלַי הֲמוֹן מֵעַי לָשׁוּב לְאַהֲבָתוֹ וְלִפְתּחַ לוֹ:\",1,0],[2,138,5,5,\"קַמְתִּי אֲנִי לִפְתּחַ לְדוֹדִי וְיָדַי נָטְפוּ מוֹר. כְּלוֹמַר, בְּלֵב שָׁלֵם וְנֶפֶשׁ חֲפֵצָה, כִּמְקַשֶּׁטֶת עַצְמָהּ לְהִתְאַהֵב עַל אִישָׁהּ בְּרֵיחַ טוֹב:\",1,0],[2,138,5,5,\"מוֹר עֹבֵר. רֵיחַ עוֹבֵר וּמִתְפַּשֵּׁט לְכָל צַד:\",2,0],[2,138,5,6,\"וְדוֹדִי חָמַק עָבָר. נִסְתַּר וְנִכְסָה מִמֶּנִּי, כְּמוֹ \\\"חַמּוּקֵי יְרֵכַיִךְ\\\", סִתְרֵי יְרֵכַיִךְ, עַל שֵׁם שֶׁהַיָּרֵךְ בַּסֵּתֶר. \\\"עַד מָתַי תִּתְחַמָּקִין\\\", תִּסָּתְרִי וְתִתְכַּסִּי מֵחֲמַת בּוּשָׁה שֶׁמָּעַלְתְּ בִּי:\",1,0],[2,138,5,6,\"נַפְשִׁי יָצְאָה בְדַבְּרוֹ. שֶׁאָמַר \\\"לֹא אָבֹא אֶל בֵּיתֵךְ, כִּי מִתְּחִלָּה לֹא אָבִית לִפְתּוֹחַ\\\".\",2,0],[2,138,5,7,\"בִּקַּשְׁתִּיהוּ וגו': מְצָאֻנִי הַשֹּׁמְרִים הַסֹּבְבִים בָּעִיר. וְתוֹפְסִין גַּנָּבִים הַמְהַלְּכִים בַּלֵּילוֹת:\",1,0],[2,138,5,7,\"הִכּוּנִי פְצָעוּנִי. חָבְלוּ בִי חַבּוּרָה. כָּל פֶּצַע, לְשׁוֹן מַכַּת כְּלִי זַיִן הוּא, נברדור\\\"א בְּלַעַ\\\"ז:\",2,0],[2,138,5,7,\"רְדִידִי. עֶדְיִי הַמְרוּדָּד וְהַמְרוּקָּע עָלַי, וְכֵן כָּל הָעִנְיָן לְשׁוֹן אֵשֶׁת נְעוּרִים הַמִּתְאוֹנֶנֶת עַל בַּעַל נְעוּרֶיהָ וּמְבַקַּשְׁתּוֹ. וְזוּ הִיא הַדֻּגְמָא:\",3,0],[2,138,5,7,\"דּוֹדִי שָלַח יָדוֹ מִן הַחוֹר. כְּשֶׁאָמַרְתִּי, \\\"רָחַצְתִּי אֶת רַגְלַי וְלֹא אֶפְתַּח לְךָ, וְלֹא אָשׁוּב מִן עֲבוֹדַת אֱלִילִים שֶׁבָּחַרְתִּי בָהּ\\\":\",4,0],[2,138,5,7,\"שָׁלַח יָדוֹ. וְהֶרְאָה נִקְמָתוֹ בִימֵי אָחָז, וְהֵבִיא עָלָיו חֵיל מֶלֶךְ אֲרָם, \\\"וַיַּכּוּ בוֹ וַיִּשְׁבּוּ מִמֶּנּוּ שִׁבְיָה גְדוֹלָה וגו' וַיַּהֲרֹג פֶּקַח בֶּן רְמַלְיָהוּ בִּיהוּדָה מֵאָה וְעֶשְׂרִים אֶלֶף בְּיוֹם אֶחָד\\\":\",5,0],[2,138,5,7,\"וּמֵעַי הָמוּ עָלָיו. בָּא חִזְקִיָּהוּ בְנוֹ וְשָׁב בְּכָל לְבָבוֹ לִדְרוֹשׁ לְהַקָּדוֹשׁ בָּרוּךְ הוּא כָל דּוֹרוֹ שְׁלֵמִים, לֹא קָם דּוֹר בְּיִשְׂרָאֵל כְּמוֹתָם, כְּמוֹ שֶׁמְּפוֹרָשׁ בְּחֵלֶק: \\\"בָּדְקוּ מִדָּן וְעַד בְּאֵר שֶׁבַע וְלֹא מָצְאוּ עַם הָאָרֶץ, מִגַּבַּת וְעַד אַנְטוֹכְיָא, וְלֹא מָצְאוּ אִישׁ וְאִשָּׁה שֶׁאֵין בְּקִיאִין בְּהִלְכוֹת טֻמְאָה וְטָהֳרָה\\\". וְזֶהוּ: \\\"וְיָדַי נָטְפוּ מוֹר וגו'\\\". אַף יֹאשִׁיָּהוּ נֶאֱמַר בּוֹ \\\"וְכָמוֹהוּ לֹא הָיָה לְפָנָיו מֶלֶךְ\\\", כִּי רָאָה פוּרְעָנוּת שֶׁבָּאָה עַל מְנַשֶּׁה וְעַל אָמוֹן, לְקַיֵּם: \\\"שָׁלַח יָדוֹ מִן הַחוֹר וּמֵעַי הָמוּ עָלָיו\\\":\",6,0],[2,138,5,7,\"פָּתַחְתִּי אֲנִי לְדוֹדִי וְדוֹדִי חָמַק עָבָר. לֹא בִטֵּל גְּזֵרָתוֹ, שֶׁנֶּאֱמַר בְּחִזְקִיָּהוּ, \\\"הִנֵּה יָמִים בָּאִים וְנִשָּׂא כָּל אֲשֶׁר בְּבֵיתֶךָ וגו'. וּמִבָּנֶיךָ אֲשֶׁר תּוֹלִיד\\\" אֵלּוּ דָנִיֵּאל, חֲנַנְיָה, מִישָׁאֵל וַעֲזַרְיָה; וְאַף בְּיֹאשִׁיָּהוּ עַל יְדֵי חֻלְדָּה הַנְּבִיאָה \\\"הִנְנִי מֵבִיא רָעָה אֶל הַמָּקוֹם הַזֶּה וְעַל ישְׁבָיו וגו'\\\", וְאוֹמֵר, \\\"וְכָמֹהוּ לֹא הָיָה לְפָנָיו מֶלֶךְ וגו'. אַךְ לֹא שָׁב ה' מֵחֲרוֹן אַפּוֹ הַגָּדוֹל אֲשֶׁר חָרָה אַפּוֹ בִּיהוּדָה עַל כָּל הַכְּעָסִים אֲשֶׁר הִכְעִיסוֹ מְנַשֶּׁה. וַיֹּאמֶר ה', 'גַּם אֶת יְהוּדָה אָסִיר מֵעַל פָּנַי כַּאֲשֶׁר הֲסִרֹתִי אֶת יִשְׂרָאֵל וּמָאַסְתִּי אֶת הָעִיר הַזֹּאת'\\\":\",7,0],[2,138,5,7,\"נַפְשִׁי יָצְאָה בְדַבְּרוֹ. יָצְאָה מִמֶּנִּי בְדַבְּרוֹ דָבָר זֶה:\",8,0],[2,138,5,7,\"בִּקַּשְׁתִּיהוּ וְלֹא מְצָאתִיהוּ. וְאִם תּאמַר, \\\"וַהֲלֹא יִרְמְיָה עוֹמֵד וּמִתְנַבֵּא בִימֵי יְהוֹיָקִים וְצִדְקִיָּהוּ, 'שׁוּבוּ אֵלַי וְאָשׁוּבָה אֲלֵיכֶם'\\\", לֹא לְבַטֵּל הַגְּזֵרָה, אֶלָּא לְהָקֵל הַפֻּרְעָנוּת וּלְהָכִין מַלְכוּתָם בְּשׁוּבָם מִן הַגּוֹלָה, לְנָטְעָם מֵאֵין נְתִישָׁה וְלִבְנוֹתָם מֵאֵין הוֹרֵס:\",9,0],[2,138,5,7,\"מְצָאֻנִי הַשֹּׁמְרִים. נְבוּכַדְנֶאצַּר וְחֵילוֹתָיו:\",10,0],[2,138,5,7,\"הַסֹּבְבִים בָּעִיר. לִנְקוֹם נִקְמָתוֹ שֶׁל מָקוֹם:\",11,0],[2,138,5,7,\"נָשְׂאוּ אֶת רְדִידִי. בֵּית הַמִּקְדָּשׁ:\",12,0],[2,138,5,7,\"שֹׁמְרֵי הַחֹמוֹת. אַף מַלְאֲכֵי הַשָּׁרֵת שֶׁהָיוּ שׁוֹמְרִים חוֹמוֹתֶיהָ כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"עַל חוֹמֹתַיִךְ יְרוּשָׁלַיִם וגו'\\\" הֵם הִצִּיתוּ בּוֹ אֶת הָאוּר, כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"מִמָּרוֹם שָׁלַח אֵשׁ וגו'\\\":\",13,0],[2,138,5,8,\"הִשְׁבַּעְתִּי אֶתְכֶם. הָאֻמּוֹת: אַנְשֵׁי נְבוּכַדְנֶאצַּר שֶׁרְאִיתֶם בַּחֲנַנְיָה, מִישָׁאֵל וַעֲזַרְיָה מוֹסְרִים עַצְמָם לְכִבְשַׁן הָאֵשׁ, וְאֶת דָּנִיֵּאל לְגוֹב אֲרָיוֹת עַל עִסְקֵי הַתְּפִלָּה, וְאֶת דּוֹרוֹ שֶׁל מָרְדְּכַי בִּימֵי הָמָן:\",1,0],[2,138,5,8,\"אִם תִּמְצְאוּ אֶת דּוֹדִי. לֶעָתִיד לָבוֹא לְיוֹם הַדִּין, שֶׁיְּבֻקַּשׁ מִכֶּם לְהָעִיד עָלַי, כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"יִתְּנוּ עֵדֵיהֶם וְיִצְדָּקוּ\\\":\",2,0],[2,138,5,8,\"מַה תַּגִּידוּ לוֹ. שֶׁתָּעִידוּ עָלַי שֶׁבִּשְׁבִיל אַהֲבָתוֹ חָלִיתִי בְּיִסּוּרִים קָשִׁים בֵּינֵיכֶם. יָבֹא נְבוּכַדְנֶאצַּר וְיָעִיד, יָבֹא אֱלִיפַז וְצוֹפַר וְכָל נְבִיאֵי הָאֻמּוֹת, וְיָעִידוּ עָלַי שֶׁקִּיַּמְתִּי אֶת הַתּוֹרָה:\",3,0],[2,138,5,9,\"מַה דּוֹדֵךְ מִדּוֹד. כָּךְ הָיוּ שׁוֹאֲלִין הָאֻמּוֹת אֶת יִשְׂרָאֵל, \\\"מַָה אֱלֹהֵיכֶם מִכָּל הָאֱלֹהִים שֶׁכָּךְ אַתֶּם נִשְׂרָפִים וְנִצְלָבִים עָלָיו\\\"?\",1,0],[2,138,5,9,\"שֶׁכָּכָה הִשְׁבַּעְתָּנוּ. לְהָעִיד לוֹ עַל אַהֲבָתֵךְ:\",2,0],[2,138,5,10,\"דּוֹדִי צַח. לָבָן, כְּמוֹ \\\"צַחוּ מֵחָלָב\\\":\",1,0],[2,138,5,10,\"וְאָדוֹם. אֲפָרֵשׁ תְּחִלָּה כָל הָעִנְיָן לְפִי פְשׁוּטוֹ, בְּקִילוּס נוֹי בָּחוּר כְּשֶׁהוּא לָבָן וּפָנָיו אַדְמוֹנִיּוֹת:\",2,0],[2,138,5,10,\"דָּגוּל מֵרְבָבָה. נִדְגָּל בַּחֲיָלוֹת הַרְבֵּה, רַבִּים חֲיָלוֹתָיו. רְבָבוֹת הַרְבֵּה קְרוּיִין רְבָבָה, שֶׁנֶּאֱמַר \\\"רְבָבָה כְּצֶמַח הַשָׂדֶה נְתַתִּיךְ\\\":\",3,0],[2,138,5,11,\"רֹאשׁוֹ. מַבְהִיק כְּכֶתֶם פָּז. כֶּתֶם הוּא לְשׁוֹן סְגֻלַּת מְלָכִים שֶׁאוֹצְרִין בְּבֵית גִּנְזֵיהֶם, וְכֵן \\\"יִשְׁנֶא הַכֶּתֶם הַטּוֹב\\\", וְכֵן \\\"וְלַכֶּתֶם אָמַרְתִּי מִבְטַחִי\\\", וְכֵן \\\"וַחֲלִי כָתֶם\\\":\",1,0],[2,138,5,11,\"קְוֻצּוֹתָיו תַּלְתַּלִּים. לְשׁוֹן תְּלוּיִים, פנדלויי\\\"ש בְּלַעַ\\\"ז:\",2,0],[2,138,5,11,\"שְׁחֹרוֹת כָּעוֹרֵב. כָּל אֵלֶּה נוֹי לְבָחוּר:\",3,0],[2,138,5,12,\"עֵינָיו כְּיוֹנִים עַל אֲפִיקֵי מָיִם. עֵינָיו עַל אֲפִיקֵי מַיִם נָאוֹת כְּעֵינֵי יוֹנִים. אֲפִיקֵי מַיִם עֲרֵבִים לְמַרְאֶה, וְהַבַּחוּרִים יוֹצְאִים שָׁם לָשׁוּט. וְכֵן מְקַלֵּס הַמְשׁוֹרֵר: עֵינֵי דוֹדִי, כְּשֶׁהוּא מַבִּיט עַל אֲפִיקֵי מַיִם, דּוֹמוֹת לְנוֹי עֵינֵי יוֹנִים:\",1,0],[2,138,5,12,\"רֹחֲצוֹת. עֵינֵי דוֹדִי בֶּחָלָב:\",2,0],[2,138,5,12,\"ישְׁבוֹת עַל מִלֵּאת. כָּל זֶה לְשׁוֹן נוֹי. לֹא בוֹלְטוֹת יוֹתֵר מִדַּאי וְלֹא שׁוֹקְעוֹת, אֶלָּא יוֹשְׁבוֹת עַל מִלֵּאת, גּוּמָא שֶׁלָּהֶם. (סְפָרִים אֲחֵרִים: הָעַיִן לְפִי הַגּוּמָא.) הָעִנְיָן לְפִי הַדֻּגְמָא. וְהוּא לְשׁוֹן כָּל דָּבָר שֶׁעָשׂוּי לְמַלּוֹאת גּוּמָא הָעֲשׂוּיָה לוֹ לְמוֹשָׁב כְּמוֹ \\\"אַבְנֵי מִלֻּאִים\\\", \\\"וּמִלֵּאתָ בוֹ מִלֻּאַת אֶבֶן\\\":\",3,0],[2,138,5,13,\"לְחָיָו כַּעֲרוּגַת הַבֹּשֶׂם. אֲשֶׁר שָׁם בְּאוֹתָם עֲרוּגוֹת גִּדּוּלֵי מֶרְקָחִים:\",1,0],[2,138,5,13,\"מִגְדְּלוֹת מֶרְקָחִים. מִגְדָּלוֹת שֶׁל מֶרְקָחִים, גִּדּוּלֵי בְשָׂמִים שֶׁמְּפַטְּמִים אוֹתָם מַעֲשֵׂה רוֹקֵחַ:\",2,0],[2,138,5,14,\"גְּלִילֵי זָהָב. כְּאוֹפַנֵּי זָהָב:\",1,0],[2,138,5,14,\"מְמֻלָּאִים בַּתַּרְשִׁישׁ. כָּל לְשׁוֹן מוֹשַׁב אֶבֶן יְקָרָה בְזָהָב קָרוּי מִלֵּאת:\",2,0],[2,138,5,14,\"עֶשֶׁת. לְשׁוֹן \\\"שָׁמְנוּ עָשְׁתוּ\\\". קִבּוּץ עָב קָרוּי עֶשֶׁת מששאי\\\"ה בְּלַעַ\\\"ז:\",3,0],[2,138,5,14,\"שֵׁן. מֵעַצְמוֹת פִּיל:\",4,0],[2,138,5,14,\"מְעֻלֶּפֶת סַפִּירִים. מְקוּשֶּׁטֶת וּמְתוּקֶּנֶת בְּסַפִּירִים, לְשׁוֹן \\\"וַתִּתְעַלָּף\\\", דִּמְתַרְגְּמִינָן וְאִתַּקְנַת:\",5,0],[2,138,5,15,\"שׁוֹקָיו. כְּעַמּוּדֵי שֵׁשׁ הַמְיֻסָּדִים עַל אַדְנֵי פָז:\",1,0],[2,138,5,15,\"עַמּוּדֵי שֵׁשׁ. עַמּוּדֵי שַׁיִשׁ, וַחֲבֵרוֹ בִמְגִלַּת אֶסְתֵּר, \\\"עַל גְּלִילֵי כֶסֶף וְעַמּוּדֵי שֵׁשׁ\\\". וּמַרְאֵהוּ גָּבוֹהַּ כְּאַרְזֵי הַלְּבָנוֹן:\",2,0],[2,138,5,15,\"בָּחוּר כָּאֲרָזִים. נִבְחָר בֵּין הַבָּנִים כְּאֶרֶז בֵּין שְׁאָר עֵצִים:\",3,0],[2,138,5,16,\"חִכּוֹ מַמְתַקִּים. דְּבָרָיו עֲרֵבִים:\",1,0],[2,138,5,16,\"זֶה דוֹדִי. זֶה דְמוּת דּוֹדִי וְזֶה דְמוּת רֵעִי, וְעַל כָּל אֵלֶּה חָלִיתִי לְאַהֲבָתוֹ. וְהַדֻּגְמָא כְּלַפֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּךְ הִיא:\",2,0],[2,138,5,16,\"דּוֹדִי צַח. וְלָבָן לְהַלְבִּין עֲוֹנוֹתָי. צַח וְלָבָן כְּשֶׁנִּרְאָה בְסִינַי נִרְאָה כְזָקֵן מוֹרֶה הוֹרָאוֹת, וְכֵן בְּשִׁבְתּוֹ לַמִּשְׁפָּט \\\"לְבוּשֵׁיהּ כִּתְלַג חִוָּר וּשְׂעַר רֵאשֵׁהּ כַּעֲמַר נְקֵא\\\":\",3,0],[2,138,5,16,\"וְאָדוֹם. לִיפָּרַע מִשׂוֹנְאָיו כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"מַדּוּעַ אָדֹם לִלְבוּשֶׁךָ\\\":\",4,0],[2,138,5,16,\"דָּגוּל מֵרְבָבָה. הַרְבֵּה חֲיָלוֹת מַקִּיפִין אוֹתוֹ:\",5,0],[2,138,5,16,\"רֹאשׁוֹ כֶּתֶם פָּז. תְּחִלַּת דְּבָרָיו הִבְהִיקוּ כְּכֶתֶם פָּז, וְכֵן הוּא אוֹמֵר, \\\"פֵּתַח דְּבָרֶיךָ יָאִיר\\\". פָּתַח: \\\"אָנֹכִי ה' אֱלֹהֶיךָ\\\"; הֶרְאָם תְּחִלָּה שֶׁמִּשְׁפַּט מְלוּכָה יֵשׁ לוֹ עֲלֵיהֶם, וְאַחַר כָּךְ גָּזַר עֲלֵיהֶם גְּזֵרוֹתָיו:\",6,0],[2,138,5,16,\"קְוֻצּוֹתָיו תַּלְתַּלִּים. עַל כָּל קוֹץ וְקוֹץ תִּלֵּי תִלִּים שֶׁל הֲלָכוֹת:\",7,0],[2,138,5,16,\"שְׁחֹרוֹת כָּעוֹרֵב. עַל שֵׁם שֶׁהָיְתָה כְתוּבָה לְפָנָיו אֵשׁ שְׁחוֹרָה עַל גַּבֵּי אֵשׁ לְבָנָה. דָּבָר אַחֵר: \\\"קְוֻצּוֹתָיו תַּלְתַּלִּים\\\" כְּשֶׁנִּרְאָה עַל הַיָּם, נִרְאָה כְּבָחוּר נִלְחָם בִּגְבוּרָה:\",8,0],[2,138,5,16,\"עֵינָיו כְּיוֹנִים עַל אֲפִיקֵי מָיִם. כְּיוֹנִים שֶׁעֵינֵיהֶם צוֹפוֹת אֶל אֲרֻבּוֹתֵיהֶם, כָּךְ עֵינָיו עַל בָּתֵּי כְנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, שֶׁשָּׁם מוֹצָאֵי הַתּוֹרָה הַמְשׁוּלִים לְמָיִם:\",9,0],[2,138,5,16,\"רֹחֲצוֹת בֶּחָלָב. כְּשֶׁהֵן צוֹפוֹת בַּמִּשְׁפָּט, מְבָרְרוֹת דִּין לַאֲמִתּוֹ לְהַצְדִּיק צַדִּיק, לָתֵת לוֹ כְצִדְקָתוֹ, וּלְהַרְשִׁיעַ רָשָׁע, לָתֵת דַּרְכּוֹ בְרֹאשׁוֹ:\",10,0],[2,138,5,16,\"ישְׁבוֹת עַל מִלֵּאת. עַל מִלֵּאת שֶׁל עוֹלָם. מְשׁוֹטְטוֹת בְּכָל הָאָרֶץ, צוֹפוֹת טוֹבִים וְרָעִים. דָּבָר אַחֵר: תַּלְמִידֵי חֲכָמִים, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתְנָם עֵינַיִם לְהָאִיר לָעוֹלָם כְּשֵׁם שֶׁהָעֵינַיִם מְאִירִים לְאָדָם. כְּיוֹנִים הַנּוֹדְדִים מִשּׁוֹבָךְ לְשׁוֹבָךְ לְבַקֵּשׁ אָכְלָם, כָּךְ הֵם הוֹלְכִים מִמִּדְרָשׁוֹ שֶׁל פְּלוֹנִי חָכָם לְבֵית הַמִּדְרָשׁ שֶׁל פְּלוֹנִי חָכָם, לְבַקֵּשׁ טַעֲמֵי תוֹרָה:\",11,0],[2,138,5,16,\"עַל אֲפִיקֵי מָיִם. עַל בָּתֵּי מִדְרָשׁוֹת, שֶׁהֵם מוֹצָאֵי מַיִם שֶׁל תּוֹרָה:\",12,0],[2,138,5,16,\"רֹחֲצוֹת בֶּחָלָב. לְפִי שֶׁקְּרָאָן עֵינַיִם וְהָעַיִן לְשׁוֹן נְקֵבָה הִיא, אָמַר \\\"רוֹחֲצוֹת\\\", לְשׁוֹן נְקֵבָה. הֵם מְצַחְצְחִין עַצְמָן בְּחָלָב שֶׁל תּוֹרָה וּמְלַבְּנִים סְתָרֶיהָ וּסְתוּמוֹתֶיהָ:\",13,0],[2,138,5,16,\"ישְׁבוֹת עַל מִלֵּאת. מְיַשְּׁבִים דְּבָרִים עַל אָפְנֵיהֶם. דָּבָר אַחֵר: \\\"עֵינָיו\\\" עִנְיָנָיו, פָּרָשִׁיּוֹת שֶׁל תּוֹרָה וַהֲלָכוֹת וּמִשְׁנָיוֹת, \\\"כְּיוֹנִים\\\" שֶׁהֵם נָאִים בַּהֲלִיכָתָן; \\\"עַל אֲפִיקֵי מָיִם\\\" בְּבָתֵּי מִדְרָשׁוֹת, \\\"רֹחֲצוֹת בֶּחָלָב\\\" מְצֻחְצָחוֹת כֶּחָלָב, כְּמוֹ שֶׁפֵּרַשְׁתִּי:\",14,0],[2,138,5,16,\"לְחָיָו. דִּבְּרוֹת הַר סִינַי, שֶׁהֶרְאָה לָהֶם פָּנִים מַסְבִּירוֹת ושׂוֹחֲקוֹת:\",15,0],[2,138,5,16,\"שִׂפְתוֹתָיו שׁוֹשַׁנִּים. דִּבּוּרִים שֶׁנִּדְבַּר בְּאֹהֶל מוֹעֵד, שֶׁהֵם לְרִיצּוּי וּלְכַפָּרָה וּלְרֵיחַ טוֹב: תּוֹרַת חַטָּאת וְאָשָׁם וּמִנְחָה וְעוֹלָה וּשְׁלָמִים:\",16,0],[2,138,5,16,\"יָדָיו. הַלּוּחוֹת שֶׁנָּתַן מִימִינוֹ, וּמַעֲשֵׂה יָדָיו הֵמָּה:\",17,0],[2,138,5,16,\"גְּלִילֵי זָהָב. אֵלּוּ הַדִּבְּרוֹת, שֶׁבָּהֶן נֶאֱמַר: \\\"הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רָב\\\". אָמַר רַבִּי יְהוֹשֻׁעַ בֶּן נְחֶמְיָה: \\\"מַעֲשֵׂה נִסִּים הָיוּ. שֶׁל סַנְפִּירִינוֹן הָיוּ וְהָיוּ נִגְלָלִין. דָּבָר אַחֵר: עַל שֵׁם שֶׁמְּגַלְגְּלוֹת טוֹבָה לָעוֹלָם:\",18,0],[2,138,5,16,\"מְמֻלָּאִים בַּתַּרְשִׁישׁ. שֶׁכָּלַל בַּעֲשֶׂרֶת הַדִּבְּרוֹת תַּרְיַ\\\"ג מִצְוֹת:\",19,0],[2,138,5,16,\"מֵעָיו עֶשֶׁת שֵׁן. זֶה תוֹרַת כֹּהֲנִים הַנִּתָּן בְּאֶמְצַע חֲמִשָּׁה חֻמָּשִׁים, כַּמֵּעַיִם הַלָּלוּ שֶׁהֵם נְתוּנִים בְּאֶמְצַע הַגּוּף:\",20,0],[2,138,5,16,\"עֶשֶׁת שֵׁן מְעֻלֶּפֶת סַפִּירִים. נִרְאֵית חֲלָקָה כְּעֶשֶׁת שֵׁן, וְהִיא סְדוּרָה דִקְדּוּקִים רַבִּים: גְּזֵרוֹת שָׁווֹת וּבִנְיַן אָב וְקַלִּים וַחֲמוּרִים:\",21,0],[2,138,5,16,\"מְיֻסָּדִים עַל אַדְנֵי פָז. אָמַר רַבִּי אֶלְעָזָר הַקַּפָּר: \\\"הָעַמּוּד הַזֶּה יֵשׁ לוֹ כוֹתֶרֶת לְמַעְלָן וּבָסִיס לְמַטָּן\\\". אָמַר רַבִּי שְׁמוּאֵל בַּר גָּדָא: פָּרָשִׁיּוֹת שֶׁבַּתּוֹרָה יֵשׁ לָהֶן כּוֹתֶרֶת לְמַעְלָן וּבָסִיס לְמַטָּן, וּסְמוּכוֹת לִפְנֵיהֶם וּלְאַחֲרֵיהֶם, כְּגוֹן פָּרָשִׁיּוֹת שֶׁל שְׁבִיעִית וְיוֹבֵל, \\\"וְכִי תִמְכְּרוּ מִמְכָּר\\\", לְהוֹדִיעֲךָ כַּמָּה קָשָׁה אֲבָקָהּ שֶׁל שְׁבִיעִית, כִּדְאִיתָא בְּמַסֶּכֶת סֻכָּה וַעֲרָכִין וּכְגוֹן \\\"יִפְקֹד ה' . . . אִישׁ עַל הָעֵדָה\\\", \\\"צַו . . . אֶת קָרְבָּנִי לַחְמִי\\\". עַד שֶׁאַתָּה מְפַקְּדֵנִי עַל בָּנַי, פְּקֹד אוֹתָם עָלַי! וְכֵן כַּמָּה. לְכָךְ נֶאֱמַר: \\\"שׁוֹקָיו עַמּוּדֵי שֵׁשׁ מְיֻסָּדִים וגו'\\\":\",22,0],[2,138,5,16,\"מַרְאֵהוּ כַּלְּבָנוֹן. הַמִּסְתַּכֵּל וּמִתְבּוֹנֵן בִּדְבָרָיו, מוֹצֵא בָהֶם פְּרָחִים וְלוּלָבִים. כְּיַעַר זֶה שֶׁמְּלַבְלֵב, כָּךְ דִּבְרֵי תוֹרָה הַהוֹגֶה בָהֶם תָּמִיד מְחַדֵּשׁ בָּהֶם טְעָמִים:\",23,0],[2,138,5,16,\"בָּחוּר. נִבְחָר, כָּאֲרָזִים הַנִּבְחָרִים לְבִנְיָן וּלְחֹזֶק וּלְגוֹבַהּ:\",24,0],[2,138,5,16,\"חִכּוֹ מַמְתַקִּים. דְּבָרָיו עֲרֵבִים. \\\"וְשֶׂרֶט לָנֶפֶשׁ לֹא תִתְּנוּ בִּבְשַׂרְכֶם אֲנִי ה'\\\", הַנֶּאֱמָן לְשַׁלֵּם שָׂכָר. יֵשׁ חֵךְ מָתוֹק מִזֶּה? אַל תַּחְבְּלוּ בְּעַצְמְכֶם וּתְקַבְּלוּ שָׂכָר! \\\"וּבְשׁוּב רָשָׁע מֵרִשְׁעָתוֹ וְעָשָׂה מִשְׁפָּט וּצְדָקָה עֲלֵיהֶם הוּא יִחְיֶה\\\" עֲוֹנוֹת נֶחְשְׁבוּ לוֹ לִזְכֻיּוֹת. יֵשׁ חֵךְ מָתוֹק מִזֶּה?\",25,0],[2,138,6,1,\"אָנָה הָלַךְ דּוֹדֵךְ. מְאַנִּים וּמְקַנְטְרִים הָאֻמּוֹת אֶת יִשְׂרָאֵל, \\\"אָנָה הָלַךְ דּוֹדֵךְ? לָמָּה הִנִּיחַ אוֹתָךְ עֲזוּבָה אַלְמָנָה\\\"?\",1,0],[2,138,6,1,\"אָנָה פָּנָה דוֹדֵךְ. כְּשֶׁחָזַר וְהִשְׁרָה רוּחוֹ עַל כֹּרֶשׁ, וְנָתַן רְשׁוּת לִבְנוֹת הַבַּיִת, וְהִתְחִילוּ לִבְנוֹת, בָּאוּ וְאָמְרוּ לָהֶם: \\\"אָנָה פָּנָה דוֹדֵךְ?\\\" אִם חוֹזֵר הוּא אֵלַיִךְ נְבַקְּשֶׁנּוּ עִמָּךְ, כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"וַיִּשְׁמְעוּ צָרֵי יְהוּדָה וּבִנְיָמִן כִּי בְנֵי הַגּוֹלָה בוֹנִים הֵיכָל וגו' וַיִּגְּשׁוּ אֶל זְרֻבָּבֶל וגו' 'נִבְנֶה עִמָּכֶם כִּי כָכֶם נִדְרוֹשׁ לֵאלֹהֵיכֶם וגו'\\\". וְכַוָּנָתָם לְרָעָה, כְּדֵי לְהַשְׁבִּיתָם מִן הַמְּלָאכָה. וְהֵם מְשִׁיבִים:\",2,0],[2,138,6,2,\"דּוֹדִי יָרַד לְגַנּוֹ. צִוָּה לָנוּ לִבְנוֹת הֵיכָלוֹ וְיִהְיֶה שָׁם עִמָּנוּ:\",1,0],[2,138,6,2,\"לַעֲרוּגוֹת הַבֹּשֶׂם. מְקוֹם מִקְטַר הַקְּטֹרֶת:\",2,0],[2,138,6,2,\"לִרְעוֹת בַּגַּנִּים. וְעוֹד יָרַד לִרְעוֹת צֹאנוֹ בַּגַּנִּים אֲשֶׁר נָפוֹצוּ שָׁם אוֹתָם שֶׁלֹּא עָלוּ מִן הַגּוֹלָה מַשְׁרֶה שְׁכִינָתוֹ עֲלֵיהֶם בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת:\",3,0],[2,138,6,2,\"וְלִלְקֹט שׁוֹשַׁנִּים. שׁוֹמֵעַ וּמַקְשִׁיב נִדְבָּרִים בְּתוֹרָתוֹ לִלְקֹט זְכֻיּוֹתֵיהֶן וּלְכָתְבָם בְּסֵפֶר זִכָּרוֹן לְפָנָיו כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"אָז נִדְבְּרוּ יִרְאֵי ה' וגו'\\\". וּמַה שֶׁאַתֶּם אוֹמְרִים לְבַקְּשׁוֹ עִמָּנוּ וְלִבְנוֹת עִמָּנוּ, \\\"אֲנִי לְדוֹדִי\\\" וְלֹא אַתֶּם לוֹ, וְלֹא תִבְנוּ עִמָּנוּ, כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"לֹא לָכֶם וְלָנוּ לִבְנוֹת בַּיִת לֵאלֹהֵינוּ\\\". וְאוֹמֵר \\\"וְלָכֶם אֵין חֵלֶק וּצְדָקָה וְזִכָּרוֹן בִּירוּשָׁלָיִם\\\":\",4,0],[2,138,6,3,\"הָרוֹעֶה בַּשּׁוֹשַׁנִּים. הָרוֹעֶה אֶת צֹאנוֹ בְּמִרְעֶה נוֹחַ וְטוֹב:\",1,0],[2,138,6,4,\"יָפָה אַתְּ רַעְיָתִי כְּתִרְצָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְקַלְּסָהּ עַל זֹאת, \\\"יָפָה אַתְּ רַעְיָתִי\\\", כְּשֶׁאַתְּ רְצוּיָה לִי. כָּךְ הוּא נִדְרַשׁ בְּסִפְרֵי:\",1,0],[2,138,6,4,\"נָאוָה. אַתְּ עַתָּה כַּאֲשֶׁר בָּרִאשׁוֹנָה בִירוּשָׁלָיִם:\",2,0],[2,138,6,4,\"אֲיֻמָּה כַּנִּדְגָּלוֹת. חֵילֵי מַלְאָכִים. אֵימָתֵךְ אָטִיל עֲלֵיהֶם שֶׁלֹּא לְהִלָּחֵם וּלְהַשְׁבִּיתְכֶם מִן הַמְּלָאכָה, כְּמוֹ שֶׁנֶּאֱמַר בְּעֶזְרָא:\",3,0],[2,138,6,5,\"הָסֵבִּי עֵינַיִךְ מִנֶּגְדִּי. כְּבָחוּר שֶׁאֲרוּסָתוֹ חֲבִיבָה וַעֲרֵבָה עָלָיו וְעֵינֶיהָ נָאוֹת. וְאוֹמֵר לָהּ, \\\"הָסֵבִּי עֵינַיִךְ מִנֶּגְדִּי כִּי בִרְאוֹתִי אוֹתָךְ לִבִּי מִשְׁתַּחֵץ וּמִתְגָּאֶה עָלַי, וְרוּחִי גַסָּה בִי, וְאֵינִי יָכוֹל לְהִתְאַפֵּק\\\":\",1,0],[2,138,6,5,\"הִרְהִיבֻנִי. הֵגֵסוּ לִבִּי, כְּמוֹ \\\"וְרָהְבָּם עָמָל וָאָוֶן\\\", \\\"רַהַב הֵם שָׁבֶת\\\", אישווי\\\"ר בְּלַעַ\\\"ז. וְהַדֻּגְמָא כָךְ הוּא: אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּמִקְדָּשׁ זֶה אִי אֶפְשָׁר לְהָשִׁיב לָכֶם אָרוֹן וְכַפֹּרֶת וּכְרוּבִים, שֶׁהֵם הִרְהִיבוּנִי בְּבַיִת רִאשׁוֹן, לְהַרְאוֹתְכֶם חִבָּה יְתֵרָה עַד שֶׁמְּעַלְתֶּם בִּי:\",2,0],[2,138,6,5,\"שַׂעְרֵךְ כְּעֵדֶר הָעִזִּים. בִּקְטַנִּים וְרַכִּים וְדַקִּים שֶׁבָּכֶם יֵשׁ שֶׁבַח הַרְבֵּה:\",3,0],[2,138,6,6,\"שִׁנַּיִךְ. קְצִינִים וְגִבּוֹרִים שֶׁבֵּיךְ כֻּלָּם לְטוֹבָה:\",1,0],[2,138,6,6,\"כְּעֵדֶר הָרְחֵלִים. הָרָחֵל הַזֹּאת כֻּלָּהּ קְדוֹשָׁה: צַמְרָהּ לִתְכֵלֶת, בְּשָׂרָהּ לְקָרְבָּן, קַרְנֶיהָ לְשׁוֹפָרוֹת, שׁוֹקֶיהָ לַחֲלִילִין, מֵעֶיהָ לְכִנּוֹרוֹת, עוֹרָהּ לְתף, אֲבָל הָרְשָׁעִים נִמְשְׁלוּ לִכְלָבִים שֶׁאֵין מֵהֶם לִקְדֻשָּׁה כְּלוּם:\",2,0],[2,138,6,8,\"שִׁשִּׁים הֵמָּה מְלָכוֹת. אַבְרָהָם וְיוֹצְאֵי יְרֵכוֹ. בְּנֵי קְטוּרָה שֵׁשׁ עֶשְׂרֵה, יִשְׁמָעֵאל וּבָנָיו שְׁלשׁ עֶשְׂרֵה, יִצְחָק וּבָנָיו ג', בְּנֵי יַעֲקֹב שְׁנֵים עָשָׂר, בְּנֵי עֵשָׂו ט\\\"ז, בְּדִבְרֵי הַיָּמִים, הֲרֵי שִׁשִּׁים. וְאִם תּאמַר, צֵא מֵהֶם תִּמְנַע שֶׁהִיא אִשָּׁה, אַבְרָהָם מִן הַמִּנְיָן:\",1,0],[2,138,6,8,\"וּשְׁמֹנִים פִּילַגְשִׁים. נֹחַ וּבָנָיו עַד אַבְרָהָם. כָּל תּוֹלְדוֹת יוֹצְאֵי הַתֵּבָה שְׁמֹנִים תִּמְצָאֵם. וּכְשֵׁם שֶׁהַמְּלָכוֹת, שֶׁהֵם נְשֵׁי הַמֶּלֶךְ, יְתֵרוֹת בִּגְדֻלָּה עַל הַפִּילַגְשִׁים, כָּךְ הָיוּ אַבְרָהָם וְיוֹצְאֵי יְרֵכוֹ חֲשׁוּבִים גְּדוֹלִים וִיתֵרִים בַּחֲשִׁיבוּת עַל הַכֹּל, כַּאֲשֶׁר תִּרְאֶה. הָגָר בַּת מְלָכִים הָיְתָה, תִּמְנַע בַּת שִׁלְטוֹנִים הָיְתָה, וְנַעֲשֵׂית פִּילֶגֶשׁ לְעֵשָׂו. וְאוֹמֵר \\\"אֶל עֵמֶק שָׁוֵה וגו'\\\" הֻשְׁווּ כֻלָּם בְּעֵצָה אַחַת וְהִמְלִיכוּ אֶת אַבְרָהָם עֲלֵיהֶם:\",2,0],[2,138,6,8,\"וַעֲלָמוֹת אֵין מִסְפָּר. לְמִשְׁפָּחוֹת הַרְבֵּה נֶחְלְקוּ כָל אֵלֶּה:\",3,0],[2,138,6,9,\"אַחַת הִיא יוֹנָתִי. וּמִכֻּלָּם אַחַת הִיא הַנִּבְחֶרֶת לִי לְיוֹנָה תַמָּה, שֶׁהִיא תְמִימַת לֵב עִם בֶּן זוּגָהּ:\",1,0],[2,138,6,9,\"אַחַת הִיא לְאִמָּהּ. לִכְנֵסִיָּתָהּ. הַרְבֵּה מַחֲלוֹקוֹת בְּבָתֵּי מִדְרָשׁוֹת כֻּלָּם לִבָּם לְהָבִין תּוֹרָה עַל מְכוֹנָהּ וְעַל אֲמִתָּתָהּ:\",2,0],[2,138,6,9,\"בָּרָה הִיא לְיוֹלַדְתָּהּ. יַעֲקֹב רָאָה אוֹתָהּ מִטָּה שְׁלֵמָה בְּלֹא פְסוּל וְהוֹדָה וְקִלֵּס לַמָּקוֹם שֶׁנֶּאֱמַר, \\\"וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה\\\":\",3,0],[2,138,6,9,\"רָאוּהָ בָנוֹת. אֶת יִשְׂרָאֵל בִּגְדֻלָּתָהּ:\",4,0],[2,138,6,9,\"וַיְאַשְּׁרוּהָ. וּמַה הִיא קִלּוּסָן?\",5,0],[2,138,6,10,\"מִי זֹאת הַנִּשְׁקָפָה. עָלֵינוּ? מִמָּקוֹם הַגָּבֹהַּ לַנָּמוּךְ קְרוּיָה הַשְׁקָפָה. כָּךְ בֵּית הַמִּקְדָּשׁ גָּבֹהַּ מִכָּל אֲרָצוֹת:\",1,0],[2,138,6,10,\"כְּמוֹ שָׁחַר. הוֹלֵךְ וּמֵאִיר מְעַט מְעַט, כָּךְ הָיוּ יִשְׂרָאֵל בְּבַיִת שֵׁנִי. בַּתְּחִלָּה זְרֻבָּבֶל פַּחַת יְהוּדָה וְלֹא מֶלֶךְ, וְהָיוּ מְשֻׁעְבָּדִים לְפָרַס וּלְיָוָן, וְאַחַר כָּךְ נִצְּחוּם בֵּית חַשְׁמוֹנַאי וְנַעֲשׂוּ מְלָכִים:\",2,0],[2,138,6,10,\"אֲיֻמָּה כַּנִּדְגָּלוֹת. אֲיֻמָּה בְגִבּוֹרֶיהָ כְּנִדְגָּלוֹת שֶׁל מְלָכִים. כָּל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַלֵּס אֶת כְּנֶסֶת יִשְׂרָאֵל. \\\"יָפָה אַתְּ רַעְיָתִי כְּתִרְצָה\\\", וְכָל הָעִנְיָן עַד כַּאן:\",3,0],[2,138,6,11,\"אֶל גִּנַּת אֱגוֹז יָרַדְתִּי. עוֹד זֶה מִדִּבְרֵי שְׁכִינָה, הִנֵּה בָאתִי אֶל מִקְדָּשׁ שֵׁנִי זֶה, אֵלָיִךְ:\",1,0],[2,138,6,11,\"לִרְאוֹת בְּאִבֵּי הַנָּחַל. מַה לַּחְלוּחִית מַעֲשִׂים טוֹבִים אֶרְאֶה בָךְ:\",2,0],[2,138,6,11,\"הֲפָרְחָה הַגֶּפֶן. אִם תַּפְרִיחוּ לְפָנַי תַּלְמִידֵי חֲכָמִים וְסוֹפְרִים וְשׁוֹנִים:\",3,0],[2,138,6,11,\"הֵנֵצוּ הָרִמֹּנִים. מְקַיְּמֵי מִצְוֹת מְלֵאֵי זְכֻיּוֹת. לָמָּה נִמְשְׁלוּ יִשְׂרָאֵל לֶאֱגוֹז? מָה אֱגוֹז זֶה, אַתָּה רוֹאֶה אוֹתוֹ כֻלּוֹ עֵץ וְאֵין נִכָּר מַה בְּתוֹכוֹ, פּוֹצְעוֹ וּמוֹצְאוֹ מָלֵא מְגוּרוֹת מְגוּרוֹת שֶׁל אֳכָלִים, כָּךְ יִשְׂרָאֵל צְנוּעִין וְעִנְוְתָנִין בְּמַעֲשֵׂיהֶם וְאֵין תַּלְמִידִים שֶׁבָּהֶן נִכָּרִים, וְאֵין מִתְפָּאֲרִים לְהַכְרִיז עַל שִׁבְחָן, בְּדַקְתּוֹ אַתָּה מוֹצֵא אוֹתוֹ מָלֵא חָכְמָה. וְעוֹד כַּמָּה מִדְרָשׁוֹת לַדָּבָר: מָה אֱגוֹז זֶה נוֹפֵל בַּטִּיט וְאֵין מַה שֶׁבְּתוֹכוֹ נִמְאָס, אַף יִשְׂרָאֵל גּוֹלִין לְבֵין הָאֻמּוֹת וְלוֹקִין מַלְקִיּוֹת הַרְבֵּה וְאֵין מַעֲשֵׂיהֶם נִמְאָסִין:\",4,0],[2,138,6,12,\"לֹא יָדַעְתִּי. כְּנֶסֶת יִשְׂרָאֵל מִתְאוֹנֶנֶת: \\\"לֹא יָדַעְתִּי לְהִזָּהֵר מִן הַחֵטְא שֶׁאֶעֱמֹד בִּכְבוֹדִי וּבִגְדֻלָּתִי, וְנִכְשַׁלְתִּי בְּשִׂנְאַת חִנָּם וּמַחֲלֹקֶת שֶׁגָּבְרָה בְמַלְכֵי בֵית חַשְׁמוֹנַאי, הוֹרְקְנוֹס וַאֲרִיסְתּוֹבְלוֹס, עַד שֶׁהָיָה מֵבִיא אֶחָד מֵהֶם אֶת מַלְכוּת רוֹמִי וְקִבֵּל מִיָּדוֹ הַמְּלוּכָה וְנַעֲשָׂה לוֹ עֶבֶד, וּמֵאָז 'נַפְשִׁי שָׂמַתְנִי' לִהְיוֹת 'מֶרְכָּבוֹת' לְהַרְכִּיב עָלַי נְדִיבוּת שְׁאָר אֻמּוֹת:\",1,0],[2,138,6,12,\"עַמִּי נָדִיב. כְּמוֹ עַם נָדִיב. יו\\\"ד יְתֵרָה כיו\\\"ד שֶׁל \\\"שֹׁכְנִי סְנֶה,\\\" \\\"גְּנֻבְתִי יוֹם\\\", \\\"רַבָּתִי עָם\\\":\",2,0],[2,138,6,12,\"נַפְשִׁי שָׂמַתְנִי. אֲנִי בְעַצְמִי מִנִּיתִים עָלַי, כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"וְאַתְּ לִמַּדְתְּ אֹתָם עָלַיִךְ אַלֻּפִים לְרֹאשׁ\\\":\",3,0],[2,138,7,1,\"שׁוּבִי שׁוּבִי הַשּׁוּלַמִּית. אוֹמְרִים אֵלַי, \\\"שׁוּבִי שׁוּבִי מֵאַחַר הַמָּקוֹם\\\":\",1,0],[2,138,7,1,\"הַשּׁוּלַמִּית. הַשְּׁלֵמָה בֶאֱמוּנָתֵךְ עִמּוֹ, שׁוּבִי שׁוּבִי אֵלֵינוּ:\",2,0],[2,138,7,1,\"וְנֶחֱזֶה בָּךְ. נַצִּיב מִמֵּךְ נְצִיבִים וְשִׁלְטוֹנִים, כְּמוֹ \\\"וְאַתָּה תֶחֱזֶה מִכָּל הָעָם\\\". כָּךְ דָּרַשׁ רַבִּי תַּנְחוּמָא. דָּבָר אַחֵר: \\\"וְנֶחֱזֶה בָּךְ\\\", נִתְבּוֹנֵן אֵלַיִךְ מַה גְּדֻלָּה לִתֵּן לָךְ. וְהִיא אוֹמֶרֶת, \\\"מַה תֶּחֱזוּ בַּשּׁוּלַמִּית\\\"? מַה גְּדֻלָּה אַתֶּם יְכוֹלִים לִפְסֹק לִי שֶׁתְּהֵא שָׁוָה לִגְדֻלָּתִי, אֲפִלּוּ לִגְדֻלַּת דִּגְלֵי מְחוֹלוֹת מַחֲנוֹת הַמִּדְבָּר?\",3,0],[2,138,7,2,\"מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים. הֵם אוֹמְרִים לָהּ, \\\"חֲפֵצִים אָנוּ שֶׁתִּדְבְּקִי בָנוּ בִּשְׁבִיל נוֹי וַחֲשִׁיבוּת שֶׁרָאִינוּ בָךְ בְּעוֹדָךְ בְּיָפְיֵךְ\\\":\",1,0],[2,138,7,2,\"מַה יָּפוּ פְעָמַיִךְ. בַּעֲלִיַּת הָרְגָלִים, בַּת נְדִיבִים:\",2,0],[2,138,7,2,\"חַמּוּקֵי יְרֵכַיִךְ כְּמוֹ חֲלָאִים. קְבוּצַת עֲדָיֵי זָהָב קְרוּיָה \\\"חֲלִי כֶתֶם\\\", אלחל\\\"י בְּלָשׁוֹן עַרְבִי. וְרַבּוֹתֵינוּ דָרְשׁוּ עַל נִקְבֵי הַשִּׁיתִין שֶׁל נְסָכִים שֶׁנַּעֲשׂוּ מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית, עֲגֻלִּים כְּמוֹ יָרֵךְ. \\\"כְּמוֹ חֲלָאִים\\\", לְשׁוֹן חֲפִירָה, כְּמוֹ \\\"חֻלְיַת הַבּוֹר\\\":\",3,0],[2,138,7,2,\"מַעֲשֵׂה יְדֵי אָמָּן. יְדֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּמַסֶּכֶת סֻכָּה. אָמָּן כְּמוֹ אוּמָן. קִלּוּסוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׂרָאֵל מְקַלְּסִין אוֹתוֹ מִלְּמַעְלָה לְמַטָּה. מַתְחִילִין מֵ\\\"רֹאשׁוֹ כֶּתֶם פָּז\\\" וְיוֹרְדִין וּבָאִין עַד \\\"שׁוֹקָיו עַמּוּדֵי שֵׁשׁ\\\" לְפִי שֶׁהֵן בָּאִין לְרַצּוֹתוֹ לְהוֹרִיד שְׁכִינָתוֹ מִן הָעֶלְיוֹנִים לַתַּחְתּוֹנִים, וְהוּא מוֹנֶה קִלּוּסָם מִלְּמַטָּה לְמַעְלָה: \\\"מַה יָּפוּ פְעָמַיִךְ\\\", הֵם הָרַגְלַיִם, וּמוֹנֶה וְהוֹלֵךְ עַד \\\"רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל\\\" עַד שֶׁהוּא בָא לְמָשְׁכָהּ אֵלָיו:\",4,0],[2,138,7,3,\"שָׁרְרֵךְ אַגַּן הַסַּהַר. טַבּוּרֵךְ כְּאַגָּן שֶׁל מַיִם צְלוּלִים שֶׁרוֹחֲצִין בָּהֶן, וְהוּא עָשׂוּי מֵאַבְנֵי שַׁיִשׁ, וּבְלָשׁוֹן עַרְבִי קָרוּי סַהַר. עַל שֵׁם שֶׁהַטַּבּוּר כְּמוֹ נֶקֶב עָגֹל, מוֹשְׁלוֹ כְאַגָּן עָגֹל. וְהַקִּלּוּס הַזֶּה אֵינוֹ מֵעִנְיַן נוֹי אִשָּׁה כַּקִּלּוּס הָעֶלְיוֹן, לְפִי שֶׁהָעֶלְיוֹן דּוֹדָהּ מְקַלְּסָהּ, וְזֶה רֵעוֹתֶיהָ מְקַלְּסוֹת אוֹתָהּ עַל שֵׁם מַעֲשֶׂיהָ, לוֹמַר: \\\"הֲגוּנָה לְהִתְחַבֵּר עִמָּנוּ\\\". וְהַדֻּגְמָא עַל שֵׁם לִשְׁכַּת הַגָּזִית הַיּוֹשֶׁבֶת בְּטַבּוּר הָאָרֶץ:\",1,0],[2,138,7,3,\"אַל יֶחְסַר הַמָּזֶג. לֹא יִכְלֶה מִשָּׁם מַשְׁקֶה, רוֹצֶה לוֹמַר, לֹא יִכְלֶה וְלֹא יִפְסֹק מִשָּׁם שׁוּם דִּבְרֵי הוֹרָאָה:\",2,0],[2,138,7,3,\"בִּטְנֵךְ עֲרֵמַת חִטִּים. שֶׁהַכֹּל צְרִיכִין לָהּ:\",3,0],[2,138,7,3,\"סוּגָה בַּשּׁוֹשַׁנִּים. גְּדוּרָה וּמְסֻיֶּגֶת בְּגֶדֶר שׁוֹשַׁנִּים. דַּי לָהּ בְּגָדֵר קַל, וְאֵין אֶחָד מֵהֶם פּוֹרֵץ בּוֹ לִכָּנֵס. הֲרֵי חָתָן נִכְנָס לַחֻפָּה, לִבּוֹ מְגַעְגֵּעַ לַחֻפָּה וּלְחִבַּת חִתּוּנָיו. בָּא לִזָּקֵק לָהּ, אָמְרָה לוֹ, \\\"טִפַּת דָּם כְּחַרְדָּל רָאִיתִי\\\". הֲרֵי הוֹפֵךְ פָּנָיו לְצַד אַחֵר. וְלֹא נְשָׁכוֹ נָחָשׁ, וְלֹא עַקְרָב עוֹקְצוֹ. הֲרֵי שֶׁהוּא עוֹבֵר בַּדֶּרֶךְ, רָאָה בַכּוּרוֹת בְּרָאשֵׁי הַתְּאֵנִים. פָּשַׁט יָדוֹ לִטֹּל, אוֹמְרִים לוֹ, \\\"שֶׁל בְּעָלִים הֵם\\\". הוּא מוֹשֵׁךְ יָדוֹ מִפְּנֵי הַגָּזֵל, הֲרֵי \\\"סוּגָה בַּשּׁוֹשַׁנִּים\\\":\",4,0],[2,138,7,4,\"שְׁנֵי שָׁדַיִךְ. שְׁתֵּי הַלּוּחוֹת. דָּבָר אַחֵר: מֶלֶךְ וְכֹהֵן גָּדוֹל:\",1,0],[2,138,7,5,\"צַוָּארֵךְ. הַהֵיכָל וְהַמִּזְבֵּחַ שֶׁהֵם זְקוּפִים וּגְבֹהִים, וְלִשְׁכַּת הַגָּזִית גַּם הִיא שָׁם עֲשׂוּיָה לְחֹזֶק וּלְמָגֵן \\\"כְּמִגְדַּל הַשֵּׁן\\\":\",1,0],[2,138,7,5,\"עֵינַיִךְ. כַּבְּרֵכוֹת אֲשֶׁר בְּחֶשְׁבּוֹן הַמּוֹשְׁכוֹת מָיִם, כָּךְ עֵינַיִךְ עַל שַׁעַר בַּת רַבִּים. חֲכָמַיִךְ, כְּשֶׁהֵם יוֹשְׁבִים בְּשַׁעֲרֵי יְרוּשָׁלַיִם, הָעִיר בַּת רַבַּת עָם, וַעֲסוּקִים בְּחֶשְׁבּוֹן תְּקוּפוֹת וּמַזָּלוֹת, חָכְמָתָם וּבִינָתָם לְעֵינֵי הָעַמִּים, מוֹשְׁכוֹת כִּבְרֵכוֹת מָיִם. וְעוֹד יֵשׁ לְפָרֵשׁ \\\"בְּרֵכוֹת בְּחֶשְׁבּוֹן\\\" כְּמוֹ \\\"יוֹנִים\\\" וּלְשׁוֹן מִשְׁנָה הוּא: \\\"הַלּוֹקֵחַ יוֹנֵי שׁוֹבָךְ מַפְרִיחַ בְּרִיכָה רִאשׁוֹנָה\\\". קוביד\\\"ש בְּלַעַ\\\"ז:\",2,0],[2,138,7,5,\"אַפֵּךְ כְּמִגְדַּל הַלְּבָנוֹן. אֵינִי יָכוֹל לְפָרְשׁוֹ לְשׁוֹן חֹטֶם, לֹא לְעִנְיַן פְּשָׁט וְלֹא לְעִנְיַן דֻּגְמָא, כִּי מַה קִּלּוּס נוֹי יֵשׁ בְּחֹטֶם גָּדוֹל וְזָקוּף כְּמִגְדָּל? וְאוֹמֵר אֲנִי, \\\"אַפֵּךְ\\\" לְשׁוֹן פָּנִים, וְזֶה שֶׁהוּא אוֹמֵר לְשׁוֹן יָחִיד, וְאֵינוֹ אוֹמֵר \\\"אַפַּיִךְ\\\", שֶׁעַל הַמֵּצַח הוּא מְדַבֵּר שֶׁהוּא עִיקַר הַכָּרַת פָּנִים, כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"הַכָּרַת פְּנֵיהֶם עָנְתָה בָּם\\\". וְתֵדַע, שֶׁהֲרֵי מְקַלְּסָם וְהוֹלֵךְ מִלְּמַטָּה לְמַעְלָה. \\\"עֵינַיִךְ בְּרֵכוֹת בְּחֶשְׁבּוֹן\\\", וְאַחֲרֵיהֶם הַמֵּצַח. וְכֵן הָאֻמּוֹת מְקַלְּסוֹת \\\"מִצְחֲךָ חָזָק לְעֻמַּת\\\" מֵצַח כָּל הַבָּאִים לְהַרְעוֹתֵךְ וּלְפַתּוֹתֵךְ: כְּמִגְדַּל הַלְּבָנוֹן\",3,0],[2,138,7,5,\"צוֹפֶה פְּנֵי דַמָּשֶׂק. רָאִיתִי בַמִּדְרָשׁ זֶה בֵית יַעַר הַלְּבָנוֹן שֶׁעָשָׂה שְׁלֹמֹה, שֶׁהָעוֹמֵד עָלָיו צוֹפֶה וּמוֹנֶה כַּמָּה בָתִּים יֵשׁ בְּדַמָּשֶׂק. דָּבָר אַחֵר: פָּנַיִךְ צוֹפוֹת פְּנֵי דַמָּשֶׂק מְצַפּוֹת לְבֹא שַׁעֲרֵי יְרוּשָׁלַיִם עַד דַּמֶּשֶׂק, שֶׁעֲתִידָה לְהַרְחִיב עַד דַּמָּשֶׂק:\",4,0],[2,138,7,6,\"רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל. אֵלּוּ תְּפִלִּין שֶׁבָּרֹאשׁ שֶׁנֶּאֱמַר בָּהֶן \\\"וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' נִקְרָא עָלֶיךָ וְיָרְאוּ מִמֶּךָ\\\". הֲרֵי הִיא חָזְקָן וּמוֹרָאָן כְּסֶלַע הָרִים, וְכַרְמֶל הוּא רֹאשׁ הֶהָרִים:\",1,0],[2,138,7,6,\"וְדַלַּת רֹאשֵׁךְ. קְלִיעַת שַׂעֲרוֹת נְזִירַיִךְ נָאָה בְמִצְוֹת כִּקְלִיעַת אַרְגָּמָן:\",2,0],[2,138,7,6,\"וְדַלַּת רֹאשֵׁךְ. עַל שֵׁם שֶׁהַקְּלִיעָה מֻדְלֵת עַל גֹּבַהּ הָרֹאשׁ:\",3,0],[2,138,7,6,\"מֶלֶךְ אָסוּר בָּרְהָטִים. שְׁמוֹ שֶׁל מָקוֹם קָשׁוּר בַּתַּלְתַּלִּים, שֶׁנֶּאֱמַר, \\\"נֵזֶר אֱלֹהָיו עַל רֹאשׁוֹ\\\":\",4,0],[2,138,7,6,\"רְהָטִים. קורנ\\\"ץ בְּלַעַ\\\"ז. כֵּן קוֹרִין לְתַלְתַּלֵּי הָאֲזוֹרוֹת שֶׁקּוֹשְׁרִין בָּהֶן הַחֲגוֹרוֹת. דָּבָר אַחֵר: \\\"מֶלֶךְ אָסוּר בָּרְהָטִים\\\" הַקָּדוֹשׁ בָּרוּךְ הוּא נִקְשָׁר בְּאַהֲבָה, בְּמִצְוֹת, וּבְרִיצוֹת שֶׁאַתֶּם רָצִים לְפָנָיו:\",5,0],[2,138,7,7,\"מַה יָּפִית וּמַה נָּעַמְתְּ. אַחַר שֶׁפָּרַט קִלּוּס כָּל אֵבֶר וְאֵבֶר, כָּלַל כָּל דָּבָר: \\\"מַה יָּפִית\\\" כֻּלָּךְ, \\\"וּמַה נָּעַמְתְּ\\\" לִדַּבֵּק בָּךְ אַהֲבָה הַהוֹגֶנֶת לְהִתְעַנֵּג בָּהּ:\",1,0],[2,138,7,8,\"זֹאת קוֹמָתֵךְ דָּמְתָה לְתָמָר. רָאִינוּ נוֹי קוֹמָתֵךְ בִּימֵי נְבוּכַדְנֶצַּר, שֶׁכָּל הָאֻמּוֹת הָיוּ כוֹרְעוֹת וְנוֹפְלוֹת לִפְנֵי הַצֶּלֶם, וְאַתָּה עָמַדְתָּ בְּקוֹמָה זְקוּפָה כַּתָּמָר הַזֶּה:\",1,0],[2,138,7,8,\"וְשָׁדַיִךְ לְאַשְׁכֹּלוֹת. דָּנִיֵּאל, חֲנַנְיָה, מִישָׁאֵל, וַעֲזַרְיָה, שֶׁהָיוּ לָךְ כְּשָׁדַיִם לִינֹק מֵהֶם, דָּמוּ לְאֶשְׁכּוֹלוֹת שֶׁמַּשְׁפִּיעוֹת מַשְׁקֶה. כָּךְ הֵם הִשְׁפִּיעוּ לְהָנִיק וּלְלַמֵּד אֶת הַכֹּל שֶׁאֵין יִרְאָה כְיִרְאַתְכֶם. עַד כַּאן קִלְּסוּהוּ הָאֻמּוֹת, מִכָּאן וְאֵילֵךְ דִּבְרֵי שְׁכִינָה לְגָלוּת יִשְׂרָאֵל שֶׁבֵּין הָאֻמּוֹת:\",2,0],[2,138,7,9,\"אָמַרְתִּי אֶעֱלֶה בְתָמָר. מִתְפָּאֵר אֲנִי בֵּין חֲיָלוֹת שֶׁל מַעְלָה בָכֶם, שֶׁאֶתְעַלֶּה וְאֶתְקַדֵּשׁ עַל יְדֵיכֶם בַּתַּחְתּוֹנִים, שֶׁתְּקַדְּשׁוּ אֶת שְׁמִי בֵּין הָאֻמּוֹת:\",1,0],[2,138,7,9,\"אֹחֲזָה בְּסַנְסִנָּיו. וַאֲנִי אֶאֱחֹז וְאֶדְבַּק בָּכֶם. סַנְסִנִּים עֲנָפִים:\",2,0],[2,138,7,9,\"וְיִהְיוּ נָא שָׁדַיִךְ. וְעַתָּה, הַאַמְתִי אֶת דְּבָרַי שֶׁלֹּא תִתְפַּתִּי אַחֲרֵי הָאֻמּוֹת, וְיִהְיוּ הַטּוֹבִים וְהַחֲכָמִים שֶׁבֵּיךְ עוֹמְדִים בֶּאֱמוּנָתָם לְהָשִׁיב דְּבָרִים לַמְפַתִּים אוֹתָם, שֶׁיִּלְמְדוּ מֵהֶם הַקְּטַנִּים שֶׁבָּכֶם:\",3,0],[2,138,7,10,\"וְחִכֵּךְ כְּיֵין הַטּוֹב. הִזָּהֲרִי בִּתְשׁוּבוֹתַיִךְ שֶׁיִּהְיוּ כְּיֵין הַטּוֹב:\",1,0],[2,138,7,10,\"הוֹלֵךְ לְדוֹדִי לְמֵישָׁרִים. זְהִירָה אֲנִי לְהָשִׁיב לָהֶם שֶׁאֶעֱמֹד בֶּאֱמוּנָתִי, שֶׁיְּהֵא חִכִּי הוֹלֵךְ לִפְנֵי דוֹדִי לְאַהֲבַת מִישׁוֹר, שֶׁהוּא מִן הַלֵּב, וְלֹא בִרְמִיָּה וַעֲקִיבָה:\",2,0],[2,138,7,10,\"כְּיֵין הַטּוֹב. שֶׁהוּא דוֹבֵב שִׂפְתֵי יְשֵׁנִים. אַף אֲבוֹתַי בַּקֶּבֶר יִשְׂמְחוּ בִי וְיוֹדוּ עַל חֶלְקָם. \\\"דּוֹבֵב\\\" מַרְחִישׁ, פרומי\\\"ד בְּלַעַ\\\"ז, וִיסוֹדוֹ לְשׁוֹן דִּבּוּר. וְכָךְ הִיא הַתְּשׁוּבָה. \\\"אֲנִי לְדוֹדִי וְגַם הוּא מִשְׁתּוֹקֵק לִי\\\":\",3,0],[2,138,7,12,\"לְכָה דוֹדִי נֵצֵא הַשָּׂדֶה. דָּרְשׁוּ רַבּוֹתֵינוּ בְּעֵרוּבִין: אָמְרָה כְנֶסֶת יִשְׂרָאֵל, רִבּוֹנוֹ שֶׁל עוֹלָם, אַל תְּדִינֵנִי כְּיוֹשְׁבֵי כְרַכִּים שֶׁיֵּשׁ בָּהֶם גָּזֵל וַעֲרָיוֹת, אֶלָּא כְיוֹשְׁבֵי פְרָזוֹת שֶׁהֵם בַּעֲלֵי אֻמָּנוּת וְעוֹסְקִין בַּתּוֹרָה מִתּוֹךְ הַדְּחָק:\",1,0],[2,138,7,12,\"נָלִינָה בַּכְּפָרִים. נָלִינָה בַּכּוֹפְרִים. בֹּא וְאַרְאֶךָ בְּנֵי עֵשָׂו שֶׁהִשְׁפַּעְתָּ לָהֶם טוֹבָה וְכוֹפְרִים בָּךְ:\",2,0],[2,138,7,13,\"נַשְׁכִּימָה לַכְּרָמִים. אֵלּוּ בָתֵּי כְנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת:\",1,0],[2,138,7,13,\"נִרְאֶה אִם פָּרְחָה הַגֶּפֶן. אֵלּוּ בַעֲלֵי מִקְרָא:\",2,0],[2,138,7,13,\"פִּתַּח הַסְּמָדַר. כְּשֶׁהַפֶּרַח נוֹפֵל וְהָעֲנָבִים נִכָּרִים, הוּא פִּתּוּחַ הַסְּמָדַר, וְלָהֶם דִּמָּה בַעֲלֵי מִשְׁנָה שֶׁהֵם קְרוֹבִים לֵהָנוֹת מֵהֶם בְּהוֹרָאַת הַתּוֹרָה:\",3,0],[2,138,7,13,\"הֵנֵצוּ הָרִמּוֹנִים. כְּשֶׁהֵם גְּמוּרִים וְהַנֵּץ שֶׁסְּבִיבוֹתֵיהֶן נוֹפֵל. \\\"הֵנֵצוּ\\\", נוֹפֵל נִצּוֹ וְלָהֶם דִּמָּה בַעֲלֵי תַלְמוּד, שֶׁהֵן בְּחָכְמָה גְמוּרה וּרְאוּיִין לְהוֹרוֹת:\",4,0],[2,138,7,13,\"שָׁם אֶתֵּן אֶת דּוֹדַי. שָׁם אַרְאֶךָ אֶת כְּבוֹדִי וְגָדְלִי שֶׁבַח בָּנַי וּבְנוֹתָי:\",5,0],[2,138,7,14,\"הַדּוּדָאִים נָתְנוּ רֵיחַ. דּוּדָאֵי הַתְּאֵנִים הַטּוֹבוֹת וְהָרָעוֹת, כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"הִרְאַנִי ה' וְהִנֵּה שְׁנֵי דּוּדָאֵי תְאֵנִים וגו' הַדּוּד אֶחָד תְּאֵנִים טֹבוֹת וגו' וְהַדּוּד אֶחָד תְּאֵנִים רָעוֹת מְאֹד אֲשֶׁר לֹא תֵאָכַלְנָה\\\". אֵלּוּ פּוֹשְׁעֵי יִשְׂרָאֵל. עַכְשָׁיו שְׁנֵיהֶם נָתְנוּ רֵיחַ, כֻּלָּם מְבַקְּשִׁים פָּנֶיךָ:\",1,0],[2,138,7,14,\"וְעַל פְּתָחֵינוּ כָּל מְגָדִים. יֵשׁ בְּיָדֵינוּ שְׂכַר מִצְוֹת הַרְבֵּה:\",2,0],[2,138,7,14,\"חֲדָשִׁים גַּם יְשָׁנִים. שֶׁחִדְּשׁוּ סוֹפְרִים עִם הַיְשָׁנִים שֶׁכָּתַבְתָּ עָלַי:\",3,0],[2,138,7,14,\"צָפַנְתִּי לָךְ. לְשִׁמְךָ וְלַעֲבוֹדָתְךָ צָפַנְתִּי בְלִבִּי. דָּבָר אַחֵר: צָפַנְתִּי לְהַרְאוֹת לְךָ שֶׁקִּיַּמְתִּים:\",4,0],[2,138,8,1,\"מִי יִתֶּנְךָ כְּאָח לִי. שֶׁתָּבֹא לְנַחֲמֵנִי כְּדֶרֶךְ שֶׁעָשָׂה יוֹסֵף לְאֶחָיו שֶׁגְּמָלוּהוּ רָעָה, וְנֶאֱמַר בּוֹ \\\"וַיְנַחֵם אוֹתָם\\\":\",1,0],[2,138,8,1,\"אֶמְצָאֲךָ בַחוּץ אֶשָּׁקְךָ. אֶמְצָא נְבִיאֶיךָ מְדַבְּרִים בִּשְׁמֶךָ, וַאֲחַבְּקֵם וַאֲנַשְּׁקֵם. גַּם יָדַעְתִּי כִּי \\\"לֹא יָבֻזוּ לִי\\\", כִּי כְדַאי הִיא אַהֲבָתְךָ שֶׁתְּהֵא אֲהוּבָתְךָ סוֹבֶבֶת לְחַזֵּר אַחֲרֶיהָ:\",2,0],[2,138,8,2,\"אֶל בֵּית אִמִּי. בֵּית הַמִּקְדָּשׁ:\",1,0],[2,138,8,2,\"תְּלַמְּדֵנִי. כַּאֲשֶׁר הֻרְגַּלְתָּ לַעֲשׂוֹת בְּאֹהֶל מוֹעֵד:\",2,0],[2,138,8,2,\"אַשְׁקְךָ מִיַּיִן הָרֶקַח. נְסָכִים:\",3,0],[2,138,8,2,\"מֵעֲסִיס. יַיִן מָתוֹק:\",4,0],[2,138,8,3,\"שְׂמֹאלוֹ תַּחַת רֹאשִׁי וגו'.\",1,0],[2,138,8,4,\"הִשְׁבַּעְתִּי אֶתְכֶם. עַכְשָׁיו כְּנֶסֶת יִשְׂרָאֵל מְסַבֶּבֶת דִּבּוּרָהּ כְּלַפֵּי הָאֻמּוֹת, \\\"אַף עַל פִּי שֶׁאֲנִי קוֹבֶלֶת וּמִתְאוֹנֶנֶת, דּוֹדִי מַחֲזִיק בְּיָדִי וְהוּא לִי לְמִשְׁעָן בְּגָלוּתִי. לְפִיכָךְ 'הִשְׁבַּעְתִּי אֶתְכֶם'\\\":\",1,0],[2,138,8,4,\"מַה תָּעִירוּ וּמַה תְּעֹרְרוּ. כִּי לֹא יוֹעִיל לָכֶם:\",2,0],[2,138,8,5,\"מִי זֹאת. הַקָּדוֹשׁ בָּרוּךְ הוּא וּבֵית דִּינוֹ אוֹמְרִים עַל כְּנֶסֶת יִשְׂרָאֵל: \\\"מִי זֹאת?\\\" כַּמָּה הִיא חֲשׁוּבָה זֹאת שֶׁנִּתְעַלְּתָה מִן הַמִּדְבָּר בְּכָל מַתָּנוֹת טוֹבוֹת! שָׁם נִתְעַלְּתָה בְמַתַּן תּוֹרָה וּבְדִבּוּק שְׁכִינָה, וְנִרְאֵית חִבָּתָהּ לַכֹּל וְעוֹדֶנָּה בְגָלוּתָהּ:\",1,0],[2,138,8,5,\"מִתְרַפֶּקֶת עַל דּוֹדָהּ. מִתְחַבֶּרֶת עַל דּוֹדָהּ, מוֹדָה שֶׁהִיא חֲבֶרְתּוֹ וּדְבוּקָה בוֹ. \\\"רפק\\\" בְּלָשׁוֹן עַרְבִי רפקתא, חֲבוּרָה:\",2,0],[2,138,8,5,\"תַּחַת הַתַּפּוּחַ עוֹרַרְתִּיךָ. כָּךְ הִיא אוֹמֶרֶת בְּבַקָּשַׁת חִבַּת דּוֹדָהּ: \\\"תַּחַת הַתַּפּוּחַ עוֹרַרְתִּיךָ.\\\" זְכֹר כִּי בְתַחְתִּית הַר סִינַי הֶעָשׂוּי עַל רֹאשִׁי כְמִין תַּפּוּחַ, שָׁם \\\"עוֹרַרְתִּיךָ\\\". וְהוּא לְשׁוֹן חִבַּת אֵשֶׁת נְעוּרִים הַמְעוֹרֶרֶת אֶת דּוֹדָהּ בַּלֵּילוֹת בִּתְנוּמוֹת עֲלֵי מִשְׁכָּב, מְחַבַּקְתּוֹ וּמְנַשַּׁקְתּוֹ:\",3,0],[2,138,8,5,\"שָׁמָּה חִבְּלָתְךָ אִמֶּךָ. הֲרֵי אָמַרְנוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קְרָאָהּ אִמּוֹ. שָׁם נִהְיְתָה לְךָ לְאֵם:\",4,0],[2,138,8,5,\"חִבְּלָתְךָ. לְשׁוֹן חֶבְלֵי יוֹלֵדָה. חִבְּלָתְךָ. בָּאוּ לָהּ חֲבָלִים מִמְּךָ כְּמוֹ \\\"בָּנַי יְצָאֻנִי\\\" יָצְאוּ מִמֶּנִּי:\",5,0],[2,138,8,6,\"שִׂימֵנִי כַחוֹתָם. בִּשְׁבִיל אוֹתָהּ אַהֲבָה, תַּחְתְּמֵנִי עַל לִבֶּךָ, שֶׁלֹּא תִשְׁכָּחֵנִי, וְתִרְאֶה:\",1,0],[2,138,8,6,\"כִּי עַזָּה כַמָּוֶת אַהֲבָה. הָאַהֲבָה שֶׁאֲהַבְתִּיךָ עָלַי כְּנֶגֶד מִיתָתִי שֶׁאֲנִי נֶהֱרֶגֶת עָלֶיךָ:\",2,0],[2,138,8,6,\"קָשָׁה כְשְׁאוֹל קִנְאָה. הַתִּגָּר שֶׁנִּתְקַנְּאוּ וְשֶׁנִּתְגָּרוּ בִי הָאֻמּוֹת בִּשְׁבִילְךָ. \\\"קִנְאָה\\\" בְּכָל מָקוֹם אינפרמנ\\\"ט בְּלַעַ\\\"ז, לְשׁוֹן אֲחִיזַת הַלֵּב לִנְקֹם נָקָם:\",3,0],[2,138,8,6,\"אֵשׁ שַׁלְהֶבֶתְיָה. רְשָׁפִים שֶׁל אֵשׁ חֲזָקָה הַבָּאָה מִכֹּחַ שַׁלְהֶבֶת שֶׁל גֵּיהִנֹּם. טַעַם הַזָּקֵף הַגָּדוֹל הַנָּקוּד עַל \\\"רִשְׁפֵּי\\\", מְלַמְּדֵנוּ עַל תֵּבַת \\\"אֵשׁ\\\" שֶׁהִיא דְבוּקָה לְ\\\"שַׁלְהֶבֶתְיָה\\\", לוֹמַר \\\"אֵשׁ שֶׁל שַׁלְהֶבֶתְיָה\\\":\",4,0],[2,138,8,7,\"מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה. עַל שֶׁכִּנָּם בִּלְשׁוֹן רְשָׁפִים, נוֹפֵל עֲלֵיהֶם לְשׁוֹן לֹא יִכְבּוּ:\",1,0],[2,138,8,7,\"מַיִם רַבִּים. הָאֻמּוֹת:\",2,0],[2,138,8,7,\"וּנְהָרוֹת. שָׂרֵיהֶם וּמַלְכֵיהֶם:\",3,0],[2,138,8,7,\"לֹא יִשְׁטְפוּהָ. עַל יְדֵי חֹזֶק וְאֵימָה, וְאַף עַל יְדֵי פִתּוּי וַהֲסָתָה:\",4,0],[2,138,8,7,\"אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ. כְּדֵי לְהָמִיר אַהֲבָתֵךְ:\",5,0],[2,138,8,7,\"בּוֹז יָבוּזוּ לוֹ. כָּל אֵלֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא וּבֵית דִּינוֹ מְעִידִים, שֶׁכָּךְ כְּנֶסֶת יִשְׂרָאֵל מִתְרַפֶּקֶת עַל דּוֹדָהּ: עַתָּה,\",6,0],[2,138,8,8,\"אָחוֹת לָנוּ. בַּתַּחְתּוֹנִים, שֶׁהִיא מִתְאַחָה וּמִתְחַבֶּרֶת וּמִתְאַוָּה לִהְיוֹת עִמָּנוּ, וְהִיא קְטַנָּה וּמַקְטֶנֶת אֶת עַצְמָהּ מִכָּל הָאֻמּוֹת, כְּעִנְיָן שֶׁנֶּאֱמַר: \\\"לֹא מֵרֻבְּכֶם וגו'\\\" שֶׁהֵם מַקְטִינִים עַצְמָם:\",1,0],[2,138,8,8,\"אָחוֹת. לְשׁוֹן אִחוּי. \\\"אֵלּוּ קְרָעִים שֶׁאֵין מִתְאַחִין\\\":\",2,0],[2,138,8,8,\"וְשָׁדַיִם אֵין לָהּ. כְּעִנְיָן שֶׁנֶּאֱמַר בְּגָלוּת מִצְרַיִם \\\"שָׁדַיִם נָכֹנוּ\\\" בְּהַגִּיעַ עֵת הַגְּאֻלָּה, אֲבָל זוּ \\\"שָׁדַיִם אֵין לָהּ\\\", עֲדַיִן לֹא הִגִּיעַ עִתָּהּ לְעֵת דּוֹדִים: מַה נַּעֲשֶׂה לַאֲחוֹתֵנוּ\",3,0],[2,138,8,8,\"בַּיּוֹם שֶׁיְּדֻבַּר בָּהּ. כְּשֶׁהָאֻמּוֹת מִתְלַחֲשִׁים עָלֶיהָ לְהַכְחִידָהּ, כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"לְכוּ וְנַכְחִידֵם מִגּוֹי\\\":\",4,0],[2,138,8,9,\"אִם חוֹמָה הִיא. אִם תֶּחֱזַק בֶּאֱמוּנָתָהּ וּבְיִרְאָתָהּ לִהְיוֹת כְּנֶגְדָּם כְּחוֹמַת נְחֹשֶׁת שֶׁלֹּא יִכָּנְסוּ לְתוֹכָהּ, רוֹצֶה לוֹמַר שֶׁלֹּא תִתְחַתֵּן בָּם וְהֵם לֹא יָבוֹאוּ בָהּ, וְלֹא תִתְפַּתֶּה לָהֶם:\",1,0],[2,138,8,9,\"נִבְנֶה עָלֶיהָ טִירַת כָּסֶף. נִהְיֶה לָהּ לְעִיר מִבְצָר וּלְכֶתֶר וּלְנוֹי, וְנִבְנֶה לָהּ אֶת עִיר הַקֹּדֶשׁ וּבֵית הַבְּחִירָה:\",2,0],[2,138,8,9,\"וְאִם דֶּלֶת הִיא. הַסּוֹבֶבֶת עַל צִירָהּ, וּבְהַקִּישׁ עָלֶיהָ הִיא נִפְתַּחַת, אַף הִיא, אִם תִּפְתַּח לָהֶם לִהְיוֹת הֵם בָּאִים בָּהּ וְהִיא בָהֶם:\",3,0],[2,138,8,9,\"נָצוּר עָלֶיהָ לוּחַ אָרֶז. נָשִׂים בְּדַלְתָּהּ נְסָרִים שֶׁל עֵץ הַנִּרְקָבִים, וְהַתּוֹלַעַת גּוֹרַרְתָּן וְאוֹכַלְתָּן. וּכְנֶסֶת יִשְׂרָאֵל אוֹמֶרֶת:\",4,0],[2,138,8,10,\"אֲנִי חוֹמָה. חֲזָקָה בְּאַהֲבַת דּוֹדִי:\",1,0],[2,138,8,10,\"וְשָׁדַי כַּמִּגְדָּלוֹת. אֵלּוּ בָתֵּי כְנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת הַמְּנִיקִים אֶת יִשְׂרָאֵל בְּדִבְרֵי תוֹרָה:\",2,0],[2,138,8,10,\"אָז. בְּאָמְרִי זֹאת:\",3,0],[2,138,8,10,\"הָיִיתִי בְעֵינָיו כְּמוֹצְאֵת שָׁלוֹם. כְּכַלָּה הַנִּמְצֵאת שְׁלֵמָה וּמוֹצְאֵת שָׁלוֹם בְּבֵית בַּעְלָהּ:\",4,0],[2,138,8,11,\"כֶּרֶם הָיָה לִשְׁלֹמֹה. זוּ כְנֶסֶת יִשְׂרָאֵל, שֶׁנֶּאֱמַר, \\\"כִּי כֶרֶם ה' צְבָאוֹת בֵּית יִשְׂרָאֵל\\\":\",1,0],[2,138,8,11,\"בְּבַעַל הָמוֹן. בִּיְרוּשָׁלַיִם, שֶׁהִיא רַבַּת עַם וְהָמוֹן רָב:\",2,0],[2,138,8,11,\"בַּעַל. לְשׁוֹן מִישׁוֹר, כְּמוֹ \\\"מִבַּעַל גָּד בְּבִקְעַת הַלְּבָנוֹן\\\":\",3,0],[2,138,8,11,\"נָתַן אֶת הַכֶּרֶם לַנֹּטְרִים. מְסָרָהּ לְיַד אֲדוֹנִים קָשִׁים: בָּבֶל, מָדַי, יָוָן וֶאֱדוֹם. בְּמִדְרַשׁ שִׁיר הַשִּׁירִים מָצָאתִי מִקְצָת סְמָךְ עַל נוֹטְרִים הַלָּלוּ, שֶׁהֵם הַמַּלְכֻיּוֹת:\",4,0],[2,138,8,11,\"אִישׁ יָבִא בְּפִרְיוֹ. כָּל מַה שֶׁיָּכְלוּ לִגְבּוֹת מֵהֶן: גֻּלְגָּלִיּוֹת וְאַרְנוּנְיוֹת וְאַנְפָּרוּת, הַכֹּל גָּבוּ מֵהֶם לְהָבִיא לְתוֹךְ בֵּיתָם:\",5,0],[2,138,8,12,\"כַּרְמִי שֶׁלִּי לְפָנָי. לְיוֹם הַדִּין יְבִיאֵם הַקָּדוֹשׁ בָּרוּךְ הוּא בְמִשְׁפָּט, וְיֹאמַר: \\\"כַּרְמִי, אַף עַל פִּי שֶׁמְּסַרְתִּיו בְּיֶדְכֶם, שֶׁלִּי הוּא, וּלְפָנַי בָּא כָּל מַה שֶּׁחֲטַפְתֶּם לָכֶם אֶת פִּרְיוֹ, וְלֹא נִכְחַד מִמֶּנִּי מַה שֶׁגְּבִיתֶם מֵהֶם\\\". וְהֵם אוֹמְרִים:\",1,0],[2,138,8,12,\"הָאֶלֶף לְךָ שְׁלֹמֹה. \\\"אֶלֶף הַכֶּסֶף שֶׁגָּבִינוּ מֵהֶם הַכֹּל נַחֲזִיר לְךָ\\\":\",2,0],[2,138,8,12,\"וּמָאתַיִם לְנֹטְרִים אֶת פִּרְיוֹ. \\\"וְעוֹד נוֹסִיף הַרְבֵּה מִשֶּׁלָּנוּ וְנִתֵּן לָהֶם, לְרָאשֵׁיהֶם וְחַכְמֵיהֶם\\\", כְּעִנְיָן שֶׁנֶּאֱמַר, \\\"תַּחַת הַנְּחשֶׁת אָבִיא זָהָב\\\":\",3,0],[2,138,8,12,\"לְנֹטְרִים אֶת פִּרְיוֹ. אֵלּוּ תַלְמִידֵי חֲכָמִים; וְאוֹתָם תַּשְׁלוּמִים לְתַלְמִידֵי חֲכָמִים, כְּמוֹ שֶׁנֶּאֱמַר, \\\"כִּי לַיּשְׁבִים לִפְנֵי ה' יִהְיֶה סַחְרָהּ\\\" וְאֶתְנַנָּהּ שֶׁל צוֹר. וְיֵשׁ לְפָרֵשׁ: \\\"וּמָאתַיִם לְנֹטְרִים אֶת פִּרְיוֹ\\\" כְּדִין הַנֶּהֱנֶה מִן הַהֶקְדֵּשׁ, שֶׁמְּשַׁלֵּם קֶרֶן וְחֹמֶשׁ. אַף אָנוּ נְשַׁלֵּם עַל \\\"קֹדֶשׁ יִשְׂרָאֵל לה' רֵאשִׁית תְּבוּאָתוֹ\\\" קֶרֶן וְחֹמֶשׁ, חֻמְשׁוֹ שֶׁל קֶרֶן, וּמָאתַיִם הֵם חֻמְשׁוֹ שֶׁל אֶלֶף:\",4,0],[2,138,8,13,\"הַיּוֹשֶׁבֶת בַּגַּנִּים. הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר לִכְנֶסֶת יִשְׂרָאֵל: \\\"אַתְּ הַנְּפוֹצָה בַגּוֹלָה, רוֹעָה בְגַנִּים שֶׁל אֲחֵרִים וְיוֹשֶׁבֶת בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת\\\":\",1,0],[2,138,8,13,\"חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ. מַלְאֲכֵי הַשָּׁרֵת חֲבֵרַיִךְ, בְּנֵי אֱלֹהִים דֻּגְמָתֵךְ, מַקְשִׁיבִים וּבָאִים לִשְׁמֹעַ קוֹלֵךְ בְּבָתֵּי כְנֵסִיּוֹת:\",2,0],[2,138,8,13,\"הַשְׁמִיעִנִי. וְאַחַר כָּךְ יַקְדִּישׁוּ הֵם, שֶׁנֶּאֱמַר, \\\"בְּרָן יַחַד כּוֹכְבֵי בֹקֶר\\\" אֵלּוּ יִשְׂרָאֵל. וְאַחַר כָּךְ, \\\"וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים\\\":\",3,0],[2,138,8,14,\"בְּרַח דּוֹדִי. מִן הַגּוֹלָה הַזֹּאת וּפְדֵנוּ מִבֵּינֵיהֶם:\",1,0],[2,138,8,14,\"וּדְמֵה לְךָ לִצְבִי. לְמַהֵר הַגְּאֻלָּה, וְהַשְׁרֵה שְׁכִינָתְךָ עַל הָרֵי בְשָׂמִים. הוּא הַר הַמּוֹרִיָּה וּבֵית הַמִּקְדָּשׁ שֶׁיִּבָּנֶה בִמְהֵרָה בְיָמֵינוּ, אָמֵן:\",2,0],[2,139,1,1,\"נְבוּאַת זְכַרְיָה סְתוּמָה הִיא מְאֹד, כִּי יֵשׁ בָּהּ מַרְאוֹת דּוֹמוֹת לַחֲלוֹם הַנִּתָּן לְפִתְרוֹן, וְאֵין אָנוּ יְכוֹלִים לַעֲמֹד עַל אֲמִתַּת פִּתְרוֹנוֹ עַד יָבֹא מוֹרֶה צֶדֶק (הושע י:יב). וּלְפִי הַיְּכֹלֶת אֶתֵּן לֵב לְיַשֵּׁב הַמִּקְרָאוֹת אֶחָד אֶחָד מִן הַפִּתְרוֹנוֹת הַדּוֹמוֹת לוֹ, וְאַחַר פִּתְרוֹנוֹת שֶׁל יוֹנָתָן:\",1,0],[2,139,1,1,\"בַּחֹדֶשׁ הַשְּׁמִינִי. קֹדֶם שֶׁהִתְחִילוּ לַחֲזוֹר וְלִבְנוֹת בַּמְּלָאכָה, שֶׁהֲרֵי בְּעֶשְׂרִים וְאַרְבָּעָה לַחֹדֶשׁ הִתְחִילוּ בָּהּ:\",2,0],[2,139,1,2,\"עַל אֲבוֹתֵיכֶם. שֶׁבְּדוֹר חֻרְבַּן הַבַּיִת:\",1,0],[2,139,1,5,\"אֲבוֹתֵיכֶם אַיֵּה הֵם. רְאוּ שֶׁלָּקוּ מַכָּה רָעָה בָּרָעָב בַּחֶרֶב וּבַשֶּׁבִי:\",1,0],[2,139,1,5,\"וְהַנְּבִיאִים הַלְעוֹלָם יִחְיוּ. וְאִם תֹּאמַר: אַף הַנְּבִיאִים אַיֵּה הֵם, הֲרֵי מֵתוּ? אֲנִי מֵשִׁיב לָכֶם: וְכִי הַנְּבִיאִים הָיָה לָהֶם לְעוֹלָם לִחְיוֹת? אַךְ סוֹפָן מוֹכִיחַ כִּי אֱמֶת הָיָה דִּבְרֵיהֶם, שֶׁכָּל דְּבָרַי וְחֻקַּי גְּזֵרוֹת פֻּרְעָנוּתִי אֲשֶׁר צִוִּיתִי אֶת עֲבָדַי הַנְּבִיאִים עֲלֵיכֶם, הֲלֹא הִשִּׂיגוּ אֲבֹתֵיכֶם.\",2,0],[2,139,1,8,\"רָאִיתִי הַלַּיְלָה וְגוֹ׳. רַבּוֹתֵינוּ פֵּרְשׁוּ מַה שֶּׁפֵּרְשׁוּ בְּאַגָּדַת חֵלֶק (סנהדרין צג.), אַךְ אֵין סֵדֶר הַפָּרָשָׁה וְהַלָּשׁוֹן מִתְיַשֵּׁב בּוֹ:\",1,0],[2,139,1,8,\"וְהִנֵּה אִישׁ. מַלְאָךְ:\",2,0],[2,139,1,8,\"עַל סוּס אָדֹם. רֶמֶז הוּא לִפָּרַע מִכַּשְׂדִּים מִמָּדַי וּפָרַס בַּחֶרֶב וּבַדָּם, כְּמוֹ שֶׁהוּא אוֹמֵר כָּאן ״וְקֶצֶף גָּדוֹל אֲנִי קֹצֵף עַל הָגּוֹיִם״:\",3,0],[2,139,1,8,\"וְאַחֲרָיו סוּסִים אֲדֻמִּים וְגוֹ׳. מוּכָנִים לִשְׁלִיחוּתוֹ שֶׁל מָקוֹם, וְיֵשׁ בָּהֶם מִינֵי צְבָעִים הַרְבֵּה, וְשֶׁבַח הוּא לוֹ. שְׂרֻקִּים. לֹא יָדַעְתִּי מַה צֶבַע הוּא, וְיוֹנָתָן תִּרְגֵּם: ״קְוָוחִין״:\",4,0],[2,139,1,8,\"בֵּין הַהֲדַסִּים אֲשֶׁר בַּמְּצוּלָה. בֵּין אִילָנֵי דְהַדַסַּיָּא דִּבְבָבֶל (סנהדרין צג.):\",5,0],[2,139,1,9,\"וָאֹמַר. לַמַּלְאָךְ אֶחָד אֲשֶׁר הָיָה מַרְאֶה אוֹתִי כָּל זֹאת מָה אֵלֶּה אֲדֹנִי. וְהוּא הָרוֹכֵב עַל סוּס אָדֹם (זכריה א:ח):\",1,0],[2,139,1,10,\"לְהִתְהַלֵּךְ בָּאָרֶץ. לִרְאוֹת אֶת שַׁלְוַת הָעַוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:\",1,0],[2,139,1,12,\"וַיַּעַן מַלְאַךְ ה׳. הוּא הַדּוֹבֵר בִּי:\",1,0],[2,139,1,13,\"וַיַּעַן ה׳ אֶת הַמַּלְאָךְ הַדּוֹבֵר בִּי דְּבָרִים טוֹבִים. לֹא שֶׁשָּׁמַע הַנָּבִיא מַה עָנָה, אַךְ מִמַּה שֶּׁאָמַר הַמַּלְאָךְ לוֹ ״קְרָא לֵאמֹר קִנֵּאתִי וְגוֹ׳״, אֲנִי יוֹדֵעַ שֶׁדְּבָרִים טוֹבִים עָנָהוּ:\",1,0],[2,139,1,14,\"קִנֵּאתִי לְצִיּוֹן. ״מִתְפָּרַע אֲנָא פּוּרְעָנוּת דִּין יְרוּשָׁלַיִם מִן הַמְּצִיקִים לָהּ״:\",1,0],[2,139,1,15,\"הַשַּׁאֲנַנִּים. אֲשֶׁר אֵלּוּ אוֹמְרִים עֲלֵיהֶם, שֶׁהֵם יוֹשְׁבִים וּשְׁקֵטִים:\",1,0],[2,139,1,15,\"אֲשֶׁר אֲנִי קָצַפְתִּי. עַל עַמִּי מְעָט:\",2,0],[2,139,1,15,\"וְהֵמָּה עָזְרוּ. עַל הַקֶּצֶף לְרָעָה:\",3,0],[2,139,1,16,\"וְקָו יִנָּטֶה. לָמֹד חוֹמוֹתֶיהָ אָרְכָּהּ וְרָחְבָּהּ:\",1,0],[2,139,2,2,\"אֵלֶּה הַקְּרָנוֹת. אֵלֶּה הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֲשֶׁר בְּאַרְבַּע רוּחוֹת הַשָּׁמַיִם, אֲשֶׁר נָגְחוּ בְּקַרְנֵיהֶם אֶת יְהוּדָה וִירוּשָׁלִַם, עַד אֲשֶׁר זֵרוּם:\",1,0],[2,139,2,3,\"אַרְבָּעָה חָרָשִׁים. נַגָּרִים הַיּוֹדְעִים לְנַסֵּר אֶת הַקְּרָנוֹת. וְרַבּוֹתֵינוּ פֵּרְשׁוּ בְּמַסֶּכֶת סֻכָּה (סוכה נב:) מִי הֵם:\",1,0],[2,139,2,4,\"וָאֹמַר מָה. אֵלֶּה הַקְּרָנוֹת אֲשֶׁר רָאִיתִי בָּרִאשׁוֹנָה:\",1,0],[2,139,2,4,\"אֲשֶׁר זֵרוּ אֶת יְהוּדָה. וְהִשְׁפִּילוּם, עַד כְּפִי אִישׁ לֹא נָשָׂא רֹאשׁוֹ. וְלֹא נָתְנוּ לְאֶחָד מִבְּנֵי עַמִּי לְהָרִים רֹאשׁ:\",2,0],[2,139,2,4,\"וַיָּבֹאוּ אֵלֶּה. הֶחָרָשִׁים לְהַחֲרִיד אוֹתָן הַקְּרָנוֹת וּלְיַדּוֹת אוֹתָן:\",3,0],[2,139,2,4,\"לְיַדּוֹת. לְהַשְׁלִיךְ:\",4,0],[2,139,2,5,\"חֶבֶל מִדָּה. חוּט הַמִּדָּה לִמְדֹּד אֶת יְרוּשָׁלַיִם כַּמָּה יִהְיֶה אָרְכָּהּ וְרָחְבָּהּ:\",1,0],[2,139,2,7,\"וְהִנֵּה הַמַּלְאָךְ הַדֹּבֵר בִּי יוֹצֵא. הוּא אֲשֶׁר בְּיָדוֹ חֶבֶל הַמִּדָּה:\",1,0],[2,139,2,8,\"רוּץ דַּבֵּר אֶל הַנַּעַר. אַל תֵּצֵא עוֹד לָמֹד, כִּי נִמְלַךְ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּפַמַלְיָא שֶׁלּוֹ, שֶׁלֹּא יְהֵא לָהּ קֶצֶב וְשִׁעוּר (בבא בתרא עה:). וְעַתָּה רוּץ דַּבֵּר אֶל זְכַרְיָה לֵאמֹר פְּרָזוֹת תֵּשֵׁב – מֵאֵין חוֹמָה, כְּדֵי שֶׁיִּתְיַשְּׁבוּ בָהּ כָּל הַבָּא, וְתִגְדַּל מִיּוֹם אֶל יוֹם:\",1,0],[2,139,2,9,\"וַאֲנִי אֶהְיֶה לָּהּ. לְמָגֵן כְּאִלּוּ חוֹמַת אֵשׁ סָבִיב לָהּ, וְגַם בְּתוֹכָהּ תִּשְׁכֹּן שְׁכִינָתִי לִכְבוֹדְכֶם:\",1,0],[2,139,2,10,\"הוֹי הוֹי. אֵין הוֹי אֶלָּא לְשׁוֹן הַכְרָזָה וְהַזְעָקַת קִבּוּץ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״אַכְלוּ לְמַבְדְּרַיָּא״ – הַכְרִיזוּ, כְּמוֹ יַרְעֵם מִן שָׁמַיִם (שמואל ב כב:יד) – ״אַכְלוּ מִן שְׁמַיָּא״:\",1,0],[2,139,2,10,\"וְנֻסוּ מֵאֶרֶץ. צְאוּ גָּלֻיּוֹת עַמִּי מִתּוֹךְ בָּבֶל וְאַשּׁוּר:\",2,0],[2,139,2,11,\"הוֹי צִיּוֹן הִמָּלְטִי. אַף זֶה לְשׁוֹן הַכְרָזָה: הֵאָסְפוּ עַם גָּלוּת צִיּוֹן וְהִמָּלְטוּ מִתּוֹךְ בָּבֶל.\",1,0],[2,139,2,12,\"אַחַר כָּבוֹד. אַחַר כְּבוֹדְכֶם אֲנִי שָׁלוּחַ לְהַגְדִּיל לָכֶם כָּבוֹד. וּמִדְרַשׁ אַגָּדָה (תנחומא בובר, דברים ד): אַחַר כָּבוֹד – אַחַר שֶׁאֲשַׁלֵּם לְעֵשָׂו כָּבוֹד שֶׁכִּבֵּד אֶת אָבִיו:\",1,0],[2,139,2,13,\"וְהָיוּ שָׁלָל לְעַבְדֵיהֶם. לְיִשְׂרָאֵל, שֶׁהֵם עַתָּה עֲבָדִים לָהֶן:\",1,0],[2,139,2,15,\"וְנִלְווּ. וְנִתְחַבְּרוּ:\",1,0],[2,139,2,16,\"וְנָחַל ה׳ אֶת יְהוּדָה. לְנַחֲלָתוֹ וּלְחֶלְקוֹ:\",1,0],[2,139,2,17,\"הַס כָּל בָּשָׂר. כָּל שְׁאָר הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:\",1,0],[2,139,2,17,\"כִּי נֵעוֹר. לְשׁוֹן הֶעָרָה וְהַקָּצָה (תהלים לה:כג):\",2,0],[2,139,3,1,\"לְשִׂטְנוֹ. לְהַשְׂטִינוֹ, עַל שֶׁהָיוּ בָּנָיו נְשׂוּאִים נָשִׁים נָכְרִיּוֹת, כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר עֶזְרָא: ״וַיִּמָּצֵא מִבְּנֵי הַכֹּהֲנִים אֲשֶׁר הוֹשִׁיבוּ נָשִׁים נָכְרִיּוֹת מִבְּנֵי יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק״ (עזרא י:יח):\",1,0],[2,139,3,2,\"יִגְעַר ה׳ בְּךָ הַשָּׂטָן. יִגְעַר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּךָ אַתָּה הַשָּׂטָן, וְחוֹזֵר וְאוֹמֵר וְיִגְעַר ה׳ בְּךָ הוּא הַבֹּחֵר בִּירוּשָׁלִָם, שֶׁלֹּא תִּכָּנֵס לְפָנָיו לְקַטְרֵג עַל הַצַּדִּיק הַזֶּה. הֲלֹא רָאוּי הוּא וְזָכָה לְכָךְ שֶׁהֻצַּל מֵאֵשׁ הַשְּׂרֵפָה:\",1,0],[2,139,3,2,\"הֲלֹא זֶה אוּד מֻצָּל מֵאֵשׁ. מְפֹרָשׁ בְּאַגָּדַת חֵלֶק (סנהדרין צג.) שֶׁהֻשְׁלַךְ עִם אַחְאָב בֶּן קוֹלָיָה וַחֲבֵרוֹ לָאוּר:\",2,0],[2,139,3,3,\"לָבוּשׁ בְּגָדִים צוֹאִים. כְּתַרְגּוּמוֹ: ״הֲווֹ לֵיהּ בְּנִין דְּנָסְבִין לְהוֹן נְשִׁין דְּלָא כַשְׁרִין לִכְהוּנְתָא״, וְהָיָה נֶעֱנָשׁ הוּא עַל שֶׁלֹּא מִיחָה בְּיָדָם (סנהדרין צג.):\",1,0],[2,139,3,4,\"הָסִירוּ הַבְּגָדִים הַצּוֹאִים מֵעָלָיו. יַבְדִּילוּ בָּנָיו אֶת נְשׁוֹתֵיהֶם, וְיִמְחוֹל לוֹ:\",1,0],[2,139,3,4,\"מַחֲלָצוֹת. חֲלִיפוֹת בְּגָדִים נָאִים, כְּלוֹמַר: זְכֻיּוֹת. אֲבָל לְפִי שֶׁדִּמָּה הֶעָוֹן לִבְגָדִים צוֹאִים, דִּמָּה הַזְּכֻיּוֹת לְמַחֲלָצוֹת בְּגָדִים נָאִים וּלְבָנִים:\",2,0],[2,139,3,5,\"וָאֹמַר. אֲנִי זְכַרְיָה:\",1,0],[2,139,3,5,\"יָשִׂימוּ צָנִיף טָהוֹר וְגוֹ׳. בִּקַּשְׁתִּי רַחֲמִים עָלָיו:\",2,0],[2,139,3,6,\"וַיָּעַד. לְשׁוֹן הַתְרָאָה, כְּמוֹ וְאָעִידָה בָם אֶת הַשָּׁמַיִם וְגוֹ׳ (דברים לא:כח):\",1,0],[2,139,3,7,\"אִם בִּדְרָכַי תֵּלֵךְ. וְגַם אֲנִי זֹאת אֶעֱשֶׂה לְךָ:\",1,0],[2,139,3,7,\"אַתָּה תָדִין אֶת בֵּיתִי. תִּשְׁפּוֹט וְתִהְיֶה פָּקִיד עַל בֵּית מִקְדָּשִׁי:\",2,0],[2,139,3,7,\"וְנָתַתִּי לְךָ מַהְלְכִים. כְּתַרְגּוּמוֹ: ״וּבַאֲחָיוּת מֵיתַיָּא אֲחַיֵּינָךְ וְאֶתֵּן לָךְ רַגְלִין דִּמְהַלְּכִין בֵּין שְׂרָפַיָּא הָאִלֵּין״. וּלְפִי פְשׁוּטוֹ: מְבַשְּׂרוֹ עַל בָּנָיו שֶׁיִּזְכּוּ לֶעָתִיד:\",3,0],[2,139,3,7,\"הָעוֹמְדִים. שְׂרָפִים וּמַלְאֲכֵי הַשָּׁרֵת שֶׁאֵין לָהֶם יְשִׁיבָה (שמות רבה כה):\",4,0],[2,139,3,8,\"אַתָּה וְרֵעֶיךָ. חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה הָיוּ (סנהדרין צג.):\",1,0],[2,139,3,8,\"אַנְשֵׁי מוֹפֵת. ״גֻּבְרִין כָּשְׁרִין לְמֵיעֲבַד לְהוֹן נִיסִּין״, שֶׁאַף לָהֶם נַעֲשָׂה נֵס (סנהדרין צג.)׃\",2,0],[2,139,3,8,\"כִּי הִנְנִי מֵבִיא אֶת עַבְדִּי צֶמַח. כִּי עַתָּה זְרֻבָּבֶל פַּחַת יְהוּדָה קָטָן בַּחֲצַר הַמֶּלֶךְ, אֲנִי מַצְמִיחַ לוֹ גְּדֻלָּה וְשֵׁם. נְתַתִּיו לְחֵן בְּעֵינֵי הַמֶּלֶךְ לְמַלֹּאות שְׁאֵלָתוֹ בְּבִנְיַן הַבַּיִת וְהָעִיר, כְּמוֹ שֶׁמְּפֹרָשׁ בְּעֶזְרָא דִּבְרֵי נְחֶמְיָה בֶּן חֲכַלְיָה, וְהוּא זְרֻבָּבֶל, כְּדַאֲמְרִינָן בְּסַנְהֶדְרִין (סנהדרין לח.):\",3,0],[2,139,3,9,\"כִּי הִנֵּה הָאֶבֶן. יְסוֹד הַבַּיִת אֲשֶׁר יְסַדְתֶּם בִּימֵי כּוֹרֶשׁ וּבָטְלוּ עַל יְדֵיכֶם, וְאוֹתוֹ הַיְּסוֹד וְעֹבִי הַחוֹמָה הָיָה מְעַט בְּעֵינֵיכֶם, כְּמוֹ שֶׁמְפֹרָשׁ בְּעֶזְרָא (עזרא ג:יב) וּבִנְבוּאַת חַגַּי (חגי ב:ג):\",1,0],[2,139,3,9,\"עַל אֶבֶן אַחַת שִׁבְעָה עֵינָיִם. סוֹפוֹ לְהַרְחִיב עַל אֶחָד שִׁבְעָה, וְכֵן תִּרְגֵּם יוֹנָתָן ״עַל אַבְנָא חֲדָא שִׁבְעָה עֵינִין חַזְיָן לָהּ״, וּלְשׁוֹן עֵינָיִם לְשׁוֹן מַרְאוֹת. וְלִי נִרְאֶה: שִׁבְעָה עֵינַיִם עַל שֵׁם עֵינֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבְּעֵינָיו וּבְלִבּוֹ לְהוֹסִיף עָלָיו עַל אֶחָד שִׁבְעָה, לְפִי שֶׁדֻּגְמָתוֹ בִּנְבוּאָה זוֹ ״וְרָאוּ אֶת הָאֶבֶן הַבְּדִיל בְּיַד זְרֻבָּבֶל שִׁבְעָה אֵלֶּה עֵינֵי ה׳ הֵמָּה מְשׁוֹטְטִים וְגוֹ׳״ (זכריה ד:י). אֶלָּא לִמֵּד, שֶׁנָּתַן עֵינָיו לְהַרְבּוֹת כְּבוֹד הַבַּיִת בְּבִנְיָנוֹ:\",2,0],[2,139,3,9,\"הִנְנִי מְפַתֵּחַ פִּתֻּחָהּ. מַתִּיר קִשּׁוּרֶיהָ, מֵפִיר עֲצַת הָאוֹיְבִים אֲשֶׁר כָּתְבוּ שִׂטְנָה לְבַטֵּל הַמְּלָאכָה (עזרא ד:ו):\",3,0],[2,139,3,9,\"וּמַשְׁתִּי. וַהֲסִירוֹתִי:\",4,0],[2,139,3,9,\"בְּיוֹם אֶחָד. לֹא יָדַעְתִּי אֵיזֶה יוֹם. [תוספת: בְּיוֹם אֲשֶׁר הִתְחִילוּ לְהוֹסִיף עַל הַבִּנְיָן יָמִישׁ עֲוֺן הָאָרֶץ וְתִהְיֶה בְּרָכָה בְּפֵירוֹתָיו, כִּי עַכְשָׁיו מְאֵירָה כְּמוֹ שֶׁנֶּאֱמַר בִּנְבוּאַת חַגַּי (חגי ב:טז)]:\",5,0],[2,139,4,2,\"וְגֻלָּה עַל רֹאשָׁהּ. כְּמוֹ (יהושע טו:יט) גֻּלּוֹת עִלִּית, לְשׁוֹן מַעְיָן, כְּמִין סֵפֶל גָּדוֹל עָגוֹל:\",1,0],[2,139,4,2,\"וְשִׁבְעָה נֵרֹתֶיהָ. כְּמִין בָּזִיכִין שֶׁנּוֹתְנִין הַשֶּׁמֶן וְהַפְּתִילָה לְתוֹכָהּ:\",2,0],[2,139,4,2,\"שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת. לְכָל נֵר וָנֵר בָּאִין שִׁבְעָה צִנּוֹרוֹת קְטַנִּים, שֶׁהַשֶּׁמֶן זָב מִן הַגֻּלָּה דֶּרֶךְ אוֹתָן מוּצָקוֹת לְכָל נֵר וָנֵר:\",3,0],[2,139,4,3,\"וּשְׁנַיִם זֵיתִים עָלֶיהָ. אֶצְלָהּ שְׁנֵי אִילָנוֹת שֶׁהַזֵּיתִים גְּדֵלִים בָּהֶם:\",1,0],[2,139,4,3,\"אֶחָד מִימִין הַגֻּלָּה וְאֶחָד מִשְּׂמֹאלָהּ וְגוֹ׳. וְכָאן לֹא פֵּרַשׁ עַל שְׁנֵי צַנְתְּרוֹת זָהָב הָאֲמוּרוֹת לְמַטָּה בַּפָּרָשָׁה, וְהֵם כְּמִין עֲרֵבוֹת וַעֲדָשִׁים שֶׁל בֵּית הַבַּד, שֶׁהֵם עוֹמְדִים אֵצֶל הַזֵּיתִים, וְהַזֵּיתִים נֶחְבָּטִים מֵאֲלֵיהֶם לְתוֹךְ הַצַּנְתְּרוֹת וּמִתְחַמְּמוֹת שָׁם כְּבַמַּעֲטָן וְנֶעֱצָרִים שָׁם בְּבֵית הַבַּד, וְהַשֶּׁמֶן נוֹפֵל לְתוֹךְ הַצַּנְתְּרוֹת וּמֵהַצַּנְתְּרוֹת לְתוֹךְ הַגֻּלָּה, וּמֵהַגֻּלָּה אֶל הַמּוּצָקוֹת, וּמֵהַמּוּצָקוֹת אֶל הַנֵּרוֹת. וְהַמּוּצָקוֹת וְהַנֵּרוֹת אַרְבָּעִים וְתֵשַׁע הָיוּ, רֶמֶז לָאוֹר שֶׁלֶּעָתִיד לָבֹא, אוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שֶׁל שִׁבְעַת יָמִים (ישעיה ל:כו), אַרְבָּעִים וְתֵשַׁע עַל אוֹר שֶׁל יוֹם בְּרֵאשִׁית:\",2,0],[2,139,4,4,\"מָה אֵלֶּה אֲדֹנִי. מַה זֶּה שֶׁהַזֵּיתִים נִמְסָקִים מֵאֲלֵיהֶם, וְהַשֶּׁמֶן בָּא אֶל הַנֵּרוֹת מֵאֵלָיו:\",1,0],[2,139,4,6,\"זֶה דְּבַר ה׳ אֶל זְרֻבָּבֶל. זֶה סִימָן לְךָ לְהַבְטִיחַ אֶת זְרֻבָּבֶל, כְּשֵׁם שֶׁהַזֵּיתִים וְהַשֶּׁמֶן הַזֶּה נִגְמָר מֵאֵלָיו לְכָל דְּבָרָיו, כָּךְ לֹא בְחַיִל וְלֹא בְכֹחַ שֶׁבָּכֶם תַּעֲשׂוּ אֶת בִּנְיַן בֵּיתִי:\",1,0],[2,139,4,6,\"כִּי אִם בְּרוּחִי. אֲנִי אֶתֵּן רוּחִי עַל דָּרְיָוֶשׁ וְיַנִּיחַ לָכֶם (ספרים אחרים: וִיצַוֶּה לָכֶם) לִבְנוֹת וְלַעֲשׂוֹת כָּל צָרְכֵי יְצִיאַת הַבִּנְיָן מִשֶּׁלּוֹ, וְלַעֲזֹר אֶתְכֶם בְּחִטִּין וְיַיִן וְשֶׁמֶן וְעֵצִים, כְּמוֹ שֶׁמְּפֹרָשׁ בְּעֶזְרָא (עזרא ו:ח-ט). וְלֹא תִצְטָרְכוּ לְעֶזְרַת אָדָם:\",2,0],[2,139,4,7,\"מִי אַתָּה הַר הַגָּדוֹל. שָׂרֵי עֵבֶר הַנָּהָר ״תַּתְּנַי פַּחַת עֵבֶר נַהֲרָה וּשְׁתַר בּוֹזְנַי וּכְנָוָתְהוֹן״ (עזרא ה:ג), שֶׁבִּטַּלְתֶּם הַמְּלָאכָה עַד כֹּה; מֵעַתָּה תִּהְיֶה לִפְנֵי זְרֻבָּבֶל לְמִישׁוֹר, אֵין לָכֶם שְׂרָרָה וּגְדֻלָּה עוֹד עָלָיו:\",1,0],[2,139,4,7,\"וְהוֹצִיא אֶת הָאֶבֶן הָרֹאשָׁה. הָאַדְרִיכָל יִקַּח אֶת אֶבֶן הַבְּדִיל בְּיָדוֹ (זכריה ד:י) לִהְיוֹת אַדְרִיכָל בְּרֹאשׁ הַבּוֹנִים, וְהֵם יִבְנוּ הַכֹּל כְּפִי דְּבָרָיו אֲשֶׁר יְצַוֶּה בְּבִנְיָן נָאֶה וּמְפֹאָר:\",2,0],[2,139,4,7,\"תְּשׁוּאוֹת חֵן חֵן. יִהְיֶה לָהּ לְאוֹתָהּ הָאֶבֶן שֶׁהַכֹּל יֹאמְרוּ מַה נָּאֶה בִּנְיָן זֶה הֶעָשׂוּי עַל יְדֵי אֶבֶן הַמִּשְׁקֹלֶת הַזֹּאת, תְּשׁוּאוֹת חֵן כְּמוֹ תְּשׁוּאוֹת נוֹי כְּמוֹ ״תְּשׁוּאוֹת מְלֵאָה עִיר הוֹמִיָּה״ (ישעיהו כב:ב), ״קוֹל שָׁאוֹן״ (ישעיהו סו:ו) כֻּלָּם לְשׁוֹן הַשְׁמָעַת קוֹל הֵם:\",3,0],[2,139,4,9,\"יְדֵי זְרֻבָּבֶל יִסְּדוּ הַבַּיִת הַזֶּה. מִתְּחִלָּה וְעַד סוֹף בִּימֵי כּוֹרֶשׁ הָרִאשׁוֹן (עזרא ג:י):\",1,0],[2,139,4,9,\"וִידָיו תְּבַצַּעְנָה. אוֹתוֹ עַתָּה, תְּבַצַּעְנָה לְשׁוֹן גְּמַר הוּא, כְּמוֹ ״כִּי יְבַצַּע ה׳ כָּל מַעֲשֵׂהוּ״ (ישעיה י:יב):\",2,0],[2,139,4,10,\"כִּי מִי בַז לְיוֹם. שֶׁיֻּסַּד הַבַּיִת אֲשֶׁר הֻקְטַן בְּעֵינֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (עזרא ג:יב) ״וְרַבִּים מֵהַכֹּהֲנִים אֲשֶׁר רָאוּ הַבַּיִת הָרִאשׁוֹן בְּיָסְדוֹ זֶה הַבַּיִת בְּעֵינֵיהֶם בֹּכִים בְּקוֹל גָּדוֹל״, וּבִנְבוּאַת חַגַּי (חגי ב:ג) ״הֲלֹא כְמוֹהוּ כְּאַיִן בְּעֵינֵיהֶם״. וְשָׂמְחוּ עַתָּה כְּשֶׁיִּרְאוּ אֶת הָאֶבֶן הַבְּדִיל הַתְּלוּיָה בְּחוּט הַמִּשְׁקֹלֶת בְּיַד אַדְרִיכַל רֹאשׁ הַבּוֹנִים, שֶׁמְּכַוֵּן בָּהּ רֹאשׁ הַפִּנָּה. וְזוֹ תִּהְיֶה בְּיַד זְרֻבָּבֶל.\",1,0],[2,139,4,10,\"שִׁבְעָה אֵלֶּה. עַל אֶחָד שִׁבְעָה בַּיְּסוֹד הָרִאשׁוֹן שֶׁבִּימֵי כּוֹרֶשׁ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״שִׁבְעָה נִדְבָּכִין כְּאִלֵּין״:\",2,0],[2,139,4,10,\"עֵינֵי ה׳ הֵמָּה מְשׁוֹטְטִים. וְלוֹ נִרְאֶה לַעֲשׂוֹת כֵּן, וְהוּא רָאָה אֶת זְרֻבָּבֶל זֶה הָגוּן לַדָּבָר:\",3,0],[2,139,4,11,\"מַה שְּׁנֵי הַזֵּיתִים. מָה רֶמֶז הֵם, וּמָה רֶמֶז שְׁנֵי שִׁבֲּלֵי זֵיתִים טְרוֹקָ״א בְּלַעַ״ז, קְבוּצוֹת זֵיתִים בְּעָנָף כְּעֵין שִׁבֹּלֶת:\",1,0],[2,139,4,12,\"אֲשֶׁר בְּיַד שְׁנֵי צַנְתְּרוֹת. כְּלוֹמַר: אֵצֶל שְׁנֵי הַצַּנְתְּרוֹת, כְּמוֹ ״רְאוּ חֶלְקַת יוֹאָב אֶל יָדִי״ (שמואל ב יד:ל):\",1,0],[2,139,4,12,\"הַמְּרִיקִים מֵעֲלֵיהֶם. אֶת הַשֶּׁמֶן הַזֶּה הַצָּלוּל וְטוֹב לְהָאִיר כְּזָהָב, כְּמוֹ (אִיּוֹב לז:כב) ״מִצָּפוֹן זָהָב יֶאֱתֶה״:\",2,0],[2,139,4,14,\"שְׁנֵי בְנֵי הַיִּצְהָר. קֶרֶן כְּהֻנָּה וּמַלְכוּת, הַנִּמְשָׁחִים בְּשֶׁמֶן הַמִּשְׁחָה:\",1,0],[2,139,4,14,\"הָעוֹמְדִים עַל אֲדוֹן כָּל הָאָרֶץ. לְבַקֵּשׁ מִלְּפָנָיו לְהַחֲזִיר אֶת גְּדֻלָּתָם:\",2,0],[2,139,4,14,\"שְׁנֵי בְנֵי הַיִּצְהָר. יֵצֶר טוֹב וְיֵצֶר הָרָע מִתְהַפֵּךְ לְטוֹב בִּזְכוּת הַתּוֹרָה:\",3,0],[2,139,5,1,\"מְגִלָּה עָפָה. רַבּוֹתֵינוּ פֵּרְשׁוּ כְּפוּלָה וְאָמְרוּ שֶׁהַתּוֹרָה כְּתוּבָה בָּהּ וְלָמְדוּ מִכָּאן שֶׁהָעוֹלָם אֶחָד מִשְּׁלֹשֶׁת אֲלָפִים וּמָאתַיִם בַּתּוֹרָה כִּדְאִיתָא בְּעֵירוּבִין (עירובין כא.) וְיוֹנָתָן תִּרְגֵּם ״מְגִלְּתָא פָּרְחָא פּוֹרַחַת בָּאֲוִיר״, וּלְפִי פְשׁוּטוֹ שֶׁל פָּרָשָׁה מְגִלַּת פֻּרְעָנוּת הָיְתָה וְהוּא שֶׁרָאָה (יחזקאל ב:י) ״וְכָתוּב אֵלֶיהָ קִינִים וָהֶגֶה וָהִי״:\",1,0],[2,139,5,3,\"זֹאת הָאָלָה. זֹאת שֶׁכָּתוּב בָּהּ פֻּרְעָנוּת נִקְמַת שְׁבוּעוֹת שֶׁקֶר:\",1,0],[2,139,5,3,\"הַיּוֹצֵאת. עַתָּה מִבֵּית קָדְשֵׁי הַקֳּדָשִׁים מִלִּפְנֵי הַשְּׁכִינָה לְהִתְהַלֵּךְ עַל פְּנֵי כָל הָאָרֶץ וְזֶהוּ אָרְכָּהּ עֶשְׂרִים וְרָחְבָּהּ עֶשֶׂר (זכריה ה:ב) כְּמִדַּת פֶּתַח הָעֲזָרָה וְהַהֵיכָל (מלכים א ו:ג) אֲשֶׁר יָצְאָת דֶּרֶךְ שָׁם:\",2,0],[2,139,5,3,\"כִּי כָל הַגֹּנֵב. עַד עַכְשָׁיו:\",3,0],[2,139,5,3,\"מִזֶּה כָּמוֹהָ נִקָּה. מִזֶּה הַפֻּרְעָנוּת כְּמוֹ שֶׁהוּא מְפֹרָשׁ בָּהּ נִקָּה וְלֹא נִשְׁתַּלֵּם פֻּרְעָנוּת יְחִידִים הָעוֹבְרִים עַל הַתּוֹרָה, אֶלָּא הִמְתִּין עַד שֶׁנִּתְמַלֵּאת סְאַת כֻּלָּם, וְלָקוּ כֻּלָּם כְּאֶחָד בַּחֻרְבָּן וּבַגּוֹלָה. וְכֵן כָּל הַנִּשְׁבָּע לַשֶּׁקֶר עַד הֵנָּה מִזֶּה הַפֻּרְעָנוּת, כְּמוֹ שֶׁהַמְּגִלָּה הַזֹּאת מַגֶּדֶת: נִקָּה וְלֹא נִשְׁתַּלֵּם. אֲבָל מִכָּאן וָאֵילָךְ הוֹצֵאתִיהָ לָשׁוּט בָּאָרֶץ וְלִנְקֹם מִן הַגַּנָּבִים וְהַנִּשְׁבָּעִים לַשֶּׁקֶר מֵעַכְשָׁיו, וּבָא אֶל בֵּית הַגַּנָּב וְגוֹ׳:\",4,0],[2,139,5,5,\"שָׂא נָא עֵינֶיךָ וּרְאֵה. עוֹד יוֹצֵאת אַחֶרֶת שֶׁתֵּצֵא מִבֵּית קֹדֶשׁ הַקֳּדָשִׁים:\",1,0],[2,139,5,6,\"וָאֹמַר מַה הִיא. הַיּוֹצֵאת שֶׁתֹּאמַר אֵלַי לִרְאוֹת:\",1,0],[2,139,5,6,\"וַיֹּאמֶר זֹאת הָאֵיפָה. שֶׁתֵּרָאֶה יוֹצֵאת כְּמִין אֵיפָה שֶׁמּוֹדְדִין בָּהּ:\",2,0],[2,139,5,6,\"וַיֹּאמֶר זֹאת עֵינָם בְּכָל הָאָרֶץ. וּלְאַחַר שֶׁרְאִיתִיהָ אָמַר: זֹאת הִיא מִדָּה שֶׁלָּקוּ בָּהּ אוֹתָם שֶׁעֵינֵיהֶם בְּכָל הָאָרֶץ לִגְזֹל וְלַעֲשֹׁק, ״לְהַקְטִין אֵיפָה וּלְהַגְדִּיל שֶׁקֶל״ (עמוס ח:ה), וְנִמְדַּד לָהֶם סְאָה בִּסְאָה:\",3,0],[2,139,5,7,\"וְהִנֵּה כִּכַּר עוֹפֶרֶת נִשֵּׂאת. רָאִיתִי שֶׁנִּשֵּׂאת מֵעַל הָאָרֶץ לָאֲוִיר מִשְׁקַל כִּכַּר עוֹפֶרֶ,ת וְרָאִיתִי עוֹד זֹאת אִשָּׁה אַחַת יוֹשֶׁבֶת בְּתוֹךְ הָאֵיפָה:\",1,0],[2,139,5,8,\"וַיֹּאמֶר זֹאת הָרִשְׁעָה. הָאִשָּׁה זֹאת שֶׁאַתָּה רוֹאֶה בְּתוֹךְ הָאֵיפָ,ה הִיא מִדַּת דֶּרֶךְ הָרִשְׁעָה אֲשֶׁר יִנְהֲגוּ בָּהּ הָרְשָׁעִים, וְהִנֵּה עַתָּה נְתוּנִים בְּתוֹכָהּ לִלְקוֹת בְּתוֹךְ הַסְּאָה עַצְמָהּ שֶׁמָּדְדוּ בָּהּ, מִדָּה בְּמִדָּה:\",1,0],[2,139,5,8,\"וַיַּשְׁלֵךְ אֹתָהּ. עַד עַתָּה הָיְתָה יוֹשֶׁבֶת, וְהוּא הִשְׁלִיכָהּ וְחָבְטָהּ לְתוֹכָהּ, רֶמֶז לְיִסּוּרִים וְלָעֳנָשִׁים:\",2,0],[2,139,5,8,\"וַיַּשְׁלֵךְ אֶת אֶבֶן הָעוֹפֶרֶת אֶל פִּיהָ. לְשַׁקְּעָהּ, לְמַעַן לֹא יִגְדְּלוּ עוֹד, וְלֹא יִשָּׁמַע קוֹלָן לְשַׁדֵּד עֲנִיִּים וְאֶבְיוֹנִים:\",3,0],[2,139,5,9,\"שְׁתַּיִם נָשִׁים יוֹצְאוֹת. מִן הַבַּיִת:\",1,0],[2,139,5,9,\"הַחֲסִידָה. דַּיָּה לְבָנָה וולטויא״ר בְּלַעַ״ז (חולין סג.)׃\",2,0],[2,139,5,11,\"וְהוּכַן וְהֻנִּיחָה שָׁם. וְהוּכַן הַבַּיִת וְהֻנְּחָה הָאֵיפָה עִם הָרְשָׁעִים שֶׁבְּתוֹכָהּ:\",1,0],[2,139,5,11,\"שָׁם. בְּאוֹתוֹ הַבַּיִת:\",2,0],[2,139,5,11,\"עַל מְכוּנָתָהּ. עַל קְבִיעוּתָהּ וְעַל בְּסִיסָהּ. כָּאן רָמַז לוֹ, שֶׁבַּעֲוֹנָם שֶׁל יִשְׂרָאֵל שֶׁמָּדְדוּ בִּסְאַת עֲבֵרוֹת וָרֶשַׁע, לָקוּ בְּאוֹתָהּ מִדָּה. וּבָאוּ שְׁתֵּי אֻמּוֹת שֶׁמָּלְכוּ כְּאַחַת, הֵם בָּבֶל וְכַשְׂדִים, חֵיל נְבוּכַדְנֶצַּר, וְהִגְלוּם לְבָבֶל; וְשָׁם עָמְדוּ קְבוּעִים עַל מְכוֹן בָּסִיס הַהֻקְבַּע לָהֶם, וְהוּא לְפִי מְלֹאות שִׁבְעִים שָׁנָה עַד עַתָּה (ירמיה כט:י), שֶׁחָזְרוּ. וְנוֹטֶה פֵּרוּשׁ זֶה אַחַר יוֹנָתָן בְּמִקְצָת. וְכַמָּה דְּרָכִים פּוֹתְרִים בָּהּ, וְלֹא נִתְיַשְּׁבוּ לִי. וְרַבּוֹתֵינוּ פֵּרְשׁוּ וְלָמְדוּ מִכָּאן, שֶׁנִּמְסַר לָהֶם יֵצֶר הָרַע לְאַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה, וְשַׁדְיוּהּ לְדוּדָא דְּאַבְרָא וְחַפְיוּהוּ בְּאַבְרָא מִשּׁוּם דְּשָׁאִיב קָלֵיהּ, כִּדְאִיתָא בְּסַנְהֶדְרִין (סנהדרין סד.) וּבְמַסֶּכֶת יוֹמָא (יומא סט:). וְשֶׁפָּתַרְתִּי מַלְכוּת נְבוּכַדְנֶצַּר בְּכֶפֶל שְׁתֵּי אֻמּוֹת – רָאִיתִי בְּמִדְרַשׁ תִּילִּים, שֶׁאַרְבַּע מַלְכֻיּוֹת הַלָּלוּ שֶׁשִּׁעְבְּדוּ בְּיִשְׂרָאֵל, כְּפוּלוֹת הָיוּ: בָּבֶל וְכַשְׂדִים, מָדַי וּפָרַס, אַנְטִיוֹכוּס וּמוֹקְדוֹן, אֱדוֹם וְיִשְׁמָעֵאל. וְעַל כָּכָה יִסֵּד הַקָּלִירִי: רְבִיעִית הִיא שְׁמִינִית, עַל אֱדוֹם:\",3,0],[2,139,6,1,\"וְהֶהָרִים הָרֵי נְחֹשֶׁת. סִימָן עַל חֹזֶק מַלְכֻיּוֹת הַלָּלוּ הַבָּא לָהֶם מִבֵּין שְׁנֵי הֶהָרִים שֶׁהוּא קָשֶׁה וְאַמִּיץ, שֶׁאֵלּוּ אַרְבַּע מַרְכָּבוֹת שְׁלוּחֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת מֶמְשֶׁלֶת לְאַרְבַּע מַלְכֻיּוֹת: בָּבֶל וּמָדַי יָוָן וֶאֱדוֹם:\",1,0],[2,139,6,2,\"סוּסִים אֲדֻמִּים. הֵם שֶׁהִרְכִּיבוּ אֶת בָּבֶל, שֶׁהִיא אֲדֻמָּה, כְּמוֹ שֶׁכָּתוּב ״אַנְתְּ הוּא רֵאשָׁה דִּי דַהֲבָא״ (דניאל ב:לח):\",1,0],[2,139,6,2,\"שְׁחוֹרִים. לְהַרְכִּיב אֶת מָדַי שֶׁהִשְׁחִירָה אֶת פְּנֵיהֶם שֶׁל יִשְׂרָאֵל בִּימֵי הָמָן (מגילה יא.):\",2,0],[2,139,6,3,\"לְבָנִים. לְהַרְכִּיב אֶת פָּרַס שֶׁבָּנָה אֶת הַבַּיִת (אבות דרבי נתן נוסחא ב כה,ב):\",1,0],[2,139,6,3,\"בְּרֻדִּים. הֵמָּה מְנֻמָּרִים, לְהַרְכִּיב אֶת יָוָן, שֶׁעִנּוּ אֶת יִשְׂרָאֵל בְּמִינֵי גְּזֵרוֹת מְשֻׁנּוֹת זוֹ מִזֶּה (ויקרא רבה יג:ה):\",2,0],[2,139,6,3,\"אֲמֻצִּים. לְהַרְכִּיב יִשְׁמָעֵאל (ספרים אחרים: אֱדוֹם) וְלֹא יָדַעְתִּי מַהוּ לְשׁוֹן אֲמֻצִּים, וְיוֹנָתָן תִּרְגֵּם ״קִטְמָנִין״:\",3,0],[2,139,6,5,\"אֵלֶּה אַרְבַּע רוּחוֹת הַשָּׁמַיִם. שָׂרֵי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת מַלְכֻיּוֹת הַקַּדְמוֹנִיּוֹת הַמּוֹשְׁלוֹת בְּאַרְבַּע רוּחוֹת הַשָּׁמַיִם:\",1,0],[2,139,6,5,\"יוֹצְאוֹת מֵהִתְיַצֵּב וְגוֹ׳. בָּאוּ לְפָנָיו וְנָתַן לָהֶם רְשׁוּת מִפִּיו לִמְשֹׁל:\",2,0],[2,139,6,6,\"אֲשֶׁר בָּהּ הַסּוּסִים הַשְּׁחֹרִים יוֹצְאִים אֶל אֶרֶץ צָפוֹן. לְהַרְכִּיב אֶת מָדַי. וְעַל הָאֲדוּמִים לֹא כָּתַב יוֹצְאִים, שֶׁכְּבָר כָּלְתָה לָהּ מֶמְשֶׁלֶת בָּבֶל:\",1,0],[2,139,6,6,\"וְהַלְּבָנִים יָצְאוּ אֶל אַחֲרֵיהֶם. לְהַרְכִּיב אֶת פָּרַס, שֶׁשְּׁתֵּיהֶן בַּצָּפוֹן, וּמָשְׁלוּ עַל בָּבֶל:\",2,0],[2,139,6,6,\"וְהַבְּרֻדִּים יָצְאוּ אֶל אֶרֶץ הַתֵּימָן. לְהַרְכִּיב אֶת יָוָן וְיִטְּלוּ הַמְּלוּכָה מִיַּד פָּרַס. וּבְפִתְרוֹנוֹ לְרַב סְעַדְיָה בְּדָנִיֵּאל רָאִיתִי מֶלֶךְ הַנֶּגֶב הוּא מֶלֶךְ יָוָן (דניאל יא:ה):\",3,0],[2,139,6,7,\"וְהָאֲמֻצִּים יָצְאוּ וַיְבַקְשׁוּ. מִלְּפָנָיו שֶׁיְּהֵא אֹרֶךְ גָּדוֹל לְמֶמְשַׁלְתָּם, לָלֶכֶת בְּכָל הָאָרֶץ:\",1,0],[2,139,6,7,\"וַיֹּאמֶר לְכוּ הִתְהַלְּכוּ בָאָרֶץ. נָתַן לָהֶם רְשׁוּת לִמְשֹׁל מִמְשָׁל רַב (דניאל יא:ג), וְהוּא מַלְכוּת אֱדוֹם:\",2,0],[2,139,6,8,\"רְאֵה הַיּוֹצְאִים אֶל אֶרֶץ צָפוֹן. לְהַרְכִּיב מָדַי וּפָרָס:\",1,0],[2,139,6,8,\"הֵנִיחוּ אֶת רוּחִי. שִׁכְּכוּ אֶת חֲמָתִי בְּבָבֶל, שֶׁהִשְׁחִיתוּ אֶת בֵּלְשַׁצַּר וְזַרְעוֹ שֶׁל נְבוּכַדְנֶצַּר (דניאל ה:ל). הוּא שֶׁאָמַר (ישעיהו מח:יד) ״ה׳ אֲהֵבוֹ יַעֲשֶׂה חֶפְצוֹ בְּבָבֶל וְגוֹ׳״:\",2,0],[2,139,6,10,\"לָקוֹחַ מֵאֵת הַגּוֹלָה מֵחֶלְדַּי וְגוֹ׳, אֲשֶׁר בָּאוּ מִבָּבֶל. כָּל הָאֲנָשִׁים הָאֵלֶּה:\",1,0],[2,139,6,12,\"צֶמַח שְׁמוֹ. הוּא זְרֻבָּבֶל הָאָמוּר לְמַעְלָה ״הִנְנִי מֵבִיא אֶת עַבְדִּי צֶמַח״ (זכריה ג:ח), וְעַל שֵׁם שֶׁצָּמְחָה גְּדֻלָּתוֹ מְעַט מְעַט. וְיֵשׁ פּוֹתְרִים אוֹתוֹ (תנחומא קרח יב) בְּמֶלֶךְ הַמָּשִׁיחַ, אֲבָל כָּל הָעִנְיָן הַזֶּה מְדַבֵּר בְּבַיִת שֵׁנִי:\",1,0],[2,139,6,12,\"וּמִתַּחְתָּיו יִצְמָח. מִזֶּרַע הַמְּלוּכָה:\",2,0],[2,139,6,13,\"וְהוּא יִשָּׂא הוֹד. הוֹד נְשִׂיאוּת:\",1,0],[2,139,6,13,\"וְיָשַׁב. כֹּהֵן גָּדוֹל עַל כִּסֵּא הַכְּהֻנָּה:\",2,0],[2,139,6,13,\"וַעֲצַת שָׁלוֹם וְגוֹ׳. הַנָּשִׂיא וְהַכֹּהֵן יֹאהֲבוּ זֶה אֶת זֶה:\",3,0],[2,139,6,14,\"וְהָעֲטָרוֹת תִּהְיֶה לְחֵלֶם וְגוֹ׳. מִקְרָא מְסֹרָס הוּא, וְהָעֲטָרוֹת תִּהְיֶינָה בְּהֵיכַל ה׳ לְזִכָּרוֹן טוֹב לְחֵלֶם וּלְטוֹבִיָּה אֲשֶׁר הִתְנַדְּבוּ הַכֶּסֶף וְהַזָּהָב. וְאוֹתָן עֲטָרוֹת הָיוּ תְּלוּיוֹת בַּחֲלוֹנוֹת בְּגֹבַהּ הַהֵיכָל, כְּמוֹ שֶׁשָּׁנִינוּ בְּמַסֶּכֶת מִדּוֹת (מידות ג,ח):\",1,0],[2,139,6,14,\"חֵלֶם. הוּא חֶלְדָּי (זכריה ו:י):\",2,0],[2,139,6,15,\"וְהָיָה אִם שָׁמוֹעַ. וְהָיָה לָכֶם הַדָּבָר הַזֶּה אִם שָׁמוֹעַ תִּשְׁמְעוּ וְגוֹ׳:\",1,0],[2,139,7,2,\"וַיִּשְׁלַח בֵּית אֵל שַׂרְאֶצֶר וְרֶגֶם מֶלֶךְ וַאֲנָשָׁיו. אֲנָשִׁים צַדִּיקִים הָיוּ, וְשָׁלְחוּ מִבָּבֶל לִקְרוֹבֵיהֶם שֶׁבְּבֵית אֵל לָבֹא לְחַלּוֹת אֶת פְּנֵי ה׳ בִּירוּשָׁלַיִם בַּעֲדָם, וְלִשְׁאֹל מֵאֵת הַכֹּהֲנִים לְהוֹדִיעָם אִם יִבְכּוּ בְּחֹדֶשׁ אָב, אַחֲרֵי אֲשֶׁר חָזַר הַבַּיִת לְהִבָּנוֹת:\",1,0],[2,139,7,3,\"הַנָּזֵר. לִפְרוֹשׁ מִן הַתַּעֲנוּג כַּאֲשֶׁר עָשִׂיתִי זֶה שִׁבְעִים שָׁנָה. אֵין נְזִירָה בְּכָל מָקוֹם אֶלָּא פְּרִישׁוּת (ספרא אמור פרשה ד, א):\",1,0],[2,139,7,5,\"וּבַשְּׁבִיעִי. הוּא צוֹם גְּדַלְיָה (ראש השנה יח:):\",1,0],[2,139,7,5,\"הֲצוֹם צַמְתֻּנִי אָנִי. הֵ״א נְקוּדָה חֲטַף פַּתָּח, לְפִי שֶׁהִיא מְשַׁמֶּשֶׁת לְשׁוֹן תְּמִיהָא: שֶׁמָּא לִכְבוֹדִי צַמְתֶּם, שֶׁתִּהְיוּ צְרִיכִים לָצוּם גַּם עַתָּה?:\",2,0],[2,139,7,6,\"וְכִי תֹאכְלוּ וְכִי תִשְׁתּוּ. וְאִם לֹא תָצוּמוּ, מַה לִּי גַּם בָּזוֹ? הֲלֹא אַתֶּם לַהֲנָאַתְכֶם הוּא הַמַּאֲכָל וְהַמִּשְׁתֶּה:\",1,0],[2,139,7,7,\"הֲלֹא אֶת הַדְּבָרִים. מִי גָּרַם לָכֶם הַצּוֹם וְהַמִּסְפֵּד? הֲלֹא דִבְרֵי תוֹכָחוֹת אֲשֶׁר קָרָא ה׳ וְגוֹ׳, הֵם הֶחֱרִיבוּ אֶתְכֶם, וְעַל כֵּן צַמְתֶּם. וְאֵלֶּה הַדְּבָרִים אֲשֶׁר קָרָא: ״מִשְׁפַּט אֱמֶת שְׁפֹטוּ״ (זכריה ז:ט):\",1,0],[2,139,7,12,\"שָׂמוּ שָׁמִיר. תּוֹלַעַת חָזָק מִצּוּר, מַרְאִין אוֹתוֹ עַל הָאֶבֶן וְהִיא מִתְבַּקַּעַת (סוטה מח:):\",1,0],[2,139,7,13,\"וַיְהִי כַּאֲשֶׁר קָרָא וְלֹא שָׁמֵעוּ. אָמַר ה׳ צְבָאוֹת עֲלֵיהֶן בְּאוֹתָן הַיָּמִים כֵּן יִקְרְאוּ וְלֹא אֶשְׁמָע:\",1,0],[2,139,7,14,\"וָאֵסָעֲרֵם. בַּגָּלוּת, וְכֵן עָשִׂיתִי:\",1,0],[2,139,7,14,\"וַיָּשִׂימוּ. בַּעֲוֹנָם:\",2,0],[2,139,7,14,\"אֶרֶץ חֶמְדָּה לְשַׁמָּה. וְהוּא גָּרַם לָהֶם הַצּוֹם וְהַמִּסְפֵּד, אֲבָל עַתָּה: ״קִנֵּאתִי לְצִיּוֹן״ (זכריה ח:ב) – בִּשְׁבִיל צִיּוֹן אֲקַנֵּא אֶת הַכַּשְׂדִּים:\",3,0],[2,139,8,2,\"קִנֵּאתִי לָהּ. בִּשְׁבִילָהּ, וְלֹא תִזָּקְקוּ לָצוּם וְלִסְפֹּד. וְכֵן סוֹף הָעִנְיָן ״צוֹם הַחֲמִישִׁי וְגוֹמֵר״ (זכריה ח:יט):\",1,0],[2,139,8,4,\"מֵרֹב יָמִים. יִהְיוּ צְרִיכִים לְמִשְׁעֶנֶת בְּיָדָם:\",1,0],[2,139,8,6,\"כִּי יִפָּלֵא. בְּעֵינֵיהֶם הַחֶסֶד הַגָּדוֹל אֲשֶׁר אֶעֱשֶׂה לָהֶם:\",1,0],[2,139,8,6,\"גַּם בְּעֵינַי יִפָּלֵא. אֵיךְ שַׁבְתִּי מִן הֶחָרוֹן הַגָּדוֹל. וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ עַל שְׁחִיטַת יֵצֶר הָרָע בְּמַסֶּכֶת סֻכָּה (סוכה נב.): בְּעֵינַי יִפָּלֵא אֵיךְ יוּכְלוּ הַצַּדִּיקִים לַעֲמֹד כְּנֶגְדּוֹ בְּחַיֵּיהֶם:\",2,0],[2,139,8,9,\"תֶּחֱזַקְנָה יְדֵיכֶם. לִבְנוֹת וּלְהַשְׁלִים, וְאַל תִּירְאוּ מֵעַם הָאָרֶץ הַמְרַפִּים יְדֵיכֶם וּמְבַהִילִים אֶתְכֶם מִלִּבְנוֹת, וּכְמוֹ שֶׁמְּפֹרָשׁ בְּסֵפֶר עֶזְרָא (עזרא ד:ד):\",1,0],[2,139,8,9,\"הַשּׁוֹמְעִים בַּיָּמִים הָאֵלֶּה. בִּשְׁנַת אַרְבַּע לְדָרְיָוֶשׁ:\",2,0],[2,139,8,9,\"אֵת הַדְּבָרִים הָאֵלֶּה. שֶׁל נִחוּמִים מִפִּי הַנְּבִיאִים אֲשֶׁר נִבְּאוּ לָהֶם אָז בְּיוֹם יֻסַּד בֵּית ה׳ בִּשְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ (חגי א:טו) אֶת הַדְּבָרִים לְהַתְחִיל בַּמְּלָאכָה. כִּי נִבְחֲנוּ אוֹתָם הַנְּבִיאִים בְּעֵינֵיהֶם בְּדִבְרֵיהֶם, שֶׁהֵם נְבִיאֵי אֱמֶת, וּלְפִיכָךְ כְּדַאי הֵם לִסְמֹךְ עֲלֵיהֶם אַף בְּדִבְרֵי נִחוּמִים שֶׁל עַכְשָׁיו. וּבַמֶּה נִבְחֲנוּהָ? כִּי לִפְנֵי הַיָּמִים הָהֵם שְׂכַר הָאָדָם וְגוֹמֵר. וְהֵם נִבְּאוּ לָכֶם שֶׁמִּשֶּׁתַּתְחִילוּ בַּמְּלָאכָה תָּבֹא בְּרָכָה בְּמַעֲשֵׂה יְדֵיכֶם, וְנִתְקַיְּמוּ דִּבְרֵיהֶם, שֶׁהֲרֵי עַתָּה לֹא כַיָּמִים הָרִאשֹׁנִים:\",3,0],[2,139,8,14,\"וְלֹא נִחָמְתִּי. עַל אֲשֶׁר זַמֹּתִי לְהָבִיא עֲלֵיכֶם לַחֲזוֹר בִּי, אֶלָּא הֲבִיאוֹתִיהָ. כֵּן לֹא אֶתְנַחֵם עַל הַטּוֹבָה אֲשֶׁר זָמַמְתִּי לָכֶם:\",1,0],[2,139,8,16,\"וּמִשְׁפַּט שָׁלוֹם. הִיא הַפְּשָׁרָה:\",1,0],[2,139,8,17,\"וְאִישׁ אֶת רָעַת רֵעֵהוּ. הִזְהִירָם עַל שִׂנְאַת חִנָּם, וְהִיא שֶׁהֶחֱרִיבָה בֵּית הַמִּקְדָּשׁ שֵׁנִי (יומא ט:):\",1,0],[2,139,8,19,\"צוֹם הָרְבִיעִי. צוֹם שֶׁל תַּמּוּז, שֶׁהוּא רְבִיעִי לֶחֳדָשִׁים:\",1,0],[2,139,8,19,\"צוֹם הַחֲמִישִׁי. שֶׁל אָב:\",2,0],[2,139,8,19,\"וְצוֹם הַשְּׁבִיעִי. שְׁלֹשָׁה בְּתִשְׁרֵי, שֶׁבּוֹ נֶהֱרַג גְּדַלְיָה (מלכים ב כה:כה; ירמיהו מא:א-ב):\",3,0],[2,139,8,19,\"וְצוֹם הָעֲשִׂירִי. שֶׁל טֵבֵת (ראש השנה יח:):\",4,0],[2,139,8,23,\"עֲשָׂרָה אֲנָשִׁים. מִשִּׁבְעִים לָשׁוֹן, הֲרֵי שְׁבַע מֵאוֹת לְכָל כָּנָף וְכָנָף. הֲרֵי לְאַרְבַּע כַּנְפֵי הַטַּלִּית אַלְפַּיִם וּשְׁמוֹנֶה מֵאוֹת (שבת לב:):\",1,0],[2,139,9,1,\"בְּאֶרֶץ חַדְרָךְ. דָּרַשׁ רַבִּי יְהוּדָה בַּר אֶלְעָאִי: זֶה מָשִׁיחַ, שֶׁהוּא חַד לְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת וְרַךְ לְיִשְׂרָאֵל. אָמַר לוֹ רַבִּי יוֹסֵי בֶּן דּוֹרְמַסְקִית: יְהוּדָה בְּרִבִּי, עַד מָתַי אַתָּה מְעַוֵּת עָלֵינוּ אֶת הַכְּתוּבִים? מֵעִיד אֲנִי עָלַי שָׁמַיִם וָאָרֶץ, שֶׁאֲנִי מִדַּמֶּשֶׂק, וְיֵשׁ מָקוֹם שֶׁשְּׁמוֹ חַדְרָךְ. וּמָה אֲנִי מְקַיֵּם וְדַמֶּשֶׂק מְנֻחָתוֹ? שֶׁעֲתִידָה יְרוּשָׁלַיִם לִהְיוֹת מַגַּעַת עַד דַּמֶּשֶׂק, וְאֵין מְנוּחָתוֹ אֶלָּא יְרוּשָׁלַיִם, שֶׁנֶּאֱמַר ״זֹאת מְנוּחָתִי עֲדֵי עַד״ (תהלים קלב:יד). אָמַר לוֹ: וּמָה אֲנִי מְקַיֵּם ״וְנִבְנְתָה עִיר עַל תִּלָּהּ״ (ירמיהו ל:יח)? אָמַר לוֹ: שֶׁאֵין עֲתִידָה לָזוּז מִמְּקוֹמָהּ. כָּךְ בְּרַיְתָא שְׁנוּיָה בְּסִפְרֵי (ספרי דברים א:א):\",1,0],[2,139,9,1,\"כִּי לַה׳ עֵין אָדָם. כִּי בַּיּוֹם הַהוּא יִשְׁעֶה הָאָדָם עַל עוֹשֵׂהוּ וְעֵינָיו אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא תִּרְאֶינָה (ישעיהו יז:ז), כְּמוֹ שֶׁאָמַר לְמַעְלָה ״נֵלְכָה עִמָּכֶם״ (זכריה ח:כג), וְנִסְפְּחוּ הֵם וְעָרֵיהֶם עַל עָרֵי יִשְׂרָאֵל:\",2,0],[2,139,9,1,\"וְכָל שִׁבְטֵי יִשְׂרָאֵל. חֲשׁוּבִים לַה׳ עַל כָּל הָאֻמּוֹת הַקַּדְמוֹנִים. כְּיוֹצֵא בוֹ: ״וְשָׁלֹמֹה אָהַב נָשִׁים נָכְרִיּוֹת רַבּוֹת וְאֶת בַּת פַּרְעֹה״ (מלכים א יא:א), וַהֲלֹא בַּת פַּרְעֹה בִּכְלָל הָיְתָה? אֶלָּא שֶׁהָיְתָה בַּת פַּרְעֹה חֲבִיבָה לוֹ כְּנֶגֶד כֻּלָּם. אַף כָּאן, כָּל הָאֻמּוֹת יִהְיוּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְיִשְׂרָאֵל כְּנֶגֶד כּוּלָם:\",3,0],[2,139,9,2,\"וְגַם חֲמָת תִּגְבָּל בָּהּ. תַּשִּׂיג גְּבוּלָהּ בִּגְבוּל יְרוּשָׁלָיִם:\",1,0],[2,139,9,2,\"צוֹר וְצִידוֹן. גַּם הֵמָּה בְּנוֹתֶיהָ, אַף עַל פִּי שֶׁחָכְמָה מְאֹד שֶׁנִּתְחַכְּמָה מְאֹד, וּסְבוּרָה לִהְיוֹת לְעוֹלָם גְּבֶרֶת בְּחָכְמָתָהּ:\",2,0],[2,139,9,3,\"וַתִּבֶן צוֹר מָצוֹר לָהּ. וְאוֹמֶרֶת: ״מִי יוֹרִידֵנִי לָאָרֶץ״? (עובדיה א:ג):\",1,0],[2,139,9,3,\"וַתִּצְבׇּר כֶּסֶף כֶּעָפָר. וּמִתְהַלֶּלֶת בְּעָשְׁרָהּ׃\",2,0],[2,139,9,3,\"וְחָרוּץ. מִין מַרְאִית זָהָב׃\",3,0],[2,139,9,4,\"הִנֵּה אֲדֹ׳. שֶׁהוּא שַׁלִּיט עַל כֹּל׃\",1,0],[2,139,9,4,\"יוֹרִישֶׁנָּה. לְשׁוֹן ״מוֹרִישׁ וּמַעֲשִׁיר״ (שמואל א ב:ז):\",2,0],[2,139,9,4,\"וְהִכָּה בַיָּם חֵילָהּ. וְהִבְלִיעַ בְּתוֹךְ יַמִּים מָמוֹנָהּ, יַעֲלֶה עָלֶיהָ אֶת הַיָּם וְיַטְבִּיעֶנָּה, כְּמוֹ שֶׁאָמַר יְחֶזְקֵאל (יחזקאל כז:כו-כז):\",3,0],[2,139,9,5,\"תִּרְאֶה אַשְׁקְלוֹן. אֶת מַפֶּלֶת צוֹר וְתִירָא:\",1,0],[2,139,9,5,\"וְעֶקְרוֹן אַף הִיא תִּירָא:\",2,0],[2,139,9,5,\"כִּי הוֹבִישׁ מֶבָּטָהּ. שֶׁהָיְתָה נִשְׁעֶנֶת עַל צוֹר, שֶׁהָיְתָה רֹאשׁ לִבְנֵי עֵשָׂו. וְעֶקְרוֹן אַף הִיא לֶאֱדוֹם, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ בְּמַסֶּכֶת מְגִלָּה (מגילה ו.). וּתְחִלָּה הָיְתָה מִשֶּׁל פְּלִשְׁתִּים:\",3,0],[2,139,9,6,\"וְיָשַׁב מַמְזֵר בְּאַשְׁדּוֹד. וְיָשַׁב עַם נָכְרִי בְּאַשְׁדּוֹד, הֵם יִשְׂרָאֵל שֶׁהָיוּ בָּהּ נָכְרִים (קידושין עב:):\",1,0],[2,139,9,7,\"וַהֲסִרֹתִי דָמָיו מִפִּיו. שֶׁל עֵשָׂו אֵלּוּ בֵּית בִּימָה שֶׁלָּהֶם שֶׁהָיוּ זוֹרְקִים שָׁם דְּמֵי זִבְחֵיהֶם (מגילה ו.). וְיֵשׁ פּוֹתְרִין שְׁפִיכוּת דָּמִים שֶׁהָיָה שׁוֹפֵךְ דְּמֵי יִשְׂרָאֵל:\",1,0],[2,139,9,7,\"וְנִשְׁאַר גַּם הוּא לֵאלֹהֵינוּ. אֵלּוּ בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת שֶׁבַּגָּלוּת (מגילה כט.):\",2,0],[2,139,9,7,\"וְהָיָה כְּאַלּוּף בִּיהוּדָה. אֵלּוּ טַרְטִיָּאוֹת וְקַרְקְסִיָּאוֹת שֶׁלָּהֶם, שֶׁעֲתִידִים שָׂרֵי יְהוּדָה לְלַמֵּד בָּהֶם תּוֹרָה בָּרַבִּים:\",3,0],[2,139,9,7,\"וְהָיָה כְּאַלּוּף. לְשׁוֹן אִלּוּף וְלִמּוּד:\",4,0],[2,139,9,7,\"וְעֶקְרוֹן. תִּהְיֶה לְיִשְׂרָאֵל:\",5,0],[2,139,9,7,\"כִּיבוּסִי. יְרוּשָׁלַיִם:\",6,0],[2,139,9,8,\"וְחָנִיתִי לְבֵיתִי מִצָּבָה. אֶחֱנֶה אֵצֶל בֵּיתִי לְהָגֵן עָלֶיהָ מִן הַמַּעֲמִידִים מִבְצָר וּמַשְׁחִית, שֶׁלֹּא יַצִּיבוּ עָלֶיהָ. וְדֻגְמָתוֹ ״וְכָל צֹבֶיהָ וּמְצֹדָתָהּ״ (ישעיהו כט:ז). וְיֵשׁ עוֹד לִפְתֹּר מִצָּבָה כְּמוֹ מִצָּבָא בְּאָלֶ״ף:\",1,0],[2,139,9,8,\"כִּי עַתָּה רָאִיתִי. צָרָתָם בְּעֵינַי, אַף עַל פִּי שֶׁעַד הֵנָּה הִסְתַּרְתִּי פָנַי מֵהֶם:\",2,0],[2,139,9,9,\"הִנֵּה מַלְכֵּךְ יָבוֹא לָךְ. אִי אֶפְשָׁר לְפוֹתְרוֹ אֶלָּא עַל מֶלֶךְ הַמָּשִׁיחַ שֶׁנֶּאֱמַר בּוֹ וּמָשְׁלוֹ מִיָּם עַד יָם, וְלֹא מָצִינוּ מוֹשֵׁל לְיִשְׂרָאֵל כָּזֶה בִּימֵי בַּיִת שֵׁנִי:\",1,0],[2,139,9,9,\"צַדִּיק וְנוֹשָׁע. בַּה׳׃\",2,0],[2,139,9,9,\"עָנִי. עֲנְוְתָן:\",3,0],[2,139,9,9,\"וְרוֹכֵב עַל חֲמוֹר. מִדַּת עֲנָוָה הִיא:\",4,0],[2,139,9,9,\"וְעַל עַיִר. כְּמוֹ ״וַעֲיָרִים עֲשָׂרָה״ (בראשית לב:טז):\",5,0],[2,139,9,10,\"וְהִכְרַתִּי רֶכֶב. שֶׁלֹּא יִהְיוּ צְרִיכִין לָהּ:\",1,0],[2,139,9,10,\"וּמָשְׁלוֹ. וּמִמְשָׁל שֶׁלּוֹ:\",2,0],[2,139,9,10,\"מִיָּם וְעַד יָם. ״מִיַּמָּא וְעַד מַעֲרְבָא״, לְסוֹף הָעוֹלָם (בראשית רבה ע:יט):\",3,0],[2,139,9,10,\"וּמִנָּהָר. פְּרָת:\",4,0],[2,139,9,11,\"גַּם אַתְּ. תִּוָּשְׁעִי עִמּוֹ, כְּמוֹ שֶׁהוּא צַדִּיק וְנוֹשָׁע (זכריה ט:ט), כִּי בְדַם בְּרִיתֵךְ הֲרֵי נִבֵּאתִי לָכֶם לֶעָתִיד, וְגַם עַתָּה מִגָּלוּת בָּבֶל שֶׁאַתֶּם עַכְשָׁיו בְּתוֹכָהּ:\",1,0],[2,139,9,11,\"בְּדַם בְּרִיתֵךְ. בִּזְכוּת דַּם הַבְּרִית שֶׁנִּזְרַק עֲלֵיכֶם בְּסִינַי, הִנֵּה דַם הַבְּרִית אֲשֶׁר כָּרַת (שמות כד:ח):\",2,0],[2,139,9,11,\"שִׁלַּחְתִּי אֲסִירַיִךְ. מִן הַגָּלוּת (ויקרא רבה יט:ו)׃\",3,0],[2,139,9,12,\"שׁוּבוּ לְבִצָּרוֹן. לְכֹחֲכֶם וְלִכְבוֹדְכֶם, אַף עַל פִּי שֶׁאַתֶּם עַתָּה בִּרְשׁוּת מַלְכֵי פָּרַס, אַתֶּם אֲסִירֵי הַתִּקְוָה. אֲשֶׁר קִוִּיתֶם לִי עַד הֵנָּה לְמַלֹּאות דְּבָרַי לְקֵץ שִׁבְעִים שָׁנָה (ירמיה כט:י):\",1,0],[2,139,9,12,\"גַּם הַיּוֹם מַגִּיד מִשְׁנֶה אָשִׁיב לָךְ. עוֹד הַיּוֹם אֲנִי מַגִּיד לְךָ בְּשׂוֹרָה שְׁנִיָּה, לְבַד זוֹ שֶׁל בִּנְיָן. וּמַה הִיא הַגָּדָה הַשְּׁנִיָּה שֶׁאֲנִי שָׁב לִשְׁנוֹת לָכֶם?:\",2,0],[2,139,9,13,\"כִּי דָרַכְתִּי לִי יְהוּדָה. סוֹף שֶׁאַנְטִיוֹכוּס יִטֹּל הַמְּלוּכָה מִיַּד מַלְכֵי פָרַס וְיָרֵעוּ לָכֶם, וַאֲנִי אֶדְרֹךְ יְהוּדָה לִהְיוֹת לִי כְּקֶשֶׁת מִלְחָמָה, וְיִלָּחֲמוּ בְּאַנְטִיוֹכוּס בִּימֵי חַשְׁמוֹנָאִים:\",1,0],[2,139,9,13,\"קֶשֶׁת מִלֵּאתִי אֶפְרַיִם. מִקְרָא קָצָר הוּא, כְּמוֹ קֶשֶׁת מִלֵּאתִי יַד אֶפְרָיִם, כְּמוֹ ״וְיֵהוּא מִלֵּא יָדוֹ בַקֶּשֶׁת״ (מלכים ב ט:כד). אֶפְרָיִם יִהְיֶה לִי כְּאַשְׁפָּה מְלֵאָה חִצִּים:\",2,0],[2,139,9,13,\"וְעוֹרַרְתִּי בָנַיִךְ צִיּוֹן. עַל חֵיל אַנְטִיוֹכוּס (פסיקתא רבתי ב):\",3,0],[2,139,9,14,\"וַה׳ עֲלֵיהֶם יֵרָאֶה. בְּסֵפֶר יוֹסִיפוֹן מָצִינוּ: בָּעֵת הַהִיא נִרְאָה מוֹפֵת לְאַנְשֵׁי יְרוּשָׁלָיִם:\",1,0],[2,139,9,14,\"בַּשּׁוֹפָר יִתְקָע. יִרְעַם:\",2,0],[2,139,9,14,\"בְּסַעֲרוֹת תֵּימָן. לְסַעֵר אֶת אַנְשֵׁי תֵימָן, הֵם חֵיל אַנְטִיוֹכוּס. וְיֵשׁ מֵרַבּוֹתֵינוּ (ירושלמי תענית ב,ד) שֶׁפָּתְרוּהוּ עַל אֱדוֹם, לֶעָתִיד לָבֹא:\",3,0],[2,139,9,15,\"וְאָכְלוּ. שְׁלַל אוֹיְבֵיהֶם:\",1,0],[2,139,9,15,\"וְכָבְשׁוּ. תַּחְתֶּיהָ אַבְנֵי קֶלַע, הֵם הַיְּוָנִים שֶׁהֵם מְלֻמְּדֵי קֶשֶׁת וְלִקְלֹעַ בָּאֶבֶן:\",2,0],[2,139,9,15,\"וְהָמוּ כְּמוֹ יָיִן. הֲמִיּוֹן בְּקוֹל שָׂשׂוֹן וְשִׂמְחָה, כְּמוֹ שֶׁהוֹמִים שְׁתוּיֵי יָיִן:\",3,0],[2,139,9,15,\"וּמָלְאוּ. נַפְשׁוֹתָם כָּל טוֹב:\",4,0],[2,139,9,15,\"כַּמִּזְרָק. שֶׁמָּלֵא דָם לִפְנֵי הַמִּזְבֵּחַ:\",5,0],[2,139,9,15,\"כְּזָוִיּוֹת מִזְבֵּחַ. שֶׁמְּנַסְּכִין שָׁם יַיִן וְהַיַּיִן צָף עָלָיו כְּמוֹ שֶׁשָּׁנִינוּ בְּמַסֶּכֶת סֻכָּה (סוכה מט:) לְשׁוֹן שְׂבִיעָה לְשׁוֹן שִׁכְרוּת:\",6,0],[2,139,9,16,\"כְּצֹאן עַמּוֹ. כַּצֹּאן שֶׁהִסִּיעַ מִמִּצְרַיִם לִהְיוֹת לוֹ לְעָם:\",1,0],[2,139,9,16,\"כִּי אַבְנֵי נֵזֶר. כִּי הַכֹּהֲנִים בְּנֵי חַשְׁמוֹנָאִים הַמִּתְפָּאֲרִים בְּאַבְנֵי נֵזֶר בְּטוּרֵי חֹשֶׁן וְאֵפוֹד יִהְיוּ מִתְנוֹסְסִים בְּנִסִּים עַל אַדְמָתָן:\",2,0],[2,139,9,17,\"כִּי מַה. רַב טוּבוֹ. הַצָּפוּן שֶׁל אוֹתוֹ הַדּוֹר:\",1,0],[2,139,9,17,\"דָּגָן בַּחוּרִים. הַנּוֹתֵן כֹּחַ לַבַּחוּרִים:\",2,0],[2,139,9,17,\"וְתִירוֹשׁ. אֲשֶׁר יְנוֹבֵב בְּתוּלוֹת בְּנִיב שִׁיר וְשִׂמְחָה. וְיֵשׁ פּוֹתְרִין אֲשֶׁר יְנוֹבֵב וְיִצְמַח בְּקַרְקַע בְּתוּלָה, וְהוּא יַיִן מְשֻׁבָּח:\",3,0],[2,139,10,1,\"שַׁאֲלוּ מֵה׳ מָטָר. אִם תִּצְטָרְכוּ:\",1,0],[2,139,10,1,\"חֲזִיזִים. עֲנָנִים מְבִיאִים מָטָר:\",2,0],[2,139,10,1,\"לְאִישׁ עֵשֶׂב בַּשָּׂדֶה. בִּשְׁבִיל אִישׁ אֶחָד וּבִשְׁבִיל עֵשֶׂב אֶחָד הַצָּרִיךְ לְמָטָר (תענית ט:):\",3,0],[2,139,10,2,\"כִּי הַתְּרָפִים. וְהַקּוֹסְמִים חָזוּ שֶׁקֶר וְהַחֲלוֹמוֹת אֲשֶׁר הִטְעוּ אֶת אֲבוֹתֵיכֶם ״לֵאמֹר חָלַמְתִּי״ (ירמיה כג:כה) וְהָיוּ מַחֲזִיקִים יְדֵיהֶם לִמְרֹד בְּהַקָּדוֹשׁ בָּרוּךְ הוּא, דִּבְּרוּ אָוֶן וְהֶבֶל דִּבְּרוּ לֵאמֹר ״שָׁלוֹם וְאֵין שָׁלוֹם״ (ירמיה ו:יד):\",1,0],[2,139,10,2,\"עַל כֵּן נָסְעוּ. אֲבָל אֲנִי נָבִיא לָהֶם בֶּאֱמֶת:\",2,0],[2,139,10,2,\"יַעֲנוּ. יִתְכַּנְּעוּ, כְּמוֹ ״לֵעָנֹת מִפְּנֵי״ (שמות י:ג) – לְשׁוֹן עֹנִי:\",3,0],[2,139,10,3,\"עַל הָרֹעִים חָרָה אַפִּי. עַל מַלְכֵי נְבוּכַדְנֶצַּר וְסַנְחֵרִיב (נוסח אחר: מַלְכֵי יָוָן):\",1,0],[2,139,10,3,\"וְעַל הָעַתּוּדִים. עַל שָׂרֵיהֶם, וְכֵן תִּרְגֵּם יוֹנָתָן: ״וְעַל מַלְכַיָּא הֲוָה רוּגְזִי וְעַל שָׁלְטָנַיָּא אֲנָא מְסָעֵר״. וְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת נִמְשְׁלוּ לַעֲתוּדִים: ״וְהַצָּפִיר הַשָּׂעִיר מֶלֶךְ יָָוָן״ (דניאל ח:כא). וְהָרוֹצֶה לְפָרֵשׁ הָעִנְיָן שֶׁלֹּא בְּמַלְכֵי עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת יֹאמַר: עַתּוּדִים – לְשׁוֹן שָׂרִים, כְּמוֹ ״עוֹרֵר לְךָ רְפָאִים כָּל עַתּוּדֵי אָרֶץ״ (ישעיה יד:ט):\",2,0],[2,139,10,3,\"כְּסוּס הוֹדוֹ בַּמִּלְחָמָה. כְּסוּס אֲשֶׁר יֻכַּר הוֹדוֹ בַּמִּלְחָמָה:\",3,0],[2,139,10,4,\"מִמֶּנּוּ פִנָּה. מֵהֶם מַלְכֵיהֶם, מֵהֶם שָׂרֵיהֶם, מֵהֶם לוֹחֲמֵי מִלְחֲמוֹתָם (חולין נו:):\",1,0],[2,139,10,5,\"וְהָיוּ כְגִבּוֹרִים בּוֹסִים בְּטִיט חוּצוֹת בַּמִּלְחָמָה. הֲרֵי מִקְרָא זֶה מְסֹרָס, וְהָיוּ בַּמִּלְחָמָה הוֹלְכִים וְדוֹרְכִים אֲנָשִׁים כְּגִבּוֹרִים הַבּוֹסִים טִיט חוּצוֹת. בּוֹסִים – דּוֹרְסִים, כְּמוֹ ״יָבוּס קָמֵינוּ״ (תהילים מד:ו), ״בּוֹסְסוּ אֶת חֶלְקָתִי״ (ירמיהו יב:י):\",1,0],[2,139,10,5,\"וְהוֹבִישׁוּ. בֵּית יְהוּדָה, אֶת רוֹכְבֵי הַסּוּסִים הַבָּאִים לְהִלָּחֵם בָּם:\",2,0],[2,139,10,6,\"וְגִבַּרְתִּי אֶת בֵּית יְהוּדָה. בְּמִלְחֶמֶת הַיְּוָנִים:\",1,0],[2,139,10,6,\"וְאֶת בֵּית יוֹסֵף אוֹשִׁיעַ. בַּמָּקוֹם שֶׁגָּלוּ שָׁם בַּחֲלַח וּבְחָבוֹר בִּימֵי סַנְחֵרִיב (מלכים ב יח:יא):\",2,0],[2,139,10,6,\"וְהוֹשְׁבוֹתִים. כְּמוֹ וְהוֹשַׁבְתִּים, לְשׁוֹן יְשִׁיבָה:\",3,0],[2,139,10,6,\"וְהָיוּ כַּאֲשֶׁר לֹא זְנַחְתִּים. כְּאִלּוּ לֹא זְנַחְתִּים מֵעוֹלָם:\",4,0],[2,139,10,8,\"אֶשְׁרְקָה לָהֶם. כְּדֶרֶךְ הַשּׁוֹרְקִים לְסִימָן אוֹת לָבֹא אֵלָיו הַטּוֹעֶה בַּדֶּרֶךְ:\",1,0],[2,139,10,8,\"וַאֲקַבְּצֵם. לְעֵת הַקֵּץ, לֶעָתִיד:\",2,0],[2,139,10,8,\"כִּי פְדִיתִים. כְּשֶׁאֶפְדֵּם:\",3,0],[2,139,10,8,\"וְרָבוּ. בַּגּוֹלָה כְּמוֹ שֶׁרָבוּ בְּמִצְרָיִם (שמות א:ז):\",4,0],[2,139,10,9,\"וְאֶזְרָעֵם. תְּחִלָּה בָּעַמִּים, כְּאָדָם הַזּוֹרֵעַ סְאָה לְהַכְנִיס כַּמָּה כּוֹרִין (פסחים פז:):\",1,0],[2,139,10,9,\"וְחָיוּ אֶת בְּנֵיהֶם. עִם בְּנֵיהֶם:\",2,0],[2,139,10,10,\"וּלְבָנוֹן. זֶה בֵּית הַמִּקְדָּשׁ (יומא לט:):\",1,0],[2,139,10,10,\"וְלֹא יִמָּצֵא לָהֶם. ״וְלֹא יִסֻפָּק לְהוֹן״ (תרגום יונתן):\",2,0],[2,139,10,11,\"וְעָבַר בַּיָּם צָרָה. וְתַעֲבֹר צָרָה בְּצוֹר הַיּוֹשֶׁבֶת בְּתוֹךְ הַיָּם, וְהוּא רֹאשׁ לְמַלְכוּת צוֹר:\",1,0],[2,139,10,11,\"וְהִכָּה. הַקָּדוֹשׁ בָּרוּךְ הוּא אֲשֶׁר הוּא הַמַּכֶּה יַכֶּה בַיָּם גַּלִּים לְהַשְׁקִיעַ אֶת צוֹר:\",2,0],[2,139,10,11,\"כָּל מְצוּלוֹת יְאוֹר. הִיא מִצְרָיִם:\",3,0],[2,139,11,1,\"פְּתַח לְבָנוֹן דְּלָתֶיךָ. תִּרְגֵּם יוֹנָתָן: ״פִּתְחוּ עַמְמַיָּא תַּרְעֵיכוֹן״:\",1,0],[2,139,11,2,\"הֵילֵל בְּרוֹשׁ כִּי נָפַל אֶרֶז. שֶׁהוּא גָּדוֹל מִן הַבְּרוֹשׁ. הֵילִילוּ הַשִּׁלְטוֹנִים כִּי נָפְלוּ הַמְּלָכִים מֵעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:\",1,0],[2,139,11,2,\"אַלּוֹנֵי בָשָׁן. קִישְׁנֵ״שׁ בְּלַעַ״ז:\",2,0],[2,139,11,2,\"כִּי יָרַד. כִּי נִשְׁבַּר, וְדוֹמֶה לוֹ ״וּבָרַד בְּרֶדֶת הַיַּעַר״ (ישעיה לב:יט):\",3,0],[2,139,11,2,\"יַעַר הַבָּצִיר. יַעַר הַמִּבְצָר, ״תְּקוֹף כַּרְכַיָּא״:\",4,0],[2,139,11,3,\"הָרוֹעִים. הַמְּלָכִים:\",1,0],[2,139,11,3,\"אַדַּרְתָּם. תִּפְאַרְתָּם׃\",2,0],[2,139,11,3,\"שַׁאֲגַת כְּפִירִים. יִבְכּוּ הַשָּׂרִים:\",3,0],[2,139,11,3,\"כִּי שֻׁדַּד גְּאוֹן הַיַּרְדֵּן. שֶׁהוּא מְקוֹם הַכְּפִירִים וַאֲרָיוֹת. וְרַבּוֹתֵינוּ פֵּרְשׁוּ פְּתַח לְבָנוֹן דְּלָתֶיךָ (יומא לט:), שֶׁעַל חֻרְבַּן בַּיִת שֵׁנִי נִתְנַבֵּא הַנָּבִיא, וְאַרְבָּעִים שָׁנָה קֹדֶם חֻרְבָּן הָיוּ דַּלְתוֹת הַהֵיכָל נִפְתָּחוֹת מֵאֲלֵיהֶן. גָּעַר בָּהֶן רַבִּי יוֹחָנָן בֶּן זַכַּאי, אָמַר לוֹ: הֵיכָל הֵיכָל, עַד מָתַי אַתָּה מְבַעִית אֶת עַצְמְךָ? יוֹדֵעַ אֲנִי שֶׁסּוֹפְךָ לֵחָרֵב, וּכְבָר נִתְנַבֵּא עָלֶיךָ זְכַרְיָה בֶּן עִדּוֹא פְּתַח לְבָנוֹן דְּלָתֶיךָ וְגוֹ׳:\",4,0],[2,139,11,4,\"רְעֵה אֶת צֹאן הַהֲרֵגָה. הָכֵן לָהֶם רוֹעִים, כְּלוֹמַר: הִנָּבֵא עַל פַּרְנָסֵיהֶם הָעֲתִידִים לִרְעוֹתָם מֵעַתָּה:\",1,0],[2,139,11,4,\"צֹאן הַהֲרֵגָה. יִשְׂרָאֵל שֶׁהֲרָגוּם רוֹעֵיהֶם וַאֲכָלוּם:\",2,0],[2,139,11,5,\"וְלֹא יֶאְשָׁמוּ. הַבַּבְלִיִּים שֶׁאַגְלֵם לְתוֹכָם, זֶה מוֹכְרָם וְהַקּוֹנֶה הָרוּג, וְאֵין נוֹתֵן לְלִבּוֹ שֶׁיְּהֵא לוֹ אַשְׁמָה בַּדָּבָר. וּמוֹכְרָם מִתְהַלֵּל: בָּרוּךְ ה׳ שֶׁמְּסָרָם בְּיָדִי, וַהֲרֵינִי עָשִׁיר:\",1,0],[2,139,11,5,\"וַאעְשִׁר. וַהֲרֵי אֲנִי עָשִׁיר:\",2,0],[2,139,11,7,\"וָאֶרְעֶה אֶת צֹאן הַהֲרֵגָה. כָּל אֵלֶּה דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לַנָּבִיא, וַאֲנִי רָעִיתִי אוֹתָם בַּיָּמִים הַקַּדְמוֹנִים:\",1,0],[2,139,11,7,\"לָכֵן עֲנִיֵּי הַצֹּאן. אֱמֶת עֲנִיֵּי הַצֹּאן הָיוּ כְּשֶׁהִתְחַלְתִּי לִרְעוֹתָם:\",2,0],[2,139,11,7,\"וָאֶקַּח לִי שְׁנֵי מַקְלוֹת. לְסוֹף יָמִים חִלַּקְתִּים לִשְׁתֵּי מַמְלָכוֹת בַּעֲוֹנָם:\",3,0],[2,139,11,7,\"לְאַחַד קָרָאתִי נֹעַם. יָרָבְעָם אָמַר לְנַהֲלָם לְאַט:\",4,0],[2,139,11,7,\"וּלְאַחַד קָרָאתִי חוֹבְלִים. רְחַבְעָם אָמַר לָהֶם לְיַסְּרָם בְּעַקְרַבִּים (מלכים א יב:יד). וּלְפִי שֶׁדֶּרֶךְ צֹאן לְנַהֲלָן בְּמַקְלוֹת, קָרָא לְמוֹשְׁלֵיהֶם מַקְלוֹת:\",5,0],[2,139,11,8,\"וָאַכְחִיד אֶת שְׁלֹשֶׁת הָרוֹעִים בְּיֶרַח אֶחָד. וְהֵם הִשְׁחִיתוּ דַרְכֵיהֶם עַד שֶׁמְאַסְתִּים וַהֲרַגְתִּים בְּחֹדֶשׁ אֶחָד. כָּל שְׁלֹשֶׁת הָרוֹעִים שֶׁהָרַג וְהוּא אֶת כָּל בֵּית אַחְאָב וְאֶת בֵּית אֲחַזְיָה מֶלֶךְ יְהוּדָה וְאֶת אֶחָיו וְאֶת כָּל זֶרַע מַלְכוּת דָּוִד, וַעֲתַלְיָה אִבְּדָה אֶת הַשְּׁאָר, זוּלָתִי יוֹאָשׁ שֶׁנִּטְמַן (מלכים ב יא:א-ג):\",1,0],[2,139,11,8,\"וַתִּקְצַר נַפְשִׁי בָּהֶם. מְאַסְתִּים. וְכָל לְשׁוֹן קֹצֶר נֶפֶשׁ הוּא דְּבַר צָרָה אוֹ דְּבַר מֵאוּס שֶׁאֵין הַדַּעַת סוֹבַלְתּוֹ, וְקָצַר הַלֵּב וְהַמֵּעַיִם מִלְּהָכִיל; כְּמוֹ שֶׁאֱלִיהוּ אָמַר: ״הֱצִיקַתְנִי רוּחַ בִּטְנִי״ (אִיּוֹב לב:יח):\",2,0],[2,139,11,8,\"גַּם נַפְשָׁם בָּחֲלָה בִי. זִכְרוֹנָם הָיָה רַב בְּמֵעַי וּמְמַלֵּא אֶת רוּחִי וּמֵצִיק אֶת בִּטְנִי. וּבָחֲלָה פֵּרְשׁוּ רַבּוֹתֵינוּ לְשׁוֹן גֹּדֶל בְּמַסֶּכֶת נִדָּה (נדה מז.): מָשָׁל מָשְׁלוּ חֲכָמִים בָּאִשָּׁה פַּגָּה בֹּחַל וְצֶמֶל, פַּגָּה עוֹדָהּ תִּינוֹקֶת, בֹּחַל אֵלּוּ יְמֵי הַנְּעוּרִים שֶׁכְּבָר הִיא גְּדוֹלָה. וְהֵבִיאוּ מִקְרָא זֶה רְאָיָה לְדִבְרֵיהֶם:\",3,0],[2,139,11,9,\"וָאֹמַר לֹא אֶרְעֶה אֶתְכֶם. אָמַרְתִּי בְּאוֹתָן הַיָּמִים אַשְׁלִיכֵם מֵעַל פָּנַי וְיִהְיוּ הֶפְקֵר וּלְבַז:\",1,0],[2,139,11,10,\"וָאֶקַּח אֶת מַקְלִי אֶת נֹעַם. שָׁבַרְתִּי אֶת כֹּחַ מַלְכֵי יִשְׂרָאֵל בִּימֵי יְהוֹאָחָז בֶּן יֵהוּא, עַד כִּי אִבְּדָם מֶלֶךְ אֲרָם וַיְשִׂימֵם כֶּעָפָר לָדוּשׁ (מלכים ב יג:ז). וּבִימֵי הוֹשֵׁעַ בֶּן אֵלָה, שֶׁמְּסַרְתִּים בְּיַד סַנְחֵרִיב וְהִגְלָהוּ (שם יז):\",1,0],[2,139,11,10,\"לְהָפֵר אֶת בְּרִיתִי אֲשֶׁר כָּרַתִּי אֶת כָּל הָעַמִּים. לְהַרְאוֹתָם, שֶׁבִּשְׁבִיל שֶׁבָּגְדוּ בִּי הֵפַרְתִּי אֶת בְּרִיתִי אֲשֶׁר כָּרַתִּי עִם כָּל הָעַמִּים עֲלֵיהֶם שֶׁלֹּא יַזִּיקוּם. שֶׁעַל מְנָת כֵּן נָתַתִּי לָהֶם אֶת הַתּוֹרָה, שֶׁאִם יִשְׁמְרוּהָ, שֶׁיִּהְיוּ חֵרוּת מִן הַמַּלְכֻיּוֹת; שֶׁלֹּא תְּהֵא אֻמָּה וְלָשׁוֹן שׁוֹלֶטֶת בָּהֶם (ערובין נד.). וְאַל תִּתְמַהּ אִם דִּבֵּר הַמִּקְרָא תְּשׁוּעָתָם מִיַּד שׂוֹנֵא בִּלְשׁוֹן כְּרִיתַת בְּרִית אֶת הַשּׂוֹנֵא, שֶׁהֲרֵי מָצִינוּ מִקְרָא דֻּגְמָתוֹ: ״וְכָרַתִּי לָהֶם בְּרִית בַּיּוֹם הַהוּא עִם חַיַּת הַשָּׂדֶה וְגוֹמֵר״ (הושע ב:כ):\",2,0],[2,139,11,11,\"וַיֵּדְעוּ. כֵּן הֵבִינוּ הַצַּדִּיקִים שֶׁבָּהֶם הַשּׁוֹמְרִים אֶת חוּקִּי:\",1,0],[2,139,11,11,\"כִּי דְבַר ה׳ הוּא. גְּזֵרָה זוֹ כְּבָר דִּבֵּר לָנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יְדֵי מֹשֶׁה: ״יוֹלִיךְ ה׳ אֹתְךָ וְאֶת מַלְכְּךָ״ (דברים כח:לו):\",2,0],[2,139,11,12,\"וָאֹמַר. אֶל מַלְכֵי יְהוּדָה הַנּוֹתָרִים:\",1,0],[2,139,11,12,\"אִם טוֹב בְּעֵינֵיכֶם הָבוּ שְׂכָרִי. קַיְּמוּ מִצְוֹתַי, וְהוּא יִהְיֶה שְׂכָרִי עַל כָּל הַטּוֹבָה אֲשֶׁר נָתַתִּי לָכֶם, כְּמוֹ שֶׁנּוֹתְנִין שָׂכָר לְרוֹעֵה צֹאן, וְאָשׁוּב וְאֶרְעֶה אֶתְכֶם:\",2,0],[2,139,11,12,\"וְאִם לֹא חֲדָלוּ. וְגַם אֲנִי לֹא אֵיטִיב לָכֶם. וְכֵן מָצִינוּ שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לִיחֶזְקֵאל: ״הַשּׁוֹמֵעַ יִשְׁמַע וְהֶחָדֵל יֶחְדָּל״ (יחזקאל ג:כז):\",3,0],[2,139,11,12,\"וַיִּשְׁקְלוּ אֶת שְׂכָרִי שְׁלֹשִׁים כָּסֶף. תִּרְגֵּם יוֹנָתָן: ״וַעֲבַדוּ יָת רְעוּתִי גֻּבְרִין מִקְצָת״ – אֲנָשִׁים טוֹבִים מְעַט הָיוּ בָּהֶם שֶׁעָשׂוּ רְצוֹנִי, כְּגוֹן ״הֶחָרָשׁ וְהַמַּסְגֵּר״ (מלכים ב כד:טז), דָּנִיֵּאל חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה, יְחֶזְקֵאל. וּלְשׁוֹן שְׁלֹשִׁים כָּסֶף – לֹא יָדַעְתִּי לְכַוֵּן כָּאן אֶלָּא כֶּסֶף – לְשׁוֹן חֶמְדָּה. וְאַף רַבּוֹתֵינוּ פֵּרְשׁוּהוּ כֵּן בִּחֻלִּין (חולין צב.), וְהֵבִיאוּ רְאָיָה: ״צְרוֹר הַכֶּסֶף לָקַח בְּיָדוֹ״ (משלי ז:כ). וְאֶת הַשְּׁלֹשִׁים פֵּרְשׁוּ, שֶׁאַרְבָּעִים וַחֲמִשָּׁה צַדִּיקִים יֵשׁ בְּכָל דּוֹר וָדוֹר; וְהֵבִיאוּ רְאָיָה: ״וְחֹמֶר שְׂעֹרִים וְלֶתֶךְ שְׂעֹרִים״ (הושע ג:ב) – חֲמִשָּׁה עָשָׂר בְּבָבֶל; וּשְׁלֹשִׁים בְּאֶרֶץ יִשְׂרָאֵל, שֶׁנֶּאֱמַר ״וָאֶקְחָה אֶת שְׁלֹשִׁים הַכֶּסֶף בֵּית ה׳״ – בְּאֶרֶץ יִשְׂרָאֵל. וּמִנְיַן הַשְּׁלֹשִׁים – מִדְרַשׁ אַגָּדָה הוּא (תנחומא מקץ ו), שֶׁהֻבְטַח אַבְרָהָם אָבִינוּ בְּכָךְ שֶׁלֹּא יְהֵא דּוֹר פָּחוֹת מִשְּׁלֹשִׁים צַדִּיקִים. מִנְיָן? ״כֹּה יִהְיֶה זַרְעֶךָ״ (בראשית טו:ה) – ״יִהְיֶה״ בְּגִימַטְרִיָּא שְׁלֹשִׁים:\",4,0],[2,139,11,13,\"וַיֹּאמֶר ה׳ אֵלַי הַשְׁלִיכֵהוּ אֶל הַיּוֹצֵר. כְּמוֹ אֶל הָאוֹצָר, שׁוֹמֵר הָאוֹצָר. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַנָּבִיא: כְּתֹב וְהַנַּח אֶת אֵלּוּ, הֵם וְצִדְקָתָם, לִהְיוֹת שָׁמוּר לְסוֹף שִׁבְעִים שָׁנָה שֶׁל גָּלוּת בָּבֶל, וְיִבָּנֶה בֵּית הַמִּקְדָּשׁ עַל יְדֵיהֶם. וּמַהוּ הָאוֹצָר? אֶדֶר הַיְקָר בֵּית מִקְדָּשִׁי, אֲדַר תִּפְאַרְתִּי:\",1,0],[2,139,11,13,\"אֲשֶׁר יָקַרְתִּי מֵעֲלֵיהֶם. אֲשֶׁר הִפְשַׁטְתִּי מֵעֲלֵיהֶם מִהְיוֹת לָהֶם לִיקָר. וּלְשׁוֹן יָקַרְתִּי הוּא הֲסָרַת כָּבוֹד, וְהַמֵּ״ם שֶׁל מֵעֲלֵיהֶם יוֹכִיחַ. וְהוּא כְּמוֹ ״וְשֵׁרֶשְׁךָ מֵאֶרֶץ חַיִּים״ (תהלים נב:ז), כְּמוֹ ״מְסָעֵף פֹּארָה״ (ישעיהו י:לג). וְדֻגְמַת הַפֵּרוּשׁ שֶׁפֵּרַשְׁתִּי, מֵעֵין תַּרְגּוּם שֶׁל יוֹנָתָן הוּא. וְרָאִיתִי לְשׁוֹנוֹת הַרְבֵּה לְפֵרוּשׁ נְבוּאָה זוֹ, וְאֵינִי יָכוֹל לְכַוְּנָן:\",2,0],[2,139,11,14,\"וָאֶגְדַּע אֶת מַקְלִי הַשֵּׁנִי. הִגְלֵיתִי אֶת צִדְקִיָּהוּ:\",1,0],[2,139,11,14,\"אֶת הַחוֹבְלִים. אֶת רִשְׁעֵי דּוֹרוֹ, כִּי הוּא צַדִּיק וְדוֹרוֹ רְשָׁעִים (סנהדרין קג.):\",2,0],[2,139,11,14,\"לְהָפֵר אֶת הָאַחֲוָה. שֶׁנִּתְאַחֲווּ בְּנֵי יְהוּדָה וּבִנְיָמִן וְנִדְבְּקוּ בְּתוֹעֲבוֹת מַלְכֵי יִשְׂרָאֵל:\",3,0],[2,139,11,15,\"עוֹד קַח לְךָ וְגוֹ׳. וְזֶהוּ שֶׁאָמַר לוֹ לְמַעְלָה רְעֵה צֹאן הַהֲרֵגָה, סִימָן הוּא שֶׁאֲנִי עָתִיד לִמְסֹר דּוֹר חֻרְבַּן בַּיִת שֵׁנִי זֶה בְּיַד טִיטוּס:\",1,0],[2,139,11,16,\"הַנִּכְחָדוֹת. הָאוֹבְדוֹת לֹא יִפְקֹד הָרוֹעֶה לְבַקְּשָׁם:\",1,0],[2,139,11,16,\"הַנַּעַר לֹא יְבַקֵּשׁ. תִּרְגֵּם יוֹנָתָן ״דְּאִטַּלְטְלוּ לָא יִתְבַּע״. הַנַּעַר – הַשּׁוֹטוֹת שֶׁאֵינָן יוֹדְעוֹת לָבוֹא אֶל הַדִּיר:\",2,0],[2,139,11,16,\"הַנִּצָּבָה. שֶׁיֵּשׁ לָהּ כֹּחַ קְצָת לַעֲמֹד עַל רַגְלֶיהָ, וּצְרִיכָה סִיּוּעַ לְנַהֲלָהּ לְאַט. וּמְנַחֵם פֵּרֵשׁ וְנִצָּבָה לְשׁוֹן ״לַצְבּוֹת בֶּטֶן״ (במדבר ה:כב):\",3,0],[2,139,11,16,\"לֹא יְכַלְכֵּל. תִּרְגֵּם יוֹנָתָן: ״לָא יְסוֹבַר״, וְדֶרֶךְ הָרוֹעֶה בְּחֵיקוֹ יִשָּׂא (יְשַׁעְיָהוּ מ:יא):\",4,0],[2,139,11,16,\"וּבְשַׂר הַבְּרִיאָה יֹאכַל. אֶת הָעֲשִׁירִים יִגְמֹר מָמוֹנָן:\",5,0],[2,139,11,16,\"וּפַרְסֵיהֶן יְפָרֵק. עַד כָּלָה. וְדֻגְמַת זוֹ אָמַר דָּנִיֵּאל (דניאל ז:ז): ״אָכְלָה וּמַדֱּקָה וּשְׁאָרָא בְּרַגְלַהּ רָפְסָה״:\",6,0],[2,139,11,17,\"הוֹי. יֵשׁ לִצְעוֹק עַל זֶה:\",1,0],[2,139,11,17,\"רֹעִי הָאֱלִיל. רוֹעֵי שֶׁל אַיִן, אֱלִיל לְשׁוֹן אַל, אֵינוֹ רוֹעֶה. וְכֵן רֹפְאֵי אֱלִיל (איוב יג:ד). רֹעִי הָאֱלִיל יוֹ״ד יְתֵרָה בִּמְקוֹם הֵ״א, כְּמוֹ עֹזְבִי הַצֹּאן (כאן), ״שֹׁכְנִי סְנֶה״ (דְּבָרִים לג:טז), ״שֹׁכְנִי לְבָדָד״ (מִיכָה ז:יד):\",2,0],[2,139,11,17,\"עוֹזְבִי הַצֹּאן. נוֹתְנָן הֶפְקֵר לְיַד כָּל הַבָּא לְהַכּוֹת וְלַהֲרֹג וְלָבֹז:\",3,0],[2,139,11,17,\"חֶרֶב עַל זְרוֹעוֹ וְעַל עֵין יְמִינוֹ. וְהוּא הָרוֹעֶה סַכִּין שֶׁל שְׁחִיטָה נוֹשֵׂא בְּיָדוֹ לִשְׁחוֹט אֶת הַשְּׁמֵנָה וְאֶת הַבְּרִיאָה, שֶׁנָּתַן עֵין יְמִינוֹ בָּהֶם לָדַעַת מִי הָעֲשִׁירִים לָבֹז וְלִגְמוֹר נִכְסֵיהֶם:\",4,0],[2,139,11,17,\"זְרוֹעוֹ יָבוֹשׁ תִּיבָשׁ. לֶעָתִיד לָבֹא: ״וְנָתַתִּי נִקְמָתִי וְגוֹמֵר״ (יחזקאל כח:יד). וְהַפּוֹתְרִים פּוֹתְרִים אוֹתוֹ בְּצִדְקִיָּהוּ, עַל שֵׁם ״וְאֶת עֵינֵי צִדְקִיָּהוּ עִוֵּר״ (ירמיה כב:יא). וְאִי אֶפְשָׁר לְכַוֵּן ״הִנְנִי מֵקִים רָעָה בָּאָרֶץ״ בְּצִדְקִיָּהוּ, שֶׁכְּבָר עָבַר לוֹ שִׁבְעִים שָׁנָה:\",5,0],[2,139,12,1,\"מַשָּׂא דְבַר ה׳. הוּא גְּמַר זֶה הַדָּבָר שֶׁהִתְחִיל לְדַבֵּר בְּפֻרְעָנוּתָן שֶׁל אוֹכְלֵי יִשְׂרָאֵל עַל בָּבֶל וְכַיּוֹצֵא בּוֹ:\",1,0],[2,139,12,2,\"סַף רַעַל. כְּלִי תַּרְעֵלָה, כְּמוֹ ״בַּדָּם אֲשֶׁר בַּסַּף״ (שמות יב:כב). רַעַל לְשׁוֹן שִׁמָּמוֹן, אֹטֶם הַלֵּב וְהָאֵבָרִים שֶׁאֵין לָהֶם כֹּחַ, כְּאָדָם הַמְעֻטָּף בְּשִׂמְלָה, כְּמוֹ (נחום ב:ד) ״הַבְּרוֹשִׁים הָרְעָלוּ״, (ישעיה ג:יט) ״הַשֵּׁרוֹת וְהָרְעָלוֹת״. בִּלְשׁוֹן מִשְׁנָה (שבת ו,ו) מָצִינוּ מְדִיּוֹת רְעוּלוֹת, אונבלופמנט״א בְּלַעַ״ז:\",1,0],[2,139,12,2,\"וְגַם עַל יְהוּדָה. יַטִּילוּ הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֲשֶׁר יִהְיוּ בַּמָּצוֹר עַל יְרוּשָׁלִַם, שֶׁיִּהְיוּ בֵית דָּוִד מִבִּפְנִים וְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת יָצוּרוּ עֲלֵיהֶם, וְיָבֹאוּ גַם בְּנֵי יְהוּדָה עַל כָּרְחָם לָצוּר עַל יְרוּשָׁלִַם. כֵּן תַּרְגּוּם יוֹנָתָן:\",2,0],[2,139,12,3,\"אֶבֶן מַעֲמָסָה. אֶבֶן מַשָּׂאוֹי הַמֻּטֶּלֶת עַל בְּנֵי אָדָם מִפִּי הַמּוֹשֵׁל לָשֵׂאתָהּ וּלְעָמְסָהּ עַל כְּתֵפַיִם, וְהִיא כְּבֵדָה מְאֹד עַד אֲשֶׁר כָּל עֹמְסֶיהָ שָׂרוֹט יִשָּׂרֵטוּ:\",1,0],[2,139,12,4,\"אַכֶּה כָל סוּס. הַצּוֹבְאִים שָׁם בַּשִּׁגָּעוֹן וְאֶת רֹכְבֵיהֶם בָּעִוָּרוֹן, אֲבָל עַל בֵּית יְהוּדָה שֶׁהֵם עַל כָּרְחָם מִן הַצּוֹבְאִים אֶפְקַח עֵינַי לְהָגֵן עֲלֵיהֶם מִן הַמַּכָּה הַזֹּאת:\",1,0],[2,139,12,5,\"וְאָמְרוּ אַלֻּפֵי יְהוּדָה בְּלִבָּם. כְּשֶׁיִּרְאוּ שְׁאָר הַצּוֹבְאִים נִגָּפִים בְּמַגֵּפָה זוֹ וְהֵם נִצּוֹלִים:\",1,0],[2,139,12,5,\"אַמְצָה לִי יֹשְׁבֵי יְרוּשָׁלִַם וְגוֹ׳. יוֹשְׁבֵי יְרוּשָׁלַיִם שֶׁיּוֹדְעִים שֶׁעַל כָּרְחֵנוּ אָנוּ בָּאִים עֲלֵיהֶם, אִמְּצוּ לְעֶזְרָתִי בִּתְפִלָּתָן בַּה׳ אֱלֹהֵיהֶם:\",2,0],[2,139,12,6,\"אָשִׂים אֶת אַלֻּפֵי יְהוּדָה. יָשׁוּבוּ וְיִלָּחֲמוּ עִם אוֹתָם שֶׁהֱבִיאוּם שָׁם:\",1,0],[2,139,12,6,\"כְּכִיּוֹר אֵשׁ. כִּמְדוּרוֹת אֵשׁ גְּדוֹלָה. וְכִיּוֹר לְשׁוֹן כִּירָה (ויקרא יא:לה), וְכָךְ חִבְּרוֹ מְנַחֵם:\",2,0],[2,139,12,6,\"תַּחְתֶּיהָ. בִּמְקוֹמָהּ:\",3,0],[2,139,12,7,\"וְהוֹשִׁעַ ה׳ אֶת אָהֳלֵי יְהוּדָה בָּרִאשׁוֹנָה. בְּטֶרֶם יָבוֹאוּ בְּנֵי יְרוּשָׁלַיִם לָצֵאת מִן הָעִיר, תִּהְיֶה לָהֶם תְּשׁוּעָה לָשׁוּב אֶל אָהֳלֵיהֶם וְאֶל בֵּיתָם. וְאַחַר כָּךְ תָּבֹא תְּשׁוּעָה לִבְנֵי הָעִיר, הִיא הַתְּשׁוּעָה שֶׁנֶּאֱמַר בָּהּ ״וְיָצָא ה׳ וְנִלְחַם״ (זכריה יד:ג):\",1,0],[2,139,12,7,\"לְמַעַן לֹא תִגְדַּל. לְהִתְפָּאֵר עֲלֵיהֶם וְלוֹמַר: לֹא נִצַּלְתֶּם אֶלָּא בִּשְׁבִילֵנוּ:\",2,0],[2,139,12,8,\"הַנִּכְשָׁל בָּהֶם. הַחַלָּשׁ שֶׁבָּהֶם:\",1,0],[2,139,12,8,\"כֵּאלֹהִים. ״כְּרַבְרְבִין״ (תרגום יונתן), כְּמַלְאָכִים:\",2,0],[2,139,12,8,\"כְּמַלְאַךְ ה׳ לִפְנֵיהֶם. ״יִצְלְחוּן כְּמַלְאֲכָא דַה׳ קֳדָמֵיהוֹן״ (תרגום יונתן):\",3,0],[2,139,12,9,\"אֲבַקֵּשׁ לְהַשְׁמִיד. אֲבַקֵּשׁ בְּהַשְׁמָדָתָם וַאֲדַקְדֵּק בַּעֲוֹנָם. וְרַבּוֹתֵינוּ פֵּרְשׁוּ לִזְכוּת (עבודה זרה ד.): אֲבַקֵּשׁ בְּנוֹגְנֵי שֶׁלָּהֶם; אִם יֵשׁ לָהֶם זְכוּת – אֲנִיחֵם, וְאִם לָאו – אַשְׁמִידֵם:\",1,0],[2,139,12,10,\"רוּחַ חֵן וְתַחֲנוּנִים. שֶׁיַּעֲלֶה עַל רוּחָם לְהִתְחַנֵּן לְפָנַי, וְהֵם יִהְיוּ לְחֵן בְּעֵינַי:\",1,0],[2,139,12,10,\"רוּחַ. טָלַנְ״ט בְּלַעַ״ז:\",2,0],[2,139,12,10,\"וְהִבִּיטוּ אֵלַי אֵת אֲשֶׁר דָּקָרוּ. תִּרְגֵּם יוֹנָתָן: ״וְיִבְעוֹן מִן קֳדָמַי עַל דִּי אִיטַלְטְלוּ״:\",3,0],[2,139,12,10,\"וְהִבִּיטוּ. לְהִתְאוֹנֵן עַל אֲשֶׁר דָּקְרוּ בָּהֶם הָאֻמּוֹת וְהָרְגוּ בָּהֶם בַּגָּלוּת:\",4,0],[2,139,12,10,\"וְסָפְדוּ עָלָיו. עַל אוֹתוֹ הֶרֶג:\",5,0],[2,139,12,10,\"כְּמִסְפֵּד עַל הַיָּחִיד. כַּאֲשֶׁר יִסְפֹּד אִישׁ עַל בֵּן יְחִידוֹ. וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ עַל מָשִׁיחַ בֶּן יוֹסֵף שֶׁנֶּהֱרַג בִּמְסֶכֶת סֻכָּה (סוכה נב.):\",6,0],[2,139,12,11,\"כְּמִסְפַּד הֲדַדְרִמּוֹן בְּבִקְעַת מְגִדּוֹן. אֵין עִנְיַן הֲדַדְרִימּוֹן בְּבִקְעַת מְגִדּוֹן, אֶלָּא שְׁנֵי מִסְפָּדוֹת הֵן: ״כְּמִסְפְּדָא דְאַחְאָב בַּר עָמְרִי דְּקָטַל יָתֵיהּ הֲדַדְרִמּוֹן בַּר טַבְרִימוֹן ״בְּרָמוֹת גִּלְעָד, שֶׁנֶּאֱמַר (מלכים א כב:לו) ״וַיַּעֲבֹר הָרִנָּה בַּמַּחֲנֶה״, וְהוּא הֶסְפֵּד. ״וּכְמִסְפְּדָא דְיֹאשִׁיָּהוּ בַּר אָמוֹן דְּקָטַל יָתֵיהּ פַּרְעֹה חֲגִירָא בְּבִקְעַת מְגִדּוֹן״, שֶׁנֶּאֱמַר שָׁם (דברי הימים ב לה:כה) ״וַיְקוֹנֵן יִרְמְיָהוּ וְגוֹ׳ וַיֹּאמְרוּ כָל הַשָּׂרִים וְהַשָּׁרוֹת בְּקִינוֹתֵיהֶם וְגוֹ׳״:\",1,0],[2,139,12,12,\"בֵּית נָתָן. הַנָּבִיא. וְיֵשׁ אוֹמְרִים: נָתָן בֶּן דָּוִד, כְּמוֹ שֶׁנֶּאֱמַר: ״שַׁמּוּעַ וְשׁוֹבָב וְנָתָן וּשְׁלֹמֹה״ (שמואל ב ה:יד):\",1,0],[2,139,12,13,\"בֵּית לֵוִי. הַכֹּהֲנִים וְהַלְוִיִּם:\",1,0],[2,139,12,13,\"מִשְׁפַּחַת הַשִּׁמְעִי. שַׁמּוּעַ בֶּן דָּוִד (שמואל ב ה:יד), בִּתְחִלָּה כָּלַל הַכָּתוּב מִשְׁפְּחוֹת בֵּית דָּוִד וְאַחַר כָּךְ פֵּרַט כָּל אַחַת וְאַחַת:\",2,0],[2,139,12,14,\"כָּל הַמִּשְׁפָּחוֹת הַנִּשְׁאָרוֹת. לְבֵית דָּוִד:\",1,0],[2,139,12,14,\"וּנְשֵׁיהֶם לְבָד. מִשּׁוּם צְנִיעוּת (סוכה נא:-נב.). וְלָמָּה מִשְׁפְּחוֹת הַכְּהוּנָּה וְהַמַּמְלָכוּת? כְּדֵי לְהַחֲזִיר לָהֶם כִּתְרֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר בְּרֹאשׁ הַסֵּפֶר ״אֵלֶּה שְׁנֵי בְנֵי הַיִּצְהָר הָעֹמְדִים עַל אֲדוֹן כָּל הָאָרֶץ״ (זכריה ד:יד):\",2,0],[2,139,13,1,\"לְחַטַּאת וּלְנִדָּה. לְאַדְיוּתָא, וְכֵן תִּרְגֵּם יוֹנָתָן: ״אֶשְׁבּוֹק לְחוֹבֵיהוֹן כְּמָא דְמִדְכָּן בְּמֵי אַדְיוּתָא וּבְקִטְם תּוֹרְתָא דְחַטָּאתָא״ – בְּאֵפֶר חַטָּאת:\",1,0],[2,139,13,2,\"וְגַם אֶת הַנְּבִיאִים. ״נְבִיאֵי שִׁקְרָא״:\",1,0],[2,139,13,2,\"רוּחַ הַטֻּמְאָה. יֵצֶר הָרָע:\",2,0],[2,139,13,4,\"אַדֶּרֶת שֵׂעָר. כֵּן דֶּרֶךְ מְסִיתִים וּמַדִּיחִים, מִתְעַטְּפִים בְּטַלִּיתָם כְּאִלּוּ הֵם אֲנָשִׁים צַדִּיקִים, לְמַעַן יְקֻבְּלוּ כַּחֲשֵׁיהֶם:\",1,0],[2,139,13,5,\"כִּי אָדָם הִקְנַנִי. פָּתַר בּוֹ מְנַחֵם לְשׁוֹן מִקְנֵה צֹאן וּבָקָר (בראשית כו:יד), כִּי אֲנִי כִּשְׁאָר כָּל אָדָם שֶׁאֵינוֹ עָסוּק בִּנְבוּאוֹת, הִפְקִידַנִי מִנְּעוּרַי לִשְׁמֹר אֶת מִקְנֵהוּ:\",1,0],[2,139,13,6,\"בֵּין יָדֶיךָ. בֵּין כְּתֵפֶיךָ, שָׁם מַלְקִין עוֹבְרֵי עֲבֵירָה (מכות כב.):\",1,0],[2,139,13,6,\"בֵּית מְאַהֲבָי. אֲשֶׁר אֲהָָבוּנִי וְהוֹכִיחוּנִי לַדֶּרֶךְ הַיְשָׁרָה:\",2,0],[2,139,13,7,\"חֶרֶב עוּרִי עַל רֹעִי. עַל אוֹתוֹ שֶׁהִפְקַדְתִּיו עַל צֹאן גָּלוּתִי:\",1,0],[2,139,13,7,\"וְעַל גֶּבֶר עֲמִיתִי. שֶׁחִבַּרְתִּיו אֵלַי לִשְׁמֹר צֹאנִי כָּמוֹנִי:\",2,0],[2,139,13,7,\"הַךְ אֶת הָרוֹעֶה. אֶת מֶלֶךְ רוֹמִי הָרְשָׁעָה:\",3,0],[2,139,13,7,\"וַתְּפוּצֶינָה הַצֹּאן. שֶׁכְּבוּשָׁה תַּחַת יָדוֹ:\",4,0],[2,139,13,7,\"וַהֲשִׁבֹתִי יָדִי. וְאֶשְׁנֶה מַכּוֹתַי שֵׁנִית:\",5,0],[2,139,13,7,\"עַל הַצּוֹעֲרִים. עַל הַשִּׁלְטוֹנִים הַצְּעִירִים מִן הַמְּלָכִים. וְיוֹנָתָן תִּרְגֵּם וַתְּפוּצֶינָה הַצֹּאן ״וְיִתְבַּדְּרוּן שִׁלְטוֹנַיָּא״, וְתִרְגֵּם עַל הַצּוֹעֲרִים מְמֻנִּים שֶׁלָּהֶם הַשְּׁנִיִּים לָהֶם, וְכֵן תִּרְגֵּם יוֹנָתָן הַמִּקְרָא הַזֶּה בָּאֻמּוֹת ״חַרְבָּא אִתְגְּלִי עַל מַלְכָּא דְבָבֶל וְעַל שִׁלְטוֹנַיָּא חַבְרֵיהּ דִּכְוָתֵיהּ דְּדָמֵי לֵיהּ אֲמַר ה׳ צְבָאוֹת קְטוֹל יַת מַלְכָּא דְבָבֶל וְיִתְבַּדְּרוּן שִׁלְטוֹנַיָּא״. וְאֵין לְשׁוֹן הַתַּרְגּוּם הַזֶּה נוֹפֵל עַל יִשְׂרָאֵל, שֶׁלֹּא מָצִינוּ בְּתַרְגּוּם וּבְמִקְרָא שִׁלְטוֹנִין בְּיִשְׂרָאֵל אֶלָּא מֶלֶךְ וְשָׂרִים וְתַרְגּוּם שֶׁלָּהֶן ״רַבְרְבִין״:\",6,0],[2,139,13,8,\"וְהַשְּׁלִישִׁית יִוָּתֶר בָּהּ. יִתְגַּיְּרוּ וְיִחְיוּ:\",1,0],[2,139,13,9,\"וְהֵבֵאתִי אֶת הַשְּׁלִישִׁית בָּאֵשׁ. ״וְאָעֵיל יָת תְּלִיתָא בְּעָקָא בְּכוּר דְּאֶשָּׁא״, שֶׁיִּסְבְּלוּ וְיִשְׂאוּ מִקְצָת הַגֵּרִים מֵהָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת בְּצָרוֹת חֶבְלוֹ שֶׁל מָשִׁיחַ וּבְמִלְחֲמוֹת גּוֹג וּמָגוֹג עִם יִשְׂרָאֵל, וּמִשָּׁם יִבָּחֲנוּ כִּי גֵרֵי אֱמֶת הֵם. כִּי הַרְבֵּה מִן הַמִּתְיַהֲדִים תְּחִלָּה יָשׁוּבוּ לְסוּרָם וְיִתְחַבְּרוּ עִם גּוֹג, כְּמוֹ שֶׁאָמְרוּ בָּאַגָּדָה (עבודה זרה ג:):\",1,0],[2,139,13,9,\"וְהוּא יֹאמַר ה׳. כְּשֶׁיִּתְפַּלֵּל, יִתְפַּלֵּל לַה׳, וְלֹא לֵאלֹהָיו הָרִאשׁוֹן:\",2,0],[2,139,14,1,\"הִנֵּה יוֹם וְגוֹ׳. חָבִיב לְהַקָּדוֹשׁ בָּרוּךְ הוּא:\",1,0],[2,139,14,1,\"וְחֻלַּק שְׁלָלֵךְ בְּקִרְבֵּךְ. שָׁלָל שֶׁתִּשְׁלְלִי מֵאוֹיְבִים יְחַלְּקוּ יוֹשְׁבַיִךְ בְּקִרְבֵּךְ. וְכֵן תִּרְגֵּם יוֹנָתָן: ״וִיפַלְּגוּן בֵּית יִשְׂרָאֵל נִכְסֵי עַמְמַיָּא בְּגַוִּיךְ יְרוּשְׁלֵם״:\",2,0],[2,139,14,2,\"וְיֶתֶר הָעָם לֹא יִכָּרֵת. לֹא יִגְלוּ כֻּלָּם. וְלָמָּה יַנִּיחֵם לְהַגְלוֹת חֶצְיָם וְלָשֹׁסוֹת הַבָּתִּים? כְּדֵי שֶׁלֹּא יְהֵא לָהֶם פִּתְחוֹן פֶּה לֵאמֹר: לֹא לַמִּלְחָמָה בָּאנוּ, כִּי אִם לְהִשְׁתַּחֲווֹת בָּאנוּ:\",1,0],[2,139,14,3,\"כְּיוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב. ״כְּיוֹם אֲגָחוּתֵיהּ קְרָב עַל יַמָּא דְּסוּף״:\",1,0],[2,139,14,4,\"מֵחֶצְיוֹ. מֵאֶמְצָעִיתוֹ:\",1,0],[2,139,14,4,\"מִזְרָחָה וָיָמָּה. מִן הַמִּזְרָח לַמַּעֲרָב, כְּמוֹ שֶׁמְּסַיֵּם וְהוֹלֵךְ:\",2,0],[2,139,14,4,\"וּמָשׁ חֲצִי הָהָר צָפוֹנָה וְגוֹ׳. חֶצְיוֹ הַצְּפוֹנִי יָמוּשׁ מִמְּקוֹמוֹ וְיִמָּשֵׁךְ לְצַד צָפוֹן, וְכֵן מָצִינוּ חֶצְיוֹ נֶגְבָּה לְצַד דָּרוֹם. וְיִהְיֶה הַגַּיְא בֵּינֵיהֶם, רֹאשׁוֹ לְמִזְרָח וְסוֹפוֹ לְמַעֲרָב:\",3,0],[2,139,14,5,\"וְנַסְתֶּם גֵּיא הָרַי. יוֹנָתָן תִּרְגֵּם: ״וְיִסְתַּתֵּם גֵּיא הָרַי״. לְפִי שֶׁ״יְרוּשָׁלַיִם הָרִים סָבִיב לָהּ״ (תהלים קכה:ב), וְיֵשׁ גַּיְא בֵּין הַר שֶׁבַּצָּפוֹן וּבֵין הַר הַזֵּיתִים, וְכֵן בַּדָּרוֹם. וּכְשֶׁיִּמָּשֵׁךְ חֲצִי הַר הַזֵּיתִים אֵצֶל הַר שֶׁבִּצְפוֹנוֹ, יִסָּתֵם הַגַּיְא שֶׁבֵּינֵיהֶם, וְכֵן בַּדָּרוֹם:\",1,0],[2,139,14,5,\"כִּי יַגִּיעַ. גֹּבַהּ גַּיְא שֶׁהָיָה בֵּין הֶהָרִים:\",2,0],[2,139,14,5,\"אֶל אָצַל. אֶל גֹּבַהּ רָאשֵׁי הֶהָרִים שֶׁמִּכָּאן וּמִכָּאן. וְכֵן חִבְּרוֹ מְנַחֵם (ישעיהו מא:ט) ״וּמֵאֲצִילֶיהָ קְרָאתִיךָ״, וּפֵרוּשׁוֹ לְשׁוֹן גֹּבַהּ:\",3,0],[2,139,14,5,\"וְנַסְתֶּם. בִּרְאוֹתְכֶם הַמּוֹפֵת הַגָּדוֹל הַזֶּה:\",4,0],[2,139,14,5,\"כַּאֲשֶׁר נַסְתֶּם מִפְּנֵי הָרַעַשׁ. (יְשַׁעְיָהוּ ו:ד) ״וַיָּנֻעוּ אַמּוֹת הַסִּפִּים״ בְּיוֹם שֶׁנִּתְנַגַּע עֻזִּיָּהוּ:\",5,0],[2,139,14,5,\"כָּל קְדוֹשִׁים. מַלְאָכִים:\",6,0],[2,139,14,6,\"לֹא יִהְיֶה אוֹר יְקָרוֹת וְקִפָּאוֹן. יוֹנָתָן תִּרְגֵּם: ״לָא יְהֵי נְהוֹרָא אֶלָּהֵין עָדֵי וְגָלִיד יְהֵי נְהוֹרָא״. לֹא יִהְיֶה אוֹר נֹגַהּ, כִּי יְקָרוֹת וְקִפָּאוֹן יִהְיֶה. יְקָרוֹת – לְשׁוֹן ״כִּיקַר כָּרִים״ (תהלים לז:כ): הוּא כְּמִין אוֹר הַנִּרְאֶה שַׁחֲרִית עַל הֶהָרִים, וְכָלֶה וְהוֹלֵךְ:\",1,0],[2,139,14,6,\"וְקִפָּאוֹן. קָפוּי וְחָשׁוּךְ וְעָב כַּקֶּרַח שֶׁנִּקְפָּה וּמַגְלִיד, כְּמוֹ ״וְכַגְּבִינָה תַּקְפִּיאֵנִי״ (איוב י:י):\",2,0],[2,139,14,7,\"וְהָיָה יוֹם אֶחָד. וְהָיָה הַדָּבָר הַזֶּה יוֹם אֶחָד מִיּוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא הַיּוֹם יָדוּעַ שֶׁהוּא לַהֲכָנַת יִשְׁעוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (פרקי דרבי אליעזר כח):\",1,0],[2,139,14,7,\"לֹא יוֹם וְלֹא לָיְלָה. לֹא אוֹר נֹגַהּ כְּאוֹר שֶׁל עוֹלָם הַבָּא, שֶׁנֶּאֱמַר: ״וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר וְגוֹמֵר״ (ישעיהו ל:כו):\",2,0],[2,139,14,7,\"וְלֹא לָיְלָה. וְלֹא עֵת צָרָה כְּצָרַת שִׁעְבּוּד גָּלֻיּוֹת שֶׁמִּקֹּדֶם, שֶׁיְּמֵי מְשִׁיחֵנוּ יִהְיוּ וְאֵין בָּהֶם שִׁעְבּוּד:\",3,0],[2,139,14,7,\"וְהָיָה לְעֵת עֶרֶב. קֹדֶם שֶׁיִּגָּמְרוּ אֶלֶף שָׁנָה יִהְיֶה אוֹר הַנֹּגַהּ וְכָל הַטּוֹב הָאָמוּר עַל יִשְׂרָאֵל (בראשית רבה ע:סב). וְכֵן תִּרְגֵּם יוֹנָתָן: ״לָא כִּנְהוֹר יוֹמָא וְלָא כִּקְבַל לֵילְיָא״:\",4,0],[2,139,14,8,\"וְהָיָה בַּיּוֹם הַהוּא. כְּשֶׁיִּבָּקַע הַר הַזֵּיתִים מִן הַמִּזְרָח לַמַּעֲרָב (זכריה יד:ד):\",1,0],[2,139,14,8,\"יֵצְאוּ מַיִם חַיִּים מִירוּשָׁלַ͏ִם. וְיֵלְכוּ לַמִּזְרָח דֶּרֶךְ אוֹתָהּ בְּקִיעָה עַד הַיָּם הַקַּדְמוֹנִי שֶׁהוּא לְמִזְרָחוֹ שֶׁל עוֹלָם קֵדְמָה. וְחֶצְיוֹ יִפְנֶה לַמַּעֲרָב אֶל יָם הַמַּעֲרָבִי. הוּא הַמַּעְיָן שֶׁנִּבָּא יוֹאֵל (יואל ד:יח) ״וּמַעְיָן מִבֵּית ה׳ יֵצֵא״, הוּא הַנַּחַל שֶׁנִּבָּא (יחזקאל מז:ד) ״וַיָּמָד אֶלֶף וַיַּעֲבִרֵנִי בַמַּיִם וְגוֹ׳״:\",2,0],[2,139,14,9,\"יִהְיֶה ה׳ אֶחָד. שֶׁכָּל הָאֻמּוֹת יַעַזְבוּ הַבְלֵיהֶם וְיוֹדוּ לוֹ שֶׁהוּא אֶחָד וְאֵין עִמּוֹ אֵל נֵכָר:\",1,0],[2,139,14,9,\"וּשְׁמוֹ אֶחָד. שֶׁיְּהֵא שְׁמוֹ נִזְכָּר בְּפִי כֻּלָּם:\",2,0],[2,139,14,10,\"יִסּוֹב כָּל הָאָרֶץ. יֵהָפֵךְ לִהְיוֹת כָּל הָאָרֶץ כַּעֲרָבָה, יִשְׁפְּלוּ הֶהָרִים וִיהִי כָּל הָעוֹלָם כֻּלּוֹ מִישׁוֹר (ישעיהו מ:ד), וִירוּשָׁלַיִם הַר כְּדֵי שֶׁתֵּרָאֶה גָּבוֹהַּ עַל הַכֹּל:\",1,0],[2,139,14,10,\"מִגֶּבַע לְרִמּוֹן נֶגֶב יְרוּשָׁלָ͏ִם. שָׁנִינוּ בְּתוֹסֶפְתָּא דְּסוֹטָה (תוספתא סוטה יא,יד): נֶגֶב יְרוּשָׁלִַם מִישׁוֹר הוּא, וְגֶבַע רִמּוֹן טְרָשִׁין וְקַרְקְשִׁין. וְכֵן פִּתְרוֹנוֹ: מִגֶּבַע לְרִמּוֹן, שֶׁהוּא מְקוֹם הָרִים, מִשָּׁם יַתְחִילוּ לִהְיוֹת נֶהְפָּכִין לַעֲרָבָה וּלְמִישׁוֹר, וְיִהְיוּ דוֹמִין לְנֶגֶב יְרוּשָׁלִַם, שֶׁהוּא מִישׁוֹר:\",2,0],[2,139,14,10,\"וְרָאֲמָה. מִתּוֹךְ שֶׁכָּל סְבִיבָהּ מִישׁוֹר, תֵּרָאֶה הִיא גְּבוֹהָָָה:\",3,0],[2,139,14,10,\"וְיָשְׁבָה תַּחְתֶּיהָ. בִּמְקוֹמָהּ:\",4,0],[2,139,14,10,\"עַד שַׁעַר הַפִּנִּים וּמִגְדַּל חֲנַנְאֵל. גַּם הוּא בִּמְקוֹמוֹ, וּמִשָּׁם יִמָּשֵׁךְ אֹרֶךְ הָעִיר עַד יִקְבֵי הַמֶּלֶךְ. תַּרְגּוּם יוֹנָתָן: ״שִׁיחֵי דְמַלְכָּא״, פושיי״ן בְּלַעַ״ז. וּכְמוֹ (בבא קמא נ:) שִׁיחִין וּמְעָרוֹת. וְכֵן כָּל יְקָבִים שֶׁבַּמִּקְרָא לְשׁוֹן שִׁיחִין הֵם: בּוֹר שֶׁלִּפְנֵי הַגַּת שֶׁהַיַּיִן זָב לְתוֹכוֹ. וּמִדְרַשׁ אַגָּדָה: יִקְבֵי מֶלֶךְ יָם אוֹקְיָנוֹס, שֶׁתַּגִּיעַ יְרוּשָׁלַיִם עַד סוֹף כָּל הָעוֹלָם. יְקָבִים שֶׁחֲצָבָם מֶלֶךְ מַלְכֵי הַמְּלָכִים:\",5,0],[2,139,14,11,\"וְחֵרֶם לֹא יִהְיֶה. הָעִיר עוֹד:\",1,0],[2,139,14,12,\"הָמֵק בְּשָׂרוֹ וְהוּא עוֹמֵד. זֶה נִפּוּל אֵיבָרִים:\",1,0],[2,139,14,13,\"תִּהְיֶה מְהוּמַת ה׳ רַבָּה בָּהֶם. לְעַרְבֵּב חָכְמָתָם לְהָפְכָם לְשִׁגָּעוֹן:\",1,0],[2,139,14,13,\"וְהֶחֱזִיקוּ אִישׁ יַד רֵעֵהוּ. יֹאחֵז בּוֹ לְהָרְגוֹ:\",2,0],[2,139,14,13,\"וְעָלְתָה יָדוֹ. כָּל דְּאַלִּים גָּבַר (בבא בתרא לד:):\",3,0],[2,139,14,14,\"וְגַם יְהוּדָה. עַל כָּרְחָהּ תִּלָּחֵם עַל יִשְׂרָאֵל:\",1,0],[2,139,14,15,\"כַּמַּגֵּפָה הַזֹּאת. הַמְפֹרֶשֶׁת לְמַעְלָה ״הָמֵק בְּשָׂרוֹ״:\",1,0],[2,139,14,16,\"אֶת חַג הַסֻּכּוֹת. כְּמוֹ שֶׁפֵּרְשׁוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בְּמַסֶּכֶת עֲבוֹדָה זָרָה: מִצְוָה קַלָּה יֵשׁ לִי וְסֻכָּה שְׁמָהּ, כִּדְאִיתָא בִּשְׁמַעְתָּא רִאשׁוֹנָה (עבודה זרה ג.):\",1,0],[2,139,14,17,\"הַגָּשֶׁם. גְּשָׁמִים מַמָּשׁ, לְהַצְמִיחַ פֵּרוֹת אַרְצָם. וּמָה רָאָה לִגְזֹר עֲלֵיהֶם עֲצִירַת גְּשָׁמִים? לְפִי שֶׁמִּצְוֹת הֶחָג עַל הַגְּשָׁמִים הֵם – אַרְבַּעַת מִינִים שֶׁבַּלּוּלָב וְנִסּוּךְ הַמַּיִם – לְרַצּוֹת עַל הַמַּיִם, עַל שֶׁהֶחָג זְמַן גִּשְׁמֵי שָׁנָה הוּא. וְאֵלּוּ הַמְפַקְפְּקִין בְּחַג הַסֻּכּוֹת, לֹא עֲלֵיהֶם יִהְיֶה הַגָּשֶׁם. כָּךְ לָמַדְתִּי בְּתוֹסֶפְתָּא דְּסֻכָּה (תוספתא סוכה ג:יח):\",1,0],[2,139,14,18,\"וְאִם מִשְׁפַּחַת מִצְרַיִם לֹא תַעֲלֶה. וְהֵן אֵין צְרִיכִים לִגְשָׁמִים, שֶׁנִּילוּס עוֹלֶה וּמַשְׁקֶה אוֹתָם:\",1,0],[2,139,14,18,\"וְלֹא עֲלֵיהֶם. תִּהְיֶה הַגֶּשֶׁם שֶׁלָּהֶם, כְּלוֹמַר: לֹא יַשְׁקֶה אוֹתָם נִילוּס. וְכֵן תִּרְגֵּם יוֹנָתָן: ״לָא עֲלֵיהוֹן יִסַּק נִילוּס״:\",2,0],[2,139,14,18,\"תִּהְיֶה הַמַּגֵּפָה. שֶׁל רָעָב:\",3,0],[2,139,14,18,\"אֲשֶׁר יִגֹּף ה׳‏. זֹאת תִּהְיֶה עֹנֶשׁ מִצְרַיִם וְעֹנֶשׁ כָּל הָעוֹבְדֵי כּוֹכָָבִים וּמַזָָָָּלוֹת, כְּמוֹ שֶׁאָמַר לֹא עֲלֵיהֶם יִהְיֶה הַגֶּשֶׁם:\",4,0],[2,139,14,20,\"מְצִלּוֹת הַסּוּס. עַל הַנְּקִישׁוֹת שֶׁתּוֹלִין לַסּוּס לְנוֹי בֵּין עֵינָיו (פסחים נ.), אַף אוֹתָן יַקְדִּישׁוּ לַעֲשׂוֹת כְּלֵי שָׁרֵת לַמִּזְרָקִים לַדָּם וְלַסִּירוֹת לְבַשֵּׁל בְּשַׂר זְבָחִים לָרֹב:\",1,0],[2,139,14,20,\"וְהָיָה הַסִּירוֹת. שֶׁהֵם הָיוּ לְדַשֵּׁן (אֶת הַדֶּשֶׁן) אַף הֵם יִהְיוּ שֶׁל זָהָב וְשֶׁל כֶּסֶף כַּמִּזְרָקִים אֲשֶׁר לִפְנֵי הַמִּזְבֵּחַ:\",2,0],[2,139,14,20,\"מְצִלּוֹת הַסּוּס. טַנְטִינִי״ר בְּלַעַ״ז:\",3,0],[2,139,14,21,\"וְלֹא יִהְיֶה כְנַעֲנִי. לֹא יִצְטָרְכוּ לִסְחוֹר, כְּמוֹ (ישעיהו כג:ח) ״כִּנְעָנֶיהָ נִכְבַּדֵּי אָרֶץ״. דָּבָר אַחֵר: אֵין כָּאן עָנִי:\",1,0],[2,140,1,2,\"אָסֹף אָסֵף. לְשׁוֹן ׳כִּלָּיוֹן׳, כְּמוֹ (שופטים יח:כה) ״וְאָסַפְתָּ אֶת נַפְשֶׁךָ״ דְּמִיכָה. וְאָלֶ״ף חֲסֵרָה בְּתֵיבָה שְׁנִיָּה, שֶׁהֲרֵי הָיָה לוֹ לִכְתֹּב ״אֶאֱסֹף״, אֲבָל יֵשׁ כָּאֵלֶּה הַרְבֵּה, כְּמוֹ ״לֹא יָהֵל שָׁם עֲרָבִי״ (ישעיהו יג:כ), שֶׁהוּא כְּמוֹ ״לֹא יֶאֱהַל״.\",1,0],[2,140,1,3,\"וְהַמַּכְשֵׁלוֹת אֶת הָרְשָׁעִים. הֵם הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת.\",1,0],[2,140,1,4,\"אֶת שְׁאָר הַבַּעַל. שֶׁלֹּא תְהֵא שְׁאֵרִית לְזִכְרוֹנוֹ.\",1,0],[2,140,1,4,\"הַכְּמָרִים עִם הַכֹּהֲנִים. ״פַּלְחֵיהוֹן עִם כּוּמְרֵיהֶם״.\",2,0],[2,140,1,5,\"וְאֶת הַנִּשְׁבָּעִים לַה׳. וְחוֹזְרִים וְנִשְׁבָּעִים בְּמַלְכָּם, בַּעֲבוֹדָה זָרָה שֶׁלָּהֶם. עוֹשִׂין עֲבוֹדָה זָרָה עִקָּר, לוֹמַר: אִם אֵין אַתָּה מַאֲמִין בִּשְׁבוּעַת ה׳, הֲרֵינִי נִשְׁבָּע לְךָ בַּעֲבוֹדָה זָרָה.\",1,0],[2,140,1,7,\"הִקְדִּישׁ קְרֻאָיו. זִמֵּן חֵילוֹתָיו לְיוֹם מוֹעֵד.\",1,0],[2,140,1,8,\"מַלְבּוּשׁ נָכְרִי. תַּכְשִׁיטֵי עֲבוֹדָה זָרָה.\",1,0],[2,140,1,9,\"הַדּוֹלֵג עַל הַמִּפְתָּן. תִּרְגֵּם יוֹנָתָן: ״דְּמְהַלְכִין בְּנִימוּסֵי פְלִשְׁתָּאֵי״, שֶׁלֹּא הָיוּ דּוֹרְכִים עַל מִפְתַּן דָּגוֹן, שֶׁנֶּאֱמַר: ״עַל כֵּן לֹא יִדְרְכוּ כֹהֲנֵי דָגוֹן וְגוֹ׳״ (שמואל א ה:ה).\",1,0],[2,140,1,10,\"מִשַּׁעַר הַדָּגִים. תִּרְגֵּם יוֹנָתָן: ״מִתְּרַע נוּנַיָּא״. וְשַׁעַר הָיָה בִּירוּשָׁלַיִם וְכָךְ שְׁמוֹ.\",1,0],[2,140,1,10,\"מִן הַמִּשְׁנֶה. מִשַּׁעַר הָעוֹפוֹת שֶׁהוּא שֵׁנִי לוֹ.\",2,0],[2,140,1,11,\"יֹשְׁבֵי הַמַּכְתֵּשׁ. ״נַחֲלָא דְקִדְרוֹן״, שֶׁעֲמֻקָּה כְּמַכְתֶּשֶׁת זֶה, תִּרְגֵּם יוֹנָתָן. וּמִדְרַשׁ אַגָּדָה: מִשַּׁעַר הַדָּגִים – זוֹ עַכּוֹ הַנְּתוּנָה בְּחֵיקוֹ שֶׁל הַיָּם, שֶׁשָּׁם נְצוֹדִים דָּגִים הַרְבֵּה.\",1,0],[2,140,1,11,\"מִן הַמִּשְׁנֶה. לוֹד, שֶׁהִיא מִשְׁנֶה לִירוּשָׁלַיִם.\",2,0],[2,140,1,11,\"מֵהַגְּבָעוֹת. זוֹ צִפּוֹרִי, שֶׁיּוֹשֶׁבֶת בְּרָאשֵׁי הֶהָרִים כְּצִפּוֹר.\",3,0],[2,140,1,11,\"יֹשְׁבֵי הַמַּכְתֵּשׁ. זוֹ טְבֶרְיָא, שֶׁעֲמוּקָה מִכָּל אֶרֶץ יִשְׂרָאֵל.\",4,0],[2,140,1,11,\"כִּי נִדְמָה כָּל עַם כְּנַעַן. תִּרְגֵּם יוֹנָתָן: ״אֲרֵי אֲתַר כָּל עַמָּא דְּדָמֵי עוֹבָדֵיהוֹן לְעוֹבְדֵי עַמָּא דְאַרְעָא דִכְנָעַן״.\",5,0],[2,140,1,11,\"כָּל נְטִילֵי כֶסֶף. ״כָּל עֲתִּירֵי נִכְסַיָּא״ טְעוּנֵי מַשָּׂא כֶּסֶף וְזָהָב, כְּמוֹ (משלי כז:ג) ״כֹּבֶד הָאֶבֶן וְנֵטֶל הַחוֹל״, לְשׁוֹן ׳מַשָּׂא׳.\",6,0],[2,140,1,12,\"אֲחַפֵּשׂ אֶת יְרוּשָׁלַ͏ִם בַּנֵּרוֹת. אֲדַקְדֵּק בַּעֲוֹנוֹתֵיהֶם.\",1,0],[2,140,1,12,\"הַקֹּפְאִים. הַצָּפִים עַל שִׁמְרֵיהֶם. ״וַיָּצֶף הַבַּרְזֶל״ (מלכים ב ו:ו) מְתַרְגְּמִינַן: ״וּקְפָא פַרְזְלָא״.\",2,0],[2,140,1,12,\"הָאֹמְרִים בִּלְבָבָם לֹא יֵיטִיב ה׳. לְעוֹשֵׂי רְצוֹנוֹ.\",3,0],[2,140,1,12,\"וְלֹא יָרֵעַ. לְעוֹבְרֵי רְצוֹנוֹ.\",4,0],[2,140,1,14,\"מַר צֹרֵחַ שָׁם גִּבּוֹר. הַגִּבּוֹר יִצְרַח שָׁם בְּקוֹל מַר.\",1,0],[2,140,1,15,\"יוֹם שׁוֹאָה. לְשׁוֹן ׳שִׁמָּמוֹן׳.\",1,0],[2,140,1,15,\"וּמְשׁוֹאָה. שִׁמָּמוֹן יוֹתֵר.\",2,0],[2,140,1,17,\"וַהֲצֵרֹתִי לָאָדָם. לְיִשְׂרָאֵל הַקְּרוּיִים אָדָם.\",1,0],[2,140,1,17,\"וּלְחֻמָּם. בְּשָׂרָם. וּלְשׁוֹן עַרְבִי, בָּשָׂר קוֹרִין ׳אַל לַחַם׳.\",2,0],[2,140,1,17,\"כַּגְּלָלִים. רְעִי.\",3,0],[2,140,2,1,\"הִתְקוֹשְׁשׁוּ. הִתְלַקְּטוּ וְאִסְפוּ יַחַד, כְּמוֹ ״לְקֹשֵׁשׁ קַשׁ״ (שמות ה:יב).\",1,0],[2,140,2,1,\"וָקוֹשּׁוּ. מַעֲשֵׂיכֶם. הַשְׁווּ מַעֲשֵׂיכֶם לְדַעַת קוֹנְכֶם. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה דָּרְשׁוּ: קַשֵּׁט עַצְמְךָ וְאַחַר כָּךְ קַשֵּׁט אֲחֵרִים. עָשׂוּ שְׁנֵיהֶם לְשׁוֹן ׳הֶקֵּשׁ׳, אָדָם הַמַּשְׁוֶה עַצְמוֹ וּמְיַשֵּׁר דַּרְכּוֹ.\",2,0],[2,140,2,1,\"הַגּוֹי לֹא נִכְסָף. תִּרְגֵּם יוֹנָתָן: ״דְּלָא חֲמַד לְמֵיתַב לְאוֹרָיְתָא״.\",3,0],[2,140,2,2,\"בְּטֶרֶם לֶדֶת חֹק. לִפְנֵי בֹּא הַגְּזֵירָה.\",1,0],[2,140,2,2,\"כְּמֹץ עָבַר. הֲרֵי זֶה מִקְרָא קָצָר, כְּמֹץ הָעוֹבֵר מִלִּפְנֵי רוּחַ, וּכְעָשָׁן הָעוֹבֵר מִלִּפְנֵי הַשֶּׁמֶשׁ. וְזֶהוּ תַּרְגּוּמוֹ שֶׁל ״עָבַר יוֹם״. כָּךְ תִּרְגֵּם יוֹנָתָן: ״תֶּהֱווֹן דָּמַן לְכְמוֹצָא דְּנָשֵׁב בֵּיהּ רוּחָא, וּכִתְנָנָא דְּעָדֵי מִן קֳדָם יוֹמָא״. נֻסָּח אַחֵר: כְּטוּלָא דְּעָדוֹ וְכוּ׳״, זֶהוּ לְשׁוֹן ׳צֵל׳.\",2,0],[2,140,2,4,\"כִּי עַזָּה עֲזוּבָה תִהְיֶה. כִּי אִם תַּעֲשׂוּ כֵּן, אֶפְקֹד עַל שְׁכֵנֵיכֶם הָרָעִים – פְּלֶשֶׁת וְעַמּוֹן וּמוֹאָב, כְּמוֹ שֶׁהַנָּבִיא מְסַדְּרָן וְהוֹלֵךְ.\",1,0],[2,140,2,4,\"בַּצָּהֳרַיִם יְגָרְשׁוּהָ. אַשְׁדּוֹד שְׁמָהּ, וּבַצָּהֳרַיִם אֲשֶׁר יָשֹׁד בָּהּ קֶטֶב יְגָרְשׁוּהָ וּתְהִי שְׁדוּדָה. דָּבָר אַחֵר: בַּצָּהֳרַיִם יְגָרְשׁוּהָ – מְקוֹם מִרְעֵה צֹאן הָיָה, וְצָהֳרַיִם קָשֶׁה לָצֵאת בּוֹ צֹאן, וְכֵן הוּא אוֹמֵר: ״אֵיכָה תַּרְבִּיץ בַּצָּהֳרָיִם״ (שיר השירים א:ז).\",2,0],[2,140,2,5,\"חֶבֶל הַיָּם. ״סְפַר יַמָּא״. וּלְשׁוֹן ׳חֶבֶל׳ – מִדַּת הַקַּרְקַע הִיא, שֶׁמּוֹדְדִין בְּחֶבֶל. כְּלוֹמַר הַסְּמוּכִים לַיָּם.\",1,0],[2,140,2,5,\"גּוֹי כְּרֵתִים. תִּרְגֵּם יוֹנָתָן: ״עַמָּא דְמְחֻיָּבִין לְאִשְׁתְּצָאָה״. וּמִי הֵן יוֹשְׁבֵי חֶבֶל הַיָּם? כְּנָעַן אֶרֶץ פְּלִשְׁתִּים, כִּי פְּלִשְׁתִּים יוֹשְׁבִים עַל שְׂפַת הַיָּם הָאַחֲרוֹן בְּמַעֲרָבָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל, בְּתוֹךְ מִצְרֵי תְּחוּמֶיהָ. וְאַף שֶׁדּוֹרְשׁוֹ יוֹנָתָן לְכִלָּיָה, ״גּוֹי כְּרֵתִים״ – מְדִינָה הִיא בַּפְּלִשְׁתִּים וּשְׁמָהּ כְּרֵתִי. וְכֵן הוּא אוֹמֵר בְּצִקְלָג: ״אֲנַחְנוּ פָשַׁטְנוּ עַל נֶגֶב הַכְּרֵתִי וְעַל אֲשֶׁר לִיהוּדָה״ (שמואל א ל:יד), וְתִּרְגֵּם יוֹנָתָן: ״עַל דָּרוֹם כְּרֵתִי״. וּלְמַטָּה כָּתוּב: ״בְּכָל הַשָּׁלָל הַגָּדוֹל אֲשֶׁר לָקְחוּ מֵאֶרֶץ פְּלִשְׁתִּים וּמֵאֶרֶץ יְהוּדָה״ (שם ל:טז).\",2,0],[2,140,2,6,\"נְוֺת כְּרֹת רוֹעִים. נְוֵה עֲרַאי שֶׁיִּכְרוּ בָּהּ הָרוֹעִים לֶחֶם בַּבֹּקֶר. כְּרֹת לְשׁוֹן ״וַיִּכְרֶה לָהֶם כֵּרָה גְדוֹלָה״ (מלכים ב ו:כג).\",1,0],[2,140,2,7,\"וְהָיָה חֶבֶל לִשְׁאֵרִית בֵּית יְהוּדָה. וְהָיָה אוֹתוֹ הַגְּבוּל גּוֹרָל לִשְׁאֵרִית בְּנֵי יְהוּדָה. חֶבֶל זֶה לְשׁוֹן ׳גּוֹרָל׳ הוּא, וְכֵן תִּרְגֵּם יוֹנָתָן: ״וִיהֵי עַדְבָּא לִשְׁאָרָא דְבֵית יְהוּדָה״.\",1,0],[2,140,2,8,\"אֲשֶׁר חֵרְפוּ אֶת עַמִּי. כְּשֶׁהָיוּ מוֹלִיכִין יִשְׂרָאֵל בַּגּוֹלָה לְצַד אֶרֶץ כַּשְׂדִּים, וְהָיוּ עוֹבְרִין דֶּרֶךְ עַמּוֹן וּמוֹאָב, וְרוֹאִים יִשְׂרָאֵל בּוֹכִים וְגוֹנְחִים וְצוֹעֲקִין, הָיוּ מוֹנִין אוֹתָן וְאוֹמְרִים: מַה לָּכֶם לִהְיוֹת סְגוּפִים? מַה תִּבְכּוּ? הֲלֹא לְבֵית אֲבִיכֶם אַתֶּם הוֹלְכִים – ״בְּעֵבֶר הַנָּהָר יָשְׁבוּ אֲבוֹתֵיכֶם מֵעוֹלָם״ (יהושע כד:ב).\",1,0],[2,140,2,8,\"וַיַּגְדִּילוּ עַל גְּבוּלָם. וַיִּתְגָּאוּ עַל גְּבוּלָם.\",2,0],[2,140,2,9,\"כִּי מוֹאָב כִּסְדֹם תִּהְיֶה. גַּם אַתֶּם לְקַדְמַתְכֶם תָּשׁוּבוּ. לוֹט אֲבִיכֶם לֹא מִסְּדוֹם הָיָה?\",1,0],[2,140,2,9,\"מִמְשַׁק חָרוּל. הַשְׁמָעַת קוֹל, כְּמוֹ ״מַשַּׁק גֵּבִים״ (ישעיהו לג:ד). וְאַף מֵ״ם הָרִאשׁוֹנָה יְסוֹד הִיא בַּתֵּבָה, כְּמוֹ ״מִמְשַׁח הַסּוֹכֵךְ״ (יחזקאל כח:יד). ״מִמְשַׁק חָרוּל״ – הַשְׁמָעַת קוֹל חֲרוּלִים הַגְּדֵלִים שָׁם מֵאֵין עוֹבֵר, וְהֵן נוֹקְשִׁין זוֹ עַל זוֹ וּמַשְׁמִיעוֹת קוֹל.\",2,0],[2,140,2,9,\"וּמִכְרֵה מֶלַח. מְקוֹם כְּרִיַּת מֶלַח.\",3,0],[2,140,2,11,\"כִּי רָזָה. הִתִּישׁ כֹּחָם.\",1,0],[2,140,2,11,\"וְיִשְׁתַּחֲווּ לוֹ. כְּשֶׁיִּרְאוּ שֶׁנִּתְקַלְקְלוּ יִרְאָתָן.\",2,0],[2,140,2,12,\"גַּם אַתֶּם כּוּשִׁים. כְּשֶׁגָּלוּ שָׁם יִשְׂרָאֵל מֵעֵבֶר לְנַהֲרֵי כּוּשׁ.\",1,0],[2,140,2,13,\"עַל צָפוֹן. אַשּׁוּר בַּצָּפוֹן אֵצֶל בָּבֶל.\",1,0],[2,140,2,13,\"נִינְוֵה. הוּא רֹאשׁ לְאַשּׁוּר.\",2,0],[2,140,2,14,\"כָּל חַיְתוֹ גוֹי. כָּל בֶּהֱמוֹת הַגּוֹיִם.\",1,0],[2,140,2,14,\"קָאַת וְקִפֹּד. עוֹפוֹת.\",2,0],[2,140,2,14,\"בְּכַפְתּוֹרֶיהָ. פומל״ש שֶׁבְּרֹאשׁ הַגָּג.\",3,0],[2,140,2,14,\"חֹרֶב בַּסַּף. הַחֻרְבָּן יִהְיֶה נִכָּר בְּסִפֵּי הַבַּיִת.\",4,0],[2,140,2,14,\"קוֹל יְשׁוֹרֵר בַּחַלּוֹן. קוֹל הָעוֹפוֹת מְצַפְצְפִים בַּחֲלוֹנוֹת.\",5,0],[2,140,2,14,\"כִּי אַרְזָה עֵרָה. כִּי אֲרָזֶיהָ עִקֵּר וְשֵׁרַשׁ, כְּמוֹ ״עָרוּ עָרוּ״ (תהלים קלז:ז). וְיוֹנָתָן תִּרְגֵּם: ״וְטַלְלָהּ סָתְרוּ״ – הוּא גַּג הַבַּיִת הַסָּפוּן בְּאֶרֶז, שֶׁאֲפִלּוּ בָּתֵּי אֲבָנִים מְסַכְּכִין בִּנְסָרִים שֶׁל עֵץ.\",6,0],[2,140,2,15,\"וְאַפְסִי. וְאֶפֶס זוּלָתִי.\",1,0],[2,140,3,1,\"הוֹי מֹרְאָה וְנִגְאָלָה. עַד עַכְשָׁיו דִּבֵּר בְּנִינְוֵה, וְעַכְשָׁיו חוֹזֵר עַל יְרוּשָׁלַיִם: הוֹי, שֶׁתְּהֵא לְבַז וּלְסְחִי כְּרֹאִי, וּתְהֵא מְגֹאֶלֶת בִּצְחַן עֲוֹנָהּ. מֹרְאָה – כְּמוֹ ״מֻרְאָתוֹ״ (ויקרא א:טז), ״וְשַׂמְתִּיךְ כְּרֹאִי״ (נחום ג:ו).\",1,0],[2,140,3,1,\"הָעִיר הַיּוֹנָה. כְּיוֹנָה פּוֹתָה אֵין לֵב.\",2,0],[2,140,3,3,\"זְאֵבֵי עֶרֶב. הַמְּמַהֲרִים לֶאֱכֹל טַרְפָּם בַּלַּיְלָה.\",1,0],[2,140,3,3,\"לֹא גָרְמוּ לַבֹּקֶר. לֹא הִשְׁאִירוּ אַף הָעֲצָמוֹת לִגְרֹם לַבֹּקֶר.\",2,0],[2,140,3,4,\"חָמְסוּ תּוֹרָה. לֹא הוֹרוּ אוֹתָהּ לְשׁוֹאֲלֵיהֶם.\",1,0],[2,140,3,5,\"ה׳ צַדִּיק. הִשְׁרָה שְׁכִינָתוֹ בְּקִרְבָּם, וּלְפִיכָךְ אֵינוֹ יָכוֹל לִרְאוֹת בְּמַעֲשֵׂיהֶם הָרָעִים, כִּי צַדִּיק הוּא וְאֵין עַוְלָה לְפָנָיו.\",1,0],[2,140,3,5,\"מִשְׁפָּטוֹ יִתֵּן לָאוֹר. נוֹתֵן לָאוֹר, דָּן דִּין אֱמֶת לַאֲמִתּוֹ.\",2,0],[2,140,3,5,\"וְלֹא יוֹדֵעַ עַוָּל בֹּשֶׁת. וְכָל זֶה לֹא נָתְנוּ שׁוֹפְטֵי עָוֶל שֶׁבְּתוֹכָהּ אֶל לִבָּם לְהִתְבַּיֵּשׁ מִן הַצַּדִּיק הַשּׁוֹכֵן בֵּינֵיהֶם.\",3,0],[2,140,3,6,\"הִכְרַתִּי גוֹיִם. הֵבֵאתִי פֻּרְעָנוּת עַל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת כְּדֵי שֶׁתִּרְאוּ וְתִירָאוּ, כְּמוֹ שֶׁהוּא מְסַיֵּם וְהוֹלֵךְ: ״אָמַרְתִּי אַךְ תִּירְאִי אוֹתִי״.\",1,0],[2,140,3,7,\"וְלֹא יִכָּרֵת מְעוֹנָהּ. וְלֹא יֶחֶרְבוּן מְדוֹרֶיהָ.\",1,0],[2,140,3,7,\"כָּל אֲשֶׁר פָּקַדְתִּי עָלֶיהָ. וְלֹא יִכָּרֵת מִמֶּנּוּ כָּל הַטּוֹב אֲשֶׁר צִוִּיתִי לְהָבִיא עָלֶיהָ.\",2,0],[2,140,3,8,\"קוּמִי לְעַד. שֶׁאָקוּם לְהִתְוַעֵד עֲלֵיכֶם.\",1,0],[2,140,3,10,\"מֵעֵבֶר לְנַהֲרֵי כוּשׁ. יוֹבִילוּן לִי מִנְחָה.\",1,0],[2,140,3,10,\"עֲתָרַי. אֶת הַמִּתְפַּלְּלִין אֵלַי.\",2,0],[2,140,3,10,\"בַּת פּוּצַי. כְּנֵסִיּוֹת נְפוּצוֹתַי אֲשֶׁר הֲפִיצוֹתִי.\",3,0],[2,140,3,11,\"לֹא תֵבוֹשִׁי מִכָּל עֲלִילוֹתַיִךְ. כִּי כְּבָר לָקִית וְנִרְצָה עֲוֹנֵךְ.\",1,0],[2,140,3,12,\"עַם עָנִי וָדָל. עַם עַנְוְתָן וּמְקַבֵּל עֻלְבָּן.\",1,0],[2,140,3,15,\"מִשְׁפָּטַיִךְ. יִסּוּרֶיךְ, יושטיצ״א בְּלַעַ״ז.\",1,0],[2,140,3,17,\"גִּבּוֹר יוֹשִׁיעַ. גִּבּוֹר הוּא אֲשֶׁר יוֹשִׁיעַ מִן הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת.\",1,0],[2,140,3,17,\"יַחֲרִישׁ בְּאַהֲבָתוֹ. יְכַסֶּה עַל פְּשָׁעֶיךָ בְּאַהֲבָתוֹ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״יִכְבּוֹשׁ עַל חוֹבֵךְ בְּרַחֲמָתֵיהּ״.\",2,0],[2,140,3,18,\"נוּגֵי מִמּוֹעֵד. אָסַפְתִּי אֶת הַמּוּצָאִים מִמּוֹעֲדֵי, שֶׁלֹּא הָיוּ מְשַׁמְּרִים שַׁבָּתוֹת וְיָמִים טוֹבִים.\",1,0],[2,140,3,18,\"אָסַפְתִּי. כִּלִּיתִי.\",2,0],[2,140,3,18,\"מִמֵּךְ הָיוּ. מֵעַמֵּךְ הָיוּ.\",3,0],[2,140,3,18,\"מַשְׂאֵת עָלֶיהָ חֶרְפָּה. עַל אוֹתָהּ אַשְׁמָה הָיָה לָךְ מַשְׂאֵת חֶרְפָּה.\",4,0],[2,140,3,18,\"נוּגֵי. לְשׁוֹן ׳הוֹצָאָה׳, כְּמוֹ ״הָגוֹ סִיגִים״ (משלי כה:ד), ״כַּאֲשֶׁר הוּגָה מִן הַמְּסִלָּה״ (שמואל ב כ:יג). וְאֵין שֹׁרֶשׁ בַּתֵּבָה אֶלָּא הַגִּימֶ״ל לְבַדָּהּ.\",5,0],[2,140,3,19,\"הִנְנִי עֹשֶׂה. תִּרְגֵּם יוֹנָתָן: ״הָא אֲנָא עָבֵיד גְּמִירָא״. וְיֵשׁ לְפוֹתְרוֹ לְשׁוֹן ׳עִ׳שּׂוּי׳, כְּמוֹ ״וְעַסּוֹתֶם רְשָׁעִים״ (מלאכי ג:כא).\",1,0],[2,140,3,19,\"בְּכָל הָאָרֶץ בָּשְׁתָּם. בְּכָל מָקוֹם אֲשֶׁר הָיוּ שָׁם לְבָשְׁתָּם, שָׁם אֶתְּנֵם לְשֵׁם וְלִתְהִלָּה.\",2,0],[4,141,1,1,\"פִּתְגָמֵי עָמוֹס דַהֲוָה מָרֵי גִתִּין מִתְּקוֹעַ דְאִתְנַבֵּי עַל יִשְׂרָאֵל בְּיוֹמֵי עֻזִיָה מְלַךְ שִׁבְטָא דְבֵית יְהוּדָה וּבְיוֹמֵי יָרָבְעָם בַּר יוֹאָשׁ מַלְכָּא דְיִשְׂרָאֵל תַּרְתֵּין שְׁנִין קֳדָם מֵיתֵי זִיעָא:\",0,0],[4,141,1,2,\"וַאֲמַר יְיָ מִצִיוֹן יִכְלֵי וּמִירוּשְׁלֵם יָרִים מֵימְרֵיהּ וְיִצְדוּן מָדוֹרֵי מַלְכַיָא וְיֶחֱרַב תְּקוֹף כְּרַכֵּיהוֹן:\",0,0],[4,141,1,3,\"כִּדְנַן אֲמַר יְיָ עַל תְּלָתָא חוֹבֵי דַמֶשֶׂק וְעַל אַרְבְּעָה לָא אֶשְׁבּוֹק לְהוֹן עַל דְדָשׁוּ בְמוֹרִגֵי בַרְזְלָא יַת יַתְבֵי אֲרַע גִלְעָד:\",0,0],[4,141,1,4,\"וְאַשְׁלַח אֶשְׁתָּא בְבֵית חֲזָאֵל וּתְשֵׁיצֵי בִּרְנְיַת בַּר הֲדָד:\",0,0],[4,141,1,5,\"וְאֶתְּבַר תְּקוֹף דַמֶשֶׂק וֶאֱשֵׁיצֵי יָתֵיב מִבִּקְעַת אָוֶן וְעָבֵיד שׁוּלְטַן מִבֵּית עֶדֶן וְיִגְלוּן עַמָא דַאֲרָם לְקִירְנֵי אֲמַר יְיָ:\",0,0],[4,141,1,6,\"כִּדְנַן אֲמַר יְיָ עַל תְּלָתָא חוֹבֵי עַזָה וְעַל אַרְבְּעָה לָא אֶשְׁבּוֹק לְהוֹן עַל דְאַגְלִיאוּנוּן גָלוּ שְׁלֵמָא לְמִמְסַר לֶאֱדוֹם:\",0,0],[4,141,1,7,\"וְאֶשְׁלַח אֶשְׁתָּא בְּשׁוּרֵי עַזָה וּתְשֵׁיצֵי בִּרְנְיָתָהָא:\",0,0],[4,141,1,8,\"וָאֳשֵׁיצֵי יָתֵיב מֵאַשְׁדוֹד וְעָבֵיד שׁוּלְטַן מֵאַשְׁקְלוֹן וְאָתִיב מְחַת גְבוּרְתִּי עַל עֶקְרוֹן וְיֵיבְדוּן שְׁאָרָא דִפְלִשְׁתָּאֵי אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,141,1,9,\"כִּדְנַן אֲמַר יְיָ עַל תְּלָתָא חוֹבֵי צוֹר וְעַל אַרְבְּעָא לָא אֶשְׁבּוֹק לְהוֹן עַל דְמַסְרִינוּן גָלוּ שְׁלֵימָא לֶאֱדוֹם וְלָא אִידְכָּרוּ קִיֵם אַחִין:\",0,0],[4,141,1,10,\"וְאֶשְׁלַח אֶשְׁתָּא בְשׁוּרֵי צוֹר וּתְשֵׁיצֵי בִּרְנְיָתָהָא:\",0,0],[4,141,1,11,\"כִּדְנַן אֲמַר יְיָ עַל תְּלָתָא חוֹבֵי אֱדוֹם וְעַל אַרְבְּעָא לָא אֶשְׁבּוֹק לְהוֹן עַל רָדְפֵיהּ בְּחַרְבָּא אֲחוּהִי וְחַבֵּיל רַחֲמוֹהִי וּקְטֵיל קְטַל עַלְמִין רוּגְזֵיהּ וְחַמְתֵיהּ נָטְרָא לְאַפְרָשׁ:\",0,0],[4,141,1,12,\"וְאֶשְׁלַח אֶשְׁתָּא בְּדָרוֹמָא וּתְשֵׁיצֵי בִּרְנְיַת בָּצְרָה:\",0,0],[4,141,1,13,\"כִּדְנַן אֲמַר יְיָ עַל תְּלָתָא חוֹבֵי בְנֵי עַמוֹן וְעַל אַרְבְּעָא לָא אֶשְׁבּוֹק לְהוֹן עַל דְבַזָעוּ מַעְדְיַת אֲרַע גִלְעָד בְּדִיל לְאַפְתָּאָה יַת תְּחוּמֵיהוֹן:\",0,0],[4,141,1,14,\"וְאַדְלֵיק אֶשְׁתָּא בְּשׁוּרֵי רַבָּה וּתְשֵׁיצֵי בִּרְנְיָתָהָא בְּיַבָּבָא בְּיוֹמָא דִקְרָבָא בְּעַלְעוֹל בְּיוֹם רוּח:\",0,0],[4,141,1,15,\"וִיהַךְ מַלְכֵּהוֹן בְּגָלוּתָא הוּא וְרַבְרְבוֹהִי כַּחֲדָא אֲמַר יְיָ:\",0,0],[4,141,2,1,\"כִּדְנַן אֲמַר יְיָ עַל תְּלָתָא חוֹבֵי מוֹאָב וְעַל אַרְבְּעָה לָא אֶשְׁבּוֹק לְהוֹן עַל דְאוֹקִיד גַרְמֵי מַלְכָּא דֶאֱדוֹם וְסָדִינוּן כְּגִירָא בְּבֵיתָא:\",0,0],[4,141,2,2,\"וְאֶשְׁלַח אֶשְׁתָּא בְּמוֹאָב וּתְשֵׁיצֵי בִּרְנְיָת כְּרַכָּא וִימוּת בְּאִתְרְגוּשָׁא מוֹאָב בְּיַבָּבָא בְּקַל שׁוֹפָרָא:\",0,0],[4,141,2,3,\"וָאֱשֵׁיצֵי דַיְנָהָא מִגַוָהּ וְכָל רַבְרְבָהָא אֶקְטוֹל עִמֵיהּ אֲמַר יְיָ:\",0,0],[4,141,2,4,\"כִּדְנַן אֲמַר יְיָ עַל תְּלָתָא חוֹבֵי יְהוּדָה וְעַל אַרְבְּעָה לָא אֶשְׁבּוֹק לְהוֹן עַל דְקָצוּ בְאוֹרַיְתָא דַייָ וּקְיָמוֹהִי לָא נְטָרוּ וְאַטְעִיאוּנוּן כַּדְבֵּיהוֹן דְהַלִיכוּ אֲבָהָתְכוֹן בַּתְרֵיהוֹן:\",0,0],[4,141,2,5,\"וְאֶשְׁלַח אֶשְׁתָּא בִּדְבֵית יְהוּדָה וּתְשֵׁיצֵי בִּרְנְיָת יְרוּשְׁלֵם:\",0,0],[4,141,2,6,\"כִּדְנַן אֲמַר יְיָ עַל תְּלָתָא חוֹבֵי יִשְׂרָאֵל וְעַל אַרְבְּעָא לָא אֶשְׁבּוֹק לְהוֹן עַד דְזַבִּינוּ בְּכַסְפָּא זַכָּאִין וַחֲשִׁיכַיָא בְּדִיל דְיַחֲסְנוּן:\",0,0],[4,141,2,7,\"דְשַׁיְטִין בְּעַפְרָא דְאַרְעָא בְּרֵישׁ מַסְכֵּינָא וְדִין חֲשִׁיכַיָא מַסְטָן וּגְבַר וְאָבוּהִי אָזְלִין עַל עוּלֶמְתָּא בְּדִיל לְאַחְלָא יַת שְׁמָא דְקוּדְשִׁי:\",0,0],[4,141,2,8,\"וְעַל שַׁוְיָן דְמַשְׁכּוֹן מְסַחֲרִין בִּסְטַר כָּל אֱגוֹרֵיהוֹן וַחֲמַר אוֹנָסָא שָׁתָן בֵּית טַעֲוַתְהוֹן:\",0,0],[4,141,2,9,\"וַאֲנָא שֵׁיצֵיתִי יַת אֱמוֹרָהָא מִן קֳדָמֵיהוֹן דִכְרוּם אֲרָזִין רוֹמֵיהּ וַחֲסִין הוּא כִּבְלוּטִין וְשֵׁיצֵיתִי אִבֵּיהּ מִלְעֵילָא וְשָׁרָשׁוֹהִי מִלְרָע:\",0,0],[4,141,2,10,\"וַאֲנָא אַסְקֵית יַתְכוֹן מֵאַרְעָא דְמִצְרָיִם וְדַבְּרֵית יַתְכוֹן בְּמַדְבְּרָא אַרְבְּעִין שְׁנִין לְמֵירַת יַת אַרְעָא דֶאֱמוֹרָאָה:\",0,0],[4,141,2,11,\"וַאֲקִימֵית מִבְּנֵיכוֹן לִנְבִיאִין וּמֵעוּלֵימֵיכוֹן לְמַלְפִין הַאַף לֵית דָא בְּנֵי יִשְׂרָאֵל אֲמַר יְיָ:\",0,0],[4,141,2,12,\"וְאַטְעִיתוּן יַת מַלְפֵיכוֹן בְּחַמְרָא וְעַל נְבִיַיָא פַּקֵידְתּוּן לְמֵימַר לָא תִתְנַבּוּן נְבוּאָה:\",0,0],[4,141,2,13,\"הָא אֲנָא מַיְתֵי עֲלֵיכוֹן עָקָא וּמָעִיק לְכוֹן בְּאַתְרְכוֹן כְּמָא דְעַיְקָא עֶגְלָתָא דִטְעִינָא עֲמִירָא:\",0,0],[4,141,2,14,\"וְיֵבַד בֵּית עֵיקוּקֵי מִדְקַלִיל וּדְתַקִיף לָא יַחֲסִין חֵילֵיהּ וְגִבַּר לָא יְשֵׁיזֵיב נַפְשֵׁיהּ:\",0,0],[4,141,2,15,\"וַאֲחִיד קַשְׁתָּא לָא יְקוּם וּדְקַלִיל בְּרִגְלֵיה לָא יִשְׁתֵּיזֵיב וּרְכִיב סוּסַיָא לָא יְשֵׁיזֵיב נַפְשֵׁיהּ:\",0,0],[4,141,2,16,\"וּדְתַקִיף לִבֵּיהּ בְּגִבָּרַיָא עַרְטִילָא דְלָא זְיַן יַעֲרוֹק בְּיוֹמָא הַהוּא אֲמַר יְיָ:\",0,0],[4,141,3,1,\"קַבִּילוּ יַת פִּתְגָמָא הָדֵין דִי גְזַר יְיָ עֲלֵיכוֹן בֵּית יִשְׂרָאֵל עַל כָּל זַרְעֲיָתָא דְאַסְקִית מֵאַרְעָא דְמִצְרַיִם לְמֵימָר:\",0,0],[4,141,3,2,\"לְחוֹד בְּכוֹן אִתְרְעֵיתִי מִכָּל זַרְעֲיַת אַרְעָא עַל כֵּן אַסְעַר עֲלֵיכוֹן יַת כָּל חוֹבֵיכוֹן:\",0,0],[4,141,3,3,\"הֲיַהֲכוּן תְּרֵין כַּחֲדָא אֱלָהֵין אִם אִזְדַמָנוּ:\",0,0],[4,141,3,4,\"הֲיִנְהוֹם אַרְיֵה בְּחוּרְשָׁה וְצֵידָה לֵית לֵיהּ הַיְרִים בַּר אַרְיְוָן קָלֵיהּ מִמַרְבּוּעָתֵיהּ אֱלָהֵין אִם אֲחָד:\",0,0],[4,141,3,5,\"הֲתִפּוֹל צִפְּרָא בְּקוּלָא עַל אַרְעָא וְצַיִד לֵית לֵיהּ הֲיִסַק קוּלָא מִן אַרְעָא וּמֵחַד לָא אֲחָד:\",0,0],[4,141,3,6,\"אִם יִתְקַע שׁוֹפָרָא בְּקַרְתָּא בְּלָא זִמְנֵיהּ וְעַמָא דִי בָהּ לָא יְזוּעוּן אִם תְּהֵי בִישְׁתָא בְּקַרְתָּא וּמִן קֳדָם יְיָ לָא אִתְעַבְּדָת:\",0,0],[4,141,3,7,\"אֲרֵי לָא כָשְׁרִין פִּתְגָמִין דְמִתְעַבְּדִין מִן קֳדָם יְיָ אֱלֹהִים אֱלָהִין גְלָא רָזֵיהּ לְעַבְדוֹהִי נְבִיַיָא:\",0,0],[4,141,3,8,\"אַרְיֵה נָהֵים מַן לָא יִדְחַל יְיָ אֱלֹהִים מַלֵיל מַן לָא יְקַבֵּיל נְבוּאֲתָא:\",0,0],[4,141,3,9,\"בַּסָרוּ עַל בִּרְנְיָת בְּאַשְׁדוֹד וְעַל בִּרְנְיָת בְּאַרְעָא דְמִצְרָיִם וַאֲמָרוּ אִתְכְּנָשׁוּ עַל טוּרֵי שֹׁמְרוֹן וַחֲזוֹ שִׁגוֹשַׁיָא סַגִיאָן בְּגַוָהּ וַאֲנוּסִין בְּגַוָהּ:\",0,0],[4,141,3,10,\"וְלָא יָדְעִין לְמֶעְבַּד אוֹרַיְתָא אֲמַר יְיָ דִי מָלָן אוֹצְרֵיהוֹן חֲטוֹף וּבִזָא בְּבִרְנְיָתְהוֹן:\",0,0],[4,141,3,11,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים עָקָא תַּקִיפָא לְאַרְעָא וְיִבָּטֵיל מִנִיךְ תּוֹקְפֵיךְ וְיִתְבַּזוּן בִּרְנְיָתָיִךְ:\",0,0],[4,141,3,12,\"כִּדְנַן אֲמַר יְיָ כְּמָא דִמְשֵׁיזֵיב רַעֲיָא מִפּוּמָא דְאַרְיָא תַּרְתֵּין כַּרְעִין אוֹ חַסְחוֹס דְאוֹדָן כֵּן יִשְׁתֵּיזְבוּן בְּנֵי יִשְׂרָאֵל דְיָתְבִין בְּשֹׁמְרוֹן בִּתְקוֹף שׁוּלְטַן וְעַל דַמֶשֶׂק רְחִיצִין:\",0,0],[4,141,3,13,\"קַבִּילוּ וְאַסְהִידוּ בְּבֵית יַעֲקֹב אֲמַר יְיָ אֱלֹהִים אֱלֹהֵי צְבָאוֹת:\",0,0],[4,141,3,14,\"אֲרֵי בְּיוֹם אַסְעֲרוּתִי חוֹבֵי יִשְׂרָאֵל עֲלוֹהִי וְאַסְעַר עַל דְפָלְחִין לֶאֱגוֹרַיָא בְּבֵית אֵל וְיִתְקַטְפָן קַרְנַת אֱגוֹרָא וְיִפְּלוּן לְאַרְעָא:\",0,0],[4,141,3,15,\"וְאֶמְחֵי בֵּית סִתְוָא עַל בֵּית קַיְטָא וְיֵיבְדוּן בָּתִּין דִמְכַבְּשִׁין בְּשֵׁן דְפִיל וִיסוּפוּן בָּתִּין סַגִיאִין אֲמַר יְיָ:\",0,0],[4,141,4,1,\"קַבִּילוּ פִּתְגָמָא הָדֵין עַתִּירֵי נִכְסַיָא דִבְטוּרָא דְשֹׁמְרוֹן דְעָשְׁקִין מִסְכֵּינַיָא וְאָנְסִין חֲשִׁיכַיָא דְאָמְרִין לְרִבּוֹנֵיהוֹן אַשְׁלְטוּנָא וְנִבַּז:\",0,0],[4,141,4,2,\"קַיָם יְיָ אֱלֹהִים בְּמֵימְרֵיהּ בְּקוּדְשֵׁיה אֲרֵי הָא יוֹמַיָא אֶתָן עֲלֵיכוֹן וְיִטְלוּן יַתְכוֹן עַמְמַיָא עַל תְּרֵיסְהוּן וּבְנַתְכוֹן בְּדוּגִית צָיְדִין:\",0,0],[4,141,4,3,\"וְיִתָרְעוּן עֲלֵיהוֹן שׁוּרָא וְיִפְקוּן יַתְכוֹן כְּנִישִׁין גְבַר לְקִבְלֵיהּ וְיִגְלוֹן יַתְהוֹן לְהָלְאָה מִן טוּרֵי חַרְמִינֵי אֲמַר יְיָ:\",0,0],[4,141,4,4,\"אֱתוֹ לְבֵית אֵל וּמְרָדוּ בְּגִלְגָלָא אַסְגִיאוּ לְמֶחֱטֵי וּמַיְתָן לְצַפְרָא דִבְחֵיכוֹן לִתְלָתָא יוֹמִין מַעֲסַרְתְּכוֹן:\",0,0],[4,141,4,5,\"וּמַגְבַן מִן אוֹנֶס תּוֹדָתָא וּמַיְתָן לֵיהּ בִּזְמַר וְאָמְרִין דֵין לְרַעֲוָא אֲרֵי כֵן רְחִמְתּוּן בֵּית יִשְׂרָאֵל אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,141,4,6,\"וְאַף אֲנָא יְהָבִית לְכוֹן אַקְהָיוּת שְׁנִין בְּכָל קִרְוֵיכוֹן וַחֲסֵירוּת מָזוֹן בְּכָל אַתְרֵיכוֹן וְלָא תַבְתּוּן לְפוּלְחָנִי אֲמַר יְיָ:\",0,0],[4,141,4,7,\"וְאַף אֲנָא מְנָעִית מִנְכוֹן יַת מִטְרָא בְּסוֹף תְּלָתָא יַרְחִין לִזְמַן חַצְדָא וְאָחֵית מִטְרָא עַל קַרְתָּא חֲדָא וְעַל קַרְתָּא חֲדָא לָא אָחֵית מִטְרָא אַחֲסָנְתָּא חֲדָא יֵחוֹת עֲלָהּ מִטְרָא וְאַחֲסַנְתָּא דְלָא יֵחוֹת עֲלָהּ מִטְרָא תִּיבָשׁ:\",0,0],[4,141,4,8,\"וְיִשְׁתַּלְהוּן תַּרְתֵּין תְּלַת קִרְוִין לְקַרְתָּא חֲדָא לְמִשְׁתֵּי מַיָא וְלָא יִסְבְּעוּן וְלָא תַבְתּוּן לְפוּלְחָנִי אֲמַר יְיָ:\",0,0],[4,141,4,9,\"מְחִיתִי יַתְכוֹן בְּשִׁדְפָנָא וּבְיַרְקָנָא סַגְיוּת גַנֵיכוֹן וְכַרְמֵיכוֹן וְתֵינֵיכוֹן וְזֵיתֵיכוֹן אָכְלָא זַחֲלָא וְלָא תַבְתּוּן לְפוְּלְחָנִי אֲמַר יְיָ:\",0,0],[4,141,4,10,\"שְׁלָחֵית בְּכוֹן מוֹתָא כַּד בְּאוֹרַח מִצְרַיִם קְטָלֵית בְּחַרְבָּא עוּלֵימֵיכוֹן עִם שְׁבִי סוּסְוַתְכוֹן וְאַסְקֵית סְרוּת מַשִׁרְיָתֵיכוֹן וּבְאַפֵּיכוֹן וְלָא תַבְתּוּן לְפוּלְחָנִי אֲמַר יְיָ:\",0,0],[4,141,4,11,\"רָחֵיק מֵימְרִי יַתְכוֹן כְּמָא דְרָחֵיק יְיָ יַת סְדוֹם וְיַת עֲמוֹרָה וַהֲוֵיתוּן כְּאוּד מְשֵׁיזֵיב מִיְקִידָא וְלָא תַבְתּוּן לְפוּלְחָנִי אֲמַר יְיָ:\",0,0],[4,141,4,12,\"בְּכֵן מָה אַעְבֵּיד לָךְ יִשְׂרָאֵל חֲלַף דְלָא תַבְתְּ לְאוֹרַיְתָא דָא אַעְבֵּיד לָךְ אִתְקַשֵׁיט לְקַבָּלָא אוּלְפַן אוֹרַיְתָא דֶאֱלָהָךְ יִשְׂרָאֵל:\",0,0],[4,141,4,13,\"אֲרֵי הָא מִתְגְלֵי דִיצַר טוּרַיָא וּבְרָא רוּחָא לְחַוָאָה לֶאֱנָשָׁא מָה עוֹבָדוֹהִי לְאִתְקְנָאָה נְהוֹר לְצַדִיקַיָא כִּנְהוֹר טוּרַיָא דַאֲזִיל וְתַקֵין לְאַיְתָאָה חֲשׁוֹךְ לְרַשִׁעַיָא לְמִתְבַּר רַשִׁיעֵי אַרְעָא יְיָ אֱלֹהֵי צְבָאוֹת שְׁמֵיהּ:\",0,0],[4,141,5,1,\"קַבִּילוּ יַת פִּתְגְמָא הָדֵין דִי אֲנָא נְטֵיל עֲלֵיכוֹן אִילְיָא בֵּית יִשְׂרָאֵל:\",0,0],[4,141,5,2,\"נָפְלָת לָא תוֹסִיף לְמֵיקָם שַׁתָּא הָדָא כְּנִשְׁתָּא דְיִשְׂרָאֵל אִתְרְטִישַׁת עַל אַרְעָא לֵית דִיקַיְמִינָהּ:\",0,0],[4,141,5,3,\"אֲרֵי כִדְנַן אֲמַר יְיָ אֱלֹהִים קַרְתָּא דְיִפְקוּן מִנָהּ אַלְפָא יִשְׁתָּאֲרוּן בָּה מְאָה וּדְיִפְקוּן מִנָה מְאָה יִשְׁתָּאֲרוּן בָּהּ עַד עַסְרָא לְבֵית יִשְׂרָאֵל:\",0,0],[4,141,5,4,\"אֲרֵי כִדְנַן אֲמַר יְיָ לְבֵית יִשְׂרָאֵל תְּבָעוּ דְחַלְתִּי וְאִתְקַיָמוּ:\",0,0],[4,141,5,5,\"וְלָא תִתְבְּעוּן לְמֵיהַךְ לְבֵית אֵל וּלְגִלְגָלָא לָא תֵיתוּן וְלִבְאֵר שָׁבַע לָא תֶעְבְּרוּן אֲרֵי דִי בְּגִלְגָלָא מִגְלָא יִגְלוּן וּדְפָלְחִין לְטַעֲוָתָא בְּבֵית אֵל יְהוֹן לִלְמָא:\",0,0],[4,141,5,6,\"תְּבָעוּ יַת דַחַלְתָּא דַייָ וְאִתְקַיָמוּ דִלְמָא יִדְלַק כְּאֶשְׁתָּא רוּגְזֵיהּ בְּבֵית יוֹסֵף וִישֵׁיצֵיהּ וְלָא יְהֵי חָיַס בְּחוֹבִין דַהֲוֵיתוּן פָּלְחִין לְטַעֲוָתָא בְּבֵית אֵל:\",0,0],[4,141,5,7,\"דְהָפְכִין לְגִידָה דִינָא וּזְכוּתָא לְאַרְעָא רָטָשׁוּ:\",0,0],[4,141,5,8,\"שְׁבָקוּ לְמִדְחַל מִן קֳדָם דַעֲבַד כִּימָה וּכְסִילָא וְהָפֵךְ לִנְהוֹר קָבֵל וִימָם וְלֵילֵי מַקְבֵּיל דַאֲמַר לְכַנָשָׁא מַשִׁרְיָן סַגִיאָן כְּמֵי יַמָא וּמְבַדַר לְהוֹן עַל אַפִּי אַרְעָא יְיָ שְׁמֵיהּ:\",0,0],[4,141,5,9,\"דְמִגַבַּר חֲלָשִׁין עַל תַּקִיפִין וּבְזִיזִין עַל כְּרַכֵּי תַּקִיפִין מַשְׁלִיט:\",0,0],[4,141,5,10,\"סְנָן לִדְמוֹכַח לְהוֹן בְּשַׁעֲרֵי בָתֵּי דִינָא פִּתְגָמֵי אוֹרַיְתָא וְלִדְמַלֵיל כֵּיוַנְתָּא מְעַקְמִין:\",0,0],[4,141,5,11,\"בְּכֵן חֲלַף בְּמִבִּזְכוֹן מִסְכֵּנַיָא וּמְנַסְכוֹן חֲשִׁיכַיָא בָתֵּי גְזִית בְּנִיתוּן וְלָא תֵיתְבוּן בְּהוֹן כַּרְמֵי חֶמְדָתָא נְצִבְתּוּן וְלָא תִשְׁתּוּן יַת חַמְרְהוֹן:\",0,0],[4,141,5,12,\"אֲרֵי גְלֵי קֳדָמַי דְסַגִיאִין מֵירְדֵיכוֹן וְתַקִיפָן חוֹבָתֵיכוֹן מְעִיקִין לֵיהּ לְזַכָּאָה בְּדִיל לְקַבָּלָא מָמוֹן דִשְׁקַר וְדִין חֲשִׁיכַיָא בְּבֵית כְּנִישְׁתֵּיהִוֹן מַסְטָן:\",0,0],[4,141,5,13,\"בְּכֵן מַלְפַיָא בְּעִדָנָא הַהִיא מִן קֳדָם רַשִׁיעַיָא שְׁתִיקוּ אֲרֵי עִדָן בִּישׁ הוּא:\",0,0],[4,141,5,14,\"תְּבָעוּ לְאוֹטָבָא וְלָא לְאַבְאָשָׁא בְּדִיל דְתִתְקַיְמוּן וִיהֵי כְעַן מֵימְרָא דַייָ אֱלֹהִים צְבָאוֹת בְּסַעְדְכוֹן כְּמָא דַאֲמַרְתּוּן:\",0,0],[4,141,5,15,\"סְגוּ לְאַבְאָשָׁא וְרִיחֲמוּ לְאַיְטָבָא וְאַתְקִינוּ בְּבֵית כְּנִישַׁתְכוֹן דִינָא מָאִים יִתְרַחֵם מִן קֳדָם יְיָ אֱלָהָא צְבָאוֹת עַל שְׁאָרָא דְיוֹסֵף:\",0,0],[4,141,5,16,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהֵי צְבָאוֹת יְיָ בְּכָל רְחוֹבַיָא מִסְפְּדָא וּבְכָל שׁוּקַיָא יֵימְרוּן וַי וַי וִיעָרְעוּן אִכָּר לְאֵבָל וְעָבַד מִסְפְּדָא לִדְיָרְעֵי אִלְיָא:\",0,0],[4,141,5,17,\"וּבְכָל כַּרְמַיָא מִסְפְּדָא אֲרֵי אִתְגְלֵי לְמֶעְבַּד פּוּרְעֲנוּת דִין בְּגַוֵיךְ אֲמַר יְיָ:\",0,0],[4,141,5,18,\"וַי לִמְחַמְדִין לְיוֹמָא דַעֲתִיד לְמֵיתֵי מִן קֳדָם יְיָ לְמָא דְנַן לְכוֹן יוֹמָא דַעֲתִיד לְמֵיתֵי מִן קֳדָם יְיָ הוּא חֲשׁוֹךְ וְלָא נְהוֹר:\",0,0],[4,141,5,19,\"כְּמָא דִי יַעֲרוֹק גַבְרָא מִן קֳדָם אַרְיָא וִיעַרְעִנֵיהּ דוּבָא וְיֵיעוֹל לְבֵיתָא וְיִסְמוֹךְ יְדֵיהּ עַל כָּתְלָא וְיַכְתִנֵיהּ חִוְיָא:\",0,0],[4,141,5,20,\"הֲלָא חֲשׁוֹךְ יוֹמָא דְעָתִיד לְמֵיתֵי מִן קֳדָם יְיָ וְלָא נְהוֹר וּקְבַל וְלָא זֵהוֹר לֵיהּ:\",0,0],[4,141,5,21,\"סְגֵיתִי רְחִיקֵת חֲגֵיכוֹן וְלָא אֲקַבֵּל בְּרַעֲוָא קוּרְבַּן כְּנִשַׁתְכוֹן:\",0,0],[4,141,5,22,\"אֲרֵי אִם תִּסְקוּן קֳדָמַי עַלְוָן וְקוּרְבְּנֵיכוֹן לָא לְרַעֲוָא וְנִכְסַת קוּדְשֵׁיכוֹן לָא יִתְקַבְּלוּן קֳדָמַי:\",0,0],[4,141,5,23,\"אַעְדֵי מִן קֳדָמַי אִתְרְגוּשַׁת זִמְרָךְ וְנִגוּן כִּנָרָךְ לָא אֶשְׁמָע:\",0,0],[4,141,5,24,\"וְיִתְגְלֵי כְמַיָא דִינָא וּזְכוּתָא כְּנַחַל מַגְבַּר:\",0,0],[4,141,5,25,\"הֲנִכְסַת קוּדְשִׁין וְקוּרְבָּנִין קְרַבְתּוּן קֳדָמַי בְּמַדְבְּרָא אַרְבְּעִין שְׁנִין בֵּית יִשְׂרָאֵל:\",0,0],[4,141,5,26,\"וּנְטַלְתּוּן יַת סִכּוּת פַּת כּוּמָרֵכוֹן וְיַת כִּיוּן צַלְמֵיכוֹן כּוֹכַב טַעֲוַתְכוֹן דִי עֲבַדְתּוּן לְכוֹן:\",0,0],[4,141,5,27,\"וְאַגְלֵי יַתְכוֹן מֵהָלְאָה לְדַמֶשֶׂק אֲמַר יְיָ אֱלֹהִים צְבָאוֹת שְׁמֵיהּ:\",0,0],[4,141,6,1,\"וַי דְשָׁלָן שְׁלֵוָא בְּצִיוֹן וּמִתְרַחֲצִין עַל כְּרַכָּא דְשׁוֹמְרוֹן מְקַיְמִין שׁוּם בְּנֵיהוֹן כְּשׁוּם בְּנֵי עַמְמַיָא וְכָל דְמִן דְיִסְתַּמְכוּן עֲלֵיהוֹן בֵּית יִשְׂרָאֵל:\",0,0],[4,141,6,2,\"עֲבַרוּ לְכַלְנֵהּ וַחֲזוֹ וַאֲזִילוּ מִתַּמָן לַחֲמַת רַבָּה וְחוּתוּ לְגַת דְפְלִשְׁתָּאֵי דְטָבִין מִן מַלְכְּוָתָא הָאִלֵין אִם סַגִי תְּחוּמְהוֹן מִתְּחוּמְכוֹן:\",0,0],[4,141,6,3,\"אִנוּן מְרָחֲקִין יוֹם בִּישׁ וְאַתּוּן מְקָרְבִין בְבֵית כְּנִשְׁתְּכוֹן חֲטוֹף:\",0,0],[4,141,6,4,\"דְשָׁכְבִין עַל עַרְסָן דִמְכַבְּשָׁן בְּשֵׁן דְפִיל וְעוּמְקִין עַל עַרְסֵיהוֹן וְאָכְלִין פַּטִימִין מֵעָנָא וְעֶגְלִין מִגוֹ רְבַקָא:\",0,0],[4,141,6,5,\"דִמְנַגָן עַל פּוּם נְבָלָא כְּדָוִיד אַתְקִינוּ לְהוֹן מָנֵי זְמָרָא:\",0,0],[4,141,6,6,\"דְשָׁתָן בְּפִילְוָן דִכְסַף חֲמַר וְרֵישׁ מַשְׁחִין טָבִין מִתְמַשְׁחִין וְלָא כָאֵב לְהוֹן עַל תַּבְרֵיהּ דְיוֹסֵף:\",0,0],[4,141,6,7,\"בְּכֵן כְּעַן יִגְלָן בְּרֵישׁ גָלָן וְיֶעְדוּן מִנְהוֹן מַרְזְחִין וּמַכִּיכִין:\",0,0],[4,141,6,8,\"קַיֵים יְיָ אֱלֹהִים בְּמֵימְרֵיהּ אָמַר יְיָ אֱלָהָא דְיִשְׂרָאֵל מְנַבֵּל אֲנָא יַת בֵית מַקְדְשָׁא דְבוּתֵיהּ דְיַעֲקֹב וּבִרְנְיָתֵיהּ רָחֲקֵית וְאֶמְסַר קַרְתָּא וּמְלָאָהּ:\",0,0],[4,141,6,9,\"וִיהֵי אִם יִשְׁתָּאֲרוּן עַסְרָא גַבְרִין בְּבֵיתָא חַד וִימוּתוּן:\",0,0],[4,141,6,10,\"וְיִטְלִנֵיהּ קְרִיבֵיהּ מִיְקֵידָא לְאַפָּקָא גַרְמַיָא מִן בֵּיתָא וְיֵימַר לְדִי בְשִׁדָא דְבֵיתָא הַעוֹד כְּעַן עִמָךְ וְיֵימַר סָפוּ וְיֵימַר סַלֵק אֲרֵי כַּד הֲווֹ קַיָמִין לָא הֲווֹ מְצַלָן בִּשְׁמָא דַיָי:\",0,0],[4,141,6,11,\"אֲרֵי הָא יְיָ מְפַקֵיד וְיִמְחֵי מַלְכוּ רַבָּא מְחָא תַקִיפָא וּמַלְכוּ זְעֵירָא מְחָא חַלָשָׁא:\",0,0],[4,141,6,12,\"הֲיִרְהֲטוּן בְּכֵיפָא סוּסְוָן אִם יִתְרְדֵי בְתוֹרַיָא אֲרֵי הֲפַכְתּוּן לְרֵישׁ חִוְיָן בִּישִׁין דִינָא וּפְרִי זְכוּתָא לְגִידִין:\",0,0],[4,141,6,13,\"דְחָדוּן לְלָא מִדַעַם דְאָמְרִין הֲלָא בְּתוּקְפָנָא קְנֵינָא לָנָא נִכְסִין:\",0,0],[4,141,6,14,\"אֲרֵי הָא אֲנָא מֵקִים עֲלֵיכוֹן בֵּית יִשְׂרָאֵל אֲמַר יְיָ אֱלֹהִים צְבָאוֹת עַם וְיִדְחֲקוּן יַתְכוֹן מִמַעֲלָנָא דַחֲמָת עַד נַחְלָא דְמֵישְׁרָא:\",0,0],[4,141,7,1,\"כְּדֵין אֲחְזְיַנִי יְיָ אֱלֹהִים וְהָא בִּרְיַת גוֹבֵי בַּאֲוַל צִמוּחַ לָקִישׁ וְהָא צִמוּחַ דַעֲדַק בָּתַר דְאִתְגְזִיזַת שִׁחֲתָא דְמַלְכָּא:\",0,0],[4,141,7,2,\"וִיהֵא כַּד שֵׁיצֵי לְמֵיכַל יַת עִסְבָּא דְאַרְעָא וַאֲמָרֵית קַבֵּל בָּעוּתִי יְיָ אֱלֹהִים שְׁבוֹק כְּעַן לְחוֹבֵי שְׁאָרָא דְיַעֲקֹב מַן יְקוּם וְיִבְעֵי עַל חַטָאֵיהוֹן אֲרֵי מְטַלְטְלִין אִנוּן:\",0,0],[4,141,7,3,\"אָתִיב יְיָ רוּגְזֵיהּ עַל דָא לָא תִתְקַיֵים אֲמַר יְיָ:\",0,0],[4,141,7,4,\"כִּדְנַן אַחְזְיַנַי יְיָ אֱלֹהִים וְהָא עֲתִיד לְמִדַן בְּאֶשְׁתָּא יְיָ אֱלֹהִים וַאֲכָלַת יַת תְּהוֹם רַבָּא וְשַׁצִיאַת יַת אַחְסַנְתָּא:\",0,0],[4,141,7,5,\"וַאֲמָרַת קַבֵּל בָּעוּתִי יְיָ אֱלֹהִים שְׁבוֹק כְּעַן לְחוֹבֵי שְׁאָרָא דְבֵית יַעֲקֹב מַן יְקוּם וְיַבְעֵי עַל חֲטָאֵיהוֹן אֲרֵי מְטַלְטְלִין אִנוּן:\",0,0],[4,141,7,6,\"אֲתֵיב יְיָ רוּגְזֵיהּ עַל דָא לָא תִתְקַיֵם אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,141,7,7,\"כִּדְנַן אַחְזְיַנִי וְהָא יְיָ קָאֵם עַל שׁוּר דְדִין וְקָדָמוֹהִי דִין:\",0,0],[4,141,7,8,\"וַאֲמַר יְיָ לִי מָא אַתְּ חָזֵי עָמוֹס וַאֲמַרֵית דִין וַאֲמַר יְיָ הָא אֲנָא עָבֵיד דִין בְּגוֹ עַמִי יִשְׂרָאֵל לָא אוֹסִיף עוֹד לְמִשְׁבַּק לְהוֹן:\",0,0],[4,141,7,9,\"וְיִצְדוּן בְּמָת יִשְׂחָק וּמַקְדְשֵׁי יִשְׂרָאֵל יֶחֱרְבוּן וַאֲקֵם עַל בֵּית יְרָבְעָם דְקָטְלִין בְּחַרְבָּא:\",0,0],[4,141,7,10,\"וּשְׁלַח אֲמַצְיָה רַבָּא דְבֵית אֵל לְוַת יְרָבְעָם מַלְכָּא דְיִשְׂרָאֵל לְמֵימַר מְרִיד עֲלָךְ עָמוֹס בְּגוֹ בֵּית יִשְׂרָאֵל לָא תִכּוּל אַרְעָא לְסוֹבָרָא יַת כָּל פִּתְגָמוֹהִי:\",0,0],[4,141,7,11,\"אֲרֵי כִּדְנַן אֲמַר עָמוֹס בְּחַרְבָּא יִתְקְטֵל יְרָבְעָם וְיִשְׂרָאֵל מִגְלָא יִגְלוֹן מְעַל אַרְעֵהוֹן:\",0,0],[4,141,7,12,\"וַאֲמַר אֲמַצְיָה לְעָמוֹס נְבִיָא אֲתָא אֱזֵל לָךְ לְאַרְעָא דְבֵית יְהוּדָה וֶאֱכוּל תַּמָן לַחְמָא וְתַמָן תִּתְנַבֵּי:\",0,0],[4,141,7,13,\"וּבֵית אֵל לָא תוֹסִיף עוֹד לְאִתְנַבָּאָה אֲרֵי מִקְדָשׁ מַלְכָּא הוּא וּבֵית מַלְכוּתָא הוּא:\",0,0],[4,141,7,14,\"וַאֲתֵיב עָמוֹס וַאֲמַר לַאֲמַצְיָה לָא נְבִיָא אֲנָא וְלָא בַר נְבִיָא אֲנָא אֲרֵי מָרֵי גֵיתֵי אֲנָא וְשִׁקְמִין אִית לִי בַשְׁפֶלְתָּא מִן קֳדָם חוֹבֵי עַמָא יִשְׂרָאֵל אֲנָא מַסְגִיף נַפְשִׁי:\",0,0],[4,141,7,15,\"וְדַבַּרְנִי יְיָ מִן דִירָא מִבָּתַר עָנָא וַאֲמַר לִי יְיָ אֱזֵל אִתְנַבֵּי עַל עַמִי יִשְׂרָאֵל:\",0,0],[4,141,7,16,\"וּכְעַן קַבֵּל פִּתְגָמָא דַייָ אַתְּ אֲמַרְתְּ לָא תִּתְנַבֵּי בִּשְׁמָא דַיְיָָ עַל יִשְׂרָאֵל וְלָא תַלֵיף עַל בֵּית יִשְׂחָק:\",0,0],[4,141,7,17,\"בְּכֵן כִּדְנַן אָמַר יְיָ אִתְּתָךְ בְּקַרְתָּא תִטְעֵי וּבְנָךְ וּבְנָתָךְ בְּחַרְבָּא יִתְקַטְלוּן וְאַרְעָךְ בְּעַדְבָא תִּתְפְּלֵג וְאַתְּ עַל אַרְעָא מְסָאֲבָא תְמוּת וְיִשְׂרָאֵל מִגְלָא יִגְלוּן מֵעַל אַרְעֲהוֹן:\",0,0],[4,141,8,1,\"כְּדֵין אַחְזְיַנִי יְיָ אֱלֹהִים וְהָא מָן מְלֵי סְיוּפֵי קַיְטָא:\",0,0],[4,141,8,2,\"וַאֲמַר מָא אַתְּ חָזֵי עָמוֹס וַאֲמָרֵית מָן מְלֵי סְיוּפֵי קַיְטָא וַאֲמַר יְיָ לִי מְטַת פּוּרְעֲנוּת קִצָא לְמֵיתֵי עַל עַמִי יִשְׂרָאֵל לָא אוֹסִיף עוֹד לְמִשְׁבַּק לְהוֹן:\",0,0],[4,141,8,3,\"וְיֵלִילוּן חֲלַף זִמְרָא בְּבָתֵּיהוֹן בְּעִדָנָא הַהִיא אֲמַר יְיָ אֱלֹהִים סַגֵי פִגְרֵי קְטִילִין בְּכָל אֲתַר יֵימַר רָמֵי וְסַלֵק:\",0,0],[4,141,8,4,\"שְׁמָעוּ דָא דְשָׁיְטִין כְּעַפְרָא דְאַרְעָא רֵישׁ מִסְכְּנַיָא וּמְדַמָן לְבַטְלָא מִלֵי חֲשִׁיכַיָא מִן אַרְעָא:\",0,0],[4,141,8,5,\"דְאָמְרִין אֵימָתַי יִמְטֵי יְרַח עִבּוּרָא וּנְזַבֵּן עִבּוּרָא וּשְׁמִטְתָּא וְנִפְתַּח אוֹצְרִין לְאַזְעָרָא מְכִלְתָּא וּלְאוֹסְפָא עַל סִלְעָא וּלְשַׁקְרָא בְמָזְנְוָן דִנְכִיל:\",0,0],[4,141,8,6,\"לְמִקְנֵי בְּכַסְפָּא מִסְכְּנַיָא חֲשִׁיכַיָא בְּדִיל דְיַחְסְנוּן וּמֵהַמְמַת עִבּוּרָא נְזַבֵּן:\",0,0],[4,141,8,7,\"קַיֵם יְיָ דִיהַב רְבוּתָא לְיַעֲקֹב אִם יִתְנְשׁוּן לְעָלְמִין כָּל עוֹבָדֵיהוֹן:\",0,0],[4,141,8,8,\"הַעַל דָא לָא תֶחֱרוֹב אַרְעָא וְיִצְדֵי כָּל דְיָתֵיב בָּהּ וְיִסַק עֲלָהּ מְלַךְ בְּמַשְׁרְיָתֵיהּ דְסַגִי כְּמֵי נַהֲרָא וִיַחֲפִנָהּ כּוּלָהּ וִיתָרֵךְ יַת יַתְבָהָא וְתִשְׁתְּקַע כִּנְהַר מִצְרַיִם:\",0,0],[4,141,8,9,\"וִיהֵי בְּעִדָנָא הַהִיא אֲמַר יְיָ אֱלֹהִים וַאֲכַסֵי שִׁמְשָׁא כַּד בְּטַהֲרָא וְאַקְבֵּיל לְאַרְעָא בְיוֹם נְהוֹר:\",0,0],[4,141,8,10,\"וְאַהֲפֵיךְ חֲגֵיכוֹן לְאָבְלָא וְכָל תֻּשְׁבַּחְתְּכוֹן לְאִלְיָא וְאֶסַק עַל כָּל חַרְצִין סַק וְעַל כָּל רֵישׁ מְרַט וְאַשְׁוִינָהּ כְּאֵבֶל יָחִיד וְסוֹפָהּ כְּיוֹם מְרִיר:\",0,0],[4,141,8,11,\"הָא יוֹמַיָא אָתָן אֲמַר יְיָ אֱלֹהִים וְאֶשְׁלַח כַּפְנָא בְּאַרְעָא לֵית דָכָפַן לְמֵיכַל וְלֵית דִי צָחֵי לְמִשְׁתֵּי אֱלָהֵין לְקַבְּלָא יַת פִּתְגָמָא דַיְיָ:\",0,0],[4,141,8,12,\"וְיִשְׁתַּלְהוֹן מִיָמָא עַד מַעַרְבָא וּמִצִפוּנָא עַד מְדִינְחָא יַהֲכוּן לְמִתְבַּע אוּלְפַן מִן קֳדָם יְיָ וְלָא יִשְׁכְּחוּן:\",0,0],[4,141,8,13,\"בְּיוֹמָא הַהוּא יִשְׁתַּלְהַיָן כְּנִישָׁתָא דְיִשְׂרָאֵל דְאִינוּן דַמְיָן לִבְתוּלָן שַׁפִּירָן דְטָעָאָה בְּשִׁפְרְהָן עִם עוּלֵימִין חַיָבִין וִיהוֹן מְטָרְפִין וּרְמָן בִּצְחוּתָא:\",0,0],[4,141,8,14,\"דִי מְקַיְמִין בְּחוֹבַת שֹׁמְרוֹן וְאָמְרִין קַיָמָא דְחַלְתָּא דִי בְדָן וְקַיָמִין נִימוּסֵי בְאֵר שָׁבַע וְיִפְּלוּן וְלָא יְקוּמוּן עוֹד:\",0,0],[4,141,9,1,\"אֲמַר עָמוֹס נְבִיָא חֲזֵיתִי יַת יְקָרָא דַייָ אִסְתַּלֵק מִכְּרוּבָא וּשְׁרָא עַל מַדְבְּחָא וַאֲמַר אִם לֵית עַמָא בֵית יִשְׂרָאֵל תָּיְבִין לְאוֹרַיְתָא טְפֵי מְנַרְתָּא אִתְקְטֵיל מַלְכָּא יֹאשִׁיָה וְיֶחְרַב בֵּיתָא וְיִתְפַּגְרָן עֲזָרָתָא וּמָנֵי בֵית מַקְדְשָׁא בְּשִׁבְיָא יַהֲכוּן וּשְׁאָרֵיהוֹן בְּחַרְבָּא אֶקְטוֹל לָא יַעֲרוֹק לְהוֹן דַעֲרִיק וְלָא יִשְׁתֵּזֵיב לְהוֹן דְמִשְׁתֵּיזִיב:\",0,0],[4,141,9,2,\"אִם יְדַמוּן לְאִטַמָרָא כִּדְבִשְׁאוֹל מִתַּמָן בְּמֵימְרִי יַדְבְּרִינוּן סַנְאֵיהוֹן וְאִם יִסְקוּן בְּטוּרִין דְרָמִין עַד צֵית שְׁמַיָא מִן תַּמָן בְּמֵימְרִי יַחֲתוּנוּן:\",0,0],[4,141,9,3,\"וְאִם יְדַמוּן לְאִטַמְרָא בְּרֵישֵׁי מִגְדְלֵי כְרַכַּיָא מִתַּמָן אַפְקֵיד בְּלוֹשִׁין וְיִבְלְשׁוֹנוּנוּן וְאִם יִטַמְרוּן מִן קֳדָם מֵימְרִי בְנִיסֵי יַמָא מִתַּמָן אַפְקֵיד יַת עַמְמַיָא דְתַקִיפִין כְּחִוְיָא וְיִקְטְלוּנוּנוּן:\",0,0],[4,141,9,4,\"וְאִם יַהֲכוּן בְּשִׁבְיָא קֳדָם בַּעֲלֵי דְבָבֵיהוֹן מִתַּמָן אַפְקִיד יַת דְקַטְלִין בְּחַרְבָּא וְיִקְטְלוּנוּן וַאֲשַׁוֵי מֵימְרִי עֲלֵיהוֹן לְבִישָׁא וְלָא לְטָבָא:\",0,0],[4,141,9,5,\"וַיָי אֱלֹהִים צְבָאוֹת דִי נָזֵיף בְּאַרְעָא וְזִיעָא וְיִצְדוּן כָּל דְיָתְבִין בָּהּ וְיַסֵיק עֲלָהּ מְלַךְ בְּמַשִׁרְיָתֵיהּ דִסַגִי כְּמֵי נַהֲרָא וְיַחֲפִינָהּ כוּלָהּ וְתִשְׁתְּקַע כִּנְהַר מִצְרָיִם:\",0,0],[4,141,9,6,\"דִי אַשְׁרֵי בִּתְקוֹף רוּמָא שְׁכִינַת יְקָרֵיהּ וּכְנִשְׁתֵּיהּ עַל אַרְעָא קִשְׁטָהּ דִי אֲמַר לְכַנָשָׁא מַשִׁרְיָן דְסַגִיאִין כְּמֵי נַהֲרָא וּמְבַדַר לְהוֹן עַל אַפֵּי אַרְעָא יְיָ שְׁמֵיהּ:\",0,0],[4,141,9,7,\"הֲלָא כִּבְנִין רְחִימִין אַתּוּן חֲשִׁיכִין קָדָמַי בֵּית יִשְׂרָאֵל אֲמַר יְיָ הֲלָא יַת יִשְׂרָאֵל אַסְקֵית מֵאַרְעָא דְמִצְרַיִם וּפְלִשְׁתָּאֵי מִקַפּוּטְקַיָא אֲרם מִקִּירְנֵי:\",0,0],[4,141,9,8,\"הָא קֳדָם יְיָ אֱלֹהִים גְלַן עוֹבְדֵי מַלְכוּתָא חַיֶבְתָּא וֶאֱשֵׁיצֵי יָתָהּ מְעַל אַפֵּי אַרְעָא בְּרַם אֲרֵי לָא גְמִירָא וְשֵׁיצָאָה אֱשֵׁיצֵי יַת בֵּית יִשְׂרָאֵל אֲמַר יְיָ:\",0,0],[4,141,9,9,\"אֲרֵי הָא אֲנָא מְפַקֵיד וַאֲבָדַר בְּכָל עַמְמַיָא יַת בֵּית יִשְׂרָאֵל כְּמָא דִמְחַזְרִין כְּעַרְבְּלָא וְלָא נָפֵיל מִנֵיהּ אֶבֶן מִבֵּינָהּ לְאַרְעָא:\",0,0],[4,141,9,10,\"בְּחַרְבָּא יִתְקַטְלוּן כָּל חַיָבֵי עַמִי דְאָמְרִין לָא תֵיתֵי וְתוֹחִי עֲלָנָא בִישְׁתָּא:\",0,0],[4,141,9,11,\"בְּעִדָנָא הַהִיא אָקִים יַת מַלְכוּתָא דְבֵית דָוִד דְנָפְלַת וְאֶבְנֵי יַת כְּרַכֵּיהוֹן וּכְנִישַׁתְהוֹן אַתְקֵין וְתִשְׁלוֹט בְּכָל מַלְכוּתָא וְתִגְמַר וּתְשֵׁיצֵי סַגִי מַשִׁרְיָתָא וְהִיא תִתְבְּנֵי וְתִשְׁתַּכְלֵיל בְּיוֹמֵי עַלְמָא:\",0,0],[4,141,9,12,\"בְּדִיל דְיָרְתִין שְׁאָרָא דֶאֱדוֹם וְכָל עַמְמַיָא בֵּית יִשְׂרָאֵל דְאִתְקְרֵי שְׁמִי עֲלֵיהוֹן בְּכֵן אֲנָא יְיָ עָבֵד דָא:\",0,0],[4,141,9,13,\"הָא יוֹמַיָא אָתָן אֲמַר יְיָ וְיֶעֱרַע רַדְיָא בַחֲצוֹדָא וְעַצָר עִנְבִין בְּמִפַּק בַּר זַרְעָא וְיִרְבּוּן טוּרַיָא חֲמַר מְרַת וְכָל רָמְתָא יִתְפַּלְחָן:\",0,0],[4,141,9,14,\"וְאָתֵיב יַת גָלוּת עַמִי יִשְׂרָאֵל וְיִבְנוּן קִרְוִין דְצַדְיָן וִיתוּבוּן וְיִצְבּוּן כַּרְמִין וְיִשְׁתּוּן יַת חַמְרֵהוֹן וְיַעְבְּדוּן גַנִין וְיֵכִלוּן יַת אִבֵּיהוֹן:\",0,0],[4,141,9,15,\"וַאֲקַיְמִינוּן עַל אַרְעֲהוֹן וְלָא יְטַלְטְלוּן עוֹד מֵעַל אַרְעֲהוֹן דִיהָבִית לְהוֹן אֲמַר יְיָ אֱלָהָךְ:\",0,0],[4,142,1,1,\"אִלֵּין פִּתְגָמֵי אוֹכָחוּתָא דִי מַלֵּיל משֶׁה עִם כָּל יִשְרָאֵל כַּנְפִינוּן לְוָתֵיהּ כַּד הֲווֹן בְּעִיבְרָא דְיַרְדְּנָא עָנָא וַאֲמַר לְהוֹן הֲלָא בְּמַדְבְּרָא בְּטַוְרָא דְסִינַי אִתְיְהִבַת לְכוֹן אוֹרַיְיתָא וּבְמֵישְׁרַיָא דְמוֹאָב אִתְפַּרְשַׁת לְכוֹן כַּמָּה נִיסִין וּפְרִישַׁן עָבַד לְכוֹן קוּדְשָׁא בְּרִיךְ הוּא מִזְמַן דַּעֲבַרְתּוּן עַל גֵּיף יַמָא דְסוּף דַּעֲבַד לְכוֹן אִסְטְרַט לְכָל שִׁבְטָא וְשִׁבְטָא וְאַתּוּן סְטֵיתוּן מִבָּתַר מֵימְרֵיהּ וְאַרְגַּזְתּוּן קֳדָמוֹי בְּפָארָן עַל מֵימְרָא אַלְלַיָא וּטְפַלְתּוּן עֲלוֹי מִילֵי שִׁקְרָא וְאִתְרַעַמְתּוּן עַל מַנָא דְאָחִית לְכוֹן חִיוַור מִן שְׁמַיָא וְשַׁיֵילְתּוּן בִּישְרָא בַּחֲצֵרוֹת וַהֲוֵי חָמֵי לְכוֹן לְמִשְׁתֵּיצְיָא מִגּוֹ עַלְמָא אִלוּלֵי דִדְכַר לְכוֹן זְכוּת אַבְהַתְכוֹן צַדִיקַיָא וּמַשְׁכַּן זִמְנָא וַאֲרוֹן קְיָימָא וּמָאנָא קוּדְשָׁא דַּחֲמִיתוּן דַּהֲבָא סַנִינָא וְכַפֵּר לְכוֹן עַל חוֹבַת עֵיגַל דַּהֲבָא\",0,0],[4,142,1,2,\"מַהֲלַךְ חַדְסַר יוֹמִין מֵחוֹרֵב מֵאוֹרַח טַוְורָא דְגַבְלָא עַד רְקַם גֵּיאָה וְעַל דִּי סְטִיתוּן וְאַרְגַּזְתּוּן קֳדָם יְיָ אִיתְחַרְתּוּן אַרְבְּעִין שְׁנִין\",0,0],[4,142,1,3,\"וַהֲוָה לְסוֹף אַרְבְּעִין שְׁנִין בְּחַדְסַר יֶרַח הוּא יַרְחָא דִשְׁבַט בְּחַד בְּיַרְחָא מַלֵּיל משֶׁה עִם בְּנֵי יִשְרָאֵל כְּכָל דִּי פַקֵּיד יְיָ יָתֵיהּ לְוַתְהוֹן\",0,0],[4,142,1,4,\"מִן בָּתַר דִּמְחָא יַת סִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה דִיתֵיב בְּחֶשְׁבּוֹן וְיַת עוֹג מַלְכָּא דְמַתְנַן דִּיתֵיב בְּעַשְׁתַּרְוָותָא בְּאֶדְרֶעָת\",0,0],[4,142,1,5,\"בְּעִיבְרָא דְיוֹרְדְּנָא בְּאַרְעָא דְמוֹאָב שׁוֹרֵי משֶׁה לְמַלְפָא יַת פִּתְגָמֵי אוֹרַיְיתָא הֲדָא לְמֵימָר\",0,0],[4,142,1,6,\"יְיָ אֱלָהֵין מַלֵיל עִמָן וְלָא אֲנָא בְּאַנְפֵּי נַפְשִׁי בְּחוֹרֵב לְמֵימָר סַגִי לְכוֹן וְאִתְהַנִי לְכוֹן עַד הָאִידְנָא דְקַבֵּילְתּוּן בֵּיהּ אוֹרַיְיתָא וַעֲבַדְתּוּן בֵּיהּ מַשְׁכְּנָא וּמָנוֹי וְאַקֵימְתּוּן רַבָּנִין עֲלֵיכוֹן וּמַבְעַן בִּישׁ לְכוֹן לְאִיתְרָחָא בְּטַוְורָא הָדֵין\",0,0],[4,142,1,7,\"אִתְפְּנִיאוּ וְטוּלוּ לְכוֹן לַעֲרָד וְחוּרְמָה וְעוּלוּ לְטַוְורָא דֶאֱמוֹרָאָה וּלְוַת כָּל דַּיְירֵי עַמּוֹן וּמוֹאָב וְגַבְלָא בְּמֵישְׁרָא דְחוֹרְשָׁא בְּטַוְורָא בִּשְׁפֵיילְתָּא וּבְדָרוֹמָא וּבִסְפַר יַמָא אַשְׁקְלוּן וְקִיסְרִין אַרַע כְּנַעֲנָאָה עַד קַלְדוֹהִי וְלִבְנָן אֲתַר טַוְורֵי בֵּית מַקְדְּשָׁא עַד נַהֲרָא רַבָּא נַהֲרָא פְּרָת\",0,0],[4,142,1,8,\"חֲמוֹן דִּי מְסָרִית קֳדָמֵיכוֹן יַת דַּיְירֵי אַרְעָא וְלָא תִצְטַרְכוּן לְמֵיטוּל זַיְינָא עוּלוּ וְאַחֲסִינוּ יַת אַרְעָא וְקָבְעוּ בָּהּ דִּפְטַיָא וּפַלְגוּהָא הֵי כְמָא דְקַיֵים לְאַבְהַתְכוֹן לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקב לְמִתַּן לְהוֹן וְלִבְנֵיהוֹן בַּתְרֵיהוֹן\",0,0],[4,142,1,9,\"וַאֲמָרִית לְכוֹן בְּעִידָנָא הַהִיא לְמֵימָר לֵיתָנָא שַׁבְקִינְכוֹן עַל דַּיָינָא חַד דַּאֲנָא לָא יָכִילְנָא בִּלְחוֹדִי לִמְסוֹבָרָא יַתְכוֹן\",0,0],[4,142,1,10,\"מֵימְרָא דַיְיָ אֱלָהָכוֹן אַסְגֵי יַתְכוֹן וְהָאִיתֵיכוֹן יוֹמָא דֵין הֵי כְּכוֹכְבֵי שְׁמַיָא לִסְגֵי\",0,0],[4,142,1,11,\"יְיָ אֱלָהָא דְאַבְהַתְכוֹן יוֹסֵף עֲלֵיכוֹן כְּוַותְכוֹן אֶלֶף זִמְנִין מְטוּל בִּרְכָתִי דָא וִיבָרֵךְ יַתְכוֹן בְּלָא סְכוּמָא הֵיכְמָא דְמַלֵּיל לְכוֹן\",0,0],[4,142,1,12,\"הֵיךְ אֲנָא יָכִיל בִּלְחוֹדִי לְמִסְבּוֹל טַרְחוֹת אַפְקַרְסוּתְכוֹן וּדְמִחַשְׁלִין עֲלֵי בִישְׁתָּא וּמִילֵי דִיגַנְבוּן דְּמַפְקִין סִלְעָא לְאַפּוֹקֵי תְּרֵי\",0,0],[4,142,1,13,\"זַמְנוּ לְכוֹן גּוּבְרִין חַכִּימִין וְסוּכְלְתָנוּן מֵרַעֲיוֹנֵיהוֹן וּמָארֵי מַנְדְּעָא לְשִׁבְטֵיכוֹן וְאֵימַנִינוּן רֵישִׁין עֲלֵיכוֹן\",0,0],[4,142,1,14,\"וְאַתֵיבְתִּין יָתִי וַאֲמַרְתּוּן תַּקִּין פִּתְגָמָא דְמַלֵּילְתָּא לְמֶעֱבַד\",0,0],[4,142,1,15,\"וְדַבָּרִית יַת רֵישֵׁי שִׁבְטֵיכוֹן וְאוֹרַכְתִּנּוּן בְּמִלַיָא גּוּבְרִין חַכִּימִין וּמָרֵי מַנְדְּעָא וְסוּכְלְתָנִין מֵרַעֲיוֹנֵיהוֹן לָא אַשְׁכָּחִית וּמְנִיתֵיתוּן רֵישֵׁי עֲלֵיכוֹן רַבָּנֵי אַלְפִין רַבָּנֵי מַאֲוָותָא רַבָּנֵי חַמְשִׁין תְּרֵיסַר אַלְפִין רַבָּנֵי עִשַרְיָיתָא שִׁית רִיבְוָון וְסַרְכִין לְשִׁבְטֵיכוֹן\",0,0],[4,142,1,16,\"וּפַקֵּדִית יַת דַּיָינֵיכוֹן בְּעִידָנָא הַהִיא יַת סִדְרֵי דִינַיָא לְמֵימָר קַבִּילוּ מִן אֲחוּכוֹן דְּלָא יְמַלֵּיל חָד כָּל מִילוֹי וְחָד מְקַטַע מִילוֹי וּמִדִּשְׁמַעֲתּוּן מִלֵּיהוֹן לֵית אֶפְשַׁר לְכוֹן דְּלָא לְמִדַנְהוֹן וּתְדוּנוּן דִּינָא בִּקְשׁוֹט וּפְשָׁרוּת שְׁלָמָא בֵּין גַּבְרָא לְאָחוֹי וּבֵין מַאן דְּמֶאֱגַר מִילֵי דִינִין\",0,0],[4,142,1,17,\"לָא תִשְׁתְּמוֹדְעוּן אַפִּין בְּדִינָא מִילֵי זְעֵירָא הֵי כְּמִילֵי רַבָּא תִשְׁמְעוּן וְלָא תִדַּחֲלוּן מִן קֳדָם עַתִּיר וְשׁוּלְטַן אֲרוּם דִּינָא מִן קֳדָם יְיָ וְחָמֵי כָּל טוּמְרַיָא וּפִתְגָמָא דְיִקְשֵׁי מִנְכוֹן תְּקַרְבוּן לְוָתִי וְאַשְׁמְעִינֵיהּ\",0,0],[4,142,1,18,\"וּפַקֵּדִית יַתְכוֹן בְּעִידָנָא הַהִיא יַת כָּל עַשְרָא פִּתְגָמַיָא דְתַעְבְּדוּן בֵּינֵי דִינֵי מָמוֹנָא לְדִינֵי נַפְשָׁתָא\",0,0],[4,142,1,19,\"וּנְטָלָנָא מֵחוֹרֵב וְהַלִיכְנָא יַת כָּל מַדְבְּרָא רַבָּא וּדְחִילָא הַהוּא דַחֲמִיתוּן חֵיוָן כִּכְשׁוּרִין וְעַקְרַבִּין כְּקַשְׁתִּין סַרְיָין רַמְיָין לְקוֹבְלֵיכוֹן אוֹרַח טַוְורָא דְאֵימוֹרָאָה הֵיכְמָא דְפַקֵּיד יְיָ אֱלָהָנָא יָתָנָא וְאָתֵינָא עַד רְקַם גֵּיעָה\",0,0],[4,142,1,20,\"וַאֲמָרִית לְכוֹן אֲתֵיתוּן עַד טַוְורָא דֶאֱמוֹרָאָה דַיְיָ אֱלָהָנָא יָהֵיב לָנָא\",0,0],[4,142,1,21,\"חָמוּן דִּיהַב יְיָ אֱלָהָכוֹן לְכוֹן יַת אַרְעָא סוּקוּ וְאַחֲסִינוּ הֵיכְמָא דְמַלֵּיל יְיָ אֱלָהָכוֹן לְכוֹן לָא תִידַחֲלוּן וְלָא תִיתַבְּרוּן\",0,0],[4,142,1,22,\"וְקָרֵיבְתּוּן לְוָתִי בְּעַרְבּוּבְיָא כּוּלְכוֹן וַאֲמַרְתּוּן נְשַׁדֵּר גּוּבְרִין קֳדָמָנָא וְיִתְרָגְנוּן לָנָא יַת אַרְעָא וִיתֵיבוּן יָתָנָא פִּתְגָמָא יַת אוֹרְחָא דְנִיסַק בָּהּ וְיַת קִרְוַיָא דְנֵיעוּל לְוַתְהוֹן\",0,0],[4,142,1,23,\"וּשְׁפַר בְּעֵינַי פִּתְגָמָא וּדְבָרִית מִנְכוֹן תְּרֵיסַר גּוּבְרִין בְּרִירִין גּוּבְרָא חָד לְשִׁבְטָא\",0,0],[4,142,1,24,\"וְאִתְפְּנִיּוּ וּסְלִיקוּ לְטַוְורָא וְאָתוּ עַד נַחֲלָא דְאַתְכְּלָא וּתְרִגִינוּ יָתָהּ\",0,0],[4,142,1,25,\"וּנְסִיבוּ בִּידֵיהוֹן מִן אִיבָּא דְאַרְעָא וְאָחִיתוּ לְוָתָנָא וְאָתִיבוּ יָתָנָא פִּתְגָמָא וַאֲמָרוּ כָּלֵב וִיהוֹשֻׁעַ טָבָא אַרְעָא דַיְיָ אֱלָהָנָא יָהֵיב לָנָא\",0,0],[4,142,1,26,\"וְלָא צְבִיתוּן לְמֵיסוֹק וְהֵמַנְתּוּן לְפִתְגָמֵי עַשְרָא רְשִׁיעִין וְסָרֵיבְתּוּן עַל מֵימְרָא דַיְיָ אֱלָהָכוֹן\",0,0],[4,142,1,27,\"וְרַגִינְתּוּן בְּמַשְׁכְּנֵיכוֹן נְסֵיבְתּוּן בְּנֵיכוֹן וּבְנָתֵיכוֹן בְּעִיטְפֵיכוֹן לְמֵימָר וַוי לְכוֹן סַגִיפִין מְחַר אַתּוּן מִתְקַטְלִין מְטוֹל דְּסָנֵי יְיָ יָתָנָא אַפְקָנָא מִן אַרְעָא דְמִצְרַיִם לְמִימְסַר יָתָנָא בִּידָא דֶאֱמוֹרָאֵי לְשֵׁצֵיוּתָנָא\",0,0],[4,142,1,28,\"לְאָן אֲנַחְנָא סַלְקִין אָחָנָא מַסְמִיסַן יַת לִיבָּנָא לְמֵימָר עַם רַב וּתְקֵיף מִנָנָא קִירְוַון רַבְרְבָן וּכְרִיכַן עַד צֵית שְׁמַיָא וְאוּף בְּנֵי עֶפְרוֹן גִּבָּרָא חֲמֵינָא תַּמָן\",0,0],[4,142,1,29,\"וַאֲמָרִית לְכוֹן לָא תִתְבְּרוּן וְלָא תִדַחֲלוּן מִנְהוֹן\",0,0],[4,142,1,30,\"מֵימְרָא דַיְיָ אֱלָהָכוֹן דִּמְדַבֵּר קֳדָמֵיכוֹן הוּא יַגִּיחַ לְכוֹן כְּכָל מַה דַּעֲבַד לְכוֹן בְּמִצְרַיִם לְמֵיחְמֵיכוֹן\",0,0],[4,142,1,31,\"וּבְמַדְבְּרָא דַחֲמֵיתָא חִוְויָא קָלָן מַלְיָין אֶרֶס דִּקְטוֹל וְסוֹבְרָךְ יְיָ אֱלָהָךְ בַּעֲנָנֵי אִיקַר שְׁכִינְתֵּיהּ הֵיכְמָא דִמְסוֹבַר גְּבַר יַת בְּרֵיהּ בְּכָל אָרְחָא דְהַלֵיכְתּוּן עַד זְמַן מֵיתֵיכוֹן עַד אַתְרָא הָדֵין\",0,0],[4,142,1,32,\"וּבְפִתְגָמָא הָדֵין לֵיתֵיכוֹן מְהֵימְנִין בְּמֵימְרָא דַיְיָ אֱלָהָכוֹן\",0,0],[4,142,1,33,\"דִּמְדַבֵּר קֳדָמֵיכוֹן בְּאָרְחָא לְאִיתַקְנָא לְכוֹן אֲתַר בֵּית מֵשְׁרוֹי לְאַשְׁרָיוּתְכוֹן בְּעַמּוּדָא דְאֵישָׁא בְּלֵילְיָא לְאַנְהָרוּתְכוֹן בְּאָרְחָא דְתֶהֱכוֹן בָּהּ וְעַמּוּדָא דַעֲנָנָא בִּימָמָא\",0,0],[4,142,1,34,\"וּשְׁמִיעַ קֳדָם יְיָ יַת קַל פִּתְגָמֵיכוֹן וּרְגַז וְקַיֵּים לְמֵימָר\",0,0],[4,142,1,35,\"אִין יֶחֱמוּן גְּבַר בְּגוּבְרַיָא הָאִילֵין דָּרָא בִישָׁא הָדֵין יַת אַרְעָא טַבְתָא דְקַיֵּימִית לְמִתַּן לְאַבְהַתְכוֹן\",0,0],[4,142,1,36,\"אֱלָהֵן כָּלֵב בַּר יְפוּנֶה הוּא יֶחֱמִינָהּ וְלֵיהּ אִיתֵּן יַת אַרְעָא טַבְתָא אַרְעָא דְחֶבְרוֹן דִּמְטַיֵּיל בָּהּ וְלִבְנוֹי חוֹלַף דְּאַשְׁלִים בָּתַר דַּחַלְתָּא דַיְיָ\",0,0],[4,142,1,37,\"אוּף עָלַי הֲוָה רְגַז מִן קֳדָם יְיָ מְטוּלְכוֹן לְמֵימָר אוּף אַנְתְּ לָא תֵיעוּל לְתַמָּן\",0,0],[4,142,1,38,\"יְהוֹשֻׁעַ בַּר נוּן דִּמְשַׁמֵּשׁ בְּבֵית אוּלְפָנָךְ הוּא יֵיעוֹל לְתַמָּן יָתֵיהּ תַּקִּיף אֲרוּם הוּא יַחְסְנִינָהּ יַת יִשְרָאֵל\",0,0],[4,142,1,39,\"וְטַפְלְכוֹן דַּאֲמַרְתּוּן לַעֲדִי יְהוֹן וּבְנֵיכוֹן דְּלָא יָדְעִין יוֹמָא דֵין בֵּין טַב לְבִישׁ הִינוּן יַעֲלוּן לְתַמָּן וּלְהוֹן אֶתְּנִינָהּ וְהִינוּן יֵירְתוּנָהּ\",0,0],[4,142,1,40,\"וְאַתּוּן אִתְפְּנִיוּ לְכוֹן וְטוּלוּ לְמַדְבְּרָא אוֹרַח יַמָא דְסוּף\",0,0],[4,142,1,41,\"וַאֲתֵיבְתּוּן וַאֲמַרְתּוּן לִי חַבְנָא קֳדָם יְיָ אֲנַחְנָא נִיסַק וְנָגִיחַ קְרָב כְּכָל דְּפַקְדָנָא יְיָ אֱלָהָנָא וַאֲסַרְתּוּן גְּבַר יַת מָאנֵי זַיְינֵיהּ וְשָׁרֵיתוּן לְמֵיסוֹק לְטַוְורָא\",0,0],[4,142,1,42,\"וַאֲמַר יְיָ לִי אֵימַר לְהוֹן לָא תִסְקוּן וְלָא תְסַדְּרוּן סִדְרֵי קְרָב אֲרוּם לֵית שְׁכִינְתִּי מְהַלְכָא בֵּינֵיכוֹן וְלָא תִיתְבְּרוּן קֳדָם בַּעֲלֵי דְבָבֵיכוֹן\",0,0],[4,142,1,43,\"וּמַלֵלִית לְכוֹן וְלָא קַבֵּילְתּוּן וְסָרֵיבְתּוּן עַל מֵימְרָא דַיְיָ וְאַרְשַׁעְתּוּן וּסְלִיקְתּוּן לְטַוְורָא\",0,0],[4,142,1,44,\"וּנְפַק אֱמוֹרָאָה דְיָתִיב בְּטַוְורָא הַהוּא לִקְדָמוּתְכוֹן וּרְדָפוּ יַתְכוֹן הֵיכְמָא דְחַדִדַן וְחַיְישַׁן אוּרְעֲיָיתָא וּמְחוֹ יַתְכוֹן בְּגַבְלָא עַד חָרְמָה\",0,0],[4,142,1,45,\"וְתֵיבְתּוּן וּבְכִיתוּן קֳדָם יְיָ וְלָא קַבֵּיל יְיָ צְלוּתְכוֹן וְלָא אָצִית לְמִילֵיכוֹן\",0,0],[4,142,1,46,\"וִיתֵיבְתּוּן בִּרְקַם יוֹמִין סַגִּיאִין כְּיוֹמַיָא דִיתֵיבְתּוּן\",0,0],[4,142,2,1,\"וְאִתְפְּנִינָא וּנְטָלְנָא לְמַדְבְּרָא אוֹרַח יַמָא דְסוּף הֵיכְמָא דְמַלֵּיל יְיָ לִי וַאֲקֵיפְנָא יַת טַוְורָא דְגַבְלָא יוֹמִין סַגִּיאִין\",0,0],[4,142,2,2,\"וַאֲמַר יְיָ לִי לְמֵימָר\",0,0],[4,142,2,3,\"סַגִי לְכוֹן דְּאַקֵיפְתּוּן יַת טוּרָא הָדֵין אִיתְפְּנוּ לְכוֹן לְצִפּוּנָא\",0,0],[4,142,2,4,\"וְיַת עַמָּא פַּקֵּיד לְמֵימָר אַתּוּן עָבְרִין בִּתְחוּם אֲחוּכוֹן בְּנוֹי דְעֵשָו דְּיָתְבִין בְּגַבְלָא וִידַחֲלוּן מִנְכוֹן וְתִסְתַּמְרוּן לַחֲדָא\",0,0],[4,142,2,5,\"לָא תִיתְגְּרוּן בְּהוֹן אֲרוּם לָא אֶתֵּן לְכוֹן מֵאַרְעַתְהוֹן עַד כְּמִיסַת פַּרְסַת רִיגְלָא אֲרוּם יְרוּתָא לְעֵשָו יְהָבִית יַת טַוְורָא דְגַבְלָא מְטוֹל אִיקָרָא דְעָבַד לַאֲבוֹי\",0,0],[4,142,2,6,\"עִבּוּרָא תִּזְבּוּן מִנְהוֹן כַּד חַי בְּכַסְפָּא וְתֵיכְלוּן וְאוּף מַיָא תִזְבְּנוּן מִנְהוֹן בְּכַסְפָּא וְתִישְׁתּוּן\",0,0],[4,142,2,7,\"אִזְדַּהֲרוּן דְּלָא תְעִיקוּן לְהוֹן אֲרוּם יְיָ אֱלָהָכוֹן בְּרִיךְ יַתְכוֹן בְּכָל עוֹבְדֵי יְדֵיכוֹן סוּפֵּיק צָרְכֵיכוֹן בְּמֵיהֲכָךְ בְּמַדְבְּרָא רַבָּא הָדֵין דְּנַן אַרְבְּעִין שְׁנִין מֵימְרָא דַיְיָ אֱלָהָכוֹן בְּסַעַדְכוֹן לָא חֲסַרְתּוּן מִדָּעַם\",0,0],[4,142,2,8,\"וְעָבַרְנָא מִלְוַת אָחָנָא בְּנֵי עֵשָו דְּיַתְבוּן בְּגַבְלָא מֵאֵילַת וּמִכְּרַךְ תַּרְנְגוֹלָא וְאִתְפְּנִינָא וְעָבַרְנָא אוֹרַח מַדְבְּרָא דְמוֹאָב\",0,0],[4,142,2,9,\"וַאֲמַר יְיָ לִי לְמֵימָר לָא תָעִיק יַת מוֹאֲבָאֵי וְלָא תְסַדֵּר לְקִבְלֵיהוֹן סִדְרֵי קְרָבָא אֲרוּם לָא אֶתֵּן לְכוֹן מֵאַרְעֲהוֹן יְרוּתָא אֲרוּם לִבְנֵי דְלוֹט יְהָבִית יַת לְחָיַית יְרוּתָא\",0,0],[4,142,2,10,\"אֵימְתָנַיָא מִן לְקַדְמִין יָתִיבוּ בָּהּ עַם רַב וְסַגִי וְחָסִין הֵי כְּגִנְבָּרַיָא\",0,0],[4,142,2,11,\"גִּבָּרַיָא דְיַתְבוּן בְּמֵישַׁר גִּיוֹנְבְּרֵי מִתְחַשְׁבִין אוּף הִינוּן הֵי כְּגִנְבְּרַיָא דְאִתְמְחִיוּ בְּטוּבְעָנָא וּמוֹאֲבָאֵי קְרַן לְהוֹן אֵימְתָנֵי\",0,0],[4,142,2,12,\"וּבְגַבְלָא יָתִיבוּ גְנוּסַיָא מִן לְקַדְמִין וּבְנֵי עֵשָו תְּרָכִינוּן וְשֵׁיצֵיאוּנוּן מִן קֳדָמֵיהוֹן וְיָתִיבוּ בְּאַתְרֵיהוֹן הֵיכְמָא דְעָבַד יִשְרָאֵל לְאַרַע יְרוּתְתֵיהּ דִּיהַב יְיָ לְהוֹן\",0,0],[4,142,2,13,\"כְּדוֹן קוּמוּ וְעִיבְרוּ לְכוֹן יַת נַחַל טַרְוַויָא וְעָבַרְנָא יַת נַחַל טַרְוַויָא\",0,0],[4,142,2,14,\"וְיוֹמַיָא דְהַלִיכְנָא מִן רְקַם גֵּיעָה עַד דְּעָבַרְנָא יַת נַחַל טַרְוַויָא תְּלָתִין וְתַמְנֵי שְׁנִין עַד דְּסַף כָּל דָּרָא גַבְרֵי מַגִּיחֵי קְרָבָא מִגּוֹ מַשְׁרִיתָא הֵיכְמָא דְקַיֵּים יְיָ לְהוֹן\",0,0],[4,142,2,15,\"וְאוּף מְחָא מִן קֳדָם יְיָ אִתְגָרִית בְּהוֹן לְמִשֵׁצְיֵיהוֹן מִגּוֹ מַשְׁרִיתָא עַד דִּי פְּסָקוּ\",0,0],[4,142,2,16,\"וַהֲוָה כַּד פָּסְקָן כָּל גַּבְרֵי מַגִּיחֵי קְרָב עָבְרֵי בִּימָתָא לִמְמַת מִגּוֹ מַשְׁרִיתָא\",0,0],[4,142,2,17,\"וּמַלֵיל יְיָ עִמִּי לְמֵימָר\",0,0],[4,142,2,18,\"אַתּוּן עָבְרִין יוֹמָא דֵין יַת תְּחוּם מוֹאָב יַת לְחָיַית\",0,0],[4,142,2,19,\"וְתִתְקַרְבוּן לְקָבֵיל בְּנֵי עַמּוֹן לָא תְצוּר עֲלֵיהוֹן וְלָא תִתְגְרֵי בְּהוֹן לְסִדְרֵי קְרָב אֲרוּם לָא אֶתֵּן לְכוֹן מֵאַרַע בְּנֵי עַמּוֹן יְרוּתָא אֲרוּם לִבְנוֹי דְלוֹט מְטוֹל זַכְוָותֵיהּ דְּאַבְרָהָם יְהַבְתָּהּ יְרוּתָּא\",0,0],[4,142,2,20,\"אֲרַע גּוּבָּרַיָא מִתְחַשְׁבָא לְחוֹד הִיא גִיבָּרַיָא יְתִיבָן בָּהּ מִן לְקַדְמִין וְעַמּוֹנָאֵי קְרַן לְהוֹן זֵימְתָנֵי\",0,0],[4,142,2,21,\"עַמָּא רַבָּא וַחֲסִינָא הֵי כְּגִנְבָּרַיָא וְשֵׁיצִינוּן מֵימְרָא דַיְיָ מִן קֳדָמֵיהוֹן וְתָרֵיכִינוּן וִיתוּבוּ בְּאַתְרֵיהוֹן\",0,0],[4,142,2,22,\"כְּמָא דַּעֲבַד לִבְנוֹי דְעֵשָו דְּיַתְבִין בְּשֵעִיר דְּשֵׁיצֵי יַת חוֹרָאֵי מִן קֳדָמֵיהוֹן וְתָרֵיכִינוּן וִיתוּבוּ בְּאַתְרֵיהוֹן עַד יוֹמָא הָדֵין\",0,0],[4,142,2,23,\"וּשְׁאָר פְּלֵיטַת כְּנַעֲנָאֵי דַּהֲווֹ שָׁרָן בְּכוּפְרָנַיָא דִפְרִיעַ עַד עַזָּה קַפּוּטְקָאֵי דִנְפָקוּ מִן קַפּוּטְקְיָאָה שֵׁיצֵיאוּנוּן וִיתִיבוּ בְּאַתְרֵיהוֹן\",0,0],[4,142,2,24,\"אִזְדְּקָפוּ טוּלוּ וְעִבְרוּ יַת נַחֲלֵי אַרְנוֹנָא חֲמוֹן דִּי מְסָרִית בִּידֵיכוֹן יַת סִיחוֹן מַלְכָּא דְחֶשְׁבּוֹן אֱמוֹרָאָה וְיַת אַרְעֵיהּ שָׁרֵי לְתַרְכוּתֵיהּ וְתִתְגָרֵי לִמְסַדְרָא לְקוּבְלֵיהּ סִדְרֵי קְרָבָא\",0,0],[4,142,2,25,\"יוֹמָא דֵין שַׁרְיַית לְמִתַּן זַעֲוָותָךְ וְדַחֲלָתָךְ עַל אַנְפֵּי כָּל עַמְמַיָא דִתְחוֹת כָּל שְׁמַיָא דְיִשְׁמְעוּן שְׁמַע זַכְוָותָךְ הֵיךְ קָמוּן שִׁמְשָׁא וְסִיהֲרָא אַמְטוּלְתִּיךְ וּפַסְקִין מִן לְמֵימָר שִׁירָתָא כְּמֵיסַת יוֹמָא וּפַלְגָא קָמוּ בִּמְדוֹרְהוֹן עַד דְּאַגְחַת קְרָבָא בְּסִיחוֹן וִיזָעוּן וִירַתְתוּן מִן קֳדָמָךְ\",0,0],[4,142,2,26,\"וְשַׁדָּרִית אִזְגַדִּין מִנְהַרְדָעָא דְסָמִיךְ לְמַדְבַּר קְדֵמוֹת לְוַת סִיחוֹן מַלְכָּא דֶאֱמוֹרָאֵי פִּתְגָמֵי שְׁלָם לְמֵימָר\",0,0],[4,142,2,27,\"אֲעִיבַר בְּאַרְעָךְ בְּאוֹרְחָא דְהִיא אוֹרַח כְּבִישָׁא אֵיזִיל לָא אַסְטֵי לְהַנְזָקוּתָךְ לְיַמִינָא וְלִשְמָאלָא\",0,0],[4,142,2,28,\"עִבּוּר כַּד חַי בְּכַסְפָּא תַּזְבִּין לִי וְאֵיכוֹל וּמוֹי בְּכַסְפָּא תִתֵּן לִי וְאִישְׁתֵּי לְחוֹד אֲעִבַּר בִּלְחוֹדִי\",0,0],[4,142,2,29,\"הֵיכְמָא דַּעֲבַד לִי בְּנוֹי דְעֵשָו דְּיַתְבִין בְּגַבְלָא וּמוֹאֲבָאֵי דְיַתְבִין בִּלְחָיַית עַד זְמַן דְּאַעִיבַר יַת יוֹרְדְּנָא לְאַרְעָא דַיְיָ אֱלָהָנָא יָהֵיב לָנָא\",0,0],[4,142,2,30,\"וְלָא צָבָא סִיחוֹן מַלְכָּא דְחֶשְׁבּוֹן לְאַעֲבְּרוּתָנָא בְּגוֹ תְחוּמֵיהּ אֲרוּם אַקְשֵׁי יְיָ אֱלָהָךְ יַת יִצְרָא דְרוּחֵיהּ וְאִיתְקַף יַת לִיבְּבֵיהּ מִן בִּגְלַל לְמִמְסְרֵיהּ בִּידָךְ כְּיוֹמָא הָדֵין\",0,0],[4,142,2,31,\"וַאֲמַר יְיָ לִי חָמֵי בְּאוֹרְכוּת שִׁמְשָׁא וְסִיהֲרָא דְשַׁרְיַית לְמִמְסַר בִּידָךְ יַת סִיחוֹן וְיַת אַרְעֵיהּ שָׁרֵי לְתַרְכוּתֵיהּ לְמֵירוֹת יַת אַרְעֵיהּ\",0,0],[4,142,2,32,\"וּנְפַק סִיחוֹן לִקְדָמוּתָנָא הוּא וְכָל עַמֵּיהּ לְאַגָחָא קְרָבָא לְיָהַץ\",0,0],[4,142,2,33,\"וּמְסַר יָתֵיהּ יְיָ אֱלָהָנָא קֳדָמָנָא וּמְחֵינָא יָתֵיהּ וְיַת בְּנוֹי וְיַת כָּל עַמֵּיהּ\",0,0],[4,142,2,34,\"וּכְבַשְׁנָא יַת כָּל קִירְווֹי בְּעִדָנָא הַהִיא וּגְמַרְנָא יַת כָּל קִרְוַיָא גוּבְרַיָא וּנְשַׁיָא וְטַפְלַיָא לָא אַשְׁאַרְנָא מְשֵׁזִיב\",0,0],[4,142,2,35,\"לְחוֹד בְּעִירֵי בַּזָנָא לָנָא וְעָרֵי קִרְוַיָא דִכְבַשְׁנָא\",0,0],[4,142,2,36,\"מֵעֲרוֹעֵר דְּעַל גֵּיף נַחֲלָא דְאַרְנוֹנָא וְקַרְתָּא דְמִתְבַּנְיָא בִּמְצִיעוֹת נַחֲלָא עַד גִּלְעָד לָא הֲוַת קַרְתָּא דִתְקִיפַת מִינָנָא יַת כֻּלְהוֹן מְסַר יְיָ אֱלָהָנָא קֳדָמָנָא\",0,0],[4,142,2,37,\"לְחוֹד לְאַרַע בְּנֵי עַמּוֹן לָא קָרֵבְתָּא כָּל אֲתַר נַחֲלָא יוּבְקָא וְקִרְוֵי טַוְורָא כְּכָל מַה דְּפַקֵּיד יְיָ אֱלָהָנָא\",0,0],[4,142,3,1,\"וְאִתְפְּנֵינָא וְסַלִיקְנָא אוֹרַח מַתְנָן וּנְפַק עוֹג מַלְכָּא דְמַתְנָן לִקֳדָמוּתָנָא הוּא וְכָל עַמֵּיהּ לְאַגָחָא קְרָבָא לְאֶדְרֶעָת\",0,0],[4,142,3,2,\"וַאֲמַר יְיָ לִי לָא תִדְחַל מִנֵיהּ אֲרוּם בִּידָךְ מְסָרִית יָתֵיהּ וְיַת כָּל עַמֵּיהּ וְיַת אַרְעֵיהּ וְתַעֲבֵיד לֵיהּ הֵיכְמָא דַעֲבַדְתָּ לְסִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה דִיתֵיב בְּחֶשְׁבּוֹן\",0,0],[4,142,3,3,\"וּמְסַר יְיָ אֱלָהָנָא בִּידָנָא אוּף יַת עוֹג מַלְכָּא דְמַתְנָן וְיַת כָּל עַמֵּיהּ וּמְחִינוֹהִי עַד דְּלָא אִשְׁתַּיַּיר לֵיהּ מְשֵׁזִיב\",0,0],[4,142,3,4,\"וְכָבַשְׁנָן יַת כָּל קִירְוֵויהּ בְּעִידָנָא הַהִיא לָא הֲוַת קַרְתָּא דְלָא נְסִיבְנָא מִנְהוֹן שִׁתִּין קִרְוִין כָּל תְּחוּם פְּלַךְ טַרְגוֹנָא מַלְכוּתָא דְעוֹג בְּמַתְנָן\",0,0],[4,142,3,5,\"כָּל אִלֵין קִירְוִין חַקְרָא מַקְפִין שׁוּרִין רָמִין אֲחִידָן בְּתַרְעִין וּנְגָרִין בַּר מִקִּרְוֵי פַּצְחַיָיא סַגִי לַחֲדָא\",0,0],[4,142,3,6,\"וּגְמַרְנָא יַת קִירְוֵיהוֹן הֵיכְמָא דַעֲבַדְנָא לְסִיחוֹן מַלְכָּא דְחֶשְׁבּוֹן הֵיכְדֵין גָּמַרְנָא יַת כָּל קִרְוֵוי גוּבְרַיָא נְשַׁיָא וְטַפְלָא\",0,0],[4,142,3,7,\"וְכָל בְּעִירֵי וְעֶדְיֵי קִרְוַיָא בָּזָנָא לָנָא\",0,0],[4,142,3,8,\"וּנְסֵיבְנָא בְּעִידָנָא הַהִיא יַת אַרְעָא מִן רְשׁוּת תְּרֵין מַלְכֵי אֱמוֹרָאֵי דִבְעִיבְרָא דְיוֹרְדְּנָא מִנַּחֲלֵי אַרְנוֹנָא עַד טַוְורָא דְחֶרְמוֹן\",0,0],[4,142,3,9,\"צִידוֹנָאֵי הֲוַון קְרַן לְחֶרְמוֹן טַוְורָא דְמַסְרֵי פֵּירוֹי וֶאֱמוֹרָאֵי קְרַן לֵיהּ טַוָור תַּלְגָא דְלָא פָּסִיק מִנֵיהּ תַּלְגָא לָא בְּקַיְיטָא וְלָא בְּסִתְוָוא\",0,0],[4,142,3,10,\"כָּל קִירְוֵי מֵישְׁרָא וְכָל גִּלְעָד וְכָל מַתְנָן עַד סַלְוָוקִיא וְאֶדְרֶעָת קִרְוֵי מַמְלְכוּתָא דְעוֹג בְּמַתְנָן\",0,0],[4,142,3,11,\"אֲרוּם לְחוֹד עוֹג מַלְכָּא דְמַתְנָן אִשְׁתְּיַיר מִמוֹתַר גִּיבָּרַיָא דְאִשְׁתֵּצְיוּ בְּטוּבְעָנָא הָא שִׁיוְויֵהּ שַׁוְיָא דְפַרְזְלָא הָא הִיא יְהִיבָא בְּבֵית אַרְכֵיוַון בְּרַבַּת בְּנֵי עַמּוֹן תְּשַׁע אַמִּין אוּרְכָּהּ וְאַרְבַּע אַמִּין פּוּתְיָהּ בְּאַמְתָא דְגַרְמֵיהּ\",0,0],[4,142,3,12,\"וְיַת אַרְעָא הֲדָא יְרִיתְנָא בְּעִידָנָא הַהִיא מֵעֲרוֹעֵר וְעַד כֵּיף נַחֲלָא וּפַלְגוּת טַוְורָא דְגִלְעָד וְקִירְוֵיהּ יְהָבִין לְשֵׁבֶט רְאוּבֵן וּלְשֵׁבֶט גָּד\",0,0],[4,142,3,13,\"וּשְׁאָר גִּלְעָד וְכָל מַתְנָן מַלְכוּתֵיהּ דְּעוֹג יְהָבִית לַחֲצִי שֵׁבֶט מְנַשֶּׁה כָּל תְּחוּם בֵּית פְּלַךְ טַרְגוֹנָא וְכָל מַתְנָן הַהוּא מִתְקְרֵי אֲרַע גִּבָּרַיָא\",0,0],[4,142,3,14,\"וְיָאִיר בַּר מְנַשֶּׁה נְסִיב יַת כָּל תְּחוּם פְּלַךְ טַרְגוֹנָא עַד תְּחוּם קִרְוֵי וְאַנְטִיקֵירוֹס וּקְרָא יַתְהוֹן עַל שְׁמֵיהּ יַת מַתְנָן כַּפְרָנֵי יָאִיר עַד יוֹמָא הָדֵין\",0,0],[4,142,3,15,\"וּלְמָכִיר יְהָבִית יַת גִּלְעָד\",0,0],[4,142,3,16,\"וּלְשֵׁבֶט רְאוּבֵן וּלְשֵׁבֶט גָּד יְהָבִית מִן גִּלְעָד וְעַד נַחֲלָאאַרְנוֹנָא מְצִיעוּת נַחֲלָא וּתְחוּמֵיהּ וְעַד יוּבְקָא דְנַחֲלֵי תְּחוּמָא דִבְנֵי עַמּוֹן\",0,0],[4,142,3,17,\"וּמֵישְׁרָא וְיוֹרְדְּנָא וּתְחוּם מִגְנִיסַר וְעַד יַמָּא דְמֵשְׁרָא וְקַרְתָּא טְבַרְיָה דִסְמִיכָא לְיַמָא דְמִלְחָא תְּחוֹת שַׁפְכוּת מַיָא מֵרַמָתָא מַדִּינְחָא\",0,0],[4,142,3,18,\"וּפַקֵּידִית יַתְכוֹן שֵׁבֶט רְאוּבֵן וְשֵׁבֶט גָּד וּפַלְגוּת שֵׁבֶט מְנַשֶּׁה בְּעִידָנָא הַהִיא לְמֵימָר יְיָ אֱלָהָכוֹן יָהִיב לְכוֹן יַת אַרְעָא הָדָא לְמֵירְתָהּ מְזַיְנִין תַּעַבְרוּן קֳדָם אֲחוּכוֹן בְּנֵי יִשְרָאֵל כָּל מְזַרְזֵי חֵילָא\",0,0],[4,142,3,19,\"לְחוֹד נְשֵׁיכוֹן טַפְלְכוֹן וּבְעִירֵיכוֹן יָדַעְנָא אֲרוּם בְּעִיר סַגִי לְכוֹן יֵתְבוּן בְּקִירְוֵיכוֹן דִּי יְהָבִית לְכוֹן\",0,0],[4,142,3,20,\"עַד זְמַן דִּינִיחַ יְיָ לַאֲחוּכוֹן כְּוַותְכוֹן וְיֵירְתוּן אוּף הִינוּן יַת אַרְעָא דַיְיָ אֱלָהָכוֹן יָהִיב לְכוֹן וּתְתוּבוּן גְּבַר לִירוּתָתֵיהּ דִּיהָבִית לְכוֹן\",0,0],[4,142,3,21,\"וְיַת יְהוֹשׁוּעַ פַּקֵדִית בְּעִידָנָא הַהוּא לְמֵימָר עֵינָךְ חַמְיָין יַת כָּל דְּעָבַד יְיָ אֱלָהָךְ לִתְרֵין מַלְכַיָא הָאִילֵין הֵיכְדֵין יַעֲבִיד יְיָ לְכָל מַלְכְוָותָא דְאַנְתְּ עָבַר לְתַמָּן\",0,0],[4,142,3,22,\"לָא תְדַחֲלוּן מִנְהוֹן אֲרוּם מֵימְרָא דַיְיָ אֱלָהָכוֹן מְגִיחַ לְכוֹן\",0,0],[4,142,3,23,\"ואתחנן וּבָעִית רַחֲמִין מִן קֳדָם יְיָ בְּעִידָנָא הַהוּא לְמֵימָר\",0,0],[4,142,3,24,\"בְּבָעוּ בְּרַחֲמִין מִן קֳדָמָךְ יְיָ אֱלהִים אַנְתְּ שָׁרִיתָ לְאַחֲזָאָה יַת עַבְדָךְ יַת רְבוּתָךְ וְיַת גְּבוּרַת יְדָךְ תַּקִיפְתָּא דְאַתְּ הוּא אֱלָהָא וְלָא אִית בַּר מִינָךְ דִּשְׁכִינְתָּךְ שַׁרְיָא בִּשְׁמַיָא מִלְעֵילָא וְשַׁלִּיט בְּאַרְעָא לָא דְיַעֲבֵיד כְּעוֹבָדָךְ וְכִגְבוּרָתָךְ\",0,0],[4,142,3,25,\"אֱעִיבַר כְּדוֹן וְאֶחֱמֵי יַת אַרְעָא טַבְתָא דִבְעִיבְרָא דְיוֹרְדְּנָא טַוְורָא טָבָא דְנַן דְּבֵיהּ מִתְבַּנְיָא קַרְתָּא דִירוּשְׁלֵם וְטַוָור לִיבְנָן דְּבֵיהּ עָתִיד לְמִישְׁרֵי שְׁכִינְתָּא\",0,0],[4,142,3,26,\"וּרְגֵיז יְיָ עָלַי בִּגְלַלְכוֹן וְלָא קַבֵּיל צְלוֹתִי וַאֲמַר יְיָ לִי סַגִי לָךְ לָא תוֹסִיף לְמַלָלָא קָדָמַי תּוּב בְּפִתְגָמָא הָדֵין\",0,0],[4,142,3,27,\"סוּק לְרֵישׁ רָמָתָא וּזְקַף עֵינָךְ לְמַעַרְבָא וּלְצִפּוּנָא וּלְדָרוֹמָא וּלְמַדִינְחָא וַחֲמֵי בְּעֵינָךְ אֲרוּם לָא תְעִיבַר יַת יוֹרְדְּנָא הָדֵין\",0,0],[4,142,3,28,\"וּפַקֵיד יַת יְהוֹשֻׁעַ וּתְקִיפוֹהִי וְאַלִימוֹהִי אֲרוּם הוּא יְעִיבַר קֳדָם עַמָּא הָדֵין וְהוּא יַחֲסִין יַתְהוֹן יַת אַרְעָא דְאַנְתְּ חָמֵי\",0,0],[4,142,3,29,\"וְשָׁרִינָן בְּחֵילְתָא בַּכְיָין עַל חוֹבֵינָן דְּאִיזְדַוֵיגָן לְפַלְחֵי טַעֲוַת פְּעוֹר\",0,0],[4,142,4,1,\"וּכְדוֹן יִשְרָאֵל שְׁמָעוּ לְקַיָּימַיָא וּלְדִינַיָא דַּאֲנָא מַלֵף יַתְכוֹן לְמֶעֱבַד מִן בִּגְלַל דְּתֵיחוֹן וְתֵיעֲלוּן וְתֵירְתוּן יַת אַרְעָא דַיְיָ אֱלָהָא דְאַבְהַתְכוֹן יָהִיב לְכוֹן\",0,0],[4,142,4,2,\"לֵיתְכוֹן רַשָּׁאִין לְמוֹסָפָא עַל פִּתְגָמַיָא דַאֲנָא מְפַקֵּיד יַתְכוֹן וְלָא תְבַצְרוּן מִינֵיהּ מִן לָא לְמִנְטוֹר יַת פִּקּוּדַיָא דַיְיָ אֱלָהָכוֹן דַּאֲנָא מְפַקֵּיד יַתְכוֹן\",0,0],[4,142,4,3,\"עֵינֵיכוֹן חֲמִיתוּן יַת דְּעָבַד מֵימְרָא דַיְיָ בְּפַלְחֵי טַעֲוַות פְּעוֹר אֲרוּם כָּל בַּר נַשׁ דְּטָעָא בָּתַר טַעֲוַות פְּעוֹר שֵׁצְיֵיהּ יְיָ אֱלָהָךְ מִבֵּינָךְ\",0,0],[4,142,4,4,\"וְאַתּוּן דִּדְבַקְתּוּן בְּדַחַלְתָּא דַיְיָ אֱלָהָכוֹן קַיָּימִין כּוּלְכוֹן יוֹמָא דֵין\",0,0],[4,142,4,5,\"חָמוּן דְּאַלֵיפִית יַתְכוֹן קְיָימִין וְדִינִין הֵיכְמָא דְפַקְדַנִי יְיָ אֱלהִים לְמֶעֱבַד הֵיכְנָא בְגוֹ אַרְעָא דְאַתּוּן עָאלִין לְתַמָּן לְמֵירְתָהּ\",0,0],[4,142,4,6,\"וְתִנְטְרוּן וְתַעַבְדוּן יַת אוֹרַיְיתָא אֲרוּם הִוא חָכְמַתְכוֹן וְסוּכְלְתָנוּתְכוֹן לְמֵיחְמֵי עַמְמַיָא דְיִשְׁמְעוּן יַת כָּל קְיָימַיָא הָאִילֵין וְיֵימְרוּן לְחוֹד עַם חַכִּים וְסוּכְלְתָן עַמָא רַבָּא הָדֵין\",0,0],[4,142,4,7,\"אֲרוּם הֵידָא אוּמָא רַבָּא דְּאִית לֵיהּ אֱלָהָא קָרִיב לְוָתֵיהּ בְּשׁוּם מֵימְרָא דַיְיָ אֱלָהֵן אוֹרְחֵיהוֹן דְּעַמְמַיָא נַטְלִין דְחַלְתְּהוֹן עַל כַּתְפֵיהוֹן וְדַמְיַין קְרִיבִין לְהוֹן וְהִינוּן רְחִיקִין מְטוֹל דְּלָא שְׁמָעִין בְּאוּדְנֵיהוֹן בְּרַם מֵימְרָא דַיְיָ יָתִיב עַל כּוּרְסֵיהּ רָם וּמְנַטֵּל וְשָׁמַע צְלוֹתָנָא בְּכָל עִידַן דַּאֲנַן מְצַלְיַין קַמֵיהּ וְעָבִיד בָּעוּתָן\",0,0],[4,142,4,8,\"וְהֵידָא אוּמָא רַבָּא דִילֵיהּ קְיָימִין וְדִינִין תְּרִיצִין כְּכָל אוֹרַיְיתָא הָדָא דַאֲנָא סְדַר קֳדָמֵיכוֹן יוֹמָא דֵין\",0,0],[4,142,4,9,\"לְחוֹד אִסְתַּמְרוּ לְכוֹן וְטוּרוּ נַפְשָׁתֵיכוֹן לַחֲדָא דִלְמָא תִתְנְשׁוּן יַת פִּתְגָמַיָא דַחֲמִיתּוּן בְּסִינַי בְּעֵינֵיכוֹן וְדִלְמָא יְעִידוּן מִן לִבְּכוֹן כָּל יוֹמֵי חַיֵּיכוֹן וּתְלוֹפוּנוּן לִבְנֵיכוֹן וְלִבְנֵי בְנֵיכוֹן\",0,0],[4,142,4,10,\"וְתִדְכּוּן גַּרְמֵיכוֹן בְּמַעַסְקְכוֹן בָּהּ הֵי כְּיוֹמָא דְקַמְתּוּן קֳדָם יְיָ אֱלָהָכוֹן בְּחוֹרֵב בִּזְמַן דַּאֲמַר יְיָ לִי כְּנוֹשׁ קֳדָמַי יַת עַמָא וְאַשְׁמִיעִינוּן יַת פִּתְגָמַי דְּיֵלְפוּן לְמִדְחַל מִן קֳדָמַי כָּל יוֹמַיָא דְהִינוּן קַיְימִין עַל אַרְעָא וְיַת בְּנֵיהוֹן יְאַלִיפוּן\",0,0],[4,142,4,11,\"וְקָרֵיבְתּוּן וְקַמְתּוּן בְּשִׁפּוּלֵי טוּרָא וְטַוְורָא דָלִיק בְּאֵישָׁתָא וְשַׁלְהוֹבֵיהּ מָטֵי עַד צֵית שְׁמַיָא חֲשׁוֹכָא עֲנָנָא וְאַמִיטְתָא\",0,0],[4,142,4,12,\"וּמַלֵּיל יְיָ עִמְכוֹן בְּטוּרָא מִגּוֹ אֵישָׁתָא קַל דְּבִירָא אַתּוּן שָׁמְעִין וּדְמוּ לָא חֲמִיתוּן אֱלָהֵן קַל מְמַלֵּל\",0,0],[4,142,4,13,\"וּתְנֵי לְכוֹן יַת קְיָמֵיהּ דְּפַקֵּיד יַתְכוֹן לְמֶעֱבַד עִישַרְתֵּי דִבּוּרַיָא וְכַתְבִינוּן עַל לוּחֵי סַמְפִּירִינוּן\",0,0],[4,142,4,14,\"וְיָתִי פַקֵּיד יְיָ בְּעִידָנָא הַהִוא לְמַלְפָא יַתְכוֹן קְיָמִין וְדִינִין לְמֶעֱבַדְכוֹן יַתְהוֹן בְּאַרְעָא דְאַתּוּן עָבְרִין לְתַמָּן לְמֵירְתָהּ\",0,0],[4,142,4,15,\"וְתִסְתַּמְרוּן לַחֲדָא לְנַפְשָׁתֵיכוֹן אֲרוּם לָא חֲמִיתוּן כָּל דְּמוּ בְּיוֹמָא דְמַלֵּיל יְיָ עִמְכוֹן בְּחוֹרֵב מִגּוֹ אֵישָׁתָא\",0,0],[4,142,4,16,\"הֲווֹ זְהִירִין דְּלָא תְחַבְּלוּן עוֹבָדֵיכוֹן וְתַעַבְדוּן לְכוֹן צְלַם דְּמוּ דְּכָל טָעוּ דְמוּ דִדְכַר אוֹ דְנוּקְבָא\",0,0],[4,142,4,17,\"דְּמוּ דְכָל בְּעִירָא דִי בְאַרְעָא דְמוּ דְכָל צִפַּר גַּפָּא דְפָרְחָא בְאֲוִיר רְקִיעַ שְׁמַיָא\",0,0],[4,142,4,18,\"דְּמוּ דְּכָל רִיחֲשָׁא דִבְאַרְעָא דְמוּ כָּל נוּנֵי דִבְמַיָא מִלְרַע לְאַרְעָא\",0,0],[4,142,4,19,\"וְדִלְמָא תִתְּלוּן עֵינֵיכוֹן לְצֵית שְׁמַיָא וְתֶחֱמוּן יַת שִׁמְשָׁא וְיַת זִיהֲרָא וְיַת רֵישֵׁי כּוֹכְבַיָא כָּל חֵילֵי שְׁמַיָא וְתִטְעוּן וְתִסְגְּדוּן לְהוֹן וְתִפְלְחִינוּן דְּפַלֵיג יְיָ אֱלָהָכוֹן בְּהוֹן דַּעְתְּהוֹן דְּכָל עַמְמַיָא דִתְחוֹת כָּל שְׁמַיָא\",0,0],[4,142,4,20,\"וְיַתְכוֹן נְסִיב מֵימְרָא דַיְיָ לְחוּלְקֵיהּ וְאַנְפֵּיק יַתְכוֹן מִנִיר פַּרְזְלָא מִמִּצְרַיִם מְטוֹל לְמֶהֱוֵי לֵיהּ לְעַם אַחֲסָנָא כְּיוֹמָא הָדֵין\",0,0],[4,142,4,21,\"וּמִן קֳדָם יְיָ הֲוָה רְגַז עָלַי עַל פִּתְגָמֵיכוֹן דְּאִתְרַעַמְתּוּן עַל מַיָא וְקַיֵּים דְּלָא אֲעִיבַר יַת יוֹרְדְּנָא וּדְלָא אֵיעוּל לְאַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן אַחֲסָנָא\",0,0],[4,142,4,22,\"אֲרוּם אֲנָא שְׁכִיב בְּאַרְעָא הָדָא לֵית אֲנָא עָבַר יַת יַרְדְּנָא וְאַתּוּן עָבְרִין וְתֵירְתוּן יַת אַרְעָא טַבְתָא הָדָא\",0,0],[4,142,4,23,\"אִסְתַּמְרוּ לְכוֹן דִּלְמָא תִתְנְשׁוּן יַת קְיָמָא דַיְיָ אֱלָהָכוֹן דִּגְזַר עִמְכוֹן וְתַעַבְדוּן לְכוֹן צְלַם דְּמוּת כּוֹלָא דְפַקְדִינְכוֹן יְיָ אֱלָהָכוֹן דְּלָא לְמֶעֱבַד\",0,0],[4,142,4,24,\"אֲרוּם יְיָ אֱלָהָכוֹן מֵימְרֵיהּ אֵישָׁא אָכְלָא אֵישָׁא הוּא אֱלָהָא קַנָאִי וּמִתְפְּרַע בְּקִנְאָה\",0,0],[4,142,4,25,\"אֲרוּם תֵּלְדוּן בְּנִין וּבְנֵי בְנִין וְתִתְעַתְּקוּן בְּאַרְעָא וּתְחַבְּלוּן עוֹבָדֵיכוֹן וְתַעַבְדוּן לְכוֹן צְלַם דְּמוּת כּוֹלָא וְתַעַבְדוּן דְּבִישׁ קֳדָם יְיָ אֱלָהָכוֹן לְאַרְגָזָא קֳדָמוֹי\",0,0],[4,142,4,26,\"אַסְהֵידִית בְּכוֹן יוֹמָא דֵין סַהֲדִין קַיְימִין יַת שְׁמַיָא וְיַת אַרְעָא אֲרוּם מֵיבַד תּוֹבְדוּן בְּסַרְהוּבַיָא מֵעִילַוֵי אַרְעָא דְאַתּוּן עָבְרִין יַת יוֹרְדְּנָא תַמָּן לְמֵירְתָהּ לָא תוֹרְכוּן יוֹמִין עֲלָהּ אֲרוּם מִשְׁתֵּצְיָא תִשְׁתֵּיצוּן\",0,0],[4,142,4,27,\"וִיבַדַר יְיָ יַתְכוֹן בֵּינֵי עַמְמַיָא וְתִשְׁתּוֹתְרוּן בְּעָם קָלִיל בֵּינֵי עַמְמַיָא דִיבַדַר יְיָ יַתְכוֹן תַּמָּן בְּגָלוּתָא\",0,0],[4,142,4,28,\"וְתִיתְעוּקוּן לְמִפְלַח תַּמָּן לְפַלְחֵי טַעֲוָותָא עוֹבַד אִידֵיהוֹן דִּבְנֵי נְשָׁא מִן קֵיסָא וְאַבְנָא דְלָא חַמְיָין וְלָא שָׁמְעִין וְלָא אָכְלִין וְלָא מְרִיחִין\",0,0],[4,142,4,29,\"וְתִתְבְּעוּן מִתַּמָּן לְמִיתַב לִדְחַלְתָּא דַיְיָ אֱלָהָכוֹן וְתִשְׁכְּחוּן רַחֲמִין אֲרוּם תִּבְעוּן מִן קֳדָמוֹי בְּכָל לִבְּכוֹן וּבְכָל נַפְשֵׁיכוֹן\",0,0],[4,142,4,30,\"כַּד תֵּיעוֹק לְכוֹן וִיאַרְעוּן לְכוֹן כָּל פִּתְגָמַיָא הָאִילֵין בְּסוֹף יוֹמַיָא וּתְתוּבוּן עַד דַּחַלְתָּא דַיְיָ אֱלָהָכוֹן וּתְקַבְּלוּן לְמֵימְרֵיהּ\",0,0],[4,142,4,31,\"אֲרוּם אֱלָהָא רַחֲמָנָא יְיָ אֱלָהָכוֹן לָא יִשְׁבְּקִנְכוֹן וְלָא יִחְבַּלְכוֹן וְלָא יִתְנְשֵׁי יַת קְיָימָא דְאַבָהַתְכוֹן דְּקַיַּים לְהוֹן\",0,0],[4,142,4,32,\"אֲרוּם שַׁיִיל כְּדוֹן לְדָרַיָא דְמִן יוֹמֵי שִׁירוּיָיא דַהֲווֹ קֳדָמָךְ לְמִן יוֹמָא דִבְרָא יְיָ אָדָם עַל אַרְעָא וּלְמִסְיָיפֵי שְׁמַיָא וְעַד סְיָיפֵי שְׁמַיָא הַהֲוָה הֵיךְ פִּתְגָמָא רַבָּא הָדֵין אוֹ הַאִשְׁתְּמַע דִּכְוָותֵיהּ\",0,0],[4,142,4,33,\"הַאֶפְשָׁר דְּשָׁמַע עַמָא קַל מֵימְרָא דַיְיָ אֱלָהָא קַיֵּם דִּמְמַלֵל מִגּוֹ אֵישָׁא הֵיכְמָא דִשְׁמַעְתּוּן אַתּוּן וְאִתְקַיָּים\",0,0],[4,142,4,34,\"אוֹ הֵיךְ נִיסָא דְעָבַד יְיָ לְאִתְגְּלָאָה לְמִפְרְשָׁא לֵיהּ אוּמָא בְּפִיצְתָא מִגּוֹ עָם אוֹחֲרֵי בְּנִיסִין בְּאָתִין וּבְתִמְהִין וּבְסִדְרֵי נִצְחָנֵי קְרָבִין וּבְאֶדְרַע מְרַמֵם וּבְחֶזְוָנֵי רַבְרְבִין הֵי כְּכָל מַה דְּעָבַד לְכוֹן יְיָ אֱלָהָכוֹן בְּמִצְרַיִם וְעֵינֵיכוֹן חַמְיָין\",0,0],[4,142,4,35,\"אַנְתְּ אִיתְחָמֵיתָא יַת פְּרִישָׁתָא הָאִלֵּין מְטוּל לְמִנְדַע אֲרוּם יְיָ הוּא אֱלָהָא לֵית תּוּב בַּר מִינֵיהּ\",0,0],[4,142,4,36,\"מִשְׁמֵי מְרוֹמָא אַשְׁמָעִינְכוֹן יַת קַל מֵימְרֵיהּ לִמְכַסְנָא יַתְכוֹן בְּאוּלְפָנֵיהּ וְעִילַוֵי אַרְעָא אַחֲמִינְכוֹן יַת אֵישָׁתֵיהּ רַבְּתָא וּפִתְגָמוֹי שְׁמַעְתּוּן מִגּוֹ אֵישָׁתָא\",0,0],[4,142,4,37,\"וְחוֹלַף דִּרֵחֵים יַת אֲבָהַתְכוֹן אַבְרָהָם וְיִצְחָק וְאִתְרְעֵי בִּבְנוֹי דְיַעֲקב בַּתְרוֹי וְאַפְקִינְכוֹן בְּאַפֵּי רְעוּתֵיהּ בְּחֵילֵיהּ רַב מִמִּצְרָיִם\",0,0],[4,142,4,38,\"לְתַרְכָא עַמְמִין רַבְרְבִין וְתַקִּיפִין מִנְכוֹן מִן קֳדָמֵיכוֹן לְאַעֲלוּתְכוֹן לְמִתַּן לְכוֹן יַת אַרְעֲהוֹן אַחְסָנָא כְּיוֹמָא הָדֵין\",0,0],[4,142,4,39,\"וְתִנְדְּעוּן יוֹמָא דֵין וּתְתוּבוּן עַל לִבְּכוֹן אֲרוּם יְיָ אֱלהִים דִּשְׁכִינְתֵּיהּ שַׁרְיָא בִּשְׁמַיָא מִלְעֵילָא וְשַׁלִּיט עַל אַרְעָא מִלְרַע לֵית חוֹרָן בַּר מִנֵיהּ\",0,0],[4,142,4,40,\"וְתִנְטְרוּן יַת קְיָימוֹי וְיַת פִּקּוּדוֹי דַּאֲנָא מְפַקֵיד לְכוֹן יוֹמָא דֵין דְּיוֹטִיב לְכוֹן וְלִבְנֵיכוֹן בַּתְרֵיכוֹן וּמִן בִּגְלַל דְּתִינְגְּדוּן יוֹמָא דֵין עַל אַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן כָּל יוֹמַיָא\",0,0],[4,142,4,41,\"הָא בְּכֵן אַפְרֵשׁ משֶׁה תְּלַת קִרְוִין בְּעִבְרָא דְיוֹרְדְּנָא מַדְנַח שִׁמְשָׁא\",0,0],[4,142,4,42,\"לְמֵעֲרוֹק לְתַמָּן קָטוֹלָא דְיִקְטוֹל יַת חַבְרֵיהּ וְלָא אִתְכְּוַון וְהוּא לָא שָנֵי לֵיהּ מֵאִיתְמְלֵי וּמִדְקָמוֹהִי וְיֵעִירוֹק לַחֲדָא מִקִּרְוַויָא הָאִלֵין וְיִתְקַיָּים\",0,0],[4,142,4,43,\"יַת כְּוָתִירִין בְּמַדְבְּרָא בְּאַרַע מִישְׁרָא לְשֵׁבֶט רְאוּבֵן וְיַת רָמָתָא בְגִלְעָד לְשֵׁבֶט גָּד וְיַת דַּבְרָא בְּמַתְנָן לְשֵׁבֶט מְנַשֶּׁה\",0,0],[4,142,4,44,\"וְדָא אַחְוָיַת אוֹרַיְיתָא דִי סַדֵּר משֶׁה קֳדָם בְּנֵי יִשְרָאֵל\",0,0],[4,142,4,45,\"אִלֵין סָהִידְוָותָא וּקְיָמַיָא וְדִינַיָא דְמַלֵיל משֶׁה עִם בְּנֵי יִשְרָאֵל בִּזְמַן מִפַּקְהוֹן מִמִּצְרָיִם\",0,0],[4,142,4,46,\"וּתְנָנוּן משֶׁה בְּעִבְרָא דְיוֹרְדְּנָא בְּחֵילְתָא לְקָבֵיל בֵּית פְּעוֹר בְּאַרַע סִיחוֹן מַלְכָּא דֶאֱמוֹרָאֵי דְיָתֵיב בְּחוּשְׁבְּנָא דִמְחָא משֶׁה וּבְנֵי יִשְרָאֵל בְּמִפַּקְהוֹן מִמִּצְרָיִם\",0,0],[4,142,4,47,\"וְיָרִיתוּ יַת אַרְעֵיהּ וְיַת אַרְעָא דְעוֹג מַלְכָּא דְמַתְנָן תְּרֵין מַלְכֵי אֱמוֹרָאָה דִבְעִיבְרָא דְיוֹרְדְּנָא מַדְנַח שִׁמְשָׁא\",0,0],[4,142,4,48,\"מֵעֲרוֹעֵר דְּעַל גֵּיף נַחֲלֵי אַרְנוֹן וְעַד טַוְורָא דְסִיאוֹן הוּא טַוָור תַּלְגָא\",0,0],[4,142,4,49,\"וְכָל מֵישְׁרָא עִיבְרָא דְיוֹרְדְּנָא מַדִּינְחָא וְעַד יַמָא דְמֵישְׁרָא תְּחוֹת מַשְׁפַּךְ מְרָמָתָא\",0,0],[4,142,5,1,\"וּקְרָא משֶׁה לְכָל יִשְרָאֵל וַאֲמַר לְהוֹן שְׁמָעוּ יִשְרָאֵל יַת קְיָמַיָא וְיַת דִּינַיָא דַאֲנָא מְמַלֵיל קֳדָמֵיכוֹן יוֹמָא דֵין וְתִילְפוּן יַתְהוֹן וְתִינְטְרוּן לְמֶעֱבַדְהוֹן\",0,0],[4,142,5,2,\"יְיָ אֱלָהָנָא גְּזַר עִמָנָא קְיָים בְּחוֹרֵב\",0,0],[4,142,5,3,\"לָא עִם אַבְהָתָנָא גְזַר יְיָ יַת קְיָימָא הָדֵין אֱלָהֵן עִמָנָא אֲנַחְנָא אִלֵין הָכָא יוֹמָא דֵין כּוּלָנָא חַיִּין וְקַיָּימִין\",0,0],[4,142,5,4,\"מַמְלֵיל קֳבֵיל מַמְלֵיל מַלֵיל יְיָ עִמְכוֹן בְּטַוְורָא מִגוֹ אֵשָׁתָא\",0,0],[4,142,5,5,\"אֲנָא הֲוֵית קָאֵים בֵּין מֵימְרָא דַיְיָ וּבֵינֵיכוֹן בְּעִידָנָא הַהוּא לְמִתְנַיָא לְכוֹן יַת פִּתְגָמַיָא דַיְיָ אֲרוּם דְּחֵלְתּוּן מִן קֳדָם קַל מֵימְרָא דַיְיָ דְּמִשְׁתַּמַע מִגוֹ אֵישָׁתָא וְלָא סְלֵיקְתּוּן בְּטוּרָא כַּד אָמַר\",0,0],[4,142,5,6,\"עַמִּי בְּנֵי יִשְרָאֵל אֲנָא הוּא יְיָ אֱלָהָכוֹן דִּי פְרָקִית וְאַפֵּיקִית יַתְכוֹן פְּרִיקִין מִן אַרְעָא דְמִצְרָאֵי מִבֵּית שִׁעֲבּוּד עַבְדַיָא\",0,0],[4,142,5,7,\"עַמִּי בְּנֵי יִשְרָאֵל לָא יֶהֱוֵי לְכוֹן אֱלָהָא אוֹחֲרָן בַּר מִינִי\",0,0],[4,142,5,8,\"וְלָא תַעַבְדוּן לְכוֹן צְלַם וְכָל דְּמוּ דְבִשְׁמַיָא מִלְעֵיל וְדִי בְאַרְעָא מִלְרַע וְדִי בְמַיָא מִלְרַע לְאַרְעָא\",0,0],[4,142,5,9,\"לָא תִסְגְּדוּן לְהוֹן וְלָא תִפְלְחוּן קֳדָמֵיהוֹן אֲרוּם אֲנָא הוּא יְיָ אֱלָהָכוֹן אֱלָהּ קַנְאָן וּפוּרְעָן וּמִתְפְּרַע בְּקִנְאָה מַדְכַּר חוֹבֵי אַבְהָן רַשִׁיעָן עַל בְּנִין מְרוֹדִין עַל דַּר תְּלִיתָאֵי וְעַל דַּר רְבִיעָאֵי לְסַנְאַי כַּד מְשַׁלְמִין בְּנַיָא לְמֶחֱטֵי בָּתַר אַבְהַתְהוֹן\",0,0],[4,142,5,10,\"וּנְטִיר חֶסֶד וְטִיבוּ לְאַלְפֵי דָרִין לְרַחֲמֵי צַדִּיקַיָא וּלְנַטְרֵי פִּקוּדַי וְאוֹרַיְיתָי\",0,0],[4,142,5,11,\"עַמִּי בְּנֵי יִשְרָאֵל לָא יִשְׁתְּבַּע חָד מִנְכוֹן בְּשׁוּם מֵימְרֵיהּ דַיְיָ אֱלָהָכוֹן עַל מַגַן אֲרוּם לָא מְזַכֵּי יְיָ בְּיוֹם דִינָא רַבָּא יַת כָּל מַאן דְּמִשְׁתְּבַּע בִּשְׁמֵיהּ עַל מַגָן\",0,0],[4,142,5,12,\"עַמִי בְּנֵי יִשְרָאֵל הֲווֹ נַטְרִין יַת יוֹמָא דְשַׁבְּתָא לִמְקַדְשָׁא יָתֵיהּ הֵיכְמָא דְפַקֵּיד יַתְכוֹן יְיָ אֱלָהָכוֹן\",0,0],[4,142,5,13,\"שִׁתָּא יוֹמִין תִּפְלְחוּן וְתַעַבְדוּן כָּל עִיבִידְתְּכוֹן\",0,0],[4,142,5,14,\"וְיוֹמָא שְׁבִיעָאָה שַׁב וְנַיַיח קֳדָם יְיָ אֱלָהָכוֹן לָא תַעַבְדוּן כָּל עִיבִידְתָּא אַתּוּן וּבְנֵיכוֹן וּבְנָתֵיכוֹן וְעַבְדֵיכוֹן וְאַמְהָתֵיכוֹן וְתוֹרֵיכוֹן וְחַמְרֵיכוֹן וְכָל בְּעִירֵיכוֹן וְגִיוֹרֵיכוֹן דִּי בְקִרְוֵיכוֹן מִן בִּגְלַל דִּינוּחוּן עַבְדֵיכוֹן וְאַמְהָתֵיכוֹן כְּוַותְכוֹן\",0,0],[4,142,5,15,\"וְתֶהֱווֹן דְּכִירִין אֲרוּם מְשַׁעְבְּדוּן הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם וּפְרַק וְאַפֵּיק יְיָ אֱלָהָכוֹן יַתְכוֹן מִתַּמָּן בִּידָא תַּקִּיפָא וּבִדְרַע מְרַמַּם בְּגִין כֵּן פַּקְדָךְ יְיָ אֱלָהָךְ לְמֶעֱבַד יַת יוֹמָא דְשַׁבְּתָא\",0,0],[4,142,5,16,\"עַמִי בְּנֵי יִשְרָאֵל הֲווֹ זְהִירִין גְּבַר בְּאִיקָרָא דְאָבוֹי וּבְאִיקָרָא דְאִימֵיהּ הֵיכְמָא דְפַקִידְכוֹן יְיָ אֱלָהָכוֹן מִן בִּגְלַל דְּיוֹרְכוּן יְמֵיכוֹן וּמִן בִּגְלַל דְּיֵיטַב לְכוֹן עַל אַרְעָא דַיְיָ אֱלָהָכוֹן יָהִיב לְכוֹן\",0,0],[4,142,5,17,\"עַמִי בְּנֵי יִשְרָאֵל לָא תֶהֱווֹן קָטוֹלִין לָא חַבְרִין וְלָא שׁוּתָּפִין עִם קָטוֹלִין וְלָא יִתְחָמֵי בִּכְנִישַׁתְהוֹן דְּיִשְרָאֵל עִם קָטוֹלִין דְּלָא יְקוּמוּן בְּנֵיכוֹן מִן בַּתְרֵיכוֹן וְיֵלְפוּן לְהוֹן הִינוּן לְמֶהֱוֵי עִם קָטוֹלִין אֲרוּם בְּחוֹבֵי קָטוֹלַיָא חַרְבָּא נָפִיק עַל עַלְמָא עַמִי בְּנֵי יִשְרָאֵל לָא תֶהֱווֹן גִּיּוֹרִין לָא חַבְרִין וְלָא שׁוּתָּפִין עִם גִּיּוֹרִין וְלָא יִתְחָמֵי בִּכְנִישַׁתְהוֹן דְּיִשְרָאֵל עִם גִּיּוֹרִין דְּלָא יְקוּמוּן בְּנֵיכוֹן מִן בַּתְרֵיכוֹן וְיֵלְפוּן לְהוֹן הִינוּן לְמֶהֱוֵי עִם גִּיּוֹרִין אֲרוּם בְּחוֹבֵי גִיוֹרָא מוֹתָא נָפִיק עַל עַלְמָא עַמִי בְּנֵי יִשְרָאֵל לָא תֶהֱווֹן גַּנָּבִין לָא חַבְרִין וְלָא שׁוּתָּפִין עִם גַּנָּבִין וְלָא יִתְחָמֵי בִּכְנִישַׁתְהוֹן דְּיִשְרָאֵל עִם גַּנָּבִין אֲרוּם בְּחוֹבֵי גַנָבַיָא כַּפְנָא נָפִיק עַל עַלְמָא עַמִּי בְּנֵי יִשְרָאֵל לָא תֶהֱווֹן מְסַהֲדִין סַהֲדֵי דְשִׁיקְרָא לָא חַבְרִין וְלָא שׁוּתָּפִין עִם מְסַהֲדֵי סַהֲדֵי דְשִׁיקְרָא וְלָא יִתְחָמֵי בִּכְנִישַׁתְהוֹן דְּיִשְרָאֵל עִם מְסַהֲדִין סַהֲדֵי דְשִׁקְרָא אֲרוּם בְּחוֹבֵי מְסַהֲדֵי שִׁקְרָא עֲנָנִין סַלְקִין וּמִטְרָא לָא נָחִית וּבַצוֹרְתָא אָתֵי עַל עַלְמָא\",0,0],[4,142,5,18,\"עַמִּי בְּנֵי יִשְרָאֵל לָא תֶהֱווֹן חֲמוּדִין לָא חַבְרִין וְלָא שׁוּתָּפִין עִם חֲמוּדִין וְלָא יִתְחָמֵי בִּכְנִישַׁתְהוֹן דְּיִשְרָאֵל עִם חֲמוּדִין דְּלָא יְקוּמוּן בְּנֵיכוֹן מִן בַּתְרֵיכוֹן וְיֵלְפוּן לְהוֹן אִינוּן לְמֶהֱוֵי עִם חֲמוּדִין וְלָא יֵירוֹג חָד מִנְכוֹן יַת אִנְתְּתֵיהּ דְּחַבְרֵיהּ וְלָא יֵירוֹג חַד מִנְכוֹן יַת בֵּיתֵיהּ דְּחַבְרֵיהּ וְלָא חַקְלֵיהּ וְלָא עַבְדֵיהּ וְלָא אַמְתֵיהּ וְלָא תּוֹרֵיהּ וְלָא חַמְרֵיהּ וְלָא כָּל מַאן דְּאִית לְחַבְרֵיהּ אֲרוּם בְּחוֹבֵי חֲמוּדַיָא מַלְכוּתָא מִתְגַרְיָא בְּנִכְסֵיהוֹן דִּבְנֵי נְשָׁא לְמֵסַב יַתְהוֹן וְגָלוּתָא אַתְיָא עַל עַלְמָא\",0,0],[4,142,5,19,\"יַת פִּתְגָמַיָא הָאִלֵין מַלֵיל יְיָ עִם כָּל קְהַלְכוֹן בְּטַוְורָא מִגּוֹ אֵישָׁתָא עֲנָנָא וַאֲמִיטְתָא קַל רַב דְּלָא פָּסִיק וַהֲוָה קַל דְּבִירָא מִתְכְּתֵיב עַל תְּרֵין לוּחֵי מַרְמִירִין וִיהָבִינוּן לִי\",0,0],[4,142,5,20,\"וַהֲוָה כֵּיוַן דִּשְׁמַעְתּוּן יַת קַל דִּבְרָא מִגּוֹ חֲשׁוֹכָא וְטַוְורָא דָלִיק בְּאֵישָׁתָא וְקָרֵיבְתּוּן לְוָתִי כָּל רֵישֵׁי שִׁבְטֵיכוֹן וְחַכִּימֵיכוֹן\",0,0],[4,142,5,21,\"וַאֲמַרְתּוּן הָא אַחֲמֵי יָתוּן מֵימְרָא דַיְיָ אֱלָהָנָא יַת שְׁכִינַת יְקָרֵיהּ וְיַת רְבוּת תּוּשְׁבַּחְתֵּיהּ וְיַת קַל מֵימְרֵיהּ שְׁמַעְנָא מִגוֹ אֵישָׁתָא יוֹמָא הָדֵין חָמֵינָא אֲרוּם מְמַלֵל יְיָ עִם בַּר נַשׁ דְּרוּחַ קַדִּישָׁא בֵּיהּ וּמִתְקַיֵּים\",0,0],[4,142,5,22,\"וּכְדוֹן לְמָא נְמוּת אֲרוּם תֵּיכְלִינָנָא אֵישָׁתָא רַבְּתָא הָדֵין אִין מוֹסִיפִין אֲנַחְנָא לְמִשְׁמַע יַת קַל מֵימְרָא דַיְיָ אֱלָהָנָא תּוּב וּמַיְיתִין אֲנַחְנָא\",0,0],[4,142,5,23,\"אֲרוּם הֵי דֵין כָּל בַּר בִּישְרָא דְשָׁמַע קַל מֵימְרָא דֶאֱלָהָא קַיֵּים מְמַלֵּיל מִגּוֹ אֵישָׁתָא כְּוָותָנָא וְאִתְקַיֵּים\",0,0],[4,142,5,24,\"קְרֵיב אַתְּ וְתִשְׁמַע יַת כָּל מַה דְּיֵימַר יְיָ אֱלָהָנָא וְאַנְתְּ תְּמַלֵּיל עִמָּנָא יַת כָּל דִּימַלֵיל יְיָ אֱלָהָנָא לָךְ וּנְקַבֵּיל וְנַעֲבֵיד\",0,0],[4,142,5,25,\"וּשְׁמַע קֳדָם יְיָ יַת קַל פִּתְגָמֵיכוֹן בְּמַלָּלוּתְכוֹן עִמִּי וַאֲמַר יְיָ לִי שְׁמִיעַ קֳדָמַי יַת קַל פִּתְגָמֵי עַמָא הָדֵין דְּמַלִילוּ עִמָךְ אוֹטִיבוּ כָּל מַה דִּי מַלִּילוּ\",0,0],[4,142,5,26,\"לְוַאי דִיהֵי יִצְרָא דְלִבְּהוֹן שְׁלִים בִּרְעוּת דֵּין לְהוֹן לְמִדְחַל מִן קֳדָמַי לְמִנְטוֹר יַת כָּל פִּקּוּדַי כָּל יוֹמַיָא מִן בִּגְלַל דְּיוֹטִיב לְהוֹן וְלִבְנֵיהוֹן לְעַלָם\",0,0],[4,142,5,27,\"אִיזֵל אֵימַר לְהוֹן שָׁרֵי לְכוֹן לְאִזְדַוְוגָא עִם נְשֵׁיכוֹן דְּאִתְפַּרַשְׁתּוּן דְּנַן תְּלָתָא יוֹמִין\",0,0],[4,142,5,28,\"וְאַנְתְּ פְּרַשׁ מִן אִנְתְּתָךְ מְטוּל דִּבְסִדְרֵי דִלְעֵיל אַנְתְּ קָאֵי לְגַבִּי וַאֲמַלֵל עִמָךְ יַת תַּפְקִידַיָא וּקְיָמַיָא וְדִינַיָא דְּתַלְפִין יַתְהוֹן וְיַעַבְדוּן בְּאַרְעָא דַאֲנָא יָהִיב לְהוֹן לְמֵירְתָהּ\",0,0],[4,142,5,29,\"וּכְדוֹן טוּרוּ לְמֶעֱבַד הֵיכְמָא דְפַקֵּיד יְיָ אֱלָהָכוֹן יַתְכוֹן לָא תִסְטוּן לְיַמִינָא וְלִשְמָאלָא\",0,0],[4,142,5,30,\"בְּכָל אָרְחָא דְפַקֵּיד יְיָ אֱלָהָכוֹן יַתְכוֹן תְּהָכוּן מִן בִּגְלַל דְּתֵיחוּן וְיוֹטִיב לְכוֹן וְתוֹרְכוּן יוֹמִין בְּאַרְעָא דְתֵירְתוּן\",0,0],[4,142,6,1,\"וְדָא אַחְוָויַת תַּפְקֵידְתָּא קְיָימַיָא וְדִינַיָיא דְפַקֵּיד יְיָ אֱלָהָכוֹן לְמֵילְפָא יַתְכוֹן לְמֶעֱבַד בְּאַרְעָא דְאַתּוּן עָבְרִין לְתַמָּן לְמֵירְתָהּ\",0,0],[4,142,6,2,\"מִן בִּגְלַל דְּתִדְחַל קֳדָם יְיָ אֱלָהָךְ לְמִנְטַר כָּל קְיָימוֹהִי וּפִיקוּדוֹהִי דַאֲנָא מְפַקֵיד לָךְ אַנְתְּ וּבְרָךְ וּבַר בְּרָךְ כָּל יוֹמֵי חַיָּיךְ וּמִן בִּגְלַל דְּיוֹרְכוּן יוֹמָךְ\",0,0],[4,142,6,3,\"וּתְקַבֵּיל יִשְרָאֵל וְתִנְטוֹר לְמֶעֱבַד מְטוּל דְּיוֹטֵב לָךְ וְתִסְגוּן לַחֲדָא הֵיכְמָא דְמַלֵיל יְיָ אֱלָהָא דְאַבְהָתָךְ לָךְ אֲרַע דְּפֵירָהָא שְׁמֵינִין כַּחֲלָב וְחַלְיָין כִּדְבָשׁ\",0,0],[4,142,6,4,\"וַהֲוָה כֵּיוַן דְּמָטָא זִימְנֵיהּ דְּיַעֲקב אָבוּנָן לְמִתְכַּנְשָׁא מִגּוֹ עַלְמָא הֲוָה מִסְתְּפֵי דִלְמָא אִית בִּבְנוֹי פְּסוּלָא קָרָא יַתְהוֹן וְשַׁיְילִינוּן דִּלְמָא אִית בְּלִבְּכוֹן עַקְמָנוּתָא אָתִיבוּ כֻּלְהוֹן כַּחֲדָא וַאֲמָרוּ לֵיהּ שְׁמַע יִשְרָאֵל אָבוּנָן יְיָ אֱלָהָנָא יְיָ חָד עָנֵי יַעֲקב וַאֲמַר בְּרִיךְ שׁוּם יְקָרֵיהּ לְעָלְמֵי עַלְמִין\",0,0],[4,142,6,5,\"אָמַר משֶׁה נְבִיָא לְעַמָּא בֵּית יִשְרָאֵל אִיזִילוּ בָּתַר פּוּלְחָנָא קְשִׁיטָא דְאַבְהַתְכוֹן וּתְרַחֲמוּן יַת יְיָ אֱלָהָכוֹן בִּתְרֵי יִצְרֵי לִבְּכוֹן וַאֲפִילוּ נְסִיב יַת נַפְשְׁכוֹן וּבְכָל מָמוֹנְכוֹן\",0,0],[4,142,6,6,\"וִיהוֹן פִּתְגָמַיָא הָאִלֵין דַּאֲנָא מְפַקֵיד יַתְכוֹן יוֹמָא דֵין כְּתִיבִין עַל לוּחַ לִבְּכוֹן\",0,0],[4,142,6,7,\"וְתִגְמְרִינוּן לִבְנָךְ וְתֶהֶוְיַין הַנְיַין בְּהוֹן בְּמוֹתְבֵיכוֹן בְּבָתֵּיכוֹן בִּזְמַן מֵיעַסוּקְכוֹן בְּחִיתוּנְכוֹן וּבְמֵיהֲכוֹן בְּאוֹרְחֲכוֹן וּבְפַנְיָא סְמִיךְ לְמִשְׁכָּבֵיכוֹן וּבְצַפְרָא סְמִיךְ לְמִקְמֵיכוֹן\",0,0],[4,142,6,8,\"וְתִקְטוּרִינוּן לְאָתִין כְּתִיבִין עַל יְדָךְ דִּשְמָאלָא וִיהֲווֹן לִתְפִילִין עַל מוֹקְדָךְ כֻּלּוֹ קָבֵיל עַל עֵינָךְ\",0,0],[4,142,6,9,\"וְתִכְתּוֹבִינִין עַל מְזוּזְיַין וְתִקְבְּעִינוּן בְּתוֹלְתָא לְקָבֵיל תַּקֵּי עַל סֵיפֵי בֵּיתָךְ וּבְתַרְעָךְ מִימִינָא בְּמֵעֲלָךְ\",0,0],[4,142,6,10,\"וִיהֵי אֲרוּם יָעֵלִינָךְ יְיָ אֱלָהָךְ לְאַרַע דְּקַיֵּים לְאַבְהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקב לְמִתַּן לָךְ קִירְוִין רַבְרְבִין וְטָבָן דְּלָא אִשְׁתַּלְהִית לְמִבְנֵי\",0,0],[4,142,6,11,\"וּבָתִּין דְּמַלְיָין כָּל טוּבָא דְּלָא עָסַקְתָּ לְמִימְלֵי וּבֵירִין פְּסִילָן דְּלָא לָעִית לְמִפְסַל כַּרְמִין וְזֵיתִין דְּלָא טָרַחְתְּ לְמִינְצַב וְתֵיכוֹל וְתִיסְבּוֹעַ\",0,0],[4,142,6,12,\"אִסְתַּמָּרוּ לְכוֹן דִּלְמָא תִתְנְשׁוּן דַּחַלְתָּא דַיְיָ אֱלָהָכוֹן דִּפְרַק וְאַפֵּיק יַתְכוֹן פְּרִיקִין מֵאַרְעָא דְמִצְרַיִם מִן בֵּית שִׁעֲבּוּד עַבְדַיָא\",0,0],[4,142,6,13,\"מִן קֳדָם יְיָ אֱלָהָכוֹן תֶּהֱווֹן דַּחֲלִין וּקְדָמוֹי תִּפְלְחוּן וּבְשׁוּם מֵימְרֵי יְיָ בִּקְשׁוֹט תּוּמוּן\",0,0],[4,142,6,14,\"לָא תַהֲכוּן בָּתַר טַעֲוַות עַמְמַיָא מִנַּחֲלַת עַמְמַיָא דִּבְחִזְרָנֵיכוֹן\",0,0],[4,142,6,15,\"אֲרוּם אֱלָהָא קַנְאָן וּפוּרְעָן יְיָ אֱלָהָכוֹן שְׁכִינְתֵּיהּ שַׁרְיָא בֵּינֵיכוֹן דִּלְמָא יִתְקוֹף רוּגְזָא דַיְיָ אֱלָהָכוֹן בְּכוֹן וִישֵׁיצִינוּךְ בְּסַרְהוֹבַיָא מֵעִילַוֵי אַפֵּי אַרְעָא\",0,0],[4,142,6,16,\"עַמִּי בְּנֵי יִשְרָאֵל הֲווֹ זְהִירִין דְּלָא תְנַסּוּן יַת יְיָ אֱלָהָכוֹן הֵיכְמָא דְנַסִּיתוּן בְּעִישַרְתֵּי נִסְיוֹנִין\",0,0],[4,142,6,17,\"מִינְטוֹר תִּנְטְרוּן יַת פִּקּוּדַיָא דַיְיָ אֱלָהָכוֹן וּסְהִידְוָותֵיהּ וּקְיָימוֹי דְפַקֵּיד לְכוֹן\",0,0],[4,142,6,18,\"וְתַעֲבֵיד דְּתַקִּין וּדְכָשַׁר קֳדָם יְיָ מִן בִּגְלַל דְּיוֹטִיב לְכוֹן וְתֵיעֲלוּן וְתֵירְתוּן יַת אַרְעָא טַבְתָּא דְקַיִים יְיָ לַאֲבָהַתְכוֹן\",0,0],[4,142,6,19,\"לְמִדְחֵי יַת כָּל בַּעֲלֵי דְבָבָךְ מִן קֳדָמָךְ הֵיכְמָא דְמַלֵּיל יְיָ\",0,0],[4,142,6,20,\"אֲרוּם יְשַׁיְילִינָךְ בְּרָךְ מְחַר לְמֵימָר מַה סְהִידְוָותָא וּקְיָימַיָא וְדִינַיָא דְפַקֵּיד יְיָ אֱלָהָנָא יַתְכוֹן\",0,0],[4,142,6,21,\"וְתֵימְרוּן לִבְנֵיכוֹן מְשַׁעְבְּדִין הֲוֵינָן לְפַרְעה בְּמִצְרָיִם וְאַפֵּיקָנָא מֵימְרָא דַיְיָ מִמִּצְרַיִם בִּידָא תַּקִיפְתָּא\",0,0],[4,142,6,22,\"וְגָרֵי מֵימְרָא דַיְיָ אָתִין וְתִימְהִין רַבְרְבִין וּמַכְתָּשִׁין בִּישִׁין בְּמִצְרַיִם וּבְפַרְעה וּבְכָל אֵינַשׁ בַּיְיתֵיהּ וַהֲוֵינָא חַמְיָין בְּעֵינָנָא\",0,0],[4,142,6,23,\"וְיָתָנָא אַפֵּיק פְּרִיקִין מִן בִּגְלַל לְאַעֲלָא יָתָנָא לְמִתַּן לָנָא יַת אַרְעָא דְקַיֵּים לְאַבְהָתָן\",0,0],[4,142,6,24,\"וּפַקֵּיד עֲלָנָא יְיָ לְמֶעֱבַד יַת כָּל קְיָמַיָא הָאִילֵין לְמִדְחַל מִן קֳדָם יְיָ אֱלָהָנָא לְטַב לָנָא כָּל יוֹמַיָא לְקַיָּימוּתָנָא כִּזְמַן יוֹמָא הָדֵין\",0,0],[4,142,6,25,\"וּזְכוּ יְהֵא נְטִיר לָנָא לְעַלְמָא דְאָתֵי אֲרוּם נִנְטוֹר לְמֶעֱבַד יַת כָּל תַּפְקֵידְתָּא הָדָא קֳדָם יְיָ אֱלָהָנָא הֵיכְמָא דְפַקֵדְנָא\",0,0],[4,142,7,1,\"אֲרוּם יַעֲלִינָךְ יְיָ אֱלָהָךְ לְאַרְעָא דְאַתְּ עָלֵיל לְתַמָּן לְמֵירְתָהּ וְיִגְלֵי עַמְמִין סַגִּיאִין מִן קֳדָמָךְ חִתָּאֵי וְגִרְגְּשָׁאֵי וְאֵימוֹרָאֵי וּכְנַעֲנָאֵי וּפְרִיזָאֵי וְחִיוָאֵי וִיבוּסָאֵי שִׁבְעָתֵי עַמְמִין סַגִּיאִין וְתַקִּיפִין מִינָךְ\",0,0],[4,142,7,2,\"וְיִמְסְרִינוּן יְיָ אֱלָהָכוֹן קֳדָמֵיכוֹן וְתִמְחִינוּן גַּמָרָא תְּגַמְרוּן יַתְהוֹן בְּשַׁמַתָּא דַיְיָ לָא תִגְזְרוּן לְהוֹן קְיָים וְלָא תְרַחֲמוּן עֲלֵיהוֹן\",0,0],[4,142,7,3,\"לָא תִתְחַתְּנוּן בְּהוֹן בְּנָתֵיכוֹן לָא תִתְּנוּן לִבְנֵיהוֹן וּבְנָתֵיהוֹן לָא תִסְבוּן לִבְנֵיכוֹן דְּכָל מַאן דְּמִתְחַתֵּן בְּהוֹן כְּמִתְחַתֵּן בְּטַעֲוַותְהוֹן\",0,0],[4,142,7,4,\"אֲרוּם יַטְעֲיָין בְּנָתֵיהוֹן יַת בְּנֵיכוֹן מִן בָּתַר פּוּלְחָנִי וְיִפְלְחוּן לְטַעֲוַת עַמְמַיָא וְיִתְקוֹף רוּגְזָא דַיְיָ בְּכוֹן וִישֵׁצִינְכוֹן בְּסַרְהוּבַיָא\",0,0],[4,142,7,5,\"אֲרוּם אִין כְּדֵין תַּעַבְדוּן לְהוֹן אִיגוֹרֵיהוֹן תִּסְתְּרוּן וְקָמַתְהוֹן תְּתַבְּרוּן וְאִילָנֵי סִיגְדֵיהוֹן תְּקַצְצוּן וְצַלְמֵי טַעֲוַותְהוֹן תּוּקְדוּן בְּנוּרָא\",0,0],[4,142,7,6,\"אֲרוּם עַמָּא קַדִּישָׁא אַתּוּן קֳדָם יְיָ אֱלָהָכוֹן וּבְכוֹן אִתְרְעֵי יְיָ אֱלָהָכוֹן מְטוֹל לְמֶהֱוֵי לֵיהּ לְעַם חָבִיב מִן כֻּלְהוֹן עַמְמַיָא דְעַל אַנְפֵּי אַרְעָא\",0,0],[4,142,7,7,\"לָא מִן בִּגְלַל דְּאַתּוּן גֵּיוְתָנִין מִן כֻּלְהוֹן אוּמַיָא צָבֵי יְיָ בְּכוֹן וְאִתְרְעֵי בְּכוֹן אֱלָהֵן דְּאַתּוּן מַכִּיכֵי רוּחָא וְעִנְוְותָנִין מִכָּל עַמְמַיָא\",0,0],[4,142,7,8,\"אֲרוּם מִן בִּגְלַל דְּרָחִים יְיָ יַתְכוֹן וּמִן דְּנָטִיר יַת קְיָימָא דְקַיֵּים לְאַבְהַתְכוֹן אַפֵּיק יַתְכוֹן פְּרִיקִין בִּידָא תַּקִּיפְתָּא וּפְרִקְכוֹן מִבֵּית שִׁעֲבּוּד עַבְדַיָא מִן יְדָא דְפַרְעה מַלְכָּא דְמִצְרָיִם\",0,0],[4,142,7,9,\"וְתִנְדְּעוּן אֲרוּם יְיָ אֱלָהָכוֹן הוּא דַיָינָא תַקִּיפָא וּמְהֵימְנָא נְטִיר קְיָימָא וְטִיבוּ לְרַחֲמוֹי צַדִּיקַיָא וּלְנַטְרֵי פִּיקוּדוֹי לְאַלְפֵי דָרִין\",0,0],[4,142,7,10,\"וּמְשַׁלֵּם לְסַנְאוֹי אֲגַר עוֹבָדֵיהוֹן טַבְיָא בְּעַלְמָא הָדֵין מִן בִּגְלַל דִּמְשֵׁיצְיָא יַתְהוֹן בְּעַלְמָא דְּאָתֵי וְלָא מַשְׁהֵי לְסַנְאוֹי אֶלָא עַד דְּהִינוּן בְּחַיִּין בְּעַלְמָא הָדֵין מְשַׁלֵּם לְהוֹן גּוּמְלֵיהוֹן\",0,0],[4,142,7,11,\"וְתִנְטְרוּן יַת תַּפְקֵידְתָּא וְיַת קְיָמַיָא וְיַת דִּינַיָא דַּאֲנָא מְפַקֵּיד יַתְכוֹן לְמֶעֱבַדְהוֹן\",0,0],[4,142,7,12,\"והיה עקב וִיהֵי חוֹלַף דִּי תְקַבְּלוּן יַת דִּינַיָא הָאִילֵין וְתִנְטְרוּן וְתַעַבְדוּן יַתְהוֹן וְיִנְטַר יְיָ אֱלָהָכוֹן לְכוֹן יַת קְיָימַיָא וְיַת חִסְדָא דִי קַיֵּים לְאַבְהַתְכוֹן\",0,0],[4,142,7,13,\"וִירַחֲמִינְכוֹן וִיבָרְכִינְכוֹן וְיַסְגִינְכוֹן וִיבָרֵךְ וַלְדֵי מְעֵיכוֹן וּפֵירוֹי אַרְעֲכוֹן עִיבּוּרֵיכוֹן חֲמָרֵיכוֹן וּמִשְׁחֵיכוֹן בַּקְרַת תּוֹרֵיכוֹן וְעֶדְרֵי עַנְכוֹן עַל אַרְעָא דְקַיֵּים לְאַבְהָתָךְ לְמִתַּן לָךְ\",0,0],[4,142,7,14,\"בְּרִיכִין תֶּהֱווֹן מִן כּוּלְהוֹן עַמַיָא לָא יֶהֱווֹן בְּכוֹן גּוּבְרִין עַקְרִין וּנְשִׁין עַקְרִין וְלָא בְּעִירָךְ עַקְרִין מֵעֲמָר וַחֲלָב וְטָלוּי\",0,0],[4,142,7,15,\"וְיַעֲדֵי יְיָ מִינָךְ כָּל מַרְעִין וְכָל מַכְתָּשַׁיָא דְגָרֵי יְיָ עַל מִצְרַיִם בִּישַׁיָא דִידַעְתְּ לָא יְשַׁוִּינוּן בְּכוֹן וִיגָרִינוּן בְּכָל סַנְאֵיכוֹן\",0,0],[4,142,7,16,\"וּתְגַמַר יַת כָּל עַמְמַיָא דַיְיָ אֱלָהָךְ יָהִיב לָךְ לָא תֵיחוֹס עֵינָךְ עֲלֵיהוֹן וְלָא תִפְלַח יַת טַעֲוַותְהוֹן אֲרוּם לְתוּקְלָא הִינוּן לָךְ\",0,0],[4,142,7,17,\"דִּלְמָא תֵימַר בְּלִבָּךְ סַגִּיאִין עַמְמַיָא הָאִלֵּין מִנִּי הֵיכְדֵין אִית לִי יוּכְלָא לְתַרְכוּתְהוֹן\",0,0],[4,142,7,18,\"לָא תִידַחֲלוּן מִנְהוֹן הֲווֹן דְּכִירִין יַת גְּבוּרָן דְּעָבַד יְיָ אֱלָהָךְ לְפַרְעה וּלְכָל מִצְרָאֵי\",0,0],[4,142,7,19,\"נִיסִין רַבְרְבִין דַּחֲמֵיתוּן בְּעֵינֵיכוֹן אָתַיָא וְתִמְהַיָא וּגְבוּרַת יְדָא תַקִיפְתָּא וְנִצְחָנוּת אֶדְרַע מְרַמְמָא כַּדְאַפְקְכוֹן יְיָ אֱלָהָכוֹן פְּרִיקִין הֵיכְדֵין יַעֲבֵד יְיָ אֱלָהָכוֹן לְכָל עַמְמַיָא דְאַנְתְּ דָּחִיל מִן קֳדָמֵיהוֹן\",0,0],[4,142,7,20,\"וּלְחוֹד יַת מְחַת אוֹרְעַיִיתָא טְרִיקַיָיא יְגָרֵי יְיָ אֱלָהָכוֹן בְּהוֹן עַד דִּיהוֹבְדוּן מַה דְּמִשְׁתּוֹתְרִין וּמַה דְּמִיטַמְרִין מִן קֳדָמֵיכוֹן\",0,0],[4,142,7,21,\"לָא תִתְבְּרוּן מִן קֳדָמֵיהוֹן אֲרוּם שְׁכִינַת יְיָ אֱלָהָכוֹן בֵּינֵיכוֹן אֱלָהָא רַבָּא וּדְחִילָא\",0,0],[4,142,7,22,\"וְיִגְלֵי יְיָ אֱלָהָכוֹן יַת עַמְמַיָא הָאִלֵּין מִן קֳדָמֵיכוֹן קָלִיל לָא תֵיכוּל לְשֵׁיצֵיוּתְהוֹן בִּפְרִיעַ דִּלְמָא יַסְגֵי עֲלֵיכוֹן חֵיוַת בָּרָא כַּד יֵיתוּן לְמֵיכוֹל גּוּשְׁמֵיהוֹן\",0,0],[4,142,7,23,\"וְיִמְסְרִינוּן יְיָ אֱלָהָכוֹן קֳדָמֵיכוֹן וִיעַרְבִּינוּן עִרְבּוּב רַב עַד דְּיִשְׁתֵּיצוּן\",0,0],[4,142,7,24,\"וְיִמְסוֹר מַלְכֵיהוֹן בְּיֶדְכוֹן וְתוֹבְדוּן יַת שׁוּמְהוֹן מִדּוּכְרָנָא תְּחוֹת כָּל שְׁמַיָא לָא יִתְעַתֵּד אֵינַשׁ קוֹמֵיכוֹן עַד דְּיִתְשֵׁיצֵי יַתְהוֹן\",0,0],[4,142,7,25,\"צַלְמֵי טַעֲוַותְהוֹן תּוֹקְדוּן בְּנוּרָא לָא תְחַמְדוּן כַּסְפָּא וְדַהֲבָא דַּעֲלֵיהוֹן וְתִסְבוּן לְכוֹן דִּלְמָא תִתַּקְלוּן בְּהוֹן אֲרוּם מְרָחֵק קֳדָם יְיָ אֱלָהָכוֹן הוּא\",0,0],[4,142,7,26,\"וְלָא תֵיעֲלוּן רִיחוּקֵי טַעֲוָותָא וְתִשְׁמִישָׁתָא לְבָתֵּיכוֹן דְּלָא תֶהֱווֹן שְׁמִיתִין כְּוַותְהוֹן שִׁיקְצָא תְּשַׁקְצִינוּן הֵיךְ סָאִיב שִׁיקְצָא וְרִיחֲקָא תְּרַחֲקִינוּן מְטוּל דְּשַׁמְתִּין הִינוּן\",0,0],[4,142,8,1,\"כָּל תַּפְקֵידְתָּא דַּאֲנָא מְפַקִּידְכוֹן יוֹמָא דֵין תִּטְרוּן לְמֶעֱבַד מִן בִּגְלַל דְּתֵיחוּן וְתִיסְגוּן וְתֵעֲלוּן וְתֵירְתוּן יַת אַרְעָא דְקַיֵּים יְיָ לְאַבְהַתְכוֹן\",0,0],[4,142,8,2,\"וְתֶהֱווֹן דְּכִירִין יַת כָּל אָרְחָא דְדַבַּרְכוֹן יְיָ אֱלָהָכוֹן דְּנַן אַרְבְּעִין שְׁנִין בְּמַדְבְּרָא מִן בִּגְלַל לְסַגִּיפְכוֹן וּמִן בִּגְלַל לְנַסְיוּכוֹן לְמִנְדוֹעַ הֲנַטְרוּן אַתּוּן פִּקּוּדוֹי אִין לָא\",0,0],[4,142,8,3,\"וְעַנְיָךְ וְאַכְפִינָךְ וְאוֹכְלָךְ יַת מַנָּא דְּלָא יְדַעְתּוּן וְלָא יָדְעוּן אַבְהָתָךְ מִן בִּגְלַל לְהוֹדָעוּתָךְ אֲרוּם לָא עַל לַחֲמָא בִּלְחוֹדוֹי חַיֵּי בַּר נְשָׁא אֲרוּם עַל כָּל מַה דְּאִתְבְּרֵי עַל מֵימְרָא דַיְיָ חַיֵּי בַּר נְשָׁא\",0,0],[4,142,8,4,\"כְּסוּתְכוֹן לָא בְּלַת מֵעִילַוֵי גּוּשְׁמֵיכוֹן וְרִגְלֵיכוֹן לָא הֲלִיכַן מְיַיחְפִּין דְּנָן אַרְבְּעִין שְׁנִין\",0,0],[4,142,8,5,\"וְתִנְדְּעוּן עִם רַעֲיוֹנֵי לִבְכוֹן אֲרוּם הֵיכְמָא דִּמְסַקֵּר גְּבַר יַת בְּרֵיהּ יְיָ אֱלָהָךְ מַסְקֵר יַתְכוֹן\",0,0],[4,142,8,6,\"וְתִנְטְרוּן יַת פִּקּוּדַיָא דַיְיָ אֱלָהָכוֹן לִמְהַךְ בְּאָרְחָן דְּתַקְנָן קֳדָמוֹי וּלְמִדְחַל יָתֵיהּ\",0,0],[4,142,8,7,\"אֲרוּם יְיָ אֱלָהָכוֹן מֵעַל יַתְכוֹן לְאַרְעָא מְשַׁבְּחָא בְּפֵירָהָא אַרְעָא דְנַגְדָא נַחֲלִין דְּמַיָין צְלִילִין מַבּוּעֵי עֵינַוָון חַלְיַין וּתְהוֹמִין דְּלָא מְיַיבְּשִׁין נַפְקִין בְּבִקְעָן וּבְטַוְורִין\",0,0],[4,142,8,8,\"אַרְעָא דְמַרְבַּיָיא חִינְטִין וּשְעוֹרִין וּמְלַבְלְבָא גוּפְנִין דְּמִנְהוֹן נָפִיק חֲמַר חַל וְחָרִיף וּמַרְבַּיָא תֵינִין וְרוּמָנִין אֲרַע דְּמִן זֵיתָהָא עַבְדִין מְשַׁח וּמִן תוּמְרַיָיהָא עַבְדִין דְּבָשׁ\",0,0],[4,142,8,9,\"אַרְעָא דְלָא בְחוּסְרָנָא תֵיכְלוּן בָּהּ לַחֲמָא לָא תֶחְסַר כָּל מִדַּעַם בָּהּ אַרְעָא דִי חַכִּימָהָא גָזְרִין גְּזֵרַן בְּרִירַן הֵי כְּפַרְזְלָא וְתַלְמִידָהָא שַׁאֲלִין שְׁאִילִין מְסִימָן כִּנְחָשָׁא\",0,0],[4,142,8,10,\"וְתֶהֱווֹן זְהִירִין בִּזְמַן דְּאַתּוּן אָכְלִין וּשְבֵעִין הֲווֹן מוֹדִין וּמְבָרְכִין קֳדָם יְיָ אֱלָהָכוֹן עַל כָּל פֵּירֵי אַרְעָא מְשַׁבְּחָא דִיהַב לְכוֹן\",0,0],[4,142,8,11,\"אִסְתַּמְרוּן לְכוֹן דִּילְמָא תִתְנְשׁוּן יַת דַּחַלְתָּא דַיְיָ אֱלָהָכוֹן מִן בִּגְלַל דְּלָא לְמִנְטַר פִּקּוּדוֹי וְדִינוֹי וּקְיָמוֹי דַּאֲנָא מְפַקֵּיד לְכוֹן יוֹמָא דֵין\",0,0],[4,142,8,12,\"דִּלְמָא תֵּיכְלוּן וְתִשְבְּעִין וּבָתִּין שַׁפִּירִין תִּיבְנוּן וְתֵיתְבוּן\",0,0],[4,142,8,13,\"וְתוֹרֵיכוֹן וְעָנֵיכוֹן יִסְגוּן וְכַסְפָּא וְדַהֲבָא יִסְגֵי לְכוֹן וְכָל דִּילְכוֹן יִסְגֵי\",0,0],[4,142,8,14,\"וְיִתְרָם לִבְּכוֹן וְתִתְנְשׁוּן יַת דַּחַלְתָּא דַיְיָ אֱלָהָכוֹן דְּאַפֵּיקְכוֹן פְּרִיקִין מֵאַרְעָא דְמִצְרַיִם מִבֵּית שִׁעֲבּוּד עַבְדַיָא\",0,0],[4,142,8,15,\"דְּדַבְּרָךְ בְּרַחֲמִין בְּמַדְבְּרָא רַבָּא וּדְחֵילָא אֲתַר מָלֵי חֵיוָן קָלִין וְעַקְרַבִּין עַקְצִין וּבֵית צַחְוָונָא אֲתַר דְּלֵית מוֹי דְּאַפֵּיק לָךְ מוֹי מִשָׁמִיר טִנְרָא\",0,0],[4,142,8,16,\"דְּאוֹכְלָךְ מַנָא בְּמַדְבְּרָא דְּלָא יַדְעוּן אַבְהָתָךְ מִן בִּגְלַל לְסַגְפוּתָךְ וּמִן בִּגְלַל לְנַסְיוֹתָךְ לְאוֹטָבָא לָךְ בְּסוֹפָךְ\",0,0],[4,142,8,17,\"הֲווֹ זְהִירִין דְּלָא תֵימְרוּן בְּלִבְּכוֹן חֵילָן וּתְקוֹף יְדָן קָנוּ לָן יַת נִכְסַיָא הָאִילֵין\",0,0],[4,142,8,18,\"וְתֶהֱווֹן דְּכִירִין יַת יְיָ אֱלָהָכוֹן אֲרוּם הוּא דִּיהַב לְכוֹן מִלְכָּא לְמִקְנֵי נִיכְסִין מִן בִּגְלַל לְקַיָימָא יַת קְיָימֵיהּ דְּקַיֵּים לְאַבְהַתְכוֹן כִּזְמַן יוֹמָא הָדֵין\",0,0],[4,142,8,19,\"וִיהֵי אִין מִנְשָׁא תִּינְשָׁא יַת דַּחַלְתָּא דַיְיָ אֱלָהָכוֹן וּתְהָכוּן בָּתַר טַעֲוַות עַמְמַיָא וְתִפְלְחִינוּן וְתִסְגְּדוּן לְהוֹן אַסְהָדִית עֲלֵיכוֹן יוֹמָא דֵין אֲרוּם מֵיבַד תֵּיבְדוּן\",0,0],[4,142,8,20,\"הֵי כְעַמְמַיָא דַיְיָ מַגְלֵי מִן קֳדָמֵיכוֹן הֵיכְדֵין תֵּיבְדוּן חוֹלַף דְּלָא קַבֵּילְתּוּן לְמֵימְרָא דַּיְיָ אֱלָהָכוֹן\",0,0],[4,142,9,1,\"שְׁמָעוּ יִשְרָאֵל אַתּוּן עָבְרִין יוֹמָא דֵין יַת יוֹרְדְּנָא לְמֵיעוּל לְמֵירוּת עַמְמִין רַבְרְבִין וְתַקִּיפִין מִנְכוֹן קִרְוִין רַבְרְבִין וּכְרִיכַן עַד צֵית שְׁמַיָא\",0,0],[4,142,9,2,\"עַם חָסִין וְגֵיוְתָן הֵי כְּגִנְבָּרַיָא דְּאַתּוּן יְדַעְתּוּן וְאַתּוּן שְׁמַעְתּוּן מַן יֵיכוּל לְמֵיקָם קֳדָם בְּנוֹי גִבָּרַיָא\",0,0],[4,142,9,3,\"וְתִנְדְּעוּן יוֹמָא דֵין אֲרוּם יְיָ אֱלָהָכוֹן שְׁכִינַת יְקָרֵיהּ מְטַיְילָא קֳדָמֵיכוֹן מֵימְרֵיהּ אֵישָׁא אָכְלָא הוּא יְשֵׁצִינוּן וְהוּא יְתָרֵיכִינוּן מִן קֳדָמֵיכוֹן וּתְרָכִינוּן וְתוֹבְדִינוּן בְּסַרְהוֹבַיָא הֵיכְמָא דְמַלֵּיל יְיָ אֱלָהָכוֹן לְכוֹן\",0,0],[4,142,9,4,\"לָא תֵימְרוּן בְּלִבְּכוֹן כַּד יַדְחֵי יְיָ אֱלָהָכוֹן יַתְהוֹן מִן קֳדָמֵיכוֹן לְמֵימָר בִּזְכוּתִי אַעֲלַנִי יְיָ לְמֵירַת יַת אַרְעָא הָדָא וּבְחוֹבֵי עַמְמַיָא הָאִלֵין יְיָ מְתַרְכְהוֹן מִן קֳדָמֵיכוֹן\",0,0],[4,142,9,5,\"לָא מְטוּל זַכְוַותְכוֹן וּבַתְרִיצוּת לִבְּכוֹן אַתּוּן עַלְלִין לְמֵירוּת יַת אַרְעֲהוֹן אֲרוּם בְּחוֹבֵי עַמְמַיָא הָאִלֵּין יְיָ אֱלָהָכוֹן מְתָרֵךְ יַתְהוֹן מִן קֳדָמֵיכוֹן וּמִן בִּגְלַל לְקַיְימָא יַת פִּתְגָמָא דְקַיֵּים יְיָ לְאַבְהַתְכוֹן לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקב\",0,0],[4,142,9,6,\"וְתִנְדְּעוּן אֲרוּם לָא בִּזְכוּתְכוֹן יְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן יַת אַרְעָא מְשַׁבְּחָא הֲדָא לְמֵירְתָהּ אֲרוּם עַם קְשֵׁי קְדַל אַתּוּן\",0,0],[4,142,9,7,\"הֲווֹ דְכִירִין לָא תִתְנְשׁוּן יַת דְּאַרְגַּזְתּוּן קֳדָם יְיָ אֱלָהָכוֹן בְּמַדְבְּרָא לְמִן יוֹמָא דִנְפַקְתּוּן מֵאַרְעָא דְמִצְרַיִם עַד מֵיתֵיכוֹן עַד אַתְרָא הָדֵין מְסַרְבִין הֲוֵיתוּן קֳדָם יְיָ\",0,0],[4,142,9,8,\"וּבְחוֹרֵב אַרְגֵזְתּוּן קֳדָם יְיָ וַהֲוָה רוּגְזָא מִן קֳדָם יְיָ בְּכוֹן לְשֵׁיצְיָא יַתְכוֹן\",0,0],[4,142,9,9,\"כַּד סְלֵיקַת לְטַוְורָא לְמִיסַב לוּחֵי מַרְמִירָא לוּחֵי קְיָימָא דְגָזַר יְיָ עִמְכוֹן וּשְׁהִיַּית בְּטַוְורָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילַוָון לַחְמָא לָא אֲכָלִית וּמַיָא לָא אִשְׁתֵּיתִי\",0,0],[4,142,9,10,\"וִיהַב יְיָ לִי תְּרֵין לוּחֵי מַרְמִירָא כְּתִיבִין בְּאִיצְבְּעָא דַיְיָ וְעִילַוֵּיהוֹן כְּתִיב הֵי כְּכָל פִּתְגָמַיָא דְמַלֵּיל יְיָ עִמְכוֹן בְּטַוְורָא מִגּוֹ אֵישָׁתָא בְּיוֹם כְּנִישַׁת קְהָלָא\",0,0],[4,142,9,11,\"וַהֲוָה מִסּוֹף אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילַוָן יְהַב יְיָ לִי יַת תְּרֵין לוּחֵי מַרְמִירָא לוּחֵי קְיָימָא\",0,0],[4,142,9,12,\"וַאֲמַר יְיָ לִי קוּם חוּת בִּפְרִיעַ מִכָּא אֲרוּם חַבִּילוּ אָרְחַתְהוֹן עַמָּא דְאִתְקַרְיָין עַל שְׁמָךְ דְּאַפֵּיקְתָּא מֵאַרַע דְּמִצְרָיִם סָטוּ בִּפְרִיעַ מִן אוֹרְחָא דְפַקֵידְתִּינוּן בְּסִינַי לָא תַעַבְּדוּן לְכוֹן צְלַם וְצוּרָה וַעֲבָדוּ לְהוֹן מַתְּכָא\",0,0],[4,142,9,13,\"וַאֲמַר יְיָ לִי לְמֵימָר גְּלֵי קֳדָמַי סוּרְחָנוּת עַמָא הָדֵין וְהָא עַם קְשֵׁי קְדַל הוּא\",0,0],[4,142,9,14,\"אֲנַח בָּעוּתָךְ מִן קֳדָמַי וְאֵישֵׁיצִינוּן וְאִמְחֵי יַת שׁוּמְהוֹן מִתְּחוֹת שְׁמַיָא וְאַעֲבֵיד יָתָךְ לְעַם תַּקִּיף וְסַגִּי מִנְהוֹן\",0,0],[4,142,9,15,\"וְכַוְנִית וּנְחָתִית מִן טַוְורָא וְטַוְורָא דָלֵיק בְּאֵישָׁתָא וּתְרֵין לוּחֵי קְיָימָא עַל תְּרֵין יְדָי\",0,0],[4,142,9,16,\"וְחָמִית וְהָא סְרַחְתּוּן קֳדָם יְיָ אֱלָהָכוֹן עֲבַדְתּוּן לְכוֹן עֵיגַל מַתְּכָא סְטִיתוּן בִּפְרִיעַ מִן אָרְחָא דְפַקֵּיד יְיָ יַתְכוֹן\",0,0],[4,142,9,17,\"וַאֲחָדַת בִּתְרֵין לוּחַיָא וּטְלַקְתִּינוּן מֵעִלַוֵי תַּרְתֵּין יְדָי וּתְבַרְתִּינוּן וְאַתּוּן חַמְיַין כַּד לוּחַיָא מִיתְבְּרִין וְאַתְוָותָא פָּרְחִין\",0,0],[4,142,9,18,\"וּבָעִית רַחֲמִין מִן קֳדָם יְיָ כַּד בְּקַדְמֵיתָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילַוָן לַחֲמָא לָא אָכְלִית וּמוֹי לָא אִשְׁתְּיַית מְטוּל כָּל חוֹבֵיכוֹן דְּחַבְתּוּן לְמֶעֱבַד דְּבִישׁ קֳדָם יְיָ לְאַרְגְּזָא קֳדָמוֹי\",0,0],[4,142,9,19,\"בֵּי הִיא זִמְנָא אִשְׁתַּלְחוּן מִן קֳדָם יְיָ חֲמֵשְׁתֵּי מַלְאָכַיָא מְחַבְּלַיָא לְחַבָּלָא יַת יִשְרָאֵל אַף וְחֵמָה וְקֶצֶף וּמַשְׁחִית וַחֲרוֹן כֵּיוַן דִּי שְׁמַע משֶׁה רַבְּהוֹן דְּיִשְרָאֵל אָזַל וְאַדְכַּר שְׁמָא רַבָּא וְיַקִּירָא וְאוֹקֵים מִקִּבְרֵהוֹן אַבְרָהָם וְיִצְחָק וְיַעֲקב וְקָמוֹן בִּצְלוֹתָא קֳדָם יְיָ וּמִן יַד אִתְכְּלִיאוּ תְּלַת מִנְהוֹן וְאִשְׁתַּיְירוּן תְּרֵין אַף וְחֵימָא בָּעָא משֶׁה רַחֲמִין וְאִיתְכְּלִיאוּ אוּף תְּרֵיהוֹן וְחָפַר שִיַיח בְּאַרְעָא דְמוֹאָב וּטְמַרְנוּן בִּשְׁבוּעַת שְׁמָא רַבָּא וּדְחֵילָא דְּהָכִין כְּתִיב אֲרוּם דְּחֵילִית מִן קֳדָם רוּגְזָא וְחֵימְתָא דִרְגַז יְיָ עֲלֵיכוֹן לִמְשֵׁצְיָא יַתְכוֹן וְקַבֵּיל יְיָ צְלוֹתִי אוּף בְּזִמְנָא הַהוּא\",0,0],[4,142,9,20,\"וְעַל אַהֲרן הֲוָה רְגַז מִן קֳדָם יְיָ לַחֲדָא לְשֵׁיצָיוּתֵיהּ וְצַלֵּיתִי אוּף עַל אַהֲרן בְּעִידָנָא הַהוּא\",0,0],[4,142,9,21,\"וְיַת סוּרְחַנְתְּכוֹן דַּעֲבַדְתּוּן יַת עֵיגְלָא נְסֵיבִית וְאוֹקֵדִית יָתֵיהּ בְּנוּרָא וְשַׁפְיַית יָתֵיהּ בְּשׁוֹפָנָא טַבְאוּת עַד דַּהֲוָה דָקִיק כְּעַפְרָא וּטְלָקִית יַת עַפְרֵיהּ לְנַחֲלָא דְנָחִית מִן טַוְורָא\",0,0],[4,142,9,22,\"וּבְבֵית יְקִידְתָּא וּבְנִסֵיתָא וּבְקִבְרֵי תַחְמוּדָא מַרְגְּזִין הֲוֵיתוּן קֳדָם יְיָ\",0,0],[4,142,9,23,\"וּבִזְמַן דְּשָׁלַח יְיָ יַתְכוֹן מֵרְקָם גֵּעָא לְמֵימָר סוּקוּ וְאַחֲסִינוּ יַת אַרְעָא דִיהָבִית לְכוֹן וְסָרֵיבְתּוּן עַל מֵימְרָא דַיְיָ אֱלָהָכוֹן וְלָא הֵימַנְתּוּן לֵיהּ וְלָא קַבֵּלְתּוּן לְמֵימְרֵיהּ\",0,0],[4,142,9,24,\"מְסַרְבִין הֲוֵיתוּן קֳדָם יְיָ מִן יוֹמָא דְחַכִּימַת יַתְכוֹן\",0,0],[4,142,9,25,\"וְאִשְׁתַּטָּחִית בִּצְלוֹ קֳדָם יְיָ יַת אַרְבְּעִין יְמָמִין וְיַת אַרְבְּעִין לֵילַוָן דְּאִשְׁתַּטָּחִית בִּצְלוֹ אֲרוּם אֲמַר יְיָ לִמְשֵׁצְיָא יַתְכוֹן\",0,0],[4,142,9,26,\"וּצְלִיַּית קֳדָם יְיָ וַאֲמָרִית בְּבָעוּ בְּרַחֲמִין קֳדָמָךְ יְיָ אֱלהִים לָא תְחַבֵּל עַמָּךְ וְאַחֲסַנְתָּךְ דִּי פְרַקְתָּא בְּתוּקְפָךְ דִּי אַפֵּיקְתָּא מִמִּצְרַיִם בִּגְבוּרַת אִידָא תַקִּיפְתָּא\",0,0],[4,142,9,27,\"הֲוֵי דְכִיר לְעַבְדָּךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקב וְלָא תִסְתַּכֵּל לְקַשְׁיוּת לֵב עַמָּא הָדֵין לְרִישְׁעֵיהוֹן וּלְסוּרְחָנוּתְהוּן\",0,0],[4,142,9,28,\"דִּילְמָא יֵימְרוּן דַּיְירֵי אַרְעָא דְאַפֵּקְתָּנָא מִתַּמָּן מִדְאִיתְתִישׁ חֵילָא מִן קֳדָם יְיָ לְאַעֲלוּתְהוֹן לְאַרְעָא דְמַלֵּיל לְהוֹן וּמִדְסָנֵי יַתְהוֹן אַפֵּיקִינוּן לְקַטְלוּתְהוֹן בְּמַדְבְּרָא\",0,0],[4,142,9,29,\"וְהִינוּן עַמָּךְ וְאַחְסַנְתָּךְ דְּאַפֵּיקְתָּא בְּחֵילָךְ רַבָּא וּבִדְרָעָךְ מְרַמְמָא\",0,0],[4,142,10,1,\"בְּעִידָנָא הַהוּא אָמַר יְיָ לִי פְּסָל לָךְ תְּרֵי לוּחֵי מַרְמִירָא כְּצוּרַתְהוֹן דְּקַמָּאֵי וְסוּק לִקְדָמַי לְטַוְורָא וְעִיבַד לָךְ אֲרוֹנָא דְקֵיסָא\",0,0],[4,142,10,2,\"וְאֶכְתּוֹב עַל לוּחַיָא יַת פִּתְגָמַיָא דַהֲווֹ עַל לוּחַיָא קַמָּאֵי דְיַיתְשַׁר חֵילָךְ דִּתְבַרְתִּינוּן וּתְשַׁוִּינוּן בָּאֲרוֹנָא\",0,0],[4,142,10,3,\"וַעֲבָדִית אֲרוֹנָא דְקֵיסֵי שִׁטַיָא וּפְסָלִית תְּרֵין לוּחֵי מַרְמִירָא כְּצוּרַת קַמָּאֵי וּסְלָקִית לְטַוְורָא וּתְרֵין לוּחֵי בִּידִי\",0,0],[4,142,10,4,\"וּכְתַב עַל לוּחַיָא הֵי כִּכְתָבָא קַמָּא יַת עֲשַרְתֵּי דְבִירַיָא דְמַלֵּיל יְיָ עִמְכוֹן בְּטַוְורָא מִגּוֹ אֵישָׁתָא בְּיוֹמָא דְאִתְכְּנָשׁוּ קְהָלָא וִיהָבִינָן יְיָ לִי\",0,0],[4,142,10,5,\"וְכַוָונִית וּנְחָתִית מִן טַוְורָא וְשַׁוְויַית יַת לוּחַיָא בָּאֲרוֹנָא דְעָבְדִית וַהֲווֹ תַּמָּן צְנִיעִין הֵיכְמָא דְפַקְדַנִי יְיָ\",0,0],[4,142,10,6,\"וּבְנֵי יִשְרָאֵל נְטָלוּ מִן כּוּפְרָנֵי בֵּירֵי בְּנֵי יַעֲקָן לְמוֹסֵרָה תַּמָּן אַגַח עִמְהוֹן עֲמָלֵק כַּד מְלָךְ בַּעֲרָד דִּשְׁמַע דְּמִית אַהֲרן וְאִסְתַּלְקוּ עֲנָנֵי יְקָרָא וּמִדְעָקַת עַל יִשְרָאֵל עַל קְרָבָא הַהוּא בָּעוּ לְמֵיתוּב לְמִצְרַיִם וְהַדְרֵי שִׁית מַטְלִין רְדָפוּ בְּנֵי לֵוִי בַּתְרֵיהוֹן וּקְטָלוּ מִנְהוֹן תַּמְנֵי גְנִיסַן וַהֲדָרוּ לַאֲחוֹרֵיהוֹן אַף מִבְּנֵי לֵוִי אִתְקְטִילוּ אַרְבַּע גְּנִיסַן אָמְרוּ דֵין לְדֵין מַאן גָּרַם לָנָא קָטוֹלָא הָדָא אֶלָא עַל דְּאִתְרְשַׁלְנָא בְּמִסְפְּדָא דְאַהֲרן חֲסִידָא וּקְבָעוּ תַּמָּן מִסְפְּדָא כָּל בְּנֵי יִשְרָאֵל כְּאִלּוּ תַמָּן מִית אַהֲרן וְאִתְקְבַר תַּמָּן וּבְכֵן שַׁמֵּישׁ אֶלְעָזָר בְּרֵיהּ בְּאַתְרוֹי\",0,0],[4,142,10,7,\"מִתַּמָּן נְטָלוּ לְגוּדְגוֹד וּמִן גּוּדְגוֹד לְיָטְבַת אֲרַע נַגְדָא נַחֲלִין דְּמַיָין\",0,0],[4,142,10,8,\"בְּעִידָנָא הַהוּא אַפְרֵישׁ יְיָ יַת שִׁבְטָא דְלֵוִי מְטוּל דְּקַנִּיאוּ לִשְׁמֵיהּ לְאִתְקְטָלָא בְּגִין יְקָרֵיהּ לִמְסוֹבְרָא יַת אֲרוֹן קְיָימָא דַיְיָ לְמֵיקוּם קֳדָם יְיָ לְשַׁמָּשׁוּתֵיהּ וּלְבָרְכָא בִּשְׁמֵיהּ עַד זְמַן יוֹמָא הָדֵין\",0,0],[4,142,10,9,\"בְּגִין כֵּן לָא הֲוָה לְשִׁבְטָא דְלֵוִי חוּלַק וְאַחְסָנָא עִם אֲחוֹהִי מַתְּנָן דִּיהַב לֵיהּ יְיָ הִינוּן אַחֲסַנְתֵּיהּ הֵיכְמָא דְמַלֵּיל יְיָ אֱלָהָכוֹן לֵיהּ\",0,0],[4,142,10,10,\"וַאֲנָא הֲוֵית קָאֵי בְּטַוְורָא בָּעֵי וּמְצַלֵּי הֵי כְּיוֹמַיָא קַמָּאֵי אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילַוָן וְקַבֵּיל יְיָ צְלוֹתִי אוּף בְּזִמְנָא הַהוּא לָא צָבָא יְיָ לְחַבְּלוּתָךְ\",0,0],[4,142,10,11,\"וַאֲמַר יְיָ לִי קוּם אֱזִיל לְתַיֵיר קֳדָם עַמָּא וְיַעֲלוּן וְיֵרְתוּן יַת אַרְעָא דְקַיֵּימִית לְאַבְהַתְהוֹן לְמִתַּן לְהוֹן\",0,0],[4,142,10,12,\"וּכְדוֹן יִשְרָאֵל מָה יְיָ אֱלָהָכוֹן בָּעֵי מִנְכוֹן אֱלָהֵן לְמִדְחַל מִן קֳדָם יְיָ אֱלָהָכוֹן לִמְהַךְ בְּכָל אָרְחָן דְּתַקְנָן קֳדָמוֹי וּלְמִרְחַם יָתֵיהּ וּלְמִפְלַח קֳדָם יְיָ אֱלָהָכוֹן בְּכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן\",0,0],[4,142,10,13,\"לְמִנְטוֹר יַת פִּקּוּדוֹי דַיְיָ וְיַת קְיָימוֹהִי דַאֲנָא מְפַקֵיד יַתְכוֹן יוֹמָא דֵין מְטוּל דְיוֹטֵב לְכוֹן\",0,0],[4,142,10,14,\"הָא דַיְיָ אֱלָהָכוֹן שְׁמַיָא וּשְׁמֵי שְׁמַיָא וְכִתֵּי מַלְאָכַיָא דִבְהוֹן לִמְשַׁמְשִׁין קֳדָמוֹי אַרְעָא וְכָל דְּאִית בָּהּ\",0,0],[4,142,10,15,\"לְחוֹד בְּאַבְהַתְכוֹן צָבָא יְיָ מְטוּל לְמִרְחַם יַתְהוֹן וְאִתְרְעֵי בִּבְנֵיהוֹן בַּתְרֵיהוֹן כְּוַותְכוֹן מִכָּל עַמְמַיָא דְעַל אַנְפֵּי אַרְעָא כִּזְמַן יוֹמָא הָדֵין\",0,0],[4,142,10,16,\"וְתַעֲדוּן יַת טִפְּשׁוּת לִבְּכוֹן וּקְדַלְכוֹן לָא תַקְשׁוּן תּוּב\",0,0],[4,142,10,17,\"אֲרוּם יְיָ אֱלָהָכוֹן הוּא אֱלָהָא דַיָינָא וּמָארֵי מַלְכִין אֱלָהָא רַבָּא גִבָּרָא וּדְחִילָא דְּלֵית קֳדָמוֹי מֵיסַב אַפִּין וְאוּף לָא לְקַבָּלָא שׁוֹחֲדָא\",0,0],[4,142,10,18,\"עִבַּד דִּין יִיתָם וְאַרְמַלְתָּא וּרְחֵים גִּיוֹרָא לְמִתַּן לֵיהּ מָזוֹן וְאִסְטוֹלָא\",0,0],[4,142,10,19,\"וּתְרַחֲמוּן יַת גִּיּוֹרָא אֲרוּם גִּיוֹרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם\",0,0],[4,142,10,20,\"מִן קֳדָם יְיָ אֱלָהָכוֹן תְּדַחֲלוּן וּקְדָמוֹי תִפְלְחוּן וּבְדַחַלְתֵּיהּ תִּתְקַרְבוּן וּבִשְׁמֵיהּ תּוֹמוּן\",0,0],[4,142,10,21,\"הוּא תוּשְׁבַּחְתְּכוֹן וְהוּא אֱלָהָכוֹן דְּעָבַד עִמְכוֹן יַת רַבְרְבָתָא וְיַת חֲסִינָתָא הָאִילֵין דַּחֲמִיתוּן בְּעֵינֵיכוֹן\",0,0],[4,142,10,22,\"בְּשׁוּבְעִין נַפְשָׁתָא נְחָתוּ אַבְהַתְכוֹן לְמִצְרַיִם וּכְדוֹן שַׁוִינְכוֹן יְיָ אֱלָהָכוֹן הֵי כְּכוֹכְבֵי שְׁמַיָא לְמִסְגֵי\",0,0],[4,142,11,1,\"וּתְרַחֲמוּן יַת יְיָ אֱלָהָכוֹן וְתִינְטְרוּן מַטְרַת מֵימְרֵיהּ וּקְיָימוֹי וְדִינוֹי וּפִקּוּדוֹי כָּל יוֹמַיָא\",0,0],[4,142,11,2,\"וְתִנְדְּעוּן יוֹמָא דֵין אֲרוּם לָא עִם בְּנֵיכוֹן דְּלָא יָדְעוּן וְלָא חָמוּן יַת אוּלְפַן אוֹרַיְיתָא דַיְיָ אֱלָהָכוֹן יַת רְבוּתֵיהּ וְיַת יְדֵיהּ תַקִיפְתָּא וּדְרָעֵיהּ מְרַמַם\",0,0],[4,142,11,3,\"וְיַת אַתְוָותֵיהּ וְיַת עוֹבָדוֹי דְעָבַד בְּגוֹ מִצְרַיִם לְפַרְעה מַלְכָּא דְמִצְרַיִם וּלְכָל יַתְבֵי אַרְעֵיהּ\",0,0],[4,142,11,4,\"וּדְעָבַד לְמַשִׁרְיַית מִצְרַיִם לְסוּסְוַותְהוֹן וּלְאַרְתִיכֵיהוֹן דִּי אַטִּיף יַת מוֹי דְיַמָא דְסוּף עַל אַפֵּיהוֹן כַּד רְדָפוּ בַּתְרֵיכוֹן וְאַבֵּידִינוּן יְיָ עַד זְמַן יוֹמָא הָדֵין\",0,0],[4,142,11,5,\"וּדְעָבַד לְכוֹן בְּמַדְבְּרָא עַד זְמַן מֵיתֵיכוֹן עַד אַתְרָא הָדֵין\",0,0],[4,142,11,6,\"וּדְעָבַד לְדָתָן וְלַאֲבִירָם בְּנֵי אֱלִיאָב בַּר רְאוּבֵן דִּפְתָחַת אַרְעָא יַת פּוּמָהּ וּבְלָעַתְנוּן וְיַת אֵינַשׁ בָּתֵּיהוֹן וְיַת כָּל טַרְיָיתָא דַּהֲווֹ עִמְהוֹן בְּגוֹ כָּל יִשְרָאֵל\",0,0],[4,142,11,7,\"אֲרוּם בְּעֵינֵיכוֹן אַתּוּן חַמְיַין יַת כָּל עוֹבָדָא דַיְיָ רַבָּא דִי עֲבָד\",0,0],[4,142,11,8,\"וְתִנְטְרוּן יַת כָּל תַּפְקֵידְתָּא דַּאֲנָא מְפַקֵיד לְכוֹן יוֹמָא דֵין מִן בִּגְלַל דְּתִתְקְפוּן וְתֵיעֲלוּן וְתֵירְתוּן יַת אַרְעָא דְאַתּוּן עָבְרִין לְתַמָּן לְמֵירְתָהּ\",0,0],[4,142,11,9,\"וּמִן בִּגְלַל דְּיִסְגוּן יוֹמֵיכוֹן עַל אַרְעָא דְקַיֵּים יְיָ לְאַבְהַתְכוֹן לְמִתַּן לְהוֹן וְלִבְנֵיהוֹן אַרְעָא דְפֵירָהָא שְׁמֵינִין כַּחֲלָב וְחַלְיַין כִּדְבָשׁ\",0,0],[4,142,11,10,\"אֲרוּם אַרְעָא דְאַנְתְּ עָלֵיל תַּמָּן לְמֵירְתָהּ לָא כְאַרְעָא דְמִצְרַיִם הִיא דִנְפַקְתּוּן מִתַּמָּן דְּתִזְרַע יַת זַרְעָךְ וּמַשְׁקְיַת לֵיהּ בְּגַרְמָךְ הֵי כְגִינַת יַרְקָא\",0,0],[4,142,11,11,\"וְאַרְעָא דְאַתּוּן עָבְרִין לְתַמָּן לְמֵירְתָהּ אֲרַע טַוְורִין וּבִקְעָן מִן מַטְרָא דְנָחִית מִן שְׁמַיָא שַׁתְיָא מוֹי\",0,0],[4,142,11,12,\"אַרְעָא דַיְיָ אֱלָהָךְ תְּבַע יָתֵהּ בְּמֵימְרֵיהּ לְאוֹטָבוּתָא תְּדִירָא עֵינֵי יְיָ אֱלָהָךְ מִסְתַּכְּלִין בָּהּ מִן שִׁירוּיָא דְשַׁתָּא עַד סוֹפָא דְשַׁתָּא\",0,0],[4,142,11,13,\"וִיהֵי אִין קַבָּלָא תְקַבְּלוּן לְפִקוּדַי דַאֲנָא מְפַקֵּיד יַתְכוֹן יוֹמָא הָדֵין לְמִרְחַם יַת יְיָ אֱלָהָכוֹן וּלְמִפְלַח קֳדָמוֹי בְּכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן\",0,0],[4,142,11,14,\"וְאֶתֵּן מִטְרָא דְאַרְעֲכוֹן בְּעִידְנֵיהּ בַּכִּיר בְּמַרְחֶשְׁוָן וְלָקִישׁ בְּנִיסָן וְתִכְנְשׁוּן עִבּוּרֵיכוֹן חַמְרֵיכוֹן וּמִשְׁחֵיכוֹן\",0,0],[4,142,11,15,\"וְאֶתֵּן עִסְבָּא בְּחַקְלָךְ לִבְעִירָךְ וְתֵיכוּל וְתִסְבַּע\",0,0],[4,142,11,16,\"אִסְתַּמָּרוּ לְכוֹן דִּילְמָא יִטְעֵי יִצְרָא דְלִבְּכוֹן וְתִסְטוּן וְתִפְלְחוּן לְטַעֲוַות עַמְמַיָא וְתִסְגְּדוּן לְהוֹן\",0,0],[4,142,11,17,\"וְיִתְקֵף רוּגְזָא דַיְיָ בְּכוֹן וְיֵיחוּד יַת עֲנָנֵי שְׁמַיָא דְלָא יֵחְתוּן מַטְרָא וְאַרְעָא לָא תִתֵּן עֲלַלְתָּהּ וְתֵיבְדוּן בְּסַרְהוֹבַיָא מֵעִלַוֵי אַרְעָא מְשַׁבְּחָא דַיְיָ יָהֵיב לְכוֹן\",0,0],[4,142,11,18,\"וּתְשַׁוּוּן יַת פִּתְגָמַי אִלֵין עַל לִבְּכוֹן וְעַל נַפְשְׁכוֹן וְתִקְטוֹרוּן יַתְהוֹן כַּד הִנּוּן כְּתִיבִין עַל תְּפִילָא לְאָת עַל רוּם יֶדְכוֹן שְמָאלִיתָא וִיהוֹן לִתְפִילִין קֳבֵיל מוֹקְדֵיכוֹן בֵּין עֵינֵיכוֹן\",0,0],[4,142,11,19,\"וְתַלְפוּן יַתְהוֹן יַת בְּנֵיכוֹן לִמְגַרְסָא בְּהוֹן בְּמִתְבֵיכוֹן בְּבָתֵּיכוֹן עִם חִיתּוּנְכוֹן וּבְמִיהֲכֵכוֹן בְּאָרְחָא וּבְפַנְיָא סְמִיךְ לְמִשְׁכַּבְכוֹן וּבְצַפְרָא סְמִיךְ לְמִקְמֵיכוֹן\",0,0],[4,142,11,20,\"וְתִכְתְּבִינוּן בִּמְגִילְתָּא עַל מְזוּזְיַין וְתִקְבְּעִינוּן בְּתוֹלְתָּא קֳבֵל תִּקֵי בְּסִיפֵי בָתֵּיכוֹן וּבְתַרְעֵיכוֹן\",0,0],[4,142,11,21,\"מִן בִּגְלַל דְּיִסְגוּן יוֹמֵיכוֹן וְיוֹמֵי בְּנֵיכוֹן עַל אַרְעָא דְקַיֵּים יְיָ לְאַבְהַתְכוֹן לְמִיתְנָא לְהוֹן כִּסְכוֹם יוֹמִין דְּקַיְימִין שְׁמַיָא עַל אַרְעָא\",0,0],[4,142,11,22,\"אֲרוּם אִין מִנְטוֹר תִּנְטְרוּן יַת כָּל תַּפְקֵידְתָּא הֲדָא דַאֲנָא מְפַקֵּיד יַתְכוֹן לְמַעַבְדָהּ לְמִרְחַם יַת יְיָ אֱלָהָכוֹן לִמְהַךְ בְּכָל אָרְחָן דְּתַקְנָן קֳדָמוֹי וּמְטוּל לְאִתְקְרָבָא לִדְחַלְתֵּיהּ\",0,0],[4,142,11,23,\"וִיתָרִיךְ מֵימְרָא דַיְיָ יַת כָּל עַמְמַיָא הָאִלֵּין מִן קֳדָמֵיכוֹן וְתֵירְתוּן עַמְמִין רַבְרְבִין וְתַקִּיפִין מִנְכוֹן\",0,0],[4,142,11,24,\"כָּל אַתְרָא דִי תִדְרוֹךְ פַּרְסַת רִגְלֵיכוֹן בֵּיהּ דִּילְכוֹן יְהֵי מִן מַדְבְּרָא וְטַוַור לְכוֹן הִינוּן טַוְורֵי בֵּית מַקְדְּשָׁא מִן נַהֲרָא רַבָּא נַהֲרָא פְּרָת עַד יַמָא דְאוֹקְיָנוּס הִינוּן מֵי בְרֵאשִׁית סְטַר מַעַרְבָא יְהֵי תְחוּמֵיכוֹן\",0,0],[4,142,11,25,\"לָא יִתְעַתֵּד בַּר נַשׁ בְּאַפֵּיכוֹן דַּחֲלַתְכוֹן וְאֵימַתְכוֹן יִתֵּן יְיָ אֱלָהָכוֹן עַל אַפֵּי כָּל יַתְבֵי אַרְעָא דְּתִדְרְכוּן בָּהּ הֵיכְמָא דְמַלֵּיל לְכוֹן\",0,0],[4,142,11,26,\"ראה אנכי אָמַר משֶׁה נְבִיָא חֲמוֹן דַּאֲנָא מְסַדֵּר קֳדָמֵיכוֹן יוֹמָא דֵין בִּרְכָתָא וְחִילוּפָהּ\",0,0],[4,142,11,27,\"יַת בִּרְכָתָא אִין תְּקַבְּלוּן לְפִיקוּדַיָא דַיְיָ אֱלָהָכוֹן דַּאֲנָא מְפַקֵּיד לְכוֹן יוֹמָא דֵין\",0,0],[4,142,11,28,\"וְחִילוּפָא אִין לָא תְקַבְּלוּן לְפִיקוּדַיָא דַיְיָ אֱלָהָכוֹן וְתִטְעוּן מִן אָרְחָא דַאֲנָא מְפַקֵיד יַתְכוֹן יוֹמָא דֵין לְמִטְעֵי בָּתַר טַעֲוַות עַמְמַיָא דְלָא יְדַעְתּוּן\",0,0],[4,142,11,29,\"וִיהֵי אֲרוּם יֵיעָל יַתְכוֹן יְיָ אֱלָהָכוֹן לְאַרְעָא דְאַתּוּן עָלְלִין לְתַמָּן לְמֵירְתָהּ וְתִתְּנוּן שִׁית שִׁבְטִין עַל טַוְורָא דִגְרִיזִים וְשִׁית שִׁבְטִין עַל טַוְורָא דְעֵיבָל מְבָרְכַיָא יֶהֱווֹן הָפְכִין אַפֵּיהוֹן לְקָבֵיל טַוְורָא דִגְרִיזִים וּמְלַטְטַיָא יֶהֱווֹן הָפְכִין אַפֵּיהוֹן לְקָבֵל טַוְורָא דְעֵיבָל\",0,0],[4,142,11,30,\"הֲלָא אִינוּן יְהִיבִין מִלְהָלָא לְיוֹרְדְּנָא אֲחוֹרֵי אוֹרַח מַטְמְעָא דְשִׁמְשָׁא בְּאַרַע כְּנַעֲנָאָה דְשָׁרֵי בְּמֵישְׁרָא כֻּלּוֹ קֳבֵיל גֻּלְגְּלָא בְּסִטְרֵי חֶזְוֵי מַמְרֵא\",0,0],[4,142,11,31,\"אֲרוּם אַתּוּן עָבְרִין יַת יוֹרְדְּנָא לְמֵיעַל לְמֵירוֹת יַת אַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן וְתֵירְתוּן יָתָהּ וְתֵיתְבוּן בָּהּ\",0,0],[4,142,11,32,\"וְתִטְרוּן לְמֶעֱבַד יַת כָּל קְיָימַיָא וְיַת דִּינַיָא דִי אֲנָא יָהֵיב קֳדָמֵיכוֹן יוֹמָא דֵין\",0,0],[4,142,12,1,\"אִלֵין קְיָימַיָא וְדִינַיָיא דְתִנְטְרוּן לְמֶעֱבַד בְּאַרְעָא דִיהַב יְיָ אֱלָהָא דְאַבְהַתְכוֹן לְכוֹן לְמֵירְתָהּ כָּל יוֹמַיָא דְאַתּוּן קְיָימִין עַל אַרְעָא\",0,0],[4,142,12,2,\"אַבָּדָא תְאַבְּדוּן יַת כָּל אַתְרַיָא דִי פְלָחוּ תַּמָּן עַמְמַיָא דְאַתּוּן יַרְתוּן יַתְהוֹן וְיַת טַעֲוַותְהוֹן עַל טַוְורַיָא רָמַיָא וְעַל גְּלִימָתָא וּתְחוֹת כָּל אִילַן דְּרִיוְיֵיהּ שַׁפִּיר\",0,0],[4,142,12,3,\"וְתִסְתְּרוּן יַת אֲגוּרֵיהוֹן וְתִתְבְּרוּן יַת קָמַתְהוֹן וּמְרַחֲקַתְהוֹן תּוֹקְדוּן בְּנוּרָא וְצִילְמֵי טַעֲוַותְהוֹן תְּשַׁקְצוּן וּתְשֵׁיצִינוּן יַת שִׁמְהוֹן מִן אַתְרָא הַהוּא\",0,0],[4,142,12,4,\"לֵיתֵיכוֹן רְשָׁאִין לְמַחְקָא כְּתַב שְׁמָא דַיְיָ אֱלָהָכוֹן\",0,0],[4,142,12,5,\"אֱלָהֵן בְּאַרְעָא דְיִתְרְעֵי מֵימְרָא דַיְיָ אֱלָהָכוֹן מִן כָּל שִׁבְטֵיכוֹן לְאַשְׁרָאָה שְׁכִינְתֵּיהּ תַּמָּן לְבֵית שְׁכִינְתֵּיהּ תִּתְבְּעוּן וְתֵיתוּן תַּמָּן\",0,0],[4,142,12,6,\"וְתַיְיתוּן תַּמָּן עַלְוַותְכוֹן וְנִכְסַת קוּדְשֵׁיכוֹן וְיַת מַעֲשַרְתֵּיכוֹן וְיַת אַפְרָשׁוּת יְדֵיכוֹן וְנִדְרֵיכוֹן וְנִיסְבָתֵיכוֹן וּבְכוֹרֵי תוֹרֵיכוֹן וְעָנֵיכוֹן\",0,0],[4,142,12,7,\"וְתֵיכְלוּן תַּמָּן קֳדָם יְיָ אֱלָהָכוֹן וְתֵחְדוּן בְּכָל אוֹשָׁטוּת יֶדְכוֹן אַתּוּן וְאֵינַשׁ בָּתֵּיכוֹן דִּי בְּרַכְכוֹן יְיָ אֱלָהָכוֹן\",0,0],[4,142,12,8,\"לֵיתֵיכוֹן רַשָּׁאִין לְמֶעֱבַד הֵיכְמָא דַאֲנָן עָבְדִין הָכָא יוֹמָא דֵין גְּבַר כָּל דְּכָשַׁר בְּעֵינוֹי\",0,0],[4,142,12,9,\"אֲרוּם לָא אָתֵיתוּן עַד כְּדוֹן לְבֵי מוּקְדְּשָׁא דְהוּא בֵּית נְיָיחָא וּלְאַחְסָנַת אַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן\",0,0],[4,142,12,10,\"וְתַעַבְרוּן יַת יוֹרְדְּנָא וְתֵיתְבוּן בְּאַרְעָא דַיְיָ אֱלָהָכוֹן מַחְסַן יַתְכוֹן וִינִיחַ לְכוֹן מִכָּל בַּעֲלֵי דְבָבֵיכוֹן מִן חֲזוֹר חֲזוֹר וְתִבְנוּן בֵּית מוּקְדְּשָׁא וּמִבָּתַר כְּדֵין תֵּיתְבוּן לְרוֹחֲצָן\",0,0],[4,142,12,11,\"וִיהֵי אַתְרָא דְיִתְרְעֵי בֵּיהּ מֵימְרָא דַיְיָ לְאַשְׁרָאָה שְׁכִינְתֵּיהּ תַּמָּן לְתַמָּן תַּיְיתוּן יַת כָּל קוּרְבָּנַיָא וּבִכּוּרַיָא וּמַעַשְרַיָא דַאֲנָא מְפַקֵּיד יַתְכוֹן תַּמָּן תִּקְרְבוּן עֲלָוַותְכוֹן וְנִכְסַת קוּדְשֵׁיכוֹן וְתַמָּן תֵּיכְלוּן מַעַשְרֵיכוֹן וְאַפְרָשׁוּת יְדֵיכוֹן וְכָל שְׁפַר נִדְרֵיכוֹן דְּתִידְרוּן קֳדָם יְיָ\",0,0],[4,142,12,12,\"וְתֶחְדוּן קֳדָם יְיָ אֱלָהָכוֹן אַתּוּן וּבְנֵיכוֹן וּבְנָתֵיכוֹן וְעַבְדֵיכוֹן וְאַמְהַתְכוֹן וְלֵוָאֵי דִבְקִירְוֵיכוֹן אֲרוּם לֵית לֵיהּ חוּלַק וְאַחֲסָנָא עִמְכוֹן\",0,0],[4,142,12,13,\"אִסְתַּמָּרוּ לְכוֹן דִּילְמָא תַסְקוּן עֲלָוַותְכוֹן בְּכָל אַתְרָא דְאַתּוּן חַמְיָין\",0,0],[4,142,12,14,\"אֱלָהֵן לְאַתְרָא דְיִתְרְעֵי יְיָ בְּאַחֲסָנַת חַד מִן שִׁבְטֵיכוֹן תַּמָּן תִּסְקוּן עֲלָוַותְכוֹן וְתַמָּן תַּעַבְדוּן יַת כָּל מַה דַאֲנָא מְפַקֵּיד לְכוֹן\",0,0],[4,142,12,15,\"לְחוֹד בְּכָל רַעֲוַות נַפְשְׁכוֹן תִּיכְסוּן וְתֵיכְלוּן בִּישְרָא הֵי כְּבִרְכָתָא דַיְיָ אֱלָהָכוֹן דִּיהַב לְכוֹן בְּכָל קִירְוֵיכוֹן דִּמְסָאֲבִין מִן לְמִיקְרַב לְקוּדְשַׁיָא וְדִדְכִין לְמִקְרַב לְקוּדְשַׁיָא כַּחֲדָא יֵיכְלוּן יָתֵיהּ כְּבִישְרֵיהּ דְּטַבְיָא וּכְאַיְלָא\",0,0],[4,142,12,16,\"לְחוֹד בְּאַדְמָא הֲווֹ זְהִירִין עַל אַרְעָא תֵּישְׁדוּנֵיהּ הֵי כְּמוֹי\",0,0],[4,142,12,17,\"לֵיתֵיכוֹן רַשָּׁאִין לְמֵיכוּל בְּקִירְוֵיכוֹן מַעַשְרֵי עִיבּוּרֵיכוֹן חַמְרֵיכוֹן וּמִשְׁחֵיכוֹן וּבִיכּוּרֵי תּוֹרֵיכוֹן וְעַנְכוֹן וְכָל נִדְרֵיכוֹן דְּתִדְרוּן וְנִסְבָתֵיכוֹן וְאַפְרָשׁוּת יְדֵיכוֹן\",0,0],[4,142,12,18,\"אֱלָהֵן קֳדָם יְיָ אֱלָהָכוֹן תֵּיכְלוּנֵיהּ בְּאַתְרָא דְיִתְרְעֵי יְיָ אֱלָהָכוֹן בֵּיהּ אַתּוּן וּבְנֵיכוֹן וּבְנָתֵיכוֹן וְעַבְדֵיכוֹן וְאַמְהוֹתֵיכוֹן וְלֵיוָאֵי דִבְקִירְוֵיכוֹן וְתֶחְדוּן קֳדָם יְיָ אֱלָהָכוֹן בְּכָל אוֹשָׁטוּת יְדֵיכוֹן\",0,0],[4,142,12,19,\"אִסְתַּמָּרוּ לְכוֹן דִּלְמָא תִּימְעָלוּן עַל לֵוָאֵי כָּל יוֹמֵיכוֹן דְּאַתּוּן שָׁרַן עַל אַרְעֲכוֹן\",0,0],[4,142,12,20,\"אֲרוּם יַפְתֵּי יְיָ אֱלָהָכוֹן יַת תְּחוּמְכוֹן הֵיכְמָא דְמַלֵּיל לְכוֹן וְתֵימַר אֵיכוֹל בִּישְרָא אֲרוּם תֵירוּג נַפְשָׁךְ לְמֵיכוֹל בִּישְרָא בְּכָל רְגוּג נַפְשָׁךְ תֵּיכוּל בִּישְרָא\",0,0],[4,142,12,21,\"אֲרוּם יִתְרְחַק מִנְכוֹן אַתְרָא דְיִתְרְעֵי יְיָ אֱלָהָכוֹן לְאַשְׁרָאָה שְׁכִינְתֵּיהּ תַּמָּן וְתִכְסוּן מִן תּוֹרֵיכוֹן וּמִן עָנֵיכוֹן דִּיהַב יְיָ אֱלָהָכוֹן לְכוֹן הֵיכְמָא דְפַקֵּדִית יַתְכוֹן וְתֵיכְלוּן בְּקִירְוֵיכוֹן בְּכָל רִיגוֹג נַפְשֵׁיכוֹן\",0,0],[4,142,12,22,\"בְּרַם הֵיכְמָא דְמִתְאָכֵל בִּישְרָא דְטַבְיָא וְאַיְלָא הֵיכְדֵין תֵּיכְלוּנֵיהּ דִּמְסָאַב לְמִקְרַב לְקוּדְשַׁיָא וְדִדְכֵי לְמִקְרַב לְקוּדְשָׁא כַּחֲדָא תֵּיכְלוּן\",0,0],[4,142,12,23,\"לְחוֹד אִיתוֹקְפוּן בְּיִצְרֵיכוֹן מְטוּל דְּלָא לְמֵיכוּל אִידְמָא אֲרוּם אִידְמָא הוּא קִיּוּם נַפְשָׁא וְלָא תֵיכְלוּן אִידְמָא דְבֵיהּ קִיּוּם נַפְשָׁא עִם בִּישְרָא\",0,0],[4,142,12,24,\"לָא תֵיכְלוּנֵיהּ עַל אַרְעָא תִשְׁדוּנֵיהּ הֵי כְמַיָּא\",0,0],[4,142,12,25,\"לָא תֵיכְלוּנֵיהּ מִן בִּגְלַל דְּיֵיטִיב לְכוֹן וְלִבְנֵיכוֹן בַּתְרֵיכוֹן אֲרוּם תַּעַבְדוּן דְּכָשַׁר קֳדָם יְיָ\",0,0],[4,142,12,26,\"לְחוֹד בְּעִירֵי מַעֲשַר קוּדְשֵׁיכוֹן דִּיהֲווֹן לְכוֹן וְנִדְרֵיכוֹן תֵּיעָלוּן וְתֵיתוּן לְאַתְרָא דְיִתְרְעֵי יְיָ\",0,0],[4,142,12,27,\"וְתַעֲבֵיד כְּהִלְכָתָא עֲלָוָותָךְ בִּסְרָא וְאַדְמָא עַל מַדְבְּחָא דַיְיָ אֱלָהָךְ וַאֲדַם שְׁאַר נִכְסַת קוּדְשָׁךְ יִשְׁתְּפֵךְ עַל מַדְבְּחָא דַיְיָ אֱלָהָךְ וּבִשְרָא אִתְכְּשָׁר לְמֵיכוֹל\",0,0],[4,142,12,28,\"טוּרוּ וְקַבִּילוּ יַת פִּתְגָמַיָא דַאֲנָא מְפַקֵּיד לְכוֹן מִן בִּגְלַל דְּיֵיטִיב לְכוֹן וְלִבְנֵיכוֹן בַּתְרֵיכוֹן עַד עַלְמָא אֲרוּם תַּעַבְדוּן דְּתַקִּין וּדְכָשַׁר קֳדָם יְיָ אֱלָהָכוֹן\",0,0],[4,142,12,29,\"אֲרוּם יְשֵׁיצֵי יְיָ אֱלָהָכוֹן יַת עַמְמַיָא דְאַתּוּן עַלְלִין לְתַמָּן לְתַרְכוּתְהוֹן מִן קֳדָמֵיכוֹן וְתֵירַת יַתְהוֹן וְתֵיתַב בְּאַרְעֲהוֹן\",0,0],[4,142,12,30,\"אִסְתַּמָּרוּ לְכוֹן דִּלְמָא תִיתּוֹקְלוּן בָּתַר טַעֲוַותְהוֹן מִן בָּתַר דְּיִשְׁתֵּיצוּן מִן קֳדָמֵיכוֹן אוֹ דִלְמָא תִּתְבְּעוּן לְטַעֲוַותְהוֹן לְמֵימָר הֵיכְדֵין פַּלְחִין עַמְמַיָא הָאִלֵּין לְטַעֲוַותְהוֹן וְנַעֲבֵיד כְּדֵין אוּף אֲנָן\",0,0],[4,142,12,31,\"לָא תַעַבְדוּן פּוּלְחָנָא כְּדֵין לַייָ אֱלָהָכוֹן אֲרוּם כָּל דִּמְרַחֵק יְיָ דְסָנֵי עָבְדִין לְטַעֲוַותְהוֹן אֲרוּם אוּף יַת בְּנֵיהוֹן וְיַת בְּנָתֵיהוֹן כַּפְתִין וּמוֹקְדִין בְּנוּרָא לְטַעֲוַותְהוֹן\",0,0],[4,142,13,1,\"יַת כָּל פִּתְגָמַיָא דַאֲנָא מְפַקֵּיד יַתְכוֹן יָתֵיהּ תִּטְרוּן לְמֶעֱבַד לָא תוֹסְפוּן עֲלוֹי וְלָא תִבְצְרוּן מִנֵּיהּ\",0,0],[4,142,13,2,\"אֲרֵי יְקוּם בֵּינֵיכוֹן נְבִי שִׁקְרָא אוֹ מָרֵי חֲלִים חֶלְמָא דְזֵדָנוּתָא וְיִתֵּן לְכוֹן אָת אוֹ תִמְהָא\",0,0],[4,142,13,3,\"וְיֵיתִי אָתָא אוֹ תִמְהָא דְמַלֵּיל עִמְכוֹן לְמֵימָר נְהַךְ בָּתַר טַעֲוַות עַמְמַיָא דְלָא חַכִּימְתְּנוּן וְנִפְלוֹחַ קֳדָמֵיכוֹן\",0,0],[4,142,13,4,\"לָא תְקַבְּלוּן לְפִתְגָמֵי נְבִי שִׁקְרָא הַהוּא אוֹ מִן חֲלִים חֵילְמָא הַהוּא אֲרוּם מְנַסֵּי יְיָ אֱלָהָכוֹן יַתְכוֹן לְמִנְדוֹעַ הַאִיתֵיכוֹן רַחֲמִין יַת יְיָ אֱלָהָכוֹן בְּכָל לְבַבְכוֹן וּבְכָל נַפְשֵׁכוֹן\",0,0],[4,142,13,5,\"בָּתַר פּוּלְחָנָא דַיְיָ אֱלָהָכוֹן תְּהָכוּן וְיָתֵיהּ תְּדַחֲלוּן וְיַת פִּקּוּדוֹי תִּנְטְרוּן וּלְמֵימְרֵיהּ תְּקַבְּלוּן וּקְדָמוֹי תִּצְלוּן וּבְדַחַלְתֵּיהּ תִּתְקַרְבוּן\",0,0],[4,142,13,6,\"וּנְבִי שִׁקְרָא הַהוּא אוֹ חֲלִים חֵילְמָא זְדָנָא הַהוּא יִתְקְטֵל בְּסַיְיפָא אֲרוּם מַלֵּיל סַטְיָא עַל יְיָ אֱלָהָכוֹן דְּאַפֵּיק יַתְכוֹן מֵאַרְעָא דְמִצְרָאֵי וְדִי פְרַקְכוֹן מִבֵּית שִׁעְבּוּד עַבְדַיָא לְאַטְעֲיוּתְכוֹן מִן אָרְחָא דְפַקֵּידְכוֹן יְיָ אֱלָהָכוֹן לִמְהַלְכָא בָּהּ וּתְפַלּוּן עַבְדֵי בִישְׁתָּא מִבֵּינֵיכוֹן\",0,0],[4,142,13,7,\"אֲרוּם יַטְעִינָךְ מִילְכָא בִּישָׁא אָחוּךְ בַּר אִימָךְ כָּל דְּכֵן בַּר אִיבָךְ אוֹ בְרָךְ אוֹ בְרַתָּךְ אוֹ אִתְּתָךְ דְּדַמְכָא בְּעוֹדָךְ אוֹ חַבְרָךְ דְּחָבִיב עֲלָךְ כְּנַפְשָׁךְ כָּרַז לְמֵימָר נְהַךְ וְנִפְלַךְ לְטַעֲוַות עַמְמַיָא דְלָא חַכִּימְתָּא אַנְתְּ וְאַבְהָתָךְ\",0,0],[4,142,13,8,\"מִטַּעֲוַות שִׁבְעָתֵי עַמְמַיָא דִּבְחוֹזְרָנוּתְכוֹן דְּקָרִיבִין לְכוֹן אוֹ מִן שְׁאַר עַמְמַיָא דִרְחִיקִין לְכוֹן מִן סְיָיפֵי אַרְעָא וְעַד סְיָיפֵי אַרְעָא\",0,0],[4,142,13,9,\"לָא תִיצְבוּן לְהוֹן וְלָא תְקַבְּלוּן מִנֵּיהּ וְלָא תֵיחוֹס עֵינֵיכוֹן עֲלוֹי וְלָא תְרַחֲמוּן וְלָא תְכַסּוּן בְּטוּמְרָא עֲלוֹי\",0,0],[4,142,13,10,\"אֲרוּם מִקְטַל תִּקְטְלִינֵיהּ יְדֵיכוֹן יְתוּשְׁטַן בֵּיהּ בְּשֵׁירוּיָא לְמִקְטְלֵיהּ וִידֵיהוֹן דְּכָל עַמָּא בְּסוֹפָא\",0,0],[4,142,13,11,\"וּתְאַטְלוּן יָתֵיהּ בְּאַבְנָא וִימוּת אֲרוּם בְּעָא לְאַטְעֲיוּתְכוֹן מִדְּחַלְתָּא דַיְיָ אֱלָהָךְ דְּאַפֵּיק יַתְכוֹן פְּרִיקִין מֵאַרְעָא דְמִצְרַיִם מִבֵּית שִׁעֲבּוּד עַבְדַיָא\",0,0],[4,142,13,12,\"וְכָל יִשְרָאֵל יִשְׁמְעוּן וִידַחֲלוּן וְלָא יוֹסְפוּן לְמֶעֱבַד כְּפִתְגָמָא בִּישָׁא הָדֵין בֵּינֵיכוֹן\",0,0],[4,142,13,13,\"אֲרוּם תִּשְׁמְעוּן בַּחֲדָא מִן קִרְוֵיכוֹן דַּיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן לְמֵיתַב תַּמָּן לְמֵימָר\",0,0],[4,142,13,14,\"נְפָקוּ גּוּבְרִין זְדָנִין מֵאוּלְפָנָא דַיְיָ אֱלָהָכוֹן דְּחַכִּימַיָא דְּבֵינֵיכוֹן וְאַטְעִין יַת יַתְבֵי קַרְתֵּיהוֹן לְמֵימָר נְהַךְ וְנִפְלַח לְטַעֲוַות עַמְמַיָא דְלָא חַכִּימְתּוּן\",0,0],[4,142,13,15,\"וְתִתְבְּעוּן וְתִבְדְּקוּן יַת סַהֲדַיָיא וּתְשַׁיְילוּן טַבָּאוּת וְהָא קוּשְׁטָא כֵּיוַון פִּתְגָמָא אִתְעֲבִידַת תּוֹעֵבְתָּא הָדָא בֵּינֵיכוֹן\",0,0],[4,142,13,16,\"מִמְחָא תִּמְחוּן יַת יַתְבֵי קַרְתָּא הַהוּא לְפִתְגַם דְּחָרֶב גַּמְרָא יָתָהּ וְיַת כָּל דְּבָהּ וְיַת בְּעִירָהּ לְפִתְגַּם דְּחָרֶב\",0,0],[4,142,13,17,\"וְיַת כָּל עֲדָאָה תִּכְנְשׁוּן בִּמְצַע פַּלְטִיתָא וְתוּקְדוּן בְּנוּרָא יַת קַרְתָּא וְיַת כָּל עֲדָאָה גְמִיר קֳדָם יְיָ אֱלָהָכוֹן וּתְהֵי תֵּל חָרוֹב לְעַלָם לָא תִתְבְּנֵי תוּב\",0,0],[4,142,13,18,\"וְלָא אִידְבֵּיק בְּיֶדְכוֹן מִדַּעַם מִן שַׁמְתָּא מִן בִּגְלַל דְּיֵיתוּב יְיָ מִתְקֵיף רוּגְזֵיהּ וְיִכְמוֹר עֲלֵיכוֹן רַחֲמִין וִירַחֵם עֲלֵיכוֹן וְיַסְגִינְכוֹן הֵיכְמָא דְקַיֵּים לְאַבְהַתְכוֹן\",0,0],[4,142,13,19,\"אֲרוּם תְּקַבְּלוּן לְמֵימְרָא דַיְיָ אֱלָהָכוֹן לְמִנְטוֹר יַת כָּל פִּיקוּדוֹי דַאֲנָא מְפַקֵּיד לְכוֹן יוֹמָא דֵין לְמֶעֱבַד דְּכָשַׁר קֳדָם יְיָ אֱלָהָכוֹן\",0,0],[4,142,14,1,\"הֵי כִבְנִין חֲבִיבִין אַתּוּן קֳדָם יְיָ אֱלָהָכוֹן לָא תְגוּדוּן בִּישְרֵיכוֹן וְלָא תְשׁוּרַן כְּלִיל דִּיסְעַר עַל בֵּית אַפֵּיכוֹן עַל נְפַשׁ דְּמִית\",0,0],[4,142,14,2,\"אֲרוּם עַם קַדִּישׁ אַתּוּן קֳדָם יְיָ אֱלָהָכוֹן וּבְכוֹן אִיתְרְעֵי יְיָ אֱלָהָכוֹן לְמֶהֱוֵי לֵיהּ לְעָם חָבִיב מִכָּל עַמְמַיָא דְּעַל אַפֵּי אַרְעָא\",0,0],[4,142,14,3,\"לָא תֵיכְלוּן כָּל מִדַּעַם דִּרְחֵיקִית מִנְכוֹן\",0,0],[4,142,14,4,\"דָּא הִיא בְּעִירָא דְתֵיכְלוּן תּוֹרִין וְאִימְרֵי בְּנֵי רְחֵילִין וְלָא בְּנֵי מְסָאֲבִין וְגַדְיֵי בְּנֵי עִיזִין וְלָא עֵירוּבֵי טַמְיָין\",0,0],[4,142,14,5,\"אַיְלִין וְטַבְיַן וְיַחֲמוּרִין יַעֲלִין וְרִימְנִין וְתוֹרֵי בַּר וְדִיצִין\",0,0],[4,142,14,6,\"וְכָל בְּעִירָא דִסְדִיקָא טַלְפַיָיא וְלָהּ קַרְנִין וּסְדִיק סִדְקָא מַסְקָא פִּישְׁרָא בִּבְעִירָא יָתָהּ תֵּיכְלוּן\",0,0],[4,142,14,7,\"בְּרַם יַת דֵּין לָא תֵיכְלוּן מִמַּסְקֵי פִּישְׁרָא וּמִסְדִיקֵי פַּרְסָתָא שְׁלִילָא דְּלֵיהּ תְּרֵין רֵישִׁין וְתַרְתֵּין שַׁדְרָאִין הוֹאִיל וְלֵית בְּזַיְנֵיהּ חָזֵי לְמִתְקַיְימָא יַת גְּמָלָא וְיַת אַרְנְבָא וְיַת טַפְּזָא אֲרוּם מַסְקֵי פִּישְׁרָא הִינוּן וּפַרְסַתְהוֹן לָא סְדִיקָן מְסָאֲבִין הִינוּן לְכוֹן\",0,0],[4,142,14,8,\"וְיַת חֲזִירָא אֲרוּם סְדִיק פַּרְסָתָא הוּא וְלֵית כַּנְפֵיק בֵּיהּ דְּסָדִיק וְלָא פָּשַׁר מְסָאַב הוּא לְכוֹן מִבִּסְרֵיהוֹן לָא תֵיכְלוּן וּבִנְבֵילְתְּהוֹן לָא תְקַרְבוּן\",0,0],[4,142,14,9,\"לְחוֹד יַת דֵּין תֵּיכְלוּן מִן כָּל דִּבְמַיָא כָּל דִּילֵיהּ צִיצִין לְמִפְרַח וְחַרְסְפִיתִין עַל מוּשְׁכֵיהּ וְאִין נַתְרוֹן וְאִשְׁתְּיֵיר חַד תְּחוֹת לִיסָתֵיהּ וְחַד תְּחוֹת צִיצִיתֵיהּ וְחַד תְּחוֹת גּוֹנְבֵיהּ יָתֵיהּ תֵּיכְלוּן\",0,0],[4,142,14,10,\"וְכָל דְּלֵית לֵיהּ צִיצִין וְחַרְסְפִיתִין לָא תֵיכְלוּן מְסָאָב הוּא לְכוֹן\",0,0],[4,142,14,11,\"כָּל צִפַּר דְּכֵי דְאִית בֵּיהּ זְפַק וְקוּרְקְבָנֵיהּ קָלִיף וְאִית לֵיהּ צִבְעָא יְתֵירָא וְלָא דָרִיס תֵּיכְלוּן\",0,0],[4,142,14,12,\"וְדֵין דְּלָא תֵיכְלוּן מִנְהוֹן נִישְׁרָא וְעוּזָא וּבַר גּוֹזָא\",0,0],[4,142,14,13,\"וְדַיְיתָא חִיוָורָא וְאוּכְמָתָא דְהִיא אִיבוּ וְדַיְיתָא לִזְנָהּ\",0,0],[4,142,14,14,\"וְיַת כָּל בְּנֵי עוּרְבָא לִזְנֵיהוֹן\",0,0],[4,142,14,15,\"וְיַת בְּרַת נַעֲמֵיתָא וְיַת חֲטִיפִיתָא וְיַת צִפַּר שַׁחֲפָא וְיַת בַּר נָצְצָא לִזְנוֹי\",0,0],[4,142,14,16,\"וְיַת קְפוּפָא וְיַת שַׁלִי נוּנָא מִן יַמָּא וְיַת צַדְיָא\",0,0],[4,142,14,17,\"וְקָקָא חִיוַרְתָּא וְאוּכְמְתָא וּשְׁרַקְרְקָא\",0,0],[4,142,14,18,\"וְדַיְיתָא חִוַורְתָּא וְאוּכְמְתָא לִזְנָהּ וְנַגַר טוּרָא וְעַרְפְּרָא\",0,0],[4,142,14,19,\"וְכָל דִּיבְבֵי וְזִיבוֹרֵי וְזִיזֵי דִטְלוֹפְחֵי וּפוּלֵי דְפַרְשֵׁיהּ מִן אוֹכְלָא וּפַרְחִין הֵי כְעוֹפָא מְסָאֲבִין אִינוּן לְכוֹן לָא יִתְאַכְלוּן\",0,0],[4,142,14,20,\"כָּל גּוּבָא דַכְיָא תֵּיכְלוּן\",0,0],[4,142,14,21,\"לָא תֵיכְלוּן כָּל דְּמִיקַלְקְלָא בְּנִכְסָא לְגִיוּר עָרֵל דִּבְקִירְוֵיכוֹן תִּיתְּנוּנָהּ וְיֵכְלוּנָהּ אוֹ תַּזְבִּין לְבַר עַמְמִין אֲרוּם עַם קַדִּישׁ אַתּוּן קֳדָם יְיָ אֱלָהָכוֹן לֵית אַתּוּן רַשָּׁאִין לְמִיבַשְׁלָא כָּל דְּכֵן לְמֵיכוֹל בְּשַר בַּחֲלָב תַּרְוֵיהוֹן מְעַרְבִין בְּחָדָא\",0,0],[4,142,14,22,\"הֲווֹ זְהִירִין לְעַשְרָא פֵּירֵיכוֹן מִן דְּאַתּוּן מַפְקִין וּכְנָשׁוּן מִן חַקְלָא כָּל שַׁתָּא וְשַׁתָּא וְלָא פֵּירֵי שַׁתָּא עַל פֵּירֵי שַׁתָּא אוֹחֲרֵי\",0,0],[4,142,14,23,\"וְתֵיכְלוּן מַעַשְרָא תִנְיָינָא קֳדָם יְיָ אֱלָהָכוֹן בְּאַתְרָא דְיִתְרְעֵי לְאַשְׁרָאָה שְׁכִינְתֵּיהּ תַּמָּן מַעֲשַר עִיבּוּרֵיכוֹן חַמְרֵיכוֹן וּמִשְׁחֲכוֹן וְכֵן בִּכּוּרֵי תוֹרֵיכוֹן וְעָנֵיכוֹן מִן בִּגְלַל דְּתֵילְפוּן לְמִדְחַל מִן קֳדָם יְיָ אֱלָהָכוֹן כָּל יוֹמַיָא\",0,0],[4,142,14,24,\"וַאֲרוּם יִסְגֵי מִנְכוֹן אוֹרְחָא אֲרוּם לָא תֵיכוּל לְמִיסוֹבְרָא יַת מַעַשְרָא אֲרוּם יִתְרְחַק מִנְכוֹן אַתְרָא דְיִתְרְעֵי יְיָ אֱלָהָכוֹן לְאַשְׁרָאָה שְׁכִינְתֵּיהּ תַּמָּן אֲרוּם יְבָרְכִינָךְ יְיָ אֱלָהָךְ\",0,0],[4,142,14,25,\"וּתְחַלֵּל בְּכַסְפָּא וִיהוֹן פְּרִיטֵי צְרִירִין בִּידָךְ וּתְהַךְ לְאַתְרָא דְיִתְרְעֵי יְיָ אֱלָהֲכוֹן בֵּיהּ\",0,0],[4,142,14,26,\"וְתִתֵּן כַּסְפָּא בְּכָל דְּיִתְרְעֵי נַפְשָׁךְ בְּתוֹרֵי וּבְעָנָא וּבַחֲמַר חֲדַת וְעַתִּיק וּבְכָל דִּתְשַׁיְילִינָךְ נַפְשָׁךְ וְתֵיכְלוּן תַּמָּן קֳדָם יְיָ אֱלָהָכוֹן וְתֶחְדוּן אַתּוּן וֶאֱנַשׁ בָּתֵּיכוֹן\",0,0],[4,142,14,27,\"וְלֵיוָאָה דִבְקִרְוֵיכוֹן לָא תִשְׁבְּקוּנֵיהּ אֲרוּם לֵית לֵיהּ חוֹלַק וְאַחְסָנָא עִמְכוֹן\",0,0],[4,142,14,28,\"מִסּוֹף תְּלַת שְׁנִין תַּפְקוּן יַת כָּל מַעֲשַר עֲלַלְתְּכוֹן בְּשַׁתָּא הַהוּא וְתַצְנִיעוּן בְּקִרְוֵיכוֹן\",0,0],[4,142,14,29,\"וְיֵיתֵי לֵיוָאָה אֲרוּם לֵית לֵיהּ חוּלַק וְאַחֲסָנָא עִמְכוֹן וְגִיּוֹרָא וְיַתְמָא וְאַרְמַלְתָּא דִבְקִירְוֵיכוֹן וְיֵיכְלוּן וְיִסְבְּעוּן מִן בִּגְלַל דִּיבָרְכֵיכוֹן יְיָ אֱלָהָכוֹן בְּכָל עוֹבָדֵי יְדֵיכוֹן דְּתַעַבְדוּן\",0,0],[4,142,15,1,\"מִסּוֹף שִׁבְעָתֵי שְׁנִין תַּעַבְדוּן שְׁמִיטָתָא\",0,0],[4,142,15,2,\"וְדֵין אַהֲוָויַת הִלְכַת שְׁמִיטָתָא אַשְׁמִיטוּ כָּל בַּר נַשׁ מָרֵי מְזוֹפְתָּא דְיִזוֹף בְּחַבְרֵיהּ לֵית לֵיהּ רְשׁוּ לִמְדַחֲקָא בְּחַבְרֵיהּ לְמִתְבּוֹעַ אוֹזְפוּתֵיהּ וְלָא מִן אָחוֹי בַּר יִשְרָאֵל אֲרוּם קָרָא בֵית דִּינָא שְׁמִיטָתָא קֳדָם יְיָ\",0,0],[4,142,15,3,\"יַת בַּר עַמְמִין תִּדְחוֹק וְדִינָא דִי יֶהֱוֵי לָךְ עִם אָחוּךְ תַּשְׁמֵיט יְדָךְ\",0,0],[4,142,15,4,\"לְחוֹד אִין אַתּוּן עֲסִיקִין בְּמִצְוָתָא דְאוֹרַיְיתָא לָא יֶהֱוֵי בְכוֹן מַסְכְּנָא אֲרוּם בְּרָכָא יְבָרְכֵכוּן יְיָ בְּאַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן אַחְסָנָא לְמֵירְתָהּ\",0,0],[4,142,15,5,\"לְחוֹד אִין קַבָּלָא תְקַבְּלוּן לְמֵימְרָא דַיְיָ אֱלָהָכוֹן לְמִנְטוֹר וּלְמֶעֱבַד יַת כָּל תַּפְקֵידְתָּא הָדָא דַאֲנָא מְפַקֵּיד לְכוֹן יוֹמָא דֵין\",0,0],[4,142,15,6,\"אֲרוּם יְיָ אֱלָהָכוֹן בֵּירַכְכוֹן הֵיכְמָא דְמַלֵּיל לְכוֹן וּתְמַשְׁכְּנוּן עַמְמִין סַגִּיאִין וְאַתּוּן לָא תִתְמַשְׁכְּנוּן וְתִשְׁלְטוּן בְּעַמְמִין סַגִּיאִין וּבְכוֹן לָא יִשְׁלְטוּן\",0,0],[4,142,15,7,\"וְאִין לֵיתֵיכוֹן עֲסִיקִין בְּמִצְוָותָא דְאוֹרַיְיתָא וְיֶהֱוֵי בְּכוֹן מַסְכְּנָא מֵחַד אָחוּךְ בַּחֲדָא מִן קִרְוָוךְ בְּאַרְעָךְ דַיְיָ אֱלָהָךְ יָהֵיב לָךְ לָא תִתְקַף יַת לְבָבָךְ וְלָא תִמְנַע יַת אִידָךְ מֵאָחוּךְ מַסְכְּנָא\",0,0],[4,142,15,8,\"אֶלָא מִפְתַּח תִּפְתַּח יַת אִידָךְ לֵיהּ וּמוּזְפָא תוּזְפִינֵיהּ הֵי כְּמֵיסַת חוּסְרָנֵיהּ דְּיֶיחְסַר לֵיהּ\",0,0],[4,142,15,9,\"אִסְתַּמָּרוּ לְכוֹן דִּלְמָא יְהֵי פִּתְגָם עִם לִבְּכוֹן דְּזָדָנוּתָא לְמֵימָר קְרֵיבַת שַׁתָּא שְׁבִיעֲתָא שַׁתָּא דִשְׁמִיטְתָא וְתִבְאַשׁ עֵינֵיכוֹן בְּאָחוּכוֹן מִסְכֵּנָא וְלָא תִתְּנוּן לֵיהּ וְיִקְבּוֹל עֲלֵיכוֹן קֳדָם יְיָ וִיהֵי בְּכוֹן חוֹבָא\",0,0],[4,142,15,10,\"מִתַּן תִּתְּנוּן לֵיהּ וְלָא יִבְאַשׁ לִבְּכוֹן בְּתִתְּנְכוֹן לֵיהּ אֲרוּם מְטוּל פִּתְגָמָא הָדֵין יְבָרְכֵיכוֹן יְיָ אֱלָהָכוֹן בְּכָל עוֹבָדֵיכוֹן וּבְכָל אוֹשָׁטוּת יְדֵיכוֹן\",0,0],[4,142,15,11,\"אֲרוּם מְטוּל דְּלָא צַיְיתִין בֵּית יִשְרָאֵל בְּמִצְוָותָא דְאוֹרַיְיתָא לָא פַסְקִין מַסְכְּנִין מִגּוֹ אַרְעָא בְּגִין כֵּן אֲנָא מְפַקִידְכוֹן לְמֵימָר מִפְתַּח תִּפְתְּחוּן יַת יְדֵיכוֹן לְקָרִיבֵיכוֹן וּלְעַנְיֵי שִׁיבְבוּתְכוֹן וּלְמִסְכְּנֵי אַרְעֲכוֹן\",0,0],[4,142,15,12,\"אֲרוּם יִזְדַּבֵּן לְכוֹן אֲחוּכוֹן בַּר יִשְרָאֵל אוֹ בַת יִשְרָאֵל וְיִפְלִיחַנְכוֹן שִׁית שְׁנִין וּבְמַעֲלֵי שְׁבִיעֲתָא תִפְטְרוּנֵיהּ לְבַר חוֹרִין מִגַּבֵּיכוֹן\",0,0],[4,142,15,13,\"וַאֲרוּם אִין תִּפְטְרוּנֵיהּ בַּר חוֹרֵי מִגַּבֵּיכוֹן לָא תִפְטְרוּנֵיהּ רֵיקָנָא\",0,0],[4,142,15,14,\"מְדַחֲרָא תְדַחֲרוּן לֵיהּ מִן עַנְכוֹן מִן אִידְרֵיכוֹן וּמִן מַעֲצַרְתְּכוֹן דְּבָרִיכֵיכוֹן יְיָ אֱלָהָכוֹן תִּתְּנוּן לֵיהּ\",0,0],[4,142,15,15,\"וְתֶהֱווֹן דְּכִירִין אֲרוּם מְשַׁעֲבְּדִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרַיִם וּפְרַקְכוֹן יְיָ אֱלָהָכוֹן מְטוּל כֵּן אֲנָא מְפַקְדְּכוֹן לְמֶעֱבַד יַת פִּתְגָמָא הָדֵין יוֹמָא דֵין\",0,0],[4,142,15,16,\"וִיהֵי אֲרוּם יֵימַר לָךְ לָא אֶפּוֹק מִן גַּבָּךְ אֲרוּם רַחֲמָךְ וְיַת אֵינַשׁ בֵּיתָךְ אֲרוּם טַב לֵיהּ דְּמִתְהָנֵי עִמָךְ\",0,0],[4,142,15,17,\"וְתִסַּב יַת מַחְטָא וְתִנְעוֹץ בְּאוּדְנֵיהּ וּבִתְרַע בֵּית דִינָא וִיהֵי לָךְ עֶבֶד פְּלַח עַד יוֹבְלָא וְאוּף לְאַמְתָךְ תִּכְתּוֹב גֵט חֵירַר וְתִתֵּן לָהּ\",0,0],[4,142,15,18,\"לָא יִקְשֵׁי בְעֵינָךְ בְּמִפְטְרָךְ יָתֵיהּ לְבַר חוֹרִין מִן גַבָּךְ אֲרוּם בְּכוּפְלָא עַל אֲגַר אֲגִירָא פַּלְחָךְ שִׁית שְׁנִין וּבֵירְכָךְ מְטוּלֵיהּ יְיָ אֱלָהָךְ בְּכָל מַה דְּתֶעֱבַד\",0,0],[4,142,15,19,\"כָּל בּוּכְרָא דְאִתְיְלִיד בְּתוֹרָךְ וּבְעָנָךְ דּוּכְרַיָא תַּקְדֵּישׁ קֳדָם יְיָ אֱלָהָךְ לָא תִפְלוֹחַ בְּבִכּוּרֵי תּוֹרֵיכוֹן וְלָא תֵיגוֹז בִּכּוּרֵי עָנֵיכוֹן\",0,0],[4,142,15,20,\"קֳדָם יְיָ אֱלָהָכוֹן תֵּיכְלִינֵיהּ שְׁנָא בִּשְׁנָא בְּאַתְרָא דְיִתְרְעֵי יְיָ אַתּוּן וְאֵינַשׁ בָּתֵּיכוֹן\",0,0],[4,142,15,21,\"וַאֲרוּם יְהֵי בֵּיהּ מוּמָא חֲגִיר אוֹ סָמֵי כָּל מִדַּעַם בִּישׁ לָא תִכְסִינֵיהּ קֳדָם יְיָ אֱלָהָכוֹן\",0,0],[4,142,15,22,\"בְּקִרְוֵיכוֹן תֵּיכְלִינֵיהּ דִּמְסָאָב מִן לְמִקְרַב לְקוּדְשַׁיָא וְדִדְכֵי לְמִקְרַב לְקוּדְשַׁיָא כַּחֲדָא הֵי כִּבְשַר טַבְיָא וְאַיְלָא\",0,0],[4,142,15,23,\"לְחוֹד אַדְמֵיהּ לָא תֵיכְלוּן עַל אַרְעָא תֵישְׁדוּנֵיהּ הֵי כְמַיָא\",0,0],[4,142,16,1,\"הֲווֹן זְהִירִין לְמִנְטוֹר זִמְנֵי מוֹעֲדַיָא לְעִבּוּרֵי שַׁתָּא וּלְמִנְטוֹר תְּקוּפְתָּא בְּיַרְחָא דְאַבִּיבָא לְמֶעֱבַד בֵּיהּ פִּסְחָא קֳדָם יְיָ אֱלָהָכוֹן אֲרוּם בְּיַרְחָא דְאַבִּיבָא אַפֵּיק יַתְכוֹן יְיָ אֱלָהָכוֹן מִמִּצְרַיִם וְתֵיכְלוּן יָתֵיהּ בְּלֵילְיָא\",0,0],[4,142,16,2,\"וְתִיכְסוּן פִּסְחָא קֳדָם יְיָ אֱלָהָכוֹן בֵּינֵי שִׁמְשָׁתָא וְעָאן וְתוֹרֵי לִמְחָר בִּכְרַן יוֹמָא לְחֶדְוַת חַגָּא בְּאַתְרָא דְיִתְרְעֵי יְיָ לְאַשְׁרָאָה שְׁכִינְתֵּיהּ תַּמָּן\",0,0],[4,142,16,3,\"לָא תֵיכְלוּן עַל פִּסְחָא חֲמִיעַ שׁוּבְעָא יוֹמִין תֵּיכְלוּן לִשְׁמֵיהּ פַּטִּיר לַחֲמָא עַנְיָא אֲרוּם בִּבְהִילוּ נְפַקְתּוּן מֵאַרְעָא דְמִצְרַיִם מִן בִּגְלַל דְּתִידְכְּרוּן יַת יוֹם מַפְקְכוֹן מֵאַרְעָא דְמִצְרַיִם כָּל יוֹמֵי חַיֵּיכוֹן\",0,0],[4,142,16,4,\"וְתִזְדַהֲרוּן מִקַּמֵּי פִּסְחָא דְלָא יִתְחָמֵי לְכוֹן חֲמִיר בְּכָל תְּחוּמְכוֹן שׁוּבְעָא יוֹמִין וְלָא יְבִית בַּר מִן בִּשְרָא דְתִכְסוּן בְּרַמְשָׁא בְּיוֹמָא קַמָּאָה לְצַפְרָא\",0,0],[4,142,16,5,\"לֵית לְכוֹן רְשׁוּ לְמִכּוֹס יַת פִּסְחָא בַּחֲדָא מִן קִירְוֵיכוֹן דַּיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן\",0,0],[4,142,16,6,\"אֱלָהֵן בְּאַתְרָא דְיִתְרְעֵי יְיָ אֱלָהָכוֹן לְאַשְׁרָאָה שְׁכִינְתֵּיהּ תַּמָּן תִּיכְסוּן יַת פִּסְחָא וּבְרַמְשָׁא בְּמֵיעֲלִית שִׁמְשָׁא תֵּיכְלוּנֵיהּ עַד פַּלְגוּת לֵילְיָא זְמַן שַׁרְיוּת פּוּרְקַנְכוֹן מִמִּצְרָיִם\",0,0],[4,142,16,7,\"וְתִטְווּן וְתֵיכְלוּן בְּאַתְרָא דְיִתְרְעֵי יְיָ אֱלָהָכוֹן בֵּיהּ וְתִתְפְּנֵי בְּצַפְרָא מֵיפַק חַגָא וּתְהַךְ לְקִרְוָוךְ\",0,0],[4,142,16,8,\"בְּיוֹמָא קַמָּא תְקַרְבוּן יַת עוֹמְרָא וְתֵיכְלוּן פַּטִּירֵי מַעֲלַלְתָּא עַתִּיקָא וְשִׁתָּא יוֹמִין דְּאִשְׁתְּיָירוּ תְּהוֹן מַרְשַׁן לְמֵיכוֹל פַּטוּרֵי מַעֲלַלְתָּא חֲדַתָּא וּבְיוֹמָא שְׁבִיעָאָה הַהוּא תְּהוֹן כְּנִישִׁין בְּתוּשְׁבְּחָא קֳדָם יְיָ אֱלָהָכוֹן לָא תַעַבְדוּן עִיבִידְתָּא\",0,0],[4,142,16,9,\"שׁוּבְעָא שְׁבוּעִין תִּימְנוּן לְכוֹן מִזְמַן דְּתִשְׁרוּן לְמִשְׁלַח מַגְלָא לְמַחֲצוֹד בְּחַקְלָא בָּתַר חֲצַד עוֹמְרָא תֵּישְׁרוּן לְמִמְנֵי שׁוּבְעָא שְׁבוּעִין\",0,0],[4,142,16,10,\"וְתַעַבְדוּן חֶדְוַת חַגָּא דְשָׁבוּעַיָיא קֳדָם יְיָ אֱלָהָכוֹן הֵי כְּמֵסַת נִדְבַת יְדֵיכוֹן הֵיכְמָא דְבָרְכֵיכוֹן יְיָ אֱלָהָכוֹן\",0,0],[4,142,16,11,\"וְתֵיחְדוּן בְּחֶדְוַת חַגָא קֳדָם יְיָ אֱלָהָכוֹן אַתּוּן וּבְנֵיכוֹן וּבְנָתֵיכוֹן וְעַבְדֵיכוֹן וְאַמְהָתֵיכוֹן וְלֵוָאֵי דִי בְקִרְוֵיכוֹן וְגִיּוֹרָא וְיַתְמָא וְאַרְמַלְתָּא דִי בֵינֵיכוֹן בְּאַתְרָא דְיִתְרְעֵי יְיָ אֱלָהָכוֹן לְאַשְׁרָאָה שְׁכִינְתֵּיהּ תַּמָּן\",0,0],[4,142,16,12,\"וְתֶהֱווֹן דְּכִירִין אֲרוּם מְשַׁעְבְּדִין הֲוֵיתוּן בְּמִצְרַיִם וְתִיטְרוּן וְתַעַבְדוּן יַת קְיָימַיָא הָאִלֵין\",0,0],[4,142,16,13,\"חַגָא דִמְטָלַיָא תַעַבְּדוּן לְכוֹן שׁוּבְעָא יוֹמִין בְּמִשְׁלַמְכוֹן לְמִכְנוֹשׁ עֲלַלְתָּא מֵאִידִירֵכוֹן וְחַמְרָא מִן מַעֲצַרְתֵּיכוֹן\",0,0],[4,142,16,14,\"וְתֵיחְדוּן בְּחֶדְוַת חַגֵּיכוֹן בְּשָׁאוּבְתָּא וְחָלִילָא אַתּוּן וּבְנֵיכוֹן וּבְנָתֵיכוֹן וְאַמְהוֹתֵיכוֹן וְלֵיוָאָה וְגִיּוֹרָא וְיַתְמָא וְאַרְמַלְתָּא דִי בְקִרְוֵיכוֹן\",0,0],[4,142,16,15,\"שׁוּבְעָא יוֹמָא תְּחַגּוּן קֳדָם יְיָ אֱלָהָכוֹן בְּאַתְרָא דְיִתְרְעֵי יְיָ אֲרוּם יְבָרֵיכְכוֹן יְיָ אֱלָהָכוֹן בְּכָל עֲלַלְתְּכוֹן וּבְכָל עוֹבָדֵי אִידֵיכוֹן וְתֶהֱווֹן בְּרַם חַדְוָן בְּאַצְלָחוּתָא\",0,0],[4,142,16,16,\"תְּלַת זִימְנִין בְּשַׁתָּא יִתְחֲמוּן כָּל דְּכוּרֵיכוֹן קֳדָם יְיָ אֱלָהָכוֹן בְּאַתְרָא דְיִתְרְעֵי בְּחַגָּא דְפַטִּירַיָא וּבְחַגָּא דְשָׁבוּעַיָא וּבְחַגָּא דִמְטָלַיָא וְלֵיתֵיכוֹן רַשָּׁאִין לְמִתְחַמְיָא קֳדָם יְיָ אֱלָהָכוֹן רֵיקָנוּן מִכָּל מִצְוָתָא\",0,0],[4,142,16,17,\"גְּבַר הֵי כְּמֵיסַת מוֹהֲבוֹת יְדֵיהּ כְּבִרְכָתָא דַּיְיָ אֱלָהָכוֹן דִּיהַב לְכוֹן\",0,0],[4,142,16,18,\"שופטים דַּיָּנִין קְשׁוּטִין וְסַרְכִין אַלִּימִין תְּמַנּוּן לְכוֹן בְּכָל קִירְוֵיכוֹן דַּיְיָ אֱלָהָכוֹן יָהִיב לְכוֹן לְשִׁבְטֵיכוֹן וִידוּנוּן יַת עַמָּא דִּין קְשׁוֹט\",0,0],[4,142,16,19,\"לָא תֵיצְלוּן דִּינָא וְלָא תִסְבּוּן אַפִּין וְלָא תְקַבְּלוּן שׁוֹחֲדָא אֲרוּם שׁוֹחֲדָא מְסַמֵּי עֵינֵי חַכִּימַיָא דְנַסְבִין לֵיהּ דְּגָרִים לְהוֹן טִפְּשׁוּתָא וּמְעַרְבֵּב מִילִין זַכָּאִין בְּפוּם דַּיָּינַיָא בְּשַׁעַת דִּינֵיהוֹן\",0,0],[4,142,16,20,\"דִּין קְשׁוֹט וְדִין שְׁלַם בִּקְשׁוֹט תְּהֵי רָדִיף מִן בִּגְלַל דְּתֵיחוּן וְתֵירְתוּן יַת אַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן\",0,0],[4,142,16,21,\"הֵיכְמָא דְלֵיתֵיכוֹן רַשָּׁאִין לְמִנְצוֹב אֲשֵׁירָתָא לִסְטַר מַדְבְּחָא דַיְיָ הֵיכְדֵין לֵיתֵיכוֹן רַשָּׁאִין לִמְזַוְוגָא בְּדִינָא גַבְרָא טִפְּשָׁא עִם דַּיָינַיָא חַכִּימַיָא לְמַלִיפָא לְכוֹן יַת דְּתַעַבְּדוּן לְכוֹן\",0,0],[4,142,16,22,\"וְהֵיכְמָא דְלֵיתֵיכוֹן רְשָׁאִין לְמִקְמָא קָמָא הֵיכְדֵין לֵיתֵיכוֹן רַשָּׁאִין לְמַנָאָה לְפַרְנָסָא גַּבְרָא זִידְנָא דְרַחֲקֵיהּ יְיָ אֱלָהָכוֹן\",0,0],[4,142,17,1,\"לָא תִכְסוּן קֳדָם יְיָ אֱלָהָכוֹן תּוֹר וְאִימַר דִּיהֵי בֵיהּ מוּמָא אוֹ כָּל מִדַּעַם בִּישׁ דְּגָזִיל וְאָנִיס אֲרוּם מְרַחֵק קֳדָם יְיָ אֱלָהָכוֹן הוּא\",0,0],[4,142,17,2,\"אֲרוּם יִשְׁתַּכַּח בֵּינֵיכוֹן בַּחֲדָא מִן קוּרְיֵיכוֹן דַּיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן גְּבַר אוֹ אִיתָא דְּעָבַד דְּבִישׁ קֳדָם יְיָ אֱלָהָכוֹן לְמֵעִיבַר עַל קְיָימֵיהּ\",0,0],[4,142,17,3,\"וַאֲזַל בָּתַר יִצְרָא בִּישָׁא וּפְלַח לְטַעֲוַות עַמְמַיָא וּסְגִיד לְהוֹן וּלְשִׁמְשָׁא אוֹ לְסִיהֲרָא אוֹ לְכָל חֵילָא שְׁמַיָא דְלָא פַקֵּידִית\",0,0],[4,142,17,4,\"וְאִתְחַוָא לְכוֹן וְתִשְׁמְעוּן וְתִיתְבְּעוּן יַת סַהֲדַיָא טַבְאוּת וְהָא קוּשְׁטָא כֵּיוַן פִּתְגָמָא אִתְעֲבִידַת תּוֹעֵבְתָּא הָדָא בֵּינֵיכוֹן\",0,0],[4,142,17,5,\"וְתִפְקוּן יַת גַּבְרָא הַהוּא אוֹ יַת אִנְתְּתָא הַהִיא דְּעָבְדוּ יַת פִּתְגָמָא בִּישָׁא הָדֵין לִתְרַע בֵּית דִּינֵיכוֹן יַת גַּבְרָא אוֹ יַת אִינְתְּתָא וּתְאַטְלוּנוּן בְּאַבְנַיָא וִימוּתוּן\",0,0],[4,142,17,6,\"עַל מֵימַר תְּרֵין סַהֲדִין אוֹ תְּלָתָא סַהֲדִין יִתְקְטֵיל דְּמִתְחַיֵּיב קָטוֹלָא לָא יִתְקְטֵיל עַל מֵימַר סָהִיד חָד\",0,0],[4,142,17,7,\"יְדָא דְסַהֲדַיָא תְהֵי בֵיהּ בְּשֵׁירוּיָא לְמִקְטְלֵיהּ וִידָא דְכָל עַמָּא בְּבַתְרֵיתָא וּתְפַלּוּן עֲבִיד דְּבִישׁ מִבֵּינֵיכוֹן\",0,0],[4,142,17,8,\"אֲרוּם יִתְפְּרֵשׁ מִנְכוֹן פִּתְגָמָא לְדִינָא בֵּינֵי אֲדַם סְאוֹב לַאֲדַם דְּכֵי וּבֵינֵי דִינָא נַפְשָׁתָא לְדִינָא מָמוֹנָא וּבֵינֵי מַכְתַּשׁ צוֹרְעָא לְמַכְתַּשׁ נִתְקָא מִלֵי פְּלוּגְתָּא בְּבֵית דִּינֵיכוֹן וּתְקוּמוּן וְתִסְקוּן לְאַתְרָא דְיִתְרְעֵי יְיָ אֱלָהָכוֹן בֵּיהּ\",0,0],[4,142,17,9,\"וְתֵיתוּן לְוַת כַּהֲנַיָא דְמִשֵּׁבֶט לֵוִי וּלְוַת דַּיָּינָא דִי יְהֵי בְיוֹמַיָא הָאִינוּן וְתִתְבְּעוּן מִנְהוֹן וִיחַוּוּן לְכוֹן יַת הִלְכַת דִּינָא\",0,0],[4,142,17,10,\"וְתַעַבְדוּן עַל מֵימַר הִלְכַת אוֹרַיְיתָא דִיחַוּוּן לְכוֹן מִן אַתְרָא הַהוּא דְיִתְרְעֵי יְיָ וְתִטְרוּן לְמֶעֱבַד כְּכָל דְּיַלְפוּנְכוֹן\",0,0],[4,142,17,11,\"עַל מֵימַר אוֹרַיְיתָא דְיַלְפוּנְכוֹן וְעַל הִילְכַת דִּינָא דְיֵימְרוּן לְכוֹן תַּעַבְדוּן לָא תִסְטוּן מִן פִּתְגָמָא דִיחַוּוּן לְכוֹן יְמִינָא וּשְמָאלָא\",0,0],[4,142,17,12,\"וְגַבְרָא דְיַעֲבֵיד בְּזָדְנוּתָא בְּדִיל דְּלָא לְמֵיצַת מִן כַּהֲנָא דְקָאִים לְשַׁמָּשָׁא תַּמָּן קֳדָם יְיָ אֱלָהָכוֹן אוֹ מִן דַּיָינָא וְיִתְקְטֵיל גַּבְרָא הַהוּא וּתְפַלּוּן עֲבִיד דְּבִישׁ מִיִּשְרָאֵל\",0,0],[4,142,17,13,\"וְכָל עַמָּא יִשְׁמְעוּן וִידַחֲלוּן וְלָא יַרְשִׁיעוּן תּוּב\",0,0],[4,142,17,14,\"אֲרוּם תֵּיעָלוּן לְאַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן וְתֵרְתוּן יָתָהּ וְתֵיתְבוּן בָּהּ וְתֵמְרוּן נְמַנֵי עֲלָן מַלְכָּא כְּכָל עַמְמַיָא דִבְחַזְרָנוּתָי\",0,0],[4,142,17,15,\"תִּתְבְּעוּן אוּלְפַן מִן קֳדָם יְיָ וּמִבָּתַר כְּדֵין תִּמְנוּן עֲלֵיכוֹן מַלְכָּא לֵית לְכוֹן רְשׁוּ לְמַנָּאָה עֲלֵיכוֹן גְּבַר חִילוֹנַי דְלָא מִן אֲחוּכוֹן הוּא\",0,0],[4,142,17,16,\"לְחוֹד לָא יִסְגוּן לֵיהּ עַל תְּרֵין סוּסְוָון דִּלְמָא יִרְכְּבוּן רַבְרְבָנוֹי עֲלֵיהוֹן וְיִתְגָאוּן וְיִתְבַּטְלוּן מִפִּתְגָמֵי אוֹרַיְיתָא וִיחוֹבוּן חוֹבַת גָּלוּתָא לְמִצְרַיִם וַיְיָ אָמַר לְכוֹן לָא תוֹסְפוּן לְמֵתוּב בְּאָרְחָא הָדֵין תּוּב\",0,0],[4,142,17,17,\"וְלָא יִסְגוּן לֵיהּ נְשִׁין עַל תַּמְנַסְרֵי דְּלָא יִטְעוּן לִבֵּיהּ וְכַסְפָּא וְדַהֲבָא לָא יִסְגֵי לֵיהּ דְּלָא יִתְרוֹמָם לִבֵּיהּ לַחֲדָא וְיִמְרוֹד בֶּאֱלָהָא שְׁמַיָא\",0,0],[4,142,17,18,\"וִיהֵי אִין נְיַיח הוּא בְּמִצְוָותָא דְאוֹרַיְיתָא יָתֵיב לְרוֹחֲצָן עַל כּוּרְסֵי מַלְכוּתֵיהּ וְיִכְתְּבוּן לֵיהּ סָבַיָא יַת פַּרְשָׁא אוֹרַיְיתָא הָדָא עַל סִפְרָא מִן קֳדָם כַּהֲנַיָא דְּמִן שֵׁבֶט לֵוִי\",0,0],[4,142,17,19,\"וּתְהֵי גַבֵּיהּ וִיהֵי קָרֵי בֵּיהּ כָּל יוֹמֵי חַייוֹי מִן בִּגְלַל דְּיַלִּיף לְמִדְחַל מִן קֳדָם יְיָ אֱלָהֵיהּ לְמִנְטַל יַת כָּל פִּתְגָמֵי אוֹרַיְיתָא הָדָא וְיַת כָּל קְיָימַיָא הָאִלֵּין לְמֶעֱבַדְהוֹן\",0,0],[4,142,17,20,\"מְטוּל דְּלָא יָגִיס לִבֵּיהּ יַתִּיר מִן אָחוֹי וּמְטוּל דְּלָא יִסְטֵי מִן תַּפְקֵידְתָּא לְיַמִינָא וְלִשְמָאלָא מִן בִּגְלַל דְּיִנְגוֹד יוֹמִין עַל מַלְכוּתֵיהּ הוּא וּבְנוֹי בֵּינֵי יִשְרָאֵל\",0,0],[4,142,18,1,\"לָא יְהֵי לְכַהֲנַיָא דְּמִן שֵׁבֶט לֵוִי חוּלַק וְאַחְסָנָא עִם אָחוֹי קוּרְבָּנַיָא דַיְיָ וּבְאַחֲסַנְתְּהוֹן יֵיכְלוּן\",0,0],[4,142,18,2,\"וְאַחֲסָנַת חֲקַל וּכְרַם לָא תְהֵי לֵיהּ בֵּינֵי אָחוֹי עֶשְרִין וְאַרְבַּע מוֹהֲבוּתָא דִכְהוּנְתָּא דִיהַב לֵיהּ יְיָ הִינוּן אַחְסַנְתֵּיהּ הֵיכְמָא דְמַלִּיל לֵיהּ\",0,0],[4,142,18,3,\"וְדֵין יְהֵי חוּלְקָא דְּחָמֵי לְכַהֲנַיָא מִן עַמָּא מִלְוַת דִּבְחֵי דִבְחִין אִין תּוֹר אִין אִימַר וְיִתְּנוּן לְכַהֲנָא אִדְרָעָא דְיַמִּינָא וְלוּחַיָא אַרְעֲיָא וְלוּחַיָא דִרְקִיתָא וְקֵיבְתָא\",0,0],[4,142,18,4,\"שֵׁירוּי עִיבּוּרֵיכוֹן חַמְרֵיכוֹן וּמִשְׁחֵיכוֹן וְשֵׁירוּי גִּיזַת עָנֵיכוֹן כְּמִסַת קָטוֹרָא תִּתְּנוּן לֵיהּ\",0,0],[4,142,18,5,\"מְטוּל דְּבֵיהּ אִתְרְעֵי יְיָ אֱלָהָכוֹן מִכָּל שִׁבְטֵיכוֹן לְמֵיקוּם לְשַׁמָּשָׁא בִּשְׁמָא דַיְיָ הוּא וּבְנוֹי כָּל יוֹמַיָא\",0,0],[4,142,18,6,\"וַאֲרוּם יֵיתֵי לֵיוָאָה מֵחֲדָא מִן קִרְוֵיכוֹן מִן כָּל יִשְרָאֵל דְּהוּא דַיָיר תַּמָּן וְיֵיתֵי בְּכָל כְּרוּךְ דְּרָעֲיָא נַפְשֵׁיהּ לְאַתְרָא דְיִתְרְעֵי יְיָ\",0,0],[4,142,18,7,\"וִישַׁמֵּשׁ בְּשׁוּם מֵימְרָא דַיְיָ אֱלָהֵיהּ הֵי כְּכָל אָחוֹי לֵיוָאֵי דִמְשַׁמְשִׁין תַּמָּן קֳדָם יְיָ\",0,0],[4,142,18,8,\"חוּלַק כָּל קֳבֵיל חוּלַק בְּשָׁוֶה יֵיכְלוּן בַּר מִמּוֹתְבֵי קוּרְבָּנַיָא דְיֵיכְלוּן כַּהֲנַיָא דְאוֹרִיתוּ לְהוֹן אֶלְעָזָר וְאִיתָמָר אֲבָהַתְכוֹן\",0,0],[4,142,18,9,\"אֲרוּם אַתּוּן עַלְלִין לְאַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן לָא תֵילְפוּן לְמֶעֱבַד כְּרִיחוֹקֵי עַמְמַיָא הָאִינוּן\",0,0],[4,142,18,10,\"לָא יִשְׁתְּכַח בְּכוֹן מְעַבְּרִין בְּנֵיהוֹן וּבְנָתֵיהוֹן בְּנוּרָא לָא קְסוֹמֵי קוּסְמִין וְלָא חֲרוּרֵי עַיְינִין וְלָא נַטוֹרֵי נְחָשִׁין וְלָא חַרְשִׁין\",0,0],[4,142,18,11,\"וּמְחַבְּרִין וְאַסְרִין חֵיוִין וְעַקְרַבִּין וְכָל מִינֵי רַחֲשִׁין וְשַׁאֲלִין אִיבָא טַמְיָא וּגְרַם יָדוּעַ וּתְבַע מִן מֵיתַיָא\",0,0],[4,142,18,12,\"אֲרוּם מְרַחֵק קֳדָם יְיָ כָּל עֲבֵיד אִלֵין וּמְטוֹל תּוֹעֵיבְתָּא הָאִילֵין יְיָ אֱלָהָכוֹן מְתָרֵיכֵיהוֹן מִן קֳדָמֵיכוֹן\",0,0],[4,142,18,13,\"שַׁלְמִין תְּהוֹן בְּדַחַלְתָּא דַיְיָ אֱלָהָכוֹן\",0,0],[4,142,18,14,\"אֲרוּם עַמְמַיָא הָאִלֵין דְּאַתּוּן עֲתִידִין לְמֵירוֹת יַתְהוֹן לְחַרוֹרֵי עֵינָא וּלְקִיסוּמֵי קוּסְמַיָא צַיְיתוּן וְאַתּוּן לָא כְוַותְהוֹן אֱלָהֵן כַּהֲנַיָא שַׁיְילוּן אוּרַיָא וְתוּמַיָא וְנָבִיָא תְרִיצַיָא יְהַב לְכוֹן יְיָ אֱלָהָכוֹן\",0,0],[4,142,18,15,\"נְבִיָא מִבֵּינֵיכוֹן מִן אֲחוּכוֹן דְּדָמֵי לִי בְּרוּחַ קוּדְשָׁא יְקִים לְכוֹן יְיָ אֱלָהָכוֹן מִנֵּיהּ תְקַבְּלוּן\",0,0],[4,142,18,16,\"כְּכל דְּשַׁיִּילְתּוּן מִן קֳדָם יְיָ אֱלָהָכוֹן בְּחוֹרֵב בְּיוֹמָא דְאִתְכַּנָּשׁוּ שִׁבְטַיָא לִמְקַבְּלָא אוֹרַיְיתָא לְמֵימָר לָא נוֹסִיף לְמִשְׁמַע יַת קַל דִּיבּוּרָא מִן קֳדָם יְיָ אֱלָהָנָא וְיַת אֵישָׁתָא רַבְּתָא הֲדָא לָא נֶחֱמֵי תּוּב דְּלָא נְמוּת\",0,0],[4,142,18,17,\"וַאֲמַר יְיָ לִי אַתְקִינָן מַה דְּמַלֵּילָן\",0,0],[4,142,18,18,\"נְבִיָא אָקִים לְהוֹן מִבֵּינֵי אֲחוּהוֹן דְּרוּחַ קוּדְשָׁא בֵּיהּ כְּוָותָךְ וְאֶתֵּן פִּתְגָמֵי נְבוּאָתִי בְּפוּמֵיהּ וִימַלֵּיל עִמְהוֹן יַת כָּל דְּאִיפְקְדִינֵיהּ\",0,0],[4,142,18,19,\"וִיהֵי גַבְרָא דְלָא יִתְקַבֵּל פִּתְגָמֵי נְבוּאָתִי דִימַלֵּיל בִּשְׁמִי מֵימְרִי יִפְרַע מִנֵּיהּ\",0,0],[4,142,18,20,\"בְּרַם נְבִי שִׁקְרָא דְיִרְשַׁע לְמַלָלָא פִּתְגָמָא בִּשְׁמִי יַת דְּלָא פַקִידְתֵּיהּ לְמַלָּלָא וְדִי יְמַלֵּל בְּשׁוּם טַעֲוַות עַמְמַיָא וְיִתְקְטֵיל נְבִיָא הַהוּא בְּסַיְיפָא\",0,0],[4,142,18,21,\"וַאֲרוּם תֵּימְרוּן בְּרַעֲיוֹנֵיכוֹן הֵיכְדֵין נֵידַע יַת פִּתְגָּמָא דְלָא מַלְלֵיהּ יְיָ\",0,0],[4,142,18,22,\"מַה דִּימַלֵּיל נְבִי שִׁקְרָא בִּשְׁמָא דַיְיָ וְלָא יֵיתֵי פִּתְגָּמָא וְלָא יִתְקַיֵּים הוּא פִּתְגָּמָא דְּלָא מַלְלֵיהּ יְיָ בִּזְדָנוּתָא מַלְלֵיהּ נְבִי שִׁקְרָא לָא תִדַחֲלוּן מִנֵּיהּ\",0,0],[4,142,19,1,\"אֲרוּם יְשֵׁיצֵי יְיָ אֱלָהָכוֹן יַת עַמְמַיָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן יַת אַרְעֲהוֹן וְתֵירְתִינוּן וְתֵיתְבוּן בְּקִירְוֵיהוֹן וּבְבָתֵּיהוֹן\",0,0],[4,142,19,2,\"תְּלַת קִרְוִין תִּפְרְשׁוּן לְכוֹן בְּגוֹ אַרְעֲכוֹן דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן לְמֵירְתָהּ\",0,0],[4,142,19,3,\"תְּכַוְונוּן לְכוֹן אָרְחָא וּתְתַלְתוּן יַת תְּחוּם אַרְעֲכוֹן דִּיחַסְנְכוֹן יְיָ אֱלָהָכוֹן וִיהֵי לְמַעֲרוֹק לְתַמָּן כָּל קָטוֹלָא\",0,0],[4,142,19,4,\"וְדֵין הִילְכַת קָטוֹלָא דְיַעֲרוֹק לְתַמָּן וְיֵיחֵי דְּיִקְטוֹל יַת אָחֵיהּ בְּלָא מִתְכַוִין לֵיהּ וְהוּא לָא נְטַר לֵיהּ סְנָא מֵאִתְמְלֵי וּמִדְקֳדָמוֹי\",0,0],[4,142,19,5,\"וּמַאן דְּעָלֵיל עִם חַבְרֵיהּ בְּחֻרְשָׁא לְמִקְטַע קִיסִין וְתִדְחַף אִידֵיהּ בְּסִיקוֹרְיָא לְמִקְטַע קִיסָא וְיִשְׁמוֹט פַּרְזְלָא מִן קַתָּא וְיַשְׁכַּח יַת חַבְרֵיהּ וִימוּת הוּא יַעֲרוֹק לַחֲדָא מִן קִירְוַיָא מְזַמְנַיָיא הָאִלֵּין וְיֵיחֵי\",0,0],[4,142,19,6,\"דִּלְמָא יִרְדוֹף תְּבַע אַדְמָא בָּתַר קָטוֹלָא אֲרוּם יִרְתַח עֲלוֹי לִבֵּיהּ בְּעַקְתֵיהּ וְיִדְבְּקֵיהּ אֲרוּם תַּסְגֵי אָרְחָא וְיִקְטְלִינֵיהּ נְפָשׁ וְלֵיהּ לָא אִית חוֹבַת דִּין דִּקְטוֹל אֲרוּם לָא סָנֵי הוּא לֵיהּ מֵאִתְמְלֵי וּמִדְקֳדָמוֹי\",0,0],[4,142,19,7,\"בְּגִין כֵּן אֲנָא מְפַקֵּיד לְכוֹן יוֹמָא דֵין תְּלַת קִירְוִין תִּפְרְשׁוּן לְכוֹן\",0,0],[4,142,19,8,\"וְאִין יַפְתֵּי יְיָ אֱלָהָכוֹן יַת תְּחוּמְכוֹן הֵיכְמָא דְקַיֵּים לְאַבְהַתְכוֹן וְיִתֵּן לְכוֹן יַת כָּל אַרְעָא דְקַיֵּים לְמִתַּן לְאַבְהַתְכוֹן\",0,0],[4,142,19,9,\"אֲרוּם תִּנְטְרוּן יַת כָּל תַּפְקֵידְתָּא הֲדָא לְמֶעֱבְדָהּ דַּאֲנָא מְפַקְדְּכוֹן יוֹמָא דֵין לְמִרְחַם יַת יְיָ אֱלָהָכוֹן וְלִמְהַךְ בְּאָרְחַן דְּתַקְנָן קֳדָמוֹי כָּל יוֹמַיָא וְתוֹסְפוּן לְכוֹן תּוּב תְּלַת קִירְוִין עַל תְּלַת אִילֵין\",0,0],[4,142,19,10,\"וְלָא יִתְשַׁד אֲדַם זַכַּאי בְּאַרְעֲכוֹן דַּיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן אַחְסָנָא וִיהֵי עֲלֵיכוֹן חוֹבַת דִּין קָטוֹלָא\",0,0],[4,142,19,11,\"וַאֲרוּם יְהֵי גְּבַר סָנֵי לְחַבְרֵיהּ וְיִכְמוֹן עֲלֵיהּ בְּטוּמְרָא וִיקוּם עֲלוֹי וְיִקְטְלִינֵיהּ נְפָשׁ וִימוּת וְיַעֲרוֹק לַחֲדָא מִן קִרְוַיָא הָאִלֵּין\",0,0],[4,142,19,12,\"וִישַׁדְרוּן חַכִּימִין קַרְתֵּיהּ וִידַבְּרוּן יָתֵיהּ מִתַּמָּן וְיִמְסְרוּן יָתֵיהּ בְּיַד תְּבַע אַדְמָא וְיִתְקְטֵל\",0,0],[4,142,19,13,\"לָא תֵיחוּס עֵינֵיכוֹן עֲלוֹי וּתְפַלּוּן שַׁדְיֵי דַם זַכַּאי מִיִּשְרָאֵל וְיֵיטִיב לְכוֹן\",0,0],[4,142,19,14,\"לָא תְשַׁנּוּן תְּחוּם חֲבֵירֵיכוֹן דְּאִתְחִימוּ קַמָּאֵי בְּאַחְסַנְתְּכוֹן דְּתַחְסְנוּן בְּאַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן לְמֵירְתָהּ\",0,0],[4,142,19,15,\"לָא יִתְקַיֵּים סַהֲדוּ דְּחַד בִּגְבַר לְכָל סָרְחָן נְפָשׁ וּלְכָל חוֹב מָמוֹן וּלְכָל חֵט דְּיֶחֱטֵי בְּרַם עַל מֵימְרָא דַיְיָ לְמִתְפַּרְעָא עַל טוּמְרַיָא עַל מַיָא סָהִיד חָד יוֹמֵי לְמִכְפּוֹר יַת מַה דְּמַסְהִיד עֲלוֹי וְעַל מֵימַר תְּרֵין סַהֲדִין אוֹ תְּלָתָא סַהֲדִין יִתְקַיֵּים פִּתְגָּמָא\",0,0],[4,142,19,16,\"אֲרוּם יְקוּמוּן סַהֲדִין שִׁיקְרִין בְּבַר נַשׁ לְאַסְהָדָא בֵּיהּ סַטְיָא\",0,0],[4,142,19,17,\"וִיקוּמוּן תְּרֵין גּוּבְרִין דִּלְהוֹן תִּיגְרָא קֳדָם יְיָ קֳדָם כַּהֲנַיָא דַיָינַיָא דִיהוֹן בְּיוֹמַיָא הָאִינוּן\",0,0],[4,142,19,18,\"וְיִתְבְּעוּן דַּיָינַיָא לְסַהֲדִין דְּמַזְמִין יַתְהוֹן טָבְאוּת וְהָא סַהֲדוּ דִשְׁקַר בְּפוּם סַהֲדִין שִׁיקְרָא אַסְהִידוּ בַּאֲחוּהוֹן\",0,0],[4,142,19,19,\"וְתַעַבְדוּן לְהוֹן הֵיכְמָא דַחֲשִׁיבוּ לְמֶעֱבַד לַאֲחוּהוֹן וּתְפַלוּן עַבְדֵי דְבִישׁ מִבֵּינֵיכוֹן\",0,0],[4,142,19,20,\"וְרַשִׁיעַיָא דְמִשְׁתַּיְירִין יִשְׁמְעוּן וִידַחֲלוּן וְלָא יוֹסְפוּן לְמֶעֱבַד תּוּב כְּפִתְגָמָא בִּישָׁא הָדֵין בֵּינֵיכוֹן\",0,0],[4,142,19,21,\"וְלָא תֵיחוֹס עֵינֵיכוֹן נַפְשָׁא חֲלוּפֵי נַפְשָׁא דְמֵי עֵינָא חוּלַף עֵינָא דְמֵי שִׁינָא חוּלַף שִׁינָא דְמֵי יְדָא חוּלַף יְדָא דְמֵי רִיגְלָא חוּלַף רִיגְלָא\",0,0],[4,142,20,1,\"אֲרוּם תִּפְקוּן לְסִדְרֵי קְרָבָא עַל בַּעֲלֵי דְבָבֵיכוֹן וְתֵיחְמוּן סוּסְוָן וְאַרְתְּכִין עַמִּין גֵּיוְתָנִין וְטֵירוּנִין אַלִּימִין מִנְכוֹן לָא תִדַחֲלוּן מִנְהוֹן אֲרוּם כֻּלְהוֹן חֲשִׁיבִין כְּסוּסְיָא חַד וְכִרְתֵיכָא חַד קֳדָם יְיָ אֱלָהָכוֹן דְּמֵימְרֵיהּ בְּסַעַדְכוֹן דְּאַפְקְכוֹן פְּרִיקִין מֵאַרְעָא דְמִצְרָיִם\",0,0],[4,142,20,2,\"וִיהֵי בִּזְמַן דְּאַתּוּן קָרֵיבִין לְאַגָּחָא קְרָבָא וְיִתְקָרֵב כַּהֲנָא וִימַלֵּל עִם עַמָּא\",0,0],[4,142,20,3,\"וְיֵימַר לְהוֹן שְׁמָעוּ יִשְרָאֵל אַתּוּן מִתְקַרְבִין יוֹמָא דֵין לְסִדְרֵי קְרָבָא עַל בַּעֲלֵי דְבָבֵיכוֹן לָא יְזוּחַ לִבְּכוֹן לָא תְדַחֲלוּן וְלָא תִרְתְּחוּן וְלָא תִתְרְעוּן מִן קֳדָמֵיהוֹן\",0,0],[4,142,20,4,\"אֲרוּם יְיָ אֱלָהָכוֹן שְׁכִינְתֵּיהּ מַדְבָּרָא קֳדָמֵיכוֹן לְאַגָחָא מְטוּלְכוֹן עִם בַּעֲלֵי דְבָבֵיכוֹן לְמִפְרוֹק יַתְכוֹן\",0,0],[4,142,20,5,\"וִימַלְלוּן סַרְכַיָא עִם עַמָּא לְמֵימָר מַאן גַּבְרָא דִי בְנָא בֵיתָא חַדְתָּא וְלָא קָבַע בֵּיהּ מְזוּזְתָּא לְשַׁכְלָלוּתֵהּ יְהַךְ וִיתוּב לְבֵיתֵיהּ דִּלְמָא יִגְרוֹם לֵיהּ חוֹבָא וְיִתְקְטֵיל בִּקְרָבָא וּגְבַר חוֹרַן יְשַׁכְלְלִינֵיהּ\",0,0],[4,142,20,6,\"וּמַאן גַּבְרָא דִּי נְצַב כַּרְמָא וְלָא פַרְקֵיהּ מִן כַּהֲנָא וְאַחֲלֵיהּ יְהַךְ וִיתוּב לְבֵיתֵיהּ דִּלְמָא יִגְרוֹם לֵיהּ חוֹבָא דְלָא פָּרְקֵיהּ וְיִתְקְטֵיל בִּקְרָבָא וּגְבַר חוֹרַן יַחְלִינֵיהּ\",0,0],[4,142,20,7,\"וּמַאן גַּבְרָא דְקָדִשׁ אִתְּתָא וְלָא נַסְבָהּ יְהַךְ וִיתוּב לְבֵיתֵיהּ דְּלָא יִגְרוֹם לֵיהּ חוֹבָא דְלָא חָדֵי בְּאִנְתְּתֵיהּ וְיִתְקְטֵיל בִּקְרָבָא וּגְבַר חוֹרַן יַסְבִינָהּ\",0,0],[4,142,20,8,\"וְיוֹסְפוּן סַרְכַיָא לְמַלָלָא עִם עַמָּא וְיֵימְרוּן מַאן הוּא גַבְרָא דְדָחֵיל מֵחוֹבֵי וְלִבֵּיהּ תְּבִיר יְהַךְ וִיתוּב לְבֵיתֵיהּ דִּלְמָא יְקַבְּלוּן אָחוֹי בְּחוֹבוֹי וְיִתְבַּר לִבְּהוֹן הֵיךְ לִבֵּיהּ\",0,0],[4,142,20,9,\"וִיהֵי כַּד פַּסְקִין סַרְכַיָא לְמַלָּלָא עִם עַמָּא וְיִמְנוּן רַבְרְבָנֵי חֵילִין בְּרֵישׁ עַמָּא\",0,0],[4,142,20,10,\"אֲרוּם תִּקְרְבוּן לְקַרְתָּא לְסַדְרָא עֲלָהּ סִדְרֵי קְרָבָא וּתְשַׁדְּרוּן לְוָותָהּ פּוּלִין לְמִקְרֵי לָהּ לִשְׁלָם\",0,0],[4,142,20,11,\"וִיהֵי אִין מִלִּין דִּשְׁלָם תְּתִיב לְכוֹן וְתִפְתַּח לְכוֹן פּוּלְוָותָהּ וִיהֵי כָּל עַמָּא דְּמִשְׁתַּכַּח בָּהּ יְהוֹן לְמִסְקֵי מִיסִין וְיִפְלְחוּנְכוֹן\",0,0],[4,142,20,12,\"וְאִין לָא תַשְׁלִים עִמְכוֹן וְתַעֲבֵיד עִמְכוֹן קְרָבָא וְתֵקְפוּן עֲלָהּ\",0,0],[4,142,20,13,\"וְיִמְסְרִינָהּ יְיָ אֱלָהָכוֹן בִּידֵיכוֹן וְתִמְחֵי יַת כָּל דְּכוּרָהּ לְפִתְגָם דְּחָרֶב\",0,0],[4,142,20,14,\"לְחוֹד נְשַׁיָא וְטַפְלָא וּבְעִירָא וְכָל דִּיהֵי בְקַרְתָּא כָּל עֲדָאָהּ תִּיבְזוּן לְכוֹן וְתֵיכְלוּן יַת עֲדֵי סַנְאֵיכוֹן דִּיהַב יְיָ אֱלָהָכוֹן לְכוֹן\",0,0],[4,142,20,15,\"הֵיכְנָא תַּעַבְדוּן לְכָל קִירְוַיָא דִרְחִיקִין מִנְכוֹן לַחֲדָא דְּלָא מִקִרְוֵי שִׁבְעָתֵי עַמְמַיָא הָאִלֵּין הִינוּן\",0,0],[4,142,20,16,\"לְחוֹד מִקִּרְוֵי עַמְמַיָא הָאִילֵן דַּיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן אַחֲסָנָא לָא תְקַיְימוּן כָּל נִשְׁמָא\",0,0],[4,142,20,17,\"אֲרוּם גַּמְרָא תְגַמְרִינוּן חִתָּאֵי וֶאֱמוֹרָאֵי כְּנַעֲנָאֵי וּפְרִיזָאֵי וְחִיוָואֵי וִיבוּסָאֵי הֵיכְמָא דְפַקֵּידְכוֹן יְיָ אֱלָהָכוֹן\",0,0],[4,142,20,18,\"מִן בִּגְלַל דְּלָא יַלְפוּן יַתְכוֹן לְמֶעֱבַד כְּכָל מְרַחֲקַתְהוֹן דְּעָבָדוּ לְטַעֲוַותְהוֹן וּתְחוֹבוּן קֳדָם יְיָ אֱלָהָכוֹן\",0,0],[4,142,20,19,\"אֲרוּם תַּקְפוּן עַל קַרְתָּא כָּל יוֹמֵי שִׁבְעֲתָא לְאַגָּחָא קְרָבָא עֲלָהּ לְמִכְבְּשָׁהּ בְּשַׁבַּתָּא לָא תְחַבְּלוּן יַת אִילָנַיָהָא לְמֵישְׁדָא עֲלוֹי מָן דְּפַרְזְלָא אֲרוּם מִפֵּירוֹי תֵיכְלוּן וְיָתֵיהּ לָא תְקוּצוּן אֲרוּם לָא בְּבַר נַשׁ אִילָן דְּאַנְפֵּי בָרָא לִמְטַמְרָא מִקָּמֵיכוֹן בִּצְיָירָא\",0,0],[4,142,20,20,\"לְחוֹד אִילָן דְּתִנְדְּעוּן אֲרוּם לָא אִילָן עֲבִיד פֵּירֵי מֵיכַל הוּא יָתֵיהּ תְּחַבְּלוּן וְתִקְטְעוּן וְתִבְנוּן קַרְקוּמִין עַל קַרְתָּא מַרְדָא דְּעַבְדָא עִמְכוֹן קְרָבָא עַד דְתִכְבְּשׁוּנָהּ\",0,0],[4,142,21,1,\"אֲרוּם יִשְׁתַּכַּח קְטִילָא בְּאַרְעָא דְלָא טָמִיעַ בְּאוּגְרָא בְּאַרְעָא דַּיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן לְמֵרְתָהּ רְמֵי וְלָא צְלוּב בְּקִיסָא בְּחַקְלָא וְלָא טָאִיף עַל אַנְפֵּי מַיָא לָא אִשְׁתְּמוֹדַע מַאן קַטְלֵיהּ\",0,0],[4,142,21,2,\"וְיִפְקוּן מִבֵּי דִינָא רַבָּא תְּרֵין מִן חַכִּימֵיךְ וּתְלַת מִן דַּיָינָךְ וְיִמְשְׁחוּן מֵאַרְבַּע טְרִיגוֹנִין יַת קִרְוַיָא דִּי בְּחַזְרָנוֹת קְטִילָא\",0,0],[4,142,21,3,\"וִיהֵי קַרְתָּא דְקָרִיבָא לְקָטִילָא מִתְחַשְׁדָא נַסְבֵי דִינָא רַבָּא מַפְטְרִין וְיִסְבוּן חַכִּימֵי סָבֵי קַרְתָּא הַהִיא עֶגְלַת בְּרַת תּוֹרִין דְּלָא עֵירוֹבִין בְּרַת שַׁתָּא דְּלָא אִתְפְּלַח בָּהּ וְלָא נַגְדַת בְּנִיר\",0,0],[4,142,21,4,\"וְיִחְתוּן חַכִּימֵי קַרְתָּא הַהוּא יַת עִיגְלְתָא לַחֲקַל בַּיַיר דְּלָא יִתְעֲבֵיד בֵּיהּ פּוּלְחַן אֲרַע וְלָא יִזְדְּרַע וְיִנְקְפוּן תַּמָּן יַת עֶגְלָתָא בְּקוֹפִיץ מִבַּתְרָהָא בִּמְצַע חַקְלָא\",0,0],[4,142,21,5,\"וִיקַרְבוּן כַּהֲנַיָא בְּנֵי לֵוִי אֲרוּם בְּהוֹן אִתְרְעֵי מֵימְרָא דַיְיָ אֱלָהָכוֹן לְשַׁמָשׁוּתֵיהּ וּלְבָרָכָא יַת יִשְרָאֵל בִּשְׁמֵיהּ וְעַל מֵימַר פּוּמְהוֹן יְהִי מִתְדָן כָּל דִּין וְכָל מַכְתַּשׁ צוֹרְעָא לְמִסְגוֹר וּלְמַחְלוֹט\",0,0],[4,142,21,6,\"וְכָל חַכִּימֵי קַרְתָּא הַהוּא דְקָרִיבִין לְקָטִילָה יְשַׁזְגוּן יַת יְדֵיהוֹן עַל עֶגְלְתָא דִנְקִיפָא בְּחַקְלָא\",0,0],[4,142,21,7,\"וִיתִיבוּן וְיֵימְרוּן גְלֵי קֳדָם יְיָ דְלָא אָתָא לִידֵינָן וּפַטְרִינֵיה מַן דְשַׁדָא יַת אִידְמָא הָדֵין וְעֵינָנָא לָא חָמוּן\",0,0],[4,142,21,8,\"כַּהֲנַיָא יֵימְרוּן כַּפֵּר לְעַמָךְ יִשְרָאֵל דִּפְרַקְתָּא יְיָ וְלָא תְשַׁוֵי חוֹבַת אֲדַם זַכְּאַי בְּגוֹ עַמָּךְ יִשְרָאֵל וּגְלֵי מַן קַטְלֵיהּ וְיִתְכַּפֵּר לְהוֹן עַל דְּמָא וּמִן יַד נַפְקִין נְחִיל דְּמוֹרָנִין מִגוֹ פָּרָתָא דְעֶגְלְתָא נַגְדִין וְאָזְלִין עַד אַתְרָא דְקָטוֹלָא תַמָּן וְסַלְקִין עֲלוֹי וְאַחֲדִין בֵּי דִינָא יָתֵיהּ וְדַיְינִין יָתֵיהּ\",0,0],[4,142,21,9,\"וְאַתּוּן בֵּית יִשְרָאֵל תְּפַלוּן מִשְׁדֵי דַם זַכַּאי מִבֵּינֵיכוֹן אֲרוּם תַּעַבְדוּן דְכָשַׁר קֳדָם יְיָ\",0,0],[4,142,21,10,\"כי תצא אֲרוּם תִּפְקוּן לְסִדְרֵי קְרָבָא עַל בַּעֲלֵי דְבָבֵיכוֹן וְיִמְסְרִינוּן יְיָ אֱלָהָכוֹן בְּיֶדְכוֹן וְתִשְׁבֵי שִׁבְיָתָא מִנְהוֹן\",0,0],[4,142,21,11,\"וְתֵיחֲמוּן בִּשְׁבִיתָא אִתָּא שַׁפִּירַת רֵיוֵוי וְתִתְיַדְעוּן בָּהּ וְתִסְבוּנָהּ לְכוֹן לְאִינְתּוּ\",0,0],[4,142,21,12,\"וְתַעֲלִינָהּ לְגוֹ בֵּיתָךְ וּתְסַפַּר יַת מַזְיָיא דְרֵישָׁהּ וְתִיצְמֵי יַת טוּפְרְיָיהָא\",0,0],[4,142,21,13,\"וּתְשַׁנֵי יַת כְּסוּת שִׁבְיָיתָהּ מִינָהּ וְתִטְבְּלִינָהּ וּתְגַיְירִינָהּ בְּבֵיתָךְ וְתִבְכֵּי עַל טַעֲוַות בֵּית אַבָּהּ וְאִמָּהּ וְתִשְׁהֵי תְּלַת יַרְחִין דִּי תֵדַע אִין הִיא מְעַבְּרָא וּמִן בָּתַר כְּדֵין תֵּיעוּל לְוָותָהּ וְתַפְרִין יָתָהּ וְתֶהֱוֵי לָךְ לְאִנְתּוּ\",0,0],[4,142,21,14,\"וִיהֵי אִין לָא תִתְרְעֵי בָּהּ וְתִפְטְרִינָהּ לְבִלְחוֹדָהּ בְּגִיטָא וְזַבָּנָא לָא תְזַבְּנִינָהּ בְּכַסְפָּא לָא תִתְגָר בָּהּ בָּתַר דְּשַׁמַּשְׁתָּ עִמָּהּ\",0,0],[4,142,21,15,\"אֲרוּם תֶּהֶוְיָין לִגְבַר תַּרְתֵּין נְשִׁין חֲדָא רְחִימְתָּא לֵיהּ וַחֲדָא סְנִיתָא לֵיהּ וִילֵדַן לֵיהּ בְּנִין רְחוּמְתָּא וּסְנוּתָא וִיהֵי בִּיר בּוּכְרָא לִסְנֵיתָא\",0,0],[4,142,21,16,\"וִיהֵי בְּיוֹם אַחֲסִינְתֵּיהּ יַת בְּנוֹי יַת נִיכְסִין דִּיהֵי לֵיהּ לֵית לֵיהּ רְשׁוּ לְמִתַּן חוּלַק בְּכוֹרוֹתָא לְבַר רְחוּמְתָּא עַל אַנְפֵּי בִּיר סְנֵיתָא דְהוּא בּוּכְרָא\",0,0],[4,142,21,17,\"אֲרוּם יַת בּוּכְרָא בִּיר סְנֵיתָא יְהוֹדַע לְכוֹלָא דְהוּא בּוּכְרָא לְמִתַּן לֵיהּ תְּרֵין חוּלְקִין בְּכָל מַה דְּמִשְׁתְּכַח גַּבֵּיהּ אֲרוּם הוּא שֵׁירוֹי תוּקְפֵיהּ לֵיהּ חַזְיָא בְּכֵירוּתָא\",0,0],[4,142,21,18,\"אֲרוּם יְהֵי לִגְבַר בִּיר סוּרְהֲבָן וּמְרוֹד דְּלֵיתוֹי מְקַבֵּל לְמֵימָר אָבוֹי וּלְמֵימְרָא דְאִמֵּיהּ וְיִכְסְנוּן יָתֵיהּ וְלָא מְקַבֵּל אוּלְפַן מִנְהוֹן\",0,0],[4,142,21,19,\"וְיֶחְדוּן בֵּיהּ אָבוֹי וְאִמֵּיהּ וְיַפְקוּן יָתֵיהּ לִקֳדָם חַכִּימֵי קַרְתָּא לִתְרַע בֵּי דִינָא דִבְאַתְרֵיהּ\",0,0],[4,142,21,20,\"וְיֵימְרוּן לְחַכִּימֵי קַרְתָּא עַבְרִינָן עַל גְּזֵירַת מֵימְרָא דַיְיָ בְּגִין כֵּן אִתְיְלִיד לָנָא בְּרָנָא דֵין דְּהוּא סוּרְהֲבָן וּמְרוֹד לֵיתוֹי צְיָית לְמֵימְרָנָא גַּרְגְּרָן בְּבִשְרָא וְשֵׁתָאֵי בְּחַמְרָא\",0,0],[4,142,21,21,\"וִיהֵי אִין דְּחִיל וּמְקַבֵּל עֲלוֹי אוּלְפָנָא וּבְעַן לְקַיְמוּתֵיהּ מְקַיְימוּנֵיהּ וְאִין תָּאִיב וּמְרִיד יְאַטְלוּנֵיהּ כָּל אַנְשֵׁי קַרְתֵּיהּ בְּאַבְנַיָא וִימוּת וּתְפַלּוּן עֲבִיד דְּבִישׁ מִבֵּינֵיכוֹן וְכָל יִשְרָאֵל יִשְׁמְעוּן וִידַחֲלוּן\",0,0],[4,142,21,22,\"וַאֲרוּם אִין יְהֵי בִּגְבַר חוֹבַת דִּין קְטוֹל וְיִתְחַיֵּיב אַטְלוּת אַבְנִין וּבָתַר כְּדֵין יִצְלְבוּן יָתֵיהּ עַל קֵיסָא\",0,0],[4,142,21,23,\"לָא תָבִית נִבְלַת גּוּשְׁמֵיהּ עַל קֵיסָא אֲרוּם מִקְבַּר תִּקְבְּרוּנֵיהּ בְּיוֹמָא הַהוּא אֲרוּם קִילוּתָא קֳדָם אֱלָהָא לְמִצְלוֹב גְּבַר אֱלָהֵן חוֹבוֹי גָרְמוּ לֵיהּ וּמִן בִּגְלַל דִּבְדִיוּקְנָא דַיְיָ אִתְעֲבֵד תְּקַבְּרוּנֵיהּ עִם מִטְמוֹעַ שִׁמְשָׁא דְּלָא יְקִילִין בִּרְיָיתָא בֵּיהּ וְלָא תְטוּפוּן בִּנְבֵילְתְּהוֹן דְּחַיָּיבָא יַת אַרְעֲכוֹן דַּיְיָ אֱלָהָכוֹן יָהִיב לְכוֹן אַחֲסָנָא\",0,0],[4,142,22,1,\"לָא תֶחְמוּן יַת תּוֹרָא דַּאֲחוּכוֹן אוֹ יַת אִמְרֵיהּ טַעֲיָין וּתְפַלְגוּן דַּעְתְּכוֹן מִנְהוֹן אָתָבָא תְּתִיבִינוּן לֵיהּ\",0,0],[4,142,22,2,\"וְאִין לָא קְרִיבָא דַעְתָּא דְאָחוּךְ עִמָךְ אוֹ לָא חַכִּימְתֵּיהּ וְתִכְנְשִׁינֵיהּ לְגוֹ בֵיתָךְ וִיהֵי מִתְפַּרְנֵס גַּבָּךְ עַד זְמַן דְּיִתְבַּע אָחוּךְ יָתֵיהּ וּתְתִיבִינֵיהּ לֵיהּ\",0,0],[4,142,22,3,\"וְהֵיכְדֵין תַּעֲבֵיד לְחַמְרֵיהּ וְהֵיכְדֵין תַּעֲבֵיד לִכְסוּתֵיהּ וְהֵיכְדֵין תַּעֲבֵיד לְכָל אֲבֵידְתָּא דְּאָחוּךְ דִּי מִתְבְּדָא מִנֵּיהּ וְתַשְׁכְּחָהּ לֵית לָךְ רְשׁוּ לְכַסָּאָהּ מִינֵיהּ אַכְרִיז עֲלָהּ וּתְהַדְרִינָהּ\",0,0],[4,142,22,4,\"לָא תֶחְמוּן יַת חֲמָרָא דַאֲחוּכוֹן אוֹ תוֹרֵי רְמָאָן בְּאוֹרְחָא וְתִכְבְּשׁוּן עֵינֵיכוֹן מִנְהוֹן מֵיקַם תְּקוּמוּן עִמֵּיהּ\",0,0],[4,142,22,5,\"לָא יִהְיֶה גּוּלְיַין דְּצִיצִית וּתְפִילִין דְּהִינוּן תִּקּוּנֵי גְבַר עַל אִיתָּא וְלָא יְסַפֵּר גְּבַר בֵּי שֵׁיחַיַא וְעִרְיְיתֵיהּ וּבֵי אַנְפּוֹי לְאִיתְחֲמָאָה הֵיךְ נְשָׁא אֲרוּם מְרַחֵק קֳדָם יְיָ אֱלָהָכוֹן הוּא כָּל דְּעָבִיד אִלֵּין\",0,0],[4,142,22,6,\"אֲרוּם אִין אִזְדַמָּן שַׁרְכְּפָא דְּצִיפַּר דְּכֵי קַמָּךְ בְּאִסְרְטָא בְּכָל אִילָן אוֹ עַל אַרְעָא גּוֹזְלִין אוֹ בַּעֲיַין וְאִימָא רְבִיעָא עַל אֶפְרוֹחִין אוֹ עִילוֹי בַּעֲיַין לָא תִסַּב אִימָא מֵעַל בְּנַיָא\",0,0],[4,142,22,7,\"מִפְטַר תִּפְטוֹר יַת אִמָּא וְיַת בְּנַיָא תִסַּב לָךְ מִן בִּגְלַל דְּיוֹטַב לָךְ בְּעַלְמָא הָדֵין וְתוֹרִיךְ יוֹמִין בְּעַלְמָא דְאָתֵי\",0,0],[4,142,22,8,\"אֲרוּם תִּבְנֶה בֵּיתָא חַדְתָּא וְתַעֲבֵיד תֵּיאַק גִּפוּפִין לְאִיגְרָךְ לָא תִגְרְמוּן לְאִסְתַּקְפָא חוֹבַת אֲדַם דִּיקְטוֹל בְּבֵיתָךְ דִּלְמָא יִפּוֹל דֵּין דְּחָמֵי לְמֵיפַל מִנֵּיהּ\",0,0],[4,142,22,9,\"לָא תִזְרְעוּן כַּרְמֵיכוֹן עֵירוּבִין דִּלְמָא תִתְחַיֵּיב יַקִידְתָּא דִּימְעַת זַרְעָא דְתִזְרְעוּן וַעֲלָלַת כַּרְמָא\",0,0],[4,142,22,10,\"לָא תֶהֱווֹן רַדְיַין בְּתוֹרָא וּבְחַמְרָא וּבְכָל בִּרְיָיתָא בִּתְרֵין זְיָנִין קְטִירִין כַּחֲדָא\",0,0],[4,142,22,11,\"לָא תֶהֱווֹן לָבְשׁוּן וּמִשְׁתַּחֲנִין בִּכְסוּ דְּשִׁיעַ וְעָזֵיל וְנֵיז עֲמַר וְכִיתָּן מְעַרְבִין כַּחֲדָא\",0,0],[4,142,22,12,\"בְּרַם לְאִצְטוֹלֵי כִיתָּן חוּטֵי צִיצְיַית מִן עֲמַר תְּהוֹן מַרְשַׁן לְמֶעֱבַד לְכוֹן עַל אַרְבַּע כַּנְפֵי גוּלְיַיתְכוֹן דְּתִתְעַטְפוּן בָּהּ בִּימָמָא\",0,0],[4,142,22,13,\"אֲרוּם יִסַּב אֵינַשׁ אִיתָא בְּתוּלְתָּא וְיֵיעוֹל עֲלָהּ וּמִבָּתַר כְּדֵין יִסְנִינָהּ\",0,0],[4,142,22,14,\"וִישַׁוֵּי לָהּ עֲרַד דְּמִילִין וְיִפּוֹק עֲלָהּ טִיב בִּישׁ וְיֵימַר יַת אִתְּתָא הֲדָא נְסִיבִית וְשַׁמָּשִׁית עִמָּהּ וְלָא אַשְׁכָּחִית לָהּ סְהִידַווֹן\",0,0],[4,142,22,15,\"וְיִסְבוּן אֲבוּהָא דְעוּלֵימְתָּא וְאִמָּהּ רְשׁוּ מִבֵּי דִינָא וְיִפְקוּן יַת שׁוֹשִׁיפָא בַּהֲדֵי סְהִידַווֹן דְּעוּלֵימְתָּא לְוַת חַכִּימֵי קַרְתָּא לִתְרַע בֵּי דִינָא\",0,0],[4,142,22,16,\"וְיֵימַר אֲבוּהָא דְעוּלֵימְתָּא לְחַכִּימַיָא יַת בְּרַתִּי קַדֵּישִׁית לְגַבְרָא הָדֵין לְאִנְתּוּ וּמִן בָּתַר דְּשַׁמֵּשׁ עִמָּהּ סַנָא לָהּ\",0,0],[4,142,22,17,\"וְהָא הוּא שַׁוֵי עֲרַד דְּמִילִין לְמֵימָר לָא אַשְׁכָּחִית לִבְרַתָּךְ סְהִידַווֹן וְאִילֵין סְהִידוֹי בְּרַתִּי וְיִפְרְסוּן שׁוֹשִׁיפָא קֳדָם חַכִּימֵי קַרְתָּא\",0,0],[4,142,22,18,\"וְיִסְבוּן חַכִּימֵי קַרְתָּא הַהוּא יַת גַּבְרָא וְיִלְקוּן יָתֵיהּ\",0,0],[4,142,22,19,\"וְיִזְמוּן יָתֵיהּ מְאָה סַלְעִין דִּכְסַף וְיִתְּנוּן לְאָבוּהָא דְעוּלֵימְתָּא אֲרוּם אַפִּיק טִיב בִּישׁ עַל בְּתוּלְתָּא כַּשְׁרָא דְיִשְרָאֵל וְלֵיהּ תְּהֵי לְאִנְתּוּ לֵית לֵיהּ רְשׁוּ לְמִפְטְרָהּ כָּל יוֹמוֹי\",0,0],[4,142,22,20,\"וְאִין קְשׁוֹט הֲוָה פִּתְגָמָא הָדֵין לָא אִישְׁתַּכָּחוּ סְהִידַווֹן לְעוּלֵמְתָּא\",0,0],[4,142,22,21,\"וְיִפְקוּן יַת עוּלֵימְתָּא לִתְרַע בֵּית אָבוּהָא וִיאַטְלוּנָהּ אִינְשֵׁי קַרְתָּא בְּאַבְנַיָא וְתֵימוּת אֲרוּם עָבְדַת קְלָנָא בְּיִשְרָאֵל לְמַפְקָא שׁוּם בִּישׁ דִּזְנוּ עַל בֵּית אָבוּהָא וּתְפַלּוּן עֲבִיד דְּבִישׁ מִבֵּינֵיכוֹן\",0,0],[4,142,22,22,\"אֲרוּם אִין מִשְׁתַּכַּח גְּבַר מְשַׁמֵּשׁ עִם אִתְּתָא אִתַּת גְּבַר חוֹרַן וְיִתְקַטְלוּן אוּף תַּרְוֵיהוֹן גַּבְרָא דִמְשַׁמֵּשׁ עִם אִתְּתָא וְאִתְּתָא וַאֲפִילוּ אִין מְעַבְּרָא לָא תִשְׁהוֹנֵיהּ עַד דְּתֵילִיד אֱלָהֵן בֵּי הִיא שַׁעְתָּא תִּקְטְלוּנוּן בְּשֵׁינוּקָא דְסוּדְרָא וּתְפַלּוּן עֲבִיד דְּבִישׁ מִיִּשְרָאֵל\",0,0],[4,142,22,23,\"אֲרוּם תֶּהֱוֵי עוּלֵימְתָּא בְתוּלְתָּא מִיקַדְשָׁא לִגְבַר וְיִשְׁכְּחִינָהּ גְּבַר חוֹרַן בְּקַרְתָּא וִישַׁמֵּשׁ עִמָּהּ\",0,0],[4,142,22,24,\"וְתַפְקוּן יַת תְּרֵיהוֹן לִתְרַע בֵּי דִינָא דִּבְקַרְתָּא הַהִיא וּתְאַטְלוּן יַתְהוֹן בְּאַבְנַיָא וִימוּתוּן יַת עוּלֵימְתָּא מִן בִּגְלַל דְּלָא פָגְנַת בְּקַרְתָּא וְיַת גַּבְרָא מִן בִּגְלַל דְּשַׁמֵּשׁ עִם אִתַּת חַבְרֵיהּ וּתְפַלּוּן עֲבִיד דְּבִישׁ מִבֵּינֵיכוֹן\",0,0],[4,142,22,25,\"וְאִין בְּבָרָא יַשְׁכַּח גַּבְרָא יַת עוּלֵימְתָּא דְמִיקַדְשָׁא וְיִתְקַף בָּהּ גַּבְרָא וִישַׁמֵּשׁ עִמָּהּ וְיִתְקְטֵיל גַּבְרָא דְּשַׁמֵּשׁ עִמָּהּ בִּלְחוֹדוֹי\",0,0],[4,142,22,26,\"וּלְעוּלֵימְתָּא לָא תַעַבְדוּן מִדָּעַם בִּישׁ לֵית לְעוּלֵימְתָּא דִין קְטוֹל אֱלָהֵן גַּבְרָא יִפְטְרִינָהּ מִנֵּיהּ בְּגִיטָא אֲרוּם הֵיכְמָא דְיִכְמוֹן גְּבַר עַל חַבְרֵיהּ וְיִקְטְלִינֵיהּ נְפָשׁ הֵיכְדֵין פִּתְגָמָא הָדֵין\",0,0],[4,142,22,27,\"אֲרוּם בְּאַנְפֵּי בָּרָא אַשְׁכְּחָהּ פָּגְנַת עוּלֵּימְתָּא דְמִיקַדְשָׁא וְלָא אִזְדַמֵּן פַּרִיק לָהּ\",0,0],[4,142,22,28,\"אֲרוּם יַשְׁכַּח גְּבַר עוּלֵימְתָּא בְּתוּלְתָּא דְלָא מִיקַדְשָׁא וְיֵחוּד בָּהּ וּמְשַׁמֵּשׁ עִמָּהּ וּמִשְׁתַּכְּחִין\",0,0],[4,142,22,29,\"וְיִתֵּן גַּבְרָא דְשַׁמֵּשׁ עִמָּהּ לְאָבוּהָא דְעוּלֵּימְתָּא דְמֵי בַּהֲתָהּ חַמְשִׁין סַלְעִין דִּכְסַף וְלֵיהּ תְּהֵי לְאִינְתּוּ חוֹלַף דְּעַנְיָיהּ לֵית לֵיהּ רְשׁוּ לְמִפְטְרָהּ בְּגִיטָא כָּל יוֹמוֹי\",0,0],[4,142,23,1,\"לָא יִסַּב גְּבַר יַת אִתְּתָא דְּאָנִיס אוֹ דְשַׁרְגִיג אָבוֹי וְכָל דְּכֵן אִתַּת אָבוֹי וְלָא יְגַלֵי כַנְפָא דְגַלֵּי אָבוֹי\",0,0],[4,142,23,2,\"לָא יִדְכֵּי דִמְסָרֵיס וּדְפָסִיק גִידָא לְמִיסַב אִיתָא מִקְהַל עַמָּא דַיְיָ\",0,0],[4,142,23,3,\"לָא יִדְכֵּי דְמִתְיְלִיד מִן זְנוּ דְבֵיהּ מוּמָא בִּישָׁא דְאִיתְיְהִיב בְּעַמְמַיָא חוֹלוֹנָאֵי לְמֵיסַב אִיתָא כַּשְׁרָא מִקְהַל עַמָּא דַיְיָ אוֹף דּוֹר עֲשִירָאֵי לָא יִדְכֵּי לֵיהּ לְמֵיעַל בִּקְהָלָא דַיְיָ\",0,0],[4,142,23,4,\"לָא יִדְכּוּן דְּכוּרֵי עַמּוֹנָאֵי וּמוֹאֲבָאֵי לְמֵיסַב אִיתָא מִקְהַל עַמָּא דַיְיָ בְּרַם דַּר עֲשִירָאֵי לָא יִדְכֵּי לְמֵיסַב אִיתָא מִקְהַל עַמָּא דַיְיָ עַד עָלְמָא\",0,0],[4,142,23,5,\"עַל עֵיסַק דְּלָא זְמִינוּ לְכוֹן בְּלַחֲמָא וּבְמוֹי בְּאָרְחָא בְּמִפַּקְכוֹן מִמִּצְרַיִם וּדְאוֹגַר לְכוֹן יַת בִּלְעָם בַּר בְּעוֹר מִן פְּתוֹר חֶלְמַיָא דְּמִתְבַּנְיָא בְּאַרַע אֲרַם דְּעַל פְּרָת לְמֵילַט יַתְכוֹן\",0,0],[4,142,23,6,\"וְלָא צָבָא יְיָ אֱלָהָכוֹן לְקַבָּלָא מִן בִּלְעָם וְהָפַךְ יְיָ אֱלָהָכוֹן בְּפוּמֵיהּ מְטוֹלְכוֹן יַת לְוָוטִין לְבִרְכַן אֲרוּם רָחֵמִינְכוֹן יְיָ אֱלָהָכוֹן\",0,0],[4,142,23,7,\"לָא תִתְבְּעוּן שְׁלָמְהוֹן וְטָבְהוֹן כָּל יוֹמֵיכוֹן דַּאֲפִלּוּ מִתְגַיְירִין סְנָא נְטִיר בְּלִבְּהוֹן עַד עַלְמָא\",0,0],[4,142,23,8,\"לָא תְרַחֲקוּן אֱדוֹמָאָה דְאָתֵי לְאִתְגַיְירָא אֲרוּם אֲחוּכוֹן הוּא לָא תְרַחֲקִין מִצְרָאָה דְּאָתֵי לְאִתְגַיְירָא אֲרוּם דַּיְירוּן הֲוֵיתוּן בְּאַרְעֲהוֹן\",0,0],[4,142,23,9,\"בְּנִין דְּמִתְיַלְדִין לְהוֹן דַּר תְּלִיתָאָה יִדְכּוּן לְמִסְבָּא מֵעַם קְהָלָה דַיְיָ\",0,0],[4,142,23,10,\"אֲרוּם תִּפְקוֹן מַשִׁירְוַיָן עַל בַּעֲלֵי דְבָבֵיכוֹן וְתִסְתַּמְּרוּן מִכָּל פִּתְגָם דְּבִישׁ מִפּוּלְחָנָא נוּכְרַיָא וְגִילוּי עֶרְיְיתָא וְשַׁדְיוּת אֲדַם זַכַּאי\",0,0],[4,142,23,11,\"אֲרוּם יְהֵי בָךְ גְּבַר דְּלָא יְהֵי דְכֵי מִקִּרְיוּת הִרְהוּר לֵילְיָא וְיִפּוֹק לְמִבָּרָא לְמַשְׁרִיתָא לָא יֵיעוֹל לְמִצּוּעַ מַשְׁרִיתָא\",0,0],[4,142,23,12,\"וִיהֵי לְעִידוֹנֵי רַמְשָׁא יַסְחֵי בְּמוֹי וּכְמִטְמוֹעַ שִׁמְשָׁא יֵיעוֹל לְגוֹ מַשְׁרִיתָא\",0,0],[4,142,23,13,\"וְאָתַר מְזַמֵּן יֶהֱוֵי לָךְ מִבָּרָא לְמַשְׁרִיתָא וּתְשׁוּד תַּמָן מוֹי דְרִגְלָךְ\",0,0],[4,142,23,14,\"וְסִיכָא תֶהֱוֵי קְבִיעָא לְכוֹן עַל מָנֵי זֵינֵיכוֹן אֲתַר דְּתִסְרוּן סְיָיפֵיכוֹן וִיהֵי בְּמִתְבָךְ לְבָרָא וְתֶהֱוֵי חָפַר בָּהּ וְתִפְנֵי תַמָּן וּתְתוּב וּתְכַס יַת רַעֲיָיךְ\",0,0],[4,142,23,15,\"אֲרוּם יְיָ אֱלָהָכוֹן שְׁכִינְתֵּיהּ מְהַלְכָא בִמְצַע מַשִּׁירְיַתְכוֹן לְשֵׁיזָבוּתְכוֹן וּלְמִימְסַר סַנְאֵיכוֹן בִּידֵיכוֹן בְּגִין כֵּן תְּהֵי אֲתַר מַשִּׁרְיַתְכוֹן קַדִּישָׁא וְלָא יֶחֱמֵי בְכוֹן קְלָנָא דְּמִדַּעַם דְּלָא יְסַלֵּק שְׁכִינְתֵּיהּ מִבֵּינֵיכוֹן\",0,0],[4,142,23,16,\"לָא תִימְסוֹר נוּכְרָאָה בִּידָא פַּלְחֵי טַעֲוָותֵי דְּאִישְׁתְּזִיב גַּבֵּיכוֹן לְמֶהֱוֵי תְּחוֹת טְלַל שְׁכִינְתִּי דְיִמְטוֹל הֵיכְנָא עֲרַק מִן פּוּלְחַן טָעוּתֵיהּ\",0,0],[4,142,23,17,\"עִמְכוֹן יָתֵיב וְיִנְטוֹר מִצְוָתָא בֵּינֵיכוֹן אַלִּיפוּ יָתֵיהּ אוֹרַיְיתָא קָבְעוּ לֵיהּ מֶדְרָשָׁא בְּאַתְרָא דְצָבֵי בַּחֲדָא מִן קִרְיֵיכוֹן אִתְעַסְקוּ עִמֵּיהּ בִּדְיוֹטִיב לֵיהּ לָא תוֹנִינֵיהּ בְּמִלִּין\",0,0],[4,142,23,18,\"לָא תִפְסוּן בְּנָתֵיכוֹן לְמֶהֱוֵי נְפָקַת בָּרָא וְלָא יִתְפַּס גַּבְרָא בַּר יִשְרָאֵל יַת גַּרְמֵיהּ בִּזְנוּ\",0,0],[4,142,23,19,\"לָא תַעֲלוּן אֲגַר מוֹהֲבוֹת מַטְעִיתָא וּפֵירוּג דְּכֶלֶב לְקַרְבָא בְּבֵי מוּקְדְּשָׁא דַיְיָ אֱלָהָכוֹן לְכָל נִדְרָא כָּל דְּכֵן לִשְׁאַר קוּרְבָּנַיָא אֲרוּם מְרַחֵק קֳדָם יְיָ אֱלָהָכוֹן אוּף תַּרְוֵיהוֹן\",0,0],[4,142,23,20,\"לָא תַרְבֵּי מִדִּילָךְ לְחַבְרָךְ עַל מִזְפּוֹ דְּאוֹזְפָךְ לָא עַל מִזְפּוֹ דְּכָסִיף וּמִזְפּוֹ דְּמֵיכְלָא וְלָא עַל מִזְפּוֹ דְּכָל מִדַּעַם דְּמִתְרַבֵּי\",0,0],[4,142,23,21,\"לְבַר עַמְמִין תֵּיזוּף מִנֵּיהּ בְּרִיבִּיתָא וּלְאָחוּךְ לָא תֵיזוּף בְּרִיבִּיתָא מִן בִּגְלַל דִּיבָרְכִינָךְ יְיָ אֱלָהָךְ בְּכָל אוֹשָׁטוּת יְדָךְ עַל אַרְעָא דְאַנְתְּ עָלֵיל לְתַמָּן לְמֵירְתָהּ\",0,0],[4,142,23,22,\"אֲרוּם תִּידְרוּן נִדְרָא קֳדָם יְיָ אֱלָהָכוֹן לָא תוֹחֲרוּן לְשַׁלְמוּתֵיהּ תְּלַת חַגִּין אֲרוּם מִתְבַּע יִתְבְּעִינֵיהּ יְיָ אֱלָהָכוֹן בְּקוּרְבָּנָא לָא יְהֵי חוֹב וּפְסוּלָא דִבְהַפְתִּיק מָרֵי עַלְמָא קָאִי וְלָא יְהֵי בָךְ חוֹבַת עִכּוּב נִדְרָא\",0,0],[4,142,23,23,\"וַאֲרוּם תִּתְמַנְעוּן מִלְּמֵידַר לָא יְהֵי בְכוֹן חוֹבָא\",0,0],[4,142,23,24,\"מוֹמָתָא דְתִפּוֹק מִן שִפְוַותְכוֹן תְּקִימוּן מִצְוָותָא דְכַשְׁרִין לְאִתְעוֹבָדָא תַּעַבְדוּן וּדְלָא כַשְׁרִין לְאִתְעוֹבָדָא לָא תַעַבְדוּן וְהֵיכְמָא דִנְדַרְתּוּן תְּשַׁלְּמוּן חַטָּאתָא וְאַשְׁמָא עֲלַוָּון וְנִכְסְתָא קוּדְשִׁין תְּקַרְבוּן קֳדָם יְיָ אֱלָהָכוֹן וְנִיכְסְתָא תֵּיהוֹן וּנְבִזְבְּיַית בֵּית מוּקְדְּשָׁא דְמַלֵּילְתּוּן תִּתְּנוּן וּלְעַנְיֵי צִדְקָתָא מַה דְּאָמַרְתּוּן בְּפוּמְכוֹן\",0,0],[4,142,23,25,\"אֲרוּם תֵּיעוּל לְמֵיסַב אַגְרָא כְּפוֹעֵל בְּכַרְמָא דְחַבְרָךְ וְתֵיכוּל כְּרַעֲוַות נַפְשָׁךְ עַד דְּתִסְבַּע וּלְוַות צַנָךְ לָא תִתֵּן\",0,0],[4,142,23,26,\"אֲרוּם תֵּיעוּלוּ לְמֵיסַב אַגְרָא כְּפָעֵל בְּקַמְתָא דְחַבְרָךְ וְתִקְטוֹף פְּרוּכְיַין בִּידָךְ וּמַגְלָא לָא תְרִים עַל קַמְתָא דְחַבְרָךְ\",0,0],[4,142,24,1,\"אֲרוּם יִסַב גְּבַר אִיתָא וְיֵיעוּל עֲלָהּ וִיהֵי אִין לָא הַשְׁכָּחַת רַחֲמִין בְּעֵינוֹי אֲרוּם אַשְׁכַּח בָּהּ עֲבֵירַת פִּתְגָם וְיִכְתּוֹב לָהּ סֵפֶר תִּירוּכִין קֳדָם בֵּי דִינָא וְיִתֵּן בִּרְשׁוּתָהּ וְיִטַיֵּיל יָתָהּ מִבֵּיתֵיהּ\",0,0],[4,142,24,2,\"וּנְפָקַת מִבַּיְיתֵיהּ וּתְהַךְ וּתְהֵי לִגְבַר אוֹחֲרָן\",0,0],[4,142,24,3,\"וְאַכְרִיזוּ עֲלָהּ מִן שְׁמַיָא דְיַסְנִינָהּ גַּבְרָא בַּתְרָאָה וְיִכְתּוֹב לָהּ סֵפֶר תִּירוּכִין וְיִתֵּן בִּרְשׁוּתָהּ וִיטַיֵּיל לָהּ מִבַּיְיתֵיהּ אוֹ אַכְרִיזוּ עֲלוֹי וְיֵמוּת גַּבְרָא בַּתְרָאָה דְנַסְבָהּ לֵיהּ לְאִנְתּוּ\",0,0],[4,142,24,4,\"לֵית לֵיהּ רְשׁוּת לְבַעֲלָהּ קַמָּאָה דְפַטְרָהּ מִן שֵׁירוּיָא לִמְתוֹב לְמִסְבָּהּ לְמֶהֱוֵי לֵיהּ לְאִנְתּוּ מִן בָּתַר דְּאִיסְתְּאָבַת אֲרוּם מְרַחֲקָא הִיא קֳדָם יְיָ וְלָא מְרַחֲקִין בְּנָהָא דְתֵלִיד מִנֵּיהּ וְלָא תְחַיֵּיב חוֹבַת מוֹתָנָא יַת אַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן אַחְסָנָא\",0,0],[4,142,24,5,\"אֲרוּם יִסַּב גְּבַר אִיתָא חַדְתָּא בְּתוּלְתָּא לָא יִפּוֹק בְּחֵילָא דְּלָא יֶאֱרַע עֲלוֹי כָּל מִדַּעַם בִּישׁ פָּנֵי יְהֵי בְּבֵיתֵיהּ שַׁתָּא חֲדָא וְיִחְדֵי עִם אִנְתְּתֵיהּ דְּנָסִיב\",0,0],[4,142,24,6,\"לָא יְמַשְׁכַּן גְּבַר רֵיחַיָא וְרִיכְבָא אֲרוּם צוֹרְכֵי דִבְהוֹן מִתְעֲבֵיד מָזוֹן לְכָל נַפְשָׁא הוּא מְמַשְׁכַּן וְלָא יֶהֱוֵי גְבַר אֲסַר חַתְנִין וְכַלִּין בְּחַרְשִׁין אֲרוּם נַפְשָׁא דְעָתִיד לְמֵיפַק מִנְהוֹן הוּא מְחַבֵּל\",0,0],[4,142,24,7,\"אֲרוּם יִשְׁתַּכַּח בַּר נַשׁ גְּנִיב נְפָשׁ מֵאָחוֹי מִבְּנֵי יִשְרָאֵל וְיַעֲבֵיד בֵּיהּ פְּרַקְמַטְיָא וְיִזְבְּנִינֵיהּ וְיִתְקְטֵיל גַּבְרָא הַהוּא בְּשִׁינוּקָא דְסוֹדְרָא וּתְפַלֵּי עֲבִיד דְּבִישׁ מִבֵּינָךְ\",0,0],[4,142,24,8,\"אִסְתַּמָּרוּ דְלָא לְמִקְטוֹעַ בִּישְרָא דְבֵיהּ בַּהֲקֵי אֱלָהֵן לְמִנְטוֹר לַחֲדָא לְמֶעֱבַד בֵּינֵי מַכְתַּשׁ צוּרְעָתָא לְמַכְתַּשׁ נוּתְקָא בֵּינֵי מְסָאָבָא לְבֵינֵי דַכְיָא הֵי כְּכָל מַה דְּיַלְפוּן יַתְכוֹן כַּהֲנַיָא דְּמִילְשֵׁבַט לֵוִי הֵיכְמָא דְפַקֵידְתִּינוּן תִּנְטְרוּן לְמֶעֱבַד\",0,0],[4,142,24,9,\"הֲווֹ זְהִירִין דְּלָא לְמֵחֲשַׁד חַד בְּחַבְרֵיהּ דְּלָא יִלְקֵי הֲווֹ דְּכִירִין מַה דְּעָבַד יְיָ אֱלָהָכוֹן לְמִרְיָם דְּחָשְׁדַּת לְמשֶׁה בְּמִלְתָא דְלָא הֲוַת בֵּיהּ וְלָקַת בְּצוֹרְעָא וְאִתְעַכְּבַת בְּאָרְחָא בְּמִפְקְכוֹן מִמִּצְרָיִם\",0,0],[4,142,24,10,\"אֲרוּם תּוֹזְפוּן בְּחַבְרֵיכוֹן מִיזְפוּ דְמִדַּעַם לָא תֵיעוּל לְבֵיתֵיהּ לְמַשְׁכּוֹנֵי מַשְׁכּוֹנֵיהּ\",0,0],[4,142,24,11,\"בְּשׁוּקָא תֵּיקוּם וְגַבְרָא דְאַנְתְּ מוֹזִיף בֵּיהּ יָפִיק לָךְ יַת מַשְׁכּוֹנָא לְשׁוּקָא\",0,0],[4,142,24,12,\"וְאִין גְּבַר מִסְכֵּין הוּא לָא תָבִית וּמַשְׁכּוֹנֵיהּ גַּבָּךְ\",0,0],[4,142,24,13,\"אוֹתָבָא תְתִיב לֵיהּ יַת מַשְׁכּוֹנָא כַּד מִטְמַע שִׁימְשָׁא וְיִגְנֵי בִּגְלוֹפְקְרֵיהּ וִיבָרְכִינָךְ וְלָךְ תְּהֵי זְכוּ דְּיַסְהִיד עֲלָךְ שִׁימְשָׁא קֳדָם יְיָ אֱלָהָךְ\",0,0],[4,142,24,14,\"לָא תִטְלוֹמוּן חַבְרֵיכוֹן וְלָא תְשַׁנּוּן סוֹטְרֵיהּ דְּאַגְרָא עַנְיָא וּמִסְכְּנָא מִן אֲחֵיכוֹן אוֹ מִן גִּיּוֹרֵיכוֹן דְּמִתְגַּיְירִין בְּאַרְעֲכוֹן בְּקִירְוֵיכוֹן\",0,0],[4,142,24,15,\"בְּיוֹמֵיהּ תִּפְרַע לֵיהּ סוֹטְרֵיהּ וְלָא תִטְמוֹעַ עֲלוֹי שִׁמְשָׁא מְטוֹל דְּעַנְיָא הוּא וּמְטוּלְתֵּיהּ הוּא סָבַר לְקַיְימָא יַת נַפְשֵׁיהּ וְלָא יִקְבּוֹל עֲלָךְ קֳדָם יְיָ וִיהֵי בָּךְ חוֹבָא\",0,0],[4,142,24,16,\"לָא יִתְקַטְלוּן אַבְהָן לָא בְּסַהֲדוּת וְלָא בְחוֹבֵי בְּנִין וּבְנִין לָא יִתְקַטְלוּן לָא בְסַהֲדוּת וְלָא בְחוֹבֵי אַבְהָן אִישׁ בְּחוֹבֵי עַל סַהֲדִין כְּשֵׁירִין יִתְקַטְלוּן\",0,0],[4,142,24,17,\"לָא תַצְלֵי דִין גִּיּוֹרָא וְיַתְמָא וְאַרְמְלָא וְלָא יְמַשְׁכַּן חַד מִנְכוֹן כְּסוּ דְאַרְמַלְתָּא דְלָא יְקוּמוּן שִׁיבְבוֹן בִּישִׁין וְיִפְקוּן עֲלָךְ טִיב בִּישׁ כַּד תְּהַדְרוּן מַשְׁכּוֹנָא לָהּ\",0,0],[4,142,24,18,\"וְתֶהֱווּן דְּכִירִין אֲרוּם מְשַׁעַבְּדִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרַיִם וּפְרַק יַתְכוֹן מֵימְרָא דַיְיָ אֱלָהָכוֹן מִתַּמָּן בְּגִין כֵּן אֲנָא מְפַקֵּיד לְכוֹן לְמֶעֱבַד יַת פִּתְגָמָא הָדֵין\",0,0],[4,142,24,19,\"אֲרוּם תְּחַצְדוּן חַצְדֵיכוֹן בְּחַקְלֵיכוֹן וְתִתְנְשׁוּן עוּמְרָא בְּחַקְלָא לָא תְתוּבוּן לְמִסְבֵיהּ לְגִיּוֹרָא לְיַתְמָא וּלְאַרְמַלְתָּא יְהֵי מְטוּל דִּי יְבָרְכֵכוּן מֵימְרָא דַיְיָ אֱלָהָכוֹן בְּכָל עוֹבָדֵי יְדֵיכוֹן\",0,0],[4,142,24,20,\"אֲרוּם תִּשְׁבְּטוּן זֵיתֵיכוֹן לָא תְבַקְרִינוּן מִן בַּתְרֵיכוֹן לְגִיּוֹרָא לְיַתְמָא וּלְאַרְמְלָא יֶהֱווֹן\",0,0],[4,142,24,21,\"אֲרוּם תַּקְפוּן כַּרְמֵיכוֹן לָא תְעָלֵיל מִן בַּתְרֵיכוֹן לְגִיּוֹרָא לְיַתְמָא וּלְאַרְמְלָא יֶהֱווֹן\",0,0],[4,142,24,22,\"וְתֶהֱווּן דְּכִירִין אֲרוּם מְשַׁעְבְּדִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרַיִם בְּגִין כֵּן אֲנָא מְפַקֵּיד לְכוֹן לְמֶעֱבַד יַת פִּתְגָמָא הָדֵין\",0,0],[4,142,25,1,\"אֲרוּם יְהֵי תִיגְרָא בֵּין תְּרֵין גּוּבְרַיָא וְיִתְקַרְבוּן לְוַת דִּינָא וִידוֹנוּן יַתְהוֹן וְיִכְרְעוּן לִזְכוּתָא יַת זַכָּאָה וּלְחוֹבָא יַת חַיָּיבָא\",0,0],[4,142,25,2,\"וִיהֵי אִין מִתְחַיֵּיב לְמִלְקֵי חַיָּיבָא וְיִרְבְּעִינֵיהּ דַּיָינָא וְיַלְקִינֵיהּ קֳדָמוֹי כְּמֵיסַת חִיּוּבֵיהּ בְּדִינֵיהּ\",0,0],[4,142,25,3,\"אַרְבְּעִין יַצְלִיף וְחָסִיר חַד יַלְקִינֵיהּ לָא יַשְׁלִים דִּלְמָא יוֹסִיף לְמִלְקֵיהּ עַל תְּלָתִין וְתֵשַׁע אִלֵּין מַלְקוּת יַתִּיר וְיִסְתַּכֵּן וְלָא יִתְבַּזֵי אָחוּךְ וְאַנְתְּ חָמֵי לֵיהּ\",0,0],[4,142,25,4,\"לָא תְזַמְמוּן פּוּם תּוֹרָא בְּשַׁעַת דָּרְכֵיהּ בְּרַם יְבִימְתָּא דְאִיתְרְעַת קַמֵּיהּ לָקֵי שִׁיחְנָא וּדְלֵי חָמֵי לָא תִזְמָמוּנָהּ לֵיהּ\",0,0],[4,142,25,5,\"כַּד דַּיְירִין בְּעַלְמָא הָדֵין שָׁעָה חֲדָא אַחִין מִן אַבָּא דִּמְיַחֲדִין בְּאַחְסַנְתָּא לָא תֶהֱוֵי אִתַּת שְׁכִיבָא הֶפְקֵרָא בְּשׁוּקָא לִגְבַר חִילוֹנָאֵי יְבָמָהּ יֵיעוּל עֲלָהּ וְיִסְבִּינָהּ לֵיהּ לְאִינְתּוּ וְיַבֵּם יָתָהּ\",0,0],[4,142,25,6,\"וִיהֵי בּוּכְרָא דְתוֹלִיד יְקוּם בְּאַחְסַנְתָּא עַל שׁוּם אָחוֹי שְׁכִיבָא וְלָא יִתְמְחֵי שְׁמֵיהּ מִיִּשְרָאֵל\",0,0],[4,142,25,7,\"וְאִם לָא יִצְבֵי גַבְרָא לְמֵיסַב יַת יְבִימְתֵּיהּ וְתִיסַק יְבִימְתֵּיהּ לִתְרַע בֵּי דִינָא קֳדָם חַמְשָׁא חַכִּימִין וִיהוֹן תְּלָתָא לְדַיְינִין וּתְרֵין לְסַהֲדִין וְתֵימַר בְּלִישַׁן בֵּית קוּדְשָׁא קֳדָמֵיהוֹן מְסָרֵב יְבָמִי לְמִקְמָא לְאָחוֹי שְׁמָא בְּיִשְרָאֵל לָא צָבֵי לְיַבָּמוּתִי\",0,0],[4,142,25,8,\"וְיִקְרוֹן לֵיהּ חַכִּימֵי קַרְתֵּיהּ וִימַלְלוּן עִמֵּיהּ מִילְכָּא קְשִׁיטָא וִיקוּם בְּבֵי דִינָא וְיֵימַר בְּלִישָׁן בֵּית קוּדְשָׁא לָא רָעֵינָא לְמִיסְבָּהּ\",0,0],[4,142,25,9,\"וְתִתְקָרֵיב יְבִימְתֵּיהּ לְוָתֵיהּ לִקֳדָם חַכִּימַיָא וִיהֵי נָעֵיל בְּרִיגְלֵיהּ דִּיבִימָהּ סַנְדְּלָא דְּלֵיהּ עֲקֵיבָא דְחַיֵּיט בִּשְׁנָצֵי וּבְפוּם סַנְדְּלָא שְׁנָצֵי קְטוּרִין וִיחַכֵּם רִיגְלֵיהּ בְּאַרְעָא וּתְקִים אִינְתְּתָא וְתִשְׁרֵי שְׁנָצֵי וְתִשְׁלוֹף סַנְדְּלֵיהּ מֵעִלַּוֵי רִיגְלֵיהּ וּמִן בָּתַר כְּדֵין תֵּירוֹק קֳדָמוֹי רוֹקָא נְפִישָׁא דְמִתְחַמֵּי לְחַכִּימַיָא וּתְתִיב וְתֵימַר כְּדֵין חָמֵי לְאִתְעוֹבָדָא לְגַבְרָא דְּלָא יִבְנֶה יַת בֵּיתָא דְאָחוֹי\",0,0],[4,142,25,10,\"וְכָל דְּקַיְימִין תַּמָּן יִכְרְזוּן עֲלוֹי וְיִקְרוּן שְׁמֵיהּ בְּיִשְרָאֵל בֵּי שְׁלִיף סַנְדְּלָא\",0,0],[4,142,25,11,\"אֲרוּם מִתְגַּרְיָין בְּנֵי אֱנָשָׁא כַּחֲדָא גְּבַר וְחַבְרֵיהּ וְתִתְקָרֵב אִתַּת חַד מִנְהוֹן לְשֵׁיזָבָא יַת בַּעֲלָהּ מִיַּד מְחָהִי וְתוֹשִׁיט יְדָהּ וְתִתְקֵיף בְּבֵית בְּהַתְתֵיהּ\",0,0],[4,142,25,12,\"וְתִקְטְעוּן יַת פִּיסַת יְדָהּ לָא תְחוּסַן עֵינֵיכוֹן\",0,0],[4,142,25,13,\"לָא יֶהֱוֵי לְכוֹן בְּנַרְתֵּיקֵיכוֹן מַתְקְלִין דִּנְכִיל מַתְקְלִין רַבְרְבִין לְמֶהֱוֵי זַבִּין בְּהוֹן וּמַתְקְלִין זְעִירִין לְמֶהֱוֵי מְזַבִּין בְּהוֹן\",0,0],[4,142,25,14,\"לָא יֶהֱוֵי לְכוֹן בְּבָתֵּיכוֹן מְכִילַן דִּנְכִיל מְכִילַן רַבְרְבִין לְמֶהֱוֵי זַבִּין בְּהוֹן וּמְכִילַן זְעִירִין לְמֶהֱוֵי מְזַבִּין בְּהוֹן\",0,0],[4,142,25,15,\"מַתְקְלִין שַׁלְמִין וּמִסְחֲאָתָא דִקְשׁוֹט יֶהֱוֵי לְכוֹן מְכִילַן שַׁלְמִין וּקְסָטִין דִּקְשׁוֹט יֶהֱוֵי לְכוֹן מִן בִּגְלַל דְּיִסְגוּן יוֹמֵיכוֹן עַל אַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן\",0,0],[4,142,25,16,\"אֲרוּם מְרַחֵק קֳדָם יְיָ אֱלָהָכוֹן כָּל דְּעָבֵיד אִלֵּין נִיכְלַיָא כָּל דְּעָבֵיד שִׁיקְרָא בִּפְרַקְמַטְיָא\",0,0],[4,142,25,17,\"הֲווֹ דְּכִירִין יַת דְּעָבָדוּ לְכוֹן דְּבֵית עֲמָלֵק בְּאָרְחָא בְּמִפַּקְכוֹן מִמִּצְרָיִם\",0,0],[4,142,25,18,\"דְּאַרְעוּ יַתְכוֹן בְּאָרְחָא וַהֲוָה קָטִיל בְּכוֹן כָּל דַּהֲוָה מְהַרְהֵר לְמִסְטֵי בָּתַר מֵימְרִי הִינוּן גּוּבְרַיָא מִשִּׁבְטָא דְבֵית דָּן דַּהֲוָה בִידֵיהוֹן פּוּלְחָנָא נוּכְרָאָה וַהֲוָה עֲנָנָא פָּלִיט יַתְהוֹן וּדְבֵית עֲמָלֵק מְקַבֵּל יַתְהוֹן וְקָטַע בֵּית גִּבָּרֵיהוֹן וְשָׁדֵי לְעֵילָא וְאַתּוּן בֵּית יִשְרָאֵל הֲוֵיתוּן לְעִיַין וּמְשַׁלְהִין מִסּוּגֵי שִׁעֲבּוּדָא דְמִצְרָאֵי וּמִן דְּלוּחֵי גְּלִילֵי יַמָּא דַּעֲבַרְתּוּן בְּמִצְעֵיהוֹן וְלָא דַחֲלוּן בֵּית עֲמָלֵק מִן קֳדָם יְיָ\",0,0],[4,142,25,19,\"וִיהֵי כַּד יָנִיחַ יְיָ אֱלָהָכוֹן לְכוֹן מִן כָּל בַּעֲלֵי דְבָבֵיכוֹן מִן חֲזוֹר חֲזוֹר בְּאַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן אַחֲסָנָא לְמֵירְתָהּ תִּמְחוּן יַת דּוּכְרָנָא דַעֲמָלֵק מִתְּחוֹת שְׁמַיָא וַאֲפִילוּ לְיוֹמֵי מַלְכָּא מְשִׁיחָא לָא תִתְנְשֵׁי\",0,0],[4,142,26,1,\"והיה וִיהֵי אֲרוּם תֵּיעֲלוּן לְאַרְעָה דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן אַחֲסָנָא וְתֵירְתוּנָהּ וְתֵיתְבוּן בָּהּ\",0,0],[4,142,26,2,\"וְתִסְבוּן מִן שֵׁירוֹי בִּכּוּרַיָא דְמִתְבַּשְׁלִין מִן שֵׁירוּיָא בְּכָל אִבָּא דְאַרְעָא דְתָעֵיל מֵאַרְעָךְ דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן וּתְשַׁווּן בְּסַלָא וּתְהָכוּן לְאַתְרָא דְיִתְרְעֵי יְיָ אֱלָהָכוֹן לְאַשְׁרָאָה שְׁכִינְתֵּיהּ תַמָן\",0,0],[4,142,26,3,\"וּתְעַטְרוּן בְּסַלַיָא וְצִינַיָא וּפֵיפוּרַיָא וְתֵיעֲלוּן לְוַת כַּהֲנָא דִי יֶהֱוֵי מְמַנֵי לְכַהֵן רַב בְּיוֹמַיָא הָאִינוּן וְתֵימְרוּן לֵיהּ אוֹדִינָן יוֹמָא דֵין קֳדָם יְיָ אֱלָהָךְ אֲרוּם עָלֵינָן לְאַרְעָא דְקַיֵים יְיָ לְאַבְהָתָן לְמִתַּן לָנָא\",0,0],[4,142,26,4,\"וְיִסַב כַּהֲנָא יַת סַלָא דְבִכּוּרַיָא מִן יְדָךְ וְיוֹבֵל וְיֵיתֵי וְיָרִים וְיָחִית וּמִבָּתַר כְּדֵין יַחְתוּנֵיהּ קֳדָם מַדְבְּחָא דַיְיָ אֱלָהָכוֹן\",0,0],[4,142,26,5,\"וְתָתִיבוּן וְתֵימְרוּן קֳדָם יְיָ אֱלָהָכוֹן לַאֲרַם נַהֲרַיָא נַחֲתַת אָבוּנָן יַעֲקב מִן שֵׁירוּיָא וּבְעָא לְאוֹבְדוֹתֵיהּ וְשֵׁזְבֵיהּ מֵימְרָא דַיְיָ מִן יְדוֹי וּמִבָּתַר כְּדֵין נָחַת לְמִצְרַיִם וְאִיתוֹתַב תַּמָן לְעַם קָלִיל וַהֲוָה תַמָן לְאוּמָא רַבָּא וְתַקִיפָא וּמְסַגְיָא\",0,0],[4,142,26,6,\"וְאַבְאִישׁוּ לָנָא מִצְרָאֵי וְצַעֲרוּ יָתָנָא וִיהָבוּ עֲלָנָא פּוּלְחָנָא קַשְׁיָא\",0,0],[4,142,26,7,\"וְצַלֵינָא קֳדָם יְיָ אֱלָהָא דְאַבְהָתָן וְקַבֵּל יְיָ צְלוֹתָנָא וּגְלֵי קֳדָמוֹי צַעֲרָן וְלֵיעוּתָן וְדַחֲקָן\",0,0],[4,142,26,8,\"וְהַנְפָקָנָא יְיָ מִמִצְרַיִם בִּידָא תַקִיפְתָּא וּבִדְרַע מְרַמְמָא וּבְחֶזְוָונָא רַבָּא וּבְאָתִין וּבְתִמְהִין\",0,0],[4,142,26,9,\"וְאַנְטֵיל יָתָנָא לְאַתְרָא הָדֵין וִיהַב לָנָא יַת אַרְעָא הָדָא אֲרַע דְפֵירָהָא שְׁמֵינִין כַּחֲלָב וְחַלְיַין כִּדְבָשׁ\",0,0],[4,142,26,10,\"וּכְדוֹן הָא אַיְתֵיתִי יַת שֵׁירוֹי בִּיכּוּרֵי אִבָּא דְאַרְעָא דִיהַבְתְּ לִי יְיָ וְתַחְתוּנֵיהּ קֳדָם יְיָ אֱלָהָךְ וְתִסְגוֹד קֳדָם יְיָ אֱלָהָךְ\",0,0],[4,142,26,11,\"וְתֶחֱדֵי בְּכָל טַבְתָּא דִיהַב לָךְ יְיָ אֱלָהָךְ וּלְאֵינַשׁ בָּתֵּיכוֹן וְתֶהֱנוּן וְתֵיכְלוּן אַתּוּן וְלֵיוָאֵי וְגִיוֹרֵי דְבֵינֵיכוֹן\",0,0],[4,142,26,12,\"אֲרוּם תְּשֵׁיצוּן לְעַשְרָא יַת כָּל מַעֲשַר עֲלַלְתָּךְ בְּשַׁתָּא תְלִיתֵיתָא דִשְׁמִיטִיתָא וְתִתְּנוּן מַעַשְרָא קַמָאָה לְלֵיוָאֵי מַעַשְרָא תִּנְיָינָא הוּא מַעֲשַר מִסְכְּנַיָא לְגִיוֹרָא לְיַתְמָא וּלְאַרְמַלְתָּא וְיֵיכְלוּן בְּקִרְוָוךְ וְיִשְבְּעוּן\",0,0],[4,142,26,13,\"וּמַעֲשַר תְּלִיתָאֵי תֵיסַק וְתֵיכוּל קֳדָם יְיָ אֱלָהָךְ וְתֵימַר הָא אַפְרַשְׁנָן קוּדְשַׁיָא מִן בֵּיתָא וּלְחוֹד יְהַבְנַן מַעֲשְרָא קַמָאָה לְלֵיוָאֵי מַעַשְרָא תִנְיָנָא לְגִיוֹרֵי לְיַתְמָא וּלְאַרְמְלָא הֵי כְּכָל תַּפְקֵידְתָּךְ דְפַקֵידְתָּנִי לָא עָבְרַת חֲדָא מִן פִּקוּדַיִךְ וְלָא אַנְשֵׁיִית\",0,0],[4,142,26,14,\"לָא אֲכָלִית בְּיוֹמֵי אֶבְלִי מִנֵיהּ וְלָא אַפְרֵישִׁית מִנֵיהּ בִּמְסָאָב וְלָא יְהָבִית מִנֵיהּ תַּכְרִיכִין לְנֶפֶשׁ דְמִית שְׁמַעֲנָן בְּקַל מֵימְרָא דַיְיָ עֲבָדִית כְּכָל מַה דְפַקֵדְתָּנִי\",0,0],[4,142,26,15,\"אוֹדִיק מִמְדוֹר בֵּית שְׁכִינַת קוּדְשָׁךְ מִן שְׁמַיָא וּבְרִיךְ יַת עַמָךְ יַת יִשְרָאֵל וְיַת אַרְעָא דִיהַבְתְּ לָנָא הֵיכְמָא דְקַיְימִית לְאַבְהָתָנָא אַרְעָא דְפֵירָהָא שְׁמֵינִין כַּחֲלָב וְחַלְיָין כִּדְבָשׁ\",0,0],[4,142,26,16,\"יוֹמָא דֵין יְיָ אֱלָהָכוֹן מְפַקֵיד לְכוֹן לְמֶעֱבַד יַת קְיָימַיָא הָאִלֵין וְיַת דִינַיָא וְתִטְרוּן וְתַעַבְדוּן יַתְהוֹן בְּכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן\",0,0],[4,142,26,17,\"יַת יְיָ חֲטַבְתּוּן חֲטִיבָא חֲדָא בְּעַלְמָא יוֹמָנָא דְהָכִין כְּתִיב שְׁמַע יִשְרָאֵל יְיָ אֱלָהָנָא יְיָ חָד מְטוֹל לְמֶהֱוֵי לָךְ לֵאלָהָא וְלִמְהַךְ בְּאָרְחָן דְתַקְנָן קֳדָמוֹי וּלְמִנְטוֹר קְיָימוֹי וּפִקוּדוֹי וְדִינוֹי וְלִמְקַבְּלָא לְמֵימְרֵיהּ\",0,0],[4,142,26,18,\"וּמֵימְרָא דַיְיָ חֲטִיב יַתְכוֹן חֲטִיבָא חֲדָא בְּעַלְמָא יוֹמָנָא דְהָכִין כְּתִיב מַאן כְּוַות עַמְךָ יִשְרָאֵל עַם יְחִידָאֵי בְּאַרְעָא מְטוֹל לְמֶהֱוֵי לֵיהּ לְעַם חָבִיב הֵיכְמָא דְמַלֵיל לְכוֹן וּלְמִנְטַר כָּל פִּקוּדוֹי\",0,0],[4,142,26,19,\"וּלְמַנָאָה יַתְכוֹן רָמִין וְגֵיוְתָנִין עַל כָּל עַמְמַיָא דְעָבַד לִרְבוּ וּלְשׁוּם דִיקַר וּלְשִׁיבְהוֹרָא מְטוּל לְמֶהֱוֵי עַם קַדִישׁ קֳדָם יְיָ אֱלָהָכוֹן הֵיכְמָא דְמַלֵיל\",0,0],[4,142,27,1,\"וּפַקֵיד משֶׁה וְסָבֵי יִשְרָאֵל יַת עַמָא לְמֵימָר טוּרוּ יַת כָּל תַּפְקֵידְתָּא דַאֲנָא מְפַקֵיד לְכוֹן יוֹמָנָא\",0,0],[4,142,27,2,\"וִיהֵי בְּיוֹמָא דְתַעַבְרוּן יַת יוֹרְדְנָא לְאַרְעָא דַיְיָ אֱלָהָכוֹן יָהִיב לְכוֹן וּתְקוּמוּן לְכוֹן אַבְנִין רַבְרְבִין וּתְשׁוּעוּן יַתְהוֹן בְּגִירָא\",0,0],[4,142,27,3,\"וְתִכְתּוֹב עֲלֵיהוֹן יַת כָּל פִּתְגָמֵי אוֹרַיְיתָא הֲדָא בְּמֶעֱבַרְכוֹן מִן בִּגְלַל דְתֵיעֲלוּן לְאַרְעָא דַיְיָ אֱלָהָכוֹן יָהִיב לְכוֹן אַרְעָא דְפֵירָהָא שְׁמֵינִין כַּחֲלָב וְעַבְדִין דְבַשׁ הֵיכְמָא דְמַלִיל אֱלָהָא דְאַבְהַתְכוֹן לְכוֹן\",0,0],[4,142,27,4,\"וִיהֵי בִּזְמַן דְתַעַבְרוּן יַת יוֹרְדְנָא תְקִימוּן יַת אַבְנַיָא הָאִילֵין דַאֲנָא מְפַקֵיד יַתְכוֹן בְּטַוְורָא דְעֵיבָל וּתְשׁוּעוּן יַתְהוֹן בְּגִירָא\",0,0],[4,142,27,5,\"וְתִבְנוּן תַּמָן מַדְבְּחָא קֳדָם יְיָ אֱלָהָכוֹן מַדְבַּח אַבְנִין לָא תְרִים עֲלֵיהוֹן פַּרְזְלָא\",0,0],[4,142,27,6,\"אַבְנִין שַׁלְמִין תִּבְנוּן יַת מַדְבְּחָא דַיְיָ אֱלָהָכוֹן וְתִסְקוּן עֲלוֹי עֲלַוָון קֳדָם יְיָ אֱלָהָכוֹן\",0,0],[4,142,27,7,\"וְתִיכְסוּן נִכְסַת קוּדְשִׁין וְתֵיכְלוּן תַּמָן וְתֵיחֲדוּן קֳדָם יְיָ אֱלָהָכוֹן\",0,0],[4,142,27,8,\"וְתִכְתְּבוּן עַל אַבְנַיָא יַת כָּל פִּתְגָמֵי אוֹרַיְיתָא הֲדָא כְּתַב חָקִיק וּמְפָרַשׁ מִתְקְרֵי בְּחַד לִישָׁן וּמִיתַרְגֵם בְּשִׁבְעִין לִישָׁנִין\",0,0],[4,142,27,9,\"וּמַלֵיל משֶׁה וְכַהֲנַיָא בְּנֵי לֵוִי עִם כָּל עַמָא לְמֵימָר צַיְיתוּ וּשְׁמָעוּ יִשְרָאֵל יוֹמָנָא הָדֵין אִתְבְּחַרְתּוּן לְמֶהֱוֵי עַמָא קֳדָם יְיָ אֱלָהָכוֹן\",0,0],[4,142,27,10,\"וּתְקַבְּלוּן לְמֵימְרָא דַיְיָ אֱלָהָכוֹן וְתַעַבְדוּן יַת פִּקוּדוֹי וְיַת קְיָימוֹי דַאֲנָא מְפַקֵיד לְכוֹן יוֹמָא דֵין\",0,0],[4,142,27,11,\"וּפַקֵיד משֶׁה יַת עַמָא בְּיוֹמָא הַהוּא לְמֵימָר\",0,0],[4,142,27,12,\"אִלֵין שִׁבְטַיָא יְקוּמוּן לְבָרְכָא יַת עַמָא עַל טַוְורָא דִגְרִיזִים בְּמֶעֱבַרְכוֹן יַת יוֹרְדְנָא שִׁמְעוֹן וְלֵוִי וִיהוּדָה וִישָשׁכָר וְיוֹסֵף וּבִנְיָמִין\",0,0],[4,142,27,13,\"וְאִלֵין שִׁבְטַיָא יְקוּמוּן עַל לְוָטַיָא בְּטַוְורָא דְעֵיבָל רְאוּבֵן גָד וְאָשֵׁר וּזְבוּלֻן דָן וְנַפְתָּלִי\",0,0],[4,142,27,14,\"וְיִכְרְזוּן לֵיוָאֵי וְיֵימְרוּן לְכָל אֵינַשׁ יִשְרָאֵל בְּקָלָא רָמָא\",0,0],[4,142,27,15,\"שִׁיתָּא שִׁבְטִין קָמוּ עַל טַוְורָא דִגְרִיזִים וְשִׁיתָּא עַל טַוְורָא דְעֵיבָל וַאֲרוֹנָא וְכַהֲנַיָא וְלֵיוָאֵי בִּמְצִיעָא מְבָרְכַיָא הֲווֹן הָפְכִין אַפֵּיהוֹן כֻּלוֹ קֳבֵיל טַוְורָא דִגְרִיזִים וְאָמְרִין בְּרִיךְ יֶהֱוֵי גַבְרָא דְלָא יֶעֱבַד צְלַם וְצוּרָה וְכָל דְמוּ מַה דִמְרַחֵק קֳדָם יְיָ עוֹבַד יְדֵי אוּמַן וְלָא יְשַׁוֵי בְטוּמְרָא מְלַטְטַיָא הֲווֹן הָפְכִין אַפֵּיהוֹן כֻּלוֹ קֳבֵיל טַוְורָא דְעֵיבָל וְאָמְרִין לִיט יֶהֱוֵי גַבְרָא דְיַעֲבֵיד צְלַם וְצוּרָה וְכָל דְמוּ מַה דִמְרַחֵק קֳדָם יְיָ עוֹבַד יְדֵי אוּמַן וְשַׁוֵי בְטוּמְרָא הֲווֹן עַנְיַין כּוּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן\",0,0],[4,142,27,16,\"לִיט דִמְזַלְזֵל אִיקְרָא דְאָבוֹי וּדְאִמֵיהּ עַנְיַין כּוּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן\",0,0],[4,142,27,17,\"לִיט דְיַשְׁנֵי תְּחוּמָא דְחַבְרֵיהּ הֲווֹן עַנְיַין כֻּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן\",0,0],[4,142,27,18,\"לִיט דְיִטְעֵי אַכְסַנְיָא בְּאוֹרְחָא דְהוּא מְדַמֵי לְסַמְיָא הֲווֹן עַנְיַין כֻּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן\",0,0],[4,142,27,19,\"לִיט דְיַצְלֵי דִין דַיָיר יִתַּם וְאַרְמְלָא הֲווֹן עַנְיַין כֻּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן\",0,0],[4,142,27,20,\"לִיט דִמְשַׁמֵשׁ עִם אִתַּת אָבוֹי אֲרוּם גְלֵי כַנְפָא דְגַלֵי אָבוֹי הֲווֹן עַנְיַין כֻּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן\",0,0],[4,142,27,21,\"לִיט דִמְשַׁמֵשׁ עִם כָּל בְּעִירָא הֲווֹן עַנְיַין כּוּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן\",0,0],[4,142,27,22,\"לִיט דִמְשַׁמֵשׁ עִם אַחְתֵיהּ בְּרַת אָבוֹי אוֹ בְּרַת אִמֵיהּ הֲווֹ עַנְיַין כּוּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן\",0,0],[4,142,27,23,\"לִיט דִמְשַׁמֵשׁ עִם חֲמוֹתֵיהּ הֲווֹן עַנְיַין כּוּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן\",0,0],[4,142,27,24,\"לִיט דְיִמְחֵי חַבְרֵיהּ בְּלִישַׁן תְּלִיתָאֵי בְּטוּמְרָא הֲווֹן עַנְיַין כּוּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן\",0,0],[4,142,27,25,\"לִיט דִמְקַבֵּל שׁוֹחֲדָא לְמִיקְטוֹל בַּר נַשׁ לְמִשְׁדֵי אֲדַם זַכַּאי הֲווֹן עַנְיַין כּוּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן\",0,0],[4,142,27,26,\"תַּרְתֵּיסְרֵי שִׁבְטַיָא כָּל חַד וְחַד הֲוָה אָמַר בִּרְכָתָא בִּכְלָלָא וּלְוָוטַיָא בִּכְלָלָא מְבָרְכַיָא הֲווֹן הָפְכִין אַפֵּיהוֹן לְכָל מִילָא וּמִילָא כֻּלוֹ קֳבֵיל טַוְורָא דִגְרִיזִים וְאָמְרִין בְּרִיךְ יֶהֱוֵי גַבְרָא דִי יְקִים יַת פִּתְגָמֵי אוֹרַיְיתָא הֲדָא לְמֶעֱבַדְהוֹן מְלַטְטַיָא הָפְכִין אַפֵּיהוֹן כֻּלוֹ קֳבֵיל טַוְורָא דְעֵיבָל וְאָמְרִין לִיט יֶהֱוֵי גַבְרָא דְלָא יְקִים יַת פִּתְגָמֵי אוֹרַיְיתָא הֲדָא לְמֶעֱבַדְהוֹן הֲווֹן עַנְיַין כֻּלְהוֹן כַּחֲדָא וְאָמְרִין אָמֵן פִּתְגָמַיָא אִלֵין אִתְאַמָרוּ בְּסִינַי וְאִתַּנְייוּ בְּמַשְׁכַּן זִמְנָא וְאִיתְלֵיתוּן בְּמֵישְׁרֵי מוֹאָב תַּרְתֵּיסְרֵי מִלִין מִן מִלְתָא לְכָל שִׁבְטַיָא וְעַל כָּל פִּיקוּדָא וּפִיקוּדָא אִתְגְזַר עֲלָהּ תְּלָתִין וְשִׁית קַיָמִין\",0,0],[4,142,28,1,\"וִיהֵי אִין קַבָּלָא תְּקַבְּלוּן לְמֵימְרָא דַיְיָ אֱלָהָכוֹן לְמִנְטַר וּלְמֶעֱבַד יַת כָּל פִּקוּדוֹי דַאֲנָא מְפַקֵיד לְכוֹן יוֹמָנָא וְיִתְנִינְכוֹן יְיָ אֱלָהָכוֹן רָמִין וְגֵיוְתָנִין עַל כָּל עַמְמֵי אַרְעָא\",0,0],[4,142,28,2,\"וְיֵיתוּן עֲלֵיכוֹן כָּל בִּרְכָתָא הָאִלֵין וְיִדְבּוּקַנְכוֹן אֲרוּם תְּקַבְּלוּן לְמֵימְרָא דַיְיָ אֱלָהָכוֹן\",0,0],[4,142,28,3,\"בְּרִיכִין אַתּוּן בְּקַרְתָּא וּבְרִיכִין אַתּוּן בְּחַקְלָא\",0,0],[4,142,28,4,\"בְּרִיכִין וַלְדֵי מֵעֵיכוֹן וּפֵירֵי אַרְעֲכוֹן בַּקְרֵי תוֹרֵיכוֹן וְעֶדְרֵי עָנֵיכוֹן\",0,0],[4,142,28,5,\"בְּרִיךְ סַלֵי בִּיכּוּרֵיכוֹן וְחַלַת שֵׁירוֹי אַצְוַותְכוֹן\",0,0],[4,142,28,6,\"בְּרִיכִין אַתּוּן בְּמֵיעֲלְכוֹן לְבָתֵּי מֶדְרָשֵׁיכוֹן וּבְרִיכִין אַתּוּן בְּמִפַּקְכוֹן לִפְרַקְמַטְיֵיכוֹן\",0,0],[4,142,28,7,\"יְשַׁוֵי מֵימְרָא דַיְיָ יַת בַּעֲלֵי דְבָבֵיכוֹן דְקַיְימִין לְקוּבְלֵיכוֹן לִמְבָאֲשָׁא תְּבִירִין קֳדָמֵיכוֹן בְּאוֹרְחָא חַד יְהוֹן נַפְקִין לְוַותְכוֹן לְסִדְרֵי קְרָבָא וּבְשִׁבְעָא אָרְחִין טַעֲיַין יֶהֱווּן עַרְקִין מִן קֳדָמֵיכוֹן\",0,0],[4,142,28,8,\"יְפַקֵיד יְיָ עִמְכוֹן יַת בִּרְכָתָא בְּאוֹצְרֵיכוֹן וּבְכָל אוֹשָׁטוּת יְדֵיכוֹן וִיבָרְכֵיכוֹן בְּאַרְעָא דַיְיָ אֱלָהָכוֹן יָהֵיב לְכוֹן\",0,0],[4,142,28,9,\"יְקוּם יַתְכוֹן מֵימְרָא דַיְיָ קֳדָמוֹי לְעַם קַדִישׁ הֵיכְמָא דְמַלֵיל לְכוֹן אֲרוּם תִּנְטְרוּן יַת פִּיקוּדַיָא דַיְיָ אֱלָהָכוֹן וְתַהֲכוּן בְּאָרְחָן דְתַקְנָן קֳדָמוֹי\",0,0],[4,142,28,10,\"וְיֶחֱמוּן כָּל עַמְמֵי אַרְעָא אֲרוּם שְׁמָא דַיְיָ חָקִיק בִּזְמַן דִתְּפִילִין עֲלָךְ וִידַחֲלוּן מִנָךְ\",0,0],[4,142,28,11,\"וִישַׁיְירִנְכוֹן מֵימְרָא דַיְיָ לְטָבָא בְּוַולְדָא דִמְעֵיכוֹן וּבְוַולְדָא דִבְעִירֵיכוֹן וּבְאִבָּא דְאַרְעֲכוֹן עַל אַרְעָא דְקַיֵים יְיָ לְאַבְהַתְכוֹן\",0,0],[4,142,28,12,\"אַרְבְּעָא מַפְתְּחִין בִּידֵי דְמָארֵי עַלְמָא דְלָא מְסָרִינוּן בִּידָא דְטַפְסְרָא מַפְתְּחָא דְחַיְיתָא וּדְקִבְרַיָא וְדִמְזוֹנֵי וּדְמִטְרָא וְכֵן אָמַר משֶׁה נְבִיָא הָכָא יִפְתַּח יְיָ לְכוֹן יַת אוֹצָרֵיהּ טַב דְעִמֵיהּ בִּשְׁמַיָא לְמִתַּן מְטַר אַרְעֲכוֹן בְּזִמְנֵיהּ בַּכִּיר בְּמַרְחֶשְׁוָן וְלָקִישׁ בְּנִיסָן וּלְבָרְכָא יַת כָּל עוֹבָדֵי יְדֵיכוֹן וְתוֹזְפוּן לְעַמְמִין סַגִיאִין וְאַתּוּן לָא תִצְטַרְכוּן לְמֵיזִיף\",0,0],[4,142,28,13,\"וְיִמְנֵי מֵימְרָא דַיְיָ יַתְכוֹן לְמַלְכִין וְלָא לְהֶדְיוֹטִין וְתֶהֱווּן לְחוֹד מְנַטְלִין וְלָא תְהוֹן לְמָאִיסִין אֲרוּם תְּקַבְּלוּן לְפִקוּדַיָא דַיְיָ אֱלָהָכוֹן דַאֲנָא מְפַקֵיד לְכוֹן יוֹמָנָא לְמִנְטוֹר וּלְמֶעֱבַד\",0,0],[4,142,28,14,\"וְלָא תִסְטוּן מִן כָּל פִּתְגָמַיָא דַאֲנָא מְפַקֵיד לְכוֹן יוֹמָנָא לְיַמִינָא וְלִשְמָאלָא לִמְהַךְ בָּתַר טַעֲוַות עַמְמַיָא לְמִפְלַחְהוֹן\",0,0],[4,142,28,15,\"כַּד פָּתַח משֶׁה נְבִיָא לְמֵימָר פִּתְגָמֵי אוֹכְחוּתָא הָאִלֵין אִתְרְגִישַׁת אַרְעָא וּשְׁמַיָא זָעוּ שִׁמְשָׁא וְסִיהֲרָא קָדְרוֹן וְכוֹכְבַיָא כְנָשׁוּ זִיוְוהוֹן אַבְהַת עַלְמָא צְוָוחִין מִבֵּית קְבוּרְתְּהֶן וְכָל בִּרְיָיתָא שָׁתְקִין וְאִלָנַיָיא לָא טִלְטֵל זָאזֵיהוֹן עַנְיַין אַבְהַת עַלְמָא וְאָמְרִין חֲבוֹל עַל בְּנֵינָן כַּד יְחוֹבִין וְיִמְטוּן עֲלֵיהוֹן לְוָוטַיָא אִלֵין הֵיךְ יָכְלִין לְסוֹבָרוּתְהוֹן וְדִלְמָא יֶעֱבַד בְּהוֹן שֵׁצְיוּ וְלָא תְהֵי זְכוּתִין מְגַנָא עֲלֵיהוֹן וְלָא יֶהֱוֵי גַבְרָא דִיקוּם וִיצַלֵי אַמָטוּלְתְּהוֹן בְּרַת קָלָא נָפְלַת מִן שְׁמֵי מְרוֹמָא וְכֵן אֲמָרַת לָא תִדְחֲלוּן אַבְהַת עַלְמָא דַאֲפִילוּ פָּסְקָא זְכוּתְהוֹן דְכָל דָרַיָא זְכוּתְכוֹן לָא יִפְסוֹק וּקְיָימָא דְקַיֵימִית עִמְכוֹן לָא מְבַטְלָא וּתְהֵי מְגַנָא עֲלֵיהוֹן עָנֵי משֶׁה נְבִיָא וַאֲמַר אַף עַל גַב דַאֲנָא מוֹכַח יַתְכוֹן עַל תְּנָאָה מִתְוַוכְּחִין לְמֵימָר דְאִין לָא תְקַבְּלוּן לְמֵימְרָא דַיְיָ אֱלָהָכוֹן דְלָא לְמִטוּר לְמֶעֱבַד יַת כָּל פִּקוּדֵי וּקְיָמֵי דַאֲנָא מְפַקֵיד לְכוֹן יוֹמָא דֵין וְיֵיתוּן עִילַוֵיכוֹן כֻּלְהוֹן לְוָטַיָא הָאִלֵין וְיִדְבְּקוּנְכוֹן\",0,0],[4,142,28,16,\"לִיטִין אַתּוּן בְּקַרְתָּא וְלִיטִין אַתּוּן בְּחַקְלָא\",0,0],[4,142,28,17,\"לִיטִין סַלֵי בִּכּוּרֵיכוֹן וְחַלַת שֵׁירוֹי אַצְוַותְכוֹן\",0,0],[4,142,28,18,\"לִיטִין וַולְדֵי מֵעֵיכוֹן וּפֵירֵי אַרְעֲכוֹן בַּקְרֵי תּוֹרֵיכוֹן וְעֶדְרֵי עָנֵיכוֹן\",0,0],[4,142,28,19,\"לִיטִין אַתּוּן בְּמַעַלְכוֹן לְבָתֵּי קִיאַטְרוֹנֵיכוֹן וְקוֹרְקִיסַתְכוֹן לְמִבַטְלָא פִּתְגָמֵי אוֹרַיְיתָא וְלִיטִין אַתּוּן בְּמִיפַּקְכוֹן לִפְרַגְמַטְיֵיכוֹן\",0,0],[4,142,28,20,\"יְגָרֵי מֵימְרָא דַיְיָ בְּכוֹן יַת לְוָוטְתָא לְלַטָטָא מָמוֹנְכוֹן וְיַת עַרְבּוּבָא לְעַרְבָּבָא שְׁלַמְכוֹן וְיַת מְזוֹפִיתָא בְּכָל אוֹשָׁטוּת יֶדְכוֹן דְתַעַבְדוּן עַד דְתִשְׁתֵּיצוּן וְעַד דְתוֹבְדוּן בְּסַרְהוּבַיָא מִן קֳדָם בִּישׁוּת עוֹבָדֵיכוֹן דִשְׁבַקְתּוּן דַחַלְתִּי\",0,0],[4,142,28,21,\"יְאַדֵיק מֵימְרָא דַיְיָ בְּכוֹן יַת מוֹתָא דִישֵׁיצֵי יַתְכוֹן מֵעִילַוֵי אַרְעָא דְאַתּוּן עַלְלִין תַּמָן לְמֵירְתָהּ\",0,0],[4,142,28,22,\"יִמְחֵי יַתְכוֹן מֵימְרָא דַיְיָ בְּשַׁחְפוּתָא וּבְקַדְחוּתָא וּבְאֵישָׁא דְגַרְמַיָא דְדַלְקָא מוֹחַיָא וּבְחַרְחוּרֵי דְלוּחֵי צִירְתָא דְלִבָּא וּבִשְׁלוּפֵי חַרְבָּא וּבְשִׁדָפוֹנָא וּבְיַרְקוֹנָא דְמַקְדוֹנַיָא וְיִרְדְפוּנְכוֹן עַל שִׁוְויֵיכוֹן עַד דְתֵיבְדוּן\",0,0],[4,142,28,23,\"וִיהוֹן שְׁמַיָא דְעִילַוֵיכוֹן הֵי כִּנְחָשָׁא דִמְזִיעַ וְלָא מְסַפְּקִין לְכוֹן טַלִין וּמִטְרִין וְאַרְעָא דִתְחוֹתְכוֹן הֵי כְּפַרְזְלָא דְלָא מַזִיעַ דְלָא מַרְטִיבָא אִילָנֵי וְאַסְפַּרְמְקֵי וּמְגָדֵי וְיַרְקֵי\",0,0],[4,142,28,24,\"יְגָרֵי יְיָ בָּתַר מִטְרִין דְנַחְתִין עַל אַרְעֲכוֹן רוּחָא דְמַסְקָא אַבְקָא וְעַפְרָא עִילַוֵי עִשְבֵּי חַקְלֵיכוֹן מִן שְׁמַיָא יֵחוֹת פּוּרְעָנוּ עֲלֵיכוֹן עַד דְתִשְׁתֵּיצוּן\",0,0],[4,142,28,25,\"יְשַׁוֵי יַתְכוֹן מֵימְרָא דַיְיָ תְּבִירִין קֳדָם בַּעֲלֵי דְבָבֵיכוֹן בְּאָרְחָא חַד תִּפְקוּן לִקְדָמוּתְהוֹן לְסִדְרֵי קְרָבָא וּבְשִׁבְעָתֵי אָרְחָן טַעֲיָין תֶּהֱווֹן מַפְכִין (י\\\"ג עַרְקִין) מִן קֳדָמֵיהוֹן וְתֶהֱווֹן לְרִיחוּק לְכָל מַלְכוּת אַרְעָא\",0,0],[4,142,28,26,\"וּתְהֵי נְבֵלְתְּכוֹן מְשַׁגְרָא לְמֵיכַל לְכָל עוֹפָא דִשְׁמַיָא וְלִבְעִירָא דְאַרְעָא וְלֵית דְמָנִיד יַתְהוֹן מֵעִילַוֵי נְבֵילְתְּכוֹן\",0,0],[4,142,28,27,\"יַמְחִינְכוֹן מֵימְרָא דַיְיָ בְּשִׁיחְנֵי דִי לָקוּ בְּהוֹן מִצְרָאֵי וּבִטְחוֹרַיָא דִמְסַמְיָין חֶזְוָותָא וּבְגַרְבָּא וּבְחִכּוּכָא דְלָא תֵכְלוּן לְאִיתְּסָאָה\",0,0],[4,142,28,28,\"יַמְחִינְכוֹן מֵימְרָא דַיְיָ בְּשַׁוְויָיתָא דִמְטַפְּשָׁא מוֹקְדָא וּבְסַמְיָתָא וּבְשִׁיעֲמָמוּת לִבָּא\",0,0],[4,142,28,29,\"וְתֶהֱווֹן תְּבִיעִין מִילְכָּא טָבָא לִרְוָחֵי עֲקַתְכוֹן וְלָא יֶהֱוֵי בְּכוֹן מְחַוֵי קוּשְׁטָא הֵיכְמָא דִמְמַשֵׁשׁ סַמְיָא בְּקִיבְלָא דְלֵית לַעֲדֵי אוֹרְחָא לְמֶחֱמֵי לִמְכַוָונוּתְהוֹן בְּאָרְחָא וְלָא תַצְלְחוּן יַת אָרְחַתְכוֹן וְתֶהֱווֹן בְּרַם עַצְיַין וַאֲנִיסִין כָּל יוֹמַיָא וְלֵית דְפָרִיק\",0,0],[4,142,28,30,\"אִיתָא תְּקַדֵשׁ וּגְבַר חוֹרַן יְשַׁמֵשׁ עִמָהּ בֵּיתָא תִבְנֵי וְלָא תִיתַב בֵּיהּ כַּרְמָא תִנְצוֹב וְלָא תַחְלִינֵיהּ\",0,0],[4,142,28,31,\"תּוֹרֵיכוֹן יְהוֹן נְכִיסִין וְאַתּוּן חַמְיַין וְלָא תֵיכְלוּן מִנְהוֹן חַמְרֵיכוֹן יֶהֱוְיָין אֲנִיסִין מִן קֳדָמֵיכוֹן וְלָא יְתוּבוּן לְכוֹן עָנֵיכוֹן מְסִירִין לְבַעֲלֵי דְבָבֵיכוֹן וְלֵית לְכוֹן פָּרִיק\",0,0],[4,142,28,32,\"בְּנֵיכוֹן וּבְנָתֵיכוֹן מְסִירִין לְעַם חִילוֹנֵי וְעֵינֵיכוֹן חַמְיָין וְחַשְׁכָן עֲלֵיהוֹן כָּל יוֹמָא וְלֵית בִּידֵיכוֹן עָבְדִין טָבְיָן דְתִיתוֹקְפָן יְדֵיכוֹן בִּצְלוֹ קֳדָם יְיָ אֲבוּכוֹן דְבִשְׁמַיָא דְיִפְרוֹק יַתְכוֹן\",0,0],[4,142,28,33,\"פֵּירֵי אַרְעֲכוֹן וְכָל לֵיעוּתְכוֹן יְגַמֵר עַמָא דְלָא חַכִּימְתּוּן וְתֶהֱווֹן בְּרַם טְלִימִין וּדְרִיסִין כָּל יוֹמַיָא\",0,0],[4,142,28,34,\"וְתֶהֱווֹן מִשְׁתַּטְיָין מִפּוּרְעֲנוּתָא וּמִן מֶחְמֵי עֵינֵיכוֹן דְתֵיחְמוּן תְּזוּעוּן\",0,0],[4,142,28,35,\"יַמְחִינְכוֹן מֵימְרָא דַיְיָ בְּשִׁיחְנָא בִישָׁא עַל רְכוּבַיָא מְטוֹל דְחַמִיטְתוֹן לְפִתְגַם עֲבֵירְתָּא וְעַל שַׁקְיָיא דִרְהָטוּ לָהּ וְאִין לָא תְתוּבוּן לְאוֹרַיְיתָא לָא תֵכְלוּן לְאִיתַּסָאָה אֱלָהֵן תִּילְקוּן בֵּיהּ מִפַּרְסַת רִיגְלֵיכוֹן וְעַד מוֹקְדָא דְרֵישֵׁיכוֹן\",0,0],[4,142,28,36,\"יַגְלֵי יְיָ יַתְכוֹן וְיַת מַלְכְּכוֹן דְתִמְנוּן עֲלֵיכוֹן לְאוּמָא דְלָא חַכִּימְתּוּן אַתּוּן וְאַבְהַתְכוֹן וְתֶהֱווֹן מַסְקֵי אַרְנוּנִין לְפַלְחֵי טַעֲוָון דְקַיְסִין וְאַבְנִין\",0,0],[4,142,28,37,\"וְאִין יְהַרְהֵר לִבְּכוֹן לְמִפְלַח לְטַעֲוַותְהוֹן תֶּהֱווֹן לְשַׁעֲמוֹן לְמִתְלִין וְלִתְנוּיָין בֵּינֵי עַמְמַיָא דִי בַּדַר יַתְכוֹן יְיָ לְתַמָן\",0,0],[4,142,28,38,\"בַּר זְרַע סַגִי תִפְקוּן לְחַקְלָא וּזְעֵיר תִּכְנְשׁוּן אֲרוּם יְקַרְסוּם יָתֵיהּ גוֹבָאֵי\",0,0],[4,142,28,39,\"כְּרָמִין תִּנְצְבוּן וְתִפְלְחוּן וְחַמְרָא לָא תִשְׁתּוּן וְלָא תְעַצְרוּן לְמִכְנוֹשׁ אֲרוּם יְגַמְרִינֵיהּ זַחֲלָא\",0,0],[4,142,28,40,\"זֵיתִין יְהוֹן לְכוֹן בְּכָל תְּחוּמְכוֹן וּמְשַׁח לָא תְשׁוּטוּן אֲרוּם יְנַתְּרוּן זֵיתֵיכוֹן\",0,0],[4,142,28,41,\"בְּנִין וּבְנָן תּוֹלְדוּן וְלָא יֶהֱוְויָין מְהַנְיָין לְכוֹן אֲרוּם יִזְלוּן בְּשִׁבְיָיתָא\",0,0],[4,142,28,42,\"כָּל אִילָנֵיכוֹן וּפֵירֵי אַרְעֲכוֹן יְשֵׁצֵי חֲלָנוּנָא\",0,0],[4,142,28,43,\"עַרְלָאָה דְדַיַיר בֵּינֵיכוֹן יִסוֹק עֲלֵיכוֹן מְסוּקְיָין עַל מְסוּקְיָין וְאַתּוּן תְּחוּתוּן דְרַע מִנֵיהּ מְחוּתִין מִן מְחוּתִין\",0,0],[4,142,28,44,\"הוּא יַזְפוּנְכוֹן וְאַתּוּן לָא תוֹזְפוּן לְהוֹן הוּא יֶהֱוֵי שַׁלִיט וְאַתּוּן תֶּהֱווֹן הֶדְיוֹטִין\",0,0],[4,142,28,45,\"וְיֵיתוּן עִילַוֵיכוֹן כָּל לְוָטַיָא הָאִלֵין וְיִרְדְפוּנְכוֹן וִיעַרְקִינְכוֹן עַד דְתִשְׁתֵּיצוּן אֲרוּם לָא קַבֵּילְתּוּן לְמֵימְרָא דַיְיָ אֱלָהָכוֹן לְמִטַר פִּקוּדוֹי וּקְיָימוֹי דִי פַקֵיד יַתְכוֹן\",0,0],[4,142,28,46,\"וִיהוֹן בְּכוֹן לְאָתִין וּלְתִמְהִין וּבִבְנֵיכוֹן עַד עָלְמָא\",0,0],[4,142,28,47,\"חוֹלַף דְלָא פְלַחְתּוּן קֳדָם יְיָ אֱלָהָכוֹן בְּחֶדְוָוא וּבִשְׁפִּירוּת לִבָּא מִסוֹגְעֵי כָּל טוּבָא\",0,0],[4,142,28,48,\"וְתִפְלְחוּן יַת בַּעֲלֵי דְבָבֵיכוֹן דִיגָרִינוּן מֵימְרָא דַיְיָ בְּכוֹן בְּכַפְנָא וּבְצָחוּתָא וּבְעַרְטִלְיוּתָא וּבְחוּסְרַן כָּל טַבְתָּא וְיִשְׁווֹן נִירֵי פַּרְזְלָא עַל צַוָורֵיכוֹן עַד זְמַן דִישֵׁיצֵי יַתְכוֹן\",0,0],[4,142,28,49,\"יְטַיֵיס מֵימְרָא דַיְיָ עֲלֵיכוֹן אוּמָא מִן רָחִיק מִן סְיָפֵי אַרְעָא קְלִילִין כְּמָא דְטַיֵיס גִישְׁרָא אוּמָא דְלָא תִשְׁמַע לִישְׁנֵיהּ\",0,0],[4,142,28,50,\"אוּמָא חֲצוּפֵי אַפִּין דְלָא נְסִיב אַפִּין לְסָבָא וְעַל עוּלֵים לָא חַיִיס\",0,0],[4,142,28,51,\"וְיִגְמְרוּן וַולְדֵי דִבְעִרֵיכוֹן וּפֵירֵי אַרְעֲכוֹן עַד דְתִשְׁתֵּיצוּן דְלָא יְשַׁיְירוּן לְכוֹן עִבּוּר מְשַׁח וַחֲמַר בַּקְרֵי תוֹרֵיכוֹן וְעֶדְרֵי עָנֵיכוֹן עַד זְמַן דִי יְהוֹבְדוּן יַתְכוֹן\",0,0],[4,142,28,52,\"וְיָעִיקוּן לְכוֹן בְּכָל קִירְוֵיכוֹן עַד זְמַן דִי יֵחְתוּן אֲכוֹלֵיכוֹן רָמַיָא וְתָלִילַיָא דְאַתּוּן רְחִיצִין בְּהוֹן לְאִשְׁתֵּיזְבָא בְּהוֹן בְּכָל אַרְעֲכוֹן וְיָעִיקוּן לְכוֹן בְּכָל קִירְוֵיכוֹן בְּכָל אַרְעֲכוֹן דִיהַב יְיָ אֱלָהָכוֹן לְכוֹן\",0,0],[4,142,28,53,\"וְיִגְמְרוּן וַולְדֵי מְעֵיכוֹן דְתֵיכְלוּנוּן בְּכַפְנָא בְּשַר בְּנֵיכוֹן וּבְנָתֵיכוֹן דִיהַב יְיָ אֱלָהָכוֹן לְכוֹן בְּצַעֲרוּ וּבְעָקָא דִיעִיקוּן לְכוֹן סַנְאֵיכוֹן\",0,0],[4,142,28,54,\"גַבְרָא דְמֶחְטֵי בְּכוֹן וְדִימְפַרְנֵק לַחֲדָא תַּבְאֵשׁ עַיְינֵיהּ בְּאָחוֹי וּבְאִתְּתָא דְדָמְכָה בְּעוֹבֵיהּ וּבְשָׁיֵיר בְּנוֹי דִישַׁיֵיר\",0,0],[4,142,28,55,\"מִן לָא לְמִתַּן לְחַד מִנְהוֹן מִבְּשַר בְּנוֹי דִי יֵיכוּל מִן דְלָא אִשְׁתְּיַיר לֵיהּ מִדַעַם בְּצַעֲרוֹי וּבְעָקָא דִי יְעָקוּן לְכוֹן סַנְאֵיכוֹן בְּכָל קִירְוֵיכוֹן\",0,0],[4,142,28,56,\"דִמְחַטַיְיתָא בְכוֹן וּדְמִפְרַנְקָא דְלָא נַסְיַית פַּרְסַת רִיגְלָהּ לְמִדְרַס עַל אַרְעָא מִן פַּרִינְקָא וּמִן חִיטוֹיָא תִּבְאַשׁ עֵינָהּ בִּבְעֵיל דְדָמִיךְ בְּעוֹבָהּ וּבִבְרָהּ וּבִבְרַתָּהּ\",0,0],[4,142,28,57,\"וּבִשְׁפִיר שִׁלְיְתָא דְתִיפּוֹק מִבֵּית תּוֹרְפָהּ בְּעִידָן מוֹלְדָהּ וּבִבְנָהּ דְתוֹלִיד אֲרוּם תֵּיכְלוּנוּן בְּחוֹסְרַן כָּל מִדַעַם בְּטוּמְרָא בְּצַעֲרוּ וּבְעָקָא דִי יְעִיקוּן לְכוֹן סַנְאֵיכוֹן בְּקִירְוֵיכוֹן\",0,0],[4,142,28,58,\"אִין לָא תִנְטְרוּן לְמֶעֱבַד יַת כָּל פִּקוּדַיָיא דְאוֹרַיְיתָא הָדָא דִכְתִיבִין בְּסִפְרָא הָדֵין לְמִדְחַל יַת שְׁמָא יַקִירָא וּדְחִילָא הָדֵין יַת יְיָ אֱלָהָכוֹן\",0,0],[4,142,28,59,\"וִיכַסֵי מֵימְרָא דַיְיָ מִנְכוֹן רוּחַ קוּדְשָׁא כַּד יֵיתוּן מַחְתִין עֲלֵיכוֹן וּמַחְתִין עַל בְּנֵיכוֹן מַחַן רַבְרְבִין וּמְהֵימְנָן דְלָא לְמִשְׁבַּקְכוֹן וּמַרְעִין בִּישִׁין וּמְהֵימְנִין דְמִתְעַתְּקִין עַל גוּשְׁמֵיכוֹן\",0,0],[4,142,28,60,\"וִיתִיב בְּכוֹן יַת כָּל אַרְעַיָא דְאִתְגְרִייוּ בְּמִצְרָאֵי דִדְחִילַת מִן קֳדָמֵיהוֹן וְיִתְאַדְקוּן בְּכוֹן\",0,0],[4,142,28,61,\"לְחוֹד כָּל מְרָא וְכָל מְחָא דְלָא כְּתִיבִין בְּסֵפֶר אוֹרַיְיתָא הָדֵין יַסְקִינוּן מֵימְרָא דַיְיָ עֲלֵיכוֹן עַד דְתִשְׁתֵּיצוּן\",0,0],[4,142,28,62,\"וְתִשְׁתַּיְירוּן בְּאוּמָה קַלִילָא חוֹלַף דִי הֲוֵיתוּן הֵי כְכוֹכְבֵי שְׁמַיָא לְסוֹגֵי אֲרוּם לָא קַבֵּילְתּוּן לְמֵימְרָא דַיְיָ אֱלָהָכוֹן\",0,0],[4,142,28,63,\"וִיהֵי הֵיכְמָא דְחָדֵי מֵימְרָא דַיְיָ עֲלֵיכוֹן לְאוֹטָבוּתְכוֹן וּלְאַסְגָאָה יַתְכוֹן הֵיכְדֵין יֶחְדֵי מֵימְרָא דַיְיָ עֲלֵיכוֹן עַמְמִין נוּכְרָאִין לְהוֹבְדָא יַתְכוֹן וּלְמֵשַׁצְיָא יַתְכוֹן וְתִיתְעַקְרוּן מֵעִילַוֵי אַרְעָא דְאַתּוּן עַלְלִין לְתַמָן לְמֵירְתָהּ\",0,0],[4,142,28,64,\"וִיבַדְרְכוֹן יְיָ בֵּינֵי כָּל עַמְמַיָא מִסְיָיפֵי אַרְעָא וְעַד סְיָיפֵי אַרְעָא וְתֶהֱווֹן מְסַק אַרְנוֹנָא לְפַלְחֵי טַעֲוָותָא דְלָא יְדַעְתּוּן אַתְּ וְאַבְהָתָךְ דְמִן קִיסִין וְאַבְנִין\",0,0],[4,142,28,65,\"וְאִין יִתְפְּלֵג דַעְתְּכוֹן לְמִפְלַח לְטַעֲוַותְהוֹן וְאִיגְרֵי בֵּינֵיכוֹן וּבֵינֵי עַמְמַיָא הָאִינוּן וְלָא תְּנוּחוּן וְלָא יֶהֱוֵי מַנַח לְפִירְסַת רִגְלֵיכוֹן וְיִתֵּן מֵימְרָא דַיְיָ לְכוֹן תַּמָן לִבָּא דַחֲלָא דְמֵחַשְׁכָן עַיְינִין וּמַפְחַת נְפָשׁ\",0,0],[4,142,28,66,\"וִיהוֹן חַיֵיכוֹן תַּלְיַין לְכוֹן מִקְבֵיל וְתֶהֱווֹן דַחֲלִין יֵימָם וְלֵילֵי וְלָא תְהֵימְנוּן בְּחַיֵיכוֹן\",0,0],[4,142,28,67,\"בְּצַפְרָא תֶהֱווֹן אָמְרִין לְוַאי דִיהֵי רַמְשָׁא דְעָקַן מְאַרְכָן שְׁעֵי יוֹמָא בְּאַפֵּיכוֹן וּבְרַמְשָׁא תֶּהֱווֹן אָמְרִין לְוַאי דִיהֵי צַפְרָא דְעָקַן מְאַרְכָן שְׁעֵי לֵילְיָא בְּאַפֵּיכוֹן מִתַּוְוהִית לִבְּכוֹן דְתֶהֱווֹן תַּוָון וּמִן מֵחְמֵי עֵינֵיכוֹן דְאַתּוּן חַמְיָין פּוּרְעֲנוּתָא וְדַחֲלוּן\",0,0],[4,142,28,68,\"וְיַגְלִינְכוֹן מֵימְרָא דַיְיָ לְמִצְרַיִם בְּאִילְפַיָא בְּגוֹ יַמָא דְסוּף בְּאָרְחָא דַעֲבַרְתּוּן וַאֲמָרִית לְכוֹן לָא תֵיסְפוּן תּוּב לְמֶחֱמֵי יָתָהּ וְתִזְדַבְּנוּן תַּמָן בְּשֵׁירוּיָא לְבַעֲלֵי דְבָבֵיכוֹן בְּדָמִין יַקִירִין הֵיךְ מָרֵי אוּמְנָוָון וּמִן בָּתַר כְּדֵין בְּדָמִין זוֹלִין כְּעַבְדִין וְאַמְהָן עַד דְתִיזַלְזְלִין לְמִשְׁתַּעַבְּדָא מַגָן וְלֵית דְמַכְנִישׁ\",0,0],[4,142,28,69,\"אִלֵין פִּתְגָמֵי קְיָימָא דְפַקֵיד יְיָ יַת משֶׁה לְמִגְזוֹר עִם בְּנֵי יִשְרָאֵל בְּאַרְעָא דְמוֹאָב בַּר מִן קַיָמָא דְגָזַר עִמְהוֹן בְּחוֹרֵב\",0,0],[4,142,29,1,\"וּקְרָא משֶׁה לְכָל יִשְרָאֵל וְאָמַר לְהוֹן אַתּוּן חֲמִיתוּן יַת כָּל מַחְוָותָא דְעָבַד מֵימְרָא דַיְיָ לְעֵינֵיכוֹן בְאַרְעָא דְמִצְרַיִם לְפַרְעה וּלְכָל עַבְדוֹי וּלְכָל יַתְבֵי אַרְעֵיהּ\",0,0],[4,142,29,2,\"נִסִין רַבְרְבִין דַחֲמִיתוּן בְּעֵינֵיכוֹן אָתַיָא וְתִמְהַיָא רַבְרְבַיָא הָאִינוּן\",0,0],[4,142,29,3,\"וְלָא יְהַב מֵימְרָא דַיְיָ לְכוֹן לִבָּא לְמִנְשֵׁי אֱלָהֵן לְמִנְדַע וְעַיְינִין לְמִרְמְזָא אֱלָהֵין לְמֶחֱמֵי וְאוּדְנִין לְטַמְטְמָא אֱלָהֵין לְצַיְיתָא וְאַתּוּן נְשִׁיתוּן אוֹרַיְיתָא דְלִבְּכוֹן וּרְמַזְתּוּן בְּעַיְינֵיכוֹן וְטַמְטַמְתּוּן אוּדְנֵיכוֹן בִּזְמַן יוֹמָא הָדֵין\",0,0],[4,142,29,4,\"וַהֲלִיכִית יַתְכוֹן אַרְבְּעִין שְׁנִין בְּמַדְבְּרָא לָא בָלְמוּ כְסוּתְכוֹן מֵעִילַוֵי גוּשְׁמֵיכוֹן וְסַנְדְלֵיכוֹן לָא אִיטָלְעוּ מֵעִילַוֵי רִיגְלֵיכוֹן\",0,0],[4,142,29,5,\"לַחֲמָא דְעִיבּוּרָא לָא אֲכַלְתּוּן וַחֲמַר וּמֵירַת לָא שְׁתִיתוּן וַהֲוַת אוֹרַיְיתָא תְּדִירָא מִסְתְּרָא בְּמֶדְרָשֵׁיכוֹן מְטוֹל דְתִתְעַסְקוּן בָּהּ וְתִנְדְעוּן אֲרוּם אֲנָא הוּא יְיָ אֱלָהָכוֹן\",0,0],[4,142,29,6,\"וְאָתֵיתוּן לְאַתְרָא הָדֵין וּנְפַק סִיחוֹן מַלְכָּא דְחוּשְׁבְּנָא וְעוֹג מַלְכָּא דְמַתְנָן לִקְדָמוּתָנָא לְסִדְרֵי קְרָבָא וּמְחוּנוּן\",0,0],[4,142,29,7,\"וּכְבַשְׁנָן יַת אַרְעֲהוֹן וִיהָבָנָא אַחֲסָנָא לְשֵׁיבַט רְאוּבֵן וּלְשֵׁיבַט גָד וּלְפַלְגוּת שֵׁיבַט מְנַשֶׁה\",0,0],[4,142,29,8,\"וְתִנְטְרוּן יַת פִּתְגָמֵי קְיָימָא הָדָא וְתַעַבְדוּן יַתְהוֹן מִן בִּגְלַל דְתַצְלְחוּן יַת כָּל דְתַעַבְדוּן\",0,0],[4,142,29,9,\"אתם אָמַר משֶׁה נְבִיָא לָא בְטוּמְרָא אֲנָא מַסְהִיד בְּכוֹן אֱלָהֵן כַּד אַתּוּן מְעַתְּדוּן יוֹמָנָא כּוּלְכוֹן קֳדָם יְיָ אֱלָהָכוֹן רֵישֵׁי סַנְהֶדְרִין דִלְכוֹן וַאֲמַרְכְּלֵי שִׁבְטֵיכוֹן סָבֵיכוֹן וְסַרְכֵיכוֹן כָּל אֵינַשׁ יִשְרָאֵל\",0,0],[4,142,29,10,\"טַפְלְכוֹן וּנְשֵׁיכוֹן וְגִיוֹרֵיכוֹן דִי בְּגוֹ מַשִׁירְוַיֵיכוֹן מִקְטוֹעַ קִיסֵיכוֹן עַד מִלוּאֵי מֵימֵיכוֹן\",0,0],[4,142,29,11,\"לְאַעֲלוּתְכוֹן בִּקְיָימָא דַיְיָ אֱלָהָכוֹן וּלְאַזְהְרוֹתְכוֹן בְּמוֹמָתֵיהּ דַיְיָ אֱלָהָכוֹן גְזַר עִמְכוֹן יוֹמָנָא\",0,0],[4,142,29,12,\"מִן בִּגְלַל לְקַיָימָא יַתְכוֹן יוֹמָנָא לֵיהּ לְאוּמָא בְּרִירָא וְהוּא יֶהֱוֵי לְכוֹן לֶאֱלָהָא הֵיכְמָא דְמַלֵיל לְכוֹן וְהֵיכְמָא דְקַיֵים לְאַבְהַתְכוֹן לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקב\",0,0],[4,142,29,13,\"וְלָא עִמְכוֹן בִּלְחוֹדֵיכוֹן אֲנָא גְזַר יַת קְיָימָא הָדָא וּמַסְהִיד יַת מוֹמָתָא הָדָא\",0,0],[4,142,29,14,\"אֲרוּם יַת כָּל דָרַיָא דְקָמוּן מִן יוֹמֵי עַלְמָא כֻּלְהוֹן הִנוּן דְקַיְימִין הָכָא עִמָנָא יוֹמָנָא קֳדָם יְיָ אֱלָהָנָא וְיַת כָּל דָרַיָא דַעֲתִידִין לְמֵיקוּם עַד סוֹף כָּל עַלְמָא כּוּלְהוֹן הִינוּן קַיְימִין הָכָא עִמָן יוֹמָנָא\",0,0],[4,142,29,15,\"אֲרוּם אַתּוּן יְדַעְתּוּן סְכוּם שְׁנַיָא דְיָתִיבְנָא בְּאַרְעָא דְמִצְרַיִם וּגְבוּרָן דְעָבַד לָנָא בֵּינֵי עַמְמַיָא דַעֲבַרְתּוּן\",0,0],[4,142,29,16,\"וְחָמִתּוּן יַת מְרַחְקַתְהוֹן וְיַת טַעֲוָון דִלְהוֹן דְמִן קֵיסָא וְאַבְנָא דְרַמְיָין בְּאוֹשְׁקְקֵי וְטַעֲוָון דִכְסַף וּדְהַב דִיהִיבִין עִמְהוֹן בְּבָתַּיָא אַחֲדִין דָמִין בַּתְרֵיהוֹן דְלָא יִתְגַנְבוּן\",0,0],[4,142,29,17,\"אִזְדַהֲרוּן דִלְמָא אִית בְּכוֹן הַשְׁתָּא וְלָא יֶהֱוֵי בָּתַר דְנָא בַּר נַשׁ אוֹ אִיתָא אוֹ גְנִיסָא אוֹ שִׁיבְטָא דְלִבֵּיהּ מִתְפְּנֵי לְמִטְעֵי יוֹמָנָא מִדַחַלְתָּא דַיְיָ אֱלָהָנָא לְמִפְלַח יַת טַעֲוַות עַמְמַיָא הָאִינוּן דִלְמָא אִית בְּכוֹן טְעוּ דְשָׁרִישׁ דְלִבֵּיהּ מְהַרְהַר עֲלוֹי בָּתַר חִיטָאֵיהּ דְשֵׁירוֹי חִיטָאֵיהּ חוֹלִי וְסוֹפֵיהּ מְרִיר כְּאַגְרָנַיָא דְמוֹתָא\",0,0],[4,142,29,18,\"וִיהֵי בְּמִשְׁמְעֵיהּ יַת פִּתְגָמֵי מוֹמָתָא הָדָא וְיִתְיָיאֵשׁ בְּלִבֵּיהּ לְמֵימָר שְׁלָמָא יְהֵא לִי אֲרוּם בִּתְקוֹף יִצְרָא בִישָׁא דְלִבִּי אֵיזִיל מִן בִּגְלַל לְמוֹסְפָא חוֹבֵי שָׁלוּתָא עַל זְדוֹנוֹתָא\",0,0],[4,142,29,19,\"לָא יְהֵי רַעֲוָא מִן קֳדָם יְיָ לְמִשְׁבַּק לֵיהּ אֲרוּם בְּכֵן יִתְקוֹף רוּגְזָא דַיְיָ וְחֵימְתֵיהּ בְּבַר נְשָׁא הַהוּא וְתָחֵיל בֵּיהּ כָּל פִּתְגָמֵי לְוָוטַיָא דִכְתִיבִין בְּסִפְרָא הָדֵין וְיִמְחֵי יְיָ יַת שׁוּם דוּכְרָנֵיהּ מִתְּחוֹת שְׁמַיָא\",0,0],[4,142,29,20,\"וְיַפְרִישִׁינֵיהּ יְיָ לְבִישָׁא מִכָּל שִׁבְטַיָא דְיִשְרָאֵל הֵי כְּכָל לְוָוטֵי קְיָימָא דִכְתִיבִין בְּסִפְרָא הָדֵין\",0,0],[4,142,29,21,\"וְיֵימְרוּן דָרַיָא בַּתְרָאֵי בְּנֵיכוֹן דִי יְקוּמוּן מִן בַּתְרֵיכוֹן וּבַר עַמְמֵי דְיֵיתֵי מֵאַרַע רְחִיקָא וְיֶחְמוּן יַת מַחֲוָותָא דְאַרְעָא הַהִיא וְיַת מַרְעָהָא דְגָרֵי יְיָ בָּהּ\",0,0],[4,142,29,22,\"כּוּבְרֵיתָא וּמִלְחָא עִם אֵשָׁא מְצַלְהֲבָא תְּהֵי יָקְדָא כָּל אַרְעָא לָא תִתְכַּשַׁר לְבַר זְרַע וְלָא תַרְבֵּי צְמָחִין וְלָא יִסַק בָּהּ כָּל עִשְבָּא תִּשְׁתְּקַע הֵיךְ תְּהַפְכָנוּתָא דִסְדוֹם וַעֲמוֹרָא אַדְמָה וּצְבוֹיִים דְהָפַךְ מֵימְרָא דַיְיָ בְּרוּגְזֵיהּ וּבִכְלִיתֵיהּ\",0,0],[4,142,29,23,\"וְיֵימְרוּן כָּל עַמְמַיָא מְטוּל מַה עָבַד יְיָ הֵיכְנָא לְאַרְעָא הָדָא מַה הֲוָה תְּקוֹף רוּגְזָא רַבָּא הָדֵין\",0,0],[4,142,29,24,\"וְיֵימְרוּן מְטוּל דִשְׁבָקוּ יַת קְיָימָא דַיְיָ אֱלָהָא דְאַבְהַתְהוֹן דְגָזַר עִמְהוֹן בְּאַפְקוּתֵיהּ יַתְהוֹן מֵאַרְעָא דְמִצְרָיִם\",0,0],[4,142,29,25,\"וַאֲזָלוּ בָּתַר יִצְרָא בִּישָׁא וּפְלָחוּ לְטַעֲוַות עַמְמַיָא וְסַגִידוּ לְהוֹן דַחֲלָן דְלָא יַדְעִינוּן וְלָא אִתְפַלְגוּן לְהוֹן\",0,0],[4,142,29,26,\"וּתְקֵיף רוּגְזָא דַיְיָ בְּאַרְעָא הַהִיא לְאַיְתַיָא עֲלָהּ יַת כָּל לְוָוטַיָא דִכְתִיבִין בְּסִפְרָא הָדֵין\",0,0],[4,142,29,27,\"וְטַלְטְלִינוּן יְיָ מֵעִלַוֵי אַרְעֲהוֹן בִּרְגוֹז וּבִכְלוּ וּבִתְקוֹף רַב וְטַלְקִינוּן בְּגָלוּתָא לְאַרַע חוֹרַן כִּזְמַן יוֹמָא הָדֵין\",0,0],[4,142,29,28,\"טְמִירְתָּא גַלְיַין קֳדָם יְיָ אֱלָהָנָא וְהוּא יִפְרַע מִנְהוֹן וְגַלְיָיתָא יִתְמַסְרָן לָנָא וְלִבְנָנָא עַד עַלְמָא לְמֶעֱבַד לְהוֹן דִינָא מְטוּל לְקַיָימָא יַת כָּל פִּתְגָמֵי אוֹרַיְיתָא הָדָא\",0,0],[4,142,30,1,\"וִיהֵי כַד יֵיתוּן עִילַוֵיכוֹן יַת כָּל פִּתְגָמַיָא הָאִילֵן בִּירְכַן וְחִילוּפֵהוֹן דְסַדָרִית קֳדָמֵיכוֹן וְתֵיתְבוּן עַל לִבְּכוֹן לְמֵיתַב לְפוּלְחָנִי בְּכָל גַלְוַות עַמְמַיָא דְאַגְלֵי יַתְכוֹן יְיָ לְתַמָן\",0,0],[4,142,30,2,\"טוּבֵיכוֹן דְצַדִיקַיָא מָרֵי תְּתוּבָא דְכַד תְּחוֹבוּן וּתְתוּבוּן מַטְיָא תְּיוּבְתְּכוֹן עַד כּוּרְסֵי יְקָרָא דַיְיָ אֱלָהָכוֹן אִין תְּקַבְּלוּן לְמֵימְרֵיהּ כְּכָל מַה דַאֲנָא מְפַקֵיד לְכוֹן יוֹמָנָא אַתּוּן וּבְנֵיכוֹן בְּכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן\",0,0],[4,142,30,3,\"וִיקַבֵּיל מֵימְרֵיהּ בְּרַעֲוָא יַת תְּיוּבְתְּכוֹן וִירַחֵם עֲלֵיכוֹן וִיתוּב וְיִכְנוֹשׁ יַתְכוֹן מִכָּל עַמְמַיָא דְבַדַר יְיָ אֱלָהָכוֹן יַתְכוֹן לְתַמָן\",0,0],[4,142,30,4,\"אִין יְהוֹן מְבַדְרֵיכוֹן בִּסְיָפֵי שְׁמַיָא מִתַּמָן יִכְנוֹשׁ יַתְכוֹן מֵימְרָא דַיְיָ אֱלָהָכוֹן עַל יְדוֹי דְאֵלִיָהוּ כַּהֲנָא רַבָּא וּמִתַּמָן יְקָרֵב יַתְכוֹן עַל יְדוֹי דְמַלְכָּא מְשִׁיחָא\",0,0],[4,142,30,5,\"וְיָעֵלִינְכוֹן מֵימְרָא דַיְיָ אֱלָהָכוֹן לְאַרְעָא דְיָרִיתוּ אַבְהַתְכוֹן וְתֵרְתָהּ וְיוֹטֵב לְכוֹן וְיַסְגִינְכוֹן יַתִּיר מִן אַבְהַתְכוֹן\",0,0],[4,142,30,6,\"וְיַעֲדֵי יְיָ אֱלָהָכוֹן יַת טִפְּשׁוּת לִבְּכוֹן וְיַת טִפְּשׁוּת לִבָּא דִבְנֵיכוֹן אֲרוּם יְבַטֵל יִצְרָא בִּישָׁא מִן עַלְמָא וְיִבְרֵי יִצְרָא טָבָא דִי יַמְלְכִינְכוֹן לְמִירְחַם יַת יְיָ אֱלָהָכוֹן בְּכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן מִן בִּגְלַל דְיוֹגְדוּן חַיֵיכוֹן עַד עַלְמִין\",0,0],[4,142,30,7,\"וְיִגְרֵי מֵימְרָא דַיְיָ אֱלָהָכוֹן יַת לְוָוטַיָא הָאִלֵין עַל בַּעֲלֵי דְבָבֵיכוֹן דְאָעִיקוּ יַתְכוֹן בְּגַלְוַותְכוֹן וְעַל סַנְאֵיכוֹן דְרָדָפוּ מִן בַּתְרֵיכוֹן עַד דִי אָנְסוּ יַתְכוֹן\",0,0],[4,142,30,8,\"וְאַתּוּן תְּתוּבוּן וּתְקַבְּלוּן לְמֵימְרָא דַיְיָ וְתַעַבְדוּן יַת כָּל פִּקוּדוֹי דַאֲנָא מְפַקֵיד לְכוֹן יוֹמָנָא\",0,0],[4,142,30,9,\"וִישַׁיְירִינְכוֹן יְיָ אֱלָהָכוֹן לְטָבָא דְתַצְלְחוּן בְּכָל עוֹבָדֵי יְדֵיכוֹן בְּוַולְדָא דִמְעֵיכוֹן וּבְוַולְדָא דִבְעִירְכוֹן וּבְפֵירֵי אַרְעֲכוֹן לְטָבָא אֲרוּם יְתוּב מֵימְרָא דַיְיָ לְמֵיחֲדֵי אַמְטוּלְכוֹן לְאוֹטָבָא לְכוֹן הֵיכְמָא דְחָדֵי עַל אַבְהַתְכוֹן\",0,0],[4,142,30,10,\"אֲרוּם תְּקַבְּלוּן לְמֵימְרָא דַיְיָ אֱלָהָכוֹן לְמִינְטַר פִּקוּדוֹי וּקְיָימוֹי דִכְתִיבִין בְּסֵפֶר אוֹרַיְיתָא הָדֵין אֲרוּם תְּתוּבוּן לִדְחַלְתָּא דַיְיָ אֱלָהָכוֹן בְּכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן\",0,0],[4,142,30,11,\"אֲרוּם תַּפְקֵידְתָּא הָדָא דַאֲנָא מְפַקֵיד לְכוֹן יוֹמָנָא לָא מְכַסְיָא הִיא מִנְכוֹן וְלָא רְחִיקָא הִיא\",0,0],[4,142,30,12,\"לָא בִשְׁמַיָא הִיא לְמֵימָר מַן יִסוֹק בְּדִילָנָא בִּשְׁמַיָא וְיִסְבִינָהּ לָנָא וְיַשְׁמַע יָתָהּ לָנָא וְנַעַבְדִינָהּ\",0,0],[4,142,30,13,\"וְלָא מִן הַאָל לְעִיבַר יַמָא רַבָּא הִיא לְמֵימָר מַאן יְעִיבַר בְּדִילָנָא לְעִיבַר יַמָא רַבָּא וְיִסְבִינָהּ לָנָא וְיַשְׁמַע יָתָהּ לָן וְנַעַבְדִינָהּ\",0,0],[4,142,30,14,\"אֲרוּם קָרִיב לְכוֹן פִּתְגָמָא בְּבֵית מֶדְרָשֵׁיכוֹן פְּתָחוּ פֻּמְכוֹן לְמֶהֱוֵי הַגְיַין בְּהוֹן בְּרֵירוּ לִבְּכוֹן לְמֶעֱבַד יַתְהוֹן\",0,0],[4,142,30,15,\"חָמוּן דִי סַדָרִית קֳדָמֵיכוֹן יוֹמָנָא יַת אָרְחָא דְחַיֵי דְבֵיהּ מִשְׁתְּלַם אֲגַר טַב לְצַדִיקַיָא וְיַת אָרְחָא דְמוֹתָא דְבֵיהּ מִשְׁתְּלַם אֲגַר בִּישׁ לְרַשִׁיעַיָא\",0,0],[4,142,30,16,\"דַאֲנָא מְפַקֵיד לְכוֹן יוֹמָנָא לְמִרְחַם יַת יְיָ אֱלָהָךְ וְלִמְהַךְ בְּאוֹרְחַן דְתַקְנָן קֳדָמוֹי וּלְמִנְטַר פִּקוּדוֹי וּקְיָימוֹי וְדִינוֹי וְתֵיחוּן וְתִסְגוּן וִיבָרֵכִינְכוֹן יְיָ אֱלָהָךְ בְּאַרְעָא דְאַתּוּן עָלְלִין לְתַמָן לְמֵירְתָהּ\",0,0],[4,142,30,17,\"וְאִין יְהַרְהַר לִבְּכוֹן וְלָא תְקַבְּלוּן וְתִטְעוּן וְתִסְגְדוּן לְטַעֲוַות עַמְמַיָא וְתִפְלְחוּנוּן\",0,0],[4,142,30,18,\"חֲוֵיתִי לְכוֹן יוֹמָנָא אֲרוּם מֵיבַד תֵּיבְדוּן וְלָא תֵגְדוֹן יוֹמִין עַל אַרְעָא דְאַתּוּן עָבְרִין יַת יוֹרְדְנָא לְמֵיעַל לְתַמָן לְמֵירְתָהּ\",0,0],[4,142,30,19,\"לָא סַהֲדִין דְעָבְרִין מִן עַלְמָא אֲנָא מַסְהִיד בְּכוֹן יוֹמָנָא אֱלָהֵן שְׁמַיָא וְאַרְעָא חַיֵי וּמוֹתָא סַדָרִית קוּמֵיכוֹן בִּרְכָתָא וְחִילוּפָהּ וּתְתֵירְעוּן בְּאָרְחָא דְחַיֵי הִיא אוֹרַיְיתָא מִן בִּגְלַל דְתֵיחוּן בְּחַיֵי עַלְמָא דְאָתֵי אַתּוּן וּבְנֵיכוֹן\",0,0],[4,142,30,20,\"לְמִירְחַם יַת יְיָ אֱלָהָכוֹן לְקַבָּלָא לְמֵימְרֵיהּ וּלְמִקְרַב לִדְחַלְתֵּיהּ אֲרוּם אוֹרַיְיתָא דְאַתּוּן עֲסִיקִין בָּהּ הִיא חַיֵיכוֹן בְּעַלְמָא הָדֵין וְאוֹגְדוּת יוֹמֵיכוֹן בְּעַלְמָא דְאָתֵי וְתִתְכַּנְשׁוּן בְּסוֹף גַלְוָותָא וְתֵיתְבוּן עַל אַרְעָא דְקַיֵים יְיָ לְאַבְהַתְכוֹן לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקב לְמִתַּן לְהוֹן\",0,0],[4,142,31,1,\"וילך וַאֲזַל משֶׁה לְמַשְׁכַּן בֵּית אוּלְפָנָא וּמַלֵיל יַת פִּתְגָמַיָא הָאִלֵין עִם כָּל יִשְרָאֵל\",0,0],[4,142,31,2,\"וַאֲמַר לְהוֹן בַּר מְאָה וְעֶשְרִין שְׁנִין אֲנָא יוֹמָנָא לֵית אֲנָא יָכִיל תּוּב לְמִפַּק וּלְמֵיעַל וּמֵימְרָא דַיְיָ אֲמַר לִי לָא תְעִיבַר יַת יוֹרְדְנָא הָדֵין\",0,0],[4,142,31,3,\"יְיָ אֱלָהָכוֹן וּשְׁכִינְתֵּיהּ עָבִיר קֳדָמֵיכוֹן הוּא יְשֵׁיצֵי יַת עַמְמַיָא הָאִלֵין וְתֵירְתִינוּן יְהוֹשֻׁעַ הוּא יְטַיֵיל קֳדָמֵיכוֹן הֵיכְמָא דְמַלֵיל יְיָ\",0,0],[4,142,31,4,\"וְיַעֲבֵיד יְיָ פּוּרְעָנוּת דִינָא מִנְהוֹן הֵיכְמָא דְעָבַד לְסִיחוֹן וּלְעוֹג מַלְכֵי אֱמוֹרָאֵי וּלְעַמְמֵי אַרְעֲהוֹן דְשֵׁיצֵי יַתְהוֹן\",0,0],[4,142,31,5,\"וְיִמְסְרִינוּן מֵימְרָא דַיְיָ קֳדָמֵיכוֹן וְתַעַבְדוּן לְהוֹן הֵי כְּכָל תַּפְקֵידְתָּא דְפַקֵידִית יַתְכוֹן\",0,0],[4,142,31,6,\"אִיתוֹקְפוּ וְאִתְחַיְילוּ לָא תִדַחֲלוּן וְלָא תִתְיַרְעוּן מִן קֳדָמֵיהוֹן אֲרוּם יְיָ אֱלָהָכוֹן שְׁכִינְתֵּיהּ מִידַבְּרָא קֳדָמֵיכוֹן לָא יִשְׁבְּקִינְכוֹן וְלָא יַרְחְקִינְכוֹן\",0,0],[4,142,31,7,\"וּקְרָא משֶׁה לִיהוֹשֻׁעַ מִן גוֹ עַמָא וַאֲמַר לֵיהּ לְמֵיחֲמֵיהוֹן דְכָל יִשְרָאֵל אִיתוֹקַף וְאִתְחַיָיל אֲרוּם אַנְתְּ מִתְמַנֵי לְמֵיעוּל עִם עַמָא הָדֵין לְאַרְעָא דְקַיֵים מֵימְרָא דַיְיָ לְאַבְהַתְהוֹן לְמִתַּן לְהוֹן וְאַנְתְּ תַּפְלִיג יָתֵיהּ לְהוֹן\",0,0],[4,142,31,8,\"וּמֵימְרָא דַיְיָ שְׁכִינְתֵּיהּ מִידַבְּרָא קֳדָמָךְ וּמֵימְרֵיהּ יְהֵי בְסַעֲדָךְ לָא יִשְׁבְּקִינָךְ וְלָא יַרְחֲקִינָךְ לָא תִדְחַל וְלָא תִתְיָרַע\",0,0],[4,142,31,9,\"וּכְתַב משֶׁה יַת אוֹרַיְיתָא הָדָא וּמְסָרָהּ לְכַהֲנַיָא בְּנֵי לֵוִי דְנַטְלִין יַת אֲרוֹן קְיָימָא דַיְיָ וּלְכָל חַכִּימֵי יִשְרָאֵל\",0,0],[4,142,31,10,\"וּפַקֵיד משֶׁה יַתְהוֹן לְמֵימָר בְּסוֹף שְׁבַע שְׁנִין בְּאִשׁוֹנֵי שַׁתָּא דִשְׁמִיטָתָא בְּחַגָא דִמְטָלַיָא\",0,0],[4,142,31,11,\"בְּמֵיתֵי כָּל יִשְרָאֵל לְאִתְחַמָאָה קֳדָם יְיָ אֱלָהָכוֹן בְּאַתְרָא דְיִתְרְעֵי תִּיקְרוּן יַת אוֹרַיְיתָא הָדָא קֳבֵיל כָּל יִשְרָאֵל בְּמִשְׁמְעֲהוֹן\",0,0],[4,142,31,12,\"כְּנוּשׁוּ יַת עַמָא גוּבְרַיָא לְמֵילַף וּנְשַׁיָא לְמִשְׁמַע אוּלְפָנָא וְטַפְלַיָא לְקִיבּוּלֵי עֲלֵיהוֹן אַגְרָא דְמַיְיתִין יַתְהוֹן וְגִיוֹרַיָא דִבְקִירְוֵיכוֹן דְיֶחֱמוּן אִיקַר אוֹרַיְיתָא וִידַחֲלוּן כֻּלְהוֹן מִן קֳדָם מֵימְרָא דַיְיָ אֱלָהָכוֹן וְיִטְרוּן לְמֶעֱבַד יַת כָּל פִּתְגָמֵי אוֹרַיְיתָא הָדָא\",0,0],[4,142,31,13,\"וּבְנֵיהוֹן דְלָא יָדְעוּ יִשְׁמְעוּן וְיִלְפוּן לְמִדְחַל מִן קֳדָם יְיָ אֱלָהָכוֹן כָּל יוֹמַיָא דְאַתּוּן קַיָימִין עַל אַרְעָא דְאַתּוּן עָבְרִין יַת יוֹרְדְנָא תַּמָן לְמֵירְתָהּ\",0,0],[4,142,31,14,\"תְּלָתָא צַדִיקַיָא אִתְאַמָרַת קְרֵיבוּתָא בְּמִיתַתְהוֹן מְטוֹל דְלָא מָטוּ לְיוֹמֵי אַבְהַתְהוֹן וְכָל חַד וְחַד מַנֵי פַּרְנָסָא בְּיוֹמֵיהּ יַעֲקב אָבוּנָן וְדָוִד מַלְכָּא וּמשֶׁה נְבִיָא דְהָכִין כְּתִיב וַאֲמַר יְיָ לְמשֶׁה הָא קְרִיבַן יוֹמָךְ לִמְמַת קְרֵי יַת יְהוֹשֻׁעַ וְתִתְעַתְּדוּן בְּמַשְׁכַּן זִמְנָא וְאַפְקְדִינֵיהּ וַאֲזַל משֶׁה וִיהוֹשֻׁעַ וְאִתְעַתָּדוּ בְּמַשְׁכַּן זִמְנָא\",0,0],[4,142,31,15,\"וְאִתְגְלֵי אִיקַר שְׁכִינְתָּא דַיְיָ בְּמַשְׁכְּנָא בְּעַמוּדָא דַעֲנָנָא וְקָם עַמוּדָא דַעֲנָנָא עַל תְּרַע מַשְׁכְּנָא וּמשֶׁה וִיהוֹשֻׁעַ קָמוֹן מִן לְבַר\",0,0],[4,142,31,16,\"וַאֲמַר יְיָ לְמשֶׁה הָא אַנְתְּ שְׁכִיב בְּעַפְרָא עִם אַבְהָתָךְ וְנִשְׁמָתָךְ תֶּהֱוֵי גְנִיזָא בִּגְנִיז חַיֵי עַלְמָא עִם אַבְהָתָךְ וִיקוּמוּן רַשִׁיעֵי עַמָא הָדֵין וְיִטְעוּן בָּתַר טַעֲוַות עַמְמַיָא דְהִינוּן עַלְלִין תַּמָן בֵּינֵיהוֹן וְיִשְׁבְּקוּן דַחַלְתִּי וְיִשְׁנוּן יַת קְיָימַי דִי גְזָרִית עִמְהוֹן\",0,0],[4,142,31,17,\"וְיִתְקוֹף רוּגְזִי בְּהוֹן בְּיוֹמָא הַהוּא וְאַרְחִיקִינוּן וַאֲסַלֵק שְׁכִינְתִּי מִנְהוֹן וִיהוֹן לְבִיזָא וִיאַרְעָן יַתְהוֹן בִּישָׁן סַגִיאִין וְעָקָן וְיֵימְרוּן בְּעִידָנָא הַהִיא בִּשְׁבוּעָא מְטוֹל דְלֵית שְׁכִינַת אֱלָהַי שַׁרְיָא בְּמִצְעִי אִירְעוּנִי בִּישָׁתָא הָאִלֵין\",0,0],[4,142,31,18,\"וַאֲנָא מְסַלְקָא אֲסַלֵק שְׁכִינְתִּי מִנְהוֹן בְּעִידָנָא הַהִיא עַד דְיִתְמַקְמְקוּן וִיקַבְּלוּן פּוּרְעָנוּת חוֹבֵיהוֹן עַל כָּל בִּישָׁתָא דְעָבָדוּ אֲרוּם אִתְפְּנִיוּ בָּתַר טַעֲוַות עַמְמַיָא\",0,0],[4,142,31,19,\"וּכְדוֹן כְּתִיבוּ לְכוֹן יַת תּוּשְׁבַּחְתָּא הֲדָא וְאַלְפָהּ יַת בְּנֵי יִשְרָאֵל שַׁוְויָהּ בְּפוּמְהוֹן בְּדִיל דְתֵהֵי תּוּשְׁבַּחְתָּא הֲדָא קֳדָמוֹי לְסָהִיד בִּבְנֵי יִשְרָאֵל\",0,0],[4,142,31,20,\"אֲרוּם אֵיעֲלִינוּן לְאַרְעָא דְקַיֵימִית לְאַבְהַתְהוֹן עַבְדָא חֲלַב וּדְבַשׁ וְיֵיכְלוּן וְיִשְבְּעוּן וִידַהֲנוּן וְיִתְפְּנוּן לְטַעֲוַות עַמְמַיָא וְיִפְלְחוּנוּן וְיִרְגְזוּן קָדָמַי וְיִשְׁנוּן יַת קְיָימִי\",0,0],[4,142,31,21,\"וִיהֵי אֲרוּם יְעַרְעָן יַתְהוֹן בִּישַׁן סַגִיאָן וְעָקָן וְתַסְהִיד תּוּשְׁבַּחְתָּא הֲדָא קֳדָמֵיהוֹן לְסַהֲדוּ אֲרוּם גְלֵי קֳדָמַי דְלָא תִתְנְשֵׁי מִפּוּם בְּנֵיהוֹן אֲרוּם גְלֵי קֳדָמַי יַת יִצְרֵהוֹן בִּישָׁא דְאִינוּן עַבְדִין יוֹמָנָא עַד לָא אַעֲלֵיכוֹן לְאַרְעָא דְקַיֵימִית\",0,0],[4,142,31,22,\"וּכְתַב משֶׁה יַת תּוּשְׁבַּחְתָּא הֲדָא וְאַלְפָהּ יַת בְּנֵי יִשְרָאֵל\",0,0],[4,142,31,23,\"וּפַקֵיד יַת יְהוֹשׁוּעַ בַּר נוּן וַאֲמַר אִיתוֹקַף וְאִתְחַיֵיל אֲרוּם אַנְתְּ תָּעֵיל יַת בְּנֵי יִשְרָאֵל לְאַרְעָא דְקַיֵימִית לְהוֹן וּמֵימְרִי יְהֵי בְּסַעֲדָךְ\",0,0],[4,142,31,24,\"וַהֲוָה כְּמִפְסַק משֶׁה לְמִכְתּוֹב יַת פִּתְגָמֵי אוֹרַיְיתָא הֲדָא עַל גְוִוילָא עַד דִי אַשְׁלִימוּנוּן\",0,0],[4,142,31,25,\"וּפַקֵיד משֶׁה יַת לֵיוָאֵי נַטְלֵי אֲרוֹן קְיָימָא דַיְיָ לְמֵימָר\",0,0],[4,142,31,26,\"סָבוּ יַת סִפְרָא דְאוֹרַיְיתָא הָדָא וּתְשַׁווּן יָתֵיהּ בְּקוּפְסָא מִן צְטַר יְמִינָא דַאֲרוֹן קְיָימָא דַיְיָ אֱלָהָכוֹן וִיהֵי תַּמָן בְּכוֹן לְסָהִיד\",0,0],[4,142,31,27,\"אֲרוּם גְלֵי קֳדָמַי יַת סוּרְהַבְנוּתְכוֹן וְיַת קְדַלְכוֹן קַשְׁיָא הָא עַד זְמַן דַאֲנָא בְּחַיִים בֵּינֵיכוֹן יוֹמָא דֵין מְסַרְהֲבִין הֲוֵיתוּן קֳדָם יְיָ וְאוּף כָּל דְכֵן בָּתַר דְאֵימוּת\",0,0],[4,142,31,28,\"כְּנוּשׁוּ לְוָותִי יַת כָּל חַכִּימֵי שִׁבְטֵיכוֹן וְסַרְכֵיכוֹן וַאֲמַלֵיל בְּמִשְׁמְעֵהוֹן יַת כָּל פִּתְגָמַיָא הָאִילֵין וְאַסְהִיד בְּהוֹן יַת שְׁמַיָא וְיַת אַרְעָא\",0,0],[4,142,31,29,\"אֲרוּם חַכִּימַת דְמִן בָּתַר דְאֵמוּת אֲרוּם חַבָּלָא תְחַבְּלוּן עוֹבָדֵיכוֹן וְתִטְעוּן מִן אָרְחָא דְפַקֵידִית יַתְכוֹן וְתֶאֱרַע יַתְכוֹן בִּישְׁתָּא בְּסוֹף כָּל יוֹמַיָא אֲרוּם תַּעַבְדוּן דְבִישׁ קֳדָם יְיָ לְאַרְגָזָא קֳדָמוֹי\",0,0],[4,142,31,30,\"וּמַלֵיל משֶׁה בְּמִשְׁמַע כָּל קְהָלָא דְיִשְרָאֵל יַת כָּל פִּתְגָמֵי שִׁבְחָא הָדָא עַד דִי שְׁלִימוּ\",0,0],[4,142,32,1,\"האזינו וַהֲוָה דִי מָטָא קִיצֵיהּ דְמשֶׁה נְבִיָא לְמִתְכַּנְשָׁא מִגוֹ עַלְמָא אָמַר בְּלִבֵּיהּ לֵיתָנָא מַסְהִיד בְּעַמָא הָדֵין סַהֲדִין דְטַעֲמִין מִיתוּתָא בְּעַלְמָא הָדֵין הָאֲנָא מַסְהִיד בְּהוֹן סַהֲדִין דְלָא טַעֲמִין מִיתוּתָא בְּעַלְמָא הָדֵין בְּרַם סוֹפֵיהוֹן לְאִתְחַדְתָּא לְעַלְמָא דְאָתֵי יְשַׁעְיָה נְבִיָא כַּד הֲוָה מִתְנַבֵּי בִּכְנִישַׁתְהוֹן דְיִשְרָאֵל יְהַב שְׁמִיעָא לִשְׁמַיָא וְצַיְיתָא לְאַרְעָא מִן בִּגְלַל דַהֲוָה קָרִיב לְאַרְעָא וְרָחִיק מִן שְׁמַיָא בְּרַם משֶׁה נְבִיָא כַּד הֲוָה מִתְנַבֵּי בִּכְנִישַׁתְהוֹן דְיִשְרָאֵל יְהַב שְׁמִיעָא לְאַרְעָא וְצַיְיתָא לִשְׁמַיָא מִן בִּגְלַל דַהֲוָה קָרִיב לִשְׁמַיָא וְרָחִיק מִן אַרְעָא דְהָכִין כְּתִיב אַצִיתוּ שְׁמַיָא וַאֲמַלֵיל וְתִשְׁמַע אַרְעָא מַמְלַל פֻּמִי\",0,0],[4,142,32,2,\"יִנְקוֹף עַל מְרוֹדַיָא הֵיךְ מִטְרָא סַפְּחָא אוּלְפָנִי וְתִתְקַבֵּל בְּרַעֲוָא עַל מְקַבְּלֵי אוּלְפָנָא הֵיךְ טַלָא מְמַלְלֵי דִילִי כִּרְבִיעִית רוּחֵי מִיטְרָא דְמִינַתְבִין עַל דִתְאִין בְּיֶרַח מַרְחֶשְׁוָון וְכַרְסִיסִין לְקוֹשִׁין דִמְרַוִוין צִמְחוֹנֵי אַרְעָא בְּיַרְחָא דְנִיסָן\",0,0],[4,142,32,3,\"וַוי לְהוֹן לְרַשִׁיעַיָא דִמְדַכְרִין שְׁמָא קַדִישָׁא בְּגִידוּפִין אֲרוּם משֶׁה דַהֲוָה רַבְּהוֹן דְיִשְרָאֵל לָא הֲוָה אֶפְשַׁר לֵיהּ לְמִדְכַּר יַת שְׁמָא קַדִישָׁא עַד דַהֲוָה מְחַנִיךְ פּוּמֵיהּ בְּרֵישׁ שִׁירָתָא בִּתְמַנְיָין וְחַמְשָׁא אָתִין דְהִינוּן עַשְרִין וְחַד מִלִין וּמִן בָּתַר כְּדֵין אָמַר אֲרוּם בִּשְׁמָא דַיְיָ אֲנָא מְצַלֵי וְאַתּוּן עַמָא בֵּית יִשְרָאֵל הָבוּ אִיקַר וּרְבוּתָא קֳדָם אֱלָהָנָא\",0,0],[4,142,32,4,\"אָמַר משֶׁה נְבִיָא כַּד סְלֵיקַת לְטַוְורָא דְסִינַי חָמִית רִבּוֹן כָּל עָלְמַיָא יְיָ מְרַבַּע יוֹמָא לְאַרְבָּעָא חוּלְקִין תְּלַת שָׁעִין עָסִיק בְּאוֹרַיְיתָא וּתְלַת עָסִיק בְּדִינָא וּתְלַת מְכַרְזֵג בֵּין גְבַר לְאִיתָא וּגְזַר לִמְרוֹמָם וּמָאִיךְ וּתְלַת מְפַרְנֵס כָּל בִּרְיָיתָא דְהָכִין כְּתִיב תַּקִיף דְשַׁלְמִין עוֹבָדוֹי אֲרוּם כָּל אָרְחָתוֹי דִינָא אֱלָהָא מְהֵימְנָא דְמִן קֳדָמוֹי עַוְלָא לָא נָפִיק דְזַכַּאי וְקָשִׁיט הוּא\",0,0],[4,142,32,5,\"חַבִּילוּ עוֹבָדֵיהוֹן טַבְיָא בְּנַיָא חֲבִיבַיָא אִשְׁתַּכַּח מוּמָא בְּהוֹן דָרָא עוּקְמָנָא דְאַשְׁנִייוּ עוֹבָדֵיהוֹן וְאוּף סֵדֶר דִינֵיהּ דְעַלְמָא אִשְׁתַּנֵי עֲלֵיהוֹן\",0,0],[4,142,32,6,\"הַאֶפְשַׁר דִלְשׁוּם מֵימְרָא דַיְיָ אַתּוּן גָמְלִין דָא עַמָא דְהַווֹן טִפְּשִׁין וְקַבִּילוּ אוֹרַיְיתָא וְלָא חַכִּימוּ הֲלָא הוּא אֲבוּכוֹן דִי קְנָא יַתְכוֹן הוּא בְּרָא יַתְכוֹן וְשַׁכְלֵיל יַתְכוֹן\",0,0],[4,142,32,7,\"אִידְכָּרוּ מִן יוֹמַת עַלְמָא אִתְבּוֹנְנוּ בִּשְׁנַתְהוֹן דְכָל דָר וְדָר קְרוֹן בְּסִפְרֵי אוֹרַיְיתָא וְיִתְנוּן לְכוֹן וּבְסִפְרֵי נְבִיָא וְיֵימְרוּן לְכוֹן\",0,0],[4,142,32,8,\"בְּאַחְסָנוּת עִלָאָה עַלְמָא לְעַמְמַיָא דִי נְפָקוּ מִבְּנוֹי דְנׂחַ בְּאַפְרָשׁוּתֵיהּ מִכְתָּבִין וְלִישְׁנִין לִבְנֵי נְשָׁא בְּדָרָא דְפַלְגוּתָא בֵּי הוּא זִמְנָא רָמָא פִיצְתָא עִם שׁוּבְעִין מַלְאָכַיָא רַבְרְבֵי עַמְמִין דְאִתְגְלֵי עִמְהוֹן לְמֶחֱמֵי קַרְתָּא וּבֵי הוּא זִמְנָא אָקִים תְּחוּמֵי אוּמַיָא כִּסְכוּם מִנְיַין שׁוּבְעִין נַפְשָׁתָא דְיִשְרָאֵל דִנְחָתוּ לְמִצְרַיִם\",0,0],[4,142,32,9,\"וְכֵיוַן דְנָפַל עַמָא קַדִישָׁא בְּפִיצְתָא דְמָארֵי עַלְמָא פָּתַח מִיכָאֵל פּוּמֵיהּ וַאֲמַר אֲרוּם חוּלַק טָב דְשׁוּם מֵימְרָא דַיְיָ עַמֵיהּ פָּתַח גַבְרִיאֵל פּוּמֵיהּ בְּתוּשְׁבְּחָא וַאֲמַר דְבֵית יַעֲקׂב עֲדַב אַחְסַנְתֵּיהּ\",0,0],[4,142,32,10,\"אֲרַע יַתְהוֹן שַׁרְיָין בְּמַדְבְּרָא בִּצְדִיוּת אֲתַר דִמְיַלְלִין שֵׁידִין וִידוּרִין וּבֵית צָחוֹתָא אָגִין עֲלֵיהוֹן שִׁבְעָתֵי עֲנָנֵי אִיקְרֵיהּ אַלֵיפִינוּן יַת אוֹרַיְיתֵיהּ נַטְרִינוּן הֵיכְמָא דִשְׁכִינָא נַטְרָא בְבֵי רְעִיוֹנֵיהּ\",0,0],[4,142,32,11,\"הֵיךְ נִישְׁרָא דִמְעוֹרֵר וּמֵחִישׁ לְשַׁרְכַפְתֵּיהּ וְעַל חָסִילוֹי מְחוֹפֵף כְּדֵין שְׁכִינְתֵּיהּ מְעוֹרֵר לְמַשִׁירְיַתְהוֹן דְיִשְרָאֵל וְחָפָא עֲלֵיהוֹן טוֹל שְׁכִינְתֵּיהּ וְהֵיכְמָא דְנִישְׁרָא פָּרִיס גַדְפוֹי עַל בְּנוֹי וְטָעִין יַתְהוֹן וְסָבִיל יַתְהוֹן עַל אֵיבָרוֹי כְּדֵין טַעֲנִינוּן וְסַבְלִינוּן וְאַשְׁרִינוּן עַל תְּקוֹף כָּרְכֵי אַרְעָא דְיִשְרָאֵל\",0,0],[4,142,32,12,\"מֵימְרָא דַיְיָ בִּלְחוֹדֵיהוֹן יַשְׁרִינוּן בְּאַרְעֲהוֹן וְלָא מַשְׁרֵי בֵּינֵיהוֹן פַּלְחֵי פּוּלְחָנָא נוּכְרָאָה\",0,0],[4,142,32,13,\"אַשְׁרִינוּן עַל כַּרְכֵי אַרְעָא דְיִשְרָאֵל וְאַיְיכוֹל יַתְהוֹן תַּפְנוּקֵי עַלְלַת חַקְלָאָה וְאוֹנִיק יַתְהוֹן דוּבְשָׁא מִפֵּירָהָא דְמִתְרַבְיָין עַל כֵּיפִין וּמִשְׁחָא מִזֵיתָהָא וּמְלַבְלְבִין מִטִנְרִין תַּקִיפִין\",0,0],[4,142,32,14,\"יְהַב לְהוֹן לְוָואִי שְׁמֵינֵי תוֹרִין מִן בִּיזַת מַלְכֵיהוֹן וְחֶלְבָּא מִבַּכִּירֵי עַנִין מִן עָדֵי שִׁלְטוֹנֵיהוֹן עִם טוּב פְּטִימִין וְדִכְרִין בְּנֵי דְעָנִין שְׁמֵנִין מִמַתְנָן וְגַדָאִין אָמַר משֶׁה נְבִיָא אִין נַטְרִין הִינוּן עַמָא בֵּית יִשְרָאֵל מִצְוָותָא דְאוֹרַיְיתָא אִתְאַמַר עָלַי בִּנְבוּאָה דִיְהֶוְיָן גַרְגִרֵי חִיטֵיהוֹן הֵיךְ כּוּלְיַין דְתוֹרֵי וַחֲמַר סוּמַק מִן עִנְבָא חָד מַפְקִין כּוֹר חָד\",0,0],[4,142,32,15,\"וְעַתָּרוּ בֵּית יִשְרָאֵל וּפָחֲזוּ אַצְלָחוּ תְּקוֹף קָנִין נִכְסִין וּשְׁבָקוּ פּוּלְחַן אֱלָהָא דִבְרָא יַתְהוֹן וְאַרְגִיזוּ קֳדָם תַּקִיפָא דְפַרְקִינוּן\",0,0],[4,142,32,16,\"קָנוֹן יָתֵיהּ בְּפוּלְחָנָא נוּכְרַיָא בְּמַרְחַקַתְהוֹן אַרְגִיזוּ קֳדָמוֹי\",0,0],[4,142,32,17,\"יְדַבְּחוּן לְטַעֲווֹת דִמְתִילִין לְשֵׁידִין דְלֵית בְּהוֹן מִדַעַם דִצְרִיךְ טַעֲוָון דְלָא יַדְעוּנוּן דַחֲלָן חֲדַתַּן דִמִזְמַן קָרִיב אִתְעֲבִידוּ וְלָא אִתְעַסְקוּ בְּהוֹן אַבְהַתְכוֹן\",0,0],[4,142,32,18,\"דַחֲלַת תַּקִיפָא דִבְרָא יַתְכוֹן אִתְנַשְׁתּוּן וְאַנְשֵׁיתוּן מֵימַר אֱלָהָא דְעָבַד יַתְכוֹן מְחִילִין מְחִילִין\",0,0],[4,142,32,19,\"וּגְלֵי קֳדָם יְיָ וַהֲוָה רְגַז מִן קֳדָמוֹי מִן דְאַרְגִיזוּ קֳדָמוֹי בְּנַיָא חֲבִיבַיָא דְאִתְקְרוּן עַל שְׁמֵיהּ בְּנִין וּבְנָן\",0,0],[4,142,32,20,\"וַאֲמַר מְפַלְגָא אִיפְלִיג אַפֵּי רְעוּתִי מִנְהוֹן נֶחְמֵי מַה יֶהֱוַון בְּסוֹפֵיהוֹן אֲרוּם דַר דְהַפְכִינָן הִינוּן בְּנִין דְלֵית בְּהוֹן הֵימְנוּתָא\",0,0],[4,142,32,21,\"הִינוּן אַקְנוּן קֳדָמוֹי בִּדְלָא אֱלָהָא אַרְגִיזוּ קֳדָמוֹי בְּהַבְלֵיהוֹן וַאֲנָא אַקְנִינוּן בְּאוּמָא דְלָא אוּמָא בְּבַּבְלָאֵי עַמָא טַפְּשָׁא נִרְגוֹז יַתְהוֹן\",0,0],[4,142,32,22,\"אֲרוּם קִידוֹם תַּקִיף כְּאֵישָׁא נְפַק מִן קֳדָמַי וּבְעָרַת בִּתְקוֹף רוּגְזִי וְאַיְקִידַת עַד שְׁיוֹל אַרְעַיָא וּסְיָיפַת אַרְעָא וַעֲלַלְתָּהּ וְשַׁלְהוֹבַת יְסוֹדֵי טַוְורַיָא\",0,0],[4,142,32,23,\"וְכַד הִינוּן יְהִיבִין בְּבָבֶל הִינוּן פְּלָחִין לְטַעֲוַותְהוֹן בְּגִין כֵּן אֲמָרִית בְּמֵימְרִי לִמְכַנְשָׁא עֲלֵיהוֹן בִּישְׁתָּא גִירֵי מְחַת פּוּרְעָנוּתִי אֲשֵׁיצֵי בְּהוֹן\",0,0],[4,142,32,24,\"אַגְלֵי יַתְהוֹן בְּמָדַי וּבְעֵלָם מִגוֹ שִׁבְיַת בָּבֶל אָעִיקוּ לְהוֹן דְבֵית אֲגַג דִי מְתִילִין לְשֵׁידִין מְנַפְחֵי כְפָן וּלְמַזִיקֵי אֲכִילֵי עוֹף וְלִבְנֵי טִהֲרִירֵי כְּתִישֵׁי רוּחִין בִּישִׁין וְלִילִין וּמְרַוְוחֵי רְוָוחִין בִּישִׁין וְעַכּוּ\\\"ם דִנְכִיתִין בְשִׁינֵיהוֹן הֵיךְ חֵיוַות בְּרָא אִיגְרֵי בְּהוֹן וַאֲטַלְטְלִינוּן בְּיַד אֲרַמָאֵי דְמַלְיָין אֲרִיסַן כְּחֵיוִין חוֹרְמָנַיָא זוֹחֲלוֹי דְעַפְרָא\",0,0],[4,142,32,25,\"עַמָא דְגָלוּ מִבָּרָא לְאַרְעָא דְיִשְרָאֵל תַּתְכֵּיל יַתְהוֹן מָחַת חַרְבָּא וּדְמִשְׁתַּיְירִין בְּאַרְעָא דְיִשְרָאֵל בְּגוֹ קִיטוֹנֵי מִדַמִיכֵיהוֹן אִיגְרֵי בְּהוֹן חַרְגַת מוֹתָא אֵילֵךְ וְאֵילֵךְ יִשְׁתֵּיצוּן לְחוֹד עוֹלֵימֵיהוֹן וּלְחוֹד בְּתוּלַתְהוֹן יְנִיקַתְהוֹן עִם גוּבְרֵיהוֹן וְסָבֵיהוֹן\",0,0],[4,142,32,26,\"אֲמָרִית בְּמֵימְרִי לְמֵיכְלֵי מִנְהוֹן רוּחַ קוּדְשִׁי אֲשַׁיֵיר בְּהוֹן קָלִיל כִּגְבַר דְחָצִיד חַקְלֵיהּ וּמְשַׁיֵיר אַרְעָא חֲדָא אַבְטוֹל מִסְפָּר יֵיחוּס אֱנוֹשׁ דוּכְרָנֵהוֹן\",0,0],[4,142,32,27,\"אִלוּלָפוֹן רוּגְזָא דְסַנָאָה דְחִיל דִלְמָא יִתְרַבְרְבוּן לְקִיבְלֵי מְעִיקֵיהוֹן דִלְמָא יֵימְרוּן יְדֵינָן מִתְפַּרְעוּן לָן מִבַּעֲלֵי דְבָבֵינָן וְלָא מִן קֳדָם יְיָ אִתְגַזָרַת כָּל דָא\",0,0],[4,142,32,28,\"אֲרוּם אוּמָא מְאַבְּדָן עֵיטִין טָבָן הִנוּן וְלֵית בְּהוֹן סוּכְלְתָנוּ\",0,0],[4,142,32,29,\"אִלוּ הֲווֹ חַכִּימִין הֲווֹן מִסְתַּכְּלִין בְּאוֹרַיְיתָא וְהִינוּן מִתְבּוֹנְנִין מַה יְהֵי עָתִיד לְמֶהֱוֵי בְּסוֹפֵיהוֹן\",0,0],[4,142,32,30,\"הֵיכְדֵין יְהֵי סַנְאָה חַד רָדִיף אֶלֶף מִנְהוֹן וּתְרֵין יְעִירְקוּן לְרִבּוּתָא מִנְהוֹן אֱלָהֵן מְטוֹל דְתַקִיפְהוֹן מְסָרִינוּן וַיְיָ אַשְׁלֵימִינוּן\",0,0],[4,142,32,31,\"אֲרוּם לָא כְתַקִיפְהוֹן דְיִשְרָאֵל טַעֲוַותְהוֹן דְעַמְמַיָא אֲרוּם תַּקִיפֵהוֹן דְיִשְרָאֵל כַּד יְחוֹבוּן מַיְיתִי עֲלֵיהוֹן פּוּרְעֲנוּתָא וְכַד פַּרְסִין יְדֵיהוֹן בִּצְלוֹ עָנֵי וּמְשֵׁזִיב יַתְהוֹן אֲבָל טַעֲוַותְהוֹן דְעַמְמַיָא עַכּוּ\\\"ם לֵית בְּהוֹן צְרוֹךְ וְעַל דִי אַרְגִיזְנָן קֳדָמוֹי וְלָא הֲדַרְנָן לְפוּלְחָנֵיהּ אִתְעֲבִידוּ בַּעֲלֵי דְבָבֵינָן סַהֲדֵינָן וְדַיָינֵינָן\",0,0],[4,142,32,32,\"אֲרוּם עוֹבָדֵיהוֹן דְעַמָא הָאִלֵין דַמְיָין לְעוֹבָדֵי עַמָא דִסְדוֹם וַעֲצַתְהוֹן בִּישִׁין כְּעֵיצַתְהוֹן דְעַם עֲמוֹרָה מַחֲשַׁבְתְּהוֹן בִּישִׁין כְּרֵישֵׁי חִיוְנַיָא חוּרְמְנַיָא בְּגִין כֵּן תְּהוֹן תּוּשְׁלָמוּתְהוֹן מְתַכְלִן וּמְמַרְרִין לְהוֹן\",0,0],[4,142,32,33,\"הֵי כִּמְרִירַתְהוֹן דְתַנִינַיָא כַּד הִינוּן הֲווֹן מִן חֲמָרֵהוֹן בְּגִין כֵּן יְהֵי מָרִיר כַּס דִלְוַוט דְיִשְׁתּוּן בְּיוֹם פּוּרְעֲנוּתְהוֹן וְהֵיךְ רֵישֵׁי פִּיתוּנַיָא הֵיכְדֵין אִינוּן אַכְזְרָאִין\",0,0],[4,142,32,34,\"הֲלָא עוֹבָדֵיהוֹן דְאִנוּן עַבְדִין בְּטוּמְרָא קֳדָמַי כּוּלְהוֹן גַלְיָין חֲתִימִין וּמְתַקְנֵי בְּאַפּוֹתִיקַיֵי\",0,0],[4,142,32,35,\"קֳדָמַי פּוּרְעֲנוּתָא וַאֲנָא אַשְׁלִים לְעִדָן דְתִימוֹט רַגְלֵיהוֹן לְגָלוּתָא אֲרוּם קָרִיב לְמֵיתֵי יוֹם תְּבַרְהוֹן וּמִבְעָא בִּישָׁתָא דִמְעַתְּדָא לְהוֹן\",0,0],[4,142,32,36,\"אֲרוּם דָאִין מֵימְרָא דַיְיָ בִּרְחָמוֹן דִינָא דְעַמֵיהּ יִשְרָאֵל וְעַל בִּישָׁתָא דִגְזַר עַל עַבְדוֹהִי יְהֵי תָּהָן קֳדָמוֹי אֲרוּם גְלֵי קֳדָמוֹי דִבְעִידָן דִיחוֹבוּן וְתִתְקַף עֲלֵיהוֹן מָחַת סַנָאָה וְתִתְנַטֵל סָעִיד מִידֵיהוֹן וִיהוֹן פַּסְקִין מְהֵימְנַיָא מִדֵי עוֹבְדִין טָבִין וִיהוֹן מִיטַלְטְלִין וּשְׁבִיקִין\",0,0],[4,142,32,37,\"וְיֵימַר סַנְאָה הָאן הוּא דַחַלְתְּהוֹן דְיִשְרָאֵל תַּקִיפָא דִרְחִיצוּ בֵיהּ\",0,0],[4,142,32,38,\"דִתְרֵיב נִכְסַתְהוֹן הֲווֹן אָכְלִין שָׁתָן חֲמַר נִיסוּכֵיהוֹן יְקוּמוּן כְּדוֹן וִיסַעֲדוּנְכוֹן יְהֵי עֲלֵיכוֹן מֵגִין בְּמֵימְרֵיהּ\",0,0],[4,142,32,39,\"כַּד יִתְגְלֵי מֵימְרָא דַיְיָ לְמִפְרוֹק יַת עַמֵיהּ יֵימַר לְכָל עַמְמַיָא חֲמוֹן כְּדוֹן אֲרוּם אֲנָא הוּא דַהֲוֵויתִי וַהֲוִית וַאֲנָא הוּא דְעָתִיד לְמֶהֱוֵי וְלֵית אֱלָהָא חוֹרַן בַּר מִינִי אֲנָא בְּמֵימְרִי מֵמִית וּמָחֵי מָחִיתִי יַת עַמָא בֵּית יִשְרָאֵל וַאֲנָא אָסֵי יַתְהוֹן בְּסוֹף יוֹמַיָא וְלֵית דִמְשֵׁזִיב מִן יְדַי גוֹג וּמַשִׁרְיָיתֵיהּ לִמְסַדְרָא סִדְרֵי קְרָבָא עִמְהוֹן\",0,0],[4,142,32,40,\"אֲרוּם זְקָפִית בִּשְׁבוּעָה יַת יְדַי בִּשְׁמַיָא וַאֲמָרִית הֵיכְמָא דַאֲנָא קַיָים הֵיכְדֵין לָא אַבְטִיל שְׁבוּעָתִי לְעַלְמִין\",0,0],[4,142,32,41,\"אִין שְׁנִינָא הִיא בְּרַק סַיְיפִי וְתִתְקֵיף בְּדִינָא יְדַי אַחֲזוֹר פּוּרְעֲנוּתָא לִמְעִיקֵי עַמִי וּלְסַנְאֵיהוֹן אַשְׁלִים אֲגַר עוֹבָדֵיהוֹן בִּישַׁיָא\",0,0],[4,142,32,42,\"אֵירַוֵי גִירְרַי מִן אֲדַם קְטוֹלֵיהוֹן וּסְיָיפַי תִגְמוֹר בִּשְרֵיהוֹן מִדַם קְטִילִין וְשִׁיבִין מִשֵׁירוֹי פּוּרְעָנוּת סַנְאֵיהוֹן דְעַמִי\",0,0],[4,142,32,43,\"שַׁבְּחוּ אוּמַיָא עַמֵיהּ בֵּית יִשְרָאֵל אֲרוּם אֲדַם עַבְדוֹי דְאִשְׁתַּיְדֵי הוּא פָּרְעוּ נְטַר וּנְקָמָה דְפוּרְעָנוּתָא יַחֲזוֹר עַל בַּעֲלֵי דְבָבוֹי וְהוּא בְּמֵימְרֵיהּ יְכַפֵּר עַל אַנְפֵּי אַרְעֵיהּ וְעַמֵיהּ\",0,0],[4,142,32,44,\"וְאָתָא משֶׁה מִן מַשְׁכַּן בֵּית אוּלְפָנָא וּמַלֵיל יַת כָּל פִּתְגָמֵי תּוּשְׁבַּחְתָּא הֲדָא בְּמִשְׁמָעֵיהוֹן דְעַמָא הוּא וְהוֹשֵׁעַ בַּר נוּן\",0,0],[4,142,32,45,\"וּפְסַק משֶׁה מִן לְמַלָלָא יַת כָּל דְבִירַיָא הָאִלֵין עִם כָּל יִשְרָאֵל\",0,0],[4,142,32,46,\"וַאֲמַר לְהוֹן שַׁווּן לִבְּכוֹן לְכָל פִּתְגָמַיָא דַאֲנָא מַסְהִיד בְּכוֹן יוֹמָנָא דְתַפְקְדוּנוּן יַת בְּנֵיכוֹן מְטוֹל לְמִינְטוֹר וּלְמֶעֱבַד יַת כָּל פִּתְגָמֵי אוֹרַיְיתָא הָדָא\",0,0],[4,142,32,47,\"אֲרוּם לֵית פִּתְגָם רֵיקָם בְּאוֹרַיְיתָא אֱלָהֵן לִדְעַבְרִין עֲלָהּ אֲרוּם הוּא חַיֵיכוֹן וּבְפִתְגָמֵי הָדֵין תּוֹרְכוּן יוֹמִין עַל אַרְעָא דְאַתּוּן עָבְרִין יַת יוֹרְדְנָא תַמָן לְמֵירְתָהּ\",0,0],[4,142,32,48,\"וּמַלֵיל יְיָ עִם משֶׁה בְּשַׁבְעָא בְּיַרְחָא דְאָדָר בִּכְרַן יוֹמָא הָדֵין לְמֵימָר\",0,0],[4,142,32,49,\"וַהֲוָה כֵיוַן דַאֲמַר לֵיהּ מֵימְרָא דַיְיָ סוּק לְטַוָור עִבְרָאֵי הָדֵין טַוְורָא דִנְבוֹ חָשֵׁב בְּלִבֵּיהּ וַאֲמַר דִלְמָא דַמְיָיא מְסוּקְתָא דָא לִמְסוּקְתָא דְטַוְורָא דְסִינַי אָמַר אִיזֵל וְאִיקְדֵישׁ יַת עַמָא אָמַר לֵיהּ מֵימְרָא דַיְיָ לָא כָּל הֵיאֵךְ אֱלָהֵן סוֹק וַחֲמֵי יַת אַרְעָא דִכְנָעַן דַאֲנָא יָהֵיב לִבְנֵי יִשְרָאֵל לְאַחְסָנָא\",0,0],[4,142,32,50,\"וּשְׁכוֹב בְּטַוְורָא דְאַנְתְּ סָלֵיק לְתַמָן וְאִתְכְּנֵשׁ לְעַמָךְ אוּף אַנְתְּ הֵיכְמָא דְשָׁכַב אַהֲרן אָחוּךְ בְּטַוְורוֹס אוּמָנוֹס וְאִתְכְּנַשׁ לְעַמֵיהּ מִן יַד פָּתַח משֶׁה פּוּמֵיהּ בִּצְלוֹתָא וְכֵן אָמַר רִבּוֹנֵיהּ דְעַלְמָא בְּבָעוּ מִנָךְ לָא אֱהִי מְתִיל כְּבַר נַשׁ דַהֲוָה לֵיהּ בִּיר יְחִידָאֵי וְאִשְׁתְּבֵי אָזַל פַּרְקֵיהּ בְּמָמוֹן סַגִי אַלְפֵיהּ חָכְמָתָא וְאוּמָנוּתָא קַדִישׁ לֵיהּ אִיתָא נְצִיב אַבְוַורְנְקִי דְמַלְכַיָא בְּנָא לֵיהּ בֵּית חֲתָנוּתָא אַתְקִין לֵיהּ פּוּרְיָינָא וְקָטַר לֵיהּ גְנָנָא בְּגַוֵיהּ זַמִין לֵיהּ שׁוּשְׁבִינֵי אַפָא פִּתֵּיהּ נְכַס נִיכְסֵיהּ מְזַג חַמְרֵיהּ כֵּיוַון דְמָטָא לְמֶחֱדֵי בְּרֵיהּ עִם אִנְתְּתֵיהּ וּבָעוּ שׁוּשְׁבִינֵי לְמִכְרַךְ רִפְתָּא אִתְּבַע הַהוּא בַּר נַשׁ לְבֵי דִינָא קַמֵי מַלְכָּא וְאִתְקְנֵס דִין קְטוֹל וְלָא דָלוּ מִנֵיהּ עַד דְחָמֵי בְּחֶדְוָות בְּרֵיהּ הֵיכְדֵין אֲנָא טְרָחִית בְּעַמָא הָדֵין אַפִּיקִית יַתְהוֹן בְּמֵימְרָךְ מִמִצְרַיִם אַלִיפִית יַתְהוֹן אוֹרַיְיתָךְ בָּנִיתִי לְהוֹן מַשְׁכְּנָא לִשְׁמָךְ וְכַד מָטָא זִמְנָא לְמֵיעֲבַר יַת יוֹרְדְנָא לְמֵירוֹת יַת אַרְעָא אֲנָא מִתְקְנַס לִמְמַת אִי נִיחָא לְקַמָךְ דַלֵי מִנִי וְאֶעֱבוֹר יַת יוֹרְדְנָא וְאֶחֱמֵי בְּטוּבָתָא דְיִשְרָאֵל וּמִבָּתַר כְּדֵין אֵימוּת\",0,0],[4,142,32,51,\"אָתִיב לֵיהּ מָרֵי עַלְמָא וְכֵן אָמַר מִן בִּגְלַל דְשַׁקַרְתּוּן בְּמֵימְרִי בִּמְצַע בְּנֵי יִשְרָאֵל בְּמוֹי מַצוֹת רְקַם מַדְבְּרָא דְצִין מְטוֹל דְלָא קַדִישְׁתּוּן יָתִי בִּמְצַע בְּנֵי יִשְרָאֵל\",0,0],[4,142,32,52,\"אֲרוּם מִקָבֵיל תֶּחֱמֵי יַת אַרְעָא וְתַמָן לָא תֵיעוּל לְאַרְעָא דַאֲנָא יָהִיב לִבְנֵי יִשְרָאֵל\",0,0],[4,142,33,1,\"וזאת וְדָא סֵדֶר בִּרְכָתָא דִבְרִיךְ משֶׁה נְבִיָא דַיְיָ יַת בְּנֵי יִשְרָאֵל קֳדָם דִימוּת\",0,0],[4,142,33,2,\"וַאֲמַר יְיָ מִן סִינַי אִתְגְלֵי לְמִתַּן אוֹרַיְיתָא לְעַמֵיהּ בֵּית יִשְרָאֵל וּדְנַח זִיו אִיקַר שְׁכִינְתֵּיהּ מִגַבְלָא לְמִיתְּנָהּ לִבְנוֹי דְעֵשָו וְלָא קַבִּילוּ יָתָהּ הוֹפַע בְּהַדְרַת אִיקַר מִטַוְורָא דְפָארָן לְמִיתְנָהּ לִבְנוֹי דְיִשְׁמָעֵאל וְלָא קַבִּילוּ יָתָהּ הֲדַר וְאִתְגְלֵי בִּקְדוּשָׁא עַל עַמֵיהּ בֵּית יִשְרָאֵל וְעִמֵיהּ רִיבַן רִיבְווָן מַלְאָכִין קַדִישִׁין כְּתַב יְמִינֵיהּ וְאוֹרַיְיתָא מִגוֹ שַׁלְהוֹבִית אֵישָׁתָא פִּקוּדַיָא יְהַב לְהוֹן\",0,0],[4,142,33,3,\"אוּף כָּל מַה דְאוֹדָאָה לְעַמְמַיָא מְטוֹל לִמְחַבְבָא עַמֵיהּ בֵּית יִשְרָאֵל כֻּלְהוֹן קָרָא לְהוֹן קַדִישִׁין לְמֵקוּם בַּאֲתַר בֵּית שְׁכִינְתֵּיהּ וְכַד הִנוּן נַטְרִין מִצְוָותָא דְאוֹרַיְיתָא מְדַבְּרִין לְרֶגֶל עֲנָנֵי יְקָרָךְ נַיְיחִין וְשַׁרְיַין כְּמִין פִּסָא דְבַר\",0,0],[4,142,33,4,\"אָמְרִין בְּנֵי יִשְרָאֵל אוֹרַיְיתָא פַּקֵיד לָנָא משֶׁה יְהָבָהּ יַרְתוּ לִקְהַל שִׁבְטַיָא דְיַעֲקב\",0,0],[4,142,33,5,\"וְהוּא הֲוָה מַלְכָּא בְּיִשְרָאֵל בְּאִתְכַּנָשׁוּת רֵישֵׁי עַמָא כַּחֲדָא מִשְׁתַּמְעִין לֵיהּ שִׁבְטַיָא דְיִשְרָאֵל\",0,0],[4,142,33,6,\"יֵיחֵי רְאוּבֵן בְּעַלְמָא הָדֵין וְלָא יֵימוּת בְּמִיתוּתָא דְמַיְיתִין בָּהּ רַשִׁיעַיָא לְעַלְמָא דְאָתֵי וִיהֵי עוּלֵימוֹי מִתְמַנְיָין עִם עוּלֵימֵיהוֹן דְאָחוֹי בֵּית יִשְרָאֵל\",0,0],[4,142,33,7,\"וְדָא בִּירְכָתָא לְשִׁבְטָא דִיהוּדָה וְזַוֵג בְּחוּלְקֵיהּ וּבְבִירְכָתֵיהּ לְשִׁמְעוֹן אָחוֹי וְכֵן אָמַר קַבֵּל יְיָ צְלוֹתֵיהּ דִיהוּדָה בְּמִפְקֵיהּ לְסִדְרֵי קְרָבָא וּלְוַות עַמֵיהּ תַּעֲלִינֵיהּ מִסִדְרֵי קְרָבָא בִּשְׁלָם יְדוֹי יִתְפַּרְעַן לֵיהּ מִן בַּעֲלֵי דְבָבוֹי וּסְעִיד וּסְמִיךְ מִסַנְאוֹי תֶּהֱוֵי לֵיהּ\",0,0],[4,142,33,8,\"וּלְשֵׁיבַט לֵוִי בְּרִיךְ משֶׁה נְבִיָא וַאֲמַר תּוּמַיָא וְאוּרַיָא אַלְבֵּישְׁתָּא לְאַהֲרן גְבַר דְאִשְׁתַּכַּח חָסִיד קֳדָמָךְ דִנְסֵית יָתֵיהּ בְּנִיסְתָא וַהֲוָה שְׁלִים בְּדַקְתֵּיהּ בְּמוֹי מַצוֹת רְקָם וְאִשְׁתַּכַּח מְהֵימָן\",0,0],[4,142,33,9,\"נַפְקִין שֵׁיבַט לֵוִי לְפוּלְחַן מַשְׁכַּן זִמְנָא וּמִתְפַּרְשִׁין מִן מַשְׁכְּנֵיהוֹן אָמְרִין לַאֲבוּהוֹן וּלְאִימַתְהוֹן לָא חַמִיתִינוּן וְיַת אֲחוּהוֹן דְלָא בְּנֵי תְּלָתִין שְׁנִין לָא אִשְׁתְּמוֹדְעוּן יַתְהוֹן וְיַת בְּנֵיהוֹן לָא יָדְעִין מְטוֹל דְקַיְימִין עַשְרִין שְׁנִין בְּמַטַרְתְּהוֹן בְּמֵימְרָךְ וּקְיַים פּוּלְחַן קוּדְשָׁךְ נַטְרִין\",0,0],[4,142,33,10,\"כַּשְׁרִין אִינוּן לְמַלְפָא סִידְרֵי דִינָךְ לִדְבֵית יַעֲקב וְאוֹרַיְיתָךְ לִדְבֵית יִשְרָאֵל יְשַׁווּן אֲחוּהוֹן כַּהֲנַיָא קְטוֹרֶת בּוּסְמִין עַל מַחְתַּיָא וְיֵיכְלוּן מִיתָנָא בְּיוֹם רוּגְזָךְ וְקָרְבַּן גְמִיר לְרַעֲוָא עַל גַּבֵּי מַדְבְּחָךְ\",0,0],[4,142,33,11,\"בְּרִיךְ יְיָ נִכְסוֹי דְבֵית לֵוִי דְיַהֲבִין מַעַשְרָא מִן מַעַשְרָא וְקָרְבַּן יְדוֹי דְאֵלִיָהוּ כַּהֲנָא דִמְקָרֵב בְּטַוְורָא כַּרְמְלָא תְּקַבֵּל בְּרַעֲוָא תְּבִיר חַרְצָא דְאַחְאָב סַנְאֵיהּ וּפוּרְקַת נְבִיֵי שִׁקְרָא דְקַיְימִין לְקוּבְלֵיהּ וְלָא יְהֵי לְסַנָאוֹי דְיוֹחָנָן כַּהֲנָא רַבָּא רֶגֶל לְמֵיקוּם\",0,0],[4,142,33,12,\"לְשִׁבְטָא דְבִנְיָמִין בְּרִיךְ משֶׁה נְבִיָא וַאֲמַר חֲבִיבֵיהּ דַיְיָ יִשְׁרֵי לְרוֹחֲצָן עֲלוֹי יְהֵי מֵגִין עֲלוֹי כָּל יוֹמַיָא וּבְגוֹ תְּחוּמֵיהּ שְׁכִינְתֵּיהּ שַׁרְיָא\",0,0],[4,142,33,13,\"וּלְשֵׁיבַט יוֹסֵף בְּרִיךְ משֶׁה נְבִיָא דַיְיָ וַאֲמַר בְּרִיכָא תֶהֱוֵי מִן קֳדָם יְיָ אַרְעֵיהּ דְיוֹסֵף מִטוּב שְׁמַיָא תְּהֵי עַבְדָא מַגְדִין מִטַלָא וּמִטְרָא דְנַחְתִין מִן לְעֵיל וּמִן טוּב מַבּוּעֵי תְהוֹמָא דְסַלְקִין וְנַגְדִין וּמְרַוִין צִמְחַיָא מִלְרַע\",0,0],[4,142,33,14,\"וּמִטוּב מַגְדִין וְעַלְלִין דִמְבַשְׁלָא אַרְעֵיהּ מִן יְבוּל שִׁמְשָׁא וּמִן טוּב בּוּכְרֵי פֵּירֵי אִילָנַיָא דִמְבַכְּרָא אַרְעֵיהּ בְּכָל רֵישׁ יֶרַח וְיֶרַח\",0,0],[4,142,33,15,\"וּמִטוּב רֵישֵׁי טַוְורָא בְּכִירְתָא דְאוֹרִיתוּ לֵיהּ בִּרְכָתָא אַבְהָתָא דְמִן שֵׁרוּיָא דִמְתִילִין לְטַוְורַיָא וּמִן טוּב רָמָתָא דְלָא מְפַסְקָן עֲלָלַיָא דְאַחְסִינוּ לֵיהּ בִרְכָתָא אַמְהָתָא דְמִן עַלְמָא דִמְתִילִין לִגְלִימָתָא\",0,0],[4,142,33,16,\"וּמִטוּב שְׁבַח פֵּירֵי אַרְעָא וּמַלְיָהּ רְעֵי לֵיהּ אֱלָהָא דְאִתְגְלֵי בְּאִיקַר שְׁכִינְתֵּיהּ עַל משֶׁה בִּסְנַיָא יִתְכַּנְשָׁן כֻּלְהוֹן בִּרְכָתָא אִלֵין וְיִתְעַבְדָן כְּלִיל דִרְבוּ לְרֵישֵׁיהּ דְיוֹסֵף וּלְקָדְקָדֵיהּ דְגַבְרָא דַהֲוָה רַב וְשַׁלִיט בְּאַרְעָא דְמִצְרַיִם וַהֲוָה זָהִיר בְּאִיקְרָא דְאָחוֹי\",0,0],[4,142,33,17,\"בְּכוֹרוֹתָא הֲוָת חַמְיָא לִרְאוּבֵן וְאִתְנְטִילַת וְהִינוּן רִבְוָותָא דִקְטוֹל יְהוֹשֻׁעַ בַּר נוּן בְּגִילְגְלָא דְהוּא מִדְבֵית אֶפְרַיִם וְהִנוּן אַלְפַיָא דִקְטוֹל גִדְעוֹן בַּר יוֹאָשׁ בִּמְדִינָאֵי דְהוּא מִדְבֵית מְנַשֶׁה\",0,0],[4,142,33,18,\"וּלְשֵׁיבַט זְבוּלוּן בְּרִיךְ משֶׁה נְבִיָא דַיְיָ וַאֲמַר חֲדוֹן דְבֵית זְבוּלוּן בְּמִפַקְכוֹן לִפְרַקְמַטְיֵכוֹן וּדְבֵית יִשָשׁכָר בְּמוֹשְׁכְּנֵי בָּתֵּי מֶדְרָשֵׁיכוֹן\",0,0],[4,142,33,19,\"אוּמִין סַגִיעִין לְטַוָור בֵּית מַקְדְשָׁא יִצְלוּן תַּמָן יִקְרְבוּן קוּרְבָּנִין דִקְשׁוֹט אֲרוּם עַל סְפַר יַמָא רַבָּא שָׁרָן וְיִתְפַּרְנְקוּן מִן טָרִיתָא וְחַלְזוֹנָא יְאַחְדוּן וְיִצְבְּעוּן מֵאַדְמֵיהּ תִּיכְלָא לְחוּטֵי גוּלְיַתְהוֹן וּמִן חָלָא מַפְקִין אִסְפַּקְלְרִין וּמָנֵי זְגוּגִיתָא אֲרוּם גְנִיזַיָא דִתְהוֹמַיָא גַלְיָין לְהוֹן\",0,0],[4,142,33,20,\"וּלְשִׁבְטָא דְגָד בְּרִיךְ משֶׁה נְבִיָא דַיְיָ וַאֲמַר בְּרִיךְ דְאַפְתֵּי תְחוּמֵיהּ דְגָד נְיָיח כְּאַרְיָא לְמֵישְׁרֵיהּ וְכַד נְפִיק לְסִדְרֵי קְרָבָא קֳבֵל בַּעֲלֵי דְבָבוֹי מִקְטַל מַלְכִין עִם שִׁלְטוֹנִין וּקְטוּלוֹי חַכִּימִין מִן כָּל קָטוֹלַיָא דְמִגְרַר אֶדְרְעָא עִם קוֹדְקְדָא\",0,0],[4,142,33,21,\"וַחֲמָא אַרְעָא טַבְתָּא וְקַבֵּיל חוּלְקֵיהּ בְּשֵׁירוּיָא אֲרוּם תַּמָן אֲתַר מִקְבַּע אַבְנִין טָבִין וּמַרְגַלְיָין דְבֵיהּ משֶׁה סַפְרֵיהוֹן דְיִשְרָאֵל גְנִיז וְהֵיכְמָא דַהֲוָה עָלֵיל וְנָפִיק בְּרֵישׁ עַמָא בְּעַלְמָא הָדֵין הֵיכְדֵין יְהֵי עָלֵיל וְנָפִיק בְּעַלְמָא דְאָתֵי מְטוֹל דְזַכְוָון קֳדָם יְיָ עָבַד וְסִידְרֵי דִינוֹי אַלִיף לְעַמֵיהּ בֵּית יִשְרָאֵל\",0,0],[4,142,33,22,\"וּלְשִׁבְטָא דְדָן בְּרִיךְ משֶׁה נְבִיָא דַיְיָ וַאֲמַר שִׁבְטָא דְדָן מְדַמֵי לְגוּר בַּר אַרְיְוָון אַרְעֵיהּ שַׁתְיָא מִנַחֲלַיָא דְנַגְדִין מִן מַתְנָן וּתְחוּמֵיהּ יְהֵי מָטֵי עַד בּוּתְנַיֵי\",0,0],[4,142,33,23,\"וּלְשִׁבְטָא דְנַפְתָּלִי בְּרִיךְ משֶׁה נְבִיָא דַיְיָ וַאֲמַר נַפְתָּלִי שְבַע רַעֲוָא וְחָדֵי בְּנוּנֵי יַמָא דִי נְפָלוּ בְּחוּלְקֵיהּ וּמְלֵי בִּרְכָאָן מִן פֵּירֵי דְבִקְעַת גִינוּסַר דְאִתְיְהִיבוּ לֵיהּ מִן קֳדָם יְיָ יַמָא דְסוּפְנֵי וְיַמָא דִטְבֶרְיָא יֵירָת\",0,0],[4,142,33,24,\"וּלְשִׁבְטָא דְאָשֵׁר בְּרִיךְ משֶׁה נְבִיָא דַיְיָ וַאֲמַר בְּרִיךְ הוּא מִבְּנַיָא דְיַעֲקב אָשֵׁר יְהֵי מַרְעֵי לְאָחוֹי וּמְסַפֵּק לְהוֹן מְזוֹנֵי בִּשְׁנֵי שְׁמִיטָתָא וּתְחוּמֵיהּ יְהֵי מַרְבֵּי זֵיתִין סַגִיעִין עָבְדִין מְשַׁח מְסַפְּקִין לְמִטְבוֹל בֵּיהּ רִיגְלוֹי\",0,0],[4,142,33,25,\"בְּרִירִין הִינוּן שִׁבְטָא דְאָשֵׁר הֵיךְ פַּרְזְלָא וַחֲסִימִין הֵיךְ נְחָשָׁא רִיגְלֵיהוֹן לְטַיְילָא עַל שִׁינֵי כֵיפַיָא וְהֵי כְיוֹמֵי טַלְיוּתְהוֹן הֵיכְדֵין יֶהֱווּן תַּקִיפִין בְּסִיבוּתְהוֹן\",0,0],[4,142,33,26,\"לֵית אֱלָהָא כָּאֱלָהָא יִשְרָאֵל דְאַשְׁרַי שְׁכִינְתֵּיהּ וּרְכוּבֵיהּ בִּשְׁמַיָא הוּא יֶהֱוֵי בְּסַעַדְכוֹן וְיָתִיב עִם כּוּרְסֵיהּ יְקָרָא בְּגַוְותָנוּתֵיהּ בִּשְׁמֵי שְׁחָקֵי מְרוֹמָא\",0,0],[4,142,33,27,\"מְדוֹרֵי דֶאֱלָהָא הֲוָה מִן לְקַדְמִין וּמִן תְּחוֹת אֶדְרַע גְבוּרְתֵּיהּ עַלְמָא סָבִיל דִיבוּדוֹר בַּעֲלֵי דְבָבֵיכוֹן מִן קֳדָמֵיכוֹן וְיֵימַר בְּמֵימְרֵיהּ לִמְשֵׁיצְיָיא יַתְהוֹן\",0,0],[4,142,33,28,\"וּשְׁרוֹן יִשְרָאֵל לְרוֹחֲצָן מִן לְקַדְמִין כְּעֵין בִּרְכָתָא דְבָרְכִינוּן יַעֲקב אֲבוּהוֹן דְבִזְכוּתֵיהּ אַחֲסִין יַתְהוֹן אַרְעָא טַבְתָּא דְעַבְדָא עִבּוּר וַחֲמַר לְחוֹד שְׁמַיָא דְעִלַוֵיהוֹן דְסַיַין לְהוֹן טַלִין דְבִרְכָתָא וּמִטְרִין דְרַעֲוָא\",0,0],[4,142,33,29,\"טוּבְכוֹן יִשְרָאֵל מַן כְּוַותְכוֹן בְּכָל עַמְמַיָא עַמָא דְמִתְפָּרְקִין בְּשׁוּם מֵימְרָא דַיְיָ וְהוּא תְּרִיס סְעוּדְכוֹן וְדִי חַרְבֵּיהּ תְּקוֹף גֵיוְתָנוּתְכוֹן וְיִתְכַּדְבוּן סַנְאֵיכוֹן לְקוּבְלֵיכוֹן מִן רְתֵיתָא וְאַתּוּן עַל פִּירְקַת צַוְורֵי מַלְכֵיהוֹן תִּדְרוֹךְ\",0,0],[4,142,34,1,\"וּסְלֵיק משֶׁה מִן מֵישְׁרָא מוֹאָב לְטַוְורָא דִנְבוֹ רֵישׁ רָמָתָא דְעַל אַפֵּי יְרֵיחוֹ וְאַחֲוֵוי לֵיהּ מֵימְרָא דַיְיָ יַת כָּל תַּקִיפֵי אַרְעָא יַת גְבוּרָן דְעָתִיד לְמֶעֱבַד יִפְתָּח דְמִן גִלְעָד וְנַצְחָנִין דְשִׁמְשׁוֹן בַּר מָנוֹחַ דְמִן שֵׁיבַט דָן\",0,0],[4,142,34,2,\"וְיַת אַלַּוּף סַרְכוּן מִדְּבֵית נַפְתָּלִי דְּמִתְחַבְּרִין עִם בָּרָק וְיַת מַלְכַיָא דְעָתִיד לְמִקְטַל יְהוֹשֻׁעַ בַּר נוּן דְמִן שֵׁיבַט אֶפְרַיִם וּגְבוּרָן דְגִדְעוֹן בַּר יוֹאָשׁ דְמִן שֵׁבַט מְנַשֶׁה וְיַת כָּל מַלְכַיָּא דְיִשְרָאֵל וּמַלְכוּתָא דְּבֵית יְהוּדָה דִשְׁלִיטוּ בְּאַרְעָא עַד דְאִצְתַּדֵי בֵּית מוּקְדְשָׁא בַּתְרָאָה\",0,0],[4,142,34,3,\"וְיַת מְלִיךְ דָּרוֹמָא דְמִתְחַבֵּר עִם מְלִיךְ צִיפוּנָא לְחַבְּלָא יַתְבֵי אַרְעָא וְעַמּוֹנָאֵי וּמוֹאֲבָאֵי יַתְבֵי מֵשְׁרָא דִּמְעִיקִין לְהוֹן לְיִשְרָאֵל וְיַת גַּלְוַות תַּלְמִידֵי אֵלִיָהוּ דְגַלַן מִן בִּקְעָתָא דִירֵיחוֹ וְיַת גַלְוַות תַּלְמִידֵי אֱלִישָׁע דְּגָלוּ מִן קִרְוַות דִּקְלַיָּא עַל יַד אֲחוּהוֹן בֵּית יִשְרָאֵל מָאתָן אַלְפִין גּוּבְרִין וְיַת עָקַת כָּל דָּר וְדָר וּפוּרְעָנוּת אַרְמַלְגּוֹס רַשִּׁיעָא וְסִדְרֵי קְרָבָא דְגוֹג וּבְעִידַן צַעֲרָא רַבָּא הַהוּא מִיכָאֵל יְקוּם בִּדְרָעָא לְפָרוּקָא\",0,0],[4,142,34,4,\"וַאֲמַר יְיָ לֵיהּ דָא הוּא סֵיפָא דְמִלְתָא בְּאַרְעָא וְדָא אַרְעָא דְּקַיֵּימִית לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקב לְמֵימָר לִבְנֵיכוֹן אֶתְּנִינָהּ אַחְמְיַית יָתָהּ בְּעֵינָךְ וְתַמָּן לָא תְעִבַּר\",0,0],[4,142,34,5,\"בְּשַׁבְעָא יוֹמִין לְיַרְחָא דַאֲדָר אִתְיְלִיד משֶׁה רַבְּהוֹן דְּיִשְרָאֵל וּבְשַׁבְעָא יוֹמִין לְיַרְחָא דַאֲדָר אִתְכְּנִישׁ מִגּוֹ עַלְמָא בְּרַת קָלָא נָפְלַת מִן שְׁמַיָּא וְכֵן אָמְרַת אָתוּן כָּל עַלְלֵי עַלְמָא וְחָמוֹן בְּצַעֲרֵי דְמשֶׁה רַבְּהוֹן דְּיִשְרָאֵל דְּטָרַח וְלָא אִתְהַנֵי וְאִתְרַבֵּי בְּאַרְבַּעַת כְּלִילִין טָבִין כְּלִילַת דְּאוֹרַיְיתָא דִידֵיהּ דְּשָׁבָא יָתָהּ מִשְּׁמֵי מְרוֹמָא וְאִתְגְלֵי עֲלוֹי אִקַר שְׁכִינְתָּא דַּיְיָ בִּתְרֵין אַלְפִין רִיבְוָון דְּמַלְאָכִין וּבְאַרְבְּעִין וְתַרְתֵּין אַלְפִין אַרְתְּכִין דְּנוּר כְּלִילָא דִכְהוּנְתָּא דִידֵיהּ הֲוַות שִׁבְעָתֵי יוֹמֵי אַשְׁלָמוּתָא כְּלִילָא דְמַלְכוּתָא אַחֲסִינוּ יָתֵיהּ מִן שְׁמַיָּא לָא חַרְבָּא שָׁלָף וְלָא סוּסָא אָסַר וְלָא מַשִּׁרְיָּן אַרְגִּישׁ כְּלִילָא דִּשְׁמָא טָבָא קָנָא בְּעוֹבָדִין טָבִין וּבְעִנְוָותָנוּתֵיהּ בְכֵן אִתְכְּנַשׁ תַּמָן משֶׁה עַבְדָּא דַיְיָ בְּאַרְעָא דְמוֹאָב עַל נְשִׁיקַת מֵימְרָא דַיְיָ\",0,0],[4,142,34,6,\"בְּרִיךְ שְׁמֵיהּ דְמָארֵי עַלְמָא דְאַלִיף לָן אָרְחָתֵיהּ תַּקְנֵי אַלִּיף יָתָן לְמִלְבַּשׁ עַרְטְלָאִין מִן דְּאַלְבֵּישׁ אָדָם וְחַוָּה אַלִיף יָתָן לִמְזַוְגָּא חַתְנִין וְכַלָּן מִן דְּזַוֵיג חַוָה לְוַת אָדָם אַלִּיף יָתָן לִמְבַקְרָא מַרְעִין מִן דְּאִתְגְּלֵי בְּחֶזְוֵוי מֵימְרֵיהּ עַל אַבְרָהָם כַּד הֲוָה מְרַע מִגְזֵרַת מָהוּלְתָּא אַלִּיף יָּתָן לִמְנַחְמָא אֶבְלִין מִן דְּאִתְגְּלֵי לְיַעֲקב תּוּב בְּמֵיתוֹי מִפַּדַן בַּאֲתַר דְּמִיתַת אִמֵּיהּ אַלִּיף יָתָן לִמְפַרְנְסָא מַסְכְּנִין מִן דְּאָחַת לִבְנֵי יִשְרָאֵל לַחֲמָא מִן שְׁמַיָּא. אַלִיף יָתָן לְמִקְבַּר מֵיתַיָּא מִן משֶׁה דְאִתְגְלֵי עֲלוֹי בְּמֵימְרֵיהּ וְעִמֵּיהּ חֲבוּרַן דְמַלְאֲכֵי שֵׁירוּתָא מִיכָאֵל וְגַבְרִיאֵל אַצִיעוֹן דַּרְגְּשָׁא דְּדַהֲבָה מִקְבְּעָא בְּיוֹרְכִין וְסַנְדַּלְכִין וּבוּרְלִין מְתַקְנָא כְּבִסְתַּרְקֵי מִלַּת וְסוּכְנִין דְּאַרְגְּוָון וְאוֹצִיטִילִין חִוְורִין מְטַטְרוֹן וְיוֹפִיאֵל וְאוֹרִיאֵל וִיפִיפְיָה רַבָּנֵי חָכְמָתָא אַרְבְּעִין יָתֵיהּ עֲלָהּ וּבְמֵימְרֵיהּ דַּבְּרֵי אַרְבַּעֲתֵּי מִלִּין וּקְבַר יָתֵיהּ בְּחֵילְתָא כֻּלּוֹ קָבֵיל בֵּית פְּעוֹר דְּכָל אֵימַת דְּזַקִּיף פְּעוֹר לְמִדְכַּר לְיִשְרָאֵל חוֹבַתְהוֹן מוֹדִיק בְּבֵית קְבוּרְתֵּיהּ דְמשֶׁה וּמִתְכְּבִישׁ וְלָא חַכִּים בַּר נַשׁ יַת קְבוּרְתֵּיהּ עַד זְמַן יוֹמָא הָדֵין\",0,0],[4,142,34,7,\"וּמשֶׁה בַּר מְאָה וְעֶשְרִין שְׁנִין כַּד שְׁכִיב לָא כַהֲיָין גִלְגוּלֵי עֵינוֹי וְלָא נַתְרוֹן נִיבֵי לִסְתֵיהּ\",0,0],[4,142,34,8,\"וּבְכוֹן בְּנֵי יִשְרָאֵל יַת משֶׁה בְּמֵישְׁרַיָא דְמוֹאָב תְּלָתִין יוֹמִין וּשְׁלִימוּ יוֹמֵי בָּכוּתָא דְאֶבְלֵיהּ דְמשֶׁה בִּתְמַנְיָא בְּנִיסָן וּבְתִשְׁעָא בְּנִיסָן אַתְקִינוּ עַמָא בֵּית יִשְרָאֵל יַת מָאנֵיהוֹן וּטְכוּסוּ יַת בְּעִירֵיהוֹן וַעֲבָרוּ יַת יוֹרְדְנָא בְּעַשְרָא בְּנִיסָן וּפְסַק לְהוֹן מַנָא בְּשִׁיתֵיסַר בְּנִיסָן הִשְׁתְּכָחוּ אָכְלִין יַת מַנָא בִּזְכוּתֵיהּ דְמשֶׁה בָּתַר דְשָׁכִיב תְּלָתִין וְשַׁבְעָא יוֹמִין\",0,0],[4,142,34,9,\"וִיהוֹשֻׁעַ בַּר נוּן אִתְמְלֵי רוּחַ חָכְמְתָא אֲרוּם סְמַךְ משֶׁה יַת יְדוֹי עֲלוֹי וְקַבִּילוּ אוּלְפַן מִנֵיהּ בְּנֵי יִשְרָאֵל וַעֲבָדוּ הֵיכְמָא דְפַקֵיד יְיָ יַת משֶׁה\",0,0],[4,142,34,10,\"וְלָא קָם נְבִיָא תּוּב בְּיִשְרָאֵל כְּמשֶׁה אֲרוּם חַכִּים יָתֵיהּ מֵימְרָא דַיְיָ מַמְלֵל כֻּלוֹ קֳבֵיל מַמְלֵל\",0,0],[4,142,34,11,\"לְכוּלְהוֹן אָתַיָא וְתִמְהֵי פְרִישָׁתָא דִי שַׁדְרֵיהּ מֵימְרָא דַיְיָ לְמֶעֱבַד בְּאַרְעָא דְמִצְרַיִם לְפַרְעה וּלְכָל עַבְדוֹי וּלְכָל עַם אַרְעֵיהּ\",0,0],[4,142,34,12,\"וּלְכָל גְבוּרַת יְדָא תַקִיפְתָּא הֵיךְ סוֹבַר יַת חוּטְרָא דְמַתְקְלֵיהּ אַרְבְּעִין סָאִין וּבְזַע יַת יַמָא וּמְחָא יַת כֵּיפָא וּלְכָל דְחֵיל רַב דְעָבַד משֶׁה בִּזְמַן דְקַבֵּל תְּרֵין לוּחֵי אֲבַן סַמְפִּירִינוֹן וּמַתְקַלְהוֹן אַרְבְּעִין סָאוִין וְסוֹבְרִינוּן בְּתַרְתֵּין יְדוֹי לְמֵיחְמֵהוֹן דְכוּלְהוֹן יִשְרָאֵל\",0,0],[4,143,1,1,\"וְאִילֵין שְׁמָהַת בְּנֵי יִשְרָאֵל דְעָלוּ לְמִצְרַיִם עִם יַעֲקב גְבַר עִם אֱנַשׁ בֵּיתֵיהּ עָלוּ\",0,0],[4,143,1,2,\"רְאוּבֵן שִׁמְעוֹן לֵוִי וִיהוּדָה\",0,0],[4,143,1,3,\"יִשָשׁכָר זְבוּלֻן וּבִנְיָמִין\",0,0],[4,143,1,4,\"דָן וְנַפְתָּלִי גָד וְאָשֵׁר\",0,0],[4,143,1,5,\"וַהֲוָה סְכוּם כָּל נַפְשָׁתָא נַפְקֵי יַרְכָא דְיַעֲקב שׁוּבְעִין נַפְשָׁתָא עִם יוֹסֵף וּבְנוֹהִי דַהֲוָה בְּמִצְרַיִם\",0,0],[4,143,1,6,\"וּמִית יוֹסֵף וּבַתְרֵיהּ מִיתוּ כָּל אֲחוֹהִי וְכָל דָרָא הַהוּא\",0,0],[4,143,1,7,\"וּבְנוֹי דְיִשְרָאֵל נְפִישׁוּ וְאִתְיְלִידוּ וּסְגוּ וְאִתְקִיפוּן לַחֲדָא לַחֲדָא וְאִתְמְלִיאַת אַרְעָא מִנְהוֹן\",0,0],[4,143,1,8,\"וְקָם מִלִיךְ חָדַת כְּמִין שֵׁירוּיָא עַל מִצְרַיִם דְלָא חֲכִּים יַת יוֹסֵף וְלָא הֲלִיךְ בְּנִימוּסוֹי\",0,0],[4,143,1,9,\"וַאֲמַר לְעַמֵיהּ הָא עַמָא בֵּית יִשְרָאֵל סַגִיאִין וְתַקְפִין יַתִּיר מִינָן\",0,0],[4,143,1,10,\"אִיתוֹן כְּדוֹן נִתְיַעַט עֲלֵיהוֹן בְּהִלֵן דִינִין נַזְעַר יַתְהוֹן קֳדָם עַד לָא יִסְגוֹן וְיֶהֱוֵי אֲרוּם יָתָן סִדְרֵי קְרָבָא וְיִתּוֹסְפוּן לְחוֹד הִינוּן עַל סַנְאֵינָן וִישֵׁיצוּן יָתָנָא וְלָא יְשַׁיְירוּן מִינָן אוּף לָא חָד וּמִן בָּתַר כְּדֵין יִפְקוּן לְהוֹן מִן אַרְעָא\",0,0],[4,143,1,11,\"וְשַׁווּן עֲלֵיהוֹן רַבְרְבָנִין מְפַלְחָנִין מִן בִּגְלַל לְמִצְעֲרָא יַתְהוֹן בְּשִׁעֲבּוּדְהוֹן וּבִנְיַין קוּרְיַין תְלִילִין לְשׁוּם בֵּית אוֹצְרוֹי דְפַרְעה יַת טָאנֵיס וְיַת פִּילוּסִין\",0,0],[4,143,1,12,\"וְהֵיכְמָא דִמְעַנְיַין לְהוֹן הֵיכְדֵין הֲווֹן סָגַן וְהֵיכְדַין הֲווֹן תַּקְפִין וְאִתְיַעֲקוּ מִצְרָאֵי בְּחַיֵיהוֹן מִן קֳדָם בְּנֵי יִשְרָאֵל\",0,0],[4,143,1,13,\"וְשַׁעֲבִּידוּ מִצְרָאֵי יַת בְּנֵי יִשְרָאֵל בְּקַשְׁיוּ\",0,0],[4,143,1,14,\"וְאַמְרָרוּ יַת חַיֵיהוֹן בְּפוּלְחָנָא קַשְׁיָא בְּטִינָא וּבְלִיבְנִין וּבְכָל פּוּלְחָנָא בְּאַנְפֵּי בָרָא יַת כָּל פּוּלְחַנְהוֹן הֲווֹן מְפַלְחִין בְּהוֹן בְּקַשְׁיוּ\",0,0],[4,143,1,15,\"וַאֲמַר פַּרְעה דָמָךְ הֲוָה חָמֵי בְּחֵילְמֵיהּ וְהָא כָּל אַרְעָא דְמִצְרַיִם קַיְימָא בְּכַף מוֹדָנָא חֲדָא וְטַלְיָא בַּר אִימְרָתָא בְּכַף מוֹדָנָא חֲדָא וַהֲוַת כַּרְעָא כַּף מוֹדָנָא מְטַלְיָא בְּגַוָה מִן יַד שָׁדַר וּקְרָא כָּל חַרְשֵׁי מִצְרַיִם וְתָנֵי לְהוֹן יַת חוּלְמֵיהּ מִן יַד פַּתְחִין פּוּמְהוֹן יֵינִיס וְיִמְבְּרֵס רֵישֵׁי חַרְשַׁיָא וְאָמְרִין לְפַרְעה בִּיר חַד עָתִיד לְמֶהֱוֵי מִתְיְלִיד בִּכְנִישַׁתְהוֹן דְיִשְרָאֵל דְעַל יְדוֹ עֲתִידָא לִמְחַרְבָא כָּל אַרְעָא דְמִצְרַיִם וּבְגִין כֵּן אִתְיַעַט פַּרְעה מַלְכָּא דְמִצְרַיִם לְחַיָיתָא יְהוֹדַיְיתָא דִשְׁמָא דְחָדָא שִׁפְרָה הִיא יוֹכֶבֶד וּשְׁמָא דְתִּנְיֵיתָא פּוּעָה הִיא מִרְיָם בְּרַתָּה\",0,0],[4,143,1,16,\"וַאֲמַר כַּד תֶּהֱוְיַין מוֹלְדָן יַת יְהוֹדַיְיתָא וְתִיסְתְּכִין עַלוֹי מַתְבְּרָא אִין בִּיר דְכַר הוּא וְתִקְטְלוּן יָתֵיהּ וְאִין בְּרַתָּא נוּקְבָא הִיא וְתִתְקַיֵים\",0,0],[4,143,1,17,\"דְחִילָא חַיְיתָא מִן קֳדָם יְיָ וְלָא עָבָדוּ הֵיכְמָא דְמַלֵל עִמְהוֹן מַלְכָּא דְמִצְרַיִם וְקַיָימָא יַת בְּנַיָיא\",0,0],[4,143,1,18,\"וּקְרָא מַלְכָּא דְמִצְרַיִם לְחַיָיתָא וַאֲמַר לְהוֹן לְמָה דֵין עֲבַדְתּוּן יַת פִּתְגָמָא הָדֵין וּקְיַימְתּוּן יַת בְּנַיָא\",0,0],[4,143,1,19,\"וַאֲמָרַן חַיְיתָא לְפַרְעה אֲרוּם לָא כִנְשַׁיָא מִצְרַיְתָא יְהוּדַיְיתָא אֲרוּם זְרִיזִין וְחַכִּימִין בְּדַעֲתֵּיהֶן הִינוּן קֳדָם עַד לָא תֵיתֵי לְוַותְהוֹן חַיְיתָא הִינִין תַּלְיַין עֵינֵיהֶן בִּצְלוֹי מַצְלָן וּבַעֲיָין רַחֲמִין מִן קֳדָם אֲבוּהֶן דְבִשְׁמַיָא וְהוּא שָמַע בְּקַל צְלוֹתְהוֹן מִן יַד הִינִין מִתְעַנְיַין וִילִידַן וּפָרְקַן בִּשְׁלָם\",0,0],[4,143,1,20,\"וְאוֹטִיב יְיָ לְחַיְיתָא וּסְגוֹ עַמָא וּתְקִיפוּ לַחֲדָא\",0,0],[4,143,1,21,\"וַהֲוָה כַּד דְחִילָא חַיְתָא מִן קֳדָם יְיָ וּקְנוּ לְהוֹן שׁוּם טַב לְדָרַיָא וּבְנָא לְהוֹן מֵימְרָא דַיְיָ בֵּית מַלְכוּתָא וּבֵית כְּהוּנְתָּא רַבְּתָא\",0,0],[4,143,1,22,\"וְכַד חָמָא פַּרְעה כְּדֵין פַּקֵיד לְכָל עַמֵיהּ לְמֵימָר כָּל בִּיר דְכַר דְאִתְלִיד לִיהוּדָאֵי בְּנַהֲרָא תִּטְלוֹקְנֵיהּ וְכָל בְּרַתָּא תְּקַיְימוּן\",0,0],[4,143,2,1,\"וַאֲזַל עַמְרָם גַבְרָא דְמִשֵׁבֶט לֵוִי וְאוֹתִיב בְּכִילְתָא וְגִינוּנָא דְהִלוּלָא יַת יוֹכֶבֶד אִנְתְּתֵיהּ דְתָרִיךְ מִן קֳדָם גְזֵירְתָּא דְפַרְעה וַהֲוַת בְּרַת מֵאָה וּתְלָתִין שְׁנִין כַּד אֲהַדְרָהּ לְוָותֵיהּ וְאִתְעֲבֵיד לָהּ נִיסָא וְהַדְרַת לְעַלֵימוֹתָא כְּמָא דַהֲוַת כַּד הִיא זְעֵירְתָּא מִקְרְיָיא בְּרַת לֵוִי\",0,0],[4,143,2,2,\"וְאִיתְעֲבָּרַת אִיתְּתָא וִילֵדַת בִּיר בְּסוֹף שִׁיתָּא יַרְחִין וְחָמַת יָתֵיהּ אֲרוּם בַּר קְיוֹמֵי הוּא וְאַטְמַרְתֵּיהּ תְּלַת יַרְחִין דִסְכוּמְהוֹן תִּשְׁעָא\",0,0],[4,143,2,3,\"וְלָא הֲוַת אֶפְשַׁר לָהּ תּוּב לְאַטְמַרְתֵּיהּ דְמִצְרַיִם מַרְגִישִׁין עֲלָהּ וּנְסִיבַת לֵיהּ תֵּיבוּתָא דְטוּנֵס וַחֲפָהָא בְּחֵימְרָא וּבְזֵיפָתָא וְשַׁוְיַית בְּגַווָהּ יַת טַלְיָא וְשַׁוְיָתֵיהּ בְּגוֹ גוּמַיָא עַל גֵיף נַהֲרָא\",0,0],[4,143,2,4,\"וְאִתְעֲתָּדַת מִרְיָם אַחְתֵיהּ מֵרָחִיק לְאִתְחַכְּמָא מָה יִתְעֲבֵד לֵיהּ\",0,0],[4,143,2,5,\"וְגָרֵי מֵימְרָא דַיְיָ צוּלְקָא דְשִׁחֲנָא וְטָרֵיב בִּשְרָא בְּאַרְעָא דְמִצְרַיִם וְנִחְתַת בְּרַתֵּיהּ דְפַרְעה לְאִתְקַרְרָא עַל נַהֲרָא וְעוּלֵימְתָּהָא אָזְלַן עַל גֵיף נַהֲרָא וַחֲמַת יַת תֵּיבוּתָא בְּגוֹ גוּמַיָיא וְאוֹשִׁיטַת יַת גַרְמִידָא וּנְסִיבְתָּא וּמִן יַד אִיתַּסְיַית מִן שִׁיחְנָא וּמִן טְרִיבָא\",0,0],[4,143,2,6,\"וּפְתָחַת וְחָמַת יַת רַבְיָא וְהָא טַלְיָא בָּכֵי וְחָסַת עֲלוֹי וַאֲמָרַת מִן בְּנֵי יְהוּדָאֵי הוּא דֵין\",0,0],[4,143,2,7,\"וַאֲמָרַת אַחְתֵיהּ לְבַת פַּרְעה הַאִיזֵיל וְאִיקְרֵי לִיךְ אִיתְּתָא מֵנִיקְתָא יְהוּדַיְיתָא וְתוֹנִיק לִיךְ יַת רַבְיָא\",0,0],[4,143,2,8,\"וַאֲמָרַת לָהּ בְּרַת פַּרְעה אִיזִילִי וְאָזְלַת טַלְיָתָא וּקְרַת לְאִמֵיהּ דְרַבְיָא\",0,0],[4,143,2,9,\"וַאֲמָרַת לָהּ בְּרַת פַּרְעה אוֹבִילִי יַת רַבְיָא הָדֵין וְאוֹנִיקְתֵּיה לִי וַאֲנָא אִיתִּין יַת סוּטְרָךְ וּנְסִיבַת אִיתְּתָא יַת רַבְיָא וְאוֹנִיקְתֵּיהּ\",0,0],[4,143,2,10,\"וּרְבָא רַבְיָא וְאַיְיתִיתֵיהּ לִבְרַת פַּרְעה וַהֲוָה לָהּ חָבִיב הֵי כְּבִיר וּקְרַת שְׁמֵיהּ משֶה אֲרוּם אֲמָרַת מִן מוֹי דְנַהֲרָא שְׁחִילְתֵּיהּ\",0,0],[4,143,2,11,\"וַהֲוָה בְּיוֹמַיָא הָאִינוּן וּרְבָא משֶׁה וּנְפַק לְוַת אָחוֹהִי וַחֲמָא בַּאֲנֵיק נַפְשֵׁיהוֹן וּבְסוּגֵי פּוּלְחַנְהוֹן וַחֲמָא גְבַר מִצְרָאֵי מָחֵי גְבַר יְהוּדָאֵי מֵאֲחוֹי\",0,0],[4,143,2,12,\"וְאִיסְתַּכֵּל משֶׁה בְחָכְמַת דַעְתֵּיהּ וְאִתְבּוֹנָן בְּכָל דַר וְדַר וְהָא לָא קָאִים מִן הַהוּא מִצְרָאֵי גְבַר גִיוֹר וְלָא דְעָבִיד תְּתוּבָא מִן בְּנֵי בְּנוֹי עַד עַלְמָא וּמְחָא יַת מִצְרָאֵי וְטַמְרֵיהּ בְּחָלָא\",0,0],[4,143,2,13,\"וּנְפַק בְּיוֹמָא תִּנְיָינָא וְאוֹדִיק וְהָא דָתָן וַאֲבִירָם גוּבְרִין יְהוּדָאִין נָצָן וְכַד חֲמָא דִי זְקַף דָתָן יְדֵיהּ עַל אֲבִירָם לְמִימְחֵיהּ אָמַר לֵיהּ לְמָא אַנְתְּ מָחֵי לְחַבְרָךְ\",0,0],[4,143,2,14,\"וַאֲמַר לֵיהּ דָתָן מַאן הוּא דְמַנֵי יָתָךְ לִגְבַר רַב וְדַיָין עֲלָנָא הֲלָא לְמִקְטְלִי אַנְתְּ אָמַר כְּמָא דִקְטַלְתָּ יַת מִצְרָאֵי וּדְחֵיל משֶׁה וַאֲמַר בְּקוּשְׁטָא אִתְפַּרְסַם פִּתְגָמָא\",0,0],[4,143,2,15,\"וּשְׁמַע פַּרְעה יַת פִּתְגָמָא הָדֵין וּבְעָא לְמִקְטוֹל יַת משֶׁה וְעָרַק משֶׁה מִן קֳדָם פַּרְעה וִיתֵיב בְּאַרְעָא דְמִדְיָן וִיתֵב עַל בֵּירָא\",0,0],[4,143,2,16,\"וּלְאוֹנֵיס דְמִדְיָן שְׁבַע בְּנָתָא וַאֲתוֹ וּדְלָאָה וּמְלָאָה יַת מוּרְכְוָותָא לְאַשְׁקָאָה יַת עָנָא דַאֲבוּהֶן\",0,0],[4,143,2,17,\"וְאָתוּן רַעֲיָא וּטְרָדוּנִין וְקָם משֶׁה בְּכחַ גְבוּרְתֵּיהּ וּפְרָקִינִין וְאַשְׁקֵי יַת עַנְהֶן\",0,0],[4,143,2,18,\"וַאֲתָאָה לְוַת רְעוּאֵל אָבוּהָא דַאֲבוּהוֹן וַאֲמַר מַה דֵין אוֹחֵיתוּן לְמֵיתֵי יוֹמָא דֵין\",0,0],[4,143,2,19,\"וְאָמָרָא גַבְרָא שֵׁיזְבָנָא מִן יְדָא דְרַעֲיָא לְחוֹד מִדוֹל חַד דָלָה לָן וְאַשְׁקֵי יַת עָנָא\",0,0],[4,143,2,20,\"וַאֲמַר לִבְנָתֵיהּ דִבְרֵיהּ וְהָאן הוּא דְנַן שְׁבַקְתּוּן יַת גַבְרָא קְרֵין לֵיהּ וְיֵיכוּל לַחֲמָא\",0,0],[4,143,2,21,\"וְכַד חַכִּים רְעוּאֵל דְעָרַק משֶׁה מִן קֳדָם פַרְעה טָלַק יָתֵיהּ לְגוּבָא וַהֲוַת צִפּוֹרָה בְּרַתֵּיהּ דִבְרֵיהּ מְפַרְנָסָא יָתֵיהּ בְּסִיתְרָא בִּזְמַן עִשַרְתִּי שְׁנִין וּלְסוֹף עִשַרְתִּי שְׁנִין אַפְקֵיהּ מִן גוּבָא וְעַל משֶׁה בְּגוֹי גִינוּנִיתָא דִרְעוּאֵל וַהֲוָה מוֹדֵי וּמַצְלֵי קֳדָם יְיָ דַעֲבֵד עִמֵיהּ נִיסִין וּגְבוּרַן וְאִיסְתְּכִיַית חוּטְרָא דְאִיתְבְּרִאַת בֵּינֵי שִׁמְשְׁתָא וְחַקְיָין וּמְפָרַשׁ עֲלָהּ שְׁמָא רַבָּא וְיַקִירָא דְבֵיהּ עָתִיד לְמֶעֱבַד יַת תִּמְהַיָא בְּמִצְרַיִם וּבֵיהּ עָתִיד לְמִבְזַע יַת יַמָא דְסוּף וּלְהַנְפָקָא מוֹי מִן כֵּיפָא וַהֲוָה דָעִיץ בְּגוֹ גִינוּנִיתָא וּמִן יַד אוֹשִׁיט יְדֵיהּ וְנַסְבֵיהּ הָא בְּכֵין צָבֵי משֶׁה לְמִתַּב עִם גַבְרָא וִיהַב יַת צִפּוֹרָה בְּרַת בְּרַתֵּיהּ לְמשֶׁה\",0,0],[4,143,2,22,\"וִילֵידַת בִּיר דְכַר וּקְרָא שְׁמֵיהּ גֵרְשׁוֹם אֲרוּם אָמַר דַיָר הֲוֵיתִי בְּאַרְעָא נוּכְרַיָיא דְלָא דִידִי\",0,0],[4,143,2,23,\"וַהֲוָה בְּיוֹמַיָא סְגִיאַיָיא הָאִינוּן וְאִתְכְּתַשׁ מַלְכָּא דְמִצְרָיִם וּפַקֵיד לְקַטָלָא בּוּכְרַיָיא דִבְנֵי יִשְרָאֵל בְגִין לְמִסְחֵי בְּאַדְמֵיהוֹן וְאִתְאַנָחוּ בְּנֵי יִשְרָאֵל מִן פּוּלְחָנָא דַהֲוָה קַשְׁיָא עֲלֵיהוֹן וּזְעָקוּ וּסְלֵיקַת קְבֵילְתְּהוֹן לִשְׁמֵי מְרוֹמָא דַיְיָ וַאֲמַר בְּמֵימְרֵיהּ לְמִפְרוֹקִינוּן מִן פּוּלְחָנָא\",0,0],[4,143,2,24,\"וּשְׁמִיעַ קֳדָם יְיָ קְבֵילְתְּהוֹן וּדְכִיר קֳדָם יְיָ יַת קְיָימֵיהּ דְקַיֵים עִם אַבְרָהָם וְעִם יִצְחָק וְעִם יַעֲקב\",0,0],[4,143,2,25,\"וַחֲמָא יְיָ צַעַר שִׁעֲבּוּדְהוֹן דִבְנֵי יִשְרָאֵל וּגְלֵי קֳדָמוֹי יַת תִּיוֹבְתָּא דְעָבָדוּ בְּטוּמְרָא דְלָא יָדְעוּ אַנַשׁ בְּחַבְרֵיהּ\",0,0],[4,143,3,1,\"וּמשֶׁה הַוָה רָעֵי יַת עָנַא דְיִתְרוֹ חָמוֹי רַבָּא דְמִדְיָן וּדְבַר יַת עָנָא לַאֲתַר שְׁפַר רַעֲיָא לַאֲחוֹרֵי מַדְבְּרָא וְאָתָא לְטַוְורָא דְאִתְגְלֵי עֲלוֹי יְקָרָא דַיְיָ לְחוֹרֵב\",0,0],[4,143,3,2,\"וְאִתְגְלֵי זַגְנוּגָאֵל מַלְאָכָא דַיְיָ לֵיהּ בְּלַהֲבֵי אֵישָׁתָא מִגוֹ סַנְיָא וַחֲמָא וְהָא סַנְיָא מַשְׁרִיב בְּאֵישָׁתָא וְסַנְיָא לֵיתוֹ יַקִיד וּמִתְאָכֵל בְּנוּרָא\",0,0],[4,143,3,3,\"וַאֲמַר משֶׁה אִתְפְּנֵי כְדוּן וְאֵיחְמֵי יַת חֶזְוָונָא רַבָּא הָדֵין מַדֵין לָא שְׁרִיב סַנְיָא\",0,0],[4,143,3,4,\"וּגְלֵי קֳדָם יְיָ אֲרוּם אִיתְפְּנֵי לְמֵיחְמֵי וּקְרָא לֵיהּ יְיָ מִגוֹ סַנְיָא וַאֲמַר משֶׁה משֶׁה וַאֲמַר הָא אֲנָא\",0,0],[4,143,3,5,\"וַאֲמַר לָא תִקְרַב הַלְכָא שְׁלוּף סֵינָךְ מֵעַל רִגְלָךְ אֲרוּם אַתְרָא דְאַנְתְּ קָאִים עֲלוֹי אָתַר קַדִישׁ הוּא וְעָלוֹי אַנְתְּ עָתִיד לְקַבָּלָא אוֹרַיְיתָא לְמַלְפָא יָתָהּ לִבְנֵי יִשְרָאֵל\",0,0],[4,143,3,6,\"וַאֲמַר אֲנָא הוּא אֱלָהֵיהּ דְאָבוּךְ אֱלָהֵיהּ דְאַבְרָהָם אֱלָהֵיהּ דְיִצְחָק וֵאלָהֵיהּ דְיַעֲקב וּכְבָשִׁינוּן משֶׁה לְאַנְפּוֹי אֲרוּם הֲוָה דָחִיל מִלְמִסְתְּכֵי בְּצֵית אִיקַר שְׁכִינְתָּא דַיְיָ\",0,0],[4,143,3,7,\"וַאֲמַר מִיגְלֵי גְלֵי קֳדָמַי יַת סִיגוּף עַמִי דִבְמִצְרַיִם וְיַת קְבֵלְתְּהוֹן שְׁמִיעַ קֳדָמַי מִן קֳדָם מְשַׁעֲבְּדֵיהוֹן אֲרוּם גְלֵי קֳדָמַי כֵּיבֵיהוֹן\",0,0],[4,143,3,8,\"וְאִיתְגְלֵיתִי יוֹמָא דֵין עֲלָךְ בְּגִין דִי בְמֵימְרִי לְשֵׁיזְבוּתְהוֹן מִן יְדָא דְמִצְרָאֵי וּלְאַסָקוּתְהוֹן מִן אַרְעָא הַהִיא מְסָאֲבָתָא לְאַרְעָא טַבְתָא וּפִתְיָא בִּתְחוּמִין לְאַרְעָא עַבְדָא חֲלַב וּדְבָשׁ לַאֲתַר דְדַיְירִין תַמָן כְּנַעֲנָאֵי וְחִיתָּאֵי וֶאֱמוֹרָאֵי וּפְרִיזָאֵי וְחִיוָואֵי וִיבוּסָאֵי\",0,0],[4,143,3,9,\"וּכְדוֹן הָא קְבֵילַת בְּנֵי יִשְרָאֵל סְלִיקַת לְקָדָמָי וּלְחוֹד גְלֵי קֳדָמָי יַת דוֹחֲקָא דְמִצְרָאֵי דַחֲקִין יַתְהוֹן\",0,0],[4,143,3,10,\"וּכְדוֹן אִיתָא וְאַשַׁדְרִינָךְ לְוַת פַּרְעה וְאַפֵּיק יַת עַמִי בְּנֵי יִשְרָאֵל מִמְצְרָיִם\",0,0],[4,143,3,11,\"וַאֲמַר משֶׁה קֳדָם יְיָ מַאן אֲנָא אֲרוּם אֵזִיל לְוַת פַּרְעה וַאֲרוּם אַפֵּיק יַת בְּנֵי יִשְרָאֵל מִמִצְרָיִם\",0,0],[4,143,3,12,\"וַאֲמַר אֲרוּם יְהֵי מֵימְרִי בְּסַעְדָךְ וְדֵין לָךְ סִימָנָא דַאֲנָא שַׁדְרָתָךְ בְּהַנְפּוּקָתָךְ יַת עַמָא מִמִצְרַיִם תְּפַלְחוּן קֳדָם יְיָ דִתְקַבְּלוּן יַת אוֹרַיְיתִי עַל טַוְורָא הָדֵין\",0,0],[4,143,3,13,\"וַאֲמַר משֶׁה קֳדָם יְיָ אֲנָא אֵזִיל לְוַת בְּנֵי יִשְרָאֵל וְאֵמַר לְהוֹן יְיָ אֱלָהָא דַאֲבָהַתְכוֹן שַׁדְרַנִי לְוַתְכוֹן וְיֵימְרוּן לִי מַה שְׁמֵיהּ מַה אֵימַר לְהוֹן\",0,0],[4,143,3,14,\"וַאֲמַר יְיָ לְמשֶׁה דֵין דְאָמַר וַהֲוָה עַלְמָא אָמַר וַהֲוָה כּוּלָא וַאֲמַר כִּדְנָא תֵּימַר לִבְנֵי יִשְרָאֵל אֲנָא הוּא דְהַוֵינָא וְעָתִיד לְמֶהֱוֵי שַׁדְרַנִי לְוַותְכוֹן\",0,0],[4,143,3,15,\"וַאֲמַר תּוּב יְיָ לְמשֶׁה כִּדְנַן תֵּימַר לִבְנֵי יִשְרָאֵל אֱלָהָא דְאַבְהַתְכוֹן אֱלָהֵיהּ דְאַבְרָהָם אֱלָהֵיהּ דְיִצְחָק וֵאלָהֵיהּ דְיַעֲקב שַׁדְרַנִי לְוַותְכוֹן דֵין הוּא שְׁמִי לְעָלַם וְדֵין דוּכְרָנִי לְכָל דַר וָדַר\",0,0],[4,143,3,16,\"אִיזֵל וְתִכְנוֹש יַת סָבֵי יִשְרָאֵל וְתֵימַר יְיָ אֱלָהָא דְאַבְהַתְכוֹן אִתְגְלֵי לִי אֱלָהֵיהּ דְאַבְרָהָם יִצְחָק וְיַעֲקב לְמֵימַר מִידְכַּר דְכִירְנָא יַתְכוֹן וְיַת עוּלְבָנָא דְאִיתְעֲבִיד לְכוֹן בְּמִצְרַיִם\",0,0],[4,143,3,17,\"וַאֲמָרִית בְּמֵימְרִי אַפִּיק יַתְכוֹן מִסִיגוּף מִצְרָאֵי לְאַרַע כְּנַעֲנָאֵי וְחִיתָּאֵי וְאִימוֹרָאֵי וּפְרִיזָאֵי וְחִיוָאֵי וִיבוּסָאֵי לְאַרְעָא עַבְדָא חֲלָב וּדְבָשׁ\",0,0],[4,143,3,18,\"וִיקַבְּלוּן מִינָךְ וְתֵיעוּל אַנְתְּ וְסָבֵי יִשְרָאֵל לְוַת מַלְכָּא דְמִצְרַיִם וְתֵימְרוּן לֵיהּ יְיָ אֱלָהָא דִיהוּדָאֵי אִתְקְרֵי עֲלָנָא וּכְדוּן נֵזֵיל כְּדוּן מַהֲלָךְ תְּלָתָא יוֹמִין בְּמַדְבְּרָא וּנְדַבַּח קֳדָם יְיָ אֱלָהָנָא\",0,0],[4,143,3,19,\"וַאֲנָא קֳדָמַי גְלֵי אֲרוּם לָא יִשְׁבּוֹק יַתְכוֹן מַלְכָּא דְמִצְרַיִם לְמֵיזַל וְלָא מִן דְחֵילֵיהּ תַּקִיף אֱלָהֵין בְּגִין דִבְמֵימְרִי לְאוֹכְחוֹתֵיהּ בְּמַכְתָּשִׁין בִּישִׁין\",0,0],[4,143,3,20,\"וְתִתְעַכְּבוּן תַּמָן עַד דְאֵשַׁדַר יַת מְחַת גְבוּרְתִּי וְאִמְחֵי יַת מִצְרָאֵי בְּכָל פְּרִשְׁוָותִי דְאֶעְבַּד בֵּינֵיהוֹן וּמִבָּתַר כֵּן יִפְטוֹר יַתְכוֹן\",0,0],[4,143,3,21,\"וְאֶתֵּן יַת עַמָא הָדֵין לְרַחֲמִין בְּעֵינֵי מִצְרָאֵי וִיהֵי אֲרוּם תַּחֲכוּן מִן תַּמָן פְּרוּקִין לָא תַהֲכוּן רֵיקָנִין\",0,0],[4,143,3,22,\"וְתִשְׁאַל אִתְּתָא מִן שְׁבַבְתָּא וּמִן קְרִיבַת כּוֹתְלֵי בֵיתָהּ מָנִין דִכְסַף וּמָנִין דִדְהַב וּלְבוּשִׁין וּתְעַטְרוּן עַל בָּנֵיכוֹן וְעַל בְּנָתֵיכוֹן וּתְרוֹקִינוּן יַת מִצְרָאֵי\",0,0],[4,143,4,1,\"וְאָתֵיב משֶׁה וַאֲמַר וְהָא לָא יְהֵימְנוּן לִי וְלָא יְקַבְּלוּן מִנִי אֲרוּם יֵימְרוּן לָא אִיתְגְלֵי לָךְ יְיָ\",0,0],[4,143,4,2,\"וַאֲמַר לֵיהּ יְיָ מַה דִין בִּידָךְ וַאֲמַר חוּטְרָא\",0,0],[4,143,4,3,\"וַאֲמַר טְלוֹק יָתֵיהּ לְאַרְעָא וְטַלְקֵיהּ לְאַרְעָא וַהֲוָה לְחִוְיָא וַעֲרַק משֶׁה מִן קֳדָמוֹי\",0,0],[4,143,4,4,\"וַאֲמַר יְיָ לְמשֶה אוֹשִׁיט יְדָךְ וְאֵיחוּד בְּקוּטְנֵיהּ וְאוֹשִׁיט יְדֵיהּ וְאַתְקֵיף בֵּיהּ וַהֲוָה לְחוּטְרָא בִּידֵיהּ\",0,0],[4,143,4,5,\"מִן בִּגְלַל דִיהֵמְנוּן אֲרוּם אִתְגְלֵי לָךְ יְיָ אֱלָהָא דְאַבָהַתְכוֹן אֱלָהֵיהּ דְאַבְרָהָם אֱלָהֵיהּ דְיִצְחָק וֵאלָהֵיהּ דְיַעֲקב\",0,0],[4,143,4,6,\"וַאֲמַר יְיָ לֵיהּ תּוּב אָעֵל כְּדוֹן יְדָךְ בְּחוּבָךְ וְאָעֵיל יָתֵיהּ בְּגוֹ חוּבֵיהּ וְהַנְפָּקָהּ וְהָא יְדֵיהּ סְגִירְתָּא מְחַוְורָא הִיא כְּתַלְגָא\",0,0],[4,143,4,7,\"וַאֲמַר אָתֵיב יְדָךְ לְעִיטְפָךְ וְאָתֵיב יְדֵיהּ לְחוּבֵיהּ וְהַנְפָּקָהּ מִן גוֹי חוּבֵיהּ וְתָבַת לְמֶהֱוֵי בַרְיָא הֵי כְּבִישְרֵיהּ\",0,0],[4,143,4,8,\"וִיהֵי אִם לָא יְהֵימְנוּן לָךְ וְלָא יְקַבְּלוּן לְקַל אָתָא קַדְמָאָה וִיהֵמְנוּן לְקַל אָתָא בַּתְרָאָה\",0,0],[4,143,4,9,\"וִיהֵי אִין לָא יְהֵימְנוּן אוּף לִתְרֵין אָתַיָא הָאִילֵן וְלָא יְקַבְּלוּן מִינָךְ וְתִסַב מִן מוֹי דִבְנַהֲרָא וְתֵשׁוֹד לְיַבֶּשְׁתָּא וִיהוֹן מוֹי דְתִיסַב מִן נַהֲרָא וִיהוֹן לִדְמָא בְּיַבֶּשְׁתָּא\",0,0],[4,143,4,10,\"וַאֲמַר משֶׁה קֳדָם יְיָ בְּבָעוּ יְיָ לָא גְבַר דַבְּרָן אֲנָא אוּף מֵאִתְמְלֵי אוּף מִן לְקָדָמוֹי אוּף מִן שַׁעְתָּא דְמַלֵילְתָּא עִם עַבְדָךְ אֲרוּם חֲגַר פּוּם וַחֲגַר מַמְלֵל אֲנָא\",0,0],[4,143,4,11,\"וַאֲמַר יְיָ לֵיהּ מַאן הוּא דְשַׁוֵי מַמְלֵל פּוּמָא בְּפוּם אָדָם קַדְמָאִי אוֹ מַאן שַׁוִי אַלִימָא אוֹ חַרְשָׁא אוֹ פִּתִיחָא אוֹ סַמְיָא הֲלָא אֲנָא יְיָ\",0,0],[4,143,4,12,\"וּכְדוֹן אִיזֵל וַאֲנָא בְּמֵימְרִי אֱהֵא עִם מַמְלֵל פּוּמָךְ וַאֲלִיף יָתָךְ מַה דִתְמַלֵיל\",0,0],[4,143,4,13,\"וַאֲמַר בְּבָעוּ בְּרַחֲמִין מִן קֳדָמָךְ יְיָ שְׁלַח כְּדוֹן שְׁלִיחוּתָךְ בְּיַד פִּנְחָס דְחָמֵי לְמִשְׁתַּלְחָא בְּסוֹף יוֹמַיָא\",0,0],[4,143,4,14,\"וּתְקֵיף רוּגְזָא דַיְיָ בְּמשֶׁה וַאֲמַר הֲלָא אַהֲרן אָחוּךְ לֵיוָאֵי גְלֵי קֳדָמַי אֲרוּם מַלָלָא יְמַלֵיל הוּא וְאוּף הָא הוּא נָפֵיק לִקְדָמוּתָךְ וְיַחֲמִינָךְ וִיחֲדֵי בְּלִבֵּיהּ\",0,0],[4,143,4,15,\"וּתְמַלֵל עִמֵיהּ וּתְשַׁוֵי יַת פִּתְגָמַיָא בְּפוּמֵיהּ וּמֵימְרִי יְהֵי עִם מֵימַר פּוּמָךְ וְעִם מֵימַר פּוּמֵיהּ וְאַלִיף יַתְכוֹן יַת מַה דְתַעַבְּדוּן\",0,0],[4,143,4,16,\"וִימַלֵיל הוּא לָךְ עִם עַמָא וִיהֵי הוּא יֶהֱוֵי לָךְ לִמְתֻּרְגְמִין וְאַנְתְּ תֶּהֱוֵי לֵיהּ לְרַב תְּבוֹעַ אוּלְפַן מִן קֳדָם יְיָ\",0,0],[4,143,4,17,\"וְיַת חוּטְרָא הָדֵין תִּיסַב בִּידָךְ דִתַעֲבֵיד בֵּיהּ יַת אָתַיָיא\",0,0],[4,143,4,18,\"וַאֲזַל משֶׁה וְתַב לְוַת יִתְרוֹ חָמוֹי וַאֲמַר לֵיהּ אֵיזִיל כְּדוּן לְוַת אַחַי דִבְמִצְרַיִם וְאֵיחְמֵי הַעַד כְּדוּן אִינוּן קַיְימִין וַאֲמַר יִתְרוֹ לְמשֶׁה אֵיזֵיל לִשְׁלָם\",0,0],[4,143,4,19,\"וַאֲמַר יְיָ לְמשֶׁה בְּמִדְיָן אִיזֵיל תּוּב לְמִצְרַיִם אֲרוּם אִתְרוֹקְנוּ וְנַחֲתוּ מִנִכְסֵיהוֹן וְהָא אִינוּן חֲשִׁיבוּן כְּמֵתַיָא כָּל גוּבְרַיָא דַהֲווֹ תַּבְעִין יַת נַפְשָׁךְ לְמִיסַב יָתָהּ\",0,0],[4,143,4,20,\"וּדְבַר משֶׁה יַת אִינְתְּתֵיהּ וְיַת בְּנוֹי וְאַרְכְּבִינוּן עַל חַמְרָא וְתַב לְאַרְעָא דְמִצְרַיִם וּנְסֵיב משֶׁה יַת חוּטְרָא דְנָסַב מִן גִנוּנִיתָא דְחָמוֹי וְהוּא מִסַפִּיר כּוּרְסֵי יְקָרָא מַתְקְלֵיהּ אַרְבְּעִין סְאִין וְעִילוֹ חָקוּק וּמְפָרֵשׁ שְׁמָא רַבָּא וְיַקִירָא וּבֵיהּ אִתְעֲבִידוּ נִיסִין מִן קֳדָם יְיָ בִּידֵיהּ\",0,0],[4,143,4,21,\"וַאֲמַר יְיָ לְמשֶׁה בִּמְהָכָךְ לְמֵיתוּב לְמִצְרַיִם חֲמִי כָּל תִּמְהַיָא דְשַׁוִיתִי בִידָךְ וְתַעֲבִידִינוּן קֳדָם פַּרְעה וַאֲנָא אַתְקֵיף יַת יִצְרָא דְלִבֵּיהּ וְלָא יִפְטוֹר יַת עַמָא\",0,0],[4,143,4,22,\"וְתֵימַר לְפַרְעה כִּדְנָא אָמַר יְיָ בְּרִי בּוּכְרִי יִשְרָאֵל\",0,0],[4,143,4,23,\"וַאֲמָרִית לָךְ פְּטוֹר יַת בְּרִי וְיִפְלַח קֳדָמַי וּמְסָרֵב אַנְתְּ לְמִפְטְרֵיהּ הָא אֲנָא קָטֵיל יַת בְּרָךְ בּוּכְרָךְ\",0,0],[4,143,4,24,\"וַהֲוָה בְאוֹרְחָה בְּבֵית מִבְתּוֹתָא וְעַרַע בֵּיהּ מַלְאָכָא דַיְיָ וּבְעָא לְמִקְטְלֵיהּ מִן בִּגְלַל גֵרְשׁוֹם בְּרֵיהּ דְלָא הֲוָה גְזִיר עַל עֵיסַק יִתְרוֹ חָמוֹי דְלָא שַׁבְקֵיהּ לְמִגְזְרֵיהּ בְּרַם אֱלִיעֶזֶר הֲוָה גָזַר בִּתְּנָאָה דְאַתְנִיוּ תַּרְוֵיהוֹן\",0,0],[4,143,4,25,\"וּנְסִיבַת צִפּוֹרָה טִינְרָא וּגְזָרַת יַת עוּרְלַת גֵרְשׁוֹם בְרָהּ וְאַקְרִיבַת יַת גְזֵירַת מָהוּלְתָּא לְרַגְלוֹי דְמַלְאָךְ חַבָּלָא וַאֲמָרַת חַתְנָא בְּעָא לְמִיגְזוֹר וְחָמוֹי עַכִּיב וּכְדוֹן אֲדָם גְזוּרְתָּא הָדֵין יְכַפֵּר עַל חַתְנָא דִילִי\",0,0],[4,143,4,26,\"וּפְסַק מַלְאָךְ חַבָּלָא מִנֵיהּ בְּכֵן שַׁבְּחַת צִפּוֹרָה וַאֲמַרַת מַה חָבִיב הוּא אֲדָם גְזוּרְתָּא הָדֵין דְשֵׁזִיב יַת חֲתָנָא מִן יְדוֹי דְמַלְאָךְ חֲבָּלָא\",0,0],[4,143,4,27,\"וַאֲמַר יְיָ לְאַהֲרן אִיזֵיל לְקַדְמוּת משֶׁה לְמַדְבְּרָא וַאֲזַל וְאַרְעֵיהּ בְּטַוְורָא דְאִתְגְלֵי עֲלוֹי יְקָרָא דַיְיָ וּנְשֵׁיק לֵיהּ\",0,0],[4,143,4,28,\"וּתְנֵי משֶׁה לְאַהֲרן יַת פִּתְגָמָא הָאִלֵין דְשַׁלְחֵיהּ וְיַת כָּל אָתַיָא דְפַקְדֵיהּ לְמֶעֱבַד\",0,0],[4,143,4,29,\"וַאֲזַל משֶׁה וְאַהֲרן וּכְנָשׁוּ יַת כָּל סָבֵי בְּנֵי יִשְרָאֵל\",0,0],[4,143,4,30,\"וּמַלֵיל אַהֲרן יַת פִּתְגָמַיָא דְמַלֵיל יְיָ עִם משֶׁה וְעָבַד אָתַיָא לְעֵינֵי עַמָא\",0,0],[4,143,4,31,\"וְהֵימִין עַמָא וּשְׁמָעוּ אֲרוּם דְכִיר יְיָ יַת בְּנֵי יִשְרָאֵל וַאֲרוּם גְלֵי קֳדָמוֹי שִׁעְבּוּדְהוֹן וּגְחָנַן וּסְגִידוּ\",0,0],[4,143,5,1,\"וּבָתַר כְּדֵין עָלוּ משֶׁה וְאַהֲרן וַאֲמָרוּ לְפַרְעה כִּדְנָא אָמַר יְיָ אֱלָהָא דְיִשְרָאֵל פְּטוֹר יַת עַמִי וְיַעַבְדוּן לִי חַגָא בְּמַדְבְּרָא\",0,0],[4,143,5,2,\"וַאֲמַר פַּרְעה שְׁמָא דַיְיָ לָא אִיתְגְלֵי לִי דַאֲקַבֵּל בְּמֵימְרֵיהּ לְמִפְטוֹר יַת יִשְרָאֵל לָא אַשְׁכָּחִית בְּסֵפֶר מַלְאָכַיָא כְּתִיב יַת שְׁמָא דַיְיָ מִינֵהּ לֵית אֲנָא דָחִיל וְאוּף יַת יִשְרָאֵל לָא אִיפְטוֹר\",0,0],[4,143,5,3,\"וַאֲמָרוּ אֱלָהָא דִיהוּדָאֵי אִיתְקְרִי שְׁמֵיהּ עֲלָנָא נְטַיֵיל כְּדוֹן מַהֲלָךְ תְּלָתָא יוֹמִין בְּמַדְבְּרָא וּנְדַבַּח נִיכְסַת חַגָא קֳדָם יְיָ אֱלָהִין דִלְמָא יֶאֱרַע יָתָן בְּמוֹתָא אוֹ בְּקַטְלָא\",0,0],[4,143,5,4,\"וַאֲמַר לְהוֹן מַלְכָּא דְמִצְרַיִם לְמָא משֶׁה וְאַהֲרן תְּבַטְלוּן יַת עַמָא מֵעֲבִידְתְּהוֹן אִיזִילוּ לְפוּלְחַנְכוֹן\",0,0],[4,143,5,5,\"וַאֲמַר פַּרְעה הָא סַגִין הִינוּן כְּדוּן עַמָא דְאַרְעָא דְאַתּוּן מְבַטְלִין יַתְהוֹן מִפּוּלְחַנְהוֹן\",0,0],[4,143,5,6,\"וּפַקֵיד פַּרְעה בְּיוֹמָא הַהוּא יַת שׁוּלְטָנַיָא דְעַמָא וְיַת סַרְכוֹי לְמֵימָר\",0,0],[4,143,5,7,\"לָא תוֹסְפוּן לְמִיתַּן תִּיבְנָא לְעַמָא לְמִירְמֵי לִבְנַיָא הֵי כְמֵאִיתְמְלֵי וְהֵי כְמִלְקָדָמוֹי הִינוּן יֵזְלוּן וִיגַבְּבוּן לְהוֹן תִּבְנָא\",0,0],[4,143,5,8,\"וְיַת סְכוּם לִבְנַיָא דְהִינוּן עָבְדִין מֵאִיתְמְלֵי וּמִדְקָדָמוֹי תְּמַנוּן עֲלֵיהוֹן לָא תִמְנְעוּן מִנֵיהּ אֲרוּם בַּטְלָנִין הִינוּן בְּגִין כֵּן הִינוּן צַוְוחִין לְמֵימַר נֵיזִיל נְדַבַּח נִיכְסַת חַגָא קֳדָם אֱלָהָנָא\",0,0],[4,143,5,9,\"תִּתְקַף פּוּלְחָנָא עִלוֹי גוּבְרַיָא וְיִתְעַסְקוּן בָּה וְלָא יִתְרַחֲצוּן עַל מִילֵי שִׁקְרָא\",0,0],[4,143,5,10,\"וּנְפָקוּ שׁוּלְטָנֵי עַמָא וְסַרְכוֹי וַאֲמָרוּ לְעַמָא כִּדְנָא אֲמַר פַּרְעה לֵית אֲנָא יָהִיב לְכוֹן תִּיבְנָא\",0,0],[4,143,5,11,\"אַתּוּן אִיזִילוּ סָבוּ לְכוֹן תִּיבְנָא מִן אָתַר דְתִשְׁכְּחוּן אֲרוּם לָא מִתְמְנַע מִפּוּלְחַנְכוֹן מִדָעַם\",0,0],[4,143,5,12,\"וְאִתְבַּדַר עַמָא בְכָל אַרְעָא דְמִצְרַיִם לְגַבְבָא גִילֵי לְתִיבְנָא\",0,0],[4,143,5,13,\"וְשׁוּלְטָנַיָא דַחֲקִין לְמֵימָר אַשְׁלִימוּ עֲבִידַתְכוֹן פִּתְגָם יוֹם בְּיוֹמֵיהּ הֵיכְמָא דַהֲוֵיתוּן עָבְדִין כַּד הֲוָה יָהֵיב לְכוֹן תִּיבְנָא\",0,0],[4,143,5,14,\"וְלָקוּ סַרְכֵי בְּנֵי יִשְרָאֵל דְמַנוּ עֲלֵיהוֹן שׁוּלְטָנֵי פַרְעה לְמֵימָר לְמָא דֵין לָא אַשְׁלַמְתּוּן גְזֵירַתְכוֹן לְמִירְמֵי לִבְנִין הֵי כְמֵאִיתְמְלֵי וְהֵי כְמִדְקָדָמוֹי אוּף אִיתְמְלֵי אוּף יוֹמָא דֵין\",0,0],[4,143,5,15,\"וְאָתוֹ סַרְכֵי בְּנֵי יִשְרָאֵל וּצְוָוחוּ קֳדָם פַּרְעה לְמֵימַר לְמָא תַעֲבֵיד כְּדֵין לְעַבְדָךְ\",0,0],[4,143,5,16,\"תִּבְנָא לָא מִתְיַהַב לְעַבְדָךְ וְלִבְנַיָא אָמְרִין לָנָא עִיבִידוּ וְהָא עַבְדָךְ לַקְיָין וּחְיוּבְתְּהוֹן דְעַמָךְ תָּקְפָא וְסַלְקָא\",0,0],[4,143,5,17,\"וַאֲמַר בַּטְלָנִין אַתּוּן בַּטְלָנִין בְּגִין כֵּן אַתּוּן אָמְרִין נֵזִיל נְדַבַּח נִכְסַת חַגָא קֳדָם אֱלָהָנָא\",0,0],[4,143,5,18,\"וּכְדוּן אִיזִילוּ פְלָחוּ וְתִיבְנָא לָא יִתְיַהֵב לְכוֹן וּסְכוּם לִבְנַיָא תִּתְּנוּן\",0,0],[4,143,5,19,\"וְחָמוּן סַרְכֵי בְנֵי יִשְרָאֵל יַתְהוֹן בְּבִישׁ לְמֵימָר לָא תִמְנְעוּן מִלִבְנֵיכוֹן דְפִתְגַם יוֹם בְּיוֹמֵי\",0,0],[4,143,5,20,\"וַעֲרָעוּ יַת משֶׁה וְיַת אַהֲרן קַיְימִין לִקְדָמוּתְהוֹן בְּמִיפַּקְהוֹן מִן קֳדָם פַּרְעה\",0,0],[4,143,5,21,\"וַאֲמָרוּ לְהוֹן יִתְגְלֵי קֳדָם יְיָ עוּלְבָּנָנָא וּלְחוֹד יִתְפְּרַע מִנְכוֹן דְאַסְרַחֲתּוּן יַת רֵיחָנָא קֳדָם פַּרְעה וְקָדָם עַבְדוֹי דְגֵרַמְתּוּן לְמִיתַּן סַיְיפָא בִידֵיהוֹן לְמִקְטְלָנָא\",0,0],[4,143,5,22,\"וְתַב משֶׁה לִקֳדָם יְיָ וַאֲמַר יְיָ לְמָא אַבְאֶשְׁתָּא לְעַמָא הָדֵין וּלְמָא דְנַן שְׁלַחְתָּנִי\",0,0],[4,143,5,23,\"וּמִן שַׁעְתָּא דְעָלִית לְוַת פַּרְעה לְמַלָלָא בִשְׁמָךְ אִתְבְּאֵשׁ לְעַמָא הָדֵין וְשֵׁיזְבָא לָא שֵׁיזַבְתָּא יַת עַמָךְ\",0,0],[4,143,6,1,\"וַאֲמַר יְיָ לְמשֶׁה כְּדוֹן תֶּחְמֵי מָה אַעֲבֵד לְפַרְעה אֲרוּם בִּידָא תַקִיפְתָּא יִפְטוֹרִינוּן וּבִידָא תַקִיפְתָּא יְתָרֵיכִינוּן מִן אַרְעֵיהּ\",0,0],[4,143,6,2,\"וידבר וּמַלֵיל יְיָ עִם משֶׁה וַאֲמַר לֵיהּ אֲנָא יְיָ הוּא דְאִתְגְלֵיתִי עֲלָךְ בְּגוֹ סַנְיָא וַאֲמָרִית לָךְ אֲנָא יְיָ\",0,0],[4,143,6,3,\"וְאִיתְגְלֵיתִי לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקב בְּאֵל שַׁדָי וּשְׁמִי יְיָ בְּרַם בְּאַפֵּי שְׁכִינְתִּי לָא אִתְיְדִיעַת לְהוֹן\",0,0],[4,143,6,4,\"וּלְחוֹד אַקֵימִית יַת קְיָימִי עִמְהוֹן לְמִתַּן לְהוֹן יַת אַרְעָא דִכְנָעַן יַת אַרַע תּוֹתָבוּתְהוֹן דְאִיתּוֹתְבוּ בָהּ\",0,0],[4,143,6,5,\"וּלְחוֹד עָל קֳדָמַי יַת אֲנֵיק בְּנֵי יִשְרָאֵל דְמִצְרָאֵי מְשַׁעֲבְּדוּן יַתְהוֹן וּדְכִירְנָא יַת קְיָימִי\",0,0],[4,143,6,6,\"בְּכֵן אֵימַר לִבְנֵי יִשְרָאֵל אֲנָא הוּא יְיָ וְאַפֵּיק יַתְכוֹן מִגוֹ דְחוֹק פּוּלְחַן מִצְרָאֵי וְאֵישֵׁיזִיב יַתְכוֹן מִפּוּלְחַנְהוֹן וְאֶפְרוֹק יַתְכוֹן בִּדְרַע מְרוֹמָא וּבְדִינִין רַבְרְבִין\",0,0],[4,143,6,7,\"וַאֲקַרֵב יַתְכוֹן קֳדָמַי לְעַם וְאֶהֱוֵי לְכוֹן לֶאֱלָהָא וְתֵידְעוּן אֲרוּם אֲנָא יְיָ אֳלָהָכוֹן דְאַנְפֵּיק יַתְכוֹן מִגוֹ דְחוֹק פּוּלְחַן מִצְרָאֵי\",0,0],[4,143,6,8,\"וְאָעִיל יַתְכוֹן דְקַיְימִית בְּמֵימְרִי לְמִתַּן יָתָהּ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקב וְאֶתֵּן יָתָהּ לְכוֹן יְרוּתָא אֲנָא יְיָ\",0,0],[4,143,6,9,\"וּמַלֵיל משֶׁה כְּדֵין עִם בְּנֵי יִשְרָאֵל וְלָא קַבִּילוּ מִן משֶׁה מִקְפִּידוּת רוּחָא וּמִפּוּלְחָנָא נוּכְרָאָה קַשְׁיָא דִי בִּידֵיהוֹן\",0,0],[4,143,6,10,\"וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר\",0,0],[4,143,6,11,\"עוּל מַלֵיל עִם פַרְעה מַלְכָּא דְמִצְרָיִם וְיִפְטוֹר יַת בְּנֵי יִשְרָאֵל מֵאַרְעֵיהּ\",0,0],[4,143,6,12,\"וּמַלֵיל משֶׁה קֳדָם יְיָ לְמֵימָר הָא בְּנֵי יִשְרָאֵל לָא קַבִּילוּ מִינִי וְהֵיכְדֵין יְקַבֵּיל מִינִי פַּרְעה וַאֲנָא קְשֵׁי מַמְלֵיל\",0,0],[4,143,6,13,\"וּמַלֵיל יְיָ עִם משֶׁה וְעִם אַהֲרן וְאַזְהַרִינוּן עַל בְּנֵי יִשְרָאֵל וְשַׁלְחִינוּן לְוַת פַּרְעה מַלְכָּא דְמִצְרַיִם לְאַפָּקָא יַת בְּנֵי יִשְרָאֵל מֵאַרְעָא דְמִצְרַיִם\",0,0],[4,143,6,14,\"אִלֵין רֵישֵׁי בֵית אֲבָהַתְהוֹן בְּנוֹי דִרְאוּבֵן בּוּכְרָא דְיִשְרָאֵל חֲנוֹךְ וּפַלוּא חֶצְרוֹן וְכַרְמִי אִלֵין יֵיחוּסִין דִרְאוּבֵן\",0,0],[4,143,6,15,\"וּבְנוֹי דְשִׁמְעוֹן יְמוּאֵל וְיָמִין וְאוֹהַד וְיָכִין וְצוֹחַר וְשָׁאוּל הוּא זִמְרִי דְאַשְׁאִיל נַפְשֵׁיהּ לִזְנוּתָא הֵי בִּכְנַעֲנָאֵי אִלֵין יֵיחוּסִין דְשִׁמְעוֹן\",0,0],[4,143,6,16,\"וְאִלֵין שְׁמָהַת בְּנוֹי דְלֵוִי לְיִיחוּסֵיהוֹן גֵרְשׁוֹן וּקְהָת וּמְרָרִי וּשְׁנֵי חַיוֹי דְלֵוִי מְאָה וּתְלָתִין וּשְׁבַע שְׁנִין חַיָיא עַד דְחָמָא יַת משֶׁה וְיַת אַהֲרן פְּרִיקַיָיא דְיִשְרָאֵל\",0,0],[4,143,6,17,\"בְּנוֹי דְגֵרְשׁוֹם לִבְנִי וְשִׁמְעִי לְיִיחוּסֵיהוֹן\",0,0],[4,143,6,18,\"וּבְנוֹי דִקְהָת עַמְרָם וְיִצְהָר וְחֶבְרוֹן וְעֻזִיאֵל וּשְׁנֵי חַיוֹי דִקְהָת חֲסִידָא מְאָה וּתְלָתִין וּתְלַת שְׁנִין חַיָיא עַד דְחָמָא יַת פִּינְחָס הוּא אֵלִיָהוּ כַּהֲנָא רַבָּא דְעָתִיד לְמִשְׁתַּלְחָא לְגָלוּתָא דְיִשְרָאֵל בְּסוֹף יוֹמַיָא\",0,0],[4,143,6,19,\"וּבְנוֹי דִמְרָרִי מַחְלִי וּמוּשִׁי אִלֵין יְחוּסִין דְלֵוִי לִגְנִסְתְּהוֹן\",0,0],[4,143,6,20,\"וּנְסֵיב עַמְרָם יַת יוֹכֶבֶד חֲבִבָתֵיהּ לֵיהּ לְאִנְתּוּ וִילֵידַת לֵיהּ יַת אַהֲרן וְיַת משֶׁה וּשְׁנֵי חַיוֹי דְעַמְרָם חֲסִידָא מְאָה וּתְלָתִין וּשְׁבַע שְׁנִין חַיָיא עַד דְחָמָא יַת בְּנֵי רְחַבְיָא בַּר גֵרְשׁוֹם בַּר משֶׁה\",0,0],[4,143,6,21,\"וּבְנוֹי דְיִצְהָר קרַח וָנֶפֶג וְזִכְרִי\",0,0],[4,143,6,22,\"וּבְנוֹי דְעֻזִיאֵל מִישָׁאֵל וְאֶלְצָפָן וְסִתְרִי\",0,0],[4,143,6,23,\"וּנְסֵיב אַהֲרן יַת אֱלִישֶׁבַע בְּרַת עַמִינָדָב אֲחָתֵיהּ דְנַחֲשׁוֹן לֵיהּ לְאִנְתּוּ וִילֵידַת לֵיהּ יַת נָדָב וְיַת אֲבִיהוּא יַת אֶלְעָזָר וְיַת אִיתָמָר\",0,0],[4,143,6,24,\"וּבְנוֹי דְקרַח אַסִיר וְאֶלְקָנָה וַאֲבִיאָסָף אִלֵין יֵיחוּסֵי דְקרַח\",0,0],[4,143,6,25,\"וְאֶלְעָזָר בַּר אַהֲרן נְסִיב לֵיהּ מִבְּרַתּוֹי דְיִתְרוֹ הוּא פּוּטִיאֵל לֵיהּ לְאִנְתּוּ וִילֵידַת לֵיהּ יַת פִּינְחָס אִלֵין רֵישֵׁי אַבְהַת לֵיוָאֵי ְיִיחוּסֵיהוֹן\",0,0],[4,143,6,26,\"אִיהוּ אַהֲרן וּמשֶׁה דַאֲמַר יְיָ לְהוֹן הַנְפִּיקוּ יַת בְּנֵי יִשְרָאֵל פְּרִיקִין מֵאַרְעָא דְמִצְרַיִם עַל חֵילֵיהוֹן\",0,0],[4,143,6,27,\"הִינוּן דְמַלְלִין עִם פַּרְעה מַלְכָּא דְמִצְרַיִם לְהַנְפָּקָא יַת בְּנֵי יִשְרָאֵל מִמְצְרַיִם הוּא משֶׁה נְבִיָא וְאַהֲרן כַּהֲנָא\",0,0],[4,143,6,28,\"וַהֲוָה בְּיוֹמָא דְמַלֵיל יְיָ עִם משֶׁה בְּאַרְעָא דְמִצְרַיִם הֲוָה אַהֲרן מָצִית אוּדְנֵיהּ וְשָׁמַע מַה דְמַלֵיל עִמֵיהּ\",0,0],[4,143,6,29,\"וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר אֲנָא הוּא יְיָ מַלֵיל עִם פַרְעה מַלְכָּא דְמִצְרַיִם יַת כָּל דַאֲנָא מְמַלֵיל עִמָךְ\",0,0],[4,143,6,30,\"וַאֲמַר משֶׁה קֳדָם יְיָ הָאֲנָא קָשֵׁי מַמְלֵל וְאֵכְדֵין יְקַבֵּל מִנִי פַּרְעה\",0,0],[4,143,7,1,\"וַאֲמַר יְיָ לְמשֶׁה לְמָא אַנְתְּ מִסְתְּפֵי חָמֵי דִכְבַר שַׁוִית יָתָךְ דְחִילָא לְפַרְעה כְּאִילוּ אֱלָהָא דִילֵיהּ וְאַהֲרן אָחוּךְ יְהֵא נְבִיָא דִילָךְ\",0,0],[4,143,7,2,\"אַנְתְּ תְּמַלֵיל לְאַהֲרן יַת כָּל דְאִיפַקְדִינָךְ וְאַהֲרן אָחוּךְ יְמַלֵיל לְפַרְעה וְיִפְטוֹר יַת בְּנֵי יִשְרָאֵל מֵאַרְעֵיהּ\",0,0],[4,143,7,3,\"וַאֲנָא אַקְשֵׁי יַת יִצְרָא דְלִבָּא דְפַרְעה וְאַסְגֵי יַת אַתְוָותַי וְיַת תִמְהַיַי בְּאַרְעָא דְמִצְרָיִם\",0,0],[4,143,7,4,\"וְלָא יְקַבֵּל מִנְכוֹן פַּרְעה וְאִיגָרֵי בְּהוֹן גִירִין דִקְטוֹל וְאֶתֵּן מְחַת גְבוּרַת יְדִי בְּמִצְרָיִם וְאַפֵּיק יַת עַמִי בְּנֵי יִשְרָאֵל פְּרִיקִין מֵאַרְעָא דְמִצְרַיִם בְּדִינִין רַבְרְבִין\",0,0],[4,143,7,5,\"וְיִנְדְעוּן מִצְרָאֵי אֲרוּם אֲנָא הוּא יְיָ כַּד אָרִים יַת מְחַת גְבוּרְתִּי עַל מִצְרָיִם וְאַנְפֵּיק יַת בְּנֵי יִשְרָאֵל פְּרִיקִין מִבֵּינֵיהוֹן\",0,0],[4,143,7,6,\"וַעֲבַד משֶׁה וְאַהֲרן הֵיכְמָא דְפַקֵיד יְיָ יַתְהוֹן הֵיכְדֵין עָבָדוּ\",0,0],[4,143,7,7,\"וּמשֶׁה בַּר תַּמְנָן שְׁנִין וְאַהֲרן בַּר תַּמְנָן וּתְלַת שְׁנִין בְּמַלָלוּתְהוֹן עִם פַּרְעה\",0,0],[4,143,7,8,\"וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרן לְמֵימָר\",0,0],[4,143,7,9,\"אֲרוּם יְמַלֵיל עִמְכוֹן פַּרְעה לְמֵימַר הָבוּ לְכוֹן תִּימְהָא וְתֵימַר לְאַהֲרן סַב יַת חוּטְרָךְ וּטְלוֹק יָתֵיהּ קֳדָם פַּרְעה יְהֵי לְחִיוִי חוּרְמַן אֲרוּם עֲתִידִין כָּל דַיְירֵי אַרְעָא לְמִשְׁמַע קַל צְוָוחַתְהוֹן דְמִצְרַיִם בְּתַבְרוּתִי יַתְהוֹן הֵיכְמָא דִשְׁמָעַן כָל בִּרְיָיתָא יַת קַל צְוָוחַת חִוְיָא כַּד אִיתְעַרְטִיל מִן שֵׁירוּיָא\",0,0],[4,143,7,10,\"וְאָעֵל משֶׁה וְאַהֲרן לְוַת פַּרְעה וְעָבָדוּ הֵיכְדֵין הֵיכְמָא דְפַקֵיד יְיָ וּטְלַק אַהֲרן יַת חוּטְרֵיהּ קֳדָם מֵיחְמֵי פַּרְעה וְקָדָם מֵיחְמֵי עַבְדוֹי וַהֲוָה לְחוּרְמָנָא\",0,0],[4,143,7,11,\"וּקְרָא לְחוֹד פַּרְעה לְחַכִּימַיָא וּלְחַרְשַׁיָא וַעֲבָדוּ לְחוֹד הִינוּן יֵנִיס וְיִמְבְּרֵיס חַרְשִׁין דִבְמִצְרַיִם בְּלַחֲשֵׁי קוּסְמֵיהוֹן הֵיכְדֵין\",0,0],[4,143,7,12,\"וּטְלָקוּן אֵינַשׁ חוּטְרֵיהּ וַהֲווֹ לְחָרְמָנִין וּמִן יַד אִתְהֲפִּיכוּ לְמֶהֱוֵי כְּמִן שֵׁירוּיָא וּבְלַע חוּטְרָא דְאַהֲרן יַת חוּטְרֵיהוֹן\",0,0],[4,143,7,13,\"וְאִיתְקַף יִצְרָא דְלִבָּא דְפַרְעה וְלָא קַבֵּיל מִנְהוֹן הֵיכְמָא דְמַלֵל יְיָ\",0,0],[4,143,7,14,\"וַאֲמַר יְיָ לְמשֶׁה אִיתְקַף יִצְרָא דְלִבָּא דְפַרְעה מְסָרֵב לְמִפְטוֹר יַת עַמָא\",0,0],[4,143,7,15,\"אִיזֵיל לְוַת פַּרְעה בְּצַפְרָא הָא נָפֵיק לְמִנְטוֹר קוּסְמִין עִילַוֵי מַיָא הֵי כְּאַמְגוֹשָׁא וְתִתְעַתַּד לְקָדָמוּתֵיהּ עַל גֵיף נַהֲרָא וּבְרַם חוּטְרָא דְאַהֲרן דְאִתְהֲפִיךְ לְחִיוֵי תִּיסֵב בִּידָךְ\",0,0],[4,143,7,16,\"וְתֵימַר לֵיהּ יְיָ אֱלָהָא דִיהוּדָאֵי שַׁדְרַנִי לְוָתָךְ לְמֵימַר פְּטוֹר יַת עַמִי וְיִפְלְחוּן קֳדָמַי בְּמַדְבְּרָא וְהָא לָא קַבֵּילְתָּ עַד כְּדוּן\",0,0],[4,143,7,17,\"כִּדְנָא אֲמַר יְיָ בְּדָא סִימָנָא תִנְדַע אֲרוּם אֲנָא יְיָ הָא אֲנָא מָחֵי בְּחוּטְרָא דְבִידִי עַל מוֹי דִי בְנַהֲרָא וְיִתְהַפְּכִין לְאַדְמָא\",0,0],[4,143,7,18,\"וְנוּנֵי דִבְנַהֲרָא יְמוּתִין וְיִסְרֵי נַהֲרָא וְיִשְׁתַּלְהוֹן מִצְרָאֵי לְמִשְׁתֵּי מוֹי מִן נַהֲרָא\",0,0],[4,143,7,19,\"וַאֲמַר יְיָ לְמשֶׁה אֵימַר לְאַהֲרן סַב חוּטְרָךְ וַאֲרֵים יְדָךְ עַל מוֹי דְמִצְרָאֵי עַל נַהֲרֵיהוֹן עַל פַּצִידֵיהוֹן עַל שִׁיקְיֵיהוֹן וְעַל כָּל כְּנִישׁוּת מֵימֵיהוֹן וִיהוֹן דְמָא בְּכָל אַרְעָא דְמִצְרַיִם וּבְמָאנֵי אָעָא וּבְמָאנֵי אַבְנָא\",0,0],[4,143,7,20,\"וַעֲבָדוּ הֵיכְדֵין משֶׁה וְאַהֲרן הֵיכְמָא דְפַּקֵיד יְיָ וַאֲרֵים בְּחוּטְרָא וּמְחָא יַת מוֹי דִבְנַהֲרָא לְמֶחֱמֵי פַרְעה וּלְמֶחֱמֵי עַבְדוֹי וְאִיתְהֲפִּיכוּ כָּל מוֹי דִבְנַהֲרָא לְאַדְמָא\",0,0],[4,143,7,21,\"וְנוּנֵי דִי בְנַהֲרָא מִיתוּ וּסְרִי נַהֲרָא וְלָא יָכִילוּ מִצְרָאֵי לְמִשְׁתֵּי מוֹי מִן נַהֲרָא וַהֲוַת מְחַת דְמָא בְּכָל אַרְעָא דְמִצְרַיִם\",0,0],[4,143,7,22,\"וַעֲבָדוּ הֵיכְדֵין אִצְטַגְנִינֵי מִצְרַיִם בְּלַחֲשֵׁיהוֹן וְהָפִיכוּ מִן מַיָא דְגוֹשֶׁן לְאַדְמָא וְאִיתְקֵיף יִצְרָא דְלִבָּא דְפַרְעה וְלָא קַבֵּיל מִנְהוֹן הֵיכְמָא דְמַלֵיל יְיָ\",0,0],[4,143,7,23,\"וַעֲבַד פַּרְעה צוֹרְכֵיהּ וְעָאל לְבֵיתֵיהּ וְלָא שַׁוֵי לִבֵּיהּ לְחוֹד לְמַחְתָא דָא\",0,0],[4,143,7,24,\"וַחֲפָרוּ מִצְרָאֵי חַזְרָנוֹת נַהֲרָא מוֹי לְמִשְׁתֵּי וְלָא אַשְׁכָּחוּ צְלִילִין אֲרוּם לָא יָכִילוּ לְמִשְׁתֵּי מִן מוֹי דִבְנַהֲרָא\",0,0],[4,143,7,25,\"וּשְׁלִימוּ שׁוּבְעָא יוֹמִין מִן בָּתַר דִמְחָא יְיָ יַת נַהֲרָא וּמִבָּתַר כֵּן אָסֵי מֵימְרָא דַיְיָ יַת נַהֲרָא\",0,0],[4,143,7,26,\"וַאֲמַר יְיָ לְמשֶׁה עוּל לְוַת פַּרְעה וְתֵימַר לֵיהּ כִּדְנָא אָמַר יְיָ פְּטוֹר יַת עַמִי וְיִפְלְחוּן קָדָמַי\",0,0],[4,143,7,27,\"וְאִין מְסָרֵב אַנְתְּ לְמִפְטוֹר הָא אֲנָא מָחֵי יַת כָּל תְּחוּמָךְ בְּעוּרְדְעָנַיָא\",0,0],[4,143,7,28,\"וְיִרְבֵּי נַהֲרָא עוּרְדְעָנַיָא וְיִסְקוּן וְיַעֲלוּן בְּבֵיתָךְ וּבְקִיטוּן בֵּי דַמְכָךְ וְעִילוֹי דַרְגְשָׁךְ וּבְבֵית עַבְדָךְ וּבְעַמָךְ וּבְתַנוּרָךְ וּבְאַצְוָותָךְ\",0,0],[4,143,7,29,\"וּבְגוּפָךְ וּבְגוּפֵי עַמָךְ וּבְכָל עַבְדָךְ יִשְׁלְטוּן עוּרְדְעָנַיָא\",0,0],[4,143,8,1,\"וַאֲמַר יְיָ לְמשֶׁה אֵימַר לְאַהֲרן אֲרֵים יַת יְדָךְ בְּחוּטְרָא עַל נַהֲרָא עַל פַּצִידַיָיא וְעַל שִׁיקַיָיא וְאַסֵיק יַת עוּרְדְעָנַיָא עַל אַרְעָא דְמִצְרַיִם\",0,0],[4,143,8,2,\"וַאֲרֵים אַהֲרן יַת יְדֵיהּ עַל מַיָא דְמִצְרַיִם וּסְלִיקַת מְחַת עוּרְדְעָנַיָא וַחֲפַת יַת אַרְעָא דְמִצְרָיִם בְּרַם משֶׁה לָא אַלְקֵי יַת מַיָא לָא בְּאַדְמָא וְלָא בְּעוּרְדְעָנַיָא מִן בִּגְלַל דַהֲוַת לֵיהּ בְּהוֹן שֵׁיזְבוּתָא בִּזְמַן דְטָלְקַת יָתֵיהּ אִמֵיהּ בְּנַהֲרָא\",0,0],[4,143,8,3,\"וְעָבָדוּ הֵיכְדֵין אִיסְטַגְנִינָן בְּלַחְשֵׁיהוֹן וְאַסִיקוּ יַת עוּרְדְעָנַיָא עַל אַרְעָא דְמִצְרָיִם\",0,0],[4,143,8,4,\"וּקְרָא פַּרְעה לְמשֶׁה וּלְאַהֲרן וַאֲמַר צְלוֹן קֳדָם יְיָ וְיַעֲדֵי עוּרְדְעָנַיָא מִינִי וּמִן עַמָא וְאֶפְטוֹר יַת עַמָא וְיִדְבְּחוּן נִיכְסַת חַגָא קֳדָם יְיָ\",0,0],[4,143,8,5,\"וַאֲמַר משֶׁה לְפַרְעה שַׁבַּח בְּגִינִי לְאֵימַת דְאַנְתְּ בָּעֵי אַיְצַלֵי עֲלָךְ וְעַל עַבְדָךְ וְעַל עַמָךְ לְשֵׁיצָאָה עוּרְדְעָנַיָא מִינָךְ וּמִבָּתָּךְ לְחוֹד מָה דִבְנַהֲרָא יִשְׁתַּיְירוּן\",0,0],[4,143,8,6,\"וַאֲמֵר לְמָחָר וַאֲמַר כְּפִתְגָמָךְ מִן בִּגְלַל דְתִנְדַע אֲרוּם לֵית כַּיְיָ אֱלָהָנָא\",0,0],[4,143,8,7,\"וְיַעֲדוּן עוּרְדְעָנַיָא מִינָךְ וּמִבָּתָּךְ וּמִן עַבְדָךְ וּמִן עַמָךְ לְחוֹד מַה דִבְנַהֲרָא יִשְׁתַּיְירוּן\",0,0],[4,143,8,8,\"וּנְפַק משֶׁה וְאַהֲרן מִלְוַת פַּרְעה וְצַלֵי משֶׁה קֳדָם יְיָ עַל עֵיסַק עוּרְדְעָנַיָא דְשַׁוֵי לְפַרְעה\",0,0],[4,143,8,9,\"וַעֲבַד יְיָ כְּפִתְגָמָא דְמשֶׁה וּמִיתוּ עוּרְדְעָנַיָא מִן בָּתַּיָא וּמִן דַרְתָּא וּמִן חַקְלָא\",0,0],[4,143,8,10,\"וּכְנָשׁוּ יַתְהוֹן כַּרְוַון כַּרְוַון וּסְרִיַית אַרְעָא\",0,0],[4,143,8,11,\"וַחֲמָא פַרְעה אֲרוּם הֲוָה רְוַוחְתָּא לְעַקְתֵיהּ וִיקַר יַת לִבֵּיהּ וְלָא קַבֵּיל מִנְהוֹן הֵיכְמָא דְמַלֵל יְיָ\",0,0],[4,143,8,12,\"וַאֲמַר יְיָ לְמשֶׁה אֵימַר לְאַהֲרן אֲרֵים יַת חוּטְרָךְ וּמְחֵי יַת עַפְרָא דְאַרְעָא וִיהֵי לְקַלְמֵי בְּכָל אַרְעָא דְמִצְרָיִם בְּרַם עַל יְדָךְ לֵית אֶפְשַׁר לְמִלְקֵי אַרְעָא דְבָהּ הֲוָת לָךְ שֵׁיזְבוּתָא כַּד קָטַלְתָּא יַת מִצְרָאֵי וְקַבִּילְתֵּיהּ\",0,0],[4,143,8,13,\"וַעֲבָדוּ הֵיכְדֵין וַאֲרֵים אַהֲרן יַת יְדֵיהּ בְּחוּטְרֵיהּ וּמְחָא יַת עַפְרָא דְאַרְעָא וַהֲוַת מְחַת קַלְמֵי בְּבִשְרָא דְאֵינָשָׁא וְדִבְעִירָא כָל עַפְרָא דְאַרְעָא אִיתְהֲפִּיךְ לְמֶהֱוֵי קַלְמֵי בְּכָל אַרְעָא דְמִצְרָיִם\",0,0],[4,143,8,14,\"וַעֲבָדוּ הֵיכְדֵין אִסְטַגְנִינַיָא חַרְשְׁיוּתָא בְּלַחֲשֵׁהוֹן לְאַנְפָּקָא יַת קַלְמִין וְלָא יָכִילוּ וַהֲוַת מְחַת קַלְמֵי שַׁלְטָא בְּאֵינָשָׁא וּבִבְעִירָא\",0,0],[4,143,8,15,\"וַאֲמָרוּ אִיסְטַגְנִינֵי פַּרְעה לָא מִן כּחַ גְבוּרַת משֶׁה וְאַהֲרן הִיא אֱלָהֵן מְחָא מִשְׁתַּלְחָא מִן קֳדָם יְיָ הִיא וְאִתְקַף יִצְרָא דְלִבָּא דְפַרְעה וְלָא קַבֵּיל מִנְהוֹן הֵיכְמָא דְמַלֵיל יְיָ\",0,0],[4,143,8,16,\"וַאֲמַר יְיָ לְמשֶׁה אַקְדֵם בְּצַפְרָא וְתִתְעַתַּד קֳדָם פַּרְעה הָא נָפִיק לְמִנְטַר קוּסְמִין עִילוֹי מַיָא הֵי כְּאַמְגוּשָׁא וְתֵימַר לֵיהּ כִּדְנָא אָמַר יְיָ פְּטוֹר יַת עַמִי וְיִפְלְחוּן קֳדָמַי\",0,0],[4,143,8,17,\"אֲרוּם אִין לֵיתָךְ מִפְטַר יַת עַמִי הָאֲנָא מְגָרֵי בָךְ וּבְעַבְדָךְ וּבְעַמָךְ וּבְבֵיתָךְ יַת עִירְבּוּב חֵיוַת בָּרָא וְיִתְמְלוּן בָּתֵּי מִצְרָאֵי עִירְבּוּב חֵיוַת בָּרָא וְאוּף יַת אַרְעָא דְהִינוּן עֲלָהּ\",0,0],[4,143,8,18,\"וְאֶעֱבֵיד פִּלְאִין בְּיוֹמָא הַהוּא עִם אַרְעָא דְגשֶׁן דְעַמִי שְׁרֵי עֲלָהּ בְּדִיל דְלָא לְמֶהֱוֵי תַמָן עִירְבּוּב חֵיוַת בָּרָא מִן בִּגְלַל דְתִנְדַע אַרוּם אֲנָא יְיָ שַׁלִיט בְּגוֹ אַרְעָא\",0,0],[4,143,8,19,\"וַאֲשַׁוֵי פּוּרְקַן לְעַמִי וְעַל עַמָךְ אַיְיתֵי מָחָא לְעִידַן מָחָר יְהֵי אָתָא הָדֵין\",0,0],[4,143,8,20,\"וְעָבַד יְיָ כֵּן וְאַיְיתֵי עִירְבּוּב חֵיוַת בָּרָא תַקִיף לְבֵית פַּרְעה וּלְבֵית עַבְדוֹי וּבְכָל אַרְעָא דְמִצְרַיִם אִיתְחַבִּילוּ יַתְבֵי אַרְעָא מִן קֳדָם עִירְבּוּב חֵיוַת בָּרָא\",0,0],[4,143,8,21,\"וּקְרָא פַרְעה לְמשֶׁה וּלְאַהֲרן וַאֲמַר אִיזִילוּ פְּלָחוּ נִכְסַת חַגָא קֳדָם יְיָ אֱלָהָכוֹן בְּאַרְעָא הָדָא\",0,0],[4,143,8,22,\"וַאֲמַר משֶׁה לָא תַקִין לְמֶעֱבַד כֵּן אֲרוּם אִמְרַיָא דְהִינוּן טַעֲוַותְהוֹן דְמִצְרָאֵי מִנְהוֹן נִיסַב וְנִקְרְבָא קֳדָם יְיָ אֱלָהֵן הָא אִין מְקַרְבִין אֲנָן יַת טַעֲוַותְהוֹן דְמִצְרָאֵי קֳדָמֵיהוֹן הוּא מִן דִינָא הוּא לְאַטָלָא יָתָן בְּאַבְנִין\",0,0],[4,143,8,23,\"מַהֲלַךְ תְּלָתָא יוֹמִין נְטַיֵיל בְּמַדְבְּרָא וּנְדַבַּח נִיכְסַת חַגָא קֳדָם אֱלָהָנָא הֵיכְמָא דְיֵימַר לָנָא\",0,0],[4,143,8,24,\"וַאֲמַר פַּרְעה אֲנָא אֶפְטוֹר יַתְכוֹן וְתִדְבְּחוּן קֳדָם יְיָ אֱלָהָכוֹן בְּמַדְבְּרָא לְחוֹד אַרְחָקָא לָא תַרְחִיקוּן לְטַיְילָא צְלוֹ עָלָי\",0,0],[4,143,8,25,\"וַאֲמַר משֶׁה הָא אֲנָא נָפִיק מִלְוָתָךְ וְאֵיצַלֵי קֳדָם יְיָ וְיַעְדֵי עִרְבּוּב חֵיוַת בָּרָא מִן פַּרְעה וּמִן עַמֵיהּ לִמְחַר לְחוֹד לָא יוֹסֵף פַּרְעה לִמְשַׁקְרָא בְּדִיל דְלָא לְמִפְטוֹר יַת עַמָא לִמְדַבְּחָא נִכְסַת חַגָא קֳדָם יְיָ\",0,0],[4,143,8,26,\"וּנְפַק משֶׁה מִלְוַת פַּרְעה וְצַלִי קֳדָם יְיָ\",0,0],[4,143,8,27,\"וַעֲבַד יְיָ כְּפִתְגַם בְּעוּתָא דְמשֶׁה וְאַעֲדֵי עִירְבּוּב חֵיוַת בָּרָא מִפַּרְעה וּמֵעַבְדוֹי וּמֵעַמֵיהּ לָא אִשְׁתְּאַר חָד\",0,0],[4,143,8,28,\"וִיקַר פַּרְעה יַת יִצְרָא דְלִבֵּיהּ אוּף בְּזִמְנָא הָדָא וְלָא פְּטַר יַת עַמָא\",0,0],[4,143,9,1,\"וַאֲמַר יְיָ לְמשֶׁה עוּל לְוַת פַּרְעה וּתְמַלֵיל עִמֵיהּ כִּדְנַן אָמַר יְיָ אֱלָהָא דִיהוּדָאֵי פְּטוֹר יַת עַמִי וְיִפְלְחוּן קֳדָמַי\",0,0],[4,143,9,2,\"אֲרוּם אִין מְסָרֵב אַנְתְּ לְמִפְטוֹר וְעַד כְּדוֹן אַנְתְּ מַתְקִיף בְּהוֹן\",0,0],[4,143,9,3,\"הָא מְחַת יְדָא דַיְיָ הַוְיָא כְּעַן כַּד לָא הֲוַת לְמֶהֱוֵי בִּבְעִירָךְ דִבְחַקְלָא בְּסוּסְוָותָא בְּחַמְרֵי בִּגְמַלֵי בְּתוֹרֵי וּבְעָנָא מוֹתָא תַקִיף לַחֲדָא\",0,0],[4,143,9,4,\"וְיַעֲבֵד יְיָ פִּלְאִין בֵּין גֵיתֵי דְיִשְרָאֵל וּבֵין גֵיתֵי דְמִצְרָאֵי וְלָא יְמוּת מִכָּל לִבְנֵי יִשְרָאֵל מִדָעַם\",0,0],[4,143,9,5,\"וּקְבַע יְיָ זִמְנָא לְמֵימָר מְחָר יַעֲבֵיד יְיָ יַת פִּתְגָמָא הָדֵין בְּאַרְעָא\",0,0],[4,143,9,6,\"וַעֲבַד יְיָ יַת פִּתְגָמָא הָדֵין לְיוֹם חֲרָן וּמִית כָּל בְּעִירָא דְמִצְרָאֵי וּמִבְּעִירָא דִבְנֵי יִשְרָאֵל לָא מִית חָד\",0,0],[4,143,9,7,\"וְשָׁדַר פַּרְעה פּוּלִין לְמֶחֱמֵי וְהָא לָא מִית מִבְּעִירָא דִבְנֵי יִשְרָאֵל עַד חָד וְאִתְיַיקַר יִצְרָא דְלִבָּא דְפַרְעה וְלָא פְטַר יַת עַמָא\",0,0],[4,143,9,8,\"וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרן סִיבוּ לְכוֹן מָלֵי חוּפְנֵיכוֹן קְטַם דְקִיק מִן אַתּוּנָא וְיִדְרְקִינֵיהּ משֶׁה לְצֵית שְׁמַיָא לְמֶיחֱמֵי פַרְעה\",0,0],[4,143,9,9,\"וִיהֵי לְאַבְקָא עַל כָּל אַרְעָא דְמִצְרָיִם וִיהֵי עַל אֱנָשָׁא וְעַל בְּעִירָא לִשְׁחִין סַגִי שַׁלְפוּקִין בְּכָל אַרְעָא דְמִצְרָיִם\",0,0],[4,143,9,10,\"וּנְסִיבוּ יַת קִיטְמָא דְאַתּוּנָא וְקָמוּ לִקְדָם פַּרְעה וּדְרַק יָתֵיהּ משֶׁה לְצֵית שְׁמַיָא וַהֲוָה שְׁחִין שַׁלְפוּקִין סַגִי בְּאֵינָשָׁא וּבִבְעִירָא\",0,0],[4,143,9,11,\"וְלָא יָכִילוּ אִיסְטַגְנִינַיָא לְמֵיקַם קֳדָם משֶׁה מִן קֳדָם שִׁיחְנָא אֲרוּם הֲוָה מְחַת שִׁיחְנָא בְּאִיסְטַגְנִינַיָא וּבְכָל מִצְרָאֵי\",0,0],[4,143,9,12,\"וּתְקֵיף יְיָ יַת יִצְרָא דְלִבָּא דְפַרְעה וְלָא קַבֵּיל מִנְהוֹן הֵיכְמָא דְמַלֵיל יְיָ עִם משֶׁה\",0,0],[4,143,9,13,\"וַאֲמַר יְיָ לְמשֶׁה אַקְדֵים בְּצַפְרָא וְתִתְעַתַּד קֳדָם פַּרְעה וְתֵימַר לֵיהּ כִּדְנָא אָמַר יְיָ אֱלָהָא דִיהוּדָאֵי פְּטוֹר יַת עַמִי וְיִפְלְחוּן קֳדָמַי\",0,0],[4,143,9,14,\"אַרוּם בְּזִימְנָא הָדָא אֲנָא שַׁלַח מַחְתָּא לָךְ מִן שְׁמַיָא וְתָתֵיב יַת כָּל מַחֲתַי דִמְחִיתָךְ לְלִבָּךְ וּבְעַבְדָךְ וּבְעַמָךְ דְמִן קֳדָמַי הַוָון מִשְׁתַּלְחוּן וְלָא מִן חַרְשְׁיוּתָא דִבְנֵי נְשָׁא בְּגִין דְתִנְדַע אֲרוּם לֵית דְדָמַי לִי בְכָל אַרְעָא\",0,0],[4,143,9,15,\"אֲרוּם כְּדוֹן שַׁדָרִית יַת מְחַת גְבוּרְתִּי מִן דִינָא הוּא דְמָחִיתִי יָתָךְ וְיַת עַמָךְ בְּמוֹתָא וְאִישְׁתֵּצִית מִן אַרְעָא\",0,0],[4,143,9,16,\"וּבְרַם בְּקוּשְׁטָא לָא מִן בִּגְלַל דִי נְטַיְיבָא לָךְ קְיַימְתִּיךְ אֶלָא מִן בִּגְלַל לִמְחַזְיָךְ יַת חֵילִי וּמִן בִּגְלַל דְתִתְגֵי שְׁמִי קַדִישָׁא בְּכָל אַרְעָא\",0,0],[4,143,9,17,\"עַד כְּדוֹן אַנְתְּ מִתְרַבְרַב בְּעַמִי בְּדִיל דְלָא לְמִפְטְרִינוּן\",0,0],[4,143,9,18,\"הָאֲנָא מָחִית בְּעִידַן הָדֵין לְמָחָר מִן אוֹצְרֵי שְׁמַיָא בַּרְדָא תַּקִיף לַחֲדָא דְלָא הֲוֵי דִכְוָותָא בְּמִצְרַיִם מִן יוֹמָא דְאִשְתַּכְלָלוּ אַנְשָׁהָא וְעַד כְּדוֹן\",0,0],[4,143,9,19,\"וּכְדוּן שְׁדַר כְּנוֹשׁ יַת גֵיתָךְ וְיַת כָּל דִילָךְ בְּחַקְלָא כָּל אֵינָשָׁא וּבְעִירָא דְאִשְׁתַּכַּח בְּחַקְלָא וְלָא יִתְכְּנוֹשׁ לְבֵיתָא וְיֵיחוֹת עִילַוֵהוֹן בַּרְדָא וִימוּתוּן\",0,0],[4,143,9,20,\"אִיוֹב דַהֲוָה דָחִיל מִפִּתְגָמָא דַיְיָ מֵעַבְדוֹי דְפַרְעה כְּנַש יַת עַבְדוֹי וְיַת גֵיתוֹי לְגוֹ בֵיתָא\",0,0],[4,143,9,21,\"וּבִלְעָם דְלָא שַׁוֵיהּ לִבֵּיהּ לְפִתְגָמָא דַיְיָ וּשְׁבַק יַת עַבְדוֹי וְיַת גֵיתוֹי בְּחַקְלָא\",0,0],[4,143,9,22,\"וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יַת יְדָךְ עַל צֵית שְׁמַיָא וִיהִי בַרְדָא בְּכָל אַרְעָא דְמִצְרָיִם עַל אֱנָשָׁא וְעַל בְּעִירָא וְעַל כָּל עִיסְבָּא דְחַקְלָא בְּאַרְעָא דְמִצְרָיִם\",0,0],[4,143,9,23,\"וַאֲרֵים משֶׁה יַת חוּטְרֵיהּ עַל צֵית שְׁמַיָא וַיְיָ יְהַב קָלִין וּבַרְדִין וּמְצַלְהֲבָא אֵישָׁתָא עַל אַרְעָא וְאָחִית יְיָ בַּרְדָא עַל אַרְעָא דְמִצְרָיִם\",0,0],[4,143,9,24,\"וַהֲוָה בַרְדָא וְאֵישָׁתָא מִתְקַפְּצָא בְּגוֹ בַרְדָא תַּקִיף לַחֲדָא דְלָא הֲוָה דִכְוָותֵיהּ בְּכָל אַרְעָא דְמִצְרַיִם מִן עִידָן דְהֲוַת לְאוּמָא וּמַלְכוּ\",0,0],[4,143,9,25,\"וּמְחָא בַרְדָא בְּכָל אַרְעָא דְמִצְרַיִם יַת כָּל דִבְחַקְלָא מֵאֵינָשָׁא וְעַד בְּעִירָא וְיַת כָּל עִסְבָּא דְחַקְלָא מְחָא בַרְדָא וְיַת כָּל אִילָנָא דְחַקְלָא תְּבִיר וְשַׁרִישׁ\",0,0],[4,143,9,26,\"לְחוֹד בְּאַרְעָא דְגשֶׁן דְתַמָן בְּנֵי יִשְרָאֵל לָא הֲוָה בַרְדָא\",0,0],[4,143,9,27,\"וְשַׁדַר פַּרְעה פּוּלִין לְמִקְרֵי לְמשֶׁה וּלְאַהֲרן וַאֲמַר לְהוֹן חָבִית בְּזִמְנָא הָדָא יְדָעִית דַיְיָ הוּא אֱלָהָא זַכָּאָה וּבְרַם אֲנָא וְעַמִי חַיָיבִין בְּכָל מַחְתָא וּמַחְתָא\",0,0],[4,143,9,28,\"צְלוֹי קֳדָם יְיָ וִיהִי סַגִי קָדָמוֹי מִלְמֶהֱוֵי קָלִין דִלְוָוט מִן קֳדָם יְיָ וּבַרְדָן וְאֶפְטוֹר יַתְכוֹן וְלָא תוֹסְפוּן לְאִתְעַכָּבָא\",0,0],[4,143,9,29,\"וַאֲמַר לֵיהּ משֶׁה כְּמִפְקִי סְמִיךְ לְקַרְתָּא אֶפְרוֹשׁ יַת יְדַי בִּצְלוֹי קֳדָם יְיָ קָלַיָיא יִתְמַנְעוּן וּבַרְדָא לָא יְהִי תוּב מִן בִּגְלַל דְתִנְדַע אֲרוּם דַיְיָ הִיא אַרְעָא\",0,0],[4,143,9,30,\"וְאַנְתְּ וְעַבְדָךְ חַכִּימִית אֲרוּם עַד לָא תִפְטְרוּן עַמָא תְּהוֹן דַחֲלִין מִן קֳדָם יְיָ אֱלהִים\",0,0],[4,143,9,31,\"וְכִתְּנָא וְסַרְתָּא לָקוּן אֲרוּם סַרְתָּא הֲוָות כְּסִירָא וְכִיתְנָא עָבַד פּוּקְלִין\",0,0],[4,143,9,32,\"וְחִיטַיָא וְכוּנְתַּיָא לָא לָקוּן אֲרוּם לְקִישָׁן הִינוּן\",0,0],[4,143,9,33,\"וּנְפַק משֶׁה וְאַהֲרן מִלְוַת פַּרְעה סְמִיךְ לְקַרְתָּא וּפְרַס יְדוֹי בִּצְלוֹי קֳדָם יְיָ וְאִתְמְנָעוּ קָלִין דִלְוָוט וּבַרְדָא וּמִטְרָא דַהֲוָה נָחִית לָא מָטָא עַל אַרְעָא\",0,0],[4,143,9,34,\"וַחֲמָא פַּרְעה אֲרוּם אִתְמְנַע מִטְרָא וּבַרְדָא וְקָלַיָיא דִלְוָוט פָּסְקוּ וְאוֹסִיף לְמֶחֱטֵי וִיקָרֵיהּ לְיִצְרָא דְלִבֵּיהּ הוּא וְעַבְדוֹי\",0,0],[4,143,9,35,\"וְאִיתְקַף יִצְרָא דְלִבָּא דְפַרְעה וְלָא פְטַר יַת בְּנֵי יִשְׁרָאֵל הֵיכְמָא דְמַלֵיל יְיָ בִּידָא דְמשֶׁה\",0,0],[4,143,10,1,\"ויאמר וַאֲמַר יְיָ לְמשֶׁה עוּל לְוַת פַּרְעה אֲרוּם אֲנָא יַקִּירִית יִצְרָא דְלִבֵּיהּ וְיִצְרָא דְלִבְּהוֹן דְעַבְדוֹי מִן בִּגְלַל לְשַׁוָואָה אַתְוָותַי אִלֵין בֵּינֵיהוֹן\",0,0],[4,143,10,2,\"וּמִן בִּגְלַל דְתַתְנֵי בְּמִשְׁמְעֵי בְּרָךְ וּבַר בְּרָךְ יַת נִיסִין דַעֲבָדִית בְּמִצְרַיִם וְיַת אַתְוָותַי דְשַׁוֵּיתִי בְּהוֹן וְתִנְדְּעוּן אֲרוּם אֲנָא הוּא יְיָ\",0,0],[4,143,10,3,\"וְאָעַל משֶׁה וְאַהֲרן לְוַת פַּרְעה וַאֲמָרוּ לֵיהּ כִּדְנָא אָמַר יְיָ אֱלָהָא דְיִשְרָאֵל עַד אֵימַת מְסָרֵב אַנְתְּ (מִן) לְמִתְכְּנָעָא מִן קֳדָמַי פְּטוֹר יַת עַמִּי וְיִפְלְחוּן קֳדָמַי\",0,0],[4,143,10,4,\"אֲרוּם אִין יֵשׁ מְסָרֵב אַנְתְּ לְמִפְטוֹר יַת עַמִּי הָא אֲנָא מַיְיתֵי מְחַר גּוֹבָא בִּתְחוּמָךְ\",0,0],[4,143,10,5,\"וְיַחֲפֵי יַת חֶזְוָונָא דְאַרְעָא וְלָא יֶהֱוֵי יָכִיל לְמֶחֲמֵי יַת אַרְעָא וִישֵׁיצֵי יַת שְׁאָר שֵׁיזְבוּתָא דְּאִישְׁתָּאֲרַת לְכוֹן מִן בַּרְדָא וִישֵׁיצֵי יַת כָּל אִילָנָא דְיִצְמַח לְכוֹן מִן חַקְלָא\",0,0],[4,143,10,6,\"וְיִתְמְלוּן בָּתָּךְ וּבָתֵּי כָּל עַבְדָךְ וּבָתֵּי כָל מִצְרָאֵי דְלָא חָמוּן אַבְהָתָךְ וְאַבְהַת אַבְהָתָךְ מִן יוֹם מֶהֱוֵיהוֹן עַל אַרְעָא עַד יוֹמָא הָדֵין וְאִתְפְּנֵי וּנְפַק מִלְוַת פַּרְעה\",0,0],[4,143,10,7,\"וְאָמָרוּ עַבְדֵי פַּרְעה עַד אֵימַת יְהֵי דֵין גַּבְרָא לָנָא לְתַקְלָא פְּטוֹר יַת גַּבְרַיָא וְיִפְלְחוּן קֳדָם יְיָ אֱלָהָהוֹן הַעַד כְּדוֹן לָא חַכִּימְתָּ אֲרוּם עַל יְדוֹי עֲתִידָא לְמוֹבְדָא אַרְעָא דְמִצְרָיִם\",0,0],[4,143,10,8,\"וּפַקֵּיד לְאִיתּוֹתָבָא יַת משֶׁה וְיַת אַהֲרן לְוַת פַּרְעה וַאֲמַר לְהוֹם אִיזִילוּ פְּלָחוּ קֳדָם יְיָ אֱלָהָכוֹן מָן וּמָן הִינוּן דְּאָזְלִין\",0,0],[4,143,10,9,\"וַאֲמַר משֶׁה בְּטַלְיָינָא וּבְסָבָנָא נֵיזִיל בִּבְנָנָא וּבִבְרַתָּנָא בְּעַנָנָא וּבְתוֹרָנָא נֵיזִיל אֲרוּם חַגָא קֳדָם יְיָ לָנָא\",0,0],[4,143,10,10,\"וַאֲמַר לְהוֹן יְהִי כְדֵין מֵימְרָא דַיְיָ בְּסַעַדְכוֹן כְּמָא דְאֶפְטוֹר יַתְכוֹן וְיַת טַפְלְכוֹן חָמוּן אֲרוּם לְתַקָּלָא בִּישָׁא הִיא לְכוֹן לִקְבֵיל אַפֵּיכוֹן בְּאוֹרְחֲכוֹן דִּתְהַלְכוֹן עַד זְמַן דִּי תִמְטוּן לְבֵית אֲתַר מַשְׁרוּיֵיכוֹן\",0,0],[4,143,10,11,\"לָא כְמָא דְאַתּוּן סַבְרִין אֱלָהֵן אִיזִילוּ כְּדוֹן גּוּבְרַיָא וּפָלְחוּ קֳדָם יְיָ אֲרוּם יָתֵיהּ אַתּוּן בָּעָן וְתָרִיךְ יַתְהוֹן מִלְוַת אַפֵּי פַּרְעה\",0,0],[4,143,10,12,\"וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יַת יְדָךְ עַל אַרְעָא דְמִצְרָיִם בְּדִיל גּוֹבָא וְיַיסֵק עַל אַרְעָא דְמִצְרָיִם וִישֵׁיצֵי יַת כָּל עִיסְבָּא דְאַרְעָא יַת כָּל מַה דִּי שַׁיֵּיר בַּרְדָא\",0,0],[4,143,10,13,\"וַאֲרֵים משֶׁה יַת חוּטְרֵיהּ עַל אַרְעָא דְמִצְרָיִם וַיְיָ דְבַר רוּחַ קִידוּמָא בְּאַרְעָא כָּל יוֹמָא הַהוּא וְכָל לֵילְיָא צַפְרָא הֲוָה וְרוּחַ קִידוּמָא נָטַל יַת גּוֹבָא\",0,0],[4,143,10,14,\"וּסְלֵיק גּוֹבָא עַל כָּל אַרְעָא דְּמִצְרָיִם וּשְׁרָא בְּכָל תְּחוּם מִצְרָיִם תַּקִּיף לַחֲדָא קֳדָמוֹי לָא הֲוָה כְדֵין קַשְׁיָין גּוֹבָא דִכְוָותֵיהּ וּבַתְרוֹי לָא עָתִיד דִּיהִי כֵן\",0,0],[4,143,10,15,\"וַחֲפָא יַת חֶזְוָונָא דְכָל אַרְעָא עַד דִּי חֲשׁוֹכַת אַרְעָא וִישֵׁיצֵי יַת כָּל עִיסְבָּא דְאַרְעָא וְיַת כָּל פֵּירֵי אִילָנָא דִי שַׁיֵּיר בַּרְדָא וְלָא אִשְׁתַּיֵּיר כָּל יְרוֹק בְּאִילָנָא וּבְעִיסְבָּא דְחַקְלָא בְּכָל אַרְעָא דְמִצְרָיִם\",0,0],[4,143,10,16,\"וְאוֹחֵי פַּרְעה וּשְׁדַר פּוּלִין לְמִקְרֵי לְמשֶׁה וּלְאַהֲרן וַאֲמַר חָבִית קֳדָם יְיָ אֱלָהָכוֹן וּלְכוֹן\",0,0],[4,143,10,17,\"וּכְדוּן שְׁבוֹק כְּדוּן חוֹבִי לְחוֹד זִמְנָא הָדָא וּצְלוּ קֳדָם יְיָ וְיַעֲדֵי מִינִי לְחוֹד יַת מוֹתָא הָדֵין\",0,0],[4,143,10,18,\"וּנְפַק מִלְוַת פַּרְעה וְצַלִּי קֳדָם יְיָ\",0,0],[4,143,10,19,\"וַהֲפַךְ יְיָ יַת רוּחָא מִמְעַרְבָא תַּקִּיף לַחֲדָא וּנְטַל יַת גּוֹבָא וְטַלְקֵיהּ לְיַמָּא דְסוּף לָא אִשְׁתְּיַיר גּוֹבָא חָד בְּכָל תְּחוּם מִצְרַיִם וַאֲפִילּוּ מַה דְּמַלְחוּן בְּמָנַיָיא לִצְרוֹךְ מֵיכַלְהוֹן נָשָא הִינוּן רוּחַ מַעֲרְבָא וַאֲזָלוּ\",0,0],[4,143,10,20,\"וּתְקֵיף יְיָ יַת יִצְרָא דְלִיבָּא דְפַרְעה וְלָא פְּטַר יַת בְּנֵי יִשְרָאֵל\",0,0],[4,143,10,21,\"וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יַת יְדָךְ עַל צֵית שְׁמַיָא וִיהִי חֲשׁוֹכָא עַל אַרְעָא דְמִצְרַיִם בִּקְרִיצְתָּא וְיַעֲדֵי בְּקַדְמֵתָא חֲשׁוֹךְ לֵילְיָא\",0,0],[4,143,10,22,\"וַאֲרֵים משֶׁה יַת יְדֵיהּ עַל צֵית שְׁמַיָא וַהֲוָה חֲשׁוֹךְ דִּקְבֵיל בְּכָל אַרְעָא דְמִצְרַיִם תְּלָתָא יוֹמִין\",0,0],[4,143,10,23,\"לָא חָמוּן גְּבַר יַת אָחוֹי וְלָא קָמוּן אֱנַשׁ מֵאַתְרֵיהּ תְּלָתָא יוֹמִין וּלְכָל בְּנֵי יִשְרָאֵל הֲוָה נְהוֹרָא לְמִקְבּוֹר רַשִׁיעַיָא דִי בֵינֵיהוֹן דְּמִיתַן וְזַכָּאַיָא לְמֶעֱסוֹק בְּמִצְוָתָא בְּמוֹתְבָנֵיהוֹן\",0,0],[4,143,10,24,\"וּבְסוֹף תְּלָתָא יוֹמִין קָרָא פַּרְעה לְמשֶׁה וַאֲמַר זִילוּ פְלָחוּ קֳדָם יְיָ לְחוֹד עַנְכוֹן וְתוֹרֵיכוֹן יְקוּם גַּבִּי אוּף טַפְלְכוֹן יֵזִיל עִמְכוֹן\",0,0],[4,143,10,25,\"וַאֲמַר משֶׁה אוּף אַנְתְּ תִּתֵּן בִּידָנָא נִכְסַת קוּדְשִׁין וְעַלְוָון וְנַעֲבֵיד קֳדָם יְיָ אֱלָהָנָא\",0,0],[4,143,10,26,\"וְאוּף גֵּיתָנָא יֵזִיל עִמָּנָא לָא תִשְׁתַּיֵּיר מִנְהוֹן פַּרְסָתָא חָדָא אֲרוּם מִנְהוֹן נִסַּב לְמִפְלַח קֳדָם יְיָ אֱלָהָן וַאֲנַחְנָא אִין נַשְׁבִּיקִינוּן לֵית אֲנַן יַדְעִין מִמָא נִפְלַח קֳדָם יְיָ עַד מֵיתָנָא לְתַמָּן\",0,0],[4,143,10,27,\"וּתְקֵיף יְיָ יַת יִצְרָא דְלִבָּא דְפַרְעה וְלָא צְבָא לְמִפְטְרִינוּן\",0,0],[4,143,10,28,\"וַאֲמַר לֵיהּ פַּרְעה אִיזֵל מֵעִילַוָוי אִיזְדַהַר לָךְ לָא תוֹסִיף לְמֶחֱמֵי סְבַר אַפַּי לְמַלָלָא קֳדָמַי חֲדָא מִן מִלַיָא קַשְׁיָיתָא כְּאִלֵּין אֲרוּם בְּיוֹמָא דְאַתְּ חָמֵי סְבַר אַפַּי יִתְקוֹף רוּגְזִי בָךְ וְאֶמְסוֹר יָתָךְ בְּיַד בְּנֵי נְשָׁא אִילֵין דַּהֲווֹ תַּבְעִין נַפְשָׁךְ לְמִיסַב יָתָהּ\",0,0],[4,143,10,29,\"וַאֲמַר משֶׁה יָאוּת מַלֵּילְתָּא אֲנָא עַד דַּהֲוֵינָא יָתִיב בְּמִדְיָן אִיתְאֲמַר לִי בְּמֵימַר מִן קֳדָם יְיָ דְגוּבְרַיָא דְבָעוּ לְמִקְטְלִי נַחֲתוּ מִנִּכְסֵיהוֹן וְהִינוּן חֲשִׁיבִין כְּמִיתַיָא וְלָא מִן סוּף דַּהֲוָה עֲלָךְ רַחֲמִין הֲוֵינָא מְצַלֵּי וּמַחְתָא הֲוָה מִתְכַּלְיָא מִינָךְ וּכְדוֹן לָא אוֹסִיף תּוּב לְמֶחֱמֵי סְבַר אַפָּךְ\",0,0],[4,143,11,1,\"וַאֲמַר יְיָ לְמשֶׁה תּוּב מַכְתַּשׁ חַד אֲנָא מַיְיתִי עֲלוֹי פַּרְעה וְעִילוֹי מִצְרָאֵי דְקָשֵׁי עֲלֵיהוֹן מִכֻּלְהוֹן וּמִבָּתַר כְּדֵין יִפְטוֹר יַתְכוֹן מִכָּא בְּמִפְטְרֵיהּ גְּמִירָא יְהֵי לֵיהּ מַטְרֵד יִטְרוֹד יַתְכוֹן מִכָּא\",0,0],[4,143,11,2,\"מַלֵּיל כְּדוֹן בְּמִשְׁמָעֵיהוֹן דְּעַמָּא וִישַׁיְילוּן גְּבַר מִן רַחֲמֵיהּ מִצְרָאֵי וְאִתְּתָא מִן רְחִימָא מִצְרֵיתָא מָאנִין דִּכְסַף וּמָאנִין דִּדְהַב\",0,0],[4,143,11,3,\"וִיהַב יְיָ יַת עַמָּא לְרַחֲמִין קֳדָם מִצְרָאֵי אוּף גַּבְרָא משֶׁה רַב לַחֲדָא בְּאַרְעָא דְמִצְרַיִם קֳדָם עַבְדֵי פַרְעה וּקְדָם עַמָּא\",0,0],[4,143,11,4,\"וַאֲמַר משֶׁה לְפַרְעה כִּדְנָא אָמַר יְיָ לֵילְיָא חוֹרַן בְּשַׁעְתָּא דָא אֲנָא מִתְגְּלֵי בְּגוֹ מִצְרָאֵי\",0,0],[4,143,11,5,\"וִימוּת כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מִבִּיר בּוּכְרָא דְפַרְעה דְּעָתִיד דְּיֵיתִיב עַל כּוּרְסַיָא מַלְכוּתֵיהּ עַד בּוּכְרָא דְאַמְתָא בִּיצִירְתָּא דִבְמִצְרַיִם דְּמִתְיְלִיד לָהּ כַּד הִיא טַחְנָא אֲחוֹרֵי רֵיחַיָא וְכָל בּוּכְרָא דִבְעִירָא\",0,0],[4,143,11,6,\"וּתְהֵי צְוַוחְתָּא רַבְּתָא בְּכָל אַרְעָא דְמִצְרַיִם דְּדִכְוָותֵיהּ לֵילְיָא לָא הֲוָת בֵּיהּ מַחְתָּא כְּדָא וְדִכְוָותֵיהּ לֵילְיָא לָא תוֹסֵיף לְמֶהֱוֵי מַחְתָּא כְּדָא\",0,0],[4,143,11,7,\"וּלְכָל בְּנֵי יִשְרָאֵל לָא יְהַנְזַק כַּלְבָּא בְּלִשְׁנֵיהּ לְמִנְבַּח לְמֵאֱנָשָׁא וְעַד בְּעִירָא מִן בִּגְלַל דְּתִנְדְּעוּן דְּיַפְרֵישׁ יְיָ בֵּין מִצְרָאֵי וּבֵינֵי יִשְרָאֵל\",0,0],[4,143,11,8,\"וְיַחְתוּן כָּל עַבְדָּךְ אִלֵּין לְוָותִי וְיִבְעוּן מָטוּ מִינִי לְמֵימַר פּוּק אַנְתְּ וְכָל עַמָּא דְּעִמָּךְ וּמִבָּתַר כְּדֵין אֶפּוֹק וּנְפַק מִלְוַת פַּרְעה בִּתְקוֹף רְגַז\",0,0],[4,143,11,9,\"וַאֲמַר יְיָ לְמשֶׁה לָא יְקַבֵּיל מִנְכוֹן פַּרְעה מִן בִּגְלַל לְאַסְגָאָה תִּמְהַיַי בְּאַרְעָא דְמִצְרָיִם\",0,0],[4,143,11,10,\"וּמשֶׁה וְאַהֲרן עֲבָדוּ יַת כָּל תִּמְהַיָא הָאִילֵין קֳדָם פַּרְעה וּתְקֵיף יְיָ יַת יִצְרָא דְלִבָּא דְפַרְעה וְלָא פְטַר יַת בְּנֵי יִשְרָאֵל מֵאַרְעֵיהּ\",0,0],[4,143,12,1,\"וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרן בְּאַרְעָא דְמִצְרַיִם לְמֵימָר\",0,0],[4,143,12,2,\"יַרְחָא הָדֵין לְכוֹן לְמִקְבְּעֵיהּ רֵישׁ יַרְחַיָּיא וּמִנֵּיהּ תֵּשְׁרוּן לְמִמְנֵי חַגַיָא וְזִמְנַיָא וּתְקוּפְתָּא קַדְמָאֵי הוּא לְכוֹן לְמִנְיַן יַרְחֵי שַׁתָּא\",0,0],[4,143,12,3,\"מַלִילוּ עִם כָּל כְּנִשְׁתָּא דִבְנֵי יִשְרָאֵל לְמֵימַר בְּעַשְרָא לְיַרְחָא הָדֵין זִמְנֵיהּ קָבִיעַ בַּהֲדָא זִימְנָא וְלָא לְדָרַיָא וְיִסְבוּן לְהוֹן אִימַר לְבֵית גְּנִיסְתָּא וְאִין סַגִּיאִין מִמִּנְיָנָא יִסְבוּן אִימְרָא לְבֵיתָא\",0,0],[4,143,12,4,\"וְאִין זְעִירִין אִינְשֵׁי בֵיתָא מִמִּנְיַן עַשְרָא כְּמִיסַת לְמֵיכוּל אִימְרָא וְיִסַב הוּא וְשִׁיבְבֵיהּ דִּקָרֵיב לְבֵיתֵיהּ בִּסְכוּם נַפְשָׁתָא גְּבַר לְפוּם מֵיסַב מֵיכְלֵיהּ תִּיכְסוּן יַת אִימְרָא\",0,0],[4,143,12,5,\"אִימַר שְׁלִים דְּכַר בַּר שַׁתָּא יְהֵי לְכוֹן מִן אִימְרַיָא וּמִן בְּנֵי עִזַּיָא תִּסְבוּן\",0,0],[4,143,12,6,\"וִיהֵי לְכוֹן קָטִיר וְנָטִיר עַד אַרְבֵּיסַר יוֹמָא לְיַרְחָא הָדֵין דְּתִנְדְּעוּן דְּלֵיתֵיכוֹן מִסְתַּפְיַן מִמִּצְרָאֵי דְחַמְיָין יָתֵיהּ וְיִכְסוֹן יָתֵיהּ כְּהִילְכָתָא כָּל קְהַל כְּנִישְׁתָּא דְיִשְרָאֵל בֵּינֵי שִׁמְשָׁתָא\",0,0],[4,143,12,7,\"וְיִסְבוּן מִן דְּמָא וְיִתְּנוּן עַל תְּרֵין סִיפַיָּיא וְעִילוֹי מִסְקוּפָא עִלָּאָה מִלְּבַּר עַל בָּתַּיָא דְיֵיכְלוּן יָתֵיהּ וּדְדַמְכוּן בְּהוֹן\",0,0],[4,143,12,8,\"וְיֵיכְלוּן יַת בִּישְרָא בְּלֵילְיָא הָדֵין דַּחֲמֵיסַר בְּנִיסַן עַד פַּלְגוּתֵיהּ דְּלֵילְיָא טְוֵי נוּר וּפַטִּיר עַל תַּמְכָא וְעוּלְשִׁין יֵיכְלוּנֵיהּ\",0,0],[4,143,12,9,\"לָא תֵיכְלוּן מִנֵיהּ כַּד חַי וְלָא כַּד בַּשְׁלָא בְּחַמְרָא וּמִשְׁחָא וְשַׁקְיָינֵי וְלָא מְבֻשָּׁל בְּמַיָא אֱלָהֵן טְוֵי נוּר עִם רֵישֵׁיהּ עִם רַגְלוֹי וְעִם גַּוֵּיהּ\",0,0],[4,143,12,10,\"וְלָא תְשַׁיְירוּן מִנֵּיהּ עַד צַפְרָא וּדְאִשְׁתַּיֵּיר מִנֵּיהּ עַד צַפְרָא תַּצְנְעִנֵּיהּ וּבְאוֹרְתָּא דְּשִׁתְּסַר בְּנוּרָא תוֹקְדוּן דְּלֵית אֶפְשַׁר לְמִיתוֹקְדָא מוֹתַר נִיכְסַת קוּדְשַׁיָא בְּיוֹמָא טָבָא\",0,0],[4,143,12,11,\"וּכְדָא הִילְכָתָא תֵיכְלוּן יָתֵיהּ בְּזִמְנָא דָא וְלָא לְדָרַיָא חַרְצֵיכוֹן יְהוֹן מְזַרְזִין מְסַנֵיכוֹן בְּרִיגְלֵיכוֹן וְחוּטְרֵיכוֹן בִּידֵיכוֹן וְתֵיכְלוּן יָתֵיהּ בִּבְהִילוּ דִשְׁכִינַת מָארֵי עַלְמָא מְטוּל דְּחַיְיסָא מִן קֳדָם יְיָ לְכוֹן הוּא\",0,0],[4,143,12,12,\"וְאִתְגְּלֵי בְּאַרְעָא דְמִצְרַיִם בִּשְׁכִינַת יְקָרִי בְּלֵילְיָא הָדֵין וְעִמִּי תִּשְׁעִין אַלְפִין רִבְוָון מַלְאָכִין מְחַבְּלִין וְאֶקְטוֹל כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מֵאֱנָשָׁא וְעַד בְּעִירָא וּבְכָל טַעֲוַות מִצְרָאֵי אֶעֱבֵיד אַרְבַּע דִינִין טַעֲוַות מַתְּכָא מִתְרַכְּכִין טַעֲוַות אַבְנָא מִתְגַּדְעִין טַעֲוַות פַּחֲרָא מִתְעַבְּדִין בְּקִיקִין טַעֲוַות אָעָא מִתְעַבְּדִין קְטַם דְּיִנְדְּעוּן מִצְרָאֵי אֲרוּם אֲנָא יְיָ\",0,0],[4,143,12,13,\"וִיהֵי דַּם נִכְסַת פִּסְחָא וּגְזֵרַת מְהוּלְתָּא מְעַרַב לְכוֹן לְמֶעֱבַד מִנֵּיהּ אָת עַל בָּתַּיָא דְּאַתּוּן שַׁרְיָן תַּמָּן וְאֶחֱמֵי יַת זְכוּת דְּמָא וְאֵיחוּס עֲלֵיכוֹן וְלָא יִשְׁלוֹט בְּכוֹן מַלְאָךְ מוֹתָא דְּאִתְיַהַב לֵיהּ רְשׁוּתָא לִמְחַבְּלָא בְּמִקְטְלִי בְּאַרְעָא דְּמִצְרָיִם\",0,0],[4,143,12,14,\"וִיהֵי יוֹמָא הָדֵין לְכוֹן לְדוּכְרָנָא וּתְחַגּוּן יָתֵיהּ חַגָּא קֳדָם יְיָ לְדָרֵיכוֹן קְיַים עֲלָם תַּחֲגוּנֵיהּ\",0,0],[4,143,12,15,\"שַׁבְעַת יוֹמִין פַּטִּירָא תֵיכְלוּן בְּרַם מִפַּלְגוּת יוֹמָא דְמִיקַמֵּי חַגָּא תְבַטְּלוּן חָמִיר מִבָּתֵּיכוֹן אֲרוּם כָּל דְּיֵיכוּל חָמִיעַ וְיִשְׁתֵּיצֵי אֵינָשָׁא הַהוּא מִיִּשְרָאֵל לְמִיּוֹמָא קַדְמָאָה דְחַגָּא וְעַד יוֹמָא שְׁבִיעָאָה\",0,0],[4,143,12,16,\"וּבְיוֹמָא קַדְמָאָה מְעָרַע קַדִּישׁ וּבְיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִּישׁ יְהֵי לְכוֹן כָּל עֲבִידְתָּא לָא יִתְעֲבֵיד בְּהוֹן לְחוֹד מִן דְּיִתְעֲבֵד לְמֵיכַל כָּל נֶפֶשׁ אִיהוּ בִּלְחוֹדוֹי יִתְעֲבֵיד לְכוֹן\",0,0],[4,143,12,17,\"וְתִטְרוּן יַת לִישָׁתָא דְּפַטִּירֵי אֲרוּם בִּכְרַן יוֹמָא הָדֵין הַנְפֵּיק יְיָ יַת חֵילֵיכוֹן פְּרִיקִין מֵאַרְעָא דְמִצְרַיִם וְתִטְרוּן יַת יוֹמָא הָדֵין לְדָרֵיכוֹן קְיַם עֲלָם\",0,0],[4,143,12,18,\"בְּנִיסָן בְּאַרְבֵּיסַר יוֹמִין לְיַרְחָא תִּכְסוּן יַת פִּסְחָא וּבְרַמְשָׁא דְּחַמְסַר תֵּיכְלוּן פַּטִּירֵי עַד יוֹמָא דְעַשְרִין וְחַד לְיַרְחָא בְּרַמְשָׁא דְעַשְרִין וּתְרֵין תֵּיכְלוּן חָמִיעַ\",0,0],[4,143,12,19,\"שׁוּבְעָא יוֹמִין חָמִיר לָא יִשְׁתְּכַח בְּבָתֵּיכוֹן אֲרוּם כָּל מַאן דְּיֵיכוּל מַחְמְעָא וְיִשְׁתֵּיצֵי בַּר נְשָׁא הַהוּא מִכְּנִשְׁתָּא דְיִשְרָאֵל בְּדִיוֹרֵי וּבְיַצִּיבֵי דְאַרְעָא\",0,0],[4,143,12,20,\"כָּל עַרְבִיבֵי דִּמְחָמַע לָא תֵיכְלוּן בְּכָל אֲתַר מוֹתְבָנֵיכוֹן תֵּיכְלוּן פַּטִירֵי\",0,0],[4,143,12,21,\"וּקְרָא משֶׁה לְכָל סָבֵי יִשְרָאֵל וַאֲמַר לְהוֹן נְגוּדוּ יְדֵיכוֹן מִטַּעֲוַות מִצְרָאֵי וּסְבוּ לְכוֹן מִן בְּנֵי עָנָא לְיִיחוּסֵיכוֹן וְכוּסוּ אִימַר פִּסְחָא\",0,0],[4,143,12,22,\"וְתִסְבוּן אֵיסָרַת אֵזוֹבָא וְתִטְמְשׁוּן בְּדָמָא דִבְמַן פַּחֲרָא וְתַדוּן לְאִיסְקוֹפָא עִלָּאָה מִלְּבַר וּלְתַרְתֵּין סִפַּיָא מִן דְּמָא דִבְמַן פַּחֲרָא וְאַתּוּן לָא תִפְקוּן אֱנַשׁ מִן תְּרַע בֵּיתֵיהּ עַד צַפְרָא\",0,0],[4,143,12,23,\"וְיִתְגְּלֵי יְקָרָא דַיְיָ לְמִימְחֵי יַת מִצְרָאֵי וְיֶחֱמֵי יַת אַדְמָא דְעַל אִסְקוֹפָא וְעַל תַּרְתֵּין סִיפַיָא וְיָגִין מֵימְרָא דַיְיָ עַל תַּרְעָא וְלָא יִשְׁבּוֹק מַלְאָכָא מְחַבְּלָא לְמֵיעוֹל לְבָתֵּיכוֹן לְמִימְחֵי\",0,0],[4,143,12,24,\"וְתִיטְרוּן יַת פִּתְגָמָא הָדֵין לִקְיַם לָךְ וְלִבְנָךְ דְּכוּרַיָא עַד עַלְמָא\",0,0],[4,143,12,25,\"וִיהֵי אֲרוּם תַּעֲלוּן לְאַרְעָא דְּעָתִיד לְמִתַּן לְכוֹן יְיָ הֵיכְמָא דְמַלֵּיל וְתִיטְרוּן מִזְמַן דְּתִמְטוֹן לְתַמָּן יַת פּוּלְחָנָא הֲדָא\",0,0],[4,143,12,26,\"וִיהֵי אֲרוּם יֵימְרוּן לְכוֹן בְּנֵיכוֹן בְּזִמְנָא הַהוּא מַה פּוּלְחָנָא הָדָא לְכוֹן\",0,0],[4,143,12,27,\"וְתֵימְרוּן נִכְסַת חַיְיסָא הוּא קֳדָם יְיָ דְחַס בְּמֵימְרֵיהּ עַל בָּתֵּי בְּנֵי יִשְרָאֵל בְּמִצְרַיִם בְּחַבְּלוּתֵיהּ יַת מִצְרָאֵי וְיַת בָּתָּנָא שֵׁיזִיב וְכַד שָׁמְעוּ בֵּית יִשְרָאֵל יַת פִּתְגָמָא הָדֵין מִפּוּם משֶׁה גָּחְנוּ וּסְגִידוּ\",0,0],[4,143,12,28,\"וַאֲזָלוּ וַעֲבָדוּ בְּנֵי יִשְרָאֵל הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה וְיַת אַהֲרן הֵיכְדֵין אִיזְדַרְזוּ וַעֲבָדוּ\",0,0],[4,143,12,29,\"וַהֲוָה בְּפַלְגוּת לֵילְיָא דַּחֲמֵיסַר וּמֵימְרָא דַיְיָ קָטַל כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מִבִּיר בּוּכְרָא דְפַרְעה דְּעָתִיד לְמִיתַּב עַל כּוּרְסֵי מַלְכוּתֵיהּ עַד בּוּכְרַיָיא בְּנֵי מַלְכַיָא דְאִשְׁתְּבִין וְאִינוּן בֵּי גוֹבָא מִתְמַשְׁכְּנִין בְּיַד פַּרְעה וְעַל דַּהֲווֹ חָדָן בְּשִׁעְבּוּדְהוֹן דְּיִשְרָאֵל לָקוּ אוּף הִינוּן וְכָל בּוּכְרֵי בְּעִירָא מֵתוּ דְּמִצְרָאֵי פַּלְחִין לְהוֹן\",0,0],[4,143,12,30,\"וְקָם פַּרְעה בְּלֵילְיָא הוּא וְכָל שְׁאָר עַבְדוֹי וְכָל שְׁאָר מִצְרָאֵי וַהֲוָה צְוַוחְתָּא רַבְּתָא אֲרוּם לָא הֲוָה תַּמָּן בֵּיתָא דְמִצְרָאֵי דְלָא הֲוָה תַמָּן בְּכוֹר מָאִית\",0,0],[4,143,12,31,\"וּתְחוּם אַרְעָא דְמִצְרַיִם מַהֲלָךְ אַרְבַּע מְאָה פַּרְסֵי הֲוַת וְאַרְעָא דְגוֹשֶׁן דְּתַמָּן משֶׁה וּבְנֵי יִשְרָאֵל בִּמְצִיעוּת אַרְעָא דְמִצְרַיִם הֲוַת וּפַלְטְרִין דְּבֵית מַלְכוּתָא דְפַרְעה בְּרֵישׁ אַרְעָא דְמִצְרַיִם הֲוָה וְכַד קְרָא לְמשֶׁה וּלְאַהֲרן בְּלֵילְיָא דְפִסְחָא אִשְׁתְּמַא קָלֵיהּ עַד אַרְעָא דְגשֶׁן מִתְחַנֵּן הֲוָה פַּרְעה בְּקַל עָצִיב וְכֵן אָמַר קוּמוּ פּוּקוּ מִגּוֹ עַמִּי אוּף אַתּוּן אוּף בְּנֵי יִשְרָאֵל וְזִילוּ פְלָחוּ קֳדָם יְיָ הֵיכְמָא דַאֲמַרְתּוּן\",0,0],[4,143,12,32,\"אוּף עַנְכוֹן אוּף תּוֹרֵיכוֹן דְּבָרוּ מִן דִּילִי הֵיכְמָא דְמַלֵּילְתּוּן וְזִילוּ וְלֵית אֲנָא בָּעֵי מִנְכוֹן אֱלָהֵין דְּתַצְלוּן עָלַי דְלָא אֵימוּת\",0,0],[4,143,12,33,\"וְכַד שְׁמָעוּ משֶׁה וְאַהֲרן וּבְנֵי יִשְרָאֵל קָל בְּכוּתָא דְפַרְעה וְלָא אַשְׁגָחוּ עַד דְּאָזַל הוּא וְכָל עַבְדוֹי וְכָל מִצְרָאֵי וּתְקִיפוּ לְכָל עַמָּא בֵּית יִשְרָאֵל לְמִפְטְרִינוּן מִן אַרְעָא אֲרוּם אָמְרִין אִי שַׁהְיַין הִינוּן הָכָא שַׁעְתָּא חָדָא הָא כּוּלָנָא מַיְיתוּן\",0,0],[4,143,12,34,\"וּנְטַל עַמָּא יַת לֵישֵׁיהוֹן עֲלוֹי רֵישֵׁיהוֹן עַד דְּלָא אַחְמָע וּמִן דְּמִשְׁתַּיֵּיר לְהוֹן מִן פַּטִּירֵי וּמְרִירִי סוֹבָרוּ צְרִיר בִּלְבוּשֵׁיהוֹן עַל כַּתְפֵיהוֹן\",0,0],[4,143,12,35,\"וּבְנֵי יִשְרָאֵל עָבָדוּ כְּפִתְגָמָא דְמשֶׁה וְשַׁיְילוּ מִן מִצְרָאֵי מָנִין דִּכְסַף וּמָנִין דִּדְהַב\",0,0],[4,143,12,36,\"וַיְיָ יְהַב יַת עַמָּא לְחֵן וָחֶסֶד קֳדָם מִצְרָאֵי וְשַׁיְילִינוּן וְרוֹקִינוּן יַת מִצְרָאֵי מִנִכְסֵיהוֹן\",0,0],[4,143,12,37,\"וּנְטָלוּ בְּנֵי יִשְרָאֵל מִן פִּילוּסִין לְסוּכּוֹת מְאָה וּתְלָתִין מִילִין תַּמָּן אִיתְחַפִּיאוּ שִׁבְעַת עֲנָנֵי יְקָרָא אַרְבָּעָה מֵאַרְבַּע צִיטְרֵיהוֹן וְחַד מֵעִילַוֵּיהוֹן דְּלָא יֵיחוֹת עֲלֵיהוֹן מִטְרָא וּבַרְדָא וְלָא יִתְחַרְכוּן בִּשְׁרָבֵי שִׁמְשָׁא וְחַד מִלְּרַע לְהוֹן דְּלָא יְהַנְזְקוּן לְהוֹן כּוּבִין וְלָא חֵיוִין וְעַקְרַבִּין וְחָד מְטַיָּיל קוּמֵיהוֹן לְאַשְׁוָאָה עוּמְקַיָא וּלְמֵימַךְ טוּרַיָא לְאַתְקָנָא לְהוֹן בֵּית מֵשְׁרוֹי וְהִינוּן כְּשִׁית מֵאָה אַלְפִין גּוּבְרַיָא וּמְטַיְילִין עַל רִיגְלֵיהוֹן וְלָא רַכְבִין עַל סוּסְוָון בַּר מִטַּפְלָא חַמְשָׁא לְכָל גַּבְרָא\",0,0],[4,143,12,38,\"וְאוּף נוּכְרָאִין סַגִּיאִין מִנְהוֹן מָאתָן וְאַרְבְּעִין רִבְוָון סַלִּיקוּ עִמְהוֹן וְעָאָן וְתוֹרֵי וְגֵיתֵי סַגִּי לַחֲדָא\",0,0],[4,143,12,39,\"וַהֲווֹ קַטְעִין מִן לִישָׁא דְאַפִּיקוּ מִמִּצְרַיִם וְסַדְרִין עַל רֵישֵׁיהוֹן וּמִתְאַפֵּי לְהוֹן מְחוּמְתָּא דְשִׁימְשָׁא חֲרִירַן פַּטִירַן אֲרוּם לָא חָמִיעַ אֲרוּם אִיתְרִיכוּ מִמִּצְרַיִם וְלָא יָכִילוּ לְמִישְׁהֵי וְסַפִּיקָא לְהוֹן לְמֵיכַל עַד חֲמֵיסַר יוֹמִין לְיַרְחָא דְאִיָּיר מְטוֹל דִּזְוָודִין לָא עֲבָדוּ לְהוֹן\",0,0],[4,143,12,40,\"וְיוֹמַיָא דְיָתִיבוּ בְּנֵי יִשְרָאֵל בְּמִצְרַיִם תְּלָתִין שְׁמִיטִין דִּשְׁנִין דִּסְכוּמְהוֹן מָאתָן וְעֶשֶר שְׁנִין וּמִנְיַן אַרְבַּע מְאָה וּתְלָתִין שְׁנִין מִן דְּמַלֵּיל יְיָ לְאַבְרָהָם מִן שַׁעְתָּא דְמַלֵּיל עִמֵּיהּ בַּחֲמֵיסַר בְּנִיסָן בֵּינֵי פְּסוּגַיָיא עַד יוֹמָא דִּנְפָקוּ מִמִּצְרַיִם\",0,0],[4,143,12,41,\"וַהֲוָה מִסּוֹף תְּלָתִין שְׁנִין מִדְאִיתְגַּזְרַת גְּזֵירְתָּא הָדָא עַד דְּאִיתְיְלִיד יִצְחָק עַד דִנְפָקוּ פְּרִיקִין מִמִּצְרַיִם אַרְבַּע מְאָה שְׁנִין וַהֲוָה בִּכְרַן יוֹמָא הָדֵין נְפָקוּ כָּל חֵילַיָא דַיְיָ פְּרִיקִין מֵאַרְעָא דְּמִצְרָיִם\",0,0],[4,143,12,42,\"אַרְבָּעָה לֵילְוָון כְּתִיבִין בְּסֵפֶר דּוּכְרָנַיָיא קֳדָם רִבּוֹן עַלְמָא לֵילְיָא קַדְמָאָה כַּד אִיתְגְּלֵי לְמִבְרֵי עַלְמָא תִּנְיָינָא כַּד אִיתְגְּלֵי עַל אַבְרָהָם תְּלִיתָאָה כַּד אִיתְגְּלֵי בְּמִצְרַיִם וַהֲוָת יְדֵיהּ מְקַטְלָא כָּל בּוּכְרָא דְמִצְרַיִם וִימִינֵיהּ מְשֵׁיזְבָא בְּכוֹרֵיהֶן דְּיִשְרָאֵל רְבִיעָאָה כַּד אִתְגְּלֵי לְמִפְרוֹק עַמָּא בֵּית יִשְרָאֵל מִבֵּינֵי עַמְמַיָא וְכוּלְהוֹן קָרָא לֵילֵי נְטִיר בְּגִין כֵּן פָּרִישׁ משֶׁה וַאֲמַר לֵיל נְטִיר לְפוּרְקַן הוּא מִן קֳדָם יְיָ לְמַפְקָא יַת עַמָּא בְּנֵי יִשְרָאֵל מֵאַרְעָא דְמִצְרַיִם הוּא לֵילְיָא הָדֵין נְטִיר מִמַּלְאָכָה מְחַבְּלָא לְכָל בְּנֵי יִשְרָאֵל דִּבְמִצְרַיִם וְכֵן לְמִיפְרַקְהוֹן מִגַּלְוַותְהוֹן לְדָרֵיהוֹן:\",0,0],[4,143,12,43,\"וַאֲמַר יְיָ לְמשֶׁה וְאַהֲרן דָּא הִיא גְזֵירַת פִּסְחָא כָּל בַּר עַמְמִין אוֹ בַּר יִשְרָאֵל דְּאִיסְתְּלַק וְלָא הָדַר לָא יֵיכוּל בֵּיהּ\",0,0],[4,143,12,44,\"וְכָל גּוּבְרָאֵי דְּאִזְדַּבַּן לְעֶבֶד לְגַבְרָא בַּר יִשְרָאֵל זַבִּין כַּסְפָּא וְתִגְזוֹר יָתֵיהּ וְתִטְבְּלִינֵיהּ בְּכֵן יֵיכוּל בֵּיהּ\",0,0],[4,143,12,45,\"דַּיוֹר תּוֹתַב וַאֲגִירָא נוּכְרָאָה לָא יֵיכוֹל בֵּיהּ\",0,0],[4,143,12,46,\"בַּחֲבוּרָא חָדָא יִתְאָכֵל לָא תִפְקוּן מִן בֵּיתָא מִן בִּשְרָא בַּר מֵחֲבוּרָתָא וְלָא לִמְשַׁדְרָא דוֹרוֹנִין גְּבַר לְחַבְרֵיהּ וּגְרָמָא לָא תְתַבְּרִין בֵּיהּ בְּדִיל לְמֵיכוּל מַה דִּבְגַוֵּיהּ\",0,0],[4,143,12,47,\"כָּל כְּנִשְׁתָּא דְיִשְרָאֵל מִתְעַרְבִין דֵּין גְנִיסָא עִם דֵּין גְּנִיסְתָּא אוֹחֲרִי לְמֶעֱבַד יָתֵיהּ\",0,0],[4,143,12,48,\"וַאֲרוּם יִתְגַּיַּיר עִמְכוֹן גִּיּוֹרָא וְיַעֲבֵד פִּסְחָא קֳדָם יְיָ יִגְזוֹר לֵיהּ כָּל דְּכוּרָא וּבְכֵן יְהֵי כָּשֵׁר לְמֶעֱבְדֵיהּ וִיהֵי כְּיַצִיבָא דְאַרְעָא וְכָל עַרְלָאֵי בַּר יִשְרָאֵל לָא יֵיכוּל בֵּיהּ\",0,0],[4,143,12,49,\"אוֹרַיְיתָא חָדָא תְּהֵא לְכָל מִצְוָותָא לְיַצִּיבָא וּלְגִיּוֹרָא דִי מִתְגַּיֵּיר בֵּינֵיכוֹן\",0,0],[4,143,12,50,\"וַעֲבָדוּ כָּל בְּנֵי יִשְרָאֵל הֵיכְמָא דְפַּקִּיד יְיָ יַת משֶׁה וְיַת אַהֲרן הֵיכְדֵין עָבָדוּ\",0,0],[4,143,12,51,\"וַהֲוָה בִּכְרַן יוֹמָא הָדֵין אַפֵּיק יְיָ יַת בְּנֵי יִשְרָאֵל מֵאַרְעָא דְמִצְרַיִם עַל חֵילֵיהוֹן\",0,0],[4,143,13,1,\"וּמַלֵּיל יְיָ עִם משֶׁה לְמֵימָר\",0,0],[4,143,13,2,\"אַקְדֵישׁ קֳדָמַי כָּל בּוּכְרָא דְכוּרַיָא פְּתַח כָּל וַולְדָא בִּבְנֵי יִשְרָאֵל בְּאֵינָשָׁא וּבִבְעִירָא דִילִי הוּא\",0,0],[4,143,13,3,\"וַאֲמַר משֶׁה לְעַמָּא הֲווֹן דְּכִירִין יַת יוֹמָא הָדֵין דִּי נְפַקְתּוּן פְּרִיקִין מִמִצְרַיִם מִבֵּית שִׁעְבּוּד עֲבָדַיָיא אֲרוּם בִּתְקוֹף גְּבוּרַת יְדָא אַפֵּיק יְיָ יַתְכוֹן מִיכָּא וְלָא יִתְאָכֵל חָמִיעַ\",0,0],[4,143,13,4,\"יוֹמָא דֵין אַתּוּן נַפְקוּן פְּרִיקִין בַּחֲמֵיסַר בְּנִיסָן הוּא יַרְחָא דְּאַבִּיבָא\",0,0],[4,143,13,5,\"וִיהֵי אֲרוּם יֵיעָלִינָךְ יְיָ אֱלָהָךְ לְאַרַע כְּנַעֲנָאֵי חִיתָּאֵי וְאֵימוֹרָאֵי וְחִיוָאֵי וִיבוּסָאֵי דְּקַיֵּים בְּמֵימְרֵיהּ וּלְאַבְהָתָךְ לְמִיתַּן לָךְ אַרְעָא עַבְדָא חֲלָב וּדְבָשׁ וְתִפְלַח יַת פּוּלְחָנָא הָדָא בְּיַרְחָא הָדֵין\",0,0],[4,143,13,6,\"שׁוּבְעָא יוֹמִין תֵּיכוּל פַּטִּירָא וּבְיוֹמָא שְׁבִיעָאָה חַגָּא קֳדָם יְיָ\",0,0],[4,143,13,7,\"פַּטִּירֵי יִתְאָכֵיל יַת שׁוּבְעָא יוֹמִין וְלָא יִתְחָמֵי לָךְ חָמִיעַ וְלָא יִתְחָמֵי לָךְ חֲמִיר בְּכָל תְּחוּמָךְ\",0,0],[4,143,13,8,\"וְתִתְנֵי לִבְרָךְ בְּיוֹמָא הַהוּא לְמֵימָר מִן בִּגְלַל מִצְוָותָא דָא עֲבַד מֵימְרָא דַיְיָ לִי נִיסִין וּפְרִישִׁין בְּמִפְקֵי מִמִּצְרָיִם\",0,0],[4,143,13,9,\"וִיהֵי לָךְ נִיסָא הָדֵין חֲקִיק וּמְפָרַשׁ עַל תְּפִילַת יְדָא בְּגוּבְהָא דִשְמָאלָךְ וּלְדוּכְרָן חֲקִיק וּמְפָרַשׁ עַל תְּפִלַּת רֵישָׁא קְבִיעָא כָּל קָבֵיל עֵינָךְ בְּגוּבְהָא לְרֵישָׁךְ מִן בִּגְלַל דְּתִיהֲוֵי אוֹרַיְיתָא דַיְיָ בְּפוּמָךְ אֲרוּם בְּחֵיל יְדָא תַקִיפְתָּא הַנְפָקָךְ יְיָ מִמִּצְרָיִם\",0,0],[4,143,13,10,\"וְתִנְטוֹר יַת קְיָימָא הָדָא דִתְפִילֵי לְזִימְנָא דְחָזֵי לָהּ בְּיוֹמֵי עוֹבָדָא וְלָא בְּשַׁבַּיָיא וּבְמוֹעֲדַיָא וּבִימָמָא וְלָא בְּלֵילְיָא\",0,0],[4,143,13,11,\"וִיהֵי אֲרוּם יָעֵלִינָךְ יְיָ לְאַרְעָא דְכְנַעֲנָאֵי הֵיכְמָא דְקַיֵּים לָךְ וּלְאַבְהָתָךְ וְיִתְּנִינָהּ לָךְ\",0,0],[4,143,13,12,\"וְתַפְרֵשׁ כָּל פְּתַח וַולְדָא קֳדָם יְיָ וְכָל פְּתַח וַולְדָא בְּעִירָא דְּמֵשַׁגְרָא אִמֵּיהּ דִּיהוֹן לִיךְ דִּכְרִין תַּקְדֵּישׁ קֳדָם יְיָ\",0,0],[4,143,13,13,\"וְכָל פְּתַח וַולְדָא דְחַמְרָא תִּפְרוֹק בְּאִימְרָא וְאִין לָא תִפְרוֹק וְתִנְקוֹף יָתֵיהּ וְכָל בּוּכְרָא דְּאֵינָשָׁא בִּבְרָךְ תִּפְרוֹק בְּכַסְפָּא וְלָא בְּעַבְדָךְ תִּפְרוֹק\",0,0],[4,143,13,14,\"וִיהֵי אֲרוּם יְשַׁיְילִינָךְ בְּרָךְ מְחַר לְמֵימַר מַה דָּא מִצְוָותָא דְבוּכְרַיָיא וְתֵימַר לֵיהּ בִּתְקוֹף יְדָא אַפְקָנָא יְיָ מִמִּצְרַיִם פְּרִיקִין מִבֵּית שִׁעֲבּוּד עַבְדַיָא\",0,0],[4,143,13,15,\"וַהֲוָה כַּד אַקְשֵׁי מֵימְרָא דַיְיָ יַת לִבָּא דְפַרְעה לְמִפְטְרָנָא וְקָטַל יְיָ כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מִן בּוּכְרָא דְּאֵינָשָׁא וְעַד בּוּכְרָא דִבְעִירָא בְּגִין כֵּן אֲנָא דַבַּח קֳדָם יְיָ כָּל פְּתַח וַולְדָא דוּכְרַיָיא וְכָל בּוּכְרָא דִבְרַיי אֶפְרוֹק בְּכַסְפָּא\",0,0],[4,143,13,16,\"וִיהֵי לְאַת חֲקִיק וּמְפָרֵשׁ עַל יַד שְמָאלָךְ וְלִתְפִילִין בֵּין רִיסֵי עֵינָךְ אֲרוּם בִּתְקוֹף גְּבוּרַת יְדָא הַנְפָקָנָא יְיָ מִמִּצְרָיִם\",0,0],[4,143,13,17,\"ויהי וַהֲוָה כַּד פְּטַר פַּרְעה יַת עַמָּא וְלָא דַבְּרִינוּן יְיָ אוֹרַח אֲרַע פְּלִישְׁתָּאֵי אֲרוּם קָרֵיב הוּא אֲרוּם אֲמַר יְיָ דִלְמָא יִתְהֲווֹן עַמָּא בְּמֵיחְמֵיהוֹן אֲחוּהוֹן דְּמִיתַן בִּקְרָבָא מָאתָן אַלְפִין גּוּבְרִין בְּנֵי חֵילָא מִשִּׁבְטָא דְאֶפְרַיִם מְאַחֲדִין בִּתְרִיסִין וְרוּמְחִין וּמָאנֵי זַיְינִין וְנַחֲתוּ לְגַת לְמֵיבוּז גֵּיתֵי פְּלִישְׁתָּאֵי וּבְגִין דַּעֲבָרוּ עַל גְּזֵרַת מֵימְרָא דַיְיָ וּנְפָקוּ מִמִּצְרַיִם תְּלָתִין שְׁנִין קֳדָם קִיצָא אִיתְמַסְרוּ בִּידָא דִפְּלִישְׁתָּאֵי וּקְטָלוּנוּן הִינוּן הֲווֹ גַרְמַיָא יְבֵישַׁיָא דְאָחֵי יַתְהוֹן מֵימְרָא דַיְיָ עַל יְדָא דִיְחֶזְקֵאל נְבִיָא בְּבִקְעַת דּוּרָא וְאִין יֶחְמוּן כְּדֵין יִדְחֲלוּן וִיתוּבוּן לְמִצְרָיִם\",0,0],[4,143,13,18,\"וְאַחֲזַר יְיָ יַת עַמָּא אוֹרַח מַדְבְּרָא דְיַמָא דְסוּף וְכָל חַד עִם חַמְשָׁא טַפְלִין סְלִיקוּ בְּנֵי יִשְרָאֵל מֵאַרְעָא דְמִצְרָיִם\",0,0],[4,143,13,19,\"וְאַסֵּק משֶׁה יַת אֲרוֹנָא דְגַרְמֵי יוֹסֵף בְּגַוֵּיהּ מִן נִילוֹס וַהֲוָה מַדְבַּר עִמֵּיהּ אֲרֵי אוֹמָאָה אוֹמֵי יַת בְּנֵי יִשְרָאֵל לְמֵימַר מִדְכַּר יַדְכַּר יְיָ יַתְכוֹן וְתִסְקוּן יַת גַּרְמַי מִיכָּא עִמְכוֹן\",0,0],[4,143,13,20,\"וּנְטָלוּ מִסֻּכּוֹת אָתַר דְּאִתְחַפִּיּוּ בַּעֲנָנֵי יְקָרָא וּשְׁרוֹ בְאֵיתָם דְּבִסְטַר מַדְבְּרָא\",0,0],[4,143,13,21,\"וְאֵיקַר שְׁכִינְתָּא דַיְיָ מִידְבַּר קֳדָמֵיהוֹן בִּימָמָא בְּעַמּוּדָא דַעֲנָנָא לְדַבָּרוּתְהוֹן בְּאָרְחָא וּבְלֵילְיָא הָדַר עַמּוּדָא דַעֲנָנָא מִבַּתְרֵיהוֹן לְמַחְשַׁךְ לִדְרַדְפִין מִן בַּתְרֵיהוֹן וְעַמּוּדָא דְאֵישָׁתָא לְאַנְהָרָא קֳדָמֵיהוֹן לְמֵיזַל בִּימָמָא וּבְלֵילְיָא\",0,0],[4,143,13,22,\"לָא עֲדֵי עֲמוּדָא דַעֲנָנָא בִּימָמָא וְעַמוּדָא דְאֵישָׁתָא בְלֵילְיָא לְמַדְבְּרָא קֳדָם עַמָא\",0,0],[4,143,14,1,\"וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר\",0,0],[4,143,14,2,\"מַלֵיל עִם בְּנֵי יִשְרָאֵל וִיתוּבוּן לַאֲחוֹרֵיהוֹן וְיִשְׁרוּן קֳדָם פּוּמֵי חִירָתָא מַרְבִּיעָתָא דְאִתְבְּרִיוּ בְּגַוְונֵי בְּנֵי נְשָׁא דְכַר וְנוּקְבָא וְעַיְינִין פְּתִיחַן לְהוֹן הוּא אַתְרָא דְטָנֵיס דְּבֵינֵי מִגְדוֹל וּבֵינֵי יַמָּא קֳדָם טַעֲוַת צְפוֹן דְּמִשְׁתַּיֵּיר מִכָּל טַעֲוָון דְּמִצְרָיִם בְּגִין דְּיֵמְרוּן מִצְרָאֵי בָּחִיר הוּא בַּעַל צְפוֹן מִכָּל טַעֲוָותָא דְאִשְׁתַּיֵּיר וְלָא לָקָא דְיֵיתוּן לְמִסְגוֹד לֵיהּ וְיִשְׁכְּחוּן יַתְכוֹן דְּאַתּוּן שְׁרָן לְקִבְלֵיהּ עַל גֵּיף יַמָּא\",0,0],[4,143,14,3,\"וְיֵמַר פַּרְעה לְדָתָן וְלַאֲבִירָם בְּנֵי יִשְרָאֵל דְּמִשְׁתַּיְירוּן בְּמִצְרַיִם מְטַרְפִין הִינוּן עַמָּא בֵּית יִשְרָאֵל בְּאַרְעָא טָרַד עֲלֵיהוֹן טַעֲוַות צְפוֹן נַגְדוֹי דְּמַדְבְּרָא\",0,0],[4,143,14,4,\"וְאַתְקֵיף יַת יִצְרָא דְּלִבָּא דְּפַרְעה וְיִרְדוֹף בַּתְרֵיהוֹן וְאִתְיַקַר בְּפַרְעה וּבְכָל מִשְׁרְיָיתֵיהּ וְיִנְדְעוּן מִצְרָאֵי אֲרוּם אֲנָא הוּא יְיָ וַעֲבָדוּ הֵיכְדֵין\",0,0],[4,143,14,5,\"וְתַנוּן אוּקְטְרַיָא דַּאֲזָלוּ עִם יִשְרָאֵל אֲרוּם עָרִיק עַמָא וְאִיתְהַפִּיךְ לִבָּא דְפַרְעה וְעַבְדוֹי לְבִישׁ עַל עַמָא וַאֲמָרוּ מַה דָא עָבַדְנָא אֲרוּם פָּטַרְנָא יַת יִשְרָאֵל מִפּוּלְחָנָא\",0,0],[4,143,14,6,\"וְטַקֵיס אִיהוּ נַפְשֵׁיהּ יַת אַרְתְּכֵיהּ וְיַת עַמֵּיהּ דְּבַר עִמֵּיהּ בְּמִילִין רַכִּיכִין\",0,0],[4,143,14,7,\"וּדְבַר שִׁית מְאָה רְתִיכִין בְּחִירִין וְכָל רְתִיכֵי מִצְרָאֵי עַבְדוֹי דִדְחִילוּ מִפִּתְגָמָא דַיְיָ דְלָא מִיתוּ בְּמוֹתָנָא וְלָא בְּבַרְדָא וּמוֹלִיתָא תְּלִיתָתָא לְמִנְגַד וּלְמִרְדוֹף בִּבְהִילוּ אוֹסִיף עַל כָּל רְתִיכָא וּרְתִיכָא\",0,0],[4,143,14,8,\"וּתְקֵיף יְיָ יָת יִצְרָא דְלִבָּא דְפַרְעה מַלְכָּא דְמִצְרַיִם וּרְדַף בָּתַר בְּנֵי יִשְרָאֵל וּבְנֵי יִשְרָאֵל נַפְקִין בִּידָא מְרַמְמָא מִתְגַּבְּרִין עַל מִצְרָאֵי\",0,0],[4,143,14,9,\"וּרְדָפוּ מִצְרָאֵי בַּתְרֵיהוֹן וְאַדְבִּיקוּ יַתְהוֹן כַּד שְׁרָן עַל יַמָא כְנִיסִין מַרְגְּלַיָין וְאַבְנִין טָבָן דִדְּבַר פִּישׁוֹן מְגִינוּנִיתָא דְעֵדֶן לְגוֹ גִיחוֹן וְגִיחוֹן דַבָּרִינוּן לְיַמָא דְסוּף וְיַמָא דְסוּף רָמָא יַתְהוֹן עַל גֵּיפֵיהּ כָּל סוּסְוַות אַרְתִּיכֵי פַּרְעה וּפָרָשׁוֹי וּמַשְׁרְיִיתֵיהּ עַל פּוּמֵי חִירָתָא דִּקְדָם טַעֲוַות צְפוֹן\",0,0],[4,143,14,10,\"וּפַרְעה חָמָא טַעֲוַות צְפוֹן מִשְׁתְּזֵיב וּקְרֵיב קֳדָמוֹי קָרְבָּנִין וּזְקָפוּ בְּנֵי יִשְרָאֵל יַת עֵינֵיהוֹן וְהָא מִצְרָאֵי נַטְלִין בַּתְרֵיהוֹן וּדְחִילוּ לַחֲדָא וְצַלוּ בְנֵי יִשְרָאֵל קֳדָם יְיָ\",0,0],[4,143,14,11,\"וַאֲמָרוּ רַשִׁיעֵי דָרָא לְמשֶׁה הֲמִן בִּגְלַל דְּלָא הֲוַת לָנָא בֵּית קְבוּרְתָּא בְּמִצְרָיִם דְּבַרְתָּנָא לִמְמַת בְּמַדְבְּרָא מַה דָּא עָבַדְתְּ לָנָא לְהַנְפָּקוּתָנָא מִמִּצְרָיִם\",0,0],[4,143,14,12,\"הֲלָא דֵין הוּא פִּתְגָמָא דְמַלֵילְנָא עִמָּךְ בְּמִצְרַיִם יִתְגְּלֵי יְיָ עֲלֵיכוֹן וִידוּן לְמֵימַר פְּסַק מִנָנָא וְנִפְלַח יַת מִצְרָאֵי אֲרוּם טַב לָנָא דְּנִפְלַח יַת מִצְרָאֵי מִדְנָמוּת בְּמַדְבְּרָא\",0,0],[4,143,14,13,\"אַרְבַּע כִּיתַּן אִתְעֲבִידוּ בְּנֵי יִשְרָאֵל עַל גֵּיף יַמָא דְסוּף חֲדָא אָמְרָה נֵיחוֹת לְיַמָא וַחֲדָא אָמְרָה נֵיתוּב לְמִצְרַיִם וַחֲדָא אָמְרָה נְסַדְרָה לְקוּבְלֵיהוֹן סִדְרֵי קְרָבָא וַחֲדָא אָמְרָה נְבַלְבְּלָא לְקוּבְלֵיהוֹן וּנְעַרְבִבָה יַתְהוֹן כִּתָּא דַהֲוָה אָמְרָה נֵיחוּת לְיַמָא אָמַר לְהוֹן משֶׁה לָא תְדַחֲלוּן אִתְעַתְּדוּ וְחָמוּן יַת פּוּרְקָנָא דַיְיָ דְיַעֲבֵיד לְכוֹן יוֹמָא דֵין כִּתָּא דַּהֲוַת אָמְרָה נֵיתוּב לְמִצְרָיִם אָמַר לְהוֹן משֶׁה לָא תְתִיבוּן אֲרוּם הֵיכְמָא דַּחֲמִיתוּן יַת מִצְרָאֵי יוֹמָא דֵין לָא תוֹסְפוּן לְמֶיחְמֵיהוֹן תּוּב עַד עַלְמָא\",0,0],[4,143,14,14,\"כִּתָּא דַהֲוָה אָמְרָה נְסַדְרָה לְקוּבְלֵיהוֹן סִדְרֵי קְרָבָא אָמַר לְהוֹן משֶׁה לָא תַגִּיחוּן דְּמִן קֳדָם יְיָ מִתְעֲבֵיד לְכוֹן נִצְחָנוּת קָרְבֵיכוֹן כִּיתָּא דַּהֲוַת אָמְרָה נְבַלְבְּלָא לְקוּבְלֵיהוֹן אָמַר לְהוֹן משֶׁה שְְׁתוּקוּ וְהָבוּ יְקָרָא וְתּוּשְׁבַּחְתָּ וְרוֹמְמוּ לֵאֱלָקָכוֹן\",0,0],[4,143,14,15,\"וַאֲמַר יְיָ לְמשֶׁה לָמָה אַנְתְּ קָאֵי וּמַצְלֵי קֳדָמַי הָא צְלוֹתְהוֹן דְּעַמִּי קַדְמַת לְדִידָךְ מַלֵּיל עִם בְּנֵי יִשְרָאֵל וְיִטְלוּן\",0,0],[4,143,14,16,\"וְאַנְתְּ אֲרוּם יַת חוּטְרָךְ וְאַרְכִין יַת יְדָךְ בֵּיהּ עַל יַמָא וּבַזְעֵיהּ וְעָלוּן בְּנֵי יִשְרָאֵל בְּגוֹ יַמָּא בְּיַבֶּשְׁתָּא\",0,0],[4,143,14,17,\"וַאֲנָא הָא אֲנָא מַתְקִיף יַת יִצְרָא דְלִבְּהוֹן דְּמִצְרָאֵי וְיַעֲלוּן בַּתְרֵיהוֹן וְאִתְיְקַר בְּפַרְעה וּבְכָל מַשִׁירְיָיתֵיהּ בִּרְתִיכוֹי וּבְפָרָשׁוֹי\",0,0],[4,143,14,18,\"וְיֵדְעוּן מִצְרָאֵי אֲרוּם אֲנָא הוּא יְיָ בְּאִתְיַקָּרוּתִי בְּפַרְעה בִּרְתִיכוֹי וּבְפָרָשׁוֹי\",0,0],[4,143,14,19,\"וּנְטַל מַלְאָכָא דַיְיָ דְּמִדַּבַּר קֳדָם מַשְׁרְיָתָא דְיִשְרָאֵל וְאָתָא מִן בַּתְרֵיהוֹן וּנְטַל עַמּוּדָא דַעֲנָנָא מִן קֳדָמֵיהוֹן וּשְׁרָא מִן בַּתְרֵיהוֹן מִן בִּגְלַל מִצְרָאֵי דְפַתְקִין גִּירִין וְאַבְנִין לְיִשְרָאֵל וַהֲוָה עֲנָנָא מְקַבֵּל יַתְהוֹן\",0,0],[4,143,14,20,\"וְאָעֵיל בֵּין מַשִׁירְיָתָא דְיִשְרָאֵל וּבֵין מַשִּׁירְיָתָא דְמִצְרָאֵי וַהֲוָה עֲנָנָא פַּלְגֵיהּ נְהוֹרָא וּפַלְגֵיהּ חֲשׁוֹכָא מִסִּטְרֵיהּ חָד מַחֲשָׁךְ עַל מִצְרָאֵי וּמִסִּטְרֵיהּ חָד אַנְהַר עַל יִשְרָאֵל כָּל לֵילְיָא וְלָא קְרָבָא מַשְׁרֵי כָּל קְבֵיל מַשְׁרֵי לִמְסַדְרָא סִדְרֵי קְרָבָא כָּל לֵילְיָא\",0,0],[4,143,14,21,\"וְאַרְכִין משֶׁה יַת יְדֵיהּ עַל יַמָא בְּחוּטְרָא רַבָּא וְיַקִירָא דְּאִיתְבְּרִי מִן שֵׁירוּיָא וּבֵיהּ חָקִיק וּמְפָרֵשׁ שְׁמָא רַבָּא וְיַקִּירָא וְעִישַרְתֵּי אַתְוָותָא דִי מְחָא יַת מִצְרָאֵי וּתְלַת אַבְהַת עַלְמָא וְשִׁית אִימְהָתָא וּתְרֵיסַר שִׁבְטוֹי דְיַעֲקב וּמִן יַד דְּבַר יְיָ יַת יַמָא בְּרוּחַ קִידוּמָא תַקִיף כָּל לֵילְיָא וְשַׁוִי יַת יַמָא נְגִיבָא וְאִתְבְּזָעוּ מַיָא לִתְרֵיסַר בְּזִיעַן כָּל קְבֵיל תְּרֵיסַר שִׁבְטוֹי דְיַעֲקב\",0,0],[4,143,14,22,\"וְעָלוּ בְנֵי יִשְרָאֵל בְּגוֹ יַמָא בְּיַבֶּשְׁתָּא וּמַיָא קַרְשְׁווּן הֵי כְשׁוּרִין דְּמִן תְּלַת מְאָה מִילִין מִיַּמִינְהוֹן וּמִשְמָאלְהוֹן\",0,0],[4,143,14,23,\"וּרְדָפוּ מִצְרָאֵי וְעָלוּ מִן בַּתְרֵיהוֹן כָּל סוּסָוַות פַּרְעה רְתִיכוֹי וּפְרָשׁוֹי לְגוֹ יַמָּא\",0,0],[4,143,14,24,\"וַהֲוָה בְּמַטְרַת צַפְרָא בְּעִידָנָא דְאַתְיַין חַיְילֵי מְרוֹמָא לְשַׁבָּחָא וְאוֹדִיק יְיָ בִּרְגוֹז עֲלוֹי מַשְׁרִיתְהוֹן דְּמִצְרָאֵי בְּעַמּוּדָא דְאֵישָׁתָא לְמִירְמֵי עֲלֵיהוֹן גּוּמְרִין דְּאֵישָׁא וּבְעַמּוּדָא דַעֲנָנָא לְמִרְמָא עֲלֵיהוֹן בַּרְדִין וְשָׁעֲמָם יַת מַשִּׁרְיַית מִצְרָאֵי\",0,0],[4,143,14,25,\"וּנְסַר יַת גַּלְגַּלֵי רִידְוָותֵיהּ דְּפַרְעה וַהֲווֹ מְדַבְּרִין יַתְהוֹן בְּקַשְׁיוּ וַהֲווֹן מְהַלְכִין וְשַׁרְיָין מִן בַּתְרֵיהוֹן וַאֲמָרוּ מִצְרָאֵי אִלֵּין לְאִלֵּין נְעִירוֹק מִן עַמָּא בֵּית יִשְרָאֵל אֲרוּם מֵימְרָא דַיְיָ הוּא דִמְגִיחַ לְהוֹן קְרָבִין בְּמִצְרָאֵי\",0,0],[4,143,14,26,\"וַאֲמַר יְיָ לְמשֶׁה אַרְכַן יַת יְדָךְ עַל יַמָא וִיתוּבוּן מָאִין עַל מִצְרָאֵי עַל רְתִיכֵהוֹן וְעַל פָּרָשֵׁיהוֹן\",0,0],[4,143,14,27,\"וְאַרְכַן משֶׁה יַת יְדֵיהּ עַל יַמָא וְתַב יַמָא לְעִידוֹנֵי צַפְרָא לְתוּקְפֵיהּ וּמִצְרָאֵי עַרְקִין כָּל קְבֵיל גְּלָלוֹי וְעַלִּים יְיָ יַת מִצְרָאֵי בְּגוֹ יַמָא דְלָא יְמוּתוּן בְּמִצְעֵי מִן בִּגְלַל דִּיקַבְּלוּן פּוּרְעָנוּת דְּמִשְׁתַּלְחָא לְהוֹן\",0,0],[4,143,14,28,\"וְתָבוּ גַלְלֵי יַמָא וְחָפוּן יַת רְתִיכַיָיא וְיַת פַּרְשַׁיָא לְכָל מַשִּׁרְיַת פַּרְעה דְּעָלַן בַּתְרֵיהוֹן בְּיַמָא לָא אִישְׁתַּיֵּיר בְּהוֹן עַד חָד\",0,0],[4,143,14,29,\"וּבְנֵי יִשְרָאֵל הֲלִיכוּ בְּיַבֶּשְׁתָּא בְּגוֹ יַמָא וּמַיָא לְהוֹן הֵי כְשׁוּרִין מִיַמִּינְהוֹן וּמִשְמָאלֵהוֹן\",0,0],[4,143,14,30,\"וּפְרִיק וּשְׁזִיב יְיָ בְּיוֹמָא הַהוּא יַת יִשְרָאֵל מִן יְדֵיהוֹן דְּמִצְרָאֵי וְחָמוּן יִשְרָאֵל יַת מִצְרָאֵי מֵיתִין וְלָא מֵיתִין רְמָאִין עַל גֵּיף יַמָא\",0,0],[4,143,14,31,\"וְחָמוּן יִשְרָאֵל יַת גְּבוּרַת יְדָא תַקִיפְתָּא דִי עָבַד יְיָ בָּהּ נִיסִין בְּמִצְרַיִם וּדְחִילוּ עַמָא מִן קֳדָם יְיָ וְהֵימִינוּן בְּשׁוּם מֵימְרָא דַיְיָ וּבִנְבוּאָתֵיהּ דְּמשֶׁה עַבְדֵיהּ\",0,0],[4,143,15,1,\"הָא בְּכֵן שַׁבַּח משֶׁה וּבְנֵי יִשְרָאֵל יַת שְׁבַח שִׁירָתָא הָדָא קֳדָם יְיָ וְאָמְרִין לְמֵימָר נוֹדֶה וּנְשַׁבְּחָא קֳדָם יְיָ רְמָא דְמִתְגָּאֵי עַל גֵּיוְותָנַיָא וּמִתְנַטֵּל עַל מְנַטְלַיָא כָּל מַאן דְּמִתְגָּאֵי קֳדָמוֹי הוּא בְּמֵימְרֵיהּ פָּרַע מִנֵּיהּ עַל דִּי אָזִיד פַּרְעה רַשִׁיעָא קֳדָם יְיָ וְאִתְנַטַּל בִּלְבָבֵיהּ וּרְדַף בָּתַר עַמָּא בְּנֵי יִשְרָאֵל סוּסְוָון וְרוֹכְבֵיהוֹן רָמָא וּטְמַע יַתְהוֹן בְּיַמָא דְסוּף\",0,0],[4,143,15,2,\"תּוּקְפַן וְרוֹב תּוּשְׁבָּחָתָן דְּחֵיל עַל כָּל עָלְמַיָא יְיָ אָמַר בְּמֵימְרֵיהּ וַהֲוָה לִי אֱלָהָא פְּרוֹק מִן חַדְיֵי אִמְהוֹן הֲווֹן יַנְקַיָא מְחַוָון בְּאֶצְבָּעַתְהוֹן לְאַבְהַתְהוֹן וְאָמְרִין דֵּין הוּא אֱלָהָן דַּהֲוָה מוֹנִיק לָן דּוּבְשָׁא מִן כֵּיפָא וּמְשַׁח מִן שָׁמִיר טִינְרָא בְּעִידַן דְּאִימַן נַפְקַן לְאַנְפֵּי בָּרָא וִילֵדַן וְשַׁבְקַן יָתָן תַּמָּן וּתְשַׁדַר מַלְאָכָא וּמַסְחֵי יָתָן וּמְלַפֵּף יָתָן וּכְדוּן נַשְׁבְּחִינֵיהּ אֱלָהָא דְּאַבְהָתָן וּנְרוֹמְמִינֵיהּ\",0,0],[4,143,15,3,\"אָמְרִין בְּנֵי יִשְרָאֵל יְיָ גַבְרָא עָבֵיד קְרָבֵינָן בְּכָל דַּר וָדַר מִנְדַע גְּבוּרְתֵּיהּ לְעַמֵּיהּ בֵּית יִשְרָאֵל יְיָ שְׁמֵיהּ כִּשְׁמֵיהּ כֵּן גְּבוּרְתֵּיהּ יְהֵי שְׁמֵיהּ מְבָרַךְ לְעָלְמֵי עַלְמִין\",0,0],[4,143,15,4,\"אַרְתּוֹכֵי דְפַרְעה וְחֵילְוָותֵיהּ שַׁדָּא בְּיַמָא שִׁיפַּר עוּלְמֵי גִבְרוֹי רְמָא וּטְמַע יַתְהוֹן בְּיַמָא דְסוּף\",0,0],[4,143,15,5,\"תְּהוֹמַיָא כַּסּוּן עֲלֵיהוֹן נַחֲתוּ וְשַׁקָעוּ בִּמְצוּלְתֵיהּ דְּיַמָא אִידְמִין הֵי כְאַבְנָא\",0,0],[4,143,15,6,\"יְמִינָךְ יְיָ מַה מְּשַׁבְּחָא הִיא בְּחֵילָא יְמִינָךְ יְיָ תַּבְרִית בַּעַל דְּבָבֵיהוֹן דְּעַמָּךְ דְּקַיְימִין לְקוּבְלֵיהוֹן מִן בִּגְלַל לְאַבְאָשָׁא לְהוֹן\",0,0],[4,143,15,7,\"וּבְסוּגֵי גֵּיפְתָנוּתָךְ תְּפַכֵר שׁוּרֵי בַּעֲלֵי דְבָבֵיהוֹן דְּעַמָּךְ תְּגָרֵי בְהוֹן תְּקוֹף רוּגְזָךְ תְּגַמֵּר יַתְהוֹן הֵי כְנוּרָא בָּעֲרָא שַׁלְטָא בְּקַשָׁא\",0,0],[4,143,15,8,\"וּבְמֵימַר מִן קֳדָמָךְ אִתְעֲבִידוּ מַיָא עוּרְמַן עוּרְמַן קָמוּ לְהֵין צְרִירִין הֵי כְזִיקִין מַיָא נָזְלַיָא קָפוּ עֲלֵיהוֹן תְּהוֹמַיָא בְּגוֹ פִילְגוּס דְּיַמָא רַבָּא\",0,0],[4,143,15,9,\"דַּהֲוָה אָמַר פַּרְעה רַשִׁיעָא סַנְאָה וּבַעַל דְּבָבָא אֶרְדוֹף בָּתַר עַמָא בְּנֵי יִשְרָאֵל וְנָרַע יַתְהוֹן שַׁרְיָין עַל גֵּיף יַמָא וּמְסַדְרָא לְקוּבְלֵיהוֹן סִדְרָא קְרָבָא וְנִקְטוֹל בְּהוֹן קְטוֹל רַב וְסַגִי וְנָבִיז מִנְהוֹן בִּיזָא רַבָּא וְנַשְׁבֵּי מִנְהוֹן שִׁבְיָא רַבָּא וְאַפְלוּג בִּיזֵיהוֹן לְעַמִּי עַבְדֵּי קְרָבָא וְכַד תִּתְמְלֵי נַפְשִׁי מִן דָּם קְטוֹלֵיהוֹן מִן בָּתַר כְּדֵין אֶשְׁלוֹף חַרְבִּי וְאֵישֵׁיצֵי יַתְהוֹן בְּיַד יְמִינִי\",0,0],[4,143,15,10,\"אָשַׁבְתְּ בְּרוּחַ מִן קֳדָמָךְ יְיָ וְכָסִין עֲלֵיהוֹן גִּירִין דְּיַמָא נַחֲתוּ וְשָׁקְעוּ הֵי כְאַבְרָא מַיָא מַמְשַׁבְּחַיָא\",0,0],[4,143,15,11,\"מָן כְּוָותָךְ בְּאֵילֵי מְרוֹמָא יְיָ מָן כְּוָותָךְ הָדוּר בְּקוּדְשָׁא דָּחֵיל בְּתוּשְׁבְּחָן עֲבֵד נִסִין וּפְרִשַׁן לְעַמֵּיהּ בֵּית יִשְרָאֵל\",0,0],[4,143,15,12,\"יַמָא וְאַרְעָא הֲווֹן מְדַיְינִין דָּא עִם דָּא כַּחֲדָא יַמָא הֲוָה אָמַר לְאַרְעָא קַבִּילִי בְּנַיְיכִי וְאַרְעָא הֲוַת אָמְרָה לְיַמָא קַבֵּיל קְטִילָנַיִךְ לָא יַמָא הֲוָה בָּעֵי לְמִטְמַע יַתְהוֹן וְלָא אַרְעָא הֲוַת בַּעֲיָא לְמִבְלַע יַתְהוֹן דְּחִילָא הֲוַת אַרְעָא לְמִקְבְּלָא יַתְהוֹן מִן בִּגְלַל דְּלָא יִתְבְּעוּן גַּבָּהּ בְּיוֹם דִּינָא רַבָּא לְעַלְמָא דַּאֲתֵי הֵיכְמָא דְיִתְבַּע מִינָהּ דְּמֵי דְהֶבֶל מִן יַד אַרְכִינַת יַד יְמִינָךְ יְיָ בִּשְׁבוּעָה עַל אַרְעָא דְלָא יִתְבְּעוּן מִינָהּ לְעַלְמָא דְאָתֵי וּפְתָחַת אַרְעָא פּוּמָהּ וּבְלָעַת יַתְהוֹן\",0,0],[4,143,15,13,\"דַּבַּרְתְּ בְּחַסְדָּךְ עַמָךְ הָאִילֵין דִּי פָרַקְתְּ וְאַחֲסִינַת יַתְהוֹן טַוָור בֵּית מַקְדְּשָׁךְ מְדוֹר בֵּית שְׁכִינַת קוּדְשָׁךְ\",0,0],[4,143,15,14,\"שְׁמָעוּ אוּמַיָא יִתְרַגְזוּן דְּחִילָא אֲחָדַת יַת כָּל עַמּוּדֵי דַיְירֵי אַרְעֲהוֹן דִּפְּלִשְׁתָּאֵי\",0,0],[4,143,15,15,\"הָא בְּכֵן אִתְבַּהֲלוּן רַבְרְבָנֵי אֱדוֹמָאֵי תַּקִּיפֵי מוֹאֲבָאָה אֲחָדַת יַתְהוֹן רְתִיתָא אִתְמְסֵי לִבְּהוֹן בְּגַוֵּיהוֹן כָּל עַמּוּדֵי דַּיְירֵי אַרְעֲהוֹן דִּכְנַעֲנָאֵי\",0,0],[4,143,15,16,\"תַּפִּיל עֲלֵיהוֹן אֵימָתָא דְמוֹתָא וּדְחִילָתָא בִּתְקוֹף אֶדְרַע וּגְבוּרְתָּךְ יִשְׁתַּתְּקוּן הֵי כְאַבְנַיָא עַד זְמַן דִּי יַעֲבְרוּן עַמָּךְ יְיָ יַת נַחֲלֵי אַרְנוֹנָא עַד זְמַן דִּי יַעֲבְרוּן עַמָּךְ הָאִילֵין דְּקָנִיתָא יַת מְגוּזָתֵיהּ דְּיוּבְקָא\",0,0],[4,143,15,17,\"תָּעוּל יַתְהוֹן וְתִנְצוֹב יַתְהוֹן בְּטוּר בֵּית מַקְדְּשָׁךְ אָתַר דִּמְכֻוַּון קְבֵיל כּוּרְסֵי יְקָרָךְ מוּזְמַן קְבֵיל בֵּית שְׁכִינַת קָדְשָׁךְ אַתְקִינְתָּא יְיָ בֵּית מַקְדָּשָׁךְ יְיָ תַּרְתֵּין אִידְיָיךְ שַׁכְלִילוּ יָתֵיהּ\",0,0],[4,143,15,18,\"כַּד חָמוּן עַמָּא בֵּית יִשְרָאֵל יַת נִיסַיָא וְיַת פְּרִישְׁוָותָא דְּעָבַד לְהוֹן קוּדְשָׁא יְהֵי שְׁמֵיהּ מְשַׁבַּח עַל יַמָא דְסוּף וּגְבוּרַת יְדֵיהּ בְּנֵי גְּלַלְיָא עַנְיָין וְאָמְרִין אִילֵין לְאִילֵין אִיתוּ נִיתַּן כְּלִיל דִּרְבוּ בְּרֵישׁ פְּרוֹקַן דְּהוּא מַעֲבִיר וְלָא עָבַר דְּהוּא מַחֲלִיף וְלָא חֲלִיף דְּדִילֵיהּ הוּא כְּלִיל מַלְכוּתָא וְהוּא מֶלֶךְ מַלְכִין בְּעָלְמָא הָדֵין וְדִילֵיהּ הוּא מַלְכוּתָא לְעַלְמָא דְאָתֵי וְדִילֵיהּ הִיא וְהַוְיָא לְעָלְמֵי עַלְמִין\",0,0],[4,143,15,19,\"אֲרוּם עָלוּ סוּסְוַות פַּרְעה בִּרְתִיכוֹי וּבְפָרָשׁוֹי בְּיַמָא וְחָזַר יְיָ עֲלֵיהוֹן יַת מוֹי דְיַמָּא וּבְנֵי יִשְרָאֵל הֲלִיכוּ בְּיַבֶּשְׁתָּא בְּגוֹ יַמָא וְתַמָּן סַלְקוּן עִינָוַון בְּסִימָן וְאִילָנֵי מֵיכְלָא וְיַרְקֵי וּמִגְדֵי בְּאַרְעִית יַמָא\",0,0],[4,143,15,20,\"וּנְסֵיבַת מִרְיָם נְבִיאָתָא אַחְתֵיהּ דְּאַהֲרן יַת תּוּפָא בִידָהּ וְנַפְקָן כָּל נְשַׁיָא בַּתְרָאָה בְּתוּפַיָיא הֲווֹ חַיְילִין וּבְחִנְגַיָא מְחַנְגִין\",0,0],[4,143,15,21,\"וְזָמְרַת לְהוֹן מִרְיָם נוֹדֵי וּנְשַׁבְּחָא קֳדָם יְיָ אֲרוּם תּוּקְפָא וְרוֹמְמוּתָא דִידֵיהּ הוּא עַל גֵּיוְותָנִין הוּא מִתְגָאֵי וְעַל רָמִין הוּא מִתְנַטֵּל עַל דִּי אָזִיד פַּרְעה רַשִׁיעָא וְרָדַף בָּתַר עַמָּא בְּנֵי יִשְרָאֵל סוּסְוָותֵיהּ וּרְתִיכוֹי רְמָא וּטְמַע יַתְהוֹן בְּיַמָא דְסוּף\",0,0],[4,143,15,22,\"וְאַטֵּיל משֶׁה יַת יִשְרָאֵל מִן יַמָא דְסוּף וּנְפָקוּ לְמַדְבְּרָא דְּחָלוּצָא וְטַיְילוּ תְּלָתָא יוֹמִין בְּמַדְבְּרָא בְּטֵילִין מִן פִּיקוּדַיָיא וְלָא אַשְׁכָּחוּ מַיָא\",0,0],[4,143,15,23,\"וְאָתוּ לְמָרָה וְלָא יָכִילוּ לְמִשְׁתֵּי מוֹי מִמָּרָה אֲרוּם מְרִירִין הִינוּן בְּגִין כֵּן קְרָא שְׁמֵיהּ מָרָה\",0,0],[4,143,15,24,\"וְאִתְרַעֲמוּ עַמָא עַל משֶׁה לְמֵימַר מַה נִּשְׁתֵּי\",0,0],[4,143,15,25,\"וְצַלֵּי קֳדָם יְיָ וְאַחְוַיֵהּ לֵיהּ יְיָ אִילַן מְרִיר דְּאַרְדִפְנֵי וְכָתַב עֲלוֹי שְׁמָא רַבָּא וְיַקִּירָא וְטָלַק לְגוֹי מַיָא וְאִתְחַלּוּן מַיָא תַּמָּן שַׁוִי לֵיהּ מֵימְרָא דַיְיָ גְּזֵרַת שַׁבְּתָא וְקַיֵּים אִיקַר אַבָּא וְאִמָּא דִינֵי פִּדְעָא וּמַשְׁקוֹפֵי וּקְנָסִין דְמִקְנְסֵי לְחַיָּיבַיָא וְתַמָּן נַסְיָא בְּנִסְיוֹנָא עֲשִירְיָתָא\",0,0],[4,143,15,26,\"וַאֲמַר אִין קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ וּדְכָשַׁר קֳדָמוֹי תַּעֲבֵיד וְתַצֵּית לְפִקוּדוֹי וְתִנְטוֹר כָּל קְיָימוֹי כָּל מַרְעִין בִּישִׁין דְּשַׁוִּיתִי עַל מִצְרָאֵי לָא אַשְׁוִינוּן עֲלָךְ וְאִם תַּעַבְרוּן עַל פִּתְגָּמֵי אוֹרַיְיתָא וּמִשְׁתַּלְחִין עֲלָךְ אִין תְּתִיבוּן אַעֲדִינוּן מִנָךְ אֲרוּם אֲנָא הוּא יְיָ אַסְאָךְ\",0,0],[4,143,15,27,\"וְאָתוּ לְאֵלִים וּבְאֵלִים תַּרְתֵּי סְרֵי עֵינַוָון דְּמַיָין עַנְוָוא לְכָל שִׁבְטָא וְשׁוּבְעִין דִּקְלִין כָּל קְבֵיל שׁוּבְעִין סָבַיָא דְיִשְרָאֵל וּשְׁרוֹן תַּמָּן עַל מַיָא\",0,0],[4,143,16,1,\"וּנְטָלוּ מֵאֵלִים וְאָתוּן כָּל כְּנִשְׁתָּא דְּיִשְרָאֵל לְמַדְבְּרָא דְסִין דְּבֵין אֵלִים וּבֵין סִינָי בַּחֲמֵיסַר יוֹמִין לְיַרְחָא דְאִיָּיר הוּא יַרְחָא תִּנְיָנָא לְמִפַּקְהוֹן מֵאַרְעָא דְמִצְרָיִם\",0,0],[4,143,16,2,\"וּבְהַהוּא יוֹמָא פָּסַק לְהוֹן לִישָׁא דְאַפִּיקוּ מִמִּצְרַיִם וְאִתְרַעֲמוּן כָּל בְּנֵי יִשְרָאֵל עַל משֶׁה וְעַל אַהֲרן בְּמַדְבְּרָא\",0,0],[4,143,16,3,\"וַאֲמָרוּ לְהוֹן בְּנֵי יִשְרָאֵל הַלְוַאי דְּמִיתְנָא בְּמֵימְרָא דַיְיָ בְּאַרְעָא דְמִצְרַיִם כַּד הֲוֵינָא יַתְבִין עַל דִּדְוָתָא דְבִיסְרָא כַּד הֲוֵינָא אָכְלִין לַחְמָא וּשְבֵעִין אֲרוּם הַנְפַּקְתּוּן יָתָן לְמַדְבְּרָא הָדֵין לְקַטָלָא יַת כָּל קְהָלָא הָדֵין בְּכַפְנָא\",0,0],[4,143,16,4,\"וַאֲמַר יְיָ לְמשֶׁה הָא אֲנָא מָחִית לְכוֹן לַחֲמָא מִן שְׁמַיָא דְּאִיצְטְנַא לְכוֹן מִן שֵׁרוּיָא וְיִפְקוּן עַמָּא וְיִלְקְטוּן פִּתְגַּם יוֹם בְּיוֹמֵיהּ מִן בִּגְלַל לְנַסּוֹיֵיהוֹן אִין נַטְרִין מִצְוָותָא דְאוֹרַיְיתִי אִין לָא\",0,0],[4,143,16,5,\"וִיהֵי בְּיוֹמָא שְׁתִיתָאֵי וְיִזְמְנוּן מַה דְּיַיְתוּן לְקָמֵיהוֹן לְמֵיכַל בְּיוֹמָא דְּשַׁבַּתָּא וִיעַרְבוּן בְּבָתַּיָא וְיִשְׁתַּתְּפוּן בְּדָרָתֵיהוֹן בְּגִין לְמֵיתַיָיא מִדֵּין לְדֵין וִיהֵי לְהוֹן בְּכוּפְלָא עַל מַה דִּמְלַקְטוּן יוֹמָא יוֹמָא\",0,0],[4,143,16,6,\"וַאֲמַר משֶׁה וְאַהֲרן לְכָל בְּנֵי יִשְרָאֵל בְּרַמְשָׁא וְתִנְדְּעוּן אֲרוּם יְיָ אַפֵּיק יַתְכוֹן פְּרִיקִין מֵאַרְעָא דְמִצְרָיִם\",0,0],[4,143,16,7,\"וּבְצַפְרָא יִתְגְּלֵי עֲלֵיכוֹן יְקַר שְׁכִינְתָּא דַיְיָ כַּד שְׁמִיעַן קֳדָמוֹי יַת תּוּרְעֲמַתְכוֹן קֳדָם יְיָ וַאֲנַחְנָא מָה אֲנַן חֲשִׁיבִין אֲרוּם אִתְרַעַמְתּוּן עֲלָנָא\",0,0],[4,143,16,8,\"וַאֲמַר משֶׁה בְּדֵין תֵדְעוּן בִּדְיַזְמִין יְיָ לְכוֹן בְּרַמְשָׁא בִּישְרָא לְמֵיכוֹל וְלַחְמָא בְּצַפְרָא לְמִשְבּוֹעַ בְּדִשְׁמִיעַן קֳדָם יְיָ יַת תּוּרְעֲמוּתְכוֹן דְּאַתּוּן מִתְרַעֲמִין עֲלוֹי וַאֲנַחְנָא מָה אֲנַן חֲשִׁיבִין לָא עֲלָנָא תּוּרְעֲמַתְכוֹן אֱלָהֵן עַל מֵימְרָא דַיְיָ\",0,0],[4,143,16,9,\"וַאֲמַר משֶׁה לְאַהֲרן אֵימַר לְכָל כְּנִישְׁתָּא דִבְנֵי יִשְרָאֵל קְרִיבוּ קֳדָם יְיָ אֲרוּם שְׁמִיעַן קֳדָמוֹי יַת תּוּרְעֲמוּתְכוֹן\",0,0],[4,143,16,10,\"וַהֲוָה בְּמַלָלוּת אַהֲרן עִם כָּל כְּנִישְׁתָּא דְיִשְרָאֵל וְאִתְפְּנִיאוּ לְמַדְבְּרָא וְהָא יְקַר שְׁכִינְתָּא דַיְיָ אִתְגְּלֵי בַּעֲנַן יְקָרָא\",0,0],[4,143,16,11,\"וּמַלֵּיל יְיָ עִם משֶׁה לְמֵימָר\",0,0],[4,143,16,12,\"שְׁמִיעַ קֳדָמַי יַת תּוּרְעֲמוּת בְּנֵי יִשְרָאֵל מַלֵּיל עִמְהוֹן לְמֵימַר בֵּינֵי שִׁמְשְׁתָא תֵיכְלוּן בִּשְרָא וּבְצַפְרָא תֵיכְלוּן לַחְמָא וְתִנְדְּעוּן אֲרוּם אֲנָא הוּא יְיָ אֱלָהָכוֹן\",0,0],[4,143,16,13,\"וַהֲוָה בְּרַמְשָׁא וּסְלִיקוּ פִּיסְיוֹנִין וַחֲפוֹי יַת מַשְׁרִיתָא וּבְצַפְרָא הֲוָת אֲנָחַת טַלָּא מִתְקַדְּשָׁא מִיתַקְנָא הֵי כְּפָתּוּרִין חֲזוֹר חֲזוֹר לְמַשְׁרִיתָא\",0,0],[4,143,16,14,\"וּסְלִיקוּ עֲנָנַיָא וְאָחִיתוּ מַנָּא עִילַוֵי אֲנָחוּת טַלָא וַהֲוַת עַל אַנְפֵּי מַדְבְּרָא דְקִיק מְסַרְגֵּל דְּקִיק כִּגְלִידָא עַל אַרְעָא\",0,0],[4,143,16,15,\"וְחָמוּן בְּנֵי יִשְרָאֵל וַהֲווֹן תַּמְהִין וְאָמְרִין אֵינַשׁ לְחַבְרֵיהּ מַן הוּא אֲרוּם לָא יָדְעוּן מַה הוּא וַאֲמַר משֶׁה לְהוֹן הוּא לַחְמָא דְּאִצְטְנַא לְכוֹן מִן שֵׁירוּיָא בִּשְׁמֵי מְרוֹמָא וּכְדוּן יְהָבֵיהּ יְיָ לְכוֹן לְמֵיכַל\",0,0],[4,143,16,16,\"דֵּין פִּתְגָּמָא דְפַקֵּיד יְיָ לְקוּטוּ מִנֵיהּ גְבַר לְפוּם מֵיכְלֵיהּ עוּמְרָא לְגוּלְגַלְתָּא מִנְיַין נַפְשָׁתֵיכוֹן גְּבַר לְפוּם סְכוּם אִינְשֵׁי מַשְׁכְּנֵיהּ תִּסְבוּן\",0,0],[4,143,16,17,\"וַעֲבָדוּ כֵן בְּנֵי יִשְרָאֵל וּלְקִיטוּ מַנָּא מַאן דְּמַסְגֵי וּמַאן דְּאַזְעֵיר\",0,0],[4,143,16,18,\"וְאָכִילוּ בְּעוּמְרָא לָא אִישְׁתַּיֵּיר מִן מְכִילְתָּא מַאן דְּאַסְגֵי לְמִלְקַט וּדְאַזְעֵר לְמִילְקַט לָא חָסֵר מִן מְכִילְתָּא גְּבַר לְפוּם מֵיכְלֵיהּ לְקִיטוּ\",0,0],[4,143,16,19,\"וַאֲמַר משֶׁה לְהוֹן גְּבַר לָא יְשַׁיֵּיר מִנֵּיהּ עַד צַפְרָא\",0,0],[4,143,16,20,\"וְלָא קַבִּילוּ מִן משֶׁה וְשַׁיְירוּ דָתָן וַאֲבִירָם גּוּבְרַיָיא חַיָיבַיָא מִנֵיהּ עַד צַפְרָא וְאַרְחֵשׁ מוֹרְנִין וּסְרֵי וּרְגַז עֲלֵיהוֹן משֶׁה\",0,0],[4,143,16,21,\"וַהֲווֹ מְלַקְטִין יָתֵיהּ מִן עִדַן צַפְרָא עַד אַרְבַּע שָׁעִין דְּיוֹמָא אֵינַשׁ לְפוּם מֵיכְלֵיהּ וּמִן אַרְבַּע שָׁעִין וּלְהָאֵל שָׁחִין שִׁימְשָׁא עִילוֹי וַהֲוָה שַׁיִיח וּמִתְעַבֵיד מַבּוּעִין דְּמַיִין וְנַגְדִין עַד יַמָא רַבָּא וְאַתְיָין חֵיוַן דַּכְיַין וּבְעִירָן וְשַׁתְיַין מִינֵהּ וַהֲווֹ בְּנֵי יִשְרָאֵל צַדְיַין וְאָכְלִין יַתְהוֹן\",0,0],[4,143,16,22,\"וַהֲוָה בְּיוֹמָא שְׁתִיתָאָה לְקָטוּ לְחֵם בְּכֵפְלָא תְּרֵין עוּמְרִין לְבַר נַשׁ חַד וְאָתוֹי כָּל רַבְרְבָנֵי כְנִשְׁתָּא וְתַנּוּ לְמשֶׁה\",0,0],[4,143,16,23,\"וַאֲמַר לְהוֹן משֶׁה הוּא דְמַלֵּיל יְיָ עֲבַדְתּוּן שַׁבָּא שַׁבַּת קוּדְשָׁא קֳדָם יְיָ לִמְחַר יַת דְּאַתּוּן צְרִיכִין לְמֵיפָא מְחַר אֵיפוּ יוֹמָא דֵין וְיַת דְּאַתּוּן צְרִיכִין לִמְבַשְׁלָא מְחַר בְּשִׁילוּ יוֹמָא דֵין וְיַת כָּל מַה דְּמִשְׁתַּיַּיר מִן מַה דִּי תֵיכְלוּן יוֹמָא דֵין אַצְנִיעוּ יָתֵיהּ וִיהֵי נְטִיר עַד צַפְרָא\",0,0],[4,143,16,24,\"וְאַצְנָעוּ יָתֵיהּ עַד צַפְרָא הֵיכְמָא דְפַקֵּיד משֶׁה וְלָא סְרִי וְרִיחֲשָׁא לָא הֲוָת בֵּיהּ\",0,0],[4,143,16,25,\"וַאֲמַר משֶׁה אִכְלוּהוּ יוֹמָא דֵין אֲרוּם שַׁבְּתָא יוֹמָא דֵין קֳדָם יְיָ יוֹמָא דֵין לָא תִשְׁכְּחוּנֵיהּ בְּחַקְלָא\",0,0],[4,143,16,26,\"שִׁתָּא יוֹמִין תִּלְקְטוּנֵיהּ וּבְיוֹמָא שְׁבִיעָאָה דְהוּא שַׁבְּתָא לָא יְהֵי בֵיהּ מַנָּא נָחִית\",0,0],[4,143,16,27,\"וַהֲוָה בְּיוֹמָא שְׁבִיעָאָה נָפְקוּ מִן רַשִׁיעֵי עַמָּא לְמִילְקוֹט מַנָּא וְלָא אַשְׁכָּחוּ\",0,0],[4,143,16,28,\"וַאֲמַר יְיָ לְמשֶׁה עַד אֵימַת אַתּוּן מְסַרְבִין לְמִנְטוֹר פִּיקוּדַי וְאוֹרַיְיתָי\",0,0],[4,143,16,29,\"חָמוּן אֲרוּם יְיָ יְהַב לְכוֹן יַת שַׁבְּתָא בְּגִין כֵּן הוּא יָהִיב לְכוֹן בְּיוֹם שְׁתִיתָאָה לְחֵם לִתְּרֵין יוֹמִין שְׁרוֹן גְּבַר בְּאַתְרֵיהּ וְלָא תְטַלְטְלוּן מִדַּעַם מִרְשׁוּתָא לִרְשׁוּתָא בַּר מֵאַרְבָּעָה גַרְמִידֵי וְלָא יִפּוֹק אֵינַשׁ מֵאַתְרֵיהּ לְטַיְילָא לְבַר מִתְּרֵין אַלְפִין גַּרְמִידֵי בְּיוֹמָא שְׁבִיעָאָה\",0,0],[4,143,16,30,\"וְנָחוּ עַמָּא בְּיוֹמָא שְׁבִיעָאָה\",0,0],[4,143,16,31,\"וּקְרוֹן בֵּית יִשְרָאֵל יַת שְׁמֵיהּ מַנָּא וְהוּא כְּבַר זְרַע כּוּסְבַּר חֵיוַר וְטַעֲמֵיהּ כַּאֲשִׁישְׁיַין בִּדְבָשׁ\",0,0],[4,143,16,32,\"וַאֲמַר משֶׁה דֵּין פִּתְגָמָא דְפַקֵיד יְיָ לְאַצְנָעָא מְלֵי עוּמְרָא מִנֵּיהּ לְמַטָּרָא לְדָרֵיכוֹן מִן בִּגְלַל דְּיֶחְמוּן דָּרַיָא מְסַרְבַיָיא יַת לַחְמָא דְאוֹכְלִית יַתְכוֹן בְּמַדְבְּרָא בְּהַנְפָקוּתִי יַתְכוֹן מֵאַרְעָא דְמִצְרָיִם\",0,0],[4,143,16,33,\"וַאֲמַר משֶׁה לְאַהֲרן סַב צְלוּחִית דְּפָחַר חֲדָא וְהַב תַּמָּן מְלֵי עוּמְרָא מַנָא וְאַצְנַע יָתֵיהּ קֳדָם יְיָ לְמַטְרָא לְדָרֵיכוֹן\",0,0],[4,143,16,34,\"הֵיכְמָא דְּפַקֵּיד יְיָ יַת משֶׁה וְאַצְנְעֵיהּ אַהֲרן קֳדָם סַהֲדוּתָא לְמַטְרָא\",0,0],[4,143,16,35,\"וּבְנֵי יִשְרָאֵל אָכְלוּ יַת מַנָּא אַרְבְּעִין שְׁנִין בְּחַיּוֹהִי דְמשֶׁה עַד מֵיתֵיהוֹן לְאַרְעָא מֵיתִיבָא יַת מַנָּא אָכְלוּ אַרְבְּעִין יוֹמִין בָּתַר מוֹתֵיהּ עַד דְּעָבְרוּ יוּרְדְּנָא וְעָלוּ לִסְיָיפֵי אַרְעָא דִכְנָעַן\",0,0],[4,143,16,36,\"וְעִמְרָא חָד מִן עַשְרָא לִתְלַת סְאִין הוּא\",0,0],[4,143,17,1,\"וּנְטָלוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְרָאֵל מִמַּדְבְּרָא דְסִין לְמִטְלָנֵיהוֹן עַל מֵימְרָא דַיְיָ וּשְׁרוֹ בִּרְפִידִים אַתְרָא דְבַטִּילוּ אִידֵיהוֹן מִמִצְוָותָא דְאוֹרַיְתָא וְאִתְיַיבְּשׁוּ מַבּוּעַיָא וְלָא הֲוָה מוֹי לְמִשְׁתֵּי לְעַמָּא\",0,0],[4,143,17,2,\"וְנָצוּ רַשִׁיעֵי עַמָא עִם משֶׁה וְאָמָרוּ הַב לָן מוֹי וְנִשְׁתֵּי וַאֲמַר לְהוֹן משֶׁה מַה נָּצַן אַתּוּן עִמִּי וּמַה מְנַסֵן אַתּוּן קֳדָם יְיָ\",0,0],[4,143,17,3,\"וּצְחִי תַמָּן עַמָּא לְמוֹי וְאִתְרָעַם עַמָּא עַל משֶׁה וַאֲמַר לְמָא דְנַן אַסֵיקְתָּנָא מִמִּצְרַיִם לְקַטְלָא יָתָנָא וְיַת בְּנָנָא וְיַת גֵּיתָנָא בְּצָחוּתָא\",0,0],[4,143,17,4,\"וְצַלִּי משֶׁה קֳדָם יְיָ לְמֵימַר מַה אַעֲבֵיד לְעַמָּא הָדֵין תּוּב קָלִיל זְעֵיר וְהִינוּן רַגְמִין יָתִי\",0,0],[4,143,17,5,\"וַאֲמַר יְיָ לְמשֶׁה עִיבַּר קֳדָם עַמָּא וּדְבַר עִמָּךְ מִסָּבֵי יִשְרָאֵל וְחוּטְרָךְ דְּמָחִית בֵּיהּ יַת נַהֲרָא דְּבַר בִּידָךְ וְאִיזֵיל לָךְ מִן קֳדָם תּוּרְעֲמַתְהוֹן\",0,0],[4,143,17,6,\"הָאֲנָא קָאִים קֳדָמָךְ תַּמָּן בְּאַתְרָא דְתֶחֱמֵי רוֹשֶׁם רִיגְלָא בְּחוֹרֵב וְתִמְחֵי בֵיהּ בְּטִינָר בְּחוּטְרָךְ וְיִפְקוּן מִינֵהּ מוֹי לְמִשְׁתֵּי וְיִשְׁתּוּן עַמָּא וְעָבַד הֵיכְדֵין משֶׁה קֳדָם סָבֵי יִשְרָאֵל\",0,0],[4,143,17,7,\"וּקְרָא שְׁמָא דְאַתְרָא הַהוּא נִסְיוֹנָא וּמַצּוּתָא בְּגִין דְּנָצוּ בְּנֵי יִשְרָאֵל עִם משֶׁה וּבְגִין דְּנַסְיַין קֳדָם יְיָ לְמֵימַר הַאִין קוּשְׁטָא אִיקַר שְׁכִינְתָּא דַיְיָ שַׁרְיָא בֵּינָנָא אִין לָא\",0,0],[4,143,17,8,\"וְאָתָא עֲמָלֵק מֵאַרַע דְּרוֹמָא וְשַׁוֵור בְּלֵילְיָא הַהוּא אֶלֶף וְשִׁית מְאָה מִילִין וּמִן בִּגְלַל מַצּוּתָא דַּהֲוָה בֵינֵי עֵשָו וּבֵינֵי יַעֲקב אָתָא וְאַגַּח קְרָבָא עִם יִשְרָאֵל בִּרְפִידִים וַהֲוָה נְסִיב וְקָטִיל גּוּבְרִין מִדְּבֵית דָּן דְּלָא הֲוָה עֲנָנָא מְקַבִּיל יַתְהוֹן מִן בִּגְלַל פּוּלְחָנָא נוּכְרָאָה דִי בֵינֵיהוֹן\",0,0],[4,143,17,9,\"וַאֲמַר משֶׁה לִיהוֹשֻׁעַ בְּחַר לָנָא גּוּבְרִין גִּבָּרִין וְתַקִּיפִין בְּפִקּוּדַיָא וְנִצְחָנֵי קְרָבָא וּפוּק מִתְּחוֹת עֲנָנֵי יְקָרָא וּסְדַר סִדְרֵי קְרָבָא לִקְבֵיל מַשִׁירְיַין עֲמָלֵק מְחַר אֲנָא קָאִים בְּצוֹמָא מֵעַתַּד בְּזַכְוָות אַבְהָתָא רֵישֵׁי עַמָּא וְזַכְוַות אִימְהָתָא דִמְתִילַן לִגְלִימָתָא וְחוּטְרָא דְאִתְעֲבִידוּ בֵיהּ נִיסִין מִן קֳדָם יְיָ בִּידִי\",0,0],[4,143,17,10,\"וְעָבַד יְהוֹשֻׁעַ הֵיכְמָא דְאָמַר לֵיהּ משֶׁה לְאַגָחָא קְרָבָא בַּעֲמָלֵק וּמשֶׁה אַהֲרן וְחוּר סְלִיקוּ לְרֵישׁ רָמָתָא\",0,0],[4,143,17,11,\"וַהֲוָה כַד זְקֵיף משֶׁה יְדוֹי בִּצְלוֹי וּמִתְגַּבְּרִין דְּבֵית יִשְרָאֵל וְכַד הֲוָה מָנַח יְדוֹי מִן לְמַצְלַיָיא וּמִתְגַּבְּרִין דְּבֵית עֲמָלֵק\",0,0],[4,143,17,12,\"וִידוֹי דְמשֶׁה הֲווֹ יַקְרִין מִן בִּגְלַל דְּעִכַּב קְרָבָא לִמְחַר וְלָא אִזְדְּרַז בְּיוֹמָא הַהוּא לְפוּרְקָנָא דְיִשְרָאֵל וְלָא הֲוָה יָכִיל לְמִיזְקַפְהוֹן בִּצְלוֹי וּמִן דַּהֲוָה צָבֵי לְסִגּוּפֵי נַפְשֵׁיהּ נְסִיבוּ אַבְנָא וְשַׁוִּיוּ תְּחוֹתוֹי וִיתֵיב עִילַוָּהּ וְאַהֲרן וְחוּר מְסַעֲדִין לִידוֹי מִיכָּא חָד וּמִכָּא חָד וְהַוָּאָה יְדוֹי פְּרִיסַן בְּהֵימְנוּתָא בִּצְלוֹ וְצוֹמָא עַד מִטְמוֹעַ שִׁמְשָׁא\",0,0],[4,143,17,13,\"וּתְבַר יְהוֹשֻׁעַ יַת עֲמָלֵק דְּקָטַע רֵישֵׁי גִיבָּרַיָא דְּעַמֵּיהּ עַל פּוּם מֵימְרָא דַיְיָ בִּקְטִילַת סַיְיפָא\",0,0],[4,143,17,14,\"וַאֲמַר יְיָ לְמשֶׁה כְּתוֹב דָּא דוּכְרָנָא בְּסֵפֶר סָבַיָיא דְמִלְקַדְמִין וְשַׁוִּי פִּתְגָמַיָא הָאִינוּן בְּמִשְׁמָעֵיהּ דִּיהוֹשֻׁעַ אֲרוּם מִימְחָא אֶמְחֵי יַת דּוּכְרָן עֲמָלֵק מִתְּחוֹת שְׁמַיָא\",0,0],[4,143,17,15,\"וּבְנָא משֶׁה מַדְבְּחָה וּקְרָא שְׁמֵיהּ מֵימְרָא דַיְיָ דֵּין נִיסָא דִילִי דְנִיסָא דְעָבַר אַתְרָא בְּגִינִי הוּא\",0,0],[4,143,17,16,\"וַאֲמַר אֲרוּם קַיֵּים מֵימְרָא דַיְיָ בְּכוּרְסֵיהּ יְקָרֵיהּ דְּהוּא בְּמֵימְרֵיהּ יַגִּיחַ קְרָבָא בִּדְבֵית עֲמָלֵק וִישֵׁיצֵי יַתְהוֹן לִתְלָתֵי דָרַיָא מִדָּרָא דְעַלְמָא דֵין וּמִדָּרָא דִמְשִׁיחָא וּמִדָּרָא דְעַלְמָא דְאָתֵי\",0,0],[4,143,18,1,\"וישמע וּשְׁמַע יִתְרוֹ אוֹנוֹס מִדְיָן חָמוּי דְמשֶׁה יַת כָּל מַאן דְּעָבִיד יְיָ לְמשֶׁה וּלְיִשְרָאֵל עַמֵּיהּ אֲרוּם אַפֵּיק יְיָ יַת יִשְרָאֵל מִמִּצְרָיִם\",0,0],[4,143,18,2,\"וּדְבַר יִתְרוֹ חָמוּי דְמשֶׁה יַת צִפּוֹרָה אִנְתְּתֵיהּ דְּמשֶׁה בָּתַר דְּשַׁלְּחָהּ מִלְּוָתֵיהּ כַּד הֲוָה אָזִיל לְמִצְרָיִם\",0,0],[4,143,18,3,\"וְיַת תְּרֵין בְּנָהָא דְּשׁוּם חָד גֵּרְשׁוֹם אֲרוּם אָמַר דַּיָּיר הֲוֵיתִי בְּאַרְעָא נוּכְרָאָה דְלָא דִידִי הוּא\",0,0],[4,143,18,4,\"וְשׁוּם חָד אֱלִיעֶזֶר אֲרוּם אֱלָהָא דְאַבָּא הֲוָה בְּסַעֲדֵי וְשֵׁיזְבַנִי מֵחַרְבָּא דְפַרְעה\",0,0],[4,143,18,5,\"וְאָתָא יִתְרוֹ חָמוֹי דְמשֶׁה וּבְנוֹי דְמשֶׁה וְאִנְתְּתֵיהּ לְוַת משֶׁה לְמַדְבְּרָא דְהוּא שָׁרֵי תַּמָּן סְמִיךְ לְטַוְורָא דְאִתְגְּלֵי עֲלוֹי יְקָרָא דַיְיָ לְמשֶׁה מִן שֵׁירוּיָא\",0,0],[4,143,18,6,\"וַאֲמַר לְמשֶׁה אָנָא חָמוּךְ יִתְרוֹ אָתֵי לְוָותָךְ לְאִתְגַיְירָא וְאִין לָא תְקַבֵּל יָתִי בְּגִינִי תְּקַבֵּיל בְּגִין אִנְתְּתָךְ וּתְרֵין בְּנָהָא דְעִמָהּ\",0,0],[4,143,18,7,\"וּנְפַק משֶׁה מִתְּחוֹת עֲנָנָא יְקָרָא לִקְדָמוּת חָמוֹי וּסְגִיד וּנְשֵׁיק לֵיהּ וְגַיְירֵיהּ וְשַׁיְילוּ גְּבַר לְחַבְרֵיהּ לִשְׁלָם וְאָתוּ לְמַשְׁכַּן בֵּית אוּלְפָנָא\",0,0],[4,143,18,8,\"וְתַנִי משֶׁה לְחָמוֹי יַת כָּל מַה דְּעָבַד יְיָ לְפַרְעה וּלְמִצְרָאֵי עַל עֵיסַק יִשְרָאֵל יַת כָּל עַקְתָא דְאַשְׁכְּחַתְנוּן בְּאָרְחָא עַל יַמָא דְסוּף וּבְמָרָה וּבִרְפִידִים וְהֵיךְ אַגַח עִמְהוֹן עֲמָלֵק וְשֵׁיזְבִינוּן יְיָ\",0,0],[4,143,18,9,\"וּבְדַח יִתְרוֹ עַל כָּל טַבְתָא דְעָבַד יְיָ לְיִשְרָאֵל דִּיהַב לְהוֹן מַנָא וּבֵירָא וְדִי שֵׁיזְבִינִין מִן יְדָא דְמִצְרָאֵי\",0,0],[4,143,18,10,\"וַאֲמַר יִתְרוֹ בְּרִיךְ שְׁמָא דַיְיָ דְּשֵׁזִיב יַתְכוֹן מִן יְדָא דְמִצְרָאֵי וּמִן יְדָא דְפַרְעה דְּשֵׁזִיב יַת עַמָּא מִתְּחוֹת מַרְוַת מִצְרָאֵי\",0,0],[4,143,18,11,\"כְּדוֹן חַכִּימַת אֲרוּם תַּקִיף הוּא יְיָ עַל כָּל אֱלָהַיָא אֲרוּם בְּפִתְגָמָא דְאַרְשִׁיעוּ מִצְרָאֵי לְמֵידַן יַת יִשְרָאֵל בְּמַיָא עֲלֵיהוֹן הָדַר דִּינָא לְאִיתְדָנָא בְּמַיָא\",0,0],[4,143,18,12,\"וּנְסַב יִתְרוֹ עַלְוָון וְנִכְסַת קוּדְשִׁין קֳדָם יְיָ וְאָתָא אַהֲרן וְכָל סָבֵי יִשְרָאֵל לְמֵיכוֹל לַחֲמָא עִם חָמוֹי דְמשֶׁה קֳדָם יְיָ וּמשֶׁה הֲוָה קָאִי וּמְשַׁמֵּשׁ קֳדָמֵיהוֹן\",0,0],[4,143,18,13,\"וַהֲוָה בְּיוֹמָא דְבָתַר יוֹמָא דְכִפּוּרֵי וִיתֵיב משֶׁה לְמֵידַן יַת עַמָּא וְקָם עַמָּא קֳדָם משֶׁה מִן צַפְרָא עַד רַמְשָׁא\",0,0],[4,143,18,14,\"וַחֲמָא חָמוֹי דְמשֶׁה יַת כָּל דְּהוּא טָרַח וְעָבֵיד לְעַמֵּיהּ וַאֲמַר מַה פִּתְגָמָא הָדֵין דְּאַנְתְּ עָבֵיד לְעַמָּא מַה דֵּין אַנְתְּ יָתֵב לְבִלְחוֹדָךְ לְמִידוּן וְכָל עַמָּא קַיְימִין קֳדָמָךְ מִן צַפְרָא עַד רַמְשָׁא\",0,0],[4,143,18,15,\"וַאֲמַר משֶׁה לְחָמוֹי אֲרוּם אַתְיָין לְוָותִי עַמָא לְמִתְבּוֹעַ אוּלְפַן מִן קֳדָם יְיָ\",0,0],[4,143,18,16,\"אֲרוּם יְהֵי לְהוֹן דִּינָא אָתָאָן לְוָותִי וְדַיֵּינָא בֵּין גַּבְרָא וּבֵין חַבְרֵיהּ וּמְהוֹדַעְנָא לְהוֹן יַת קְיָמַיָא דַיְיָ וְיַת אוֹרַיְיתֵיהּ\",0,0],[4,143,18,17,\"וַאֲמַר חָמוּי דְמשֶׁה לֵיהּ לָא תַקִין פִּתְגָמָא דְאַנְתְּ עָבִיד\",0,0],[4,143,18,18,\"מִיתַר תִּינְתַר אוּף אַנְתְּ אוּף אַהֲרן וּבְנוֹי וְסָבַיָא דְעִמָּךְ אֲרוּם יַקִּיר מִינָךְ פִּתְגָּמָא לָא תֵיכוֹל לְמֶעְבְּדֵיהּ בִּלְחוֹדָךְ\",0,0],[4,143,18,19,\"כְּדוֹן קַבֵּיל מִינִי אִימְלְכִינָךְ וִיהֵי מֵימְרָא דַיְיָ בְּסַעֲדָךְ הֲוֵי אַנְתְּ לְעַמָּא תְּבַע אוּלְפַן מִן קֳדָם יְיָ וְתַיְתֵי אַנְתְּ יַת פִּתְגָמָא דִילְהוֹן קֳדָם יְיָ\",0,0],[4,143,18,20,\"וְתַזְהַר יַתְהוֹן יַת קְיָימַיָא וְיַת אוֹרַיְיתָא וּתְהוֹדַע לְהוֹן יַת צְלוֹתָא דְיֵיצְלוּן בְּבֵית כְּנִשְׁתְּהוֹן וְיַת אוֹרְחָא דְּיַבְקְרוּן לְמָרִיעִין וּדְיַהֲכוּן לְמִיקְבּוֹר מֵתַיָא וּלְמִגְמוֹל בָּהּ חִיסְדָא וְיַת עוּבְדָא וְשׁוּרַת דִּינָא וּדְיַעַבְדוּן מִלְגַו לְשׁוּרָתָא לְרַשִׁיעַיָין\",0,0],[4,143,18,21,\"וְאַנְתְּ בְּרוֹר מִכָּל עַמָא גִיבְרֵי חֵילָא דַחֲלַיָא דַיְיָ גּוּבְרִין דִּקְשׁוֹט דְּסָנַן לְקַבְּלָא מָמוֹן שִׁיקְרָא וּתְמַנֵי עֲלֵיהוֹן רַבָּנֵי אַלְפִין רַבָּנֵי מַאֲוָותָא רַבָּנֵי חוּמְשִׁין רַבָּנֵי עִשּׂוּרְיָיתָא\",0,0],[4,143,18,22,\"וִידִינוּן יַת עַמָּא בְּכָל עִידַן וִיהֵי כָּל פִּתְגַּם רַב יֵיתוּן לְוָותָךְ וְכָל פִּתְגַּם קָלִיל יִדוֹנוּן הִינוּן וִיקִילוּן מִן מְטוֹל דְּעָלָךְ וִיסוֹבְרוּן עִמָךְ\",0,0],[4,143,18,23,\"אִין יַת פִּתְגָמָא הָדֵין תַּעֲבֵיד דְּתֵיהֵי פָנֵי מִן דִּינָא וְיַפְקְדִינָךְ יְיָ פְּקוּדַיָא וְתֵיכוּל לְמֵיקָם לְמִשְׁמָעֵהוֹן וְאוּף אַהֲרן וּבְנוֹי וְכָל סָבַיָא דְעַמָא הָדֵין עַל אֲתַר בֵּי דִינְהוֹן יֵיתוּן בִּשְׁלָם\",0,0],[4,143,18,24,\"וְקַבֵּל משֶׁה לְמֵימָר חָמוֹי וְעָבַד כָּל דְּאָמַר\",0,0],[4,143,18,25,\"וּבְחַר משֶׁה גִיבָּרֵי חֵילָא מִכָּל יִשְרָאֵל וּמַנֵי יַתְהוֹן רֵישִׁין עַל עַמָא רַבָּנֵי אַלְפִין שִׁית מְאָה רַבָּנֵי מַאֲוָותָא שִׁית אַלְפִין רַבָּנֵי חוּמְשִׁין תְּרֵיסַר אַלְפִין וְרַבָּנֵי עִישׁוֹרְיָיתָא שִׁית רִבְוָון\",0,0],[4,143,18,26,\"וַהֲווֹן דַּיְינִין יַת עַמָא בְּכָל עִידַן יַת פִּתְגַם קְשֵׁי מַיְיתוּן לְוַת משֶׁה וְכָל פִּתְגַם קָלִיל דַּיְינִין הִינוּן\",0,0],[4,143,18,27,\"וּפְטַר משֶׁה יַת חָמוֹי וְאָזַל לֵיהּ לְגַיְירָא כָּל בְּנֵי אַרְעֵיהּ\",0,0],[4,143,19,1,\"בְּיַרְחָא תְּלִיתָאָה לְאַפְקוּת בְּנֵי יִשְרָאֵל מֵאַרְעָא דְמִצְרַיִם בְּיוֹמָא הָדֵין בְּחַד לְיַרְחָא אָתוּ לְמַדְבְּרָא דְסִינָי\",0,0],[4,143,19,2,\"וּנְטָלוּ מֵרְפִידִים וְאָתוֹ לְמַדְבְּרָא דְסִינַי וּשְׁרוֹ בְּמַדְבְּרָא וּשְׁרָא תַּמָן יִשְרָאֵל בְּלֵב מְיַיחֵד כָּל קְבֵיל טַוְורָא\",0,0],[4,143,19,3,\"וּמשֶׁה סְלִיק בְּיוֹמָא תִנְיָנָא לְרֵישׁ טַוְורָא וּקְרָא לֵיהּ יְיָ מִן טַוְורָא לְמֵימָר כִּדְנָא תֵימַר לִנְשַׁיָא דְבֵית יַעֲקב וְתַתְנֵי לְבֵית יִשְרָאֵל\",0,0],[4,143,19,4,\"אַתּוּן חֲמִיתוּן מַה דִּי עֲבָדִית לְמִצְרָאֵי וּטְעָנִית יַתְכוֹן עַל עֲנָנִין הֵי כְּעַל גַּדְפֵי נִשְׁרִין מִן פִּילוּסִין וְאוֹבֵילִית יַתְכוֹן לְאַתַר בֵּית מוּקְדָּשָׁא לְמֶעֱבַד תַּמָּן פִּסְחָא וּבְהַהוּא לֵילְיָא אֲתֵיבִית יַתְכוֹן לְפִילוּסִין וּמִתַּמָּן קְרִיבִית יַתְכוֹן לְאוּלְפַן אוֹרַיְיתִי\",0,0],[4,143,19,5,\"וּכְדוּן אִין קַבָּלָא תְּקַבְּלוּן לְמֵימְרִי וְתִנְטְרוּן יַת קְיָימַי וּתְהוֹן קֳדָמַי חֲבִיבִין מִכָּל עַמְמַיָא דְעַל אַפֵּי אַרְעָא\",0,0],[4,143,19,6,\"וְאַתּוּן תְּהוֹן קֳדָמַי מַלְכִין קְטִירֵי כְּלִילָא וְכַהֲנִין מְשַׁמְשִׁין וְעַם קַדִּישׁ אִלֵין פִּתְגָמַיָא דִּתְמַלֵּיל עִם בְּנֵי יִשְרָאֵל\",0,0],[4,143,19,7,\"וְאָתָא משֶׁה בְּיוֹמָא הַהוּא וּקְרָא לְסָבֵי עַמָא וּסְדַר קֳדָמֵיהוֹן יַת כָּל פִּתְגָמַיָא הָאִלֵּין דְּפַקְדֵיהּ יְיָ\",0,0],[4,143,19,8,\"וְאָתִיבוּ כָּל עַמָּא כַּחֲדָא וַאֲמָרוּ כָּל דְּמַלֵּיל יְיָ נַעֲבֵיד וְאָתֵיב משֶׁה יַת פִּתְגָמֵי עַמָּא קֳדָם יְיָ\",0,0],[4,143,19,9,\"וַאֲמַר יְיָ לְמשֶׁה בְּיוֹמָא תְּלִיתָאָה הָא אֲנָא מִתְגְּלֵי עֲלָךְ בְּעֵיבָא דַּעֲנַן יְקָרָא מִן בִּגְלַל דְּיִשְׁמְעוּן עַמָּא בְּמַלָּלוּתִי עִמָּךְ וְאוּף בָּךְ יְהֵימְנוּן לְעָלַם וְתַנִי משֶׁה יַת פִּתְגָּמֵי עַמָּא קֳדָם יְיָ\",0,0],[4,143,19,10,\"וַאֲמַר יְיָ לְמשֶׁה בְּיוֹמָא רְבִיעַאָה אִיזֵיל לְוַת עַמָּא וְתִזְמְנִינוּן יוֹמָא דֵין וְיוֹם מָחְרָא וִיחַוְורוּן לְבוּשֵׁיהוֹן\",0,0],[4,143,19,11,\"וִיהוֹן זְמִינִין לְיוֹמָא תְּלִיתָאָה אֲרוּם בְּיוֹמָא תְּלִיתָאָה יִתְגְּלֵי יְיָ לְעֵינֵי כָל עַמָּא עַל טוּרָא דְסִינָי\",0,0],[4,143,19,12,\"וְתַתְחֵם יַת עַמָּא וִיקוּמוּן חֲזוֹר חֲזוֹר לְטוּרָא לְמֵימָר הֲווֹ זְהִירִין מִלְמֵיסַק בְּהַר וּלְמִקְרַב בְּסַיְיפֵיהּ כָּל דְּיִקְרַב בְּטַוְורָא אִתְקְטָלָא יִתְקְטֵיל\",0,0],[4,143,19,13,\"לָא תִקְרַב בֵּיהּ יְדָא אֲרוּם יִתְרְגָמָא יִתְרְגֵם בְּאַבְנָא בַרְדָא אוֹ גִירִין דְּאֵשָׁא יִדְרְקוּן בֵּיהּ אִין בְּעִירָא אִין אֵינָשָׁא לָא יִתְקַיֵּים בְּרַם בְּמֵיגַד קַל שׁוֹפְרָא הִינוּן מַרְשַׁן לְמֵיסַק בְּטַוְורָא\",0,0],[4,143,19,14,\"וּנְחַת משֶׁה בְּיוֹמָא הַהוּא לְוַת עַמָּא וְזַמִּין יַת עַמָּא וְחַוָּרוּ לְבוּשֵׁיהוֹן\",0,0],[4,143,19,15,\"וַאֲמַר לְעַמָּא הֲווֹ זְמִינִין לִתְלָתֵי יוֹמִין לָא תִקְרְבוּן לְתַשְׁמִישׁ דְעָרִיס\",0,0],[4,143,19,16,\"וַהֲוָה בְּיוֹמָא תְּלִיתָאָה בְּשִׁיתָּא בְּיַרְחָא בְּעִידוֹנֵי צַפְרָא וַהֲוָה קָלִין דִּרְעֵים וּבְרָקִים וַעֲנָנָא תַּקִּיף קְטִיר עַל טַוְורָא וְקַל שׁוֹפָרָא תַקִּיף לַחֲדָא וְזַע כָּל עַמָּא דִי בְּמַשְׁרִיתָא\",0,0],[4,143,19,17,\"וְאַנְפֵּיק משֶׁה יַת עַמָּא לִקְדָמוּת שְׁכִינְתָּא דַיְיָ מִן מַשְׁרִיתָא וּמִן יַד תָּלִישׁ מָארֵי עַלְמָא יַת טַוְורָא וְזַקְפֵיהּ בְּאַוִירָא וַהֲוָה זַיֵיג הֵי כְּאִסְפַּקְלַרְיָא וְאִתְעַתָּדוּ תְּחוֹתֵי טַוְורָא\",0,0],[4,143,19,18,\"וְטַוְורָא דְסִינַי תָנֵין כּוּלֵיהּ מִן בִּגְלַל דְּאַרְכִין לֵיהּ שְׁמַיָא וְאִתְגְּלֵי עֲלוֹי בְּאֵישָׁא מְצַלְהֲבָא וְסָלֵיק קוּטְרֵיהּ הֵי כְקוּטְרָא דְאַתּוּנָא וְזַע כָּל טַוְורָא לַחֲדָא\",0,0],[4,143,19,19,\"וְהַוָּה קַל שׁוֹפָרָא אָזִיל וְתַקִּיף לַחֲדָא משֶׁה הֲוָה מְמַלֵּיל וּמִן קֳדָם יְיָ הֲוָה מִתְעַנֵי בְקַל נָעִים וּמְשַׁבַּח וּנְעִימָתָא מַלְיָא\",0,0],[4,143,19,20,\"וְאִתְגְּלֵי יְיָ עַל טַוְורָא דְסִינַי עַל רֵישׁ טַוְורָא וּקְרָא יְיָ לְמשֶׁה לְרֵישׁ טַוְורָא וּסְלֵיק משֶׁה\",0,0],[4,143,19,21,\"וַאֲמַר יְיָ לְמשֶׁה חוּת אַסְהִיד בְּעַמָּא דִּלְמָא יְכַוְּונוּן קֳדָם יְיָ לְאִסְתַּכְּלָא וְיַפִּיל מִנְהוֹן רַב דִּבְהוֹן\",0,0],[4,143,19,22,\"וְאוּף כַּהֲנַיָא דִּקְרִיבִין לְשַׁמְשָׁא קֳדָם יְיָ יִתְקַדְּשׁוּן דִּלְמָא יִקְטוֹל בְּהוֹן יְיָ\",0,0],[4,143,19,23,\"וַאֲמַר משֶׁה קֳדָם יְיָ לָא יִכְלוּן עַמָּא לְמֵיסַק לְטַוְורָא דְסִינַי אֲרוּם אַנְתְּ אַסְהֵידְתָּא בָּנָא לְמֵימָר תָּחִים יַת טַוְורָא וְקַדְשׁוֹהִי\",0,0],[4,143,19,24,\"וַאֲמַר לֵיהּ יְיָ אִיזֵל חוֹת וְתִיסַק אַנְתְּ וְאַהֲרן עִמָּךְ וְכַהֲנַיָא וְעַמָּא לָא יְכַוְונוּן לְמִיסוּק לְמִסְתַּכְּלָא קֳדָם יְיָ דִּילְמָא יִקְטוֹל בְּהוֹן\",0,0],[4,143,19,25,\"וּנְחַת משֶׁה מִן טַוְורָא לְוַת עַמָּא וַאֲמַר לְהוֹן קְרִיבוּ קַבִּילוּ אוֹרַיְיתָא עִם עֲשַרְתֵּי דִבְּרַיָא\",0,0],[4,143,20,1,\"וּמַלֵּיל יְיָ יַת כָּל דִּבְּרַיָא הָאִילֵין לְמֵימָר\",0,0],[4,143,20,2,\"דְּבִירָא קַדְמָאָה כַּד הֲוָה נָפִיק מִן פּוּם קוּדְשָׁא יְהֵי שְׁמֵיהּ מְבָרֵךְ הֵי כְזִיקִין וְהֵי כְבַרְקִין וְהֵי כְשַׁלְהוֹבְיָין לַמְפַּד דִּינוּר מִן יְמִנֵיהּ וְלַמְפַּד דְּאֵישָׁא מִן שְמָאלֵיהּ פָּרַח וְטַיֵּיס בְּאַוִיר שְׁמַיָא וְחָזַר וּמִתְחַמֵּי עַל מַשִּׁירְיַתְהוֹן דְּיִשְרָאֵל וְחָזַר וּמִתְחֲקֵק עַל לוּחֵי קְיָימָא דַהֲווֹן יְהִיבִין בְּכַף יְדוֹי דְמשֶׁה וּמִתְהֲפִיךְ בְּהוֹן מִן סְטַר לִסְטָר וּבְכֵן צָוַוח וְאָמַר עַמִּי בְּנֵי יִשְרָאֵל אֲנָא הוּא אֱלָהָכוֹן דִּי פְּרָקִית וְאַפֵּיקִית יַתְכוֹן פְּרִיקִין מִן אַרְעָא דְּמִצְרָאֵי מִבֵּית שִׁעְבוּד עַבְדַיָּא\",0,0],[4,143,20,3,\"דְּבִירָא תִּנְיָנָא כַּד הֲוָה נָפִיק מִן פּוּם קוּדְשָׁא יְהֵי שְׁמֵיהּ מְבָרֵךְ הֵי כְּזִיקִין וְהֵי כְבַרְקִין וְהֵי כְּשַׁלְהוֹבִין דִּינוּר לַמְפַּד דִּינוּר מִן יְמִינֵיהּ וְלַמְפַּד דְּאֵישָׁא מִן שְמָאלֵיהּ פָּרַח וְטַיֵּיס בְּאַוִיר שְׁמַיָא חָזַר וּמִתְחַמֵּי עַל מַשִׁירְיַתְהוֹן דְּיִשְרָאֵל וְחָזַר וּמִתְחַקֵּק עַל לוּחֵי קְיָימָא וּמִתְהַפִּיךְ בְּהוֹן מִן סְטַר לִסְטַר וּבְכֵן הֲוָה צָוַוח וְאָמַר עַמִּי בֵּית יִשְרָאֵל לָא יֶהֱוֵי לָךְ אֱלָהָא אוֹחֲרָן בַּר מִינִי\",0,0],[4,143,20,4,\"לָא תַעַבְדוּן לְכוֹן צְלַם וְצוּרָא וְכָל דְּמוֹי דְּבִשְׁמַיָא מִלְּעֵיל וְדִי בְאַרְעָא מִלְּרַע וְדִי בְמַיָא מִלְּרַע לְאַרְעָא\",0,0],[4,143,20,5,\"לָא תִסְגְּדוּן לְהוֹן וְלָא תִפְלְחוּן קֳדָמֵיהוֹן אֲרוּם אֲנָא יְיָ אֱלָהָכוֹן אֱלָהּ קַנָאַן וּפוּרְעַן וּמִתְפְּרַע בְּקִינָאָה מַדְכַּר חוֹבֵי אַבְהַת רַשִׁיעַן עַל בְּנִין מְרָדִין עַל דַּר תְּלִיתָאֵי וְעַל דַּר רְבִיעָאֵי לְשׁוֹנְאָי\",0,0],[4,143,20,6,\"וּנְטִיר חֶסֶד וְטִיבוּ לְאַלְפִין דָרִין לְרַחֲמַי צַדִּיקַיָא וּלְנַטְרֵי פִּיקוּדָי וְאוֹרַיְיתָי\",0,0],[4,143,20,7,\"עַמִּי בֵּית יִשְרָאֵל לָא יִשְׁתְּבַּע חַד מִנְכוֹן בְּשׁוּם מֵימְרָא דַיְיָ אֱלָהָכוֹן עַל מַגָּן אֲרוּם לָא מִזַכֵּי יְיָ בְּיוֹם דִּינָא רַבָּא יַת כָּל מַאן דְּמִשְׁתְּבַע בִּשְׁמֵיהּ עַל מַגָּן\",0,0],[4,143,20,8,\"עַמִּי בֵּית יִשְרָאֵל הֲווֹן דְּכִירִין יוֹמָא דְשַׁבַּתָּא לְמַקְדְּשָׁא יָתֵיהּ\",0,0],[4,143,20,9,\"שִׁיתָּא יוֹמִין תִּפְלְחוּן וְתַעַבְדוּן כָּל עֲבִדְתֵּיכוֹן\",0,0],[4,143,20,10,\"וְיוֹמָא שְׁבִיעָאָה שַׁבָּת וְנַיַּיח קֳדָם יְיָ אֱלָהָכוֹן לָא תַעְבְדוּן כָּל עִבִידְתָּא אַתּוּן וּבְנֵיכוֹן וּבְנָתֵיכוֹן וְעַבְדֵיכוֹן וְאַמְהוֹתֵיכוֹן וְגִיּוֹרֵיכוֹן בְּקִירְוֵיכוֹן\",0,0],[4,143,20,11,\"אֲרוּם בְּשִׁתָּא יוֹמִין בָּרָא יְיָ יַת שְׁמַיָא וְיַת אַרְעָא יַת יַמָא וְיַת כָּל מַה דְּאִית בְּהוֹן וְנַח בְּיוֹמָא שְׁבִיעָאָה בְּגִין כֵּן בְּרִיךְ יְיָ יַת יוֹמָא דְשַׁבְּתָא וְקַדִּישׁ יָתֵיהּ\",0,0],[4,143,20,12,\"עַמִּי בֵּית יִשְרָאֵל הֲווֹ זְהִירִין גְּבַר בִּיקָרָא דְאָבוּהִי וּבִיקָרָא דְאִמֵיהּ מִן בִּגְלַל דְּיִסְגוּן יוֹמֵיכוֹן עַל אַרְעָא דַיְיָ אֱלָהָכוֹן יָהִיב לְכוֹן\",0,0],[4,143,20,13,\"עַמִּי בְּנֵי יִשְרָאֵל לָא תֶהֱווּן קְטוֹלִין לָא חַבְרִין וְלָא שׁוּתְּפִין עִם קְטוֹלִין וְלָא יִתְחָמֵי בִּכְנִשְׁתְּהוֹן דְּיִשְרָאֵל עִם קְטוֹלִין וְלָא יְקוּמוּן בְּנֵיכוֹן מִן בַּתְרֵיכוֹן וְיִלְפוּן לְחוֹד הִינוּן לְמֶהֱוֵי עִם קְטוֹלִין אֲרוּם בְּחוֹבֵי קְטוֹלַיָא חַרְבָּא נָפִיק עַל עַלְמָא: לא תנאף עַמִּי בְּנֵי יִשְרָאֵל לָא תֶהֱווּן גִּיּוּרִין לָא חַבְרִין וְלָא שׁוּתָּפִין עִם גִּיּוּרִין וְלָא יִתְחָמֵי בִּכְנִשְׁתְּהוֹן דְּיִשְרָאֵל עִם גִּיּוּרִין דְּלָא יְקוּמוּן בְּנֵיכוֹן מִן בַּתְרֵיכוֹן וְיִלְפוּן לְחוֹד הִינוּן לְמֶהֱוֵי עִם גִּיּוּרִין אֲרוּם בְּחוֹבֵי גִיּוּרָא מוֹתָא נָפִיק עַל עַלְמָא: לא תגנוב עַמִּי בְּנֵי יִשְרָאֵל לָא תֶהֱווּן גַּנָּבִין לָא חַבְרִין וְלָא שׁוּתָּפִין עִם גַּנָּבִין וְלָא יִתְחָמֵי בִּכְנִשְׁתְּהוֹן דְּיִשְרָאֵל עִם גַּנָּבִין דְּלָא יְקוּמוּן בְּנֵיכוֹן מִן בַּתְרֵיכוֹן וְיִלְפוּן לְחוֹד הִינוּן לְמֶהֱוֵי עִם גַּנָּבִין אֲרוּם בְּחוֹבֵי גַנָבַיָא כַּפְנָא נָפִיק עַל עַלְמָא: לא תענה עַמִּי בְּנֵי יִשְרָאֵל לָא תֶהֱווּן מְסַהֲדִין בְּחַבְרֵיכוֹן סַהֲדֵי שִׁיקְרָא לָא חַבְרִין וְלָא שׁוּתָּפִין עִם מְסַהְדִין סַהֲדֵי שִׁקְרָא וְלָא יִתְחָמֵי בִּכְנִשְׁתְּהוֹן דְּיִשְרָאֵל עִם מְסַהֲדִין סַהֲדֵי שִׁיקְרָא דְלָא יְקוּמוּן בְּנֵיכוֹן בַּתְרֵיכוֹן וְיִלְפוּן לְחוֹד הִינוּן לְמֶהֱוֵי עִם מְסַהֲדִין סַהֲדֵי שִׁיקְרָא אֲרוּם בְּחוֹבֵי סַהֲדֵי שִׁיקְרָא עֲנָנָן סַלְקִין וּמִטְרָא לָא נָחִית וּבְצוֹרָתָא אַתְיָא עַל עַלְמָא\",0,0],[4,143,20,14,\"עַמִּי בְּנֵי יִשְרָאֵל לָא תֶהֱווּן חֲמִידִין לָא חַבְרִין וְלָא שׁוּתָּפִין עִם חֲמִידִין וְלָא יִתְחֲמוּן בִּכְנִשְׁתְּהוֹן דְּיִשְרָאֵל עִם חֲמוּדִין דְּלָא יְקוּמוּן בְּנֵיכוֹן מִן בַּתְרֵיכוֹן וְיִלְפוּן לְחוֹד הִינוּן לְמֶהֱוֵי עִם חֲמוּדִין וְלָא יַחְמִיד חַד מִנְכוֹן יַת אִנְתְּתֵיהּ דְּחַבְרֵיהּ וְלָא לְעַבְדֵיהּ וְלָא לְאַמְתֵיהּ וְלָא לְתוֹרֵיהּ וְלָא לְחַמְרֵיהּ וְלָא לְכָל מַאן דְּאִית לְחַבְרֵיהּ אֲרוּם בְחוֹבֵי חִמּוּדַיָא מַלְכוּתָא מִתְגַרְיָא בְּנִכְסֵיהוֹן דִּבְנֵי נְשָׁא וּלְמֵיסַב יַתְהוֹן וְעַתִּירֵי נִכְסִין מִתְמַסְכְּנִין וְגָלוּתָא אַתְיָא עַל עַלְמָא\",0,0],[4,143,20,15,\"וְכָל עַמָּא חַמְיַין יַת קָלַיָיא הֵיךְ הֲווֹ מִתְהַפְּכִין בְּשָׁמְעֲהוֹן דְּכָל חַד וְחַד וְהֵיךְ הֲווֹ נַפְקִין מִן גּוֹ בְּעוּרַיָא וְיַת קַל שׁוֹפְרָא הֵיךְ הֲוָה מְחֵי מֵיתַיָא וְיַת טוּרָא תָּנֵין וְחָמוּן כָּל עַמָּא וּרְתָעַן וְקָמוּ תְּרֵיסַר מִילִין מֵרָחִיק\",0,0],[4,143,20,16,\"וַאֲמָרוּ לְמשֶׁה מַלֵּיל אַנְתְּ עִמָּנָא וּנְקַבֵּיל וְלָא יִתְמַלֵּל עִמָּנָא תּוּב מִן קֳדָם יְיָ דִלְמָא נְמוּת\",0,0],[4,143,20,17,\"וַאֲמַר משֶׁה לְעַמָּא לָא תְדַחֲלוּן אֲרוּם מִן בִּגְלַל לְנַסָּיוּתְכוֹן אִתְגְּלֵי לְכוֹן יְקָרָא דַיְיָ וּמִן בִּגְלַל דְּתֶהֱוֵי דַחַלְתֵּיהּ עַל אַפֵּיכוֹן בְּגִין דְּלָא תְחוּבוּן\",0,0],[4,143,20,18,\"וְקָם עַמָּא תְּרֵיסַר מִילִין מֵרָחִיק וּמשֶׁה קָרֵיב לְצֵית אַמִיטְתָא דְתַּמָּן יְקַר שְׁכִינְתָּא דַיְיָ\",0,0],[4,143,20,19,\"וַאֲמַר יְיָ לְמשֶׁה כִּדְנָא תֵימַר לִבְנֵי יִשְרָאֵל אַתּוּן חֲמִיתּוּן אֲרוּם מִן שְׁמַיָא מַלֵּילִית עִמְכוֹן\",0,0],[4,143,20,20,\"עַמִּי בְּנֵי יִשְרָאֵל לָא תַעַבְדוּן לְמִסְגוֹד דְּמוּת שִׁמְשָׁא וְסִיהֲרָא וְכוֹכְבַיָא וּמַזְלַיָא וּמַלְאָכַיָא דִמְשַׁמְשִׁין קֳדָמוֹי דַּחֲלָן דִּכְסַף וְדַחֲלָן דִּדְהַב לָא תַעַבְדוּן לְכוֹן\",0,0],[4,143,20,21,\"מַדְבַּח אַדְמְתָא תַעֲבֵיד לִשְׁמִי וּתְהֵי דַבַּח עֲלוֹי יַת עַלְוָותָךְ וְיַת נִכְסַת קוּדְשָׁךְ מִן עָנָךְ וּמִן תּוֹרָךְ בְּכָל אַתְרָא דְאַשְׁרֵי שְׁכִינְתִּי וְאַנְתְּ פְּלַח קֳדָמַי תַּמָּן אֲשַׁלַח עֲלָךְ בִּרְכָתִי וְאֵיבָרֵיכִינָךְ\",0,0],[4,143,20,22,\"וְאִם מַדְבַּח אַבְנִין תַּעֲבֵיד לִשְׁמִי לָא תִבְנֵי יַתְהוֹן חֲצִיבִין דְּאִין אֲרֵימַת פַּרְזְלָא דְמִנֵיהּ מִתְעֲבֵיד סְיָיפָא עַל אַבְנָא אַפִיסְתָּא יָתָהּ\",0,0],[4,143,20,23,\"וְאַתּוּן כַּהֲנַיָא דְקַיְימִין לְמִשַׁמְשָׁא קֳדָמַי לָא תִסְקוּן בְּמַסוּקְיָין עַל מַדְבְּחִי אֱלָהֵן בְּגִשְׁרַיָא דְלָא תִּתְחַמֵי עִירְיָתָךְ עֲלוֹי\",0,0],[4,143,21,1,\"ואלה וְאִלֵּין הִינוּן סִדְרֵי דִינַיָא דִי תְסַדֵּר קֳדָמֵיהוֹן\",0,0],[4,143,21,2,\"אֲרוּם תִּיזְבוּן בִּגְנֵיבוּתֵיהּ לְעַבְדָא בַּר יִשְרָאֵל שִׁית שְׁנִין יִפְלַח וּבְמַעֲלֵי שְׁבִיעָתָא יִפּוֹק לְבַר חוֹרִין מַגָּן\",0,0],[4,143,21,3,\"אִין בִּלְחוֹדוֹי יֵיעוֹל בִּלְחוֹדוֹי יִפּוֹק וְאִין מָרֵי אִינְתְּתָא בַּת יִשְרָאֵל הוּא וְתִיפּוֹק אִינְתְּתֵיהּ עִמֵּיהּ\",0,0],[4,143,21,4,\"אִין רִבּוֹנֵיהּ יִתֵּן לֵיהּ אִתְּתָא אַמְתָא וְתֵילִיד לֵיהּ בְּנִין אוֹ בְּנָן אִתְּתָא וּבְנָהָא תְּהֵא לְרִבּוֹנָהּ וְהוּא יִפּוֹק בִּלְחוֹדוֹי\",0,0],[4,143,21,5,\"וְאִין יַתְנֵי וְיֵימַר עַבְדָא רְחֵימְנָא יַת רִבּוֹנִי יַת אִנְתְּתִי וְיַת בְּנַי לָא אֵיפּוֹק לְבַר חוֹרִין\",0,0],[4,143,21,6,\"וִיקַרְבִינֵיהּ רִבּוֹנֵיהּ לִקְדָם דַּיָּינַיָא וְיִסַּב מִנְהוֹן רְשׁוּתָא וִיקַרְבִינֵיהּ לְוַת דָּשָׁא דְּלוּחַ מְזוּזְתָא וִיחַיֵּיט רִבּוֹנֵיהּ יַת אוּדְנֵיהּ יַמִּינָא בְּמַחְטָא וִיהֵי לֵיהּ עָבַד פְּלַח עַד יוּבְלָא\",0,0],[4,143,21,7,\"וַאֲרוּם יִזְבּוֹן גְּבַר בַּר יִשְרָאֵל יַת בְּרַתֵּיהּ זְעֵירְתָּא לְאַמְהוּ לָא תִיפּוֹק כְּמַפְקָנוּת עַבְדַיָא כְּנַעֲנָאֵי דְּמִשְׁתַּחְרְרִין בְּשִׁינָא וְעֵינָא אֱלָהֵן בִּשְׁנִין דִּשְׁמִיטָתָא וּבְסִימָנַיָא וּבְיוּבְלָא וּבְמוֹתַת רִבּוֹנָהָא וּפוּרְעַן כַּסְפָּא\",0,0],[4,143,21,8,\"אִין לָא אַשְׁכַּחַת חִינָא קֳדָם רִבּוֹנָהָא דְּזַבִּין יָתָהּ וְיִפְרוֹק יָתָהּ אָבוּהָא לִגְבַר אוֹחֲרָן לֵית לֵיהּ רְשׁוּ לִזְבּוֹנָהּ חֲלַף דְּמַנִי מָרָהּ רְשׁוּתֵיהּ עֲלָהּ\",0,0],[4,143,21,9,\"וְאִין לְצֵיד בְּרֵיהּ זַמִּין יָתָהּ כְּהִלְכַת בְּנַת יִשְרָאֵל יַעֲבִיד לָהּ\",0,0],[4,143,21,10,\"אִין אוֹחֲרַנְתָּא בַּת יִשְרָאֵל יִסַב לֵיהּ עֲלָהּ מְזוֹנָהּ וְתַכְשִׁיטָהּ וּמְעַיֵּל לָהּ לָא יִמְנַע לָהּ\",0,0],[4,143,21,11,\"אִין תְּלַת מִילַיָיא הָאִלֵּין לָא יַעֲבֵיד לָהּ לִמְזַמְנָא יָתָהּ לֵיהּ אוֹ לִבְרֵיהּ אוֹ לְמִפְרְקָא לְבַר אָבוּהָא וְתִיפּוֹק מַגָּן בְּלָא כְסַף בְּרַם גֵּט פְּטוּרִין יָהִיב לָהּ\",0,0],[4,143,21,12,\"דְּיִמְחֵי לְבַר יִשְרָאֵל אוֹ לְבַת יִשְרָאֵל וְיִקְטְלִינֵיהּ אִתְקְטָלָא יִתְקְטֵיל בִּסְיָיפָא\",0,0],[4,143,21,13,\"וְדִי לָא אִיזְדַוֵּיג לֵיהּ וּמִן קֳדָם יְיָ אֲרַע עִיקְתֵיהּ לִידוֹי וַאֲזַמֵן לָךְ אֲתַר דְּיַעֲרוֹק לְתַמָּן\",0,0],[4,143,21,14,\"וַאֲרוּם יִרְשַׁע גְּבַר עַל חַבְרֵיהּ לְמִקְטְלֵיהּ בִּנְכִילוּ אֲפִילּוּ כַּהֲנָא הוּא וּמְשַׁמֵּשׁ עַל גַּבֵּי מַדְבְּחִי מִתַּמָּן תִּסְבוּנֵיהּ וְתִקְטְלִינֵיהּ בְּסַיָּיפָא\",0,0],[4,143,21,15,\"וּדְחַבֵּל בְּאָבוֹי וּבְאִימֵיהּ אִתְקְטָלָא יִתְקְטֵיל בְּשִׁינוּקָא דְסוּדְרָא\",0,0],[4,143,21,16,\"וּדְיִגְנוֹב נֶפֶשׁ מִבְּנֵי יִשְרָאֵל וִיזַבְּנִינֵיהּ וְיִשְׁתַּכַּח בִּרְשׁוּתֵיהּ אִתְקְטָלָא יִתְקְטֵיל בְּשִׁינוּקָא דְסוּדְרָא\",0,0],[4,143,21,17,\"וּדְיֵילוּט לְאָבוּי וּלְאִימֵיהּ בִּשְׁמָא מְפַרְשָׁא אִתְקְטָלָא יִתְקְטֵיל בְּאַטְלוּת אַבְנִין\",0,0],[4,143,21,18,\"וַאֲרוּם יִנְצוּן גּוּבְרִין וְיִמְחוּן חַד לְחַבְרֵיהּ בְּאַבְנָא אוֹ בְּמַרְתּוֹקָא (נ\\\"א מוֹרְנִיתָא) וְלָא יְמוּת וְיִפּוֹל לְמֵירַע\",0,0],[4,143,21,19,\"אִין יְקוּם מִמַּרְעֵיהּ וּמְהֲלֵךְ בְּשׁוּקָא עַל מוֹרְנִיתֵיהּ וִיהֵי זַכְיַי מַחְיָיא מִדִּין קְטוֹל לְחוֹד בּוּטְלִין עִיבִידְתֵּיהּ וְצַעֲרֵיהּ וְנִזְקֵיהּ וּבַהֲתֵיהּ יִתֵּן וַאֲגַר אַסְיָא יְשַׁלֵּם עַד דְּמִתְּסֵי\",0,0],[4,143,21,20,\"וַאֲרוּם יִמְחֵי גְבַר יַת עַבְדֵיהּ כְּנַעֲנָאָה אוֹ יַת אַמְתֵיהּ כְּנַעֲנִיתָא בְּשַׁרְבִיטָא וִימוּת בְּהַהוּא יוֹמָא תְּחוֹת יְדֵיהּ יִתְדְּנָא יִתְדַן דִּין קְטִילַת סַיְיפָא\",0,0],[4,143,21,21,\"בְּרַם אִין יוֹמָא חַד מֵעִידַן לְעִידַן אוֹ תְּרֵין יוֹמִין קְטִיעִין יִתְקַיֵּים לָא יִתְדַן מְטוֹל דִּכְסַף זְבִינֵיהּ הוּא\",0,0],[4,143,21,22,\"וַאֲרוּם יִנְצוּן גַּבְרִין וְיִמְחוּן אִתְּתָא מְעַבְּרָא וְאַפִּילַת יַת וַולְדָהָא וְלָא יְהֵי בָהּ מוֹתָא מִתְקַנְסָא יִתְקְנֵיס דְּמֵי וַולְדָא הֵיכְמָא דִמְשַׁוֵי עֲלֵיהּ בַּעֲלֵיהּ דְּאִינְתְּתָא וְיִתֵּן עַל מֵימַר דַּיָינַיָא\",0,0],[4,143,21,23,\"וְאִין מוֹתָא יְהֵי בָהּ וּתְדִינוּן נַפְשָׁא דִקְטוֹלָא חוֹלַף נַפְשָׁא דְאִתְּתָא\",0,0],[4,143,21,24,\"דְּמֵי עֵינָא חוֹלַף עֵינָא דְּמֵי שִׁינָא חוֹלַף שִׁינָא דְּמֵי יְדָא חוֹלַף יְדָא דְּמֵי רִיגְלָא חוֹלַף רִיגְלָא\",0,0],[4,143,21,25,\"דְּמֵי צַעַר מֵחֲרוֹךְ חוֹלַף מֵחֲרוֹךְ דְּמֵי פּוּדְעָא חוֹלַף פּוּדְעָא דְּמֵי הַלְכְשִׁישׁ חוֹלַף הַלְכְשִׁישׁ\",0,0],[4,143,21,26,\"וַאֲרוּם יִמְחֵי גְּבַר יַת עֵינָא דְעַבְדֵיהּ כְּנַעֲנָאֵי אוֹ יַת עֵינָא דְאַמְתֵיהּ כְּנַעֲנִיתָא וְסָמִינָהּ לְבַר חוֹרִין יִפְטְרִינֵיהּ חוֹלַף עֵינֵיהּ\",0,0],[4,143,21,27,\"וְאִין שִׁינָא דְעַבְדֵיהּ כְּנַעֲנָאֵי אוֹ שִׁינָא דְאַמְתֵיהּ כְּנַעֲנִיתָא יַפִּיל לְבַר חוֹרִין יִפְטְרִינֵיהּ חוֹלַף שִׁינֵיהּ\",0,0],[4,143,21,28,\"וַאֲרוּם יִנְגַשׁ תּוֹר יַת גְּבַר אוֹ יַת אִיתָא וִימוּת יִתְרְגָמָא יִתְרְגֵם תּוֹרָא וְלָא יִתְנְכֵס לְמֵיכוּל יַת בִּשְרֵיהּ וּמָרֵיהּ דְּתוֹרָא יְהֵי זַכְּאַי מִדִּין קְטוֹל וְאוּף מִדְמֵי עַבְדָא וְאַמְהוּ\",0,0],[4,143,21,29,\"וְאִין תּוֹר נַגְשָׁן הוּא מֵאִתְמְלֵי וּמִדְקֳדָמוֹי וְאִתַּסְהַד עַל אַנְפֵּי מָרֵיהּ תְּלָתֵי זִמְנֵי וְלָא נַטְרֵיהּ וּמִבָּתַר כֵּן קָטֵל גַּבְרָא אוֹ אִיתָא תּוֹרָא יִתְרְגֵם וְאוּף מָרֵיהּ יִתְקְטֵיל בְּמִיתוּתָא דְמִשְׁתַּלְחָא עֲלוֹי מִן שְׁמַיָא\",0,0],[4,143,21,30,\"בְּרַם אִין קְנָסָא דְמָמוֹנָא יִתְשַׁוֵּי עֲלוֹי וְיִתֵּן פּוּרְקַן נַפְשֵׁיהּ כְּכָל מַה דִּישַׁווּן עֲלוֹי סַנְהֶדְרִין דְּיִשְרָאֵל\",0,0],[4,143,21,31,\"אִין בַּר יִשְרָאֵל יְנַגַּח תּוֹרָא אוֹ לְבַת יִשְרָאֵל יְנַגַּח כְּדִינָא הָדֵין יִתְעֲבֵד לֵיהּ\",0,0],[4,143,21,32,\"בְּרַם אִין עֶבֶד כְּנַעֲנָאֵי נְגַשׁ תּוֹרָא אוֹ אַמְתָא כְּנַעֲנִיתָא כְּסַף תְּלָתִין סִלְעִין יִתֵּן לְמָרֵיהּ דְּעַבְדָא אוֹ דְאַמְתָא וְתוֹרָא יִתְרְגָם\",0,0],[4,143,21,33,\"וַאֲרוּם יִפְתָּח אֵינַשׁ גּוּב אוֹ אֲרוּם יַחְפֵּס אֵינָשׁ גּוּב בְּשׁוּקָא וְלָא יְכַסִּינֵיהּ וּנְפוֹל תַּמָּן תּוֹרָא אוֹ חַמָרָא\",0,0],[4,143,21,34,\"מָרֵיהּ דְּגוֹבָא יְשַׁלֵּם כְּסַף יָתֵיב לְמָרֵיהּ דְּמֵי תּוֹרֵיהּ וְחַמְרֵיהּ וּנְבֵילְתָּא יְהֵי דִילֵיהּ\",0,0],[4,143,21,35,\"וַאֲרוּם יִנְגוֹף תּוֹר דִּגְבַר יַת תּוֹרָא דְּחַבְרֵיהּ וִימוּת וִיזַבְּנוּן יַת תּוֹרָה חַיָיא וְיִפְלְגוּן יַת דְּמֵיהּ וְאוּף יַת דְּמֵי מוֹתָא יִפְלְגוּן\",0,0],[4,143,21,36,\"אִין אִישְׁתְּמוֹדַע אֲרוּם תּוֹר נַגְחָן הוּא מֵאִתְמְלֵי וּמִדְקֳדָמוֹי וְלָא נַטְרֵיהּ מָרֵיהּ שַׁלְמָא יְשַׁלֵם תּוֹרָא חוֹלַף תּוֹרָא וּנְבֵילְתָּא וּמוֹשְׁכָא יְהֵי דִילֵיהּ\",0,0],[4,143,21,37,\"אֲרוּם יִגְנוֹב גְּבַר תּוֹר אוֹ אִימַר וְיִכְסִינֵיהּ אוֹ זַבִּינֵיהּ חַמְשָׁא תּוֹרָא יְשַׁלֵם חוֹלַף תּוֹר חַד מִן בִּגְלַל דְּבַטְלֵי מִן רַדְיֵיה וְאַרְבַּע עָנָא חוֹלַף אִימַר חַד מִן בִּגְלַל דְּאַקְטֵיהּ בִּגְנֵבוּתֵיהּ וְלֵית בָּהּ עִיבִידְתָּא\",0,0],[4,143,22,1,\"אִין בַּחְרַכָּא דְכוֹתְלָא מִשְׁתְּכַח גַּנָבָא וְיִתְמְחֵי וִימוּת לֵית לֵיהּ חוֹבַת שְׁפִיכוּת אֲדַם זַכְּאַי\",0,0],[4,143,22,2,\"אִין בָּרִיר פִּתְגָּמָא כְשִׁמְשָׁא דְּלָא לְמִיקְטוֹל נְפַשׁ עָאל וְקַטְלֵיהּ חוֹבַת שְׁפִיכוּת אֲדַם זַכְּאַי עֲלוֹי וְאִין אִישְׁתְּזִיב מִן יְדוֹי שַׁלָמָא יְשַׁלֵם אִין לֵית לֵיהּ מַה דִּמְשַׁלֵם וְיִזְדַּבֵּן לֵיהּ בֵּית דִּינָא מִן גְּנִיבוּתֵיהּ וְעַד שַׁתָּא דִשְׁמִיטְתָא\",0,0],[4,143,22,3,\"אִין בְּסַהֲדַיָא מִשְׁתַּכְּחָא בִּרְשׁוּתֵיהּ גְּנִיבוּתֵיהּ מִן תּוֹר עַד חֲמוֹר עַד אִימַר כַּד הִינוּן קַיְימִין עַל חַד תְּרֵין יְשַׁלֵּם\",0,0],[4,143,22,4,\"אֲרוּם יִפְקַר גְּבַר חֲקִיל אוֹ כַּרְמָא וִישַׁלַח יַת בְּעִירֵיהּ וְיֵיכוּל בַּחֲקַל גְּבַר אוֹחֲרָן שְׁפַר חַקְלֵיהּ וּשְׁפַר כַּרְמֵיהּ יְשַׁלֵּם\",0,0],[4,143,22,5,\"אֲרוּם תִּתְפּוֹק נוּר וְתַשְׁכַּח כּוּבִין וְתִגְמַר גָּדִישׁ אוֹ מִדַּעַם דְּקָאִי אוֹ חֲקִיל שַׁלָמָא יְשַׁלִים מַאן דְּאַדְלִיק יַת דְּלֵיקְתָּא\",0,0],[4,143,22,6,\"אֲרוּם יִתֵּן גְּבַר לְחַבְרֵיהּ כְּסַף אוֹ מָאנִין לְמִנְטַר בְּלָא אֲגַר נְטִיר וּמִתְגַנְבִין מִן בֵּית גְּבַר אִין מִשְׁתְּכַּח גַּנְבָא אִיהוּ מְשַׁלֵּם עַל חַד תְּרֵין\",0,0],[4,143,22,7,\"אִין לָא אִישְׁתַּכַּח גַּנְבָא וְיִתְקְרֵיב מָרֵיהּ בֵּיתָא לִקְדָם דַּיָינַיָא וְיוֹמֵי דְלָא אוֹשִׁיט יְדֵיהּ בְּעִיסְקָא דְחַבְרֵיהּ\",0,0],[4,143,22,8,\"עַל כָּל מִדַּעַם דְּאִתְּבִיר בְּכוּסְיָא עַל תּוֹר עַל חֲמוֹר עַל אִימַר עַל כְּסוּי עַל כָּל אֲבִידְתָּא יוֹמֵי כַּד יֵימַר אֲרוּם הוּא דֵין וְכַד מִשְׁתַּכְּחָא גְנִיבוּתָא בָּתַר כֵּן בְּיַד גַּנָבָא קֳדָם דַּיָינַיָא יוֹעִיל דִּין תַּרְוֵויהוֹם דִּין מָרֵיהּ דְּבֵיתָא וְדִין גַּנְבָא וּלְמַאן דִּמְחַיְיבִין דַּיָינַיָא יְשַׁלֵּם גַּנְבָא עַל חַד תְּרֵין לְחַבְרֵיהּ\",0,0],[4,143,22,9,\"אֲרוּם יִתֵּן גְּבַר לְחַבְרֵיהּ חֲמוֹר אוֹ תּוֹר אוֹ אִימַר וְכָל בְּעִירָא לְמִנְטוֹר בְּלָא אֲגַר נְטִיר וִימוּת אוֹ אִיתְבִיר מִן חֵיוָא אוֹ אִישְׁתְּבֵי וְלֵית סָהִיד חָמֵי וּמַסְהִיד\",0,0],[4,143,22,10,\"מוֹמָתָא דַיְיָ תְּהֵי בֵּין תַּרְוֵיהוֹם יוֹמֵי דְלָא אוֹשִׁיט יְדֵיהּ בְּעִיסְקָא דְחַבְרֵיהּ וִיקַבֵּל מָארֵיהּ מִנֵיהּ מוֹמָתָא וְלָא יְשַׁלֵּם\",0,0],[4,143,22,11,\"וְאִין יִתְגַנְבָא יִתְגַנֵּב מִנֵיהּ דַּהֲוָה לֵיהּ עִמֵּיהּ אֲגַר נְטִיר יְשַׁלֵם לְמָרוֹי\",0,0],[4,143,22,12,\"אִין אִתְבְּרָא יִתְבַּר מִן חֵיוַת בְּרָא מַיְיתֵי לֵיהּ סַהֲדִין אוֹ יַמְטִינֵיהּ עֵד גּוּפָא דִתְבִיר לָא יְשַׁלֵּם\",0,0],[4,143,22,13,\"וַאֲרוּם יִשְׁאַל גְּבַר מִדַּעַם מִן חַבְרֵיהּ וְיִתְבַּר מָנָא אוֹ מִית בְּעִירָא מָרֵיהּ לֵית עִמֵּיהּ שַׁלָּמָא יְשַׁלֵּם\",0,0],[4,143,22,14,\"אִין מָרֵיהּ עִמֵּיהּ לָא יְשַׁלֵּם אִין אֲגִירָא הוּא עָאֵל פְּסֵידֵיהּ בְּאַגְרֵיהּ\",0,0],[4,143,22,15,\"וַאֲרוּם יְשַׁרְגֵג גְּבַר בְּתוּלְתָּא דְלָא מְאַרְסָא וִישַׁמֵּשׁ עִמָּהּ מַפְרָנָא יַפְרִין יָתָהּ לֵיהּ לְאִינְתּוּ\",0,0],[4,143,22,16,\"אִין לָא חַמְיָא לֵיהּ אוֹ דְלָא יִצְבֵי אָבוּהָא לְמִתְבָהּ לֵיהּ כְּסַף חַמְשִׁין סַלְעִין יִתְקְנֵס הֵי כְמִפְרוֹנִי בְּתוּלְתָּא\",0,0],[4,143,22,17,\"עַמִּי בְנֵי יִשְרָאֵל כָּל עֲבִיד חַרְשִׁיּוּתָא לָא תְקַיְימוּן\",0,0],[4,143,22,18,\"כָּל דְּיִשְׁכּוּב עִם בְּעִירָא בְאַטְלוּת אַבְנִין יִתְקַטְלוּן\",0,0],[4,143,22,19,\"כָּל מַאן דְּדַבַּח לְטַעֲוַות עַמְמַיָא יִתְקְטֵל בְּסַיְיפָא וְנִכְסוֹי יִתְגַמְרוּן בְּגִין כֵּן לָא תְהוֹן פַּלְחִין אֱלָהֵן לִשְׁמָא דַיְיָ בִּלְחוֹדוֹי\",0,0],[4,143,22,20,\"וְגִיּוֹרָא לָא תְקַנְטוּן בְּמִילִין וְלָא תְעִיקוּן לְמִיסַב לֵיהּ נִכְסוֹי עַמִּי בְנֵי יִשְרָאֵל הֲווֹ דְכִירִין אֲרוּם דַּיְירִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם\",0,0],[4,143,22,21,\"כָּל אַרְמְלָא וְיָתוֹם לָא תְסַגְפוּן\",0,0],[4,143,22,22,\"אִין סַגָּפָא תְסַגֵּף יָתֵיהּ אִזְדַהֲרוּן לְכוֹן אֲרוּם אִין יְקוּם וְיִצְוַוח עֲלֵיכוֹן בִּצְלוֹי קֳדָמַי שְׁמַע אֲנָא בְּקַל צְלוֹתֵיהּ וּפָרַע לֵיהּ\",0,0],[4,143,22,23,\"וְיִתְקַף רוּגְזִי וְאֶקְטוֹל יַתְכוֹן בְּחַרְבָּא דְמוֹתָא וִיהוֹן נְשֵׁיכוֹן אַרְמְלָן וּבְנֵיכוֹן יַתְמִין\",0,0],[4,143,22,24,\"אִין כַּסְפָּא תּוֹזִיף לְעַמִּי יַת עַנְיָיא דְעִמָּךְ לָא תְהֵי לֵיהּ הֵי כְּרַשְׁיָא לָא תְשַׁוּוּן דְּלֶהֱוֵי עֲלוֹי סַהֲדִין וּמִידִי עַרְבְנוּתָא לָא עַל שְׁעָרִין וְלָא רִיבְיָין\",0,0],[4,143,22,25,\"אִין מְמַשְׁכְּנָא תְמַשְׁכַּן כְּסוּתָא דְחַבְרָךְ עַד לָא יִטְמוֹעַ שִׁמְשָׁא תְּתָבִינֵיהּ לֵיהּ\",0,0],[4,143,22,26,\"אֲרוּם הִיא טָלֵית דְּמִתְכַּסֵּי בָהּ בִּלְחוֹדָהּ הִיא תּוֹתְבֵיהּ דְּנַפְלָא לְמוֹשְׁכֵיהּ וְאִין תִּיסַב מַצַּע עַרְסֵיהּ בַּמֶּה יִשְׁכּוּב וִיהֵי אִין יִקְבּוֹל קֳדָמַי וַאֲקַבֵּיל צְלוֹתֵיהּ אֲרוּם אֱלָהָא חֲנָנָא אֲנָא\",0,0],[4,143,22,27,\"עַמִּי בְנֵי יִשְרָאֵל דַּיָּינֵיכוֹן לָא תְקִילִין וְרַבָּנִין דִּמִתְמַנִין נְגוֹדִין בְּעַמָּךְ לָא תְלוּטִין\",0,0],[4,143,22,28,\"בִּכּוּרֵי פֵּירָךְ וּבִכּוּרֵי חֲמַר נַעֲוָוךְ לָא תַשְׁהֵי עַל זִמָנֵיהוֹן מִן לְאַסְקוּתְהוֹן לַאֲתַר שְׁכִינְתִּי בּוּכְרֵי דִבְרָךְ תַּפְרֵישׁ קֳדָמַי\",0,0],[4,143,22,29,\"הֵיכְדֵין תַּעֲבֵד לְבוּכְרֵי תוֹרָךְ וְעָנָךְ שַׁבְעָא יוֹמִין יְהֵי יֵינִיק בָּתַר אִימֵיהּ וּבְיוֹמָא תְּמִינָאָה תַּפְרִישִׁינֵיהּ קֳדָמַי\",0,0],[4,143,22,30,\"וְאַנְשִׁין קַדִּישִׁין טְעָמִין חוּלִין בִּדְכוּתָא תְּהוֹן קֳדָמַי בְּרַם בְּשַר תְּלִישׁ מִן חֵיוָותָא חַיָיא לָא תֵיכְלוּן לְכַלְבָּא תֵירְמוּן יָתֵיהּ בְּסִיטְרֵיהּ\",0,0],[4,143,23,1,\"עַמִּי בְּנֵי יִשְרָאֵל לָא תְקַבְּלוּן מִילֵי שִׁיקְרָא מִגַּבְרָא דְּיֵיכוּל קוֹרְצִין בְּחַבְרֵיהּ קֳדָמָךְ וְלָא תְשַׁוֵּי יְדָךְ עִם רַשִׁיעָא דִיהֵי סָהִיד שְׁקָר\",0,0],[4,143,23,2,\"עַמִּי בְּנֵי יִשְרָאֵל לָא תֶהֱווֹן בָּתַר סַגִּיאִין לְמַבְאֲשָׁא אֱלָהֵן לִמְטַיְיבָא וְלָא יִתְמְנַע חַד מִנְכוֹן לְמַלְפָא זְכוּ עַל חַבְרֵיהּ בְּדִינָא לְמֵימַר הָא בָּתַר סַגִּיאֵי דִינָא סָטֵי\",0,0],[4,143,23,3,\"וּמִסְכְּנָא דְאִתְחַיֵּיב בְּדִינֵיהּ לָא תִיסַב לֵיהּ אַפִּין לִמְרַחֲמָא עֲלוֹי אֲרוּם לֵית מִיסַב אַפִּין בְּדִינָא\",0,0],[4,143,23,4,\"אִין תֶּאֱרַע תּוֹרָא דְסַנְאָךְ דְּאַתְּ סָנֵי לֵיהּ עַל חוֹבָתָא דְאַנְתְּ יְדַע בֵּיהּ בִּלְחוֹדָךְ אוֹ חַמְרָא דְטָעֵי מִן אָרְחָא אָתָבָא תִתְבִינֵיהּ לֵיהּ\",0,0],[4,143,23,5,\"אִין תֶּחֱמֵי חַמְרָא דְסַנְאָךְ דְּאַנְתְּ סָנֵי לֵיהּ עַל חוֹבָתָא דְאַנְתְּ יְדַע בֵּיהּ בִּלְחוֹדָךְ רְבִיעַ תְּחוֹת טוֹנֵיהּ וְתִמְנוֹעַ לְנַפְשָׁךְ מִלְמִקְרוֹב לֵיהּ מִשְׁבּוֹק תִּשְׁבּוֹק בְּהַהִיא שַׁעְתָּא יַת סָנָא דִבְלִבָּךְ עֲלוֹי וְתִפְרוֹק וְתִטְעוֹן עִמֵּיהּ\",0,0],[4,143,23,6,\"עַמִּי בְּנֵי יִשְרָאֵל לָא תַצְלוּן דִּין מִסְכֵּינָא בְּדִינֵיהּ\",0,0],[4,143,23,7,\"מִפִּתְגַם שִׁיקְרָא הֲוֵי רָחִיק וְדִי נְפַק זַכְּאַי מִבֵּי דִינָךְ וְאַשְׁכָּחוּ לֵיהּ חוֹבָתֵיהּ וְדִי נְפַק חַיָּיב וְאַשְׁכָּחוּ לֵיהּ זְכוּ לָא תִקְטֵיל אֲרוּם לָא הֲוֵינָא מְזַכֵּי לֵיהּ אִין הוּא חַיָּיבָא\",0,0],[4,143,23,8,\"וְשׁוֹחֲדָא לָא תְקַבֵּיל אֲרוּם שׁוֹחֲדָא מְסַמֵּי עֵינוֹי נַסְבוֹי וּמְטַלְטֵל חַכִּימַיָא מִמוֹתְבָנֵיהוֹן וּמְקַלְקֵל פִּתְגָּמִין תְּרִיצִין דְּמִכְתָּבִין בְּאוֹרַיְיתָא וּמְעַרְבֵב מִילֵי זַכָּאִין בְּפוּמְהוֹן בְּשַׁעַת דִּינָא\",0,0],[4,143,23,9,\"וּלְגִיּוּרָא לָא תְעִיקוּן וְאַתּוּן חַכִּימְתּוּן יַת אֲנִיק נְפַשׁ גִּיּוֹרָא אֲרוּם דַּיְירִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם\",0,0],[4,143,23,10,\"וְשִׁית שְׁנִין תִּדְרַע יַת אַרְעָךְ וְתִכְנוֹשׁ יַת עֲלַלְתָּא\",0,0],[4,143,23,11,\"וּשְׁבִיעִיתָא תִּשְׁמְטִינָא מִפּוּלְחָנָא וְתַפְקַר פֵּירָהָא וְיֵיכְלוּן מִסְכֵּינֵי עַמָּא וְשִׁיּוּרְהוֹן תֵּיכוּל חֵיוַת בָּרָא כְּדֵין תַּעֲבֵיד לְכַרְמָךְ לְזֵיתָךְ\",0,0],[4,143,23,12,\"שִׁיתָּא יוֹמִין תַּעֲבֵד עוּבְדָךְ וּבְיוֹמָא שְׁבִיעָאָה תִּנּוּחַ מִן בִּגְלַל דִּינוּחוּן תּוֹרָךְ וְחַמְרָךְ וְיִשְׁקוֹט בַּר אַמְתָךְ עַרְלָאָה וְגִיּוֹרָא\",0,0],[4,143,23,13,\"וּבְכָל פִּקּוּדַיָא דְאָמְרִית לְכוֹן תִּסְתַּמְּרוּן וְשׁוּם טַעֲוַות עַמְמַיָא לָא תִדְכְּרוּן לָא יִשְׁתְּמַע עַל פּוּמְכוֹן\",0,0],[4,143,23,14,\"תְּלָתָא זִמְנִין תְּחַגּוּן קֳדָמַי בְּשַׁתָּא\",0,0],[4,143,23,15,\"יַת חַגָּא דְפַטִירַיָיא תִּנְטוֹר שׁוּבְעָא יוֹמִין תֵּיכוֹל פַּטִּירָא הֵיכְמָא דְפַקֵידְתָּךְ לִזְמַן יַרְחָא דְאַבִּיבָא אֲרוּם בֵּיהּ נְפַקְתְּ מִמִּצְרַיִם וְלָא יִתְחַמּוּן קֳדָמַי רֵיקָנִין\",0,0],[4,143,23,16,\"וְחַגָא דְחַצְדָא בִּכּוּרֵי עוּבְדָךְ דְּתִזְרַע בְּחַקְלָא וְחַגָא דִּכְנָשָׁא בְּמִפְקָא דְשַׁתָּא בְּמִכְנְשָׁךְ יַת עוּבְדָךְ מִן חַקְלָא\",0,0],[4,143,23,17,\"תְּלָתָא זִמְנִין בְּשַׁתָּא יִתְחַמּוּן כָּל דְּכוּרָךְ קֳדָם רִבּוֹן עַלְמָא יְיָ\",0,0],[4,143,23,18,\"עַמִּי בְנֵי יִשְרָאֵל לָא תֵכְסוּן כַּד דְּחָמִיעַ בְּבָתֵּיכוֹן דָּם נִכְסַת פִּיסְחִי וְלָא יְבִית בַּר מִן מַדְבְּחָא תַּרְבֵּי נִכְסַת פִּסְחִי עַד צַפְרָא לָא מִן בִּשְרָא דְתֵיכְלוּן בְּרַמְשָׁא\",0,0],[4,143,23,19,\"שֵׁירוּי בִּיכוּרֵי פֵּירֵי אַרְעָךְ תַּיְתֵי לְבֵית מַקְדְּשָׁא דַיְיָ אֱלָהָךְ עַמִּי בֵּית יִשְרָאֵל לֵית אַתּוּן רְשָׁאִין לָא לִמְבַשְׁלָא וְלָא לְמֵיכוּל בְּשַר וַחֲלַב מְעַרְבִין כַּחֲדָא דְלָא יִתְקַף רוּגְזִי וְאִיבְשֵׁיל עִיבּוּרֵיכוֹן דְּגָנָא וְקַשָׁא תְּרֵיהוֹן כַּחֲדָא\",0,0],[4,143,23,20,\"הָא אֲנָא מְשַׁגֵּר מַלְאָכָא קֳדָמָךְ לְמִטְרָךְ בְּאָרְחָא וּלְאַעֲלוּתָךְ לַאֲתַר שְׁכִינְתִּי דְאִיתְקֵינִית\",0,0],[4,143,23,21,\"אִיזְדַהַר מִן קֳדָמוֹי וְקַבֵּיל לְמֵימְרֵיהּ לָא תְסָרֵיב עַל מִילוֹי אֲרוּם לָא יִשְׁבּוֹק לְחוֹבֵיכוֹן אֲרוּם בִּשְׁמִי מֵימְרֵיהּ\",0,0],[4,143,23,22,\"אֲרוּם אִין קַבָּלָא תְקַבֵּיל לְמֵימְרֵיהּ וְתַעֲבֵיד כָּל דַּאֲמַלֵּיל עַל יְדוֹי וְאַסְגֵי יַת סַנְאָךְ וְאָעִיק לְמֵיעִיקְיָךְ\",0,0],[4,143,23,23,\"אֲרוּם יְטַיֵיל מַלְאָכִי קֳדָמָךְ וְיֵעָלִינָךְ לְוַת אֱמוֹרָאֵי וְחִיתָּאֵי וּפְרִיזָאֵי וּכְנַעֲנָאֵי חִיוָאֵי וִיבוּסָאֵי וְאֵישֵׁיצִינוּן\",0,0],[4,143,23,24,\"לָא תִסְגְּדוּן לְטַעֲוַותְהוֹן וְלָא תִפְלְחִינוּן וְלָא תַעַבְדוּן כְּעוֹבְדֵיהוֹן בִּישַׁיָּיא אֲרוּם מְפַכְרָא תִּפְכַר בֵּית סְגוּדְהוֹן וְתִבְרָא תְּתַבֵּר קָמְתֵי צִילְמֵיהוֹן\",0,0],[4,143,23,25,\"וְתִפְלְחוּן קֳדָם יְיָ אֱלָהָכוֹן וִיבָרֵךְ יַת מְזוֹנֵי מֵיכְלָךְ וּמִשְׁתַּיָּיךְ וְאַעֲדֵי מְחַת מָרִירְתָּא מִגַּוָּוךְ\",0,0],[4,143,23,26,\"לָא תְהֵי תַּכְלָא וְעַקְרָא בְּאַרְעָךְ יַת מִנְיַין יוֹמֵי חַיָּיךְ אֲשַׁלֵּם מִיּוֹמָא לְיוֹמָא\",0,0],[4,143,23,27,\"יַת אֵימְתִי אֲשַׁדֵּר קֳדָמָךְ וָאֶשְׁגַשׁ יַת כָּל עַמְמַיָא דְאַנְתְּ אָתֵי לְסַדְרָא בְּהוֹן סִדְרֵי קְרָבָא וְאִיתֵּין יַת כָּל בַּעֲלֵי דְבָבָךְ קֳדָמָךְ מְחַזְרֵי קְדָל\",0,0],[4,143,23,28,\"וְאֵשַׁדַּר יַת אוּרְעִיתָא קֳדָמָךְ וּתְתָרֵךְ יַת חִיוָאֵי וְיַת כְּנַעֲנָאֵי וְיַת חִיתָּאֵי מִן קֳדָמָךְ\",0,0],[4,143,23,29,\"לָא אֵיתָרֵיכִינוּן מִן קֳדָמָךְ בְּשַׁתָּא חֲדָא דִלְמָא תְהֵי אַרְעָא צַדְיָא וְיִסְגוּן עֲלָךְ חֵיוַת בָּרָא כַּד יֵיתוּן לְמֵיכוּל פִּיגְרֵיהוֹן וְיִנְזְקוּן בָּךְ\",0,0],[4,143,23,30,\"קָלִיל קָלִיל אֵיתָרְכִינוּן מִן קֳדָמָךְ עַד דִּי תִסְגֵי וְתֶחֱסִין יַת אַרְעָא\",0,0],[4,143,23,31,\"וַאֲשַׁוֵי יַת תְּחוּמָךְ מִן יַמָא דְסוּף עַד יַמָא דִפְלִשְׁתָּאֵי וּמִן מַדְבְּרָא וְעַד פְּרָת אֲרוּם אֶמְסוֹר בְּיֶדְכוֹן יַת כָּל יַתְבֵי אַרְעָא וְאַנְתְּ תְּתָרֵיכִינוּן מִן קֳדָמָךְ\",0,0],[4,143,23,32,\"לָא תִגְזְרוּן לְהוֹן וּלְטַעֲוַותְהוֹן קְיָים\",0,0],[4,143,23,33,\"לָא תַעֲבֵיד לְהוֹן שְׁכוּנַן בְּאַרְעָךְ דִּלְמָא יַטְעִינָךְ וִיחַיְיבוּן יָתָךְ קֳדָמַי אֲרוּם תִּפְלַח יַת טַעֲוַותְהוֹן אֲרוּם יְהוֹן לָךְ לְתוּקְלָא\",0,0],[4,143,24,1,\"וּלְוַת משֶׁה אָמַר מִיכָאֵל סַרְכַן חָכְמְתָא בְּיוֹמָא שְׁבִיעָאָה לְיַרְחָא סַק קֳדָם יְיָ אַנְתְּ וְאַהֲרן נָדָב וַאֲבִיהוּא וְשׁוּבְעִין מִסָּבֵי יִשְרָאֵל וְתִסְגְּדוּן מֵרָחִיק\",0,0],[4,143,24,2,\"וְיִתְקָרֵב משֶׁה בִּלְחוֹדוֹי קֳדָם יְיָ וְהִינוּן לָא יִתְקַרְבוּן וְעַמָּא לָא יִסְקוּן עִמֵּיהּ\",0,0],[4,143,24,3,\"וְאָתָא משֶׁה וְאִשְׁתָּעֵי לְעַמָּא יַת כָּל פִּתְגָּמַיָא דַיְיָ וְיַת כָּל דִּינַיָיא וְאָתֵיב כָּל עַמָּא קָלָא חָד וַאֲמָרוּ כָּל דְּמַלֵּיל יְיָ נַעֲבֵיד\",0,0],[4,143,24,4,\"וּכְתַב משֶׁה יַת כָּל פִּתְגָמַיָא דַיְיָ וְאַקְדֵים בְּצַפְרָא וּבְנָא מַדְבְּחָא בְּשִׁיפּוֹלֵי טוּרָא וּתְרֵי סְרֵי קָמָן לִתְרֵי סְרֵי שִׁבְטַיָא דְיִשְרָאֵל\",0,0],[4,143,24,5,\"וְשַׁדַּר יַת בּוּכְרֵי בְּנֵי יִשְרָאֵל אֲרוּם עַד הַהִיא שַׁעְתָּא הֲוַות פּוּלְחָנָא בְּבוּכְרַיָא דְעַד כְּדוֹן לָא אִיתְעֲבֵיד מַשְׁכַּן זִמְנָא וְעַד כְּדוֹן לָא אִתְיְיהִיבַת כְּהוּנְתָּא לְאַהֲרן וְאַסִיקוּ עֲלַוָון וְנִכְסַת קוּדְשִׁין קֳדָם יְיָ תּוֹרִין\",0,0],[4,143,24,6,\"וּנְסֵיב משֶׁה פַּלְגוּת אֲדָם נִכְסָא וְשַׁוִי בְּמִזְרְקַיָא וּפַלְגוּת אֲדָם נִכְסָא דָרַק עַל מַדְבְּחָא\",0,0],[4,143,24,7,\"וּנְסֵיב סִפְרָא דְקַיָימָא דְאוֹרַיְיתָא וּקְרָא קֳדָם עַמָא וְאָמָרוּ כָּל פִּתְגָמַיָא דְמַלֵּיל יְיָ נַעֲבֵיד וּנְקַבֵּיל\",0,0],[4,143,24,8,\"וּנְסֵיב משֶׁה יַת פַּלְגוּת דְּמָא דִבְמִזְרְקַיָא וְדָרֵיק עַל מַדְבְּחָא לְכַפָּרָא עַל עַמָּא וַאֲמַר הָא דֵין אֲדַם קְיָימָא דִגְזַר יְיָ עִמְכוֹן עַל כָּל פִּתְגָמַיָא הָאִילֵן\",0,0],[4,143,24,9,\"וּסְלֵיק משֶׁה וְאַהֲרן נָדָב וַאֲבִיהוּא וְשִׁבְעִין מִסָּבֵי יִשְרָאֵל\",0,0],[4,143,24,10,\"וּזְקָפוּ נָדָב וַאֲבִיהוּא יַת עֵינֵיהוֹן וְחָמוּן יַת אִיקַר אֱלָהָא דְיִשְרָאֵל וּתְחוֹת אַפִּיפּוּרִין דְּרִיגְלוֹי דְמַיְצַע תְּחוֹת כּוּרְסֵיהּ הֵי כְעוֹבַד אַבַן סַפִּירִינוּן מִידְכַּר שִׁעֲבּוּדָא דְשַׁעְבִּידוּ מִצְרָאֵי יַת בְּנֵי יִשְרָאֵל בְּטִינָא וּבְלִיבְנִין וַהֲווֹן נְשַׁיָא בָּטְשָׁן יַת טִינָא עִם גּוּבְרֵיהוֹן הֲוַת תַּמָּן רִיבָא מְפַנְקָתָא מַעְבַּרְתָּא וְאַפִּילַת יַת עוּבְרָא וְאִיתְבַּטַּשׁ עִם טִינָא נָחָת גַּבְרִיאֵל וְעָבַד מִנֵיהּ לְבֵינְתָא וְאַסְקֵיהּ לִשְׁמֵי מְרוֹמָא וְאַתְקְנֵיהּ גִּילוּגְדַק תְּחוֹת אַפִּיפּוּרִין דְּמָרֵי עַלְמָא זִיוֵיהּ הֵי כְּעוֹבַד אֲבַן טָבָא וְהֵי כִּתְקוּף שְׁפַר שְׁמַיָא כַּד הִינוּן בְּרִירִין מִן עֲנָנַיָא\",0,0],[4,143,24,11,\"וּלְוַת נָדָב וַאֲבִיהוּא עוּלֵמַיָא שַׁפִּירַיָא לָא שָׁדַר מַחְתֵּיהּ בְּהַהוּא שַׁעְתָּא בְּרַם אִתְנַטְרָא לְהוֹן לְיוֹם תְּמִינַיָא לְאַשְׁלָמוּתָא לְאַסְעָרָא עֲלֵיהוֹן וְחָמוֹן יַת אִיקַר שְׁכִינְתָּא דַיְיָ וַהֲווֹן חָדָן בְּקוּרְבָּנֵיהוֹן דְּאִתְקַבָּלוּ בְּרַעֲוָא הֵי כְאָכְלִין וְהֵי כְשַׁתְיָין\",0,0],[4,143,24,12,\"וַאֲמַר יְיָ לְמשֶׁה סוֹק קֳדָמַי לְטַוְורָא וַהֲוֵי תַמָּן וְאֵיתַּן לָךְ יַת לוּחֵי אַבְנָא דִּבְּהוֹן רָמוּז שְׁאָר פִּתְגָמֵי אוֹרַיְיתָא וְשִׁית מְאָה וּתְלֵיסְרֵי פִקּוּדַיָיא דִכְתָבִית לְאַלּוּפֵיהוֹן\",0,0],[4,143,24,13,\"וְקָם משֶׁה וִיהוֹשֻׁעַ מְשׁוּמְשָׁנֵיהּ וּסְלֵיק משֶׁה לְטַוְורָא דְאִיתְגְּלֵי עֲלוֹי יְקַר שְׁכִינְתָּא דַיְיָ\",0,0],[4,143,24,14,\"וּלְחַכִּימַיָא אָמַר אַמְתִּינוּן לָנָא הָכָא עַד זְמַן דִּנְתוֹב לְוַותְכוֹן וְהָא אַהֲרן וְחוּר עִמְכוֹן מַאן דְּאִית לֵיהּ עֵיסַק דִּינָא יִתְקְרֵב לְוַותְהוֹן\",0,0],[4,143,24,15,\"וּסְלֵיק משֶׁה לְטַוְורָא וַחֲפָא עֲנַן יְקָרָא יַת טַוְורָא\",0,0],[4,143,24,16,\"וּשְׁרָא אִיקַר שְׁכִינְתָּא דַיְיָ עַל טַוְורָא דְסִינַי וַחֲפָהִי עֲנַן יְקָרָא שִׁיתָּא יוֹמִין וּקְרָא לְמשֶׁה בְּיוֹמָא שְׁבִיעָאָה מִגּוֹ עֲנָנָא\",0,0],[4,143,24,17,\"וְחֵיזוּ זִיו יִקְרָא דַיְיָ הֵי כְאֵשָׁא בָעֲרָא וְזִיקוּקֵי אֵשָׁא אָכְלָא אֵשָׁא וַהֲווֹ חָמָן וּתְמֵהִין בְּנֵי יִשְרָאֵל\",0,0],[4,143,24,18,\"וְעָאל משֶׁה בְּגוֹ עֲנָנָא וּסְלֵיק לְטַוְורָא וַהֲוָה משֶׁה בְּטַוְורָא אַלִיף פִּתְגָמֵי אוֹרַיְיתָא מִן פּוּם קוּדְשָׁא יְהֵי שְׁמֵיהּ מְשַׁבַּח אַרְבְּעִין יְמָמִין וְאַרְבָּעִין לֵילְוָון\",0,0],[4,143,25,1,\"וידבר וּמַלֵּיל יְיָ עִם משֶׁה לְמֵימָר\",0,0],[4,143,25,2,\"מַלֵּיל עִם בְּנֵי יִשְרָאֵל וְיִסְבוּן קֳדָמַי אַפְרְשׁוּתָא מִן כָּל דְּיִתְרְעֵי לִבֵּיהּ וְלָא בְּאַלְמוּתָא תִסְבוּן יַת אַפְרָשׁוּתִי\",0,0],[4,143,25,3,\"וְדָא אַפְרָשׁוּתָא דְתִסְבוּן מִנְהוֹן דַּהֲבָא וְכַסְפָּא וּנְחָשָׁא\",0,0],[4,143,25,4,\"וְתִכְלָא וְאַרְגְּוָונָא וּצְבַא זְהוֹרֵי וּבוּץ וּמֵעַזֵּי\",0,0],[4,143,25,5,\"וּמַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וּמַשְׁכֵי דְסַסְגוֹנָא וְקַיְסִין דְּשִׁיטִין\",0,0],[4,143,25,6,\"וּמְשַׁח זֵיתָא לְאַנְהָרָא וּבוּסְמַיָא לְפִיטוּמָא דִמְשַׁח רְבוּתָא וּלְפִיטוּמָא דִקְטוֹרֶת בּוּסְמַיָא\",0,0],[4,143,25,7,\"מַרְגַלְיַין דְּבוּרְלִין הִינוּן מַרְגַלְיַין דְּאַשְׁלֵמוּתָא לְמַכְנְשָׁא וּלְמִקְבְּעָא בְּאֵיפוֹדָא וּבְחוּשְׁנָא\",0,0],[4,143,25,8,\"וְיַעַבְדוּן לִשְׁמִי מַקְדְּשָׁא וְאַשְׁרֵי שְׁכִינְתִּי בֵּינֵיהוֹן\",0,0],[4,143,25,9,\"כְּכָל מַה דַּאֲנָא מַחֲמֵי יָתָךְ יַת צוּרַת מַשְׁכְּנָא וְיַת צוּרַת כָּל מָנוֹי וְהֵיכְדֵין תַּעַבְדוּן\",0,0],[4,143,25,10,\"וִיעַבְּדוּן אֲרוֹנָא דְקַיְסֵי שִׁיטָא תַרְתֵּין אַמִין וּפַלְגָא אוּרְכֵּיהּ וְאַמְתָא וּפַלְגָא פּוּתְיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵיהּ\",0,0],[4,143,25,11,\"וְתַחְפֵּי יָתֵיהּ דְּהַב דְּכֵי מִגֵּיו וּמִבָּרָא תַחֲפִינֵיהּ וְתַעֲבֵיד עֲלוֹי דֵּיר דִּדְהַב חֲזוֹר חֲזוֹר\",0,0],[4,143,25,12,\"וְתַתִּיךְ לֵיהּ אַרְבַּע עִזְקַן דִּדְהַב וְתִתֵּן עַל אַרְבַּע אִיזְתַוְודוֹי וְתַרְתֵּין עִזְקַן עַל צִיטְרֵיהּ חָד וְתַרְתֵּין עִיזְקַן עַל צִיטְרֵיהּ תִּנְיָינָא\",0,0],[4,143,25,13,\"וְתַעֲבֵיד אֲרִיחֵי דְקֵיסֵי שִׁיטָא וְתַחֲפֵי יַתְהוֹן דַּהֲבָא\",0,0],[4,143,25,14,\"וּתְהַנְעַל יַת אֲרִיחַיָא בְּעִזְקָתָא עַל צִיטְרֵיהּ אֲרוֹנָא לְמֵיטוֹל יַת אֲרוֹנָא בְּהוֹן\",0,0],[4,143,25,15,\"בְּעִיזְקָתָא דַאֲרוֹנָא יְהוֹן מַחְתָן אֲרִיחַיָא לָא יַעֲדוּן מִנֵּיהּ\",0,0],[4,143,25,16,\"וְתִתֵּן בְּגוֹ אֲרוֹנָא יַת סַהֲדוּתָא דְאֵיתֵּן לָךְ\",0,0],[4,143,25,17,\"וְתַעֲבֵיד כַּפּוּרְתָּא דִדְהַב דְּכֵי תַרְתֵּין אַמִּין וּפַלְגָא אוּרְכָּהּ וְאַמְתָא וּפַלְגָא פּוּתְיָהּ וְסוּמְכָהּ יְהֵא פּוּשְׁכָה\",0,0],[4,143,25,18,\"וְתַעֲבֵיד תְּרֵין כְּרוּבִין דִּדְהַב דְּכֵי נְגִיד תַּעֲבֵיד יַתְהוֹי מִתְּרֵין צִיטְרֵי כְפּוּרְתָּא\",0,0],[4,143,25,19,\"וְעַבֵיד כְּרוּבָא חָד מִצִּיטְרָא מִכָּא וּכְרוּבָא חָד מִצִּיטְרָא מִכָּא מִן כַּפּוּרְתָּא תַעֲבֵיד יַת כְּרוּבַיָא מִתְּרֵין צִיטְרוֹי\",0,0],[4,143,25,20,\"וִיהוֹן כְּרוּבַיָא פְּרִיסַן גַּדְפֵיהוֹן לְעֵילָא כָּל קְבֵיל רֵישֵׁיהוֹם מְטַלְלִין בְּגַדְפֵיהוֹן עַל כַּפּוּרְתָּא וְאַפֵּיהוֹן חָד כָּל קְבֵיל חַד לִקְבֵיל כַּפּוּרְתָּא יְהוֹן אַפֵּי כְרוּבַיָא\",0,0],[4,143,25,21,\"וְתִתֵּן יַת כַּפּוּרְתָּא עַל אֲרוֹנָא מִלְעֵילָא וּבְגוֹ אֲרוֹנָא תִּתֵּן יַת לוּחֵי סַהֲדוּתָא דְאֵיתֵּן לָךְ\",0,0],[4,143,25,22,\"וְאֵיזַמֵן מֵימְרִי לָךְ תַּמָּן וְאֵימַלֵּיל עִמָּךְ מֵעִילַוֵי כַּפּוּרְתָּא מִבֵּין תְּרֵין כְּרוּבַיָא דְעַל אֲרוֹנָא דְסַהֲדוּתָא יַת כָּל מַה דַּאֲפַקֵּיד יָתָךְ לְוַת בְּנֵי יִשְרָאֵל\",0,0],[4,143,25,23,\"וְתַעֲבֵיד פְּתוֹרָא דְקֵיסֵי שִׁיטִין תַּרְתֵּין אַמִּין אוּרְכֵּיהּ וְאַמְתָא פּוּתְיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵיהּ\",0,0],[4,143,25,24,\"וְתַחְפֵי יָתֵיהּ דְּהַב דְּכֵי וְתַעֲבֵיד לֵיהּ דֵּיר דִּדְהַב חֲזוֹר חֲזוֹר\",0,0],[4,143,25,25,\"וְתַעֲבֵיד לֵיהּ גַּפוּף רוּמָא פּוּשְׁכָא חֲזוֹר חֲזוֹר וְתַעֲבֵיד דֵּיר דִּדְהַב לְגִיפוּפֵיהּ חֲזוֹר חֲזוֹר\",0,0],[4,143,25,26,\"וְתַעֲבֵיד אַרְבַּע עִזְקַן דִּדְהַב וְתִתֵּן יַת עִזְקָתָא עַל אַרְבַּע זִיוְיַין דִּי לְאַרְבַּע רִיגְלוֹי\",0,0],[4,143,25,27,\"כָּל קְבֵיל גָּפוּף תֶּהֶוְיַין עִיזְקָתָא לְאַתְרָא לַאֲרִיחַיָיא לְמִיטוֹל יַת פָּתוֹרָא\",0,0],[4,143,25,28,\"וְתַעֲבֵיד יַת אֲרִיחַיָיא דְקֵיסֵי שִׁיטָא וְתַחְפֵי יַתְהוֹן דַּהֲבָא וִיהוֹן נַטְלִין בְּהוֹן יַת פְּתוֹרָא\",0,0],[4,143,25,29,\"וְתַעֲבֵיד פַּיַילְתּוֹי וּבָזִיכוֹי וְקַשְוָותוֹי וּמְכִילְתוֹי דִי יִשְׁתַּמֵּשׁ וְיִתְרוֹק בְּהוֹן דִּדְהַב דְּכֵי תַעֲבֵיד יַתְהוֹן\",0,0],[4,143,25,30,\"וּתְסַדֵּר עַל פְּתוֹרָא לַחֲמָא גַוָואָה קֳדָמַי תְּדִירָא\",0,0],[4,143,25,31,\"וְתַעֲבֵיד מְנַרְתָּא דִדְהַב דְּכֵי נְגִיד תַּעֲבֵיד מְנַרְתָּא בָּסִיס דִּידָהּ וּקְנָאָה כַּלִידָהָא וְחִיזוּרְיָיהּ וְשׁוֹשַׁנְיָיהּ מִינָהּ יְהוֹן\",0,0],[4,143,25,32,\"וְשִׁיתָּא קְנִין נַפְקִין מִצִּיטְרָהָא תְּלָתָא קְנֵי מְנַרְתָּא מִצִּטְרָה חָד וּתְלָתָא קְנֵי מְנַרְתָּא מִצִּיטְרָה תִּנְיָינָא\",0,0],[4,143,25,33,\"תְּלָתָא כַּלִּידִין מְשַׁקְעִין בְּצִיּוּרֵיהוֹן בְּקַנְיָא חָד חֵיזוּר וְשׁוֹשַׁן וּתְלָתָא כַּלִּידִין מְשַׁקְעִין בְּצִיּוּרֵיהוֹן בְּקַנְיָא חָד חֵיזוּר וְשׁוֹשַׁן הֵיכְדֵין לְשִׁיתָּא קְנִין דְּנַפְקִין מִן מְנַרְתָּא\",0,0],[4,143,25,34,\"וּבִמְנַרְתָּא אַרְבְּעָה כַּלִּידִין מְשַׁקְעִין בְּצִיּוּרֵיהוֹן חִיזוּרְיָהָא וְשׁוֹשַׁנְיָהָא\",0,0],[4,143,25,35,\"וְחֵיזוֹר תְּחוֹת תְּרֵין קְנִין דְּמִינָהּ וְחֵיזוּר תְּחוֹת תְּרֵין קְנִין דְמִינָהּ וְחֵיזוּר תְּחוֹת תְּרֵין קְנִין דְּמִינָהּ לְשִׁיתָּא קְנִין דְּנַפְקִין מִן מְנַרְתָּא\",0,0],[4,143,25,36,\"חֵיזוּרֵיהוֹן וּקְנֵיהוֹן מִינָהּ יְהוֹן כּוּלָהּ נְגִידָא חֲדָא דִדְהַב דְּכֵי\",0,0],[4,143,25,37,\"וְתַעֲבֵיד יַת בּוֹצִינָהָא שַׁבְעָא וּדְלֵיק כַּהֲנָא דְמִתְמַנֵּי יַת בּוֹצִינָהָא וִיהוֹן מְנַהֲרִין כָּל קְבֵיל אַפָּהָא\",0,0],[4,143,25,38,\"וּמַלְקָטַיָיהָא וּמַחְתְּיָיתָא דִדְהַב דְּכֵי\",0,0],[4,143,25,39,\"קַנְטְנַר דִּדְהַב דְּכֵי יַעֲבֵיד יָתָהּ יַת כָּל מָנַיָיא דִידָהּ הָאִלֵּין\",0,0],[4,143,25,40,\"וַחֲמֵי וַעֲבַד בְּצִיּוּרֵיהוֹן דְּאַנְתְּ מִתְחֲמֵי בְּטַוְורָא\",0,0],[4,143,26,1,\"וְיַת מַשְׁכְּנָא תַעֲבֵיד עֲשַר יְרִיעָן דְּבוּץ שְׁזִיר וְתִכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי צִיּוּר כְּרוּבִין עוֹבֵד אוֹמַן תַּעֲבֵיד יַתְהוֹם\",0,0],[4,143,26,2,\"אוּרְכָּא דִירִיעֲתָא חֲדָא עַשְרִין וְתַמְנֵי אַמִּין וּפוּתְיָה אַרְבַּע אַמִּין דִּירִיעֲתָא חֲדָא מִשְׁחֲתָא חֲדָא לְכָל יְרִיעֲתָא\",0,0],[4,143,26,3,\"חֲמֵשׁ יְרִיעַן תֶּהֶוְיַן מְלַפְּפָן חֲדָא עִם חֲדָא וַחֲמֵשׁ יְרִיעַן חוֹרַנְיָין מְלַפְּפָן חֲדָא עִם חֲדָא\",0,0],[4,143,26,4,\"וְתַעֲבֵיד עֲנוּבִין דְּתִיכְלָא עַל אִימְרָא דִירִיעֲתָא חֲדָא מִן צִיטְרֵיהּ בְּבֵית לִיפוּפָא וְכֵן תַּעֲבֵיד בְּאִימְרָא דִירִיעֲתָא בְּבֵית לִיפוּפָא תִּנְיָין\",0,0],[4,143,26,5,\"חַמְשִׁין עֲנוּבִין תַּעֲבֵיד בִּירִיעֲתָא חֲדָא וְחַמְשִׁין עֲנוּבִין תַּעֲבֵיד בְּצִיטְרָא דִירִיעֲתָא דִּבְּבֵית לִיפוּפָא תִנְיָינָא מְכַוְונַן עֲנוּבַיָא חָד כָּל קְבֵיל חָד\",0,0],[4,143,26,6,\"וְתַעֲבֵיד חַמְשִׁין פּוּרְפִין דִּדְהַב וּתְלַפֵיף יַת יְרִיעֲתָא חֲדָא עִם חֲדָא בְּפוּרְפַּיָיא וְיִתְחַבֵּר מַשְׁכְּנָא לְמֶהֱוֵי חָד\",0,0],[4,143,26,7,\"וְתַעֲבֵיד יְרִיעַן דְּמֵעִיזֵי לְמִפְרַס עַל מַשְׁכְּנָא חַדְסְרִי יְרִיעַן תַּעֲבֵיד יַתְהֵין\",0,0],[4,143,26,8,\"אוּרְכָּא דִירִיעֲתָא חֲדָא תְּלָתִין אַמִּין וּפוּתְיָא אַרְבַּע אַמִּין דִּירִיעֲתָא חֲדָא מִשְׁחֲתָא חֲדָא לְחַדְסְרִי יְרִיעַן\",0,0],[4,143,26,9,\"וּתְלָפִיף יַת חֲמֵשׁ יְרִיעַן לְחוֹד כָּל קְבֵיל חַמְשָׁא סִפְרֵי אוֹרַיְיתָא וְיַת שִׁית יְרִיעַן לְחוֹד כָּל קְבֵיל שִׁית סִדְרֵי מַתְנִיתָּא וְתֵיעוֹף יַת יְרִיעֲתָא שָׁתִיתֵיתָא כָּל קְבֵיל אַפֵּי מַשְׁכְּנָא\",0,0],[4,143,26,10,\"וְתַעֲבֵיד חַמְשִׁין עֲנוּבִין עַל אִימְרַת דִּירִיעֲתָא חֲדָא מִצִּיטְרָא בְּבֵית לִיפּוּפָא וְחַמְשִׁין עֲנוּבִין עַל אִימְרָא דִירִיעֲתָא בְּבֵית לִיפּוּפָא תִּנְיָינָא\",0,0],[4,143,26,11,\"וְתַעֲבֵיד פּוּרְפִּין דִּנְחַשׁ חַמְשִׁין וְתֵעוּל יַת פּוּרְפַּיָא בַּעֲנוּבַיָיא וּתְלַפֵף יַת מַשְׁכְּנָא וִיהֵי חָד\",0,0],[4,143,26,12,\"וְשִׁיפּוּעַ מוֹתָרָא בִּירִיעוֹת מַשְׁכְּנָא פַּלְגוּת יְרִיעָתָא דִיתֵירָא תִּשְׁפַּע עַל אֲחוֹרֵי מַשְׁכְּנָא\",0,0],[4,143,26,13,\"וְאַמְתָא מִיכָּא וְאַמְתָא מִיכָּא בִּדְיַתִּיר בְּאוֹרֶךְ יְרִיעֲתָא דְמַשְׁכְּנָא יְהֵי מְשֻׁפַּע עַל צִיטְרֵי מַשְׁכְּנָא מִיכָּא וּמִיכָּא לְכַסִּיּוּתֵיהּ\",0,0],[4,143,26,14,\"וְתַעֲבֵיד חוֹפָאָה לְמַשְׁכְּנָא מוֹשְׁכֵי דְדִכְרֵי מִסַמְקֵי וְחוֹפָאָה דְמַשְׁכֵי סַסְגְּוָונָא מִלְעֵילָא\",0,0],[4,143,26,15,\"וְתַעֲבֵיד יַת לוּחַיָא לְמַשְׁכְּנָא דְקֵיסֵי שִׁיטָא קַיָמִין הֵי כְּאוֹרַח נְצִיבְהוֹן\",0,0],[4,143,26,16,\"עֲשַר אַמִּין אוּרְכָּא דְלוּחָא וְאַמְתָא וּפַלְגָא דְאַמְתָא פּוּתְיָא דְלוּחָא חָד\",0,0],[4,143,26,17,\"תַּרְתֵּין צִירִין לְלוּחָא חָד מְכַוְונִין צְטַר חָד בְּגוֹ חַד הֵיכְדֵין תַּעֲבֵיד לְכָל לוּחֵי מַשְׁכְּנָא\",0,0],[4,143,26,18,\"וְתַעֲבֵיד יַת לוּחַיָא לְמַשְׁכְּנָא עַשְרִין לוּחִין לְרוּחַ עִיבַר דָּרוֹמָא\",0,0],[4,143,26,19,\"וְאַרְבְּעִין חוֹמְרִין דִּכְסָף תַּעֲבֵיד תְּחוֹת עַשְרִין לוּחִין תְּרֵין חוֹמְרִין תְּחוֹת לוּחָא חָד לִתְרֵין צִירוֹי וּתְרֵין חוֹמְרִין תְּחוֹת לוּחָא חָד לִתְרֵין צִירוֹי\",0,0],[4,143,26,20,\"וְלִסְטָר מַשְׁכְּנָא תִנְיָנָא לְרוּחַ צִיפוּנָא עֶשְרִין לוּחִין\",0,0],[4,143,26,21,\"וְאַרְבְּעִין חוֹמְרֵיהוֹן דִּכְסַף תְּרֵין חוֹמְרִין תְּחוֹת לוּחָא חָד וּתְרֵין חוֹמְרִין תְּחוֹת לוּחָא חָד\",0,0],[4,143,26,22,\"וְלִסְיָיפֵי מַשְׁכְּנָא מַעַרְבָאָה תַּעֲבֵיד שִׁיתָּא לוּחִין\",0,0],[4,143,26,23,\"וּתְרֵין לוּחִין תַּעֲבֵיד לְזִוְיַית מַשְׁכְּנָא בְּסוֹפֵיהוֹן\",0,0],[4,143,26,24,\"וִיהוֹן מִזַוְוגִין מִלְּרַע וְכַחֲדָא יְהוֹן מְזַוְוגִין עַל רֵישֵׁיהוֹן בְּעִזְקָתָא חֲדָא הֵיכְדֵין יְהֵי לְתַרְוֵיהוֹן לִתְּרֵין זִיוְויָן יְהוֹן\",0,0],[4,143,26,25,\"וִיהוֹן תְּמַנְיָא לוּחִין וְחוֹמְרֵיהוֹן דִּכְסַף שִׁיתְסְרֵי חוֹמְרִין תְּרֵין חוֹמְרִין תְּחוֹת לוּחָא חָד וּתְרֵין חוֹמְרִין תְּחוֹת לוּחָא חָד\",0,0],[4,143,26,26,\"וְתַעֲבֵיד נַגְרִין דְּקֵיסֵי שִׁיטָא חַמְשָׁא לְלוּחֵי צְטַר מַשְׁכְּנָא חָד\",0,0],[4,143,26,27,\"וְחַמְשָׁא נַגְרִין לְלוּחֵי צְטַר מַשְׁכְּנָא תִּנְיָנָא וְחַמְשָׁא נַגְרִין לְלוּחֵי צְטַר מַשְׁכְּנָא לְסוֹפֵיהוֹן מַעֲרָבָא\",0,0],[4,143,26,28,\"וְנַגְרָא מְצִיעָאָה בְּגוֹ לוּחַיָיא מְשַׁלְבִישׁ מִן סְיָיפֵי לִסְיָיפֵי מִן אִילָנָא דִנְצִיב אַבְרָהָם בִּבְאֵרָה דְשָׁבַע וְכַד עֲבָרוּ יִשְרָאֵל יַת יַמָּא קְטָעוּ מַלְאָכַיָא יַת אִילָנָא וְטַלְקוּהוּ לְיַמָא וַהֲוַת טָפֵי עַל אַנְפֵּי מַיָא וַהֲוָה מַלְאָכַיָא מַכְרִיז וַאֲמַר דֵּין הוּא אִילָנָא דִנְצִיב אַבְרָהָם בְּבֵירָא דְשָׁבַע וְצַלִּי תַמָּן בְּשׁוּם מֵימְרָא דַיְיָ וְנַסְבוֹהִי בְּנֵי יִשְרָאֵל וַעֲבָדוּ מִנֵיהּ נַגְרָא מְצִיעָאָה אוּרְכֵּיהּ שׁוּבְעִין אַמִּין וּפְרִישָׁן מִתְעַבְדָן בֵּיהּ דְּכַד הֲווֹ מוֹקְמִין יַת מַשְׁכְּנָא הֲוָה מִתְגַּלְגֵּל הֵי כְּעַכְנָא חֲזוֹר חֲזוֹר מִלְגֵיו לְלוּחֵי מַשְׁכְּנָא וְכַד הֲוָה מִתְפָּרֵק הֲוָה פַּשִׁיט הֵי כְּחוּטְרָא\",0,0],[4,143,26,29,\"וְיַת לוּחַיָא תַחֲפֵי דַהֲבָא וְיַת עִזְקַתְהוֹן תַּעֲבֵיד דַהֲבָא אַתְרָא לְנַגְרִין וְתַחֲפֵי יַת נַגְרַיָא דַהֲבָא\",0,0],[4,143,26,30,\"וְתָקִים יַת מַשְׁכְּנָא כְּהִילְכָתָא דְאִתְחֲמִיתָא בְּטַוְורָא\",0,0],[4,143,26,31,\"וְתַעֲבֵיד פַּרְגוֹדָא דְתִכְלָא וְאַרְגְּוָונָא וּצְבַא זְהוֹרֵי וּבוּץ שְׁזִיר עוֹבַד אוּמַן יַעֲבֵיד יָתָהּ צוּרִין כְּרוּבִין\",0,0],[4,143,26,32,\"וּתְסַדַּר יָתָהּ עַל אַרְבָּעָה עַמּוּדֵי שִׁיטָא מְחַפִּין דַּהֲבָא וָוֵיהוֹן דַּהֲבָא עַל אַרְבְּעָה חוֹמְרִין דִּכְסַף\",0,0],[4,143,26,33,\"וְתִתֵּן יַת פַּרְגוֹדָא תְּחוֹת פּוּרְפַּיָא וְתֵיעוֹל לְתַמָּן מִלְגֵיו לְפַרְגוֹדָא יַת אֲרוֹנָא דְסַהֲדוּתָא וְתַפְרֵישׁ פַּרְגוֹדָא לְכוֹן בֵּינֵי קוּדְשָׁא וּבֵינֵי קוֹדֶשׁ קוּדְשָׁא\",0,0],[4,143,26,34,\"וְתִתֵּן יַת כַּפּוּרְתָּא בַּהֲדֵי כְּרוּבַיָא דְּנַפְקִין נְגִיד מִינָהּ בַּקּדֶשׁ קוּדְשַׁיָא\",0,0],[4,143,26,35,\"וּתְשַׁוֵּי יַת פָּתוֹרָא מִבָּרָא לְפַרְגוֹדָא וְיַת מְנַרְתָּא כָּל קְבֵיל פָּתוֹרָא עַל סְטַר מַשְׁכְּנָא דָרוֹמָא וּפְתוֹרָא תְּסַדֵּר עַל סְטַר צִיפוּנָא\",0,0],[4,143,26,36,\"וְתַעֲבֵיד פְּרָסָא לִתְרַע מַשְׁכְּנָא תִיכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי וּבוּץ שְׁזִיר עוֹבַד צִיּוּר מַחְטָא\",0,0],[4,143,26,37,\"וְתַעֲבֵיד לִפְרָסָא חַמְשָׁא עַמּוּדֵי שִׁיטָא וְתַחֲפֵי יַתְהוֹן דַּהֲבָא וָוֵיהוֹן דַּהֲבָא וְתַתִּיךְ לְהוֹן חַמְשָׁא חוֹמְרִין דִּנְחָשָׁא\",0,0],[4,143,27,1,\"וְתַעֲבֵיד יַת מַדְבְּחָא דְקֵיסֵי שִׁיטָא חָמֵשׁ אַמִּין אוּרְכָּא וְחָמֵשׁ אַמִּין פּוּתְיָא מְרַבַּע יְהֵי מַדְבְּחָא וּתְלַת אַמִּין רוּמֵיהּ\",0,0],[4,143,27,2,\"וְתַעֲבֵיד קַרְנוֹהִי עַל אַרְבַּע זִיוְיָתֵיהּ מִנֵיהּ יֶהֶוְיַן קַרְנוֹי זְקִיפִין לְעֵיל וְתַחְפֵי יָתֵיהּ נְחָשָׁא\",0,0],[4,143,27,3,\"וְתַעֲבֵיד דּוּדְוָתֵיהּ לְמֵירְדָדָא יָתֵיהּ וּמִגְרִפַתֵּיהּ וּמִזִירִקוֹי וּמְשִׁילְיָיתֵיהּ וּמַחְתְּיָיתֵיהּ כָּל מָנוֹי תַּעֲבֵיד נְחָשָׁא\",0,0],[4,143,27,4,\"וְתַעֲבֵיד לֵיהּ קַנְקַל עוֹבַד מְצַרְתָּא דְנַחָשָׁא וְתַעֲבֵיד עַל מְצַרְתָּא אַרְבַּע עִזְקַן דִּנְחָשָׁא עַל אַרְבַּע צִיטְרוֹי\",0,0],[4,143,27,5,\"וְתִיתֵּן יָתָהּ תְּחוֹת סוֹבְבֵי מַדְבְּחָא מִלְרַע וּתְהֵי מְצַרְתָּא עַד פַּלְגוּת מַדְבְּחָא וְאִין נָפִיל גּוֹמָא אוֹ גוּמְרָא דְאֵשָׁא מֵעִילַוֵי מַדְבְּחָא נָפִיל עִילַוֵי קַנְקַל וְלָא יִתְמְטֵי לְאַרְעָא וְנַסְבִין יָתֵיהּ כַהֲנַיָא מֵעִילַוֵי קַנְקַל וּמְהַדְרִין יָתֵיהּ עַל מַדְבְּחָא\",0,0],[4,143,27,6,\"וְתַעֲבֵיד אֲרִיחִין דְּקֵיסֵי שִׁיטָא וְתַחְפֵּי יַתְהוֹן נְחָשָׁא\",0,0],[4,143,27,7,\"וִיהַנְעַל יַת אֲרִיחוֹי בְּעִזְקָתָא וִיהוֹן אֲרִיחַיָא עַל תְּרֵין צִטְרֵי מַדְבְּחָא בְּמֵיטַל מַדְבְּחָא\",0,0],[4,143,27,8,\"חַלִיל לוּחִין מְלֵי עַפְרָא תַעֲבֵיד יָתֵיהּ הֵיכְמָא דְאַחְמִיתָךְ בְּטַוְורָא הֵיכְדֵין יַעַבְדוּן\",0,0],[4,143,27,9,\"וְתַעֲבֵיד יַת דָּרַת מַשְׁכְּנָא לְרוּחַ עִיבַר דָּרוֹמָא וִילַוָון לְדַרְתָּא דְּבוּץ שְׁזִיר מְאָה אַמִּין אוּרְכָּא לְרוּחַ חֲדָא\",0,0],[4,143,27,10,\"וְעַמּוּדוֹי עַשְרִין וְחוּמְרֵיהוֹן עַשְרִין דִּנְחָשָׁא וָוֵי עַמּוּדַיָא וְכִיבּוּשֵׁיהוֹן כְּסָף\",0,0],[4,143,27,11,\"וְהֵיכְדֵין לְרוּחַ צִפוּנָא בְּאוּרְכָּא וִילַוָון מְאָה אוּרְכָּא וְעַמּוּדֵיהוֹן עַשְרִין וְחוּמְרֵיהוֹן עַשְרִין דִּנְחָשָׁא וָוֵי עַמּוּדַיָא וְכִיבּוּשֵׁיהוֹן כְּסָף\",0,0],[4,143,27,12,\"וּפוּתְיָא דְדַרְתָּא לְרוּחַ מַעַרְבָא וִילַוָון חַמְשִׁין אַמִּין עַמּוּדֵיהוֹן עַשְרָא וְחוּמְרֵיהוֹן עַשְרָא\",0,0],[4,143,27,13,\"וּפוּתְיָא דְדַרְתָּא לְרוּחַ קִידוּמָא מַדִּינְחָא חַמְשִׁין אַמִּין\",0,0],[4,143,27,14,\"וַחֲמֵיסְרֵי אַמִּין וִילַוָון לְעִיבְרָא עַמּוּדֵיהוֹן תְּלָתָא וְחוּמְרֵיהוֹן תְּלָתָא\",0,0],[4,143,27,15,\"וּלְעִיבְרָא תִּנְיָנָא חֲמֵשׁ עַסְרֵי סְרָדִין עַמּוּדֵיהוֹן תְּלָתָא וְחוּמְרֵיהוֹן תְּלָתָא\",0,0],[4,143,27,16,\"וְלִתְרַע דַּרְתָּא פְרָסָא עַשְרִין אַמִּין דְּתִיכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי וּבוּץ שְׁזִיר עוֹבַד צִיּוּר מַחְטָא עַמּוּדֵיהוֹן אַרְבָּעָה וְחוּמְרֵיהוֹן אַרְבָּעָה\",0,0],[4,143,27,17,\"כָּל עַמּוּדֵי דַרְתָּא חֲזוֹר חֲזוֹר מְכֻבָּשִׁין כְּסַף וָוֵיהוֹן כְּסַף וְחוּמְרֵיהוֹן דִּנְחָשָׁא\",0,0],[4,143,27,18,\"אוּרְכָּא דְדַרְתָּא מְאָה אַמִּין וּפוּתְיָא חַמְשִׁין לְמַעַרְבָא וְחַמְשִׁין לְמַדִינְחָא וְרוּמָא חֲמֵשׁ אַמִּין דְּבוּץ שְׁזִיר וְחוּמְרֵיהוֹן דִּנְחָשָׁא\",0,0],[4,143,27,19,\"לְכָל מָאנֵי מַשְׁכְּנָא בְּכָל פּוּלְחָנֵיהּ וְכָל מִתְחוֹי וְכָל מִתְחֵי דַרְתָּא חֲזוֹר חֲזוֹר דִּנְחָשָׁא\",0,0],[4,143,27,20,\"ואתה וְאַנְתְּ תְּפַקֵיד יַת בְּנֵי יִשְרָאֵל וְיִסְבוּן לָךְ מִישְׁחָא דְזֵיתָא דַכְיָא כְּתִישָׁא לְאַנְהוֹרֵי לְאַדְלָקָא בּוֹצִינַיָא תְּדִירָא\",0,0],[4,143,27,21,\"בְּמַשְׁכַּן זִימְנָא מִבָּרָא לְפַרְגוֹדָא דְעַל סַהֲדוּתָא יְסַדֵּר יָתֵיהּ אַהֲרן וּבְנוֹי מִן רַמְשָׁא עַד צַפְרָא קֳדָם יְיָ קְיַים עֲלָם לְדָרֵיהוֹן מִן בְּנֵי יִשְרָאֵל\",0,0],[4,143,28,1,\"וְאַנְתְּ קְרַב לְוָותָךְ יַת אַהֲרן אָחוּךְ וְיַת בְּנוֹי עִמֵּיהּ מִגּוֹ בְּנֵי יִשְרָאֵל לְשַׁמָּשָׁא קֳדָמַי אַהֲרן נָדָב וַאֲבִיהוּא אֶלְעָזָר וְאִיתָמָר בְּנוֹי דְאַהֲרן\",0,0],[4,143,28,2,\"וְתַעֲבֵיד לְבוּשָׁא דְקוּדְשָׁא לְאַהֲרן אָחוּךְ לִיְקַר וּלְתוּשְׁבְּחָא\",0,0],[4,143,28,3,\"וְאַנְתְּ תְּמַלֵּיל עִם כָּל חַכִּימֵי לִבָּא דְאַשְׁלֵימִית עִמְהוֹן רוּחָא דְחָכְמְתָא וְעָבָדוּ יַת לְבוּשֵׁי אַהֲרן לְקַדְשׁוּתֵיהּ לְשַׁמָּשָׁא קֳדָמַי\",0,0],[4,143,28,4,\"וְאִלֵּין לְבוּשַׁיָא דְיַעַבְדוּן חוּשְׁנָא וְאֵיפוֹדָא וּמְעִילָא וְכִיתּוּנוּן מְרַמְצִין מַצִינְפַן וְקִימוֹרִין וְיַעַבְדוּן לְבוּשֵׁי קוּדְשָׁא לְאַהֲרן אָחוּךְ וְלִבְנוֹי לְשַׁמָּשָׁא קֳדָמַי\",0,0],[4,143,28,5,\"וְהִינוּן יִסְבוּן מִן מָמוֹנְהוֹן יַת דַּהֲבָא וְיַת תִּכְלָא וְיַת אַרְגְּוָונָא וְיַת צְבַע זְהוֹרֵי וְיַת בּוּצָא\",0,0],[4,143,28,6,\"וְיַעַבְדוּן יַת אֵיפוֹדָא תִּכְלָא וְאַרְגְּוָונָא צְבַע זְהוֹרֵי וּבוּץ שְׁזִיר עוֹבַד אוּמָן\",0,0],[4,143,28,7,\"תַּרְתֵּין כַּתְפִין מְלַפְפִין יֶהֱוָן לֵיהּ לִתְרֵין סִטְרוֹי וְיִתְלָפֵף\",0,0],[4,143,28,8,\"וְהֶמְיַן טִיכוּתֵיהּ דְּעָלוֹי הֵי כְּעוּבְדֵיהּ מִנֵיהּ יְהֵי דַהֲבָא תִּיכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי וּבוּץ שְׁזִיר\",0,0],[4,143,28,9,\"וְתִיסַב יַת תַּרְתֵּין מַרְגַלְיַין דְּבוּרְלָא וְתִגְלוֹף עֲלֵיהוֹן שְׁמָהַת בְּנֵי יִשְרָאֵל\",0,0],[4,143,28,10,\"שִׁיתָּא מִן קְצַת שְׁמָהַתְהוֹן עַל מַרְגַלְיָיא חֲדָא וְיַת שְׁמָהַת שִׁיתָּא דְמִשְׁתַּיְירִין עַל מַרְגְּלִיתָא תִּנְיָתָא מְסַדְרִין הֵי כְּיַלְדוּתְהוֹן\",0,0],[4,143,28,11,\"עוֹבַד אוּמַן יֶהֶוְיַין מַרְגְּלַיְיתָא גְּלוּף חָקִיק וּמְפָרֵשׁ הֵי כִּגְלוֹף דְּעִזְקָא תִּגְלוֹף יַת תַּרְתֵּין מַרְגְּלִיָיתָא עַל שְׁמָהַת בְּנֵי יִשְרָאֵל מַקְפַן בְּאוּמַנְוַתְהוֹן מְרַמְצָן דִּדְהַב תַּעֲבֵיד יַתְהוֹן\",0,0],[4,143,28,12,\"וּתְסַדֵּר יַת תַּרְתֵּין מַרְגָלִיָתָא עַל כִּתְפֵי אֵפוֹדָא מַרְגַלְיַית מְדַכְרַן זְכוּתָא לִבְנֵי יִשְרָאֵל וְיִטּוֹל אַהֲרן יַת שְׁמָהַת בְּנֵי יִשְרָאֵל עַל תְּרֵין כַּתְפוֹי לְדוּכְרָנָא\",0,0],[4,143,28,13,\"וְתַעֲבֵיד מְרַמְצָן דִּדְהַב\",0,0],[4,143,28,14,\"וְתַרְתֵּין שִׁישְׁלַן דִּדְהַב דְּכֵי מְתַחְמָן תַּעֲבֵיד יַתְהוֹן עוֹבַד קְלִיעָא וְתִתֵּן יַת שׁוֹשִׁילְתָּא קְלִיעֲתָא עַל מְרַמְצָתָא\",0,0],[4,143,28,15,\"וְתַעֲבֵיד חוֹשֶׁן דִּינָא דְּבֵיהּ מְהוֹדַע דִּינֵיהוֹן דְּיִשְרָאֵל דְּאִתְכַּסֵּי מִן דַּיָינַיָא וְסִדְרֵי נַצְחַן קְרָבֵיהוֹן וּלְמִכַפְּרָא עַל דַּיָינַיָא עוֹבֵד אוּמַן הֵי עוֹבַד אֵפוֹדָא תַעַבְדִינֵיהּ דַּהֲבָא תִּיכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי וּבוּץ שְׁזִיר תַּעֲבֵיד יָתֵיהּ\",0,0],[4,143,28,16,\"מְרַבַּע יְהֵי עֵיף זַרְתָּא אוּרְכֵּיהּ וְזַרְתָּא פּוּתְיֵיהּ\",0,0],[4,143,28,17,\"וְתַשְׁלֵים בֵּיהּ אַשְׁלָמוּת דְּמַרְגַּלְיָין טַבָאָן אַרְבְּעָא סִדְרִין דִּמַרְגַלְיָין טַבָאָן כָּל קָבֵיל אַרְבַּע טְרִיגוֹנִין דְּעַלְמָא סִדְרָא קַדְמָאָה סִמוּקְתָּא יַרְקְתָא וּבַרְקְתָא סִדְרָא חָד וַעֲלֵיהוֹן חָקִיק וּמְפָרַשׁ שְׁמָהַת שִׁבְטַיָא רְאוּבֵן שִׁמְעוֹן וְלֵוִי\",0,0],[4,143,28,18,\"וְשׁוּם סִדְרָא תִּנְיָנָא אִיזְמוֹרַד וְסַפִּירִינוּן וְכַדְכוֹדֵי וַעֲלֵיהוֹן חָקִיק וּמְפָרַשׁ שְׁמָהַת תְּלָתָא שִׁבְטַיָא יְהוּדָה דָּן וְנַפְתָּלִי\",0,0],[4,143,28,19,\"וְשׁוּם סִדְרָא תְּלִיתָאָה קַנְכִּירִינוּן וְעַרְקִין וְעֵין עֵיגָל וַעֲלֵיהוֹן חָקִיק וּמְפָרַשׁ שְׁמָהַת תְּלָתָא שִׁבְטַיָא גָּד וְאָשֵׁר וְיִשָשׁכָר\",0,0],[4,143,28,20,\"וְשׁוּם סִדְרָא רְבִיעָאָה כְּרוּם יַמָא רַבָּא וּבִירְלֵיוַות חַלָא וּמַרְגְּנִיַית אַפַּנְטוּרִין וַעֲלֵיהוֹן חָקִיק וּמְפָרַשׁ שְׁמָהַת תְּלָתָא שִׁבְטַיָא זְבוּלוּן יוֹסֵף וּבִנְיָמִין מְשַׁקְעִין בִּדְהַב יְהוֹן בְּאַשְׁלָמוּתְהוֹן\",0,0],[4,143,28,21,\"וּמַרְגַּלְיָיתָא תֶהֶוְיָין מִתְנַסְבָן עַל שְׁמָהַת בְּנֵי יִשְרָאֵל הִינוּן תַּרְתֵּיסְרֵי עַל שְׁמָהַתְהוֹן גְּלִיף חָקִיק וּפָרַשׁ הֵי כִּגְלוֹף דְּעִזְקָא גְּבַר מַרְגָּלִיתֵיהּ עַל שְׁמֵיהּ תֶּהֶוְיַין לִתְרֵיסַר שִׁבְטִין\",0,0],[4,143,28,22,\"וְתַעֲבֵיד עַל חוּשְׁנָא שִׁישְׁלַן מְתַחְמָן עוֹבַד קְלִיעָא דִּדְהַב דְּכֵי\",0,0],[4,143,28,23,\"וְתַעֲבֵיד עַל חוּשְׁנָא תַּרְתֵּין עִזְקַן דִּדְהַב דְּכֵי וְתִתֵּן יַת תַּרְתֵּין עִזְקָתָא עַל תַּרְתֵּין סִטְרֵי חוּשְׁנָא\",0,0],[4,143,28,24,\"וְתִתֵּן יַת תַּרְתֵּין קְלִיעַן דִּדְהַב עַל תַּרְתֵּין עִיזְקָתָא בְּסִיטְרֵי חוּשְׁנָא\",0,0],[4,143,28,25,\"וְיַת תַּרְתֵּין קְלִיעַן דְּעַל תְּרֵין סִיטְרוֹי תִּתֵּן עַל תַּרְתֵּין מְרַמְצָתָא וְתִתֵּן עַל כִּתְפֵי אֵפוֹדָא כָּל קְבֵיל אַנְפּוֹי\",0,0],[4,143,28,26,\"וְתַעֲבֵיד תַּרְתֵּין עִזְקַן דִּדְהַב וְתִתֵּן יַתְהוֹן עַל תְּרֵין סִיטְרֵי חוּשְׁנָא עַל שִיפְמֵיהּ דִּלְעַבְרָא לְאֵפוֹדָא לְגֵיו\",0,0],[4,143,28,27,\"וְתַעֲבֵיד תַּרְתֵּין עִזְקַן דִּדְהַב וְתִתֵּן יַתְהוֹן עַל תְּרֵין כִּתְפֵי אֵפוֹדָא מִלְרַע מִקְבֵיל אַפּוֹי כָּל קְבֵיל בֵּית לוֹפֵי מֵעִילַוֵי לְהֶמְיַין אֵפוֹדָא\",0,0],[4,143,28,28,\"וִיטַכְּסוּן יַת חוּשְׁנָא מֵעִזְקָתֵיהּ לְעִזְקַת אֵיפוֹדָא בִּשְׁזִיר חוּטָא דְתִיכְלָא לְמֶהֱוֵי אֲדִיק עַל הֶמְיַין אֵפוֹדָא וְלָא יִתְפְּרֵק חוּשְׁנָא מֵעִילַוֵי אֵפוֹדָא\",0,0],[4,143,28,29,\"וְיִטוֹל אַהֲרן יַת שְׁמָהַת בְּנֵי יִשְרָאֵל בְּחֹשֶׁן דִּינָא עַל לִבֵּיהּ בִּזְמַן מַעֲלֵיהּ לְקוּדְשָׁא לְדוּכְרָן טַב קֳדָם יְיָ תְּדִירָא\",0,0],[4,143,28,30,\"וְתִתֵּן בְּחֹשֶׁן דִּינָא יַת אוּרַיָא דִּמְנַהֲרִין מִלֵּיהוֹן וּמְפַרְסְמִין טְמִירָן דְּבֵית יִשְרָאֵל וְיַת תּוּמַיָא דְמַשְׁלִימִין בְּעוֹבָדֵיהוֹן לְכַהֲנָא רַבָּא דְתָבַע אוּלְפַן מִן קֳדָם יְיָ בְּהוֹן דִּבְהוֹן חָקִיק וּמְפָרַשׁ שְׁמָא רַבָּא וְקַדִּישָׁא דְבֵיהּ אִתְבַּרְיַין תְּלַת מְאָה וְעִישַרְתֵּי עַלְמַיָא וְחָקִיק וּמְפָרֵשׁ בְּאֶבֶן שְׁתִיָה דְבָהּ חָתַם מָארֵי עַלְמָא פּוּם תְּהוֹמָא רַבָּא מִן שֵׁירוּיָיא וְכָל מַאן דְּמַדְכַּר הַהוּא שְׁמָא קַדִּישָׁא בְּשַׁעַת אֲנִיקֵי מִשְׁתְּזֵיב וּטְמִירַן מְגַלְיַין וִיהוֹן עַל לִבָּא דְאַהֲרן בִּזְמַן מֵיעֲלֵיהּ קֳדָם יְיָ וְיִטוֹל אַהֲרן יַת דִּין בְּנֵי יִשְרָאֵל עַל לִבֵּיהּ קֳדָם יְיָ תְּדִירָא\",0,0],[4,143,28,31,\"וְתַעֲבֵיד יַת מִנְטַר מְעִילָא דְאֵפוֹדָא שְׁזִיר חוּטָא דְתִיכְלָא\",0,0],[4,143,28,32,\"וִיהֵי פּוּם רֵישֵׁיהּ בְּמִיצְעֵיהּ תּוֹרָא בְּשִיפְמֵיהּ יְהֵי מַקִּיף לְפוּמֵיהּ חֲזוֹר חֲזוֹר עוֹבַד גִרְדָאֵי הֵי כְפוּם לַשִּׁירַיָא יְהֵי לֵיהּ לָא יִתְבְּזָע\",0,0],[4,143,28,33,\"וְתַעֲבֵיד עַל שִׁיפּוּלוֹי רוּמַנְיַין דְּתִיכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי עַל שִׁיפּוּלוֹי חֲזוֹר חֲזוֹר וְחִיזוּרְיַין דְּדַהֲבָא בְּמִצְעֵיהוֹן חֲזוֹר חֲזוֹר\",0,0],[4,143,28,34,\"חִיזוּרָא דְדַהֲבָא וְרִמוֹנָא דִתְכֶלְתָּא וְדִצְבַע זְהוֹרֵי חִיזוּרָא דְדַהֲבָא וְרִימוֹנָא דִתְכֶלְתָּא וְדִצְבַע זְהוֹרֵי עַל שִׁיפּוּלֵי מִינְטַר מְעִילָא חֲזוֹר חֲזוֹר סְכוּמְהוֹן שַׁבְעִין וְחַד\",0,0],[4,143,28,35,\"וִיהֵי עָטִיף עַל אַהֲרן לְשַׁמָשָׁא וְיִשְׁתְּמַע קָלֵיהּ בִּזְמַן מֵיעֲלֵיהּ לְקוּדְשָׁא קֳדָם יְיָ וּבִזְמַן מִיפְקֵיהּ וְלָא יְמוּת בְּאֵשָׁא מְצַלְהֲבָא\",0,0],[4,143,28,36,\"וְתַעֲבֵיד צִיצָא דִדְהַב דְּכֵי וְתִגְלוֹף עֲלוֹי חָקִיק וּמְפָרַשׁ קוֹדֶשׁ לַיְיָ\",0,0],[4,143,28,37,\"וּתְשַׁוֵּי יָתֵיהּ עַל שְׁזִיר חוּטָא דִתְכֶלְתָּא לִמְכַפְּרָא עַל חֲצִיפֵי אַפַּיָא וִיהֵי עַל מַצְנַפְתָּא מֵעִילַוֵי תְּפִילַת רֵישָׁא כָּל קְבֵיל אַפֵּי מִצְנַפְתָּא יְהֵי\",0,0],[4,143,28,38,\"וִיהֵי עַל פְּדַחְתָּא דְבֵית אַפּוֹי דְאַהֲרן מִן צִידְעָא לְצִידְעָא יִתְמְטֵי וְיִטוֹל אַהֲרן יַת עֲוָויַית קוּדְשַׁיָא דִיקַדְשׁוּן בְּנֵי יִשְרָאֵל לְכָל מַתְּנַת קוּדְשֵׁיהוֹן דִּמְשַׁקְרִין בְּהוֹן וִיהֵי עַל פְּדַחְתֵּיהּ תְּדִירָא לְרַעֲוָא לְהוֹן קֳדָם יְיָ\",0,0],[4,143,28,39,\"וּתְרַמֵץ כִּיתּוּנָא דְבוּצָא לִמְכַפְּרָא עַל שִׁידֵי אַדְמָא זַכָּאָה וְתַעֲבֵיד מִצְנַפְתָּא דְבוּצָא לִמְכַפְּרָא עַל מַגִּיסֵי רַעֲיוֹנֵיהוֹן וְקָמוּר תַּעֲבֵיד עוֹבַד צִיּוּר\",0,0],[4,143,28,40,\"וְלִבְנֵי אַהֲרן תַּעֲבֵיד כִּתּוּנִין וְתַעֲבֵיד לְהוֹן קְמוּרִין וְכוֹבְעִין תַּעֲבֵיד לְהוֹן לִיקַר וּלְתוּשְׁבְּחָא\",0,0],[4,143,28,41,\"וְתַלְבֵּשׁ יַתְהוֹן יַת אַהֲרן אָחוּךְ וְיַת בְּנוֹי עִמֵיהּ וּתְרַבֵּי יַתְהוֹן וּתְקָרֵב יַת קוּרְבָּנֵיהוֹן וּתְקַדֵּשׁ יַתְהוֹן וִישַׁמְשׁוּן קֳדָמַי\",0,0],[4,143,28,42,\"וַעֲבֵיד לְהוֹן אֲוַורְסְקִין דְּבוּץ לְכַסָּאָה בְּשַר עִירְיָא מִן אֲתַר קָטוֹר חַרְצֵיהוֹן וְעַד יַרְכֵיהוֹן יְהוֹן\",0,0],[4,143,28,43,\"וִיהוֹן עַל אַהֲרן וְעַל בְּנוֹי בִּזְמַן מֵעַלְהוֹן לְמַשְׁכַּן זִימְנָא אוֹ בְּמִקְרָבֵיהוֹן לְמַדְבְּחָא לְשַׁמָשָׁא בְּקוּדְשָׁא וְלָא יְקַבְּלוּן חוֹבָא וְלָא יְמוּתוּן בְּאֵשָׁא מִצַלְהֲבָא קְיַים עֲלַם לֵיהּ וְלִבְנוֹי בַּתְרוֹי\",0,0],[4,143,29,1,\"וְדֵין פִּתְגָמָא דְתַעֲבֵיד לְהוֹן לְקַדְשָׁא יַתְהוֹן לְשַׁמָשָׁא קֳדָמַי סַב תּוֹר חַד בַּר תּוֹרֵי דְלָא עֵירוּבִין וְדִכְרִין תְּרֵין שַׁלְמִין\",0,0],[4,143,29,2,\"וּלְחֵים פַּטִּיר וּגְרִיצַן פַּטִּירִין דִּפְּתִיכִין בִּמְשַׁח זֵיתָא וְעֵירוּבִין דִּלְחֵם פַּטִּיר דִּמְשִׁיחִין בִּמְשַׁח זֵיתָא סְמִידָא דְחִינְטִין תַּעֲבֵיד יַתְהוֹן\",0,0],[4,143,29,3,\"וְתִתֵּן יַתְהוֹן עַל סַלָא חָד וּתְקָרֵב יַתְהוֹן בְּסַלָא וְיַת תּוֹרָא וְיַת תְּרֵין דִּכְרִין יְסוֹבְרוּן בְּאַסְלָא\",0,0],[4,143,29,4,\"וְיַת אַהֲרן וְיַת בְּנוֹי תִּקְרַב לִתְרַע מַשְׁכַּן זִמְנָא וְתִּטְבּוֹל יַתְהוֹן בְּאַרְבְּעִין סְאִין דְּמַיָין חַיָין\",0,0],[4,143,29,5,\"וְתִסַב יַת לְבוּשַׁיָא וְתַלְבֵּישׁ יַת אַהֲרן יַת כִּיתּוּנָא וְיַת מִנְטַר מְעִיל אֵפוֹדָא וְיַת אֵפוֹדָא וְיַת חוּשְׁנָא וּתְטַכֵּס יָתֵיהּ בְּהֶמְיַין אֵפוֹדָא\",0,0],[4,143,29,6,\"וּתְשַׁוֵּי מַצְנַפְתָּא עַל רֵישֵׁיהּ וְתִתֵּן יַת כְּלִילָא דְבֵיהּ חֲקִיק שְׁמָא דְקוּדְשָׁא עַל מִצְנַפְתָּא\",0,0],[4,143,29,7,\"וְתִיסַב יַת מִשְׁחָא דִרְבוּתָא וְתָרִיק עַל רֵישֵׁיהּ וּתְרַבֵּי יָתֵיהּ\",0,0],[4,143,29,8,\"וְיַת בְּנוֹי תַקְרֵב וְתַלְבְּשִׁינוּן כִּיתּוּנִין\",0,0],[4,143,29,9,\"וְתִּטְכַס יַתְהוֹן בְּקַמּוּרִין לְאַהֲרן וּבְנוֹי וְתִכְבּוֹשׁ לְהוֹן כּוּבְעִין וּתְהֵי לְהוֹן כְּהוּנָתָא לִקְיַים עֲלָם וּתְקָרֵיב קוּרְבָּנָא דְאַהֲרן וְקוּרְבָּנָא דִבְנוֹי\",0,0],[4,143,29,10,\"וְתַקְרֵיב יַת תּוֹרָא קֳדָם מַשְׁכַּן זִמְנָא וְיִסְמוֹךְ אַהֲרן וּבְנוֹי יַת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא\",0,0],[4,143,29,11,\"וְתִיכּוֹס יַת תּוֹרָא קֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא\",0,0],[4,143,29,12,\"וְתִיסַב מֵאַדְמָא דְתוֹרָא וְתִתֵּן עַל קַרְנַת מַדְבְּחָא בְּאַדְבָּעָךְ וְיַת כָּל דְּמָא תֵשׁוֹד לִיסוֹדָא דְמַדְבְּחָא\",0,0],[4,143,29,13,\"וְתִיסַב יַת כָּל תַּרְבָּא דְחָפֵי עַל בְּנֵי גַוָא וְיַת דְּמִשְׁתְּאַר עַל חֲצַר כַּבְדָא וְיַת תַּרְתֵּין כּוֹלְיַין וְיַת תַּרְבָּא דִעֲלֵיהוֹן וּתְסַדֵּר עַל מַדְבְּחָא\",0,0],[4,143,29,14,\"וְיַת בִּשְרָא דְתוֹרָא וְיַת מוֹשְׁכֵיהּ וְיַת רֵיעֵיהּ תּוֹקַד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא חַטָּאתָא הוּא\",0,0],[4,143,29,15,\"וְיַת דִּכְרָא חָד תִּסַב וְיִסְמְכוּן אַהֲרן וּבְנוֹי יַת יְדֵיהוֹן עַל רֵישׁ דִּכְרָא\",0,0],[4,143,29,16,\"וְתִכּוֹס יַת דִּכְרָא וְתִסַּב יַת אַדְמֵיהּ וְתִדְרוֹק עַל מַדְבְּחָא חֲזוֹר חֲזוֹר\",0,0],[4,143,29,17,\"וְיַת דִּכְרָא תַפְסִיג לְפִסְגוֹי וּתְחַלֵּיל בְּנֵי גַוָאָה וּכְרָעוֹי וּתְסַדֵּר עַל אֵיבָרוֹי וְעַל רֵישֵׁיהּ\",0,0],[4,143,29,18,\"וְתַסִיק יַת כָּל דִּכְרָא לְמַדְבְּחָא עֲלָתָא הוּא קֳדָם יְיָ לְאִתְקַבָּלָא בְּרַעֲוָא קוּרְבָּנָא קֳדָם יְיָ הוּא\",0,0],[4,143,29,19,\"וְתִיסַב יַת דִּכְרָא תִנְיָנָא וְיִסְמוֹךְ אַהֲרן וּבְנוֹי יַת יְדֵיהוֹן עַל רֵישׁ דִּכְרָא\",0,0],[4,143,29,20,\"וְתִיכּוֹס יַת דִּכְרָא וְתִיסַב מִן אַדְמֵיהּ וְתִתֵּן עַל חַסְחוּס אוּדְנָא דְאַהֲרן דְּיַמִינָא וְעַל חַסְחוּס אוּדְנָא דִבְנוֹי דְיַמִינָא וְעַל אִילְיוֹן יְדֵיהוֹן דְּיַמִינָא וְעַל אִילְיוֹן רִיגְלֵיהוֹן דְּיַמִינָא וְתִדְרוֹק יַת מוֹתַר אַדְמָא עַל מַדְבְּחָא חֲזוֹר חֲזוֹר\",0,0],[4,143,29,21,\"וְתִיסַב מִן אַדְמָא דְעַל מַדְבְּחָא וּמִמִּשְׁחָא דִרְבוּתָא וְתַדִי עַל אַהֲרן וְעַל לְבוּשׁוֹי וְעַל בְּנוֹי וְעַל לְבוּשֵׁי בְּנוֹי עִמֵּיהּ וְיִתְקַדֵּשׁ הוּא וּלְבוּשׁוֹהִי וּבְנוֹהִי וּלְבוּשֵׁי בְּנוֹהִי עִמֵּיהּ\",0,0],[4,143,29,22,\"וְתִסַב מִן דִּכְרָא תַּרְבָּא וְאַלְיָתָא וְיַת תַּרְבָּא דְחָפֵי יַת בְּנֵי גַוָא וְיַת דְּמִשְׁתְּאַר עַל חֲצַר כַּבְדָא וְיַת תַּרְתֵּין כּוּלְּיַין וְיַת תַּרְבָּא דַּעֲלֵיהוֹן וְיַת שׁוֹקָא דְיַמִּינָא אֲרוּם דְּכַר קוּרְבָּנַיָא הוּא\",0,0],[4,143,29,23,\"וַעֲגוֹל דִּלְחֵים חָד וּגְרֵיץ דִּלְחֵים פָּתִיךְ בִּמְשַׁח חַד וְעָרִיךְ חַד מִסַּלָא דְפַטִּירָא דִקְדָם יְיָ\",0,0],[4,143,29,24,\"וּתְשַׁוֵּי כוֹלָא עַל יְדֵי אַהֲרן וְעַל יְדֵי בְנוֹי וְתָרִים יַתְהוֹן אֲרָמָא קֳדָם יְיָ\",0,0],[4,143,29,25,\"וְתִיסַב יַתְהוֹן מִידֵיהוֹן וּתְסַדֵּר בְּמַדְבְּחָא עַל עֲלָתָא לְאִתְקַבָּלָא בְּרַעֲוָא קֳדָם יְיָ קוּרְבָּנָא הוּא קֳדָם יְיָ\",0,0],[4,143,29,26,\"וְתִיסַב יַת חַדְיָא מִדְכַר קוּרְבָּנַיָא דִלְאַהֲרן וְתָרֵים יָתָהּ אֲרָמָא קֳדָם יְיָ וִיהֵי לָךְ לְחוּלָק\",0,0],[4,143,29,27,\"וּתְקַדֵּשׁ יַת חַדְיָא דְאַרָמוּתָא וְיַת שׁוֹקָא דְאַפְרָשׁוּתָא דְאִיתְרַם וּדְאִיתְפָּרֵשׁ מִדְכַר קוּרְבָּנַיָא מִידֵי לְאַהֲרן וּמִידֵי לִבְנוֹהִי\",0,0],[4,143,29,28,\"וִיהֵי לְאַהֲרן וְלִבְנוֹי לִקְיַים עֲלָם מִן בְּנֵי יִשְרָאֵל אֲרֵי אַפְרָשׁוּתָא הוּא וְאַפְרְשׁוּתָא יְהֵי מִן בְּנֵי יִשְרָאֵל מִנִּכְסַת קוּדְשֵׁיהוֹן אַפְרָשׁוּתְהוֹן קֳדָם יְיָ\",0,0],[4,143,29,29,\"וּלְבוּשֵׁי קוּדְשָׁא דִלְאַהֲרן יְהוֹן לִבְנוֹי בַּתְרוֹי לְרַבָּאָה בְּהוֹן וּלְקָרָבָא בְּהוֹן יַת קוּרְבָּנֵיהוֹן\",0,0],[4,143,29,30,\"שׁוּבְעָא יוֹמִין יַלְבְּשִׁינוּן כַּהֲנָא דִיקוּם בַּתְרוֹי מִן בְּנוֹי וְלָא מִן לֵיוָאֵי בִּזְמַן דִּיעוֹלִין לְמַשְׁכַּן זִימְנָא לְשַׁמָּשָׁא בְּקוּדְשָׁא\",0,0],[4,143,29,31,\"וְיַת דְּכַר קוּרְבָּנַיָא תִיסַב וּתְבַשֵּׁל יַת בִּשְרֵיהּ בְּאָתַר קַדִּישׁ\",0,0],[4,143,29,32,\"וְיֵיכוֹל אַהֲרן וּבְנוֹי יַת בִּישְרָא דְדִיכְרָא וְיַת לַחֲמָא דִי בְסַלָא בִּתְרַע מַשְׁכַּן זִימְנָא\",0,0],[4,143,29,33,\"וְיֵיכְלוּן יַתְהוֹן דְּאִתְכַּפֵּר בְּהוֹן לְקָרְבָא יַת קוּרְבַּנְהוֹן לְמַקְדְּשָׁא יַתְהוֹן לְשַׁמָּשָׁא קֳדָמַי וְחִילוֹנֵי לָא יֵיכוּל אֲרוּם קוּדְשָׁא הִינוּן\",0,0],[4,143,29,34,\"וְאִין יִשְׁתְּיַיר מִבְּשַר קוּרְבָּנַיָא וּמִן לַחְמָא עַד צַפְרָא וְתוֹקֵיד יַת דְּמִשְׁתְּיַיר בְּנוּרָא לָא יִתְאָכֵיל אֲרוּם קוּדְשָׁא הוּא\",0,0],[4,143,29,35,\"וְתַעֲבֵיד לְאַהֲרן וְלִבְנוֹהִי הֵיכְדֵין כְּכָל דִּי פַקֵידִית יָתָךְ שׁוּבְעָא יוֹמִין תִּקְרַב קוּרְבַּנְהוֹן\",0,0],[4,143,29,36,\"וְתוֹרָא דְחַטָּאתָא תַּעֲבֵיד לְיוֹמָא עַל כִּיפּוּרַיָא וּתְרַבֵּי עַל מַדְבְּחָא בְּכַפָּרוּתָךְ עֲלוֹי וּתְרַבֵּי עֲלֵיהּ לְקַדָּשׁוּתֵיהּ\",0,0],[4,143,29,37,\"שׁוּבְעָא יוֹמִין תְּכַפֵּר עַל מַדְבְּחָא וּתְקַדֵּישׁ יָתֵיהּ וִיהֵי מַדְבְּחָא קוֹדֶשׁ קוּדְשִׁין כָּל דְּיִקְרַב בְּמַדְבְּחָא יִתְקַדֵּשׁ מִן בְּנֵי אַהֲרן בְּרַם מִן שְׁאַר עַמָּא לֵית אֶפְשַׁר לְהוֹן לְמִקְרַב דִּלְמָא יִתּוֹקְדוּן בְּאֵשָׁא מְצַלְהֲבָא דְנָפִיק מִן קוּדְשַׁיָא\",0,0],[4,143,29,38,\"וְדֵין קוּרְבָּנָא דְתַעֲבֵיד עַל מַדְבְּחָא אִמְרִין בְּנֵי שְׁנָה תְּרֵין לְיוֹמָא תְדִירָא\",0,0],[4,143,29,39,\"יַת אִימְרָא חַד תַּעֲבֵיד בְּצַפְרָא וְיַת אִימְרָא תִנְיָנָא תַעֲבֵיד בֵּינֵי שִׁימְשָׁתָא\",0,0],[4,143,29,40,\"וְעִשְרוֹנָא סְמִידָא פָּתִיךְ בִּמְשַׁח זֵיתָא כְּתִישָׁא רַבְעוּת הִינָא וְנִיסוּכָא רַבְעוּת הִינָא חַמְרָא לְאִימְרָא חָד\",0,0],[4,143,29,41,\"וְיַת אִימְרָא תִנְיָנָא תַּעֲבֵיד בֵּינֵי שִׁמְשְׁתָא הֵי כְּמִנְחַת צַפְרָא וְהֵי כְנִיסוּכָהּ תַּעֲבֵיד לָהּ לְאִתְקַבָּלָא בְּרַעֲוָא קוּרְבָּנָא קֳדָם יְיָ\",0,0],[4,143,29,42,\"עֲלַת תְּדִירָא לְדָרֵיכוֹן בִּתְרַע מַשְׁכַּן זִימְנָא קֳדָם יְיָ דְּאַזְמִין מֵימְרִי לְכוֹן תַּמָּן לְמַלָּלָא עִמָךְ תַּמָּן\",0,0],[4,143,29,43,\"וְאֵיזַמֵן מֵימְרִי תַמָּן לִבְנֵי יִשְרָאֵל וְאֵקַדֵשׁ בְּרַבָּנֵיהוֹן בְּגִין יְקָרִי\",0,0],[4,143,29,44,\"וְאֵיקַדֵּשׁ יַת מַשְׁכַּן זִימְנָא וְיַת מַדְבְּחָא וְיַת אַהֲרן וְיַת בְּנוֹי אֵיקַדֵּשׁ לְשַׁמָּשָׁא קֳדָמָי\",0,0],[4,143,29,45,\"וְאַשְׁרֵי שְׁכִינְתִּי בְּגוֹ בְּנֵי יִשְרָאֵל וְאֶהֱוֵי לְהוֹן לֵאלָהָא\",0,0],[4,143,29,46,\"וְיֵדְעוּן בְּנֵי יִשְרָאֵל אֲרוּם אֲנָא יְיָ אֱלָהָהוֹן דִּי הַנְפֵיקִית יַתְהוֹן פְּרִיקִין מֵאַרְעָא דְמִצְרַיִם לְאַשְׁרָאָה שְׁכִינְתִּי בֵּינֵיהוֹן אֲנָא הוּא יְיָ אֱלָהָהוֹן\",0,0],[4,143,30,1,\"וְתַעֲבֵיד מַדְבְּחָא לְאַסָקָא עֲלוֹי קְטוֹרֶת בּוּסְמַיָא דְקִיסֵי שִׁיטָא תַעֲבֵיד יָתֵיהּ\",0,0],[4,143,30,2,\"אַמְתָא אוּרְכֵּיהּ וְאַמְתָא פּוּתְיֵהּ מְרַבַּע יְהֵא וְתַרְתֵּין אַמִּין רוּמֵיהּ מִינֵיהּ יְהוֹן קַרְנוֹי זְקִיפוּן\",0,0],[4,143,30,3,\"וְתַחְפֵי יָתֵיהּ דְּהַב דְּכֵי יַת אִיגְרֵיהּ וְיַת כּוֹתְלוֹי חֲזוֹר חֲזוֹר וְיַת קַרְנוֹי וְתַעֲבֵיד לֵיהּ זֵיר דִּדְהַב חֲזוֹר חֲזוֹר\",0,0],[4,143,30,4,\"וְתַרְתֵּין עִיזְקַן דִּדְהַב תַּעֲבֵיד לֵיהּ מִלְרַע לְזֵירֵיהּ עַל תְּרֵין זִיוְיָיתֵיהּ תַּעֲבֵיד עַל תְּרֵין צִיטְרוֹי וִיהֵי לְאַתְרָא לַאֲרִיחַיָא לְמֵיטַל יָתֵיהּ בְּהוֹם\",0,0],[4,143,30,5,\"וְתַעֲבֵיד יַת אֲרִיחַיָא דְקִיסֵי שִׁיטָא וְתַחֲפֵי יַתְהוֹן דַּהֲבָא\",0,0],[4,143,30,6,\"וְתִתֵּן יָתֵיהּ קֳדָם פַּרְגּוֹדָא דְעַל אֲרוֹנָא דְסַהֲדוּתָא קֳדָם כַּפּוּרְתָּא דְעַל סַהֲדוּתָא דְּאֵיזַמֵּן מֵימְרִי לָךְ תַּמָּן\",0,0],[4,143,30,7,\"וְיַקְטֵר עֲלוֹי אַהֲרן קְטוֹרֶת בּוּסְמִין בִּצְפַר בִּצְפַר בְּאַתְקָנוּתֵיהּ יַת בּוֹצִינַיָא יַקְטְרִינָהּ\",0,0],[4,143,30,8,\"וּבְאַדְלָקוּת אַהֲרן יַת בּוֹצִינַיָא בֵּינֵי שִׁמְשְׁתָא יַקְטְרִינָהּ קְטוֹרֶת בּוּסְמִין תְּדִירָא קֳדָם יְיָ לְדָרֵיכוֹן\",0,0],[4,143,30,9,\"לָא תִסְקוּן עֲלוֹי קְטוֹרֶת בּוּסְמִין דְּעַמְמִין נוּכְרָאִין וְעָלָתָא וּמִנְחָתָא וְנִיסוּכִין לָא תְנַסְכוּן עֲלוֹי\",0,0],[4,143,30,10,\"וִיכַפֵּר אַהֲרן עַל קַרְנוֹי חֲדָא בְּשַׁתָּא מִן אֲדָם חַטָּאתָא דְכִפּוּרַיָא חֲדָא זִמְנָא בְּשַׁתָּא יְכַפֵּר עֲלוֹי בְּיוֹמָא דְכִפּוּרֵי לְדָרֵיכוֹן קוֹדֶשׁ קוּדְשִׁין הוּא קֳדָם יְיָ\",0,0],[4,143,30,11,\"וידבר וּמַלֵּיל יְיָ עִם משֶׁה לְמֵימָר\",0,0],[4,143,30,12,\"אֲרוּם תְּקַבֵּל יַת חוּשְׁבַּן בְּנֵי יִשְרָאֵל לְמִנְיָינֵיהוֹן וְיִתְּנוּן גְּבַר פּוּרְקַן נַפְשֵׁיהּ קֳדָם יְיָ כַּד תִּמְנֵי יַתְהוֹן וְלָא יְהֵי בְּהוֹן נִזְקָא דְמוֹתָא כַּד תִּמְנֵי יַתְהוֹן\",0,0],[4,143,30,13,\"דֵּין שִׁיעוּרָא אִיתְחַמֵי לְמשֶׁה בְּטַוְורָא הֵי כְדִינְרָא דְאֵשָׁא וְהֵיכְדֵין אָמַר לֵיהּ כְּדֵין יִנָּתְנוּן כָּל מַאן דְּעָבַר עַל מִנְיָנַיָא פַּלְגוּת סִילְעָא בְּסִילְעָא דְטַבְעָא דְקוּדְשָׁא עַשְרִין מָעִין סִילְעָא פַּלְגוּת סִילְעָא אַפְרָשׁוּתָא קֳדָם יְיָ\",0,0],[4,143,30,14,\"כָּל מַאן דְּעָבַר עַל מִנְיָינַיָא מִבַּר עַשְרִין שְׁנִין וּלְעֵילָא יִתֵּן אַפְרָשׁוּתָא קֳדָם יְיָ\",0,0],[4,143,30,15,\"דְּעַתִּיר לָא יִסְגֵי וּדְמִסְכֵּן לָא יַזְעַר מִפַּלְגוּת סִלְעָא לְמִתַּן יַת אַפְרָשׁוּתָא קֳדָם יְיָ לְכַפָּרָא עַל נַפְשָׁתֵיכוֹן\",0,0],[4,143,30,16,\"וְתִיסַב יַת כַּסְפָּא דְכִיפּוּרַיָא מִן בְּנֵי יִשְרָאֵל וְתִתֵּן יָתֵיהּ עַל עֲבִידַת מַשְׁכַּן זִימְנָא וִיהֵי לִבְנֵי יִשְרָאֵל לְדוּכְרַן טַב קֳדָם יְיָ לְכַפָּרָא עַל נַפְשָׁתֵיכוֹן\",0,0],[4,143,30,17,\"וּמַלֵּיל יְיָ עִם משֶׁה לְמֵימָר\",0,0],[4,143,30,18,\"וְתַעֲבֵיד כִּיּוֹרָא דִנְחָשָׁא וּבְסִיסֵיהּ דִּנְחָשָׁא לְקִדּוּשׁ וּתְסַדֵּר יָתֵיהּ בֵּין מַשְׁכַּן זִימְנָא וּבֵין מַדְבְּחָא וְתִתֵּן תַּמָּן מוֹי\",0,0],[4,143,30,19,\"וְיִסְבּוּן מִנֵּיהּ בִּנְטִילָא דַכְיָא וִיקַדְשׁוּן בְּמוֹהִי אַהֲרן וּבְנוֹי יַת יְדֵיהוֹן וְיַת רִיגְלֵיהוֹן\",0,0],[4,143,30,20,\"בִּזְמַן מֵיעַלְהוֹן לְמַשְׁכַּן זִימְנָא יְקַדְּשׁוּן מוֹי וְלָא יְמוּתוּן בְּאֵשָׁא מְצַלְהֲבָא אוֹ בְּמִקְרַבְהוֹן לְמַדְבְּחָא לְשַׁמָּשָׁא לְאַסָקָא קוּרְבָּנָא קֳדָם יְיָ\",0,0],[4,143,30,21,\"וִיקַדְשׁוּן יְדֵיהוֹן וְרִיגְלֵיהוֹן וְלָא יְמוּתוּן וּתְהֵי לְהוֹן קְיַים עֲלַם לֵיהּ וְלִבְנוֹי לְדָרֵיהוֹן\",0,0],[4,143,30,22,\"וּמַלֵּיל יְיָ עִם משֶׁה לְמֵימָר\",0,0],[4,143,30,23,\"וְאַנְתְּ סַב לָךְ בּוּסְמִין בִּשְׁרוּיָיא מוֹר בְּחִיר מַתְקַל חֲמֵשׁ מְאָה מָנִין וְקִינְמוֹן בּוֹשֶם פַּלְגוּתֵיהּ מַתְקַל מָאתָן וְחַמְשִׁין מָנִין וּקְנֵהּ בּוּשְמָא מַתְקַל מָאתָן וְחַמְשִׁין מָנִין\",0,0],[4,143,30,24,\"וּקְצִיעָתָא מַתְקַל חֲמֵשׁ מְאָה מָנִין סִילְעִין בְּסִלְעֵי קוּדְשָׁא וּמְשַׁח זֵיתָא מְלֵי קִסְטָא דִסְכוּמֵיהּ תְּרֵיסַר לוּגִין לוּגָא לְכָל שִׁיבְטָא לִתְרֵיסַר שִׁבְטִין\",0,0],[4,143,30,25,\"וְתַעֲבֵיד יָתֵיהּ מְשַׁח רְבוּת קוּדְשָׁא בּוֹשֶם מִתְבַּשַם עוֹבַד מִתְבַּשֵם בִּישְמָא מַמְזִיג מְשַׁח רְבוּת קוּדְשָׁא יְהֵי\",0,0],[4,143,30,26,\"וּתְרַבֵּי בֵיהּ יַת מַשְׁכַּן זִימְנָא וְיַת אֲרוֹנָא דְסַהֲדוּתָא\",0,0],[4,143,30,27,\"וְיַת פְּתוֹרָא וְיַת כָּל מָנוֹי וְיַת מְנַרְתָּא וְיַת מְנָהָא וְיַת מַדְבְּחָא דִקְטוֹרֶת בּוּסְמַיָא\",0,0],[4,143,30,28,\"וְיַת מַדְבְּחָא דַעֲלָתָא וְיַת כָּל מָנוֹי וְיַת כִּיּוֹרָא וְיַת בְּסִיסֵיהּ\",0,0],[4,143,30,29,\"וּתְקַדַּשׁ יַתְהוֹן וִיהוֹן קוֹדֶשׁ קוּדְשִׁין כָּל דְּיִקְרַב בְּהוֹן מִן כַּהֲנַיָא יִתְקַדָּשׁ וּמִשְׁאַר שִׁבְטַיָא יְתוּקַד בְּאֵשָׁא מְצַלְהֲבָא קֳדָם יְיָ\",0,0],[4,143,30,30,\"וְיַת אַהֲרן וְיַת בְּנוֹי תְרַבֵּי וּתְקַדֵּשׁ יַתְהוֹן לְשַׁמָּשָׁא קֳדָמַי\",0,0],[4,143,30,31,\"וְעִם בְּנֵי יִשְרָאֵל תְּמַלֵּיל לְמֵימָר מְשַׁח רְבוּת קוּדְשָׁא יְהֵי דֵין קֳדָמַי לְדָרֵיכוֹן\",0,0],[4,143,30,32,\"עַל בִּישְרָא דְּאֵינָשָׁא לָא יִתְמְרַק וְכִדְמוּיֵיהּ לָא תַעַבְדוּן כְּוָותֵיהּ קוּדְשָׁא הוּא קוּדְשָׁא יְהֵי לְכוֹן\",0,0],[4,143,30,33,\"גְבַר דִּי יִמְזָג כְּוָותֵיהּ וּדְיִתֵּן מִינָהּ עַל חִילוֹנֵי דְלָא מִבְּנוֹי דְאַהֲרן וְיִשְׁתֵּיצֵי מֵעַמֵּיהּ\",0,0],[4,143,30,34,\"וַאֲמַר יְיָ לְמשֶׁה סַב לָךְ בּוּסְמֵי קְטַף וּבְשַׁת וְחֶלְבָּנַיָא בּוּסְמִין בְּחִירִין דַּכְיָיתָא מַתְקַל בְּמַתְקַל יְהֵי\",0,0],[4,143,30,35,\"וְתַעֲבֵיד יָתֵיהּ קְטוֹרֶת בּוּסְמָנָן בּוֹשֶם עוֹבַד מַמְזִיג מְעַרֵב דְּכֵי קוּדְשָׁא\",0,0],[4,143,30,36,\"וְתִכְתּוֹשׁ מִינָהּ וְתָדִיק וְתִתֵּן מִינָהּ קֳדָם סַהֲדוּתָא בְּמַשְׁכַּן זִימְנָא דְּאֵיזַמִין מֵימְרִי לָךְ תַּמָּן קוֹדֶשׁ קוּדְשִׁין תְּהֵא לְכוֹן\",0,0],[4,143,30,37,\"וּקְטוֹרֶת בּוּסְמִין דְּתַעֲבֵיד בִּדְמוּיָיהּ לָא תַעַבְּדוּן לְכוֹן קוּדְשָׁא תְּהֵא לְכוֹן קֳדָם יְיָ\",0,0],[4,143,30,38,\"גְּבַר דְּיַעֲבֵיד דִּכְוָותֵיהּ לְאָרָחָא בָהּ וְיִשְׁתְּצֵי מֵעַמֵּיהּ\",0,0],[4,143,31,1,\"וּמַלֵּיל יְיָ עִם משֶׁה לְמֵימָר\",0,0],[4,143,31,2,\"חֲמֵי משֶׁה דְּקַרְיַית בְּשׁוּם טַב בְּצַלְאֵל בַּר אוּרִי בַּר חוּר לְשִׁבְטָא דִיהוּדָה\",0,0],[4,143,31,3,\"וְאַשְׁלֵמִית עִמֵּיהּ רוּחַ קוּדְשָׁא מִן קֳדָם יְיָ בְּחָכְמָתָא בְּסוּכְלְתָנוּ וּבְמַנְדְּעָא וּבְכָל עִיבִידְתָּא\",0,0],[4,143,31,4,\"לְמֵיחְשַׁב בְּרַעֲיוֹנֵיהוֹן הֵיךְ לְמֶעֱבַד בְּדַהֲבָא וּבְכַסְפָּא וּבִנְחָשָׁא\",0,0],[4,143,31,5,\"וּבְאַגְלָפוּת מַרְגְּלִיתָא לְאַשְׁלָמָא וּבְנַגָרוֹת קִיסָא לְמֶעֱבַד כָּל עִיבִידְתָּא\",0,0],[4,143,31,6,\"וַאֲנָא הָא מַנְיַית עִמֵּיהּ יַת אָהֳלִיאָב בַר אֲחִיסָמָךְ לְשִׁבְטָא דְדָן וּבְלִבָּא דְּכָל חַכִּימֵי לִיבָּא אוֹסִיפִית רוּחַ חוּכְמָתָא וְיַעַבְדוּן יַת כָּל מַה דְּאַפְקֵדִיתָךְ\",0,0],[4,143,31,7,\"יַת מַשְׁכַּן זִימְנָא וְיַת אֲרוֹנָא דְסַהֲדוּתָא וְיַת כַּפּוּרְתָּא דְעָלוֹי וְיַת כָּל מָנֵי מַשְׁכְּנָא\",0,0],[4,143,31,8,\"וְיַת פְּתוֹרָא וְיַת כָּל מָנוֹי וְיַת מְנַרְתָּא דָכִיתָא וְיַת כָּל מָנָהָא וְיַת מַדְבְּחָא דִקְטוֹרֶת בּוּסְמַיָא\",0,0],[4,143,31,9,\"וְיַת מַדְבְּחָא דְעָלָתָא וְיַת כָּל מָנוֹי וְיַת כִּיּוֹרָא וְיַת בְּסִיסֵיהּ\",0,0],[4,143,31,10,\"וְיַת לְבוּשֵׁי שִׁמּוּשָׁא וְיַת לְבוּשֵׁי קוּדְשָׁא לְאַהֲרן כַּהֲנָא וְיַת לְבוּשֵׁי בְנוֹי לְשַׁמָּשָׁא\",0,0],[4,143,31,11,\"וְיַת מְשַׁח רְבוּתָא וְיַת קְטוֹרֶת בּוּסְמַיָא לְקוּדְשָׁא הֵי כְּכָל מַה דְּפַקִידְתָּךְ יַעַבְדוּן\",0,0],[4,143,31,12,\"וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר\",0,0],[4,143,31,13,\"וְאַנְתְּ תְּמַלֵּיל עִם בְּנֵי יִשְרָאֵל לְמֵימַר בְּרַם יַת יוֹמֵי שַׁבַּיָא דִי לִי תִנְטְרוּן אֲרוּם אָת הוּא בֵּין מֵימְרִי וּבֵינֵיכוֹן לְדָרֵיכוֹן לְמִידוֹעַ אֲרוּם אֲנָא הוּא יְיָ מְקַדִּישְׁכוֹן\",0,0],[4,143,31,14,\"וְתִנְטְרוּן יַת שַׁבְּתָא אֲרוּם קוּדְשָׁא הִיא לְכוֹן דְּיַפְסִינָהּ אִיתְקְטָלָא יִתְקְטֵיל אֲרוּם כָּל מַאן דְּיַעֲבֵיד בָּהּ עִיבִידְתָּא וְיִשְׁתֵּיצֵי בַּר נְשָׁא הַהוּא מֵעַמֵּיהּ\",0,0],[4,143,31,15,\"שִׁיתָּא יוֹמִין יִתְעֲבֵיד עִיבִידְתָּא וּבְיוֹמָא שְׁבִיעָאָה שַׁבָּת שַׁבְּתָא קוּדְשָׁא קֳדָם יְיָ כָּל מַאן דְּיַעֲבֵיד עִיבִידְתָּא בְּיוֹמָא דְשַׁבְּתָא אִתְקְטָלָא יִתְקְטֵיל בְּמַטְלוּת אַבְנִין\",0,0],[4,143,31,16,\"וְיִנְטְרוּן בְּנֵי יִשְרָאֵל יַת שַׁבְּתָא לְמֶעֱבַד תַּפְנוּקֵי שַׁבְּתָא לְדָרֵיהוֹן קְיַים עֲלָם\",0,0],[4,143,31,17,\"בֵּין מֵימְרִי וּבֵין בְּנֵי יִשְרָאֵל אָת הִיא לְעַלָם אֲרוּם בְּשִׁיתָּא יוֹמִין בְּרָא יְיָ וְשַׁכְלֵיל יַת שְׁמַיָא וְיַת אַרְעָא וּבְיוֹמָא שְׁבִיעָאָה שְׁבָת וְנָח\",0,0],[4,143,31,18,\"וִיהַב לְמשֶׁה כַּד פָּסַק לְמַלָּלָא עִמֵּיהּ בְּטַוְורָא דְסִינַי תְּרֵין לוּחֵי סַהֲדוּתָא לוּחֵי דְאֶבֶן סַפִּירִינוּן מִכּוּרְסֵי יְקָרָא מַתְקַלְהוֹן אַרְבְּעִין סְאִין כְּתִיבִין בְּאֶצְבְּעָא דַיְיָ\",0,0],[4,143,32,1,\"וַחֲמָא עַמָּא אֲרוּם אִשְׁתְּהֵי משֶׁה לְמֵיחוּת מִן טַוְורָא וְאִתְכְּנֵישׁ עַמָּא עַל אַהֲרן כַּד חֲמוּן דְּעָבַר זִימְנָא דְקָבַע לְהוֹן וַאֲזַל סַטָנָא וְאַטְעִינוּן וְהָדַר לִבְּהוֹן זְחוֹחִין וַאֲמַרוּ לֵיהּ קוּם עִיבַד לָנָא דַחֲלַן דִּי טַיְילִן קָדָמָנָא אֲרוּם דֵּין משֶׁה גַבְרָא דְאַסְקָנָא מֵאַרְעָא דְמִצְרַיִם אִשְׁתַּלְהַב בְּטַוְורָא דְאֵשָׁא מְצַלְהֲבָא מִן קֳדָם יְיָ לָא אִשְׁתְּמוֹדְעָנָא מַה הֲוָה לֵיהּ בְּסֵיפֵיהּ\",0,0],[4,143,32,2,\"וַאֲמַר לְהוֹן אַהֲרן פְּרִיקוּ קָדָשֵׁי דְדַהֲבָא דִבְאוּדְנֵי נְשֵׁיכוֹן בְּנֵיכוֹן וּבְנָתֵיכוֹן וְאַיְיתוּ לְוָתִי\",0,0],[4,143,32,3,\"וְסָרִיבוּ נְשַׁיָא לְמִיתַּן תַּכְשִׁיטֵיהוֹן לְגַבְרֵיהוֹן וּמִן יַד פְּרִיקוּ כָּל עַמָּא יַת קָדָשֵׁי דְדַהֲבָא דִי בְאוּדְנֵיהוֹן וְאַיְיתִיוּ לְאַהֲרן\",0,0],[4,143,32,4,\"וּנְסֵיב מִידֵיהוֹן וְצַר יָתֵיהּ בְּשׁוֹשִׁיפָא וּרְמָא יָתֵיהּ בְּטוּפְרָא וְעַבְדֵיהּ עֵיגַל מַתְּכָא וַאֲמָרוּ אִלֵּין דַּחַלְתָּךְ יִשְרָאֵל דְּהַנְפָקוּךְ מֵאַרְעָא דְמִצְרָיִם\",0,0],[4,143,32,5,\"וַחֲמָא אַהֲרן יַת חוּר נְכִיס קֳדָמוֹי וּדְחִיל וּבְנָא מַדְבְּחָא קֳדָמוֹי וּקְרָא בְּקַל עָצִיב וַאֲמַר חַגָּא דַיְיָ מְחַר מִנִּכְסַת קְטוֹל בַּעֲלֵי דְבָבוֹי אִלֵּין דְּכָּפְרִין בְּמָרֵיהוֹן וּפָרְגוּ עִיקַר שְׁכִינְתֵּיהּ יְיָ בְּעִיגְלָא הָדֵין\",0,0],[4,143,32,6,\"וְאַקְדִימוּ מִיּוֹמָא מָחְרָא וְאַסִיקוּ עֲלָוָון וּקְרִיבוּ נִיכְסִין וְאַסְחַר עַמָא לְמֵיכוֹל וּלְמִישְׁתֵּי וְקָמוּ לְהוֹן לִמְגַחֲכָא בְּפוּלְחָנָא נוּכְרָאָה\",0,0],[4,143,32,7,\"וּמַלֵּיל יְיָ עִם משֶׁה אִיזֵיל חוּת מִן רְבוּת יְקָרָךְ דְּלָא יְהָבִית לָךְ רְבוּתָא אֱלָהֵן בְּגִין יִשְרָאֵל וּכְדוּן חַבִּילוּ עוֹבָדֵיהוֹן עַמָּךְ דְּאַפֵּיקְתָּא מֵאַרְעָא דְמִצְרָיִם\",0,0],[4,143,32,8,\"סָטוּ בִּפְרִיעַ מִן אוֹרְחָא דְפַקֵידְתִּינוּן בְּסִינַי לָא תַעַבְּדוּן לְכוֹן צְלַם וְצוּרָה וְכָל דְּמוּ וּכְדוֹן עָבְדוּ לְהוֹן עֵיגַל מַתְּכָא וּסְגִידוּ לֵיהּ וְדַבְּחוּ לֵיהּ וְאַכְרִיזוּ קֳדָמוֹי אִלֵּין דַּחַלְתָּךְ יִשְרָאֵל דְאַסְקוּךְ מֵאַרְעָא דְמִצְרָיִם\",0,0],[4,143,32,9,\"וַאֲמַר יְיָ לְמשֶׁה גְּלֵי קֳדָמָי זְדוֹנְהוֹן דְּעַמָּא הָדֵין וְהָא עַם קְשֵׁי קְדַל הוּא\",0,0],[4,143,32,10,\"וּכְדוּן אַנַח בְּעוּתָךְ וְלָא תַפְגִין עֲלֵיהוֹן קֳדָמַי וְאַרְתַח רְגַז אֵשָׁתָא תַקִיפְתָּא בְּהוֹן וְאֵשֵׁיצִינוּן וְאֶעְבַּד יָתָךְ לְעַם סַגִי\",0,0],[4,143,32,11,\"וְאִתְחַלְחַל משֶׁה מִן רְתִיתָא וּשְׁרֵי לְצַלָּאָה קֳדָם יְיָ אֱלָהֵיהּ וַאֲמַר לְמָא יְיָ יִתְקוֹף רוּגְזָךְ בְּעַמָּךְ דְּהַנְפָּקַת מֵאַרְעָא דְמִצְרַיִם בְּחֵיל רַב וּבִידָא תַקִיפָא\",0,0],[4,143,32,12,\"לְמָא דֵין יֵימְרוּן מִצְרָאֵי דְמִשְׁתַּיְירִין לְמֵימָר בְּבִישָׁא אַנְפֵּיקִינוּן לְקַטְלָא יַתְהוֹן בֵּינֵי טַוְורַיָא תָּבוֹר וְחֶרְמוֹן וְשִירְיוֹן וְסִינַי וּבְגִין לְשֵׁיצָאָה יַתְהוֹן מֵעַל אַנְפֵּי אַרְעָא תּוּב מִתְקוֹף רוּגְזָךְ וִיהֱוֵי תוֹהוּ קֳדָמָךְ עַל בִּישְׁתָּא דְמַלֵּילַת לְמֶעְבַּד לְעַמָּךְ\",0,0],[4,143,32,13,\"הֱוֵי דְכִיר לְאַבְרָהָם לְיִצְחָק וּלְיִשְרָאֵל עַבְדָךְ דְּקַיֵּימְתָּא לְהוֹן בְּמֵימְרָךְ וּמַלֵּילְתָּא לְהוֹן אַסְגֵי יַת בְּנֵיכוֹן הֵי כְּכוֹכְבֵי שְׁמַיָא וְכָל אַרְעָא הָדָא דַאֲמָרִית לְכוֹן אֵיתֵּן לִבְנֵיכוֹן וְיֶחְסְנוּן לְעָלָם\",0,0],[4,143,32,14,\"וַהֲוָה תוֹהוּ מִן קֳדָם יְיָ עַל בִּישְׁתָּא דְחָשִׁיב לְמֶעְבַּד לְעַמֵּיהּ\",0,0],[4,143,32,15,\"וְאִתְפְּנֵי וּנְחַת משֶׁה מִן טַוְורָא וּתְרֵין לוּחֵי סַהֲדוּתָא בִּידֵיהּ לוּחִין כְּתוּבִין מִתְּרֵין צִיטְרֵיהוֹן מִיכָּא וּמִיכָּא אִינוּן כְּתִיבִין\",0,0],[4,143,32,16,\"וְלוּחַיָא עוּבְדָא דַיְיָ הִינִין וּכְתָבָא כְּתָבָא דַיְיָ הוּא חָקִיק וּמְפָרַשׁ עַל לוּחַיָא\",0,0],[4,143,32,17,\"וּשְׁמַע יְהוֹשֻׁעַ יַת קַל עַמָּא כַּד מְיַבְּבִין בְּחֶדְוָא קֳדָם עִיגְלָא וַאֲמַר לְמשֶׁה קַל סִידְרֵי קְרָבָא בְּמַשְׁרִיתָא\",0,0],[4,143,32,18,\"וַאֲמַר לָא קַל גִּיבָּרִין דְּנַצְחִין בְּסִידְרֵי קְרָבָא וְלָא קַל חֲלָשִׁין דְּמִתְנַצְחִין מִן בַּעֲלֵי דְבָבֵיהוֹן בְּסִדְרֵי קְרָבָא קַל פַּלְחֵי פּוּלְחָנָא נוּכְרָאָה וּמְגַחֲכָן קַדְמָאָה אֲנָא שְׁמַע\",0,0],[4,143,32,19,\"וַהֲוָה כַּד קָרֵיב משֶׁה לְמַשְׁרִיתָא וַחֲמָא יַת עִיגְלָא וְחִינְגִין בִּידֵיהוֹן דְּרַשִׁיעַיָא מְחַנְגִין וּמְגַחֲנִין קֳדָמוֹי וְסִטְנָא הֲוָה בְּגַוֵּיהּ מְטַפֵּז וּמְשַׁוֵּור קֳדָם עַמָּא וּמִן יַד תְּקַף רָתַח רוּגְזֵיהּ דְּמשֶׁה וּטְלַק מִן יְדוֹי יַת לוּחַיָא וּתְבַר יַתְהוֹן בְּשִׁיפּוּלֵי טַוְורָא בְּרַם כְּתָבָא קַדִּישָׁא דִי בְּהוֹן הֲוָה פָּרַח וְטַיַיס לְאַוֵיר שְׁמַיָיא וַהֲוָה צָוַוח וַאֲמַר חֲבַל עַל עַמָּא דְשָׁמְעוּ בְּסִינַי מִן פּוּם קוּדְשָׁא לָא תַעַבְדוּן לְכוֹן צְלַם וְצוּרָה וְכָל דְּמוּי וּלְסוֹף אַרְבְּעִין יוֹמִין עֲבָדוּ עֵיגַל מַתְּכָא דְלֵית בֵּיהּ מַשָׁשָׁא\",0,0],[4,143,32,20,\"וּנְסִיב יַת עִיגְלָא דַעֲבָדוּ וְאוֹקֵד בְּנוּרָא וְשַׁף עַד דַּהֲוָה דָּקִיק וְדָרֵי עַל אַנְפֵּי מוֹי דְנַחֲלָא וְאַשְׁקֵי יַת בְּנֵי יִשְרָאֵל וְכָל מַאן דְּיָהַב תַּמָּן כָּל מָאנָא דְדַהֲבָא הֲוָה סִימָא נַפְקָא בְּאַנְפָּא\",0,0],[4,143,32,21,\"וַאֲמַר משֶׁה לְאַהֲרן מַה עָבַד לָךְ עַמָּא הָדֵין אֲרוּם אָתֵיתָא עֲלוֹי חוֹבָא רַבָּא\",0,0],[4,143,32,22,\"וַאֲמַר אַהֲרן לָא יִתְקֵיף רוּגְזָא דְרִבּוֹנִי אַנְתְּ יַדְעָת יַת עַמָּא אֲרוּם בְּנֵי צַדִּיקַיָא אִינוּן בְּרַם יִצְרָא בִּישָׁא הוּא דְאַטְעִינוּן\",0,0],[4,143,32,23,\"וַאֲמָרוּ לִי עִיבַד לָנָא דַחֲלָן דִּיטַיְילוּן קֳדָמָנָא אֲרוּם דֵּין משֶׁה גַבְרָא דְאַסְקָנָא מֵאַרְעָא דְמִצְרַיִם אִישְׁתַּלְהַב בְּטַוְורָא בְּאֵישָׁא מְצַלְהֲבָא מִן קֳדָם יְיָ וְלָא אִשְׁתְּמוֹדַעֲנָא מַה הֲוָה לֵיהּ בְּסֵיפֵיהּ\",0,0],[4,143,32,24,\"וַאֲמָרִית לְהוֹן לְמַאן אִית דְּהַב פְּרִיקוּ וִיהָבוּ לִי וּטְלֵיקְתֵיהּ בְּנוּרָא וְעָאַל סִטְנָא בְּגַוֵּיהּ וּנְפַק מִינֵיהּ דְּמוּת עֵיגְלָא הָדֵין\",0,0],[4,143,32,25,\"וַחֲמָא משֶׁה יַת עַמָּא אֲרוּם פְּרִיעִין הִינוּן אֲרוּם פְּרִיעוּ עַל יְדוֹי דְאַהֲרן יַת כְּלִילָא קַדִּישָׁא דַהֲוָה בְּרֵישֵׁיהוֹן וַהֲוָה שְׁמָא רַבָּא וְיַקִּירָא חָקִיק וּמְפָרַשׁ בֵּיהּ וּנְפַק טִבְּהוֹן בִּישׁ בְּעַמְמֵי אַרְעָא וְקָנוּן בְּהוֹן שׁוּם בִּישׁ לְדָרֵיהוֹן\",0,0],[4,143,32,26,\"וְקָם משֶׁה בִּתְרַע סַנְהֶדְרִין דְּמַשְׁרִיתָא וַאֲמַר מַאן הוּא דַחֲלַיָא דַיְיָ יֵיתוּן לְוָותִי וְאִתְכְּנָשׁוּ לְוָותֵיהּ כָּל בְּנוֹי דְּלֵוִי\",0,0],[4,143,32,27,\"וַאֲמַר לְהוֹן כִּדְנַן אָמַר יְיָ אֱלָהָא דְיִשְרָאֵל כָּל מַאן דְּדָבַח לְטַעֲוַת עַמְמַיָא יִתְקְטֵל בְּסַיְיפָא וּכְדוּן עִיבְרוּ וְתוּבוּ מִתְּרַע סַנְהֶדְרִין לִתְרַע בֵּי דִינָא בְּמַשְׁרִיתָא וּבְעוֹי מִן קֳדָם יְיָ דְיִשְׁתְּבֵיק לְכוֹן חוֹבָא דָא וְאִתְפְּרָעוּ מִן רַשִׁיעַיָא פַּלְחֵי פּוּלְחָנָא נוּכְרָאָה וּקְטִילוּ אֲפִלּוּ גְבַר יַת אָחוֹי וּגְבַר יַת חַבְרֵיהּ וְאֵינַשׁ יַת קָרִיבֵיהּ\",0,0],[4,143,32,28,\"וְעָבָדוּ בְנֵי לֵוִי הֵי כְּפִתְגָמָא דְמשֶׁה וּנְפָלוּ מִן עַמָּא דַּהֲוָה סִימָן בְּאַפֵּיהוֹן בִּקְטִילַת סָיְיפָא בְּיוֹמָא הַהוּא כְּמִנְיַן תְּלָתָא אַלְפִין גַּבְרָא\",0,0],[4,143,32,29,\"וַאֲמַר משֶׁה קְרִיבוּ קוּרְבָּנֵכוֹן עַל שְׁפִיכוּת אַדְמָא דִי בִידֵיכוֹן וְיִתְכַּפֵּר לְכוֹן קֳדָם יְיָ אֲרוּם נְגַעֲתּוּן גְּבַר בִּבְרֵיהּ וּבְאָחוֹי וּלְאַיְיתָאָה עֲלֵיכוֹן יוֹמָא דֵין בִּרְכָתָא\",0,0],[4,143,32,30,\"וַהֲוָה בְּיוֹמָא אָחְרִי וַאֲמַר משֶׁה לְעַמָּא אַתּוּן חַבְתּוּן חוֹבָא רַבָּא וּכְדוּן אֵיסַק וְאַצְלֵי קֳדָם יְיָ הַלְוַאי אֵיכַפֵּר עַל חוֹבֵיכוֹן\",0,0],[4,143,32,31,\"וְתַב משֶׁה וְצַלִּי קֳדָם יְיָ וַאֲמַר בְּמָטוּ מִינָךְ רִבּוֹן כָּל עָלְמַיָא גְּלֵי קֳדָמָךְ חֲשׁוֹכָא הֵי כִנְהוֹרָא וּכְדוֹן חַב עַמָּא הָדֵין חוֹבָא רַבָּא וְעָבָדוּ לְהוֹן דַּחֲלָן דִּדְהַב\",0,0],[4,143,32,32,\"וּכְדוֹן אִין תִּשְׁבּוֹק לְחוֹבֵיהוֹן שְׁבוֹק וְאִין לָא מְחֵינִי כְּדוֹן מִן סֵפֶר צַדִּיקַיָא דְּכָתַבְתָּא לִשְׁמִי בְּגַוֵּיהּ\",0,0],[4,143,32,33,\"וַאֲמַר יְיָ לְמשֶׁה לָא חֲמֵי לְמִימְחֵי שְׁמָךְ אֱלָהֵן מַאן דְּחַב קֳדָמַי אַמְחִינֵיהּ מִסִּפְרִי\",0,0],[4,143,32,34,\"וּכְדוּן אִיזֵיל דְּבַר יַת עַמָּא לַאֲתַר דְּמַלֵּילִית לָךְ הָא מַלְאָכִי יְטַיֵּיל קֳדָמָךְ וּבְיוֹם אַסְעָרוּתִי וְאַסְעַר עֲלֵיהוֹן חוֹבֵיהוֹן\",0,0],[4,143,32,35,\"וַחֲבַל מֵימְרָא דַיְיָ יַת עַמָּא עַל דְּגָחְנָן לְעִגְלָא דְעָבַד אַהֲרן\",0,0],[4,143,33,1,\"וּמַלֵּיל יְיָ עִם משֶׁה אִיזֵיל אִיסְתַּלֵּק מִכָּא דִלְמָא יִתְקֵף רְתַח רוּגְזִי בְּעַמָא וְאֵישֵׁיצִינוּן בְּגִין כֵּן טַיֵּיל אַנְתְּ וְעַמָּא דְאַסֵיקְתָּא מֵאַרְעָא דְמִצְרַיִם לְאַרְעָא דְקַיֵּימִית לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקב לְמֵימַר לִבְנָךְ אֵיתְּנִינָהּ\",0,0],[4,143,33,2,\"וְאֵיזַמֵּן קֳדָמָךְ מַלְאָךְ וְאֵיתָרֵךְ עַל יְדוֹי יַת כְּנַעֲנָאֵי אֱמוֹרָאֵי חִיתָּאֵי וּפְרִיזָאֵי חִיוָאֵי וִיבוּסָאֵי\",0,0],[4,143,33,3,\"לְאַרַע עַבְדָא חֲלָב וּדְבָשׁ אֲרוּם לֵית אֶפְשַׁר דְּאֵיסַלֵק שְׁכִינַת יְקָרִי מִבֵּינֵיכוֹן בְּרַם לָא יְהֵי יְקָרִי שְׁרֵי בְּמָדוֹר מַשְׁרִיתֵיהוֹן אֲרוּם עַם קְשֵׁי קְדַל אַנְתְּ דִּילְמָא אֵישֵׁיצִינְכוֹן בְּאָרְחָא\",0,0],[4,143,33,4,\"וּשְׁמַע עַמָּא יַת פִּתְגָּמָא בִּישָׁא הָדֵין וְאִתְאַבָּלוּ וְלָא שַׁוִּיוּ גְבַר יַת תִּיקוּן זֵינֵיהּ דְּאִתְיַהַב לְהוֹן בְּסִינַי דְבֵיהּ שְׁמָא רַבָּא וְקַדִּישָׁא חָקִיק וּמְפָרַשׁ עֲלוֹי\",0,0],[4,143,33,5,\"וַאֲמַר יְיָ לְמשֶׁה אֵימַר לִבְנֵי יִשְרָאֵל אַתּוּן עַם קְשֵׁי קְדַל שְׁעָא חֲדָא קְלִילָא אֵיסַלֵּק אִיקַר שְׁכִינְתִּי מִבֵּינָךְ וְאֵישֵׁיצִינָךְ וּכְדוֹן אַעֲדֵי תִיקוּן זֵינָךְ מִינָךְ דְּאִתְגְּלֵי קֳדָמַי מַאן אֶעֱבַד לָךְ\",0,0],[4,143,33,6,\"וְאִתְרוֹקְנוּ בְּנֵי יִשְרָאֵל מִן תִּיקוּן זֵינֵיהוֹן דִּשְׁמָא רַבָּא מְפָרַשׁ כְּתִיב בְּהוֹן דְּאִתְיַהֲבוּ לְהוֹן לְמַתָּנָה מִן טַוָור חוֹרֵב\",0,0],[4,143,33,7,\"וּמשֶׁה נְסִיבוּנוּן וּטְמִירִינוּן בְּמַשְׁכַּן אוּלְפַן אוֹרַיְיתָא דִּילֵיהּ בְּרַם יַת מַשְׁכְּנָא נָסַב מִתַּמָּן וּפַרְסֵיהּ לֵיהּ מִבָּרָא לְמַשְׁרִיתָא אַרְחִיק יָתֵיהּ מִן מַשִׁירְיַת עַמָּא דְּאִתְנְדוּן תְּרֵין אַלְפִין אַמִּין וַהֲוָה קָרֵי לֵיהּ מַשְׁכַּן בֵּית אוּלְפָנָא וַהֲוֵי כָּל מַאן דַּהֲדַר בִּתְתוּבָא בְּלֵב שְׁלִים קֳדָם יְיָ הֲוָה נָפִיק לְמַשְׁכַּן בֵּית אוּלְפָנָא דְמִבָּרָא לְמַשְׁרִיתָא מוֹדֵי עַל חוֹבֵיהּ וּמַצְלֵי עַל חוֹבֵיהּ וּמַצְלֵי וּמִשְׁתְּבֵק לֵיהּ\",0,0],[4,143,33,8,\"וַהֲוָה כַּד הֲוָה נָפִיק משֶׁה מִן מַשְׁרִיתָא וְאָזֵיל לְמַשְׁכְּנָא קַיְימִין כָּל רַשִׁיעֵי עַמָּא וּמִתְעַתְּדִין גְּבַר בִּתְרַע מַשְׁכְּנֵיהּ וּמִסְתַּכְּלִין בְּעֵינָא בִּישָׁא אֲחוּרֵי משֶׁה עַד זְמַן מֵיעֲלֵיהּ לְמַשְׁכְּנָא\",0,0],[4,143,33,9,\"וַהֲוָה כַּד אָעֵיל משֶׁה לְמַשְׁכְּנָא נָחִית עַמּוּדָא דַּעֲנָן יְקָרָא וְקָאֵי בִּתְרַע מַשְׁכְּנָא וּמִתְמַלֵּיל מֵימְרָא דַיְיָ עִם משֶׁה\",0,0],[4,143,33,10,\"וְחָמַן כָּל עַמָּא יַת עַמּוּדָא דַעֲנָנָא קָאִי בִּתְרַע מַשְׁכְּנָא וּמִן יַד קַיְימִין כָּל עַמָּא וְסַגְדִין כָּל קְבֵל מַשְׁכְּנָא כִּדְקַיְימִין גְּבַר בִּתְרַע מַשְׁכְּנֵיהּ\",0,0],[4,143,33,11,\"וּמִתְמַלֵּיל יְיָ עִם משֶׁה מַמְלֵל קְבֵל מַמְלֵל קַל דִּבּוּרָא הֲוָה שָׁמַע בְּרַם זִיו אַפִּין לָא הֲוָה חָמֵי הֵיכְמָא דִמְמַלֵּיל גְּבַר עִם חַבְרֵיהּ וּמִן בָּתַר דְּאִסְתַּלֵּק קַל דִּבּוּרָא תָּאִיב לְמַשְׁרִיתָא וּמִתְנֵי פִּתְגָמַיָא לִכְנִישְׁתְּהוֹן דְּיִשְרָאֵל בְּרַם מְשׁוּמְשָׁנֵיהּ יְהוֹשֻׁעַ בַּר נוּן הֲוָה טְלֵי לָא הֲוַת זֵייעַ מִגּוֹ מַשְׁכְּנֵיהּ\",0,0],[4,143,33,12,\"וַאֲמַר משֶׁה קֳדָם יְיָ חָמֵי מַה דְּאַנְתְּ אָמַר לִי סַלֵיק יַת עַמָּא הָדֵין וְאַנְתְּ לָא אוֹדַעְתָּנִי יַת מַאן דְּאַנְתְּ שְׁלַח עִמִּי וְאַנְתְּ בְּמֵימְרָךְ אָמַרְתְּ מַנֵית יָתָךְ בְּשׁוּם טַב וְאוּף אַשְׁכַּחְתְּ רַחֲמִין קֳדָמָי\",0,0],[4,143,33,13,\"וּכְדוּן אִין בְּבָעוּ אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ אוֹדְעַנִי כְּדוּן יַת אוֹרַח טוּבָךְ וְאִנְדַע רַחֲמָךְ הֵיךְ אַנְתְּ מְדַבֵּר עִם בְּנֵי נְשָׁא זַכָּאִין מָטֵי לְהוֹן הֵי כְחַיְיבִין וּלְחַיְיבִין הֵי כְזַכָּאִין וְתוּב זַכָּאִין מָטֵי לְהוֹן הֵי כְזָכְוַותְהוֹן וְחַיְיבִין מָטֵי לְהוֹן הֵי כְחוֹבֵיהֶן מִן בִּגְלַל דְּאַשְׁכַּח רַחֲמִין קֳדָמָךְ וּגְלֵי קֳדָמָךְ אֲרוּם עַמָּךְ עַמָּא הָדֵין\",0,0],[4,143,33,14,\"וַאֲמַר אַמְתֵּן עַד דִּיהֲכוּן סְבַר אַפִּין דְּרוּגְזָא וּמִן בָּתַר כְּדוֹן אָנוּחַ לָךְ\",0,0],[4,143,33,15,\"וַאֲמַר לֵיהּ אִין לֵית אַפִּין מְהַלְכָא מִינָנָא לָא תְסַלְקִינָנָא מִיכָּא בִּסְבַר אַפִּין דְּרוּגְזָא\",0,0],[4,143,33,16,\"וּבְמָה יִתְיְדַע כְּדוּן אֲרוּם אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ אֲנָא וְעַמָּךְ אֱלָהֵן בְּמַלָלוּת שְׁכִינְתָּךְ עִמָּן וְיִתְעַבְדָן לָנָא פְּרִישָׁן בְּסַלְקוּתָךְ רוּחַ נְבוּאָה מֵיעִילַוֵי אוּמַיָא וּתְהֵי מִתְמַלֵּיל בְּרוּחַ קוּדְשָׁא לִי וּלְעַמָּךְ מִן בִּגְלַל דְּנֵיהֵי מְשַׁנְיֵי מִכָּל עַמְמַיָא דְעַל אַנְפֵּי אַרְעָא\",0,0],[4,143,33,17,\"וַאֲמַר יְיָ לְמשֶׁה אוּף יַת פִּתְגָמָא הָדֵין דְּמַלֵּילְתָּא אֶעֱבַד אֲרוּם אַשְׁכַּחְתָּא רַחֲמִין קֳדָמַי וּמַנֵּית יָתָךְ בְּשׁוּם טַב\",0,0],[4,143,33,18,\"וַאֲמַר אַחְמֵי כְדוּן יָתִי יַת יְקָרָךְ\",0,0],[4,143,33,19,\"וַאֲמַר אֲנָא מַעֲבֵר כָּל מְכִילַת טוּבִי קֳדָמָךְ וְאֵיקְרֵי בְּשׁוּם מֵימְרֵיהּ דַּיְיָ קֳדָמָךְ וְאֵיחוּס עַל מַאן דְּחָמֵי לֵיהּ לְמֵיחוּס וְאֵירְחֵים עַל מַאן דְּחָמֵי לֵיהּ לְמִתְרַחֲמָא\",0,0],[4,143,33,20,\"וַאֲמַר לֵית אֶפְשַׁר לָךְ לְמֵיחְמֵי יַת סְבַר אַפַּי אֲרוּם לָא יַחְמִינַנִי אֵינָשָׁא וְיִתְקַיֵּים\",0,0],[4,143,33,21,\"וַאֲמַר יְיָ הָא אֲתַר מְתַקַּן קֳדָמַי וּתְהֵי מְעַתַּד עַל טִינָרָא\",0,0],[4,143,33,22,\"וִיהֵי בְּמֵיעִיבַר יְקַר שְׁכִינְתִּי וְאֵישַׁוִינָךְ בְּאַסְפְּלִידָא דְטִינְרָא וְאַגִין בְּמֵימְרִי עֲלָךְ עַד זְמַן דְּאַעִיבַּר\",0,0],[4,143,33,23,\"וְאַעֲבַּר יַת כִּיתֵּי מַלְאָכַיָא דְּקַיְימִין וּמְשַׁמְשִׁין קֳדָמַי וְתֶחְמֵי יַת קְטוֹר דְּבִידָא דִתְפִילֵי אִיקַר שְׁכִינְתִּי וְאַפֵּי אִיקַר שְׁכִינְתִּי לֵית אֶפְשָׁר לָךְ לְמֵיחְמֵי\",0,0],[4,143,34,1,\"וַאֲמַר יְיָ לְמשֶׁה פְּסָל לָךְ תְּרֵין לוּחֵי אַבְנִין הֵי כְּקַדְמָאֵי וְאֶכְתּוֹב עַל לוּחַיָא יַת פִּתְגָמַיָא דַהֲווֹ עַל לוּחַיָא קַדְמָאֵי דִי תְבַרְתָּ\",0,0],[4,143,34,2,\"וַהֲוֵי זַמִין לְצַפְרָא וְתִיסוֹק לְצַפְרָא לְטַוְורָא דְסִינַי וְתִתְעַתַּד קֳדָמַי תַּמָּן עַל רֵישׁ טוּרָא\",0,0],[4,143,34,3,\"וְאֵינַשׁ לָא יִסַק עִמָּךְ וְאוּף אֵינַשׁ לָא יִתְחָמֵי בְּכָל טַוְורָא אוּף עָנָא וְתוֹרֵי לָא יַרְעוּן כָּל קְבֵיל טַוְורָא הַהוּא\",0,0],[4,143,34,4,\"וּפְסַל תְּרֵין לוּחֵי אַבְנִין הֵי כְקַדְמָאֵי וְאַקְדִים משֶׁה בְּצַפְרָא וּסְלֵיק לְטַוְורָא דְסִינַי הֵיכְמָא דְפַקֵּיד יְיָ יָתֵיהּ וּנְסֵיב בִּידֵיהּ תְּרֵין לוּחֵי אַבְנַיָא\",0,0],[4,143,34,5,\"וְאִתְגְּלֵי יְיָ בְּעַנָנֵי אִיקַר שְׁכִינְתֵּיהּ וְאִתְעַתַּד משֶׁה עִמֵּיהּ תַּמָּן וּקְרָא משֶׁה בְּשׁוּם מֵימְרָא דַיְיָ\",0,0],[4,143,34,6,\"וְאַעֲבֵיר יְיָ שְׁכִינְתֵּיהּ עַל אַפּוֹי וּקְרָא יְיָ יְיָ אֱלָהָא רַחֲמָנָא וְחַנָנָא אֶרֶךְ רוּחַ וּקְרִיב רַחֲמִין וּמַסְגֵי לְמֶעֱבַד חֶסֶד וּקְשׁוֹט\",0,0],[4,143,34,7,\"נְטִיר חֶסֶד וְטִיבוּ לְאַלְפֵי דָרִין שָׁרֵי וְשָׁבִיק עַל חוֹבִין וּמַעֲבַר עַל מְרוֹדִין וּמְכַפֵּר עַל חַטָּאִין סְלַח לִדְתַיְיבִין לְאוֹרַיְיתָא וְלִדְלָא תַיְיבִין לָא מְזַכֵּי בְּיוֹם דִּינָא רַבָּא מַסְעַר חוֹבֵי אַבְהָן עַל בְּנִין מְרוֹדִין עַל דַּר תְּלִיתָאֵי וְעַל דַּר רְבִיעָאֵי\",0,0],[4,143,34,8,\"וְאוֹחִי משֶׁה וְגָחַן עַל אַרְעָא וּסְגִיד\",0,0],[4,143,34,9,\"וַאֲמַר אִין בְּבָעוּ אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ יְיָ תְּהַךְ כְּדוֹן שְׁכִינַת יְקָרָךְ יְיָ בֵּינָנָא אֲרוּם עַם קְשֵׁי קְדַל הוּא וְתִשְׁבּוֹק לְחוֹבָנָא וּלְחַטָּאנָא וְתַחְסְנִינָנָא יַת אַרְעָא דְקַיְימִית לְאַבְהָתָנָא דְּלָא תְשַׁלְחְפִינָנָא בְּעַם אוֹחֲרָן\",0,0],[4,143,34,10,\"וַאֲמַר הָא אֲנָא גְזַר קְיַים דְּלָא אַשַׁלְחִיף עַמָּא הָדֵין בְּעַם אוֹחְרַן בְּרַם מִינָךְ יִפְקוּן אוֹכְלוֹסִין דְּצַדִּיקִין קְבֵיל כָּל עַמָּךְ אַעֲבֵּיד פְּרִישַׁן לְהוֹן בִּזְמַן דִּיהָכוּן בְּשִׁבְיָיתָא עַל נַהַרְוַות בָּבֶל וְאֵסֵילֵיקִינוּן מִתַּמָּן וְאֵשְׁרִינוּן מִן לְגֵיו לִנְהַר סַמְבַּטְיוֹן וּכְהִינוּן פְּרִישַׁן לָא אִתְבְּרִיוּ בְּכָל דַּיְירֵי אַרְעָא וּבְכָל עַמְמַיָא וְיֶחֱמוּן כָּל עַמָּא דְאַנְתְּ שָׁרֵי בֵּינֵיהוֹן בְּיוֹמָא הַהוּא יַת עוּבְדָא דַיְיָ אֲרוּם דָּחִיל הוּא דַאֲנָא עָבִיד עִמָךְ\",0,0],[4,143,34,11,\"טוֹר לָךְ יַת מַה דַּאֲנָא מְפַקֵיד לָךְ יוֹמָא דֵין הָאֲנָא מְתָרֵיךְ מִן קֳדָמָךְ יַת אֱמוֹרָאֵי וּכְנַעֲנָאֵי וְחִתָּאֵי וּפְרִיזָאֵי וְחִיוָאֵי וִיבוּסָאֵי\",0,0],[4,143,34,12,\"אִיסְתַּמַּר לָךְ דִּילְמָא תִגְזוֹר קְיַים לְיָתֵיב אַרְעָא דְאַנְתְּ עָלֵיל עֲלָהּ דִּלְמָא יְהֵי לְתַקָּלָא בֵּינָךְ\",0,0],[4,143,34,13,\"אֲרוּם יַת אֵיגוֹרֵיהוֹן תְּתַרְעוּן וְיַת קָמַתְהוֹן תְּתַבְּרוּן וְיַת אֲשֵׁרֵיהוֹן תְּקַצְּצוּן\",0,0],[4,143,34,14,\"אֲרוּם לֵית לְכוֹן רְשׁוּ לְמִסְגוֹד לֶאֱלָהָא אוֹחֲרָן אֲרוּם יְיָ קַנַּאי וּפוּרְעַן שְׁמֵיהּ אֱלָהּ קַנְּאַי וּפוּרְעַן הוּא\",0,0],[4,143,34,15,\"דִּילְמָא תִגְזוֹר קְיַים לְיָתֵיב אַרְעָא וְיִטְעוּן בָּתַר טַעֲוַותְהוֹן וְיִדְבְּחוּן לְטַעֲוַותְהוֹן וִיזַמְנוּן לָךְ וְתֵיכוֹל מִן דִּיבְחֵי טַעֲוַותְהוֹן\",0,0],[4,143,34,16,\"וְתִיסַב מִבְּנַתְהוֹן לִבְנָךְ וְכַד טַעֲיָין בְּנַתְהוֹן בָּתַר טַעֲוַותְהֵין מַטְעֲיַין אוּף יַת בְּנָךְ בָּתַר טַעֲוַותְהֵין\",0,0],[4,143,34,17,\"דַּחֲלַן דְּמַתְּכָא לָא תַעְבְּדוּן לְכוֹן\",0,0],[4,143,34,18,\"יַת חַגָא דְפַטִירַיָא תִנְטְרוּן שׁוּבְעָא יוֹמִין תֵּיכוֹל פַּטִּירֵי הֵיכְמָא דְפַקֵידְתָּךְ לִזְמַן יַרְחָא דְאַבִּיבָא אֲרוּם בְּיַרְחָא דְאַבִּיבָא נְפַקְתּוּן פְּרִיקִין מִמִּצְרָיִם\",0,0],[4,143,34,19,\"כָּל פְּתַח וַולְדָא דִילִי הוּא וְכָל בְּעִירָךְ תַּקְדִישׁ מִנְהוֹן דִּכְרַיָא דְתוֹרֵי וְאִמְרֵי\",0,0],[4,143,34,20,\"וּבוּכְרָא דְחַמְרָא תִּפְרוֹק בְּאִימְרָא וְאִין לָא תִפְרוֹק וְתִנְקְפֵיהּ בְּקוּפִּיץ וְכָל בּוּכְרָא דִבְרָךְ תִּפְרוֹק וְלָא יִתְחֲמוּן קֳדָמַי רֵיקָנִין\",0,0],[4,143,34,21,\"שִׁיתָּא יוֹמִין תִּפְלָח וּבְיוֹמָא שְׁבִיעָאָה תָנוּחַ בְּרִידַיָא וּבְחַצְדָא תָּנוּחַ\",0,0],[4,143,34,22,\"וְחַגָא דִּשְׁבוּעַיָא תַּעֲבֵיד לָךְ בִּזְמַן בִּכּוּרֵי חֲצַד חִינְטִין וְחַגָא דִכְנָשָׁא בְּמִיפְקָא דְשַׁתָּא\",0,0],[4,143,34,23,\"תְּלַת זִמְנִין בְּשַׁתָּא יִתְחַמְיוּן כָּל דְּכוּרָךְ קֳדָם רִבּוֹן עָלְמַיָא יְיָ אֱלָהָא דְיִשְרָאֵל\",0,0],[4,143,34,24,\"אֲרוּם אֵיתָרֵיךְ עַמְמִין מִן קֳדָמָךְ וְאַפְתֵּי יַת תְּחוּמָךְ וְלָא יַחְמֵיד אֵינַשׁ יַת אַרְעָךְ בִּזְמַן מִיסְקָךְ לְאִתְחֲמָאָה קֳדָם יְיָ אֱלָהָךְ תְּלַת זִמְנִין בְּשַׁתָּא\",0,0],[4,143,34,25,\"לָא תִכְסוּן קֳדָם עַד לָא תְבַטְלִין חֲמִיעַ נִכְסַת פִּסְחִי וְלָא יְבִיתוּן לְצַפְרָא בַּר מִמַּדְבְּחָא תַּרְבֵּי נִכְסַת פִּיסְחָא\",0,0],[4,143,34,26,\"שֵׁירוּי בּוּכְרַת פֵּרֵי אַרְעֲכוֹן תַּיְיתוּן לְבֵית מוּקְדְּשָׁא דַיְיָ אֱלָהָכוֹן לֵית אַתּוּן רְשָּׁאִין לָא לִמְבַשְׁלָא וְלָא לְמֵיכוּל בְּשַר וַחֲלַב תְּרֵיהוֹן מְעַרְבִין כַּחֲדָא דְּלָא יִתְקוֹף רוּגְזִי בְּכוֹן וְאֵירְשִׁין פֵּרֵי אֵילָנֵיכוֹן עִם בּוּסְרָא בְּלִבְלוּבֵיהוֹן וְטַרְפֵיהוֹן כַּחֲדָא\",0,0],[4,143,34,27,\"וַאֲמַר יְיָ לְמשֶׁה כְּתוֹב לָךְ יַת פִּתְגָמַיָא הָאִילֵין אֲרוּם עַל מֵימַר פִּתְגָמַיָא הָאִילֵין גְּזָרִית עִמָּךְ קְיַים וְעִם יִשְרָאֵל\",0,0],[4,143,34,28,\"וַהֲוָה תַּמָּן קֳדָם יְיָ אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילַוָן לַחֲמָא לָא אָכַל וּמוֹי לָא אִשְׁתֵּי וּכְתַב עַל לוּחַיָא חוֹרַנְיָיתָא יַת פִּתְגָמֵי קַיְימָא עֲשַרְתֵּי דִבּוּרַיָא דַהֲווֹ כְתִיבִין עַל לוּחַיָא קַדְמָאֵי\",0,0],[4,143,34,29,\"וַהֲוָה בִזְמַן מֵיחַת משֶׁה מִן טַוְורָא דְסִינַי וּתְרֵין לוּחֵי דְסַהֲדוּתָא בִּידָא דְמשֶׁה בְּמֵיחְתֵיהּ מִן טַוְורָא וּמשֶׁה לָא חַכִּים אֲרוּם אִשְׁתַּבְהַר זִיו אִיקוּנִין דְּאַנְפּוֹי דַּהֲוַת לֵיהּ מִן זִיו אִיקַר שְׁכִינְתָּא דַיְיָ בִּזְמַן מַלֵלְיוּתֵיהּ עִמֵיהּ\",0,0],[4,143,34,30,\"וַחֲמָא אַהֲרן וְכָל בְּנֵי יִשְרָאֵל יַת משֶׁה וְהָא אִשְׁתַּבְהַר זִיו אִקּוּנִין דְּאַנְפּוֹי וּדְחִילוּ מִן לְמִקְרְבָא לְוָותֵיהּ\",0,0],[4,143,34,31,\"וּקְרָא לְהוֹן משֶׁה וְתָבוּ לְוָותֵיהּ אַהֲרן וְכָל רַבְרְבַיָא דְאִתְמְנוּן נְגוֹדִין בִּכְנִישְׁתָּא וּמַלֵיל משֶׁה עִמְהוֹן\",0,0],[4,143,34,32,\"וּמִבָּתַר כְּדֵין אִיתְקְרִיבוּ כָּל בְּנֵי יִשְרָאֵל וּפַקֵּידִינוּן יַת כָּל מַה דְּמַלֵּיל יְיָ עִמֵּיהּ בְּטַוְורָא דְסִינַי\",0,0],[4,143,34,33,\"וּפְסַק משֶׁה מִן לְמַלָלָא עִמְהוֹן וִיהַב עַל אִיקוּנִין דְּבֵית אַנְפּוֹי סוּדָרָא\",0,0],[4,143,34,34,\"וְכַד עָלֵיל משֶׁה לִקְדָם יְיָ לְמַלָלָא עִמֵּיהּ מַעְדֵי יַת סוּדְרָא דְעַל אִיקוּנִין דְּבֵית אַנְפּוֹי עַד מִיפְקֵיהּ וְנָפֵיק וּמְמַלֵּיל עִם בְּנֵי יִשְרָאֵל יַת מַה דְּאִתְפַּקֵּד\",0,0],[4,143,34,35,\"וְחַמְיַין בְּנֵי יִשְרָאֵל יַת אִיקוּנִין דְּמשֶׁה אֲרוּם אִשְׁתַּבְהַר זִיו אִיקוּנִין דְּאַנְפֵּי משֶׁה וְאָתֵיב משֶׁה יַת סוּדְרָא עַל בֵּית אַפּוֹי עַד זְמַן מֵיעֲלֵיהּ לְמַלָלָא עִמֵּיהּ\",0,0],[4,143,35,1,\"ויקהל וּכְנַשׁ משֶׁה יַת כָּל כְּנִישְׁתָּא דִבְנֵי יִשְרָאֵל וַאֲמַר לְהוֹן אִלֵּין פִּתְגָמַיָא דְפַקֵיד יְיָ לְמֶעֱבַּד יַתְהוֹן\",0,0],[4,143,35,2,\"שִׁיתָּא יוֹמִין תִּתְעֲבֵיד עִיבִידְתָּא וּבְיוֹמָא שְׁבִיעָאָה יְהֵי לְכוֹן קוּדְשָׁא שַׁבְּתָא נְיָיחָא קֳדָם יְיָ כָּל דְּיַעֲבֵיד עִיבִידְתָּא בְּיוֹמָא דְשַׁבַּתָּא אִתְקְטָלָא יִתְקְטֵיל בְּמַטְלִית אַבְנִין\",0,0],[4,143,35,3,\"עַמִּי בְּנֵי יִשְרָאֵל לָא תְבַעֲרוּן אֵישָׁתָא בְּכָל אֲתַר מוֹתְבָנֵיכוֹן בְּיוֹמָא דְשַׁבַּתָּא\",0,0],[4,143,35,4,\"וַאֲמַר משֶׁה לְכָל כְּנִישְׁתָּא דִבְנֵי יִשְרָאֵל לְמֵימַר דֵּין פִּתְגָּמָא דְפַקֵּיד יְיָ לְמֵימָר\",0,0],[4,143,35,5,\"סָבוּ מִנְכוֹן אַפְרָשׁוּתָא קֳדָם יְיָ כָּל מַאן דְּאִתְרְעֵי לִבֵּיהּ יַיְתֵי יַת אַפְרָשׁוּתָא דַיְיָ דַהֲבָא וְכַסְפָּא וּנְחָשָׁא\",0,0],[4,143,35,6,\"וְתִכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי וּבוּץ וּמֵעַזֵּי\",0,0],[4,143,35,7,\"וּמַשְׁכֵי דְדִיכְרֵי מְסַמְקֵי וּמַשְׁכֵי דְסַסְגוֹנָא וְקֵיסֵי דְשִׁיטָא\",0,0],[4,143,35,8,\"וּמִשְׁחָא לְאַנְהָרוּתָא וּבוּשְמַיָא לִמְשַׁח רְבוּתָא וְלִקְטוֹרֶת בּוּסְמַיָא\",0,0],[4,143,35,9,\"מַרְגַלְיַין דְּבוּרְלִין הִינוּן וּמַרְגַּלְיַין דְּאַשְׁלָמוּתָא לִמְשַׁקְעָא בְּאֵפוֹדָא וּבְחוּשְׁנָא\",0,0],[4,143,35,10,\"וְכָל חַכִּימֵי לִבָּא דִבְכוֹן יֵיתוּן וְיַעַבְּדוּן יַת דְּפַקֵּיד יְיָ\",0,0],[4,143,35,11,\"יַת מַשְׁכְּנָא יַת פְּרָסֵיהּ וְיַת חוֹפָאָה דִילֵיהּ יַת פּוּרְפוֹי וְיַת לוּחוֹי יַת נַגְרוֹי וְיַת עַמּוּדוֹי וְיַת חוֹמְרוֹי\",0,0],[4,143,35,12,\"יַת אֲרוֹנָא וְיַת אֲרִיחוֹי וְיַת כַּפּוּרְתָּא וְיַת פַּרְגוֹדָא דִפְרָסָא\",0,0],[4,143,35,13,\"יַת פָּתוֹרָא וְיַת אֲרִיחוֹי וְיַת כָּל מָנוֹי וְיַת לְחֵם דְּאַפַּיָא\",0,0],[4,143,35,14,\"וְיַת מְנַרְתָּא דְאַנְהוֹרֵי וְיַת מָנָהָא וְיַת בּוֹצִינָהָא וְיַת מִשְׁחָא דְאַנְהָרוּתָא\",0,0],[4,143,35,15,\"וְיַת מַדְבְּחָא דִקְטוֹרֶת בּוּסְמַיָא וְיַת אֲרִיחוֹי וְיַת מִישְׁחָא דִרְבוּתָא וְיַת קְטוֹרֶת בּוּסְמַיָא וְיַת פָּרָסָא דְתַרְעָא לִתְרַע מַשְׁכַּן זִימְנָא\",0,0],[4,143,35,16,\"יַת מַדְבְּחָא דַעֲלָתָא וְיַת קַנְקַל דִּנְחָשָׁא דִילֵיהּ יַת אֲרִיחוֹי וְיַת כָּל מָנוֹי וְיַת כִּיּוֹרָא וְיַת בְּסִיסֵיהּ\",0,0],[4,143,35,17,\"יַת וָוִילְוַת דַּרְתָּא יַת עַמּוּדוֹי וְיַת חוֹמַרְנָהָא וְיַת פְּרָסָא דִתְרַע דַּרְתָּא\",0,0],[4,143,35,18,\"יַת מַחְתֵּי מַשְׁכְּנָא וְיַת מַחְתֵּי דַרְתָּא וְיַת אֲטוּנֵיהוֹן\",0,0],[4,143,35,19,\"יַת לְבוּשֵׁי שִׁמּוּשָׁא לְשַׁמָּשָׁא בְּקוּדְשָׁא יַת לְבוּשֵׁי קוּדְשָׁא דִּלְאַהֲרן כַּהֲנָא וְיַת לְבוּשֵׁי בְּנוֹי לְשַׁמָּשָׁא\",0,0],[4,143,35,20,\"וּנְפָקוּ כָּל כְּנִישְׁתָּא דִבְנֵי יִשְרָאֵל מִן קֳדָם משֶׁה\",0,0],[4,143,35,21,\"וְאָתוֹ כָּל גְּבַר דְּאִתְרְעֵי לִבֵּיהּ וְכָל דְּאַשְׁלֵמִית רוּחֵיהּ בִּנְבוּאָתָא דְעִמֵּיהּ הַיְתִיוּ יַת אַפְרָשׁוּתָא לִקְדָם יְיָ לְעִיבִידַת מַשְׁכַּן זִימְנָא וּלְכָל פּוּלְחָנֵיהּ וְלִלְבוּשֵׁיהּ קוּדְשָׁא\",0,0],[4,143,35,22,\"וְאָתוּ גוּבְרַיָא עִם נְשַׁיָא כָּל מַאן דְּאִתְרְעֵי לִבֵּיהּ הַיְתִיוּ שִׁירִין וְשִׁיוְוִין עִזְקַן וּמְחוֹכִין וְכָל תַּכְשִׁיט דִּדְהַב וְכָל גְבַר דְּאֲרִים אֲרָמוּת דַּהֲבָא קֳדָם יְיָ\",0,0],[4,143,35,23,\"וְכָל גְּבַר דְּהִשְׁתַּכַּח עִמֵּיהּ תִּכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי וּבוּץ וּמְעִיזֵי וּמַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וּמַשְׁכֵי סַסְגוֹנָא הַיְיתִיוּ\",0,0],[4,143,35,24,\"כָּל דְּאָרִים אֲרָמוּת כַּסְפָּא וּנְחָשָׁא הַיְתִיוּ יַת אַפְרָשׁוּתָא קֳדָם יְיָ וְכָל מַאן דְּהִשְׁתַּכַּח עִמֵּיהּ קִיסִין דְּשִׁיטָא לְכָל עִיבִידַת פּוּלְחָנָא הַיְתִיוּ\",0,0],[4,143,35,25,\"וְכָל אִיתְּתָא חַכִּימַת לִבָּהָא בִידָהָא הֲוַת עַזְלָא וּמַתְיָין כַּד עָזִיל יַת תִּכְלָא וְיַת אַרְגְּוָונָא וְיַת צְבַע זְהוֹרִי וְיַת בּוּצָא\",0,0],[4,143,35,26,\"וְכָל נְשַׁיָא דְאִתְרְעֵי לִבְּהוֹן עִמְהוֹן בְּחָכְמְתָא הֲווֹן עַזְלָן יַת מְעִיזַיָא עַל גְּוִיַיתְהוֹן וּמְנַפְסִין יַתְהֵן כַּד הִינוּן חַיִּין\",0,0],[4,143,35,27,\"וַעֲנַנֵי שְׁמַיָא אָזְלִין לְפִישׁוֹן וְדַלְיַין מִתַּמָּן יַת אַבְנֵי בּוּרְלְוַת חֵילָא וְיַת אַבְנֵי אַשְׁלָמוּתָא לְשַׁקְעָא בְּאֵיפוֹדָא וּבְחוּשְׁנָא וּמַחְתַן יַתְהוֹן בְּאַנְפֵּי מַדְבְּרָא אָזְלִין רַבְרְבָנֵי יִשְרָאֵל וּמַיְיתַן יַתְהוֹן לִצְרוֹךְ עִיבִידְתָּא\",0,0],[4,143,35,28,\"וְתַיְבִין עֲנָנֵי שְׁמַיָא וְאָזְלִין לְגַן עֵדֶן וְנַסְבִין מִתַּמָּן יַת בּוּשְמָא בְּחִירָא וְיַת מִשְׁחָא דְזֵיתָא לְאַנְהָרוּתָא וְיַת אַפַרְסְמָא דַכְיָא לִמְשַׁח רְבוּתָא וְלִקְטוֹרֶת בּוּסְמַיָא\",0,0],[4,143,35,29,\"כָּל גְּבַר בַּר יִשְרָאֵל וְאִתְּתָא בַת יִשְרָאֵל דְּאִתְרְעֵי לִבְּהוֹן עִמְהוֹן לְאַיְיתָאָה לְכָל עִיבִידְתָּא דְפַקֵּיד יְיָ לְמֶעֱבַד בִּידָא דְמשֶׁה הַיְתִיוּ בְּנֵי יִשְרָאֵל נְדַבְתָּא קֳדָם יְיָ\",0,0],[4,143,35,30,\"וַאֲמַר משֶׁה לִבְנֵי יִשְרָאֵל חָמוֹן דְּמַנֵי יְיָ בְּשׁוּם טַב בְּצַלְאֵל בַּר אוּרִי בַּר חוּר לְשִׁבְטָא דִיהוּדָא\",0,0],[4,143,35,31,\"וְאַשְׁלֵים עִמֵּיהּ רוּחַ נְבוּאָה מִן קֳדָם יְיָ בְּחוּכְמָתָא בְּסוּכְלְתָנוּ וּבְמַנְדְּעָא וּבְכָל עִיבִידְתָּא\",0,0],[4,143,35,32,\"וּלְאַלָפָא אוּמַנְוָון לְמֶעֱבַד בְּדַהֲבָא וּבְכַסְפָּא וּבִנְחָשָׁא\",0,0],[4,143,35,33,\"וּבְאַגְלָפוּת מַרְגְּלִיתָא טַבְתָא לְאַשְׁלָמוּת בְּהוֹן יַת עִיבִידְתָּא וּבְנַגָּרוּת קִיסָא לְמֶעֱבַד בְּכָל עִיבִידַת אוּמַנְוָון\",0,0],[4,143,35,34,\"וּלְמֵילַף אוּמַנְוָותָא לְמִשְׁאַר אוּמַנְיָא יְהַב מַנְדְּעָא בְּלִבֵּיהּ הוּא וְאָהֳלִיאָב בַּר אֲחִיסָמָךְ לְשִׁבְטָא דְדָן\",0,0],[4,143,35,35,\"אַשְׁלִים עִמְהוֹן חַכִּימוּת לִבָּא לְמֶעֱבַד כָּל עִיבִידַת נַגַר וְאוּמָן וְצַיַיר בְּתִיכְלָא וּבְאַרְגְּוָונָא וּבִצְבַע זְהוֹרֵי וּבְבוּצָא וְגַרְדֵי עַבְדֵי כָּל עִיבִידְתָּא וּמַלְפֵי אוּמַנְוָון\",0,0],[4,143,36,1,\"וַעֲבַד בְּצַלְאֵל וְאָהֳלִיאָב וְכָל גְּבַר חַכִּים לִבָּא דִּיהַב יְיָ חוּכְמָתָא וְסוּכְלְתָנוּתָא בְּהוֹן לְמִידַע וּלְמֶעֱבַד יַת כָּל עִיבִידַת פּוּלְחַן קוּדְשָׁא לְכָל מַה דְּפַקֵּיד יְיָ\",0,0],[4,143,36,2,\"וּקְרָא משֶׁה לִבְצַלְאֵל וּלְאָהֳלִיאָב וּלְכָל גְּבַר חַכִּים לִבָּא דִיהַב יְיָ חָכְמְתָא בְּלִבֵּיהּ כָּל מַאן דְּאִתְרְעֵי לִבֵּיהּ לְמִקְרַב לְעִיבִידְתָּא לְמֶעֱבַד יָתָהּ\",0,0],[4,143,36,3,\"וּנְסִיבוּ מִן קֳדָם משֶׁה יַת כָּל אַפְרָשׁוּתָא דְאַיְיתִיוּ בְּנֵי יִשְרָאֵל לְעִיבִידַת פּוּלְחַן קוּדְשָׁא לְמֶעֱבַד יָתָהּ וְהִינוּן מַיְיתִין לֵיהּ תּוּב נְדַבְתָּא בִּצְפַר בִּצְפָר מִן מָמוֹנְהוֹן\",0,0],[4,143,36,4,\"וְאָתוּ כָּל חַכִּימַיָא דְעָבְדִין יַת כָּל עִיבִידַת קוּדְשָׁא גְּבַר גְּבַר מֵעִבִידְתֵּיהּ דְּהִינוּן עָבְדִין\",0,0],[4,143,36,5,\"וַאֲמָרוּ לְמשֶׁה מַסְגְּיַין עַמָּא לְמַיְיתַיָא מִיסַת פּוּלְחָנָא לְעִיבִידְתָּא דְפַקֵּיד יְיָ לְמֶעֱבַד יָתָהּ\",0,0],[4,143,36,6,\"וּפַקֵּיד משֶׁה וְאַעֲבָרוּ כְרוֹזָא בְּמַשְׁרִיתָא לְמֵימָר גְּבַר וְאִתְּתָא לָא יַעַבְדוּן תּוּב עִיבִידְתָּא לְאַפְרָשׁוּת קוּדְשָׁא וּפְסַק עַמָּא מִלְאַיְתָאָה\",0,0],[4,143,36,7,\"וְעִיבִידְתָּא הֲוַת כְּמֵיסַת לְכָל עִבִידְתָּא וַעֲבָדוּ יָתָהּ וּבְרַם שַׁיְירוּ\",0,0],[4,143,36,8,\"וַעֲבָדוּ כָּל חַכִּימֵי לִבָּא יַת מַשְׁכְּנָא עֲשַר יְרִיעַן דְּבוּץ שְׁזִיר וְתִכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרִי צוּרַת כְּרוּבִין עוֹבַד אוּמַן עֲבַד יַתְהוֹן\",0,0],[4,143,36,9,\"אוּרְכָּא דִירִיעֲתָא חֲדָא עַשְרִין וְתַמְנֵי אַמִּין וּפוּתְיָא אַרְבַּע אַמִּין סְכוּם דִּירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לְכָל יְרִיעָתָא\",0,0],[4,143,36,10,\"וְלָפֵיף יַת חָמֵשׁ יְרִיעַן חֲדָא עִם חֲדָא וְחָמֵשׁ יְרִיעַן לָפֵיף חֲדָא עִם חֲדָא\",0,0],[4,143,36,11,\"וְעָבַד עֲנוּבִין דְּתִכְלָא עַל שִפְתָא דִירִיעֲתָא חֲדָא מִסִּטְרָא בֵּית לוֹפֵי כֵּן עָבַד בְּשִפְתָא דִירִיעֲתָא בֵּית לוֹפֵי תִּנְיָינָא\",0,0],[4,143,36,12,\"חַמְשִׁין עֲנוּבִין עָבַד בִּירִיעֲתָא חֲדָא וְחַמְשִׁין עֲנוּבִין עָבַד בְּסִטְרָא דִירִיעֲתָא דְבֵית לוֹפֵי תִנְיָינָא מְכַוְונַן עֲנוּבַיָא חֲדָא לְקָבֵל חֲדָא\",0,0],[4,143,36,13,\"וְעָבַד חַמְשִׁין פּוּרְפִין דִּדְהַב וְלָפֵיף יַת יְרִיעֲתָא חֲדָא עִם חֲדָא בְּפוּרְפַּיָא וַהֲוָה מַשְׁכְּנָא חָד\",0,0],[4,143,36,14,\"וַעֲבַד יְרִיעַן דְּמֵעַזֵּי לִפְרָסָא עַל מַשְׁכְּנָא חַד סְרֵי יְרִיעַן עֲבַד יַתְהוֹן\",0,0],[4,143,36,15,\"אוּרְכָּא דִירִיעֲתָא חֲדָא תְּלָתִין אַמִּין וְאַרְבַּע אַמִּין פּוּתְיָא דִירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לְחַד סְרֵי יְרִיעַן\",0,0],[4,143,36,16,\"וְלָפֵיף יַת חֲמֵשׁ יְרִיעַן לְחוֹד כָּל קְבֵיל חַמְשָׁא סִפְרֵי אוֹרַיְיתָא וְיַת שִׁית יְרִיעַן לְחוֹד כָּל קְבֵיל שִׁתָּא סִדְרֵי מַתְנְיָיתָא\",0,0],[4,143,36,17,\"וַעֲבַד עֲנוּבִין חַמְשִׁין עַל שִפְתָא דִירִיעֲתָא בְּצִטְרָא בֵּית לוֹפֵי וְחַמְשִׁין עֲנוּבִין עֲבַד עַל שִפְתָא דִירִיעֲתָא דְּבֵית לוֹפֵי תִּנְיָינָא\",0,0],[4,143,36,18,\"וַעֲבַד פּוּרְפִּין דִּנְחָשָׁא לְלַפְּפָא יַת מַשְׁכְּנָא לְמֶהֱוֵי חָד\",0,0],[4,143,36,19,\"וַעֲבַד חוֹפָאָה לְמַשְׁכְּנָא מַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וּמַשְׁכֵי דְסַסְגוֹנָא לְטַלְלָא מִלְעֵילָא\",0,0],[4,143,36,20,\"וַעֲבַד יַת לוּחַיָא לְמַשְׁכְּנָא מִן קִיסֵי שִׁיטָא קַיְימִין הֵי כְאוֹרַח נְצִיבְהוֹן\",0,0],[4,143,36,21,\"עֲשַר אַמִּין אוּרְכָּא דְלוּחָא וְאַמְתָא וּפַלְגָא דְאַמְתָא פּוּתְיָא דְלוּחָא חָד\",0,0],[4,143,36,22,\"תְּרֵין צִירִין לְלוּחָא חָד מְכַוְונָן סְטַר חַד בְּגוֹ סְטַר חַד הֵיכְדֵין עָבַד לְכָל לוּחֵי מַשְׁכְּנָא\",0,0],[4,143,36,23,\"וַעֲבַד יַת לוּחַיָא לְמַשְׁכְּנָא עֶשְרִין לוּחִין לְרוּחַ עִיבַר דְּרוֹמָא\",0,0],[4,143,36,24,\"וְאַרְבְּעִין חוֹמְרִין דִּכְסַף עֲבַד תְּחוֹת עֶשְרִין לוּחַיָא תְּרֵין חוֹמְרִין תְּחוֹת לוּחָא חָד לִתְרֵין צִירוֹי וּתְרֵין חוֹמְרִין תְּחוֹת לוּחָא חָד לִתְרֵין צִירוֹי\",0,0],[4,143,36,25,\"וְלִסְטַר מַשְׁכְּנָא תִּנְיָינָא לְרוּחַ צִפּוּנָא עָבַד עֶשְרִין לוּחִין\",0,0],[4,143,36,26,\"וְאַרְבְּעִין חוֹמְרֵיהוֹן דִּכְסַף תְּרֵין חוֹמְרִין תְּחוֹת לוּחָא חָד וּתְרֵין חוֹמְרִין תְּחוֹת לוּחָא חָד\",0,0],[4,143,36,27,\"וְלִסְיָיפֵי מַשְׁכְּנָא מַעַרְבָא עָבַד שִׁתָּא לוּחִין\",0,0],[4,143,36,28,\"וּתְרֵין לוּחִין עָבַד לְזַוְויַת מַשְׁכְּנָא בְּסוֹפֵיהוֹן\",0,0],[4,143,36,29,\"וַהֲווֹן מְזַוְוגִין מִלְרַע וְכַחֲדָא הֲווֹן מְזַוְוגִין בְּרֵישֵׁיהוֹן בְּעִזְקָתָא חֲדָא הֵיכְדֵין עָבַד לִתְרֵיהוֹן לְתַרְתֵּין זִוְויַין\",0,0],[4,143,36,30,\"וַהֲווֹן תְּמַנְיָא לוּחִין וְחוֹמְרֵיהוֹן דִּכְסַף שִׁיתְּסַר חוֹמְרִין תְּרֵין חוֹמְרִין תְּרֵין חוֹמְרִין תְּחוֹת לוּחָא חָד\",0,0],[4,143,36,31,\"וַעֲבַד נַגְרִין דְּקִיסֵי שִׁיטָא חַמְשָׁא לְלוּחֵי סְטַר מַשְׁכְּנָא חָד\",0,0],[4,143,36,32,\"וְחַמְשָׁא נַגְרִין לְלוּחֵי סְטַר מַשְׁכְּנָא תִּנְיָינָא וְחַמְשָׁא נַגְרִין לְלוּחֵי סְטַר מַשְׁכְּנָא לְסוֹפֵיהוֹן מַעַרְבָא\",0,0],[4,143,36,33,\"וַעֲבַד יַת נַגְרָא מְצִיעָאָה לְשַׁלְבְּשָׁא בְּגוֹ לוּחַיָיא מִן סְיָיפֵי לִסְיָיפֵי מִן אִילָנָא דִנְצִיב אַבְרָהָם אָבוּנָן בְּבֵירָא דְשָׁבַע וְצַלִי תַּמָּן בְּשׁוּם מֵימְרָא דַיְיָ אֱלָהָא עַלְמָא\",0,0],[4,143,36,34,\"וְיַת לוּחַיָא חָפָא דַהֲבָא וְיַת עִזְקַתְהוֹן עָבַד דַּהֲבָא אַתְרָא לְנַגְרִין וַחֲפָא יַת נַגְרִין דַּהֲבָא\",0,0],[4,143,36,35,\"וַעֲבַד יַת פַּרְגּוֹדָא דְתִיכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד אוּמַן עָבָד יָתָהּ כְּרוּבִין צִיּוּרִין\",0,0],[4,143,36,36,\"וַעֲבַד לָהּ אַרְבְּעָה עַמּוּדֵי קֵיסֵי שִׁיטָא וַחֲפָנוּן דַּהֲבָא וָוֵיהוֹן דַּהֲבָא וְאָתִיךְ לְהוֹן אַרְבְּעָא חוֹמְרִין דִּכְסָף\",0,0],[4,143,36,37,\"וַעֲבַד וִילוֹן פָּרִיס לִתְרַע מַשְׁכְּנָא דְתִכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד צִיּוּר\",0,0],[4,143,36,38,\"וְיַת עַמּוּדוֹי חַמְשָׁא וְיַת וָוֵיהוֹן וְחָפֵי רֵישֵׁיהוֹן וְכִבּוּשֵׁיהוֹן דַּהֲבָא וְחוֹמְרֵיהוֹן חַמְשָׁא דִנְחָשָׁא\",0,0],[4,143,37,1,\"וְעָבַד בְּצַלְאֵל יַת אֲרוֹנָא דְקִיסֵי שִׁיטָא תַּרְתֵּין אַמִּין וּפַלְגָא אוּרְכֵּיהּ וְאַמְתָא וּפַלְגָא פּוּתְיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵיהּ\",0,0],[4,143,37,2,\"וְחַפְיֵיהּ דְּהַב דְּכֵי מִגֵּיו וּמִבָּרָא וְעָבַד לֵיהּ דֵּיר דִּדְהַב חֲזוֹר חֲזוֹר\",0,0],[4,143,37,3,\"וְאַתִּיךְ לֵיהּ אַרְבַּע עִזְקַן דִּדְהַב עַל אַרְבַּע אִסְתַּוָורוֹי וְתַרְתֵּין עִזְקַן עַל סִטְרֵיהּ חָד וְתַרְתֵּין עִזְקַן עַל סִטְרֵיהּ תִּנְיָינָא\",0,0],[4,143,37,4,\"וְעָבַד אֲרִיחֵי דְקִיסָא שִׁיטָא וַחֲפָא יַתְהוֹן דַּהֲבָא\",0,0],[4,143,37,5,\"וְאָעֵיל יַת אֲרִיחַיָא בְּעִזְקָתָא עַל סִטְרָא דַאֲרוֹנָא לְמֵיטַל יַת אֲרוֹנָא\",0,0],[4,143,37,6,\"וְעָבַד כַּפּוּרְתָּא דִדְהַב דְּכֵי תַּרְתֵּין אַמִּין וּפַלְגָא אוּרְכָּא וְאַמְתָא וּפַלְגָא פּוּתְיָא בְּרַם סוּמְכָא הֲוַת פּוּשְׁכָא\",0,0],[4,143,37,7,\"וְעָבַד תְּרֵין כְּרוּבִין דִּדְהַב דְּכֵי נְגִיד עָבַד יַתְהוֹן מִתְּרֵין סִטְרֵי כַּפּוּרְתָּא\",0,0],[4,143,37,8,\"כְּרוּבָא חָד מִסִטְרָא מִכָּא וּכְרוּבָא חָד מִסִטְרָא מִכָּא נְגִידִין וְאַדִּיקִין הֲווֹן כְּרוּבַיָא וְלָא מִתְפַּרְשִׁין מִן כַּפּוּרְתָּא אֲרוּם בְּחוּכְמַת רוּחַ נְבוּאָה עָבַד יַת כְּרוּבַיָא מִתְּרֵין סִטְרוֹי\",0,0],[4,143,37,9,\"וַהֲווֹן כְּרוּבַיָא פְּרִיסִין גַּדְפֵיהוֹן בַּהֲדֵי רֵישֵׁיהוֹן לְעֵילָא מְטַלְלִין בְּגַדְפֵיהוֹן עַל כַּפּוּרְתָּא וְאַפֵּיהוֹן חַד לִקְבֵיל חָד כָּל קֳבֵיל כַּפּוּרְתָּא הֲווֹן אַנְפֵּי כְּרוּבַיָא\",0,0],[4,143,37,10,\"וְעָבַד יַת פָּתוֹרָא דְקִיסֵי שִׁיטָא תַּרְתֵּין אַמִּין אוּרְכֵּיהּ וְאַמְתָא פּוּתְיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵיהּ\",0,0],[4,143,37,11,\"וַחֲפָא יָתֵיהּ דְּהַב דְּכֵי וְעָבַד לֵיהּ דֵּיר דִּדְהַב חֲזוֹר חֲזוֹר\",0,0],[4,143,37,12,\"וְעָבַד לֵיהּ גִּפּוּף רוּמֵיהּ פּוּשְׁכָא חֲזוֹר חֲזוֹר וְעָבַד דֵּיר דִּדְהַב לְגַפוּפֵיהּ חֲזוֹר חֲזוֹר\",0,0],[4,143,37,13,\"וְאַתִּיךְ לֵיהּ אַרְבַּע עִזְקַן דִּדְהַב וִיהַב יַת עִזְקָתָא עַל אַרְבַּע זִוְיָתָא דִלְאַרְבַּע רִגְלוֹי\",0,0],[4,143,37,14,\"כָּל קְבֵיל גִּפּוֹף הֲוָאָה עִזְקָתָא אַתְרָא לַאֲרִיחַיָא לְמֵיטַל יַת פָּתוֹרָא\",0,0],[4,143,37,15,\"וַעֲבַד יַת אֲרִיחַיָא דְקִיסֵי שִׁיטָא וַחֲפָא יַתְהוֹן דַּהֲבָא לְמֵיטַל יַת פָּתוֹרָא\",0,0],[4,143,37,16,\"וַעֲבַד יַת מָנַיָא דְעַל פָּתוֹרָא יַת פְּיַלְוָותֵיהּ וְיַת בָּזִיכוֹי וְיַת מְכִילָתֵיהּ וְיַת קַסְוָותָא דִמְחַפְיַין בְּהוֹן דִּדְהַב דְּכֵי\",0,0],[4,143,37,17,\"וַעֲבַד יַת מְנַרְתָּא דִּדְהַב דְּכֵי נְגִיד עֲבַד יַת מְנַרְתָּא בָּסִיס דִּידָהּ וּקְנָהָא כַּלִידָהָא חֲזוֹרְיָיהָא וְשׁוֹשַׁנְהָא מִינָהּ הֲווֹן\",0,0],[4,143,37,18,\"וְשִׁתָּא קְנִין נַפְקִין מִסִטְרָהָא תְּלָתָא קְנֵי מְנַרְתָּא מִסִּטְרָא חָד וּתְלָתָא קְנֵי מְנַרְתָּא מִסִּטְרָא תִּנְיָנָא\",0,0],[4,143,37,19,\"תְּלָתָא כַּלִידִין מְשַׁקְעִין בְּצִיּוֹרֵיהֶן בְּקַנְיָא חָד חֲזוֹר וְשׁוֹשַׁן וּתְלָתָא כַּלִידִין מְשַׁקְעִין בְּצִיּוֹרֵיהֶן בְּקַנְיָא חָד חֲזוֹר וְשׁוֹשַׁן הֵיכְדֵין לְשִׁתָּא קְנִין דְּנַפְקִין מִן מְנַרְתָּא\",0,0],[4,143,37,20,\"וּבִמְנַרְתָּא אַרְבָּעָא כַּלִידִין מְשַׁקְעִין בְּצִיּוּרֵיהֶן חִיזוּרָהָא וְשׁוֹשַׁנָהָא\",0,0],[4,143,37,21,\"וְחֵיזוּר תְּחוֹת תְּרֵין קְנִין דְּמִינָהּ וְחֵיזוּר תְּחוֹת תְּרֵין קְנִין דְּמִינָהּ וְחֵיזוּר תְּחוֹת תְּרֵין קְנִין דְּמִינָהּ לְשִׁתָּא קְנִין דְּנַפְקִין מִינָהּ\",0,0],[4,143,37,22,\"חִיזוּרֵיהוֹן וּקְנֵיהוֹן מִינָהּ הֲווֹ כּוּלָה נְגִידָא חֲדָא דִדְהַב דְּכֵי\",0,0],[4,143,37,23,\"וַעֲבַד יַת בּוֹצִינָהָא שַׁבְעָא וּמַלְקְטְיָיהָא וּמַחְתְּיָיהָא דִדְהַב דְּכֵי\",0,0],[4,143,37,24,\"קַנְטִינָר דִּדְהַב דְּכֵי עָבַד יָתָהּ וְיַת כָּל מָנָהָא\",0,0],[4,143,37,25,\"וַעֲבַד יַת מַדְבְּחָא דִקְטוֹרֶת בּוּסְמַיָא מִן קִיסֵי שִׁיטָא אַמְתָא אוּרְכֵּיהּ וְאַמְתָא פּוּתְיֵיהּ מְרַבַּע וְתַרְתֵּין אַמִּין רוּמֵיהּ מִינֵיהּ הֲווֹן קַרְנוֹי זְקִיפִין\",0,0],[4,143,37,26,\"וַחֲפָא יָתֵיהּ דְּהַב דְּכֵי יַת אִיגְרֵיהּ וְיַת כּוֹתְלוֹי חֲזוֹר חֲזוֹר וְיַת קַרְנוֹי וְעָבַד לֵיהּ דֵּיר דִּדְהַב חֲזוֹר חֲזוֹר\",0,0],[4,143,37,27,\"וְתַרְתֵּין עִזְקַן דִּדְהַב עָבַד לֵיהּ מִלְרַע לְדֵירֵיהּ עַל תְּרֵין זִיוְיָתֵיהּ עַל תְּרֵין סִיטְרוֹי לְאַתְרָא לַאֲרִיחַיָא לְמֵיטוֹל יָתֵהּ בְּהוֹן\",0,0],[4,143,37,28,\"וַעֲבַד יַת אֲרִיחַיָא דְקִיסֵי שִׁיטָא וַחֲפָא יַתְהוֹן דַּהֲבָא\",0,0],[4,143,37,29,\"וַעֲבַד יַת מִשְׁחָא דִרְבוּתָא קוּדְשָׁא וְיַת קְטוֹרֶת בּוּסְמַיָא דְכֵי עוֹבַד בּוּסְמָנוּ\",0,0],[4,143,38,1,\"וַעֲבַד יַת מַדְבְּחָא דְעָלָתָא דְקִיסֵי שִׁיטָא חֲמֵשׁ אַמִּין אוּרְכֵּיהּ וַחֲמֵשׁ אַמִּין פּוּתְיֵהּ מְרַבַּע וּתְלַת אַמִּין רוּמֵיהּ\",0,0],[4,143,38,2,\"וְעָבַד קַרְנוֹי עַל אַרְבַּע זִוְיָיתֵיהּ מִנֵיהּ הֲוָואָה קַרְנוֹי זְקִיפִין לְעֵיל וַחֲפָא יָתֵיהּ נְחָשָׁא\",0,0],[4,143,38,3,\"וְעָבַד יַת כָּל מָנֵי מַדְבְּחָא יַת דּוּדְוָתַיָא וְיַת מִגְרוֹפְיָתָא וְיַת מִזְרְקַיָא וְיַת מַשִׁילְיָתָא וְיַת מַחְתְּיָתָא לְכָל מָנוֹי עָבַד נְחָשָׁא\",0,0],[4,143,38,4,\"וַעֲבַד לְמַדְבְּחָא קַנְקַל עוֹבַד מְצַרְתָּא דִנְחָשָׁא תְּחוֹת סוֹבְבֵיהּ מִלְרַע עַד פַּלְגֵיהּ מְטוֹל לְקַבָּלָא גוּמְרַיָא וְגַרְמַיָא דְנָפְלִין מִן מַדְבְּחָא\",0,0],[4,143,38,5,\"וְאַתֵּיךְ אַרְבַּע עִזְקַן בְּאַרְבַּע זִוְיָתֵיהּ לְקַנְקַל דִּנְחָשָׁא אַתְרָא לַאֲרִיחַיָא\",0,0],[4,143,38,6,\"וַעֲבַד יַת אֲרִיחַיָא דְקִיסֵי שִׁיטָא וַחֲפָא יַתְהוֹן נְחָשָׁא\",0,0],[4,143,38,7,\"וְהַנְעַל יַת אֲרִיחַיָא בְּעִזְקָתָא עַל סְטַר מַדְבְּחָא לְמִטַּל יָתֵיהּ בְּהוֹן חֲלִיל לוּחִין מְלֵי עַפְרָא עֲבַד יָתֵיהּ\",0,0],[4,143,38,8,\"וַעֲבַד יַת כִּיּוֹרָא דִנְחָשָׁא וְיַת בְּסִיסֵיהּ דִּנְחָשָׁא מִן אַסְפַּקְלִירֵי נְחָשָׁא נְשַׁיָא צְנִיעוּתָא וּבְעִידַן דְּאָתוּן לְצַלָּאָה בִּתְרַע מַשְׁכַּן זִמְנָא הֲוָאָן קַיְימִין עַל קָרְבַּן אַדְמוּתְהוֹן וּמְשַׁבְּחָן וּמוֹדָן וְתַיְיבִין לְגוּבְרֵיהוֹן וְיָלְדַן בְּנִין צַדִּיקִין בִּזְמַן דְּמִדְכַן מִן סוֹאָבוֹת דִּמְהוֹן\",0,0],[4,143,38,9,\"וַעֲבַד יַת דָּרְתָא לְרוּחַ עִיבַר דָּרוֹמָא וִילַוֵי דָרְתָא דְבוּץ שְׁזִיר מְאָה אַמִּין\",0,0],[4,143,38,10,\"עַמּוּדֵיהוֹן עַשְרִין וְחוֹמְרֵיהוֹן עַשְרִין דִּנְחָשָׁא וָוֵי עַמּוּדַיָא וְכִבּוּשֵׁיהוֹן דִּכְסָף\",0,0],[4,143,38,11,\"וּלְרוּחַ צִפּוּנָא מְאָה אַמִּין עַמּוּדֵיהוֹן עַשְרִין וְחוֹמְרֵיהוֹן עַשְרִין דִּנְחָשָׁא וָוֵי עַמּוּדַיָא וְכִבּוּשֵׁיהוֹן דִּכְסָף\",0,0],[4,143,38,12,\"וּלְרוּחַ מַעַרְבָא וִילַוַן חַמְשִׁין אַמִּין עַמּוּדֵיהוֹן עַשְרָא וְחוֹמְרֵיהוֹן עַשְרָא וָוֵי עַמּוּדַיָא וְכִבּוּשֵׁיהוֹן דִּכְסָף\",0,0],[4,143,38,13,\"וּלְרוּחַ קִידוּמָא מַדִנְחָא חַמְשִׁין אַמִּין\",0,0],[4,143,38,14,\"וִילַוַן חֲמֵיסְרֵי אַמִּין לְעִבְרָא עַמּוּדֵיהוֹן תְּלָתָא וְחוֹמְרֵיהוֹן תְּלָתָא\",0,0],[4,143,38,15,\"וּלְעִבְרָא תִּנְיָינָא מִכָּא וּמִכָּא לִתְרַע דָּרְתָּא וִילַוַן חֲמֵיסְרֵי אַמִּין עַמּוּדֵיהוֹן תְּלָתָא וְחוֹמְרֵיהוֹן תְּלָתָא\",0,0],[4,143,38,16,\"כָּל וִילַוֵי דָרְתָא חֲזוֹר חֲזוֹר דְּבוּץ שְׁזִיר\",0,0],[4,143,38,17,\"וְחוֹמְרַיָא לַעֲמוּדַיָא דִנְחָשָׁא וָוֵי עַמּוּדַיָא וְכִבּוּשֵׁיהוֹן כְּסַף וְחִפּוּי רֵישֵׁיהוֹן כְּסָף וְהִינוּן מְכַבְּשִׁין כְּסַף הֵיכְדֵין הֲווֹ מִתְעַבְּדִין כָּל עַמּוּדֵי דָרְתָא\",0,0],[4,143,38,18,\"וּפְרָסָא דִתְרַע דָּרְתָא עוֹבַד צִיּוּר מַחְטָא דְתִכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי וּבוּץ שְׁזִיר וְעֶשְרִין אַמִּין אוּרְכָּא וְרוּמֵיהּ בְּפוּתְיָהּ חֲמֵשׁ אַמִּין כָּל קֳבֵיל וִילַוֵי דָרְתָא\",0,0],[4,143,38,19,\"וְעַמּוּדֵיהוֹן אַרְבְּעָא וְחוֹמְרֵיהוֹן אַרְבְּעָא דִנְחָשָׁא וָוֵיהוֹן כְּסַף וְחִפּוּי רֵישֵׁיהוֹן וְכִבּוּשֵׁיהוֹן כְּסָף\",0,0],[4,143,38,20,\"וְכָל מַתַּחְיָא לְמַשְׁכְּנָא וּלְדָרְתָא חֲזוֹר חֲזוֹר דִּנְחָשָׁא\",0,0],[4,143,38,21,\"אלה אִלֵין מִנְיָנֵי מַתְקַלְוָן וּסְכוּמְהוֹן דְּמַשְׁכְּנָא דְסַהֲדוּתָא דְאִתְמְנִיוּ עַל פּוּם מֵימְרָא דְמשֶׁה בְּרַם פּוּלְחַן לֵיוָאֵי הֲוַת בִּידָא דְאִיתָמָר בַּר אַהֲרן כַּהֲנָא\",0,0],[4,143,38,22,\"וּבְצַלְאֵל בַּר אוּרִי בַּר חוּר לְשִׁבְטָא דִיהוּדָה עֲבַד יַת כָּל דְּפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,38,23,\"וְעִמֵּיהּ אָהֳלִיאָב בַּר אֲחִיסָמָךְ לְשִׁבְטָא דְדָן נַגַר וְאוֹמַן וְצַיַיר בְּתִכְלָא וּבְאַרְגְוָונָא וּבִצְבַע זְהוֹרֵי וּבְבוּצָא\",0,0],[4,143,38,24,\"כָּל דַּהֲבָא דְּאִתְעֲבֵיד לְעִיבִידְתָּא בְּכָל עִיבִידַת קוּדְשָׁא וַהֲוָה סְכוּם דְּהַב אֲרָמוּתָא עַשְרִין וּתְשַׁע קַנְטְרִין וּשְׁבַע מְאָה וּתְלָתִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא דֵין הוּא דְהַב אֲרָמוּתָא דְאַרִימוּ בְּנֵי יִשְרָאֵל כָּל גְּבַר דְּאִתְרְעֵי לִבֵּיהּ לְאַפְרָשָׁא\",0,0],[4,143,38,25,\"וּכְסַף מִנְיָינֵי דִּבְנֵי יִשְרָאֵל דִּיהָבוּ בִּזְמַן דִּמְמַנּוּן משֶׁה גְּבַר פּוּרְקַן נַפְשֵׁיהּ מְאָה קַנְטְרִין וְאַלְפָא וּשְׁבַע מְאָה וְשׁוּבְעִין וְחָמֵשׁ סַלְעִין בְּסִלְעֵי קוּדְשָׁא\",0,0],[4,143,38,26,\"דַּרְכְּמוֹנָא לְגֻלְגַלְתָּא פַּלְגוּת סִלְעָא בְּסִלְעָא דְקוּדְשָׁא לְכָל מַאן דְּעָבַר עַל מִנְיָינַיָא מִבַּר עֶשְרִין שְׁנִין וּלְעֵילָא לְשִׁית מְאָה וּתְלָתָא אַלְפִין וַחֲמֵשׁ מְאָה וְחַמְשִׁין\",0,0],[4,143,38,27,\"וַהֲוָאָה מְאַת קַנְטִינְרִין דְּכַסְפָּא לַאֲתָבָא יַת חוֹמְרֵי קוּדְשָׁא וְיַת חוֹמְרֵי פַּרְגוֹדָא מְאָה חוֹמְרִין כָּל קְבֵיל קַנְטִינְרִין קַנְטִינַר לְחוֹמְרָא\",0,0],[4,143,38,28,\"וְיַת אַלְפָא וּשְׁבַע מְאָה וְשַׁבְעִין וַחֲמֵשׁ סַלְעִין עֲבַד וָוִין לַעֲמוּדַיָא וַחֲפָא רֵישֵׁיהוֹן וּכְבַשׁ יַתְהוֹן\",0,0],[4,143,38,29,\"וּנְחָשָׁא דְאַרָמוּתָא שַׁבְעִין קַנְטִירִין וּתְרֵין אַלְפִין וְאַרְבַּע מְאָה סִלְעִין\",0,0],[4,143,38,30,\"וְעָבַד בָּהּ יַת חוֹמְרֵי תְּרַע מַשְׁכַּן זִימְנָא וְיַת מַדְבְּחָא דִנְחָשָׁא וְיַת קַנְקַלֵי דִנְחָשָׁא דִילֵיהּ וְיַת כָּל מָנֵי מַדְבְּחָא\",0,0],[4,143,38,31,\"וְיַת חוֹמְרֵי דָרְתָא חֲזוֹר חֲזוֹר וְיַת חוֹמְרֵי תְרַע דָּרְתָא וְיַת כָּל מַתְחֵי מַשְׁכְּנָא וְיַת כָּל מַתְחֵי דָרְתָא חֲזוֹר חֲזוֹר\",0,0],[4,143,39,1,\"וּמִן תִּכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי עֲבָדוּ לְבוּשֵׁי שִׁמּוּשָׁא לְשַׁמָּשָׁא בְּקוּדְשָׁא וַעֲבָדוּ יַת לְבוּשֵׁי קוּדְשָׁא דִי לְאַהֲרן כַּהֲנָא הֵי כְּמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,39,2,\"וְעָבַד יַת אֵיפוֹדָא דְדַהֲבָא תִּכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי וּבוּץ שְׁזִיר\",0,0],[4,143,39,3,\"וְרַדִּידוּ יַת טַסֵי דְדַהֲבָא וְקָטָעוּ יַתְהוֹן שֶׁזְרִין לְמֶעְבַּד בְּגוֹ תִכְלָא וּבְגוֹ אַרְגְּוָונָא וּבְגוֹ צְבַע זְהוֹרֵי וּבְגוֹ בוּצָא עוֹבַד אוּמָן\",0,0],[4,143,39,4,\"כַּתְפִין עָבְדוּ לֵיהּ מְלַפְפָן עַל תְּרֵין צִטְרוֹי מִתְלָפֵף\",0,0],[4,143,39,5,\"וְהֵמְיַן טִיכוּסֵיהּ דַּעֲלוֹי מִנֵּיהּ הוּא הֵי כְּעוֹבָדוֹי דַהֲבָא תִּכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי וּבוּץ שְׁזִיר הֵיכְמָא דְפַקֵיד יְיָ יַת משֶׁה\",0,0],[4,143,39,6,\"וַעֲבָדוּ יַת מַרְגַלְוָן דְּבוּרְלָת חֲלָא מְשַׁקְעָן מְרַמְצָן גְּלִיפָן כְּתַב חָקִיק מְפָרַשׁ עַל שְׁמָהַת בְּנֵי יִשְרָאֵל\",0,0],[4,143,39,7,\"וְשַׁוִי יַתְהוֹן עַל כִּתְפֵי אֵפוֹדָא אַבְנֵי דוּכְרָנָא לִבְנֵי יִשְרָאֵל הֵיכְמָא דְפַקֵיד יְיָ יַת משֶׁה\",0,0],[4,143,39,8,\"וַעֲבַד יַת חוּשְׁנָא עוֹבַד אוּמַן הֵי כְעוֹבַד אֵיפוֹדָא דְדַהֲבָא תִּכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי וּבוּץ שְׁזִיר\",0,0],[4,143,39,9,\"מְרַבַּע הֲוָה עֵיף עָבָדוּ יַת חוּשְׁנָא זַרְתָּא אוּרְכֵּיהּ וְזַרְתָּא פּוּתְיֵהּ עֵיף\",0,0],[4,143,39,10,\"וְאַשְׁלִימוּ בֵּיהּ אַרְבְּעָא סְדָרִין מַרְגַלְיַן טָבִן כָּל קְבֵיל אַרְבַּעַת טְרִיגוֹנִין דְּעַלְמָא סִדְרָא קַמְיָיתָא סַמּוּקְתָּא יְרוּקְתָא וּבַרְקָתָא סִדְרָא חָד וַעֲלֵיהוֹן חָקִיק וּמְפָרַשׁ שְׁמָהַת תְּלַת שִׁבְטַיָא רְאוּבֵן שִׁמְעוֹן וְלֵוִי\",0,0],[4,143,39,11,\"וְשׁוּם סִדְרָא תִּנְיָנָא אִיזְמוֹרַד וְסִפִּירִינוּן וְכַדְכּוֹדִין וַעֲלֵיהוֹן חָקִיק וּמְפָרַשׁ שְׁמָהַת תְּלַת שִׁבְטַיָא יְהוּדָה דָן וְנַפְתָּלִי\",0,0],[4,143,39,12,\"וְשׁוּם סִידְרָא תְּלִיתָא קַנְכַּרִין טִרְקִין וְעֵין עֵגֶל וַעֲלֵיהוֹן חָקִיק וּמְפָרַשׁ שְׁמָהַת תְּלַת שִׁבְטַיָא גָד אָשֵׁר וְיִשָשׁכָר\",0,0],[4,143,39,13,\"וְשׁוּם סִידְרָא רְבִיעָאָה כְּרוֹם יַמָא רַבָּא וּבוּרְלַת חֲלָא וּמַרִגְנִית אַפַנְטוּרִין וַעֲלֵיהוֹן חָקִיק וּמְפָרַשׁ שְׁמָהַת תְּלַת שִׁבְטַיָא זְבוּלֻן יוֹסֵף וּבִנְיָמִין מְשַׁקְעָן מְרַמְצַן בִּדְהַב בְּאַשְׁלָמוּתְהוֹן\",0,0],[4,143,39,14,\"וּמַרְגְּלִיתָא עַל שְׁמָהַת בְּנֵי יִשְרָאֵל תְּרֵיסְרֵי עַל שְׁמָהַתְהוֹן כְּתַב גָּלִיף חָקִיק וּמְפָרַשׁ הֵי כִגְלִיף דְּעִזְקָא גְבַר מַרְגְּלִיתֵיהּ עַל שְׁמֵיהּ לִתְרֵיסַר שִׁבְטַיָא\",0,0],[4,143,39,15,\"וַעֲבָדוּ עַל חוּשְׁנָא שַׁלְשְׁלַן מְתַחֲמָן עוֹבַד קְלִיעָא דִדְהַב דְּכֵי\",0,0],[4,143,39,16,\"וְעָבָדוּ תַּרְתֵּין מְרַמְצִין דִּדְהַב וְתַרְתֵּין עִזְקַן דִּדְהַב וִיהָבוּ יַת תַּרְתֵּין עִזְקָתָא עַל תְּרֵין צִטְרֵי חוּשְׁנָא\",0,0],[4,143,39,17,\"וִיהָבוּ תַּרְתֵּין קְלִיעָן דִּדְהַב עַל תַּרְתֵּין עִיזְקָתָא עַל צִטְרֵי חוּשְׁנָא\",0,0],[4,143,39,18,\"וְיַת תַּרְתֵּין קְלִיעָן דִּמְסַדְרָן עַל תְּרֵין צִטְרוֹי יְהָבוּ עַל תַּרְתֵּין מְרַמְצָתָא וִיהָבִינוּן עַל כִּתְפֵי אֵיפוֹדָא כָּל קְבֵיל אַנְפּוֹי\",0,0],[4,143,39,19,\"וַעֲבָדוּ תַּרְתֵּין עִזְקַן דְּהַב וְשַׁוִּיאוּ עַל תַּרְתֵּין סִטְרֵי חוּשְׁנָא עַל שִפְתֵיהּ דִּלְעִבְרָא דְאֵפוֹדָא לְגֵיו\",0,0],[4,143,39,20,\"וַעֲבָדוּ תַּרְתֵּין עִזְקָן דְּהַב וְסַדְרִינוּן עַל תְּרֵין כִּתְפֵי אֵיפוֹדָא מִלְרַע מִלְקָבֵיל אַנְפּוֹי כָּל קְבֵיל בֵּית לוֹפֵי מֵעִילַוֵי לְהֶמְיַין אֵיפוֹדָא\",0,0],[4,143,39,21,\"וְטָכִיסוּ יַת חוּשְׁנָא מֵעִזְקָתָא לְעִזְקַת אֵיפוֹדָא בִּשְׁזִיר תִּכְלָא לְמֶהֱוֵי אָדִיק עַל הֶמְיַין אֵיפוֹדָא וְלָא יִתְפְּרַק חוּשְׁנָא מֵעִילַוֵי אֵיפוֹדָא הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,39,22,\"וַעֲבַד יַת מִנְטַר מְעִילָא עוֹבַד גַּרְדֵי שְׁזִיר תִּכְלָא\",0,0],[4,143,39,23,\"וּפוּם מִנְטַר מְעִילָא כְּפִיל בְּמִיצְעֵיהּ הֵי כְּפוּם שִׁירְיָא תוֹרָא בְּשִיפְתֵיהּ מַקַּף לְפוּמֵיהּ חֲזוֹר חֲזוֹר מְטוּל דְּלָא יִתְבְּזָע\",0,0],[4,143,39,24,\"וַעֲבָדוּ עַל שִׁפּוֹלֵי מִנְטַר מְעִילָא רוֹמַנְיָן דְּתִכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי שְׁזִיר\",0,0],[4,143,39,25,\"וַעֲבָדוּ חִיזוֹרְיַין דִּדְהַב וִיהָבוּ יַת חִיזוֹרָא בִּמְצִיעוּת רוּמַנְיָא עַל שִׁפּוּלֵי מִינְטַר מְעִילָא חֲזוֹר חֲזוֹר בִּמְצִיעוּת רוֹמַנְיָא\",0,0],[4,143,39,26,\"חִיזוֹרָא וְרוֹמָנָא חִיזוֹרָא וְרוֹמָנָא כּוּלְהוֹן שַׁבְעִין וּתְרֵין עַל שִׁפּוּלֵי מִנְטַר מְעִילָא חֲזוֹר חֲזוֹר לְשַׁמָּשָׁא הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,39,27,\"וַעֲבָדוּ יַת כִּתּוּנִין דְּבוּץ עוֹבַד גַּרְדֵי לְאַהֲרן וְלִבְנוֹי\",0,0],[4,143,39,28,\"וְיַת מִצְנַפְתָּא דְבוּצָא וְיַת בַּרְצִיץ כּוֹבְעַיָא דְבוּצָא וְיַת אַוַורְקִיסֵי בּוּצָא דְבוּץ שְׁזִיר\",0,0],[4,143,39,29,\"וְיַת קַמוּרָא דְבוּץ שְׁזִיר וְתִכְלָא וְאַרְגְּוָונָא וּצְבַע זְהוֹרֵי עוֹבַד צִיּוּר הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,39,30,\"וַעֲבָדוּ יַת צִיצַת כְּלִילָא דְקוּדְשָׁא דְּהַב דְּכֵי וּכְתָבוּ עֲלוֹי גְלִיף חָקִיק וּמְפָרֵשׁ קוֹדֶשׁ לַיְיָ\",0,0],[4,143,39,31,\"וְסַדָרוּ עֲלוֹי שְׁזִיר חוּטָא דְתִכְלָא מְטוֹל לְמִתַּן עַל מִצְנֶפְתָּא מִן לְעֵילָא דִתְפִילָתָא דְרֵישָׁא הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,39,32,\"וּשְׁלִימַת כָּל עִיבִידַת מַשְׁכְּנָא מַשְׁכַּן זִימְנָא וַעֲבָדוּ בְּנֵי יִשְרָאֵל הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה הֵיכְדֵין עֲבָדוּ\",0,0],[4,143,39,33,\"וְאַיְיתִיוּ יַת מַשְׁכְּנָא לְוַת משֶׁה לְבֵית מִדְרָשֵׁיהּ דְּהֲווּ תַּמָּן יַתְבִין משֶׁה וְאַהֲרן וּבְנוֹי וַהֲוָה מִתְרַץ לְהוֹן סֵדֶר כְּהוּנְתָּא וְתַמָּן יַתְבִין סָבֵי יִשְרָאֵל וְאַחְוִיאוּ לֵיהּ יַת מַשְׁכְּנָא וְיַת כָּל מָנוֹי פּוּרְפּוֹי לוּחוֹי נַגְרוֹי עֲמוּדוֹי וְחוֹמְרוֹי\",0,0],[4,143,39,34,\"וְיַת חוֹפָאָה דְמַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וְיַת חוֹפָאָה דְמַשְׁכֵי סַסְגְוָונָא וְיַת פַּרְגוֹדָא דִפְרָסָא\",0,0],[4,143,39,35,\"וְיַת אֲרוֹנָא דְסַהֲדוּתָא וְיַת אֲרִיחוֹי וְיַת כַּפּוּרְתָּא וּכְרוּבַיָא דְנַפְקִין נְגִיד מִינָהּ חָד מִכָּא וְחָד מִכָּא\",0,0],[4,143,39,36,\"וְיַת פָּתוֹרָא וְיַת כָּל מָנוֹי וְיַת לְחֵים אַפַּיָא\",0,0],[4,143,39,37,\"וְיַת מְנַרְתָּא וְיַת בּוֹצִינָהָא בּוֹצִינֵי סְדוּרָא דִמְסַדְרִין כָּל קְבֵיל שִׁבְעָתֵי כּוֹכְבַיָא דִנְהִיגִין בְּשִׁטְרֵיהוֹן בִּרְקִיעָא בִּימָמָא וּבְלֵילְיָא וְיַת מִשְׁחָא דְאַנְהָרוּתָא\",0,0],[4,143,39,38,\"וְיַת מַדְבְּחָא דְדַהֲבָא וְיַת מִשְׁחָא דִרְבוּתָא וְיַת קְטוֹרֶת בּוּסְמַיָא וְיַת פְּרָסָא דְבִתְרַע מַשְׁכְּנָא\",0,0],[4,143,39,39,\"וְיַת מַדְבְּחָא דִנְחָשָׁא וְיַת קַנְקַל דִּנְחָשָׁא דִילֵיהּ יַת אֲרִיחוֹי וְיַת כָּל מָנוֹי יַת כִּיּוֹרָא וְיַת בְּסִיסֵיהּ\",0,0],[4,143,39,40,\"יַת וִילַוֵי דַרְתָּא וְיַת עַמּוּדָהָא יַת חוּמְרָהָא וְיַת פְּרָסָא לִתְרַע דַּרְתָּא וְיַת אֲטוּנוֹי וּמַחְתָּהָא וְיַת כָּל מָנֵי פּוּלְחַן מַשְׁכְּנָא לְמַשְׁכַּן זִמְנָא\",0,0],[4,143,39,41,\"יַת לְבוּשֵׁי שִׁמוּשָׁא לְשַׁמָשָׁא בְּקוּדְשָׁא יַת לְבוּשֵׁי קוּדְשָׁא לְאַהֲרן כַּהֲנָא וְיַת לְבוּשֵׁי בְּנוֹי לְשַׁמָּשָׁא\",0,0],[4,143,39,42,\"הֵי כְּכָל מַה דְּפַקֵּיד יְיָ יַת משֶׁה הֵיכְדֵין עָבָדוּ בְּנֵי יִשְרָאֵל יַת כָּל פּוּלְחָנָא\",0,0],[4,143,39,43,\"וַחֲמָא משֶׁה יַת כָּל פּוּלְחָנָא וְהָא עָבָדוּ יָתָהּ הֵיכְמָא דְפַקֵּיד יְיָ הֵיכְדֵין עָבָדוּ וּבְרִיךְ יַתְהוֹן משֶׁה וַאֲמַר תִּשְׁרֵי שְׁכִינְתָּא דַיְיָ בְּעוֹבָדֵי יְדֵיכוֹן\",0,0],[4,143,40,1,\"וּמַלֵּיל יְיָ עִם משֶׁה לְמֵימָר\",0,0],[4,143,40,2,\"בְּיוֹמָא דְיַרְחָא קַדְמָאָה הוּא יַרְחָא דְנִיסָן בְּחַד לְיַרְחָא תְּקִים יַת מַשְׁכְּנָא מַשְׁכַּן זִימְנָא\",0,0],[4,143,40,3,\"וּתְשַׁוֵּי תַּמָּן יַת אֲרוֹנָא דְסַהֲדוּתָא וְתַטְלֵיל עַל אֲרוֹנָא יַת כַּפּוּרְתָּא\",0,0],[4,143,40,4,\"וְהַנְעַל יַת פָּתוֹרָא בִּסְטַר צִפּוּנָא מְטוּל דְּמִתַּמָּן מִתְיָהֵיב עוּתְרָא דְמִתַּמָן זָלְחָן רְסִיסֵי מַלְקוֹשִׁין עַל עוּסְבִין לְמִתְפַּרְנְסָא בְּהוֹן דַּיְירֵי עַלְמָא וּתְסַדֵּר יַת סִדְרוֹי תְּרֵין סִדְרֵי לַחְמָא גַוָאָה שִׁית עֲגוּלִין בְּסִדְרָא כָּל קְבֵל שִׁבְטוֹי דְיַעֲקב וּתְהַנְעַל יַת מְנַרְתָּא בִּסְטַר דָּרוֹמָא מְטוֹל דְּמִתַּמָּן שְׁבִילֵי שִׁמְשָׁא וְסִיהֲרָא וּמִתַּמָּן אִיסְרַטְוָון דִּנְהוֹרֵי וְתַמָּן גִּנְזֵי חָכְמְתָא דִמְתִילִין לִנְהוֹרֵי וְתַדְלֵיק יַת בּוֹצִינָהָא שׁוּבְעָא כָּל קְבֵיל שִׁבְעָתֵי כּוֹכְבַיָא דִמְתִילִין לְצַדִּיקַיָא דִמְנַהֲרִין לְעַלְמָא בִּזְכוּתֵיהוֹן\",0,0],[4,143,40,5,\"וְתִתֵּן יַת מַדְבְּחָא דְדַהֲבָא לִקְטוֹרֶת בּוּסְמַיָא קֳדָם אֲרוֹנָא דְסַהֲדוּתָא מְטוּל חַכִּימַיָא דַעֲסִיקִין בְּאוֹרַיְיתָא וְרֵחֵיהוֹן נָדִיף הֵי כִקְטוֹרֶת בּוּסְמַיָא וּתְשַׁוֵּי יַת פְּרָסָא דְתַרְעָא לְמַשְׁכְּנָא מְטוּל צַדִּיקַיָא דַחֲפִין בִּזְכוּתְהוֹן עַל עַמָּא בֵּית יִשְרָאֵל\",0,0],[4,143,40,6,\"וְתִתֵּן יַת מַדְבְּחָא דְעָלָתָא קֳדָם תְּרַע מַשְׁכַּן זִמְנָא מְטוּל עֲתִירַיָא דִמְסַדְרִין פָּתוֹרָא קֳדָם תַּרְעֵיהוֹן וּמְפַרְנְסִין מִסְכֵּנַיָא וּמִשְׁתְּבֵיק לְהוֹן חוֹבֵיהוֹן כְּאִילוּ מְקַרְבִין עֲלָתָא עַל מַדְבְּחָא\",0,0],[4,143,40,7,\"וְתִתֵּן יַת כִּיּוֹרָא בֵּינֵי מַשְׁכַּן זִמְנָא וּבֵינֵי מַדְבְּחָא וְתִתֵּן תַּמָּן מוֹי מְטוּל חוֹבַיָא דְהַדְרִין בִּתְיוּבְתָּא וְשַׁדִיַין עַקְמוּמִיתְהוֹן הֵי כְמַיָא\",0,0],[4,143,40,8,\"וּתְשַׁוֵּי יַת דַּרְתָּא חֲזוֹר חֲזוֹר מְטוֹל זַכְוַות אַבְהַת עַלְמָא דִמְחַזְרִין חֲזוֹר חֲזוֹר לְעַמָּא בֵּית יִשְרָאֵל וְתִתֵּן יַת פְּרָסָא דִתְרַע דָּרְתָא מְטוּל זַכְוַת אַבְהַת עַלְמָא דְפָרִיס בִּתְרַע גֵּיהִנָּם מִן בִּגְלַל דְּלָא יֵעָלוּן תַּמָּן נַפְשַׁת דַרְדְּקֵי עַמָּא דְיִשְרָאֵל\",0,0],[4,143,40,9,\"וְתִסַּב יַת מִשְׁחָא דִרְבוּתָא וּתְרַבֵּי יַת מַשְׁכְּנָא וְיַת כָּל דְּבֵיהּ וּתְקַדֵּשׁ יָתֵיהּ מְטוּל כְּלִיל דְּמַלְכוּתָא דְבֵית יְהוּדָה וּמַלְכָּא מְשִׁיחָא דְעָתִיד לְמִפְרַק יַת יִשְרָאֵל בְּסוֹף יוֹמַיָא\",0,0],[4,143,40,10,\"וּתְרַבֵּי יַת מַדְבְּחָא דַעֲלָתָא וְיַת כָּל מָנוֹי וּתְקַדֵּשׁ יַת מַדְבְּחָא וִיהֵי מַדְבְּחָא קוֹדֶשׁ קוּדְשִׁין מְטוּל כְּלִילָא דִכְהוּנְתָּא דְאַהֲרן וּבְנוֹי וְאֵלִיָהוּ כַּהֲנָא רַבָּא דַּעֲתִיד לְמִשְׁתַּלְחָא בְּסוֹף גַּלְוָותָא\",0,0],[4,143,40,11,\"וּתְרַבֵּי יַת כִּיּוֹרָא וְיַת בְּסִיסֵיהּ וּתְקַדֵּשׁ יָתֵיהּ מְטוּל יְהוֹשֻׁעַ מְשׁוּמְשָׁנָךְ רַבָּא דְסַנְהֶדְרִין דְּעִמֵּיהּ דְּעַל יְדוֹי עֲתִידָא אַרְעָא דְיִשְרָאֵל לְאִיתְפַּלְגָא וּמְשִׁיחָא בַּר אֶפְרַיִם דְּנָפִיק מִינֵיהּ דְּעַל יְדוֹי עֲתִידִין בֵּית יִשְרָאֵל לִמְנַצְחָא לְגוֹג וּלְסִיעָתֵיהּ בְּסוֹף יוֹמַיָא\",0,0],[4,143,40,12,\"וּתְקָרֵיב יַת אַהֲרן וְיַת בְּנוֹי לִתְרַע מַשְׁכַּן זִמְנָא וְתַסְחֵי יַתְהוֹן בְּמַיָא\",0,0],[4,143,40,13,\"וְתַלְבֵּשׁ יַת אַהֲרן לְבוּשֵׁי קוּדְשָׁא וּתְרַבֵּי יָתֵיהּ וּתְקַדֵּשׁ יָתֵיהּ וִישַׁמֵּשׁ קֳדָמַי\",0,0],[4,143,40,14,\"וְיַת בְּנוֹי תַּקְרִיב וְתַלְבְּשִׁינוּן כִּיתּוּנִין\",0,0],[4,143,40,15,\"וּתְרַבֵּי יַתְהוֹן הֵיכְמָא דְרָבִית יַת אֲבוּהוֹן וִישַׁמְשׁוּן קֳדָמַי וּתְהֵי לְמֶהֱוֵי לְהוֹן רְבוּתְהוֹן לִכְהוּנַת עֲלָם לְדָרֵיהוֹן\",0,0],[4,143,40,16,\"וְעָבַד משֶׁה הֵי כְּכָל מַה דְּפַקֵּיד יְיָ יָתֵיהּ הֵיכְדֵין עֲבָד\",0,0],[4,143,40,17,\"וַהֲוָה בְּיַרְחָא קַמָאָה הוּא יַרְחָא דְנִיסָן בְּשַׁתָּא תִּנְיֵינְתָא בְּחַד לְיַרְחָא אִיתָקַם מַשְׁכְּנָא\",0,0],[4,143,40,18,\"וְאָקִים משֶׁה יַת מַשְׁכְּנָא וִיהַב יַת חוֹמְרוֹי וְשַׁוִּי יַת לוּחוֹי וִיהַב יַת נַגְרוֹי וְאָקִים יַת עַמּוּדוֹי\",0,0],[4,143,40,19,\"וּפְרַס יַת פְּרָסָא עַל מַשְׁכְּנָא וְשַׁוִּי יַת חוֹפָאָה לְמַשְׁכְּנָא עֲלוֹי מִן לְעֵילָא הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,40,20,\"וּנְסֵיב יַת תְּרֵין לוּחֵי אַבְנָא לוּחֵי קְיָימָא דְאִתְיְהִיבוּ לֵיהּ בְּחוֹרֵב וַהֲווּ קַיְימִין עַל אָת בְּבֵית אוּלְפָנָא הִנּוּן לוּחֵי סַהֲדוּתָא וְתַבְרֵי לוּחַיָא בְּאָרוֹנָא וְשַׁוִי יַת אֲרִיחַיָא עַל אֲרוֹנָא וִיהַב יַת כַּפּוּרְתָּא בַּהֲדֵי כְּרוּבַיָא דְנַפְקִין נְגִיד מִינָהּ עַל אֲרוֹנָא מִלְעֵילָא\",0,0],[4,143,40,21,\"וְהַנְעַל יַת אֲרוֹנָא לְמַשְׁכְּנָא וְשַׁוִי יַת פַּרְגוֹדָא דִפְרָסָא וְטַלְלֵיהּ עַל אֲרוֹנָא דְסַהֲדוּתָא הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,40,22,\"וִיהַב יַת פָּתוֹרָא בְּמַשְׁכַּן זִימְנָא עַל שִׁידָא דְמַשְׁכְּנָא צִפּוּנָא מִבָּרָא לְפַרְגוֹדָא\",0,0],[4,143,40,23,\"וְסַדֵּר עֲלוֹהִי סִדוּרִין דִּלְחֵם קֳדָם יְיָ הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,40,24,\"וְשַׁוֵּי יַת מְנַרְתָּא בְּמַשְׁכַּן זִימְנָא כָּל קְבֵיל פָּתוֹרָא עַל שִׁידָא דְמַשְׁכְּנָא דְרוֹמָא\",0,0],[4,143,40,25,\"וְאַדְלִיק יַת בּוֹצִינַיָא קֳדָם יְיָ הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,40,26,\"וְשַׁוִּי יַת מַדְבְּחָא דְדַהֲבָא בְּמַשְׁכַּן זִימְנָא קֳדָם פַּרְגוֹדָא\",0,0],[4,143,40,27,\"וְאַסֵיק עֲלוֹי קְטוֹרֶת בּוּסְמִין הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,40,28,\"וְשַׁוֵּי יַת פְּרָסָא דְתַרְעָא לְמַשְׁכְּנָא\",0,0],[4,143,40,29,\"וְיַת מַדְבְּחָא דְעָלָתָא שַׁוִי בִּתְרַע מַשְׁכְּנָא וְאַסֵּיק עֲלוֹי יַת עֲלָתָא וְיַת מִנְחָתָא הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,40,30,\"וְשַׁוֵי יַת כִּיּוֹרָא עַל בְּסִיסֵיהּ בֵּינֵי מַשְׁכַּן זִמְנָא וּבֵינֵי מַדְבְּחָא וִיהַב תַּמָּן מַיִין חַיִין לְקִידוּשׁ וְלָא פַּסְקִין וְלָא סַרְיַן כָּל יוֹמַיָא\",0,0],[4,143,40,31,\"וְנַסְבִין משֶׁה וְאַהֲרן וּבְנוֹי מִינֵיהּ בְּנַטְלָא וּמְקַדְשִׁין מִינֵיהּ יַת יְדֵיהוֹן וְיַת רִגְלֵיהוֹן\",0,0],[4,143,40,32,\"בִּזְמַן מֵיעַלְהוֹן לְמַשְׁכַּן זִימְנָא וּבְמִקְרְבֵיהוֹן לְמַדְבְּחָא מְקַדְשִׁין הֵיכְמָא דְפַקֵּיד יְיָ יַת משֶׁה\",0,0],[4,143,40,33,\"וְאָקֵים יַת דַרְתָּא חֲזוֹר חֲזוֹר לְמַשְׁכְּנָא וּלְמַדְבְּחָא וִיהַב יַת פְּרָסָא דְבִתְרַע מַשְׁכְּנָא וּגְמַר משֶׁה יַת עִיבִידְתָּא\",0,0],[4,143,40,34,\"וַחֲפָא עֲנַן יְקָרָא יַת מַשְׁכַּן זִמְנָא וְאִיקַר שְׁכִינְתָּא דַיְיָ אִתְמְלֵי יַת מַשְׁכְּנָא\",0,0],[4,143,40,35,\"וְלָא הֲוָה אֶפְשַׁר לְמשֶׁה לְמֵיעַל לְמַשְׁכַּן זִמְנָא אֲרוּם שְׁרָא עֲלוֹי עֲנַן יְקָרָא וְאִיקַר שְׁכִינְתָּא דַיְיָ אִתְמְלֵי יַת מַשְׁכְּנָא\",0,0],[4,143,40,36,\"וּבְאִישׁוֹן אִסְתַּלְקוּת עֲנַן יְקָרָא מֵעִלַוֵי מַשְׁכְּנָא נַטְלִין בְּנֵי יִשְרָאֵל בְּכָל מַטְלָנֵיהוֹן\",0,0],[4,143,40,37,\"וְאִין לָא מִסְתַּלֵּק עֲנַן יְקָרָא וְלָא נַטְלִין עַד יוֹם אִסְתַּלְקוּתֵיהּ\",0,0],[4,143,40,38,\"אֲרוּם עֲנַן יְקָרָא דַיְיָ הֲוָה מְטַלָל עַל מַשְׁכְּנָא בִּימָמָא וַעֲמוּדָא דְאֵישָׁתָא הֲוָה מִנְהַר בְּלֵילְיָא וְחַמְיָין כָּל בְּנֵי יִשְרָאֵל בְּכָל מַטְלָנֵיהוֹן\",0,0],[4,144,1,1,\"וַהֲוָה בִּתְלָתִין שְׁנִין לִזְמַן דְאַשְׁכַּח חִלְקִיָה כַּהֲנָא רַבָּא סִפְרָא דְאוֹרַיְתָא בְּבֵית מַקְדְשָׁא בַּעֲזַרְתָּא תְּחוֹת אוּלָמָא בְּפַלְגוּת לֵילְיָא בָּתַר מַעֲלָנֵי סִיהֲרָא בְּיוֹמֵי יֹאשִׁיָה בַר אָמוֹן מְלַךְ שִׁבְטָא דְבֵית יְהוּדָה בְּתַמוּז בְּחַמְשָׁא לְיַרְחָא אֲמַר נְבִיָא וַאֲנָא בְגוֹ בְנֵי גָלוּתָא עַל נְהַר כְּבָר אִתְפְּתַחוּ שְׁמַיָא וַחֲזֵית בְּחֵיזוּ נְבוּאָה דִי שְׁרָת עֲלֵי חֵיזוּ יְקָר שְׁכִנְתָּא דַיָי:\",0,0],[4,144,1,2,\"בְּחַמְשָׁא לְיַרְחָא הִיא שַׁתָּא חֲמֵשְׁתָּא לְגָלוּת מַלְכָּא יוֹיָכִין:\",0,0],[4,144,1,3,\"מֶהֱוֵי הֲוָה פִּתְגָם נְבוּאָה מִן קֳדָם יְיָ עִם יְחֶזְקֵאל בַּר בּוּזִי כַהֲנָא בְאַרְעָא דְיִשְׂרָאֵל תָּב תִּנְיָנוּת וְאִתְמַלֵל עִמֵיהּ בִּמְדִינַת אֲרַע כַּסְדָאֵי עַל נְהַר כְּבָר וּשְׁרָת עֲלוֹהִי תַּמָן רוּחַ נְבוּאָה מִן קֳדָם יְיָ:\",0,0],[4,144,1,4,\"וַחֲזֵית וְהָא רוּחַ עַלְעוֹלָא אָתֵי מִן צִפוּנָא עַנָן רַב וְאֶשְׁתָּא מִשְׁתַּלְהָבָא וְזֵיהוֹרָא לֵיהּ סְחוֹר סְחוֹר וּמִגוֹ עֲנָנָא וּמִגוֹ עַלְעוֹלָא כְּעֵין חַשְׁמָלָא מִגוֹ אֶשְׁתָּא:\",0,0],[4,144,1,5,\"וּמִגַוָהּ דְמוּת אַרְבַּע בִּרְיָן וְדֵין חֶזְוֵיהוֹן דְמוּת אֱנָשָׁא לְהֵין:\",0,0],[4,144,1,6,\"וְאַרְבְּעָא אַפִּין לַחֲדָא וְאַרְבַּע אַפִּין לְכָל חַד וְחַד שִׁתָּא עֲסַר אַפִּין לְבִרְיָתָא חֲדָא מִנְיַן אַפַּיָא דְאַרְבַּע בִּרְיָן שִׁתִּין וְאַרְבְּעָא אַפִּין וְאַרְבְּעָה גַפִּין לַחֲדָא וְאַרְבְּעָא גַפִּין לְכָל חַד וְחַד שִׁתָּת עֲסַר לְכָל אַפָּא וְאַפָּא שִׁתִּין וְאַרְבָּעָא גַפִּין לְבִרְיָתָא חֲדָא וַהֲווֹ מִנְיָן גַפַּיָא דְאַרְבַּע בִּרְיָן מָאתָן וְחַמְשִׁין וְשִׁתָּא גַפִּין:\",0,0],[4,144,1,7,\"וְרִגְלֵיהוֹן רִגְלִין כֵּיוָנָן וּפַרְסַת רִגְלֵיהוֹן כְּפַרְסַת רִגְלִית סְגַלְגְלָן וּמְזִיעָן עַלְמָא בִּמְהָכְהֵן וּמְנַצְנְצָן כְּעֵין נְחָשׁ מְצַלְהַב:\",0,0],[4,144,1,8,\"וִידִין כִּידֵי אֱנָשָׁא עֲבִיד לְהוֹן מִתְּחוֹת גַפֵּיהוֹן עַל אַרְבַּע סִטְרֵיהוֹן לְמֶחְתֵּי בְהֵן גוּמְרִין דְאֵשָׁא מִבֵּינֵי כְרוּבַיָא מִתְּחוֹת רְקִיעָא דְעַל רֵישֵׁיהוֹן לְמִתַּן עַל חוּפְנֵי סַרְפַּיָא לְמִזְרַק עַל אֲתַר רַשִׁיעַיָא לְאַבָּדָא חַיָבַיָא עָבְרֵי מֵימְרֵיהּ וְאַפֵּיהוֹן וְגַפֵּיהוֹן שַׁוֵי לְאַרְבַּעְתְּהֵן:\",0,0],[4,144,1,9,\"מְכַוְנָן חֲדָא לִקְבֵיל חֲדָא גַפֵּיהוֹן לָא מִתְחַזְרִין בְּמִיזַלְהֶן בִּרְיָא לִקְבֵיל אַפָּהָא אָזְלַן:\",0,0],[4,144,1,10,\"וּדְמוּת אַפֵּיהוֹן אַפֵּי אֱנָשָׁא וְאַפֵּי אַרְיָא עֲבִיד מִימִינָא לְאַרְבַּעְתְּהֵן וְאַפֵּי תוֹרָא עֲבִיד מִסְמָלָא לְאַרְבַּעְתְּהֵן וְאַפֵּי נִשְׁרָא לְאַרְבַּעְתְּהֵן:\",0,0],[4,144,1,11,\"וְאַפֵּיהֵן וְגַפֵּיהֵן פְּרִישִׁין מִלְעָלָא לַחֲדָא תַּרְתִּין מְכַוְנָן חֲדָא וְתַרְתֵּין מְכַסָן יַת גְוִיָתְהֵין:\",0,0],[4,144,1,12,\"וּבִרְיָא לִקְבֵל אַפָּהָא אַזְלָא לַאֲתַר דְתֶהֱוֵי תַמָן רַעֲוָא לְמֵיזַל אָזְלָל לָא מִתְחַזְרָן בְּמֵיזַלְהֵן:\",0,0],[4,144,1,13,\"וּדְמוּת בִּרְיָתָא חֲזְוֵיהֶן כְּגוּמְרִין דְאֶשָׁא בָּעֲרָן כְּחֵזוּ בְעוּרַיָא אֶשְׁתָּא מִשְׁתַּלְהֲבָא בֵּין בִּרְיָתָא וְזֵיהוֹרַיָא לְאֶשְׁתָּא וּמִן אֶשְׁתָּא נָפֵיק בַּרְקָא:\",0,0],[4,144,1,14,\"וּבִרְיָתָא בְּאִשְׁתַּלְחוּתְהֵין לְמֶעְבַּד רְעוּת רִבּוֹנְהֵן דְאַשְׁרֵי שְׁכִינְתֵּיהּ בִּמְרוֹמָא עֵלָא מִנְהֵן בַּאֲנָפָא עֵינָא לְמֶחֱזֵי חֶזְרָן וּמַקְפַן וּמְכַסָן יַת עַלְמָא וְתָיְבִין בִּרְיָתָא כַּחֲדָא וְקַלִילָן כְּחֵיזוּ בַרְקָא:\",0,0],[4,144,1,15,\"וַחֲזֵית בִּרְיָתָא וְהָא גַלְגַל חַד מִשְׁתְּוֵי בְּמִלְרַע לְרוּם שְׁמַיָא בִּסְטַר בִּרְיָתָא לְאַרְבַּע אַפּוֹהִי:\",0,0],[4,144,1,16,\"חֵיזוּ גִלְגְלַיָא וְעוֹבָדֵיהוֹן כְּעֵין אֲבַן טָבָא וּדְמוּת חַד לְאַרְבַּעְתְּהֵן וְחֶזְוֵהֶן וְעוֹבָדֵיהֶן כְּמָא דַהֲוֵי גַלְגַל בְּגוֹ גַלְגָל:\",0,0],[4,144,1,17,\"עַל אַרְבְּעָא סִטְרֵיהֶן בְּמִיזַלְהֵן אָזְלִין לָא מִתְחַזְרִין בְּמֵיזַלְהֵן:\",0,0],[4,144,1,18,\"וְגַבֵּיהֶן שָׁוָן לְקִיבְלָא רָקִיעָא וְרוּמָא לְהֶן וּדְחִילִין אִנוּן וְגַבֵּיהֶן מְלָן עַיְנִין סְחוֹר סְחוֹר לְאַרְבַּעְתְּהֶן:\",0,0],[4,144,1,19,\"וּבְמֵיזַל בִּרְיָתָא אָזְלִין גַלְגְלַיָא לְקִבְלֵיהֶן וּבְאִתְרָמָא בִרְיָתָא בְּמִלְרַע לְרוּם שְׁמַיָא מִתְרְמִין לְגַלְגְלַיָא:\",0,0],[4,144,1,20,\"עַל אֲתַר דַהֲוֵי תַמָן רַעֲוָא לְמֵיזַל אָזְלִין לְתַמָן רַעֲוָא לְמֵיזַל וְגַלְגְלַיָא מִתְרְמִין לְקִבְלֵהֶן אֲרֵי כְּרוּחַ בִּרְיָתָא בְּגַלְגְלַיָא:\",0,0],[4,144,1,21,\"בְּמֵיזַלְהוֹן אָזְלִין וּבִמְקָמְהוֹן קְיָמִין וּבְאִתְרָמְהוֹן כְּמִלְרַע לְרוּם שְׁמַיָא מִתְרְמִין גַלְגְלַיָא לְקִבְלֵיהוֹן אֲרֵי כְּרוּחַ בִּרְיָתָא בְּגַלְגְלַיָא:\",0,0],[4,144,1,22,\"וּדְמוּת עַל רֵישֵׁי בִּרְיָתָא רְקִיעָא כְּעֵין גְלִיד חֲסִין מַרְכֵן עַל רֵישֵׁיהוֹן מִלְעֵלָא:\",0,0],[4,144,1,23,\"וּתְחוֹת רְקִיעָא גַפֵּיהוֹן מְכַוְנָן חֲדָא לִקְבֵיל חֲדָא לַחֲדָא תַּרְתֵּין מְכַסִין לְהֵן וְלַחֲדָא תַּרְתֵּין מְכַסִין לְהֵן יַת גְוִיָתְהֵן:\",0,0],[4,144,1,24,\"וּשְׁמָעִית יַת קַל גַפֵּיהֶן כְּקַל מַיִין סַגִיאִין כְּקָלָא מִן קֳדָם שַׁדַי בִּמְהָכְהֵן קָל מִלוּלֵיהֶן כַּד מוֹדָן וּמְבָרְכִין יַת רִבּוֹנְהוֹן קַיָמָא מֶלֶךְ עָלְמַיָא כְּקָל מַשִׁרְיָת מַלְאֲכֵי מְרוֹמָא בִּמְקָמְהֶן מְשַׁתְקָן גַפֵּיהֶן מִן קֳדָם דִבּוּרָא:\",0,0],[4,144,1,25,\"וּבִזְמַן דַהֲוֵי רַעֲוָא קֳדָמוֹהִי לְאַשְׁמָעָא דִי דִבּוּרָא לְעַבְדוֹהִי נְבִיֵי יִשְׂרָאֵל הֲוֵי קָלָא וּמִשְׁתְּמַע מֵעִלַוֵי רְקִיעָא מִבֵּין כְּרוּבַיָא מִתְּחוֹת רְקִיעָא דִי עַל רֵישֵׁיהוֹן בִּמְקָמְהֵן מְשַׁתְקָן גַפֵּיהֵן מִן קֳדָם דִבּוּרָא:\",0,0],[4,144,1,26,\"וּמֵעִלַוֵי רְקִיעָא דִי עַל רֵישֵׁיהוֹן כְּחַזוּ אֲבַן טָבָא דְמוּת כּוּרְסַיָא וְעַל דְמוּת כּוּרְסַיָא דְמוּת כְּחֵיזוּ אֱנָשָׁא עֲלוֹהִי מִלְעֶלָא:\",0,0],[4,144,1,27,\"וַחֲזֵית כְּעֵין חַשְׁמָלָא כְּחֵיזוּ אֶשְׁתָּא מִגָיו לָהּ סְחוֹר סְחוֹר חֵיזוּ יְקָר דְלָא יְכִילָא עֵינָא לְמֶחֱזֵי וְלָא אֶפְשַׁר לְאִסְתְּכִּלָא בֵיהּ וּלְעֵלָא חֵיזוּ יְקָר דְלָא יְכִילָא עֵינָא לְמֶחֱזֵי וְלָא אֶפְשַׁר לְאִסְתַכָּלָא בֵיהּ וּלְרַע חֲזֵיתִי כְּחֵיזוּ אֶשְׁתָּא וְזֵיהוֹרָא לֵיהּ סְחוֹר סְחוֹר:\",0,0],[4,144,1,28,\"כְּחֵיזוּ קַשְׁתָּא דַהֲוֵי בַעֲנָנָא בְּיוֹמָא דְמִטְרָא כֵּן חֵיזוּ זֵיהוֹרָא סְחוֹר סְחוֹר הוּא חֵיזוּ דְמוּת יְקָרָא דַייָ וַחֲזֵית וְאִשְׁתַּטְחֵית עַל אַפַּי וּשְׁמַעִית קַל דְמִתְמַלֵל:\",0,0],[4,144,2,1,\"וַאֲמַר לִי בַּר אָדָם קוּם עַל רִיגְלָךְ וַאֲמַלֵל עִמָךְ:\",0,0],[4,144,2,2,\"וְעַלַת בִּי רוּחָא כַּד מַלֵיל עִמִי וַאֲקַמְתַּנִי עַל רִגְלַי וּשְׁמַעֵית יַת דְמִתְמַלֵל עִמִי:\",0,0],[4,144,2,3,\"וַאֲמַר לִי בַּר אָדָם שָׁלַח אֲנָא יָתָךְ לְוַת בְּנֵי יִשְׂרָאֵל לְוַת עַמְמַיָא סַרְבָנַיָא דְסָרִיבוּ עַל מֵימְרִי אִינוּן וַאֲבָהָתְהוֹן מְרָדוּ בְמֵימְרִי עַד כְּרַן יוֹמָא הָדֵים:\",0,0],[4,144,2,4,\"וּמִתְקְרַן בְּנַיָא אִינוּן חֲצִיפֵי אַפַּיָא וְתַקִיפֵי לִבָּא אֲנָא שָׁלַח יָתָךְ לְוַתְהוֹן וְתֵימַר לְהוֹן כִּדְנַן אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,2,5,\"וְאִינוּן אִם יְקַבְּלוּן אוּלְפַן וְאִם יִתְמַנְעוּן מִלְמֶחְטֵי אֲרֵי עַם סַרְבָן אִינוּן וְיֵדְעוּן דִי נְבִיָא הֲוָה בֵינֵיהוֹן:\",0,0],[4,144,2,6,\"וְאַתְּ בַּר אָדָם לָא תִדְחַל מִנְהוֹן וּמִפִּתְגְמֵיהוֹן לָא תִדְחַל אֲרֵי מְסָרְבִין וּמַקְשִׁין לְקִבְלָךְ וּבְגוֹ עַמָא דְעוֹבָדֵיהוֹן דָמָן לְעַקְרַבִּין אַתְּ יָתֵיב מִפִּתְגָמֵיהוֹן לָא תִדְחַל וּמִן קֳדָמֵיהוֹן לָא תִתְּבַר אֲרֵי עַם סַרְבָן אִינוּן:\",0,0],[4,144,2,7,\"וְתִתְנַבֵּי יַת פִּתְגָמֵי נְבוּאֲתִי לְהוֹן אִם יְקַבְּלוּן אוּלְפָן וְאִם יִתְמַנְעוּן מִלְמֶחְטֵי אֲרֵי עַם סַרְבָן אִינוּן:\",0,0],[4,144,2,8,\"וְאַתְּ בַּר אָדָם קַבֵּל יַת דִי אֲנָא מְמַלֵיל עִמָךְ לָא תְהֵי סַרְבָן כְּעַמָא סַרְבָנָא אַרְכִין נַפְשָׁךְ וְקַבֵּיל יַת דִי אֲנָא יָהֵיב לְךְ:\",0,0],[4,144,2,9,\"וַחֲזֵית וְהָא דְמוּת יַד מִתּוֹשְׁטָא לְצַד לְוָתִי וְהָא בֵּיהּ מְגִלַת סַפְרָא:\",0,0],[4,144,2,10,\"וּפְרַס יָתָהּ קֳדָמַי וְהָא כְתִיבָא מֵאַפָּהָא וּמֵאֲחוֹרָהָא מַה דַהֲוָה מִן שְׁרוּיָא וּמַה דְעָתִיד לְמֶהֱוֵי בְּסוֹפָא וּכְתִיב בָּהּ דְאִם יֶעְבְּרוּן בֵּית יִשְׂרָאֵל עַל אוֹרַיְתָא יִשְׁלְטוּן בְהוֹן עַמְמַיָא וְאִם יַעַבְדוּן יַת אוֹרַיְתָא יְסוּף מִנְהוֹן אִלְיָא וּדְוָנָא וְתֵינַחְתָּא:\",0,0],[4,144,3,1,\"וַאֲמַר לִי בַּר אָדָם יַת דְמִתְיְהִיב לָךְ קַבֵּיל קַבֵּיל מַה דִכְתִיב בִּמְגִלְתָא הָדָא וַאֲזֵיל וְאִתְנַבֵּי עַל בֵּית יִשְׂרָאֵל:\",0,0],[4,144,3,2,\"וְאַרְכִינֵית יַת נַפְשִׁי וְאַחְכִּימֵינִי מַה דִכְתִיב בִּמְגִלְתָא הָדָא:\",0,0],[4,144,3,3,\"וַאֲמַר לִי בַּר אָדָם נַפְשָׁךְ תִּסְבַּע וּמֵעָךְ תְּמַלֵי אִם תְּקַבֵּיל מַה דִכְתִיב בִּמְגִלְתָא הָדָא דִי אֲנָא יָהֵיב לָךְ וְקַבֵּילְתָּהָא וַהֲווֹ פִּתְגָמָהָא בְּפוּמִי כִּדְבָשׁ חֲלִי:\",0,0],[4,144,3,4,\"וַאֲמַר לִי בַּר אָדָם אֱתָא אֲזִיל לְוַת בְּנֵי יִשְׂרָאֵל וְתִתְנַבֵּי בְּפִתְגָמֵי נְבוּאֲתִי לְהוֹן:\",0,0],[4,144,3,5,\"אֲרֵי לָא לְוַת עַם עִמְקֵי מְמַלֵל וְיַקִירֵי לִישָׁן אַתְּ שְׁלִיחַ לְאִתְנַבָּאָה אֱלָהֵין לְוַת בֵּית יִשְׂרָאֵל:\",0,0],[4,144,3,6,\"לָא לְוַת עַמְמַיָא סַגִיאִין תַּקִיפֵי מַמְלֵל וְיַקִירֵי לִישָׁן דְלָא תִשְׁמַע פִּתְגָמֵיהוֹן אִלּוּ לְוַתְהוֹן שְׁלַחְתָּךְ אִינוּן יְקַבְּלוּן מִנָךְ:\",0,0],[4,144,3,7,\"וּבֵית יִשְׂרָאֵל לָא יֵיבוּן לְקַבְּלָא מִנָךְ אֲרֵי לֵית אִינוּן צָבָן לְקַבָּלָא לְמֵימְרִי אֲרֵי כָּל בֵּית יִשְׂרָאֵל חֲצִיפֵי אַפִּין וְתַקִיפֵי לִבָּא אִינוּן:\",0,0],[4,144,3,8,\"הָא יַהֲבֵית יַת אַפָּךְ תַּקִיף כִּקְבֵּיל בֵּית אַפֵּיהוֹן וְיַת בֵּית עֵינָךְ חֲסִין כִּקְבֵיל בֵּית עֵינֵיהוֹן:\",0,0],[4,144,3,9,\"כְּמָא דְשָׁמִירָא תַּקִיף מִטִינָרָא כֵּן יַהֲבֵית יַת בֵּית עֵינָךְ חֲסִין כִּקְבֵיל בֵּית אַפֵּיהוֹן לָא תִדְחַל מִנְהוֹן וְלָא תִתְבַּר מִן קָדָמֵיהוֹן אֲרֵי עַם סַרְבָן אִינוּן:\",0,0],[4,144,3,10,\"וַאֲמַר לִי בַּר אָדָם יַת כָּל פִּתְגָמֵי דַאֲמַלֵיל עִמָךְ קַבֵּיל בְּלִבָּךְ וּבְאוּדְנָךְ שְׁמַע:\",0,0],[4,144,3,11,\"וֶאֱתָא אֱזֵיל לְוַת בְּנֵי גָלוּתָא לְוַת בְּנֵי עַמָךְ וְתִתְנַבֵּי לְהוֹן וְתֵימַר לְהוֹן כִּדְנַן אֲמַר יְיָ אֱלֹהִים אִם יְקַבְּלוּן אוּלְפַן וְאִם יִתְמַנְעוּן מִלְמֶחֱטֵי:\",0,0],[4,144,3,12,\"וּנְטַלְתַּנִי רוּחָא וְשִׁמְעֵית בַּתְרֵי קַל זִיעַ סַגִי דִמְשַׁבְּחִין וְאָמְרִין בְּרִיךְ יְקָרָא דַייָ מֵאֲתַר בֵּית שְׁכִינְתֵּיהּ:\",0,0],[4,144,3,13,\"וְקַל גַפֵּי בִּרְיָתָא נַקְשָׁן חַד לְחַד וְקַל גַלְגְלַיָא לְקִבְלֵהוֹן וְקַל זִיעַ סַגִי:\",0,0],[4,144,3,14,\"וְרוּחָא נְטָלַתְנִי וּנְסֵיבְתַּנִי וַאֲזֵלֵית בִּמְרִיר בִּתְקוֹף רוּחִי וּנְבוּאָה מִן קֳדָם יְיָ עֲלַי תַּקִיפַת:\",0,0],[4,144,3,15,\"וְאָתֵית לְוַת בְּנֵי גָלוּתָא לְתֵל אָבִיב דְיָתְבִין עַל נְהַר כְּבָר וְנָחֵית בֵּינֵיהוֹן וְאִינוּן יַתְבִין תַּמָן וִיתִיבֵית תַּמָן שַׁבְעָא יוֹמִין שָׁתִיק בֵּינֵיהוֹן:\",0,0],[4,144,3,16,\"וַהֲוָה מִסוֹף שַׁבְעָא יוֹמִין וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,3,17,\"בַּר אָדָם מַלֵיף מַנִיתָךְ לְבֵית יִשְׂרָאֵל וּתְקַבֵּיל מִמֵימְרִי פִּתְגַם וְתַזְהֵיר יַתְהוֹן מִלְמֶחֱטֵי קָדָמָי:\",0,0],[4,144,3,18,\"כַּד אֲמָרֵית לְרַשִׁיעָא מֵימַת תְּמוּת וְלָא אַזְהַרְתֵּיהּ וְלָא מַלֵילְתָּא לְאַזְהָרָה רַשִׁיעָא מֵאוֹרְחֵיהּ דְרִשְׁעָא לְקַיָמוּתֵהּ הוּא רַשִׁיעָא בְּחוֹבֵיהּ יְמוּת וּדְמֵיהּ מִן יְדָךְ אֶתְּבַע:\",0,0],[4,144,3,19,\"וְאַתְּ אֲרֵי אַזְהַרְתָּא רַשִׁיעָא וְלָא תָב מֵחוֹבֵיהּ וּמֵאוֹרְחֵיהּ דְרִשְׁעָא הוּא בְּחוֹבֵיהּ יְמוּת וְאַתְּ יַת נַפְשָׁךְ שֵׁיזַבְתָּא:\",0,0],[4,144,3,20,\"וְכַד יְתוּב זַכָּאָה מִזְכוּתֵיהּ וְיַעֲבֵיד שְׁקַר וְאֶתֵּן תַּקְלַת חוֹבִין קֳדָמוֹהִי הוּא יְמוּת אֲרֵי לָא אַזְהַרְתֵּיהּ בְּחוֹבֵיהּ יְמוּת וְלָא אִדַכְּרָן זַכְוָתֵיהּ דַעֲבַד וּדְמֵיהּ מִן יְדָךְ אֶתְּבַע:\",0,0],[4,144,3,21,\"וְאַתְּ אֲרֵי אַזְהַרְתְּ לְצַדִיקָא בְּדִיל דְלָא לְמֶחֱטֵי צַדִיקָא וְהוּא לָא חָטֵי מַחֵי יְחֵי אֲרֵי אִזְדָהֵר וְאַתְּ יַת נַפְשָׁךְ שֵׁיזַבְתָּא:\",0,0],[4,144,3,22,\"וּשְׁרַת עֲלַי תַּמָן רוּחַ נְבוּאָה מִן קֳדָם יְיָ וַאֲמַר לִי קוּם פּוּק לְבִקְעֲתָא וְתַמָן אֲמַלֵיל עִמָךְ:\",0,0],[4,144,3,23,\"וְקָמֵית וּנְפָקֵית לְבִקְעֲתָא וְהָא תַמָן יְקָרָא דַייָ שַׁרְיָא כִּיקָרָא דַחֲזֵיתִי עַל נְהַר כְּבָר וְאִשְׁתַּטְחֵית עַל אַפָּי:\",0,0],[4,144,3,24,\"וַעֲלַת בִּי רוּחָא וַאֲקֵימַתְנִי עַל רִגְלָי וּמַלֵיל עִמִי וַאֲמַר עוּל אִטַמַר בְּגוֹ בֵיתָךְ:\",0,0],[4,144,3,25,\"וְאַתְּ בַּר אָדָם הָא גְזָרֵית פִּתְגָמֵי פוּמִי עֲלָךְ כֶּאֱסוֹר גְדִילַן דְאָסְרִין בָּהֶן וְלָא תִפּוֹק בֵּינֵיהוֹן:\",0,0],[4,144,3,26,\"וְלִישָׁנָךְ אַדְבֵּיק לְחִכֵּךְ וְתִשְׁתּוֹק וְלָא תְהֵי לְהוֹן לִגְבַר מוֹכַח אֲרֵי עַם סַרְבָן אִינוּן:\",0,0],[4,144,3,27,\"וּבְמַלְלוּתִי עִמָךְ אַרְכִין יַת נַפְשָׁךְ וְתֵימַר לְהוֹן כִּדְנַן אֲמַר יְיָ אֱלֹהִים דִמְקַבֵּיל יְקַבֵּיל אוּלְפַן וְדִי יִתְמְנַע יִתְמְנַע מִלְמֶחֱטֵי אֲרֵי עַם סַרְבָן אִינוּן:\",0,0],[4,144,4,1,\"וְאַתְּ בַּר אָדָם סַב לָךְ אַבְנָא וְתִתֵּן יָתָהּ קָדָמָךְ וּתְצוֹר עֲלָהּ קַרְתָּא יַת יְרוּשְׁלֵם:\",0,0],[4,144,4,2,\"וְתִתֵּן עֲלָהּ צְיָר וְתִבְנֵי עֲלָהּ מִלְיָתָא וְתִשְׁרֵי עֲלָהּ מַשִׁרְיָן וּמַנֵי עֲלָהּ אֶפְדוֹרְוָן סְחוֹר סְחוֹר:\",0,0],[4,144,4,3,\"וְאַתְּ סַב לָךְ מַסְרֵית בַּרְזֵל וְתִתֵּן יָתָהּ כּוֹתֶל בַּרְזֶל בֵּינָךְ וּבֵין קַרְתָּא וְתַתְקֵן יַת אַפָךְ לָהּ וּתְהֵי בְצַיְרָא וּתְצוּר עֲלָהּ אָת הִיא לְבֵית יִשְׂרָאֵל:\",0,0],[4,144,4,4,\"וְאַתְּ שְׁכוּב עַל סִטְרָךְ דִסְמָלָא וּתְשַׁוֵי יַת חוֹבֵי בֵית יִשְׂרָאֵל עֲלוֹהִי מִנְיַן יוֹמַיָא דְתִשְׁכּוֹב עֲלוֹהִי תְּקַבֵּל יַת חוֹבֵיהוֹן:\",0,0],[4,144,4,5,\"וַאֲנָא יְהָבִית לָךְ עַל חַד תְּרֵין בְּחוֹבֵיהוֹן לְמִנְיַן יוֹמַיָא תְּלַת מְאָה וְתִשְׁעִין יוֹמִין וּתְקַבֵּיל חוֹבֵי בֵית יִשְׂרָאֵל:\",0,0],[4,144,4,6,\"וְתַשְׁלִים יַת אִלֵין וְתִשְׁכּוֹב עַל סִטְרָךְ דִיְמִינָא תִּנְיָנוּת וּתְקַבֵּיל יַת חוֹבֵי בֵית יְהוּדָה אַרְבְּעִין יוֹמִין יוֹמָא לְשַׁתָּא יוֹמָא לְשַׁתָּא יְהַבְתִּינוּן לָךְ:\",0,0],[4,144,4,7,\"וְלִצְיָר יְרוּשְׁלֵם תְּתַקֵין אַפָּךְ וְדַרְעָךְ תַּתְקֵיף וְתִתְנַבֵּי עֲלָהּ:\",0,0],[4,144,4,8,\"וְהָא גְזָרֵית פִּתְגָמֵי עֲלָךְ כֶּאֱסוּר גְדִילָן וְלָא תִתְהַפֵּיךְ מִסִטְרָךְ לְסִטְרָךְ עַד אַשְׁלְמוּתָךְ יוֹמֵי צַיְרָךְ:\",0,0],[4,144,4,9,\"וְאַתְּ סַב לָךְ חִטִין וּסְעוֹרִין וּפוֹלָא וּטְלוֹפְחִין וְדוֹחָן וְכוּנְתִּין וְתִתֵּן יַתְהוֹן לָךְ לְמֵיכַל מִנְיַן יוֹמַיָא דְאַתְּ שְׁכִיב עַל סִטְרָךְ תְּלַת מְאָה וְתִשְׁעִין יוֹמִין תֵּיכְלִינֵיהּ:\",0,0],[4,144,4,10,\"וּמֵיכְלָךְ דְתֵיכְלִינֵיהּ בְמַתְקַל עַסְרִין פִּילֵס לְיוֹם מֵעִדַן עַד עִדָן תֵּיכְלִינֵיהּ:\",0,0],[4,144,4,11,\"וּמַיָא בִּמְכִילָא תִשְׁתֵּי חַד מִן שַׁתָּא בְּהִינָא מֵעִדַן עַד עִדַן תִּשְׁתֵּי:\",0,0],[4,144,4,12,\"וַחֲרָרָא דִלְחַם שְׂעוֹרִין תֵּיכְלִינָהּ וְהִיא עַל גְלֵי מַפְקַת אֱנָשָׁא תַּחְרְרִינָה לְעֵינֵיהוֹן:\",0,0],[4,144,4,13,\"וַאֲמַר יְיָ כְּדֵין יֵיכְלוּן בְּנֵי יִשְׂרָאֵל יַת מֵיכַלְהוֹן מְסָאַב בֵּינֵי עַמְמַיָא דְאַגְלִינוּן לְתַמָן:\",0,0],[4,144,4,14,\"וַאֲמָרֵית קַבֵּיל בָּעוּתִי יְיָ אֱלֹהִים הָא נַפְשִׁי לָא מְסָאֲבָא וּנְבֵילָא וּתְבִירָא לָא אֲכָלֵית מִזְעוּרֵי וְעַד כְּעַן וְלָא אֲכָלֵית בְּסַר מְרָחָק:\",0,0],[4,144,4,15,\"וַאֲמַר לִי חֲזֵי דִיהָבֵית לָךְ יַת גְלֵי תוֹרַיָא חֲלַף גְלֵי אֱנָשָׁא וְתַעֲבֵיד יַת מֵיכְלָךְ עֲלֵיהוֹן:\",0,0],[4,144,4,16,\"וַאֲמַר לִי בַּר אָדָם הָא אֲנָא תָבֵר סְעִיד מֵיכְלָא בִּירוּשְׁלֵם וְיֵכְלוּן לַחְמָא בְּמַתְקַל וּבְיִצְפָּא וּמַיָא בְּצָדוּ וּבְאִשְׁתְּמָמוּ יִשְׁתּוּן:\",0,0],[4,144,4,17,\"בְּדִיל דְיַחְסַר לְהוֹן מֵיכַל וּמִשְׁתִּי וְיִצְדוֹן גְבַר וַאֲחוּהִי וְיִתְמְסוּן בְּחוֹבֵיהוֹן:\",0,0],[4,144,5,1,\"וְאַתְּ בַּר אָדָם סַב לָךְ חַרְבָּא חֲרִיפָא מַסְפַּר גַלְבַיָא תִּסַב לָךְ וְתַעְבֵּד עַל רֵישֵׁךְ וְעַל דִקְנָךְ וְתִסֵב לָךְ מוֹזְנָיָן דְמַתְקַל וְתַפְלְגִינוּן:\",0,0],[4,144,5,2,\"תִּלְתָּא בְּנוּרָא תַדְלֵיק בְּגוֹ קַרְתָּא כְּמִשְׁלַם יְמֵי צַיְרָא וְתִסַב יַת תִּלְתָּא תִּקְטֵיל בְּחַרְבָּא סָחֲרָנָהָא וְתִלְתָּא יִתְבַּדְרוּן וּדְקַטְלִין בְּחַרְבָּא אֱגָרֵי בַּתְרֵיהוֹן:\",0,0],[4,144,5,3,\"וְתִסֵב מִתַּמָן זְעֵיר בְּמִנְיַן וּתְצוּר יַתְהוֹן בִכְנָפָךְ:\",0,0],[4,144,5,4,\"וּמִנְהוֹן עוֹד תִּסַב וְתַרְמֵי יַתְהוֹן לְגוֹ נוּרָא וְתוֹקִיד יַתְהוֹן בְּנוּרָא בְּכֵן תִּפּוֹק אֶשְׁתָּא עַל כָּל בֵּית יִשְׂרָאֵל:\",0,0],[4,144,5,5,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים דָא יְרוּשְׁלֵם בְּגוֹ עַמְמַיָא שַׁוִיתָהָא וּסְחוֹר סְחוֹר לָהּ מְדִינָתָא:\",0,0],[4,144,5,6,\"וְאַשְׁנִיאַת יַת דִינִי לִמְחַבְּבֵיהוֹן מִן עַמְמַיָא וְיַת קְיָמִי מִן מְדִינָתָא דִי בְּסֶחֱרָנָהָא אֲרֵי בְּדִינַי קָצוּ וּקְיָמַי לָא הֲלִיכוּ בְהוֹן:\",0,0],[4,144,5,7,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים חֲלַף דְחַבְתּוּן מִן עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן בִּקְיָמַי לָא הֲלֵכְתּוּן וְיַת דִינַי לָא עֲבַדְתּוּן וּכְנִימוּסֵי עַמְמַיָא דִי בְסַחְרָנֵיכוֹן לָא עֲבַדְתּוּן:\",0,0],[4,144,5,8,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא שָׁלַח רוּגְזִי עֲלָךְ אַף אֲנָא וְאַעֲבֵּיד בְּגַוִיךְ פּוּרְעֲנוּת דִינִין לְעֵינֵי עַמְמַיָא:\",0,0],[4,144,5,9,\"וְאַעְבֵּיד בִּיךְ יַת דְלָא עֲבַדֵית וְיַת דְלָא אַעְבֵּיד דִכְוָתֵיהּ עוֹד חֲלַף כָּל תּוֹעֲבָתָיִךְ:\",0,0],[4,144,5,10,\"בְּכֵן אֲבָהָן יֵיכְלוּן בְּסַר בְּנֵיהוֹן בְּגַוִיךְ וּבְנַיָא יֵיכְלוּן בְּסַר אֲבָהָתְהוֹן וְאַעְבֵּיד בִּיךְ פּוּרְעֲנוּת דִינִין וַאֲבַדַר יַת כָּל שְׁאָר עַמִיךְ לְכָל רוּחַ:\",0,0],[4,144,5,11,\"בְּכֵן קַיָים אֲנָא אֲמַר יְיָ אֱלֹהִים אִם לָא חֲלַף דְמָקְדְשֵׁי סָאֵבְתְּ בְּכָל שִׁקוּצָיִךְ וּבְכָל תּוֹעֲבָתָיִךְ וְאַף אֲנָא אֶקְטוֹף תְּקוֹף דַרְעִיךְ וְלָא יָחוּס מֵימְרִי וְאַף אֲנָא לָא אֲרַחֵם:\",0,0],[4,144,5,12,\"תִּלְתִּיךְ בְּמוֹתָא יְמוּתוּן וּבְכַפְנָא יִשְׁתֵּיצוּן בְּגַוִיךְ וְתִלְתָּא בְּחַרְבָּא יִתְקַטְלוּן סַחֲרָנַיִךְ וְתִלְתָּא לְכָל רוּחַ אֲבַדַר וּדְקָטְלִין בְּחַרְבָּא אֱגָרֵי בַּתְרֵיהוֹן:\",0,0],[4,144,5,13,\"וְיָחוּל רוּגְזִי וַאֲנִיחַ חֵימְתִי בְהוֹן וַאֲסִיף וְיֵדְעוּן אֲרֵי אֲנָא יְיָ גְזַרֵית בְּמֵימְרִי וַאֲקַיֵים כַּד יָחוּל רוּגְזִי בְּהוֹן:\",0,0],[4,144,5,14,\"וְאֶתְּנִנָךְ לְחַרְבָּא וּלְחִסוּדִין בֵּינֵי עַמְמַיָא דִי בְסַחְרָנָךְ לְעֵינֵי כָּל דְעָדֵי:\",0,0],[4,144,5,15,\"וּתְהֵין לְחִסוּדִין וּלְאִתְרַבְרְבָא עֲלָךְ צָדוּ וְאִשְׁתְּמָמוּ לְעַמְמַיָא דִבְסָחֳרָנִיךְ כַּד אַעְבֵיד בִּיךְ פּוּרְעֲנוּת דִינִין בִּרְגַז וּבְחֵמָה וּבִתְקוֹף רְגַז אֲנָא יְיָ גְזַרֵית בְּמֵימְרִי:\",0,0],[4,144,5,16,\"בְּגָרָיוּתִי יַת מְחַת כַּפְנָא מַכְתָּשִׁין בִּישִׁין דִמְתַקְנִין לְחַבָּלָא דַאֲשַׁלַח יַתְהוֹן לְחַבָּלוּתְכוֹן וְכַפְנָא אוֹסִיף עֲלֵיכוֹן וְאִתְבַּר לְכוֹן סְעַד מֵיכְלָא:\",0,0],[4,144,5,17,\"וַאֲשַׁלַח עֲלֵיכוֹן כַּפְנָא וְחַיְתָא בִישְׁתָּא וְיִתְכְּלוּנַיִךְ וּמוֹתָא וּקְטָלָא יַעְדוּן בִּיךְ וּדְקָטְלִין בְּחַרְבָּא אַיְתֵי עֲלָךְ אֲנָא יְיָ גְזָרֵית בְּמֵימְרִי:\",0,0],[4,144,6,1,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,6,2,\"בַּר אָדָם קַבֵּל נְבוּאָה עַל טוּרֵי יִשְׂרָאֵל וְאִתְנַבֵּי עֲלֵיהוֹן:\",0,0],[4,144,6,3,\"וְתֵימַר טוּרֵי יִשְׂרָאֵל קַבִּילוּ פִתְגָמָא דַייָ אֱלֹהִים כִּדְנַן אֲמַר יְיָ אֱלֹהִים לְטוּרַיָא וּלְרָמָתָא וּלְפַצִידַיָא וּלְחֵילַיָא הָא אֲנָא מַיְתֵי עֲלֵיכוֹן דְקַטְלִין בְּחַרְבָּא וְאוֹבִיד בָּמָתֵיכוֹן:\",0,0],[4,144,6,4,\"וְיִצְדוּן אֱגוֹרֵיכוֹן וְיִתְבְּרוּן חֲנִיסְנְסֵיכוֹן וְאַרְמִי קְטִילֵיכוֹן קֳדָם פִּגוּר טַעֲוַתְכוֹן:\",0,0],[4,144,6,5,\"וְאֶתֵּן יַת פִּגְרֵי בְּנֵי יִשְׂרָאֵל קֳדָם פִּגּוּר טַעֲוַתְהוֹן וַאֲבַדֵר יַת גַרְמֵיכוֹן סִחְרָנוּת אֱגוֹרֵיכוֹן:\",0,0],[4,144,6,6,\"בְּכֵל מוֹתְבָנֵיכוֹן קִרְוַיָא יֶחֱרְבָן וּבְמָתָא יִצְדְיָן בְּדִיל דְיֶחֱרְבוּן וְיִצְדוּן אֱגוֹרֵיכוֹן וְיִתְבְּרָן וְיִבְטְלָן טַעֲוַתְכוֹן וְיִתְקַטְפוּן חֲנִסְנְסֵיכוֹן וְיִתְמְחוּן עוֹבָדֵיכוֹן:\",0,0],[4,144,6,7,\"וְיִתְרְמוּן קְטִילִין בֵּינֵיכוֹן וְתֵדְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,6,8,\"וְאַשְׁאַר בְּמֶהֱוֵי לְכוֹן מְשֵׁזְבֵי חַרְבָּא בֵּינֵי עַמְמַיָא בְּאִתְבַּדָרוּתֵיכוֹן בִּמְדִינָתָא:\",0,0],[4,144,6,9,\"וְיִדְכְּרוּן מְשֵׁיזְבֵיכוֹן דְחַלְתִּי בֵּינֵי עַמְמַיָא דְאִשְׁתְּבִיאוּ לְתַמָן דִתְבַרֵית יַת לִבְּהוֹן טִפְּשָׁא דִסְטָא מִבָּתַר פּוּלְחָנִי וְיַת חֵיזוּ עֵינֵיהוֹן דִטְעָא בָּתַר טַעֲוַתְהוֹן וְיִדַנְקוּן וִיהוֹן חָזַן עַל בִּישְׁתָּא דַעֲבַדוּ לְכָל תּוֹעֲבַתְהוֹן:\",0,0],[4,144,6,10,\"וְיֵדְעוּן אֲרֵי אֲנָא יְיָ לָא לְמַגָן גְזֵרֵית בְּמֵימְרִי לְמֶעְבַּד לְהוֹן בִּישְׁתָּא הָדָא:\",0,0],[4,144,6,11,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים טְפַּח בִּידָךְ וּרְפוֹס בְּרַגְלָךְ וַאֲמַר וַי עַל כָּל תּוֹעֲבָתָא בִּישְׁתָא בֵּית יִשְׂרָאֵל דִי בְּחַרְבָּא בְּכַפְנָא וּבְמוֹתָא יִתְרְמוּן:\",0,0],[4,144,6,12,\"דְרָחִיק בְּמוֹתָא יְמוּת וּדְקָרִיב בְּחַרְבָּא יִתְקְטֵיל וּדְיִשְׁתְּאַר וּדְיֵעוֹל לִכְרַכֵּי צַיְרָא בְּכַפְנָא יְמוּת וְיָחוּל רוּגְזִי בְּהוֹן:\",0,0],[4,144,6,13,\"וְתִדְעוּן אֲרֵי אֲנָא יְיָ בְּמֶהֱוֵי קְטִילֵיהוֹן בְּגוֹ פִּגוּר טַעֲוַתְהוֹן סַחֲרָנוּת אִגוֹרֵיהוֹן עַל כָּל רָמָא מְנַטְלָא בְּכָל רֵישֵׁי טוּרַיָא תְּחוֹת כָּל אִילָן עַבּוּף וּתְחוֹת כָּל בּוּטְמָא מְעַפְיָא אֲתַר דִיהַבוּ תַמָן קוּרְבָּנִין לְפוּלְחַן לְכָל טַעֲוַתְהוֹן:\",0,0],[4,144,6,14,\"וְאָרִים יַת מְחַת גְבוּרְתִּי עֲלֵיהוֹן וְאֶתֵּן יַת אַרְעָא לְצָדוּ וְאִשְׁתְּמָמוּ מִמִדְבַּר דִבְלָת בְּכָל מוֹתְבָנֵיהוֹן וְיֵדְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,7,1,\"וַהֲוָה פִּתְגָם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,7,2,\"וְאַתְּ בַּר אָדָם כִּדְנַן אֲמַר יְיָ אֱלֹהִים לְאַרְעָא דְיִשְׂרָאֵל קִצָא מְטָא מְטַת פּוּרְעֲנוּת קִצָא לְמֵיתֵי עַל אַרְבַּע רוּחֵי אַרְעָא:\",0,0],[4,144,7,3,\"כְּעַן מְטַת פּוּרְעֲנוּת קִצָא לְמֵיתֵי עֲלָךְ וְאֶשְׁלַח רוּגְזִי בִּיךְ וְאִתְפְּרַע מִנִיךְ כְּאוֹרְחָתַיִךְ וְאֶתֵּן עֲלָךְ יַת כָּל תּוֹעֲבָתָיִךְ:\",0,0],[4,144,7,4,\"וְלָא יְחוּס מֵימְרִי עֲלָךְ וְלָא אֶרְחַם אֲרֵי חוֹב אוֹרְחָתָיִךְ עֲלָךְ אֶתֵּן וּפוּרְעֲנוּת תּוֹעֲבָתַיִךְ בְּגַוִיךְ יֶהֶוְיָן וְתֵידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,7,5,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים בִּישְׁתָא בָּתַר בִּישְׁתָא הָא אַתְיָא:\",0,0],[4,144,7,6,\"קִצָא מְטָא מְטַת פּוּרְעֲנוּת קִיצָא לְמֵיתֵי עֲלַךְ הָא אַתְיָא:\",0,0],[4,144,7,7,\"אִתְגְלִיאַת מַלְכוּתָא עֲלָךְ יָתֵיב אַרְעָא מְטָא עִדַן תְּבִירַת קָרֵיב יוֹם אִתְרְגוּשָׁא וְלֵית לְאִשְׁתֵּיזָבָא בִּמְצָדֵי טוּרַיָא:\",0,0],[4,144,7,8,\"כְּעַן מִקָרֵיב אֶשְׁפּוֹךְ חֵימְתִי עֲלָךְ וְיֵחוֹל רוּגְזִי בִּיךְ וְאִתְפְּרַע מִנִיךְ כְּאוֹרְחָתָיִךְ וְאֶתֵּן עֲלָךְ יַת כָּל תּוֹעֲבָתָיִךְ:\",0,0],[4,144,7,9,\"וְלָא תְחוֹס מֵימְרִי וְלָא אֶרְחִים כְּחוֹבֵי אוֹרְחָתַיִךְ עֲלָךְ אֶתֵּן וּפוּרְעֲנוּת תּוֹעֲבָתַיִךְ בְּגַוִיךְ יֶהֱוְיָן וְתִדְעוּן אֲרֵי אֲנָא יְיָ אַיְתֵיתִי עֲלֵיכוֹן מְחָא:\",0,0],[4,144,7,10,\"הָא יוֹם פּוּרְעֲנוּתָא מְטָא הָא אַתְיָא אִתְגְלִיאַת מַלְכוּתָא צְמַח שׁוּלְטָנָא הוֹפַע רַשִׁיעָא:\",0,0],[4,144,7,11,\"חֲטוֹפִין קָמוּ לְמִסְעַר רַשִׁיעִין לָא מִנְהוֹן וְלָא מְאִתְרְגוּשְׁתְּהוֹן וְלָא מִבְּנֵיהוֹן וְלָא מִבְּנֵי בְּנֵיהוֹן:\",0,0],[4,144,7,12,\"מְטָא עִדָן תּוּשְׁלְמַת חוֹבִין קָרִיב יוֹם פּוּרְעֲנוּת חֶטְאִין זָבְנָא לָא יֶחֱדֵי וּמְזוֹבְנָא לָא יִדְוֵי אֲרֵי רְגַז מִן קֳדָמַי עַל כָּל אִתְרְגוּשַׁתְהוֹן:\",0,0],[4,144,7,13,\"אֲרֵי מְזוֹבְנָא לִזְבִינָא לָא יְתוּב וְעַד דְאִינוּן חַיָן יִרְדִינוּן בִּגְוִיָתְהוֹן אֲרֵי נְבִיַיָא מִתְנַבָּן עַל כָּל אִתְרְגוּשַׁתְהוֹן לְמֵיתַב בִּתְיוּבְתָּא וְלָא תָיְבִין גְבַר בְּחוֹבֵי נַפְשֵׁיהּ מִתְרְעָן וְעַד דְאִינוּן קַיָמִין בִּתְיוּבְתָּא לָא מִתַּקְפִין:\",0,0],[4,144,7,14,\"נַפְקִין בְּאַצְוָחַת קַרְנָא מִתַקְנִין בְּמָנֵי זְיָנָא וְלֵית דְאָזִיל לִקְרָבָא אֲרֵי רְגַז מִן קֳדָמַי עַל כָּל אִתְרְגוּשַׁתְהוֹן:\",0,0],[4,144,7,15,\"חַרְבָּא מִלְבָרָא וּמוֹתָא וְכַפְנָא מִלְגָיו דִבְחַקְלָא בְּחַרְבָּא יִתְקְטֵיל וְדִי בְקַרְתָּא כַּפְנָא וּמוֹתָא יְשֵׁיצִינֵיהּ:\",0,0],[4,144,7,16,\"וּמְשֵׁיזְבַיָא יִשְׁתֵּיזְבוּן מִנְהוֹן וִיהוֹן עַל טוּרַיָא כְּיוֹנֵי חֵילַיָא כּוּלְהוֹן מְנַהֲמִין גְבַר בְּחוּבֵי נַפְשֵׁיהּ:\",0,0],[4,144,7,17,\"כָּל יְדַיָא יִתְרַשְׁלָן וְכָל רְכִיבַיָא יִתְאַשְׁדָן מַיָא:\",0,0],[4,144,7,18,\"וְיֵסְרוּן סַקִין וְתַחְפֵי יַתְהוֹן אִתְכְּנָעוּתָא וְעַל כָּל אַפֵּיהוֹן בַּהֲתָא וּבְכָל רֵישֵׁיהוֹן מְרַט:\",0,0],[4,144,7,19,\"כַּסְפֵּהוֹן בְּשׁוּקִין יִרְמוֹן וּדְהַבְהוֹן לְבוּסְרָן יְהֵי כַּסְפֵּיהוֹן וּדְהַבְהוֹן לָא יִכּוּל לְשֵׁיזָבוּתְהוֹן בְּיוֹם רוּגְזָא דַייָ נַפְשֵׁיהוֹן לָא יִסְבְּעוּן וּמֵעֵיהוֹן לָא יִמְלוּן אֲרֵי לְתַקְלַת חוֹבִין יְהֵי:\",0,0],[4,144,7,20,\"וְחֶדְוַת תִּקוּנֵיהּ לִיקַר יְהַבְתֵּיהּ וְאִינוּן צַלְמֵי תוֹעֲבַתְהוֹן שִׁקוּצֵיהוֹן עֲבַדוּ בֵיהּ עַל כֵּן יְהַבְתֵּיהּ לְהוֹן לְבוּסְרָן:\",0,0],[4,144,7,21,\"וְאֶמְסְרִנֵיהּ בְּיַד רַשִׁיעִין לְמִבַז וּלְחַיָבֵי אַרְעָא לַעֲדִי וְיַחֲלוּנֵיהּ:\",0,0],[4,144,7,22,\"וַאֲסַלֵיק שְׁכִינְתִּי מִנְהוֹן עַל דְאָחִילוּ יַת אַרְעָא בֵּית שְׁכִינְתִּי וְיַעֲלוּן בָּהּ רַשִׁיעִין וְיַחֲלוּנָהּ:\",0,0],[4,144,7,23,\"עֲבֵיד שִׁלְשְׁלָן אֲרֵי אַרְעָא אִתְמְלִיאַת חַיָבֵי קְטוֹל וְקַרְתָּא אִתְמְלִיאַת חֲטוֹפִין:\",0,0],[4,144,7,24,\"וְאַיְתֵי מַבְאִשֵׁי עַמְמַיָא וְיַחְסְנוּן יַת בָּתֵּיהוֹן וַאֲבַטֵיל רְבוּת רַשִׁיעִין וְיִתָּחֲלוּן מִקְדָשֵׁיהוֹן:\",0,0],[4,144,7,25,\"אִתְקְפָדַת מְטַת וְיִבְעוֹן שְׁלָמָא וְלֵית:\",0,0],[4,144,7,26,\"תְּבַר עַל תְּבַר יֵיתִי וּכְסוֹרְתָּא עַל בְּסוֹרְתָּא תְּהֵי וְיִבְעוּן אוּלְפַן מִסָפֵר וְאוֹרָאָה תִּפְסוֹק מִכָּהֵן וּמְלַךְ מְחַכִּים:\",0,0],[4,144,7,27,\"מַלְכָּא יִתְאַבַּל וְרַבָּא יִלְבַּשׁ צָדוּ וִידֵי עַמָא דְאַרְעָא יִתְבַּהֲלָן מֵאָרְחֵיהוֹן אַעְבֵיד עִמְהוֹן וּבְנִימוּסֵיהוֹן אִתְפְּרַע מִנְהוֹן וְיֵדְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,8,1,\"וַהֲוָה בְּשַׁתָּא שְׁתִיתֵי בִּשְׁתִיתָאָה בְּחַמְשָׁא לְיַרְחָא אֲמַר נְבִיָא אֲנָא יָתֵיב בְּבֵיתִי וְסָבֵי בֵּית יְהוּדָה יָתְבִין קֳדָמַי וּשְׁרַת עֲלַי תַּמָן רוּחַ נְבוּאָה מִן קֳדָם יְיָ אֱלֹהִים:\",0,0],[4,144,8,2,\"וַחֲזֵית וְהָא דְמוּת כְּחֵיזוּ אֶשְׁתָּא חֵיזוּ יְקַר דְלָא יָכְלָא עֵינָא לְמֶחֱזֵי וְלֵית אֶפְשַׁר לְאִסְתַּכָּלָא בֵּיהּ וּלְרַע חֵיזוּ אֶשְׁתָּא וְחֵיזוּ יְקָר דְלָא יָכְלָא עֵינָא לְמֶחֱזֵי וְלָא אֶפְשַׁר לְאִסְתַּכָּלָא בֵּיהּ וּלְעֵילָא כְּחֵיזוּ זָהֳרָא כְּעֵין חַשְׁמַל:\",0,0],[4,144,8,3,\"וְאוֹשִׁיט דְמוּת יַד וְאַחֲדַנִי בִּסְעַר רֵישִׁי וּנְטָלַת יָתִי רוּחָא בֵּין אַרְעָא וּבֵין שְׁמַיָא וְאָעֲלַת יָתִי לִירוּשְׁלֵם בְּחֵיזוּ נְבוּאָה דִשְׁרַת עֲלֵי מִן קֳדָם יְיָ בְּמַעֲלָנָא דְתַרְעָא גַוָאָה דִפְתִיחַ לְצִפּוּנָא דְתַמָן מוֹתַב צְלַם קִנְאֲתָא דְמַרְגְזִין:\",0,0],[4,144,8,4,\"וְהָא תַמָן יְקַר אֱלָהָא דְיִשְׂרָאֵל כְּחֵיזְוָא דַחֲזֵיתִי בְּבִקְעֲתָא:\",0,0],[4,144,8,5,\"וַאֲמַר לִי בַּר אָדָם זְקוֹף כְּעַן עֵינָךְ לְאוֹרַח צִפּוּנָא וּזְקָפֵית עֵינַי לְאוֹרַח צִפּוּנָא וְהָא מִצִפּוּנָא לִתְרַע מַדְבְּחָא צְלַם קִנְאָתָא הָדֵין בְּמַעֲלָנָא:\",0,0],[4,144,8,6,\"וַאֲמַר לִי בַּר אָדָם חֲזֵי אַתְּ מַה דְאִינוּן עָבְדִין תּוֹעֵיבָן רַבְרְבָן דְבֵית יִשְׂרָאֵל עָבְדִין בָּא לְאִתְרַחֲקָא מֵעַל מַקְדְשִׁי וְעוֹד תְּתוּב תֶּחֱזֵי תוֹעֵיבָן רַבְרְבָן:\",0,0],[4,144,8,7,\"וְאָעֵיל יָתִי לִתְרַע דָרָתָא וַחֲזֵית וְהָא חוֹרָא חַד בְּכוֹתְלָא:\",0,0],[4,144,8,8,\"וַאֲמַר לִי בַּר אָדָם חֲתוֹר כְּעַן בְּכוֹתָלָא וַחֲתָרֵית בְּכוֹתְלָא וְהָא תַּרְעָא חָד:\",0,0],[4,144,8,9,\"וַאֲמַר לִי עוּל וַחֲזֵי יַת תּוֹעֲבָתָא בִישָׁתָא דְאִינוּן עָבְדִין בָּא:\",0,0],[4,144,8,10,\"וַעֲלֵית וַחֲזֵית וְהָא כָל דְמוּת רְחִישׁ וּבְעִירָא שִׁקוּצִין וְכָל טַעֲוָתָא דְפָּלְחִין לְהוֹן בֵּית יִשְׂרָאֵל מְצַיְרִין עַל כִּתְלָא סְחוֹר סְחוֹר:\",0,0],[4,144,8,11,\"וְשַׁבְעִין גַבְרָא מִסָבֵי בֵית יִשְׂרָאֵל וְיַאֲזַנְיָה בַּר שָׁפָן קָאֵם בֵּינֵיהוֹן קַיְמִין קֳדָמֵיהוֹן וּגְבַר מַחְתְּיָתֵיהּ דִקְטַרְתָּא בִּידֵיהּ וִיטוּר עֲנַן קְטַרְתָּא סְלִיק:\",0,0],[4,144,8,12,\"וַאֲמַר לִי הַחֲזֵיתָא בַּר אָדָם דְסָבֵי בֵית יִשְׂרָאֵל עָבְדִין בְּקִבְלָא גְבַר בְּאִידְרוֹן בֵּית מִשְׁכְּבֵיהּ אֲרֵי אָמְרִין לָא גְלַן עוֹבָדָנָא קֳדָם יְיָ רָחִיק יְיָ יַת אַרְעָא:\",0,0],[4,144,8,13,\"וַאֲמַר לִי עוֹד תְּתוּב תֶּחֱזַי תּוֹעֵיבָן רַבְרְבָן דְאִינוּן עָבְדִין:\",0,0],[4,144,8,14,\"וְאָעֵיל יָתִי בְּמַעֲלָנָא דִתְרַע בֵּית מַקְדָשָׁא דַייָ דִפְּתִיחַ לְצִפּוּנָא וְהָא תַמָן נְשַׁיָא יָתְבָן מְבַכָּן יַת תִּמוּזָא:\",0,0],[4,144,8,15,\"וַאֲמַר לִי הַחֲזֵיתָא בַר אָדָם עוֹד תְּתוּב תֶּחֱזֵי תּוֹעֵיבָן רַבְרְבָן מֵאִלֵין:\",0,0],[4,144,8,16,\"וְאָעֵיל יָתִי לְדָרַת בֵּית מַקְדְשָׁא דַייָ גְוִיָתָא וְהָא תְרַע הֵיכְלָא דַייָ בֵּין אוּלָמָא וּבֵין מַדְבְּחָא כְּעַשְׂרִין וְחַמְשָׁא גַבְרָא אֲחוֹרֵיהוֹן לְהֵיכְלָא דַייָ וְאַפֵּיהוֹן לְמַדִינְחָא וְהָא אִינוּן מִתְחַבְּלִין וְסָגְדִין לְמַדִינְחָא לְשִׁמְשָׁא:\",0,0],[4,144,8,17,\"וַאֲמַר לִי הָא חֲזֵיתָא בַּר אָדָם הַזְעֵיר לְבֵית יְהוּדָה מִלְמֶעֱבַּד יַת תּוֹעֶבְתָּא דַעֲבָדוּ כָא אֲרֵי מְלוֹ יַת אַרְעָא חֲטוּפִין וְתָבוּ לְאַרְגָזָא קֳדָמַי וְהָא אִינוּן מַיְתָן בַּהֲתָא לְאַפֵּיהוֹן:\",0,0],[4,144,8,18,\"וְאַף אֲנָא אַעְבֵּיד בִּרְגַז לָא יָחוּס מֵימְרִי וְלָא אֶרְחַם וִיצַלוּן קֳדָמַי בְּקַל רָב וְלָא אֲקַבֵּל צְלוֹתְהוֹן:\",0,0],[4,144,9,1,\"וְאִכְלֵי וַאֲנָא שְׁמַע קַל רַב לְמֵימָר אִתְקְרָבוּ דִמְמַנָן עַל קַרְתָּא וּגְבַר מָן חִבּוּלֵיהּ בִּידֵיהּ:\",0,0],[4,144,9,2,\"וְהָא שִׁתָּא גַבְרִין אָתָן מֵאוֹרַח תַּרְעָא עִלָאָה דִפְתִיחַ לְצִפּוּנָא וּגְבַר מִן כִּידוּרֵיהּ בִּידֵיהּ וְגַבְרָא חָד בֵּינֵיהוֹן לָבֵישׁ לְבוּשִׁין וּפִנְקֵס סַפְרָא בְּחַרְצֵיהּ וַעֲלוּ וְקָמוּ בִּסְטַר מַדְבְּחָא דִנְחָשָׁא:\",0,0],[4,144,9,3,\"וִיקָר אֱלָהָא דְיִשְׂרָאֵל אִסְתַּלָק בִּכְרוּבָא דַהֲוָה שָׁרֵי עֲלוֹהִי בֵּית קוֹדֶשׁ קוּדְשַׁיָא וּשְׁרָא מֵעֵיל לָקֳבֵיל סְקוּפַת בֵּיתָא וּקְרָא לְגַבְרָא דְלָבִישׁ לְבוּשַׁיָא דְפִנְקֵס סַפְרָא בְּחַרְצֵיהּ:\",0,0],[4,144,9,4,\"וַאֲמַר יְיָ לֵיהּ עֲבַר בְּגוֹ קַרְתָּא בְּגוֹ יְרוּשְׁלֵם וְתִרְשׁוֹם תְּוָא עַל בֵּית עֵינֵי גַבְרַיָא דִמְאַנְחִין וְדִמְאַנְקִין עַל כָּל תּוֹעֶבְתָּא דְאִתְעֲבִידָא בְּגַוָהּ:\",0,0],[4,144,9,5,\"וּלְאִילֵן אֲמַר וַאֲנָא שָׁמַע עֲבָרוּ בְּקַרְתָּא בַּתְרוֹהִי וּקְטוּלוּ לָא תֶחוּס עֵינֵיכוֹן וְלָא תְרַחֲמוּן:\",0,0],[4,144,9,6,\"סָב עוּלֵם וּבְתוּלָה טַפְלָא וּנְשַׁיָא תִּקְטְלוּן לְחַבָּלָא וְעַל כָּל גַבְרָא דַעֲלוֹהִי רוּשָׁם תְּוָא לָא תִקְרְבוּן וּמִבֵּית מַקְדְשִׁי תִּשְׁרוּן וּשְׁרִיאוּ בְּגַבְרַיָא סָבַיָא דְקָדָם בֵּיתָא:\",0,0],[4,144,9,7,\"וַאֲמַר לְהוֹן סָאִיבוּ יַת בֵּיתָא וּמְלוֹ יַת דָרָתָא קְטִילִין פּוּקוּ וּנְפַקוּ וּקְטַלוּ בְקַרְתָּא:\",0,0],[4,144,9,8,\"וַהֲוָה כְּקַטָלוּתְהוֹן וְאִשְׁתְּאַרֵית אֲנָא וְאִשְׁתַּטְחֵית עַל אַפֵּי וּצְוַחֵית וַאֲמַרֵית קַבֵּיל בָּעוּתִי יְיָ אֱלֹהִים הַמְחַבֵּל אַתְּ יַת כָּל שְׁאָרָא דְיִשְׂרָאֵל בְּמִשְׁפְּכָךְ יַת חֵימְתָךְ עַל יְרוּשְׁלֵם:\",0,0],[4,144,9,9,\"וַאֲמַר לִי חוֹבֵי בֵּית יִשְׂרָאֵל וִיהוּדָה תַּקִיפוּ בָּהּ לַחֲדָא אִתְמְלִיאַת אַרְעָא חַיָיבֵי קְטוֹל וְקַרְתָּא אִתְמְלִיאַת אַסְטָיוּת דִין אֲרֵי אֲמַרוּ רָחִיק יְיָ יַת יָתְבֵי אַרְעָא וְלֵית דְאִיגַלְיָא קֳדָם יְיָ:\",0,0],[4,144,9,10,\"וְאַף אֲנָא לָא אָחוּס מֵימְרִי וְלָא אַרְחֵים פּוּרְעֲנוּת אוֹרְחַתְהוֹן בְּרֵישֵׁיהוֹן יְהָבִית:\",0,0],[4,144,9,11,\"וְהָא גַבְרָא דְלָבֵישׁ לְבוּשָׁא דְפִנְקָסָא בְּחַרְצֵיהּ מֵתִיב פִּתְגָמָא לְמֵימַר עֲבָדֵית כְּמָא דְפַקֵדְתָּנִי:\",0,0],[4,144,10,1,\"וַחֲזֵית וְהָא בִרְקִיעָא דִי עַל רֵישׁ כְּרוּבַיָא כַּאֲבַן טָבָא כְּחֵיזוּ דְמוּת כּוּרְסְיָא אִתְחַזֵי עֲלֵיהוֹן:\",0,0],[4,144,10,2,\"וַאֲמַר לְגַבְרָא דְלָבֵישׁ לְבוּשַׁיָא וַאֲמַר עוּל לְבֵינֵי גִלְגְלַיָא לִתְחוֹת כְּרוּבָא וּמַלֵי חוּפְנָךְ גוּמְרִין דְאֶשָׁא מִבֵּינֵי כְרוּבַיָא וּזְרוֹק עַל קַרְתָּא וְעַל וַאֲנָא חָזֵי:\",0,0],[4,144,10,3,\"וּכְרוּבַיָא קַיְמִין מִדָרוֹם לְבֵיתָא בְּמֵיעַל גַבְרָא וַעֲנַן אֲמִיטְתָא אִתְמְלִיאַת יַת דַרְתָּא גַוַיְתָא:\",0,0],[4,144,10,4,\"וְאִסְתַּלֵק יְקָרָא דַייָ בִּכְרוּבָא דַהֲוָה שָׁרֵי עֲלוֹהִי וּשְׁרָא מֵעֵיל לָקֳבֵיל סְקוּפַת בֵּיתָא וְאִתְמְלִיאַת בֵּיתָא יַת עֲנַן אֲמִיטְתָא וְדַרְתָּא אִתְמְלִיאַת יַת זְהוֹר יְקָרָא דַיָי:\",0,0],[4,144,10,5,\"וְקַל כַּנְפֵי כְרוּבַיָא אִשְׁתְּמַע עַד דַרְתָּא בִּרְיָתָא כְקָלָא מִן קֳדָם שַׁדַי בְּמִלוּלָא:\",0,0],[4,144,10,6,\"וַהֲוָה בְּפַקְדוּתֵיהּ יַת גַבְרָא דְלָבֵישׁ לְבוּשַׁיָא לְמֵימַר סָב אֶשְׁתָּא מִבֵּינֵי גַלְגְלַיָא מִבֵּינֵי כְרוּבַיָא וְעַל וְקָם בִּסְטַר גַלְגְלָא:\",0,0],[4,144,10,7,\"וְאוֹשִׁיט כְּרוּבָא יַת יְדֵיהּ מִבֵּינֵי כְרוּבַיָא לְאֶשְׁתָּא דִי בֵּינֵי כְרוּבַיָא וּנְסֵיב וִיהַב לְחָפְנִי דְלָבֵישׁ לְבוּשַׁיָא וּנְסִיב וּנְפַק:\",0,0],[4,144,10,8,\"וְאִתְחַזֵי לַכְרוּבַיָא דְמוּת יַד אֱנָשָׁא תְּחוֹת גַפֵּיהוֹן:\",0,0],[4,144,10,9,\"וַחֲזֵית וְהָא אַרְבְּעָא גַלְגְלַיָא בִּסְטַר כְּרוּבַיָא גַלְגַל חַד בִּסְטַר כְּרוּבָא חָד וְגַלְגַל חַד בִּסְטַר כְּרוּבָא חָד וְחֵיזוּ גַלְגְלַיָא כְּעֵין אֲבַן טָבָא:\",0,0],[4,144,10,10,\"וְחֶזְוֵיהוֹן דְמוּת חָד לְאַרְבַּעְתְּהוֹן כְּמָא דַהֲוֵי גַלְגַל בְּגוֹ גַלְגַל:\",0,0],[4,144,10,11,\"בְּמֵיזַלְהוֹן עַל אַרְבַּעַת סִטְרֵיהוֹן אָזְלִין לָא מִתְחַזְרִין בְּמֵיזַלְהוֹן אֲרֵי לְאַתְרָא דְמִתְפְּנֵי קַדְמָאָה בַּתְרוֹהִי אָזְלִין וְלָא מִתְחַזְרִין בְּמֵיזַלְהוֹן:\",0,0],[4,144,10,12,\"וְכָל בִּסְרֵיהוֹן וְגַבֵּיהוֹן וְאֶשְׁדַתְהוֹן וְכַנְפֵיהוֹן וְגַלְגְלַיָא מְלַן עַיְנִין סְחוֹר סְחוֹר לְאַרְבַּעְתְּהוֹן דְגַלְגְלַיָא:\",0,0],[4,144,10,13,\"לְאוֹפְנַיָא לְהוֹן אִתְקְרֵי גַלְגְלָא וַאֲנָא שְׁמַע:\",0,0],[4,144,10,14,\"וְאַרְבָּעָא אַפִּין לְחַד אַפֵּי חַד אַפֵּי כְרוּבָא וְאַפֵּי תִנְיָנָא אַפֵּי אֱנָשָׁא וּתְלִיתָאָה אַפֵּי אַרְיָא וּרְבִיעָאָה אַפֵּי נִשְׁרָא:\",0,0],[4,144,10,15,\"וְאִתְרָמוּ כְּרוּבַיָא אִינוּן בִּרְיָתָא דִי חֲזֵיתִי בִּנְהַר כְּבָר:\",0,0],[4,144,10,16,\"וּבְמֵיזַל כְּרוּבַיָא אָזְלִין גַלְגְלַיָא לְקִבְלֵיהוֹן וּבְמִטַל כְּרוּבַיָא יַת גַפֵּיהוֹן לְאִתְרָמָא כְּמִלְרַע לְרוּם שְׁמַיָא לָא מִתְחַזְרִין גַלְגְלַיָא אַף אִינוּן מִקִבְלֵיהוֹן:\",0,0],[4,144,10,17,\"בִּמְקָמְהוֹן קַיְמִין וּבְאִתְרָמוּתְהוֹן מִתְרְמִין עִמְהוֹן אֲרֵי בְרוּחַ בִּרְיָתָא בְּהוֹן:\",0,0],[4,144,10,18,\"וְאִסְתַּלֵק יְקָרָא דַייָ דַהֲוָה שָׁרַי עֲלוֹהִי מֵעֵיל לָקֳבֵיל סְקוּפַת בֵּיתָא וּשְׁרָא עַל כְּרוּבַיָא:\",0,0],[4,144,10,19,\"וּנְטַלוּ כְּרוּבַיָא יַת גַפֵּיהוֹן וְאִתְרָמוּ כְמִלְרַע לְרוּם שְׁמַיָא וַאֲנָא חָזֵי בְּמִפַקְהוֹן וְגַלְגְלַיָא לְקִבְלֵיהוֹן וְקָם בְּמַעֲלָנָא דִתְרַע בֵּית מַקְדְשָׁא דַייָ מַדִינְחָאָה וִיקָר אֱלָהָא דְיִשְׂרָאֵל עֲלֵיהוֹן מִלְעֵלָא:\",0,0],[4,144,10,20,\"אִינוּן בִּרְיָתָא דַחֲזֵיתִי תְּחוֹת יְקַד אֱלָהָא דְיִשְׂרָאֵל בִּנְהַר כְּבָר וִידָעִית אֲרֵי כְרוּבַיָא אִינוּן:\",0,0],[4,144,10,21,\"אַרְבַּע אַרְבַּע אַפִּין לְחַד וְאַרְבַּע גַפִּין לְחַד וּדְמוּת יַד אֱנָשָׁא תְּחוֹת גַפֵּיהוֹן:\",0,0],[4,144,10,22,\"וּדְמוּת אַפֵּיהוֹן אִינוּן אַפַּיָא דִי חֲזֵיתִי עַל נְהַר כְּבָר חֶזְוֵיהוֹן וְאִינוּן בִּרְיָא לָקֳבֵיל אַפָּהָא אָזְלָא:\",0,0],[4,144,11,1,\"וּנְטָלַת יָתִי רוּחָא וְאָעַלָת יָתִי לִתְרַע בֵּית מַקְדְשָׁא דַייָ מַדִינְחָאָה דִפְתִיחַ לְמַדִינְחָא וְהָא בְּמַעֲלָנָא דִתְרַע עַסְרִין וְחַמְשָׁא גַבְרִין וַחֲזֵית בֵּינֵיהוֹן יַת יַאֲזַנְיָה בַּר עַזֻר וְיַת פְּלַטְיָא בַּר בְּנָיָא רַבְרְבֵי עַמָא:\",0,0],[4,144,11,2,\"וַאֲמַר לִי בַּר אָדָם אִלֵין גַבְרַיָא דִמְחַשְׁבִין לְמֵינַס וּדְמָלְכִין מְלַךְ בִּישׁ בְּקַרְתָּא הָדָא:\",0,0],[4,144,11,3,\"דְאָמְרִין לָא בְקָרִיב לְמִבְנֵי בָתִּין הִיא חֲשִׁיבָא לָנָא כְדוּדָא וַאֲנַחְנָא חֲשִׁיבִין בְּגַוָהּ כְּבִסְרָא דִבְשִׁיל בְּגוֹ דוּדָא:\",0,0],[4,144,11,4,\"בְּכֵן אִתְנַבֵּי עֲלֵיהוֹן אִתְנַבֵּי בַּר אָדָם:\",0,0],[4,144,11,5,\"וּשְׁרַת עֲלֵי רוּחַ נְבוּאָה מִן קֳדָם יְיָ וַאֲמַר לִי אֱמַר כִּדְנַן אֲמַר יְיָ כֵּן אֲמַרְתּוּן בֵּית יִשְׂרָאֵל וְדִי אַתּוּן מְהַרְהֲרִין וְדִסְלִיקַת עַל לִבְּכוֹן קֳדָמַי גְלַן:\",0,0],[4,144,11,6,\"אַסְגֵיתוּן קְטִילֵכוֹן בְּקַרְתָּא הָדָא וּמְלֵיתוּן שׁוּקָהָא קְטִילִין:\",0,0],[4,144,11,7,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים קְטִילֵיכוֹן דְשַׁוִיתוּן בְּגַוָהּ אִינוּן כְּבִסְרָא וְהָא כְדוּדָא וְיַתְכוֹן אַגְלֵי מִגַוָהּ:\",0,0],[4,144,11,8,\"מִן קֳדָם דְקָטְלִין בְּחַרְבָּא דְחַלְתּוּן וּדְקָטְלִין בְּחַרְבָּא אַיְתִי עֲלֵיכוֹן אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,11,9,\"וְאַגְלֵי יַתְכוֹן מִגַוָהּ וְאֶמְסַר יַתְכוֹן בְּיַד נוּכְרָאִין וְאַעְבֵּיד בְּכוֹן פּוּרְעֲנוּת דִינִין:\",0,0],[4,144,11,10,\"בְּחַרְבָּא תִּתְקַטְלוּן עַל תְּחוּם אַרְעָא דְיִשְׂרָאֵל אִתְפְּרַע מִנְכוֹן וְתֵידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,11,11,\"הִיא לָא תְהֵי לְכוֹן כְּדוּדָא בְּרַם אַתּוּן תְּהוֹן בְּגַוָהּ כְּבִסְרָא דִבְשִׁיל בְּגוֹ דוּדָא עַל תְּחוּם אַרְעָא דְיִשְׂרָאֵל אֶתְפְּרַע מִנְכוֹן:\",0,0],[4,144,11,12,\"וְתֵידְעוּן אֲרֵי אֲנָא יְיָ דִי בִקְיָמַי לָא הַלֵיכְתּוּן וְדִינַי לָא עֲבַדְתּוּן וּכְנִימוּסֵי עַמְמַיָא דִי בְסָחְרָנֵיכוֹן עֲבַדְתּוּן:\",0,0],[4,144,11,13,\"וַהֲוָה כְּאִתְנַבָּיוּתִי וּפְלַטְיָה בַר בְּנָיָה מִית וְאִשְׁתַּטְחֵית עַל אַפֵּי וּצְוָחֵית בְּקַל רַב וַאֲמָרֵית קַבֵּיל בָּעוּתִי יְיָ אֱלֹהִים גְמִירָא אַתְּ עֲבִיד עִם שְׁאָרָא דְיִשְׂרָאֵל:\",0,0],[4,144,11,14,\"וַהֲוָה פִּתְגָם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,11,15,\"בַּר אָדָם אֲחַךְ אֲחַךְ אֱנַשׁ קָרִיבָךְ וְכָל בֵּית יִשְׂרָאֵל כּוּלְהוֹן דְאָמְרִין לְהוֹן יַתְבֵי יְרוּשְׁלֵם אִתְרְחָקוּ מִדְחַלְתָּא דַייָ דִילָנָא הִיא אִתְיְהִיבַת אַרְעָא לְמֵירְתָּה:\",0,0],[4,144,11,16,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים אֲרֵי אַרְחֵיקְתִּינוּן לְבֵינֵי עַמְמַיָא וַאֲרֵי בְדַרְתִּינוּן בִמְדִינָתָא וִיהָבֵית לְהוֹן בָתֵּי כְנִשְׁתָּא תִּנְיָן לְבֵית מַקְדְשִׁי וְאִינוּן כִּזְעֵיר בִּמְדִינָתָא דְאִתְגִלִיאוּ לְתַמָן:\",0,0],[4,144,11,17,\"בְּכֵן אֲמַר כִּדְנַן אֲמַר יְיָ אֱלֹהִים וַאֲקָרֵיב יַתְכוֹן מִן בֵּינֵי עַמְמַיָא וְאַכְנֵישׁ יַתְכוֹן מִן מְדִינָתָא דְאִתְבַּדַרְתּוּן בְּהֵן וְאֶתֵּן לְכוֹן יַת אַרְעָא דְיִשְׂרָאֵל:\",0,0],[4,144,11,18,\"וְיֶעֱלוּן לְתַמָן וְיַעְדוּן יַת כָּל שִׁקוּצָא וְיַת כָּל תּוֹעֲבָתָא מִנָהּ:\",0,0],[4,144,11,19,\"וְאֶתֵּן לְהוֹן לֵב דְחִיל וְרוּחַ דְחִילָא אֶתֵּן בְּמֵעֵיהוֹן וְאֶתְּבַר לִבָּא דְרַשִׁיעָא דְהוּא תַּקִיף כְּאַבְנָא מִבִּסְרֵיהוֹן וְאֶתֵּן לְהוֹן לֵב דָחִיל קֳדָמַי לְמֶעְבַד רְעוּתָי:\",0,0],[4,144,11,20,\"בְּדִיל דְבִקְיָמַי יְהָכִין וְיַת דִינַי יִטְרוּן וְיַעַבְּדוּן יַתְהוֹן וִיהוֹן קֳדָמַי לְעַם וַאֲנָא אֶהֱוֵי לְהוֹן לֶאֱלָהָא:\",0,0],[4,144,11,21,\"בָּתַר פּוּלְחַן שִׁקוּצֵיהוֹן וְתוֹעֲבָתְהוֹן לִבְּהוֹן טָעֵי פּוּרְעֲנוּת אוֹרְחֵיהוֹן בְּרֵישֵׁיהוֹן יְהָבֵית אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,11,22,\"וּנְטָלוּ כְרוּבַיָא יַת גַפֵּיהוֹן וְגַלְגְלַיָא לְקִבְלֵיהוֹן וִיקָר אֱלָהָא דְיִשְׂרָאֵל עֲלֵיהוֹן מִלְעֵילָא:\",0,0],[4,144,11,23,\"וְאִסְתַּלֵק יְקָרָא דַייָ מִן גוֹ קַרְתָּא וּשְׁרָא עַל טוּר זֵיתָא דְמִמִדְנַח לְקַרְתָּא:\",0,0],[4,144,11,24,\"וְרוּחַ נְטַלְתַּנִי וְאֹבִילַתְנִי לִמְדִינַת אַרְעָא כַסְדָאֵי לְוַת בְּנֵי גָלוּתָא בְּחֶזְוָא בְּרוּחַ נְבוּאָה דִי שְׁרָת עֲלֵי מִן קֳדָם יְיָ וְאִסְתַּלֵק מִנִי חֲזְוָא דַחֲזֵיתִי:\",0,0],[4,144,11,25,\"וְאִתְנַבֵּיתִי לִבְנֵי גָלוּתָא יַת כָּל פִּתְגָמַיָא דַייָ דְאַחְזִינִי:\",0,0],[4,144,12,1,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,12,2,\"בַּר אָדָם בְּגוֹ עַמָא סַרְבָנָא אַתְּ יָתֵיב דִי עַיְנִין לְהוֹן לְמֶחֱזֵי וְלָא חָזָן וְאוּדְנִין לְהוֹן לְמִשְׁמַע וְלָא שָׁמְעִין אֲרֵי עַם סַרְבָן אִינוּן:\",0,0],[4,144,12,3,\"וְאַתְּ בַּר אָדָם אַתְקִין לָךְ מָנֵי גָלוּתָא וּגְלֵי בִימָם לְעֵינֵיהוֹן וְתִגְלֵי מֵאַתְרָךְ לַאֲתַר אוֹחֲרָן לְעֵינֵיהוֹן מָאִים יִדְחֲלוּן אֲרֵי עַם סַרְבָן אִינוּן:\",0,0],[4,144,12,4,\"וְתַפֵּיק מָנָךְ כְמָנֵי גָלוּתָא בִּימָם לְעֵינֵיהוֹן וְאַתְּ תִּפּוֹק בְּרַמְשָׁא לְעֵינֵיהוֹן כְּמַפְקָנֵי גָלוּתָא:\",0,0],[4,144,12,5,\"לְעֵינֵיהוֹן חֲתַּר לָךְ בְּכוּתְלָא וְתִפּוֹק בֵּיהּ:\",0,0],[4,144,12,6,\"לְעֵינֵיהוֹן עַל כַּתְפָא תִטוֹל בְּקִבְלָא תִפּוֹק אַפָּךְ תְּכַסֵי וְלָא תֶחֱזֵי יַת אַרְעָא אֲרֵי אָת יְהָבְתָּךְ לְבֵית יִשְׂרָאֵל:\",0,0],[4,144,12,7,\"וַעֲבָדִית כֵּן כְּמָא דְאִתְפַקֵדִית מָנֵי אַפְקֵית כְּמָנֵי גָלוּתָא בִּימָם וּבְרַמְשָׁא אִתְחַתְּרֵית לִי בְּכִתְלָא בְּיַד בְּקִבְלָא נַפְקֵית עַל כַּתְפָא נְטָלֵית לְעֵינֵיהוֹן:\",0,0],[4,144,12,8,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי בְצַפְרָא לְמֵימָר:\",0,0],[4,144,12,9,\"בַּר אָדָם הֲלָא אִם יֵימְרוּן לָךְ בֵּית יִשְׂרָאֵל עַמָא סַרְבָנָא מָא אַתְּ עָבֵיד:\",0,0],[4,144,12,10,\"אֱמַר לְהוֹן כִּדְנָן אֲמַר יְיָ אֱלֹהִים עַל רַבָּא מַטַל נְבוּאֲתָא הָדָא בִירוּשְׁלֵם וְכָל בֵּית יִשְׂרָאֵל דְאִינוּן בֵּינֵיהוֹן:\",0,0],[4,144,12,11,\"אֲמַר אֲנָא אָתְכוֹן כְּמָא דַעֲבָדֵית כֵּן יִתְעַבֵיד לְהוֹן בְּגָלוּתָא בְּשִׁבְיָא יְהָכוּן:\",0,0],[4,144,12,12,\"וְרַבָּא דְבֵינֵיהוֹן עַל כַּתְפָא יִטוֹל בְּקִבְלָא יִפּוֹק בְּכוּתְלָא יַחְתְּרוּן לְאַפָּקוּתֵיהּ בֵּיהּ אַפּוֹהִי יְכַסֵי חֲלַף דְחַב הוּא וְלָא יֶחֱזֵי יַת אַרְעָא:\",0,0],[4,144,12,13,\"וְאֶפְרוֹס יַת מְצֻדָתִי עֲלוֹהִי וְיִתְאֲחַד בִּסְרִגְתִי וְאַגְלֵי יָתֵיהּ לְבָבֶל לִמְדִינַת אַרְעָא כַסָדָאִי וְיָתָהּ לָא יֶחֱזֵי וְתַמָן יְמוּת:\",0,0],[4,144,12,14,\"וְכֹל דִי בְּסָחֳרָנוֹהִי סַעֲדוֹהִי וְכָל מַשִׁרְיָתֵיהּ אֲבַדֵר לְכָל רוּחָא וּדְקַטְלִין בְּחַרְבָּא אֲגָרֵי בַתְרֵיהוֹן:\",0,0],[4,144,12,15,\"וְיֵדְעוּן אֲרֵי אֲנָא יְיָ כַּד אַגְלֵי יַתְהוֹן לְבֵינֵי עַמְמַיָא וַאֲבַדֵר יַתְהוֹן בִּמְדִינָתָא:\",0,0],[4,144,12,16,\"וְאַשְׁאַר מִנְהוֹן גַבְרִין דְמִנְיַן מֵחַרְבָּא מִכַּפְנָא וּמִמוֹתָא בְּדִיל דְיִשְׁתָּעוּן יַת כָּל תּוֹעֲבָתְהוֹן בְּעַמְמַיָא דְאִתְגְלִיאוּ לְתַמָן וְיֵדְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,12,17,\"וַהֲוָה פִּתְגָם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,12,18,\"בַּר אָדָם מֵיכְלָךְ בְּזֵיעַ תֵּיכוֹל וּמִשְׁתָּךְ בְּצָדוּ וּבְאִשְׁתְּמָמוּ תִּשְׁתֵּי:\",0,0],[4,144,12,19,\"וְתֵימַר לְעַמָא דְאַרְעָא כִּדְנַן אֲמַר יְיָ אֱלֹהִים לְיַתְבֵי יְרוּשְׁלֵם עַל אַרְעָא דְיִשְׂרָאֵל מֵיכַלְהוֹן בְּזִיעַ יֵיכְלוּן וּמִשְׁתְּהוֹן בְּאִשְׁתְּמָמוּ יִשְׁתּוּן בְּדִיל דְתִצְדֵי אַרְעָא מִמְלוֹאָהּ מֵחֲטוֹף כָּל דְיַתְבִין בָּהּ:\",0,0],[4,144,12,20,\"וְקִרְוַיָא דַהֲוָאָה יָתְבָן יֶחֱרְבָן וְאַרְעָא לְצָדוּ תְהֵי וְתִידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,12,21,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,12,22,\"בַּר אָדָם מָא מַתְלָא הָדֵין לְכוֹן עַל אַרְעָא דְיִשְׂרָאֵל לְמֵימַר יוֹרְכוּן יוֹמַיָא וּתְבַטֵיל כָּל נְבוּאָה:\",0,0],[4,144,12,23,\"בְּכֵן אֲמַר לְהוֹן כִּדְנַן אֲמַר יְיָ אֱלֹהִים אֲבַטֵל יַת מַתְלָא הָדֵין וְלָא יִמְתְלוּן יָתֵיהּ עוֹד בְּיִשְׂרָאֵל אֱלָהֵין אִתְנַבֵּי לְהוֹן אִתְקְרָבוּ יוֹמַיָא וּפִתְגַם כָּל נְבוּאָה:\",0,0],[4,144,12,24,\"אֲרֵי לָא תְהֵי עוֹד כָּל נְבוּאָה שְׁקַר וּכְזַב כָּדְבִין בְּגוֹ בְנֵי יִשְׂרָאֵל:\",0,0],[4,144,12,25,\"אֲרֵי אֲנָא יְיָ אֲמַלֵיל יַת דַאֲמַלֵיל פִּתְגְמָא וְיִתְקַיֵם וְלָא יִבָּטֵיל עוֹד אֲרֵי בְיוֹמֵיכוֹן עַמָא סַרְבָנָא אֲמַלֵיל פִתְגָמָא וַאֲקֵימִינֵיהּ אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,12,26,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,12,27,\"בַּר אָדָם הָא בֵּית יִשְׂרָאֵל אָמְרִין אוּלְפַן דְהוּא מַלֵף לְיוֹמִין סַגִיאִין וּלְעִדַן רָחִיק הוּא מִתְנַבֵּי:\",0,0],[4,144,12,28,\"בְּכֵן אֲמַר לְהוֹן כִּדְנַן אֲמַר יְיָ אֱלֹהִים לָא יִבָּטֵל עוֹד כָּל פִּתְגָמֵי דַאֲמַלֵיל פִּתְגָמָא וְיִתְקַיֵם אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,13,1,\"וַהֲוָה פִּתְגָם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,13,2,\"בַּר אָדָם אִתְנַבֵּי עַל נְבִיֵי שִׁקְרָא דְמִתְנַבֵּן וְתֵימַר לִדְמִתְנַבֵּן בִּרְעוּת לִבְּהוֹן קַבִּילוּ פִתְגָמָא דַיָי:\",0,0],[4,144,13,3,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים וַי עַל נְבִיֵי שִׁקְרָא דְמִשְׁתַּטָן דְאָזְלִין בָּתַר הִרְהוּר לִבְּהוֹן וּמִדַעַם לָא חָזָן:\",0,0],[4,144,13,4,\"כִּתְעָלִין בְּחָרְבָתָא נְבִיֵי שִׁקְרָךְ יִשְׂרָאֵל הֲווֹ:\",0,0],[4,144,13,5,\"לָא קַמְתּוּן בְּתַרְעֲתָא וְלָא עֲבַדְתּוּן לְכוֹן עוֹבָדִין טָבִין לְמִבְעֵי עַל בֵּית יִשְׂרָאֵל לְמֵיקָם לְמִבְעֵי עֲלֵיהוֹן רַחֲמִין בְּעִדַן דַאֲתוֹ עֲלֵיהוֹן עָבְדֵי קְרָבָא בְּיוֹם רוּגְזָא דַיָי:\",0,0],[4,144,13,6,\"מִתְנַבָּן שְׁקַר וּמַלְפַן כַּדְבִין אָמְרִין אֲמַר יְיָ וַיָי לָא שַׁלְחִינוּן וּמַחְצְפִין דְתִתְקַייָם מִלַתְהוֹן:\",0,0],[4,144,13,7,\"הֲלָא נְבוּאָן דִשְׁקַר אִתְנַבֵּיתוּן וּקְסַם כַּדְבִין אֲמַרְתּוּן וְאָמְרִין אֲמַר יְיָ וּמִן קֳדָם יְיָ לָא אִתְמַלָל:\",0,0],[4,144,13,8,\"בְּכֵן כִּדְנַן יְיָ אֱלֹהִים חֲלַף דְאִתְנַבֵּיתוּן שְׁקַר וַאֲלַפְתּוּן כַּדְבִין בְּכֵן הָא אֲנָא שְׁלַח רוּגְזִי עֲלֵיכוֹן אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,13,9,\"וּתְהֵי מְחַת גְבוּרְתִּי עַל נְבִיֵי שִׁקְרָא דְמִתְנַבֵּן שְׁקַר וּמַלְפִין כַּדִיבִין בְּרַז טַב דְגָנִיז לְעַמִי לָא יְהוֹן וּבִכְתַב חַיֵי עַלְמָא דִכְתִיב לְצַדִיקֵי בֵּית יִשְׂרָאֵל לָא יִתְכַּתְבוּן וּלְאַרְעָא דְיִשְׂרָאֵל לָא יַעֲלוּן וְתִידְעוּן אֲרֵי אֲנָא יְיָ אֱלֹהִים:\",0,0],[4,144,13,10,\"חֲלַף דְאִתְנַבִּיאוּ שְׁקַר וַחֲלַף דְאַטְעִיאוּ יַת עַמִי לְמֵימָר שְׁלָמָא וְלֵית שְׁלָם וְאִינוּן דָמָן לִדְבָנֵי מְחִיצָא וְשָׁעֵיָע לֵיהּ טִין פַּטִיר דְלָא תֲבָן:\",0,0],[4,144,13,11,\"אֱמַר לִדְבָנֵי מְחִיצָא וְשָׁעֵיָא לֵיהּ טִין פַּטִיר דְלָא תֶבֶן נָפִיל הוּא כְּעַן יְהֵי מְטַר מַגְבַּר וְיַת אַבְנֵי אֶלְגָבִישׁ יַחְתָן וְרוּחַ עַלְעוֹלִין תְּבַזַע:\",0,0],[4,144,13,12,\"וְהָא נְפַל כָּתְלָא הֲלָא יִתְאֲמַר לְכוֹן אָן שִׁיעָא דְשַׁעְתּוּן:\",0,0],[4,144,13,13,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים וְאַיְתֵי מְלַךְ דְתַקִיף בְּרוּחַ עַלְעוֹלִין בַּחֲמָתִי וְעַמְמִין קְטוֹלִין כִמְטַר מַגְבַּר בְּרוּגְזִי יֵיתוּן וּמַלְכְּוָן דַחֲסִינִין כְּאַבְנֵי אֶלְגָבִישׁ בִּרְגַז לְשֵׁיצָאָה:\",0,0],[4,144,13,14,\"וְאַפְגַר יַת קַרְתָּא דְאִתְנַבֵּיתוּן בָּהּ נְבוּאַן דִשְׁקַר וְאֶרְמִינָהּ לְאַרְעָא וְיִתְגְלוּן אוּשָׁהָא וְתַפֵּל וְתִשְׁתֵּיצוּן בְּגַוָהּ וְתֵידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,13,15,\"וְיָחוּל רוּגְזִי בְּקַרְתָּא וּבִנְבִיֵי שִׁקְרָא דְאִתְנַבִּיאוּ בָּהּ נְבוּאַן דִשְׁקַר וְיִתְאַמַר לְכוֹן לֵית קַרְתָּא וְלֵית נְבִיֵי שִׁקְרָא:\",0,0],[4,144,13,16,\"נְבִיֵי שִׁקְרָא דְיִשְׂרָאֵל דְמִתְנַבֵּין עַל יְרוּשְׁלֵם וּמַטְעִין לָהּ בְּאוּלְפַן שְׁלָם וְלֵית שְׁלָם אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,13,17,\"וְאַתְּ בַּר אָדָם קַבֵּיל נְבוּאָה עַל בְּנַת עַמָךְ דְמִתְנַבָּן כִּרְעוּת לִבְּהוֹן וְאִתְנַבֵּי עֲלֵיהֶן:\",0,0],[4,144,13,18,\"וְתֵימַר כִּדְנַן יְיָ אֱלֹהִים וַי עֲלֵיהוֹן עַל דִמְחַטְטָן רְקִיעֵי חֲשׁוֹךְ עַל כָּל מַרְפְּקִי יָדִין וְעָבְדִן פַּת כּוּמָרִין עַל רֵישׁ כָּל קוֹמָה לְאַבָּדָא נַפְשָׁן הַנְפָשׁוֹת עַמִי אַתֵּן יָכְלָן לְאַבָּדָא וּלְקַיָמָא הֲלָא נַפְשָׁתְכֵן דִילְכֵן הֲלָא יְכַלְתֵּין לְקַיָמָא:\",0,0],[4,144,13,19,\"וְאָחַלְתֵּין רְעוּתִי בְּעַמִי בְּשַׁעֲלֵי סְעָרִן וּבִמְנוּסִין דִלְחֵים לַאֲמָתָא נַפְשָׁן דְלָא חֲזֵי לְהֵין דִימוּתוּן לָא אַתֵּן מְמִיתָן וּלְקַיָמָא נַפְשָׁן דְלָא חֲזֵי לְהֵין לְקַיָמָא דְתִתְקַיְמָן לָא אַתֵּין מְקַיְמָן בְּכַדָבוּתְכֵין לְעַמִי שָׁמְעֵי כַדְבִין:\",0,0],[4,144,13,20,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא שְׁלַח רוּגְזִי עַל רְקִיעַי חֲשִׁיכִין דְאַתִּין מַטְעֲיָן לְמֵימַר בְּהוֹן אֲנַחְנָא מְחַרְשָׁן יַת נַפְשָׁן לְאַבָּדָא וְאַפְסֵיק יַתְהֵין מֵעָל דַרְעֵיכוֹן וַאֲשֵׁיזֵיב יַת נַפְשָׁתָא דְאַתּוּן מְחַרְשָׁן יַת נַפְשֵׁיהֵן לְאַבָּדוּתָהָא:\",0,0],[4,144,13,21,\"וְאַפְסֵיק יַת פַּת כּוּמָרֵיכוֹן וַאֲשֵׁיזֵיב יַת עַמִי מִיֶדְכוֹן וְלָא יִתְמַסְרוּן עוֹד בְּיֶדְכוֹן לְאִשְׁתֵּיצָאָה וְתִידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,13,22,\"חֲלַף דְאַכְהֵיתֵן לֵב זַכַּאי לִמֶהֱוֵי שְׁקַר וּמִן קֳדָם מֵימְרִי לָא אִתְבְּהִי וּלְתַקָפָא יְדֵי רַשִׁיעָא בְּדִיל דְלָא לְמֵיתָב מֵאוֹרְחֵיהּ בִּישְׁתָא לְקַיָמוּתֵיהּ:\",0,0],[4,144,13,23,\"בְּכֵן שְׁקַר לָא תִתְנַבְּאוּן וְאוּלְפַן לָא תֵילְפוּן עוֹד וַאֲשֵׁיזִיב יַת עַמִי מִיֶדְכוֹן וְתִידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,14,1,\"אֲמַר נְבִיָא אֲתוֹ לְוָתִי גַבְרִין מִסָבֵי יִשְׂרָאֵל וִיתִיבוּ קֳדָמַי:\",0,0],[4,144,14,2,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,14,3,\"בַּר אָדָם גַבְרַיָא הָאִלֵין אַסִיקוּ פּוּלְחַן טַעֲוַתְהוֹן עַל לִבְּהוֹן וְתַקְלַת חוֹבֵיהוֹן יְהָבוּ לָקֳבֵיל אַפֵּיהוֹן הֲאִשְׁתְּאִילָא יִשְׁתְּאַל בְּמֵימְרִי לְהוֹן:\",0,0],[4,144,14,4,\"בְּכֵן אִתְנַבֵּי לְהוֹן וְתֵימַר לְהוֹן כִּדְנַן אֲמַר יְיָ אֱלֹהִים גְבַר גְבַר מִבֵּית יִשְׂרָאֵל דִי יַסֵיק פּוּלְחַן טַעֲוְתֵיהּ עַל לִבֵּיהּ וְתַקְלַת חוֹבֵיהּ יְשַׁוֵי לָקֳבֵיל אַפּוֹהִי וְיֵיתֵי לְוַת נְבִיָא אֲנָא יְיָ מִשְׁתְּאֵיל לֵיהּ בְּמֵימְרִי דְאָתֵי לְמִתְבַּע אוּלְפַן מַן קֳדָמַי אַף עַל גַב דְמִתְעָרֵב בִּסְגִי פּוּלְחַן טַעֲוָתֵיהּ:\",0,0],[4,144,14,5,\"בְּדִיל לְקָרָבָא יַת בֵּית יִשְׂרָאֵל לְמִתַּן תִּיוּבְתָּא בְּלִבְּהוֹן דִסְטוֹ מִבָּתַר פּוּלְחָנִי וְאִסְתָּאָבוּ בְּפוּלְחַן טַעֲוָתְהוֹן כּוּלְהוֹן:\",0,0],[4,144,14,6,\"בְּכֵן אֲמַר לְבֵית יִשְׂרָאֵל כִּדְנַן אֲמַר יְיָ אֱלֹהִים תוּבוּ לְפוּלְחָנִי וְאַעְדוּ מִנְכוֹן פּוּלְחַן טַעֲוָתְכוֹן וְיַת כָּל חוֹבֵי פּוּלְחַן טַעֲוַת תּוֹעֲבַתְכוֹן אַרְחִיקוּ מִקְבֵיל אַפֵּיכוֹן:\",0,0],[4,144,14,7,\"אֲרֵי גְבַר גְבַר מִבֵית יִשְׂרָאֵל וּמִן גִיוֹרַיָא דְיִתְגַיְרוּן בְּיִשְׂרָאֵל וְיִסְטֵי מִבָּתַר פּוּלְחָנִי וְיַסֵיק פּוּלְחַן טַעֲוָתֵהּ עַל לִבֵּיהּ וְתַקְלַת חוֹבוֹהִי יְשַׁוֵי לָקֳבֵיל אֲפּוֹהִי וְיֵיתֵי לְוַת נְבִיָא לְמִשְׁאַל לֵיהּ בְּמֵימְרִי אֲנָא יְיָ מִשְׁתְּאֵיל לֵיהּ בְּמֵימְרִי:\",0,0],[4,144,14,8,\"וְאֶתֵּן רוּגְזִי בְּגַבְרָא הַהוּא וַאֲשַׁוִינֵיהּ לְאָת וּלְמַתְלִין וֶאֱשֵׁיצִינֵיהּ מִגוֹ עַמִי וְתִידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,14,9,\"וּנְבִיָא אֲרֵי יִטְעֵי וִימַלֵיל פִּתְגָמָא אֲנָא יְיָ אַטְעֵיתִי יַת נְבִיָא הַהוּא וַאֲרֵים יַת מְחַת גְבוּרְתִּי עֲלוֹהִי וֶאֱשֵׁיצִינֵיהּ מִגוֹ עַמִי יִשְׂרָאֵל:\",0,0],[4,144,14,10,\"וִיקַבְּלוּן חוֹבֵיהוֹן כְּחוֹב דְאָתֵי לְמֵילַף וְלָא אַלֵיף כְּחוֹב נְבִיֵי שִׁקְרָא יְהֵי:\",0,0],[4,144,14,11,\"בְּדִיל דְלָא יִטְעוּן עוֹד בֵּית יִשְׂרָאֵל מִבָּתַר פּוּלְחָנִי וְלָא יִסְתַּאֲבוּן עוֹד בְּכָל מֵירְדֵיהוֹן וִיהוֹן קֳדָמַי לְעַם וַאֲנָא אֶהֱוֵי לְהוֹן לֵאלָהָא אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,14,12,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,14,13,\"בַּר אָדָם אַרְעָא אֲרֵי תֵיחוֹב קֳדָמַי לְשַׁקָרָא שְׁקַר וַאֲרֵים מְחַת גְבוּרְתִּי עֲלָהּ וְאֶתְבַּר בָּהּ סְעֵיד מֵיכְלָא וְאֶשְׁלַח בָּהּ כַּפְנָא וֶאֱשֵׁיצֵי מִנָהּ אֱנָשָׁא וּבְעִירָא:\",0,0],[4,144,14,14,\"וִיהוֹן תְּלָתָא גַבְרַיָא הָאִלֵין בְּגַוָהּ נֹחַ דָנִיאֵל וְאִיוֹב אִינוּן בִּזְכוּתְהוֹן יְשֵׁיזְבוּן נַפְשְׁהוֹן אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,14,15,\"אִילוּ חַיְתָא בִישְׁתָא אַעְבֵּיד בְּאַרְעָא וְתִתְכְּלִינָהּ וּתְהֵי לְצָדוּ מִבְּלִי עָדֵי מִן קֳדָם חַיְתָא:\",0,0],[4,144,14,16,\"תְּלָתָא גַבְרַיָא הָאִילֵן בְּגַוָהּ קַיָם אֲנָא אֲמַר יְיָ אֱלֹהִים אִם בְּנִין וְאִם בְּנָן יְשֵׁיזְבוּן יִשְׁתֵּיזְבוּן וְאַרְעָא תְּהֵי לְצָדוּ:\",0,0],[4,144,14,17,\"אוֹ דְקַטְלִין בְּחַרְבָּא אַיְיתֵי עַל אַרְעָא הַהִיא וְאֵימַר דְקַטְלִין בְּחַרְבָּא יֶעְדוּן בְּאַרְעָא וֶאֱשֵׁיצֵי מִנָהּ אֱנָשָׁא וּבְעִירָא:\",0,0],[4,144,14,18,\"וּתְלָתָא גַבְרַיָא הָאִילֵן בְּגַוָהּ קַיָם אֲנָא אֲמַר יְיָ אֱלֹהִים לָא יְשֵׁיזְבוּן בְּנִין וּבְנָן אֱלָהֵין אִינוּן בִּלְחוֹדֵיהוֹן יִשְׁתֵּיזְבוּן:\",0,0],[4,144,14,19,\"אוֹ מוֹתָא אֲשַׁלַח עַל אַרְעָא הַהִיא וְאֶשְׁפּוֹךְ חֵימְתִי עֲלָה בִּקְטוֹל לְשֵׁיצָאָה מִנָהּ אֱנָשָׁא וּבְעִירָא:\",0,0],[4,144,14,20,\"וְנֹחַ דָנִיאֵל וְאִיוֹב בְּגַוָהּ וְקַיָם אֲנָא אֲמַר יְיָ אֱלֹהִים אִם בַּר אִם בְּרַתָּא יְשֵׁיזְבוּן אִינוּן בִּזְכוּתְהוֹן יְשֵׁיזְבוּן נַפְשְׁהוֹן:\",0,0],[4,144,14,21,\"אֲרֵי כִּדְנַן אֲמַר יְיָ אֱלֹהִים אַף אֲרֵי אַרְבַּע פּוּרְעָנִין בִּישָׁן חַרְבָּא וְכַפְנָא וְחַיְתָא בִּישְׁתָא וּמוֹתָא שְׁלָחֵית עַל יְרוּשְׁלֵם לְשֵׁיצָאָה מִנָה אֱנָשָׁא וּבְעִירָא:\",0,0],[4,144,14,22,\"וְהָא אִשְׁתָּאֲרַת בָּהּ שֵׁיזֵיבְתָּא דְמִתַּפְקִין בְּנִין וּבְנָן אִינוּן נַפְקִין לְוַתְכוֹן וְתֶחֱזוּן יַת אוֹרְחֵיהוֹן וְיַת עוֹבָדֵיהוֹן וְתִתְנַחֲמוּן עַל בִּישְׁתָא דְאַיְתֵיתִי עַל יְרוּשְׁלֵם יַת כָּל דְאַיְתֵיתִי עֲלָהּ:\",0,0],[4,144,14,23,\"וִינַחֲמוּן יַתְכוֹן אֲרֵי תֶחֱזוּן יַת אוֹרְחֵיהוֹן וְיַת עוֹבְדֵיהוֹן וְתֵידְעוּן אֲרֵי לָא לְמַגֵן עֲבָדֵית יַת כָּל דַעֲבַדֵית בָּהּ אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,15,1,\"וַהֲוָה פִּתְגָם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,15,2,\"בַּר אָדָם מַה שְׁנָא אִילַן גוּפְנָא מִכָּל אִילָנָא שַׁבֶּשְׁתָּא דַהֲוַת בְּאָעֵי חוּרְשָׁא:\",0,0],[4,144,15,3,\"הֲיִסְבוּן מִנֵיהּ אָעָא לְמֶעְבַּד עֲבִידָא אִם יִסְבוּן מִנֵיהּ סִיכָתָא לְמִתְלֵי בָּהּ כָּל מָאן:\",0,0],[4,144,15,4,\"הָא לְאֶשְׁתָּא אִתְמְסַר לְאִשְׁתֵּיצָאָה יַת תְּרֵין סִטְרוֹהִי אָכְלָא אַשִׁתָּא וְגַוֵיהּ חַר הַיִכְשַׁר לַעֲבִידָא:\",0,0],[4,144,15,5,\"הָא כַּד הֲוָה שְׁלִים לָא כְשַׁר לַעֲבִידָא אַף אֱלָהֵין דְאֶשְׁתָּא אֲכַלְתֵּיהּ וְחַד הֲיִכְשַׁר עוֹד לַעֲבִידָא:\",0,0],[4,144,15,6,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים כְּמָא דְאִילָן גוּפְנָא בַּאֲעֵי חוּרְשָׁא דִמְסַרְתֵּיהּ לְאֶשְׁתָּא לְאִשְׁתֵּיצָאָהּ כֵּן מְסָרֵית יַת יַתְבֵי יְרוּשְׁלֵם:\",0,0],[4,144,15,7,\"וְאֶתֵּן יַת פּוּרְעֲנוּתִי בְּהוֹן עַל פִּתְגָמַי אוֹרַיְתָא דִיהִיבִין מִגוֹ אֶשְׁתָּא עֲבַרוּ וְעַמְמַיָא דִתְקִיפִין כְּאֶשְׁתָּא יְשֵׁיצִינוּן וְתִידְעוּן אֲרֵי אֲנָא יְיָ כַּד יָחוּל רוּגְזִי בְּהוֹן:\",0,0],[4,144,15,8,\"וְאֶתֵּן יַת אַרְעָא לְצָדוּ חֲלַף דִשְׁקָרוּ שְׁקַר אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,16,1,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,16,2,\"בַּר אָדָם חוֹכַת יַת יַתְבֵי יְרוּשְׁלֵם וְחַוֵי לְהוֹן יַת תּוֹעֲבָתְהוֹן:\",0,0],[4,144,16,3,\"וְתֵימַר כִּדְנַן אֲמַר יְיָ אֱלֹהִים לְיָתְבֵי יְרוּשְׁלֵם תּוֹתְבַתְכוֹן וְיַלְדוּתְכוֹן מֵאַרְעָא כְּנַעֲנָאֵי תַּמָן אִתְגְלֵיתִי עַל אַבְרָהָם אֲבוּכוֹן בֵּין בִּתְרַיָא וְאוֹדַעְתֵּיהּ דְאַתּוּן נַחֲתִין לְמִצְרַיִם בִּדְרַע מְרוֹמָם אֲנָא פָּרֵק יַתְכוֹן וּבִזְכוּת אֲבָהָתְכוֹן אֲנָא מְתָרֵיךְ מִן קֳדָמֵיכוֹן יַת אֱמוֹרָאֵי וּמְשֵׁיצַי יַת חִתָּאֵי:\",0,0],[4,144,16,4,\"וְאַף כַּד נְחָתוּ אֲבָהַתְכוֹן לְמִצְרַיִם תּוֹתָבִין בְּאַרְעָא דְלָא דִילְהוֹן מְשַׁעְבְּדִין וּמְעַנַן לְהוֹן הֲוַת כְּנִשְׁתָּא דְיִשְׂרָאֵל דַמְיָא לְוַלְדָא דִי רְטִישׁ עַל אַפֵּי בָרָא דְלָא אִתְפְּסַק שׁוֹרֵיהּ וּבְמַיָא לָא אִשְׁתְּטִיף לְאִתְנַקָאָה וּבִמְלַח לָא אִתְמְלַח וּבְאִיסוּרִין לָא אִתְאֲסָר:\",0,0],[4,144,16,5,\"לָא חָסַת עֲלֵיכוֹן עֵינָא דְפַרְעֹה לְמֶעֱבַד לְכוֹן טָבָא חֲדָא לְרָחָמָא עֲלֵיכוֹן וּגְזַר עֲלֵיכוֹן גְזֵרַת גְמִירָא לְמִרְמֵי דְכוּרֵיכוֹן בְּנַהֲרָא לְאַבָּדָא יַתְכוֹן בְּעִדַן דַהֲוֵיתוּן בְּמִצְרַיִם:\",0,0],[4,144,16,6,\"וְעַל דָכְרָן קְיָם אֲבָהַתְכוֹן קֳדָמֵי אִתְגְלֵיתִי לְמִפְרַקְכוֹן אֲרֵי גְלֵי קֳדָמֵי אֲרֵי אַתּוּן מְעַנַן בְּשִׁעְבּוּדְכוֹן וַאֲמָרִית לְכוֹן בִּדְמָא דְמָהוּלִתָּא אָחוֹס עֲלֵיכוֹן וַאֲמַרֵית לְכוֹן בְּדַם פִּסְחָא אֶפְרוֹק יַתְכוֹן:\",0,0],[4,144,16,7,\"רִבְבַת כְּצִימְחֵי חַקְלָא יְהַבְתִּיכוֹן וּסְגֵיתוּן וּתְקֵיפְתּוּן וַהֲוֵיתוּן לְזַרְעִין וּלְשִׁבְטִין וּכְעוֹבָדֵי אֲבָהַתְכוֹן תַּקָנַיָא עִידַן פּוּרְקַן כְּנִישַׁתְכוֹן מְטָא אֲרֵי אַתּוּן מְשַׁעְבְּדִין וּמְעַנָן:\",0,0],[4,144,16,8,\"וְאִתְגְלֵיתִי עַל מֹשֶׁה בְּאַסְנָא אֲרֵי גְלֵי קֳדָמָי אֲרֵי מְטָא זְמַן פּוּרְקָנֵיכוֹן וְאַגְנֵית בְּמֵימְרִי עֲלֵיכוֹן וְאַעֲדֵיתִי חוֹבֵיכוֹן וְקַיֵמִית בְּמֵימְרִי לְמִפְרַק יַתְכוֹן כְּמָא דְקַיֵמֵית לַאֲבָהָתְכוֹן אֲמַר יְיָ אֱלֹהִים לְמֶהֱוֵיכוֹן עַם מְשַׁמֵשׁ קֳדָמַי:\",0,0],[4,144,16,9,\"וּפָרִיקִית יַתְכוֹן מִשִׁעְבּוּד מִצְרָאֵי וְאַעְדֵיתִי תְּקוֹף מַרְוָתָא מִנְכוֹן וְדַבְּרֵית יַתְכוֹן בְּחֵירוּתָא:\",0,0],[4,144,16,10,\"וְאַלְבִּישֵׁית יַתְכוֹן לְבוּשֵׁי צִיוּרִין מֵחָמְדַת סָנְאֵיכוֹן וִיהָבֵית מְסַן דִיקַר בְּרַגְלֵיכוֹן וְקַדְשֵׁית מִנְכוֹן כַּהֲנַיָא לְמֶהֱוֵי מְשַׁמְשִׁין קֳדָמַי בְּמִצְנְפָן דְבוּץ וְיַת כַּהֲנָא רַבָּא בִּלְבוּשֵׁי צִבְעוֹנִין:\",0,0],[4,144,16,11,\"וְתַקְנֵית יַתְכוֹן תִּקוּן פִּתְגָמֵי אוֹרַיְתָא כְּתִיבִין עַל תְּרֵין לוּחֵי אַבְנַיָא וִיהִיבִין עַל יְדֵי מֹשֶׁה וּבִקְדוּשַׁת שְׁמִי רַבָּא קַדִישֵׁית יַתְכוֹן:\",0,0],[4,144,16,12,\"וִיהָבֵית אֲרוֹן קְיָמִי בֵּינֵיכוֹן וַעֲנַן יְקָרִי מַטַל עֲלַוֵיכוֹן וּמַלְאַךְ שְׁלִיחַ מִן קֳדָמַי מְדַבֵּר בְּרֵישֵׁיכוֹן:\",0,0],[4,144,16,13,\"וִיהָבֵית מַשְׁכְּנִי בֵּינֵיכוֹן מְתַקֵן בִּדְהַב וּכְסַף וִירִיעַת בּוּץ וְצִבְעוֹנִין וְצִיוּרִין וּמַנָא דְטַב כְּסוּלְתָא וְכִדְבַשׁ וְכִמְשַׁח אוֹכְלֵית יַתְכוֹן וַעֲתַרְתּוּן וּתְקֵיפְתּוּן לַחֲדָא וְאִצְלַחְתּוּן וּשְׁלֵיטְתּוּן בְּכָל מַלְכְּוָתָא:\",0,0],[4,144,16,14,\"וּנְפַק לָךְ שׁוּם כְּנִשְׁתָּא דְיִשְׂרָאֵל בֵּינֵי עַמְמַיָא בְּשׁוּפְרַיִךְ אֲרֵי גְמִיר הוּא יְקָרִי דְשַׁוֵיתִי עָלַיִךְ אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,16,15,\"וְאִתְרְחֵיצְתְּ בְּשׁוּפְרֵיךְ וּטְעֵית עַל שְׁמִיךְ וְאִתְחַבַּרְתְּ לִיךְ לְמִפְלַח לְטַעֲוָתָא עִם כָּל דְעָדֵי וְלָא כְשַׁר לִיךְ לְמֶעְבַּד כֵּן:\",0,0],[4,144,16,16,\"וּנְסֵיבְתְּ מַלְבּוּשַׁיִךְ וַעֲבִידְתְּ לִיךְ בָּמָן מְחַפְיָן פַּת כּוֹמְרִין וּטְעֵית עֲלֵיהוֹן לָא כִּדְכָשַׁר וְלָא כִדְחֲזֵי:\",0,0],[4,144,16,17,\"וּנְסֵיבְתְּ מָנַי תוּשְׁבַּחְתִּיךְ מִדַהֲבֵי וּמִכַּסְפִּי דִי יְהָבֵית לִיךְ וַעֲבֵידְתְּ לִיךְ צַלְמֵי דְכוּרָא וּטְעֵית בְּהוֹן:\",0,0],[4,144,16,18,\"וּנְסֵיבְתְּ יַת לְבוּשֵׁי צִיוּרַיִךְ וּכִסִיתִינוּן וּמִשְׁחִי וּקְטוֹרֶת בּוּסְמֵי שַׁוִית קֳדָמֵיהוֹן:\",0,0],[4,144,16,19,\"וְטוּבִי דִיהָבִית לִיךְ סוּלְתָּא וּמְשַׁח וּדְבַשׁ אוֹכֵילְתִּיךְ יְהַבְתִּינוּן קֳדָמֵיהוֹן קוּרְבָּנִין לְפוּלְחַן הֲלָא הֲוָאָה כָּל אִלֵין אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,16,20,\"אֵיכָא אַסְגֵית לְאַרְגָזָא קֳדָמַי כְּנִשְׁתָּא דְיִשְׂרָאֵל דִי דַבַּרְתְּ יַת בְּנַךְ וְיַת בְּנָתָךְ דַעֲתִידִין לְמִפַּק מִנְהוֹן תּוּלְדַת קוּדְשָׁא קָדָמַי וּנְכֵיסְתִּינוּן לְהֵין קוּרְבָּנִין לְפוּלְחַן הַזְעֵירָא הֲוַת בְּעֵינָךְ טַעֲוָתִיךְ:\",0,0],[4,144,16,21,\"וּנְכֵיסְתְּ יַת בְּנַיָא וִיהַבְתִּינוּן בְּאַעֲבָרָא יַתְהוֹן לְהֵין:\",0,0],[4,144,16,22,\"וְיַת כָּל חוֹבֵי תוֹעֲבוֹתַיִךְ וְטַעֲוָתַיִךְ לָא אִדְכַּרְתְּ יַת יוֹמִין דְמִלְקַדְמִין כַּד הֲוִית מְטַלְטָלָא וּשְׁבִיקָא מִתְעַנְיָא בְּשִׁעְבּוּדַיִךְ הֲוֵית:\",0,0],[4,144,16,23,\"מַה יְהֵי בְסוֹפַיִךְ עַל כָּל בִּישְׁתִּיךְ נְבִיָא אֲמַר יַהּ וַי לִיךְ עַל דְחַבְתְּ וַי לִיךְ עַל דְלָא תַבְתְּ אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,16,24,\"וּבְנֵית לִיךְ אֱגוֹרִין וַעֵבַדְתְּ לִיךְ רָמָן בְּכָל רְחוֹב:\",0,0],[4,144,16,25,\"בְּרֵישׁ כָּל פָּרָשׁוּת אוֹרַח בְּנִית רָמָתַיִךְ וְאָחֵילְתְּ יַת קְדוּשְׁתִּיךְ וְאִיתְחַבַּרְתְּ לִיךְ לְמִפְלַח לְטַעֲוָתָיִךְ עִם כָּל דְעָדֵי וְאַסְגֵית יַת טַעֲוָתָיִךְ:\",0,0],[4,144,16,26,\"וּטְעֵית בָּתַר בְּנֵי מִצְרַיִם קְרִיבַיִךְ מְסַרְבְּלֵי בְּסַר וְאַסְגֵית יַת טַעֲוָתַיִךְ לְאַרְגָזָא קֳדָמַי:\",0,0],[4,144,16,27,\"וְהָא אֲרֵימִית יַת מְחַת גְבוּרְתִּי עֲלָךְ וּמְנָעֵית טוּבִיךְ וְאֶמְסְרִינִיךְ בְּיַד בַּעֲלֵי דְבָבִיךְ כַּפְרָנֵי פְּלִשְׁתָּאֵי דְאִלוּ שַׁלְחֵית לְוַתְהוֹן נְבִיַי אִתְכְּנָעוּ וְאַתְּ לָא תַּבְתְּ מֵאוֹרְחִיךְ דְעֵיצַת חֶטְאִין:\",0,0],[4,144,16,28,\"וּטְעֵית בָּתַר בְּנֵי אַתּוּר מִדְלָא יְדַעַתְּ אוֹרַיְתָא וּטְעֵית בְּהוֹן וְאַף לָא יְדַעַתְּ תְּיוּבְתָּא:\",0,0],[4,144,16,29,\"וְאַסְגֵית יַת טַעֲוָתַיִךְ לְאִתְחַבָּרָא לְעַמָא דִכְנַעַן לִמְהַךְ בְּנִימוּסֵי כַּסְדָאֵי וְאַף בְּדָא לָא יְדַעַתְּ אוֹרַיְתָא:\",0,0],[4,144,16,30,\"מָה תַקִיף הֲוָה רֶשַׁע לִבֵּךְ אֲמַר יְיָ אֱלֹהִים בְּמֶעְבְּדִיךְ יַת כָּל אִילֵן בְּעוֹבָדֵי אִיתְּתָא נַפְקַת בְּרָא דְשַׁלִיט לָהּ בְּנַפְשָׁהּ:\",0,0],[4,144,16,31,\"בְמִבְנָךְ אֱגוֹרָךְ בְּרֵישׁ כָּל פָּרָשׁוּת אוֹרַח וְרָמָתֵךְ עֲבַדְתְּ בְּכָל רְחוֹב וְלָא הֲוֵית כְּנַפְקַת בָּרָא דְמִתְהַנְיָא בְּאַגְרָא:\",0,0],[4,144,16,32,\"כְּנִשְׁתָא דְיִשְׂרָאֵל דַמְיָא לְאִתְּתָא דִרְחִימָא עַל בַּעְלָהּ וּמְזַנְיָא עֲלוֹהִי שָׁבְקַת יַת בַּעְלָהּ וּטְעַת בָּתַר נוּכְרָאִין:\",0,0],[4,144,16,33,\"לְכָל נַפְקַת בָּרָא יֶהֱבִין אֲגַר וְאַתְּ אַהֲנִית יַת אַגְרִיךְ לְכָל רְחִימָךְ וּשְׁחֵידְתְּ יַתְהוֹן לְמֵיתֵי עֲלָךְ מִסְחוֹר סְחוֹר בְּטַעֲוָתַיִךְ:\",0,0],[4,144,16,34,\"וַהֲוָה בִּיךְ שְׁנוּ כְנִשְׁתָּא דְיִשְׂרָאֵל מִן מְדִינָתָא בְּטַעֲוָתַיִךְ וּבַתְרִיךְ לָא הֲוַת דְטָעִית כְּוָתִיךְ וּבְמִתְּנִיךְ אֲגַר וְאֲגַר לָא אִתְיְהַב לִיךְ וַהֲוֵית לִשְׁנוּ:\",0,0],[4,144,16,35,\"בְּכֵן דְעוֹבְדָהָא כְּנַפְקַת בָּרָא כְּנִשְׁתָּא דְיִשְׂרָאֵל קַבִּילוּ פִּתְגָמָא דַיָי:\",0,0],[4,144,16,36,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים חֲלַף דְאַגְלִיאַת בַּהֲתָתֵיךְ וְאִיתְחֲזִית קָלוֹנִיךְ בִּדְטָעִית בָּתַר רְחִימַיִךְ וְיַת כָּל חוֹבֵי פּוּלְחַן טַעֲוַת תּוֹעֲבָתַיִךְ וּבְחוֹבַת דַם בְּנֵךְ דִנְכֵיסְתְּ לְהֵין:\",0,0],[4,144,16,37,\"בְּכֵן הָא אֲנָא מַכְנִישׁ יַת כָּל רְחִימֵיךְ דְאִתְרְעֵית לְמִטְעֵי בַתְרֵיהוֹן וְיַת כָּל דִרְחֵימְתְּ עִם כָּל דִשְׂנֵית וְאַכְנֵישׁ יַתְהוֹן עֲלָךְ מִסְחוֹר סְחוֹר וַאֲגַלֵי בַּהֲתָתַיִךְ לְהוֹן וְיֶחֱזוּן יַת כָּל קְלוֹנָיִךְ:\",0,0],[4,144,16,38,\"וְאִתְפְּרַע מִנִיךְ פּוּרְעֲנּוּת גָיְפָן וְאַשְׁדִת דַם וְאֶמְסְרִינָךְ לִקְטוֹל בִּרְגַז וּבְחֵימָה:\",0,0],[4,144,16,39,\"וְאֶמְסַר יָתִיךְ בִּידֵיהוֹן וִיפַגְרוּן שׁוּרֵיךְ וְיִתַרְעוּן רָמָתַיִךְ וְיִשְׁלְחוּן יָתִיךְ לְבוּשֵׁי יְקָרִיךְ וְיִסְבּוּן מָנַי תוּשְׁבַּחְתִּיךְ וְיִשְׁבְקוּנִיךְ מְטַלְטָלָא וּשְׁבִיקָא:\",0,0],[4,144,16,40,\"וְיִסְקוּן עֲלָךְ מַשִׁרְיָן וְיִרְגְמוּן יָתִיךְ בְּאַבְנֵי קְלַע וְיִבְזְעוּנִיךְ בְּסַיְפֵהוֹן:\",0,0],[4,144,16,41,\"וְיוֹקְדוּן בָּתָּךְ בְּנוּרָא וְיַעְבְּדוּן בִּיךְ פּוּרְעֲנוּת דִינִין לְעֵינֵי מְדִינָן סַגִיאָן וְאֶבְטְלִינִיךְ מִלְמֶהֱוֵי כְּנַפְקַת בָּרָא וְאַף אֲגַר לָא תִתְּנִין עוֹד:\",0,0],[4,144,16,42,\"וַאֲנִיחַ חֵמְתִי בִיךְ וְתַעְדֵי קִנְאָתִי מִנִיךְ וַאֲסִיף וְלָא יְהֵי רוּגְזִי עוֹד:\",0,0],[4,144,16,43,\"חֲלַף דְלָא אִידְכַּרְתְּ יַת יוֹמֵי דְמִלְקָדְמִין וַהֲוֵית מַרְגְזָא קֳדָמַי בְּכָל אִלֵין וְאַף אֲנָא פּוּרְעֲנוּת אוֹרְחָתִיךְ בְּרֵישׁ יְהָבֵית אֲמַר יְיָ אֱלֹהִים לָא עֲבַדְתְּ לִיךְ עֵיצָה לְמֵיתַב מִן כָּל תּוֹעֲבָתָיִךְ:\",0,0],[4,144,16,44,\"הָא כָּל דְמָתֵיל עֲלָךְ יִמְתוֹל לְמֵימָר כְּעוֹבָדֵי אִמָא כֵּן בְּרַתָּא:\",0,0],[4,144,16,45,\"לְמָה הֲוֵית בְּרַתָּא לְאַרְעָא דִכְנַעַן לְמֶעֱבַּד כְּעוֹבָדֵי עַמָא דְאִיתְרַבּוּ אֲבָהָן עִם בְּנִין וַאֲחָתָא לִסְדוֹם וַעֲמוֹרָה דְאִישְׁתֵּיצֵי עִמְהוֹן אַבָהָן עִם בְּנִין הֲלָא אִמְכוֹן שָׂרָה בֵּינֵי חִתָּאֵי הֲוַת וְלָא עַבְדַת כְּעוֹבָדֵיהוֹן וַאֲבוּכוֹן אַבְרָהָם בֵּינֵי אֱמוֹרָאֵי וְלָא הֲלֵיךְ בְּעֵיצַתְהוֹן:\",0,0],[4,144,16,46,\"וַאֲחָתִיךְ רַבְּתָא שׁוֹמְרוֹן הִיא וְכַפְרָנָהָא דְיָתְבָא עַל שְׂמָאלִיךְ וַאֲחָתִיךְ דִזְעֵירָא מִנִיךְ דְיַתְבָא מִימִינִיךְ סְדוֹם וְכַפְרָנָהָא:\",0,0],[4,144,16,47,\"וְאִלוּ בְּאוֹרְחָתְהוֹן הֲלֵיכְתְּ וּכְתוֹעֲבָתְהוֹן עֲבַדְתְּ חֲסוֹךְ הֲוָה חוֹבִיךְ אֱלָהֵין דְאַסְגֵית לְחַבָּלָא מִנְהוֹן בְּכָל אוֹרְחָתָיִךְ:\",0,0],[4,144,16,48,\"קַיָם אֲנָא אֲמַר יְיָ אֱלֹהִים אִם עַבְדַת סְדוֹם אֲחָתִיךְ הִיא וְכַפְרָנָהָא כְּמָא דַעֲבַדְתְּ אַתְּ וְכַפְרָנָיִךְ:\",0,0],[4,144,16,49,\"הָא דֵין הֲוָה חוֹב סְדוֹם אֲחָתִיךְ גַאוְתָנִין סָבְעִין לַחֲמָא וּשְׁלֵיוָא וּשְׁדוּכַיָא הֲוָה לָהּ וּלְכַפְרָנָהָא וְיַד מִסְכֵּן וַחֲשׁוֹךְ לָא אַתְקֵיפַת:\",0,0],[4,144,16,50,\"וְאִתְרַבְרְבָא וַעֲבָדָא תּוֹעֵיבָא קֳדָמַי וְאַגְלֵיתִי יַתְהֵין כְּמָא דִגְלֵי קֳדָמַי:\",0,0],[4,144,16,51,\"וְשׁוֹמְרוֹן כְּפַלְגוּת חוֹבַיִךְ לָא חָבַת וְאַסְגֵית יַת תּוֹעֲבוֹתַיִךְ מִנְהוֹן וְזַכֵּית יַת אֲחָתַיִךְ בְּכָל תּוֹעֲבָתַיִךְ דַעֲבַדְתְּ:\",0,0],[4,144,16,52,\"אַף אַתְּ קַבִּילִי אִתְכְּנָעוּתִיךְ דִי בְעֵית לַאֲחַתִיךְ בְּחוֹבַיִךְ דְאַתְעֵיבְתְּ מִנְהֵין וְזַכְיָן מִנִיךְ וְאַף אַתְּ בַּהֲתִי וְקַבִּילִי אִתְכְּנָעוּתִיךְ בִּדְזַכֵּית אַחֲוָתַיִךְ:\",0,0],[4,144,16,53,\"וְאָתִיב יַת עַמְהֶן לְהֶן יַת עַמָא דִסְדוֹם וְכַפְרָנָהָא וְיַת עַמָא דְשׁוֹמְרוֹן וְכַפְרָנָהָא וְאָתֵיב גָלוּת עַמִיךְ בֵּינֵיהוֹן:\",0,0],[4,144,16,54,\"בְּדִיל דִתְקַבְּלִין אִתְכְּנָעוּתִיךְ וְתִתְכַּנְעִין מִכָּל דַעְבַדְתְּ בְּנַחֲמוֹתַיִךְ יַתְהֶן:\",0,0],[4,144,16,55,\"וַאֲחָתַיִךְ סְדוֹם וְכַפְרָנָהָא יְתוּבָן לְאַוְלְהֶן וְשֹׁמְרוֹן וְכַפְרָנָהָא יְתוּבוּן לְאַוְלְהֶן וְאַתְּ וְכַפְרָנָךְ תְּתוּבוּן לְאַוְלְכֶן:\",0,0],[4,144,16,56,\"וְלָא הֲוַת סְדוֹם אֲחָתִיךְ לְאוּלְפַן בְּפוּמִיךְ בְּיוֹם אִתְרַבְרְבוּתִיךְ:\",0,0],[4,144,16,57,\"עַד לָא תִתְגְלֵי בִישְׁתִּיךְ כְּעִדַן דַחֲסִידוּ כַּפְרָנֵי אֲרָם וְכָל סָחְרָנָהָא כַּפְרָנֵי פְּלִשְׁתָּאֵי דְבָזוּ יָתִיךְ מִסְחוֹר סְחוֹר:\",0,0],[4,144,16,58,\"יַת חוֹבֵי עֵיצַת חֶטְאָךְ וְיַת פּוּלְחַן תּוֹעֲבָתַיִךְ אַתְּ קַבֵּילְתִּנוּן אֲמַר יְיָ:\",0,0],[4,144,16,59,\"אֲרֵי כִּדְנַן אֲמַר יְיָ אֱלֹהִים וְאִתְפְּרַע מִנִיךְ כְּמָא דַעֲבַדְתְּ דִבְסַרְתְּ עַל מוֹמֵי לְאַשְׁנָאָה קְיָם:\",0,0],[4,144,16,60,\"וְדָכֵירְנָא אֲנָא יַת קְיָמִי דְעִמָךְ בְּיוֹמֵי קֳדָם וַאֲקֵים לָךְ קְיַם עֲלָם:\",0,0],[4,144,16,61,\"וְתִדְכְּרִין יַת אוֹרְחָתַיִךְ וְתִתְכַּנְעוּן בְּקָרְבוּתִיךְ יַת מְדִינָן דְרַבְרְבָן מִנִיךְ עִם דְעַדְקָן מִנִיךְ וּמְסָרֵית יַתְהוֹן לִיךְ לְאִשְׁתְּמָעָא וְאַתְּ לָא עֲבַדְתְּ יַת אוֹרַיְתָא:\",0,0],[4,144,16,62,\"וַאֲקֵים אֲנָא יַת קְיָמִי עִמָךְ וְתִידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,16,63,\"בְּדִיל דְתִדְכְּרִין וְתִבְהֲתִין וְלָא יְהֵי לִיךְ עוֹד לְאִתְרַבְרְבָא בְּמִלֵי פּוּמִיךְ מִן קֳדָם אִתְכְּנָעוּתִיךְ כַּד אֶשְׁבּוֹק לִיךְ לְכָל דַעֲבַדְתְּ אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,17,1,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימַר:\",0,0],[4,144,17,2,\"בַּר אָדָם חוּד חִידְתָּא וּמְתַל מַתְלָא עַל בֵּית יִשְׂרָאֵל:\",0,0],[4,144,17,3,\"וְתֵימַר כִּדְנַן אֲמַר יְיָ אֱלֹהִים נִשְׁרָא רַבָּא רַב גַפִּין אֲרִיךְ אֵיבְרָן חָפֵי כַנְפִין דִילֵהּ צִיוּרִין אֲתָא לְלִבְנָן וּנְסֵיב יַת עוֹבַרְתָּא דְאַרְזָא רָמָא:\",0,0],[4,144,17,4,\"יַת רֵישׁ שַׁבִּשְׁתֵּהּ נְסִיב וְאוֹבְלֵיהּ לְאַרְעָא דְבָטְלָא מִפּוּלְחָנָא בְאַרְעָא דִכְנַעַן וְעַד לָא יַעֲלוּן לָהּ בֵּית יִשְׂרָאֵל בְּקִרְיַת תַּגָרִין שַׁוְיֵיהּ:\",0,0],[4,144,17,5,\"וּנְסִיב מִזַרְעָא דְאַרְעָא וְיַהֲבֵיהּ בַּחֲקַל טַב לְמִזְרַע נִצְבַהּ עַל מַיִין סַגִיאִין גְפַּן נִצְבָא שַׁוְיֵיהּ:\",0,0],[4,144,17,6,\"וּצְמַח וַהֲוָה לְגֶפֶן תַּקִיף מַכִּיךְ בְּקוֹמָא לְכַפָפָא עוֹבַרְתֵּהּ לֵיהּ וְשָׁרָשׁוֹהִי תְּחוֹתוֹהִי יְהוֹן וַהֲוָה לְגֶפֶן וַעֲבַד שַׁבְקִין וּשְׁלַח עוֹבָרָן:\",0,0],[4,144,17,7,\"וַהֲוָה נִשְׁרָא חַד רַבָּא רַב גַפִּין וַחֲפֵי כַנְפִין וְהָא גוּפְנָא הָדָא כַּפַּת שָׁרְשׁוֹהִי עֲלוֹהִי וְעוֹבַרְתֵּהּ שְׁלָחַת לֵיהּ לְאַשְׁקָאָה יָתָהּ מֵעוּגְיַת נִצְבָתָהּ:\",0,0],[4,144,17,8,\"בַּחֲקַל טַב עֲלֵי מַיִין סַגִיאִין הִיא שְׁתִילָה לְמֶעְבַר עֲנַף וּלְמִטְעַן פֵּרִין לְמֶהֱוֵי לְגֶפֶן תַקִיף:\",0,0],[4,144,17,9,\"אֲמַר כִּדְנַן יְיָ אֱלֹהִים תִּצְלַח הֲלָא יַת שָׁרְשׁוֹהִי יַפְסֵיק וְיַת אִבָּהּ יַקְטֵיף וְיִבְשׁוּן כָּל טַרְפֵי צִמְחָהּ יִתְּרוֹן וְלָא בְמַשִׁרְיָן סַגִיאִין וּבְעַם סַגִי יֵיתוּן לְמֶעְקַר יָתָהּ מִשׁוֹרְשָׁהָא:\",0,0],[4,144,17,10,\"וְהָא שְׁתִילָא הֲתִצְלַח הֲלָא כְּמִיקְרַב בָּה רוּחַ קִידוּמָא תִיבַשׁ מֵיבַשׁ עַל עוּגְיַת נִצְבְתָהּ תִּיבָשׁ:\",0,0],[4,144,17,11,\"וַהֲוָה פִּתְגָם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,17,12,\"אֱמַר כְּעַן לְעַמָא סַרְבָנָא הֲלָא יְדַעְתּוּן מָה אִלֵין אֱמַר הָא אָתָא מַלְכָּא דְבָבֶל לִירוּשְׁלֵם וּדְבַר יַת מַלְכָּהּ וְיַת רַבְרְבָהָא וְאוֹבִיל יַתְהוֹן לְוָתֵה לְבָבֶל:\",0,0],[4,144,17,13,\"וּדְבַר מִזַרְעָא דְמַלְכוּתָא וּגְזַר עִמֵהּ קְיַם וְאָעֵיל יָתֵהּ בְּמוֹמֵי וְיַת רַבְרְבֵי אַרְעָא דְבַר:\",0,0],[4,144,17,14,\"לְמֶהֱוֵי מַלְכוּ חַלָשָׁא בְּדִיל דְלָא לְאִתְרַבְרְבָא לְמִטַר יַת קְיָמַהּ לְמִפְלְחֵהּ:\",0,0],[4,144,17,15,\"וּמְרַד בֵּיהּ לְשַׁלָחָא אִזְגַדוֹהִי לְמִצְרַיִם לְמִתַּן לֵיהּ סוּסְוָן וְעַם סַגִי הֲיִצְלַח הֲיִשְׁתֵּיזִיב דְעָבֵיד אִילֵין וּמְשַׁנֵי קַיֵם הֲיִשְׁתֵּיזֵיב:\",0,0],[4,144,17,16,\"קַיֵם אֲנָא אֲמַר יְיָ אֱלֹהִים אִם לָא בְּאַתְרָא דְמַלְכָּא דְאַמְלִיךְ יָתֵיהּ דִבְסַר עַל מוֹמָתֵהּ וּדְאַשְׁנֵי יַת קְיָמֵיהּ עִמֵיהּ בְּגוֹ בָבֶל יְמוּת:\",0,0],[4,144,17,17,\"וְלָא בְּמַשִׁרְיָן סַגִיאִין וּבְעַם סַגִי יַעְבֵד עִמֵהּ פַרְעֹה קְרָבָא בְּמִצְבַּר מְלֵיתָא וּבְמִבְנֵי כַרְקוֹם לְשֵׁיצָאָה מְדִינַן סַגִיאִין:\",0,0],[4,144,17,18,\"וּבְסַר עַל מוֹמֵי לְאַשְׁנָאָה קְיַם וְהָא אַמְטֵי יְדֵיהּ לְפַרְעֹה וְכָל אִלֵין עֲבַד לָא יִשְׁתֵּיזֵיב:\",0,0],[4,144,17,19,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים קַיָם אֲנָא אִם לָא מוֹמָתִי דִבְסַר וּקְיָמִי דְשַׁנִי וְאֶתֵּן פּוּרְעֲנוּת אוֹרְחֵהּ בְּרֵישֵׁהּ:\",0,0],[4,144,17,20,\"וְאֶפְרוֹס עֲלוֹהִי מְצֻדָתִי וְיִתְאַחַד בִּסְרִגְתִּי וְאַגְלִינֵהּ לְבָבֶל וְאִתְפְּרַע מִנֵיהּ תַּמָן שִׁקְרַהּ דִשְׁקַר קֳדָמַי:\",0,0],[4,144,17,21,\"וְיַת כָּל גַבְּרוֹהִי בְּכָל מַשִׁרְיָתֵיהּ בְּחַרְבָּא יִתְקַטְלוּן וּדְיִשְׁתָּאֲרוּן לְכָל רוּחַ יִתְבַּדְרוּן וְתֵידְעוּן אֲרֵי אֲנָא יְיָ גְזָרֵית בְּמֵימְרִי:\",0,0],[4,144,17,22,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים וַאֲקָרֵיב אֲנָא מִמַלְכוּתָא דְבֵית דָוִד דִמְתִיל כְּאַרְזָא רָמָה וַאֲקַיְמִינֵהּ מִבְּנֵי בְנוֹהִי יָנִיק וַאֲרַבֵּי וַאֲקַיְמִינֵיהּ בְּמֵימְרִי בְּטוּר רָם וּמְנַטֵל:\",0,0],[4,144,17,23,\"בְּטוּר קוּדְשָׁא דְיִשְׂרָאֵל אֲקַיְמִינֵיהּ וְיַכְנֵישׁ מַשִׁרְיָן וְיַעְבֵיד סוּמְכְוָן וִיהֵי לְמֶלֶךְ תַּקִיף וְיִסְתַּמְכוּן עֲלוֹהִי כָּל צַדִיקַיָא וְכָל עִנְוְתָנַיָא בִּטְלַל מַלְכוּתֵיהּ יִשְׁרוּן:\",0,0],[4,144,17,24,\"וְיֵדְעוּן כָּל מַלְכֵי עַמְמַיָא אֲרֵי אֲנָא יְיָ אַמְאִיכֵית מַלְכוּת דַהֲוַת תַּקִיפָא וְתַקִיפַת מַלְכוּת דַהֲוַת חַלָשָׁא אַמְאִיכֵית מַלְכוּת עַמְמַיָא דַהֲוַת תַּקִיפָא כְּאָעָא רָטִיב וּתְקִיפִית מַלְכוּת בֵּית יִשְׂרָאֵל דַהֲוַת חַלָשָׁא כְּאָעָא יַבִּישׁ אֲנָא יְיָ גְזָרִית בְּמֵימְרִי וַאֲקַיֵם:\",0,0],[4,144,18,1,\"וַהֲוָה פִתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,18,2,\"מָה לְכוֹן דְאַתּוּן מַתְלִין יַת מַתְלָא הָדֵין עַל אַרְעָא דְיִשְׂרָאֵל לְמֵימָר אֲבָהָתָא חָטָן וּבְנַיָא לְקָן:\",0,0],[4,144,18,3,\"קַיָם אֲנָא אֲמַר יְיָ אֱלֹהִים אִם יְהֵי לְכוֹן עוֹד מְתֵיל מַתְלָא הָדֵין בְּיִשְׂרָאֵל:\",0,0],[4,144,18,4,\"הָא כָּל נַפְשְׁתָא דִילִי אִינוּן כִּנְפַשׁ אַבָּא וְכִנְפַשׁ בְּרָא קֳדָמַי אִינוּן אֱנַשׁ דְיֶחְטֵי הוּא יְמוּת:\",0,0],[4,144,18,5,\"וּגְבַר אֲרֵי יְהֵי זַכַּאי וְיַעְבֵיד דִין דִקְשׁוֹט וְזָכוּ:\",0,0],[4,144,18,6,\"בְּטוּרַיָא לָא פְלַח לְטַעֲוָתָא וְעֵינוֹהִי לָא זְקַף לְפוּלְחַן טַעֲוַת בֵּיהּ יִשְׂרָאֵל וְיַת אִתַּת חַבְרֵיהּ לָא סְאֵיב וּלְוַת אִתָּא מְסָאֲבָא לָא עָל:\",0,0],[4,144,18,7,\"וֶאֱנַשׁ לָא אוֹנֵי מַשְׁכּוֹן דְחוֹבְתָא אֲתֵיב גְזֵילָא לָא גְזַל מִלְחַמְמֵיהּ לְכָפְנָא יְהֵב וְעַרְטִילָאָה כַּסֵי מִכְּסוּתֵיהּ:\",0,0],[4,144,18,8,\"בְּחִבּוּלְיָא לָא יְהַב וְרִבִּיתָא לָא נְסִיב מִשִׁקְרָא אֲתֵיב יְדֵהּ דִין דִקְשׁוֹט עֲבֵיד בֵּין גְבַר לִגְבַר:\",0,0],[4,144,18,9,\"בִּקְיָמַי הַלִיךְ וְדִינַי נְטַר לְמֶעְבַּד קְשׁוֹט צַדִיקָא הוּא מֵיחָא יֵחֵי אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,18,10,\"וְאוֹלֵיד בַּר רַשִׁיעָא אָשֵׁיד דַם וְיַעְבֵּיד לַאֲחוּהִי מַחֲדָא מֵאִלֵין:\",0,0],[4,144,18,11,\"וְהוּא יַת כָּל אִלֵין לָא עֲבַד אֱלָהֵין בְּטוּרַיָא פְּלַח לְטַעֲוָתָא וְיַת אִתַּת חַבְרֵיהּ סָאֵיב:\",0,0],[4,144,18,12,\"מִסְכֵּן וְחָשִׁיךְ אוֹנִי גְזֵילָא גְזַל מַשְׁכּוֹנָא לָא אֲתֵיב וּלְפוּלְחַן טַעֲוָתָא זְקַף עֵינוֹהִי תּוֹעֵיבָא עָבַד:\",0,0],[4,144,18,13,\"בְּחִבּוּלְיָא יְהַב וְרִבִּיתָא נְסִיב הֲאִתְקַיֵם לָא יִתְקַיֵם יַת כָּל תּוֹעֲבָתָּא הָאִלֵין עֲבַד מֵימַת יְמוּת חוֹבַת קְטוֹלֵהּ בֵּיהּ תְּהֵי:\",0,0],[4,144,18,14,\"וְהָא אוֹלִיד בַּר וַחֲזָא יַת כָּל חוֹבֵי אֲבוֹהִי דִעֲבָד וַחֲזָא וְלָא עָבַד כְּוַתְהוֹן:\",0,0],[4,144,18,15,\"עַל טוּרַיָא לָא פְלַח לְטַעֲוָתָא וְעֵינוֹהִי לָא זְקַף לְפוּלְחַן טַעֲוַת בֵּית יִשְׂרָאֵל וְיַת אִתַּת חַבְרֵיהּ לָא סָאֵיב:\",0,0],[4,144,18,16,\"וֶאֱנַשׁ לָא אוֹנִי מַשְׁכּוֹנָא לָא נְסִיב וּגְזֵלָה לָא גְזַל מִלַחְמֵיהּ לְכָפְנָא יְהַב וְעַרְטִילָאָה כַסֵי מִכְּסוּתֵהּ:\",0,0],[4,144,18,17,\"מִמַסְכֵּנָא לָא אֲתֵיב יְדֵהּ חִבּוּלְיָא וְרִבִּיתָא לָא נְסִיב דִינִי עֲבִיד בִּקְיָמֵי הֲלִיךְ הוּא לָא יְמוּת בְּחוֹבֵי אֲבוּהִי מֵיחָא יְחֵי:\",0,0],[4,144,18,18,\"אֲבוּהִי אֲרֵי עֲשַׁק עִשְׁקָא גְזַל גְזֵלָא לְחַד מֵאֲחוֹהִי וּדְלָא תַקִין עָבֵד בְּגוֹ עַמֵיהּ וְהָא מִית בְּחוֹבֵיהּ:\",0,0],[4,144,18,19,\"וְתֵימְרוּן מָא דֵין לָא לָקֵי בְרָא בְּחוֹבֵי אַבָּא וּבְרָא דִין וּקְשׁוֹט וּזְכוּ עָבַד יַת כָּל קְיָמֵי נְטַר וַעֲבַד יַתְהוֹן מֵיחָא יְחֵי:\",0,0],[4,144,18,20,\"אֱנַשׁ דְיֵחוֹב הוּא יְמוּת בְּרָא לָא לָקֵי בְּחוֹבֵי אַבָּא וְאַבָּא לָא לָקֵי בְּחוֹבֵי בְרָא זְכוּת זַכָּאָה בֵּיהּ יִתְקַיֵם וְחוֹבַת חַיָבָא עֲלוֹהִי תְהֵא:\",0,0],[4,144,18,21,\"וְרַשִׁיעָה אֲרֵי יְתוּב מִכָּל חוֹבוֹהִי דַעֲבַד וְיִטַר יַת כָּל קְיְמַי וְיַעֲבֵיד דִין דִקְשׁוֹט וּזְכוּ מֵיחָא יְחֵי לָא יְמוּת:\",0,0],[4,144,18,22,\"כָּל חוֹבוֹהִי דַעֲבַד לָא יִדְכְּרוּן לֵיהּ בִּזְכוּתֵהּ דַעֲבַד יִתְקַיֵם:\",0,0],[4,144,18,23,\"הַמִרְעָא רָעֵינָא בְּמוֹתֵיהּ דְרַשִׁיעָא אֲמַר יְיָ אֱלֹהִים הֲלָא כַּד יְתוּב מֵאוֹרְחֵיהּ וְיִתְקַיֵם:\",0,0],[4,144,18,24,\"וְכַד יְתוּב זַכָּאָה מִזְכוּתֵהּ וְיַעְבֵּיד שְׁקַר כְּכֹל תּוֹעֲבָתָא דִי עֲבַד רַשִׁיעָא יַעְבֵּיד דְאִתְקַיֵם כָּל זְכוּתֵיהּ דַעֲבַד לָא יִדְכְּרוּן בְּשִׁקְרֵיהּ דִשְׁקַר וּבְחוֹבוֹהִי דִי חַב בְּהוֹן יְמוּת:\",0,0],[4,144,18,25,\"וַאֲמַרְתּוּן לָא מַפְרְשַׁן לָנָא אוֹרְחַת טוּבָא דַייָ שְׁמָעוּ כְעַן בֵּית יִשְׂרָאֵל הֲאוֹרְחַת טוּבִי לָא מַפְרְשַׁן לְכוֹן הֲלָא אוֹרְחָתְכוֹן דִילְכוֹן לָא תַקְנָן:\",0,0],[4,144,18,26,\"וְכַד יְתוּב זַכָּאָה מִזְכוּתֵהּ וְיַעְבֵּיד שְׁקַר וִימוּת עֲלֵיהוֹן בְּשִׁקְרֵיהּ דִי עֲבַד יְמוּת:\",0,0],[4,144,18,27,\"וְכַד יְתוּב רַשִׁיעָא מֵחוֹבוֹהִי דִי עֲבַד וְיַעְבֵּיד דִין דִקְשׁוֹט וּזְכוּ הִיא יַת נַפְשֵׁהּ יְקַיֵם:\",0,0],[4,144,18,28,\"וַחֲזָא וְתַב מִכָּל חוֹבוֹהִי דִי עֲבַד מֵיחָא יְחֵי לָא יְמוּת:\",0,0],[4,144,18,29,\"וַאֲמָרוּ בֵּית יִשְׂרָאֵל לָא מַפְרְשָׁן לָנָא אוֹרְחַת טוּבָא דַייָ הֲאוֹרְחַת טוּבִי לָא מַפְרְשַׁן לְכוֹן בֵּית יִשְׂרָאֵל הֲלָא אוֹרְחַתְכוֹן דִילְכוֹן לָא תַקְנָן:\",0,0],[4,144,18,30,\"בְּכֵן אֱנָשׁ כְּאוֹרְחָתֵיהּ אֶתְפְּרַע מִנְכוֹן בֵּית יִשְׂרָאֵל אֲמַר יְיָ אֱלֹהִים תּוּבוּ לְפוּלְחָנִי וְאַעְדוּ מִנְכוֹן פּוּלְחַן טַעֲוָתָא וְלָא יְהֵי לְכוֹן לְתִקְלַת חוֹבִין:\",0,0],[4,144,18,31,\"אַרְחִיקוּ מִנְכוֹן יַת כָּל חוֹבֵיכוֹן דְחַבְתּוֹן בְּהוֹן וֶעֱבִידוּ לְכוֹן לֵב דָחֵיל וְרוּחַ דַחֲלָא וְלָמָה תְמוּתוּן בֵּית יִשְׂרָאֵל:\",0,0],[4,144,18,32,\"אֲרֵי לָא רָעֵינָא בְמוֹתָא דְחַיָב לִמְמָת אֲמַר יְיָ אֱלֹהִים תּוּבוּ לְפוּלְחָנִי וְאִתְקַיְמוּ:\",0,0],[4,144,19,1,\"וְאַתְּ טוּל אִלְיָא עַל רַבְרְבֵי יִשְׂרָאֵל:\",0,0],[4,144,19,2,\"וְתֵימַר מַה כְּנִשְׁתָּא דְיִשְׂרָאֵל דַהֲוַת דַמְיָא לְלַיְתָא בֵּינֵי מַלְכַיָא רַבָּא בֵּינֵי שִׁלְטוֹנַיָא רַבִּיאַת בְּנָהָא:\",0,0],[4,144,19,3,\"וְרַבִּיאַת חַד מִבְּנָהָא מַלְכָּא הֲוָה וַאֲלִיף לְמִקְטַל קְטוֹל אֱנָשָׁא קְטַל:\",0,0],[4,144,19,4,\"וּשְׁמָעוּ עֲלוֹהִי עַמְמַיָא בִּסְרִיגַתְהוֹן אִתְאֲחַד וְאַיְתִיאוּהוּ בְּשַׁלְשְׁלָן לְאַרְעָא דְמִצְרָיִם:\",0,0],[4,144,19,5,\"וַחֲזַת אֲרֵי פְּסַק אֲבַד סִבּוּרָה וְרַבִּיאַת חַד מִבְּנָהָא מַלְכָּא שַׁוְיָתֵיהּ:\",0,0],[4,144,19,6,\"וְהַלֵיךְ בְּגוֹ מַלְכַיָא מַלְכָּא הֲוָה וַאֲלֵיף לְמִקְטַל קְטוֹל אֱנָשָׁא קְטָל:\",0,0],[4,144,19,7,\"וְאַצְדֵי בִּרְנְיָתֵיהּ וְקִרִוֵיהוֹן אַחְרִיב וּצְדִיאַת אַרְעָא וּמְלוֹאָהּ מִקָל אִתְרְגֻשְׁתֵּהּ:\",0,0],[4,144,19,8,\"וְאִתְכְּנִישׁוּ עֲלוֹהִי עַמְמַיָא סְחוֹר סְחוֹר מִמְדִינָתָא וּפְרָסוּ עֲלוֹהִי מְצָדַתְהוֹן בִּסְרִיגַתְהוֹן אִתְאַחַד:\",0,0],[4,144,19,9,\"וְיַהֲבוּהִי בְּקוֹלָרִין בְּשִׁלְשְׁלָן וְאַיְתִיאוּהוּ לְוַת מַלְכָּא דְבָבֶל אַיְתִיאוּהוּ בִּמְצַדְיָא בְּדִיל דְלָא יִשְׁתְּמַע קָלֵיהּ עַד עַל טוּרֵי יִשְׂרָאֵל:\",0,0],[4,144,19,10,\"כְּנִשְׁתָּא דְיִשְׂרָאֵל בְּמַעְבְּדָה אוֹרַיְתָא דַמְיָא כְגוּפַן דִשְׁתִילָא עַל מַבּוּעַ דְמַיָן דְנוֹפָהּ שַׁפִּיר וְסוֹכָהּ מַטְלָן הִיא שְׁתִילָה עַל מַיִין סַגִיאִין:\",0,0],[4,144,19,11,\"וַהֲווֹ בָּהּ שִׁכלְטוֹנִין תַּקִיפִין וּמַלְכִין דְגִבָּרִין לְשַׁעְבְּדָא מַלְכוּ וְרָאֵים בְּתוּקְפֵיהּ עַל מַלְכוּתֵיהּ וְאִתְנְצַח בְּסוּמְכְוָתֵיהּ בִּסְגֵי גִבָּרוֹהִי:\",0,0],[4,144,19,12,\"וְאִתְעַקְרַת בִּתְקוֹף מֵאַרְעָא בֵּית שְׁכִנְתָּא לְאַרְעָא אוֹחֲרֵי אִתְגְלִיאַת וּמְלַךְ דְתַקִיף כְּרוּחַ קִידוּמָא קְטֵיל עַמָהּ אִטַלְטָלוּ וּגְלוֹ שִׁלְטוֹנֵי תוּקְפָא וְעַמְמַיָא דְתַקִיפִין כְּאֶשְׁתָּא שֵׁיצִיאִינוּן:\",0,0],[4,144,19,13,\"וּכְעַן דַמְיָא לְגוּפַן דִשְׁתִילָא בִּמַדְבְּרָא בְּאַרְעָא צַדְיָא וַחֲרֵיבָא:\",0,0],[4,144,19,14,\"וַאֲתוֹ עַמְמַיָא דְתַקִיפִין כְּאֶשְׁתָּא מֵחוֹבֵי זְדוֹנָהּ עַמָהּ קְטִילוּ וְלָא הֲווֹ בָהּ שִׁלְטוֹנִין תַּקִיפִין מַלְכִין דְגִבָּרִין לְשַׁעְבָּדָא מַלְכוּ אֲמַר נְבִיָא אִלְיָא הִיא נְבוּאֲתָא וּתְהֵי לְאִלְיָא:\",0,0],[4,144,20,1,\"וַהֲוָה בְשַׁתָּא שְׁבִיעֲתָא בְּחַמְשָׁא בְּעַסְרָא לְיַרְחָא אֲמַר נְבִיָא אֲתוֹ גַבְרִין מִסָבֵי יִשְׂרָאֵל לְמִתְבַּע אוּלְפַן מִן קֳדָם יְיָ וִיתִיבוּ קֳדָמַי:\",0,0],[4,144,20,2,\"וַהֲוָה פִתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,20,3,\"בַּר אָדָם אִתְנַבֵּי לְסָבֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן כִּדְנַן אֲמַר יְיָ אֱלֹהִים הַלְמִתְבַּע אוּלְפַן מִן קֳדָמַי אַתּוּן אָתָן קַיָם אֲנָא אִם אֶשְׁתְּאֵיל לְכוֹן בְּמֵימְרִי אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,20,4,\"הֲתוֹכַח יַתְהוֹן הֲתוֹכַח בַּר אָדָם יַת תּוֹעֲבַת אֲבָהַתְהוֹן הוֹדָעִינוּן:\",0,0],[4,144,20,5,\"וְתֵימַר לְהוֹן כִּדְנַן אֲמַר יְיָ אֱלֹהִים בְּיוֹמָא דְאִתְרְעֵיתִי בְיִשְׂרָאֵל וְקַיְמֵית לְהוֹן בְּמֵימְרִי לְזַרְעָא דְבֵית יַעֲקֹב וְאִתְגְלֵיתִי לְמִפְרַקְהוֹן בְּאַרְעָא דְמִצְרַיִם וְקַיְמֵית בְּמֵימְרִי לְהוֹן לְמֵימָר אֲנָא יְיָ אֱלָֹהָכוֹן:\",0,0],[4,144,20,6,\"בְּיוֹמָא הַהוּא קַיְמִית לְהוֹן בְּמֵימְרִי לְאַפָּקוּתְהוֹן מֵאַרְעָא דְמִצְרַיִם לְאַרְעָא דִיהָבֵית לְהוֹן עַבְדָא חֲלַב וּדְבָשׁ תּוּשְׁבְּחָא הִיא לְכָל מְדִינָתָא:\",0,0],[4,144,20,7,\"וַאֲמָרֵית לְהוֹן גְבַר יַת שִׁקוּצוֹהִי אַרְחִיקוּ מִקֳבֵיל עֵינוֹהִי וּבְפוּלְחַן טַעֲוַת מִצְרָאֵי לָא תִּסְתַּאֲבוּן אֲנָא יְיָ אֱלָהָכוֹן:\",0,0],[4,144,20,8,\"וְסָרִיבוּ עַל מֵימְרִי וְלָא אָבוּ לְקַבָּלָא לִנְבִיֵי גְבַר יַת שִׁקוּצֵי עֵינֵיהוֹן לָא אַרְחִיקוּ וְיַת פּוּלְחַן טַעֲוַת מִצְרָאֵי לָא שְׁבָקוּ וַאֲמָרֵית לְמִשְׁפַּךְ חֵימְתִי עֲלֵיהוֹן דְיָחוּל רוּגְזִי בְּהוֹן בְּגוֹ אַרְעָא דְמִצְרָיִם:\",0,0],[4,144,20,9,\"וַעֲבָדֵית בְּדִיל שְׁמִי בְּדִיל דְלָא יִתְחַל לְעֵינֵי עַמְמַיָא דִי אִינוּן בֵּינֵיהוֹן דְאִתְגְלֵיתִי לְמִפְרַקְהוֹן לְעֵינֵיהוֹן לְאַפָּקוּתְהוֹן מֵאַרְעָא דְמִצְרָיִם:\",0,0],[4,144,20,10,\"וְאַפֵּיקְתִּינוּן מֵאַרְעָא דְמִצְרָיִם וְאָעֵלְתִּינוּן לְמַדְבְּרָא:\",0,0],[4,144,20,11,\"וִיהָבֵית לְהוֹן יַת קְיָמַי וְיַת דִינַי הוֹדְעֵית יַתְהוֹן דְאִם יַעְבֵּיד יַתְהוֹן אֱנָשָׁא וִיחֵי בְהוֹן בְּחַיֵי עַלְמָא:\",0,0],[4,144,20,12,\"וְאַף יַת יוֹמֵי שַׁבַּיָא דִילִי יְהָבֵית לְהוֹן לְמֶהֱוֵי לְאָת בֵּין מֵימְרִי וּבֵינֵיהוֹן לְמֵדַע אֲרֵי אֲנָא יְיָ מְקַדְשֵׁיהוֹן:\",0,0],[4,144,20,13,\"וְסָרִיבוּ עַל מֵימְרִי בֵּית יִשְׂרָאֵל בְּמַדְבְּרָא בִּקְיָמַי לָא הֲלִיכוּ וְיַת דִינַי קָצוּ דְאִם יַעְבֵּיד יַתְהוֹן אֱנָשָׁא וְיֵיחֵי בְהוֹן חַיֵי עַלְמָא וְיַת יוֹמֵי שַׁבַּיָא דִילִי אֲחִילוּ לַחֲדָא וַאֲמָרֵית לְמִשְׁפַּךְ חֲמָתִי עֲלֵיהוֹן בְּמַדְבְּרָא לְשֵׁיצָיוּתְהוֹן:\",0,0],[4,144,20,14,\"וַעֲבָדֵית בְּדִיל שְׁמִי בְּדִיל דְלָא יִתְחַל לְעֵינֵי עַמְמַיָא דְאַפֵיקְתִּינוּן לְעֵינֵיהוֹן:\",0,0],[4,144,20,15,\"וְאַף אֲנָא קַיְמֵת בְּמֵימְרִי לְהוֹן בְּמַדְבְּרָא בְּדִיל דְלָא לְאָעֲלָא יַתְהוֹן לְאַרְעָא דִי יְהָבֵית עָבְדָא חֲלַב וּדְבַשׁ תּוּשְׁבְּחָא הִיא לְכָל מְדִינָתָא:\",0,0],[4,144,20,16,\"חֲלַף דִי בְדִינַי קָצוּ וְיַת קְיָמַי לָא הַלִיכוּ בְּהוֹן וְיַת יוֹמֵי שַׁבַּיָא דִילִי אֲחִילוּ אֲרֵי בָתַר פוּלְחַן טַעֲוָתְהוֹן לִבְּהוֹן טָעֵי:\",0,0],[4,144,20,17,\"וְחָס מֵימְרִי עֲלֵיהוֹן מִלְחַבְּלוּתְהוֹן וְלָא עֲבָדִית עִמְהוֹן גְמִירָא בְּמַדְבְּרָא:\",0,0],[4,144,20,18,\"וַאֲמָרֵית לִבְנֵיהוֹן בְּמַדְבְּרָא בִּגְזֵירַת אֲבָהַתְכוֹן לָא תְהָכוּן וְיַת נִימוּסֵיהוֹן לָא תִטְרוּן וּבְפוּלְחַן טַעֲוָתְהוֹן לָא תִסְתַּאֲבוּן:\",0,0],[4,144,20,19,\"אֲנָא יְיָ אֱלָהָכוֹן בִּקְיָמֵי הֲלִיכוּ וְיַת דִינֵי טָרוּ וַעֲבִידוּ יַתְהוֹן:\",0,0],[4,144,20,20,\"וְיַת יוֹמֵי שַׁבַּיָא דִילִי קַדִישׁוּ וִיהוֹן לְאָת בֵּין מֵימְרִי וּבֵינֵיכוֹן לְמֵידַע אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:\",0,0],[4,144,20,21,\"וְסָרִיבוּ עַל מֵימְרִי בְּנַיָא בִּקְיָמַי לָא הֲלִיכוּ וְיַת דִינַי לָא נְטָרוּ לְמֶעְבַּד יַתְהוֹן דְאִם יַעְבֵּיד יַתְהוֹן אֱנָשָׁא וִיחֵי בְהוֹן בְחַיֵי עַלְמָא יַת יוֹמֵי שַׁבַּיָא דִילִי אֲחִילוּ וַאֲמָרֵית לְמִשְׁפַּךְ חֵימְתִי עֲלֵיהוֹן דְיָחוּל רוּגְזִי בְהוֹן בְּמַדְבְּרָא:\",0,0],[4,144,20,22,\"וַאֲתֵיב יַת מְחַת גְבוּרְתִּי וַעֲבָדֵית בְּדִיל שְׁמִי בְּדִיל דְלָא יִתְחַל לְעֵינֵי עַמְמַיָא דְאַפְקֵית יַתְהוֹן לְעֵינֵיהוֹן:\",0,0],[4,144,20,23,\"אַף אֲנָא קַיְמֵית בְּמֵימְרִי לְהוֹן בְּמַדְבְּרָא לְאַגְלָאָה יַתְהוֹן לְבֵינֵי עַמְמַיָא וּלְבַדָרָא יַתְהוֹן בִּמְדִינָתָא:\",0,0],[4,144,20,24,\"חֲלַף דְדִינֵי לָא עֲבָדוּ וּבִקְיָמַי קָצוּ וְיַת יוֹמֵי שַׁבַּיָא דִילִי אֲחִילוּ וּבָתַר טַעֲוַת אֲבָהַתְהוֹן הֲוָאָה עֵינֵיהוֹן:\",0,0],[4,144,20,25,\"וְאַף אֲנָא מִדְמָרְדוּ בְמֵימְרֵי וְלָא אָבוּ לְקַבָּלָא לִנְבִיאַי אַרְחֵיקְתִּינוּן וּמְסַרְתִּינוּן בְּיַד שַׂנְאֵיהוֹן וּבָתַר יִצְרֵיהוֹן טִפְּשָׁא אֲזָלוּ וַעֲבָדוּ גְזֵירָן דְלָא תַקְנָן וְנִימוּסִין דְלָא אִתְקַיֵמְתּוּן בְּהוֹן:\",0,0],[4,144,20,26,\"וְסָאִיבֵית יַתְהוֹן בְּמַתְּנָתְהוֹן בְּאַעֲבְּרָא כָּל פְּתַח וַלְדָא בְדִיל דְאַצְדִינוּן בְּדִיל דְיֵדְעוּן דִי אֲנָא יְיָ:\",0,0],[4,144,20,27,\"בְּכֵן אִתְנַבֵּי לְבֵית יִשְׂרָאֵל בַּר אָדָם וְתֵימַר לְהוֹן כִּדְנַן אֲמַר יְיָ אֱלֹהִים עוֹד דָא אַרְגִיזוּ קָדְמַי אֲבָהָתְכוֹן בִּדְשַׁקָרוּ בְּמֵימְרִי שְׁקַר:\",0,0],[4,144,20,28,\"וְאָעֵילְתִּינוּן לְאַרְעָא דְקַיֵמִית בְּמֵימְרִי לְמִתַּן יָתָהּ לְהוֹן וַחֲזוֹ כָּל רָמָא מְנַטְלָא וְכָל אִילַן עַבּוּף וּנְכִיסוּ תַמָן אַרְגָזָא קוּרְבָּנֵיהוֹן וְשַׁוִיאוּ תַמָן פּוּלְחַן דִבְחֵיהוֹן וּנְסִיכוּ תַמָן יַת נִכְסֵיהוֹן:\",0,0],[4,144,20,29,\"וַאֲמָרֵית לְהוֹן מָא בָמָתָא דְאַתּוּן אָתָן לְאִשְׁתְּטָאָה תַמָן וְאִתְקְרִי שְׁמָהּ בָּמָתָא עַד יוֹמָא הָדֵין:\",0,0],[4,144,20,30,\"בְּכֵן אֲמַר לְבֵית יִשְׂרָאֵל כִּדְנַן אֲמַר יְיָ אֱלֹהִים הַבְּאוֹרַח אֲבָהַתְכוֹן אַתּוּן מִסְתַּאֲבִין וּבָתַר שִׁקוּצֵיהוֹן אַתּוּן טָעָן:\",0,0],[4,144,20,31,\"וּבְמַטַל מַתְּנָתֵיכוֹן בְּאַעֲבָרָא בְּנֵיכוֹן בְּנוּרָא אַתּוּן מִסְתַּאֲבִין לְכָל פּוּלְחַן טַעֲוָתְכוֹן עַד יוֹמָא דֵין וַאֲנָא אֶשְׁתָּאֵיל לְכוֹן בְּמֵימְרִי בֵּית יִשְׂרָאֵל קַיָם אֲנָא אֲמַר יְיָ אֱלֹהִים אִם אֶשְׁתְּאֵין לְכוֹן בְּמֵימְרִי:\",0,0],[4,144,20,32,\"וּדְאַתּוּן מְהַרְהֲרִין וְדִסְלִיקַת עַל לִבְּכוֹן קֳדָמַי גַלְיָן דְאַתּוּן אָמְרִין נְהֵי כְעַמְמַיָא כְּזַרְעֲיַת מְדִינָתָא לְשַׁמְשָׁא אָעָא וְאַבְנָא:\",0,0],[4,144,20,33,\"קַיָם אֲנָא אֲמַר יְיָ אֱלֹהִים אִם לָא בְּיַד תַּקִיפָא וּבְדַרְעָא מְרוֹמָם וּבִרְגַז שְׁפִיךְ אֶמְלוֹךְ עֲלֵיכוֹן:\",0,0],[4,144,20,34,\"וְאַפֵּיק יַתְכוֹן מִבֵּינֵי עַמְמַיָא וְאַכְנֵישׁ יַתְכוֹן מִן מְדִינָתָא דְאִתְבַּדַרְתּוּן בְּהוֹן בְּיַד תַּקִיפָא וּבְדַרְעָא מְרוֹמָם וּבִרְגַז שְׁפִיךְ:\",0,0],[4,144,20,35,\"וְאָעֵיל יַתְכוֹן לְמִדְבַּר עַמְמַיָא וְאִתְפְּרַע מִנְכוֹן תַּמָן אַפִּין בְּאַפִּין:\",0,0],[4,144,20,36,\"כְּמָא דְאִתְפְּרָעֵית מִן אֲבָהַתְכוֹן בְּמַדְבְּרָא אַרְעָא דְמִצְרָיִם כֵּן אִתְפְּרַע מִנְכוֹן אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,20,37,\"וַאֲנִיחַ עֲלֵיכוֹן גְזֵירַת דִינִי וְאָעֵיל יַתְכוֹן בְּמַסוֹרֶת קַיָמָא:\",0,0],[4,144,20,38,\"וְאַפְרִישׁ מִנְכוֹן דִי מְרָדוּ וְדִי שַׁקָרוּ בְמֵימְרִי מֵאַרְעָא תוֹתְבוּתְהוֹן אַפֵיק יַתְהוֹן וּלְאַרְעָא דְיִשְׂרָאֵל לָא יַעֲלוּן וְתֵידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,20,39,\"וְאַתּוּן בֵּית יִשְׂרָאֵל כִּדְנַן אֲמַר יְיָ אֱלֹהִים גְבַר פּוּלְחַן טַעֲוָתֵהּ אֱזִילוּ פְלָחוּ וּבָתַר דְתַבְתּוּן לֵיתֵיכוֹן צָבָן לְקַבָּלָא לְמֵימְרִי וְיַת שְׁמָא דְקוּדְשִׁי לָא תַחֲלוּן עוֹד בְּמַתְּנָתֵכוֹן וּבְטַעֲוָתְכוֹן:\",0,0],[4,144,20,40,\"אֲרֵי בְטוּר קוּדְשִׁי בְּטוּר קוּדְשָׁא דְיִשְׂרָאֵל אֲמַר יְיָ אֱלֹהִים תַּמָן יִפְלְחוּן קֳדָמַי כָּל בֵּית יִשְׂרָאֵל כּוּלְהוֹן בְּאַרְעָא חַיַיָא תַּמָן יִתְקַבֵּל קוּרְבָּנֵיהוֹן בִּפְרִיעַ וְתַמָן אֶתְבַּע יַת אַפְרָשׁוּתְכוֹן וְיַת רֵישׁ אַצְוָתְכוֹן בְּכָל קוּדְשֵׁיכוֹן:\",0,0],[4,144,20,41,\"קוּרְבַּן לְרַעֲוָא יִתְקַבֵּל קוּרְבַּנְכוֹן בִּפְרִיעַ כַּד אַפֵּיק יַתְכוֹן מִבֵּינֵי עַמְמַיָא וְאַכְנֵישׁ יַתְכוֹן מִן מְדִינָתָא דְאִתְבַּדַרְתּוּן בְּהָן וְאֶתְקַדֵשׁ בְּכוֹן לְעֵינֵי עַמְמַיָא:\",0,0],[4,144,20,42,\"וְתֵידְעוּן אֲרֵי אֲנָא יְיָ כַּד אָעֵיל יַתְכוֹן לְאַרְעָא דְיִשְׂרָאֵל דִי קַיֵמִית בְּמֵימְרִי לְמִתַּן יָתָהּ לַאֲבָהָתְכוֹן:\",0,0],[4,144,20,43,\"וְתִדְכְּרוּן תַּמָן יַת אוֹרְחָתְכוֹן וְיַת כָּל עוֹבָדֵיכוֹן דְאִסְתַּאַבְתּוּן בְּהוֹן וְתִידַנְקוּן וּתְהוֹן חָזָן בְּכָל בִּישַׁתְכוֹן דַעֲבַדְתּוּן:\",0,0],[4,144,20,44,\"וְתֵידְעוּן אֲרֵי אֲנָא יְיָ כַּד אַעְבֵּיד עִמְכוֹן בְּדִיל שְׁמִי לָא כְאוֹרְחָתְכוֹן בִּישְׁתָא וּכְעוֹבָדֵיכוֹן מְחַבְּלַיָא בֵּית יִשְׂרָאֵל אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,21,1,\"וַהֲוָה פִּתְגָם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,21,2,\"בַּר אָדָם קַבֵּיל נְבוּאָה לְאוֹרַח דָרוֹמָא וְאַלֵיף עַל דָרוֹמָא וְאִתְנְבֵּי עַל חוּרְשָׁא דַחֲקַל דָרוֹמָא:\",0,0],[4,144,21,3,\"וְתֵימַר לְחוּרְשָׁא דְדָרוֹמָא קַבֵּיל פִּתְגָמָא דַייָ כִּדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא מַדְלִיק בָּךְ אֶשְׁתָּא וְתִקְטֵיל בָּךְ כָּל אִילַן יַבִּישׁ לָא תִטְפֵי לְשַׁלְהוֹבִיתָא דִמְשֵׁיצְיָא וְיִתְרַשְׁמוּן בָּהּ כָּל אַפַּיָא מִדְרוֹם לְצִפּוּנָא:\",0,0],[4,144,21,4,\"וְיֶחֱזוּן כָּל בְּנֵי בִסְרָא אֲרֵי אֲנָא יְיָ אַדְלִיקְתָּהּ לָא תִטְפֵי:\",0,0],[4,144,21,5,\"וַאֲמָרֵית קַבֵּיל בָּעוּתִי יְיָ אֱלֹהִים הָא אִינוּן אָמְרִין לִי הֲלָא מַמְתֵיל מַתְלִין הוּא:\",0,0],[4,144,21,6,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,21,7,\"בַּר אָדָם קַבֵיל נְבוּאָה עַל יְרוּשְׁלֵם וְאַלֵיף עַל מַקְדְשִׁין וְאִתְנַבֵּי עַל אַרְעָא דְיִשְׂרָאֵל:\",0,0],[4,144,21,8,\"וְתֵימַר לְאַרְעָא דְיִשְׂרָאֵל כִּדְנַן אֲמַר יְיָ הָא אֲנָא שְׁלַח רוּגְזִי עֲלָךְ וְאַפֵּיק חַרְבִּי מִלִדְנָהּ וְאַגְלֵי מִנִיךְ זַכָּאָךְ בְּדִיל לְשֵׁיצָאָה חַיָבָךְ:\",0,0],[4,144,21,9,\"חֲלַף דְאַגְלֵי מִנִיךְ זַכָּאָךְ בְּדִיל לְשֵׁיצָאָה חַיָבָךְ בְּכֵן תִּפּוֹק חַרְבִּי מִלִדְנָהּ עַל כָּל בִּסְרָא מִדָרוֹם לְצִפּוּנָא:\",0,0],[4,144,21,10,\"וְיֵדְעוּן כָּל בְּנֵי בִּסְרָא אֲרֵי אֲנָא יְיָ אַפְקֵית חַרְבִּי מִלִדְנָהּ לָא תְתוֹב עוֹד:\",0,0],[4,144,21,11,\"וְאַתְּ בַּר אָדָם אִתְאַנַח בְּזִיעַ חַרְצִין וּבְמֶרֶר תִּתְאַנַח לְעֵינֵיהוֹן:\",0,0],[4,144,21,12,\"וִיהֵי אֲרֵי יֵמְרוּן לָךְ עַל מָה אַתְּ מִתְאַנַח וְתֵימַר עַל בְּסוֹרְתָא אֲרֵי אַתְיָא וְיִתְמְסֵי כָּל לֵב וְיִתְרַשְׁלָן כָּל יְדֵין וְתֶעֱמֵי כָל רוּחַ וְכָל רְכוּבַיָא יִתְאַשְׁדָן מַיָא הָא אַתְיָא וְתִתְקַיֵם אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,21,13,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,21,14,\"בַּר אָדָם אִתְנַבֵּי וְתֵימַר כִּדְנַן אֲמַר יְיָ אֱלֹהִים אֲמַר חַרְבָּא דְמַלְכָּא דְבָבֶל תִּקְטוֹל וְחַרְבָּא דִבְנֵי עַמוֹן תִּתְּנֵי וּתְשֵׁיצֵי:\",0,0],[4,144,21,15,\"בְּדִיל לְמִקְטַל קְטוֹל אִשְׁתְּלִיפַת בְּדִיל לְמֶעְבַּד פּוּרְעֲנוּת אִשְׁתַּנִינַת עַל דְחָדִיאוּ שִׁבְטָא דְבֵית יְהוּדָה וּבִנְיָמִין לְשִׁבְטֵי יִשְׂרָאֵל כַּד גְלוֹ עַל דִפְלָחוּ לְטַעֲוָתָא וְתָבוּ אִינוּן לְמִטְעֵי בָּתַר צַלְמֵי אָעַיָא:\",0,0],[4,144,21,16,\"וִיהַב פּוּרְעֲנוּתְהוֹן לְאִתְמַסְרָא בְּיַד מַלְכָּא דְבָבֶל הִיא מְחַת חַרְבָּא תְּהֵי פּוּרְעֲנוּתְהוֹן לְמִמְסַר יַתְהוֹן בְּיַד קָטוֹלִין:\",0,0],[4,144,21,17,\"צְוַח וְאַיְלֵיל בַּר אָדָם אֲרֵי הִיא הֲוַת בְּעַמִי הִיא וְכָל רַבְרְבֵי יִשְׂרָאֵל קְטוֹלֵי חַרְבָּא אִתְכַּנְשׁוּ וְאָתוּ עַל עַמִי מִסְחוֹר סְחוֹר בְּכֵן טְפַח עַל יַרְכָא:\",0,0],[4,144,21,18,\"אֲרֵי אִתְנַבִּיאוּ עֲלֵיהוֹן נְבִיָא וְלָא תָבוּ וּמָה יְהֵי בְסוֹפֵיהוֹן אֱמַר וְאַף שִׁבְטָא דְבֵית יְהוּדָה וּבִנְיָמִין מִגְלָא יַגְלוּן וּבְעוֹבְדֵיהוֹן בִּישַׁיָא לָא יִתְקַיְמוּן אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,21,19,\"וְאַתְּ בַּר אָדָם אִתְנַבֵּי וּטְפַח יַד עַל יַד וְתִתְכְּפֵיל חַרְבָא תְלִיתָאָה חֲרַב קְטוֹלִין הִיא חֲרָב פּוּרְעֲנוּת קְטוֹלָא רַבָּא דִמְזִיעָא לְהוֹן:\",0,0],[4,144,21,20,\"בְּדִיל לְמִתְבַּר לִבְּהוֹן וּלְאַסְגָאָה מַתְקַלְהוֹן עַל כָּל קִרְוֵיהוֹן מַנִיתִי קָטְלֵי חַרְבָּא וֵי חַרְבָּא אִשְׁתְּלִיפַת לְמִקְטֵל אִשְׁתְּנִינִת לְשֵׁיצָאָה:\",0,0],[4,144,21,21,\"אִשְׁתְּלִיפִי וּקְטִילִי מִדָרוֹמָא וְשֵׁיצֵי מִן צִפוּנָא לְאָן אַפָּךְ מְזַמְנִין:\",0,0],[4,144,21,22,\"וְאַף אֲנָא אַיְתֵי פּוּרְעֲנוּת עַל פּוּרְעֲנוּת וַאֲנִיחַ חֵימְתִי אֲנָא יְיָ גְזַרֵית בְּמֵימְרִי:\",0,0],[4,144,21,23,\"וַהֲוָה פִּתְגָם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,21,24,\"וְאַתְּ בַּר אָדָם אַתְקִין לָךְ תַּרְתֵּין אוֹרְחָן דְיֵיתוּן בְּהוֹן קְטוֹלֵי חַרְבָּא דְמַלְכָּא דְבָבֶל מִמְדִינְתָא הֲדָא יִפְקוּן תַּרְוֵיהוֹן וְאַתְרָא אַתְקִין בְּרֵישׁ פְּרָשׁוּת אוֹרַח קַרְתָּא אַתְרָא אַתְקֵין:\",0,0],[4,144,21,25,\"אוֹרְחָא אַתְקֵין דְיֵיתוּן בָּהּ קְטוֹלֵי חַרְבָּא מֵרַבַּת בְּנֵי עַמוֹן וְעַל דְבֵית יְהוּדָה דִי נְפַקוּ מִירוּשְׁלֵם לְמֵיתַב בְּקִרְוִין כְּרִיכָן:\",0,0],[4,144,21,26,\"אֲרֵי קָם מַלְכָּא דְבָבֶל עַל אֵם פְּרָשׁוּת אוֹרַח בְּרֵישׁ תַּרְתֵּין אוֹרַח לְמִקְסָם קָסֶם קְשַׁת בְּגִרְרַיָא שָׁאַל בְּצַלְמְנַיָא חֲזָא בְּכַבְדָא:\",0,0],[4,144,21,27,\"בִימִינֵיהּ הֲוָה קִסְמָא נָפִיל לִמְהַךְ לִירוּשְׁלֵם לְמַנְאָה אָפְרוּרְוָן לְפַתָּרָא תַרְעִין דְיַעֲלוּן בְּהוֹן קָטוֹלִין לַאֲרָמָא קַל בְּאַצְוָחַת קַרְנָא לְמַנְאָה אָפְרוּרְוָן עַל תַּרְעֵן לְמִצְבַּר מִלַיְתָא וּלְמִבְנֵי כַרְקוֹם:\",0,0],[4,144,21,28,\"וַהֲוָה לְהוֹן קִסוּמֵיהוֹן כַּדִיבִין בְּעֵינֵיהוֹן נַחֲשִׁין דַהֲוָה מְנַחַשׁ לְהוֹן וְאִינוּן לָא יָדְעִין דְאַרְבְּעִין וּתְשַׁע זַמְנִין הֲוָה כְמַן וּמִתְּתֵיב עַל פִּתְגָמָא עַד דְתֵיתֵי לֵיהּ שַׁעְתָּא דְיִתְמַסְרוּן בִּידֵיהּ:\",0,0],[4,144,21,29,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים חֲלַף דְאַדְכַּרְתּוּן חוֹבֵיכוֹן בְּאִתְגְלָאָה מְרָדֵיכוֹן לְאִתְחֲזָאָה חֶטְאֵיכוֹן בְּכֹל עוֹבָדֵיכוֹן חֲלַף דְאַדְכַּרְתּוּן בְּיַד מַלְכָּא דְבָבֶל תִּתְמַסְרוּן:\",0,0],[4,144,21,30,\"וְאַתְּ חַיָב קְטָלָא רַשִׁיעָא רַבָּא דְיִשְׂרָאֵל דִמְטָא יוֹם תַּבְרֵיהּ עִדַן תּוּשְׁלְמַת חוֹבוֹהִי:\",0,0],[4,144,21,31,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים אַעְדֵי מִצְנָפְתָּא מִשְׁרָיָה כַּהֲנָא רַבָּא וַאֲבַטֵיל כִּתְרָא מִצִדְקִיָה מַלְכָּא אֲמַר דֵין וְדֵין בְּאַתְרֵיהּ לָא יִתְקַיֵם מִגְלָא יִגְלוֹן גְדַלְיָה בַּר אֲחִיקָם דְלָא הֲוָה דִילֵיהּ יִסְבִינָהּ וְצִדְקִיָה דְדִילֵיהּ הִיא תַּעְדֵי מִנֵיהּ:\",0,0],[4,144,21,32,\"חוֹבֵיהוֹן דְחָבוּ כְּחוֹבֵיהוֹן אֶתְפְּרַע מִנְהוֹן אַף לְדֵין לָא יִתְקַיֵם לֵיהּ עַד דְאַיְתֵי עֲלוֹהִי פּוֹרְעֲנוּת יִשְׁמָעֵאל בַּר נְתַנְיָה וְאֶמְסְרִינֵיהּ בִּידֵיהּ:\",0,0],[4,144,21,33,\"וְאַתְּ בַּר אָדָם אִתְנַבֵּי וְתֵימַר כִּדְנַן אֲמַר יְיָ אֱלֹהִים עַל בְּנֵי עַמוֹן וְעַל חִסוּדֵיהוֹן וְתֵימַר חַרְבָּא חַרְבָּא אִשְׁתַּלְפַת לְמִקְטַל אִשְׁתַּנִינַת לְשֵׁיצָאָה בְּדִיל לְמֶהֱוֵי לָהּ צַחְצוּחִין:\",0,0],[4,144,21,34,\"בְּאִתְנַבָּאָה לָךְ שְׁקַר בְּאַלְפָא לָךְ כִּדְבָן לְמִמְסַר יַת צַוְרָךְ כְּצַוְרֵי קְטִילֵי רַשִׁיעַיָא דִמְטָא יוֹם תְּבִירְהוֹן עִדַן סְעוּרַן בִּישַׁתְהוֹן:\",0,0],[4,144,21,35,\"אֲתִיב חַרְבָּא לִנְדָנָהּ בְּאַתְרָא דְאִתְבְּרֵיתוּן בַּאֲרַע תּוֹתָבוּתְכוֹן אֶתְפְּרַע מִנְכוֹן:\",0,0],[4,144,21,36,\"וְאֶשְׁפּוֹךְ עֲלָךְ חֵימָתִי בְּאֵשַׁת פּוּרְעֲנוּתִי אַתְקֵיף עֲלָךְ וְאֶמְסְרִינָךְ בְּיַד גִבָּרִין רַשִׁיעִין דְאוֹמָנִין לְחַבָּלָא:\",0,0],[4,144,21,37,\"לְעַמָמַיָא דְתַקִיפִין כְּאֶשְׁתָּא תִּתְמָסְרוּן לְאִשְׁתֵּיצָאָה חוֹבַת קְטוֹלָךְ תְּהֵי בְגוֹ אַרְעָא לָא יֵעוּל דָכְרָנִיךְ אֲרֵי אֲנָא יְיָ גְזֵרִית בְּמֵימְרִי:\",0,0],[4,144,22,1,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,22,2,\"וְאַתְּ בַּר אָדָם הֲתוֹכַח הֲתוֹכַח יַת קַרְתָּא דְאִשְׁדֵי דַם זַכַּאי בְּגַוָהּ וְחַוֵי לָהּ יַת כָּל תּוֹעֲבָתָהָא:\",0,0],[4,144,22,3,\"וְתֵימַר כִּדְנַן אֲמַר יְיָ אֱלֹהִים קַרְתָּא דְאַשְׁדֵי דַם זַכַּאי בְּגַוָהּ מְטָא עִדַן תַּבְרָהּ וּדְפָלְחִין לְטַעֲוָתָא בְגַוָהּ בְּדִיל לְסַאֲבוּתָא:\",0,0],[4,144,22,4,\"בְּחוֹבַת דַם זַכַּאי דִאַשַׁדְתְּ חַבְתְּ וּבְּפוּלְחָן טַעֲוָתֵךְ דִפְלַחְתְּ אִסְתַּאַבְתְּ וְקָרֵיב יוֹם תַּבְרִיךְ וּמְטָא עִדַן בִּישְׁתִּיךְ עַל כֵּן יְהַבְתִּיךְ חִסוּדִין לְעַמְמַיָא וּלְעֵיב לְכָל מִדִינָתָא:\",0,0],[4,144,22,5,\"דְקָרִיבִין וְדִרְחִיקִין מִנִיךְ יִתְלַעֲבוּן בִּיךְ סוֹאֲבַת שְׁמָא דְסַגִיאִין אִתְרְגוּשְׁתָּהָא:\",0,0],[4,144,22,6,\"הָא רַבְרְבֵי יִשְׂרָאֵל גְבַר לְתוּקְפֵיהּ הֲווֹ בִיךְ בְּדִיל לְמִשְׁפַּךְ דַם זַכַּאי:\",0,0],[4,144,22,7,\"אַבָּא וְאִמָא אָקִילוּ בָךְ לְגִיוֹרָא אֲנִיסוּ אוֹנְסָא בְּגַוִיךְ יַתְמִין וְאַרְמְלָן אוֹנִיאוּ בִיךְ:\",0,0],[4,144,22,8,\"עַל קוּדְשֵׁי בִּסַרְתְּ וְיַת יוֹמֵי שַׁבַּיָא דִילִי אָחֵילְתְּ:\",0,0],[4,144,22,9,\"גַבְרֵי אָכְלֵי קוּרְצָא הֲיוֹ בִיךְ בְּדִיל לְמִשְׁפַּךְ דַם זַכַּאי וּבְטוּרַיָא פְלָחוּ בִיךְ לְטַעֲוָתָא אֲרֵי עֵיצַת חֶטְאִין עֲבָדוּ בְגַוִיךְ:\",0,0],[4,144,22,10,\"עֶרְיַת אַבָּא גַלִיאוּ בִּיךְ אִתָּא טוּמְאָה עֵנִיאוּ בִיךְ:\",0,0],[4,144,22,11,\"וּגְבַר יַת אִתַּת חַבְרֵיהּ עֲבַד תּוֹעֵיבָא וּגְבַר יַת כַּלָתֵיהּ סָאֵיב בְּעֵיצַת חֶטְאִין וּגְבַר יַת אֲחָתֵיהּ בַת אֲבוּהִי עַנֵי בִיךְ:\",0,0],[4,144,22,12,\"שׁוֹחֲדָא קַבִּילוּ בִיךְ בְּדִיל לְמִשְׁפַּךְ דַם זַכַּאי חִבּוּלְיָא וְרִבִּיתָא נְסֵיבְתְּ וְאַהֲנֵית רְחִימָךְ בְּאוּנְסָא וּפּוּלְחָנִי שְׁבַקְתְּ אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,22,13,\"וְהָא אַיְתֵיתִי פּוּרְעֲנוּתִי עֲלָךְ בְּחוֹבֵי מָמוֹן אוֹנְסִיךְ דַאֲנַסְתְּ וְעַל דַם זַכַּאי דְאִשְׁתְּפִיךְ בְּגַוִיךְ:\",0,0],[4,144,22,14,\"הֲיִתְקַף לִבִּיךְ אִם יִתְחַסְנָן יְדֵיךְ לְיוֹמַיָא דַאֲנָא עֲתִיד לְמֶעְבַד עִמָךְ אֲנָא יְיָ גְזָרֵית בְּמֵימְרִי וַאֲקַיֵם:\",0,0],[4,144,22,15,\"וְאַגְלֵי יָתִיךְ לְבֵינֵי עַמְמַיָא וְאַבַדְרִינָךְ בִּמְדִינָתָא וַאֲסִיף סְאוֹבְתִּיךְ מִנֵיךְ:\",0,0],[4,144,22,16,\"וְאֶתְקַדֵשׁ בִּיךְ לְעֵינֵי עַמְמַיָא וְתֵידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,22,17,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,22,18,\"בַּר אָדָם הֲווֹ קֳדָמַי בֵּית יִשְׂרָאֵל לִפְסוּלָא כּוּלְהוֹן כְּמָא דִמְעָרַב נְחַשׁ וּבְעִיץ וּבַרְזֶל וַאֲבַר בְּגוֹ כוּרָא לִפְּסוֹלַת כַּסְפָּא הֲווֹ:\",0,0],[4,144,22,19,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים חֲלַף דַהֲוֵיתוּן כּוּלְכוֹן לִפְסוּלָא בְּכֵן הָא אֲנָא כָנֵישׁ יַתְכוֹן לְגוֹ יְרוּשְׁלֵם:\",0,0],[4,144,22,20,\"כְּמַכְנֵשׁ כְּסַף וּנְחַשׁ וּבַרְזְלָא וַאֲבַר וּבְעִיץ לְגוֹ כוּרָא לְאַתְקָפָא עֲלוֹהִי נוּרָא לְאַמְסָיוּתֵיהּ כֵּן אַכְנֵשׁ בְּרוּגְזִי וּבְחֵימְתִי וְאָסֵיף וֶאֱשֵׁיצֵי יַתְכוֹן:\",0,0],[4,144,22,21,\"וְאַכְנֵישׁ יַתְכוֹן וְאַתְקֵיף עֲלֵיכוֹן בְּאֶשְׁתָּא פּוּרְעֲנוּתִי וְתִתְמְסוּן בְגַוָהּ:\",0,0],[4,144,22,22,\"כְּאִתְמְסָאָה כְסַף בְּגוֹ כוּרָא כֵּן תִּתְמְסוּן בְּגַוָהּ וְתִידְעוּן אֲרֵי אֲנָא יְיָ שְׁפִיכֵית חֵימְתִי עֲלֵיכוֹן:\",0,0],[4,144,22,23,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,22,24,\"בַּר אָדָם אֲמַר לָהּ אַתְּ אַרְעָא דְיִשְׂרָאֵל אַרְעָא לָא מִדַכְיָא הִיא וְלָא אִתְעֲבִידוּ בָּהּ עוֹבָדִין טָבִין דְיִגְנוּן עֲלָהּ בְּיוֹם לְוָט:\",0,0],[4,144,22,25,\"סִיעַת סַפְרָהָא בְּגַוָהּ כְּאַרְיְוָן נָהֲמִין לְמִקְטַל קְטוֹל אֱנָשָׁא קְטָלוּ עוֹתֵר וִיקָר נְסִיבוּ אַרְמַלְתָּהָא אַסְגִיאוּ בְּגַוָהּ:\",0,0],[4,144,22,26,\"כַּהֲנָהָא חָטְפִין בְּאוֹרַיְתִי וּמַפְסִין קֳדָשַׁי בֵּין קוּדְשָׁא לְחוֹלָא לָא אַפְרִישׁוּ וּבֵין מְסַאֲבָא לְדַכְיָא לָא הוֹדִיעוּ וּמִיוֹמֵי שַׁבַּיָא דִילִי כְבָשׁוּ עֵינֵיהוֹן וְחַלַת רְעוּתִי בֵּינֵיהוֹן:\",0,0],[4,144,22,27,\"רַבְרְבָהָא בְגַוָהּ כַדִיבִין חָטְפֵי חֲטוֹף לְמִשְׁפַּךְ דַם זַכַּאי לַאֲבָדָא נַפְשָׁן בְּדִיל לְקַבָּלָא מָמוֹן דִשְׁקַר:\",0,0],[4,144,22,28,\"וּנְבִיֵי שִׁקְרָא דִי בְגַוָה דָמָן לִדְבָנֵי מְחִיצָא וְשָׁעֵיעַ לֵיהּ טִין פַטִיר דְלָא תֶּבֶן מִתְנַבַּן שְׁקַר וּמַלְפִין לְהוֹן כַּדְבִין אָמְרִין כִּדְנַן אֲמַר יְיָ אֱלֹהִים וּמִן קֳדָם יְיָ לָא אִתְמַלָל:\",0,0],[4,144,22,29,\"עַמָא דְאַרְעָא עֲשָׁקוּ עוּשְׁקָא וּגְזָלוּ גְזֵלָה וּמִסְכֵּן וַחֲשִׁיךְ אוֹנִיאוּ וּלְגִיוֹרָא אֵנָסוּ בְּלָא כִדְחֲזֵי:\",0,0],[4,144,22,30,\"וְאֶתְבַּע מִנְהוֹן קֳדָמַי גְבַר דְלֵיהּ עוֹבָדִין טָבִין דִיקוּם בְּתִרְעֲתָא קֳדָמַי וְיִבְעֵי רַחֲמִין עַל עַמָא דְאַרְעָא בְּדִיל דְלָא לְחַבָּלוּתָא וְלָא אַשְׁכְּחֵית:\",0,0],[4,144,22,31,\"וּשְׁפִיכֵית עֲלֵיהוֹן חֵימְתִי בְּאֶשַׁת פּוּרְעָנוּתִי שֵׁיצִיתִינוּן פּוּרְעֲנוּת אוֹרְחֵיהוֹן בְּרֵישֵׁיהוֹן יְהָבֵית אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,23,1,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,23,2,\"בַּר אָדָם אִתְנַבֵּי עַל תַּרְתֵּין מְדִינָן דְאִינוּן כְּתַרְתִּין נְשִׁין דִי בְנַת אִמָא חֲדָא הֲוָאָה:\",0,0],[4,144,23,3,\"וְטַעֲאָה בְמִצְרַיִם בָּתַר פּוּלְחַן טַעֲוָתְהוֹן טִעֲאָה תַּמָן פַּלְחָא לְטַעֲוָתָא וְתַמָן קִלְקְלָא עוֹבְדֵיהֶן:\",0,0],[4,144,23,4,\"וּשְׁמָהָתְהֶן אָהֳלָה רַבְּתָא וְאָהָלִיבָה אֲחָתָהּ וַהֲוָאָה מְשַׁמְשָׁן קָדָמַי וְאַצְלְחָא בִּבְנִין וּבְנָן וּשְׁמָהָתְהֶן שׁוֹמְרוֹן אָהֳלָה וִירוּשְׁלֵם אָהֳלִיבָה:\",0,0],[4,144,23,5,\"וּטְעַת אָהֳלָה מִבָּתַר פוּלְחָנִי וְאִתְרְעִיאַת לְמִטְעֵי בָתַר רְחִימָהָא בָּתַר בְּנֵי אַתּוּר קָרִיבָהָא:\",0,0],[4,144,23,6,\"לְבוּשֵׁי גְמִיר שִׁלְטוֹנִין וְטוּרָנִין עוּלֵימֵי חֶמְדָתָא כּוּלְהוֹן פָּרָשִׁין רָכְבֵי סוּסְוָן:\",0,0],[4,144,23,7,\"וְאִתְרְעִיאַת לְמִטְעֵי בַתְרֵיהוֹן עוּלֵימֵי בְנֵי אַתּוּר כוּלְהוֹן וּבְכָל דְאִתְרְעִיאַת בְּכָל פּוּלְחַן טַעֲוָתְהוֹן אִסְתַּאֲבָת:\",0,0],[4,144,23,8,\"וְיַת פּוּלְחַן טַעֲוָתָא דַהֲוָה עִמָהּ מִמִצְרַיִם לָא שַׁבְקַת אֲרֵי יָתָהּ אַפְלָחוּ לְטַעֲוָתָהּ וְאִינוּן אַלִפוּהָא עוֹבָדִין בִּישִׁין וּשְׁפָכוּ טַעֲוָתְהוֹן עֲלָהּ:\",0,0],[4,144,23,9,\"בְּכֵן מְסַרְתִיהָא בְּיַד רְחִימָהָא בְּיַד בְּנֵי אַתּוּוּן דְאִתְרְעִיאַת לְמִטְעֵי בַתְרֵיהוֹן:\",0,0],[4,144,23,10,\"אִינוּן גַלִיאוּ קְלָנָהּ בְּנָהָא וּבְנָתָהָא שְׁבוֹ וְעַמָהּ בְּחַרְבָּא קְטִילוּ וַהֲוַת שׁוּם לִמְדִינָתָא וּפוּרְעֲנוּת דִינִין עֲבָדוּ בְּגַוָהּ:\",0,0],[4,144,23,11,\"וַחֲזַת אֲחָתָהּ אָהֳלִיבָה וְחַבִּילַת רְחִימְתָּא מִנָהּ וְיַת טַעֲוָתָהָא מִטַעֲוַת אֲחָתָהּ:\",0,0],[4,144,23,12,\"בָּתַר בְּנֵי אַתּוּר אִתְרְעִיאַת לְמִטְעֵי שִׁלְטוֹנִין וְטוּרְנִין קָרִיבִין לְבוּשֵׁי גְמַר וּפָרָשִׁין רָכְבֵי סוּסְוָן עוּלֵימֵי חֶמְדָתָא כּוּלְהוֹן:\",0,0],[4,144,23,13,\"וּגְלֵי קֳדָמֵי אֲרֵי אִסְתַּאֲבַת אוֹרְחָא חֲדָא שַׁוִי לְתַרְתֵּיהֶן:\",0,0],[4,144,23,14,\"וְאוֹסִיפַת עַל טַעֲוָתָהּ וַחֲזַת גַבְרִין מְצַיְרִין עַל כָּתְלָא צַלְמֵי כַסְדָאֵי מְצַיְרִין בְּסַמְמָנַיָא:\",0,0],[4,144,23,15,\"אֲסִירִין זַרְזִין בְּחַרְצֵיהוֹן מָחֲתִין קוּלְסִין בְּרֵישֵׁיהוֹן חֵיזוּ גִבָּרִין כּוּלְהוֹן דְמוּת בְּנֵי בָבֶל מְדִינַת כַּסְדָאֵי אֲרַע יַלְדוּתְהוֹן:\",0,0],[4,144,23,16,\"וְאִתְרְעִיאַת לְמִיטְעֵי בַתְרֵיהוֹן בָּתַר חֵיזוּ עֵינָהָא וּשְׁלָחַת אִזְגַדִין לְוַתְהוֹן לִמְדִינַת אֲרַע כַּסְדָאֵי:\",0,0],[4,144,23,17,\"וַאֲתוֹ לְוָתָהּ בְּנֵי בָבֶל לְמֶעְבַּד רַחֲמוּ וְסָאִיבוּ יָתָהּ בְּטַעֲוָתְהוֹן וְאִסְתַּאֲבַת בְּהוֹן עַד דְקָצַת נַפְשָׁהּ בְּהוֹן:\",0,0],[4,144,23,18,\"וְאִתְגְלִיאַת בַּהֲתָתָהּ וְאִתְחַזֵי קְלָנָהּ וְרַחֵיק מֵימְרִי יָתָהּ כְּמָא דְרָחֵיק מֵימְרִי יַת אֲחָתָהּ:\",0,0],[4,144,23,19,\"וְאַסְגִיאַת יַת טַעֲוָתָהּ לְאַדְכָּרָא יַת יוֹמִין דְמִלְקָדְמִין דִטְעַת בְּהוֹן כַּד הֲוַת בְּאַרְעָא דְמִצְרַיִם:\",0,0],[4,144,23,20,\"וְאִתְרְעִיאַת לְמֶהֱוֵי שְׁמוֹטָא לְהוֹן דִבְסַר חֲמָרִין בִּסְרֵיהוֹן וְצַחֲנַת סוּסְוָן צַחֲנַתְהוֹן:\",0,0],[4,144,23,21,\"וְאַדְכַּרְתְּ יַת חוֹבֵי עֲצַת חֶטְאָךְ דְמִלְקַדְמִין בְּמַעְבְּדִיךְ מִמִצְרַיִם רְחִימוּ בְּדִיל חֶטְאֵי יַנְקוּתִיךְ:\",0,0],[4,144,23,22,\"בְּכֵן אָהֳלִיבָה כִּדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא מַיְתֵי בִּגְלֵי יַת רְחִימָךְ עֲלָךְ יַת דְקָצַת נַפְשִׁיךְ בְּהוֹן וְאַיְתִינוּן עֲלָךְ מִסְחוֹר סְחוֹר:\",0,0],[4,144,23,23,\"בְּנֵי בָבֶל וְכָל כַּסְדָאֵי פְּקוּדָאֵי וְשׁוֹעָאֵי וְקוֹעָאֵי כָּל בְּנֵי אַתּוּר עִמְהוֹן עוּלֵימֵי חֶמְדָתָא שִׁלְטוֹנִין וְטוּרָנִין כּוּלְהוֹן גִבָּרִין מְזַמְנִין רָכְבֵי סוּסְוָן כּוּלְהוֹן:\",0,0],[4,144,23,24,\"וְיֵיתוּן עֲלָךְ בְּמָאנֵי זְיָנָא בִּרְתִיכִין וְגַלְגַלִין וּמַשִׁרְיַת עַמְמִין דִמְזַיְנִין בַּעֲגִילִין וְקוּלְסִין יְמַנוּן עֲלָךְ סְחוֹר סְחוֹר וְאֶתֵּן קֳדָמֵיהוֹן פּוּרְעֲנוּת דִינִין וְיִתְפְּרָעוּן מִנִיךְ בְּנִימוּסֵיהוֹן:\",0,0],[4,144,23,25,\"וְאֶתֵּן פּוּרְעֲנוּתִי בִּיךְ וְיִתְפַּרְעוּן מִנִיךְ בִּרְגַז רַבְרְבַיִךְ וְיַקִירַיִךְ יִגְלוֹן וְעַמִיךְ בְּחַרְבָּא יִתְקַטְלוּן אִינוּן בְּנָךְ וּבְנָתָךְ יִשְׁבּוּן וּשְׁפַר אַרְעִיךְ יִתּוֹקַד בְּנוּרָא:\",0,0],[4,144,23,26,\"וִישַׁלְחוּנִיךְ לְבוּשֵׁי יְקָרִיךְ וְיִסְבוּן מָאנֵי תוּשְׁבַּחְתִּיךְ:\",0,0],[4,144,23,27,\"וַאֲבַטֵל חוֹבֵי עֲצַת חֶטְאָךְ מִנִיךְ וְיַת פּוּלְחַן טַעֲוָתִיךְ דַהֲוַת עִמִיךְ כַּד הֲוֵית בְּאַרְעָא דְמִצְרַיִם וְלָא תִזְקְפִין עַיְנָךְ לְהוֹן וְטַעֲוַת מִצְרָאֵי לָא תִדְכְּרִין עוֹד:\",0,0],[4,144,23,28,\"אֲרֵי כִדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא מָסַר לִיךְ בְּיַד דִסְנֵית בְּיַד דְקָצַת נַפְשִׁיךְ בְּהוֹן:\",0,0],[4,144,23,29,\"וְיִתְפָּרְעוּן מִנִיךְ כִּדְבָבוּ וְיִסְבוּן יַת כָּל לֵיאוּתִיךְ וְיִשְׁבְּקוּנִיךְ מְטַלְטְלָא וּשְׁבִיקָא וְתִתְגְלֵי בַהֲתַת טְעוּתִיךְ וְחוֹבֵי עֵיצַת חֶטְאָךְ וּזְדוֹנִיךְ:\",0,0],[4,144,23,30,\"חוֹבַיִךְ גְרָמוּ אִלֵין לִיךְ בִדְטָעֵית בָּתַר עַמְמַיָא וְאִסְתְּאַבְתְּ בְּפוּלְחַן טַעֲוָתְהוֹן:\",0,0],[4,144,23,31,\"בְּאוֹרַח אֲחָתִיךְ הַלֵיכְתְּ וְאֶתֵּן כָּס פּוּרְעֲנוּתָהּ בִידִיךְ:\",0,0],[4,144,23,32,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים כָּס פּוּרְעֲנוּת אֲחָתֵיךְ תִּשְׁתִּין תַּקִיפָא וַחֲסֵינְתָּא תְּהִין לְחוֹךְ וְלִלְעֵיב מִסְגֵי עָקָא דְתֵיתֵי עֲלָךְ:\",0,0],[4,144,23,33,\"הָא כְרַוְיָא וְרַוָן תִּתְמְלִין כָּס צָדוּ וְאִישְׁתֵּמָמוּ כָּס פּוּרְעֲנוּת אֲחָתִיךְ שׁוֹמְרוֹן:\",0,0],[4,144,23,34,\"וְתִשְׁתִּין יָתָהּ וְתִגְמְרִין וְיַת פוּרְעֲנוּתָהָא תְקַבְּלִין וּבִסְרִיךְ תִּתְלְשִׁין אֲרֵי אֲנָא גְזָרֵית בְּמֵימְרִי אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,23,35,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים חֲלַף דִשְׁבַקְתָּ פּוּלְחָנִי וְאַרְחֵיקְתְּ דְחַלְתִּי מִקָבֵל עֵינָךְ וְאַף אַתְּ קַבִּילִי חוֹבֵי עֵיצַת חֶטְאִיךְ וְטַעֲוָתַיִךְ:\",0,0],[4,144,23,36,\"וַאֲמַר יְיָ לִי בַּר אָדָם הֲתוֹכַח יַת אָהֳלָה וְיַת אָהֳלִיבָה וְחַוֵי לְהֶן יַת תּוֹעֶבָתְהָן:\",0,0],[4,144,23,37,\"אֲרֵי זַנָאִין בְּהֶן וְדַם זַכַּאי אֲשָׁדוּ בִידֵיהֶן וּבָתַר פוּלְחַן טַעֲוַתְהֶן טְעוֹ וְאַף יַת בְּנֵיהֶן דַעֲתִידִין לְמִיפַּק מִנְהֶן תּוּלְדַת קוּדְשָׁא קֳדָמַי אַעֲבִירוּ לְהֵן לְפוּלְחַן:\",0,0],[4,144,23,38,\"עוֹד אַרְגִיזוּ קֳדָמַי סָאִיבוּ יַת בֵּית מַקְדְשִׁי בְּיוֹמָא הַהוּא וְיַת יוֹמֵי שַׁבַּיָא דִילִי אָחִילוּ:\",0,0],[4,144,23,39,\"וּבְמִכְסוּתְהֶן יַת בְּנֵיהוֹן לְפוּלְחַן טַעֲוַתְהוֹן וְעָלוּ לְבֵית מַקְדְשִׁי בְיוֹמָא הַהוּא לְאָחָלוּתֵיהּ וְהָא כְדֵין עֳבָדוּ בְּגוֹ בֵּית מַקְדְשֵׁי:\",0,0],[4,144,23,40,\"וְאַף אֲרֵי שְׁלַחְתְּ לְגַבְרַיָא דְאָתָן מֵרָחִיק דְאִזְגַד שְׁלִיחַ לְוַתְהוֹן וְהָא אֲתוֹ לַאֲתַר דְזַמִינְתְּ אַתְקִינְתְּ שׁוּקִין וּמַנִית פַּלְטוֹרִין:\",0,0],[4,144,23,41,\"וּרְמֵית דַרְגְשִׁין מַכִּיכִין דִיקַר וּפְתוֹרִין מְלַן כָּל טוּב סִדַרְתְּ קֳדָמֵיהוֹן וּקְטוֹרֶת בּוּסְמִי וּמִשְׁחִי שַׁוֵית עֲלֵיהוֹן:\",0,0],[4,144,23,42,\"וְקַל אִתְרְגוּשְׁתְּהוֹן דִי שְׁלַן שְׁלֵיוָא בְהוֹן וְלִתְקוֹף גִבָּרִין מִסְגֵי אֱנָשָׁא אָתָן מִסְחוֹר סְחוֹר מִמַדְבְּרָא וִיהָבוּ שֵׁירִין עַל יְדֵיהוֹן וְכֶתֶר דְתוּשְׁבְּחָתָא עַל רֵישֵׁיהוֹן:\",0,0],[4,144,23,43,\"וַאֲמָרֵית לִכְנִשְׁתָּא דְיִשְׂרָאֵל דִבְלִיעַת עַמָה בְּחוֹבִין כְּעַן תִּשְׁבוֹק מִטַעֲוָתָהּ וּתְתוּב לְפוּלְחָנִי וְלָא תָבָת:\",0,0],[4,144,23,44,\"וְעָלוּ לְוָתָהּ כְּמָא דְעָלִין לְוַת אִיתְּתָא פּוּנְדְקִיתָא כֵּן עָלוּ לְאָהֳלָה וּלְאָהֳלִיבָה מְזִינְתָא דְעֵיצַתְהוֹן חֶטְאִין:\",0,0],[4,144,23,45,\"וְגַבְרִין זַכָּאִין בְּקִבְלֵיהוֹן יִתְפָּרְעוּן מִנְהֶן פּוּרְעֲנוּת נַיָפִין וּפוּרְעֲנוּת אַשְׁדַת דַם אֲרֵי זַנְאִין בְּהֶן וְדַם זַכַּאִי אֲשָׁדוּ בִּידֵיהוֹן:\",0,0],[4,144,23,46,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים אִיתְנַבֵּי דְיִסְקוּן עֲלֵיהוֹן מַשִׁרְיָן וְאֶמְסַר יַתְהוֹן לִתְבִיר וּלְבִזָא:\",0,0],[4,144,23,47,\"וְיִרְגְמוּ יַתְהֶן בְּאַבְנֵי קָלַע מַשִׁרְיָן וְיִבְזְעוּן יַתְהֶן בְּסַיְפֵיהוֹן בְּנֵיהוֹן וּבְנָתְהוֹן יִקְטְלוּן וּבָתֵּיהוֹן יוֹקְדוּן בְּנוּרָא:\",0,0],[4,144,23,48,\"וַאֲבַטֵיל חוֹבֵי עֵיצַת חֶטְאִין מִן אַרְעָא וְיִתְרַדְיָן כָּל מְדִינְתָא וְלָא יַעְבְּדָן כְּעֵיצַת חֲטָאֵיכוֹן:\",0,0],[4,144,23,49,\"וְיִתְיַהֲבוּן חוֹבֵי עֵיצַת חֶטְאֵיכוֹן עֲלֵיכוֹן וְחֶטְאֵי פּוּלְחַן טַעֲוַתְכוֹן תְּקַבְּלָן וְתֵידְעוּן אֲרֵי אֲנָא יְיָ אֱלֹהִים:\",0,0],[4,144,24,1,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי בְּשַׁתָּא תְשִׁיעֵיתָא בְּיַרְחָא עֲשִׂירָאָה בְּעַסְרָא לְיַרְחָא לְמֵימָר:\",0,0],[4,144,24,2,\"בַּר אָדָם כְּתַב לָךְ יַת שׁוּם יוֹמָא יַת כְּרַן יוֹמָא הָדֵין סְמַךְ מַלְכָּא דְבָבֶל עַל יְרוּשְׁלֵם בִּכְרַן יוֹמָא הָדֵין:\",0,0],[4,144,24,3,\"וְאִתְנַבֵּי לְעַמָא סַרְבָנָא נְבוּאָה וְתֵימַר לְהוֹן כִּדְנַן אֲמַר יְיָ אֱלֹהִים אִתְנַבֵּי דְיִסְקוּן מַשִׁרְיָן עַל קַרְתָּא הָדָא וְאַף יִתְיְהֵיב לָהּ אַרְכָא לְקַבָּלָא מְצִירָא:\",0,0],[4,144,24,4,\"כְנוֹשׁ רַבִרְבָהָא לְגַוָהּ כָּל גְבַר עָבֵיד קְרָב מַשִׁרְיַת עַמְמִין מַלֵי יָתָהּ:\",0,0],[4,144,24,5,\"מַלְכֵי עַמְמִין קָרִיב וְאַף טַקֵיס סוּמְכְוָתָהָא עִמְהוֹן אַבַּע זִמְנָהּ אַף יִתְרְמוֹן קְטִילָהָא בְּגַוָהּ:\",0,0],[4,144,24,6,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים וַי עַל קַרְתָּא דְאָשְׁדֵי דָם זַכַּאי בְּגַוָהּ דְהִיא כְדוּדָא דְזִיהוּמְתֵּיהּ בֵּיהּ וְזִיהוּמְתֵּיהּ לָא נַפְקַת מִנֵיהּ גָלוּ עַל גָלוּ אִתַּפֵּק עַמָא מִדְלָא יִתְעֲבֵיר בָּהּ תִּיוּבָא:\",0,0],[4,144,24,7,\"אֲרֵי דַם זַכַּאי דְאִתְאַשַׁד בְּגַוָהּ בְּזֵידוּ וּבִדְרַע מְרוֹמָם שְׁפַכְתֵּיהּ לָא שְׁפַכְתֵּיהּ בְּשָׁלוּ לְמֶעְבַּד עֲלוֹהִי תְּיוּבָא:\",0,0],[4,144,24,8,\"לְמֶעְבַד פּוּרְעֲנּוּת לְאִתְפְּרָעָא בִתְקוֹף גַלֵיתִי חוֹבֵיהוֹן עַל דַאֲשִׁידוּ דַם זַכַּאי בִּגְלֵי בְּדִיל דְלָא לְאִישְׁתַּבָּקָא:\",0,0],[4,144,24,9,\"בְּכֵן כִדְנַן אֲמַר יְיָ אֱלֹהִים וַי עַל קַרְתָּא דְאֶשְׁדֵי דַם זַכַּאי בְּגַוָהּ אַף אֲנָא אַסְגֵי תְּבִירָהּ:\",0,0],[4,144,24,10,\"אַסְגֵי מַלְכַיָא כְּנִישׁ מַשִׁרְיָתָא טַקֵיס סוּמְכְוָתָא וְזַמִין עֲלָהּ עָבְדֵי קְרָבָא וְגִבָּרָהָא יִשְׁתַּבְּשׁוּן:\",0,0],[4,144,24,11,\"וְאַשְׁאַר אַרְעָא צַדְיָא בְּדִיל דְיִצְדוּן וִיסוּפוּן תַּרְעֵי קִרְוָהָא וְיִתְמְסוּן בְּגַוָהּ עָבְדֵי סְאוֹבְתָּהּ וִיסוּפוּן חוֹבָהָא:\",0,0],[4,144,24,12,\"תִּסְקוֹפִין אִיתְמְלִיאַת וְלָא יִפְקוּן מִנָהּ עָבְדֵי בִישְׁתָּא בְּנוּרָא תִתּוֹקַד מִסַגִיוּת חוֹבָהָא:\",0,0],[4,144,24,13,\"בִּדְאִסְתְּאַבְתְּ בַּעֲצַת חֶטְאִין חֲלַף דְדַכֵּיתִיךְ וְלָא דְכֵית מִסוֹאַבְתִּיךְ לָא תִדְכִּין עוֹד עַד דַאֲנִיחַ חֵמְתִי בִיךְ:\",0,0],[4,144,24,14,\"אֲנָא יְיָ גְזַרֵית בְּמֵימְרִי אֶתְיָא וְתִתְקַיֵם לָא אֶמְנַע וְלָא אֲחוּס וְלָא אֶרְחַם כְּאוֹרְחָתַיִךְ בִּישְׁתָא וּכְעוֹבָדַיִךְ מְקַלְקְלַיָא אִתְפְּרַע מִנִיךְ אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,24,15,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,24,16,\"בַּר אָדָם הָא אֲנָא נָסֵיב מִנָךְ יַת רִגְגָא דְעֵינָךְ בְּמוֹתָא וְלָא תִסְפַּד וְלָא תִבְכֵּי וְלָא תְשַׁגַר דִמְעִין:\",0,0],[4,144,24,17,\"אִידְנַק שְׁתוֹק עַל מֵיתָךְ אֶבְלָא לָא תַעְבֵּיד טוֹטְפָתָךְ יֶהֱוְיָן עֲלָךְ וּמְסַנֵךְ תְּשַׁוֵי בְרִגְלָךְ וְלָא תִתְעַטֵיף עַל שָׂפָם וּלְחֵים אֶבְלִין לָא תֵיכוּל:\",0,0],[4,144,24,18,\"וְאִתְנַבֵּיתִי לְעַמָא בְּצַפְרָא וּמִיתַת אִתְּתִי בְּרַמְשָׁא וַעֲבָדֵית בְּצַפְרָא כְמָא דְאִתְפַּקֵדִית:\",0,0],[4,144,24,19,\"וַאֲמָרוּ לִי עַמָא הֲלָא תְחַוֵי לָנָא מָא אִילֵן לָנָא אֲרֵי אַתְּ עָבֵיד:\",0,0],[4,144,24,20,\"וַאֲמָרֵית לְהוֹן פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ הֲוָה עִמִי לְמֵימָר:\",0,0],[4,144,24,21,\"אֲמַר לְבֵית יִשְׂרָאֵל כִּדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא מַפִיס יַת בֵּית מִקְדָשִׁי יְקָר תּוּקְפְכוֹן רִגְנָא דְעֵינֵיכוֹן וְחִבּוּב נַפְשְׁכוֹן וּבְנֵיכוֹן וּבְנָתֵיכוֹן דִשְׁבַקְתּוּן בְּחַרְבָּא יִתְקַטְלוּן:\",0,0],[4,144,24,22,\"וְתַעְבְּדוּן כְּמָא דַעֲבָדֵית עַל שָׂפָם לָא תִתְעַטְפוּן וּלְחֵים אֶבְלִין לָא תֵיכְלוּן:\",0,0],[4,144,24,23,\"וְטוֹטְפָתְכוֹן בְּרֵישֵׁיכוֹן וּמַסְגֵיכוֹן בְּרִגְלֵיכוֹן לָא תִסְפְּדוּן וְלָא תִבְכּוּן וְתִתְמְסוּן בְּחוֹבֵיכוֹן וְתִתְנַהֲמוּן גְבַר לַאֲחוֹהִי:\",0,0],[4,144,24,24,\"וִיהֵי יְחֶזְקֵאל לְכוֹן לְאָת כְּכֹל דִי עֲבַד תַּעְבְּדוּן בְּמֵיתָהּ וְתֵידְעוּן אֲרֵי אֲנָא יְיָ אֱלֹהִים:\",0,0],[4,144,24,25,\"וְאַתְּ בַּר אָדָם הֲלָא בְּיוֹמָא דְאַעֲדִי מִנְהוֹן יַת בֵּית מִקְדָשֵׁיהוֹן יְקַר תּוּקְפֵהוֹן חֶדְוַת תּוּשְׁבַּחְתְּהוֹן יִתְנְסִיב מִנְהוֹן רִגְגָא דְעֵינֵיהוֹן וְחַבּוּב נַפְשְׁהוֹן דְטַב לְהוֹן מִבְּנֵיהוֹן וּמִבְנָתֵיהוֹן:\",0,0],[4,144,24,26,\"בְּיוֹמָא הַהוּא יֵיתֵי מְשֵׁיזְבָא לְוָתָךְ לְאַשְׁמְעוּתָךְ בְּסוֹרָא:\",0,0],[4,144,24,27,\"בְּיוֹמָא הַהוּא יִתְפְּתַח פּוּמָךְ בְּמֵיתֵי מְשֵׁיזְבָא וְתִתְנַבֵּי וְלָא תִשְׁתּוֹק עוֹד וּתְהֵי לְהוֹן לְאָת וְתֵידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,25,1,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,25,2,\"בַּר אָדָם קַבֵּיל נְבוּאָה עַל בְּנֵי עַמוֹן וְתִתְנַבֵּי עֲלֵיהוֹן:\",0,0],[4,144,25,3,\"וְתֵימַר לִבְנֵי עַמוֹן קַבִּילוּ פִּתְגָמָא דַייָ אֱלֹהִים כִּדְנַן אֲמַר יְיָ אֱלֹהִים חֲלַף דַאֲמַרְתָּא חֶדְוָא עַל מַקְדְשִׁי אֲרֵי אִתְחַל וְעַל אַרְעָא דְיִשְׂרָאֵל אֲרֵי צְדִיאַת וְעַל דְבֵית יְהוּדָה אֲרֵי הַלִיכוּ בְגָלוּתָא:\",0,0],[4,144,25,4,\"בְּכֵן הָא אֲנָא מְסַר לִיךְ לִבְנֵי מַדִינְחָא לִירוּתָא וְיִתְבוּן בִּרְנְיָתֵיהוֹן בִּיךְ מַשְׁכְּנֵיהוֹן אִינוּן יֵיכְלוּן טוּב אַרְעִיךְ וְאִינוּן יִבְזוּן נִכְסָךְ:\",0,0],[4,144,25,5,\"וְאֶתֵּן יַת רַבָּה לִמְדוֹר גַמְלִין וְיַת בְּנֵי עַמוֹן לְבֵית מַשְׁרֵי עֶדְרִין דְעָן וְתֵידְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,25,6,\"אֲרֵי כִדְנַן אֲמַר יְיָ אֱלֹהִים חֲלַף דִטְפַחְתָּא בִידָךְ וּרְפַסְתָּא בְרִגְלָךְ וַחֲדִיתָא בְּכָל צִפּוּחַ נְפַשׁ עַל אַרְעָא דְיִשְׂרָאֵל:\",0,0],[4,144,25,7,\"בְּכֵן הָא אֲנָא מְרִים יַת מְחַת גְבוּרְתִּי עֲלָךְ וְאֶתְּנִנָךְ לְבִיז לְעַמְמַיָא וְאֱשֵׁיצִינָךְ מִבֵּינֵי עַמְמַיָא וְאַבְּדִנָךְ מִן מְדִינָתָא אַצְדִנָךְ וְתֵידַע אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,25,8,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים חֲלַף דַאֲמַרוּ מוֹאֲבָאֵי וְשֵׂעִיר מַה שְׁנוֹ מִכָּל עַמְמַיָא דְבֵית יְהוּדָה:\",0,0],[4,144,25,9,\"בְּכֵן הָא אֲנָא תָבַר יַת תְּקוֹף מוֹאָב מִקִרְוֵיהוֹן מִכְּרַכֵּיהוֹן עַד פַּצִיחֵיהוֹן חֶדְוַת אַרְעֲהוֹן בֵּית יְשִׁימוֹת בַּעַל מְעוֹן וְקִרְיָתָיִם:\",0,0],[4,144,25,10,\"לִבְנֵי קֶדֶם עַל בְּנֵי עַמוֹן וְאֶמְסְרִינָהּ לִירוּתָא בְּדִיל דְלָא יְהֵי דָכְרָי בְּנֵי עַמוֹן בְּעַמְמַיָא:\",0,0],[4,144,25,11,\"וּבְמוֹאָב אַעְבֵּיד פּוּרְעֲנוּת דִינִין וְיֵדְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,25,12,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים חֲלַף דַעֲבַדוּ אֱדוֹמָאֵי בִּתְקוֹף פּוּרְעֲנוּת לְבֵית יְהוּדָה וְחָבוּ חוֹבָא וְאִתְפְּרָעוּ מִנְהוֹן:\",0,0],[4,144,25,13,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים וַאֲרֵים מְחַת גְבוּרְתִּי עַל אֱדוֹם וֶאֱשֵׁיצֵי מִנָהּ אֱנָשָׁא וּבְעִירָא וְאֶתְּנִינָהּ חוּרְבָא מִדָרוֹמָא וְיַתְבֵי דְדָן בְּחַרְבָּא יִתְקַטְלוּן:\",0,0],[4,144,25,14,\"וְאֶתֵּן יַת פּוּרְעֲנוּתִי בֶּאֱדוֹם בְּיַד עַמִי יִשְׂרָאֵל וְיִתְמַסְרוּן וְיִתְפְּרָעוּן מִן אֱדוֹם כְּרוּגְזִי וּכְחֵימְתִי וְיֵדְעוּן יַת פּוּרְעֲנוּתִי אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,25,15,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים חֲלַף דַעֲבָדוּ פְּלִשְׁתָּאֵי בִּדְבָבוּ וְיִתְפְּרָעוּן פּוּרְעֲנוּת בְּצִפּוּחַ נְפַשׁ בְּדִיל לְחַבְּלָא דְבָבוּת עֲלָם:\",0,0],[4,144,25,16,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא מְרִים יַת מְחַת גְבוּרְתִּי עַל פְּלִשְׁתָּאֵי וֶאֱשֵׁיצֵי יַת עַמָא דְחַיָבִין לְאִשְׁתֵּיצָאָה וְאוֹבִיד יַת שְׁאַר סְפַר יַמָא:\",0,0],[4,144,25,17,\"וְאַעְבֵּיד בְּהוֹן פּוּרְעֲנוּן רַבְרְבָן בִּתְקוֹף רְגָז וְיֵדְעוּן אֲרֵי אֲנָא יְיָ בִּדְאֶתֵּן יַת פּוּרְעֲנוּתִי בְּהוֹן:\",0,0],[4,144,26,1,\"וַהֲוָה בַּחֲדָא עַסְרֵי שְׁנִין בְּחַד לְיַרְחָא הֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,26,2,\"בַּר אָדָם חֲלַף דַאֲמָרֵית צוֹר עַל יְרוּשְׁלֵם חֶדְוָא אִתְבְּרַת דַהֲוָה מְסַפְּקָא סְחוֹרָה לְכָל עַמְמַיָא אִסְתְּחָרַת לְמֵיתֵי לְוָתִי דַהֲוַת מַלְיָא חֲרוּבָת:\",0,0],[4,144,26,3,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא שָׁלַח רוּגְזִי עֲלָךְ צוֹר וְאֶסַק עֲלָךְ מַשִׁרְיַת עַמְמִין סַגִיאִין כְּמֵיסַק יַמָא בְּאִתְרְגוּשַׁת גַלוֹהִי:\",0,0],[4,144,26,4,\"וִיחַבְּלוּן שׁוּרֵי צוֹר וִיפַגְרוּן מִגְדְלָהָא וְאַעְקַר עֲפְרָהּ מִנָהּ וְאֶתֵּן יָתָהּ לִשְׁעִיעוֹת כֵּיף גְלֵי:\",0,0],[4,144,26,5,\"מִשְׁטַח צַיָדִין תְּהֵי בְּגוֹ יַמָא אֲרֵי אֲנָא גְזָרֵית בְּמֵימְרִי אֲמַר יְיָ אֱלֹהִים וּתְהֵי לְבִזָא לְעַמְמַיָא:\",0,0],[4,144,26,6,\"וְיַתְבֵי כַּפְרָנָהָא דִי בְּחַקְלָא בְּחַרְבָּא יִתְקַטְלוּן וְיֵדְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,26,7,\"אֲרֵי כִדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא מַיְתִי עַל צוֹר נְבוּכַדְרֶאצַר מַלְכָּא דְבָבֶל מִצִפּוּנָא מְלַךְ מַלְכַיָא בְּסוּסְוָן וּבִרְתִיכִין וּבְפָרָשִׁין וּמַשִׁרְיָן וְעַם סַגִי:\",0,0],[4,144,26,8,\"יַתְבֵי כַפְרָנָךְ דִי בְחַקְלָא בְּחַרְבָּא יִקְטֵיל וְיִבְנֵי עֲלָךְ כַּרְקוֹם וְיִצְבוֹר עֲלָךְ מִלֵיתָא וְיָקִים עֲלָךְ דִי מְזַיְנִין בִּתְרֵסִין:\",0,0],[4,144,26,9,\"וּמְחַת פָּגוֹזוֹהִי יֵהַב בְּשׁוּרָךְ וּמִגְדְלָךְ יְתָרַע בְּאַבְנֵי בַרְזְלֵיהּ:\",0,0],[4,144,26,10,\"מֵרִפְסַת סוּסְוָתֵיהּ יַחֲפִינָךְ אַבְקֵיהוֹן מִקַל פָּרָשִׁין וְגַלְגְלִין וּרְתִיכִין יְזוּעוּן שׁוּרָךְ בְּמֵיעֲלוֹהִי בְּתַרְעָךְ כְּמָא דְעָלִין בְּקַרְתָּא דִמְתַּרְעָא מִשׁוּר:\",0,0],[4,144,26,11,\"בְּפַרְסַת סוּסְוָתֵיהּ יְרוּשׁ יַת כָּל שׁוּקָךְ עַמִיךְ בְּחַרְבָּא יִקְטֵיל וְקָמַת תּוּקְפִיךְ לְאַרְעָא יְמַגֵר:\",0,0],[4,144,26,12,\"וְיִבְזוּן נִכְסָךְ וְיִשְׁבּוּן סְחוֹרְתִּיךְ וִיפַגְרוּן שׁוּרָךְ וּבָתֵּי חֶמְדָתֵךְ יִתְרְעוּן וַאֲבָנֵיךְ וְאָעָךְ וְעַפְרָךְ בְּגוֹ יַמָא יְשַׁווּן:\",0,0],[4,144,26,13,\"וַאֲבַטֵיל אִתְרְגוּשַׁת זְמִרָיִךְ וְקַל נָגוּן כִּנְרַיִךְ לָא יִשְׁתְּמַע עוֹד:\",0,0],[4,144,26,14,\"וְאֶתְּנִינָךְ לִשְׁעִיעוּת כֵּיף גְלֵי מִשְׁטַח צַיָדִין תְּהֵי לָא תִתְבְּנֵי עוֹד אֲרֵי אֲנָא יְיָ גְזָרֵית בְּמֵימְרִי אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,26,15,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים לְצוֹר הֲלָא מִקַל מַפְּלַת קְטִילָךְ בְּנִיהוּם מְטַעֲנֵי חֶרֶב כַּד יִתְרְמוּן קְטִילִין בְּגַוִיךְ יְזוּעוּן פַּרְוְרַיָא:\",0,0],[4,144,26,16,\"וְיֶחֱתוּן מֵעַל כּוּרְסְוָתֵיהוֹן כָּל רַבְרְבֵי יַמָא וְיַעְדוּן יַת מְעִילֵיהוֹן וְיַת לְבוּשֵׁי צִיוּרֵיהוֹן יַשְׁלְחוּן זְיַע יִלְבְּשׁוּן עַל אַרְעָא יַתְבוּן וִיזוּעוּן מִן קֳדָם תְּבִירֵיהוֹן וְיִצְדוּן עֲלָךְ:\",0,0],[4,144,26,17,\"וְיִטְלוּן עֲלָךְ אִלְיָא וְיֵימְרוּן לָךְ אֵיכְדֵין אַבַדְתְּ דַהֲוֵית יָתְבָא בְּגוֹ יַמַיָא קַרְתָּא מִשֻׁבַּחְתָּא דַהֲוֵית יָתָבָא בִּתְקוֹף יַמָא הִיא וְיָתְבָהָא אִיכְדֵין אִתְמַסְרוּ לִתְבַר כָּל יָתְבָהָא:\",0,0],[4,144,26,18,\"כְּעַן יְזוּעוּן פַּרְוְרַיָא בְּיוֹם מַפְּלַת קְטִילָךְ וְיִתְבָּהֲלוּן נַגְוָתָא דִי בְיַמָא בְּמִפַּק גָלוּתִיךְ:\",0,0],[4,144,26,19,\"אֲרֵי כִּדְנַן אֲמַר יְיָ אֱלֹהִים כַּד אֶתֵּן יָתִיךְ קִרְיָא חֶרְבָא כְּקִרְוִין דְלָא אִתּוֹתַבָא בְּאַסָקוּתִי עֲלָךְ מְשִׁרְיַת עַמְמִין דְסַגִיאִין כְּמֵי תְהוֹמָא וְיַחֲפוּנָךְ עַמְמִין סַגִיאִין:\",0,0],[4,144,26,20,\"וְאַחֲתִנִיךְ עִם נָחֲתֵי נוֹב בֵּית אַבְדָנָא לְוַת עַמָא דִמְעַלְמָא וְאַצְדִנִיךְ בְּאַרְעָא אַרְעִיתָא בְּחֶרְבָתָא דִמְעַלְמָא עִם נַחֲתֵי גוֹב בֵּית אָבְדָנָא בְּדִיל דְלָא תִּתְיַתְבִין וְאֶתֵּן חֶדְוָא בְּאַרְעָא דְיִשְׂרָאֵל:\",0,0],[4,144,26,21,\"כִּדְלָא הֲוֵית אֶתְּנִנָךְ וְכֵן תְּהֵי וְתִתְבְּעִין וְלָא תִשְׁכְּחִין עוֹד לַעֲלָם אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,27,1,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,27,2,\"וְאַתְּ בַּר אָדָם טוֹל עַל צוֹר אִלְיָא:\",0,0],[4,144,27,3,\"וְתֵימַר לְצוֹר דְיַתְבָא עַל מִגְרַשׁ מָחוֹזֵי יַמָא מְסַפְּקָא סְחוֹרָא לְעַמְמַיָא לְנַגְוָן סַגִיאִין כִּדְנַן אֲמַר יְיָ אֱלֹהִים צוֹר אַתְּ אֲמַרְתְּ אֲנָא מְשַׁכְלְלָא בְּשׁוּפְרִי:\",0,0],[4,144,27,4,\"בְּגוֹ יֵמַיָא תְּחוּמַיִךְ אַרְדִיכְלַיִךְ שַׁכְלִילוּ בִּנְיָנַיִךְ:\",0,0],[4,144,27,5,\"בִּירְוָן מִשְׂנִיר בְּנוֹ לִיךְ יַת כָּל נִשְׁרֵךְ אַרְזִין מִלִבְנָן נְסִיבוּ לְמֶעְבַּד תּוֹרְנִין עֲלָךְ:\",0,0],[4,144,27,6,\"בְּלוּטִין מִמַתְנָן עֲבַדוּ מְשׁוֹטֵי סְפִינָךְ תְּרוֹמֵי תַרְעָךְ דַפִּין דְאֶשְׁכְּרוֹעִין מְכַבְשִׁין בְּשֵׁן דְפִיל בֵּית חוֹפָאָה לְאִתְיָטְרוּן מִמְדִינַת אַפּוּלְיָא:\",0,0],[4,144,27,7,\"בּוּץ וְצִיוּרִין מִמְצְרַיִם הֲוָה פְּרָסִיךְ לְמֶהֱוֵי לִיךְ לְאָת תִּכְלָא וְאַרְגְוָנָא מִמְדִינַת אִיטַלְיָא הֲוַת כְּסוּתִיךְ:\",0,0],[4,144,27,8,\"יַתְבֵי צִידוֹן וְאַרְוַד הֲווֹ שַׁיְטִין וּמַיְתָן סְחוֹרָא לְגַוִיךְ חַכִּימַיִךְ צוֹר הֲווֹ בִיךְ אִינוּן פַּרְנָסֵיךְ:\",0,0],[4,144,27,9,\"סָבֵי גְבַל וְחַכִּימָהָא הֲווֹ בִיךְ מַתְקְפֵי צוֹרְבִיךְ כָּל נַחֲתֵי יַמָא וְסַפָנֵיהוֹן הֲווֹ שָׁיְטִין וְמַיְתָן סְחוֹרָא לְגַוִיךְ:\",0,0],[4,144,27,10,\"פַּרְסָאֵי וְלוּדָאֵי וּפוּטְאֵי הֲווֹ בְמַשְׁרִיתֵיךְ גַבְרֵי עָבְדֵי קְרָבִיךְ עֲגִילִין וְקוּלְסִין תְּלוֹ בִּיךְ אִינוּן אַסְגִיאוּ זִיוֵיךְ:\",0,0],[4,144,27,11,\"בְּנֵי אַרְוַד וְכָל מַשִׁרְיָתִיךְ עַל שׁוּרָךְ סְחוֹר סְחוֹר וְאַף קַפּוּטְקָאֵי בְּמִגְדָלֵיךְ הֲווֹ שִׁלְטֵיהוֹן תְּלוֹ עַל שׁוּרֵךְ סְחוֹר סְחוֹר אִינוּן שַׁכְלִילוּ שׁוּפְּרִיךְ:\",0,0],[4,144,27,12,\"מִן יַמָא מַיְתָן סְחוֹרָא לְגַוִיךְ מִסְגֵי כָּל עוֹתַר בִּכְסַף בַּרְזֶל עֲבַץ וַאֲבַד יְהָבוּ בְּבֵית גִנְזַיִךְ:\",0,0],[4,144,27,13,\"יָוָן תּוּבָל וּמֶשֶׁךְ אִינוּן תַּגָרֵיךְ בְּנַפְשָׁא דֶאֱנָשָׁא וּמַנֵי נְחָשָׁא מַיְתָן סְחוֹרָא לְגַוִיךְ:\",0,0],[4,144,27,14,\"מִמְדִינַת גַרְמַמְיָא סוּסְוָן וּפָרָשִׁין וְכוּדְנְוָן מַיְתָן סְחוֹרָא לְגַוִיךְ:\",0,0],[4,144,27,15,\"בְּנֵי דְדָן תַּגְרָךְ יַתְבֵי נַגְוָן סַגִיאָן מַיְתָן סְחוֹרָא לְגַוִיךְ בְּקַרְנִין דְיָעְלִין וְשֵׁן דְפִיל וְטַוְסִין אֲתִיבוּ קוּרְבָּנִיךְ:\",0,0],[4,144,27,16,\"מִן אֲרָם מַיְתָן סְחוֹרָא לְגַוִיךְ מִסָגִי עוּתְרִיךְ בִּתַכְרִיכִין דְאַרְגְוָן וּרְקָם וּבוּץ צִיוּרִין וְאַבְנִין טָבִין וּמַרְגָלִין יְהָבוּ בְּבֵית גִנְזָיִךְ:\",0,0],[4,144,27,17,\"יְהוּדָה וְאַרְעָא דְיִשְׂרָאֵל אִינוּן תַּגָרֵיךְ בְּהִטֵי רִיחוּשׁ וְקוֹלְיָא וּדְבַשׁ וּמְשַׁח וּשְׁעֵיף יְהָבוּ בַּחֲנּוּתָיִךְ:\",0,0],[4,144,27,18,\"מִן דַמֶשֶׂק מַיְתָן סְחוֹרָה לְגַוִיךְ בִּסְגֵי עוֹתְרִין מִסְגֵי כָּל עוֹתַר בַּחֲמַר חֵילַת מְבַשֵׁל וַעֲמַר מֵילַת כְּבֵינָא:\",0,0],[4,144,27,19,\"וְדָן וְיָוָן בְּשִׁירִין סְחוֹרְתִּיךְ מַיְתָן בְּעַרְקִין דְבַרְזֶל קִדָה וּקְנֵה בֹּשֶׁם בַּחֲנוּתַיִךְ יְהָבוּ:\",0,0],[4,144,27,20,\"מִן דְדָן מַיְתַן סְחוֹרָא לְגַוִיךְ בִּלְבוּשׁ דִיקָר לִרְתִיכִין:\",0,0],[4,144,27,21,\"עֲרַב וְכָל רַבְרְבֵי נְבָט אִינוּן תַּגָרֵיךְ בְּתוֹרִין וְדִכְרִין וְגַדְיָן בְּהוֹן הֲוַת סְחוֹרְתִּיךְ:\",0,0],[4,144,27,22,\"תַּגָרֵי שְׁבָא וְרַעֲמָה אִינוּן תַּגָרַיִךְ בְּרֵישׁ כָּל בּוּסְמִין וּבְכָל אַבְנִין טָבָן וְדַהֲבָא יְהָבוּ בְּבֵית גִנְזָיִךְ:\",0,0],[4,144,27,23,\"חַרְוָן וּנְצִיבִין וְהַדְיֵב תַּגְרֵי שְׁבָא מְדִינַן אַתּוּר וּמָדַי אִינוּן תַּגָרֵיךְ:\",0,0],[4,144,27,24,\"אִינוּן תַּגָרֵיךְ בִּגְמַר מִינֵי כָּל תּוּשְׁבַּחְתָא בְגוֹזְזִין דְתִכְלָא וְכוּשְׁפִין דְאַרְזָא בְּאִימְלִין דִי זָהְרָיִתָא דְמָחֲתִין בְּקוֹמְטְרִין חֲפַן גִלְדִין מְאַסְרִין בְּאַטוּנִין דִי בוּצָא חֲתִימִין בְּעִזְקַת גְלַף עֱבִידַת יַמָא מָחֲתִין בְּמִגְדָלֵי אָעֵי הֲדַסִין בְּהוֹן הֲוַת סְחוֹרְתִּיךְ:\",0,0],[4,144,27,25,\"בִּסְפִינֵי יַמָא הֲווֹ שַׁיְטִין וּמַיְתָן סְחוֹרָא לְגַוִיךְ וַעֲתַרְתְּ וּתְקֵיפְתְּ לַחֲדָא בְּגוֹ יַמַיָא:\",0,0],[4,144,27,26,\"בְּמַיִין סַגִיאִין עָלוּ עֲלָךְ וּבָזוּ יָתִיךְ מֶלֶךְ דְתַקִיף כְּרוּחַ קִדוּמָא תַּבְרִיךְ בְּגוֹ יַמַיָא:\",0,0],[4,144,27,27,\"עוֹתְרִיךְ וְנִכְסַיִךְ סְחוֹרְתִּיךְ סַפָּנַיִךְ וּפַרְנָסָיִךְ מַתְקְפֵי צוֹרְכִיךְ וּמַיְתָן סְחוֹרַת חֶנְוָתַיִךְ וְכָל גַבְרֵי עָבְדֵי קְרָבִיךְ דִי בִיךְ וְכָל מַשִׁרְיָתִיךְ דִי בְגַוִיךְ יִתְרְמוּן בְּגוֹ יַמַיָא בְּיוֹם מַפְּלַת קְטִילַיִךְ:\",0,0],[4,144,27,28,\"לְקַל צַוְחַת פַּרְנָסַיִךְ יְזוּעוּן פַּרְוָרַיָא:\",0,0],[4,144,27,29,\"וְיִחֲתוּן מִסְפִינֵיהוֹן כָּל אָחֲדֵי מָשׁוֹט סַפָנִין כָּל פַּרְנָסֵי יַמָא עַל אַרְעָא יְקוּמוּן:\",0,0],[4,144,27,30,\"וְיִשְׁמְעוּן עֲלָךְ בְּקָלֵיהוֹן וְיִצְוָחוּן בְּמֶרֶר וְיַסְקִין עַפְרָא עַל רֵישֵׁיהוֹן בְּקִיטְמָא יְהוֹן חֲפִיפִין:\",0,0],[4,144,27,31,\"וְיִמְרְטוּן עֲלָךְ מְרַט וְיֵיסְרוּן סַקִין וְיִבְכּוּן עֲלָךְ בִּמְרִיר נְפַשׁ וְיַעְבְּדוּן מִסְפַּד מְרִיר:\",0,0],[4,144,27,32,\"וְיִטְלוּן עֲלָךְ בְּעִינוּיֵהוֹן אִילְיָא וְיֵלִילוּן עֲלָךְ מַן כְּצוֹר לֵית דְדָמֵי לָהּ בְּגוֹ יַמַיָא:\",0,0],[4,144,27,33,\"בְּמִפַּק סְחוֹרְתִּיךְ מִבֵּינֵי עַמְמַיָא שַׂבַעְתְּ עַמְמִין סַגִיאִין בִּסְגֵי עוֹתְרִיךְ וְנִכְסַיִךְ אַעַתַּרְתְּ מַלְכֵי אַרְעָא:\",0,0],[4,144,27,34,\"כְּעַן אִתְּבָרַת דַהֲוַת מְסַפְּקָא סְחוֹרָא לְעַמְמַיָא בְּעוֹמְקֵי יַמָא סְחוֹרְתִּיךְ וְכָל מַשִׁרְיָתִיךְ בְּגַוִיךְ נְפָלוּ:\",0,0],[4,144,27,35,\"כָּל יַתְבֵי נַגְוָתָא צְדִיאוּ עֲלָךְ וּמַלְכֵיהוֹן זָעוּ זִיעַ אִתְרְשִׁימוּ אַפֵּיהוֹן:\",0,0],[4,144,27,36,\"תַּגָרִין בְּעַמְמַיָא צְדִיאוּ עָלַיִךְ כִּדְלָא הֲוֵית אֶתְּנִינִיךְ וְכֵן תְּהֵין עַד עַלְמָא:\",0,0],[4,144,28,1,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,28,2,\"בַּר אָדָם אֱמַר לְמַלְכָּא דְצוֹר כִּדְנַן אֲמַר לִיבָּךְ וַאֲמַרְתְּ דַחֲלָא אֲנָא יְיָ אֱלֹהִים חֲלַף דְרָאֵים מוֹתַב תַּקִיפִין יְתִיבֵית בְּגוֹ יַמַיָא וְאַתְּ אֱנָשָׁא וְלֵית בָּךְ צְרוֹךְ וַחֲשַׁבְתָּא בְלִיבָּךְ דְאַתְּ דַחֲלָא:\",0,0],[4,144,28,3,\"הָא חַכִּים אַתְּ מִדָנִיאֵל וְכָל רָז לָא יִתְכַּסָא מִנָךְ:\",0,0],[4,144,28,4,\"בְּחוּכְמְתָךְ וּבְסִכְלְתָנוּתָךְ קְנִיתָא לָךְ נִכְסִין וּכְנִשְׁתָּא דַהֲבָא וְכַסְפָּא בְּאוֹצְרָךְ:\",0,0],[4,144,28,5,\"בִּסְגִי חוֹכְמְתָךְ וּבִסְחוֹרָתָךְ סַגִיאָה מַשִׁרְיָתָךְ וְרָאֵים לִבָּךְ בְמַשִׁרְיָתָךְ:\",0,0],[4,144,28,6,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים חֲלַף דַחֲשַׁבְתָּא בְּלִבָּךְ דְאַתְּ דַחֲלָא:\",0,0],[4,144,28,7,\"בְּכֵן הָא אֲנָא מַיְתֵי עֲלָךְ נוּכְרָאִין תַּקִיפֵי עַמְמַיָא וְיִשְׁלְפוּן סַיְפֵיהוֹן עַל תִּקוּן חוּכְמְתָךְ וִיחַבְּלוּן זִיו אֵימָתָךְ:\",0,0],[4,144,28,8,\"לְחַבָּלָא יַחְתוּנָךְ וּתְמוּת מְמַת מְטַעֲנֵי חַרְבָּא בְּגוֹ יַמַיָא:\",0,0],[4,144,28,9,\"הֲמֵימַר תֵּימַר דַחֲלָא אֲנָא קֳדָם דְקַטְלָךְ וְאַתְּ אֱנָשָׁא וְלֵית בָּךְ צְרוֹךְ בְּיַד מְחַבְּלָךְ:\",0,0],[4,144,28,10,\"מְמַת רַשִׁיעִין תְּמוּת בְּיַד נוּכְרָאִין אֲרֵי אֲנָא גְזַרֵית בְּמֵימְרִי אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,28,11,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,28,12,\"בַּר אָדָם טוֹל אִילְיָא עַל מַלְכָּא דְצוֹר וְתֵימַר לֵיהּ כִּדְנַן אֲמַר יְיָ אֱלֹהִים אַתְּ דָמֵי לְמָנָא דְצוּרְתָא דִי מְתַקֵן בְּחוּכְמְתָא וּמְשֻׁכְלַל בְּשׁוּפְרֵיהּ:\",0,0],[4,144,28,13,\"בִּסְגִי טָבְוָן וְתַפְנוּקִין אַתְּ מִתְפְּנַק כְּאִילוּ בְּעֵדֶן גִנְתָא דַייָ אַתְּ שָׁרַי כָּל עֻתְרָא גֵיוְתָא וִיקָרָא מִתְיַהַב לָךְ כָּל אַבְנִין טָבִין מְסַרְדָן עַל לְבוּשָׁךְ סַמְקָן יַרְקָן וְסִבְהֲלוֹם כְּרוּם יַמָא וּבוּרְלָא וּפַנְתֵּירִין שִׁבְזֵיז אִזְמַררְגְדִין וּבַרְקָן מְשַׁקְעִן בִּדְהַב כָּל אִלֵין עֲבִידַת תִּקוּנְךְ בְּכֵן רָאֵים לִבָּךְ בְּרַם לָא אִסְתַּכַּלְתְּ בְּפִגְרָךְ דְאִתְעֲבִיד חֲלָלִין וּנְקָבִין דְאִינוּן צוֹרְכָן דְלָא אֶפְשַׁר לָךְ דְתִתְקַיֵים בְּלָא בְּהוֹן מִיוֹמָא דְאִתְבְּרֵיתָא עִמָךְ מְתַקְנִין:\",0,0],[4,144,28,14,\"אַתְּ מְלַךְ מְרַבָּא לְמָלְכוּ וִיהֵבִית לָךְ רְבוּתָא וְאַתְּ עַל טוּר קוּדְשָׁא דַייָ בְּסַרְתָּא וּבְעַמָא קַדִישָׁא סְבַרְתָּא לְמִשְׁלַט:\",0,0],[4,144,28,15,\"שְׁלִים אַתְּ בְּאוֹרְחָךְ מִיוֹמָא דְאִתְבְּרֵיתָא עַד דְאִשְׁתַּכַּח שְׁקַר בִּיךְ:\",0,0],[4,144,28,16,\"בִּסְגִיאוּת סְחוֹרְתָּךְ אִתְמְלִיאוּ אוֹצְרָךְ חֲטוֹף וְחַבְתָּא וַאֲפִסִינָךְ עַל דִבְסַרְתָּ עַל טוּר קוּדְשָׁא דַייָ וְאַבְּדִינָךְ מַלְכָּא דְרַבְּתָנָא עַל דִי סְבַרְתָּא לְמִשְׁלַט בְּעַמָא קַדִישָׁא:\",0,0],[4,144,28,17,\"רָאֵים לִבָּךְ בְּתוּקְפָךְ אִתְחַבַּלְתָּ בְּחוּכְמְתָךְ עַל זִיו אֵימְתָךְ עַל אַרְעָא רְטַשְׁתָּךְ אַזְהָרָא לְמַלְכַיָא יְהַבְתִּיךְ לְאִסְתַכְּלָא בָךְ:\",0,0],[4,144,28,18,\"מִסְגֵי חוֹבָךְ בִּשְׁקַר סְחוֹרְתָּךְ אָפֵיסְתָּא מַקְדְשָׁךְ וְאַיְתֵי עַמְמַיָא דְתַקִיפִין כְּאֶשְׁתָּא מֵחוֹבֵי זְדוֹנָךְ אִינוּן יְשֵׁיצוּנָךְ וְאֶתְּנִינָךְ כִּקְטַם עַל אַרְעָא לְעֵינֵי כָּל חָזָךְ:\",0,0],[4,144,28,19,\"כָּל דְיָדְעָךְ בְּעַמְמַיָא צְדִיאוּ עֲלָךְ כִּדְלָא הֲוֵית אֶתְנִינָךְ וְכֵן תְּהֵי עַד עָלְמָא:\",0,0],[4,144,28,20,\"וַהֲוָה פִתְגָם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,28,21,\"בַּר אָדָם קַבֵּיל נְבוּאָה עַל צִידוֹן וְאִתְנַבֵּי עֲלָה:\",0,0],[4,144,28,22,\"וְתֵימַר כִּדְנָן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא שְׁלַח רוּגְזִי עֲלָךְ צִידוֹן וְאִתְיַקַר בְּנַיִיךְ וְיֵדְעוּן אֲרֵי אֲנָא יְיָ כַּד אַעְבֵּיד בִּיךְ פּוּרְעֲנוּת דִינִין וְאֶתְקַדֵשׁ בָּהּ:\",0,0],[4,144,28,23,\"וַאֲשַׁלַח בָּהּ מוֹתָא וּקְטָלָא בְשׁוּקָהָא כַּד יִתְרְמוּן קְטִילִין בְּגַוָהּ בְּאַיְתָיוּתִי עֲלָהּ דְקָטְלִין בְּחַרְבָּא מִסְחוֹר סְחוֹר וְיֵדְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,28,24,\"וְלָא יְהֵי עוֹד לְבֵית יִשְׂרָאֵל מְלַךְ מַבְאִישׁ וְשִׁלְטוֹן מָעֵיק מִכָּל סָחֳרָנֵיהוֹן דְבָזְזִין יַתְהוֹן וְיֵדְעוּן אֲרֵי אֲנָא יְיָ אֱלֹהִים:\",0,0],[4,144,28,25,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים כַּד אַכְנַשׁ יַת בֵּית יִשְׂרָאֵל מִבֵּינֵי עַמְמַיָא דְאִתְבַּדַרוּ לְתַמָן וְאִתְקַדֵשׁ בְּהוֹן לְעֵינֵי עַמְמַיָא וִיתוּבוּן עַל אַרְעֲהוֹן דִיהֲבִית לְעַבְדִי לְיַעֲקֹב:\",0,0],[4,144,28,26,\"וִיתוּבוּן עֲלָהּ לְרוֹחֲצָן וְיִבְנוּן בָּתִּין וְיִצְבוּן כַּרְמִין וְיֵתְבוּן לְרוֹחֲצָן כַּד אַעְבֵיד פּוּרְעֲנוּת דִינִין מִכֹּל דְבָּזְזִין יַתְהוֹן מִסָחְרָנֵיהוֹן וְיֵדְעוּן אֲרֵי אֲנָא יְיָ אֱלָהָהוֹן:\",0,0],[4,144,29,1,\"בְּשַׁתָּא עֲשִׂירְיֵתָא בַּעֲשִׂירָאָה בִּתְרֵי עֲסַר לְיַרְחָא הֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,29,2,\"בַּר אָדָם קַבֵּיל נְבוּאָה עַל פַּרְעֹה מַלְכָּא דְמִצְרָיִם וְאִתְנַבֵּי עֲלוֹהִי וְעַל מִצְרָאֵי כּוּלְהוֹן:\",0,0],[4,144,29,3,\"אִתְנַבֵּי וְתֵימַר כִּדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא שְׁלַח רוּגְזִי עֲלָךְ פַּרְעֹה מַלְכָּא דְמִצְרָיִם דְאַתְּ דָמֵי לְתַנִינָא רַבָּא דִי שָׁרֵי בְּגוֹ נַהַרְוָתֵיהּ דִי אֲמַר דִילִי מַלְכוּתָא וַאֲנָא כְבִישִׁית:\",0,0],[4,144,29,4,\"וְאֶתֵּן שִׁירִין בְּלִיסָתָךְ וְאֶקְטוֹל שִׁלְטוֹנֵי תוּקְפָךְ עִם גִבָּרָךְ וַאֲבַטְלִינָךְ מִמַלְכוּתָךְ וְיַת כָּל שִׁלְטוֹנֵי תוּקְפָךְ עִם גִבָּרָךְ יִתְקַטְלוּן:\",0,0],[4,144,29,5,\"וַאֲרַטְשִׁינָךְ לְמָדְבְּרָא יָתָךְ וְיַת כָּל שִׁלְטוֹנֵי תוּקְפָךְ עַל אַפַּי חַקְלָא תִּתְרְמֵי נְבֵילְתָּךְ לָא תִתְכְּנֵישׁ וְלָא תִתְקְבַר לְחַיַת אַרְעָא וּלְעוֹפָא דִשְׁמַיָא מְסַרְתָּךְ לְאִשְׁתֵּיצָאָה:\",0,0],[4,144,29,6,\"וְיֵדְעוּן כָּל יַתְבֵי מִצְרַיִם אֲרֵי אֲנָא יְיָ חֲלַף דַהֲווֹ סְמַךְ קַנְיָא רְעִיעָא לְבֵית יִשְׂרָאֵל:\",0,0],[4,144,29,7,\"בְּאִתְכְּנָיוּתְהוֹן בָּךְ בְּיַד מְלַךְ תַּקִיף תִּתְמְסַר וְיֵיבַד בֵּית רוֹחֲצָנֵיהוֹן וּבְאִיסְתְּמָכוּתְהוֹן עֲלָךְ תִּתְּבַר וְלָא תְהֵי לְהוֹן לְבֵית סוּמְכְוָן:\",0,0],[4,144,29,8,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא מַיְתֵי עֲלָךְ דְקַטְלִין בְּחַרְבָּא וֶאֱשֵׁיצֵי מִנָךְ אֱנָשָׁא וּבְעִירָא:\",0,0],[4,144,29,9,\"וּתְהֵי אַרְעָא דְמִצְרָיִם לְאִישְׁתְּמָמוּ וְחוּרְבָּא וְיֵדְעוּן אֲרֵי אֲנָא יְיָ חֲלַף דַאֲמַר מַלְכוּתָא דִילִי וַאֲנָא כַבְּשֵׁית:\",0,0],[4,144,29,10,\"בְּכֵן הָא אֲנָא שְׁלַח רוּגְזִי עֲלָךְ וְעַל מַלְכְּוָתָךְ וְאֶתֵּן יַת אַרְעָא דְמִצְרַיִם לְחוֹרֶב צָדוּ וּשְׁמָמוּ מִמִגְדַל סְוֵנָה וְעַד תְּחוּם כּוּשׁ:\",0,0],[4,144,29,11,\"לָא תֶעְבַּר בָּהּ רִגְלָא דִי אֱנָשָׁא וְרִגְלָא דִי בְעִירָא לָא תֶעְבַּר בָהּ וְלָא תִתְיַתֵּב אַרְבְּעִין שְׁנִין:\",0,0],[4,144,29,12,\"וְאֶתֵּן יַת אַרְעָא דְמִצְרַיִם לְצָדוּ בְּגוֹ מְדִינָן צַדְיָן וְקִרְוָהָא בְּגוֹ קִרְוִין דַהֲוָאָה חֶרְבָּן יֶהֶוְיָן לְצָדוּ אַרְבְּעִין שְׁנִין וְאַגְלֵי יַת מִצְרָאֵי לְבֵינֵי עַמְמַיָא וֶאֱבַדְרִינוּן בִּמְדִינָתָא:\",0,0],[4,144,29,13,\"אֲרֵי כִדְנַן אֲמַר יְיָ אֱלֹהִים מִסוֹף אַרְבְּעִין שְׁנִין אַכְנֵישׁ יַת מִצְרָאֵי מִבֵּינֵי עַמְמַיָא דְאִתְבַּדָרוּ לְתַמָן:\",0,0],[4,144,29,14,\"וְאֶתֵּיב יַת גָלוּת מִצְרַיִם וְאָתֵיב יַתְהוֹן לְאַרְעָא פַּתְרוֹס עַל אַרְעָא תּוֹתְבוּתְהוֹן וִיהוֹן תַּמָן מָלְכוּ חֲלָשָׁא:\",0,0],[4,144,29,15,\"מִן מַלְכְּוָתָא תְּהֵי חֲלָשָׁא וְלָא תִתְרַבְרֵב עוֹד עַל עַמְמַיָא וְאַזְעִירִינוּן בְּדִיל דְלָא יִפְלְחוּן בְּעַמְמַיָא:\",0,0],[4,144,29,16,\"וְלָא יְהוֹן עוֹד לְבֵית יִשְׂרָאֵל לְאִתְרַחָצָא עֲלֵיהוֹן לְאַדְכְּרָא חוֹבִין בְּאַפְנָיוּתְהוֹן בַּתְרֵיהוֹן וְיֵדְעוּן אֲרֵי אֲנָא יְיָ אֱלֹהִים:\",0,0],[4,144,29,17,\"וַהֲוָה בְּעַסְרִין וּשְׁבַע שְׁנִין בְּקַדְמָאָה בְּחַד לְיַרְחָא הֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,29,18,\"בַּר אָדָם נְבוּכַדְרֶאצַר מַלְכָּא דְבָבֶל אַפְלַח יַת מַשִׁרְיָתֵיהּ פּוּלְחַן רַב עַל כָּל סְעַר רֵישׁ נַתֵּר וְכָל כְתַף אִתְמְרַט וַאֲגָר לָא הֲוָה לֵיהּ וּלְמַשִׁרְיָתֵיהּ מִצוֹר עַל פּוּלְחָנָא דְאַפְלַח עֲלָהּ:\",0,0],[4,144,29,19,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא יָהֵיב לִנְבוּכַדְרֶאצַר מַלְכָּא דְבָבֶל יַת אַרְעָא דְמִצְרָיִם וְיִשְׁבֵּי אִתְרְגוּשְׁתָּהּ וְיִבּוֹז בִּזָהּ וְיַעְדֵי עֲדָאָהּ וּתְהֵי אֲגַר לְמַשִׁרְיָתֵיהּ:\",0,0],[4,144,29,20,\"אַגְרֵיהּ דְאַפְלַח בֵּיהּ יְהָבֵית לֵיהּ יַת אַרְעָא דְמִצְרָיִם דְחָבוּ קֳדָמָי לְאִתְפְּרַע מִנְהוֹן אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,29,21,\"בְּיוֹמָא הַהוּא אַיְתֵי פוּרְקַן לְבֵית יִשְׂרָאֵל וְלָךְ אֶתֵּן מִפְתַּח פּוּמָא בִּנְבוּאָה בֵינֵיהוֹן וְיֵדְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,30,1,\"וַהֲוָה פִּתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,30,2,\"בַּר אָדָם אִתְנַבֵּי וְתֵימַר כִּדְנַן אֲמַר יְיָ אֱלֹהִים אַיְלִילוּ וַאֲמָרוּ וַי מִן קֳדָם יוֹמָא:\",0,0],[4,144,30,3,\"אֲרֵי קָרִיב יוֹמָא וְקָרִיב יוֹמָא דַעֲתִיד לְמֵיתֵי מִן קֳדָם יְיָ יוֹם עַנַן זִיעַ תְּבַר עַמְמַיָא יְהֵי:\",0,0],[4,144,30,4,\"וְתָחוֹל חַרְבָּא בְּמִצְרַיִם וִיהֵי זִיעַ בְּכוּשׁ כַּד יִתְרְמוּן קְטִילִין בְּמִצְרַיִם וְיִשְׁבּוּן אִתְרְגוּשְׁתָּהּ וְיִתְפַּגְרוּן אוּשְׁוָתָהָא:\",0,0],[4,144,30,5,\"כּוּשָׁאֵי וּפוּטָאֵי וְלוּדָאֵי וְכָל סוּמְכָוָתָא וְכוּב וּבְנֵי אַרְעָא קְיָמָא עִמְהוֹן בְּחַרְבָּא יִתְקַטְלוּן:\",0,0],[4,144,30,6,\"כִּדְנַן אֲמַר יְיָ וְיִתְקַטְלוּן סַעֲדֵי מִצְרַיִם וְיִבַטֵל יְקַר תּוּקְפָהּ מִמִגְדוֹל סְוָנֵה בְּחַרְבָּא יִתְקַטְלוּן בָּהּ אֲמַר יְיָ אֱלֹהִים:\",0,0],[4,144,30,7,\"וְיִצְדוּן בְּגוֹ מְדִינָן דְצַדְיָן וְקִרְווֹהִי בְּגוֹ קִרְוֵין דַהֲוָאָה חָרְבָן יֶהֱוְיָן:\",0,0],[4,144,30,8,\"וְיֵדְעוּן אֲרֵי אֲנָא יְיָ בִּדְאֶתֵּן עַמְמַיָא דְתַקִיפִין כְּאֶשְׁתָּא עַל מִצְרַיִם וְיִתְּבְרוּן כָּל סְעִידָהָא:\",0,0],[4,144,30,9,\"בְּעִדָנָא הַהִיא יִפְקוּן אִזְגַדִין מִן קֳדָמַי בְּלִגְיוֹנִין לַאֲזָעָא כּוּשׁ דְשַׁרְיָא לְרוֹחֲצָן וִיהֵי זִיעָא בְּהוֹן כְּיוֹם מִצְרַיִם אֲרֵי הָא אַתְיָא:\",0,0],[4,144,30,10,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים וַאֲבַטֵיל יַת אִתְרְגוּשַׁת מִצְרַיִם בְּיַד נְבוּכַדְרֶאצַר מַלְכָּא דְבָבֶל:\",0,0],[4,144,30,11,\"הוּא וְעַמֵיהּ עִמֵיהּ תְּקִיפֵי עַמְמַיָא אֶתֵּן לְחַבָּלָא אַרְעָא וְיִשְׁלְפוּן סַיְפֵיהוֹן עַל מִצְרַיִם וְיִמְלוֹן יַת אַרְעָא קְטִילִין:\",0,0],[4,144,30,12,\"וְאֶתֵּן נַהֲרֵיהוֹן יַבֶּשְׁתָּא וְאֶמְסַר יַת אַרְעָא בְּיַד מַבְאֲשִׁין וְאַצְדֵי אַרְעָא וּמְלָהָא בְּיַד רְשִׁיעִין אֲנָא יְיָ גְזָרִית בְּמֵימְרִי:\",0,0],[4,144,30,13,\"כִּדְנַן אֲמַר יְיָ אֱלֹהִים וְאַבֵיד דְפָלְחִין לְטַעֲוָתָא וֶאֱשֵׁיצֵי דְפָלְחִין לְצַלְמָנַיָא מִמָפֵס וּמַלְכָּא מֵאַרְעָא דְמִצְרַיִם דַחֲלָא בְּמִצְרַיִם:\",0,0],[4,144,30,14,\"וְאַצְדֵי יַת פַּתְרוֹס וְאַיְתֵי עַמָא דְתַקִיפִין כְּאֶשְׁתָּא עַל טָאנֵיס וְאַעְבֵּיד פּוּרְעֲנוּת דִינִין בְּאַלַכְסַנְדַרְיָא:\",0,0],[4,144,30,15,\"וְאֶשְׁפּוֹךְ חֵימְתִי עַל סִין תְּקוֹף מִצְרַיִם וֶאֱשֵׁיצֵי יַת אִתְרְגוּשַׁת אֲלַכְסַנְדַרְיָא:\",0,0],[4,144,30,16,\"וְאַיְתֵי עַמְמַיָא דְתַקִיפִין כְּאֶשְׁתָּא בְּמִצְרַיִם מִזַע תְּזוּעַ סִין וַאֲלַכְסַנְדַרְיָא תְּהֵי מְתַרְעָא מִשׁוּר וּמָפֵיס בַּעֲלֵי דְבָבוּ יִקְפוּנָהּ יוֹם יוֹם:\",0,0],[4,144,30,17,\"עוּלֵימֵי אָוֶן וּפִיבֶסֶת בְּחַרְבָּא יִתְקַטְלוּן וּפָלְחֵיהוֹן בְּשִׁבְיָא יָהֲכוּן:\",0,0],[4,144,30,18,\"וְעַל תַּחְפַּנְחֵס אַיְתֵי חֲשׁוֹךְ בִּימָם כַּד אֶתְבַּר תַּמָן יַת תְּקוֹף מִצְרַיִם וִיבַטֵל בָּהּ יְקַר תּוּקְפָהּ מְלַךְ בְּמַשִׁרְיָתֵיהּ יַחְפִּינָהּ כַּעֲנָנָא דְסָלֵיק וְחָפֵי יַת אַרְעָא וְיַתְבֵי כַפְרָנָהָא בְּשִׁבְיָא יָהֲכוּן:\",0,0],[4,144,30,19,\"וְאַעְבֵּד פּוּרְעֲנוּת דִינִין בְּמִצְרַיִם וְיֵדְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,30,20,\"וַהֲוָה בַּחֲדָא עַשְׂרֵי שְׁנִין בְּקַדְמָאָה בְּשַׁבְעָא לְיַרְחָא הֲוָה פִתְגַם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,30,21,\"בַּר אָדָם יַת תְּקִיף פַּרְעֹה מַלְכָּא דְמִצְרַיִם תַּבְרֵית וְהָא לָא מִתַּקְפָא לְאִתַּסָאָה לְמִתַּן עֵיצָה לְמֶחְכַּם לְאִתַּקָפָא לְמֵיחַד מַלְכּוּ:\",0,0],[4,144,30,22,\"בְּכֵן כִּדְנַן אֲמַר יְיָ אֱלֹהִים הָא אֲנָא שְׁלַח רוּגְזִי עַל פַּרְעֹה מַלְכָּא דְמִצְרַיִם וְאֶתְּבַר יַת סַעֲדוֹהִי וְיַת שִׁלְטוֹנוֹהִי תַקִיפַיָא דִבְהוֹן הוּא תְבַר יַת מַלְכְּוָתָא וְאֶרְמֵי יַת תּוּקְפָא מִנֵיהּ:\",0,0],[4,144,30,23,\"וְאַגְלֵי יַת מִצְרָאֵי בֵּינֵי עַמְמַיָא וַאֲבַדְרִינוּן בִּמְדִינָתָא:\",0,0],[4,144,30,24,\"וְאַתְקֵיף יַת מַלְכוּת מַלְכָּא דְבָבֶל וְאֶתֵּן יַת תּוּקְפִי בִּידֵיהּ וְאֶתְּבַר יַת תְּקוֹף פַּרְעֹה וְיִנְהֵם נְהוֹם מְטַעֲנֵי חֶרֶב קֳדָמוֹהִי:\",0,0],[4,144,30,25,\"וְאַתְקֵיף יַת מַלְכוּת מַלְכָּא דְבָבֶל וּמַלְכוּת פַּרְעֹה תִּבְטֵל וְיֵדְעוּן אֲרֵי אֲנָא יְיָ כַּד אֶתֵּן תּוּקְפִי בְּיַד מַלְכָּא דְבָבֶל וְיִתְפְּרַע פּוּרְעֲנוּת מִן אַרְעָא דְמִצְרָיִם:\",0,0],[4,144,30,26,\"וְאַגְלֵי יַת מִצְרָאֵי לְבֵינֵי עַמְמַיָא וֶאֱבַדַר יַתְהוֹן בִּמְדִינָתָא וְיֵדְעוּן אֲרֵי אֲנָא יְיָ:\",0,0],[4,144,31,1,\"וַהֲוָה בַּחֲדָא עַסְרָא שְׁנִין בִּתְלִיתָאָה בְּחַד לְיַרְחָא הֲוָה פִּתְגָם נְבוּאָה מִן קֳדָם יְיָ עִמִי לְמֵימָר:\",0,0],[4,144,31,2,\"בַּר אָדָם אֲמַר לְפַרְעֹה מַלְכָּא דְמִצְרַיִם וּלְאִתְרְגוּשְׁתֵּהּ לְמָן דְמִיתָא בְּתוּקְפָךְ:\",0,0],[4,144,31,3,\"הָא אַתּוּרָאָה דַמְיָא לְאַרְזָא בְּלִבְנָן דְנוֹפֵיהּ שַׁפִּיר וְסוֹכֵיהּ מַטְלָן וְרָם בְקוֹמָה וְעַל נַגְדִין שָׁלַח שָׁרְשׁוֹהִי:\",0,0],[4,144,31,4,\"בְּעַמְמַיָא סַגִי בְּסוּמְכְוָתָא תַּקִיף יַת מַלְכַיָא שַׁעְבֵּיד לִתְחוֹת מַלְכוּתֵיהּ וְיַת שִׁלְטוֹנוֹהִי מָנֵי עַל כָּל מְדִינַת אַרְעָא:\",0,0],[4,144,31,5,\"עַל כֵּן רָאִים בְּתוּקְפֵיהּ מִכָּל מַלְכֵי אַרְעָא וּסְגִיאַת מַשִׁרְיָתֵיהּ וְאִתְנַצְחוּ סוּמְכְוָתֵיהּ עַל עַמְמִין סַגִיאִין בְּאִתְנַצְחוּתֵהּ:\",0,0],[4,144,31,6,\"בְּמַשִׁרְיָתֵיהּ כְּבֵישׁ כָּל כְּרַכִּין תַּקִיפִין וּתְחוֹת שִׁלְטוֹנוֹהִי שַׁעְבֵּיד כָּל מְד");
